PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE "__drizzle_migrations" (
			id SERIAL PRIMARY KEY,
			hash text NOT NULL,
			created_at numeric
		);
CREATE TABLE `attempt_answers` (
	`id` text PRIMARY KEY NOT NULL,
	`attempt_id` text NOT NULL,
	`question_id` text NOT NULL,
	`user_answer` text,
	`is_correct` integer,
	`time_taken_seconds` integer,
	FOREIGN KEY (`attempt_id`) REFERENCES `user_attempts`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`question_id`) REFERENCES `questions`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `content_blogs` (
	`id` text PRIMARY KEY NOT NULL,
	`slug` text NOT NULL,
	`title` text NOT NULL,
	`description` text,
	`content` text NOT NULL,
	`category` text NOT NULL,
	`image_url` text,
	`reading_time` integer,
	`is_published` integer DEFAULT false,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`updated_at` integer DEFAULT (strftime('%s', 'now'))
, `content_type` text DEFAULT 'blog' NOT NULL, `unit_id` text, `topic_id` text, `is_premium` integer DEFAULT true, `is_free_access` integer DEFAULT false, `is_lite_access` integer DEFAULT false, `is_pro_access` integer DEFAULT true, `is_hidden` integer DEFAULT false, `excerpt` text, "exam_type" text NOT NULL DEFAULT 'mppsc');
CREATE TABLE `feedbacks` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`name` text NOT NULL,
	`email` text,
	`phone` text,
	`message` text NOT NULL,
	`rating` integer NOT NULL,
	`category` text DEFAULT 'other',
	`created_at` integer DEFAULT (strftime('%s', 'now'))
, `role` text, `location` text, "exam_type" text NOT NULL DEFAULT 'mppsc');
CREATE TABLE free_quiz_attempts (
    id text PRIMARY KEY NOT NULL,
    "test_id" text NOT NULL REFERENCES tests(id) ON DELETE cascade ON UPDATE no action, `guest_id` text, `score` real, `total_questions` integer, `percentage` real, `time_taken_seconds` integer, `completed_at` integer DEFAULT (strftime('%s', 'now')), `exam_type` text DEFAULT 'mppsc' NOT NULL);
CREATE TABLE `guests` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`email` text,
	`mobile` text,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
, "updated_at" integer DEFAULT (strftime('%s', 'now')), `exam_type` text DEFAULT 'mppsc' NOT NULL, `lead_source` TEXT);
CREATE TABLE "intelligence_feedback" (
    "id" text PRIMARY KEY NOT NULL,
    "guest_id" text,
    "question_id" text NOT NULL,
    "test_id" text,
    "reaction" text NOT NULL,
    "message" text,
    "created_at" integer DEFAULT (strftime('%s', 'now')),
    "exam_type" text DEFAULT 'mppsc' NOT NULL, question_text TEXT, `is_pro` integer DEFAULT false, `source` text, `user_id` text, `user_name` text, `user_mobile` text, `user_email` text,
    FOREIGN KEY ("guest_id") REFERENCES "guests"("id") ON UPDATE no action ON DELETE no action
  );
CREATE TABLE `mains_content` (
	`id` text PRIMARY KEY NOT NULL,
	`topic_id` text,
	`concept_hi` text NOT NULL,
	`concept_en` text NOT NULL,
	`expert_strategy_hi` text,
	`expert_strategy_en` text,
	`model_answers` text NOT NULL,
	`updated_at` integer DEFAULT (strftime('%s', 'now')), `key_terms_hi` text, `key_terms_en` text, `practice_questions` text,
	FOREIGN KEY (`topic_id`) REFERENCES `mains_topics`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `mains_feedback` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`topic_id` text,
	`type` text NOT NULL,
	`message` text,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	FOREIGN KEY (`user_id`) REFERENCES `mppsc_mains_users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`topic_id`) REFERENCES `mains_topics`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `mains_papers` (
	`id` text PRIMARY KEY NOT NULL,
	`paper_number` integer NOT NULL,
	`title_hi` text NOT NULL,
	`title_en` text NOT NULL,
	`total_marks` integer NOT NULL,
	`duration_minutes` integer NOT NULL,
	`display_order` integer DEFAULT 0,
	`description` text
);
CREATE TABLE `mains_progress` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`topic_id` text,
	`status` text DEFAULT 'unseen',
	`last_reviewed_at` integer,
	FOREIGN KEY (`user_id`) REFERENCES `mppsc_mains_users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`topic_id`) REFERENCES `mains_topics`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `mains_topics` (
	`id` text PRIMARY KEY NOT NULL,
	`unit_id` text,
	`title_hi` text NOT NULL,
	`title_en` text NOT NULL,
	`display_order` integer DEFAULT 0,
	`status` text DEFAULT 'draft',
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	FOREIGN KEY (`unit_id`) REFERENCES `mains_units`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `mains_units` (
	`id` text PRIMARY KEY NOT NULL,
	`paper_id` text,
	`part` text DEFAULT 'NONE',
	`unit_number` integer NOT NULL,
	`title_hi` text NOT NULL,
	`title_en` text NOT NULL,
	`display_order` integer DEFAULT 0,
	FOREIGN KEY (`paper_id`) REFERENCES `mains_papers`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `mppolice_one_liner_facts` (
	`id` text PRIMARY KEY NOT NULL,
	`subject_tag` text NOT NULL,
	`stem_hi` text NOT NULL,
	`stem_en` text,
	`answer_hi` text NOT NULL,
	`answer_en` text,
	"importance_score" real,
	`sort_order` integer DEFAULT 0,
	`extended_data` text,
	`status` text DEFAULT 'draft',
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`updated_at` integer DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE `mppolice_one_liner_revisions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`fact_id` text NOT NULL,
	`revision_count` integer DEFAULT 0,
	`last_revised_at` integer DEFAULT (strftime('%s', 'now')),
	FOREIGN KEY (`user_id`) REFERENCES `mppsc_users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`fact_id`) REFERENCES `mppolice_one_liner_facts`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `mppsc_mains_users` (
	`id` text PRIMARY KEY NOT NULL,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`email` text NOT NULL,
	`password` text NOT NULL,
	`name` text,
	`phone` text,
	`is_subscribed` integer DEFAULT false,
	`plan_tier` text DEFAULT 'free',
	`access_expires_at` integer,
	`is_active` integer DEFAULT true,
	`metadata` text,
	`deleted_at` integer
);
CREATE TABLE `mppsc_user_activities` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`user_email` text NOT NULL,
	`user_name` text,
	`admin_id` text,
	`action` text NOT NULL,
	`details` text,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE `mppsc_users` (
	`id` text PRIMARY KEY NOT NULL,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`email` text NOT NULL,
	`password` text NOT NULL,
	`name` text,
	`is_subscribed` integer DEFAULT false
, `role` text DEFAULT 'guest', `plan_tier` text DEFAULT 'free', `admin_secret` text, `deleted_at` integer, `access_expires_at` integer, `phone` text, `metadata` text, `previous_user_id` text, `is_active` integer DEFAULT true, category TEXT DEFAULT 'UR', gender TEXT DEFAULT 'M', "exam_type" text NOT NULL DEFAULT 'mppsc');
CREATE TABLE `payment_exit_reasons` (
	`id` text PRIMARY KEY NOT NULL,
	`reason` text NOT NULL,
	`custom_reason` text,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
, exam_type TEXT DEFAULT 'mppsc' NOT NULL);
CREATE TABLE "payments" (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`order_id` text NOT NULL,
	`payment_id` text,
	`signature` text,
	`amount` integer NOT NULL,
	`plan_tier` text,
	`status` text DEFAULT 'created' NOT NULL,
	`currency` text DEFAULT 'INR' NOT NULL,
	`receipt` text,
	`notes` text,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`updated_at` integer DEFAULT (strftime('%s', 'now')), "exam_type" text NOT NULL DEFAULT 'mppsc',
	FOREIGN KEY (`user_id`) REFERENCES `mppsc_users`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE TABLE "pricing_config" (
	`exam_type` text PRIMARY KEY NOT NULL,
	`lite_price` integer DEFAULT 99,
	`lite_original_price` integer DEFAULT 299,
	`lite_validity_text` text DEFAULT 'Valid till Exam',
	`lite_months` integer DEFAULT 8,
	`pro_price` integer DEFAULT 299,
	`pro_original_price` integer DEFAULT 999,
	`pro_validity_text` text DEFAULT 'Valid for 1 Year',
	`pro_months` integer DEFAULT 12,
	`upgrade_price` integer DEFAULT 199,
	`upgrade_original_price` integer DEFAULT 299,
	`urgency_text` text DEFAULT 'Special Offer',
	`urgency_text_hi` text DEFAULT 'विशेष ऑफर',
	`students_bought` integer DEFAULT 23,
	`updated_at` integer DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE "pricing_config_old" (
	`exam_type` text PRIMARY KEY NOT NULL,
	`lite_price` integer DEFAULT 99,
	`lite_original_price` integer DEFAULT 299,
	`lite_validity_text` text DEFAULT 'Valid till Exam',
	`lite_months` integer DEFAULT 8,
	`pro_price` integer DEFAULT 299,
	`pro_original_price` integer DEFAULT 999,
	`pro_validity_text` text DEFAULT 'Valid for 1 Year',
	`pro_months` integer DEFAULT 12,
	`upgrade_price` integer DEFAULT 199,
	`upgrade_original_price` integer DEFAULT 299,
	`urgency_text` text DEFAULT 'Special Offer',
	`urgency_text_hi` text DEFAULT 'विशेष ऑफर',
	`students_bought` integer DEFAULT 23,
	`updated_at` integer DEFAULT (strftime('%s', 'now'))
);
CREATE TABLE pyq_content_import_jobs (
    id text PRIMARY KEY NOT NULL,
    uploaded_by text,
    input_hash text NOT NULL,
    total_records integer,
    success_count integer,
    failure_count integer,
    status text DEFAULT 'pending',
    error_report text,
    created_at integer DEFAULT (strftime('%s', 'now'))
  );
CREATE TABLE pyq_fact_bank (
    id text PRIMARY KEY NOT NULL,
    topic_id text NOT NULL,
    subject text NOT NULL,
    fact_text text NOT NULL,
    fact_text_en text,
    memory_tip text,
    memory_tip_en text,
    scam_alert text,
    scam_alert_en text,
    difficulty text DEFAULT 'medium',
    frequency_score real DEFAULT 0,
    importance_score real DEFAULT 0,
    pyq_refs text DEFAULT '[]' NOT NULL,
    tags text DEFAULT '[]',
    status text DEFAULT 'draft',
    source text DEFAULT 'manual',
    created_by text,
    created_at integer DEFAULT (strftime('%s', 'now')),
    updated_at integer DEFAULT (strftime('%s', 'now')),
    FOREIGN KEY (topic_id) REFERENCES pyq_topics(id) ON DELETE cascade
  );
CREATE TABLE pyq_question_topics (
    id text PRIMARY KEY NOT NULL,
    question_id text NOT NULL,
    topic_id text NOT NULL,
    confidence real DEFAULT 1,
    is_primary integer DEFAULT false,
    source text DEFAULT 'manual',
    created_at integer DEFAULT (strftime('%s', 'now')),
    FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE cascade,
    FOREIGN KEY (topic_id) REFERENCES pyq_topics(id) ON DELETE cascade
  );
CREATE TABLE pyq_repeated_cache (
      id text PRIMARY KEY NOT NULL,
      question_id text NOT NULL,
      cluster_id text NOT NULL,
      unit_id text,
      unit_title text,
      repeat_count integer DEFAULT 1 NOT NULL,
      years text NOT NULL,
      occurrences text NOT NULL,
      related_question_ids text NOT NULL,
      computed_at integer DEFAULT (strftime('%s', 'now')),
      FOREIGN KEY (question_id) REFERENCES questions(id) ON UPDATE no action ON DELETE cascade
    );
CREATE TABLE pyq_topic_trends (
    id text PRIMARY KEY NOT NULL,
    topic_id text NOT NULL,
    subject text NOT NULL,
    year integer NOT NULL,
    question_count integer DEFAULT 0 NOT NULL,
    weight_percent real DEFAULT 0 NOT NULL,
    trend_delta real DEFAULT 0,
    computed_at integer DEFAULT (strftime('%s', 'now')),
    FOREIGN KEY (topic_id) REFERENCES pyq_topics(id) ON DELETE cascade
  );
CREATE TABLE pyq_topics (
    id text PRIMARY KEY NOT NULL,
    subject text NOT NULL,
    topic_slug text NOT NULL,
    topic_title text NOT NULL,
    topic_title_en text,
    description text,
    is_active integer DEFAULT true,
    created_at integer DEFAULT (strftime('%s', 'now')),
    updated_at integer DEFAULT (strftime('%s', 'now'))
  , `ai_content` text);
CREATE TABLE pyq_unit_cache (
      id text PRIMARY KEY NOT NULL,
      year integer NOT NULL,
      unit_id text NOT NULL,
      unit_title text NOT NULL,
      question_count integer DEFAULT 0 NOT NULL,
      question_ids text NOT NULL,
      computed_at integer DEFAULT (strftime('%s', 'now'))
    );
CREATE TABLE `questions` (
	`id` text PRIMARY KEY NOT NULL,
	`test_id` text NOT NULL,
	`question_text` text NOT NULL,
	`options` text NOT NULL,
	`correct_answer` text NOT NULL,
	`explanation` text,
	`marks` integer NOT NULL,
	"negative_marks" real DEFAULT 1,
	`order` integer NOT NULL, `subject` text, `question_text_en` text, `explanation_en` text, `ideal_time` integer DEFAULT 60, `type` text DEFAULT 'standard', `match_pairs` text, `deleted_at` integer, extended_data text, "exam_type" text NOT NULL DEFAULT 'mppsc',
	FOREIGN KEY (`test_id`) REFERENCES `tests`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE VIRTUAL TABLE questions_fts USING fts5(
        id UNINDEXED, 
        testId UNINDEXED, 
        questionText, 
        tokenize='unicode61'
      );
CREATE TABLE `support_tickets` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`name` text NOT NULL,
	`email` text NOT NULL,
	`phone` text,
	`category` text DEFAULT 'general',
	`message` text NOT NULL,
	`status` text DEFAULT 'open',
	`created_at` integer DEFAULT (strftime('%s', 'now'))
, exam_type TEXT DEFAULT 'mppsc' NOT NULL);
CREATE TABLE `syllabus_topics` (
	`id` text PRIMARY KEY NOT NULL,
	`unit_id` text NOT NULL,
	`title` text NOT NULL,
	`title_en` text,
	`content` text NOT NULL,
	`content_en` text,
	`order` integer NOT NULL,
	`is_free` integer DEFAULT false,
	`img_url` text,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
, `ai_content` text, `ai_content_en` text, `is_lite_access` integer DEFAULT false, `is_pro_access` integer DEFAULT true, exam_type TEXT DEFAULT 'mppsc' NOT NULL);
CREATE TABLE `test_attempt_limits` (
	`test_type` text PRIMARY KEY NOT NULL,
	`max_attempts` integer
);
CREATE TABLE `test_feedback` (
	`id` text PRIMARY KEY NOT NULL,
	`test_id` text NOT NULL,
	`user_id` text,
	`test_type` text NOT NULL,
	`overall_rating` integer NOT NULL,
	`difficulty_level` text NOT NULL,
	`question_quality` text NOT NULL,
	`would_recommend` text NOT NULL,
	`comments` text,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`updated_at` integer DEFAULT (strftime('%s', 'now'))
, `user_name` text, `user_email` text, `test_name` text, `exam_type` text DEFAULT 'mppsc' NOT NULL);
CREATE TABLE `test_leaderboard` (
	`id` text PRIMARY KEY NOT NULL,
	`test_id` text NOT NULL,
	`user_id` text,
	`display_name` text NOT NULL,
	`score` real NOT NULL,
	`percentage` real,
	`time_taken_seconds` integer,
	`rank` integer,
	`is_fake` integer DEFAULT 0,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
, exam_type TEXT DEFAULT 'mppsc' NOT NULL);
CREATE TABLE `tests` (
	`id` text PRIMARY KEY NOT NULL,
	`title` text NOT NULL,
	`description` text,
	`slug` text NOT NULL,
	`duration_minutes` integer NOT NULL,
	`total_marks` integer NOT NULL,
	`type` text NOT NULL,
	`is_pro` integer DEFAULT false,
	`created_at` integer DEFAULT (strftime('%s', 'now')),
	`updated_at` integer DEFAULT (strftime('%s', 'now'))
, `unit_id` text, `tags` text, `max_retries` integer, `total_questions` integer DEFAULT 0, `topic_id` text, `display_order` integer DEFAULT 0, `deleted_at` integer, `title_en` text, `is_free_access` integer DEFAULT false, `is_lite_access` integer DEFAULT false, `is_pro_access` integer DEFAULT true, `is_hidden` integer DEFAULT false, cutoffs text, "exam_type" text NOT NULL DEFAULT 'mppsc');
CREATE TABLE "topic_revisions" (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`topic_id` text NOT NULL,
	`unit_id` text NOT NULL,
	`revision_count` integer DEFAULT 0,
	`last_revised_at` integer DEFAULT (strftime('%s', 'now')),
	FOREIGN KEY (`user_id`) REFERENCES `mppsc_users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE "user_attempts" (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`test_id` text NOT NULL,
	`start_time` integer NOT NULL,
	`end_time` integer,
	`score` real,
	`is_completed` integer DEFAULT false,
	`deleted_at` integer, "created_at" integer DEFAULT (strftime('%s', 'now')), "exam_type" text NOT NULL DEFAULT 'mppsc',
	FOREIGN KEY (`user_id`) REFERENCES `mppsc_users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`test_id`) REFERENCES `tests`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `verification_tokens` (
	`identifier` text NOT NULL,
	`token` text NOT NULL,
	`expires` integer NOT NULL,
	`created_at` integer DEFAULT (strftime('%s', 'now'))
);
