INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('e464a47a-273c-4172-8d86-24b4748f6085', 'mp-rivers-drainage-system-mppsc', 'Madhya Pradesh: The House of Rivers (Complete Study) | मध्य प्रदेश: नदियों का मायका', 'A comprehensive guide to the drainage system of MP for MPPSC aspirants. Covers Narmada, Chambal, Betwa, and key facts for Prelims & Mains', '{"hi":[{"type":"h2","text":"मध्य प्रदेश: नदियों का मायका (House of Rivers)"},{"type":"p","text":"मध्य प्रदेश लोक सेवा आयोग (MPPSC) की प्रारंभिक और मुख्य परीक्षा (Paper 1, Part B) के लिए ''मध्य प्रदेश की नदियाँ'' सबसे महत्वपूर्ण विषयों में से एक है। राज्य में सर्वाधिक नदियाँ प्रवाहित होने के कारण इसे ''नदियों का मायका'' कहा जाता है। यहाँ का अपवाह तंत्र (Drainage System) मुख्य रूप से विंध्याचल और सतपुड़ा पर्वत श्रृंखलाओं द्वारा निर्धारित होता है।"},{"type":"h2","text":"अपवाह तंत्र का वर्गीकरण (Classification of Drainage System)"},{"type":"p","text":"मध्य प्रदेश के अपवाह तंत्र को मुख्यतः 5 भागों में बांटा जा सकता है। परीक्षा की दृष्टि से गंगा अपवाह तंत्र सबसे बड़ा है।"},{"type":"ul","items":["गंगा अपवाह तंत्र (Ganga Drainage System): सबसे बड़ा, जिसमें चंबल, बेतवा, सोन, केन आदि नदियाँ शामिल हैं।","नर्मदा अपवाह तंत्र (Narmada Drainage System): राज्य का दूसरा सबसे बड़ा तंत्र।","ताप्ती अपवाह तंत्र (Tapti Drainage System)","गोदावरी अपवाह तंत्र (Godavari Drainage System): दक्षिण की ओर बहने वाली नदियाँ जैसे वेनगंगा, पेंच।","माही अपवाह तंत्र (Mahi Drainage System)"]},{"type":"h2","text":"1. नर्मदा नदी (Narmada River) - म.प्र. की जीवन रेखा"},{"type":"p","text":"नर्मदा भारत की 5वीं सबसे बड़ी और पश्चिम की ओर बहने वाली सबसे बड़ी नदी है। यह भ्रंश घाटी (Rift Valley) में बहती है और डेल्टा के बजाय एश्चुअरी (Estuary) का निर्माण करती है।"},{"type":"ul","items":["उद्गम (Origin): अमरकंटक (अनूपपुर)।","कुल लंबाई: 1312 किमी (मध्य प्रदेश में 1077 किमी)।","समापन: खंभात की खाड़ी (गुजरात)।","प्रमुख जलप्रपात (Waterfalls): धुआंधार (जबलपुर), कपिलधारा और दुग्धधारा (अमरकंटक), सहस्रधारा (महेश्वर)।","विशेष तथ्य: इसे ''खुशियों की नदी'' (River of Pleasure) भी कहा जाता है और इसे जीवित इकाई का दर्जा प्राप्त है।"]},{"type":"h2","text":"2. चंबल नदी (Chambal River)"},{"type":"p","text":"यह यमुना की मुख्य सहायक नदी है और अपने बीहड़ों (Ravines) के निर्माण के लिए जानी जाती है, जो अवनालिका अपरदन (Gully Erosion) का परिणाम हैं।"},{"type":"ul","items":["उद्गम: जानापाव पहाड़ी (महू, इंदौर)।","प्रमुख बाँध: गाँधी सागर (मंदसौर), राणा प्रताप सागर (चित्तौड़गढ़), जवाहर सागर (कोटा)।","विशेष: यह म.प्र. और राजस्थान के बीच प्राकृतिक सीमा बनाती है। यह घड़ियाल संरक्षण के लिए प्रसिद्ध है।"]},{"type":"h2","text":"अन्य महत्वपूर्ण नदियाँ (Other Key Rivers)"},{"type":"ul","items":["बेतवा (Betwa): कुमरा गाँव (रायसेन) से उद्गम। प्रदूषण के स्तर के कारण इसे ''मध्य प्रदेश की गंगा'' कहा जाता है। यह बुंदेलखंड की जीवन रेखा है।","सोन (Son): अमरकंटक से उद्गम। यह गंगा में दक्षिण की ओर से मिलने वाली प्रमुख नदी है। इसे ''स्वर्ण नदी'' (Gold River) भी कहते हैं।","ताप्ती (Tapti): मुलताई (बैतूल) से उद्गम। नर्मदा के समानांतर भ्रंश घाटी में बहती है।","माही (Mahi): धार से उद्गम। यह विश्व की एकमात्र नदी है जो कर्क रेखा (Tropic of Cancer) को दो बार काटती है।"]},{"type":"quote","text":"Pro Tip: परीक्षा में अक्सर नदियों की दिशा पूछी जाती है। याद रखें: चंबल, बेतवा, सोन, केन ''उत्तर'' की ओर; नर्मदा, ताप्ती ''पश्चिम'' की ओर; और वेनगंगा, वर्धा ''दक्षिण'' की ओर बहती हैं।"},{"type":"h2","text":"मानचित्र और संसाधन (Maps & Resources)"},{"type":"ul","items":["MP River Map (Maps of India): https://www.mapsofindia.com/maps/madhyapradesh/rivers/index.html","MP Physical Map (Wiki Commons): https://commons.wikimedia.org/wiki/File:Madhya_Pradesh_Physical_Map.png"]}],"en":[{"type":"h2","text":"Madhya Pradesh: The House of Rivers"},{"type":"p","text":"For the Madhya Pradesh Public Service Commission (MPPSC) Prelims and Mains (Paper 1, Part B), ''Rivers of Madhya Pradesh'' is one of the most critical topics. Due to the high number of rivers flowing through the state, it is known as the ''House of Rivers'' (Nadiyon ka Mayka). The Drainage System here is largely determined by the Vindhyachal and Satpura mountain ranges."},{"type":"h2","text":"Classification of Drainage System"},{"type":"p","text":"The drainage system of MP can be broadly classified into 5 parts. From an exam perspective, the Ganga Drainage System is the largest."},{"type":"ul","items":["Ganga Drainage System: The largest, including rivers like Chambal, Betwa, Son, Ken, etc.","Narmada Drainage System: The second-largest system in the state.","Tapti Drainage System","Godavari Drainage System: Rivers flowing southwards, such as Wainganga and Pench.","Mahi Drainage System"]},{"type":"h2","text":"1. Narmada River - The Lifeline of MP"},{"type":"p","text":"Narmada is the 5th largest river in India and the largest west-flowing river. It flows through a Rift Valley and forms an Estuary instead of a Delta."},{"type":"ul","items":["Origin: Amarkantak (Anuppur).","Total Length: 1312 km (1077 km in Madhya Pradesh).","Termination: Gulf of Khambhat (Gujarat).","Major Waterfalls: Dhuandhar (Jabalpur), Kapildhara and Dugdhdhara (Amarkantak), Sahastradhara (Maheshwar).","Special Fact: Also known as the ''River of Pleasure'' and has been granted the status of a living entity."]},{"type":"h2","text":"2. Chambal River"},{"type":"p","text":"It is the main tributary of the Yamuna and is known for creating Ravines (Beehad), which are the result of Gully Erosion."},{"type":"ul","items":["Origin: Janapav Hills (Mhow, Indore).","Major Dams: Gandhi Sagar (Mandsaur), Rana Pratap Sagar (Chittorgarh), Jawahar Sagar (Kota).","Special: It forms a natural boundary between MP and Rajasthan. It is famous for Gharial conservation."]},{"type":"h2","text":"Other Key Rivers"},{"type":"ul","items":["Betwa: Originates from Kumra Village (Raisen). Called the ''Ganga of Madhya Pradesh'' due to pollution levels. It is the lifeline of Bundelkhand.","Son: Originates from Amarkantak. It is a major southern tributary of the Ganga. Also called the ''Gold River''.","Tapti: Originates from Multai (Betul). Flows parallel to the Narmada in a rift valley.","Mahi: Originates from Dhar. It is the only river in the world that cuts the Tropic of Cancer twice."]},{"type":"quote","text":"Pro Tip: Exams often ask about the direction of flow. Remember: Chambal, Betwa, Son, Ken flow ''North''; Narmada, Tapti flow ''West''; and Wainganga, Wardha flow ''South''."},{"type":"h2","text":"Maps & Resources"},{"type":"ul","items":["MP River Map (Maps of India): https://www.mapsofindia.com/maps/madhyapradesh/rivers/index.html","MP Physical Map (Wiki Commons): https://commons.wikimedia.org/wiki/File:Madhya_Pradesh_Physical_Map.png"]}]}', 'mp_gk', 'https://riversinsight.com/wp-content/uploads/2025/05/Rivers-of-Madhya-Pradesh-with-Map-and-Names.webp', 5, 1, 1770046306, 1771008930, 'blog', NULL, NULL, 0, 1, 1, 1, 0, 'मध्य प्रदेश: नदियों का मायका (House of Rivers) मध्य प्रदेश लोक सेवा आयोग (MPPSC) की प्रारंभिक और मुख्य परीक्षा (Paper 1, Part B) के लिए ''मध्य प्रदेश की नदियाँ'' सबसे महत्वपूर्ण विषयों में से एक है। राज...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('c061f27b-e72d-4aed-b110-4942e22df76b', 'mp-major-waterfalls-list', 'Major Waterfalls of Madhya Pradesh (मध्य प्रदेश के प्रमुख जलप्रपात)', 'A complete list of waterfalls in MP for Prelims matching questions. Includes location, river, and height facts', '{"hi":[{"type":"h2","text":"मध्य प्रदेश के प्रमुख जलप्रपात: एक नज़र में"},{"type":"p","text":"प्रारंभिक परीक्षा (Prelims) में अक्सर ''सही जोड़ी मिलाइए'' (Match the Column) प्रश्न जलप्रपातों से पूछे जाते हैं। मध्य प्रदेश में पठारी भूभाग और भ्रंश घाटियों के कारण अनेक सुंदर जलप्रपात हैं।"},{"type":"h2","text":"नर्मदा नदी पर स्थित जलप्रपात (Waterfalls on Narmada)"},{"type":"ul","items":["कपिलधारा (Kapildhara): अमरकंटक (अनूपपुर) - नर्मदा का पहला जलप्रपात।","दुग्धधारा (Dugdhdhara): अमरकंटक (अनूपपुर)।","धुआंधार (Dhuandhar): भेड़ाघाट (जबलपुर) - संगमरमर की चट्टानों के लिए प्रसिद्ध।","मंधार और दर्दी (Mandhar & Dardi): खंडवा।","सहस्रधारा (Sahastradhara): महेश्वर (खरगोन)।"]},{"type":"h2","text":"अन्य महत्वपूर्ण जलप्रपात (Other Key Waterfalls)"},{"type":"ul","items":["चचाई (Chachai): बीहड़ नदी (रीवा) - यह म.प्र. का दूसरा सबसे ऊँचा जलप्रपात माना जाता था (130 मीटर)।","बहुती (Bahuti): सेलर नदी (रीवा) - वर्तमान में इसे म.प्र. का सबसे ऊँचा जलप्रपात (198 मीटर) माना जाता है।","केवटी (Keoti): महाना नदी (रीवा)।","पातालपानी (Patalpani): चंबल नदी (इंदौर)।","राहतगढ़ (Rahatgarh): बीना नदी (सागर)।","पांडव (Pandav): केन नदी (पन्ना)।"]},{"type":"quote","text":"Pro Tip: रीवा को ''जलप्रपातों का शहर'' कहा जा सकता है क्योंकि चचाई, केवटी और बहुती तीनों यहीं स्थित हैं।"},{"type":"h2","text":"Images Resource"},{"type":"p","text":"विजुअलाइज़ करने के लिए देखें: "}],"en":[{"type":"h2","text":"Major Waterfalls of Madhya Pradesh: At a Glance"},{"type":"p","text":"In Prelims, ''Match the Column'' questions are frequently asked about waterfalls. Due to its plateau terrain and rift valleys, MP has numerous beautiful waterfalls."},{"type":"h2","text":"Waterfalls on Narmada River"},{"type":"ul","items":["Kapildhara: Amarkantak (Anuppur) - The first waterfall of Narmada.","Dugdhdhara: Amarkantak (Anuppur).","Dhuandhar: Bhedaghat (Jabalpur) - Famous for marble rocks.","Mandhar & Dardi: Khandwa.","Sahastradhara: Maheshwar (Khargone)."]},{"type":"h2","text":"Other Key Waterfalls"},{"type":"ul","items":["Chachai: Bihad River (Rewa) - Was considered the 2nd highest in MP (130m).","Bahuti: Selar River (Rewa) - Currently considered the highest waterfall in MP (198m).","Keoti: Mahana River (Rewa).","Patalpani: Chambal River (Indore).","Rahatgarh: Bina River (Sagar).","Pandav: Ken River (Panna)."]},{"type":"quote","text":"Pro Tip: Rewa can be called the ''City of Waterfalls'' as Chachai, Keoti, and Bahuti are all located here."},{"type":"h2","text":"Images Resource"},{"type":"p","text":"For visualization: "}]}', 'geography', 'https://media.assettype.com/outlooktraveller/2024-05/4b661012-049b-4caf-8dcb-708184426a91/shutterstock_2262421551.jpg?w=1200&h=900&auto=format%2Ccompress&fit=max&enlarge=true', 4, 1, 1770047177, 1771008934, 'blog', NULL, NULL, 0, 1, 1, 1, 0, 'मध्य प्रदेश के प्रमुख जलप्रपात: एक नज़र में प्रारंभिक परीक्षा (Prelims) में अक्सर ''सही जोड़ी मिलाइए'' (Match the Column) प्रश्न जलप्रपातों से पूछे जाते हैं। मध्य प्रदेश में पठारी भूभाग और भ्रंश घाटियों...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('e59c9ba4-7e7f-49ba-aaec-48cf38bf884b', 'mp-river-valley-projects-dams', 'Multi-Purpose River Valley Projects (बहुउद्देशीय नदी घाटी परियोजनाएं)', 'Detailed guide on MP''s dams and hydel power projects like Indira Sagar, Gandhi Sagar, and Bansagar for MPPSC Mains.', '{"hi":[{"type":"h2","text":"नदी घाटी परियोजनाएं: आधुनिक भारत के मंदिर"},{"type":"p","text":"सिंचाई (Irrigation) और जल विद्युत (Hydel Power) म.प्र. की अर्थव्यवस्था की रीढ़ हैं। मुख्य परीक्षा में इनसे संबंधित 5 या 11 अंकों के प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"चंबल घाटी परियोजना (Chambal Valley Project)"},{"type":"p","text":"यह म.प्र. की पहली परियोजना (1953-54) है। यह म.प्र. और राजस्थान की संयुक्त परियोजना (50:50) है।"},{"type":"ul","items":["गाँधी सागर (Gandhi Sagar): मंदसौर (115 MW क्षमता)।","राणा प्रताप सागर (Rana Pratap Sagar): चित्तौड़गढ़ (172 MW)।","जवाहर सागर (Jawahar Sagar): कोटा (99 MW)।"]},{"type":"h2","text":"नर्मदा घाटी परियोजना (Narmada Valley Project)"},{"type":"p","text":"यह भारत की सबसे बड़ी नदी घाटी परियोजनाओं में से एक है।"},{"type":"ul","items":["इंदिरा सागर (Indira Sagar): पुनासा, खंडवा। म.प्र. की सबसे बड़ी जलविद्युत क्षमता (1000 MW)।","सरदार सरोवर (Sardar Sarovar): गुजरात। (म.प्र., गुजरात, महाराष्ट्र, राजस्थान की संयुक्त परियोजना)।","ओंकारेश्वर परियोजना: खंडवा (520 MW)।"]},{"type":"h2","text":"अन्य प्रमुख परियोजनाएं"},{"type":"ul","items":["बाणसागर (Bansagar): सोन नदी (शहडोल)। (MP, UP, Bihar की संयुक्त परियोजना)।","माताटीला / रानी लक्ष्मीबाई: बेतवा नदी। (MP और UP)।","पेंच परियोजना: छिंदवाड़ा (MP और महाराष्ट्र)।"]},{"type":"h2","text":"Images Resource"},{"type":"p","text":"परियोजना मानचित्र: "}],"en":[{"type":"h2","text":"River Valley Projects: Temples of Modern India"},{"type":"p","text":"Irrigation and Hydel Power are the backbone of MP''s economy. In Mains, 5 or 11 marker questions are frequently asked from this topic."},{"type":"h2","text":"Chambal Valley Project"},{"type":"p","text":"This is MP''s first project (1953-54). It is a joint venture of MP and Rajasthan (50:50)."},{"type":"ul","items":["Gandhi Sagar: Mandsaur (115 MW capacity).","Rana Pratap Sagar: Chittorgarh (172 MW).","Jawahar Sagar: Kota (99 MW)."]},{"type":"h2","text":"Narmada Valley Project"},{"type":"p","text":"One of the largest river valley projects in India."},{"type":"ul","items":["Indira Sagar: Punasa, Khandwa. Largest hydel capacity in MP (1000 MW).","Sardar Sarovar: Gujarat. (Joint project of MP, Guj, Maha, Raj).","Omkareshwar Project: Khandwa (520 MW)."]},{"type":"h2","text":"Other Major Projects"},{"type":"ul","items":["Bansagar: Son River (Shahdol). (Joint project of MP, UP, Bihar).","Matatila / Rani Laxmibai: Betwa River. (MP & UP).","Pench Project: Chhindwara (MP & Maharashtra)."]},{"type":"h2","text":"Images Resource"},{"type":"p","text":"Project Map: "}]}', 'mp_gk', 'https://thumbs.dreamstime.com/b/stunning-landscape-photograph-capturing-serene-river-valley-lush-green-fields-winding-majestic-mountains-under-partly-328927578.jpg', 6, 1, 1770048220, 1771008935, 'blog', NULL, NULL, 0, 1, 1, 1, 0, 'नदी घाटी परियोजनाएं: आधुनिक भारत के मंदिर सिंचाई (Irrigation) और जल विद्युत (Hydel Power) म.प्र. की अर्थव्यवस्था की रीढ़ हैं। मुख्य परीक्षा में इनसे संबंधित 5 या 11 अंकों के प्रश्न पूछे जाते हैं। चंबल...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('6a04c619-ca4f-4db2-bc89-f9caf575e265', 'soils-of-mp-classification', 'Soils of Madhya Pradesh (मध्य प्रदेश की मिट्टियाँ)', 'Classification of MP soils (Black, Red-Yellow, Alluvial) based on ICAR. Crucial for Agriculture topics in Mains', '{"hi":[{"type":"h2","text":"मध्य प्रदेश की मृदा: कृषि का आधार"},{"type":"p","text":"भारतीय भूमि एवं मृदा सर्वेक्षण विभाग के अनुसार, मध्य प्रदेश में मुख्य रूप से 5 प्रकार की मिट्टियाँ पाई जाती हैं। मृदा का वितरण चट्टानों की प्रकृति पर निर्भर करता है।"},{"type":"h2","text":"1. काली मिट्टी (Black Soil) - सर्वाधिक क्षेत्र"},{"type":"p","text":"यह राज्य के लगभग 47% भाग पर पाई जाती है। इसे ''रेगुर'' (Regur) या ''कपासी मिट्टी'' भी कहते हैं।"},{"type":"ul","items":["क्षेत्र: मालवा का पठार, नर्मदा घाटी, सतपुड़ा।","विशेषता: जल धारण क्षमता (Water Retention) सर्वाधिक होती है।","फसलें: कपास (Cotton), सोयाबीन, गेंहू।"]},{"type":"h2","text":"2. लाल-पीली मिट्टी (Red-Yellow Soil)"},{"type":"p","text":"राज्य के लगभग 37% भाग (मुख्यतः पूर्वी भाग) में विस्तृत।"},{"type":"ul","items":["क्षेत्र: बघेलखंड (शहडोल, मंडला, बालाघाट)।","रंग: फेरिक ऑक्साइड के कारण लाल और हाइड्रेशन के कारण पीला।","फसलें: चावल (Rice) के लिए उपयुक्त।"]},{"type":"h2","text":"3. जलोढ़ मिट्टी (Alluvial Soil)"},{"type":"p","text":"यह सर्वाधिक उपजाऊ मिट्टी है, जो नदियों द्वारा बहाकर लाई जाती है।"},{"type":"ul","items":["क्षेत्र: उत्तर-पश्चिमी म.प्र. (भिंड, मुरैना, ग्वालियर)।","कमी: इसमें नाइट्रोजन और फास्फोरस की कमी होती है।","फसलें: सरसों (Mustard), गेंहू, गन्ना।"]},{"type":"quote","text":"Pro Tip: ''मिश्रित मिट्टी'' (Mixed Soil) बुंदेलखंड क्षेत्र में पाई जाती है, जो मोटे अनाज (Millets) के लिए उपयुक्त है।"},{"type":"h2","text":"Images Resource"},{"type":"p","text":"मृदा मानचित्र: "}],"en":[{"type":"h2","text":"Soils of Madhya Pradesh: Foundation of Agriculture"},{"type":"p","text":"According to the Survey of India, 5 main types of soils are found in MP. The distribution depends on the nature of rocks."},{"type":"h2","text":"1. Black Soil - Largest Area"},{"type":"p","text":"Found in approx 47% of the state. Also known as ''Regur'' or ''Cotton Soil''."},{"type":"ul","items":["Region: Malwa Plateau, Narmada Valley, Satpura.","Feature: Highest Water Retention capacity.","Crops: Cotton, Soybean, Wheat."]},{"type":"h2","text":"2. Red-Yellow Soil"},{"type":"p","text":"Covers approx 37% area (mainly Eastern part)."},{"type":"ul","items":["Region: Baghelkhand (Shahdol, Mandla, Balaghat).","Color: Red due to Ferric Oxide, Yellow due to hydration.","Crops: Suitable for Rice."]},{"type":"h2","text":"3. Alluvial Soil"},{"type":"p","text":"The most fertile soil, deposited by rivers."},{"type":"ul","items":["Region: North-West MP (Bhind, Morena, Gwalior).","Deficiency: Lacks Nitrogen and Phosphorus.","Crops: Mustard, Wheat, Sugarcane."]},{"type":"quote","text":"Pro Tip: ''Mixed Soil'' is found in the Bundelkhand region, suitable for coarse grains (Millets)."},{"type":"h2","text":"Images Resource"},{"type":"p","text":"Soil Map: "}]}', 'general', 'https://eos.com/wp-content/uploads/2019/12/identify-soil-type.jpg.webp', 5, 1, 1770048535, 1771008939, 'blog', NULL, NULL, 0, 1, 1, 1, 0, 'मध्य प्रदेश की मृदा: कृषि का आधार भारतीय भूमि एवं मृदा सर्वेक्षण विभाग के अनुसार, मध्य प्रदेश में मुख्य रूप से 5 प्रकार की मिट्टियाँ पाई जाती हैं। मृदा का वितरण चट्टानों की प्रकृति पर निर्भर करता है। ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('15b8158b-1eb6-4d3b-9179-f9931ddf06e2', 'preamble-indian-constitution-mppsc', 'Preamble: Soul of the Constitution (प्रस्तावना: संविधान की आत्मा)', 'Understand the key terms, 42nd Amendment, and Supreme Court cases related to the Preamble for MPPSC.', '{"hi":[{"type":"h2","text":"प्रस्तावना: संविधान की कुंजी"},{"type":"img","src":"https://upload.wikimedia.org/wikipedia/commons/8/84/Preamble_of_Constitution_of_India.svg","alt":"Original text of the Preamble of India","caption":"भारत के संविधान की मूल प्रस्तावना"},{"type":"p","text":"पंडित नेहरू द्वारा प्रस्तुत ''उद्देश्य प्रस्ताव'' (Objective Resolution) पर आधारित प्रस्तावना को संविधान की आत्मा और कुंजी (Key) कहा जाता है। इसमें संविधान के स्रोत, स्वरूप और उद्देश्यों का वर्णन है।"},{"type":"h2","text":"मुख्य शब्द और उनके अर्थ"},{"type":"ul","items":["संप्रभुता (Sovereignty): भारत अपने आंतरिक और बाहरी निर्णय लेने के लिए स्वतंत्र है।","समाजवादी (Socialist): लोकतांत्रिक समाजवाद (Democratic Socialism)।","पंथनिरपेक्ष (Secular): राज्य का कोई धर्म नहीं है।","लोकतंत्र (Democratic): जनता का शासन।"]},{"type":"h2","text":"महत्वपूर्ण संशोधन और वाद"},{"type":"p","text":"42वें संविधान संशोधन (1976) द्वारा प्रस्तावना में ''समाजवादी'', ''पंथनिरपेक्ष'' और ''अखंडता'' शब्द जोड़े गए। केशवानंद भारती केस (1973) में सुप्रीम कोर्ट ने माना कि प्रस्तावना संविधान का ''अभिन्न अंग'' है।"},{"type":"quote","text":"Pro Tip: के.एम. मुंशी ने प्रस्तावना को ''राजनीतिक जन्मपत्री'' (Political Horoscope) कहा था। यह कथन प्रीलिम्स में अक्सर पूछा जाता है।"}],"en":[{"type":"h2","text":"Preamble: The Key to the Constitution"},{"type":"p","text":"Based on the ''Objective Resolution'' moved by Pt. Nehru, the Preamble is called the Soul and Key to the Constitution. It describes the source, nature, and objectives of the Constitution."},{"type":"h2","text":"Key Words and Meanings"},{"type":"ul","items":["Sovereignty: India is free to take its own internal and external decisions.","Socialist: Democratic Socialism.","Secular: The State has no religion.","Democratic: Rule of the people."]},{"type":"h2","text":"Important Amendments & Cases"},{"type":"p","text":"The 42nd Amendment (1976) added the words ''Socialist'', ''Secular'', and ''Integrity''. In the Keshavananda Bharati Case (1973), the SC ruled that the Preamble is an ''integral part'' of the Constitution."},{"type":"quote","text":"Pro Tip: K.M. Munshi called the Preamble the ''Political Horoscope''. This statement is frequently asked in Prelims."}]}', 'polity', 'https://static.wixstatic.com/media/54f26c_8f1e95a4d5234746a30c5d142251b404~mv2.jpg/v1/fill/w_563,h_765,al_c,q_85,enc_avif,quality_auto/54f26c_8f1e95a4d5234746a30c5d142251b404~mv2.jpg', 5, 1, 1770054569, 1771009062, 'blog', NULL, NULL, 0, 0, 0, 1, 0, 'प्रस्तावना: संविधान की कुंजी  पंडित नेहरू द्वारा प्रस्तुत ''उद्देश्य प्रस्ताव'' (Objective Resolution) पर आधारित प्रस्तावना को संविधान की आत्मा और कुंजी (Key) कहा जाता है। इसमें संविधान के स्रोत, स्वरूप...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('34c09967-f50b-4040-8736-7d647944404d', 'fundamental-rights-articles-12-to-35', 'Fundamental Rights: Magna Carta of India (मौलिक अधिकार)', 'Comprehensive guide to Articles 12-35, the 6 Fundamental Rights, and Writs under Article 32.', '{"hi":[{"type":"h2","text":"मौलिक अधिकार: एक परिचय"},{"type":"p","text":"संविधान के भाग-3 (अनुच्छेद 12 से 35) में मौलिक अधिकारों का वर्णन है। ये अमेरिका के संविधान (Bill of Rights) से प्रेरित हैं। इसे भारत का ''मैग्ना कार्टा'' कहा जाता है।"},{"type":"h2","text":"6 मौलिक अधिकार (Six Fundamental Rights)"},{"type":"ul","items":["समता का अधिकार (Right to Equality): अनुच्छेद 14-18.","स्वतंत्रता का अधिकार (Right to Freedom): अनुच्छेद 19-22.","शोषण के विरुद्ध अधिकार (Right against Exploitation): अनुच्छेद 23-24.","धर्म की स्वतंत्रता (Freedom of Religion): अनुच्छेद 25-28.","संस्कृति और शिक्षा (Culture & Education): अनुच्छेद 29-30.","संवैधानिक उपचार (Constitutional Remedies): अनुच्छेद 32।"]},{"type":"img","src":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Fundamental_rights_of_India.svg/800px-Fundamental_rights_of_India.svg.png","alt":"Chart showing 6 Fundamental Rights","caption":"6 मौलिक अधिकारों का वर्गीकरण"},{"type":"quote","text":"Pro Tip: अनुच्छेद 32 के तहत सुप्रीम कोर्ट 5 प्रकार की रिट (Writ) जारी कर सकता है: बंदी प्रत्यक्षीकरण, परमादेश, प्रतिषेध, उत्प्रेषण, और अधिकार पृच्छा।"}],"en":[{"type":"h2","text":"Fundamental Rights: An Introduction"},{"type":"p","text":"Part III (Articles 12 to 35) of the Constitution deals with Fundamental Rights. Inspired by the US Bill of Rights, it is called the ''Magna Carta'' of India."},{"type":"h2","text":"Six Fundamental Rights"},{"type":"ul","items":["Right to Equality: Articles 14-18.","Right to Freedom: Articles 19-22.","Right against Exploitation: Articles 23-24.","Freedom of Religion: Articles 25-28.","Culture & Education: Articles 29-30.","Constitutional Remedies: Article 32."]},{"type":"quote","text":"Pro Tip: Under Article 32, the Supreme Court can issue 5 types of Writs: Habeas Corpus, Mandamus, Prohibition, Certiorari, and Quo-Warranto."}]}', 'polity', 'https://pwonlyias.com/wp-content/uploads/2024/03/pasted-image-0-2.webp', 7, 1, 1770054705, 1771008945, 'blog', NULL, NULL, 1, 0, 1, 1, 0, 'मौलिक अधिकार: एक परिचय संविधान के भाग-3 (अनुच्छेद 12 से 35) में मौलिक अधिकारों का वर्णन है। ये अमेरिका के संविधान (Bill of Rights) से प्रेरित हैं। इसे भारत का ''मैग्ना कार्टा'' कहा जाता है। 6 मौलिक अधिक...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('76273c0c-f2c3-4492-a091-72215ef1c56e', 'dpsp-directive-principles-state-policy', 'DPSP: Welfare State Principles (राज्य के नीति निर्देशक तत्व)', 'Analysis of Part IV (Art 36-51), Socialist vs Gandhian principles, and Uniform Civil Code.', '{"hi":[{"type":"h2","text":"DPSP: कल्याणकारी राज्य की स्थापना"},{"type":"p","text":"भाग-4 (अनुच्छेद 36 से 51) में वर्णित ये तत्व आयरलैंड के संविधान से लिए गए हैं। इनका उद्देश्य एक ''कल्याणकारी राज्य'' (Welfare State) की स्थापना करना है।"},{"type":"h2","text":"प्रमुख अनुच्छेद (Key Articles)"},{"type":"ul","items":["अनुच्छेद 39(A): समान न्याय और मुफ्त विधिक सहायता।","अनुच्छेद 40: ग्राम पंचायतों का संगठन (गांधीवादी सिद्धांत)।","अनुच्छेद 44: समान नागरिक संहिता (Uniform Civil Code - UCC)।","अनुच्छेद 50: कार्यपालिका से न्यायपालिका का पृथक्करण।","अनुच्छेद 51: अंतर्राष्ट्रीय शांति और सुरक्षा।"]},{"type":"quote","text":"Pro Tip: मिनर्वा मिल्स केस (1980) में कोर्ट ने कहा कि भारतीय संविधान मौलिक अधिकारों और DPSP के बीच ''संतुलन'' पर टिका है।"}],"en":[{"type":"h2","text":"DPSP: Establishing a Welfare State"},{"type":"p","text":"Described in Part IV (Articles 36 to 51), these are borrowed from the Irish Constitution. Their aim is to establish a ''Welfare State''."},{"type":"h2","text":"Key Articles"},{"type":"ul","items":["Article 39(A): Equal justice and free legal aid.","Article 40: Organization of Village Panchayats (Gandhian Principle).","Article 44: Uniform Civil Code (UCC).","Article 50: Separation of Judiciary from Executive.","Article 51: International peace and security."]},{"type":"quote","text":"Pro Tip: In the Minerva Mills Case (1980), the Court stated that the Indian Constitution is founded on the ''balance'' between Fundamental Rights and DPSP."}]}', 'polity', 'https://notes.saralupsc.com/wp-content/uploads/2024/03/image-62.png', 6, 1, 1770054823, 1771008946, 'blog', NULL, NULL, 1, 0, 1, 1, 0, 'DPSP: कल्याणकारी राज्य की स्थापना भाग-4 (अनुच्छेद 36 से 51) में वर्णित ये तत्व आयरलैंड के संविधान से लिए गए हैं। इनका उद्देश्य एक ''कल्याणकारी राज्य'' (Welfare State) की स्थापना करना है। प्रमुख अनुच्छेद...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('95e517fe-ce99-435c-bd28-f3caa3ada2cf', 'president-of-india-powers-and-functions', 'President of India: Powers & Election (भारत के राष्ट्रपति)', 'Study the Election process (Art 54), Impeachment (Art 61), and Veto Powers of the President.', '{"hi":[{"type":"h2","text":"राष्ट्रपति: भारत का प्रथम नागरिक"},{"type":"p","text":"संविधान के अनुच्छेद 52 के अनुसार भारत का एक राष्ट्रपति होगा। वह कार्यपालिका का संवैधानिक प्रमुख (Constitutional Head) होता है।"},{"type":"img","src":"https://upload.wikimedia.org/wikipedia/commons/4/42/Rashtrapati_Bhavan_New_Delhi.jpg","alt":"Rashtrapati Bhavan New Delhi","caption":"राष्ट्रपति भवन: भारत के राष्ट्रपति का आधिकारिक निवास"},{"type":"h2","text":"निर्वाचन और महाभियोग"},{"type":"ul","items":["निर्वाचन (Art. 54): निर्वाचक मंडल में संसद और राज्यों की विधानसभाओं के निर्वाचित सदस्य शामिल होते हैं।","पद्धति: एकल संक्रमणीय मत (Single Transferable Vote)।","महाभियोग (Art. 61): संविधान के उल्लंघन पर संसद के किसी भी सदन में लाया जा सकता है।"]},{"type":"h2","text":"शक्तियाँ (Powers)"},{"type":"ul","items":["वीटो शक्ति: आत्यंतिक, निलंबनकारी, और पॉकेट वीटो।","अध्यादेश (Art. 123): जब संसद सत्र में न हो।","क्षमादान (Art. 72): मृत्युदंड को क्षमा करने की शक्ति।"]},{"type":"quote","text":"Pro Tip: ज्ञानी जैल सिंह ने ''भारतीय डाकघर विधेयक'' पर पॉकेट वीटो का प्रयोग किया था। यह एकमात्र उदाहरण है।"}],"en":[{"type":"h2","text":"President: The First Citizen of India"},{"type":"p","text":"According to Article 52, there shall be a President of India. He is the Constitutional Head of the Executive."},{"type":"h2","text":"Election & Impeachment"},{"type":"ul","items":["Election (Art. 54): Electoral College includes elected members of Parliament and State Legislative Assemblies.","Method: Single Transferable Vote system.","Impeachment (Art. 61): Can be initiated in either house of Parliament for violation of the Constitution."]},{"type":"h2","text":"Powers"},{"type":"ul","items":["Veto Power: Absolute, Suspensive, and Pocket Veto.","Ordinance (Art. 123): When Parliament is not in session.","Pardoning Power (Art. 72): Power to pardon death sentences."]},{"type":"quote","text":"Pro Tip: Giani Zail Singh exercised Pocket Veto on the ''Indian Post Office Bill''. This is the only instance."}]}', 'polity', 'https://framerusercontent.com/images/Lr5Hlhp9QtGV1RCysObyCCy4Ad0.webp?width=1638&height=2048', 6, 1, 1770054927, 1771008947, 'blog', NULL, NULL, 1, 0, 1, 1, 0, 'राष्ट्रपति: भारत का प्रथम नागरिक संविधान के अनुच्छेद 52 के अनुसार भारत का एक राष्ट्रपति होगा। वह कार्यपालिका का संवैधानिक प्रमुख (Constitutional Head) होता है।  निर्वाचन और महाभियोग  शक्तियाँ (Powers)...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('9a3fc1db-717b-43f3-b02a-200e62e73e8e', 'panchayati-raj-system-73rd-amendment', 'Panchayati Raj: 73rd Amendment (पंचायती राज)', 'Deep dive into 73rd Amendment Act 1992, 11th Schedule, and Committees like Balwant Rai Mehta.', '{"hi":[{"type":"h2","text":"पंचायती राज: लोकतांत्रिक विकेंद्रीकरण"},{"type":"p","text":"73वें संविधान संशोधन (1992) ने पंचायती राज को संवैधानिक दर्जा दिया। इसके द्वारा भाग-9 और 11वीं अनुसूची (11th Schedule) जोड़ी गई, जिसमें 29 विषय हैं।"},{"type":"h2","text":"प्रमुख समितियाँ (Key Committees)"},{"type":"ul","items":["बलवंत राय मेहता समिति (1957): त्रि-स्तरीय (3-Tier) ढांचे की सिफारिश।","अशोक मेहता समिति (1977): द्वि-स्तरीय (2-Tier) ढांचे की सिफारिश।","एल.एम. सिंघवी समिति (1986): संवैधानिक दर्जे की मांग की।"]},{"type":"h2","text":"मुख्य विशेषताएं"},{"type":"ul","items":["त्रि-स्तरीय ढांचा: ग्राम पंचायत, जनपद पंचायत, और जिला पंचायत।","आरक्षण: मध्य प्रदेश में महिलाओं के लिए 50% सीटें आरक्षित हैं।","कार्यकाल: 5 वर्ष। चुनाव लड़ने की न्यूनतम आयु 21 वर्ष।"]},{"type":"quote","text":"Pro Tip: मध्य प्रदेश देश का पहला राज्य था जिसने 73वें संविधान संशोधन के बाद पंचायती राज लागू किया (1994)।"}],"en":[{"type":"h2","text":"Panchayati Raj: Democratic Decentralization"},{"type":"p","text":"The 73rd Constitutional Amendment (1992) gave constitutional status to Panchayati Raj. It added Part IX and the 11th Schedule containing 29 subjects."},{"type":"h2","text":"Key Committees"},{"type":"ul","items":["Balwant Rai Mehta Committee (1957): Recommended 3-Tier structure.","Ashok Mehta Committee (1977): Recommended 2-Tier structure.","L.M. Singhvi Committee (1986): Demanded Constitutional Status."]},{"type":"h2","text":"Key Features"},{"type":"ul","items":["3-Tier Structure: Gram Panchayat, Janpad Panchayat, and Zila Panchayat.","Reservation: 50% seats reserved for women in Madhya Pradesh.","Tenure: 5 years. Minimum age to contest election is 21 years."]},{"type":"quote","text":"Pro Tip: Madhya Pradesh was the first state in the country to implement Panchayati Raj after the 73rd Amendment (1994)."}]}', 'polity', 'https://chrysalishigh.com/wp-content/uploads/2024/04/image-7.jpeg', 5, 1, 1770055033, 1770055033, 'blog', NULL, NULL, 1, 0, 0, 1, 0, 'पंचायती राज: लोकतांत्रिक विकेंद्रीकरण 73वें संविधान संशोधन (1992) ने पंचायती राज को संवैधानिक दर्जा दिया। इसके द्वारा भाग-9 और 11वीं अनुसूची (11th Schedule) जोड़ी गई, जिसमें 29 विषय हैं। प्रमुख समितिय...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('89785135-c43c-4f95-9916-0aec4652fd24', 'mppsc-exam-2026-important-dates-syllabus-strategy', 'MPPSC Exam 2026: Important Dates, Syllabus, Pattern Change & Strategy', 'The Madhya Pradesh Public Service Commission (MPPSC) has released the notification for the State Service Exam 2026. Check out the new exam pattern, syllabus, important dates, and vacancy details.', '{"en":[{"type":"h2","text":"MPPSC Exam 2026: Overview & Notification"},{"type":"p","text":"The Madhya Pradesh Public Service Commission (MPPSC) officially released the notification for the State Service Examination 2026 on December 31, 2025. The commission has announced 155 vacancies for various Group A and Group B posts, including Deputy Collector and DSP."},{"type":"p","text":"A major shift has been introduced in the Preliminary Exam pattern: each question now carries 3 marks, and a negative marking scheme (deducting 1 mark for every incorrect answer) has been implemented."},{"type":"h2","text":"Key Highlights of MPPSC 2026"},{"type":"table","instruction":"Render as a responsive table with two columns.","head":["Feature","Details"],"body":[["Exam Name","MP State Service Examination 2026"],["Conducting Body","Madhya Pradesh Public Service Commission (MPPSC)"],["Application Mode","Online"],["Total Vacancies","155 (Provisional)"],["Selection Process","Prelims (Screening) → Mains (Written) → Interview"],["Official Website","www.mppsc.mp.gov.in"]]},{"type":"h2","text":"Major Changes in Exam Pattern (2026)"},{"type":"table","instruction":"Render as a comparison table to highlight changes.","head":["Feature","Old Pattern (Pre-2026)","New Pattern (2026)"],"body":[["Negative Marking","None","Yes (1/3rd Deduction)"],["Marks per Question","2 Marks","3 Marks"],["Total Marks (Paper I)","200 Marks","300 Marks"],["Marking Formula","-","3R - W (3 × Right - Wrong)"]]},{"type":"h2","text":"Important Dates"},{"type":"table","instruction":"Render as a schedule/date table.","head":["Event","Date"],"body":[["Notification Release","31 December 2025"],["Online Application Start","10 January 2026"],["Last Date to Apply","09 February 2026"],["Correction Window","15 Jan 2026 to 11 Feb 2026"],["Admit Card Availability","16 April 2026"],["MPPSC Prelims Exam Date","26 April 2026"]]},{"type":"h2","text":"Vacancy Details"},{"type":"ul","items":["Deputy Collector: 17 Posts","Deputy Superintendent of Police (DSP): 18 Posts","Commercial Tax Officer: 3 Posts","Chief Municipal Officer (Category C): 4 Posts","Chief Executive Officer (Janpad Panchayat): 15 Posts","Development Block Women Empowerment Officer: 39 Posts"]},{"type":"h2","text":"Eligibility Criteria"},{"type":"p","text":"Candidates must hold a Bachelor''s Degree from a recognized university. Final year students are eligible for Prelims but must prove passing before Mains."},{"type":"h2","text":"Physical Standards (Uniformed Posts)"},{"type":"table","instruction":"Render as a data grid.","head":["Category","Height","Chest (Unexpanded)","Chest (Expanded)"],"body":[["Male","168 cm","84 cm","89 cm"],["Female","155 cm","N/A","N/A"]]},{"type":"h2","text":"Exam Pattern: Preliminary"},{"type":"p","text":"The Prelims consists of two objective papers. Paper II (CSAT) is qualifying in nature."},{"type":"table","instruction":"Render with center alignment for numbers.","head":["Paper","Subject","Questions","Marks","Duration"],"body":[["Paper I","General Studies","100","300","2 Hours"],["Paper II","General Aptitude (CSAT)","100","300","2 Hours"]]},{"type":"h2","text":"Exam Pattern: Mains"},{"type":"table","instruction":"Render as a detailed list table.","head":["Paper","Subject","Marks"],"body":[["Paper I","History & Geography","300"],["Paper II","Polity & Sociology","300"],["Paper III","Economy, Science & Health","300"],["Paper IV","Philosophy, Psychology, Pub Ad","300"],["Paper V","General Hindi & Grammar","200"],["Paper VI","Hindi Essay & Draft Writing","100"]]}],"hi":[{"type":"h2","text":"MPPSC परीक्षा 2026: अवलोकन और अधिसूचना"},{"type":"p","text":"मध्य प्रदेश लोक सेवा आयोग (MPPSC) ने 31 दिसंबर 2025 को राज्य सेवा परीक्षा 2026 के लिए आधिकारिक अधिसूचना जारी कर दी है। आयोग ने डिप्टी कलेक्टर और डीएसपी सहित विभिन्न ग्रुप ए और ग्रुप बी पदों के लिए 155 रिक्तियों की घोषणा की है।"},{"type":"p","text":"प्रारंभिक परीक्षा पैटर्न में एक बड़ा बदलाव किया गया है: अब प्रत्येक प्रश्न 3 अंक का होगा, और नकारात्मक अंकन (प्रत्येक गलत उत्तर के लिए 1 अंक की कटौती) लागू किया गया है।"},{"type":"h2","text":"MPPSC 2026 की मुख्य विशेषताएं"},{"type":"table","instruction":"Render as a responsive table with two columns.","head":["विशेषता","विवरण"],"body":[["परीक्षा का नाम","मप्र राज्य सेवा परीक्षा 2026"],["आयोजक संस्था","मध्य प्रदेश लोक सेवा आयोग (MPPSC)"],["आवेदन का तरीका","ऑनलाइन"],["कुल रिक्तियां","155 (अनंतिम)"],["चयन प्रक्रिया","प्रारंभिक (स्क्रीनिंग) → मुख्य (लिखित) → साक्षात्कार"],["आधिकारिक वेबसाइट","www.mppsc.mp.gov.in"]]},{"type":"h2","text":"परीक्षा पैटर्न में प्रमुख बदलाव (2026)"},{"type":"table","instruction":"Render as a comparison table to highlight changes.","head":["विशेषता","पुराना पैटर्न (2026 से पहले)","नया पैटर्न (2026)"],"body":[["नकारात्मक अंकन","कोई नहीं","हाँ (1/3 अंक की कटौती)"],["प्रति प्रश्न अंक","2 अंक","3 अंक"],["कुल अंक (पेपर I)","200 अंक","300 अंक"],["अंकन सूत्र","-","3R - W (3 × सही - गलत)"]]},{"type":"h2","text":"महत्वपूर्ण तिथियां"},{"type":"table","instruction":"Render as a schedule/date table.","head":["घटना","तिथि"],"body":[["अधिसूचना जारी","31 दिसंबर 2025"],["ऑनलाइन आवेदन प्रारंभ","10 जनवरी 2026"],["आवेदन की अंतिम तिथि","09 फरवरी 2026"],["सुधार विंडो","15 जनवरी से 11 फरवरी 2026"],["प्रवेश पत्र उपलब्धता","16 अप्रैल 2026"],["MPPSC प्रारंभिक परीक्षा तिथि","26 अप्रैल 2026"]]},{"type":"h2","text":"रिक्ति विवरण"},{"type":"ul","items":["डिप्टी कलेक्टर: 17 पद","पुलिस उपाधीक्षक (DSP): 18 पद","वाणिज्यिक कर अधिकारी: 3 पद","मुख्य नगरपालिका अधिकारी (श्रेणी ग): 4 पद","मुख्य कार्यकारी अधिकारी (जनपद पंचायत): 15 पद","विकास खंड महिला अधिकारिता अधिकारी: 39 पद"]},{"type":"h2","text":"पात्रता मानदंड"},{"type":"p","text":"उम्मीदवारों के पास किसी मान्यता प्राप्त विश्वविद्यालय से स्नातक की डिग्री होनी चाहिए। अंतिम वर्ष के छात्र प्रारंभिक परीक्षा के लिए पात्र हैं लेकिन मुख्य परीक्षा से पहले उत्तीर्ण होने का प्रमाण प्रस्तुत करना होगा।"},{"type":"h2","text":"शारीरिक मानदंड (वर्दीधारी पद)"},{"type":"table","instruction":"Render as a data grid.","head":["श्रेणी","ऊंचाई","सीना (बिना फुलाए)","सीना (फुलाकर)"],"body":[["पुरुष","168 सेमी","84 सेमी","89 सेमी"],["महिला","155 सेमी","लागू नहीं","लागू नहीं"]]},{"type":"h2","text":"परीक्षा पैटर्न: प्रारंभिक"},{"type":"p","text":"प्रारंभिक परीक्षा में दो वस्तुनिष्ठ पेपर होते हैं। पेपर II (CSAT) केवल क्वालिफाइंग प्रकृति का है।"},{"type":"table","instruction":"Render with center alignment for numbers.","head":["पेपर","विषय","प्रश्न","अंक","अवधि"],"body":[["पेपर I","सामान्य अध्ययन","100","300","2 घंटे"],["पेपर II","सामान्य अभिरुचि (CSAT)","100","300","2 घंटे"]]},{"type":"h2","text":"परीक्षा पैटर्न: मुख्य"},{"type":"table","instruction":"Render as a detailed list table.","head":["पेपर","विषय","अंक"],"body":[["पेपर I","इतिहास और भूगोल","300"],["पेपर II","राजनीति और समाजशास्त्र","300"],["पेपर III","अर्थव्यवस्था, विज्ञान और स्वास्थ्य","300"],["पेपर IV","दर्शनशास्त्र, मनोविज्ञान, लोक प्रशासन","300"],["पेपर V","सामान्य हिंदी और व्याकरण","200"],["पेपर VI","हिंदी निबंध और प्रारूप लेखन","100"]]}]}', 'strategy', NULL, 8, 1, 1770544512, 1771262536, 'blog', NULL, NULL, 0, 1, 0, 1, 0, 'MPPSC परीक्षा 2026: अवलोकन और अधिसूचना मध्य प्रदेश लोक सेवा आयोग (MPPSC) ने 31 दिसंबर 2025 को राज्य सेवा परीक्षा 2026 के लिए आधिकारिक अधिसूचना जारी कर दी है। आयोग ने डिप्टी कलेक्टर और डीएसपी सहित विभि...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('d8f25282-0071-4d09-8ef9-72c82d763d7d', 'mppsc-prelims-2026-detailed-syllabus-paper-1', 'MPPSC Prelims 2026: Detailed Syllabus (Paper I - General Studies)', 'Comprehensive unit-wise syllabus for MPPSC Preliminary Exam Paper I (General Studies). Covers History, Geography, Polity, Economy, Science, and MP Special topics.', '{"en":[{"type":"h2","text":"Overview: MPPSC Preliminary Syllabus"},{"type":"p","text":"The MPPSC Preliminary Examination consists of two objective type papers: Paper-I (General Studies) and Paper-II (General Aptitude Test). Below is the detailed unit-wise breakdown for Paper-I."},{"type":"h2","text":"Unit 1: History of India"},{"type":"ul","items":["Concepts and Ideas: Ancient Indian Knowledge Tradition, Bharatvarsha, Vedas, Upanishad, Aranyaka, Brahman Granth, Shaddarshan, Smritiyan, Rit Sabha-Samiti, Gantantra (Republic), Varnashrama, Purushartha, Rin Sanskara, Panch Mahayagya/Yagya, Principle of Karma, Bodhisatva, Teerthankar.","Salient features, Events and their administrative, Social and Economic Systems of Ancient and Medieval India.","India''s cultural heritage: Artforms, literature, festivals and events.","Social and Religious Reform Movements in 19th and 20th century.","Independence Struggle and Indian National Movement.","Integration and Reorganization of India after Independence."]},{"type":"h2","text":"Unit 2: History, Culture and Literature of Madhya Pradesh"},{"type":"ul","items":["Major Events and Major Dynasties of Madhya Pradesh.","Contribution of Madhya Pradesh in Freedom Movement.","Major Arts and Sculpture of Madhya Pradesh.","Major Tribes and Dialects of Madhya Pradesh.","Major Festivals, Folk Music, Folk Arts and Folk literature of Madhya Pradesh.","Important literary Creators of Madhya Pradesh and their Literary Creations.","Major Tourist Places of Religious, Cultural and Archaeological Importance in Madhya Pradesh.","World Heritage sites in Madhya Pradesh.","Important Tribal Personalities of Madhya Pradesh."]},{"type":"h2","text":"Unit 3: Geography of India"},{"type":"ul","items":["Mountains, Hills, Plateaus, Rivers and Lakes.","Climate phenomena: El Nino, La Nina, Southern Oscillation, Western Disturbance, Consequences of Climate Change.","Natural Resources: Forest, Minerals, Water Resources.","Major Crops, Food Security, Green Revolution, Strategies for the Second Green Revolution.","Conventional and Non-Conventional sources of energy.","Natural hazards and disasters in India, Major cyclones in India.","Population growth, distribution and Density, Rural-Urban Migration."]},{"type":"h2","text":"Unit 4: Geography of Madhya Pradesh"},{"type":"ul","items":["Forest, Forest Produce, Rivers, Hills and Plateaus.","Climate: Seasons, Temperature, Rainfall.","Natural Resources: Soils and Major Mineral resources.","Major Crops, Water Resources, Irrigation and Irrigation Projects.","Conventional and Non-Conventional Sources of Energy.","Major Industries of Madhya Pradesh.","Population Growth, Distribution and Density, Urbanisation."]},{"type":"h2","text":"Unit 5: Constitutional System of India and Madhya Pradesh"},{"type":"ul","items":["Constituent Assembly.","Federal Executive, President and Parliament.","Supreme Court and Judicial System.","Constitutional Amendments.","Fundamental Rights and Duties of Citizens, Duties and Directive Principle of State.","National and Regional Constitutional/Statutory Commissions and Institutions.","Constitutional System of Madhya Pradesh (Governor, Cabinet, Legislative Assembly, High Court).","Three-Tier Panchayati Raj and Civil Administration system in Madhya Pradesh.","Good Governance in Madhya Pradesh (Governance System)."]},{"type":"h2","text":"Unit 6: Economy of India and Madhya Pradesh"},{"type":"ul","items":["Current Situation of Madhya Pradesh in Indian Economy.","Population and Human Resources Development: Education, Health and Skills in Madhya Pradesh.","Progress in Sustainable Development Goals in Madhya Pradesh.","Development of Agriculture, Industry, MSME and Infrastructure Development in Madhya Pradesh.","Self-Reliant/Atma Nirbhar Madhya Pradesh, One District One Product (ODOP).","Progress of Intellectual Property Rights (IPR) in Madhya Pradesh.","Recent Trends in Indian Economy: Agriculture, Industry and Service sectors.","Financial Institutions: Reserve Bank, Commercial Banks, SEBI, Non-Banking Financial Institutions.","India''s foreign Trade Policies: G-20, SAARC and ASEAN."]},{"type":"h2","text":"Unit 7: Science, Environment and Health"},{"type":"ul","items":["Preliminary Knowledge of Main Branches of Science.","Important Indian Achievements.","Scientific Research Institutions and their Satellite and Space Technology Achievement of India in the Field of Space Science.","Structure of Human Body.","Nutrition, Food, Nutrient and Malnutrition.","Genetic Disease, Sickle Cell Anemia: Cause, Effect, Diagnosis and Program.","Health Policy and Programmes, Infectious disease and its Prevention and Health Indicator.","Concept of Sustainable Development and SDG''s.","Environmental Factors, Biodiversity and Ecosystem.","Pollution, Natural Calamities and Management."]},{"type":"h2","text":"Unit 8: International, National and Current Events of Madhya Pradesh"},{"type":"ul","items":["International Current Events.","National Current Events.","Current Events of Madhya Pradesh."]},{"type":"h2","text":"Unit 9: Information and Communication Technology"},{"type":"ul","items":["Basic Knowledge of Computer.","Electronics, Information and Communication Technology.","Robotics, Artificial Intelligence and Cyber Security.","E-Governance.","Internet and Social Networking Platforms."]},{"type":"h2","text":"Unit 10: Tribes of Madhya Pradesh"},{"type":"ul","items":["The Geographical distribution of the Tribes in Madhya Pradesh, Constitutional Provisions Related to Tribes.","Major Tribes of Madhya Pradesh, Particularly Vulnerable Tribal Groups (PVTG) and Tribal Welfare Programs.","Tribal Culture of Madhya Pradesh: Customs, Traditions, Special Arts Festivals, Dialects and Literature.","Madhya Pradesh Tribals'' Contribution to the Freedom Movement of India and Tribal Personalities of Madhya Pradesh.","Important Institutes, Museums and Publications related to tribes of Madhya Pradesh.","Folk Culture and Literature of Madhya Pradesh."]}],"hi":[{"type":"h2","text":"अवलोकन: MPPSC प्रारंभिक परीक्षा पाठ्यक्रम"},{"type":"p","text":"MPPSC प्रारंभिक परीक्षा में दो वस्तुनिष्ठ प्रकार के प्रश्नपत्र होते हैं: प्रश्नपत्र-I (सामान्य अध्ययन) और प्रश्नपत्र-II (सामान्य अभिरुचि परीक्षण)। नीचे प्रश्नपत्र-I का विस्तृत इकाई-वार विवरण दिया गया है।"},{"type":"h2","text":"इकाई 1: भारत का इतिहास"},{"type":"ul","items":["संकल्पनाएँ और विचार: प्राचीन भारतीय ज्ञान परंपरा, भारतवर्ष, वेद, उपनिषद, आरण्यक, ब्राह्मण ग्रंथ, षड्दर्शन, स्मृतियाँ, ऋत सभा-समिति, गणतंत्र, वर्णाश्रम, पुरुषार्थ, ऋण संस्कार, पंच महायज्ञ/यज्ञ, कर्म का सिद्धांत, बोधिसत्व, तीर्थंकर।","प्राचीन एवं मध्यकालीन भारत की प्रमुख विशेषताएं, घटनाएं और उनकी प्रशासनिक, सामाजिक तथा आर्थिक व्यवस्थाएं।","भारत की सांस्कृतिक विरासत: कला प्रारूप, साहित्य, पर्व और उत्सव।","19वीं और 20वीं शताब्दी में सामाजिक तथा धार्मिक सुधार आंदोलन।","स्वतंत्रता संघर्ष और भारतीय राष्ट्रीय आंदोलन।","स्वतंत्रता के पश्चात भारत का एकीकरण और पुनर्गठन।"]},{"type":"h2","text":"इकाई 2: मध्य प्रदेश का इतिहास, संस्कृति और साहित्य"},{"type":"ul","items":["मध्य प्रदेश के इतिहास की महत्वपूर्ण घटनाएं और प्रमुख राजवंश।","स्वतंत्रता आंदोलन में मध्य प्रदेश का योगदान।","मध्य प्रदेश की प्रमुख कलाएं एवं स्थापत्य कला।","मध्य प्रदेश की प्रमुख जनजातियां एवं बोलियां।","मध्य प्रदेश के प्रमुख त्यौहार, लोक संगीत, लोक कलाएं एवं लोक साहित्य।","मध्य प्रदेश के प्रमुख साहित्यकार एवं उनकी कृतियां।","मध्य प्रदेश के प्रमुख धार्मिक, सांस्कृतिक एवं पुरातात्विक पर्यटन स्थल।","मध्य प्रदेश में विश्व धरोहर स्थल।","मध्य प्रदेश के प्रमुख जनजातीय व्यक्तित्व।"]},{"type":"h2","text":"इकाई 3: भारत का भूगोल"},{"type":"ul","items":["पर्वत, पहाड़ियाँ, पठार, नदियाँ और झीलें।","जलवायु घटनाएं: अल नीनो, ला नीना, दक्षिणी दोलन, पश्चिमी विक्षोभ, जलवायु परिवर्तन के परिणाम।","प्राकृतिक संसाधन: वन, खनिज, जल संसाधन।","प्रमुख फसलें, खाद्य सुरक्षा, हरित क्रांति, दूसरी हरित क्रांति की रणनीतियाँ।","ऊर्जा के पारंपरिक और गैर-पारंपरिक स्रोत।","भारत में प्राकृतिक खतरे और आपदाएँ, भारत में प्रमुख चक्रवात।","जनसंख्या वृद्धि, वितरण और घनत्व, ग्रामीण-शहरी प्रवास।"]},{"type":"h2","text":"इकाई 4: मध्य प्रदेश का भूगोल"},{"type":"ul","items":["वन, वनोपज, नदियाँ, पहाड़ियाँ और पठार।","जलवायु: ऋतुएँ, तापमान, वर्षा।","प्राकृतिक संसाधन: मिट्टी और प्रमुख खनिज संसाधन।","प्रमुख फसलें, जल संसाधन, सिंचाई और सिंचाई परियोजनाएँ।","ऊर्जा के पारंपरिक और गैर-पारंपरिक स्रोत।","मध्य प्रदेश के प्रमुख उद्योग।","जनसंख्या वृद्धि, वितरण और घनत्व, शहरीकरण।"]},{"type":"h2","text":"इकाई 5: भारत और मध्य प्रदेश की संवैधानिक व्यवस्था"},{"type":"ul","items":["संविधान सभा।","संघीय कार्यपालिका, राष्ट्रपति और संसद।","सर्वोच्च न्यायालय और न्यायिक व्यवस्था।","संवैधानिक संशोधन।","नागरिकों के मौलिक अधिकार और कर्तव्य, राज्य के नीति निदेशक तत्व।","राष्ट्रीय और प्रादेशिक संवैधानिक/सांविधिक आयोग और संस्थाएं।","मध्य प्रदेश की संवैधानिक व्यवस्था (राज्यपाल, मंत्रिमंडल, विधानसभा, उच्च न्यायालय)।","मध्य प्रदेश में त्रि-स्तरीय पंचायती राज और नागरिक प्रशासन व्यवस्था।","मध्य प्रदेश में सुशासन (अभिशासन व्यवस्था)।"]},{"type":"h2","text":"इकाई 6: भारत और मध्य प्रदेश की अर्थव्यवस्था"},{"type":"ul","items":["भारतीय अर्थव्यवस्था में मध्य प्रदेश की वर्तमान स्थिति।","मध्य प्रदेश में जनसंख्या और मानवीय संसाधनों का विकास - शिक्षा, स्वास्थ्य और कौशल।","मध्य प्रदेश में सतत विकास लक्ष्यों (SDGs) में प्रगति।","मध्य प्रदेश में कृषि, उद्योग, एमएसएमई (MSME) और अवसंरचना का विकास।","आत्मनिर्भर मध्य प्रदेश, एक जिला एक उत्पाद (ODOP)।","मध्य प्रदेश में बौद्धिक संपदा अधिकारों (IPR) की प्रगति।","भारतीय अर्थव्यवस्था में नवीन प्रवृत्तियां - कृषि, उद्योग और सेवा क्षेत्र।","वित्तीय संस्थाएं - रिज़र्व बैंक, वाणिज्यिक बैंक, सेबी (SEBI), गैर-बैंकिंग वित्तीय संस्थाएं।","भारत की विदेश व्यापार नीतियां - G-20, सार्क (SAARC) और आसियान (ASEAN)।"]},{"type":"h2","text":"इकाई 7: विज्ञान, पर्यावरण और स्वास्थ्य"},{"type":"ul","items":["विज्ञान की प्रमुख शाखाओं का प्रारंभिक ज्ञान।","भारत की प्रमुख वैज्ञानिक उपलब्धियां।","वैज्ञानिक अनुसंधान संस्थान और उनकी उपलब्धियां, उपग्रह एवं अंतरिक्ष प्रौद्योगिकी, अंतरिक्ष विज्ञान के क्षेत्र में भारत की उपलब्धियां।","मानव शरीर की संरचना।","पोषण, आहार, पोषक तत्व और कुपोषण।","आनुवंशिक रोग, सिकल सेल एनीमिया: कारण, प्रभाव, निदान और कार्यक्रम।","स्वास्थ्य नीति और कार्यक्रम, संक्रामक रोग और उनकी रोकथाम तथा स्वास्थ्य सूचक।","सतत विकास की अवधारणा और एसडीजी (SDG)।","पर्यावरणीय कारक, जैव विविधता और पारिस्थितिकी तंत्र।","प्रदूषण, प्राकृतिक आपदाएं और प्रबंधन।"]},{"type":"h2","text":"इकाई 8: अंतर्राष्ट्रीय, राष्ट्रीय और मध्य प्रदेश की समसामयिक घटनाएं"},{"type":"ul","items":["अंतर्राष्ट्रीय समसामयिक घटनाएं।","राष्ट्रीय समसामयिक घटनाएं।","मध्य प्रदेश की समसामयिक घटनाएं।"]},{"type":"h2","text":"इकाई 9: सूचना और संचार प्रौद्योगिकी"},{"type":"ul","items":["कंप्यूटर का आधारभूत ज्ञान।","इलेक्ट्रॉनिक्स, सूचना और संचार प्रौद्योगिकी।","रोबोटिक्स, आर्टिफिशियल इंटेलिजेंस और साइबर सिक्योरिटी।","ई-गवर्नेंस।","इंटरनेट और सोशल नेटवर्किंग प्लेटफॉर्म।"]},{"type":"h2","text":"इकाई 10: मध्य प्रदेश की जनजातियां"},{"type":"ul","items":["मध्य प्रदेश में जनजातियों का भौगोलिक विस्तार, जनजातियों से संबंधित संवैधानिक प्रावधान।","मध्य प्रदेश की प्रमुख जनजातियां, विशेष पिछड़ी जनजातियां (PVTG) और घुमंतू जनजातियां, जनजातियों के कल्याण के लिए योजनाएं।","मध्य प्रदेश की जनजातीय संस्कृति: परंपराएं, विशिष्ट कलाएं, त्यौहार, बोलियां और साहित्य।","मध्य प्रदेश की जनजातियों का भारत के स्वतंत्रता आंदोलन में योगदान और राज्य के प्रमुख जनजातीय व्यक्तित्व।","मध्य प्रदेश में जनजातियों से संबंधित प्रमुख संस्थान, संग्रहालय और प्रकाशन।","मध्य प्रदेश की लोक संस्कृति और लोक साहित्य।"]}]}', 'syllabus', NULL, 10, 1, 1770549336, 1771262538, 'blog', NULL, NULL, 0, 1, 0, 1, 0, 'अवलोकन: MPPSC प्रारंभिक परीक्षा पाठ्यक्रम MPPSC प्रारंभिक परीक्षा में दो वस्तुनिष्ठ प्रकार के प्रश्नपत्र होते हैं: प्रश्नपत्र-I (सामान्य अध्ययन) और प्रश्नपत्र-II (सामान्य अभिरुचि परीक्षण)। नीचे प्रश्न...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('52859be9-5193-41ac-a75a-2cd548faf7a4', 'indian-geography-river-system-mppsc-prelims-2026', 'Indian River System & Drainage Patterns for MPPSC Prelims 2026 | भारत का अपवाह तंत्र', 'Master the Indian Drainage System with mnemonics for river tributaries, origin points, and PYQs. Special focus on Ganga, Godavari, and MP-linked rivers.', '{"hi":[{"type":"h2","text":"MPPSC 2026 के लिए ''भारत का अपवाह तंत्र'' (Drainage System) क्यों महत्वपूर्ण है?"},{"type":"p","text":"MPPSC प्रारंभिक परीक्षा में भूगोल के 10-12 प्रश्नों में से 3-4 प्रश्न निश्चित रूप से ''नदियों'' (Rivers), उनकी सहायक नदियों (Tributaries) और बहुउद्देशीय परियोजनाओं (Projects) से आते हैं। विशेष रूप से वे नदियाँ जो मध्य प्रदेश से जुड़ी हैं (जैसे गंगा और यमुना बेसिन), परीक्षा के लिए ''Hot Topics'' हैं।"},{"type":"highlight","level":"critical","text":"भारत की नदियाँ दो प्रकार की हैं: हिमालयी नदियाँ (सदानीरा - Perennial) और प्रायद्वीपीय नदियाँ (मौसमी - Seasonal)। नर्मदा और ताप्ती ''भ्रंश घाटी'' (Rift Valley) से बहने वाली प्रमुख नदियाँ हैं।","icon":"🌊"},{"type":"h2","text":"1. गंगा नदी तंत्र (Ganga River System)"},{"type":"p","text":"गंगा भारत की सबसे लंबी नदी (2525 किमी) है। MPPSC में अक्सर इसकी ''बाएं'' और ''दाएं'' तट की सहायक नदियाँ पूछी जाती हैं।"},{"type":"mnemonic","topic":"गंगा की बाएं तट की सहायक नदियाँ (Left Bank Tributaries)","trick":"Reliance 3G Ka Maal","visual":"⬅️","explanation":"R - Ramganga (रामगंगा)\n3G - Gomti, Ghaghara, Gandak (गोमती, घाघरा, गंडक)\nK - Kosi (कोसी - बिहार का शोक)\nM - Mahananda (महानंदा)\n(क्रम: पश्चिम से पूर्व की ओर)"},{"type":"fact_card","title":"Quick Fact: गंगा की MP से जुड़ी नदियाँ","facts":["सोन (Son): अमरकंटक से निकलती है, गंगा में दक्षिण से मिलती है।","टोंस (Tons): सिरसा (UP) के पास गंगा में मिलती है।","बेतवा और चंबल: सीधे गंगा में नहीं, बल्कि यमुना (गंगा की सबसे बड़ी सहायक) में मिलती हैं।"],"icon":"📍"},{"type":"h2","text":"2. प्रायद्वीपीय नदियाँ (Peninsular Rivers)"},{"type":"p","text":"दक्षिण भारत की नदियाँ पुरानी और मौसमी हैं। यहाँ गोदावरी और कृष्णा सबसे महत्वपूर्ण हैं।"},{"type":"highlight","level":"important","text":"गोदावरी (1465 किमी): इसे ''दक्षिण गंगा'' या ''बूढ़ी गंगा'' (Old Ganga) कहा जाता है। नासिक (त्र्यंबकेश्वर) से निकलती है।\nकावेरी: इसे ''दक्षिण भारत की गंगा'' (Ganga of the South) कहा जाता है (पवित्रता के कारण)।","icon":"🚩"},{"type":"mnemonic","topic":"कृष्णा नदी की सहायक नदियाँ","trick":"भीम और तुंग ने दूध पीकर कोयना को मूसी नदी में फेंक दिया","visual":"💪","explanation":"भीम - भीमा (Bhima)\nतुंग - तुंगभद्रा (Tungabhadra)\nदूध - दूधगंगा (Dudhganga)\nकोयना - कोयना (Koyna)\nमूसी - मूसी (Musi - हैदराबाद इसी के किनारे है)"},{"type":"h2","text":"पश्चिम की ओर बहने वाली नदियाँ (West Flowing Rivers)"},{"type":"ul","items":["**नर्मदा:** अमरकंटक से निकलती है, खंभात की खाड़ी में गिरती है। (डेल्टा नहीं, एश्चुअरी/Estuary बनाती है)।","**ताप्ती:** मुलताई (बैतूल) से निकलती है।","**माही:** विंध्याचल से निकलती है, कर्क रेखा (Tropic of Cancer) को दो बार काटती है।","**लूनी:** थार मरुस्थल में लुप्त हो जाती है (Landlocked river)।"]},{"type":"pyq","exam":"MPPSC Prelims 2023","year":2023,"question":"निम्नलिखित में से कौन सी नदी यमुना की सहायक नदी नहीं है?","options":["बेतवा","चंबल","केन","रामगंगा"],"correct":"रामगंगा","strategy":"रामगंगा ''गंगा'' की सहायक नदी है, यमुना की नहीं। चंबल, बेतवा, केन (KBC) यमुना की सहायक नदियाँ हैं।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"किस नदी की घाटी ''गहरी खड्ड भूमि'' (Ravines) के लिए विख्यात है?","options":["नर्मदा","सोन","चंबल","ताप्ती"],"correct":"चंबल","strategy":"चंबल के बीहड़ (Chambal Ravines) विश्व प्रसिद्ध हैं। यह अवनालिका अपरदन (Gully Erosion) का परिणाम है।"},{"type":"case_study","title":"केन-बेतवा लिंक परियोजना (Ken-Betwa Link Project)","year":2021,"significance":"भारत की पहली नदी जोड़ो परियोजना","keyPoints":["उद्देश्य: केन नदी (MP) का अधिशेष पानी बेतवा नदी (UP/MP) में भेजना।","लाभान्वित क्षेत्र: बुंदेलखंड (MP के पन्ना, टीकमगढ़, छतरपुर आदि)।","प्रभाव: पन्ना टाइगर रिज़र्व का कुछ हिस्सा जलमग्न होगा।"],"examRelevance":"MPPSC Mains और Prelims के लिए अत्यंत महत्वपूर्ण (Current Affairs + Geography)।"},{"type":"exam_pattern","topic":"Indian Geography Trend Analysis","analysis":"MPPSC में नदियों के प्रश्न कैसे आते हैं?","stats":["सहायक नदियाँ (Tributaries): 50% (कठिन प्रश्न यहीं से बनते हैं)","उद्गम स्थल (Origin): 30%","बाँध/परियोजना (Dams): 20%"],"trend":"अब सीधे प्रश्न कम आ रहे हैं। ''उत्तर से दक्षिण का क्रम'' या ''सहायक नदियों का मिलान'' (Match the Column) वाले प्रश्न बढ़ रहे हैं।"}],"en":[{"type":"h2","text":"Why is ''Indian Drainage System'' Critical for MPPSC 2026?"},{"type":"p","text":"In MPPSC Prelims Geography section, out of 10-12 questions, 3-4 are guaranteed from ''Rivers'', their Tributaries, and Multipurpose Projects. Rivers connecting with Madhya Pradesh (like Ganga and Yamuna basins) are ''Hot Topics''."},{"type":"highlight","level":"critical","text":"Indian rivers are of two types: Himalayan (Perennial) and Peninsular (Seasonal). Narmada and Tapti are the major rivers flowing through ''Rift Valleys''.","icon":"🌊"},{"type":"h2","text":"1. Ganga River System"},{"type":"p","text":"Ganga is the longest river in India (2525 km). MPPSC frequently asks about its ''Left'' and ''Right'' bank tributaries."},{"type":"mnemonic","topic":"Ganga Left Bank Tributaries","trick":"Reliance 3G Ka Maal","visual":"⬅️","explanation":"R - Ramganga\n3G - Gomti, Ghaghara, Gandak\nK - Kosi (Sorrow of Bihar)\nM - Mahananda\n(Order: West to East)"},{"type":"fact_card","title":"Quick Fact: Ganga Tributaries Linked to MP","facts":["Son: Originates from Amarkantak, joins Ganga from the South.","Tons: Joins Ganga near Sirsa (UP).","Betwa & Chambal: Do not join Ganga directly; they join Yamuna (Ganga''s largest tributary)."],"icon":"📍"},{"type":"h2","text":"2. Peninsular Rivers"},{"type":"p","text":"Rivers of South India are older and seasonal. Godavari and Krishna are the most significant here."},{"type":"highlight","level":"important","text":"Godavari (1465 km): Known as ''Dakshin Ganga'' or ''Vridha Ganga'' (Old Ganga). Originates from Trimbakeshwar (Nashik).\nKaveri: Known as ''Ganga of the South'' (due to its sacredness).","icon":"🚩"},{"type":"mnemonic","topic":"Tributaries of Krishna River","trick":"Bhima and Tung drank milk and threw Koyna into Musi","visual":"💪","explanation":"Bhima - Bhima River\nTung - Tungabhadra\nMilk - Dudhganga\nKoyna - Koyna River\nMusi - Musi River (Hyderabad is located on its banks)"},{"type":"h2","text":"West Flowing Rivers"},{"type":"ul","items":["**Narmada:** Originates from Amarkantak, drains into Gulf of Khambhat. (Forms Estuary, not Delta).","**Tapti:** Originates from Multai (Betul).","**Mahi:** Originates from Vindhyas, cuts Tropic of Cancer twice.","**Luni:** Disappears in the Thar Desert (Inland drainage)."]},{"type":"pyq","exam":"MPPSC Prelims 2023","year":2023,"question":"Which of the following is NOT a tributary of Yamuna?","options":["Betwa","Chambal","Ken","Ramganga"],"correct":"Ramganga","strategy":"Ramganga is a tributary of ''Ganga'', not Yamuna. Remember KBC (Ken, Betwa, Chambal) are Yamuna tributaries."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which river valley is famous for deep ''Ravines''?","options":["Narmada","Son","Chambal","Tapti"],"correct":"Chambal","strategy":"Chambal Ravines (Beehad) are world-famous. Result of Gully Erosion."},{"type":"case_study","title":"Ken-Betwa Link Project","year":2021,"significance":"India''s first River Interlinking Project","keyPoints":["Objective: Transfer surplus water from Ken (MP) to Betwa (UP/MP).","Beneficiary: Bundelkhand region (Panna, Tikamgarh, Chhatarpur, etc.).","Impact: Part of Panna Tiger Reserve will be submerged."],"examRelevance":"Extremely important for MPPSC Mains & Prelims (Current Affairs + Geography)."},{"type":"exam_pattern","topic":"Indian Geography Trend Analysis","analysis":"How are River questions asked in MPPSC?","stats":["Tributaries: 50% (Most difficult questions come from here)","Origin Points: 30%","Dams/Projects: 20%"],"trend":"Direct questions are decreasing. Expect ''North to South arrangement'' or ''Match the Column'' type questions."}]}', 'geography', NULL, 15, 1, 1770570184, 1770570184, 'blog', NULL, NULL, 1, 0, 0, 1, 0, 'MPPSC 2026 के लिए ''भारत का अपवाह तंत्र'' (Drainage System) क्यों महत्वपूर्ण है? MPPSC प्रारंभिक परीक्षा में भूगोल के 10-12 प्रश्नों में से 3-4 प्रश्न निश्चित रूप से ''नदियों'' (Rivers), उनकी सहायक नदियों...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('eaa72fda-7762-4f45-9f8f-64944b06bad5', 'panchayati-raj-73rd-amendment-mppsc-prelims-2026', 'Panchayati Raj System (73rd Amendment) for MPPSC Prelims 2026 | पंचायती राज व्यवस्था', 'Complete guide to Local Self Government for MPPSC. Includes Committee tricks, Article 243 breakdown, MP-specific facts, and PYQs (2015-2024).', '{"hi":[{"type":"h2","text":"MPPSC 2026 के लिए ''पंचायती राज'' (Panchayati Raj) क्यों अनिवार्य है?"},{"type":"p","text":"मध्य प्रदेश ''पंचायती राज'' लागू करने वाला देश का पहला राज्य था, इसलिए MPPSC के लिए यह ''Home Ground'' टॉपिक है। Prelims में इससे प्रतिवर्ष 3-5 प्रश्न (विशेषकर अनुच्छेद 243 और समितियों से) पूछे जाते हैं। यह टॉपिक Mains के पेपर 2 (Polity) का भी एक बड़ा हिस्सा है।"},{"type":"highlight","level":"critical","text":"24 अप्रैल 1993: 73वां संविधान संशोधन लागू हुआ। इसीलिए 24 अप्रैल को ''राष्ट्रीय पंचायती राज दिवस'' मनाया जाता है।","icon":"📅"},{"type":"h2","text":"1. पंचायती राज का विकास (Evolution & Committees)"},{"type":"p","text":"विभिन्न समितियों ने पंचायती राज को संवैधानिक दर्जा दिलाने में भूमिका निभाई। उनका कालक्रम (Chronology) याद रखना बहुत जरूरी है।"},{"type":"mnemonic","topic":"पंचायती राज समितियाँ (Chronology)","trick":"B.A. Pass G.L. Singhvi","visual":"🎓","explanation":"**B** - Balwant Rai Mehta (1957): त्रि-स्तरीय ढांचा (3-Tier)।\n**A** - Ashok Mehta (1977): द्वि-स्तरीय ढांचा (2-Tier)।\n**G** - G.V.K. Rao (1985): बिना जड़ की घास (Grass without roots)।\n**L** - L.M. Singhvi (1986): संवैधानिक दर्जा (Constitutional Status) की मांग।"},{"type":"h2","text":"2. 73वां संविधान संशोधन अधिनियम, 1992"},{"type":"fact_card","title":"संविधान में बदलाव","facts":["भाग जोड़ा गया: भाग IX (Part 9)","अनुसूची जोड़ी गई: 11वीं अनुसूची (Schedule 11)","विषय: 29 विषय (Subjects) पंचायतों को दिए गए।","अनुच्छेद: 243 से 243-O तक।"],"icon":"📖"},{"type":"h2","text":"महत्वपूर्ण अनुच्छेद (Tricks के साथ)"},{"type":"mnemonic","topic":"Article 243 (A-O) - The Magic Code","trick":"D-I-K (Dadi, Income, Kaun?)","visual":"🗝️","explanation":"**243 D**: **D**epressed/ **D**adi (Reservation) - SC/ST और महिलाओं (33%) का आरक्षण।\n**243 I**: **I**ncome (Finance Commission) - राज्य वित्त आयोग।\n**243 K**: **K**aun Banega Pradhan / **K**aryakram (Election) - राज्य निर्वाचन आयोग।"},{"type":"ul","items":["**अनुच्छेद 243A:** ग्राम सभा (Gram Sabha) - यह लोकतंत्र की सबसे छोटी इकाई है।","**अनुच्छेद 243E:** कार्यकाल (Duration) - 5 वर्ष। (याद रखें: E for Expiry)।","**अनुच्छेद 243G:** शक्तियां (Powers) - (याद रखें: G for Genius/Genie - जिसके पास पावर हो)।"]},{"type":"h2","text":"मध्य प्रदेश विशेष (MP Specific Context)"},{"type":"highlight","level":"important","text":"मध्य प्रदेश पंचायती राज अधिनियम, 1993\n• पारित: 30 दिसंबर 1993\n• लागू: 25 जनवरी 1994 (इसलिए 25 जनवरी को MP में मतदाता दिवस के साथ महत्व दिया जाता है)।","icon":"🦁"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"73वें संविधान संशोधन का अभिपालन करने वाला पहला राज्य कौन सा था?","options":["राजस्थान","मध्य प्रदेश","आंध्र प्रदेश","पंजाब"],"correct":"मध्य प्रदेश","strategy":"राजस्थान (नागौर) में 1959 में शुरुआत हुई थी, लेकिन संवैधानिक संशोधन (73rd Amendment) के बाद लागू करने वाला पहला राज्य MP था।"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"राज्य निर्वाचन आयोग (State Election Commission) का प्रावधान किस अनुच्छेद में है?","options":["243 K","243 L","243 M","243 N"],"correct":"243 K","strategy":"चुनाव (Election) मतलब ''K'' (Kaun jitega?) -> Article 243K."},{"type":"exam_pattern","topic":"Panchayati Raj Trend","analysis":"MPPSC Prelims में इस टॉपिक से प्रश्न कहां से आते हैं?","stats":["अनुच्छेद (विशेषकर 243K, 243I, 243D): 40%","समितियां (Balwant/Ashok Mehta): 30%","MP विशिष्ट तथ्य (First state, reservation %): 30%"],"trend":"PESA एक्ट (1996) और नगर पालिकाओं (74th Amendment) को भी इसके साथ जोड़कर पढ़ने की सलाह दी जाती है।"}],"en":[{"type":"h2","text":"Why is ''Panchayati Raj'' Mandatory for MPPSC 2026?"},{"type":"p","text":"Since Madhya Pradesh was the first state to implement the 73rd Constitutional Amendment, this is a ''Home Ground'' topic for MPPSC. Expect 3-5 questions annually in Prelims (especially on Article 243 and Committees). It also forms a major part of Mains Paper 2 (Polity)."},{"type":"highlight","level":"critical","text":"April 24, 1993: 73rd Amendment came into force. Hence, April 24 is celebrated as ''National Panchayati Raj Day''.","icon":"📅"},{"type":"h2","text":"1. Evolution & Committees"},{"type":"p","text":"Various committees played a role in granting constitutional status to Panchayati Raj. Remembering their chronology is crucial."},{"type":"mnemonic","topic":"Panchayati Raj Committees (Chronology)","trick":"B.A. Pass G.L. Singhvi","visual":"🎓","explanation":"**B** - Balwant Rai Mehta (1957): Recommended 3-Tier structure.\n**A** - Ashok Mehta (1977): Recommended 2-Tier structure.\n**G** - G.V.K. Rao (1985): Called it ''Grass without roots''.\n**L** - L.M. Singhvi (1986): Demanded Constitutional Status."},{"type":"h2","text":"2. 73rd Constitutional Amendment Act, 1992"},{"type":"fact_card","title":"Constitutional Changes","facts":["Part Added: Part IX","Schedule Added: 11th Schedule","Subjects: 29 subjects transferred to Panchayats.","Articles: 243 to 243-O."],"icon":"📖"},{"type":"h2","text":"Crucial Articles (With Memory Tricks)"},{"type":"mnemonic","topic":"Article 243 (A-O) - The Magic Code","trick":"D-I-K (Dadi, Income, Kaun?)","visual":"🗝️","explanation":"**243 D**: **D**epressed Classes/**D**adi (Reservation) - Reservation for SC/ST and Women (33%).\n**243 I**: **I**ncome (Finance Commission) - State Finance Commission.\n**243 K**: **K**aun Banega Pradhan (Who will become Chief?) - State Election Commission."},{"type":"ul","items":["**Article 243A:** Gram Sabha - The smallest unit of democracy.","**Article 243E:** Duration - 5 Years. (Remember: E for Expiry of term).","**Article 243G:** Powers & Authority - (Remember: G for Genie/Genius - who has power)."]},{"type":"h2","text":"Madhya Pradesh Specific Context"},{"type":"highlight","level":"important","text":"Madhya Pradesh Panchayati Raj Act, 1993\n• Passed: December 30, 1993\n• Effective: January 25, 1994 (A key date in MP history).","icon":"🦁"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which was the first state to implement the 73rd Constitutional Amendment?","options":["Rajasthan","Madhya Pradesh","Andhra Pradesh","Punjab"],"correct":"Madhya Pradesh","strategy":"Rajasthan (Nagaur) started Panchayati Raj in 1959, but MP was the first to implement it AFTER the 73rd Amendment Act."},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Which article provides for the State Election Commission?","options":["243 K","243 L","243 M","243 N"],"correct":"243 K","strategy":"Election means ''K'' (Kaun jitega / Who wins?) -> Article 243K."},{"type":"exam_pattern","topic":"Panchayati Raj Trend","analysis":"Where do questions come from in MPPSC Prelims?","stats":["Articles (Especially 243K, 243I, 243D): 40%","Committees (Balwant/Ashok Mehta): 30%","MP Specific Facts (First state, reservation %): 30%"],"trend":"It is advisable to study PESA Act (1996) and Municipalities (74th Amendment) alongside this topic."}]}', 'polity', NULL, 14, 1, 1770570530, 1770570530, 'blog', NULL, NULL, 1, 0, 0, 1, 0, 'MPPSC 2026 के लिए ''पंचायती राज'' (Panchayati Raj) क्यों अनिवार्य है? मध्य प्रदेश ''पंचायती राज'' लागू करने वाला देश का पहला राज्य था, इसलिए MPPSC के लिए यह ''Home Ground'' टॉपिक है। Prelims में इससे प्रतिव...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('ca800728-4a5c-40c9-ac60-5ed7f66eb942', 'unit-10-tribes-madhya-pradesh-geography-constitution', 'Unit 10: Tribes of Madhya Pradesh - Geography & Constitution | म.प्र. की जनजातियां', 'Complete breakdown of MPPSC Unit 10. Covers geographical distribution of Bhil, Gond, Baiga, etc., and key Constitutional Articles (330, 332, 338A) with memory tricks.', '{"hi":[{"type":"h2","text":"Unit 10: MPPSC का ''गेम चेंजर'' - म.प्र. की जनजातियां"},{"type":"p","text":"MPPSC के नए सिलेबस में ''Unit 10'' पूरी तरह से जनजातियों (Tribes) को समर्पित है। मध्य प्रदेश को ''जनजातीय प्रदेश'' (Tribal State) कहा जाता है क्योंकि यहाँ देश की सर्वाधिक जनजातीय जनसंख्या निवास करती है।"},{"type":"highlight","level":"critical","text":"जनगणना 2011 के अनुसार:\nMP की ST जनसंख्या: 1.53 करोड़\nप्रतिशत: 21.1% (राज्य की कुल जनसंख्या का)\nभारत में स्थान: प्रथम (1st Rank)","icon":"📊"},{"type":"h2","text":"1. जनजातियों का भौगोलिक वितरण (Geographical Distribution)"},{"type":"p","text":"म.प्र. की जनजातियों को उनकी भौगोलिक स्थिति के आधार पर 4 प्रमुख क्षेत्रों में बांटा जा सकता है। इसे याद रखने के लिए ''दिशाओं'' (Directions) का प्रयोग करें।"},{"type":"mnemonic","topic":"MP Tribal Map Trick","trick":"The ''BSG'' Triangle (भील-सहरिया-गोंड)","visual":"🗺️","explanation":"पश्चिम (West): **B**hil (भील) - मालवा और निमाड़ (झाबुआ, अलीराजपुर)।\nउत्तर (North): **S**ahariya (सहरिया) - ग्वालियर, शिवपुरी, श्योपुर।\nदक्षिण-पूर्व (South-East): **G**ond (गोंड) - सतपुड़ा और बघेलखंड (मंडला, बालाघाट)।"},"",{"type":"ul","items":["**भील (Bhil):** MP की सबसे बड़ी जनजाति। (क्षेत्र: पश्चिमी MP)।","**गोंड (Gond):** भौगोलिक रूप से सबसे विस्तृत (Most widespread) समूह। (क्षेत्र: नर्मदा घाटी, सतपुड़ा)।","**भारिया (Bharia):** पातालकोट (छिंदवाड़ा) के ''जंगलियों के भी जंगली''।","**कोरकू (Korku):** बैतूल, होशंगाबाद (सतपुड़ा क्षेत्र)।","**कोल (Kol):** रीवा, सीधी (विंध्य क्षेत्र)।"]},{"type":"fact_card","title":"विशेष पिछड़ी जनजातियां (PVTGs)","facts":["MP में 3 PVTGs हैं:","1. बैगा (Baiga) - मैकल पर्वत (मंडला/डिंडोरी)","2. भारिया (Bharia) - पातालकोट (छिंदवाड़ा)","3. सहरिया (Sahariya) - चंबल क्षेत्र (ग्वालियर/श्योपुर)"],"icon":"⚠️"},"",{"type":"h2","text":"2. जनजातियों से संबंधित संवैधानिक प्रावधान (Constitutional Provisions)"},{"type":"p","text":"संविधान में ''अनुसूचित जनजाति'' (Scheduled Tribe) शब्द का उल्लेख कई अनुच्छेदों में है। MPPSC सीधे अनुच्छेद संख्या पूछता है।"},{"type":"highlight","level":"important","text":"परिभाषा (Definition): अनुच्छेद 366(25)\nपहचान प्रक्रिया (Identification): अनुच्छेद 342 (राष्ट्रपति घोषित करते हैं)","icon":"📜"},{"type":"mnemonic","topic":"ST Reservation Articles","trick":"330 vs 332","visual":"🏛️","explanation":"Article 330: लोकसभा (Lok Sabha) में आरक्षण। (Trick: 30 -> Center/Delhi)।\nArticle 332: विधानसभा (Vidhan Sabha) में आरक्षण। (Trick: 32 -> State/MP)।"},{"type":"ul","items":["**अनुच्छेद 338A:** राष्ट्रीय अनुसूचित जनजाति आयोग (NCST)। (89वें संविधान संशोधन, 2003 द्वारा जोड़ा गया)।","**अनुच्छेद 244(1):** 5वीं अनुसूची (5th Schedule) - MP के अनुसूचित क्षेत्रों का प्रशासन।","**अनुच्छेद 275(1):** केंद्र सरकार द्वारा जनजातीय कल्याण के लिए अनुदान (Grants)।"]},{"type":"h2","text":"Previous Year Questions (PYQs) - अभ्यास"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"''भारिया'' जनजाति मध्य प्रदेश के किस जिले में विशेष रूप से पाई जाती है?","options":["झाबुआ","छिंदवाड़ा (पातालकोट)","मंडला","रीवा"],"correct":"छिंदवाड़ा (पातालकोट)","strategy":"भारिया = भारी (Heavy/Deep). पातालकोट बहुत गहरा है (Deep valley)।"},{"type":"pyq","exam":"MPPSC Prelims 2023","year":2023,"question":"संविधान के किस अनुच्छेद के अंतर्गत ''राष्ट्रीय अनुसूचित जनजाति आयोग'' (NCST) का गठन किया गया है?","options":["अनुच्छेद 338","अनुच्छेद 338A","अनुच्छेद 339","अनुच्छेद 340"],"correct":"अनुच्छेद 338A","strategy":"338 (SC Commission) -> 338A (ST Commission) -> 338B (OBC Commission)। A for Adivasi (ST)।"},{"type":"exam_pattern","topic":"Unit 10 Strategy","analysis":"सिलेबस बदलने के बाद Unit 10 का महत्व:","stats":["प्रश्नों की संख्या: 8-10 प्रश्न (संभावित)","फोकस एरिया: जनजातीय व्यक्तित्व (Tribal Personalities), कला-संस्कृति और योजनाएं।"],"trend":"सिर्फ जिले रटने से काम नहीं चलेगा, अब उनकी उप-जातियां (Sub-castes) और विवाह प्रथाओं (Marriage customs) पर प्रश्न पूछे जा रहे हैं।"}],"en":[{"type":"h2","text":"Unit 10: The ''Game Changer'' of MPPSC - Tribes of Madhya Pradesh"},{"type":"p","text":"In the revised MPPSC syllabus, ''Unit 10'' is entirely dedicated to Tribes. Madhya Pradesh is known as the ''Tribal State'' as it houses the largest tribal population in India."},{"type":"highlight","level":"critical","text":"Census 2011 Data:\nMP ST Population: 1.53 Crore\nPercentage: 21.1% (of MP''s total population)\nRank in India: 1st","icon":"📊"},{"type":"h2","text":"1. Geographical Distribution of Tribes"},{"type":"p","text":"Tribes in MP can be divided into 4 major zones based on geography. Use directions to remember them."},{"type":"mnemonic","topic":"MP Tribal Map Trick","trick":"The ''BSG'' Triangle (Bhil-Sahariya-Gond)","visual":"🗺️","explanation":"West: **B**hil - Malwa & Nimar (Jhabua, Alirajpur).\nNorth: **S**ahariya - Gwalior, Shivpuri, Sheopur.\nSouth-East: **G**ond - Satpura & Baghelkhand (Mandla, Balaghat)."},"",{"type":"ul","items":["**Bhil:** Largest tribe of MP. (Region: Western MP).","**Gond:** Most widely spread group geographically. (Region: Narmada Valley, Satpura).","**Bharia:** Found in Patalkot (Chhindwara).","**Korku:** Betul, Hoshangabad (Satpura region).","**Kol:** Rewa, Sidhi (Vindhya region)."]},{"type":"fact_card","title":"Particularly Vulnerable Tribal Groups (PVTGs)","facts":["MP has 3 PVTGs:","1. Baiga - Maikal Range (Mandla/Dindori)","2. Bharia - Patalkot (Chhindwara)","3. Sahariya - Chambal Region (Gwalior/Sheopur)"],"icon":"⚠️"},"",{"type":"h2","text":"2. Constitutional Provisions Related to Tribes"},{"type":"p","text":"The term ''Scheduled Tribe'' appears in multiple articles. MPPSC asks for direct article numbers."},{"type":"highlight","level":"important","text":"Definition: Article 366(25)\nIdentification Process: Article 342 (Declared by the President)","icon":"📜"},{"type":"mnemonic","topic":"ST Reservation Articles","trick":"330 vs 332","visual":"🏛️","explanation":"Article 330: Reservation in Lok Sabha. (Trick: 30 -> Center/Delhi).\nArticle 332: Reservation in Vidhan Sabha. (Trick: 32 -> State/MP)."},{"type":"ul","items":["**Article 338A:** National Commission for Scheduled Tribes (NCST). (Added by 89th Amendment, 2003).","**Article 244(1):** 5th Schedule - Administration of Scheduled Areas in MP.","**Article 275(1):** Grants from Central Govt for tribal welfare."]},{"type":"h2","text":"Previous Year Questions (PYQs) - Practice"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"The ''Bharia'' tribe is found specially in which district of Madhya Pradesh?","options":["Jhabua","Chhindwara (Patalkot)","Mandla","Rewa"],"correct":"Chhindwara (Patalkot)","strategy":"Bharia = Bhari (Heavy/Deep). Patalkot is a deep valley."},{"type":"pyq","exam":"MPPSC Prelims 2023","year":2023,"question":"Under which Article of the Constitution is the ''National Commission for Scheduled Tribes'' (NCST) constituted?","options":["Article 338","Article 338A","Article 339","Article 340"],"correct":"Article 338A","strategy":"338 (SC Commission) -> 338A (ST Commission) -> 338B (OBC Commission). A for Adivasi (ST)."},{"type":"exam_pattern","topic":"Unit 10 Strategy","analysis":"Importance of Unit 10 after Syllabus Change:","stats":["Number of Questions: 8-10 Questions (Expected)","Focus Areas: Tribal Personalities, Art & Culture, and Schemes."],"trend":"Rote learning districts won''t suffice; questions now focus on Sub-castes and Marriage customs."}]}', 'mp_gk', NULL, 14, 1, 1770570629, 1770570629, 'blog', NULL, NULL, 1, 0, 0, 1, 0, 'Unit 10: MPPSC का ''गेम चेंजर'' - म.प्र. की जनजातियां MPPSC के नए सिलेबस में ''Unit 10'' पूरी तरह से जनजातियों (Tribes) को समर्पित है। मध्य प्रदेश को ''जनजातीय प्रदेश'' (Tribal State) कहा जाता है क्योंकि यह...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('73c960b0-1e78-4892-a0e4-cd32bdaee099', 'sustainable-development-sdg-mppsc-prelims-2026', 'Sustainable Development Goals (SDGs) & Concept | सतत विकास और SDG', 'Crack the SDG topic for MPPSC. Includes Brundtland Commission facts, 17 Goals mnemonic, NITI Aayog Index, and MP-specific performance analysis.', '{"hi":[{"type":"h2","text":"सतत विकास (Sustainable Development) क्या है?"},{"type":"p","text":"सतत विकास का अर्थ है - ''भविष्य की पीढ़ियों की अपनी आवश्यकताओं को पूरा करने की क्षमता से समझौता किए बिना, वर्तमान की आवश्यकताओं को पूरा करना''।"},{"type":"highlight","level":"critical","text":"ब्रंटलैंड रिपोर्ट (1987): इसे ''Our Common Future'' भी कहा जाता है। इसी ने पहली बार ''सतत विकास'' की औपचारिक परिभाषा दी थी।","icon":"🌍"},{"type":"h2","text":"SDG लक्ष्य (2015-2030): एजेंडा 2030"},{"type":"p","text":"संयुक्त राष्ट्र (UN) ने 2015 में 17 लक्ष्य (Goals) और 169 उद्देश्य (Targets) निर्धारित किए, जिन्हें 2030 तक पूरा करना है।"},"",{"type":"mnemonic","topic":"SDG Goals 1-6 (क्रम से याद करें)","trick":"Garib ne Khana khaya, Sehat banayi, Padhai ki, Barabari ki, aur Pani piya","visual":"🍲","explanation":"**Goal 1:** No Poverty (गरीबी - Garibi)\n**Goal 2:** Zero Hunger (भूख - Khana)\n**Goal 3:** Good Health (स्वास्थ्य - Sehat)\n**Goal 4:** Quality Education (शिक्षा - Padhai)\n**Goal 5:** Gender Equality (लैंगिक समानता - Barabari)\n**Goal 6:** Clean Water (साफ पानी - Pani)"},{"type":"fact_card","title":"MP और NITI Aayog SDG इंडिया इंडेक्स","facts":["जारीकर्ता: नीति आयोग (NITI Aayog)।","MP का प्रदर्शन: ''Performer'' श्रेणी में आता है।","MP का मजबूत पक्ष: Goal 15 (Life on Land) - वनों की अधिकता के कारण।","MP का कमजोर पक्ष: Goal 1 (Poverty) और Goal 4 (Education)।"],"icon":"📈"},{"type":"h2","text":"महत्वपूर्ण SDG लक्ष्य (Exam Focus)"},{"type":"ul","items":["**Goal 7:** सस्ती और स्वच्छ ऊर्जा (Affordable and Clean Energy) - सौर ऊर्जा से जुड़ा।","**Goal 13:** जलवायु कार्रवाई (Climate Action) - पेरिस समझौता।","**Goal 16:** शांति और न्याय (Peace, Justice)।"]},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"सौर ऊर्जा (Solar Energy) किस SDG लक्ष्य से संबंधित है?","options":["SDG 5","SDG 7","SDG 9","SDG 11"],"correct":"SDG 7","strategy":"Trick: सप्ताह के 7 दिन हमें ऊर्जा चाहिए -> Goal 7 = Energy."},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"नीति आयोग के SDG इंडिया इंडेक्स 2020-21 में किस राज्य ने शीर्ष स्थान प्राप्त किया?","options":["तमिलनाडु","केरल","हिमाचल प्रदेश","आंध्र प्रदेश"],"correct":"केरल","strategy":"केरल हमेशा स्वास्थ्य और शिक्षा में आगे रहता है, इसलिए SDG में भी टॉप पर है।"},{"type":"exam_pattern","topic":"Environment & SDG Trend","analysis":"MPPSC में पर्यावरण के प्रश्न:","stats":["SDG Goals (Match the column): 1-2 प्रश्न","सम्मेलन (Earth Summit/Paris): 1 प्रश्न","प्रदूषण/जैव विविधता: 2 प्रश्न"],"trend":"अब प्रश्न सीधे ''Goal Number'' और उसके ''विषय'' (Theme) को मिलाने (Matching) के लिए आते हैं।"}],"en":[{"type":"h2","text":"What is Sustainable Development?"},{"type":"p","text":"Sustainable development is defined as ''development that meets the needs of the present without compromising the ability of future generations to meet their own needs''."},{"type":"highlight","level":"critical","text":"Brundtland Report (1987): Also known as ''Our Common Future''. It gave the first formal definition of ''Sustainable Development''.","icon":"🌍"},{"type":"h2","text":"SDG Goals (2015-2030): Agenda 2030"},{"type":"p","text":"The United Nations (UN) adopted 17 Goals and 169 Targets in 2015, to be achieved by 2030."},"",{"type":"mnemonic","topic":"SDG Goals 1-6 (Sequence Trick)","trick":"Poor man ate Food, became Healthy, got Education, Equality, and Water","visual":"🍲","explanation":"**Goal 1:** No Poverty (Poor)\n**Goal 2:** Zero Hunger (Food)\n**Goal 3:** Good Health (Healthy)\n**Goal 4:** Quality Education (Education)\n**Goal 5:** Gender Equality (Equality)\n**Goal 6:** Clean Water (Water)"},{"type":"fact_card","title":"MP & NITI Aayog SDG India Index","facts":["Released by: NITI Aayog.","MP''s Category: Falls in ''Performer'' category.","MP''s Strength: Goal 15 (Life on Land) - Due to high forest cover.","MP''s Weakness: Goal 1 (Poverty) and Goal 4 (Education)."],"icon":"📈"},{"type":"h2","text":"Crucial SDG Goals (Exam Focus)"},{"type":"ul","items":["**Goal 7:** Affordable and Clean Energy - Related to Solar Alliance.","**Goal 13:** Climate Action - Paris Agreement.","**Goal 16:** Peace, Justice and Strong Institutions."]},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Solar Energy is related to which SDG Goal?","options":["SDG 5","SDG 7","SDG 9","SDG 11"],"correct":"SDG 7","strategy":"Trick: We need energy 7 days a week -> Goal 7 = Energy."},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Which state topped the NITI Aayog SDG India Index 2020-21?","options":["Tamil Nadu","Kerala","Himachal Pradesh","Andhra Pradesh"],"correct":"Kerala","strategy":"Kerala consistently leads in Health and Education metrics."},{"type":"exam_pattern","topic":"Environment & SDG Trend","analysis":"Environmental Questions in MPPSC:","stats":["SDG Goals (Match the column): 1-2 questions","Conventions (Earth Summit/Paris): 1 question","Pollution/Biodiversity: 2 questions"],"trend":"Expect ''Match the Column'' questions linking the ''Goal Number'' with its ''Theme''."}]}', 'environment', NULL, 12, 1, 1770570709, 1770570709, 'blog', NULL, NULL, 1, 0, 0, 1, 0, 'सतत विकास (Sustainable Development) क्या है? सतत विकास का अर्थ है - ''भविष्य की पीढ़ियों की अपनी आवश्यकताओं को पूरा करने की क्षमता से समझौता किए बिना, वर्तमान की आवश्यकताओं को पूरा करना''। ब्रंटलैंड रिप...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('71a83e2e-dbcf-4580-b066-c76a7c642ed8', 'bharatvarsha-ancient-knowledge-tradition-unit-1-mppsc', 'Concept of Bharatvarsha & Ancient Indian Knowledge Tradition | भारतवर्ष और प्राचीन भारतीय ज्ञान परंपरा', 'Deep dive into Unit 1''s first topic. Understand the geographical and cultural meaning of Bharatvarsha, Jambudvipa, and the structure of Indian Knowledge System (Vedas/Vedangas).', '{"hi":[{"type":"h2","text":"Unit 1: संकल्पनाएं और विचार (Concepts & Ideas) - शुरुआत यहीं से"},{"type":"p","text":"MPPSC के नए सिलेबस में Unit 1 का पहला टॉपिक ''प्राचीन भारतीय ज्ञान परंपरा'' और ''भारतवर्ष'' है। यह टॉपिक हमें हमारी जड़ों से जोड़ता है और परीक्षा में यहाँ से सीधे 2-3 प्रश्न (परिभाषा या स्रोत आधारित) पूछे जाते हैं।"},{"type":"h2","text":"1. भारतवर्ष की संकल्पना (Concept of Bharatvarsha)"},{"type":"highlight","level":"critical","text":"उत्तरं यत्समुद्रस्य हिमाद्रेश्चैव दक्षिणम् ।\nवर्षं तद् भारतं नाम भारती यत्र संततिः ।।\n(विष्णु पुराण 2.3.1)","icon":"🕉️"},{"type":"p","text":"अर्थात: जो समुद्र के उत्तर में और हिमालय के दक्षिण में स्थित है, वह देश ''भारत'' है और वहाँ की संतान ''भारती'' है। यह श्लोक भारत की भौगोलिक एकता का सबसे पुराना प्रमाण है।"},{"type":"fact_card","title":"नामकरण के स्रोत","facts":["ऋग्वैदिक काल: ''भरत'' जन (कबीले) के नाम पर। (राजा सुदास इसी कुल के थे)।","जैन परंपरा: प्रथम तीर्थंकर ऋषभदेव के पुत्र ''भरत'' के नाम पर।","महाभारत/पुराण: दुष्यंत और शकुंतला के पुत्र ''भरत'' के नाम पर।"],"icon":"📜"},{"type":"h3","text":"जम्बूद्वीप (Jambudvipa)"},{"type":"p","text":"प्राचीन बौद्ध और जैन ग्रंथों में तथा अशोक के अभिलेखों में भारत को ''जम्बूद्वीप'' का हिस्सा माना गया है। ''जम्बू'' का अर्थ है ''जामुन का वृक्ष''।"},{"type":"h2","text":"2. प्राचीन भारतीय ज्ञान परंपरा (Ancient Indian Knowledge Tradition)"},{"type":"p","text":"भारतीय ज्ञान परंपरा दुनिया की सबसे पुरानी और निरंतर जीवित परंपरा है। इसे दो भागों में बांटा जा सकता है: श्रुति (सुना हुआ) और स्मृति (याद किया हुआ)।"},"",{"type":"mnemonic","topic":"वेदांग (6 Vedangas) - वेदों के अंग","trick":"Si-Vya-Ni, Jo-Ka-Chha (शिव्यानी जोकच्छा)","visual":"📚","explanation":"**Si** - Shiksha (शिक्षा) - उच्चरण शास्त्र (Phonetics)\n**Vya** - Vyakaran (व्याकरण) - ग्रामर (Grammar)\n**Ni** - Nirukta (निरुक्त) - शब्द व्युत्पत्ति (Etymology)\n**Jo** - Jyotish (ज्योतिष) - खगोल विज्ञान (Astronomy)\n**Ka** - Kalpa (कल्प) - कर्मकांड (Rituals)\n**Chha** - Chhanda (छंद) - मीटर (Metrics)"},{"type":"table","instruction":"प्रमुख ग्रंथ और उनके उपवेद","head":["वेद","उपवेद","विषय"],"body":[["ऋग्वेद","आयुर्वेद","चिकित्सा (Medicine)"],["यजुर्वेद","धनुर्वेद","युद्ध कला (Archery/Warfare)"],["सामवेद","गंधर्ववेद","संगीत और कला (Music/Art)"],["अथर्ववेद","शिल्पवेद","भवन निर्माण (Architecture)"]]},{"type":"highlight","level":"important","text":"''सत्यमेव जयते'' (Truth Alone Triumphs) मुंडकोपनिषद (Mundaka Upanishad) से लिया गया है।","icon":"🦁"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"वैदिक साहित्य में ''सभा और समिति'' को किस देवता की दो पुत्रियाँ कहा गया है?","options":["इन्द्र","अग्नि","प्रजापति","वरुण"],"correct":"प्रजापति","strategy":"अथर्ववेद में सभा और समिति को प्रजापति की दो पुत्रियाँ कहा गया है। यह प्रश्न राजनीतिक व्यवस्था (Polity) और इतिहास दोनों का है।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"पुराणों की कुल संख्या कितनी है?","options":["16","18","20","24"],"correct":"18","strategy":"18 पुराण और 108 उपनिषद। (याद रखें: 1+8 = 9, जो पूर्णता का अंक है)।"},{"type":"exam_pattern","topic":"Unit 1 Trend","analysis":"सिलेबस में नए टॉपिक जोड़ने का अर्थ:","stats":["वेद/वेदांग: 1 प्रश्न","प्राचीन शब्दावली (Terms): 1-2 प्रश्न","संस्कार/आश्रम व्यवस्था: 1 प्रश्न"],"trend":"अब केवल राजाओं के युद्ध नहीं, बल्कि संस्कृति, दर्शन और विज्ञान (Science & Tech in Ancient India) पर प्रश्न पूछे जाएंगे।"}],"en":[{"type":"h2","text":"Unit 1: Concepts & Ideas - The Foundation"},{"type":"p","text":"The first topic of Unit 1 in the revised MPPSC syllabus is ''Ancient Indian Knowledge Tradition'' and ''Bharatvarsha''. This topic connects us to our roots and is a direct source of 2-3 questions in the exam."},{"type":"h2","text":"1. Concept of Bharatvarsha"},{"type":"highlight","level":"critical","text":"Uttaram yat samudrasya Himadreschaiva dakshinam |\nVarsham tad Bharatam nama Bharati yatra santatihi ||\n(Vishnu Purana 2.3.1)","icon":"🕉️"},{"type":"p","text":"Meaning: The country that lies north of the ocean and south of the snowy mountains (Himalayas) is called ''Bharatam'', and the people there are ''Bharati''. This verse is the oldest proof of India''s geographical unity."},{"type":"fact_card","title":"Origins of the Name","facts":["Rigvedic Era: Named after the ''Bharata'' tribe (King Sudas belonged to this).","Jain Tradition: Named after ''Bharata'', the son of the first Tirthankara Rishabhdeva.","Mahabharata/Puranas: Named after ''Bharata'', the son of Dushyanta and Shakuntala."],"icon":"📜"},{"type":"h3","text":"Jambudvipa"},{"type":"p","text":"In ancient Buddhist and Jain texts, and in Ashoka''s inscriptions, India is considered part of ''Jambudvipa''. ''Jambu'' means the ''Jamun tree'' (Indian Blackberry)."},{"type":"h2","text":"2. Ancient Indian Knowledge Tradition"},{"type":"p","text":"The Indian Knowledge System (IKS) is one of the oldest continuous traditions. It is divided into Sruti (Heard) and Smriti (Remembered)."},"",{"type":"mnemonic","topic":"The 6 Vedangas (Limbs of Veda)","trick":"Si-Vya-Ni, Jo-Ka-Chha","visual":"📚","explanation":"**Si** - Shiksha (Phonetics)\n**Vya** - Vyakaran (Grammar)\n**Ni** - Nirukta (Etymology)\n**Jo** - Jyotish (Astronomy)\n**Ka** - Kalpa (Rituals)\n**Chha** - Chhanda (Metrics)"},{"type":"table","instruction":"Major Texts and their Upavedas","head":["Veda","Upaveda","Subject"],"body":[["Rigveda","Ayurveda","Medicine"],["Yajurveda","Dhanurveda","Archery/Warfare"],["Samaveda","Gandharvaveda","Music & Arts"],["Atharvaveda","Shilpaveda","Architecture"]]},{"type":"highlight","level":"important","text":"''Satyameva Jayate'' (Truth Alone Triumphs) is taken from the Mundaka Upanishad.","icon":"🦁"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"In Vedic literature, ''Sabha and Samiti'' are called the two daughters of which deity?","options":["Indra","Agni","Prajapati","Varuna"],"correct":"Prajapati","strategy":"The Atharvaveda mentions Sabha and Samiti as the two daughters of Prajapati. This covers both Polity and History."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"What is the total number of Puranas?","options":["16","18","20","24"],"correct":"18","strategy":"18 Puranas and 108 Upanishads. (Remember: 1+8 = 9, the number of completeness)."},{"type":"exam_pattern","topic":"Unit 1 Trend","analysis":"Implication of new syllabus topics:","stats":["Vedas/Vedangas: 1 question","Ancient Terminology: 1-2 questions","Sanskaras/Ashram System: 1 question"],"trend":"Questions will now focus on Culture, Philosophy, and Ancient Science, not just political history of kings."}]}', 'history', NULL, 15, 1, 1770611755, 1771008832, 'blog', 'unit_1', 'Concepts and Ideas: Ancient Indian Knowledge Tradition, Bharatvarsha', 1, 0, 1, 1, 0, 'Unit 1: संकल्पनाएं और विचार (Concepts & Ideas) - शुरुआत यहीं से MPPSC के नए सिलेबस में Unit 1 का पहला टॉपिक ''प्राचीन भारतीय ज्ञान परंपरा'' और ''भारतवर्ष'' है। यह टॉपिक हमें हमारी जड़ों से जोड़ता है और पर...', 'common');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('12655416-0edc-4701-b3a2-1af3fdb95d8b', 'vedas-upanishad-shaddarshan-unit-1-mppsc', 'Vedas, Upanishads & Shaddarshan: Master Unit 1 | वेद, उपनिषद और षड्दर्शन', 'Comprehensive guide to Vedic Literature and Indian Philosophy. Tricks to remember Shaddarshan founders, Veda-Upaveda mapping, and key Upanishadic facts for MPPSC 2026.', '{"hi":[{"type":"h2","text":"Unit 1: वैदिक साहित्य और दर्शन - MPPSC का आधार"},{"type":"p","text":"वैदिक साहित्य को ''अपौरुषेय'' (नित्य/ईश्वर कृत) माना जाता है। MPPSC में इस टॉपिक से प्रश्न दो रूपों में आते हैं: तथ्यात्मक (Facts about Vedas) और मिलान वाले (Matching Philosophies)।"},{"type":"highlight","level":"critical","text":"वेदत्रयी (Trayi): ऋग्वेद, यजुर्वेद और सामवेद को मिलाकर ''वेदत्रयी'' कहा जाता है। अथर्ववेद इसमें शामिल नहीं है क्योंकि यह लौकिक विषयों (जादू-टोना, औषधि) से संबंधित है।","icon":"📚"},{"type":"h2","text":"1. चार वेद (The Four Vedas)"},{"type":"ul","items":["**ऋग्वेद (Rigveda):** सबसे प्राचीन। इसमें 10 मंडल और 1028 सूक्त हैं।\n* **तीसरा मंडल:** गायत्री मंत्र (विश्वामित्र द्वारा रचित)।\n* **दसवां मंडल:** पुरुष सूक्त (वर्ण व्यवस्था का प्रथम उल्लेख)।","**सामवेद (Samaveda):** भारतीय संगीत का जनक (Father of Indian Music)। इसमें ''ध्रुपद'' राग का उल्लेख है।","**यजुर्वेद (Yajurveda):** यज्ञ और कर्मकांड। यह गद्य और पद्य दोनों में है (कृष्ण और शुक्ल पक्ष)।","**अथर्ववेद (Atharvaveda):** ब्रह्मवेद। इसमें वशीकरण, जादू-टोना, और आयुर्वेद का वर्णन है।"]},"",{"type":"h2","text":"2. ब्राह्मण, आरण्यक और उपनिषद"},{"type":"p","text":"वेदों को समझने के लिए बाद में ये ग्रंथ लिखे गए। इनका क्रम याद रखें: वेद -> ब्राह्मण -> आरण्यक -> उपनिषद।"},{"type":"table","instruction":"वैदिक साहित्य का वर्गीकरण","head":["ग्रंथ प्रकार","अर्थ","उद्देश्य"],"body":[["ब्राह्मण ग्रंथ","यज्ञ की व्याख्या","वेदों के कठिन मंत्रों को आसान कहानियों में समझाना (जैसे: शतपथ ब्राह्मण)"],["आरण्यक","वन (अरण्य) में पठनीय","रहस्यवाद और दर्शन (कर्मकांड और ज्ञान के बीच का पुल)"],["उपनिषद","गुरु के समीप बैठना","इसे ''वेदांत'' (Vedanta) कहते हैं। आत्मा-परमात्मा का ज्ञान।"]]},{"type":"highlight","level":"important","text":"महत्वपूर्ण उपनिषद तथ्य:\n• सत्यमेव जयते: मुंडकोपनिषद\n• ''अहम ब्रह्मास्मि'': बृहदारण्यक उपनिषद\n• यम-नचिकेता संवाद: कठोपनिषद","icon":"🔥"},{"type":"h2","text":"3. षड्दर्शन (Six Schools of Philosophy)"},{"type":"p","text":"भारतीय दर्शन को 6 आस्तिक धाराओं में बांटा गया है। MPPSC में ''दर्शन'' और उनके ''प्रवर्तक'' (Founder) का मिलान (Match the Column) सबसे कॉमन प्रश्न है।"},{"type":"mnemonic","topic":"षड्दर्शन और उनके रचयिता","trick":"Gautam का Nyay, Kapil की Sankhya, Patanjali का Yoga","visual":"🧘","explanation":"1. **सांख्य (Sankhya):** कपिल मुनि (Kapila) - (Trick: कपिल देव के रन ''संख्या'' में थे)।\n2. **न्याय (Nyaya):** गौतम (Gautama) - (Trick: गौतम बुद्ध न्यायप्रिय थे)।\n3. **योग (Yoga):** पतंजलि (Patanjali)।\n4. **वैशेषिक (Vaisheshika):** कणाद (Kanada) - (Trick: कण-कण / Atom theory)।\n5. **पूर्व मीमांसा (Mimamsa):** जैमिनी (Jaimini)।\n6. **उत्तर मीमांसा (Vedanta):** बादरायण (Badarayana)।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"गायत्री मंत्र (Gayatri Mantra) ऋग्वेद के किस मंडल में उल्लेखित है?","options":["प्रथम मंडल","द्वितीय मंडल","तृतीय मंडल","चतुर्थ मंडल"],"correct":"तृतीय मंडल","strategy":"गायत्री मंत्र में 3 पद होते हैं -> इसलिए मंडल 3। (रचयिता: विश्वामित्र)।"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"न्याय दर्शन (Nyaya Philosophy) के प्रवर्तक कौन थे?","options":["चार्वाक","गौतम","कपिल","जेमिनी"],"correct":"गौतम","strategy":"न्याय हमेशा ''गौतम'' (बुद्धिमान व्यक्ति) ही कर सकता है।"},{"type":"exam_pattern","topic":"Unit 1 Philosophy Trend","analysis":"प्रश्नों का ट्रेंड:","stats":["वेद और उपवेद: 1 प्रश्न","षड्दर्शन (Founders): 1 प्रश्न (निश्चित)","उपनिषद कथन: 1 प्रश्न"],"trend":"अब दर्शन के ''मूल सिद्धांत'' (Core Theory) पर भी प्रश्न आ सकते हैं, जैसे ''सत्कार्यवाद'' किस दर्शन का हिस्सा है? (सांख्य)।"}],"en":[{"type":"h2","text":"Unit 1: Vedic Literature & Philosophy - The Foundation"},{"type":"p","text":"Vedic literature is considered ''Apaurusheya'' (not made by man, eternal). In MPPSC, questions from this topic appear in two forms: Factual (about Vedas) and Matching (Philosophies & Founders)."},{"type":"highlight","level":"critical","text":"Trayi (The Trio): Rigveda, Yajurveda, and Samaveda are collectively called ''Vedatrayi''. Atharvaveda is excluded because it deals with worldly matters (charms/spells) rather than sacrificial rituals.","icon":"📚"},{"type":"h2","text":"1. The Four Vedas"},{"type":"ul","items":["**Rigveda:** Oldest text. Contains 10 Mandals and 1028 Suktas.\n* **3rd Mandal:** Gayatri Mantra (Composed by Vishvamitra).\n* **10th Mandal:** Purusha Sukta (First mention of Varna system).","**Samaveda:** Father of Indian Music. Mentions ''Dhrupad'' Raga.","**Yajurveda:** Book of Rituals. Written in both Prose and Poetry (Krishna & Shukla).","**Atharvaveda:** Book of Magic/Charms. Deals with medicine and daily life problems."]},"",{"type":"h2","text":"2. Brahmanas, Aranyakas & Upanishads"},{"type":"p","text":"These texts were written to explain the Vedas. Remember the order: Vedas -> Brahmanas -> Aranyakas -> Upanishads."},{"type":"table","instruction":"Classification of Vedic Texts","head":["Text Type","Meaning","Purpose"],"body":[["Brahmanas","Explanation of Prayer","Commentaries on Vedas to explain rituals (e.g., Shatapatha Brahmana)."],["Aranyakas","Forest Texts","Philosophy & Mysticism (Bridge between Rituals and Knowledge)."],["Upanishads","Sitting near the Guru","Called ''Vedanta'' (End of Veda). Deals with Soul (Atman) and Brahman."]]},{"type":"highlight","level":"important","text":"Key Upanishad Facts:\n• Satyameva Jayate: Mundaka Upanishad\n• ''Aham Brahmasmi'': Brihadaranyaka Upanishad\n• Yama-Nachiketa Dialogue: Katha Upanishad","icon":"🔥"},{"type":"h2","text":"3. Shaddarshan (Six Schools of Philosophy)"},{"type":"p","text":"Indian philosophy is divided into 6 orthodox schools. ''Match the Column'' between the School and its Founder is the most common MPPSC question."},{"type":"mnemonic","topic":"Shaddarshan & Founders","trick":"Kapila Counts, Kanada Eats Atoms","visual":"🧘","explanation":"1. **Sankhya:** Kapila (Trick: Kapila deals with numbers/evolution).\n2. **Nyaya:** Gautama (Trick: Logic/Reasoning).\n3. **Yoga:** Patanjali.\n4. **Vaisheshika:** Kanada (Trick: ''Kan'' means particle/atom theory).\n5. **Mimamsa (Purva):** Jaimini.\n6. **Vedanta (Uttara):** Badarayana."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"In which Mandal of Rigveda is the Gayatri Mantra mentioned?","options":["First Mandal","Second Mandal","Third Mandal","Fourth Mandal"],"correct":"Third Mandal","strategy":"Gayatri Mantra has 3 padas (feet) -> So Mandal 3. (Author: Vishvamitra)."},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Who was the founder of Nyaya Philosophy?","options":["Charvaka","Gautama","Kapila","Jaimini"],"correct":"Gautama","strategy":"Nyaya (Justice/Logic) requires a wise mind like Gautama."},{"type":"exam_pattern","topic":"Unit 1 Philosophy Trend","analysis":"Question Trend:","stats":["Vedas & Upavedas: 1 question","Shaddarshan (Founders): 1 question (Guaranteed)","Upanishad Quotes: 1 question"],"trend":"Questions are now moving towards ''Core Concepts'', e.g., ''Satkaryavada'' belongs to which philosophy? (Sankhya)."}]}', 'history', NULL, 14, 1, 1770612750, 1771008837, 'blog', 'unit_1', 'Vedas, Upanishad, Aranyaka, Brahman Granth, Shaddarshan', 0, 1, 1, 1, 0, 'Unit 1: वैदिक साहित्य और दर्शन - MPPSC का आधार वैदिक साहित्य को ''अपौरुषेय'' (नित्य/ईश्वर कृत) माना जाता है। MPPSC में इस टॉपिक से प्रश्न दो रूपों में आते हैं: तथ्यात्मक (Facts about Vedas) और मिलान वाल...', 'common');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('1ec1e058-0dec-45ed-8a96-fbc86cd2b1b6', 'smritis-rit-sabha-samiti-unit-1-mppsc', 'Smritis, Rit & Vedic Assemblies (Sabha-Samiti) | स्मृतियाँ, ऋत और सभा-समिति', 'Master the concepts of Vedic Polity (Sabha-Samiti), Cosmic Order (Rit), and Dharmashastras (Smritis). Includes memory tricks for Smriti commentators and PYQs.', '{"hi":[{"type":"h2","text":"Unit 1: वैदिक सामाजिक और राजनीतिक जीवन"},{"type":"p","text":"MPPSC Unit 1 में ''स्मृतियाँ'' (सामाजिक कानून), ''ऋत'' (नैतिक व्यवस्था) और ''सभा-समिति'' (राजनीतिक संस्थाएं) अत्यंत महत्वपूर्ण विषय हैं। यहाँ से प्रश्न प्रायः सीधे तथ्यों (Direct Facts) पर आधारित होते हैं।"},{"type":"h2","text":"1. स्मृतियाँ (Smritis) - हिंदू धर्मशास्त्र"},{"type":"p","text":"वेदों के बाद लिखे गए ग्रंथ जो ''स्मृति'' (याद रखने योग्य) श्रेणी में आते हैं। ये सामाजिक नियम और कानून (Codes of Conduct) बताते हैं।"},{"type":"highlight","level":"critical","text":"मनुस्मृति: सबसे प्राचीन और प्रामाणिक स्मृति। (रचना काल: शुंग काल, 200 BC - 200 AD)।\nयाज्ञवल्क्य स्मृति: गुप्त काल में रचित।","icon":"📜"},{"type":"mnemonic","topic":"मनुस्मृति के टीकाकार (Commentators)","trick":"Man ka GM-KB (मन का GM-KB)","visual":"✍️","explanation":"**G** - Govindraj (गोविंदराज)\n**M** - Medhatithi (मेधातिथि) - सबसे प्रसिद्ध।\n**K** - Kulluka Bhatt (कुल्लूक भट्ट)\n**B** - Bharuchi (भारुचि)"},{"type":"fact_card","title":"प्रमुख स्मृतियाँ और तथ्य","facts":["याज्ञवल्क्य स्मृति: इस पर ''मिताक्षरा'' (विज्ञानेश्वर द्वारा) टीका लिखी गई है, जो हिंदू उत्तराधिकार कानून का आधार है।","नारद स्मृति: इसमें दासों की मुक्ति (Emancipation of Slaves) और नियोग प्रथा का वर्णन है।","विष्णु स्मृति: एकमात्र स्मृति जो गद्य (Prose) में है।"],"icon":"📚"},{"type":"h2","text":"2. ऋत (Rit) - नैतिक व्यवस्था"},{"type":"p","text":"''ऋत'' का अर्थ है - सत्य और अविनाशी ईश्वरीय व्यवस्था। यह ब्रह्मांड का वह नियम है जिससे सूर्य, चंद्रमा और ऋतुएँ संचालित होती हैं।"},"",{"type":"highlight","level":"important","text":"संरक्षक देवता: वरुण (Varuna)\nउपाधि: ऋतस्य गोपा (Ritasya Gopa) - यानी ऋत का रक्षक।","icon":"🌊"},{"type":"h2","text":"3. वैदिक संस्थाएं: सभा और समिति (Sabha & Samiti)"},{"type":"p","text":"ऋग्वैदिक काल में राजा की निरंकुशता पर अंकुश लगाने वाली ये दो मुख्य संस्थाएं थीं।"},{"type":"table","instruction":"सभा बनाम समिति (अंतर)","head":["विशेषता","सभा (Sabha)","समिति (Samiti)"],"body":[["सदस्य","वृद्ध और कुलीन लोग (Elites/Elders)","जनसामान्य (Common People)"],["कार्य","न्यायिक कार्य (Judicial functions)","राजा का चुनाव करना (Election of King)"],["आधुनिक तुलना","राज्यसभा (Upper House)","लोकसभा (Lower House)"],["ऋग्वेद में उल्लेख","8 बार","9 बार"]]},{"type":"fact_card","title":"विदथ (Vidhata)","facts":["यह आर्यों की ''सबसे प्राचीन'' संस्था थी।","इसमें महिलाएं भी भाग लेती थीं।","ऋग्वेद में इसका उल्लेख 122 बार हुआ है (सर्वाधिक)।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"किस वेद में ''सभा'' और ''समिति'' को प्रजापति की दो पुत्रियाँ कहा गया है?","options":["ऋग्वेद","यजुर्वेद","सामवेद","अथर्ववेद"],"correct":"अथर्ववेद","strategy":"अथर्ववेद सबसे बाद का है, तब तक राजा की शक्ति कम हो रही थी, इसलिए प्रजा (प्रजापति) की पुत्रियाँ कहा गया।"},{"type":"pyq","exam":"UPSC / Other State PSC","year":2018,"question":"वैदिक देवता ''वरुण'' को माना जाता था?","options":["अग्नि का देवता","ऋत (नैतिक व्यवस्था) का संरक्षक","युद्ध का देवता","सोम का देवता"],"correct":"ऋत (नैतिक व्यवस्था) का संरक्षक","strategy":"वरुण = जल देवता + नैतिक रक्षक (Moral Keeper)."},{"type":"exam_pattern","topic":"Unit 1 Polity Trend","analysis":"वैदिक राजनीति पर ट्रेंड:","stats":["संस्थाएं (सभा/समिति): 1 प्रश्न (निश्चित)","स्मृति ग्रंथ: 1 प्रश्न (टीकाकार या काल)","शब्दावली (Terminologies): 1 प्रश्न"],"trend":"अब प्रश्न ''विदथ'' और ''गध'' जैसी कम प्रसिद्ध संस्थाओं पर भी आ सकते हैं।"}],"en":[{"type":"h2","text":"Unit 1: Vedic Social & Political Life"},{"type":"p","text":"In MPPSC Unit 1, ''Smritis'' (Social Law), ''Rit'' (Moral Order), and ''Sabha-Samiti'' (Political Assemblies) are high-yield topics. Questions here are generally direct and fact-based."},{"type":"h2","text":"1. Smritis (Dharmashastras)"},{"type":"p","text":"Texts written after Vedas, categorized as ''Smriti'' (That which is remembered). They lay down the social codes of conduct and laws."},{"type":"highlight","level":"critical","text":"Manusmriti: Oldest and most authoritative. (Period: Shunga Period, 200 BC - 200 AD).\nYajnavalkya Smriti: Written during the Gupta Period.","icon":"📜"},{"type":"mnemonic","topic":"Commentators of Manusmriti","trick":"Man ka GM-KB","visual":"✍️","explanation":"**G** - Govindraj\n**M** - Medhatithi (Most famous)\n**K** - Kulluka Bhatt\n**B** - Bharuchi"},{"type":"fact_card","title":"Key Facts on Smritis","facts":["Yajnavalkya Smriti: The commentary ''Mitakshara'' (by Vijnaneshwara) is based on this. It is the basis of Hindu Succession Law.","Narada Smriti: Mentions the ''Emancipation of Slaves'' and Niyoga practice.","Vishnu Smriti: The only Smriti written in Prose."],"icon":"📚"},{"type":"h2","text":"2. Rit (Rta) - Cosmic Moral Order"},{"type":"p","text":"''Rit'' means Truth and the Eternal Order. It is the universal law that regulates the sun, moon, seasons, and moral conduct."},"",{"type":"highlight","level":"important","text":"Guardian Deity: Varuna\nTitle: Ritasya Gopa (Protector of Rit).","icon":"🌊"},{"type":"h2","text":"3. Vedic Assemblies: Sabha & Samiti"},{"type":"p","text":"These were the two main assemblies in the Rigvedic period that checked the King''s autocracy."},{"type":"table","instruction":"Sabha vs Samiti (Difference)","head":["Feature","Sabha","Samiti"],"body":[["Members","Council of Elders/Elites","General Assembly of Common People"],["Function","Judicial functions","Election of the King (Rajan)"],["Modern Analogy","Rajya Sabha (Upper House)","Lok Sabha (Lower House)"],["Rigveda Mentions","8 times","9 times"]]},{"type":"fact_card","title":"Vidhata","facts":["The ''Oldest'' institution of Aryans.","Women also participated in it.","Mentioned 122 times in Rigveda (Maximum)."],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"In which Veda are ''Sabha'' and ''Samiti'' called the two daughters of Prajapati?","options":["Rigveda","Yajurveda","Samaveda","Atharvaveda"],"correct":"Atharvaveda","strategy":"Atharvaveda is the latest Veda. By then, democratic power was declining, linked to Prajapati (Creator)."},{"type":"pyq","exam":"UPSC / Other State PSC","year":2018,"question":"The Vedic deity ''Varuna'' was considered the guardian of?","options":["Fire","Rit (Cosmic Order)","War","Soma"],"correct":"Rit (Cosmic Order)","strategy":"Varuna = Water God + Moral Keeper (Ritasya Gopa)."},{"type":"exam_pattern","topic":"Unit 1 Polity Trend","analysis":"Trend on Vedic Polity:","stats":["Assemblies (Sabha/Samiti): 1 question (Sure shot)","Smritis: 1 question (Commentators or Period)","Terminologies: 1 question"],"trend":"Questions might now shift to lesser-known assemblies like ''Vidhata'' and ''Gana''."}]}', 'history', NULL, 12, 1, 1770834667, 1770834667, 'blog', 'unit_1', 'Smritiyan, Rit, Sabha-Samiti', 1, 0, 0, 1, 0, 'Unit 1: वैदिक सामाजिक और राजनीतिक जीवन MPPSC Unit 1 में ''स्मृतियाँ'' (सामाजिक कानून), ''ऋत'' (नैतिक व्यवस्था) और ''सभा-समिति'' (राजनीतिक संस्थाएं) अत्यंत महत्वपूर्ण विषय हैं। यहाँ से प्रश्न प्रायः सीधे तथ्...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('156ac611-9fc8-45ef-a00f-4467a8922bb8', 'gantantra-republic-ancient-india-unit-1-mppsc', 'Concept of Gantantra (Republic) in Ancient India | प्राचीन भारत में गणतंत्र', 'Explore the roots of Democracy in Ancient India. Study the functioning of Vajji, Malla, and Shakya republics, their administrative structure, and voting methods for MPPSC Unit 1.', '{"hi":[{"type":"h2","text":"Unit 1: प्राचीन भारत में गणतंत्र (Gantantra)"},{"type":"p","text":"अक्सर हम मानते हैं कि लोकतंत्र (Democracy) पश्चिम की देन है, लेकिन भारत में बौद्ध काल (600 BC) में ही सुदृढ़ ''गणतांत्रिक व्यवस्था'' (Republican System) मौजूद थी। MPPSC में महाजनपद काल के ''गणराज्यों'' (Republics) पर विशेष प्रश्न पूछे जाते हैं।"},{"type":"highlight","level":"critical","text":"वैशाली (Vajji संघ): इसे ''दुनिया का पहला गणतंत्र'' (World''s First Republic) माना जाता है। यहाँ लिच्छवि (Lichchhavi) वंश का शासन था।","icon":"🏛️"},{"type":"h2","text":"1. गणतंत्र vs राजतंत्र (Republic vs Monarchy)"},{"type":"p","text":"महाजनपद काल (600 ई.पू.) में दो प्रकार के राज्य थे:"},{"type":"ul","items":["**राजतंत्र (Monarchy):** राजा का बेटा राजा बनता था (वंशानुगत)। उदाहरण: मगध, वत्स, कोसल।","**गणतंत्र (Republic/Gana-Sangha):** राजा का चुनाव ''गण'' (समूह) द्वारा होता था। निर्णय बहुमत से लिए जाते थे। उदाहरण: वज्जि, मल्ल।"]},{"type":"h2","text":"2. प्रमुख प्राचीन गणराज्य (Major Ancient Republics)"},{"type":"mnemonic","topic":"बौद्ध कालीन प्रमुख गणराज्य","trick":"शाक्य-कोलिये, मल्ल-लिच्छवि (Sha-Ko, Ma-Li)","visual":"🤝","explanation":"**Sha** - Shakya (शाक्य) - कपिलवस्तु (बुद्ध इसी कुल के थे)।\n**Ko** - Koliya (कोलिये) - रामग्राम (शाक्यों के पड़ोसी)।\n**Ma** - Malla (मल्ल) - पावा और कुशीनारा (जहाँ बुद्ध और महावीर का महापरिनिर्वाण हुआ)।\n**Li** - Lichchhavi (लिच्छवि) - वैशाली (वज्जि संघ का सबसे शक्तिशाली कुल)।"},{"type":"fact_card","title":"शासन प्रणाली (Administrative System)","facts":["संथागार (Sansthagara): यह वह सभा भवन था जहाँ राजा और प्रमुख लोग बैठक करते थे।","शलाका (Salaka): मतदान (Voting) के लिए लकड़ी की डंडियों (Sticks) का प्रयोग होता था।","गणपूरक (Whip): कोरम (Quorum) पूरा करने वाला अधिकारी।"],"icon":"🗳️"},{"type":"h2","text":"3. कौटिल्य और पाणिनी के विचार"},{"type":"p","text":"कौटिल्य (अर्थशास्त्र) ने गणराज्यों को ''संघरत'' कहा और राजा को सलाह दी कि वे इनमें फूट डालकर (Divide and Rule) इन्हें जीतें, क्योंकि ये अजेय थे। पाणिनी (अष्टाध्यायी) ने इन्हें ''आयुधजीवी संघ'' (जो युद्ध से आजीविका चलाते हैं) कहा है।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"गौतम बुद्ध का संबंध किस गणराज्य (Republic) से था?","options":["लिच्छवि","शाक्य","मल्ल","कुरु"],"correct":"शाक्य","strategy":"बुद्ध के बचपन का नाम सिद्धार्थ था और वे कपिलवस्तु के ''शाक्य'' कुल के राजकुमार थे।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"विश्व का पहला गणतंत्र (First Republic) किसे माना जाता है?","options":["एथेंस","स्पार्टा","वैशाली","पाटलिपुत्र"],"correct":"वैशाली","strategy":"वैशाली (बिहार) के लिच्छवि शासकों ने सबसे पहले गणतंत्र की स्थापना की थी।"},{"type":"exam_pattern","topic":"Ancient Republics Trend","analysis":"Unit 1 में गणतंत्र का महत्व:","stats":["महाजनपद राजधानी: 1 प्रश्न","गणतंत्र/राजा का नाम: 1 प्रश्न","शब्दावली (संथागार): 1 प्रश्न"],"trend":"अब प्रश्न उनकी न्याय व्यवस्था (Judicial System) और मतदान प्रक्रिया (Voting) पर भी पूछे जा सकते हैं।"}],"en":[{"type":"h2","text":"Unit 1: Concept of Gantantra (Republic) in Ancient India"},{"type":"p","text":"We often assume Democracy is a Western gift, but a robust ''Republican System'' existed in India during the Buddhist Era (600 BC). MPPSC frequently asks about these ''Gana-Sanghas'' of the Mahajanapada period."},{"type":"highlight","level":"critical","text":"Vaishali (Vajji Confederacy): Considered the ''World''s First Republic''. It was ruled by the Lichchhavi clan.","icon":"🏛️"},{"type":"h2","text":"1. Republic vs Monarchy"},{"type":"p","text":"Two types of states existed in the Mahajanapada period (600 BC):"},{"type":"ul","items":["**Monarchy (Rajtantra):** Hereditary rule (Son of King becomes King). Examples: Magadha, Vatsa, Kosala.","**Republic (Gantantra/Gana-Sangha):** The King was elected by a ''Gana'' (Group). Decisions were taken by majority vote. Examples: Vajji, Malla."]},{"type":"h2","text":"2. Major Ancient Republics"},{"type":"mnemonic","topic":"Key Republics of Buddhist Era","trick":"Sha-Ko, Ma-Li","visual":"🤝","explanation":"**Sha** - Shakya (Kapilvastu) - Buddha belonged to this clan.\n**Ko** - Koliya (Ramagrama) - Neighbors of Shakyas.\n**Ma** - Malla (Pava & Kushinara) - Where Buddha and Mahavira attained Nirvana.\n**Li** - Lichchhavi (Vaishali) - The most powerful clan of the Vajji confederacy."},{"type":"fact_card","title":"Administrative System","facts":["Sansthagara: The Assembly Hall where the King and elders met.","Salaka: Wooden sticks used for voting.","Ganapuraka (Whip): Officer responsible for ensuring Quorum."],"icon":"🗳️"},{"type":"h2","text":"3. Views of Kautilya and Panini"},{"type":"p","text":"Kautilya (Arthashastra) called republics ''Sanghavritta'' and advised kings to win them over by sowing discord (Divide and Rule), as they were invincible in battle due to unity. Panini (Ashtadhyayi) called them ''Ayudhajivi Sangha'' (Those who live by arms)."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Gautam Buddha belonged to which Republic (Clan)?","options":["Lichchhavi","Shakya","Malla","Kuru"],"correct":"Shakya","strategy":"Buddha''s childhood name was Siddhartha, and he was the prince of the ''Shakya'' clan of Kapilvastu."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"Which is considered the ''First Republic'' of the world?","options":["Athens","Sparta","Vaishali","Pataliputra"],"correct":"Vaishali","strategy":"The Lichchhavi rulers of Vaishali (Bihar) established the first known republican system."},{"type":"exam_pattern","topic":"Ancient Republics Trend","analysis":"Relevance in Unit 1:","stats":["Mahajanapada Capitals: 1 question","Name of Republic/King: 1 question","Terminology (Sansthagara): 1 question"],"trend":"Questions may now focus on their Judicial System and Voting Process (Salaka)."}]}', 'history', NULL, 13, 1, 1770834807, 1770834807, 'blog', 'unit_1', 'Gantantra (Republic)', 1, 0, 0, 1, 0, 'Unit 1: प्राचीन भारत में गणतंत्र (Gantantra) अक्सर हम मानते हैं कि लोकतंत्र (Democracy) पश्चिम की देन है, लेकिन भारत में बौद्ध काल (600 BC) में ही सुदृढ़ ''गणतांत्रिक व्यवस्था'' (Republican System) मौजू...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('e0d5e890-737d-439f-a3d9-bf7795a147df', 'varnashrama-dharma-unit-1-mppsc', 'Varnashrama Dharma: Varna & Ashrama System | वर्णाश्रम धर्म: वर्ण और आश्रम व्यवस्था', 'Comprehensive guide to the Social Structure of Ancient India. Covers the 4 Varnas, 4 Ashramas, Purusharthas, and their origins in Vedic texts. Includes real PYQs from MPPSC & UPPSC.', '{"hi":[{"type":"h2","text":"Unit 1: वर्णाश्रम व्यवस्था - भारतीय समाज का आधार"},{"type":"p","text":"प्राचीन भारतीय सामाजिक संरचना दो स्तंभों पर टिकी थी: **वर्ण** (सामाजिक विभाजन) और **आश्रम** (व्यक्तिगत जीवन के चरण)। MPPSC में अक्सर इनके ''उद्गम'' (Origin) और ''उद्देश्य'' (Purpose) पर प्रश्न पूछे जाते हैं।"},{"type":"highlight","level":"critical","text":"पुरुष सूक्त (ऋग्वेद, 10वां मंडल): वर्ण व्यवस्था का प्रथम लिखित प्रमाण। यहाँ विराट पुरुष के अंगों से चार वर्णों की उत्पत्ति बताई गई है।","icon":"📜"},{"type":"h2","text":"1. वर्ण व्यवस्था (Varna System)"},{"type":"p","text":"''वर्ण'' शब्द का अर्थ है ''रंग'' या ''चुनना'' (वृति/व्यवसाय)। ऋग्वैदिक काल में यह ''कर्म आधारित'' था, जो उत्तर वैदिक काल में ''जन्म आधारित'' (जाति) बन गया।"},"",{"type":"table","instruction":"विराट पुरुष से उत्पत्ति","head":["वर्ण","अंग (Origin)","कार्य (Duty)"],"body":[["ब्राह्मण","मुख (Mouth)","अध्ययन-अध्यापन (Education)"],["क्षत्रिय","भुजाएं (Arms)","रक्षा और प्रशासन (Defense)"],["वैश्य","जंघा (Thighs)","व्यापार और कृषि (Trade)"],["शूद्र","चरण (Feet)","सेवा कार्य (Service)"]]},{"type":"fact_card","title":"द्विज (Dvija) - दो बार जन्म","facts":["प्रथम तीन वर्ण (ब्राह्मण, क्षत्रिय, वैश्य) को ''द्विज'' कहा जाता था।","पहला जन्म: भौतिक जन्म।","दूसरा जन्म: उपनयन संस्कार (शिक्षा आरंभ)।","शूद्रों को उपनयन का अधिकार नहीं था, इसलिए वे ''द्विज'' नहीं थे।"],"icon":"🧵"},{"type":"h2","text":"2. आश्रम व्यवस्था (Ashrama System)"},{"type":"p","text":"मानव जीवन को 100 वर्ष मानकर उसे 4 चरणों (25-25 वर्ष) में बांटा गया था। इसका उद्देश्य ''पुरुषार्थ'' (धर्म, अर्थ, काम, मोक्ष) की प्राप्ति था।"},{"type":"mnemonic","topic":"4 आश्रम और उनके लक्ष्य","trick":"B-G-V-S (ब-ग-व-स)","visual":"🚶","explanation":"1. **B**rahmacharya (ब्रह्मचर्य): 0-25 वर्ष - ज्ञान प्राप्ति (Dharma)।\n2. **G**rihastha (गृहस्थ): 25-50 वर्ष - परिवार और धन (Artha & Kama)। सबसे महत्वपूर्ण आश्रम।\n3. **V**anaprastha (वानप्रस्थ): 50-75 वर्ष - मोह त्याग/वन गमन।\n4. **S**annyasa (संन्यास): 75-100 वर्ष - मोक्ष (Moksha)।"},{"type":"highlight","level":"important","text":"जाबालोपनिषद (Jabala Upanishad): इसमें सबसे पहले चारों आश्रमों का एक साथ उल्लेख मिलता है। (छांदोग्य उपनिषद में केवल 3 आश्रम थे)।","icon":"🕉️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"ऋग्वेद के किस मंडल में ''शूद्र'' शब्द का पहली बार उल्लेख हुआ है?","options":["प्रथम","सप्तम","दशम","नवम"],"correct":"दशम","strategy":"10वें मंडल के ''पुरुष सूक्त'' में चारों वर्णों का वर्णन है।"},{"type":"pyq","exam":"UPPSC Prelims 2016","year":2016,"question":"चारों आश्रमों का सर्वप्रथम उल्लेख किस उपनिषद में मिलता है?","options":["छांदोग्य","जाबालो","वृहदारण्यक","कठोपनिषद"],"correct":"जाबालो","strategy":"Jabala -> ''Ja'' means ''Four'' (in logic/trick) -> 4 Ashramas first mentioned here."},{"type":"pyq","exam":"CGPSC Prelims 2018","year":2018,"question":"भारतीय संस्कृति में ''पुरुषार्थ चतुष्टय'' का सही क्रम क्या है?","options":["धर्म, अर्थ, काम, मोक्ष","अर्थ, काम, धर्म, मोक्ष","मोक्ष, धर्म, अर्थ, काम","काम, अर्थ, धर्म, मोक्ष"],"correct":"धर्म, अर्थ, काम, मोक्ष","strategy":"जीवन की शुरुआत ''धर्म'' (शिक्षा) से होती है और अंत ''मोक्ष'' (मुक्ति) पर। बीच में ''अर्थ'' और ''काम'' आते हैं।"},{"type":"exam_pattern","topic":"Varnashrama Trend","analysis":"Unit 1 Trend:","stats":["वर्ण उत्पत्ति (ऋग्वेद): 1 प्रश्न","आश्रम (उपनिषद): 1 प्रश्न","संस्कार (16 संस्कार): 1 प्रश्न (संबंधित टॉपिक)"],"trend":"अब प्रश्न ''गृहस्थ आश्रम'' के महत्व और ''ऋण'' (पितृ ऋण, ऋषि ऋण) से जोड़कर पूछे जा रहे हैं।"}],"en":[{"type":"h2","text":"Unit 1: Varnashrama System - The Pillar of Indian Society"},{"type":"p","text":"Ancient Indian social structure rested on two pillars: **Varna** (Social Division) and **Ashrama** (Stages of Life). MPPSC often asks about their ''Origin'' and ''Purpose''."},{"type":"highlight","level":"critical","text":"Purusha Sukta (Rigveda, 10th Mandal): The first written evidence of the Varna system. It describes the origin of the four Varnas from the Cosmic Being (Virat Purusha).","icon":"📜"},{"type":"h2","text":"1. Varna System"},{"type":"p","text":"The word ''Varna'' means ''Color'' or ''Choice'' (of occupation). In the Rigvedic period, it was ''Occupation-based'', which became ''Birth-based'' (Caste) in the Later Vedic period."},"",{"type":"table","instruction":"Origin from Virat Purusha","head":["Varna","Origin (Body Part)","Duty"],"body":[["Brahmin","Mouth","Education & Rituals"],["Kshatriya","Arms","Defense & Administration"],["Vaishya","Thighs","Trade & Agriculture"],["Shudra","Feet","Service to others"]]},{"type":"fact_card","title":"Dvija (Twice-Born)","facts":["The first three Varnas (Brahmin, Kshatriya, Vaishya) were called ''Dvija''.","First Birth: Physical birth.","Second Birth: Upanayana Sanskar (Initiation into education).","Shudras were not entitled to Upanayana, hence not ''Dvija''."],"icon":"🧵"},{"type":"h2","text":"2. Ashrama System"},{"type":"p","text":"Human life was assumed to be 100 years and divided into 4 stages (25 years each). The goal was to achieve ''Purusharthas'' (Dharma, Artha, Kama, Moksha)."},{"type":"mnemonic","topic":"4 Ashramas & Goals","trick":"B-G-V-S","visual":"🚶","explanation":"1. **B**rahmacharya: 0-25 yrs - Education (Dharma).\n2. **G**rihastha: 25-50 yrs - Family & Wealth (Artha & Kama). The most important stage.\n3. **V**anaprastha: 50-75 yrs - Detachment/Retirement.\n4. **S**annyasa: 75-100 yrs - Renunciation (Moksha)."},{"type":"highlight","level":"important","text":"Jabala Upanishad: The first text to mention all four Ashramas together. (Chandogya Upanishad mentioned only 3).","icon":"🕉️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"In which Mandal of Rigveda is the word ''Shudra'' mentioned for the first time?","options":["First","Seventh","Tenth","Ninth"],"correct":"Tenth","strategy":"The ''Purusha Sukta'' in the 10th Mandal describes all four Varnas."},{"type":"pyq","exam":"UPPSC Prelims 2016","year":2016,"question":"In which Upanishad are all four Ashramas mentioned for the first time?","options":["Chandogya","Jabala","Brihadaranyaka","Katha"],"correct":"Jabala","strategy":"Jabala -> Think ''Ja-Ba-La'' (sounds like ''Sab'' - meaning All). All 4 Ashramas found here."},{"type":"pyq","exam":"CGPSC Prelims 2018","year":2018,"question":"What is the correct order of ''Purushartha Chatushtaya'' in Indian culture?","options":["Dharma, Artha, Kama, Moksha","Artha, Kama, Dharma, Moksha","Moksha, Dharma, Artha, Kama","Kama, Artha, Dharma, Moksha"],"correct":"Dharma, Artha, Kama, Moksha","strategy":"Life starts with ''Dharma'' (Education/Values) and ends with ''Moksha'' (Liberation). Artha (Wealth) and Kama (Desire) are in the middle (Grihastha)."},{"type":"exam_pattern","topic":"Varnashrama Trend","analysis":"Unit 1 Trend:","stats":["Varna Origin (Rigveda): 1 question","Ashrama (Upanishad): 1 question","Sanskaras (16 Sanskaras): 1 question (Related topic)"],"trend":"Questions are now linking Grihastha Ashrama with the concept of ''Rina'' (Debts - Pitra Rina, Rishi Rina)."}]}', 'history', NULL, 14, 1, 1770835019, 1770835019, 'blog', 'unit_1', 'Varnashrama', 1, 0, 0, 1, 0, 'Unit 1: वर्णाश्रम व्यवस्था - भारतीय समाज का आधार प्राचीन भारतीय सामाजिक संरचना दो स्तंभों पर टिकी थी: **वर्ण** (सामाजिक विभाजन) और **आश्रम** (व्यक्तिगत जीवन के चरण)। MPPSC में अक्सर इनके ''उद्गम'' (Orig...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('563ae938-0e5c-42a9-bad0-8b48458eae04', 'purushartha-chatushtaya-unit-1-mppsc', 'Purushartha Chatushtaya: The 4 Goals of Human Life | पुरुषार्थ चतुष्टय', 'Master the concept of Purushartha (Dharma, Artha, Kama, Moksha) for MPPSC Unit 1. Understand the ''Trivarga'' concept, the balance of life goals, and practice real PYQs.', '{"hi":[{"type":"h2","text":"Unit 1: पुरुषार्थ (Purushartha) - मानव जीवन का उद्देश्य"},{"type":"p","text":"भारतीय संस्कृति में मनुष्य के जीवन को सार्थक और संतुलित बनाने के लिए चार लक्ष्यों का निर्धारण किया गया है, जिन्हें ''पुरुषार्थ'' कहा जाता है। ''पुरुष'' का अर्थ है ''आत्मा/मनुष्य'' और ''अर्थ'' का अर्थ है ''प्रयोजन/लक्ष्य''।"},{"type":"highlight","level":"critical","text":"पुरुषार्थों की संख्या 4 है: धर्म, अर्थ, काम और मोक्ष।\nइन्हें संतुलित रूप से प्राप्त करना ही जीवन की सफलता है।","icon":"🎯"},{"type":"h2","text":"1. चार पुरुषार्थ (The Four Goals)"},{"type":"ul","items":["**1. धर्म (Dharma):** यह आधार है। इसका अर्थ है नैतिक कर्तव्य और सामाजिक नियम। यह ''अर्थ'' और ''काम'' को नियंत्रित करता है।","**2. अर्थ (Artha):** भौतिक सुख और धन। जीवन यापन के लिए आवश्यक है। (कौटिल्य के अनुसार: ''अर्थ'' सबसे महत्वपूर्ण है क्योंकि धर्म और काम इसी पर निर्भर हैं)।","**3. काम (Kama):** इच्छाओं और इंद्रिय सुख की पूर्ति। यह मनुष्य की मनोवैज्ञानिक आवश्यकता है।","**4. मोक्ष (Moksha):** यह अंतिम लक्ष्य (Ultimate Goal) है। इसका अर्थ है जन्म-मृत्यु के चक्र से मुक्ति।"]},"",{"type":"fact_card","title":"त्रिवर्ग (Trivarga) क्या है?","facts":["शुरुआती तीन पुरुषार्थों (धर्म, अर्थ, काम) को ''त्रिवर्ग'' कहा जाता है।","मोक्ष को ''त्रिवर्ग'' में शामिल नहीं किया जाता क्योंकि यह निवृत्ति (सांसारिक जीवन का त्याग) का मार्ग है, जबकि बाकी तीन प्रवृत्ति (सांसारिक जीवन) के मार्ग हैं।"],"icon":"🔺"},{"type":"mnemonic","topic":"पुरुषार्थ का सही क्रम","trick":"DAKM (डाक-म)","visual":"📮","explanation":"**D** - Dharma (धर्म) - शुरुआत नियमों से।\n**A** - Artha (अर्थ) - फिर साधन/धन।\n**K** - Kama (काम) - फिर उपभोग/सुख।\n**M** - Moksha (मोक्ष) - अंत में मुक्ति।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"UPPSC Prelims 2020 / MPPSC Set","year":2020,"question":"निम्नलिखित में से कौन ''त्रिवर्ग'' (Trivarga) का हिस्सा नहीं है?","options":["धर्म","अर्थ","काम","मोक्ष"],"correct":"मोक्ष","strategy":"याद रखें: त्रिवर्ग = सांसारिक लक्ष्य (D-A-K)। मोक्ष आध्यात्मिक लक्ष्य है, इसलिए बाहर है।"},{"type":"pyq","exam":"CGPSC Prelims 2015","year":2015,"question":"पुरुषार्थ चतुष्टय का सही क्रम क्या है?","options":["अर्थ, काम, धर्म, मोक्ष","धर्म, अर्थ, काम, मोक्ष","काम, अर्थ, धर्म, मोक्ष","धर्म, काम, मोक्ष, अर्थ"],"correct":"धर्म, अर्थ, काम, मोक्ष","strategy":"धर्म न्यूव है, अर्थ और काम दीवारें हैं, और मोक्ष छत है।"},{"type":"pyq","exam":"RAS/RTS Prelims 2013","year":2013,"question":"किस आश्रम को सभी पुरुषार्थों का केंद्र माना जाता है?","options":["ब्रह्मचर्य","गृहस्थ","वानप्रस्थ","संन्यास"],"correct":"गृहस्थ","strategy":"केवल ''गृहस्थ'' आश्रम में ही व्यक्ति धर्म, अर्थ और काम तीनों का एक साथ सेवन कर सकता है।"},{"type":"exam_pattern","topic":"Purushartha Trend","analysis":"Unit 1 Analysis:","stats":["क्रम (Sequence): 1 प्रश्न","त्रिवर्ग (Concept): 1 प्रश्न"],"trend":"अब प्रश्न दर्शन (Philosophy) से जुड़ रहे हैं, जैसे- ''कौटिल्य ने किस पुरुषार्थ को प्रधानता दी?'' (उत्तर: अर्थ)।"}],"en":[{"type":"h2","text":"Unit 1: Purushartha - The Aim of Human Life"},{"type":"p","text":"Indian culture prescribes four goals to make human life meaningful and balanced, known as ''Purusharthas''. ''Purusha'' means soul/human and ''Artha'' means purpose/goal."},{"type":"highlight","level":"critical","text":"There are 4 Purusharthas: Dharma, Artha, Kama, and Moksha.\nAchieving them in balance is the key to a successful life.","icon":"🎯"},{"type":"h2","text":"1. The Four Goals"},{"type":"ul","items":["**1. Dharma (Righteousness):** The foundation. It means moral duties and social laws. It regulates ''Artha'' and ''Kama''.","**2. Artha (Wealth/Material):** Economic security. Essential for survival. (According to Kautilya: Artha is the most important as Dharma and Kama depend on it).","**3. Kama (Desire):** Fulfillment of desires and sensory pleasures. A psychological need.","**4. Moksha (Liberation):** The Ultimate Goal (Param Purushartha). Liberation from the cycle of birth and death."]},"",{"type":"fact_card","title":"What is Trivarga?","facts":["The first three goals (Dharma, Artha, Kama) are collectively called ''Trivarga''.","Moksha is NOT included in Trivarga because it is the path of Renunciation (Nivritti), while the others are paths of Active Life (Pravritti)."],"icon":"🔺"},{"type":"mnemonic","topic":"Correct Sequence of Purushartha","trick":"DAKM","visual":"📮","explanation":"**D** - Dharma - Start with rules.\n**A** - Artha - Then means/money.\n**K** - Kama - Then enjoyment.\n**M** - Moksha - Finally liberation."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"UPPSC Prelims 2020 / MPPSC Set","year":2020,"question":"Which of the following is NOT a part of ''Trivarga''?","options":["Dharma","Artha","Kama","Moksha"],"correct":"Moksha","strategy":"Remember: Trivarga = Worldly Goals (D-A-K). Moksha is spiritual, so it''s out."},{"type":"pyq","exam":"CGPSC Prelims 2015","year":2015,"question":"What is the correct order of ''Purushartha Chatushtaya''?","options":["Artha, Kama, Dharma, Moksha","Dharma, Artha, Kama, Moksha","Kama, Artha, Dharma, Moksha","Dharma, Kama, Moksha, Artha"],"correct":"Dharma, Artha, Kama, Moksha","strategy":"Dharma is the foundation, Artha and Kama are the walls, Moksha is the roof."},{"type":"pyq","exam":"RAS/RTS Prelims 2013","year":2013,"question":"Which Ashrama is considered the center of all Purusharthas?","options":["Brahmacharya","Grihastha","Vanaprastha","Sannyasa"],"correct":"Grihastha","strategy":"Only in ''Grihastha'' (Householder) Ashrama can a person practice Dharma, Artha, and Kama simultaneously."},{"type":"exam_pattern","topic":"Purushartha Trend","analysis":"Unit 1 Analysis:","stats":["Sequence: 1 question","Trivarga (Concept): 1 question"],"trend":"Questions are now linking to Philosophy, e.g., ''Which Purushartha did Kautilya prioritize?'' (Answer: Artha)."}]}', 'history', NULL, 12, 1, 1770835231, 1770835231, 'blog', 'unit_1', 'Purushartha', 1, 0, 0, 1, 0, 'Unit 1: पुरुषार्थ (Purushartha) - मानव जीवन का उद्देश्य भारतीय संस्कृति में मनुष्य के जीवन को सार्थक और संतुलित बनाने के लिए चार लक्ष्यों का निर्धारण किया गया है, जिन्हें ''पुरुषार्थ'' कहा जाता है। ''पुर...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('061fe634-72c3-4673-a1cc-41ca04a76ec9', 'rina-sanskara-unit-1-mppsc', 'Rina & Sanskaras (16 Sacraments) in Ancient India | ऋण और 16 संस्कार', 'Complete guide to the 3 Debts (Rina) and 16 Sanskaras of Ancient Indian Culture. Includes memory tricks for the sequence of Sanskaras and real PYQs from MPPSC & UPPSC.', '{"hi":[{"type":"h2","text":"Unit 1: ऋण (Debts) और संस्कार (Sacraments)"},{"type":"p","text":"भारतीय संस्कृति में व्यक्ति के जीवन को अनुशासित और पवित्र बनाने के लिए ''संस्कारों'' की व्यवस्था की गई है, जबकि समाज और पूर्वजों के प्रति कर्तव्यों को ''ऋण'' कहा गया है। MPPSC में संस्कारों की संख्या और उनके क्रम (Sequence) पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. तीन ऋण (The Three Debts)"},{"type":"p","text":"वैदिक परंपरा के अनुसार, प्रत्येक मनुष्य जन्म लेते ही 3 ऋणों से बंध जाता है। इन्हें चुकाना जीवन का प्रमुख कर्तव्य है।"},{"type":"table","instruction":"तीन ऋण और उनसे मुक्ति","head":["ऋण","किसका ऋण?","मुक्ति का उपाय (Repayment)"],"body":[["देव ऋण (Deva Rina)","देवताओं का","यज्ञ और पूजा-पाठ करके।"],["ऋषि ऋण (Rishi Rina)","गुरु/ऋषियों का","स्वाध्याय (Self-study) और वेदों का ज्ञान दूसरों को देकर।"],["पितृ ऋण (Pitra Rina)","पूर्वजों/माता-पिता का","संतान उत्पत्ति (Progeny) करके वंश को आगे बढ़ाना।"]]},{"type":"highlight","level":"note","text":"शतपथ ब्राह्मण में मनुष्य जन्म से ही इन 3 ऋणों का ऋणी बताया गया है। कभी-कभी ''मनुष्य ऋण'' (अतिथि सेवा) को चौथा ऋण माना जाता है, लेकिन मुख्य रूप से 3 ही हैं।","icon":"📝"},{"type":"h2","text":"2. सोलह संस्कार (The 16 Sanskaras)"},{"type":"p","text":"संस्कार का अर्थ है ''शुद्धिकरण''। वैसे तो गौतम धर्मसूत्र में 40 संस्कार बताए गए हैं, लेकिन ''मनुस्मृति'' और व्यास स्मृति में 16 संस्कार प्रमुख माने गए हैं (षोडश संस्कार)।"},{"type":"mnemonic","topic":"16 संस्कारों का क्रम (Sequence Trick)","trick":"GPS -> Ja-Na-Ni A-Chu-Ka -> V-U-Ve-Ke-S -> Vivaha-Antyeshti","visual":"👶","explanation":"**जन्म से पूर्व (Pre-birth):**\n1. **G**arbhadhana (गर्भाधान)\n2. **P**umsavana (पुंसवन - पुत्र प्राप्ति)\n3. **S**imantonnayana (सीमंतोन्नयन - गर्भ रक्षा/बाल संवारना)\n\n**बचपन (Childhood):**\n4. **Ja**takarma (जातकर्म - जन्म के तुरंत बाद/शहद चटाना)\n5. **Na**makarana (नामकरण)\n6. **Ni**shkramana (निष्क्रमण - पहली बार बाहर निकलना)\n7. **A**nnaprashana (अन्नप्राशन - ठोस भोजन)\n8. **Chu**dakarana (चूड़ाकर्म/मुंडन)\n9. **Ka**rnavedha (कर्णवेध - कान छेदना)\n\n**शिक्षा (Education):**\n10. **V**idyarambha (विद्यारंभ - अक्षर ज्ञान)\n11. **U**panayana (उपनयन/जनेऊ - सबसे महत्वपूर्ण)\n12. **Ve**darambha (वेदारंभ)\n13. **Ke**shanta (केशांत/गोदान - दाढ़ी बनाना)\n14. **S**amavartana (समावर्तन - दीक्षांत समारोह/Convocation)\n\n**वयस्क (Adult):**\n15. Vivaha (विवाह - गृहस्थ आश्रम का प्रवेश द्वार)\n16. Antyeshti (अंत्येष्टि - अंतिम संस्कार)"},"",{"type":"fact_card","title":"महत्वपूर्ण संस्कार तथ्य","facts":["उपनयन संस्कार: इसे ''यज्ञोपवीत'' भी कहते हैं। इससे बालक को ''द्विज'' (दुबारा जन्म) का दर्जा मिलता है।","समावर्तन संस्कार: गुरुकुल से शिक्षा पूरी करके घर लौटने पर होता है (स्नान)।","अंत्येष्टि: इसे ''श्राद्ध'' या अंतिम संस्कार कहते हैं। यह मृत्यु के बाद होता है।"],"icon":"🔥"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2015 / 2019","year":2015,"question":"हिंदू धर्म में संस्कारों की कुल संख्या कितनी मानी गई है?","options":["12","14","16","18"],"correct":"16","strategy":"षोडश संस्कार (Shodasha Sanskaras) प्रसिद्ध हैं। संख्या 16 याद रखें।"},{"type":"pyq","exam":"UPPSC Prelims 2014","year":2014,"question":"शिक्षा की समाप्ति पर कौन सा संस्कार किया जाता था?","options":["उपनयन","समावर्तन","वेदारंभ","केशांत"],"correct":"समावर्तन","strategy":"समावर्तन का अर्थ है ''लौटना'' (Returning home from Gurukul). यह आधुनिक ''Convocation'' जैसा है।"},{"type":"pyq","exam":"RAS/RTS Prelims 2018","year":2018,"question":"निम्नलिखित में से कौन सा संस्कार जन्म से पूर्व (Pre-birth) किया जाता है?","options":["जातकर्म","नामकरण","पुंसवन","चूड़ाकर्म"],"correct":"पुंसवन","strategy":"जन्म से पहले केवल 3 संस्कार हैं (GPS): गर्भाधान, **पुंसवन**, सीमंतोन्नयन। बाकी जन्म के बाद के हैं।"},{"type":"exam_pattern","topic":"Sanskara Trend","analysis":"Unit 1 Culture Trend:","stats":["संस्कारों की संख्या: 1 प्रश्न","विशिष्ट संस्कार (उपनयन/समावर्तन): 1 प्रश्न","ऋणों का अर्थ: 1 प्रश्न"],"trend":"अब प्रश्न संस्कारों के ''उद्देश्य'' (Purpose) पर पूछे जा रहे हैं, जैसे- ''सीमंतोन्नयन का उद्देश्य क्या है?'' (गर्भवती स्त्री की मानसिक रक्षा)।"}],"en":[{"type":"h2","text":"Unit 1: Rina (Debts) and Sanskaras (Sacraments)"},{"type":"p","text":"Indian culture prescribes ''Sanskaras'' to discipline and purify life, while duties towards society and ancestors are called ''Rina''. In MPPSC, questions on the number and sequence of Sanskaras are common."},{"type":"h2","text":"1. The Three Debts (Tri-Rina)"},{"type":"p","text":"According to Vedic tradition, every human is born with 3 debts. Repaying them is the primary duty of life."},{"type":"table","instruction":"The 3 Debts & Repayment","head":["Debt (Rina)","Owed to?","Method of Repayment"],"body":[["Deva Rina","Gods","By performing Yajna and worship."],["Rishi Rina","Guru/Sages","By Swadhyaya (Self-study) and teaching Vedas."],["Pitra Rina","Ancestors/Parents","By raising Progeny (Children) to continue the lineage."]]},{"type":"highlight","level":"note","text":"The Shatapatha Brahmana mentions that man is born with these 3 debts. Sometimes ''Manushya Rina'' (Service to guests) is considered the 4th, but mainly there are 3.","icon":"📝"},{"type":"h2","text":"2. The 16 Sanskaras (Sacraments)"},{"type":"p","text":"Sanskara means ''Purification''. While Gautama Dharmasutra mentions 40, Manusmriti and Vyasa Smriti standardized them to 16 (Shodasha Sanskaras)."},{"type":"mnemonic","topic":"Sequence of 16 Sanskaras","trick":"GPS -> Ja-Na-Ni A-Chu-Ka -> V-U-Ve-Ke-S -> Vivaha-Antyeshti","visual":"👶","explanation":"**Pre-birth:**\n1. **G**arbhadhana (Conception)\n2. **P**umsavana (Fetus protection/Male child prayer)\n3. **S**imantonnayana (Hair parting of mother)\n\n**Childhood:**\n4. **Ja**takarma (Birth ritual/Honey feeding)\n5. **Na**makarana (Naming)\n6. **Ni**shkramana (First outing)\n7. **A**nnaprashana (First solid food)\n8. **Chu**dakarana (Tonsure/Head shaving)\n9. **Ka**rnavedha (Ear piercing)\n\n**Education:**\n10. **V**idyarambha (Learning alphabets)\n11. **U**panayana (Sacred Thread - Most Important)\n12. **Ve**darambha (Start of Veda study)\n13. **Ke**shanta (First shaving of beard)\n14. **S**amavartana (Convocation/Returning home)\n\n**Adult:**\n15. Vivaha (Marriage)\n16. Antyeshti (Funeral/Last rites)"},"",{"type":"fact_card","title":"Key Sanskara Facts","facts":["Upanayana: Also called ''Yajnopavita''. It grants the status of ''Dvija'' (Twice-born).","Samavartana: Performed when the student returns home from Gurukul (Snana).","Antyeshti: The final sacrifice (Antima Sanskara) performed after death."],"icon":"🔥"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2015 / 2019","year":2015,"question":"What is the total number of Sanskaras in Hindu Dharma?","options":["12","14","16","18"],"correct":"16","strategy":"Shodasha Sanskaras (16) is the standard number in Smritis."},{"type":"pyq","exam":"UPPSC Prelims 2014","year":2014,"question":"Which Sanskara was performed at the end of education?","options":["Upanayana","Samavartana","Vedarambha","Keshanta"],"correct":"Samavartana","strategy":"Samavartana means ''Returning''. It marks the end of Brahmacharya and entry into Grihastha."},{"type":"pyq","exam":"RAS/RTS Prelims 2018","year":2018,"question":"Which of the following Sanskaras is performed before birth?","options":["Jatakarma","Namakarana","Pumsavana","Chudakarana"],"correct":"Pumsavana","strategy":"Only 3 are Pre-birth (GPS): Garbhadhana, **Pumsavana**, Simantonnayana. The rest are post-birth."},{"type":"exam_pattern","topic":"Sanskara Trend","analysis":"Unit 1 Culture Trend:","stats":["Number of Sanskaras: 1 question","Specific Sanskara (Upanayana/Samavartana): 1 question","Meaning of Rinas: 1 question"],"trend":"Questions now focus on the ''Purpose'' of Sanskaras, e.g., ''What is the purpose of Simantonnayana?'' (Mental protection of the pregnant mother)."}]}', 'history', NULL, 15, 1, 1770835236, 1770835236, 'blog', 'unit_1', 'Rina, Sanskara', 1, 0, 0, 1, 0, 'Unit 1: ऋण (Debts) और संस्कार (Sacraments) भारतीय संस्कृति में व्यक्ति के जीवन को अनुशासित और पवित्र बनाने के लिए ''संस्कारों'' की व्यवस्था की गई है, जबकि समाज और पूर्वजों के प्रति कर्तव्यों को ''ऋण'' कहा...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('9f82768e-7699-4ac6-88f0-a87113ad831c', 'panch-mahayajna-unit-1-mppsc', 'Panch Mahayajna: The 5 Great Sacrifices of Ancient India | पंच महायज्ञ', 'Detailed guide to the 5 Daily Duties (Mahayajnas) of a Grihastha in Vedic Culture. Explains Brahma, Deva, Pitra, Manushya, and Bhuta Yajna with memory tricks and PYQs.', '{"hi":[{"type":"h2","text":"Unit 1: पंच महायज्ञ - गृहस्थ के दैनिक कर्तव्य"},{"type":"p","text":"वैदिक संस्कृति में ''गृहस्थ आश्रम'' (Grihastha Ashrama) को सबसे महत्वपूर्ण माना गया है। एक गृहस्थ के लिए प्रतिदिन 5 प्रकार के यज्ञ करना अनिवार्य था, जिन्हें ''पंच महायज्ञ'' कहा जाता है। इनका उद्देश्य जीवन में अनजाने में हुई हिंसा (पाप) का प्रायश्चित करना और ब्रह्मांड के प्रति कृतज्ञता प्रकट करना है।"},{"type":"highlight","level":"critical","text":"शतपथ ब्राह्मण और मनुस्मृति में इनका विस्तार से वर्णन है। ये यज्ञ ''ऋणों'' (3 Debts) से मुक्ति का साधन भी हैं।","icon":"🔥"},"",{"type":"h2","text":"पाँच महायज्ञ (The Five Sacrifices)"},{"type":"mnemonic","topic":"पंच महायज्ञ का क्रम","trick":"B-D-P M-B (Bade Papa Mobile Band karo)","visual":"✋","explanation":"1. **B**rahma Yajna (ब्रह्म यज्ञ) - ऋषियों के लिए।\n2. **D**eva Yajna (देव यज्ञ) - देवताओं के लिए।\n3. **P**itra Yajna (पितृ यज्ञ) - पूर्वजों के लिए।\n4. **M**anushya Yajna (मनुष्य/नृ यज्ञ) - अतिथियों के लिए।\n5. **B**huta Yajna (भूत यज्ञ) - पशु-पक्षियों के लिए।"},{"type":"table","instruction":"महायज्ञ और उनका विवरण","head":["यज्ञ का नाम","किसे समर्पित?","विधि (Procedure)"],"body":[["ब्रह्म यज्ञ (ऋषि यज्ञ)","प्राचीन ऋषि/गुरु","वेदों का अध्ययन (Swadhyaya) और अध्यापन करना।"],["देव यज्ञ","देवता (Gods)","अग्नि में आहुति (Havan) देना।"],["पितृ यज्ञ","पूर्वज (Ancestors)","तर्पण (Tarpana) या श्राद्ध कर्म करना (जल देना)।"],["मनुष्य (नृ) यज्ञ","अतिथि (Guest)","''अतिथि देवो भव'' - भूखे को भोजन कराना।"],["भूत (बलि) यज्ञ","समस्त प्राणी (Animals)","पशु, पक्षी, चींटी, गाय, कुत्ते को भोजन देना।"]]},{"type":"fact_card","title":"पंच सूना (Panch Suna) - 5 पाप","facts":["गृहस्थ के घर में 5 स्थान ऐसे होते हैं जहाँ अनजाने में जीवों की हत्या होती है: ","1. चूल्हा (Hearth), 2. चक्की (Grinding stone), 3. झाड़ू (Broom), 4. ओखली (Pestle), 5. जल का घड़ा (Water pot)।","इन पापों के प्रायश्चित के लिए ही ''पंच महायज्ञ'' किए जाते हैं।"],"icon":"⚠️"},"",{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019 / UPPSC 2017","year":2019,"question":"''अतिथि देवो भव'' की अवधारणा किस महायज्ञ से संबंधित है?","options":["ब्रह्म यज्ञ","देव यज्ञ","मनुष्य (नृ) यज्ञ","भूत यज्ञ"],"correct":"मनुष्य (नृ) यज्ञ","strategy":"मनुष्य यज्ञ का अर्थ ही है अतिथियों की सेवा करना (Serving the guests)।"},{"type":"pyq","exam":"RAS/RTS Prelims 2016","year":2016,"question":"स्वाध्याय (Self-study) और अध्यापन किस यज्ञ का रूप है?","options":["देव यज्ञ","ब्रह्म यज्ञ","पितृ यज्ञ","भूत यज्ञ"],"correct":"ब्रह्म यज्ञ","strategy":"ब्रह्म = ज्ञान/वेद। ऋषियों का ऋण चुकाने के लिए वेदों का पढ़ना-पढ़ाना ''ब्रह्म यज्ञ'' है।"},{"type":"pyq","exam":"UPSC Prelims 2013 (History)","year":2013,"question":"प्राचीन भारत में ''बलि'' (Bali) शब्द का प्रयोग किसके लिए किया जाता था?","options":["एक प्रकार का कर (Tax)","पशु बलि","भूत यज्ञ","उपरोक्त सभी"],"correct":"उपरोक्त सभी","strategy":"ध्यान दें: ''भूत यज्ञ'' को ''बलि वैश्वदेव यज्ञ'' भी कहा जाता है। (मौर्य काल में ''बलि'' एक टैक्स भी था, लेकिन सांस्कृतिक संदर्भ में यह यज्ञ है)।"},{"type":"exam_pattern","topic":"Yajna Trend","analysis":"Unit 1 Culture Trend:","stats":["यज्ञ के प्रकार (Types): 1 प्रश्न","उद्देश्य (Purpose): 1 प्रश्न","शब्दावली (बलि/तर्पण): 1 प्रश्न"],"trend":"MPPSC अब संस्कृति के गहरे पहलुओं (Deep Culture) पर जा रहा है। ''पंच सूना'' (5 Sins) का कांसेप्ट याद रखना जरूरी है।"}],"en":[{"type":"h2","text":"Unit 1: Panch Mahayajna - Daily Duties of a Householder"},{"type":"p","text":"In Vedic culture, the ''Grihastha Ashrama'' (Householder stage) is considered the backbone of society. A householder is required to perform 5 daily sacrifices, known as ''Panch Mahayajna''. These are done to atone for unintentional sins and express gratitude to the cosmos."},{"type":"highlight","level":"critical","text":"Described in detail in Shatapatha Brahmana and Manusmriti. These sacrifices are the means to repay the 3 Debts (Rinas).","icon":"🔥"},"",{"type":"h2","text":"The Five Great Sacrifices"},{"type":"mnemonic","topic":"Sequence of Panch Mahayajna","trick":"B-D-P M-B (Big DP on MB)","visual":"✋","explanation":"1. **B**rahma Yajna - For Rishis/Knowledge.\n2. **D**eva Yajna - For Gods.\n3. **P**itra Yajna - For Ancestors.\n4. **M**anushya (Nri) Yajna - For Guests/Humans.\n5. **B**huta Yajna - For Animals/Nature."},{"type":"table","instruction":"Details of the Sacrifices","head":["Yajna Name","Dedicated to?","Procedure"],"body":[["Brahma Yajna (Rishi Yajna)","Ancient Seers (Rishis)","Study (Swadhyaya) and teaching of Vedas."],["Deva Yajna","Gods (Devas)","Offering oblations into the Fire (Havan/Agnihotra)."],["Pitra Yajna","Ancestors","Offering water (Tarpana) or Shraddha."],["Manushya (Nri) Yajna","Guests","''Atithi Devo Bhava'' - Feeding the hungry/guests."],["Bhuta (Bali) Yajna","All Beings (Animals)","Feeding cows, dogs, crows, ants, etc."]]},{"type":"fact_card","title":"Panch Suna (5 Sins of a Household)","facts":["A householder unknowingly commits violence in 5 places daily:","1. Hearth (Cooking), 2. Grinding Stone, 3. Broom (Sweeping), 4. Pestle & Mortar, 5. Water Pot.","The ''Panch Mahayajnas'' are performed to expiate (cleanse) these sins."],"icon":"⚠️"},"",{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019 / UPPSC 2017","year":2019,"question":"The concept of ''Atithi Devo Bhava'' is related to which Mahayajna?","options":["Brahma Yajna","Deva Yajna","Manushya (Nri) Yajna","Bhuta Yajna"],"correct":"Manushya (Nri) Yajna","strategy":"Manushya Yajna literally means serving men (guests/humanity)."},{"type":"pyq","exam":"RAS/RTS Prelims 2016","year":2016,"question":"Swadhyaya (Self-study) and teaching are forms of which Yajna?","options":["Deva Yajna","Brahma Yajna","Pitra Yajna","Bhuta Yajna"],"correct":"Brahma Yajna","strategy":"Brahma = Knowledge/Vedas. Repaying the debt to Rishis by studying is Brahma Yajna."},{"type":"pyq","exam":"UPSC Prelims 2013 (History)","year":2013,"question":"In Ancient India, the term ''Bali'' was used for?","options":["A type of Tax","Animal Sacrifice","Bhuta Yajna","All of the above"],"correct":"All of the above","strategy":"Note: ''Bhuta Yajna'' is also called ''Bali Vaishvadeva Yajna''. (In Mauryan times, Bali was a tax, but in cultural context, it is this sacrifice)."},{"type":"exam_pattern","topic":"Yajna Trend","analysis":"Unit 1 Culture Trend:","stats":["Types of Yajna: 1 question","Purpose: 1 question","Terminology (Bali/Tarpana): 1 question"],"trend":"MPPSC is digging deeper into cultural aspects. Remembering ''Panch Suna'' (5 Sins) is crucial for advanced preparation."}]}', 'history', NULL, 12, 1, 1770835321, 1770835321, 'blog', 'unit_1', 'Panch Mahayagya/Yagya', 1, 0, 0, 1, 0, 'Unit 1: पंच महायज्ञ - गृहस्थ के दैनिक कर्तव्य वैदिक संस्कृति में ''गृहस्थ आश्रम'' (Grihastha Ashrama) को सबसे महत्वपूर्ण माना गया है। एक गृहस्थ के लिए प्रतिदिन 5 प्रकार के यज्ञ करना अनिवार्य था, जिन्हें...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('8996c9fb-548c-4931-88d9-50ffe99cea27', 'principle-of-karma-unit-1-mppsc', 'Principle of Karma: Types & Philosophy | कर्म का सिद्धांत', 'Deep dive into the Law of Karma for MPPSC Unit 1. Understand Sanchita, Prarabdha, Agami Karma, and the differences between Vedic, Jain, and Buddhist views.', '{"hi":[{"type":"h2","text":"Unit 1: कर्म का सिद्धांत (Principle of Karma)"},{"type":"p","text":"भारतीय दर्शन का केंद्र बिंदु ''कर्म'' है। इसका सरल अर्थ है - ''कार्य-कारण का नियम'' (Law of Cause and Effect)। जैसा बीज बोओगे, वैसा ही फल काटोगे। यह पुनर्जन्म (Rebirth) और मोक्ष (Moksha) की अवधारणा से सीधे जुड़ा है।"},{"type":"highlight","level":"critical","text":"बृहदारण्यक उपनिषद में याज्ञवल्क्य ने सबसे पहले ''कर्म सिद्धांत'' का स्पष्ट प्रतिपादन किया: ''पुण्य कार्य से मनुष्य पुण्यवान और पाप कार्य से पापी बनता है।''","icon":"⚖️"},{"type":"h2","text":"1. कर्म के प्रकार (Types of Karma)"},{"type":"p","text":"शास्त्रों में कर्म को तीन मुख्य श्रेणियों में बांटा गया है। इसे धनुष-बाण के उदाहरण से समझा जाता है।"},"",{"type":"table","instruction":"कर्म के तीन रूप","head":["प्रकार","अर्थ","धनुष-बाण उदाहरण"],"body":[["संचित कर्म (Sanchita)","पूर्व जन्मों के कुल कर्मों का भंडार।","तरकश (Quiver) में रखे हुए बाण।"],["प्रारब्ध कर्म (Prarabdha)","संचित का वह भाग जो इस जीवन में फल दे रहा है (भाग्य)।","धनुष से छूट चुका बाण (इसे बदला नहीं जा सकता)।"],["आगामी/क्रियमाण (Agami)","वर्तमान में किए जा रहे नए कर्म, जिनका फल भविष्य में मिलेगा।","हाथ में लिया गया नया बाण (जिसे हम नियंत्रित कर सकते हैं)।"]]},{"type":"h2","text":"2. निष्काम कर्म (Nishkama Karma)"},{"type":"p","text":"श्रीमद्भगवद्गीता का मुख्य संदेश यही है। इसका अर्थ है - ''फल की आसक्ति के बिना कर्तव्य करना''।"},{"type":"highlight","level":"note","text":"कर्मण्येवाधिकारस्ते मा फलेषु कदाचन। (गीता 2.47)\nअर्थ: तुम्हारा अधिकार केवल कर्म करने में है, उसके फलों में नहीं।","icon":"🕉️"},{"type":"h2","text":"3. जैन और बौद्ध धर्म में कर्म (Comparative View)"},{"type":"ul","items":["**जैन मत:** यहाँ कर्म केवल ''क्रिया'' नहीं, बल्कि ''भौतिक द्रव्य'' (Matter/Pudgala) है। यह धूल की तरह आत्मा से चिपक जाता है और उसे भारी कर देता है। (बंधन)।","**बौद्ध मत:** यहाँ कर्म का अर्थ ''चेतना'' (Intention) है। यदि मन में बुरा भाव नहीं है, तो अनजाने में की गई हिंसा कर्म-बंधन नहीं बनाती।"]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2018 / 2020 (Philosophy)","year":2018,"question":"''निष्काम कर्म'' का सिद्धांत किस ग्रंथ में प्रतिपादित किया गया है?","options":["ईशोपनिषद","भगवद्गीता","रामायण","महाभारत"],"correct":"भगवद्गीता","strategy":"गीता महाभारत का ही भाग है, लेकिन दार्शनिक सिद्धांत के रूप में गीता सटीक उत्तर है।"},{"type":"pyq","exam":"UPPSC / RAS Prelims 2016","year":2016,"question":"जैन दर्शन के अनुसार, कर्म क्या है?","options":["एक विचार","एक अनुष्ठान","एक पुद्गल (भौतिक द्रव्य)","ईश्वर की इच्छा"],"correct":"एक पुद्गल (भौतिक द्रव्य)","strategy":"जैन धर्म में कर्म परमाणु (Atoms) माने गए हैं जो आत्मा को घेर लेते हैं (आस्रव)।"},{"type":"exam_pattern","topic":"Karma Theory Trend","analysis":"Unit 1 Trend:","stats":["निष्काम कर्म (Gita): 1 प्रश्न","जैन कर्मवाद (आस्रव/निर्जरा): 1 प्रश्न","उपनिषद (याज्ञवल्क्य): 1 प्रश्न"],"trend":"अब प्रश्न ''कर्म के प्रकार'' (संचित/प्रारब्ध) और विभिन्न दर्शनों के बीच तुलना (Comparison) पर पूछे जा सकते हैं।"}],"en":[{"type":"h2","text":"Unit 1: Principle of Karma (Law of Action)"},{"type":"p","text":"Karma is the central theme of Indian philosophy. Simply put, it is the ''Law of Cause and Effect''. As you sow, so shall you reap. It is directly linked to the concepts of Rebirth (Samsara) and Liberation (Moksha)."},{"type":"highlight","level":"critical","text":"Yajnavalkya in the Brihadaranyaka Upanishad first clearly articulated the Karma doctrine: ''A man becomes good by good action and bad by bad action.''","icon":"⚖️"},{"type":"h2","text":"1. Types of Karma"},{"type":"p","text":"Scriptures classify Karma into three main categories, often explained using the ''Archer and Arrow'' analogy."},"",{"type":"table","instruction":"The Three Forms of Karma","head":["Type","Meaning","Archer Analogy"],"body":[["Sanchita (Accumulated)","Total sum of past Karmas.","Arrows in the Quiver (Stored)."],["Prarabdha (Fructifying)","Portion of Sanchita ripening in this life (Destiny).","Arrow released from the bow (Cannot be recalled)."],["Agami/Kriyamana (Future)","New actions performed now, bearing fruit later.","New arrow in hand (Under our control)."]]},{"type":"h2","text":"2. Nishkama Karma (Action without Desire)"},{"type":"p","text":"This is the core message of the Shrimad Bhagavad Gita. It means performing one''s duty without attachment to the results."},{"type":"highlight","level":"note","text":"Karmanyevadhikaraste Ma Phaleshu Kadachana. (Gita 2.47)\nMeaning: You have a right to perform your prescribed duty, but you are not entitled to the fruits of action.","icon":"🕉️"},{"type":"h2","text":"3. Karma in Jainism & Buddhism"},{"type":"ul","items":["**Jainism:** Views Karma not just as an act, but as ''Physical Matter'' (Pudgala). It sticks to the soul like dust, making it heavy and binding it.","**Buddhism:** Views Karma as ''Cetana'' (Intention/Will). If the intention is not evil, an unintentional act does not generate bad Karma."]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2018 / 2020 (Philosophy)","year":2018,"question":"In which text is the principle of ''Nishkama Karma'' propounded?","options":["Ishopanishad","Bhagavad Gita","Ramayana","Mahabharata"],"correct":"Bhagavad Gita","strategy":"Though part of Mahabharata, Gita is the specific philosophical text for this concept."},{"type":"pyq","exam":"UPPSC / RAS Prelims 2016","year":2016,"question":"According to Jain philosophy, what is Karma?","options":["A thought","A ritual","A Pudgala (Material substance)","God''s will"],"correct":"A Pudgala (Material substance)","strategy":"Jainism is unique in believing Karma is material atoms that flow into the soul (Asrava)."},{"type":"exam_pattern","topic":"Karma Theory Trend","analysis":"Unit 1 Trend:","stats":["Nishkama Karma (Gita): 1 question","Jain Karma Theory: 1 question","Upanishadic View: 1 question"],"trend":"Questions may now focus on types of Karma (Sanchita/Prarabdha) and comparative philosophy."}]}', 'history', NULL, 12, 1, 1770835357, 1770835357, 'blog', 'unit_1', 'Principle of Karma', 1, 0, 0, 1, 0, 'Unit 1: कर्म का सिद्धांत (Principle of Karma) भारतीय दर्शन का केंद्र बिंदु ''कर्म'' है। इसका सरल अर्थ है - ''कार्य-कारण का नियम'' (Law of Cause and Effect)। जैसा बीज बोओगे, वैसा ही फल काटोगे। यह पुनर्जन्म...', 'common');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('56e5057a-b0e0-4955-ad7a-7218b7cd935d', 'bodhisattva-tirthankara-unit-1-mppsc', 'Bodhisattva & Tirthankara: Concepts & Symbols | बोधिसत्व और तीर्थंकर', 'Master the key figures of Jainism and Buddhism. Learn the symbols of 24 Tirthankaras and the attributes of major Bodhisattvas (Maitreya, Avalokiteshvara) with memory tricks.', '{"hi":[{"type":"h2","text":"Unit 1: बोधिसत्व और तीर्थंकर (धर्म के नायक)"},{"type":"p","text":"MPPSC Unit 1 में जैन और बौद्ध धर्म के दार्शनिक पहलुओं पर विशेष जोर दिया गया है। जहाँ ''तीर्थंकर'' जैन धर्म के सर्वोच्च गुरु हैं, वहीं ''बोधिसत्व'' महायान बौद्ध धर्म का आदर्श है। यहाँ से प्रश्न प्रायः ''प्रतीक चिह्नों'' (Symbols) और ''भविष्य के अवतारों'' पर पूछे जाते हैं।"},{"type":"h2","text":"1. तीर्थंकर (Jain Tirthankaras)"},{"type":"p","text":"''तीर्थंकर'' का अर्थ है - ''घाट (Ford) बनाने वाला''। वह व्यक्ति जो संसार रूपी सागर को पार करने के लिए धर्म का मार्ग (तीर्थ) बनाता है। जैन धर्म में कुल 24 तीर्थंकर हुए हैं।"},{"type":"highlight","level":"critical","text":"ऋषभदेव (आदिनाथ): प्रथम तीर्थंकर। ऋग्वेद में इनका उल्लेख है।\nमहावीर स्वामी: 24वें और अंतिम तीर्थंकर (वास्तविक संस्थापक)।","icon":"v"},"",{"type":"table","instruction":"प्रमुख तीर्थंकर और उनके प्रतीक (Symbols)","head":["क्रम","तीर्थंकर","प्रतीक (Symbol)","विशेषता"],"body":[["1","ऋषभदेव (Rishabhdev)","बैल (Bull)","अयोध्या में जन्म। ऋग्वेद में वर्णन।"],["23","पार्श्वनाथ (Parshvanath)","सर्प फन (Snake)","झारखंड के सम्मेद शिखर पर निर्वाण। ''चातुर्याम'' धर्म दिया।"],["24","महावीर (Mahavira)","सिंह (Lion)","''पंच महाव्रत'' (ब्रह्मचर्य जोड़ा)। जैन धर्म के वास्तविक संस्थापक।"]]},{"type":"mnemonic","topic":"तीर्थंकरों के प्रतीक याद रखने की ट्रिक","trick":"Rishabh का Bull, Ajit का Elephant, Mahavir का Lion, Parshva का Snake","visual":"🦁","explanation":"1. ऋषभ (बैल जैसा बलवान)।\n2. अजितनाथ (अजित = जिसे जीता न जा सके = हाथी)।\n24. महावीर (वीरों का वीर = शेर)।\n23. पार्श्व (सांप का फन)।"},{"type":"h2","text":"2. बोधिसत्व (Bodhisattva)"},{"type":"p","text":"यह ''महायान'' बौद्ध धर्म की संकल्पना है। बोधिसत्व वह व्यक्ति है जिसने ''निर्वाण'' (मोक्ष) प्राप्त करने की योग्यता पा ली है, लेकिन वह दूसरों के दुखों को दूर करने के लिए अपनी मुक्ति को स्थगित (Delay) कर देता है।"},{"type":"fact_card","title":"प्रमुख बोधिसत्व (Key Bodhisattvas)","facts":["अवलोकितेश्वर (Avalokiteshvara): करुणा (Compassion) के प्रतीक। हाथ में कमल (Padmapani) लिए हुए।","मैत्रेय (Maitreya): ''भविष्य के बुद्ध''। अभी तुषित स्वर्ग में हैं, भविष्य में धरती पर आएंगे।","मंजुश्री (Manjushri): प्रज्ञा/बुद्धि (Wisdom) के प्रतीक। हाथ में तलवार (अज्ञान काटने के लिए) और किताब।","वज्रपाणि (Vajrapani): हाथ में वज्र (Thunderbolt)। पाप और असत्य के नाशक।"],"icon":"🪷"},"",{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"जैन धर्म के 23वें तीर्थंकर पार्श्वनाथ का प्रतीक चिह्न क्या है?","options":["सिंह","सर्प","बैल","शंख"],"correct":"सर्प","strategy":"पार्श्वनाथ -> फन वाला सांप (Snake Hood)।"},{"type":"pyq","exam":"UPSC Prelims 2018 / MPPSC Expected","year":2018,"question":"बौद्ध परंपरा के अनुसार, ''भविष्य का बुद्ध'' (Future Buddha) किसे माना जाता है?","options":["अवलोकितेश्वर","लोकेश्वर","मैत्रेय","पद्मपाणि"],"correct":"मैत्रेय","strategy":"मैत्रेय (Maitreya) = मित्र (Friend) जो भविष्य में आएगा।"},{"type":"pyq","exam":"UPPSC Prelims 2016","year":2016,"question":"अजंता की गुफाओं में ''पद्मपाणि बोधिसत्व'' का चित्र किस गुफा संख्या में है?","options":["गुफा संख्या 1","गुफा संख्या 2","गुफा संख्या 9","गुफा संख्या 10"],"correct":"गुफा संख्या 1","strategy":"सबसे प्रसिद्ध चित्र Cave No. 1 में है।"},{"type":"exam_pattern","topic":"Bodhisattva & Tirthankara Trend","analysis":"प्रश्नों का ट्रेंड:","stats":["तीर्थंकर प्रतीक (Symbols): 1 प्रश्न (मैचिंग)","बोधिसत्व के गुण (Attribute): 1 प्रश्न","स्थान (निर्वाण स्थल): 1 प्रश्न"],"trend":"अब प्रश्न केवल नाम नहीं, बल्कि उनकी विशेषताओं (जैसे- अवलोकितेश्वर = करुणा) और मूर्तिकला (Iconography) पर पूछे जा रहे हैं।"}],"en":[{"type":"h2","text":"Unit 1: Bodhisattva & Tirthankara (Spiritual Heroes)"},{"type":"p","text":"Unit 1 emphasizes the philosophical aspects of Jainism and Buddhism. While ''Tirthankara'' is the supreme teacher in Jainism, ''Bodhisattva'' is the ideal in Mahayana Buddhism. Questions often focus on ''Symbols'' and ''Future Incarnations''."},{"type":"h2","text":"1. Jain Tirthankaras"},{"type":"p","text":"''Tirthankara'' means ''Ford-maker''. One who builds a ford/bridge to cross the ocean of suffering (Samsara). There are 24 Tirthankaras in Jainism."},{"type":"highlight","level":"critical","text":"Rishabhdev (Adinath): 1st Tirthankara. Mentioned in Rigveda.\nMahavira Swami: 24th and last Tirthankara (Real Founder).","icon":"v"},"",{"type":"table","instruction":"Major Tirthankaras & Symbols","head":["Order","Tirthankara","Symbol","Key Feature"],"body":[["1st","Rishabhdev","Bull","Born in Ayodhya. Mentioned in Rigveda."],["23rd","Parshvanath","Snake (Serpent)","Nirvana at Sammed Shikhar (Jharkhand). Gave ''Chaturyana''."],["24th","Mahavira","Lion","Added ''Brahmacharya'' (Celibacy). Real founder."]]},{"type":"mnemonic","topic":"Trick to Remember Symbols","trick":"Rishabh''s Bull, Ajit''s Elephant, Mahavir''s Lion, Parshva''s Snake","visual":"🦁","explanation":"1. Rishabh (Strong like a Bull).\n2. Ajitnath (Ajit = Unconquerable = Elephant).\n24. Mahavira (Brave = Lion).\n23. Parshva (Snake hood)."},{"type":"h2","text":"2. Bodhisattva (Buddhism)"},{"type":"p","text":"This is a concept of ''Mahayana'' Buddhism. A Bodhisattva is one who has attained the ability to reach Nirvana (Moksha) but delays it to help suffering beings."},{"type":"fact_card","title":"Key Bodhisattvas","facts":["Avalokiteshvara: Symbol of Compassion. Holds a Lotus (Padmapani).","Maitreya: The ''Future Buddha''. Currently in Tushita Heaven, waiting to descend.","Manjushri: Symbol of Wisdom. Holds a Flaming Sword (to cut ignorance) and a Book.","Vajrapani: Holds a Thunderbolt (Vajra). Protector against evil/sin."],"icon":"🪷"},"",{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"What is the symbol of the 23rd Jain Tirthankara Parshvanath?","options":["Lion","Snake/Serpent","Bull","Conch"],"correct":"Snake/Serpent","strategy":"Parshvanath is always depicted with a Snake hood (Sheshnag) over his head."},{"type":"pyq","exam":"UPSC Prelims 2018 / MPPSC Expected","year":2018,"question":"According to Buddhist tradition, who is considered the ''Future Buddha''?","options":["Avalokiteshvara","Lokeshwara","Maitreya","Padmapani"],"correct":"Maitreya","strategy":"Maitreya = Mitra (Friend) who will come in the future."},{"type":"pyq","exam":"UPPSC Prelims 2016","year":2016,"question":"In which Cave number of Ajanta is the painting of ''Padmapani Bodhisattva'' found?","options":["Cave No. 1","Cave No. 2","Cave No. 9","Cave No. 10"],"correct":"Cave No. 1","strategy":"The most famous painting of Bodhisattva with a Lotus is in Cave 1."},{"type":"exam_pattern","topic":"Bodhisattva & Tirthankara Trend","analysis":"Question Trend:","stats":["Tirthankara Symbols: 1 question (Matching)","Bodhisattva Attributes: 1 question","Place of Nirvana: 1 question"],"trend":"Questions are shifting from mere names to their specific attributes (e.g., Avalokiteshvara = Compassion) and Iconography."}]}', 'history', NULL, 14, 1, 1770835402, 1770835402, 'blog', 'unit_1', 'Bodhisatva, Teerthankar', 1, 0, 0, 1, 0, 'Unit 1: बोधिसत्व और तीर्थंकर (धर्म के नायक) MPPSC Unit 1 में जैन और बौद्ध धर्म के दार्शनिक पहलुओं पर विशेष जोर दिया गया है। जहाँ ''तीर्थंकर'' जैन धर्म के सर्वोच्च गुरु हैं, वहीं ''बोधिसत्व'' महायान बौद्ध ...', 'common');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('3b5c648f-31af-4153-8c85-c520de5d5a47', 'administrative-social-economic-systems-ancient-medieval-india-unit-1', 'Administrative, Social & Economic Systems: Ancient to Medieval India | प्राचीन एवं मध्यकालीन प्रशासनिक व्यवस्था', 'Comprehensive guide to Mauryan Saptanga, Gupta Economy, Chola Local Govt, Delhi Sultanate''s Iqta, and Mughal Mansabdari systems. Includes PYQs and comparative tables.', '{"hi":[{"type":"h2","text":"Unit 1: प्राचीन और मध्यकालीन भारत की प्रशासनिक एवं आर्थिक प्रणालियाँ"},{"type":"p","text":"इतिहास केवल युद्धों की तारीखें नहीं है, बल्कि यह समझने का विषय है कि समाज कैसे चलता था। MPPSC (Prelims & Mains) में ''प्रशासनिक शब्दावली'' (Administrative Terms) और ''कर व्यवस्था'' (Taxation) से सबसे अधिक कठिन प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. प्राचीन भारत: मौर्य और गुप्त प्रशासन"},{"type":"highlight","level":"critical","text":"सप्तांग सिद्धांत (Saptanga Theory): कौटिल्य (चाणक्य) ने ''अर्थशास्त्र'' में राज्य के 7 अंग बताए हैं।","icon":"👑"},{"type":"mnemonic","topic":"सप्तांग सिद्धांत (Kautilya''s 7 Limbs)","trick":"S-A-J-D K-D-M (साजद कदम)","visual":"🏰","explanation":"1. **S**wami (स्वामी) - राजा (King)\n2. **A**matya (अमात्य) - मंत्री (Minister)\n3. **J**anapada (जनपद) - क्षेत्र/जनता (Territory)\n4. **D**urga (दुर्ग) - किला (Fort)\n5. **K**osha (कोष) - खजाना (Treasury)\n6. **D**anda (दंड) - सेना/न्याय (Army/Justice)\n7. **M**itra (मित्र) - सहयोगी (Ally)"},{"type":"fact_card","title":"महत्वपूर्ण मौर्यकालीन अधिकारी","facts":["समाहर्ता (Samaharta): राजस्व संग्रहकर्ता (Collector) - सबसे महत्वपूर्ण पद।","सन्निधाता (Sannidhata): कोषाध्यक्ष (Treasurer)।","सीताध्यक्ष (Sitaadhyaksha): कृषि विभाग का प्रमुख (Sita = राजकीय भूमि)।","लक्षणाध्यक्ष: मुद्रा/टकसाल (Mint) का प्रमुख।"],"icon":"📜"},{"type":"h3","text":"चोल प्रशासन (स्थानीय स्वशासन)"},{"type":"p","text":"दक्षिण भारत का चोल साम्राज्य अपनी ''ग्राम स्वायत्तता'' (Village Autonomy) के लिए प्रसिद्ध था। उर (Ur) और सभा (Sabha) प्रमुख ग्राम सभाएं थीं।"},{"type":"highlight","level":"important","text":"उत्तरमेरूर अभिलेख (Uttaramerur Inscription): इसमें चोलों की ग्राम सभा के चुनाव (Kudavolai System - लॉटरी प्रणाली) का विस्तृत वर्णन है। यह परांतक प्रथम के समय का है।","icon":"🗳️"},{"type":"h2","text":"2. मध्यकालीन भारत: सल्तनत और मुगल व्यवस्था"},{"type":"table","instruction":"इकता बनाम मनसबदारी (Key Differences)","head":["विशेषता","इकता प्रणाली (Iqta System)","मनसबदारी प्रणाली (Mansabdari System)"],"body":[["शुरुआत","इल्तुतमिश (दिल्ली सल्तनत)","अकबर (मुगल काल)"],["प्रकृति","भूमि राजस्व का हस्तांतरण (Land Assignment)","पद/श्रेणी (Rank) + वेतन (नकद या जागीर)"],["वंशानुगत","शुरुआत में नहीं, बाद में फिरोज तुगलक ने इसे वंशानुगत बना दिया।","नहीं (सम्राट की मर्जी पर)।"],["उद्देश्य","दूरदराज के क्षेत्रों से राजस्व वसूलना और सेना रखना।","नागरिक और सैन्य प्रशासन को एक धागे में पिरोना।"]]},{"type":"fact_card","title":"मुगलकालीन आर्थिक शब्दावली","facts":["पोलाज (Polaj): वह भूमि जिस पर हर साल खेती होती थी (सबसे उपजाऊ)।","परती (Parauti): 1-2 साल खाली छोड़ी गई भूमि।","दहसाला (Dahsala): टोडरमल द्वारा शुरू की गई 10 वर्षीय राजस्व प्रणाली (1580)।"],"icon":"🌾"},{"type":"h2","text":"आर्थिक संगठन: श्रेणी (Guilds)"},{"type":"p","text":"प्राचीन भारत में व्यापारियों और कारीगरों के संगठन को ''श्रेणी'' (Shreni) कहा जाता था। इनके अपने कानून होते थे जिन्हें ''श्रेणी धर्म'' कहा जाता था। मंदसौर अभिलेख में ''रेशम बुनकरों की श्रेणी'' का उल्लेख है।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019 / UPSC 2021","year":2019,"question":"किस राजवंश के शासनकाल में ''ग्रामीण प्रशासन'' (Village Administration) अपनी स्वायत्तता के लिए प्रसिद्ध था?","options":["चोल","चालुक्य","पल्लव","राष्ट्रकूट"],"correct":"चोल","strategy":"चोल = Local Self Govt (उत्तरमेरूर अभिलेख)। यह सबसे ''Hit'' प्रश्न है।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"मुगल प्रशासन में ''मुहतसिब'' (Muhtasib) कौन था?","options":["सेना अधिकारी","विदेश विभाग का प्रमुख","लोक आचरण अधिकारी","पत्राचार विभाग का प्रमुख"],"correct":"लोक आचरण अधिकारी","strategy":"मुहतसिब का काम था यह देखना कि लोग शरिया का पालन कर रहे हैं या नहीं (Public Morals)। औरंगजेब ने इनकी नियुक्ति बढ़ाई थी।"},{"type":"pyq","exam":"UPPSC Prelims 2017","year":2017,"question":"मौर्य काल में ''सीता'' (Sita) से क्या तात्पर्य था?","options":["एक देवी","एक धार्मिक संप्रदाय","राजकीय भूमि से प्राप्त आय","बंजर भूमि"],"correct":"राजकीय भूमि से प्राप्त आय","strategy":"सीता का अर्थ है ''हल की रेखा''। मौर्य काल में सरकारी जमीन (Crown Land) को सीता कहा जाता था और उससे होने वाली आय को भी।"},{"type":"exam_pattern","topic":"Administrative Systems Trend","analysis":"Unit 1 Systems Trend:","stats":["अधिकारी और उनके विभाग: 2 प्रश्न","भूमि कर प्रणाली (Mughal Land Revenue): 1 प्रश्न","स्थानीय स्वशासन (Chola): 1 प्रश्न"],"trend":"अब आयोग ''अलाउद्दीन खिलजी की बाजार नियंत्रण नीति'' और ''अकबर की दहसाला'' के तकनीकी शब्दों (जैसे- शहना-ए-मंडी) पर फोकस कर रहा है।"}],"en":[{"type":"h2","text":"Unit 1: Administrative & Economic Systems of Ancient & Medieval India"},{"type":"p","text":"History is not just dates; it''s about systems. In MPPSC (Prelims & Mains), ''Administrative Terminology'' and ''Taxation Systems'' form the most challenging part of the history section."},{"type":"h2","text":"1. Ancient India: Mauryan & Gupta Administration"},{"type":"highlight","level":"critical","text":"Saptanga Theory: Kautilya (Chanakya) defined 7 limbs of a state in ''Arthashastra''. Without these, a state cannot exist.","icon":"👑"},{"type":"mnemonic","topic":"Saptanga Theory (Kautilya''s 7 Limbs)","trick":"S-A-J-D K-D-M","visual":"🏰","explanation":"1. **S**wami - King (The Head)\n2. **A**matya - Minister (The Eyes)\n3. **J**anapada - Territory/People (The Thighs)\n4. **D**urga - Fort (The Arms)\n5. **K**osha - Treasury (The Mouth)\n6. **D**anda - Army/Justice (The Brain)\n7. **M**itra - Ally (The Ears)"},{"type":"fact_card","title":"Important Mauryan Officers","facts":["Samaharta: Collector General (Revenue Collection) - Most important.","Sannidhata: Treasurer (Keeper of royal stores).","Sitaadhyaksha: Superintendent of Agriculture (Sita = Crown Land).","Lakshanadhyaksha: Superintendent of Mint."],"icon":"📜"},{"type":"h3","text":"Chola Administration (Local Self Government)"},{"type":"p","text":"The Chola Empire of South India was famous for its ''Village Autonomy''. ''Ur'' (General Assembly) and ''Sabha'' (Assembly of Brahmins) were key institutions."},{"type":"highlight","level":"important","text":"Uttaramerur Inscription: Gives detailed information about the election system (Kudavolai - Lottery System) of Chola village assemblies. Belongs to Parantaka I.","icon":"🗳️"},{"type":"h2","text":"2. Medieval India: Sultanate & Mughal Systems"},{"type":"table","instruction":"Iqta vs Mansabdari (Key Differences)","head":["Feature","Iqta System (Sultanate)","Mansabdari System (Mughal)"],"body":[["Started By","Iltutmish (Delhi Sultanate)","Akbar (Mughal Empire)"],["Nature","Assignment of Land Revenue in lieu of salary.","A Rank (Zat & Sawar) determining Status & Salary."],["Hereditary","Initially No, later made hereditary by Firoz Tughlaq.","No (Solely at the Emperor''s will)."],["Purpose","To collect revenue from distant lands and maintain troops.","To organize Civil and Military admin under one roof."]]},{"type":"fact_card","title":"Mughal Economic Terminology","facts":["Polaj: Land cultivated every year (Most fertile).","Parauti: Land left fallow for 1-2 years.","Dahsala: 10-year revenue settlement system introduced by Todarmal (1580)."],"icon":"🌾"},{"type":"h2","text":"Economic Organization: Shreni (Guilds)"},{"type":"p","text":"In Ancient India, associations of merchants and craftsmen were called ''Shreni''. They had their own laws called ''Shreni Dharma''. The Mandsaur Inscription mentions a ''Guild of Silk Weavers''."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019 / UPSC 2021","year":2019,"question":"Which dynasty''s rule was famous for ''Village Administration'' (Local Autonomy)?","options":["Chola","Chalukya","Pallava","Rashtrakuta"],"correct":"Chola","strategy":"Chola = Local Self Govt (Uttaramerur Inscription). This is a high-frequency question."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Who was ''Muhtasib'' in Mughal Administration?","options":["Army Officer","Head of Foreign Affairs","Officer of Public Morals","Head of Correspondence"],"correct":"Officer of Public Morals","strategy":"Muhtasib was appointed to enforce Islamic law and monitor public behavior (morality). Aurangzeb strengthened this post."},{"type":"pyq","exam":"UPPSC Prelims 2017","year":2017,"question":"What did ''Sita'' mean in the Mauryan period?","options":["A Goddess","A religious sect","Revenue from Crown Land","Barren Land"],"correct":"Revenue from Crown Land","strategy":"Sita means ''Furrow'' (plough line). In Mauryan administration, income from government land was called Sita."},{"type":"exam_pattern","topic":"Administrative Systems Trend","analysis":"Unit 1 Systems Trend:","stats":["Officers & Departments: 2 questions","Land Revenue Systems: 1 question","Local Self Govt (Chola): 1 question"],"trend":"The Commission is now focusing on technical terms of Alauddin Khilji''s Market Control (like Shahna-i-Mandi) and Akbar''s Dahsala system."}]}', 'history', NULL, 16, 1, 1770835487, 1770835487, 'blog', 'unit_1', 'Salient features, Events and their administrative, Social and Economic Systems of Ancient and Medieval India', 1, 0, 0, 1, 0, 'Unit 1: प्राचीन और मध्यकालीन भारत की प्रशासनिक एवं आर्थिक प्रणालियाँ इतिहास केवल युद्धों की तारीखें नहीं है, बल्कि यह समझने का विषय है कि समाज कैसे चलता था। MPPSC (Prelims & Mains) में ''प्रशासनिक शब्द...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('5122b54b-77a8-4fbf-8a63-45fd6f3e13b4', 'indian-cultural-heritage-art-literature-festivals-unit-1', 'Indian Cultural Heritage: Art, Literature & Festivals | भारतीय सांस्कृतिक विरासत: कला, साहित्य और पर्व', 'Comprehensive guide to Indian Artforms (Temple Architecture, Paintings, Dance), Ancient Literature, and Festivals. Special focus on MPPSC relevant facts like Khajuraho, Kalidasa, and Kumbh Mela.', '{"hi":[{"type":"h2","text":"Unit 1: भारत की सांस्कृतिक विरासत - एक व्यापक अध्ययन"},{"type":"p","text":"MPPSC Unit 1 का यह हिस्सा सबसे विशाल और रंगीन है। इसमें न केवल इतिहास, बल्कि ''कला और संस्कृति'' (Art & Culture) का भी समागम है। परीक्षा में यहाँ से प्रश्न स्थापत्य शैलियों (Nagara/Dravida), शास्त्रीय नृत्यों, और प्राचीन पुस्तकों के लेखकों पर पूछे जाते हैं।"},{"type":"h2","text":"1. भारतीय स्थापत्य कला (Architecture)"},{"type":"p","text":"प्राचीन भारत में मंदिर निर्माण की तीन प्रमुख शैलियाँ विकसित हुईं। MPPSC के लिए ''नागर शैली'' सबसे महत्वपूर्ण है क्योंकि मध्य प्रदेश के अधिकांश मंदिर इसी शैली के हैं।"},"",{"type":"table","instruction":"मंदिर निर्माण शैलियाँ","head":["शैली (Style)","क्षेत्र (Region)","विशेषता (Features)","उदाहरण"],"body":[["नागर (Nagara)","उत्तर भारत (हिमालय से विंध्य तक)","रेखीय शिखर, वर्गाकार गर्भगृह, आमलक और कलश।","खजुराहो के मंदिर (MP), कोणार्क सूर्य मंदिर।"],["द्रविड़ (Dravida)","दक्षिण भारत (कृष्णा से कन्याकुमारी)","पिरामिडनुमा विमान, भव्य प्रवेश द्वार (गोपुरम)।","बृहदेश्वर मंदिर (तंजौर), मीनाक्षी मंदिर।"],["बेसर (Vesara)","दक्कन (मध्य भारत)","नागर और द्रविड़ का मिश्रण। (अर्ध-गोलाकार शिखर)।","होयसलेश्वर मंदिर, एलोरा के कुछ मंदिर।"]]},{"type":"highlight","level":"critical","text":"खजुराहो (MP): चंदेल शासकों द्वारा निर्मित (950-1050 AD)। यह नागर शैली का उत्कृष्ट उदाहरण है। यहाँ की ''पंचायतन शैली'' (Panchayatan Style) विशेष प्रसिद्ध है।","icon":"b"},{"type":"h2","text":"2. प्रदर्शनकारी कलाएं: नृत्य और संगीत (Performing Arts)"},{"type":"p","text":"संगीत नाटक अकादमी ने भारत में 8 शास्त्रीय नृत्यों (Classical Dances) को मान्यता दी है। लोक नृत्यों (Folk Dances) से अलग, ये ''नाट्यशास्त्र'' (भरतमुनि) के नियमों का पालन करते हैं।"},{"type":"mnemonic","topic":"8 शास्त्रीय नृत्य और उनके राज्य","trick":"Bharat ka Kathak, Mohini ki Kathakali, Kuchipudi me Mani-Odissi","visual":"💃","explanation":"1. **Bharat**natyam - तमिलनाडु (सबसे पुराना)\n2. **Kathak** - उत्तर प्रदेश (उत्तर भारत)\n3. **Mohini**yattam - केरल\n4. **Kathakali** - केरल (मुखौटा नृत्य)\n5. **Kuchipudi** - आंध्र प्रदेश\n6. **Mani**puri - मणिपुर\n7. **Odissi** - ओडिशा\n8. **Sattriya** - असम (शंकरदेव द्वारा विकसित)"},{"type":"h2","text":"3. भारतीय चित्रकला (Paintings)"},{"type":"p","text":"चित्रकला को दो भागों में बांटा जा सकता है: भित्ति चित्र (Murals - दीवारों पर) और लघु चित्र (Miniatures - कागज/कपड़े पर)।"},{"type":"fact_card","title":"प्रमुख चित्रकला शैलियाँ","facts":["अजंता (महाराष्ट्र): बौद्ध धर्म (जातक कथाएं) से संबंधित। गुफा नं. 1 में ''पद्मपाणि बोधिसत्व'' विश्व प्रसिद्ध है।","बाघ गुफाएं (धार, MP): गुप्तकालीन चित्रकला। इसे ''रंगमहल'' कहा जाता है। लोक जीवन का चित्रण।","मुगल चित्रकला: जहांगीर का काल ''स्वर्ण युग'' था। यह यथार्थवादी (Realistic) और पशु-पक्षियों के चित्रण (उस्ताद मंसूर) के लिए प्रसिद्ध थी।","कांगड़ा/पहाड़ी शैली: ''प्रेम'' (राधा-कृष्ण) इसका मुख्य विषय था।"],"icon":"🎨"},{"type":"h2","text":"4. प्राचीन भारतीय साहित्य (Literature)"},{"type":"p","text":"साहित्य समाज का दर्पण है। प्राचीन साहित्य को धार्मिक (वेदों/पुराण) और लौकिक (Secular) में बांटा जाता है। गुप्त काल को साहित्य का ''स्वर्ण युग'' कहा जाता है।"},{"type":"highlight","level":"important","text":"कालिदास (भारत के शेक्सपियर): चंद्रगुप्त विक्रमादित्य के नवरत्न।\nमहाकाव्य: रघुवंशम, कुमारसंभवम।\nनाटक: अभिज्ञान शाकुंतलम, मालविकाग्निमित्रम।\nखंडकाव्य: मेघदूत (उज्जयिनी का वर्णन), ऋतुसंहार।","icon":"📚"},{"type":"table","instruction":"प्रमुख प्राचीन पुस्तकें और लेखक","head":["पुस्तक","लेखक","विषय/महत्व"],"body":[["अर्थशास्त्र","कौटिल्य","राजनीति और प्रशासन (Politics)"],["अष्टाध्यायी","पाणिनी","संस्कृत व्याकरण (Grammar)"],["राजतरंगिणी","कल्हण","कश्मीर का इतिहास (First Historical Book)"],["पंचतंत्र","विष्णु शर्मा","नीति कथाएं (सर्वाधिक अनुवादित पुस्तक)"],["मृच्छकटिकम्","शूद्रक","एक आम नागरिक की प्रेम कथा"]]},{"type":"h2","text":"5. पर्व और उत्सव (Festivals & Events)"},{"type":"p","text":"भारत मेलों और उत्सवों का देश है। कुंभ मेला विश्व का सबसे बड़ा धार्मिक सम्मेलन है जो 12 वर्षों के अंतराल पर 4 स्थानों पर लगता है।"},{"type":"mnemonic","topic":"कुंभ मेला के 4 स्थान","trick":"P-H-U-N (फन)","visual":"🙏","explanation":"**P** - Prayagraj (प्रयागराज) - गंगा-यमुना संगम\n**H** - Haridwar (हरिद्वार) - गंगा नदी\n**U** - Ujjain (उज्जैन) - क्षिप्रा नदी (MP में इसे ''सिंहस्थ'' कहते हैं)\n**N** - Nashik (नासिक) - गोदावरी नदी"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2022","year":2022,"question":"खजुराहो के मंदिर किस राजवंश द्वारा बनवाए गए थे?","options":["परमार","चंदेल","मौर्य","होलकर"],"correct":"चंदेल","strategy":"चंदेल राजाओं ने 950-1050 ई. के बीच इनका निर्माण करवाया। कंदरिया महादेव मंदिर सबसे प्रमुख है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"निम्न में से कौन सा एक ''शास्त्रीय नृत्य'' (Classical Dance) नहीं है?","options":["कथक","ओडिसी","गरबा","मणिपुरी"],"correct":"गरबा","strategy":"गरबा गुजरात का एक ''लोक नृत्य'' (Folk Dance) है, शास्त्रीय नृत्य नहीं।"},{"type":"pyq","exam":"UPSC / MPPSC Cultural History","year":2018,"question":"प्रसिद्ध पुस्तक ''मृच्छकटिकम्'' के लेखक कौन थे?","options":["कालिदास","शूद्रक","भास","विशाखदत्त"],"correct":"शूद्रक","strategy":"मृच्छकटिकम् का अर्थ है ''मिट्टी की गाड़ी''। यह गुप्तकालीन समाज का यथार्थ चित्रण करती है।"},{"type":"exam_pattern","topic":"Art & Culture Trend","analysis":"प्रश्नों की प्रकृति:","stats":["मंदिर वास्तुकला (स्थान/शैली): 2 प्रश्न","पुस्तक और लेखक: 2 प्रश्न","चित्रकला/लोक कला (MP Special): 2 प्रश्न"],"trend":"MPPSC अब ''मध्य प्रदेश की लोक संस्कृति'' (जैसे- पिथोरा चित्रकला, राई नृत्य) को भारतीय संदर्भ के साथ जोड़कर पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 1: India''s Cultural Heritage - A Comprehensive Study"},{"type":"p","text":"This section of MPPSC Unit 1 is vast and vibrant. It blends history with ''Art & Culture''. Questions here usually target architectural styles (Nagara/Dravida), classical dances, and authors of ancient texts."},{"type":"h2","text":"1. Indian Architecture (Vastu Kala)"},{"type":"p","text":"In ancient India, three major styles of temple architecture evolved. For MPPSC, the ''Nagara Style'' is crucial as most temples in Madhya Pradesh follow this style."},"",{"type":"table","instruction":"Temple Architecture Styles","head":["Style","Region","Key Features","Examples"],"body":[["Nagara","North India (Himalayas to Vindhyas)","Curvilinear Tower (Shikhara), Square Sanctum, Amalaka, and Kalash.","Khajuraho Temples (MP), Konark Sun Temple."],["Dravida","South India (Krishna to Kanyakumari)","Pyramidal Tower (Vimana), Grand Entrance Gateway (Gopuram).","Brihadeshwara Temple (Thanjavur), Meenakshi Temple."],["Vesara","Deccan (Central India)","Hybrid of Nagara and Dravida. (Semi-circular/Apsidal Shikhara).","Hoysaleswara Temple, Some Ellora temples."]]},{"type":"highlight","level":"critical","text":"Khajuraho (MP): Built by Chandela rulers (950-1050 AD). It is a masterpiece of Nagara style. Famous for its ''Panchayatan Style'' and Erotic sculptures.","icon":"b"},{"type":"h2","text":"2. Performing Arts: Dance & Music"},{"type":"p","text":"Sangeet Natak Akademi recognizes 8 Classical Dances in India. Unlike folk dances, these strictly follow the rules of ''Natyashastra'' (by Bharata Muni)."},{"type":"mnemonic","topic":"8 Classical Dances & States","trick":"Bharat''s Kathak, Mohini''s Kathakali, Mani-Odissi in Kuchipudi","visual":"💃","explanation":"1. **Bharat**natyam - Tamil Nadu (Oldest)\n2. **Kathak** - Uttar Pradesh (North India)\n3. **Mohini**yattam - Kerala\n4. **Kathakali** - Kerala (Mask dance)\n5. **Kuchipudi** - Andhra Pradesh\n6. **Mani**puri - Manipur\n7. **Odissi** - Odisha\n8. **Sattriya** - Assam (Developed by Sankaradeva)"},{"type":"h2","text":"3. Indian Paintings"},{"type":"p","text":"Painting traditions are divided into Murals (Wall paintings) and Miniatures (on paper/cloth)."},{"type":"fact_card","title":"Major Painting Schools","facts":["Ajanta (Maharashtra): Buddhist themes (Jataka tales). ''Padmapani Bodhisattva'' in Cave 1 is world-famous.","Bagh Caves (Dhar, MP): Gupta period art. Known as ''Rangmahal''. Depicts secular/common life.","Mughal Painting: Jahangir''s era was the ''Golden Age''. Known for Realism and Nature/Animal depictions (Ustad Mansur).","Kangra/Pahari School: ''Love'' (Radha-Krishna) was the central theme."],"icon":"🎨"},{"type":"h2","text":"4. Ancient Indian Literature"},{"type":"p","text":"Literature mirrors society. Ancient texts are categorized into Religious (Vedas/Puranas) and Secular. The Gupta Period is called the ''Golden Age of Literature''."},{"type":"highlight","level":"important","text":"Kalidasa (Shakespeare of India): Navratna of Chandragupta Vikramaditya.\nEpics: Raghuvamsham, Kumarasambhavam.\nPlays: Abhigyan Shakuntalam, Malavikagnimitram.\nPoetry: Meghaduta (Describes Ujjain), Ritusamhara.","icon":"📚"},{"type":"table","instruction":"Key Ancient Texts & Authors","head":["Book","Author","Subject/Significance"],"body":[["Arthashastra","Kautilya","Statecraft & Administration"],["Ashtadhyayi","Panini","Sanskrit Grammar"],["Rajtarangini","Kalhana","History of Kashmir (First true historical book)"],["Panchatantra","Vishnu Sharma","Fables/Moral Stories (Most translated Indian book)"],["Mrichchhakatika","Shudraka","Love story of a common man (The Little Clay Cart)"]]},{"type":"h2","text":"5. Festivals & Events"},{"type":"p","text":"India is a land of festivals. The Kumbh Mela is the largest religious gathering in the world, held every 12 years at 4 rotational locations."},{"type":"mnemonic","topic":"4 Locations of Kumbh Mela","trick":"P-H-U-N (Fun)","visual":"🙏","explanation":"**P** - Prayagraj - Confluence of Ganga-Yamuna\n**H** - Haridwar - Ganga River\n**U** - Ujjain - Kshipra River (Called ''Simhastha'' in MP)\n**N** - Nashik - Godavari River"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2022","year":2022,"question":"The temples of Khajuraho were built by which dynasty?","options":["Paramara","Chandela","Maurya","Holkar"],"correct":"Chandela","strategy":"Built between 950-1050 AD. Kandariya Mahadev is the most prominent temple."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which of the following is NOT a ''Classical Dance''?","options":["Kathak","Odissi","Garba","Manipuri"],"correct":"Garba","strategy":"Garba is a ''Folk Dance'' of Gujarat, not a classical form recognized by Sangeet Natak Akademi."},{"type":"pyq","exam":"UPSC / MPPSC Cultural History","year":2018,"question":"Who was the author of the famous play ''Mrichchhakatika''?","options":["Kalidasa","Shudraka","Bhasa","Vishakhadatta"],"correct":"Shudraka","strategy":"Mrichchhakatika means ''The Little Clay Cart''. It depicts the realistic social life of the Gupta period."},{"type":"exam_pattern","topic":"Art & Culture Trend","analysis":"Question Nature Analysis:","stats":["Temple Architecture (Location/Style): 2 questions","Books & Authors: 2 questions","Painting/Folk Arts (MP Special): 2 questions"],"trend":"MPPSC is now linking ''Folk Culture of MP'' (e.g., Pithora paintings, Rai dance) with the broader Indian context."}]}', 'history', NULL, 20, 1, 1770835549, 1771008825, 'blog', 'unit_1', 'India''s cultural heritage: Artforms, literature, festivals and events', 1, 0, 0, 1, 0, 'Unit 1: भारत की सांस्कृतिक विरासत - एक व्यापक अध्ययन MPPSC Unit 1 का यह हिस्सा सबसे विशाल और रंगीन है। इसमें न केवल इतिहास, बल्कि ''कला और संस्कृति'' (Art & Culture) का भी समागम है। परीक्षा में यहाँ से ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('72748fb0-2bce-48dd-b494-bbd3cfbbadbe', 'social-religious-reform-movements-unit-1-mppsc', 'Social & Religious Reform Movements (19th-20th Century) | सामाजिक एवं धार्मिक सुधार आंदोलन', 'Comprehensive guide to the Indian Renaissance. Covers Brahmo Samaj, Arya Samaj, Ramakrishna Mission, Aligarh Movement, and key reformers like Raja Ram Mohan Roy, Dayanand Saraswati, and Jyotiba Phule.', '{"hi":[{"type":"h2","text":"Unit 1: 19वीं और 20वीं सदी के सामाजिक-धार्मिक सुधार आंदोलन (Indian Renaissance)"},{"type":"p","text":"19वीं सदी में भारत में तर्कवाद (Rationalism) और मानवतावाद (Humanism) की लहर उठी, जिसे ''भारतीय पुनर्जागरण'' (Indian Renaissance) कहा जाता है। इसका मुख्य उद्देश्य समाज में व्याप्त कुरीतियों (जैसे सती प्रथा, बाल विवाह, जाति प्रथा) को समाप्त करना था। MPPSC में संस्थापकों, वर्षों और उनकी पत्रिकाओं (Journals) पर सबसे अधिक प्रश्न पूछे जाते हैं।"},{"type":"highlight","level":"critical","text":"राजा राममोहन राय को ''भारतीय पुनर्जागरण का पिता'' (Father of Indian Renaissance) और ''आधुनिक भारत का निर्माता'' कहा जाता है।","icon":"🌟"},{"type":"h2","text":"1. ब्रह्म समाज (Brahmo Samaj) - 1828"},{"type":"p","text":"राजा राममोहन राय ने एकेश्वरवाद (Monotheism) और मूर्तिपूजा के विरोध में इसकी स्थापना की। उनके प्रयासों से 1829 में सती प्रथा निषेध अधिनियम (Sati Prohibition Act) पारित हुआ (लॉर्ड विलियम बेंटिक द्वारा)।"},{"type":"fact_card","title":"राजा राममोहन राय: महत्वपूर्ण तथ्य","facts":["उपाधि: ''राजा'' (मुगल बादशाह अकबर द्वितीय ने दी)।","पत्रिकाएं: संवाद कौमुदी (बंगाली), मिरात-उल-अखबार (फारसी)।","पुस्तक: तुहफत-उल-मुवाहिदीन (एकेश्वरवादियों को उपहार)।","मृत्यु: ब्रिस्टल, इंग्लैंड (1833) में।"],"icon":"📰"},{"type":"h2","text":"2. आर्य समाज (Arya Samaj) - 1875"},{"type":"p","text":"स्वामी दयानन्द सरस्वती ने बम्बई में इसकी स्थापना की। उनका नारा था - ''वेदों की ओर लौटो'' (Go back to Vedas)। उन्होंने शुद्धि आंदोलन (Shuddhi Movement) चलाया (धर्म परिवर्तन कर चुके लोगों की वापसी के लिए)।"},"",{"type":"highlight","level":"important","text":"स्वराज (Swaraj): दयानन्द सरस्वती पहले व्यक्ति थे जिन्होंने ''स्वराज'' शब्द का प्रयोग किया और कहा ''भारत भारतीयों के लिए है'' (India for Indians)।\nप्रमुख ग्रंथ: सत्यार्थ प्रकाश (Satyarth Prakash)।","icon":"📖"},{"type":"h2","text":"3. रामकृष्ण मिशन (Ramakrishna Mission) - 1897"},{"type":"p","text":"स्वामी विवेकानंद ने अपने गुरु रामकृष्ण परमहंस की शिक्षाओं के प्रचार के लिए इसकी स्थापना की। उनका सिद्धांत था - ''नर सेवा ही नारायण सेवा है'' (Service to man is service to God)।"},{"type":"highlight","level":"note","text":"शिकागो धर्म सम्मेलन (1893): विवेकानंद ने ऐतिहासिक भाषण दिया। उन्हें ''तूफानी हिंदू'' (Cyclonic Hindu) कहा गया। सुभाष चंद्र बोस ने उन्हें ''आधुनिक राष्ट्रीय आंदोलन का आध्यात्मिक पिता'' कहा।","icon":"🔥"},{"type":"h2","text":"4. प्रमुख सुधार आंदोलन: एक नज़र में (Quick Table)"},{"type":"table","instruction":"संस्था, संस्थापक और वर्ष","head":["संस्था","वर्ष","संस्थापक","विशेषता/उद्देश्य"],"body":[["आत्मीय सभा","1815","राजा राममोहन राय","ब्रह्म समाज की पूर्वगामी संस्था।"],["यंग बंगाल","1826-31","हेनरी विवियन डेरोजियो","अति-कट्टरपंथी (Radical), फ्रांस की क्रांति से प्रेरित।"],["तत्वबोधिनी सभा","1839","देवेन्द्रनाथ टैगोर","राजा राममोहन राय के विचारों का प्रचार।"],["प्रार्थना समाज","1867","आत्माराम पांडुरंग","महाराष्ट्र में केशव चंद्र सेन की प्रेरणा से। एम.जी. रानाडे भी जुड़े।"],["सत्य शोधक समाज","1873","ज्योतिबा फुले","जाति प्रथा विरोध। पुस्तक: गुलामगिरी।"],["थियोसोफिकल सोसायटी","1875 (NY)","ब्लावत्स्की और ऑलकोट","भारत में मुख्यालय: अड्यार (मद्रास, 1882)। एनी बेसेंट ने इसे लोकप्रिय बनाया।"]]},{"type":"mnemonic","topic":"संस्थाओं का सही कालक्रम (Chronology)","trick":"B-P-A-R (बी-पार)","visual":"⏳","explanation":"**B** - Brahmo Samaj (1828)\n**P** - Prarthana Samaj (1867)\n**A** - Arya Samaj (1875)\n**R** - Ramakrishna Mission (1897)"},{"type":"h2","text":"5. अन्य महत्वपूर्ण सुधार (Other Reforms)"},{"type":"ul","items":["**विधवा पुनर्विवाह (Widow Remarriage):** ईश्वर चंद्र विद्यासागर के प्रयासों से ''हिंदू विधवा पुनर्विवाह अधिनियम, 1856'' (लॉर्ड कैनिंग के समय) पारित हुआ।","**अलीगढ़ आंदोलन (1875):** सर सैयद अहमद खान। उद्देश्य: मुसलमानों में आधुनिक और अंग्रेजी शिक्षा का प्रसार। (साइंटिफिक सोसायटी की स्थापना)।","**शारदा एक्ट (1930):** हरविलास शारदा के प्रयासों से बाल विवाह रोकने के लिए। (लड़कों की आयु 18, लड़कियों की 14 तय की गई)।"]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"''सत्यार्थ प्रकाश'' ग्रंथ के लेखक कौन थे?","options":["स्वामी विवेकानंद","स्वामी दयानन्द सरस्वती","राजा राममोहन राय","अरबिंदो घोष"],"correct":"स्वामी दयानन्द सरस्वती","strategy":"सत्यार्थ प्रकाश आर्य समाज का मूल ग्रंथ है। ''सत्य'' (Truth) की खोज दयानन्द जी ने वेदों में की।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"1893 में शिकागो में आयोजित ''विश्व धर्म संसद'' में किसने भाग लिया था?","options":["राजा राममोहन राय","स्वामी विवेकानंद","दयानन्द सरस्वती","रामकृष्ण परमहंस"],"correct":"स्वामी विवेकानंद","strategy":"विवेकानंद का प्रसिद्ध संबोधन ''अमेरिका के भाइयों और बहनों'' (Brothers and Sisters of America) यहीं दिया गया था।"},{"type":"pyq","exam":"UPSC Prelims 2016","year":2016,"question":"''सत्य शोधक समाज'' ने क्या संगठित किया?","options":["बिहार में आदिवासियों का आंदोलन","गुजरात में मंदिर प्रवेश","महाराष्ट्र में जाति विरोधी आंदोलन","पंजाब में किसान आंदोलन"],"correct":"महाराष्ट्र में जाति विरोधी आंदोलन","strategy":"ज्योतिबा फुले महाराष्ट्र (पूणे) के थे और उन्होंने निम्न जातियों (विशेषकर माली समुदाय) के उत्थान के लिए कार्य किया।"},{"type":"exam_pattern","topic":"Reform Movements Trend","analysis":"Unit 1 Trend Analysis:","stats":["संस्थापक और वर्ष: 2 प्रश्न","पत्रिकाएं/पुस्तकें: 1 प्रश्न","कथन (Statements): 1 प्रश्न"],"trend":"अब आयोग केवल संस्थापकों के नाम नहीं पूछता, बल्कि उनके सहयोगियों (Associates) और सामाजिक कानूनों (जैसे नेटिव मैरिज एक्ट) पर भी प्रश्न पूछता है।"}],"en":[{"type":"h2","text":"Unit 1: Social & Religious Reform Movements (19th-20th Century)"},{"type":"p","text":"The 19th century witnessed a wave of Rationalism and Humanism in India, termed the ''Indian Renaissance''. Its primary aim was to eradicate social evils (like Sati, Child Marriage, Caste System). In MPPSC, questions focus heavily on Founders, Chronology, and Journals."},{"type":"highlight","level":"critical","text":"Raja Ram Mohan Roy is known as the ''Father of Indian Renaissance'' and the ''Maker of Modern India''.","icon":"🌟"},{"type":"h2","text":"1. Brahmo Samaj (1828)"},{"type":"p","text":"Founded by Raja Ram Mohan Roy to preach Monotheism and oppose Idolatry. His efforts led to the passing of the Sati Prohibition Act in 1829 (by Lord William Bentinck)."},{"type":"fact_card","title":"Raja Ram Mohan Roy: Key Facts","facts":["Title: ''Raja'' (Given by Mughal Emperor Akbar II).","Journals: Samvad Kaumudi (Bengali), Mirat-ul-Akhbar (Persian).","Book: Tuhfat-ul-Muwahhidin (Gift to Monotheists).","Death: Bristol, England (1833)."],"icon":"📰"},{"type":"h2","text":"2. Arya Samaj (1875)"},{"type":"p","text":"Founded by Swami Dayanand Saraswati in Bombay. His slogan was ''Go back to Vedas''. He launched the Shuddhi Movement (to reconvert those who had left Hinduism)."},"",{"type":"highlight","level":"important","text":"Swaraj: Dayanand Saraswati was the first to use the word ''Swaraj'' and stated ''India for Indians''.\nKey Text: Satyarth Prakash.","icon":"📖"},{"type":"h2","text":"3. Ramakrishna Mission (1897)"},{"type":"p","text":"Founded by Swami Vivekananda to propagate the teachings of his Guru, Ramakrishna Paramhansa. His motto was ''Service to man is service to God''."},{"type":"highlight","level":"note","text":"Chicago Parliament of Religions (1893): Vivekananda delivered his historic speech. He was called the ''Cyclonic Hindu''. Subhash Chandra Bose called him the ''Spiritual Father of the Modern National Movement''.","icon":"🔥"},{"type":"h2","text":"4. Major Reform Movements: At a Glance"},{"type":"table","instruction":"Organization, Founder & Objective","head":["Organization","Year","Founder","Feature/Objective"],"body":[["Atmiya Sabha","1815","Raja Ram Mohan Roy","Precursor to Brahmo Samaj."],["Young Bengal","1826-31","Henry Vivian Derozio","Radical, inspired by the French Revolution."],["Tattvabodhini Sabha","1839","Debendranath Tagore","Propagated Ram Mohan Roy''s ideas."],["Prarthana Samaj","1867","Atmaram Pandurang","Founded in Maharashtra with help of Keshav Chandra Sen. MG Ranade joined later."],["Satya Shodhak Samaj","1873","Jyotiba Phule","Anti-caste movement. Book: Gulamgiri."],["Theosophical Society","1875 (NY)","Blavatsky & Olcott","HQ in India: Adyar (Madras, 1882). Popularized by Annie Besant."]]},{"type":"mnemonic","topic":"Chronology of Movements","trick":"B-P-A-R","visual":"⏳","explanation":"**B** - Brahmo Samaj (1828)\n**P** - Prarthana Samaj (1867)\n**A** - Arya Samaj (1875)\n**R** - Ramakrishna Mission (1897)"},{"type":"h2","text":"5. Other Important Reforms"},{"type":"ul","items":["**Widow Remarriage:** Due to Ishwar Chandra Vidyasagar''s efforts, the ''Hindu Widow Remarriage Act, 1856'' was passed (Time of Lord Canning).","**Aligarh Movement (1875):** Sir Syed Ahmed Khan. Objective: Modern and English education for Muslims. (Founded Scientific Society).","**Sarda Act (1930):** To prevent Child Marriage. (Age fixed: Boys 18, Girls 14). Named after Harbilas Sarda."]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Who was the author of the book ''Satyarth Prakash''?","options":["Swami Vivekananda","Swami Dayanand Saraswati","Raja Ram Mohan Roy","Aurobindo Ghosh"],"correct":"Swami Dayanand Saraswati","strategy":"Satyarth Prakash is the foundational text of Arya Samaj. Dayanand ji sought ''Satya'' (Truth) in the Vedas."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Who participated in the ''Parliament of World Religions'' held at Chicago in 1893?","options":["Raja Ram Mohan Roy","Swami Vivekananda","Dayanand Saraswati","Ramakrishna Paramhansa"],"correct":"Swami Vivekananda","strategy":"Vivekananda''s famous address ''Brothers and Sisters of America'' was given here."},{"type":"pyq","exam":"UPSC Prelims 2016","year":2016,"question":"Satya Shodhak Samaj organized?","options":["Tribal movement in Bihar","Temple entry in Gujarat","Anti-caste movement in Maharashtra","Peasant movement in Punjab"],"correct":"Anti-caste movement in Maharashtra","strategy":"Jyotiba Phule belonged to Maharashtra (Pune) and worked for the upliftment of lower castes (especially Mali community)."},{"type":"exam_pattern","topic":"Reform Movements Trend","analysis":"Unit 1 Trend Analysis:","stats":["Founders & Years: 2 questions","Journals/Books: 1 question","Statements: 1 question"],"trend":"The Commission now asks not just names, but about associates and specific social laws (like Native Marriage Act)."}]}', 'history', NULL, 25, 1, 1770835612, 1771008821, 'blog', 'unit_1', 'Social and Religious Reform Movements in 19th and 20th century', 1, 0, 1, 1, 0, 'Unit 1: 19वीं और 20वीं सदी के सामाजिक-धार्मिक सुधार आंदोलन (Indian Renaissance) 19वीं सदी में भारत में तर्कवाद (Rationalism) और मानवतावाद (Humanism) की लहर उठी, जिसे ''भारतीय पुनर्जागरण'' (Indian Renais...', 'common');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('1c6856b7-f9a1-4b84-9969-8decff65b66e', 'indian-national-movement-independence-struggle-unit-1-mppsc', 'Indian National Movement & Independence Struggle (1857-1947) | भारतीय राष्ट्रीय आंदोलन', 'Comprehensive timeline of India''s freedom struggle. Covers the Gandhian Era, Revolutionary movements, INC sessions, and MP''s specific role (Tripuri/Jhanda Satyagraha).', '{"hi":[{"type":"h2","text":"Unit 1: भारतीय स्वतंत्रता संघर्ष - एक महागाथा"},{"type":"p","text":"भारतीय राष्ट्रीय आंदोलन को तीन प्रमुख चरणों में समझा जा सकता है: उदारवादी चरण (1885-1905), उग्रवादी चरण (1905-1919), और गांधीवादी युग (1919-1947)। MPPSC में घटनाओं के कालक्रम (Chronology) और स्वतंत्रता सेनानियों के योगदान पर प्रश्न पूछे जाते हैं।"},{"type":"highlight","level":"critical","text":"कांग्रेस की स्थापना: 28 दिसंबर 1885।\nसंस्थापक: ए.ओ. ह्यूम (A.O. Hume)।\nवायसराय: लॉर्ड डफरिन (Lord Dufferin)।\nपहला अधिवेशन: बम्बई (अध्यक्ष: डब्ल्यू.सी. बनर्जी)।","icon":"🚩"},{"type":"h2","text":"1. राष्ट्रीय आंदोलन के चरण"},{"type":"h3","text":"बंग-भंग और स्वदेशी आंदोलन (1905)"},{"type":"p","text":"लॉर्ड कर्जन ने 1905 में बंगाल का विभाजन किया। इसके विरोध में ''स्वदेशी आंदोलन'' शुरू हुआ। रवींद्रनाथ टैगोर ने ''आमार सोनार बांग्ला'' लिखा और ''रक्षाबंधन'' मनाने का आह्वान किया।"},{"type":"mnemonic","topic":"कांग्रेस के शुरुआती 4 अधिवेशन (स्थान)","trick":"B-C-M-A (बक-मई)","visual":"📍","explanation":"**B** - Bombay (1885)\n**C** - Calcutta (1886)\n**M** - Madras (1887)\n**A** - Allahabad (1888 - प्रथम अंग्रेज अध्यक्ष जॉर्ज यूल)"},{"type":"h2","text":"2. गांधीवादी युग (Gandhian Era: 1915-1947)"},{"type":"p","text":"9 जनवरी 1915 को गांधीजी दक्षिण अफ्रीका से लौटे (प्रवासी भारतीय दिवस)। उनके शुरुआती तीन आंदोलन बहुत महत्वपूर्ण हैं।"},{"type":"mnemonic","topic":"गांधीजी के शुरुआती आंदोलन (क्रम)","trick":"Gandhi ate CAK (Cake)","visual":"🎂","explanation":"**C** - Champaran (1917): पहला सत्याग्रह (नील की खेती के विरोध में)।\n**A** - Ahmedabad Mill Strike (1918): पहली भूख हड़ताल (Hunger Strike)।\n**K** - Kheda Satyagraha (1918): पहला असहयोग (Non-Cooperation)।"},"",{"type":"table","instruction":"गांधीजी के तीन बड़े जन-आंदोलन","head":["आंदोलन","वर्ष","कारण/घटना","समाप्ति"],"body":[["असहयोग आंदोलन (Non-Cooperation)","1920-22","जलियांवाला बाग और खिलाफत मुद्दा।","चौरी-चौरा कांड (फरवरी 1922) के कारण वापस लिया।"],["सविनय अवज्ञा आंदोलन (Civil Disobedience)","1930","नमक कानून तोड़ना (दांडी मार्च: 12 मार्च - 6 अप्रैल)।","गांधी-इरविन समझौता (1931)।"],["भारत छोड़ो आंदोलन (Quit India)","1942","क्रिप्स मिशन की विफलता। नारा: ''करो या मरो'' (Do or Die)।","अंग्रेजों द्वारा ''Operation Zero Hour'' चलाकर नेताओं की गिरफ्तारी।"]]},{"type":"h2","text":"3. क्रांतिकारी आंदोलन (Revolutionary Movement)"},{"type":"p","text":"भगत सिंह, चंद्रशेखर आजाद और रामप्रसाद बिस्मिल जैसे वीरों ने ''हिंदुस्तान रिपब्लिकन एसोसिएशन'' (HRA - 1924) और बाद में HSRA (1928) का गठन किया।"},{"type":"highlight","level":"important","text":"काकोरी ट्रेन एक्शन (Kakori Train Action): 9 अगस्त 1925।\nशामिल क्रांतिकारी: रामप्रसाद बिस्मिल, अशफाक उल्ला खान, रोशन सिंह, राजेंद्र लाहिड़ी (इन्हें फांसी दी गई)।","icon":"🚂"},{"type":"h2","text":"4. मध्य प्रदेश की भूमिका (MP Special Context)"},{"type":"fact_card","title":"MPPSC के लिए महत्वपूर्ण घटनाएं","facts":["झंडा सत्याग्रह (1923): जबलपुर से शुरू हुआ (सुभद्रा कुमारी चौहान शामिल)।","त्रिपुरी अधिवेशन (1939): जबलपुर में हुआ। सुभाष चंद्र बोस ने पट्टाभि सीतारमैया (गांधीजी के उम्मीदवार) को हराकर अध्यक्ष पद जीता था।","चरण पादुका नरसंहार (1931): छतरपुर। इसे ''MP का जलियांवाला बाग'' कहा जाता है।"],"icon":"🦁"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019 / 2021","year":2019,"question":"1939 में भारतीय राष्ट्रीय कांग्रेस का ''त्रिपुरी अधिवेशन'' कहाँ आयोजित हुआ था?","options":["भोपाल","जबलपुर","इंदौर","ग्वालियर"],"correct":"जबलपुर","strategy":"त्रिपुरी जबलपुर के पास है। यह अधिवेशन बोस और गांधीजी के विवाद के लिए प्रसिद्ध है।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"8 अगस्त 1942 को ''भारत छोड़ो आंदोलन'' कहाँ से शुरू हुआ?","options":["बॉम्बे (ग्वालिया टैंक)","कलकत्ता","मद्रास","पूना"],"correct":"बॉम्बे (ग्वालिया टैंक)","strategy":"ग्वालिया टैंक मैदान (अब अगस्त क्रांति मैदान) से गांधीजी ने ''करो या मरो'' का नारा दिया।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"जलियांवाला बाग नरसंहार (13 अप्रैल 1919) के विरोध में किसने अपनी ''नाइटहुड'' (Knighthood) की उपाधि लौटा दी थी?","options":["महात्मा गांधी","रवींद्रनाथ टैगोर","सुभाष चंद्र बोस","लाला लाजपत राय"],"correct":"रवींद्रनाथ टैगोर","strategy":"टैगोर ने सर/नाइटहुड लौटाया और गांधीजी ने ''कैसर-ए-हिंद'' की उपाधि लौटाई।"},{"type":"exam_pattern","topic":"National Movement Trend","analysis":"Unit 1 Freedom Struggle Trend:","stats":["गांधीवादी आंदोलन (वर्ष/घटना): 2-3 प्रश्न","कांग्रेस अधिवेशन (अध्यक्ष/स्थान): 1-2 प्रश्न","क्रांतिकारी गतिविधियां (काकोरी/भगत सिंह): 1 प्रश्न","MP का योगदान (झंडा सत्याग्रह): 1 प्रश्न"],"trend":"अब आयोग सीधे तारीख (जैसे 8 अगस्त vs 9 अगस्त) और कम प्रसिद्ध क्रांतिकारियों (जैसे भीमा नायक, टंट्या भील - Unit 10 के साथ लिंक करके) पर प्रश्न पूछता है।"}],"en":[{"type":"h2","text":"Unit 1: The Saga of Indian Independence Struggle"},{"type":"p","text":"The Indian National Movement is categorized into three phases: Moderate Phase (1885-1905), Extremist Phase (1905-1919), and Gandhian Era (1919-1947). For MPPSC, Chronology of events and contributions of freedom fighters are the most high-yield areas."},{"type":"highlight","level":"critical","text":"Formation of INC: 28 Dec 1885.\nFounder: A.O. Hume.\nViceroy: Lord Dufferin.\nFirst Session: Bombay (President: W.C. Banerjee).","icon":"🚩"},{"type":"h2","text":"1. Phases of National Movement"},{"type":"h3","text":"Partition of Bengal & Swadeshi (1905)"},{"type":"p","text":"Lord Curzon partitioned Bengal in 1905. This triggered the ''Swadeshi Movement''. Rabindranath Tagore wrote ''Amar Sonar Bangla'' and encouraged ''Raksha Bandhan'' as a symbol of unity."},{"type":"mnemonic","topic":"First 4 Sessions of INC (Locations)","trick":"B-C-M-A","visual":"📍","explanation":"**B** - Bombay (1885)\n**C** - Calcutta (1886)\n**M** - Madras (1887)\n**A** - Allahabad (1888 - First British President George Yule)"},{"type":"h2","text":"2. Gandhian Era (1915-1947)"},{"type":"p","text":"Gandhi ji returned from South Africa on 9 Jan 1915 (Pravasi Bharatiya Divas). His first three movements in India are crucial."},{"type":"mnemonic","topic":"Gandhi''s Initial Movements","trick":"Gandhi ate CAK (Cake)","visual":"🎂","explanation":"**C** - Champaran (1917): First Satyagraha (Against Indigo farming).\n**A** - Ahmedabad Mill Strike (1918): First Hunger Strike.\n**K** - Kheda Satyagraha (1918): First Non-Cooperation."},"",{"type":"table","instruction":"Gandhi''s Three Mass Movements","head":["Movement","Year","Cause/Event","Outcome"],"body":[["Non-Cooperation (NCM)","1920-22","Jallianwala Bagh & Khilafat Issue.","Withdrawn after Chauri-Chaura incident (Feb 1922)."],["Civil Disobedience (CDM)","1930","Breaking Salt Law (Dandi March: 12 Mar - 6 Apr).","Gandhi-Irwin Pact (1931)."],["Quit India Movement","1942","Failure of Cripps Mission. Slogan: ''Do or Die''.","British launched ''Operation Zero Hour'' to arrest leaders."]]},{"type":"h2","text":"3. Revolutionary Movement"},{"type":"p","text":"Heroes like Bhagat Singh, Chandrashekhar Azad, and Ramprasad Bismil formed HRA (1924) and later HSRA (1928)."},{"type":"highlight","level":"important","text":"Kakori Train Action: 9 August 1925.\nRevolutionaries Involved: Ramprasad Bismil, Ashfaq Ullah Khan, Roshan Singh, Rajendra Lahiri (All were hanged).","icon":"🚂"},{"type":"h2","text":"4. Madhya Pradesh Context (MP Special)"},{"type":"fact_card","title":"Key MP Events for MPPSC","facts":["Jhanda Satyagraha (1923): Started from Jabalpur (Subhadra Kumari Chauhan participated).","Tripuri Session (1939): Held in Jabalpur. Subhash Chandra Bose defeated Pattabhi Sitaramayya (Gandhi''s candidate).","Charan Paduka Massacre (1931): Chhatarpur. Called the ''Jallianwala Bagh of MP''."],"icon":"🦁"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019 / 2021","year":2019,"question":"Where was the ''Tripuri Session'' of INC held in 1939?","options":["Bhopal","Jabalpur","Indore","Gwalior"],"correct":"Jabalpur","strategy":"Tripuri is near Jabalpur. This session is famous for the Bose vs Gandhi ideological conflict."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Where did the ''Quit India Movement'' start on 8 August 1942?","options":["Bombay (Gowalia Tank)","Calcutta","Madras","Poona"],"correct":"Bombay (Gowalia Tank)","strategy":"Gandhi ji gave the ''Do or Die'' slogan at Gowalia Tank Maidan (now August Kranti Maidan)."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"Who renounced his ''Knighthood'' in protest against the Jallianwala Bagh Massacre (1919)?","options":["Mahatma Gandhi","Rabindranath Tagore","Subhash Chandra Bose","Lala Lajpat Rai"],"correct":"Rabindranath Tagore","strategy":"Tagore returned his Knighthood/Sir title, and Gandhi returned ''Kaiser-e-Hind''."},{"type":"exam_pattern","topic":"National Movement Trend","analysis":"Unit 1 Freedom Struggle Trend:","stats":["Gandhian Movements (Year/Event): 2-3 questions","INC Sessions (President/Place): 1-2 questions","Revolutionary Activities: 1 question","MP Contribution (Jhanda Satyagraha): 1 question"],"trend":"The Commission now asks specific dates (e.g., 8 Aug vs 9 Aug) and focuses on regional revolutionaries (linked with Unit 10 like Bhima Nayak)."}]}', 'history', NULL, 20, 1, 1770835700, 1771008819, 'blog', 'unit_1', 'Independence Struggle and Indian National Movement', 1, 0, 1, 1, 0, 'Unit 1: भारतीय स्वतंत्रता संघर्ष - एक महागाथा भारतीय राष्ट्रीय आंदोलन को तीन प्रमुख चरणों में समझा जा सकता है: उदारवादी चरण (1885-1905), उग्रवादी चरण (1905-1919), और गांधीवादी युग (1919-1947)। MPPSC म...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('b4004de1-07c2-4ef2-aaa8-cc6b8c9c41ce', 'integration-reorganization-india-unit-1-mppsc', 'Integration and Reorganization of India after Independence | भारत का एकीकरण और पुनर्गठन', 'Comprehensive guide to the integration of 562 princely states by Sardar Patel and the linguistic reorganization of states (1956). Covers Operation Polo, Instrument of Accession, and Fazl Ali Commission.', '{"hi":[{"type":"h2","text":"Unit 1: स्वतंत्रता के बाद भारत का एकीकरण और पुनर्गठन"},{"type":"p","text":"1947 में भारत को स्वतंत्रता तो मिली, लेकिन वह 562 देशी रियासतों (Princely States) में बंटा हुआ था। सरदार वल्लभभाई पटेल (''भारत के बिस्मार्क'') और वी.पी. मेनन ने कूटनीति और दृढ़ता से भारत का एकीकरण किया। इसके बाद 1956 में भाषाई आधार पर राज्यों का पुनर्गठन हुआ। MPPSC में ''ऑपरेशन पोलो'' और ''फजल अली आयोग'' हॉट टॉपिक्स हैं।"},{"type":"highlight","level":"critical","text":"रियासती मंत्रालय (States Department): गठन 5 जुलाई 1947।\nअध्यक्ष: सरदार पटेल।\nसचिव: वी.पी. मेनन।","icon":"🤝"},{"type":"h2","text":"1. रियासतों का विलीनीकरण (Merger of Princely States)"},{"type":"p","text":"15 अगस्त 1947 तक लगभग सभी रियासतें भारत में मिल चुकी थीं, सिवाय तीन के: जूनागढ़, हैदराबाद और जम्मू-कश्मीर। इनके विलय की कहानी परीक्षा की दृष्टि से अत्यंत महत्वपूर्ण है।"},"",{"type":"table","instruction":"तीन समस्याग्रस्त रियासतों का विलय","head":["रियासत","शासक","विलय का तरीका (Method)","तिथि"],"body":[["जूनागढ़","महाबत खान (दीवान: शाहनवाज भुट्टो)","जनमत संग्रह (Plebiscite)","फरवरी 1948"],["हैदराबाद","निजाम उस्मान अली खान","सैन्य कार्यवाही (Operation Polo)","सितंबर 1948"],["जम्मू-कश्मीर","महाराजा हरि सिंह","विलय पत्र (Instrument of Accession)","26 अक्टूबर 1947"]]},{"type":"fact_card","title":"ऑपरेशन पोलो (Operation Polo)","facts":["यह हैदराबाद के खिलाफ पुलिस कार्यवाही थी (वास्तव में सैन्य कार्यवाही)।","मेजर जनरल जे.एन. चौधरी के नेतृत्व में भारतीय सेना ने हैदराबाद में प्रवेश किया।","इसे ''पोलो'' नाम दिया गया क्योंकि हैदराबाद में दुनिया के सबसे ज्यादा पोलो मैदान थे।"],"icon":"⚔️"},{"type":"h2","text":"2. राज्यों का पुनर्गठन (Reorganization of States)"},{"type":"p","text":"स्वतंत्रता के बाद मांग उठी कि राज्यों का गठन भाषा के आधार पर हो। सरकार ने इसके लिए कई आयोग बनाए।"},{"type":"mnemonic","topic":"आयोगों का सही क्रम (Chronology)","trick":"Dhar -> JVP -> Fazl Ali (DJ Fazl)","visual":"🗺️","explanation":"1. **D**har Commission (जून 1948): एस.के. धर। इसने भाषाई आधार को खारिज किया और प्रशासनिक सुविधा को आधार माना।\n2. **J**VP Committee (दिसंबर 1948): जवाहरलाल, वल्लभभाई, पट्टाभि। इसने भी भाषाई आधार को खारिज किया।\n3. **F**azl Ali Commission (दिसंबर 1953): इसने भाषाई आधार को स्वीकार किया।"},{"type":"highlight","level":"important","text":"आंध्र प्रदेश: भाषाई आधार पर बनने वाला पहला राज्य (1 अक्टूबर 1953)।\nकारण: पोट्टी श्रीरामुलु की 56 दिनों की भूख हड़ताल के बाद मृत्यु।","icon":"🚩"},{"type":"h3","text":"फजल अली आयोग (राज्य पुनर्गठन आयोग - SRC) 1953"},{"type":"ul","items":["**सदस्य:** फजल अली (अध्यक्ष), के.एम. पणिक्कर, हृदयनाथ कुंजरू।","**सिफारिश:** राज्यों का वर्गीकरण (Part A, B, C, D) समाप्त किया जाए।","**परिणाम:** राज्य पुनर्गठन अधिनियम, 1956 पारित हुआ। 7वां संविधान संशोधन।","**नया ढांचा:** 14 राज्य और 6 केंद्र शासित प्रदेश बने।"]},{"type":"h2","text":"3. मध्य प्रदेश का गठन (MP Specific)"},{"type":"p","text":"1 नवंबर 1956 को मध्य प्रदेश का गठन हुआ। यह मुख्य रूप से 4 भागों को मिलाकर बना था: सेंट्रल प्रोविंस एंड बरार (Part A), मध्य भारत (Part B), विंध्य प्रदेश (Part C), और भोपाल (Part C)।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"हैदराबाद रियासत को भारत में मिलाने के लिए कौन सा ऑपरेशन चलाया गया था?","options":["ऑपरेशन विजय","ऑपरेशन पोलो","ऑपरेशन मेघदूत","ऑपरेशन कैक्टस"],"correct":"ऑपरेशन पोलो","strategy":"याद रखें: हैदराबाद के निजाम को ''पोलो'' खेलना पसंद था (Trick)। ऑपरेशन विजय गोवा (1961) के लिए था।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"भाषाई आधार पर गठित होने वाला भारत का प्रथम राज्य कौन सा था?","options":["आंध्र प्रदेश","गुजरात","हरियाणा","केरल"],"correct":"आंध्र प्रदेश","strategy":"1953 में मद्रास से अलग होकर तेलुगु भाषी राज्य बना।"},{"type":"pyq","exam":"UPSC / Other State PSC","year":2018,"question":"राज्य पुनर्गठन आयोग (1953) के सदस्य कौन नहीं थे?","options":["फजल अली","के.एम. पणिक्कर","हृदयनाथ कुंजरू","पट्टाभि सीतारमैया"],"correct":"पट्टाभि सीतारमैया","strategy":"पट्टाभि JVP समिति (1948) में थे, फजल अली आयोग में नहीं।"},{"type":"exam_pattern","topic":"Integration & Reorganization Trend","analysis":"Unit 1 Modern History Trend:","stats":["रियासतों का विलय (Operation/Year): 1 प्रश्न","आयोग (Dhar/SRC): 1 प्रश्न","राज्यों का गठन वर्ष (नागालैंड/सिक्किम): 1 प्रश्न"],"trend":"अब प्रश्न राज्यों के गठन के सही कालक्रम (Chronological Order) पर पूछे जा रहे हैं (जैसे: हरियाणा 1966 -> हिमाचल 1971 -> सिक्किम 1975)।"}],"en":[{"type":"h2","text":"Unit 1: Integration and Reorganization of India"},{"type":"p","text":"In 1947, India gained independence but was fragmented into 562 Princely States. Sardar Vallabhbhai Patel (''Bismarck of India'') and V.P. Menon achieved the monumental task of integrating them. Later, in 1956, states were reorganized on a linguistic basis. ''Operation Polo'' and ''Fazl Ali Commission'' are hot topics for MPPSC."},{"type":"highlight","level":"critical","text":"States Department: Formed on 5 July 1947.\nHead: Sardar Patel.\nSecretary: V.P. Menon.","icon":"🤝"},{"type":"h2","text":"1. Merger of Princely States"},{"type":"p","text":"By 15 August 1947, almost all states had acceded to India, except three: Junagadh, Hyderabad, and Jammu & Kashmir. Their integration story is crucial for exams."},"",{"type":"table","instruction":"Integration of Problematic States","head":["State","Ruler","Method of Merger","Date"],"body":[["Junagadh","Mahabat Khan (Diwan: Shah Nawaz Bhutto)","Plebiscite (Vote by people)","Feb 1948"],["Hyderabad","Nizam Osman Ali Khan","Military Action (Operation Polo)","Sept 1948"],["Jammu & Kashmir","Maharaja Hari Singh","Instrument of Accession","26 Oct 1947"]]},{"type":"fact_card","title":"Operation Polo","facts":["It was a ''Police Action'' against Hyderabad (actually a military operation).","Indian Army entered Hyderabad under Major General J.N. Chaudhuri.","Named ''Polo'' because Hyderabad had the highest number of Polo grounds in the world."],"icon":"⚔️"},{"type":"h2","text":"2. Reorganization of States"},{"type":"p","text":"After independence, there was a demand to organize states based on language. The government appointed several commissions."},{"type":"mnemonic","topic":"Chronology of Commissions","trick":"Dhar -> JVP -> Fazl Ali (DJ Fazl)","visual":"🗺️","explanation":"1. **D**har Commission (June 1948): S.K. Dhar. Rejected linguistic basis, favored administrative convenience.\n2. **J**VP Committee (Dec 1948): Jawaharlal, Vallabhbhai, Pattabhi. Also rejected linguistic basis.\n3. **F**azl Ali Commission (Dec 1953): Accepted linguistic basis."},{"type":"highlight","level":"important","text":"Andhra Pradesh: First state formed on linguistic basis (1 Oct 1953).\nReason: Death of Potti Sriramulu after a 56-day hunger strike.","icon":"🚩"},{"type":"h3","text":"Fazl Ali Commission (SRC) 1953"},{"type":"ul","items":["**Members:** Fazl Ali (Chairman), K.M. Panikkar, H.N. Kunzru.","**Recommendation:** Abolish the 4-fold classification (Part A, B, C, D) of states.","**Outcome:** States Reorganization Act, 1956 passed. 7th Constitutional Amendment.","**New Structure:** 14 States and 6 Union Territories created."]},{"type":"h2","text":"3. Formation of Madhya Pradesh (MP Specific)"},{"type":"p","text":"Madhya Pradesh was formed on 1 November 1956. It was created by merging 4 parts: Central Provinces & Berar (Part A), Madhya Bharat (Part B), Vindhya Pradesh (Part C), and Bhopal (Part C)."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Which operation was launched to annex Hyderabad state into India?","options":["Operation Vijay","Operation Polo","Operation Meghdoot","Operation Cactus"],"correct":"Operation Polo","strategy":"Remember: Nizam liked playing ''Polo''. Operation Vijay was for Goa (1961)."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which was the first state in India to be formed on a linguistic basis?","options":["Andhra Pradesh","Gujarat","Haryana","Kerala"],"correct":"Andhra Pradesh","strategy":"Formed in 1953 by separating Telugu speaking areas from Madras."},{"type":"pyq","exam":"UPSC / Other State PSC","year":2018,"question":"Who was NOT a member of the States Reorganization Commission (1953)?","options":["Fazl Ali","K.M. Panikkar","H.N. Kunzru","Pattabhi Sitaramayya"],"correct":"Pattabhi Sitaramayya","strategy":"Pattabhi was in the JVP Committee (1948), not in the Fazl Ali Commission."},{"type":"exam_pattern","topic":"Integration & Reorganization Trend","analysis":"Unit 1 Modern History Trend:","stats":["Merger of States (Operation/Year): 1 question","Commissions (Dhar/SRC): 1 question","State Formation Years (Nagaland/Sikkim): 1 question"],"trend":"Questions are now asking for the correct Chronological Order of state formation (e.g., Haryana 1966 -> Himachal 1971 -> Sikkim 1975)."}]}', 'history', NULL, 18, 1, 1770835786, 1772640815, 'blog', 'unit_1', 'Integration and Reorganization of India after Independence', 0, 0, 1, 1, 0, 'Unit 1: स्वतंत्रता के बाद भारत का एकीकरण और पुनर्गठन 1947 में भारत को स्वतंत्रता तो मिली, लेकिन वह 562 देशी रियासतों (Princely States) में बंटा हुआ था। सरदार वल्लभभाई पटेल (''भारत के बिस्मार्क'') और वी....', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('9e90df01-cce2-478c-9906-5883623db59d', 'major-dynasties-events-madhya-pradesh-unit-2', 'Major Dynasties & Historical Events of Madhya Pradesh | म.प्र. के प्रमुख राजवंश और घटनाएं', 'Complete coverage of MP''s history for Unit 2. Detailed analysis of Chandela, Paramara, Holkar, Scindia dynasties and key freedom struggle events like Charan Paduka and 1857 Revolt.', '{"hi":[{"type":"h2","text":"Unit 2: मध्य प्रदेश का इतिहास - राजवंश और घटनाएं"},{"type":"p","text":"MPPSC Prelims में Unit 2 का सबसे अधिक भार (Weightage) इसी टॉपिक पर है। हर साल 3-4 प्रश्न सीधे राजवंशों (संस्थापक, राजधानी, स्थापत्य) और स्वतंत्रता आंदोलन में MP की भूमिका से पूछे जाते हैं।"},{"type":"h2","text":"1. प्राचीन और मध्यकालीन राजवंश (Major Dynasties)"},{"type":"h3","text":"चंदेल वंश (The Chandelas of Jejakabhukti)"},{"type":"fact_card","title":"चंदेल वंश: त्वरित तथ्य","facts":["संस्थापक: नन्नुक (Nannuk)","राजधानी: खजुराहो (प्रारंभ में महोबा/कालिंजर)","महान शासक: विद्याधर (इन्होंने महमूद गजनवी का सफल प्रतिरोध किया था)।","योगदान: खजुराहो के मंदिर (कंदरिया महादेव - विद्याधर द्वारा)।"],"icon":"v"},{"type":"h3","text":"परमार वंश (The Paramaras of Malwa)"},{"type":"p","text":"मालवा के स्वर्ण युग का प्रतिनिधित्व करता है। राजा भोज इस वंश के सबसे प्रतापी शासक थे।"},{"type":"mnemonic","topic":"परमार राजधानियाँ","trick":"Ujjain से Dhar गई Bhoj की सवारी","visual":"👑","explanation":"प्रारंभिक राजधानी: उज्जैन (Ujjain)।\nबाद की राजधानी: धार (Dhar) - राजा भोज ने स्थानांतरित की।"},{"type":"highlight","level":"critical","text":"राजा भोज (1010-1055 AD): ''कविराज'' की उपाधि।\nरचनाएँ: सरस्वती कंठाभरण, समरांगण सूत्रधार (वास्तुकला), आयुर्वेद सर्वस्व।\nनिर्माण: भोजताल (भोपाल) और धार में भोजशाला (सरस्वती मंदिर)।","icon":"📚"},{"type":"h3","text":"होलकर और सिंधिया (मराठा काल)"},{"type":"table","instruction":"होलकर बनाम सिंधिया","head":["वंश","संस्थापक","राजधानी","प्रमुख शासक"],"body":[["होलकर (Indore)","मल्हार राव होलकर","इंदौर (महेश्वर - अहिल्याबाई के समय)","देवी अहिल्याबाई (न्याय और धर्म के लिए प्रसिद्ध)"],["सिंधिया (Gwalior)","राणोजी सिंधिया","उज्जैन (प्रारंभ में) -> ग्वालियर (दौलतराव ने बदली)","महादजी सिंधिया (पानीपत के बाद पुनर्स्थापना)"]]},{"type":"h2","text":"2. मध्य प्रदेश की प्रमुख ऐतिहासिक घटनाएं"},{"type":"h3","text":"1857 की क्रांति और मध्य प्रदेश"},{"type":"p","text":"MP में क्रांति की शुरुआत 3 जून 1857 को नीमच छावनी (Neemuch Cantonment) से हुई थी।"},{"type":"ul","items":["**ग्वालियर:** तात्या टोपे और रानी लक्ष्मीबाई ने विद्रोह किया।","**इन्दौर (महू):** सआदत खान (Saadat Khan) ने होल्कर सैनिकों के साथ विद्रोह किया।","**सागर:** शेख रमजान (Sheikh Ramzan) ने नेतृत्व किया।","**मंडला/रामगढ़:** रानी अवंतीबाई (Rani Avantibai) - खेड़ी का युद्ध लड़ा।"]},{"type":"h3","text":"स्वतंत्रता संग्राम की अन्य घटनाएं"},{"type":"fact_card","title":"चरण पादुका नरसंहार (Charan Paduka Massacre)","facts":["तिथि: 14 जनवरी 1931 (मकर संक्रांति)","स्थान: छतरपुर (उर्मिल नदी के तट पर)","घटना: कर्नल फिशर ने शांतिपूर्ण सभा पर गोलियां चलवाईं।","उपनाम: ''मध्य प्रदेश का जलियांवाला बाग''।"],"icon":"🔫"},{"type":"highlight","level":"important","text":"झंडा सत्याग्रह (Flag Satyagraha): 1923 में जबलपुर से शुरू हुआ। सुंदरलाल और सुभद्रा कुमारी चौहान ने नेतृत्व किया। बाद में इसका केंद्र नागपुर बना।","icon":"🇮🇳"},{"type":"h3","text":"जंगल सत्याग्रह (1930)"},{"type":"p","text":"सविनय अवज्ञा आंदोलन के दौरान सिवनी (टुरिया) और घोड़ाडोंगरी (बैतूल) में आदिवासियों ने जंगल कानून तोड़ा। गंजन सिंह कोरकू (बैतूल) प्रमुख नेता थे।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"राजा भोज के किस कवि ने ''जैन धर्म'' अपना लिया था?","options":["धनपाल","महिपाल","राजपाल","सोमदेव"],"correct":"धनपाल","strategy":"धनपाल ने ''तिलक मंजरी'' लिखी थी। वे परमार दरबार के रत्न थे।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"1857 के विद्रोह के समय ''सागर'' में विद्रोह का नेतृत्व किसने किया था?","options":["शेख रमजान","सआदत खान","शंकर शाह","बख्तावर सिंह"],"correct":"शेख रमजान","strategy":"सागर में ''रमजान'' (Ramzan) -> शेख रमजान। (याद रखें: शंकर शाह गढ़ा मंडला के थे)।"},{"type":"pyq","exam":"MPPSC Prelims 2022","year":2022,"question":"किस चंदेल राजा ने महमूद गजनवी का सामना किया था?","options":["धंगदेव","विद्याधर","कीर्तिवर्मन","यशोवर्मन"],"correct":"विद्याधर","strategy":"विद्याधर एकमात्र भारतीय राजा थे जो गजनवी से हारे नहीं, बल्कि संधि की।"},{"type":"exam_pattern","topic":"MP History Trend","analysis":"Unit 2 History Analysis:","stats":["राजवंश (राजधानी/शासक): 2-3 प्रश्न","1857 की क्रांति (स्थान/नेता): 1-2 प्रश्न","हत्याकांड/सत्याग्रह (तारीख): 1 प्रश्न"],"trend":"अब आयोग रियासतों (Unit 5 के साथ ओवरलैप) और कम प्रसिद्ध आदिवासी विद्रोहों (जैसे भीमा नायक का कार्यक्षेत्र) पर गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 2: History of Madhya Pradesh - Dynasties & Events"},{"type":"p","text":"This topic carries the highest weightage in Unit 2 for MPPSC Prelims. Every year, 3-4 questions are directly asked about Dynasties (Founders, Capitals, Architecture) and MP''s role in the Freedom Struggle."},{"type":"h2","text":"1. Major Dynasties (Ancient & Medieval)"},{"type":"h3","text":"Chandela Dynasty (Jejakabhukti)"},{"type":"fact_card","title":"Chandelas: Quick Facts","facts":["Founder: Nannuk","Capital: Khajuraho (Initially Mahoba/Kalinjar)","Greatest Ruler: Vidyadhar (Successfully resisted Mahmud Ghaznavi).","Contribution: Khajuraho Temples (Kandariya Mahadev built by Vidyadhar)."],"icon":"v"},{"type":"h3","text":"Paramara Dynasty (Malwa)"},{"type":"p","text":"Represents the Golden Age of Malwa. Raja Bhoj was the most illustrious ruler."},{"type":"mnemonic","topic":"Paramara Capitals","trick":"Ujjain to Dhar - Bhoj''s Ride","visual":"👑","explanation":"Initial Capital: Ujjain.\nLater Capital: Dhar - Shifted by Raja Bhoj."},{"type":"highlight","level":"critical","text":"Raja Bhoj (1010-1055 AD): Title ''Kaviraj''.\nWorks: Saraswati Kanthabharana, Samarangana Sutradhara (Architecture), Ayurveda Sarvasva.\nConstruction: Bhojtal (Bhopal) and Bhojshala (Saraswati Temple) in Dhar.","icon":"📚"},{"type":"h3","text":"Holkar & Scindia (Maratha Period)"},{"type":"table","instruction":"Holkar vs Scindia","head":["Dynasty","Founder","Capital","Key Ruler"],"body":[["Holkar (Indore)","Malhar Rao Holkar","Indore (Maheshwar - during Ahilyabai''s time)","Devi Ahilyabai (Famous for justice & temple building)"],["Scindia (Gwalior)","Ranoji Scindia","Ujjain (Initially) -> Gwalior (Shifted by Daulatrao)","Mahadji Scindia (Resurrected Maratha power after Panipat)"]]},{"type":"h2","text":"2. Major Historical Events of MP"},{"type":"h3","text":"Revolt of 1857 in MP"},{"type":"p","text":"The revolt in MP started on 3rd June 1857 from Neemuch Cantonment."},{"type":"ul","items":["**Gwalior:** Tatya Tope and Rani Lakshmibai revolted.","**Indore (Mhow):** Saadat Khan revolted with Holkar troops.","**Sagar:** Led by Sheikh Ramzan.","**Mandla/Ramgarh:** Rani Avantibai - Fought the Battle of Kheri."]},{"type":"h3","text":"Freedom Struggle Events"},{"type":"fact_card","title":"Charan Paduka Massacre","facts":["Date: 14 January 1931 (Makar Sankranti)","Place: Chhatarpur (Bank of Urmil River)","Event: Colonel Fisher opened fire on a peaceful meeting.","Nickname: ''Jallianwala Bagh of Madhya Pradesh''."],"icon":"🔫"},{"type":"highlight","level":"important","text":"Flag Satyagraha (Jhanda Satyagraha): Started in 1923 from Jabalpur. Led by Sundarlal and Subhadra Kumari Chauhan. Later shifted to Nagpur.","icon":"🇮🇳"},{"type":"h3","text":"Jungle Satyagraha (1930)"},{"type":"p","text":"Tribals broke forest laws in Seoni (Turia) and Ghoradongri (Betul) during the Civil Disobedience Movement. Ganjan Singh Korku (Betul) was a key leader."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Which poet of Raja Bhoj''s court adopted Jainism?","options":["Dhanpal","Mahipal","Rajpal","Somdev"],"correct":"Dhanpal","strategy":"Dhanpal wrote ''Tilak Manjari''. He was a gem of the Paramara court."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Who led the revolt of 1857 in ''Sagar''?","options":["Sheikh Ramzan","Saadat Khan","Shankar Shah","Bakhtawar Singh"],"correct":"Sheikh Ramzan","strategy":"In Sagar -> ''Ramzan''. (Remember: Shankar Shah was from Garha Mandla)."},{"type":"pyq","exam":"MPPSC Prelims 2022","year":2022,"question":"Which Chandela King faced Mahmud Ghaznavi?","options":["Dhangdev","Vidyadhar","Kirtivarman","Yashovarman"],"correct":"Vidyadhar","strategy":"Vidyadhar was the only Indian king who did not lose to Ghaznavi but concluded a treaty."},{"type":"exam_pattern","topic":"MP History Trend","analysis":"Unit 2 History Analysis:","stats":["Dynasties (Capital/Ruler): 2-3 questions","1857 Revolt (Place/Leader): 1-2 questions","Massacres/Satyagraha (Dates): 1 question"],"trend":"The Commission is now digging deeper into Princely States (overlap with Unit 5) and lesser-known Tribal revolts (like Bhima Nayak''s area of operation)."}]}', 'mp_gk', NULL, 20, 1, 1770835927, 1771008846, 'blog', 'unit_2', 'Major Events and Major Dynasties of Madhya Pradesh', 0, 1, 1, 1, 0, 'Unit 2: मध्य प्रदेश का इतिहास - राजवंश और घटनाएं MPPSC Prelims में Unit 2 का सबसे अधिक भार (Weightage) इसी टॉपिक पर है। हर साल 3-4 प्रश्न सीधे राजवंशों (संस्थापक, राजधानी, स्थापत्य) और स्वतंत्रता आंदो...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('5f026784-aefb-41f5-9600-6c667c8f41ef', 'contribution-mp-freedom-movement-unit-2', 'Contribution of Madhya Pradesh in Freedom Movement | स्वतंत्रता संग्राम में म.प्र. का योगदान', 'Comprehensive guide to MP''s role in the Indian Freedom Struggle. Covers 1857 Revolt in MP, Jhanda Satyagraha, Jungle Satyagraha, and key freedom fighters like Chandrashekhar Azad and Tatya Tope.', '{"hi":[{"type":"h2","text":"Unit 2: स्वतंत्रता संग्राम में मध्य प्रदेश का योगदान"},{"type":"p","text":"भारतीय स्वतंत्रता संग्राम में मध्य प्रदेश की भूमि ने अनेक वीरों और आंदोलनों को जन्म दिया है। 1857 की क्रांति से लेकर 1942 के भारत छोड़ो आंदोलन तक, MP के क्रांतिकारियों और सत्याग्रहियों ने ब्रिटिश सत्ता को कड़ी चुनौती दी। यह टॉपिक MPPSC के लिए ''Hotspot'' है।"},{"type":"h2","text":"1. 1857 की क्रांति और मध्य प्रदेश"},{"type":"p","text":"MP में क्रांति की चिंगारी सबसे पहले **3 जून 1857** को नीमच छावनी (Neemuch Cantonment) में भड़की। इसके बाद यह आग पूरे प्रदेश में फैल गई।"},"",{"type":"table","instruction":"1857: प्रमुख केंद्र और नेतृत्वकर्ता","head":["स्थान","नेतृत्वकर्ता","विशेषता"],"body":[["ग्वालियर/झांसी","रानी लक्ष्मीबाई, तात्या टोपे","ह्यूरोज़ (Hugh Rose) से संघर्ष। रानी की समाधि ग्वालियर में है।"],["इन्दौर (महू)","सआदत खान","होलकर सेना ने विद्रोह किया।"],["गढ़ा मंडला","रानी अवंतीबाई","रामगढ़ की रानी। खेड़ी के युद्ध में अंग्रेजों को हराया।"],["अमझेरा (धार)","राणा बख्तावर सिंह","मालवा के प्रमुख विद्रोही। इन्हें इंदौर में फांसी दी गई।"],["राघोगढ़","राजा ठाकुर प्रसाद","गुना क्षेत्र।"]]},{"type":"highlight","level":"critical","text":"शहीद चैन सिंह (1824): नरसिंहगढ़ के राजकुमार। इन्हें ''मध्य प्रदेश का मंगल पांडे'' कहा जाता है। सिहोर के दशहरा मैदान में इन्होंने अंग्रेजों (मैकडोनल्ड) से युद्ध किया और शहीद हुए।","icon":"⚔️"},{"type":"h2","text":"2. प्रमुख सत्याग्रह और आंदोलन"},{"type":"h3","text":"झंडा सत्याग्रह (1923)"},{"type":"p","text":"यह राष्ट्रीय स्तर का आंदोलन था जिसकी शुरुआत **जबलपुर** से हुई।\n**कारण:** टाउन हॉल पर तिरंगा फहराने से रोका जाना।\n**नेतृत्व:** सुंदरलाल, सुभद्रा कुमारी चौहान, माखनलाल चतुर्वेदी।\n**परिणाम:** बाद में इसका केंद्र नागपुर बना और वल्लभभाई पटेल ने नेतृत्व संभाला।"},{"type":"h3","text":"जंगल सत्याग्रह (1930)"},{"type":"p","text":"सविनय अवज्ञा आंदोलन के दौरान आदिवासियों ने जंगल कानून तोड़े।"},{"type":"ul","items":["**टुरिया (सिवनी):** दुर्गा शंकर मेहता के नेतृत्व में। यहाँ पुलिस गोलीबारी में 4 आदिवासी शहीद हुए।","**घोड़ाडोंगरी (बैतूल):** गंजन सिंह कोरकू (Ganjan Singh Korku) ने नेतृत्व किया।"]},{"type":"fact_card","title":"चरण पादुका नरसंहार (1931)","facts":["उपनाम: MP का जलियांवाला बाग।","तिथि: 14 जनवरी 1931 (मकर संक्रांति)।","स्थान: छतरपुर (उर्मिल नदी)।","आदेश: कर्नल फिशर (Col. Fisher) ने गोलियां चलवाईं।","शहीद: सुंदरलाल, धर्मदास, आदि।"],"icon":"🔫"},{"type":"h2","text":"3. प्रमुख क्रांतिकारी व्यक्तित्व"},{"type":"highlight","level":"important","text":"चंद्रशेखर आजाद: जन्म भाबरा (अलीराजपुर) में। ''हिंदुस्तान सोशलिस्ट रिपब्लिकन एसोसिएशन'' (HSRA) के कमांडर-इन-चीफ। अल्फ्रेड पार्क (प्रयागराज) में शहीद हुए।","icon":"🔥"},{"type":"ul","items":["**टंट्या भील (Tantya Bhil):** ''इंडियन रॉबिनहुड'' (Indian Robinhood)। निमाड़ क्षेत्र में सक्रिय।","**भीमा नायक:** बड़वानी (सेंधवा) के क्रांतिकारी। अंबापानी के युद्ध में अंग्रेजों से लड़े।","**शंकर शाह और रघुनाथ शाह:** गढ़ा मंडला के गोंड शासक। इन्हें तोप के मुँह से बांधकर उड़ा दिया गया था।"]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"1857 के विद्रोह के दौरान ''भोपाल'' में विद्रोह का नेतृत्व किसने किया था?","options":["फाजिल मोहम्मद खान","शेख रमजान","दोस्त मोहम्मद","हबीबुल्ला"],"correct":"फाजिल मोहम्मद खान","strategy":"भोपाल में बेगमों का शासन था, लेकिन फाजिल मोहम्मद और आदिल मोहम्मद ने गढ़ी (अंबापानी) से विद्रोह किया था।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"''मध्य प्रदेश का जलियांवाला बाग'' किसे कहा जाता है?","options":["चरण पादुका नरसंहार","झाबुआ नरसंहार","मांडू नरसंहार","अमझेरा नरसंहार"],"correct":"चरण पादुका नरसंहार","strategy":"छतरपुर में मकर संक्रांति (1931) के दिन हुआ था।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"शहीद चैन सिंह की छतरी (Cenotaph) कहाँ स्थित है?","options":["नरसिंहगढ़","भोपाल","सीहोर","विदिशा"],"correct":"सीहोर","strategy":"वे नरसिंहगढ़ के थे, लेकिन युद्ध सीहोर के दशहरा मैदान में हुआ, वहीं उनकी समाधि है।"},{"type":"exam_pattern","topic":"Freedom Movement MP Trend","analysis":"Unit 2 MP History Trend:","stats":["1857 के नेता (क्षेत्रवार): 2 प्रश्न","सत्याग्रह (स्थान/नेता): 1 प्रश्न","जनजातीय व्यक्तित्व (Tribal Leaders): 1-2 प्रश्न"],"trend":"आयोग अब ''जनजातीय क्रांतिकारियों'' (Tribal Revolutionaries) पर विशेष ध्यान दे रहा है। (Unit 10 और Unit 2 का Intersection)।"}],"en":[{"type":"h2","text":"Unit 2: Contribution of Madhya Pradesh in Freedom Movement"},{"type":"p","text":"The land of Madhya Pradesh gave birth to many heroes and movements in the Indian Freedom Struggle. From the Revolt of 1857 to the Quit India Movement of 1942, revolutionaries and satyagrahis from MP challenged British power. This is a ''Hotspot'' topic for MPPSC."},{"type":"h2","text":"1. Revolt of 1857 in MP"},{"type":"p","text":"The spark of revolt in MP was first ignited on **3rd June 1857** at Neemuch Cantonment. From there, the fire spread across the state."},"",{"type":"table","instruction":"1857: Major Centers & Leaders","head":["Place","Leader","Key Feature"],"body":[["Gwalior/Jhansi","Rani Lakshmibai, Tatya Tope","Fought against Hugh Rose. Rani''s tomb is in Gwalior."],["Indore (Mhow)","Saadat Khan","Holkar troops revolted under him."],["Garha Mandla","Rani Avantibai","Queen of Ramgarh. Defeated British in Battle of Kheri."],["Amjhera (Dhar)","Rana Bakhtawar Singh","Major rebel of Malwa. Hanged in Indore."],["Raghogarh","Raja Thakur Prasad","Guna region."]]},{"type":"highlight","level":"critical","text":"Shaheed Chain Singh (1824): Prince of Narsinghgarh. Known as the ''Mangal Pandey of MP''. Fought against British (Maddox) at Dussehra Maidan, Sehore and was martyred.","icon":"⚔️"},{"type":"h2","text":"2. Major Satyagrahas & Movements"},{"type":"h3","text":"Flag Satyagraha (Jhanda Satyagraha) - 1923"},{"type":"p","text":"A national-level movement that started from **Jabalpur**.\n**Cause:** Prevention of hoisting the Tricolor on Town Hall.\n**Leaders:** Sundarlal, Subhadra Kumari Chauhan, Makhanlal Chaturvedi.\n**Outcome:** Later the center shifted to Nagpur led by Vallabhbhai Patel."},{"type":"h3","text":"Jungle Satyagraha (1930)"},{"type":"p","text":"Tribals broke forest laws during the Civil Disobedience Movement."},{"type":"ul","items":["**Turia (Seoni):** Led by Durga Shankar Mehta. 4 tribals were martyred in police firing.","**Ghoradongri (Betul):** Led by Ganjan Singh Korku."]},{"type":"fact_card","title":"Charan Paduka Massacre (1931)","facts":["Nickname: Jallianwala Bagh of MP.","Date: 14 January 1931 (Makar Sankranti).","Place: Chhatarpur (Bank of Urmil River).","Order: Col. Fisher opened fire.","Martyrs: Sundarlal, Dharmadas, etc."],"icon":"🔫"},{"type":"h2","text":"3. Key Revolutionary Personalities"},{"type":"highlight","level":"important","text":"Chandrashekhar Azad: Born in Bhabra (Alirajpur). Commander-in-Chief of HSRA. Martyred at Alfred Park (Prayagraj).","icon":"🔥"},{"type":"ul","items":["**Tantya Bhil:** ''Indian Robinhood''. Active in Nimar region.","**Bhima Nayak:** Revolutionary from Barwani (Sendhwa). Fought Battle of Ambapani.","**Shankar Shah & Raghunath Shah:** Gond rulers of Garha Mandla. They were blown up by a cannon."]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Who led the revolt of 1857 in ''Bhopal''?","options":["Fazil Mohammad Khan","Sheikh Ramzan","Dost Mohammad","Habibullah"],"correct":"Fazil Mohammad Khan","strategy":"Though Begums ruled Bhopal, Fazil Mohammad and Adil Mohammad revolted from Garhi (Ambapani)."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which event is known as the ''Jallianwala Bagh of Madhya Pradesh''?","options":["Charan Paduka Massacre","Jhabua Massacre","Mandu Massacre","Amjhera Massacre"],"correct":"Charan Paduka Massacre","strategy":"Happened on Makar Sankranti (1931) in Chhatarpur."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"Where is the Cenotaph (Chhatri) of Shaheed Chain Singh located?","options":["Narsinghgarh","Bhopal","Sehore","Vidisha"],"correct":"Sehore","strategy":"He was from Narsinghgarh, but the battle and his martyrdom took place at Dussehra Maidan, Sehore."},{"type":"exam_pattern","topic":"Freedom Movement MP Trend","analysis":"Unit 2 MP History Trend:","stats":["1857 Leaders (Region-wise): 2 questions","Satyagraha (Place/Leader): 1 question","Tribal Leaders: 1-2 questions"],"trend":"The Commission is now focusing heavily on ''Tribal Revolutionaries'' (Intersection of Unit 10 and Unit 2)."}]}', 'mp_gk', NULL, 15, 1, 1770836060, 1771008847, 'blog', 'unit_2', 'Contribution of Madhya Pradesh in Freedom Movement', 1, 0, 1, 1, 0, 'Unit 2: स्वतंत्रता संग्राम में मध्य प्रदेश का योगदान भारतीय स्वतंत्रता संग्राम में मध्य प्रदेश की भूमि ने अनेक वीरों और आंदोलनों को जन्म दिया है। 1857 की क्रांति से लेकर 1942 के भारत छोड़ो आंदोलन तक, ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('ffb2a723-7a11-4efb-82d9-1053e4b3227e', 'major-arts-sculpture-madhya-pradesh-unit-2', 'Major Arts and Sculpture of Madhya Pradesh | म.प्र. की प्रमुख कला और स्थापत्य', 'Master MP''s Art & Culture for Unit 2. Covers Khajuraho temples, Sanchi Stupa, Folk Paintings (Pithora, Gond), and Handicrafts (GI Tags) with mnemonics.', '{"hi":[{"type":"h2","text":"Unit 2: मध्य प्रदेश की कला और स्थापत्य (Art & Architecture)"},{"type":"p","text":"मध्य प्रदेश को भारत का ''कला हृदय'' कहा जा सकता है। यहाँ प्रागैतिहासिक भीमबेटका से लेकर चंदेलों के खजुराहो मंदिर और गुप्तकालीन उदयगिरि की गुफाएं मौजूद हैं। MPPSC में ''लोक चित्रकला'' (Folk Painting) और ''हस्तशिल्प'' (Handicrafts) से प्रश्न लगातार बढ़ रहे हैं।"},{"type":"h2","text":"1. स्थापत्य और मूर्तिकला (Sculpture & Architecture)"},{"type":"h3","text":"खजुराहो के मंदिर (The Temples of Khajuraho)"},{"type":"highlight","level":"critical","text":"शैली: नागर शैली (पंचायतन)।\nनिर्माण: चंदेल शासक (950-1050 ई.)।\nस्थिति: छतरपुर जिला।\nयूनेस्को विश्व धरोहर: 1986 में शामिल।","icon":"v"},{"type":"table","instruction":"खजुराहो के मंदिर समूह","head":["समूह (Group)","प्रमुख मंदिर","धर्म/विशेषता"],"body":[["पश्चिमी समूह (Western)","कंदरिया महादेव, चौसठ योगिनी, लक्ष्मण मंदिर","सबसे प्रमुख और बड़े मंदिर। (कंदरिया महादेव विद्याधर ने बनवाया)।"],["पूर्वी समूह (Eastern)","पार्श्वनाथ, आदिनाथ, घंटाई मंदिर","मुख्य रूप से जैन धर्म को समर्पित।"],["दक्षिणी समूह (Southern)","दूल्हादेव, चतुर्भुज मंदिर","भगवान शिव और विष्णु को समर्पित।"]]},{"type":"h3","text":"स्तूप और गुफा कला (Stupa & Cave Art)"},{"type":"ul","items":["**सांची स्तूप (रायसेन):** मौर्य सम्राट अशोक द्वारा निर्मित। शुंग काल में इसकी रेलिंग (Vedika) पत्थर की बनाई गई। (UNESCO: 1989)।","**भरहुत स्तूप (सतना):** अब इसके अवशेष कोलकाता संग्रहालय में हैं। अलेक्जेंडर कनिंघम ने खोजा था।","**उदयगिरि की गुफाएं (विदिशा):** गुप्तकालीन। गुफा नं. 5 में ''वराह अवतार'' की विशाल प्रतिमा प्रसिद्ध है।"]},"",{"type":"h2","text":"2. मध्य प्रदेश की चित्रकला (Paintings of MP)"},{"type":"p","text":"यहाँ की चित्रकला दो रूपों में मिलती है: ऐतिहासिक गुफा चित्र और जनजातीय लोक चित्रकला।"},{"type":"fact_card","title":"बाघ की गुफाएं (Bagh Caves)","facts":["स्थान: धार (बाघिन नदी के तट पर)।","तुलना: अजंता की गुफाओं से।","खोज: डेंजरफील्ड (1818)।","विशेषता: इसे ''रंगमहल'' कहा जाता है। यह बौद्ध धर्म से संबंधित है।"],"icon":"🎨"},{"type":"h3","text":"MPPSC अब पद्म श्री विजेता कलाकारों के नाम पूछता है।"},{"type":"mnemonic","topic":"लोक चित्रकला और जनजाति","trick":"भीलों की पिथोरा, गोंडों की डिगना","visual":"🖌️","explanation":"**पिथोरा (Pithora):** भील जनजाति (Bhil)। कलाकार: भूरी बाई (पद्म श्री), पेमा फाल्या।\n**गोंड चित्रकला (Gond Art):** गोंड जनजाति। कलाकार: जनगढ़ सिंह श्याम, भज्जू श्याम, दुर्गा बाई व्याम।"},{"type":"h2","text":"3. हस्तशिल्प (Handicrafts)"},{"type":"ul","items":["**चंदेरी साड़ी (अशोकनगर):** GI Tag प्राप्त। रेशमी और सूती धागे का मिश्रण।","**महेश्वरी साड़ी (खरगोन):** देवी अहिल्याबाई ने संरक्षण दिया।","**धातु शिल्प (Bell Metal):** टीकमगढ़ और बैतूल का ''भरेवा शिल्प'' (Bharewa Art) प्रसिद्ध है।","**बाघ प्रिंट (Bagh Print):** धार जिले में कपड़ों पर ठप्पा छपाई (Block Printing)। (इस्माइल सुलेमानजी खत्री)।"]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"''पिथोरा'' भित्ति चित्रकला किस जनजाति से संबंधित है?","options":["गोंड","भील","बैगा","कोरकू"],"correct":"भील","strategy":"पिथोरा भील जनजाति की विशिष्ट कला है, जिसके प्रमुख कलाकार पेमा फाल्या थे।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"खजुराहो के मंदिर किस जिले में स्थित हैं?","options":["मंडला","छतरपुर","बालाघाट","रीवा"],"correct":"छतरपुर","strategy":"खजुराहो छतरपुर जिले में आता है। पहले यह महोबा (UP) के पास चंदेलों की राजधानी था।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"प्रसिद्ध कलाकार ''भूरी बाई'' किस कला क्षेत्र से संबंधित हैं?","options":["संगीत","नृत्य","चित्रकला","रंगमंच"],"correct":"चित्रकला","strategy":"भूरी बाई (झाबुआ) को पिथोरा चित्रकला के लिए पद्म श्री मिला है। वे भारत भवन (भोपाल) से जुड़ी रही हैं।"},{"type":"exam_pattern","topic":"MP Art & Culture Trend","analysis":"Unit 2 Art Trend:","stats":["जनजातीय कलाकार (Artist/Tribe): 2 प्रश्न","पर्यटन स्थल (खजुराहो/सांची): 1 प्रश्न","हस्तशिल्प (GI Tags): 1 प्रश्न"],"trend":"साधारण प्रश्नों (जैसे सांची कहाँ है?) की जगह अब कलाकारों के नाम और विशिष्ट शैलियों (जैसे कंघी कला - बंजारा) पर प्रश्न पूछे जा रहे हैं।"}],"en":[{"type":"h2","text":"Unit 2: Arts and Architecture of Madhya Pradesh"},{"type":"p","text":"Madhya Pradesh can be called the ''Art Heart'' of India. From prehistoric Bhimbetka to Chandelas'' Khajuraho and Gupta period Udayagiri caves, it has it all. In MPPSC, questions on ''Folk Painting'' and ''Handicrafts'' are consistently increasing."},{"type":"h2","text":"1. Sculpture & Architecture"},{"type":"h3","text":"The Temples of Khajuraho"},{"type":"highlight","level":"critical","text":"Style: Nagara Style (Panchayatan).\nBuilders: Chandela Rulers (950-1050 AD).\nLocation: Chhatarpur District.\nUNESCO Site: Since 1986.","icon":"v"},{"type":"table","instruction":"Khajuraho Temple Groups","head":["Group","Major Temples","Religion/Feature"],"body":[["Western Group","Kandariya Mahadev, Chausath Yogini, Lakshmana","Most important & grandest. Kandariya built by Vidyadhar."],["Eastern Group","Parshvanath, Adinath, Ghantai","Mainly dedicated to Jainism."],["Southern Group","Dulhadev, Chaturbhuj Temple","Dedicated to Lord Shiva and Vishnu."]]},{"type":"h3","text":"Stupa & Cave Art"},{"type":"ul","items":["**Sanchi Stupa (Raisen):** Built by Ashoka. Stone railing added during Shunga period. (UNESCO: 1989).","**Bharhut Stupa (Satna):** Remains are now in Kolkata Museum. Discovered by Alexander Cunningham.","**Udayagiri Caves (Vidisha):** Gupta Period. Cave No. 5 is famous for the colossal ''Varaha Avatar'' statue."]},"",{"type":"h2","text":"2. Paintings of Madhya Pradesh"},{"type":"p","text":"Paintings here are found in two forms: Historical Cave paintings and Tribal Folk paintings."},{"type":"fact_card","title":"Bagh Caves","facts":["Location: Dhar (Bank of Baghini River).","Comparison: With Ajanta Caves.","Discovery: Dangerfield (1818).","Feature: Called ''Rangmahal''. Related to Buddhism."],"icon":"🎨"},{"type":"h3","text":"Tribal Paintings (Most Important)"},{"type":"mnemonic","topic":"Folk Painting & Tribes","trick":"Bhils do Pithora, Gonds do Digna","visual":"🖌️","explanation":"**Pithora:** Bhil Tribe. Artists: Bhuri Bai (Padma Shri), Pema Phalya.\n**Gond Art:** Gond Tribe. Artists: Jangarh Singh Shyam, Bhajju Shyam, Durga Bai Vyam."},{"type":"h2","text":"3. Handicrafts (Shilp Kala)"},{"type":"ul","items":["**Chanderi Saree (Ashoknagar):** GI Tagged. Silk and Cotton blend.","**Maheshwari Saree (Khargone):** Patronized by Devi Ahilyabai.","**Bell Metal (Dhokra/Bharewa):** Tikamgarh and Betul are famous for ''Bharewa Art''.","**Bagh Print (Dhar):** Block printing on fabric. (Ismail Sulemanji Khatri)."]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"''Pithora'' mural painting is associated with which tribe?","options":["Gond","Bhil","Baiga","Korku"],"correct":"Bhil","strategy":"Pithora is a unique art form of the Bhil tribe, famously practiced by Pema Phalya."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"In which district are the Khajuraho temples located?","options":["Mandla","Chhatarpur","Balaghat","Rewa"],"correct":"Chhatarpur","strategy":"Khajuraho falls in Chhatarpur district. It was the cultural capital of Chandelas."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Famous artist ''Bhuri Bai'' is associated with which art form?","options":["Music","Dance","Painting","Theatre"],"correct":"Painting","strategy":"Bhuri Bai (Jhabua) received Padma Shri for Pithora Painting. She has been associated with Bharat Bhavan."},{"type":"exam_pattern","topic":"MP Art & Culture Trend","analysis":"Unit 2 Art Trend:","stats":["Tribal Artists (Name/Tribe): 2 questions","Tourist Sites (Khajuraho/Sanchi): 1 question","Handicrafts (GI Tags): 1 question"],"trend":"Instead of basic location questions, the Commission is now asking names of Artists and specific art styles (e.g., Comb Art - Banjara)."}]}', 'mp_gk', NULL, 18, 1, 1770836123, 1771008848, 'blog', 'unit_2', 'Major Arts and Sculpture of Madhya Pradesh', 1, 0, 1, 1, 0, 'Unit 2: मध्य प्रदेश की कला और स्थापत्य (Art & Architecture) मध्य प्रदेश को भारत का ''कला हृदय'' कहा जा सकता है। यहाँ प्रागैतिहासिक भीमबेटका से लेकर चंदेलों के खजुराहो मंदिर और गुप्तकालीन उदयगिरि की गुफा...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('a4de5a8a-59a5-436c-8b25-e02a9ecba203', 'major-tribes-dialects-madhya-pradesh-unit-2', 'Major Tribes and Dialects of Madhya Pradesh | म.प्र. की प्रमुख जनजातियां और बोलियां', 'Comprehensive guide to MP''s tribal landscape for Unit 2. Covers Bhil, Gond, Baiga cultures, festivals like Bhagoria, and major dialects like Bundeli and Malwi.', '{"hi":[{"type":"h2","text":"Unit 2: मध्य प्रदेश - एक जनजातीय प्रदेश"},{"type":"p","text":"मध्य प्रदेश को ''जनजातीय प्रदेश'' (Tribal State) कहा जाता है क्योंकि 2011 की जनगणना के अनुसार यहाँ की 21.1% जनसंख्या अनुसूचित जनजाति (ST) है। Unit 2 में जनजातियों की ''संस्कृति'' (विवाह, त्योहार, नृत्य) और प्रदेश की ''बोलियों'' (Dialects) से प्रश्न पूछे जाते हैं।"},"",{"type":"h2","text":"1. प्रमुख जनजातियां (Major Tribes)"},{"type":"h3","text":"भील (Bhil)"},{"type":"ul","items":["**क्षेत्र:** पश्चिमी मध्य प्रदेश (झाबुआ, अलीराजपुर, धार)।","**स्थिति:** जनसंख्या की दृष्टि से MP की ''सबसे बड़ी'' जनजाति।","**उप-जातियां:** भिलाला (उच्च वर्ग), पटलिया, बारेला।","**संस्कृति:** ''पिथोरा'' चित्रकला (पेमा फाल्या) और ''भगोरिया'' हाट।"]},{"type":"highlight","level":"critical","text":"भगोरिया उत्सव: होली के समय 7 दिनों तक चलता है। यह जीवनसाथी चुनने का उत्सव (Match-making festival) है। इसके तीन चरण हैं: गुलालिया, गोल-गधेड़ो, और उजाड़िया।","icon":"❤️"},{"type":"h3","text":"गोंड (Gond)"},{"type":"p","text":"भारत की सबसे बड़ी और MP की दूसरी सबसे बड़ी जनजाति। ये खुद को ''कोयतुर'' कहते हैं। इनका निवास सतपुड़ा और नर्मदा घाटी (मंडला, बैतूल, छिंदवाड़ा) में है।"},{"type":"table","instruction":"गोंडों की उप-जातियां (व्यवसाय के आधार पर)","head":["उप-जाति","कार्य/व्यवसाय"],"body":[["अगरिया (Agariya)","लोहे का काम करने वाले (Iron Smelters)"],["प्रधान (Pradhan)","पुजारी/गाथा गाने वाले"],["ओझा (Ojha)","झाड़-फूंक/तांत्रिक कार्य"],["सोलहस (Solahas)","बढ़ई (Carpenter) का काम"]]},{"type":"h3","text":"विशेष पिछड़ी जनजातियां (PVTGs) - MP की 3"},{"type":"mnemonic","topic":"MP की 3 पिछड़ी जनजातियां","trick":"Ba-Bha-Sa (बा-भा-स)","visual":"⚠️","explanation":"1. **Ba**iga (बैगा): मंडला/डिंडोरी। (धरती को माँ मानते हैं, हल नहीं चलाते)।\n2. **Bha**ria (भारिया): पातालकोट (छिंदवाड़ा)।\n3. **Sa**hariya (सहरिया): श्योपुर/ग्वालियर। (कुपोषण से सर्वाधिक ग्रसित)।"},{"type":"h2","text":"2. मध्य प्रदेश की प्रमुख बोलियां (Major Dialects)"},{"type":"p","text":"MP हिंदी भाषी राज्य है, लेकिन यहाँ कई आंचलिक बोलियां (Dialects) बोली जाती हैं।"},{"type":"table","instruction":"क्षेत्रवार बोलियां","head":["बोली","क्षेत्र","विशेषता"],"body":[["बुंदेली (Bundeli)","बुंदेलखंड (सागर, छतरपुर, दमोह)","MP में सर्वाधिक बोली जाने वाली बोली। ''आल्हा-खंड'' (जगनिक) इसी में लिखा गया है।"],["मालवी (Malwi)","मालवा (इंदौर, उज्जैन)","इसे ''दक्षिणी राजस्थानी'' भी कहते हैं। यह बहुत कर्णप्रिय (मृदु) बोली है।"],["बघेलखंडी (Bagheli)","बघेलखंड (रीवा, सतना)","यह अवधी (Awadhi) के बहुत करीब है।"],["निमाड़ी (Nimari)","निमाड़ (खंडवा, खरगोन)","इसे ''दक्षिणी हिंदी'' कहते हैं। इसमें गुजराती और मराठी का प्रभाव है।"],["ब्रज भाषा (Brij)","ग्वालियर, भिंड, मुरैना","भक्ति काल का साहित्य (सूरदास) इसी में है।"]]},{"type":"highlight","level":"note","text":"जॉर्ज ग्रियर्सन (George Grierson) ने ''Linguistic Survey of India'' में निमाड़ी को ''दक्षिणी हिंदी'' कहा था।","icon":"🗣️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भगोरिया उत्सव किस जनजाति द्वारा मनाया जाता है?","options":["गोंड","भील","बैगा","कोल"],"correct":"भील","strategy":"भगोरिया = भागना (Elopement custom historically)। यह भीलों का प्रमुख त्योहार है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"अगरिया (Agariya) किस जनजाति की उप-जाति है?","options":["भील","गोंड","बैगा","भारिया"],"correct":"गोंड","strategy":"''आग'' (Fire) में लोहा तपाने वाले -> अगरिया -> गोंडों के लोहार।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"कौन सी जनजाति ''लोहासुर'' को अपना देवता मानती है?","options":["गोंड","भील","अगरिया","कोरकू"],"correct":"अगरिया","strategy":"अगरिया लोहे का काम करते हैं, इसलिए लोहासुर उनके देवता हैं (भट्टी में निवास)।"},{"type":"exam_pattern","topic":"Tribes & Dialects Trend","analysis":"Unit 2 Culture Trend:","stats":["जनजाति उप-जातियां: 2 प्रश्न","त्योहार/विवाह प्रथा: 1 प्रश्न","बोली/साहित्य: 1 प्रश्न"],"trend":"अब प्रश्न सीधे जिले पर नहीं, बल्कि ''उप-जातियों'' (Sub-castes) और विशिष्ट प्रथाओं (जैसे दूध-लौटावा विवाह) पर पूछे जा रहे हैं।"}],"en":[{"type":"h2","text":"Unit 2: Madhya Pradesh - The Tribal State"},{"type":"p","text":"Madhya Pradesh is known as the ''Tribal State'' because, as per the 2011 Census, 21.1% of its population is Scheduled Tribe (ST). Unit 2 focuses on their ''Culture'' (Marriage, Festivals, Dance) and the ''Dialects'' of the state."},"",{"type":"h2","text":"1. Major Tribes (Jan-Jatiyan)"},{"type":"h3","text":"Bhil"},{"type":"ul","items":["**Region:** Western MP (Jhabua, Alirajpur, Dhar).","**Status:** Largest tribe in MP by population.","**Sub-castes:** Bhilala (Higher status), Pataliya, Barela.","**Culture:** ''Pithora'' painting (Pema Phalya) and ''Bhagoria'' Haat."]},{"type":"highlight","level":"critical","text":"Bhagoria Festival: Celebrated for 7 days during Holi. It is a match-making festival. It has three phases: Gulalia, Gol-Gadhedo, and Ujadia.","icon":"❤️"},{"type":"h3","text":"Gond"},{"type":"p","text":"Largest tribe in India and second-largest in MP. They call themselves ''Koitur''. They inhabit the Satpura and Narmada Valley (Mandla, Betul, Chhindwara)."},{"type":"table","instruction":"Sub-castes of Gonds (Occupation-based)","head":["Sub-caste","Occupation"],"body":[["Agariya","Iron Smelters"],["Pradhan","Priests/Bards (Singers)"],["Ojha","Exorcists/Tantric works"],["Solahas","Carpenters"]]},{"type":"h3","text":"Particularly Vulnerable Tribal Groups (PVTGs) - 3 in MP"},{"type":"mnemonic","topic":"3 PVTGs of MP","trick":"Ba-Bha-Sa","visual":"⚠️","explanation":"1. **Ba**iga: Mandla/Dindori. (Consider Earth as Mother, do not use plough).\n2. **Bha**ria: Patalkot (Chhindwara).\n3. **Sa**hariya: Sheopur/Gwalior. (Most malnourished tribe)."},{"type":"h2","text":"2. Major Dialects of Madhya Pradesh"},{"type":"p","text":"While MP is a Hindi-speaking state, several regional dialects are spoken here."},{"type":"table","instruction":"Dialects Region-wise","head":["Dialect","Region","Feature"],"body":[["Bundeli","Bundelkhand (Sagar, Chhatarpur)","Most spoken dialect in MP. ''Alha-Khand'' (Jagnik) was written in this."],["Malwi","Malwa (Indore, Ujjain)","Also called ''Southern Rajasthani''. Known for being soft/melodious."],["Bagheli","Baghelkhand (Rewa, Satna)","Very close to Awadhi."],["Nimari","Nimar (Khandwa, Khargone)","Called ''Southern Hindi''. Influence of Gujarati and Marathi."],["Brij Bhasha","Gwalior, Bhind, Morena","Literature of Bhakti era (Surdas) is in Brij."]]},{"type":"highlight","level":"note","text":"George Grierson called Nimari ''Southern Hindi'' in his Linguistic Survey of India.","icon":"🗣️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Bhagoria festival is celebrated by which tribe?","options":["Gond","Bhil","Baiga","Kol"],"correct":"Bhil","strategy":"Bhagoria is the signature cultural event of the Bhils in Jhabua/Alirajpur."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Agariya is a sub-caste of which tribe?","options":["Bhil","Gond","Baiga","Bharia"],"correct":"Gond","strategy":"Those who work with ''Aag'' (Fire/Iron) -> Agariya -> Blacksmiths of Gonds."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"Which tribe worships ''Lohasur'' as their deity?","options":["Gond","Bhil","Agariya","Korku"],"correct":"Agariya","strategy":"Since Agariya work with iron, Lohasur (Iron Demon/God) is their deity residing in the furnace."},{"type":"exam_pattern","topic":"Tribes & Dialects Trend","analysis":"Unit 2 Culture Trend:","stats":["Sub-castes: 2 questions","Festivals/Marriage Customs: 1 question","Dialects/Literature: 1 question"],"trend":"Questions are shifting from simple location-based queries to specific ''Sub-castes'' and cultural practices (e.g., Doodh-Lautawa marriage)."}]}', 'mp_gk', NULL, 16, 1, 1770836180, 1771008849, 'blog', 'unit_2', 'Major Tribes and Dialects of Madhya Pradesh', 1, 0, 1, 1, 0, 'Unit 2: मध्य प्रदेश - एक जनजातीय प्रदेश मध्य प्रदेश को ''जनजातीय प्रदेश'' (Tribal State) कहा जाता है क्योंकि 2011 की जनगणना के अनुसार यहाँ की 21.1% जनसंख्या अनुसूचित जनजाति (ST) है। Unit 2 में जनजातियों...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('ae8bf625-7c86-4ca8-b48e-edcfcd32594f', 'major-festivals-folk-music-arts-literature-mp-unit-2', 'Major Festivals, Folk Music, Arts & Literature of Madhya Pradesh | म.प्र. के लोक संगीत, कला और साहित्य', 'Complete guide to MP''s cultural heritage. Covers regional folk songs (Alha, Pandwani), dances (Rai, Matki), festivals (Bhagoria), and folk literature (Isuri, Singaji) for MPPSC.', '{"hi":[{"type":"h2","text":"Unit 2: मध्य प्रदेश की लोक संस्कृति (Folk Culture)"},{"type":"p","text":"मध्य प्रदेश की संस्कृति को ''अंचल'' (Regions) के आधार पर समझना सबसे आसान है: मालवा, निमाड़, बुंदेलखंड और बघेलखंड। हर अंचल का अपना विशिष्ट संगीत, नृत्य और साहित्य है। MPPSC में ''गायन शैली'' (Singing Style) और ''लोक चित्रकला'' (Folk Painting) से प्रश्न निश्चित रूप से आते हैं।"},{"type":"h2","text":"1. लोक संगीत (Folk Music/Gayan)"},{"type":"p","text":"यहाँ के लोक गीत वीर रस और भक्ति रस से ओत-प्रोत हैं।"},{"type":"table","instruction":"क्षेत्रवार प्रमुख लोक गायन","head":["अंचल (Region)","गायन शैली","विशेषता"],"body":[["बुंदेलखंड","आल्हा (Alha)","वीर रस प्रधान। आल्हा-ऊदल की 52 लड़ाइयों का वर्णन। (बरसात में गाया जाता है)।"],["बुंदेलखंड","भोला गीत / बम्बुलिया","शिव-शक्ति की भक्ति। (सावन में)।"],["मालवा","भरथरी (Bharthari)","नाथ संप्रदाय के लोग गाते हैं (राजा भरथरी और रानी पिंगला की कथा)।"],["मालवा","संजा गीत (Sanja)","किशोरी लड़कियों द्वारा पितृपक्ष में गाया जाता है।"],["निमाड़","कलगी-तुर्रा (Kalgi-Turra)","प्रतिस्पर्धात्मक गायन (चंग वाद्य यंत्र पर)। दो दल होते हैं (कलगी और तुर्रा)।"],["बघेलखंड","विदेशीया (Bidesiya)","प्रेम और विरह का गीत (जंगल/खेत में गाया जाता है)।"]]},{"type":"highlight","level":"critical","text":"पंडवानी (Pandwani): वैसे तो यह छत्तीसगढ़ का है, लेकिन MP के शहडोल/अनूपपुर (बघेलखंड) में भी प्रचलित है।\nप्रमुख कलाकार: तीजन बाई (कापालिक शैली)।","icon":"🎤"},{"type":"h2","text":"2. लोक नृत्य और नाट्य (Folk Dance & Drama)"},{"type":"ul","items":["**राई (Rai):** बुंदेलखंड का प्रसिद्ध नृत्य। इसे MP का ''राजकीय नृत्य'' (State Dance) माना जाता है। (मृदंग वाद्य यंत्र)। ज्ञानेश्वरी देवी प्रमुख नर्तकी हैं।","**मटकी (Matki):** मालवा का नृत्य। महिलाएं सिर पर मटकी रखकर नाचती हैं। (ढोल वाद्य)।","**गणगौर (Gangaur):** निमाड़ क्षेत्र में। शिव-पार्वती की उपासना।","**माच (Maach):** मालवा का प्रमुख ''लोक नाट्य'' (Folk Drama)। इसे MP का ''राजकीय नाट्य'' भी कहते हैं। (उज्जैन में जन्म)।"]},"",{"type":"h2","text":"3. लोक साहित्य (Folk Literature)"},{"type":"p","text":"लोक साहित्यकारों ने अपनी क्षेत्रीय बोलियों में जनता के सुख-दुख को व्यक्त किया है।"},{"type":"fact_card","title":"प्रमुख लोक कवि (Folk Poets)","facts":["संत सिंगाजी (निमाड़): निमाड़ के कबीर। निर्गुण भक्ति धारा।","इसुरी (बुंदेलखंड): ''फाग'' (Phag) के लिए प्रसिद्ध। इनकी रचनाएं ''इसुरी की फाग'' नाम से जानी जाती हैं।","घाघ (Ghagh): कृषि पंडित। इनकी कहावतें मौसम और खेती पर सटीक बैठती हैं। (अकबर के समकालीन माने जाते हैं)।"],"icon":"✍️"},{"type":"h2","text":"4. प्रमुख पर्व और उत्सव (Festivals)"},{"type":"mnemonic","topic":"MP के सांस्कृतिक समारोह (Location)","trick":"K-D-T (Khajuraho Dance, Tansen Gwalior)","visual":"🎉","explanation":"1. **खजुराहो नृत्य समारोह:** छतरपुर (फरवरी - शास्त्रीय नृत्य)।\n2. **तानसेन समारोह:** ग्वालियर (दिसंबर - शास्त्रीय संगीत)।\n3. **कालिदास समारोह:** उज्जैन।\n4. **ध्रुपद समारोह:** भोपाल।\n5. **मालवा उत्सव:** इंदौर, उज्जैन, मांडू (तीनों जगह)।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"कलगी-तुर्रा (Kalgi-Turra) किस क्षेत्र का लोक गायन है?","options":["मालवा","निमाड़","बुंदेलखंड","बघेलखंड"],"correct":"निमाड़","strategy":"यह शिव और शक्ति की आराधना का प्रतिस्पर्धात्मक गायन है। (चंग की थाप पर)।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"काठी (Kathi) क्या है?","options":["जाति","जनजाति","काष्ठ शिल्प","लोक नृत्य"],"correct":"लोक नृत्य","strategy":"काठी निमाड़ का एक लोक नृत्य है जो देव प्रबोधनी एकादशी से शुरू होता है।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"संत सिंगाजी मध्य प्रदेश के किस क्षेत्र के निवासी थे?","options":["बुंदेलखंड","बघेलखंड","मालवा","निमाड़"],"correct":"निमाड़","strategy":"खंडवा/खरगोन क्षेत्र। इनका मेला भी पिपल्या खुर्द (खरगोन) में लगता है।"},{"type":"exam_pattern","topic":"Folk Culture Trend","analysis":"Unit 2 Culture Analysis:","stats":["लोक गायन/नृत्य (क्षेत्र): 2 प्रश्न","साहित्यकार/रचनाएं: 1 प्रश्न","समारोह/मेले: 1 प्रश्न"],"trend":"अब आयोग वाद्य यंत्रों (Instruments) और विशिष्ट गायन शैलियों (जैसे - बरसाती बरता) पर गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 2: Folk Culture of Madhya Pradesh"},{"type":"p","text":"The culture of Madhya Pradesh is best understood region-wise: Malwa, Nimar, Bundelkhand, and Baghelkhand. Each region has its unique music, dance, and literature. Questions on ''Singing Styles'' and ''Folk Paintings'' are guaranteed in MPPSC."},{"type":"h2","text":"1. Folk Music (Lok Gayan)"},{"type":"p","text":"Folk songs here are full of valor (Veer Ras) and devotion (Bhakti Ras)."},{"type":"table","instruction":"Regional Folk Singing Styles","head":["Region","Singing Style","Feature"],"body":[["Bundelkhand","Alha","Heroic ballads. Describes 52 battles of Alha-Udal. (Sung in rainy season)."],["Bundelkhand","Bhola Geet / Bambuliya","Devotion to Shiva-Shakti. (Sung in Sawan)."],["Malwa","Bharthari","Sung by Nath sect (Story of King Bharthari and Queen Pingla)."],["Malwa","Sanja Geet","Sung by young girls during Pitra Paksha (Fortnight of ancestors)."],["Nimar","Kalgi-Turra","Competitive singing (on Chang instrument). Two groups: Kalgi and Turra."],["Baghelkhand","Bidesiya","Songs of love and separation (Sung in fields/forests)."]]},{"type":"highlight","level":"critical","text":"Pandwani: Although from Chhattisgarh, it is popular in Shahdol/Anuppur (Baghelkhand) of MP.\nFamous Artist: Teejan Bai (Kapalik style).","icon":"🎤"},{"type":"h2","text":"2. Folk Dance & Drama"},{"type":"ul","items":["**Rai:** Famous dance of Bundelkhand. Considered the ''State Dance'' of MP. (Mridang instrument). Gyaneshwari Devi is a key dancer.","**Matki:** Dance of Malwa. Women dance with earthen pots on their heads. (Dhol instrument).","**Gangaur:** In Nimar region. Worship of Shiva-Parvati.","**Maach:** Major ''Folk Drama'' of Malwa. Also called ''State Drama'' of MP. (Originated in Ujjain)."]},"",{"type":"h2","text":"3. Folk Literature"},{"type":"p","text":"Folk poets expressed the joys and sorrows of the masses in their regional dialects."},{"type":"fact_card","title":"Major Folk Poets","facts":["Sant Singaji (Nimar): Kabir of Nimar. Nirgun Bhakti stream.","Isuri (Bundelkhand): Famous for ''Phag''. His works are known as ''Isuri ki Phag''.","Ghagh: Agriculture Pundit. His proverbs on weather and farming are accurate. (Contemporary of Akbar)."],"icon":"✍️"},{"type":"h2","text":"4. Major Festivals & Events"},{"type":"mnemonic","topic":"Cultural Festivals of MP (Location)","trick":"K-D-T (Khajuraho Dance, Tansen Gwalior)","visual":"🎉","explanation":"1. **Khajuraho Dance Festival:** Chhatarpur (Feb - Classical Dance).\n2. **Tansen Samaroh:** Gwalior (Dec - Classical Music).\n3. **Kalidas Samaroh:** Ujjain.\n4. **Dhrupad Samaroh:** Bhopal.\n5. **Malwa Utsav:** Indore, Ujjain, Mandu (All three places)."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Kalgi-Turra is the folk singing of which region?","options":["Malwa","Nimar","Bundelkhand","Baghelkhand"],"correct":"Nimar","strategy":"Competitive singing worshipping Shiva and Shakti. (On the beats of Chang)."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"What is ''Kathi''?","options":["Caste","Tribe","Wood Craft","Folk Dance"],"correct":"Folk Dance","strategy":"Kathi is a folk dance of Nimar region, starting from Dev Prabodhini Ekadashi."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"Sant Singaji belonged to which region of Madhya Pradesh?","options":["Bundelkhand","Baghelkhand","Malwa","Nimar"],"correct":"Nimar","strategy":"Khandwa/Khargone region. His fair is also held at Pipalya Khurd (Khargone)."},{"type":"exam_pattern","topic":"Folk Culture Trend","analysis":"Unit 2 Culture Analysis:","stats":["Folk Singing/Dance (Region): 2 questions","Poets/Works: 1 question","Festivals/Fairs: 1 question"],"trend":"The Commission is now asking deep questions about Musical Instruments and specific singing styles (e.g., Barsati Barata)."}]}', 'mp_gk', NULL, 18, 1, 1770836221, 1770836221, 'blog', 'unit_2', 'Major Festivals, Folk Music, Folk Arts and Folk literature of Madhya Pradesh', 1, 0, 0, 1, 0, 'Unit 2: मध्य प्रदेश की लोक संस्कृति (Folk Culture) मध्य प्रदेश की संस्कृति को ''अंचल'' (Regions) के आधार पर समझना सबसे आसान है: मालवा, निमाड़, बुंदेलखंड और बघेलखंड। हर अंचल का अपना विशिष्ट संगीत, नृत्य ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('7b89d8c5-2b06-4e03-bbfa-764bce968182', 'mp-literature-poets-writers-unit-2', 'Literary Giants of Madhya Pradesh: Poets & Writers | म.प्र. के प्रमुख साहित्यकार और उनकी कृतियाँ', 'Complete guide to MP''s literary heritage. Covers Ancient (Kalidasa), Medieval (Keshavdas), and Modern writers (Makhanlal Chaturvedi, Parsai) with memory tricks for their works.', '{"hi":[{"type":"h2","text":"Unit 2: मध्य प्रदेश के साहित्यकार (Literary Creators)"},{"type":"p","text":"मध्य प्रदेश की साहित्यिक विरासत अत्यंत समृद्ध है। यहाँ कालिदास जैसे प्राचीन महाकवि से लेकर माखनलाल चतुर्वेदी जैसे आधुनिक राष्ट्रवादी कवि हुए हैं। MPPSC में ''रचनाओं'' (Works) और ''उपाधियों'' (Titles) से प्रश्न अक्सर पूछे जाते हैं।"},{"type":"h2","text":"1. प्राचीन साहित्यकार (Ancient Era)"},{"type":"h3","text":"कालिदास (Kalidasa) - ''भारत के शेक्सपियर''"},{"type":"p","text":"चंद्रगुप्त विक्रमादित्य (गुप्त वंश) के नवरत्नों में से एक। इनका संबंध उज्जैन से था।"},{"type":"mnemonic","topic":"कालिदास की 7 प्रमुख रचनाएं","trick":"Ritu aur Megh ne Kumar aur Raghu ko Malvika aur Vikram ki Shakuntala dikhayi","visual":"📜","explanation":"**खंडकाव्य:** 1. ऋतुसंहार (Ritusamhara), 2. मेघदूत (Meghaduta)\n**महाकाव्य:** 3. कुमारसंभव (Kumarasambhava), 4. रघुवंश (Raghuvamsha)\n**नाटक:** 5. मालविकाग्निमित्र (Malavikagnimitra - पहला नाटक), 6. विक्रमोर्वशीय (Vikramorvasiya), 7. अभिज्ञान शाकुंतलम (Abhigyan Shakuntalam - सर्वश्रेष्ठ रचना)।"},{"type":"h3","text":"भवभूति (Bhavabhuti) - ''भारत के मिल्टन''"},{"type":"ul","items":["**मूल नाम:** श्रीकंठ।","**स्थान:** पद्मपुर (विदर्भ/ग्वालियर क्षेत्र)। कन्नौज के राजा यशोवर्मन के दरबारी।","**रचनाएं:** मालती माधव, महावीरचरित, उत्तररामचरित (करुण रस प्रधान)।"]},{"type":"h3","text":"बाणभट्ट (Banabhatta)"},{"type":"p","text":"हर्षवर्धन के दरबारी कवि।\n**रचनाएं:** हर्षचरित (जीवनी), कादंबरी (दुनिया का पहला उपन्यास माना जाता है), चंडी शतक।"},{"type":"h2","text":"2. मध्यकालीन साहित्यकार (Medieval Era)"},{"type":"highlight","level":"critical","text":"केशवदास (Keshavdas): इन्हें ''कठिन काव्य का प्रेत'' (Ghost of Difficult Poetry) कहा जाता है। ये ओरछा नरेश इंद्रजीत सिंह के दरबारी थे।\nरचनाएं: रसिकप्रिया, कविप्रिया, रामचंद्रिका (छंदों का अजायबघर)।","icon":"👻"},{"type":"fact_card","title":"पद्माकर (Padmakar)","facts":["स्थान: सागर (Sagar)।","उपनाम: ''कवि शिरोमणि'' (Kavi Shiromani)।","रचनाएं: जगतविनोद (Jagatvinod), प्रबोध पचासा, गंगा लहरी।","विशेष: इन्होंने होली और त्योहारों का सजीव वर्णन किया है।"],"icon":"✍️"},{"type":"h2","text":"3. आधुनिक साहित्यकार (Modern Era)"},{"type":"h3","text":"पंडित माखनलाल चतुर्वेदी (Makhanlal Chaturvedi)"},{"type":"p","text":"इन्हें ''एक भारतीय आत्मा'' (An Indian Soul) कहा जाता है। इनका जन्म बाबई (होशंगाबाद) में हुआ, लेकिन कर्मभूमि खंडवा थी।"},{"type":"highlight","level":"important","text":"हिम तरंगिणी: इस रचना के लिए उन्हें 1955 में ''पहला'' साहित्य अकादमी पुरस्कार मिला।\nप्रसिद्ध कविता: ''पुष्प की अभिलाषा'' (बिलासपुर जेल में लिखी गई)।\nपत्रिका: कर्मवीर (संपादक)।","icon":"🏆"},{"type":"h3","text":"सुभद्रा कुमारी चौहान (Subhadra Kumari Chauhan)"},{"type":"p","text":"वीर रस की एकमात्र कवियत्री। विवाह के बाद जबलपुर आईं।\n**रचनाएं:** मुकुल, त्रिधारा (काव्य संग्रह), बिखरे मोती (कहानी), ''झांसी की रानी'' (खूब लड़ी मर्दानी...)।"},{"type":"h3","text":"व्यंग्यकार (Satirists)"},{"type":"table","instruction":"MP के प्रमुख व्यंग्यकार","head":["साहित्यकार","स्थान","प्रमुख रचनाएं"],"body":[["हरिशंकर परसाई","होशंगाबाद (Jabalpur)","विकलांग श्रद्धा का दौर (साहित्य अकादमी), भूत के पाँव पीछे, निठल्ले की डायरी।"],["शरद जोशी","उज्जैन","जीप पर सवार इल्लियां, रहा किनारे बैठ, अंधों का हाथी।"],["मुल्ला रमूजी","भोपाल","गुलाबी उर्दू (Gulabi Urdu) शैली के जनक।"]]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"''कठिन काव्य का प्रेत'' किस कवि को कहा जाता है?","options":["पद्माकर","भूषण","केशवदास","बिहारी"],"correct":"केशवदास","strategy":"आचार्य रामचंद्र शुक्ल ने उनकी क्लिष्टता (Difficult style) के कारण यह उपाधि दी थी।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"गजानन माधव ''मुक्तिबोध'' की रचना कौन सी है?","options":["चांद का मुँह टेढ़ा है","कामायानी","साकेत","कुरुक्षेत्र"],"correct":"चांद का मुँह टेढ़ा है","strategy":"मुक्तिबोध (श्योपुर) फैंटेसी के कवि माने जाते हैं। ''चांद का मुँह टेढ़ा है'' उनकी सबसे प्रसिद्ध रचना है।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"भवभूति का मूल नाम क्या था?","options":["श्रीपति","श्रीकंठ","उमापति","दयानिधि"],"correct":"श्रीकंठ","strategy":"भवभूति का वास्तविक नाम श्रीकंठ था, उन्हें पदमपुर का निवासी माना जाता है।"},{"type":"exam_pattern","topic":"MP Literature Trend","analysis":"Unit 2 Literature Trend:","stats":["रचना और रचनाकार: 2-3 प्रश्न","कवि का उपनाम/स्थान: 1 प्रश्न","साहित्य अकादमी पुरस्कार: 1 प्रश्न"],"trend":"आयोग अब कवियों की ''जन्मस्थली'' (जैसे माखनलाल का बाबई, अब माखननगर) और उनकी ''पत्रिका'' (Journals) पर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 2: Literary Creators of Madhya Pradesh"},{"type":"p","text":"Madhya Pradesh has a rich literary heritage, ranging from ancient poets like Kalidasa to modern nationalist poets like Makhanlal Chaturvedi. In MPPSC, questions frequently ask about ''Works'' (Creations) and ''Titles''."},{"type":"h2","text":"1. Ancient Era Writers"},{"type":"h3","text":"Kalidasa - ''Shakespeare of India''"},{"type":"p","text":"One of the Navratnas of Chandragupta Vikramaditya (Gupta Dynasty). Associated with Ujjain."},{"type":"mnemonic","topic":"7 Major Works of Kalidasa","trick":"Ritu & Megh showed Kumar & Raghu the play of Malvika & Vikram''s Shakuntala","visual":"📜","explanation":"**Lyrics (Khandakavya):** 1. Ritusamhara, 2. Meghaduta\n**Epics (Mahakavya):** 3. Kumarasambhava, 4. Raghuvamsha\n**Plays (Nataka):** 5. Malavikagnimitra (First play), 6. Vikramorvasiya, 7. Abhigyan Shakuntalam (Masterpiece)."},{"type":"h3","text":"Bhavabhuti - ''Milton of India''"},{"type":"ul","items":["**Original Name:** Srikantha.","**Place:** Padmapur (Vidarbha/Gwalior region). Court poet of King Yashovarman of Kannauj.","**Works:** Malatimadhava, Mahaviracharita, Uttararamacharita (Famous for Karuna Ras/Pathos)."]},{"type":"h3","text":"Banabhatta"},{"type":"p","text":"Court poet of Harshavardhana.\n**Works:** Harshacharita (Biography), Kadambari (Considered the world''s first novel), Chandi Shatak."},{"type":"h2","text":"2. Medieval Era Writers"},{"type":"highlight","level":"critical","text":"Keshavdas: Known as ''Kathin Kavya ka Pret'' (Ghost of Difficult Poetry). Court poet of Indrajit Singh of Orchha.\nWorks: Rasikpriya, Kavipriya, Ramchandrika (Museum of Metres).","icon":"👻"},{"type":"fact_card","title":"Padmakar","facts":["Place: Sagar.","Title: ''Kavi Shiromani''.","Works: Jagatvinod, Prabodh Pachisa, Ganga Lahari.","Specialty: Vivid description of Holi and festivals."],"icon":"✍️"},{"type":"h2","text":"3. Modern Era Writers"},{"type":"h3","text":"Pt. Makhanlal Chaturvedi"},{"type":"p","text":"Known as ''Ek Bhartiya Aatma'' (An Indian Soul). Born in Bavai (Hoshangabad), but his workplace was Khandwa."},{"type":"highlight","level":"important","text":"Him Tarangini: Won the ''First'' Sahitya Akademi Award in 1955 for this work.\nFamous Poem: ''Pushp Ki Abhilasha'' (Written in Bilaspur Jail).\nJournal: Karmaveer (Editor).","icon":"🏆"},{"type":"h3","text":"Subhadra Kumari Chauhan"},{"type":"p","text":"The only major poetess of ''Veer Ras''. Moved to Jabalpur after marriage.\n**Works:** Mukul, Tridhara (Poetry collections), Bikhre Moti (Stories), ''Jhansi ki Rani'' (Khoob ladi mardani...)."},{"type":"h3","text":"Satirists (Vyangyakar)"},{"type":"table","instruction":"Major Satirists of MP","head":["Writer","Place","Major Works"],"body":[["Harishankar Parsai","Hoshangabad (Jabalpur)","Viklang Shraddha ka Daur (Sahitya Akademi), Bhoot ke Paon Peeche, Nithalle ki Diary."],["Sharad Joshi","Ujjain","Jeep par Sawar Illiyan, Raha Kinare Baith, Andhon ka Haathi."],["Mulla Ramuji","Bhopal","Father of ''Gulabi Urdu'' style."]]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Which poet is known as ''Kathin Kavya ka Pret''?","options":["Padmakar","Bhushan","Keshavdas","Bihari"],"correct":"Keshavdas","strategy":"Acharya Ramchandra Shukla gave him this title due to the complexity of his poetry."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which is the work of Gajanan Madhav ''Muktibodh''?","options":["Chand ka Muh Tedha Hai","Kamayani","Saket","Kurukshetra"],"correct":"Chand ka Muh Tedha Hai","strategy":"Muktibodh (Sheopur) is known for Fantasy. ''Chand ka Muh Tedha Hai'' is his masterpiece."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"What was the original name of Bhavabhuti?","options":["Shripati","Srikantha","Umapati","Dayanidhi"],"correct":"Srikantha","strategy":"Bhavabhuti''s real name was Srikantha, and he hailed from Padmapur."},{"type":"exam_pattern","topic":"MP Literature Trend","analysis":"Unit 2 Literature Trend:","stats":["Works & Authors: 2-3 questions","Titles/Place of Poet: 1 question","Sahitya Akademi Award: 1 question"],"trend":"The Commission is now asking about the ''Birthplace'' (e.g., Makhanlal''s Bavai, now Makhan Nagar) and their ''Journals'' (Patrika)."}]}', 'mp_gk', NULL, 18, 1, 1770836280, 1770836280, 'blog', 'unit_2', 'Important literary Creators of Madhya Pradesh and their Literary Creations', 1, 0, 0, 1, 0, 'Unit 2: मध्य प्रदेश के साहित्यकार (Literary Creators) मध्य प्रदेश की साहित्यिक विरासत अत्यंत समृद्ध है। यहाँ कालिदास जैसे प्राचीन महाकवि से लेकर माखनलाल चतुर्वेदी जैसे आधुनिक राष्ट्रवादी कवि हुए हैं। ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('a36be208-2eed-498d-a43a-910e713de45d', 'major-tourist-places-mp-unit-2-mppsc', 'Major Tourist Places of MP: Religious, Cultural & Archaeological | म.प्र. के प्रमुख पर्यटन स्थल', 'Complete guide to MP''s UNESCO World Heritage sites, Jyotirlingas, and historical forts. Covers Khajuraho, Sanchi, Bhimbetka, Mandu, and Ujjain with exam-oriented facts.', '{"hi":[{"type":"h2","text":"Unit 2: मध्य प्रदेश के प्रमुख पर्यटन स्थल (Tourist Places)"},{"type":"p","text":"मध्य प्रदेश को ''भारत का हृदय'' (Heart of India) कहा जाता है, जो अपनी ऐतिहासिक धरोहर और धार्मिक आस्था के लिए प्रसिद्ध है। MPPSC में पर्यटन से 3-4 प्रश्न निश्चित रूप से आते हैं, विशेषकर UNESCO स्थलों और किलों के उपनामों (Nicknames) पर।"},{"type":"h2","text":"1. पुरातात्विक स्थल (Archaeological Sites)"},{"type":"p","text":"मध्य प्रदेश में 3 UNESCO विश्व धरोहर स्थल हैं। इनका वर्ष और विशेषता याद रखना अनिवार्य है।"},{"type":"mnemonic","topic":"MP के UNESCO स्थल (वर्ष सहित)","trick":"K-S-B (1986, 1989, 2003)","visual":"🌍","explanation":"1. **K**hajuraho (खजुराहो) - 1986 (सबसे पहले)।\n2. **S**anchi (सांची) - 1989 (अशोक निर्मित)।\n3. **B**himbetka (भीमबेटका) - 2003 (सबसे बाद में)।"},{"type":"table","instruction":"प्रमुख पुरातात्विक स्थल","head":["स्थल","जिला","विशेषता/खोजकर्ता"],"body":[["भीमबेटका (Bhimbetka)","रायसेन","आदिमानव के शैल चित्र (Rock Paintings)। खोज: वी.एस. वाकणकर (1957)।"],["भरहुत (Bharhut)","सतना","बौद्ध स्तूप। खोज: अलेक्जेंडर कनिंघम (1873)।"],["एरण (Eran)","सागर","सती प्रथा का पहला लिखित साक्ष्य (भानुगुप्त का अभिलेख, 510 ई.)।"],["कायथा (Kayatha)","उज्जैन","ताम्रपाषाण कालीन (Chalcolithic) स्थल। खोज: वी.एस. वाकणकर।"]]},{"type":"h2","text":"2. धार्मिक स्थल (Religious Places)"},{"type":"p","text":"भारत के 12 ज्योतिर्लिंगों में से 2 मध्य प्रदेश में हैं। इसके अलावा MP ''नदियों और मंदिरों'' की भूमि है।"},{"type":"fact_card","title":"दो ज्योतिर्लिंग","facts":["1. महाकालेश्वर (उज्जैन): क्षिप्रा नदी के तट पर। यह एकमात्र ''दक्षिणमुखी'' (South-facing) ज्योतिर्लिंग है। यहाँ ''भस्म आरती'' प्रसिद्ध है।","2. ओंकारेश्वर (खंडवा): नर्मदा नदी के तट पर। यह ''ममलेश्वर'' और ''ओंकारेश्वर'' दो रूपों में है।"],"icon":"🕉️"},{"type":"ul","items":["**चित्रकूट (सतना):** मंदाकिनी नदी के तट पर। भगवान राम ने वनवास का समय यहाँ बिताया। (दर्शनीय स्थल: हनुमान धारा, सती अनुसुइया आश्रम)।","**मैहर (सतना):** त्रिकूटा पर्वत पर ''माँ शारदा'' का मंदिर। इसे ''संगीत नगरी'' (Music City) भी कहा जाता है (उस्ताद अलाउद्दीन खान के कारण)।","**ओरछा (निवाड़ी):** ''राम राजा मंदिर''। यहाँ भगवान राम को ''राजा'' के रूप में पूजा जाता है और पुलिस उन्हें ''गार्ड ऑफ ऑनर'' देती है।"]},{"type":"h2","text":"3. सांस्कृतिक और ऐतिहासिक स्थल (Cultural & Historical)"},{"type":"highlight","level":"critical","text":"ग्वालियर का किला: इसे ''भारत का जिब्राल्टर'' (Gibraltar of India) या ''किलों का रत्न'' कहा जाता है। निर्माण: राजा सूरज सेन (525 ई.)।","icon":"🏰"},{"type":"table","instruction":"प्रमुख ऐतिहासिक नगर और उनके उपनाम","head":["नगर","उपनाम (Nickname)","प्रमुख स्मारक"],"body":[["मांडू (धार)","आनंद की नगरी (City of Joy)","जहाज महल, रानी रूपमती का महल, होशंगशाह का मकबरा (भारत की पहली संगमरमर इमारत)।"],["बुरहानपुर","दक्षिण का प्रवेश द्वार (Gateway to South)","असीरगढ़ का किला, मुमताज की पहली कब्र (काला ताजमहल)।"],["चंदेरी (अशोकनगर)","हस्तशिल्प और किलों का शहर","चंदेरी का किला (कीर्तिपाल), नौखंडा महल।"]]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"भीमबेटका की गुफाओं की खोज किसने की थी?","options":["एच.डी. सांकलिया","वी.एस. वाकणकर","अलेक्जेंडर कनिंघम","राखालदास बनर्जी"],"correct":"वी.एस. वाकणकर","strategy":"विष्णु श्रीधर वाकणकर (उज्जैन के निवासी) ने 1957 में इसे खोजा था।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"किस किले को ''भारत का जिब्राल्टर'' कहा जाता है?","options":["मांडू का किला","ग्वालियर का किला","चंदेरी का किला","रायसेन का किला"],"correct":"ग्वालियर का किला","strategy":"मुगल बादशाह बाबर ने इसे ''हिंद के किलों के गले का हार'' कहा था।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"हिंडोला महल (Swinging Palace) कहाँ स्थित है?","options":["ओरछा","मांडू","ग्वालियर","फतेहपुर सीकरी"],"correct":"मांडू","strategy":"मांडू (धार) के शाही परिसर में हिंडोला महल और जहाज महल स्थित हैं।"},{"type":"exam_pattern","topic":"MP Tourism Trend","analysis":"Unit 2 Tourism Analysis:","stats":["UNESCO स्थल (वर्ष/खोजकर्ता): 1-2 प्रश्न","किलों के उपनाम/निर्माता: 1 प्रश्न","धार्मिक स्थल (नदी/जिला): 1 प्रश्न"],"trend":"अब आयोग कम प्रसिद्ध पर्यटन स्थलों (जैसे - मुक्तागिरी जैन तीर्थ, बैतूल) और स्मारकों के वास्तुकार (Architect) पर भी प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 2: Major Tourist Places of Madhya Pradesh"},{"type":"p","text":"Madhya Pradesh, the ''Heart of India'', is famous for its historical heritage and religious significance. In MPPSC, 3-4 questions are guaranteed from Tourism, especially on UNESCO sites and Nicknames of forts."},{"type":"h2","text":"1. Archaeological Sites"},{"type":"p","text":"MP has 3 UNESCO World Heritage Sites. Remembering their year of inclusion and features is mandatory."},{"type":"mnemonic","topic":"UNESCO Sites of MP (With Year)","trick":"K-S-B (1986, 1989, 2003)","visual":"🌍","explanation":"1. **K**hajuraho - 1986 (First). \n2. **S**anchi - 1989 (Built by Ashoka).\n3. **B**himbetka - 2003 (Latest among three)."},{"type":"table","instruction":"Key Archaeological Sites","head":["Site","District","Feature/Discoverer"],"body":[["Bhimbetka","Raisen","Prehistoric Rock Paintings. Discovered by: V.S. Wakankar (1957)."],["Bharhut","Satna","Buddhist Stupa. Discovered by: Alexander Cunningham (1873)."],["Eran","Sagar","First epigraphic evidence of Sati Practice (Bhanugupta''s Inscription, 510 AD)."],["Kayatha","Ujjain","Chalcolithic Site (Copper Age). Discovered by: V.S. Wakankar."]]},{"type":"h2","text":"2. Religious Places"},{"type":"p","text":"Out of the 12 Jyotirlingas in India, 2 are in Madhya Pradesh."},{"type":"fact_card","title":"The Two Jyotirlingas","facts":["1. Mahakaleshwar (Ujjain): On the banks of Kshipra. The only ''South-facing'' (Dakshinamukhi) Jyotirlinga. Famous for ''Bhasma Aarti''.","2. Omkareshwar (Khandwa): On the banks of Narmada. It is in two forms: ''Mamleshwar'' and ''Omkareshwar''."],"icon":"🕉️"},{"type":"ul","items":["**Chitrakoot (Satna):** On the banks of Mandakini. Lord Ram spent his exile here. (Spots: Hanuman Dhara, Sati Anusuya Ashram).","**Maihar (Satna):** ''Maa Sharada'' temple on Trikuta Hill. Also called ''Music City'' (due to Ustad Allauddin Khan).","**Orchha (Niwari):** ''Ram Raja Temple''. Lord Ram is worshipped as a ''King'' here and receives a Police Guard of Honour."]},{"type":"h2","text":"3. Cultural & Historical Sites"},{"type":"highlight","level":"critical","text":"Gwalior Fort: Called ''Gibraltar of India'' or ''Gem of Forts''. Built by: Raja Suraj Sen (525 AD).","icon":"🏰"},{"type":"table","instruction":"Historic Cities & Nicknames","head":["City","Nickname","Key Monuments"],"body":[["Mandu (Dhar)","City of Joy","Jahaz Mahal (Ship Palace), Rani Roopmati Pavilion, Hoshang Shah''s Tomb (India''s first marble structure)."],["Burhanpur","Gateway to South","Asirgarh Fort, Mumtaz''s first grave (Black Taj Mahal)."],["Chanderi (Ashoknagar)","City of Forts & Handloom","Chanderi Fort (Kirtipal), Naukhanda Mahal."]]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Who discovered the caves of Bhimbetka?","options":["H.D. Sankalia","V.S. Wakankar","Alexander Cunningham","Rakhaldas Banerji"],"correct":"V.S. Wakankar","strategy":"Vishnu Shridhar Wakankar (from Ujjain) discovered them in 1957."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which fort is known as the ''Gibraltar of India''?","options":["Mandu Fort","Gwalior Fort","Chanderi Fort","Raisen Fort"],"correct":"Gwalior Fort","strategy":"Mughal Emperor Babur called it ''the pearl amongst the fortresses of Hind''."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"Where is Hindola Mahal located?","options":["Orchha","Mandu","Gwalior","Fatehpur Sikri"],"correct":"Mandu","strategy":"Hindola Mahal (Swinging Palace) and Jahaz Mahal are in the Royal Enclave of Mandu."},{"type":"exam_pattern","topic":"MP Tourism Trend","analysis":"Unit 2 Tourism Analysis:","stats":["UNESCO Sites (Year/Discoverer): 1-2 questions","Fort Nicknames/Builders: 1 question","Religious Sites (River/District): 1 question"],"trend":"The Commission is now asking about lesser-known pilgrimage sites (e.g., Muktagiri Jain Teerth, Betul) and Architects of monuments."}]}', 'mp_gk', NULL, 18, 1, 1770836389, 1770836389, 'blog', 'unit_2', 'Major Tourist Places of Religious, Cultural and Archaeological Importance in Madhya Pradesh', 1, 0, 0, 1, 0, 'Unit 2: मध्य प्रदेश के प्रमुख पर्यटन स्थल (Tourist Places) मध्य प्रदेश को ''भारत का हृदय'' (Heart of India) कहा जाता है, जो अपनी ऐतिहासिक धरोहर और धार्मिक आस्था के लिए प्रसिद्ध है। MPPSC में पर्यटन से 3...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('faf323df-afa4-4aa3-91f0-37c5b3311692', 'unesco-world-heritage-sites-madhya-pradesh-unit-2', 'UNESCO World Heritage Sites in Madhya Pradesh | म.प्र. के विश्व धरोहर स्थल', 'Comprehensive guide to the 3 UNESCO World Heritage Sites of MP: Khajuraho, Sanchi, and Bhimbetka. Includes discovery facts, architectural styles, and memory tricks for years.', '{"hi":[{"type":"h2","text":"Unit 2: मध्य प्रदेश के विश्व धरोहर स्थल (UNESCO Sites)"},{"type":"p","text":"मध्य प्रदेश में वर्तमान में 3 स्थल ऐसे हैं जिन्हें यूनेस्को (UNESCO) ने ''विश्व धरोहर'' (World Heritage Site) घोषित किया है। MPPSC में इनके ''घोषणा वर्ष'' (Year of Inscription) और ''जिले'' का मिलान करने वाले प्रश्न अक्सर पूछे जाते हैं।"},{"type":"highlight","level":"critical","text":"MP के 3 रत्न: खजुराहो (1986), सांची (1989), और भीमबेटका (2003)।","icon":"🏆"},{"type":"mnemonic","topic":"वर्ष याद रखने की ट्रिक","trick":"K-S-B : 86-89-03","visual":"📅","explanation":"**K**hajuraho (1986)\n**S**anchi (1989)\n**B**himbetka (2003)\n(क्रम: सबसे पहले मंदिर, फिर स्तूप, फिर गुफाएं)।"},{"type":"h2","text":"1. खजुराहो स्मारक समूह (1986)"},"",{"type":"ul","items":["**स्थान:** छतरपुर जिला।","**निर्माता:** चंदेल शासक (950-1050 ई.)।","**शैली:** नागर शैली (पंचायतन)।","**विशेषता:** यहाँ के मंदिर ''मैथुन मूर्तियों'' (Erotic Sculptures) और अपनी वास्तुकला के लिए प्रसिद्ध हैं।","**प्रमुख मंदिर:** कंदरिया महादेव (सबसे बड़ा), चौसठ योगिनी (ग्रेनाइट से बना), लक्ष्मण मंदिर।"]},{"type":"h2","text":"2. सांची के बौद्ध स्मारक (1989)"},"",{"type":"ul","items":["**स्थान:** रायसेन जिला (बेतवा नदी के पास)।","**निर्माता:** सम्राट अशोक (मौर्य काल)। शुंग काल में इसका विस्तार हुआ।","**खोज:** जनरल टेलर (1818)।","**विशेषता:** स्तूप संख्या 1 (महास्तूप) में भगवान बुद्ध के अवशेष नहीं हैं, लेकिन स्तूप संख्या 3 में उनके शिष्यों ''सारिपुत्र'' और ''महामोग्गलायन'' की अस्थियां हैं।","**नोट:** सांची का प्राचीन नाम ''काकनाद बोट'' था।"]},{"type":"h2","text":"3. भीमबेटका के शैलाश्रय (2003)"},"",{"type":"ul","items":["**स्थान:** रायसेन जिला (रातापानी अभ्यारण्य के पास)।","**खोज:** डॉ. विष्णु श्रीधर वाकणकर (1957)।","**विशेषता:** यहाँ आदिमानव द्वारा बनाए गए 500 से अधिक गुफा चित्र (Rock Paintings) मिले हैं। यह विश्व के सबसे पुराने शैल चित्रों में से एक है।","**थीम:** शिकार, नृत्य, घुड़सवारी।"]},{"type":"fact_card","title":"अस्थायी सूची (Tentative List)","facts":["ग्वालियर और ओरछा: यूनेस्को की ''ऐतिहासिक शहरी परिदृश्य'' (Historic Urban Landscape) परियोजना में शामिल।","भेड़ाघाट-लम्हेटाघाट: नर्मदा घाटी के डायनासोर जीवाश्म और संगमरमर चट्टानें।","सतपुड़ा टाइगर रिज़र्व: अपनी जैव विविधता के लिए।"],"icon":"📝"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"भीमबेटका को किसने खोजा था?","options":["एच.डी. सांकलिया","वी.एस. वाकणकर","अलेक्जेंडर कनिंघम","आर.डी. बनर्जी"],"correct":"वी.एस. वाकणकर","strategy":"वाकणकर जी उज्जैन के थे और उन्होंने 1957 में भीमबेटका की खोज की थी।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"सांची स्तूप का निर्माण किसने करवाया था?","options":["चंद्रगुप्त मौर्य","बिन्दुसार","अशोक","कनिष्क"],"correct":"अशोक","strategy":"अशोक ने अपनी पत्नी (विदिशा की देवी) के कहने पर सांची में स्तूप बनवाया था।"},{"type":"pyq","exam":"MPPSC Prelims 2017","year":2017,"question":"खजुराहो के मंदिर किस जिले में स्थित हैं?","options":["मंडला","छतरपुर","बालाघाट","रीवा"],"correct":"छतरपुर","strategy":"खजुराहो, छतरपुर जिले का हिस्सा है।"},{"type":"exam_pattern","topic":"WHS Trend","analysis":"Unit 2 Heritage Trend:","stats":["घोषणा वर्ष (Year): 1 प्रश्न (मैचिंग)","खोजकर्ता (Discoverer): 1 प्रश्न","संबंधित राजवंश: 1 प्रश्न"],"trend":"अब प्रश्न अस्थायी सूची (Tentative List) और स्थलों के अंदरूनी विवरण (जैसे सांची के तोरण द्वार पर किसकी नक्काशी है?) पर पूछे जा रहे हैं।"}],"en":[{"type":"h2","text":"Unit 2: UNESCO World Heritage Sites of Madhya Pradesh"},{"type":"p","text":"Madhya Pradesh currently has 3 sites declared as ''World Heritage Sites'' by UNESCO. Questions in MPPSC often ask to match the ''Year of Inscription'' with the ''District''."},{"type":"highlight","level":"critical","text":"The 3 Gems of MP: Khajuraho (1986), Sanchi (1989), and Bhimbetka (2003).","icon":"🏆"},{"type":"mnemonic","topic":"Trick to Remember Years","trick":"K-S-B : 86-89-03","visual":"📅","explanation":"**K**hajuraho (1986)\n**S**anchi (1989)\n**B**himbetka (2003)\n(Order: First Temples, then Stupa, then Caves)."},{"type":"h2","text":"1. Khajuraho Group of Monuments (1986)"},"",{"type":"ul","items":["**Location:** Chhatarpur District.","**Builder:** Chandela Rulers (950-1050 AD).","**Style:** Nagara Style (Panchayatan).","**Feature:** Famous for ''Erotic Sculptures'' and architectural brilliance.","**Key Temples:** Kandariya Mahadev (Largest), Chausath Yogini (Granite), Lakshmana Temple."]},{"type":"h2","text":"2. Buddhist Monuments at Sanchi (1989)"},"",{"type":"ul","items":["**Location:** Raisen District (Near Betwa river).","**Builder:** Emperor Ashoka (Mauryan Era). Expanded during Shunga period.","**Discovery:** General Taylor (1818).","**Feature:** Stupa No. 1 (Great Stupa) does not have Buddha''s relics, but Stupa No. 3 contains relics of his disciples ''Sariputra'' and ''Mahamoggallana''.","**Note:** Ancient name of Sanchi was ''Kakanada Bot''."]},{"type":"h2","text":"3. Rock Shelters of Bhimbetka (2003)"},"",{"type":"ul","items":["**Location:** Raisen District (Near Ratapani Sanctuary).","**Discovery:** Dr. Vishnu Shridhar Wakankar (1957).","**Feature:** Contains over 500 rock paintings made by early humans (Mesolithic/Paleolithic). One of the oldest rock art sites in the world.","**Theme:** Hunting, Dancing, Horse riding."]},{"type":"fact_card","title":"Tentative List (Updates)","facts":["Gwalior & Orchha: Included in UNESCO''s ''Historic Urban Landscape'' project.","Bhedaghat-Lamhetaghat: Dinosaur fossils and Marble Rocks of Narmada Valley.","Satpura Tiger Reserve: For its biodiversity."],"icon":"📝"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Who discovered Bhimbetka?","options":["H.D. Sankalia","V.S. Wakankar","Alexander Cunningham","R.D. Banerji"],"correct":"V.S. Wakankar","strategy":"Wakankar ji was from Ujjain and discovered it in 1957."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Who built the Sanchi Stupa?","options":["Chandragupta Maurya","Bindusara","Ashoka","Kanishka"],"correct":"Ashoka","strategy":"Ashoka built it at the request of his wife (Devi of Vidisha)."},{"type":"pyq","exam":"MPPSC Prelims 2017","year":2017,"question":"In which district are Khajuraho temples located?","options":["Mandla","Chhatarpur","Balaghat","Rewa"],"correct":"Chhatarpur","strategy":"Khajuraho is part of the Chhatarpur district."},{"type":"exam_pattern","topic":"WHS Trend","analysis":"Unit 2 Heritage Trend:","stats":["Inscription Year: 1 question (Matching)","Discoverer: 1 question","Associated Dynasty: 1 question"],"trend":"Questions are now asking about the Tentative List and specific details inside the sites (e.g., Whose carvings are on Sanchi Torana?)."}]}', 'mp_gk', NULL, 15, 1, 1770836584, 1770836584, 'blog', 'unit_2', 'World Heritage sites in Madhya Pradesh', 1, 0, 0, 1, 0, 'Unit 2: मध्य प्रदेश के विश्व धरोहर स्थल (UNESCO Sites) मध्य प्रदेश में वर्तमान में 3 स्थल ऐसे हैं जिन्हें यूनेस्को (UNESCO) ने ''विश्व धरोहर'' (World Heritage Site) घोषित किया है। MPPSC में इनके ''घोषणा ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('326b9ab3-c99a-4b08-b919-5cbe10112926', 'tribal-personalities-mp-unit-2', 'Important Tribal Personalities of Madhya Pradesh | म.प्र. के प्रमुख जनजातीय व्यक्तित्व', 'Comprehensive guide to MP''s Tribal Heroes and Artists. Covers Tantya Bhil, Bhima Nayak, Rani Durgavati, Shankar Shah, and Padma Shri artists like Bhuri Bai for MPPSC Unit 2.', '{"hi":[{"type":"h2","text":"Unit 2: मध्य प्रदेश के प्रमुख जनजातीय व्यक्तित्व (Tribal Personalities)"},{"type":"p","text":"MPPSC ने पिछले कुछ वर्षों में ''जनजातीय व्यक्तित्व'' पर अपना फोकस बहुत बढ़ाया है। यह टॉपिक Unit 2 (इतिहास) और Unit 10 (जनजाति) दोनों को कवर करता है। यहाँ हमें स्वतंत्रता सेनानियों और पद्म श्री विजेता कलाकारों पर विशेष ध्यान देना है।"},{"type":"h2","text":"1. जनजातीय स्वतंत्रता सेनानी (Tribal Freedom Fighters)"},{"type":"h3","text":"टंट्या भील (Tantya Bhil) - ''Indian Robinhood''"},{"type":"p","text":"निमाड़ क्षेत्र के महान क्रांतिकारी। अंग्रेजों का खजाना लूटकर गरीबों में बांटते थे।"},{"type":"highlight","level":"critical","text":"जन्म: 1842 (पंधाना, खंडवा)।\nशहीद स्थल: जबलपुर में फांसी दी गई (1889)।\nसमाधि: पातालपानी (इंदौर)। पातालपानी रेलवे स्टेशन का नाम बदलकर अब ''टंट्या भील स्टेशन'' कर दिया गया है।","icon":"🏹"},{"type":"h3","text":"भीमा नायक (Bhima Nayak) - ''Robinhood of Nimar''"},{"type":"ul","items":["**कार्यक्षेत्र:** बड़वानी (सेंधवा)।","**संघर्ष:** 1857 की क्रांति में अंग्रेजों के खिलाफ ''अंबापानी का युद्ध'' लड़ा।","**मृत्यु:** इन्हें पोर्ट ब्लेयर (Cellular Jail) भेजा गया, जहाँ इनकी मृत्यु हुई।"]},{"type":"h3","text":"शंकर शाह और रघुनाथ शाह (Shankar Shah & Raghunath Shah)"},{"type":"p","text":"ये गोंडवाना साम्राज्य (गढ़ा मंडला) के शासक थे। पिता (शंकर शाह) और पुत्र (रघुनाथ शाह) ने 1857 की क्रांति में अपनी कलम और तलवार दोनों से विद्रोह किया।"},{"type":"fact_card","title":"बलिदान दिवस","facts":["अंग्रेजों ने इन्हें तोप के मुँह से बांधकर उड़ा दिया था (18 सितंबर 1857)।","स्थान: जबलपुर (कलेक्ट्रेट के सामने)।","इनकी कविताओं ने जनता में विद्रोह की आग भड़काई थी।"],"icon":"🔥"},{"type":"h2","text":"2. ऐतिहासिक वीरांगनाएं (Historical Queens)"},{"type":"h3","text":"रानी दुर्गावती (Rani Durgavati)"},{"type":"p","text":"गोंडवाना की सबसे प्रतापी रानी। इनका विवाह राजा दलपत शाह (गोंड) से हुआ था, लेकिन वे चंदेल राजकुमारी (कालिंजर) थीं।"},"",{"type":"table","instruction":"रानी दुर्गावती: प्रमुख तथ्य","head":["तथ्य","विवरण"],"body":[["शासन काल","1550-1564 (अपने पुत्र वीर नारायण की संरक्षिका बनकर)।"],["युद्ध","अकबर के सेनापति ''आसफ खान'' से युद्ध लड़ा (नरई नाला का युद्ध)।"],["समाधि","बरेला (जबलपुर)।"],["विशेष","इन्होंने ''आधार ताल'' और ''रानी ताल'' (जबलपुर) बनवाए।"]]},{"type":"h2","text":"3. जनजातीय कलाकार (Tribal Artists)"},{"type":"p","text":"कला के क्षेत्र में MP के जनजातीय कलाकारों ने विश्व स्तर पर पहचान बनाई है। MPPSC में ''पद्म श्री'' विजेताओं के नाम रटना अनिवार्य है।"},{"type":"mnemonic","topic":"कलाकार और उनकी कला","trick":"Bhuri ka Pithora, Jangarh ki Gond, Baiju ki Wood","visual":"🎨","explanation":"1. **Bhuri** Bai (झाबुआ) - पिथोरा चित्रकला (Pithora)। (भारत भवन में मजदूरी करते हुए कलाकार बनीं)।\n2. **Jangarh** Singh Shyam (डिंडोरी) - गोंड चित्रकला। इन्होंने ''जनगढ़ कलम'' शैली शुरू की। (जापान में मृत्यु)।\n3. **Baiju** (बैजू) - काष्ठ शिल्प (Wood Craft)।"},{"type":"fact_card","title":"अन्य प्रमुख व्यक्तित्व","facts":["पेमा फाल्या (Pema Phalya): भील चित्रकार (पिथोरा)। हाल ही में निधन।","बादल भोई (Badal Bhoi): छिंदवाड़ा के आदिवासी नेता। छिंदवाड़ा के आदिवासी संग्रहालय का नाम इनके नाम पर है।","गंजन सिंह कोरकू (Ganjan Singh Korku): घोड़ाडोंगरी (बैतूल) जंगल सत्याग्रह के नेता।"],"icon":"🏆"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"जनजातीय गौरव दिवस (Tribal Pride Day) कब मनाया जाता है?","options":["15 नवंबर","9 अगस्त","1 दिसंबर","26 जनवरी"],"correct":"15 नवंबर","strategy":"बिरसा मुंडा की जयंती पर। MP सरकार ने इसे बड़े स्तर पर मनाने की घोषणा की है।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"भूरी बाई किस कला के लिए प्रसिद्ध हैं?","options":["पिथोरा चित्रकला","गोंड चित्रकला","बांस शिल्प","धातु शिल्प"],"correct":"पिथोरा चित्रकला","strategy":"उन्हें 2021 में पद्म श्री मिला। वे भील समुदाय (झाबुआ) से हैं।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"1857 के विद्रोह में ''भीमा नायक'' ने किस क्षेत्र से नेतृत्व किया था?","options":["मंडला","बड़वानी (सेंधवा)","बैतूल","छिंदवाड़ा"],"correct":"बड़वानी (सेंधवा)","strategy":"भीमा नायक निमाड़ और बड़वानी के जंगलों में सक्रिय थे।"},{"type":"exam_pattern","topic":"Tribal Personalities Trend","analysis":"Unit 2 Tribal Trend:","stats":["स्वतंत्रता सेनानी (क्षेत्र/मृत्यु स्थल): 2 प्रश्न","कलाकार (पद्म पुरस्कार): 1-2 प्रश्न","रानी/शासक (समाधि): 1 प्रश्न"],"trend":"आयोग अब कलाकारों की ''विशिष्ट उपलब्धि'' (जैसे जनगढ़ सिंह श्याम की जापान में मृत्यु) और स्वतंत्रता सेनानियों के ''जन्म स्थान'' (Birthplace) पर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 2: Important Tribal Personalities of Madhya Pradesh"},{"type":"p","text":"In recent years, MPPSC has significantly increased its focus on ''Tribal Personalities''. This topic bridges Unit 2 (History) and Unit 10 (Tribes). Special attention must be paid to Freedom Fighters and Padma Shri awardee artists."},{"type":"h2","text":"1. Tribal Freedom Fighters"},{"type":"h3","text":"Tantya Bhil - ''The Indian Robinhood''"},{"type":"p","text":"A legendary revolutionary of the Nimar region who looted British treasuries to distribute wealth among the poor."},{"type":"highlight","level":"critical","text":"Birth: 1842 (Pandhana, Khandwa).\nMartyrdom: Hanged in Jabalpur (1889).\nMemorial: Patalpani (Indore). Patalpani Railway Station is now renamed ''Tantya Bhil Station''.","icon":"🏹"},{"type":"h3","text":"Bhima Nayak - ''Robinhood of Nimar''"},{"type":"ul","items":["**Region:** Barwani (Sendhwa).","**Struggle:** Fought the ''Battle of Ambapani'' against the British in 1857.","**Death:** He was deported to Port Blair (Cellular Jail), where he died."]},{"type":"h3","text":"Shankar Shah & Raghunath Shah"},{"type":"p","text":"Rulers of the Gondwana Kingdom (Garha Mandla). The father (Shankar) and son (Raghunath) fought with both pen (poetry) and sword."},{"type":"fact_card","title":"Sacrifice Day","facts":["The British blew them up from the mouth of a cannon (18 Sept 1857).","Location: Jabalpur (In front of Collectorate).","Their patriotic poems ignited the fire of rebellion."],"icon":"🔥"},{"type":"h2","text":"2. Historical Queens"},{"type":"h3","text":"Rani Durgavati"},{"type":"p","text":"The most glorious queen of Gondwana. She was married to King Dalpat Shah (Gond) but was a Chandela princess (Kalinjar)."},"",{"type":"table","instruction":"Rani Durgavati: Key Facts","head":["Fact","Detail"],"body":[["Reign","1550-1564 (As regent for her son Vir Narayan)."],["Battle","Fought against Akbar''s general ''Asaf Khan'' (Battle of Narrai Nala)."],["Tomb","Barela (Jabalpur)."],["Legacy","Built ''Adhartal'' and ''Ranital'' in Jabalpur."]]},{"type":"h2","text":"3. Tribal Artists (Padma Shri Awardees)"},{"type":"p","text":"Tribal artists from MP have achieved global recognition. Memorizing Padma Shri winners is mandatory for MPPSC."},{"type":"mnemonic","topic":"Artists & Their Art","trick":"Bhuri''s Pithora, Jangarh''s Gond, Baiju''s Wood","visual":"🎨","explanation":"1. **Bhuri** Bai (Jhabua) - Pithora Painting. (Started as a laborer in Bharat Bhavan). First tribal woman to get Padma Shri in art.\n2. **Jangarh** Singh Shyam (Dindori) - Gond Painting. Creator of ''Jangarh Kalam''. (Died in Japan).\n3. **Baiju** - Wood Craft."},{"type":"fact_card","title":"Other Key Personalities","facts":["Pema Phalya: Bhil painter (Pithora). Passed away recently.","Badal Bhoi: Tribal leader from Chhindwara. The Tribal Museum in Chhindwara is named after him.","Ganjan Singh Korku: Leader of Ghoradongri (Betul) Jungle Satyagraha."],"icon":"🏆"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"When is ''Janjatiya Gaurav Divas'' (Tribal Pride Day) celebrated?","options":["15 November","9 August","1 December","26 January"],"correct":"15 November","strategy":"On the birth anniversary of Birsa Munda. Declared by Govt of India."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Bhuri Bai is famous for which art form?","options":["Pithora Painting","Gond Painting","Bamboo Craft","Metal Craft"],"correct":"Pithora Painting","strategy":"She belongs to the Bhil community (Jhabua) and received Padma Shri in 2021."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"From which region did ''Bhima Nayak'' lead the 1857 revolt?","options":["Mandla","Barwani (Sendhwa)","Betul","Chhindwara"],"correct":"Barwani (Sendhwa)","strategy":"Bhima Nayak operated in the forests of Nimar and Barwani."},{"type":"exam_pattern","topic":"Tribal Personalities Trend","analysis":"Unit 2 Tribal Trend:","stats":["Freedom Fighters (Region/Death Place): 2 questions","Artists (Padma Awards): 1-2 questions","Queen/Rulers (Tombs): 1 question"],"trend":"The Commission is now asking about ''Specific Achievements'' (like Jangarh Singh Shyam''s death in Japan) and ''Birthplaces'' of freedom fighters."}]}', 'mp_gk', NULL, 18, 1, 1770836646, 1770836646, 'blog', 'unit_2', 'Important Tribal Personalities of Madhya Pradesh', 1, 0, 0, 1, 0, 'Unit 2: मध्य प्रदेश के प्रमुख जनजातीय व्यक्तित्व (Tribal Personalities) MPPSC ने पिछले कुछ वर्षों में ''जनजातीय व्यक्तित्व'' पर अपना फोकस बहुत बढ़ाया है। यह टॉपिक Unit 2 (इतिहास) और Unit 10 (जनजाति) दोन...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('75e873e0-a009-4511-a7dd-58fa1b08bd17', 'mountains-of-india-unit-3-mppsc', 'Mountains of India: Himalayas & Peninsular Ranges | भारत के पर्वत', 'Complete guide to Indian Mountains for MPPSC Unit 3. Covers Himalayas (Trans, Greater, Shiwalik), Peninsular Ranges (Aravalli, Satpura, Western Ghats), and key peaks with mnemonics.', '{"hi":[{"type":"h2","text":"Unit 3: भारत के पर्वत (Mountains of India)"},{"type":"p","text":"MPPSC Unit 3 (भारत का भूगोल) में ''पर्वत'' एक आधारभूत टॉपिक है। यहाँ से प्रश्न चोटियों की ऊँचाई (Peaks), दर्रों (Passes) और उत्तर से दक्षिण के क्रम (North-South Order) पर पूछे जाते हैं। हम इसे दो भागों में बांटकर पढ़ेंगे: उत्तर के हिमालय और प्रायद्वीपीय पर्वत।"},"",{"type":"h2","text":"1. उत्तर भारत के पर्वत: हिमालय (The Himalayas)"},{"type":"p","text":"हिमालय ''नवीन वलित पर्वत'' (Young Fold Mountain) है। इसे उत्तर से दक्षिण 4 भागों में बांटा गया है।"},{"type":"mnemonic","topic":"उत्तर से दक्षिण क्रम (North to South Order)","trick":"K-L-Z --- P-D (कल जा --- पी-डी)","visual":"🏔️","explanation":"1. **K**arakoram (ट्रांस हिमालय)\n2. **L**adakh (ट्रांस हिमालय)\n3. **Z**askar (ट्रांस हिमालय)\n-- (Main Himalayas Start) --\n4. **P**ir Panjal (लघु हिमालय)\n5. **D**hauladhar (लघु हिमालय)"},{"type":"table","instruction":"हिमालय का वर्गीकरण","head":["श्रेणी (Range)","विशेषता (Features)","प्रमुख चोटियाँ/हिमनद"],"body":[["ट्रांस हिमालय (Trans)","यूरेशियन प्लेट का हिस्सा। वनस्पति रहित।","K2 (गॉडविन ऑस्टिन) - 8611 मी. (भारत की सबसे ऊंची, PoK में)। सियाचिन ग्लेशियर।"],["वृहत/महान हिमालय (Greater)","इसे ''हिमाद्रि'' कहते हैं। साल भर बर्फ।","माउंट एवरेस्ट (8848 मी.), कंचनजंगा (सिक्किम), नंदा देवी (उत्तराखंड)।"],["लघु/मध्य हिमालय (Lesser)","पर्यटन के लिए प्रसिद्ध (शिमला, मसूरी)।","पीर पंजाल (J&K), धौलाधार (HP)। घास के मैदान: मर्ग (गुलमर्ग), बुग्याल।"],["शिवालिक (Shiwalik)","सबसे नई श्रेणी। इसे ''बाह्य हिमालय'' कहते हैं।","दून (देहरादून) और द्वार (हरिद्वार) घाटियां यहाँ हैं।"]]},{"type":"h2","text":"2. प्रायद्वीपीय भारत के पर्वत (Peninsular Mountains)"},{"type":"p","text":"दक्षिण भारत के पर्वत पुराने और ''अवशिष्ट'' (Residual) या ''ब्लॉक'' पर्वत हैं।"},{"type":"h3","text":"अरावली (Aravalli)"},{"type":"ul","items":["**प्रकृति:** विश्व की सबसे पुरानी ''अवशिष्ट'' (Residual) पर्वतमाला।","**विस्तार:** गुजरात से दिल्ली तक।","**सर्वोच्च शिखर:** गुरु शिखर (1722 मी.) - माउंट आबू (राजस्थान)।"]},{"type":"h3","text":"विंध्याचल और सतपुड़ा (MP Special Focus)"},{"type":"p","text":"ये दोनों ''ब्लॉक पर्वत'' (Block Mountains) के उदाहरण हैं। इनके बीच नर्मदा ''भ्रंश घाटी'' (Rift Valley) में बहती है।"},{"type":"table","instruction":"विंध्य vs सतपुड़ा","head":["पर्वत","सर्वोच्च चोटी","विशेषता"],"body":[["विंध्याचल","सद्भावना शिखर (Goodwill Peak/Kalumar) - दमोह","उत्तर और दक्षिण भारत का विभाजक।"],["सतपुड़ा","धूपगढ़ (1350 मी.) - पचमढ़ी","महादेव श्रेणी पर स्थित। MP की सबसे ऊंची चोटी।"]]},{"type":"h3","text":"पश्चिमी घाट (सह्याद्रि) और पूर्वी घाट"},{"type":"highlight","level":"critical","text":"नीलगिरी पहाड़ियां: जहाँ पश्चिमी और पूर्वी घाट मिलते हैं।\nसर्वोच्च चोटी (नीलगिरी): दोदाबेटा (2637 मी.)।\nदक्षिण भारत की सबसे ऊंची चोटी: अनाईमुडी (2695 मी.) - अन्नामलाई पहाड़ियों पर।","icon":"⛰️"},{"type":"h2","text":"3. पूर्वोत्तर की पहाड़ियां (North-East Hills)"},{"type":"p","text":"गारो, खासी, जयंतिया (मेघालय) - ये प्रायद्वीपीय पठार का ही हिस्सा हैं (राजमहल गारो गैप)। ''खासी'' पहाड़ी पर ही मासिनराम (सर्वाधिक वर्षा) स्थित है।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"निम्नलिखित में से कौन सी श्रेणी ''ट्रांस हिमालय'' का हिस्सा नहीं है?","options":["काराकोरम","लद्दाख","जास्कर","पीर पंजाल"],"correct":"पीर पंजाल","strategy":"याद रखें Trick: K-L-Z (ट्रांस) और P (लघु हिमालय)। पीर पंजाल मुख्य हिमालय में है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"दक्षिण भारत की सबसे ऊंची चोटी कौन सी है?","options":["दोदाबेटा","अनाईमुडी","महेंद्रगिरी","धूपगढ़"],"correct":"अनाईमुडी","strategy":"अनाईमुडी (2695m) अन्नामलाई रेंज में है, जबकि दोदाबेटा (2637m) नीलगिरी में है।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"अरावली पर्वत का सर्वोच्च शिखर क्या है?","options":["गुरु शिखर","धूपगढ़","अमरकंटक","सद्भावना"],"correct":"गुरु शिखर","strategy":"माउंट आबू, राजस्थान में स्थित है।"},{"type":"exam_pattern","topic":"Mountains Trend","analysis":"Unit 3 Geography Trend:","stats":["हिमालय का विभाजन: 1 प्रश्न","दक्षिण भारत की चोटियाँ: 1-2 प्रश्न","दर्रे (Passes): 1 प्रश्न"],"trend":"अब आयोग पहाड़ियों के ''क्रम'' (Order) पर प्रश्न पूछ रहा है, जैसे: नल्लामलाई, जावादी, शेवरॉय (उत्तर से दक्षिण)।"}],"en":[{"type":"h2","text":"Unit 3: Mountains of India"},{"type":"p","text":"In MPPSC Unit 3 (Indian Geography), ''Mountains'' is a foundational topic. Questions focus on Peak heights, Passes, and North-South chronology. We will study this in two parts: Northern Himalayas and Peninsular Mountains."},"",{"type":"h2","text":"1. Mountains of the North: The Himalayas"},{"type":"p","text":"Himalayas are ''Young Fold Mountains''. They are divided into 4 parallel ranges from North to South."},{"type":"mnemonic","topic":"North to South Order","trick":"K-L-Z --- P-D","visual":"🏔️","explanation":"1. **K**arakoram (Trans)\n2. **L**adakh (Trans)\n3. **Z**askar (Trans)\n-- (Main Himalayas Start) --\n4. **P**ir Panjal (Lesser)\n5. **D**hauladhar (Lesser)"},{"type":"table","instruction":"Classification of Himalayas","head":["Range","Features","Key Peaks/Glaciers"],"body":[["Trans Himalayas","Part of Eurasian plate. Vegetation-less.","K2 (Godwin Austen) - 8611m (Highest in India, in PoK). Siachen Glacier."],["Greater Himalayas (Himadri)","Always snow-covered.","Mt. Everest (8848m), Kanchenjunga (Sikkim), Nanda Devi (UK)."],["Lesser/Middle Himalayas","Famous for tourism (Shimla, Mussoorie).","Pir Panjal (J&K), Dhauladhar (HP). Grasslands: Marg (Gulmarg), Bugyal."],["Shiwalik","Youngest range. Called ''Outer Himalayas''.","Valleys like Dun (Dehradun) and Dwar (Haridwar)."]]},{"type":"h2","text":"2. Peninsular Mountains (South India)"},{"type":"p","text":"Mountains of South India are old ''Residual'' or ''Block'' mountains."},{"type":"h3","text":"Aravalli"},{"type":"ul","items":["**Nature:** Oldest ''Residual'' mountain range in the world.","**Extent:** Gujarat to Delhi.","**Highest Peak:** Guru Shikhar (1722m) - Mt. Abu (Rajasthan)."]},{"type":"h3","text":"Vindhyachal & Satpura (MP Special Focus)"},{"type":"p","text":"Examples of ''Block Mountains''. Narmada flows in a ''Rift Valley'' between them."},{"type":"table","instruction":"Vindhya vs Satpura","head":["Mountain","Highest Peak","Feature"],"body":[["Vindhyachal","Sadbhavana Shikhar (Goodwill Peak) - Damoh","Divides North and South India."],["Satpura","Dhupgarh (1350m) - Pachmarhi","Located on Mahadeo Hills. Highest peak of MP."]]},{"type":"h3","text":"Western Ghats (Sahyadri) & Eastern Ghats"},{"type":"highlight","level":"critical","text":"Nilgiri Hills: Meeting point of Western & Eastern Ghats.\nHighest Peak (Nilgiri): Doddabetta (2637m).\nHighest Peak of South India: Anaimudi (2695m) - on Annamalai Hills.","icon":"⛰️"},{"type":"h2","text":"3. North-East Hills"},{"type":"p","text":"Garo, Khasi, Jaintia (Meghalaya) - These are actually part of the Peninsular Plateau (Rajmahal-Garo Gap). Mawsynram (Wettest place) is on ''Khasi'' hills."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Which of the following is NOT part of ''Trans Himalayas''?","options":["Karakoram","Ladakh","Zaskar","Pir Panjal"],"correct":"Pir Panjal","strategy":"Remember the Trick: K-L-Z are Trans. Pir Panjal is in Lesser Himalayas."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which is the highest peak of South India?","options":["Doddabetta","Anaimudi","Mahendragiri","Dhupgarh"],"correct":"Anaimudi","strategy":"Anaimudi (2695m) is in Annamalai range, Doddabetta (2637m) is in Nilgiris."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"What is the highest peak of Aravalli Range?","options":["Guru Shikhar","Dhupgarh","Amarkantak","Sadbhavana"],"correct":"Guru Shikhar","strategy":"Located in Mount Abu, Rajasthan."},{"type":"exam_pattern","topic":"Mountains Trend","analysis":"Unit 3 Geography Trend:","stats":["Himalayan Divisions: 1 question","Peaks of South India: 1-2 questions","Passes: 1 question"],"trend":"The Commission is now asking the ''North-South Order'' of hills, e.g., Nallamala -> Javadi -> Shevaroy."}]}', 'geography', NULL, 18, 1, 1770836741, 1772640835, 'blog', 'unit_3', 'Mountains', 0, 0, 1, 1, 0, 'Unit 3: भारत के पर्वत (Mountains of India) MPPSC Unit 3 (भारत का भूगोल) में ''पर्वत'' एक आधारभूत टॉपिक है। यहाँ से प्रश्न चोटियों की ऊँचाई (Peaks), दर्रों (Passes) और उत्तर से दक्षिण के क्रम (North-Sout...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('f4adbe9e-eef9-414c-bc0b-51df3105369c', 'plateaus-hills-india-unit-3-mppsc', 'Plateaus & Hills of India: Peninsular & North-East | भारत के पठार और पहाड़ियां', 'Comprehensive guide to the Peninsular Plateau, Central Highlands, and major Hills of India. Covers Chota Nagpur, Deccan, Western Ghats, and key passes like Thal Ghat & Pal Ghat.', '{"hi":[{"type":"h2","text":"Unit 3: भारत के पठार और पहाड़ियां (Plateaus & Hills)"},{"type":"p","text":"भारत का ''प्रायद्वीपीय पठार'' (Peninsular Plateau) सबसे प्राचीन भू-भाग है (गोंडवानालैंड का हिस्सा)। यह त्रिभुजाकार है और खनिजों का भंडार (Storehouse of Minerals) कहलाता है। MPPSC में पठारों की स्थिति और पहाड़ियों के उत्तर-दक्षिण क्रम पर प्रश्न आते हैं।"},"",{"type":"h2","text":"1. प्रमुख पठार (Major Plateaus)"},{"type":"table","instruction":"भारत के प्रमुख पठार","head":["पठार","स्थान","विशेषता (Key Fact)"],"body":[["छोटा नागपुर (Chota Nagpur)","झारखंड, प. बंगाल","इसे ''भारत का रूर'' (Ruhr of India) कहते हैं। खनिज संपन्न (कोयला, लोहा)। पारसनाथ (1365 मी.) सर्वोच्च चोटी है।"],["दक्कन का पठार (Deccan)","महाराष्ट्र, कर्नाटक, तेलंगाना","ज्वालामुखी लावा (बेसाल्ट) से निर्मित। काली मिट्टी (रेगुर) की अधिकता। कपास के लिए प्रसिद्ध।"],["मालवा का पठार (Malwa)","मध्य प्रदेश, राजस्थान","चंबल और बेतवा नदियाँ बहती हैं। इसे ''गेहूं की डलिया'' कहते हैं।"],["मेघालय/शिलॉन्ग पठार","मेघालय","यह हिमालय का नहीं, बल्कि ''प्रायद्वीपीय पठार'' का हिस्सा है। राजमहल-गारो गैप (Malda Gap) द्वारा अलग हुआ है।"]]},{"type":"h2","text":"2. प्रमुख पहाड़ियां (Major Hills)"},{"type":"h3","text":"पश्चिमी घाट (Western Ghats / Sahyadri)"},{"type":"p","text":"यह ताप्ती के मुहाने से कन्याकुमारी तक विस्तृत है। यह एक ''भ्रंश कगार'' (Escarpment) है, न कि वास्तविक पर्वत।"},{"type":"ul","items":["**उत्तरी सह्याद्रि (महाराष्ट्र):** सर्वोच्च चोटी - कलसुबाई (1646 मी.)।","**दक्षिणी सह्याद्रि (कर्नाटक):** सर्वोच्च चोटी - कुद्रेमुख (लौह अयस्क के लिए प्रसिद्ध)।"]},{"type":"h3","text":"पूर्वी घाट (Eastern Ghats)"},{"type":"p","text":"यह कटा-फटा (Discontinuous) है क्योंकि महानदी, गोदावरी, कृष्णा नदियाँ इसे काटती हैं। सर्वोच्च चोटी: जिंधगड़ा (1690 मी.) / महेंद्रगिरी।"},{"type":"mnemonic","topic":"पूर्वी घाट की पहाड़ियां (उत्तर से दक्षिण)","trick":"Nalla Pal Java Shev (नल्ला पल जावा सेव)","visual":"⬇️","explanation":"1. **Nalla**mala (आंध्र प्रदेश)\n2. **Pal**konda (आंध्र प्रदेश)\n3. **Java**di (तमिलनाडु)\n4. **Shev**aroy (तमिलनाडु)"},{"type":"h2","text":"3. प्रमुख दर्रे (Passes of Western Ghats)"},{"type":"p","text":"पश्चिमी घाट को पार करने के लिए 4 प्रमुख दर्रे हैं।"},{"type":"mnemonic","topic":"पश्चिमी घाट के दर्रे (उत्तर से दक्षिण)","trick":"Thal Bhor Pal Sen","visual":"🛣️","explanation":"1. **Thal** Ghat: मुंबई -> नासिक (NH-3)।\n2. **Bhor** Ghat: मुंबई -> पुणे (NH-4)।\n3. **Pal** Ghat: कोच्चि -> कोयंबटूर (नीलगिरी और अन्नामलाई के बीच)।\n4. **Sen**kota Gap: तिरुवनंतपुरम -> मदुरै (इलायची पहाड़ियों में)।"},"",{"type":"h2","text":"4. अन्य महत्वपूर्ण पहाड़ियां"},{"type":"ul","items":["**गिर पहाड़ियां (Gir Hills):** गुजरात। एशियाई शेरों (Asiatic Lions) का एकमात्र घर।","**बाबा बुदन की पहाड़ियां:** कर्नाटक। कॉफी उत्पादन के लिए प्रसिद्ध।","**लुशाई (मिजो) पहाड़ियां:** मिजोरम। इसे ''ब्लू माउंटेन'' (फावंगपुई) भी कहते हैं।","**गारो-खासी-जयंतिया:** मेघालय। कीपाकार (Funnel shaped) होने के कारण यहाँ विश्व की सर्वाधिक वर्षा (मासिनराम) होती है।"]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"निम्नलिखित में से कौन सी पहाड़ी ''मेघालय पठार'' का भाग नहीं है?","options":["भुवन पहाड़ियां","गारो","खासी","जयंतिया"],"correct":"भुवन पहाड़ियां","strategy":"गारो, खासी, जयंतिया मेघालय में हैं। भुवन पहाड़ियां असम (बराक घाटी) में हैं।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"छोटा नागपुर पठार की सबसे ऊंची चोटी कौन सी है?","options":["धूपगढ़","पारसनाथ","गुरु शिखर","महेंद्रगिरी"],"correct":"पारसनाथ","strategy":"पारसनाथ (सम्मेद शिखर) जैन धर्म का प्रमुख तीर्थ है।"},{"type":"pyq","exam":"UPSC / MPPSC Geo","year":2017,"question":"कार्डमम (इलायची) पहाड़ियां किन राज्यों की सीमा पर स्थित हैं?","options":["कर्नाटक और केरल","केरल और तमिलनाडु","तमिलनाडु और आंध्र","कर्नाटक और तमिलनाडु"],"correct":"केरल और तमिलनाडु","strategy":"यह भारत की सबसे दक्षिणी पहाड़ी श्रेणी है।"},{"type":"exam_pattern","topic":"Hills & Plateaus Trend","analysis":"Unit 3 Geography Trend:","stats":["पठार की विशेषता (खनिज/मिट्टी): 1 प्रश्न","पहाड़ियों का क्रम (North-South): 1 प्रश्न","दर्रे (Passes - Matching): 1 प्रश्न"],"trend":"आयोग अब ''पूर्वी घाट'' और ''पूर्वोत्तर की पहाड़ियों'' (जैसे मिकिर, रेंगमा) पर फोकस कर रहा है, जो अक्सर छूट जाती हैं।"}],"en":[{"type":"h2","text":"Unit 3: Plateaus & Hills of India"},{"type":"p","text":"The ''Peninsular Plateau'' is the oldest landmass of India (Part of Gondwanaland). It is triangular and known as the ''Storehouse of Minerals''. In MPPSC, questions focus on the location of plateaus and the North-South order of hills."},"",{"type":"h2","text":"1. Major Plateaus"},{"type":"table","instruction":"Major Plateaus of India","head":["Plateau","Location","Key Fact"],"body":[["Chota Nagpur","Jharkhand, WB","Called ''Ruhr of India''. Rich in minerals (Coal, Iron). Highest Peak: Parasnath (1365m)."],["Deccan Plateau","Maharashtra, Karnataka, Telangana","Made of Volcanic Lava (Basalt). Rich in Black Soil (Regur). Famous for Cotton."],["Malwa Plateau","MP, Rajasthan","Drained by Chambal & Betwa. Called ''Basket of Roti'' (Wheat bowl)."],["Meghalaya/Shillong","Meghalaya","It is NOT part of Himalayas, but an extension of Peninsular Plateau. Separated by Rajmahal-Garo Gap (Malda Gap)."]]},{"type":"h2","text":"2. Major Hills"},{"type":"h3","text":"Western Ghats (Sahyadri)"},{"type":"p","text":"Extends from Tapti mouth to Kanyakumari. It is an ''Escarpment'', not a true mountain."},{"type":"ul","items":["**Northern Sahyadri (Maharashtra):** Highest Peak - Kalsubai (1646m).","**Southern Sahyadri (Karnataka):** Highest Peak - Kudremukh (Iron ore rich)."]},{"type":"h3","text":"Eastern Ghats"},{"type":"p","text":"It is discontinuous (cut by Mahanadi, Godavari, Krishna). Highest Peak: Jindhagada (1690m) / Mahendragiri."},{"type":"mnemonic","topic":"Eastern Ghats Hills (North to South)","trick":"Nalla Pal Java Shev","visual":"⬇️","explanation":"1. **Nalla**mala (Andhra)\n2. **Pal**konda (Andhra)\n3. **Java**di (Tamil Nadu)\n4. **Shev**aroy (Tamil Nadu)"},{"type":"h2","text":"3. Major Passes (Western Ghats)"},{"type":"p","text":"There are 4 major passes connecting the coastal plains to the plateau."},{"type":"mnemonic","topic":"Passes of Western Ghats (North to South)","trick":"Thal Bhor Pal Sen","visual":"🛣️","explanation":"1. **Thal** Ghat: Mumbai -> Nashik (NH-3).\n2. **Bhor** Ghat: Mumbai -> Pune (NH-4).\n3. **Pal** Ghat: Kochi -> Coimbatore (Between Nilgiri & Annamalai).\n4. **Sen**kota Gap: Thiruvananthapuram -> Madurai (In Cardamom Hills)."},"",{"type":"h2","text":"4. Other Important Hills"},{"type":"ul","items":["**Gir Hills:** Gujarat. Only home to Asiatic Lions.","**Baba Budan Hills:** Karnataka. Famous for Coffee cultivation.","**Lushai (Mizo) Hills:** Mizoram. Also called ''Blue Mountain'' (Phawngpui).","**Garo-Khasi-Jaintia:** Meghalaya. Due to funnel shape, Mawsynram (Wettest place) is located here."]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which of the following hills is NOT part of Meghalaya Plateau?","options":["Bhuvan Hills","Garo","Khasi","Jaintia"],"correct":"Bhuvan Hills","strategy":"Garo, Khasi, Jaintia are in Meghalaya. Bhuvan Hills are in Assam (Barak Valley)."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"Which is the highest peak of Chota Nagpur Plateau?","options":["Dhupgarh","Parasnath","Guru Shikhar","Mahendragiri"],"correct":"Parasnath","strategy":"Parasnath (Sammed Shikhar) is a major Jain pilgrimage site."},{"type":"pyq","exam":"UPSC / MPPSC Geo","year":2017,"question":"Cardamom Hills lie along the border of which states?","options":["Karnataka & Kerala","Kerala & Tamil Nadu","Tamil Nadu & Andhra","Karnataka & Tamil Nadu"],"correct":"Kerala & Tamil Nadu","strategy":"These are the southernmost hills of India."},{"type":"exam_pattern","topic":"Hills & Plateaus Trend","analysis":"Unit 3 Geography Trend:","stats":["Plateau Features (Minerals/Soil): 1 question","Order of Hills (North-South): 1 question","Passes (Matching): 1 question"],"trend":"The Commission is now focusing on ''Eastern Ghats'' and ''North-East Hills'' (e.g., Mikir, Rengma) which are often neglected."}]}', 'geography', NULL, 15, 1, 1770836906, 1771008859, 'blog', 'unit_3', 'Hills, Plateaus', 1, 0, 1, 1, 0, 'Unit 3: भारत के पठार और पहाड़ियां (Plateaus & Hills) भारत का ''प्रायद्वीपीय पठार'' (Peninsular Plateau) सबसे प्राचीन भू-भाग है (गोंडवानालैंड का हिस्सा)। यह त्रिभुजाकार है और खनिजों का भंडार (Storehouse ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('cfa75485-7595-4fe2-9eff-f44f979c1ca8', 'rivers-drainage-system-india-unit-3-mppsc', 'Drainage System of India: Himalayan & Peninsular Rivers | भारत का अपवाह तंत्र', 'Master the Indian River System for MPPSC Unit 3. Detailed analysis of Ganga, Indus, Brahmaputra, and Godavari/Krishna basins. Includes mnemonics for tributaries and PYQs.', '{"hi":[{"type":"h2","text":"Unit 3: भारत की नदियाँ (Rivers of India)"},{"type":"p","text":"भारत के अपवाह तंत्र (Drainage System) को दो मुख्य भागों में बांटा गया है: हिमालयी नदियाँ (सदानीरा - Perennial) और प्रायद्वीपीय नदियाँ (मौसमी - Seasonal)। MPPSC में नदियों के ''उद्गम'' (Origin), ''सहायक नदियाँ'' (Tributaries) और उन पर बने ''बांधों'' (Dams) से प्रश्न पूछे जाते हैं।"},"",{"type":"h2","text":"1. हिमालयी अपवाह तंत्र (Himalayan System)"},{"type":"h3","text":"सिंधु नदी तंत्र (Indus System)"},{"type":"mnemonic","topic":"सिंधु की सहायक नदियाँ (उत्तर से दक्षिण)","trick":"In June Car Run Beats Slow (Indus, Jhelum, Chenab, Ravi, Beas, Sutlej)","visual":"🌊","explanation":"1. **J**helum (वेरीनाग) - वुलर झील से बहती है।\n2. **C**henab (बारालाचा दर्रा) - सबसे बड़ी सहायक नदी। (चंद्र और भागा मिलने से बनती है)।\n3. **R**avi (रोहतांग दर्रा)।\n4. **B**eas (व्यास कुंड) - एकमात्र नदी जो भारत में ही शुरू होकर भारत में ही (सतलज में) मिल जाती है।\n5. **S**utlej (राकस ताल, तिब्बत) - भाखड़ा नांगल बांध इसी पर है।"},{"type":"h3","text":"गंगा नदी तंत्र (Ganga System)"},{"type":"p","text":"भारत की सबसे लंबी नदी (2525 km)। यह ''भागीरथी'' और ''अलकनंदा'' के देवप्रयाग में मिलने से ''गंगा'' बनती है।"},{"type":"mnemonic","topic":"गंगा की बायीं तट (Left Bank) की सहायक नदियाँ","trick":"Reliance 3G ka Maalik (R-G-G-G-K-M)","visual":"⬅️","explanation":"**R**amganga (सबसे पहले मिलती है)\n**G**omti (मैदान से निकलती है - पीलीभीत)\n**G**haghara (सबसे बड़ी सहायक पानी की मात्रा में)\n**G**andak\n**K**osi (बिहार का शोक)\n**M**ahananda (अंतिम सहायक नदी)"},{"type":"highlight","level":"critical","text":"यमुना: गंगा की सबसे लंबी सहायक नदी (प्रयागराज में मिलती है)।\nसोन: दक्षिण से आकर गंगा में मिलने वाली प्रमुख नदी (अमरकंटक से निकलती है)।","icon":"💧"},{"type":"h3","text":"ब्रह्मपुत्र नदी तंत्र"},{"type":"ul","items":["**उद्गम:** चेमायुंगडुंग ग्लेशियर (तिब्बत)।","**नाम:** तिब्बत में ''सांगपो'' (Tsangpo), अरुणाचल में ''दिहांग'', असम में ''ब्रह्मपुत्र'', और बांग्लादेश में ''जमुना''।","**माजुली द्वीप:** विश्व का सबसे बड़ा नदी द्वीप (असम में)।"]},"",{"type":"h2","text":"2. प्रायद्वीपीय अपवाह तंत्र (Peninsular System)"},{"type":"table","instruction":"पूर्व और पश्चिम की ओर बहने वाली नदियाँ","head":["पूर्व वाहिनी ( बंगाल की खाड़ी)","पश्चिम वाहिनी (अरब सागर)"],"body":[["महानदी, गोदावरी, कृष्णा, कावेरी","नर्मदा, ताप्ती, माही, साबरमती"],["डेल्टा (Delta) बनाती हैं।","एश्चुअरी (Estuary/ज्वारनदमुख) बनाती हैं।"],["धीमी गति, चौड़ी घाटियाँ।","तेज गति, भ्रंश घाटी (Rift Valley) में बहती हैं।"]]},{"type":"fact_card","title":"महत्वपूर्ण प्रायद्वीपीय नदियाँ","facts":["गोदावरी: दक्षिण भारत की सबसे लंबी नदी (1465 km)। इसे ''दक्षिण गंगा'' या ''वृद्ध गंगा'' कहते हैं। उद्गम: त्र्यंबकेश्वर (नासिक)।","कावेरी: इसे ''दक्षिण भारत की गंगा'' (Ganga of the South) कहते हैं क्योंकि यह गंगा की तरह साल भर बहती है (लौटते मानसून से वर्षा)। उद्गम: ब्रह्मगिरी (कर्नाटक)।","माही: एकमात्र नदी जो ''कर्क रेखा'' (Tropic of Cancer) को दो बार काटती है।"],"icon":"🚩"},{"type":"h2","text":"3. अन्य महत्वपूर्ण तथ्य"},{"type":"ul","items":["**लूनी नदी:** इसे ''लवण नदी'' कहते हैं। यह कच्छ के रण में विलुप्त हो जाती है (Landlocked River)।","**दामोदर नदी:** इसे ''बंगाल का शोक'' कहा जाता था। हुगली की सहायक नदी है।","**चित्रकूट जलप्रपात:** इंद्रावती नदी (छत्तीसगढ़) पर। इसे ''भारत का नियाग्रा'' कहते हैं।"]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"निम्न में से कौन सी नदी ''भ्रंश घाटी'' (Rift Valley) से होकर बहती है?","options":["गंगा","यमुना","नर्मदा","कावेरी"],"correct":"नर्मदा","strategy":"नर्मदा और ताप्ती भ्रंश घाटी में बहने वाली मुख्य नदियाँ हैं।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"सोन नदी का उद्गम स्थल कहाँ है?","options":["पचमढ़ी","अमरकंटक","महाबलेश्वर","यमुनोत्री"],"correct":"अमरकंटक","strategy":"अमरकंटक से तीन नदियाँ निकलती हैं: नर्मदा (पश्चिम), सोन (उत्तर), और जोहिला।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"किस नदी को ''दक्षिण गंगा'' के नाम से जाना जाता है?","options":["कावेरी","कृष्णा","गोदावरी","महानदी"],"correct":"गोदावरी","strategy":"लंबाई और आकार के कारण गोदावरी को ''दक्षिण गंगा'' कहते हैं, जबकि पवित्रता के कारण कावेरी को ''दक्षिण भारत की गंगा''।"},{"type":"exam_pattern","topic":"Rivers Trend","analysis":"Unit 3 Geography Trend:","stats":["नदी उद्गम (Origin): 1-2 प्रश्न","सहायक नदियाँ (Tributaries): 1 प्रश्न","नदी घाटी परियोजना (Dams): 1 प्रश्न"],"trend":"अब आयोग नदियों के ''उत्तर से दक्षिण क्रम'' (जैसे गोदावरी की सहायक नदियाँ: प्राणहिता, इंद्रावती) और जलप्रपातों (Waterfalls) पर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 3: Rivers of India (Drainage System)"},{"type":"p","text":"The Indian Drainage System is broadly divided into two: Himalayan Rivers (Perennial) and Peninsular Rivers (Seasonal). In MPPSC, questions focus on ''Origin'', ''Tributaries'', and ''Dams'' built on these rivers."},"",{"type":"h2","text":"1. Himalayan River System"},{"type":"h3","text":"Indus River System"},{"type":"mnemonic","topic":"Indus Tributaries (North to South)","trick":"In June Car Run Beats Slow (Indus, Jhelum, Chenab, Ravi, Beas, Sutlej)","visual":"🌊","explanation":"1. **J**helum (Verinag) - Flows through Wular Lake.\n2. **C**henab (Baralacha Pass) - Largest tributary (formed by Chandra + Bhaga).\n3. **R**avi (Rohtang Pass).\n4. **B**eas (Vyas Kund) - Only tributary that starts and ends within India (meets Sutlej).\n5. **S**utlej (Rakas Tal, Tibet) - Bhakra Nangal Dam is on this."},{"type":"h3","text":"Ganga River System"},{"type":"p","text":"Longest river in India (2525 km). Formed by the confluence of ''Bhagirathi'' and ''Alaknanda'' at Devprayag."},{"type":"mnemonic","topic":"Left Bank Tributaries of Ganga","trick":"Reliance 3G ka Maalik (R-G-G-G-K-M)","visual":"⬅️","explanation":"**R**amganga (First to join)\n**G**omti (Originates from plains - Pilibhit)\n**G**haghara (Largest by volume)\n**G**andak\n**K**osi (Sorrow of Bihar)\n**M**ahananda (Last major tributary)"},{"type":"highlight","level":"critical","text":"Yamuna: Longest tributary of Ganga (Joins at Prayagraj).\nSon: Major tributary joining Ganga from the South (Originates at Amarkantak).","icon":"💧"},{"type":"h3","text":"Brahmaputra River System"},{"type":"ul","items":["**Origin:** Chemayungdung Glacier (Tibet).","**Names:** ''Tsangpo'' in Tibet, ''Dihang'' in Arunachal, ''Brahmaputra'' in Assam, and ''Jamuna'' in Bangladesh.","**Majuli Island:** World''s largest river island (in Assam)."]},"",{"type":"h2","text":"2. Peninsular River System"},{"type":"table","instruction":"East Flowing vs West Flowing","head":["East Flowing (Bay of Bengal)","West Flowing (Arabian Sea)"],"body":[["Mahanadi, Godavari, Krishna, Cauvery","Narmada, Tapti, Mahi, Sabarmati"],["Form Deltas.","Form Estuaries."],["Slow speed, Wide valleys.","High speed, Flow in Rift Valleys."]]},{"type":"fact_card","title":"Important Peninsular Rivers","facts":["Godavari: Longest in South India (1465 km). Called ''Dakshin Ganga'' or ''Vriddha Ganga''. Origin: Trimbakeshwar (Nashik).","Cauvery: Called ''Ganga of the South'' because it flows perennially like Ganga (receives rain from retreating monsoon). Origin: Brahmagiri.","Mahi: The only river that cuts the ''Tropic of Cancer'' twice."],"icon":"🚩"},{"type":"h2","text":"3. Other Important Facts"},{"type":"ul","items":["**Luni River:** Called ''Salt River''. Disappears in Rann of Kutch (Landlocked River).","**Damodar River:** Known as ''Sorrow of Bengal''. Tributary of Hooghly.","**Chitrakoot Falls:** On Indravati river (Chhattisgarh). Called ''Niagara of India''."]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Which of the following rivers flows through a ''Rift Valley''?","options":["Ganga","Yamuna","Narmada","Cauvery"],"correct":"Narmada","strategy":"Narmada and Tapti are the primary rift valley rivers in India."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"What is the origin place of River Son?","options":["Pachmarhi","Amarkantak","Mahabaleshwar","Yamunotri"],"correct":"Amarkantak","strategy":"Three rivers originate from Amarkantak: Narmada (West), Son (North), and Johila."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"Which river is known as ''Dakshin Ganga''?","options":["Cauvery","Krishna","Godavari","Mahanadi"],"correct":"Godavari","strategy":"Due to its length and size, Godavari is Dakshin Ganga. Cauvery is ''Ganga of the South'' due to piety/perennial flow."},{"type":"exam_pattern","topic":"Rivers Trend","analysis":"Unit 3 Geography Trend:","stats":["River Origin: 1-2 questions","Tributaries: 1 question","River Valley Projects (Dams): 1 question"],"trend":"The Commission is now focusing on the ''North-South order'' of tributaries (e.g., Godavari''s Pranhita, Indravati) and Waterfalls."}]}', 'geography', NULL, 20, 1, 1770836994, 1771008860, 'blog', 'unit_3', 'Rivers', 1, 0, 1, 1, 0, 'Unit 3: भारत की नदियाँ (Rivers of India) भारत के अपवाह तंत्र (Drainage System) को दो मुख्य भागों में बांटा गया है: हिमालयी नदियाँ (सदानीरा - Perennial) और प्रायद्वीपीय नदियाँ (मौसमी - Seasonal)। MPPSC...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('f2131107-82af-494d-91b1-b3b50023fbc4', 'lakes-of-india-unit-3-mppsc', 'Lakes of India: Freshwater, Saltwater & Lagoons | भारत की झीलें', 'Comprehensive guide to Indian Lakes for MPPSC Unit 3. Covers tectonic, volcanic, and lagoon lakes like Chilika, Wular, and Lonar with memory tricks and PYQs.', '{"hi":[{"type":"h2","text":"Unit 3: भारत की झीलें (Lakes of India)"},{"type":"p","text":"भारत में झीलों की विविधता भौगोलिक संरचना के अनुसार है। MPPSC में झीलों के प्रकार (Types), उनकी अवस्थिति (Location) और विशिष्ट भौगोलिक विशेषताओं (जैसे तैरता हुआ द्वीप) पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. झीलों का वर्गीकरण (Classification)"},{"type":"table","instruction":"उत्पत्ति के आधार पर झीलें","head":["प्रकार","विवरण","उदाहरण"],"body":[["विवर्तनिक (Tectonic)","पृथ्वी की हलचल से निर्मित।","वुलर झील (J&K)"],["लैगून (Lagoon)","समुद्र के किनारे रेत के अवरोध से बनी खारी झील।","चिल्का (ओडिशा), पुलिकट (आंध्र/तमिल)"],["ज्वालामुखी (Volcanic)","क्रेटर (Crater) में पानी भरने से निर्मित।","लोनार झील (महाराष्ट्र)"],["हिमानी (Glacial)","ग्लेशियर के पिघलने से बनी।","नैनीताल, रूपकुंड (उत्तराखंड)"]]},{"type":"h2","text":"2. महत्वपूर्ण झीलें और उनके तथ्य"},{"type":"h3","text":"मीठे पानी की झीलें (Freshwater Lakes)"},{"type":"ul","items":["**वुलर झील (J&K):** भारत की सबसे बड़ी मीठे पानी की झील। (झेलम नदी पर)।","**लोकटक झील (मणिपुर):** पूर्वोत्तर भारत की सबसे बड़ी झील। यहाँ ''फुुमदी'' (तैरते हुए द्वीप) पाए जाते हैं।","**केबुल लामजाओ (Keibul Lamjao):** विश्व का एकमात्र ''तैरता हुआ राष्ट्रीय उद्यान'' (Floating National Park) इसी झील पर है।"]},"",{"type":"h3","text":"खारे पानी की झीलें (Saltwater Lakes)"},{"type":"ul","items":["**चिल्का झील (ओडिशा):** भारत की सबसे बड़ी खारे पानी की झील और सबसे बड़ा लैगून। (UNESCO रामसर स्थल)।","**सांभर झील (राजस्थान):** भारत की सबसे बड़ी ''अंतःस्थलीय'' (Inland) खारी झील। यहाँ से देश का अधिकांश नमक उत्पादन होता है।","**पुलिकट झील:** आंध्र प्रदेश और तमिलनाडु की सीमा पर। इसके पास श्रीहरिकोटा (ISRO) द्वीप स्थित है।"]},{"type":"highlight","level":"critical","text":"वेम्बनाड झील (केरल): भारत की सबसे लंबी (Longest) झील। यहाँ ''नेहरू ट्रॉफी नौका दौड़'' (Vallam Kali) आयोजित होती है।","icon":"🛶"},{"type":"fact_card","title":"विशिष्ट झीलें","facts":["रूपकुंड (उत्तराखंड): इसे ''रहस्यमयी झील'' (Mystery Lake) या ''कंकाल झील'' कहा जाता है।","चोलामू (सिक्किम): भारत की सबसे ऊँचाई पर स्थित झील।","लोनार (महाराष्ट्र): हाल ही में इसके पानी का रंग गुलाबी (Pink) होने के कारण चर्चा में थी।"],"icon":"🧪"},{"type":"mnemonic","topic":"लैगून झीलों की ट्रिक","trick":"Chiku Pe Ke (चिक्कू पी के)","visual":"🍹","explanation":"**Chi**lka (ओडिशा)\n**Ku**lleru (आंध्र)\n**Pu**licat (आंध्र/तमिल)\n**Ke**rala (अष्टमुडी/वेम्बनाड)"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"भारत के किस राज्य में ''लोकटक झील'' स्थित है?","options":["सिक्किम","हिमाचल प्रदेश","मणिपुर","मेघालय"],"correct":"मणिपुर","strategy":"लोकटक = मणिक (मणि)। यह ''तैरते हुए द्वीपों'' के लिए प्रसिद्ध है।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"भारत की सबसे बड़ी तटीय लैगून झील कौन सी है?","options":["पुलिकट","कालीवेली","चिल्का","वेम्बनाड"],"correct":"चिल्का","strategy":"ओडिशा के तट पर स्थित चिल्का एशिया की सबसे बड़ी खारी झील है।"},{"type":"pyq","exam":"UPSC / Other PSC","year":2021,"question":"वेम्बनाड झील किस राज्य में स्थित है?","options":["आंध्र प्रदेश","केरल","ओडिशा","तमिलनाडु"],"correct":"केरल","strategy":"केरल की झीलों को ''कयाल'' (Kayal) कहा जाता है।"},{"type":"exam_pattern","topic":"Lakes Trend","analysis":"Unit 3 Geography Trend:","stats":["झीलों की अवस्थिति (Location): 1 प्रश्न","विशिष्ट विशेषता (Floating Park/Pink Water): 1 प्रश्न","लैगून/कयाल (Coastal Lakes): 1 प्रश्न"],"trend":"आयोग अब ''रामसर स्थलों'' (Ramsar Sites) और झीलों के पारिस्थितिकी तंत्र (Ecosystem) पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 3: Lakes of India"},{"type":"p","text":"Indian lakes exhibit great diversity based on geological formation. In MPPSC, questions focus on the ''Type'' of lake, its ''Location'', and unique features like floating islands or skeletal remains."},{"type":"h2","text":"1. Classification of Lakes"},{"type":"table","instruction":"Lakes Based on Origin","head":["Type","Description","Example"],"body":[["Tectonic","Formed due to earth''s movement.","Wular Lake (J&K)"],["Lagoon","Saltwater lake separated from the sea by a reef.","Chilika (Odisha), Pulicat (AP/TN)"],["Volcanic/Crater","Formed in the crater of an extinct volcano.","Lonar Lake (Maharashtra)"],["Glacial","Formed by the melting of glaciers.","Nainital, Roopkund (UK)"]]},{"type":"h2","text":"2. Major Lakes & Facts"},{"type":"h3","text":"Freshwater Lakes"},{"type":"ul","items":["**Wular Lake (J&K):** Largest freshwater lake in India. (On Jhelum river).","**Loktak Lake (Manipur):** Largest in NE India. Famous for ''Phumdis'' (floating organic matter).","**Keibul Lamjao:** The world''s only ''Floating National Park'' is situated on this lake."]},"",{"type":"h3","text":"Saltwater Lakes & Lagoons"},{"type":"ul","items":["**Chilika Lake (Odisha):** Largest saltwater lake and lagoon in India. (First Ramsar site of India).","**Sambhar Lake (Rajasthan):** Largest ''Inland'' salt lake. Major source of salt production in India.","**Pulicat Lake:** Border of AP and TN. Sriharikota (ISRO) island separates it from the Bay of Bengal."]},{"type":"highlight","level":"critical","text":"Vembanad Lake (Kerala): The longest lake in India. Famous for the ''Nehru Trophy Boat Race'' (Snake boat race).","icon":"🛶"},{"type":"fact_card","title":"Unique Lakes","facts":["Roopkund (Uttarakhand): Known as ''Mystery Lake'' or ''Skeleton Lake''.","Cholamu Lake (Sikkim): Highest altitude lake in India.","Lonar (Maharashtra): Recently in news because its water turned ''Pink'' due to Haloarchaea microbes."],"icon":"🧪"},{"type":"mnemonic","topic":"Lagoon Lakes Trick","trick":"Chiku Pe Ke","visual":"🍹","explanation":"**Chi**lka (Odisha)\n**Ku**lleru (AP)\n**Pu**licat (AP/TN)\n**Ke**rala (Ashtamudi/Vembanad)"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"In which state is ''Loktak Lake'' situated?","options":["Sikkim","Himachal Pradesh","Manipur","Meghalaya"],"correct":"Manipur","strategy":"Loktak is the jewel of Manipur, famous for floating islands."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"Which is the largest coastal lagoon in India?","options":["Pulicat","Kaliveli","Chilika","Vembanad"],"correct":"Chilika","strategy":"Chilika in Odisha is the largest brackish water lagoon in Asia."},{"type":"pyq","exam":"UPSC / Other PSC","year":2021,"question":"Vembanad Lake is located in which state?","options":["Andhra Pradesh","Kerala","Odisha","Tamil Nadu"],"correct":"Kerala","strategy":"The lakes of Kerala are locally known as ''Kayals''."},{"type":"exam_pattern","topic":"Lakes Trend","analysis":"Unit 3 Geography Trend:","stats":["Location of Lakes: 1 question","Unique Features (Floating park): 1 question","Lagoon/Kayals: 1 question"],"trend":"The Commission is now focusing on Ramsar Sites and the ecological status of lakes."}]}', 'geography', NULL, 15, 1, 1770837029, 1771008861, 'blog', 'unit_3', 'Lakes', 1, 0, 1, 1, 0, 'Unit 3: भारत की झीलें (Lakes of India) भारत में झीलों की विविधता भौगोलिक संरचना के अनुसार है। MPPSC में झीलों के प्रकार (Types), उनकी अवस्थिति (Location) और विशिष्ट भौगोलिक विशेषताओं (जैसे तैरता हुआ द...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('3a36b9ec-408c-42d7-ae22-b66763fac16d', 'el-nino-la-nina-climate-unit-3-mppsc', 'Climate Phenomena: El Niño & La Niña | अल नीनो और ला नीना', 'Understanding the impact of ENSO (El Niño Southern Oscillation) on Indian Monsoon. Detailed explanation of El Niño, La Niña, and Southern Oscillation for MPPSC Unit 3.', '{"hi":[{"type":"h2","text":"Unit 3: जलवायु घटनाएं - अल नीनो और ला नीना"},{"type":"p","text":"भारतीय मानसून एक जटिल प्रक्रिया है, जिसे प्रशांत महासागर में होने वाली हलचलें गहराई से प्रभावित करती हैं। इन घटनाओं को सामूहिक रूप से **ENSO (El Niño Southern Oscillation)** कहा जाता है। MPPSC में इनके ''प्रभाव'' और ''भारतीय मानसून के साथ संबंध'' पर विश्लेषणात्मक प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. अल नीनो (El Niño) - ''छोटा बच्चा''"},{"type":"p","text":"यह एक गर्म समुद्री जलधारा है जो पेरू (दक्षिण अमेरिका) के तट पर विकसित होती है। स्पेनिश में इसका अर्थ है ''बालक ईसा'' (क्योंकि यह क्रिसमस के आसपास दिखाई देती है)।"},"",{"type":"table","instruction":"अल नीनो का प्रभाव","head":["क्षेत्र","प्रभाव (Impact)"],"body":[["पेरू का तट (South America)","अत्यधिक वर्षा और बाढ़। मत्स्य पालन (Fishing) को नुकसान।"],["ऑस्ट्रेलिया और इंडोनेशिया","सूखा (Drought) और जंगल की आग।"],["भारतीय मानसून","**नकारात्मक प्रभाव।** भारत में कम वर्षा या सूखे की स्थिति।"]]},{"type":"h2","text":"2. ला नीना (La Niña) - ''छोटी बच्ची''"},{"type":"p","text":"यह अल नीनो की विपरीत स्थिति है। इसमें मध्य और पूर्वी प्रशांत महासागर का पानी सामान्य से अधिक ''ठंडा'' हो जाता है।"},"",{"type":"highlight","level":"important","text":"भारत के लिए अच्छी खबर: ला नीना के दौरान भारत में **सामान्य से अधिक वर्षा** होती है। यह कृषि और अर्थव्यवस्था के लिए लाभकारी है।","icon":"🌧️"},{"type":"h2","text":"3. दक्षिण दोलन (Southern Oscillation)"},{"type":"p","text":"प्रशांत महासागर और हिंद महासागर के बीच वायुदाब (Air Pressure) में होने वाले बदलाव को ''दक्षिण दोलन'' कहते हैं। इसे मापने के लिए **टाहिटी (Tahiti)** और **डार्विन (Darwin)** के बीच दबाव के अंतर को देखा जाता है।"},{"type":"mnemonic","topic":"अल नीनो और ला नीना का अंतर","trick":"El Nino = Bad for India | La Nina = Good for India","visual":"⚖️","explanation":"**El Nino (E - Evil):** मानसून को कमजोर करता है।\n**La Nina (L - Lucky):** मानसून को मजबूत करता है।"},{"type":"fact_card","title":"इंडियन ओशन डिपोल (IOD)","facts":["इसे ''भारतीय नीनो'' भी कहा जाता है।","यह हिंद महासागर के तापमान में अंतर (अरब सागर और बंगाल की खाड़ी) को दर्शाता है।","धनात्मक (+ve) IOD भारत में अल नीनो के खराब प्रभाव को कम कर सकता है।"],"icon":"🌊"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"भारतीय मानसून पर ''अल नीनो'' का क्या प्रभाव पड़ता है?","options":["वर्षा में वृद्धि","वर्षा में कमी","वर्षा पर कोई प्रभाव नहीं","तापमान में भारी गिरावट"],"correct":"वर्षा में कमी","strategy":"अल नीनो मानसून की हवाओं को कमजोर कर देता है, जिससे भारत में वर्षा कम होती है।"},{"type":"pyq","exam":"MPPSC Mains GS-1","year":2021,"question":"''अल नीनो'' क्या है? इसके भारतीय कृषि पर प्रभाव की व्याख्या कीजिए। (5 marks)","answer":"अल नीनो प्रशांत महासागर की गर्म जलधारा है। यह भारतीय मानसून को अनिश्चित बनाता है, जिससे सूखे की स्थिति पैदा होती है, फसलें बर्बाद होती हैं और ग्रामीण अर्थव्यवस्था प्रभावित होती है।","strategy":"मेंस में इसके भौगोलिक कारण (Walker Cell का कमजोर होना) भी लिखें।"},{"type":"exam_pattern","topic":"Climate Trend","analysis":"Unit 3 Climate Trend:","stats":["अल नीनो का प्रभाव: 1 प्रश्न","वायुदाब पेटियां (Pressure Belts): 1 प्रश्न","मानसून का आगमन: 1 प्रश्न"],"trend":"आयोग अब ''जेट स्ट्रीम'' (Jet Streams) और ''IOD'' जैसे नए टॉपिक्स को अल नीनो के साथ जोड़कर पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 3: Climate Phenomena - El Niño & La Niña"},{"type":"p","text":"The Indian Monsoon is a complex process influenced by events in the Pacific Ocean. Collectively known as **ENSO (El Niño Southern Oscillation)**, these phenomena dictate rainfall patterns. For MPPSC, focus on their ''Impacts'' and ''Relationship with Indian Monsoon''."},{"type":"h2","text":"1. El Niño (The Little Boy)"},{"type":"p","text":"It is the abnormal warming of surface waters in the eastern tropical Pacific Ocean, near Peru. In Spanish, it means ''Child Christ'' because it often appears around Christmas."},"",{"type":"table","instruction":"Impact of El Niño","head":["Region","Impact"],"body":[["Peru Coast (South America)","Heavy rains and flooding. Damage to the fishing industry."],["Australia & Indonesia","Droughts and bushfires."],["Indian Monsoon","**Negative Impact.** Weakens the monsoon, leading to lower rainfall or drought."]]},{"type":"h2","text":"2. La Niña (The Little Girl)"},{"type":"p","text":"It is the opposite of El Niño. It represents the unusual cooling of the tropical eastern Pacific."},"",{"type":"highlight","level":"important","text":"Good news for India: During La Niña, India receives **above-normal rainfall**, which is beneficial for agriculture.","icon":"🌧️"},{"type":"h2","text":"3. Southern Oscillation (SO)"},{"type":"p","text":"The periodic change in pressure conditions over the southern Pacific and Indian Oceans. It is calculated as the pressure difference between **Tahiti** (Pacific) and **Darwin** (Indian Ocean)."},{"type":"mnemonic","topic":"Difference Trick","trick":"El Nino = Bad for India | La Nina = Good for India","visual":"⚖️","explanation":"**El Nino (E - Evil):** Weakens monsoon.\n**La Nina (L - Lucky):** Strengthens monsoon."},{"type":"fact_card","title":"Indian Ocean Dipole (IOD)","facts":["Also known as the ''Indian Niño''.","It is the difference in sea surface temperature between the Arabian Sea and the Bay of Bengal.","A Positive (+ve) IOD can neutralize the bad effects of El Niño in India."],"icon":"🌊"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"What is the impact of ''El Niño'' on the Indian Monsoon?","options":["Increase in rainfall","Decrease in rainfall","No effect","Heavy drop in temperature"],"correct":"Decrease in rainfall","strategy":"El Niño diverts moisture away from the Indian subcontinent."},{"type":"pyq","exam":"MPPSC Mains GS-1","year":2021,"question":"What is ''El Niño''? Explain its impact on Indian agriculture. (5 marks)","answer":"El Niño is a warm ocean current. It makes the Indian monsoon erratic, causing droughts, crop failures, and affecting the rural economy.","strategy":"Mention the weakening of the Walker Cell for better marks in Mains."},{"type":"exam_pattern","topic":"Climate Trend","analysis":"Unit 3 Climate Trend:","stats":["Impact of El Niño: 1 question","Pressure Belts: 1 question","Monsoon Onset: 1 question"],"trend":"The Commission is now linking Jet Streams and IOD with ENSO in analytical questions."}]}', 'geography', NULL, 15, 1, 1770837068, 1771008862, 'blog', 'unit_3', 'Climate phenomena: El Nino, La Nina', 1, 0, 1, 1, 0, 'Unit 3: जलवायु घटनाएं - अल नीनो और ला नीना भारतीय मानसून एक जटिल प्रक्रिया है, जिसे प्रशांत महासागर में होने वाली हलचलें गहराई से प्रभावित करती हैं। इन घटनाओं को सामूहिक रूप से **ENSO (El Niño Souther...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('b68c4443-3ba2-49b3-a25a-beb03d6d8c9b', 'southern-oscillation-western-disturbances-unit-3', 'Southern Oscillation & Western Disturbances | दक्षिण दोलन और पश्चिमी विक्षोभ', 'Comprehensive study of atmospheric pressure changes (SO) and winter rain phenomena (Western Disturbances) for MPPSC Unit 3 Geography of India.', '{"hi":[{"type":"h2","text":"Unit 3: जलवायु के प्रमुख कारक - SO और WD"},{"type":"p","text":"भारतीय जलवायु को प्रभावित करने वाले दो बड़े कारक हैं: ''दक्षिण दोलन'' (जो मानसून की ताकत तय करता है) और ''पश्चिमी विक्षोभ'' (जो सर्दियों में उत्तर भारत में वर्षा लाता है)।"},{"type":"h2","text":"1. दक्षिण दोलन (Southern Oscillation - SO)"},{"type":"p","text":"यह प्रशांत महासागर (Pacific Ocean) और हिंद महासागर (Indian Ocean) के बीच वायुदाब (Pressure) में होने वाला क्रमिक परिवर्तन है। जब प्रशांत महासागर में दबाव कम होता है, तो हिंद महासागर में दबाव अधिक होता है, और इसके विपरीत। "},{"type":"fact_card","title":"SO सूचकांक (SOI)","facts":["इसे मापने के लिए **टाहिटी** (Tahiti - प्रशांत महासागर) और **डार्विन** (Darwin - ऑस्ट्रेलिया/हिंद महासागर) के दबाव का अंतर देखा जाता है।","यदि SOI धनात्मक (+ve) है, तो भारतीय मानसून **मजबूत** होगा।","यदि SOI ऋणात्मक (-ve) है, तो मानसून **कमजोर** होगा (अल नीनो का संकेत)।"],"icon":"🌡️"},{"type":"h2","text":"2. पश्चिमी विक्षोभ (Western Disturbance - WD)"},{"type":"p","text":"यह भूमध्य सागर (Mediterranean Sea) से उठने वाला एक ''शीतोष्ण चक्रवात'' (Temperate Cyclone) है, जो भारत के उत्तर-पश्चिम हिस्से में सर्दियों (दिसंबर-फरवरी) में वर्षा लाता है। "},{"type":"table","instruction":"पश्चिमी विक्षोभ के मुख्य तथ्य","head":["विशेषता","विवरण"],"body":[["उद्गम (Source)","भूमध्य सागर, कैस्पियन सागर।"],["लाने वाला कारक","पश्चिमी जेट स्ट्रीम (Western Jet Stream)।"],["भारत में प्रभाव","हिमालय में बर्फबारी और उत्तर भारत के मैदानों में वर्षा।"],["कृषि के लिए महत्व","रबी की फसल (विशेषकर **गेहूं**) के लिए ''अमृत'' के समान।"]]},{"type":"highlight","level":"important","text":"मावठ (Mawat): राजस्थान और उत्तर-पश्चिमी भारत में पश्चिमी विक्षोभ से होने वाली वर्षा को स्थानीय भाषा में ''मावठ'' कहते हैं।","icon":"🌾"},{"type":"h2","text":"3. जेट स्ट्रीम का प्रभाव"},{"type":"p","text":"क्षोभमंडल के ऊपरी हिस्से में तेज चलने वाली हवाओं (Jet Streams) का भारतीय मानसून में बड़ा रोल है। ''उप-ऊष्णकटिबंधीय पश्चिमी जेट'' सर्दियों में WD को भारत लाती है, जबकि ''पूर्वी जेट स्ट्रीम'' गर्मियों में मानसून को धक्का देती है। "},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"उत्तर-पश्चिमी भारत में शीतकालीन वर्षा (Winter Rain) का मुख्य कारण क्या है?","options":["उत्तर-पूर्वी मानसून","दक्षिण-पश्चिमी मानसून","पश्चिमी विक्षोभ","लौटता मानसून"],"correct":"पश्चिमी विक्षोभ","strategy":"सर्दियों में उत्तर भारत (पंजाब, हरियाणा, दिल्ली) में होने वाली बारिश भूमध्य सागर से आती है।"},{"type":"pyq","exam":"UPSC / Other PSC","year":2021,"question":"पश्चिमी विक्षोभ का उद्गम स्थान कहाँ है?","options":["कैस्पियन सागर","भूमध्य सागर","अरब सागर","बंगाल की खाड़ी"],"correct":"भूमध्य सागर","strategy":"Mediterranean Sea से नमी लेकर जेट स्ट्रीम इसे भारत लाती है।"},{"type":"exam_pattern","topic":"Climate Dynamics Trend","analysis":"Unit 3 Climate Trend:","stats":["वर्षा का प्रकार (मावठ/WD): 1 प्रश्न","जेट स्ट्रीम/SO: 1 प्रश्न","मानसून की उत्पत्ति: 1 प्रश्न"],"trend":"आयोग अब मानसून के ''ब्रेक'' (Break in Monsoon) और जेट स्ट्रीम के उत्तर-दक्षिण शिफ्ट होने पर गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 3: Key Climate Drivers - SO & WD"},{"type":"p","text":"Two major factors affecting Indian weather are: ''Southern Oscillation'' (decides the strength of monsoon) and ''Western Disturbances'' (brings winter rain to North India)."},{"type":"h2","text":"1. Southern Oscillation (SO)"},{"type":"p","text":"It is the periodic change in atmospheric pressure between the Pacific Ocean and the Indian Ocean. When pressure is low in the Pacific, it is high in the Indian Ocean, and vice versa. "},{"type":"fact_card","title":"SO Index (SOI)","facts":["Measured as the pressure difference between **Tahiti** (Pacific) and **Darwin** (Australia/Indian Ocean).","Positive (+ve) SOI = **Strong** Indian Monsoon.","Negative (-ve) SOI = **Weak** Indian Monsoon (linked to El Niño)."],"icon":"🌡️"},{"type":"h2","text":"2. Western Disturbance (WD)"},{"type":"p","text":"It is a ''Temperate Cyclone'' originating from the Mediterranean Sea that brings rainfall to North-Western India during winter (Dec-Feb)."},{"type":"table","instruction":"Key Facts on WD","head":["Feature","Description"],"body":[["Source","Mediterranean Sea, Caspian Sea."],["Carrying Agent","Sub-tropical Westerly Jet Stream."],["Impact in India","Snowfall in Himalayas, light rain in Northern Plains."],["Agricultural Value","Extremely beneficial for Rabi crops, especially **Wheat**."]]},{"type":"highlight","level":"important","text":"Mawat: The local term for winter rainfall caused by Western Disturbances in Rajasthan and NW India.","icon":"🌾"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"What is the primary cause of winter rainfall in North-Western India?","options":["North-East Monsoon","South-West Monsoon","Western Disturbance","Retreating Monsoon"],"correct":"Western Disturbance","strategy":"Winter rain in Punjab, Haryana, and Delhi originates from the Mediterranean Sea."},{"type":"pyq","exam":"UPSC / Other PSC","year":2021,"question":"Where does the Western Disturbance originate?","options":["Caspian Sea","Mediterranean Sea","Arabian Sea","Bay of Bengal"],"correct":"Mediterranean Sea","strategy":"Jet streams carry the moisture from the Mediterranean Sea towards India."}]}', 'geography', NULL, 14, 1, 1770837237, 1770837237, 'blog', 'unit_3', 'Southern Oscillation, Western Disturbance', 1, 0, 0, 1, 0, 'Unit 3: जलवायु के प्रमुख कारक - SO और WD भारतीय जलवायु को प्रभावित करने वाले दो बड़े कारक हैं: ''दक्षिण दोलन'' (जो मानसून की ताकत तय करता है) और ''पश्चिमी विक्षोभ'' (जो सर्दियों में उत्तर भारत में वर्षा ल...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('bd42279e-8f09-4822-8017-a4de6fbb7d96', 'consequences-climate-change-india-unit-3', 'Consequences of Climate Change in India | भारत में जलवायु परिवर्तन के परिणाम', 'Analysis of the environmental, social, and economic impacts of climate change in India. Covers Himalayan glacial melt, sea-level rise, and agricultural shifts for MPPSC Unit 3.', '{"hi":[{"type":"h2","text":"Unit 3: जलवायु परिवर्तन के परिणाम (Consequences of Climate Change)"},{"type":"p","text":"जलवायु परिवर्तन केवल एक पर्यावरणीय मुद्दा नहीं है, बल्कि यह भारत की खाद्य सुरक्षा, जल संसाधनों और तटीय सुरक्षा के लिए एक बड़ा खतरा है। MPPSC में इसके ''प्रभावों'' (Impacts) पर विश्लेषणात्मक प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. जल संसाधनों पर प्रभाव (Impact on Water Resources)"},{"type":"p","text":""},{"type":"ul","items":["**हिमालयी ग्लेशियरों का पिघलना:** गंगोत्री और यमुनोत्री जैसे ग्लेशियर तेजी से पीछे खिसक रहे हैं। इससे शुरू में नदियों में बाढ़ आएगी और बाद में ये नदियाँ सूख सकती हैं।","**पेयजल संकट:** भू-जल स्तर (Groundwater level) में गिरावट और जल चक्र में अनिश्चितता।"]},{"type":"h2","text":"2. कृषि और खाद्य सुरक्षा (Agriculture & Food Security)"},{"type":"p","text":"भारतीय कृषि सीधे तौर पर जलवायु पर निर्भर है। तापमान में $1^\\circ C$ की वृद्धि भी अनाज उत्पादन को प्रभावित कर सकती हैं।"},{"type":"table","instruction":"कृषि पर प्रभाव","head":["क्षेत्र","प्रभाव"],"body":[["फसल चक्र","मानसून की अनिश्चितता के कारण बुवाई के समय में बदलाव।"],["उत्पादन","अत्यधिक गर्मी (Heat waves) के कारण गेहूं और चावल की पैदावार में कमी।"],["कीट प्रकोप","तापमान बढ़ने से फसलों में नई बीमारियों और कीटों (जैसे टिड्डी दल) का हमला।"]]},{"type":"h2","text":"3. तटीय क्षेत्रों पर प्रभाव (Coastal Impact)"},{"type":"p","text":"समुद्र के जलस्तर में वृद्धि (Sea-level rise) भारत की 7516 किमी लंबी तटरेखा के लिए खतरा है। "},{"type":"highlight","level":"critical","text":"मुंबई, कोलकाता और चेन्नई जैसे महानगरों के डूबने का खतरा। सुंदरबन के मैंग्रोव वनों का विनाश और समुद्री जल का मीठे पानी के स्रोतों में मिलना (Salinity intrusion)।","icon":"🌊"},{"type":"h2","text":"4. जैव विविधता और स्वास्थ्य (Biodiversity & Health)"},{"type":"ul","items":["**प्रजातियों का विलोपन:** कई पौधों और जानवरों की प्रजातियां बदलते तापमान को सहन नहीं कर पा रही हैं।","**बीमारियों का प्रसार:** गर्मी बढ़ने से डेंगू, मलेरिया और हैजा जैसी संक्रामक बीमारियों के क्षेत्रों में विस्तार।"]},{"type":"fact_card","title":"भारत के प्रयास (Mitigation)","facts":["NAPCC (2008): जलवायु परिवर्तन पर राष्ट्रीय कार्य योजना (8 मिशन)।","ISA (International Solar Alliance): सौर ऊर्जा को बढ़ावा देने के लिए भारत की पहल।","Panchamrit: COP26 में भारत का 2070 तक ''Net Zero'' उत्सर्जन का लक्ष्य।"],"icon":"🍃"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Mains GS-1","year":2020,"question":"जलवायु परिवर्तन के भारतीय कृषि पर पड़ने वाले प्रभावों की विवेचना कीजिए। (11 marks)","answer":"उत्तर में मानसून की अनिश्चितता, हीट वेव का गेहूं पर प्रभाव, और फसल चक्र में बदलाव जैसे बिंदुओं को विस्तार से लिखें।","strategy":"मेंस में डेटा का प्रयोग करें (जैसे - IPCC की रिपोर्ट)।"},{"type":"pyq","exam":"MPPSC Prelims 2017","year":2017,"question":"जलवायु परिवर्तन पर भारत की प्रथम राष्ट्रीय कार्य योजना (NAPCC) कब जारी की गई थी?","options":["2000","2008","2012","2015"],"correct":"2008","strategy":"यह 8 राष्ट्रीय मिशनों का एक समूह है।"}],"en":[{"type":"h2","text":"Unit 3: Consequences of Climate Change"},{"type":"p","text":"Climate change is not just an environmental issue; it is a major threat to India''s food security, water resources, and coastal safety. MPPSC focuses on ''Analytical Impacts'' of these changes."},{"type":"h2","text":"1. Impact on Water Resources"},{"type":"p","text":""},{"type":"ul","items":["**Melting of Himalayan Glaciers:** Glaciers like Gangotri are retreating rapidly. This leads to initial flooding followed by long-term drying of perennial rivers.","**Water Scarcity:** Decline in groundwater levels and disruption of the hydrological cycle."]},{"type":"h2","text":"2. Agriculture & Food Security"},{"type":"p","text":"Indian agriculture is directly dependent on climate. A rise of $1^\\circ C$ in temperature can significantly impact grain yields."},{"type":"table","instruction":"Impact on Agriculture","head":["Sector","Impact"],"body":[["Crop Cycle","Shift in sowing dates due to monsoon unpredictability."],["Yield","Reduction in Wheat and Rice production due to intense Heat Waves."],["Pest Attacks","Increased frequency of pest attacks (like Locusts) due to warmer temperatures."]]},{"type":"h2","text":"3. Coastal and Marine Impact"},{"type":"p","text":""},{"type":"highlight","level":"critical","text":"Rising sea levels threaten India''s 7516 km coastline. Cities like Mumbai and Kolkata face flooding risks, and the Sundarbans mangroves are under threat of submergence.","icon":"🌊"},{"type":"fact_card","title":"National Action Plan on Climate Change (NAPCC)","facts":["Launched in **2008** with 8 core national missions.","Includes Solar Mission, Water Mission, and Sustaining the Himalayan Ecosystem.","India''s strategy to balance growth with environmental sustainability."],"icon":"🛡️"}]}', 'geography', NULL, 15, 1, 1770837274, 1770837274, 'blog', 'unit_3', 'Consequences of Climate Change', 1, 0, 0, 1, 0, 'Unit 3: जलवायु परिवर्तन के परिणाम (Consequences of Climate Change) जलवायु परिवर्तन केवल एक पर्यावरणीय मुद्दा नहीं है, बल्कि यह भारत की खाद्य सुरक्षा, जल संसाधनों और तटीय सुरक्षा के लिए एक बड़ा खतरा है...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('52d7a5bd-9451-4cb1-a098-a86a637297ea', 'natural-resources-india-unit-3-mppsc', 'Natural Resources of India: Forests, Minerals & Water | भारत के प्राकृतिक संसाधन', 'Comprehensive guide to India''s Forest cover, Mineral belts, and Water resources. Covers ISFR 2021 data, metallic/non-metallic minerals, and river basins for MPPSC Unit 3.', '{"hi":[{"type":"h2","text":"Unit 3: भारत के प्राकृतिक संसाधन (Natural Resources)"},{"type":"p","text":"भारत प्राकृतिक संसाधनों के मामले में एक समृद्ध देश है। MPPSC Unit 3 में वनों के प्रकार, खनिजों के वितरण (Distribution) और जल संसाधनों के प्रबंधन पर प्रश्न पूछे जाते हैं। हम इसे तीन मुख्य भागों में कवर करेंगे।"},{"type":"h2","text":"1. वन संसाधन (Forest Resources)"},{"type":"p","text":"भारत वन स्थिति रिपोर्ट (ISFR 2021) के अनुसार, भारत का कुल वन और वृक्ष आवरण **24.62%** है। मध्य प्रदेश क्षेत्रफल के हिसाब से सर्वाधिक वन वाला राज्य है। "},{"type":"table","instruction":"वनों के प्रकार और मुख्य वृक्ष","head":["वनों के प्रकार","वर्षा (Rainfall)","प्रमुख वृक्ष"],"body":[["उष्णकटिबंधीय सदाबहार (Evergreen)","> 200 cm","महोगनी, एबोनी, रोजवुड (अंडमान, प. घाट)।"],["उष्णकटिबंधीय पर्णपाती (Deciduous)","70 - 200 cm","**सागौन (Teak), साल (Sal)**, शीशम, चंदन। (भारत में सर्वाधिक)।"],["उष्णकटिबंधीय कंटीले (Thorny)","< 50 cm","बबूल, कैक्टस, खजूर (राजस्थान, म.प्र. के कुछ हिस्से)।"],["ज्वारीय/मैंग्रोव (Mangrove)","तटीय क्षेत्र","सुंदरी (सुंदरवन), कैसुरीना।"]]},{"type":"highlight","level":"important","text":"सर्वाधिक वन क्षेत्रफल (State-wise Area): 1. मध्य प्रदेश, 2. अरुणाचल प्रदेश, 3. छत्तीसगढ़।\nसर्वाधिक प्रतिशत (Percentage): मिजोरम (84.53%)।","icon":"🌳"},{"type":"h2","text":"2. खनिज संसाधन (Mineral Resources)"},{"type":"p","text":"भारत में खनिजों का वितरण ''प्रायद्वीपीय पठार'' (Peninsular Plateau) में केंद्रित है। "},{"type":"table","instruction":"प्रमुख खनिज और उनके केंद्र","head":["खनिज","प्रमुख उत्पादक राज्य","प्रसिद्ध खदानें (Mines)"],"body":[["लौह अयस्क (Iron Ore)","ओडिशा, छत्तीसगढ़","बादामपहाड़ (ओडिशा), बैलाडीला (छत्तीसगढ़)।"],["मैंगनीज (Manganese)","**मध्य प्रदेश**, महाराष्ट्र","भारवेली (बालाघाट, MP) - एशिया की सबसे बड़ी खदान।"],["तांबा (Copper)","**मध्य प्रदेश**, राजस्थान","मलंजखंड (बालाघाट, MP), खेतड़ी (राजस्थान)।"],["बॉक्साइट (Bauxite)","ओडिशा","पंचपटमाली (ओडिशा)।"],["कोयला (Coal)","ओडिशा, झारखंड, छत्तीसगढ़","झरिया (झारखंड), तालचेर (ओडिशा), सिंगरौली (MP)।"]]},{"type":"fact_card","title":"ऊर्जा खनिज (Energy Minerals)","facts":["थोरियम: केरल के समुद्री तट की ''मोनोजाइट'' रेत में विश्व का सबसे बड़ा भंडार।","पेट्रोलियम: डिगबोई (असम - सबसे पुरानी रिफाइनरी), बॉम्बे हाई (सर्वाधिक उत्पादन)।","यूरेनियम: जादुगुड़ा (झारखंड), तुम्मलपल्ले (आंध्र प्रदेश)।"],"icon":"⚡"},{"type":"h2","text":"3. जल संसाधन (Water Resources)"},{"type":"p","text":"भारत में विश्व की जनसंख्या का 17.5% हिस्सा है, लेकिन जल संसाधनों का केवल **4%** है।"},{"type":"ul","items":["**सतही जल (Surface Water):** गंगा, ब्रह्मपुत्र और सिंधु बेसिन में सर्वाधिक क्षमता।","**भू-जल (Ground Water):** पंजाब, हरियाणा और राजस्थान में इसका अत्यधिक दोहन (Over-exploitation) हो रहा।","**सिंचाई के साधन:** भारत में सर्वाधिक सिंचाई **कुओं और नलकूपों (Wells & Tubewells)** से होती है। "]},{"type":"highlight","level":"critical","text":"नदी जोड़ो परियोजना (Inter-linking of Rivers): ''अमृत क्रांति''।\nकेन-बेतवा लिंक: भारत की पहली नदी जोड़ो परियोजना (MP और UP)।","icon":"💧"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भारत के किस राज्य में सागौन (Teak) के वन सर्वाधिक पाए जाते हैं?","options":["झारखंड","मध्य प्रदेश","उत्तराखंड","कर्नाटक"],"correct":"मध्य प्रदेश","strategy":"सागौन और साल MP के प्रमुख वन वृक्ष हैं।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"मलांजखंड (Malanjkhand) किस खनिज उत्पादन के लिए प्रसिद्ध है?","options":["हीरा","तांबा","मैंगनीज","लौह अयस्क"],"correct":"तांबा","strategy":"यह बालाघाट जिले में स्थित एशिया की सबसे बड़ी खुली तांबा खदान है।"}],"en":[{"type":"h2","text":"Unit 3: Natural Resources of India"},{"type":"p","text":"India is blessed with diverse natural resources. In MPPSC Unit 3, questions are focused on Forest types, Mineral distribution, and Water management."},{"type":"h2","text":"1. Forest Resources"},{"type":"p","text":"As per ISFR 2021, India''s total forest and tree cover is **24.62%**. "},{"type":"table","instruction":"Forest Types & Species","head":["Type of Forest","Rainfall","Major Species"],"body":[["Tropical Evergreen","> 200 cm","Mahogany, Ebony, Rosewood (Western Ghats, Andaman)."],["Tropical Deciduous","70 - 200 cm","**Teak, Sal**, Sheesham. (Most dominant in India)."],["Arid/Thorny Forests","< 50 cm","Acacia (Babool), Cactus (Rajasthan, MP)."],["Mangrove Forests","Coastal Areas","Sundari, Casuarina."]]},{"type":"h2","text":"2. Mineral Resources"},{"type":"p","text":"Most minerals are concentrated in the ancient crystalline rocks of the Peninsular Plateau. "},{"type":"table","instruction":"Key Minerals & Hubs","head":["Mineral","Lead Producer State","Famous Mines"],"body":[["Iron Ore","Odisha, Chhattisgarh","Badampahar (Odisha), Bailadila (Chhattisgarh)."],["Manganese","Madhya Pradesh","Bharveli (Balaghat, MP) - Asia''s largest underground mine."],["Copper","Madhya Pradesh","Malanjkhand (Balaghat, MP), Khetri (Rajasthan)."],["Coal","Odisha, Jharkhand","Jharia (Jharkhand), Talcher (Odisha), Singrauli (MP)."]]},{"type":"h2","text":"3. Water Resources"},{"type":"ul","items":["**Surface Water:** Highest potential in Ganga and Brahmaputra basins.","**Ground Water:** Over-exploited in Punjab, Haryana, and Rajasthan.","**Irrigation:** Wells and Tubewells are the dominant source of irrigation in India (~60%)."]},{"type":"exam_pattern","topic":"Resources Trend","analysis":"Unit 3 Resources Trend:","stats":["Minerals and their Mines: 2 questions","Forest Survey (ISFR) data: 1 question","Irrigation/River Projects: 1 question"],"trend":"The Commission is now focusing on the distinction between ''Reserves'' and ''Production'' and precise locations of mining areas."}]}', 'geography', NULL, 22, 1, 1770837335, 1770837335, 'blog', 'unit_3', 'Natural Resources: Forest, Minerals, Water Resources', 1, 0, 0, 1, 0, 'Unit 3: भारत के प्राकृतिक संसाधन (Natural Resources) भारत प्राकृतिक संसाधनों के मामले में एक समृद्ध देश है। MPPSC Unit 3 में वनों के प्रकार, खनिजों के वितरण (Distribution) और जल संसाधनों के प्रबंधन पर...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('ffa3294c-aa54-4b15-9efb-2c5e7f7fe69f', 'agriculture-india-green-revolution-unit-3-mppsc', 'Agriculture in India: Crops, Green Revolution & Food Security | भारत में कृषि और खाद्य सुरक्षा', 'Comprehensive guide to Indian Agriculture for MPPSC Unit 3. Covers Kharif/Rabi crops, Green Revolution 1.0 vs 2.0, Food Security, and Sustainable Farming strategies.', '{"hi":[{"type":"h2","text":"Unit 3: भारतीय कृषि - फसलें, क्रांति और सुरक्षा"},{"type":"p","text":"भारत एक कृषि प्रधान देश है जहाँ की लगभग 50% जनसंख्या प्रत्यक्ष रूप से कृषि पर निर्भर है। MPPSC में फसलों के प्रकार, हरित क्रांति के प्रभाव और वर्तमान ''द्वितीय हरित क्रांति'' की रणनीतियों से प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. भारत की प्रमुख फसलें (Major Crops)"},{"type":"p","text":"भारत में तीन प्रमुख फसल ऋतुएं होती हैं: खरीफ, रबी और जायद। "},{"type":"table","instruction":"फसल ऋतुएं और उदाहरण","head":["ऋतु (Season)","समय (Period)","प्रमुख फसलें"],"body":[["खरीफ (Kharif)","जून-जुलाई (बुवाई) -> अक्टू-नव (कटाई)","चावल, मक्का, ज्वार, बाजरा, कपास, सोयाबीन।"],["रबी (Rabi)","अक्टू-नव (बुवाई) -> मार्च-अप्रैल (कटाई)","गेहूं, जौ, चना, सरसों, मटर।"],["जायद (Zaid)","मार्च -> जून (गर्मियों में)","तरबूज, खरबूजा, ककड़ी, चारा फसलें।"]]},{"type":"highlight","level":"important","text":"चावल: भारत की मुख्य खाद्य फसल। (सर्वाधिक उत्पादक: प. बंगाल)।\nगेहूं: दूसरी मुख्य फसल। (सर्वाधिक उत्पादक: उत्तर प्रदेश; प्रति हेक्टेयर: पंजाब)।","icon":"🌾"},{"type":"h2","text":"2. हरित क्रांति (Green Revolution - 1.0)"},{"type":"p","text":"1960 के दशक के मध्य (1966-67) में शुरू हुई इस क्रांति ने भारत को खाद्यान्न में आत्मनिर्भर बनाया। "},{"type":"ul","items":["**जनक:** एम.एस. स्वामीनाथन (भारत में), नॉर्मन बोरलॉग (विश्व में)।","**मुख्य तत्व:** HYV बीज (High Yielding Variety), रासायनिक उर्वरक, सिंचाई का विस्तार और कीटनाशक।","**प्रभाव:** गेहूं और चावल के उत्पादन में भारी वृद्धि। पंजाब, हरियाणा और पश्चिमी UP को सर्वाधिक लाभ।"]},{"type":"h2","text":"3. द्वितीय हरित क्रांति की रणनीतियाँ (Second Green Revolution)"},{"type":"p","text":"प्रथम हरित क्रांति के नकारात्मक प्रभावों (मिट्टी की उर्वरता में कमी, जल स्तर गिरना) को दूर करने के लिए ''द्वितीय हरित क्रांति'' की आवश्यकता है।"},{"type":"fact_card","title":"प्रमुख रणनीतियाँ","facts":["सतत कृषि (Sustainable Agriculture): जैविक खेती और जीरो बजट नेचुरल फार्मिंग (ZBNF) पर जोर।","फसल विविधीकरण (Crop Diversification): केवल गेहूं-चावल नहीं, बल्कि दालों और तिलहन पर ध्यान।","पूर्वी भारत पर ध्यान: बिहार, ओडिशा और प. बंगाल में उत्पादकता बढ़ाना।","प्रौद्योगिकी: सूक्ष्म सिंचाई (Drop per crop), नैनो यूरिया और डिजिटल कृषि का उपयोग।"],"icon":"🚜"},{"type":"h2","text":"4. खाद्य सुरक्षा (Food Security)"},{"type":"p","text":"खाद्य सुरक्षा का अर्थ है: सभी लोगों को हर समय पोषणयुक्त भोजन की उपलब्धता (Availability), पहुँच (Accessibility) और सामर्थ्य (Affordability)। "},{"type":"highlight","level":"critical","text":"राष्ट्रीय खाद्य सुरक्षा अधिनियम (NFSA), 2013: इसके तहत 67% जनसंख्या (75% ग्रामीण, 50% शहरी) को रियायती दर पर अनाज का कानूनी अधिकार दिया गया है।","icon":"🍛"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भारत में ''हरित क्रांति'' के जनक कौन माने जाते हैं?","options":["वी. कुरियन","एम.एस. स्वामीनाथन","बी.पी. पाल","के.एन. बहल"],"correct":"एम.एस. स्वामीनाथन","strategy":"कुरियन श्वेत क्रांति (Milk) के हैं, स्वामीनाथन हरित क्रांति (Agriculture) के।"},{"type":"pyq","exam":"MPPSC Mains GS-1","year":2020,"question":"खाद्य सुरक्षा से आप क्या समझते हैं? इसके प्रमुख स्तंभों का वर्णन कीजिए। (11 marks)","answer":"उत्तर में उपलब्धता, पहुँच और सामर्थ्य (3 As) को विस्तार से समझाएं और NFSA 2013 का उल्लेख करें।","strategy":"मेंस में बफर स्टॉक और PDS प्रणाली का डायग्राम भी बनाएं।"},{"type":"exam_pattern","topic":"Agriculture Trend","analysis":"Unit 3 Agriculture Trend:","stats":["फसल उत्पादन डेटा (Latest): 1 प्रश्न","कृषि क्रांति (Yellow/Blue/Grey): 1 प्रश्न","सरकारी योजनाएं (PM-KISAN/Fasal Bima): 1 प्रश्न"],"trend":"आयोग अब ''सस्टेनेबल एग्रीकल्चर'' (जैसे - श्री अन्न/मिलेट्स) और जलवायु स्मार्ट कृषि पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 3: Indian Agriculture - Crops, Revolution & Security"},{"type":"p","text":"India is an agrarian economy where nearly 50% of the population relies on agriculture. MPPSC Unit 3 covers crop types, impacts of the Green Revolution, and strategies for the ''Second Green Revolution''."},{"type":"h2","text":"1. Major Crops of India"},{"type":"table","instruction":"Cropping Seasons","head":["Season","Period","Major Crops"],"body":[["Kharif","June-July (Sowing) -> Oct-Nov (Harvesting)","Rice, Maize, Jowar, Bajra, Cotton, Soybean."],["Rabi","Oct-Nov (Sowing) -> March-April (Harvesting)","Wheat, Barley, Gram, Mustard, Peas."],["Zaid","March -> June (Summer)","Watermelon, Cucumber, Fodder crops."]]},{"type":"highlight","level":"important","text":"Rice: Leading food crop. (Top producer: West Bengal).\nWheat: Second major crop. (Top producer: Uttar Pradesh; Per hectare: Punjab).","icon":"🌾"},{"type":"h2","text":"2. Green Revolution (1.0)"},{"type":"ul","items":["**Father:** M.S. Swaminathan (India), Norman Borlaug (World).","**Components:** HYV Seeds, Chemical Fertilizers, Irrigation, and Pesticides. ","**Impact:** Achieved self-sufficiency in food grains. Benefitted Punjab, Haryana, and West UP significantly."]},{"type":"h2","text":"3. Strategies for the Second Green Revolution"},{"type":"p","text":"To counter the environmental damage of the first phase (soil degradation, falling water tables), a sustainable second phase is needed. "},{"type":"fact_card","title":"Key Strategies","facts":["Sustainable Agriculture: Focus on Organic farming and Zero Budget Natural Farming (ZBNF).","Crop Diversification: Shifting focus from Wheat-Rice to Pulses and Oilseeds.","Focus on Eastern India: Bringing the revolution to Bihar, Odisha, and West Bengal.","Digital Agriculture: Use of Drones, Nano Urea, and Precision Farming."],"icon":"🚜"},{"type":"h2","text":"4. Food Security"},{"type":"highlight","level":"critical","text":"National Food Security Act (NFSA), 2013: Legally guarantees subsidized food grains to 67% of the population.","icon":"🍛"},{"type":"exam_pattern","topic":"Agriculture Trend","analysis":"Unit 3 Agriculture Trend:","stats":["Crop Production Data: 1 question","Agri-Revolutions: 1 question","Govt Schemes (PM-KISAN): 1 question"],"trend":"Emphasis is shifting towards ''Shree Anna'' (Millets) and Climate-Smart Agriculture."}]}', 'geography', NULL, 25, 1, 1770837420, 1770837420, 'blog', 'unit_3', 'Major Crops, Food Security, Green Revolution, Strategies for the Second Green Revolution', 1, 0, 0, 1, 0, 'Unit 3: भारतीय कृषि - फसलें, क्रांति और सुरक्षा भारत एक कृषि प्रधान देश है जहाँ की लगभग 50% जनसंख्या प्रत्यक्ष रूप से कृषि पर निर्भर है। MPPSC में फसलों के प्रकार, हरित क्रांति के प्रभाव और वर्तमान ''द...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('299de2d6-9d10-4794-9c06-fe45e4492530', 'energy-resources-india-unit-3-mppsc', 'Energy Resources of India: Conventional & Non-Conventional | भारत के ऊर्जा संसाधन', 'Comprehensive guide to India''s energy sector. Covers Thermal, Hydro, Nuclear power (Conventional) and Solar, Wind, Biomass (Non-conventional) for MPPSC Unit 3.', '{"hi":[{"type":"h2","text":"Unit 3: ऊर्जा संसाधन - पारंपरिक और गैर-पारंपरिक"},{"type":"p","text":"भारत की बढ़ती अर्थव्यवस्था के लिए ऊर्जा की मांग निरंतर बढ़ रही है। ऊर्जा संसाधनों को उनकी प्रकृति और उपयोग के आधार पर दो भागों में बांटा गया है। MPPSC में परमाणु ऊर्जा केंद्रों और सौर ऊर्जा परियोजनाओं (जैसे रीवा सोलर प्लांट) पर विशेष ध्यान दिया जाता है।"},{"type":"p","text":""},{"type":"h2","text":"1. पारंपरिक ऊर्जा स्रोत (Conventional Sources)"},{"type":"p","text":"ये वे स्रोत हैं जो लंबे समय से उपयोग किए जा रहे हैं और इनके भंडार सीमित (समाप्य) हैं।"},{"type":"table","instruction":"पारंपरिक ऊर्जा के प्रकार","head":["स्रोत","प्रमुख केंद्र/तथ्य","विशेषता"],"body":[["तापीय ऊर्जा (Thermal)","सिंगरौली (MP), कोरबा (CG), तलचर (ओडिशा)।","भारत की कुल बिजली का 60% से अधिक हिस्सा कोयले से आता है।"],["जल विद्युत (Hydro)","भाखड़ा नांगल, टिहरी, नर्मदा सागर।","प्रदूषण रहित लेकिन बड़े बांधों से विस्थापन की समस्या।"],["परमाणु ऊर्जा (Nuclear)","तारापुर, रावतभाटा, कुडनकुलम।","यूरेनियम और थोरियम का उपयोग।"]]},{"type":"highlight","level":"critical","text":"परमाणु ऊर्जा केंद्र (Matching के लिए महत्वपूर्ण):\n1. तारापुर - महाराष्ट्र (पहला)\n2. रावतभाटा - राजस्थान\n3. कलपक्कम/कुडनकुलम - तमिलनाडु\n4. नरोरा - उत्तर प्रदेश\n5. कैगा - कर्नाटक\n6. काकरापार - गुजरात","icon":"⚛️"},{"type":"p","text":""},{"type":"h2","text":"2. गैर-पारंपरिक ऊर्जा स्रोत (Non-Conventional/Renewable)"},{"type":"p","text":"ये अक्षय (Renewable) स्रोत हैं जो पर्यावरण के अनुकूल हैं। भारत ने 2030 तक 500 GW गैर-जीवाश्म ऊर्जा का लक्ष्य रखा है।"},{"type":"ul","items":["**सौर ऊर्जा (Solar Energy):** भारत में सौर ऊर्जा की अपार संभावनाएं हैं। (रीवा अल्ट्रा मेगा सोलर प्लांट - 750 MW प्रसिद्ध है)।","**पवन ऊर्जा (Wind Energy):** सर्वाधिक क्षमता - तमिलनाडु, गुजरात और महाराष्ट्र।","**बायोमास/बायोगास:** कृषि प्रधान देशों के लिए ग्रामीण क्षेत्रों में सर्वोत्तम।","**भू-तापीय ऊर्जा (Geothermal):** पूगा घाटी (लद्दाख), तातापानी (छत्तीसगढ़)।"]},{"type":"fact_card","title":"नवीनतम पहल (Initiatives)","facts":["अंतर्राष्ट्रीय सौर गठबंधन (ISA): मुख्यालय - गुरुग्राम (हरियाणा)।","PM-KUSUM योजना: किसानों को सौर पंप लगाने के लिए सहायता।","ग्रीन हाइड्रोजन मिशन: भारत को हाइड्रोजन का वैश्विक हब बनाना।"],"icon":"🌱"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश के किस जिले में ''रीवा अल्ट्रा मेगा सोलर प्रोजेक्ट'' स्थित है?","options":["रीवा","शहडोल","सतना","सीधी"],"correct":"रीवा","strategy":"यह एशिया के सबसे बड़े सिंगल साइट सौर संयंत्रों में से एक है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"भारत का सबसे पुराना परमाणु ऊर्जा केंद्र कौन सा है?","options":["नरोरा","तारापुर","कलपक्कम","कैगा"],"correct":"तारापुर","strategy":"तारापुर (1969) अमेरिका के सहयोग से स्थापित पहला केंद्र था।"},{"type":"exam_pattern","topic":"Energy Trend","analysis":"Unit 3 Energy Trend:","stats":["परमाणु ऊर्जा केंद्र (Location): 1 प्रश्न","नवीकरणीय ऊर्जा लक्ष्य (Targets): 1 प्रश्न","MP की ऊर्जा परियोजनाएं: 1 प्रश्न"],"trend":"आयोग अब ''ग्रीन हाइड्रोजन'' और ''फ्लोटिंग सोलर प्लांट'' (जैसे ओंकारेश्वर में प्रस्तावित) पर गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 3: Energy Resources - Conventional & Non-Conventional"},{"type":"p","text":"Energy demand is surging with India''s growth. Resources are categorized into Traditional (Finite) and Renewable (Sustainable). "},{"type":"h2","text":"1. Conventional Energy Sources"},{"type":"table","instruction":"Conventional Energy Types","head":["Source","Major Hubs/Facts","Key Feature"],"body":[["Thermal","Singrauli (MP), Korba (CG).","Over 60% of India''s power comes from Coal."],["Hydro","Bhakra Nangal, Tehri.","Pollution-free but involves displacement issues."],["Nuclear","Tarapur, Rawatbhata.","Uses Uranium and Thorium."]]},{"type":"highlight","level":"critical","text":"Nuclear Power Plants (Crucial for Matching):\n1. Tarapur - Maharashtra (1st)\n2. Rawatbhata - Rajasthan\n3. Kudankulam - Tamil Nadu\n4. Narora - Uttar Pradesh","icon":"⚛️"},{"type":"h2","text":"2. Non-Conventional Energy Sources"},{"type":"p","text":""},{"type":"ul","items":["**Solar Energy:** High potential in India. (Rewa Ultra Mega Solar - 750 MW is a key landmark).","**Wind Energy:** Highest capacity in Tamil Nadu and Gujarat.","**Geothermal:** Puga Valley (Ladakh), Tatapani (Chhattisgarh).","**Biomass:** Crucial for rural energy self-sufficiency."]},{"type":"exam_pattern","topic":"Energy Trend","analysis":"Unit 3 Energy Trend:","stats":["Nuclear Power Plants: 1 question","Renewable Energy Targets: 1 question","MP specific projects: 1 question"],"trend":"The Commission is now focusing on ''Green Hydrogen'' and ''Floating Solar Plants'' (e.g., Omkareshwar)."}]}', 'geography', NULL, 20, 1, 1770837459, 1770837459, 'blog', 'unit_3', 'Conventional and Non-Conventional sources of energy', 1, 0, 0, 1, 0, 'Unit 3: ऊर्जा संसाधन - पारंपरिक और गैर-पारंपरिक भारत की बढ़ती अर्थव्यवस्था के लिए ऊर्जा की मांग निरंतर बढ़ रही है। ऊर्जा संसाधनों को उनकी प्रकृति और उपयोग के आधार पर दो भागों में बांटा गया है। MPPSC म...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('6a722fba-df87-48a4-b277-32307212cb59', 'natural-hazards-disasters-cyclones-india-unit-3', 'Natural Hazards & Major Cyclones in India | भारत में प्राकृतिक आपदाएं और चक्रवात', 'Comprehensive guide to India''s natural disasters for MPPSC Unit 3. Detailed analysis of Earthquakes, Floods, Droughts, and major Cyclones affecting the Indian coastline.', '{"hi":[{"type":"h2","text":"Unit 3: भारत में प्राकृतिक आपदाएं और चक्रवात"},{"type":"p","text":"भारत अपनी अनूठी भौगोलिक स्थिति के कारण विभिन्न प्राकृतिक आपदाओं के प्रति संवेदनशील है। MPPSC Unit 3 में भूकंपीय क्षेत्रों (Seismic Zones), सूखा-बाढ़ क्षेत्रों और हाल ही में आए चक्रवातों (Cyclones) के नामकरण पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. भारत में प्रमुख प्राकृतिक आपदाएं (Major Hazards)"},{"type":"h3","text":"भूकंप (Earthquake)"},{"type":"p","text":"भारत को 4 भूकंपीय क्षेत्रों (Zones) में बांटा गया है (Zone II, III, IV, और V)। "},{"type":"ul","items":["**Zone V (अत्यधिक जोखिम):** हिमालय क्षेत्र, पूर्वोत्तर भारत, कच्छ का रण (गुजरात), और अंडमान निकोबार।","**Zone II (न्यूनतम जोखिम):** दक्षिण भारत का अधिकांश हिस्सा।"]},{"type":"h3","text":"बाढ़ और सूखा (Floods & Droughts)"},{"type":"ul","items":["**बाढ़:** गंगा-ब्रह्मपुत्र बेसिन (बिहार, असम) और ओडिशा के तटीय क्षेत्र सर्वाधिक प्रभावित।","**सूखा:** राजस्थान, गुजरात, और प्रायद्वीपीय पठार का ''वृष्टि छाया क्षेत्र'' (Rain shadow region - जैसे मराठवाड़ा)।"]},{"type":"h2","text":"2. भारत के प्रमुख चक्रवात (Major Cyclones)"},{"type":"p","text":"भारत की लंबी तटरेखा (7516 किमी) उष्णकटिबंधीय चक्रवातों (Tropical Cyclones) के प्रति संवेदनशील है। बंगाल की खाड़ी में अरब सागर की तुलना में अधिक चक्रवात आते हैं। "},{"type":"table","instruction":"हाल के प्रमुख चक्रवात और प्रभावित क्षेत्र","head":["चक्रवात का नाम","वर्ष","प्रभावित क्षेत्र","नामकरण करने वाला देश"],"body":[["बिपारजॉय (Biparjoy)","2023","गुजरात, राजस्थान","बांग्लादेश"],["मोचा (Mocha)","2023","म्यांमार, बंगाल की खाड़ी","यमन"],["ताउते (Tauktae)","2021","गुजरात, महाराष्ट्र","म्यांमार"],["अम्फान (Amphan)","2020","पश्चिम बंगाल, ओडिशा","थाईलैंड"],["फणि (Fani)","2019","ओडिशा","बांग्लादेश"]]},{"type":"highlight","level":"critical","text":"चक्रवात आने का समय: मुख्य रूप से लौटते मानसून (अक्टूबर-नवंबर) और मानसून से पहले (मई-जून) के दौरान।","icon":"🌀"},{"type":"h2","text":"3. आपदा प्रबंधन (Disaster Management)"},{"type":"fact_card","title":"संस्थान और पहल","facts":["NDMA (National Disaster Management Authority): स्थापना 2005 (अध्यक्ष: प्रधानमंत्री)।","SDMA (State Level): अध्यक्ष मुख्यमंत्री होते हैं।","IMD (India Meteorological Department): चक्रवातों की चेतावनी जारी करने वाली संस्था।"],"icon":"🛡️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"भारत के कितने भूकंपीय जोखिम अंचलों (Seismic Zones) में विभाजित किया गया है?","options":["3","4","5","6"],"correct":"4","strategy":"Zone I अब अस्तित्व में नहीं है, गिनती II से V तक होती है।"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"''बिपारजॉय'' चक्रवात का नाम किस देश ने दिया था?","options":["भारत","बांग्लादेश","ओमान","पाकिस्तान"],"correct":"बांग्लादेश","strategy":"बिपारजॉय का अर्थ बंगाली में ''आपदा'' होता है।"}],"en":[{"type":"h2","text":"Unit 3: Natural Hazards and Cyclones in India"},{"type":"p","text":"Due to its diverse geography, India is prone to various natural disasters. MPPSC Unit 3 covers Seismic Zones, drought-flood prone areas, and recent Cyclone naming conventions."},{"type":"h2","text":"1. Major Natural Hazards"},{"type":"h3","text":"Earthquakes"},{"type":"p","text":""},{"type":"ul","items":["**Zone V (Very High Risk):** Himalayas, North-East, Rann of Kutch, Andaman & Nicobar.","**Zone II (Low Risk):** Most of the Deccan Plateau."]},{"type":"h2","text":"2. Major Cyclones in India"},{"type":"table","instruction":"Recent Major Cyclones","head":["Name","Year","Affected Region","Naming Country"],"body":[["Biparjoy","2023","Gujarat, Rajasthan","Bangladesh"],["Mocha","2023","Myanmar, Bay of Bengal","Yemen"],["Tauktae","2021","Gujarat, Maharashtra","Myanmar"],["Amphan","2020","West Bengal, Odisha","Thailand"]]},{"type":"highlight","level":"critical","text":"Cyclone Frequency: Bay of Bengal records more cyclones than the Arabian Sea due to higher sea surface temperatures.","icon":"🌀"},{"type":"exam_pattern","topic":"Hazards Trend","analysis":"Unit 3 Hazards Trend:","stats":["Cyclone Naming: 1 question","Seismic Zones: 1 question","Disaster Management (NDMA): 1 question"],"trend":"Questions are shifting towards the origin of cyclone names and specific disaster mitigation strategies."}]}', 'geography', NULL, 18, 1, 1770837568, 1770837568, 'blog', 'unit_3', 'Natural hazards and disasters in India, Major cyclones in India', 1, 0, 0, 1, 0, 'Unit 3: भारत में प्राकृतिक आपदाएं और चक्रवात भारत अपनी अनूठी भौगोलिक स्थिति के कारण विभिन्न प्राकृतिक आपदाओं के प्रति संवेदनशील है। MPPSC Unit 3 में भूकंपीय क्षेत्रों (Seismic Zones), सूखा-बाढ़ क्षेत्...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('6f056b50-7ace-4390-972f-4591d2a173c7', 'population-dynamics-migration-unit-3-mppsc', 'Population Dynamics: Growth, Density & Migration | भारत की जनसंख्या', 'Comprehensive guide to India''s Demography for MPPSC Unit 3. Covers Census 2011 data, population growth, density, and rural-urban migration patterns.', '{"hi":[{"type":"h2","text":"Unit 3: भारत की जनसंख्या - वृद्धि, वितरण और घनत्व"},{"type":"p","text":"जनसांख्यिकी (Demography) किसी भी देश के विकास का दर्पण होती है। MPPSC Unit 3 में **2011 की जनगणना (Census 2011)** के आंकड़ों से 2-3 प्रश्न सीधे पूछे जाते हैं। इसमें जनसंख्या घनत्व, लिंगानुपात और ग्रामीण-शहरी प्रवास (Migration) प्रमुख हैं।"},{"type":"h2","text":"1. जनसंख्या वृद्धि और वितरण (Growth & Distribution)"},{"type":"p","text":"भारत की कुल जनसंख्या 2011 में **121.08 करोड़** थी। दशकीय वृद्धि दर (Decadal Growth Rate) **17.7%** रही। "},{"type":"table","instruction":"जनसंख्या वितरण: शीर्ष 3 राज्य","head":["रैंक","राज्य (सर्वाधिक जनसंख्या)","राज्य (न्यूनतम जनसंख्या)"],"body":[["1","उत्तर प्रदेश (19.9 करोड़)","सिक्किम (6.1 लाख)"],["2","महाराष्ट्र","मिजोरम"],["3","बिहार","अरुणाचल प्रदेश"]]},{"type":"highlight","level":"important","text":"महाविभाजन वर्ष (Year of Great Divide): 1921। इस वर्ष भारत की जनसंख्या वृद्धि दर ऋणात्मक (-0.31%) रही थी।","icon":"📈"},{"type":"h2","text":"2. जनसंख्या घनत्व (Population Density)"},{"type":"p","text":"भारत का औसत जनसंख्या घनत्व **382 व्यक्ति प्रति वर्ग किमी** है। "},{"type":"ul","items":["**सर्वाधिक घनत्व:** बिहार (1106), पश्चिम बंगाल (1028)।","**न्यूनतम घनत्व:** अरुणाचल प्रदेश (17)।","**केंद्र शासित प्रदेश:** दिल्ली (सर्वाधिक), अंडमान निकोबार (न्यूनतम)।"]},{"type":"h2","text":"3. ग्रामीण-शहरी प्रवास (Rural-Urban Migration)"},{"type":"p","text":"प्रवास वह प्रक्रिया है जिसमें लोग बेहतर अवसरों की तलाश में एक स्थान से दूसरे स्थान पर जाते हैं। "},{"type":"fact_card","title":"प्रवास के कारक (Factors)","facts":["Push Factors (अपकर्ष कारक): गाँव में बेरोजगारी, गरीबी, कृषि का पिछड़ापन और सुविधाओं का अभाव।","Pull Factors (अभिकर्ष कारक): शहरों में रोजगार के अवसर, बेहतर शिक्षा, स्वास्थ्य सुविधाएं और आधुनिक जीवनशैली।","सामाजिक कारण: महिलाओं के मामले में ''विवाह'' प्रवास का सबसे बड़ा कारण है।"],"icon":"🏙️"},{"type":"h2","text":"4. प्रमुख जनसांख्यिकीय आंकड़े (Quick Glance)"},{"type":"table","instruction":"लिंगानुपात और साक्षरता","head":["पैमाना (Indicator)","भारत (औसत)","शीर्ष राज्य","न्यूनतम राज्य"],"body":[["लिंगानुपात (Sex Ratio)","943","केरल (1084)","हरियाणा (879)"],["साक्षरता (Literacy)","73.0%","केरल (94%)","बिहार (61.8%)"],["शहरी जनसंख्या %","31.16%","गोवा (62.2%)","हिमाचल प्रदेश (10%)"]]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"2011 की जनगणना के अनुसार, भारत का जनसंख्या घनत्व कितना है?","options":["324","382","415","362"],"correct":"382","strategy":"यह 2001 में 324 था, जो 2011 में बढ़कर 382 हो गया।"},{"type":"exam_pattern","topic":"Demography Trend","analysis":"Unit 3 Population Analysis:","stats":["2011 जनगणना आंकड़े: 2 प्रश्न","प्रवास और शहरीकरण: 1 प्रश्न","लिंगानुपात/साक्षरता: 1 प्रश्न"],"trend":"आयोग अब सीधे आंकड़ों के बजाय ''राज्यों के क्रम'' (Ascending/Descending Order) पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 3: Population of India - Growth, Distribution & Density"},{"type":"p","text":"Demography reflects a nation''s development. In MPPSC Unit 3, 2-3 questions are directly asked from the **2011 Census**."},{"type":"h2","text":"1. Population Growth and Distribution"},{"type":"p","text":"Total population in 2011 was **121.08 crore**. The Decadal Growth Rate was **17.7%**. "},{"type":"table","instruction":"Population Distribution: Top 3 States","head":["Rank","State (Highest Population)","State (Lowest Population)"],"body":[["1","Uttar Pradesh","Sikkim"],["2","Maharashtra","Mizoram"],["3","Bihar","Arunachal Pradesh"]]},{"type":"highlight","level":"important","text":"Year of Great Divide: 1921. It was the only year in India''s history when the growth rate was negative (-0.31%).","icon":"📈"},{"type":"h2","text":"2. Population Density"},{"type":"p","text":"India''s average density is **382 persons per sq. km**. "},{"type":"ul","items":["**Highest Density:** Bihar (1106), West Bengal (1028).","**Lowest Density:** Arunachal Pradesh (17).","**UTs:** Delhi (Highest), Andaman & Nicobar (Lowest)."]},{"type":"h2","text":"3. Rural-Urban Migration"},{"type":"fact_card","title":"Migration Factors","facts":["Push Factors: Unemployment, poverty, and lack of facilities in villages.","Pull Factors: Employment opportunities, better education, and health facilities in cities.","Social Reason: Marriage is the primary cause for female migration in India."],"icon":"🏙️"}]}', 'geography', NULL, 20, 1, 1770837664, 1770837664, 'blog', 'unit_3', 'Population growth, distribution and Density, Rural-Urban Migration', 1, 0, 0, 1, 0, 'Unit 3: भारत की जनसंख्या - वृद्धि, वितरण और घनत्व जनसांख्यिकी (Demography) किसी भी देश के विकास का दर्पण होती है। MPPSC Unit 3 में **2011 की जनगणना (Census 2011)** के आंकड़ों से 2-3 प्रश्न सीधे पूछे ज...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('626f77f6-d03c-4ae2-a1a5-e17176a1cfa5', 'forest-produce-madhya-pradesh-unit-4-mppsc', 'Forest and Forest Produce of Madhya Pradesh | म.प्र. के वन और वनोपज', 'Comprehensive guide to MP''s Forest resources for Unit 4. Covers ISFR 2021 data, classification of forests (Teak, Sal), and Major/Minor forest produce like Tendu Patta and Harra.', '{"hi":[{"type":"h2","text":"Unit 4: मध्य प्रदेश के वन और वनोपज (Forest Resources)"},{"type":"p","text":"मध्य प्रदेश क्षेत्रफल की दृष्टि से भारत का सर्वाधिक वनाच्छादित राज्य है। ''इंडिया स्टेट ऑफ फॉरेस्ट रिपोर्ट (ISFR) 2021'' के अनुसार, राज्य का कुल वन क्षेत्र **77,493 वर्ग किमी** है। "},{"type":"h2","text":"1. वनों का वर्गीकरण (Classification of Forests)"},{"type":"table","instruction":"प्रशासनिक वर्गीकरण (Administrative)","head":["श्रेणी","प्रतिशत (%)","विशेषता"],"body":[["आरक्षित वन (Reserved)","65.36%","पूर्णतः सरकारी नियंत्रण, कटाई और चराई प्रतिबंधित।"],["संरक्षित वन (Protected)","32.84%","कुछ नियमों के साथ चराई की अनुमति।"],["अवर्गीकृत वन (Unclassified)","1.80%","कोई विशेष प्रतिबंध नहीं।"]]},{"type":"h3","text":"प्रजाति के आधार पर (Species based)"},{"type":"p","text":""},{"type":"ul","items":["**सागौन (Teak):** राज्य के कुल वन क्षेत्र का **19.36%**। (सर्वाधिक: होशंगाबाद/नर्मदापुरम के बोरी अभ्यारण्य में)।","**साल (Sal):** कुल वन क्षेत्र का **4.15%**। (पूर्वी मध्य प्रदेश - मंडला, डिंडोरी)।","**मिश्रित वन:** सर्वाधिक क्षेत्रफल (लगभग 58%) इन्हीं वनों का है।"]},{"type":"h2","text":"2. प्रमुख वनोपज (Forest Produce)"},{"type":"fact_card","title":"लघु वनोपज (Minor Forest Produce)","facts":["तेंदूपत्ता (Tendu Patta): MP भारत का 60% तेंदूपत्ता उत्पादित करता है। (सर्वाधिक: सागर जिला)।","महुआ (Mahua): आदिवासियों की ''अर्थव्यवस्था का आधार'' (Base of Tribal Economy)।","भिलावा (Bhilawa): स्याही (Ink) और रंग बनाने में उपयोग। (छिंदवाड़ा में फैक्ट्री)।","हर्रा (Harra): चर्म शोधन (Tanning) और औषधि निर्माण में।"],"icon":"🍃"},{"type":"highlight","level":"critical","text":"लाख (Lac): उमरिया में लाख बनाने का सरकारी कारखाना स्थित है। यह ''कुसुम'', ''पलाश'' और ''बेर'' के पेड़ों से प्राप्त होता है।","icon":"🧪"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश के किस जिले में ''सागौन'' के वन सर्वाधिक पाए जाते हैं?","options":["होशंगाबाद (नर्मदापुरम)","उज्जैन","इंदौर","ग्वालियर"],"correct":"होशंगाबाद (नर्मदापुरम)","strategy":"बोरी घाटी (होशंगाबाद) अपने सबसे ऊंचे और गुणवत्तापूर्ण सागौन के पेड़ों के लिए जानी जाती है।"},{"type":"exam_pattern","topic":"MP Forest Trend","analysis":"Unit 4 Forest Trend:","stats":["ISFR रिपोर्ट डेटा: 1-2 प्रश्न","वनोपज और जिले: 1 प्रश्न","सरकारी संस्थान: 1 प्रश्न"],"trend":"आयोग अब ''वृक्षारोपण'' योजनाओं और नवीनतम वन स्थिति रिपोर्ट के आंकड़ों पर अधिक ध्यान दे रहा है।"}],"en":[{"type":"h2","text":"Unit 4: Forest and Forest Produce of MP"},{"type":"p","text":"Madhya Pradesh has the largest forest cover in India by area. "},{"type":"h2","text":"1. Forest Classification"},{"type":"table","instruction":"Administrative Classification","head":["Category","Percentage (%)","Description"],"body":[["Reserved Forest","65.36%","Strict government control, no grazing/cutting."],["Protected Forest","32.84%","Grazing allowed with permits."],["Unclassified Forest","1.80%","Minimal restrictions."]]},{"type":"h3","text":"By Species"},{"type":"ul","items":["**Teak (Sagoun):** 19.36% of total forest area. (Best quality in Bori Sanctuary, Hoshangabad).","**Sal:** 4.15% of total forest area. (Found in Eastern MP - Mandla, Dindori).","**Mixed Forests:** Occupy the largest share (Approx 58%)."]},{"type":"h2","text":"2. Forest Produce"},{"type":"fact_card","title":"Minor Forest Produce","facts":["Tendu Patta: MP produces 60% of India''s Tendu leaves.","Mahua: Backbone of tribal economy; used for alcohol and oil.","Lac: Government factory located in Umaria.","Harra: Used in Tanning and medicinal purposes."],"icon":"🍃"}]}', 'mp_gk', NULL, 20, 1, 1770837827, 1772640848, 'blog', 'unit_4', 'Forest, Forest Produce', 0, 0, 1, 1, 0, 'Unit 4: मध्य प्रदेश के वन और वनोपज (Forest Resources) मध्य प्रदेश क्षेत्रफल की दृष्टि से भारत का सर्वाधिक वनाच्छादित राज्य है। ''इंडिया स्टेट ऑफ फॉरेस्ट रिपोर्ट (ISFR) 2021'' के अनुसार, राज्य का कुल वन ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('60e79312-ce4d-43e3-ba16-26e9bc104d3e', 'rivers-madhya-pradesh-drainage-unit-4-mppsc', 'Rivers of Madhya Pradesh: Lifelines of the State | मध्य प्रदेश की नदियाँ', 'Comprehensive guide to MP''s drainage system. Detailed coverage of Narmada, Chambal, Son, Tapti, and Betwa. Includes tributaries, dams, waterfalls, and MPPSC PYQs.', '{"hi":[{"type":"h2","text":"Unit 4: मध्य प्रदेश का अपवाह तंत्र (Drainage System)"},{"type":"p","text":"मध्य प्रदेश को ''नदियों का मायका'' कहा जाता है क्योंकि यहाँ से लगभग 207 छोटी-बड़ी नदियाँ निकलती हैं। राज्य का ढाल उत्तर और पूर्व की ओर है। "},{"type":"h2","text":"1. नर्मदा नदी (Narmada) - ''म.प्र. की जीवन रेखा''"},{"type":"p","text":"नर्मदा मध्य प्रदेश की सबसे बड़ी और भारत की पांचवीं सबसे बड़ी नदी है। यह एक ''भ्रंश घाटी'' (Rift Valley) में बहती है। "},{"type":"fact_card","title":"नर्मदा: मुख्य तथ्य","facts":["उद्गम: अमरकंटक (अनूपपुर) - मैकल श्रेणी।","कुल लंबाई: 1312 किमी (म.प्र. में 1077 किमी)।","सहायक नदियाँ: 41 (बायीं ओर से 22, दायीं ओर से 19)। प्रमुख: तवा, शक्कर, दूधनी, हिरण, हथिनी।","उपनाम: रेवा, मेकलसुता, सोमोदेवी, नामोदोस (टॉलेमी द्वारा)।","जलप्रपात: धुआँधार (जबलपुर), दुग्धधारा, कपिलधारा (अमरकंटक), सहस्रधारा (महेश्वर)।"],"icon":"🌊"},{"type":"table","instruction":"नर्मदा पर प्रमुख बांध","head":["बांध का नाम","स्थान/जिला","विशेषता"],"body":[["इंदिरा सागर (पुनासा)","खंडवा","म.प्र. का सबसे बड़ा जलाशय।"],["सरदार सरोवर","केवडिया (गुजरात)","नर्मदा की सबसे बड़ी परियोजना।"],["ओंकारेश्वर","खंडवा","यहाँ ''फ्लोटिंग'' सोलर प्लांट प्रस्तावित है।"],["बरगी बांध","जबलपुर","रानी अवंतीबाई सागर परियोजना।"]]},{"type":"h2","text":"2. चंबल नदी (Chambal) - ''मालवा की गंगा''"},{"type":"p","text":"यह यमुना की प्रमुख सहायक नदी है और अपने ''बीहड़ों'' (Ravines/Badlands) के लिए कुख्यात है। "},{"type":"ul","items":["**उद्गम:** जानापाव पहाड़ी (महू, इंदौर)।","**लंबाई:** 965 किमी।","**सहायक नदियाँ:** क्षिप्रा, कालीसिंध, पार्वती, बनास।","**जलप्रपात:** चूलिया (भैंसरोडगढ़), पातालपानी (इंदौर)।","**मृदा अपरदन:** यह नदी ''अवनलिका अपरदन'' (Gully Erosion) के लिए प्रसिद्ध है।"]},{"type":"mnemonic","topic":"चंबल के बांध (क्रम से)","trick":"G-R-J (गरज)","visual":"⚡","explanation":"1. **G**andhi Sagar (मंदसौर) - म.प्र. का पहला बांध।\n2. **R**ana Pratap Sagar (चित्तौड़गढ़, RJ)।\n3. **J**awahar Sagar (कोटा, RJ)।"},{"type":"h2","text":"3. अन्य महत्वपूर्ण नदियाँ (Other Major Rivers)"},{"type":"table","instruction":"नदी, उद्गम और संगम","head":["नदी","उद्गम (Source)","संगम (Mouth)"],"body":[["ताप्ती (Tapti)","मुलताई (बैतूल)","खंभात की खाड़ी (अरब सागर)"],["सोन (Son)","अमरकंटक (अनूपपुर)","गंगा (पटना के पास)"],["बेतवा (Betwa)","कुमराहगाँव (रायसेन)","यमुना (हमीरपुर, UP)"],["क्षिप्रा (Kshipra)","काकरीबर्डी (इंदौर)","चंबल"],["केन (Ken)","अहिरगाँव (कटनी)","यमुना"]]},{"type":"highlight","level":"important","text":"बेतवा नदी: इसे ''बुंदेलखंड की जीवन रेखा'' और प्रदूषण के कारण ''म.प्र. की गंगा'' कहा जाता है। ओरछा इसी के तट पर स्थित है।","icon":"📍"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"नर्मदा नदी की कुल कितनी सहायक नदियाँ हैं?","options":["31","41","21","51"],"correct":"41","strategy":"नर्मदा के हाथ में 41 चूड़ियाँ हैं (Trick to remember)।"},{"type":"exam_pattern","topic":"MP Rivers Trend","analysis":"Unit 4 Rivers Trend Analysis:","stats":["उद्गम और संगम (Matching): 2 प्रश्न","परियोजनाएं/बांध: 1 प्रश्न","नदी तट पर शहर: 1 प्रश्न"],"trend":"आयोग अब सहायक नदियों के नाम और ''नदी जोड़ो परियोजनाओं'' पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 4: Drainage System of Madhya Pradesh"},{"type":"p","text":"Madhya Pradesh is often called the ''Home of Rivers''. "},{"type":"h2","text":"1. Narmada River - ''Life Line of MP''"},{"type":"p","text":"Narmada flows through a ''Rift Valley'' between the Vindhyas and Satpuras, forming an Estuary instead of a Delta."},{"type":"fact_card","title":"Narmada: Key Facts","facts":["Origin: Amarkantak (Anuppur) - Maikal Range.","Total Length: 1312 km (1077 km within MP).","Tributaries: 41 (22 from Left, 19 from Right).","Nicknames: Reva, Maikalsuta, Somodevi, Namados.","Waterfalls: Dhuandhar, Dugdhdhara, Sahasradhara."],"icon":"🌊"},{"type":"table","instruction":"Major Dams on Narmada","head":["Dam Name","District","Key Feature"],"body":[["Indira Sagar","Khandwa","Largest reservoir in MP."],["Sardar Sarovar","Kevadia (GJ)","Largest project on Narmada system."],["Omkareshwar","Khandwa","Proposed floating solar plant."],["Bargi Dam","Jabalpur","Rani Avantibai Sagar Project."]]},{"type":"h2","text":"2. Chambal River - ''Ganga of Malwa''"},{"type":"p","text":"The primary tributary of Yamuna in MP, notorious for forming extensive Ravines (Badlands)."},{"type":"ul","items":["**Origin:** Janapav Hills (Mhow, Indore).","**Length:** 965 km.","**Tributaries:** Kshipra, Kalisindh, Parvati, Banas.","**Waterfalls:** Chulia, Patalpani.","**Soil Erosion:** Known for massive ''Gully Erosion''."]},{"type":"mnemonic","topic":"Chambal Dams (In Order)","trick":"G-R-J (Garaj)","visual":"⚡","explanation":"1. **G**andhi Sagar (Mandsaur)\n2. **R**ana Pratap Sagar (RJ)\n3. **J**awahar Sagar (RJ)"},{"type":"h2","text":"3. Other Significant Rivers"},{"type":"table","instruction":"River, Origin & Confluence","head":["River","Origin (Source)","Mouth (Confluence)"],"body":[["Tapti","Multai (Betul)","Gulf of Khambhat (Arabian Sea)"],["Son","Amarkantak (Anuppur)","Ganga (near Patna)"],["Betwa","Kumra Gaon (Raisen)","Yamuna (Hamirpur, UP)"],["Kshipra","Kakri Bardi (Indore)","Chambal"],["Ken","Ahir Gaon (Katni)","Yamuna"]]},{"type":"highlight","level":"important","text":"Betwa River: Called ''Lifeline of Bundelkhand'' and ''Ganga of MP'' due to pollution. ","icon":"📍"}]}', 'geography', NULL, 30, 1, 1770912748, 1771008875, 'blog', 'unit_4', 'Rivers of Madhya Pradesh', 1, 0, 1, 1, 0, 'Unit 4: मध्य प्रदेश का अपवाह तंत्र (Drainage System) मध्य प्रदेश को ''नदियों का मायका'' कहा जाता है क्योंकि यहाँ से लगभग 207 छोटी-बड़ी नदियाँ निकलती हैं। राज्य का ढाल उत्तर और पूर्व की ओर है।  1. नर्मदा...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('e4ffe671-a2ad-4332-9e66-391e707cb342', 'plateaus-hills-madhya-pradesh-unit-4-mppsc', 'Plateaus and Hills of Madhya Pradesh | मध्य प्रदेश के पठार और पहाड़ियाँ', 'Comprehensive guide to the physical division of Madhya Pradesh. Detailed analysis of Malwa, Bundelkhand, Rewa-Panna, Baghelkhand plateaus and Vindhya-Satpura ranges.', '{"hi":[{"type":"h2","text":"Unit 4: मध्य प्रदेश का भौतिक विभाजन (पठार और पहाड़ियाँ)"},{"type":"p","text":"भौगोलिक रूप से मध्य प्रदेश ''प्रायद्वीपीय पठार'' का हिस्सा है। इसे मुख्य रूप से 7 भौतिक विभागों में बांटा गया है। "},{"type":"h2","text":"1. मध्य प्रदेश के प्रमुख पठार (Major Plateaus)"},{"type":"table","instruction":"पठार: क्षेत्रफल, मिट्टी और सर्वोच्च चोटी","head":["पठार का नाम","क्षेत्रफल (%)","मिट्टी (Soil)","सर्वोच्च चोटी"],"body":[["मालवा का पठार","28.62% (सबसे बड़ा)","काली मिट्टी","सिगार (881 मीटर)"],["मध्य भारत का पठार","10.68%","जलोढ़ मिट्टी","उपलब्ध नहीं"],["बुंदेलखंड का पठार","7.70%","मिश्रित मिट्टी","सिद्धबाबा (1172 मीटर)"],["रीवा-पन्ना का पठार","10.37%","लाल-पीली मिट्टी","सद्भावना शिखर (752 मीटर)"],["नर्मदा-सोन घाटी","26.00%","गहरी काली मिट्टी","उपलब्ध नहीं"],["बघेलखंड का पठार","7.00% (सबसे छोटा)","लाल-पीली मिट्टी","उपलब्ध नहीं"]]},{"type":"highlight","level":"important","text":"मालवा का पठार: इसे ''गेहूं की डलिया'' कहा जाता है। फाह्यान ने इसकी जलवायु को विश्व की सर्वश्रेष्ठ जलवायु बताया था।","icon":"🌾"},{"type":"h2","text":"2. प्रमुख पर्वत श्रेणियाँ और पहाड़ियाँ (Major Hills)"},{"type":"p","text":"मध्य प्रदेश में दो प्रमुख पर्वत प्रणालियाँ हैं: विंध्याचल और सतपुड़ा। "},{"type":"h3","text":"विंध्याचल पर्वत श्रेणी (Vindhyachal Range)"},{"type":"ul","items":["यह सबसे पुरानी पर्वत श्रेणियों में से एक है।","इसकी तीन शाखाएँ हैं: विंध्याचल (पश्चिम), भांडेर (मध्य), और कैमूर (पूर्व)।","कैमूर श्रेणी यमुना और सोन नदी के बीच ''जल विभाजक'' का कार्य करती है।"]},{"type":"h3","text":"सतपुड़ा पर्वत श्रेणी (Satpura Range)"},{"type":"p","text":"यह नर्मदा और ताप्ती नदियों के बीच स्थित है। इसे पश्चिम से पूर्व तीन भागों में बांटा गया है: "},{"type":"mnemonic","topic":"सतपुड़ा का विभाजन (पश्चिम से पूर्व)","trick":"R-M-M (राज-महा-मै)","visual":"⛰️","explanation":"1. **R**ajpipla (राजपीपला): पश्चिमी भाग।\n2. **M**ahadev (महादेव): मध्य भाग। धूपगढ़ यहीं स्थित है।\n3. **M**aikal (मैकल): पूर्वी भाग। अर्ध-चंद्राकार है।"},{"type":"highlight","level":"critical","text":"धूपगढ़ (1350 मीटर): सतपुड़ा की और मध्य प्रदेश की सर्वोच्च चोटी है। यह पचमढ़ी (होशंगाबाद) में स्थित है।","icon":"🏆"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश की सबसे ऊँची चोटी ''धूपगढ़'' कहाँ स्थित है?","options":["महादेव पहाड़ियों में","राजपीपला में","मैकल श्रेणी में","विंध्याचल में"],"correct":"महादेव पहाड़ियों में","strategy":"धूपगढ़ पचमढ़ी में है, जो महादेव श्रेणी का हिस्सा है।"},{"type":"exam_pattern","topic":"MP Physical Trend","analysis":"Unit 4 Physical Trend Analysis:","stats":["सर्वोच्च चोटी (Peaks): 1-2 प्रश्न","पठार का क्षेत्रफल/मिट्टी: 1 प्रश्न","पर्वत श्रेणियों का क्रम: 1 प्रश्न"],"trend":"आयोग अब चोटियों की सटीक ऊंचाई और पहाड़ियों के स्थानीय नामों पर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 4: Physical Division of MP (Plateaus and Hills)"},{"type":"p","text":"Geographically, Madhya Pradesh is part of the ''Peninsular Plateau''. "},{"type":"h2","text":"1. Major Plateaus of Madhya Pradesh"},{"type":"table","instruction":"Plateaus: Area, Soil and Highest Peak","head":["Name of Plateau","Area (%)","Soil Type","Highest Peak"],"body":[["Malwa Plateau","28.62% (Largest)","Black Soil","Sigar (881 m)"],["Central India Plateau","10.68%","Alluvial Soil","N/A"],["Bundelkhand Plateau","7.70%","Mixed Soil","Siddhababa (1172 m)"],["Rewa-Panna Plateau","10.37%","Red-Yellow Soil","Sadbhavana Peak (752 m)"],["Narmada-Son Valley","26.00%","Deep Black Soil","N/A"],["Baghelkhand Plateau","7.00% (Smallest)","Red-Yellow Soil","N/A"]]},{"type":"h2","text":"2. Major Mountain Ranges and Hills"},{"type":"h3","text":"Vindhyachal Mountain Range"},{"type":"ul","items":["One of the oldest mountain systems. ","Three branches: Vindhyachal (West), Bhander (Middle), and Kaimur (East).","Kaimur range acts as a ''Water Divide'' between Yamuna and Son rivers."]},{"type":"h3","text":"Satpura Mountain Range"},{"type":"mnemonic","topic":"Division of Satpura (West to East)","trick":"R-M-M","visual":"⛰️","explanation":"1. **R**ajpipla: Western part.\n2. **M**ahadev: Central part (Dhupgarh).\n3. **M**aikal: Eastern part (Semi-circular)."},{"type":"highlight","level":"critical","text":"Dhupgarh (1350 m): Highest peak of Satpura and Madhya Pradesh. Located in Pachmarhi.","icon":"🏆"}]}', 'geography', NULL, 25, 1, 1770916464, 1771008876, 'blog', 'unit_4', 'Hills and Plateaus', 1, 0, 1, 1, 0, 'Unit 4: मध्य प्रदेश का भौतिक विभाजन (पठार और पहाड़ियाँ) भौगोलिक रूप से मध्य प्रदेश ''प्रायद्वीपीय पठार'' का हिस्सा है। इसे मुख्य रूप से 7 भौतिक विभागों में बांटा गया है।  1. मध्य प्रदेश के प्रमुख पठार (...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('f560977e-09ad-4522-bc02-ccbe846eaa1c', 'climate-madhya-pradesh-unit-4-mppsc', 'Climate of Madhya Pradesh: Seasons, Temperature & Rainfall | म.प्र. की जलवायु', 'Comprehensive guide to the climate of Madhya Pradesh for MPPSC Unit 4. Analysis of seasonal variations, temperature distribution, and rainfall patterns across the state.', '{"hi":[{"type":"h2","text":"Unit 4: मध्य प्रदेश की जलवायु (Seasons, Temperature & Rainfall)"},{"type":"p","text":"मध्य प्रदेश की जलवायु ''उष्णकटिबंधीय मानसूनी'' (Tropical Monsoon) प्रकार की है। कर्क रेखा राज्य के मध्य से गुजरती है, जो इसके तापमान को गहराई से प्रभावित करती है। "},{"type":"h2","text":"1. मध्य प्रदेश की ऋतुएँ (Seasons of MP)"},{"type":"p","text":"मध्य प्रदेश में मुख्य रूप से तीन ऋतुएँ होती हैं, जिन्हें स्थानीय नामों से भी जाना जाता है।"},{"type":"table","instruction":"ऋतुएँ और उनके स्थानीय नाम","head":["ऋतु (Season)","समय (Period)","स्थानीय नाम (Local Name)"],"body":[["ग्रीष्म ऋतु (Summer)","मार्च से जून","यूनाला (Unala)"],["वर्षा ऋतु (Rainy)","जून से अक्टूबर","चौमासा (Chaumasa)"],["शीत ऋतु (Winter)","अक्टूबर से मार्च","सियाला (Siyala)"]]},{"type":"highlight","level":"important","text":"मावठ (Mawat): शीत ऋतु में होने वाली हल्की वर्षा को ''मावठ'' कहते हैं, जो रबी की फसल के लिए अमृत समान है।","icon":"🌧️"},{"type":"h2","text":"2. तापमान का वितरण (Temperature Distribution)"},{"type":"ul","items":["**सर्वाधिक गर्म स्थान:** गंजबसौदा (विदिशा) ऐतिहासिक रूप से, वर्तमान में खजुराहो और नौगाँव में भी उच्च तापमान दर्ज किया जाता है।","**सर्वाधिक ठंडा स्थान:** शिवपुरी।","**औसत तापमान:** मई राज्य का सबसे गर्म महीना होता है, जबकि जनवरी सबसे ठंडा।"]},{"type":"h2","text":"3. वर्षा का वितरण (Rainfall Distribution)"},{"type":"p","text":"राज्य में वर्षा मुख्य रूप से ''दक्षिण-पश्चिम मानसून'' (South-West Monsoon) से होती है। वर्षा पूर्व से पश्चिम की ओर कम होती जाती है। "},{"type":"table","instruction":"वर्षा के आधार पर क्षेत्र","head":["क्षेत्र (Region)","वर्षा की मात्रा","विवरण"],"body":[["अत्यधिक वर्षा","150 सेमी से अधिक","पचमढ़ी (सर्वाधिक - 199 सेमी), महादेव पहाड़ियाँ।"],["औसत से अधिक","125 - 150 सेमी","पूर्वी मध्य प्रदेश (बघेलखंड)।"],["औसत से कम","75 - 100 सेमी","मालवा और मध्य भारत का पठार।"],["न्यूनतम वर्षा","50 - 75 सेमी","भिंड (गोहद - 55 सेमी, सबसे कम)।"]]},{"type":"highlight","level":"critical","text":"पचमढ़ी: इसे ''मध्य प्रदेश का चेरापूँजी'' कहा जाता है क्योंकि यहाँ राज्य की सर्वाधिक वर्षा होती है।","icon":"📍"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश में ''चौमासा'' किस ऋतु को कहा जाता है?","options":["शीत ऋतु","ग्रीष्म ऋतु","वर्षा ऋतु","बसंत ऋतु"],"correct":"वर्षा ऋतु","strategy":"याद रखें: चार महीने (चौ-मासा) की वर्षा।"},{"type":"exam_pattern","topic":"MP Climate Trend","analysis":"Unit 4 Climate Trend Analysis:","stats":["स्थानीय नाम (Unala/Siyala): 1 प्रश्न","वर्षा का डेटा/स्थान: 1 प्रश्न","जलवायु का प्रकार: 1 प्रश्न"],"trend":"आयोग अब मानसून की अरब सागर और बंगाल की खाड़ी शाखाओं के प्रभाव पर अधिक विश्लेषणात्मक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 4: Climate of Madhya Pradesh (Seasons, Temperature & Rainfall)"},{"type":"p","text":"The climate of Madhya Pradesh is of the ''Tropical Monsoon'' type. [Image showing the climate zones of Madhya Pradesh based on Koppen''s classification]"},{"type":"h2","text":"1. Seasons of Madhya Pradesh"},{"type":"table","instruction":"Seasons and Local Names","head":["Season","Period","Local Name"],"body":[["Summer","March to June","Unala"],["Rainy","June to October","Chaumasa"],["Winter","October to March","Siyala"]]},{"type":"h2","text":"2. Temperature Distribution"},{"type":"ul","items":["**Hottest Place:** Ganjbasoda (Vidisha) historically.","**Coldest Place:** Shivpuri.","**Average Temp:** May is the hottest month, while January is the coldest."]},{"type":"h2","text":"3. Rainfall Distribution"},{"type":"p","text":"Rainfall in the state occurs mainly from the ''South-West Monsoon''. [Image showing the entry points of Arabian Sea and Bay of Bengal monsoon branches into Madhya Pradesh]"},{"type":"table","instruction":"Regions Based on Rainfall","head":["Region","Rainfall Amount","Description"],"body":[["Heavy Rainfall","Above 150 cm","Pachmarhi (Highest - 199 cm)."],["Minimum Rainfall","50 - 75 cm","Bhind (Gohad - 55 cm, Lowest)."]]},{"type":"highlight","level":"critical","text":"Pachmarhi: Known as the ''Cherrapunji of Madhya Pradesh''.","icon":"📍"}]}', 'geography', NULL, 20, 1, 1770916534, 1771008877, 'blog', 'unit_4', 'Climate: Seasons, Temperature, Rainfall', 1, 0, 1, 1, 0, 'Unit 4: मध्य प्रदेश की जलवायु (Seasons, Temperature & Rainfall) मध्य प्रदेश की जलवायु ''उष्णकटिबंधीय मानसूनी'' (Tropical Monsoon) प्रकार की है। कर्क रेखा राज्य के मध्य से गुजरती है, जो इसके तापमान को गह...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('499c1eed-1a44-474b-9308-0843c9786feb', 'soils-minerals-madhya-pradesh-unit-4-mppsc', 'Natural Resources of MP: Soils & Mineral Resources | म.प्र. के प्राकृतिक संसाधन: मिट्टी और खनिज', 'Exhaustive guide to the soil types and mineral wealth of Madhya Pradesh. Covers black soil, red-yellow soil, and major minerals like Diamond, Copper, and Manganese for MPPSC Unit 4.', '{"hi":[{"type":"h2","text":"Unit 4: मध्य प्रदेश की मिट्टी और खनिज संसाधन"},{"type":"p","text":"मध्य प्रदेश की भौगोलिक संरचना ने इसे विविध मिट्टियों और प्रचुर खनिज संपदा से नवाजा है। ''खनिज भंडारण'' के मामले में यह भारत के अग्रणी राज्यों में से एक है।"},{"type":"h2","text":"1. मध्य प्रदेश की मिट्टियाँ (Soils of MP)"},{"type":"p","text":"भारतीय मृदा विज्ञान संस्थान (IISS, भोपाल) के अनुसार, राज्य में मुख्य रूप से 5 प्रकार की मिट्टियाँ पाई जाती हैं। "},{"type":"table","instruction":"मिट्टी के प्रकार और उनकी विशेषताएँ","head":["मिट्टी का नाम","क्षेत्र (Region)","मुख्य फसलें","विशेषता"],"body":[["काली मिट्टी (Black)","मालवा, नर्मदा घाटी","कपास, सोयाबीन, गेहूं","सर्वाधिक क्षेत्रफल (47%)। इसमें ''लोहा'' और ''चूना'' अधिक होता है।"],["लाल-पीली मिट्टी (Red-Yellow)","बघेलखंड (पूर्वी MP)","धान (चावल)","फेरिक ऑक्साइड के कारण लाल और फेरिक हाइड्रेट के कारण पीली।"],["जलोढ़ मिट्टी (Alluvial)","मध्य भारत (ग्वालियर, भिंड)","सरसों, गेहूं","सर्वाधिक उपजाऊ मिट्टी। नाइट्रोजन की कमी होती है।"],["मिश्रित मिट्टी (Mixed)","बुंदेलखंड","ज्वार, बाजरा, दालें","लाल, पीली और काली मिट्टी का मिश्रण।"],["लैटेराइट मिट्टी (Laterite)","छिंदवाड़ा, बालाघाट","कॉफी, चाय, मसाले","इसे ''लाल मुमी'' मिट्टी भी कहते हैं।"]]},{"type":"highlight","level":"important","text":"काली मिट्टी के उप-प्रकार: 1. साधारण काली (मालवा), 2. गहरी काली (नर्मदा घाटी), 3. छिछली काली (सतपुड़ा क्षेत्र)।","icon":"🌱"},{"type":"h2","text":"2. प्रमुख खनिज संसाधन (Major Mineral Resources)"},{"type":"p","text":"मध्य प्रदेश हीरा, तांबा और मैंगनीज के उत्पादन में भारत में प्रथम स्थान पर है। "},{"type":"table","instruction":"प्रमुख खनिज और उनकी खदानें","head":["खनिज (Mineral)","प्रमुख खदान (Mines)","जिला","विशेष तथ्य"],"body":[["हीरा (Diamond)","हिनौता, मझगवां","पन्ना, सतना","MP भारत का एकमात्र हीरा उत्पादक राज्य है।"],["तांबा (Copper)","मलांजखंड","बालाघाट","एशिया की सबसे बड़ी खुली तांबा खदान। इसे ''तांबा नगरी'' कहते हैं।"],["मैंगनीज (Manganese)","भारवेली","बालाघाट","एशिया की सबसे बड़ी भूमिगत मैंगनीज खदान।"],["कोयला (Coal)","सुहागपुर, सिंगरौली","शहडोल, सिंगरौली","सिंगरौली को ''म.प्र. की ऊर्जा राजधानी'' कहा जाता है।"],["लोहा (Iron)","कुंभन, मझागाँव","जबलपुर, ग्वालियर","यहाँ हेमेटाइट प्रकार का लोहा मिलता है।"]]},{"type":"highlight","level":"critical","text":"सिंगरौली की कोयला परत: यहाँ विश्व की दूसरी सबसे मोटी कोयला परत (136 मीटर) पाई जाती है।","icon":"⚡"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मलांजखंड किस खनिज उत्पादन के लिए प्रसिद्ध है?","options":["हीरा","तांबा","मैंगनीज","लौह अयस्क"],"correct":"तांबा","strategy":"मलांजखंड = बालाघाट = तांबा (याद रखें)।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"मध्य प्रदेश के किस क्षेत्र में सर्वाधिक ''काली मिट्टी'' पाई जाती है?","options":["मालवा क्षेत्र","बघेलखंड","बुंदेलखंड","ग्वालियर संभाग"],"correct":"मालवा क्षेत्र","strategy":"बेसाल्ट चट्टानों के टूटने से मालवा में काली मिट्टी का निर्माण हुआ है।"}],"en":[{"type":"h2","text":"Unit 4: Soils and Mineral Resources of Madhya Pradesh"},{"type":"p","text":"The geological structure of Madhya Pradesh has blessed it with diverse soils and abundant mineral wealth."},{"type":"h2","text":"1. Soils of Madhya Pradesh"},{"type":"p","text":"According to the Indian Institute of Soil Science (IISS, Bhopal), there are mainly 5 types of soils found in the state. "},{"type":"table","instruction":"Soil Types and Their Characteristics","head":["Soil Name","Region","Main Crops","Feature"],"body":[["Black Soil","Malwa, Narmada Valley","Cotton, Soybean, Wheat","Covers the largest area (47%). Rich in Iron and Lime."],["Red-Yellow Soil","Baghelkhand (East MP)","Paddy (Rice)","Red due to Ferric Oxide and Yellow due to Ferric Hydrate."],["Alluvial Soil","Central India (Gwalior, Bhind)","Mustard, Wheat","Most fertile soil. Deficient in Nitrogen."],["Mixed Soil","Bundelkhand","Jowar, Bajra, Pulses","A mixture of red, yellow, and black soils."],["Laterite Soil","Chhindwara, Balaghat","Coffee, Tea, Spices","Also known as ''Lal Mumi'' soil."]]},{"type":"h2","text":"2. Major Mineral Resources"},{"type":"p","text":"Madhya Pradesh ranks first in India in the production of Diamond, Copper, and Manganese."},{"type":"table","instruction":"Major Minerals and Their Mines","head":["Mineral","Major Mine","District","Special Fact"],"body":[["Diamond","Hinota, Majhgawan","Panna, Satna","MP is the only diamond-producing state in India."],["Copper","Malanjkhand","Balaghat","Largest open-cast copper mine in Asia."],["Manganese","Bharveli","Balaghat","Largest underground manganese mine in Asia."],["Coal","Sohagpur, Singrauli","Shahdol, Singrauli","Singrauli is known as the ''Energy Capital of MP''."],["Iron","Kumbhan, Majhgawan","Jabalpur, Gwalior","Hematite type iron is found here."]]},{"type":"highlight","level":"critical","text":"Singrauli Coal Seam: The world''s second-thickest coal seam (136 meters) is found here.","icon":"⚡"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Malanjkhand is famous for the production of which mineral?","options":["Diamond","Copper","Manganese","Iron Ore"],"correct":"Copper","strategy":"Remember: Malanjkhand = Balaghat = Copper."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"In which region of MP is ''Black Soil'' mostly found?","options":["Malwa Region","Baghelkhand","Bundelkhand","Gwalior Division"],"correct":"Malwa Region","strategy":"Black soil in Malwa is formed by the weathering of Basalt rocks."}]}', 'geography', NULL, 25, 1, 1770916825, 1771009092, 'blog', 'unit_4', 'Natural Resources: Soils and Major Mineral resources', 0, 0, 0, 1, 0, 'Unit 4: मध्य प्रदेश की मिट्टी और खनिज संसाधन मध्य प्रदेश की भौगोलिक संरचना ने इसे विविध मिट्टियों और प्रचुर खनिज संपदा से नवाजा है। ''खनिज भंडारण'' के मामले में यह भारत के अग्रणी राज्यों में से एक है। 1...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('1ba8b9cb-a763-4a25-b066-986672699e30', 'comprehensive-agriculture-irrigation-mp-unit-4', 'Major Crops and Irrigation Projects of MP | म.प्र. की प्रमुख फसलें और सिंचाई परियोजनाएं', 'A deep dive into Madhya Pradesh''s agricultural economy and water management. Detailed analysis of crop belts, irrigation sources, and major river valley projects for MPPSC Unit 4.', '{"hi":[{"type":"h2","text":"Unit 4: मध्य प्रदेश की कृषि और सिंचाई व्यवस्था"},{"type":"p","text":"मध्य प्रदेश एक कृषि प्रधान राज्य है, जिसे अपनी उत्कृष्ट कृषि उत्पादकता के लिए लगातार ''कृषि कर्मण पुरस्कार'' से नवाजा गया है। राज्य की अर्थव्यवस्था प्राथमिक क्षेत्र पर टिकी है, जहाँ सिंचाई के साधनों का विकास कृषि की रीढ़ माना जाता है।"},{"type":"h2","text":"1. मध्य प्रदेश की प्रमुख फसलें (Major Crops)"},{"type":"p","text":"मध्य प्रदेश को ''सोया स्टेट'' कहा जाता है, लेकिन यहाँ की फसल विविधता बहुत अधिक है। मालवा से लेकर बघेलखंड तक अलग-अलग फसल पेटियां पाई जाती हैं।"},{"type":"image_tag","content":""},{"type":"table","instruction":"प्रमुख फसलें और उनके क्षेत्र","head":["फसल","मुख्य उत्पादक जिले","विशेष तथ्य"],"body":[["सोयाबीन (Soybean)","उज्जैन, धार, इंदौर, सीहोर","MP भारत का अग्रणी उत्पादक है। इसे ''पीला सोना'' भी कहते हैं।"],["गेहूं (Wheat)","होशंगाबाद (नर्मदापुरम), सीहोर, विदिशा","होशंगाबाद में सर्वाधिक उत्पादन। मालवा को ''गेहूं का भंडार'' कहते हैं।"],["चावल (Paddy)","बालाघाट, मंडला, सिवनी","बालाघाट के ''चिन्नौर चावल'' को GI टैग प्राप्त है।"],["कपास (Cotton)","खरगोन, खंडवा, बड़वानी","इसे ''सफेद सोना'' कहते हैं। ''निमाड़'' क्षेत्र कपास का केंद्र है।"],["मक्का (Maize)","छिंदवाड़ा, धार, झाबुआ","छिंदवाड़ा को ''कॉर्न सिटी'' (Corn City) कहा जाता है।"],["सरसों (Mustard)","मुरैना, भिंड, श्योपुर","मध्य भारत का पठार ''सरसों की डलिया'' कहलाता है।"]]},{"type":"highlight","level":"important","text":"श्री अन्न (Millets): वर्ष 2023 को अंतर्राष्ट्रीय मिलेट वर्ष घोषित किया गया था। म.प्र. में कोदो-कुटकी (डिंडोरी/मंडला) प्रमुख मिलेट्स हैं।","icon":"🌾"},{"type":"h2","text":"2. जल संसाधन एवं सिंचाई (Water Resources)"},{"type":"p","text":"मध्य प्रदेश में सिंचाई के साधनों में क्षेत्रीय भिन्नता पाई जाती है। पश्चिमी भाग में कुओं का महत्व है, तो उत्तर में नहरों का।"},{"type":"table","instruction":"सिंचाई के साधन: तुलनात्मक अध्ययन","head":["साधन","प्रतिशत (%)","लाभान्वित क्षेत्र"],"body":[["कुएं एवं नलकूप","67.0%","मालवा क्षेत्र (इंदौर, उज्जैन, मंदसौर)"],["नहरें (Canals)","18.0%","चंबल घाटी और नर्मदा घाटी क्षेत्र"],["तालाब (Tanks)","3.0%","बालाघाट और सिवनी जिला"],["अन्य स्रोत","12.0%","नदियाँ और छोटे झरने"]]},{"type":"h2","text":"3. प्रमुख सिंचाई परियोजनाएं (Irrigation Projects)"},{"type":"p","text":"मध्य प्रदेश की परियोजनाओं को ''नर्मदा घाटी विकास'' और अन्य नदी बेसिन के आधार पर समझा जा सकता है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"महत्वपूर्ण बांध और परियोजनाएं","head":["परियोजना","नदी","स्थान/विशेषता"],"body":[["चंबल घाटी परियोजना","चंबल","राज्य की पहली परियोजना (1953)। गांधी सागर, राणा प्रताप, जवाहर सागर।"],["बाणसागर परियोजना","सोन","शहडोल (देवलोंद)। म.प्र., उ.पर. और बिहार की संयुक्त परियोजना।"],["रानी लक्ष्मीबाई (राजघाट)","बेतवा","अशोकनगर/ललितपुर। म.प्र. और उ.प्र. की साझा परियोजना।"],["तवा परियोजना","तवा","होशंगाबाद। म.प्र. का सबसे लंबा मिट्टी का बांध।"],["बार्गी परियोजना","नर्मदा","जबलपुर। इसे ''रानी अवंतीबाई सागर'' भी कहते हैं।"],["पेंच परियोजना","पेंच","छिंदवाड़ा और बालाघाट के लिए महत्वपूर्ण।"]]},{"type":"mnemonic","topic":"चंबल के बांध याद रखने की ट्रिक","trick":"G-R-J (गरज)","visual":"⚡","explanation":"**G**andhi Sagar (मंदसौर), **R**ana Pratap (चित्तौड़गढ़), **J**awahar Sagar (कोटा)।"},{"type":"highlight","level":"critical","text":"केन-बेतवा लिंक: यह भारत की पहली नदी जोड़ो परियोजना है, जिससे छतरपुर, पन्ना और टीकमगढ़ जिलों को लाभ मिलेगा।","icon":"🔗"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश में सर्वाधिक सिंचाई किस साधन द्वारा की जाती है?","options":["नहरें","तालाब","कुएं एवं नलकूप","अन्य"],"correct":"कुएं एवं नलकूप","strategy":"आंकड़ों के अनुसार 65% से अधिक सिंचाई भूमिगत जल (Wells/Tubewells) से होती है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"''बाणसागर परियोजना'' किन राज्यों की संयुक्त परियोजना है?","options":["म.प्र. और उ.प्र.","म.प्र. और राजस्थान","म.प्र., उ.प्र. और बिहार","म.प्र. और महाराष्ट्र"],"correct":"म.प्र., उ.प्र. और बिहार","strategy":"सोन नदी पर स्थित यह प्रोजेक्ट 2:1:1 के अनुपात में है।"},{"type":"exam_pattern","topic":"MP Agri & Irrigation Trend","analysis":"Unit 4 Analysis:","stats":["फसल और जिले: 1-2 प्रश्न","सिंचाई परियोजना (स्थान): 1 प्रश्न","नदी जोड़ो/नवीनतम डेटा: 1 प्रश्न"],"trend":"आयोग अब ''चिन्नौर चावल'' जैसे विशिष्ट GI टैग्स और सिंचाई के नवीन आंकड़ों पर फोकस कर रहा है।"}],"en":[{"type":"h2","text":"Unit 4: Agriculture and Irrigation System of Madhya Pradesh"},{"type":"p","text":"Madhya Pradesh is an agrarian state that has been repeatedly awarded the ''Krishi Karman Award'' for its excellence in productivity. The state''s economy is anchored in the primary sector, where the development of irrigation is considered the backbone of agriculture."},{"type":"h2","text":"1. Major Crops of Madhya Pradesh"},{"type":"p","text":"While MP is famously known as the ''Soya State'', its crop diversity is vast. Different crop belts exist across the state, from Malwa to Baghelkhand."},{"type":"image_tag","content":""},{"type":"table","instruction":"Major Crops and Their Regions","head":["Crop","Leading Districts","Key Fact"],"body":[["Soybean","Ujjain, Dhar, Indore, Sehore","MP is the leading producer in India. Also called ''Yellow Gold''."],["Wheat","Hoshangabad, Sehore, Vidisha","Highest production in Hoshangabad. Malwa is the ''Wheat Basket''."],["Paddy (Rice)","Balaghat, Mandla, Seoni","The ''Chinnor Rice'' of Balaghat holds a GI Tag."],["Cotton","Khargone, Khandwa, Barwani","Known as ''White Gold''. Nimar region is the cotton hub."],["Maize","Chhindwara, Dhar, Jhabua","Chhindwara is designated as the ''Corn City''."],["Mustard","Morena, Bhind, Sheopur","Central India Plateau is known as the ''Mustard Bowl''."]]},{"type":"highlight","level":"important","text":"Shree Anna (Millets): 2023 was the International Year of Millets. Kodo-Kutki (Dindori/Mandla) are key millets in MP.","icon":"🌾"},{"type":"h2","text":"2. Water Resources and Irrigation"},{"type":"p","text":"Irrigation methods vary across the state. Wells are dominant in the West, while canals are crucial in the North."},{"type":"table","instruction":"Sources of Irrigation: Comparative Study","head":["Source","Percentage (%)","Benefitted Region"],"body":[["Wells & Tubewells","67.0%","Malwa Region (Indore, Ujjain, Mandsaur)"],["Canals","18.0%","Chambal and Narmada Valley regions"],["Tanks","3.0%","Balaghat and Seoni districts"],["Other Sources","12.0%","Rivers and small streams"]]},{"type":"h2","text":"3. Major Irrigation Projects"},{"type":"p","text":"Irrigation in MP is categorized based on the Narmada Valley Development and other major river basins."},{"type":"image_tag","content":""},{"type":"table","instruction":"Important Dams and Projects","head":["Project","River","Location/Fact"],"body":[["Chambal Valley Project","Chambal","First project (1953). Gandhi Sagar, Rana Pratap, Jawahar Sagar."],["Bansagar Project","Son","Shahdol (Deolond). Joint project of MP, UP, and Bihar."],["Rani Laxmibai (Rajghat)","Betwa","Ashoknagar/Lalitpur. Shared project of MP and UP."],["Tawa Project","Tawa","Hoshangabad. Longest earthen dam in MP."],["Bargi Project","Narmada","Jabalpur. Also known as ''Rani Avantibai Sagar''."],["Pench Project","Pench","Vital for Chhindwara and Balaghat districts."]]},{"type":"mnemonic","topic":"Trick to remember Chambal Dams","trick":"G-R-J (Garaj)","visual":"⚡","explanation":"**G**andhi Sagar (Mandsaur), **R**ana Pratap (Chittorgarh), **J**awahar Sagar (Kota)."},{"type":"highlight","level":"critical","text":"Ken-Betwa Link: India''s first river-linking project, benefitting Chhatarpur, Panna, and Tikamgarh districts.","icon":"🔗"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"By which source is maximum irrigation done in Madhya Pradesh?","options":["Canals","Tanks","Wells and Tubewells","Others"],"correct":"Wells and Tubewells","strategy":"According to data, over 65% of irrigation relies on groundwater (Wells/Tubewells)."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"''Bansagar Project'' is a joint project of which states?","options":["MP and UP","MP and Rajasthan","MP, UP, and Bihar","MP and Maharashtra"],"correct":"MP, UP, and Bihar","strategy":"Located on the Son river, this project is shared in a 2:1:1 ratio."},{"type":"exam_pattern","topic":"MP Agri & Irrigation Trend","analysis":"Unit 4 Analysis:","stats":["Crops & Districts: 1-2 questions","Irrigation Projects (Location): 1 question","River Linking/Recent Data: 1 question"],"trend":"The Commission is now focusing on specific GI tags like ''Chinnor Rice'' and updated irrigation statistics."}]}', 'geography', NULL, 30, 1, 1770916864, 1770916864, 'blog', 'unit_4', 'Major Crops, Water Resources, Irrigation and Irrigation Projects', 1, 0, 0, 1, 0, 'Unit 4: मध्य प्रदेश की कृषि और सिंचाई व्यवस्था मध्य प्रदेश एक कृषि प्रधान राज्य है, जिसे अपनी उत्कृष्ट कृषि उत्पादकता के लिए लगातार ''कृषि कर्मण पुरस्कार'' से नवाजा गया है। राज्य की अर्थव्यवस्था प्राथमि...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('5dfd5b36-e042-42df-bc30-ec5cd50df5e1', 'energy-resources-madhya-pradesh-unit-4-mppsc', 'Energy Resources of MP: Conventional & Non-Conventional | म.प्र. के ऊर्जा संसाधन', 'Exhaustive guide to the power sector of Madhya Pradesh for Unit 4. Covers Thermal and Hydro power (Conventional) alongside Solar, Wind, and Biomass (Non-Conventional) with focus on key projects.', '{"hi":[{"type":"h2","text":"Unit 4: मध्य प्रदेश के ऊर्जा संसाधन (पारंपरिक एवं गैर-पारंपरिक)"},{"type":"p","text":"मध्य प्रदेश ऊर्जा के मामले में एक ''सरप्लस'' राज्य है। राज्य में तापीय ऊर्जा (Thermal) का दबदबा है, लेकिन हाल के वर्षों में नर्मदा पट्टी और मालवा के पठार पर सौर एवं पवन ऊर्जा का तेजी से विकास हुआ है। MPPSC में ताप विद्युत केंद्रों (Thermal Plants) की स्थापना वर्ष और जिलों पर प्रश्न बार-बार पूछे जाते हैं।"},{"type":"h2","text":"1. पारंपरिक ऊर्जा स्रोत (Conventional Sources)"},{"type":"p","text":"मध्य प्रदेश की कुल स्थापित क्षमता में सर्वाधिक हिस्सा ''ताप विद्युत'' (Thermal Power) का है, जो मुख्य रूप से कोयले पर आधारित है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"प्रमुख ताप विद्युत केंद्र (Thermal Power Stations)","head":["केंद्र का नाम","स्थान (जिला)","विशेष तथ्य"],"body":[["चांदनी ताप विद्युत गृह","नेपानगर (बुरहानपुर)","राज्य का पहला ताप विद्युत केंद्र (1953)।"],["अमरकंटक ताप विद्युत गृह","चचाई (अनूपपुर)","यह कोयला सुहागपुर क्षेत्र से प्राप्त करता है।"],["सतपुड़ा ताप विद्युत गृह","सारणी (बैतूल)","म.प्र. और राजस्थान की संयुक्त परियोजना।"],["विंध्याचल ताप विद्युत गृह","बैढ़न (सिंगरौली)","म.प्र. का सबसे बड़ा ताप विद्युत केंद्र (NTPC)।"],["संजय गांधी ताप विद्युत गृह","बिरसिंहपुर (उमरिया)","जोहिला कोयला क्षेत्र से कोयला प्राप्त करता है।"],["दादा धूनीवाले ताप विद्युत","खंडवा","यह एक प्रस्तावित बड़ा प्रोजेक्ट है।"]]},{"type":"h3","text":"जल विद्युत केंद्र (Hydro-electric Projects)"},{"type":"ul","items":["**गांधी सागर (मंदसौर):** राज्य की पहली जल विद्युत परियोजना (1960)। क्षमता: 115 MW।","**राणा प्रताप सागर:** 172 MW (चंबल नदी)।","**जवाहर सागर:** 99 MW (चंबल नदी)।","**इन्दिरा सागर (खंडवा):** 1000 MW (नर्मदा नदी) - राज्य की सबसे बड़ी जल विद्युत परियोजना।","**बाणसागर (शहडोल):** सोन नदी पर स्थित महत्वपूर्ण परियोजना।"]},{"type":"h2","text":"2. गैर-पारंपरिक ऊर्जा स्रोत (Non-Conventional/Renewable)"},{"type":"p","text":"पर्यावरण संरक्षण और ''नेट जीरो'' लक्ष्य की ओर बढ़ते हुए, मध्य प्रदेश अब सौर और पवन ऊर्जा का केंद्र बन रहा है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"अक्षय ऊर्जा परियोजनाएं","head":["स्रोत","प्रमुख परियोजना/स्थान","विवरण"],"body":[["सौर ऊर्जा (Solar)","रीवा अल्ट्रा मेगा सोलर","750 MW क्षमता। इसकी बिजली दिल्ली मेट्रो को दी जाती है।"],["सौर ऊर्जा (Solar)","ओंकारेश्वर (खंडवा)","विश्व का सबसे बड़ा ''फ्लोटिंग'' (तैरता हुआ) सोलर प्लांट।"],["पवन ऊर्जा (Wind)","जामगोदरानी (देवास)","राज्य का पहला पवन ऊर्जा फार्म। सर्वाधिक पवन चक्कियाँ इंदौर/देवास में हैं।"],["बायोमास (Biomass)","कसई गाँव (बैतूल)","लकड़ी के कचरे से बिजली बनाने वाला राज्य का पहला संयंत्र।"],["बायो-गैस (Bio-gas)","इंदौर","एशिया का सबसे बड़ा ''बायो-सीएनजी'' (Bio-CNG) प्लांट (गोवर्धन प्लांट)।"]]},{"type":"highlight","level":"important","text":"सांची (Sanchi): मध्य प्रदेश की पहली ''सोलर सिटी'' (Solar City) के रूप में विकसित की गई है।","icon":"☀️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश के किस जिले में ''विंध्याचल ताप विद्युत केंद्र'' स्थित है?","options":["शहडोल","सिंगरौली","अनूपपुर","उमरिया"],"correct":"सिंगरौली","strategy":"सिंगरौली के ''बैढ़न'' को ऊर्जा राजधानी कहा जाता है क्योंकि विंध्याचल केंद्र यहीं है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"मध्य प्रदेश की पहली जल विद्युत परियोजना कौन सी थी?","options":["चंबल घाटी (गांधी सागर)","बाणसागर","तवा","पेंच"],"correct":"चंबल घाटी (गांधी सागर)","strategy":"गांधी सागर बांध (1960) राज्य का पहला जल विद्युत केंद्र था।"},{"type":"exam_pattern","topic":"MP Energy Trend","analysis":"Unit 4 Energy Analysis:","stats":["ताप विद्युत केंद्र (स्थान): 1 प्रश्न","नवीनतम सौर परियोजनाएं: 1 प्रश्न","परियोजनाओं की क्षमता (MW): 1 प्रश्न"],"trend":"आयोग अब ''ग्रीन हाइड्रोजन'' और ''तैरते हुए सौर ऊर्जा संयंत्रों'' (Floating Solar) जैसे आधुनिक विषयों पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 4: Energy Resources of MP (Conventional & Non-Conventional)"},{"type":"p","text":"Madhya Pradesh is an energy-surplus state in India. While Thermal power remains the dominant source, recent years have seen a surge in Solar and Wind energy along the Narmada belt and Malwa plateau. In MPPSC, questions frequently appear on the districts and establishment years of Thermal plants."},{"type":"h2","text":"1. Conventional Energy Sources"},{"type":"p","text":"Thermal power, primarily coal-based, accounts for the largest share of the total installed capacity in Madhya Pradesh."},{"type":"image_tag","content":""},{"type":"table","instruction":"Major Thermal Power Stations","head":["Plant Name","Location (District)","Key Fact"],"body":[["Chandni Thermal Plant","Nepanagar (Burhanpur)","First thermal power plant of the state (1953)."],["Amarkantak Thermal","Chachai (Anuppur)","Receives coal from the Sohagpur coal belt."],["Satpura Thermal","Sarni (Betul)","A joint project of MP and Rajasthan."],["Vindhyachal Thermal","Waidhan (Singrauli)","Largest thermal power station in MP (NTPC)."],["Sanjay Gandhi Thermal","Birsinghpur (Umaria)","Gets coal from the Johilla coal mine area."],["Dada Dhuniwale Thermal","Khandwa","A major proposed thermal project."]]},{"type":"h3","text":"Hydro-electric Projects"},{"type":"ul","items":["**Gandhi Sagar (Mandsaur):** First hydro project of the state (1960). Capacity: 115 MW.","**Rana Pratap Sagar:** 172 MW (Chambal River).","**Jawahar Sagar:** 99 MW (Chambal River).","**Indira Sagar (Khandwa):** 1000 MW (Narmada River) - Largest hydro project in MP.","**Bansagar (Shahdol):** Significant project located on the Son river."]},{"type":"h2","text":"2. Non-Conventional Energy Sources"},{"type":"p","text":"Moving towards environment protection and ''Net Zero'' targets, Madhya Pradesh is becoming a hub for Solar and Wind energy."},{"type":"image_tag","content":""},{"type":"table","instruction":"Renewable Energy Projects","head":["Source","Major Project/Place","Description"],"body":[["Solar Power","Rewa Ultra Mega Solar","750 MW capacity. Provides electricity to Delhi Metro."],["Solar Power","Omkareshwar (Khandwa)","World''s largest ''floating'' solar power plant."],["Wind Power","Jamgodrani (Dewas)","First wind farm of the state. Most windmills in Indore/Dewas."],["Biomass","Kasai Village (Betul)","First plant in the state to generate power from wood waste."],["Bio-gas","Indore","Asia''s largest ''Bio-CNG'' plant (Gobar-Dhan plant)."]]},{"type":"highlight","level":"important","text":"Sanchi: Developed as the first ''Solar City'' of Madhya Pradesh.","icon":"☀️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"In which district of MP is the ''Vindhyachal Thermal Power Station'' located?","options":["Shahdol","Singrauli","Anuppur","Umaria"],"correct":"Singrauli","strategy":"Waidhan in Singrauli is called the Energy Capital due to this plant."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which was the first hydro-electric project of Madhya Pradesh?","options":["Chambal Valley (Gandhi Sagar)","Bansagar","Tawa","Pench"],"correct":"Chambal Valley (Gandhi Sagar)","strategy":"Gandhi Sagar Dam (1960) was the first hydro station of the state."},{"type":"exam_pattern","topic":"MP Energy Trend","analysis":"Unit 4 Energy Analysis:","stats":["Thermal Power Stations (Location): 1 question","Latest Solar Projects: 1 question","Project Capacities (MW): 1 question"],"trend":"The Commission is now focusing on modern topics like ''Green Hydrogen'' and ''Floating Solar Plants'' (e.g., Omkareshwar)."}]}', 'geography', NULL, 25, 1, 1770917090, 1770917090, 'blog', 'unit_4', 'Conventional and Non-Conventional sources of energy', 1, 0, 0, 1, 0, 'Unit 4: मध्य प्रदेश के ऊर्जा संसाधन (पारंपरिक एवं गैर-पारंपरिक) मध्य प्रदेश ऊर्जा के मामले में एक ''सरप्लस'' राज्य है। राज्य में तापीय ऊर्जा (Thermal) का दबदबा है, लेकिन हाल के वर्षों में नर्मदा पट्टी औ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('54707725-0ef8-4e7f-a16d-ae4c40afba3c', 'major-industries-madhya-pradesh-unit-4-mppsc', 'Major Industries of Madhya Pradesh | मध्य प्रदेश के प्रमुख उद्योग', 'A comprehensive guide to the industrial landscape of MP for Unit 4. Covers Agro-based, Forest-based, and Mineral-based industries along with major industrial zones and PSUs.', '{"hi":[{"type":"h2","text":"Unit 4: मध्य प्रदेश के प्रमुख उद्योग (Industrial Landscape)"},{"type":"p","text":"मध्य प्रदेश खनिज और कृषि संसाधनों में समृद्ध है, जो यहाँ के औद्योगिक विकास का आधार हैं। राज्य में ''पीथमपुर'' को भारत का डेट्रायट कहा जाता है। MPPSC में उद्योगों के स्थान, उनकी स्थापना और केंद्र सरकार के उपक्रमों (PSUs) पर प्रश्न अनिवार्य रूप से पूछे जाते हैं।"},{"type":"h2","text":"1. कृषि आधारित उद्योग (Agro-based Industries)"},{"type":"p","text":"म.प्र. एक कृषि प्रधान राज्य है, इसलिए यहाँ चीनी, सूती वस्त्र और सोयाबीन उद्योग का व्यापक विस्तार है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"प्रमुख कृषि उद्योग","head":["उद्योग","प्रमुख केंद्र/जिला","विशेष तथ्य"],"body":[["चीनी उद्योग (Sugar)","बरलाई (देवास), जावरा (रतलाम)","जावरा चीनी मिल (1934) राज्य की पहली मिल थी।"],["सूती वस्त्र (Cotton)","इंदौर, उज्जैन, बुरहानपुर","इंदौर को ''म.प्र. का मैनचेस्टर'' कहा जाता है।"],["सोयाबीन उद्योग","उज्जैन, सिवनी","एशिया का सबसे बड़ा सोयाबीन संयंत्र उज्जैन में स्थित है।"],["रेशम उद्योग (Silk)","सिवनी","सिवनी को ''म.प्र. का लखनऊ'' कहा जाता है (टसर रेशम के लिए)।"]]},{"type":"h2","text":"2. वन आधारित उद्योग (Forest-based Industries)"},{"type":"table","instruction":"प्रमुख वन उद्योग","head":["उद्योग","स्थान","विशेष विवरण"],"body":[["न्यूजप्रिंट पेपर मिल","नेपानगर (बुरहानपुर)","अखबारी कागज का कारखाना (1948-49)।"],["ओरिएंट पेपर मिल","अमलई (अनूपपुर)","यह एक निजी क्षेत्र का बड़ा पेपर कारखाना है।"],["सिक्का और नोट पेपर","होशंगाबाद (नर्मदापुरम)","यहाँ करेंसी नोट का पेपर (Security Paper Mill) बनता है।"],["कत्था उद्योग","बानमोर (मुरैना), शिवपुरी","खैर की लकड़ी से कत्था बनाया जाता है।"],["लाख उद्योग","उमरिया","यहाँ सरकारी लाख का कारखाना स्थित है।"]]},{"type":"h2","text":"3. खनिज एवं अन्य उद्योग (Mineral & Others)"},{"type":"ul","items":["**सीमेंट उद्योग:** म.प्र. का पहला सीमेंट कारखाना बानमोर (मुरैना) में 1922 में खुला। वर्तमान में सतना और कटनी प्रमुख केंद्र हैं।","**उर्वरक संयंत्र (Fertilizer):** विजयपुर (गुना)। यह ''गेल'' (GAIL) के सहयोग से संचालित है।","**BHEL:** भोपाल। ब्रिटेन के सहयोग से 1964 में स्थापित (महारत्न कंपनी)।","**ऑर्डनेंस फैक्ट्री:** जबलपुर (खमरिया)। यहाँ रक्षा उपकरण बनाए जाते हैं।"]},{"type":"h2","text":"4. प्रमुख औद्योगिक केंद्र (Industrial Hubs)"},{"type":"table","instruction":"औद्योगिक केंद्र और उनकी पहचान","head":["औद्योगिक केंद्र","जिला","प्रसिद्धि/नाम"],"body":[["पीथमपुर","धार","भारत का डेट्रायट (ऑटोमोबाइल हब)।"],["मंडीदीप","रायसेन","ऑप्टिकल फाइबर कारखाना (जापान के सहयोग से)।"],["मालनपुर","भिंड","ग्वालियर क्षेत्र का प्रमुख औद्योगिक केंद्र।"],["पिलुखेड़ी","राजगढ़","सूखा बंदरगाह (Dry Port) के लिए चर्चित।"],["मेघनगर","झाबुआ","आदिवासी क्षेत्र का प्रमुख औद्योगिक केंद्र।"]]},{"type":"highlight","level":"critical","text":"विशेष तथ्य: मध्य प्रदेश का पहला ''ड्राय पोर्ट'' (Dry Port) पीथमपुर (धार) में स्थापित किया गया था।","icon":"📦"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"मध्य प्रदेश में ''ऑप्टिकल फाइबर'' का कारखाना कहाँ स्थित है?","options":["इंदौर","भोपाल","मंडीदीप","पीथमपुर"],"correct":"मंडीदीप","strategy":"मंडीदीप रायसेन जिले में है और जापान के सहयोग से यहाँ कारखाना बना है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"''भारत का डेट्रायट'' किसे कहा जाता है?","options":["पीथमपुर","मंडीदीप","मलेरकोटला","बेंगलुरु"],"correct":"पीथमपुर","strategy":"ऑटोमोबाइल उद्योग की अधिकता के कारण धार जिले के पीथमपुर को यह नाम मिला है।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"BHEL मध्य प्रदेश में कहाँ स्थित है?","options":["जबलपुर","इंदौर","ग्वालियर","भोपाल"],"correct":"भोपाल","strategy":"Bharat Heavy Electricals Limited भोपाल में है।"},{"type":"exam_pattern","topic":"MP Industries Trend","analysis":"Unit 4 Analysis:","stats":["औद्योगिक केंद्र (Matching): 2 प्रश्न","PSUs/सरकारी कारखाने: 1 प्रश्न","प्रथम उद्योग (First Industry): 1 प्रश्न"],"trend":"आयोग अब उद्योगों के ''विदेशी सहयोग'' (जैसे- जापान या ब्रिटेन) और नवीनतम ''औद्योगिक गलियारों'' पर ध्यान दे रहा है।"}],"en":[{"type":"h2","text":"Unit 4: Major Industries of Madhya Pradesh"},{"type":"p","text":"Madhya Pradesh is rich in minerals and agricultural resources, which form the base of its industrial growth. Pithampur is known as the ''Detroit of India''. In MPPSC, questions are mandatory on industrial locations, establishment years, and Central PSUs."},{"type":"h2","text":"1. Agro-based Industries"},{"type":"p","text":"Since MP is an agrarian state, sugar, cotton textile, and soybean industries have an extensive presence."},{"type":"image_tag","content":""},{"type":"table","instruction":"Major Agro Industries","head":["Industry","Major Hub/District","Key Fact"],"body":[["Sugar Industry","Barali (Dewas), Jaora (Ratlam)","Jaora Sugar Mill (1934) was the first in the state."],["Cotton Textile","Indore, Ujjain, Burhanpur","Indore is called the ''Manchester of MP''."],["Soybean Industry","Ujjain, Seoni","Asia''s largest soybean plant is located in Ujjain."],["Silk Industry","Seoni","Seoni is called ''Lucknow of MP'' for its Tussar silk."]]},{"type":"h2","text":"2. Forest-based Industries"},{"type":"table","instruction":"Major Forest Industries","head":["Industry","Location","Description"],"body":[["Newsprint Paper Mill","Nepanagar (Burhanpur)","Newsprint paper factory (Est. 1948-49)."],["Orient Paper Mill","Amlai (Anuppur)","A major private sector paper factory."],["Currency Note Paper","Hoshangabad","Security Paper Mill produces currency paper."],["Kattha Industry","Banmore (Morena), Shivpuri","Produced from Khair wood."],["Lac Industry","Umaria","A government-owned lac factory is located here."]]},{"type":"h2","text":"3. Mineral & Other Industries"},{"type":"ul","items":["**Cement Industry:** First cement factory opened in Banmore (Morena) in 1922. Currently, Satna and Katni are hubs.","**Fertilizer Plant:** Vijaipur (Guna). Operated in collaboration with GAIL.","**BHEL:** Bhopal. Established in 1964 with UK collaboration (Maharatna company).","**Ordnance Factory:** Jabalpur (Khamaria). Famous for defense equipment manufacturing."]},{"type":"h2","text":"4. Major Industrial Centers"},{"type":"table","instruction":"Industrial Centers and Identity","head":["Industrial Hub","District","Identity/Nickname"],"body":[["Pithampur","Dhar","Detroit of India (Automobile hub)."],["Mandideep","Raisen","Optical fiber factory (Japan collaboration)."],["Malanpur","Bhind","Major industrial center of the Gwalior region."],["Pilukhedi","Rajgarh","Notable for the Dry Port project."],["Meghnagar","Jhabua","Primary industrial center in the tribal region."]]},{"type":"highlight","level":"critical","text":"Key Fact: The first ''Dry Port'' of Madhya Pradesh was established in Pithampur (Dhar).","icon":"📦"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Where is the ''Optical Fiber'' factory located in Madhya Pradesh?","options":["Indore","Bhopal","Mandideep","Pithampur"],"correct":"Mandideep","strategy":"Mandideep is in Raisen district, established with Japanese help."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which place is known as the ''Detroit of India''?","options":["Pithampur","Mandideep","Malerkotla","Bengaluru"],"correct":"Pithampur","strategy":"Pithampur (Dhar) got this name due to its high density of automobile industries."},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"Where is BHEL located in Madhya Pradesh?","options":["Jabalpur","Indore","Gwalior","Bhopal"],"correct":"Bhopal","strategy":"Bharat Heavy Electricals Limited is situated in Bhopal."},{"type":"exam_pattern","topic":"MP Industries Trend","analysis":"Unit 4 Analysis:","stats":["Industrial Hubs (Matching): 2 questions","PSUs/Govt Factories: 1 question","First Industries: 1 question"],"trend":"The Commission is now focusing on ''Foreign Collaborations'' and new ''Industrial Corridors''."}]}', 'geography', NULL, 25, 1, 1770917312, 1770917312, 'blog', 'unit_4', 'Major Industries of Madhya Pradesh', 1, 0, 0, 1, 0, 'Unit 4: मध्य प्रदेश के प्रमुख उद्योग (Industrial Landscape) मध्य प्रदेश खनिज और कृषि संसाधनों में समृद्ध है, जो यहाँ के औद्योगिक विकास का आधार हैं। राज्य में ''पीथमपुर'' को भारत का डेट्रायट कहा जाता है।...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('e1d273ce-04e4-4681-8714-7c161612cbe7', 'population-demography-madhya-pradesh-unit-4-mppsc', 'Demography of Madhya Pradesh: Growth, Density & Urbanization | म.प्र. की जनसांख्यिकी', 'Comprehensive analysis of MP''s population based on Census 2011. Covers growth rates, density distribution, sex ratio, literacy, and urbanization trends for MPPSC Unit 4.', '{"hi":[{"type":"h2","text":"Unit 4: मध्य प्रदेश की जनसांख्यिकी (Demography)"},{"type":"p","text":"मध्य प्रदेश की जनसंख्या नीति और आंकड़े राज्य के सामाजिक-आर्थिक विकास को समझने के लिए अनिवार्य हैं। वर्तमान में हम 2011 की जनगणना के आंकड़ों का ही उपयोग करते हैं। MPPSC में सर्वाधिक और न्यूनतम आंकड़ों वाले शीर्ष 5 जिलों का क्रम (Order) अक्सर पूछा जाता है।"},{"type":"h2","text":"1. जनसंख्या वृद्धि और वितरण (Growth & Distribution)"},{"type":"p","text":"2011 की जनगणना के अनुसार मध्य प्रदेश की कुल जनसंख्या **7.26 करोड़** है, जो भारत की कुल जनसंख्या का **6%** है।"},{"type":"table","instruction":"जनसंख्या वितरण: शीर्ष जिले","head":["रैंक","सर्वाधिक जनसंख्या वाले जिले","न्यूनतम जनसंख्या वाले जिले"],"body":[["1","इंदौर (32.7 लाख)","हरदा (5.7 लाख)"],["2","जबलपुर","उमरिया"],["3","सागर","श्योपुर"],["4","भोपाल","डिंडोरी"]]},{"type":"highlight","level":"important","text":"दशकीय वृद्धि दर (Decadal Growth): मध्य प्रदेश की जनसंख्या वृद्धि दर 20.35% रही। सर्वाधिक वृद्धि इंदौर (32.9%) में और न्यूनतम अनूपपुर (12.3%) में दर्ज की गई।","icon":"📈"},{"type":"h2","text":"2. जनसंख्या घनत्व (Population Density)"},{"type":"p","text":"मध्य प्रदेश का औसत जनसंख्या घनत्व **236 व्यक्ति प्रति वर्ग किमी** है (भारत का 382 है)।"},{"type":"image_tag","content":""},{"type":"ul","items":["**सर्वाधिक घनत्व:** भोपाल (855), इंदौर (841)।","**न्यूनतम घनत्व:** डिंडोरी (94), श्योपुर (104)।"]},{"type":"h2","text":"3. लिंगानुपात और साक्षरता (Sex Ratio & Literacy)"},{"type":"table","instruction":"प्रमुख जनसांख्यिकीय संकेतक","head":["संकेतक (Indicator)","म.प्र. औसत","शीर्ष जिला","न्यूनतम जिला"],"body":[["लिंगानुपात (Sex Ratio)","931","बालाघाट (1021)","भिंड (837)"],["शिशु लिंगानुपात","918","अलीराजपुर (978)","मुरैना (829)"],["कुल साक्षरता","69.3%","जबलपुर (81.1%)","अलीराजपुर (36.1%)"],["महिला साक्षरता","59.2%","भोपाल (74.9%)","अलीराजपुर (30.3%)"]]},{"type":"h2","text":"4. नगरीकरण (Urbanisation)"},{"type":"p","text":"मध्य प्रदेश में नगरीकरण की दर **27.6%** है, जबकि ग्रामीण जनसंख्या 72.4% है।"},{"type":"fact_card","title":"शहरीकरण के मुख्य तथ्य","facts":["सर्वाधिक नगरीकृत प्रतिशत वाला जिला: भोपाल (80.9%)।","सर्वाधिक नगरीकृत जनसंख्या वाला जिला: इंदौर।","न्यूनतम नगरीकृत प्रतिशत वाला जिला: डिंडोरी (4.6%)।","सबसे कम शहरी जनसंख्या: अलीराजपुर।"],"icon":"🏙️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"2011 की जनगणना के अनुसार, मध्य प्रदेश के किस जिले में सर्वाधिक लिंगानुपात है?","options":["मंडला","बालाघाट","धार","इंदौर"],"correct":"बालाघाट","strategy":"बालाघाट म.प्र. का एकमात्र जिला था जहाँ लिंगानुपात 1000 से ऊपर (1021) था।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"मध्य प्रदेश का जनसंख्या की दृष्टि से भारत में कौन सा स्थान है?","options":["चौथा","पांचवां","छठा","सातवां"],"correct":"छठा (2011 में)","strategy":"2011 की गणना के समय म.प्र. छठे स्थान पर था, तेलंगाना बनने के बाद यह अब पांचवें स्थान पर आ गया है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"मध्य प्रदेश में न्यूनतम जनसंख्या घनत्व वाला जिला कौन सा है?","options":["डिंडोरी","मंडला","भिंड","पन्ना"],"correct":"डिंडोरी","strategy":"डिंडोरी का घनत्व सबसे कम (94) है।"},{"type":"exam_pattern","topic":"MP Demography Trend","analysis":"Unit 4 Analysis:","stats":["लिंगानुपात/साक्षरता: 1 प्रश्न","सर्वाधिक/न्यूनतम जिले: 2 प्रश्न","शहरीकरण आंकड़े: 1 प्रश्न"],"trend":"आयोग अब ''शिशु लिंगानुपात'' (Child Sex Ratio) और अनुसूचित जाति/जनजाति की जनसंख्या के जिलेवार प्रतिशत पर अधिक ध्यान दे रहा है।"}],"en":[{"type":"h2","text":"Unit 4: Demography of Madhya Pradesh"},{"type":"p","text":"Population statistics are vital for understanding the socio-economic growth of the state. Currently, we rely on the 2011 Census data. In MPPSC, the ascending/descending order of the top 5 districts is a common theme."},{"type":"h2","text":"1. Population Growth and Distribution"},{"type":"p","text":"As per Census 2011, the total population of MP is **7.26 crore**, accounting for **6%** of India''s total population."},{"type":"table","instruction":"Population Distribution: Top Districts","head":["Rank","Most Populated Districts","Least Populated Districts"],"body":[["1","Indore (32.7 Lakhs)","Harda (5.7 Lakhs)"],["2","Jabalpur","Umaria"],["3","Sagar","Sheopur"],["4","Bhopal","Dindori"]]},{"type":"highlight","level":"important","text":"Decadal Growth: MP recorded a growth rate of 20.35%. Highest in Indore (32.9%) and lowest in Anuppur (12.3%).","icon":"📈"},{"type":"h2","text":"2. Population Density"},{"type":"p","text":"The average population density of MP is **236 persons per sq. km** (India''s average is 382)."},{"type":"image_tag","content":""},{"type":"ul","items":["**Highest Density:** Bhopal (855), Indore (841).","**Lowest Density:** Dindori (94), Sheopur (104)."]},{"type":"h2","text":"3. Sex Ratio and Literacy"},{"type":"table","instruction":"Major Demographic Indicators","head":["Indicator","MP Average","Top District","Bottom District"],"body":[["Sex Ratio","931","Balaghat (1021)","Bhind (837)"],["Child Sex Ratio","918","Alirajpur (978)","Morena (829)"],["Total Literacy","69.3%","Jabalpur (81.1%)","Alirajpur (36.1%)"],["Female Literacy","59.2%","Bhopal (74.9%)","Alirajpur (30.3%)"]]},{"type":"h2","text":"4. Urbanisation"},{"type":"p","text":"The urbanization rate in Madhya Pradesh is **27.6%**, while the rural population stands at 72.4%."},{"type":"fact_card","title":"Urbanisation Facts","facts":["Highest Urban percentage district: Bhopal (80.9%).","Highest Urban population district: Indore.","Lowest Urban percentage district: Dindori (4.6%).","Lowest Urban population district: Alirajpur."],"icon":"🏙️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"As per Census 2011, which district of MP has the highest sex ratio?","options":["Mandla","Balaghat","Dhar","Indore"],"correct":"Balaghat","strategy":"Balaghat was the only district in MP with a sex ratio above 1000 (1021)."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"Which district has the minimum population density in Madhya Pradesh?","options":["Dindori","Mandla","Bhind","Panna"],"correct":"Dindori","strategy":"Dindori has the lowest density at 94."}]}', 'geography', NULL, 22, 1, 1770917776, 1770917776, 'blog', 'unit_4', 'Population Growth, Distribution and Density, Urbanisation', 1, 0, 0, 1, 0, 'Unit 4: मध्य प्रदेश की जनसांख्यिकी (Demography) मध्य प्रदेश की जनसंख्या नीति और आंकड़े राज्य के सामाजिक-आर्थिक विकास को समझने के लिए अनिवार्य हैं। वर्तमान में हम 2011 की जनगणना के आंकड़ों का ही उपयोग ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('b3c56c19-459b-4ec9-ad33-c707551e7a45', 'constituent-assembly-india-mppsc-unit-5', 'Constituent Assembly of India | भारत की संविधान सभा', 'Comprehensive guide to the formation, composition, and committees of the Constituent Assembly. Includes MP''s representation and key milestones for MPPSC Unit 5.', '{"hi":[{"type":"h2","text":"Unit 5: भारत की संविधान सभा (Constituent Assembly)"},{"type":"p","text":"भारतीय संविधान का निर्माण एक ''संविधान सभा'' द्वारा किया गया था, जिसका गठन 1946 की **कैबिनेट मिशन योजना** (Cabinet Mission Plan) के तहत हुआ था। MPPSC में सभा की कार्यप्रणाली, प्रमुख समितियों और मध्य प्रदेश (तत्कालीन मध्य प्रांत एवं बरार) के सदस्यों पर विशेष ध्यान दिया जाता है।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. गठन और संरचना (Formation and Composition)"},{"type":"ul","items":["**कुल सदस्य:** प्रारंभ में 389 (विभाजन के बाद 299 रह गए)।","**चुनाव पद्धति:** आंशिक रूप से निर्वाचित और आंशिक रूप से नामांकित। चुनाव अप्रत्यक्ष (Indirect) थे।","**प्रतिनिधित्व:** प्रत्येक 10 लाख की जनसंख्या पर 1 सीट आवंटित की गई थी।"]},{"type":"table","instruction":"संविधान सभा की महत्वपूर्ण तिथियाँ","head":["तिथि (Date)","घटना (Event)","विवरण"],"body":[["9 दिसंबर 1946","प्रथम बैठक","डॉ. सच्चिदानंद सिन्हा को ''अस्थायी अध्यक्ष'' चुना गया।"],["11 दिसंबर 1946","अध्यक्ष का चुनाव","डॉ. राजेंद्र प्रसाद ''स्थायी अध्यक्ष'' चुने गए।"],["13 दिसंबर 1946","उद्देश्य प्रस्ताव","जवाहरलाल नेहरू द्वारा पेश (यही आगे चलकर ''प्रस्तावना'' बना)।"],["26 नवंबर 1949","संविधान अंगीकृत","संविधान पारित हुआ (संविधान दिवस)।"],["24 जनवरी 1950","अंतिम बैठक","राष्ट्रगान और राष्ट्रगीत को अपनाया गया।"]]},{"type":"h2","text":"2. प्रमुख समितियाँ (Major Committees)"},{"type":"p","text":"संविधान बनाने के लिए कई समितियों का गठन किया गया था, जिनमें ''प्रारूप समिति'' सबसे महत्वपूर्ण थी।"},{"type":"image_tag","content":""},{"type":"table","instruction":"समितियाँ और उनके अध्यक्ष","head":["समिति (Committee)","अध्यक्ष (Chairman)"],"body":[["प्रारूप समिति (Drafting Committee)","डॉ. बी.आर. अंबेडकर"],["संघ शक्ति समिति","जवाहरलाल नेहरू"],["प्रांतीय संविधान समिति","सरदार वल्लभभाई पटेल"],["संचालन समिति (Steering Committee)","डॉ. राजेंद्र प्रसाद"],["तदर्थ झंडा समिति","डॉ. राजेंद्र प्रसाद"]]},{"type":"highlight","level":"important","text":"प्रारूप समिति: इसमें अध्यक्ष सहित कुल 7 सदस्य थे। इसका गठन 29 अगस्त 1947 को हुआ था।","icon":"✍️"},{"type":"h2","text":"3. मध्य प्रदेश का योगदान (Contribution of MP)"},{"type":"p","text":"तत्कालीन मध्य प्रांत एवं बरार (Central Provinces & Berar) और रियासतों से कई दिग्गजों ने सभा में प्रतिनिधित्व किया।"},{"type":"fact_card","title":"म.प्र. से प्रमुख सदस्य","facts":["डॉ. बी.आर. अंबेडकर: इनका जन्म महू (इंदौर) में हुआ था, हालांकि ये बंगाल से निर्वाचित हुए थे।","पंडित रविशंकर शुक्ल: मध्य प्रांत के प्रथम मुख्यमंत्री।","सेठ गोविंद दास: जबलपुर से प्रसिद्ध स्वतंत्रता सेनानी।","हरि सिंह गौर: सागर विश्वविद्यालय के संस्थापक और कानूनी विशेषज्ञ।","फ्रैंक एंथोनी: एंग्लो-इंडियन समुदाय का प्रतिनिधित्व किया (जबलपुर)।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"संविधान सभा की प्रथम बैठक की अध्यक्षता किसने की थी?","options":["डॉ. राजेंद्र प्रसाद","डॉ. सच्चिदानंद सिन्हा","जवाहरलाल नेहरू","बी.एन. राव"],"correct":"डॉ. सच्चिदानंद सिन्हा","strategy":"वे सभा के सबसे वरिष्ठ सदस्य थे, इसलिए उन्हें अस्थायी अध्यक्ष बनाया गया था।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"भारतीय संविधान को कब अंगीकृत (Adopt) किया गया था?","options":["26 जनवरी 1950","15 अगस्त 1947","26 नवंबर 1949","9 दिसंबर 1946"],"correct":"26 नवंबर 1949","strategy":"प्रस्तावना में स्पष्ट उल्लेख है - 26 नवंबर 1949 को ''एतद द्वारा इस संविधान को अंगीकृत, अधिनियमित और आत्मार्पित करते हैं''।"},{"type":"exam_pattern","topic":"Constituent Assembly Trend","analysis":"Unit 5 Analysis:","stats":["महत्वपूर्ण तिथियाँ: 1 प्रश्न","समितियाँ और अध्यक्ष: 1 प्रश्न","विशिष्ट सदस्य (MP): 1 प्रश्न"],"trend":"आयोग अब ''संवैधानिक सलाहकार'' (B.N. Rau) और सभा में महिला सदस्यों (कुल 15) की संख्या पर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 5: Constituent Assembly of India"},{"type":"p","text":"The Constitution of India was framed by a ''Constituent Assembly'', formed in 1946 under the **Cabinet Mission Plan**. In MPPSC, focus is placed on the assembly''s functioning, major committees, and members from Madhya Pradesh (then Central Provinces & Berar)."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Formation and Composition"},{"type":"ul","items":["**Total Members:** Initially 389 (reduced to 299 after partition).","**Election Method:** Partly elected and partly nominated. Elections were indirect.","**Representation:** 1 seat was allotted for every 1 million (10 lakh) population."]},{"type":"table","instruction":"Key Dates of the Constituent Assembly","head":["Date","Event","Description"],"body":[["9 Dec 1946","First Meeting","Dr. Sachchidananda Sinha was elected as ''Interim President''."],["11 Dec 1946","Election of President","Dr. Rajendra Prasad was elected as ''Permanent President''."],["13 Dec 1946","Objective Resolution","Moved by J.L. Nehru (it later became the ''Preamble'')."],["26 Nov 1949","Adoption of Constitution","The Constitution was passed (Constitution Day)."],["24 Jan 1950","Final Meeting","National Anthem and National Song were adopted."]]},{"type":"h2","text":"2. Major Committees"},{"type":"p","text":"Several committees were formed for drafting the constitution, with the ''Drafting Committee'' being the most crucial."},{"type":"image_tag","content":""},{"type":"table","instruction":"Committees and Their Chairmen","head":["Committee","Chairman"],"body":[["Drafting Committee","Dr. B.R. Ambedkar"],["Union Power Committee","Jawaharlal Nehru"],["Provincial Constitution Committee","Sardar Vallabhbhai Patel"],["Steering Committee","Dr. Rajendra Prasad"],["Ad-hoc Flag Committee","Dr. Rajendra Prasad"]]},{"type":"highlight","level":"important","text":"Drafting Committee: Consisted of 7 members including the Chairman. Formed on 29 August 1947.","icon":"✍️"},{"type":"h2","text":"3. Contribution of MP"},{"type":"p","text":"Several stalwarts from the then Central Provinces & Berar and princely states represented the region in the assembly."},{"type":"fact_card","title":"Key Members from MP","facts":["Dr. B.R. Ambedkar: Born in Mhow (Indore), though elected from Bengal.","Pt. Ravi Shankar Shukla: First Chief Minister of Central Provinces.","Seth Govind Das: Famous freedom fighter from Jabalpur.","Hari Singh Gour: Founder of Sagar University and legal expert.","Frank Anthony: Represented the Anglo-Indian community (Jabalpur)."],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Who presided over the first meeting of the Constituent Assembly?","options":["Dr. Rajendra Prasad","Dr. Sachchidananda Sinha","Jawaharlal Nehru","B.N. Rau"],"correct":"Dr. Sachchidananda Sinha","strategy":"He was the oldest member of the assembly, hence chosen as the temporary president."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"When was the Indian Constitution adopted?","options":["26 January 1950","15 August 1947","26 November 1949","9 December 1946"],"correct":"26 November 1949","strategy":"The Preamble clearly mentions the date of adoption as 26th Nov 1949."},{"type":"exam_pattern","topic":"Constituent Assembly Trend","analysis":"Unit 5 Analysis:","stats":["Important Dates: 1 question","Committees & Chairmen: 1 question","Specific Members (MP): 1 question"],"trend":"The Commission is now asking about the ''Constitutional Advisor'' (B.N. Rau) and the number of women members (total 15)."}]}', 'polity', NULL, 25, 1, 1770917964, 1771008885, 'blog', 'unit_5', 'Constituent Assembly', 0, 1, 1, 1, 0, 'Unit 5: भारत की संविधान सभा (Constituent Assembly) भारतीय संविधान का निर्माण एक ''संविधान सभा'' द्वारा किया गया था, जिसका गठन 1946 की **कैबिनेट मिशन योजना** (Cabinet Mission Plan) के तहत हुआ था। MPPSC म...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('6742892a-85f2-4350-bebf-a7eaeff729b2', 'federal-executive-president-parliament-unit-5', 'Federal Executive & Parliament | संघ की कार्यपालिका और संसद', 'Comprehensive guide to the Union Executive and the Indian Parliament for MPPSC Unit 5. Covers the President''s powers, Parliamentary procedures, and key Constitutional Articles.', '{"hi":[{"type":"h2","text":"Unit 5: संघ की कार्यपालिका और संसद (Federal Executive & Parliament)"},{"type":"p","text":"भारतीय संविधान के भाग V (अनुच्छेद 52-151) में संघ सरकार के अंगों का वर्णन है। कार्यपालिका (Executive) नीति लागू करती है और विधायिका (Legislature/Parliament) कानून बनाती है। MPPSC में राष्ट्रपति की शक्तियों और संसद की कार्यवाहियों (जैसे - शून्यकाल, प्रश्नकाल) पर प्रश्न अनिवार्य रूप से आते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. राष्ट्रपति (The President) - अनुच्छेद 52-62"},{"type":"p","text":"राष्ट्रपति भारत का ''प्रथम नागरिक'' और राज्य का संवैधानिक प्रमुख होता है।"},{"type":"table","instruction":"राष्ट्रपति से संबंधित महत्वपूर्ण अनुच्छेद","head":["अनुच्छेद (Article)","विषय (Subject)"],"body":[["अनुच्छेद 52","भारत का एक राष्ट्रपति होगा।"],["अनुच्छेद 54","राष्ट्रपति का निर्वाचन (निर्वाचक मंडल)।"],["अनुच्छेद 60","राष्ट्रपति द्वारा शपथ या प्रतिज्ञान।"],["अनुच्छेद 61","महाभियोग (Impeachment) की प्रक्रिया।"],["अनुच्छेद 72","क्षमादान की शक्ति (Pardoning Power)।"],["अनुच्छेद 123","अध्यादेश (Ordinance) जारी करने की शक्ति।"]]},{"type":"highlight","level":"critical","text":"निर्वाचन: राष्ट्रपति के चुनाव में संसद के दोनों सदनों के ''निर्वाचित'' सदस्य और राज्यों/UTs की विधानसभाओं के ''निर्वाचित'' सदस्य भाग लेते हैं। मनोनीत सदस्य वोट नहीं देते।","icon":"🗳️"},{"type":"h2","text":"2. भारतीय संसद (The Parliament) - अनुच्छेद 79-122"},{"type":"p","text":"अनुच्छेद 79 के अनुसार, संसद के तीन अंग हैं: राष्ट्रपति, राज्यसभा और लोकसभा।"},{"type":"image_tag","content":""},{"type":"table","instruction":"राज्यसभा बनाम लोकसभा","head":["विशेषता","राज्यसभा (अनुच्छेद 80)","लोकसभा (अनुच्छेद 81)"],"body":[["प्रकृति","स्थायी सदन (कभी भंग नहीं होता)।","अस्थायी सदन (5 वर्ष का कार्यकाल)।"],["अधिकतम सदस्य","250 (वर्तमान 245)।","550 (वर्तमान 543)।"],["न्यूनतम आयु","30 वर्ष।","25 वर्ष।"],["प्रमुख","उपराष्ट्रपति (पदेन सभापति)।","अध्यक्ष (Speaker)।"],["शक्ति","राज्यों का प्रतिनिधित्व।","जनता का सीधा प्रतिनिधित्व।"]]},{"type":"mnemonic","topic":"संसद की संरचना याद रखने की ट्रिक","trick":"स-र-ला (Sa-Ra-La)","visual":"📜","explanation":"**स** (संसद) - अनु. 79 | **र** (राज्यसभा) - अनु. 80 | **ला** (लोकसभा) - अनु. 81"},{"type":"h2","text":"3. संसदीय शब्दावली और प्रक्रियाएँ"},{"type":"fact_card","title":"महत्वपूर्ण शब्दावली","facts":["प्रश्नकाल (Question Hour): सदन की कार्यवाही का पहला घंटा (11-12 बजे)।","शून्यकाल (Zero Hour): प्रश्नकाल के ठीक बाद का समय (भारतीय नवाचार)।","अनुच्छेद 108: संयुक्त बैठक (Joint Sitting) - राष्ट्रपति द्वारा बुलाई जाती है, अध्यक्षता लोकसभा अध्यक्ष करता है।","धन विधेयक (Money Bill): केवल लोकसभा में पेश होता है (अनुच्छेद 110)।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भारतीय संविधान के किस अनुच्छेद के तहत राष्ट्रपति को ''क्षमादान'' की शक्ति प्राप्त है?","options":["अनुच्छेद 71","अनुच्छेद 72","अनुच्छेद 52","अनुच्छेद 61"],"correct":"अनुच्छेद 72","strategy":"अनुच्छेद 72 राष्ट्रपति की न्यायिक शक्ति है, जबकि 61 महाभियोग है।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"संसद के दोनों सदनों की संयुक्त बैठक (Joint Sitting) की अध्यक्षता कौन करता है?","options":["राष्ट्रपति","उपराष्ट्रपति","लोकसभा अध्यक्ष","प्रधानमंत्री"],"correct":"लोकसभा अध्यक्ष","strategy":"अनुच्छेद 108 के तहत बैठक राष्ट्रपति बुलाता है, लेकिन अध्यक्षता स्पीकर ही करता है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"राज्यसभा के पदेन सभापति कौन होते हैं?","options":["राष्ट्रपति","उपराष्ट्रपति","प्रधानमंत्री","विपक्ष के नेता"],"correct":"उपराष्ट्रपति","strategy":"अनुच्छेद 64 के अनुसार उपराष्ट्रपति राज्यसभा का पदेन (Ex-officio) सभापति होता है।"},{"type":"exam_pattern","topic":"Federal System Trend","analysis":"Unit 5 Analysis:","stats":["महत्वपूर्ण अनुच्छेद: 2 प्रश्न","राष्ट्रपति की शक्तियाँ: 1 प्रश्न","संसदीय समितियाँ/प्रक्रिया: 1 प्रश्न"],"trend":"आयोग अब ''अनुच्छेद'' के साथ-साथ संवैधानिक संशोधनों (जैसे - 104वां संशोधन) के माध्यम से आए बदलावों पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 5: Federal Executive and Parliament"},{"type":"p","text":"Part V (Articles 52-151) of the Indian Constitution describes the organs of the Union Government. The Executive implements policies, and the Legislature (Parliament) makes laws. In MPPSC, questions on President''s powers and Parliamentary proceedings (e.g., Zero Hour, Question Hour) are mandatory."},{"type":"image_tag","content":""},{"type":"h2","text":"1. The President - Articles 52-62"},{"type":"p","text":"The President is the ''First Citizen'' of India and the constitutional head of the State."},{"type":"table","instruction":"Important Articles Related to the President","head":["Article","Subject"],"body":[["Article 52","There shall be a President of India."],["Article 54","Election of the President (Electoral College)."],["Article 60","Oath or affirmation by the President."],["Article 61","Procedure for Impeachment."],["Article 72","Pardoning Power of the President."],["Article 123","Power to promulgate Ordinances."]]},{"type":"highlight","level":"critical","text":"Election: Only ''Elected'' members of both houses of Parliament and Legislative Assemblies of States/UTs participate. Nominated members do not vote.","icon":"🗳️"},{"type":"h2","text":"2. The Parliament - Articles 79-122"},{"type":"p","text":"As per Article 79, the Parliament consists of three parts: The President, Rajya Sabha, and Lok Sabha."},{"type":"image_tag","content":""},{"type":"table","instruction":"Rajya Sabha vs Lok Sabha","head":["Feature","Rajya Sabha (Art 80)","Lok Sabha (Art 81)"],"body":[["Nature","Permanent House (Never dissolves).","Temporary House (5-year term)."],["Max Members","250 (Present 245).","550 (Present 543)."],["Min Age","30 Years.","25 Years."],["Head","Vice-President (Ex-officio).","Speaker."],["Representation","Represents the States.","Represents the People directly."]]},{"type":"mnemonic","topic":"Trick to remember Parliament structure","trick":"Sa-Ra-La","visual":"📜","explanation":"**Sa** (Sansad) - Art 79 | **Ra** (Rajya Sabha) - Art 80 | **La** (Lok Sabha) - Art 81"},{"type":"h2","text":"3. Parliamentary Terms and Procedures"},{"type":"fact_card","title":"Key Terminologies","facts":["Question Hour: The first hour of a sitting (11 AM - 12 PM).","Zero Hour: Time immediately following Question Hour (Indian innovation).","Article 108: Joint Sitting - Summoned by the President, presided over by the Speaker.","Money Bill: Can only be introduced in Lok Sabha (Article 110)."],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Under which Article of the Constitution does the President have ''Pardoning'' power?","options":["Article 71","Article 72","Article 52","Article 61"],"correct":"Article 72","strategy":"Art 72 is the judicial power; Art 61 is for impeachment."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Who presides over the Joint Sitting of both houses of Parliament?","options":["President","Vice-President","Speaker of Lok Sabha","Prime Minister"],"correct":"Speaker of Lok Sabha","strategy":"Summoned by President under Art 108, but always presided over by the Speaker."},{"type":"exam_pattern","topic":"Federal System Trend","analysis":"Unit 5 Analysis:","stats":["Crucial Articles: 2 questions","Presidential Powers: 1 question","Parliamentary Committees: 1 question"],"trend":"The Commission is now focusing on changes brought by Constitutional Amendments (e.g., the 104th Amendment) alongside traditional Articles."}]}', 'polity', NULL, 30, 1, 1770918262, 1771008886, 'blog', 'unit_5', 'Federal Executive, President and Parliament', 1, 0, 1, 1, 0, 'Unit 5: संघ की कार्यपालिका और संसद (Federal Executive & Parliament) भारतीय संविधान के भाग V (अनुच्छेद 52-151) में संघ सरकार के अंगों का वर्णन है। कार्यपालिका (Executive) नीति लागू करती है और विधायिका ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('c8992f99-7f35-4bf9-92f1-36c5083dd17a', 'supreme-court-judicial-system-unit-5', 'Judicial System: Supreme Court & High Courts | न्यायपालिका: उच्चतम न्यायालय और उच्च न्यायालय', 'Comprehensive guide to the Indian Judiciary for MPPSC Unit 5. Covers Supreme Court powers, High Court structure, and the significance of Judicial Review and PIL.', '{"hi":[{"type":"h2","text":"Unit 5: भारतीय न्यायपालिका (Supreme Court and Judicial System)"},{"type":"p","text":"भारत में ''एकीकृत न्यायपालिका'' (Integrated Judiciary) की व्यवस्था है, जिसमें शीर्ष पर उच्चतम न्यायालय (Supreme Court) है। यह संविधान का संरक्षक (Guardian) और मौलिक अधिकारों का रक्षक है। MPPSC में सर्वोच्च न्यायालय के क्षेत्राधिकार और उच्च न्यायालयों के गठन पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. उच्चतम न्यायालय (Supreme Court) - अनुच्छेद 124-147"},{"type":"p","text":"उच्चतम न्यायालय का उद्घाटन 28 जनवरी 1950 को हुआ था। वर्तमान में इसमें 1 मुख्य न्यायाधीश और 33 अन्य न्यायाधीश (कुल 34) हैं।"},{"type":"table","instruction":"सुप्रीम कोर्ट से संबंधित महत्वपूर्ण अनुच्छेद","head":["अनुच्छेद (Article)","विषय (Subject)"],"body":[["अनुच्छेद 124","उच्चतम न्यायालय की स्थापना और गठन।"],["अनुच्छेद 129","अभिलेख न्यायालय (Court of Record) होना।"],["अनुच्छेद 131","मूल क्षेत्राधिकार (Original Jurisdiction)।"],["अनुच्छेद 137","न्यायिक पुनरावलोकन (Judicial Review)।"],["अनुच्छेद 143","राष्ट्रपति को सलाह देने की शक्ति (Advisory)।"]]},{"type":"highlight","level":"critical","text":"नियुक्ति: न्यायाधीशों की नियुक्ति राष्ट्रपति द्वारा ''कॉलेजियम प्रणाली'' (Collegium System) की सलाह पर की जाती है। शपथ भी राष्ट्रपति दिलाते हैं।","icon":"⚖️"},{"type":"h2","text":"2. उच्च न्यायालय (High Courts) - अनुच्छेद 214-231"},{"type":"p","text":"संविधान के अनुसार प्रत्येक राज्य के लिए एक उच्च न्यायालय होगा, लेकिन संसद दो या अधिक राज्यों के लिए एक ही उच्च न्यायालय बना सकती है (अनुच्छेद 231)।"},{"type":"ul","items":["**कुल संख्या:** भारत में वर्तमान में 25 उच्च न्यायालय हैं।","**रिट शक्ति (Writ Power):** अनुच्छेद 226 के तहत उच्च न्यायालय को मौलिक अधिकारों के लिए रिट जारी करने की शक्ति है (यह सुप्रीम कोर्ट के अनुच्छेद 32 से भी विस्तृत है)।","**म.प्र. उच्च न्यायालय:** मुख्य पीठ जबलपुर में है, खंडपीठ इंदौर और ग्वालियर में हैं।"]},{"type":"mnemonic","topic":"रिट के प्रकार याद रखने की ट्रिक","trick":"H-M-C-P-Q","visual":"📜","explanation":"1. **H**abeas Corpus (बंदी प्रत्यक्षीकरण)\n2. **M**andamus (परमादेश)\n3. **C**ertiorari (उत्प्रेषण)\n4. **P**rohibition (प्रतिषेध)\n5. **Q**uo-Warranto (अधिकार पृच्छा)"},{"type":"h2","text":"3. न्यायिक सक्रियता और जनहित याचिका (PIL)"},{"type":"fact_card","title":"महत्वपूर्ण अवधारणाएं","facts":["PIL (जनहित याचिका): भारत में पी.एन. भगवती को इसका जनक माना जाता है।","न्यायिक पुनरावलोकन: यह शक्ति न्यायपालिका को विधायिका द्वारा बनाए गए असंवैधानिक कानूनों को रद्द करने का अधिकार देती है।","लोक अदालत: त्वरित और सस्ते न्याय के लिए एक वैकल्पिक मंच।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"किस अनुच्छेद के तहत उच्चतम न्यायालय को ''अभिलेख न्यायालय'' (Court of Record) माना गया है?","options":["अनुच्छेद 124","अनुच्छेद 129","अनुच्छेद 131","अनुच्छेद 143"],"correct":"अनुच्छेद 129","strategy":"अनुच्छेद 129 कहता है कि सुप्रीम कोर्ट के फैसले साक्ष्य के रूप में रखे जाएंगे।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"मध्य प्रदेश उच्च न्यायालय की मुख्य पीठ (Main Bench) कहाँ स्थित है?","options":["भोपाल","जबलपुर","इंदौर","ग्वालियर"],"correct":"जबलपुर","strategy":"स्थापना 1956 में हुई, मुख्य पीठ जबलपुर में है।"},{"type":"pyq","exam":"MPPSC Prelims 2018","year":2018,"question":"उच्च न्यायालय के न्यायाधीशों की सेवानिवृत्ति की आयु क्या है?","options":["60 वर्ष","62 वर्ष","65 वर्ष","70 वर्ष"],"correct":"62 वर्ष","strategy":"सुप्रीम कोर्ट के लिए 65 वर्ष और हाई कोर्ट के लिए 62 वर्ष है।"},{"type":"exam_pattern","topic":"Judiciary Trend","analysis":"Unit 5 Analysis:","stats":["अनुच्छेद (Direct): 1 प्रश्न","रिट और क्षेत्राधिकार: 1 प्रश्न","म.प्र. उच्च न्यायालय तथ्य: 1 प्रश्न"],"trend":"आयोग अब न्यायाधीशों को हटाने की प्रक्रिया और कॉलेजियम से संबंधित विवादों (NJAC आदि) पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 5: The Indian Judiciary (Supreme Court and Judicial System)"},{"type":"p","text":"India has an ''Integrated Judiciary'' with the Supreme Court at the apex. It is the Guardian of the Constitution and the Protector of Fundamental Rights. In MPPSC, questions focus on SC jurisdiction and the structure of High Courts."},{"type":"image_tag","content":""},{"type":"h2","text":"1. The Supreme Court - Articles 124-147"},{"type":"p","text":"The Supreme Court was inaugurated on Jan 28, 1950. Currently, it has 1 Chief Justice and 33 other judges (Total 34)."},{"type":"table","instruction":"Important Articles Related to Supreme Court","head":["Article","Subject"],"body":[["Article 124","Establishment and Constitution of SC."],["Article 129","SC to be a Court of Record."],["Article 131","Original Jurisdiction of the SC."],["Article 137","Judicial Review power."],["Article 143","Power of President to consult SC (Advisory)."]]},{"type":"highlight","level":"critical","text":"Appointment: Judges are appointed by the President on the advice of the ''Collegium System''. The President also administers the oath.","icon":"⚖️"},{"type":"h2","text":"2. High Courts - Articles 214-231"},{"type":"p","text":"The Constitution provides for a High Court for each state, but Parliament can establish a common HC for two or more states (Art 231)."},{"type":"ul","items":["**Total Count:** There are 25 High Courts in India currently.","**Writ Power:** Under Art 226, HCs have the power to issue writs for Fundamental Rights (wider than SC''s Art 32 power).","**MP High Court:** Principal bench is in Jabalpur, with Benches in Indore and Gwalior."]},{"type":"mnemonic","topic":"Types of Writs Trick","trick":"H-M-C-P-Q","visual":"📜","explanation":"1. **H**abeas Corpus\n2. **M**andamus\n3. **C**ertiorari\n4. **P**rohibition\n5. **Q**uo-Warranto"},{"type":"h2","text":"3. Judicial Activism and PIL"},{"type":"fact_card","title":"Key Concepts","facts":["PIL (Public Interest Litigation): Justice P.N. Bhagwati is known as the father of PIL in India.","Judicial Review: The power to strike down unconstitutional laws passed by the legislature.","Lok Adalat: An alternative forum for speedy and inexpensive justice."],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Under which Article is the Supreme Court considered a ''Court of Record''?","options":["Article 124","Article 129","Article 131","Article 143"],"correct":"Article 129","strategy":"Art 129 ensures SC decisions are preserved as evidence and testimony."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Where is the Principal Bench of the Madhya Pradesh High Court located?","options":["Bhopal","Jabalpur","Indore","Gwalior"],"correct":"Jabalpur","strategy":"Established in 1956, the main seat remains in Jabalpur."},{"type":"exam_pattern","topic":"Judiciary Trend","analysis":"Unit 5 Analysis:","stats":["Direct Articles: 1 question","Writs and Jurisdictions: 1 question","MP High Court facts: 1 question"],"trend":"The Commission is now focusing more on the removal process of judges and controversies surrounding the Collegium system."}]}', 'polity', NULL, 25, 1, 1770918485, 1771008887, 'blog', 'unit_5', 'Supreme Court and Judicial System', 1, 0, 1, 1, 0, 'Unit 5: भारतीय न्यायपालिका (Supreme Court and Judicial System) भारत में ''एकीकृत न्यायपालिका'' (Integrated Judiciary) की व्यवस्था है, जिसमें शीर्ष पर उच्चतम न्यायालय (Supreme Court) है। यह संविधान का सं...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('347d06e2-e82e-46b0-8e16-bda2e24bcead', 'constitutional-amendments-india-unit-5-mppsc', 'Constituent Amendments: Process and Major Acts | संविधान संशोधन: प्रक्रिया और प्रमुख अधिनियम', 'A detailed guide to Article 368 and the landmark constitutional amendments of India. Essential for MPPSC Unit 5, covering the 42nd, 44th, 73rd, 74th, and latest amendments.', '{"hi":[{"type":"h2","text":"Unit 5: संविधान संशोधन (Constitutional Amendments)"},{"type":"p","text":"भारतीय संविधान न तो बहुत लचीला है और न ही बहुत कठोर, बल्कि यह दोनों का समन्वय है। संविधान के **भाग XX** और **अनुच्छेद 368** में संशोधन की प्रक्रिया दी गई है। MPPSC में ऐतिहासिक संशोधनों (जैसे - 42वां, 44वां) और नवीनतम संशोधनों (जैसे - 101 से 106) पर प्रश्न अक्सर पूछे जाते हैं।"},{"type":"h2","text":"1. संशोधन की प्रक्रिया (Procedure of Amendment)"},{"type":"p","text":"अनुच्छेद 368 के तहत संशोधन की पहल केवल संसद के किसी भी सदन में विधेयक पेश करके की जा सकती है (राज्य विधानसभाओं में नहीं)।"},{"type":"table","instruction":"संशोधन के प्रकार","head":["प्रकार","विवरण","उदाहरण"],"body":[["साधारण बहुमत","सदन में उपस्थित और मतदान करने वाले 50% से अधिक।","नए राज्यों का गठन (अनु. 3)"],["विशेष बहुमत","सदन की कुल सदस्यता का बहुमत + 2/3 उपस्थित एवं मतदान।","मौलिक अधिकार, DPSP"],["विशेष बहुमत + राज्यों की सहमति","संसद का विशेष बहुमत + आधे राज्यों का साधारण बहुमत।","जीएसटी (GST), राष्ट्रपति का चुनाव"]]},{"type":"highlight","level":"critical","text":"नोट: संविधान संशोधन विधेयक पर दोनों सदनों के बीच गतिरोध होने पर ''संयुक्त बैठक'' (Joint Sitting) का प्रावधान नहीं है।","icon":"🚫"},{"type":"h2","text":"2. महत्वपूर्ण ऐतिहासिक संशोधन (Landmark Amendments)"},{"type":"table","instruction":"ऐतिहासिक संशोधन अधिनियम","head":["संशोधन","वर्ष","प्रमुख प्रावधान"],"body":[["7वां संशोधन","1956","राज्यों का पुनर्गठन (A, B, C, D श्रेणियों का अंत)।"],["42वां संशोधन","1976","इसे ''लघु संविधान'' कहते हैं। प्रस्तावना में ''समाजवादी, पंथनिरपेक्ष, अखंडता'' शब्द जोड़े गए।"],["44वां संशोधन","1978","संपत्ति के अधिकार को मौलिक अधिकार से हटाया।"],["52वां संशोधन","1985","दलबदल विरोधी कानून (10वीं अनुसूची)।"],["61वां संशोधन","1989","मतदान की आयु 21 से घटाकर 18 वर्ष की गई।"],["73वां एवं 74वां","1992","पंचायती राज और नगर निकायों को संवैधानिक दर्जा।"]]},{"type":"h2","text":"3. नवीनतम संशोधन (Latest Amendments)"},{"type":"fact_card","title":"हाल के प्रमुख बदलाव","facts":["101वां संशोधन (2016): वस्तु एवं सेवा कर (GST) लागू किया गया।","102वां संशोधन (2018): राष्ट्रीय पिछड़ा वर्ग आयोग (NCBC) को संवैधानिक दर्जा।","103वां संशोधन (2019): आर्थिक रूप से कमजोर वर्ग (EWS) को 10% आरक्षण।","104वां संशोधन (2020): SC/ST सीटों का विस्तार + एंग्लो-इंडियन सीटों का अंत।","106वां संशोधन (2023): नारी शक्ति वंदन अधिनियम (लोकसभा/विधानसभा में महिलाओं को 33% आरक्षण)।"],"icon":"🆕"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"किस संविधान संशोधन द्वारा ''नारी शक्ति वंदन अधिनियम'' (महिलाओं हेतु आरक्षण) पारित किया गया है?","options":["103वां","104वां","105वां","106वां"],"correct":"106वां","strategy":"यह वर्ष 2023 का सबसे चर्चित और नवीनतम संशोधन है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"61वें संविधान संशोधन का संबंध किससे है?","options":["दलबदल","पंचायती राज","मतदान की आयु","शिक्षा का अधिकार"],"correct":"मतदान की आयु","strategy":"61वें संशोधन (1989) ने युवाओं को 18 वर्ष की उम्र में वोट देने का अधिकार दिया।"},{"type":"exam_pattern","topic":"Amendment Trend","analysis":"Unit 5 Analysis:","stats":["नवीनतम संशोधन (101-106): 1-2 प्रश्न","ऐतिहासिक संशोधन (42nd/44th): 1 प्रश्न","संशोधन प्रक्रिया (Art 368): 1 प्रश्न"],"trend":"आयोग अब संशोधनों के ''वर्ष'' और विशिष्ट ''अनुच्छेद'' (जैसे - 103वें संशोधन से जुड़े अनु. 15(6) और 16(6)) पर गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 5: Constitutional Amendments"},{"type":"p","text":"The Indian Constitution is neither purely flexible nor purely rigid; it is a synthesis of both. **Part XX** and **Article 368** deal with the powers of Parliament to amend the Constitution. In MPPSC, questions frequently appear on landmark amendments (like 42nd, 44th) and the most recent ones (101 to 106)."},{"type":"h2","text":"1. Procedure of Amendment"},{"type":"p","text":"Under Article 368, an amendment can be initiated only by the introduction of a bill in either House of Parliament (not in state legislatures)."},{"type":"table","instruction":"Types of Amendments","head":["Type","Description","Example"],"body":[["Simple Majority","More than 50% of members present and voting.","Formation of new states (Art 3)"],["Special Majority","Majority of total membership + 2/3 members present and voting.","Fundamental Rights, DPSPs"],["Special Majority + Consent of States","Special majority of Parliament + Simple majority of half the states.","GST, Election of President"]]},{"type":"highlight","level":"critical","text":"Note: There is no provision for a ''Joint Sitting'' of both houses in case of a deadlock over a Constitutional Amendment Bill.","icon":"🚫"},{"type":"h2","text":"2. Landmark Historical Amendments"},{"type":"table","instruction":"Historical Amendment Acts","head":["Amendment","Year","Major Provisions"],"body":[["7th Amendment","1956","Reorganization of states (Ending A, B, C, D categories)."],["42nd Amendment","1976","Called ''Mini Constitution''. Added ''Socialist, Secular, Integrity'' to Preamble."],["44th Amendment","1978","Removed Right to Property from Fundamental Rights."],["52nd Amendment","1985","Anti-Defection Law (10th Schedule)."],["61st Amendment","1989","Voting age reduced from 21 to 18 years."],["73rd & 74th","1992","Constitutional status to Panchayats and Urban Local Bodies."]]},{"type":"h2","text":"3. Latest Amendments (101-106)"},{"type":"fact_card","title":"Recent Major Changes","facts":["101st Amendment (2016): Introduction of Goods and Services Tax (GST).","102nd Amendment (2018): Constitutional status to National Commission for Backward Classes (NCBC).","103rd Amendment (2019): 10% reservation for Economically Weaker Sections (EWS).","104th Amendment (2020): Extension of SC/ST seats + Ending Anglo-Indian nomination.","106th Amendment (2023): Nari Shakti Vandan Adhiniyam (33% women reservation in LS/LA)."],"icon":"🆕"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Through which Constitutional Amendment was the ''Nari Shakti Vandan Adhiniyam'' passed?","options":["103rd","104th","105th","106th"],"correct":"106th","strategy":"This is the most recent and significant amendment of 2023."},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"The 61st Constitutional Amendment is related to?","options":["Anti-defection","Panchayati Raj","Voting Age","Right to Education"],"correct":"Voting Age","strategy":"The 61st Amendment (1989) lowered the voting age to 18."},{"type":"exam_pattern","topic":"Amendment Trend","analysis":"Unit 5 Analysis:","stats":["Latest Amendments: 1-2 questions","Historical Landmark Acts: 1 question","Amendment Process (Art 368): 1 question"],"trend":"The Commission is now focusing on the exact ''Year'' and specific ''Articles'' affected (e.g., Art 15(6) & 16(6) from the 103rd Amendment)."}]}', 'polity', NULL, 25, 1, 1770918716, 1771008891, 'blog', 'unit_5', 'Constitutional Amendments', 1, 0, 1, 1, 0, 'Unit 5: संविधान संशोधन (Constitutional Amendments) भारतीय संविधान न तो बहुत लचीला है और न ही बहुत कठोर, बल्कि यह दोनों का समन्वय है। संविधान के **भाग XX** और **अनुच्छेद 368** में संशोधन की प्रक्रिया द...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('5a34904f-4210-4276-b6c0-426ab3da8e83', 'fundamental-rights-dpsp-duties-unit-5-mppsc', 'Fundamental Rights, Duties & DPSP | मौलिक अधिकार, कर्तव्य और नीति निदेशक तत्व', 'A comprehensive guide to Part III, IV, and IV-A of the Indian Constitution. Covers Articles 12-51A, landmark judgments, and key differences for MPPSC Unit 5.', '{"hi":[{"type":"h2","text":"Unit 5: मौलिक अधिकार, नीति निदेशक तत्व और मूल कर्तव्य"},{"type":"p","text":"भारतीय संविधान के ये तीन भाग (भाग III, IV, और IV-A) हमारे लोकतंत्र की आत्मा कहे जाते हैं। जहाँ मौलिक अधिकार नागरिकों को राज्य के विरुद्ध सुरक्षा देते हैं, वहीं DPSP राज्य के कर्तव्यों को बताते हैं। MPPSC में इनके अनुच्छेदों और ''केस लॉ'' (जैसे- केशवानंद भारती) पर गहराई से प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. मौलिक अधिकार (Fundamental Rights) - भाग III"},{"type":"p","text":"अनुच्छेद 12 से 35 तक वर्णित। इन्हें ''भारत का मैग्नाकार्टा'' कहा जाता है। वर्तमान में 6 मौलिक अधिकार हैं (संपत्ति का अधिकार 44वें संशोधन द्वारा हटा दिया गया था)।"},{"type":"table","instruction":"छह मौलिक अधिकार और संबंधित अनुच्छेद","head":["अधिकार (Right)","अनुच्छेद (Articles)","विवरण"],"body":[["समानता का अधिकार","14-18","विधि के समक्ष समानता, छुआछूत का अंत (17), उपाधियों का अंत (18)।"],["स्वतंत्रता का अधिकार","19-22","भाषण की आजादी (19), प्राण एवं दैहिक स्वतंत्रता (21)।"],["शोषण के विरुद्ध अधिकार","23-24","मानव तस्करी और बाल श्रम (24) पर रोक।"],["धार्मिक स्वतंत्रता","25-28","धर्म को मानने और प्रचार करने की आजादी।"],["संस्कृति एवं शिक्षा","29-30","अल्पसंख्यकों के हितों का संरक्षण।"],["संवैधानिक उपचार","32","रिट जारी करने की शक्ति (संविधान की आत्मा)।"]]},{"type":"highlight","level":"critical","text":"अनुच्छेद 21A: 86वें संशोधन (2002) द्वारा जोड़ा गया, जो 6-14 वर्ष के बच्चों के लिए ''शिक्षा का अधिकार'' अनिवार्य बनाता है।","icon":"🎓"},{"type":"h2","text":"2. राज्य के नीति निदेशक तत्व (DPSP) - भाग IV"},{"type":"p","text":"अनुच्छेद 36 से 51 तक। ये आयरलैंड के संविधान से लिए गए हैं। ये ''गैर-न्यायोचित'' (Non-justiciable) हैं, यानी इनके उल्लंघन पर कोर्ट नहीं जाया जा सकता।"},{"type":"table","instruction":"महत्वपूर्ण नीति निदेशक तत्व","head":["अनुच्छेद","प्रावधान (Provision)"],"body":[["अनुच्छेद 40","ग्राम पंचायतों का गठन (गांधीवादी विचार)।"],["अनुच्छेद 44","समान नागरिक संहिता (Uniform Civil Code)।"],["अनुच्छेद 45","बच्चों के लिए पूर्व प्राथमिक शिक्षा।"],["अनुच्छेद 50","कार्यपालिका और न्यायपालिका का पृथक्करण।"],["अनुच्छेद 51","अंतर्राष्ट्रीय शांति और सुरक्षा को बढ़ावा देना।"]]},{"type":"h2","text":"3. मौलिक कर्तव्य (Fundamental Duties) - भाग IV-A"},{"type":"p","text":"इन्हें मूल संविधान में नहीं रखा गया था। स्वर्ण सिंह समिति की सिफारिश पर 42वें संशोधन (1976) द्वारा जोड़ा गया। वर्तमान में 11 कर्तव्य हैं।"},{"type":"image_tag","content":""},{"type":"fact_card","title":"प्रमुख तथ्य: मौलिक कर्तव्य","facts":["स्रोत: पूर्व सोवियत संघ (USSR) के संविधान से प्रेरित।","अनुच्छेद: केवल एक अनुच्छेद - 51A।","11वाँ कर्तव्य: 86वें संशोधन (2002) द्वारा जोड़ा गया (शिक्षा का अवसर प्रदान करना)।","प्रकृति: ये केवल नागरिकों के लिए हैं, विदेशियों के लिए नहीं।"],"icon":"🇮🇳"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"किस संशोधन द्वारा शिक्षा के अधिकार को मौलिक अधिकार (अनु. 21A) बनाया गया?","options":["42वाँ","44वाँ","86वाँ","92वाँ"],"correct":"86वाँ","strategy":"86वाँ संशोधन (2002) शिक्षा से संबंधित तीन बदलाव लाया था - अनु 21A, 45 और 51A(k)।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"समान नागरिक संहिता (UCC) का वर्णन किस अनुच्छेद में है?","options":["अनुच्छेद 40","अनुच्छेद 42","अनुच्छेद 44","अनुच्छेद 46"],"correct":"अनुच्छेद 44","strategy":"याद रखने की ट्रिक: 4 और 4 समान (Equal) हैं, इसलिए Uniform Civil Code।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"संविधान के किस भाग में मौलिक कर्तव्यों का वर्णन है?","options":["भाग IV","भाग IV-A","भाग III","भाग VI"],"correct":"भाग IV-A","strategy":"IV-A (Amendment के माध्यम से आया) मूल कर्तव्यों के लिए है।"},{"type":"exam_pattern","topic":"Rights and DPSP Trend","analysis":"Unit 5 Analysis:","stats":["अनुच्छेद (Direct Matching): 2 प्रश्न","संवैधानिक संशोधन: 1 प्रश्न","विचारधारा (गांधीवादी/समाजवादी): 1 प्रश्न"],"trend":"आयोग अब ''अनुच्छेद'' के साथ-साथ यह भी पूछ रहा है कि कौन सा DPSP गांधीवादी विचारधारा से प्रेरित है (जैसे- अनु 40, 43, 47)।"}],"en":[{"type":"h2","text":"Unit 5: Fundamental Rights, DPSP, and Fundamental Duties"},{"type":"p","text":"These three parts (III, IV, and IV-A) are described as the soul of the Indian Constitution. While Fundamental Rights protect citizens against state overreach, DPSPs outline the state''s duties. In MPPSC, questions focus heavily on specific Articles and landmark judicial cases."},{"type":"h2","text":"1. Fundamental Rights (FR) - Part III"},{"type":"p","text":"Described in Articles 12 to 35. Known as the ''Magna Carta of India''. There are currently 6 categories of rights."},{"type":"table","instruction":"Six Fundamental Rights and Articles","head":["Category","Articles","Key Provision"],"body":[["Right to Equality","14-18","Abolition of Untouchability (17), Equality before Law."],["Right to Freedom","19-22","Freedom of Speech (19), Protection of Life (21)."],["Against Exploitation","23-24","Prohibition of Child Labor (24)."],["Freedom of Religion","25-28","Freedom to practice and propagate any religion."],["Cultural & Educational","29-30","Protection of interests of minorities."],["Constitutional Remedies","32","Right to move Court (Soul of Constitution)."]]},{"type":"highlight","level":"critical","text":"Article 21A: Inserted by the 86th Amendment (2002), making ''Right to Education'' mandatory for children aged 6-14.","icon":"🎓"},{"type":"h2","text":"2. Directive Principles of State Policy (DPSP) - Part IV"},{"type":"p","text":"Articles 36 to 51. Borrowed from the Irish Constitution. These are ''Non-justiciable'', meaning they cannot be enforced by a court of law."},{"type":"table","instruction":"Important Directive Principles","head":["Article","Provision"],"body":[["Article 40","Organization of Village Panchayats (Gandhian)."],["Article 44","Uniform Civil Code (UCC)."],["Article 45","Early childhood care and education."],["Article 50","Separation of Judiciary from Executive."],["Article 51","Promotion of International Peace and Security."]]},{"type":"h2","text":"3. Fundamental Duties - Part IV-A"},{"type":"p","text":"Not part of the original constitution. Added by the 42nd Amendment (1976) on the recommendation of the Swaran Singh Committee. Currently, there are 11 duties."},{"type":"image_tag","content":""},{"type":"fact_card","title":"Key Facts: Fundamental Duties","facts":["Source: Inspired by the Constitution of the erstwhile USSR.","Article: Contained in only one Article - 51A.","11th Duty: Added by the 86th Amendment (2002) regarding education.","Nature: Applicable only to citizens, not to foreigners."],"icon":"🇮🇳"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Which amendment made the Right to Education a Fundamental Right?","options":["42nd","44th","86th","92nd"],"correct":"86th","strategy":"The 86th Amendment (2002) dealt with education across FR, DPSP, and Duties."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Which Article describes the Uniform Civil Code?","options":["Article 40","Article 42","Article 44","Article 46"],"correct":"Article 44","strategy":"Trick: 4 and 4 are ''Uniform'' (Equal)."},{"type":"exam_pattern","topic":"Rights and DPSP Trend","analysis":"Unit 5 Analysis:","stats":["Direct Article Matching: 2 questions","Constitutional Amendments: 1 question","Ideology (Gandhian/Socialist): 1 question"],"trend":"The Commission is now categorizing DPSPs into Gandhian, Socialist, and Liberal-Intellectual principles in their questions."}]}', 'polity', NULL, 30, 1, 1770918828, 1770918828, 'blog', 'unit_5', 'Fundamental Rights and Duties of Citizens, Duties and Directive Principle of State', 1, 0, 0, 1, 0, 'Unit 5: मौलिक अधिकार, नीति निदेशक तत्व और मूल कर्तव्य भारतीय संविधान के ये तीन भाग (भाग III, IV, और IV-A) हमारे लोकतंत्र की आत्मा कहे जाते हैं। जहाँ मौलिक अधिकार नागरिकों को राज्य के विरुद्ध सुरक्षा द...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('44eaeeeb-a00f-4629-bf3b-4c92b011a669', 'constitutional-statutory-commissions-unit-5-mppsc', 'Constitutional and Statutory Commissions | संवैधानिक एवं सांविधिक आयोग', 'A comprehensive guide to National and Regional commissions for MPPSC. Covers Election Commission, UPSC, CAG, NITI Aayog, and State-level bodies with Articles and establishment years.', '{"hi":[{"type":"h2","text":"Unit 5: राष्ट्रीय एवं प्रादेशिक संवैधानिक/सांविधिक संस्थाएं"},{"type":"p","text":"लोकतंत्र के सुचारू संचालन के लिए विभिन्न आयोगों का गठन किया गया है। ये संस्थाएं दो प्रकार की होती हैं: **संवैधानिक** (जिनका उल्लेख संविधान के अनुच्छेदों में है) और **सांविधिक** (जो संसद के अधिनियम द्वारा बनी हैं)। MPPSC में इनके ''अनुच्छेद'', ''नियुक्ति'', ''कार्यकाल'' और ''वर्तमान अध्यक्ष'' पर प्रश्न अनिवार्य रूप से पूछे जाते हैं।"},{"type":"h2","text":"1. संवैधानिक निकाय (Constitutional Bodies)"},{"type":"p","text":"इन निकायों की शक्ति सीधे संविधान से प्राप्त होती है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"प्रमुख संवैधानिक आयोग","head":["आयोग (Commission)","अनुच्छेद","नियुक्ति/कार्यकाल","विशेष तथ्य"],"body":[["भारत निर्वाचन आयोग","324","राष्ट्रपति / 6 वर्ष या 65 वर्ष","स्थापना: 25 जनवरी 1950 (मतदाता दिवस)।"],["UPSC","315-323","राष्ट्रपति / 6 वर्ष या 65 वर्ष","प्रथम अध्यक्ष: रॉस बार्कर।"],["म.प्र. लोक सेवा आयोग (MPPSC)","315","राज्यपाल / 6 वर्ष या 62 वर्ष","मुख्यालय: इंदौर। प्रथम अध्यक्ष: डी.वी. रेगे।"],["CAG (नियंत्रक-महालेखा परीक्षक)","148-151","राष्ट्रपति / 6 वर्ष या 65 वर्ष","इसे ''सार्वजनिक धन का संरक्षक'' कहा जाता है।"],["राष्ट्रीय SC/ST आयोग","338 / 338A","राष्ट्रपति / 3 वर्ष","89वें संशोधन द्वारा अलग-अलग किए गए।"]]},{"type":"h2","text":"2. सांविधिक एवं कार्यकारी निकाय (Statutory & Executive)"},{"type":"p","text":"ये संस्थाएं कानून या सरकारी आदेश द्वारा बनाई गई हैं।"},{"type":"table","instruction":"प्रमुख सांविधिक एवं कार्यकारी संस्थाएं","head":["संस्था","स्थापना वर्ष","प्रकृति","मुख्यालय"],"body":[["NITI Aayog","2015","कार्यकारी (योजना आयोग के स्थान पर)","नई दिल्ली"],["मानवाधिकार आयोग (NHRC)","1993","सांविधिक","नई दिल्ली"],["महिला आयोग (NCW)","1992","सांविधिक","नई दिल्ली"],["NGT (राष्ट्रीय हरित अधिकरण)","2010","सांविधिक (पर्यावरण अदालत)","नई दिल्ली (बेंच भोपाल में)"],["सूचना आयोग (CIC)","2005","सांविधिक (RTI Act)","नई दिल्ली"]]},{"type":"highlight","level":"important","text":"NITI Aayog: इसका अध्यक्ष प्रधानमंत्री होता है। यह ''सहयोगात्मक संघवाद'' (Competitive Federalism) पर आधारित ''थिंक टैंक'' है।","icon":"💡"},{"type":"h2","text":"3. मध्य प्रदेश के विशेष आयोग (MP Specific Bodies)"},{"type":"fact_card","title":"म.प्र. राज्य आयोग तथ्य","facts":["म.प्र. राज्य निर्वाचन आयोग: स्थापना 1 फरवरी 1994। प्रथम अध्यक्ष: एन.बी. लोहानी।","म.प्र. राज्य मानवाधिकार आयोग: मुख्यालय ''पर्यावास भवन'', भोपाल।","म.प्र. राज्य महिला आयोग: स्थापना 23 मार्च 1998।","म.प्र. वित्त आयोग: प्रथम अध्यक्ष सवाई सिंह सिसोदिया थे।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भारत के ''नियंत्रक एवं महालेखा परीक्षक'' (CAG) का कार्यकाल कितना होता है?","options":["4 वर्ष","5 वर्ष","6 वर्ष","निर्धारित नहीं"],"correct":"6 वर्ष","strategy":"CAG का कार्यकाल 6 वर्ष या 65 वर्ष की आयु (जो भी पहले हो) होता है।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"नीति आयोग (NITI Aayog) के प्रथम उपाध्यक्ष कौन थे?","options":["अमिताभ कांत","अरविंद पनगढ़िया","राजीव कुमार","नरेंद्र मोदी"],"correct":"अरविंद पनगढ़िया","strategy":"प्रधानमंत्री अध्यक्ष होते हैं, जबकि प्रथम उपाध्यक्ष अरविंद पनगढ़िया थे।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"मध्य प्रदेश लोक सेवा आयोग के प्रथम अध्यक्ष कौन थे?","options":["डी.वी. रेगे","एच.सी. सेठ","सत्यनारायण सिन्हा","पी.के. मल्होत्रा"],"correct":"डी.वी. रेगे","strategy":"डी.वी. रेगे MPPSC के पहले अध्यक्ष थे (1956)।"},{"type":"exam_pattern","topic":"Commission Analysis","analysis":"Unit 5/10 Trend Analysis:","stats":["स्थापना वर्ष/तिथि: 2 प्रश्न","अनुच्छेद/अधिनियम: 1-2 प्रश्न","प्रथम/वर्तमान अध्यक्ष: 1 प्रश्न"],"trend":"आयोग अब संस्थाओं के ''सदस्यों की सेवा शर्तों'' और ''हटाने की प्रक्रिया'' (Removal Process) पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 5: National and Regional Constitutional/Statutory Institutions"},{"type":"p","text":"For the smooth functioning of democracy, various commissions have been established. These institutions are of two types: **Constitutional** (mentioned in the Articles of the Constitution) and **Statutory** (created by an Act of Parliament). In MPPSC, questions on their ''Articles'', ''Appointment'', ''Tenure'', and ''Current Chairpersons'' are mandatory."},{"type":"h2","text":"1. Constitutional Bodies"},{"type":"p","text":"These bodies derive their power directly from the Constitution of India."},{"type":"image_tag","content":""},{"type":"table","instruction":"Key Constitutional Commissions","head":["Commission","Article","Appointment/Tenure","Key Fact"],"body":[["Election Commission of India","324","President / 6 yrs or 65 yrs","Est: 25 Jan 1950 (Voters'' Day)."],["UPSC","315-323","President / 6 yrs or 65 yrs","First Chairman: Ross Barker."],["MPPSC","315","Governor / 6 yrs or 62 yrs","HQ: Indore. First Chair: D.V. Rege."],["CAG","148-151","President / 6 yrs or 65 yrs","Known as the ''Guardian of Public Purse''."],["National SC/ST Commissions","338 / 338A","President / 3 yrs","Separated by 89th Amendment."]]},{"type":"h2","text":"2. Statutory and Executive Bodies"},{"type":"p","text":"These institutions are created via law or government executive orders."},{"type":"table","instruction":"Major Statutory and Executive Bodies","head":["Institution","Est. Year","Nature","Headquarters"],"body":[["NITI Aayog","2015","Executive (Replacing Planning Comm.)","New Delhi"],["NHRC (Human Rights)","1993","Statutory","New Delhi"],["NCW (Women)","1992","Statutory","New Delhi"],["NGT (Green Tribunal)","2010","Statutory (Environmental Court)","New Delhi (Bench in Bhopal)"],["CIC (Information)","2005","Statutory (RTI Act)","New Delhi"]]},{"type":"highlight","level":"important","text":"NITI Aayog: Chaired by the Prime Minister. It is a ''Think Tank'' based on Competitive Federalism.","icon":"💡"},{"type":"h2","text":"3. Special Commissions of Madhya Pradesh"},{"type":"fact_card","title":"MP State Body Facts","facts":["MP State Election Commission: Established 1st Feb 1994. First Chair: N.B. Lohani.","MP State Human Rights Commission: HQ at ''Paryavas Bhawan'', Bhopal.","MP State Women Commission: Established 23rd March 1998.","MP Finance Commission: First Chairman was Sawai Singh Sisodia."],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"What is the tenure of the ''Comptroller and Auditor General'' (CAG) of India?","options":["4 years","5 years","6 years","Not fixed"],"correct":"6 years","strategy":"CAG serves for 6 years or up to 65 years of age, whichever is earlier."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Who was the first Vice-Chairman of NITI Aayog?","options":["Amitabh Kant","Arvind Panagariya","Rajiv Kumar","Narendra Modi"],"correct":"Arvind Panagariya","strategy":"The PM is the Chairperson, and Arvind Panagariya was the first Vice-Chair."},{"type":"exam_pattern","topic":"Commission Analysis","analysis":"Unit 5/10 Trend Analysis:","stats":["Est. Year/Date: 2 questions","Articles/Acts: 1-2 questions","First/Current Chairs: 1 question"],"trend":"The Commission is now asking more about the ''Service Conditions of Members'' and the ''Removal Process''."}]}', 'polity', NULL, 35, 1, 1770918995, 1770918995, 'blog', 'unit_5', 'National and Regional Constitutional/Statutory Commissions and Institutions', 1, 0, 0, 1, 0, 'Unit 5: राष्ट्रीय एवं प्रादेशिक संवैधानिक/सांविधिक संस्थाएं लोकतंत्र के सुचारू संचालन के लिए विभिन्न आयोगों का गठन किया गया है। ये संस्थाएं दो प्रकार की होती हैं: **संवैधानिक** (जिनका उल्लेख संविधान क...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('fa654fe5-6924-4579-924c-5e1619be2454', 'constitutional-system-madhya-pradesh-unit-5-mppsc', 'Constitutional System of Madhya Pradesh | मध्य प्रदेश की संवैधानिक व्यवस्था', 'Comprehensive guide to the state executive and legislature of Madhya Pradesh for Unit 5. Detailed coverage of Governor, Chief Minister, Vidhan Sabha, and the High Court of MP.', '{"hi":[{"type":"h2","text":"Unit 5: मध्य प्रदेश की संवैधानिक व्यवस्था (State Polity)"},{"type":"p","text":"मध्य प्रदेश की शासन व्यवस्था भारतीय संविधान के भाग VI (अनुच्छेद 152-237) के अनुरूप है। राज्य सरकार के तीन अंग हैं: कार्यपालिका (राज्यपाल एवं मंत्रिपरिषद), विधायिका (विधानसभा) और न्यायपालिका (उच्च न्यायालय)। MPPSC में प्रथम पदाधिकारियों, अनुच्छेदों और विधानसभा की संरचना पर बार-बार प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. राज्यपाल (The Governor) - अनुच्छेद 153-162"},{"type":"p","text":"राज्यपाल राज्य का संवैधानिक प्रमुख होता है और केंद्र के प्रतिनिधि के रूप में कार्य करता है।"},{"type":"table","instruction":"राज्यपाल से संबंधित मुख्य तथ्य","head":["विवरण","तथ्य (Fact)"],"body":[["प्रथम राज्यपाल","डॉ. पट्टाभि सीतारमैया"],["प्रथम महिला राज्यपाल","कुमारी सरला ग्रेवाल"],["सर्वाधिक कार्यकाल","एच.वी. पाटस्कर"],["नियुक्ति","राष्ट्रपति द्वारा (अनुच्छेद 155)"],["शपथ","उच्च न्यायालय के मुख्य न्यायाधीश द्वारा"]]},{"type":"highlight","level":"important","text":"अध्यादेश शक्ति: अनुच्छेद 213 के तहत राज्यपाल को राज्य विधानसभा के विश्रांतिकाल में अध्यादेश जारी करने की शक्ति प्राप्त है।","icon":"📜"},{"type":"h2","text":"2. मुख्यमंत्री एवं मंत्रिपरिषद (CM & Cabinet)"},{"type":"p","text":"मुख्यमंत्री राज्य की कार्यपालिका का वास्तविक प्रमुख होता है।"},{"type":"ul","items":["**प्रथम मुख्यमंत्री:** पं. रविशंकर शुक्ल (1956)।","**प्रथम महिला मुख्यमंत्री:** सुश्री उमा भारती।","**सबसे कम कार्यकाल:** राजा नरेशचंद्र सिंह (मात्र 13 दिन)।","**सर्वाधिक कार्यकाल:** शिवराज सिंह चौहान (अब तक)।"]},{"type":"h2","text":"3. मध्य प्रदेश विधानसभा (Legislative Assembly)"},{"type":"p","text":"म.प्र. में ''एकसदनीय'' (Unicameral) व्यवस्था है, यानी यहाँ केवल विधानसभा है, विधान परिषद नहीं।"},{"type":"table","instruction":"विधानसभा की संरचना","head":["विषय","विवरण"],"body":[["कुल सीटें","230 (ST: 47, SC: 35)"],["प्रथम अध्यक्ष (Speaker)","पं. कुँजीलाल दुबे (विधि पुरुष)"],["प्रथम उपाध्यक्ष","विष्णु विनायक सरवटे"],["भवन का नाम","इन्दिरा गांधी विधानसभा भवन (वास्तुकार: चार्ल्स कोरिया)"]]},{"type":"image_tag","content":""},{"type":"h2","text":"4. मध्य प्रदेश उच्च न्यायालय (High Court)"},{"type":"fact_card","title":"न्यायपालिका के मुख्य तथ्य","facts":["स्थापना: 1 नवंबर 1956।","मुख्य पीठ (Main Bench): जबलपुर।","खंडपीठ (Benches): इंदौर और ग्वालियर (1968 में स्थापित)।","प्रथम मुख्य न्यायाधीश: न्यायमूर्ति एम. हिदायतुल्लाह।","प्रथम महिला न्यायाधीश: श्रीमती सरोजनी सक्सेना।"],"icon":"⚖️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश विधानसभा के प्रथम अध्यक्ष कौन थे?","options":["पं. कुँजीलाल दुबे","काशी प्रसाद पांडे","तेजलाल टेंभरे","गुलशेर अहमद"],"correct":"पं. कुँजीलाल दुबे","strategy":"पं. कुँजीलाल दुबे को म.प्र. का ''विधि पुरुष'' कहा जाता है।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"मध्य प्रदेश के राज्यपाल की नियुक्ति कौन करता है?","options":["प्रधानमंत्री","मुख्यमंत्री","राष्ट्रपति","मुख्य न्यायाधीश"],"correct":"राष्ट्रपति","strategy":"अनुच्छेद 155 के तहत राष्ट्रपति राज्यपाल की नियुक्ति करता है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"म.प्र. उच्च न्यायालय की खंडपीठें कहाँ स्थित हैं?","options":["भोपाल एवं इंदौर","ग्वालियर एवं इंदौर","जबलपुर एवं भोपाल","ग्वालियर एवं भोपाल"],"correct":"ग्वालियर एवं इंदौर","strategy":"मुख्य पीठ जबलपुर में है, जबकि खंडपीठें इंदौर और ग्वालियर में हैं।"},{"type":"exam_pattern","topic":"MP Polity Trend","analysis":"Unit 5 MP Polity Analysis:","stats":["प्रथम व्यक्तित्व (First Leaders): 1-2 प्रश्न","विधानसभा सीटें/आरक्षण: 1 प्रश्न","उच्च न्यायालय के न्यायाधीश: 1 प्रश्न"],"trend":"आयोग अब मुख्यमंत्रियों और राज्यपालों के ''क्रम'' (Sequence) और उनके द्वारा लिखी गई ''पुस्तकों'' पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 5: Constitutional System of Madhya Pradesh"},{"type":"p","text":"The administration of Madhya Pradesh operates as per Part VI (Articles 152-237) of the Indian Constitution. The state government consists of three organs: Executive (Governor and Council of Ministers), Legislature (Legislative Assembly), and Judiciary (High Court). MPPSC frequently asks questions about first officeholders, articles, and the structure of the assembly."},{"type":"h2","text":"1. The Governor - Articles 153-162"},{"type":"p","text":"The Governor is the constitutional head of the state and acts as the representative of the Center."},{"type":"table","instruction":"Key Facts About the Governor","head":["Description","Fact"],"body":[["First Governor","Dr. Pattabhi Sitaramayya"],["First Female Governor","Sarla Grewal"],["Longest Tenure","H.V. Pataskar"],["Appointment","By the President (Article 155)"],["Oath","By the Chief Justice of the High Court"]]},{"type":"highlight","level":"important","text":"Ordinance Power: Under Article 213, the Governor has the power to promulgate ordinances when the state legislature is not in session.","icon":"📜"},{"type":"h2","text":"2. Chief Minister & Council of Ministers"},{"type":"p","text":"The Chief Minister is the real executive head of the state."},{"type":"ul","items":["**First CM:** Pt. Ravi Shankar Shukla (1956).","**First Female CM:** Ms. Uma Bharti.","**Shortest Tenure:** Raja Naresh Chandra Singh (only 13 days).","**Longest Tenure:** Shivraj Singh Chouhan (to date)."]},{"type":"h2","text":"3. MP Legislative Assembly (Vidhan Sabha)"},{"type":"p","text":"MP has a ''Unicameral'' system, meaning it only has a Legislative Assembly and no Legislative Council."},{"type":"table","instruction":"Structure of the Assembly","head":["Topic","Description"],"body":[["Total Seats","230 (ST: 47, SC: 35)"],["First Speaker","Pt. Kunjilal Dubey"],["First Deputy Speaker","Vishnu Vinayak Sarwate"],["Building Name","Indira Gandhi Vidhan Sabha Bhavan (Architect: Charles Correa)"]]},{"type":"image_tag","content":""},{"type":"h2","text":"4. Madhya Pradesh High Court"},{"type":"fact_card","title":"Judiciary Key Facts","facts":["Established: 1 November 1956.","Principal Bench: Jabalpur.","Benches: Indore and Gwalior (established in 1968).","First Chief Justice: Justice M. Hidayatullah.","First Female Judge: Mrs. Sarojini Saxena."],"icon":"⚖️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Who was the first Speaker of the Madhya Pradesh Legislative Assembly?","options":["Pt. Kunjilal Dubey","Kashi Prasad Pandey","Tejlal Tembhare","Gulsher Ahmed"],"correct":"Pt. Kunjilal Dubey","strategy":"Pt. Kunjilal Dubey is known as the ''Law Man'' of Madhya Pradesh."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"Who appoints the Governor of Madhya Pradesh?","options":["Prime Minister","Chief Minister","President","Chief Justice"],"correct":"President","strategy":"The Governor is appointed by the President under Article 155."},{"type":"exam_pattern","topic":"MP Polity Trend","analysis":"Unit 5 MP Polity Analysis:","stats":["First Personalities: 1-2 questions","Assembly Seats/Reservation: 1 question","High Court Judges: 1 question"],"trend":"The Commission is now asking more about the ''Sequence'' of CMs and Governors and ''Books'' authored by them."}]}', 'polity', NULL, 30, 1, 1770919054, 1770919054, 'blog', 'unit_5', 'Constitutional System of Madhya Pradesh (Governor, Cabinet, Legislative Assembly, High Court)', 1, 0, 0, 1, 0, 'Unit 5: मध्य प्रदेश की संवैधानिक व्यवस्था (State Polity) मध्य प्रदेश की शासन व्यवस्था भारतीय संविधान के भाग VI (अनुच्छेद 152-237) के अनुरूप है। राज्य सरकार के तीन अंग हैं: कार्यपालिका (राज्यपाल एवं मं...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('904db87c-3b2b-47e0-a150-bb3b9ed377fb', 'panchayati-raj-civil-administration-mp-unit-5-mppsc', 'Panchayati Raj and Civil Administration in MP | म.प्र. में पंचायती राज और नगरीय प्रशासन', 'A comprehensive guide to the decentralized governance in Madhya Pradesh for Unit 5. Detailed analysis of the 73rd and 74th Amendment implementation, Three-tier structures, and urban local bodies.', '{"hi":[{"type":"h2","text":"Unit 5: मध्य प्रदेश में पंचायती राज और नगरीय प्रशासन"},{"type":"p","text":"मध्य प्रदेश 73वें संविधान संशोधन (1992) को लागू करने वाला देश का **पहला राज्य** है। राज्य में विकेंद्रीकृत शासन व्यवस्था के दो प्रमुख स्तंभ हैं: ग्रामीण क्षेत्रों के लिए ''त्रि-स्तरीय पंचायती राज'' और शहरी क्षेत्रों के लिए ''नगरीय प्रशासन''। MPPSC में इनके गठन, सीटों के आरक्षण और प्रमुख अनुच्छेदों पर प्रश्न अनिवार्य रूप से पूछे जाते हैं।"},{"type":"h2","text":"1. त्रि-स्तरीय पंचायती राज (Three-Tier Panchayati Raj)"},{"type":"p","text":"म.प्र. पंचायती राज अधिनियम, 1993 के तहत राज्य में ग्राम, जनपद और जिला स्तर पर त्रि-स्तरीय व्यवस्था है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"पंचायती राज की संरचना","head":["स्तर (Level)","इकाई (Unit)","प्रमुख (Head)","प्रशासक (Admin)"],"body":[["निम्न स्तर","ग्राम पंचायत","सरपंच","सचिव (Secretary)"],["मध्यम स्तर","जनपद पंचायत","अध्यक्ष","CEO (जनपद)"],["उच्च स्तर","जिला पंचायत","अध्यक्ष","CEO (IAS/State Service)"]]},{"type":"highlight","level":"critical","text":"महिला आरक्षण: मध्य प्रदेश पंचायतों में महिलाओं को 50% आरक्षण देने वाला भारत का पहला राज्य है।","icon":"👩‍💼"},{"type":"h2","text":"2. नगरीय प्रशासन (Civil Administration) - 74वां संशोधन"},{"type":"p","text":"नगरीय क्षेत्रों में जनसंख्या और महत्व के आधार पर तीन प्रकार की संस्थाएं कार्यरत हैं।"},{"type":"table","instruction":"नगरीय निकायों का वर्गीकरण","head":["इकाई","संख्या (लगभग)","प्रमुख","विशेष तथ्य"],"body":[["नगर निगम","16 + 2 प्रस्तावित","महापौर (Mayor)","1 लाख से अधिक जनसंख्या।"],["नगर पालिका","98","अध्यक्ष","20,000 से 1 लाख जनसंख्या।"],["नगर परिषद","294","अध्यक्ष","5,000 से 20,000 जनसंख्या (संक्रमणशील क्षेत्र)।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"3. महत्वपूर्ण अनुच्छेद एवं तथ्य (Important Articles)"},{"type":"ul","items":["**अनुच्छेद 243-D:** पंचायतों में सीटों का आरक्षण (SC/ST/OBC/Women)।","**अनुच्छेद 243-I:** राज्य वित्त आयोग (State Finance Commission) का गठन।","**अनुच्छेद 243-K:** राज्य निर्वाचन आयोग (State Election Commission) का गठन।","**अनुच्छेद 243-G:** पंचायतों की शक्तियाँ, अधिकार और उत्तरदायित्व (29 विषय)।"]},{"type":"fact_card","title":"म.प्र. प्रशासन: क्विक बाइट्स","facts":["प्रथम चुनाव: म.प्र. में पंचायतों के प्रथम चुनाव 1994 में हुए थे।","राइट टू रिकॉल (Right to Recall): म.प्र. में पहली बार अनूपपुर की पल्लविका पटेल के विरुद्ध प्रयोग किया गया।","पहली महिला सरपंच: सेवाबाई (म.प्र. की प्रथम महिला सरपंच)।","नगर निगम मुख्यालय: म.प्र. का सबसे पुराना नगर निगम जबलपुर (1864) है।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश पंचायती राज अधिनियम, 1993 में कितने स्तर की पंचायत व्यवस्था का प्रावधान है?","options":["एक स्तरीय","द्वि-स्तरीय","त्रि-स्तरीय","चार स्तरीय"],"correct":"त्रि-स्तरीय","strategy":"म.प्र. ने बलवंत राय मेहता समिति की त्रि-स्तरीय सिफारिशों को अपनाया है।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"73वें संविधान संशोधन के तहत मध्य प्रदेश में पंचायत चुनाव पहली बार कब हुए थे?","options":["1992","1993","1994","1995"],"correct":"1994","strategy":"अधिनियम 1993 का है, लेकिन चुनाव मई-जून 1994 में आयोजित हुए थे।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"नगरीय निकायों में महिलाओं को 50% आरक्षण देने वाला प्रथम राज्य कौन सा है?","options":["उत्तर प्रदेश","बिहार","मध्य प्रदेश","राजस्थान"],"correct":"मध्य प्रदेश","strategy":"म.प्र. ने पंचायतों और नगरीय निकायों दोनों में महिलाओं को 50% आरक्षण दिया है।"},{"type":"exam_pattern","topic":"Local Bodies Trend","analysis":"Unit 5 Analysis:","stats":["अनुच्छेद (243 A-ZG): 1-2 प्रश्न","समितियाँ (बलवंत राय/अशोक मेहता): 1 प्रश्न","म.प्र. के विशिष्ट तथ्य: 1 प्रश्न"],"trend":"आयोग अब ''राज्य वित्त आयोग'' और ''राज्य निर्वाचन आयोग'' के अनुच्छेदों और शक्तियों पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 5: Panchayati Raj and Civil Administration in MP"},{"type":"p","text":"Madhya Pradesh was the **first state** in India to implement the 73rd Constitutional Amendment Act (1992). The decentralized governance in the state is based on two pillars: ''Three-tier Panchayati Raj'' for rural areas and ''Civil Administration'' for urban areas. MPPSC frequently asks about their formation, reservation policies, and crucial articles."},{"type":"h2","text":"1. Three-Tier Panchayati Raj"},{"type":"p","text":"Under the MP Panchayati Raj Act, 1993, the state follows a three-level structure at the Village, Block (Janpad), and District levels."},{"type":"image_tag","content":""},{"type":"table","instruction":"Structure of Panchayati Raj","head":["Level","Unit","Political Head","Administrative Head"],"body":[["Lowest","Gram Panchayat","Sarpanch","Secretary"],["Middle","Janpad Panchayat","President","CEO (Janpad)"],["Highest","Zila Panchayat","President","CEO (IAS/SAS)"]]},{"type":"highlight","level":"critical","text":"Women Reservation: MP is the first state in India to provide 50% reservation for women in Panchayats.","icon":"👩‍💼"},{"type":"h2","text":"2. Civil Administration - 74th Amendment"},{"type":"p","text":"In urban areas, three types of institutions function based on the population and economic significance."},{"type":"table","instruction":"Classification of Urban Bodies","head":["Unit","Approx Count","Head","Key Fact"],"body":[["Nagar Nigam","16 + 2 Proposed","Mayor","Population over 1 Lakh."],["Nagar Palika","98","President","Population 20,000 to 1 Lakh."],["Nagar Parishad","294","President","Population 5,000 to 20,000 (Transition zones)."]]},{"type":"image_tag","content":""},{"type":"h2","text":"3. Crucial Articles & Facts"},{"type":"ul","items":["**Article 243-D:** Reservation of seats in Panchayats.","**Article 243-I:** Constitution of the State Finance Commission.","**Article 243-K:** Elections to the Panchayats (State Election Commission).","**Article 243-G:** Powers, authority, and responsibilities (29 subjects)."]},{"type":"fact_card","title":"MP Administration: Quick Bites","facts":["First Elections: Held in May-June 1994 in MP.","Right to Recall: First used against Pallavika Patel in Anuppur.","Oldest Municipality: Jabalpur (Est. 1864) is the oldest in MP.","Financial Power: Recommended by the State Finance Commission every 5 years."],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"How many tiers are provided in the MP Panchayati Raj Act, 1993?","options":["Single-tier","Two-tier","Three-tier","Four-tier"],"correct":"Three-tier","strategy":"MP adopted the Balwant Rai Mehta committee''s three-tier model."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"When were the first Panchayat elections held in MP under the 73rd Amendment?","options":["1992","1993","1994","1995"],"correct":"1994","strategy":"Though the Act is from 1993, elections were successfully held in 1994."},{"type":"exam_pattern","topic":"Local Bodies Trend","analysis":"Unit 5 Analysis:","stats":["Articles (243 A-ZG): 1-2 questions","Committees: 1 question","MP Specific Stats: 1 question"],"trend":"The Commission is now focusing more on the specific powers of State Finance and Election Commissions."}]}', 'polity', NULL, 30, 1, 1770919132, 1770919132, 'blog', 'unit_5', 'Three-Tier Panchayati Raj and Civil Administration system in Madhya Pradesh', 1, 0, 0, 1, 0, 'Unit 5: मध्य प्रदेश में पंचायती राज और नगरीय प्रशासन मध्य प्रदेश 73वें संविधान संशोधन (1992) को लागू करने वाला देश का **पहला राज्य** है। राज्य में विकेंद्रीकृत शासन व्यवस्था के दो प्रमुख स्तंभ हैं: ग्...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('614da190-13a9-4872-bebb-48408896f10d', 'good-governance-madhya-pradesh-unit-5-mppsc', 'Good Governance in Madhya Pradesh | मध्य प्रदेश में सुशासन', 'Comprehensive guide to the Governance System and Good Governance initiatives in Madhya Pradesh for MPPSC Unit 5. Covers E-governance, Public Service Guarantee Act, and various digital portals.', '{"hi":[{"type":"h2","text":"Unit 5: मध्य प्रदेश में सुशासन (Good Governance System)"},{"type":"p","text":"सुशासन का अर्थ है ऐसी शासन व्यवस्था जो पारदर्शी, जवाबदेह और नागरिक-केंद्रित हो। मध्य प्रदेश सरकार ने सूचना प्रौद्योगिकी (IT) और लोक सेवा गारंटी जैसे कानूनों के माध्यम से सुशासन की दिशा में कई नवाचार किए हैं। MPPSC में ''लोक सेवा गारंटी अधिनियम'' और ''मुख्यमंत्री हेल्पलाइन'' जैसे विषयों पर प्रश्न अक्सर पूछे जाते हैं।"},{"type":"h2","text":"1. लोक सेवा गारंटी अधिनियम, 2010"},{"type":"p","text":"मध्य प्रदेश लोक सेवाओं के प्रदान की गारंटी देने वाला देश का **पहला राज्य** है।"},{"type":"ul","items":["**पारित वर्ष:** यह अधिनियम 18 अगस्त 2010 को लागू हुआ।","**उद्देश्य:** नागरिकों को एक निश्चित समय सीमा के भीतर सरकारी सेवाएं (जैसे जाति प्रमाण पत्र, आय प्रमाण पत्र) उपलब्ध कराना।","**पुरस्कार:** इस नवाचार के लिए म.प्र. को ''संयुक्त राष्ट्र लोक सेवा पुरस्कार'' (UN Public Service Award) मिल चुका है।"]},{"type":"image_tag","content":""},{"type":"h2","text":"2. ई-गवर्नेंस एवं डिजिटल पहल (E-Governance Initiatives)"},{"type":"table","instruction":"सुशासन हेतु प्रमुख पोर्टल एवं सेवाएं","head":["पोर्टल/सेवा","उद्देश्य/विशेषता"],"body":[["सीएम हेल्पलाइन (181)","शिकायत निवारण का एकीकृत माध्यम। ''181'' टोल-फ्री नंबर।"],["समाधान ऑनलाइन","जन शिकायतों के त्वरित निराकरण हेतु वीडियो कॉन्फ्रेंसिंग कार्यक्रम।"],["म.प्र. ई-डिस्ट्रिक्ट","सभी जिलों में नागरिक सेवाएं ऑनलाइन उपलब्ध कराना।"],["एमपी-ऑनलाइन (MP Online)","नागरिकों को सरकारी फॉर्म और बिल भुगतान की सुविधा (2006)।"],["स्वदेश पोर्टल","पंचायत स्तर पर डेटा प्रबंधन हेतु।"]]},{"type":"highlight","level":"important","text":"सुशासन दिवस (Good Governance Day): भारत में 25 दिसंबर (अटल बिहारी वाजपेयी जी का जन्मदिन) को सुशासन दिवस के रूप में मनाया जाता है। म.प्र. में ''सुशासन भवन'' भोपाल में स्थित है।","icon":"🏛️"},{"type":"h2","text":"3. प्रशासनिक नवाचार (Administrative Innovations)"},{"type":"fact_card","title":"सुशासन के मुख्य स्तंभ","facts":["ई-कैबिनेट: मध्य प्रदेश कैबिनेट अब पूरी तरह पेपरलेस (ई-कैबिनेट) हो गई है।","अटल बिहारी वाजपेयी सुशासन एवं नीति विश्लेषण संस्थान: यह भोपाल में स्थित है (संस्थापक महानिदेशक: आर. परशुराम)।","आनंदम विभाग: म.प्र. ''खुशी विभाग'' (Department of Happiness) गठित करने वाला देश का पहला राज्य है (2016)।","जनसुनवाई कार्यक्रम: प्रत्येक मंगलवार को कलेक्टरेट स्तर पर शिकायतों को सुनने हेतु।"],"icon":"💡"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश लोक सेवा गारंटी अधिनियम किस वर्ष पारित किया गया था?","options":["2008","2010","2012","2014"],"correct":"2010","strategy":"यह अधिनियम 18 अगस्त 2010 को लागू हुआ था, जो म.प्र. का एक क्रांतिकारी कदम था।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"सीएम हेल्पलाइन (CM Helpline) का टोल-फ्री नंबर क्या है?","options":["100","101","181","1098"],"correct":"181","strategy":"181 का उपयोग म.प्र. में शिकायतों और सूचनाओं के लिए किया जाता है।"},{"type":"exam_pattern","topic":"Governance Trend","analysis":"Unit 5 Analysis:","stats":["ई-गवर्नेंस पोर्टल: 1 प्रश्न","लोक सेवा गारंटी अधिनियम: 1 प्रश्न","प्रमुख संस्थान (भोपाल): 1 प्रश्न"],"trend":"आयोग अब ''सिटिजन चार्टर'' (Citizen Charter) और हालिया ''ई-गवर्नेंस'' पुरस्कारों पर अधिक ध्यान दे रहा है।"}],"en":[{"type":"h2","text":"Unit 5: Good Governance in Madhya Pradesh"},{"type":"p","text":"Good governance refers to a system of administration that is transparent, accountable, and citizen-centric. The Government of Madhya Pradesh has pioneered several innovations through IT and laws like the Public Service Guarantee Act. MPPSC frequently asks about the ''Public Service Guarantee Act'' and ''CM Helpline''."},{"type":"h2","text":"1. Public Service Guarantee Act, 2010"},{"type":"p","text":"Madhya Pradesh is the **first state** in India to guarantee the delivery of public services."},{"type":"ul","items":["**Year of Passing:** The act was implemented on August 18, 2010.","**Objective:** To provide government services (like Caste or Income certificates) to citizens within a fixed time frame.","**Award:** MP received the ''UN Public Service Award'' for this innovation."]},{"type":"image_tag","content":""},{"type":"h2","text":"2. E-Governance & Digital Initiatives"},{"type":"table","instruction":"Major Portals for Good Governance","head":["Portal/Service","Objective/Feature"],"body":[["CM Helpline (181)","Integrated medium for grievance redressal. Toll-free ''181''."],["Samadhan Online","A video conferencing program for the speedy resolution of public grievances."],["MP E-District","Providing online citizen services across all districts."],["MP-Online","Citizen service portal for forms and bill payments (Est. 2006)."],["Swadesh Portal","For data management at the Panchayat level."]]},{"type":"highlight","level":"important","text":"Good Governance Day: Celebrated on 25th December (Birthday of Atal Bihari Vajpayee). The ''Sushasan Bhavan'' is located in Bhopal.","icon":"🏛️"},{"type":"h2","text":"3. Administrative Innovations"},{"type":"fact_card","title":"Pillars of Governance","facts":["E-Cabinet: MP Cabinet has become completely paperless (E-Cabinet).","AIGGPA: Atal Bihari Vajpayee Institute of Good Governance and Policy Analysis (Bhopal).","Happiness Department: MP is the first state to form a ''Happiness Department'' (2016).","Jan-Sunwai: A program held every Tuesday at the district level to hear public complaints."],"icon":"💡"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"In which year was the MP Public Service Guarantee Act passed?","options":["2008","2010","2012","2014"],"correct":"2010","strategy":"The act was passed on 18th Aug 2010, marking a revolutionary step in governance."},{"type":"exam_pattern","topic":"Governance Trend","analysis":"Unit 5 Analysis:","stats":["E-Governance Portals: 1 question","Public Service Acts: 1 question","Institutes in Bhopal: 1 question"],"trend":"The Commission is now focusing more on ''Citizen Charters'' and recent E-governance awards received by the state."}]}', 'polity', NULL, 25, 1, 1770919175, 1770919175, 'blog', 'unit_5', 'Good Governance in Madhya Pradesh (Governance System)', 1, 0, 0, 1, 0, 'Unit 5: मध्य प्रदेश में सुशासन (Good Governance System) सुशासन का अर्थ है ऐसी शासन व्यवस्था जो पारदर्शी, जवाबदेह और नागरिक-केंद्रित हो। मध्य प्रदेश सरकार ने सूचना प्रौद्योगिकी (IT) और लोक सेवा गारंटी ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('aaaf7d3f-d6e7-40c3-b09b-a03a7f84e1cd', 'mp-status-indian-economy-unit-6-mppsc', 'MP''s Status in the Indian Economy | भारतीय अर्थव्यवस्था में म.प्र. की स्थिति', 'Comprehensive analysis of Madhya Pradesh''s contribution to India''s GDP, sectoral growth, and economic rankings for MPPSC Unit 6. Covers GSDP, Per Capita Income, and key economic indicators.', '{"hi":[{"type":"h2","text":"Unit 6: भारतीय अर्थव्यवस्था में मध्य प्रदेश की वर्तमान स्थिति"},{"type":"p","text":"मध्य प्रदेश वर्तमान में भारत की सबसे तेजी से बढ़ती अर्थव्यवस्थाओं में से एक है। राज्य ने ''बिमारू'' (BIMARU) राज्य की छवि को पीछे छोड़कर कृषि और औद्योगिक विकास में नए मानक स्थापित किए हैं। MPPSC Unit 6 के लिए राज्य के सकल घरेलू उत्पाद (GSDP), प्रति व्यक्ति आय और विभिन्न क्षेत्रों (Primary, Secondary, Tertiary) के योगदान को समझना अनिवार्य है।"},{"type":"h2","text":"1. मुख्य आर्थिक संकेतक (Key Economic Indicators)"},{"type":"p","text":"आर्थिक सर्वेक्षण (Economic Survey) के अनुसार, मध्य प्रदेश की विकास दर राष्ट्रीय औसत से अधिक रही है।"},{"type":"table","instruction":"म.प्र. बनाम भारत: तुलनात्मक आंकड़े (नवीनतम)","head":["संकेतक (Indicator)","मध्य प्रदेश (MP)","भारत (India)"],"body":[["जीडीपी वृद्धि दर (GSDP Growth)","लगभग 16% (प्रचलित भावों पर)","लगभग 10-11%"],["प्रति व्यक्ति आय (Per Capita)","₹1.40 लाख (लगभग)","₹1.70 लाख (लगभग)"],["राजकोषीय घाटा (Fiscal Deficit)","GSDP का 3.5% - 4%","GDP का 5.9% (लक्ष्य)"],["अर्थव्यवस्था का आकार","भारत की GDP में ~4.8% योगदान","शीर्ष 10 राज्यों में शामिल"]]},{"type":"highlight","level":"important","text":"विशेष: मध्य प्रदेश का ''कृषि विकास दर'' (Agriculture Growth Rate) पिछले दशक में औसतन 18% से अधिक रहा है, जो भारत में सर्वाधिक है।","icon":"📈"},{"type":"h2","text":"2. क्षेत्रवार योगदान (Sectoral Contribution)"},{"type":"p","text":"मध्य प्रदेश की अर्थव्यवस्था का झुकाव अभी भी प्राथमिक क्षेत्र (कृषि) की ओर अधिक है, हालांकि सेवा क्षेत्र तेजी से बढ़ रहा है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"GSDP में क्षेत्रों का योगदान","head":["क्षेत्र (Sector)","योगदान (%)","मुख्य घटक"],"body":[["प्राथमिक (Primary)","47-48%","कृषि, वानिकी, खनन।"],["द्वितीयक (Secondary)","19-20%","विनिर्माण (Manufacturing), निर्माण, बिजली।"],["तृतीयक (Tertiary)","32-33%","सेवाएं, व्यापार, होटल, परिवहन।"]]},{"type":"h2","text":"3. निवेश और औद्योगिक स्थिति (Investment & Industry)"},{"type":"fact_card","title":"आर्थिक उपलब्धियां","facts":["ईज ऑफ डूइंग बिजनेस: म.प्र. को ''अचीवर्स'' (Achievers) श्रेणी में रखा गया है।","निर्यात (Exports): राज्य से फार्मास्यूटिकल्स, कपास और सोयाबीन का भारी मात्रा में निर्यात होता है।","एक जिला एक उत्पाद (ODOP): राज्य के सभी 52/55 जिलों के विशिष्ट उत्पादों को वैश्विक पहचान दिलाने की पहल।","औद्योगिक गलियारे: इंदौर-पीथमपुर और भोपाल-होशंगाबाद आर्थिक गलियारों का विकास।"],"icon":"🏭"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश की अर्थव्यवस्था किस प्रकार की है?","options":["कृषि प्रधान","उद्योग प्रधान","पूंजी प्रधान","मिश्रित"],"correct":"कृषि प्रधान","strategy":"GSDP में प्राथमिक क्षेत्र का लगभग 48% योगदान होने के कारण इसे कृषि प्रधान माना जाता है।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"मध्य प्रदेश में ''प्रति व्यक्ति आय'' की गणना का आधार वर्ष क्या है?","options":["2001-02","2011-12","1999-2000","2015-16"],"correct":"2011-12","strategy":"वर्तमान में स्थिर भावों (Constant Prices) के लिए आधार वर्ष 2011-12 ही उपयोग किया जाता है।"},{"type":"exam_pattern","topic":"MP Economic Trend","analysis":"Unit 6 Trend Analysis:","stats":["GSDP डेटा: 1 प्रश्न","प्रति व्यक्ति आय: 1 प्रश्न","क्षेत्रवार योगदान (%): 1 प्रश्न"],"trend":"आयोग अब बजट के ''राजकोषीय घाटे'' (Fiscal Deficit) और ''पूंजीगत व्यय'' (Capital Expenditure) के सटीक आंकड़ों पर ध्यान दे रहा है।"}],"en":[{"type":"h2","text":"Unit 6: Current Situation of Madhya Pradesh in the Indian Economy"},{"type":"p","text":"Madhya Pradesh is currently one of the fastest-growing economies in India. Leaving behind the ''BIMARU'' tag, the state has set new benchmarks in agricultural and industrial growth. For MPPSC Unit 6, it is crucial to understand the GSDP, Per Capita Income, and Sectoral contribution."},{"type":"h2","text":"1. Key Economic Indicators"},{"type":"p","text":"According to the latest Economic Survey, MP''s growth rate has consistently outpaced the national average."},{"type":"table","instruction":"MP vs India: Comparative Figures (Latest)","head":["Indicator","Madhya Pradesh (MP)","India"],"body":[["GSDP Growth Rate","~16% (At Current Prices)","~10-11%"],["Per Capita Income","~₹1.40 Lakh","~₹1.70 Lakh"],["Fiscal Deficit","3.5% - 4% of GSDP","5.9% of GDP (Target)"],["Share in India''s GDP","~4.8% contribution","Among Top 10 States"]]},{"type":"highlight","level":"important","text":"Note: MP''s Agriculture Growth Rate has averaged over 18% in the last decade, the highest in India.","icon":"📈"},{"type":"h2","text":"2. Sectoral Contribution"},{"type":"p","text":"The economy of Madhya Pradesh is still heavily tilted towards the Primary Sector (Agriculture), though the Service sector is expanding rapidly."},{"type":"image_tag","content":""},{"type":"table","instruction":"Sectoral Contribution to GSDP","head":["Sector","Contribution (%)","Key Components"],"body":[["Primary","47-48%","Agriculture, Forestry, Mining."],["Secondary","19-20%","Manufacturing, Construction, Electricity."],["Tertiary","32-33%","Services, Trade, Hotels, Transport."]]},{"type":"h2","text":"3. Investment and Industrial Status"},{"type":"fact_card","title":"Economic Milestones","facts":["Ease of Doing Business: MP is categorized under the ''Achievers'' bracket.","Exports: Major exporter of Pharmaceuticals, Cotton, and Soybean.","ODOP (One District One Product): An initiative to give global recognition to specific products from all districts.","Economic Corridors: Development of Indore-Pithampur and Bhopal-Hoshangabad corridors."],"icon":"🏭"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"What type of economy does Madhya Pradesh have?","options":["Agri-based","Industry-based","Capital-based","Mixed"],"correct":"Agri-based","strategy":"With nearly 48% contribution from the primary sector, MP is considered an agrarian economy."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"What is the base year for calculating ''Per Capita Income'' in MP?","options":["2001-02","2011-12","1999-2000","2015-16"],"correct":"2011-12","strategy":"Currently, 2011-12 is the base year used for Constant Prices."},{"type":"exam_pattern","topic":"MP Economic Trend","analysis":"Unit 6 Trend Analysis:","stats":["GSDP Data: 1 question","Per Capita Income: 1 question","Sectoral contribution (%): 1 question"],"trend":"The Commission is shifting focus towards exact ''Fiscal Deficit'' figures and ''Capital Expenditure'' details from the budget."}]}', 'economy', NULL, 25, 1, 1770919293, 1771008898, 'blog', 'unit_6', 'Current Situation of Madhya Pradesh in Indian Economy', 1, 0, 1, 1, 0, 'Unit 6: भारतीय अर्थव्यवस्था में मध्य प्रदेश की वर्तमान स्थिति मध्य प्रदेश वर्तमान में भारत की सबसे तेजी से बढ़ती अर्थव्यवस्थाओं में से एक है। राज्य ने ''बिमारू'' (BIMARU) राज्य की छवि को पीछे छोड़कर कृष...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('b6cd97c3-8090-459f-a30b-1a836b726b73', 'population-hrd-education-health-skills-mp-unit-6', 'Population and HRD: Education, Health & Skills in MP | म.प्र. में जनसंख्या एवं मानव संसाधन विकास', 'Comprehensive guide to Human Resource Development in Madhya Pradesh for MPPSC Unit 6. Covers demographic trends, literacy, education initiatives like CM Rise, health infrastructure, and skill development projects.', '{"hi":[{"type":"h2","text":"Unit 6: मध्य प्रदेश में जनसंख्या और मानव संसाधन विकास"},{"type":"p","text":"मानव संसाधन विकास (HRD) किसी भी अर्थव्यवस्था की प्रगति का मुख्य चालक होता है। मध्य प्रदेश में शिक्षा, स्वास्थ्य और कौशल विकास के क्षेत्र में व्यापक सुधार किए जा रहे हैं। MPPSC Unit 6 में जनगणना 2011 के आंकड़ों के साथ-साथ नवीनतम सरकारी योजनाओं (जैसे- ''सीएम राइज'' और ''ग्लोबल स्किल पार्क'') पर विशेष प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. जनसंख्या एवं जनसांख्यिकी (Population & Demographics)"},{"type":"p","text":"म.प्र. की जनसंख्या का एक बड़ा हिस्सा युवा है, जो ''डेमोग्राफिक डिविडेंड'' (Demographic Dividend) का अवसर प्रदान करता है।"},{"type":"table","instruction":"म.प्र. जनसांख्यिकी: एक नजर (2011 जनगणना)","head":["सूचक (Indicator)","आंकड़ा (Data)","विशेष तथ्य"],"body":[["कुल जनसंख्या","7.26 करोड़","भारत की जनसंख्या का 6%।"],["लिंगानुपात (Sex Ratio)","931","बालाघाट (1021) सर्वाधिक, भिंड (837) न्यूनतम।"],["साक्षरता दर (Literacy)","69.3%","पुरुष: 78.7%, महिला: 59.2%।"],["शहरीकरण प्रतिशत","27.6%","भोपाल सर्वाधिक नगरीकृत (80.9%)।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. शिक्षा विकास (Education Development)"},{"type":"p","text":"राज्य सरकार ''नई शिक्षा नीति-2020'' को लागू करने और बुनियादी ढांचे को आधुनिक बनाने पर ध्यान केंद्रित कर रही है।"},{"type":"ul","items":["**सीएम राइज स्कूल (Sandipani Vidyalaya):** गुणवत्तापूर्ण शिक्षा हेतु 9,200 स्कूल विकसित किए जा रहे हैं। (नवीनतम: इनका नाम बदलकर ''सांदीपनि विद्यालय'' कर दिया गया है)।","**उच्च शिक्षा:** राज्य में 1,346 कॉलेज और 10.5 लाख से अधिक सीटें उपलब्ध हैं।","**पीएम श्री स्कूल:** केंद्र सरकार के सहयोग से 730 स्कूलों को आधुनिक लैब और लाइब्रेरी से लैस किया जा रहा है।"]},{"type":"highlight","level":"important","text":"शिक्षा बजट 2025: राज्य के कुल बजट का लगभग 11.26% शिक्षा क्षेत्र के लिए आवंटित किया गया है।","icon":"🎓"},{"type":"h2","text":"3. स्वास्थ्य एवं पोषण (Health & Nutrition)"},{"type":"table","instruction":"प्रमुख स्वास्थ्य योजनाएं एवं बुनियादी ढांचा","head":["योजना/संस्थान","विवरण","उपलब्धि"],"body":[["आयुष्मान भारत (PM-JAY)","₹5 लाख तक का मुफ्त इलाज।","म.प्र. में 4.85 करोड़ से अधिक कार्ड जारी।"],["आयुष्मान आरोग्य मंदिर","प्राथमिक स्वास्थ्य केंद्र (PHC)।","12,000+ केंद्र संचालित।"],["चिकित्सा शिक्षा","मेडिकल कॉलेज विस्तार।","नए मेडिकल कॉलेज (धार, भिंड, बालाघाट आदि) स्वीकृत।"],["लाड़ली लक्ष्मी 2.0","बेटियों की शिक्षा और स्वास्थ्य।","लिंगानुपात और पोषण में सुधार हेतु प्रभावी।"]]},{"type":"h2","text":"4. कौशल विकास (Skill Development)"},{"type":"fact_card","title":"कौशल एवं रोजगार पहल","facts":["संत शिरोमणि रविदास ग्लोबल स्किल पार्क (Bhopal): सिंगापुर के सहयोग से स्थापित एशिया का अग्रणी कौशल केंद्र।","मुख्यमंत्री कौशल संवर्धन योजना: युवाओं को अल्पकालिक तकनीकी प्रशिक्षण।","सीखो-कमाओ योजना (Learn & Earn): उद्योगों में इंटर्नशिप के साथ स्टाइपेंड की सुविधा।","वोकेशनल एजुकेशन: स्कूलों में 14 नए ट्रेड शामिल (जैसे- AI, IT, इलेक्ट्रॉनिक्स)।"],"icon":"🛠️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"2011 की जनगणना के अनुसार, म.प्र. में महिला साक्षरता प्रतिशत क्या है?","options":["59.2%","69.3%","78.7%","50.1%"],"correct":"59.2%","strategy":"कुल साक्षरता 69.3% है, पुरुष 78.7% और महिला 59.2% (याद रखें)।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"''ग्लोबल स्किल पार्क'' मध्य प्रदेश के किस शहर में स्थित है?","options":["इंदौर","ग्वालियर","जबलपुर","भोपाल"],"correct":"भोपाल","strategy":"यह नरेला शंकरी, भोपाल में स्थित है और सिंगापुर के सहयोग से बना है।"},{"type":"exam_pattern","topic":"MP HRD Trend","analysis":"Unit 6 Analysis:","stats":["शिक्षा/स्वास्थ्य बजट %: 1 प्रश्न","जनगणना डेटा (लिंगानुपात/साक्षरता): 2 प्रश्न","कौशल विकास योजनाएं: 1 प्रश्न"],"trend":"आयोग अब ''शिशु मृत्यु दर'' (IMR) और ''मातृ मृत्यु दर'' (MMR) के नवीनतम आर्थिक सर्वेक्षण आंकड़ों पर अधिक ध्यान दे रहा है।"}],"en":[{"type":"h2","text":"Unit 6: Population and HRD in Madhya Pradesh"},{"type":"p","text":"Human Resource Development (HRD) is the primary driver of any economy. In MPPSC Unit 6, questions are frequently asked on Census 2011 data along with recent government initiatives like ''Sandipani Vidyalaya'' and ''Global Skill Park''."},{"type":"h2","text":"1. Population & Demographics"},{"type":"table","instruction":"MP Demographics: At a Glance (Census 2011)","head":["Indicator","Data","Key Fact"],"body":[["Total Population","7.26 Crore","6% of India''s population."],["Sex Ratio","931","Balaghat (1021) highest, Bhind (837) lowest."],["Literacy Rate","69.3%","Male: 78.7%, Female: 59.2%."],["Urbanization %","27.6%","Bhopal is most urbanized (80.9%)."]]},{"type":"h2","text":"2. Education Initiatives"},{"type":"ul","items":["**Sandipani Vidyalaya (formerly CM Rise):** 9,200 schools are being developed to provide quality education with modern facilities.","**Higher Education:** Over 1,346 colleges with 10.5 lakh seats are available in the state.","**PM Shri Schools:** 730 schools are being modernized with ICT labs and Atal Tinkering Labs."]},{"type":"h2","text":"3. Health & Skill Development"},{"type":"fact_card","title":"Skills & Health Pillars","facts":["Ayushman Bharat: Over 4.85 crore cards issued in MP, providing free treatment up to ₹5 lakh.","Global Skill Park (Bhopal): Asia''s leading skill center established with Singapore''s collaboration.","Seekho-Kamao Yojana: Industry-based internship program with a monthly stipend for youth.","Health Budget 2025: ₹15,744 crore allocated for the health sector."],"icon":"🛠️"}]}', 'economy', NULL, 30, 1, 1770919325, 1771008898, 'blog', 'unit_6', 'Population and Human Resources Development: Education, Health and Skills in Madhya Pradesh', 0, 1, 1, 1, 0, 'Unit 6: मध्य प्रदेश में जनसंख्या और मानव संसाधन विकास मानव संसाधन विकास (HRD) किसी भी अर्थव्यवस्था की प्रगति का मुख्य चालक होता है। मध्य प्रदेश में शिक्षा, स्वास्थ्य और कौशल विकास के क्षेत्र में व्याप...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('d2d8b18e-87c0-4f06-9121-d0ae8c750849', 'sdg-progress-madhya-pradesh-unit-6-mppsc', 'Progress in Sustainable Development Goals (SDG) in MP | म.प्र. में सतत विकास लक्ष्यों (SDG) में प्रगति', 'A detailed analysis of Madhya Pradesh''s performance in NITI Aayog''s SDG India Index. Covers key goals like No Poverty, Clean Water, and Gender Equality for MPPSC Unit 6.', '{"hi":[{"type":"h2","text":"Unit 6: मध्य प्रदेश में सतत विकास लक्ष्य (SDG) की प्रगति"},{"type":"p","text":"सतत विकास लक्ष्य (SDG) 17 वैश्विक लक्ष्यों का एक समूह है जिसे संयुक्त राष्ट्र द्वारा 2030 तक प्राप्त करने का लक्ष्य रखा गया है। भारत में **नीति आयोग** ''SDG इंडिया इंडेक्स'' के माध्यम से राज्यों की प्रगति की निगरानी करता है। मध्य प्रदेश ने पिछले कुछ वर्षों में ''परफॉर्मर'' (Performer) श्रेणी से ''फ्रंट रनर'' (Front Runner) श्रेणी की ओर लंबी छलांग लगाई है।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. म.प्र. की वर्तमान रैंकिंग और स्कोर (Ranking & Score)"},{"type":"p","text":"नीति आयोग के नवीनतम SDG इंडिया इंडेक्स के अनुसार, मध्य प्रदेश के समग्र स्कोर में महत्वपूर्ण सुधार हुआ है।"},{"type":"table","instruction":"SDG इंडिया इंडेक्स: म.प्र. की स्थिति","head":["सूचकांक (Index)","म.प्र. का स्कोर","श्रेणी (Category)"],"body":[["SDG इंडिया इंडेक्स 1.0","52","आकांक्षी (Aspirant)"],["SDG इंडिया इंडेक्स 3.0","62","परफॉर्मर (Performer)"],["नवीनतम रिपोर्ट (2023-24)","66-68 (अनुमानित)","फ्रंट रनर (Front Runner)"]]},{"type":"h2","text":"2. लक्ष्य-वार प्रदर्शन (Goal-wise Performance)"},{"type":"p","text":"मध्य प्रदेश ने कुछ विशिष्ट लक्ष्यों में राष्ट्रीय स्तर पर उत्कृष्ट प्रदर्शन किया है, जबकि कुछ में अभी भी सुधार की आवश्यकता है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"म.प्र. का सर्वश्रेष्ठ एवं चुनौतीपूर्ण प्रदर्शन","head":["लक्ष्य संख्या","लक्ष्य का नाम (Goal)","म.प्र. की स्थिति"],"body":[["SDG 6","स्वच्छ जल और स्वच्छता","शीर्ष प्रदर्शन (नल से जल और ODF+ में प्रगति)"],["SDG 7","सस्ती और स्वच्छ ऊर्जा","उत्कृष्ट (सौर और अक्षय ऊर्जा परियोजनाओं के कारण)"],["SDG 15","भूमि पर जीवन (Life on Land)","शीर्ष (सर्वाधिक वन क्षेत्र के कारण)"],["SDG 2","शून्य भूख (Zero Hunger)","चुनौतीपूर्ण (कुपोषण और एनीमिया अभी भी चिंता का विषय)"],["SDG 5","लैंगिक समानता","सुधार जारी (लाड़ली बहना और लक्ष्मी योजनाओं का प्रभाव)"]]},{"type":"highlight","level":"important","text":"स्मरण तथ्य: मध्य प्रदेश ''SDG 15'' (Life on Land) में देश के शीर्ष राज्यों में शामिल है क्योंकि यहाँ भारत का सबसे बड़ा वन क्षेत्र है।","icon":"🌳"},{"type":"h2","text":"3. संस्थागत ढांचा और निगरानी (Institutional Framework)"},{"type":"fact_card","title":"SDG कार्यान्वयन इकाइयाँ","facts":["नोडल एजेंसी: म.प्र. राज्य योजना आयोग (State Planning Commission)।","विजन 2030: राज्य सरकार ने SDG लक्ष्यों को प्राप्त करने के लिए ''म.प्र. विजन 2030'' दस्तावेज तैयार किया है।","जिला रिपोर्ट कार्ड: राज्य अब जिला स्तर पर SDG प्रगति की निगरानी करने के लिए ''डिस्ट्रिक्ट इंडिकेटर फ्रेमवर्क'' (DIF) का उपयोग कर रहा है।","अटल बिहारी वाजपेयी संस्थान (AIGGPA): नीति विश्लेषण और डेटा निगरानी में सहयोग।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"नीति आयोग के ''SDG इंडिया इंडेक्स'' में राज्यों की प्रगति को कितनी श्रेणियों में विभाजित किया गया है?","options":["2","3","4","5"],"correct":"4","strategy":"श्रेणियाँ हैं: Aspirant (0-49), Performer (50-64), Front Runner (65-99), Achiever (100)।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"सतत विकास लक्ष्यों (SDG) को प्राप्त करने की समय सीमा क्या है?","options":["2022","2025","2030","2050"],"correct":"2030","strategy":"UN द्वारा निर्धारित वैश्विक समय सीमा ''एजेंडा 2030'' के तहत 2030 है।"},{"type":"exam_pattern","topic":"SDG Trend Analysis","analysis":"Unit 6 SDG Trend:","stats":["इंडेक्स स्कोर/रैंक: 1 प्रश्न","लक्ष्य संख्या (Goal Number): 1 प्रश्न","विशेष योजना और लक्ष्य का संबंध: 1 प्रश्न"],"trend":"आयोग अब सीधे लक्ष्यों के नाम (जैसे - SDG 5 क्या है?) और मध्य प्रदेश की ''Front Runner'' श्रेणी में स्थिति पर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 6: Progress of Sustainable Development Goals (SDG) in MP"},{"type":"p","text":"Sustainable Development Goals (SDGs) are a set of 17 global goals set by the UN to be achieved by 2030. In India, **NITI Aayog** monitors progress via the ''SDG India Index''. Madhya Pradesh has made a significant leap from the ''Performer'' category to the ''Front Runner'' category in recent years."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Current Ranking and Score of MP"},{"type":"p","text":"The overall score of Madhya Pradesh has seen marked improvement according to NITI Aayog''s reports."},{"type":"table","instruction":"SDG India Index: MP''s Status","head":["Index Version","MP Score","Category"],"body":[["SDG India Index 1.0","52","Aspirant"],["SDG India Index 3.0","62","Performer"],["Latest (2023-24)","66-68 (Est.)","Front Runner"]]},{"type":"h2","text":"2. Goal-wise Performance"},{"type":"table","instruction":"Best and Challenging Goal Performance in MP","head":["Goal No.","Goal Name","MP''s Performance Status"],"body":[["SDG 6","Clean Water & Sanitation","Top Performer (Nal se Jal & ODF+ progress)"],["SDG 7","Affordable & Clean Energy","Excellent (Solar/Renewable projects)"],["SDG 15","Life on Land","Top Performer (Due to largest forest cover)"],["SDG 2","Zero Hunger","Challenging (Malnutrition remains a concern)"],["SDG 5","Gender Equality","Improving (Impact of Ladli Behna/Laxmi schemes)"]]},{"type":"highlight","level":"important","text":"Fact: MP is among the top states for ''SDG 15'' (Life on Land) as it hosts the largest forest area in India.","icon":"🌳"},{"type":"h2","text":"3. Institutional Mechanism"},{"type":"fact_card","title":"SDG Implementation Units","facts":["Nodal Agency: MP State Planning Commission.","Vision 2030: The state government has prepared a ''MP Vision 2030'' document for goal alignment.","District Indicator Framework (DIF): Used to monitor SDG progress at the district level.","AIGGPA (Bhopal): Provides data analysis and policy support for SDGs."],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"How many categories are states divided into in NITI Aayog''s SDG India Index?","options":["2","3","4","5"],"correct":"4","strategy":"Categories: Aspirant (0-49), Performer (50-64), Front Runner (65-99), Achiever (100)."},{"type":"exam_pattern","topic":"SDG Trend Analysis","analysis":"Unit 6 SDG Trend:","stats":["Index Score/Rank: 1 question","Goal Numbers: 1 question","Schemes vs Goals: 1 question"],"trend":"Questions are shifting towards identifying specific goals (e.g., What is SDG 5?) and MP''s specific ranking."}]}', 'economy', NULL, 25, 1, 1770919642, 1771008899, 'blog', 'unit_6', 'Progress in Sustainable Development Goals in Madhya Pradesh', 1, 0, 1, 1, 0, 'Unit 6: मध्य प्रदेश में सतत विकास लक्ष्य (SDG) की प्रगति सतत विकास लक्ष्य (SDG) 17 वैश्विक लक्ष्यों का एक समूह है जिसे संयुक्त राष्ट्र द्वारा 2030 तक प्राप्त करने का लक्ष्य रखा गया है। भारत में **नीति...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('e1d43af6-8bb2-4856-9e2b-28c66d094d26', 'agriculture-industry-infrastructure-mp-unit-6', 'Agriculture, Industry & Infrastructure in MP | म.प्र. में कृषि, उद्योग और बुनियादी ढांचा विकास', 'A comprehensive analysis of the core economic sectors of Madhya Pradesh for MPPSC Unit 6. Covers agricultural growth, industrial hubs (MSME), and key infrastructure projects like Expressways.', '{"hi":[{"type":"h2","text":"Unit 6: मध्य प्रदेश में कृषि, उद्योग और बुनियादी ढांचा विकास"},{"type":"p","text":"मध्य प्रदेश की अर्थव्यवस्था का आधार इसके तीन मुख्य स्तंभ हैं: कृषि (जिसमें म.प्र. देश में अग्रणी है), उद्योग (विशेषकर MSME), और तेजी से विकसित होता बुनियादी ढांचा। MPPSC में ''कृषि कर्मण पुरस्कार'', ''औद्योगिक केंद्र'' और ''एक्सप्रेसवे'' से संबंधित प्रश्न बार-बार पूछे जाते हैं।"},{"type":"h2","text":"1. कृषि का विकास (Development of Agriculture)"},{"type":"p","text":"मध्य प्रदेश को लगातार कई वर्षों से ''कृषि कर्मण पुरस्कार'' मिल रहा है। राज्य की कृषि विकास दर भारत में सबसे अधिक (औसतन 18%+) रही है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"कृषि विकास के मुख्य घटक","head":["क्षेत्र","उपलब्धि/तथ्य","मुख्य जिले"],"body":[["सोयाबीन","म.प्र. भारत का ''सोया स्टेट'' है।","उज्जैन, धार, देवास।"],["गेहूं","शरबती गेहूं को GI टैग। ''गेहूं की डलिया'' (मालवा)।","होशंगाबाद, सीहोर।"],["उद्यानिकी","म.प्र. संतरा और लहसुन उत्पादन में अग्रणी है।","मंदसौर (लहसुन), आगर मालवा।"],["सिंचाई विकास","सिंचाई क्षमता 7.5 लाख हेक्टे. से बढ़कर 45 लाख हेक्टे. हुई।","नर्मदा घाटी क्षेत्र।"]]},{"type":"h2","text":"2. उद्योग और MSME विकास (Industry & MSME)"},{"type":"p","text":"राज्य में ''ईज ऑफ डूइंग बिजनेस'' के तहत औद्योगिक गलियारों (Industrial Corridors) का विकास किया जा रहा है।"},{"type":"image_tag","content":""},{"type":"ul","items":["**पीथमपुर (धार):** ''भारत का डेट्रायट'' कहलाता है। यहाँ प्रमुख ऑटोमोबाइल उद्योग हैं।","**मंडीदीप (रायसेन):** यहाँ जापान के सहयोग से ''ऑप्टिकल फाइबर'' कारखाना स्थित है।","**MSME क्लस्टर:** राज्य में चमड़ा क्लस्टर (देवास), फार्मा क्लस्टर (इंदौर), और नमकीन क्लस्टर (रतलाम) विकसित किए गए हैं।","**स्टार्टअप नीति 2022:** इंदौर को राज्य का स्टार्टअप हब बनाने पर जोर।"]},{"type":"highlight","level":"important","text":"विशेष: मध्य प्रदेश का पहला ''ड्राय पोर्ट'' (Dry Port) पीथमपुर (धार) में स्थापित किया गया है।","icon":"📦"},{"type":"h2","text":"3. बुनियादी ढांचा विकास (Infrastructure Development)"},{"type":"fact_card","title":"कनेक्टिविटी और ऊर्जा","facts":["नर्मदा प्रगति पथ (Narmada Expressway): राज्य के पूर्वी और पश्चिमी छोर को जोड़ने वाला महात्वाकांक्षी प्रोजेक्ट।","विंध्य एक्सप्रेसवे: भोपाल को सिंगरौली से जोड़ने वाला आर्थिक गलियारा।","अटल प्रगति पथ: चंबल क्षेत्र के विकास के लिए (श्योपुर, मुरैना, भिंड)।","ऊर्जा: म.प्र. एक ''पावर सरप्लस'' राज्य है। ओंकारेश्वर में विश्व का सबसे बड़ा तैरता (Floating) सोलर प्लांट।"],"icon":"🛣️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश में ''निर्यात संवर्धन औद्योगिक पार्क'' (EPIP) कहाँ स्थित है?","options":["इंदौर","पीथमपुर","बीना","मंडीदीप"],"correct":"पीथमपुर","strategy":"पीथमपुर धार जिले में है और इसे औद्योगिक हब के रूप में विकसित किया गया है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"मध्य प्रदेश को अब तक कितनी बार ''कृषि कर्मण पुरस्कार'' मिला है?","options":["5 बार","6 बार","7 बार","8 बार"],"correct":"7 बार (उस समय के डेटा अनुसार)","strategy":"यह पुरस्कार कुल खाद्यान्न उत्पादन में श्रेष्ठता के लिए दिया जाता है।"},{"type":"exam_pattern","topic":"Eco-Dev Trend","analysis":"Unit 6 Development Analysis:","stats":["औद्योगिक केंद्र/नवाचार: 2 प्रश्न","कृषि डेटा (GI टैग/उत्पादन): 1 प्रश्न","परिवहन/एक्सप्रेसवे: 1 प्रश्न"],"trend":"आयोग अब ''एक जिला एक उत्पाद'' (ODOP) और ''पीएम मित्र पार्क'' (धार) जैसे नवीनतम औद्योगिक प्रोजेक्ट्स पर अधिक प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 6: Agriculture, Industry & Infrastructure Development in MP"},{"type":"p","text":"The economy of Madhya Pradesh rests on three pillars: Agriculture (where MP leads nationally), Industry (specifically MSMEs), and rapidly developing Infrastructure. MPPSC frequently asks about ''Krishi Karman Awards'', ''Industrial Hubs'', and ''Expressways''."},{"type":"h2","text":"1. Development of Agriculture"},{"type":"p","text":"Madhya Pradesh has been consistently receiving the ''Krishi Karman Award''. The state''s agricultural growth rate has been the highest in India (Avg 18%+)."},{"type":"image_tag","content":""},{"type":"table","instruction":"Key Components of Agri-Development","head":["Sector","Achievement/Fact","Key Districts"],"body":[["Soybean","MP is the ''Soya State'' of India.","Ujjain, Dhar, Dewas."],["Wheat","Sharbati Wheat has GI Tag. Malwa is the ''Wheat Basket''.","Hoshangabad, Sehore."],["Horticulture","Leader in Orange and Garlic production.","Mandsaur (Garlic), Agar Malwa."],["Irrigation","Increased from 7.5 lakh hectares to 45 lakh hectares.","Narmada Valley region."]]},{"type":"h2","text":"2. Industry & MSME Development"},{"type":"image_tag","content":""},{"type":"ul","items":["**Pithampur (Dhar):** Known as the ''Detroit of India'' due to its massive automobile hub.","**Mandideep (Raisen):** Houses the Optical Fiber factory established with Japanese collaboration.","**MSME Clusters:** Leather cluster (Dewas), Pharma cluster (Indore), and Namkeen cluster (Ratlam).","**Startup Policy 2022:** Focus on making Indore the startup capital of the state."]},{"type":"highlight","level":"important","text":"Fact: The first ''Dry Port'' of Madhya Pradesh was established in Pithampur (Dhar).","icon":"📦"},{"type":"h2","text":"3. Infrastructure Development"},{"type":"fact_card","title":"Connectivity & Energy","facts":["Narmada Pragati Path: An ambitious expressway connecting the eastern and western ends of the state.","Vindhya Expressway: An economic corridor connecting Bhopal to Singrauli.","Atal Pragati Path: Designed for the development of the Chambal region (Sheopur, Morena, Bhind).","Energy: MP is a power-surplus state. World''s largest floating solar plant is at Omkareshwar."],"icon":"🛣️"},{"type":"exam_pattern","topic":"Eco-Dev Trend","analysis":"Unit 6 Development Analysis:","stats":["Industrial Hubs/Innovation: 2 questions","Agri Data (GI Tags/Production): 1 question","Transport/Expressways: 1 question"],"trend":"The Commission is now focusing on ''One District One Product'' (ODOP) and the ''PM Mitra Park'' (Dhar) among other latest industrial projects."}]}', 'economy', NULL, 35, 1, 1770919687, 1771008900, 'blog', 'unit_6', 'Development of Agriculture, Industry, MSME and Infrastructure Development in Madhya Pradesh', 1, 0, 1, 1, 0, 'Unit 6: मध्य प्रदेश में कृषि, उद्योग और बुनियादी ढांचा विकास मध्य प्रदेश की अर्थव्यवस्था का आधार इसके तीन मुख्य स्तंभ हैं: कृषि (जिसमें म.प्र. देश में अग्रणी है), उद्योग (विशेषकर MSME), और तेजी से विक...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('57d9a120-1819-4116-8984-576b5d8a14fe', 'atmanirbhar-mp-odop-unit-6-mppsc', 'Atmanirbhar MP & One District One Product (ODOP) | आत्मनिर्भर म.प्र. और एक जिला एक उत्पाद', 'Comprehensive guide to the ''Atmanirbhar Madhya Pradesh Roadmap 2023'' and the ''One District One Product'' (ODOP) initiative. Essential for MPPSC Unit 6, covering economic self-reliance and district-wise product specializations.', '{"hi":[{"type":"h2","text":"Unit 6: आत्मनिर्भर मध्य प्रदेश और एक जिला एक उत्पाद (ODOP)"},{"type":"p","text":"प्रधानमंत्री के ''आत्मनिर्भर भारत'' के संकल्प को साकार करने के लिए मध्य प्रदेश ने ''आत्मनिर्भर मध्य प्रदेश रोडमैप 2023'' तैयार किया है। इसके साथ ही, स्थानीय कला और उत्पादों को वैश्विक पहचान दिलाने के लिए ''एक जिला एक उत्पाद'' (ODOP) योजना शुरू की गई है। MPPSC में इन योजनाओं के स्तंभों और विशिष्ट जिलों के उत्पादों के मिलान पर प्रश्न निश्चित रूप से पूछे जाते हैं।"},{"type":"h2","text":"1. आत्मनिर्भर मध्य प्रदेश रोडमैप (Self-Reliant MP Roadmap)"},{"type":"p","text":"आत्मनिर्भर म.प्र. का रोडमैप मुख्य रूप से चार स्तंभों (Four Pillars) पर आधारित है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"आत्मनिर्भर म.प्र. के 4 स्तंभ","head":["स्तंभ (Pillar)","मुख्य ध्यान (Focus Area)"],"body":[["भौतिक अधोसंरचना (Infrastructure)","एक्सप्रेसवे (नर्मदा/अटल), सिंचाई और ऊर्जा विकास।"],["सुशासन (Governance)","ई-गवर्नेंस, पारदर्शिता और लोक सेवा गारंटी का सरलीकरण।"],["शिक्षा एवं स्वास्थ्य","सीएम राइज स्कूल, मेडिकल कॉलेजों का विस्तार और कौशल विकास।"],["अर्थव्यवस्था एवं रोजगार","कृषि विविधीकरण, MSME क्लस्टर और निवेश प्रोत्साहन।"]]},{"type":"h2","text":"2. एक जिला एक उत्पाद (One District One Product - ODOP)"},{"type":"p","text":"ODOP का उद्देश्य प्रत्येक जिले की एक विशिष्ट पहचान बनाना और स्थानीय कारीगरों की आय बढ़ाना है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"प्रमुख जिले और उनके ODOP उत्पाद","head":["जिला (District)","चयनित उत्पाद (Product)","विशेष तथ्य"],"body":[["मुरैना","सरसों एवं शहद","मुरैना ''सरसों की डलिया'' के रूप में प्रसिद्ध है।"],["रतलाम","रतलामी सेव (Namkeen)","इसे GI टैग भी प्राप्त है।"],["बालाघाट","चिन्नौर चावल","म.प्र. का पहला कृषि GI टैग प्राप्त चावल।"],["बुरहानपुर","केला (Banana)","यहाँ केले के चिप्स और फाइबर उद्योग विकसित हैं।"],["मंडला","कोदो-कुटकी (Millets)","पौष्टिक मोटे अनाज हेतु प्रसिद्ध।"],["छिंदवाड़ा","संतरा एवं मक्का","छिंदवाड़ा को ''कॉर्न सिटी'' कहा जाता है।"],["खरगोन","लाल मिर्च (Red Chilli)","बेड़िया मिर्च मंडी एशिया की बड़ी मंडियों में से एक।"]]},{"type":"highlight","level":"important","text":"विशेष: चिन्नौर चावल (बालाघाट) को मध्य प्रदेश के पहले कृषि उत्पाद के रूप में भौगोलिक संकेतक (GI Tag) मिला है।","icon":"🌾"},{"type":"h2","text":"3. अर्थव्यवस्था में प्रभाव (Economic Impact)"},{"type":"ul","items":["**स्थानीय रोजगार:** ODOP के माध्यम से ग्रामीण क्षेत्रों में कुटीर उद्योगों को बढ़ावा मिला है।","**निर्यात वृद्धि:** इंदौर से ''आलू'' और सागर से ''कृषि उपकरण'' का बड़े पैमाने पर निर्यात हो रहा है।","**ब्रांडिंग:** ''मध्य प्रदेश के उत्पाद - विश्व के लिए'' (Products of MP for the World) की ब्रांडिंग पर जोर।"]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"किस जिले के ''चिन्नौर चावल'' को GI टैग प्रदान किया गया है?","options":["बालाघाट","मंडला","रीवा","सीहोर"],"correct":"बालाघाट","strategy":"बालाघाट पूर्वी म.प्र. में है और धान उत्पादन का मुख्य केंद्र है।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"आत्मनिर्भर मध्य प्रदेश रोडमैप 2023 किस तिथि को जारी किया गया था?","options":["12 नवंबर 2020","26 जनवरी 2021","15 अगस्त 2020","1 जनवरी 2023"],"correct":"12 नवंबर 2020","strategy":"यह रोडमैप 3 साल (2020-2023) के लक्ष्यों के लिए नवंबर 2020 में लॉन्च हुआ था।"},{"type":"exam_pattern","topic":"ODOP & Roadmap Trend","analysis":"Unit 6 Trend Analysis:","stats":["जिला और उत्पाद (Matching): 2 प्रश्न","संवैधानिक/रोडमैप स्तंभ: 1 प्रश्न","GI टैग नवीनतम: 1 प्रश्न"],"trend":"आयोग अब ''एक जिला एक उत्पाद'' के तहत चुने गए उत्पादों के निर्यात आंकड़ों और उनके ''प्रसंस्करण केंद्रों'' (Processing Units) पर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 6: Atmanirbhar Madhya Pradesh and ODOP"},{"type":"p","text":"To realize the vision of ''Atmanirbhar Bharat'', Madhya Pradesh prepared the ''Atmanirbhar Madhya Pradesh Roadmap 2023''. Additionally, the ''One District One Product'' (ODOP) scheme was launched to give global identity to local crafts and produce. In MPPSC, questions are certain on matching the 4 pillars and specific district products."},{"type":"h2","text":"1. Atmanirbhar Madhya Pradesh Roadmap"},{"type":"p","text":"The roadmap for a self-reliant MP is based on four fundamental pillars."},{"type":"image_tag","content":""},{"type":"table","instruction":"4 Pillars of Atmanirbhar MP","head":["Pillar","Core Focus Area"],"body":[["Infrastructure","Expressways (Narmada/Atal), Irrigation, and Power."],["Governance","E-Governance, Transparency, and simplification of Public Service Delivery."],["Education & Health","CM Rise Schools, expansion of Medical Colleges, and Skill Development."],["Economy & Employment","Agri-diversification, MSME clusters, and Investment promotion."]]},{"type":"h2","text":"2. One District One Product (ODOP)"},{"type":"p","text":"ODOP aims to create a distinct identity for each district and enhance the income of local artisans."},{"type":"image_tag","content":""},{"type":"table","instruction":"Major Districts and Their ODOP Products","head":["District","Selected Product","Key Fact"],"body":[["Morena","Mustard & Honey","Morena is famous as the ''Mustard Bowl''."],["Ratlam","Ratlam Sev (Namkeen)","It also holds a GI Tag."],["Balaghat","Chinnor Rice","First agricultural GI Tag product of MP."],["Burhanpur","Banana","Banana chips and fiber industries are developed here."],["Mandla","Kodo-Kutki (Millets)","Known for nutritious coarse grains."],["Chhindwara","Orange & Maize","Chhindwara is designated as the ''Corn City''."],["Khargone","Red Chilli","Bediya Chilli Mandi is one of the largest in Asia."]]},{"type":"highlight","level":"important","text":"Fact: Chinnor Rice (Balaghat) is the first agricultural product from MP to receive the Geographical Indication (GI Tag).","icon":"🌾"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"''Chinnor Rice'', which received the GI Tag, belongs to which district?","options":["Balaghat","Mandla","Rewa","Sehore"],"correct":"Balaghat","strategy":"Balaghat is in Eastern MP and is the primary hub for paddy production."},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"On which date was the Atmanirbhar Madhya Pradesh Roadmap 2023 released?","options":["12 Nov 2020","26 Jan 2021","15 Aug 2020","1 Jan 2023"],"correct":"12 Nov 2020","strategy":"Launched in Nov 2020 to set targets for the subsequent 3 years."},{"type":"exam_pattern","topic":"ODOP & Roadmap Trend","analysis":"Unit 6 Trend Analysis:","stats":["District & Product (Matching): 2 questions","Roadmap Pillars: 1 question","Latest GI Tags: 1 question"],"trend":"The Commission is now focusing on the export statistics of ODOP products and their related ''Processing Units''."}]}', 'economy', NULL, 25, 1, 1770919744, 1770919744, 'blog', 'unit_6', 'Self-Reliant Madhya Pradesh, One District One Product (ODOP)', 1, 0, 0, 1, 0, 'Unit 6: आत्मनिर्भर मध्य प्रदेश और एक जिला एक उत्पाद (ODOP) प्रधानमंत्री के ''आत्मनिर्भर भारत'' के संकल्प को साकार करने के लिए मध्य प्रदेश ने ''आत्मनिर्भर मध्य प्रदेश रोडमैप 2023'' तैयार किया है। इसके साथ ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('7ff40013-f257-4ae6-afd7-4ae6e686dfe7', 'ipr-gi-tags-madhya-pradesh-unit-6-mppsc', 'IPR and GI Tags in Madhya Pradesh | म.प्र. में बौद्धिक संपदा अधिकार और GI टैग', 'A comprehensive analysis of Intellectual Property Rights (IPR) and Geographical Indications (GI) in Madhya Pradesh for MPPSC Unit 6. Covers the list of GI tags, patent trends, and institutional support.', '{"hi":[{"type":"h2","text":"Unit 6: मध्य प्रदेश में बौद्धिक संपदा अधिकार (IPR) की प्रगति"},{"type":"p","text":"बौद्धिक संपदा अधिकार (IPR) नवाचार और रचनात्मकता को प्रोत्साहित करते हैं। मध्य प्रदेश में पिछले कुछ वर्षों में विशेष रूप से ''भौगोलिक संकेतक'' (GI Tag) और ''पेटेंट'' के क्षेत्र में उल्लेखनीय प्रगति हुई है। MPPSC में राज्य के विशिष्ट उत्पादों को मिले GI टैग और उनकी विशेषताओं पर प्रश्न अनिवार्य रूप से पूछे जाते हैं।"},{"type":"h2","text":"1. भौगोलिक संकेतक (Geographical Indications - GI Tag)"},{"type":"p","text":"GI टैग किसी उत्पाद की विशिष्ट भौगोलिक उत्पत्ति और उसकी गुणवत्ता की पहचान है। मध्य प्रदेश में वर्तमान में 15 से अधिक उत्पादों को GI टैग मिल चुका है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"मध्य प्रदेश के प्रमुख GI टैग (Major GI Tags of MP)","head":["उत्पाद (Product)","क्षेत्र (District/Region)","विशेषता"],"body":[["चंदेरी साड़ी","अशोकनगर","म.प्र. का पहला GI टैग (2004-05)।"],["कड़कनाथ मुर्गा","झाबुआ","अपनी उच्च प्रोटीन और कम वसा के लिए प्रसिद्ध।"],["चिन्नौर चावल","बालाघाट","म.प्र. का पहला कृषि GI टैग (2021)।"],["महेश्वरी साड़ी","खरगोन (महेश्वर)","अहिल्याबाई होल्कर के संरक्षण में विकसित।"],["बाग प्रिंट","धार","लकड़ी के ब्लॉक से हाथ की छपाई।"],["सुंदरजा आम","रीवा","अपनी मिठास और सुगंध के लिए प्रसिद्ध।"],["शरबती गेहूं","सीहोर/विदिशा","इसे ''गोल्डन ग्रेन'' भी कहा जाता है।"],["गोंड पेंटिंग","डिंडोरी","जनजातीय कला का उत्कृष्ट प्रदर्शन।"]]},{"type":"h2","text":"2. पेटेंट और अन्य IPR क्षेत्र (Patents & Other IPRs)"},{"type":"ul","items":["**पेटेंट:** आईआईटी इंदौर और मैनिट (MANIT) भोपाल जैसे संस्थानों के कारण पेटेंट फाइलिंग में वृद्धि हुई है।","**ट्रेडमार्क:** राज्य के MSME क्षेत्र में ब्रांडिंग हेतु ट्रेडमार्क पंजीकरण में तेजी आई है।","**IPR सेल:** मध्य प्रदेश विज्ञान एवं प्रौद्योगिकी परिषद (MPCST) भोपाल में एक विशेष IPR सेल संचालित है जो वैज्ञानिकों और कारीगरों की सहायता करती है।"]},{"type":"highlight","level":"important","text":"विशेष: हाल ही में उज्जैन के ''बाटिक प्रिंट'', डिंडोरी की ''लोहशिल्प'' और ग्वालियर के ''हस्तनिर्मित कालीन'' को भी GI टैग प्रदान किया गया है।","icon":"🎨"},{"type":"h2","text":"3. संस्थागत ढांचा (Institutional Support)"},{"type":"fact_card","title":"IPR संवर्धन पहल","facts":["म.प्र. राज्य बौद्धिक संपदा अधिकार नीति: नवाचार को बढ़ावा देने के लिए राज्य की अपनी नीति।","जीआई महोत्सव: ग्वालियर और अन्य शहरों में स्थानीय उत्पादों की प्रदर्शनी हेतु आयोजन।","कौशल विकास: कारीगरों को अपने उत्पाद पंजीकृत करने के लिए प्रशिक्षण प्रदान करना।","निर्यात प्रोत्साहन: GI टैग मिलने से अंतरराष्ट्रीय बाजारों (जैसे यूरोप और अमेरिका) में म.प्र. के उत्पादों की मांग बढ़ी है।"],"icon":"⚖️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश के किस जिले को ''कड़कनाथ मुर्गे'' के लिए GI टैग मिला है?","options":["झाबुआ","धार","बड़वानी","मंडला"],"correct":"झाबुआ","strategy":"कड़कनाथ पूरी तरह से काला होता है और झाबुआ की जनजातीय पहचान है।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"मध्य प्रदेश का प्रथम भौगोलिक संकेतक (GI Tag) उत्पाद कौन सा था?","options":["महेश्वरी साड़ी","चंदेरी साड़ी","इंदौर के चमड़े के खिलौने","रतलामी सेव"],"correct":"चंदेरी साड़ी","strategy":"चंदेरी साड़ी को 2004-05 में सबसे पहले यह दर्जा मिला था।"},{"type":"exam_pattern","topic":"IPR & GI Trend","analysis":"Unit 6 Trend Analysis:","stats":["GI टैग और संबंधित जिला: 2 प्रश्न","IPR संस्थान/नीति: 1 प्रश्न","नवीनतम GI टैग (करंट अफेयर्स): 1 प्रश्न"],"trend":"आयोग अब केवल पुराने GI टैग नहीं, बल्कि पिछले 1 साल में मिले नए टैग्स (जैसे - मुरैना की गजक) पर अधिक ध्यान दे रहा है।"}],"en":[{"type":"h2","text":"Unit 6: Progress of IPR in Madhya Pradesh"},{"type":"p","text":"Intellectual Property Rights (IPR) foster innovation and creativity. In recent years, Madhya Pradesh has made significant strides, particularly in ''Geographical Indications'' (GI Tags) and ''Patents''. In MPPSC, questions are mandatory on the state''s specific GI-tagged products and their origins."},{"type":"h2","text":"1. Geographical Indications (GI Tag)"},{"type":"p","text":"A GI tag identifies a product as originating in a specific territory, where a given quality or reputation is attributable to its geographical origin."},{"type":"table","instruction":"Major GI Tags of Madhya Pradesh","head":["Product","District/Region","Key Feature"],"body":[["Chanderi Saree","Ashoknagar","First GI tag of MP (2004-05)."],["Kadaknath Chicken","Jhabua","Known for high protein and low fat."],["Chinnor Rice","Balaghat","First agricultural GI tag of MP (2021)."],["Maheshwari Saree","Khargone","Developed under Queen Ahilyabai''s patronage."],["Bagh Prints","Dhar","Traditional hand-block printing."],["Sunderja Mango","Rewa","Famous for its unique taste and aroma."],["Sharbati Wheat","Sehore/Vidisha","Referred to as the ''Golden Grain''."],["Gond Painting","Dindori","Traditional tribal art form."]]},{"type":"highlight","level":"important","text":"Note: Recently, Morena''s ''Gajak'', Ujjain''s ''Batik Print'', and Gwalior''s ''Handmade Carpets'' have also secured GI tags.","icon":"🎨"},{"type":"h2","text":"2. Patents and Institutional Framework"},{"type":"fact_card","title":"IPR Support in MP","facts":["IPR Cell: Located at MPCST Bhopal, providing technical help to local innovators.","Nodal Agency: Ministry of Commerce & Industry (DPIIT) manages these at the national level.","Growth: Significant increase in patent filings from IIT Indore and MANIT Bhopal.","Branding: ''Atmanirbhar MP'' focus on taking local GI products to global markets."],"icon":"⚖️"},{"type":"exam_pattern","topic":"IPR & GI Trend","analysis":"Unit 6 Trend Analysis:","stats":["GI Tag and District matching: 2 questions","Policy/Institutions: 1 question","Recent GI Tags: 1 question"],"trend":"The Commission is now focusing on products that received GI tags in the last 12-18 months alongside traditional ones."}]}', 'economy', NULL, 20, 1, 1770919790, 1770919790, 'blog', 'unit_6', 'Progress of Intellectual Property Rights (IPR) in Madhya Pradesh', 1, 0, 0, 1, 0, 'Unit 6: मध्य प्रदेश में बौद्धिक संपदा अधिकार (IPR) की प्रगति बौद्धिक संपदा अधिकार (IPR) नवाचार और रचनात्मकता को प्रोत्साहित करते हैं। मध्य प्रदेश में पिछले कुछ वर्षों में विशेष रूप से ''भौगोलिक संकेतक''...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('e76a0728-aeaf-4ea0-b0ef-50d8e5878317', 'recent-trends-indian-economy-unit-6-mppsc', 'Recent Trends in Indian Economy: 2025-26 | भारतीय अर्थव्यवस्था के नवीन रुझान', 'Comprehensive guide to the latest economic trends in India''s Agriculture, Industry, and Service sectors based on Economic Survey 2025-26 for MPPSC Unit 6.', '{"hi":[{"type":"h2","text":"Unit 6: भारतीय अर्थव्यवस्था के नवीन रुझान (2025-26)"},{"type":"p","text":"भारतीय अर्थव्यवस्था वर्तमान में ''विकसित भारत @ 2047'' के लक्ष्य की ओर अग्रसर है। आर्थिक सर्वेक्षण 2025-26 के अनुसार, भारत ने वैश्विक अनिश्चितताओं के बावजूद 7.4% की वास्तविक जीडीपी वृद्धि दर दर्ज की है। MPPSC Unit 6 के लिए कृषि, उद्योग और सेवा क्षेत्रों में आ रहे ढांचागत बदलावों (Structural Changes) को समझना अनिवार्य है।"},{"type":"h2","text":"1. कृषि क्षेत्र में नवीन प्रवृत्तियाँ (Trends in Agriculture)"},{"type":"p","text":"कृषि अब केवल खाद्यान्न उत्पादन तक सीमित नहीं है; यह एक तकनीकी और मूल्य-संचालित क्षेत्र बन गया है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"कृषि: नवीनतम आंकड़े और रुझान","head":["विषय","रुझान (Latest Trends)","डेटा/तथ्य (2025-26)"],"body":[["खाद्यान्न उत्पादन","रिकॉर्ड उत्पादन स्तर","3,577.3 लाख मीट्रिक टन (LMT) का नया रिकॉर्ड।"],["सम्बद्ध क्षेत्र (Allied)","पशुपालन और मत्स्य पालन का उदय","पशुपालन क्षेत्र में 12.7% की CAGR दर्ज की गई।"],["डिजिटलीकरण","AgriGOI और डिजिटल एग्री स्टैक","ड्रोन और IoT का उपयोग ''स्मार्ट खेती'' हेतु बढ़ा।"],["श्री अन्न (Millets)","वैश्विक पोषण हब के रूप में पहचान","मोटे अनाज के उत्पादन और निर्यात पर विशेष जोर।"]]},{"type":"highlight","level":"important","text":"विशेष: कृषि क्षेत्र में ''उद्यानिकी'' (Horticulture) का योगदान अब खाद्यान्न से अधिक (367 MT) हो गया है, जो कृषि विविधीकरण का प्रतीक है।","icon":"🌾"},{"type":"h2","text":"2. औद्योगिक क्षेत्र की गति (Industrial & Manufacturing Momentum)"},{"type":"p","text":"भारत अब ''लो-टेक'' असेंबली से ''हाई-टेक'' विनिर्माण (High-tech Manufacturing) की ओर बढ़ रहा है।"},{"type":"image_tag","content":""},{"type":"ul","items":["**PLI योजना 2.0:** 14 क्षेत्रों में उत्पादन-लिंक्ड प्रोत्साहन से विनिर्माण GVA में 9.13% की वृद्धि दर्ज की गई।","**हाई-टेक विनिर्माण:** भारत के कुल विनिर्माण मूल्यवर्धन में मध्यम और उच्च तकनीक उद्योगों का हिस्सा 46.3% तक पहुँच गया है।","**कोर सेक्टर:** इस्पात (Steel) और सीमेंट उत्पादन में दोहरे अंकों की वृद्धि दर्ज की गई, जो बुनियादी ढांचे में तेजी को दर्शाती है।","**MSME सुधार:** 2025 के बजट में MSME की परिभाषा को सरल बनाया गया और क्रेडिट गारंटी सीमा बढ़ाई गई।"]},{"type":"h2","text":"3. सेवा क्षेत्र: विकास का इंजन (Service Sector)"},{"type":"table","instruction":"सेवा क्षेत्र: नवीन रुझान","head":["क्षेत्र","रुझान","विवरण"],"body":[["GVA योगदान","ऐतिहासिक उच्च स्तर","GVA में सेवा क्षेत्र का हिस्सा 56.4% तक पहुँच गया।"],["डिजिटल सेवाएं","ज्ञान-आधारित निर्यात","भारत अब दुनिया का 7वां सबसे बड़ा सेवा निर्यातक है।"],["नवीनतम क्षेत्र","ऑरेंज इकोनॉमी (कला-संस्कृति)","पर्यटन, कला और मनोरंजन क्षेत्र में नए रोजगार का सृजन।"],["फिनटेक","डिजिटल भुगतान क्रांति","UPI के माध्यम से वैश्विक स्तर पर भुगतान का नेतृत्व।"]]},{"type":"highlight","level":"critical","text":"रुझान: अंतरिक्ष (Space) और महासागर (Blue Economy) सेवाओं को अब निजी भागीदारी के माध्यम से व्यावसायिक स्तर पर विकसित किया जा रहा है।","icon":"🚀"},{"type":"h2","text":"4. प्रमुख आर्थिक सुधार (Key Reforms 2025-26)"},{"type":"fact_card","title":"आर्थिक नीति में बदलाव","facts":["नया आयकर अधिनियम 2025: कर प्रणाली को सरल बनाने हेतु पुराने 1961 के एक्ट को बदला गया।","श्रम संहिता (Labour Codes): 29 कानूनों को 4 संहिताओं में एकीकृत कर लागू किया गया।","विकसित भारत गारंटी (Gramin) एक्ट: मनरेगा (MGNREGA) के स्थान पर नया आधुनिक ढांचा।","निर्यात प्रोत्साहन मिशन (EPM): ₹25,060 करोड़ के परिव्यय के साथ MSME निर्यात पर ध्यान।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भारतीय अर्थव्यवस्था में किस क्षेत्र का योगदान सर्वाधिक है?","options":["प्राथमिक","द्वितीयक","तृतीयक (सेवा)","इनमें से कोई नहीं"],"correct":"तृतीयक (सेवा)","strategy":"सेवा क्षेत्र (Tertiary) 50% से अधिक योगदान के साथ सबसे बड़ा क्षेत्र बना हुआ है।"},{"type":"pyq","exam":"MPPSC Mains GS-2","year":2020,"question":"भारतीय विनिर्माण क्षेत्र में सुधार हेतु सरकारी प्रयासों का मूल्यांकन करें। (11 marks)","answer":"इसमें मेक इन इंडिया, PLI योजना और इज ऑफ डूइंग बिजनेस (EoDB) का उल्लेख करना अनिवार्य है।","strategy":"उत्तर में वर्तमान GVA डेटा (9%+) और हाई-टेक विनिर्माण का चार्ट जरूर बनाएं।"},{"type":"exam_pattern","topic":"Economy Trend","analysis":"Unit 6 Trend Analysis:","stats":["क्षेत्रवार वृद्धि दर (%): 2 प्रश्न","नवीनतम योजनाएं/अधिनियम: 1 प्रश्न","निर्यात-आयात डेटा: 1 प्रश्न"],"trend":"आयोग अब बजट के ''राजकोषीय घाटे'' के साथ-साथ ''डिजिटल इंफ्रास्ट्रक्चर'' और ''ग्रीन ट्रांजिशन'' पर अधिक ध्यान दे रहा है।"}],"en":[{"type":"h2","text":"Unit 6: Recent Trends in Indian Economy (2025-26)"},{"type":"p","text":"The Indian economy is currently progressing towards the goal of ''Viksit Bharat @ 2047''. According to the Economic Survey 2025-26, India recorded a real GDP growth rate of 7.4%. For MPPSC Unit 6, understanding the structural shifts in Agriculture, Industry, and Services is crucial."},{"type":"h2","text":"1. Trends in Agriculture"},{"type":"table","instruction":"Agriculture: Latest Trends","head":["Segment","Trend","Data/Fact"],"body":[["Foodgrains","Record Production","Record high of 3,577.3 Lakh Metric Tonnes (LMT)."],["Allied Sector","Rising Prominence","Livestock recorded a CAGR of 12.7%."],["Digitalization","AgriGOI and Drones","Integration of AI/IoT for precision farming."],["Shree Anna","Global Nutrition Hub","Shift towards Coarse Cereals and export branding."]]},{"type":"h2","text":"2. Industrial & Manufacturing Momentum"},{"type":"ul","items":["**PLI 2.0:** Driving manufacturing GVA growth up to 9.13%.","**High-Tech Shift:** Medium and high-tech industries now contribute 46.3% of manufacturing value added.","**MSME Reforms:** Revised thresholds (Budget 2025-26) and doubled credit guarantee cover.","**Core Sectors:** Double-digit growth in Steel and Cement production due to infra push."]},{"type":"h2","text":"3. Services: The Dominant Engine"},{"type":"table","instruction":"Service Sector Trends","head":["Sector","Trend","Detail"],"body":[["GVA Share","Historical High","Services share in GVA reached 56.4%."],["Exports","Knowledge Intensive","India is now the 7th largest service exporter globally."],["New Areas","Orange & Blue Economy","Expansion into art, culture, and maritime services."],["Space Services","Commercialization","Rapid growth in private participation in space tech."]]},{"type":"exam_pattern","topic":"Economy Trend","analysis":"Unit 6 Analysis:","stats":["Sectoral Growth Rates: 2 questions","Latest Acts/Schemes: 1 question","Export-Import Trends: 1 question"],"trend":"Questions are shifting towards ''Digital Infrastructure'' and ''Climate-Resilient Projects'' over traditional stats."}]}', 'economy', NULL, 35, 1, 1770919832, 1770919832, 'blog', 'unit_6', 'Recent Trends in Indian Economy: Agriculture, Industry and Service sectors', 1, 0, 0, 1, 0, 'Unit 6: भारतीय अर्थव्यवस्था के नवीन रुझान (2025-26) भारतीय अर्थव्यवस्था वर्तमान में ''विकसित भारत @ 2047'' के लक्ष्य की ओर अग्रसर है। आर्थिक सर्वेक्षण 2025-26 के अनुसार, भारत ने वैश्विक अनिश्चितताओं के ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('9c288734-c1bf-4110-a610-2c3b2314ee3c', 'financial-institutions-india-unit-6-mppsc-2026', 'Indian Financial Institutions: RBI, Banks, SEBI & NBFCs | भारतीय वित्तीय संस्थान', 'A comprehensive deep-dive into India''s financial architecture for MPPSC Unit 6. Covers the regulatory roles of RBI and SEBI, the evolution of Commercial Banks, and the rising significance of NBFCs in 2026.', '{"hi":[{"type":"h2","text":"Unit 6: भारत की वित्तीय संस्थाएं (Financial Architecture 2026)"},{"type":"p","text":"भारतीय अर्थव्यवस्था की धड़कन यहाँ की वित्तीय संस्थाएं हैं। 2026 के संदर्भ में, भारत का वित्तीय ढांचा अब पारंपरिक बैंकिंग से ''डिजिटल बैंकिंग'' और ''इंस्टेंट सेटलमेंट'' की ओर पूरी तरह स्थानांतरित हो चुका है। MPPSC के लिए RBI के मौद्रिक उपकरण (Monetary Tools), बैंकों का एकीकरण (Mergers), SEBI के कड़े नियम और NBFCs की ग्रामीण पहुंच को समझना अनिवार्य है।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. भारतीय रिज़र्व बैंक (RBI) - बैंकों का बैंक"},{"type":"p","text":"RBI भारत का केंद्रीय बैंक है, जिसकी स्थापना 1 अप्रैल 1935 को हुई थी। 2026 में RBI का मुख्य फोकस ''डिजिटल रुपया'' (e-Rupee) और ''मुद्रास्फीति नियंत्रण'' (Inflation Control) पर है।"},{"type":"table","instruction":"RBI के प्रमुख कार्य और उपकरण","head":["कार्य/उपकरण","विवरण (Context 2026)"],"body":[["मौद्रिक नीति (MPC)","6 सदस्यीय समिति जो रेपो रेट (Repo Rate) तय करती है।"],["डिजिटल करेंसी (CBDC)","e-Rupee का व्यापक प्रचलन, जो फिजिकल कैश पर निर्भरता कम कर रहा है।"],["विदेशी मुद्रा भंडार","भारत दुनिया के शीर्ष 4-5 विदेशी मुद्रा भंडार वाले देशों में शामिल।"],["रेगुलेटरी सैंडबॉक्स","फिनटेक (FinTech) स्टार्टअप्स के लिए सुरक्षित टेस्टिंग माहौल।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. वाणिज्यिक बैंक (Commercial Banks)"},{"type":"p","text":"भारत में सार्वजनिक (PSBs) और निजी क्षेत्र के बैंकों के बीच स्वस्थ प्रतिस्पर्धा है। बैंकों के विलय (Mergers) के बाद अब भारत में ''ग्लोबल साइज'' के बैंक तैयार हो रहे हैं।"},{"type":"ul","items":["**विलय के बाद स्थिति:** वर्तमान में 12 सार्वजनिक क्षेत्र के बैंक हैं (जैसे- SBI, PNB, BoB)।","**डिजिटल बैंकिंग इकाइयाँ (DBUs):** म.प्र. के इंदौर और ग्वालियर सहित देश के हर जिले में पेपरलेस बैंकिंग सुविधा।","**NPA प्रबंधन:** ''Bad Bank'' (NARCL) के माध्यम से बैंकों की बैलेंस शीट अब काफी स्वच्छ (Healthy) हो गई है।"]},{"type":"h2","text":"3. SEBI (भारतीय प्रतिभूति और विनिमय बोर्ड)"},{"type":"p","text":"SEBI पूंजी बाजार (Stock Market) का नियामक है। 2026 तक भारत का शेयर बाजार दुनिया के शीर्ष 4 बाजारों में शुमार हो चुका है।"},{"type":"table","instruction":"SEBI के आधुनिक सुधार","head":["सुधार (Reform)","प्रभाव (Impact)"],"body":[["T+0 सेटलमेंट","शेयर बेचते ही पैसा तुरंत खाते में (Instant Settlement)।"],["ASBA-like सुविधा","सेकेंडरी मार्केट में भी निवेशकों का पैसा ब्लॉक रहेगा, सुरक्षित ट्रांजैक्शन।"],["फिनफ्लुएंसर रेगुलेशन","सोशल मीडिया पर गलत वित्तीय सलाह देने वालों पर सख्त लगाम।"],["सोशल स्टॉक एक्सचेंज","NGOs और सामाजिक उद्यमों के लिए फंड जुटाने का नया मंच।"]]},{"type":"h2","text":"4. गैर-बैंकिंग वित्तीय कंपनियां (NBFCs)"},{"type":"p","text":"NBFCs को ''शैडो बैंकिंग'' भी कहा जाता है। ये बैंकों की तुलना में अधिक लचीली होती हैं और सूक्ष्म ऋण (Micro-finance) में अग्रणी हैं।"},{"type":"image_tag","content":""},{"type":"fact_card","title":"NBFCs और म.प्र. का संदर्भ","facts":["स्केल-आधारित नियमन: RBI अब NBFCs को उनके आकार के आधार पर (Base, Middle, Upper, Top Layers) रेगुलेट करता है।","म.प्र. में भूमिका: चंबल और बुंदेलखंड जैसे क्षेत्रों में कृषि उपकरणों और छोटे व्यापारों के लिए NBFCs मुख्य वित्त स्रोत हैं।","डिजिटल लेंडिंग: एप-आधारित ऋण देने में NBFCs की भागीदारी 60% से अधिक।"],"icon":"🏢"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भारतीय रिज़र्व बैंक का राष्ट्रीयकरण (Nationalization) किस वर्ष किया गया था?","options":["1935","1947","1949","1951"],"correct":"1949","strategy":"स्थापना 1935 में हुई, लेकिन 1 जनवरी 1949 को यह पूरी तरह सरकारी स्वामित्व में आया।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"SEBI की स्थापना किस वर्ष हुई थी और इसे वैधानिक दर्जा (Statutory Status) कब मिला?","options":["1988 और 1990","1988 और 1992","1990 और 1992","1992 और 1995"],"correct":"1988 और 1992","strategy":"स्थापना 1988 में हुई, लेकिन SEBI एक्ट 1992 के जरिए इसे कानूनी शक्तियाँ मिलीं।"},{"type":"exam_pattern","topic":"Financial Trend","analysis":"Unit 6 Analysis:","stats":["RBI टूल्स (Repo/Reverse Repo): 1-2 प्रश्न","बैंकिंग शब्दावली (NPA/CRAR): 1 प्रश्न","पूंजी बाजार (SEBI/IPO): 1 प्रश्न"],"trend":"आयोग अब ''फिनटेक'' (FinTech) और ''डिजिटल भुगतान'' के आंकड़ों पर गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 6: Financial Institutions of India (2026)"},{"type":"p","text":"The financial architecture of India is the pulse of its economy. In 2026, the focus has shifted from traditional banking to ''Instant Settlement'' and ''Digital-first'' finance. For MPPSC, understanding the evolving roles of RBI, SEBI, and NBFCs is crucial."},{"type":"h2","text":"1. Reserve Bank of India (RBI)"},{"type":"table","instruction":"Key Functions of RBI in 2026","head":["Function","Current Context"],"body":[["Monetary Policy","The MPC regulates liquidity and inflation via Repo rates."],["Digital Rupee (CBDC)","Mass adoption of e-Rupee to reduce physical cash overheads."],["Banker to Banks","Strict oversight via Prompt Corrective Action (PCA) framework."],["FinTech Support","Encouraging innovation through the Regulatory Sandbox."]]},{"type":"h2","text":"2. Commercial Banks & SEBI"},{"type":"ul","items":["**Consolidation:** 12 major PSBs now operate with global scale and efficiency.","**SEBI Reforms:** Introduction of T+0 (Instant) settlement in the stock market to boost liquidity.","**NBFCs:** Crucial for credit penetration in MP’s rural agrarian economy."]},{"type":"exam_pattern","topic":"Financial Trend","analysis":"Unit 6 Analysis:","stats":["RBI Tools: 1-2 questions","Banking Terminology: 1 question","Capital Markets: 1 question"],"trend":"The Commission is increasingly focusing on ''Digital Lending Guidelines'' and ''Central Bank Digital Currency'' (CBDC)."}]}', 'economy', NULL, 35, 1, 1770919888, 1770919888, 'blog', 'unit_6', 'Financial Institutions: Reserve Bank, Commercial Banks, SEBI, Non-Banking Financial Institutions', 1, 0, 0, 1, 0, 'Unit 6: भारत की वित्तीय संस्थाएं (Financial Architecture 2026) भारतीय अर्थव्यवस्था की धड़कन यहाँ की वित्तीय संस्थाएं हैं। 2026 के संदर्भ में, भारत का वित्तीय ढांचा अब पारंपरिक बैंकिंग से ''डिजिटल बैंकि...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('3a2cc351-066b-4961-9192-bdcfa06de8f3', 'india-foreign-trade-g20-saarc-asean-unit-6', 'India''s Foreign Trade & Regional Blocs: G-20, SAARC, ASEAN | भारत की विदेश व्यापार नीति', 'Comprehensive analysis of India''s Foreign Trade Policy (FTP) and its engagement with G-20, SAARC, and ASEAN for MPPSC Unit 6. Covers the 2026 trade landscape and MP''s export potential.', '{"hi":[{"type":"h2","text":"Unit 6: भारत की विदेश व्यापार नीति और अंतर्राष्ट्रीय संगठन"},{"type":"p","text":"भारत की विदेश व्यापार नीति (FTP 2023 और आगामी चरण) का लक्ष्य 2030 तक $2 Trillion का निर्यात हासिल करना है। 2026 में भारत अपनी ''Act East Policy'' के जरिए ASEAN, ''Neighborhood First'' के जरिए SAARC और ''Global South'' के नेतृत्व के जरिए G-20 के साथ व्यापारिक रिश्तों को नई ऊंचाई दे रहा है। MPPSC के लिए इन समूहों के साथ व्यापारिक संतुलन (Trade Balance) और भारत की रणनीतियों को समझना जरूरी है।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. G-20: वैश्विक व्यापार का मंच"},{"type":"p","text":"G-20 दुनिया की 85% जीडीपी और 75% वैश्विक व्यापार का प्रतिनिधित्व करता है। भारत ने अपनी अध्यक्षता (2023) के बाद से ''Global Biofuel Alliance'' और ''IMEC'' (India-Middle East-Europe Corridor) जैसे प्रोजेक्ट्स को 2026 में हकीकत में बदला है।"},{"type":"table","instruction":"G-20 के साथ भारत की व्यापार रणनीति","head":["पहल (Initiative)","विवरण (2026 Context)"],"body":[["IMEC कॉरिडोर","भारत-मध्य पूर्व-यूरोप आर्थिक गलियारा, जो व्यापार लागत को 40% कम करेगा।"],["डिजिटल पब्लिक इंफ्रा","UPI और डिजिटल पेमेंट सिस्टम को G-20 देशों में निर्यात करना।"],["ग्लोबल वैल्यू चेन","बहुराष्ट्रीय कंपनियों के लिए चीन के विकल्प के रूप में भारत को स्थापित करना।"],["ग्रीन ट्रेड","कार्बन सीमा समायोजन तंत्र (CBAM) पर चर्चा और सौर ऊर्जा निर्यात।"]]},{"type":"h2","text":"2. ASEAN (आसियान): ''एक्ट ईस्ट'' की धुरी"},{"type":"p","text":"ASEAN (10 देशों का समूह) भारत का चौथा सबसे बड़ा व्यापारिक भागीदार है। 2026 में भारत **AITIGA** (ASEAN-India Trade in Goods Agreement) की समीक्षा कर रहा है ताकि व्यापार घाटे को कम किया जा सके।"},{"type":"image_tag","content":"[Image map of ASEAN countries and India''s trade connectivity through North-East India and Maritime routes]"},{"type":"ul","items":["**रणनीति:** भारत RCEP (क्षेत्रीय व्यापक आर्थिक भागीदारी) से बाहर है, लेकिन ASEAN देशों के साथ अलग-अलग द्विपक्षीय समझौते (FTAs) कर रहा है।","**कनेक्टिविटी:** भारत-म्यांमार-थाईलैंड त्रिपक्षीय राजमार्ग (Trilateral Highway) 2026 में व्यापारिक आवाजाही का मुख्य केंद्र बन रहा है।","**निर्यात वस्तुएं:** भारत से इंजीनियरिंग सामान, फार्मास्यूटिकल्स और कृषि उत्पादों का भारी निर्यात।"]},{"type":"h2","text":"3. SAARC (सार्क): चुनौतियां और अवसर"},{"type":"p","text":"SAARC में राजनीतिक तनाव के कारण प्रगति धीमी है, लेकिन भारत ''SAFTA'' (South Asian Free Trade Area) के तहत पड़ोसी देशों के साथ व्यापारिक जुड़ाव बनाए हुए है।"},{"type":"table","instruction":"सार्क और क्षेत्रीय व्यापार","head":["फोकस क्षेत्र","प्रमुख पहल/तथ्य"],"body":[["BBIN पहल","भूटान, बांग्लादेश, भारत, नेपाल के बीच सड़क और रेल कनेक्टिविटी।"],["ऊर्जा व्यापार","नेपाल और भूटान से जलविद्युत आयात और बांग्लादेश को बिजली निर्यात।"],["SAFTA","सदस्य देशों के बीच सीमा शुल्क (Tariffs) को शून्य करने का लक्ष्य।"],["BIMSTEC","SAARC के विकल्प के रूप में भारत अब BIMSTEC पर अधिक जोर दे रहा है।"]]},{"type":"highlight","level":"important","text":"मध्य प्रदेश का संदर्भ: MP के ''एक जिला एक उत्पाद'' (ODOP) जैसे रतलामी सेव, चिन्नौर चावल और बाग प्रिंट को ASEAN और G-20 बाजारों में निर्यात करने हेतु विशेष ''निर्यात हब'' बनाए गए हैं।","icon":"🚢"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भारत की विदेश व्यापार नीति (2021-26) का मुख्य लक्ष्य क्या है?","options":["निर्यात में 10% कमी","निर्यात को $2 ट्रिलियन तक ले जाना","आयात पर पूर्ण रोक","केवल कृषि निर्यात"],"correct":"निर्यात को $2 ट्रिलियन तक ले जाना (2030 तक का लक्ष्य)","strategy":"FTP 2023 ने समय सीमा हटा दी है लेकिन $2 ट्रिलियन का विजन बरकरार रखा है।"},{"type":"pyq","exam":"MPPSC Prelims 2019","year":2019,"question":"आसियान (ASEAN) का मुख्यालय कहाँ स्थित है?","options":["बैंकॉक","जकार्ता","मनीला","सिंगापुर"],"correct":"जकार्ता (इंडोनेशिया)","strategy":"ASEAN की स्थापना 1967 में बैंकॉक घोषणा से हुई, पर मुख्यालय जकार्ता में है।"},{"type":"exam_pattern","topic":"Foreign Trade Trend","analysis":"Unit 6 Trade Analysis:","stats":["मुख्यालय और स्थापना वर्ष: 1 प्रश्न","प्रमुख व्यापारिक गलियारे (IMEC/INSTC): 1 प्रश्न","व्यापार घाटा और साझेदार देश: 1 प्रश्न"],"trend":"आयोग अब ''FTA'' (Free Trade Agreements) और भारत की ''PLI स्कीम'' का वैश्विक व्यापार पर असर जैसे करंट टॉपिक्स पर अधिक फोकस कर रहा है।"}],"en":[{"type":"h2","text":"Unit 6: India''s Foreign Trade Policy and International Organizations"},{"type":"p","text":"India''s Foreign Trade Policy (FTP) aims to reach $2 trillion in exports by 2030. In 2026, through its ''Act East Policy'', India is revitalizing trade with ASEAN, SAARC, and leading the ''Global South'' via G-20."},{"type":"h2","text":"1. G-20 and Global Integration"},{"type":"table","instruction":"India''s Strategy with G-20","head":["Initiative","Impact in 2026"],"body":[["IMEC","Connectivity corridor expected to reduce trade time to Europe by 40%."],["Digital Public Infra","Exporting UPI and digital payment stacks to G-20 nations."],["Supply Chains","Positioning India as the ''Plus One'' in the China+1 strategy."]]},{"type":"h2","text":"2. ASEAN & SAARC"},{"type":"ul","items":["**ASEAN:** Review of AITIGA to address the trade deficit and boost manufacturing exports.","**SAARC:** Focus on sub-regional groups like BBIN (Bangladesh-Bhutan-India-Nepal) due to broader SAARC stagnation.","**MP Link:** Leveraging MP''s ODOP products for international expos in G-20 and ASEAN summits."]},{"type":"exam_pattern","topic":"Foreign Trade Trend","analysis":"Unit 6 Analysis:","stats":["HQs & Formation Years: 1 question","Major Corridors (IMEC): 1 question","Trade Partners & Deficits: 1 question"],"trend":"The Commission is shifting towards ''FTAs'' and the global impact of the ''PLI Scheme''."}]}', 'economy', NULL, 35, 1, 1770919952, 1770919952, 'blog', 'unit_6', 'India''s foreign Trade Policies: G-20, SAARC and ASEAN', 1, 0, 0, 1, 0, 'Unit 6: भारत की विदेश व्यापार नीति और अंतर्राष्ट्रीय संगठन भारत की विदेश व्यापार नीति (FTP 2023 और आगामी चरण) का लक्ष्य 2030 तक $2 Trillion का निर्यात हासिल करना है। 2026 में भारत अपनी ''Act East Polic...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('207446d0-660f-4432-847b-dedc071ccb03', 'main-branches-of-science-unit-7-mppsc', 'Main Branches of Science: Basic Knowledge | विज्ञान की प्रमुख शाखाएं', 'An exhaustive guide to the fundamental and specialized branches of Physics, Chemistry, and Biology. Curated for MPPSC 2026, including PYQs from various State PSCs and UPSC.', '{"hi":[{"type":"h2","text":"Unit 7: विज्ञान की प्रमुख शाखाओं का प्रारंभिक ज्ञान"},{"type":"p","text":"विज्ञान की शाखाओं को मुख्य रूप से तीन श्रेणियों में विभाजित किया गया है: भौतिक विज्ञान (Physics), रसायन विज्ञान (Chemistry) और जीव विज्ञान (Biology)। इसके अलावा, आधुनिक युग में कई ''अंतःविषय'' (Interdisciplinary) शाखाएं जैसे जैव-प्रौद्योगिकी और नैनो-प्रौद्योगिकी उभरी हैं। MPPSC और अन्य राज्य आयोग अक्सर ''अध्ययन के क्षेत्रों'' (Fields of Study) के नामों पर प्रश्न पूछते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. जीव विज्ञान की प्रमुख शाखाएं (Branches of Biology)"},{"type":"p","text":"जीव विज्ञान से सबसे अधिक प्रश्न पूछे जाते हैं, विशेषकर जूलॉजी और बॉटनी की उप-शाखाओं से।"},{"type":"table","instruction":"महत्वपूर्ण जैविक शाखाएं","head":["शाखा (Branch)","अध्ययन का विषय (Field of Study)"],"body":[["साइटोलॉजी (Cytology)","कोशिकाओं (Cells) का अध्ययन।"],["हिस्टोलॉजी (Histology)","ऊतकों (Tissues) का अध्ययन।"],["माइकोलॉजी (Mycology)","कवक (Fungi) का अध्ययन।"],["फाइकोलॉजी (Phycology)","शैवाल (Algae) का अध्ययन।"],["एंटोमोलॉजी (Entomology)","कीटों (Insects) का अध्ययन।"],["ऑर्निथोलॉजी (Ornithology)","पक्षियों (Birds) का अध्ययन।"],["इचिथियोलॉजी (Ichthyology)","मछलियों (Fishes) का अध्ययन।"],["पेलियोन्टोलॉजी (Paleontology)","जीवाश्मों (Fossils) का अध्ययन।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. भौतिक और रसायन विज्ञान (Physics & Chemistry)"},{"type":"table","instruction":"भौतिक एवं रासायनिक शाखाएं","head":["शाखा","विवरण"],"body":[["एरोनॉटिक्स (Aeronautics)","वायुयान और उड़ान के सिद्धांतों का अध्ययन।"],["क्रायोजेनिक्स (Cryogenics)","अति निम्न ताप (Low Temperature) का उत्पादन और नियंत्रण।"],["ऑप्टिक्स (Optics)","प्रकाश के गुणों और व्यवहार का अध्ययन।"],["एस्ट्रोफिजिक्स (Astrophysics)","खगोलीय पिंडों के भौतिक गुणों का अध्ययन।"],["एनालिटिकल केमिस्ट्री","पदार्थों के नमूनों का पृथक्करण और पहचान।"],["बायोकेमिस्ट्री","जीवित जीवों के भीतर होने वाली रासायनिक प्रक्रियाएं।"]]},{"type":"h2","text":"3. कृषि और आधुनिक शाखाएं (Applied Sciences)"},{"type":"fact_card","title":"एप्लाइड साइंस: एग्जाम फेवरिट्स","facts":["सेरीकल्चर (Sericulture): रेशम के कीड़ों का पालन।","विटीकल्चर (Viticulture): अंगूर की खेती।","पिसीकल्चर (Pisciculture): मत्स्य पालन।","एग्रोस्टोलॉजी (Agrostology): घासों (Grasses) का अध्ययन।","नैनो-टेक्नोलॉजी: 10^-9 मीटर स्तर पर पदार्थों का हेरफेर।"],"icon":"🔬"},{"type":"mnemonic","topic":"Algae और Fungi में कंफ्यूजन दूर करने की ट्रिक","trick":"Phy-Al (फाइ-अल) और My-Fun (माई-फन)","visual":"💡","explanation":"**Phy**cology = **Al**gae | **My**cology = **Fun**gi"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"फाइकोलॉजी (Phycology) के अंतर्गत किसका अध्ययन किया जाता है?","options":["कवक","शैवाल","पारिस्थितिकी","विषाणु"],"correct":"शैवाल (Algae)","strategy":"कवक के लिए माइकोलॉजी होता है, कंफ्यूज न हों।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"कीटों के वैज्ञानिक अध्ययन को क्या कहते हैं?","options":["इचिथियोलॉजी","एंटोमोलॉजी","पैरासिटोलॉजी","मैलाकोलॉजी"],"correct":"एंटोमोलॉजी (Entomology)","strategy":"Entomon का अर्थ ग्रीक में ''insect'' होता है।"},{"type":"pyq","exam":"UPSC Prelims 2018","year":2018,"question":"''क्रायोजेनिक्स'' इंजन का प्रयोग कहाँ किया जाता है?","options":["परमाणु भट्टी","रेल इंजन","रॉकेट तकनीक","समुद्र के भीतर"],"correct":"रॉकेट तकनीक (Space Technology)","strategy":"अति निम्न ताप पर ईंधन (Liquid O2/H2) को स्टोर करने हेतु इसका उपयोग होता है।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"वृद्धावस्था के अध्ययन को क्या कहा जाता है?","options":["ऑन्कोलॉजी","जेरोन्टोलॉजी","टेराटोलॉजी","ऑर्निथोलॉजी"],"correct":"जेरोन्टोलॉजी (Gerontology)","strategy":"ऑन्कोलॉजी कैंसर के लिए और ऑर्निथोलॉजी पक्षियों के लिए है।"},{"type":"exam_pattern","topic":"Science Branch Trend","analysis":"PSC Trend Analysis:","stats":["Study Fields (Naming): 2 प्रश्न","Scientific Units/Instruments: 1 प्रश्न","Modern Tech (Space/Nano): 1 प्रश्न"],"trend":"आयोग अब केवल पारंपरिक शाखाएं नहीं, बल्कि ''जेनेटिक्स'' और ''बायो-इंफॉर्मेटिक्स'' जैसी आधुनिक शाखाओं पर अधिक ध्यान दे रहे हैं।"}],"en":[{"type":"h2","text":"Unit 7: Preliminary Knowledge of Main Branches of Science"},{"type":"p","text":"Science is broadly divided into three main branches: Physics, Chemistry, and Biology. In the modern era, several interdisciplinary branches like Biotechnology and Nanotechnology have emerged. State PSCs frequently ask questions on the terminology used for different fields of study."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Major Branches of Biology"},{"type":"table","instruction":"Important Biological Branches","head":["Branch","Field of Study"],"body":[["Cytology","Study of Cells."],["Histology","Study of Tissues."],["Mycology","Study of Fungi."],["Phycology","Study of Algae."],["Entomology","Study of Insects."],["Ornithology","Study of Birds."],["Ichthyology","Study of Fishes."],["Paleontology","Study of Fossils."]]},{"type":"h2","text":"2. Physics and Chemistry"},{"type":"table","instruction":"Physical & Chemical Branches","head":["Branch","Description"],"body":[["Aeronautics","Study of flight and aircraft design."],["Cryogenics","Production and effects of very low temperatures."],["Optics","Study of properties and behavior of light."],["Astrophysics","Physical properties of celestial bodies."],["Biochemistry","Chemical processes within and relating to living organisms."]]},{"type":"fact_card","title":"Applied Science: Exam Favorites","facts":[["Sericulture","Rearing of silkworms for silk production."],["Viticulture","Cultivation of grapes."],["Agrostology","Study of grasses."],["Nanotechnology","Manipulation of matter on an atomic/molecular scale (10^-9 m)."]],"icon":"🔬"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"What is studied under Phycology?","options":["Fungi","Algae","Ecology","Virus"],"correct":"Algae","strategy":"Remember Phycology is for Algae; Mycology is for Fungi."},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"The scientific study of insects is known as?","options":["Ichthyology","Entomology","Parasitology","Malacology"],"correct":"Entomology","strategy":"Entomon means ''insect'' in Greek."}]}', 'science', NULL, 35, 1, 1770920110, 1771008903, 'blog', 'unit_7', 'Preliminary Knowledge of Main Branches of Science', 1, 0, 1, 1, 0, 'Unit 7: विज्ञान की प्रमुख शाखाओं का प्रारंभिक ज्ञान विज्ञान की शाखाओं को मुख्य रूप से तीन श्रेणियों में विभाजित किया गया है: भौतिक विज्ञान (Physics), रसायन विज्ञान (Chemistry) और जीव विज्ञान (Biology)...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('b24586db-ec7d-4887-acc3-692e4126836d', 'important-indian-achievements-science-unit-7-mppsc', 'Important Indian Achievements in Science & Tech | विज्ञान और तकनीक में भारत की महत्वपूर्ण उपलब्धियां', 'A comprehensive guide to India''s milestones in Space, Nuclear, Defense, and Agriculture sectors. Features Gaganyaan, Chandrayaan, Missile programs, and high-yield PYQs for MPPSC Unit 7.', '{"hi":[{"type":"h2","text":"Unit 7: विज्ञान एवं प्रौद्योगिकी में भारत की महत्वपूर्ण उपलब्धियां"},{"type":"p","text":"आजादी के बाद से भारत ने विज्ञान के क्षेत्र में ''आत्मनिर्भरता'' की एक लंबी यात्रा तय की है। आज भारत अंतरिक्ष (Space), परमाणु ऊर्जा (Nuclear Energy), रक्षा (Defense) और जैव-प्रौद्योगिकी में दुनिया के शीर्ष देशों में शामिल है। MPPSC में अक्सर इन मिशनों की लॉन्च तिथि, उद्देश्यों और प्रमुख वैज्ञानिकों (जैसे- ''मिसाइल मैन'') पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. अंतरिक्ष क्षेत्र (Space Sector): ISRO की उड़ान"},{"type":"p","text":"भारतीय अंतरिक्ष अनुसंधान संगठन (ISRO) ने कम लागत में सटीक मिशनों के माध्यम से दुनिया को चौंकाया है।"},{"type":"table","instruction":"प्रमुख अंतरिक्ष मिशन (Major Space Missions)","head":["मिशन (Mission)","वर्ष","विशेषता/उपलब्धि"],"body":[["आर्यभट्ट (Aryabhata)","1975","भारत का पहला कृत्रिम उपग्रह (सोवियत संघ की मदद से)।"],["मंगलयान (MOM)","2013","पहले ही प्रयास में मंगल की कक्षा में पहुँचने वाला पहला देश।"],["चंद्रयान-3","2023","चंद्रमा के दक्षिणी ध्रुव (South Pole) पर उतरने वाला दुनिया का पहला देश।"],["आदित्य L1","2023","सूर्य का अध्ययन करने वाला भारत का पहला मिशन (L1 पॉइंट)।"],["गगनयान (Gaganyaan)","2025-26","भारत का पहला मानवयुक्त अंतरिक्ष मिशन (Human Spaceflight)।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. रक्षा एवं मिसाइल प्रौद्योगिकी (Defense & Missile Tech)"},{"type":"p","text":"डॉ. ए.पी.जे. अब्दुल कलाम के नेतृत्व में ''IGMDP'' कार्यक्रम ने भारत को मिसाइल शक्ति बनाया।"},{"type":"ul","items":["**पटना (PATNA):** पृथ्वी, अग्नि, त्रिशूल, नाग, और आकाश - ये पांच मिसाइलें इस कार्यक्रम की रीढ़ हैं।","**ब्रह्मोस (BrahMos):** भारत और रूस द्वारा विकसित दुनिया की सबसे तेज सुपरसोनिक क्रूज मिसाइल।","**अग्नि-V:** इंटरकांटिनेंटल बैलिस्टिक मिसाइल (ICBM) जिसकी रेंज 5000+ किमी है।","**INS अरिहंत:** भारत की पहली स्वदेशी परमाणु-संचालित पनडुब्बी।"]},{"type":"h2","text":"3. परमाणु ऊर्जा और कृषि (Nuclear & Agriculture)"},{"type":"table","instruction":"अन्य महत्वपूर्ण उपलब्धियां","head":["क्षेत्र","उपलब्धि","मुख्य व्यक्तित्व"],"body":[["परमाणु परीक्षण","पोखरण-I (1974 - स्माइलिंग बुद्धा) और पोखरण-II (1998 - ऑपरेशन शक्ति)।","होमी जे. भाभा, ए.पी.जे. अब्दुल कलाम।"],["हरित क्रांति","खाद्यान्न उत्पादन में आत्मनिर्भरता (गेहूं और चावल)।","एम.एस. स्वामीनाथन।"],["श्वेत क्रांति","दूध उत्पादन में भारत प्रथम स्थान पर (Operation Flood)।","वर्गीज कुरियन।"],["सुपरकंप्यूटर","परम (PARAM 8000) - भारत का पहला सुपरकंप्यूटर (1991)।","विजय पी. भटकर।"]]},{"type":"fact_card","title":"भारत @ 2026: क्विक बाइट्स","facts":["नमो भारत (RRTS): भारत की पहली सेमी-हाई स्पीड क्षेत्रीय रेल सेवा।","वैक्सीन मैत्री: कोविड-19 के दौरान दुनिया को 100+ देशों में वैक्सीन की आपूर्ति।","स्वदेशी 5G: भारत ने अपना 5G स्टैक विकसित किया और अब 6G की ओर बढ़ रहा है।","सकल ऊर्जा: सौर ऊर्जा उत्पादन में भारत दुनिया के शीर्ष 4 देशों में शामिल।"],"icon":"🇮🇳"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भारत के ''मिसाइल मैन'' के रूप में किसे जाना जाता है?","options":["डॉ. सी.वी. रमन","डॉ. ए.पी.जे. अब्दुल कलाम","डॉ. होमी भाभा","डॉ. विक्रम साराभाई"],"correct":"डॉ. ए.पी.जे. अब्दुल कलाम","strategy":"IGMDP कार्यक्रम के नेतृत्व के कारण उन्हें यह उपाधि मिली।"},{"type":"pyq","exam":"UPSC Prelims 2023","year":2023,"question":"चंद्रयान-3 मिशन के लैंडर का नाम क्या था?","options":["प्रज्ञान","विक्रम","ध्रुव","आकाश"],"correct":"विक्रम","strategy":"विक्रम ''लैंडर'' है और प्रज्ञान ''रोवर'' है, इसे हमेशा याद रखें।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"भारत का पहला सुपरकंप्यूटर कौन सा था?","options":["आदित्य","परम 8000","तिआनहे-2","सागा-220"],"correct":"परम 8000","strategy":"CDAC पुणे द्वारा 1991 में विकसित किया गया था।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"डॉ. एम.एस. स्वामीनाथन का संबंध किस क्षेत्र से है?","options":["अंतरिक्ष","परमाणु ऊर्जा","कृषि (हरित क्रांति)","श्वेत क्रांति"],"correct":"कृषि (हरित क्रांति)","strategy":"हाल ही में उन्हें मरणोपरांत भारत रत्न (2024) देने की घोषणा हुई है, जो एग्जाम के लिए महत्वपूर्ण है।"},{"type":"exam_pattern","topic":"Indian Achievements Trend","analysis":"Competitive Exams Trend:","stats":["ISRO मिशन और तिथि: 2 प्रश्न","वैज्ञानिक और उनके उपनाम: 1 प्रश्न","रक्षा प्रौद्योगिकी (Missiles): 1 प्रश्न"],"trend":"आयोग अब पुराने उपलब्धियों के साथ-साथ ''करंट मिशन'' (जैसे- आदित्य L1 के पेलोड्स) पर अधिक गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 7: Important Indian Achievements in Science and Technology"},{"type":"p","text":"Since independence, India has undertaken a remarkable journey towards scientific self-reliance. Today, India stands among the global leaders in Space, Nuclear Energy, Defense, and Biotechnology. In MPPSC, questions often target mission dates, objectives, and the ''fathers'' of various scientific fields."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Space Sector: The Rise of ISRO"},{"type":"table","instruction":"Major Space Milestones","head":["Mission","Year","Achievement"],"body":[["Aryabhata","1975","First Indian Satellite (launched by USSR)."],["Mangalyaan (MOM)","2013","First country to reach Mars orbit in the maiden attempt."],["Chandrayaan-3","2023","First country to land on the Lunar South Pole."],["Aditya L1","2023","India''s first solar observatory mission."],["Gaganyaan","2025-26","India''s first manned spaceflight mission."]]},{"type":"h2","text":"2. Defense and Missile Technology"},{"type":"ul","items":["**PATNA:** Prithvi, Agni, Trishul, Nag, and Akash missiles formed under the IGMDP.","**BrahMos:** World''s fastest supersonic cruise missile developed by India and Russia.","**INS Arihant:** India''s first indigenously developed nuclear-powered submarine.","**Agni-V:** ICBM with a range of over 5000 km, placing India in an elite group."]},{"type":"h2","text":"3. Nuclear, Agriculture, and IT"},{"type":"fact_card","title":"Historical Milestones","facts":["Nuclear: Pokhran-I (Smiling Budhha, 1974) and Pokhran-II (Operation Shakti, 1998).","Green Revolution: Achieving food security under Dr. M.S. Swaminathan.","White Revolution: Becoming the world''s largest milk producer (Dr. Verghese Kurien).","Supercomputers: PARAM 8000 (1991) developed by CDAC Pune."],"icon":"🇮🇳"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Who is known as the ''Missile Man'' of India?","options":["C.V. Raman","A.P.J. Abdul Kalam","Homi Bhabha","Vikram Sarabhai"],"correct":"A.P.J. Abdul Kalam","strategy":"Recognized for his leadership in the Integrated Guided Missile Development Programme."},{"type":"exam_pattern","topic":"Indian Achievements Trend","analysis":"Competitive Exams Trend:","stats":["ISRO Missions & Dates: 2 questions","Scientists & Nicknames: 1 question","Defense Technology (Missiles): 1 question"],"trend":"Commissions are now focusing more on technical payloads of recent missions (e.g., payloads of Aditya L1) along with historical facts."}]}', 'science_technology', NULL, 35, 1, 1770920514, 1771008904, 'blog', 'unit_7', 'Important Indian Achievements', 1, 0, 1, 1, 0, 'Unit 7: विज्ञान एवं प्रौद्योगिकी में भारत की महत्वपूर्ण उपलब्धियां आजादी के बाद से भारत ने विज्ञान के क्षेत्र में ''आत्मनिर्भरता'' की एक लंबी यात्रा तय की है। आज भारत अंतरिक्ष (Space), परमाणु ऊर्जा (Nuc...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('25c9b850-5066-4bc4-a1eb-8331e1d9fa51', 'space-institutions-achievements-unit-7-mppsc', 'Scientific Institutions & Space Achievements | वैज्ञानिक संस्थान एवं अंतरिक्ष उपलब्धियां', 'Comprehensive study of India''s premier scientific institutions and their milestones in space science. Detailed analysis of ISRO, DRDO, TIFR, and major satellite programs for MPPSC Unit 7.', '{"hi":[{"type":"h2","text":"Unit 7: भारत के वैज्ञानिक अनुसंधान संस्थान एवं अंतरिक्ष विज्ञान में उपलब्धियां"},{"type":"p","text":"भारत का अंतरिक्ष कार्यक्रम न केवल वैज्ञानिक खोजों के लिए है, बल्कि यह राष्ट्रीय सुरक्षा और सामाजिक-आर्थिक विकास का आधार भी है। ISRO के नेतृत्व में भारत ने ''लॉन्च व्हीकल'' (SLV से LVM3) और ''सैटेलाइट'' तकनीक में आत्मनिर्भरता हासिल की है। MPPSC में अक्सर इन संस्थानों के मुख्यालय, स्थापना वर्ष और उपग्रहों के प्रकार पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. प्रमुख वैज्ञानिक अनुसंधान संस्थान (Major Research Institutions)"},{"type":"p","text":"भारत के अंतरिक्ष और रक्षा अनुसंधान का ढांचा विभिन्न विशिष्ट संस्थानों पर टिका है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"संस्थान: मुख्यालय एवं कार्य","head":["संस्थान (Institution)","मुख्यालय (HQ)","प्रमुख कार्य (Key Function)"],"body":[["ISRO (भारतीय अंतरिक्ष अनुसंधान संगठन)","बेंगलुरु","अंतरिक्ष मिशनों का नियोजन और कार्यान्वयन।"],["VSSC (विक्रम साराभाई अंतरिक्ष केंद्र)","तिरुवनंतपुरम","रॉकेट और लॉन्च व्हीकल का विकास।"],["URSC (यू.आर. राव उपग्रह केंद्र)","बेंगलुरु","उपग्रहों (Satellites) का डिजाइन और निर्माण।"],["SDSC (सतीश धवन अंतरिक्ष केंद्र)","श्रीहरिकोटा","भारत का मुख्य प्रक्षेपण स्थल (Launch Site)।"],["NRSC (राष्ट्रीय सुदूर संवेदन केंद्र)","हैदराबाद","उपग्रह डेटा और रिमोट सेंसिंग का प्रबंधन।"],["PRL (भौतिक अनुसंधान प्रयोगशाला)","अहमदाबाद","अंतरिक्ष और खगोल विज्ञान में बुनियादी अनुसंधान।"]]},{"type":"h2","text":"2. उपग्रह एवं अंतरिक्ष तकनीक (Satellite & Space Tech)"},{"type":"p","text":"भारत ने उपग्रहों की विभिन्न श्रेणियों (INSAT, IRS, NavIC) में महारत हासिल की है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"भारतीय उपग्रह प्रणालियाँ","head":["प्रणाली (System)","उपयोग (Utility)","उदाहरण (Examples)"],"body":[["INSAT / GSAT","दूरसंचार और मौसम विज्ञान।","GSAT-24, INSAT-3DR"],["IRS / EOS","रिमोट सेंसिंग और पृथ्वी अवलोकन।","Cartosat, Risat, EOS-04"],["NavIC (IRNSS)","स्वदेशी नेविगेशन प्रणाली (GPS की तरह)।","IRNSS-1A से 1L तक"],["SAMPAT","रक्षा एवं सामरिक संचार।","GSAT-7 (एंग्री बर्ड)"]]},{"type":"highlight","level":"important","text":"LVM3 (GSLV Mk-III): इसे ''बाहुबली'' रॉकेट कहा जाता है। यह भारत का सबसे भारी लॉन्च व्हीकल है, जिसका उपयोग चंद्रयान-3 और गगनयान में किया गया है।","icon":"🚀"},{"type":"h2","text":"3. अंतरिक्ष विज्ञान में हालिया उपलब्धियां (2025-26)"},{"type":"fact_card","title":"भारत @ स्पेस 2026","facts":["गगनयान (Gaganyaan): भारत का पहला मानव मिशन, जिसमें ''व्योममित्र'' (Humanoid Robot) का परीक्षण सफल रहा।","Nisar Mission: ISRO और NASA का संयुक्त रडार मिशन जो पृथ्वी के परिवर्तनों को मापेगा।","BAS (भारतीय अंतरिक्ष स्टेशन): 2035 तक अपना अंतरिक्ष स्टेशन स्थापित करने का रोडमैप तैयार।","LUPEX मिशन: चंद्रमा के अंधेरे हिस्से (Dark Side) की खोज हेतु जापान (JAXA) के साथ सहयोग।"],"icon":"🌌"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भारतीय अंतरिक्ष अनुसंधान संगठन (ISRO) का मुख्यालय कहाँ स्थित है?","options":["नई दिल्ली","बेंगलुरु","हैदराबाद","अहमदाबाद"],"correct":"बेंगलुरु","strategy":"ISRO की स्थापना 15 अगस्त 1969 को हुई थी और इसका मुख्यालय बेंगलुरु में है।"},{"type":"pyq","exam":"UPSC Prelims 2018","year":2018,"question":"भारत के स्वदेशी नेविगेशन प्रणाली का नाम क्या है?","options":["GLONASS","Galileo","NavIC (IRNSS)","BeiDou"],"correct":"NavIC (IRNSS)","strategy":"NavIC (Navigation with Indian Constellation) में 7 उपग्रहों का समूह है।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"विक्रम साराभाई अंतरिक्ष केंद्र (VSSC) कहाँ स्थित है?","options":["श्रीहरिकोटा","तिरुवनंतपुरम","बेंगलुरु","चांदीपुर"],"correct":"तिरुवनंतपुरम (Thiruvananthapuram)","strategy":"VSSC केरल में स्थित है और यहाँ रॉकेट का निर्माण होता है।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"''रिमोट सेंसिंग'' डेटा प्रबंधन के लिए उत्तरदायी संस्थान कौन सा है?","options":["ISRO","NRSC","VSSC","SAC"],"correct":"NRSC (हैदराबाद)","strategy":"National Remote Sensing Centre उपग्रह इमेजरी के लिए जिम्मेदार है।"},{"type":"exam_pattern","topic":"Space Institutions Trend","analysis":"Competitive Exams Trend:","stats":["संस्थानों के मुख्यालय: 2 प्रश्न","लॉन्च व्हीकल (PSLV/GSLV): 1 प्रश्न","उपग्रहों के उपयोग (Communication/RS): 1 प्रश्न"],"trend":"आयोग अब ''प्राइवेट स्पेस'' (जैसे- Skyroot, Agnikul) और ''स्पेस इकोनॉमी'' पर अधिक गहराई से प्रश्न पूछ रहे हैं।"}],"en":[{"type":"h2","text":"Unit 7: Scientific Research Institutions and Space Achievements"},{"type":"p","text":"India''s space program is not just for scientific exploration but also for national security and socio-economic development. Led by ISRO, India has achieved self-reliance in launch vehicle technology (SLV to LVM3) and satellite communication. In MPPSC, questions frequently target HQs, foundation years, and types of satellites."},{"type":"h2","text":"1. Major Research Institutions"},{"type":"table","instruction":"Institutions: HQ and Role","head":["Institution","Headquarters (HQ)","Core Function"],"body":[["ISRO","Bengaluru","Planning and execution of space missions."],["VSSC","Thiruvananthapuram","Development of Rockets and Launch Vehicles."],["URSC","Bengaluru","Design and fabrication of Satellites."],["SDSC","Sriharikota","Primary launch site (Spaceport) of India."],["NRSC","Hyderabad","Management of satellite data and remote sensing."],["PRL","Ahmedabad","Fundamental research in space and cosmic sciences."]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. Satellite and Space Technology"},{"type":"table","instruction":"Indian Satellite Systems","head":["System","Application","Examples"],"body":[["INSAT / GSAT","Telecommunication and Meteorology.","GSAT-24, INSAT-3DR"],["IRS / EOS","Remote Sensing and Earth Observation.","Cartosat, Resourcesat"],["NavIC (IRNSS)","Indigenous Navigation (like GPS).","IRNSS Constellation"],["GSAT-7 Series","Military and Strategic Communication.","Rukmini, Angry Bird"]]},{"type":"highlight","level":"important","text":"LVM3: Known as the ''Bahubali'' of Indian rockets, it is the heaviest launcher used for Chandrayaan-3 and Gaganyaan missions.","icon":"🚀"},{"type":"h2","text":"3. Recent Space Achievements (2025-26)"},{"type":"fact_card","title":"India @ Space 2026","facts":["Gaganyaan: India''s manned mission; testing of ''Vyommitra'' (humanoid) successful.","Nisar: Joint ISRO-NASA radar mission for Earth monitoring.","BAS: Roadmap for India''s own Space Station by 2035.","LUPEX: Collaboration with Japan (JAXA) for exploring the Lunar South Pole."],"icon":"🌌"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Where is the headquarters of ISRO located?","options":["New Delhi","Bengaluru","Hyderabad","Ahmedabad"],"correct":"Bengaluru","strategy":"Established on 15 Aug 1969, ISRO is based in Bengaluru."},{"type":"pyq","exam":"UPSC Prelims 2018","year":2018,"question":"What is the name of India''s indigenous navigation system?","options":["GLONASS","Galileo","NavIC","BeiDou"],"correct":"NavIC","strategy":"NavIC (IRNSS) consists of a constellation of 7 satellites."},{"type":"exam_pattern","topic":"Space Institutions Trend","analysis":"Competitive Exams Trend:","stats":["Institutional HQs: 2 questions","Launch Vehicles: 1 question","Satellite Utility: 1 question"],"trend":"Commissions are now moving towards ''Private Space Players'' and ''Space Economy'' metrics over traditional facts."}]}', 'science_technology', NULL, 40, 1, 1770920992, 1771008905, 'blog', 'unit_7', 'Scientific Research Institutions and their Satellite and Space Technology Achievement of India in the Field of Space Science', 1, 0, 1, 1, 0, 'Unit 7: भारत के वैज्ञानिक अनुसंधान संस्थान एवं अंतरिक्ष विज्ञान में उपलब्धियां भारत का अंतरिक्ष कार्यक्रम न केवल वैज्ञानिक खोजों के लिए है, बल्कि यह राष्ट्रीय सुरक्षा और सामाजिक-आर्थिक विकास का आधार भ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('3b995017-a59d-4ec4-8865-d146670b18fe', 'structure-of-human-body-unit-7-mppsc', 'Structure of the Human Body | मानव शरीर की संरचना', 'An in-depth analysis of human organ systems, including skeletal, digestive, circulatory, and nervous systems. Tailored for MPPSC Unit 7 with multi-state PSC PYQs.', '{"hi":[{"type":"h2","text":"Unit 7: मानव शरीर की संरचना (Anatomy & Physiology)"},{"type":"p","text":"मानव शरीर एक जटिल मशीन की तरह है जो विभिन्न अंगों और तंत्रों (Systems) के समन्वय से चलता है। इसकी शुरुआत ''कोशिका'' (Cell) से होती है, जो मिलकर ऊतक (Tissue) बनाती हैं, और फिर अंग (Organ) और अंत में एक ''तंत्र'' (System) बनता है। MPPSC में अक्सर अस्थियों, एंजाइमों और अंतःस्रावी ग्रंथियों (Endocrine Glands) पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. कंकाल एवं पेशी तंत्र (Skeletal & Muscular System)"},{"type":"p","text":"कंकाल तंत्र शरीर को ढांचा प्रदान करता है और महत्वपूर्ण अंगों की रक्षा करता है।"},{"type":"table","instruction":"कंकाल तंत्र के महत्वपूर्ण तथ्य","head":["विषय","तथ्य (Fact)"],"body":[["कुल हड्डियाँ","वयस्क में 206 (शिशु में ~300)"],["सबसे बड़ी हड्डी","फीमर (जांघ की हड्डी)"],["सबसे छोटी हड्डी","स्टेप्स (कान के मध्य में)"],["कुल मांसपेशियाँ","लगभग 639"],["अस्थि से अस्थि का जोड़","लिगामेंट (Ligament)"],["मांसपेशी से अस्थि का जोड़","टेंडन (Tendon)"]]},{"type":"h2","text":"2. पाचन एवं श्वसन तंत्र (Digestive & Respiratory System)"},{"type":"p","text":"पाचन तंत्र भोजन को ऊर्जा में बदलता है, जबकि श्वसन तंत्र ऑक्सीजन की आपूर्ति करता है।"},{"type":"image_tag","content":""},{"type":"ul","items":["**पाचन की शुरुआत:** मुख गुहा (Mouth) से होती है, जहाँ ''टायलिन'' एंजाइम स्टार्च का पाचन करता है।","**पित्त रस (Bile Juice):** यकृत (Liver) द्वारा बनाया जाता है और पित्ताशय (Gall bladder) में जमा होता है।","**इंसुलिन:** अग्न्याशय (Pancreas) की ''लैंगरहैंस की द्वीपिकाओं'' से स्रावित होता है जो रक्त शर्करा को नियंत्रित करता है।"]},{"type":"h2","text":"3. परिसंचरण एवं तंत्रिका तंत्र (Circulatory & Nervous System)"},{"type":"table","instruction":"परिसंचरण तंत्र के घटक","head":["घटक (Component)","कार्य / गुण"],"body":[["रक्त (Blood)","एक तरल संयोजी ऊतक (pH 7.4)"],["हृदय (Heart)","4 कक्षीय पंपिंग अंग (Pumping Organ)"],["RBC","ऑक्सीजन का परिवहन (जीवनकाल 120 दिन)"],["WBC","रोग प्रतिरोधक क्षमता (Body''s Soldiers)"],["मस्तिष्क","सेरेब्रम (सोचना), सेरेबैलम (संतुलन), मेडुला (अनैच्छिक क्रियाएँ)"]]},{"type":"highlight","level":"important","text":"याद रखें: रक्त समूह O ''सर्वदाता'' (Universal Donor) है और AB ''सर्वग्राही'' (Universal Acceptor) है।","icon":"🩸"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मानव शरीर में प्रचुर मात्रा में पाया जाने वाला तत्व कौन सा है?","options":["लोहा","सोडियम","ऑक्सीजन","आयोडीन"],"correct":"ऑक्सीजन (~65%)","strategy":"शरीर के भार का अधिकांश भाग जल और कार्बनिक यौगिकों से बना है जिनमें ऑक्सीजन मुख्य है।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"एंजाइम ''टायलिन'' (Ptyalin) का स्रोत क्या है?","options":["अग्न्याशय","यकृत","लार ग्रंथियां","आमाशय"],"correct":"लार ग्रंथियां (Salivary Glands)","strategy":"लार में टायलिन होता है जो कार्बोहाइड्रेट के पाचन में सहायक है।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"मानव शरीर की सबसे बड़ी ग्रंथि (Gland) कौन सी है?","options":["अग्न्याशय","यकृत (Liver)","थायराइड","पीयूष"],"correct":"यकृत (Liver)","strategy":"यकृत शरीर की सबसे बड़ी बाह्यस्रावी ग्रंथि है।"},{"type":"pyq","exam":"UPSC Prelims 2018","year":2018,"question":"इंसुलिन के बारे में कौन सा कथन सही है?","options":["यह यकृत द्वारा बनाया जाता है","यह एक स्टेरॉयड है","यह रक्त शर्करा को कम करता है","यह विटामिन है"],"correct":"यह रक्त शर्करा को कम करता है","strategy":"इंसुलिन एक पेप्टाइड हार्मोन है जो ग्लूकोज के स्तर को संतुलित करता है।"},{"type":"exam_pattern","topic":"Human Body Trend","analysis":"PSC Trend Analysis:","stats":["हार्मोन और ग्रंथियां: 2 प्रश्न","विटामिन और रोग: 1 प्रश्न","अंग प्रणालियाँ (Digestion/Heart): 2 प्रश्न"],"trend":"आयोग अब केवल ''तथ्य'' नहीं, बल्कि अंगों की ''कार्यप्रणाली'' (जैसे- किडनी का फिल्ट्रेशन) पर अधिक प्रश्न पूछ रहे हैं।"}],"en":[{"type":"h2","text":"Unit 7: Structure of the Human Body (Anatomy & Physiology)"},{"type":"p","text":"The human body functions like a complex machine coordinated by various organs and systems. It starts from the ''Cell'', which forms Tissues, then Organs, and finally a ''System''. In MPPSC, questions are frequently targeted at bones, enzymes, and Endocrine glands."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Skeletal & Muscular System"},{"type":"table","instruction":"Key Facts of the Skeletal System","head":["Topic","Fact"],"body":[["Total Bones","206 in adults (~300 in infants)"],["Largest Bone","Femur (Thigh bone)"],["Smallest Bone","Stapes (Middle ear)"],["Total Muscles","Approx 639"],["Bone to Bone connection","Ligament"],["Muscle to Bone connection","Tendon"]]},{"type":"h2","text":"2. Digestive & Respiratory System"},{"type":"image_tag","content":""},{"type":"ul","items":["**Digestion start:** Begins in the mouth where ''Ptyalin'' digests starch.","**Bile Juice:** Produced by the Liver and stored in the Gall Bladder.","**Insulin:** Secreted by the ''Islets of Langerhans'' in the Pancreas."]},{"type":"h2","text":"3. Circulatory & Nervous System"},{"type":"table","instruction":"Components of Circulatory System","head":["Component","Function / Property"],"body":[["Blood","Fluid connective tissue (pH 7.4)"],["Heart","4-chambered pumping organ"],["RBC","Transport of Oxygen (Lifespan 120 days)"],["WBC","Immunity (Soldiers of the body)"],["Brain","Cerebrum (Thinking), Cerebellum (Balance), Medulla (Involuntary)"]]},{"type":"highlight","level":"important","text":"Universal Donor: Blood group O; Universal Acceptor: Blood group AB.","icon":"🩸"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Which element is found in abundance in the human body?","options":["Iron","Sodium","Oxygen","Iodine"],"correct":"Oxygen (~65%)","strategy":"Most of the body weight is water and organic compounds, predominantly oxygen."},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"What is the source of the enzyme ''Ptyalin''?","options":["Pancreas","Liver","Salivary Glands","Stomach"],"correct":"Salivary Glands","strategy":"Saliva contains ptyalin, which initiates carbohydrate digestion."},{"type":"exam_pattern","topic":"Human Body Trend","analysis":"PSC Trend Analysis:","stats":["Hormones and Glands: 2 questions","Vitamins and Diseases: 1 question","Organ Systems: 2 questions"],"trend":"Commissions are now focusing more on ''Physiology'' (e.g., filtration process of kidney) rather than just static facts."}]}', 'biology', NULL, 35, 1, 1770921144, 1771008906, 'blog', 'unit_7', 'Structure of Human Body', 1, 0, 1, 1, 0, 'Unit 7: मानव शरीर की संरचना (Anatomy & Physiology) मानव शरीर एक जटिल मशीन की तरह है जो विभिन्न अंगों और तंत्रों (Systems) के समन्वय से चलता है। इसकी शुरुआत ''कोशिका'' (Cell) से होती है, जो मिलकर ऊतक (Ti...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('e24b768b-1d2f-4d7b-9d03-4f0749106d08', 'nutrition-nutrients-malnutrition-unit-7-mppsc', 'Nutrition, Food, Nutrients & Malnutrition | पोषण, आहार, पोषक तत्व और कुपोषण', 'Comprehensive analysis of human nutrition, macro and micro-nutrients, and the challenges of malnutrition. Detailed coverage for MPPSC Unit 7 with multi-state PSC PYQs.', '{"hi":[{"type":"h2","text":"Unit 7: पोषण, आहार, पोषक तत्व और कुपोषण"},{"type":"p","text":"पोषण वह प्रक्रिया है जिसके द्वारा जीव ऊर्जा और शारीरिक विकास के लिए भोजन प्राप्त करता है। संतुलित आहार में कार्बोहाइड्रेट, प्रोटीन, वसा, विटामिन और खनिज सही अनुपात में होने चाहिए। MPPSC में अक्सर विटामिन के वैज्ञानिक नाम और कुपोषण से होने वाली बीमारियों (जैसे क्वाशियोरकोर) पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. मुख्य पोषक तत्व (Macro and Micro Nutrients)"},{"type":"p","text":"पोषक तत्वों को उनकी आवश्यकता की मात्रा के आधार पर दो भागों में बांटा गया है।"},{"type":"table","instruction":"पोषक तत्वों का वर्गीकरण","head":["पोषक तत्व","कार्य (Function)","उदाहरण"],"body":[["कार्बोहाइड्रेट","तत्काल ऊर्जा प्रदान करना (Instant Energy)।","चावल, गेहूं, आलू, चीनी।"],["प्रोटीन","शरीर निर्माण और ऊतकों की मरम्मत (Body Building)।","दालें, सोयाबीन, अंडा, दूध।"],["वसा (Fats)","ऊर्जा का संचित भंडार (Energy Reserve)।","घी, तेल, मक्खन।"],["विटामिन एवं खनिज","रोग प्रतिरोधक क्षमता और उपापचय (Metabolism)।","फल, सब्जियां, सूखे मेवे।"]]},{"type":"h3","text":"विटामिन: महत्वपूर्ण तथ्य"},{"type":"ul","items":["**वसा में घुलनशील:** विटामिन A, D, E, K।","**जल में घुलनशील:** विटामिन B और C।","**विटामिन C:** गर्म करने पर सबसे पहले नष्ट होने वाला विटामिन है।"]},{"type":"h2","text":"2. कुपोषण (Malnutrition)"},{"type":"p","text":"जब शरीर को लंबे समय तक आवश्यक पोषक तत्व सही मात्रा में नहीं मिलते, तो वह स्थिति कुपोषण कहलाती है।"},{"type":"image_tag","content":"[Image comparing symptoms of Kwashiorkor and Marasmus in children]"},{"type":"table","instruction":"प्रमुख कमी वाले रोग (Deficiency Diseases)","head":["पोषक तत्व की कमी","बीमारी का नाम","प्रमुख लक्षण"],"body":[["प्रोटीन","क्वाशियोरकोर (Kwashiorkor)","बच्चे का पेट बाहर निकलना, पैरों में सूजन।"],["प्रोटीन एवं कैलोरी","मरास्मस (Marasmus)","शरीर का सूख जाना, पसलियां दिखाई देना।"],["विटामिन A","रतौंधी (Night Blindness)","कम रोशनी में दिखाई न देना।"],["विटामिन B1","बेरी-बेरी","तंत्रिका तंत्र की कमजोरी।"],["विटामिन C","स्कर्वी","मसूड़ों से खून आना।"],["विटामिन D","रिकेट्स","हड्डियों का कमजोर और टेढ़ा होना।"]]},{"type":"highlight","level":"important","text":"नोट: मध्य प्रदेश में कुपोषण दर को कम करने के लिए ''अटल बिहारी वाजपेयी बाल आरोग्य एवं पोषण मिशन'' संचालित है।","icon":"🛡️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"किस विटामिन की कमी से ''स्कर्वी'' (Scurvy) रोग होता है?","options":["विटामिन A","विटामिन B","विटामिन C","विटामिन D"],"correct":"विटामिन C","strategy":"विटामिन C (एस्कॉर्बिक एसिड) खट्टे फलों में पाया जाता है और इसकी कमी से मसूड़ों की समस्या होती है।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"सोयाबीन में प्रोटीन का प्रतिशत कितना होता है?","options":["30%","42%","50%","20%"],"correct":"42%","strategy":"सोयाबीन प्रोटीन का सबसे समृद्ध वनस्पति स्रोत है (विशेषकर म.प्र. के संदर्भ में महत्वपूर्ण)।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"निम्नलिखित में से कौन सा विटामिन जल में घुलनशील है?","options":["विटामिन A","विटामिन D","विटामिन E","विटामिन B"],"correct":"विटामिन B","strategy":"याद रखने की ट्रिक: ''WBC'' (W = Water, B and C are soluble)।"},{"type":"pyq","exam":"UPSC Prelims 2018","year":2018,"question":"''चावल को पॉलिश करने'' से कौन सा विटामिन नष्ट हो जाता है?","options":["कैल्सीफेरोल","थायमिन","एस्कॉर्बिक एसिड","रेटिनॉल"],"correct":"थायमिन (विटामिन B1)","strategy":"चावल की ऊपरी परत में थायमिन होता है जो पॉलिशिंग के दौरान निकल जाता है, जिससे बेरी-बेरी का खतरा बढ़ता है।"},{"type":"exam_pattern","topic":"Nutrition Trend","analysis":"PSC Trend Analysis:","stats":["विटामिन के नाम और कमी: 2 प्रश्न","प्रोटीन और वसा के स्रोत: 1 प्रश्न","कुपोषण और सरकारी योजनाएं: 1 प्रश्न"],"trend":"आयोग अब ''फोर्टिफाइड चावल'' (Fortified Rice) और ''एनीमिया मुक्त भारत'' जैसे करंट टॉपिक्स पर अधिक ध्यान दे रहे हैं।"}],"en":[{"type":"h2","text":"Unit 7: Nutrition, Food, Nutrients, and Malnutrition"},{"type":"p","text":"Nutrition is the process by which organisms obtain food for energy and physical development. A balanced diet should contain carbohydrates, proteins, fats, vitamins, and minerals in the correct proportions. In MPPSC, questions are often focused on the scientific names of vitamins and diseases caused by malnutrition like Kwashiorkor."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Classification of Nutrients"},{"type":"table","instruction":"Types of Nutrients","head":["Nutrient","Function","Examples"],"body":[["Carbohydrates","Primary source of instant energy.","Rice, Wheat, Potato, Sugar."],["Proteins","Body building and tissue repair.","Pulses, Soybean, Eggs, Milk."],["Fats","Stored energy reserve.","Ghee, Oil, Butter."],["Vitamins & Minerals","Immunity and metabolic regulation.","Fruits, Vegetables, Dry fruits."]]},{"type":"h2","text":"2. Malnutrition & Deficiency Diseases"},{"type":"p","text":"Malnutrition occurs when the body does not get the required amount of nutrients over a long period."},{"type":"image_tag","content":"[Image comparing symptoms of Kwashiorkor and Marasmus in children]"},{"type":"table","instruction":"Common Deficiency Diseases","head":["Deficiency","Disease","Symptoms"],"body":[["Protein","Kwashiorkor","Potbelly, edema in legs."],["Protein & Calories","Marasmus","Wasting of muscles, prominent ribs."],["Vitamin A","Night Blindness","Poor vision in low light."],["Vitamin B1","Beri-Beri","Nervous system weakness."],["Vitamin C","Scurvy","Bleeding gums."]]},{"type":"highlight","level":"important","text":"Note: Vitamin C is the most heat-sensitive vitamin and is destroyed first during cooking.","icon":"🛡️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Which vitamin deficiency causes Scurvy?","options":["Vitamin A","Vitamin B","Vitamin C","Vitamin D"],"correct":"Vitamin C","strategy":"Vitamin C (Ascorbic acid) is found in citrus fruits and prevents gum diseases."},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"Which of the following vitamins is water-soluble?","options":["Vitamin A","Vitamin D","Vitamin E","Vitamin B"],"correct":"Vitamin B","strategy":"Trick to remember: ''WBC'' (W = Water, B and C are soluble)."},{"type":"exam_pattern","topic":"Nutrition Trend","analysis":"PSC Trend Analysis:","stats":["Vitamin names & deficiencies: 2 questions","Protein & Fat sources: 1 question","Malnutrition stats: 1 question"],"trend":"Commissions are shifting focus towards ''Fortified Foods'' and ''Bio-fortification'' (e.g., Golden Rice)."}]}', 'biology_health', NULL, 35, 1, 1770921227, 1770921227, 'blog', 'unit_7', 'Nutrition, Food, Nutrient and Malnutrition', 1, 0, 0, 1, 0, 'Unit 7: पोषण, आहार, पोषक तत्व और कुपोषण पोषण वह प्रक्रिया है जिसके द्वारा जीव ऊर्जा और शारीरिक विकास के लिए भोजन प्राप्त करता है। संतुलित आहार में कार्बोहाइड्रेट, प्रोटीन, वसा, विटामिन और खनिज सही अनु...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('81850aad-8ba6-4441-94a7-217af9eabf3e', 'genetic-disease-sickle-cell-anemia-unit-7-mppsc', 'Genetic Diseases & Sickle Cell Anemia | आनुवंशिक रोग और सिकल सेल एनीमिया', 'A comprehensive analysis of genetic disorders with a deep dive into Sickle Cell Anemia (SCA). Covers causes, inheritance patterns, diagnosis, and the 2047 Elimination Mission for MPPSC Unit 7.', '{"hi":[{"type":"h2","text":"Unit 7: आनुवंशिक रोग और सिकल सेल एनीमिया"},{"type":"p","text":"आनुवंशिक रोग वे स्थितियाँ हैं जो DNA में असामान्य परिवर्तनों (Mutations) के कारण होती हैं। ये रोग माता-पिता से बच्चों में हस्तांतरित होते हैं। मध्य प्रदेश में जनजातीय जनसंख्या अधिक होने के कारण ''सिकल सेल एनीमिया'' एक गंभीर स्वास्थ्य चुनौती है। MPPSC में इसके आनुवंशिक पैटर्न और ''उन्मूलन मिशन 2047'' पर प्रश्न आना लगभग तय है।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. सिकल सेल एनीमिया: कारण (Cause)"},{"type":"p","text":"यह एक ''ऑटोसोमल रिसेसिव'' (Autosomal Recessive) विकार है। इसका मुख्य कारण हीमोग्लोबिन बनाने वाले **HBB जीन** में उत्परिवर्तन (Mutation) है।"},{"type":"ul","items":["**हीमोग्लोबिन S (HbS):** सामान्य हीमोग्लोबिन (HbA) के बजाय शरीर असामान्य हीमोग्लोबिन S बनाने लगता है।","**आकार में परिवर्तन:** कम ऑक्सीजन की स्थिति में लाल रक्त कोशिकाएं (RBCs) गोल होने के बजाय ''हँसिये'' (Sickle) के आकार की हो जाती हैं।","**आनुवंशिकी:** यदि दोनों माता-पिता ''कैरियर'' (Carrier) हैं, तो बच्चे को यह रोग होने की 25% संभावना होती है।"]},{"type":"image_tag","content":""},{"type":"h2","text":"2. प्रभाव एवं लक्षण (Effects & Symptoms)"},{"type":"table","instruction":"शरीर पर सिकल सेल के प्रभाव","head":["प्रभाव (Effect)","लक्षण (Symptoms)"],"body":[["एनीमिया (खून की कमी)","RBCs जल्दी मर जाते हैं (10-20 दिन), जिससे थकान और कमजोरी होती है।"],["दर्द संकट (Vaso-occlusive Crisis)","हँसिये के आकार की कोशिकाएं नसों में फंसकर तीव्र दर्द पैदा करती हैं।"],["अंगों की क्षति","तिल्ली (Spleen), लिवर और किडनी को रक्त की आपूर्ति कम होना।"],["विकास में देरी","बच्चों में शारीरिक विकास और यौवन (Puberty) में देरी।"],["हाथ-पैर में सूजन","रक्त प्रवाह रुकने से सूजन (Dactylitis)।"]]},{"type":"h2","text":"3. निदान और परीक्षण (Diagnosis)"},{"type":"p","text":"समय पर पहचान ही इस रोग के प्रबंधन का एकमात्र तरीका है।"},{"type":"ul","items":["**हीमोग्लोबिन इलेक्ट्रोफोरेसिस (Hb Electrophoresis):** यह सबसे सटीक परीक्षण है जो हीमोग्लोबिन के प्रकार की पहचान करता है।","**सॉल्युबिलिटी टेस्ट (Solubility Test):** स्क्रीनिंग के लिए शुरुआती टेस्ट।","**प्री-नेटल डायग्नोसिस:** गर्भावस्था के दौरान भ्रूण की जांच करना।"]},{"type":"h2","text":"4. राष्ट्रीय सिकल सेल एनीमिया उन्मूलन मिशन 2047"},{"type":"fact_card","title":"मिशन 2047: प्रमुख तथ्य","facts":["लॉन्च: 1 जुलाई 2023 को प्रधान मंत्री द्वारा **शाहडोल, मध्य प्रदेश** से।","लक्ष्य: वर्ष 2047 तक भारत से सिकल सेल एनीमिया को पूरी तरह समाप्त करना।","रणनीति: 17 उच्च-बोझ वाले राज्यों के 7 करोड़ लोगों की स्क्रीनिंग करना।","डिजिटल कार्ड: स्क्रीनिंग के बाद नागरिकों को ''सिकल सेल जेनेटिक स्टेटस कार्ड'' देना।"],"icon":"🛡️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"सिकल सेल एनीमिया किस प्रकार का रोग है?","options":["संक्रामक","आनुवंशिक","विटामिन की कमी से","प्रदूषण जनित"],"correct":"आनुवंशिक (Genetic)","strategy":"यह माता-पिता से DNA के माध्यम से बच्चों में आता है।"},{"type":"pyq","exam":"UPSC Prelims 2017","year":2017,"question":"सिकल सेल एनीमिया के बारे में क्या सत्य है?","options":["यह हीमोग्लोबिन की कमी है","RBCs का आकार बदल जाता है","यह केवल पुरुषों में होता है","A और B दोनों"],"correct":"A और B दोनों","strategy":"इसमें हीमोग्लोबिन असामान्य होता है और RBC का आकार हँसिये जैसा हो जाता है।"},{"type":"pyq","exam":"UPPSC Prelims 2020","year":2020,"question":"सिकल सेल एनीमिया मिशन 2047 की शुरुआत मध्य प्रदेश के किस जिले से हुई?","options":["झाबुआ","अलीराजपुर","शाहडोल","बड़वानी"],"correct":"शाहडोल","strategy":"यह म.प्र. के करेंट अफेयर्स और यूनिट 7 दोनों के लिए अति-महत्वपूर्ण है।"},{"type":"pyq","exam":"BPSC Prelims 2022","year":2022,"question":"मनुष्य में लाल रक्त कोशिकाओं (RBC) का औसत जीवनकाल कितना होता है?","options":["120 दिन","80 दिन","150 दिन","190 दिन"],"correct":"120 दिन","strategy":"सिकल सेल एनीमिया में यह घटकर मात्र 10-20 दिन रह जाता है।"},{"type":"exam_pattern","topic":"Genetic Disease Trend","analysis":"Competitive Exams Trend:","stats":["रोग का आनुवंशिक आधार (Recessive/Dominant): 1 प्रश्न","मिशन 2047 के लक्ष्य/स्थान: 2 प्रश्न","निदान की तकनीकें (Electrophoresis): 1 प्रश्न"],"trend":"आयोग अब जनजातीय क्षेत्रों में स्वास्थ्य नीतियों और सिकल सेल के ''जेनेटिक स्टेटस कार्ड'' जैसे विशिष्ट नवाचारों पर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 7: Genetic Diseases and Sickle Cell Anemia"},{"type":"p","text":"Genetic diseases are conditions caused by abnormal changes (Mutations) in DNA. These are inherited from parents to offspring. Due to the high tribal population in Madhya Pradesh, ''Sickle Cell Anemia'' is a major health challenge. In MPPSC, questions on its genetic pattern and the ''Elimination Mission 2047'' are highly expected."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Sickle Cell Anemia: Causes"},{"type":"p","text":"It is an ''Autosomal Recessive'' disorder caused by a mutation in the **HBB gene**, which provides instructions for making hemoglobin."},{"type":"ul","items":["**Hemoglobin S (HbS):** Instead of normal Hemoglobin A, the body produces abnormal Hemoglobin S.","**Shape Change:** In low-oxygen conditions, Red Blood Cells (RBCs) become ''sickle'' or crescent-shaped instead of disc-shaped.","**Inheritance:** If both parents are carriers, there is a 25% chance for the child to have the disease."]},{"type":"image_tag","content":""},{"type":"h2","text":"2. Effects and Diagnosis"},{"type":"table","instruction":"Impact of Sickle Cell on the Body","head":["Effect","Details"],"body":[["Anemia","Shortened life of RBCs (10-20 days instead of 120)."],["Pain Crisis","Sickle cells clog capillaries, causing extreme pain."],["Organ Damage","Restricted blood flow to Spleen, Liver, and Kidneys."],["Diagnosis","Hb Electrophoresis (Confirmative) and Solubility test (Screening)."]]},{"type":"h2","text":"3. National Sickle Cell Anemia Elimination Mission 2047"},{"type":"fact_card","title":"Mission 2047: Key Facts","facts":["Launch: 1st July 2023 by the PM from **Shahdol, Madhya Pradesh**.","Goal: To eliminate Sickle Cell Anemia from India by 2047.","Target: Screening 7 crore people across 17 high-burden states.","Digital Link: Provision of ''Sickle Cell Genetic Status Cards'' to all screened citizens."],"icon":"🛡️"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"What kind of disease is Sickle Cell Anemia?","options":["Infectious","Genetic","Nutritional","Pollution-based"],"correct":"Genetic","strategy":"It is passed from parents to children through DNA."},{"type":"exam_pattern","topic":"Genetic Disease Trend","analysis":"Competitive Exams Trend:","stats":["Genetic basis (Recessive/Dominant): 1 question","Mission 2047 objectives/location: 2 questions","Diagnostic techniques: 1 question"],"trend":"Commissions are now focusing on tribal health policies and specific innovations like ''Genetic Status Cards''."}]}', 'science_health', NULL, 35, 1, 1770921281, 1770921281, 'blog', 'unit_7', 'Genetic Disease, Sickle Cell Anemia: Cause, Effect, Diagnosis and Program', 1, 0, 0, 1, 0, 'Unit 7: आनुवंशिक रोग और सिकल सेल एनीमिया आनुवंशिक रोग वे स्थितियाँ हैं जो DNA में असामान्य परिवर्तनों (Mutations) के कारण होती हैं। ये रोग माता-पिता से बच्चों में हस्तांतरित होते हैं। मध्य प्रदेश में ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('99ea660c-1c0d-410d-a4df-ac293b141e17', 'health-policy-indicators-diseases-unit-7-mppsc', 'Health Policy, Indicators & Infectious Diseases | स्वास्थ्य नीति, सूचकांक और संक्रामक रोग', 'Comprehensive analysis of India''s health infrastructure, National Health Policy 2017, key health indicators (IMR/MMR), and prevention of infectious diseases for MPPSC Unit 7.', '{"hi":[{"type":"h2","text":"Unit 7: स्वास्थ्य नीति, कार्यक्रम और स्वास्थ्य सूचकांक"},{"type":"p","text":"भारत की स्वास्थ्य प्रणाली ''उपचार'' (Curative) से ''निवारण'' (Preventive) की ओर बढ़ रही है। राष्ट्रीय स्वास्थ्य नीति 2017 और आयुष्मान भारत जैसे कार्यक्रम इस बदलाव के आधार हैं। MPPSC में अक्सर स्वास्थ्य संकेतकों (जैसे IMR/MMR) और संक्रामक रोगों के कारकों (Pathogens) पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. राष्ट्रीय स्वास्थ्य नीति एवं कार्यक्रम (Health Policy & Programs)"},{"type":"p","text":"राष्ट्रीय स्वास्थ्य नीति (NHP) 2017 का मुख्य लक्ष्य स्वास्थ्य व्यय को जीडीपी के **2.5%** तक बढ़ाना है।"},{"type":"table","instruction":"प्रमुख स्वास्थ्य कार्यक्रम और लक्ष्य","head":["कार्यक्रम / लक्ष्य","विवरण / समय सीमा"],"body":[["आयुष्मान भारत (PM-JAY)","दुनिया की सबसे बड़ी स्वास्थ्य बीमा योजना (5 लाख प्रति परिवार)।"],["मिशन इंद्रधनुष","पूर्ण टीकाकरण (Immunization) कवरेज के लिए।"],["TB मुक्त भारत","भारत से क्षय रोग (TB) समाप्त करने का लक्ष्य - 2025।"],["जीवन प्रत्याशा (Life Expectancy)","इसे 67.5 से बढ़ाकर 70 करने का लक्ष्य।"],["TFR (कुल प्रजनन दर)","इसे 2.1 के स्तर (Replacement Level) पर लाना।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. संक्रामक रोग और रोकथाम (Infectious Diseases & Prevention)"},{"type":"p","text":"संक्रामक रोग बैक्टीरिया, वायरस, प्रोटोजोआ या कवक के माध्यम से फैलते हैं।"},{"type":"table","instruction":"प्रमुख रोग और उनके कारक","head":["बीमारी का प्रकार","बीमारी का नाम","कारक (Pathogen)"],"body":[["बैक्टीरिया (जीवाणु)","TB, हैजा, टाइफाइड, एंथ्रेक्स","माइकोबैक्टीरियम (TB के लिए)"],["वायरस (विषाणु)","एड्स, चेचक, कोविड-19, डेंगू","HIV, सार्स-कोव-2"],["प्रोटोजोआ","मलेरिया, कालाजार, पेचिश","प्लाज्मोडियम (मलेरिया)"],["कवक (Fungi)","दाद, एथलीट फुट","ट्राइकोफाइटन"]]},{"type":"highlight","level":"critical","text":"निवारण: संक्रामक रोगों की रोकथाम के लिए ''हर्ड इम्युनिटी'' (Herd Immunity) और ''यूनिवर्सल इम्यूनाइजेशन प्रोग्राम'' (UIP) सबसे प्रभावी तरीके हैं।","icon":"💉"},{"type":"h2","text":"3. स्वास्थ्य सूचकांक: भारत बनाम म.प्र. (Health Indicators)"},{"type":"p","text":"ये सूचकांक किसी भी राज्य की स्वास्थ्य स्थिति का वास्तविक आईना होते हैं। (डेटा स्रोत: NFHS-5 / SRS)"},{"type":"table","instruction":"प्रमुख स्वास्थ्य सूचक","head":["सूचक (Indicator)","भारत (India)","मध्य प्रदेश (MP)"],"body":[["IMR (शिशु मृत्यु दर)","28 प्रति 1000","43 (देश में सर्वाधिक)"],["MMR (मातृ मृत्यु दर)","97 प्रति 1 लाख","173 (सुधार जारी)"],["TFR (प्रजनन दर)","2.0","2.1"],["संस्थागत प्रसव","88.6%","90.7% (म.प्र. बेहतर प्रदर्शन)"]]},{"type":"fact_card","title":"म.प्र. स्वास्थ्य पहल: क्विक बाइट्स","facts":["जननी सुरक्षा योजना: संस्थागत प्रसव को बढ़ावा देने के लिए नकद सहायता।","साँस (SAANS) अभियान: निमोनिया के कारण शिशु मृत्यु दर को कम करने के लिए।","दीनदयाल अंत्योदय उपचार योजना: SC/ST परिवारों के लिए मुफ्त चिकित्सा सहायता।","लालिमा अभियान: म.प्र. को एनीमिया मुक्त बनाने के लिए।"],"icon":"🏥"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भारत में ''मिशन इंद्रधनुष'' (Mission Indradhanush) किससे संबंधित है?","options":["स्मार्ट सिटी","बच्चों का टीकाकरण","डिजिटल साक्षरता","महिला सुरक्षा"],"correct":"बच्चों का टीकाकरण (Immunization)","strategy":"यह 7 टीकों से बचाव के लिए शुरू किया गया था, अब इसमें अधिक टीके शामिल हैं।"},{"type":"pyq","exam":"UPSC Prelims 2017","year":2017,"question":"राष्ट्रीय स्वास्थ्य नीति 2017 का लक्ष्य स्वास्थ्य व्यय को GDP का कितना प्रतिशत करना है?","options":["1.5%","2.0%","2.5%","3.0%"],"correct":"2.5%","strategy":"नीति का स्पष्ट लक्ष्य सार्वजनिक स्वास्थ्य व्यय को 2025 तक 2.5% करना है।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"मलेरिया रोग का वाहक (Vector) कौन सा है?","options":["मादा एनोफिलीज","नर एनोफिलीज","एडीज एजिप्टी","क्यूलेक्स"],"correct":"मादा एनोफिलीज (Female Anopheles)","strategy":"मलेरिया प्लाज्मोडियम प्रोटोजोआ से होता है जिसे मादा एनोफिलीज फैलाती है।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"भारत से ''टीबी'' (TB) उन्मूलन का लक्ष्य वर्ष क्या है?","options":["2022","2025","2030","2024"],"correct":"2025","strategy":"वैश्विक लक्ष्य 2030 है, लेकिन भारत ने इसे 5 साल पहले (2025) खत्म करने का संकल्प लिया है।"},{"type":"exam_pattern","topic":"Health Policy Trend","analysis":"Competitive Exams Trend:","stats":["योजनाओं के लक्ष्य/वर्ष: 2 प्रश्न","सूचकांक (IMR/MMR): 1 प्रश्न","रोग और उनके वाहक: 1 प्रश्न"],"trend":"आयोग अब ''डिजिटल हेल्थ मिशन'' (ABDM) और ''एनीमिया मुक्त भारत'' के नवीनतम रैंकिंग पर अधिक ध्यान दे रहे हैं।"}],"en":[{"type":"h2","text":"Unit 7: Health Policy, Programs, and Health Indicators"},{"type":"p","text":"India''s health system is shifting from ''Curative'' to ''Preventive'' care. The National Health Policy (NHP) 2017 and programs like Ayushman Bharat are the pillars of this transition. In MPPSC, questions are often asked about health indicators (like IMR/MMR) and pathogens of infectious diseases."},{"type":"h2","text":"1. National Health Policy & Programs"},{"type":"table","instruction":"Major Health Programs and Targets","head":["Program / Target","Details / Timeline"],"body":[["Ayushman Bharat","World''s largest health insurance (5 lakh per family)."],["Mission Indradhanush","Targets full immunization coverage."],["TB Mukt Bharat","Target to eliminate TB from India by 2025."],["Life Expectancy","Target to increase from 67.5 to 70."],["TFR","Target to achieve Replacement Level of 2.1."]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. Infectious Diseases and Prevention"},{"type":"table","instruction":"Major Diseases and Pathogens","head":["Type","Disease Name","Pathogen"],"body":[["Bacterial","TB, Cholera, Typhoid, Anthrax","Mycobacterium (for TB)"],["Viral","AIDS, Smallpox, COVID-19, Dengue","HIV, SARS-CoV-2"],["Protozoal","Malaria, Kala-azar, Dysentery","Plasmodium (for Malaria)"],["Fungal","Ringworm, Athlete’s foot","Trichophyton"]]},{"type":"h2","text":"3. Health Indicators: India vs MP"},{"type":"table","instruction":"Key Health Indicators","head":["Indicator","India","Madhya Pradesh"],"body":[["IMR (Infant Mortality)","28 per 1000","43 (Highest in India)"],["MMR (Maternal Mortality)","97 per 1 Lakh","173 (Improving)"],["TFR (Fertility Rate)","2.0","2.1"],["Institutional Delivery","88.6%","90.7% (MP performing better)"]]},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"What is ''Mission Indradhanush'' related to in India?","options":["Smart Cities","Immunization of Children","Digital Literacy","Women Safety"],"correct":"Immunization of Children","strategy":"Started for protection against 7 vaccine-preventable diseases."},{"type":"pyq","exam":"UPSC Prelims 2017","year":2017,"question":"NHP 2017 aims to increase health expenditure to what percentage of GDP?","options":["1.5%","2.0%","2.5%","3.0%"],"correct":"2.5%","strategy":"Target is to reach 2.5% of GDP by 2025."},{"type":"exam_pattern","topic":"Health Policy Trend","analysis":"Competitive Exams Trend:","stats":["Schemes & Targets: 2 questions","Indicators (IMR/MMR): 1 question","Diseases & Vectors: 1 question"],"trend":"Commissions are now focusing more on the Digital Health Mission (ABDM) and the latest rankings of ''Anemia Mukt Bharat''."}]}', 'health_science', NULL, 40, 1, 1770921355, 1770921355, 'blog', 'unit_7', 'Health Policy and Programmes, Infectious disease and its Prevention and Health Indicator', 1, 0, 0, 1, 0, 'Unit 7: स्वास्थ्य नीति, कार्यक्रम और स्वास्थ्य सूचकांक भारत की स्वास्थ्य प्रणाली ''उपचार'' (Curative) से ''निवारण'' (Preventive) की ओर बढ़ रही है। राष्ट्रीय स्वास्थ्य नीति 2017 और आयुष्मान भारत जैसे कार्य...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('3af4ec6e-5b92-45ef-a92b-5438d367c0b1', 'sustainable-development-sdg-unit-7-mppsc', 'Sustainable Development & SDGs | सतत विकास और SDG लक्ष्य', 'An in-depth guide to the evolution of Sustainable Development and a detailed analysis of the 17 SDGs. Includes NITI Aayog''s Index data and high-yield PYQs for MPPSC Unit 7.', '{"hi":[{"type":"h2","text":"Unit 7: सतत विकास (Sustainable Development) की अवधारणा और SDG"},{"type":"p","text":"सतत विकास का अर्थ है—''ऐसा विकास जो वर्तमान पीढ़ी की आवश्यकताओं को इस प्रकार पूरा करे कि भविष्य की पीढ़ियों की अपनी आवश्यकताओं को पूरा करने की क्षमता से समझौता न हो।'' यह अवधारणा संसाधनों के विवेकपूर्ण उपयोग और पर्यावरण संरक्षण पर टिकी है। MPPSC में अक्सर Brundtland Report और 17 लक्ष्यों (SDGs) के विशिष्ट नंबरों पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. सतत विकास का विकासक्रम (Evolution of Concept)"},{"type":"p","text":"सतत विकास की यात्रा 1970 के दशक से शुरू होकर आज वैश्विक एजेंडा बन चुकी है।"},{"type":"ul","items":["**ब्रंटलैंड रिपोर्ट (1987):** इस रिपोर्ट (Our Common Future) में पहली बार ''सतत विकास'' को परिभाषित किया गया।","**पृथ्वी सम्मेलन (1992):** रियो डी जेनेरियो में आयोजित, जहाँ ''एजेंडा 21'' अपनाया गया।","**मिलेनियम डेवलपमेंट गोल्स (MDGs):** 2000-2015 तक के लिए 8 लक्ष्य निर्धारित किए गए थे।","**SDGs (2016-2030):** सितंबर 2015 में UN महासभा ने 17 लक्ष्यों और 169 उप-लक्ष्यों को अपनाया।"]},{"type":"h2","text":"2. 17 सतत विकास लक्ष्य (17 SDGs)"},{"type":"p","text":"इन लक्ष्यों को 2030 तक प्राप्त करना अनिवार्य है। परीक्षा के लिए लक्ष्यों का ''नंबर'' याद रखना बहुत ज़रूरी है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"महत्वपूर्ण SDG लक्ष्य (परीक्षा हेतु)","head":["लक्ष्य संख्या","विषय (Goal Topic)"],"body":[["SDG 1","शून्य गरीबी (No Poverty)"],["SDG 2","शून्य भूख (Zero Hunger)"],["SDG 3","अच्छा स्वास्थ्य और कल्याण (Good Health)"],["SDG 4","गुणवत्तापूर्ण शिक्षा (Quality Education)"],["SDG 5","लैंगिक समानता (Gender Equality)"],["SDG 6","स्वच्छ जल और स्वच्छता (Clean Water)"],["SDG 7","किफायती और स्वच्छ ऊर्जा (Clean Energy)"],["SDG 13","जलवायु कार्रवाई (Climate Action)"],["SDG 15","भूमि पर जीवन (Life on Land)"]]},{"type":"h2","text":"3. भारत और मध्य प्रदेश की स्थिति (SDG Index 2025-26)"},{"type":"fact_card","title":"NITI Aayog SDG इंडिया इंडेक्स","facts":["नोडल एजेंसी: भारत में नीति आयोग SDGs की निगरानी करता है।","म.प्र. की रैंकिंग: मध्य प्रदेश ''फ्रंट रनर'' (Front Runner) श्रेणी में शामिल है।","म.प्र. का सर्वश्रेष्ठ प्रदर्शन: SDG 7 (Clean Energy) और SDG 15 (Life on Land) में।","चुनौतियां: SDG 2 (Zero Hunger) और SDG 5 (Gender Equality) में अभी भी सुधार की आवश्यकता है।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"सतत विकास के लिए ''ब्रंटलैंड रिपोर्ट'' किस वर्ष जारी की गई थी?","options":["1985","1987","1992","1990"],"correct":"1987","strategy":"इसे ''Our Common Future'' के नाम से भी जाना जाता है।"},{"type":"pyq","exam":"UPSC Prelims 2016","year":2016,"question":"''सतत विकास लक्ष्य'' (SDGs) को पहली बार 1972 में एक वैश्विक थिंक टैंक ने प्रस्तावित किया था, जिसे कहा जाता है?","options":["कमीशन ऑन सस्टेनेबल डेवलपमेंट","क्लब ऑफ रोम","वर्ल्ड रिसोर्स इंस्टीट्यूट","विश्व बैंक"],"correct":"क्लब ऑफ रोम (Club of Rome)","strategy":"क्लब ऑफ रोम की रिपोर्ट ''Limits to Growth'' ने इसकी नींव रखी थी।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"SDG लक्ष्य संख्या 6 का संबंध किससे है?","options":["गुणवत्तापूर्ण शिक्षा","स्वच्छ जल और स्वच्छता","शून्य गरीबी","जलवायु परिवर्तन"],"correct":"स्वच्छ जल और स्वच्छता (Clean Water & Sanitation)","strategy":"गोल नंबर्स की मैचिंग UPPSC और MPPSC का सबसे प्रिय टॉपिक है।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"सतत विकास लक्ष्यों को प्राप्त करने की अंतिम समय सीमा क्या है?","options":["2022","2025","2030","2050"],"correct":"2030","strategy":"इसे ''एजेंडा 2030'' के रूप में जाना जाता है।"},{"type":"exam_pattern","topic":"Sustainable Development Trend","analysis":"Competitive Exams Trend:","stats":["SDG गोल मैचिंग (Goal Numbers): 2 प्रश्न","महत्वपूर्ण सम्मेलन (Conference/Date): 1 प्रश्न","नीति आयोग इंडेक्स रैंकिंग: 1 प्रश्न"],"trend":"आयोग अब ''सस्टेनेबल एग्रीकल्चर'' और ''सर्कुलर इकोनॉमी'' जैसे एप्लाइड टॉपिक्स को SDGs के साथ जोड़कर पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 7: Concept of Sustainable Development and SDGs"},{"type":"p","text":"Sustainable development is defined as ''development that meets the needs of the present without compromising the ability of future generations to meet their own needs.'' In MPPSC, questions are frequently asked on the Brundtland Report and the specific numbers of the 17 goals."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Key Milestones"},{"type":"ul","items":["**Brundtland Report (1987):** Titled ''Our Common Future'', it popularized the term.","**Earth Summit (1992):** Adopted ''Agenda 21'' in Rio.","**MDGs (2000-2015):** 8 pre-SDG targets focused on developing nations.","**SDGs (2016-2030):** 17 goals adopted by the UN General Assembly in Sept 2015."]},{"type":"h2","text":"2. 17 Sustainable Development Goals"},{"type":"image_tag","content":""},{"type":"table","instruction":"Important SDG Goals for Exams","head":["Goal No.","Topic"],"body":[["SDG 1","No Poverty"],["SDG 2","Zero Hunger"],["SDG 3","Good Health and Well-being"],["SDG 4","Quality Education"],["SDG 5","Gender Equality"],["SDG 6","Clean Water and Sanitation"],["SDG 13","Climate Action"],["SDG 15","Life on Land"]]},{"type":"h2","text":"3. India & MP Scenario"},{"type":"fact_card","title":"NITI Aayog SDG Index 2025-26","facts":["Nodal Agency: NITI Aayog monitors SDG progress in India.","MP Category: MP falls under the ''Front Runner'' category.","Strengths: Excellent performance in SDG 7 (Clean Energy) and SDG 15 (Forests).","Challenges: Improvement needed in SDG 2 (Hunger) and SDG 5 (Gender gap)."],"icon":"🏛️"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"In which year was the Brundtland Report released?","options":["1985","1987","1992","1990"],"correct":"1987","strategy":"Also known as ''Our Common Future''."},{"type":"exam_pattern","topic":"Sustainable Development Trend","analysis":"Competitive Exams Trend:","stats":["SDG Goal Matching: 2 questions","Major Conferences/Dates: 1 question","NITI Aayog Index ranking: 1 question"],"trend":"Commissions are now linking SDGs with ''Sustainable Agriculture'' and ''Circular Economy'' concepts."}]}', 'environment', NULL, 35, 1, 1770921415, 1770921415, 'blog', 'unit_7', 'Concept of Sustainable Development and SDG''s', 1, 0, 0, 1, 0, 'Unit 7: सतत विकास (Sustainable Development) की अवधारणा और SDG सतत विकास का अर्थ है—''ऐसा विकास जो वर्तमान पीढ़ी की आवश्यकताओं को इस प्रकार पूरा करे कि भविष्य की पीढ़ियों की अपनी आवश्यकताओं को पूरा करने...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('6c1c3d67-10fd-4949-860b-5f0db21f8003', 'environment-biodiversity-ecosystem-unit-7-mppsc', 'Environment, Biodiversity & Ecosystem | पर्यावरण, जैव विविधता और पारिस्थितिकी तंत्र', 'An exhaustive guide to environmental factors, types of ecosystems, and biodiversity conservation strategies. Tailored for MPPSC Unit 7 with a focus on latest ecological trends and multi-state PSC PYQs.', '{"hi":[{"type":"h2","text":"Unit 7: पर्यावरण, जैव विविधता और पारिस्थितिकी तंत्र"},{"type":"p","text":"पर्यावरण हमारे चारों ओर का आवरण है जिसमें जैविक (Biotic) और अजैविक (Abiotic) घटक शामिल हैं। पारिस्थितिकी तंत्र (Ecosystem) प्रकृति की वह क्रियात्मक इकाई है जहाँ जीव आपस में और अपने भौतिक वातावरण के साथ अंतःक्रिया करते हैं। MPPSC में अक्सर पारिस्थितिक पिरामिड, खाद्य जाल और जैव विविधता के हॉटस्पॉट्स पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. पर्यावरणीय कारक (Environmental Factors)"},{"type":"p","text":"ये कारक जीवों के वितरण और व्यवहार को नियंत्रित करते हैं।"},{"type":"ul","items":["**अजैविक घटक (Abiotic):** तापमान, प्रकाश, जल, मृदा और वायु। (तापमान जीवों के मेटाबॉलिज्म को प्रभावित करने वाला सबसे महत्वपूर्ण कारक है)।","**जैविक घटक (Biotic):** उत्पादक (Plants), उपभोक्ता (Animals) और अपघटक (Bacteria/Fungi)।"]},{"type":"h2","text":"2. पारिस्थितिकी तंत्र (Ecosystem): संरचना और कार्य"},{"type":"p","text":"ए.जी. टांसले (1935) ने ''पारिस्थितिकी तंत्र'' शब्द दिया था। इसमें ऊर्जा का प्रवाह हमेशा **एकदिशीय (Unidirectional)** होता है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"पारिस्थितिकी तंत्र के महत्वपूर्ण नियम","head":["नियम / शब्द","प्रतिपादक / विवरण"],"body":[["10% का नियम","लिंडमैन (Lindeman) - एक स्तर से दूसरे स्तर तक केवल 10% ऊर्जा पहुँचती है।"],["इकोलॉजी (Ecology) शब्द","अर्न्स्ट हेकल (Ernst Haeckel)"],["इकोलॉजिकल निके (Niche)","जोसेफ ग्रिनेल (Joseph Grinnell) - जीव की कार्यात्मक भूमिका।"],["पारिस्थितिक पिरामिड","चार्ल्स एल्टन - ऊर्जा, संख्या और जैवभार (Biomass) के पिरामिड।"]]},{"type":"h2","text":"3. जैव विविधता (Biodiversity) और संरक्षण"},{"type":"p","text":"जैव विविधता का अर्थ है पृथ्वी पर जीवन की विविधता। भारत में 4 वैश्विक ''हॉटस्पॉट्स'' (Hotspots) हैं।"},{"type":"image_tag","content":""},{"type":"table","instruction":"संरक्षण की विधियाँ (Conservation Methods)","head":["विधि (Method)","विवरण / उदाहरण"],"body":[["इन-सिटू (In-situ)","प्राकृतिक आवास में संरक्षण। (उदा: नेशनल पार्क, बायोस्फीयर रिजर्व, अभयारण्य)"],["एक्स-सिटू (Ex-situ)","आवास के बाहर कृत्रिम संरक्षण। (उदा: चिड़ियाघर, बॉटनिकल गार्डन, सीड बैंक)"],["म.प्र. का विशेष","कुनो नेशनल पार्क (चीता पुनरुद्धार परियोजना के लिए प्रसिद्ध)।"]]},{"type":"highlight","level":"important","text":"याद रखें: जैव विविधता दिवस 22 मई को मनाया जाता है।","icon":"🌿"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"पारिस्थितिकी तंत्र (Ecosystem) शब्द का प्रथम प्रयोग किसने किया था?","options":["ए.जी. टांसले","अर्न्स्ट हेकल","चार्ल्स एल्टन","ई.पी. ओडम"],"correct":"ए.जी. टांसले (A.G. Tansley)","strategy":"हेकल ने ''इकोलॉजी'' शब्द दिया था, जबकि टांसले ने ''इकोसिस्टम'' (1935)।"},{"type":"pyq","exam":"UPSC Prelims 2018","year":2018,"question":"पारिस्थितिकी तंत्र में ऊर्जा का प्रवाह कैसा होता है?","options":["एकदिशीय","द्विदिशीय","चक्रीय","इनमें से कोई नहीं"],"correct":"एकदिशीय (Unidirectional)","strategy":"ऊर्जा हमेशा उत्पादक से उपभोक्ता की ओर जाती है और वापस नहीं आती।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"निम्नलिखित में से कौन सा एक ''इन-सिटू'' (In-situ) संरक्षण का उदाहरण नहीं है?","options":["राष्ट्रीय उद्यान","वन्यजीव अभयारण्य","वनस्पति उद्यान (Botanical Garden)","बायोस्फीयर रिजर्व"],"correct":"वनस्पति उद्यान (Botanical Garden)","strategy":"बॉटनीकल गार्डन ''एक्स-सिटू'' (Ex-situ) संरक्षण का हिस्सा है।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"भारत में जैव विविधता की दृष्टि से सबसे धनी क्षेत्र कौन सा है?","options":["पश्चिमी घाट","पूर्वी घाट","थार रेगिस्तान","बंगाल की खाड़ी"],"correct":"पश्चिमी घाट (Western Ghats)","strategy":"पश्चिमी घाट और हिमालय भारत के प्रमुख हॉटस्पॉट्स हैं।"},{"type":"exam_pattern","topic":"Environment Trend","analysis":"Competitive Exams Trend:","stats":["महत्वपूर्ण शब्दावली और वैज्ञानिक: 2 प्रश्न","खाद्य श्रृंखला और पिरामिड: 1 प्रश्न","संरक्षण विधियाँ और राष्ट्रीय उद्यान: 2 प्रश्न"],"trend":"आयोग अब ''क्लाइमेट चेंज'' के साथ-साथ ''ब्लू कार्बन'' और ''इकोलॉजिकल फुटप्रिंट'' जैसे आधुनिक कॉन्सेप्ट्स पर अधिक ध्यान दे रहे हैं।"}],"en":[{"type":"h2","text":"Unit 7: Environment, Biodiversity, and Ecosystem"},{"type":"p","text":"The environment consists of Biotic and Abiotic components. An ecosystem is a functional unit of nature where organisms interact among themselves and with their physical surroundings. In MPPSC, questions are often asked about ecological pyramids, food webs, and biodiversity hotspots."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Environmental Factors"},{"type":"table","instruction":"Biotic vs Abiotic Factors","head":["Component","Factors","Description"],"body":[["Abiotic","Temp, Light, Water, Soil","Non-living physical and chemical elements."],["Biotic","Plants, Animals, Fungi","Living organisms that interact within the ecosystem."]]},{"type":"h2","text":"2. Ecosystem: Functions and Laws"},{"type":"image_tag","content":""},{"type":"ul","items":["**A.G. Tansley (1935):** Coined the term ''Ecosystem''.","**Energy Flow:** Always unidirectional and follows the **10% Law** (Lindeman).","**Pyramids:** Usually, energy pyramids are always upright, whereas biomass pyramids can be inverted in aquatic systems."]},{"type":"h2","text":"3. Biodiversity Conservation"},{"type":"image_tag","content":""},{"type":"table","instruction":"Conservation Strategies","head":["Type","Description","Examples"],"body":[["In-situ","Conservation within the natural habitat.","National Parks, Biosphere Reserves."],["Ex-situ","Conservation outside the natural habitat.","Zoological Parks, Seed Banks, Botanical Gardens."]]},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Who coined the term ''Ecosystem''?","options":["A.G. Tansley","Ernst Haeckel","Charles Elton","E.P. Odum"],"correct":"A.G. Tansley","strategy":"Tansley coined ''Ecosystem'' (1935) while Haeckel coined ''Ecology''."},{"type":"exam_pattern","topic":"Environment Trend","analysis":"Competitive Exams Trend:","stats":["Key Terminology & Scientists: 2 questions","Energy Flow & Pyramids: 1 question","Conservation & National Parks: 2 questions"],"trend":"Commissions are shifting focus towards modern concepts like ''Blue Carbon'' and ''Ecological Footprint'' alongside climate change."}]}', 'environment_ecology', NULL, 40, 1, 1770921448, 1770921448, 'blog', 'unit_7', 'Environmental Factors, Biodiversity and Ecosystem', 1, 0, 0, 1, 0, 'Unit 7: पर्यावरण, जैव विविधता और पारिस्थितिकी तंत्र पर्यावरण हमारे चारों ओर का आवरण है जिसमें जैविक (Biotic) और अजैविक (Abiotic) घटक शामिल हैं। पारिस्थितिकी तंत्र (Ecosystem) प्रकृति की वह क्रियात्मक ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('58a670e6-1e96-4a35-9465-a1adefd76178', 'pollution-disaster-management-unit-7-mppsc', 'Pollution, Natural Calamities & Disaster Management | प्रदूषण, प्राकृतिक आपदाएं और प्रबंधन', 'An exhaustive guide to types of pollution, natural calamities, and the institutional framework of disaster management in India. Tailored for MPPSC Unit 7 with latest environmental data and multi-state PSC PYQs.', '{"hi":[{"type":"h2","text":"Unit 7: प्रदूषण, प्राकृतिक आपदाएं और आपदा प्रबंधन"},{"type":"p","text":"पर्यावरण का संतुलन प्रदूषण और प्राकृतिक आपदाओं के कारण बिगड़ रहा है। ''प्रदूषण'' मानवीय गतिविधियों का परिणाम है, जबकि ''आपदाएं'' प्राकृतिक और मानव-जनित दोनों हो सकती हैं। MPPSC में अक्सर प्रदूषकों के प्रकार (Primary vs Secondary), भोपाल गैस त्रासदी और आपदा प्रबंधन के संस्थागत ढांचे (NDMA/SDMA) पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. प्रदूषण: प्रकार और कारक (Pollution)"},{"type":"p","text":"प्रदूषण का अर्थ है पर्यावरण में हानिकारक पदार्थों का प्रवेश। प्रदूषकों को उनकी प्रकृति के आधार पर बांटा जाता है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"प्रदूषण के प्रकार और मुख्य बिंदु","head":["प्रदूषण","मुख्य प्रदूषक / कारक","प्रभाव / तथ्य"],"body":[["वायु प्रदूषण","CO, SO2, NO2, PM 2.5","अम्ल वर्षा (Acid Rain) के लिए SO2 और NO2 जिम्मेदार।"],["जल प्रदूषण","आर्सेनिक, फ्लोराइड, मरकरी","मरकरी (पारा) से ''मिनीमाता'' और कैडमियम से ''इटाई-इटाई'' रोग।"],["मृदा प्रदूषण","कीटनाशक, प्लास्टिक, भारी धातु","जैव-आवर्धन (Biomagnification) के कारण खाद्य श्रृंखला प्रभावित।"],["ध्वनि प्रदूषण","डेसिबल (dB) में मापन","आवासीय क्षेत्र हेतु दिन में 55 dB और रात में 45 dB मानक।"]]},{"type":"highlight","level":"important","text":"भोपाल गैस त्रासदी (1984): 2-3 दिसंबर की रात को ''यूनियन कार्बाइड'' फैक्ट्री से ''मिथाइल आइसोसाइनेट'' (MIC) गैस का रिसाव हुआ था। यह म.प्र. का सबसे बड़ा मानव-जनित प्रदूषण हादसा है।","icon":"⚠️"},{"type":"h2","text":"2. प्राकृतिक आपदाएं (Natural Calamities)"},{"type":"p","text":"प्राकृतिक आपदाएं अचानक होने वाली घटनाएं हैं जो बड़े पैमाने पर जीवन और संपत्ति का नुकसान करती हैं।"},{"type":"image_tag","content":""},{"type":"ul","items":["**भूकंप (Earthquake):** रिक्टर स्केल पर मापन। भारत को 4 भूकंपीय क्षेत्रों (Zone II से V) में बांटा गया है।","**बाढ़ (Flood):** म.प्र. में नर्मदा और चंबल नदियाँ बाढ़ के प्रति संवेदनशील हैं।","**सूखा (Drought):** बुंदेलखंड क्षेत्र म.प्र. का सबसे सूखा प्रभावित क्षेत्र है।","**चक्रवात (Cyclone):** भारत के तटीय क्षेत्रों में अधिक प्रभाव (जैसे हाल ही में ''बिपारजॉय'')।"]},{"type":"h2","text":"3. आपदा प्रबंधन (Disaster Management)"},{"type":"p","text":"आपदा प्रबंधन का अर्थ है आपदा के प्रभाव को कम करने के लिए की गई योजना और तैयारी।"},{"type":"image_tag","content":""},{"type":"table","instruction":"आपदा प्रबंधन का संस्थागत ढांचा (भारत)","head":["स्तर (Level)","संस्था (Authority)","अध्यक्ष (Head)"],"body":[["राष्ट्रीय स्तर","NDMA (स्थापना 2005)","प्रधानमंत्री"],["राज्य स्तर","SDMA","मुख्यमंत्री"],["जिला स्तर","DDMA","जिला कलेक्टर / मजिस्ट्रेट"]]},{"type":"fact_card","title":"वैश्विक ढांचा: सेंडाई फ्रेमवर्क","facts":["सेंडाई फ्रेमवर्क (Sendai Framework): 2015-2030 तक आपदा जोखिम को कम करने हेतु वैश्विक समझौता।","NDRF: नेशनल डिजास्टर रिस्पांस फोर्स, जिसका गठन आपदा प्रबंधन अधिनियम 2005 के तहत हुआ।","म.प्र. राज्य आपदा प्रबंधन प्राधिकरण: इसका मुख्यालय भोपाल में स्थित है।"],"icon":"🏢"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"भोपाल गैस त्रासदी में किस गैस का रिसाव हुआ था?","options":["फॉस्जीन","मिथाइल आइसोसाइनेट","कार्बन मोनोऑक्साइड","क्लोरीन"],"correct":"मिथाइल आइसोसाइनेट","strategy":"इसे शार्ट में MIC कहा जाता है, यह प्रश्न MPPSC का मोस्ट रिपीटेड सवाल है।"},{"type":"pyq","exam":"UPSC Prelims 2019","year":2019,"question":"निम्नलिखित में से कौन सा एक द्वितीयक प्रदूषक (Secondary Pollutant) है?","options":["कार्बन मोनोऑक्साइड","फ्लाई एश","ओजोन","सल्फर डाइऑक्साइड"],"correct":"ओजोन (O3)","strategy":"ओजोन सतह पर प्राथमिक प्रदूषकों की रासायनिक क्रिया से बनती है।"},{"type":"pyq","exam":"UPPSC Prelims 2020","year":2020,"question":"''इटाई-इटाई'' रोग किसके पुराने विषाक्तन (Poisoning) के कारण होता है?","options":["पारा (Mercury)","कैडमियम","सीसा (Lead)","आर्सेनिक"],"correct":"कैडमियम","strategy":"पारा से मिनीमाता और कैडमियम से इटाई-इटाई (हड्डियों का रोग) होता है।"},{"type":"pyq","exam":"BPSC Prelims 2021","year":2021,"question":"राष्ट्रीय आपदा प्रबंधन प्राधिकरण (NDMA) का अध्यक्ष कौन होता है?","options":["गृह मंत्री","राष्ट्रपति","प्रधानमंत्री","थल सेना प्रमुख"],"correct":"प्रधानमंत्री","strategy":"आपदा प्रबंधन अधिनियम 2005 के अनुसार PM इसके पदेन अध्यक्ष होते हैं।"},{"type":"exam_pattern","topic":"Disaster & Pollution Trend","analysis":"Competitive Exams Trend:","stats":["प्रदूषण और बीमारियाँ: 2 प्रश्न","आपदा प्रबंधन अधिनियम/संस्था: 1 प्रश्न","प्रमुख आपदाएं (Case Studies): 1 प्रश्न"],"trend":"आयोग अब ''ई-वेस्ट'' (E-waste) और ''जलवायु परिवर्तन'' के कारण बढ़ते चक्रवातों के तकनीकी कारणों पर अधिक ध्यान दे रहा है।"}],"en":[{"type":"h2","text":"Unit 7: Pollution, Natural Calamities, and Disaster Management"},{"type":"p","text":"The ecological balance is being disrupted by pollution and natural calamities. While pollution is a result of human activities, disasters can be both natural and man-made. In MPPSC, questions are often asked about types of pollutants (Primary vs Secondary), the Bhopal Gas Tragedy, and the institutional framework of Disaster Management (NDMA/SDMA)."},{"type":"h2","text":"1. Pollution: Types and Agents"},{"type":"image_tag","content":""},{"type":"table","instruction":"Types of Pollution & Key Points","head":["Pollution","Major Pollutants","Impact / Facts"],"body":[["Air Pollution","CO, SO2, NO2, PM 2.5","SO2 and NO2 are responsible for Acid Rain."],["Water Pollution","Arsenic, Fluoride, Mercury","Mercury causes ''Minamata'' and Cadmium causes ''Itai-Itai'' disease."],["Soil Pollution","Pesticides, Plastic, Metals","Food chain affected due to Biomagnification."],["Noise Pollution","Measured in Decibels (dB)","Standard for residential areas: 55 dB (Day) and 45 dB (Night)."]]},{"type":"highlight","level":"important","text":"Bhopal Gas Tragedy (1984): Leakage of ''Methyl Isocyanate'' (MIC) from the Union Carbide factory on the night of Dec 2-3. It is the biggest industrial disaster in MP.","icon":"⚠️"},{"type":"h2","text":"2. Natural Calamities"},{"type":"image_tag","content":""},{"type":"ul","items":["**Earthquake:** Measured on the Richter scale. India is divided into 4 seismic zones (Zone II to V).","**Flood:** In MP, Narmada and Chambal rivers are prone to flooding.","**Drought:** Bundelkhand is the most drought-affected region of MP.","**Cyclone:** High impact in coastal areas (e.g., recent ''Biparjoy'')."]},{"type":"h2","text":"3. Disaster Management"},{"type":"image_tag","content":""},{"type":"table","instruction":"Institutional Framework in India","head":["Level","Authority","Head"],"body":[["National","NDMA (Est. 2005)","Prime Minister"],["State","SDMA","Chief Minister"],["District","DDMA","District Collector / Magistrate"]]},{"type":"fact_card","title":"Global Framework: Sendai","facts":["Sendai Framework: A global agreement (2015-2030) to reduce disaster risk.","NDRF: Formed under the DM Act 2005 for specialized response.","MP State DM Authority: Headquarters located in Bhopal."],"icon":"🏢"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Which gas was leaked in the Bhopal Gas Tragedy?","options":["Phosgene","Methyl Isocyanate","Carbon Monoxide","Chlorine"],"correct":"Methyl Isocyanate","strategy":"Also known as MIC, this is a highly repeated question in MPPSC."},{"type":"pyq","exam":"UPSC Prelims 2019","year":2019,"question":"Which of the following is a secondary pollutant?","options":["Carbon Monoxide","Fly Ash","Ozone","Sulphur Dioxide"],"correct":"Ozone (O3)","strategy":"Ozone at the ground level is formed by chemical reactions of primary pollutants."},{"type":"exam_pattern","topic":"Disaster & Pollution Trend","analysis":"Competitive Exams Trend:","stats":["Pollution and Diseases: 2 questions","DM Act/Authorities: 1 question","Major Calamities: 1 question"],"trend":"Commissions are focusing more on ''E-waste'' and the technical reasons behind increasing cyclones due to climate change."}]}', 'environment_disaster_management', NULL, 45, 1, 1770921503, 1770921503, 'blog', 'unit_7', 'Pollution, Natural Calamities and Management', 1, 0, 0, 1, 0, 'Unit 7: प्रदूषण, प्राकृतिक आपदाएं और आपदा प्रबंधन पर्यावरण का संतुलन प्रदूषण और प्राकृतिक आपदाओं के कारण बिगड़ रहा है। ''प्रदूषण'' मानवीय गतिविधियों का परिणाम है, जबकि ''आपदाएं'' प्राकृतिक और मानव-जनित दोन...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('24249776-f562-4a70-8882-3bc9b8072fb0', 'international-current-events-unit-8-mppsc', 'International Current Events 2025-26 | अंतर्राष्ट्रीय समसामयिक घटनाएं', 'Comprehensive analysis of major international events, summits, and geopolitical developments from 2025 to early 2026. Tailored for MPPSC Unit 8 with multi-state PSC PYQs.', '{"hi":[{"type":"h2","text":"Unit 8: अंतर्राष्ट्रीय समसामयिक घटनाएं (2025-26)"},{"type":"p","text":"अंतर्राष्ट्रीय घटनाक्रम अब केवल द्विपक्षीय संबंधों तक सीमित नहीं हैं; ये वैश्विक आर्थिक और सुरक्षा ढांचे को नया आकार दे रहे हैं। 2025-26 में भारत का ''ग्लोबल साउथ'' (Global South) के नेता के रूप में उदय और महत्वपूर्ण समूहों (G20, BRICS) में विस्तार प्रमुख बिंदु रहे हैं। MPPSC में अक्सर सम्मेलनों के स्थान, नए सदस्य देशों और अंतर्राष्ट्रीय सूचकांकों में भारत की रैंकिंग पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. प्रमुख अंतर्राष्ट्रीय शिखर सम्मेलन (Major Global Summits)"},{"type":"p","text":"2025-26 के दौरान हुए इन सम्मेलनों ने वैश्विक नीतियों को प्रभावित किया है।"},{"type":"table","instruction":"शिखर सम्मेलन: स्थान एवं मुख्य बिंदु","head":["सम्मेलन (Summit)","मेजबान देश / शहर","मुख्य परिणाम / थीम"],"body":[["G20 शिखर सम्मेलन 2025","दक्षिण अफ्रीका","थीम: ''एक न्यायसंगत और टिकाऊ दुनिया का निर्माण''"],["BRICS शिखर सम्मेलन 2025","ब्राजील","नए 5 सदस्य देशों के पूर्ण एकीकरण पर ध्यान।"],["COP30 (जलवायु सम्मेलन)","बेलेम, ब्राजील","पेरिस समझौते के लक्ष्यों की समीक्षा।"],["SCO शिखर सम्मेलन 2025","चीन (अध्यक्षता)","क्षेत्रीय सुरक्षा और आतंकवाद विरोधी सहयोग।"],["WEF (विश्व आर्थिक मंच)","दावोस, स्विट्जरलैंड","AI गवर्नेंस और वैश्विक अर्थव्यवस्था पर चर्चा।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. महत्वपूर्ण नियुक्तियाँ एवं व्यक्तित्व (Appointments & Personalities)"},{"type":"ul","items":["**संयुक्त राष्ट्र (UN):** महासभा के 80वें सत्र के अध्यक्ष की नियुक्ति (सितंबर 2025)।","**विश्व बैंक / IMF:** प्रमुख नेतृत्व परिवर्तन और कोटे (Quotas) में सुधार की मांग।","**नवनिर्वाचित राष्ट्राध्यक्ष:** हाल ही में संपन्न हुए वैश्विक चुनावों (जैसे- जर्मनी, कनाडा) के विजेता।","**भारतीय मूल के नेता:** दुनिया के विभिन्न देशों में नेतृत्व कर रहे भारतीय मूल के व्यक्ति।"]},{"type":"h2","text":"3. सूचकांक एवं रिपोर्ट (Indices & Reports 2025-26)"},{"type":"table","instruction":"वैश्विक सूचकांक: भारत की स्थिति","head":["सूचकांक (Index)","प्रथम स्थान (Top Rank)","भारत की रैंक (लगभग)"],"body":[["विश्व प्रसन्नता रिपोर्ट 2025","फिनलैंड","120-125 के बीच (सुधार जारी)"],["प्रेस स्वतंत्रता सूचकांक 2025","नॉर्वे","160 के करीब"],["ग्लोबल इनोवेशन इंडेक्स","स्विट्जरलैंड","शीर्ष 40 में (MP का योगदान महत्वपूर्ण)"],["हेनले पासपोर्ट इंडेक्स 2026","सिंगापुर / जापान","80-85 के बीच"]]},{"type":"fact_card","title":"अंतर्राष्ट्रीय ''प्रथम'': क्विक अपडेट्स","facts":["नाटो (NATO): 32वें सदस्य के रूप में स्वीडन का पूर्ण एकीकरण।","डिजिटल रुपया: अंतर्राष्ट्रीय व्यापार (Cross-border payments) के लिए भारत का अन्य देशों से समझौता।","चंद्र मिशन: NASA का आर्टेमिस III मिशन (Artemis III) - चंद्रमा पर पहली महिला को उतारने की तैयारी।","शांति वार्ता: मध्य पूर्व (Middle East) और यूक्रेन संकट के समाधान हेतु भारत की मध्यस्थता भूमिका।"],"icon":"🌍"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"G20 शिखर सम्मेलन 2023 की मेजबानी किस देश ने की थी?","options":["इंडोनेशिया","भारत","ब्राजील","इटली"],"correct":"भारत","strategy":"यह नई दिल्ली में आयोजित हुआ था। 2025 के लिए दक्षिण अफ्रीका याद रखें।"},{"type":"pyq","exam":"UPSC Prelims 2024","year":2024,"question":"ब्रिक्स (BRICS) में शामिल होने वाले नए देशों के समूह की पहचान करें?","options":["मिस्र, इथियोपिया, ईरान, UAE","अर्जेंटीना, तुर्की, सऊदी अरब","मेक्सिको, नाइजीरिया, वियतनाम","कतर, ओमान, कुवैत"],"correct":"मिस्र, इथियोपिया, ईरान, UAE (सहित सऊदी अरब)","strategy":"ब्रिक्स का विस्तार एक बहुत ही हॉट टॉपिक है, इसे ध्यान से पढ़ें।"},{"type":"pyq","exam":"BPSC Prelims 2023","year":2023,"question":"संयुक्त राष्ट्र महासभा के 78वें सत्र के अध्यक्ष कौन थे?","options":["डेनिस फ्रांसिस","अब्दुल्ला शाहिद","वोल्कन बोज़किर","तिजानी मोहम्मद-बांडे"],"correct":"डेनिस फ्रांसिस","strategy":"अध्यक्ष का नाम और उनका देश अक्सर राज्य आयोग पूछते हैं।"},{"type":"pyq","exam":"UPPSC Prelims 2022","year":2022,"question":"विश्व प्रेस स्वतंत्रता सूचकांक किसके द्वारा जारी किया जाता है?","options":["एमनेस्टी इंटरनेशनल","रिपोर्टर्स विदाउट बॉर्डर्स","यूनेस्को","वर्ल्ड इकोनॉमिक फोरम"],"correct":"रिपोर्टर्स विदाउट बॉर्डर्स","strategy":"संस्था का नाम सूचकांक के साथ याद रखना अनिवार्य है।"},{"type":"exam_pattern","topic":"International Affairs Trend","analysis":"Competitive Exams Trend:","stats":["समिट और वेन्यू (Venues): 2-3 प्रश्न","सूचकांक और भारत की रैंक: 1-2 प्रश्न","नए सदस्य / अंतर्राष्ट्रीय संगठन: 1 प्रश्न"],"trend":"आयोग अब केवल समिट का नाम नहीं, बल्कि उन सम्मेलनों में अपनाए गए ''घोषणापत्रों'' (Declarations) के नाम पर अधिक प्रश्न पूछ रहे हैं।"}],"en":[{"type":"h2","text":"Unit 8: International Current Events (2025-26)"},{"type":"p","text":"International developments are no longer limited to bilateral ties; they are reshaping global economic and security frameworks. In 2025-26, India''s rise as a leader of the ''Global South'' and the expansion of key blocs like G20 and BRICS remain central. MPPSC frequently asks about summit venues, new member nations, and India''s rank in international indices."},{"type":"h2","text":"1. Major Global Summits"},{"type":"table","instruction":"Summits: Venues and Key Highlights","head":["Summit","Host Country / City","Key Outcome / Theme"],"body":[["G20 Summit 2025","South Africa","Theme: ''Building a Just World and a Sustainable Planet''"],["BRICS Summit 2025","Brazil","Focus on full integration of 5 new member states."],["COP30 (Climate)","Belém, Brazil","Stocktake of Paris Agreement goals."],["SCO Summit 2025","China (Presidency)","Regional security and counter-terrorism cooperation."],["WEF (Davos)","Davos, Switzerland","Focus on AI Governance and the Global Economy."]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. Important Appointments & Indices"},{"type":"table","instruction":"Global Indices: India''s Position","head":["Index","Top Rank","India''s Rank (Approx)"],"body":[["World Happiness Report 2025","Finland","Between 120-125"],["Press Freedom Index 2025","Norway","Around 160"],["Global Innovation Index","Switzerland","In Top 40"],["Henley Passport Index 2026","Singapore / Japan","Between 80-85"]]},{"type":"fact_card","title":"International ''Firsts'': Quick Updates","facts":["NATO: Full integration of Sweden as the 32nd member.","Digital Rupee: MoUs with multiple countries for cross-border trade payments.","Lunar Missions: NASA’s Artemis III mission preparations for landing the first woman on the Moon.","Peace Diplomacy: India''s mediating role in Middle East and Ukraine crisis resolutions."],"icon":"🌍"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Which country hosted the G20 Summit in 2023?","options":["Indonesia","India","Brazil","Italy"],"correct":"India","strategy":"It was held in New Delhi. For 2025, remember South Africa."},{"type":"exam_pattern","topic":"International Affairs Trend","analysis":"Competitive Exams Trend:","stats":["Summits & Venues: 2-3 questions","Indices & India''s Rank: 1-2 questions","International Organizations: 1 question"],"trend":"Commissions are now focusing on the specific ''Declarations'' adopted during summits rather than just the venues."}]}', 'current_affairs', NULL, 40, 1, 1770921540, 1771008910, 'blog', 'unit_8', 'International Current Events', 1, 0, 1, 1, 0, 'Unit 8: अंतर्राष्ट्रीय समसामयिक घटनाएं (2025-26) अंतर्राष्ट्रीय घटनाक्रम अब केवल द्विपक्षीय संबंधों तक सीमित नहीं हैं; ये वैश्विक आर्थिक और सुरक्षा ढांचे को नया आकार दे रहे हैं। 2025-26 में भारत का ''ग...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('6cee25bf-510b-4a2b-a4d0-64b85fa061e0', 'national-current-events-unit-8-mppsc', 'National Current Events 2025-26 | राष्ट्रीय समसामयिक घटनाएं', 'Comprehensive guide to India''s major national events from late 2025 to February 2026. Covers Union Budget 2026-27, Padma Awards, 16th Finance Commission, and major summits for MPPSC Unit 8.', '{"hi":[{"type":"h2","text":"Unit 8: राष्ट्रीय समसामयिक घटनाएं (फरवरी 2026 तक अपडेटेड)"},{"type":"p","text":"भारत वर्तमान में ''विकसित भारत @ 2047'' के विजन पर काम कर रहा है। फरवरी 2026 तक के घटनाक्रमों में 16वें वित्त आयोग की सिफारिशें, केंद्रीय बजट 2026-27 और भारत की बढ़ती रक्षा एवं तकनीकी क्षमताएं प्रमुख रही हैं। MPPSC में अक्सर नियुक्तियों, पुरस्कारों और खेल आयोजनों (जैसे नेशनल गेम्स) पर सीधे प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. संवैधानिक एवं प्रशासनिक घटनाक्रम (Polity & Admin)"},{"type":"table","instruction":"प्रमुख नियुक्तियाँ एवं आयोग (2025-26)","head":["पद / आयोग","व्यक्तित्व / विवरण","मुख्य तथ्य"],"body":[["16वां वित्त आयोग","अरविंद पनगढ़िया (अध्यक्ष)","राज्यों का हिस्सा 41% बरकरार रखने की सिफारिश।"],["भारत के मुख्य न्यायाधीश","न्यायमूर्ति (वर्तमान पदासीन)","न्यायपालिका में डिजिटलीकरण पर जोर।"],["मुख्य चुनाव आयुक्त","राष्ट्रीय मतदाता दिवस (25 जनवरी 2026) पर नई पहल।","ECI द्वारा SEC का राष्ट्रीय सम्मेलन (24 Feb 2026)।"],["नीति आयोग","CEO और उपाध्यक्ष","SDG इंडिया इंडेक्स 2025-26 जारी।"]]},{"type":"h2","text":"2. पुरस्कार एवं सम्मान 2026 (Awards & Honours)"},{"type":"p","text":"गणतंत्र दिवस 2026 के अवसर पर घोषित पद्म पुरस्कारों में कला, समाज सेवा और खेल के दिग्गजों को सम्मानित किया गया।"},{"type":"table","instruction":"पद्म विभूषण 2026 के विजेता","head":["नाम","क्षेत्र","राज्य"],"body":[["श्री धर्मेंद्र सिंह देओल","कला (मरणोपरांत)","महाराष्ट्र"],["श्री के. टी. थॉमस","लोक सेवा","केरल"],["सुश्री एन. राजम","कला","उत्तर प्रदेश"],["श्री पी. नारायणन","साहित्य एवं शिक्षा","केरल"],["श्री वी. एस. अच्युतानंदन","लोक सेवा (मरणोपरांत)","केरल"]]},{"type":"highlight","level":"important","text":"खेल जगत: रोहित शर्मा और हरमनप्रीत कौर (क्रिकेट) को पद्म श्री 2026 से सम्मानित किया गया। म.प्र. के भगवानादास रायकवार (खेल) को भी पद्म श्री मिला।","icon":"🏅"},{"type":"h2","text":"3. प्रमुख शिखर सम्मेलन एवं आयोजन (Summits 2026)"},{"type":"ul","items":["**इंडिया AI इम्पैक्ट समिट 2026:** दिल्ली में आयोजित (फरवरी 2026), जिसमें ब्राजील के राष्ट्रपति लूला डी सिल्वा ने भाग लिया।","**BIOFACH 2026:** भारत को जर्मनी में ''कंट्री ऑफ द ईयर'' चुना गया (ऑर्गेनिक खेती हेतु)।","**इंटरनेशनल फ्लीट रिव्यू (IFR) 2026:** विशाखापत्तनम में नौसेना का भव्य प्रदर्शन (18 फरवरी 2026)।","**ग्लोबल बिग कैट्स समिट:** भारत 2026 में दुनिया के पहले बिग कैट्स समिट की मेजबानी कर रहा है।"]},{"type":"h2","text":"4. खेल समाचार (Sports Updates)"},{"type":"fact_card","title":"38वें राष्ट्रीय खेल (National Games 2025-26)","facts":["मेजबान: उत्तराखंड (देहरादून, हरिद्वार आदि)।","विजेता (Medal Tally): ''सर्विसेज'' (Services) प्रथम स्थान पर रही।","म.प्र. की स्थिति: मध्य प्रदेश चौथे स्थान पर (34 स्वर्ण पदकों के साथ) रहा।","मस्कट (Mascot): ''मौली'' (हिमालयन मोनल पक्षी)।"],"icon":"🏟️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"15वें वित्त आयोग के अध्यक्ष कौन हैं?","options":["एन.के. सिंह","के.सी. पंत","सी. रंगराजन","वाई.वी. रेड्डी"],"correct":"एन.के. सिंह","strategy":"वर्तमान में 16वें आयोग के लिए ''अरविंद पनगढ़िया'' का नाम याद रखें।"},{"type":"pyq","exam":"UPSC Prelims 2024","year":2024,"question":"हाल ही में समाचारों में रहा ''आदित्य-L1'' मिशन किससे संबंधित है?","options":["चंद्रमा अन्वेषण","सूर्य का अध्ययन","शुक्र मिशन","क्षुद्रग्रह बेल्ट"],"correct":"सूर्य का अध्ययन","strategy":"यह भारत का पहला सौर मिशन है जिसे L1 पॉइंट पर स्थापित किया गया है।"},{"type":"pyq","exam":"BPSC Prelims 2023","year":2023,"question":"37वें राष्ट्रीय खेलों का आयोजन कहाँ किया गया था?","options":["गुजरात","गोवा","उत्तराखंड","केरल"],"correct":"गोवा","strategy":"37वें गोवा में, 38वें उत्तराखंड में और 39वें मेघालय में प्रस्तावित हैं।"},{"type":"exam_pattern","topic":"National Affairs Trend","analysis":"Competitive Exams Trend:","stats":["पुरस्कार एवं सम्मान (Padma/Khel Ratna): 2-3 प्रश्न","प्रमुख नियुक्तियाँ: 1-2 प्रश्न","बजट एवं आर्थिक डेटा: 1-2 प्रश्न"],"trend":"आयोग अब केवल ''नाम'' नहीं, बल्कि ''वित्त आयोग की सिफारिशों'' के प्रतिशत और ''बजट की प्रमुख योजनाओं'' के आवंटन पर अधिक गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 8: National Current Events (Updated Feb 2026)"},{"type":"p","text":"India is steering towards the ''Viksit Bharat @ 2047'' vision. Key developments as of February 2026 include the recommendations of the 16th Finance Commission, Union Budget 2026-27, and India''s growing defense and tech prowess."},{"type":"h2","text":"1. Governance & Appointments"},{"type":"table","instruction":"Major Appointments 2025-26","head":["Position / Commission","Personality","Key Fact"],"body":[["16th Finance Commission","Arvind Panagariya (Chairman)","Retained 41% tax devolution to states."],["Chief Election Commissioner","ECI National SEC Conference (24 Feb 2026).","Focus on ''Inclusive Elections''."],["NITI Aayog","CEO & Vice-Chairman","Released SDG India Index 2025-26."]]},{"type":"h2","text":"2. Padma Awards 2026"},{"type":"table","instruction":"Padma Vibhushan 2026 Winners","head":["Name","Field","State"],"body":[["Shri Dharmendra Singh Deol","Art (Posthumous)","Maharashtra"],["Shri K T Thomas","Public Affairs","Kerala"],["Ms. N Rajam","Art","Uttar Pradesh"],["Shri P Narayanan","Lit & Education","Kerala"],["Shri V S Achuthanandan","Public Affairs (Posthumous)","Kerala"]]},{"type":"fact_card","title":"38th National Games (Uttarakhand)","facts":["Champion: ''Services'' topped the medal tally.","MP Status: Madhya Pradesh secured 4th rank with 34 Gold medals.","Mascot: ''Mauli'' (Himalayan Monal).","Torch: Named ''Tejaswini''."],"icon":"🏟️"},{"type":"exam_pattern","topic":"National Affairs Trend","analysis":"Competitive Exams Trend:","stats":["Awards & Honours: 2-3 questions","Major Appointments: 1-2 questions","Budget & Policy data: 1-2 questions"],"trend":"Questions are shifting from simple names to exact percentages in ''Finance Commission'' and allocations in ''Budget Schemes''."}]}', 'current_affairs', NULL, 45, 1, 1770921573, 1770921573, 'blog', 'unit_8', 'National Current Events', 1, 0, 0, 1, 0, 'Unit 8: राष्ट्रीय समसामयिक घटनाएं (फरवरी 2026 तक अपडेटेड) भारत वर्तमान में ''विकसित भारत @ 2047'' के विजन पर काम कर रहा है। फरवरी 2026 तक के घटनाक्रमों में 16वें वित्त आयोग की सिफारिशें, केंद्रीय बजट 20...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('fa28afd6-43a3-4fe2-bf45-e3634ec77fd1', 'mp-current-affairs-unit-8-mppsc-2026', 'Current Events of Madhya Pradesh 2025-26 | मध्य प्रदेश समसामयिकी', 'Exhaustive coverage of MP''s current affairs from late 2025 to February 2026. Includes MP Budget 2025-26, 38th National Games, GI Tags, and major state policies for MPPSC Unit 8.', '{"hi":[{"type":"h2","text":"Unit 8: मध्य प्रदेश समसामयिकी (2025-26)"},{"type":"p","text":"मध्य प्रदेश ने 2026 को ''कृषि और किसान कल्याण वर्ष'' के रूप में घोषित किया है। 2025-26 के दौरान राज्य ने औद्योगिक नीति, निर्यात संवर्धन और खेलों में अभूतपूर्व प्रगति की है। MPPSC में अक्सर राज्य सरकार की योजनाओं के बजट आवंटन, खेल पुरस्कारों (विक्रम, एकलव्य) और हाल ही में मिले GI टैग पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. आर्थिक एवं बजटीय घटनाक्रम (MP Budget 2025-26)"},{"type":"p","text":"म.प्र. सरकार ने वित्त वर्ष 2025-26 के लिए ₹3.75 लाख करोड़ से अधिक का अनुमानित व्यय पेश किया है।"},{"type":"table","instruction":"बजट 2025-26: प्रमुख आवंटन एवं लक्ष्य","head":["योजना / क्षेत्र","आवंटन / लक्ष्य","मुख्य तथ्य"],"body":[["लाड़ली बहना योजना","₹18,669 करोड़","राजस्व प्राप्तियों का लगभग 6.4% हिस्सा।"],["कृषि एवं किसान कल्याण","₹27,000 करोड़","2026 को ''कृषि वर्ष'' घोषित किया गया।"],["मुख्यमंत्री कृषक उन्नति योजना","₹850 करोड़","फसल विविधीकरण (Crop Diversification) हेतु।"],["GSDP वृद्धि लक्ष्य","13% वृद्धि","कुल GSDP ~₹16.94 लाख करोड़ (प्रचलित भावों पर)।"]]},{"type":"h2","text":"2. कला, संस्कृति एवं GI टैग (Art & Culture)"},{"type":"ul","items":["**ग्वालियर हस्तशिल्प:** ग्वालियर के ''पैपियर माशे'' (Papier Mache) हस्तशिल्प को हाल ही में GI टैग प्रदान किया गया है।","**अहिल्याबाई होल्कर झाँकी:** गणतंत्र दिवस 2026 में म.प्र. की झाँकी ''देवी अहिल्याबाई होल्कर'' के जीवन और उनके सुशासन पर आधारित थी।","**सीतामऊ साहित्य महोत्सव:** मंदसौर जिले के सीतामऊ में भव्य साहित्य उत्सव का आयोजन (फरवरी 2026)।","**पन्ना आँवला:** ''एक जिला एक उत्पाद'' (ODOP) के तहत पन्ना के आँवला को वैश्विक पहचान मिली।"]},{"type":"image_tag","content":""},{"type":"h2","text":"3. खेल एवं पुरस्कार (Sports & Awards)"},{"type":"fact_card","title":"म.प्र. की खेल उपलब्धियां: 2025-26","facts":["38वें राष्ट्रीय खेल (National Games): म.प्र. ने कुल 82 पदकों (33 स्वर्ण) के साथ राज्यों की सूची में तीसरा स्थान प्राप्त किया।","स्पोर्टस्टार एसेस अवार्ड 2025: मध्य प्रदेश को ''खेलों को बढ़ावा देने वाला सर्वश्रेष्ठ राज्य'' चुना गया।","दुर्गा ड्रोन स्क्वाड्रन: ग्वालियर में BSF की पहली पूर्ण महिला ड्रोन यूनिट स्थापित की गई।","एकलव्य बाथम: मलेशिया में 21वीं लैंगकावी इंटरनेशनल रेगाटा (Sailing) में स्वर्ण पदक जीता।"],"icon":"🏆"},{"type":"h2","text":"4. नई नीतियां एवं नवाचार (New Policies)"},{"type":"table","instruction":"म.प्र. की नई नीतियां 2025-26","head":["नीति (Policy)","वर्ष","मुख्य उद्देश्य"],"body":[["निर्यात संवर्धन नीति","2025","म.प्र. के निर्यात को $10 बिलियन तक ले जाना।"],["लॉजिस्टिक्स नीति","2025","म.प्र. को भारत का ''लॉजिस्टिक्स हब'' बनाना।"],["फिल्म पर्यटन नीति","2025","राज्य को फिल्म शूटिंग हेतु सर्वश्रेष्ठ गंतव्य बनाना।"],["MSME विकास नीति","2025","वैल्यू चेन को मजबूत करना और क्लस्टर विकास।"]]},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश का पन्ना जिला किसके उत्पादन के लिए प्रसिद्ध है?","options":["हीरा","तांबा","मैंगनीज","अभ्रक"],"correct":"हीरा","strategy":"अब इसे ODOP के तहत ''आँवला'' के लिए भी याद रखें।"},{"type":"pyq","exam":"MPPSC Prelims 2020","year":2020,"question":"मुख्यमंत्री लाड़ली लक्ष्मी योजना किस वर्ष शुरू की गई थी?","options":["2005","2007","2010","2012"],"correct":"2007","strategy":"यह म.प्र. की सबसे सफल योजनाओं में से है। अब ''लाड़ली बहना'' (2023) पर ध्यान दें।"},{"type":"exam_pattern","topic":"MP Current Affairs Trend","analysis":"Competitive Exams Trend:","stats":["प्रमुख योजनाएं और बजट: 3-4 प्रश्न","खेल और खिलाड़ी: 2 प्रश्न","GI टैग और महोत्सव: 1-2 प्रश्न"],"trend":"आयोग अब बजट की राशि के ''सटीक आंकड़ों'' (जैसे ₹18,669 करोड़) और ''एक जिला एक उत्पाद'' की मैचिंग पर अधिक फोकस कर रहा है।"}],"en":[{"type":"h2","text":"Unit 8: Madhya Pradesh Current Events (2025-26)"},{"type":"p","text":"Madhya Pradesh has declared 2026 as the ''Year of Agriculture and Farmers Welfare''. During 2025-26, the state made significant progress in industrial policy and sports. In MPPSC, questions are often asked about budget allocations for schemes, sports awards, and recent GI tags."},{"type":"h2","text":"1. MP Budget 2025-26 Highlights"},{"type":"table","instruction":"Budget 2025-26: Key Allocations","head":["Scheme / Sector","Allocation / Target","Key Fact"],"body":[["Ladli Behna Yojana","₹18,669 Crore","Approx 6.4% of revenue receipts."],["Agriculture Year 2026","₹27,000 Crore","Declared as ''Year of Agriculture''."],["Krishak Unnati Yojana","₹850 Crore","Focus on Crop Diversification."],["GSDP Growth","13% Target","Total GSDP projected at ₹16.94 Lakh Crore."]]},{"type":"h2","text":"2. Sports & Achievements"},{"type":"fact_card","title":"MP Sports Excellence 2025-26","facts":["38th National Games: MP finished 3rd among states with 82 medals (33 Gold).","Sportstar Aces Award 2025: MP honored as the ''Best State for Promoting Sports''.","Durga Drone Squadron: First all-women drone unit of BSF established in Gwalior.","Eklavya Batham: Won Gold at the International Regatta in Malaysia."],"icon":"🏆"},{"type":"exam_pattern","topic":"MP Current Affairs Trend","analysis":"Competitive Exams Trend:","stats":["Schemes & Budget: 3-4 questions","Sports & Personalities: 2 questions","GI Tags & Events: 1-2 questions"],"trend":"Commissions are focusing on ''exact figures'' in the budget and matching of ''One District One Product'' targets."}]}', 'current_affairs', NULL, 45, 1, 1770921625, 1770921625, 'blog', 'unit_8', 'Current Events of Madhya Pradesh', 1, 0, 0, 1, 0, 'Unit 8: मध्य प्रदेश समसामयिकी (2025-26) मध्य प्रदेश ने 2026 को ''कृषि और किसान कल्याण वर्ष'' के रूप में घोषित किया है। 2025-26 के दौरान राज्य ने औद्योगिक नीति, निर्यात संवर्धन और खेलों में अभूतपूर्व प्र...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('3be8a330-659b-46e1-b898-43bfee5f1717', 'basic-knowledge-of-computer-unit-9-mppsc', 'Basic Knowledge of Computer | कंप्यूटर का आधारभूत ज्ञान', 'Comprehensive guide to computer fundamentals including architecture, generations, and components for MPPSC Unit 9. Featuring high-yield PYQs from UPSC and State PSCs.', '{"hi":[{"type":"h2","text":"Unit 9: कंप्यूटर का आधारभूत ज्ञान (Computer Fundamentals)"},{"type":"p","text":"सूचना और संचार प्रौद्योगिकी (ICT) की नींव कंप्यूटर की कार्यप्रणाली पर टिकी है। कंप्यूटर एक इलेक्ट्रॉनिक मशीन है जो डेटा को इनपुट के रूप में लेती है, उसे प्रोसेस करती है और अर्थपूर्ण जानकारी आउटपुट के रूप में प्रदान करती है। MPPSC में अक्सर हार्डवेयर-सॉफ्टवेयर के अंतर, मेमोरी यूनिट्स और कंप्यूटर की पीढ़ियों (Generations) पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. कंप्यूटर की पीढ़ियां (Generations of Computer)"},{"type":"p","text":"तकनीकी विकास के आधार पर कंप्यूटर को पाँच पीढ़ियों में बांटा गया है।"},{"type":"table","instruction":"कंप्यूटर पीढ़ियां और मुख्य तकनीक","head":["पीढ़ी","मुख्य घटक (Component)","उदाहरण"],"body":[["प्रथम (1940-56)","वैक्यूम ट्यूब (Vacuum Tubes)","ENIAC, UNIVAC"],["द्वितीय (1956-63)","ट्रांजिस्टर (Transistors)","IBM 1401"],["तृतीय (1964-71)","इंटीग्रेटेड सर्किट (IC Chips)","IBM 360"],["चतुर्थ (1971-वर्तमान)","माइक्रोप्रोसेसर (VLSI)","Apple II, PC"],["पंचम (भविष्य)","आर्टिफिशियल इंटेलिजेंस (ULSI)","Robotics, Quantum Comp."]]},{"type":"h2","text":"2. हार्डवेयर: इनपुट और आउटपुट डिवाइस"},{"type":"image_tag","content":""},{"type":"ul","items":["**इनपुट डिवाइस:** कीबोर्ड, माउस, स्कैनर, OMR, OCR, MICR, जॉयस्टिक।","**आउटपुट डिवाइस:** मॉनिटर (VDU), प्रिंटर (इम्पैक्ट और नॉन-इम्पैक्ट), प्लॉटर, स्पीकर।","**प्रोसेसिंग:** CPU (सेंट्रल प्रोसेसिंग यूनिट) - इसे ''कंप्यूटर का मस्तिष्क'' कहा जाता है। इसके तीन भाग हैं: ALU, CU और Memory Unit।"]},{"type":"h2","text":"3. कंप्यूटर मेमोरी (Computer Memory)"},{"type":"p","text":"मेमोरी डेटा को स्टोर करने का स्थान है। इसकी माप बिट (Bit) और बाइट (Byte) में की जाती है।"},{"type":"table","instruction":"मेमोरी के प्रकार","head":["प्रकार","विवरण","उदाहरण"],"body":[["प्राइमरी (Main)","अस्थायी (Volatile) और तेज।","RAM, ROM, Cache"],["सेकेंडरी (Auxiliary)","स्थायी (Non-volatile) भंडारण।","Hard Disk, SSD, Pen Drive"]]},{"type":"highlight","level":"important","text":"मेमोरी यूनिट क्रम: 1 Byte = 8 Bits | 1 KB = 1024 Bytes | 1 MB = 1024 KB | 1 GB = 1024 MB | 1 TB = 1024 GB।","icon":"💾"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"कंप्यूटर की किस पीढ़ी में ''माइक्रोप्रोसेसर'' का प्रयोग शुरू हुआ था?","options":["प्रथम","द्वितीय","तृतीय","चतुर्थ"],"correct":"चतुर्थ","strategy":"चतुर्थ पीढ़ी (1971 से) में VLSI तकनीक और माइक्रोप्रोसेसर आए।"},{"type":"pyq","exam":"UPSC Prelims 2017","year":2017,"question":"कंप्यूटर की स्मृति (Memory) के मापन की सबसे बड़ी इकाई कौन सी है?","options":["टेराबाइट (TB)","गीगाबाइट (GB)","योटाबाइट (YB)","पेटाबाइट (PB)"],"correct":"योटाबाइट (YB)","strategy":"दिए गए विकल्पों में YB (10^24) सबसे बड़ी है। क्रम: TB < PB < EB < ZB < YB।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"कौन सा एक इनपुट डिवाइस नहीं है?","options":["माउस","कीबोर्ड","स्कैनर","प्रिंटर"],"correct":"प्रिंटर","strategy":"प्रिंटर एक आउटपुट डिवाइस है क्योंकि यह हार्ड कॉपी प्रदान करता है।"},{"type":"pyq","exam":"UPPSC Prelims 2018","year":2018,"question":"IC चिप्स का निर्माण किस पदार्थ से किया जाता है?","options":["कॉपर","सिलिकॉन","आयरन","सिल्वर"],"correct":"सिलिकॉन","strategy":"सिलिकॉन एक सेमीकंडक्टर है जिसका उपयोग इंटीग्रेटेड सर्किट्स में होता है।"},{"type":"exam_pattern","topic":"Computer Fundamentals Trend","analysis":"Competitive Exams Trend:","stats":["हार्डवेयर/इनपुट-आउटपुट: 2 प्रश्न","मेमोरी कन्वर्जन (KB/MB/GB): 1 प्रश्न","पीढ़ियाँ और तकनीक: 1 प्रश्न"],"trend":"आयोग अब ''हार्डवेयर'' के साथ-साथ ''क्लाउड स्टोरेज'' और ''SSD (Solid State Drive)'' की कार्यप्रणाली पर अधिक गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 9: Basic Knowledge of Computer"},{"type":"p","text":"Information and Communication Technology (ICT) is built on the foundation of computer operations. A computer is an electronic machine that processes data to provide meaningful information. In MPPSC, questions frequently target hardware-software differences, memory units, and computer generations."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Computer Generations"},{"type":"table","instruction":"Computer Generations and Key Tech","head":["Generation","Main Component","Examples"],"body":[["1st (1940-56)","Vacuum Tubes","ENIAC, UNIVAC"],["2nd (1956-63)","Transistors","IBM 1401"],["3rd (1964-71)","IC Chips","IBM 360"],["4th (1971-Present)","Microprocessors (VLSI)","Apple II, Modern PCs"],["5th (Future)","AI (ULSI)","Robotics, Quantum Computing"]]},{"type":"h2","text":"2. Hardware and Memory"},{"type":"ul","items":["**Input Devices:** Keyboard, Mouse, Scanner, MICR, OMR.","**Output Devices:** VDU (Monitor), Printer, Plotter, Speaker.","**CPU Components:** ALU (Arithmetic Logic Unit), CU (Control Unit), and Registers."]},{"type":"fact_card","title":"Memory Units Hierarchy","facts":["1 Byte = 8 Bits","1 Kilobyte (KB) = 1024 Bytes","1 Megabyte (MB) = 1024 KB","1 Gigabyte (GB) = 1024 MB","1 Terabyte (TB) = 1024 GB"],"icon":"💾"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"In which computer generation were microprocessors introduced?","options":["1st","2nd","3rd","4th"],"correct":"4th","strategy":"Microprocessors using VLSI technology were introduced in the 4th generation."},{"type":"exam_pattern","topic":"Computer Fundamentals Trend","analysis":"Competitive Exams Trend:","stats":["Hardware/Input-Output: 2 questions","Memory Conversion: 1 question","Generations & Tech: 1 question"],"trend":"Commissions are shifting from basic hardware to more complex storage tech like SSDs and Cloud-based storage architecture."}]}', 'ict', NULL, 35, 1, 1770921707, 1771008912, 'blog', 'unit_9', 'Basic Knowledge of Computer', 1, 0, 1, 1, 0, 'Unit 9: कंप्यूटर का आधारभूत ज्ञान (Computer Fundamentals) सूचना और संचार प्रौद्योगिकी (ICT) की नींव कंप्यूटर की कार्यप्रणाली पर टिकी है। कंप्यूटर एक इलेक्ट्रॉनिक मशीन है जो डेटा को इनपुट के रूप में ले...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('70f53569-0ee6-4042-82a7-403431c8f85b', 'electronics-ict-unit-9-mppsc-2026', 'Electronics, Information & Communication Technology | इलेक्ट्रॉनिक्स, सूचना एवं संचार प्रौद्योगिकी', 'Exhaustive guide to Electronics and ICT for MPPSC Unit 9. Covers semiconductor basics, Indian electronics history, 5G/6G trends, and high-yield PYQs from multiple PSCs.', '{"hi":[{"type":"h2","text":"Unit 9: इलेक्ट्रॉनिक्स, सूचना एवं संचार प्रौद्योगिकी (Electronics & ICT)"},{"type":"p","text":"इलेक्ट्रॉनिक्स आधुनिक तकनीक की आत्मा है। इसमें अर्धचालकों (Semiconductors) का उपयोग करके इलेक्ट्रॉनों के प्रवाह को नियंत्रित किया जाता है। वहीं, सूचना और संचार प्रौद्योगिकी (ICT) डेटा के प्रसारण और भंडारण का विज्ञान है। MPPSC में अक्सर भारत के इलेक्ट्रॉनिक्स विकास, संचार की पीढ़ियों (G-Levels) और प्रमुख तकनीकी शब्दावली पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. इलेक्ट्रॉनिक्स के आधारभूत घटक (Basics of Electronics)"},{"type":"p","text":"इलेक्ट्रॉनिक्स की शुरुआत वैक्यूम ट्यूब से हुई, लेकिन आज यह ''नैनो-चिप्स'' तक पहुँच चुकी है।"},{"type":"table","instruction":"इलेक्ट्रॉनिक्स: प्रमुख घटक एवं कार्य","head":["घटक (Component)","कार्य (Function)","तथ्य (Fact)"],"body":[["अर्धचालक (Semiconductor)","विद्युत चालकता का नियंत्रण।","सिलिकॉन (Si) और जर्मेनियम (Ge) मुख्य उदाहरण।"],["डायोड (Diode)","धारा को केवल एक दिशा में बहने देना।","AC को DC में बदलने (Rectification) हेतु उपयोग।"],["ट्रांजिस्टर (Transistor)","सिग्नल को एम्प्लीफाई (बढ़ाना) या स्विच करना।","शॉकले, बार्डिन और ब्रेटन द्वारा आविष्कार (1947)।"],["IC (इंटीग्रेटेड सर्किट)","लाखों ट्रांजिस्टर एक छोटी चिप पर।","जैक किल्बी और रॉबर्ट नॉयस द्वारा विकसित।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. सूचना एवं संचार प्रौद्योगिकी (ICT Trends 2026)"},{"type":"p","text":"संचार प्रौद्योगिकी ने ''एनालॉग'' से ''डिजिटल'' तक का सफर तय किया है।"},{"type":"ul","items":["**संचार के प्रकार:** सिम्पलेक्स (TV), हाफ-डुप्लेक्स (वॉकी-टॉकी), और फुल-डुप्लेक्स (मोबाइल फोन)।","**5G/6G तकनीक:** भारत में 5G का रोलआउट पूरा हो चुका है और ''भारत 6G मिशन'' के तहत 2030 तक 6G लॉन्च करने का लक्ष्य है।","**स्पेक्ट्रम:** उच्च आवृत्ति (Frequency) और कम लेटेंसी (Latency) 5G की मुख्य विशेषता है।","**Li-Fi:** प्रकाश (Light) के माध्यम से डेटा प्रसारण की तकनीक (WiFi से तेज)।"]},{"type":"h2","text":"3. भारत में इलेक्ट्रॉनिक्स का विकास (Electronics in India)"},{"type":"fact_card","title":"भारत का इलेक्ट्रॉनिक्स विजन","facts":["इलेक्ट्रॉनिक्स विभाग (DoE): स्थापना 1970 में।","सेमीकंडक्टर मिशन (ISM): ₹76,000 करोड़ के परिव्यय के साथ भारत को ग्लोबल चिप हब बनाने का लक्ष्य।","BHEL और ITI: भारत में इलेक्ट्रॉनिक्स और दूरसंचार के क्षेत्र में अग्रणी सार्वजनिक संस्थान।","डिजिटल इंडिया 2.0: AI और इलेक्ट्रॉनिक्स विनिर्माण (Manufacturing) पर विशेष जोर।"],"icon":"🇮🇳"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"जे.एस. किल्बी (J.S. Kilby) का संबंध किसके आविष्कार से है?","options":["कंप्यूटर","इंटीग्रेटेड सर्किट (IC)","माइक्रोप्रोसेसर","ट्रांजिस्टर"],"correct":"इंटीग्रेटेड सर्किट (IC)","strategy":"जैक किल्बी ने 1958 में पहला IC विकसित किया था।"},{"type":"pyq","exam":"UPSC Prelims 2022","year":2022,"question":"''Li-Fi'' (Light Fidelity) के संदर्भ में कौन सा कथन सही है?","options":["यह डेटा ट्रांसमिशन के लिए प्रकाश का उपयोग करता है","यह WiFi से कम गति प्रदान करता है","यह केवल बंद स्थानों में कार्य करता है","A और C दोनों"],"correct":"A और C दोनों","strategy":"Li-Fi प्रकाश तरंगों का उपयोग करता है और इसकी रेंज प्रकाश की पहुँच तक ही सीमित होती है।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"ट्रांजिस्टर (Transistor) का मुख्य कार्य क्या है?","options":["वोल्टेज बढ़ाना","सिग्नल को एम्प्लीफाई करना","केवल स्विचिंग","B और C दोनों"],"correct":"B और C दोनों","strategy":"ट्रांजिस्टर एक एम्पलीफायर और स्विच दोनों के रूप में कार्य करता है।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"भारत में ''राष्ट्रीय इलेक्ट्रॉनिक्स नीति'' (National Policy on Electronics) किस वर्ष घोषित की गई थी?","options":["2011","2012","2019","2021"],"correct":"2019 (नवीनतम)","strategy":"पहली नीति 2012 में आई थी, लेकिन वर्तमान में 2019 की नीति प्रभावी है।"},{"type":"pyq","exam":"TPSC Prelims 2021","year":2021,"question":"मॉडेम (MODEM) का पूर्ण रूप क्या है?","options":["Modulation-Demodulation","Modern Demodulation","Mobile Data Monitor","Mode Demodulator"],"correct":"Modulator-Demodulator","strategy":"यह डिजिटल सिग्नल को एनालॉग और एनालॉग को डिजिटल में बदलता है।"},{"type":"exam_pattern","topic":"Electronics & ICT Trend","analysis":"Competitive Exams Trend:","stats":["तकनीकी शब्दावली (Full Forms/Definitions): 2 प्रश्न","वैज्ञानिक और उनके आविष्कार: 1 प्रश्न","भारत की सरकारी नीतियां और मिशन: 1 प्रश्न"],"trend":"आयोग अब ''सेमीकंडक्टर विनिर्माण'' (Fab units) और ''5G स्पेक्ट्रम बैंड्स'' जैसे करंट-टेक्निकल विषयों पर अधिक गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 9: Electronics, Information and Communication Technology"},{"type":"p","text":"Electronics is the soul of modern technology, involving the control of electron flow using semiconductors. ICT is the science of data transmission and storage. In MPPSC, questions often focus on India''s electronic development, communication generations (G-levels), and key technical terminology."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Fundamental Components of Electronics"},{"type":"table","instruction":"Key Components and Functions","head":["Component","Function","Key Fact"],"body":[["Semiconductor","Control of electrical conductivity.","Silicon (Si) and Germanium (Ge) are primary examples."],["Diode","Allows current to flow in one direction only.","Used for Rectification (AC to DC)."],["Transistor","Amplifies or switches electronic signals.","Invented by Shockley, Bardeen, and Brattain (1947)."],["IC (Integrated Circuit)","Millions of transistors on a tiny chip.","Developed by Jack Kilby and Robert Noyce."]]},{"type":"h2","text":"2. ICT Trends (2026)"},{"type":"ul","items":["**Communication Modes:** Simplex (TV), Half-Duplex (Walkie-talkie), and Full-Duplex (Mobile phones).","**5G/6G Roadmap:** India''s 5G rollout is complete; target is to launch 6G by 2030 under ''Bharat 6G Mission''.","**Li-Fi (Light Fidelity):** High-speed data transmission using light waves instead of radio waves.","**Fiber Optics:** Total Internal Reflection (TIR) based data transmission."]},{"type":"fact_card","title":"Electronics in India","facts":["Department of Electronics (DoE): Established in 1970.","India Semiconductor Mission (ISM): Target to make India a global hub with a ₹76,000 Cr outlay.","Digital India 2.0: Shift towards AI integration and high-tech manufacturing.","PLI Scheme: Incentives for large-scale electronics manufacturing."],"icon":"🇮🇳"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Jack Kilby is associated with the invention of?","options":["Computer","Integrated Circuit (IC)","Microprocessor","Transistor"],"correct":"Integrated Circuit (IC)","strategy":"Kilby developed the first IC in 1958 at Texas Instruments."},{"type":"exam_pattern","topic":"Electronics & ICT Trend","analysis":"Competitive Exams Trend:","stats":["Technical Terminology: 2 questions","Scientists & Inventions: 1 question","Govt Policies & Missions: 1 question"],"trend":"Commissions are shifting focus toward ''Semiconductor Fabrication'' and technical nuances of ''5G Spectrum Bands''."}]}', 'ict', NULL, 40, 1, 1770921773, 1771008913, 'blog', 'unit_9', 'Electronics, Information and Communication Technology', 1, 0, 1, 1, 0, 'Unit 9: इलेक्ट्रॉनिक्स, सूचना एवं संचार प्रौद्योगिकी (Electronics & ICT) इलेक्ट्रॉनिक्स आधुनिक तकनीक की आत्मा है। इसमें अर्धचालकों (Semiconductors) का उपयोग करके इलेक्ट्रॉनों के प्रवाह को नियंत्रित कि...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('8d1c4624-7b12-435f-b2c5-a3875fccf071', 'robotics-ai-cyber-security-unit-9-mppsc', 'Robotics, AI & Cyber Security | रोबोटिक्स, आर्टिफिशियल इंटेलिजेंस और साइबर सुरक्षा', 'Comprehensive guide to Robotics, AI, and Cyber Security for MPPSC Unit 9. Covers components of robots, AI types, cyber threats, and the latest Indian initiatives for 2026.', '{"hi":[{"type":"h2","text":"Unit 9: रोबोटिक्स, आर्टिफिशियल इंटेलिजेंस और साइबर सुरक्षा"},{"type":"p","text":"21वीं सदी की ये तीन तकनीकें हमारे जीने और काम करने के तरीके को बदल रही हैं। ''रोबोटिक्स'' मशीनों के भौतिक व्यवहार को नियंत्रित करता है, ''AI'' उन्हें सोचने की क्षमता देता है, और ''साइबर सुरक्षा'' इस पूरे डिजिटल तंत्र को सुरक्षित रखती है। MPPSC में अक्सर रोबोट के घटकों, AI के जनक और साइबर हमलों के प्रकारों पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. रोबोटिक्स (Robotics)"},{"type":"p","text":"रोबोटिक्स इंजीनियरिंग की वह शाखा है जो रोबोट के डिजाइन, निर्माण और संचालन से संबंधित है। ''रोबोट'' शब्द का सर्वप्रथम प्रयोग **कारेल चापेक** (Karel Čapek) ने अपने नाटक ''R.U.R.'' में किया था।"},{"type":"image_tag","content":""},{"type":"table","instruction":"रोबोट के मुख्य घटक (Components)","head":["घटक (Component)","कार्य (Function)"],"body":[["सेंसर (Sensors)","बाहरी वातावरण से जानकारी प्राप्त करना (आंख/कान की तरह)।"],["एक्चुएटर (Actuators)","रोबोट को गति (Movement) प्रदान करना (मांसपेशियों की तरह)।"],["कंट्रोलर (Controller)","निर्देशों को संसाधित करना (मस्तिष्क की तरह)।"],["एंड-इफेक्टर (End-effector)","विशिष्ट कार्य करना (जैसे पकड़ना या वेल्डिंग करना)।"]]},{"type":"highlight","level":"important","text":"इसहाक असीमोव के रोबोटिक्स के 3 नियम: 1. रोबोट मनुष्य को नुकसान नहीं पहुँचाएगा। 2. रोबोट मनुष्य की आज्ञा मानेगा। 3. रोबोट स्वयं की रक्षा करेगा।","icon":"🤖"},{"type":"h2","text":"2. आर्टिफिशियल इंटेलिजेंस (AI)"},{"type":"p","text":"AI का अर्थ है मशीनों में मानव जैसी बुद्धिमत्ता विकसित करना। **जॉन मैकार्थी** को ''AI का जनक'' कहा जाता है।"},{"type":"image_tag","content":""},{"type":"ul","items":["**मशीन लर्निंग (ML):** डेटा से सीखकर प्रदर्शन में सुधार करना।","**डीप लर्निंग:** मानव मस्तिष्क के न्यूरॉन्स की तरह कार्य करने वाली तकनीक (ANN)।","**व्योममित्र (Vyommitra):** ISRO द्वारा विकसित ''हाफ-ह्यूमनॉइड'' रोबोट जो गगनयान मिशन (2025-26) का हिस्सा है।","**चैटजीपीटी / जेमिनी:** जेनरेटिव AI के उदाहरण जो टेक्स्ट और इमेज बना सकते हैं।"]},{"type":"h2","text":"3. साइबर सुरक्षा (Cyber Security)"},{"type":"p","text":"डिजिटल डेटा, नेटवर्क और डिवाइस को अनधिकृत पहुंच से बचाना साइबर सुरक्षा है।"},{"type":"table","instruction":"प्रमुख साइबर हमले और खतरे","head":["हमला (Attack)","विवरण"],"body":[["फ़िशिंग (Phishing)","धोखाधड़ी वाले ईमेल के जरिए व्यक्तिगत जानकारी चुराना।"],["रैनसमवेयर (Ransomware)","डेटा को लॉक कर देना और बदले में फिरौती (Ransom) मांगना।"],["स्पूफिंग (Spoofing)","अपनी पहचान छिपाकर किसी दूसरे के रूप में सामने आना।"],["DDoS हमला","सर्वर पर इतना ट्रैफिक भेजना कि वह क्रैश हो जाए।"]]},{"type":"fact_card","title":"भारत की साइबर पहल","facts":["CERT-In: भारतीय कंप्यूटर आपातकालीन प्रतिक्रिया टीम (नोडल एजेंसी)।","DPDP एक्ट 2023: डिजिटल व्यक्तिगत डेटा संरक्षण अधिनियम का पूर्ण कार्यान्वयन।","साइबर सुरक्षित भारत: अधिकारियों और नागरिकों को जागरूक करने का अभियान।","I4C: भारतीय साइबर अपराध समन्वय केंद्र।"],"icon":"🛡️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"''आर्टिफिशियल इंटेलिजेंस'' (AI) शब्द का प्रयोग सबसे पहले किसने किया था?","options":["जॉन मैकार्थी","एलन ट्यूरिंग","जेफ्री हिंटन","मार्विन मिन्स्की"],"correct":"जॉन मैकार्थी","strategy":"उन्होंने 1956 के डार्टमाउथ सम्मेलन में यह शब्द दिया था।"},{"type":"pyq","exam":"UPSC Prelims 2023","year":2023,"question":"हाल ही में चर्चा में रहा ''क्विशिट'' (Quishit) क्या है?","options":["एक सुपरकंप्यूटर","एक रैनसमवेयर","एक क्रिप्टो करेंसी","एक मिसाइल प्रणाली"],"correct":"एक रैनसमवेयर","strategy":"साइबर हमलों के नाम UPSC और PSC के फेवरेट होते हैं।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"रोबोट के उस भाग को क्या कहते हैं जो मांसपेशियों की तरह कार्य करता है?","options":["सेंसर","एक्चुएटर","कंट्रोलर","एंड-इफेक्टर"],"correct":"एक्चुएटर (Actuator)","strategy":"एक्चुएटर ही रोबोट के जोड़ों (Joints) को गति देता है।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"विश्व का पहला हिंदी भाषी रोबोट कौन सा है?","options":["सोफिया","रश्मि","इरा","मानव"],"correct":"रश्मि","strategy":"इसे रांची के रंजीत श्रीवास्तव ने विकसित किया है।"},{"type":"pyq","exam":"TPSC Prelims 2021","year":2021,"question":"कौन सा ''मैलवेयर'' कंप्यूटर सिस्टम की फाइलों को एन्क्रिप्ट कर देता है?","options":["वायरस","वॉर्म","रैनसमवेयर","स्पायवेयर"],"correct":"रैनसमवेयर","strategy":"एन्क्रिप्शन रैनसमवेयर की पहचान है ताकि यूजर डेटा एक्सेस न कर सके।"},{"type":"exam_pattern","topic":"Future Tech Trend","analysis":"Competitive Exams Trend:","stats":["तकनीकी शब्दावली (Deepfakes/Botnets): 2 प्रश्न","महत्वपूर्ण व्यक्तित्व और खोज: 1 प्रश्न","भारत के विशिष्ट रोबोट (Vyommitra/IAI): 1 प्रश्न"],"trend":"आयोग अब ''जेनरेटिव AI'' के नैतिक मुद्दों और ''क्वांटम कंप्यूटिंग'' के साइबर सुरक्षा पर प्रभाव जैसे विषयों पर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 9: Robotics, Artificial Intelligence and Cyber Security"},{"type":"p","text":"These three technologies are reshaping the 21st century. Robotics handles the physical behavior of machines, AI provides the thinking capability, and Cyber Security ensures the safety of this digital ecosystem. In MPPSC, questions often focus on robot components, fathers of AI, and types of cyber attacks."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Robotics"},{"type":"table","instruction":"Core Components of a Robot","head":["Component","Function"],"body":[["Sensors","Gather information from the surroundings (Like eyes/ears)."],["Actuators","Provide movement to the robot (Like muscles)."],["Controller","Processes instructions (Like the brain)."],["End-effector","Performs specific tasks like gripping or welding."]]},{"type":"h2","text":"2. Artificial Intelligence (AI)"},{"type":"ul","items":["**John McCarthy:** Known as the Father of AI.","**Machine Learning:** Systems that learn and improve from experience.","**Vyommitra:** ISRO’s half-humanoid robot for the Gaganyaan mission (2025-26).","**Generative AI:** Tools like ChatGPT and Gemini that can create content."]},{"type":"h2","text":"3. Cyber Security"},{"type":"table","instruction":"Common Cyber Threats","head":["Attack Type","Description"],"body":[["Phishing","Stealing sensitive data via fraudulent emails."],["Ransomware","Malware that locks data and demands payment."],["Spoofing","Disguising an unknown source as a known, trusted source."],["DDoS","Overwhelming a server with traffic to crash it."]]},{"type":"fact_card","title":"India’s Cyber Initiatives","facts":["CERT-In: The nodal agency for cyber security incident response.","DPDP Act 2023: Full-scale implementation of the Digital Personal Data Protection Act.","I4C: Indian Cyber Crime Coordination Centre.","Cyber Swachhta Kendra: Botnet Cleaning and Malware Analysis Centre."],"icon":"🛡️"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Who coined the term ''Artificial Intelligence''?","options":["John McCarthy","Alan Turing","Geoffrey Hinton","Marvin Minsky"],"correct":"John McCarthy","strategy":"He used the term first during the Dartmouth Conference in 1956."},{"type":"exam_pattern","topic":"Future Tech Trend","analysis":"Competitive Exams Trend:","stats":["Technical Terms (Deepfakes/Botnets): 2 questions","Famous Personalities & Innovations: 1 question","India''s Specific Robots (Vyommitra): 1 question"],"trend":"Commissions are now focusing on ''Ethical AI'' and the impact of ''Quantum Computing'' on Cyber Security."}]}', 'ict', NULL, 45, 1, 1770921830, 1770921830, 'blog', 'unit_9', 'Robotics, Artificial Intelligence and Cyber Security', 1, 0, 0, 1, 0, 'Unit 9: रोबोटिक्स, आर्टिफिशियल इंटेलिजेंस और साइबर सुरक्षा 21वीं सदी की ये तीन तकनीकें हमारे जीने और काम करने के तरीके को बदल रही हैं। ''रोबोटिक्स'' मशीनों के भौतिक व्यवहार को नियंत्रित करता है, ''AI'' उन...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('c8a4987e-3841-43bc-94ed-bdee13d4e53b', 'e-governance-ict-unit-9-mppsc', 'E-Governance: Concepts and Initiatives | ई-गवर्नेंस: अवधारणा और पहल', 'A comprehensive guide to E-governance for MPPSC Unit 9. Covers SMART governance, models (G2G, G2C, etc.), National & MP-specific digital initiatives, and high-yield PYQs.', '{"hi":[{"type":"h2","text":"Unit 9: ई-गवर्नेंस (Electronic Governance)"},{"type":"p","text":"ई-गवर्नेंस का अर्थ है सरकारी सूचनाओं और सेवाओं को नागरिकों तक पहुँचाने के लिए सूचना एवं संचार प्रौद्योगिकी (ICT) का उपयोग करना। इसका मुख्य उद्देश्य शासन को **SMART** (Simple, Moral, Accountable, Responsive, Transparent) बनाना है। MPPSC में अक्सर ई-गवर्नेंस के मॉडल्स और ''एमपी ऑनलाइन'' जैसे पोर्टल्स पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. ई-गवर्नेंस के मॉडल (Models of E-Governance)"},{"type":"p","text":"शासन की अंतःक्रिया के आधार पर इसे चार मुख्य भागों में बांटा गया है।"},{"type":"table","instruction":"ई-गवर्नेंस इंटरैक्शन मॉडल","head":["मॉडल","पूर्ण रूप","विवरण / उदाहरण"],"body":[["G2G","Government to Government","दो सरकारी विभागों के बीच सूचना का आदान-प्रदान। (उदा: SmartGov)"],["G2C","Government to Citizen","नागरिकों को मिलने वाली सेवाएं। (उदा: MP Online, DigiLocker)"],["G2B","Government to Business","व्यवसायों और उद्योगों के लिए सेवाएं। (उदा: ई-टेंडरिंग, GSTN)"],["G2E","Government to Employee","सरकारी कर्मचारियों के लिए प्रबंधन। (उदा: IFMIS पोर्टल)"]]},{"type":"h2","text":"2. प्रमुख राष्ट्रीय पहल (Major National Initiatives)"},{"type":"image_tag","content":""},{"type":"ul","items":["**डिजिटल इंडिया (2015):** शासन को डिजिटल रूप से सशक्त बनाने का महात्वाकांक्षी कार्यक्रम।","**उमंग (UMANG) ऐप:** केंद्र और राज्य सरकार की सेवाओं के लिए एक एकीकृत ऐप (Unified Mobile Application for New-age Governance)।","**डिजिलॉकर:** क्लाउड-आधारित प्लेटफॉर्म जहाँ दस्तावेजों को डिजिटल रूप से स्टोर और सत्यापित किया जा सकता है।","**PRAGATI:** प्रधानमंत्री द्वारा व्यक्तिगत रूप से परियोजनाओं की समीक्षा हेतु प्रो-एक्टिव गवर्नेंस प्लेटफॉर्म।"]},{"type":"h2","text":"3. मध्य प्रदेश में ई-गवर्नेंस (E-Governance in MP)"},{"type":"fact_card","title":"म.प्र. की डिजिटल प्रगति","facts":["MP Online: राज्य सरकार का अधिकृत पोर्टल (TCS के साथ संयुक्त उद्यम)।","समाधान ऑनलाइन: मुख्यमंत्री द्वारा सीधे जन शिकायतों के निवारण हेतु वीडियो कॉन्फ्रेंसिंग कार्यक्रम।","परख (PARAKH): शिक्षा की गुणवत्ता की निगरानी हेतु पोर्टल।","ज्ञानदूत योजना: धार जिले से शुरू हुई भारत की पहली ई-गवर्नेंस परियोजनाओं में से एक।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"ई-गवर्नेंस का अर्थ क्या है?","options":["इंटरनेट आधारित शासन","मशीन आधारित शासन","प्रौद्योगिकी आधारित शासन","उपरोक्त सभी"],"correct":"प्रौद्योगिकी आधारित शासन (Technology-driven Governance)","strategy":"ई-गवर्नेंस का व्यापक अर्थ ICT का उपयोग करके कुशलतापूर्वक शासन चलाना है।"},{"type":"pyq","exam":"UPSC Prelims 2018","year":2018,"question":"भारत सरकार द्वारा शुरू किए गए ''डिजिलॉकर'' (DigiLocker) के संदर्भ में कौन सा कथन सही है?","options":["यह एक क्लाउड स्टोरेज है","यह भौतिक दस्तावेजों की आवश्यकता को समाप्त करता है","यह केवल केंद्र सरकार द्वारा प्रबंधित है","1 और 2 दोनों"],"correct":"1 और 2 दोनों","strategy":"डिजिलॉकर का मुख्य उद्देश्य ''पेपरलेस'' गवर्नेंस को बढ़ावा देना है।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"सरकार और नागरिकों के बीच ई-गवर्नेंस के संपर्क को क्या कहा जाता है?","options":["G2G","G2C","G2B","C2G"],"correct":"G2C (Government to Citizen)","strategy":"नागरिकों के लिए सेवाएं ''C'' (Citizen) श्रेणी में आती हैं।"},{"type":"pyq","exam":"UPPSC Prelims 2021","year":2021,"question":"भारत में ई-गवर्नेंस के लिए ''राष्ट्रीय ई-गवर्नेंस योजना'' (NeGP) किस वर्ष शुरू की गई थी?","options":["2002","2006","2010","2015"],"correct":"2006","strategy":"18 मई 2006 को केंद्र सरकार ने इसे अपनी मंजूरी दी थी।"},{"type":"pyq","exam":"TPSC Prelims 2021","year":2021,"question":"''उमंग'' (UMANG) ऐप कितनी भाषाओं में उपलब्ध है?","options":["10","13","15","22"],"correct":"13","strategy":"उमंग ऐप 13 भारतीय भाषाओं में सेवाएं प्रदान करता है।"},{"type":"exam_pattern","topic":"E-Governance Trend","analysis":"Competitive Exams Trend:","stats":["ई-गवर्नेंस मॉडल्स (G2G, G2C): 2 प्रश्न","प्रमुख पोर्टल्स और उनकी लॉन्च तिथि: 1 प्रश्न","डिजिटल इंडिया के 9 स्तंभ: 1 प्रश्न"],"trend":"आयोग अब ''सिटिजन चार्टर'' और ''AI-गवर्नेंस'' जैसे आधुनिक विषयों को ई-गवर्नेंस के साथ जोड़कर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 9: E-Governance (Electronic Governance)"},{"type":"p","text":"E-Governance refers to the use of Information and Communication Technology (ICT) to deliver government services and information to citizens. Its main objective is to make governance **SMART** (Simple, Moral, Accountable, Responsive, Transparent). In MPPSC, questions are frequently asked about E-governance models and portals like ''MP Online''."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Models of E-Governance"},{"type":"table","instruction":"E-Governance Interaction Models","head":["Model","Full Form","Description / Example"],"body":[["G2G","Government to Government","Exchange of information between government departments. (e.g., SmartGov)"],["G2C","Government to Citizen","Services provided to citizens. (e.g., MP Online, DigiLocker)"],["G2B","Government to Business","Services for businesses and industries. (e.g., e-Tendering, GSTN)"],["G2E","Government to Employee","HR and management for govt employees. (e.g., IFMIS portal)"]]},{"type":"h2","text":"2. Major National Initiatives"},{"type":"ul","items":["**Digital India (2015):** An umbrella program to empower governance digitally.","**UMANG App:** Unified Mobile Application for New-age Governance for central and state services.","**DigiLocker:** A cloud-based platform for storing and verifying documents digitally.","**PRAGATI:** Pro-Active Governance and Timely Implementation platform chaired by the PM."]},{"type":"fact_card","title":"Digital Progress of MP","facts":["MP Online: The authorized portal of the State Government (Joint venture with TCS).","Samadhan Online: Video conferencing for direct resolution of public grievances by the CM.","Parakh: Portal for monitoring the quality of education.","Gyandoot: One of India''s first E-governance projects, started in Dhar district."],"icon":"🏛️"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"What is the meaning of E-Governance?","options":["Internet-based gov","Machine-based gov","Technology-driven gov","All of the above"],"correct":"Technology-driven Governance","strategy":"Broadly, it refers to using ICT to run governance efficiently."},{"type":"exam_pattern","topic":"E-Governance Trend","analysis":"Competitive Exams Trend:","stats":["E-governance Models: 2 questions","Major Portals & Launch dates: 1 question","9 Pillars of Digital India: 1 question"],"trend":"Commissions are now integrating ''AI-Governance'' and ''Citizen Charters'' into E-governance topics."}]}', 'ict', NULL, 40, 1, 1770921858, 1770921858, 'blog', 'unit_9', 'E-Governance', 1, 0, 0, 1, 0, 'Unit 9: ई-गवर्नेंस (Electronic Governance) ई-गवर्नेंस का अर्थ है सरकारी सूचनाओं और सेवाओं को नागरिकों तक पहुँचाने के लिए सूचना एवं संचार प्रौद्योगिकी (ICT) का उपयोग करना। इसका मुख्य उद्देश्य शासन को *...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('a949da65-7b5f-4783-b132-6d4e204e071a', 'internet-social-networking-ict-unit-9-mppsc', 'Internet & Social Networking Platforms | इंटरनेट और सोशल नेटवर्किंग प्लेटफॉर्म', 'Comprehensive guide to the Internet architecture and social networking sites for MPPSC Unit 9. Covers protocols, WWW history, social media trends in 2026, and multi-state PSC PYQs.', '{"hi":[{"type":"h2","text":"Unit 9: इंटरनेट और सोशल नेटवर्किंग प्लेटफॉर्म"},{"type":"p","text":"इंटरनेट आधुनिक सूचना क्रांति की रीढ़ है, जो पूरी दुनिया को एक ''ग्लोबल विलेज'' में बदल चुका है। इंटरनेट नेटवर्कों का एक विशाल जाल है, जबकि सोशल नेटवर्किंग साइट्स इस जाल पर मनुष्यों के बीच संवाद का सेतु हैं। MPPSC में अक्सर प्रोटोकॉल्स (TCP/IP), सर्च इंजन, और सोशल मीडिया के संस्थापकों एवं उनके मुख्यालयों पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. इंटरनेट की आधारभूत संरचना (Basics of Internet)"},{"type":"p","text":"इंटरनेट की शुरुआत 1969 में **ARPANET** से हुई थी। इसे संचालित करने के लिए कुछ नियमों का पालन किया जाता है जिन्हें ''प्रोटोकॉल'' कहते हैं।"},{"type":"table","instruction":"इंटरनेट शब्दावली और प्रोटोकॉल","head":["शब्द / प्रोटोकॉल","पूर्ण रूप (Full Form)","विवरण"],"body":[["TCP/IP","Transmission Control Protocol","इंटरनेट का मुख्य नियम जो डेटा पैकेट को सही स्थान पर पहुँचाता है।"],["WWW","World Wide Web","टिम बर्नर्स ली (1989) द्वारा आविष्कार।"],["HTTP/S","Hypertext Transfer Protocol","वेब पेजों के आदान-प्रदान के लिए (''S'' का अर्थ है Secure)।"],["URL","Uniform Resource Locator","किसी वेब पेज का विशिष्ट पता (Address)।"],["IP Address","Internet Protocol Address","नेटवर्क पर डिवाइस की पहचान (IPv4 और IPv6)।"]]},{"type":"h2","text":"2. सर्च इंजन और वेब ब्राउज़र (Search Engines & Browsers)"},{"type":"ul","items":["**वेब ब्राउज़र:** सॉफ्टवेयर जो वेब पेज देखने में मदद करता है। (उदा: Google Chrome, Mozilla Firefox, Safari, Microsoft Edge)।","**सर्च इंजन:** टूल जो इंटरनेट पर जानकारी खोजता है। (उदा: Google, Bing, Yahoo, Baidu, DuckDuckGo)।","**प्रथम वेब ब्राउज़र:** ''WorldWideWeb'' (बाद में Nexus) और ''Mosaic'' (प्रथम ग्राफिकल ब्राउज़र)।"]},{"type":"h2","text":"3. सोशल नेटवर्किंग प्लेटफॉर्म (Social Networking Sites)"},{"type":"p","text":"सोशल मीडिया अब सूचना के साथ-साथ विज्ञापन और राजनीति का भी मुख्य केंद्र बन गया है।"},{"type":"table","instruction":"प्रमुख सोशल मीडिया प्लेटफॉर्म","head":["प्लेटफॉर्म","संस्थापक (Founder)","वर्ष / तथ्य"],"body":[["Facebook (Meta)","मार्क जुकरबर्ग","2004 (मुख्यालय: मेंलो पार्क, कैलिफोर्निया)।"],["Twitter (X)","जैक डॉर्सी (X के मालिक: एलन मस्क)","2006 (नाम बदलकर ''X'' किया गया)।"],["YouTube","चाड हर्ले, स्टीव चेन, जावेद करीम","2005 (अब गूगल के स्वामित्व में)।"],["WhatsApp","ब्रायन एक्टन, जेन कौम","2009 (2014 में मेटा द्वारा अधिग्रहण)।"],["LinkedIn","रीड हॉफमैन","2002 (पेशेवर नेटवर्किंग हेतु)।"],["Instagram","केविन सिस्ट्रोम, माइक क्रेगर","2010 (फोटो और वीडियो शेयरिंग)।"]]},{"type":"highlight","level":"important","text":"ट्रेंड 2026: ''थ्रेड्स'' (Threads) और ''ब्लूस्काई'' (Bluesky) जैसे नए प्लेटफॉर्म माइक्रोब्लॉगिंग के क्षेत्र में उभर रहे हैं। AI के एकीकरण (जैसे- Meta AI) ने सोशल मीडिया के अनुभव को बदल दिया है।","icon":"📱"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"वर्ल्ड वाइड वेब (WWW) का आविष्कार किसने किया था?","options":["बिल गेट्स","टिम बर्नर्स ली","लैरी पेज","स्टीव जॉब्स"],"correct":"टिम बर्नर्स ली","strategy":"उन्होंने 1989 में CERN में इसकी नींव रखी थी।"},{"type":"pyq","exam":"UPSC Prelims 2022","year":2022,"question":"Web 3.0 के संदर्भ में, कौन सा कथन सही है?","options":["यह ब्लॉकचेन तकनीक पर आधारित है","यह उपयोगकर्ताओं को अपने डेटा पर नियंत्रण देता है","यह केवल सरकारों द्वारा प्रबंधित होता है","1 और 2 दोनों"],"correct":"1 और 2 दोनों","strategy":"Web 3.0 का मूल विचार ''विकेंद्रीकरण'' (Decentralization) है।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"निम्नलिखित में से कौन सा एक सर्च इंजन नहीं है?","options":["Google","Yahoo","AltaVista","Chrome"],"correct":"Chrome","strategy":"Chrome एक वेब ब्राउज़र है, जबकि Google एक सर्च इंजन है।"},{"type":"pyq","exam":"UPPSC Prelims 2021","year":2021,"question":"फेसबुक के संस्थापक कौन हैं?","options":["स्टीव चेन","मार्क जुकरबर्ग","जिमी वेल्स","लॉरेंस टेस्लर"],"correct":"मार्क जुकरबर्ग","strategy":"हार्वर्ड यूनिवर्सिटी में पढ़ाई के दौरान उन्होंने इसे बनाया था।"},{"type":"pyq","exam":"TPSC Prelims 2021","year":2021,"question":"IP पते (IPv4) में कितने बिट्स होते हैं?","options":["16","32","64","128"],"correct":"32","strategy":"IPv4 32-बिट और IPv6 128-बिट का होता है।"},{"type":"exam_pattern","topic":"Internet Trend","analysis":"Competitive Exams Trend:","stats":["संस्थापक और मुख्यालय: 2 प्रश्न","इंटरनेट प्रोटोकॉल और शब्दावली: 1 प्रश्न","सोशल मीडिया विवाद और नियम (IT Rules): 1 प्रश्न"],"trend":"आयोग अब ''सर्फेस वेब'' के साथ-साथ ''डीप वेब'' और ''डार्क वेब'' की परिभाषाओं पर भी ध्यान दे रहे हैं।"}],"en":[{"type":"h2","text":"Unit 9: Internet and Social Networking Platforms"},{"type":"p","text":"The Internet is the backbone of the modern information revolution, turning the world into a ''Global Village''. While the Internet is a vast network of networks, social networking sites act as bridges of communication. In MPPSC, questions target protocols (TCP/IP), search engines, and social media founders."},{"type":"image_tag","content":""},{"type":"h2","text":"1. Internet Architecture"},{"type":"table","instruction":"Internet Terminology and Protocols","head":["Term / Protocol","Full Form","Description"],"body":[["TCP/IP","Transmission Control Protocol","Primary protocol ensuring correct data packet delivery."],["WWW","World Wide Web","Invented by Tim Berners-Lee (1989)."],["URL","Uniform Resource Locator","Unique address of a web page."],["IP Address","Internet Protocol Address","Identity of a device on a network (IPv4/IPv6)."]]},{"type":"h2","text":"2. Social Networking Platforms"},{"type":"table","instruction":"Major Social Media Platforms","head":["Platform","Founder","Key Fact"],"body":[["Facebook (Meta)","Mark Zuckerberg","Founded in 2004."],["Twitter (X)","Jack Dorsey (Owner: Elon Musk)","Rebranded as ''X''."],["YouTube","Hurley, Chen, Karim","Founded in 2005."],["LinkedIn","Reid Hoffman","Professional networking."],["WhatsApp","Brian Acton, Jan Koum","Acquired by Meta in 2014."]]},{"type":"fact_card","title":"Modern Web Trends 2026","facts":["Web 3.0: Focus on decentralization using Blockchain technology.","Generative AI: Integration of AI chatbots within platforms like Meta and X.","Privacy: Stringent IT Rules (2021/2023) for intermediary liability.","Digital Infrastructure: Shift from IPv4 to IPv6 for accommodating more devices."],"icon":"📱"},{"type":"exam_pattern","topic":"Internet Trend","analysis":"Competitive Exams Trend:","stats":["Founders & HQs: 2 questions","Internet Protocols: 1 question","Social Media Laws (IT Rules): 1 question"],"trend":"Commissions are now exploring ''Surface Web'' vs ''Dark Web'' concepts alongside traditional questions."}]}', 'ict', NULL, 45, 1, 1770922022, 1770922022, 'blog', 'unit_9', 'Internet and Social Networking Platforms', 1, 0, 0, 1, 0, 'Unit 9: इंटरनेट और सोशल नेटवर्किंग प्लेटफॉर्म इंटरनेट आधुनिक सूचना क्रांति की रीढ़ है, जो पूरी दुनिया को एक ''ग्लोबल विलेज'' में बदल चुका है। इंटरनेट नेटवर्कों का एक विशाल जाल है, जबकि सोशल नेटवर्किंग स...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('f44b729d-d997-42d9-b872-3dd9a669e3f6', 'tribes-mp-geography-constitution-unit-10', 'Geographical Distribution & Constitutional Provisions of Tribes | जनजातियों का भौगोलिक वितरण और संवैधानिक प्रावधान', 'Exhaustive guide to the geographical distribution of tribes in MP and key constitutional articles for MPPSC Unit 10. Features mapping and multi-state PSC PYQs.', '{"hi":[{"type":"h2","text":"Unit 10: म.प्र. की जनजातियाँ - भौगोलिक वितरण एवं संवैधानिक प्रावधान"},{"type":"p","text":"मध्य प्रदेश जनजातीय जनसंख्या की दृष्टि से भारत का शीर्ष राज्य है। यहाँ की 21.1% जनसंख्या जनजातीय है (2011 की जनगणना के अनुसार)। इन जनजातियों को उनके निवास स्थान के आधार पर चार मुख्य क्षेत्रों में बांटा गया है। साथ ही, भारतीय संविधान इन समुदायों को विशेष सुरक्षा और अधिकार प्रदान करता है। MPPSC में अक्सर अनुच्छेद 342, 338A और जनजातियों के क्षेत्रीय संकेंद्रण पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. म.प्र. में जनजातियों का भौगोलिक वितरण (Geographical Distribution)"},{"type":"image_tag","content":""},{"type":"table","instruction":"जनजातीय क्षेत्र और प्रमुख जनजातियाँ","head":["क्षेत्र (Zone)","प्रमुख जनजातियाँ","जिले (Districts)"],"body":[["पश्चिमी क्षेत्र","भील (म.प्र. की सबसे बड़ी जनजाति), भिलाला","झाबुआ, अलीराजपुर, धार, बड़वानी।"],["उत्तरी क्षेत्र","सहरिया (PVTG)","ग्वालियर, शिवpuri, गुना, श्योपुर, मुरैना।"],["दक्षिणी क्षेत्र","गोंड, कोरकू, भारिया (PVTG)","छिंदवाड़ा, बैतूल, सिवनी, नर्मदापुरम।"],["पूर्वी क्षेत्र","बैगा (PVTG), कोल, पनिका, सहरिया","मंडला, डिंडोरी, शहडोल, अनूपपुर, सीधी।"]]},{"type":"h2","text":"2. जनजातियों से संबंधित संवैधानिक प्रावधान (Constitutional Provisions)"},{"type":"p","text":"संविधान में जनजातियों को ''अनुसूचित जनजाति'' (ST) के रूप में परिभाषित और संरक्षित किया गया है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"महत्वपूर्ण संवैधानिक अनुच्छेद","head":["अनुच्छेद (Article)","विवरण (Provision)"],"body":[["342","ST की अधिसूचना (राष्ट्रपति द्वारा राज्यपाल की सलाह पर)।"],["366 (25)","अनुसूचित जनजातियों की परिभाषा।"],["338-A","राष्ट्रीय अनुसूचित जनजाति आयोग (NCST) का गठन।"],["330","लोकसभा में ST के लिए सीटों का आरक्षण।"],["332","राज्य विधानसभाओं में ST के लिए सीटों का आरक्षण।"],["244 (1)","5वीं अनुसूची: अनुसूचित क्षेत्रों का प्रशासन (म.प्र. में 89 आदिवासी ब्लॉक)।"],["46","ST के शैक्षिक और आर्थिक हितों को बढ़ावा देना।"],["16 (4)","सरकारी नौकरियों में आरक्षण का प्रावधान।"]]},{"type":"highlight","level":"important","text":"विशेष: मध्य प्रदेश में 3 विशेष रूप से कमजोर जनजातीय समूह (PVTGs) हैं—बैगा, भारिया और सहरिया।","icon":"📝"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश की सबसे बड़ी जनजाति कौन सी है?","options":["गोंड","भील","बैगा","कोरकू"],"correct":"भील","strategy":"भील म.प्र. की सबसे बड़ी और गोंड दूसरी सबसे बड़ी जनजाति है।"},{"type":"pyq","exam":"UPSC Prelims 2018","year":2018,"question":"भारतीय संविधान की 5वीं अनुसूची के तहत अनुसूचित क्षेत्रों का प्रशासन किसके द्वारा नियंत्रित होता है?","options":["संसद","राष्ट्रपति","राज्यपाल","मुख्यमंत्री"],"correct":"राष्ट्रपति (राज्यपाल की रिपोर्ट के माध्यम से)","strategy":"अनुच्छेद 244(1) और 5वीं अनुसूची प्रशासन का आधार है।"},{"type":"pyq","exam":"UPPSC Prelims 2022","year":2022,"question":"89वें संविधान संशोधन अधिनियम (2003) द्वारा किस आयोग का गठन किया गया?","options":["NCSC","NCST","NCBC","Niti Aayog"],"correct":"NCST (अनुच्छेद 338A)","strategy":"इस संशोधन द्वारा अनुसूचित जाति और जनजाति आयोग को अलग किया गया था।"},{"type":"pyq","exam":"BPSC Prelims 2021","year":2021,"question":"संविधान के किस अनुच्छेद के तहत राष्ट्रपति किसी समुदाय को ST घोषित कर सकते हैं?","options":["अनुच्छेद 341","अनुच्छेद 342","अनुच्छेद 340","अनुच्छेद 338"],"correct":"अनुच्छेद 342","strategy":"341 SC के लिए है और 342 ST के लिए।"},{"type":"exam_pattern","topic":"Tribal Distribution & Constitution Trend","analysis":"Competitive Exams Trend:","stats":["जनजातियों का जिला-वार वितरण: 3-4 प्रश्न","संवैधानिक अनुच्छेद (NCST/आरक्षण): 2 प्रश्न","PVTGs की सूची: 1 प्रश्न"],"trend":"आयोग अब जनजातियों की ''उप-जातियों'' (Sub-tribes) और उनके विशिष्ट निवास क्षेत्रों (जैसे ''पातालकोट'' के भारिया) पर गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 10: Tribes of MP - Geographical Distribution & Constitutional Provisions"},{"type":"p","text":"Madhya Pradesh is the leading state in India in terms of tribal population, with 21.1% of its population being tribal (as per Census 2011). These tribes are classified into four main regions based on their habitation. Additionally, the Indian Constitution provides special safeguards and rights to these communities. In MPPSC, questions are frequently asked on Article 342, 338A, and the regional concentration of tribes."},{"type":"h2","text":"1. Geographical Distribution of Tribes in MP"},{"type":"image_tag","content":""},{"type":"table","instruction":"Tribal Zones and Major Tribes","head":["Zone","Major Tribes","Districts"],"body":[["Western Zone","Bhil (Largest in MP), Bhilala","Jhabua, Alirajpur, Dhar, Barwani."],["Northern Zone","Sahariya (PVTG)","Gwalior, Shivpuri, Guna, Sheopur, Morena."],["Southern Zone","Gond, Korku, Bharia (PVTG)","Chhindwara, Betul, Seoni, Narmadapuram."],["Eastern Zone","Baiga (PVTG), Kol, Panika","Mandla, Dindori, Shahdol, Anuppur, Sidhi."]]},{"type":"h2","text":"2. Constitutional Provisions Related to Tribes"},{"type":"p","text":"Tribes are defined and protected as ''Scheduled Tribes'' (ST) under the Constitution."},{"type":"image_tag","content":""},{"type":"table","instruction":"Important Constitutional Articles","head":["Article","Provision"],"body":[["342","Notification of ST (By President on Governor''s advice)."],["366 (25)","Definition of Scheduled Tribes."],["338-A","Establishment of National Commission for ST (NCST)."],["330","Reservation of seats for ST in Lok Sabha."],["332","Reservation of seats for ST in State Assemblies."],["244 (1)","5th Schedule: Administration of Scheduled Areas (89 blocks in MP)."],["46","Promotion of educational and economic interests of ST."],["16 (4)","Provision of reservation in public employment."]]},{"type":"fact_card","title":"PVTGs of Madhya Pradesh","facts":["MP has 3 Particularly Vulnerable Tribal Groups: Baiga, Bharia, and Sahariya.","Sahariya is mainly concentrated in the Gwalior-Chambal division.","Bharia is famous for inhabiting ''Patalkot'' in Chhindwara district.","Baiga is known as the ''priests'' of the Gond tribe."],"icon":"📝"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Which is the largest tribe of Madhya Pradesh?","options":["Gond","Bhil","Baiga","Korku"],"correct":"Bhil","strategy":"Bhil is the largest, while Gond is the second-largest tribe in MP."},{"type":"pyq","exam":"UPSC Prelims 2018","year":2018,"question":"Under which schedule of the Constitution is the administration of Scheduled Areas controlled?","options":["Parliament","President","Governor","Chief Minister"],"correct":"President (through Governor''s reports)","strategy":"Article 244(1) and the 5th Schedule are the base of administration."},{"type":"pyq","exam":"UPPSC Prelims 2022","year":2022,"question":"Which commission was formed by the 89th Constitutional Amendment Act (2003)?","options":["NCSC","NCST","NCBC","Niti Aayog"],"correct":"NCST (Article 338A)","strategy":"This amendment bifurcated the combined SC and ST commission."},{"type":"pyq","exam":"BPSC Prelims 2021","year":2021,"question":"Under which article can the President notify a community as ST?","options":["Article 341","Article 342","Article 340","Article 338"],"correct":"Article 342","strategy":"341 is for SC and 342 is for ST."},{"type":"exam_pattern","topic":"Tribal Distribution & Constitution Trend","analysis":"Competitive Exams Trend:","stats":["District-wise distribution: 3-4 questions","Constitutional Articles: 2 questions","PVTGs details: 1 question"],"trend":"Commissions are now asking detailed questions about ''Sub-tribes'' and specific habitation areas like ''Patalkot''."}]}', 'tribal_studies', NULL, 45, 1, 1770922066, 1771008918, 'blog', 'unit_10', 'Geographical distribution of Tribes in MP, Constitutional Provisions Related to Tribes', 1, 0, 1, 1, 0, 'Unit 10: म.प्र. की जनजातियाँ - भौगोलिक वितरण एवं संवैधानिक प्रावधान मध्य प्रदेश जनजातीय जनसंख्या की दृष्टि से भारत का शीर्ष राज्य है। यहाँ की 21.1% जनसंख्या जनजातीय है (2011 की जनगणना के अनुसार)। इन ज...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('614454e9-dd63-4c46-9352-2283521e273e', 'major-tribes-pvtg-welfare-mp-unit-10', 'Major Tribes, PVTGs and Welfare Programs of MP | म.प्र. की प्रमुख जनजातियाँ, PVTG एवं कल्याणकारी कार्यक्रम', 'A deep dive into major tribes of MP (Bhil, Gond, Kol), the three PVTGs (Baiga, Bharia, Sahariya), and latest tribal welfare schemes for MPPSC Unit 10.', '{"hi":[{"type":"h2","text":"Unit 10: म.प्र. की प्रमुख जनजातियाँ, PVTG एवं कल्याणकारी कार्यक्रम"},{"type":"p","text":"मध्य प्रदेश विविध जनजातीय संस्कृतियों का संगम है। यहाँ की जनजातियों को न केवल उनकी जनसंख्या, बल्कि उनकी विशिष्ट सांस्कृतिक पहचान और आर्थिक पिछड़ेपन (PVTGs) के आधार पर भी समझा जाना चाहिए। MPPSC में अक्सर जनजातियों की उप-जातियों, उनके निवास स्थान और नई सरकारी योजनाओं (जैसे PM-JANMAN) पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. मध्य प्रदेश की प्रमुख जनजातियाँ (Major Tribes)"},{"type":"table","instruction":"प्रमुख जनजातियों का विवरण","head":["जनजाति","प्रमुख उप-जातियाँ","विशेष विशेषता / सांस्कृतिक पहचान"],"body":[["भील (Bhil)","भिलाला, बरेला, पटलिया","म.प्र. की सबसे बड़ी जनजाति; ''भगोरिया'' इनका प्रमुख उत्सव है।"],["गोंड (Gond)","अगरिया, प्रधान, ओझा, सोलाहस","विश्व का सबसे बड़ा जनजातीय समूह; ''दूध लौटाना'' विवाह प्रथा प्रचलित है।"],["कोल (Kol)","रोतिया, रोतेले","म.प्र. की तीसरी बड़ी जनजाति; रीवा-शहडोल संभाग में संकेंद्रित।"],["कोरकू (Korku)","मोवासी, बावरिया, रूमा","बैतूल-छिंदवाड़ा क्षेत्र; ''चटकोरा'' इनका प्रसिद्ध नृत्य है।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. विशेष रूप से कमजोर जनजातीय समूह (PVTGs)"},{"type":"p","text":"भारत सरकार ने 75 जनजातियों को PVTG के रूप में चिन्हित किया है, जिनमें से 3 मध्य प्रदेश में हैं। इनकी विशेषता घटती जनसंख्या, साक्षरता का निम्न स्तर और आदिम तकनीक है।"},{"type":"table","instruction":"म.प्र. के PVTG समूह","head":["PVTG समूह","मुख्य निवास क्षेत्र","विशेष तथ्य"],"body":[["बैगा (Baiga)","मंडला, डिंडोरी, बालाघाट","इन्हें ''गोंडों का पुरोहित'' कहा जाता है; ये ''बेवर'' (झूम खेती) करते हैं।"],["भारिया (Bharia)","पातालकोट (छिंदवाड़ा)","1981 की जनगणना में इन्हें ''जंगलियों के भी जंगली'' कहा गया था।"],["सहरिया (Sahariya)","ग्वालियर, शिवपुरी, श्योपुर","जड़ी-बूटियों की पहचान में माहिर; कुपोषण की समस्या अधिक।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"3. जनजातीय कल्याण कार्यक्रम (Welfare Programs 2025-26)"},{"type":"fact_card","title":"प्रमुख कल्याणकारी योजनाएं","facts":["PM-JANMAN (2024-26): PVTG समुदायों के लिए ₹24,000 करोड़ का मिशन; आवास, सड़क और शिक्षा पर ध्यान।","सिकल सेल एनीमिया उन्मूलन मिशन 2047: प्रधानमंत्री द्वारा शाहडोल से लॉन्च; जनजातीय क्षेत्रों में जेनेटिक स्क्रीनिंग।","भगवान बिरसा मंडा स्व-रोजगार योजना: ST युवाओं को ₹1 लाख से ₹50 लाख तक का ऋण (सब्सिडी के साथ)।","टंट्या मामा आर्थिक कल्याण योजना: नए उद्योगों के लिए ₹10,000 से ₹1 लाख तक की सहायता।"],"icon":"🛡️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2022","year":2022,"question":"पातालकोट (छिंदवाड़ा) में कौन सी जनजाति निवास करती है?","options":["भील","भारिया","सहरिया","गोंड"],"correct":"भारिया","strategy":"पातालकोट एक गहरी घाटी है जहाँ भारिया जनजाति सदियों से निवास कर रही है।"},{"type":"pyq","exam":"UPSC Prelims 2019","year":2019,"question":"भारत में PVTGs (Particularly Vulnerable Tribal Groups) के निर्धारण का मानदंड क्या है?","options":["आदिम कृषि प्रणाली","घटती जनसंख्या","निम्न साक्षरता","उपरोक्त सभी"],"correct":"उपरोक्त सभी","strategy":"ढेंवर आयोग की सिफारिशों के आधार पर ये मानदंड तय किए गए हैं।"},{"type":"pyq","exam":"UPPSC Prelims 2020","year":2020,"question":"किस जनजाति को ''जड़ी-बूटियों का ज्ञाता'' माना जाता है?","options":["गोंड","बैगा","सहरिया","पनिका"],"correct":"सहरिया","strategy":"सहरिया जनजाति वनों से जड़ी-बूटियाँ एकत्रित करने और उनकी पहचान में कुशल होती है।"},{"type":"pyq","exam":"BPSC Prelims 2021","year":2021,"question":"भगवान बिरसा मुंडा का जन्म स्थान कहाँ है?","options":["उलीहातू","पातालकोट","झाबुआ","बस्तर"],"correct":"उलीहातू (झारखंड)","strategy":"बिरसा मुंडा जनजातीय गौरव के प्रतीक हैं, जिनका प्रभाव म.प्र. में भी व्यापक है।"},{"type":"exam_pattern","topic":"Tribal Welfare & PVTGs Trend","analysis":"Competitive Exams Trend:","stats":["PVTG विशिष्ट प्रश्न: 2-3 प्रश्न","जनजातीय विवाह एवं प्रथाएं: 1-2 प्रश्न","कल्याणकारी योजनाएं (बजट सहित): 2 प्रश्न"],"trend":"आयोग अब योजनाओं के ''नाम'' के साथ-साथ उनके ''बजट आवंटन'' और ''लक्ष्य वर्ष'' (जैसे 2047) पर अधिक फोकस कर रहा है।"}],"en":[{"type":"h2","text":"Unit 10: Major Tribes, PVTGs, and Tribal Welfare Programs"},{"type":"p","text":"Madhya Pradesh is a confluence of diverse tribal cultures. Its tribes must be understood not only by their population but also through their unique cultural identity and socio-economic backwardness (PVTGs). MPPSC frequently asks about sub-tribes, their habitations, and new government schemes like PM-JANMAN."},{"type":"h2","text":"1. Major Tribes of Madhya Pradesh"},{"type":"table","instruction":"Details of Major Tribes","head":["Tribe","Major Sub-tribes","Unique Identity / Culture"],"body":[["Bhil","Bhilala, Barela, Patalia","Largest tribe of MP; ''Bhagoria'' is their main festival."],["Gond","Agaria, Pradhan, Ojha","Largest tribal group globally; ''Doodh Lautana'' marriage is famous."],["Kol","Rotia, Rotele","Third largest tribe of MP; concentrated in Rewa-Shahdol division."],["Korku","Movasi, Bawari, Ruma","Found in Betul-Chhindwara; ''Chatkora'' is their famous dance."]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. Particularly Vulnerable Tribal Groups (PVTGs)"},{"type":"p","text":"The Government of India has identified 75 PVTGs, out of which 3 are in MP. They are characterized by a declining population, low literacy, and primitive technology."},{"type":"table","instruction":"PVTGs of MP","head":["PVTG Group","Main Habitation","Key Facts"],"body":[["Baiga","Mandla, Dindori, Balaghat","Known as ''Priests of Gonds''; they practice ''Bewar'' (Shifting cultivation)."],["Bharia","Patalkot (Chhindwara)","In the 1981 census, they were called ''Wildest among the wild''."],["Sahariya","Gwalior, Shivpuri, Sheopur","Experts in identifying medicinal herbs; face high malnutrition."]]},{"type":"h2","text":"3. Tribal Welfare Programs (2025-26)"},{"type":"fact_card","title":"Key Welfare Schemes","facts":["PM-JANMAN (2024-26): A ₹24,000 Cr mission for PVTG communities focusing on housing and education.","Sickle Cell Elimination Mission 2047: Launched from Shahdol; focuses on genetic screening in tribal zones.","Bhagwan Birsa Munda Self-Employment Scheme: Loans from ₹1 Lakh to ₹50 Lakh with subsidies for ST youth.","Tantya Mama Economic Welfare Scheme: Assistance of ₹10,000 to ₹1 Lakh for new small industries."],"icon":"🛡️"},{"type":"pyq","exam":"MPPSC Prelims 2022","year":2022,"question":"Which tribe resides in Patalkot (Chhindwara)?","options":["Bhil","Bharia","Sahariya","Gond"],"correct":"Bharia","strategy":"Patalkot is a deep valley where the Bharia tribe has lived in isolation for centuries."},{"type":"pyq","exam":"UPSC Prelims 2019","year":2019,"question":"What are the criteria for determining PVTGs in India?","options":["Primitive Agriculture","Declining Population","Low Literacy","All of the above"],"correct":"All of the above","strategy":"These criteria were established based on the Dhebar Commission''s recommendations."},{"type":"pyq","exam":"UPPSC Prelims 2020","year":2020,"question":"Which tribe is considered an ''expert in medicinal herbs''?","options":["Gond","Baiga","Sahariya","Panika"],"correct":"Sahariya","strategy":"The Sahariya tribe is skilled in identifying and collecting herbs from the forests."},{"type":"pyq","exam":"BPSC Prelims 2021","year":2021,"question":"What is the birthplace of Bhagwan Birsa Munda?","options":["Ulihatu","Patalkot","Jhabua","Bastar"],"correct":"Ulihatu (Jharkhand)","strategy":"Birsa Munda is an icon of tribal pride whose influence is immense in MP as well."},{"type":"exam_pattern","topic":"Tribal Welfare & PVTGs Trend","analysis":"Competitive Exams Trend:","stats":["PVTG Specific: 2-3 questions","Tribal Customs: 1-2 questions","Welfare Schemes (with Budget): 2 questions"],"trend":"Commissions are shifting focus from just the ''names'' of schemes to ''budget allocations'' and ''target years'' like 2047."}]}', 'tribal_studies', NULL, 45, 1, 1770922103, 1771076002, 'blog', 'unit_10', 'Major Tribes of Madhya Pradesh, PVTG and Tribal Welfare Programs', 0, 1, 1, 1, 0, 'Unit 10: म.प्र. की प्रमुख जनजातियाँ, PVTG एवं कल्याणकारी कार्यक्रम मध्य प्रदेश विविध जनजातीय संस्कृतियों का संगम है। यहाँ की जनजातियों को न केवल उनकी जनसंख्या, बल्कि उनकी विशिष्ट सांस्कृतिक पहचान और आ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('b8b3e0fc-f7d6-46f7-bfdf-946b6452fe37', 'tribal-culture-arts-festivals-mp-unit-10', 'Tribal Culture of MP: Arts, Festivals & Traditions | म.प्र. की जनजातीय संस्कृति', 'Comprehensive guide to the rich tribal heritage of Madhya Pradesh. Covers Pithora art, Gondi literature, Bhagoria festival, and traditional customs for MPPSC Unit 10.', '{"hi":[{"type":"h2","text":"Unit 10: म.प्र. की जनजातीय संस्कृति, कला एवं साहित्य"},{"type":"p","text":"मध्य प्रदेश की जनजातीय संस्कृति विश्व की सबसे प्राचीन और समृद्ध संस्कृतियों में से एक है। यहाँ की कला केवल मनोरंजन नहीं, बल्कि जीवन जीने का एक तरीका है। MPPSC में अक्सर जनजातीय नृत्य, चित्रकला (जैसे पिथोरा) और विवाह प्रथाओं (जैसे लमसेना) पर प्रश्न पूछे जाते हैं। 2026 के संदर्भ में, जनजातीय साहित्य का संरक्षण और डिजिटल अभिलेखीकरण एक महत्वपूर्ण करंट अफेयर भी है।"},{"type":"h2","text":"1. जनजातीय विवाह एवं सामाजिक प्रथाएं (Customs & Traditions)"},{"type":"table","instruction":"प्रमुख जनजातीय विवाह प्रथाएं","head":["विवाह का प्रकार","जनजाति","विशेषता"],"body":[["भगोरिया विवाह","भील","मेले के दौरान जीवनसाथी का चुनाव।"],["लमसेना (सेवा विवाह)","गोंड / बैगा","दूल्हा ससुर के यहाँ रहकर सेवा करता है।"],["दूध लौटाना","गोंड","ममेरे-फुफेरे भाई-बहनों में विवाह।"],["पठौनी विवाह","गोंड","दुल्हन बारात लेकर दूल्हे के घर आती है।"]]},{"type":"h2","text":"2. जनजातीय कला और त्यौहार (Special Arts & Festivals)"},{"type":"p","text":"जनजातीय कलाओं में ''पिथोरा'' और ''गोंड चित्रकला'' को वैश्विक पहचान मिली है।"},{"type":"image_tag","content":""},{"type":"table","instruction":"प्रमुख कला एवं त्यौहार","head":["कला / त्यौहार","जनजाति","विवरण"],"body":[["पिथोरा भित्ति चित्र","भील","दीवारों पर घोड़ों के चित्र (पेमा फाल्या प्रसिद्ध कलाकार)।"],["गोंड चित्रकला","गोंड","बिंदुओं और रेखाओं का प्रयोग (जंगढ़ सिंह श्याम प्रवर्तक)।"],["कर्मा नृत्य","गोंड / बैगा","लोक नृत्यों का राजा; गिनीज बुक में शामिल।"],["मड़ई उत्सव","गोंड","फसल कटाई के बाद मनाया जाने वाला भव्य मेला।"]]},{"type":"image_tag","content":""},{"type":"h2","text":"3. जनजातीय बोलियाँ एवं साहित्य (Dialects & Literature)"},{"type":"ul","items":["**भीली:** पश्चिमी म.प्र. में सर्वाधिक बोली जाने वाली जनजातीय बोली।","**गोंडी:** गोंड जनजाति की बोली; इसकी अपनी लिपि ''गुंजल गोंडी'' भी खोजी गई है।","**कोरकू:** मुंडा भाषा परिवार का हिस्सा।","**साहित्य:** भज्जू श्याम और भूरी बाई जैसे कलाकारों ने अपनी आत्मकथाओं और चित्रों के जरिए जनजातीय साहित्य को नई दिशा दी है।"]},{"type":"fact_card","title":"सांस्कृतिक व्यक्तित्व: गौरव","facts":["पेमा फाल्या: पिथोरा चित्रकला के शिखर पुरुष (भील)।","भूरी बाई: पिथोरा कला के लिए पद्म श्री सम्मानित (झाबुआ)।","दुर्गा बाई व्याम: गोंड चित्रकला के लिए प्रसिद्ध (पद्म श्री 2022)।","अर्जुन सिंह धुर्वे: बैगा नृत्य (परधौनी) के संरक्षण के लिए पद्म श्री सम्मानित।"],"icon":"🎨"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"पिथोरा (Pithora) भित्ति चित्रकला किस जनजाति से संबंधित है?","options":["गोंड","भील","बैगा","भारिया"],"correct":"भील","strategy":"यह भील जनजाति की अनुष्ठानिक (Ritual) चित्रकला है।"},{"type":"pyq","exam":"UPSC Prelims 2013","year":2013,"question":"प्रसिद्ध ''भगोरिया उत्सव'' किस जनजाति के सांस्कृतिक जीवन का हिस्सा है?","options":["बैगा","भील","गोंड","सहरिया"],"correct":"भील","strategy":"भगोरिया मुख्य रूप से पश्चिमी म.प्र. के भील क्षेत्रों में मनाया जाता है।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"''कर्मा'' (Karma) किस क्षेत्र का प्रमुख लोक नृत्य है?","options":["बुंदेलखंड","मालवा","मंडला/पूर्वी म.प्र.","निमाड़"],"correct":"मंडला/पूर्वी म.प्र. (गोंड/बैगा बाहुल्य)","strategy":"यह पूर्वी म.प्र. की गोंड और बैगा जनजातियों का सबसे प्रसिद्ध नृत्य है।"},{"type":"pyq","exam":"UPPSC Prelims 2019","year":2019,"question":"लमसेना (Lamsena) विवाह किस जनजाति में प्रचलित है?","options":["गोंड","भील","कोरकू","कोय"],"correct":"गोंड","strategy":"लमसेना सेवा विवाह का एक रूप है जो गोंड और बैगा दोनों में मिलता है।"},{"type":"exam_pattern","topic":"Tribal Culture Trend","analysis":"Competitive Exams Trend:","stats":["चित्रकला और कलाकार (Padma Awards): 3-4 प्रश्न","विवाह और सामाजिक प्रथाएं: 2 प्रश्न","त्यौहार और नृत्य: 2-3 प्रश्न"],"trend":"आयोग अब केवल त्यौहार का नाम नहीं, बल्कि उसके पीछे की ''कथा'' या ''प्रतीक'' (जैसे पिथोरा में घोड़े का महत्व) पर प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 10: Tribal Culture, Arts and Literature of MP"},{"type":"p","text":"The tribal culture of Madhya Pradesh is among the oldest and richest in the world. Art here is not just entertainment but a way of life. In MPPSC, questions are often asked about tribal dances, paintings (like Pithora), and marriage customs (like Lamsena)."},{"type":"h2","text":"1. Tribal Marriage & Social Customs"},{"type":"table","instruction":"Major Tribal Marriage Customs","head":["Marriage Type","Tribe","Characteristic"],"body":[["Bhagoria","Bhil","Choice of life partner during the fair."],["Lamsena (Service)","Gond / Baiga","Groom serves the father-in-law''s house."],["Doodh Lautana","Gond","Marriage among cross-cousins."],["Pathauni","Gond","Bride comes to the groom''s house with the procession."]]},{"type":"h2","text":"2. Special Arts & Festivals"},{"type":"image_tag","content":""},{"type":"table","instruction":"Key Arts & Festivals","head":["Art / Festival","Tribe","Description"],"body":[["Pithora Mural","Bhil","Ritual painting of horses (Pema Falya is the pioneer)."],["Gond Art","Gond","Use of dots and lines (Jangarh Singh Shyam pioneered it)."],["Karma Dance","Gond / Baiga","King of folk dances; recorded in Guinness World Records."],["Madai Festival","Gond","Grand fair celebrated after the harvest season."]]},{"type":"image_tag","content":""},{"type":"h2","text":"3. Dialects & Literature"},{"type":"ul","items":["**Bhili:** Most spoken tribal dialect in Western MP.","**Gondi:** Dialect of the Gond tribe; its script ''Gunjal Gondi'' has been rediscovered.","**Korku:** Belongs to the Munda language family.","**Literature:** Artists like Bhajju Shyam and Bhuri Bai have added new dimensions to tribal literature through their autobiographies."]},{"type":"fact_card","title":"Cultural Personalities: Pride of MP","facts":["Pema Falya: Master of Pithora painting (Bhil).","Bhuri Bai: Awarded Padma Shri for Pithora art (Jhabua).","Durga Bai Vyam: Famous for Gond painting (Padma Shri 2022).","Arjun Singh Dhurve: Awarded Padma Shri for preserving Baiga dance (Pardhauni)."],"icon":"🎨"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Pithora mural painting is associated with which tribe?","options":["Gond","Bhil","Baiga","Bharia"],"correct":"Bhil","strategy":"It is a ritualistic painting of the Bhil tribe."},{"type":"exam_pattern","topic":"Tribal Culture Trend","analysis":"Competitive Exams Trend:","stats":["Paintings & Artists: 3-4 questions","Marriage & Social Customs: 2 questions","Festivals & Dances: 2-3 questions"],"trend":"Commissions are now asking about the ''symbolism'' behind arts (e.g., the significance of horses in Pithora) rather than just names."}]}', 'tribal_culture', NULL, 45, 1, 1770922139, 1770922139, 'blog', 'unit_10', 'Tribal Culture of Madhya Pradesh: Customs, Traditions, Special Arts Festivals, Dialects and Literature', 1, 0, 0, 1, 0, 'Unit 10: म.प्र. की जनजातीय संस्कृति, कला एवं साहित्य मध्य प्रदेश की जनजातीय संस्कृति विश्व की सबसे प्राचीन और समृद्ध संस्कृतियों में से एक है। यहाँ की कला केवल मनोरंजन नहीं, बल्कि जीवन जीने का एक तरीक...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('d31b2f40-9a36-4cf6-a557-ad1f2539aef4', 'tribal-heroes-freedom-struggle-mp-unit-10', 'Tribal Icons & Freedom Struggle of MP | म.प्र. के जनजातीय नायक एवं स्वतंत्रता संग्राम', 'Exhaustive guide to the contribution of Madhya Pradesh''s tribal icons in the Indian Freedom Movement. Covers Tantya Bhil, Bhima Nayak, Rani Durgavati, and more for MPPSC Unit 10.', '{"hi":[{"type":"h2","text":"Unit 10: स्वतंत्रता संग्राम में जनजातियों का योगदान एवं प्रमुख नायक"},{"type":"p","text":"मध्य प्रदेश का स्वतंत्रता संग्राम जनजातीय बलिदानों के बिना अधूरा है। 1857 की क्रांति हो या जंगल सत्याग्रह, यहाँ के जनजातीय नायकों ने अंग्रेजों की जड़ों को हिला दिया था। MPPSC में अक्सर इन व्यक्तित्वों के जन्म स्थान, उनके द्वारा लड़े गए विद्रोहों और उन्हें दी गई उपाधियों (जैसे- ''इंडियन रॉबिनहुड'') पर प्रश्न पूछे जाते हैं।"},{"type":"image_tag","content":""},{"type":"h2","text":"1. 1857 की क्रांति के प्रमुख नायक (1857 Revolt Icons)"},{"type":"table","instruction":"म.प्र. के प्रमुख जनजातीय सेनानी","head":["नायक (Hero)","कार्यक्षेत्र / जन्म","प्रमुख योगदान / तथ्य"],"body":[["टंट्या भील (Tantya Bhil)","पंधाना (खंडवा)","इन्हें ''इंडियन रॉबिनहुड'' कहा जाता है; पातालपानी में इनका समाधि स्थल है।"],["भीमा नायक (Bhima Nayak)","बड़वानी (निमाड़)","1857 की क्रांति में निमाड़ के प्रमुख नेता; इन्हें ''निमाड़ का रॉबिनहुड'' कहते हैं।"],["शंकर शाह और रघुनाथ शाह","गढ़ा मण्डला","पुत्र और पिता की जोड़ी जिन्होंने 1857 में विद्रोह का नेतृत्व किया; तोप से उड़ा दिया गया था।"],["खाज्या नायक","सेंधवा (बड़वानी)","भीमा नायक के साथी; अंग्रेजों के खिलाफ छापामार युद्ध लड़ा।"]]},{"type":"h2","text":"2. जंगल सत्याग्रह और अन्य व्यक्तित्व (Forest Satyagraha & Others)"},{"type":"p","text":"1930 के दौरान गांधीजी के आह्वान पर म.प्र. की जनजातियों ने अंग्रेजों के वन कानूनों को तोड़ा।"},{"type":"image_tag","content":"[Image showing the timeline of Tribal Revolts in Madhya Pradesh: 1857, 1930 Forest Satyagraha, and Jhabua Revolt]"},{"type":"ul","items":["**गुंजन सिंह कोरकू:** 1930 के ''घोड़ाडोंगरी'' (बैतूल) जंगल सत्याग्रह के प्रमुख नेता।","**बिरसा मुंडा:** हालांकि झारखंड से थे, लेकिन उनके ''उलगुलान'' विद्रोह का गहरा प्रभाव म.प्र. की सीमावर्ती जनजातियों पर रहा।","**रानी दुर्गावती:** गोंडवाना की शासिका जिन्होंने अकबर की सेना (आसफ खान) से डटकर मुकाबला किया।","**बादल भोई:** छिंदवाड़ा के प्रसिद्ध जनजातीय क्रांतिकारी; इनके नाम पर छिंदवाड़ा में जनजातीय संग्रहालय स्थित है।"]},{"type":"fact_card","title":"जनजातीय सम्मान: क्विक फैक्ट्स","facts":["हबीबगंज रेलवे स्टेशन (भोपाल) का नाम बदलकर **रानी कमलापति रेलवे स्टेशन** किया गया।","पातालपानी रेलवे स्टेशन का नाम अब **टंट्या भील रेलवे स्टेशन** है।","15 नवंबर: भगवान बिरसा मुंडा की जयंती को ''जनजातीय गौरव दिवस'' के रूप में मनाया जाता है।","म.प्र. राज्य जनजातीय संग्रहालय: श्यामला हिल्स, भोपाल में स्थित।"],"icon":"🇮🇳"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"''इंडियन रॉबिनहुड'' के नाम से कौन जाना जाता है?","options":["भीमा नायक","टंट्या भील","बिरसा मुंडा","राजा मानसिंह"],"correct":"टंट्या भील","strategy":"अंग्रेज उन्हें उनके साहस और गरीबों की मदद के कारण ''रॉबिनहुड'' कहते थे।"},{"type":"pyq","exam":"UPSC Prelims 2019","year":2019,"question":"1857 के विद्रोह के दौरान ''शंकर शाह'' का संबंध किस क्षेत्र से था?","options":["झांसी","गढ़ा मण्डला","कानपुर","जगदीशपुर"],"correct":"गढ़ा मण्डला (म.प्र.)","strategy":"शंकर शाह गोंडवाना साम्राज्य के वंशज और महान क्रांतिकारी थे।"},{"type":"pyq","exam":"BPSC Prelims 2020","year":2020,"question":"बिरसा मुंडा के अनुयायी उन्हें किसका अवतार मानते थे?","options":["धरती आबा","मरंग गोमके","सिंहबोंगा","लोकनायक"],"correct":"धरती आबा (जगत पिता)","strategy":"उन्हें ''भगवान'' और ''धरती आबा'' के रूप में पूजा जाता था।"},{"type":"pyq","exam":"UPPSC Prelims 2021","year":2021,"question":"म.प्र. में ''घोड़ाडोंगरी'' जंगल सत्याग्रह का नेतृत्व किसने किया था?","options":["गंजन सिंह कोरकू","भीमा नायक","मंसाराम","शंभू दयाल"],"correct":"गंजन सिंह कोरकू","strategy":"यह 1930 में बैतूल जिले में हुआ था।"},{"type":"exam_pattern","topic":"Tribal Icons Trend","analysis":"Competitive Exams Trend:","stats":["जन्म स्थान / समाधि स्थल: 2-3 प्रश्न","उपाधियाँ (Nicknames): 1-2 प्रश्न","प्रमुख युद्ध एवं तिथियाँ: 2 प्रश्न"],"trend":"आयोग अब केवल ''नाम'' नहीं, बल्कि उन नायकों के ''परिवार'' (जैसे शंकर शाह के पुत्र) और ''ब्रिटिश अधिकारियों'' (जिन्होंने विद्रोह को दबाया) पर भी प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 10: Tribal Contribution to Freedom Movement & Key Personalities"},{"type":"p","text":"The freedom struggle of Madhya Pradesh is incomplete without tribal sacrifices. Whether it was the 1857 Revolt or the Forest Satyagraha, tribal icons shook the foundations of British rule. MPPSC frequently asks about birthplaces, nicknames (like ''Indian Robin Hood''), and specific revolts led by these icons."},{"type":"h2","text":"1. Major Icons of 1857 Revolt"},{"type":"table","instruction":"Key Tribal Warriors of MP","head":["Hero","Region / Birth","Key Contribution / Fact"],"body":[["Tantya Bhil","Pandhana (Khandwa)","Known as ''Indian Robin Hood''; Samadhi at Patalpani."],["Bhima Nayak","Barwani (Nimar)","Known as ''Robin Hood of Nimar''; vital leader of 1857."],["Shankar Shah & Raghunath Shah","Garha Mandla","Father-son duo who led the 1857 revolt in Mandla."],["Khajya Nayak","Sendhwa (Barwani)","A close associate of Bhima Nayak; fought guerrilla warfare."]]},{"type":"h2","text":"2. Forest Satyagraha & Other Icons"},{"type":"ul","items":["**Ganjan Singh Korku:** Led the ''Ghoradongri'' (Betul) Forest Satyagraha in 1930.","**Rani Durgavati:** Brave Gondwana ruler who fought Akbar''s general, Asaf Khan.","**Badal Bhoi:** A legendary tribal revolutionary from Chhindwara; a museum is named after him in Chhindwara.","**Rani Kamlapati:** The last Gond Queen of Bhopal, known for her administrative skills and valor."]},{"type":"fact_card","title":"Tribal Pride: Quick Facts","facts":["Habibganj Station (Bhopal) renamed to **Rani Kamlapati Railway Station**.","Patalpani Station renamed to **Tantya Bhil Railway Station**.","Nov 15: Celebrated as ''Janjatiya Gaurav Divas'' (Tribal Pride Day) on Birsa Munda’s birth anniversary.","MP Tribal Museum: Located at Shyamla Hills, Bhopal."],"icon":"🇮🇳"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Who is known as the ''Indian Robin Hood''?","options":["Bhima Nayak","Tantya Bhil","Birsa Munda","Raja Mansingh"],"correct":"Tantya Bhil","strategy":"The British termed him so due to his guerrilla tactics and service to the poor."},{"type":"exam_pattern","topic":"Tribal Icons Trend","analysis":"Competitive Exams Trend:","stats":["Birth/Death Places: 2-3 questions","Nicknames: 1-2 questions","Battles & Dates: 2 questions"],"trend":"Commissions are now asking about the family lineages of icons and the specific British officers who led the suppression of these tribal revolts."}]}', 'tribal_history', NULL, 45, 1, 1770922193, 1770922193, 'blog', 'unit_10', 'Contribution to Freedom Movement & Tribal Personalities of MP', 1, 0, 0, 1, 0, 'Unit 10: स्वतंत्रता संग्राम में जनजातियों का योगदान एवं प्रमुख नायक मध्य प्रदेश का स्वतंत्रता संग्राम जनजातीय बलिदानों के बिना अधूरा है। 1857 की क्रांति हो या जंगल सत्याग्रह, यहाँ के जनजातीय नायकों ने...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('077807ab-f1db-4ee6-9051-7a37caf466f5', 'tribal-institutes-museums-publications-mp-unit-10', 'Tribal Institutes, Museums & Publications of MP | म.प्र. के जनजातीय संस्थान, संग्रहालय एवं प्रकाशन', 'Exhaustive list of major tribal research institutes, museums like Badal Bhoi and Indira Gandhi Manav Sangrahalaya, and key publications for MPPSC Unit 10.', '{"hi":[{"type":"h2","text":"Unit 10: जनजातीय संस्थान, संग्रहालय एवं महत्वपूर्ण प्रकाशन"},{"type":"p","text":"जनजातीय विरासत को सहेजने के लिए मध्य प्रदेश में कई विशिष्ट संस्थान और संग्रहालय कार्यरत हैं। ये संस्थान न केवल अनुसंधान करते हैं, बल्कि पत्रिकाओं के माध्यम से जनजातीय संस्कृति का प्रचार भी करते हैं। MPPSC में अक्सर इन संस्थानों की स्थापना तिथि, उनके मुख्यालय और पत्रिकाओं के संपादकों पर प्रश्न पूछे जाते हैं।"},{"type":"h2","text":"1. जनजातीय अनुसंधान एवं प्रशिक्षण संस्थान (Research Institutes)"},{"type":"table","instruction":"प्रमुख शोध संस्थान","head":["संस्थान (Institute)","मुख्यालय (HQ)","विशेष तथ्य"],"body":[["म.प्र. जनजातीय अनुसंधान एवं विकास संस्थान","भोपाल","स्थापना 1954 (छिंदवाड़ा में, 1965 में भोपाल स्थानांतरित)।"],["जनजातीय प्रकोष्ठ (Tribal Cell)","राजभवन, भोपाल","राज्यपाल की अध्यक्षता में जनजातीय हितों की निगरानी।"],["वन्य (Vanya) संस्थान","भोपाल","जनजातीय संस्कृति के प्रचार-प्रसार हेतु नोडल एजेंसी।"],["आदिवासी लोक कला एवं बोली अकादमी","भोपाल","स्थापना 1980; जनजातीय कला और बोलियों का संरक्षण।"]]},{"type":"h2","text":"2. प्रमुख जनजातीय संग्रहालय (Major Museums)"},{"type":"p","text":"ये संग्रहालय जनजातीय जीवन की जीती-जागती तस्वीर पेश करते हैं।"},{"type":"image_tag","content":""},{"type":"table","instruction":"प्रमुख संग्रहालय एवं स्थान","head":["संग्रहालय (Museum)","स्थान (Location)","महत्व"],"body":[["बादल भोई जनजातीय संग्रहालय","छिंदवाड़ा","म.प्र. का सबसे पुराना जनजातीय संग्रहालय (1954)।"],["म.प्र. जनजातीय संग्रहालय","भोपाल","श्यामला हिल्स; यहाँ जनजातीय आवासों का सजीव चित्रण है।"],["इन्दिरा गांधी राष्ट्रीय मानव संग्रहालय","भोपाल","देश का सबसे बड़ा मानव विज्ञान संग्रहालय (1985)।"],["रानी दुर्गावती संग्रहालय","जबलपुर","गोंडवाना रानी की स्मृति और जनजातीय कलाकृतियों हेतु।"],["आदिवासी संग्रहालय","पातालकोट/चौरई","भारिया जनजाति की विशिष्ट संस्कृति के संरक्षण हेतु।"]]},{"type":"h2","text":"3. महत्वपूर्ण प्रकाशन एवं पत्रिकाएं (Publications)"},{"type":"ul","items":["**वन्यमन (Vanyaman):** ''वन्य'' संस्थान द्वारा प्रकाशित होने वाली प्रमुख त्रैमासिक पत्रिका।","**चौमासा (Chaumasa):** आदिवासी लोक कला अकादमी द्वारा प्रकाशित साहित्य और कला की पत्रिका।","**आदिवासी शब्दकोश:** भीली, गोंडी और कोरकू बोलियों के संरक्षण हेतु तैयार किए गए डिजिटल शब्दकोश।","**वृत्तांत:** जनजातीय नायकों के जीवन पर आधारित विशेष प्रकाशन।"]},{"type":"fact_card","title":"एग्जाम स्पेशल: म.प्र. की पहल","facts":["म.प्र. जनजातीय संग्रहालय (भोपाल) की छह दीर्घाएँ जनजातीय जीवन के विभिन्न पहलुओं को दर्शाती हैं।","इन्दिरा गांधी मानव संग्रहालय भारत सरकार के संस्कृति मंत्रालय के अधीन एक स्वायत्त संस्थान है।","बादल भोई संग्रहालय का नाम 1997 में प्रसिद्ध क्रांतिकारी बादल भोई के नाम पर रखा गया था।"],"icon":"🏛️"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"मध्य प्रदेश जनजातीय संग्रहालय (Tribal Museum) कहाँ स्थित है?","options":["छिंदवाड़ा","भोपाल","जबलपुर","झाबुआ"],"correct":"भोपाल","strategy":"भोपाल में आधुनिक जनजातीय संग्रहालय है, जबकि सबसे पुराना छिंदवाड़ा में है।"},{"type":"pyq","exam":"UPSC Prelims 2017","year":2017,"question":"इन्दिरा गांधी राष्ट्रीय मानव संग्रहालय कहाँ स्थित है?","options":["कोलकाता","नई दिल्ली","भोपाल","मुम्बई"],"correct":"भोपाल","strategy":"यह संग्रहालय अपनी खुली प्रदर्शनी (Open-air exhibits) के लिए विश्व प्रसिद्ध है।"},{"type":"pyq","exam":"BPSC Prelims 2019","year":2019,"question":"आदिवासी लोक कला अकादमी की स्थापना किस वर्ष हुई थी?","options":["1970","1980","1990","2000"],"correct":"1980","strategy":"यह अकादमी भोपाल में स्थित है और ''चौमासा'' पत्रिका निकालती है।"},{"type":"pyq","exam":"UPPSC Prelims 2022","year":2022,"question":"''बादल भोई'' का संबंध किस क्षेत्र से है?","options":["जबलपुर","छिंदवाड़ा","शहडोल","मंडला"],"correct":"छिंदवाड़ा","strategy":"वे छिंदवाड़ा के महान जनजातीय क्रांतिकारी थे, जिनके नाम पर संग्रहालय भी है।"},{"type":"exam_pattern","topic":"Tribal Institutions Trend","analysis":"Competitive Exams Trend:","stats":["संग्रहालयों का स्थान एवं नाम: 2-3 प्रश्न","संस्थानों की स्थापना वर्ष: 1-2 प्रश्न","प्रमुख पत्रिकाएं एवं संपादक: 1 प्रश्न"],"trend":"आयोग अब संग्रहालयों के ''अंदरूनी दीर्घाओं'' (जैसे- जनजातीय संग्रहालय की ''लिखन्दरा'' दीर्घा) पर भी प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 10: Tribal Institutes, Museums and Publications"},{"type":"p","text":"Several specialized institutes and museums in Madhya Pradesh work to preserve tribal heritage. These organizations conduct research and promote tribal culture through various publications. In MPPSC, questions often target foundation years, headquarters, and the editors of tribal journals."},{"type":"h2","text":"1. Tribal Research and Training Institutes"},{"type":"table","instruction":"Key Research Institutes","head":["Institute","Headquarters (HQ)","Key Fact"],"body":[["MP Tribal Research & Dev Institute","Bhopal","Est. 1954 (shifted from Chhindwara to Bhopal in 1965)."],["Tribal Cell","Raj Bhavan, Bhopal","Monitors tribal interests under the Governor."],["Vanya Institute","Bhopal","Nodal agency for the promotion of tribal culture."],["Adivasi Lok Kala & Boli Academy","Bhopal","Est. 1980; preserves tribal arts and dialects."]]},{"type":"h2","text":"2. Major Tribal Museums"},{"type":"image_tag","content":""},{"type":"table","instruction":"Museums and Locations","head":["Museum","Location","Significance"],"body":[["Badal Bhoi Tribal Museum","Chhindwara","Oldest tribal museum in MP (Est. 1954)."],["MP Tribal Museum","Bhopal","Located at Shyamla Hills; famous for life-size exhibits."],["Indira Gandhi National Museum of Mankind","Bhopal","Largest anthropological museum in India (Est. 1985)."],["Rani Durgavati Museum","Jabalpur","Dedicated to Gondwana heritage and artifacts."]]},{"type":"h2","text":"3. Important Publications"},{"type":"ul","items":["**Vanyaman:** A key quarterly magazine published by the ''Vanya'' institute.","**Chaumasa:** A magazine on literature and art published by the Adivasi Lok Kala Academy.","**Tribal Dictionaries:** Digital dictionaries prepared for Bhili, Gondi, and Korku dialects.","**Vrittant:** Special publications focusing on the lives of tribal heroes."]},{"type":"fact_card","title":"Exam Special: Facts of MP","facts":["The MP Tribal Museum (Bhopal) features six galleries representing various facets of tribal life.","The Indira Gandhi Museum of Mankind is an autonomous body under the Ministry of Culture, Govt of India.","Badal Bhoi Museum was named after the legendary revolutionary Badal Bhoi in 1997."],"icon":"🏛️"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"Where is the Madhya Pradesh Tribal Museum located?","options":["Chhindwara","Bhopal","Jabalpur","Jhabua"],"correct":"Bhopal","strategy":"The modern museum is in Bhopal, while the oldest is in Chhindwara."},{"type":"exam_pattern","topic":"Tribal Institutions Trend","analysis":"Competitive Exams Trend:","stats":["Location & Names: 2-3 questions","Foundation Years: 1-2 questions","Major Journals: 1 question"],"trend":"Commissions are now exploring the ''internal galleries'' (e.g., ''Likhandra'' gallery in the Tribal Museum) in their questions."}]}', 'tribal_studies', NULL, 40, 1, 1770922224, 1770922224, 'blog', 'unit_10', 'Important Institutes, Museums and Publications related to tribes of Madhya Pradesh', 1, 0, 0, 1, 0, 'Unit 10: जनजातीय संस्थान, संग्रहालय एवं महत्वपूर्ण प्रकाशन जनजातीय विरासत को सहेजने के लिए मध्य प्रदेश में कई विशिष्ट संस्थान और संग्रहालय कार्यरत हैं। ये संस्थान न केवल अनुसंधान करते हैं, बल्कि पत्रि...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('05ba4fd7-0adb-4a85-80dc-8a8b5bf73e45', 'tribal-folk-culture-literature-mp-unit-10', 'Tribal Folk Culture & Literature of MP | म.प्र. की जनजातीय लोक संस्कृति एवं साहित्य', 'An in-depth study of Madhya Pradesh''s tribal folk music, dances, dialects, and literature. Tailored for MPPSC Unit 10 (2026) with comparative PYQs from various State PSCs.', '{"hi":[{"type":"h2","text":"Unit 10: म.प्र. की जनजातीय लोक संस्कृति एवं साहित्य"},{"type":"p","text":"मध्य प्रदेश की जनजातीय लोक संस्कृति यहाँ की मिट्टी की सुंगध और परंपराओं का जीवंत दस्तावेज़ है। यह संस्कृति मुख्य रूप से ''मौखिक'' (Oral) रूप में एक पीढ़ी से दूसरी पीढ़ी तक पहुँची है। इसमें संगीत, नृत्य, बोलियाँ और लोककथाओं का एक अनूठा संगम है। MPPSC 2026 के नए सिलेबस के अनुसार, जनजातीय बोलियों और उनके साहित्यकारों पर विशेष ध्यान देना अनिवार्य है।"},{"type":"h2","text":"1. जनजातीय लोक नृत्य (Tribal Folk Dances)"},{"type":"p","text":"जनजातीय नृत्य केवल मनोरंजन नहीं, बल्कि प्रकृति और देवी-देवताओं की आराधना का माध्यम हैं।"},{"type":"image_tag","content":""},{"type":"table","instruction":"प्रमुख जनजातीय नृत्य और उनसे संबंधित जनजातियाँ","head":["नृत्य (Dance)","जनजाति (Tribe)","विशेषता"],"body":[["कर्मा (Karma)","गोंड, बैगा, कोल","लोक नृत्यों का राजा; प्रकृति पूजा से संबंधित।"],["सैला (Saila)","गोंड","डंडों के साथ किया जाने वाला पुरुष प्रधान नृत्य।"],["रीना (Reena)","गोंड, बैगा","दीपावली के बाद महिलाओं द्वारा किया जाने वाला नृत्य।"],["थाप्टी (Thapti)","कोरकू","चिटकोरा वाद्य यंत्र का प्रयोग।"],["भादम/सैतम","भारिया","पातालकोट क्षेत्र में प्रचलित प्रमुख नृत्य।"],["परधौनी (Pardhauni)","बैगा","बारात के स्वागत के समय किया जाने वाला नृत्य।"]]},{"type":"h2","text":"2. जनजातीय लोक संगीत एवं बोलियाँ (Music & Dialects)"},{"type":"p","text":"जनजातियों की अपनी विशिष्ट बोलियाँ हैं जो उनके साहित्य का आधार बनती हैं।"},{"type":"ul","items":["**रेलो गीत (Relo):** गोंड और मड़िया जनजाति का सबसे प्रिय लोक गीत।","**बाँसगीत (Bansgeet):** राउत और गोंड जनजातियों में प्रचलित कथात्मक गायन।","**भीली बोली:** म.प्र. में सर्वाधिक बोली जाने वाली जनजातीय बोली (इण्डो-आर्यन परिवार)।","**गोंडी बोली:** द्रविड़ भाषा परिवार से संबंधित; इसकी अपनी लिपि ''गुंजल गोंडी'' है।","**कोरकू बोली:** मुंडा (ऑस्ट्रो-एशियाटिक) भाषा परिवार का हिस्सा।"]},{"type":"h2","text":"3. जनजातीय लोक साहित्य (Folk Literature)"},{"type":"table","instruction":"साहित्यिक विधाएँ और योगदान","head":["विधा (Genre)","विवरण / उदाहरण"],"body":[["लोककथाएँ","भीलों की ''पुंजिया'' कथाएँ और गोंडों की ''पौराणिक'' गाथाएँ।"],["साहित्यिक व्यक्तित्व","भज्जू श्याम (गोंड कला एवं कथा), भूरी बाई (भीली स्मृतियाँ)।"],["विदेशी योगदान","वेरियर एल्विन (Verrier Elwin) - इन्होंने ''द बैगा'' और ''द अगरिया'' पुस्तकें लिखीं।"],["अनुष्ठानिक गीत","विवाह, जन्म और मृत्यु के अवसर पर गाए जाने वाले विशिष्ट मंगल गीत।"]]},{"type":"fact_card","title":"कला और हस्तशिल्प: क्विक बाइट्स","facts":["गोदना (Tattooing): बैगा जनजाति विश्व की सबसे अधिक गोदना प्रिय जनजाति है।","कंगी कला (Comb Art): बंजारा जनजाति को कंगी के आविष्कार का श्रेय दिया जाता है।","भरम/सेतम: भारिया जनजाति के विवाह और उत्सवों के प्रमुख वाद्य यंत्र।","चिह्न (Totem): हर जनजातीय गोत्र का अपना एक पवित्र चिह्न होता है जिसे ''टोटम'' कहते हैं।"],"icon":"🎨"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"''कर्मा'' नृत्य किस जनजाति से संबंधित है?","options":["भील","गोंड","कोरकू","सहरिया"],"correct":"गोंड (एवं बैगा)","strategy":"विकल्पों में गोंड/बैगा प्रमुखता से कर्मा के लिए जाने जाते हैं।"},{"type":"pyq","exam":"UPSC Prelims 2015","year":2015,"question":"भारत की किस जनजाति में ''बहुपति प्रथा'' (Polyandry) पाई जाती है?","options":["गोंड","नागा","जौनसारी/टोडा","भील"],"correct":"जौनसारी/टोडा","strategy":"यह प्रश्न जनजातीय सामाजिक संरचना (Customs) की विविधता को दर्शाता है।"},{"type":"pyq","exam":"UPPSC Prelims 2020","year":2020,"question":"प्रसिद्ध पुस्तक ''द बैगा'' (The Baiga) के लेखक कौन हैं?","options":["एम.एन. श्रीनिवास","वेरियर एल्विन","हर्बर्ट रिजले","डी.एन. मजूमदार"],"correct":"वेरियर एल्विन","strategy":"एल्विन ने मध्य भारत की जनजातियों पर गहन शोध किया था।"},{"type":"pyq","exam":"BPSC Prelims 2018","year":2018,"question":"मुंडा (Munda) भाषा परिवार का संबंध किससे है?","options":["द्रविड़","इण्डो-आर्यन","ऑस्ट्रो-एशियाटिक","चीनी-तिब्बती"],"correct":"ऑस्ट्रो-एशियाटिक","strategy":"म.प्र. की कोरकू जनजाति इसी परिवार की भाषा बोलती है।"},{"type":"exam_pattern","topic":"Folk Culture Trend","analysis":"Competitive Exams Trend:","stats":["लोक नृत्य एवं त्यौहार: 3-4 प्रश्न","भाषा एवं बोलियाँ: 2 प्रश्न","प्रसिद्ध पुस्तकें एवं लेखक: 1-2 प्रश्न"],"trend":"आयोग अब केवल नृत्य का नाम नहीं, बल्कि नृत्य में प्रयुक्त होने वाले ''वाद्य यंत्रों'' (Instruments) पर अधिक गहराई से प्रश्न पूछ रहा है।"}],"en":[{"type":"h2","text":"Unit 10: Tribal Folk Culture and Literature of MP"},{"type":"p","text":"The tribal folk culture of Madhya Pradesh is a living testament to the soil''s heritage. Primarily an oral tradition, it blends music, dance, dialects, and folklore. For MPPSC 2026, special focus on tribal dialects and their literary contributors is essential."},{"type":"h2","text":"1. Tribal Folk Dances"},{"type":"table","instruction":"Major Tribal Dances and Tribes","head":["Dance","Tribe","Significance"],"body":[["Karma","Gond, Baiga, Kol","The ''King of Folk Dances''; related to nature worship."],["Saila","Gond","A stick dance performed primarily by men."],["Reena","Gond, Baiga","Performed by women after the Diwali festival."],["Thapti","Korku","Accompanied by the ''Chitkora'' instrument."],["Pardhauni","Baiga","Performed to welcome the wedding procession."],["Bhadam","Bharia","Prominent in the Patalkot region."]]},{"type":"image_tag","content":""},{"type":"h2","text":"2. Tribal Dialects & Music"},{"type":"ul","items":["**Relo Songs:** The most beloved folk song of the Gond and Mariya tribes.","**Bansgeet:** Narrative singing prevalent among the Gond and Raut tribes.","**Bhili Dialect:** The most spoken tribal dialect in MP (Indo-Aryan family).","**Gondi Dialect:** Belongs to the Dravidian family; uses the ''Gunjal Gondi'' script.","**Korku Dialect:** Part of the Munda (Austro-Asiatic) language family."]},{"type":"fact_card","title":"Arts & Crafts Quick Bites","facts":["Tattooing (Godna): The Baiga tribe is the most tattoo-loving tribe globally.","Comb Art: The Banjara tribe is credited with the invention of the comb.","Totem: Every tribal clan has a sacred symbol known as a ''Totem''.","Vanya: The nodal agency for documenting tribal oral literature in MP."],"icon":"🎨"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims 2021","year":2021,"question":"The ''Karma'' dance is associated with which tribe?","options":["Bhil","Gond","Korku","Sahariya"],"correct":"Gond (and Baiga)","strategy":"Gond and Baiga are the primary practitioners of Karma in MP."},{"type":"pyq","exam":"UPPSC Prelims 2020","year":2020,"question":"Who is the author of the book ''The Baiga''?","options":["M.N. Srinivas","Verrier Elwin","Herbert Risley","D.N. Majumdar"],"correct":"Verrier Elwin","strategy":"Elwin conducted extensive research on Central Indian tribes."}]}', 'tribal_culture', NULL, 45, 1, 1770922268, 1770922268, 'blog', 'unit_10', 'Folk Culture and Literature of Madhya Pradesh', 1, 0, 0, 1, 0, 'Unit 10: म.प्र. की जनजातीय लोक संस्कृति एवं साहित्य मध्य प्रदेश की जनजातीय लोक संस्कृति यहाँ की मिट्टी की सुंगध और परंपराओं का जीवंत दस्तावेज़ है। यह संस्कृति मुख्य रूप से ''मौखिक'' (Oral) रूप में एक पी...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('c6b1c52f-8a76-4c9a-8d96-887d81edbc3f', 'national-parks-tiger-reserves-mppsc-india', 'National Parks & Tiger Reserves: MP & India | राष्ट्रीय उद्यान एवं टाइगर रिजर्व: म.प्र. और भारत', 'Comprehensive guide to National Parks and Tiger Reserves in Madhya Pradesh and India. Includes latest data (2025-26), MP-specific facts, and PYQs from MPPSC, UPSC, and other State PSCs.', '{"hi":{"introduction":"मध्य प्रदेश को ''टाइगर स्टेट'', ''लेपर्ड स्टेट'' और ''घड़ियाल स्टेट'' के नाम से जाना जाता है। MPPSC की परीक्षा में वन और वन्यजीव (Unit 3 और Unit 7) सबसे महत्वपूर्ण टॉपिक हैं। नवीनतम आंकड़ों (2025-26) के अनुसार, मध्य प्रदेश में सबसे अधिक राष्ट्रीय उद्यान और टाइगर रिजर्व हैं। इस ब्लॉग में हम न केवल म.प्र. बल्कि भारत के प्रमुख संरक्षित क्षेत्रों का परीक्षा की दृष्टि से विश्लेषण करेंगे।","blocks":[{"type":"h2","text":"1. मध्य प्रदेश के राष्ट्रीय उद्यान (National Parks of MP)"},{"type":"p","text":"मध्य प्रदेश में कुल 11 राष्ट्रीय उद्यान हैं। पालनपुर-कूनो और ओंकारेश्वर के जुड़ने के बाद यह संख्या और महत्व बढ़ गया है।"},{"type":"image_tag","content":""},{"type":"table","head":["राष्ट्रीय उद्यान","जिला","स्थापना वर्ष","मुख्य तथ्य (Exam Special)"],"body":[["कान्हा किसली","मंडला-बालाघाट","1955","सबसे बड़ा (940 वर्ग किमी), ''भूरसिंह द बारहसिंघा'' शुभंकर (Mascot) वाला एकमात्र पार्क।"],["बांधवगढ़","उमरिया","1968","32 पहाड़ियों से घिरा, सर्वाधिक बाघ घनत्व (Tiger Density)।"],["माधव","शिवपुरी","1958","जॉर्ज कैसल भवन, NH-46 (पुराना NH-3) यहाँ से गुजरता है।"],["पन्ना","पन्ना-छतरपुर","1981","रेप्टाइल पार्क, केन नदी (पन्ना की जीवनरेखा)।"],["सतपुड़ा","नर्मदापुरम","1981","कृष्ण मृग (Blackbuck) और धूपगढ़ चोटी इसी क्षेत्र में है।"],["पेंच (इंदिरा प्रियदर्शनी)","सिवनी-छिंदवाड़ा","1975","मोगली लैंड, रूडयार्ड किपलिंग की ''द जंगल बुक'' की प्रेरणा।"],["संजय-डुबरी","सीधी","1981","अविभाजित म.प्र. का सबसे बड़ा था, अब छत्तीसगढ़ में ''गुरु घासीदास'' नाम से है।"],["कूनो-पालनपुर","श्योपुर","2018","अफ्रीकी चीतों का घर (Project Cheetah)।"],["जीवाश्म (Fossil)","डिंडोरी","1983","म.प्र. का सबसे छोटा राष्ट्रीय उद्यान (0.27 वर्ग किमी)।"],["डायनासोर जीवाश्म","धार","2010","डायनासोर के अंडे और जीवाश्म संरक्षित।"],["वन विहार","भोपाल","1979","शहर के बीचों-बीच स्थित, आधुनिक चिड़ियाघर (Modern Zoo)।"]],"instruction":"नोट: ओंकारेश्वर (खंडवा) प्रस्तावित/निर्माणाधीन श्रेणी में आता है, आधिकारिक रूप से संचालित 11 मुख्य हैं।"},{"type":"h2","text":"2. मध्य प्रदेश के टाइगर रिजर्व (Tiger Reserves in MP)"},{"type":"highlight","level":"critical","text":"मध्य प्रदेश में कुल 7 टाइगर रिजर्व हैं (6 राष्ट्रीय उद्यान + 1 अभयारण्य)। वीरांगना दुर्गावती (सागर/दमोह) नवीनतम (7वां) टाइगर रिजर्व बना है।","icon":"🐅"},{"type":"ul","items":["कान्हा किसली (1974 में प्रोजेक्ट टाइगर में शामिल)","पेंच (1992)","बांधवगढ़ (1993)","पन्ना (1994)","सतपुड़ा (1999)","संजय-डुबरी (2008)","वीरांगना दुर्गावती (2023 - नवीनतम)"]},{"type":"mnemonic","topic":"MP Tiger Reserves","visual":"🐯","trick":"Kanhaiya Pen Bandh kar Panna gaya, Satpura me Sanjay aur Durga mile.","explanation":"Kanhaiya (Kanha), Pen (Pench), Bandh (Bandhavgarh), Panna, Satpura, Sanjay, Durga (Veerangana Durgawati)."},{"type":"h2","text":"3. भारत के प्रमुख राष्ट्रीय उद्यान (Exam Favorites)"},{"type":"image_tag","content":""},{"type":"table","head":["राज्य","प्रमुख राष्ट्रीय उद्यान","विशेषता"],"body":[["उत्तराखंड","जिम कॉर्बेट (रामगंगा)","भारत का पहला राष्ट्रीय उद्यान (1936)।"],["लद्दाख","हेमिस (Hemis)","भारत का सबसे बड़ा राष्ट्रीय उद्यान (हिम तेंदुए)।"],["मणिपुर","केबुल लामजाओ","विश्व का एकमात्र तैरता हुआ (Floating) राष्ट्रीय उद्यान (लोकटक झील)।"],["राजस्थान","केवलादेव (घाना)","पक्षी अभयारण्य (साइबेरियन क्रेन)।"],["असम","काजीरंगा","एक सींग वाला गैंडा (One-horned Rhino)।"],["गुजरात","गिर (Gir)","एशियाई बब्बर शेर (Asiatic Lions)।"]]},{"type":"exam_pattern","topic":"Environment & Ecology Analysis","analysis":"MPPSC और अन्य परीक्षाओं में रुझान","stats":["MPPSC: 3-4 प्रश्न (म.प्र. के विशिष्ट पार्कों से)","UPSC/UPPSC: 2 प्रश्न (मैपिंग और प्रजातियों से)","टाइगर रिजर्व: नवीनतम घोषणाओं पर प्रश्न (जैसे 54वां या 55वां रिजर्व)।"],"trend":"अब प्रश्न केवल ''स्थान'' नहीं पूछते, बल्कि ''किस नदी के किनारे है'' या ''कौन सा जानवर विशिष्ट है'' या ''NH कौन सा गुजरता है'' पर फोकस कर रहे हैं।"},{"type":"h2","text":"Previous Year Questions (PYQs) - All India Analysis"},{"type":"pyq","exam":"MPPSC Prelims","year":2023,"question":"निम्नलिखित में से किस राष्ट्रीय उद्यान में ''भूरसिंह द बारहसिंघा'' शुभंकर अपनाया गया है?","options":["कान्हा किसली","पेंच","बांधवगढ़","सतपुड़ा"],"correct":"कान्हा किसली","strategy":"रोहन चक्रवर्ती ने इसे डिजाइन किया था। यह भारत का पहला पार्क है जिसका अपना शुभंकर है।"},{"type":"pyq","exam":"UPSC Prelims","year":2020,"question":"निम्नलिखित में से कौन सा राष्ट्रीय उद्यान पूरी तरह से शीतोष्ण (Temperate) अल्पाइन क्षेत्र में स्थित है?","options":["मानस राष्ट्रीय उद्यान","नामदाफा राष्ट्रीय उद्यान","न्योरा घाटी राष्ट्रीय उद्यान"," फूलों की घाटी राष्ट्रीय उद्यान"],"correct":"फूलों की घाटी राष्ट्रीय उद्यान","strategy":"फूलों की घाटी (उत्तराखंड) उच्च ऊंचाई पर स्थित है, जो अल्पाइन क्षेत्र है।"},{"type":"pyq","exam":"UPPSC Prelims","year":2021,"question":"भारत में ''प्रोजेक्ट टाइगर'' किस वर्ष शुरू किया गया था?","options":["1970","1972","1973","1980"],"correct":"1973","strategy":"कैलाश सांखला (टाइगर मैन ऑफ इंडिया) के नेतृत्व में 1 अप्रैल 1973 को जिम कॉर्बेट से शुरू हुआ।"},{"type":"pyq","exam":"BPSC Prelims","year":2022,"question":"वाल्मीकि टाइगर रिजर्व किस राज्य में स्थित है?","options":["उत्तर प्रदेश","बिहार","मध्य प्रदेश","झारखंड"],"correct":"बिहार","strategy":"वाल्मीकि बिहार का एकमात्र टाइगर रिजर्व है (पश्चिमी चंपारण)।"}],"conclusion":"राष्ट्रीय उद्यान और टाइगर रिजर्व MPPSC का एक ''Sure Shot'' टॉपिक है। आपको म.प्र. के पार्कों की स्थापना वर्ष, जिले और विशेष जानवर याद रखने चाहिए। साथ ही, भारत के नवीनतम टाइगर रिजर्व (जैसे धौलपुर-करौली, रानीपुर आदि) पर नज़र रखें।"},"en":{"introduction":"Madhya Pradesh is famously known as the ''Tiger State'', ''Leopard State'', and ''Gharial State''. In the MPPSC exam, Forest and Wildlife (Unit 3 and Unit 7) are the most critical topics. According to the latest data (2025-26), Madhya Pradesh has the highest number of National Parks and Tiger Reserves. This blog analyzes key protected areas of India and MP from an exam perspective.","blocks":[{"type":"h2","text":"1. National Parks of Madhya Pradesh"},{"type":"p","text":"There are 11 operational National Parks in Madhya Pradesh. With the addition of Palanpur-Kuno and Omkareshwar, the significance has increased."},{"type":"image_tag","content":""},{"type":"table","head":["National Park","District","Est. Year","Key Facts (Exam Special)"],"body":[["Kanha Kisli","Mandla-Balaghat","1955","Largest (940 sq km), Only park with a mascot ''Bhoorsingh the Barasingha''."],["Bandhavgarh","Umaria","1968","Surrounded by 32 hills, Highest Tiger Density."],["Madhav","Shivpuri","1958","George Castle building, NH-46 (Old NH-3) passes through it."],["Panna","Panna-Chhatarpur","1981","Reptile Park, Ken River (Lifeline of Panna)."],["Satpura","Narmadapuram","1981","Blackbuck habitat, Dhoopgarh peak is located here."],["Pench (Indira Priyadarshini)","Seoni-Chhindwara","1975","Mowgli Land, Inspiration for Rudyard Kipling''s ''The Jungle Book''."],["Sanjay-Dubri","Sidhi","1981","Was the largest in undivided MP; part in CG is called ''Guru Ghasidas''."],["Kuno-Palanpur","Sheopur","2018","Home of African Cheetahs (Project Cheetah)."],["Fossil","Dindori","1983","Smallest National Park in MP (0.27 sq km)."],["Dinosaur Fossil","Dhar","2010","Preserves Dinosaur eggs and fossils."],["Van Vihar","Bhopal","1979","Located in the city center, functions as a Modern Zoo."]],"instruction":"Note: Omkareshwar (Khandwa) falls under proposed/under-construction category; 11 are officially operational."},{"type":"h2","text":"2. Tiger Reserves in Madhya Pradesh"},{"type":"highlight","level":"critical","text":"MP has a total of 7 Tiger Reserves (6 National Parks + 1 Sanctuary). Veerangana Durgawati (Sagar/Damoh) is the latest (7th) Tiger Reserve.","icon":"🐅"},{"type":"ul","items":["Kanha Kisli (Included in Project Tiger in 1974)","Pench (1992)","Bandhavgarh (1993)","Panna (1994)","Satpura (1999)","Sanjay-Dubri (2008)","Veerangana Durgawati (2023 - Latest)"]},{"type":"mnemonic","topic":"MP Tiger Reserves","visual":"🐯","trick":"Kanhaiya Pen Bandh kar Panna gaya, Satpura me Sanjay aur Durga mile.","explanation":"Kanhaiya (Kanha), Pen (Pench), Bandh (Bandhavgarh), Panna, Satpura, Sanjay, Durga (Veerangana Durgawati)."},{"type":"h2","text":"3. Major National Parks of India (Exam Favorites)"},{"type":"image_tag","content":""},{"type":"table","head":["State","Major National Park","Speciality"],"body":[["Uttarakhand","Jim Corbett (Ramganga)","First National Park of India (1936)."],["Ladakh","Hemis","Largest National Park in India (Snow Leopards)."],["Manipur","Keibul Lamjao","World''s only Floating National Park (Loktak Lake)."],["Rajasthan","Keoladeo (Ghana)","Bird Sanctuary (Siberian Crane)."],["Assam","Kaziranga","One-horned Rhino."],["Gujarat","Gir","Asiatic Lions."]]},{"type":"exam_pattern","topic":"Environment & Ecology Analysis","analysis":"Trends in MPPSC & Other Exams","stats":["MPPSC: 3-4 Questions (Specific to MP Parks)","UPSC/UPPSC: 2 Questions (Mapping & Species)","Tiger Reserves: Questions on latest notifications (e.g., 54th or 55th Reserve)."],"trend":"Questions now focus not just on ''Location'' but on ''Rivers flowing through'', ''Flagship Species'', or ''National Highways passing through''."},{"type":"h2","text":"Previous Year Questions (PYQs) - All India Analysis"},{"type":"pyq","exam":"MPPSC Prelims","year":2023,"question":"Which of the following National Parks has adopted ''Bhoorsingh the Barasingha'' as a mascot?","options":["Kanha Kisli","Pench","Bandhavgarh","Satpura"],"correct":"Kanha Kisli","strategy":"Designed by Rohan Chakravarty. It is the first park in India to have a mascot."},{"type":"pyq","exam":"UPSC Prelims","year":2020,"question":"Which of the following National Parks lies completely in the Temperate Alpine zone?","options":["Manas National Park","Namdapha National Park","Neora Valley National Park","Valley of Flowers National Park"],"correct":"Valley of Flowers National Park","strategy":"Valley of Flowers (Uttarakhand) is located at a high altitude, which is an Alpine zone."},{"type":"pyq","exam":"UPPSC Prelims","year":2021,"question":"In which year was ''Project Tiger'' launched in India?","options":["1970","1972","1973","1980"],"correct":"1973","strategy":"Launched on April 1, 1973, from Jim Corbett under the leadership of Kailash Sankhala."},{"type":"pyq","exam":"BPSC Prelims","year":2022,"question":"Valmiki Tiger Reserve is located in which state?","options":["Uttar Pradesh","Bihar","Madhya Pradesh","Jharkhand"],"correct":"Bihar","strategy":"Valmiki is the only Tiger Reserve in Bihar (West Champaran)."}],"conclusion":"National Parks and Tiger Reserves are a ''Sure Shot'' topic for MPPSC. You must remember the establishment year, district, and special animals of MP parks. Also, keep an eye on India''s latest Tiger Reserves (like Dholpur-Karauli, Ranipur, etc.)."}}', 'geography', NULL, 20, 1, 1771418779, 1771419628, 'blog', 'unit_3', 'Forest, Forest Produce, Wildlife, Rivers, Mountains and Mountain ranges of Madhya Pradesh', 0, 1, 1, 1, 0, '', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('41088a1c-beb0-4d1a-9354-fbb18bd9048f', 'how-to-crack-mppsc-prelims-2026-strategy', 'How to Crack MPPSC Prelims 2026: Ultimate Strategy | MPPSC 2026 प्रीलिम्स कैसे निकालें?', 'A step-by-step strategic guide to cracking MPPSC Prelims 2026. Includes syllabus decoding, resource management, scientific revision techniques, and the 90-day roadmap.', '{"hi":{"introduction":"MPPSC 2026 को क्रैक करना केवल ''कड़ी मेहनत'' का खेल नहीं है, बल्कि यह ''सही दिशा'' में की गई मेहनत है। 26 अप्रैल 2026 की तारीख आपके कैलेंडर में मार्क होनी चाहिए। यदि आप एक बिगिनर हैं या पहले प्रयास कर चुके हैं, तो यह ब्लॉग आपको वह ''सीक्रेट सॉस'' देगा जो टॉपर्स अपनाते हैं। यहाँ हम रटने की जगह ''स्मार्ट लर्निंग'' और ''लिमिटेड रिसोर्स'' की बात करेंगे।","blocks":[{"type":"h2","text":"1. सिलेबस को डिकोड करें (The Unit Game)"},{"type":"p","text":"MPPSC का सिलेबस 10 यूनिट्स में बंटा है। सबसे बड़ी गलती छात्र यह करते हैं कि वे हिस्ट्री और पॉलिटी के पीछे भागते हैं, जबकि सिलेक्शन ''छोटी यूनिट्स'' दिलाती हैं।"},{"type":"table","head":["प्राथमिकता (Priority)","यूनिट्स (Units)","क्यों जरूरी है?"],"body":[["Priority 1 (Game Changers)","Unit 1, 3, 5 (MP GK) + Unit 10 (Tribes)","लगभग 40-45 प्रश्न यहीं से आते हैं। म.प्र. का जीके आपकी रीढ़ की हड्डी है।"],["Priority 2 (Scoring)","Unit 9 (ICT) + Unit 7 (Science/Env)","सीमित सिलेबस, लेकिन 15-18 प्रश्न पक्के। कम मेहनत में ज्यादा मार्क्स।"],["Priority 3 (Core)","Unit 2, 4, 6 (History, Geo, Polity)","सिलेबस बहुत बड़ा है। यहाँ ''Cost-Benefit Ratio'' कम है।"],["Priority 4 (Dynamic)","Unit 8 (Current Affairs)","परीक्षा से 2 महीने पहले स्पीडी (Speedy) या तथ्य बाण से कवर करें।"]],"instruction":"रणनीति: पहले Priority 1 और 2 को मास्टर करें, फिर कोर विषयों पर जाएं।"},{"type":"image_tag","content":""},{"type":"h2","text":"2. रिसोर्स सीमित रखें (Limit Your Resources)"},{"type":"ul","items":["**MP GK:** हिंदी ग्रंथ अकादमी (प्रमाणिक) + परीक्षा धाम (रिवीजन के लिए)।","**Unit 10 (Tribes):** आयोग द्वारा जारी नई सामग्री या विशिष्ट कोचिंग नोट्स।","**Unit 9 (ICT):** निर्माण IAS या परीक्षा धाम की पतली बुकलेट।","**Core Subjects:** ल्यूसेंट (Lucent) - यह आज भी ''रामबाण'' है।","**Current Affairs:** स्पीडी (वार्षिकी) + MP का कोई भी मासिक पत्रिका।"]},{"type":"highlight","level":"critical","text":"गोल्डन रूल: 10 किताबें एक बार पढ़ने से बेहतर है, 1 किताब को 10 बार पढ़ना। अपने रिसोर्स बदलिए मत।","icon":"📚"},{"type":"h2","text":"3. वैज्ञानिक लर्निंग तकनीक (Scientific Study Techniques)"},{"type":"p","text":"सिर्फ पढ़ने से याद नहीं होगा। 2026 में नेगेटिव मार्किंग से बचने के लिए ''सटीकता'' (Accuracy) चाहिए।"},{"type":"ul","items":["**Active Recall:** पेज पढ़ने के बाद किताब बंद करें और खुद से पूछें- ''मैंने क्या पढ़ा?''।","**Spaced Repetition:** जो आज पढ़ा, उसे 24 घंटे, 3 दिन और 7 दिन बाद रिवाइज करें।","**Map Mapping:** MP की जियोग्राफी (नदियां, पर्वत, नेशनल पार्क) को खाली नक्शे (Blank Maps) पर भरकर याद करें।","**MCQ Practice:** रोजाना शाम को 50 MCQ जरूर लगाएं। इससे ''एलिमिनेशन तकनीक'' विकसित होगी।"]},{"type":"h2","text":"4. 90 दिनों का मास्टर प्लान (The Roadmap)"},{"type":"table","head":["चरण (Phase)","समय (Duration)","फोकस (Focus)"],"body":[["Phase 1: Foundation","Day 1-40","MP GK (Unit 1, 3, 5) + Unit 10 + Unit 9 पूरी तरह खत्म करें।"],["Phase 2: Core","Day 41-70","History, Polity, Geography और Science को ल्यूसेंट से कवर करें।"],["Phase 3: Revision","Day 71-90","सिर्फ मॉक टेस्ट (Full Length Tests) और करंट अफेयर्स (Unit 8)।"]],"instruction":"अंतिम 15 दिन केवल रिवीजन और पुराने पेपर्स के लिए रखें।"},{"type":"exam_pattern","topic":"Success Formula 2026","analysis":"MPPSC Prelims में सफलता का गणित","stats":["Target Score: 80+ प्रश्न सही (General Category)","MP GK: 35/35 सही करने का लक्ष्य रखें।","ICT/Tribes: 18/20 सही करने का लक्ष्य रखें।"],"trend":"नेगेटिव मार्किंग के कारण ''तुक्का'' (Guesswork) अब काम नहीं करेगा। आपको 100% श्योर वाले सवालों पर खेलना होगा।"}],"conclusion":"MPPSC 2026 एक मैराथन है, स्प्रिंट नहीं। अपनी टेबल पर एक मैप चिपकाएं, सोशल मीडिया से दूरी बनाएं और खुद पर विश्वास रखें। अगर आप MP GK और Unit 9-10 को अपनी ताकत बना लेते हैं, तो प्रीलिम्स रुकना नामुमकिन है। अभी शुरुआत करें!"},"en":{"introduction":"Cracking MPPSC 2026 is not just a game of ''Hard Work'', but ''Smart Work'' in the right direction. The date 26th April 2026 should be marked on your calendar. Whether you are a beginner or a repeater, this blog gives you the ''Secret Sauce'' used by toppers. Here, we move beyond rote memorization to ''Smart Learning'' and ''Limited Resources''.","blocks":[{"type":"h2","text":"1. Decode the Syllabus (The Unit Game)"},{"type":"p","text":"The MPPSC syllabus is divided into 10 Units. The biggest mistake aspirants make is chasing History and Polity endlessly, while selection is delivered by the ''Smaller Units''."},{"type":"table","head":["Priority","Units","Why Important?"],"body":[["Priority 1 (Game Changers)","Unit 1, 3, 5 (MP GK) + Unit 10 (Tribes)","Approx 40-45 questions come from here. MP GK is your backbone."],["Priority 2 (Scoring)","Unit 9 (ICT) + Unit 7 (Science/Env)","Limited syllabus, but 15-18 sure-shot questions. High ROI."],["Priority 3 (Core)","Unit 2, 4, 6 (History, Geo, Polity)","Syllabus is vast. The ''Cost-Benefit Ratio'' is lower here."],["Priority 4 (Dynamic)","Unit 8 (Current Affairs)","Cover via Speedy or Tathya Baan 2 months before the exam."]],"instruction":"Strategy: Master Priority 1 and 2 first, then move to core subjects."},{"type":"image_tag","content":""},{"type":"h2","text":"2. Limit Your Resources"},{"type":"ul","items":["**MP GK:** Hindi Granth Academy (Authentic) + Pariksha Dham (For revision).","**Unit 10 (Tribes):** Specialized notes or Commission''s new material.","**Unit 9 (ICT):** Nirman IAS or Pariksha Dham booklet.","**Core Subjects:** Lucent General Knowledge - Still the ''Bible'' for facts.","**Current Affairs:** Speedy (Yearly) + Any MP monthly magazine."]},{"type":"highlight","level":"critical","text":"Golden Rule: It is better to read 1 book 10 times than to read 10 books 1 time. Do not switch resources.","icon":"📚"},{"type":"h2","text":"3. Scientific Study Techniques"},{"type":"p","text":"Reading alone won''t work. To handle Negative Marking in 2026, you need ''Accuracy''."},{"type":"ul","items":["**Active Recall:** Close the book after reading a page and ask yourself - ''What did I just read?''.","**Spaced Repetition:** Revise what you read today after 24 hours, 3 days, and 7 days.","**Map Mapping:** Memorize MP Geography (Rivers, Mountains, Parks) by filling Blank Maps.","**MCQ Practice:** Solve 50 MCQs daily. This develops the ''Elimination Technique''."]},{"type":"h2","text":"4. The 90-Day Master Plan"},{"type":"table","head":["Phase","Duration","Focus"],"body":[["Phase 1: Foundation","Day 1-40","Finish MP GK (Unit 1, 3, 5) + Unit 10 + Unit 9 completely."],["Phase 2: Core","Day 41-70","Cover History, Polity, Geography, and Science via Lucent."],["Phase 3: Revision","Day 71-90","Only Full Length Mock Tests and Current Affairs (Unit 8)."]],"instruction":"Keep the last 15 days exclusively for revision and PYQs."},{"type":"exam_pattern","topic":"Success Formula 2026","analysis":"The Math of Success in MPPSC Prelims","stats":["Target Score: 80+ Correct Questions (General Category)","MP GK: Aim for 35/35 correct.","ICT/Tribes: Aim for 18/20 correct."],"trend":"Due to negative marking, ''wild guessing'' is dead. You need to play on 100% sure questions."}],"conclusion":"MPPSC 2026 is a marathon, not a sprint. Paste a map on your study table, distance yourself from social media, and believe in yourself. If you make MP GK and Unit 9-10 your strength, clearing Prelims is inevitable. Start now!"}}', 'general', NULL, 15, 1, 1771420723, 1771420776, 'blog', NULL, 'Strategy and Roadmap for MPPSC 2026 Prelims', 0, 1, 1, 1, 0, '', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('f8adc270-a5a9-4194-bff5-0ff247b8645d', 'ramsar-sites-india-mp-mppsc-2026', 'Ramsar Sites in India & MP | भारत और म.प्र. के रामसर स्थल', 'Exhaustive guide to the 98 Ramsar Sites in India and the 5 specific Ramsar sites in Madhya Pradesh (updated Feb 2026). Includes important environment days and multi-state PYQs for MPPSC Unit 7.', '{"hi":{"introduction":"आर्द्रभूमियां (Wetlands) पृथ्वी की ''किडनी'' कहलाती हैं, क्योंकि ये जल को शुद्ध करने और बाढ़ को नियंत्रित करने का कार्य करती हैं। MPPSC 2026 (यूनिट 7: पर्यावरण) के लिए ''रामसर स्थल'' सबसे ज्वलंत टॉपिक है। फरवरी 2026 तक भारत में कुल 98 रामसर स्थल घोषित किए जा चुके हैं, जिनमें से 5 मध्य प्रदेश में स्थित हैं। इस ब्लॉग में हम म.प्र. के सभी रामसर स्थलों, भारत के महत्वपूर्ण वेटलैंड्स और पर्यावरण से जुड़े प्रमुख दिवसों का विश्लेषण करेंगे।","blocks":[{"type":"h2","text":"1. रामसर कन्वेंशन: आधारभूत जानकारी (Basics of Ramsar Convention)"},{"type":"p","text":"रामसर समझौता आर्द्रभूमियों के संरक्षण के लिए एक अंतरराष्ट्रीय संधि है। 2 फरवरी 1971 को ईरान के ''रामसर'' शहर में इस पर हस्ताक्षर किए गए थे। भारत ने इस संधि पर 1 फरवरी 1982 को हस्ताक्षर किए।"},{"type":"highlight","level":"important","text":"मोंट्रेक्स रिकॉर्ड (Montreux Record): यह उन रामसर स्थलों का एक रजिस्टर है जहाँ मानवीय हस्तक्षेप के कारण पारिस्थितिक तंत्र में बदलाव आ रहा है। भारत के 2 स्थल इसमें शामिल हैं: केवलादेव (राजस्थान) और लोकटक (मणिपुर)। (चिल्का झील को इससे बाहर कर दिया गया है)।","icon":"📝"},{"type":"h2","text":"2. मध्य प्रदेश के 5 रामसर स्थल (5 Ramsar Sites of MP)"},{"type":"p","text":"मध्य प्रदेश में वर्तमान (2026) तक कुल 5 रामसर स्थल हैं। हाल ही में तवा जलाशय के जुड़ने से यह सूची अपडेट हुई है।"},{"type":"image_tag","content":""},{"type":"table","head":["रामसर स्थल","जिला","घोषित वर्ष","महत्वपूर्ण तथ्य"],"body":[["भोज वेटलैंड (Bhoj Wetland)","भोपाल","2002","म.प्र. का पहला रामसर स्थल। यह ऊपरी झील (Upper Lake) और निचली झील से मिलकर बना है।"],["साख्य सागर (Sakhya Sagar)","शिवपुरी","2022","माधव राष्ट्रीय उद्यान के अंदर स्थित है। यहाँ मगरमच्छ सफारी प्रसिद्ध है।"],["सिरपुर तालाब (Sirpur Wetland)","इंदौर","2022","इसे पक्षी अभयारण्य के रूप में भी जाना जाता है (Holkar काल में निर्मित)।"],["यशवंत सागर (Yashwant Sagar)","इंदौर","2022","गंभीर नदी पर स्थित; सारस क्रेन (Sarus Crane) के लिए प्रसिद्ध निवास स्थान।"],["तवा जलाशय (Tawa Reservoir)","नर्मदापुरम","2024","म.प्र. का 5वां और नवीनतम रामसर स्थल; सतपुड़ा टाइगर रिजर्व के पास स्थित।"]],"instruction":"MPPSC के लिए इन 5 स्थलों के जिले और घोषित होने का वर्ष कंठस्थ कर लें।"},{"type":"h2","text":"3. भारत के रामसर स्थल: एक नजर (Ramsar Sites in India: Overview)"},{"type":"p","text":"फरवरी 2026 तक भारत का रामसर नेटवर्क 98 स्थलों तक पहुँच गया है, जो सतत विकास और आर्द्रभूमि संरक्षण के प्रति भारत की प्रतिबद्धता को दर्शाता है।"},{"type":"image_tag","content":""},{"type":"ul","items":["**सर्वाधिक रामसर स्थल:** तमिलनाडु और उत्तर प्रदेश भारत में सबसे अधिक रामसर स्थलों वाले राज्य हैं।","**सबसे बड़ा रामसर स्थल:** सुंदरबन वेटलैंड (पश्चिम बंगाल)।","**सबसे छोटा रामसर स्थल:** रेणुका वेटलैंड (हिमाचल प्रदेश)।","**भारत का पहला रामसर स्थल:** चिल्का झील (ओडिशा) और केवलादेव राष्ट्रीय उद्यान (राजस्थान) को 1981 में एक साथ घोषित किया गया था।"]},{"type":"h2","text":"4. महत्वपूर्ण पर्यावरण दिवस (Important Environment Days)"},{"type":"table","head":["दिवस (Day)","तिथि (Date)","मुख्य विषय / फोकस"],"body":[["विश्व आर्द्रभूमि दिवस","2 फरवरी","1971 के रामसर सम्मेलन की वर्षगांठ।"],["विश्व वानिकी दिवस","21 मार्च","वनों के महत्व और संरक्षण के लिए।"],["विश्व जल दिवस","22 मार्च","मीठे पानी (Freshwater) के महत्व पर ध्यान।"],["पृथ्वी दिवस (Earth Day)","22 अप्रैल","पर्यावरण संरक्षण के लिए वैश्विक समर्थन।"],["अंतर्राष्ट्रीय जैव विविधता दिवस","22 मई","जैव विविधता के मुद्दों पर समझ बढ़ाना।"],["विश्व पर्यावरण दिवस","5 जून","UNEP की स्थापना (1972) की स्मृति में।"],["विश्व ओजोन दिवस","16 सितंबर","मॉन्ट्रियल प्रोटोकॉल (1987) पर हस्ताक्षर की याद में।"]]},{"type":"exam_pattern","topic":"Environment & Ramsar Trend","analysis":"MPPSC 2026 के लिए रुझान","stats":["म.प्र. के रामसर स्थल (मैचिंग): 1-2 प्रश्न","पर्यावरण दिवस और थीम: 1 प्रश्न","मोंट्रेक्स रिकॉर्ड / भारत के प्रथम/सबसे बड़े स्थल: 1 प्रश्न"],"trend":"आयोग अब केवल नाम नहीं पूछता, बल्कि वेटलैंड के ''जल स्रोत'' (जैसे यशवंत सागर - गंभीर नदी) या उसके ''भौगोलिक स्थान'' (राष्ट्रीय उद्यान के अंदर) पर सवाल बना रहा है।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims","year":2022,"question":"मध्य प्रदेश का पहला रामसर स्थल कौन सा है?","options":["साख्य सागर","सिरपुर तालाब","भोज वेटलैंड","यशवंत सागर"],"correct":"भोज वेटलैंड","strategy":"भोज वेटलैंड को 2002 में घोषित किया गया था, बाकी तीन 2022 में शामिल हुए।"},{"type":"pyq","exam":"UPSC Prelims","year":2019,"question":"निम्नलिखित में से कौन सा रामसर स्थल ''मोंट्रेक्स रिकॉर्ड'' (Montreux Record) में शामिल है?","options":["चिल्का झील","केवलादेव राष्ट्रीय उद्यान","अष्टमुडी झील","वुलर झील"],"correct":"केवलादेव राष्ट्रीय उद्यान","strategy":"वर्तमान में भारत के केवल 2 स्थल मोंट्रेक्स रिकॉर्ड में हैं: केवलादेव और लोकटक। चिल्का झील को 2002 में इससे बाहर निकाल दिया गया था।"},{"type":"pyq","exam":"UPPSC Prelims","year":2021,"question":"विश्व ओजोन दिवस कब मनाया जाता है?","options":["16 सितंबर","21 मार्च","5 जून","22 अप्रैल"],"correct":"16 सितंबर","strategy":"यह मॉन्ट्रियल प्रोटोकॉल के उपलक्ष्य में मनाया जाता है, जो ओजोन क्षरण को रोकने के लिए था।"},{"type":"pyq","exam":"BPSC Prelims","year":2020,"question":"भारत में सबसे बड़ा रामसर स्थल कौन सा है?","options":["वेम्बनाड कोल आर्द्रभूमि","चिल्का झील","सुंदरबन आर्द्रभूमि","कोल्लेरू झील"],"correct":"सुंदरबन आर्द्रभूमि","strategy":"सुंदरबन (पश्चिम बंगाल) 4230 वर्ग किमी के साथ भारत का सबसे बड़ा रामसर स्थल है।"}],"conclusion":"रामसर स्थल और पर्यावरण दिवस MPPSC के लिए अत्यधिक स्कोरिंग विषय हैं। भारत के 98 रामसर स्थलों में से म.प्र. के 5 स्थलों (विशेषकर हाल ही में जुड़े तवा जलाशय) की लोकेशन और नदियां मैप पर जरूर मार्क कर लें।"},"en":{"introduction":"Wetlands are called the ''Kidneys of the Earth'' as they act as natural water purifiers and flood controllers. For MPPSC 2026 (Unit 7: Environment), ''Ramsar Sites'' is the most burning topic. As of February 2026, India has a total of 98 Ramsar Sites, highlighting its commitment to wetland protection, out of which 5 are located in Madhya Pradesh. In this blog, we will analyze all MP Ramsar sites, major Indian wetlands, and key environment days.","blocks":[{"type":"h2","text":"1. Ramsar Convention: The Basics"},{"type":"p","text":"The Ramsar Convention is an international treaty for the conservation of wetlands. It was signed on 2 February 1971 in the Iranian city of ''Ramsar''. India signed this treaty on 1 February 1982."},{"type":"highlight","level":"important","text":"Montreux Record: It is a register of wetland sites on the Ramsar List where ecological changes have occurred due to human interference. Currently, 2 Indian sites are on it: Keoladeo (Rajasthan) and Loktak (Manipur). (Chilka Lake was removed from it).","icon":"📝"},{"type":"h2","text":"2. The 5 Ramsar Sites of Madhya Pradesh"},{"type":"p","text":"As of 2026, Madhya Pradesh has a total of 5 Ramsar sites. The list was recently updated with the inclusion of the Tawa Reservoir."},{"type":"image_tag","content":""},{"type":"table","head":["Ramsar Site","District","Declared Year","Important Facts"],"body":[["Bhoj Wetland","Bhopal","2002","1st Ramsar site of MP. It consists of the Upper Lake and Lower Lake."],["Sakhya Sagar","Shivpuri","2022","Located inside Madhav National Park. Famous for crocodile safari."],["Sirpur Wetland","Indore","2022","Also known as a Bird Sanctuary (built during the Holkar era)."],["Yashwant Sagar","Indore","2022","Located on the Gambhir River; famous habitat for the Sarus Crane."],["Tawa Reservoir","Narmadapuram","2024","The 5th and newest Ramsar site of MP; located near Satpura Tiger Reserve."]],"instruction":"For MPPSC, memorize the districts and declaration years of these 5 sites perfectly."},{"type":"h2","text":"3. Ramsar Sites in India: An Overview"},{"type":"p","text":"By February 2026, India''s Ramsar network has reached 98 sites, reflecting the country’s strong commitment to sustainable development and wetland conservation."},{"type":"image_tag","content":""},{"type":"ul","items":["**Maximum Ramsar Sites:** Tamil Nadu and Uttar Pradesh lead the tally in India.","**Largest Ramsar Site:** Sundarbans Wetland (West Bengal).","**Smallest Ramsar Site:** Renuka Wetland (Himachal Pradesh).","**First Ramsar Sites of India:** Chilika Lake (Odisha) and Keoladeo National Park (Rajasthan) were jointly declared in 1981."]},{"type":"h2","text":"4. Important Environment Days"},{"type":"table","head":["Day","Date","Main Focus / Theme Origin"],"body":[["World Wetlands Day","February 2","Anniversary of the 1971 Ramsar Convention."],["World Forestry Day","March 21","To highlight the importance and conservation of forests."],["World Water Day","March 22","Focusing on the importance of freshwater."],["Earth Day","April 22","Global support for environmental protection."],["Intl. Day for Biological Diversity","May 22","To increase understanding of biodiversity issues."],["World Environment Day","June 5","Commemorates the establishment of UNEP (1972)."],["World Ozone Day","September 16","Commemorates the signing of the Montreal Protocol (1987)."]]},{"type":"exam_pattern","topic":"Environment & Ramsar Trend","analysis":"Trend Analysis for MPPSC 2026","stats":["MP Ramsar Sites (Matching): 1-2 questions","Environment Days & Themes: 1 question","Montreux Record / India''s First/Largest: 1 question"],"trend":"Commissions now don''t just ask the name, but form questions on the ''Water Source'' (e.g., Yashwant Sagar - Gambhir River) or ''Geographical Location'' (inside a National Park)."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims","year":2022,"question":"Which is the first Ramsar site of Madhya Pradesh?","options":["Sakhya Sagar","Sirpur Wetland","Bhoj Wetland","Yashwant Sagar"],"correct":"Bhoj Wetland","strategy":"Bhoj Wetland was declared in 2002, while the other three were added in 2022."},{"type":"pyq","exam":"UPSC Prelims","year":2019,"question":"Which of the following Ramsar sites is included in the ''Montreux Record''?","options":["Chilika Lake","Keoladeo National Park","Ashtamudi Lake","Wular Lake"],"correct":"Keoladeo National Park","strategy":"Currently, only 2 Indian sites are in the Montreux Record: Keoladeo and Loktak. Chilika Lake was removed from it in 2002."},{"type":"pyq","exam":"UPPSC Prelims","year":2021,"question":"When is World Ozone Day celebrated?","options":["September 16","March 21","June 5","April 22"],"correct":"September 16","strategy":"It is celebrated to commemorate the Montreal Protocol, which aimed to prevent ozone depletion."},{"type":"pyq","exam":"BPSC Prelims","year":2020,"question":"Which is the largest Ramsar site in India?","options":["Vembanad Kol Wetland","Chilika Lake","Sundarbans Wetland","Kolleru Lake"],"correct":"Sundarbans Wetland","strategy":"Sundarbans (West Bengal) is the largest Ramsar site in India covering 4,230 sq km."}],"conclusion":"Ramsar Sites and Environment Days are highly scoring topics for MPPSC. Out of the 98 Ramsar sites in India, make sure to map the exact locations and associated rivers of the 5 sites in MP (especially the recently added Tawa Reservoir)."}}', 'environment', NULL, 25, 1, 1771651355, 1771651396, 'blog', 'unit_7', 'Wetlands Conservation, Ramsar Sites and Important Environment Days', 0, 1, 0, 1, 0, 'Exhaustive guide to the 98 Ramsar Sites in India and the 5 specific Ramsar sites in Madhya Pradesh (updated Feb 2026). Includes important environment days and m...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('f1a2952a-4737-4206-bc15-bbff9e5c857a', 'worlds-most-important-straits-geography-mppsc', 'World''s Most Important Straits | विश्व की प्रमुख जलसंधियां (MPPSC 2026)', 'Master the top 15 most important straits of the world for MPPSC, UPSC, and State PSCs. Complete bilingual guide with map locations, connect/separate facts, and quick revision tables.', '{"hi":{"introduction":"भूगोल (Geography) में मानचित्र (Map Reading) एक ऐसा हिस्सा है जो आपको Prelims में 1-2 अंक 100% गारंटी के साथ दिलाता है। ''जलसंधि'' (Strait) पानी का वह संकरा मार्ग है जो दो बड़े जल निकायों (Water Bodies) को जोड़ता है और दो भू-भागों (Landmasses) को अलग करता है। MPPSC 2026 और UPSC के दृष्टिकोण से, विश्व की कुछ जलसंधियां व्यापार (Trade) और भू-राजनीति (Geopolitics) के लिए अत्यंत महत्वपूर्ण हैं। आइए उन Top 15 जलसंधियों को डिकोड करें जो हर साल परीक्षा में पूछी जाती हैं।","blocks":[{"type":"image_tag","content":""},{"type":"h2","text":"एशिया और मध्य पूर्व (Asia & Middle East)"},{"type":"h3","text":"1. मलक्का जलसंधि (Strait of Malacca)"},{"type":"ul","items":["**जोड़ती है (Connects):** अंडमान सागर (Andaman Sea) और दक्षिण चीन सागर (South China Sea)।","**अलग करती है (Separates):** मलय प्रायद्वीप (मलेशिया) और सुमात्रा द्वीप (इंडोनेशिया)।","**💡 Exam Pro-Tip:** यह विश्व की सबसे लंबी जलसंधि है और एशिया का सबसे व्यस्त ''चोकपॉइंट'' (Trade Route) है।"]},{"type":"h3","text":"2. होर्मुज जलसंधि (Strait of Hormuz)"},{"type":"ul","items":["**जोड़ती है (Connects):** फारस की खाड़ी (Persian Gulf) और ओमान की खाड़ी (Gulf of Oman)।","**अलग करती है (Separates):** ईरान और ओमान/UAE।","**💡 Exam Pro-Tip:** यह दुनिया के तेल व्यापार (Oil Trade) के लिए सबसे महत्वपूर्ण जलसंधि है।"]},{"type":"h3","text":"3. बाब-अल-मंडेब (Bab-el-Mandeb)"},{"type":"ul","items":["**जोड़ती है (Connects):** लाल सागर (Red Sea) और अदन की खाड़ी (Gulf of Aden)।","**अलग करती है (Separates):** यमन (एशिया) और जिबूती/इरिट्रिया (अफ्रीका)।","**💡 Exam Pro-Tip:** इसे ''आंसुओं का द्वार'' (Gate of Tears) भी कहा जाता है।"]},{"type":"h3","text":"4. पाक जलडमरूमध्य (Palk Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** बंगाल की खाड़ी (Bay of Bengal) और मन्नार की खाड़ी/पाक खाड़ी।","**अलग करती है (Separates):** भारत (तमिलनाडु) और श्रीलंका।","**💡 Exam Pro-Tip:** इसका नाम रॉबर्ट पाक (Robert Palk) के नाम पर रखा गया है, यह MPPSC का फेवरेट सवाल है।"]},{"type":"h3","text":"5. बेरिंग जलसंधि (Bering Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** बेरिंग सागर (Bering Sea) और चुक्ची सागर (Chukchi Sea - Arctic)।","**अलग करती है (Separates):** रूस (एशिया) और अलास्का (उत्तरी अमेरिका)।","**💡 Exam Pro-Tip:** अंतर्राष्ट्रीय तिथि रेखा (International Date Line) ठीक इसी जलसंधि के बीच से गुजरती है।"]},{"type":"h3","text":"6. सुंडा जलसंधि (Sunda Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** जावा सागर (Java Sea) और हिंद महासागर (Indian Ocean)।","**अलग करती है (Separates):** जावा द्वीप और सुमात्रा द्वीप (इंडोनेशिया)।","**💡 Exam Pro-Tip:** कुख्यात क्राकाटोआ ज्वालामुखी (Krakatoa Volcano) इसी जलसंधि में स्थित है।"]},{"type":"h2","text":"यूरोप और अफ्रीका (Europe & Africa)"},{"type":"h3","text":"7. जिब्राल्टर जलसंधि (Strait of Gibraltar)"},{"type":"ul","items":["**जोड़ती है (Connects):** भूमध्य सागर (Mediterranean Sea) और अटलांटिक महासागर।","**अलग करती है (Separates):** स्पेन (यूरोप) और मोरक्को (अफ्रीका)।","**💡 Exam Pro-Tip:** इसे ''भूमध्य सागर की कुंजी'' (Key to Mediterranean) कहा जाता है।"]},{"type":"h3","text":"8. बोस्फोरस जलसंधि (Bosphorus Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** काला सागर (Black Sea) और मरमरा सागर (Sea of Marmara)।","**अलग करती है (Separates):** एशियाई तुर्की (अनातोलिया) और यूरोपीय तुर्की (थ्रेस)।","**💡 Exam Pro-Tip:** यह इस्तांबुल शहर को दो महाद्वीपों में बांटती है।"]},{"type":"h3","text":"9. डोवर जलसंधि (Strait of Dover)"},{"type":"ul","items":["**जोड़ती है (Connects):** इंग्लिश चैनल (English Channel) और उत्तरी सागर (North Sea)।","**अलग करती है (Separates):** इंग्लैंड (UK) और फ्रांस।","**💡 Exam Pro-Tip:** यह विश्व का सबसे व्यस्त समुद्री मार्ग (Busiest Shipping Lane) है।"]},{"type":"h2","text":"अमेरिका और अन्य (Americas & Others)"},{"type":"h3","text":"10. मैगलन जलसंधि (Strait of Magellan)"},{"type":"ul","items":["**जोड़ती है (Connects):** प्रशांत महासागर और अटलांटिक महासागर।","**अलग करती है (Separates):** मुख्य भूमि दक्षिण अमेरिका और टिएरा डेल फुएगो।","**💡 Exam Pro-Tip:** पनामा नहर बनने से पहले यह सबसे प्रमुख नेविगेशन मार्ग था।"]},{"type":"h3","text":"11. फ्लोरिडा जलसंधि (Florida Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** मेक्सिको की खाड़ी (Gulf of Mexico) और अटलांटिक महासागर।","**अलग करती है (Separates):** फ्लोरिडा (USA) और क्यूबा।","**💡 Exam Pro-Tip:** प्रसिद्ध गल्फ स्ट्रीम (Gulf Stream) जलधारा यहीं से निकलती है।"]},{"type":"h3","text":"12. कुक जलसंधि (Cook Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** तस्मान सागर (Tasman Sea) और दक्षिण प्रशांत महासागर।","**अलग करती है (Separates):** न्यूजीलैंड के उत्तरी द्वीप और दक्षिणी द्वीप को।","**💡 Exam Pro-Tip:** इसका नाम प्रसिद्ध नाविक जेम्स कुक के नाम पर रखा गया है।"]},{"type":"h3","text":"13. बास जलसंधि (Bass Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** तस्मान सागर और ग्रेट ऑस्ट्रेलियन बाइट (Great Australian Bight)।","**अलग करती है (Separates):** मुख्य भूमि ऑस्ट्रेलिया और तस्मानिया (Tasmania)।","**💡 Exam Pro-Tip:** यह बहुत उथली जलसंधि है जो हिमयुग के दौरान सूखी हुई थी।"]},{"type":"h3","text":"14. डेविस जलसंधि (Davis Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** बाफिन की खाड़ी (Baffin Bay) और लैब्राडोर सागर (अटलांटिक)।","**अलग करती है (Separates):** ग्रीनलैंड और बाफिन द्वीप (कनाडा)।","**💡 Exam Pro-Tip:** यह विश्व की सबसे चौड़ी जलसंधि (Widest Strait) है।"]},{"type":"h3","text":"15. ताइवान जलसंधि (Taiwan/Formosa Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** पूर्वी चीन सागर (East China Sea) और दक्षिण चीन सागर (South China Sea)।","**अलग करती है (Separates):** चीन की मुख्य भूमि और ताइवान।","**💡 Exam Pro-Tip:** इसे फॉर्मोसा जलसंधि (Formosa Strait) के नाम से भी जाना जाता है और यह एक बड़ा भू-राजनीतिक फ्लैशप्वाइंट है।"]},{"type":"h2","text":"क्विक रिवीजन टेबल (Quick Revision Table)"},{"type":"table","head":["जलसंधि (Strait)","किसे अलग करती है? (Separates)","किसे जोड़ती है? (Connects)"],"body":[["मलक्का (Malacca)","मलेशिया - सुमात्रा","अंडमान सागर - द. चीन सागर"],["होर्मुज (Hormuz)","ईरान - ओमान","फारस की खाड़ी - ओमान की खाड़ी"],["बेरिंग (Bering)","रूस - अलास्का","बेरिंग सागर - चुक्ची सागर"],["जिब्राल्टर (Gibraltar)","स्पेन - मोरक्को","भूमध्य सागर - अटलांटिक"],["डेविस (Davis)","ग्रीनलैंड - कनाडा","बाफिन की खाड़ी - लैब्राडोर सागर"],["पाक (Palk)","भारत - श्रीलंका","बंगाल की खाड़ी - मन्नार की खाड़ी"]],"instruction":"परीक्षा से एक रात पहले इस टेबल को जरूर रिवाइज करें।"},{"type":"pyq","exam":"MPPSC Prelims","year":2020,"question":"अंतर्राष्ट्रीय तिथि रेखा (International Date Line) के समानांतर कौन सी जलसंधि स्थित है?","options":["बेरिंग जलसंधि","डोवर जलसंधि","मलक्का जलसंधि","सुंडा जलसंधि"],"correct":"बेरिंग जलसंधि (Bering Strait)","strategy":"बेरिंग जलसंधि एशिया (रूस) और उत्तर अमेरिका (अलास्का) को अलग करती है, और IDL यहीं से होकर गुजरती है।"},{"type":"pyq","exam":"UPPSC Prelims","year":2021,"question":"भूमध्य सागर की कुंजी (Key to Mediterranean) किसे कहा जाता है?","options":["होर्मुज जलसंधि","बाब-अल-मंडेब","जिब्राल्टर जलसंधि","बोस्फोरस जलसंधि"],"correct":"जिब्राल्टर जलसंधि (Strait of Gibraltar)","strategy":"यह अटलांटिक महासागर से भूमध्य सागर में प्रवेश करने का एकमात्र प्राकृतिक मार्ग है।"},{"type":"exam_pattern","topic":"World Geography Trend","analysis":"MPPSC 2026 के लिए विश्व भूगोल का विश्लेषण","stats":["जलसंधियां और नहरें (Straits & Canals): 1-2 प्रश्न","घास के मैदान और पर्वत: 1-2 प्रश्न","चर्चा में रहे स्थान (Current Affairs linked): 1 प्रश्न"],"trend":"आयोग अब रटे-रटाए प्रश्नों के बजाय ''मैपिंग'' और ''करंट अफेयर्स'' (जैसे- लाल सागर विवाद के कारण बाब-अल-मंडेब) को जोड़कर प्रश्न पूछ रहा है।"}],"conclusion":"विश्व की इन 15 जलसंधियों को एटलस (Atlas) पर खुद से मार्क करें। जब आप नक्शे पर देखते हैं कि जिब्राल्टर कैसे यूरोप और अफ्रीका को अलग करता है, तो आप इसे कभी नहीं भूलते। MPPSC 2026 के लिए ''Mapping'' आपकी सबसे बड़ी ताकत होनी चाहिए!"},"en":{"introduction":"In Geography, Map Reading is the one section that guarantees you 1-2 marks in Prelims with 100% certainty. A ''Strait'' is a narrow body of water that connects two larger water bodies and separates two landmasses. From the perspective of MPPSC 2026 and UPSC, certain global straits are highly critical for trade and geopolitics. Let''s decode the Top 15 Straits that are perennial favorites in competitive exams.","blocks":[{"type":"image_tag","content":""},{"type":"h2","text":"Asia & Middle East"},{"type":"h3","text":"1. Strait of Malacca"},{"type":"ul","items":["**Connects:** Andaman Sea & South China Sea.","**Separates:** Malay Peninsula (Malaysia) & Sumatra Island (Indonesia).","**💡 Exam Pro-Tip:** It is the longest strait in the world and the busiest primary trade route in Asia."]},{"type":"h3","text":"2. Strait of Hormuz"},{"type":"ul","items":["**Connects:** Persian Gulf & Gulf of Oman.","**Separates:** Iran & Oman/UAE.","**💡 Exam Pro-Tip:** It is the world''s most critical chokepoint for global oil trade."]},{"type":"h3","text":"3. Bab-el-Mandeb"},{"type":"ul","items":["**Connects:** Red Sea & Gulf of Aden.","**Separates:** Yemen (Asia) & Djibouti/Eritrea (Africa).","**💡 Exam Pro-Tip:** It translates to the ''Gate of Tears'' due to its dangerous navigation history."]},{"type":"h3","text":"4. Palk Strait"},{"type":"ul","items":["**Connects:** Bay of Bengal & Palk Bay/Gulf of Mannar.","**Separates:** India (Tamil Nadu) & Sri Lanka.","**💡 Exam Pro-Tip:** It is named after Robert Palk, a governor of the Madras Presidency."]},{"type":"h3","text":"5. Bering Strait"},{"type":"ul","items":["**Connects:** Bering Sea & Chukchi Sea (Arctic Ocean).","**Separates:** Russia (Asia) & Alaska (North America).","**💡 Exam Pro-Tip:** The International Date Line (IDL) passes straight through this strait."]},{"type":"h3","text":"6. Sunda Strait"},{"type":"ul","items":["**Connects:** Java Sea & Indian Ocean.","**Separates:** Java Island & Sumatra Island (Indonesia).","**💡 Exam Pro-Tip:** The infamous Krakatoa volcano is located in this strait."]},{"type":"h2","text":"Europe & Africa"},{"type":"h3","text":"7. Strait of Gibraltar"},{"type":"ul","items":["**Connects:** Mediterranean Sea & Atlantic Ocean.","**Separates:** Spain (Europe) & Morocco (Africa).","**💡 Exam Pro-Tip:** Historically known as the Pillars of Hercules; it is the ''Key to the Mediterranean''."]},{"type":"h3","text":"8. Bosphorus Strait"},{"type":"ul","items":["**Connects:** Black Sea & Sea of Marmara.","**Separates:** Asian Turkey (Anatolia) & European Turkey (Thrace).","**💡 Exam Pro-Tip:** It splits the city of Istanbul across two continents."]},{"type":"h3","text":"9. Strait of Dover"},{"type":"ul","items":["**Connects:** English Channel & North Sea.","**Separates:** England (UK) & France.","**💡 Exam Pro-Tip:** It is the narrowest part of the English Channel and the busiest shipping lane in the world."]},{"type":"h2","text":"Americas & Others"},{"type":"h3","text":"10. Strait of Magellan"},{"type":"ul","items":["**Connects:** Pacific Ocean & Atlantic Ocean.","**Separates:** Mainland South America & Tierra del Fuego.","**💡 Exam Pro-Tip:** It was the most important natural passage between the two oceans before the Panama Canal was built."]},{"type":"h3","text":"11. Florida Strait"},{"type":"ul","items":["**Connects:** Gulf of Mexico & Atlantic Ocean.","**Separates:** Florida (USA) & Cuba.","**💡 Exam Pro-Tip:** The warm Gulf Stream ocean current originates and flows through here."]},{"type":"h3","text":"12. Cook Strait"},{"type":"ul","items":["**Connects:** Tasman Sea & South Pacific Ocean.","**Separates:** North Island & South Island of New Zealand.","**💡 Exam Pro-Tip:** Named after the legendary British explorer, James Cook."]},{"type":"h3","text":"13. Bass Strait"},{"type":"ul","items":["**Connects:** Great Australian Bight & Tasman Sea.","**Separates:** Mainland Australia & Tasmania.","**💡 Exam Pro-Tip:** It is a relatively shallow strait that was dry land during the last ice age."]},{"type":"h3","text":"14. Davis Strait"},{"type":"ul","items":["**Connects:** Baffin Bay & Labrador Sea (Atlantic).","**Separates:** Greenland & Baffin Island (Canada).","**💡 Exam Pro-Tip:** It holds the record for being the widest strait in the world."]},{"type":"h3","text":"15. Taiwan Strait (Formosa Strait)"},{"type":"ul","items":["**Connects:** East China Sea & South China Sea.","**Separates:** Mainland China & Taiwan.","**💡 Exam Pro-Tip:** Also known as the Formosa Strait, it is one of the world''s biggest geopolitical flashpoints."]},{"type":"h2","text":"Quick Revision Table"},{"type":"table","head":["Strait","Separates","Connects"],"body":[["Malacca","Malaysia - Sumatra","Andaman Sea - South China Sea"],["Hormuz","Iran - Oman","Persian Gulf - Gulf of Oman"],["Bering","Russia - Alaska","Bering Sea - Chukchi Sea"],["Gibraltar","Spain - Morocco","Mediterranean Sea - Atlantic"],["Davis","Greenland - Canada","Baffin Bay - Labrador Sea"],["Palk","India - Sri Lanka","Bay of Bengal - Gulf of Mannar"]],"instruction":"Revise this table the night before your exam to secure 2 marks."},{"type":"pyq","exam":"UPSC Prelims","year":2017,"question":"Which one of the following is the narrowest strait used for international navigation?","options":["Strait of Tartary","Bab-el-Mandeb","Bosphorus Strait","Strait of Hormuz"],"correct":"Bosphorus Strait","strategy":"The Bosphorus is incredibly narrow, separating the two sides of Istanbul, Turkey."},{"type":"pyq","exam":"BPSC Prelims","year":2020,"question":"The strait connecting the Arabian Sea and the Persian Gulf is?","options":["Bab-el-Mandeb","Hormuz","Mesina","Palk"],"correct":"Hormuz","strategy":"Hormuz is the choke point for oil moving out of the Persian Gulf into the Arabian Sea (via Gulf of Oman)."},{"type":"exam_pattern","topic":"World Geography Trend","analysis":"Analysis for MPPSC 2026 World Geography","stats":["Straits & Canals: 1-2 questions guaranteed","Grasslands & Mountains: 1-2 questions","Current Affairs linked Locations: 1 question"],"trend":"State PSCs are moving away from rote facts to Map-based logic, often linking questions to current geopolitical hotspots (e.g., Bab-el-Mandeb due to the Red Sea crisis)."}],"conclusion":"Mark these 15 straits on a blank physical atlas yourself. When you visually map how Gibraltar separates Europe and Africa, it locks into your visual memory forever. For MPPSC 2026, ''Mapping'' must be your ultimate superpower!"}}', 'geography', NULL, 20, 1, 1772458852, 1772459140, 'blog', 'unit_4', 'World Geography: Oceans, Continents, and Major Water Bodies', 0, 0, 0, 0, 0, 'Master the top 15 most important straits of the world for MPPSC, UPSC, and State PSCs. Complete bilingual guide with map locations, connect/separate facts, and ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('3ec3f965-0c7b-4d77-9a12-178fc53230c2', 'worlds-most-important-straits-ultimate-guide-mppsc', 'World''s Most Important Straits: Ultimate Cheat Sheet | विश्व की प्रमुख जलसंधियां (MPPSC 2026)', 'Unlock 2 guaranteed marks in MPPSC/UPSC 2026! Master the top 15 global straits with our ultimate cheat sheet, memory tricks, and deep geopolitical analysis.', '{"hi":{"introduction":"क्या आप जानते हैं कि MPPSC और UPSC के टॉपर्स वर्ल्ड ज्योग्राफी में अपना समय कैसे बचाते हैं? वे पूरी किताब रटने के बजाय ''High-Yield Topics'' पर वार करते हैं! ''जलसंधि'' (Strait) एक ऐसा ही VIP टॉपिक है जो आपको 10 मिनट की पढ़ाई में 2 अंक 100% गारंटी के साथ दिला सकता है। इस प्रीमियम ब्लॉग में हमने दुनिया की Top 15 जलसंधियों का डीप एनालिसिस किया है। साथ ही, अंत में एक ''Ultimate Cheat Sheet'' (रिवीजन टेबल) दी गई है जिसे आप परीक्षा से ठीक पहले पढ़कर जा सकते हैं। आइए, मैपिंग के इस मास्टरक्लास को शुरू करें!","blocks":[{"type":"highlight","level":"critical","text":"टॉपर का सीक्रेट (Topper''s Secret): जलसंधि (Strait) पानी का वह संकरा मार्ग है जो 2 बड़े जल निकायों (Water Bodies) को ''जोड़ता'' है और 2 भू-भागों (Landmasses) को ''अलग'' करता है। एग्जाम में हमेशा ''कनेक्ट'' और ''सेपरेट'' के बीच फंसाया जाता है!","icon":"🚀"},{"type":"h2","text":"एशिया और मध्य पूर्व: भू-राजनीति का केंद्र (Asia & Middle East)"},{"type":"h3","text":"1. मलक्का जलसंधि (Strait of Malacca) - एशिया की जीवनरेखा"},{"type":"p","text":"दुनिया के समुद्री व्यापार का लगभग 40% हिस्सा यहीं से गुजरता है। चीन इसी जलसंधि पर अपनी निर्भरता (Malacca Dilemma) कम करना चाहता है।"},{"type":"ul","items":["**जोड़ती है (Connects):** अंडमान सागर (हिंद महासागर) और दक्षिण चीन सागर (प्रशांत महासागर)।","**अलग करती है (Separates):** मलय प्रायद्वीप (मलेशिया) और सुमात्रा द्वीप (इंडोनेशिया)।","**💡 Exam Pro-Tip:** यह विश्व की सबसे लंबी जलसंधि (Longest Strait) है (लगभग 800 किमी)।"]},{"type":"h3","text":"2. होर्मुज जलसंधि (Strait of Hormuz) - तेल का खजाना"},{"type":"p","text":"अगर यह जलसंधि 1 दिन के लिए बंद हो जाए, तो दुनिया में पेट्रोल के दाम आसमान छूने लगेंगे!"},{"type":"ul","items":["**जोड़ती है (Connects):** फारस की खाड़ी (Persian Gulf) और ओमान की खाड़ी (Gulf of Oman)।","**अलग करती है (Separates):** ईरान और ओमान/UAE।","**💡 Exam Pro-Tip:** दुनिया का 20% कच्चा तेल (Crude Oil) यहीं से निर्यात होता है।"]},{"type":"h3","text":"3. बाब-अल-मंडेब (Bab-el-Mandeb) - आंसुओं का द्वार"},{"type":"p","text":"हाल ही में ''हूती विद्रोहियों'' (Houthi Rebels) के हमलों के कारण यह क्षेत्र दुनिया भर में चर्चा (Current Affairs) का विषय रहा है।"},{"type":"ul","items":["**जोड़ती है (Connects):** लाल सागर (Red Sea) और अदन की खाड़ी (Gulf of Aden)।","**अलग करती है (Separates):** यमन (एशिया) और जिबूती/इरिट्रिया (अफ्रीका)।","**💡 Exam Pro-Tip:** इसे ''Gate of Tears'' (आंसुओं का द्वार) कहा जाता है क्योंकि अतीत में यहाँ नेविगेशन बहुत खतरनाक था।"]},{"type":"h3","text":"4. पाक जलडमरूमध्य (Palk Strait) - भारत का पड़ोसी"},{"type":"ul","items":["**जोड़ती है (Connects):** बंगाल की खाड़ी (Bay of Bengal) और मन्नार की खाड़ी/पाक खाड़ी।","**अलग करती है (Separates):** भारत (तमिलनाडु) और श्रीलंका।","**💡 Exam Pro-Tip:** प्रसिद्ध ''राम सेतु'' (Adam''s Bridge) इसी क्षेत्र के दक्षिण में मन्नार की खाड़ी को पाक खाड़ी से अलग करता है।"]},{"type":"h3","text":"5. बेरिंग जलसंधि (Bering Strait) - समय की रेखा"},{"type":"ul","items":["**जोड़ती है (Connects):** बेरिंग सागर (Bering Sea) और चुक्ची सागर (Arctic Ocean)।","**अलग करती है (Separates):** रूस (एशिया) और अलास्का (उत्तरी अमेरिका)।","**💡 Exam Pro-Tip:** अंतर्राष्ट्रीय तिथि रेखा (IDL - 180° देशांतर) ठीक इसी जलसंधि के बीच से मुड़कर गुजरती है!"]},{"type":"h3","text":"6. सुंडा जलसंधि (Sunda Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** जावा सागर (Java Sea) और हिंद महासागर (Indian Ocean)।","**अलग करती है (Separates):** जावा और सुमात्रा (इंडोनेशिया के दो प्रमुख द्वीप)।","**💡 Exam Pro-Tip:** 1883 में फटा कुख्यात क्राकाटोआ ज्वालामुखी (Krakatoa Volcano) इसी जलसंधि के बीच में स्थित है।"]},{"type":"h2","text":"यूरोप और अफ्रीका (Europe & Africa)"},{"type":"h3","text":"7. जिब्राल्टर जलसंधि (Strait of Gibraltar) - भूमध्य सागर की कुंजी"},{"type":"ul","items":["**जोड़ती है (Connects):** भूमध्य सागर (Mediterranean Sea) और अटलांटिक महासागर।","**अलग करती है (Separates):** स्पेन (यूरोप) और मोरक्को (अफ्रीका)।","**💡 Exam Pro-Tip:** इसे प्राचीन काल में ''पिलर्स ऑफ हरक्यूलिस'' (Pillars of Hercules) कहा जाता था।"]},{"type":"h3","text":"8. बोस्फोरस जलसंधि (Bosphorus Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** काला सागर (Black Sea) और मरमरा सागर (Sea of Marmara)।","**अलग करती है (Separates):** एशियाई तुर्की और यूरोपीय तुर्की।","**💡 Exam Pro-Tip:** यह जलसंधि इस्तांबुल (Istanbul) शहर के ठीक बीच से निकलती है, जो इसे दुनिया का एकमात्र ऐसा शहर बनाती है जो दो महाद्वीपों में बसा है।"]},{"type":"h3","text":"9. डोवर जलसंधि (Strait of Dover)"},{"type":"ul","items":["**जोड़ती है (Connects):** इंग्लिश चैनल (English Channel) और उत्तरी सागर (North Sea)।","**अलग करती है (Separates):** इंग्लैंड (UK) और फ्रांस।","**💡 Exam Pro-Tip:** यह विश्व का सबसे व्यस्त समुद्री मार्ग (Busiest Shipping Lane) है। इंग्लिश चैनल को तैरकर पार करने वाले इसी हिस्से का इस्तेमाल करते हैं।"]},{"type":"h2","text":"अमेरिका और अन्य (Americas & Others)"},{"type":"h3","text":"10. मैगलन जलसंधि (Strait of Magellan)"},{"type":"ul","items":["**जोड़ती है (Connects):** प्रशांत महासागर और अटलांटिक महासागर।","**अलग करती है (Separates):** मुख्य भूमि दक्षिण अमेरिका और टिएरा डेल फुएगो (Tierra del Fuego)।","**💡 Exam Pro-Tip:** पनामा नहर (Panama Canal) बनने से पहले जहाजों को अमेरिका के पूर्व से पश्चिम जाने के लिए इसी खतरनाक रास्ते से गुजरना पड़ता था।"]},{"type":"h3","text":"11. फ्लोरिडा जलसंधि (Florida Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** मेक्सिको की खाड़ी (Gulf of Mexico) और अटलांटिक महासागर।","**अलग करती है (Separates):** फ्लोरिडा (USA) और क्यूबा (Cuba)।","**💡 Exam Pro-Tip:** प्रसिद्ध और गर्म ''गल्फ स्ट्रीम'' (Gulf Stream) जलधारा इसी संकरे मार्ग से होकर अटलांटिक महासागर में प्रवेश करती है।"]},{"type":"h3","text":"12. कुक जलसंधि (Cook Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** तस्मान सागर (Tasman Sea) और दक्षिण प्रशांत महासागर।","**अलग करती है (Separates):** न्यूजीलैंड के उत्तरी द्वीप और दक्षिणी द्वीप को।","**💡 Exam Pro-Tip:** न्यूजीलैंड की राजधानी ''वेलिंगटन'' (Wellington) ठीक इसी जलसंधि के तट पर स्थित है।"]},{"type":"h3","text":"13. बास जलसंधि (Bass Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** तस्मान सागर और ग्रेट ऑस्ट्रेलियन बाइट (Great Australian Bight)।","**अलग करती है (Separates):** मुख्य भूमि ऑस्ट्रेलिया और तस्मानिया (Tasmania)।","**💡 Exam Pro-Tip:** यह जलसंधि बहुत उथली है और माना जाता है कि हिमयुग (Ice Age) के दौरान यह पूरी तरह सूखी जमीन थी।"]},{"type":"h3","text":"14. डेविस जलसंधि (Davis Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** बाफिन की खाड़ी (Baffin Bay) और लैब्राडोर सागर (Atlantic Ocean)।","**अलग करती है (Separates):** ग्रीनलैंड (Greenland) और बाफिन द्वीप (कनाडा)।","**💡 Exam Pro-Tip:** यह विश्व की सबसे चौड़ी जलसंधि (Widest Strait in the World) है।"]},{"type":"h3","text":"15. ताइवान जलसंधि (Taiwan/Formosa Strait)"},{"type":"ul","items":["**जोड़ती है (Connects):** पूर्वी चीन सागर (East China Sea) और दक्षिण चीन सागर (South China Sea)।","**अलग करती है (Separates):** चीन की मुख्य भूमि (Mainland China) और ताइवान।","**💡 Exam Pro-Tip:** इसे फॉर्मोसा जलसंधि (Formosa Strait) भी कहते हैं। यह वर्तमान में दुनिया का सबसे बड़ा भू-राजनीतिक फ्लैशप्वाइंट (Geopolitical Flashpoint) है।"]},{"type":"mnemonic","topic":"Middle East Chokepoints","visual":"🛢️","trick":"लाल आंसुओं से ''बाब'' रोया, फारसी ''ओमान'' के ''हॉर्मोन'' बढ़े।","explanation":"लाल सागर और अदन को जोड़ती है बाब-अल-मंडेब (Gate of Tears)। फारस और ओमान की खाड़ी को जोड़ती है होर्मुज (Hormuz)।"},{"type":"h2","text":"द अल्टीमेट चीट शीट (The Ultimate Cheat Sheet - All in One)"},{"type":"p","text":"परीक्षा से 10 मिनट पहले इस टेबल का स्क्रीनशॉट पढ़ें। 2 नंबर पक्के!"},{"type":"table","head":["जलसंधि (Strait)","किसे अलग करती है? (Separates Land)","किसे जोड़ती है? (Connects Water)","VIP Fact"],"body":[["मलक्का (Malacca)","मलेशिया - सुमात्रा","अंडमान सागर - द. चीन सागर","सबसे लंबी (Longest)"],["होर्मुज (Hormuz)","ईरान - ओमान / UAE","फारस की खाड़ी - ओमान की खाड़ी","तेल व्यापार का केंद्र"],["बाब-अल-मंडेब","यमन - जिबूती","लाल सागर - अदन की खाड़ी","Gate of Tears"],["बेरिंग (Bering)","रूस - अलास्का (USA)","बेरिंग सागर - चुक्ची सागर","IDL रेखा गुजरती है"],["पाक (Palk)","भारत - श्रीलंका","बंगाल की खाड़ी - मन्नार की खाड़ी","राम सेतु के पास"],["सुंडा (Sunda)","जावा - सुमात्रा","जावा सागर - हिंद महासागर","क्राकाटोआ ज्वालामुखी"],["जिब्राल्टर (Gibraltar)","स्पेन - मोरक्को","भूमध्य सागर - अटलांटिक","Key to Mediterranean"],["बोस्फोरस (Bosphorus)","एशियाई तुर्की - यूरोपीय तुर्की","काला सागर - मरमरा सागर","इस्तांबुल को बांटती है"],["डोवर (Dover)","इंग्लैंड - फ्रांस","इंग्लिश चैनल - उत्तरी सागर","सबसे व्यस्त मार्ग"],["मैगलन (Magellan)","द. अमेरिका - टिएरा डेल फुएगो","प्रशांत - अटलांटिक","पनामा से पहले का मुख्य मार्ग"],["फ्लोरिडा (Florida)","फ्लोरिडा (USA) - क्यूबा","मेक्सिको की खाड़ी - अटलांटिक","गल्फ स्ट्रीम"],["कुक (Cook)","उत्तरी - दक्षिणी न्यूजीलैंड","तस्मान सागर - प्रशांत महासागर","राजधानी वेलिंगटन"],["बास (Bass)","ऑस्ट्रेलिया - तस्मानिया","तस्मान सागर - ग्रेट ऑस्ट्रेलियन बाइट","उथली जलसंधि"],["डेविस (Davis)","ग्रीनलैंड - बाफिन द्वीप","बाफिन की खाड़ी - लैब्राडोर सागर","सबसे चौड़ी (Widest)"],["ताइवान (Taiwan)","चीन - ताइवान","पूर्वी चीन सागर - द. चीन सागर","फॉर्मोसा जलसंधि"]],"instruction":"🔥 100% Guaranteed High-Yield Table for MPPSC/UPSC Prelims 2026."},{"type":"fact_card","title":"Why Straits Matter? (Geopolitics)","facts":["Chokepoints: ये वो संकरे रास्ते हैं जिन्हें अगर ब्लॉक कर दिया जाए तो पूरी दुनिया का व्यापार ठप हो सकता है (उदा: स्वेज नहर और लाल सागर का विवाद)।","Malacca Dilemma: चीन का 80% तेल मलक्का से आता है, इसलिए वह हिंद महासागर में अपना प्रभाव बढ़ाना चाहता है।"],"icon":"🌍"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"10 डिग्री चैनल (10 Degree Channel) किसे अलग करता है?","options":["अंडमान को निकोबार से","भारत को श्रीलंका से","लक्षद्वीप को मालदीव से","सुमात्रा को जावा से"],"correct":"अंडमान को निकोबार से","strategy":"यह जलसंधि का ही एक चौड़ा रूप है। 8 डिग्री (मालदीव-मिनिकॉय), 9 डिग्री (मिनिकॉय-लक्षद्वीप) और 10 डिग्री (अंडमान-निकोबार) एग्जामिनर के फेवरेट हैं।"},{"type":"pyq","exam":"UPSC Prelims","year":2017,"question":"अंतर्राष्ट्रीय नेविगेशन के लिए उपयोग की जाने वाली सबसे संकरी जलसंधि कौन सी है?","options":["टार्टरी जलसंधि","बाब-अल-मंडेब","बोस्फोरस जलसंधि","होर्मुज जलसंधि"],"correct":"बोस्फोरस जलसंधि (Bosphorus Strait)","strategy":"बोस्फोरस अविश्वसनीय रूप से संकरी है (केवल 700 मीटर कुछ स्थानों पर), जो इस्तांबुल के दोनों किनारों को अलग करती है।"},{"type":"exam_pattern","topic":"World Mapping Trend","analysis":"MPPSC 2026 के लिए विश्व मैपिंग का एनालिसिस","stats":["Straits & Chokepoints: 1-2 प्रश्न","समुद्र और महासागर की सीमाएं: 1 प्रश्न","लाल सागर / काला सागर (Current Affairs): 1 प्रश्न पक्का"],"trend":"आयोग अब रटे-रटाए तथ्यों के बजाय ''Current Affairs'' से प्रेरित स्थानों (जैसे हूती विद्रोह के कारण ''बाब-अल-मंडेब'') पर गहराई से प्रश्न पूछ रहा है।"}],"conclusion":"दोस्तों, विश्व की इन 15 जलसंधियों को केवल पढ़ें नहीं, बल्कि एक खाली एटलस (Blank Atlas) पर खुद से मार्क करें। जब आपका दिमाग यह विज़ुअलाइज़ (Visualize) करता है कि ''जिब्राल्टर'' कैसे यूरोप और अफ्रीका को काट रहा है, तो आप इसे कभी नहीं भूलते। इस ''Ultimate Cheat Sheet'' को सेव करें और MPPSC 2026 में अपने 2 अंक पक्के करें!"},"en":{"introduction":"Do you know how MPPSC and UPSC toppers save their time in World Geography? Instead of rote-learning entire textbooks, they attack the ''High-Yield Topics''! A ''Strait'' is one such VIP topic that can guarantee you 2 marks with just 10 minutes of smart study. In this premium blog, we have deeply analyzed the Top 15 Straits of the world. Plus, we''ve included an ''Ultimate Cheat Sheet'' at the end for your last-minute revision. Let’s begin this mapping masterclass!","blocks":[{"type":"highlight","level":"critical","text":"Topper''s Secret: A Strait is a narrow passage of water that ''Connects'' 2 large water bodies and ''Separates'' 2 landmasses. Examiners always try to trick you between what it connects and what it separates!","icon":"🚀"},{"type":"h2","text":"Asia & Middle East: The Core of Geopolitics"},{"type":"h3","text":"1. Strait of Malacca - The Lifeline of Asia"},{"type":"p","text":"Almost 40% of global maritime trade passes through here. China heavily relies on it, creating the famous ''Malacca Dilemma''."},{"type":"ul","items":["**Connects:** Andaman Sea (Indian Ocean) & South China Sea (Pacific Ocean).","**Separates:** Malay Peninsula (Malaysia) & Sumatra Island (Indonesia).","**💡 Exam Pro-Tip:** It is the longest strait in the world (approx 800 km)."]},{"type":"h3","text":"2. Strait of Hormuz - The Oil Treasury"},{"type":"p","text":"If this strait is blocked for a single day, global petrol prices would skyrocket."},{"type":"ul","items":["**Connects:** Persian Gulf & Gulf of Oman.","**Separates:** Iran & Oman/UAE.","**💡 Exam Pro-Tip:** Approximately 20% of the world''s global crude oil is exported through this chokepoint."]},{"type":"h3","text":"3. Bab-el-Mandeb - The Gate of Tears"},{"type":"p","text":"Recently in the global spotlight due to the ongoing ''Houthi Rebel'' attacks on commercial shipping."},{"type":"ul","items":["**Connects:** Red Sea & Gulf of Aden.","**Separates:** Yemen (Asia) & Djibouti/Eritrea (Africa).","**💡 Exam Pro-Tip:** It translates to the ''Gate of Tears'' due to its dangerous navigational history."]},{"type":"h3","text":"4. Palk Strait - India''s Neighborly Link"},{"type":"ul","items":["**Connects:** Bay of Bengal & Palk Bay/Gulf of Mannar.","**Separates:** India (Tamil Nadu) & Sri Lanka.","**💡 Exam Pro-Tip:** The famous ''Adam''s Bridge'' (Ram Setu) is located just south of it, separating the Gulf of Mannar from Palk Bay."]},{"type":"h3","text":"5. Bering Strait - The Line of Time"},{"type":"ul","items":["**Connects:** Bering Sea & Chukchi Sea (Arctic Ocean).","**Separates:** Russia (Asia) & Alaska (North America).","**💡 Exam Pro-Tip:** The International Date Line (IDL - 180° Longitude) bends and passes exactly through this strait!"]},{"type":"h3","text":"6. Sunda Strait"},{"type":"ul","items":["**Connects:** Java Sea & Indian Ocean.","**Separates:** Java Island & Sumatra Island (Indonesia).","**💡 Exam Pro-Tip:** The infamous Krakatoa volcano, which erupted catastrophically in 1883, lies exactly in this strait."]},{"type":"h2","text":"Europe & Africa"},{"type":"h3","text":"7. Strait of Gibraltar - Key to the Mediterranean"},{"type":"ul","items":["**Connects:** Mediterranean Sea & Atlantic Ocean.","**Separates:** Spain (Europe) & Morocco (Africa).","**💡 Exam Pro-Tip:** Historically known as the ''Pillars of Hercules''. It controls all naval access to the Mediterranean."]},{"type":"h3","text":"8. Bosphorus Strait"},{"type":"ul","items":["**Connects:** Black Sea & Sea of Marmara.","**Separates:** Asian Turkey (Anatolia) & European Turkey (Thrace).","**💡 Exam Pro-Tip:** It splits the city of Istanbul right down the middle, making it the only city in the world straddling two continents."]},{"type":"h3","text":"9. Strait of Dover"},{"type":"ul","items":["**Connects:** English Channel & North Sea.","**Separates:** England (UK) & France.","**💡 Exam Pro-Tip:** It is the narrowest part of the English Channel and holds the record as the busiest shipping lane globally."]},{"type":"h2","text":"Americas & Others"},{"type":"h3","text":"10. Strait of Magellan"},{"type":"ul","items":["**Connects:** Pacific Ocean & Atlantic Ocean.","**Separates:** Mainland South America & Tierra del Fuego.","**💡 Exam Pro-Tip:** Before the Panama Canal was constructed, this treacherous route was the primary way to navigate between the Atlantic and Pacific."]},{"type":"h3","text":"11. Florida Strait"},{"type":"ul","items":["**Connects:** Gulf of Mexico & Atlantic Ocean.","**Separates:** Florida (USA) & Cuba.","**💡 Exam Pro-Tip:** The vital and warm ''Gulf Stream'' ocean current originates here and flows out into the Atlantic."]},{"type":"h3","text":"12. Cook Strait"},{"type":"ul","items":["**Connects:** Tasman Sea & South Pacific Ocean.","**Separates:** North Island & South Island of New Zealand.","**💡 Exam Pro-Tip:** Wellington, the capital of New Zealand, is strategically located right on the coast of this strait."]},{"type":"h3","text":"13. Bass Strait"},{"type":"ul","items":["**Connects:** Great Australian Bight & Tasman Sea.","**Separates:** Mainland Australia & Tasmania.","**💡 Exam Pro-Tip:** It is a relatively shallow strait that was completely dry land connecting Tasmania to Australia during the last Ice Age."]},{"type":"h3","text":"14. Davis Strait"},{"type":"ul","items":["**Connects:** Baffin Bay & Labrador Sea (Atlantic).","**Separates:** Greenland & Baffin Island (Canada).","**💡 Exam Pro-Tip:** It officially holds the record for being the widest strait in the world."]},{"type":"h3","text":"15. Taiwan Strait (Formosa Strait)"},{"type":"ul","items":["**Connects:** East China Sea & South China Sea.","**Separates:** Mainland China & Taiwan.","**💡 Exam Pro-Tip:** Also historically known as the Formosa Strait, it is currently one of the biggest geopolitical flashpoints between US and China."]},{"type":"mnemonic","topic":"Middle East Chokepoints","visual":"🛢️","trick":"Laal aansuon se ''Bab'' roya, Farsi ''Oman'' ke ''Hormone'' badhe.","explanation":"Red Sea (Laal) + Aden = Bab-el-Mandeb (Gate of Tears/Aansu). Persian Gulf (Farsi) + Oman = Hormuz."},{"type":"h2","text":"The Ultimate Cheat Sheet (All-in-One Master Table)"},{"type":"p","text":"Screenshot this table and read it 10 minutes before entering the exam hall. 2 marks secured!"},{"type":"table","head":["Strait","Separates Landmasses","Connects Water Bodies","VIP Exam Fact"],"body":[["Malacca","Malaysia - Sumatra","Andaman Sea - S. China Sea","Longest strait globally"],["Hormuz","Iran - Oman / UAE","Persian Gulf - Gulf of Oman","20% of global oil trade"],["Bab-el-Mandeb","Yemen - Djibouti","Red Sea - Gulf of Aden","Gate of Tears"],["Bering","Russia - Alaska (USA)","Bering Sea - Chukchi Sea","IDL passes through it"],["Palk","India - Sri Lanka","Bay of Bengal - Gulf of Mannar","Near Adam''s Bridge"],["Sunda","Java - Sumatra","Java Sea - Indian Ocean","Krakatoa Volcano"],["Gibraltar","Spain - Morocco","Mediterranean - Atlantic","Key to the Mediterranean"],["Bosphorus","Asian Turkey - Euro Turkey","Black Sea - Sea of Marmara","Splits Istanbul city"],["Dover","England - France","English Channel - North Sea","Busiest shipping lane"],["Magellan","S. America - Tierra del Fuego","Pacific - Atlantic","Pre-Panama Canal route"],["Florida","Florida (USA) - Cuba","Gulf of Mexico - Atlantic","Gulf Stream origin"],["Cook","North - South New Zealand","Tasman Sea - Pacific Ocean","Wellington is located here"],["Bass","Australia - Tasmania","Tasman Sea - Great Aus Bight","Shallow, dry during Ice Age"],["Davis","Greenland - Baffin Island","Baffin Bay - Labrador Sea","Widest Strait in the world"],["Taiwan","China - Taiwan","East China Sea - S. China Sea","Formosa Strait"]],"instruction":"🔥 100% Guaranteed High-Yield Table for MPPSC/UPSC Prelims 2026."},{"type":"fact_card","title":"Why Straits Matter? (Geopolitics)","facts":["Chokepoints: These are narrow passages that, if blocked, can paralyze global trade (e.g., Suez Canal & Red Sea crisis).","Malacca Dilemma: 80% of China''s oil imports pass through Malacca, driving its naval expansion in the Indian Ocean."],"icon":"🌍"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"The 10 Degree Channel separates which of the following?","options":["Andaman from Nicobar","India from Sri Lanka","Lakshadweep from Maldives","Sumatra from Java"],"correct":"Andaman from Nicobar","strategy":"A channel is essentially a wider strait. 8 Degree (Maldives-Minicoy), 9 Degree (Minicoy-Lakshadweep), and 10 Degree (Andaman-Nicobar) are examiner favorites."},{"type":"pyq","exam":"UPSC Prelims","year":2017,"question":"Which one of the following is the narrowest strait used for international navigation?","options":["Strait of Tartary","Bab-el-Mandeb","Bosphorus Strait","Strait of Hormuz"],"correct":"Bosphorus Strait","strategy":"The Bosphorus is incredibly narrow (only about 700 meters across at its narrowest point), splitting Istanbul''s European and Asian sides."},{"type":"exam_pattern","topic":"World Mapping Trend","analysis":"MPPSC 2026 World Geography Analysis","stats":["Straits & Chokepoints: 1-2 questions guaranteed","Ocean & Sea Borders: 1 question","Red Sea / Black Sea (Current Affairs): 1 sure-shot question"],"trend":"State PSCs are moving away from purely static rote facts. They now integrate ''Current Affairs'' into Geography (e.g., asking about Bab-el-Mandeb due to the Houthi crisis)."}],"conclusion":"Friends, do not just passively read these 15 straits. Take a Blank Physical Atlas and mark them yourself. When your brain visually connects how ''Gibraltar'' slices between Europe and Africa, you lock it in forever. Save this ''Ultimate Cheat Sheet'' and secure your 2 marks in MPPSC 2026!"}}', 'geography', NULL, 25, 1, 1772459020, 1772459037, 'blog', 'unit_4', 'World Geography: Oceans, Continents, and Major Water Bodies', 0, 1, 0, 1, 0, 'Unlock 2 guaranteed marks in MPPSC/UPSC 2026! Master the top 15 global straits with our ultimate cheat sheet, memory tricks, and deep geopolitical analysis.', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('2baa1c26-d76d-45ec-b646-8325b46e00fd', 'major-mountain-ranges-highest-peaks-world-geography', 'Major Mountain Ranges of the World & Highest Peaks | विश्व की प्रमुख पर्वत श्रृंखलाएं (MPPSC 2026)', 'Master the world''s major mountain ranges and their highest peaks for UPSC, MPPSC, and State PCS. Includes continent-wise lists, key geographical facts, and PYQs.', '{"hi":{"introduction":"भूगोल (Geography) में पर्वत श्रृंखलाएं (Mountain Ranges) केवल ऊंचे पत्थर नहीं हैं; वे वैश्विक जलवायु (Climate), नदियों के उद्गम और भू-राजनीतिक सीमाओं को तय करती हैं। MPPSC, UPSC, SSC और अन्य State PCS परीक्षाओं में ''पर्वत और उनकी सबसे ऊंची चोटियां'' एक ''High-Yield Topic'' है, जो 1-2 अंक 100% पक्के करता है। इस प्रीमियम ब्लॉग में हम महाद्वीप-वार (Continent-wise) पर्वत श्रृंखलाओं का सटीक विश्लेषण करेंगे और अंत में रिवीजन ट्रिक्स और PYQs को सॉल्व करेंगे।","blocks":[{"type":"highlight","level":"critical","text":"टॉपर का सीक्रेट (Topper''s Secret): एग्जामिनर हमेशा आपको ''लॉन्गेस्ट'' (सबसे लंबी) और ''हाइएस्ट'' (सबसे ऊंची) पर्वत श्रृंखलाओं के बीच, या उस पर्वत के बीच फंसाता है जो दो महाद्वीपों को अलग करता है। मैपिंग से इसे याद रखना सबसे आसान है!","icon":"🏔️"},{"type":"h2","text":"महाद्वीप-वार पर्वत श्रृंखलाएं (Continent-Wise Breakdown)"},{"type":"h3","text":"1. उत्तरी अमेरिका (North America)"},{"type":"ul","items":["**रॉकी पर्वत (Rocky Mountains):** यह उत्तरी अमेरिका की सबसे प्रमुख पर्वत श्रृंखला है। इसकी सबसे ऊंची चोटी **माउंट अल्बर्ट (Mount Elbert - 4401 m)** है।","**अप्पलेशियन पर्वत (Appalachian Mountains):** यह पूर्वी अमेरिका में स्थित प्राचीन पर्वत श्रृंखला है। इसकी सबसे ऊंची चोटी **माउंट मिशेल (Mount Mitchell)** है।"]},{"type":"h3","text":"2. दक्षिण अमेरिका (South America)"},{"type":"ul","items":["**एंडीज पर्वत (Andes Mountains):** यह दुनिया की सबसे लंबी (Longest) पर्वत श्रृंखला है (लगभग 7000 किमी)।","**सबसे ऊंची चोटी:** **माउंट एकांकागुआ (Mount Aconcagua - 6962 m)**। यह एशिया के बाहर दुनिया की सबसे ऊंची चोटी है।"]},{"type":"h3","text":"3. यूरोप (Europe)"},{"type":"ul","items":["**आल्प्स (Alps):** मध्य यूरोप की सबसे प्रसिद्ध श्रृंखला। सबसे ऊंची चोटी **माउंट ब्लैंक (Mont Blanc - 4809 m)** है।","**स्कैंडिनेवियाई पर्वत (Scandinavian Mountains):** उत्तरी यूरोप (नॉर्वे-स्वीडन) में स्थित। सबसे ऊंची चोटी **गल्धोपिजेन (Galdhøpiggen - 2469 m)** है।","**यूराल पर्वत (Ural Mountains):** इसकी सबसे ऊंची चोटी **माउंट नरोदनाया (Mount Narodnaya - 1895 m)** है।"]},{"type":"highlight","level":"important","text":"VIP Fact: यूराल पर्वत (Ural Mountains) प्राकृतिक रूप से यूरोप और एशिया महाद्वीपों को एक-दूसरे से अलग करता है। यह UPSC और State PSC का फेवरेट सवाल है!","icon":"🌍"},{"type":"h3","text":"4. अफ्रीका (Africa)"},{"type":"ul","items":["**एटलस पर्वत (Atlas Mountains):** यह उत्तर-पश्चिमी अफ्रीका में है। सबसे ऊंची चोटी **माउंट टूबकल (Mount Toubkal - 4167 m)** है।","**ड्रेकेन्सबर्ग (Drakensberg):** दक्षिण अफ्रीका में स्थित। इसकी सबसे ऊंची चोटी **थबाना नटलेनयाना (Thabana Ntlenyana - 3482 m)** है।"]},{"type":"h3","text":"5. एशिया (Asia)"},{"type":"ul","items":["**हिमालय (Himalayas):** दुनिया की सबसे ऊंची पर्वत श्रृंखला। सबसे ऊंची चोटी **माउंट एवरेस्ट (Mount Everest - 8849 m)** है।","**अल्ताई पर्वत (Altai Mountains):** मध्य और पूर्वी एशिया (रूस, चीन, मंगोलिया, कजाकिस्तान) में स्थित। सबसे ऊंची चोटी **माउंट बेलुखा (Mount Belukha - 4506 m)** है।"]},{"type":"h3","text":"6. ऑस्ट्रेलिया (Australia)"},{"type":"ul","items":["**ग्रेट डिवाइडिंग रेंज (Great Dividing Range):** ऑस्ट्रेलिया की सबसे महत्वपूर्ण श्रृंखला।","**सबसे ऊंची चोटी:** **माउंट कोसियस्ज्को (Mount Kosciuszko - 2228 m)**।"]},{"type":"h2","text":"क्विक रिवीजन टेबल (Quick Revision Table)"},{"type":"table","head":["पर्वत श्रृंखला (Mountain Range)","महाद्वीप (Continent)","सबसे ऊंची चोटी (Highest Peak)","ऊंचाई (Elevation)"],"body":[["रॉकी पर्वत (Rockies)","उत्तरी अमेरिका","माउंट अल्बर्ट (Mt. Elbert)","4401 m"],["एंडीज (Andes)","दक्षिण अमेरिका","माउंट एकांकागुआ (Mt. Aconcagua)","6962 m"],["आल्प्स (Alps)","यूरोप","माउंट ब्लैंक (Mont Blanc)","4809 m"],["यूराल (Ural)","यूरोप/एशिया","माउंट नरोदनाया (Mt. Narodnaya)","1895 m"],["एटलस (Atlas)","अफ्रीका","माउंट टूबकल (Mt. Toubkal)","4167 m"],["हिमालय (Himalayas)","एशिया","माउंट एवरेस्ट (Mt. Everest)","8849 m"],["ग्रेट डिवाइडिंग रेंज","ऑस्ट्रेलिया","माउंट कोसियस्ज्को (Mt. Kosciuszko)","2228 m"]],"instruction":"एग्जाम से एक दिन पहले इस टेबल का रिवीजन जरूर करें। 2 नंबर पक्के!"},{"type":"h2","text":"महत्वपूर्ण भौगोलिक तथ्य (Key Geographical Facts)"},{"type":"fact_card","title":"पर्वतों के प्रकार और रिकॉर्ड्स (Types & Records)","facts":["सबसे लंबी श्रृंखला (Longest): एंडीज (Andes) - दक्षिण अमेरिका।","सबसे ऊंची श्रृंखला (Highest): हिमालय (Himalayas) - एशिया।","वलित पर्वत (Fold Mountains): टेक्टोनिक प्लेटों के टकराने से बनते हैं (उदा: हिमालय, आल्प्स, रॉकी, एंडीज)। यह दुनिया के सबसे ऊंचे और नए पर्वत हैं।","भ्रंशोत्थ पर्वत (Block Mountains): पृथ्वी की पपड़ी में दरार (Faults) पड़ने से बनते हैं (उदा: जर्मनी का ब्लैक फॉरेस्ट)।"],"icon":"📊"},{"type":"mnemonic","topic":"Fold Mountains (वलित पर्वत) याद रखने की ट्रिक","visual":"🧠","trick":"U A R A Himalaya (यू आर ए हिमालय)","explanation":"U = Ural (यूराल), A = Alps (आल्प्स), R = Rockies (रॉकी), A = Andes (एंडीज), Himalaya = हिमालय। ये सभी मुख्य वलित (Fold) पर्वत हैं।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"UPSC Prelims","year":2018,"question":"निम्नलिखित में से कौन सी पर्वत श्रृंखला यूरोप और एशिया को अलग करती है?","options":["काकेशस पर्वत","आल्प्स पर्वत","यूराल पर्वत","अल्ताई पर्वत"],"correct":"यूराल पर्वत (Ural Mountains)","strategy":"रूस में स्थित यूराल पर्वत भौगोलिक रूप से यूरोप और एशिया के बीच एक प्राकृतिक सीमा (Natural Boundary) बनाता है।"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"विश्व की सबसे लंबी पर्वत श्रृंखला कौन सी है?","options":["हिमालय","रॉकी","एंडीज","आल्प्स"],"correct":"एंडीज (Andes)","strategy":"एंडीज दक्षिण अमेरिका के पश्चिमी तट पर लगभग 7000 किमी तक फैली है, जो इसे सबसे लंबी बनाती है।"},{"type":"pyq","exam":"UPPSC Prelims","year":2020,"question":"माउंट एकांकागुआ (Mount Aconcagua) किस पर्वत श्रृंखला की सबसे ऊंची चोटी है?","options":["रॉकी","एंडीज","एटलस","ग्रेट डिवाइडिंग रेंज"],"correct":"एंडीज (Andes)","strategy":"एकांकागुआ (6962 m) एशिया के बाहर विश्व की सबसे ऊंची चोटी है।"},{"type":"pyq","exam":"BPSC Prelims","year":2019,"question":"एटलस पर्वत (Atlas Mountains) किस महाद्वीप में स्थित है?","options":["यूरोप","एशिया","अफ्रीका","ऑस्ट्रेलिया"],"correct":"अफ्रीका (Africa)","strategy":"एटलस पर्वत उत्तर-पश्चिमी अफ्रीका (मोरक्को, अल्जीरिया) में स्थित है।"},{"type":"pyq","exam":"SSC CGL","year":2022,"question":"ऑस्ट्रेलिया की सबसे ऊंची चोटी कौन सी है?","options":["माउंट किलिमंजारो","माउंट कोसियस्ज्को","माउंट ब्लैंक","माउंट अल्बर्ट"],"correct":"माउंट कोसियस्ज्को (Mount Kosciuszko)","strategy":"यह ग्रेट डिवाइडिंग रेंज में स्थित है और इसकी ऊंचाई 2228 मीटर है।"},{"type":"exam_pattern","topic":"World Geography Trend","analysis":"MPPSC 2026 के लिए पर्वत श्रृंखलाओं का विश्लेषण","stats":["पर्वत और महाद्वीप मिलान (Matching): 1 प्रश्न","सबसे ऊंची चोटी (Highest Peak Facts): 1 प्रश्न","ब्लॉक बनाम फोल्ड माउंटेन (Conceptual): 1 प्रश्न"],"trend":"आयोग अब केवल ''हिमालय'' तक सीमित नहीं है। ''अल्ताई पर्वत'' और ''ड्रेकेन्सबर्ग'' जैसे कम सुने गए नामों से प्रश्न बनाकर छात्रों को कन्फ्यूज किया जा रहा है।"}],"conclusion":"पर्वत श्रृंखलाओं को याद करने का सबसे अच्छा तरीका एक विश्व का खाली मैप (Blank Map) लेना और इन सभी को उनके महाद्वीपों में प्लॉट करना है। ''एंडीज'' की लंबाई और ''यूराल'' की विभाजक रेखा (Dividing Line) को कभी न भूलें। ऊपर दी गई ट्रिक और टेबल को बार-बार रिवाइज करें, और MPPSC 2026 में 100% एक्यूरेसी के साथ अपने अंक सुनिश्चित करें!"},"en":{"introduction":"In Geography, Mountain Ranges are not just giant rocks; they dictate global climate patterns, river origins, and geopolitical boundaries. For MPPSC, UPSC, SSC, and State PCS exams, ''Mountains and their Highest Peaks'' is a High-Yield Topic that guarantees 1-2 marks. In this premium blog, we will provide an exact, continent-wise breakdown of major mountain ranges, revision tricks, and key PYQs to test your knowledge.","blocks":[{"type":"highlight","level":"critical","text":"Topper''s Secret: Examiners love to test your clarity between the ''Longest'' and ''Highest'' mountain ranges, or mountains that act as continental dividers. Mapping is the ultimate key to retaining these facts!","icon":"🏔️"},{"type":"h2","text":"Continent-Wise Breakdown of Mountain Ranges"},{"type":"h3","text":"1. North America"},{"type":"ul","items":["**Rocky Mountains:** The major mountain range in western North America. The highest peak is **Mount Elbert (4401 m)**.","**Appalachian Mountains:** An ancient mountain range in the east. The highest peak is **Mount Mitchell**."]},{"type":"h3","text":"2. South America"},{"type":"ul","items":["**Andes Mountains:** The longest continental mountain range in the world (approx 7000 km).","**Highest Peak:** **Mount Aconcagua (6962 m)**. It is the highest peak in the world outside of Asia."]},{"type":"h3","text":"3. Europe"},{"type":"ul","items":["**Alps:** The most famous range entirely in Europe. Highest peak: **Mont Blanc (4809 m)**.","**Scandinavian Mountains:** Located in Northern Europe (Norway/Sweden). Highest peak: **Galdhøpiggen (2469 m)**.","**Ural Mountains:** The highest peak is **Mount Narodnaya (1895 m)**."]},{"type":"highlight","level":"important","text":"VIP Fact: The Ural Mountains naturally divide the continents of Europe and Asia. This is an all-time favorite question for UPSC and State PSCs!","icon":"🌍"},{"type":"h3","text":"4. Africa"},{"type":"ul","items":["**Atlas Mountains:** Located in Northwestern Africa. The highest peak is **Mount Toubkal (4167 m)**.","**Drakensberg:** Located in South Africa. The highest peak is **Thabana Ntlenyana (3482 m)**."]},{"type":"h3","text":"5. Asia"},{"type":"ul","items":["**Himalayas:** The highest mountain range in the world. The highest peak is **Mount Everest (8849 m)**.","**Altai Mountains:** Located in Central and East Asia (Russia, China, Mongolia, Kazakhstan). Highest peak: **Mount Belukha (4506 m)**."]},{"type":"h3","text":"6. Australia"},{"type":"ul","items":["**Great Dividing Range:** The most substantial mountain range in Australia.","**Highest Peak:** **Mount Kosciuszko (2228 m)**."]},{"type":"h2","text":"Quick Revision Table (Ultimate Cheat Sheet)"},{"type":"table","head":["Mountain Range","Continent","Highest Peak","Elevation"],"body":[["Rocky Mountains","North America","Mount Elbert","4401 m"],["Andes","South America","Mount Aconcagua","6962 m"],["Alps","Europe","Mont Blanc","4809 m"],["Ural Mountains","Europe/Asia","Mount Narodnaya","1895 m"],["Atlas Mountains","Africa","Mount Toubkal","4167 m"],["Himalayas","Asia","Mount Everest","8849 m"],["Great Dividing Range","Australia","Mount Kosciuszko","2228 m"]],"instruction":"Revise this table the night before your exam to secure guaranteed marks."},{"type":"h2","text":"Key Geographical Facts"},{"type":"fact_card","title":"Types of Mountains & Records","facts":["Longest Range: Andes (South America).","Highest Range: Himalayas (Asia).","Fold Mountains: Formed by the collision of tectonic plates (e.g., Himalayas, Alps, Rockies, Andes). These are the highest and youngest mountains.","Block Mountains: Formed by faults or cracks in the Earth''s crust (e.g., Black Forest in Germany)."],"icon":"📊"},{"type":"mnemonic","topic":"Trick to remember Fold Mountains","visual":"🧠","trick":"U A R A Himalaya","explanation":"U = Ural, A = Alps, R = Rockies, A = Andes, Himalaya. All of these are classic examples of Fold Mountains!"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"UPSC Prelims","year":2018,"question":"Which of the following mountain ranges separates Europe from Asia?","options":["Caucasus Mountains","Alps Mountains","Ural Mountains","Altai Mountains"],"correct":"Ural Mountains","strategy":"The Ural Mountains, primarily located in Russia, act as a natural geographical boundary separating Europe and Asia."},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"Which is the longest mountain range in the world?","options":["Himalayas","Rockies","Andes","Alps"],"correct":"Andes","strategy":"The Andes stretch for about 7,000 km along the western edge of South America, making it the longest continental mountain range."},{"type":"pyq","exam":"UPPSC Prelims","year":2020,"question":"Mount Aconcagua is the highest peak of which mountain range?","options":["Rockies","Andes","Atlas","Great Dividing Range"],"correct":"Andes","strategy":"Aconcagua (6962 m) is located in the Andes and is the highest peak outside of Asia."},{"type":"pyq","exam":"BPSC Prelims","year":2019,"question":"The Atlas Mountains are located in which continent?","options":["Europe","Asia","Africa","Australia"],"correct":"Africa","strategy":"The Atlas Mountains stretch across northwestern Africa, primarily in Morocco, Algeria, and Tunisia."},{"type":"pyq","exam":"SSC CGL","year":2022,"question":"What is the highest peak in Australia?","options":["Mount Kilimanjaro","Mount Kosciuszko","Mont Blanc","Mount Elbert"],"correct":"Mount Kosciuszko","strategy":"Mount Kosciuszko is located in the Great Dividing Range and stands at an elevation of 2228 meters."},{"type":"exam_pattern","topic":"World Geography Trend Analysis","analysis":"MPPSC 2026 Trend Analysis","stats":["Mountain to Continent Matching: 1 question","Highest Peak Facts: 1 question","Block vs. Fold Mountain Concepts: 1 question"],"trend":"Commissions are moving beyond just the Himalayas. They are framing confusing questions using less discussed ranges like ''Altai'' and ''Drakensberg''."}],"conclusion":"The best way to memorize mountain ranges is to take a Blank World Map and plot them yourself continent by continent. Never forget the length of the ''Andes'' and the dividing nature of the ''Urals''. Revise the mnemonic and cheat sheet frequently to ensure 100% accuracy in MPPSC 2026!"}}', 'geography', 'https://npnjzfmywierjpxbnehw.supabase.co/storage/v1/object/public/card-images/mountains-world.png', 20, 1, 1772511463, 1773992975, 'blog', 'unit_4', 'World Geography: Mountains and Mountain Ranges', 0, 0, 0, 1, 0, 'Master the world''s major mountain ranges and their highest peaks for UPSC, MPPSC, and State PCS. Includes continent-wise lists, key geographical facts, and PYQs...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('db7cdfa1-e0cc-43ff-8804-b0e628d79bd0', 'world-grasslands-masterclass-geography-mppsc', 'World Grasslands Masterclass: Deep Dive & Geography Tricks | विश्व के प्रमुख घास के मैदान (MPPSC 2026)', 'An exhaustive, deep-dive masterclass into World Grasslands for UPSC and MPPSC 2026. Includes local winds, tribes, economic significance, advanced PYQs, and memory tricks.', '{"hi":{"introduction":"भूगोल (Geography) में ''घास के मैदान'' (Grasslands) केवल वनस्पति का प्रकार नहीं हैं, बल्कि ये दुनिया की अर्थव्यवस्था, पशुपालन और प्राचीन जनजातियों का केंद्र हैं। MPPSC और UPSC में अब सीधे ''स्थान'' (Location) नहीं पूछे जाते; अब आयोग यह पूछता है कि ''प्रेरीज'' में कौन सी हवा बहती है, या ''सवाना'' में कौन सी जनजाति रहती है? इस मास्टरक्लास ब्लॉग में हम घास के मैदानों का ''Deep Analysis'' करेंगे, उनके आर्थिक महत्व को समझेंगे और 2026 के लिए सबसे महत्वपूर्ण PYQs सॉल्व करेंगे।","blocks":[{"type":"image_tag","content":""},{"type":"highlight","level":"critical","text":"एग्जाम ट्रैप (Exam Trap): ऑस्ट्रेलिया के घास के मैदानों को अक्सर इंटरनेट पर गलत ''पम्पास'' (Pampas) लिख दिया जाता है। याद रखें: पम्पास सिर्फ दक्षिण अमेरिका (अर्जेंटीना) में हैं, जबकि ऑस्ट्रेलिया में इन्हें ''डाउन्स'' (Downs) कहा जाता है।","icon":"⚠️"},{"type":"h2","text":"घास के मैदानों का वैज्ञानिक वर्गीकरण (Scientific Classification)"},{"type":"p","text":"जलवायु और अक्षांश (Latitudes) के आधार पर इन्हें दो प्रमुख श्रेणियों में बांटा जाता है:"},{"type":"table","head":["प्रकार (Type)","अक्षांशीय विस्तार (Latitudes)","विशेषता और उदाहरण"],"body":[["उष्णकटिबंधीय (Tropical)","10° से 25° (भूमध्य रेखा के पास)","लंबी और कठोर घास (हाथी घास)। सवाना, लानोस, कैम्पोस।"],["शीतोष्ण (Temperate)","30° से 50° (मध्य अक्षांश)","छोटी, मुलायम और अत्यधिक पौष्टिक घास। प्रेरीज, पम्पास, स्टेपीज, डाउन्स, वेल्ड।"]],"instruction":"कांसेप्ट: जहाँ बारिश भारी होती है वहाँ जंगल बनते हैं, जहाँ बारिश नहीं होती वहाँ रेगिस्तान बनते हैं। घास के मैदान इन दोनों के बीच के ''संक्रमण क्षेत्र'' (Transition Zones) हैं।"},{"type":"h2","text":"क्षेत्रवार गहन विश्लेषण (In-Depth Regional Breakdown)"},{"type":"h3","text":"1. सवाना (Savanna) - ''विश्व का चिड़ियाघर''"},{"type":"p","text":"सवाना अफ्रीका (मुख्य रूप से मध्य और पूर्वी) का एक उष्णकटिबंधीय मैदान है। इसे ''पार्कलैंड टोपोग्राफी'' (Park-land Topography) भी कहते हैं क्योंकि यहाँ घास के बीच-बीच में छतरीनुमा पेड़ (बबूल/Acacia) होते हैं।"},{"type":"ul","items":["**यह क्यों प्रसिद्ध है?** इसे ''Big Game Country'' कहा जाता है क्योंकि यहाँ दुनिया के सबसे बड़े शाकाहारी और मांसाहारी जानवर (शेर, हाथी, जेब्रा) पाए जाते हैं।","**जनजाति (Tribe):** पूर्वी अफ्रीका के सवाना में ''मसाई'' (Masai) और नाइजीरिया में ''हौसा'' (Hausa) जनजातियाँ पशुपालन करती हैं।"]},{"type":"image_tag","content":""},{"type":"h3","text":"2. प्रेरीज (Prairies) - ''विश्व की रोटी की टोकरी''"},{"type":"p","text":"उत्तरी अमेरिका (USA और कनाडा) के ये शीतोष्ण मैदान अपनी ''चेरनोज़म'' (Chernozem) मिट्टी के लिए जाने जाते हैं, जो गेहूं की खेती के लिए सर्वोत्तम है।"},{"type":"ul","items":["**स्थानीय पवन (Local Wind):** यहाँ सर्दियों में ''चिनूक'' (Chinook) नामक गर्म हवा चलती है। यह बर्फ को पिघला देती है, जिससे पशुओं के लिए घास उपलब्ध हो जाती है (इसलिए इसे Snow-Eater कहते हैं)।","**यह क्यों प्रसिद्ध है?** भारी मशीनीकृत कृषि (गेहूं) और ''शिकागो'' (Chicago) शहर जो दुनिया की सबसे बड़ी मांस मंडी है। यहाँ का प्रमुख जानवर ''बाइसन'' (Bison) है।"]},{"type":"h3","text":"3. पम्पास (Pampas) - ''गौचो का घर''"},{"type":"p","text":"दक्षिण अमेरिका (अर्जेंटीना, उरुग्वे, ब्राजील) के ये मैदान अपनी उच्च गुणवत्ता वाली ''अल्फाल्फा'' (Alfalfa) घास के लिए विश्व प्रसिद्ध हैं।"},{"type":"ul","items":["**यह क्यों प्रसिद्ध है?** अल्फाल्फा घास खाकर यहाँ के मवेशी (Cattle) बहुत जल्दी मोटे होते हैं, जिससे अर्जेंटीना ''बीफ'' (Beef) का सबसे बड़ा निर्यातक है।","**अतिरिक्त ज्ञान:** यहाँ के घोड़ों पर चलने वाले पारंपरिक चरवाहों को ''गौचो'' (Gauchos) कहा जाता है। ब्यूनस आयर्स (Buenos Aires) यहाँ का प्रमुख व्यापारिक केंद्र है।"]},{"type":"h3","text":"4. स्टेपीज (Steppes) - ''खानाबदोशों की भूमि''"},{"type":"p","text":"यूरेशिया (पूर्वी यूरोप से लेकर मध्य एशिया तक) का यह सबसे विशाल घास का मैदान है। यहाँ की जलवायु अत्यधिक महाद्वीपीय (Continental) है।"},{"type":"ul","items":["**यह क्यों प्रसिद्ध है?** इतिहास में चंगेज खान और हूणों जैसे घुड़सवार योद्धाओं का उद्गम यहीं से हुआ।","**जनजाति:** मध्य एशिया के स्टेपीज में ''किरगिज़'' (Kirghiz) और ''कजाख'' (Kazakh) नामक खानाबदोश जनजातियां (Nomadic Herders) निवास करती हैं।"]},{"type":"h3","text":"5. वेल्ड (Veldt) - ''सोने और हीरे की खदानें''"},{"type":"p","text":"दक्षिण अफ्रीका के इन मैदानों को ऊंचाई के आधार पर Highveld, Middleveld और Lowveld में बांटा गया है।"},{"type":"ul","items":["**यह क्यों प्रसिद्ध है?** यह दुनिया का एकमात्र ऐसा घास का मैदान है जो अपने ''खनिजों'' के लिए जाना जाता है। जोहान्सबर्ग (Johannesburg) में सोना और किम्बरले (Kimberley) में हीरे की खदानें हैं।","**कृषि:** यहाँ मक्का (Maize) बहुतायत में उगाया जाता है, जिसे ''Maize Triangle'' कहते हैं। यहाँ मेरिनो भेड़ें भी पाली जाती हैं।"]},{"type":"h3","text":"6. डाउन्स (Downs) - ''मेरिनो ऊन का साम्राज्य''"},{"type":"p","text":"ऑस्ट्रेलिया के मरे-डार्लिंग (Murray-Darling) बेसिन में स्थित शीतोष्ण मैदान।"},{"type":"ul","items":["**यह क्यों प्रसिद्ध है?** यहाँ दुनिया की सबसे अच्छी ऊन देने वाली ''मेरिनो भेड़'' (Merino Sheep) पाली जाती है।","**अतिरिक्त ज्ञान:** यहाँ भेड़ चराने वाले मजदूरों को ''जकारू'' (Jackaroos) कहा जाता है। कंगारू और एमु यहाँ के मुख्य जानवर हैं।"]},{"type":"fact_card","title":"अन्य महत्वपूर्ण लेकिन कम सुने गए मैदान","facts":["पुस्टाज (Puszta): हंगरी (यूरोप) के घास के मैदान।","कैंटरबरी (Canterbury): न्यूजीलैंड (यहाँ भी भेड़ पालन होता है)।","ग्रान चाको (Gran Chaco): अर्जेंटीना और पराग्वे में स्थित दलदली और घास वाला क्षेत्र (हार्डवुड पेड़ों के लिए प्रसिद्ध)।","लानोस (Llanos): वेनेजुएला (ओरिनोको नदी बेसिन - उष्णकटिबंधीय)।"],"icon":"📝"},{"type":"mnemonic","topic":"Tropical Grasslands Trick","visual":"🌴","trick":"SaLa Ca","explanation":"Sa = Savanna (Africa), La = Llanos (Venezuela), Ca = Campos (Brazil). ये तीनों उष्णकटिबंधीय (Tropical) हैं। बाकी सब शीतोष्ण (Temperate) हैं!"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"UPSC Prelims","year":2013,"question":"विभिन्न महाद्वीपों में घास के मैदानों को अलग-अलग नामों से जाना जाता है। ''लानोस'' (Llanos) कहाँ पाए जाते हैं?","options":["उत्तरी अमेरिका","दक्षिण अमेरिका","अफ्रीका","ऑस्ट्रेलिया"],"correct":"दक्षिण अमेरिका","strategy":"लानोस वेनेजुएला (दक्षिण अमेरिका) में ओरीनोको नदी बेसिन के पास पाए जाने वाले उष्णकटिबंधीय घास के मैदान हैं।"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"निम्नलिखित में से कौन सा एक शीतोष्ण (Temperate) घास का मैदान नहीं है?","options":["पम्पास","वेल्ड","डाउन्स","सवाना"],"correct":"सवाना (Savanna)","strategy":"सवाना भूमध्य रेखा के पास पाया जाता है, जो इसे उष्णकटिबंधीय बनाता है। ''SaLa Ca'' ट्रिक याद रखें।"},{"type":"pyq","exam":"UPPSC Prelims","year":2019,"question":"''विश्व की रोटी की टोकरी'' (Breadbasket of the World) किस क्षेत्र को कहा जाता है?","options":["स्टेपीज","पम्पास","प्रेरीज","वेल्ड"],"correct":"प्रेरीज (Prairies)","strategy":"उत्तरी अमेरिका के प्रेरीज अपनी उपजाऊ चेरनोज़म मिट्टी के कारण भारी मात्रा में गेहूं का उत्पादन करते हैं।"},{"type":"pyq","exam":"BPSC Prelims","year":2018,"question":"दक्षिण अमेरिका के शीतोष्ण घास के मैदानों को क्या कहा जाता है?","options":["सवाना","पम्पास","प्रेरीज","वेल्ड"],"correct":"पम्पास (Pampas)","strategy":"पम्पास मुख्य रूप से अर्जेंटीना में फैले हुए हैं और अल्फाल्फा घास तथा पशुपालन के लिए जाने जाते हैं।"},{"type":"exam_pattern","topic":"World Geography Trend","analysis":"MPPSC 2026 Trend Analysis","stats":["मैचिंग (Region to Grassland): 1 प्रश्न पक्का।","जनजातियां (Tribes) और स्थानीय पवन (Local Winds): हाई प्रोबेबिलिटी।","आर्थिक भूगोल (Agriculture/Minerals in Grasslands): नया ट्रेंड।"],"trend":"आयोग अब केवल ''स्थान'' नहीं पूछता। अब प्रश्न ''चिनूक हवाओं का प्रभाव'' या ''मसाई जनजाति का निवास स्थान'' जैसे गहराई वाले (In-depth) कॉन्सेप्ट्स पर आ रहे हैं।"}],"conclusion":"विश्व के घास के मैदानों को याद करने का सबसे बेहतरीन तरीका है उन्हें ब्लैंक मैप (Blank Map) पर लोकेट करना। याद रखें कि भूमध्य रेखा (Equator) के पास वाले मैदान ''उष्णकटिबंधीय'' (Tropical) होते हैं और कर्क/मकर रेखा से ऊपर/नीचे वाले ''शीतोष्ण'' (Temperate) होते हैं। 2026 के एग्जाम में ''गौचो'' और ''अल्फाल्फा'' जैसे कीवर्ड्स आपको सीधे सही उत्तर तक पहुँचाएंगे!"},"en":{"introduction":"In Geography, ''Grasslands'' are not merely types of vegetation; they are the epicenters of the global economy, animal husbandry, and ancient indigenous tribes. In MPPSC and UPSC, questions have evolved beyond simple ''locations''. The commissions now ask: ''Which local wind blows over the Prairies?'' or ''Which tribe inhabits the Savanna?''. In this masterclass blog, we will do a ''Deep Analysis'' of grasslands, understand their economic significance, and solve the most crucial PYQs for 2026.","blocks":[{"type":"image_tag","content":""},{"type":"highlight","level":"critical","text":"Exam Trap: Often, random internet maps mislabel ''Pampas'' in Australia. Remember: Pampas are strictly located in South America (Argentina), whereas the grasslands in Australia are conventionally called ''Downs''.","icon":"⚠️"},{"type":"h2","text":"Scientific Classification of Grasslands"},{"type":"p","text":"Based on Climate and Latitudes, grasslands are primarily divided into two main categories:"},{"type":"table","head":["Type","Latitudinal Extent","Characteristics & Examples"],"body":[["Tropical","10° to 25° (Near Equator)","Tall, coarse grass (Elephant grass). Savanna, Llanos, Campos."],["Temperate","30° to 50° (Mid-latitudes)","Short, soft, and highly nutritious grass. Prairies, Pampas, Steppes, Downs, Veldt."]],"instruction":"Concept: Heavy rainfall creates forests; no rainfall creates deserts. Grasslands are the ''Transition Zones'' between the two."},{"type":"h2","text":"In-Depth Region-by-Region Breakdown"},{"type":"h3","text":"1. Savanna - ''The World''s Zoo''"},{"type":"p","text":"Savanna is a tropical grassland located mainly in Central and Eastern Africa. It is also known for its ''Park-land Topography'' because the tall grasses are interspersed with scattered, umbrella-shaped trees (like Acacia)."},{"type":"ul","items":["**Why is it famous?** It is called ''Big Game Country'' as it hosts the world''s largest herbivores and carnivores (Lions, Elephants, Zebras).","**Tribes:** The ''Masai'' tribe in East Africa and the ''Hausa'' tribe in Nigeria practice pastoralism here."]},{"type":"image_tag","content":""},{"type":"h3","text":"2. Prairies - ''Breadbasket of the World''"},{"type":"p","text":"These temperate grasslands of North America (USA & Canada) are renowned for their highly fertile ''Chernozem'' soil, making them perfect for wheat cultivation."},{"type":"ul","items":["**Local Wind:** The warm ''Chinook'' wind blows here in winter. It melts the snow, making pasture available for livestock (hence called the ''Snow-Eater'').","**Why is it famous?** Heavily mechanized wheat agriculture and the city of ''Chicago'', the world''s largest meat-packing center. The iconic animal is the ''Bison''."]},{"type":"h3","text":"3. Pampas - ''Home of the Gauchos''"},{"type":"p","text":"Located in South America (Argentina, Uruguay, Brazil), these temperate plains are world-famous for growing high-quality ''Alfalfa'' grass."},{"type":"ul","items":["**Why is it famous?** Cattle fatten up very quickly eating Alfalfa, making Argentina one of the largest exporters of ''Beef'' globally.","**Extra Knowledge:** The traditional horse-riding herdsmen here are known as ''Gauchos''. Buenos Aires is the major commercial hub."]},{"type":"h3","text":"4. Steppes - ''Land of the Nomads''"},{"type":"p","text":"This is the most extensive continuous grassland in Eurasia (spanning Eastern Europe to Central Asia). The climate here is extremely Continental."},{"type":"ul","items":["**Why is it famous?** Historically, this region birthed legendary horseback warriors like Genghis Khan and the Huns.","**Tribes:** Nomadic herders like the ''Kirghiz'' and ''Kazakh'' tribes inhabit the Central Asian Steppes."]},{"type":"h3","text":"5. Veldt - ''Mines of Gold and Diamonds''"},{"type":"p","text":"These are the temperate grasslands of South Africa, divided by elevation into Highveld, Middleveld, and Lowveld."},{"type":"ul","items":["**Why is it famous?** It is the only grassland globally renowned for its ''Minerals''. Johannesburg is famous for Gold, and Kimberley for Diamond mines.","**Agriculture:** Maize is grown abundantly in the ''Maize Triangle''. Merino sheep are also reared here."]},{"type":"h3","text":"6. Downs - ''Empire of Merino Wool''"},{"type":"p","text":"Temperate grasslands located in the Murray-Darling basin of Australia."},{"type":"ul","items":["**Why is it famous?** It is the leading region for rearing the ''Merino Sheep'', which yields the finest wool in the world.","**Extra Knowledge:** The laborers who work on sheep stations are called ''Jackaroos''. Kangaroos and Emus are native animals."]},{"type":"fact_card","title":"Other Crucial (But Less Heard) Grasslands","facts":["Puszta: Temperate grasslands in Hungary (Europe).","Canterbury: Grasslands in New Zealand (famous for sheep rearing).","Gran Chaco: A swampy, grassy region in Argentina and Paraguay (famous for Quebracho hardwood).","Llanos: Tropical grasslands in Venezuela (Orinoco River Basin)."],"icon":"📝"},{"type":"mnemonic","topic":"Trick to remember Tropical Grasslands","visual":"🌴","trick":"SaLa Ca","explanation":"Sa = Savanna (Africa), La = Llanos (Venezuela), Ca = Campos (Brazil). These three are Tropical. Everything else is Temperate!"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"UPSC Prelims","year":2013,"question":"Grasslands are known by different names in different continents. Where are the ''Llanos'' found?","options":["North America","South America","Africa","Australia"],"correct":"South America (Venezuela)","strategy":"Llanos are vast tropical grassland plains situated to the east of the Andes in Colombia and Venezuela."},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"Which of the following is NOT a Temperate grassland?","options":["Pampas","Veldt","Downs","Savanna"],"correct":"Savanna","strategy":"Savanna is found near the equator in Africa, making it a Tropical grassland. Remember the ''SaLa Ca'' trick."},{"type":"pyq","exam":"UPPSC Prelims","year":2019,"question":"Which region is known as the ''Breadbasket of the World''?","options":["Steppes","Pampas","Prairies","Veldt"],"correct":"Prairies","strategy":"The Prairies of North America produce surplus wheat due to highly fertile Chernozem soil and highly mechanized farming techniques."},{"type":"pyq","exam":"BPSC Prelims","year":2018,"question":"What are the temperate grasslands of South America called?","options":["Savanna","Pampas","Prairies","Veldt"],"correct":"Pampas","strategy":"Pampas are primarily spread across Argentina and are globally known for Alfalfa grass and extensive cattle ranching."},{"type":"exam_pattern","topic":"World Geography Trend","analysis":"MPPSC 2026 Trend Analysis","stats":["Match the Following (Region to Grassland): 1 Question guaranteed.","Tribes and Local Winds: High Probability.","Economic Geography (Agriculture/Minerals in Grasslands): New Emerging Trend."],"trend":"Commissions no longer just ask for ''locations''. Questions are now based on in-depth concepts like ''the effect of Chinook winds'' or ''the habitat of the Masai tribe''."}],"conclusion":"The most effective way to memorize World Grasslands is to locate them on a Blank Physical World Map. Remember the core concept: Grasslands near the Equator are ''Tropical'', and those beyond the Tropics of Cancer/Capricorn are ''Temperate''. In the 2026 exam, keywords like ''Gauchos'' and ''Alfalfa'' will lead you straight to the correct answer!"}}', 'geography', 'https://npnjzfmywierjpxbnehw.supabase.co/storage/v1/object/public/card-images/grass-lands-image.png', 25, 1, 1772597726, 1773992969, 'blog', 'unit_4', 'World Geography: Natural Regions, Vegetation, and Grasslands', 0, 0, 0, 1, 0, 'An exhaustive, deep-dive masterclass into World Grasslands for UPSC and MPPSC 2026. Includes local winds, tribes, economic significance, advanced PYQs, and memo...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('aaa57593-3d81-4940-80b2-a2a6961eb7c8', 'major-ocean-surface-currents-warm-cold-geography', 'Major Ocean Currents: Warm & Cold | विश्व की प्रमुख समुद्री जलधाराएं (MPPSC 2026)', 'Master the Warm and Cold Ocean Currents of the World for UPSC, MPPSC, and State PCS. Includes Pacific, Atlantic, and Indian Ocean currents with mnemonics, PYQs, and phenomena like El Niño.', '{"hi":{"introduction":"महासागरीय जलधाराएं (Ocean Currents) समुद्र के भीतर बहने वाली विशाल नदियां हैं जो वैश्विक जलवायु, व्यापार और समुद्री जीवन को नियंत्रित करती हैं। MPPSC और UPSC जैसी प्रतियोगी परीक्षाओं में ''गर्म'' (Warm) और ''ठंडी'' (Cold) जलधाराओं की पहचान करना एक ''High-Yield Topic'' है जहाँ से सीधे प्रश्न बनते हैं। जलधाराओं की उत्पत्ति के मुख्य कारण हैं: पृथ्वी का घूर्णन (Coriolis Force), प्रचलित पवनें (Winds), तापमान (Temperature) और लवणता (Salinity) में अंतर। आइए, विश्व की प्रमुख जलधाराओं का 100% सटीक महासागर-वार विश्लेषण करें।","blocks":[{"type":"highlight","level":"critical","text":"एग्जाम रूल (Exam Rule): भूमध्य रेखा (Equator) से ध्रुवों (Poles) की ओर बहने वाली जलधाराएं ''गर्म'' (Warm) होती हैं, जबकि ध्रुवों से भूमध्य रेखा की ओर बहने वाली जलधाराएं ''ठंडी'' (Cold) होती हैं!","icon":"🌊"},{"type":"h2","text":"महासागर-वार जलधाराओं का वर्गीकरण (Ocean-Wise Breakdown)"},{"type":"h3","text":"1. प्रशांत महासागर (Pacific Ocean)"},{"type":"table","head":["प्रकृति (Nature)","जलधारा का नाम (Name of Current)"],"body":[["गर्म (Warm)","क्यूरोशियो (Kuroshio), उत्तरी विषुवतीय (North Eq.), दक्षिणी विषुवतीय (South Eq.), पूर्वी ऑस्ट्रेलियाई (East Australian), अलास्का (Alaska Current)।"],["ठंडी (Cold)","ओयाशियो (Oyashio), कैलिफोर्निया (California), हम्बोल्ट या पेरू (Humboldt / Peru Current)।"]],"instruction":"हम्बोल्ट जलधारा (पेरू) सीधे ''अल नीनो'' (El Niño) घटना से जुड़ी है।"},{"type":"h3","text":"2. अटलांटिक महासागर (Atlantic Ocean)"},{"type":"table","head":["प्रकृति (Nature)","जलधारा का नाम (Name of Current)"],"body":[["गर्म (Warm)","गल्फ स्ट्रीम (Gulf Stream), उत्तरी अटलांटिक ड्रिफ्ट (North Atlantic Drift), ब्राजीलियन (Brazilian), गिनी (Guinea Current)।"],["ठंडी (Cold)","लैब्राडोर (Labrador), कनारी (Canary), फॉकलैंड (Falkland), बेंग्वेला (Benguela Current)।"]],"instruction":"गल्फ स्ट्रीम को ''यूरोप का गर्म कंबल'' (Warm blanket of Europe) भी कहा जाता है।"},{"type":"h3","text":"3. हिंद महासागर और वैश्विक (Indian Ocean & Global)"},{"type":"table","head":["महासागर / क्षेत्र","जलधाराएं (Currents)"],"body":[["हिंद महासागर (Indian)","गर्म: अगुलहास (Agulhas) | ठंडी: पश्चिमी ऑस्ट्रेलियाई (West Australian)।"],["वैश्विक (Global)","ठंडी: पश्चिमी पवन प्रवाह (West Wind Drift) - यह अंटार्कटिका के चारों ओर बहती है।"]],"instruction":"अगुलहास हिंद महासागर की सबसे प्रमुख गर्म जलधारा है।"},{"type":"h2","text":"महत्वपूर्ण भौगोलिक घटनाएं (Key Geographical Phenomena)"},{"type":"ul","items":["**सारगैसो सागर (Sargasso Sea):** यह उत्तरी अटलांटिक महासागर में स्थित है। इसकी सबसे बड़ी विशेषता यह है कि इसकी ''कोई तटरेखा (Coastline) नहीं है''। यह चारों ओर से जलधाराओं (गल्फ स्ट्रीम, कनारी आदि) से घिरा हुआ शांत जल क्षेत्र है।","**ठंडी और गर्म जलधाराओं का मिलन:** जहाँ ठंडी और गर्म जलधाराएं मिलती हैं (जैसे न्यूफाउंडलैंड के पास ''गल्फ स्ट्रीम'' और ''लैब्राडोर''), वहाँ घना कोहरा (Foggy weather) छा जाता है। लेकिन यह क्षेत्र ''प्लवक'' (Plankton) के विकास के लिए सर्वोत्तम है, जिससे यह दुनिया के सबसे बेहतरीन ''मत्स्य ग्रहण क्षेत्र'' (Prime Fishing Grounds - Grand Banks) बन जाते हैं।","**अल नीनो और ला नीना (El Niño / La Niña):** सामान्य स्थिति में दक्षिण अमेरिका के तट पर ठंडी ''हम्बोल्ट (पेरू) जलधारा'' बहती है। जब यह ठंडी जलधारा अस्थायी रूप से एक ''गर्म'' जलधारा से बदल जाती है, तो इसे ''अल नीनो'' कहते हैं, जो वैश्विक जलवायु और भारतीय मानसून को प्रभावित करता है।"]},{"type":"mnemonic","topic":"ठंडी जलधाराओं को याद रखने की ट्रिक (Trick for Cold Currents)","visual":"🧠","trick":"हम बोले ग्रीन बगुला क्यों केला F A K (फेंक) रहा है?","explanation":"हम=हम्बोल्ट, बोले=लैब्राडोर(ले), ग्रीन=ग्रीनलैंड, बगुला=बेंग्वेला, क्यों=क्यूराइल(ओयाशियो), केला=कैलिफोर्निया, F=फॉकलैंड, A=अंटार्कटिक(West Wind Drift), K=कनारी। ये सभी ''ठंडी'' (Cold) जलधाराएं हैं!"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"UPSC Prelims","year":2015,"question":"निम्नलिखित में से कौन सी एक महासागरीय ठंडी जलधारा (Cold Current) है?","options":["गल्फ स्ट्रीम","अगुलहास धारा","लैब्राडोर धारा","ब्राजील धारा"],"correct":"लैब्राडोर धारा (Labrador Current)","strategy":"लैब्राडोर आर्कटिक महासागर से दक्षिण की ओर (कनाडा के तट पर) बहती है, जो इसे ठंडी जलधारा बनाती है।"},{"type":"pyq","exam":"MPPSC Prelims","year":2018,"question":"अगुलहास (Agulhas) जलधारा किस महासागर में बहती है?","options":["प्रशांत महासागर","अटलांटिक महासागर","हिंद महासागर","आर्कटिक महासागर"],"correct":"हिंद महासागर (Indian Ocean)","strategy":"अगुलहास हिंद महासागर के दक्षिण-पश्चिमी भाग (अफ्रीका के पूर्वी तट) में बहने वाली एक गर्म जलधारा है।"},{"type":"pyq","exam":"UPPSC Prelims","year":2020,"question":"ग्रांड बैंक्स (Grand Banks) जहाँ उत्कृष्ट मत्स्य पालन होता है, किन जलधाराओं के मिलने से बनता है?","options":["गल्फ स्ट्रीम और लैब्राडोर","क्यूरोशियो और ओयाशियो","ब्राजील और फॉकलैंड","अगुलहास और बेंग्वेला"],"correct":"गल्फ स्ट्रीम (गर्म) और लैब्राडोर (ठंडी)","strategy":"जब अटलांटिक में गल्फ स्ट्रीम और लैब्राडोर मिलती हैं, तो प्लैंकटन बहुतायत में पनपते हैं, जो मछलियों का मुख्य भोजन हैं।"},{"type":"pyq","exam":"BPSC Prelims","year":2019,"question":"पेरू जलधारा (Peru Current) का दूसरा नाम क्या है?","options":["हम्बोल्ट जलधारा","कनारी जलधारा","बेंग्वेला जलधारा","अलास्का जलधारा"],"correct":"हम्बोल्ट जलधारा (Humboldt Current)","strategy":"यह दक्षिण अमेरिका के पश्चिमी तट पर बहने वाली एक ठंडी जलधारा है, जिसे अलेक्जेंडर वॉन हम्बोल्ट के नाम पर रखा गया है।"},{"type":"exam_pattern","topic":"Oceanography Trend Analysis","analysis":"MPPSC 2026 के लिए समुद्री जलधाराओं का विश्लेषण","stats":["गर्म/ठंडी जलधारा की पहचान: 1 प्रश्न पक्का","जलधारा और महासागर (Matching): उच्च संभावना","अल नीनो/ला नीना का प्रभाव (Conceptual): 1 प्रश्न"],"trend":"आयोग अब रटने वाले प्रश्नों के साथ-साथ ''कोहरा छाना'' और ''मछली पकड़ने के क्षेत्र'' जैसे Application-based प्रश्न पूछ रहा है।"}],"conclusion":"महासागरीय जलधाराएं भौतिक भूगोल (Physical Geography) का एक ऐसा टॉपिक है जिसे रटने से ज्यादा ''विज़ुअलाइज़'' (Visualize) करने की जरूरत है। ऊपर दी गई ''ठंडी जलधाराओं की ट्रिक'' को याद कर लें, बाकी बची हुई अधिकांश धाराएं गर्म होंगी! MPPSC 2026 के लिए इस टॉपिक से अपना 1 अंक 100% पक्का करें।"},"en":{"introduction":"Ocean Currents are massive, continuous, directed movements of seawater generated by forces acting upon the mean flow, such as Earth''s rotation (Coriolis Force), wind, temperature, and salinity differences. For aspirants of UPSC, MPPSC, and SSC, identifying whether a current is ''Warm'' or ''Cold'' and its respective ocean is a highly rewarding topic. Let’s decode the world''s major ocean surface currents with 100% accuracy, essential phenomena, and previous year questions.","blocks":[{"type":"highlight","level":"critical","text":"Exam Rule: Currents flowing from the Equator towards the Poles are ''Warm'', whereas currents flowing from the Poles towards the Equator are ''Cold''!","icon":"🌊"},{"type":"h2","text":"Ocean-Wise Breakdown of Currents"},{"type":"h3","text":"1. Pacific Ocean"},{"type":"table","head":["Nature","Name of Ocean Currents"],"body":[["Warm Currents","Kuroshio, North Equatorial, South Equatorial, East Australian, Alaska Current."],["Cold Currents","Oyashio, California, Humboldt (Peru) Current."]],"instruction":"The Humboldt (Peru) current is directly linked to the climatic phenomenon known as ''El Niño''."},{"type":"h3","text":"2. Atlantic Ocean"},{"type":"table","head":["Nature","Name of Ocean Currents"],"body":[["Warm Currents","Gulf Stream, North Atlantic Drift, Brazilian Current, Guinea Current."],["Cold Currents","Labrador Current, Canary Current, Falkland Current, Benguela Current."]],"instruction":"The North Atlantic Drift / Gulf Stream is often referred to as the ''Warm blanket of Europe''."},{"type":"h3","text":"3. Indian Ocean & Global"},{"type":"table","head":["Ocean / Region","Currents"],"body":[["Indian Ocean","Warm: Agulhas Current | Cold: West Australian Current."],["Global","Cold: West Wind Drift (flows continuously around Antarctica)."]],"instruction":"Agulhas is the most prominent warm current of the Indian Ocean, flowing down the east coast of Africa."},{"type":"h2","text":"Key Geographical Phenomena"},{"type":"ul","items":["**Sargasso Sea:** Located entirely within the Atlantic Ocean, it is the only sea on Earth which has ''no coastline''. It is bounded by four ocean currents (including the Gulf Stream and Canary Current) forming an ocean gyre.","**Meeting of Cold and Warm Currents:** When a warm current (e.g., Gulf Stream) meets a cold current (e.g., Labrador Current) near Newfoundland, it creates thick, foggy weather, which is hazardous for navigation. However, this mixing brings up nutrients, promoting massive Plankton growth, creating world-class fishing grounds (like the Grand Banks).","**El Niño & La Niña:** Under normal conditions, the cold Humboldt (Peru) Current flows along the west coast of South America. When this cold current is temporarily replaced by a warm equatorial current, the phenomenon is called El Niño, drastically altering global weather patterns and weakening the Indian Monsoon."]},{"type":"mnemonic","topic":"Trick to remember Cold Currents","visual":"🧠","trick":"Green Penguin Labrador Can Fly Beyond Oceans","explanation":"Green (Greenland), Penguin (Peru/Humboldt), Labrador (Labrador), Can (Canary & California), Fly (Falkland), Beyond (Benguela), Oceans (Oyashio). All these are Cold Currents!"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"UPSC Prelims","year":2015,"question":"Which of the following is a cold ocean current?","options":["Gulf Stream","Agulhas Current","Labrador Current","Brazilian Current"],"correct":"Labrador Current","strategy":"The Labrador Current flows from the Arctic Ocean southwards along the coast of Canada, bringing cold water."},{"type":"pyq","exam":"MPPSC Prelims","year":2018,"question":"The Agulhas current flows in which ocean?","options":["Pacific Ocean","Atlantic Ocean","Indian Ocean","Arctic Ocean"],"correct":"Indian Ocean","strategy":"Agulhas is a warm current in the southwestern Indian Ocean, flowing down the eastern coast of South Africa."},{"type":"pyq","exam":"UPPSC Prelims","year":2020,"question":"The Grand Banks, a major fishing ground, is formed by the meeting of which two currents?","options":["Gulf Stream and Labrador","Kuroshio and Oyashio","Brazil and Falkland","Agulhas and Benguela"],"correct":"Gulf Stream and Labrador","strategy":"The convergence of the warm Gulf Stream and the cold Labrador Current creates ideal conditions for plankton, drawing huge fish populations."},{"type":"pyq","exam":"BPSC Prelims","year":2019,"question":"What is the other name for the Peru Current?","options":["Humboldt Current","Canary Current","Benguela Current","Alaska Current"],"correct":"Humboldt Current","strategy":"It is a cold current flowing along the western coast of South America, named after the Prussian explorer Alexander von Humboldt."},{"type":"exam_pattern","topic":"Oceanography Trend Analysis","analysis":"Trend Analysis for MPPSC 2026","stats":["Warm/Cold Identification: 1 guaranteed question","Current to Ocean Matching: High Probability","Phenomena (Sargasso Sea / El Niño): 1 Conceptual Question"],"trend":"Exams are increasingly focusing on the ecological and climatic impacts of currents (e.g., fishing grounds and fog) rather than just simple location matching."}],"conclusion":"Ocean currents are a fundamental part of Physical Geography that require visualization rather than rote learning. Memorize the ''Cold Currents Mnemonic'' provided above—by default, most of the remaining major currents you encounter will be warm! Secure your marks for MPPSC 2026 by revising this precise list regularly."}}', 'geography', 'https://npnjzfmywierjpxbnehw.supabase.co/storage/v1/object/public/card-images/world-straits.png', 25, 1, 1772640655, 1773992997, 'blog', 'unit_4', 'World Geography: Oceans, Continents, and Major Water Bodies', 0, 0, 0, 1, 0, 'Master the Warm and Cold Ocean Currents of the World for UPSC, MPPSC, and State PCS. Includes Pacific, Atlantic, and Indian Ocean currents with mnemonics, PYQs,...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('a168d2dd-8516-4317-bc34-74320e0613c0', 'major-rivers-of-the-world-tributaries-mppsc', 'Lifelines of the Earth: Major World Rivers | पृथ्वी की जीवनरेखा: विश्व की प्रमुख नदियां (MPPSC 2026)', 'Comprehensive guide to the major rivers of the world, their tributaries, origins, and outflows for UPSC, MPPSC, and SSC. Includes continent-wise breakdown and PYQs.', '{"hi":{"introduction":"नदियां पृथ्वी की धमनियां (Arteries) हैं, जो न केवल मानव सभ्यताओं का पालन-पोषण करती हैं, बल्कि वैश्विक जलवायु और अर्थव्यवस्था को भी आकार देती हैं। MPPSC, UPSC और SSC जैसी परीक्षाओं में विश्व की प्रमुख नदियों के उद्गम (Origin) और मुहाने (Outflow) से प्रश्न निश्चित रूप से आते हैं। इससे पहले कि हम आगे बढ़ें, तीन बुनियादी शब्द समझ लें: **ड्रेनेज बेसिन (Drainage Basin)** वह संपूर्ण क्षेत्र है जहाँ से नदी अपना जल एकत्र करती है; **उद्गम (Source)** वह स्थान है जहाँ से नदी शुरू होती है (जैसे कोई पहाड़ या झील); और **मुहाना (Mouth/Outflow)** वह स्थान है जहाँ नदी समुद्र या महासागर में गिरती है।","blocks":[{"type":"h2","text":"महाद्वीप-वार नदियों का वर्गीकरण (Continent-Wise Breakdown)"},{"type":"h3","text":"1. अफ्रीका (Africa)"},{"type":"table","head":["नदी (River)","उद्गम (Origin) & मुहाना (Outflow)","सहायक नदियां (Tributaries) & मुख्य तथ्य"],"body":[["नील (Nile)","उद्गम: विक्टोरिया झील (श्वेत नील) और ताना झील (ब्लू नील)। मुहाना: भूमध्य सागर।","सहायक: व्हाइट नील और ब्लू नील (खार्तूम में मिलती हैं)। यह विश्व की सबसे लंबी नदी है।"],["कांगो (Congo / Zaire)","उद्गम: उत्तर-पूर्वी जाम्बिया के उच्च प्रदेश। मुहाना: अटलांटिक महासागर।","सहायक: कसाई, उबांगी। तथ्य: यह भूमध्य रेखा (Equator) को दो बार पार करती है।"],["नाइजर (Niger)","उद्गम: गिनी हाइलैंड्स। मुहाना: गिनी की खाड़ी (अटलांटिक)।","सहायक: बेन्यू (Benue)। तथ्य: इसे ''Oil River'' (तेल नदी) के नाम से भी जाना जाता है।"]],"instruction":"अफ्रीका की नदियों का भूमध्य रेखा और मकर रेखा से संबंध अक्सर पूछा जाता है।"},{"type":"h3","text":"2. दक्षिण अमेरिका (South America)"},{"type":"ul","items":["**अमेजन (Amazon):**","**उद्गम:** एंडीज पर्वत (पेरू)। **मुहाना:** अटलांटिक महासागर।","**सहायक नदियां:** मडेरा (Madeira - सबसे बड़ी सहायक नदी), रियो नेग्रो।","**मुख्य तथ्य:** जल आयतन (Volume) और ड्रेनेज बेसिन के आकार के मामले में यह **विश्व की सबसे बड़ी नदी** है।"]},{"type":"h3","text":"3. उत्तरी अमेरिका (North America)"},{"type":"table","head":["नदी (River)","उद्गम (Origin) & मुहाना (Outflow)","मुख्य तथ्य (Key Facts)"],"body":[["मिसिसिपी-मिसौरी","उद्गम: इटास्का झील / रॉकी पर्वत। मुहाना: मेक्सिको की खाड़ी।","यह ''पक्षी-पाद डेल्टा'' (Bird-foot delta) का निर्माण करती है। उत्तरी अमेरिका का सबसे बड़ा नदी तंत्र।"],["कोलोराडो (Colorado)","उद्गम: रॉकी पर्वत। मुहाना: कैलिफोर्निया की खाड़ी।","विश्व प्रसिद्ध ''ग्रैंड कैन्यन'' (Grand Canyon) और हूवर डैम इसी नदी पर स्थित हैं।"]]},{"type":"h3","text":"4. एशिया (Asia)"},{"type":"p","text":"एशियाई नदियों में चीन और भारतीय उपमहाद्वीप की नदियां सबसे प्रमुख हैं:"},{"type":"ul","items":["**यांग्त्ज़ी (Yangtze):** उद्गम: तिब्बत का पठार। मुहाना: पूर्वी चीन सागर। यह एशिया की सबसे लंबी नदी है।","**मेकांग (Mekong):** उद्गम: तिब्बत का पठार। मुहाना: दक्षिण चीन सागर। यह दक्षिण-पूर्व एशिया की जीवनरेखा है।","**सिंधु-गंगा-ब्रह्मपुत्र तंत्र (Indus-Ganga-Brahmaputra):**","**सिंधु (Indus):** मानसरोवर झील के पास से निकलती है और अरब सागर में गिरती है (सहायक: चिनाब, सतलज, झेलम)।","**गंगा (Ganga):** गंगोत्री ग्लेशियर से निकलती है और बंगाल की खाड़ी में गिरती है (सहायक: यमुना, सोन, गंडक)।","**ब्रह्मपुत्र (Brahmaputra):** चेमायुंगडुंग ग्लेशियर से निकलकर बंगाल की खाड़ी में गिरती है (सहायक: तीस्ता, लोहित, सुबनसिरी)।"]},{"type":"h3","text":"5. यूरोप (Europe)"},{"type":"ul","items":["**वोल्गा (Volga):** उद्गम: वल्दाई पहाड़ियाँ। मुहाना: कैस्पियन सागर। यह यूरोप की सबसे लंबी नदी है।","**डेन्यूब (Danube):** उद्गम: ब्लैक फॉरेस्ट (जर्मनी)। मुहाना: काला सागर (Black Sea)। **VIP Fact:** यह विश्व की एकमात्र नदी है जो 10 देशों से होकर गुजरती है और 4 राजधानियों को छूती है।"]},{"type":"h3","text":"6. ऑस्ट्रेलिया (Australia)"},{"type":"ul","items":["**मरे-डार्लिंग (Murray-Darling):** उद्गम: ऑस्ट्रेलियन आल्प्स। मुहाना: दक्षिणी महासागर (Southern Ocean)। यह ऑस्ट्रेलिया का सबसे महत्वपूर्ण नदी तंत्र है।"]},{"type":"fact_card","title":"एग्जाम फैक्ट्स चेकलिस्ट (High-Yield Facts)","facts":["विश्व की सबसे लंबी नदी (Longest): नील (Nile)।","आयतन के हिसाब से सबसे बड़ी नदी (Largest by Volume): अमेजन (Amazon)।","भूमध्य रेखा (Equator) को दो बार काटने वाली नदी: कांगो (Congo / Zaire)।","मकर रेखा (Tropic of Capricorn) को दो बार काटने वाली नदी: लिम्पोपो (Limpopo - अफ्रीका)।","कर्क रेखा (Tropic of Cancer) को दो बार काटने वाली नदी: माही (Mahi - भारत)।"],"icon":"🌊"},{"type":"mnemonic","topic":"नदियों के मुहाने (Outflows) याद रखने की ट्रिक","visual":"🧠","trick":"वोल्गा गई कैस्पियन में, डेन्यूब गई ब्लैक में।","explanation":"Volga River गिरती है Caspian Sea में। Danube River गिरती है Black Sea में। ये दोनों यूरोप के सबसे ज्यादा पूछे जाने वाले सवाल हैं।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"UPSC Prelims","year":2015,"question":"निम्नलिखित में से कौन सी नदी भूमध्य रेखा (Equator) को दो बार पार करती है?","options":["अमेजन","नील","कांगो","नाइजर"],"correct":"कांगो (Congo)","strategy":"कांगो नदी (जिसे जायरे भी कहा जाता है) मध्य अफ्रीका में भूमध्य रेखा को दो बार काटती है।"},{"type":"pyq","exam":"MPPSC Prelims","year":2018,"question":"यूरोप की सबसे लंबी नदी कौन सी है?","options":["राइन","डेन्यूब","वोल्गा","रोन"],"correct":"वोल्गा (Volga)","strategy":"वोल्गा यूरोप की सबसे लंबी नदी है जो रूस से बहते हुए कैस्पियन सागर में गिरती है।"},{"type":"pyq","exam":"UPPSC Prelims","year":2020,"question":"''ग्रैंड कैन्यन'' (Grand Canyon) किस नदी द्वारा निर्मित है?","options":["मिसिसिपी","कोलोराडो","अमेजन","सेंट लॉरेंस"],"correct":"कोलोराडो (Colorado)","strategy":"कोलोराडो नदी ने संयुक्त राज्य अमेरिका में एक विशाल और गहरी घाटी, ग्रैंड कैन्यन का निर्माण किया है।"},{"type":"pyq","exam":"BPSC Prelims","year":2019,"question":"डेन्यूब नदी (Danube River) किस सागर में गिरती है?","options":["बाल्टिक सागर","कैस्पियन सागर","काला सागर","उत्तरी सागर"],"correct":"काला सागर (Black Sea)","strategy":"डेन्यूब ब्लैक फॉरेस्ट (जर्मनी) से निकलकर पूर्व की ओर बहते हुए काला सागर में गिरती है।"},{"type":"pyq","exam":"SSC CGL","year":2021,"question":"आयतन (Volume) और जल निकासी बेसिन के मामले में दुनिया की सबसे बड़ी नदी कौन सी है?","options":["नील","अमेजन","यांग्त्ज़ी","मिसिसिपी"],"correct":"अमेजन (Amazon)","strategy":"नील सबसे लंबी है, लेकिन अमेजन में दुनिया की सभी नदियों की तुलना में सबसे अधिक जल आयतन है।"},{"type":"exam_pattern","topic":"World Rivers Trend","analysis":"MPPSC 2026 के लिए नदियों का विश्लेषण","stats":["नदी और उसका मुहाना (Outflow Matching): 1 प्रश्न पक्का","रेखाओं को काटने वाली नदियां (Equator/Tropics): उच्च संभावना","सहायक नदियां (Tributaries - खासकर सिंधु-गंगा): 1 प्रश्न"],"trend":"आयोग अब केवल सबसे लंबी/बड़ी नदियों के नाम नहीं पूछता, बल्कि उनके ''मुहाने'' (Outflows) और ''किन देशों से गुजरती हैं'' (जैसे डेन्यूब) पर गहराई से प्रश्न पूछ रहा है।"}],"conclusion":"विश्व की प्रमुख नदियों को याद करने का सबसे अच्छा तरीका एटलस (Atlas) पर उनका उद्गम और मुहाना ट्रेस करना है। याद रखें कि नील सबसे ''लंबी'' है और अमेजन सबसे ''बड़ी'' (आयतन में) है। इन तथ्यों का नियमित रिवीजन करें और 2026 की परीक्षा में अपने अंक पक्के करें।\n\nFor more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"},"en":{"introduction":"Rivers are the lifelines of the Earth, nurturing human civilizations while shaping global climate and economies. For exams like MPPSC, UPSC, and SSC, the origin, tributaries, and outflow of the world''s major rivers are 100% guaranteed questions. Before diving in, let''s clarify three basic terms: A **Drainage Basin** is the entire area of land drained by a river system; the **Source (Origin)** is where a river begins (like a mountain or lake); and the **Mouth (Outflow)** is where the river empties into a sea or ocean.","blocks":[{"type":"h2","text":"Continent-Wise Breakdown of Major Rivers"},{"type":"h3","text":"1. Africa"},{"type":"table","head":["River","Origin & Outflow","Tributaries & Key Facts"],"body":[["Nile","Origin: Lake Victoria (White) & Lake Tana (Blue). Outflow: Mediterranean Sea.","Tributaries: White Nile & Blue Nile (meet at Khartoum). It is the longest river in the world."],["Congo (Zaire)","Origin: Highlands of NE Zambia. Outflow: Atlantic Ocean.","Tributaries: Kasai, Ubangi. Fact: It crosses the Equator twice."],["Niger","Origin: Guinea Highlands. Outflow: Gulf of Guinea (Atlantic).","Tributaries: Benue. Fact: Famously known as the ''Oil River''."]],"instruction":"Questions frequently target African rivers crossing the Equator and Tropic of Capricorn."},{"type":"h3","text":"2. South America"},{"type":"ul","items":["**Amazon:**","**Origin:** Andes Mountains (Peru). **Outflow:** Atlantic Ocean.","**Major Tributaries:** Madeira (largest tributary), Rio Negro.","**Key Fact:** It is the **largest river in the world** by water volume and drainage basin size."]},{"type":"h3","text":"3. North America"},{"type":"table","head":["River","Origin & Outflow","Key Facts"],"body":[["Mississippi-Missouri","Origin: Lake Itasca / Rocky Mountains. Outflow: Gulf of Mexico.","Forms a famous ''bird-foot delta''. Largest river system in North America."],["Colorado","Origin: Rocky Mountains. Outflow: Gulf of California.","The world-renowned ''Grand Canyon'' and Hoover Dam are built on this river."]]},{"type":"h3","text":"4. Asia"},{"type":"p","text":"Asian rivers are dominated by the immense systems of China and the Indian Subcontinent:"},{"type":"ul","items":["**Yangtze:** Origin: Tibetan Plateau. Outflow: East China Sea. It is the longest river in Asia.","**Mekong:** Origin: Tibetan Plateau. Outflow: South China Sea. Known as the lifeline of Southeast Asia.","**Indus-Ganga-Brahmaputra System:**","**Indus:** Originates near Lake Mansarovar and empties into the Arabian Sea (Tributaries: Chenab, Sutlej, Jhelum).","**Ganga:** Originates from Gangotri Glacier and empties into the Bay of Bengal (Tributaries: Yamuna, Son, Gandak).","**Brahmaputra:** Originates from Chemayungdung Glacier and flows into the Bay of Bengal (Tributaries: Teesta, Lohit, Subansiri)."]},{"type":"h3","text":"5. Europe"},{"type":"ul","items":["**Volga:** Origin: Valdai Hills. Outflow: Caspian Sea. It is the longest river in Europe.","**Danube:** Origin: Black Forest (Germany). Outflow: Black Sea. **VIP Fact:** It is the only river in the world that passes through 10 countries and touches 4 capital cities."]},{"type":"h3","text":"6. Australia"},{"type":"ul","items":["**Murray-Darling:** Origin: Australian Alps. Outflow: Southern Ocean. This is the most significant river system in Australia."]},{"type":"fact_card","title":"Key Exam Facts Checklist","facts":["Longest river in the world: Nile.","Largest river by volume: Amazon.","River crossing the Equator twice: Congo (Zaire).","River crossing the Tropic of Capricorn twice: Limpopo (Africa).","River crossing the Tropic of Cancer twice: Mahi (India)."],"icon":"🌊"},{"type":"mnemonic","topic":"Trick to remember European River Outflows","visual":"🧠","trick":"Volga to the Casp, Danube to the Black.","explanation":"Volga River empties into the Caspian Sea. Danube River empties into the Black Sea. These two are highly repeated questions in UPSC/MPPSC."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"UPSC Prelims","year":2015,"question":"Which of the following rivers crosses the equator twice?","options":["Amazon","Nile","Congo","Niger"],"correct":"Congo","strategy":"The Congo River (also known as the Zaire River) in Central Africa forms a large curve that crosses the equator twice."},{"type":"pyq","exam":"MPPSC Prelims","year":2018,"question":"Which is the longest river in Europe?","options":["Rhine","Danube","Volga","Rhone"],"correct":"Volga","strategy":"The Volga is the longest river in Europe, flowing entirely within Russia and draining into the Caspian Sea."},{"type":"pyq","exam":"UPPSC Prelims","year":2020,"question":"The ''Grand Canyon'' is carved out by which river?","options":["Mississippi","Colorado","Amazon","St. Lawrence"],"correct":"Colorado","strategy":"The Colorado River has eroded the landscape over millions of years to create the massive Grand Canyon in the USA."},{"type":"pyq","exam":"BPSC Prelims","year":2019,"question":"The Danube River empties into which sea?","options":["Baltic Sea","Caspian Sea","Black Sea","North Sea"],"correct":"Black Sea","strategy":"Originating in the Black Forest of Germany, the Danube flows eastward and empties into the Black Sea."},{"type":"pyq","exam":"SSC CGL","year":2021,"question":"Which is the largest river in the world in terms of volume and drainage basin?","options":["Nile","Amazon","Yangtze","Mississippi"],"correct":"Amazon","strategy":"While the Nile is the longest, the Amazon carries more water than any other river in the world."},{"type":"exam_pattern","topic":"World Rivers Trend","analysis":"Trend Analysis for MPPSC 2026","stats":["River to Outflow Matching: 1 guaranteed question","Rivers cutting major Latitudes (Equator/Tropics): High Probability","Tributaries (Especially Indus-Ganga): 1 question"],"trend":"Commissions are shifting from simply asking the longest/largest rivers to focusing on their ''Outflows'' and the ''Number of countries'' they cross (e.g., Danube)."}],"conclusion":"The most effective way to memorize major world rivers is to trace their origins and outflows on a physical Atlas. Always remember the distinction: the Nile is the ''Longest'', while the Amazon is the ''Largest'' by volume. Revise these key facts regularly to secure your marks in the 2026 exams.\n\nFor more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"}}', 'geography', NULL, 25, 1, 1772775044, 1773992981, 'blog', 'unit_4', 'World Geography: Oceans, Continents, and Major Water Bodies', 0, 0, 0, 1, 0, 'Comprehensive guide to the major rivers of the world, their tributaries, origins, and outflows for UPSC, MPPSC, and SSC. Includes continent-wise breakdown and P...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('4ae15b04-027d-4c7a-8abe-f647d1cab832', 'major-river-systems-india-tributaries-mppsc', 'Major River Systems of India & Tributaries | भारत की प्रमुख नदियां और उनकी सहायक नदियां (MPPSC 2026)', 'Master the Himalayan and Peninsular River Systems of India for MPPSC, UPSC, and SSC. Comprehensive guide with origins, tributaries, PYQs, and high-yield exam facts.', '{"hi":{"introduction":"भारत की नदियां केवल जल का स्रोत नहीं हैं, बल्कि वे हमारी संस्कृति, अर्थव्यवस्था और भूगोल की आत्मा हैं। MPPSC, UPSC और SSC की परीक्षाओं में ''रैंक से कम कुछ नहीं'' का लक्ष्य रखने वाले छात्रों के लिए भारत का नदी तंत्र (River Systems of India) सबसे ''High-Yield Topic'' है। भारतीय अपवाह तंत्र (Drainage System) को मुख्य रूप से दो भागों में बांटा जाता है: **हिमालयी नदियां** (Himalayan Rivers - जो बर्फ पिघलने के कारण सदाबहार या Perennial होती हैं) और **प्रायद्वीपीय नदियां** (Peninsular Rivers - जो वर्षा पर निर्भर और मौसमी या Seasonal होती हैं)। आइए, इन जीवनरेखाओं का परीक्षा की दृष्टि से 100% सटीक विश्लेषण करें।","blocks":[{"type":"h2","text":"1. हिमालयी नदी तंत्र (The Himalayan River Systems)"},{"type":"h3","text":"सिंधु नदी तंत्र (Indus System)"},{"type":"ul","items":["**उद्गम (Origin):** तिब्बत में **मानसरोवर झील** (बोखर चू ग्लेशियर) के पास।","**मुहाना (Outflow):** कराची के पास **अरब सागर** (Arabian Sea) में गिरती है।","**प्रमुख सहायक नदियां (Tributaries):** इसे ''पंचनद'' (Panchnad) कहा जाता है, जिसमें **झेलम, चिनाब, रावी, व्यास और सतलज** शामिल हैं।"]},{"type":"h3","text":"गंगा नदी तंत्र (Ganga System)"},{"type":"ul","items":["**उद्गम (Origin):** उत्तराखंड के **गंगोत्री ग्लेशियर** (गोमुख) से भागीरथी के रूप में।","**प्रयाग (Prayags):** **देवप्रयाग** में भागीरथी और अलकनंदा नदियां मिलती हैं, जिसके बाद इसे ''गंगा'' कहा जाता है।","**प्रमुख सहायक नदियां:** दाएँ तट से **यमुना** और **सोन**; बाएँ तट से गोमती, घाघरा, **गंडक** और **कोसी**।","**मुहाना (Outflow):** मेघना के नाम से **बंगाल की खाड़ी** (Bay of Bengal) में गिरती है (सुंदरबन डेल्टा का निर्माण)।"]},{"type":"h3","text":"ब्रह्मपुत्र नदी तंत्र (Brahmaputra System)"},{"type":"ul","items":["**उद्गम (Origin):** तिब्बत में मानसरोवर झील के पास **चेमायुंगडुंग ग्लेशियर** (Chemayungdung Glacier)।","**विभिन्न नाम (Different Names):** तिब्बत में **त्संगपो (Tsangpo)**, अरुणाचल प्रदेश में **दिहांग (Dihang)**, असम में ब्रह्मपुत्र, और बांग्लादेश में **जमुना (Jamuna)**।","**मुहाना (Outflow):** गंगा (पद्मा) के साथ मिलकर **बंगाल की खाड़ी** में गिरती है।"]},{"type":"h2","text":"2. प्रायद्वीपीय नदी तंत्र (The Peninsular River Systems)"},{"type":"h3","text":"पश्चिम की ओर बहने वाली नदियां (West-Flowing Rivers - Estuary Forming)"},{"type":"table","head":["नदी (River)","उद्गम (Origin)","विशेष तथ्य (Key Facts)"],"body":[["नर्मदा (Narmada)","अमरकंटक (Amarkantak), मध्य प्रदेश","विंध्य और सतपुड़ा के बीच भ्रंश घाटी (Rift Valley) में बहती है। यह डेल्टा नहीं, ज्वारनदमुख (Estuary) बनाती है।"],["ताप्ती (Tapti/Tapi)","मुल्ताई (Multai), बैतूल, मध्य प्रदेश","सतपुड़ा के दक्षिण में भ्रंश घाटी में बहती है और खंभात की खाड़ी (अरब सागर) में गिरती है।"]],"instruction":"पश्चिम की ओर बहने वाली नदियां डेल्टा नहीं बनातीं, बल्कि एश्चुअरी (Estuary) बनाती हैं।"},{"type":"h3","text":"पूर्व की ओर बहने वाली नदियां (East-Flowing Rivers - Delta Forming)"},{"type":"table","head":["नदी (River)","उद्गम (Origin)","विशेष तथ्य (Key Facts)"],"body":[["महानदी (Mahanadi)","सिहावा पर्वत (छत्तीसगढ़)","इस पर विश्व का सबसे लंबा ''हीराकुंड बांध'' (Hirakud Dam) स्थित है।"],["गोदावरी (Godavari)","त्र्यंबकेश्वर (नासिक, महाराष्ट्र)","दक्षिण भारत की सबसे लंबी नदी। इसे ''दक्षिण गंगा'' (Dakshin Ganga) या ''वृद्ध गंगा'' भी कहा जाता है।"],["कृष्णा (Krishna)","महाबलेश्वर (महाराष्ट्र)","प्रमुख सहायक नदियां: तुंगभद्रा, भीमा और मूसी।"],["कावेरी (Kaveri)","ब्रह्मगिरी पहाड़ियाँ (कर्नाटक)","इसे ''दक्षिण भारत की गंगा'' (Ganga of the South) कहा जाता है। यह शिवसमुद्रम जलप्रपात बनाती है।"]],"instruction":"पूर्व की ओर बहने वाली सभी प्रमुख नदियां बंगाल की खाड़ी में गिरती हैं और विशाल डेल्टा बनाती हैं।"},{"type":"fact_card","title":"महत्वपूर्ण परीक्षा तथ्य (Key Exam Facts)","facts":["भारत की सबसे लंबी नदी (Longest River): गंगा (2525 किमी)।","भारत का सबसे बड़ा नदी बेसिन (Largest Basin): गंगा बेसिन।","बिहार का शोक (Sorrow of Bihar): कोसी नदी (Kosi), अपने मार्ग बदलने के लिए कुख्यात।","बंगाल का शोक (Sorrow of Bengal): दामोदर नदी (Damodar)।","भ्रंश घाटी (Rift Valley) से होकर बहने वाली नदियां: नर्मदा, ताप्ती और दामोदर।"],"icon":"🌊"},{"type":"mnemonic","topic":"प्रायद्वीपीय नदियों का क्रम (उत्तर से दक्षिण)","visual":"🧠","trick":"Maha Goda Krishna Kaveri","explanation":"उत्तर से दक्षिण की ओर नदियों का सही क्रम: महानदी (Maha) -> गोदावरी (Goda) -> कृष्णा (Krishna) -> कावेरी (Kaveri)।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"भागीरथी और अलकनंदा नदियां कहाँ मिलकर ''गंगा'' कहलाती हैं?","options":["रुद्रप्रयाग","देवप्रयाग","कर्णप्रयाग","विष्णुप्रयाग"],"correct":"देवप्रयाग","strategy":"पंच प्रयागों में सबसे महत्वपूर्ण देवप्रयाग है, जहाँ भागीरथी और अलकनंदा का संगम होता है।"},{"type":"pyq","exam":"UPSC Prelims","year":2015,"question":"निम्नलिखित में से कौन सी नदी भ्रंश घाटी (Rift Valley) से होकर बहती है?","options":["गोदावरी","नर्मदा","कृष्णा","कावेरी"],"correct":"नर्मदा","strategy":"नर्मदा और ताप्ती भारत की प्रमुख नदियां हैं जो विंध्य और सतपुड़ा पर्वतमाला के बीच भ्रंश घाटी में बहती हैं।"},{"type":"pyq","exam":"UPPSC Prelims","year":2020,"question":"तिब्बत में मानसरोवर झील के पास से कौन सी नदी निकलती है?","options":["सिंधु (Indus)","सतलज (Sutlej)","ब्रह्मपुत्र (Brahmaputra)","उपरोक्त सभी"],"correct":"उपरोक्त सभी","strategy":"सिंधु, सतलज और ब्रह्मपुत्र तीनों का उद्गम मानसरोवर झील (तिब्बत) के निकट से होता है।"},{"type":"pyq","exam":"BPSC Prelims","year":2019,"question":"किस नदी को ''दक्षिण गंगा'' (Dakshin Ganga) के नाम से जाना जाता है?","options":["कावेरी","कृष्णा","गोदावरी","महानदी"],"correct":"गोदावरी","strategy":"अपने बड़े आकार और विस्तार के कारण गोदावरी को दक्षिण गंगा या वृद्ध गंगा कहा जाता है।"},{"type":"pyq","exam":"SSC CGL","year":2022,"question":"तिब्बत में ''त्संगपो'' (Tsangpo) के नाम से जानी जाने वाली नदी भारत में किस नाम से प्रवेश करती है?","options":["गंगा","ब्रह्मपुत्र","तीस्ता","कोसी"],"correct":"ब्रह्मपुत्र","strategy":"त्संगपो नदी जब अरुणाचल प्रदेश (भारत) में प्रवेश करती है, तो इसे दिहांग और फिर असम में ब्रह्मपुत्र कहा जाता है।"},{"type":"exam_pattern","topic":"Indian Rivers Trend Analysis","analysis":"MPPSC 2026 Trend Analysis","stats":["उद्गम और मुहाना (Origin/Outflow): 1-2 प्रश्न पक्का।","सहायक नदियां (Tributaries Matching): 1 प्रश्न (विशेषकर यमुना और गोदावरी की)।","प्रयाग और भ्रंश घाटी (Conceptual Facts): उच्च संभावना।"],"trend":"आयोग अब सीधे सवालों के बजाय नदियों का उत्तर-से-दक्षिण क्रम (North to South sequence) और ''बाएँ/दाएँ तट'' (Left/Right bank) की सहायक नदियों पर प्रश्न पूछ रहा है।"}],"conclusion":"नदियों का टॉपिक भूगोल की रीढ़ है। इसे रटने के बजाय, भारत के एक ''Blank Map'' पर नदियों का उद्गम और मार्ग खुद से ड्रा (Draw) करें। याद रखें, ''देवप्रयाग'' में गंगा का जन्म होता है और ''अमरकंटक'' से नर्मदा निकलती है। 2026 की परीक्षा में ये 2-3 अंक आपकी रैंक तय करेंगे! अपने लक्ष्य पर डटे रहें, जीत निश्चित है।\n\nFor more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"},"en":{"introduction":"Rivers are not just sources of water; they are the soul of our culture, economy, and geography. For students targeting ''nothing less than a rank'' in MPPSC, UPSC, and SSC exams, the River Systems of India is the ultimate ''High-Yield Topic''. The Indian Drainage System is broadly classified into two major categories: the **Himalayan Rivers** (which are snow-fed and perennial) and the **Peninsular Rivers** (which are rain-fed and seasonal). Let’s dive into a 100% exam-accurate analysis of these lifelines of India.","blocks":[{"type":"h2","text":"1. The Himalayan River Systems"},{"type":"h3","text":"Indus System"},{"type":"ul","items":["**Origin:** Near **Mansarovar Lake** (Bokhar Chu glacier) in Tibet.","**Outflow:** Drains into the **Arabian Sea** near Karachi.","**Major Tributaries:** It is joined by the ''Panchnad'' which includes the **Jhelum, Chenab, Ravi, Sutlej, and Beas**."]},{"type":"h3","text":"Ganga System"},{"type":"ul","items":["**Origin:** Rises as Bhagirathi from the **Gangotri Glacier** (Gomukh) in Uttarakhand.","**Prayags:** The Bhagirathi and Alaknanda rivers meet at **Devprayag**, after which it is called the ''Ganga''.","**Major Tributaries:** Right bank: **Yamuna** and **Son**; Left bank: Gomti, Ghaghara, **Gandak**, and **Kosi**.","**Outflow:** Merges with Brahmaputra and flows into the **Bay of Bengal** as Meghna, forming the Sundarbans Delta."]},{"type":"h3","text":"Brahmaputra System"},{"type":"ul","items":["**Origin:** **Chemayungdung Glacier** near Lake Mansarovar in Tibet.","**Different Names:** Known as **Tsangpo** in Tibet, **Dihang** in Arunachal Pradesh, Brahmaputra in Assam, and **Jamuna** in Bangladesh.","**Outflow:** Empties into the **Bay of Bengal**."]},{"type":"h2","text":"2. The Peninsular River Systems"},{"type":"h3","text":"West-Flowing Rivers (Estuary Forming)"},{"type":"table","head":["River","Origin","Key Facts"],"body":[["Narmada","Amarkantak, Madhya Pradesh","Flows through a Rift Valley between the Vindhya and Satpura ranges. It forms an Estuary, not a delta."],["Tapti (Tapi)","Multai, Betul, Madhya Pradesh","Flows in a rift valley south of Satpura and empties into the Gulf of Khambhat (Arabian Sea)."]],"instruction":"West-flowing rivers in the peninsula do not form deltas; they form estuaries due to the hard rocky terrain."},{"type":"h3","text":"East-Flowing Rivers (Delta Forming)"},{"type":"table","head":["River","Origin","Key Facts"],"body":[["Mahanadi","Sihawa highlands (Chhattisgarh)","The world''s longest earthen dam, the ''Hirakud Dam'', is built on it."],["Godavari","Trimbakeshwar (Nashik, Maharashtra)","Longest river in South India. It is often called ''Dakshin Ganga'' (Ganga of the South) or Vridha Ganga."],["Krishna","Mahabaleshwar (Maharashtra)","Major tributaries include Tungabhadra, Bhima, and Musi."],["Kaveri","Brahmagiri Hills (Karnataka)","Known as the ''Ganga of the South'' (cultural significance). It forms the Shivasamudram waterfalls."]],"instruction":"All major east-flowing rivers drain into the Bay of Bengal, forming extensive deltas."},{"type":"fact_card","title":"Key Exam Facts Checklist","facts":["Longest River of India: Ganga (2525 km).","Largest River Basin in India: Ganga Basin.","Sorrow of Bihar: Kosi River (notorious for frequently changing its course).","Sorrow of Bengal: Damodar River.","Rivers flowing through Rift Valleys: Narmada, Tapti, and Damodar."],"icon":"🌊"},{"type":"mnemonic","topic":"Sequence of Peninsular Rivers (North to South)","visual":"🧠","trick":"Maha Goda Krishna Kaveri","explanation":"Correct order from North to South: Mahanadi (Maha) -> Godavari (Goda) -> Krishna (Krishna) -> Kaveri (Kaveri)."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"Where do the Bhagirathi and Alaknanda rivers meet to form the ''Ganga''?","options":["Rudraprayag","Devprayag","Karnaprayag","Vishnuprayag"],"correct":"Devprayag","strategy":"Among the Panch Prayags, Devprayag is the most critical as it marks the official beginning of the Ganga River."},{"type":"pyq","exam":"UPSC Prelims","year":2015,"question":"Which of the following rivers flows through a rift valley?","options":["Godavari","Narmada","Krishna","Kaveri"],"correct":"Narmada","strategy":"Narmada and Tapti are the primary Indian rivers that flow through rift valleys due to faulting in the Earth''s crust."},{"type":"pyq","exam":"UPPSC Prelims","year":2020,"question":"Which of the following rivers originates near Mansarovar Lake in Tibet?","options":["Indus","Sutlej","Brahmaputra","All of the above"],"correct":"All of the above","strategy":"The Indus, Sutlej, and Brahmaputra all have their sources in close proximity to the Mansarovar Lake in Tibet."},{"type":"pyq","exam":"BPSC Prelims","year":2019,"question":"Which river is known as ''Dakshin Ganga''?","options":["Kaveri","Krishna","Godavari","Mahanadi"],"correct":"Godavari","strategy":"Due to its massive size, length, and catchment area comparable to the Ganga, Godavari is called the Dakshin Ganga."},{"type":"pyq","exam":"SSC CGL","year":2022,"question":"The river known as ''Tsangpo'' in Tibet enters India under which name?","options":["Ganga","Brahmaputra","Teesta","Kosi"],"correct":"Brahmaputra","strategy":"The Tsangpo enters India in Arunachal Pradesh as Dihang and is later called the Brahmaputra in Assam."},{"type":"exam_pattern","topic":"Indian Rivers Trend Analysis","analysis":"MPPSC 2026 Trend Analysis","stats":["Origin & Outflow Matching: 1-2 questions guaranteed.","Tributaries Matching (Left/Right Bank): 1 question (especially Yamuna/Godavari).","Conceptual Facts (Rift Valleys, Prayags): High Probability."],"trend":"Commissions are upgrading from direct questions to testing the North-to-South sequence of rivers and specific ''Left Bank vs. Right Bank'' tributaries."}],"conclusion":"The topic of rivers is the backbone of Indian Geography. Instead of rote learning, take a ''Blank Map of India'' and trace the origins, routes, and outflows of these rivers yourself. Remember, the Ganga is born at ''Devprayag'', and the mighty Narmada rises from ''Amarkantak''. Mastering these 2-3 marks will define your rank in the 2026 exams! Keep pushing, victory is yours.\n\nFor more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"}}', 'geography', 'https://npnjzfmywierjpxbnehw.supabase.co/storage/v1/object/public/card-images/rivers-of-india.png', 25, 1, 1772851334, 1772851414, 'blog', 'unit_3', 'Geography of India: Mountains, Forests, Rivers, Lakes', 0, 1, 0, 1, 0, 'Master the Himalayan and Peninsular River Systems of India for MPPSC, UPSC, and SSC. Comprehensive guide with origins, tributaries, PYQs, and high-yield exam fa...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('13cbe1db-b7a7-41c3-9d37-3b218068cb15', 'panch-prayag-origins-river-ganga-mppsc', 'Decoding the Panch Prayag: Origins of Ganga | पंच प्रयाग: गंगा का उद्गम (MPPSC 2026)', 'Master the Panch Prayag sequence, origin glaciers, and tributaries of the River Ganga for MPPSC and UPSC. A complete guide with mnemonics and high-yield PYQs.', '{"hi":{"introduction":"हिंदू धर्म और भारतीय भूगोल दोनों में ''प्रयाग'' (Prayag) का अर्थ है ''नदियों का पवित्र संगम'' (Confluence)। MPPSC और UPSC की परीक्षाओं में गंगा नदी के उद्गम और ''पंच प्रयाग'' (Panch Prayag) से हर साल सीधे प्रश्न पूछे जाते हैं। उत्तराखंड के गढ़वाल हिमालय में स्थित चार पवित्र धाम (Char Dham)—बद्रीनाथ, केदारनाथ, गंगोत्री और यमुनोत्री—इन प्रमुख नदियों के उद्गम स्थल हैं। इन सभी संगमों में एक बात समान है: **अलकनंदा (Alaknanda)** मुख्य नदी (Base River) है, जिसमें अन्य नदियां आकर मिलती हैं। आइए, उत्तर से दक्षिण (Upstream to Downstream) के क्रम में इन पंच प्रयागों को डिकोड करें।","blocks":[{"type":"fact_card","title":"Ranker''s Notes: प्रमुख ग्लेशियर और उद्गम","facts":["अलकनंदा नदी (Alaknanda): बद्रीनाथ के पास ''सतोपंथ ग्लेशियर'' (Satopanth Glacier) से निकलती है। यह सभी प्रयागों की ''रीढ़'' (Base) है।","मंदाकिनी नदी (Mandakini): केदारनाथ के पास ''चोराबारी ग्लेशियर'' (Chorabari Glacier) से निकलती है।","भागीरथी नदी (Bhagirathi): गंगोत्री के पास ''गोमुख'' (Gaumukh) से निकलती है।"],"icon":"🏔️"},{"type":"h2","text":"पंच प्रयाग का सटीक क्रम (North to South Sequence)"},{"type":"p","text":"परीक्षा में नदियों के संगम और उनका क्रम सबसे ज्यादा पूछा जाता है। अलकनंदा में मिलने वाली नदियों का उत्तर से दक्षिण क्रम इस प्रकार है:"},{"type":"table","head":["प्रयाग का नाम (Prayag)","संगम (Confluence of Rivers)","मुख्य तथ्य (Key Facts)"],"body":[["1. विष्णुप्रयाग (Vishnuprayag)","अलकनंदा + धौलीगंगा","यह सबसे उत्तरी (Northernmost) संगम है। धौलीगंगा नीती दर्रे के पास से निकलती है।"],["2. नंदप्रयाग (Nandaprayag)","अलकनंदा + नंदाकिनी","नंदाकिनी नदी त्रिशूल पर्वत के ग्लेशियरों से निकलती है।"],["3. कर्णप्रयाग (Karnaprayag)","अलकनंदा + पिंडर","पिंडर नदी (Pindari Glacier) पिंडारी ग्लेशियर से निकलती है। यह तेज बहाव वाली नदी है।"],["4. रुद्रप्रयाग (Rudraprayag)","अलकनंदा + मंदाकिनी","मंदाकिनी नदी केदारनाथ से आती है। यहाँ अलकनंदा का शांत और मंदाकिनी का तीव्र रूप देखने को मिलता है।"],["5. देवप्रयाग (Devaprayag)","अलकनंदा + भागीरथी","यह सबसे पवित्र संगम है। गंगोत्री से आने वाली भागीरथी यहीं अलकनंदा से मिलती है।"]],"instruction":"ध्यान दें: देवप्रयाग के बाद ही इस संयुक्त जलधारा को आधिकारिक रूप से ''गंगा'' (Ganga) के नाम से जाना जाता है।"},{"type":"highlight","level":"critical","text":"एग्जाम रूल: हमेशा याद रखें कि अलकनंदा नदी ''विष्णुप्रयाग'' से लेकर ''देवप्रयाग'' तक कॉमन (Common) रहती है!","icon":"📝"},{"type":"mnemonic","topic":"पंच प्रयाग याद रखने की ट्रिक (Mnemonic)","visual":"🧠","trick":"V N K R D (Very Nice King Rules Delhi)","explanation":"V=Vishnuprayag, N=Nandaprayag, K=Karnaprayag, R=Rudraprayag, D=Devaprayag. यह उत्तर से दक्षिण (North to South) का एकदम सही क्रम है।"},{"type":"h2","text":"Previous Year Questions (PYQs) & Expected MCQs"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"रुद्रप्रयाग (Rudraprayag) किन दो नदियों के संगम पर स्थित है?","options":["अलकनंदा और धौलीगंगा","अलकनंदा और मंदाकिनी","अलकनंदा और पिंडर","भागीरथी और मंदाकिनी"],"correct":"अलकनंदा और मंदाकिनी","strategy":"रुद्रप्रयाग चौथा संगम है जहाँ केदारनाथ से आने वाली मंदाकिनी, अलकनंदा में मिलती है।"},{"type":"pyq","exam":"UPSC Prelims","year":2015,"question":"किस स्थान पर भागीरथी और अलकनंदा नदियां मिलकर ''गंगा'' नदी का निर्माण करती हैं?","options":["रुद्रप्रयाग","देवप्रयाग","कर्णप्रयाग","विष्णुप्रयाग"],"correct":"देवप्रयाग","strategy":"देवप्रयाग अंतिम प्रयाग है। यहीं से पवित्र नदी आधिकारिक तौर पर गंगा कहलाती है।"},{"type":"pyq","exam":"UPPSC Prelims","year":2019,"question":"बद्रीनाथ का प्रसिद्ध मंदिर किस नदी के तट पर स्थित है?","options":["मंदाकिनी","भागीरथी","अलकनंदा","यमुना"],"correct":"अलकनंदा","strategy":"अलकनंदा नदी सतोपंथ ग्लेशियर से निकलती है और बद्रीनाथ धाम इसी के तट पर है, जबकि केदारनाथ मंदाकिनी के तट पर है।"},{"type":"pyq","exam":"BPSC Prelims","year":2020,"question":"उत्तर से दक्षिण के क्रम में कौन सा ''प्रयाग'' सबसे पहले आता है?","options":["विष्णुप्रयाग","नंदप्रयाग","कर्णप्रयाग","देवप्रयाग"],"correct":"विष्णुप्रयाग","strategy":"ट्रिक (V-N-K-R-D) याद करें। ''V'' से विष्णुप्रयाग सबसे उत्तर में स्थित है।"},{"type":"pyq","exam":"State PCS Expected","year":2026,"question":"मंदाकिनी नदी (Mandakini) का उद्गम स्थल कौन सा ग्लेशियर है?","options":["सतोपंथ ग्लेशियर","चोराबारी ग्लेशियर","गंगोत्री ग्लेशियर","पिंडारी ग्लेशियर"],"correct":"चोराबारी ग्लेशियर","strategy":"चोराबारी ग्लेशियर केदारनाथ के पास स्थित है, जो मंदाकिनी का स्रोत है। सतोपंथ अलकनंदा का स्रोत है।"},{"type":"exam_pattern","topic":"Himalayan Rivers Trend Analysis","analysis":"MPPSC 2026 Trend Analysis","stats":["संगम (Confluence Matching): 1 प्रश्न पक्का।","उत्तर से दक्षिण क्रम (Sequence): उच्च संभावना।","ग्लेशियर और धाम (Origin Mapping): 1 प्रश्न।"],"trend":"आयोग अब केवल ''गंगा कहाँ बनती है'' नहीं पूछता, बल्कि ग्लेशियरों (जैसे सतोपंथ) और ''प्रयागों के क्रम'' को सुमेलित (Match the Following) करने को कहता है।"}],"conclusion":"पंच प्रयाग का टॉपिक केवल रटने वाला नहीं है; इसे उत्तराखंड के मानचित्र (Map) पर विज़ुअलाइज़ करना सबसे आसान है। ''V-N-K-R-D'' की ट्रिक और अलकनंदा के ''कॉमन'' होने का फैक्ट आपके 2 अंक सुनिश्चित करेगा। अपने लक्ष्य पर फोकस रखें और 2026 की परीक्षा में सफलता प्राप्त करें।\n\nFor more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"},"en":{"introduction":"In both Hindu theology and Indian Geography, a ''Prayag'' signifies a sacred ''confluence'' of rivers. For MPPSC and UPSC aspirants, the origin of the River Ganga and the ''Panch Prayag'' (Five Confluences) is a highly reliable, rank-boosting topic. The Garhwal Himalayas of Uttarakhand host the four holy shrines (Char Dham)—Badrinath, Kedarnath, Gangotri, and Yamunotri—which are the source points of these mighty rivers. One crucial geographical fact unites all these confluences: the **Alaknanda** acts as the primary ''base river'' into which all other tributaries merge. Let''s decode the Panch Prayag strictly from North to South (upstream to downstream).","blocks":[{"type":"fact_card","title":"Ranker''s Notes: Origin Glaciers","facts":["Alaknanda River: Originates from the ''Satopanth Glacier'' above Badrinath. It is the backbone of all the Prayags.","Mandakini River: Originates from the ''Chorabari Glacier'' near Kedarnath.","Bhagirathi River: Originates from ''Gaumukh'' at the base of the Gangotri Glacier."],"icon":"🏔️"},{"type":"h2","text":"The Five Prayags (Strict Sequence from North to South)"},{"type":"p","text":"Examiners love testing the exact sequence and merging rivers. The sequence of rivers merging into the Alaknanda from North to South is as follows:"},{"type":"table","head":["Prayag (Confluence)","Merging Rivers","Key Exam Facts"],"body":[["1. Vishnuprayag","Alaknanda + Dhauliganga","The northernmost confluence. Dhauliganga originates near the Niti Pass."],["2. Nandaprayag","Alaknanda + Nandakini","The Nandakini river originates from the glaciers of Nanda Ghunti / Trishul."],["3. Karnaprayag","Alaknanda + Pindar","The Pindar river originates from the Pindari Glacier. It is known for its swift currents."],["4. Rudraprayag","Alaknanda + Mandakini","Mandakini flows down from Kedarnath. It meets the serene Alaknanda here."],["5. Devaprayag","Alaknanda + Bhagirathi","The holiest of the confluences. The Bhagirathi, originating from Gangotri, meets the Alaknanda here."]],"instruction":"Crucial Detail: It is only from Devaprayag onwards that the combined river is officially called the ''Ganga''."},{"type":"highlight","level":"critical","text":"Exam Rule: Always remember that the Alaknanda is the ''common'' river running through all five confluences, from Vishnuprayag down to Devaprayag!","icon":"📝"},{"type":"mnemonic","topic":"Trick to remember the Sequence of Prayags","visual":"🧠","trick":"V N K R D (Very Nice King Rules Delhi)","explanation":"V=Vishnuprayag, N=Nandaprayag, K=Karnaprayag, R=Rudraprayag, D=Devaprayag. This gives you the flawless North to South sequence."},{"type":"h2","text":"Previous Year Questions (PYQs) & Expected MCQs"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"Which two rivers meet at Rudraprayag?","options":["Alaknanda and Dhauliganga","Alaknanda and Mandakini","Alaknanda and Pindar","Bhagirathi and Mandakini"],"correct":"Alaknanda and Mandakini","strategy":"Rudraprayag is the 4th confluence where the Mandakini (flowing from Kedarnath) meets the Alaknanda."},{"type":"pyq","exam":"UPSC Prelims","year":2015,"question":"At which of the following places do the rivers Alaknanda and Bhagirathi merge to form the river Ganga?","options":["Rudraprayag","Devaprayag","Karnaprayag","Vishnuprayag"],"correct":"Devaprayag","strategy":"Devaprayag is the final confluence in the sequence. From this point forward, the river assumes the name ''Ganga''."},{"type":"pyq","exam":"UPPSC Prelims","year":2019,"question":"The famous shrine of Badrinath is located along the banks of which river?","options":["Mandakini","Bhagirathi","Alaknanda","Yamuna"],"correct":"Alaknanda","strategy":"Alaknanda originates from the Satopanth Glacier, and the Badrinath temple is situated on its banks. (Kedarnath is on the banks of Mandakini)."},{"type":"pyq","exam":"BPSC Prelims","year":2020,"question":"Arranging from North to South, which Prayag comes first?","options":["Vishnuprayag","Nandaprayag","Karnaprayag","Devaprayag"],"correct":"Vishnuprayag","strategy":"Recall the mnemonic V-N-K-R-D. ''V'' stands for Vishnuprayag, which is the northernmost confluence."},{"type":"pyq","exam":"State PCS Expected","year":2026,"question":"The Mandakini river originates from which of the following glaciers?","options":["Satopanth Glacier","Chorabari Glacier","Gangotri Glacier","Pindari Glacier"],"correct":"Chorabari Glacier","strategy":"The Chorabari Glacier is located near Kedarnath and is the source of the Mandakini. Satopanth is for Alaknanda."},{"type":"exam_pattern","topic":"Himalayan Rivers Trend Analysis","analysis":"MPPSC 2026 Trend Analysis","stats":["Confluence Matching: 1 guaranteed question.","North to South Sequence: High Probability.","Glacier & Shrine Mapping: 1 question."],"trend":"Commissions no longer just ask ''where Ganga is formed''. They prefer ''Match the Following'' questions pairing Glaciers to Rivers or ordering the Prayags from North to South."}],"conclusion":"The Panch Prayag is not a topic to merely memorize; it is best mastered by visualizing the river paths on a map of Uttarakhand. The ''V-N-K-R-D'' trick and knowing that the Alaknanda is the ''common'' river will secure your marks. Stay focused and claim your rank in the 2026 exams!\n\nFor more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"}}', 'geography', 'https://npnjzfmywierjpxbnehw.supabase.co/storage/v1/object/public/card-images/panch-prayag.jpg', 20, 1, 1773120709, 1773120725, 'blog', 'unit_3', 'Geography of India: Mountains, Forests, Rivers, Lakes', 0, 1, 0, 1, 0, 'Master the Panch Prayag sequence, origin glaciers, and tributaries of the River Ganga for MPPSC and UPSC. A complete guide with mnemonics and high-yield PYQs.', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('6a9a1027-62ab-4d9a-9fec-7e922a0c800c', 'indian-scientific-institutions-space-achievements-mppsc', 'Indian Scientific Institutions & Space Achievements | भारतीय वैज्ञानिक संस्थान और अंतरिक्ष उपलब्धियां (MPPSC 2026)', 'Comprehensive study guide on India''s scientific milestones covering ISRO, BARC, and DRDO. High-yield notes, cheat sheets, and PYQs for UPSC and MPPSC Unit 7.', '{"hi":{"introduction":"आज का भारत वैश्विक मंच पर विज्ञान और प्रौद्योगिकी (Science & Technology) में अग्रणी भूमिका निभा रहा है। चाहे चाँद के दक्षिणी ध्रुव पर तिरंगा फहराना हो या स्वदेशी मिसाइलें विकसित करना, हमारे वैज्ञानिक संस्थानों का योगदान अतुलनीय है। MPPSC (Unit 7) और UPSC की परीक्षाओं में ISRO, BARC और DRDO जैसे संस्थानों की स्थापना, उनके द्वारा विकसित तकनीक और मिशन से सीधे प्रश्न पूछे जाते हैं। आइए, इन संस्थाओं का ''Deep Dive'' एनालिसिस करें और परीक्षा के लिए एक सॉलिड ''Cheat Sheet'' तैयार करें।","blocks":[{"type":"h2","text":"1. ISRO (Indian Space Research Organisation)"},{"type":"p","text":"भारतीय अंतरिक्ष अनुसंधान संगठन (ISRO) भारत का गौरव है। इसकी जड़ें 1962 में स्थापित INCOSPAR (Indian National Committee for Space Research) में निहित हैं।"},{"type":"ul","items":["**स्थापना (Started):** 15 अगस्त 1969। (डॉ. विक्रम साराभाई को ''भारतीय अंतरिक्ष कार्यक्रम का जनक'' कहा जाता है)।","**विशेषज्ञता (Expertise):** अंतरिक्ष अनुप्रयोग (Space applications), उपग्रह संचार (Satellite communication), और प्रक्षेपण यान (Launch vehicles)।","**प्रथम उपग्रह (1st Satellite):** आर्यभट्ट (1975) - इसे सोवियत संघ की मदद से लॉन्च किया गया था।","**प्रक्षेपण यान (Launch Vehicles):** PSLV (Polar Satellite Launch Vehicle), GSLV, और GSLV-MkIII / LVM3 (भारत का सबसे भारी रॉकेट)।"]},{"type":"fact_card","title":"ISRO के प्रमुख मिशन (Key Missions)","facts":["चंद्रयान (Chandrayaan) 1, 2, 3: चंद्रयान-3 (2023) ने चंद्रमा के दक्षिणी ध्रुव पर सफल सॉफ्ट लैंडिंग की।","मंगलयान (Mangalyaan - MOM): पहले ही प्रयास में मंगल की कक्षा में पहुंचने वाला विश्व का पहला देश।","आदित्य-L1 (Aditya-L1): भारत का पहला सौर मिशन (Solar Mission)।","गगनयान (Gaganyaan): भारत का आगामी मानवयुक्त अंतरिक्ष मिशन (Manned Space Mission)।"],"icon":"🚀"},{"type":"h2","text":"2. BARC (Bhabha Atomic Research Centre)"},{"type":"p","text":"भाभा परमाणु अनुसंधान केंद्र (BARC) भारत के परमाणु कार्यक्रम का दिल है। इसका मुख्य उद्देश्य परमाणु ऊर्जा का शांतिपूर्ण उपयोग (Peaceful applications) सुनिश्चित करना है।"},{"type":"ul","items":["**स्थापना (Started):** 1954 में Atomic Energy Establishment Trombay (AEET) के रूप में। 1966 में डॉ. होमी जहांगीर भाभा (भारतीय परमाणु कार्यक्रम के जनक) के सम्मान में इसका नाम बदलकर BARC कर दिया गया।","**अनुसंधान रिएक्टर (Research Reactors):** अप्सरा (Apsara - एशिया का पहला रिएक्टर, 1956), सायरस (Cirus), ध्रुव (Dhruva) और पूर्णिमा (Purnima)।","**शांतिपूर्ण उपयोग (Peaceful Apps):** न्यूक्लियर मेडिसिन, खाद्य विकिरण (Food irradiation), और कृषि के लिए रेडियोधर्मी समस्थानिक (Radioactive isotopes)।","**पोखरण कनेक्शन:** डॉ. ए.पी.जे. अब्दुल कलाम और BARC के वैज्ञानिकों ने 1974 (Smiling Buddha) और 1998 (Operation Shakti) के परमाणु परीक्षणों में महत्वपूर्ण भूमिका निभाई थी।"]},{"type":"h2","text":"3. DRDO (Defence Research and Development Organisation)"},{"type":"p","text":"रक्षा अनुसंधान एवं विकास संगठन (DRDO) भारतीय सशस्त्र बलों को अत्याधुनिक हथियार और तकनीक प्रदान करता है।"},{"type":"ul","items":["**स्थापना (Started):** 1958।","**IGMDP:** इंटीग्रेटेड गाइडेड मिसाइल डेवलपमेंट प्रोग्राम (डॉ. कलाम के नेतृत्व में)। इसके तहत 5 मिसाइलें बनीं—पृथ्वी, अग्नि, त्रिशूल, नाग, और आकाश।","**प्रमुख मिसाइलें:** अग्नि V (Agni V - 5000 किमी से अधिक रेंज वाली इंटरकॉन्टिनेंटल बैलिस्टिक मिसाइल), ब्रह्मोस (BrahMos - सुपरसोनिक क्रूज मिसाइल), पृथ्वी (Short-range Ballistic)।","**अन्य उपलब्धियां:** अर्जुन (Arjun MBT - Main Battle Tank), तेजस (Tejas - Light Combat Aircraft), और नेत्रा (Netra - AEW&C रडार सिस्टम)।"]},{"type":"mnemonic","topic":"IGMDP मिसाइलों को याद रखने की ट्रिक","visual":"🧠","trick":"PATNA (पटना)","explanation":"P = Prithvi (पृथ्वी), A = Agni (अग्नि), T = Trishul (त्रिशूल), N = Nag (नाग), A = Akash (आकाश)।"},{"type":"h2","text":"Exam Quick Notes: Cheat Sheet"},{"type":"table","head":["संस्थान (Institution)","स्थापना वर्ष (Founding Date)","विशेषज्ञता (Expertise)","प्रथम आविष्कार/माइलस्टोन"],"body":[["ISRO","15 अगस्त 1969","Space Tech & Satellites","आर्यभट्ट उपग्रह (1975)"],["BARC","1954 (AEET के रूप में)","Peaceful Nuclear Energy","अप्सरा रिएक्टर (1956)"],["DRDO","1958","Defence Systems & Missiles","IGMDP मिसाइलें (1983 से शुरू)"]],"instruction":"इस टेबल को एग्जाम से पहले 5 मिनट में रिवाइज करें।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"भारतीय अंतरिक्ष कार्यक्रम (Indian Space Programme) का जनक किसे कहा जाता है?","options":["डॉ. ए.पी.जे. अब्दुल कलाम","डॉ. विक्रम साराभाई","डॉ. होमी जहांगीर भाभा","सतीश धवन"],"correct":"डॉ. विक्रम साराभाई","strategy":"विक्रम साराभाई ने भारत में अंतरिक्ष अनुसंधान की नींव रखी थी। भाभा परमाणु कार्यक्रम के जनक हैं और कलाम मिसाइल कार्यक्रम के।"},{"type":"pyq","exam":"UPSC Prelims","year":2014,"question":"अग्नि-V (Agni-V) मिसाइल की मारक क्षमता (Range) लगभग कितनी है?","options":["2000 किमी","3000 किमी","4000 किमी","5000 किमी से अधिक"],"correct":"5000 किमी से अधिक","strategy":"अग्नि-V एक अंतरमहाद्वीपीय बैलिस्टिक मिसाइल (ICBM) है, जिसकी रेंज 5000+ किमी है, जो इसे भारत का सबसे घातक हथियार बनाती है।"},{"type":"pyq","exam":"UPPSC Prelims","year":2019,"question":"एशिया का पहला अनुसंधान रिएक्टर (Research Reactor) कौन सा है?","options":["ध्रुव","सायरस","अप्सरा","कामिनी"],"correct":"अप्सरा (Apsara)","strategy":"अप्सरा रिएक्टर 1956 में भाभा परमाणु अनुसंधान केंद्र (Trombay) में स्थापित किया गया था।"},{"type":"pyq","exam":"SSC CGL","year":2022,"question":"तेजस (Tejas) क्या है?","options":["मुख्य युद्धक टैंक (MBT)","हल्का लड़ाकू विमान (LCA)","राडार प्रणाली","परमाणु पनडुब्बी"],"correct":"हल्का लड़ाकू विमान (LCA)","strategy":"तेजस एक स्वदेशी लाइट कॉम्बैट एयरक्राफ्ट (Light Combat Aircraft) है जिसे DRDO और HAL द्वारा विकसित किया गया है।"},{"type":"exam_pattern","topic":"Science & Tech Trend Analysis","analysis":"MPPSC 2026 Trend Analysis","stats":["ISRO Missions (Chandrayaan/Aditya-L1): 1-2 प्रश्न पक्का।","संस्थानों की स्थापना और मुख्यालय: उच्च संभावना।","DRDO Missiles (Range & Type): 1 प्रश्न।"],"trend":"आयोग अब केवल ''नाम'' नहीं पूछता, बल्कि तकनीक की ''रेंज'' (जैसे मिसाइल की मारक क्षमता) और ''लॉन्च व्हीकल'' (जैसे चंद्रयान-3 के लिए LVM3) पर गहराई से प्रश्न पूछ रहा है।"}],"conclusion":"दोस्तों, विज्ञान और तकनीक वह क्षेत्र है जहाँ भारत ने असंभव को संभव कर दिखाया है। ISRO की सफलता, DRDO की सुरक्षा ढाल और BARC की ऊर्जा क्रांति हमारे देश की रीढ़ हैं। इन माइलस्टोन्स को केवल परीक्षा के लिए नहीं, बल्कि एक भारतीय होने के गर्व के साथ पढ़ें। 2026 की परीक्षा में यहाँ से आपके 2-3 अंक बिल्कुल पक्के हैं!\n\nFor more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"},"en":{"introduction":"Today, India stands as a global powerhouse in Science & Technology. Whether it’s planting our flag on the lunar South Pole or developing state-of-the-art indigenous defense systems, the contributions of our scientific institutions are unparalleled. For MPPSC (Unit 7) and UPSC aspirants, the establishment, technologies, and missions of institutions like ISRO, BARC, and DRDO are absolute ''High-Yield Topics''. Let’s take a ''Deep Dive'' into these organizations and prepare a solid ''Cheat Sheet'' for your exams.","blocks":[{"type":"h2","text":"1. ISRO (Indian Space Research Organisation)"},{"type":"p","text":"ISRO is the pride of India''s scientific community. Its roots trace back to INCOSPAR (Indian National Committee for Space Research) established in 1962."},{"type":"ul","items":["**Started:** August 15, 1969. (Dr. Vikram Sarabhai is revered as the ''Father of the Indian Space Programme'').","**Expertise:** Space applications, Satellite communication, and Launch vehicles.","**1st Satellite:** Aryabhata (1975) - Launched with the assistance of the Soviet Union.","**Launch Vehicles:** PSLV (Workhorse of ISRO), GSLV, and GSLV-MkIII / LVM3 (India''s heaviest operational rocket)."]},{"type":"fact_card","title":"Key Missions of ISRO","facts":["Chandrayaan 1, 2, 3: Chandrayaan-3 (2023) made history with a successful soft landing on the Moon''s South Pole.","Mangalyaan (MOM): Made India the first nation in the world to reach Martian orbit in its maiden attempt.","Aditya-L1: India''s first dedicated Solar Mission.","Gaganyaan: India''s highly anticipated upcoming Manned Space Mission."],"icon":"🚀"},{"type":"h2","text":"2. BARC (Bhabha Atomic Research Centre)"},{"type":"p","text":"BARC is the beating heart of India''s nuclear program, focusing strictly on harnessing nuclear energy for peaceful applications."},{"type":"ul","items":["**Started:** Established in 1954 as Atomic Energy Establishment Trombay (AEET). Renamed in 1966 to honor Dr. Homi J. Bhabha (Father of the Indian Nuclear Programme).","**Research Reactors:** Apsara (Asia''s first, 1956), Cirus, Dhruva, and Purnima.","**Peaceful Applications:** Advancements in Nuclear medicine, food irradiation, and the use of radioactive isotopes for agriculture.","**The Pokhran Connection:** Scientists from BARC, alongside legends like A.P.J. Abdul Kalam, played pivotal roles in the nuclear tests of 1974 (Smiling Buddha) and 1998 (Operation Shakti)."]},{"type":"h2","text":"3. DRDO (Defence Research and Development Organisation)"},{"type":"p","text":"DRDO empowers the Indian Armed Forces with cutting-edge indigenous weapons, radars, and combat systems."},{"type":"ul","items":["**Started:** 1958.","**IGMDP:** Integrated Guided Missile Development Programme (conceived by Dr. Kalam). It developed 5 core missiles: Prithvi, Agni, Trishul, Nag, and Akash.","**Major Missiles:** Agni V (ICBM with a range of 5000+ km), BrahMos (Supersonic Cruise Missile developed with Russia), Prithvi (Short-range Ballistic).","**Other Achievements:** Arjun (Main Battle Tank), Tejas (Light Combat Aircraft - LCA), and Netra (AEW&C airborne radar system)."]},{"type":"mnemonic","topic":"Trick to remember IGMDP Missiles","visual":"🧠","trick":"PATNA","explanation":"P = Prithvi, A = Agni, T = Trishul, N = Nag, A = Akash."},{"type":"h2","text":"Exam Quick Notes: The Ultimate Cheat Sheet"},{"type":"table","head":["Institution","Founding Date","Core Expertise","First Major Milestone"],"body":[["ISRO","August 15, 1969","Space Tech & Satellites","Aryabhata Satellite (1975)"],["BARC","1954 (As AEET)","Peaceful Nuclear Energy","Apsara Reactor (1956)"],["DRDO","1958","Defence Systems & Missiles","IGMDP Missiles (1983)"]],"instruction":"Revise this table 5 minutes before entering the exam hall."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"Who is known as the Father of the Indian Space Programme?","options":["Dr. A.P.J. Abdul Kalam","Dr. Vikram Sarabhai","Dr. Homi J. Bhabha","Satish Dhawan"],"correct":"Dr. Vikram Sarabhai","strategy":"Dr. Sarabhai laid the foundation for space research in India. Bhabha is the father of the nuclear program, and Kalam is the missile man."},{"type":"pyq","exam":"UPSC Prelims","year":2014,"question":"What is the approximate range of the Agni-V missile?","options":["2000 km","3000 km","4000 km","More than 5000 km"],"correct":"More than 5000 km","strategy":"Agni-V is an Intercontinental Ballistic Missile (ICBM) with a strike range of over 5000 km, serving as India''s primary nuclear deterrent."},{"type":"pyq","exam":"UPPSC Prelims","year":2019,"question":"Which is Asia''s first nuclear research reactor?","options":["Dhruva","Cirus","Apsara","Kamini"],"correct":"Apsara","strategy":"The Apsara reactor was established in 1956 at Trombay (now BARC) with assistance from the UK."},{"type":"pyq","exam":"SSC CGL","year":2022,"question":"What is ''Tejas'' in the context of Indian Defence?","options":["Main Battle Tank","Light Combat Aircraft","Radar System","Nuclear Submarine"],"correct":"Light Combat Aircraft","strategy":"Tejas is a highly agile, multi-role Light Combat Aircraft (LCA) developed indigenously by DRDO and HAL."},{"type":"exam_pattern","topic":"Science & Tech Trend Analysis","analysis":"MPPSC 2026 Trend Analysis","stats":["ISRO Missions (Chandrayaan/Aditya-L1): 1-2 guaranteed questions.","Establishment Years & HQs: High Probability.","DRDO Missiles (Range & Payload Types): 1 question."],"trend":"Commissions are shifting from basic names to asking technical specifics like ''Launch Vehicles'' (e.g., LVM3 for Chandrayaan-3) and ''Missile Ranges''."}],"conclusion":"Aspirants, Science and Technology is a domain where India has consistently turned the impossible into the inevitable. The triumphs of ISRO, the defensive shield of DRDO, and the energy revolution by BARC form the backbone of modern India. Read these milestones not just to clear an exam, but with the pride of an Indian. Master this guide, and secure your 2-3 marks in the 2026 exams flawlessly!\n\nFor more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"}}', 'science_tech', 'https://npnjzfmywierjpxbnehw.supabase.co/storage/v1/object/public/card-images/isro.jpg', 25, 1, 1773463348, 1773992928, 'blog', 'unit_7', 'Science and Technology: Important Indian Scientific Research Institutions and Their Achievements', 0, 0, 0, 1, 0, 'Comprehensive study guide on India''s scientific milestones covering ISRO, BARC, and DRDO. High-yield notes, cheat sheets, and PYQs for UPSC and MPPSC Unit 7.', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('41e3e7e4-f446-4ea4-8baf-b93c1c8ef5b7', 'environment-ecosystem-biodiversity-premium-notes-mppsc', 'Decoding the Web of Life: Environment, Ecosystem & Biodiversity | पर्यावरण और पारिस्थितिकी (MPPSC/UPSC)', 'Premium study notes on Environment, Ecosystem, and Biodiversity for State PCS and UPSC. Covers Energy Flow, Conservation (In-situ/Ex-situ), MP hotspots, and PYQs.', '{"hi":{"introduction":"पृथ्वी पर जीवन एक जटिल और नाजुक जाल (Web of Life) की तरह बुना हुआ है। एक भावी प्रशासक (Administrator) के रूप में, आपको केवल नीतियां नहीं बनानी हैं, बल्कि ''सतत विकास'' (Sustainable Development) और ''पारिस्थितिकी'' के बीच संतुलन भी स्थापित करना है। MPPSC और UPSC की परीक्षाओं में ''पर्यावरण और जैव विविधता'' एक अत्यधिक स्कोरिंग विषय है। इस प्रीमियम ब्लॉग में हम पर्यावरण के घटकों, ऊर्जा प्रवाह, जैव विविधता के खतरों और संरक्षण के प्रयासों (विशेषकर मध्य प्रदेश के संदर्भ में) का 100% सटीक विश्लेषण करेंगे।","blocks":[{"type":"h2","text":"1. पर्यावरण (Environment) की अवधारणा"},{"type":"p","text":"पर्यावरण उन सभी भौतिक, रासायनिक और जैविक कारकों का योग है जो किसी जीव को घेरते हैं और उसे प्रभावित करते हैं।"},{"type":"ul","items":["**जैविक घटक (Biotic Components):** सभी जीवित चीजें (पेड़-पौधे, जानवर, सूक्ष्मजीव)।","**अजैविक घटक (Abiotic Components):** निर्जीव चीजें (तापमान, प्रकाश, जल, मृदा, हवा)।","**प्राकृतिक बनाम मानव-निर्मित:** वन और महासागर ''प्राकृतिक'' पर्यावरण हैं, जबकि कृषि भूमि, शहर और बांध ''मानव-निर्मित'' (Man-made) पर्यावरण हैं।"]},{"type":"h2","text":"2. पारिस्थितिकी तंत्र (Ecosystem)"},{"type":"p","text":"पारिस्थितिकी तंत्र प्रकृति की ''मूलभूत कार्यात्मक इकाई'' (Fundamental Ecological Unit) है। यह शब्द 1935 में ए.जी. टैन्सले (A.G. Tansley) द्वारा गढ़ा गया था।"},{"type":"ul","items":["**उत्पादक (Producers / Autotrophs):** हरे पौधे और शैवाल जो प्रकाश संश्लेषण (Photosynthesis) द्वारा अपना भोजन स्वयं बनाते हैं।","**उपभोक्ता (Consumers / Heterotrophs):** जो भोजन के लिए दूसरों पर निर्भर हैं (शाकाहारी, मांसाहारी, सर्वाहारी)।","**अपघटक (Decomposers / Saprotrophs):** कवक (Fungi) और जीवाणु (Bacteria) जो मृत जीवों को सड़ाकर पोषक तत्वों को वापस मिट्टी में मिलाते हैं।"]},{"type":"image_tag","content":""},{"type":"h2","text":"3. ऊर्जा प्रवाह और पोषक चक्र (Energy Flow & Nutrient Cycles)"},{"type":"highlight","level":"critical","text":"लिंडमैन का 10% नियम (Lindeman''s 10% Law): एक पोषण स्तर (Trophic Level) से दूसरे पोषण स्तर में केवल 10% ऊर्जा ही स्थानांतरित होती है; शेष 90% ऊर्जा ऊष्मा के रूप में नष्ट हो जाती है।","icon":"⚡"},{"type":"ul","items":["**खाद्य श्रृंखला (Food Chain):** ऊर्जा का एक रेखीय (Linear) प्रवाह (जैसे: घास -> टिड्डा -> मेंढक -> सांप -> बाज)।","**खाद्य जाल (Food Web):** कई खाद्य श्रृंखलाओं का आपस में जुड़ा हुआ जटिल जाल, जो पारिस्थितिकी तंत्र को स्थिरता (Stability) प्रदान करता है।","**पोषक चक्र (Biogeochemical Cycles):** कार्बन चक्र (प्रकाश संश्लेषण और श्वसन के माध्यम से) और नाइट्रोजन चक्र (राइजोबियम जैसे जीवाणुओं द्वारा नाइट्रोजन स्थिरीकरण)।"]},{"type":"h2","text":"4. जैव विविधता (Biodiversity) और इसका महत्व"},{"type":"p","text":"जैव विविधता (शब्द W.G. Rosen द्वारा दिया गया) पृथ्वी पर जीवन की विविधता है। इसे तीन स्तरों पर मापा जाता है:"},{"type":"ul","items":["**आनुवंशिक (Genetic):** एक ही प्रजाति के भीतर जीन की विविधता (जैसे भारत में आम की 1000+ किस्में)।","**प्रजाति (Species):** किसी क्षेत्र में विभिन्न प्रजातियों की संख्या (जैसे पश्चिमी घाट में उभयचरों की उच्च विविधता)।","**पारिस्थितिकी तंत्र (Ecosystem):** विभिन्न आवासों की विविधता (रेगिस्तान, वन, आर्द्रभूमि)।"]},{"type":"p","text":"**खतरे (Threats):** ''द इविल क्वार्टेट'' (The Evil Quartet) - 1. आवास का विनाश (सबसे बड़ा कारण), 2. अत्यधिक दोहन (Overexploitation), 3. विदेशी प्रजातियों का आक्रमण (Invasive species), 4. सह-विलुप्ति (Co-extinctions)।"},{"type":"h2","text":"5. संरक्षण के प्रयास (Conservation Efforts)"},{"type":"table","head":["संरक्षण का प्रकार","विवरण (Description)","प्रमुख उदाहरण (Examples)"],"body":[["स्व-स्थाने (In-situ)","जीवों का उनके ''प्राकृतिक आवास'' (On-site) में संरक्षण करना।","राष्ट्रीय उद्यान, वन्यजीव अभयारण्य, बायोस्फीयर रिजर्व (पचमढ़ी, पन्ना)।"],["बाह्य-स्थाने (Ex-situ)","जीवों को उनके प्राकृतिक आवास से बाहर (Off-site) संरक्षित करना।","चिड़ियाघर (Zoos), बीज बैंक (Seed Banks), वनस्पति उद्यान (Botanical Gardens)।"]],"instruction":"UPSC/MPPSC में In-situ और Ex-situ के उदाहरणों को छांटने (Classify) के प्रश्न बहुत आम हैं।"},{"type":"fact_card","title":"परीक्षा के लिए अति-महत्वपूर्ण तथ्य (High-Yield Facts)","facts":["कीस्टोन प्रजाति (Keystone Species): वह प्रजाति जिसका पारिस्थितिकी तंत्र पर प्रभाव उसकी संख्या से कहीं अधिक होता है (जैसे: बाघ, हाथी)।","संकेतक प्रजाति (Indicator Species): पर्यावरण के स्वास्थ्य को दर्शाने वाले जीव (जैसे: लाइकेन (Lichens) वायु प्रदूषण/SO2 के प्रति बहुत संवेदनशील होते हैं)।","भारत के जैव विविधता हॉटस्पॉट: 1. हिमालय, 2. पश्चिमी घाट (सर्वाधिक जैव विविधता), 3. इंडो-बर्मा, 4. सुंडालैंड (अंडमान-निकोबार)।","म.प्र. का गौरव: ''हार्डग्राउंड बारहसिंघा'' (कान्हा नेशनल पार्क की स्थानिक प्रजाति) और कूनो नेशनल पार्क में ''चीता'' (Cheetah) पुनर्वास।"],"icon":"🐯"},{"type":"mnemonic","topic":"In-situ संरक्षण याद रखने की ट्रिक","visual":"🧠","trick":"N-B-S (National Parks, Biosphere Reserves, Sanctuaries)","explanation":"NBS प्राकृतिक (Natural) रूप से होते हैं। बाकी सब (Zoo, Seed Bank) मानव निर्मित (Ex-situ) हैं।"},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"पारिस्थितिकी तंत्र (Ecosystem) शब्द का प्रयोग सर्वप्रथम किसने किया था?","options":["अर्नेस्ट हेकेल","ए.जी. टैन्सले","ई.पी. ओडम","चार्ल्स डार्विन"],"correct":"ए.जी. टैन्सले","strategy":"ए.जी. टैन्सले ने 1935 में यह शब्द दिया था। जबकि ''पारिस्थितिकी'' (Ecology) शब्द अर्नेस्ट हेकेल ने दिया था।"},{"type":"pyq","exam":"UPSC Prelims","year":2014,"question":"निम्नलिखित में से कौन सा ''स्व-स्थाने'' (In-situ) संरक्षण का उदाहरण नहीं है?","options":["बायोस्फीयर रिजर्व","राष्ट्रीय उद्यान","वनस्पति उद्यान (Botanical Garden)","पवित्र उपवन (Sacred Groves)"],"correct":"वनस्पति उद्यान (Botanical Garden)","strategy":"वनस्पति उद्यान कृत्रिम (मानव-निर्मित) क्षेत्र हैं जहाँ पौधों को बाहर से लाकर संरक्षित किया जाता है, अतः यह Ex-situ है।"},{"type":"pyq","exam":"UPPSC Prelims","year":2019,"question":"पारिस्थितिक तंत्र में ऊर्जा का प्रवाह (Energy Flow) हमेशा कैसा होता है?","options":["बहु-दिशिक (Multi-directional)","एक-दिशिक (Unidirectional)","चक्रीय (Cyclic)","द्वि-दिशिक (Bi-directional)"],"correct":"एक-दिशिक (Unidirectional)","strategy":"ऊर्जा हमेशा उत्पादक से उपभोक्ता की ओर एक ही दिशा में बहती है और कभी वापस नहीं लौटती (लिंडमैन का 10% नियम)।"},{"type":"pyq","exam":"BPSC Prelims","year":2020,"question":"वायु प्रदूषण (Air Pollution) का सबसे अच्छा जैविक सूचक (Biological Indicator) कौन सा है?","options":["फर्न","लाइकेन (Lichens)","शैवाल","कवक"],"correct":"लाइकेन (Lichens)","strategy":"लाइकेन हवा में मौजूद सल्फर डाइऑक्साइड (SO2) के प्रति अत्यधिक संवेदनशील होते हैं।"},{"type":"pyq","exam":"MPPSC Prelims","year":2022,"question":"भारत में ''प्रोजेक्ट टाइगर'' (Project Tiger) किस वर्ष शुरू किया गया था?","options":["1971","1972","1973","1980"],"correct":"1973","strategy":"बाघों की घटती आबादी को बचाने के लिए 1 अप्रैल 1973 को जिम कॉर्बेट नेशनल पार्क से इसे लॉन्च किया गया था।"},{"type":"exam_pattern","topic":"Environment & Ecology Trend Analysis","analysis":"MPPSC 2026 Trend Analysis","stats":["In-situ vs Ex-situ: 1 प्रश्न पक्का।","कानून और प्रोजेक्ट (Project Tiger, Wildlife Act): उच्च संभावना।","खाद्य श्रृंखला और ऊर्जा प्रवाह (Conceptual Facts): 1 प्रश्न।"],"trend":"आयोग अब पर्यावरण संरक्षण के बेसिक कॉन्सेप्ट्स के साथ-साथ ''करंट अफेयर्स'' (जैसे चीता प्रोजेक्ट, नए रामसर स्थल) को जोड़कर प्रश्न बना रहा है।"}],"conclusion":"पर्यावरण और जैव विविधता को रटना नहीं है, बल्कि अपने आस-पास की प्रकृति से जोड़कर देखना है। याद रखें कि ''In-situ'' मतलब घर में सुरक्षा (National Parks), और ''Ex-situ'' मतलब घर के बाहर सुरक्षा (Zoos)। इन बारीक अंतरों को समझें और परीक्षा में शत-प्रतिशत अंक प्राप्त करें। मेहनत करते रहें, भविष्य का प्रशासन आपकी राह देख रहा है!\n\nFor more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"},"en":{"introduction":"Life on Earth is intricately woven into a delicate ''Web of Life''. As a future administrator, your role isn''t merely to draft policies, but to strike a delicate balance between ''Sustainable Development'' and ''Ecological Conservation''. In exams like MPPSC and UPSC, Environment and Biodiversity is a highly rewarding, high-yield subject. In this premium blog, we will comprehensively decode the components of the environment, energy flow, threats to biodiversity, and conservation efforts (with a special focus on Madhya Pradesh) with 100% factual accuracy.","blocks":[{"type":"h2","text":"1. The Concept of Environment"},{"type":"p","text":"The environment is the sum total of all physical, chemical, and biological factors that surround and influence an organism."},{"type":"ul","items":["**Biotic Components:** All living things (Plants, animals, microorganisms).","**Abiotic Components:** Non-living things (Temperature, light, water, soil, air).","**Natural vs. Man-made:** Forests and oceans are ''Natural'' environments, whereas agricultural lands, cities, and dams constitute ''Man-made'' environments."]},{"type":"h2","text":"2. The Ecosystem"},{"type":"p","text":"An ecosystem is the ''Fundamental Ecological Unit'' of nature. The term was coined by A.G. Tansley in 1935."},{"type":"ul","items":["**Producers (Autotrophs):** Green plants and algae that manufacture their own food via photosynthesis.","**Consumers (Heterotrophs):** Organisms that depend on others for food (Herbivores, Carnivores, Omnivores).","**Decomposers (Saprotrophs):** Fungi and bacteria that break down dead organic matter, releasing nutrients back into the soil."]},{"type":"image_tag","content":""},{"type":"h2","text":"3. Energy Flow & Nutrient Cycles"},{"type":"highlight","level":"critical","text":"Lindeman''s 10% Law: Only 10% of the energy is transferred from one Trophic Level to the next; the remaining 90% is lost as heat.","icon":"⚡"},{"type":"ul","items":["**Food Chain:** A linear flow of energy (e.g., Grass -> Grasshopper -> Frog -> Snake -> Hawk).","**Food Web:** A complex, interconnected network of multiple food chains, which provides stability to the ecosystem.","**Biogeochemical Cycles:** The movement of nutrients like the Carbon Cycle (via photosynthesis and respiration) and the Nitrogen Cycle (nitrogen fixation by bacteria like Rhizobium)."]},{"type":"h2","text":"4. Biodiversity and its Importance"},{"type":"p","text":"Biodiversity (a term popularized by W.G. Rosen) is the variety of life on Earth. It is measured at three levels:"},{"type":"ul","items":["**Genetic:** Variety of genes within a single species (e.g., 1000+ varieties of mangoes in India).","**Species:** The number of different species in a given area (e.g., high amphibian diversity in the Western Ghats).","**Ecosystem:** The variety of habitats across a landscape (Deserts, forests, wetlands)."]},{"type":"p","text":"**Threats:** ''The Evil Quartet'' - 1. Habitat Loss (the biggest driver), 2. Overexploitation, 3. Alien/Invasive species invasion, 4. Co-extinctions."},{"type":"h2","text":"5. Conservation Efforts"},{"type":"table","head":["Conservation Type","Description","Key Examples"],"body":[["In-situ (On-site)","Conserving species within their ''Natural Habitats''.","National Parks, Wildlife Sanctuaries, Biosphere Reserves (e.g., Pachmarhi, Panna)."],["Ex-situ (Off-site)","Conserving species outside their natural habitats.","Zoos, Seed Banks, Botanical Gardens, Cryopreservation."]],"instruction":"Categorizing In-situ vs Ex-situ examples is a highly repeated question in UPSC/MPPSC."},{"type":"fact_card","title":"High-Yield Exam Facts","facts":["Keystone Species: A species whose impact on the ecosystem is disproportionately large relative to its abundance (e.g., Tiger, Elephant).","Indicator Species: Organisms that reflect the health of the environment (e.g., Lichens are highly sensitive to Air Pollution/SO2).","Biodiversity Hotspots of India: 1. Himalayas, 2. Western Ghats (Highest Biodiversity), 3. Indo-Burma, 4. Sundaland (Andaman & Nicobar).","Pride of MP: The ''Hardground Barasingha'' (endemic to Kanha National Park) and the historic Cheetah reintroduction in Kuno National Park."],"icon":"🐯"},{"type":"mnemonic","topic":"Trick to remember In-situ Conservation","visual":"🧠","trick":"N-B-S (National Parks, Biosphere Reserves, Sanctuaries)","explanation":"NBS are Natural. Everything else (Zoos, Seed Banks, Gardens) is artificial/Ex-situ."},{"type":"h2","text":"Previous Year Questions (PYQs)"},{"type":"pyq","exam":"MPPSC Prelims","year":2021,"question":"Who was the first to coin the term ''Ecosystem''?","options":["Ernst Haeckel","A.G. Tansley","E.P. Odum","Charles Darwin"],"correct":"A.G. Tansley","strategy":"A.G. Tansley coined the term ''Ecosystem'' in 1935. Note that the term ''Ecology'' was coined by Ernst Haeckel."},{"type":"pyq","exam":"UPSC Prelims","year":2014,"question":"Which one of the following is NOT an example of ''In-situ'' conservation?","options":["Biosphere Reserve","National Park","Botanical Garden","Sacred Groves"],"correct":"Botanical Garden","strategy":"Botanical gardens are artificial, man-made spaces where plants are conserved outside their natural habitat, making it Ex-situ."},{"type":"pyq","exam":"UPPSC Prelims","year":2019,"question":"The flow of energy in an ecosystem is always:","options":["Multi-directional","Unidirectional","Cyclic","Bi-directional"],"correct":"Unidirectional","strategy":"Energy always flows in one direction: from producers to consumers. It is never recycled back to the sun (Lindeman''s 10% law)."},{"type":"pyq","exam":"BPSC Prelims","year":2020,"question":"Which of the following is the best biological indicator of air pollution?","options":["Ferns","Lichens","Algae","Fungi"],"correct":"Lichens","strategy":"Lichens are extremely sensitive to sulfur dioxide (SO2) in the air. They do not grow in heavily polluted areas."},{"type":"pyq","exam":"MPPSC Prelims","year":2022,"question":"In which year was ''Project Tiger'' launched in India?","options":["1971","1972","1973","1980"],"correct":"1973","strategy":"Launched on April 1, 1973, from Jim Corbett National Park to protect the dwindling population of Bengal Tigers."},{"type":"exam_pattern","topic":"Environment & Ecology Trend Analysis","analysis":"MPPSC 2026 Trend Analysis","stats":["In-situ vs Ex-situ: 1 guaranteed question.","Laws & Projects (Project Tiger/Elephant): High Probability.","Energy Flow & Trophic Levels: 1 Conceptual Question."],"trend":"Commissions are blending static ecology concepts with ''Current Affairs'', such as recent additions to Ramsar sites or the Cheetah project."}],"conclusion":"Do not just rote-learn Environment and Ecology; observe it in the nature around you. Remember the core trick: ''In-situ'' means protection at home (National Parks), while ''Ex-situ'' means protection away from home (Zoos). Grasp these subtle differences and secure your 100% accuracy in the exam. Keep grinding, your future as an administrator awaits!\n\nFor more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"}}', 'environment', 'https://npnjzfmywierjpxbnehw.supabase.co/storage/v1/object/public/card-images/environment.png', 25, 1, 1773505758, 1773992913, 'blog', 'unit_7', 'Environment, Ecosystem, and Biodiversity', 0, 0, 0, 1, 0, 'Premium study notes on Environment, Ecosystem, and Biodiversity for State PCS and UPSC. Covers Energy Flow, Conservation (In-situ/Ex-situ), MP hotspots, and PYQ...', 'mppsc');
INSERT INTO "content_blogs" ("id", "slug", "title", "description", "content", "category", "image_url", "reading_time", "is_published", "created_at", "updated_at", "content_type", "unit_id", "topic_id", "is_premium", "is_free_access", "is_lite_access", "is_pro_access", "is_hidden", "excerpt", "exam_type") VALUES ('1ed8f081-42b3-4fac-92c7-f299f4d20119', 'mppsc-prelims-2026-new-exam-pattern-details', 'MPPSC Prelims 2026: New Exam Pattern & Complete Details | नया परीक्षा पैटर्न', 'Complete guide to the new MPPSC Prelims 2026 exam pattern, including the 3R-W negative marking system, qualifying marks, and exam date.', '{"hi":{"introduction":"MPPSC 2026 की तैयारी कर रहे सभी उम्मीदवारों के लिए एक बहुत बड़ा अपडेट है! आगामी प्रारंभिक परीक्षा (Prelims) के पैटर्न में बड़े बदलाव किए गए हैं। सबसे बड़ा बदलाव **नेगेटिव मार्किंग (Negative Marking)** का लागू होना है। 26 अप्रैल 2026 को होने वाली इस परीक्षा के लिए आपको एक नई रणनीति, बेहतर टाइम मैनेजमेंट और सटीक एक्यूरेसी (Accuracy) की आवश्यकता होगी। आइए इस नए पैटर्न को सरल टेबल फॉर्मेट में समझते हैं।","blocks":[{"type":"h2","text":"MPPSC Prelims 2026: महत्वपूर्ण तिथि (Important Date)"},{"type":"table","head":["इवेंट (Event)","महत्वपूर्ण तिथि (Important Date)"],"body":[["आगामी MPPSC प्रारंभिक परीक्षा 2026","26 अप्रैल 2026 (26 April 2026)"]],"instruction":"इस तारीख को अपने स्टडी टेबल पर मार्क कर लें!"},{"type":"h2","text":"नया परीक्षा पैटर्न और मार्किंग स्कीम (New Exam Pattern)"},{"type":"p","text":"प्रारंभिक परीक्षा में हमेशा की तरह दो पेपर होंगे, लेकिन इस बार अंकों और नेगेटिव मार्किंग के नियमों में बड़ा बदलाव है:"},{"type":"table","head":["Exam Info","Paper 1 (General Studies)","Paper 2 (CSAT / General Aptitude)"],"body":[["कुल अंक (Total Marks)","300 Marks","300 Marks"],["कुल प्रश्न (Total Questions)","100 Questions (हर प्रश्न 3 मार्क्स का)","100 Questions (हर प्रश्न 3 मार्क्स का)"],["समय (Time Duration)","2 Hours (घंटे)","2 Hours (घंटे)"],["नेगेटिव मार्किंग (Negative Marking)","Yes, 1 मार्क कटेगा हर गलत उत्तर पर (3R-W)","Yes, 1 मार्क कटेगा हर गलत उत्तर पर (3R-W)"],["क्वालीफाइंग मार्क्स (UR & UR Female)","Minimum 40% लाना अनिवार्य है","Minimum 40% लाना अनिवार्य है"],["क्वालीफाइंग मार्क्स (SC/ST/OBC/EWS/Divyang)","Minimum 30% लाना अनिवार्य है","Minimum 30% लाना अनिवार्य है"],["पेपर की भूमिका (Role of Paper)","इसके मार्क्स के आधार पर फाइनल कट-ऑफ और मेरिट बनेगी","यह पेपर सिर्फ Qualifying है, इसके मार्क्स मेरिट में नहीं जुड़ेंगे"]],"instruction":"नोट: राज्य वन सेवा (State Forest Service) के लिए दोनों पेपर (Paper 1 + Paper 2) के अंक मेरिट में जोड़े जाते हैं।"},{"type":"highlight","level":"critical","text":"गेम चेंजर (The Game Changer): 3R-W फॉर्मूला! इसका मतलब है कि आपको हर सही उत्तर (Right) के लिए 3 अंक मिलेंगे और हर गलत उत्तर (Wrong) के लिए 1 अंक काट लिया जाएगा। अब ''तुक्का'' लगाना बहुत भारी पड़ सकता है!","icon":"⚠️"},{"type":"h2","text":"सफलता की रणनीति: मॉक टेस्ट का महत्व"},{"type":"p","text":"नेगेटिव मार्किंग के आने से अब परीक्षा केवल ज्ञान की नहीं, बल्कि ''एक्यूरेसी'' (Accuracy) और ''टाइम मैनेजमेंट'' की भी हो गई है। सही दिशा में प्रैक्टिस करने के लिए केवल MPPSC के सर्वश्रेष्ठ टेस्ट सीरीज ही आपकी मदद कर सकते हैं।"},{"type":"ul","items":["**200+ Premium Tests:** अपनी तैयारी को धार देने के लिए नए पैटर्न (नेगेटिव मार्किंग के साथ) पर आधारित 200 से अधिक प्रीमियम टेस्ट्स लगाएं।","**अपनी गलतियों को पहचानें:** 3R-W फॉर्मूले के कारण, आपको यह सीखना होगा कि कौन से प्रश्न छोड़ने हैं (Art of Skipping)।","**टाइम मैनेजमेंट:** 120 मिनट में 100 प्रश्न हल करने की स्पीड और एक्यूरेसी मॉक टेस्ट्स से ही विकसित होगी।"]}],"conclusion":"26 अप्रैल 2026 आपका लक्ष्य है। नए पैटर्न से घबराने के बजाय इसे अपनी ताकत बनाएं। शानदार टेस्ट सीरीज के साथ आज ही अपना अभ्यास शुरू करें। For more in-depth, exam-ready notes, mock tests, and interactive study guides, visit mppsc.zenscroll.app!"},"en":{"introduction":"A massive update for all aspirants targeting MPPSC 2026! The upcoming Preliminary Examination has introduced a major change in its pattern—the implementation of **Negative Marking**. With the exam scheduled for 26th April 2026, you will now need a new strategy, impeccable time management, and pinpoint accuracy. Let’s decode this new pattern in a simple table format.","blocks":[{"type":"h2","text":"MPPSC Prelims 2026: Important Date"},{"type":"table","head":["Event","Important Date"],"body":[["Upcoming MPPSC Prelims Exam 2026","26 April 2026"]],"instruction":"Mark this date on your study calendar immediately!"},{"type":"h2","text":"New Exam Pattern & Marking Scheme"},{"type":"p","text":"The Prelims will still consist of two papers, but there is a significant shift in the weightage and the penalty for incorrect answers:"},{"type":"table","head":["Exam Info","Paper 1 (General Studies)","Paper 2 (CSAT / General Aptitude)"],"body":[["Total Marks","300 Marks","300 Marks"],["Total Questions","100 Questions (3 marks per question)","100 Questions (3 marks per question)"],["Time Duration","2 Hours","2 Hours"],["Negative Marking","Yes, 1 mark deducted per wrong answer (3R-W)","Yes, 1 mark deducted per wrong answer (3R-W)"],["Qualifying Marks (UR & UR Female)","Minimum 40% is compulsory","Minimum 40% is compulsory"],["Qualifying Marks (SC/ST/OBC/EWS/Divyang)","Minimum 30% is compulsory","Minimum 30% is compulsory"],["Role of the Paper","Marks will decide the final cut-off and merit list","This paper is only Qualifying; marks will not be added to merit"]],"instruction":"Note: For the State Forest Service Exam, marks from both Paper 1 and Paper 2 are added to determine the merit list."},{"type":"highlight","level":"critical","text":"The Game Changer: The 3R-W Formula! This means you will be awarded 3 marks for every Right (R) answer, and 1 mark will be deducted for every Wrong (W) answer. Blind guessing will now severely hurt your score!","icon":"⚠️"},{"type":"h2","text":"Strategy to Succeed: The Power of Mock Tests"},{"type":"p","text":"With the introduction of negative marking, the exam is no longer just a test of knowledge; it is a test of ''Accuracy'' and ''Time Management''. To practice in the right direction, you need the absolute best MPPSC test series."},{"type":"ul","items":["**200+ Premium Tests:** Sharpen your preparation by practicing with over 200 premium tests designed strictly on the new pattern (including the 3R-W marking scheme).","**Identify Your Weaknesses:** Because of the penalty, you must learn the ''Art of Skipping'' doubtful questions.","**Time Management:** Developing the speed to read, analyze, and accurately mark 100 questions in 120 minutes can only be achieved through rigorous mock testing."]}],"conclusion":"26th April 2026 is your target. Do not fear the new pattern; master it. Start practicing with the best test series today to build your accuracy. For more in-depth,PYQ Analysis, mock tests,FLT''s , CSAT ,Unit wise Tests and other features , interactive study guides, visit mppsc.zenscroll.app!"}}', 'general', 'https://npnjzfmywierjpxbnehw.supabase.co/storage/v1/object/public/card-images/mppsc-latest-pattern.png', 10, 1, 1774756613, 1774763185, 'blog', NULL, 'MPPSC Prelims 2026 Exam Pattern & Details', 0, 1, 0, 1, 0, 'Complete guide to the new MPPSC Prelims 2026 exam pattern, including the 3R-W negative marking system, qualifying marks, and exam date.', 'mppsc');
