INSERT INTO "mains_topics" ("id", "unit_id", "title_hi", "title_en", "display_order", "status", "created_at") VALUES ('e3c86f09-fff1-45f5-8920-50db29795363', '85d4ed47-56b0-4284-893c-6eb2f33f32ff', 'विषय: भारतीय ज्ञान-विज्ञान परंपरा, विकसित भारत @2047, आत्मनिर्भर भारत की संकल्पना, स्वर्णिम मध्यप्रदेश, अंतरिक्ष में भारत के बढ़ते कदम, मध्यप्रदेश का गौरवशाली इतिहास, पर्यावरण, विज्ञान, धर्म-आध्यात्म, विश्व ग्राम की संकल्पना, शिक्षा में गुणवत्ता, राष्ट्रीय शिक्षा नीति- 2020, परंपरागत कौशल आधारित व्यवसाय, आधुनिकीकरण, भूमंडलीकरण, उदारीकरण, कृत्रिम बुद्धिमता, परंपरागत खेल, सांस्कृतिक विरासत, सभ्यता एवं संस्कृति, धार्मिक-सांस्कृतिक पर्यटन, युवा नीति, योग एवं स्वास्थ्य, ई-मार्केटिंग, ई-कॉमर्स, नेतृत्व एवं विकास, सुशासन, नौकरशाही, लोकतंत्र में सिविल सेवाओं की भूमिका, जनजातीय विकास, स्वदेशी, स्वभाषा, राष्ट्रीयता के विभिन्न मुद्दे, राष्ट्रीय एकता एवं सामाजिक समरसता, सामुदायिक जीवन, सामाजिक सरोकार, नवीनीकरणीय ऊर्जा, सतत् विकास लक्ष्य, समावेशी विकास, ग्राहक जागरुकता आज की आवश्यकता, मादक पदार्थों का सेवन एवं दुष्प्रभाव, घरेलू हिंसा, बाह्य एवं आंतरिक सुरक्षा के मुद्दे, व्यवसायगत सरलता, सोशल मीडिया का मानव जीवन पर प्रभाव, गौरवशाली भारतीय संस्कृति, वसुधैव कुटुम्बकम्, मानवीय जीवन में संस्कार और जीवन मूल्य, वन नेशन वन हेल्थ सिस्टम / पॉलिसी - 2030', 'Topics: Indian knowledge-science tradition, Viksit Bharat @2047, Concept of Aatmanirbhar Bharat, Golden Madhya Pradesh, India''s growing steps in space, Glorious history of Madhya Pradesh, Environment, Science, Religion-spirituality, Concept of Global Village, Quality in education, National Education Policy- 2020, Traditional skill-based occupation, Modernization, Globalization, Liberalization, Artificial Intelligence, Traditional sports, Cultural heritage, Civilization and culture, Religious-cultural tourism, Youth policy, Yoga and health, E-marketing, E-commerce, Leadership and development, Good governance, Bureaucracy, Role of civil services in democracy, Tribal development, Swadeshi, Mother tongue, Various issues of nationality, National integration and social harmony, Community life, Social concerns, Renewable energy, Sustainable Development Goals, Inclusive development, Consumer awareness today''s need, Drug abuse and side effects, Domestic violence, Issues of external and internal security, Ease of doing business, Impact of social media on human life, Glorious Indian culture, Vasudhaiva Kutumbakam, Sanskars and life values in human life, One Nation One Health System / Policy - 2030', 2, 'published', 1777713473);
