INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HD4Z8M-A6ulR-r1FjPXwM', 'General Knowledge', 'भगवान बुद्ध को ज्ञान की प्राप्ति कहाँ हुई थी?', 'Where did Lord Buddha attain enlightenment?', 'बोधगया', 'Bodh Gaya', 95, 0, '{"facts":["बोधगया बिहार राज्य में स्थित है।","ज्ञान पीपल के पेड़ (बोधि वृक्ष) के नीचे मिला था।"],"factsEn":["Located in Bihar.","Enlightenment attained under the Bodhi (Peepal) tree."],"explanationHi":"गौतम बुद्ध ने वर्षों की तपस्या के बाद निरंजना नदी के तट पर ज्ञान प्राप्त किया था।","explanationEn":"Buddha attained enlightenment on the banks of the Niranjana river after rigorous meditation.","memoryTip":"बोध (Knowledge) + गया (Place) = बोधगया।","memoryTipEn":"Bodh means realization/knowledge.","related":["Buddhism","Sarnath","Lumbini"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('slGU4m_4Oo2Q0zg7CPN2a', 'General Knowledge', 'आर्य समाज की स्थापना किसने की?', 'Who founded the Arya Samaj?', 'स्वामी दयानंद सरस्वती', 'Swami Dayanand Saraswati', 90, 0, '{"facts":["स्थापना 1875 में बॉम्बे में हुई।","इन्होंने ''वेदों की ओर लौटो'' का नारा दिया।"],"factsEn":["Founded in 1875 in Bombay.","Gave the slogan ''Go back to Vedas''."],"explanationHi":"हिंदू धर्म में सुधार लाने और वैदिक परंपराओं को पुनर्जीवित करने के लिए आर्य समाज की स्थापना की गई।","explanationEn":"Founded to reform Hinduism and revive the Vedic traditions.","memoryTip":"आर्य (Noble) ज्ञान ''दयानंद'' (Compassion+Bliss) से आता है।","memoryTipEn":"Arya (Noble) + Dayanand.","related":["Brahmo Samaj","Satyarth Prakash"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('tp9gTi8vdQeFLPYzysrGW', 'General Knowledge', 'पंजाबी भाषा की लिपि कौनसी है?', 'What is the script of the Punjabi language?', 'गुरुमुखी', 'Gurmukhi', 85, 0, '{"facts":["गुरुमुखी का अर्थ है ''गुरु के मुख से''।","इसे दूसरे सिख गुरु, गुरु अंगद देव द्वारा मानकीकृत किया गया था।"],"factsEn":["Means ''from the mouth of the Guru''.","Standardized by Guru Angad Dev."],"explanationHi":"सिखों के धार्मिक ग्रंथ इसी लिपि में लिखे गए हैं।","explanationEn":"Sikh religious texts are predominantly written in this script.","memoryTip":"पंजाब में ''गुरु'' का महत्व है, इसलिए लिपि ''गुरुमुखी''।","memoryTipEn":"Gurus speak Punjabi -> Gurmukhi.","related":["Devanagari","Sikhism","Guru Angad Dev"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('K_G8FKCnCC_EA49gxzDpS', 'General Knowledge', 'भारत की मुख्य भूमि का दक्षिणतम किनारा कौनसा है?', 'Which is the southernmost point of mainland India?', 'कन्याकुमारी', 'Kanyakumari', 88, 0, '{"facts":["यह तमिलनाडु राज्य में स्थित है।","यहाँ तीन समुद्र (अरब सागर, बंगाल की खाड़ी, हिंद महासागर) मिलते हैं।"],"factsEn":["Located in Tamil Nadu.","Confluence of three oceans happens here."],"explanationHi":"यह भारतीय प्रायद्वीप का अंतिम दक्षिणी बिंदु है (मुख्य भूमि पर)।","explanationEn":"It is the tip of the Indian peninsula on the mainland.","memoryTip":"भारत माता के चरणों में ''कन्या'' (Kanya) निवास करती है।","memoryTipEn":"Mainland ends with a ''Kumari'' (girl/goddess).","related":["Indira Point","Cape Comorin"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('o4DRxfc4iFtsf4wgscUv2', 'General Knowledge', 'भारत में सबसे पहले सूर्य किस राज्य में निकलता है?', 'In which Indian state does the sun rise first?', 'अरुणाचल प्रदेश', 'Arunachal Pradesh', 92, 0, '{"facts":["डोंग घाटी में सबसे पहले सूर्योदय देखा जाता है।","अरुणाचल का अर्थ ही ''उगते सूर्य की भूमि'' है।"],"factsEn":["Dong valley sees the first sunrise.","Name translates to ''Land of dawn-lit mountains''."],"explanationHi":"भारत के सबसे पूर्वी छोर पर स्थित होने के कारण यहाँ सबसे पहले सूर्योदय होता है।","explanationEn":"Being the easternmost state, it receives the first sunlight in India.","memoryTip":"अरुण = सूर्य। इसलिए अरुणाचल में सबसे पहले सूर्य आता है।","memoryTipEn":"Arun means Sun in Hindi.","related":["Dong Valley","Easternmost point of India"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yKgO9krNP63ABPgjZCBad', 'General Science', 'इंसुलिन का प्रयोग किस बीमारी के उपचार में होता है?', 'Insulin is used in the treatment of which disease?', 'मधुमेह (Diabetes)', 'Diabetes', 95, 0, '{"facts":["इंसुलिन अग्न्याशय (Pancreas) द्वारा स्रावित होता है।","यह रक्त शर्करा (Blood Sugar) को नियंत्रित करता है।"],"factsEn":["Secreted by the Pancreas.","Regulates blood sugar levels."],"explanationHi":"मधुमेह के रोगियों में शरीर पर्याप्त इंसुलिन नहीं बनाता है, जिससे रक्त में ग्लूकोज बढ़ जाता है।","explanationEn":"In diabetes, the body doesn''t produce enough insulin, leading to high blood glucose.","memoryTip":"Insulin In-serts Sugar into cells.","memoryTipEn":"Insulin IN-serts Sugar into cells.","related":["Pancreas","Blood Sugar","Glucagon"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YB5_l61fc0M1qT5mdDkTY', 'General Knowledge', 'बिहू किस राज्य का प्रसिद्ध त्योहार है?', 'Bihu is a famous festival of which state?', 'असम', 'Assam', 89, 0, '{"facts":["यह एक फसल कटाई का त्योहार है।","वर्ष में तीन बार (रोंगाली, कंगाली, भोगाली बिहू) मनाया जाता है।"],"factsEn":["It is a harvest festival.","Celebrated three times a year."],"explanationHi":"असमिया नव वर्ष और वसंत के आगमन का प्रतीक है।","explanationEn":"Marks the Assamese New Year and the advent of Spring.","memoryTip":"असम की ''बहू'' (Bihu) चाय बनाती है।","memoryTipEn":"Assam tea is served with Bihu dance.","related":["Rongali Bihu","Assamese Culture"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aGRqRsla1mYgkOcRHLIKn', 'General Science', 'कौनसा विटामिन आंवले में प्रचुर मात्रा में मिलता है?', 'Which vitamin is abundantly found in Amla (Gooseberry)?', 'विटामिन C', 'Vitamin C', 90, 0, '{"facts":["विटामिन C का रासायनिक नाम एस्कॉर्बिक एसिड है।","यह प्रतिरक्षा प्रणाली (Immunity) को मजबूत करता है।"],"factsEn":["Chemical name is Ascorbic Acid.","Boosts the immune system."],"explanationHi":"खट्टे फलों में विटामिन C पाया जाता है, जो स्कर्वी रोग से बचाता है।","explanationEn":"Citrus fruits are rich in Vitamin C, which prevents Scurvy.","memoryTip":"C से खट्टा (Citrus), आंवला खट्टा होता है।","memoryTipEn":"C for Citrus and Colds.","related":["Scurvy","Ascorbic Acid"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('d6mjx6dXsMQVg62_v3TrF', 'General Knowledge', 'भारत का प्रथम गवर्नर जनरल कौन था?', 'Who was the first Governor-General of India?', 'विलियम बेंटिक', 'William Bentinck', 92, 0, '{"facts":["चार्टर एक्ट 1833 के तहत इन्हें यह पद मिला।","इन्होंने सती प्रथा (1829) पर प्रतिबंध लगाया था।"],"factsEn":["Appointed under the Charter Act of 1833.","Abolished the Sati practice in 1829."],"explanationHi":"बंगाल के गवर्नर जनरल के पद को बदलकर भारत का गवर्नर जनरल कर दिया गया था।","explanationEn":"The post of Governor-General of Bengal was redesignated as Governor-General of India.","memoryTip":"बेंटिक ने सती प्रथा को ''बैन'' (Ban) किया, वही पहले बने।","memoryTipEn":"Bentinck ''Banned'' Sati as the first pan-India Governor General.","related":["Lord Canning","Sati System","Charter Act 1833"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xxTrvk3C1YCCjne3SpM3O', 'General Knowledge', 'कागज का आविष्कार किस देश में हुआ?', 'In which country was paper invented?', 'चीन', 'China', 80, 0, '{"facts":["हान राजवंश के दौरान चाई लुन द्वारा आविष्कार किया गया था।","यह पहले शहतूत की छाल से बनाया गया था।"],"factsEn":["Invented by Cai Lun during the Han Dynasty.","Originally made from mulberry bark."],"explanationHi":"प्राचीन चीन में लेखन के लिए कागज का पहली बार निर्माण और उपयोग किया गया था।","explanationEn":"Paper was first manufactured and used for writing in ancient China.","memoryTip":"चीन (China) = कागज (Paper)।","memoryTipEn":"China -> Cai Lun -> Paper.","related":["Printing Press","Cai Lun"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NTP00pQ6A1-6ROf5TRezh', 'General Knowledge', 'गौतम बुद्ध का बचपन का नाम क्या था?', 'What was the childhood name of Gautam Buddha?', 'सिद्धार्थ', 'Siddhartha', 88, 0, '{"facts":["उनके पिता का नाम शुद्धोधन और माता का नाम मायादेवी था।","उनका जन्म लुंबिनी (नेपाल) में हुआ था।"],"factsEn":["Father was Suddhodana, Mother was Mayadevi.","Born in Lumbini, Nepal."],"explanationHi":"ज्ञान प्राप्ति से पहले उन्हें राजकुमार सिद्धार्थ के नाम से जाना जाता था।","explanationEn":"Before attaining enlightenment, he was known as Prince Siddhartha.","memoryTip":"जिसका लक्ष्य (अर्थ) सिद्ध हो गया हो = सिद्धार्थ।","memoryTipEn":"Siddhartha means ''he who has attained his goals''.","related":["Buddhism","Mahamaya","Suddhodana"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('42AHPD8jD5QjE8-iaE7jz', 'General Knowledge', 'भारत में सशस्त्र बलों का सर्वोच्च सेनापति कौन होता है?', 'Who is the Supreme Commander of the Armed Forces in India?', 'राष्ट्रपति', 'President', 95, 0, '{"facts":["संविधान के अनुच्छेद 53(2) के तहत यह अधिकार दिया गया है।","तीनों सेनाओं के प्रमुख राष्ट्रपति को रिपोर्ट करते हैं।"],"factsEn":["Mandated by Article 53(2) of the Constitution.","All three service chiefs report to the President."],"explanationHi":"भारत के राष्ट्रपति थल सेना, नौसेना और वायु सेना के औपचारिक प्रमुख होते हैं।","explanationEn":"The President of India is the formal head of the Army, Navy, and Air Force.","memoryTip":"देश का ''प्रथम नागरिक'' ही सेना का ''सर्वोच्च'' होगा।","memoryTipEn":"First Citizen = Supreme Commander.","related":["Chief of Defence Staff","Article 53"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('v4bn8ZBtQ3Ne2ulNYhGQS', 'General Science', 'रतौंधी किस विटामिन की कमी से होती है?', 'Night blindness is caused by the deficiency of which vitamin?', 'विटामिन A', 'Vitamin A', 94, 0, '{"facts":["विटामिन A का रासायनिक नाम रेटिनॉल (Retinol) hai।","गाजर और हरी पत्तेदार सब्जियां इसके अच्छे स्रोत हैं।"],"factsEn":["Chemical name is Retinol.","Carrots and leafy greens are good sources."],"explanationHi":"विटामिन ए आंखों के रेटिना को स्वस्थ रखने के लिए आवश्यक है।","explanationEn":"Vitamin A is essential for keeping the retina of the eyes healthy.","memoryTip":"A से आँख (Eye) की बीमारी रतौंधी।","memoryTipEn":"Vitamin A for ''A''mazing Vision.","related":["Retinol","Carrot","Vision"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MYVSmF8dty9lF0CUmpU0P', 'General Knowledge', 'पोंगल किस राज्य का त्योहार है?', 'Pongal is a festival of which state?', 'तमिलनाडु', 'Tamil Nadu', 87, 0, '{"facts":["यह चार दिनों तक चलने वाला फसल उत्सव है।","मुख्य रूप से सूर्य देवता को समर्पित है।"],"factsEn":["A four-day harvest festival.","Primarily dedicated to the Sun God."],"explanationHi":"मकर संक्रांति के समय तमिलनाडु में अच्छी फसल के लिए यह पर्व मनाया जाता है।","explanationEn":"Celebrated in Tamil Nadu during Makar Sankranti for a good harvest.","memoryTip":"तमिलनाडु में पोंगल खाया जाता है।","memoryTipEn":"Pongal is both a dish and a festival in TN.","related":["Jallikattu","Makar Sankranti","Onam"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8CCUfT9H1uhMgnTqVHwMl', 'General Knowledge', 'गिद्धा और भंगड़ा किस राज्य के लोक नृत्य हैं?', 'Giddha and Bhangra are folk dances of which state?', 'पंजाब', 'Punjab', 85, 0, '{"facts":["भंगड़ा पुरुषों द्वारा किया जाता है।","गिद्धा विशेष रूप से महिलाओं का लोक नृत्य है।"],"factsEn":["Bhangra is performed by men.","Giddha is specifically a women''s folk dance."],"explanationHi":"ये नृत्य मुख्य रूप से बैसाखी के त्योहार और फसल कटाई के दौरान किए जाते हैं।","explanationEn":"These dances are mainly performed during the Baisakhi festival and harvest season.","memoryTip":"पंजाब की ऊर्जा भंगड़ा और गिद्धा में दिखती है।","memoryTipEn":"Bhangra beats belong to Punjab.","related":["Baisakhi","Folk Dances of India"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('T8A2P4CMBaU6z3zq07Azi', 'General Knowledge', 'टेलीविजन का आविष्कार किसने किया?', 'Who invented the television?', 'जॉन लोगी बेयर्ड', 'John Logie Baird', 82, 0, '{"facts":["इन्होंने 1925 में मैकेनिकल टेलीविजन का प्रदर्शन किया था।","ये स्कॉटलैंड के इंजीनियर थे।"],"factsEn":["Demonstrated mechanical television in 1925.","He was a Scottish engineer."],"explanationHi":"उन्होंने पहली बार चलती हुई छवियों को प्रसारित करने में सफलता प्राप्त की थी।","explanationEn":"He successfully transmitted moving images for the first time.","memoryTip":"टीव्ही पर हम ''बर्ड'' (Baird) देखते हैं।","memoryTipEn":"Baird broadcasted the first TV pictures.","related":["Inventions","Radio transmission"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('cUkE8y_vluI45imVT3LOJ', 'General Knowledge', 'भारत की पहली महिला शासिका कौन थी?', 'Who was the first female ruler of India?', 'रजिया सुल्तान', 'Razia Sultana', 92, 0, '{"facts":["वह इल्तुतमिश की पुत्री थी।","उन्होंने 1236 से 1240 तक दिल्ली पर शासन किया।"],"factsEn":["She was the daughter of Iltutmish.","Ruled Delhi from 1236 to 1240."],"explanationHi":"वह दिल्ली सल्तनत (गुलाम वंश) की एकमात्र महिला शासिका थीं।","explanationEn":"She was the only female ruler of the Delhi Sultanate (Slave Dynasty).","memoryTip":"दिल्ली पर ''राज'' करने वाली पहली महिला ''रजिया''।","memoryTipEn":"Razia Ruled Royalty.","related":["Delhi Sultanate","Slave Dynasty","Iltutmish"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_uHM-9LXFpsdipiToRKMi', 'General Science', 'मछली किसकी सहायता से सांस लेती है?', 'With whose help does a fish breathe?', 'गलफड़ों (Gills)', 'Gills', 80, 0, '{"facts":["गलफड़े पानी में घुली हुई ऑक्सीजन को सोख लेते हैं।","पानी मुंह से अंदर जाता है और गलफड़ों से बाहर आता है।"],"factsEn":["Gills absorb dissolved oxygen from water.","Water enters the mouth and exits through gills."],"explanationHi":"गलफड़ों में रक्त वाहिकाएं होती हैं जो सीधे ऑक्सीजन ग्रहण करती हैं और कार्बन डाइऑक्साइड छोड़ती हैं।","explanationEn":"Blood vessels in the gills absorb oxygen directly and release carbon dioxide.","memoryTip":"गले में ''गलफड़े'' पानी छानते हैं।","memoryTipEn":"Gills Filter dissolved oxygen.","related":["Aquatic Respiration","Lungs"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XmmC1jo6CANl0TduQJyRf', 'General Knowledge', '''इंकलाब जिंदाबाद'' का नारा किसने दिया?', 'Who gave the slogan ''Inquilab Zindabad''?', 'भगत सिंह', 'Bhagat Singh', 96, 0, '{"facts":["मूल रूप से इसे हसरत मोहानी ने लिखा था, लेकिन भगत सिंह ने इसे लोकप्रिय बनाया।","इसका अर्थ है ''क्रांति अमर रहे''।"],"factsEn":["Originally coined by Hasrat Mohani, popularized by Bhagat Singh.","Means ''Long live the revolution''."],"explanationHi":"सेंट्रल असेंबली में बम फेंकने के बाद भगत सिंह और बटुकेश्वर दत्त ने यह नारा लगाया था।","explanationEn":"Shouted by Bhagat Singh and Batukeshwar Dutt after bombing the Central Assembly.","memoryTip":"क्रांति (Inquilab) के प्रतीक भगत सिंह।","memoryTipEn":"Bhagat Singh popularized Revolution (Inquilab).","related":["Hasrat Mohani","Indian Freedom Struggle"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('OoRmvQ7uhtLt4dUNozm9Z', 'General Knowledge', 'जलियांवाला बाग हत्याकांड कब व कहाँ हुआ?', 'When and where did the Jallianwala Bagh massacre take place?', '1919 ई., अमृतसर', '1919, Amritsar', 98, 0, '{"facts":["यह 13 अप्रैल 1919 को बैसाखी के दिन हुआ था।","जनरल डायर ने निहत्थी भीड़ पर गोलियां चलवाई थीं।"],"factsEn":["Happened on 13 April 1919 (Baisakhi day).","General Dyer ordered firing on an unarmed crowd."],"explanationHi":"लोग रॉलेट एक्ट और दो नेताओं (सत्यपाल और सैफुद्दीन किचलू) की गिरफ्तारी का विरोध करने जमा हुए थे।","explanationEn":"People gathered to protest the Rowlatt Act and the arrest of two leaders.","memoryTip":"13 अप्रैल 1919 को अमृतसर खून से रंग गया।","memoryTipEn":"1919 Amritsar Massacre.","related":["Rowlatt Act","General Dyer","Udham Singh"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dKyh7l9U-RFokMhhJzNob', 'General Knowledge', '1939 ई. में कांग्रेस छोड़ने के बाद सुभाषचंद्र बोस ने किस दल की स्थापना की?', 'Which party was founded by Subhash Chandra Bose after leaving Congress in 1939?', 'फॉरवर्ड ब्लॉक', 'Forward Bloc', 93, 0, '{"facts":["इसकी स्थापना वामपंथी विचारधारा को संगठित करने के लिए की गई थी।","गांधीजी के साथ वैचारिक मतभेद के कारण उन्होंने कांग्रेस छोड़ी।"],"factsEn":["Founded to consolidate the left-wing ideology.","He left Congress due to ideological differences with Gandhi."],"explanationHi":"त्रिपुरी अधिवेशन के बाद बोस ने अध्यक्ष पद से इस्तीफा दिया और ऑल इंडिया फॉरवर्ड ब्लॉक बनाया।","explanationEn":"After the Tripuri session, Bose resigned and formed the All India Forward Bloc.","memoryTip":"बोस हमेशा ''फॉरवर्ड'' (आगे) सोचते थे।","memoryTipEn":"Bose moved ''Forward'' out of Congress.","related":["Tripuri Session","Pattabhi Sitaramayya","INA"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('LUS63U9iOa643Z_AVSGfD', 'General Knowledge', '''पंजाब केसरी'' किसे कहा जाता है?', 'Who is known as ''Punjab Kesari''?', 'लाला लाजपत राय', 'Lala Lajpat Rai', 91, 0, '{"facts":["वे ''लाल-बाल-पाल'' की तिकड़ी के सदस्य थे।","साइमन कमीशन का विरोध करते हुए लाठीचार्ज में वे घायल हुए थे।"],"factsEn":["Part of the ''Lal-Bal-Pal'' trio.","Injured in a lathi charge while protesting the Simon Commission."],"explanationHi":"उनके साहस और पंजाब के प्रति योगदान के कारण उन्हें शेर-ए-पंजाब या पंजाब केसरी कहा गया।","explanationEn":"Known as the Lion of Punjab for his bravery and contribution.","memoryTip":"पंजाब का ''शेर'' (केसरी) = लाला जी।","memoryTipEn":"Kesari means Lion -> Lion of Punjab.","related":["Simon Commission","Lal Bal Pal"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('LYMZnHp-MFmHMppwmoeud', 'General Knowledge', 'सांडर्स की हत्या किसने की थी?', 'Who assassinated Saunders?', 'भगत सिंह', 'Bhagat Singh', 88, 0, '{"facts":["लाला लाजपत राय की मौत का बदला लेने के लिए हत्या की गई।","दिसंबर 1928 में लाहौर में हत्या की गई।"],"factsEn":["Assassinated to avenge the death of Lala Lajpat Rai.","Killed in Lahore in December 1928."],"explanationHi":"भगत सिंह, राजगुरु और चंद्रशेखर आजाद ने जेम्स ए. स्कॉट को मारने की योजना बनाई थी, लेकिन गलती से जॉन पी. सांडर्स को मार दिया।","explanationEn":"They intended to kill James A. Scott but mistakenly shot John P. Saunders.","memoryTip":"लाला जी के लाठीचार्ज का बदला सांडर्स को मारकर लिया गया।","memoryTipEn":"Revenge for Lala Lajpat Rai.","related":["Lala Lajpat Rai","Rajguru","Chandrashekhar Azad"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NaUj8iRJxaBV30Y4s96kq', 'General Knowledge', '1857 ई. के विद्रोह में किसने अपना बलिदान सबसे पहले दिया?', 'Who gave his sacrifice first in the revolt of 1857?', 'मंगल पांडे', 'Mangal Pandey', 95, 0, '{"facts":["वे बैरकपुर छावनी (बंगाल) में 34वीं बंगाल नेटिव इन्फैंट्री के सिपाही थे।","उन्हें 8 अप्रैल 1857 को फाँसी दी गई।"],"factsEn":["Sepoy in the 34th Bengal Native Infantry at Barrackpore.","Hanged on 8 April 1857."],"explanationHi":"उन्होंने गाय और सूअर की चर्बी वाले कारतूसों का उपयोग करने से मना कर दिया और ब्रिटिश अधिकारियों पर हमला किया।","explanationEn":"He refused to use greased cartridges and attacked British officers.","memoryTip":"1857 का ''मंगल'' (आरंभ) मंगल पांडे से हुआ।","memoryTipEn":"First spark of 1857 was Mangal.","related":["Revolt of 1857","Barrackpore Mutiny"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('V88CmbFIBWHtgPl_N5dqa', 'General Knowledge', 'भारत की पहली महिला राज्यपाल कौन थी?', 'Who was the first female Governor of India?', 'सरोजिनी नायडु', 'Sarojini Naidu', 94, 0, '{"facts":["वह उत्तर प्रदेश (संयुक्त प्रांत) की राज्यपाल बनी थीं।","इन्हें ''भारत कोकिला'' (Nightingale of India) भी कहा जाता है।"],"factsEn":["Became Governor of United Provinces (UP).","Known as the Nightingale of India."],"explanationHi":"वह 1947 में भारत की स्वतंत्रता के बाद किसी राज्य की राज्यपाल बनने वाली पहली महिला थीं।","explanationEn":"She became the first woman to hold the governor''s office in independent India in 1947.","memoryTip":"राज्यपाल का ''ताज'' पहली बार ''कोकिला'' सरोजिनी को मिला।","memoryTipEn":"Nightingale of India became the first Governor.","related":["Sucheta Kriplani","Nightingale of India"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DGVczVl3oee65QQjr50UR', 'General Knowledge', 'माउन्ट एवेरेस्ट पर दो बार चढ़ने वाली पहली महिला कौन थी?', 'Who was the first woman to climb Mount Everest twice?', 'संतोष यादव', 'Santosh Yadav', 90, 0, '{"facts":["उन्होंने 1992 और 1993 में एवरेस्ट फतह किया।","कंगशुंग फेस से एवरेस्ट पर चढ़ने वाली पहली महिला।"],"factsEn":["Summited in 1992 and 1993.","First woman to climb Everest from the Kangshung face."],"explanationHi":"वह लगातार दो बार विश्व की सबसे ऊंची चोटी पर चढ़ने वाली पहली महिला बनीं।","explanationEn":"First woman globally to reach the summit twice continuously.","memoryTip":"एक बार चढ़कर ''संतोष'' नहीं हुआ, इसलिए दो बार चढ़ीं संतोष यादव।","memoryTipEn":"Santosh wasn''t ''satisfied'' with just one climb.","related":["Bachendri Pal","Mount Everest"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KFfKh3S9z5RsWI8dAL0yn', 'General Knowledge', '''ब्रह्म समाज'' की स्थापना किसके द्वारा की गई?', 'Who founded the ''Brahmo Samaj''?', 'राजा राममोहन राय', 'Raja Ram Mohan Roy', 96, 0, '{"facts":["1828 में कलकत्ता में स्थापना हुई।","इन्होंने सती प्रथा के खिलाफ बड़ा आंदोलन चलाया।"],"factsEn":["Founded in 1828 in Calcutta.","Campaigned heavily against the Sati system."],"explanationHi":"ब्रह्म समाज ने मूर्ति पूजा, जाति व्यवस्था और अन्य कुरीतियों का विरोध किया।","explanationEn":"Brahmo Samaj opposed idol worship, the caste system, and social evils.","memoryTip":"राम और मोहन ने मिलकर ''ब्रह्म'' का ज्ञान दिया।","memoryTipEn":"Raja Ram reformed the Brahmo way.","related":["Atmiya Sabha","Sati System","Indian Renaissance"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7-rNvuVQfSdUpvV8CyHHo', 'General Knowledge', 'स्वामी दयानंद सरस्वती का मूल नाम क्या था?', 'What was the original name of Swami Dayanand Saraswati?', 'मूलशंकर', 'Moolshankar', 86, 0, '{"facts":["उनका जन्म गुजरात के मोरबी में हुआ था।","वे आर्य समाज के संस्थापक थे।"],"factsEn":["Born in Morbi, Gujarat.","Founder of Arya Samaj."],"explanationHi":"उनके ''मूल'' नाम से ही पता चलता है कि वे वैदिक जड़ों (मूल) की ओर लौटना चाहते थे।","explanationEn":"He wanted to go back to the ''roots'' (Vedas).","memoryTip":"दयानंद का ''मूल'' नाम ''मूलशंकर'' था।","memoryTipEn":"Original name = Mool (Root) Shankar.","related":["Arya Samaj","Go back to Vedas"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('l9qKKm8r2VJhoWdOOu6ce', 'General Knowledge', '''वेदों की ओर लौटो'' का नारा किसने दिया?', 'Who gave the slogan ''Go back to Vedas''?', 'दयानंद सरस्वती', 'Dayanand Saraswati', 91, 0, '{"facts":["यह नारा आर्य समाज का मुख्य सिद्धांत था।","उनका मानना था कि वेद ही सच्चे ज्ञान का स्रोत हैं।"],"factsEn":["Main principle of Arya Samaj.","Believed Vedas are the true source of knowledge."],"explanationHi":"उन्होंने हिंदू समाज की कुरीतियों को दूर करने के लिए वैदिक जीवन शैली अपनाने पर जोर दिया।","explanationEn":"He emphasized adopting the Vedic lifestyle to eradicate social evils in Hinduism.","memoryTip":"सरस्वती (विद्या की देवी) का वास ''वेदों'' में है।","memoryTipEn":"Saraswati = Goddess of Knowledge -> Vedas.","related":["Arya Samaj","Satyarth Prakash"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qXEjVGNZUtlVEb1d9y6lk', 'General Knowledge', '''रामकृष्ण मिशन'' की स्थापना किसने की?', 'Who founded the ''Ramakrishna Mission''?', 'स्वामी विवेकानंद', 'Swami Vivekananda', 95, 0, '{"facts":["स्थापना 1 मई 1897 को हुई।","मुख्यालय बेलूर मठ (पश्चिम बंगाल) में है।"],"factsEn":["Founded on May 1, 1897.","Headquarters at Belur Math, West Bengal."],"explanationHi":"यह मिशन उनके गुरु रामकृष्ण परमहंस के आदर्शों और वेदांत दर्शन के प्रचार-प्रसार के लिए बनाया गया था।","explanationEn":"Created to spread the ideals of his guru Ramakrishna Paramahamsa and Vedanta philosophy.","memoryTip":"विवेकानंद ने अपने गुरु (रामकृष्ण) के नाम पर मिशन शुरू किया।","memoryTipEn":"Vivekananda honored his guru Ramakrishna.","related":["Belur Math","Ramakrishna Paramahamsa","Vedanta"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jAa8YtJwHZceumhuYYp_L', 'General Knowledge', 'वास्कोडिगामा भारत कब आया?', 'When did Vasco da Gama come to India?', '1498 ई.', '1498 AD', 93, 0, '{"facts":["वह केरल के कालीकट (कोझिकोड) तट पर पहुंचा था।","वहां के राजा ''जमोरिन'' ने उसका स्वागत किया था।"],"factsEn":["Arrived at the port of Calicut (Kozhikode), Kerala.","Welcomed by the local ruler, Zamorin."],"explanationHi":"उसने यूरोप से भारत तक केप ऑफ गुड होप होते हुए सीधे समुद्री मार्ग की खोज की।","explanationEn":"He discovered the direct sea route from Europe to India via the Cape of Good Hope.","memoryTip":"14-9-8 (क्रम याद रखें: 1498)।","memoryTipEn":"1498: Vasco navigates.","related":["Zamorin","Calicut","Cape of Good Hope"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YMwtxWxzsLgQH9bZ4SF3o', 'General Knowledge', 'वास्कोडिगामा कहाँ का रहने वाला था?', 'Where was Vasco da Gama from?', 'पुर्तगाल', 'Portugal', 88, 0, '{"facts":["वह एक पुर्तगाली नाविक और खोजकर्ता था।","भारत आने वाले पहले यूरोपीय पुर्तगाली ही थे।"],"factsEn":["He was a Portuguese explorer.","Portuguese were the first Europeans to reach India by sea."],"explanationHi":"पुर्तगालियों ने ही सबसे पहले भारत में व्यापारिक केंद्र स्थापित किए (कोचीन में)।","explanationEn":"The Portuguese established the first European trading centers in India.","memoryTip":"पुर्तगाल से ''पोर'' (Port) होते हुए भारत आया।","memoryTipEn":"Portugal -> Port explorer.","related":["Estado da India","Cochin","Goa"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bZi-Dy4P9gjLx5V9hg2H5', 'General Knowledge', 'हवा महल कहाँ स्थित है?', 'Where is Hawa Mahal located?', 'जयपुर', 'Jaipur', 86, 0, '{"facts":["इसे महाराजा सवाई प्रताप सिंह ने 1799 में बनवाया था।","इसमें 953 छोटी खिड़कियां (झरोखे) हैं।"],"factsEn":["Built by Maharaja Sawai Pratap Singh in 1799.","Has 953 small windows (jharokhas)."],"explanationHi":"शाही महिलाओं को शहर के त्योहारों को बिना किसी के देखे देखने की अनुमति देने के लिए इसे बनवाया गया था।","explanationEn":"Built to allow royal ladies to observe street festivals unseen.","memoryTip":"गुलाबी नगर (जयपुर) में गुलाबी हवा महल है।","memoryTipEn":"Palace of Winds is in the Pink City.","related":["Pink City","Sawai Pratap Singh","Rajasthan Architecture"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0VHYQ3macUCctL3sUXd7G', 'General Knowledge', 'सिख धर्म का संस्थापक किस सिख गुरु को माना जाता है?', 'Which Sikh Guru is considered the founder of Sikhism?', 'गुरु नानक', 'Guru Nanak', 92, 0, '{"facts":["वे सिखों के दस गुरुओं में से पहले गुरु थे।","उनका जन्म तलवंडी (अब पाकिस्तान में ननकाना साहिब) में हुआ था।"],"factsEn":["First of the ten Sikh Gurus.","Born in Talwandi (now Nankana Sahib, Pakistan)."],"explanationHi":"उन्होंने 15वीं शताब्दी में समानता और एकेश्वरवाद का उपदेश देते हुए सिख धर्म की नींव रखी।","explanationEn":"Founded Sikhism in the 15th century, preaching equality and monotheism.","memoryTip":"सिख धर्म के ''नानक'' (जनक)।","memoryTipEn":"First Guru -> Guru Nanak.","related":["Guru Granth Sahib","Nankana Sahib","Sikh Gurus"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('fZOasqVUEPLWk54zDtpVm', 'General Knowledge', 'सिखों का प्रमुख त्यौहार कौन-सा है?', 'Which is the major festival of Sikhs?', 'बैसाखी', 'Baisakhi', 88, 0, '{"facts":["यह वसंत ऋतु का फसल उत्सव hai।","इसी दिन 1699 में गुरु गोबिंद सिंह ने खालसा पंथ की स्थापना की थी।"],"factsEn":["A spring harvest festival.","Khalsa Panth was founded on this day in 1699 by Guru Govind Singh."],"explanationHi":"यह सिखों के लिए एक धार्मिक और कृषि उत्सव दोनों है।","explanationEn":"It is both a religious and agricultural festival for Sikhs.","memoryTip":"बैसाखी में ''खालसा'' की साखी (कथा) जुड़ी है।","memoryTipEn":"Baisakhi -> Birth of Khalsa.","related":["Khalsa Panth","Guru Gobind Singh","Harvest Festival"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ALlTtMK_Yn7uVezb8F4tU', 'General Knowledge', '''लौह पुरुष'' किस महापुरुष को कहा जाता है?', 'Which great man is known as the ''Iron Man''?', 'सरदार वल्लभभाई पटेल', 'Sardar Vallabhbhai Patel', 96, 0, '{"facts":["वे भारत के पहले उप प्रधानमंत्री और गृह मंत्री थे।","उन्होंने 562 रियासतों को भारत में एकीकृत किया।"],"factsEn":["First Deputy PM and Home Minister of India.","Integrated 562 princely states into India."],"explanationHi":"रियासतों के एकीकरण में उनके दृढ़ संकल्प के कारण उन्हें ''भारत का लौह पुरुष'' कहा गया।","explanationEn":"Called Iron Man for his iron will in integrating the princely states.","memoryTip":"पटेल जी का इरादा ''लोहे'' जैसा मजबूत था।","memoryTipEn":"Iron Man -> Statue of Unity -> Patel.","related":["Statue of Unity","Bismarck of India","Bardoli Satyagraha"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uOPJdoo555VMgW_5Ds0Qi', 'General Knowledge', 'नेताजी किस महापुरुष को कहा जाता है?', 'Which great man is called ''Netaji''?', 'सुभाष चंद्र बोस', 'Subhas Chandra Bose', 94, 0, '{"facts":["इन्होंने ''आजाद हिंद फौज'' का पुनर्गठन किया।","''तुम मुझे खून दो, मैं तुम्हें आजादी दूंगा'' का प्रसिद्ध नारा दिया।"],"factsEn":["Reorganized the ''Indian National Army'' (INA).","Gave the famous slogan ''Give me blood, and I shall give you freedom''."],"explanationHi":"भारत के स्वतंत्रता संग्राम में उनके असाधारण नेतृत्व के लिए लोगों और भारतीय सैनिकों ने उन्हें ''नेताजी'' की उपाधि दी।","explanationEn":"Given the title ''Netaji'' (Respected Leader) by Indian soldiers in Germany.","memoryTip":"हमारे ''नेता'' सुभाष बाबू।","memoryTipEn":"Netaji = Leader -> Bose.","related":["Azad Hind Fauj","Forward Bloc","Parakram Diwas"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('w3fNON_d3ZqMf1dRiIPY2', 'General Knowledge', 'दिल्ली स्थित लाल बहादुर शास्त्री की समाधि का क्या नाम है?', 'What is the name of the memorial of Lal Bahadur Shastri in Delhi?', 'विजय घाट', 'Vijay Ghat', 89, 0, '{"facts":["यह नई दिल्ली में यमुना नदी के तट पर स्थित है।","यह 1965 के युद्ध में पाकिस्तान पर भारत की विजय का भी प्रतीक है।"],"factsEn":["Located on the banks of Yamuna river in New Delhi.","Symbolizes India''s victory over Pakistan in the 1965 war."],"explanationHi":"भारत के दूसरे प्रधानमंत्री लाल बहादुर शास्त्री के सम्मान में इसे विजय घाट नाम दिया गया।","explanationEn":"Named ''Vijay Ghat'' (Victory Bank) to honor the 2nd PM who led India during the 1965 war.","memoryTip":"बहादुर लोग हमेशा ''विजय'' प्राप्त करते हैं।","memoryTipEn":"Brave (Bahadur) brings Victory (Vijay).","related":["Raj Ghat","Kisan Ghat","Tashkent Agreement"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rMYbZyQ9CncJcZNFd8IWQ', 'General Knowledge', 'महाभारत के रचयिता कौन हैं?', 'Who is the author of Mahabharata?', 'महर्षि वेदव्यास', 'Maharishi Ved Vyas', 91, 0, '{"facts":["महाभारत दुनिया का सबसे लंबा महाकाव्य है।","श्रीमद्भगवद्गीता इसी महाकाव्य का एक हिस्सा (भीष्म पर्व) है।"],"factsEn":["Mahabharata is the longest epic poem in the world.","Bhagavad Gita is a part of it (Bhishma Parva).."],"explanationHi":"महर्षि वेदव्यास ने महाभारत की रचना की और भगवान गणेश ने इसे लिखा था।","explanationEn":"Dictated by Ved Vyas and written down by Lord Ganesha.","memoryTip":"वेद और महाभारत दोनों ''व्यास'' जी ने संकलित किए।","memoryTipEn":"Vyas wrote the Vast epic.","related":["Ramayana","Bhagavad Gita","Kurukshetra"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Hb2fkGe0GXZA1yij8PKT2', 'General Knowledge', 'अर्थशास्त्र नामक पुस्तक किसने लिखी?', 'Who wrote the book named Arthashastra?', 'चाणक्य (कौटिल्य / विष्णुगुप्त)', 'Chanakya (Kautilya)', 95, 0, '{"facts":["यह राज्यकला, आर्थिक नीति और सैन्य रणनीति पर एक प्राचीन भारतीय ग्रंथ है।","चाणक्य चंद्रगुप्त मौर्य के प्रधानमंत्री थे।"],"factsEn":["An ancient Indian treatise on statecraft, economic policy, and military strategy.","Chanakya was the PM of Chandragupta Maurya."],"explanationHi":"इस पुस्तक में मौर्य साम्राज्य के प्रशासन के बारे में विस्तृत जानकारी है।","explanationEn":"Provides detailed insights into the administration of the Mauryan Empire.","memoryTip":"कौटिल्य की कूटनीति = अर्थशास्त्र।","memoryTipEn":"Kautilya''s economics = Arthashastra.","related":["Chandragupta Maurya","Mauryan Empire","Vishnugupta"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IbuYr3TitdHewZA2Yvx7I', 'General Knowledge', '''जय जवान, जय किसान'' का नारा किसने दिया?', 'Who gave the slogan ''Jai Jawan, Jai Kisan''?', 'लाल बहादुर शास्त्री', 'Lal Bahadur Shastri', 96, 0, '{"facts":["यह नारा 1965 के भारत-पाकिस्तान युद्ध के दौरान दिया गया था।","अटल बिहारी वाजपेयी ने इसमें ''जय विज्ञान'' जोड़ा था।"],"factsEn":["Given during the 1965 India-Pakistan war.","Atal Bihari Vajpayee later added ''Jai Vigyan'' to it."],"explanationHi":"सैनिकों (जवानों) और किसानों का मनोबल बढ़ाने के लिए यह नारा दिया गया था, क्योंकि देश युद्ध और अन्न की कमी का सामना कर रहा था।","explanationEn":"To boost the morale of soldiers and farmers when India was facing war and food scarcity.","memoryTip":"शास्त्री जी ने जवान और किसान दोनों की महिमा गाई।","memoryTipEn":"Shastri honored soldiers and farmers.","related":["1965 Indo-Pak War","Green Revolution"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('B-Ie946-Kdywb9NAabJp6', 'General Knowledge', 'संविधान सभा का स्थाई अध्यक्ष कौन था?', 'Who was the permanent President of the Constituent Assembly?', 'डॉ. राजेन्द्र प्रसाद', 'Dr. Rajendra Prasad', 95, 0, '{"facts":["उन्हें 11 दिसंबर 1946 को अध्यक्ष चुना गया था।","अस्थाई अध्यक्ष डॉ. सच्चिदानंद सिन्हा थे (9 दिसंबर को)।"],"factsEn":["Elected on December 11, 1946.","Dr. Sachchidananda Sinha was the interim president."],"explanationHi":"वे बाद में स्वतंत्र भारत के पहले राष्ट्रपति भी बने।","explanationEn":"He later became the first President of independent India.","memoryTip":"प्रसाद के रूप में हमें ''स्थाई'' संविधान मिला।","memoryTipEn":"First President of India = Permanent President of Assembly.","related":["Constituent Assembly","Dr. Sachchidananda Sinha","Drafting Committee"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ofWHvBxgD0UcHXpIcL8ry', 'General Knowledge', 'संविधान सभा की प्रारूप समिति के अध्यक्ष कौन थे?', 'Who was the Chairman of the Drafting Committee of the Constituent Assembly?', 'डॉ. भीमराव अंबेडकर', 'Dr. B. R. Ambedkar', 98, 0, '{"facts":["प्रारूप समिति का गठन 29 अगस्त 1947 को हुआ था।","समिति में अध्यक्ष सहित 7 सदस्य थे।"],"factsEn":["Drafting Committee was formed on Aug 29, 1947.","It had 7 members including the Chairman."],"explanationHi":"उन्हें भारतीय संविधान के ''जनक'' या ''निर्माता'' के रूप में जाना जाता है।","explanationEn":"Known as the Father of the Indian Constitution.","memoryTip":"अंबेडकर जी ने संविधान का ''रूप'' (प्रारूप) तैयार किया।","memoryTipEn":"Ambedkar drafted our future.","related":["Father of Indian Constitution","Article 32"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RWN-nQ4mmSCy3InOYeMi9', 'General Knowledge', 'विश्व रेडक्रॉस दिवस किस तारीख को मनाया जाता है?', 'On which date is World Red Cross Day celebrated?', '8 मई', '8 May', 84, 0, '{"facts":["यह हेनरी ड्यूनेंट के जन्मदिन पर मनाया जाता है।","हेनरी ड्यूनेंट इंटरनेशनल कमिटी ऑफ द रेड क्रॉस (ICRC) के संस्थापक थे।"],"factsEn":["Celebrated on the birthday of Henry Dunant.","Henry Dunant founded the ICRC."],"explanationHi":"यह दिन मानवीय कार्यों और रेडक्रॉस स्वयंसेवकों को सम्मानित करने के लिए मनाया जाता है।","explanationEn":"Celebrated to honor humanitarian efforts and Red Cross volunteers.","memoryTip":"मई (May) में 8 (आठ) दिशाओं में रेडक्रॉस मदद करता है।","memoryTipEn":"May 8 -> Mate -> Helping mate -> Red Cross.","related":["Henry Dunant","Geneva Conventions"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('g0gZY3z0yQetcUerX6hKr', 'General Knowledge', 'सूर्योदय का देश के नाम से कौनसा देश प्रसिद्ध है?', 'Which country is famous as the ''Land of the Rising Sun''?', 'जापान', 'Japan', 90, 0, '{"facts":["जापानी भाषा में इसे ''निप्पॉन'' (Nippon) या ''निहोन'' कहते हैं, जिसका अर्थ सूर्य का मूल है।","यह एशिया के सुदूर पूर्व में स्थित है।"],"factsEn":["In Japanese, it''s called ''Nippon'' meaning origin of the sun.","Located in the far east of Asia."],"explanationHi":"प्राचीन चीनियों के नजरिए से सूर्य जापान की दिशा से उगता हुआ दिखाई देता था।","explanationEn":"From China''s perspective, the sun appeared to rise from Japan''s direction.","memoryTip":"जा-पान -> जहाँ से सूरज पान करता है रोशनी का।","memoryTipEn":"Japan is far east, gets sun first in the region.","related":["Nippon","Midnight Sun (Norway)"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Wb4FIpx8ahzsQYQOYgQyd', 'General Knowledge', 'अन्तर्राष्ट्रीय महिला दिवस किस तिथि को मनाया जाता है?', 'On which date is International Women''s Day celebrated?', '8 मार्च', '8 March', 92, 0, '{"facts":["इसे संयुक्त राष्ट्र द्वारा भी मान्यता प्राप्त है।","यह महिलाओं के अधिकारों और महिला सशक्तीकरण का जश्न मनाता है।"],"factsEn":["Recognized by the United Nations.","Celebrates women''s rights and empowerment."],"explanationHi":"महिलाओं की सामाजिक, आर्थिक, सांस्कृतिक और राजनीतिक उपलब्धियों का जश्न मनाने के लिए यह दिन मनाया जाता है।","explanationEn":"A global day celebrating the social, economic, cultural, and political achievements of women.","memoryTip":"मार्च (March) करती महिलाएँ (8)।","memoryTipEn":"Marching forward on the 8th.","related":["National Women''s Day (Feb 13)"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ksQj_LSAP_zOMtqafc4Fx', 'General Knowledge', 'क्षेत्रफल की दृष्टि से भारत में सबसे छोटा राज्य कौन-सा है?', 'Which is the smallest state in India in terms of area?', 'गोवा', 'Goa', 93, 0, '{"facts":["इसका क्षेत्रफल केवल 3,702 वर्ग किलोमीटर hai।","जनसंख्या के हिसाब से सबसे छोटा राज्य सिक्किम है।"],"factsEn":["Its area is only 3,702 sq km.","Smallest state by population is Sikkim."],"explanationHi":"गोवा भारत के पश्चिमी तट (कोंकण क्षेत्र) पर स्थित है।","explanationEn":"Goa is located on the western coast of India (Konkan region).","memoryTip":"गोवा ''गया'' और तुरंत खत्म हो गया (सबसे छोटा)।","memoryTipEn":"Goa is tiny like a dot on the west coast.","related":["Sikkim","Rajasthan (Largest Area)"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TZ3WpiGLEJLyBfo2Vyix7', 'General Knowledge', 'ओणम किस राज्य का प्रसिद्ध त्योहार है?', 'Onam is a famous festival of which state?', 'केरल', 'Kerala', 90, 0, '{"facts":["यह एक फसल उत्सव है।","राजा महाबली के स्वागत में मनाया जाता है।"],"factsEn":["It is a harvest festival.","Celebrated to welcome King Mahabali."],"explanationHi":"इस त्योहार के दौरान प्रसिद्ध नौका दौड़ (वल्लमकली) आयोजित की जाती है।","explanationEn":"The famous snake boat race (Vallamkali) is held during this festival.","memoryTip":"केरल के लोग ''ओणम'' पर केले के पत्ते पर खाते हैं।","memoryTipEn":"K-O: Kerala - Onam.","related":["Pongal","Snake Boat Race","King Mahabali"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('43lyJJwmyyEc0cvhfKBse', 'General Knowledge', 'दिल्ली भारत की राजधानी कब बनी?', 'When did Delhi become the capital of India?', '1911', '1911', 94, 0, '{"facts":["1911 के दिल्ली दरबार में जॉर्ज पंचम ने इसकी घोषणा की थी।","इससे पहले भारत की राजधानी कलकत्ता (अब कोलकाता) थी।"],"factsEn":["Announced by King George V in the 1911 Delhi Durbar.","Previously, the capital was Calcutta."],"explanationHi":"भारत के बेहतर प्रशासन के लिए राजधानी को केंद्र में (दिल्ली) स्थानांतरित किया गया।","explanationEn":"The capital was moved to the center (Delhi) for better administration of India.","memoryTip":"कलकत्ता से दिल्ली ''एक-एक'' (11) कदम करके गए (1911)।","memoryTipEn":"1911 -> Capital shifts from East to Center.","related":["Lord Hardinge","Delhi Durbar","Calcutta"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7_WS-pH-nEu_Rtj8IF6Pt', 'General Science', 'सबसे चमकीला ग्रह कौनसा है?', 'Which is the brightest planet?', 'शुक्र (Venus)', 'Venus', 91, 0, '{"facts":["इसे भोर का तारा (Morning Star) और सांझ का तारा (Evening Star) भी कहा जाता hai।","यह सौरमंडल का सबसे गर्म ग्रह भी है।"],"factsEn":["Also called Morning Star and Evening Star.","It is also the hottest planet in the solar system."],"explanationHi":"शुक्र के वायुमंडल में सल्फ्यूरिक एसिड के घने बादल हैं, जो सूरज की रोशनी को अत्यधिक प्रतिबिंबित करते हैं।","explanationEn":"Venus has thick clouds of sulfuric acid that heavily reflect sunlight.","memoryTip":"शुक्र (Shukra) मतलब सुंदरता, और सुंदर चीज़ चमकती है।","memoryTipEn":"Venus = Roman Goddess of Beauty = Brightest.","related":["Hottest Planet","Morning Star","Earth''s Twin"]}', 'published', 1776081103, 1776081103);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qZJfgqXg6418LxYpkRaXW', 'General Knowledge', 'भारत का राष्ट्रीय पशु कौनसा है?', 'Which is the national animal of India?', 'बाघ', 'Tiger', 85, 0, '{"facts":["बाघ का वैज्ञानिक नाम पैंथेरा टाइग्रिस है।","इसे 1973 में राष्ट्रीय पशु घोषित किया गया था।"],"factsEn":["Scientific name is Panthera tigris.","Declared the national animal in 1973."],"explanationHi":"अपनी शक्ति, चपलता और अपार ऊर्जा के कारण बाघ को राष्ट्रीय पशु के रूप में चुना गया है।","explanationEn":"Chosen as the national animal for its power, agility, and immense energy.","memoryTip":"बाघ भारत की ''शक्ति'' का प्रतीक है।","memoryTipEn":"Tiger represents India''s strength.","related":["Project Tiger","National Symbols"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HZ9pHcsJkH0AVRDAaVflr', 'General Knowledge', 'भारत का राष्ट्रीय पक्षी कौनसा है?', 'Which is the national bird of India?', 'मोर', 'Peacock', 85, 0, '{"facts":["मोर का वैज्ञानिक नाम पावो क्रिस्टेटस (Pavo cristatus) है।","इसे 1963 में राष्ट्रीय पक्षी घोषित किया गया था।"],"factsEn":["Scientific name is Pavo cristatus.","Declared the national bird in 1963."],"explanationHi":"भारतीय उपमहाद्वीप में व्यापक रूप से पाए जाने और अपनी सुंदरता के कारण इसे यह सम्मान मिला।","explanationEn":"Given this honor due to its beauty and wide distribution across the Indian subcontinent.","memoryTip":"भारत का ''गौरव'' मोर के पंखों जैसा रंगीन है।","memoryTipEn":"Peacock dances with India''s vibrant colors.","related":["National Symbols","Pavo Cristatus"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('M6oOknYmdJkHi9QG5UCbd', 'General Knowledge', 'भारत का राष्ट्रीय जलीय जीव कौनसा है?', 'Which is the national aquatic animal of India?', 'गंगा डॉलफिन', 'Ganges River Dolphin', 90, 0, '{"facts":["इसे 2009 में राष्ट्रीय जलीय जीव घोषित किया गया था।","यह केवल मीठे पानी में जीवित रह सकती है।"],"factsEn":["Declared the national aquatic animal in 2009.","It can only survive in freshwater."],"explanationHi":"यह गंगा नदी की शुद्धता का प्रतिनिधित्व करती है क्योंकि यह केवल साफ पानी में ही जीवित रह सकती है।","explanationEn":"It represents the purity of the holy Ganga river as it can only survive in pure and fresh water.","memoryTip":"गंगा की ''डॉल'' (Dolphin) भारत की जलीय शान है।","memoryTipEn":"Dolphin of the holy Ganges.","related":["Vikramshila Gangetic Dolphin Sanctuary","National Symbols"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aujCUN6-V_BtmQOB_G7ag', 'General Knowledge', 'भारत का राष्ट्रीय फल कौनसा है?', 'Which is the national fruit of India?', 'आम', 'Mango', 80, 0, '{"facts":["आम का वैज्ञानिक नाम मैंगिफेरा इंडिका है।","इसे ''फलों का राजा'' भी कहा जाता है।"],"factsEn":["Scientific name is Mangifera indica.","Also known as the ''King of Fruits''."],"explanationHi":"प्राचीन काल से ही भारत में आम की खेती की जाती रही है और इसका सांस्कृतिक महत्व है।","explanationEn":"Mangoes have been cultivated in India since ancient times and hold cultural significance.","memoryTip":"भारत का फल बहुत ''आम'' (Mango) है।","memoryTipEn":"Mango is ''Aam'' (Common/Universal) in India.","related":["Mangifera Indica","National Symbols"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ayUDSimiAbI-gBG8JC2O_', 'General Knowledge', 'भारत का राष्ट्रीय फूल कौनसा है?', 'Which is the national flower of India?', 'कमल', 'Lotus', 82, 0, '{"facts":["कमल का वैज्ञानिक नाम नेलुम्बो न्यूसिफेरा है।","यह भारतीय संस्कृति में पवित्रता और शुभता का प्रतीक है।"],"factsEn":["Scientific name is Nelumbo nucifera.","Symbolizes purity and auspiciousness in Indian culture."],"explanationHi":"कीचड़ में खिलने के बावजूद यह अछूता रहता है, जो आध्यात्मिकता और ज्ञान का प्रतीक है।","explanationEn":"Despite growing in mud, it remains untouched, symbolizing spirituality and enlightenment.","memoryTip":"कीचड़ में भी ''कमल'' खिलकर देश का मान बढ़ाता है।","memoryTipEn":"Lotus blooms in mud -> Purity in adversity.","related":["National Symbols","Nelumbo nucifera"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AZfTf1Gupe4p8B_kD8I-x', 'General Knowledge', 'भारत का राष्ट्रीय पेड़ कौनसा है?', 'Which is the national tree of India?', 'बरगद', 'Banyan Tree', 85, 0, '{"facts":["बरगद का वैज्ञानिक नाम फिकस बेंघालेंसिस है।","इसकी जड़ें शाखाओं से लटककर नई जड़ें बनाती हैं।"],"factsEn":["Scientific name is Ficus benghalensis.","Its aerial roots hang from branches to form new trunks."],"explanationHi":"अपनी लंबी उम्र और विशाल फैलाव के कारण इसे अमरता और भारत की एकता का प्रतीक माना जाता है।","explanationEn":"Considered a symbol of immortality and India''s unity due to its long life and massive spread.","memoryTip":"भारत की जड़ें ''बरगद'' की तरह गहरी और फैली हुई हैं।","memoryTipEn":"Banyan covers widely like India''s unity.","related":["National Symbols","Ficus benghalensis"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Kl7n8sRnPCFTg3mJHmrBW', 'General Knowledge', 'भारत का राष्ट्रीय खेल कौनसा है?', 'Which is considered the national sport of India?', 'हॉकी', 'Hockey', 85, 0, '{"facts":["भारत ने ओलंपिक हॉकी में 8 स्वर्ण पदक जीते हैं।","हालांकि, खेल मंत्रालय के अनुसार भारत का आधिकारिक रूप से कोई राष्ट्रीय खेल नहीं है, लेकिन इसे माना जाता है।"],"factsEn":["India has won 8 Olympic gold medals in Hockey.","Technically, the Sports Ministry says India has no official national sport, but it''s widely accepted as such."],"explanationHi":"ओलंपिक में भारत के स्वर्णिम इतिहास के कारण हॉकी को अनौपचारिक रूप से राष्ट्रीय खेल का दर्जा दिया गया है।","explanationEn":"Due to India''s golden history in Olympics, hockey is unofficially accorded the status of the national sport.","memoryTip":"ध्यानचंद के ''हॉकी'' ने भारत को पहचान दिलाई।","memoryTipEn":"Hockey brought 8 Olympic Golds.","related":["Major Dhyan Chand","Olympic Hockey"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1PfZNeOf7lcTJD3TmiI_D', 'General Knowledge', 'भारत के राष्ट्रीय झंडे की लम्बाई और चौड़ाई में अनुपात कितना होता है?', 'What is the ratio of the length to the width of the National Flag of India?', '3:2', '3:2', 92, 0, '{"facts":["तिरंगे का डिज़ाइन पिंगली वेंकय्या ने तैयार किया था।","संविधान सभा ने इसे 22 जुलाई 1947 को अपनाया।"],"factsEn":["The tricolor was designed by Pingali Venkayya.","Adopted by the Constituent Assembly on July 22, 1947."],"explanationHi":"राष्ट्रीय ध्वज के आयाम सख्ती से 3:2 के अनुपात में होने चाहिए (लंबाई 3, चौड़ाई 2)।","explanationEn":"The dimensions of the national flag must strictly be in the ratio of 3:2 (Length 3, Width 2).","memoryTip":"लंबाई 3, चौड़ाई 2 (3 > 2)।","memoryTipEn":"Length is longer -> 3:2 ratio.","related":["Pingali Venkayya","National Flag Code"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lK8uRBgLwzUf7a0omfVXG', 'General Knowledge', 'भारत का राष्ट्रगान किसने लिखा?', 'Who wrote the National Anthem of India?', 'रवीन्द्रनाथ टैगोर', 'Rabindranath Tagore', 95, 0, '{"facts":["''जन गण मन'' मूल रूप से बंगाली भाषा में लिखा गया था।","टैगोर ने बांग्लादेश का राष्ट्रगान (आमार सोनार बांग्ला) भी लिखा है।"],"factsEn":["''Jana Gana Mana'' was originally written in Bengali.","Tagore also wrote the national anthem of Bangladesh."],"explanationHi":"इसे पहली बार 27 दिसंबर 1911 को कलकत्ता अधिवेशन में गाया गया था।","explanationEn":"It was first sung on December 27, 1911, at the Calcutta session of the INC.","memoryTip":"टैगोर जी ने दो देशों का ''गान'' (Anthem) लिखा।","memoryTipEn":"Tagore = Two Anthems (India & Bangladesh).","related":["Jana Gana Mana","National Anthem","Calcutta Session 1911"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kbIFZuPAqv3Sc6FIY-Gy-', 'General Knowledge', 'भारत का राष्ट्रगीत कौनसा है?', 'Which is the National Song of India?', 'वंदेमातरम्', 'Vande Mataram', 92, 0, '{"facts":["यह आनंदमठ नामक उपन्यास से लिया गया है।","इसे पहली बार 1896 के कांग्रेस अधिवेशन में गाया गया था।"],"factsEn":["Taken from the novel ''Anandamath''.","First sung at the 1896 Congress session."],"explanationHi":"वंदेमातरम् ने भारतीय स्वतंत्रता संग्राम में एक महत्वपूर्ण प्रेरक भूमिका निभाई थी।","explanationEn":"Vande Mataram played a vital inspirational role in the Indian freedom struggle.","memoryTip":"भारत माता की वंदना = वंदेमातरम्।","memoryTipEn":"Vande (Bow) Mataram (Mother).","related":["Anandamath","National Song","Bankim Chandra"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YLkHTlK4519KbLIE5gdTV', 'General Knowledge', 'भारत का राष्ट्रगीत किसने लिखा है?', 'Who wrote the National Song of India?', 'बंकिमचन्द्र चटर्जी', 'Bankim Chandra Chatterjee', 95, 0, '{"facts":["यह मूल रूप से संस्कृत और बंगाली मिश्रित भाषा में लिखा गया था।","श्री अरबिंदो ने इसका अंग्रेजी में अनुवाद किया था।"],"factsEn":["Originally written in a mix of Sanskrit and Bengali.","Sri Aurobindo translated it into English."],"explanationHi":"उन्होंने 1882 में अपने प्रसिद्ध उपन्यास ''आनंदमठ'' में इस कविता को शामिल किया था।","explanationEn":"He included this poem in his famous 1882 novel ''Anandamath''.","memoryTip":"बंकिम जी ने ''आनंद'' के लिए वंदेमातरम् लिखा।","memoryTipEn":"Bankim authored the Song of the Nation.","related":["Vande Mataram","Anandamath"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vVkPfY_3nSws3dHFwdks-', 'General Knowledge', 'महात्मा गाँधी को राष्ट्रपिता सबसे पहले किसने कहा?', 'Who first called Mahatma Gandhi the ''Father of the Nation''?', 'नेताजी सुभाष चन्द्र बोस', 'Netaji Subhas Chandra Bose', 93, 0, '{"facts":["उन्होंने 1944 में सिंगापुर रेडियो से एक प्रसारण में यह बात कही थी।","यह आज़ाद हिंद फ़ौज के अभियान के दौरान कहा गया था।"],"factsEn":["He said this in a broadcast from Singapore Radio in 1944.","It was said during the INA campaign."],"explanationHi":"वैचारिक मतभेदों के बावजूद, बोस ने गांधीजी के योगदान का अत्यधिक सम्मान किया।","explanationEn":"Despite ideological differences, Bose highly respected Gandhi''s contribution.","memoryTip":"नेताजी ने बापू को ''राष्ट्रपिता'' का सम्मान दिया।","memoryTipEn":"Netaji gave the title Father of the Nation.","related":["Mahatma Gandhi","Singapore Radio Broadcast 1944"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HK3Fvva9ZjCsAG-HKzud3', 'General Knowledge', 'हमारा राष्ट्रीय पंचांग कौनसा है?', 'Which is our National Calendar?', 'शक संवत्', 'Saka Samvat', 88, 0, '{"facts":["इसे 22 मार्च 1957 को ग्रेगोरियन कैलेंडर के साथ अपनाया गया था।","इसका पहला महीना चैत्र और अंतिम महीना फाल्गुन होता है।"],"factsEn":["Adopted on 22 March 1957 along with the Gregorian calendar.","Its first month is Chaitra and the last is Phalguna."],"explanationHi":"शक युग 78 ईस्वी में शुरू हुआ माना जाता है, जिसे भारत सरकार अपने आधिकारिक उद्देश्यों के लिए उपयोग करती है।","explanationEn":"The Saka era is believed to have started in 78 AD, and is used by the Govt of India for official purposes.","memoryTip":"हम भारत पर ''शक'' नहीं करते, यही हमारा संवत् है।","memoryTipEn":"Saka Samvat starts with Chaitra.","related":["Gregorian Calendar","Chaitra Month","78 AD"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6oN_75eWpcv1N4nDgRHE6', 'General Knowledge', 'राष्ट्रगान गाने की अवधि कितनी है?', 'What is the playing time of the National Anthem?', '52 सेकंड', '52 seconds', 92, 0, '{"facts":["इसके संक्षिप्त संस्करण (पहली और अंतिम पंक्ति) को गाने में लगभग 20 सेकंड लगते हैं।","यह नियम भारत के राष्ट्रीय ध्वज संहिता में उल्लेखित है।"],"factsEn":["The short version (first and last lines) takes about 20 seconds to play.","This rule is mentioned in the Flag Code of India."],"explanationHi":"पूरे राष्ट्रगान को गाने का आधिकारिक मानक समय ठीक 52 सेकंड निर्धारित है।","explanationEn":"The official standard time to sing the full national anthem is strictly 52 seconds.","memoryTip":"50 के बाद 2 सेकंड और = 52 सेकंड।","memoryTipEn":"52 weeks in a year, 52 seconds for the Anthem.","related":["Jana Gana Mana","Flag Code of India"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qregrne92Id0_rkE2d05j', 'General Science', 'रेडियोऐक्टिवता की खोज किसने की थी?', 'Who discovered Radioactivity?', 'हेनरी बेकरल', 'Henri Becquerel', 89, 0, '{"facts":["इन्होंने 1896 में यूरेनियम लवणों में इसकी खोज की थी।","इस खोज के लिए उन्हें मैरी और पियरे क्यूरी के साथ नोबेल पुरस्कार मिला।"],"factsEn":["Discovered it in uranium salts in 1896.","Shared the Nobel Prize with Marie and Pierre Curie."],"explanationHi":"रेडियोधर्मिता वह प्रक्रिया है जिसमें एक अस्थिर परमाणु नाभिक विकिरण (अल्फा, बीटा या गामा) उत्सर्जित करके ऊर्जा खोता है।","explanationEn":"Radioactivity is the process by which an unstable atomic nucleus loses energy by emitting radiation.","memoryTip":"बेकरल के ''बैरल'' से रेडिएशन निकला।","memoryTipEn":"Becquerel backed the radioactive discovery.","related":["Marie Curie","Uranium","Alpha Beta Gamma"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('94ikrovznRNczESgYOCqr', 'General Science', 'पेस मेकर का सम्बन्ध शरीर के किस अंग से हैं?', 'Pacemaker is associated with which organ of the human body?', 'हृदय', 'Heart', 93, 0, '{"facts":["प्राकृतिक पेसमेकर को SA नोड (Sinoatrial node) कहा जाता है।","कृत्रिम पेसमेकर दिल की धड़कन को नियंत्रित करने के लिए लगाया जाता है।"],"factsEn":["The natural pacemaker is called the SA Node.","An artificial pacemaker is implanted to regulate the heartbeat."],"explanationHi":"यह एक छोटा उपकरण है जो विद्युत आवेग भेजकर हृदय गति को नियंत्रित करने में मदद करता है।","explanationEn":"It is a small device that helps control the heartbeat by sending electrical impulses.","memoryTip":"हृदय की ''पेस'' (रफ़्तार) को ''मेक'' (बनाता) है पेसमेकर।","memoryTipEn":"Pace -> Heartbeat rate -> Heart.","related":["SA Node","Cardiology","Arrhythmia"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('17r94V1HYGD8I9yzmwEqb', 'General Science', 'मानव शरीर की किस ग्रन्थि को ''मास्टर ग्रन्थि'' कहा जाता है?', 'Which gland in the human body is known as the ''Master Gland''?', 'पियूष ग्रंथि', 'Pituitary Gland', 96, 0, '{"facts":["यह मटर के दाने के आकार की होती है और मस्तिष्क के आधार पर स्थित होती है।","यह अन्य अंतःस्रावी ग्रंथियों (Endocrine Glands) को नियंत्रित करती है।"],"factsEn":["It is pea-sized and located at the base of the brain.","It controls other endocrine glands."],"explanationHi":"चूंकि यह शरीर की अन्य कई ग्रंथियों के हार्मोन स्राव को नियंत्रित करती है, इसलिए इसे मास्टर ग्रंथि कहते हैं।","explanationEn":"It is called the master gland because it controls the hormone release of many other glands in the body.","memoryTip":"मास्टर हमेशा ''पीयूष'' (अमृत) बांटता है।","memoryTipEn":"Pituitary is the Boss (Master).","related":["Endocrine System","Hypothalamus","Growth Hormone"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MOOq66ETom1xhe9oh1dAW', 'General Science', 'कार्बन का सर्वाधिक शुद्ध रूप कौनसा है?', 'Which is the purest form of Carbon?', 'हीरा', 'Diamond', 92, 0, '{"facts":["हीरा प्राकृतिक रूप से पाया जाने वाला सबसे कठोर पदार्थ है।","ग्रेफाइट और फुलेरीन भी कार्बन के अपररूप (Allotropes) हैं।"],"factsEn":["Diamond is the hardest naturally occurring substance.","Graphite and Fullerene are also allotropes of carbon."],"explanationHi":"हीरे में प्रत्येक कार्बन परमाणु चार अन्य कार्बन परमाणुओं से जुड़कर एक दृढ़ 3D संरचना बनाता है।","explanationEn":"In a diamond, each carbon atom is bonded to four others, forming a rigid 3D structure.","memoryTip":"हीरा है सदा के लिए, और सबसे शुद्ध।","memoryTipEn":"Diamond is pure carbon perfection.","related":["Allotropes of Carbon","Graphite","Hardest Natural Substance"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0Rv2seR8087mUPZfxJ3yn', 'General Science', 'एक्स-रे का आविष्कार किसने किया था?', 'Who invented the X-ray?', 'रांटजन', 'Wilhelm Roentgen', 90, 0, '{"facts":["इन्होंने 1895 में एक्स-रे की खोज की थी।","इन्हें भौतिकी का पहला नोबेल पुरस्कार (1901) दिया गया था।"],"factsEn":["He discovered X-rays in 1895.","Awarded the first Nobel Prize in Physics in 1901."],"explanationHi":"अज्ञात प्रकार के विकिरण होने के कारण उन्होंने गणितीय प्रतीक ''X'' का उपयोग करके इसे एक्स-रे नाम दिया।","explanationEn":"Named it X-ray using the mathematical symbol ''X'' for an unknown type of radiation.","memoryTip":"हड्डियां ''रॉटन'' (सड़ी) हैं या नहीं, यह एक्स-रे बताता है।","memoryTipEn":"Roentgen revealed the bones.","related":["Electromagnetic Spectrum","Nobel Prize in Physics"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vY54Up_6iec3dSHTk9Nk6', 'General Knowledge', 'किस धातु का प्रयोग मानव द्वारा सबसे पहले किया गया?', 'Which metal was used first by humans?', 'तांबा', 'Copper', 94, 0, '{"facts":["ताम्र पाषाण युग (Chalcolithic Age) में इसका पहली बार उपयोग हुआ।","तांबे और टिन को मिलाकर कांस्य (Bronze) बनाया गया था।"],"factsEn":["First used during the Chalcolithic Age.","Copper and tin were later mixed to make Bronze."],"explanationHi":"तांबा आसानी से उपलब्ध था और इसे बिना अधिक तापमान के मोड़ा और आकार दिया जा सकता था।","explanationEn":"Copper was easily accessible and could be bent and shaped without extremely high temperatures.","memoryTip":"सबसे पहले ''ताकत'' के लिए ''तांबा'' प्रयोग किया।","memoryTipEn":"Copper came before Bronze or Iron.","related":["Chalcolithic Age","Bronze Age"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Zttz0GTyM9hzjzpV7kjL7', 'General Science', 'अंतरिक्ष यात्री को बाह्य आकाश कैसा दिखायी पड़ता है?', 'How does the outer space appear to an astronaut?', 'काला', 'Black', 91, 0, '{"facts":["अंतरिक्ष में कोई वायुमंडल नहीं है।","प्रकाश का प्रकीर्णन (Scattering) न होने के कारण यह काला दिखाई देता है।"],"factsEn":["There is no atmosphere in space.","It appears black due to the absence of scattering of light."],"explanationHi":"पृथ्वी का आकाश नीला इसलिए दिखता है क्योंकि वायुमंडल प्रकाश को बिखेरता है; अंतरिक्ष में ऐसा कोई माध्यम नहीं है।","explanationEn":"Earth''s sky is blue because the atmosphere scatters light; space lacks this medium.","memoryTip":"बिना हवा के प्रकाश नहीं फैलता, इसलिए सब काला।","memoryTipEn":"No air to scatter light = Black sky.","related":["Scattering of light","Atmosphere"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('etJOVR61Dho6WY77dcYpd', 'General Science', 'दूरबीन का आविष्कार किसने किया था?', 'Who invented the telescope?', 'गैलिलियो ने', 'Galileo Galilei', 88, 0, '{"facts":["हालांकि हैंस लिपरशी ने पहला पेटेंट दायर किया था, लेकिन गैलिलियो ने इसे खगोल विज्ञान के लिए लोकप्रिय बनाया।","उन्होंने बृहस्पति के 4 चंद्रमाओं की खोज की।"],"factsEn":["Hans Lippershey filed the first patent, but Galileo popularized its astronomical use.","He discovered the 4 moons of Jupiter."],"explanationHi":"गैलिलियो ने दूरबीन का उपयोग करके पहली बार ब्रह्मांड का व्यवस्थित अध्ययन किया।","explanationEn":"Galileo used the telescope to systematically study the universe for the first time.","memoryTip":"दूर के तारे ''गली-गली'' (Galileo) में दिखाए।","memoryTipEn":"Galileo gazed at galaxies.","related":["Hans Lippershey","Astronomy","Jupiter Moons"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-jorLvzxpdVHs2MJ3Pbuj', 'General Knowledge', 'दिल्ली स्थित महात्मा गाँधी की समाधि का क्या नाम है?', 'What is the name of Mahatma Gandhi''s memorial located in Delhi?', 'राजघाट', 'Rajghat', 90, 0, '{"facts":["यह यमुना नदी के किनारे स्थित है।","यहाँ काले संगमरमर का एक चौकोर चबूतरा है जहाँ एक अखंड ज्योति जलती रहती है।"],"factsEn":["Located on the banks of the Yamuna River.","It consists of a square block of black marble with an eternal flame."],"explanationHi":"31 जनवरी 1948 को गाँधीजी के अंतिम संस्कार के स्थान को स्मारक के रूप में संरक्षित किया गया है।","explanationEn":"The site of Gandhi''s cremation on January 31, 1948, is preserved as a memorial.","memoryTip":"बापू दिलों पर ''राज'' करते हैं, इसलिए ''राजघाट''।","memoryTipEn":"Gandhi ruled hearts -> Raj (Rule) Ghat.","related":["Vijay Ghat","Shakti Sthal","Mahatma Gandhi"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('j5kw-pItmMbLiSzMfHdpa', 'General Knowledge', 'भारत में पहली रेल कहाँ से कहाँ तक चली? [cite: 87, 88]', 'Where did the first train run in India?', 'बम्बई (वर्तमान मुंबई) से थाने तक', 'Bombay to Thane', 97, 0, '{"facts":["यह यात्रा 16 अप्रैल 1853 को हुई थी।","इसने 34 किलोमीटर की दूरी तय की थी।"],"factsEn":["The journey took place on April 16, 1853.","It covered a distance of 34 kilometers."],"explanationHi":"लॉर्ड डलहौजी के कार्यकाल के दौरान पहली यात्री ट्रेन तीन भाप इंजनों (साहिब, सिंध और सुल्तान) द्वारा चलाई गई थी।","explanationEn":"Run during Lord Dalhousie''s tenure, pulled by three steam locomotives (Sahib, Sindh, and Sultan).","memoryTip":"बोरीबंदर (मुंबई) से ''ठाणे'' जाकर ठहरी।","memoryTipEn":"Bombay to Thane -> First Train.","related":["Lord Dalhousie","Indian Railways 1853"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FaZDFJdq26xvZIL6CJvSB', 'General Knowledge', 'भारत में पहली बार मेट्रो रेल सेवा किस नगर में आरम्भ की गई? [cite: 88, 89]', 'In which city was the metro rail service started for the first time in India?', 'कोलकाता', 'Kolkata', 95, 0, '{"facts":["कोलकाता मेट्रो की शुरुआत 1984 में हुई थी।","यह भारत की पहली भूमिगत (Underground) रेलवे प्रणाली थी।"],"factsEn":["Kolkata Metro started in 1984.","It was India''s first underground railway system."],"explanationHi":"तत्कालीन प्रधानमंत्री इंदिरा गांधी के समय में इसका वाणिज्यिक संचालन शुरू हुआ था।","explanationEn":"Its commercial operation began during the tenure of PM Indira Gandhi.","memoryTip":"अंग्रेजों की पहली राजधानी (कोलकाता) में ही पहली मेट्रो चली।","memoryTipEn":"Oldest capital got the first Metro.","related":["Delhi Metro","Indian Railways"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aJtmCGdtQbhDWKvwcKku0', 'General Knowledge', 'भारत में रेल का आरम्भ किस सन में हुआ?', 'In which year did the railways start in India?', '1853', '1853', 96, 0, '{"facts":["16 अप्रैल 1853 को पहली ट्रेन चली थी।","यह लॉर्ड डलहौजी के समय में शुरू हुई थी।"],"factsEn":["The first train ran on April 16, 1853.","It started during the time of Lord Dalhousie."],"explanationHi":"भारत में औद्योगिक क्रांति और परिवहन को बढ़ावा देने के लिए अंग्रेजों द्वारा रेलवे शुरू की गई थी।","explanationEn":"Railways were introduced by the British to boost the industrial revolution and transport in India.","memoryTip":"18-5-3 (1853) - रेल की शुरुआत।","memoryTipEn":"1853: Wheels rolling free.","related":["Lord Dalhousie","Bombay to Thane"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('shcf_B97Ir4bXoTzUu3sd', 'General Knowledge', 'प्रथम भारतीय अंतरिक्ष यात्री कौन थे?', 'Who was the first Indian astronaut?', 'राकेश शर्मा (1984 में)', 'Squadron Leader Rakesh Sharma (in 1984)', 95, 0, '{"facts":["उन्होंने सोवियत संघ के सोयुज टी-11 मिशन के साथ अंतरिक्ष की यात्रा की।","उन्होंने अंतरिक्ष से भारत को देखकर कहा था: ''सारे जहाँ से अच्छा''।"],"factsEn":["Traveled to space aboard the Soviet Union''s Soyuz T-11 mission.","Described India from space as ''Sare Jahan Se Achha''."],"explanationHi":"वे भारतीय वायु सेना के एक पायलट थे और अंतरिक्ष में जाने वाले पहले भारतीय नागरिक बने।","explanationEn":"He was an IAF pilot and became the first Indian citizen to go to space.","memoryTip":"अंतरिक्ष में भारत का ''शर्मा'' (रौशन) किया राकेश जी ने।","memoryTipEn":"Rakesh reached the stars in 1984.","related":["Soyuz T-11","ISRO","Kalpana Chawla"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('o-Uyjo5mPaUuTyIPVaYOG', 'General Knowledge', 'भारत की प्रथम महिला मुख्यमंत्री कौन थी? [cite: 91, 92]', 'Who was the first female Chief Minister in India?', 'श्रीमती सुचेता कृपलानी', 'Sucheta Kriplani', 94, 0, '{"facts":["वे उत्तर प्रदेश (1963-1967) की मुख्यमंत्री बनी थीं।","वे एक प्रमुख स्वतंत्रता सेनानी थीं।"],"factsEn":["Served as the CM of Uttar Pradesh (1963-1967).","She was a prominent freedom fighter."],"explanationHi":"भारतीय राजनीति में महिलाओं की भागीदारी के इतिहास में यह एक बड़ी उपलब्धि थी।","explanationEn":"It was a major milestone in the history of women''s participation in Indian politics.","memoryTip":"पहली महिला मुख्यमंत्री का काम ''सुचारु'' (Sucheta) रूप से चला।","memoryTipEn":"Sucheta steered the state of UP.","related":["Sarojini Naidu","Uttar Pradesh","First in India"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('D-bpUF3wrwlXMq4qssA2n', 'General Knowledge', 'हरियाणा के पहले मुख्यमंत्री कौन थे?', 'Who was the first Chief Minister of Haryana?', 'पं. भगवत दयाल शर्मा', 'Pt. Bhagwat Dayal Sharma', 82, 0, '{"facts":["वे 1 नवंबर 1966 को हरियाणा के गठन के बाद पहले मुख्यमंत्री बने।","वे भारतीय राष्ट्रीय कांग्रेस के सदस्य थे।"],"factsEn":["Became the first CM after the formation of Haryana on Nov 1, 1966.","He was a member of the INC."],"explanationHi":"इन्हें पंडितजी के नाम से जाना जाता था और इन्होंने मध्य प्रदेश और उड़ीसा के राज्यपाल के रूप में भी कार्य किया।","explanationEn":"Known as Panditji, he also served as the Governor of Madhya Pradesh and Odisha.","memoryTip":"''भगवान'' की ''दया'' से हरियाणा के पहले सीएम बने।","memoryTipEn":"Bhagwat blessed Haryana as its first CM.","related":["Haryana Formation 1966","State Politics"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UfU0-VLHLR3pKE0da1LA3', 'General Knowledge', 'संयुक्त राष्ट्र संघ का मुख्यालय कहाँ स्थित है?', 'Where is the headquarters of the United Nations located?', 'न्यूयॉर्क', 'New York', 93, 0, '{"facts":["यह मुख्यालय मैनहट्टन (न्यूयॉर्क शहर) में स्थित है।","इसके लिए ज़मीन जॉन डी. रॉकफेलर जूनियर द्वारा दान की गई थी।"],"factsEn":["Located in Manhattan, New York City.","The land was donated by John D. Rockefeller Jr."],"explanationHi":"हालांकि मुख्यालय अमेरिका में है, लेकिन यह क्षेत्र अंतर्राष्ट्रीय क्षेत्र माना जाता है।","explanationEn":"Although located in the US, the headquarters is considered international territory.","memoryTip":"दुनिया का ''नया'' संगठन ''न्यू'' यॉर्क में है।","memoryTipEn":"New world order -> New York.","related":["Geneva (UN offices)","General Assembly"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NjdEqjnPvgryP1mQR4ABd', 'General Knowledge', 'संयुक्त राष्ट्र संघ के पहले महासचिव कौन थे? [cite: 95, 96]', 'Who was the first Secretary-General of the United Nations?', 'त्रिग्वेली', 'Trygve Lie', 88, 0, '{"facts":["वे नॉर्वे के एक राजनेता थे।","उन्होंने 1946 से 1952 तक इस पद पर कार्य किया।"],"factsEn":["He was a Norwegian politician.","Served from 1946 to 1952."],"explanationHi":"उन्होंने ही संयुक्त राष्ट्र मुख्यालय का स्थान न्यूयॉर्क में स्थापित करने का समर्थन किया था।","explanationEn":"He supported the establishment of the UN headquarters in New York.","memoryTip":"UN ने पहले इंसान को ''ट्राई'' (Trygve) किया।","memoryTipEn":"Trygve was the first to ''Try'' managing the UN.","related":["Dag Hammarskjöld","United Nations Secretariat"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dO6f_8uPAIsgzRt4F6wlB', 'General Knowledge', 'इस समय संयुक्त राष्ट्र संघ के कितने देश सदस्य हैं?', 'How many member countries are there in the United Nations at present?', '193', '193', 90, 0, '{"facts":["सबसे नया सदस्य देश दक्षिण सूडान है।","वेटिकन सिटी और फिलिस्तीन पर्यवेक्षक (Observer) राज्य हैं।"],"factsEn":["The newest member is South Sudan.","Vatican City and Palestine are observer states."],"explanationHi":"विश्व के लगभग सभी अंतरराष्ट्रीय स्तर पर मान्यता प्राप्त देश इसके सदस्य हैं।","explanationEn":"Almost all internationally recognized nations of the world are members.","memoryTip":"1-9-3 देश मिलकर UN चलाते हैं।","memoryTipEn":"193 nations united.","related":["South Sudan","UN General Assembly"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rC7JwQMBBEAD0NciWeOwW', 'General Knowledge', 'संयुक्त राष्ट्र संघ सुरक्षा परिषद् के कितने देश सदस्य होते हैं?', 'How many member countries are there in the UN Security Council?', '15', '15', 92, 0, '{"facts":["इसमें 5 स्थायी (Permanent) और 10 अस्थायी (Non-Permanent) सदस्य होते हैं।","अस्थायी सदस्य हर दो साल के लिए चुने जाते हैं।"],"factsEn":["Consists of 5 permanent and 10 non-permanent members.","Non-permanent members are elected for two years."],"explanationHi":"UNSC का मुख्य कार्य अंतरराष्ट्रीय स्तर पर शांति और सुरक्षा बनाए रखना है।","explanationEn":"The primary role of UNSC is to maintain international peace and security.","memoryTip":"सुरक्षा के लिए 15 गार्ड्स (सदस्य) हैं।","memoryTipEn":"15 members secure the world.","related":["UNSC","Veto Power"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ztyisX1uQhQ1Ts7gO7pqV', 'General Knowledge', 'संयुक्त राष्ट्र संघ सुरक्षा परिषद् के कितने देश स्थाई सदस्य हैं?', 'How many permanent member countries are there in the UN Security Council?', '5', '5', 95, 0, '{"facts":["ये 5 देश हैं: अमेरिका, रूस, चीन, फ्रांस और ब्रिटेन।","इन पाँचों देशों के पास ''वीटो पावर'' (Veto Power) है।"],"factsEn":["The 5 countries are: USA, Russia, China, France, and UK.","These five have ''Veto Power''."],"explanationHi":"किसी भी महत्वपूर्ण प्रस्ताव को पास करने के लिए इन पांचों देशों की सहमति (या वीटो का प्रयोग न होना) आवश्यक है।","explanationEn":"Any substantive resolution requires the agreement (or non-use of veto) of these five nations.","memoryTip":"सुरक्षा के ''पंच'' (5) स्थायी होते हैं।","memoryTipEn":"P5 (Permanent 5) nations.","related":["Veto Power","P5 Nations"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ueVChrcQaQQMZHPwJcATS', 'General Knowledge', 'अंतरराष्ट्रीय न्यायालय कहाँ स्थित है? [cite: 98, 99]', 'Where is the International Court of Justice located?', 'द हेग, हॉलैंड में', 'The Hague, Netherlands', 94, 0, '{"facts":["इसे ''विश्व न्यायालय'' (World Court) भी कहा जाता है।","यह संयुक्त राष्ट्र का एकमात्र मुख्य अंग है जो न्यूयॉर्क में नहीं है।"],"factsEn":["Also known as the ''World Court''.","The only principal UN organ not located in New York."],"explanationHi":"इसमें 15 न्यायाधीश होते हैं, जिन्हें संयुक्त राष्ट्र महासभा और सुरक्षा परिषद द्वारा 9 साल के लिए चुना जाता है।","explanationEn":"It has 15 judges elected for 9-year terms by the UN General Assembly and Security Council.","memoryTip":"न्याय के लिए दुनिया को ''हेग'' (Hague) जाना पड़ता है।","memoryTipEn":"Justice at The Hague.","related":["ICJ","Peace Palace"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oUioj2tvuqnrugwDILGbV', 'General Knowledge', 'संयुक्त राष्ट्र संघ के महासचिव कौन है (पीडीएफ स्रोत अनुसार)?', 'Who is the Secretary-General of the United Nations (as per PDF source)?', 'बान-की-मून', 'Ban Ki-moon', 85, 0, '{"facts":["नोट: वर्तमान में (2026) एंटोनियो गुटेरेस UN के महासचिव हैं।","बान-की-मून दक्षिण कोरिया के राजनेता थे।"],"factsEn":["Note: Currently (2026), Antonio Guterres is the UN Secretary-General.","Ban Ki-moon was a South Korean politician."],"explanationHi":"दिए गए संदर्भ स्रोत के समय बान-की-मून पद पर थे, जिन्होंने 2007 से 2016 तक कार्य किया।","explanationEn":"Ban Ki-moon was in office at the time of the provided source context (served 2007-2016).","memoryTip":"बान-की-मून ने मून (Moon) की तरह UN को शांति दी।","memoryTipEn":"Ban Ki-moon served before Guterres.","related":["Antonio Guterres","United Nations Secretariat"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vXVgdXWeE374oVg-AuTYP', 'General Knowledge', 'संयुक्त राष्ट्र महासभा में हिंदी में भाषण देने वाले भारतीय कौन थे? [cite: 101, 102]', 'Who was the first Indian to deliver a speech in Hindi at the UN General Assembly?', 'अटल बिहारी वाजपेयी', 'Atal Bihari Vajpayee', 95, 0, '{"facts":["उन्होंने 1977 में भारत के विदेश मंत्री के रूप में यह ऐतिहासिक भाषण दिया था।","इस भाषण ने वैश्विक मंच पर हिंदी भाषा का मान बढ़ाया।"],"factsEn":["Delivered this historic speech in 1977 as India''s External Affairs Minister.","It boosted the prestige of Hindi on a global platform."],"explanationHi":"उनके इस कदम की देश-विदेश में भारी प्रशंसा हुई थी।","explanationEn":"This initiative of his was highly praised both domestically and internationally.","memoryTip":"वाजपेयी जी की ''वाणी'' (भाषण) हिंदी में पूरी दुनिया ने सुनी।","memoryTipEn":"Vajpayee voiced Hindi at the UN.","related":["UNGA","External Affairs Minister India 1977"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DmuRfc3EA3xXOIBZWW0xX', 'General Knowledge', 'संयुक्त राष्ट्र संघ सुरक्षा परिषद् के अस्थायी सदस्य कितने वर्ष के लिये चुने जाते हैं?', 'For how many years are the non-permanent members of the UN Security Council elected?', '2 वर्ष', '2 years', 89, 0, '{"facts":["संयुक्त राष्ट्र महासभा द्वारा हर साल 5 अस्थायी सदस्यों का चुनाव होता है।","भारत कई बार अस्थायी सदस्य बन चुका है।"],"factsEn":["The UN General Assembly elects 5 non-permanent members every year.","India has served as a non-permanent member multiple times."],"explanationHi":"विश्व के विभिन्न क्षेत्रों को समान प्रतिनिधित्व देने के लिए यह रोटेशन प्रणाली अपनाई जाती है।","explanationEn":"This rotation system ensures equitable geographical representation from different regions of the world.","memoryTip":"अस्थायी मतलब 2 साल के लिए मेहमान।","memoryTipEn":"Non-permanent = 2 year term.","related":["UNSC","UN General Assembly"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_W1wY-fuoyxNUihyt5iwY', 'General Knowledge', 'संयुक्त राष्ट्र संघ का 193वां सदस्य कौनसा देश बना था?', 'Which country became the 193rd member of the United Nations?', 'दक्षिण सूडान', 'South Sudan', 90, 0, '{"facts":["यह 2011 में सूडान से अलग होकर एक स्वतंत्र देश बना।","इसकी राजधानी जुबा (Juba) है।"],"factsEn":["Became an independent country from Sudan in 2011.","Its capital is Juba."],"explanationHi":"स्वतंत्रता प्राप्त करने के तुरंत बाद इसे संयुक्त राष्ट्र के सदस्य के रूप में शामिल किया गया था।","explanationEn":"It was admitted as a UN member shortly after gaining independence.","memoryTip":"सबसे नया देश ''दक्षिण'' दिशा में सूडान से बना।","memoryTipEn":"South Sudan is the newest nation.","related":["Sudan","Juba"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TYwMRm63BhP_ZYNgpYBgi', 'General Science', 'किस विटामिन की कमी से खून का रुकाव बंद नहीं होता?', 'Deficiency of which vitamin prevents the clotting of blood?', 'विटामिन K', 'Vitamin K', 96, 0, '{"facts":["विटामिन K का रासायनिक नाम फाइलोक्विनोन है।","यह रक्त का थक्का (Blood clotting) बनाने वाले प्रोटीन के संश्लेषण के लिए आवश्यक है।"],"factsEn":["Chemical name is Phylloquinone.","Essential for the synthesis of proteins required for blood clotting."],"explanationHi":"यदि शरीर में विटामिन K की कमी हो जाए, तो छोटी सी चोट लगने पर भी खून बहना बंद नहीं होता।","explanationEn":"In its absence, even minor injuries can cause continuous bleeding due to non-clotting.","memoryTip":"K से ''Klot'' (Clot) यानी थक्का जमना।","memoryTipEn":"K for Koagulation (Clotting).","related":["Phylloquinone","Hemophilia","Blood Clotting"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zrxs87HrjRFzWYJU6A_c0', 'General Knowledge', 'हिंदी दिवस कब मनाया जाता है?', 'When is Hindi Diwas celebrated?', '14 सितंबर', '14 September', 92, 0, '{"facts":["14 सितंबर 1949 को संविधान सभा ने हिंदी को आधिकारिक भाषा के रूप में अपनाया था।","विश्व हिंदी दिवस 10 जनवरी को मनाया जाता है।"],"factsEn":["The Constituent Assembly adopted Hindi as an official language on 14 Sept 1949.","World Hindi Day is on Jan 10."],"explanationHi":"देश भर में हिंदी के उपयोग को बढ़ावा देने और इसके महत्व को पहचानने के लिए यह दिन मनाया जाता है।","explanationEn":"Celebrated to promote the use of Hindi and recognize its importance nationwide.","memoryTip":"14 सितंबर को हिंदी को सम्मान मिला।","memoryTipEn":"September 14 = Hindi Diwas.","related":["World Hindi Day","Article 343"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('VxlJmM3F5NXqIEemavcGy', 'General Knowledge', 'संविधान के किस अनुच्छेद द्वारा हिंदी को राष्ट्रभाषा घोषित किया गया?', 'By which article of the constitution was Hindi declared the official language?', 'अनुच्छेद 343', 'Article 343', 93, 0, '{"facts":["संविधान के अनुसार भारत की कोई ''राष्ट्रभाषा'' नहीं है, हिंदी संघ की ''राजभाषा'' (Official Language) है।","इसकी लिपि देवनागरी है।"],"factsEn":["India has no ''National Language''; Hindi is the ''Official Language'' of the Union.","Its script is Devanagari."],"explanationHi":"अनुच्छेद 343(1) कहता है कि संघ की राजभाषा हिंदी और लिपि देवनागरी होगी।","explanationEn":"Article 343(1) states that the official language of the Union shall be Hindi in Devanagari script.","memoryTip":"3-4-3 (गिनती की तरह) = हिंदी अनुच्छेद।","memoryTipEn":"Article 3-4-3 for Hindi script.","related":["Eighth Schedule","Official Languages Act"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RQffTLhK4H32l2G3MBE0g', 'General Knowledge', 'ओलंपिक खेलों की एकल स्पर्धा में स्वर्ण पदक जीतने वाले एकमात्र भारतीय कौन है (पीडीएफ स्रोत अनुसार)? [cite: 108, 109]', 'Who was the first (and only, as per PDF context) Indian to win a gold medal in an individual event at the Olympic Games?', 'अभिनव बिंद्रा', 'Abhinav Bindra', 94, 0, '{"facts":["उन्होंने 2008 बीजिंग ओलंपिक में 10 मीटर एयर राइफल स्पर्धा में स्वर्ण जीता था।","नोट: 2021 में नीरज चोपड़ा (भाला फेंक) भी व्यक्तिगत स्वर्ण जीत चुके हैं।"],"factsEn":["He won gold in the 10m Air Rifle event at the 2008 Beijing Olympics.","Note: Neeraj Chopra (Javelin) also won individual gold in 2021."],"explanationHi":"अभिनव बिंद्रा ओलंपिक इतिहास में भारत के पहले व्यक्तिगत स्वर्ण पदक विजेता हैं।","explanationEn":"Abhinav Bindra is India''s first individual Olympic gold medalist in history.","memoryTip":"''अभिनव'' (नया) काम बिंद्रा ने शूटिंग में किया।","memoryTipEn":"Bindra broke the gold barrier in Beijing.","related":["Neeraj Chopra","Beijing Olympics 2008","10m Air Rifle"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wVEm87HfrOCeL0NqdFbWD', 'General Knowledge', 'ओलंपिक खेलों का आयोजन कितने वर्षों बाद होता है?', 'After how many years are the Olympic Games held?', '4 वर्ष', '4 years', 90, 0, '{"facts":["ग्रीष्मकालीन और शीतकालीन ओलंपिक हर चार साल में होते हैं।","इन चार वर्षों की अवधि को ''ओलंपियाड'' (Olympiad) कहा जाता है।"],"factsEn":["Summer and Winter Olympics are held every four years.","This four-year period is called an ''Olympiad''."],"explanationHi":"यह परंपरा प्राचीन ग्रीक ओलंपिक से प्रेरित है, जो हर चार साल में ओलंपिया में आयोजित किए जाते थे।","explanationEn":"The tradition is inspired by the ancient Greek Olympics held every four years in Olympia.","memoryTip":"ओलंपिक के छल्ले (Rings) 5 हैं, लेकिन खेल 4 साल में आते हैं।","memoryTipEn":"Olympics occurs once in an Olympiad (4 years).","related":["Olympiad","IOC","Ancient Olympics"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_XSs14DaaUeHQWzLTQLvt', 'General Knowledge', 'सन 2016 में ओलंपिक खेल कहाँ हुऐ?', 'Where were the Olympic Games held in the year 2016?', 'रियो डी जिनेरो', 'Rio de Janeiro', 84, 0, '{"facts":["रियो डी जिनेरो ब्राज़ील का एक प्रमुख शहर है।","यह दक्षिण अमेरिका में आयोजित होने वाला पहला ओलंपिक खेल था।"],"factsEn":["Rio de Janeiro is a major city in Brazil.","It was the first Olympic Games held in South America."],"explanationHi":"इन खेलों में पीवी सिंधु (बैडमिंटन) और साक्षी मलिक (कुश्ती) ने भारत के लिए पदक जीते थे।","explanationEn":"PV Sindhu (Badminton) and Sakshi Malik (Wrestling) won medals for India in these games.","memoryTip":"2016 में ओलंपिक ''रियो'' (Rio) गए।","memoryTipEn":"2016 -> Rio Olympics.","related":["Tokyo 2020","Brazil"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2cGYZktKVcslboJXRVEpW', 'General Knowledge', 'अन्तर्राष्ट्रीय मानव अधिकार दिवस कब मनाया जाता है?', 'When is International Human Rights Day celebrated?', '10 दिसंबर', '10 December', 92, 0, '{"facts":["1948 में इसी दिन संयुक्त राष्ट्र ने मानवाधिकारों की सार्वभौम घोषणा (UDHR) को अपनाया था।","हर इंसान के बुनियादी अधिकारों की रक्षा के लिए यह दिन महत्वपूर्ण है।"],"factsEn":["On this day in 1948, the UN adopted the Universal Declaration of Human Rights (UDHR).","Crucial for protecting the basic rights of every human."],"explanationHi":"यह दिन विश्व स्तर पर समानता, शांति और स्वतंत्रता के संदेश को बढ़ावा देता है।","explanationEn":"Promotes the message of equality, peace, and freedom globally.","memoryTip":"दिसंबर (10) में हर ''मानव'' को अधिकार मिला।","memoryTipEn":"10th Dec -> Declare Human Rights.","related":["UDHR","United Nations"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('duQBbaY76E9uTaYqaWwnQ', 'General Knowledge', 'हरियाणा की कौनसी नस्ल की भैंस प्रसिद्ध है?', 'Which breed of buffalo from Haryana is famous?', 'मुर्राह', 'Murrah', 86, 0, '{"facts":["मुर्राह भैंस अपने उच्च दूध उत्पादन के लिए दुनिया भर में प्रसिद्ध है।","इसे हरियाणा में ''काला सोना'' (Black Gold) भी कहा जाता है।"],"factsEn":["Murrah buffalo is world-famous for its high milk yield.","It is also known as ''Black Gold'' in Haryana."],"explanationHi":"इन भैंसों के सींग मुड़े हुए (कुंडीदार) होते हैं और दूध में उच्च वसा (Fat) की मात्रा होती है।","explanationEn":"These buffaloes have tightly curled horns and high fat content in their milk.","memoryTip":"हरियाणा का ''काला सोना'' = मुर्राह।","memoryTipEn":"Murrah yields More milk.","related":["Black Gold of Haryana","Animal Husbandry"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PvU3Yjj0ntqlZffdh4xWl', 'General Knowledge', 'प्रसिद्ध शीतला माता मंदिर कहाँ स्थित है?', 'Where is the famous Sheetla Mata Temple located?', 'गुडगाँव (गुरुग्राम)', 'Gurgaon (Gurugram)', 85, 0, '{"facts":["शीतला माता को चेचक (Smallpox) से बचाव करने वाली देवी माना जाता है।","यह मंदिर महाभारत काल के गुरु द्रोणाचार्य की पत्नी कृपी को समर्पित है।"],"factsEn":["Sheetla Mata is considered the goddess who protects against Smallpox.","The temple is dedicated to Kripi, wife of Guru Dronacharya."],"explanationHi":"गुडगाँव का नया नाम गुरुग्राम गुरु द्रोणाचार्य के नाम पर ही पड़ा है, और यह मंदिर यहाँ का मुख्य तीर्थ स्थल है।","explanationEn":"The city''s new name Gurugram is named after Guru Dronacharya, and this temple is a key pilgrimage site.","memoryTip":"गुरुग्राम में ''शीतला'' माता शीतलता देती हैं।","memoryTipEn":"Sheetla Mata resides in Gurugram.","related":["Gurugram","Guru Dronacharya"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('X-3Hyn1W_glO5iZ6LFZ7A', 'General Knowledge', 'विशाल हरियाणा पार्टी किसने बनाई थी? [cite: 115, 116]', 'Who formed the Vishal Haryana Party?', 'राव विरेन्द्र सिंह', 'Rao Birender Singh', 81, 0, '{"facts":["यह हरियाणा की पहली क्षेत्रीय पार्टी थी।","राव विरेन्द्र सिंह हरियाणा के दूसरे मुख्यमंत्री बने थे।"],"factsEn":["It was the first regional party of Haryana.","Rao Birender Singh became the second CM of Haryana."],"explanationHi":"उन्होंने 1967 में यह पार्टी बनाई और गैर-कांग्रेसी सरकार का नेतृत्व किया।","explanationEn":"He formed this party in 1967 and led a non-Congress government.","memoryTip":"विशाल ''वीर'' (विरेन्द्र) ने विशाल हरियाणा पार्टी बनाई।","memoryTipEn":"Virender built Vishal Haryana.","related":["Haryana Politics","Regional Parties of India"]}', 'published', 1776083188, 1776083188);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CyNMhzxum4Qeb4wYb48yt', 'General Knowledge', 'हरियाणा का क्षेत्रफल कितना वर्ग किलोमीटर है?', 'What is the area of Haryana in square kilometers?', '44,212', '44,212', 75, 0, '{"facts":["हरियाणा भारत के कुल भौगोलिक क्षेत्र का लगभग 1.34% है।","इसका गठन 1 नवंबर 1966 को हुआ था।"],"factsEn":["Haryana accounts for about 1.34% of India''s total geographical area.","It was formed on November 1, 1966."],"explanationHi":"पंजाब से अलग होकर 1966 में एक नया राज्य बनने पर इसका क्षेत्रफल 44,212 वर्ग किलोमीटर निर्धारित किया गया था।","explanationEn":"Its area was set at 44,212 sq km when it was carved out of Punjab as a new state in 1966.","memoryTip":"4-4-2-1-2 (चार-चार, दो-एक-दो)।","memoryTipEn":"44-212 -> Double 4, half is 2, middle 1, end 2.","related":["Haryana Geography","Punjab Reorganization Act"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4rdrcLMwGl-kfrVAoeD64', 'General Knowledge', 'हरियाणा के पहले मुख्यमंत्री कौन थे?', 'Who was the first Chief Minister of Haryana?', 'पं. भगवत दयाल शर्मा', 'Pt. Bhagwat Dayal Sharma', 82, 0, '{"facts":["वे 1 नवंबर 1966 से 23 मार्च 1967 तक मुख्यमंत्री रहे।","बाद में वे उड़ीसा और मध्य प्रदेश के राज्यपाल भी बने।"],"factsEn":["Served as CM from Nov 1, 1966, to March 23, 1967.","Later served as Governor of Odisha and Madhya Pradesh."],"explanationHi":"हरियाणा राज्य के गठन के बाद भारतीय राष्ट्रीय कांग्रेस के भगवत दयाल शर्मा इसके प्रथम मुख्यमंत्री बने।","explanationEn":"After Haryana''s formation, Bhagwat Dayal Sharma of INC became its first CM.","memoryTip":"हरियाणा पर पहले ''भगवान की दया'' हुई।","memoryTipEn":"Bhagwat blessed Haryana as its first CM.","related":["Haryana Politics","Rao Birender Singh"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wICK9KD7lWZt5b0-8uU9K', 'General Knowledge', 'किस देश की स्थलसीमा सर्वाधिक देशों के साथ लगती है?', 'Which country shares its land border with the maximum number of countries?', 'चीन', 'China', 92, 0, '{"facts":["चीन की सीमा 14 देशों से लगती है।","रूस की सीमा भी 14 देशों से लगती है, लेकिन ऐतिहासिक रूप से चीन का नाम अधिक लिया जाता है।"],"factsEn":["China borders 14 countries.","Russia also borders 14 countries, though China is often cited."],"explanationHi":"भौगोलिक रूप से विशाल और मध्य एशिया में स्थित होने के कारण चीन सबसे अधिक पड़ोसी देशों से घिरा है।","explanationEn":"Due to its vast geography and central location in Asia, China is surrounded by the most neighbors.","memoryTip":"चीन हर तरफ अपनी ''दीवार'' (सीमा) फैलाना चाहता है।","memoryTipEn":"China connects with 14 neighbors.","related":["Russia","International Borders","Geography"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('pSZ0Yig42nmZI9mfxIMMQ', 'General Science', 'बैरोमीटर के पठन में तेजी से गिरावट किस बात का सूचक है?', 'What does a sudden fall in the barometer reading indicate?', 'तूफान का', 'Storm', 95, 0, '{"facts":["बैरोमीटर वायुमंडलीय दबाव मापता है।","धीरे-धीरे गिरावट बारिश का संकेत देती है, जबकि धीरे-धीरे बढ़ना साफ मौसम का।"],"factsEn":["A barometer measures atmospheric pressure.","A slow fall indicates rain, while a slow rise indicates clear weather."],"explanationHi":"वायुदाब में अचानक कमी का मतलब है कि हवाएं तेजी से उस कम दबाव वाले क्षेत्र को भरने आ रही हैं, जो तूफान लाता है।","explanationEn":"A sudden drop in air pressure means winds will rush to fill the low-pressure area, causing a storm.","memoryTip":"पारा तेज़ी से गिरे, मतलब मौसम बिगड़ेगा (तूफ़ान)।","memoryTipEn":"Sudden drop -> Storm drops in.","related":["Atmospheric Pressure","Evangelista Torricelli"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('pRCekhI0JBtN63FQo-bjG', 'General Knowledge', 'भारतीय मरूस्थल का क्या नाम है?', 'What is the name of the Indian desert?', 'थार', 'Thar', 90, 0, '{"facts":["इसे ग्रेट इंडियन डेजर्ट भी कहा जाता है।","यह मुख्य रूप से राजस्थान राज्य में स्थित है, और कुछ हिस्सा पाकिस्तान में भी है।"],"factsEn":["Also known as the Great Indian Desert.","Primarily located in Rajasthan, with a portion in Pakistan."],"explanationHi":"यह अरावली पहाड़ियों के पश्चिम में स्थित एक शुष्क क्षेत्र है जहाँ बहुत कम वर्षा होती है।","explanationEn":"It is an arid region west of the Aravalli hills receiving very low rainfall.","memoryTip":"रेत का ''थार'' (पहाड़) = थार मरुस्थल।","memoryTipEn":"Thar = The Hot Arid Region (mnemonic).","related":["Aravalli Range","Sahara Desert"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('azD15bnKEDTgymu16MHfu', 'General Knowledge', 'काजीरंगा राष्ट्रीय अभयारण्य किस राज्य में है?', 'In which state is the Kaziranga National Park located?', 'आसाम (असम)', 'Assam', 96, 0, '{"facts":["यह एक सींग वाले गैंडे (One-horned Rhinoceros) के लिए विश्व प्रसिद्ध है।","इसे 1985 में यूनेस्को विश्व धरोहर स्थल घोषित किया गया था।"],"factsEn":["World-famous for the One-horned Rhinoceros.","Declared a UNESCO World Heritage site in 1985."],"explanationHi":"ब्रह्मपुत्र नदी के बाढ़ के मैदानों में स्थित यह अभयारण्य जैव विविधता का एक प्रमुख केंद्र है।","explanationEn":"Located in the floodplains of the Brahmaputra river, it''s a major biodiversity hotspot.","memoryTip":"असम में काज़ी ने एक सींग वाला गैंडा देखा।","memoryTipEn":"Kazi in Assam loves Rhinos.","related":["One-horned Rhinoceros","UNESCO Heritage","Manas National Park"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('byCtzQpiBWoVg8jeluzek', 'General Science', 'पृथ्वी अपनी धुरी पर किस दिशा में घूमती है?', 'In which direction does the Earth rotate on its axis?', 'पश्चिम से पूर्व', 'West to East', 94, 0, '{"facts":["इसी कारण सूर्योदय हमेशा पूर्व में होता है।","शुक्र (Venus) और अरुण (Uranus) पूर्व से पश्चिम की ओर घूमते हैं।"],"factsEn":["This is why the sun always rises in the East.","Venus and Uranus rotate from East to West."],"explanationHi":"पृथ्वी की धुरी पर इस घूर्णन के कारण ही दिन और रात होते हैं।","explanationEn":"This rotation on its axis is what causes day and night on Earth.","memoryTip":"WE (West to East) rotate the Earth.","memoryTipEn":"Earth rotates WE (West to East).","related":["Rotation vs Revolution","Solar System"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SefIA67U-qSpDlnAI6QtS', 'General Knowledge', 'उज्जैन किस नदी के किनारे बसा है?', 'Ujjain is situated on the banks of which river?', 'शिप्रा', 'Shipra', 95, 0, '{"facts":["यहाँ हर 12 साल में कुंभ मेला लगता है।","भगवान महाकालेश्वर का प्रसिद्ध ज्योतिर्लिंग यहीं स्थित है।"],"factsEn":["The Kumbh Mela is held here every 12 years.","The famous Mahakaleshwar Jyotirlinga is located here."],"explanationHi":"शिप्रा नदी का हिंदू धर्म में बहुत महत्व है और इसे मोक्षदायिनी माना जाता है।","explanationEn":"Shipra river holds immense significance in Hinduism and is considered salvation-giving.","memoryTip":"उज्जैन के ''महाकाल'' शिप्रा जल से प्रसन्न होते हैं।","memoryTipEn":"Shipra flows beside the Mahakal.","related":["Kumbh Mela","Mahakaleshwar Jyotirlinga","Rivers of MP"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('U0n5fJBvDr-WXBePtrWUo', 'General Science', 'निम्न में से कौन-सी धातु बिजली की सबसे अधिक सुचालक है?', 'Which of the following metals is the best conductor of electricity?', 'चांदी', 'Silver', 93, 0, '{"facts":["चांदी के बाद तांबा (Copper) दूसरा सबसे अच्छा सुचालक है।","महंगी होने के कारण चांदी का उपयोग तारों में नहीं किया जाता।"],"factsEn":["Copper is the second-best conductor after silver.","Due to its high cost, silver is not used in common electrical wiring."],"explanationHi":"चांदी में मुक्त इलेक्ट्रॉनों की संख्या बहुत अधिक होती है जो बिजली को आसानी से प्रवाहित होने देते हैं।","explanationEn":"Silver has a very high number of free electrons allowing electricity to flow with minimal resistance.","memoryTip":"बिजली सबसे तेज़ ''चांदी'' के जूतों से भागती है।","memoryTipEn":"Silver is Gold for electricity.","related":["Copper","Electrical Conductivity","Resistance"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('OUYlOWK0dx8o6c1PnVdkb', 'General Science', '''गोबर गैस'' में मुख्य रूप से क्या पाया जाता है?', 'What is mainly found in ''Gobar Gas'' (Biogas)?', 'मीथेन', 'Methane', 94, 0, '{"facts":["मीथेन (CH4) एक रंगहीन, गंधहीन ज्वलनशील गैस है।","गोबर गैस में लगभग 55-70% मीथेन होती है।"],"factsEn":["Methane (CH4) is a colorless, odorless flammable gas.","Biogas contains about 55-70% methane."],"explanationHi":"ऑक्सीजन की अनुपस्थिति में जैविक कचरे के सड़ने से मीथेन गैस उत्पन्न होती है।","explanationEn":"Methane gas is produced by the anaerobic decomposition of organic waste.","memoryTip":"गाय के गोबर से ''मीठी'' (Methane) गैस बनती है।","memoryTipEn":"Methane Magic from Manure.","related":["Biogas Plant","Anaerobic Digestion","CNG"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BbXBLhOLi5_6TbAQufK1G', 'General Knowledge', 'राज्य सभा के सदस्यों का चुनाव कितनी अवधि के लिए किया जाता है?', 'For what duration are the members of the Rajya Sabha elected?', 'छह वर्ष', 'Six years', 94, 0, '{"facts":["राज्यसभा एक स्थायी सदन है, इसे कभी भंग नहीं किया जा सकता।","इसके एक-तिहाई सदस्य हर दो साल बाद सेवानिवृत्त हो जाते हैं।"],"factsEn":["Rajya Sabha is a permanent house and cannot be dissolved.","One-third of its members retire every two years."],"explanationHi":"लोकसभा (5 वर्ष) के विपरीत, राज्य सभा के सदस्यों का कार्यकाल 6 वर्ष का होता है।","explanationEn":"Unlike the Lok Sabha (5 years), Rajya Sabha members have a 6-year term.","memoryTip":"राज्य सभा (उच्च सदन) का कार्यकाल भी उच्च (5 से ज़्यादा 6) है।","memoryTipEn":"Upper House gets Upper Term (6 > 5).","related":["Lok Sabha","Parliament of India"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('U9b92qGW9Qb2zAG8hOdqD', 'General Knowledge', 'हिंदी भाषा की लिपि कौनसी है?', 'What is the script of the Hindi language?', 'देवनागरी', 'Devanagari', 90, 0, '{"facts":["संस्कृत, मराठी और नेपाली भाषाएं भी देवनागरी में लिखी जाती हैं।","यह लिपि बाएं से दाएं लिखी जाती है।"],"factsEn":["Sanskrit, Marathi, and Nepali are also written in Devanagari.","It is written from left to right."],"explanationHi":"देवनागरी लिपि ब्राह्मी लिपि से विकसित हुई है और इसके अक्षरों के ऊपर एक क्षैतिज रेखा (शिरोरेखा) होती है।","explanationEn":"Evolved from the Brahmi script, characterized by a horizontal line (shirorekha) over the letters.","memoryTip":"देवों के नगर की लिपि = देवनागरी।","memoryTipEn":"Script of the Devas -> Devanagari.","related":["Brahmi Script","Article 343"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dMVSDLkSUIJ6mcBYoBnTO', 'General Science', 'हमारी आकाशगंगा का नाम क्या है?', 'What is the name of our galaxy?', 'दुग्ध मेखला (Milky Way)', 'Milky Way (Dugdha Mekhala)', 93, 0, '{"facts":["यह एक सर्पिलाकार (Spiral) आकाशगंगा है।","हमारा सौरमंडल ओरियन आर्म (Orion Arm) नामक हिस्से में स्थित है।"],"factsEn":["It is a spiral-shaped galaxy.","Our solar system is located in the Orion Arm."],"explanationHi":"रात के आकाश में दूध की नदी की तरह दिखने के कारण इसे ''मिल्की वे'' या ''दुग्ध मेखला'' कहा जाता है।","explanationEn":"Named so because it appears as a milky band of light in the night sky.","memoryTip":"आकाश में सितारों का ''दूध'' = मिल्की वे।","memoryTipEn":"Galaxy made of Milk -> Milky Way.","related":["Andromeda Galaxy","Solar System","Spiral Galaxy"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jtcHjUHCCAoacGWPfsmp2', 'General Knowledge', 'हिंदी भाषा का पहला समाचारपत्र कौनसा था?', 'Which was the first newspaper in the Hindi language?', 'उदंत मार्तण्ड', 'Udant Martand', 89, 0, '{"facts":["यह 30 मई 1826 को कलकत्ता से प्रकाशित हुआ था।","इसके संपादक पंडित जुगल किशोर शुक्ल थे।"],"factsEn":["Published from Calcutta on May 30, 1826.","Its editor was Pandit Jugal Kishore Shukla."],"explanationHi":"30 मई को इसके प्रकाशन के कारण भारत में ''हिंदी पत्रकारिता दिवस'' मनाया जाता है।","explanationEn":"Because of its publication on May 30, ''Hindi Journalism Day'' is celebrated in India.","memoryTip":"हिंदी का पहला समाचार ''उड़ते हुए सूर्य'' (उदंत मार्तण्ड) की तरह आया।","memoryTipEn":"Udant Martand = The Rising Sun of Hindi news.","related":["Hindi Journalism Day","Jugal Kishore Shukla"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NkW1Qp1SwKcr0mQrjg4lX', 'General Knowledge', 'तुलसीदासकृत रामचरितमानस हिंदी भाषा की किस बोली में लिखी गयी है?', 'In which dialect of Hindi language is Ramcharitmanas, written by Tulsidas, composed?', 'अवधी', 'Awadhi', 88, 0, '{"facts":["अवधी, मुख्य रूप से उत्तर प्रदेश के अवध क्षेत्र में बोली जाती है।","रामचरितमानस 16वीं शताब्दी में लिखा गया था।"],"factsEn":["Awadhi is mainly spoken in the Awadh region of UP.","Ramcharitmanas was written in the 16th century."],"explanationHi":"तुलसीदास ने भगवान राम की कथा को आम लोगों तक पहुँचाने के लिए संस्कृत के बजाय स्थानीय ''अवधी'' बोली को चुना।","explanationEn":"Tulsidas chose the local Awadhi dialect over Sanskrit to make Lord Ram''s story accessible to common people.","memoryTip":"राम जी ''अवध'' (अयोध्या) के थे, इसलिए भाषा अवधी।","memoryTipEn":"Ram belongs to Awadh -> Awadhi dialect.","related":["Tulsidas","Bhojpuri","Awadh Region"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('s2_T3t3jW2pJ-TZqn5SoH', 'General Knowledge', 'हरियाणा के राज्यकवि कौन कहलाते हैं?', 'Who is known as the State Poet of Haryana?', 'उदयभानु हंस', 'Uday Bhanu Hans', 81, 0, '{"facts":["इन्हें 1966 में हरियाणा के गठन पर राज्यकवि की उपाधि दी गई थी।","इन्होंने ''हंस मुक्तावली'' और ''देशां में देश हरियाणा'' की रचना की।"],"factsEn":["Awarded the title of State Poet upon Haryana''s formation in 1966.","Composed ''Hans Muktavali''."],"explanationHi":"वे रुबाई (कविता का एक रूप) के विशेषज्ञ थे और उन्हें ''रुबाई सम्राट'' भी कहा जाता था।","explanationEn":"He was an expert in Rubai (a form of poetry) and was known as the Rubai Samrat.","memoryTip":"हरियाणा का कवि उदय होते ही ''हंस'' पड़ा।","memoryTipEn":"Hans (Swan) poet of Haryana.","related":["State Poets","Haryana Literature"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6YbvZNyj4Dh8aDlU09Wdr', 'General Knowledge', 'आधुनिक ओलंपिक खेलों की शुरूआत कब और कहाँ से हुई?', 'When and where did the modern Olympic games begin?', 'एथेंस (यूनान) में 1896 में', 'Athens (Greece) in 1896', 94, 0, '{"facts":["आधुनिक ओलंपिक का जनक पियरे डी कुबर्टिन को माना जाता है।","पहले आधुनिक ओलंपिक में केवल 14 देशों ने भाग लिया था।"],"factsEn":["Pierre de Coubertin is considered the father of the modern Olympics.","Only 14 countries participated in the first modern Olympics."],"explanationHi":"प्राचीन ओलंपिक खेलों को पुनर्जीवित करने के उद्देश्य से 1896 में यूनान (ग्रीस) की राजधानी एथेंस में इनकी शुरुआत की गई।","explanationEn":"Started in 1896 in Athens to revive the ancient Olympic games.","memoryTip":"1896 में ग्रीस (यूनान) से खेल ''ग्रो'' (बढ़े) हुए।","memoryTipEn":"Athens -> Ancient & Modern start.","related":["Pierre de Coubertin","IOC","Ancient Olympics"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qEMWmtei5fvi3QMUalKUV', 'General Knowledge', 'भारत ने किस खेल में ओलंपिक खेलों में 8 बार स्वर्ण पदक जीता है?', 'In which sport has India won 8 Olympic gold medals?', 'हाकी (Hockey)', 'Hockey', 95, 0, '{"facts":["भारत ने लगातार 6 स्वर्ण (1928-1956) जीते थे।","ध्यानचंद इन स्वर्णिम युग के प्रमुख खिलाड़ी थे।"],"factsEn":["India won 6 consecutive golds (1928-1956).","Dhyan Chand was the key player of this golden era."],"explanationHi":"हॉकी में भारत का ओलंपिक इतिहास दुनिया में सबसे सफल रहा है, कुल 8 स्वर्ण के साथ।","explanationEn":"India has the most successful Olympic history in field hockey with a total of 8 gold medals.","memoryTip":"हॉकी स्टिक का आकार थोड़ा-थोड़ा ''8'' के ऊपरी हिस्से जैसा होता है।","memoryTipEn":"Hockey -> 8 Gold Medals.","related":["Major Dhyan Chand","Tokyo 2020 Bronze"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gMobUsc_1AVfNbEaV9pGn', 'General Knowledge', 'भारत ने आखिरी बार हाकी में स्वर्ण पदक कहाँ और कब जीता था?', 'Where and when did India last win a gold medal in hockey?', '1980 मास्को में', '1980 in Moscow', 91, 0, '{"facts":["मास्को ओलंपिक (1980) में भारत ने स्पेन को 4-3 से हराकर अपना आठवाँ स्वर्ण जीता था।","हाल ही में टोक्यो ओलंपिक (2020/21) में भारत ने हॉकी में कांस्य पदक जीता है।"],"factsEn":["Won the 8th gold by defeating Spain 4-3 in Moscow 1980.","Recently, India won Bronze in Tokyo 2020."],"explanationHi":"1980 के बाद भारत को ओलंपिक हॉकी में पदक जीतने के लिए 41 साल का लंबा इंतजार करना पड़ा था।","explanationEn":"After 1980, India had to wait 41 years to win another Olympic hockey medal.","memoryTip":"1980 में ''मास्क'' पहनकर आखरी गोल्ड लाए।","memoryTipEn":"1980 Moscow was the last Gold.","related":["Moscow Olympics","V. Baskaran"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('J_CNNHpnDeR8mFWLgcpx1', 'General Knowledge', 'अंतर्राष्ट्रीय ओलंपिक समिति का मुख्यालय कहाँ स्थित है?', 'Where is the headquarters of the International Olympic Committee (IOC) located?', 'लुसान (स्विट्जरलैंड)', 'Lausanne, Switzerland', 88, 0, '{"facts":["इसे ओलंपिक राजधानी के रूप में भी जाना जाता है।","IOC की स्थापना 23 जून 1894 को हुई थी।"],"factsEn":["Also known as the Olympic Capital.","IOC was established on June 23, 1894."],"explanationHi":"IOC विश्व भर में ओलंपिक खेलों के आयोजन और प्रबंधन के लिए सर्वोच्च संस्था है।","explanationEn":"IOC is the supreme authority for organizing and managing the Olympic games worldwide.","memoryTip":"ओलंपिक के नियम ''लुसान'' (Loss नहीं) देते।","memoryTipEn":"Lausanne is the Olympic Capital.","related":["Thomas Bach","Pierre de Coubertin"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4su8fM9QQ06JlIv8Dg2pu', 'General Knowledge', 'सन 2012 में ओलंपिक खेल कहाँ हुए?', 'Where were the Olympic Games held in 2012?', 'लन्दन', 'London', 80, 0, '{"facts":["लंदन तीन बार (1908, 1948, 2012) ग्रीष्मकालीन ओलंपिक की मेजबानी करने वाला पहला शहर बना था।","इस ओलंपिक में भारत ने 6 पदक जीते थे।"],"factsEn":["London became the first city to host the Summer Olympics three times.","India won 6 medals in this Olympics."],"explanationHi":"इन खेलों का आधिकारिक शुभंकर ''वेनलॉक'' (Wenlock) था।","explanationEn":"The official mascot for these games was ''Wenlock''.","memoryTip":"2012 में ''लंदन'' ब्रिज पर खेल हुए।","memoryTipEn":"2012 -> London Calling.","related":["London Olympics 2012","Mary Kom"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('76i1H-DAhXY8P-zuSMWNP', 'General Knowledge', 'ओलंपिक ध्वज में कितने गोले हैं?', 'How many rings are there in the Olympic flag?', '5', '5', 89, 0, '{"facts":["ये 5 गोले दुनिया के पांच आबाद महाद्वीपों का प्रतिनिधित्व करते हैं।","इनके रंग नीला, पीला, काला, हरा और लाल हैं।"],"factsEn":["The 5 rings represent the five inhabited continents of the world.","Their colors are blue, yellow, black, green, and red."],"explanationHi":"सफ़ेद पृष्ठभूमि पर ये 5 रंग आपस में जुड़े हुए हैं जो दुनिया के देशों की एकता का प्रतीक है।","explanationEn":"Interlocking rings on a white background symbolize the unity of nations worldwide.","memoryTip":"दुनिया के 5 महाद्वीप = 5 गोले।","memoryTipEn":"5 Rings = 5 Continents.","related":["Olympic Symbols","Pierre de Coubertin"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uNrJwEbBCqyY49HsaezBn', 'General Knowledge', 'एक ओलंपिक में सर्वाधिक स्वर्ण पदक जीतने वाला खिलाड़ी कौन है?', 'Who is the athlete with the maximum gold medals in a single Olympics?', 'माइकल फेल्प्स', 'Michael Phelps', 93, 0, '{"facts":["इन्होंने 2008 बीजिंग ओलंपिक में 8 स्वर्ण पदक जीते थे।","वे एक अमेरिकी तैराक (Swimmer) हैं और कुल 23 ओलंपिक स्वर्ण जीत चुके हैं।"],"factsEn":["Won 8 gold medals at the 2008 Beijing Olympics.","He is an American swimmer with a total of 23 Olympic golds."],"explanationHi":"उन्होंने मार्क स्पिट्ज (7 स्वर्ण) का 1972 का पुराना रिकॉर्ड तोड़कर यह ऐतिहासिक उपलब्धि हासिल की।","explanationEn":"He broke Mark Spitz''s 1972 record (7 golds) to achieve this historic feat.","memoryTip":"पानी में मछली की तरह तैरने वाले ''माइकल फेल्प्स''।","memoryTipEn":"Phelps swims in Gold.","related":["Swimming","Mark Spitz","Beijing 2008"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JX2MyQPnnCzg1X6YsAjr8', 'General Knowledge', 'सन 2020 में ओलंपिक खेल कहाँ होंगे (पीडीएफ स्रोत अनुसार)?', 'Where were the Olympic games scheduled to be held in 2020?', 'टोकियो (जापान)', 'Tokyo (Japan)', 85, 0, '{"facts":["कोविड-19 महामारी के कारण ये खेल 2021 में आयोजित किए गए।","इन खेलों में भारत के नीरज चोपड़ा ने भाला फेंक में स्वर्ण पदक जीता।"],"factsEn":["Due to the COVID-19 pandemic, these games were held in 2021.","Neeraj Chopra won gold in Javelin throw for India here."],"explanationHi":"जापान ने दूसरी बार (पहले 1964 में) ग्रीष्मकालीन ओलंपिक की मेजबानी की।","explanationEn":"Japan hosted the Summer Olympics for the second time (first in 1964).","memoryTip":"20-20 में ''टोक्यो'' ने सबको टोका (COVID के कारण)।","memoryTipEn":"Tokyo 2020 shifted to 2021.","related":["Neeraj Chopra","COVID-19 Postponement"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2WyN8hcaI3fubjD-pLzzQ', 'General Knowledge', 'सन 2012 के ओलंपिक खेलों में कांस्य पदक जीतने वाली सायना नेहवाल का संबंध किस खेल से हैं?', 'Saina Nehwal, who won a bronze medal in the 2012 Olympics, is associated with which sport?', 'बेडमिन्टन', 'Badminton', 90, 0, '{"facts":["वह ओलंपिक पदक जीतने वाली पहली भारतीय बैडमिंटन खिलाड़ी हैं।","वे विश्व रैंकिंग में नंबर 1 पर पहुँचने वाली पहली भारतीय महिला हैं।"],"factsEn":["First Indian badminton player to win an Olympic medal.","First Indian woman to reach World No. 1 ranking."],"explanationHi":"लंदन ओलंपिक 2012 में उन्होंने चीन की वांग शिन के चोटिल होने के कारण कांस्य पदक जीता था।","explanationEn":"Won bronze at the London 2012 Olympics after China''s Wang Xin retired due to injury.","memoryTip":"सायना ने शटल ''कॉक'' से देश को मेडल दिलाया।","memoryTipEn":"Saina smashes the shuttle.","related":["PV Sindhu","London Olympics 2012"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1sjPiSnRCroDRWavZmBFV', 'General Knowledge', 'भारत ने ओलंपिक खेलों में पहली बार किस वर्ष भाग लिया था?', 'In which year did India participate in the Olympic Games for the first time?', 'सन 1900', '1900', 91, 0, '{"facts":["यह पेरिस ओलंपिक था।","भारत का प्रतिनिधित्व नॉर्मन प्रिटचर्ड ने किया था, जो एक एंग्लो-इंडियन थे।"],"factsEn":["It was the Paris Olympics.","India was represented by Norman Pritchard, an Anglo-Indian."],"explanationHi":"नॉर्मन प्रिटचर्ड ने एथलेटिक्स (200 मीटर हर्डल्स और 200 मीटर डैश) में दो रजत पदक जीते थे।","explanationEn":"Norman Pritchard won two silver medals in athletics.","memoryTip":"1900 (शुरुआत) से ही भारत ओलंपिक में है।","memoryTipEn":"Started exactly in nineteen hundred.","related":["Norman Pritchard","Paris Olympics 1900"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('iIBzW4zbScdqBndnCKD6x', 'General Knowledge', 'ओलंपिक खेलों में पदक जीतने वाली पहली भारतीय महिला खिलाड़ी कौन है?', 'Who is the first Indian female athlete to win an Olympic medal?', 'कर्णम मल्लेश्वरी', 'Karnam Malleswari', 96, 0, '{"facts":["इन्होंने सिडनी ओलंपिक (2000) में कांस्य पदक जीता था।","इनका संबंध भारोत्तोलन (Weightlifting) से है।"],"factsEn":["She won a bronze medal at the Sydney Olympics (2000).","She is associated with Weightlifting."],"explanationHi":"उन्होंने 69 किग्रा वर्ग में 240 किग्रा वजन उठाकर भारत के लिए इतिहास रचा था।","explanationEn":"She made history for India by lifting 240kg in the 69kg category.","memoryTip":"कर्णम ने ''वजन'' उठाकर मेडल जीता।","memoryTipEn":"Malleswari lifted the nation''s pride.","related":["Sydney Olympics 2000","Weightlifting"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yaJPdQ9OmwAMhaExQTrJf', 'General Knowledge', 'Back to the Vedas (वेदों की ओर लौटो) नारा किसने दिया था?', 'Who gave the slogan ''Back to the Vedas''?', 'महर्षि दयानंद', 'Maharishi Dayanand Saraswati', 89, 0, '{"facts":["वे आर्य समाज के संस्थापक थे।","उन्होंने ''सत्यार्थ प्रकाश'' नामक प्रसिद्ध पुस्तक लिखी।"],"factsEn":["He was the founder of Arya Samaj.","He wrote the famous book ''Satyarth Prakash''."],"explanationHi":"उनका मानना था कि वेद ही सच्चे ज्ञान का मूल स्रोत हैं और समाज की कुरीतियों को वैदिक शिक्षा से दूर किया जा सकता है।","explanationEn":"He believed Vedas are the source of true knowledge and societal evils can be cured by Vedic teachings.","memoryTip":"दयानंद ''वेद'' के ज्ञानी थे।","memoryTipEn":"Dayanand = Back to Vedas.","related":["Arya Samaj","Satyarth Prakash"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wa6A7HbOyr22l0UvK-KQj', 'General Science', 'पशुओं में ''मिल्क फीवर'' बीमारी किसकी कमी के कारण होती है?', 'The disease ''Milk Fever'' in animals is caused by the deficiency of what?', 'कैल्शियम', 'Calcium', 87, 0, '{"facts":["यह मुख्य रूप से गायों और भैंसों में ब्याने (जन्म देने) के समय होता है।","इसे ''हाइपोकैल्सीमिया'' (Hypocalcemia) भी कहा जाता है।"],"factsEn":["Mainly occurs in cows and buffaloes during calving.","Also called ''Hypocalcemia''."],"explanationHi":"अधिक दूध देने वाले जानवरों में दूध के साथ बहुत सारा कैल्शियम शरीर से बाहर निकल जाता है, जिससे यह बीमारी होती है।","explanationEn":"In high-yielding animals, a large amount of calcium is lost in milk, leading to this disease.","memoryTip":"दूध = कैल्शियम। मिल्क फीवर कैल्शियम की कमी से होता है।","memoryTipEn":"Milk needs Calcium; lack of it causes fever.","related":["Hypocalcemia","Animal Husbandry"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QfE6vplpoxNUeAHkhZ9YF', 'General Science', 'मानव शरीर के किस अंग द्वारा यूरिया को रक्त से फ़िल्टर किया जाता है?', 'By which organ of the human body is urea filtered from the blood?', 'गुर्दे (Kidneys)', 'Kidneys', 95, 0, '{"facts":["गुर्दे की कार्यात्मक इकाई को नेफ्रॉन (Nephron) कहते हैं।","यूरिया यकृत (Liver) में बनता है और गुर्दे द्वारा बाहर निकाला जाता है।"],"factsEn":["The functional unit of the kidney is the Nephron.","Urea is formed in the Liver and excreted by Kidneys."],"explanationHi":"गुर्दे रक्त से अपशिष्ट उत्पादों (यूरिया, अतिरिक्त लवण और पानी) को फ़िल्टर करके मूत्र (Urine) बनाते हैं।","explanationEn":"Kidneys filter waste products (urea, excess salts, and water) from blood to form urine.","memoryTip":"रक्त का ''फ़िल्टर'' मशीन = गुर्दे (किडनी)।","memoryTipEn":"Kidneys clean the blood.","related":["Nephron","Excretory System","Dialysis"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('g57SK9HFHhiiZ1bqasnYa', 'General Knowledge', 'किस एकमात्र भारतीय को अर्थशास्त्र में नोबेल पुरस्कार मिला है? (पीडीएफ स्रोत अनुसार)', 'Who is the only Indian to receive the Nobel Prize in Economics? (As per PDF source)', 'प्रो. अमर्त्य सेन', 'Prof. Amartya Sen', 94, 0, '{"facts":["इन्हें 1998 में कल्याणकारी अर्थशास्त्र (Welfare Economics) के लिए नोबेल पुरस्कार मिला था।","नोट: 2019 में अभिजीत बनर्जी (भारतीय मूल) को भी अर्थशास्त्र में नोबेल मिला है।"],"factsEn":["Received the Nobel Prize in 1998 for Welfare Economics.","Note: Abhijit Banerjee (Indian-origin) also won in 2019."],"explanationHi":"उन्होंने अकाल, गरीबी और सामाजिक पसंद के सिद्धांतों पर अपने शोध के लिए यह सम्मान प्राप्त किया।","explanationEn":"Honored for his research on famine, poverty, and social choice theory.","memoryTip":"अर्थ (पैसे) से व्यक्ति ''अमर'' (अमर्त्य) होना चाहता है।","memoryTipEn":"Amartya makes sense in Economics.","related":["Welfare Economics","Abhijit Banerjee"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6iZzHssrQ0NAEJmV0Fh8y', 'General Knowledge', 'भारत रत्न उस्ताद बिस्मिल्ला खाँ किस वाद्य यन्त्र के वादन में विख्यात रहे हैं?', 'Bharat Ratna Ustad Bismillah Khan was famous for playing which musical instrument?', 'शहनाई', 'Shehnai', 93, 0, '{"facts":["इन्हें 2001 में भारत रत्न से सम्मानित किया गया था।","इन्होंने 15 अगस्त 1947 को लाल किले पर शहनाई बजाई थी।"],"factsEn":["Awarded the Bharat Ratna in 2001.","Played the Shehnai at the Red Fort on Aug 15, 1947."],"explanationHi":"उन्होंने शहनाई जैसे लोक वाद्य यंत्र को शास्त्रीय संगीत के मंच पर लाकर वैश्विक पहचान दिलाई।","explanationEn":"He brought the folk instrument Shehnai to the classical music stage, giving it global recognition.","memoryTip":"''बिस्मिल्लाह'' बोलकर शहनाई बजाते थे।","memoryTipEn":"Bismillah''s breath brought Shehnai to life.","related":["Bharat Ratna","Classical Music"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('STnrqzxWOClfHob-omPOA', 'General Knowledge', 'भारत के अन्तिम गवर्नर जनरल कौन थे?', 'Who was the last Governor-General of India?', 'सी. राजगोपालाचारी', 'C. Rajagopalachari', 96, 0, '{"facts":["वे स्वतंत्र भारत के पहले और एकमात्र ''भारतीय'' गवर्नर-जनरल थे।","उन्हें ''राजाजी'' के नाम से भी जाना जाता था।"],"factsEn":["He was the first and only ''Indian'' Governor-General of independent India.","Also known as ''Rajaji''."],"explanationHi":"1950 में भारत के गणतंत्र बनने पर गवर्नर जनरल का पद समाप्त कर दिया गया और राष्ट्रपति का पद अस्तित्व में आया।","explanationEn":"The post was abolished when India became a republic in 1950, replaced by the President.","memoryTip":"भारत पर अंतिम ''राज'' (राजगोपालाचारी) एक भारतीय का था।","memoryTipEn":"Rajaji was the last ruler (Governor).","related":["Lord Mountbatten","First President of India"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('p3f3TcHZGjm98_MeLXvGb', 'General Knowledge', 'भिलाई इस्पात संयंत्र का निर्माण किस देश के सहयोग से किया गया था?', 'Bhilai Steel Plant was built with the collaboration of which country?', 'रूस (सोवियत संघ)', 'Russia (Soviet Union)', 90, 0, '{"facts":["यह छत्तीसगढ़ राज्य में स्थित है।","इसकी स्थापना 1955 (दूसरी पंचवर्षीय योजना) में की गई थी।"],"factsEn":["Located in the state of Chhattisgarh.","Established in 1955 (Second Five-Year Plan)."],"explanationHi":"भारत में बुनियादी ढांचे और भारी उद्योगों को विकसित करने के लिए सोवियत संघ ने तकनीकी और वित्तीय सहायता प्रदान की थी।","explanationEn":"The Soviet Union provided technical and financial aid to develop heavy industries in India.","memoryTip":"भिलाई में ''रूस'' के सहयोग से इस्पात ''पिघलाया'' (भिलाई)।","memoryTipEn":"Bhilai relies on Russian ties.","related":["Rourkela Steel Plant","Durgapur Steel Plant","Second Five-Year Plan"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DkkYszMitNA1Fr5LQp5gS', 'General Knowledge', 'उत्तरी ध्रुव में भारत के अनुसन्धान केन्द्र का नाम क्या है?', 'What is the name of India''s research center in the North Pole (Arctic)?', 'हिमाद्रि', 'Himadri', 88, 0, '{"facts":["यह नॉर्वे के स्वालबार्ड में स्थित है।","इसका उद्घाटन 2008 में हुआ था।"],"factsEn":["Located in Svalbard, Norway.","Inaugurated in 2008."],"explanationHi":"यह भारत का पहला आर्कटिक अनुसंधान स्टेशन है, जो जलवायु परिवर्तन और ग्लेशियरों का अध्ययन करता है।","explanationEn":"It is India''s first Arctic research station, studying climate change and glaciers.","memoryTip":"उत्तरी ध्रुव पर बहुत ''हिम'' (बर्फ) है = हिमाद्रि।","memoryTipEn":"Himadri means peak of snow.","related":["Maitri","Dakshin Gangotri","Bharati"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vVIxJUs8MsalVvD7Qrr1z', 'General Knowledge', 'विश्व में माउन्ट एवरेस्ट पर चढ़ने वाली प्रथम महिला कौन थी?', 'Who was the first woman in the world to climb Mount Everest?', 'जापान की जुनको तबाई', 'Junko Tabei of Japan', 92, 0, '{"facts":["उन्होंने 16 मई 1975 को एवरेस्ट फतह किया था।","वे सभी सातों महाद्वीपों की सबसे ऊंची चोटियों पर चढ़ने वाली पहली महिला भी हैं।"],"factsEn":["Summited Everest on May 16, 1975.","Also the first woman to ascend all Seven Summits."],"explanationHi":"उन्होंने एक अखिल महिला पर्वतारोहण अभियान का नेतृत्व करते हुए इतिहास रचा था।","explanationEn":"She made history by leading an all-female mountaineering expedition.","memoryTip":"जापान की जुनको ने एवरेस्ट की ऊंचाई को ''तबाही'' (तबाई) मचा दी।","memoryTipEn":"Junko Tabei reached the top.","related":["Bachendri Pal","Mount Everest","Seven Summits"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zqzb4Ic9Ef8exzckgsyRw', 'General Science', 'पीलिया किस अंग का रोग है?', 'Jaundice is a disease of which organ?', 'यकृत या लीवर (Liver)', 'Liver', 95, 0, '{"facts":["रक्त में ''बिलीरुबिन'' (Bilirubin) की मात्रा बढ़ने से पीलिया होता है।","इसमें त्वचा और आंखें पीली पड़ जाती हैं।"],"factsEn":["Caused by an excess of ''Bilirubin'' in the blood.","Skin and eyes turn yellow."],"explanationHi":"जब लीवर क्षतिग्रस्त हो जाता है या ठीक से काम नहीं करता, तो यह बिलीरुबिन को रक्त से बाहर निकालने में विफल रहता है।","explanationEn":"When the liver is damaged or dysfunctions, it fails to remove bilirubin from the blood.","memoryTip":"पीले रंग से यकृत (लीवर) खराब होता है।","memoryTipEn":"Liver failure leaves you looking yellow.","related":["Bilirubin","Hepatitis"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dmNd_OhgBB7O9IqxlHGXm', 'General Science', 'क्लोरोफिल का खनिज घटक क्या है?', 'What is the mineral component of Chlorophyll?', 'मैग्नीशियम', 'Magnesium', 94, 0, '{"facts":["क्लोरोफिल पौधों को उनका हरा रंग देता है।","यह प्रकाश संश्लेषण (Photosynthesis) के लिए आवश्यक है।"],"factsEn":["Chlorophyll gives plants their green color.","Essential for photosynthesis."],"explanationHi":"क्लोरोफिल के अणु के केंद्र में एक मैग्नीशियम आयन होता है, जो सूर्य के प्रकाश को अवशोषित करने में मदद करता है।","explanationEn":"A magnesium ion sits at the center of the chlorophyll molecule, aiding in light absorption.","memoryTip":"हरे पत्तों में ''मैजिक'' (Magnesium) होता है।","memoryTipEn":"Magnesium makes the Magic green.","related":["Photosynthesis","Hemoglobin (Iron component)"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mEsYmy69WdMm9FgjRtFA0', 'General Science', 'एल.पी.जी. (LPG) गैस में क्या होता है?', 'What does LPG gas contain?', 'ब्यूटेन (तथा प्रोपेन)', 'Butane (and Propane)', 96, 0, '{"facts":["LPG का अर्थ ''Liquefied Petroleum Gas'' है।","रिसाव का पता लगाने के लिए इसमें इथाइल मर्केप्टन मिलाया जाता है (दुर्गंध के लिए)।"],"factsEn":["LPG stands for Liquefied Petroleum Gas.","Ethyl Mercaptan is added to detect leaks (foul smell)."],"explanationHi":"रसोई गैस सिलेंडरों में मुख्य रूप से ब्यूटेन और प्रोपेन गैसों को तरल रूप में उच्च दबाव में रखा जाता है।","explanationEn":"Cooking gas cylinders primarily contain Butane and Propane in liquid form under high pressure.","memoryTip":"गैस ''ब्यूटीफुल'' (Butane) खाना पकाती है।","memoryTipEn":"Butane boils your food.","related":["Propane","Ethyl Mercaptan","Biogas"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lWB81noWE_brBoavuTOgS', 'General Knowledge', 'किसने सर्वप्रथम अशोक के अभिलेखों को पढ़ा?', 'Who deciphered the inscriptions of Ashoka first?', 'जेम्स प्रिंसेप', 'James Prinsep', 95, 0, '{"facts":["उन्होंने 1837 में ब्राह्मी और खरोष्ठी लिपियों को पढ़ा।","वे ईस्ट इंडिया कंपनी में एक अधिकारी (Mint Assay Master) थे।"],"factsEn":["Deciphered Brahmi and Kharosthi scripts in 1837.","He was an officer in the East India Company."],"explanationHi":"उनके इस कार्य से प्राचीन भारतीय इतिहास और मौर्य साम्राज्य को समझने में बड़ी सफलता मिली।","explanationEn":"His work was a breakthrough in understanding ancient Indian history and the Mauryan Empire.","memoryTip":"अशोक ''प्रिंस'' (Prinsep) की तरह राज करते थे, उनके लेख प्रिंसेप ने पढ़े।","memoryTipEn":"Prinsep parsed the pillars.","related":["Brahmi Script","Mauryan Empire","Ashoka Edicts"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3Gy_2LrFNVQKuHKt353sO', 'General Knowledge', 'किस बोद्ध भिक्षु के प्रभाव में अशोक ने बोद्ध धर्म ग्रहण किया?', 'Under the influence of which Buddhist monk did Ashoka embrace Buddhism?', 'उपगुप्त', 'Upagupta', 90, 0, '{"facts":["कलिंग युद्ध (261 ईसा पूर्व) के भारी रक्तपात के बाद अशोक का हृदय परिवर्तन हुआ।","उपगुप्त ने अशोक को अहिंसा का मार्ग दिखाया।"],"factsEn":["Ashoka had a change of heart after the massive bloodshed in the Kalinga War (261 BC).","Upagupta guided him towards non-violence."],"explanationHi":"बौद्ध परंपरा के अनुसार, भिक्षु उपगुप्त ने सम्राट अशोक को बुद्ध की शिक्षाओं से परिचित कराया और दीक्षित किया।","explanationEn":"According to Buddhist traditions, monk Upagupta introduced and initiated Emperor Ashoka into Buddhism.","memoryTip":"अशोक ने ''गुप्त'' रूप से नहीं, ''उपगुप्त'' से दीक्षा ली।","memoryTipEn":"Upagupta uplifted Ashoka.","related":["Kalinga War","Buddhism","Dhamma"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('efgW236GsUCZ4LT_mCLTo', 'General Knowledge', 'कौनसा मुगल बादशाह अशिक्षित था?', 'Which Mughal Emperor was uneducated (illiterate)?', 'अकबर', 'Akbar', 96, 0, '{"facts":["हालाँकि वह पढ़ना-लिखना नहीं जानता था, लेकिन उसे कला, साहित्य और धर्म में गहरी रुचि थी।","वह 13 साल की उम्र में गद्दी पर बैठा था।"],"factsEn":["Although illiterate, he had a deep interest in art, literature, and religion.","He ascended the throne at the age of 13."],"explanationHi":"उसके दरबार में ''नवरत्न'' (नौ विद्वान) थे, और उसने ''दीन-ए-इलाही'' नामक एक नया धर्म भी चलाया था।","explanationEn":"He had the ''Navaratnas'' (Nine Jewels) in his court and founded a new religion called ''Din-i-Ilahi''.","memoryTip":"सबसे महान मुग़ल राजा बिना पढ़े ही महान (अकबर) बना।","memoryTipEn":"Akbar couldn''t read a book, but read the people.","related":["Din-i-Ilahi","Navaratnas","Bairam Khan"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('u2udOUlUn4MKLOqEpUJ5M', 'General Knowledge', 'अमृतसर शहर की स्थापना किसने की?', 'Who founded the city of Amritsar?', 'गुरु रामदास', 'Guru Ram Das', 91, 0, '{"facts":["गुरु रामदास सिखों के चौथे गुरु थे।","उन्होंने 1577 में इस शहर की स्थापना ''रामदासपुर'' के रूप में की थी।"],"factsEn":["Guru Ram Das was the 4th Sikh Guru.","He founded the city in 1577 as ''Ramdaspur''."],"explanationHi":"मुगल सम्राट अकबर ने इस शहर को बसाने के लिए गुरु जी को भूमि दान में दी थी, जहाँ आज स्वर्ण मंदिर (हरमंदिर साहिब) स्थित है।","explanationEn":"Mughal Emperor Akbar donated the land to him to establish the city, where the Golden Temple now stands.","memoryTip":"अमृतसर में ''राम के दास'' (रामदास) ने नगरी बसाई।","memoryTipEn":"Ram Das raised Amritsar.","related":["Golden Temple","Sikh Gurus"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JGBM3CZOSvRUxlgiSibm5', 'General Knowledge', 'ग़दर पार्टी का संस्थापक कौन था?', 'Who was the founder of the Ghadar Party?', 'लाला हरदयाल', 'Lala Hardayal', 94, 0, '{"facts":["पार्टी की स्थापना 1913 में सैन फ्रांसिस्को (अमेरिका) में हुई थी।","इसके प्रथम अध्यक्ष सोहन सिंह भकना थे।"],"factsEn":["The party was founded in 1913 in San Francisco (USA).","Its first president was Sohan Singh Bhakna."],"explanationHi":"यह मुख्य रूप से प्रवासी भारतीयों (विशेषकर पंजाबियों) द्वारा भारत को ब्रिटिश शासन से मुक्त कराने के लिए बनाया गया एक क्रांतिकारी संगठन था।","explanationEn":"It was a revolutionary organization founded primarily by expatriate Indians to free India from British rule.","memoryTip":"हर ''दयाल'' इंसान ने मिलकर ग़दर (क्रांति) मचाई।","memoryTipEn":"Hardayal initiated the Ghadar.","related":["San Francisco","Sohan Singh Bhakna","Komagata Maru Incident"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xF-siRk902K5-bZozcWGF', 'General Knowledge', 'सिख इतिहास में लंगर प्रथा किसने शुरू की?', 'Who started the Langar system in Sikh history?', 'गुरु अंगद देव', 'Guru Angad Dev', 87, 0, '{"facts":["हालांकि इसकी शुरुआत गुरु नानक ने की थी, लेकिन इसे एक स्थायी संस्था के रूप में गुरु अंगद देव (दूसरे गुरु) ने स्थापित किया।","लंगर का अर्थ है सामुदायिक रसोई (Community Kitchen)।"],"factsEn":["Initiated by Guru Nanak, but institutionalized as a regular system by Guru Angad Dev (2nd Guru).","Langar means a community kitchen."],"explanationHi":"लंगर का मुख्य उद्देश्य ऊंच-नीच और जाति-पांति के भेदभाव को मिटाकर सभी को एक साथ बैठाकर भोजन कराना है।","explanationEn":"The main aim is to eradicate caste and class discrimination by making everyone sit and eat together.","memoryTip":"लंगर में सब अपने शरीर के ''अंग'' (अंगद) जोड़कर बैठते हैं।","memoryTipEn":"Angad anchored the Langar.","related":["Guru Nanak","Gurmukhi Script","Sikhism"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('99h5145FdWkHQD-UsxJnn', 'General Knowledge', 'सबसे प्राचीन वेद कौनसा है?', 'Which is the oldest Veda?', 'ऋग्वेद', 'Rigveda', 96, 0, '{"facts":["इसमें 10 मंडल (अध्याय) और 1028 सूक्त (Hymns) हैं।","प्रसिद्ध गायत्री मंत्र ऋग्वेद के तीसरे मंडल से लिया गया है।"],"factsEn":["It contains 10 Mandalas (books) and 1028 hymns.","The famous Gayatri Mantra is taken from its 3rd Mandala."],"explanationHi":"यह वैदिक संस्कृत भजनों का एक प्राचीन भारतीय संग्रह है और हिंदू धर्म के चार पवित्र ग्रंथों (वेदों) में सबसे पुराना है।","explanationEn":"It is an ancient Indian collection of Vedic Sanskrit hymns and the oldest of the four sacred Vedas of Hinduism.","memoryTip":"सबसे पहले ''ऋषि'' आए, तो वेद हुआ ''ऋग''।","memoryTipEn":"Rigveda holds the Roots.","related":["Gayatri Mantra","Samaveda","Yajurveda","Atharvaveda"]}', 'published', 1776083235, 1776083235);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KQUdN5tyUATXSEQh7PZ7K', 'General Knowledge', 'भगवान बुद्ध को ज्ञान की प्राप्ति कहाँ हुई थी?', 'Where did Lord Buddha attain enlightenment?', 'बोधगया', 'Bodh Gaya', 95, 0, '{"facts":["बोधगया बिहार राज्य में स्थित है।","ज्ञान पीपल के पेड़ (बोधि वृक्ष) के नीचे मिला था।"],"factsEn":["Located in Bihar.","Enlightenment attained under the Bodhi (Peepal) tree."],"explanationHi":"गौतम बुद्ध ने वर्षों की तपस्या के बाद निरंजना नदी के तट पर ज्ञान प्राप्त किया था।","explanationEn":"Buddha attained enlightenment on the banks of the Niranjana river after rigorous meditation.","memoryTip":"बोध (Knowledge) + गया (Place) = बोधगया।","memoryTipEn":"Bodh means realization/knowledge.","related":["Buddhism","Sarnath","Lumbini"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MBWyp21vYn_IOyajp0Fvt', 'General Knowledge', 'आर्य समाज की स्थापना किसने की?', 'Who founded the Arya Samaj?', 'स्वामी दयानंद सरस्वती', 'Swami Dayanand Saraswati', 90, 0, '{"facts":["स्थापना 1875 में बॉम्बे में हुई।","इन्होंने ''वेदों की ओर लौटो'' का नारा दिया।"],"factsEn":["Founded in 1875 in Bombay.","Gave the slogan ''Go back to Vedas''."],"explanationHi":"हिंदू धर्म में सुधार लाने और वैदिक परंपराओं को पुनर्जीवित करने के लिए आर्य समाज की स्थापना की गई।","explanationEn":"Founded to reform Hinduism and revive the Vedic traditions.","memoryTip":"आर्य (Noble) ज्ञान ''दयानंद'' (Compassion+Bliss) से आता है।","memoryTipEn":"Arya (Noble) + Dayanand.","related":["Brahmo Samaj","Satyarth Prakash"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Y9GgGXSggD3u8CSWF26IL', 'General Knowledge', 'पंजाबी भाषा की लिपि कौनसी है?', 'What is the script of the Punjabi language?', 'गुरुमुखी', 'Gurmukhi', 85, 0, '{"facts":["गुरुमुखी का अर्थ है ''गुरु के मुख से''।","इसे दूसरे सिख गुरु, गुरु अंगद देव द्वारा मानकीकृत किया गया था।"],"factsEn":["Means ''from the mouth of the Guru''.","Standardized by Guru Angad Dev."],"explanationHi":"सिखों के धार्मिक ग्रंथ इसी लिपि में लिखे गए हैं।","explanationEn":"Sikh religious texts are predominantly written in this script.","memoryTip":"पंजाब में ''गुरु'' का महत्व है, इसलिए लिपि ''गुरुमुखी''।","memoryTipEn":"Gurus speak Punjabi -> Gurmukhi.","related":["Devanagari","Sikhism","Guru Angad Dev"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bh1aC7BXChpqPO5m4q-Vb', 'General Knowledge', 'भारत की मुख्य भूमि का दक्षिणतम किनारा कौनसा है?', 'Which is the southernmost point of mainland India?', 'कन्याकुमारी', 'Kanyakumari', 88, 0, '{"facts":["यह तमिलनाडु राज्य में स्थित है।","यहाँ तीन समुद्र (अरब सागर, बंगाल की खाड़ी, हिंद महासागर) मिलते हैं।"],"factsEn":["Located in Tamil Nadu.","Confluence of three oceans happens here."],"explanationHi":"यह भारतीय प्रायद्वीप का अंतिम दक्षिणी बिंदु है (मुख्य भूमि पर)।","explanationEn":"It is the tip of the Indian peninsula on the mainland.","memoryTip":"भारत माता के चरणों में ''कन्या'' (Kanya) निवास करती है।","memoryTipEn":"Mainland ends with a ''Kumari'' (girl/goddess).","related":["Indira Point","Cape Comorin"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3BPO_YRKM688TlvKx6FP2', 'General Knowledge', 'भारत में सबसे पहले सूर्य किस राज्य में निकलता है?', 'In which Indian state does the sun rise first?', 'अरुणाचल प्रदेश', 'Arunachal Pradesh', 92, 0, '{"facts":["डोंग घाटी में सबसे पहले सूर्योदय देखा जाता है।","अरुणाचल का अर्थ ही ''उगते सूर्य की भूमि'' है।"],"factsEn":["Dong valley sees the first sunrise.","Name translates to ''Land of dawn-lit mountains''."],"explanationHi":"भारत के सबसे पूर्वी छोर पर स्थित होने के कारण यहाँ सबसे पहले सूर्योदय होता है।","explanationEn":"Being the easternmost state, it receives the first sunlight in India.","memoryTip":"अरुण = सूर्य। इसलिए अरुणाचल में सबसे पहले सूर्य आता है।","memoryTipEn":"Arun means Sun in Hindi.","related":["Dong Valley","Easternmost point of India"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nbo21sx7bOy5yGUzFXB6r', 'General Science', 'इंसुलिन का प्रयोग किस बीमारी के उपचार में होता है?', 'Insulin is used in the treatment of which disease?', 'मधुमेह (Diabetes)', 'Diabetes', 95, 0, '{"facts":["इंसुलिन अग्न्याशय (Pancreas) द्वारा स्रावित होता है।","यह रक्त शर्करा (Blood Sugar) को नियंत्रित करता है।"],"factsEn":["Secreted by the Pancreas.","Regulates blood sugar levels."],"explanationHi":"मधुमेह के रोगियों में शरीर पर्याप्त इंसुलिन नहीं बनाता है, जिससे रक्त में ग्लूकोज बढ़ जाता है।","explanationEn":"In diabetes, the body doesn''t produce enough insulin, leading to high blood glucose.","memoryTip":"Insulin In-serts Sugar into cells.","memoryTipEn":"Insulin IN-serts Sugar into cells.","related":["Pancreas","Blood Sugar","Glucagon"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lSuo5p08oQE2NLSDvzTm2', 'General Knowledge', 'बिहू किस राज्य का प्रसिद्ध त्योहार है?', 'Bihu is a famous festival of which state?', 'असम', 'Assam', 89, 0, '{"facts":["यह एक फसल कटाई का त्योहार है।","वर्ष में तीन बार (रोंगाली, कंगाली, भोगाली बिहू) मनाया जाता है।"],"factsEn":["It is a harvest festival.","Celebrated three times a year."],"explanationHi":"असमिया नव वर्ष और वसंत के आगमन का प्रतीक है।","explanationEn":"Marks the Assamese New Year and the advent of Spring.","memoryTip":"असम की ''बहू'' (Bihu) चाय बनाती है।","memoryTipEn":"Assam tea is served with Bihu dance.","related":["Rongali Bihu","Assamese Culture"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Y5mJtT-pqJJV2dV5iXC6w', 'General Science', 'कौनसा विटामिन आंवले में प्रचुर मात्रा में मिलता है?', 'Which vitamin is abundantly found in Amla (Gooseberry)?', 'विटामिन C', 'Vitamin C', 90, 0, '{"facts":["विटामिन C का रासायनिक नाम एस्कॉर्बिक एसिड है।","यह प्रतिरक्षा प्रणाली (Immunity) को मजबूत करता है।"],"factsEn":["Chemical name is Ascorbic Acid.","Boosts the immune system."],"explanationHi":"खट्टे फलों में विटामिन C पाया जाता है, जो स्कर्वी रोग से बचाता है।","explanationEn":"Citrus fruits are rich in Vitamin C, which prevents Scurvy.","memoryTip":"C से खट्टा (Citrus), आंवला खट्टा होता है।","memoryTipEn":"C for Citrus and Colds.","related":["Scurvy","Ascorbic Acid"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('sFaKTHd6Xmrjzpnu7UIVT', 'General Knowledge', 'भारत का प्रथम गवर्नर जनरल कौन था?', 'Who was the first Governor-General of India?', 'विलियम बेंटिक', 'William Bentinck', 92, 0, '{"facts":["चार्टर एक्ट 1833 के तहत इन्हें यह पद मिला।","इन्होंने सती प्रथा (1829) पर प्रतिबंध लगाया था।"],"factsEn":["Appointed under the Charter Act of 1833.","Abolished the Sati practice in 1829."],"explanationHi":"बंगाल के गवर्नर जनरल के पद को बदलकर भारत का गवर्नर जनरल कर दिया गया था।","explanationEn":"The post of Governor-General of Bengal was redesignated as Governor-General of India.","memoryTip":"बेंटिक ने सती प्रथा को ''बैन'' (Ban) किया, वही पहले बने।","memoryTipEn":"Bentinck ''Banned'' Sati as the first pan-India Governor General.","related":["Lord Canning","Sati System","Charter Act 1833"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('sC3ojAN2fca9PJSMJu6uq', 'General Knowledge', 'कागज का आविष्कार किस देश में हुआ?', 'In which country was paper invented?', 'चीन', 'China', 80, 0, '{"facts":["हान राजवंश के दौरान चाई लुन द्वारा आविष्कार किया गया था।","यह पहले शहतूत की छाल से बनाया गया था।"],"factsEn":["Invented by Cai Lun during the Han Dynasty.","Originally made from mulberry bark."],"explanationHi":"प्राचीन चीन में लेखन के लिए कागज का पहली बार निर्माण और उपयोग किया गया था।","explanationEn":"Paper was first manufactured and used for writing in ancient China.","memoryTip":"चीन (China) = कागज (Paper)।","memoryTipEn":"China -> Cai Lun -> Paper.","related":["Printing Press","Cai Lun"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bxzn2xDAKqD050NGDAwW6', 'General Knowledge', 'गौतम बुद्ध का बचपन का नाम क्या था?', 'What was the childhood name of Gautam Buddha?', 'सिद्धार्थ', 'Siddhartha', 88, 0, '{"facts":["उनके पिता का नाम शुद्धोधन और माता का नाम मायादेवी था।","उनका जन्म लुंबिनी (नेपाल) में हुआ था।"],"factsEn":["Father was Suddhodana, Mother was Mayadevi.","Born in Lumbini, Nepal."],"explanationHi":"ज्ञान प्राप्ति से पहले उन्हें राजकुमार सिद्धार्थ के नाम से जाना जाता था।","explanationEn":"Before attaining enlightenment, he was known as Prince Siddhartha.","memoryTip":"जिसका लक्ष्य (अर्थ) सिद्ध हो गया हो = सिद्धार्थ।","memoryTipEn":"Siddhartha means ''he who has attained his goals''.","related":["Buddhism","Mahamaya","Suddhodana"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('w7k0-ruCuz-uKH6ZyCcMz', 'General Knowledge', 'भारत में सशस्त्र बलों का सर्वोच्च सेनापति कौन होता है?', 'Who is the Supreme Commander of the Armed Forces in India?', 'राष्ट्रपति', 'President', 95, 0, '{"facts":["संविधान के अनुच्छेद 53(2) के तहत यह अधिकार दिया गया है।","तीनों सेनाओं के प्रमुख राष्ट्रपति को रिपोर्ट करते हैं।"],"factsEn":["Mandated by Article 53(2) of the Constitution.","All three service chiefs report to the President."],"explanationHi":"भारत के राष्ट्रपति थल सेना, नौसेना और वायु सेना के औपचारिक प्रमुख होते हैं।","explanationEn":"The President of India is the formal head of the Army, Navy, and Air Force.","memoryTip":"देश का ''प्रथम नागरिक'' ही सेना का ''सर्वोच्च'' होगा।","memoryTipEn":"First Citizen = Supreme Commander.","related":["Chief of Defence Staff","Article 53"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('a2Q4HoCSx_AhctzyTsIfB', 'General Science', 'रतौंधी किस विटामिन की कमी से होती है?', 'Night blindness is caused by the deficiency of which vitamin?', 'विटामिन A', 'Vitamin A', 94, 0, '{"facts":["विटामिन A का रासायनिक नाम रेटिनॉल (Retinol) है।","गाजर और हरी पत्तेदार सब्जियां इसके अच्छे स्रोत हैं।"],"factsEn":["Chemical name is Retinol.","Carrots and leafy greens are good sources."],"explanationHi":"विटामिन ए आंखों के रेटिना को स्वस्थ रखने के लिए आवश्यक है।","explanationEn":"Vitamin A is essential for keeping the retina of the eyes healthy.","memoryTip":"A से आँख (Eye) की बीमारी रतौंधी।","memoryTipEn":"Vitamin A for ''A''mazing Vision.","related":["Retinol","Carrot","Vision"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('owiXdsmcjlA6UKq74bnsx', 'General Knowledge', 'पोंगल किस राज्य का त्योहार है?', 'Pongal is a festival of which state?', 'तमिलनाडु', 'Tamil Nadu', 87, 0, '{"facts":["यह चार दिनों तक चलने वाला फसल उत्सव है।","मुख्य रूप से सूर्य देवता को समर्पित है।"],"factsEn":["A four-day harvest festival.","Primarily dedicated to the Sun God."],"explanationHi":"मकर संक्रांति के समय तमिलनाडु में अच्छी फसल के लिए यह पर्व मनाया जाता है।","explanationEn":"Celebrated in Tamil Nadu during Makar Sankranti for a good harvest.","memoryTip":"तमिलनाडु में पोंगल खाया जाता है।","memoryTipEn":"Pongal is both a dish and a festival in TN.","related":["Jallikattu","Makar Sankranti","Onam"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Agx4SeLH6POQNTTBvL2Yl', 'General Knowledge', 'गिद्धा और भंगड़ा किस राज्य के लोक नृत्य हैं?', 'Giddha and Bhangra are folk dances of which state?', 'पंजाब', 'Punjab', 85, 0, '{"facts":["भंगड़ा पुरुषों द्वारा किया जाता है।","गिद्धा विशेष रूप से महिलाओं का लोक नृत्य है।"],"factsEn":["Bhangra is performed by men.","Giddha is specifically a women''s folk dance."],"explanationHi":"ये नृत्य मुख्य रूप से बैसाखी के त्योहार और फसल कटाई के दौरान किए जाते हैं।","explanationEn":"These dances are mainly performed during the Baisakhi festival and harvest season.","memoryTip":"पंजाब की ऊर्जा भंगड़ा और गिद्धा में दिखती है।","memoryTipEn":"Bhangra beats belong to Punjab.","related":["Baisakhi","Folk Dances of India"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZNltfRE4rQeWOzVd9N7Rv', 'General Knowledge', 'टेलीविजन का आविष्कार किसने किया?', 'Who invented the television?', 'जॉन लोगी बेयर्ड', 'John Logie Baird', 82, 0, '{"facts":["इन्होंने 1925 में मैकेनिकल टेलीविजन का प्रदर्शन किया था।","ये स्कॉटलैंड के इंजीनियर थे।"],"factsEn":["Demonstrated mechanical television in 1925.","He was a Scottish engineer."],"explanationHi":"उन्होंने पहली बार चलती हुई छवियों को प्रसारित करने में सफलता प्राप्त की थी।","explanationEn":"He successfully transmitted moving images for the first time.","memoryTip":"टीव्ही पर हम ''बर्ड'' (Baird) देखते हैं।","memoryTipEn":"Baird broadcasted the first TV pictures.","related":["Inventions","Radio transmission"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('l4vr2NNPfUsQVfaHrJ8dh', 'General Knowledge', 'भारत की पहली महिला शासिका कौन थी?', 'Who was the first female ruler of India?', 'रजिया सुल्तान', 'Razia Sultana', 92, 0, '{"facts":["वह इल्तुतमिश की पुत्री थी।","उन्होंने 1236 से 1240 तक दिल्ली पर शासन किया।"],"factsEn":["She was the daughter of Iltutmish.","Ruled Delhi from 1236 to 1240."],"explanationHi":"वह दिल्ली सल्तनत (गुलाम वंश) की एकमात्र महिला शासिका थीं।","explanationEn":"She was the only female ruler of the Delhi Sultanate (Slave Dynasty).","memoryTip":"दिल्ली पर ''राज'' करने वाली पहली महिला ''रजिया''।","memoryTipEn":"Razia Ruled Royalty.","related":["Delhi Sultanate","Slave Dynasty","Iltutmish"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('en-T8znBdsQhEoJOJ6iPG', 'General Science', 'मछली किसकी सहायता से सांस लेती है?', 'With whose help does a fish breathe?', 'गलफड़ों (Gills)', 'Gills', 80, 0, '{"facts":["गलफड़े पानी में घुली हुई ऑक्सीजन को सोख लेते हैं।","पानी मुंह से अंदर जाता है और गलफड़ों से बाहर आता है।"],"factsEn":["Gills absorb dissolved oxygen from water.","Water enters the mouth and exits through gills."],"explanationHi":"गलफड़ों में रक्त वाहिकाएं होती हैं जो सीधे ऑक्सीजन ग्रहण करती हैं और कार्बन डाइऑक्साइड छोड़ती हैं।","explanationEn":"Blood vessels in the gills absorb oxygen directly and release carbon dioxide.","memoryTip":"गले में ''गलफड़े'' पानी छानते हैं।","memoryTipEn":"Gills Filter dissolved oxygen.","related":["Aquatic Respiration","Lungs"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xTGqZVCD_XowWigfMs0Nr', 'General Knowledge', '''इंकलाब जिंदाबाद'' का नारा किसने दिया?', 'Who gave the slogan ''Inquilab Zindabad''?', 'भगत सिंह', 'Bhagat Singh', 96, 0, '{"facts":["मूल रूप से इसे हसरत मोहानी ने लिखा था, लेकिन भगत सिंह ने इसे लोकप्रिय बनाया।","इसका अर्थ है ''क्रांति अमर रहे''।"],"factsEn":["Originally coined by Hasrat Mohani, popularized by Bhagat Singh.","Means ''Long live the revolution''."],"explanationHi":"सेंट्रल असेंबली में बम फेंकने के बाद भगत सिंह और बटुकेश्वर दत्त ने यह नारा लगाया था।","explanationEn":"Shouted by Bhagat Singh and Batukeshwar Dutt after bombing the Central Assembly.","memoryTip":"क्रांति (Inquilab) के प्रतीक भगत सिंह।","memoryTipEn":"Bhagat Singh popularized Revolution (Inquilab).","related":["Hasrat Mohani","Indian Freedom Struggle"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ujHX1am-MqJf6oemKdiX4', 'General Knowledge', 'जलियांवाला बाग हत्याकांड कब व कहाँ हुआ?', 'When and where did the Jallianwala Bagh massacre take place?', '1919 ई., अमृतसर', '1919, Amritsar', 98, 0, '{"facts":["यह 13 अप्रैल 1919 को बैसाखी के दिन हुआ था।","जनरल डायर ने निहत्थी भीड़ पर गोलियां चलवाई थीं।"],"factsEn":["Happened on 13 April 1919 (Baisakhi day).","General Dyer ordered firing on an unarmed crowd."],"explanationHi":"लोग रॉलेट एक्ट और दो नेताओं (सत्यपाल और सैफुद्दीन किचलू) की गिरफ्तारी का विरोध करने जमा हुए थे।","explanationEn":"People gathered to protest the Rowlatt Act and the arrest of two leaders.","memoryTip":"13 अप्रैल 1919 को अमृतसर खून से रंग गया।","memoryTipEn":"1919 Amritsar Massacre.","related":["Rowlatt Act","General Dyer","Udham Singh"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zQopXA84tnVH91A5FZXlC', 'General Knowledge', '1939 ई. में कांग्रेस छोड़ने के बाद सुभाषचंद्र बोस ने किस दल की स्थापना की?', 'Which party was founded by Subhash Chandra Bose after leaving Congress in 1939?', 'फॉरवर्ड ब्लॉक', 'Forward Bloc', 93, 0, '{"facts":["इसकी स्थापना वामपंथी विचारधारा को संगठित करने के लिए की गई थी।","गांधीजी के साथ वैचारिक मतभेद के कारण उन्होंने कांग्रेस छोड़ी।"],"factsEn":["Founded to consolidate the left-wing ideology.","He left Congress due to ideological differences with Gandhi."],"explanationHi":"त्रिपुरी अधिवेशन के बाद बोस ने अध्यक्ष पद से इस्तीफा दिया और ऑल इंडिया फॉरवर्ड ब्लॉक बनाया।","explanationEn":"After the Tripuri session, Bose resigned and formed the All India Forward Bloc.","memoryTip":"बोस हमेशा ''फॉरवर्ड'' (आगे) सोचते थे।","memoryTipEn":"Bose moved ''Forward'' out of Congress.","related":["Tripuri Session","Pattabhi Sitaramayya","INA"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Jwi2GlgkfDNug6ER5n05i', 'General Knowledge', '''पंजाब केसरी'' किसे कहा जाता है?', 'Who is known as ''Punjab Kesari''?', 'लाला लाजपत राय', 'Lala Lajpat Rai', 91, 0, '{"facts":["वे ''लाल-बाल-पाल'' की तिकड़ी के सदस्य थे।","साइमन कमीशन का विरोध करते हुए लाठीचार्ज में वे घायल हुए थे।"],"factsEn":["Part of the ''Lal-Bal-Pal'' trio.","Injured in a lathi charge while protesting the Simon Commission."],"explanationHi":"उनके साहस और पंजाब के प्रति योगदान के कारण उन्हें शेर-ए-पंजाब या पंजाब केसरी कहा गया।","explanationEn":"Known as the Lion of Punjab for his bravery and contribution.","memoryTip":"पंजाब का ''शेर'' (केसरी) = लाला जी।","memoryTipEn":"Kesari means Lion -> Lion of Punjab.","related":["Simon Commission","Lal Bal Pal"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3Frfge9Gs4a1752EiFoVS', 'General Knowledge', 'सांडर्स की हत्या किसने की थी?', 'Who assassinated Saunders?', 'भगत सिंह', 'Bhagat Singh', 88, 0, '{"facts":["लाला लाजपत राय की मौत का बदला लेने के लिए हत्या की गई।","दिसंबर 1928 में लाहौर में हत्या की गई।"],"factsEn":["Assassinated to avenge the death of Lala Lajpat Rai.","Killed in Lahore in December 1928."],"explanationHi":"भगत सिंह, राजगुरु और चंद्रशेखर आजाद ने जेम्स ए. स्कॉट को मारने की योजना बनाई थी, लेकिन गलती से जॉन पी. सांडर्स को मार दिया।","explanationEn":"They intended to kill James A. Scott but mistakenly shot John P. Saunders.","memoryTip":"लाला जी के लाठीचार्ज का बदला सांडर्स को मारकर लिया गया।","memoryTipEn":"Revenge for Lala Lajpat Rai.","related":["Lala Lajpat Rai","Rajguru","Chandrashekhar Azad"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QoqTy0yXvfn52yvVz8RH7', 'General Knowledge', '1857 ई. के विद्रोह में किसने अपना बलिदान सबसे पहले दिया?', 'Who gave his sacrifice first in the revolt of 1857?', 'मंगल पांडे', 'Mangal Pandey', 95, 0, '{"facts":["वे बैरकपुर छावनी (बंगाल) में 34वीं बंगाल नेटिव इन्फैंट्री के सिपाही थे।","उन्हें 8 अप्रैल 1857 को फाँसी दी गई।"],"factsEn":["Sepoy in the 34th Bengal Native Infantry at Barrackpore.","Hanged on 8 April 1857."],"explanationHi":"उन्होंने गाय और सूअर की चर्बी वाले कारतूसों का उपयोग करने से मना कर दिया और ब्रिटिश अधिकारियों पर हमला किया।","explanationEn":"He refused to use greased cartridges and attacked British officers.","memoryTip":"1857 का ''मंगल'' (आरंभ) मंगल पांडे से हुआ।","memoryTipEn":"First spark of 1857 was Mangal.","related":["Revolt of 1857","Barrackpore Mutiny"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1d9wl7c2xCsDVbXQqjs8E', 'General Knowledge', 'भारत की पहली महिला राज्यपाल कौन थी?', 'Who was the first female Governor of India?', 'सरोजिनी नायडु', 'Sarojini Naidu', 94, 0, '{"facts":["वह उत्तर प्रदेश (संयुक्त प्रांत) की राज्यपाल बनी थीं।","इन्हें ''भारत कोकिला'' (Nightingale of India) भी कहा जाता है।"],"factsEn":["Became Governor of United Provinces (UP).","Known as the Nightingale of India."],"explanationHi":"वह 1947 में भारत की स्वतंत्रता के बाद किसी राज्य की राज्यपाल बनने वाली पहली महिला थीं।","explanationEn":"She became the first woman to hold the governor''s office in independent India in 1947.","memoryTip":"राज्यपाल का ''ताज'' पहली बार ''कोकिला'' सरोजिनी को मिला।","memoryTipEn":"Nightingale of India became the first Governor.","related":["Sucheta Kriplani","Nightingale of India"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rOzxpu3I0KvZNipzK3dw8', 'General Knowledge', 'माउन्ट एवेरेस्ट पर दो बार चढ़ने वाली पहली महिला कौन थी?', 'Who was the first woman to climb Mount Everest twice?', 'संतोष यादव', 'Santosh Yadav', 90, 0, '{"facts":["उन्होंने 1992 और 1993 में एवरेस्ट फतह किया।","कंगशुंग फेस से एवरेस्ट पर चढ़ने वाली पहली महिला।"],"factsEn":["Summited in 1992 and 1993.","First woman to climb Everest from the Kangshung face."],"explanationHi":"वह लगातार दो बार विश्व की सबसे ऊंची चोटी पर चढ़ने वाली पहली महिला बनीं।","explanationEn":"First woman globally to reach the summit twice continuously.","memoryTip":"एक बार चढ़कर ''संतोष'' नहीं हुआ, इसलिए दो बार चढ़ीं संतोष यादव।","memoryTipEn":"Santosh wasn''t ''satisfied'' with just one climb.","related":["Bachendri Pal","Mount Everest"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DxhHYurb78gHm9NDqqnLC', 'General Knowledge', '''ब्रह्म समाज'' की स्थापना किसके द्वारा की गई?', 'Who founded the ''Brahmo Samaj''?', 'राजा राममोहन राय', 'Raja Ram Mohan Roy', 96, 0, '{"facts":["1828 में कलकत्ता में स्थापना हुई।","इन्होंने सती प्रथा के खिलाफ बड़ा आंदोलन चलाया।"],"factsEn":["Founded in 1828 in Calcutta.","Campaigned heavily against the Sati system."],"explanationHi":"ब्रह्म समाज ने मूर्ति पूजा, जाति व्यवस्था और अन्य कुरीतियों का विरोध किया।","explanationEn":"Brahmo Samaj opposed idol worship, the caste system, and social evils.","memoryTip":"राम और मोहन ने मिलकर ''ब्रह्म'' का ज्ञान दिया।","memoryTipEn":"Raja Ram reformed the Brahmo way.","related":["Atmiya Sabha","Sati System","Indian Renaissance"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0t6ZCTqo5akGAOJpmvDdA', 'General Knowledge', 'स्वामी दयानंद सरस्वती का मूल नाम क्या था?', 'What was the original name of Swami Dayanand Saraswati?', 'मूलशंकर', 'Moolshankar', 86, 0, '{"facts":["उनका जन्म गुजरात के मोरबी में हुआ था।","वे आर्य समाज के संस्थापक थे।"],"factsEn":["Born in Morbi, Gujarat.","Founder of Arya Samaj."],"explanationHi":"उनके ''मूल'' नाम से ही पता चलता है कि वे वैदिक जड़ों (मूल) की ओर लौटना चाहते थे।","explanationEn":"He wanted to go back to the ''roots'' (Vedas).","memoryTip":"दयानंद का ''मूल'' नाम ''मूलशंकर'' था।","memoryTipEn":"Original name = Mool (Root) Shankar.","related":["Arya Samaj","Go back to Vedas"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KxZ_EfA0NbH9KfUIGC3nb', 'General Knowledge', '''वेदों की ओर लौटो'' का नारा किसने दिया?', 'Who gave the slogan ''Go back to Vedas''?', 'दयानंद सरस्वती', 'Dayanand Saraswati', 91, 0, '{"facts":["यह नारा आर्य समाज का मुख्य सिद्धांत था।","उनका मानना था कि वेद ही सच्चे ज्ञान का स्रोत हैं।"],"factsEn":["Main principle of Arya Samaj.","Believed Vedas are the true source of knowledge."],"explanationHi":"उन्होंने हिंदू समाज की कुरीतियों को दूर करने के लिए वैदिक जीवन शैली अपनाने पर जोर दिया।","explanationEn":"He emphasized adopting the Vedic lifestyle to eradicate social evils in Hinduism.","memoryTip":"सरस्वती (विद्या की देवी) का वास ''वेदों'' में है।","memoryTipEn":"Saraswati = Goddess of Knowledge -> Vedas.","related":["Arya Samaj","Satyarth Prakash"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aF33Vh7MdOlHsh62l-l_9', 'General Knowledge', '''रामकृष्ण मिशन'' की स्थापना किसने की?', 'Who founded the ''Ramakrishna Mission''?', 'स्वामी विवेकानंद', 'Swami Vivekananda', 95, 0, '{"facts":["स्थापना 1 मई 1897 को हुई।","मुख्यालय बेलूर मठ (पश्चिम बंगाल) में है।"],"factsEn":["Founded on May 1, 1897.","Headquarters at Belur Math, West Bengal."],"explanationHi":"यह मिशन उनके गुरु रामकृष्ण परमहंस के आदर्शों और वेदांत दर्शन के प्रचार-प्रसार के लिए बनाया गया था।","explanationEn":"Created to spread the ideals of his guru Ramakrishna Paramahamsa and Vedanta philosophy.","memoryTip":"विवेकानंद ने अपने गुरु (रामकृष्ण) के नाम पर मिशन शुरू किया।","memoryTipEn":"Vivekananda honored his guru Ramakrishna.","related":["Belur Math","Ramakrishna Paramahamsa","Vedanta"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XezfkA70auB5jpdRtgKWc', 'General Knowledge', 'वास्कोडिगामा भारत कब आया?', 'When did Vasco da Gama come to India?', '1498 ई.', '1498 AD', 93, 0, '{"facts":["वह केरल के कालीकट (कोझिकोड) तट पर पहुंचा था।","वहां के राजा ''जमोरिन'' ने उसका स्वागत किया था।"],"factsEn":["Arrived at the port of Calicut (Kozhikode), Kerala.","Welcomed by the local ruler, Zamorin."],"explanationHi":"उसने यूरोप से भारत तक केप ऑफ गुड होप होते हुए सीधे समुद्री मार्ग की खोज की।","explanationEn":"He discovered the direct sea route from Europe to India via the Cape of Good Hope.","memoryTip":"14-9-8 (क्रम याद रखें: 1498)।","memoryTipEn":"1498: Vasco navigates.","related":["Zamorin","Calicut","Cape of Good Hope"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2raJHOT5We5A4RXCKAAId', 'General Knowledge', 'वास्कोडिगामा कहाँ का रहने वाला था?', 'Where was Vasco da Gama from?', 'पुर्तगाल', 'Portugal', 88, 0, '{"facts":["वह एक पुर्तगाली नाविक और खोजकर्ता था।","भारत आने वाले पहले यूरोपीय पुर्तगाली ही थे।"],"factsEn":["He was a Portuguese explorer.","Portuguese were the first Europeans to reach India by sea."],"explanationHi":"पुर्तगालियों ने ही सबसे पहले भारत में व्यापारिक केंद्र स्थापित किए (कोचीन में)।","explanationEn":"The Portuguese established the first European trading centers in India.","memoryTip":"पुर्तगाल से ''पोर'' (Port) होते हुए भारत आया।","memoryTipEn":"Portugal -> Port explorer.","related":["Estado da India","Cochin","Goa"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4ZHpldF_cArzOxW46igzl', 'General Knowledge', 'हवा महल कहाँ स्थित है?', 'Where is Hawa Mahal located?', 'जयपुर', 'Jaipur', 86, 0, '{"facts":["इसे महाराजा सवाई प्रताप सिंह ने 1799 में बनवाया था।","इसमें 953 छोटी खिड़कियां (झरोखे) हैं।"],"factsEn":["Built by Maharaja Sawai Pratap Singh in 1799.","Has 953 small windows (jharokhas)."],"explanationHi":"शाही महिलाओं को शहर के त्योहारों को बिना किसी के देखे देखने की अनुमति देने के लिए इसे बनवाया गया था।","explanationEn":"Built to allow royal ladies to observe street festivals unseen.","memoryTip":"गुलाबी नगर (जयपुर) में गुलाबी हवा महल है।","memoryTipEn":"Palace of Winds is in the Pink City.","related":["Pink City","Sawai Pratap Singh","Rajasthan Architecture"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FvlKEJyqq0mCj75B5Qglp', 'General Knowledge', 'सिख धर्म का संस्थापक किस सिख गुरु को माना जाता है?', 'Which Sikh Guru is considered the founder of Sikhism?', 'गुरु नानक', 'Guru Nanak', 92, 0, '{"facts":["वे सिखों के दस गुरुओं में से पहले गुरु थे।","उनका जन्म तलवंडी (अब पाकिस्तान में ननकाना साहिब) में हुआ था।"],"factsEn":["First of the ten Sikh Gurus.","Born in Talwandi (now Nankana Sahib, Pakistan)."],"explanationHi":"उन्होंने 15वीं शताब्दी में समानता और एकेश्वरवाद का उपदेश देते हुए सिख धर्म की नींव रखी।","explanationEn":"Founded Sikhism in the 15th century, preaching equality and monotheism.","memoryTip":"सिख धर्म के ''नानक'' (जनक)।","memoryTipEn":"First Guru -> Guru Nanak.","related":["Guru Granth Sahib","Nankana Sahib","Sikh Gurus"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aE2qznyRsyZPTTVZWOrGu', 'General Knowledge', 'सिखों का प्रमुख त्यौहार कौन-सा है?', 'Which is the major festival of Sikhs?', 'बैसाखी', 'Baisakhi', 88, 0, '{"facts":["यह वसंत ऋतु का फसल उत्सव है।","इसी दिन 1699 में गुरु गोबिंद सिंह ने खालसा पंथ की स्थापना की थी।"],"factsEn":["A spring harvest festival.","Khalsa Panth was founded on this day in 1699 by Guru Gobind Singh."],"explanationHi":"यह सिखों के लिए एक धार्मिक और कृषि उत्सव दोनों है।","explanationEn":"It is both a religious and agricultural festival for Sikhs.","memoryTip":"बैसाखी में ''खालसा'' की साखी (कथा) जुड़ी है।","memoryTipEn":"Baisakhi -> Birth of Khalsa.","related":["Khalsa Panth","Guru Gobind Singh","Harvest Festival"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('VEC1jgPgC_R8BFtOX9qXo', 'General Knowledge', '''लौह पुरुष'' किस महापुरुष को कहा जाता है?', 'Which great man is known as the ''Iron Man''?', 'सरदार वल्लभभाई पटेल', 'Sardar Vallabhbhai Patel', 96, 0, '{"facts":["वे भारत के पहले उप प्रधानमंत्री और गृह मंत्री थे।","उन्होंने 562 रियासतों को भारत में एकीकृत किया।"],"factsEn":["First Deputy PM and Home Minister of India.","Integrated 562 princely states into India."],"explanationHi":"रियासतों के एकीकरण में उनके दृढ़ संकल्प के कारण उन्हें ''भारत का लौह पुरुष'' कहा गया।","explanationEn":"Called Iron Man for his iron will in integrating the princely states.","memoryTip":"पटेल जी का इरादा ''लोहे'' जैसा मजबूत था।","memoryTipEn":"Iron Man -> Statue of Unity -> Patel.","related":["Statue of Unity","Bismarck of India","Bardoli Satyagraha"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NcR_KZ7AzCStwmEZ4S6rg', 'General Knowledge', 'नेताजी किस महापुरुष को कहा जाता है?', 'Which great man is called ''Netaji''?', 'सुभाष चंद्र बोस', 'Subhas Chandra Bose', 94, 0, '{"facts":["इन्होंने ''आजाद हिंद फौज'' का पुनर्गठन किया।","''तुम मुझे खून दो, मैं तुम्हें आजादी दूंगा'' का प्रसिद्ध नारा दिया।"],"factsEn":["Reorganized the ''Indian National Army'' (INA).","Gave the famous slogan ''Give me blood, and I shall give you freedom''."],"explanationHi":"भारत के स्वतंत्रता संग्राम में उनके असाधारण नेतृत्व के लिए लोगों और भारतीय सैनिकों ने उन्हें ''नेताजी'' की उपाधि दी।","explanationEn":"Given the title ''Netaji'' (Respected Leader) by Indian soldiers in Germany.","memoryTip":"हमारे ''नेता'' सुभाष बाबू।","memoryTipEn":"Netaji = Leader -> Bose.","related":["Azad Hind Fauj","Forward Bloc","Parakram Diwas"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZL_AD4qloYQlHgB5-9Nx0', 'General Knowledge', 'दिल्ली स्थित लाल बहादुर शास्त्री की समाधि का क्या नाम है?', 'What is the name of the memorial of Lal Bahadur Shastri in Delhi?', 'विजय घाट', 'Vijay Ghat', 89, 0, '{"facts":["यह नई दिल्ली में यमुना नदी के तट पर स्थित है।","यह 1965 के युद्ध में पाकिस्तान पर भारत की विजय का भी प्रतीक है।"],"factsEn":["Located on the banks of Yamuna river in New Delhi.","Symbolizes India''s victory over Pakistan in the 1965 war."],"explanationHi":"भारत के दूसरे प्रधानमंत्री लाल बहादुर शास्त्री के सम्मान में इसे विजय घाट नाम दिया गया।","explanationEn":"Named ''Vijay Ghat'' (Victory Bank) to honor the 2nd PM who led India during the 1965 war.","memoryTip":"बहादुर लोग हमेशा ''विजय'' प्राप्त करते हैं।","memoryTipEn":"Brave (Bahadur) brings Victory (Vijay).","related":["Raj Ghat","Kisan Ghat","Tashkent Agreement"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('W8zyGXVF8JkHiNlVVdOBM', 'General Knowledge', 'महाभारत के रचयिता कौन हैं?', 'Who is the author of Mahabharata?', 'महर्षि वेदव्यास', 'Maharishi Ved Vyas', 91, 0, '{"facts":["महाभारत दुनिया का सबसे लंबा महाकाव्य है।","श्रीमद्भगवद्गीता इसी महाकाव्य का एक हिस्सा (भीष्म पर्व) है।"],"factsEn":["Mahabharata is the longest epic poem in the world.","Bhagavad Gita is a part of it (Bhishma Parva)."],"explanationHi":"महर्षि वेदव्यास ने महाभारत की रचना की और भगवान गणेश ने इसे लिखा था।","explanationEn":"Dictated by Ved Vyas and written down by Lord Ganesha.","memoryTip":"वेद और महाभारत दोनों ''व्यास'' जी ने संकलित किए।","memoryTipEn":"Vyas wrote the Vast epic.","related":["Ramayana","Bhagavad Gita","Kurukshetra"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8MZAz_iK4Br_trL9v_HwQ', 'General Knowledge', 'अर्थशास्त्र नामक पुस्तक किसने लिखी?', 'Who wrote the book named Arthashastra?', 'चाणक्य (कौटिल्य / विष्णुगुप्त)', 'Chanakya (Kautilya)', 95, 0, '{"facts":["यह राज्यकला, आर्थिक नीति और सैन्य रणनीति पर एक प्राचीन भारतीय ग्रंथ है।","चाणक्य चंद्रगुप्त मौर्य के प्रधानमंत्री थे।"],"factsEn":["An ancient Indian treatise on statecraft, economic policy, and military strategy.","Chanakya was the PM of Chandragupta Maurya."],"explanationHi":"इस पुस्तक में मौर्य साम्राज्य के प्रशासन के बारे में विस्तृत जानकारी है।","explanationEn":"Provides detailed insights into the administration of the Mauryan Empire.","memoryTip":"कौटिल्य की कूटनीति = अर्थशास्त्र।","memoryTipEn":"Kautilya''s economics = Arthashastra.","related":["Chandragupta Maurya","Mauryan Empire","Vishnugupta"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AIURBjRMa-vfnSpmTqHNk', 'General Knowledge', '''जय जवान, जय किसान'' का नारा किसने दिया?', 'Who gave the slogan ''Jai Jawan, Jai Kisan''?', 'लाल बहादुर शास्त्री', 'Lal Bahadur Shastri', 96, 0, '{"facts":["यह नारा 1965 के भारत-पाकिस्तान युद्ध के दौरान दिया गया था।","अटल बिहारी वाजपेयी ने इसमें ''जय विज्ञान'' जोड़ा था।"],"factsEn":["Given during the 1965 India-Pakistan war.","Atal Bihari Vajpayee later added ''Jai Vigyan'' to it."],"explanationHi":"सैनिकों (जवानों) और किसानों का मनोबल बढ़ाने के लिए यह नारा दिया गया था, क्योंकि देश युद्ध और अन्न की कमी का सामना कर रहा था।","explanationEn":"To boost the morale of soldiers and farmers when India was facing war and food scarcity.","memoryTip":"शास्त्री जी ने जवान और किसान दोनों की महिमा गाई।","memoryTipEn":"Shastri honored soldiers and farmers.","related":["1965 Indo-Pak War","Green Revolution"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4ketyOt2fxYSNfxm9f2aU', 'General Knowledge', 'संविधान सभा का स्थाई अध्यक्ष कौन था?', 'Who was the permanent President of the Constituent Assembly?', 'डॉ. राजेन्द्र प्रसाद', 'Dr. Rajendra Prasad', 95, 0, '{"facts":["उन्हें 11 दिसंबर 1946 को अध्यक्ष चुना गया था।","अस्थाई अध्यक्ष डॉ. सच्चिदानंद सिन्हा थे (9 दिसंबर को)।"],"factsEn":["Elected on December 11, 1946.","Dr. Sachchidananda Sinha was the interim president."],"explanationHi":"वे बाद में स्वतंत्र भारत के पहले राष्ट्रपति भी बने।","explanationEn":"He later became the first President of independent India.","memoryTip":"प्रसाद के रूप में हमें ''स्थाई'' संविधान मिला।","memoryTipEn":"First President of India = Permanent President of Assembly.","related":["Constituent Assembly","Dr. Sachchidananda Sinha","Drafting Committee"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bEwFgvcokxKaEj9eb6CHf', 'General Knowledge', 'संविधान सभा की प्रारूप समिति के अध्यक्ष कौन थे?', 'Who was the Chairman of the Drafting Committee of the Constituent Assembly?', 'डॉ. भीमराव अंबेडकर', 'Dr. B. R. Ambedkar', 98, 0, '{"facts":["प्रारूप समिति का गठन 29 अगस्त 1947 को हुआ था।","समिति में अध्यक्ष सहित 7 सदस्य थे।"],"factsEn":["Drafting Committee was formed on Aug 29, 1947.","It had 7 members including the Chairman."],"explanationHi":"उन्हें भारतीय संविधान के ''जनक'' या ''निर्माता'' के रूप में जाना जाता है।","explanationEn":"Known as the Father of the Indian Constitution.","memoryTip":"अंबेडकर जी ने संविधान का ''रूप'' (प्रारूप) तैयार किया।","memoryTipEn":"Ambedkar drafted our future.","related":["Father of Indian Constitution","Article 32"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4fn0tmHJRtZRwvqzUx-ws', 'General Knowledge', 'विश्व रेडक्रॉस दिवस किस तारीख को मनाया जाता है?', 'On which date is World Red Cross Day celebrated?', '8 मई', '8 May', 84, 0, '{"facts":["यह हेनरी ड्यूनेंट के जन्मदिन पर मनाया जाता है।","हेनरी ड्यूनेंट इंटरनेशनल कमिटी ऑफ द रेड क्रॉस (ICRC) के संस्थापक थे।"],"factsEn":["Celebrated on the birthday of Henry Dunant.","Henry Dunant founded the ICRC."],"explanationHi":"यह दिन मानवीय कार्यों और रेडक्रॉस स्वयंसेवकों को सम्मानित करने के लिए मनाया जाता है।","explanationEn":"Celebrated to honor humanitarian efforts and Red Cross volunteers.","memoryTip":"मई (May) में 8 (आठ) दिशाओं में रेडक्रॉस मदद करता है।","memoryTipEn":"May 8 -> Mate -> Helping mate -> Red Cross.","related":["Henry Dunant","Geneva Conventions"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xm78_5otBhYvEItO9Pk8O', 'General Knowledge', 'सूर्योदय का देश के नाम से कौनसा देश प्रसिद्ध है?', 'Which country is famous as the ''Land of the Rising Sun''?', 'जापान', 'Japan', 90, 0, '{"facts":["जापानी भाषा में इसे ''निप्पॉन'' (Nippon) या ''निहोन'' कहते हैं, जिसका अर्थ सूर्य का मूल है।","यह एशिया के सुदूर पूर्व में स्थित है।"],"factsEn":["In Japanese, it''s called ''Nippon'' meaning origin of the sun.","Located in the far east of Asia."],"explanationHi":"प्राचीन चीनियों के नजरिए से सूर्य जापान की दिशा से उगता हुआ दिखाई देता था।","explanationEn":"From China''s perspective, the sun appeared to rise from Japan''s direction.","memoryTip":"जा-पान -> जहाँ से सूरज पान करता है रोशनी का।","memoryTipEn":"Japan is far east, gets sun first in the region.","related":["Nippon","Midnight Sun (Norway)"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3IFQMjouJjYUL1ksei1lW', 'General Knowledge', 'अन्तर्राष्ट्रीय महिला दिवस किस तिथि को मनाया जाता है?', 'On which date is International Women''s Day celebrated?', '8 मार्च', '8 March', 92, 0, '{"facts":["इसे संयुक्त राष्ट्र द्वारा भी मान्यता प्राप्त है।","यह महिलाओं के अधिकारों और महिला सशक्तीकरण का जश्न मनाता है।"],"factsEn":["Recognized by the United Nations.","Celebrates women''s rights and empowerment."],"explanationHi":"महिलाओं की सामाजिक, आर्थिक, सांस्कृतिक और राजनीतिक उपलब्धियों का जश्न मनाने के लिए यह दिन मनाया जाता है।","explanationEn":"A global day celebrating the social, economic, cultural, and political achievements of women.","memoryTip":"मार्च (March) करती महिलाएँ (8)।","memoryTipEn":"Marching forward on the 8th.","related":["National Women''s Day (Feb 13)"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Z4GBp6ptK5XJMg5-FJs3n', 'General Knowledge', 'क्षेत्रफल की दृष्टि से भारत में सबसे छोटा राज्य कौन-सा है?', 'Which is the smallest state in India in terms of area?', 'गोवा', 'Goa', 93, 0, '{"facts":["इसका क्षेत्रफल केवल 3,702 वर्ग किलोमीटर है।","जनसंख्या के हिसाब से सबसे छोटा राज्य सिक्किम है।"],"factsEn":["Its area is only 3,702 sq km.","Smallest state by population is Sikkim."],"explanationHi":"गोवा भारत के पश्चिमी तट (कोंकण क्षेत्र) पर स्थित है।","explanationEn":"Goa is located on the western coast of India (Konkan region).","memoryTip":"गोवा ''गया'' और तुरंत खत्म हो गया (सबसे छोटा)।","memoryTipEn":"Goa is tiny like a dot on the west coast.","related":["Sikkim","Rajasthan (Largest Area)"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('INCYST-0WUxms6qggxYrB', 'General Knowledge', 'ओणम किस राज्य का प्रसिद्ध त्योहार है?', 'Onam is a famous festival of which state?', 'केरल', 'Kerala', 90, 0, '{"facts":["यह एक फसल उत्सव है।","राजा महाबली के स्वागत में मनाया जाता है।"],"factsEn":["It is a harvest festival.","Celebrated to welcome King Mahabali."],"explanationHi":"इस त्योहार के दौरान प्रसिद्ध नौका दौड़ (वल्लमकली) आयोजित की जाती है।","explanationEn":"The famous snake boat race (Vallamkali) is held during this festival.","memoryTip":"केरल के लोग ''ओणम'' पर केले के पत्ते पर खाते हैं।","memoryTipEn":"K-O: Kerala - Onam.","related":["Pongal","Snake Boat Race","King Mahabali"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('96Bw3snDLN9mmt5gmsERi', 'General Knowledge', 'दिल्ली भारत की राजधानी कब बनी?', 'When did Delhi become the capital of India?', '1911', '1911', 94, 0, '{"facts":["1911 के दिल्ली दरबार में जॉर्ज पंचम ने इसकी घोषणा की थी।","इससे पहले भारत की राजधानी कलकत्ता (अब कोलकाता) थी।"],"factsEn":["Announced by King George V in the 1911 Delhi Durbar.","Previously, the capital was Calcutta."],"explanationHi":"भारत के बेहतर प्रशासन के लिए राजधानी को केंद्र में (दिल्ली) स्थानांतरित किया गया।","explanationEn":"The capital was moved to the center (Delhi) for better administration of India.","memoryTip":"कलकत्ता से दिल्ली ''एक-एक'' (11) कदम करके गए (1911)।","memoryTipEn":"1911 -> Capital shifts from East to Center.","related":["Lord Hardinge","Delhi Durbar","Calcutta"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('y3mHwuXEEYINBGxU7Du1c', 'General Science', 'सबसे चमकीला ग्रह कौनसा है?', 'Which is the brightest planet?', 'शुक्र (Venus)', 'Venus', 91, 0, '{"facts":["इसे भोर का तारा (Morning Star) और सांझ का तारा (Evening Star) भी कहा जाता है।","यह सौरमंडल का सबसे गर्म ग्रह भी है।"],"factsEn":["Also called Morning Star and Evening Star.","It is also the hottest planet in the solar system."],"explanationHi":"शुक्र के वायुमंडल में सल्फ्यूरिक एसिड के घने बादल हैं, जो सूरज की रोशनी को अत्यधिक प्रतिबिंबित करते हैं।","explanationEn":"Venus has thick clouds of sulfuric acid that heavily reflect sunlight.","memoryTip":"शुक्र (Shukra) मतलब सुंदरता, और सुंदर चीज़ चमकती है।","memoryTipEn":"Venus = Roman Goddess of Beauty = Brightest.","related":["Hottest Planet","Morning Star","Earth''s Twin"]}', 'published', 1776083255, 1776083255);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MfmtVh46VqsW0uKSoLqoC', 'General Knowledge', 'किस सुल्तान ने अपनी राजधानी दिल्ली से दौलताबाद स्थानान्तरित की थी?', 'Which Sultan transferred his capital from Delhi to Daulatabad?', 'मुहम्मद बिन तुगलक', 'Muhammad bin Tughluq', 92, 0, '{"facts":["दौलताबाद का पुराना नाम देवगिरि था।","राजधानी परिवर्तन का यह निर्णय एक बड़ी विफलता साबित हुआ।"],"factsEn":["The old name of Daulatabad was Devagiri.","This decision to shift the capital proved to be a massive failure."],"explanationHi":"उसने साम्राज्य के केंद्र में शासन करने के लिए राजधानी को दक्षिण (देवगिरि) में स्थानांतरित किया, लेकिन रसद और विद्रोह के कारण इसे वापस दिल्ली लाना पड़ा।","explanationEn":"He moved the capital to the south (Devagiri) to rule centrally, but logistics and rebellions forced a return to Delhi.","memoryTip":"तुगलक के ''तुगलकी फरमान'' में राजधानी बदलना सबसे प्रसिद्ध है।","memoryTipEn":"Tughluq''s tragic transfer to Daulatabad.","related":["Tughlaq Dynasty","Devagiri","Token Currency"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('htTTTVgGhNDZqdM0O4a1a', 'General Knowledge', 'प्रथम पंचवर्षीय योजना कब प्रारंभ हुई?', 'When did the first Five-Year Plan start?', '1951 में', 'In 1951', 94, 0, '{"facts":["यह योजना हैरोड-डोमर मॉडल (Harrod-Domar model) पर आधारित थी।","इसका मुख्य ध्यान कृषि क्षेत्र के विकास पर था।"],"factsEn":["The plan was based on the Harrod-Domar model.","Its primary focus was on the development of the agricultural sector."],"explanationHi":"भारत की अर्थव्यवस्था को मजबूत करने के लिए 1951 से 1956 तक पहली योजना लागू की गई थी।","explanationEn":"The first plan was implemented from 1951 to 1956 to strengthen India''s economy.","memoryTip":"देश आज़ाद होने के कुछ साल बाद ''51'' में पहली योजना आई।","memoryTipEn":"1951 = 1st Plan for 5 Years.","related":["Planning Commission","Harrod-Domar Model","Agriculture"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ce5o06C2jR_sKFFxpQyCm', 'General Knowledge', 'चीनी यात्री ह्वेनसांग ने किस विश्वविद्यालय में अध्ययन किया?', 'In which university did the Chinese traveler Hiuen Tsang study?', 'नालन्दा', 'Nalanda', 95, 0, '{"facts":["ह्वेनसांग हर्षवर्धन के शासनकाल के दौरान भारत आया था।","नालंदा विश्वविद्यालय प्राचीन बिहार में स्थित था।"],"factsEn":["Hiuen Tsang visited India during the reign of Harshavardhana.","Nalanda University was located in ancient Bihar."],"explanationHi":"ह्वेनसांग ने नालंदा में बौद्ध दर्शन और योगशास्त्र का गहन अध्ययन किया था।","explanationEn":"Hiuen Tsang extensively studied Buddhist philosophy and Yogashastra at Nalanda.","memoryTip":"ह्वेनसांग (H) और हर्षवर्धन (H), और उसने नालंदा में पढ़ाई की।","memoryTipEn":"Hiuen Tsang at Nalanda under Harsha.","related":["Harshavardhana","Fa-Hien","Kumaragupta"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('t1BwBXexiZlMDXIy9g9EY', 'General Science', 'कौनसा रक्त समूह सर्वदाता कहलाता है?', 'Which blood group is called the universal donor?', 'O (ओ)', 'O (specifically O negative)', 98, 0, '{"facts":["O नेगेटिव (O-) रक्त को किसी भी अन्य रक्त समूह वाले व्यक्ति को दिया जा सकता है।","AB पॉजिटिव (AB+) को सर्वग्राही (Universal Recipient) कहा जाता है।"],"factsEn":["O negative (O-) blood can be given to a person with any other blood group.","AB positive (AB+) is known as the Universal Recipient."],"explanationHi":"O रक्त समूह में A और B दोनों एंटीजन नहीं होते हैं, इसलिए इसे किसी के भी शरीर में सुरक्षित रूप से चढ़ाया जा सकता है।","explanationEn":"Group O red blood cells lack both A and B antigens, making them safe for transfusion into any recipient.","memoryTip":"O मतलब ''Open to all'' (सबके लिए खुला)।","memoryTipEn":"O is for Open to give to all.","related":["Universal Recipient (AB)","Blood Antigens","Karl Landsteiner"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('sWA_ERUT18ivtg8nCl8U_', 'General Science', 'मनुष्य के शरीर में कितनी हड्डियाँ होती है?', 'How many bones are there in the human body?', '206', '206', 90, 0, '{"facts":["नवजात शिशु के शरीर में लगभग 300 हड्डियाँ होती हैं, जो बाद में जुड़कर 206 रह जाती हैं।","सबसे बड़ी हड्डी फीमर (जांघ में) और सबसे छोटी स्टेपीज़ (कान में) होती है।"],"factsEn":["A newborn baby has around 300 bones, which fuse together to form 206.","The longest bone is Femur (thigh) and the shortest is Stapes (ear)."],"explanationHi":"व्यस्क मानव कंकाल मुख्य रूप से 206 हड्डियों से मिलकर शरीर को आकार और सहारा प्रदान करता है।","explanationEn":"The adult human skeleton primarily consists of 206 bones that provide structure and support to the body.","memoryTip":"वयस्क में 206, बच्चे में 300।","memoryTipEn":"206 bones to fix.","related":["Femur","Stapes","Skeleton System"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('E6dosUAJ-TM3IOZfvYCzA', 'General Science', 'सूर्य के प्रकाश से कौनसा विटामिन प्राप्त होता है?', 'Which vitamin is obtained from sunlight?', 'विटामिन D', 'Vitamin D', 96, 0, '{"facts":["विटामिन D को ''सनशाइन विटामिन'' भी कहा जाता है।","यह कैल्शियम के अवशोषण और हड्डियों को मजबूत बनाने में मदद करता है।"],"factsEn":["Vitamin D is also known as the ''Sunshine Vitamin''.","It helps in calcium absorption and strengthening bones."],"explanationHi":"जब हमारी त्वचा सूरज की यूवी (UV) किरणों के संपर्क में आती है, तो शरीर प्राकृतिक रूप से विटामिन डी का संश्लेषण करता है।","explanationEn":"When our skin is exposed to the sun''s UV rays, the body naturally synthesizes Vitamin D.","memoryTip":"धूप (Sun) = D से Dhoop, D से Vitamin D।","memoryTipEn":"D for Day (Sunlight).","related":["Rickets","Calcium","Calciferol"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YynQ3ByTedz8G__JrpwAX', 'General Science', 'मादा एनाफ्लीज मच्छर के काटने से कौनसा रोग होता है?', 'Which disease is caused by the bite of a female Anopheles mosquito?', 'मलेरिया', 'Malaria', 95, 0, '{"facts":["मलेरिया ''प्लाज्मोडियम'' नामक परजीवी (Parasite) के कारण होता है।","इसकी दवा कुनैन (Quinine), सिनकोना पेड़ की छाल से प्राप्त होती है।"],"factsEn":["Malaria is caused by a parasite named ''Plasmodium''.","Its medicine Quinine is obtained from the bark of the Cinchona tree."],"explanationHi":"मादा एनाफ्लीज मच्छर प्लाज्मोडियम परजीवी को संक्रमित इंसान से स्वस्थ इंसान के खून में फैलाती है।","explanationEn":"The female Anopheles mosquito transmits the Plasmodium parasite from an infected person to a healthy person.","memoryTip":"''मादा'' एनाफ्लीज से ''मलेरिया'' (M से M)।","memoryTipEn":"Mad Anopheles causes Malaria.","related":["Plasmodium","Dengue (Aedes)","Quinine"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KlFn8K3rGDJiu8ot8YLoF', 'General Science', 'टेलीफोन का आविष्कार किसने किया था?', 'Who invented the telephone?', 'अलेक्जेंडर ग्राहम बेल', 'Alexander Graham Bell', 88, 0, '{"facts":["उन्होंने 1876 में टेलीफोन का पेटेंट कराया था।","उन्होंने अपनी मशीन पर पहली बार कहा था, ''मिस्टर वॉटसन, यहां आइए, मुझे आपकी जरूरत है।''"],"factsEn":["He patented the telephone in 1876.","His first words on the machine were, ''Mr. Watson, come here, I want to see you.''"],"explanationHi":"बेल ने ध्वनि को विद्युत संकेतों में बदलकर तार के माध्यम से भेजने का तरीका खोजा था।","explanationEn":"Bell discovered a way to convert sound into electrical signals and transmit them over wires.","memoryTip":"फोन की ''बेल'' (Bell) बजती है, तो अलेक्जेंडर ग्राहम बेल याद आते हैं।","memoryTipEn":"Telephone rings a ''Bell''.","related":["Thomas Edison","Communication","Inventions"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wvOppqDVjxVZl2lr2N8Dq', 'General Science', 'प्रकाश की गति कितनी होती है?', 'What is the speed of light?', '3,00,000 कि.मी./सेकंड', '300,000 km/second', 92, 0, '{"facts":["निर्वात (Vacuum) में यह गति सबसे अधिक होती है।","सूर्य का प्रकाश पृथ्वी तक पहुँचने में लगभग 8 मिनट 20 सेकंड (500 सेकंड) का समय लेता है।"],"factsEn":["This speed is maximum in a vacuum.","Sunlight takes about 8 minutes 20 seconds (500 seconds) to reach Earth."],"explanationHi":"ब्रह्मांड में प्रकाश की गति सबसे तेज़ ज्ञात गति है (लगभग 3 × 10^8 मीटर प्रति सेकंड)।","explanationEn":"The speed of light is the fastest known speed in the universe (approx 3 × 10^8 m/s).","memoryTip":"तीन लाख किलोमीटर एक सेकंड में! छूमंतर!","memoryTipEn":"3 with 5 zeros km per second.","related":["Light Year","Vacuum","Sound Speed"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DFELlDEGIXDJETOrGi8n6', 'General Science', 'पृथ्वी सूर्य का चक्कर लगाती है यह सबसे पहले किसने बताया?', 'Who first stated that the Earth revolves around the Sun?', 'कोपरनिकस', 'Copernicus', 91, 0, '{"facts":["निकोलाउस कोपरनिकस ने हेलियोसेंट्रिक (Heliocentric) मॉडल का प्रस्ताव दिया था।","इससे पहले लोग मानते थे कि पृथ्वी ब्रह्मांड के केंद्र में है (Geocentric model)।"],"factsEn":["Nicolaus Copernicus proposed the Heliocentric model.","Earlier, people believed the Earth was at the center of the universe (Geocentric model)."],"explanationHi":"कोपरनिकस ने यह सिद्ध किया कि ब्रह्मांड का केंद्र पृथ्वी नहीं बल्कि सूर्य है।","explanationEn":"Copernicus proved that the Sun, not the Earth, is the center of the solar system.","memoryTip":"''कॉपर'' (Copernicus) ने पृथ्वी की पुरानी मान्यता को बदल दिया।","memoryTipEn":"Copernicus centered the Sun.","related":["Heliocentrism","Galileo","Kepler"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZlgkW9aUU5pKTIv0_owl3', 'General Science', 'प्रकाश वर्ष (Light Year) का सम्बन्ध किससे है?', 'What is ''Light Year'' related to?', 'खगोलीय दूरी', 'Astronomical Distance', 93, 0, '{"facts":["प्रकाश वर्ष समय की नहीं, बल्कि ''दूरी'' (Distance) की इकाई है।","एक प्रकाश वर्ष वह दूरी है जो प्रकाश एक वर्ष में निर्वात में तय करता है (लगभग 9.46 ट्रिलियन किमी)।"],"factsEn":["Light Year is a unit of ''distance'', not time.","It is the distance light travels in a vacuum in one year (approx 9.46 trillion km)."],"explanationHi":"ब्रह्मांड में तारों और आकाशगंगाओं के बीच की विशाल दूरियों को मापने के लिए इसका उपयोग किया जाता है।","explanationEn":"It is used to measure the vast distances between stars and galaxies in the universe.","memoryTip":"वर्ष (Year) सुनकर ''समय'' मत सोचना, प्रकाश वर्ष ''दूरी'' है।","memoryTipEn":"Light Year measures how far, not how long.","related":["Parsec","Astronomical Unit","Speed of Light"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('hErcLPfwW4UXiGr16jpCN', 'General Knowledge', 'स्वर्ण मंदिर कहाँ स्थित है?', 'Where is the Golden Temple located?', 'अमृतसर', 'Amritsar', 94, 0, '{"facts":["इसे श्री हरमंदिर साहिब (Sri Harmandir Sahib) के नाम से भी जाना जाता है।","इसके निर्माण के लिए भूमि मुगल सम्राट अकबर द्वारा दान की गई थी।"],"factsEn":["It is also known as Sri Harmandir Sahib.","The land for its construction was donated by Mughal Emperor Akbar."],"explanationHi":"यह सिखों का सबसे पवित्र धार्मिक स्थल है, जो एक अमृत सरोवर (पवित्र तालाब) के बीच में स्थित है।","explanationEn":"It is the holiest religious site of Sikhism, situated in the middle of an Amrit Sarovar (holy pool).","memoryTip":"''अमृत'' के सरोवर में ''स्वर्ण'' मंदिर है।","memoryTipEn":"Golden Temple shines in Amritsar.","related":["Guru Ram Das","Sikhism","Punjab"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Xl9rcVoK_o0w1t9Eae4iu', 'General Knowledge', 'चारमीनार कहाँ स्थित है?', 'Where is the Charminar located?', 'हैदराबाद', 'Hyderabad', 91, 0, '{"facts":["इसे 1591 में मुहम्मद कुली कुतुब शाह ने बनवाया था।","यह प्लेग (Plague) महामारी के अंत की याद में बनाया गया था।"],"factsEn":["Built in 1591 by Muhammad Quli Qutb Shah.","It was constructed to commemorate the end of the Plague epidemic."],"explanationHi":"यह हैदराबाद शहर की पहचान है और मूसी नदी के पूर्वी तट पर स्थित है।","explanationEn":"It is the iconic symbol of Hyderabad, located on the east bank of the Musi river.","memoryTip":"हैदराबाद की शान है ''चार मीनार''।","memoryTipEn":"Four Minarets in Hyderabad.","related":["Qutb Shahi Dynasty","Musi River","Golconda Fort"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('V-UN6ydP8vWSFuF44ALc2', 'General Knowledge', 'कुतुबमीनार कहाँ स्थित है?', 'Where is the Qutub Minar located?', 'दिल्ली', 'Delhi', 89, 0, '{"facts":["इसका निर्माण कुतुबुद्दीन ऐबक ने शुरू करवाया और इल्तुतमिश ने पूरा किया।","यह ईंटों से बनी दुनिया की सबसे ऊंची मीनार (73 मीटर) है।"],"factsEn":["Construction was started by Qutb-ud-din Aibak and completed by Iltutmish.","It is the tallest brick minaret in the world (73 meters)."],"explanationHi":"यह यूनेस्को (UNESCO) का एक विश्व धरोहर स्थल है, जो महरौली (दिल्ली) में स्थित है।","explanationEn":"It is a UNESCO World Heritage site located in Mehrauli, Delhi.","memoryTip":"दिल्ली में ''कुतुब'' की मीनार गगन चूमती है।","memoryTipEn":"Qutub Minar dominates Delhi''s history.","related":["Qutb-ud-din Aibak","Iltutmish","Slave Dynasty"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wsq7bXCZNH6-oAHSoML-N', 'General Knowledge', 'गेटवे ऑफ इंडिया कहाँ स्थित है?', 'Where is the Gateway of India located?', 'मुंबई', 'Mumbai', 90, 0, '{"facts":["इसे 1911 में किंग जॉर्ज पंचम और क्वीन मैरी की भारत यात्रा की याद में बनाया गया था।","यह इंडो-सारासेनिक शैली (Indo-Saracenic style) में बना है।"],"factsEn":["Built to commemorate the visit of King George V and Queen Mary to India in 1911.","It is built in the Indo-Saracenic style."],"explanationHi":"यह मुंबई हार्बर के तट पर स्थित है और अंग्रेजों के समय में इसे भारत का ''प्रवेश द्वार'' कहा जाता था।","explanationEn":"Located on the waterfront at Mumbai Harbour, it was considered the entry point to India during British rule.","memoryTip":"समुद्र के रास्ते भारत का ''गेटवे'' मुंबई में है।","memoryTipEn":"Gateway of India faces the Arabian Sea in Mumbai.","related":["George V","Taj Mahal Palace Hotel","Elephanta Caves"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WB1r0Sx4FMDz73NjNW_WC', 'General Knowledge', 'इंडिया गेट कहाँ स्थित है?', 'Where is India Gate located?', 'नई दिल्ली', 'New Delhi', 90, 0, '{"facts":["यह एक युद्ध स्मारक (War Memorial) है।","इसे प्रथम विश्व युद्ध और अफगान युद्ध में शहीद हुए भारतीय सैनिकों की याद में बनाया गया था।"],"factsEn":["It is a War Memorial.","Built in memory of the Indian soldiers who died in WWI and the Afghan Wars."],"explanationHi":"इसके वास्तुकार एडविन लुटियंस थे। यहाँ अमर जवान ज्योति भी स्थित है।","explanationEn":"Designed by Edwin Lutyens, it also houses the Amar Jawan Jyoti.","memoryTip":"राजधानी (दिल्ली) में ''इंडिया गेट'' जवानों को सलाम करता है।","memoryTipEn":"India Gate honors soldiers in New Delhi.","related":["Amar Jawan Jyoti","Edwin Lutyens","Rajpath (Kartavya Path)"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kraIhqpXFcsZIViQ-nNjt', 'General Knowledge', 'ताज महल कहाँ स्थित है?', 'Where is the Taj Mahal located?', 'आगरा', 'Agra', 88, 0, '{"facts":["यह यमुना नदी के दक्षिणी तट पर स्थित है।","मुगल सम्राट शाहजहाँ ने इसे अपनी पत्नी मुमताज महल की याद में बनवाया था।"],"factsEn":["Located on the south bank of the Yamuna River.","Built by Mughal Emperor Shah Jahan in memory of his wife Mumtaz Mahal."],"explanationHi":"यह सफेद संगमरमर से बना है और दुनिया के सात अजूबों (Seven Wonders) में से एक है।","explanationEn":"Made of white marble, it is one of the Seven Wonders of the World.","memoryTip":"आगरा का ''ताज'' दुनिया में मशहूर है।","memoryTipEn":"Taj shines in Agra.","related":["Shah Jahan","Mumtaz Mahal","Yamuna River"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ha1MGMtgx-E1YSvSf_fzy', 'General Knowledge', '''आजाद हिन्द फौज'' की स्थापना कहाँ की गई?', 'Where was the ''Azad Hind Fauj'' (Indian National Army) founded?', 'सिंगापुर', 'Singapore', 95, 0, '{"facts":["इसे मूल रूप से कैप्टन मोहन सिंह ने 1942 में स्थापित किया था।","बाद में 1943 में सुभाष चंद्र बोस ने इसका पुनर्गठन किया।"],"factsEn":["Originally formed by Captain Mohan Singh in 1942.","Later reorganized by Subhas Chandra Bose in 1943."],"explanationHi":"द्वितीय विश्व युद्ध के दौरान भारत को अंग्रेजों से मुक्त कराने के लिए इसका गठन जापान की सहायता से किया गया था।","explanationEn":"Formed with Japanese support during WWII to free India from British rule.","memoryTip":"बोस ने ''सिंगापुर'' से भारत की आज़ादी की सेना खड़ी की।","memoryTipEn":"INA formed in Singapore.","related":["Subhas Chandra Bose","Captain Mohan Singh","Rash Behari Bose"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xkGgiBpvZWQd9Jv4kjuCs', 'General Knowledge', 'शिक्षक दिवस कब मनाया जाता है?', 'When is Teacher''s Day celebrated?', '5 सितम्बर', '5 September', 91, 0, '{"facts":["यह भारत के दूसरे राष्ट्रपति डॉ. सर्वपल्ली राधाकृष्णन के जन्मदिन पर मनाया जाता है।","विश्व शिक्षक दिवस 5 अक्टूबर को मनाया जाता है।"],"factsEn":["Celebrated on the birthday of India''s 2nd President, Dr. Sarvepalli Radhakrishnan.","World Teachers'' Day is celebrated on October 5."],"explanationHi":"डॉ. राधाकृष्णन एक महान दार्शनिक और शिक्षक थे, इसलिए उनके सम्मान में यह दिन शिक्षकों को समर्पित है।","explanationEn":"Dr. Radhakrishnan was a great philosopher and teacher, hence this day is dedicated to teachers in his honor.","memoryTip":"5 सितंबर को शिक्षक हमें ज्ञान देते हैं।","memoryTipEn":"September 5 for Teachers.","related":["Dr. S. Radhakrishnan","World Teachers'' Day"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('f4gBVn6kwjbM--GrTykpk', 'General Knowledge', 'राष्ट्रीय खेल दिवस कब मनाया जाता है?', 'When is the National Sports Day celebrated?', '29 अगस्त', '29 August', 93, 0, '{"facts":["इस दिन भारत के राष्ट्रपति खिलाड़ियों को राष्ट्रीय खेल पुरस्कार (जैसे अर्जुन पुरस्कार) प्रदान करते हैं।","यह मेजर ध्यानचंद की जयंती है।"],"factsEn":["On this day, the President gives National Sports Awards (like Arjuna Award) to athletes.","It is the birth anniversary of Major Dhyan Chand."],"explanationHi":"खेलों के प्रति जागरूकता बढ़ाने के लिए यह दिवस राष्ट्रीय स्तर पर मनाया जाता है।","explanationEn":"Celebrated nationally to spread awareness about sports and physical activities.","memoryTip":"अगस्त (29) में खेलों का महाकुंभ।","memoryTipEn":"29 August -> Sports Day.","related":["Major Dhyan Chand","Arjuna Award","Khel Ratna"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jt8c8iJ8clDFCS8EfthIP', 'General Knowledge', 'किसके जन्म दिवस को खेल दिवस के रूप में मनाया जाता है?', 'Whose birthday is celebrated as National Sports Day?', 'मेजर ध्यानचंद', 'Major Dhyan Chand', 94, 0, '{"facts":["उन्हें ''हॉकी का जादूगर'' (The Wizard of Hockey) कहा जाता था।","उन्होंने 1928, 1932 और 1936 के ओलंपिक में भारत को स्वर्ण पदक दिलाया था।"],"factsEn":["He was known as ''The Wizard of Hockey''.","Led India to Olympic gold in 1928, 1932, and 1936."],"explanationHi":"भारत के सर्वोच्च खेल सम्मान (राजीव गांधी खेल रत्न) का नाम बदलकर अब ''मेजर ध्यानचंद खेल रत्न'' कर दिया गया है।","explanationEn":"India''s highest sporting honor has been renamed to ''Major Dhyan Chand Khel Ratna''.","memoryTip":"ध्यानचंद की हॉकी का ''जादू'' खेल दिवस पर याद किया जाता है।","memoryTipEn":"Dhyan Chand is the father of Indian Sports Day.","related":["Hockey Wizard","Major Dhyan Chand Khel Ratna"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Y3BaTKv1imA9mDw7gLzoG', 'General Knowledge', 'विश्व पर्यावरण दिवस कब मनाया जाता है?', 'When is World Environment Day celebrated?', '5 जून', '5 June', 95, 0, '{"facts":["यह संयुक्त राष्ट्र (UN) द्वारा पर्यावरण की रक्षा के लिए जागरूकता बढ़ाने का प्रमुख साधन है।","पहला पर्यावरण दिवस 1973 में मनाया गया था।"],"factsEn":["It is the UN''s principal vehicle for encouraging awareness to protect the environment.","The first WED was held in 1973."],"explanationHi":"हर साल प्रकृति को बचाने के लिए एक नई थीम के साथ यह वैश्विक स्तर पर मनाया जाता है।","explanationEn":"Celebrated globally every year with a new theme to encourage action to protect nature.","memoryTip":"5 जून को ''जुनून'' से पर्यावरण बचाओ।","memoryTipEn":"June 5th is Earth''s day out.","related":["UNEP","Stockholm Conference 1972"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KfGfR3zTRsrSd3vBy78Xy', 'General Knowledge', '"करो या मरो" का नारा किसने दिया?', 'Who gave the slogan "Do or Die"?', 'महात्मा गाँधी', 'Mahatma Gandhi', 96, 0, '{"facts":["यह नारा 1942 के ''भारत छोड़ो आंदोलन'' (Quit India Movement) के दौरान दिया गया था।","गांधीजी ने यह उद्घोष बॉम्बे के गोवालिया टैंक मैदान (अगस्त क्रांति मैदान) से किया था।"],"factsEn":["Given during the ''Quit India Movement'' in 1942.","Gandhi made this call from the Gowalia Tank Maidan (August Kranti Maidan) in Bombay."],"explanationHi":"इस नारे का अर्थ था कि या तो हम भारत को आज़ाद कराएंगे या इस प्रयास में अपनी जान दे देंगे।","explanationEn":"The slogan meant that Indians shall either free India or die in the attempt.","memoryTip":"आज़ादी के लिए गांधी जी ने ''करो या मरो'' का आह्वान किया।","memoryTipEn":"Do or Die for freedom in ''42.","related":["Quit India Movement","August Kranti Maidan","1942"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CtFBEkWWnP0Lb28Ql4v0c', 'General Knowledge', '"दिल्ली चलो" का नारा किसने दिया?', 'Who gave the slogan ''Dilli Chalo'' (March to Delhi)?', 'नेताजी सुभाषचंद्र बोस', 'Netaji Subhas Chandra Bose', 94, 0, '{"facts":["1943 में सिंगापुर से आज़ाद हिंद फ़ौज (INA) के सैनिकों को संबोधित करते हुए यह नारा दिया गया था।","इसका उद्देश्य दिल्ली पहुँचकर लाल किले पर तिरंगा फहराना था।"],"factsEn":["Given in 1943 while addressing INA soldiers from Singapore.","The goal was to reach Delhi and hoist the tricolor at the Red Fort."],"explanationHi":"नेताजी ने ब्रिटिश साम्राज्य को उखाड़ फेंकने के लिए सेना को दिल्ली कूच करने का आह्वान किया था।","explanationEn":"Netaji called upon the army to march to Delhi to overthrow the British Empire.","memoryTip":"नेताजी की आज़ाद फौज का लक्ष्य ''दिल्ली चलो'' था।","memoryTipEn":"Bose led the march to Delhi.","related":["Azad Hind Fauj","Singapore 1943","Red Fort Trials"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6gKS42abIzmTejkanrpFS', 'General Knowledge', '"वेदों की ओर लौटो" का नारा किसने दिया?', 'Who gave the slogan ''Go back to Vedas''?', 'दयानंद सरस्वती', 'Dayanand Saraswati', 90, 0, '{"facts":["स्वामी दयानंद ने आर्य समाज की स्थापना (1875) की थी।","उनका मानना था कि वेद त्रुटिहीन हैं और सच्चे ज्ञान के स्रोत हैं।"],"factsEn":["Swami Dayanand founded the Arya Samaj (1875).","He believed Vedas are infallible and the source of true knowledge."],"explanationHi":"हिंदू धर्म में आई कुरीतियों (जैसे मूर्तिपूजा और जाति प्रथा) का विरोध करते हुए उन्होंने वैदिक काल की शुद्धता अपनाने पर जोर दिया।","explanationEn":"Opposing social evils like idol worship and the caste system, he emphasized returning to the purity of the Vedic period.","memoryTip":"ज्ञान की ''सरस्वती'' वेदों में बसती है।","memoryTipEn":"Saraswati = Back to Vedas.","related":["Arya Samaj","Satyarth Prakash"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-IZ21JEdnrBpY90nUcqS1', 'General Knowledge', '"इंकलाब ज़िन्दाबाद" का नारा किसने दिया?', 'Who gave the slogan ''Inquilab Zindabad''?', 'भगतसिंह', 'Bhagat Singh', 95, 0, '{"facts":["मूल रूप से 1921 में उर्दू कवि हसरत मोहानी ने इसे गढ़ा था।","1929 में सेंट्रल असेंबली में बम फेंकने के बाद भगत सिंह और बटुकेश्वर दत्त ने इसे जोर से पुकारा था।"],"factsEn":["Originally coined by Urdu poet Hasrat Mohani in 1921.","Shouted by Bhagat Singh and Batukeshwar Dutt after bombing the Central Assembly in 1929."],"explanationHi":"इस नारे का अर्थ ''क्रांति अमर रहे'' है, जो स्वतंत्रता संग्राम का पर्याय बन गया।","explanationEn":"Meaning ''Long live the revolution'', this slogan became synonymous with the freedom struggle.","memoryTip":"भगत सिंह की ''इंकलाब'' की आवाज़ आज भी गूंजती है।","memoryTipEn":"Bhagat Singh shouted for Revolution.","related":["Hasrat Mohani","Central Assembly Bombing","Batukeshwar Dutt"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TpsEtAHt1jCo_aj1A-OA-', 'General Knowledge', '"तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा" का नारा किसने दिया?', 'Who gave the slogan ''Give me blood, and I shall give you freedom''?', 'नेताजी सुभाषचंद्र बोस', 'Netaji Subhas Chandra Bose', 96, 0, '{"facts":["यह 1944 में बर्मा (म्यांमार) में भारतीय राष्ट्रीय सेना (INA) के सैनिकों को संबोधित करते हुए कहा गया था।","यह युवाओं से मातृभूमि के लिए सर्वोच्च बलिदान देने का आह्वान था।"],"factsEn":["Delivered in 1944 while addressing INA soldiers in Burma (Myanmar).","It was a call to the youth to make the supreme sacrifice for the motherland."],"explanationHi":"नेताजी का मानना था कि स्वतंत्रता भीख मांगकर नहीं, बल्कि संघर्ष और बलिदान से मिलती है।","explanationEn":"Netaji believed that freedom is not begged for, but achieved through struggle and sacrifice.","memoryTip":"खून के बदले आज़ादी का सौदा ''बोस'' ने किया।","memoryTipEn":"Bose asked for blood to buy freedom.","related":["Azad Hind Fauj","Burma Campaign","Indian Freedom Struggle"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ngptfixsVEcwE6AMHhVoZ', 'General Knowledge', '"आराम हराम है" का नारा किसने दिया?', 'Who gave the slogan ''Aaram Haram Hai'' (Rest is rust/forbidden)?', 'जवाहरलाल नेहरु', 'Jawaharlal Nehru', 88, 0, '{"facts":["स्वतंत्रता प्राप्ति के बाद देश के निर्माण के लिए कड़ी मेहनत करने का आह्वान था।","पंडित नेहरू भारत के पहले प्रधानमंत्री थे।"],"factsEn":["It was a call to work hard for nation-building after achieving independence.","Pandit Nehru was the first Prime Minister of India."],"explanationHi":"नेहरू जी का मानना था कि एक नए राष्ट्र के निर्माण के लिए देशवासियों को निरंतर कर्मशील रहना होगा।","explanationEn":"Nehru believed that building a new nation required continuous hard work from its citizens without resting.","memoryTip":"नेहरू जी ने ''आराम'' छोड़कर देश बनाया।","memoryTipEn":"Nehru said no rest until the nation is built.","related":["Nation Building","First Prime Minister"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_IZVZ4W2UkjVZFhTf9WkD', 'General Knowledge', '"जय जवान जय किसान" का नारा किसने दिया?', 'Who gave the slogan ''Jai Jawan, Jai Kisan''?', 'लालबहादुर शास्त्री', 'Lal Bahadur Shastri', 95, 0, '{"facts":["यह नारा 1965 के भारत-पाकिस्तान युद्ध के समय दिया गया था।","इस समय देश युद्ध और अन्न संकट दोनों का सामना कर रहा था।"],"factsEn":["The slogan was given during the 1965 Indo-Pak war.","At that time, the country was facing both war and a food crisis."],"explanationHi":"यह सीमा पर लड़ने वाले सैनिकों और खेतों में काम करने वाले किसानों का मनोबल बढ़ाने के लिए था।","explanationEn":"It aimed to boost the morale of soldiers fighting at borders and farmers working in fields.","memoryTip":"शास्त्री जी ने जवान और किसान की जयकार की।","memoryTipEn":"Shastri hailed the soldier and the farmer.","related":["1965 War","Green Revolution","Jai Vigyan (Atal Bihari Vajpayee)"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('pM523dwQBU1bilkigAtJv', 'General Knowledge', '"मारो फिरंगी को" का नारा किसने दिया?', 'Who gave the slogan ''Maro Firangi Ko''?', 'मंगल पांडे', 'Mangal Pandey', 92, 0, '{"facts":["यह नारा 1857 के सिपाही विद्रोह की शुरुआत का प्रतीक है।","''फिरंगी'' शब्द का प्रयोग ब्रिटिश अधिकारियों के लिए किया गया था।"],"factsEn":["This slogan marks the beginning of the Sepoy Mutiny of 1857.","The term ''Firangi'' was used for British officials."],"explanationHi":"बैरकपुर छावनी में चर्बी वाले कारतूसों के विरोध में मंगल पांडे ने यह नारा दिया था।","explanationEn":"Mangal Pandey raised this slogan in the Barrackpore cantonment against the use of greased cartridges.","memoryTip":"1857 का ''मंगल'' फिरंगियों को मार कर शुरू हुआ।","memoryTipEn":"Mangal Pandey sparked the mutiny against Firangis.","related":["Revolt of 1857","Barrackpore Mutiny","Greased Cartridges"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('M_WfeuHu6OwvhLtaeaR1c', 'General Knowledge', '"सरफरोशी की तमन्ना, अब हमारे दिल में है..." का नारा किसने दिया?', 'Who gave the slogan ''Sarfaroshi ki Tamanna, ab hamare dil mein hai...''?', 'रामप्रसाद बिस्मिल', 'Ramprasad Bismil', 93, 0, '{"facts":["मूल रूप से यह गजल ''बिस्मिल अजीमाबादी'' द्वारा 1921 में लिखी गई थी।","स्वतंत्रता सेनानी रामप्रसाद बिस्मिल ने इसे काकोरी कांड (1925) और स्वतंत्रता आंदोलन के दौरान अमर कर दिया।"],"factsEn":["The ghazal was originally written by ''Bismil Azimabadi'' in 1921.","Freedom fighter Ramprasad Bismil immortalized it during the Kakori train robbery (1925) and freedom movement."],"explanationHi":"यह गीत ब्रिटिश शासन के खिलाफ देश के युवाओं में देशभक्ति की आग जगाने का काम करता था।","explanationEn":"This poem worked to ignite the fire of patriotism among the youth against British rule.","memoryTip":"''बिस्मिल'' (Ramprasad Bismil) ने सरफरोशी की तमन्ना गाई।","memoryTipEn":"Bismil bled with Sarfaroshi.","related":["Kakori Conspiracy","Bismil Azimabadi","HRA"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('exrBQ5Fqo-00M_DLQ-hpJ', 'General Knowledge', 'भारत का नेपोलियन किसे कहा जाता है?', 'Who is known as the Napoleon of India?', 'समुद्रगुप्त', 'Samudragupta', 95, 0, '{"facts":["यह उपाधि ब्रिटिश इतिहासकार वी.ए. स्मिथ (V.A. Smith) ने दी थी।","समुद्रगुप्त ने अपने जीवन में कभी कोई युद्ध नहीं हारा।"],"factsEn":["This title was given by British historian V.A. Smith.","Samudragupta never lost a battle in his life."],"explanationHi":"गुप्त साम्राज्य के इस महान शासक की सैन्य विजय और साम्राज्य विस्तार की तुलना नेपोलियन बोनापार्ट से की गई।","explanationEn":"His military conquests and expansion of the Gupta Empire were compared to Napoleon Bonaparte.","memoryTip":"''समुद्र'' जितना विशाल साम्राज्य, इसलिए नेपोलियन।","memoryTipEn":"Samudragupta''s sea of victories.","related":["Gupta Empire","V.A. Smith","Allahabad Pillar Inscription"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('L7XN8_ici7iaKDNeCdCeo', 'General Knowledge', 'सती प्रथा के अंत में सबसे अधिक प्रयास किस समाज सुधारक का रहा?', 'Which social reformer made the most effort to end the Sati system?', 'राजा राममोहन राय', 'Raja Ram Mohan Roy', 96, 0, '{"facts":["इनके प्रयासों से 1829 में लॉर्ड विलियम बेंटिक ने सती प्रथा को गैरकानूनी घोषित किया।","इन्हें ''आधुनिक भारत का जनक'' (Father of Modern India) भी कहा जाता है।"],"factsEn":["Due to his efforts, Lord William Bentinck declared Sati illegal in 1829.","He is also known as the ''Father of Modern India''."],"explanationHi":"उन्होंने ब्रह्म समाज की स्थापना की और महिलाओं के अधिकारों, शिक्षा और सामाजिक सुधार के लिए आजीवन संघर्ष किया।","explanationEn":"He founded the Brahmo Samaj and fought his whole life for women''s rights, education, and social reform.","memoryTip":"राममोहन ने ''सती'' को ''राय'' देकर रोका।","memoryTipEn":"Raja Ram stopped the fire of Sati.","related":["Brahmo Samaj","Lord William Bentinck","Abolition of Sati Act 1829"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2a-wRYu6h1sH2Zezb2o1w', 'General Knowledge', '''रामकृष्ण मिशन'' की स्थापना किसने की?', 'Who founded the ''Ramakrishna Mission''?', 'स्वामी विवेकानंद', 'Swami Vivekananda', 92, 0, '{"facts":["स्थापना 1 मई 1897 को हुई थी।","मिशन का मुख्यालय बेलूर मठ, हावड़ा (पश्चिम बंगाल) में है।"],"factsEn":["Founded on May 1, 1897.","The headquarters is located at Belur Math, Howrah (West Bengal)."],"explanationHi":"विवेकानंद ने अपने गुरु रामकृष्ण परमहंस की शिक्षाओं और वेदांत दर्शन के प्रचार के लिए इस मिशन की स्थापना की।","explanationEn":"Vivekananda founded this mission to propagate the teachings of his guru Ramakrishna Paramahamsa and Vedanta philosophy.","memoryTip":"विवेकानंद ने अपने गुरु (रामकृष्ण) का मिशन पूरा किया।","memoryTipEn":"Vivekananda''s mission for his master.","related":["Ramakrishna Paramahamsa","Belur Math","Vedanta"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MLdZB7Ek2RcGbQKbphbqj', 'General Knowledge', 'महात्मा गांधी का जन्म दिवस किस तिथि को मनाया जाता है?', 'On which date is Mahatma Gandhi''s birthday celebrated?', '2 अक्टूबर', '2 October', 90, 0, '{"facts":["इस दिन को ''गांधी जयंती'' के रूप में मनाया जाता है।","संयुक्त राष्ट्र (UN) इस दिन को ''अंतर्राष्ट्रीय अहिंसा दिवस'' के रूप में मनाता है।"],"factsEn":["This day is celebrated as ''Gandhi Jayanti''.","The UN observes this day as the ''International Day of Non-Violence''."],"explanationHi":"गांधीजी का जन्म 2 अक्टूबर 1869 को गुजरात के पोरबंदर में हुआ था।","explanationEn":"Gandhiji was born on October 2, 1869, in Porbandar, Gujarat.","memoryTip":"2 अक्टूबर को ''अहिंसा'' का जन्म हुआ।","memoryTipEn":"October 2 = Peace Day.","related":["International Day of Non-Violence","Porbandar","Lal Bahadur Shastri (Also born Oct 2)"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Z-lDKIMFjWBjmELGYqYAs', 'General Knowledge', 'महात्मा गांधी का पूरा नाम क्या है?', 'What is the full name of Mahatma Gandhi?', 'मोहनदास करमचंद गांधी', 'Mohandas Karamchand Gandhi', 85, 0, '{"facts":["करमचंद उनके पिता का नाम था।","उनकी माता का नाम पुतलीबाई था।"],"factsEn":["Karamchand was his father''s name.","His mother''s name was Putlibai."],"explanationHi":"गुजरात की परंपरा के अनुसार, उनके नाम में उनका अपना नाम और पिता का नाम जुड़ा हुआ है।","explanationEn":"As per Gujarati tradition, his name includes his first name followed by his father''s name.","memoryTip":"''मोहन'' ने ''करम'' करके भारत बचाया।","memoryTipEn":"MK Gandhi = Mohandas Karamchand.","related":["Karamchand Gandhi","Putlibai","Kasturba Gandhi"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('x_trsKoj65Cv1z-SlngTu', 'General Knowledge', 'गांधी जी को महात्मा की उपाधि किसने दी थी?', 'Who gave the title of ''Mahatma'' to Gandhiji?', 'रवीन्द्रनाथ टैगोर', 'Rabindranath Tagore', 94, 0, '{"facts":["यह उपाधि उन्हें 1915 में दी गई थी।","बदले में गांधीजी ने टैगोर को ''गुरुदेव'' की उपाधि दी थी।"],"factsEn":["This title was conferred on him in 1915.","In return, Gandhiji gave Tagore the title of ''Gurudev''."],"explanationHi":"दक्षिण अफ्रीका में गांधीजी के संघर्ष और त्याग से प्रभावित होकर टैगोर ने उन्हें ''महान आत्मा'' (महात्मा) कहा था।","explanationEn":"Impressed by Gandhi''s struggle and sacrifice in South Africa, Tagore called him a ''Great Soul'' (Mahatma).","memoryTip":"टैगोर ने बापू को ''महात्मा'' बनाया।","memoryTipEn":"Tagore termed him Mahatma.","related":["Gurudev","Champaran Satyagraha","Father of the Nation (Subhas Chandra Bose)"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('sJizBG85JUd41wDpj_N_z', 'General Knowledge', '''माई एक्सपेरीमेन्ट्स विद ट्रुथ'' पुस्तक के लेखक कौन थे?', 'Who was the author of the book ''My Experiments with Truth''?', 'महात्मा गांधी', 'Mahatma Gandhi', 93, 0, '{"facts":["यह महात्मा गांधी की आत्मकथा है।","यह मूल रूप से गुजराती भाषा में लिखी गई थी (''सत्य ना प्रयोगो'')।"],"factsEn":["It is the autobiography of Mahatma Gandhi.","It was originally written in the Gujarati language."],"explanationHi":"इस पुस्तक में गांधीजी के बचपन से लेकर 1921 तक के जीवन की घटनाओं का वर्णन है।","explanationEn":"The book covers events in Gandhiji''s life from his childhood up to 1921.","memoryTip":"बापू जीवन भर ''सत्य'' के प्रयोग करते रहे।","memoryTipEn":"Gandhi experimented with truth.","related":["Hind Swaraj","Navjivan","Autobiography"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('T3AgFa0KHlweoA2Rtzk6l', 'General Knowledge', 'भारत का सर्वोच्च नागरिक सम्मान कौनसा है?', 'Which is the highest civilian award in India?', 'भारत रत्न', 'Bharat Ratna', 96, 0, '{"facts":["इसकी शुरुआत 1954 में हुई थी।","पहले प्राप्तकर्ता डॉ. सर्वपल्ली राधाकृष्णन, सी. राजगोपालाचारी और सी.वी. रमन थे।"],"factsEn":["It was instituted in 1954.","The first recipients were Dr. S. Radhakrishnan, C. Rajagopalachari, and C.V. Raman."],"explanationHi":"यह कला, साहित्य, विज्ञान, सार्वजनिक सेवा और खेल जैसे क्षेत्रों में असाधारण सेवा के लिए दिया जाता है।","explanationEn":"It is awarded for exceptional service in fields like art, literature, science, public service, and sports.","memoryTip":"देश का सबसे अनमोल ''रत्न'' = भारत रत्न।","memoryTipEn":"Bharat Ratna = Jewel of India.","related":["Padma Vibhushan","1954 Awards","Khan Abdul Ghaffar Khan (First foreigner)"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vE21h63TxmPNPQgH8AqLW', 'General Knowledge', 'फिल्म के क्षेत्र में दिया जाने वाला सर्वोच्च भारतीय पुरस्कार कौन-सा है?', 'Which is the highest Indian award given in the field of cinema?', 'दादा साहेब फाल्के पुरस्कार', 'Dadasaheb Phalke Award', 92, 0, '{"facts":["इसकी शुरुआत 1969 में हुई थी।","पहली प्राप्तकर्ता अभिनेत्री देविका रानी थीं।"],"factsEn":["It was introduced in 1969.","The first recipient was actress Devika Rani."],"explanationHi":"दादा साहेब फाल्के को ''भारतीय सिनेमा का जनक'' माना जाता है; उन्होंने भारत की पहली फुल-लेंथ फीचर फिल्म ''राजा हरिश्चंद्र'' (1913) बनाई थी।","explanationEn":"Dadasaheb Phalke is considered the ''Father of Indian Cinema''; he made India''s first full-length feature film ''Raja Harishchandra'' (1913).","memoryTip":"सिनेमा के ''दादा'' का पुरस्कार सबसे बड़ा है।","memoryTipEn":"Phalke = Father of Films.","related":["Devika Rani","Raja Harishchandra","National Film Awards"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('o5MIPPeo1A3YWsakc4XQv', 'General Knowledge', 'भारत का सर्वोच्च वीरता पदक का नाम बताएं।', 'Name the highest gallantry award of India.', 'परमवीर चक्र', 'Param Vir Chakra (PVC)', 97, 0, '{"facts":["यह युद्ध के दौरान दुश्मन की उपस्थिति में सर्वोच्च बहादुरी और आत्म-बलिदान के लिए दिया जाता है।","पहले प्राप्तकर्ता मेजर सोमनाथ शर्मा थे।"],"factsEn":["Awarded for the most conspicuous bravery or self-sacrifice in the presence of the enemy during wartime.","The first recipient was Major Somnath Sharma."],"explanationHi":"यह पदक कांस्य का बना होता है और इस पर इंद्र के वज्र का प्रतीक बना होता है।","explanationEn":"The medal is made of bronze and bears the symbol of Indra''s Vajra.","memoryTip":"सबसे ''परम'' वीर को ही यह चक्र मिलता है।","memoryTipEn":"Param means Supreme + Vir means Brave.","related":["Maha Vir Chakra","Ashoka Chakra (Peacetime)","Major Somnath Sharma"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4M1_dMDejFSErNG4kVeAQ', 'General Knowledge', 'भारत का शेक्सपीयर किसे कहा जाता है?', 'Who is called the Shakespeare of India?', 'कालिदास को', 'Kalidasa', 89, 0, '{"facts":["वे गुप्त काल (चंद्रगुप्त द्वितीय/विक्रमादित्य) के दौरान एक महान संस्कृत कवि और नाटककार थे।","''अभिज्ञानशाकुंतलम्'' और ''मेघदूतम्'' उनकी प्रसिद्ध रचनाएँ हैं।"],"factsEn":["He was a great Sanskrit poet and dramatist during the Gupta period.","''Abhijnanashakuntalam'' and ''Meghadutam'' are his famous works."],"explanationHi":"नाटक और साहित्य में उनकी असाधारण रचनाओं के कारण उनकी तुलना विलियम शेक्सपियर से की जाती है।","explanationEn":"His exceptional creations in drama and literature led to his comparison with William Shakespeare.","memoryTip":"शेक्सपीयर और कालिदास दोनों ने महान नाटक लिखे।","memoryTipEn":"Kalidasa: The Bard of India.","related":["Abhijnanashakuntalam","Chandragupta II","Sanskrit Literature"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nCVn7xz9AYu6Go8gPiYYz', 'General Science', 'कम्प्यूटर का पिता किसे कहा जाता है?', 'Who is known as the Father of the Computer?', 'चार्ल्स बेबेज', 'Charles Babbage', 94, 0, '{"facts":["वे एक अंग्रेजी गणितज्ञ और आविष्कारक थे।","उन्होंने ''एनालिटिकल इंजन'' (Analytical Engine) की अवधारणा दी थी, जो पहला सामान्य-उद्देश्य वाला कंप्यूटर था।"],"factsEn":["He was an English mathematician and inventor.","He conceptualized the ''Analytical Engine'', the first general-purpose computer."],"explanationHi":"भले ही उनके समय में तकनीक की कमी के कारण यह बन नहीं पाया, लेकिन उनके डिज़ाइन में आधुनिक कंप्यूटर की सभी बुनियादी विशेषताएँ (ALU, Memory) थीं।","explanationEn":"Although it wasn''t built in his time due to technology constraints, his design had all the basic features of modern computers.","memoryTip":"कंप्यूटर के ''बाबा'' (बेबेज)।","memoryTipEn":"Babbage built the brain.","related":["Analytical Engine","Difference Engine","Ada Lovelace (First Programmer)"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('S4MEXNRpOCgtZbVfKBsve', 'General Knowledge', 'अन्तरिक्ष में जाने वाले प्रथम व्यक्ति कौन थे?', 'Who was the first person to go into space?', 'यूरी गगारिन (रूस)', 'Yuri Gagarin (Russia/USSR)', 95, 0, '{"facts":["उन्होंने 12 अप्रैल 1961 को अंतरिक्ष की यात्रा की।","उनके अंतरिक्ष यान का नाम ''वोस्तोक 1'' (Vostok 1) था।"],"factsEn":["He traveled to space on April 12, 1961.","His spacecraft was named ''Vostok 1''."],"explanationHi":"यूरी गगारिन ने अंतरिक्ष में जाकर पृथ्वी की एक पूरी परिक्रमा की और मानव अंतरिक्ष उड़ान की शुरुआत की।","explanationEn":"Yuri Gagarin completed one orbit of the Earth, marking the beginning of human spaceflight.","memoryTip":"अंतरिक्ष में ''गगन'' (गगारिन) में उड़े यूरी।","memoryTipEn":"Yuri went out in the Vostok.","related":["Vostok 1","Neil Armstrong","Valentina Tereshkova"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yN3uckJJ5jOE46uNstYxV', 'General Knowledge', 'चन्द्रमा पर कदम रखने वाले प्रथम व्यक्ति कौन हैं?', 'Who is the first person to step on the Moon?', 'नील आर्मस्ट्रांग', 'Neil Armstrong', 96, 0, '{"facts":["उन्होंने 20 जुलाई 1969 को अपोलो 11 (Apollo 11) मिशन के तहत चाँद पर कदम रखा था।","बज़ एल्ड्रिन चाँद पर चलने वाले दूसरे व्यक्ति थे।"],"factsEn":["He stepped on the moon on July 20, 1969, during the Apollo 11 mission.","Buzz Aldrin was the second person to walk on the moon."],"explanationHi":"आर्मस्ट्रांग का प्रसिद्ध वाक्य था: ''यह मनुष्य के लिए एक छोटा कदम है, लेकिन मानव जाति के लिए एक बड़ी छलांग है।''","explanationEn":"Armstrong''s famous quote: ''That''s one small step for a man, one giant leap for mankind.''","memoryTip":"चाँद पर नील आर्मस्ट्रांग की भुजाएं (Arms) सबसे ''स्ट्रांग'' थीं।","memoryTipEn":"Armstrong stood strong on the moon.","related":["Apollo 11","Buzz Aldrin","NASA"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NozYUsmaclAUmFti8Axq_', 'General Knowledge', 'अन्तरिक्ष में जाने वाले प्रथम भारतीय कौन हैं?', 'Who is the first Indian to go to space?', 'राकेश शर्मा', 'Rakesh Sharma', 94, 0, '{"facts":["उन्होंने 1984 में सोवियत-भारतीय संयुक्त मिशन (T-11) के तहत अंतरिक्ष यात्रा की।","अंतरिक्ष से उन्होंने भारत को देखकर ''सारे जहां से अच्छा'' कहा था।"],"factsEn":["Traveled in 1984 under the joint Soviet-Indian mission (Soyuz T-11).","Looking at India from space, he said, ''Sare Jahan Se Achha''."],"explanationHi":"वे भारतीय वायुसेना (IAF) के पायलट थे, जो अंतरिक्ष यात्रा करने वाले एकमात्र भारतीय नागरिक हैं (अब तक)।","explanationEn":"An IAF pilot, he remains the only Indian citizen to have traveled in space (as of now).","memoryTip":"अंतरिक्ष में भारत का ''शर्मा'' (गर्व) राकेश ने बढ़ाया।","memoryTipEn":"Rakesh Sharma rocked space.","related":["Soyuz T-11","ISRO","Kalpana Chawla"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qIWfZU-VYn1rTXRQLCmYf', 'General Science', 'प्रथम भारतीय उपग्रह का नाम क्या है और इसे कब छोड़ा गया?', 'What is the name of the first Indian satellite and when was it launched?', 'आर्यभट्ट, सन 1975 में', 'Aryabhata, in 1975', 95, 0, '{"facts":["इसे 19 अप्रैल 1975 को सोवियत संघ के कापुस्टिन यार (Kapustin Yar) से लॉन्च किया गया था।","इसका नाम प्रसिद्ध प्राचीन भारतीय खगोलशास्त्री आर्यभट्ट के नाम पर रखा गया।"],"factsEn":["Launched on April 19, 1975, from Kapustin Yar in the Soviet Union.","Named after the famous ancient Indian astronomer Aryabhata."],"explanationHi":"यह भारत का पहला उपग्रह था और इसे भारतीय अंतरिक्ष अनुसंधान संगठन (ISRO) द्वारा बनाया गया था।","explanationEn":"It was India''s first satellite, built by the Indian Space Research Organisation (ISRO).","memoryTip":"भारत का पहला ''भट्ट'' (रॉकेट) अंतरिक्ष में ''75'' में गया।","memoryTipEn":"Aryabhata initiated Indian space.","related":["ISRO","Bhaskara-I","Soviet Union"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FiZ9HPXwgQioQcjLrIviO', 'General Knowledge', 'संयुक्त राष्ट्र संघ के वर्तमान महासचिव कौन हैं? (पीडीएफ स्रोत अनुसार)', 'Who is the current Secretary-General of the UN? (As per PDF source)', 'बान की मून', 'Ban Ki-moon', 75, 0, '{"facts":["ध्यान दें: यह तथ्य पीडीएफ के समय (2016 से पहले) का है।","वर्तमान (2026) में यूएन के महासचिव ''एंटोनियो गुटेरेस'' (Antonio Guterres) हैं।"],"factsEn":["Note: This fact is from the time of the PDF (pre-2016).","Currently (in 2026), the UN Secretary-General is Antonio Guterres."],"explanationHi":"बान की मून दक्षिण कोरिया से थे और उन्होंने 2007 से 2016 तक संयुक्त राष्ट्र के 8वें महासचिव के रूप में कार्य किया।","explanationEn":"Ban Ki-moon from South Korea served as the 8th Secretary-General of the UN from 2007 to 2016.","memoryTip":"किताब के छपने के समय ''मून'' (Moon) चमक रहा था।","memoryTipEn":"Ban Ki-moon preceded Guterres.","related":["Antonio Guterres","United Nations"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xRq7Zl_UHp0aES17aG_Hi', 'General Knowledge', 'अन्तर्राष्ट्रीय महिला दिवस किस तिथि को मनाया जाता है?', 'On which date is International Women''s Day celebrated?', '8 मार्च', '8 March', 92, 0, '{"facts":["यह दिन महिलाओं के सामाजिक, आर्थिक, और राजनीतिक अधिकारों का जश्न मनाता है।","संयुक्त राष्ट्र (UN) ने 1977 में आधिकारिक तौर पर इस दिन को मान्यता दी थी।"],"factsEn":["This day celebrates the social, economic, and political rights of women.","The UN officially recognized this day in 1977."],"explanationHi":"यह महिलाओं की उपलब्धियों का सम्मान करने और लैंगिक समानता (Gender Equality) के लिए कार्रवाई का आह्वान करने का वैश्विक दिन है।","explanationEn":"A global day honoring women''s achievements and a call to action for gender equality.","memoryTip":"मार्च (March) करती महिलाएँ (8)।","memoryTipEn":"Marching on the 8th.","related":["Gender Equality","UN Women"]}', 'published', 1776083329, 1776083329);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NA7tBBYwtBgdQgSAS2qso', 'General Science', 'घेंघा (Goiter) रोग किसकी कमी से होता है?', 'Goiter disease is caused by the deficiency of which mineral?', 'आयोडीन', 'Iodine', 95, 0, '{"facts":["इस बीमारी में गले की थायरॉयड ग्रंथि (Thyroid Gland) में सूजन आ जाती है।","आयोडीन युक्त नमक इसका सबसे आसान बचाव है।"],"factsEn":["In this disease, the Thyroid Gland in the neck swells up.","Iodized salt is the easiest prevention for it."],"explanationHi":"थायरॉयड ग्रंथि को थायरोक्सिन हार्मोन बनाने के लिए आयोडीन की आवश्यकता होती है; इसकी कमी से ग्रंथि बढ़ जाती है।","explanationEn":"The thyroid gland requires iodine to produce thyroxine hormone; its deficiency causes the gland to enlarge.","memoryTip":"नमक में ''आयोडीन'' गले को घेंघा से बचाता है।","memoryTipEn":"Iodine prevents the neck from getting Ironed (swollen).","related":["Thyroid Gland","Thyroxine","Endocrine System"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2kw0Q4n69h10Ltql4hFDi', 'General Science', 'कौनसी ग्रंथि इन्सुलिन स्रावित करती है?', 'Which gland secretes Insulin?', 'अग्नाशय (Pancreas)', 'Pancreas', 96, 0, '{"facts":["अग्नाशय एक मिश्रित ग्रंथि (अंतःस्रावी और बहिःस्रावी दोनों) है।","इंसुलिन अग्नाशय के ''आइलेट्स ऑफ लैंगरहैंस'' (Islets of Langerhans) की बीटा कोशिकाओं से स्रावित होता है।"],"factsEn":["Pancreas is a mixed gland (both endocrine and exocrine).","Insulin is secreted by the beta cells of the Islets of Langerhans in the pancreas."],"explanationHi":"इंसुलिन रक्त में शर्करा (ग्लूकोज) के स्तर को नियंत्रित करता है; इसकी कमी से मधुमेह (Diabetes) होता है।","explanationEn":"Insulin regulates the sugar (glucose) level in the blood; its deficiency causes Diabetes.","memoryTip":"पैन (Pan) में शुगर (Sugar) कंट्रोल होती है (Pancreas)।","memoryTipEn":"Pancreas packs away the sugar.","related":["Diabetes","Glucagon","Endocrine Glands"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('O1rbgnN-nJ05qEeGu4bGE', 'General Knowledge', 'डूरंड कप का सम्बन्ध किस खेल से है?', 'Durand Cup is associated with which sport?', 'फुटबॉल', 'Football', 90, 0, '{"facts":["यह एशिया का सबसे पुराना फुटबॉल टूर्नामेंट है (1888 में शिमला में शुरू हुआ)।","इसे सर मोर्टिमर डूरंड के नाम पर रखा गया है।"],"factsEn":["It is the oldest football tournament in Asia (started in 1888 in Shimla).","It is named after Sir Mortimer Durand."],"explanationHi":"यह भारतीय सशस्त्र बलों और अन्य आमंत्रित क्लबों के बीच खेली जाने वाली एक प्रतिष्ठित घरेलू फुटबॉल प्रतियोगिता है।","explanationEn":"It is a prestigious domestic football competition played between Indian Armed Forces and other invited clubs.","memoryTip":"डूरंड कप में खिलाड़ी ''दूर-दूर'' (Durand) तक गेंद किक करते हैं।","memoryTipEn":"Durand demands strong kicking (Football).","related":["Santosh Trophy","Rovers Cup","Football Tournaments"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9388ZzjPOclJusv9nmSIc', 'General Knowledge', 'भारत का सबसे बड़ा बांध कौनसा है?', 'Which is the largest (longest) dam in India?', 'हीराकुंड बांध', 'Hirakud Dam', 95, 0, '{"facts":["यह ओडिशा राज्य में महानदी पर बना है।","यह मुख्य धारा पर 4.8 किमी लंबा है, जो इसे दुनिया के सबसे लंबे मिट्टी के बांधों में से एक बनाता है।"],"factsEn":["It is built across the Mahanadi River in the state of Odisha.","Its main section is 4.8 km long, making it one of the longest earthen dams in the world."],"explanationHi":"बाढ़ नियंत्रण, सिंचाई और जलविद्युत उत्पादन के लिए आज़ादी के बाद शुरू की गई यह पहली प्रमुख बहुउद्देशीय नदी घाटी परियोजना थी।","explanationEn":"It was one of the first major multipurpose river valley projects started after independence for flood control, irrigation, and power generation.","memoryTip":"जो बांध ''महान'' नदी पर होगा, वही ''हीरा'' (सबसे बड़ा) होगा।","memoryTipEn":"Hirakud is a huge diamond (Heera) on the Mahanadi.","related":["Mahanadi River","Tehri Dam (Highest Dam)","Bhakra Nangal Dam"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FM_2VBrgSd20QOQL7Eetq', 'General Knowledge', 'संविधान की 8वीं अनुसूची में कितनी भारतीय भाषाओं को मान्यता दी गयी है?', 'How many Indian languages are recognized in the 8th Schedule of the Constitution?', '22', '22', 96, 0, '{"facts":["मूल रूप से इस अनुसूची में 14 भाषाएँ थीं।","बोडो, डोगरी, मैथिली और संथाली को 92वें संशोधन (2003) द्वारा जोड़ा गया।"],"factsEn":["Originally, there were 14 languages in this schedule.","Bodo, Dogri, Maithili, and Santhali were added by the 92nd Amendment (2003)."],"explanationHi":"यह अनुसूची भारत गणराज्य की आधिकारिक भाषाओं को सूचीबद्ध करती है, जिनका उपयोग साहित्य और प्रशासन में किया जाता है।","explanationEn":"This schedule lists the official languages of the Republic of India used in literature and administration.","memoryTip":"22 भाषाएँ 8वीं अनुसूची में ''बाईस'' (22) सुरों की तरह बजती हैं।","memoryTipEn":"8th Schedule embraces 22 voices.","related":["Official Languages Act","Article 343","Classical Languages of India"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GxdzDCVSG142_PvfaXlIt', 'General Knowledge', 'चीन की मुद्रा कौनसी है?', 'What is the currency of China?', 'युआन (रेन्मिन्बी)', 'Yuan (Renminbi)', 88, 0, '{"facts":["आधिकारिक मुद्रा का नाम रेन्मिन्बी (Renminbi) है, और युआन (Yuan) इसकी प्राथमिक इकाई है।","चीन की राजधानी बीजिंग है।"],"factsEn":["The official currency is called Renminbi, and the Yuan is its primary unit.","The capital of China is Beijing."],"explanationHi":"जिस तरह स्टर्लिंग मुद्रा है और पाउंड उसकी इकाई, उसी तरह रेन्मिन्बी मुद्रा है और युआन उसकी इकाई।","explanationEn":"Just as Sterling is the currency and Pound is the unit, Renminbi is the currency and Yuan is the unit.","memoryTip":"चीन ''युवा'' (युआन) शक्ति वाला देश है।","memoryTipEn":"Yuan is China''s One (Y-One).","related":["Yen (Japan)","Renminbi","Beijing"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('VISJzoyKGyTag8BbHTodM', 'General Knowledge', 'रेडक्रॉस के संस्थापक कौन हैं?', 'Who is the founder of the Red Cross?', 'हेनरी डूनांट', 'Henry Dunant', 92, 0, '{"facts":["उन्हें 1901 में पहला नोबेल शांति पुरस्कार मिला था।","रेडक्रॉस का मुख्यालय जिनेवा, स्विट्जरलैंड में है।"],"factsEn":["He received the first Nobel Peace Prize in 1901.","The headquarters of the Red Cross is in Geneva, Switzerland."],"explanationHi":"यह एक अंतर्राष्ट्रीय मानवीय संगठन है जो युद्ध और आपदाओं के दौरान लोगों की मदद करता है।","explanationEn":"It is an international humanitarian movement aimed at protecting human life and health in conflicts and disasters.","memoryTip":"रेडक्रॉस में लोग ''डोनट'' (Dunant / Donate) करते हैं खून और पैसा।","memoryTipEn":"Dunant donated his life to the Red Cross.","related":["World Red Cross Day (8 May)","Geneva Conventions"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7k9kYSMI-sZdlJZp5CeCd', 'General Science', 'हीमोग्लोबिन की कमी से होने वाला रोग कौनसा है?', 'Which disease is caused by the deficiency of Hemoglobin?', 'एनीमिया (रक्तअल्पता)', 'Anemia', 96, 0, '{"facts":["हीमोग्लोबिन लाल रक्त कोशिकाओं (RBCs) में पाया जाने वाला आयरन युक्त प्रोटीन है।","आयरन (लोहा) की कमी एनीमिया का सबसे आम कारण है।"],"factsEn":["Hemoglobin is an iron-rich protein found in red blood cells (RBCs).","Iron deficiency is the most common cause of anemia."],"explanationHi":"हीमोग्लोबिन शरीर के अंगों तक ऑक्सीजन ले जाता है। इसकी कमी से थकान और कमजोरी महसूस होती है।","explanationEn":"Hemoglobin carries oxygen to body organs. Its deficiency leads to fatigue and weakness.","memoryTip":"रक्त में आयरन की कमी = एनी (Enemy) मिया (Anemia)।","memoryTipEn":"Anemia means lack of blood vitality.","related":["Iron Deficiency","Erythrocytes (RBC)","Vitamin B12"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('S4jTaGvfiENztHrKpAdAF', 'General Knowledge', 'भारत कोकिला (Nightingale of India) कौन कहलाती है?', 'Who is known as the ''Nightingale of India'' (Bharat Kokila)?', 'सरोजिनी नायडू', 'Sarojini Naidu', 94, 0, '{"facts":["वे भारत की किसी भी राज्य (उत्तर प्रदेश) की पहली महिला राज्यपाल थीं।","उन्होंने ''द ब्रोकन विंग'' (The Broken Wing) जैसी प्रसिद्ध कविताएँ लिखीं।"],"factsEn":["She was the first female governor of an Indian state (Uttar Pradesh).","She wrote famous poems like ''The Broken Wing''."],"explanationHi":"उनकी कविताओं की संगीतमय और गेय प्रकृति के कारण महात्मा गांधी ने उन्हें यह उपाधि दी थी।","explanationEn":"Mahatma Gandhi gave her this title because of the lyrical and musical quality of her poetry.","memoryTip":"सरोजिनी के सुर ''कोकिला'' (कोयल) जैसे थे।","memoryTipEn":"Naidu''s notes were like a Nightingale.","related":["Lata Mangeshkar (Swar Kokila)","First Female Governor","Indian National Congress"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('B2QOU9pN0vDPyaxiRillI', 'General Knowledge', 'दिल्ली में कुतुबमीनार किसने बनवानी शुरु की थी?', 'Who started the construction of the Qutub Minar in Delhi?', 'कुतुबुद्दीन ऐबक', 'Qutb-ud-din Aibak', 93, 0, '{"facts":["उसने इसे 1192-1193 के आसपास बनवाना शुरू किया, लेकिन केवल पहली मंजिल ही बना सका।","बाद में इल्तुतमिश ने इसमें तीन और मंजिलें जोड़ीं।"],"factsEn":["He started it around 1192-1193 but could only build the first storey.","Later, Iltutmish added three more storeys to it."],"explanationHi":"यह मीनार प्रसिद्ध सूफी संत ख्वाजा कुतुबुद्दीन बख्तियार काकी की याद में बनवाई गई थी।","explanationEn":"The minaret was built in memory of the famous Sufi saint Khwaja Qutbuddin Bakhtiar Kaki.","memoryTip":"कुतुबमीनार की नींव ''कुतुबुद्दीन'' ने रखी।","memoryTipEn":"Qutb started the Qutub Minar.","related":["Iltutmish","Slave Dynasty","Qutbuddin Bakhtiar Kaki"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('p8XPzGhtdQ_PJ0wuLDp_5', 'General Knowledge', 'बनारस हिन्दू विश्वविद्यालय के संस्थापक कौन थे?', 'Who was the founder of the Banaras Hindu University (BHU)?', 'मदनमोहन मालवीय', 'Madan Mohan Malaviya', 90, 0, '{"facts":["विश्वविद्यालय की स्थापना 1916 में हुई थी।","एनी बेसेंट और सुंदर लाल ने भी इसकी स्थापना में महत्वपूर्ण भूमिका निभाई थी।"],"factsEn":["The university was established in 1916.","Annie Besant and Sunder Lal also played crucial roles in its foundation."],"explanationHi":"यह एशिया का सबसे बड़ा आवासीय विश्वविद्यालय है, जो शिक्षा और भारतीय संस्कृति को बढ़ावा देने के लिए स्थापित किया गया था।","explanationEn":"It is the largest residential university in Asia, established to promote education and Indian culture.","memoryTip":"बनारस के ''मदन'' ने महान विश्वविद्यालय बनाया।","memoryTipEn":"Malaviya made BHU a marvel.","related":["Annie Besant","Mahamana","Varanasi"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('p1ZAQbQmqa5cKoJnCg4t6', 'General Knowledge', 'अर्थशास्त्र के लेखक कौन थे?', 'Who was the author of Arthashastra?', 'चाणक्य (कौटिल्य)', 'Chanakya (Kautilya)', 94, 0, '{"facts":["चाणक्य को विष्णुगुप्त के नाम से भी जाना जाता है।","यह पुस्तक राजनीति, कूटनीति और अर्थशास्त्र पर एक प्राचीन भारतीय ग्रंथ है।"],"factsEn":["Chanakya is also known as Vishnugupta.","The book is an ancient Indian treatise on politics, diplomacy, and economics."],"explanationHi":"चाणक्य चंद्रगुप्त मौर्य के प्रधानमंत्री थे, और उन्होंने मौर्य साम्राज्य की स्थापना में महत्वपूर्ण भूमिका निभाई।","explanationEn":"Chanakya was the Prime Minister of Chandragupta Maurya and played a key role in establishing the Mauryan Empire.","memoryTip":"चाणक्य की चालाकी (कूटनीति) = कौटिल्य का अर्थशास्त्र।","memoryTipEn":"Kautilya calculated the kingdom''s economics.","related":["Chandragupta Maurya","Mauryan Empire","Vishnugupta"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('R73MypZFZ30W-vJeW1f_w', 'General Knowledge', 'विवेकानंद स्मारक कहाँ स्थित है?', 'Where is the Vivekananda Rock Memorial located?', 'कन्याकुमारी', 'Kanyakumari', 88, 0, '{"facts":["यह 1970 में स्वामी विवेकानंद के सम्मान में बनाया गया था।","यह समुद्र में एक चट्टान पर स्थित है, जहाँ स्वामी जी ने 1892 में ध्यान किया था।"],"factsEn":["Built in 1970 in honor of Swami Vivekananda.","It sits on a rock in the sea where the Swami meditated in 1892."],"explanationHi":"यह तमिलनाडु के सुदूर दक्षिण में स्थित एक प्रसिद्ध पर्यटन और तीर्थ स्थल है।","explanationEn":"It is a famous tourist and pilgrimage destination located at the southernmost tip of Tamil Nadu.","memoryTip":"विवेकानंद ने ''कन्या'' कुमारी के चरणों (दक्षिण छोर) पर ध्यान लगाया।","memoryTipEn":"Vivekananda meditated at the edge of India.","related":["Swami Vivekananda","Tamil Nadu","Cape Comorin"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vKs-XBEgWjrrR8IOOicZb', 'General Knowledge', 'दक्षेस (SAARC) का मुख्यालय कहाँ स्थित है?', 'Where is the headquarters of SAARC located?', 'काठमांडू (नेपाल)', 'Kathmandu (Nepal)', 92, 0, '{"facts":["SAARC का पूर्ण रूप South Asian Association for Regional Cooperation है।","इसकी स्थापना 8 दिसंबर 1985 को ढाका (बांग्लादेश) में हुई थी।"],"factsEn":["SAARC stands for South Asian Association for Regional Cooperation.","It was established on Dec 8, 1985, in Dhaka (Bangladesh)."],"explanationHi":"यह दक्षिण एशिया के 8 देशों का एक आर्थिक और राजनीतिक संगठन है।","explanationEn":"It is an economic and political organization of 8 countries in South Asia.","memoryTip":"दक्षिण के आठों देश ''काठमांडू'' में मिलते हैं।","memoryTipEn":"SAARC HQ sits in the Himalayas (Kathmandu).","related":["South Asian Nations","Kathmandu","Dhaka"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FS2nvJe2_J-sA3kopxI-R', 'General Knowledge', 'दक्षेस (SAARC) के कितने देश सदस्य हैं?', 'How many member countries are there in SAARC?', '8', '8', 91, 0, '{"facts":["ये 8 देश हैं: भारत, नेपाल, बांग्लादेश, श्रीलंका, मालदीव, भूटान, पाकिस्तान, अफगानिस्तान।","अफगानिस्तान 2007 में सार्क का 8वां सदस्य बना था।"],"factsEn":["The 8 members are: India, Nepal, Bangladesh, Sri Lanka, Maldives, Bhutan, Pakistan, Afghanistan.","Afghanistan became the 8th member in 2007."],"explanationHi":"इन सभी देशों का उद्देश्य क्षेत्रीय सहयोग और आर्थिक विकास को बढ़ावा देना है।","explanationEn":"The aim of all these countries is to promote regional cooperation and economic development.","memoryTip":"MBBS PAIN (Maldives, Bhutan, Bangladesh, Sri Lanka, Pakistan, Afghanistan, India, Nepal).","memoryTipEn":"MBBS PAIN (Acronym for all 8 countries).","related":["Afghanistan (Newest member)","BIMSTEC"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QPQp5L929C0YO5HZJbMbV', 'General Knowledge', 'भारत की तट रेखा (Coastline) की लम्बाई कितनी है?', 'What is the total length of India''s coastline?', '7516 कि.मी.', '7516 km', 89, 0, '{"facts":["इसमें मुख्य भूमि की तटरेखा और अंडमान-निकोबार तथा लक्षद्वीप की तटरेखाएँ शामिल हैं।","गुजरात राज्य की तटरेखा सबसे लंबी है।"],"factsEn":["This includes the mainland coastline and the coastlines of Andaman & Nicobar and Lakshadweep islands.","The state of Gujarat has the longest coastline."],"explanationHi":"भारत तीन ओर से समुद्र से घिरा हुआ है (अरब सागर, बंगाल की खाड़ी और हिंद महासागर)।","explanationEn":"India is surrounded by the sea on three sides (Arabian Sea, Bay of Bengal, and Indian Ocean).","memoryTip":"7-5-1-6 किलोमीटर का समुद्री पहरा।","memoryTipEn":"7516 kilometers of waves.","related":["Gujarat Coastline","Indian Ocean","Exclusive Economic Zone"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QZ_zyiV1D6TgcLdr6_Y_Y', 'General Knowledge', 'विश्व में अभ्रक (Mica) का सर्वाधिक उत्पादन किस देश में होता है?', 'Which country is the largest producer of Mica in the world?', 'भारत (ऐतिहासिक रूप से/पीडीएफ अनुसार)', 'India (Historically / As per PDF)', 84, 0, '{"facts":["नोट: वर्तमान वैश्विक आंकड़ों के अनुसार चीन दुनिया का सबसे बड़ा अभ्रक उत्पादक है।","भारत में अभ्रक का सर्वाधिक उत्पादन आंध्र प्रदेश (नेल्लोर) में होता है।"],"factsEn":["Note: According to current global data, China is the largest producer of mica.","In India, Andhra Pradesh (Nellore) is the top producer of mica."],"explanationHi":"अभ्रक का उपयोग मुख्य रूप से विद्युत उद्योगों में इंसुलेटर के रूप में किया जाता है क्योंकि यह ऊष्मा और बिजली का कुचालक है।","explanationEn":"Mica is primarily used in electrical industries as an insulator because it is a bad conductor of heat and electricity.","memoryTip":"अभ्रक से भारत का ''अभिमान'' चमकता था।","memoryTipEn":"Mica insulates Indian wires.","related":["Andhra Pradesh Mica","Insulators","Minerals of India"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JwVkLJA7Vg0hgZqsA9U-Y', 'General Knowledge', 'ग्रांट-ट्रंक (G.T.) रोड किसने बनवाया?', 'Who built the Grand Trunk (G.T.) Road?', 'शेरशाह सूरी', 'Sher Shah Suri', 95, 0, '{"facts":["यह एशिया की सबसे पुरानी और लंबी प्रमुख सड़कों में से एक है।","यह चटगांव (बांग्लादेश) से हावड़ा होते हुए काबुल (अफगानिस्तान) तक जाती थी।"],"factsEn":["It is one of Asia''s oldest and longest major roads.","It ran from Chittagong (Bangladesh) through Howrah to Kabul (Afghanistan)."],"explanationHi":"शेरशाह सूरी ने 16वीं शताब्दी में अपने साम्राज्य को सुदृढ़ करने के लिए इस प्राचीन मार्ग का पुनर्निर्माण कराया था जिसे ''सड़क-ए-आज़म'' कहा जाता था।","explanationEn":"Sher Shah Suri rebuilt this ancient route in the 16th century to consolidate his empire, calling it ''Sadak-e-Azam''.","memoryTip":"''शेर'' की तरह ''ग्रांड'' काम किया सूरी ने।","memoryTipEn":"Sher Shah steered the Grand route.","related":["Sadak-e-Azam","National Highway 1 and 2","Sur Empire"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ev17_udtauW4hsafg1HkD', 'General Science', 'विटामिन ''B'' की कमी से कौनसा रोग होता है?', 'Which disease is caused by the deficiency of Vitamin ''B'' (specifically B1)?', 'बेरी-बेरी', 'Beri-Beri', 94, 0, '{"facts":["विटामिन B1 का रासायनिक नाम थियामिन (Thiamine) है।","यह रोग मुख्य रूप से उन क्षेत्रों में होता है जहाँ पॉलिश किए हुए सफेद चावल मुख्य भोजन हैं।"],"factsEn":["The chemical name of Vitamin B1 is Thiamine.","It mainly occurs in regions where polished white rice is the staple diet."],"explanationHi":"बेरी-बेरी नर्वस सिस्टम (तंत्रिका तंत्र) और हृदय प्रणाली को गंभीर रूप से प्रभावित करता है।","explanationEn":"Beri-Beri severely affects the nervous system and cardiovascular system.","memoryTip":"B से Beri-Beri (बी से बेरी-बेरी)।","memoryTipEn":"B stands for Beri-Beri.","related":["Thiamine","Polished Rice","Water-soluble vitamins"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('irBD5jyoyCJImrqzMgM6X', 'General Science', 'विटामिन ''C'' की कमी से कौनसी बीमारी होती है?', 'Which disease is caused by the deficiency of Vitamin ''C''?', 'स्कर्वी', 'Scurvy', 95, 0, '{"facts":["इस बीमारी में मसूड़ों से खून आने लगता है और घाव जल्दी नहीं भरते।","खट्टे फल (नींबू, संतरा, आंवला) इसके सबसे अच्छे स्रोत हैं।"],"factsEn":["In this disease, gums start bleeding and wounds don''t heal quickly.","Citrus fruits (lemon, orange, amla) are its best sources."],"explanationHi":"विटामिन C कोलेजन प्रोटीन बनाने के लिए आवश्यक है, जो त्वचा और मसूड़ों को स्वस्थ रखता है।","explanationEn":"Vitamin C is essential for making collagen protein, which keeps skin and gums healthy.","memoryTip":"C से Scurvy (C की कमी से स्कर्वी)।","memoryTipEn":"C cures Scurvy.","related":["Ascorbic Acid","Citrus Fruits","Collagen"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RKbPZMwFZ4j9HhpaIiVpI', 'General Science', 'दूध में कौनसा विटामिन नहीं होता है?', 'Which vitamin is not present in milk?', 'विटामिन ''C''', 'Vitamin ''C''', 92, 0, '{"facts":["दूध को पूर्ण आहार माना जाता है, लेकिन इसमें विटामिन C और आयरन की कमी होती है।","विटामिन C खट्टे फलों में पाया जाता है।"],"factsEn":["Milk is considered a complete food, but it lacks Vitamin C and Iron.","Vitamin C is found in citrus fruits."],"explanationHi":"गाय या भैंस के दूध में एस्कॉर्बिक एसिड (विटामिन सी) नगण्य मात्रा में होता है और उबालने पर यह पूरी तरह नष्ट हो जाता है।","explanationEn":"Cow or buffalo milk has negligible amounts of ascorbic acid (Vitamin C), which is completely destroyed upon boiling.","memoryTip":"दूध खट्टा नहीं होता, इसलिए विटामिन C नहीं होता।","memoryTipEn":"Milk is not citrus, so no C.","related":["Complete Food","Calcium","Iron deficiency in milk"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('E7qGJMDI-nqyumv29-QIJ', 'General Science', 'विटामिन ''D'' की कमी से कौनसा रोग होता है?', 'Which disease is caused by the deficiency of Vitamin ''D''?', 'रिकेट्स (सूखा रोग)', 'Rickets', 96, 0, '{"facts":["यह मुख्य रूप से बच्चों में होता है, जिससे उनकी हड्डियां नरम और मुड़ी हुई हो जाती हैं।","वयस्कों में इसकी कमी से ''ऑस्टियोमलेशिया'' (Osteomalacia) होता है।"],"factsEn":["It primarily occurs in children, making their bones soft and bent.","In adults, its deficiency causes ''Osteomalacia''."],"explanationHi":"विटामिन डी शरीर में कैल्शियम और फास्फोरस को अवशोषित करने में मदद करता है, जो मजबूत हड्डियों के लिए आवश्यक है।","explanationEn":"Vitamin D helps the body absorb calcium and phosphorus, which are essential for strong bones.","memoryTip":"D से ''धूप'' नहीं मिलेगी तो हड्डियाँ ''रिकेट्स'' का शिकार होंगी।","memoryTipEn":"Deficiency of D makes bones Decrepit (Rickets).","related":["Calciferol","Sunlight Vitamin","Osteomalacia"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mxBWFmAsfndZxaEPSKvd0', 'General Science', 'किस विटामिन की कमी से खून का थक्का नहीं जमता?', 'Deficiency of which vitamin prevents blood from clotting?', 'विटामिन ''K''', 'Vitamin ''K''', 95, 0, '{"facts":["विटामिन K का मुख्य कार्य रक्तस्राव को रोकना है।","यह हरी पत्तेदार सब्जियों में प्रचुर मात्रा में पाया जाता है।"],"factsEn":["The main function of Vitamin K is to stop bleeding.","It is found abundantly in green leafy vegetables."],"explanationHi":"जब शरीर में चोट लगती है, तो विटामिन K प्रोथ्रोम्बिन (Prothrombin) बनाकर रक्त का थक्का जमाता है।","explanationEn":"When the body is injured, Vitamin K forms blood clots by synthesizing Prothrombin.","memoryTip":"K से खून का थक्का (Klot - Clot)।","memoryTipEn":"K is for Koagulation (Clotting).","related":["Phylloquinone","Prothrombin","Hemophilia"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8YLnTKewtD0T0j2hfTMQP', 'General Science', 'विटामिन ''E'' की कमी से कौनसा रोग होता है?', 'Which disease is caused by the deficiency of Vitamin ''E''?', 'बांझपन (Infertility)', 'Infertility (Sterility)', 89, 0, '{"facts":["विटामिन E का रासायनिक नाम टोकोफेरॉल (Tocopherol) है।","इसे ''ब्यूटी विटामिन'' (Beauty Vitamin) भी कहा जाता है।"],"factsEn":["The chemical name of Vitamin E is Tocopherol.","It is also known as the ''Beauty Vitamin''."],"explanationHi":"यह एक शक्तिशाली एंटीऑक्सीडेंट है; इसकी कमी से प्रजनन क्षमता (Fertility) कम हो सकती है और मांसपेशियां कमजोर हो सकती हैं।","explanationEn":"It is a powerful antioxidant; its deficiency can reduce fertility and cause muscle weakness.","memoryTip":"E से ''एग'' (Egg) नहीं बनता, यानी बांझपन।","memoryTipEn":"E ensures Embryo survival.","related":["Tocopherol","Antioxidants","Beauty Vitamin"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lDo7CEZVwHLmYaHOZo-Js', 'General Science', 'विटामिन ''C'' का रासायनिक नाम क्या है?', 'What is the chemical name of Vitamin ''C''?', 'एस्कोर्बिक अम्ल (Ascorbic Acid)', 'Ascorbic Acid', 94, 0, '{"facts":["यह जल में घुलनशील (Water-soluble) विटामिन है।","यह प्रतिरक्षा प्रणाली (Immune system) को मजबूत करता है।"],"factsEn":["It is a water-soluble vitamin.","It strengthens the immune system."],"explanationHi":"गर्म करने पर यह विटामिन सबसे जल्दी नष्ट हो जाता है।","explanationEn":"This vitamin gets destroyed most rapidly upon heating.","memoryTip":"खट्टे (Acid) फलों में एस्कोर्बिक एसिड होता है।","memoryTipEn":"C stands for aCorbic acid (phonetic).","related":["Scurvy","Water-soluble vitamins"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oLOI30E-BfsOY1QEVIuYf', 'General Science', 'वसा में घुलनशील विटामिन कौनसे हैं?', 'Which are the fat-soluble vitamins?', 'A, D, E, और K (पीडीएफ में ''A'' और ''E'' उल्लिखित)', 'A, D, E, and K (PDF mentions ''A'' and ''E'')', 92, 0, '{"facts":["विटामिन B और C जल में घुलनशील (Water-soluble) होते हैं।","वसा में घुलनशील विटामिन यकृत (Liver) और फैटी ऊतकों में जमा हो जाते हैं।"],"factsEn":["Vitamins B and C are water-soluble.","Fat-soluble vitamins are stored in the liver and fatty tissues."],"explanationHi":"A, D, E, और K को अवशोषित होने के लिए वसा की आवश्यकता होती है।","explanationEn":"A, D, E, and K require fat to be absorbed by the body.","memoryTip":"कीड़ा (K-E-D-A) वसा में घुल जाता है।","memoryTipEn":"KEDA (A, D, E, K) dissolves in fat.","related":["Water-soluble vitamins","Liver Storage"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zIz9ymbaoBhTRxCvlECXt', 'General Science', 'साधारण नमक का रासायनिक नाम क्या है?', 'What is the chemical name of common salt?', 'सोडियम क्लोराइड (NaCl)', 'Sodium Chloride (NaCl)', 93, 0, '{"facts":["यह समुद्र के पानी के वाष्पीकरण से प्राप्त होता है।","यह मानव शरीर में द्रव संतुलन (Fluid balance) बनाए रखने के लिए आवश्यक है।"],"factsEn":["It is obtained by the evaporation of seawater.","It is essential for maintaining fluid balance in the human body."],"explanationHi":"सोडियम (Na) और क्लोरीन (Cl) आयनों के संयोजन से यह आयनिक यौगिक बनता है।","explanationEn":"This ionic compound is formed by the combination of Sodium (Na) and Chlorine (Cl) ions.","memoryTip":"नमक (Na) और क्लोरीन (Cl) = NaCl।","memoryTipEn":"NaCl is the salt of the earth.","related":["Salinity","Evaporation","Iodized Salt"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RO3QNqcRp-0aj_F5XQyLo', 'General Science', 'हँसाने वाली गैस (Laughing Gas) का रासायनिक नाम क्या है?', 'What is the chemical name of Laughing Gas?', 'नाइट्रस ऑक्साइड (N2O)', 'Nitrous Oxide (N2O)', 94, 0, '{"facts":["इसे अक्सर दंत चिकित्सा (Dentistry) में एनेस्थीसिया के रूप में प्रयोग किया जाता है।","यह एक रंगहीन और अज्वलनशील गैस है।"],"factsEn":["It is often used as an anesthetic in dentistry.","It is a colorless and non-flammable gas."],"explanationHi":"सांस के साथ अंदर जाने पर यह गैस हल्की खुशी और हँसी पैदा करती है, इसीलिए इसे लाफिंग गैस कहते हैं।","explanationEn":"When inhaled, this gas induces mild euphoria and laughter, hence the name.","memoryTip":"N2O (Nitrous Oxide) सुंघोगे तो No (N) To (2) Oh (O) कहते हुए हंसोगे।","memoryTipEn":"N2O will make you go Ho Ho.","related":["Anesthesia","Joseph Priestley (Discovered it)","Dentistry"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JBVrLr5HVadzBG9YmlKc8', 'General Science', 'धावन सोड़ा (Washing Soda) का रासायनिक नाम क्या है?', 'What is the chemical name of Washing Soda?', 'सोडियम कार्बोनेट', 'Sodium Carbonate', 91, 0, '{"facts":["इसका रासायनिक सूत्र Na2CO3 है।","बेकिंग सोडा (Baking Soda) का नाम सोडियम बाइकार्बोनेट (NaHCO3) है।"],"factsEn":["Its chemical formula is Na2CO3.","Baking Soda is Sodium Bicarbonate (NaHCO3)."],"explanationHi":"इसका उपयोग पानी की कठोरता (Hardness of water) दूर करने और कपड़े धोने के लिए किया जाता है।","explanationEn":"It is used to remove the permanent hardness of water and for laundering.","memoryTip":"कपड़े धोने (Washing) में ''बाइ'' (Bicarbonate) नहीं लगती, सिर्फ कार्बोनेट लगता है।","memoryTipEn":"Washing drops the ''Bi'' from Bicarbonate.","related":["Baking Soda","Water Softening","Solvay Process"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DCUGwTY3Ozm4J0ax_juBO', 'General Science', 'पीतल (Brass) किन दो धातुओं का मिश्रण है?', 'Brass is an alloy of which two metals?', 'तांबा और जस्ता', 'Copper and Zinc', 95, 0, '{"facts":["इसमें आमतौर पर 60-70% तांबा (Copper) और 30-40% जस्ता (Zinc) होता है।","कांसा (Bronze) तांबा और टिन (Tin) का मिश्रण है।"],"factsEn":["It usually contains 60-70% Copper and 30-40% Zinc.","Bronze is an alloy of Copper and Tin."],"explanationHi":"जस्ते की उपस्थिति पीतल को शुद्ध तांबे की तुलना में अधिक मजबूत और कठोर बनाती है।","explanationEn":"The presence of zinc makes brass stronger and harder than pure copper.","memoryTip":"''पिताजी'' - पी (पीतल) = ता (तांबा) + जी (जिंक/जस्ता)।","memoryTipEn":"BraZZ has Z for Zinc (and Copper).","related":["Bronze (Copper + Tin)","Alloys","Metallurgy"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IW89gHkmSqpDThMZRKzMT', 'General Science', 'कैल्सीफेरॉल किस विटामिन का रासायनिक नाम है?', 'Calciferol is the chemical name of which vitamin?', 'विटामिन ''D''', 'Vitamin ''D''', 92, 0, '{"facts":["यह आंतों से कैल्शियम के अवशोषण को बढ़ाता है।","D2 को एर्गोकैल्सीफेरोल और D3 को कोलेकैल्सीफेरोल कहते हैं।"],"factsEn":["It promotes the absorption of calcium from the intestines.","D2 is Ergocalciferol and D3 is Cholecalciferol."],"explanationHi":"चूंकि यह शरीर में कैल्शियम के स्तर को नियंत्रित करता है, इसलिए इसका नाम ''कैल्सीफेरॉल'' पड़ा।","explanationEn":"Since it regulates Calcium levels in the body, it is named ''Calciferol''.","memoryTip":"विटामिन D ''कैल्शियम'' (कैल्सी) के लिए जरूरी है।","memoryTipEn":"Calciferol Controls Calcium.","related":["Rickets","Calcium Absorption","Sunlight"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MeZDDh77Ko-haeMhcc5qn', 'General Science', 'नेत्रदान में नेत्र के किस भाग का दान किया जाता है?', 'Which part of the eye is donated in eye donation?', 'कोर्निया', 'Cornea', 96, 0, '{"facts":["कोर्निया आंख का पारदर्शी (transparent) सामने का हिस्सा है।","कोर्निया में रक्त वाहिकाएं (Blood vessels) नहीं होती हैं, इसलिए अस्वीकृति (Rejection) का खतरा कम होता है।"],"factsEn":["Cornea is the clear front surface of the eye.","The cornea has no blood vessels, reducing the risk of rejection."],"explanationHi":"पूरे नेत्र का प्रत्यारोपण नहीं किया जाता, केवल धुंधली हो चुकी कोर्निया को स्वस्थ दान की गई कोर्निया से बदला जाता है।","explanationEn":"The entire eye is not transplanted; only the clouded cornea is replaced with a healthy donated one.","memoryTip":"नेत्रदान में ''कोना'' (Cornea - बाहरी परत) दान होता है।","memoryTipEn":"Cornea is the Cover we donate.","related":["Eye Transplant","Retina","Cataract"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zMrVu-XsZ5m7dkT7Nj9j_', 'General Science', 'किस विटामिन में कोबाल्ट (Cobalt) होता है?', 'Which vitamin contains Cobalt?', 'विटामिन B-12', 'Vitamin B-12', 94, 0, '{"facts":["विटामिन B-12 का रासायनिक नाम साइनोकोबालामिन (Cyanocobalamin) है।","इसकी कमी से ''पर्निशियस एनीमिया'' (Pernicious anemia) होता है।"],"factsEn":["The chemical name of Vitamin B-12 is Cyanocobalamin.","Its deficiency causes ''Pernicious anemia''."],"explanationHi":"कोबाल्ट की उपस्थिति के कारण ही इसका नाम ''कोबालामिन'' है, जो तंत्रिका तंत्र और लाल रक्त कोशिकाओं के लिए आवश्यक है।","explanationEn":"Due to the presence of cobalt, it is named ''Cobalamin'', essential for the nervous system and RBCs.","memoryTip":"B-12 में को''बाल''ट (Cobalt) होता है।","memoryTipEn":"Cobalamin contains Cobalt.","related":["Cyanocobalamin","Pernicious Anemia","Red Blood Cells"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jBLtp1Sr4BRL-Q5M_73Fr', 'General Science', 'कोशिका का पावरहाउस (Powerhouse of the cell) किसे कहा जाता है?', 'What is known as the powerhouse of the cell?', 'माइटोकॉन्ड्रिया', 'Mitochondria', 97, 0, '{"facts":["माइटोकॉन्ड्रिया का अपना DNA होता है।","यह कोशिकीय श्वसन (Cellular respiration) का स्थल है।"],"factsEn":["Mitochondria have their own DNA.","It is the site of cellular respiration."],"explanationHi":"यह भोजन के अणुओं को तोड़कर ऊर्जा (ATP - एडेनोसिन ट्राइफॉस्फेट) उत्पन्न करता है, इसलिए इसे पावरहाउस कहते हैं।","explanationEn":"It breaks down food molecules to generate energy (ATP - Adenosine Triphosphate), hence called the powerhouse.","memoryTip":"माइट (Mighty/ताकतवर) बनाने वाला = माइटोकॉन्ड्रिया।","memoryTipEn":"Mighty Mitochondria makes energy.","related":["ATP (Adenosine Triphosphate)","Cellular Respiration","Nucleus"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dexFB0j8gVzcLqw9uSaON', 'General Science', 'लाल रक्त कणिकाओं (RBC) का निर्माण हमारे शरीर के किस भाग में होता है?', 'In which part of our body are Red Blood Cells (RBCs) formed?', 'अस्थि मज्जा (Bone Marrow)', 'Bone Marrow', 95, 0, '{"facts":["RBC का जीवनकाल लगभग 120 दिन होता है।","भ्रूण अवस्था (fetal stage) में इनका निर्माण यकृत (Liver) और प्लीहा (Spleen) में होता है।"],"factsEn":["The lifespan of RBCs is about 120 days.","In the fetal stage, they are formed in the liver and spleen."],"explanationHi":"लंबी हड्डियों के खोखले हिस्से में मौजूद स्पंजी ऊतक (अस्थि मज्जा) स्टेम कोशिकाओं के माध्यम से रक्त का निर्माण करते हैं।","explanationEn":"The spongy tissue (bone marrow) inside long bones produces blood through stem cells.","memoryTip":"हड्डी (Bone) के बीच ''मजे'' (Marrow) से खून बनता है।","memoryTipEn":"Blood is born in the bones.","related":["Erythrocytes","Spleen (Graveyard of RBC)","White Blood Cells"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('i01j2VX0CuTl9MclLrzo7', 'General Knowledge', 'राष्ट्रीय विज्ञान दिवस कब मनाया जाता है?', 'When is National Science Day celebrated?', '28 फरवरी', '28 February', 92, 0, '{"facts":["यह दिन भारतीय भौतिक विज्ञानी सी.वी. रमन द्वारा ''रमन प्रभाव'' (Raman Effect) की खोज की याद में मनाया जाता है।","इस खोज के लिए उन्हें 1930 में नोबेल पुरस्कार मिला था।"],"factsEn":["Celebrated to mark the discovery of the ''Raman Effect'' by Indian physicist C.V. Raman.","He received the Nobel Prize in 1930 for this discovery."],"explanationHi":"समाज में वैज्ञानिक सोच को बढ़ावा देने के लिए यह दिवस राष्ट्रीय स्तर पर मनाया जाता है।","explanationEn":"This day is observed nationally to foster a scientific temper in society.","memoryTip":"फ़रवरी के अंत (28) में विज्ञान का ''रमन'' (जश्न) होता है।","memoryTipEn":"28 Feb = Science reflects the Raman effect.","related":["C.V. Raman","Raman Effect","Nobel Prize in Physics 1930"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Q8VUTDUhYDeQEClXix7nY', 'General Science', 'ब्लडप्रेशर (रक्तचाप) मापने के लिए किस यंत्र का प्रयोग किया जाता है?', 'Which instrument is used to measure blood pressure?', 'स्फिग्मोमैनोमीटर', 'Sphygmomanometer', 94, 0, '{"facts":["एक स्वस्थ सामान्य वयस्क का रक्तचाप 120/80 mmHg होता है।","यह यंत्र सिस्टोलिक (Systolic) और डायस्टोलिक (Diastolic) दोनों दबावों को मापता है।"],"factsEn":["A healthy normal adult''s blood pressure is 120/80 mmHg.","It measures both systolic and diastolic pressures."],"explanationHi":"यह एक हवा भरने वाले कफ (cuff) और पारे के गेज (mercury gauge) का उपयोग करके धमनियों में रक्त के दबाव को मापता है।","explanationEn":"It measures arterial blood pressure using an inflatable cuff and a mercury gauge.","memoryTip":"बीपी मापने का यंत्र जिसका नाम बोलने में ''सांस'' फूल जाए = स्फिग्मोमैनोमीटर।","memoryTipEn":"Sphygmo measures the pulse pressure.","related":["Systolic/Diastolic Pressure","Hypertension","Stethoscope"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('16vVHgY615HESL84YxIDz', 'General Science', 'कंप्यूटर की परमानेंट मैमोरी क्या कहलाती है?', 'What is the permanent memory of a computer called?', 'ROM (Read Only Memory)', 'ROM (Read Only Memory)', 91, 0, '{"facts":["यह एक नॉन-वोलेटाइल (Non-volatile) मेमोरी है, यानी बिजली जाने पर भी डेटा सुरक्षित रहता है।","RAM (Random Access Memory) अस्थायी (Temporary/Volatile) मेमोरी है।"],"factsEn":["It is non-volatile memory, meaning data is retained even when power is off.","RAM (Random Access Memory) is temporary/volatile memory."],"explanationHi":"इसमें कंप्यूटर को स्टार्ट (Boot) करने के लिए आवश्यक बुनियादी निर्देश (BIOS) स्टोर होते हैं।","explanationEn":"It stores fundamental instructions (BIOS) required to boot up the computer.","memoryTip":"ROM हमेशा रहता है (Permanent), RAM भाग जाता है (Temporary)।","memoryTipEn":"Read Only, Retained forever.","related":["RAM","Non-volatile Memory","BIOS"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8UXB3HB8jK9ezlBy42Nu3', 'General Knowledge', 'किस अधिवेशन में कांग्रेस उदारवादी और उग्रवादी नामक दो दलों में विभाजित हो गयी थी?', 'In which session did the Congress split into two factions: Moderates and Extremists?', '1907 के सूरत अधिवेशन में', 'In the 1907 Surat Session', 93, 0, '{"facts":["इस अधिवेशन की अध्यक्षता रासबिहारी घोष ने की थी।","गरम दल के प्रमुख नेता ''लाल-बाल-पाल'' (लाला लाजपत राय, बाल गंगाधर तिलक, बिपिन चंद्र पाल) थे।"],"factsEn":["This session was presided over by Rash Behari Ghosh.","The extremist leaders were ''Lal-Bal-Pal''."],"explanationHi":"स्वदेशी आंदोलन के तरीके और अध्यक्ष पद को लेकर दोनों गुटों में भारी मतभेद हो गया था, जिससे यह विभाजन हुआ।","explanationEn":"The split occurred due to severe differences over the methods of the Swadeshi movement and the presidency election.","memoryTip":"सूरत में कांग्रेस की ''सूरत'' बिगड़ गई (विभाजन)।","memoryTipEn":"Surat Split in Seven (1907).","related":["Surat Split","Lal Bal Pal","Lucknow Pact 1916 (Reunion)"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('g_-W3TPTdHbsPpWwB5LZs', 'General Knowledge', 'तंजौर का वृहदेश्वर मंदिर किसने बनवाया था?', 'Who built the Brihadisvara Temple at Tanjore (Thanjavur)?', 'राजराजा प्रथम चोल ने', 'Rajaraja Chola I', 90, 0, '{"facts":["यह भगवान शिव को समर्पित एक हिंदू मंदिर है।","यह पूरी तरह से ग्रेनाइट से बना दुनिया का पहला मंदिर है और यूनेस्को विश्व धरोहर स्थल है।"],"factsEn":["It is a Hindu temple dedicated to Lord Shiva.","It is the world''s first complete granite temple and a UNESCO World Heritage site."],"explanationHi":"द्रविड़ वास्तुकला की चोटी का प्रतिनिधित्व करने वाला यह मंदिर चोल साम्राज्य की शक्ति और धन का प्रतीक है।","explanationEn":"Representing the pinnacle of Dravidian architecture, it symbolizes the power and wealth of the Chola Empire.","memoryTip":"''वृहद'' (बड़ा) मंदिर ''राज'' (राजाओं) के ''राज'' में बना।","memoryTipEn":"Rajaraja raised the grand (Brihad) temple.","related":["Chola Dynasty","Dravidian Architecture","Raja Raja Chola I"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DLqPkAwMf_DmqYfXJhVzr', 'General Knowledge', 'मुगल सम्राट अकबर का जन्म कहाँ हुआ था?', 'Where was the Mughal Emperor Akbar born?', 'अमरकोट के दुर्ग (किले) में', 'At the Amarkot Fort', 88, 0, '{"facts":["उनका जन्म 1542 में राजपूत शासक राणा प्रसाद (वीरसाल) के महल में हुआ था।","उस समय उनके पिता हुमायूँ शेरशाह सूरी से हारने के बाद निर्वासित जीवन जी रहे थे।"],"factsEn":["He was born in 1542 in the palace of Rajput ruler Rana Prasad.","His father Humayun was living in exile after being defeated by Sher Shah Suri."],"explanationHi":"अकबर का जन्म एक राजपूत महल में हुआ था, जो बाद में उनकी धार्मिक सहिष्णुता की नीतियों का एक कारण माना जाता है।","explanationEn":"Akbar''s birth in a Rajput palace is often considered a subtle influence on his later policies of religious tolerance.","memoryTip":"अकबर ''अमर'' हो गया, और उसका जन्म ''अमरकोट'' में हुआ था।","memoryTipEn":"Akbar was born in Amarkot during exile.","related":["Humayun","Sher Shah Suri","Din-i-Ilahi"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rbn_WVCLpmLk8jIF7FqhF', 'General Knowledge', 'संसद के दोनों सदनों की संयुक्त बैठक की अध्यक्षता कौन करता है?', 'Who presides over the joint sitting of both houses of Parliament?', 'लोकसभा अध्यक्ष', 'Speaker of Lok Sabha', 95, 0, '{"facts":["संयुक्त बैठक बुलाने (Summon) का अधिकार ''राष्ट्रपति'' के पास है (अनुच्छेद 108)।","यदि लोकसभा अध्यक्ष अनुपस्थित है, तो लोकसभा का उपाध्यक्ष अध्यक्षता करता है।"],"factsEn":["The President has the power to summon the joint sitting (Article 108).","If the Speaker is absent, the Deputy Speaker of Lok Sabha presides."],"explanationHi":"किसी सामान्य विधेयक पर दोनों सदनों (लोकसभा और राज्यसभा) के बीच गतिरोध को हल करने के लिए संयुक्त बैठक बुलाई जाती है।","explanationEn":"A joint sitting is convened to resolve a deadlock between the two houses over an ordinary bill.","memoryTip":"बुलाएगा राष्ट्रपति, लेकिन कुर्सी पर बैठेगा ''लोकसभा का स्पीकर''।","memoryTipEn":"President summons, Speaker presides.","related":["Article 108","Parliament of India","Rajya Sabha Chairman"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0i30Sfg1n_I_wpGTIdx0I', 'General Knowledge', 'भारत के प्रथम लोकसभा अध्यक्ष कौन थे?', 'Who was the first Speaker of the Lok Sabha in India?', 'गणेश वासुदेव मावलंकर (G. V. Mavalankar)', 'G. V. Mavalankar', 92, 0, '{"facts":["इन्हें ''लोकसभा का पिता'' भी कहा जाता है।","उन्होंने 1952 से 1956 तक इस पद पर कार्य किया।"],"factsEn":["He is also known as the ''Father of the Lok Sabha''.","He served from 1952 to 1956."],"explanationHi":"वे स्वतंत्र भारत की पहली चुनी हुई संसद (लोकसभा) के पीठासीन अधिकारी थे।","explanationEn":"He was the presiding officer of the first elected parliament (Lok Sabha) of independent India.","memoryTip":"लोकसभा का ''श्री गणेश'' मावलंकर जी ने किया।","memoryTipEn":"Ganesh started the Lok Sabha.","related":["Lok Sabha Speaker","Father of Lok Sabha","Sukumar Sen (First Chief Election Commissioner)"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('cf6BRj6D-7HVsSK6V3jLi', 'General Knowledge', 'कोई विधेयक धन विधेयक (Money Bill) है या नहीं, इसका निर्णय कौन करता है?', 'Who decides whether a bill is a Money Bill or not?', 'लोकसभा अध्यक्ष', 'Speaker of Lok Sabha', 96, 0, '{"facts":["धन विधेयक केवल लोकसभा में पेश किया जा सकता है (अनुच्छेद 110)।","अध्यक्ष का निर्णय अंतिम होता है और इसे किसी भी अदालत में चुनौती नहीं दी जा सकती।"],"factsEn":["A Money Bill can only be introduced in the Lok Sabha (Article 110).","The Speaker''s decision is final and cannot be challenged in any court."],"explanationHi":"धन विधेयक करों (Taxes) या सरकारी खर्चों से संबंधित होता है, और इस पर राज्यसभा की शक्तियां सीमित होती हैं।","explanationEn":"A Money Bill relates to taxation or government expenditure, and the Rajya Sabha has limited powers over it.","memoryTip":"पैसे (धन) का फैसला ''जनता'' का सदन (लोकसभा) का मुखिया करेगा।","memoryTipEn":"Speaker has the final say on Money.","related":["Article 110","Financial Bill","Rajya Sabha powers"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('chGkhTNOZu5CVqhCwyjBC', 'General Knowledge', 'विश्व का सबसे बड़ा महाद्वीप कौनसा है?', 'Which is the largest continent in the world?', 'एशिया', 'Asia', 94, 0, '{"facts":["एशिया क्षेत्रफल और जनसंख्या दोनों ही दृष्टि से सबसे बड़ा महाद्वीप है।","यह पृथ्वी के कुल भूमि क्षेत्र का लगभग 30% हिस्सा कवर करता है।"],"factsEn":["Asia is the largest continent by both area and population.","It covers about 30% of the Earth''s total land area."],"explanationHi":"दुनिया की 60% से अधिक आबादी इसी महाद्वीप में रहती है, जिसमें भारत और चीन जैसे बड़े देश शामिल हैं।","explanationEn":"Over 60% of the global population resides in this continent, which includes massive countries like India and China.","memoryTip":"एशिया का ''एरिया'' सबसे बड़ा है।","memoryTipEn":"Asia has the most Area.","related":["Africa (Second Largest)","Australia (Smallest)","Population density"]}', 'published', 1776083451, 1776083451);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1DYu1RGw3wVwLFz-s4UO2', 'General Knowledge', 'हैदराबाद किस नदी पर बसा है?', 'Hyderabad is situated on the banks of which river?', 'मूसी', 'Musi', 89, 0, '{"facts":["मूसी नदी कृष्णा नदी की एक सहायक नदी है।","हैदराबाद को ''मोतियों का शहर'' (City of Pearls) भी कहा जाता है।"],"factsEn":["Musi river is a tributary of the Krishna river.","Hyderabad is also known as the ''City of Pearls''."],"explanationHi":"मूसी नदी हैदराबाद को ऐतिहासिक रूप से पुराने और नए शहर में विभाजित करती है।","explanationEn":"The Musi River historically divides Hyderabad into the old and new city.","memoryTip":"हैदराबाद की बिरयानी खाकर ''मूसी'' (मौसी) खुश हो गईं।","memoryTipEn":"Musi brings Music to Hyderabad.","related":["Krishna River","Charminar","Hussain Sagar Lake"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Ln4mZ2ULm9TsEHMz6dm-F', 'General Knowledge', 'विश्व में चांदी का सबसे बड़ा उत्पादक देश कौनसा है?', 'Which country is the largest producer of silver in the world?', 'मैक्सिको', 'Mexico', 85, 0, '{"facts":["मैक्सिको उत्तरी अमेरिका का एक देश है।","चांदी का रासायनिक प्रतीक ''Ag'' (Argentum) है।"],"factsEn":["Mexico is a country in North America.","The chemical symbol for silver is ''Ag'' (Argentum)."],"explanationHi":"मैक्सिको लंबे समय से चांदी के खनन में विश्व में प्रथम स्थान पर रहा है, विशेषकर जैकाटेकास (Zacatecas) क्षेत्र।","explanationEn":"Mexico has long been the world leader in silver mining, particularly the Zacatecas region.","memoryTip":"चांदी की ''मैक्सी'' (Mexico) पहनकर चमको।","memoryTipEn":"Max Silver in Mexico.","related":["Peru (Second largest producer)","Silver (Ag)","Precious Metals"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('S12eQipun08IIwb1LPL34', 'General Knowledge', 'क्षेत्रफल के अनुसार विश्व का सबसे छोटा देश कौनसा है?', 'Which is the smallest country in the world by area?', 'वैटिकन सिटी', 'Vatican City', 92, 0, '{"facts":["यह केवल 0.44 वर्ग किलोमीटर (110 एकड़) में फैला हुआ है।","यह इटली के रोम शहर के बीचो-बीच स्थित एक स्वतंत्र संप्रभु राज्य है।"],"factsEn":["It spans only 0.44 square kilometers (110 acres).","It is an independent sovereign state located entirely within the city of Rome, Italy."],"explanationHi":"यह कैथोलिक चर्च का आध्यात्मिक और प्रशासनिक केंद्र है और यहाँ पोप (Pope) का निवास है।","explanationEn":"It is the spiritual and administrative center of the Catholic Church and the residence of the Pope.","memoryTip":"सबसे छोटी ''सिटी'' = वैटिकन सिटी।","memoryTipEn":"Vatican is a tiny dot in Rome.","related":["Pope","Monaco (Second smallest)","Rome"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_VITwvOz7vLiJw2pxVw-Q', 'General Knowledge', 'स्वेज नहर किन दो सागरों को जोड़ती है?', 'The Suez Canal connects which two seas?', 'भूमध्यसागर और लाल सागर', 'Mediterranean Sea and Red Sea', 96, 0, '{"facts":["यह मिस्र (Egypt) में स्थित एक कृत्रिम समुद्र-स्तरीय जलमार्ग है।","इसे 1869 में आधिकारिक तौर पर खोला गया था।"],"factsEn":["It is an artificial sea-level waterway located in Egypt.","It was officially opened in 1869."],"explanationHi":"यह नहर यूरोप और एशिया के बीच की दूरी को बहुत कम कर देती है, जिससे जहाजों को अफ्रीका का चक्कर नहीं लगाना पड़ता।","explanationEn":"The canal vastly reduces the distance between Europe and Asia by allowing ships to avoid navigating around Africa.","memoryTip":"''भूल'' (भू-मध्य + लाल) से स्वेज नहर याद रखें।","memoryTipEn":"Suez Saves sailing around Africa.","related":["Panama Canal","Strait of Gibraltar","Egypt"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('abBigqVpnf7YqgzKcjPmW', 'General Knowledge', 'पनामा नहर किन दो महासागरों को जोड़ती है?', 'The Panama Canal connects which two oceans?', 'प्रशांत महासागर और उत्तरी अटलांटिक महासागर', 'Pacific Ocean and Atlantic Ocean', 95, 0, '{"facts":["यह मध्य अमेरिका के पनामा देश में स्थित है।","इस नहर में जहाजों को ऊपर उठाने और नीचे करने के लिए ''लॉक्स'' (Locks) का उपयोग किया जाता है।"],"factsEn":["It is located in the country of Panama in Central America.","The canal uses a system of ''locks'' to lift and lower ships."],"explanationHi":"यह नहर उत्तरी और दक्षिणी अमेरिका को अलग करती है और समुद्री व्यापार के लिए एक महत्वपूर्ण शॉर्टकट प्रदान करती है।","explanationEn":"The canal separates North and South America, providing a crucial shortcut for maritime trade.","memoryTip":"अटलांटिक की ''पा'' (प्रशांत) से पनामा में मुलाकात।","memoryTipEn":"Panama links the Pacific to the Atlantic.","related":["Suez Canal","Isthmus of Panama","Locks system"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Y1iTsxRWwgqbMgEOTqHUn', 'General Knowledge', 'भारत के संघीय क्षेत्र ''दादरा और नगर हवेली'' की राजधानी कौनसी है?', 'What is the capital of the Indian Union Territory ''Dadra and Nagar Haveli''?', 'सिल्वासा', 'Silvassa', 88, 0, '{"facts":["2020 में दादरा और नगर हवेली तथा दमन और दीव का विलय कर एक ही केंद्र शासित प्रदेश बना दिया गया है।","अब इस संयुक्त केंद्र शासित प्रदेश की राजधानी ''दमन'' (Daman) है।"],"factsEn":["In 2020, Dadra & Nagar Haveli and Daman & Diu were merged into a single Union Territory.","The capital of this newly merged UT is ''Daman''."],"explanationHi":"यह क्षेत्र 1954 तक पुर्तगाली शासन के अधीन था। (नोट: परीक्षा में पुराने संदर्भ में ''सिल्वासा'' उत्तर हो सकता है, लेकिन नया विलय याद रखें)।","explanationEn":"This territory was under Portuguese rule until 1954. (Note: Silvassa is the old capital; keep the new merger in mind).","memoryTip":"हवेली में ''सिल्वर'' (Silvassa) के बर्तन हैं।","memoryTipEn":"Silvassa was the silver lining of the Haveli.","related":["Daman and Diu","Union Territories","Portuguese India"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('y9m_STNXsKpT_glQaoMtN', 'General Knowledge', 'क्षेत्रफल की दृष्टि से भारत का सबसे बड़ा राज्य कौनसा है?', 'Which is the largest state in India in terms of area?', 'राजस्थान', 'Rajasthan', 94, 0, '{"facts":["वर्ष 2000 में मध्य प्रदेश से छत्तीसगढ़ के अलग होने के बाद राजस्थान सबसे बड़ा राज्य बना।","इसका क्षेत्रफल 3,42,239 वर्ग किलोमीटर है।"],"factsEn":["Rajasthan became the largest state after Chhattisgarh was carved out of Madhya Pradesh in 2000.","Its area is 342,239 square kilometers."],"explanationHi":"यह भारत के कुल भौगोलिक क्षेत्र का 10.4% हिस्सा कवर करता है और इसमें विशाल थार मरुस्थल शामिल है।","explanationEn":"It covers 10.4% of India''s total geographical area and encompasses the vast Thar Desert.","memoryTip":"सबसे बड़े ''स्थान'' पर ''राज'' (राजस्थान) चलता है।","memoryTipEn":"Raja''s sthan (King''s place) is the biggest.","related":["Madhya Pradesh (2nd Largest)","Goa (Smallest by area)","Thar Desert"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('pZXzF--U2DH4N8E8HxODP', 'General Knowledge', 'पृथ्वी दिवस (Earth Day) कब मनाया जाता है?', 'When is Earth Day celebrated?', '22 अप्रैल', '22 April', 95, 0, '{"facts":["इसकी शुरुआत 1970 में आधुनिक पर्यावरण आंदोलन को चिन्हित करने के लिए हुई थी।","विश्व जल दिवस 22 मार्च को मनाया जाता है।"],"factsEn":["It started in 1970 to mark the modern environmental movement.","World Water Day is celebrated on March 22."],"explanationHi":"यह पर्यावरण संरक्षण के लिए वैश्विक स्तर पर समर्थन प्रदर्शित करने का एक दिन है।","explanationEn":"It is a day to demonstrate support globally for environmental protection.","memoryTip":"22 अप्रैल को ''पृथ्वी'' की परवाह करो।","memoryTipEn":"April 22 -> Earth for you and me.","related":["World Environment Day (June 5)","World Water Day (March 22)","Gaylord Nelson"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wm2hQtKTLgeSCJ3nlKo2h', 'General Knowledge', 'फूलों की घाटी (Valley of Flowers) किस राज्य में है?', 'In which state is the Valley of Flowers located?', 'उत्तराखंड में', 'Uttarakhand', 91, 0, '{"facts":["यह चमोली जिले, गढ़वाल हिमालय में स्थित एक राष्ट्रीय उद्यान है।","इसे यूनेस्को (UNESCO) द्वारा विश्व धरोहर स्थल का दर्जा प्राप्त है।"],"factsEn":["It is a national park located in the Chamoli district, Garhwal Himalayas.","It is recognized as a UNESCO World Heritage Site."],"explanationHi":"यह क्षेत्र अपनी अल्पाइन (Alpine) फूलों की विविधता और उत्कृष्ट प्राकृतिक सुंदरता के लिए प्रसिद्ध है।","explanationEn":"The region is renowned for its meadows of endemic alpine flowers and outstanding natural beauty.","memoryTip":"''उत्तरा'' हिमालय की ''घाटी'' में फूल चुनती है।","memoryTipEn":"Uttarakhand unfolds the valley of flora.","related":["Nanda Devi National Park","UNESCO Heritage Sites","Chamoli"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uUfHfOeglb28EZC1jmmhs', 'General Knowledge', 'वर्ष 2011 में नवनिर्मित राष्ट्र दक्षिणी सूडान की राजधानी कौनसी है?', 'What is the capital of the newly formed nation (in 2011) South Sudan?', 'जूबा', 'Juba', 88, 0, '{"facts":["यह संयुक्त राष्ट्र (UN) का 193वां सदस्य देश है।","यह अफ्रीका महाद्वीप में स्थित एक भूमि से घिरा (Landlocked) देश है।"],"factsEn":["It is the 193rd member state of the United Nations.","It is a landlocked country located in the continent of Africa."],"explanationHi":"दशकों के गृह युद्ध के बाद यह सूडान से अलग होकर एक स्वतंत्र देश बना था।","explanationEn":"It became an independent country, seceding from Sudan, after decades of civil war.","memoryTip":"सूडान से अलग होकर ''जूबा'' (अजूबा) देश बना।","memoryTipEn":"South Sudan Jumps to Juba.","related":["Sudan (Khartoum)","United Nations 193rd member","Landlocked Countries"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aZKcO1_8jIUBdcflIXa-z', 'General Knowledge', 'योजना आयोग (Planning Commission) का अध्यक्ष कौन होता है?', 'Who is the Chairman of the Planning Commission?', 'प्रधानमंत्री', 'Prime Minister', 92, 0, '{"facts":["1 जनवरी 2015 को योजना आयोग को ''नीति आयोग'' (NITI Aayog) से बदल दिया गया।","नीति आयोग के अध्यक्ष भी भारत के प्रधानमंत्री ही होते हैं।"],"factsEn":["On Jan 1, 2015, the Planning Commission was replaced by ''NITI Aayog''.","The Chairperson of NITI Aayog is also the Prime Minister of India."],"explanationHi":"योजना आयोग भारत सरकार की वह संस्था थी जिसने पंचवर्षीय योजनाएँ बनाई थीं।","explanationEn":"The Planning Commission was the institution in the Government of India that formulated Five-Year Plans.","memoryTip":"देश की ''नीति'' और ''योजना'' प्रधानमंत्री बनाते हैं।","memoryTipEn":"PM Plans the Nation.","related":["NITI Aayog","Five-Year Plans","National Development Council"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_6T3XuzsZ2DV6XC9pxeFO', 'General Knowledge', 'आईने अकबरी का लेखक कौन था?', 'Who was the author of Ain-i-Akbari?', 'अबुल फजल', 'Abul Fazl', 93, 0, '{"facts":["यह ''अकबरनामा'' नामक तीन खंडों वाली बड़ी पुस्तक का तीसरा खंड है।","अबुल फजल अकबर के नवरत्नों में से एक थे।"],"factsEn":["It is the third volume of a larger, three-volume work known as the ''Akbarnama''.","Abul Fazl was one of the Navaratnas (Nine Jewels) of Akbar."],"explanationHi":"यह एक 16वीं शताब्दी का विस्तृत दस्तावेज़ है जिसमें सम्राट अकबर के साम्राज्य के प्रशासन की जानकारी है।","explanationEn":"It is a detailed 16th-century document recording the administration of Emperor Akbar''s empire.","memoryTip":"''फजल'' ने अकबर के प्रशासन का ''आईना'' दिखाया।","memoryTipEn":"Fazl focused on Akbar''s facts.","related":["Akbarnama","Navaratnas","Mughal Administration"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-vywWNvVmgyywBWNftWqb', 'General Knowledge', 'होपमेन कप (Hopman Cup) किस खेल से सम्बंधित है?', 'Hopman Cup is associated with which sport?', 'टेनिस', 'Tennis', 86, 0, '{"facts":["यह एक वार्षिक अंतर्राष्ट्रीय इनडोर हार्डकोर्ट टेनिस टूर्नामेंट है।","इसमें देशों का प्रतिनिधित्व करने वाली मिश्रित लिंग (Mixed-gender) टीमें भाग लेती हैं।"],"factsEn":["It is an annual international indoor hardcourt tennis tournament.","It features mixed-gender teams representing countries."],"explanationHi":"इसे प्रसिद्ध ऑस्ट्रेलियाई टेनिस खिलाड़ी ''हैरी होपमैन'' के नाम पर शुरू किया गया था।","explanationEn":"It was launched in honor of the renowned Australian tennis player ''Harry Hopman''.","memoryTip":"टेनिस में जीतने की ''होप'' (Hopman) हर खिलाड़ी को होती है।","memoryTipEn":"Hoping to win the Tennis match.","related":["Davis Cup","Fed Cup (Billie Jean King Cup)","Grand Slam"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8BTycF84PBAqJErhXA4oo', 'General Knowledge', 'देशबंधु के नाम से कौन जाने जाते है?', 'Who is known as ''Deshbandhu''?', 'चितरंजन दास (सी. आर. दास)', 'Chittaranjan Das (C.R. Das)', 91, 0, '{"facts":["इन्होंने मोतीलाल नेहरू के साथ मिलकर ''स्वराज पार्टी'' (1923) की स्थापना की थी।","''देशबंधु'' का अर्थ होता है ''राष्ट्र का मित्र'' (Friend of the Nation)।"],"factsEn":["He founded the ''Swaraj Party'' (1923) along with Motilal Nehru.","''Deshbandhu'' means ''Friend of the Nation''."],"explanationHi":"भारतीय स्वतंत्रता आंदोलन के दौरान उनके त्याग और गरीबों के लिए मुफ़्त कानूनी वकालत के कारण उन्हें यह उपाधि दी गई थी।","explanationEn":"He was given this title during the Indian freedom movement for his sacrifices and free legal advocacy for the poor.","memoryTip":"देश के ''दास'' बनकर ''बंधु'' बन गए = देशबंधु सी. आर. दास।","memoryTipEn":"Deshbandhu is a friend (Das).","related":["Swaraj Party","Dinbandhu (C.F. Andrews)","Motilal Nehru"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('y-450jmykFTuWBK88XwrJ', 'General Knowledge', 'अशोक चक्र मे कितनी तिलियां (Spokes) होती हैं?', 'How many spokes are there in the Ashoka Chakra?', '24', '24', 95, 0, '{"facts":["यह भारत के राष्ट्रीय ध्वज के मध्य में नेवी ब्लू (Navy Blue) रंग में स्थित है।","इसे सम्राट अशोक के ''सारनाथ सिंह स्तंभ'' (Lion Capital of Ashoka) से लिया गया है।"],"factsEn":["It is situated in the center of the Indian national flag in Navy Blue color.","It is adopted from the ''Lion Capital of Ashoka'' at Sarnath."],"explanationHi":"अशोक चक्र की 24 तीलियाँ दिन के 24 घंटों और जीवन की निरंतर गतिशीलता (प्रगति) का प्रतीक हैं।","explanationEn":"The 24 spokes represent the 24 hours of the day and the continuous motion (progress) of life.","memoryTip":"24 घंटे देश प्रगति के ''चक्र'' पर चले।","memoryTipEn":"24 spokes for 24 hours of progress.","related":["National Flag of India","Lion Capital of Ashoka","Dharma Chakra"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nqsfBvZpeN4j3_yBkgzU8', 'General Knowledge', 'भारत में सबसे पहली फिल्म कौन सी बनी?', 'Which was the first film made in India?', 'राजा हरिश्चन्द्र', 'Raja Harishchandra', 92, 0, '{"facts":["यह 1913 में रिलीज़ हुई एक मूक (Silent) फिल्म थी।","इसके निर्माता-निर्देशक दादा साहेब फाल्के थे।"],"factsEn":["It was a silent film released in 1913.","Its producer-director was Dadasaheb Phalke."],"explanationHi":"यह एक पूर्ण लंबाई वाली पहली भारतीय फीचर फिल्म थी, जिसमें सत्यवादी राजा हरिश्चंद्र की कहानी दिखाई गई थी।","explanationEn":"It was the first full-length Indian feature film, depicting the story of the truthful King Harishchandra.","memoryTip":"सिनेमा की दुनिया में सबसे पहला ''राजा'' हरिश्चन्द्र था।","memoryTipEn":"First film featured the truthful King.","related":["Alam Ara (First Talkie)","Dadasaheb Phalke","Indian Cinema History"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dJHnUNYn5WbzSgwWAE3ve', 'General Science', 'सबसे छोटी हड्डी कौनसी है?', 'Which is the smallest bone in the human body?', 'स्टेपीज़ (Stapes)', 'Stapes', 96, 0, '{"facts":["यह मनुष्य के मध्य कान (Middle Ear) में स्थित होती है।","कान की अन्य दो हड्डियां मैलियस (Malleus) और इनकस (Incus) हैं।"],"factsEn":["It is located in the middle ear of humans.","The other two bones of the ear are the Malleus and Incus."],"explanationHi":"यह हड्डी एक घोड़े की रकाब (Stirrup) के आकार की होती है और ध्वनि तरंगों को आंतरिक कान तक पहुँचाती है।","explanationEn":"This bone is shaped like a horse''s stirrup and transmits sound waves to the inner ear.","memoryTip":"कान में ''टेप'' (स्टेपीज़) सबसे छोटा होता है।","memoryTipEn":"Stapes is the tiniest stepping stone for sound.","related":["Femur (Largest Bone)","Middle Ear","Ossicles"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_dcdnkRC1LWVmajFqWxwJ', 'General Science', 'सबसे बड़ी हड्डी कौनसी है?', 'Which is the largest (and longest) bone in the human body?', 'फीमर (जांघ की हड्डी)', 'Femur (Thigh bone)', 97, 0, '{"facts":["यह न केवल सबसे बड़ी, बल्कि शरीर की सबसे भारी और मजबूत हड्डी भी है।","यह कूल्हे (Hip) से लेकर घुटने (Knee) तक होती है।"],"factsEn":["It is not only the largest but also the heaviest and strongest bone in the body.","It extends from the hip to the knee."],"explanationHi":"यह हमारे शरीर के अधिकांश वजन को सहन करती है और चलने-दौड़ने में सहायता करती है।","explanationEn":"It supports most of our body weight and facilitates walking and running.","memoryTip":"फीमर (फ्रेम) शरीर का सबसे बड़ा फ्रेम है।","memoryTipEn":"Femur forms the foundation of legs.","related":["Stapes (Smallest Bone)","Tibia","Human Skeleton System"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8wMVyDoKPPWrHZ1Mg5O1b', 'General Science', 'मानव शरीर में कितनी पेशियाँ (Muscles) हैं?', 'How many muscles are there in the human body?', '639', '639', 90, 0, '{"facts":["हमारे शरीर का लगभग 40-50% वजन मांसपेशियों का होता है।","सबसे बड़ी मांसपेशी ग्लूटस मैक्सिमस (Gluteus Maximus) है।"],"factsEn":["Muscles make up about 40-50% of our body weight.","The largest muscle is the Gluteus Maximus."],"explanationHi":"मांसपेशियां शरीर की गतिविधियों, मुद्रा बनाए रखने और रक्त संचारण में मदद करती हैं।","explanationEn":"Muscles help in body movements, maintaining posture, and blood circulation.","memoryTip":"6-3-9 (छह, तीन, नौ) पेशियां शरीर को चलाती हैं।","memoryTipEn":"639 -> Muscles intertwine.","related":["Gluteus Maximus","Stapedius (Smallest muscle)","Skeletal System"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ASX43XxbebcDqgx64pC4i', 'General Science', 'लाल रक्त कणिका (RBC) का जीवनकाल कितना होता है?', 'What is the lifespan of Red Blood Cells (RBCs)?', '120 दिन', '120 days', 95, 0, '{"facts":["लाल रक्त कणिकाओं का मुख्य कार्य शरीर में ऑक्सीजन पहुंचाना है।","इनका निर्माण अस्थि मज्जा (Bone Marrow) में होता है और प्लीहा (Spleen) में नष्ट होती हैं।"],"factsEn":["The main function of RBCs is to transport oxygen in the body.","They are formed in the Bone Marrow and destroyed in the Spleen."],"explanationHi":"लगभग 4 महीने (120 दिन) काम करने के बाद पुरानी कोशिकाएँ नष्ट हो जाती हैं और नई कोशिकाएँ उनकी जगह ले लेती हैं।","explanationEn":"After functioning for about 4 months (120 days), old cells are destroyed and replaced by new ones.","memoryTip":"खून को 4 महीने (120 दिन) में नया जीवन मिलता है।","memoryTipEn":"120 days of carrying oxygen.","related":["White Blood Cells (WBC Lifespan: 13-20 days)","Erythrocytes","Spleen"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DbPfl6Dq9kUWzJugMnUtt', 'General Science', 'जंग लगने से बचाने के लिए लोहे पर जस्ते की परत चढ़ाने की क्रिया को क्या कहते हैं?', 'What is the process of applying a protective zinc coating to iron to prevent rusting called?', 'जस्तीकरण या गेल्वेनाइजेशन (Galvanization)', 'Galvanization', 94, 0, '{"facts":["इसमें जस्ता (Zinc) धातु का उपयोग किया जाता है।","जस्ते की परत लोहे को नमी और ऑक्सीजन के सीधे संपर्क में आने से रोकती है।"],"factsEn":["Zinc metal is used in this process.","The zinc layer prevents iron from coming into direct contact with moisture and oxygen."],"explanationHi":"चूंकि जिंक लोहे की तुलना में अधिक प्रतिक्रियाशील है, यह लोहे के क्षरण (Corrosion) से पहले खुद ऑक्सीकृत हो जाता है (Galvanic protection)।","explanationEn":"Since zinc is more reactive than iron, it oxidizes itself before the iron corrodes (Galvanic protection).","memoryTip":"''जस्ते'' की परत चढ़ाना मतलब ''जस्तीकरण''।","memoryTipEn":"Galvanization gives zinc armor.","related":["Corrosion","Zinc (Zn)","Rust (Iron Oxide)"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('T2mSquIZd0vr5W1HsrI1h', 'General Science', 'मानव शरीर की सबसे बड़ी ग्रंथि (Gland) का नाम क्या है?', 'What is the name of the largest gland in the human body?', 'यकृत (Liver)', 'Liver', 96, 0, '{"facts":["यकृत शरीर का सबसे बड़ा आंतरिक अंग भी है (त्वचा के बाद)।","यह पित्त (Bile) का निर्माण करता है, जो वसा के पाचन में मदद करता है।"],"factsEn":["The liver is also the largest internal organ in the body (after the skin).","It produces bile, which helps in the digestion of fats."],"explanationHi":"यकृत रक्त से विषाक्त पदार्थों (Toxins) को बाहर निकालने और पोषक तत्वों के चयापचय (Metabolism) का एक प्रमुख कार्य करता है।","explanationEn":"The liver plays a major role in detoxifying chemicals from the blood and metabolizing nutrients.","memoryTip":"जो ''लीव'' (जिंदा) रखे, वो लीवर (सबसे बड़ी ग्रंथि)।","memoryTipEn":"Liver is large for life.","related":["Bile Juice","Pancreas","Hepatitis"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2k6uqjqUmBX-HUZA0zNRy', 'General Knowledge', 'भारत का प्रथम तेल शोधन संयंत्र (Oil Refinery) कहां पर स्थित है?', 'Where is the first oil refinery of India located?', 'डिगबोई (असोम)', 'Digboi (Assam)', 91, 0, '{"facts":["यह 1901 में शुरू की गई थी और एशिया की सबसे पुरानी चालू रिफाइनरी है।","डिगबोई को भारत की ''ऑयल सिटी'' (Oil City) भी कहा जाता है।"],"factsEn":["It was commissioned in 1901 and is Asia''s oldest operating refinery.","Digboi is also known as the ''Oil City'' of India."],"explanationHi":"अंग्रेजों ने असम में चाय के बागानों के पास रेलवे ट्रैक बिछाते समय संयोग से तेल की खोज की थी।","explanationEn":"The British accidentally discovered oil in Assam while laying a railway track near tea estates.","memoryTip":"तेल ''डिग'' (Dig) करके ''बोई'' (Boy) ने निकाला = डिगबोई।","memoryTipEn":"Dig-Boy Digs for Oil.","related":["Assam","Petroleum","ONGC"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zdk-tCCz06zQfo8gq0sho', 'General Knowledge', 'UNESCO द्वारा कलिंग पुरस्कार किस क्षेत्र के लिए दिया जाता है?', 'For which field is the Kalinga Prize awarded by UNESCO?', 'विज्ञान के क्षेत्र में (विज्ञान संचार हेतु)', 'In the field of Science (for Science Popularization)', 92, 0, '{"facts":["इसकी स्थापना 1952 में भारत के कलिंग फाउंडेशन ट्रस्ट (बीजू पटनायक) के दान से हुई थी।","यह विज्ञान को आम लोगों तक पहुँचाने (Popularization of Science) के लिए दिया जाता है।"],"factsEn":["It was created in 1952 by a donation from the Kalinga Foundation Trust of India (Biju Patnaik).","It is awarded for the popularization of science among the common people."],"explanationHi":"यह अंतर्राष्ट्रीय पुरस्कार उन लोगों को मान्यता देता है जो लेखकों, संपादकों या वक्ताओं के रूप में विज्ञान को लोकप्रिय बनाते हैं।","explanationEn":"This international award recognizes individuals who popularize science as writers, editors, or speakers.","memoryTip":"विज्ञान के ''कलिंग'' (कौशल) को सम्मानित किया जाता है।","memoryTipEn":"Kalinga conveys science to the public.","related":["Biju Patnaik","UNESCO Awards","Shanti Swarup Bhatnagar Prize"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FpbK00k-I82hM6VZ5wiWL', 'General Knowledge', 'हैदराबाद में चार मीनार का निर्माण किसने करवाया?', 'Who built the Charminar in Hyderabad?', 'कुली कुतुबशाह', 'Muhammad Quli Qutb Shah', 93, 0, '{"facts":["इसे 1591 ई. में बनवाया गया था।","यह गोलकुंडा से राजधानी को हैदराबाद स्थानांतरित करने के बाद बनवाई गई थी।"],"factsEn":["It was built in 1591 AD.","It was constructed after the capital was moved from Golconda to Hyderabad."],"explanationHi":"ऐतिहासिक मान्यताओं के अनुसार इसे शहर से प्लेग महामारी के उन्मूलन का जश्न मनाने के लिए बनवाया गया था।","explanationEn":"According to historical beliefs, it was built to celebrate the eradication of the plague epidemic from the city.","memoryTip":"चार मीनार खड़े करने के लिए ''कुली'' की मेहनत लगी (कुली कुतुबशाह)।","memoryTipEn":"Quli Qutb raised the four minarets.","related":["Qutb Shahi Dynasty","Hyderabad","Plague Eradication"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AtDo8D_32VWrd1AlnO9BW', 'General Knowledge', 'कांग्रेस द्वारा पूर्ण स्वाधीनता (Purna Swaraj) का प्रस्ताव कब और कहाँ पारित किया गया?', 'When and where was the resolution of ''Purna Swaraj'' (Complete Independence) passed by the Congress?', 'सन 1929 के लाहौर अधिवेशन में', 'In the 1929 Lahore Session', 97, 0, '{"facts":["इस ऐतिहासिक अधिवेशन की अध्यक्षता जवाहरलाल नेहरू ने की थी।","इसी अधिवेशन में 26 जनवरी 1930 को प्रथम ''स्वतंत्रता दिवस'' मनाने का निर्णय लिया गया।"],"factsEn":["This historic session was presided over by Jawaharlal Nehru.","In this session, it was decided to celebrate Jan 26, 1930, as the first ''Independence Day''."],"explanationHi":"यह वह क्षण था जब कांग्रेस ने अपना लक्ष्य ''डोमिनियन स्टेटस'' से बदलकर ''पूर्ण स्वतंत्रता'' कर लिया।","explanationEn":"This was the moment when Congress shifted its goal from ''Dominion Status'' to ''Complete Independence''.","memoryTip":"29 में ''लाहौर'' में गूंजी ''पूर्ण'' आज़ादी की लहर।","memoryTipEn":"1929 Lahore declared total freedom.","related":["Jawaharlal Nehru","Republic Day (Jan 26)","Ravi River"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MdsukCiizwFLN0VdDLqBF', 'General Knowledge', 'श्वेत क्रांति (White Revolution) का सम्बन्ध किस से है?', 'The White Revolution is related to what?', 'दूध से', 'Milk', 94, 0, '{"facts":["इसे ''ऑपरेशन फ्लड'' (Operation Flood) के नाम से भी जाना जाता है।","डॉ. वर्गीज कुरियन को भारत में श्वेत क्रांति का जनक माना जाता है।"],"factsEn":["It is also known as ''Operation Flood''.","Dr. Verghese Kurien is considered the father of the White Revolution in India."],"explanationHi":"इस कार्यक्रम ने भारत को एक दूध की कमी वाले देश से दुनिया के सबसे बड़े दुग्ध उत्पादक देश में बदल दिया।","explanationEn":"This program transformed India from a milk-deficient nation into the world''s largest milk producer.","memoryTip":"दूध ''श्वेत'' (सफेद) होता है।","memoryTipEn":"White as milk.","related":["Dr. Verghese Kurien","Operation Flood","Amul"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('M4ddsujj0aMdq1mLwRvvP', 'General Knowledge', 'भारत का सबसे पुराना चालू रेल इंजन कौन सा है?', 'Which is the oldest working railway locomotive in India (and the world)?', 'फेयरी क्वीन (Fairy Queen)', 'Fairy Queen', 86, 0, '{"facts":["यह एक भाप इंजन (Steam Locomotive) है जिसे 1855 में बनाया गया था।","इसे गिनीज़ बुक ऑफ़ वर्ल्ड रिकॉर्ड्स में भी सबसे पुराना चालू इंजन दर्ज किया गया है।"],"factsEn":["It is a steam locomotive built in 1855.","It is listed in the Guinness Book of World Records as the oldest working steam locomotive."],"explanationHi":"यह ऐतिहासिक इंजन आज भी पर्यटकों के लिए विशेष मौकों पर नई दिल्ली और अलवर के बीच चलाया जाता है।","explanationEn":"This historical engine is still run on special occasions for tourists between New Delhi and Alwar.","memoryTip":"रेल की ''क्वीन'' (रानी) सबसे पुरानी है।","memoryTipEn":"Fairy Queen rules the old tracks.","related":["Steam Engine","Indian Railways History","Rewari Railway Heritage Museum"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Mnac9tQgR0wi6KV9MNTH9', 'General Knowledge', 'भारत में आपातकाल (National Emergency) की प्रथम घोषणा कब की गई?', 'When was the first declaration of National Emergency made in India?', 'चीनी आक्रमण के समय (26 अक्टूबर 1962)', 'During the Chinese aggression (October 26, 1962)', 95, 0, '{"facts":["यह आपातकाल 1962 से 1968 तक लागू रहा।","उस समय भारत के राष्ट्रपति डॉ. सर्वपल्ली राधाकृष्णन और प्रधानमंत्री जवाहरलाल नेहरू थे।"],"factsEn":["This emergency remained in force from 1962 to 1968.","At that time, Dr. S. Radhakrishnan was the President and Jawaharlal Nehru was the PM."],"explanationHi":"संविधान के अनुच्छेद 352 के तहत ''बाह्य आक्रमण'' (External Aggression) के आधार पर पहली बार राष्ट्रीय आपातकाल लगाया गया था।","explanationEn":"Under Article 352, the national emergency was declared for the first time on the grounds of ''External Aggression''.","memoryTip":"1962 के युद्ध ने देश में पहली बार ''आपात'' स्थिति ला दी।","memoryTipEn":"1962 war sparked the first Emergency.","related":["Article 352","Sino-Indian War 1962","Indo-Pak War 1971 (2nd Emergency)"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Sp9FJ9KopMgg35aZ3SBYB', 'General Knowledge', 'भारत में भाषा के आधार बनने वाला पहला राज्य कौनसा है?', 'Which was the first state in India created on a linguistic basis?', 'आंध्रप्रदेश', 'Andhra Pradesh', 96, 0, '{"facts":["इसका गठन 1 अक्टूबर 1953 को हुआ था।","तेलुगु भाषी लोगों के लिए मद्रास राज्य से अलग करके इसे बनाया गया था।"],"factsEn":["It was formed on October 1, 1953.","It was carved out of Madras State for Telugu-speaking people."],"explanationHi":"पोट्टी श्रीरामुलु के 56 दिन के अनशन और मृत्यु के बाद भाषाई आधार पर इस राज्य की स्थापना को मंजूरी मिली।","explanationEn":"The state''s creation on linguistic lines was approved after the 56-day fast and death of Potti Sreeramulu.","memoryTip":"''आँधी'' की तरह सबसे पहले भाषा के नाम पर बना (आंध्रप्रदेश)।","memoryTipEn":"Andhra spoke Telugu first.","related":["States Reorganisation Act, 1956","Telugu Language","Potti Sreeramulu"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dJFGjnoAbd644_s2oOazB', 'General Knowledge', 'भारत पर हमला करने वाला प्रथम मुस्लिम आक्रमणकारी कौन था?', 'Who was the first Muslim invader to attack India?', 'मुहम्मद बिन कासिम (712 ई.)', 'Muhammad bin Qasim (712 AD)', 92, 0, '{"facts":["उसने 712 ईस्वी में सिंध प्रांत पर आक्रमण किया था।","उस समय सिंध का शासक राजा दाहिर था।"],"factsEn":["He invaded the Sindh province in 712 AD.","At that time, the ruler of Sindh was King Dahir."],"explanationHi":"मुहम्मद बिन कासिम के सफल आक्रमण ने भारतीय उपमहाद्वीप में इस्लामी शासन की नींव रखी थी।","explanationEn":"Muhammad bin Qasim''s successful invasion laid the foundation of Islamic rule in the Indian subcontinent.","memoryTip":"712 में ''कासिम'' ने सिंध की ''कसम'' खाई।","memoryTipEn":"Qasim conquered Sindh in 712.","related":["King Dahir","Sindh","Mahmud of Ghazni"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gBWZtLakbMwqdOQNF7TGh', 'General Knowledge', 'सेल्यूकस का राजदूत जो चंद्रगुप्त मौर्य के दरबार में आया, कौन था?', 'Who was the ambassador of Seleucus who came to the court of Chandragupta Maurya?', 'मैग्स्थनीज', 'Megasthenes', 95, 0, '{"facts":["उसने भारत के बारे में ''इंडिका'' (Indica) नामक एक प्रसिद्ध पुस्तक लिखी।","मैग्स्थनीज एक यूनानी (ग्रीक) इतिहासकार और राजनयिक था।"],"factsEn":["He wrote a famous book about India called ''Indica''.","Megasthenes was a Greek historian and diplomat."],"explanationHi":"उसकी पुस्तक ''इंडिका'' प्राचीन भारत (मौर्य साम्राज्य) के प्रशासन, समाज और भूगोल को समझने का एक प्रमुख स्रोत है।","explanationEn":"His book ''Indica'' is a primary source for understanding the administration, society, and geography of ancient India (Mauryan Empire).","memoryTip":"मौर्य दरबार में ग्रीक ''गेस्ट'' (मेगास्थनीज) आया।","memoryTipEn":"Megasthenes mapped the Mauryans in Indica.","related":["Indica","Seleucus Nicator","Chandragupta Maurya"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('j29VNGklijqHWa7VKOmot', 'General Knowledge', 'श्रीलंका का पुराना नाम क्या है?', 'What is the old name of Sri Lanka?', 'सिलोन (Ceylon)', 'Ceylon', 88, 0, '{"facts":["1972 में इसका नाम बदलकर ''लंका'' और 1978 में ''श्रीलंका'' कर दिया गया।","यह हिंद महासागर में स्थित एक द्वीप राष्ट्र है।"],"factsEn":["It was renamed ''Lanka'' in 1972 and ''Sri Lanka'' in 1978.","It is an island nation located in the Indian Ocean."],"explanationHi":"ब्रिटिश शासन के दौरान इसे सिलोन के नाम से जाना जाता था, और आज भी यहाँ की ''सीलोन चाय'' दुनिया भर में प्रसिद्ध है।","explanationEn":"Under British rule, it was known as Ceylon, and ''Ceylon Tea'' remains world-famous today.","memoryTip":"श्रीलंका में ''सिलोन'' (चाय) मिलती है।","memoryTipEn":"Ceylon sails to Sri Lanka.","related":["Ceylon Tea","Palk Strait","Jayawardenepura Kotte"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jwzEGt7nrBiC3d5wgkJxH', 'General Science', 'विटामिन्स की खोज किसने की?', 'Who discovered Vitamins?', 'कैसिमिर फंक ने (C. Funk)', 'Casimir Funk', 91, 0, '{"facts":["फंक ने 1912 में सबसे पहले ''विटामिन'' (Vitamin) शब्द का प्रयोग किया था।","उनका यह शब्द ''Vital'' (जीवन के लिए आवश्यक) और ''Amine'' से मिलकर बना था।"],"factsEn":["Funk first coined the term ''Vitamin'' in 1912.","The word was a combination of ''Vital'' (essential for life) and ''Amine''."],"explanationHi":"फंक ने यह सिद्धांत दिया कि कुछ बीमारियों (जैसे बेरी-बेरी और स्कर्वी) का कारण विशिष्ट पोषक तत्वों की कमी है।","explanationEn":"Funk theorized that certain diseases (like Beri-Beri and Scurvy) are caused by a lack of specific nutrients.","memoryTip":"विटामिन खाओगे तो ''फंक'' (स्फूर्ति) में रहोगे।","memoryTipEn":"Funk found the vital vitamins.","related":["Vital Amines","Beri-Beri","Nutrition Science"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YDsS_4W2B6BvHlusHk7kH', 'General Science', 'स्टेनलेस स्टील (Stainless Steel) किसकी मिश्र धातु होती है?', 'Stainless Steel is an alloy of which elements?', 'आयरन, क्रोमियम, निकिल', 'Iron, Chromium, Nickel', 95, 0, '{"facts":["इसमें जंग को रोकने के लिए कम से कम 10.5% क्रोमियम (Chromium) मिलाया जाता है।","निकिल (Nickel) इसे मजबूती और चमक प्रदान करता है।"],"factsEn":["It contains at least 10.5% Chromium to prevent rusting.","Nickel adds strength and a shiny finish to it."],"explanationHi":"यह लोहे का एक ऐसा रूप है जिसमें आसानी से जंग (Rust) नहीं लगता, इसलिए इसका उपयोग बर्तन और सर्जिकल उपकरण बनाने में होता है।","explanationEn":"It is a form of iron that does not rust easily, making it ideal for making utensils and surgical instruments.","memoryTip":"लोहे को ''क्रोम'' (चमक) और ''निकिल'' ने मिलकर ''स्टेनलेस'' कर दिया।","memoryTipEn":"Iron + Chrome makes it shine.","related":["Rusting","Chromium","Alloys"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vMyo0l5zO4Xp6nMgxWLYk', 'General Science', 'कांसा (Bronze) किसकी मिश्र धातु होती है?', 'Bronze is an alloy of which metals?', 'कॉपर (तांबा) तथा टिन', 'Copper and Tin', 93, 0, '{"facts":["कांस्य युग (Bronze Age) में यह मानव द्वारा बड़े पैमाने पर उपयोग किया जाने वाला पहला कठोर मिश्र धातु था।","पीतल (Brass) में तांबे के साथ जस्ता (Zinc) होता है, जबकि कांसे में टिन होता है।"],"factsEn":["During the Bronze Age, it was the first hard alloy widely used by humans.","Brass has Zinc with Copper, whereas Bronze has Tin."],"explanationHi":"कांसे का उपयोग मूर्तियां, पदक (Bronze Medals) और घंटियां (Bells) बनाने में किया जाता है।","explanationEn":"Bronze is used to make statues, medals (Bronze Medals), and bells.","memoryTip":"कांसा (Bronze) में टिन ''टन-टन'' बजता है।","memoryTipEn":"Bronze = Cu + Sn (Tin).","related":["Brass","Bronze Age","Alloys"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xBzsS_eI79gm6XIx2Xr-w', 'General Knowledge', 'स्वामी विवेकानंद ने शिकागो में हुए विश्व धर्म सम्मेलन को कब संबोधित किया?', 'When did Swami Vivekananda address the World Parliament of Religions in Chicago?', '1893 में', 'In 1893', 95, 0, '{"facts":["उन्होंने अपने भाषण की शुरुआत \"मेरे अमेरिकी भाइयो और बहनो\" से की थी।","इस भाषण ने पश्चिमी दुनिया को हिंदू धर्म और वेदांत दर्शन से परिचित कराया।"],"factsEn":["He began his speech with \"Sisters and Brothers of America\".","This speech introduced Hinduism and Vedanta philosophy to the Western world."],"explanationHi":"उनके इस ऐतिहासिक भाषण ने उन्हें रातों-रात एक प्रसिद्ध वैश्विक आध्यात्मिक नेता बना दिया था।","explanationEn":"His historic speech made him a globally renowned spiritual leader overnight.","memoryTip":"18-93 में विवेकानंद ने दुनिया को ''ज्ञान'' दिया।","memoryTipEn":"1893: The year Vedanta echoed in Chicago.","related":["World Parliament of Religions","Ramakrishna Mission","Vedanta Philosophy"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CnqCStWk9gJIdhZAER2fG', 'General Knowledge', 'जलियांवाला बाग हत्याकांड कब हुआ?', 'When did the Jallianwala Bagh massacre take place?', '13 अप्रैल 1919', '13 April 1919', 98, 0, '{"facts":["यह घटना अमृतसर (पंजाब) में बैसाखी के दिन हुई थी।","निहत्थी भीड़ पर गोलियां चलाने का आदेश जनरल डायर ने दिया था।"],"factsEn":["This incident occurred in Amritsar (Punjab) on the day of Baisakhi.","General Dyer ordered the firing on the unarmed crowd."],"explanationHi":"लोग रॉलेट एक्ट (Rowlatt Act) और दो लोकप्रिय नेताओं की गिरफ्तारी का शांतिपूर्ण विरोध करने के लिए वहां जमा हुए थे।","explanationEn":"People had gathered there to peacefully protest against the Rowlatt Act and the arrest of two popular leaders.","memoryTip":"1919 में बैसाखी (13 अप्रैल) खून से लाल हो गई।","memoryTipEn":"April 13, 1919 - A dark day in Amritsar.","related":["Rowlatt Act","General Dyer","Hunter Commission"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0fYFGpP_0BTZqh-Y3uatN', 'General Knowledge', 'पृथ्वी पर उत्तरी गोलार्ध (Northern Hemisphere) में सबसे बड़ा दिन कब होता है?', 'When is the longest day in the Northern Hemisphere on Earth?', '21 जून', '21 June', 93, 0, '{"facts":["इसे ग्रीष्म अयनांत (Summer Solstice) कहा जाता है।","21 जून को विश्व योग दिवस (International Day of Yoga) भी मनाया जाता है।"],"factsEn":["It is called the Summer Solstice.","June 21 is also celebrated as the International Day of Yoga."],"explanationHi":"इस दिन सूर्य की किरणें कर्क रेखा (Tropic of Cancer) पर सीधी पड़ती हैं, जिससे उत्तरी गोलार्ध में दिन सबसे लंबा होता है।","explanationEn":"On this day, the sun''s rays fall directly on the Tropic of Cancer, resulting in the longest day in the Northern Hemisphere.","memoryTip":"21 जून को योग करो, क्योंकि दिन सबसे लंबा है।","memoryTipEn":"June 21 has the most Sun.","related":["Summer Solstice","Tropic of Cancer","Winter Solstice (Dec 22)"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YR8NC1IapaH7qDpC3C0EO', 'General Knowledge', 'महात्मा बुद्ध ने अपना पहला उपदेश कहाँ दिया था?', 'Where did Mahatma Buddha give his first sermon?', 'सारनाथ', 'Sarnath', 96, 0, '{"facts":["सारनाथ उत्तर प्रदेश में वाराणसी (बनारस) के पास स्थित है।","उनके पहले उपदेश की इस घटना को बौद्ध धर्म में ''धर्मचक्रप्रवर्तन'' कहा जाता है।"],"factsEn":["Sarnath is located near Varanasi (Banaras) in Uttar Pradesh.","The event of his first sermon is called ''Dharmachakra Pravartana'' in Buddhism."],"explanationHi":"ज्ञान प्राप्ति (बोधगया) के बाद, बुद्ध ने अपने पहले पांच शिष्यों को सारनाथ में ''चार आर्य सत्य'' (Four Noble Truths) का उपदेश दिया।","explanationEn":"After attaining enlightenment (Bodh Gaya), Buddha preached the ''Four Noble Truths'' to his first five disciples in Sarnath.","memoryTip":"ज्ञान का ''सार'' बुद्ध ने ''सार''नाथ में दिया।","memoryTipEn":"Sarnath spread the essence (Sar) of Buddhism.","related":["Dharmachakra Pravartana","Four Noble Truths","Bodh Gaya"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('leGMlRk2pqtlCFF1aKJjz', 'General Knowledge', 'साइमन कमीशन के बहिष्कार के दौरान लाठी चार्ज से किस नेता की मृत्यु हो गयी थी?', 'Which leader died due to a lathi charge during the boycott of the Simon Commission?', 'लाला लाजपत राय', 'Lala Lajpat Rai', 95, 0, '{"facts":["यह घटना 1928 में लाहौर में हुई थी।","लाला जी को ''पंजाब केसरी'' (Lion of Punjab) कहा जाता था।"],"factsEn":["This incident occurred in 1928 in Lahore.","Lala ji was known as ''Punjab Kesari'' (Lion of Punjab)."],"explanationHi":"साइमन कमीशन में कोई भारतीय सदस्य न होने के कारण इसका विरोध (''साइमन गो बैक'') हो रहा था। लाला जी पर पुलिस अधीक्षक जेम्स ए. स्कॉट ने लाठीचार्ज का आदेश दिया था।","explanationEn":"The commission was boycotted (''Simon Go Back'') as it had no Indian members. Police Superintendent James A. Scott ordered the lathi charge on Lala ji.","memoryTip":"लाठियों से शेर (पंजाब केसरी) को मारा गया।","memoryTipEn":"Lajpat Rai faced the Lathis.","related":["Simon Commission 1928","Punjab Kesari","Bhagat Singh (Took revenge)"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('LWlQ65xOFtMYfIzoHrf6y', 'General Science', 'भारत में निर्मित प्रथम कंप्यूटर का क्या नाम है?', 'What is the name of the first computer manufactured in India?', 'सिद्धार्थ', 'Siddhartha', 88, 0, '{"facts":["इसे इलेक्ट्रॉनिक्स कॉरपोरेशन ऑफ इंडिया (ECIL) द्वारा विकसित किया गया था।","इसे 1986 में मुख्य डाकघर, बेंगलुरु में स्थापित किया गया था।"],"factsEn":["It was developed by the Electronics Corporation of India Limited (ECIL).","It was installed at the Main Post Office in Bengaluru in 1986."],"explanationHi":"हालांकि भारत का पहला सुपरकंप्यूटर ''परम 8000'' है, लेकिन स्वदेशी रूप से निर्मित पहला सामान्य कंप्यूटर ''सिद्धार्थ'' था।","explanationEn":"While India''s first supercomputer is ''PARAM 8000'', the first indigenously built general computer was ''Siddhartha''.","memoryTip":"बुद्ध (सिद्धार्थ) की तरह ही भारत का कंप्यूटर ज्ञानवर्धन लाया।","memoryTipEn":"Siddhartha was India''s first digital step.","related":["PARAM 8000","ECIL","C-DAC"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TEqv8EZ_bjge2n2QTB4cy', 'General Knowledge', '''गायत्री मन्त्र'' का उल्लेख किस ग्रंथ में है?', '''Gayatri Mantra'' is mentioned in which ancient text?', 'ऋग्वेद', 'Rigveda', 95, 0, '{"facts":["यह ऋग्वेद के तीसरे मंडल (Book 3) में पाया जाता है।","इसकी रचना महर्षि विश्वामित्र ने की थी।"],"factsEn":["It is found in the third Mandala (Book 3) of the Rigveda.","It was composed by Maharishi Vishvamitra."],"explanationHi":"यह वैदिक मंत्र सूर्य देवता (सावित्री/सविता) को समर्पित है और ज्ञान तथा बुद्धि के प्रकाश की प्रार्थना करता है।","explanationEn":"This Vedic mantra is dedicated to the Sun God (Savitri/Savita) and is a prayer for intellectual illumination.","memoryTip":"''ऋग'' (Rig) में ''गायत्री'' गाई गई।","memoryTipEn":"Rigveda holds the radiant Gayatri.","related":["Vishvamitra","Savitri (Sun Deity)","Mandalas of Rigveda"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0_31_-vpySuLfBPLhJMvx', 'General Science', 'मानव शरीर में पाचन क्रिया अधिकतर किस अंग में संपन्न होती है?', 'In which organ is the process of digestion mostly completed in the human body?', 'छोटी आंत (Small Intestine)', 'Small Intestine', 96, 0, '{"facts":["भोजन का अधिकतम पाचन और पोषक तत्वों का अवशोषण (Absorption) यहीं होता है।","यह पाचन तंत्र का सबसे लंबा हिस्सा है (लगभग 20-23 फीट)।"],"factsEn":["Maximum digestion of food and absorption of nutrients occur here.","It is the longest part of the digestive tract (approx. 20-23 feet)."],"explanationHi":"पेट (Stomach) से आंशिक रूप से पचा हुआ भोजन छोटी आंत में आता है, जहाँ अग्नाशय रस और पित्त की मदद से पाचन पूरा होता है।","explanationEn":"Partially digested food from the stomach enters the small intestine, where digestion is completed with the help of pancreatic juice and bile.","memoryTip":"नाम की ''छोटी'' है, पर काम (पाचन) सबसे ''बड़ा'' करती है।","memoryTipEn":"Small intestine does the biggest digestive job.","related":["Large Intestine","Villi (Absorption)","Stomach"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zDDo6R3GG1nKSijgRNLBq', 'General Science', 'आनुवांशिकता (Genetics) के नियमों का प्रतिपादन किसने किया?', 'Who propounded the laws of Heredity (Genetics)?', 'ग्रेगर मेंडल ने (Gregor Mendel)', 'Gregor Mendel', 93, 0, '{"facts":["उन्हें ''आधुनिक आनुवंशिकी का जनक'' (Father of Modern Genetics) कहा जाता है।","उन्होंने अपने प्रयोग मटर के पौधे (Pea plants) पर किए थे।"],"factsEn":["He is known as the ''Father of Modern Genetics''.","He conducted his experiments on Pea plants."],"explanationHi":"मेंडल ने प्रदर्शित किया कि लक्षण माता-पिता से संतानों में विशिष्ट नियमों के अनुसार कैसे स्थानांतरित होते हैं (प्रभाविता और पृथक्करण के नियम)।","explanationEn":"Mendel demonstrated how traits are transferred from parents to offspring according to specific laws (Laws of Dominance and Segregation).","memoryTip":"''मटर'' (Mendal) ने पी (Pea) के साथ प्रयोग किया।","memoryTipEn":"Mendel matched the peas.","related":["Pea Plant (Pisum sativum)","Father of Genetics","DNA"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YBzXokPYsWCq94JXda0Id', 'General Knowledge', 'मानव द्वारा सबसे पहले किस धातु का प्रयोग किया गया?', 'Which metal was used first by humans?', 'तांबा (Copper)', 'Copper', 94, 0, '{"facts":["ताम्र पाषाण युग (Chalcolithic Age) में इसका उपयोग पहली बार हुआ।","इसके बाद तांबे और टिन को मिलाकर कांस्य (Bronze) बनाया गया।"],"factsEn":["It was first used during the Chalcolithic Age.","Later, copper and tin were alloyed to make Bronze."],"explanationHi":"तांबा प्रकृति में अपेक्षाकृत शुद्ध रूप में पाया जाता था और इसे बिना अधिक तापमान के मोड़ा और आकार दिया जा सकता था।","explanationEn":"Copper was found in relatively pure form in nature and could be easily bent and shaped without extremely high temperatures.","memoryTip":"इंसान ने सबसे पहले ''ताकत'' के लिए ''तांबा'' पकड़ा।","memoryTipEn":"Copper came before the Bronze Age.","related":["Chalcolithic Age","Bronze Age","Iron Age"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xTXvKdjSikkR5xr96CQv2', 'General Science', 'बाल पेन (Ball Pen) किस सिद्धांत पर काम करता है?', 'On which principle does a ballpoint pen work?', 'पृष्ठीय तनाव (Surface Tension)', 'Surface Tension (and Capillary Action / Gravity)', 89, 0, '{"facts":["पेन की निब में एक छोटी सी गेंद (Ball) होती है जो कागज पर घूमती है।","स्याही का कागज पर चिपकना और बहना गुरुत्वाकर्षण और पृष्ठीय तनाव पर निर्भर करता है।"],"factsEn":["The pen nib has a tiny ball that rolls on the paper.","The ink clinging and flowing onto the paper relies on gravity and surface tension."],"explanationHi":"स्याही में उच्च पृष्ठीय तनाव और गाढ़ापन (Viscosity) होता है, जिससे गेंद के घूमने पर यह बिना रिसे कागज पर छप जाती है। (नोट: गुरुत्वाकर्षण और केशिकत्व भी भूमिका निभाते हैं)।","explanationEn":"The ink has high surface tension and viscosity, allowing it to coat the rolling ball and transfer to the paper without leaking. (Note: Gravity and capillary action also play roles).","memoryTip":"स्याही ''तनाव'' लेकर पेपर पर उतरती है।","memoryTipEn":"Surface Tension keeps the ink on the ball.","related":["Capillary Action","Viscosity","Fountain Pen"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GM3QhhFQp6V1QTCIiBIJi', 'General Science', 'रेशम के कीड़े (Silkworm) किस वृक्ष की कोमल पत्तियों पर पाले जाते हैं?', 'Silkworms are reared on the tender leaves of which tree?', 'शहतूत (Mulberry)', 'Mulberry', 92, 0, '{"facts":["रेशम के कीड़ों के पालन को ''सेरीकल्चर'' (Sericulture) कहा जाता है।","रेशम का कीड़ा अपने कोकून (Cocoon) से रेशम का धागा बनाता है।"],"factsEn":["The rearing of silkworms is called ''Sericulture''.","The silkworm produces silk thread from its cocoon."],"explanationHi":"मुख्य रूप से बॉम्बिक्स मोरी (Bombyx mori) नामक रेशम का कीड़ा शहतूत की पत्तियों को खाकर उच्च गुणवत्ता वाला रेशम पैदा करता है।","explanationEn":"Primarily, the silkworm species Bombyx mori feeds on mulberry leaves to produce high-quality silk.","memoryTip":"रेशम के कीड़े को ''शहतूत'' का शहद पसंद है।","memoryTipEn":"Mulberry makes the silk merry.","related":["Sericulture","Cocoon","Bombyx mori"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HDhxGBzuDIQWctzEV6Esi', 'General Knowledge', 'राजस्थान में खेतड़ी (Khetri) किसके लिए प्रसिद्ध है?', 'What is Khetri in Rajasthan famous for?', 'तांबे की खान (Copper Mines)', 'Copper Mines', 94, 0, '{"facts":["खेतड़ी राजस्थान के झुंझुनू जिले में स्थित है।","सिंधु घाटी सभ्यता (हड़प्पा) के लोगों को भी तांबा खेतड़ी की खदानों से ही मिलता था।"],"factsEn":["Khetri is located in the Jhunjhunu district of Rajasthan.","People of the Indus Valley Civilization (Harappa) also sourced copper from Khetri mines."],"explanationHi":"हिंदुस्तान कॉपर लिमिटेड (HCL) द्वारा यहां बड़े पैमाने पर तांबे का खनन और शोधन किया जाता है।","explanationEn":"Large-scale copper mining and smelting are carried out here by Hindustan Copper Limited (HCL).","memoryTip":"खेतों (खेतड़ी) में ''तांबा'' बोया गया है।","memoryTipEn":"Khetri''s Copper is historic.","related":["Indus Valley Civilization","Hindustan Copper Limited","Jhunjhunu"]}', 'published', 1776083476, 1776083476);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uetp3bECpH8iLAm_QUXxe', 'General Science', 'पृथ्वी के सबसे नजदीक ग्रह कौनसा है?', 'Which is the closest planet to Earth?', 'शुक्र (Venus)', 'Venus', 92, 0, '{"facts":["शुक्र को ''पृथ्वी की जुड़वां बहन'' (Earth''s Twin) भी कहा जाता है।","आकार और द्रव्यमान में यह पृथ्वी के काफी समान है।"],"factsEn":["Venus is also known as ''Earth''s Twin''.","It is very similar to Earth in size and mass."],"explanationHi":"यह हमारे सौरमंडल में पृथ्वी का सबसे निकटतम पड़ोसी ग्रह है और इसे रात के आकाश में आसानी से देखा जा सकता है।","explanationEn":"It is Earth''s closest planetary neighbor in the solar system and can be easily seen in the night sky.","memoryTip":"शुक्र मनाओ कि पृथ्वी के पास ''शुक्र'' है।","memoryTipEn":"Venus is very close to us.","related":["Mars","Earth''s Twin","Morning Star"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XP0aBrqks1H5pxrgt5xMm', 'General Science', 'मनुष्य की आँख में किसी वस्तु का प्रतिबिम्ब (Image) कहाँ बनता है?', 'Where is the image of an object formed in the human eye?', 'रेटिना (Retina)', 'Retina', 95, 0, '{"facts":["रेटिना आँख का वह प्रकाश-संवेदनशील पर्दा है जो कैमरे की फिल्म की तरह काम करता है।","रेटिना पर बनने वाला प्रतिबिम्ब ''वास्तविक और उल्टा'' (Real and Inverted) होता है।"],"factsEn":["Retina is the light-sensitive screen of the eye that acts like a camera film.","The image formed on the retina is ''Real and Inverted''."],"explanationHi":"आँख का लेंस प्रकाश को मोड़कर रेटिना पर केंद्रित करता है, जहाँ से ऑप्टिक नर्व इसे मस्तिष्क तक ले जाती है।","explanationEn":"The eye lens focuses light onto the retina, from where the optic nerve carries it to the brain.","memoryTip":"रेटिना ''रेट'' (दर) तय करती है कि चीज़ कैसी दिख रही है।","memoryTipEn":"Retina acts as the screen for the visual ''Retention''.","related":["Cornea","Optic Nerve","Real and Inverted Image"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6egMeUgUtL7hJD55u-uNr', 'General Science', 'सूर्य से पृथ्वी पर ऊष्मा का संचरण किस विधि के द्वारा होता है?', 'By which method is heat from the sun transmitted to the Earth?', 'विकिरण (Radiation)', 'Radiation', 96, 0, '{"facts":["ऊष्मा संचरण की तीन विधियाँ हैं: चालन (Conduction), संवहन (Convection), और विकिरण (Radiation)।","विकिरण को किसी माध्यम (Medium) की आवश्यकता नहीं होती है।"],"factsEn":["The three modes of heat transfer are Conduction, Convection, and Radiation.","Radiation does not require any material medium."],"explanationHi":"चूँकि अंतरिक्ष में निर्वात (Vacuum) है, इसलिए सूर्य की ऊष्मा विद्युत चुम्बकीय तरंगों (Electromagnetic waves) के रूप में पृथ्वी तक पहुँचती है।","explanationEn":"Since space is a vacuum, the sun''s heat reaches Earth in the form of electromagnetic waves.","memoryTip":"बिना तार के रेडियो (Radiation) की तरह धूप आती है।","memoryTipEn":"Radiant heat travels through space.","related":["Conduction","Convection","Electromagnetic Waves"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rFWMbP3hDgs2HDCQZ-FE2', 'General Science', 'डी.एन.ए. (DNA) की द्विगुणित कुंडली (Double Helix) का पता किसने लगाया?', 'Who discovered the double helix structure of DNA?', 'वाटसन और क्रिक', 'James Watson and Francis Crick', 95, 0, '{"facts":["इन्होंने 1953 में इस संरचना की खोज की थी।","इस कार्य के लिए उन्हें 1962 में नोबेल पुरस्कार से सम्मानित किया गया था।"],"factsEn":["They discovered this structure in 1953.","They were awarded the Nobel Prize in 1962 for this work."],"explanationHi":"डीएनए (Deoxyribonucleic acid) की यह सीढ़ीनुमा घुमावदार संरचना ही सभी जीवित जीवों की आनुवंशिक जानकारी रखती है।","explanationEn":"This twisted-ladder structure of DNA carries the genetic instructions for all living organisms.","memoryTip":"वाटसन और क्रिक ने DNA का ''रहस्य'' क्रैक (Crick) किया।","memoryTipEn":"Watson and Crick cracked the DNA code.","related":["Rosalind Franklin","DNA","Genetics"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Kus-PhPO-VzpyYCOwu_Qi', 'General Science', 'ध्वनि की तीव्रता किसमें मापी जाती है?', 'In which unit is the intensity of sound measured?', 'डेसिबल (Decibel - dB)', 'Decibel (dB)', 94, 0, '{"facts":["सामान्य बातचीत की तीव्रता लगभग 60 डेसिबल होती है।","85 डेसिबल से अधिक की ध्वनि मानव कान के लिए हानिकारक (प्रदूषण) मानी जाती है।"],"factsEn":["Normal conversation has an intensity of about 60 decibels.","Sound above 85 decibels is considered harmful (noise pollution) for human ears."],"explanationHi":"यह इकाई अलेक्जेंडर ग्राहम बेल के नाम पर रखी गई है और यह ध्वनि के दबाव स्तर (Pressure level) को मापती है।","explanationEn":"This unit is named after Alexander Graham Bell and measures the sound pressure level.","memoryTip":"आवाज़ में कितना ''बल'' (Deci-bel) है।","memoryTipEn":"Decibel decides the loudness.","related":["Alexander Graham Bell","Noise Pollution","Frequency (Hertz)"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TvaHDYn3JACuFq2s80p1u', 'General Science', 'मधुमक्खी पालन क्या कहलाता है?', 'What is the rearing of honey bees called?', 'एपीकल्चर (Apiculture)', 'Apiculture', 90, 0, '{"facts":["यह शहद और मोम (Beeswax) के उत्पादन के लिए किया जाता है।","मधुमक्खी को वैज्ञानिक भाषा में ''एपिस'' (Apis) कहा जाता है।"],"factsEn":["It is done for the production of honey and beeswax.","The scientific name for the honey bee genus is ''Apis''."],"explanationHi":"कृषि की इस शाखा के तहत मधुमक्खियों के छत्तों का कृत्रिम रूप से प्रबंधन किया जाता है।","explanationEn":"Under this branch of agriculture, bee hives are artificially managed.","memoryTip":"शहद की एक ''पी'' (Apis) है, इसलिए एपीकल्चर।","memoryTipEn":"Ape (Apis) culture is for bees.","related":["Sericulture (Silkworm)","Pisciculture (Fish)","Horticulture"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('x5ZKJ2AW4Dncb0le-Oz4K', 'General Knowledge', 'किसी वेबसाइट के प्रथम पृष्ठ को क्या कहा जाता है?', 'What is the first page of a website called?', 'होमपेज (Homepage)', 'Homepage', 85, 0, '{"facts":["यह वेबसाइट का मुख्य या प्रारंभिक बिंदु होता है।","यहाँ से यूजर वेबसाइट के अन्य पेजों पर नेविगेट कर सकता है।"],"factsEn":["It is the main or starting point of a website.","From here, a user can navigate to other pages of the website."],"explanationHi":"जब भी आप कोई डोमेन नाम टाइप करते हैं (जैसे www.google.com), तो सबसे पहले जो वेबपेज खुलता है उसे होमपेज कहते हैं।","explanationEn":"Whenever you type a domain name, the default webpage that loads first is called the homepage.","memoryTip":"इंटरनेट पर घर का दरवाज़ा = होमपेज।","memoryTipEn":"Every website starts at Home.","related":["URL","Web Browser","HTML"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('hI5fCFUBUAUYUmQ0Mq793', 'General Science', 'गाड़ियों में पीछे का दृश्य (Rear view) देखने के लिए किस दर्पण का प्रयोग किया जाता है?', 'Which mirror is used as a rear-view mirror in vehicles?', 'उत्तल दर्पण (Convex Mirror)', 'Convex Mirror', 96, 0, '{"facts":["उत्तल दर्पण हमेशा सीधा और छोटा (Diminished) प्रतिबिम्ब बनाता है।","अवतल दर्पण (Concave) का उपयोग डेंटिस्ट और शेविंग मिरर में होता है।"],"factsEn":["A convex mirror always forms an erect and diminished image.","Concave mirrors are used by dentists and as shaving mirrors."],"explanationHi":"यह पीछे के बहुत बड़े क्षेत्र (Wider field of view) को छोटे आकार में दिखा देता है, जिससे ड्राइवर को ट्रैफिक देखने में मदद मिलती है।","explanationEn":"It provides a wider field of view by showing a large area in a smaller size, helping the driver see traffic.","memoryTip":"पीछे से गाड़ी ''उठ'' (उत्तल) कर आ रही है।","memoryTipEn":"Convex covers a wider context.","related":["Concave Mirror","Field of View","Optics"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3qhJxJk-hhPHT8RpJJZzK', 'General Science', 'सामान्य परिस्थितियों में हवा में ध्वनि की गति कितनी होती है?', 'What is the speed of sound in air under normal conditions?', '332 मी./ सेकंड', '332 m/s', 94, 0, '{"facts":["यह गति 0°C तापमान पर होती है।","तापमान बढ़ने पर हवा में ध्वनि की गति बढ़ जाती है (लगभग 0.6 m/s प्रति डिग्री सेल्सियस)।"],"factsEn":["This is the speed at 0°C temperature.","The speed of sound in air increases with temperature (approx 0.6 m/s per °C)."],"explanationHi":"ध्वनि एक यांत्रिक तरंग (Mechanical wave) है, इसलिए इसे यात्रा करने के लिए एक माध्यम (हवा, पानी या ठोस) की आवश्यकता होती है।","explanationEn":"Sound is a mechanical wave, so it requires a medium (air, water, or solid) to travel.","memoryTip":"तीन-तीन-दो, हवा में ध्वनि दौड़ो।","memoryTipEn":"332 meters per tick.","related":["Mach Number","Speed of Light","Acoustics"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QkP9k_4gjdYoT4VH9OR-f', 'General Science', 'वह एकमात्र ग्रह कौनसा है जो अपनी धुरी पर पूर्व से पश्चिम (East to West) दिशा में घूमता है?', 'Which planet rotates on its axis from East to West?', 'शुक्र (Venus) [तथा अरुण/Uranus भी]', 'Venus (and Uranus)', 93, 0, '{"facts":["पृथ्वी और अन्य ग्रह पश्चिम से पूर्व की ओर घूमते हैं।","शुक्र ग्रह पर सूर्योदय पश्चिम में और सूर्यास्त पूर्व में होता है।"],"factsEn":["Earth and other planets rotate from West to East.","On Venus, the sun rises in the West and sets in the East."],"explanationHi":"इस विपरीत घुमाव को ''रेट्रोग्रेड रोटेशन'' (Retrograde Rotation) कहा जाता है। (ध्यान दें: अरुण भी पूर्व से पश्चिम घूमता है)।","explanationEn":"This opposite rotation is called ''Retrograde Rotation''. (Note: Uranus also rotates East to West).","memoryTip":"शुक्र ने कहा, ''मैं सबसे अलग हूँ'', इसलिए उल्टी दिशा में घूमा।","memoryTipEn":"Venus is the rebel rotating in reverse.","related":["Retrograde Rotation","Uranus","Solar System"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1O-EPgSWRKM3IWFh_94f9', 'General Science', 'सूर्य में सर्वाधिक गैस कौनसी है?', 'Which gas is most abundant in the Sun?', 'हाइड्रोजन', 'Hydrogen', 95, 0, '{"facts":["सूर्य का लगभग 73-74% हिस्सा हाइड्रोजन है।","दूसरा सबसे प्रचुर तत्व हीलियम (लगभग 24-25%) है।"],"factsEn":["Hydrogen makes up about 73-74% of the Sun.","The second most abundant element is Helium (approx 24-25%)."],"explanationHi":"सूर्य अपनी ऊर्जा नाभिकीय संलयन (Nuclear Fusion) के माध्यम से उत्पन्न करता है, जिसमें हाइड्रोजन के परमाणु मिलकर हीलियम बनाते हैं।","explanationEn":"The Sun generates its energy through Nuclear Fusion, where hydrogen atoms fuse to form helium.","memoryTip":"सूरज एक ''हाइड्रोजन'' बम की तरह सुलग रहा है।","memoryTipEn":"Hydrogen fuels the Helium fire.","related":["Helium","Nuclear Fusion","Solar Energy"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('asZqQQKn6qtLNq9a1m9H4', 'General Science', 'पृथ्वी से दिखाई देने वाला सबसे चमकीला ग्रह कौनसा है?', 'Which is the brightest planet visible from Earth?', 'शुक्र (Venus)', 'Venus', 92, 0, '{"facts":["इसे भोर का तारा (Morning Star) और सांझ का तारा (Evening Star) भी कहा जाता है।","चंद्रमा के बाद यह रात के आकाश में दूसरी सबसे चमकीली प्राकृतिक वस्तु है।"],"factsEn":["It is also called the Morning Star and Evening Star.","It is the second brightest natural object in the night sky after the Moon."],"explanationHi":"इसके वायुमंडल में सल्फ्यूरिक एसिड के अत्यधिक परावर्तक (Reflective) बादल होते हैं, जो इसे बहुत चमकीला बनाते हैं।","explanationEn":"Its atmosphere contains highly reflective clouds of sulfuric acid, making it extremely bright.","memoryTip":"शुक्र मनाओ कि आसमान में सबसे चमकने वाला शुक्र है।","memoryTipEn":"Venus = Goddess of Beauty = Brightest.","related":["Albedo","Morning Star","Evening Star"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1wWx7F_yRVBo2XKYHKcUB', 'General Science', 'सौरमंडल की आयु कितनी है?', 'What is the age of the solar system?', '4.6 अरब वर्ष', '4.6 billion years', 88, 0, '{"facts":["वैज्ञानिकों ने उल्कापिंडों (Meteorites) और चंद्रमा की चट्टानों की रेडियोमेट्रिक डेटिंग (Radiometric dating) करके यह आयु निकाली है।","ब्रह्मांड (Universe) की आयु लगभग 13.8 अरब वर्ष है।"],"factsEn":["Scientists calculated this age using radiometric dating of meteorites and moon rocks.","The age of the Universe is about 13.8 billion years."],"explanationHi":"माना जाता है कि हमारा सौरमंडल गैस और धूल के एक विशाल बादल (Solar Nebula) के ढहने से बना है।","explanationEn":"It is believed that our solar system was formed from the collapse of a giant cloud of gas and dust (Solar Nebula).","memoryTip":"4 और 6 (4.6) मिलकर सौरमंडल की उम्र बताते हैं।","memoryTipEn":"4.6 billion years of sunshine.","related":["Big Bang Theory","Solar Nebula","Radiometric Dating"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gF4llQ-ZiI639uGdKX7uO', 'General Science', 'कौनसा पुच्छल तारा (Comet) 76 वर्ष बाद दिखाई देता है?', 'Which comet appears after every 76 years?', 'हेली पुच्छल तारा (Halley''s Comet)', 'Halley''s Comet', 93, 0, '{"facts":["यह पिछली बार 1986 में देखा गया था।","अब यह वर्ष 2061 में पृथ्वी से दिखाई देगा।"],"factsEn":["It was last seen in 1986.","It will next be visible from Earth in the year 2061."],"explanationHi":"इसका नाम अंग्रेजी खगोलशास्त्री एडमंड हेली के नाम पर रखा गया है, जिन्होंने इसकी परिक्रमा अवधि की गणना की थी।","explanationEn":"It is named after English astronomer Edmond Halley, who calculated its orbital period.","memoryTip":"हेली पुच्छल तारा 76 साल बाद ''हेलो'' (Halley) कहता है।","memoryTipEn":"Halley says Hello every 76 years.","related":["Edmond Halley","Comets","Oort Cloud"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JDyDdk0yw8wEw7Ogzwyou', 'General Science', 'पृथ्वी और सूर्य के बीच दूरी कितनी है?', 'What is the distance between the Earth and the Sun?', '15 करोड़ किलोमीटर', '150 Million Kilometers', 91, 0, '{"facts":["इस दूरी को 1 खगोलीय इकाई (Astronomical Unit - AU) कहा जाता है।","प्रकाश को इस दूरी को तय करने में 8 मिनट 20 सेकंड लगते हैं।"],"factsEn":["This distance is called 1 Astronomical Unit (AU).","Light takes 8 minutes and 20 seconds to cover this distance."],"explanationHi":"पृथ्वी एक अण्डाकार कक्षा में सूर्य की परिक्रमा करती है, इसलिए यह दूरी पूरे वर्ष थोड़ी बदलती रहती है (औसत 15 करोड़ किमी)।","explanationEn":"Earth orbits the sun in an elliptical path, so this distance varies slightly throughout the year (average 150 million km).","memoryTip":"15 करोड़ कदम दूर है सूरज।","memoryTipEn":"1 AU = 150 Million KM.","related":["Astronomical Unit (AU)","Perihelion","Aphelion"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('G-dMb0lGztPMWgbEysTLM', 'General Science', 'सूर्य का प्रकाश पृथ्वी तक पहुँचने में कितना समय लेता है?', 'How much time does sunlight take to reach the Earth?', 'लगभग 500 सेकंड (8 मिनट 20 सेकंड)', 'Approx. 500 seconds (8 minutes 20 seconds)', 96, 0, '{"facts":["प्रकाश की गति 3,00,000 किमी प्रति सेकंड होती है।","सूर्य और पृथ्वी के बीच की औसत दूरी 15 करोड़ किलोमीटर है।"],"factsEn":["The speed of light is 300,000 km per second.","The average distance between the Sun and Earth is 150 million kilometers."],"explanationHi":"दूरी (15,00,00,000) को प्रकाश की गति (3,00,000) से भाग देने पर हमें 500 सेकंड मिलते हैं।","explanationEn":"Dividing the distance (150,000,000) by the speed of light (300,000) gives us 500 seconds.","memoryTip":"500 की गिनती तक सूरज की किरण ज़मीन चूम लेती है।","memoryTipEn":"500 seconds from the sun.","related":["Speed of Light","Astronomical Unit"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4vEgst61t4rAGU8rdgCf3', 'General Knowledge', 'भारत ने पहला परमाणु परीक्षण (Nuclear Test) कब और कहाँ किया था?', 'When and where did India conduct its first nuclear test?', '14 मई 1974 को पोखरण (राजस्थान) में', '14 May 1974 at Pokhran (Rajasthan)', 95, 0, '{"facts":["इस ऑपरेशन का कूट नाम ''स्माइलिंग बुद्धा'' (Smiling Buddha) था।","यह एक शांतिपूर्ण परमाणु विस्फोट (PNE) था।"],"factsEn":["The code name of this operation was ''Smiling Buddha''.","It was a Peaceful Nuclear Explosion (PNE)."],"explanationHi":"तत्कालीन प्रधानमंत्री इंदिरा गांधी के नेतृत्व में यह परीक्षण किया गया था, जिससे भारत परमाणु शक्ति संपन्न देशों के क्लब में शामिल हो गया।","explanationEn":"Conducted under PM Indira Gandhi, this test made India a member of the nuclear-armed nations club.","memoryTip":"74 में पोखरण में ''बुद्ध मुस्कुराए'' (Smiling Buddha)।","memoryTipEn":"Pokhran ''74: The Buddha Smiled.","related":["Operation Smiling Buddha","Pokhran-II (1998)","Indira Gandhi"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QEqYlALz_W7SdF8RF59bs', 'General Science', 'कंप्यूटर के जिस भाग को हम स्पर्श (Touch) कर सकते हैं वह क्या कहलाता है?', 'The part of a computer that we can touch is called what?', 'हार्डवेयर (Hardware)', 'Hardware', 90, 0, '{"facts":["कीबोर्ड, माउस, मॉनिटर, मदरबोर्ड आदि हार्डवेयर के उदाहरण हैं।","जिन प्रोग्रामों या निर्देशों को हम छू नहीं सकते, वे सॉफ्टवेयर (Software) कहलाते हैं।"],"factsEn":["Keyboard, mouse, monitor, motherboard, etc., are examples of hardware.","Programs or instructions that we cannot touch are called Software."],"explanationHi":"कंप्यूटर सिस्टम के सभी भौतिक उपकरणों (Physical components) को हार्डवेयर कहा जाता है।","explanationEn":"All the physical components and equipment of a computer system are known as hardware.","memoryTip":"जो छूने में ''हार्ड'' (कठोर) लगे, वो हार्डवेयर।","memoryTipEn":"Hardware is hard to the touch.","related":["Software","Input/Output Devices","Peripherals"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Kk2MYxujRfbvEwbuZWdTc', 'General Science', 'कैंसर के उपचार में प्रयुक्त उत्कृष्ट गैस (Noble Gas) कौनसी है?', 'Which noble gas is used in the treatment of cancer?', 'रेडॉन (Radon)', 'Radon', 92, 0, '{"facts":["रेडॉन एक रेडियोधर्मी (Radioactive) नोबल गैस है।","इसका परमाणु क्रमांक 86 है।"],"factsEn":["Radon is a radioactive noble gas.","Its atomic number is 86."],"explanationHi":"कैंसर (विशेषकर ट्यूमर) के इलाज के लिए रेडियोथेरेपी में रेडॉन के विकिरण गुणों का उपयोग किया जाता है।","explanationEn":"The radiation properties of radon are used in radiotherapy to treat cancer (especially tumors).","memoryTip":"''रेडियो''थेरेपी में ''रेडॉन'' का प्रयोग।","memoryTipEn":"Radon Radiates the tumor.","related":["Radiotherapy","Noble Gases","Radioactivity"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('g9QsxNpG2qRK0vLLDBk6w', 'General Science', 'मोनेजाइट (Monazite) बालू में कौनसा खनिज पाया जाता है?', 'Which mineral is found in Monazite sand?', 'थोरियम (Thorium)', 'Thorium', 90, 0, '{"facts":["भारत के केरल राज्य के समुद्री तटों पर मोनेजाइट रेत प्रचुर मात्रा में पाई जाती है।","थोरियम का उपयोग भविष्य के परमाणु रिएक्टरों (Nuclear Reactors) में ईंधन के रूप में किया जा सकता है।"],"factsEn":["Monazite sand is abundantly found on the coastal beaches of Kerala, India.","Thorium can be used as a fuel in future nuclear reactors."],"explanationHi":"थोरियम एक रेडियोधर्मी रासायनिक तत्व है, जो सीधे विखंडनीय नहीं है, लेकिन इसे यूरेनियम-233 में बदला जा सकता है।","explanationEn":"Thorium is a radioactive chemical element; it is not fissile directly but can be converted into Uranium-233.","memoryTip":"मोनेजाइट बालू में ''थोर'' (Thorium) की शक्ति छुपी है।","memoryTipEn":"Thor wields the power of Thorium from the sand.","related":["Kerala Coast","Nuclear Fuel","Uranium"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PvlU35mTBEzYNobRO87gE', 'General Science', 'शरीर में सबसे बड़ी अंतःस्रावी ग्रंथि (Endocrine Gland) कौनसी है?', 'Which is the largest endocrine gland in the body?', 'थायराइड (Thyroid)', 'Thyroid', 95, 0, '{"facts":["यह गले में श्वासनली (Trachea) के सामने स्थित एक तितली के आकार की ग्रंथि है।","यह थायरोक्सिन (Thyroxine) हार्मोन स्रावित करती है।"],"factsEn":["It is a butterfly-shaped gland located in the front of the neck along the trachea.","It secretes the Thyroxine hormone."],"explanationHi":"यह ग्रंथि शरीर के चयापचय (Metabolism), ऊर्जा स्तर और विकास को नियंत्रित करने में महत्वपूर्ण भूमिका निभाती है।","explanationEn":"This gland plays a crucial role in regulating the body''s metabolism, energy levels, and development.","memoryTip":"गले का ''थायराइड'' सबसे बड़ी ''अंतः'' ग्रंथि है।","memoryTipEn":"Thyroid dominates the endocrine system by size.","related":["Endocrine System","Goiter","Pituitary Gland (Master Gland)"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CqXZ1Ov-WG6auNEkwxq45', 'General Science', 'संसार का विशालतम स्तनधारी (Mammal) कौनसा है?', 'Which is the largest mammal in the world?', 'ब्लू व्हेल (Blue Whale)', 'Blue Whale', 93, 0, '{"facts":["यह पृथ्वी पर अब तक का सबसे बड़ा ज्ञात प्राणी है।","एक वयस्क ब्लू व्हेल का वजन 200 टन और लंबाई 100 फीट तक हो सकती है।"],"factsEn":["It is the largest known animal to have ever lived on Earth.","An adult Blue Whale can weigh up to 200 tons and reach 100 feet in length."],"explanationHi":"मछली जैसी दिखने के बावजूद, व्हेल स्तनधारी हैं; वे बच्चे पैदा करती हैं और फेफड़ों से सांस लेती हैं।","explanationEn":"Despite looking like fish, whales are mammals; they give birth to live young and breathe air using lungs.","memoryTip":"समुद्र का ''नीला'' राक्षस = ब्लू व्हेल।","memoryTipEn":"Blue Whale dwarfs the dinosaurs.","related":["Mammalia","African Elephant (Largest Land Mammal)"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('LQnyFAUtX7nh1Y_VPmVPb', 'General Science', 'ब्लड ग्रुप (Blood Group) की खोज किसने की थी?', 'Who discovered the Blood Groups?', 'कार्ल लैंडस्टीनर', 'Karl Landsteiner', 94, 0, '{"facts":["उन्होंने 1900-1901 में ABO रक्त समूह प्रणाली की खोज की थी।","इस खोज के लिए उन्हें 1930 में चिकित्सा का नोबेल पुरस्कार मिला था।"],"factsEn":["He discovered the ABO blood group system in 1900-1901.","He was awarded the Nobel Prize in Medicine in 1930 for this discovery."],"explanationHi":"उनकी खोज ने सुरक्षित रक्त आधान (Blood Transfusion) को संभव बनाया, जिससे अनगिनत जानें बचाई जा सकीं।","explanationEn":"His discovery made safe blood transfusions possible, saving countless lives.","memoryTip":"खून के अलग-अलग ''लैंड'' (समूह) लैंडस्टीनर ने खोजे।","memoryTipEn":"Landsteiner mapped the blood lands.","related":["ABO System","Rh Factor","Universal Donor (O-)"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FCly_RbTla0Xiw-gvYH6d', 'General Science', 'ऐलुमिनियम (Aluminium) का प्रमुख अयस्क (Ore) कौनसा है?', 'Which is the main ore of Aluminium?', 'बॉक्साइट (Bauxite)', 'Bauxite', 95, 0, '{"facts":["दुनिया भर में अधिकांश एल्युमीनियम इसी अयस्क से निकाला जाता है।","भारत में ओडिशा राज्य बॉक्साइट का सबसे बड़ा उत्पादक है।"],"factsEn":["Most of the world''s aluminium is extracted from this ore.","In India, Odisha is the largest producer of bauxite."],"explanationHi":"बॉक्साइट में मुख्य रूप से एल्युमिनियम ऑक्साइड के यौगिक होते हैं। बेयर प्रक्रिया (Bayer process) के जरिए इसे शुद्ध किया जाता है।","explanationEn":"Bauxite primarily consists of aluminium oxide compounds. It is purified through the Bayer process.","memoryTip":"ऐलुमिनियम को ''बॉक्स'' (बॉक्साइट) से निकालते हैं।","memoryTipEn":"Bauxite Box holds Aluminium.","related":["Bayer Process","Hall-Héroult process","Odisha Minerals"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PaQRQWYxyx0L_1d6QjUqu', 'General Science', 'पहला कृत्रिम उपग्रह (Artificial Satellite) कौनसा था?', 'Which was the first artificial satellite?', 'स्पुतनिक-1 (Sputnik 1)', 'Sputnik 1', 96, 0, '{"facts":["इसे 4 अक्टूबर 1957 को सोवियत संघ (रूस) द्वारा लॉन्च किया गया था।","इसने दुनिया में ''अंतरिक्ष युग'' (Space Age) की शुरुआत की थी।"],"factsEn":["It was launched by the Soviet Union (Russia) on October 4, 1957.","It initiated the ''Space Age'' in the world."],"explanationHi":"यह पृथ्वी की परिक्रमा करने वाली मानव निर्मित पहली वस्तु थी, जिसने अमेरिका और सोवियत संघ के बीच अंतरिक्ष दौड़ को जन्म दिया।","explanationEn":"It was the first human-made object to orbit Earth, sparking the space race between the US and the USSR.","memoryTip":"रूस ने ''स्पुतनिक'' भेजकर दुनिया को चौंका दिया।","memoryTipEn":"Sputnik sparked the Space Race.","related":["Space Race","Explorer 1 (First US Satellite)","Aryabhata (First Indian Satellite)"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('O6TXtZyZ53Twvjl0hvf7P', 'General Science', 'किस उपकरण द्वारा यांत्रिक ऊर्जा (Mechanical Energy) को विद्युत् ऊर्जा (Electrical Energy) में परिवर्तित किया जाता है?', 'Which device converts mechanical energy into electrical energy?', 'डायनेमो (या जनरेटर)', 'Dynamo (or Generator)', 94, 0, '{"facts":["यह विद्युत चुम्बकीय प्रेरण (Electromagnetic Induction) के सिद्धांत पर काम करता है।","इसके विपरीत, विद्युत मोटर (Electric Motor) विद्युत् ऊर्जा को यांत्रिक ऊर्जा में बदलती है।"],"factsEn":["It works on the principle of Electromagnetic Induction.","Conversely, an Electric Motor converts electrical energy into mechanical energy."],"explanationHi":"डायनेमो में एक कुंडल (coil) को चुंबकीय क्षेत्र में घुमाया जाता है, जिससे विद्युत धारा उत्पन्न होती है।","explanationEn":"In a dynamo, a coil is rotated within a magnetic field, which induces an electric current.","memoryTip":"घूमकर (यांत्रिक) बिजली बनाए = डायनेमो।","memoryTipEn":"Dynamo drives current.","related":["Electric Motor","Michael Faraday","Electromagnetic Induction"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HgaNoDEET6lR7GAuuY5ph', 'General Science', 'कंप्यूटर की अस्थायी स्मृति (Temporary Memory) क्या कहलाती है?', 'What is the temporary memory of a computer called?', 'RAM (Random Access Memory)', 'RAM (Random Access Memory)', 92, 0, '{"facts":["यह एक वोलेटाइल (Volatile) मेमोरी है; बिजली कटते ही इसका डेटा मिट जाता है।","यह कंप्यूटर को कार्य करते समय प्रोग्राम और डेटा को तेजी से एक्सेस करने की सुविधा देता है।"],"factsEn":["It is a volatile memory; data is lost when power is turned off.","It allows the computer to quickly access active programs and data."],"explanationHi":"जब आप कोई ऐप खोलते हैं, तो वह हार्ड ड्राइव से रैम में लोड होता है ताकि प्रोसेसर उसे तेज़ी से चला सके।","explanationEn":"When you open an app, it is loaded from the hard drive into RAM so the processor can run it quickly.","memoryTip":"RAM ''भाग'' (Volatile) जाता है, ROM ''रह'' (Permanent) जाता है।","memoryTipEn":"Randomly Accessing temporary stuff.","related":["ROM (Read Only Memory)","Volatile Memory","Cache Memory"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YWip93wyfWkRc-64MY6oW', 'General Science', 'रिक्टर पैमाने (Richter Scale) द्वारा क्या मापा जाता है?', 'What is measured by the Richter Scale?', 'भूकंप की तीव्रता', 'Intensity (Magnitude) of an Earthquake', 94, 0, '{"facts":["इसे 1935 में चार्ल्स एफ. रिक्टर द्वारा विकसित किया गया था।","यह एक लघुगणकीय पैमाना (Logarithmic scale) है।"],"factsEn":["It was developed by Charles F. Richter in 1935.","It is a base-10 logarithmic scale."],"explanationHi":"इस पैमाने पर 1 बिंदु की वृद्धि का अर्थ है भूकंप के आयाम में 10 गुना वृद्धि और ऊर्जा में लगभग 31.6 गुना वृद्धि।","explanationEn":"An increase of 1 point on this scale means a 10-fold increase in earthquake amplitude and about 31.6 times more energy.","memoryTip":"भूकंप आते ही ज़मीन ''रिएक्ट'' (रिक्टर) करती है।","memoryTipEn":"Richter records the ruptures.","related":["Seismograph","Mercalli Scale","Earthquake"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JmnaW9C2-UPAPWC0VxRua', 'General Science', 'भू-पटल (Earth''s Crust) में सबसे अधिक कौनसी धातु (Metal) है?', 'Which is the most abundant metal in the Earth''s crust?', 'एल्युमीनियम', 'Aluminium', 93, 0, '{"facts":["पृथ्वी की क्रस्ट में ऑक्सीजन और सिलिकॉन के बाद एल्युमीनियम तीसरा सबसे प्रचुर तत्व है।","धातुओं में इसका स्थान पहला है (लगभग 8% हिस्सा)।"],"factsEn":["Aluminium is the third most abundant element in the Earth''s crust after oxygen and silicon.","Among metals, it ranks first (approx 8%)."],"explanationHi":"हालाँकि यह प्रचुर मात्रा में है, यह प्रकृति में शुद्ध रूप में नहीं पाया जाता, बल्कि ऑक्साइड और सिलिकेट के रूप में होता है।","explanationEn":"Although abundant, it is never found free in nature; it is typically found in oxides and silicates.","memoryTip":"धरती के ऊपर की पटल ''अल्युमीनियम'' की पन्नी जैसी है।","memoryTipEn":"Aluminium is all around the crust.","related":["Oxygen (Most abundant element)","Iron (Second most abundant metal)","Bauxite"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RfREBSJ2fDYSWS-9ZvRiW', 'General Science', 'किस ग्रह को सांध्य तारा (Evening Star) कहते हैं?', 'Which planet is called the Evening Star?', 'शुक्र (Venus)', 'Venus', 91, 0, '{"facts":["इसे ''भोर का तारा'' (Morning Star) भी कहा जाता है।","यह सौरमंडल का सबसे गर्म ग्रह है।"],"factsEn":["It is also called the ''Morning Star''.","It is the hottest planet in the solar system."],"explanationHi":"यह सूर्योदय से ठीक पहले या सूर्यास्त के ठीक बाद आकाश में सबसे चमकीले पिंड के रूप में दिखाई देता है।","explanationEn":"It appears as the brightest object in the sky just before sunrise or just after sunset.","memoryTip":"शाम और सुबह आसमान का ''शुक्र'' (Venus) है जो इतना चमकता है।","memoryTipEn":"Venus is the star of the evening.","related":["Brightest Planet","Morning Star","Earth''s Twin"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MXaPdX3zMP7Mig5knAVDm', 'General Science', 'वायुमंडल की सबसे निचली सतह को क्या कहते हैं?', 'What is the lowest layer of the atmosphere called?', 'क्षोभमंडल (Troposphere)', 'Troposphere', 96, 0, '{"facts":["बादल, बारिश और तूफान जैसी सभी मौसम संबंधी घटनाएँ इसी परत में होती हैं।","इसकी औसत ऊँचाई सतह से लगभग 13 किलोमीटर है।"],"factsEn":["All weather phenomena like clouds, rain, and storms occur in this layer.","Its average height is about 13 kilometers from the surface."],"explanationHi":"जैसे-जैसे हम क्षोभमंडल में ऊपर जाते हैं, तापमान घटता जाता है।","explanationEn":"As we go higher in the troposphere, the temperature decreases.","memoryTip":"मौसम के ''क्षोभ'' (हंगामा) इसी मंडल में होते हैं।","memoryTipEn":"Weather troops in the Troposphere.","related":["Stratosphere","Atmosphere Layers","Weather"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('slPdiheHSGmMlNen05VPG', 'General Science', 'पृथ्वी को 1 डिग्री देशांतर (Longitude) घूमने में कितना समय लगता है?', 'How much time does it take for the Earth to rotate 1 degree of longitude?', '4 मिनट', '4 minutes', 93, 0, '{"facts":["पृथ्वी 24 घंटे में 360 डिग्री घूमती है।","इसलिए, 15 डिग्री घूमने में 1 घंटा (60 मिनट) लगता है।"],"factsEn":["The Earth rotates 360 degrees in 24 hours.","Therefore, it takes 1 hour (60 mins) to rotate 15 degrees."],"explanationHi":"360 डिग्री / 24 घंटे = 15 डिग्री प्रति घंटा। 60 मिनट / 15 डिग्री = 4 मिनट प्रति डिग्री।","explanationEn":"360 degrees / 24 hours = 15 degrees per hour. 60 mins / 15 degrees = 4 minutes per degree.","memoryTip":"1 डिग्री = 4 मिनट।","memoryTipEn":"Four minutes for one degree spin.","related":["Time Zones","Rotation of Earth","Greenwich Mean Time (GMT)"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xDQwRCyE3pGq41eZBfEhv', 'General Science', 'प्लास्टर ऑफ पेरिस (Plaster of Paris) किससे बनता है?', 'What is Plaster of Paris made from?', 'जिप्सम (Gypsum)', 'Gypsum', 90, 0, '{"facts":["जब जिप्सम को लगभग 150 डिग्री सेल्सियस पर गर्म किया जाता है, तो यह प्लास्टर ऑफ पेरिस बन जाता है।","इसका रासायनिक नाम कैल्शियम सल्फेट हेमीहाइड्रेट है।"],"factsEn":["When gypsum is heated to about 150°C, it becomes Plaster of Paris.","Its chemical name is Calcium Sulfate Hemihydrate."],"explanationHi":"पानी मिलाने पर यह वापस जिप्सम में बदल कर कठोर हो जाता है, जिसका उपयोग टूटी हड्डियों पर प्लास्टर चढ़ाने और मूर्तियां बनाने में होता है।","explanationEn":"On adding water, it sets into hard gypsum again, making it useful for medical casts for broken bones and making sculptures.","memoryTip":"प्लास्टर को ''जिप'' (Gypsum) कर दो ताकि हड्डी हिले नहीं।","memoryTipEn":"Gypsum gives plaster its power.","related":["Gypsum","Calcium Sulfate","Bone Fracture Cast"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GgKJRPJpxgUfZbdXnMNIn', 'General Science', 'हरे पौधों द्वारा भोजन बनाने की क्रिया क्या कहलाती है?', 'What is the process of making food by green plants called?', 'प्रकाश संश्लेषण (Photosynthesis)', 'Photosynthesis', 95, 0, '{"facts":["पौधे सूर्य के प्रकाश, कार्बन डाइऑक्साइड और पानी का उपयोग करके ग्लूकोज बनाते हैं।","इस प्रक्रिया में उप-उत्पाद (Byproduct) के रूप में ऑक्सीजन गैस निकलती है।"],"factsEn":["Plants use sunlight, carbon dioxide, and water to create glucose.","Oxygen gas is released as a byproduct in this process."],"explanationHi":"यह प्रक्रिया पौधों की पत्तियों में मौजूद क्लोरोफिल (हरे वर्णक) की सहायता से होती है।","explanationEn":"This process occurs with the help of Chlorophyll (green pigment) present in the leaves of plants.","memoryTip":"''प्रकाश'' से भोजन का ''संश्लेषण'' करना = प्रकाश संश्लेषण।","memoryTipEn":"Photo (Light) + Synthesis (Putting together).","related":["Chlorophyll","Stomata","Autotrophs"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FaM2Ev-rF4XNFlHJQAc47', 'General Science', 'दूध से क्रीम किस प्रक्रिया से बनाई जाती है?', 'By which process is cream separated from milk?', 'अपकेन्द्रिय बल (Centrifugal Force)', 'Centrifugal Force (Centrifugation)', 91, 0, '{"facts":["इस प्रक्रिया में दूध को एक मशीन (Centrifuge) में तेजी से घुमाया जाता है।","वाशिंग मशीन में कपड़े सुखाने वाला स्पिनर भी इसी सिद्धांत पर काम करता है।"],"factsEn":["In this process, milk is spun rapidly in a machine (Centrifuge).","The clothes dryer in a washing machine works on the same principle."],"explanationHi":"तेजी से घूमने पर भारी कण (पानी/स्किम्ड दूध) बाहर की ओर धकेले जाते हैं, और हल्की क्रीम केंद्र में जमा हो जाती है।","explanationEn":"Upon rapid spinning, heavier particles (water/skimmed milk) are pushed outwards, and lighter cream collects at the center.","memoryTip":"क्रीम ''केंद्र'' से ''अप'' (दूर) होकर अलग होती है।","memoryTipEn":"Centrifuge spins out the cream.","related":["Centrifugation","Centripetal Force","Washing Machine Spinner"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AWvPl2zrxnQkJm73mtVRZ', 'General Knowledge', 'रिजर्व बैंक आफ इण्डिया (RBI) का मुख्यालय कहाँ है?', 'Where is the headquarters of the Reserve Bank of India (RBI)?', 'मुंबई', 'Mumbai', 92, 0, '{"facts":["RBI की स्थापना 1 अप्रैल 1935 को हुई थी।","शुरुआत में इसका मुख्यालय कोलकाता में था, जिसे 1937 में मुंबई स्थानांतरित कर दिया गया।"],"factsEn":["RBI was established on April 1, 1935.","Initially, the headquarters was in Kolkata, which was moved to Mumbai in 1937."],"explanationHi":"यह भारत का केंद्रीय बैंक है जो रुपये के जारी होने और आपूर्ति को नियंत्रित करता है।","explanationEn":"It is India''s central bank, which controls the issue and supply of the Indian rupee.","memoryTip":"भारत का ''वित्तीय'' केंद्र (मुंबई) ही RBI का घर है।","memoryTipEn":"Money resides in Mumbai.","related":["Shaktikanta Das","Central Bank","Monetary Policy"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9EjF9EmSWOQZVbpkneIBM', 'General Knowledge', 'किसे ''सीमांत गाँधी'' (Frontier Gandhi) कहा जाता है?', 'Who is known as the ''Frontier Gandhi'' (Simant Gandhi)?', 'खान अब्दुल गफ्फार खान', 'Khan Abdul Ghaffar Khan', 94, 0, '{"facts":["वे भारत रत्न (1987) पाने वाले पहले विदेशी नागरिक थे।","उन्होंने ''खुदाई खिदमतगार'' (ईश्वर के सेवक) नामक अहिंसक आंदोलन की स्थापना की थी।"],"factsEn":["He was the first foreigner to receive the Bharat Ratna (1987).","He founded the non-violent movement called ''Khudai Khidmatgar'' (Servants of God)."],"explanationHi":"महात्मा गांधी के अहिंसा के सिद्धांतों के प्रति उनकी गहरी निष्ठा के कारण उन्हें उत्तर-पश्चिम सीमांत प्रांत में यह उपाधि मिली।","explanationEn":"He earned this title in the North-West Frontier Province due to his deep devotion to Mahatma Gandhi''s principles of non-violence.","memoryTip":"भारत की सीमा के अंत (सीमांत) पर गफ्फार खान गांधीजी की तरह थे।","memoryTipEn":"Ghaffar Khan stood at the frontier of peace.","related":["Khudai Khidmatgar","Red Shirts","Bharat Ratna"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Dd1NzMpH357rISr-fkMI6', 'General Knowledge', 'विश्व का सबसे बड़ा द्वीप (Island) कौन सा है?', 'Which is the largest island in the world?', 'ग्रीनलैंड (Greenland)', 'Greenland', 89, 0, '{"facts":["यह उत्तरी अमेरिका महाद्वीप के पास स्थित है लेकिन राजनीतिक रूप से डेनमार्क का एक स्वायत्त क्षेत्र है।","इसका लगभग 80% हिस्सा बर्फ से ढका है।"],"factsEn":["It is located near the North American continent but is politically an autonomous territory of Denmark.","About 80% of its landmass is covered by ice."],"explanationHi":"ऑस्ट्रेलिया को एक द्वीप के बजाय महाद्वीप माना जाता है, इसलिए ग्रीनलैंड दुनिया का सबसे बड़ा द्वीप है।","explanationEn":"Australia is considered a continent rather than an island, making Greenland the largest island in the world.","memoryTip":"नाम ''ग्रीन'' (हरा) है, लेकिन है पूरा बर्फीला और सबसे बड़ा।","memoryTipEn":"Greenland is a massive white island.","related":["Denmark","New Guinea (2nd Largest Island)","Arctic Ocean"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gPGzQfq0Eru99au3MhnPO', 'General Knowledge', 'स्वतन्त्र भारत के प्रथम राष्ट्रपति कौन थे?', 'Who was the first President of independent India?', 'डॉ. राजेन्द्र प्रसाद', 'Dr. Rajendra Prasad', 96, 0, '{"facts":["वे लगातार दो बार राष्ट्रपति चुने जाने वाले एकमात्र व्यक्ति हैं (1950–1962)।","वे भारत की संविधान सभा के स्थायी अध्यक्ष भी थे।"],"factsEn":["He is the only person to be elected President twice consecutively (1950–1962).","He was also the permanent President of the Constituent Assembly of India."],"explanationHi":"स्वतंत्रता संग्राम के दौरान उन्होंने चंपारण सत्याग्रह में महात्मा गांधी के साथ महत्वपूर्ण भूमिका निभाई थी।","explanationEn":"During the freedom struggle, he played a crucial role alongside Mahatma Gandhi in the Champaran Satyagraha.","memoryTip":"संविधान सभा के अध्यक्ष को ही पहले राष्ट्रपति का ''प्रसाद'' मिला।","memoryTipEn":"Rajendra Prasad presided over the new republic.","related":["Constituent Assembly","First President of India","Bihar Gandhi"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1--dfYaO7zi2Q2J5fagz8', 'General Science', 'काली मिट्टी (Black Soil) किस फसल के लिए सर्वाधिक उपयुक्त है?', 'Black soil is most suitable for which crop?', 'कपास (Cotton)', 'Cotton', 95, 0, '{"facts":["इसे ''रेगुर मिट्टी'' (Regur Soil) या ब्लैक कॉटन सॉयल भी कहा जाता है।","यह मुख्य रूप से दक्कन के पठार (महाराष्ट्र, गुजरात) में पाई जाती है।"],"factsEn":["It is also known as ''Regur Soil'' or Black Cotton Soil.","It is mainly found in the Deccan Plateau region (Maharashtra, Gujarat)."],"explanationHi":"यह मिट्टी नमी बनाए रखने (Moisture retention) में बहुत अच्छी होती है, जो कपास की खेती के लिए आदर्श है।","explanationEn":"This soil is highly retentive of moisture, which is ideal for the cultivation of cotton.","memoryTip":"काली मिट्टी से ''सफेद'' कपास खिलता है।","memoryTipEn":"Black soil yields white cotton.","related":["Regur Soil","Deccan Plateau","Moisture Retention"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('X2lKq3-HEZafVurOERCyU', 'General Knowledge', 'कौन-सा विदेशी आक्रमणकारी ''कोहिनूर हीरा'' एवं ''मयूर सिंहासन'' (Peacock Throne) लूटकर अपने साथ स्वदेश ले गया?', 'Which foreign invader looted and took away the ''Kohinoor Diamond'' and the ''Peacock Throne''?', 'नादिरशाह', 'Nader Shah', 93, 0, '{"facts":["उसने 1739 में करनाल के युद्ध में मुगलों को हराया और दिल्ली को लूटा।","वह फारस (ईरान) का शासक था।"],"factsEn":["He defeated the Mughals at the Battle of Karnal in 1739 and sacked Delhi.","He was the ruler of Persia (Iran)."],"explanationHi":"नादिरशाह की लूट ने मुगल साम्राज्य की बची-खुची प्रतिष्ठा और धन को पूरी तरह से नष्ट कर दिया था।","explanationEn":"Nader Shah''s plunder completely shattered the remaining prestige and wealth of the Mughal Empire.","memoryTip":"नादिरशाह ''नादिर'' (दुर्लभ) चीजें (कोहिनूर) ले गया।","memoryTipEn":"Nader Shah nabbed the diamond.","related":["Battle of Karnal 1739","Kohinoor Diamond","Peacock Throne (Takht-e-Taus)"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2TGuug83ccbLShMLCKYcj', 'General Knowledge', 'भारत में सबसे पुरानी पर्वत श्रृंखला कौन सी है?', 'Which is the oldest mountain range in India?', 'अरावली पर्वतमाला', 'Aravalli Range', 94, 0, '{"facts":["यह मुख्य रूप से राजस्थान राज्य को पार करती हुई दिल्ली से गुजरात तक फैली है।","अरावली की सबसे ऊँची चोटी ''गुरु शिखर'' (माउंट आबू) है।"],"factsEn":["It primarily runs through Rajasthan, stretching from Delhi to Gujarat.","The highest peak of the Aravallis is ''Guru Shikhar'' (Mount Abu)."],"explanationHi":"ये अवशिष्ट पहाड़ (Residual mountains) हैं जो लाखों वर्षों के अपरदन (Erosion) के कारण घिस गए हैं।","explanationEn":"These are residual mountains that have been worn down by millions of years of erosion.","memoryTip":"अरावली सबसे ''अरा'' (प्राचीन) है।","memoryTipEn":"Aravalli is Ancient.","related":["Guru Shikhar","Residual Mountains","Rajasthan"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UEZAguFiTDhsNEkGWOY-A', 'General Science', 'धरती के तल का लगभग कितने प्रतिशत पानी है?', 'Approximately what percentage of the Earth''s surface is covered with water?', '71%', '71%', 90, 0, '{"facts":["इस 71% पानी में से लगभग 96.5% पानी महासागरों में (खारा पानी) है।","केवल लगभग 2.5% पानी ही मीठा (Freshwater) है।"],"factsEn":["Of this 71%, about 96.5% of the water is in the oceans (saltwater).","Only about 2.5% of the water is freshwater."],"explanationHi":"इतने अधिक पानी की मौजूदगी के कारण ही अंतरिक्ष से देखने पर पृथ्वी नीली दिखाई देती है (Blue Planet)।","explanationEn":"Because of the presence of so much water, the Earth appears blue when viewed from space (Blue Planet).","memoryTip":"पृथ्वी का ''तीन-चौथाई'' (लगभग 71%) हिस्सा पानी है।","memoryTipEn":"71 parts water, 29 parts land.","related":["Blue Planet","Freshwater Percentage","Hydrosphere"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XQAWIZibnM1a8tXASBeJJ', 'General Knowledge', 'भारत की सबसे लम्बी स्थलीय सीमा (Land border) किस देश से लगती है?', 'With which country does India share its longest land border?', 'बांग्लादेश', 'Bangladesh', 96, 0, '{"facts":["यह सीमा 4,096.7 किलोमीटर लंबी है।","पश्चिम बंगाल, असम, मेघालय, त्रिपुरा और मिजोरम राज्य बांग्लादेश के साथ सीमा साझा करते हैं।"],"factsEn":["This border is 4,096.7 kilometers long.","West Bengal, Assam, Meghalaya, Tripura, and Mizoram share a border with Bangladesh."],"explanationHi":"मानचित्र पर चीन या पाकिस्तान की सीमा लंबी लग सकती है, लेकिन बांग्लादेश की सीमा बहुत घुमावदार है, जिससे इसकी कुल लंबाई सबसे अधिक हो जाती है।","explanationEn":"China or Pakistan might look longer on a map, but the Bangladesh border is highly convoluted, making its total length the longest.","memoryTip":"भारत के बगल में बैठा ''बांग्ला'' सबसे लंबी दीवार साझा करता है।","memoryTipEn":"Bangladesh border winds the longest.","related":["China Border (2nd Longest)","Pakistan Border (3rd Longest)","Zero Line (Tripura)"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uX-8IhItBRw4HnlFomgqP', 'General Science', 'हमारे सौर मण्डल का सबसे बड़ा ग्रह कौनसा है?', 'Which is the largest planet in our solar system?', 'बृहस्पति (Jupiter)', 'Jupiter', 92, 0, '{"facts":["यह एक ''गैस दानव'' (Gas Giant) है, जिसका कोई ठोस धरातल नहीं है।","इसका सबसे बड़ा उपग्रह ''गैनीमीड'' (Ganymede) है, जो सौरमंडल का भी सबसे बड़ा उपग्रह है।"],"factsEn":["It is a ''Gas Giant'' with no solid surface.","Its largest moon is ''Ganymede'', which is also the largest moon in the solar system."],"explanationHi":"बृहस्पति इतना विशाल है कि सौरमंडल के बाकी सभी ग्रहों को मिलाने पर भी इसका द्रव्यमान उनसे दोगुना से अधिक है।","explanationEn":"Jupiter is so massive that its mass is more than twice that of all the other planets in the solar system combined.","memoryTip":"बृहस्पति सबसे ''बृहद'' (विशाल) है।","memoryTipEn":"Jupiter is the giant of the system.","related":["Gas Giants","Ganymede","Great Red Spot"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9fSw-4dulIUmZyzvsyPUs', 'General Knowledge', 'किस नदी को ''बिहार का शोक'' (Sorrow of Bihar) कहा जाता है?', 'Which river is known as the ''Sorrow of Bihar''?', 'कोसी', 'Kosi', 94, 0, '{"facts":["यह नदी नेपाल से निकलती है और बिहार में प्रवेश करती है।","यह अपने मार्ग बदलने (Shifting of course) के लिए कुख्यात है।"],"factsEn":["This river originates in Nepal and enters Bihar.","It is notorious for shifting its course."],"explanationHi":"बारिश के मौसम में यह नदी बार-बार अपना रास्ता बदलती है, जिससे बिहार में भयंकर बाढ़ और विनाश होता है।","explanationEn":"During the rainy season, this river frequently changes its path, causing severe floods and destruction in Bihar.","memoryTip":"बिहार के लोग बाढ़ आने पर इसे ''कोसते'' हैं (कोसी)।","memoryTipEn":"Kosi causes chaos in Bihar.","related":["Damodar River (Sorrow of Bengal)","Brahmaputra (Sorrow of Assam)"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KNy1nS7q1HawpgNcAs7m9', 'General Science', 'गैस सिलेंडरों से गैस लीकेज का पता लगाने के लिए उसमे किस गंध युक्त पदार्थ को मिलाया जाता है?', 'Which odorant substance is added to gas cylinders to detect gas leakage?', 'इथाइल मर्केप्टेन (Ethyl Mercaptan)', 'Ethyl Mercaptan', 96, 0, '{"facts":["LPG (तरलीकृत पेट्रोलियम गैस) मूल रूप से रंगहीन और गंधहीन होती है।","इथाइल मर्केप्टेन (Ethanethiol) की गंध सड़े हुए पत्तागोभी या लहसुन जैसी होती है।"],"factsEn":["LPG (Liquefied Petroleum Gas) is naturally colorless and odorless.","Ethyl Mercaptan (Ethanethiol) has a smell similar to rotting cabbage or garlic."],"explanationHi":"सुरक्षा के लिए इसे LPG में मिलाया जाता है, ताकि रिसाव होने पर इसकी तेज गंध से तुरंत पता चल सके और हादसों से बचा जा सके।","explanationEn":"It is added to LPG as a safety measure so that leaks can be immediately detected by its strong smell, preventing accidents.","memoryTip":"गैस लीक पर ''मर'' (Mercaptan) सकते हैं, इसलिए इसे मिलाते हैं।","memoryTipEn":"Mercaptan makes the gas smell.","related":["LPG (Butane and Propane)","Ethanethiol"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dmOgmQNcsg9QIuVzAU7Op', 'General Science', 'वायुमंडल में सबसे अधिक किस गैस का प्रतिशत है?', 'Which gas has the highest percentage in the atmosphere?', 'नाइट्रोजन', 'Nitrogen', 93, 0, '{"facts":["पृथ्वी के वायुमंडल में लगभग 78% नाइट्रोजन (N2) है।","ऑक्सीजन दूसरी सबसे प्रचुर गैस है (लगभग 21%)।"],"factsEn":["Earth''s atmosphere contains about 78% Nitrogen (N2).","Oxygen is the second most abundant gas (approx 21%)."],"explanationHi":"नाइट्रोजन एक अक्रिय (Inert) गैस की तरह काम करती है, जो दहन (Combustion) को नियंत्रित रखती है; यदि केवल ऑक्सीजन होती तो आग बुझाना मुश्किल होता।","explanationEn":"Nitrogen acts somewhat like an inert gas, diluting oxygen and preventing rapid combustion; if there were only oxygen, fires would be hard to control.","memoryTip":"हवा में सबसे ज्यादा ''नाइट'' (Nitrogen) का राज है (78%)।","memoryTipEn":"Nitrogen is number one in the air.","related":["Oxygen","Argon (3rd most abundant)","Atmosphere Composition"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kjPmXVoydpKMBp8Id0XXq', 'General Knowledge', 'कोणार्क का सूर्य मन्दिर (Sun Temple) किस प्रदेश में स्थित है?', 'In which state is the Sun Temple of Konark located?', 'ओड़िसा (Odisha)', 'Odisha', 95, 0, '{"facts":["इसे ''ब्लैक पैगोडा'' (Black Pagoda) भी कहा जाता है।","इसका निर्माण 13वीं शताब्दी में गंग वंश के राजा नरसिंहदेव प्रथम ने करवाया था।"],"factsEn":["It is also known as the ''Black Pagoda''.","It was built in the 13th century by King Narasimhadeva I of the Eastern Ganga Dynasty."],"explanationHi":"यह मंदिर सूर्य देवता के रथ के आकार में बनाया गया है, जिसमें 24 पहिए और 7 घोड़े उकेरे गए हैं।","explanationEn":"The temple is designed in the shape of a colossal chariot of the Sun God, with 24 carved wheels and 7 horses.","memoryTip":"सूर्य की किरण ''कोने-कोने'' (कोणार्क) तक ''उड़'' (ओडिशा) कर आती है।","memoryTipEn":"Sun shines on Konark in Odisha.","related":["Black Pagoda","King Narasimhadeva I","UNESCO World Heritage Site"]}', 'published', 1776083493, 1776083493);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HaWEL9Ft56khA6LmuvZdG', 'General Knowledge', 'किस देश से अलग होकर वर्ष 1971 में बांग्लादेश का निर्माण हुआ था?', 'From which country did Bangladesh separate to become an independent nation in 1971?', 'पाकिस्तान', 'Pakistan', 96, 0, '{"facts":["इसे पहले ''पूर्वी पाकिस्तान'' (East Pakistan) के नाम से जाना जाता था।","1971 के भारत-पाकिस्तान युद्ध के बाद बांग्लादेश एक स्वतंत्र देश बना।"],"factsEn":["It was previously known as ''East Pakistan''.","Bangladesh became an independent country after the 1971 India-Pakistan war."],"explanationHi":"शेख मुजीबुर रहमान के नेतृत्व में स्वतंत्रता संग्राम और भारतीय सेना की मदद से 1971 में बांग्लादेश का उदय हुआ।","explanationEn":"Bangladesh emerged in 1971 through a liberation war led by Sheikh Mujibur Rahman, aided by the Indian Army.","memoryTip":"पाकिस्तान के दो टुकड़े हुए, और ''बांग्ला''देश बना।","memoryTipEn":"East Pakistan became Bangladesh in 1971.","related":["1971 Indo-Pak War","Mukti Bahini","Sheikh Mujibur Rahman"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('R08R2n8Guc8mbSFxN2u0b', 'General Science', 'कंप्यूटर भाषा में WWW का अर्थ क्या है?', 'What does WWW stand for in computer language?', 'World Wide Web', 'World Wide Web', 95, 0, '{"facts":["इसकी खोज 1989 में ब्रिटिश वैज्ञानिक टिम बर्नर्स-ली ने की थी।","यह इंटरनेट पर मौजूद सभी पब्लिक वेबसाइट्स का एक नेटवर्क है।"],"factsEn":["It was invented by British scientist Tim Berners-Lee in 1989.","It is a network of all public websites available on the internet."],"explanationHi":"यह एक सूचना प्रणाली (Information System) है जहां दस्तावेजों और अन्य वेब संसाधनों को URL द्वारा पहचाना जाता है।","explanationEn":"It is an information system where documents and other web resources are identified by URLs.","memoryTip":"दुनिया (World) भर में फैला जाल (Web) = WWW।","memoryTipEn":"Web that is World Wide.","related":["Tim Berners-Lee","HTTP","URL"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XtY-Ik_b2JuOitZM0DJRg', 'General Science', 'एक किलोबाइट (KB) में कितनी बाइट होती है?', 'How many bytes are there in one Kilobyte (KB)?', '1024 बाइट', '1024 bytes', 93, 0, '{"facts":["1 मेगाबाइट (MB) में 1024 किलोबाइट (KB) होते हैं।","कंप्यूटर की सबसे छोटी इकाई बिट (Bit) होती है (8 bits = 1 Byte)।"],"factsEn":["1 Megabyte (MB) contains 1024 Kilobytes (KB).","The smallest unit of a computer is a Bit (8 bits = 1 Byte)."],"explanationHi":"कंप्यूटर मेमोरी द्विआधारी (Binary) प्रणाली पर काम करती है, इसलिए यह 1000 के बजाय 2 की घात 10 (2^10 = 1024) का उपयोग करती है।","explanationEn":"Computer memory works on a binary system, so it uses 2 to the power of 10 (2^10 = 1024) instead of 1000.","memoryTip":"एक किलो (कंप्यूटर में) 1000 नहीं, 1024 होता है।","memoryTipEn":"Computers count in powers of 2 (1024).","related":["Megabyte (MB)","Gigabyte (GB)","Binary System"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wxgaMOvosrdlYYXZRdy05', 'General Knowledge', 'भारतीय राष्ट्रीय कांग्रेस के 1929 के ऐतिहासिक अधिवेशन की अध्यक्षता किसने की?', 'Who presided over the historic 1929 session of the Indian National Congress?', 'जवाहरलाल नेहरू', 'Jawaharlal Nehru', 98, 0, '{"facts":["यह अधिवेशन लाहौर में रावी नदी के तट पर हुआ था।","इसी अधिवेशन में पहली बार ''पूर्ण स्वराज'' (Complete Independence) का प्रस्ताव पारित किया गया था।"],"factsEn":["This session was held in Lahore on the banks of the Ravi river.","The resolution for ''Purna Swaraj'' (Complete Independence) was passed here for the first time."],"explanationHi":"नेहरू जी की अध्यक्षता में 26 जनवरी 1930 को पहला स्वतंत्रता दिवस मनाने का निर्णय लिया गया था, जिसके कारण बाद में इसी दिन गणतंत्र दिवस लागू हुआ।","explanationEn":"Under Nehru''s presidency, it was decided to celebrate Jan 26, 1930, as Independence Day, which later became Republic Day.","memoryTip":"29 में ''नेहरू'' ने लाहौर में पूर्ण आज़ादी की मांग की।","memoryTipEn":"Nehru led the 1929 Lahore leap.","related":["Purna Swaraj","Lahore Session 1929","Republic Day"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('eCH3jfa5HUNKLjCI9FcZ6', 'General Knowledge', 'केन्द्रीय असेम्बली में बम फेंकने में भगत सिंह का साथी कौन था?', 'Who was Bhagat Singh''s companion in throwing the bomb in the Central Assembly?', 'बटुकेश्वर दत्त', 'Batukeshwar Dutt', 94, 0, '{"facts":["यह घटना 8 अप्रैल 1929 को दिल्ली की सेंट्रल असेंबली में हुई थी।","उन्होंने जन सुरक्षा विधेयक (Public Safety Bill) और व्यापार विवाद विधेयक के विरोध में बम फेंका था।"],"factsEn":["This incident occurred on April 8, 1929, in the Central Assembly in Delhi.","They threw the bomb to protest the Public Safety Bill and the Trade Dispute Act."],"explanationHi":"उनका उद्देश्य किसी को मारना नहीं था, बल्कि बहरी ब्रिटिश सरकार को सुनाना था। बम फेंकने के बाद उन्होंने खुद गिरफ्तारी दी।","explanationEn":"Their intention was not to kill, but ''to make the deaf hear''. They courted arrest after throwing the bomb.","memoryTip":"भगत और ''बटुक'' ने बम से धमाका किया।","memoryTipEn":"Bhagat and Batukeshwar bombed the assembly.","related":["Bhagat Singh","Public Safety Bill","Inquilab Zindabad"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lFemu8ZCNAyJsDuKpkjRf', 'General Knowledge', 'मुस्लिम लीग ने भारत विभाजन की मांग सबसे पहले कब की थी?', 'When did the Muslim League first demand the partition of India?', '1940 में', 'In 1940', 93, 0, '{"facts":["यह मांग मुस्लिम लीग के लाहौर अधिवेशन (23 मार्च 1940) में की गई थी।","इसे ''लाहौर प्रस्ताव'' या ''पाकिस्तान प्रस्ताव'' भी कहा जाता है।"],"factsEn":["This demand was made in the Lahore Session of the Muslim League (March 23, 1940).","It is also known as the ''Lahore Resolution'' or ''Pakistan Resolution''."],"explanationHi":"मुहम्मद अली जिन्ना के नेतृत्व में यह प्रस्ताव पारित किया गया कि मुसलमानों के लिए एक अलग स्वतंत्र राज्य होना चाहिए।","explanationEn":"Under Muhammad Ali Jinnah''s leadership, a resolution was passed demanding a separate independent state for Muslims.","memoryTip":"40 (चालीस) में जिन्ना की ''चाल'' से विभाजन की मांग उठी।","memoryTipEn":"1940: Lahore Resolution for Pakistan.","related":["Lahore Resolution","Muhammad Ali Jinnah","Two-Nation Theory"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6TZsS23hRme5Keh8TxiIS', 'General Knowledge', 'काँमनवील पत्रिका का प्रकाशन किसने किया था?', 'Who published the ''Commonweal'' magazine?', 'ऐनी बेसेन्ट ने', 'Annie Besant', 90, 0, '{"facts":["यह एक साप्ताहिक अंग्रेजी अखबार था जिसकी शुरुआत 1914 में हुई थी।","ऐनी बेसेंट ने ''न्यू इंडिया'' नामक एक अन्य दैनिक समाचार पत्र भी शुरू किया था।"],"factsEn":["It was a weekly English newspaper started in 1914.","Annie Besant also started another daily newspaper named ''New India''."],"explanationHi":"इन पत्रिकाओं का उपयोग उन्होंने भारतीय होम रूल लीग आंदोलन के प्रचार-प्रसार और भारतीय राजनीति में स्वशासन की मांग के लिए किया।","explanationEn":"She used these publications to propagate the Indian Home Rule League movement and demand self-government.","memoryTip":"कॉमन (Common) लोगों के लिए ''बेसेंट'' (Besant) ने पत्रिका निकाली।","memoryTipEn":"Besant brought the Commonweal.","related":["Home Rule League","New India (Newspaper)","Theosophical Society"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JWhaCdpk-ZgbBajYYrQX-', 'General Knowledge', 'किस एकमात्र भारतीय को अर्थशास्त्र में नोबेल पुरस्कार मिला है? (पीडीएफ स्रोत के अनुसार)', 'Who is the only Indian (as per PDF source) to receive the Nobel Prize in Economics?', 'अमर्त्य सेन', 'Amartya Sen', 95, 0, '{"facts":["उन्हें 1998 में कल्याणकारी अर्थशास्त्र (Welfare Economics) के लिए यह पुरस्कार मिला था।","नोट: 2019 में एक और भारतीय मूल के व्यक्ति ''अभिजीत बनर्जी'' को भी अर्थशास्त्र का नोबेल मिला है।"],"factsEn":["He received this award in 1998 for Welfare Economics.","Note: In 2019, another Indian-origin person, ''Abhijit Banerjee'', also won the Nobel in Economics."],"explanationHi":"उनके शोध ने अकाल के कारणों और गरीबी से निपटने के तरीकों को समझने में महत्वपूर्ण योगदान दिया।","explanationEn":"His research significantly contributed to understanding the causes of famine and ways to tackle poverty.","memoryTip":"अर्थ (धन) कमाकर व्यक्ति ''अमर'' (अमर्त्य) होना चाहता है।","memoryTipEn":"Amartya makes sense of Economics.","related":["Welfare Economics","Abhijit Banerjee","Poverty and Famines"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5sgWrz4MyaC70E33rrSgI', 'General Knowledge', '1856 में विधवा पुनर्विवाह क़ानून किसके प्रयासों से बनाया गया था?', 'Through whose efforts was the Widow Remarriage Act enacted in 1856?', 'ईश्वरचंद्र विद्यासागर के प्रयासों से', 'Through the efforts of Ishwar Chandra Vidyasagar', 96, 0, '{"facts":["हिंदू विधवा पुनर्विवाह अधिनियम (Hindu Widow Remarriage Act) 1856 में लॉर्ड डलहौजी के समय में तैयार हुआ और लॉर्ड कैनिंग द्वारा पारित किया गया।","विद्यासागर जी ने प्राचीन संस्कृत ग्रंथों का हवाला देकर साबित किया कि विधवा विवाह शास्त्र-सम्मत है।"],"factsEn":["The Hindu Widow Remarriage Act was drafted by Lord Dalhousie and passed by Lord Canning in 1856.","Vidyasagar cited ancient Sanskrit texts to prove that widow remarriage is permitted by scriptures."],"explanationHi":"उस समय हिंदू समाज में विधवाओं की स्थिति बहुत दयनीय थी, इस कानून ने उन्हें कानूनी रूप से फिर से शादी करने का अधिकार दिया।","explanationEn":"The condition of widows in Hindu society was miserable then; this act legally allowed them to remarry.","memoryTip":"विधवाओं के लिए ''ईश्वर'' बनकर आए विद्यासागर।","memoryTipEn":"Vidyasagar validated widow remarriage.","related":["Lord Canning","Hindu Widow Remarriage Act 1856","Social Reformers"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JNTMoHtN4OLUGu7_9BK8f', 'General Knowledge', 'लॉर्ड कैनिंग ने नवंबर 1858 में कहाँ आयोजित दरबार में भारत में क्राउन के शासन की घोषणा की?', 'Where did Lord Canning announce the assumption of the Government of India by the Crown in the Durbar held in November 1858?', 'इलाहाबाद में आयोजित दरबार में', 'In the Durbar held at Allahabad', 94, 0, '{"facts":["इसे ''इलाहाबाद घोषणापत्र'' भी कहा जाता है, जहाँ रानी विक्टोरिया का उद्घोषणा पत्र पढ़ा गया था।","इसके साथ ही ईस्ट इंडिया कंपनी का शासन समाप्त हो गया।"],"factsEn":["It is also known as the ''Allahabad Declaration'', where Queen Victoria''s Proclamation was read.","With this, the rule of the East India Company came to an end."],"explanationHi":"1857 के विद्रोह के बाद, भारत का सीधा नियंत्रण ब्रिटिश राजशाही (ब्रिटिश क्राउन) के हाथों में चला गया और गवर्नर जनरल को ''वायसराय'' कहा जाने लगा।","explanationEn":"Following the 1857 revolt, direct control of India passed to the British Crown, and the Governor-General was redesignated as the ''Viceroy''.","memoryTip":"1858 में ''इलाहाबाद'' में कंपनी का राज ''आबाद'' से बर्बाद हो गया।","memoryTipEn":"Allahabad announced the Crown''s crown.","related":["Queen Victoria''s Proclamation","Government of India Act 1858","Revolt of 1857"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JpjZuVnfwB7SsJdS42f86', 'General Knowledge', 'लॉर्ड वेलेजली के साथ सबसे पहले सहायक संधि किस राज्य के शासक ने की?', 'The ruler of which state was the first to enter into a Subsidiary Alliance with Lord Wellesley?', 'हैदराबाद के निजाम ने', 'The Nizam of Hyderabad', 96, 0, '{"facts":["निजाम ने 1798 में सहायक संधि (Subsidiary Alliance) पर हस्ताक्षर किए थे।","सहायक संधि भारत में ब्रिटिश साम्राज्य के विस्तार की एक महत्वपूर्ण नीति थी।"],"factsEn":["The Nizam signed the Subsidiary Alliance in 1798.","The Subsidiary Alliance was a crucial policy for the expansion of the British Empire in India."],"explanationHi":"इस संधि के तहत भारतीय शासकों को अपनी स्वतंत्र सेना भंग करनी पड़ती थी और ब्रिटिश सेना को अपने राज्य में रखकर उसका खर्च उठाना पड़ता था।","explanationEn":"Under this alliance, Indian rulers had to disband their independent armies and maintain British troops in their states at their own expense.","memoryTip":"अंग्रेजों की ''सहायता'' सबसे पहले ''हैदराबाद'' ने ली।","memoryTipEn":"Hyderabad yielded first to Wellesley.","related":["Subsidiary Alliance","Lord Wellesley","Nizam Ali Khan"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lhbxQo5DPNLOqtOJzaM-P', 'General Knowledge', 'भारत की सर्वाधिक बड़ी जनजाति कौनसी है?', 'Which is the largest tribe in India?', 'गोंड (पीडीएफ स्रोत अनुसार)', 'Gond (As per PDF source)', 91, 0, '{"facts":["नोट: 2011 की जनगणना के नवीनतम आंकड़ों के अनुसार ''भील'' (Bhil) भारत की सबसे बड़ी जनजाति है, और गोंड दूसरे स्थान पर हैं।","गोंड जनजाति मुख्य रूप से मध्य प्रदेश, छत्तीसगढ़, और महाराष्ट्र में पाई जाती है।"],"factsEn":["Note: As per the latest 2011 census, ''Bhil'' is the largest tribe in India, and Gond is second.","The Gond tribe is mainly found in MP, Chhattisgarh, and Maharashtra."],"explanationHi":"चूँकि स्रोत सामग्री पुरानी हो सकती है, इसलिए ''गोंड'' उत्तर दिया गया है, परन्तु वर्तमान में भील सबसे बड़ी जनजाति है।","explanationEn":"Since the source material might be older, ''Gond'' is given as the answer, but currently, Bhil is the largest tribe.","memoryTip":"भील और गोंड भारत की ''विशाल'' (बड़ी) जनजातियाँ हैं।","memoryTipEn":"Gond was the largest, now it''s Bhil.","related":["Bhil Tribe","Scheduled Tribes of India","Gondwana"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lw84dB3jb57FXz2LVP-Wi', 'General Knowledge', 'भारतीय राष्ट्रीय कांग्रेस की प्रथम महिला अध्यक्ष कौन थी?', 'Who was the first woman President of the Indian National Congress?', 'ऐनी बेसेन्ट', 'Annie Besant', 95, 0, '{"facts":["उन्होंने 1917 के कलकत्ता अधिवेशन की अध्यक्षता की थी।","यदि ''प्रथम भारतीय महिला अध्यक्ष'' पूछा जाए, तो उत्तर ''सरोजिनी नायडू'' (1925) होगा।"],"factsEn":["She presided over the Calcutta session in 1917.","If asked for the ''first Indian woman president'', the answer is ''Sarojini Naidu'' (1925)."],"explanationHi":"वे एक आयरिश मूल की समाजसेविका थीं, जिन्होंने भारत के स्वतंत्रता संग्राम और होम रूल आंदोलन में बड़ी भूमिका निभाई।","explanationEn":"She was an Irish-born social worker who played a major role in the Indian freedom struggle and the Home Rule Movement.","memoryTip":"कांग्रेस की पहली महिला अध्यक्ष कोई विदेशी ''बेस'' (Besant) से थीं।","memoryTipEn":"Annie was the first, Sarojini was the first Indian.","related":["Sarojini Naidu","Home Rule League","Theosophical Society"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AgzyS-qdL7dehuTrLih7L', 'General Knowledge', '''शहीद-ए-आजम'' के नाम से कौन जाने जाते हैं?', 'Who is known by the name ''Shaheed-e-Azam''?', 'भगत सिंह', 'Bhagat Singh', 97, 0, '{"facts":["उन्हें 23 मार्च 1931 को राजगुरु और सुखदेव के साथ फांसी दी गई थी।","उन्होंने ''नौजवान भारत सभा'' की स्थापना की थी।"],"factsEn":["He was hanged on March 23, 1931, along with Rajguru and Sukhdev.","He founded the ''Naujawan Bharat Sabha''."],"explanationHi":"''शहीद-ए-आजम'' का अर्थ है महान शहीद (Great Martyr)। उनके बलिदान ने भारतीय युवाओं में आज़ादी की लौ को भड़का दिया था।","explanationEn":"''Shaheed-e-Azam'' translates to Great Martyr. His sacrifice ignited the flame of freedom among Indian youth.","memoryTip":"देश के सबसे ''आज़म'' (महान) शहीद भगत सिंह थे।","memoryTipEn":"Azam means greatest; Bhagat Singh is the greatest martyr.","related":["Inquilab Zindabad","Rajguru and Sukhdev","Lahore Conspiracy Case"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ecG8k43Xb8qqk3jydmjqN', 'General Knowledge', 'किस योजना के फलस्वरूप भारत का विभाजन हुआ?', 'As a result of which plan was India partitioned?', 'माउंटबेटन योजना के फलस्वरूप', 'Mountbatten Plan', 96, 0, '{"facts":["इस योजना की घोषणा 3 जून 1947 को की गई थी, इसलिए इसे ''3 जून योजना'' भी कहते हैं।","लॉर्ड माउंटबेटन भारत के अंतिम वायसराय थे।"],"factsEn":["This plan was announced on June 3, 1947, so it''s also called the ''3 June Plan''.","Lord Mountbatten was the last Viceroy of India."],"explanationHi":"इसी योजना के आधार पर भारतीय स्वतंत्रता अधिनियम 1947 पारित किया गया, जिसने भारत को दो स्वतंत्र देशों (भारत और पाकिस्तान) में विभाजित किया।","explanationEn":"Based on this plan, the Indian Independence Act 1947 was passed, dividing India into two independent dominions (India and Pakistan).","memoryTip":"''माउंट'' (पहाड़) जैसी समस्या को विभाजन से ''बांट'' (बेटन) दिया।","memoryTipEn":"Mountbatten battened down the borders.","related":["Indian Independence Act 1947","Radcliffe Line","Lord Mountbatten"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Oze-NzKNo21HR98UkJmz-', 'General Knowledge', 'जनरल डायर (जलियाँवाला बाग हत्याकांड से जुड़े) की हत्या किसने की थी?', 'Who assassinated General Dyer (associated with the Jallianwala Bagh massacre)?', 'उधम सिंह ने', 'Udham Singh', 93, 0, '{"facts":["उन्होंने 13 मार्च 1940 को लंदन के कैक्सटन हॉल (Caxton Hall) में माइकल ओ''ड्वायर को गोली मारी थी।","(ध्यान दें: उधम सिंह ने माइकल ओ''ड्वायर को मारा था, जो पंजाब का लेफ्टिनेंट गवर्नर था, न कि कर्नल रेजिनाल्ड डायर को, जिसने गोलियां चलवाई थीं। लेकिन अक्सर आम भाषा में इसे डायर की हत्या कहा जाता है।)"],"factsEn":["He shot Michael O''Dwyer in Caxton Hall, London, on March 13, 1940.","(Note: Udham Singh actually killed Michael O''Dwyer, the Lt. Governor of Punjab, not Col. Reginald Dyer who fired the shots. However, popularly it is stated as killing Dyer.)"],"explanationHi":"उधम सिंह ने जलियांवाला बाग हत्याकांड का बदला लेने के लिए 21 साल तक इंतजार किया और लंदन जाकर उसे अंजाम दिया।","explanationEn":"Udham Singh waited for 21 years to avenge the Jallianwala Bagh massacre and assassinated him in London.","memoryTip":"डायर का ''उद्धार'' उधम सिंह ने लंदन में किया।","memoryTipEn":"Udham ended O''Dwyer.","related":["Jallianwala Bagh Massacre","Michael O''Dwyer","Caxton Hall"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Y1dEPFZYQVkvU8pAHMIBJ', 'General Knowledge', 'बंगाल का विभाजन कब और किसके द्वारा किया गया था?', 'When and by whom was the partition of Bengal done?', '1905 ई. में गवर्नर लार्ड कर्जन द्वारा', 'In 1905 AD by Governor Lord Curzon', 95, 0, '{"facts":["विभाजन का कारण प्रशासनिक सुविधा बताया गया था, लेकिन असली कारण राष्ट्रवाद को कमजोर करना था।","इसके विरोध में स्वदेशी आंदोलन (Swadeshi Movement) शुरू हुआ और अंततः 1911 में विभाजन रद्द कर दिया गया।"],"factsEn":["Administrative convenience was cited as the reason, but the real motive was to weaken nationalism.","The Swadeshi Movement started in protest, and the partition was finally annulled in 1911."],"explanationHi":"कर्जन ने हिंदू और मुस्लिम आबादी को बांटने के लिए बंगाल को पूर्वी और पश्चिमी बंगाल में विभाजित कर दिया था।","explanationEn":"Curzon divided Bengal into East and West Bengal to divide the Hindu and Muslim populations.","memoryTip":"बंगाल को ''कर्ज़'' (Curzon) देकर 1905 में दो हिस्सों में बांट दिया।","memoryTipEn":"Curzon cut Bengal in 1905.","related":["Swadeshi Movement","Lord Curzon","Delhi Durbar 1911"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('OcGlOZRw4lQpzXjNIftOJ', 'General Knowledge', 'भारत में कुल कितने उच्च न्यायालय (High Courts) हैं?', 'How many High Courts are there in total in India?', '24 (वर्तमान में 25)', '24 (Currently 25)', 90, 0, '{"facts":["नोट: पीडीएफ स्रोत में 24 दिए गए हैं, लेकिन 2019 में आंध्र प्रदेश उच्च न्यायालय (अमरावती) के गठन के बाद अब भारत में 25 उच्च न्यायालय हैं।","सबसे पुराना उच्च न्यायालय कलकत्ता उच्च न्यायालय (1862) है।"],"factsEn":["Note: PDF source says 24, but with the formation of the Andhra Pradesh HC (Amaravati) in 2019, there are now 25 High Courts.","The oldest High Court is the Calcutta High Court (1862)."],"explanationHi":"प्रत्येक राज्य का अपना एक उच्च न्यायालय हो सकता है, लेकिन संविधान 2 या अधिक राज्यों के लिए एक साझा उच्च न्यायालय की भी अनुमति देता है।","explanationEn":"Each state can have its own High Court, but the Constitution also allows a common High Court for 2 or more states.","memoryTip":"अब एक चौथाई (25) शतक पूरा हो गया है हाई कोर्ट्स का।","memoryTipEn":"India hosts a quarter-century (25) of High Courts.","related":["Supreme Court","Calcutta High Court","Andhra Pradesh High Court"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lzOKDe0stXjWu1DyaoYp-', 'General Knowledge', 'प्रथम लोकसभा का अध्यक्ष कौन था?', 'Who was the first Speaker of the Lok Sabha?', 'जी. वी. मावलंकर', 'G. V. Mavalankar', 94, 0, '{"facts":["इनका पूरा नाम गणेश वासुदेव मावलंकर था।","इन्हें जवाहरलाल नेहरू ने ''लोकसभा का पिता'' (Father of Lok Sabha) की उपाधि दी थी।"],"factsEn":["His full name was Ganesh Vasudev Mavalankar.","He was titled the ''Father of Lok Sabha'' by Jawaharlal Nehru."],"explanationHi":"स्वतंत्र भारत के पहले आम चुनाव (1951-52) के बाद गठित पहली लोकसभा के वे पीठासीन अधिकारी थे।","explanationEn":"He was the presiding officer of the first Lok Sabha constituted after independent India''s first general elections (1951-52).","memoryTip":"लोकसभा का ''श्री गणेश'' मावलंकर जी ने किया।","memoryTipEn":"Ganesh started the Lok Sabha.","related":["Lok Sabha","Father of Lok Sabha","Sukumar Sen"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KZNb_dWwLlLD_WZSiXfVL', 'General Knowledge', 'संविधान सभा का अस्थायी अध्यक्ष किसे चुना गया?', 'Who was elected as the temporary President of the Constituent Assembly?', 'सच्चिदानन्द सिन्हा', 'Dr. Sachchidananda Sinha', 93, 0, '{"facts":["उन्हें 9 दिसंबर 1946 को संविधान सभा की पहली बैठक में अध्यक्ष चुना गया था।","वे फ्रांसीसी प्रथा का पालन करते हुए सबसे उम्रदराज सदस्य के रूप में चुने गए थे।"],"factsEn":["He was elected in the first meeting of the Constituent Assembly on Dec 9, 1946.","Following French practice, he was chosen as he was the oldest member."],"explanationHi":"दो दिन बाद, 11 दिसंबर 1946 को डॉ. राजेंद्र प्रसाद को संविधान सभा का स्थायी अध्यक्ष चुना गया।","explanationEn":"Two days later, on Dec 11, 1946, Dr. Rajendra Prasad was elected as the permanent President of the Assembly.","memoryTip":"सबसे बुजुर्ग होने के नाते ''सच्चे'' (सच्चिदानंद) व्यक्ति को पहले सम्मान मिला।","memoryTipEn":"Sinha sat first, Prasad sat permanent.","related":["Dr. Rajendra Prasad","Constituent Assembly First Meeting"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RwEDbQPWW0TlwfOOllLXh', 'General Knowledge', 'कुचिपुड़ी नृत्य शैली मुख्यतः किस राज्य से सम्बन्धित मानी जाती है?', 'Kuchipudi dance style is mainly considered to be related to which state?', 'आंध्रप्रदेश', 'Andhra Pradesh', 94, 0, '{"facts":["कुचिपुड़ी भारत के आठ प्रमुख शास्त्रीय नृत्यों में से एक है।","इसका नाम कृष्णा जिले के एक गांव कुचेलपुरम के नाम पर पड़ा है।"],"factsEn":["Kuchipudi is one of the eight major classical dances of India.","It is named after Kuchelapuram, a village in the Krishna district."],"explanationHi":"यह नृत्य पारंपरिक रूप से केवल पुरुषों द्वारा किया जाता था, लेकिन अब महिलाएं भी इसमें पारंगत हैं। इसमें पीतल की थाली के किनारों पर नाचना (तरंगम) इसका एक मुख्य आकर्षण है।","explanationEn":"Traditionally performed only by men, women now excel in it too. Dancing on the edges of a brass plate (Tarangam) is its main attraction.","memoryTip":"''अंधेरे'' (आंध्र) में ''कच्ची पूड़ी'' (कुचिपुड़ी) खाई।","memoryTipEn":"Andhra cooks Kuchipudi.","related":["Classical Dances of India","Tarangam","Bharatanatyam"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('K2DSFiy6BHowgSD-ESI4D', 'General Knowledge', 'मोहिनीअट्टम नृत्य शैली मुख्यतः किस राज्य से सम्बन्धित मानी जाती है?', 'Mohiniyattam dance style is mainly considered to be related to which state?', 'केरल', 'Kerala', 92, 0, '{"facts":["यह भगवान विष्णु के ''मोहिनी'' अवतार पर आधारित है।","यह नृत्य मुख्य रूप से एकल महिलाओं द्वारा किया जाता है।"],"factsEn":["It is based on the ''Mohini'' avatar of Lord Vishnu.","This dance is mainly performed by solo women."],"explanationHi":"केरल में दो शास्त्रीय नृत्य प्रसिद्ध हैं— मोहिनीअट्टम (सौम्य और लालित्यपूर्ण) और कथकली (नाटकीय और ऊर्जावान)।","explanationEn":"Kerala has two famous classical dances—Mohiniyattam (gentle and graceful) and Kathakali (dramatic and energetic).","memoryTip":"केरल की प्राकृतिक सुंदरता मन ''मोह'' लेती है (मोहिनी)।","memoryTipEn":"Kerala mesmerizes like Mohini.","related":["Kathakali","Classical Dances of India","Lord Vishnu"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1TafBpugcEmo6IQZOz6Fn', 'General Knowledge', 'भरतनाट्यम नृत्य शैली मुख्यतः किस राज्य से सम्बन्धित मानी जाती है?', 'Bharatanatyam dance style is mainly considered to be related to which state?', 'तमिलनाडु', 'Tamil Nadu', 95, 0, '{"facts":["यह भारत का सबसे पुराना और सबसे लोकप्रिय शास्त्रीय नृत्य है।","इसकी उत्पत्ति दक्षिण भारत के हिंदू मंदिरों (विशेषकर देवदासी परंपरा) में हुई थी।"],"factsEn":["It is the oldest and most popular classical dance of India.","It originated in the Hindu temples of South India (specifically the Devadasi tradition)."],"explanationHi":"इसके नाम में भ (भाव), र (राग), त (ताल) और नाट्यम (नृत्य) शामिल है।","explanationEn":"Its name incorporates Bha (Bhava/Expression), Ra (Raga/Music), Ta (Tala/Rhythm), and Natyam (Dance).","memoryTip":"भरत मुनि का नाट्य शास्त्र ''तमिलनाडु'' में रचा-बसा।","memoryTipEn":"Tamil Nadu is the home of Bharatanatyam.","related":["Devadasi Tradition","Natya Shastra","Rukmini Devi Arundale"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dt6znW5Zu_onAfIOk2WLd', 'General Knowledge', 'कथकली किस राज्य का शास्त्रीय नृत्य है?', 'Kathakali is the classical dance of which state?', 'केरल', 'Kerala', 95, 0, '{"facts":["यह अपने विस्तृत मेकअप, रंगीन वेशभूषा और बड़े मुकुटों के लिए जाना जाता है।","कथकली में नर्तक बोलते नहीं हैं, वे इशारों (मुद्रा) और चेहरे के भावों से कहानी कहते हैं।"],"factsEn":["It is known for its elaborate makeup, colorful costumes, and large headgears.","Dancers don''t speak in Kathakali; they tell stories through gestures (mudras) and facial expressions."],"explanationHi":"यह मुख्य रूप से हिंदू महाकाव्यों (रामायण, महाभारत) की कहानियों का नाट्य रूपांतरण है।","explanationEn":"It is primarily a dramatic adaptation of stories from Hindu epics (Ramayana, Mahabharata).","memoryTip":"केरल की ''कथा'' ''कली'' (कथकली) में दिखती है।","memoryTipEn":"Kathakali is Kerala''s story play.","related":["Mohiniyattam","Classical Dances","Mahabharata"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Ab9j3RHN8X1KQqIvl_dbq', 'General Knowledge', 'केसर (Saffron) का सर्वाधिक उत्पादन किस राज्य में होता है?', 'Which state is the largest producer of Saffron?', 'जम्मू कश्मीर', 'Jammu & Kashmir', 93, 0, '{"facts":["जम्मू कश्मीर के पंपोर (Pampore) क्षेत्र को भारत का ''केसर का कटोरा'' कहा जाता है।","केसर क्रोकस (Crocus sativus) फूल के वर्तिकाग्र (Stigma) से प्राप्त होता है।"],"factsEn":["The Pampore region of J&K is called the ''Saffron Bowl'' of India.","Saffron is obtained from the stigma of the Crocus sativus flower."],"explanationHi":"यह दुनिया के सबसे महंगे मसालों में से एक है क्योंकि प्रत्येक फूल से केवल तीन धागे हाथ से निकाले जाते हैं।","explanationEn":"It is one of the most expensive spices in the world because only three threads are hand-picked from each flower.","memoryTip":"कश्मीर की वादियों में लाल ''केसर'' खिलता है।","memoryTipEn":"Kashmir is colored with Saffron.","related":["Pampore","Crocus sativus","Karewa soil"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HFVJAhIrCSV3yLOaWqvd3', 'General Knowledge', 'भारत में प्रथम बहुउद्देश्य परियोजना का निर्माण किस नदी पर किया गया?', 'On which river was the first multipurpose river valley project constructed in India?', 'दामोदर', 'Damodar', 92, 0, '{"facts":["दामोदर घाटी निगम (DVC) की स्थापना 1948 में हुई थी।","यह अमेरिका की ''टेनेसी वैली अथॉरिटी'' (TVA) के मॉडल पर आधारित था।"],"factsEn":["Damodar Valley Corporation (DVC) was established in 1948.","It was based on the model of the ''Tennessee Valley Authority'' (TVA) of the USA."],"explanationHi":"दामोदर नदी को पहले ''बंगाल का शोक'' कहा जाता था। इस परियोजना का उद्देश्य बाढ़ नियंत्रण, सिंचाई और जलविद्युत उत्पन्न करना था।","explanationEn":"The Damodar river was earlier called the ''Sorrow of Bengal''. This project aimed at flood control, irrigation, and hydropower generation.","memoryTip":"पहली योजना में ''दम'' (दामोदर) था।","memoryTipEn":"Damodar Valley Corporation was the First.","related":["Sorrow of Bengal","Tennessee Valley Authority","Hirakud Dam"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rrprDhM8oJ2hRZ3gQlxDo', 'General Knowledge', 'इंडियन नेशनल कांग्रेस के प्रथम अध्यक्ष कौन थे?', 'Who was the first President of the Indian National Congress?', 'व्योमेश चन्द्र बनर्जी (W. C. Bonnerjee)', 'Womesh Chandra Bonnerjee', 94, 0, '{"facts":["कांग्रेस का पहला अधिवेशन 1885 में बॉम्बे (अब मुंबई) में हुआ था।","कांग्रेस की स्थापना ए. ओ. ह्यूम (A. O. Hume) नामक एक अंग्रेज अधिकारी ने की थी।"],"factsEn":["The first session of Congress was held in Bombay (now Mumbai) in 1885.","Congress was founded by an English officer, A. O. Hume."],"explanationHi":"इस प्रथम अधिवेशन में 72 प्रतिनिधियों ने भाग लिया था, और यहीं से भारत के संगठित राष्ट्रीय आंदोलन की शुरुआत मानी जाती है।","explanationEn":"72 delegates attended this first session, marking the beginning of India''s organized national movement.","memoryTip":"कांग्रेस के पहले अध्यक्ष ने सबको ''बैनर'' (Banerjee) के नीचे इकट्ठा किया।","memoryTipEn":"W.C. Bonnerjee held the first banner of INC.","related":["A. O. Hume","1885 Bombay Session","Badruddin Tyabji (First Muslim President)"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uX5FIBMDx1JpxgF_4mvGL', 'General Knowledge', 'गांधीजी किसे अपना राजनितिक गुरु मानते थे?', 'Whom did Gandhiji consider as his political guru?', 'गोपाल कृष्ण गोखले', 'Gopal Krishna Gokhale', 95, 0, '{"facts":["गोखले एक नरमपंथी (Moderate) कांग्रेस नेता और ''सर्वेन्ट्स ऑफ इंडिया सोसाइटी'' के संस्थापक थे।","गोखले के कहने पर ही गांधीजी ने 1915 में भारत लौटने के बाद एक साल तक पूरे भारत का भ्रमण किया था।"],"factsEn":["Gokhale was a moderate Congress leader and founder of the ''Servants of India Society''.","On Gokhale''s advice, Gandhi toured India for a year upon returning in 1915."],"explanationHi":"गांधीजी ने अपनी पुस्तक में लिखा है कि गोखले उनके लिए एक आदर्श मार्गदर्शक थे, जिन्होंने उन्हें भारत की वास्तविक स्थिति से अवगत कराया।","explanationEn":"Gandhiji wrote in his book that Gokhale was an ideal guide who made him aware of the ground realities of India.","memoryTip":"गांधीजी ने ''गोखले'' से राजनीति का ''ज्ञान'' लिया।","memoryTipEn":"Gokhale guided Gandhi''s early politics.","related":["Servants of India Society","Moderate Leaders","M. G. Ranade (Gokhale''s Guru)"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yZhaX4rK5BF8AkPJFzm2T', 'General Knowledge', 'अन्तराष्ट्रीय शांति एवं सुरक्षा को बनाए रखने की जिम्मेदारी संयुक्त राष्ट्र संघ के किस अंग की है?', 'Which organ of the United Nations is responsible for maintaining international peace and security?', 'सुरक्षा परिषद् (Security Council)', 'Security Council (UNSC)', 93, 0, '{"facts":["इसमें 15 सदस्य होते हैं (5 स्थायी और 10 अस्थायी)।","पांच स्थायी सदस्यों के पास ''वीटो पावर'' (Veto Power) होती है।"],"factsEn":["It consists of 15 members (5 permanent and 10 non-permanent).","The five permanent members have ''Veto Power''."],"explanationHi":"जब भी अंतरराष्ट्रीय शांति को खतरा होता है, तो सुरक्षा परिषद शांति रक्षा मिशन भेजने या प्रतिबंध लगाने का फैसला करती है।","explanationEn":"Whenever there is a threat to international peace, the Security Council decides on sending peacekeeping missions or imposing sanctions.","memoryTip":"सुरक्षा का जिम्मा ''सुरक्षा परिषद्'' का ही होगा।","memoryTipEn":"Security Council Secures peace.","related":["Veto Power","UN General Assembly","P5 Nations"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('cPeOuoiuTzaj75D1g8j4F', 'General Knowledge', 'नोबेल पुरस्कार पाने वाला पहला भारतीय नागरिक कौन था?', 'Who was the first Indian citizen to receive the Nobel Prize?', 'रवीन्द्रनाथ टैगोर (1913 में)', 'Rabindranath Tagore (in 1913)', 96, 0, '{"facts":["उन्हें साहित्य के क्षेत्र में उनके काव्य संग्रह ''गीतांजलि'' (Gitanjali) के लिए यह पुरस्कार मिला था।","वे न केवल भारत बल्कि पूरे एशिया के पहले नोबेल पुरस्कार विजेता थे।"],"factsEn":["He received this award in Literature for his poetry collection ''Gitanjali''.","He was the first Nobel laureate not only in India but in all of Asia."],"explanationHi":"टैगोर एक महान कवि, दार्शनिक और कलाकार थे, जिन्होंने भारत और बांग्लादेश दोनों के राष्ट्रगान लिखे।","explanationEn":"Tagore was a great poet, philosopher, and artist who authored the national anthems of both India and Bangladesh.","memoryTip":"साहित्य का ''गीत'' गाकर टैगोर ने पहला नोबेल जीता।","memoryTipEn":"Tagore took the first Nobel to Asia.","related":["Gitanjali","Nobel Prize in Literature","C. V. Raman (First Indian Science Nobel)"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Ql18MjXkO1xPNAJdiqxlt', 'General Knowledge', 'मिड डे मील योजना (Mid Day Meal) किस वर्ष शुरु हुई?', 'In which year did the Mid-Day Meal scheme start?', '1995 में', '1995', 88, 0, '{"facts":["यह योजना 15 अगस्त 1995 को शुरू की गई थी।","तमिलनाडु भारत का पहला राज्य था जिसने सबसे पहले अपने यहाँ मध्याह्न भोजन योजना शुरू की थी।"],"factsEn":["This scheme was launched on August 15, 1995.","Tamil Nadu was the first state in India to introduce a mid-day meal scheme."],"explanationHi":"इस योजना का उद्देश्य गरीब बच्चों के पोषण स्तर में सुधार करना और प्राथमिक स्कूलों में बच्चों की उपस्थिति बढ़ाना है।","explanationEn":"The objective is to improve the nutritional status of poor children and increase their attendance in primary schools.","memoryTip":"95 (पचानवे) में बच्चों को स्कूल में ''भोजन'' मिलने लगा।","memoryTipEn":"1995 provided the mid-day drive.","related":["PM POSHAN Scheme (New name)","Right to Education","K. Kamaraj (Initiated in TN)"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PEpy0IJ4tpxmf1bef8jYm', 'General Knowledge', 'बंग्लादेश का राष्ट्रगान कौनसा है और इसे किसने लिखा है?', 'Which is the national anthem of Bangladesh and who wrote it?', '''आमार सोनार बांग्ला'' जो रवीन्द्रनाथ टैगोर ने लिखा है', '''Amar Sonar Bangla'', written by Rabindranath Tagore', 92, 0, '{"facts":["यह गीत 1905 में बंगाल विभाजन (Partition of Bengal) के विरोध में लिखा गया था।","1971 में स्वतंत्रता के बाद बांग्लादेश ने इसकी पहली 10 पंक्तियों को राष्ट्रगान के रूप में अपनाया।"],"factsEn":["This song was written in 1905 to protest the Partition of Bengal.","After independence in 1971, Bangladesh adopted its first 10 lines as the national anthem."],"explanationHi":"रवीन्द्रनाथ टैगोर दुनिया के एकमात्र ऐसे व्यक्ति हैं जिनकी रचनाओं को दो देशों (भारत और बांग्लादेश) ने अपना राष्ट्रगान चुना है।","explanationEn":"Rabindranath Tagore is the only person in the world whose compositions were chosen as national anthems by two countries (India and Bangladesh).","memoryTip":"टैगोर जी ने दो देशों का गान लिखा।","memoryTipEn":"Tagore wrote anthems for two nations.","related":["Jana Gana Mana","Partition of Bengal","Rabindranath Tagore"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KL8QShIHPs5-NII0RMoYy', 'General Knowledge', 'लोदी वंश का संस्थापक कौन था?', 'Who was the founder of the Lodi Dynasty?', 'बहलोल लोदी', 'Bahlul Lodi', 91, 0, '{"facts":["उसने 1451 में सैय्यद वंश को हटाकर दिल्ली सल्तनत में लोदी वंश की स्थापना की।","इब्राहिम लोदी इस वंश का अंतिम शासक था, जिसे बाबर ने पानीपत के प्रथम युद्ध (1526) में हराया।"],"factsEn":["He established the Lodi dynasty in the Delhi Sultanate in 1451, replacing the Sayyid dynasty.","Ibrahim Lodi was the last ruler, defeated by Babur in the First Battle of Panipat (1526)."],"explanationHi":"लोदी वंश दिल्ली सल्तनत का पहला अफगान (पश्तून) वंश था।","explanationEn":"The Lodi dynasty was the first Afghan (Pashtun) dynasty of the Delhi Sultanate.","memoryTip":"''बहलोल'' ने लोदी वंश की ''बहाली'' की।","memoryTipEn":"Bahlul brought the Lodis.","related":["Ibrahim Lodi","First Battle of Panipat","Delhi Sultanate"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('piUvMbCQhyRl-OYyN9zok', 'General Knowledge', 'किस संविधान संशोधन को ''मिनी कॉन्स्टीट्यूशन'' (Mini Constitution) कहते हैं?', 'Which Constitutional Amendment is known as the ''Mini Constitution''?', '42वें', '42nd Amendment', 96, 0, '{"facts":["यह 1976 में इंदिरा गांधी सरकार के आपातकाल के दौरान पारित हुआ था।","इसने प्रस्तावना में ''समाजवादी'', ''धर्मनिरपेक्ष'' और ''अखंडता'' शब्द जोड़े और मौलिक कर्तव्य (Fundamental Duties) भी शामिल किए।"],"factsEn":["It was passed during the Emergency in 1976 by the Indira Gandhi government.","It added the words ''Socialist'', ''Secular'', and ''Integrity'' to the Preamble and included Fundamental Duties."],"explanationHi":"इस संशोधन द्वारा संविधान के लगभग हर हिस्से में बड़े पैमाने पर बदलाव किए गए थे, इसलिए इसे लघु संविधान (Mini Constitution) कहा जाता है।","explanationEn":"This amendment made extensive changes to almost every part of the Constitution, hence it is called the Mini Constitution.","memoryTip":"4 और 2 (42) मिलकर संविधान का सबसे बड़ा ''छोटा'' हिस्सा बने।","memoryTipEn":"42nd Amendment changed so much, it''s a Mini Constitution.","related":["Fundamental Duties","Preamble","National Emergency 1975"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('EP-oGi-BPfuawEGYGqpT5', 'General Science', 'गोताखोर पानी के अंदर सांस लेने के लिए कौन-कौन सी गैसों का मिश्रण ले जाते हैं?', 'What mixture of gases do deep-sea divers carry for breathing underwater?', 'आक्सीजन और हीलियम गैसों का मिश्रण', 'A mixture of Oxygen and Helium', 94, 0, '{"facts":["इस मिश्रण को ''हेलिओक्स'' (Heliox) भी कहा जाता है।","हीलियम का उपयोग इसलिए किया जाता है क्योंकि उच्च दबाव में यह रक्त में कम घुलनशील होती है।"],"factsEn":["This mixture is also known as ''Heliox''.","Helium is used because it is less soluble in blood at high pressures."],"explanationHi":"गहरे पानी में उच्च दबाव के कारण हवा की नाइट्रोजन रक्त में घुल सकती है, जिससे ''बेंड्स'' (Bends) या ''नाइट्रोजन नार्कोसिस'' जैसी घातक स्थिति हो सकती है; हीलियम इससे बचाती है।","explanationEn":"At high pressure in deep water, nitrogen from regular air can dissolve in blood, causing a fatal condition like ''the bends'' or ''nitrogen narcosis''; helium prevents this.","memoryTip":"पानी के अंदर ''ऑक्सीजन'' के साथ ''हीलियम'' का गुब्बारा उड़ता है।","memoryTipEn":"Helium helps divers breathe deep safely.","related":["Decompression Sickness (The Bends)","Scuba Diving","Nitrogen Narcosis"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('htlrPYTLJa2NhWFD2z83B', 'General Science', 'होम्योपैथी का संस्थापक कौन था?', 'Who was the founder of Homeopathy?', 'हनीमैन (Samuel Hahnemann)', 'Samuel Hahnemann', 87, 0, '{"facts":["वे एक जर्मन चिकित्सक थे जिन्होंने 1796 में इस प्रणाली की शुरुआत की।","होम्योपैथी ''समान से समान की चिकित्सा'' (Like cures like) सिद्धांत पर आधारित है।"],"factsEn":["He was a German physician who started this system in 1796.","Homeopathy is based on the principle of ''Like cures like'' (Similia similibus curentur)."],"explanationHi":"इस चिकित्सा पद्धति में अत्यधिक पतले (Diluted) पदार्थों का उपयोग शरीर की प्राकृतिक उपचार प्रणाली को सक्रिय करने के लिए किया जाता है।","explanationEn":"This medical system uses highly diluted substances to trigger the body''s natural healing system.","memoryTip":"होम्योपैथी की मीठी गोलियों में ''हनी'' (Hahnemann) होता है।","memoryTipEn":"Hahnemann healed with Homeopathy.","related":["Alternative Medicine","Ayurveda","Allopathy"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('heuvqZdrtyWmnvtxUflPQ', 'General Science', 'फलों को पकाने में कौन सी गैस उपयोग में लायी जाती है?', 'Which gas is used for the artificial ripening of fruits?', 'ऐथिलीन (Ethylene)', 'Ethylene', 92, 0, '{"facts":["ऐथिलीन एक प्राकृतिक प्लांट हार्मोन है जो फलों के पकने की प्रक्रिया को नियंत्रित करता है।","कृत्रिम रूप से पकाने के लिए कैल्शियम कार्बाइड का भी इस्तेमाल होता है (जो एसिटिलीन गैस छोड़ता है), लेकिन कई देशों में इसे प्रतिबंधित कर दिया गया है।"],"factsEn":["Ethylene is a natural plant hormone that regulates the ripening process.","Calcium Carbide is also used artificially (which releases acetylene gas), but it is banned in many countries."],"explanationHi":"यह गैस फलों को मुलायम बनाती है और उनका रंग बदलती है, जिससे वे खाने के लिए मीठे और तैयार हो जाते हैं।","explanationEn":"This gas softens the fruits and changes their color, making them sweet and ready to eat.","memoryTip":"कच्चे फलों को ''ऐथिलीन'' जल्दी पका देती है।","memoryTipEn":"Ethylene ripens the green.","related":["Plant Hormones","Calcium Carbide","Acetylene"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('eLsf9R_qVZua6mT0OFSN7', 'General Knowledge', 'भारतीय राष्ट्रीय कलेंडर का पहला माह कौन सा है?', 'Which is the first month of the Indian National Calendar?', 'चैत्र', 'Chaitra', 91, 0, '{"facts":["भारत का राष्ट्रीय पंचांग ''शक संवत'' (Saka Era) पर आधारित है।","इसका अंतिम महीना फाल्गुन होता है।"],"factsEn":["India''s National Calendar is based on the ''Saka Era''.","Its last month is Phalguna."],"explanationHi":"चैत्र महीने का पहला दिन सामान्यतः ग्रेगोरियन कैलेंडर के 22 मार्च (लीप वर्ष में 21 मार्च) को पड़ता है।","explanationEn":"The first day of the Chaitra month normally falls on March 22 (March 21 in a leap year) of the Gregorian calendar.","memoryTip":"हिन्दू नववर्ष की शुरुआत ''चैत्र'' से होती है।","memoryTipEn":"Chaitra is the start of Saka.","related":["Saka Samvat","Phalguna","Gregorian Calendar"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('R_fXkOOWqOHm_R0DgQEVA', 'General Knowledge', 'पं. हरिप्रसाद चौरसिया कौनसा वाद्य यंत्र बजाते हैं?', 'Pt. Hariprasad Chaurasia plays which musical instrument?', 'बाँसुरी', 'Flute', 90, 0, '{"facts":["उन्हें 2000 में पद्म विभूषण से सम्मानित किया गया था।","वे भारतीय शास्त्रीय संगीत में एक विश्व प्रसिद्ध बाँसुरी वादक हैं।"],"factsEn":["He was awarded the Padma Vibhushan in 2000.","He is a world-renowned flautist in Indian classical music."],"explanationHi":"हरिप्रसाद चौरसिया ने बांसुरी जैसे सरल लोक वाद्ययंत्र को शास्त्रीय मंच पर असाधारण ऊंचाइयों तक पहुंचाया।","explanationEn":"Hariprasad Chaurasia elevated the simple folk instrument of the flute to extraordinary heights on the classical stage.","memoryTip":"''हरि'' (कृष्ण) हमेशा ''बांसुरी'' बजाते हैं।","memoryTipEn":"Hari (Krishna) plays the Flute.","related":["Padma Vibhushan","Ustad Bismillah Khan (Shehnai)","Ravi Shankar (Sitar)"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('o_bWEUCQ3DWW6jSRkuxsU', 'General Knowledge', 'भारत का प्रधानमंत्री बनने के लिए कम-से-कम कितनी आयु होनी चाहिए?', 'What is the minimum age required to become the Prime Minister of India?', '25 वर्ष', '25 Years', 95, 0, '{"facts":["यदि प्रधानमंत्री लोकसभा का सदस्य है, तो न्यूनतम आयु 25 वर्ष होनी चाहिए।","यदि प्रधानमंत्री राज्यसभा का सदस्य है, तो न्यूनतम आयु 30 वर्ष होनी चाहिए।"],"factsEn":["If the PM is a member of the Lok Sabha, the minimum age is 25 years.","If the PM is a member of the Rajya Sabha, the minimum age is 30 years."],"explanationHi":"संविधान के अनुसार, प्रधानमंत्री को संसद के किसी एक सदन का सदस्य होना अनिवार्य है, और लोकसभा चुनाव लड़ने की न्यूनतम आयु 25 वर्ष है।","explanationEn":"According to the constitution, the PM must be a member of either house of parliament, and the minimum age to contest Lok Sabha elections is 25 years.","memoryTip":"25 की उम्र में लोकसभा जाकर पीएम बन सकते हो।","memoryTipEn":"25 to sit in the Lok Sabha and lead.","related":["President (35 Years)","Rajya Sabha Member (30 Years)","Lok Sabha"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Z5IFK4T54-Vi0BD_je2v4', 'General Knowledge', 'साँची के स्तूप का निर्माण किसने करवाया था?', 'Who built the Sanchi Stupa?', 'अशोक', 'Ashoka', 94, 0, '{"facts":["यह मध्य प्रदेश के रायसेन जिले में स्थित है।","यह भारत में पत्थर की सबसे पुरानी संरचनाओं में से एक है और यूनेस्को (UNESCO) विश्व धरोहर स्थल है।"],"factsEn":["It is located in the Raisen district of Madhya Pradesh.","It is one of the oldest stone structures in India and a UNESCO World Heritage site."],"explanationHi":"महान मौर्य सम्राट अशोक ने तीसरी शताब्दी ईसा पूर्व में भगवान बुद्ध के अवशेषों को सुरक्षित रखने के लिए इसका निर्माण करवाया था।","explanationEn":"The great Mauryan emperor Ashoka built it in the 3rd century BCE to preserve the relics of Lord Buddha.","memoryTip":"अशोक ने ''सच्चाई'' (साँची) के स्तूप बनवाए।","memoryTipEn":"Ashoka sculpted Sanchi.","related":["Buddhism","UNESCO World Heritage Site","Mauryan Empire"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bwiIFKjDtxZesk82W7wFF', 'General Knowledge', 'यक्षगान किस राज्य का लोकनृत्य है?', 'Yakshagana is a folk dance of which state?', 'कर्नाटक', 'Karnataka', 92, 0, '{"facts":["यह नृत्य, संगीत, संवाद, वेशभूषा और मेकअप का एक पारंपरिक नाट्य रूप है।","यक्षगान का अर्थ है ''यक्ष (प्रकृति की आत्माओं) का गीत''।"],"factsEn":["It is a traditional theater form combining dance, music, dialogue, costume, and makeup.","Yakshagana means ''song of the Yakshas (nature spirits)''."],"explanationHi":"यह मुख्य रूप से हिंदू महाकाव्यों और पुराणों से पौराणिक कहानियों को प्रस्तुत करने के लिए रात भर खुले में किया जाने वाला प्रदर्शन है।","explanationEn":"It is an open-air performance mainly held overnight to depict mythological stories from Hindu epics and Puranas.","memoryTip":"नाटक करने के लिए ''कर्नाटक'' जाओ और यक्षगान देखो।","memoryTipEn":"Yakshas act in Karnataka.","related":["Kathakali (Kerala)","Folk Dances","Dullu Kunitha"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FMUw5R9xbnaW-oCVTHDk0', 'General Knowledge', 'मैकमोहन रेखा किन दो देशों के बीच सीमा बनाती है?', 'The McMahon Line forms the boundary between which two countries?', 'भारत-चीन', 'India-China', 96, 0, '{"facts":["यह रेखा 1914 के शिमला समझौते के दौरान सर हेनरी मैकमोहन द्वारा प्रस्तावित की गई थी।","यह मुख्य रूप से भारत के अरुणाचल प्रदेश और तिब्बत के बीच की सीमा है।"],"factsEn":["This line was proposed by Sir Henry McMahon during the 1914 Simla Convention.","It primarily forms the boundary between India''s Arunachal Pradesh and Tibet."],"explanationHi":"भारत इसे अपनी वैध राष्ट्रीय सीमा मानता है, जबकि चीन अक्सर इसे ब्रिटिश साम्राज्यवाद की देन बताते हुए विवाद करता है।","explanationEn":"India considers it the legal national border, while China often disputes it, calling it a legacy of British imperialism.","memoryTip":"''मैक'' और ''मोहन'' मिलकर चीन से लड़ते हैं।","memoryTipEn":"McMahon marks the dragon''s edge.","related":["Radcliffe Line (India-Pakistan)","Durand Line (Pakistan-Afghanistan)","Line of Actual Control (LAC)"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aWyrXz5f6bp33QdKgmIID', 'General Science', 'प्याज में खाद्य भाग कौनसा है?', 'Which is the edible part of an onion?', 'तना (Stem)', 'Stem (Modified fleshy leaves/bulb)', 87, 0, '{"facts":["तकनीकी रूप से प्याज एक ''शल्ककंद'' (Bulb) है, जो एक भूमिगत रूपांतरित तना (Modified underground stem) होता है।","हम जो खाते हैं वह मुख्य रूप से रूपांतरित गूदेदार पत्तियां (Fleshy leaves) होती हैं जो तने से जुड़ी होती हैं।"],"factsEn":["Technically, an onion is a ''Bulb'', which is a modified underground stem.","What we eat is primarily modified fleshy leaves attached to a compressed stem."],"explanationHi":"परीक्षाओं में प्रायः इसे ''ताना'' (Stem) माना जाता है क्योंकि कंद तने का ही रूपांतरण है, जहाँ पत्तियां भोजन जमा कर मोटी हो जाती हैं।","explanationEn":"In exams, it is often classified as a ''stem'' because the bulb is a stem modification where leaves become thick by storing food.","memoryTip":"प्याज एक कंद (तना) है, जिसे छीलते-छीलते आंसू आते हैं।","memoryTipEn":"Onion bulb is a buried stem.","related":["Potato (Modified Stem)","Carrot (Tuber/Stem)","Bulb"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('l0kM7dgY7FMIeWlVJfo3L', 'General Science', 'श्रव्य परिसर में ध्वनि तरंगों की आवृति कितनी होती है?', 'What is the frequency of sound waves in the audible range?', '20 Hz से 20000 Hz', '20 Hz to 20,000 Hz', 94, 0, '{"facts":["20 हर्ट्ज से कम आवृत्ति वाली ध्वनि को ''अपश्रव्य'' (Infrasonic) कहते हैं।","20,000 हर्ट्ज से अधिक आवृत्ति वाली ध्वनि को ''पराश्रव्य'' (Ultrasonic) कहते हैं।"],"factsEn":["Sound with a frequency less than 20 Hz is called ''Infrasonic''.","Sound with a frequency more than 20,000 Hz is called ''Ultrasonic''."],"explanationHi":"एक सामान्य मानव कान केवल 20 कंपन प्रति सेकंड से लेकर 20 हज़ार कंपन प्रति सेकंड के बीच की ध्वनि ही सुन सकता है।","explanationEn":"A normal human ear can only hear sounds between 20 vibrations per second and 20,000 vibrations per second.","memoryTip":"20 से 20 हज़ार तक ही इंसान के कान सुन पाते हैं।","memoryTipEn":"20 to 20K is what we can hear today.","related":["Ultrasonic Waves","Infrasonic Waves","Decibel (Loudness)"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Z7rjpu8S9z4GtdqOiJSKW', 'General Knowledge', 'मधुबनी किस राज्य की लोक चित्रकला शैली है?', 'Madhubani is a folk painting style of which state?', 'बिहार', 'Bihar', 92, 0, '{"facts":["इसे ''मिथिला पेंटिंग'' (Mithila Art) भी कहा जाता है।","इस चित्रकला में प्राकृतिक रंगों का उपयोग किया जाता है (जैसे हल्दी, फूलों का अर्क)।"],"factsEn":["It is also known as ''Mithila Painting''.","Natural dyes and pigments (like turmeric, flower extracts) are used in this art."],"explanationHi":"यह पारंपरिक रूप से बिहार के मिथिला क्षेत्र में महिलाओं द्वारा ताजे प्लास्टर वाली मिट्टी की दीवारों और फर्श पर की जाती थी।","explanationEn":"Traditionally, it was done by women in the Mithila region of Bihar on freshly plastered mud walls and floors.","memoryTip":"''मधु'' (शहद) जैसा मीठा है ''बिहार'' का चित्र।","memoryTipEn":"Madhubani is the beauty of Bihar.","related":["Mithila Art","Warli Painting (Maharashtra)","Pattachitra (Odisha)"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WMGFlP7x-hWV-ZJ1mtQKt', 'General Knowledge', 'विश्व का सबसे ऊँचा पर्वत शिखर माउंट एवरेस्ट किस देश में स्थित है?', 'In which country is the world''s highest mountain peak, Mount Everest, located?', 'नेपाल', 'Nepal', 95, 0, '{"facts":["इसकी ऊंचाई 8,848.86 मीटर है।","नेपाल में इसे ''सागरमाथा'' (Sagarmatha) और तिब्बत में ''चोमोलुंग्मा'' (Chomolungma) कहा जाता है।"],"factsEn":["Its height is 8,848.86 meters.","It is called ''Sagarmatha'' in Nepal and ''Chomolungma'' in Tibet."],"explanationHi":"यह हिमालय पर्वत श्रृंखला का हिस्सा है और चीन (तिब्बत) और नेपाल की सीमा पर स्थित है, लेकिन मुख्य शिखर नेपाल में पड़ता है।","explanationEn":"It is part of the Himalayas and sits on the border of China (Tibet) and Nepal, but the main summit lies in Nepal.","memoryTip":"एवरेस्ट का सिर ''नेपाल'' में ऊँचा है।","memoryTipEn":"Nepal holds the highest peak.","related":["Sagarmatha","Himalayas","K2 (Godwin Austen - 2nd Highest)"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('k51WGP8XTDCHblBi8fdrF', 'General Knowledge', 'किस नदी को दक्षिण गंगा कहा जाता है?', 'Which river is called the Dakshin Ganga (Ganges of the South)?', 'गोदावरी', 'Godavari', 93, 0, '{"facts":["यह प्रायद्वीपीय भारत (Peninsular India) की सबसे लंबी नदी है।","इसका उद्गम महाराष्ट्र के नासिक जिले के त्र्यंबकेश्वर से होता है।"],"factsEn":["It is the longest river in Peninsular India.","It originates from Trimbakeshwar in the Nashik district of Maharashtra."],"explanationHi":"अपने विशाल आकार, पवित्रता और दक्षिण भारत में उपयोगिता के कारण इसे ''दक्षिण गंगा'' या ''वृद्ध गंगा'' कहा जाता है। (कावेरी को अक्सर ''दक्षिण भारत की गंगा'' कहा जाता है)।","explanationEn":"Due to its large size, sanctity, and utility in South India, it is called ''Dakshin Ganga'' or ''Vridha Ganga''. (Kaveri is often called the Ganges of South India).","memoryTip":"दक्षिण में ''गोद'' (गोदावरी) में गंगा बहती है।","memoryTipEn":"Godavari is the grand Ganga of the south.","related":["Trimbakeshwar","Kaveri River","Peninsular Rivers"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PA9CKQwe7DJ6Tu3o-lxrl', 'General Knowledge', 'निर्विरोध चुने जाने वाले एकमात्र राष्ट्रपति कौन थे?', 'Who was the only President to be elected unopposed?', 'नीलम संजीवा रेड्डी', 'Neelam Sanjiva Reddy', 90, 0, '{"facts":["वे भारत के छठे राष्ट्रपति (1977-1982) थे।","वे सबसे कम उम्र (64 वर्ष) में राष्ट्रपति बनने वाले व्यक्ति थे, जब तक कि द्रौपदी मुर्मू (64 वर्ष 1 महीना) नहीं चुनी गईं।"],"factsEn":["He was the 6th President of India (1977-1982).","He was the youngest person to become President (64 years) until Droupadi Murmu was elected."],"explanationHi":"1977 के चुनाव में अन्य सभी उम्मीदवारों के नामांकन पत्र खारिज हो गए थे, इसलिए वे निर्विरोध चुने गए।","explanationEn":"In the 1977 election, the nomination papers of all other candidates were rejected, hence he was elected unopposed.","memoryTip":"''नीलम'' बिना किसी विरोध के चमकती है।","memoryTipEn":"Reddy was ready with no opposition.","related":["President of India","Lok Sabha Speaker","1977 Elections"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('OlDBsdaNESrIC2UElYUfM', 'General Knowledge', 'संसार का सबसे बड़ा डेल्टा सुंदरबन डेल्टा कौनसी नदियाँ बनाती हैं?', 'Which rivers form the Sundarbans Delta, the largest delta in the world?', 'गंगा-ब्रह्मपुत्र', 'Ganga and Brahmaputra', 96, 0, '{"facts":["यह डेल्टा भारत (पश्चिम बंगाल) और बांग्लादेश में फैला हुआ है।","यह ''सुंदरी'' नामक मैंग्रोव पेड़ों (Mangroves) और ''रॉयल बंगाल टाइगर'' के लिए विश्व प्रसिद्ध है।"],"factsEn":["This delta is spread across India (West Bengal) and Bangladesh.","It is world-famous for the ''Sundari'' mangrove trees and the ''Royal Bengal Tiger''."],"explanationHi":"जब गंगा और ब्रह्मपुत्र नदियां बंगाल की खाड़ी में गिरती हैं, तो वे अपनी मिट्टी और गाद से इस विशाल और उपजाऊ डेल्टा का निर्माण करती हैं।","explanationEn":"When the Ganga and Brahmaputra rivers empty into the Bay of Bengal, they deposit silt and sediment to form this vast, fertile delta.","memoryTip":"गंगा और ब्रह्मपुत्र मिलकर एक ''सुंदर वन'' (सुंदरबन) बनाते हैं।","memoryTipEn":"Ganga and Brahmaputra build the beautiful Sundarbans.","related":["Royal Bengal Tiger","Mangrove Forests","Bay of Bengal"]}', 'published', 1776083509, 1776083509);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PcoL-3Ex9XHNwa7ONOY0u', 'General Knowledge', 'सिन्धु घाटी सभ्यता का बंदरगाह वाला नगर कौनसा था?', 'Which was the port city of the Indus Valley Civilization?', 'लोथल', 'Lothal', 95, 0, '{"facts":["लोथल गुजरात के भाल क्षेत्र में स्थित है।","यहाँ दुनिया का सबसे पुराना ज्ञात गोदीबाड़ा (Dockyard) पाया गया है।"],"factsEn":["Lothal is located in the Bhal region of Gujarat.","The world''s oldest known dockyard was found here."],"explanationHi":"लोथल सिंधु घाटी सभ्यता का एक प्रमुख व्यापारिक केंद्र था, जहाँ से मनके, रत्न और मूल्यवान धातुओं का व्यापार होता था।","explanationEn":"Lothal was a major trading center of the Indus Valley Civilization, trading beads, gems, and valuable metals.","memoryTip":"व्यापार का ''लोड़'' (Load) ''लोथल'' के बंदरगाह से जाता था।","memoryTipEn":"Lothal Loaded the ships.","related":["Indus Valley Civilization","Dholavira","Harappa"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gSxKrhehg46dgBMvQ43Xf', 'General Knowledge', 'किसे सितार और तबले का जनक माना जाता है?', 'Who is considered the father of the Sitar and Tabla?', 'अमीर खुसरो', 'Amir Khusro', 92, 0, '{"facts":["इन्हें ''तूती-ए-हिंद'' (Parrot of India) भी कहा जाता है।","ये एक सूफी संत, कवि और संगीतकार थे जो दिल्ली सल्तनत के कई शासकों के दरबार में रहे।"],"factsEn":["He is also known as ''Tuti-e-Hind'' (Parrot of India).","He was a Sufi mystic, poet, and musician who lived under several Delhi Sultanate rulers."],"explanationHi":"अमीर खुसरो ने भारतीय और फारसी संगीत परंपराओं का मिश्रण करके सितार और तबले जैसे वाद्य यंत्रों का आविष्कार किया।","explanationEn":"Amir Khusro blended Indian and Persian musical traditions to invent instruments like the Sitar and Tabla.","memoryTip":"संगीत के ''अमीर'' खजाने से खुसरो ने सितार निकाला।","memoryTipEn":"Amir means rich; he enriched Indian music.","related":["Qawwali","Delhi Sultanate","Tuti-e-Hind"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('tOl4cVluRX5WDPflJbEc2', 'General Knowledge', 'विश्व का सबसे ऊँचा पठार कौनसा है?', 'Which is the highest plateau in the world?', 'पामीर या तिब्बत का पठार', 'Pamir / Tibetan Plateau', 94, 0, '{"facts":["इसे ''दुनिया की छत'' (Roof of the World) कहा जाता है।","यह मध्य एशिया में स्थित है और कई प्रमुख पर्वत श्रृंखलाओं (जैसे हिमालय और काराकोरम) का केंद्र है।"],"factsEn":["It is known as the ''Roof of the World''.","It is located in Central Asia and is the center of major mountain ranges like the Himalayas and Karakoram."],"explanationHi":"इसकी अत्यधिक ऊंचाई और विशाल क्षेत्रफल के कारण इसे यह उपाधि दी गई है, जिसका औसत समुद्र तल से लगभग 4,500 मीटर ऊपर है।","explanationEn":"It earned this title due to its extreme height and vast area, averaging around 4,500 meters above sea level.","memoryTip":"पामीर का पठार दुनिया की ''छत'' है।","memoryTipEn":"Pamir is the Peak Plateau.","related":["Roof of the World","Himalayas","Karakoram"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5A41aZmnBPv1CEvuiP2Ss', 'General Knowledge', 'योजना आयोग (Planning Commission) का अध्यक्ष कौन होता है?', 'Who is the Chairman of the Planning Commission?', 'प्रधानमंत्री', 'Prime Minister', 90, 0, '{"facts":["योजना आयोग को 2015 में ''नीति आयोग'' (NITI Aayog) द्वारा प्रतिस्थापित किया गया है।","नीति आयोग के अध्यक्ष भी भारत के प्रधानमंत्री ही होते हैं।"],"factsEn":["The Planning Commission was replaced by NITI Aayog in 2015.","The Prime Minister is also the Chairman of NITI Aayog."],"explanationHi":"योजना आयोग भारत के लिए पंचवर्षीय योजनाएँ बनाता था, जिसके पदेन अध्यक्ष हमेशा प्रधानमंत्री होते थे।","explanationEn":"The Planning Commission formulated Five-Year Plans for India, with the Prime Minister always serving as its ex-officio chairman.","memoryTip":"देश की ''योजना'' का मुखिया देश का मुखिया (PM) होता है।","memoryTipEn":"The PM Plans for the nation.","related":["NITI Aayog","Five-Year Plans","National Development Council"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('s5dlO4FChqzmr0gRbIrXg', 'General Science', 'वनस्पति घी के निर्माण में कौनसी गैस प्रयुक्त होती है?', 'Which gas is used in the manufacture of Vanaspati Ghee?', 'हाइड्रोजन', 'Hydrogen', 92, 0, '{"facts":["इस रासायनिक प्रक्रिया को हाइड्रोजनीकरण (Hydrogenation) कहा जाता है।","इस प्रक्रिया में निकेल (Nickel) उत्प्रेरक (Catalyst) के रूप में कार्य करता है।"],"factsEn":["This chemical process is called Hydrogenation.","Nickel acts as a catalyst in this process."],"explanationHi":"तरल वनस्पति तेलों में हाइड्रोजन गैस प्रवाहित करने से वे ठोस वसा (वनस्पति घी) में बदल जाते हैं।","explanationEn":"Passing hydrogen gas through liquid vegetable oils converts them into solid fats (Vanaspati Ghee).","memoryTip":"तेल को ''हार्ड'' (ठोस) बनाने के लिए ''हाइड्रोजन'' डालते हैं।","memoryTipEn":"Hydrogen hardens the oil.","related":["Hydrogenation","Catalyst (Nickel)","Unsaturated Fats"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MRqWsoJlecEmR7E18IeYa', 'General Knowledge', 'इंग्लिश चैनल पार करने वाला पहला भारतीय कौन था?', 'Who was the first Indian to cross the English Channel?', 'मिहिर सेन', 'Mihir Sen', 88, 0, '{"facts":["उन्होंने 1958 में डोवर (इंग्लैंड) से कैलाइस (फ्रांस) तक तैरकर इसे पार किया था।","आरती साहा इंग्लिश चैनल पार करने वाली पहली भारतीय महिला थीं।"],"factsEn":["He swam from Dover (England) to Calais (France) to cross it in 1958.","Arati Saha was the first Indian woman to cross the English Channel."],"explanationHi":"मिहिर सेन न केवल इंग्लिश चैनल बल्कि पनामा नहर और जिब्राल्टर जलडमरूमध्य तैरकर पार करने वाले पहले एशियाई भी थे।","explanationEn":"Mihir Sen was not only the first Asian to swim the English Channel but also the Panama Canal and the Strait of Gibraltar.","memoryTip":"''मिहिर'' ने लहरों को चीर कर चैनल पार किया।","memoryTipEn":"Mihir made his mark in the marine channel.","related":["Arati Saha","English Channel","Swimming"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mhbVRgwm43U_qN_Z-H7Mb', 'General Science', 'एक अश्व शक्ति (Horsepower) कितने वाट के बराबर होती है?', 'One horsepower is equal to how many watts?', '746 वाट', '746 Watts', 95, 0, '{"facts":["अश्व शक्ति का उपयोग मुख्य रूप से इंजन और मोटरों की शक्ति (Power) मापने के लिए किया जाता है।","वाट (Watt) शक्ति की मानक अंतर्राष्ट्रीय (SI) इकाई है।"],"factsEn":["Horsepower is primarily used to measure the power of engines and motors.","Watt is the standard SI unit of power."],"explanationHi":"स्कॉटिश इंजीनियर जेम्स वाट ने भाप इंजन की शक्ति की तुलना घोड़ों की खींचने की क्षमता से करने के लिए यह इकाई बनाई थी।","explanationEn":"Scottish engineer James Watt coined this unit to compare the power of steam engines with the draft capacity of horses.","memoryTip":"7-4-6 (सात-चार-छह), घोड़े की दौड़ की तरह याद रखें।","memoryTipEn":"Seven-Four-Six, the horse does tricks.","related":["James Watt","Power","Kilowatt"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HdHsZa0-H8vDbVjb0vG0k', 'General Science', 'पानी की बूंदों के गोल होने का क्या कारण है?', 'What is the reason for water drops being spherical?', 'पृष्ठीय तनाव (Surface Tension)', 'Surface Tension', 97, 0, '{"facts":["पृष्ठीय तनाव तरल पदार्थों का वह गुण है जिससे वे अपना सतह क्षेत्र (surface area) कम से कम रखना चाहते हैं।","दी गई मात्रा के लिए, एक गोले (sphere) का सतह क्षेत्र सबसे कम होता है।"],"factsEn":["Surface tension is the property of liquids to minimize their surface area.","For a given volume, a sphere has the minimum surface area."],"explanationHi":"पानी के अणुओं के बीच आपसी आकर्षण बल (Cohesive force) बाहरी सतह को सिकोड़ने की कोशिश करता है, जिससे बूंदें गोल हो जाती हैं।","explanationEn":"The cohesive force between water molecules tries to shrink the outer surface, causing drops to become spherical.","memoryTip":"सतह के ''तनाव'' के कारण बूंद सिकुड़ कर गोल हो जाती है।","memoryTipEn":"Tension pulls it into a perfect sphere.","related":["Cohesive Force","Capillary Action","Viscosity"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UQ6IPqvYAY6vtJ79vU7-q', 'General Science', 'मानव निर्मित प्रथम रेशा (Fiber) कौनसा है?', 'Which is the first man-made fiber?', 'नायलॉन (Nylon)', 'Nylon', 93, 0, '{"facts":["यह पहला पूर्ण रूप से सिंथेटिक बहुलक (Synthetic Polymer) है, जिसे 1930 के दशक में बनाया गया था।","इसका निर्माण कोयला, पानी और हवा से किया गया था।"],"factsEn":["It is the first fully synthetic polymer, created in the 1930s.","It was synthesized from coal, water, and air."],"explanationHi":"नायलॉन बहुत मजबूत, हल्का और लचीला होता है, इसलिए इसका उपयोग कपड़े, रस्सियाँ और पैराशूट बनाने में होता है।","explanationEn":"Nylon is very strong, lightweight, and elastic, hence used in making clothes, ropes, and parachutes.","memoryTip":"नया (New) धागा जो इंसान ने ''लॉन्च'' किया = नायलॉन।","memoryTipEn":"NY-LON (New York - London) was a synthetic success.","related":["Rayon (Semi-synthetic)","Polyester","Synthetic Polymers"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5cW0cchLNI8nWGfqwKhay', 'General Science', 'स्पष्ट प्रतिध्वनि (Echo) सुनने के लिए श्रोता एवं परावर्तक के बीच कम से कम कितनी दूरी होनी चाहिए?', 'What should be the minimum distance between the listener and the reflector to hear a clear echo?', '17 मीटर', '17 meters', 91, 0, '{"facts":["मानव कान किसी ध्वनि के प्रभाव को 0.1 सेकंड (1/10 सेकंड) तक याद रखता है।","ध्वनि को परावर्तक तक जाने और वापस आने के लिए कम से कम 34 मीटर (17 मी. जाना + 17 मी. आना) की दूरी तय करनी चाहिए।"],"factsEn":["The human ear retains the effect of a sound for 0.1 seconds (1/10th of a second).","Sound must travel at least 34 meters (17m go + 17m return) to be heard distinctly."],"explanationHi":"यदि परावर्तक सतह 17 मीटर से कम दूरी पर है, तो परावर्तित ध्वनि मूल ध्वनि के साथ मिल जाएगी और स्पष्ट रूप से सुनाई नहीं देगी।","explanationEn":"If the reflecting surface is less than 17 meters away, the reflected sound will merge with the original sound and won''t be heard clearly.","memoryTip":"17 का खतरा, अगर दूरी कम हुई तो गूंज (Echo) नहीं सुनेगी।","memoryTipEn":"17 meters separates the sound from the echo.","related":["Speed of Sound","Reverberation","Acoustics"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2jD6JH5sjD6dIp3UmPN36', 'General Science', 'किस माध्यम में प्रकाश की चाल सर्वाधिक होती है?', 'In which medium is the speed of light the maximum?', 'निर्वात (Vacuum)', 'Vacuum', 96, 0, '{"facts":["निर्वात में प्रकाश की चाल लगभग 3,00,000 किलोमीटर प्रति सेकंड (3x10^8 m/s) होती है।","हवा में प्रकाश की गति निर्वात की तुलना में बहुत मामूली सी कम होती है।"],"factsEn":["The speed of light in a vacuum is approximately 300,000 km per second (3x10^8 m/s).","The speed of light in air is only marginally slower than in a vacuum."],"explanationHi":"प्रकाश एक विद्युत चुम्बकीय तरंग है जिसे यात्रा करने के लिए किसी भी भौतिक माध्यम की आवश्यकता नहीं होती; माध्यम के कण इसकी गति को धीमा करते हैं।","explanationEn":"Light is an electromagnetic wave requiring no physical medium to travel; particles in a medium only slow it down.","memoryTip":"जहाँ कुछ नहीं (निर्वात), वहाँ प्रकाश बिना रोक-टोक सबसे तेज़ भागता है।","memoryTipEn":"Light is fastest where there is nothing (Vacuum).","related":["Speed of Light","Electromagnetic Waves","Refractive Index"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QNximxXjiBBYZVTcFBsyp', 'General Science', 'किस रंग के प्रकाश का प्रकीर्णन (Scattering) सबसे अधिक होता है?', 'Which color of light is scattered the most?', 'बैंगनी (Violet)', 'Violet', 94, 0, '{"facts":["बैंगनी रंग की तरंगदैर्घ्य (Wavelength) सबसे कम होती है।","लाल रंग का प्रकीर्णन सबसे कम होता है क्योंकि इसकी तरंगदैर्घ्य सबसे अधिक होती है।"],"factsEn":["Violet light has the shortest wavelength.","Red light scatters the least because it has the longest wavelength."],"explanationHi":"रैले के नियम (Rayleigh scattering) के अनुसार, प्रकीर्णन तरंगदैर्घ्य के व्युत्क्रमानुपाती होता है, इसलिए छोटी तरंगें ज्यादा बिखरती हैं।","explanationEn":"According to Rayleigh''s law, scattering is inversely proportional to wavelength, so shorter waves scatter more.","memoryTip":"VIBGYOR में V (Violet) सबसे पहले है, इसलिए सबसे ज्यादा बिखरता है।","memoryTipEn":"Violet scatters violently.","related":["Rayleigh Scattering","Wavelength","Blue Sky (Blue scatters heavily too)"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GfV6HbWcl-IOozUAEhth9', 'General Science', 'वाहनों की हैडलाइट में किस दर्पण (Mirror) का उपयोग किया जाता है?', 'Which mirror is used in the headlights of vehicles?', 'अवतल दर्पण (Concave Mirror)', 'Concave Mirror', 96, 0, '{"facts":["यह प्रकाश की किरणों को एक सीधी और शक्तिशाली बीम (Beam) में केंद्रित करता है।","दाढ़ी बनाने वाले शीशे (Shaving mirrors) भी अवतल होते हैं।"],"factsEn":["It focuses the light rays into a straight and powerful beam.","Shaving mirrors are also concave."],"explanationHi":"जब बल्ब को अवतल दर्पण के फोकस पर रखा जाता है, तो दर्पण प्रकाश को एक समानांतर किरण के रूप में लंबी दूरी तक फेंकता है।","explanationEn":"When the bulb is placed at the focus of the concave mirror, it reflects the light as a parallel beam over a long distance.","memoryTip":"प्रकाश को ''अंदर'' (अवतल) समेट कर दूर तक फेंकता है।","memoryTipEn":"Concave catches and casts the light.","related":["Convex Mirror (Rear-view)","Focus","Reflectors"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('VaWkr3MDsMgHNU-pImn0B', 'General Science', 'आकाश में तारे टिमटिमाते (Twinkle) क्यों दिखते हैं?', 'Why do stars appear to twinkle in the sky?', 'प्रकाश के अपवर्तन (Refraction) के कारण', 'Due to atmospheric refraction of light', 95, 0, '{"facts":["पृथ्वी का वायुमंडल अलग-अलग तापमान और घनत्व वाली परतों से बना है।","ग्रह (Planets) नहीं टिमटिमाते क्योंकि वे तारों की तुलना में पृथ्वी के बहुत करीब हैं।"],"factsEn":["Earth''s atmosphere consists of layers with different temperatures and densities.","Planets do not twinkle because they are much closer to Earth than stars."],"explanationHi":"जब तारों का प्रकाश वायुमंडल से गुजरता है, तो हवा की परतों के कारण वह लगातार मुड़ता (Refract) है, जिससे तारे टिमटिमाते नजर आते हैं।","explanationEn":"When starlight passes through the atmosphere, it constantly bends (refracts) due to varying air layers, causing the twinkling effect.","memoryTip":"हवा के हिलने से रोशनी ''अपवर्तित'' होकर टिमटिमाती है।","memoryTipEn":"Refraction makes the stars react.","related":["Atmospheric Refraction","Scattering of Light","Mirage"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZXCM17-xyz-gGPBicChuw', 'General Science', 'प्राथमिक रंग (Primary Colors) किसे कहा जाता है?', 'Which are called the Primary Colors?', 'लाल, हरा, नीला (RGB)', 'Red, Green, Blue (RGB)', 92, 0, '{"facts":["इन तीन रंगों को मिलाकर सफेद प्रकाश सहित कोई भी अन्य रंग बनाया जा सकता है।","टेलीविज़न और कंप्यूटर मॉनिटर इसी ''RGB'' मॉडल का उपयोग करते हैं।"],"factsEn":["By mixing these three colors, any other color including white light can be created.","Televisions and computer monitors use this ''RGB'' model."],"explanationHi":"प्रकाश के मामले में लाल, हरा और नीला मूल रंग हैं। (ध्यान दें: पेंटिंग या वर्णक (Pigments) के प्राथमिक रंग लाल, पीला और नीला होते हैं)।","explanationEn":"In terms of light, Red, Green, and Blue are the fundamental colors. (Note: For pigments/painting, primary colors are Red, Yellow, Blue).","memoryTip":"ला-ह-नी (लाल, हरा, नीला) = प्रकाश के प्राथमिक रंग।","memoryTipEn":"RGB stands for Primary Lights.","related":["Secondary Colors","RGB Model","CMYK (Printers)"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1CZYLsNxSD8G4JV2Z4fhU', 'General Science', 'वायुयानों के टायरों में कौनसी गैस भरी जाती है?', 'Which gas is filled in airplane tires?', 'हीलियम (तथा नाइट्रोजन)', 'Helium (and Nitrogen)', 89, 0, '{"facts":["हवाई जहाज के टायरों में मुख्य रूप से नाइट्रोजन का उपयोग किया जाता है (आधुनिक समय में), हालांकि पीडीएफ स्रोत हीलियम बताता है।","ये गैसें अक्रिय (Inert) होती हैं और तापमान बदलने पर भी टायर के दबाव को स्थिर रखती हैं।"],"factsEn":["Modern airplane tires predominantly use Nitrogen, though the PDF source mentions Helium.","These gases are inert and keep tire pressure stable despite extreme temperature changes."],"explanationHi":"हवाई जहाज जब उतरता है तो टायरों में अत्यधिक घर्षण और गर्मी पैदा होती है; हीलियम या नाइट्रोजन ऑक्सीजन की तरह ज्वलनशील नहीं होती, जिससे आग लगने का खतरा टल जाता है।","explanationEn":"High friction and heat are generated during landing; Helium or Nitrogen are not highly reactive like oxygen, preventing fire risks.","memoryTip":"हवा में उड़ने वाले टायरों को ''हीलियम'' हल्का और सुरक्षित रखती है।","memoryTipEn":"Helium helps the tires hover safely.","related":["Nitrogen in tires","Inert Gases","Friction"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('G6oatthLJsw-DuIlXTGhX', 'General Science', 'टाँका धातु या सोल्डर (Solder) में किस धातु का मिश्रण होता है?', 'Solder is an alloy of which metals?', 'टिन व सीसा (Tin and Lead)', 'Tin and Lead', 91, 0, '{"facts":["सोल्डर का गलनांक (Melting point) बहुत कम होता है।","इसका उपयोग विद्युत तारों या इलेक्ट्रॉनिक उपकरणों (सर्किट बोर्ड) को जोड़ने के लिए किया जाता है।"],"factsEn":["Solder has a very low melting point.","It is used to join electrical wires or electronic components (circuit boards)."],"explanationHi":"टिन और सीसा (Lead) मिलाने से यह आसानी से पिघल जाता है और ठंडा होने पर एक मजबूत जोड़ बनाता है।","explanationEn":"The alloy of tin and lead melts easily and forms a strong joint upon cooling.","memoryTip":"तारों पर ''टाँका'' लगाने के लिए ''टिन'' और ''सीसा'' पिघलाते हैं।","memoryTipEn":"Solder with Tin and Lead.","related":["Alloys","Melting Point","Welding"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wl7YEPdgT6qZvfBp6JAcc', 'General Science', 'ग्लूकोमा रोग शरीर के किस अंग से संबंधित है?', 'Glaucoma is a disease associated with which part of the body?', 'आँख (Eye)', 'Eye', 94, 0, '{"facts":["ग्लूकोमा को ''काला मोतियाबिंद'' भी कहा जाता है।","यह आँख की ऑप्टिक तंत्रिका (Optic nerve) को नुकसान पहुंचाता है।"],"factsEn":["Glaucoma is also known as ''Kala Motiabind'' in Hindi.","It damages the optic nerve of the eye."],"explanationHi":"आँख के अंदर तरल पदार्थ का दबाव बढ़ने के कारण यह बीमारी होती है, जो समय के साथ स्थायी अंधापन ला सकती है।","explanationEn":"It is caused by abnormally high fluid pressure inside the eye, which can lead to permanent blindness over time.","memoryTip":"आँख में ''ग्लू'' (Glaucoma) लगने से रोशनी छिन सकती है।","memoryTipEn":"Glaucoma clouds the Vision.","related":["Cataract","Optic Nerve","Trachoma"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('afVAFp5lLHz0qipgzqK22', 'General Science', 'विश्व की पहली महिला अंतरिक्ष यात्री का नाम क्या है?', 'What is the name of the world''s first female astronaut (cosmonaut)?', 'वेलेंटाइना तेरेश्कोवा', 'Valentina Tereshkova', 95, 0, '{"facts":["वे सोवियत संघ (रूस) की नागरिक थीं।","उन्होंने 1963 में वोस्तोक-6 (Vostok 6) अंतरिक्ष यान से उड़ान भरी थी।"],"factsEn":["She was a citizen of the Soviet Union (Russia).","She flew aboard the Vostok 6 spacecraft in 1963."],"explanationHi":"अंतरिक्ष में जाने वाली पहली महिला बनकर उन्होंने महिलाओं के लिए एक नया इतिहास रचा।","explanationEn":"By becoming the first woman in space, she made history and broke barriers for women.","memoryTip":"अंतरिक्ष को ''वैलेंटाइन'' (Valentina) का तोहफा रूस ने दिया।","memoryTipEn":"Valentina ventured into the void.","related":["Yuri Gagarin","Vostok 6","Sally Ride (First US woman)"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xCEYre6YJ6BBnGVM__SXF', 'General Science', '''ऑरिजन ऑफ स्पीशिज बाई नेचुरल सलेक्शन'' पुस्तक के लेखक कौन थे?', 'Who was the author of the book ''Origin of Species by means of Natural Selection''?', 'चार्ल्स डार्विन', 'Charles Darwin', 96, 0, '{"facts":["यह पुस्तक 1859 में प्रकाशित हुई थी।","डार्विन ने एचएमएस बीगल (HMS Beagle) जहाज पर दुनिया भर की यात्रा की थी।"],"factsEn":["This book was published in 1859.","Darwin traveled around the world on the ship HMS Beagle."],"explanationHi":"इस पुस्तक ने जीव विज्ञान में क्रांति ला दी, जिसमें डार्विन ने विकासवाद (Evolution) और प्राकृतिक चयन (Natural Selection) का सिद्धांत दिया।","explanationEn":"This book revolutionized biology, introducing the theory of evolution and natural selection.","memoryTip":"प्रकृति ''डार्विन'' के विकासवाद के नियम से चलती है।","memoryTipEn":"Darwin discovered how species originate.","related":["Evolution","Natural Selection","HMS Beagle"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QRQXdCEnh4RorrMoeH_Ld', 'General Science', 'सिनेबार (Cinnabar) किस धातु का अयस्क है?', 'Cinnabar is an ore of which metal?', 'पारा या मरकरी (Mercury)', 'Mercury', 92, 0, '{"facts":["सिनेबार का रासायनिक नाम मरक्यूरिक सल्फाइड (HgS) है।","पारा कमरे के तापमान पर तरल अवस्था में रहने वाली एकमात्र धातु है।"],"factsEn":["The chemical name of Cinnabar is Mercuric Sulfide (HgS).","Mercury is the only metal that remains liquid at room temperature."],"explanationHi":"चमकीले लाल रंग के इस अयस्क को गर्म करके पारा (Mercury) धातु निकाली जाती है।","explanationEn":"Mercury metal is extracted by heating this bright red ore.","memoryTip":"''सिनेमा'' देखने के बाद बुखार (पारा) चढ़ गया।","memoryTipEn":"Cinnabar melts into Mercury.","related":["Mercury (Hg)","Ores","Thermometer"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0t_okjBskkBi-UmBJEMlD', 'General Science', 'कौन सा यंत्र दूध में पानी की मात्रा मापने के लिए प्रयोग किया जाता है?', 'Which instrument is used to measure the amount of water in milk (purity of milk)?', 'लैक्टोमीटर', 'Lactometer', 93, 0, '{"facts":["यह आर्कमिडीज के सिद्धांत (Principle of Flotation/Buoyancy) पर काम करता है।","दूध में मौजूद शर्करा को लैक्टोज (Lactose) कहा जाता है।"],"factsEn":["It works on Archimedes'' Principle (Principle of Flotation).","The sugar present in milk is called Lactose."],"explanationHi":"यह उपकरण दूध के विशिष्ट घनत्व (Specific Gravity) को मापता है। पानी मिलाने पर दूध का घनत्व कम हो जाता है।","explanationEn":"This instrument measures the specific gravity of milk. Adding water decreases the density of milk.","memoryTip":"दूध से जुड़े हर शब्द में ''लैक्टो'' आता है।","memoryTipEn":"Lacto relates to milk.","related":["Hydrometer","Archimedes'' Principle","Lactic Acid"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8D9HJeOE1it4IKIaRf8R-', 'General Science', '"हाइड्रोजन बम्ब" किस सिद्धांत पर आधारित है?', 'On which principle is the "Hydrogen Bomb" based?', 'नाभिकीय संलयन (Nuclear Fusion)', 'Nuclear Fusion', 95, 0, '{"facts":["सूर्य और अन्य तारों की ऊर्जा का स्रोत भी नाभिकीय संलयन है।","परमाणु बम (Atomic Bomb) नाभिकीय विखंडन (Nuclear Fission) पर आधारित होता है।"],"factsEn":["Nuclear fusion is also the source of energy for the Sun and stars.","An Atomic Bomb is based on Nuclear Fission."],"explanationHi":"हाइड्रोजन बम में हाइड्रोजन के हल्के नाभिक आपस में जुड़कर (संलयन) हीलियम बनाते हैं, जिससे भारी मात्रा में ऊर्जा निकलती है।","explanationEn":"In a hydrogen bomb, light hydrogen nuclei fuse together to form helium, releasing a massive amount of energy.","memoryTip":"संलयन (Fusion) में परमाणु ''मिलते'' हैं, जिससे महा-विस्फोट (H-Bomb) होता है।","memoryTipEn":"Fusion fuses hydrogen.","related":["Nuclear Fission","Edward Teller (Father of H-Bomb)","Nuclear Reactor"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vv5g_qqhccF6fGjcNqJrR', 'General Science', 'पैलाग्रा रोग किस विटामिन की कमी से होता है?', 'Pellagra disease is caused by the deficiency of which vitamin?', 'विटामिन B-3', 'Vitamin B3', 90, 0, '{"facts":["विटामिन B3 का रासायनिक नाम नियासिन (Niacin) है।","पैलाग्रा रोग मुख्य रूप से ''3 डी'' (3 D''s) का कारण बनता है: डर्मेटाइटिस, डायरिया और डिमेंशिया।"],"factsEn":["The chemical name of Vitamin B3 is Niacin.","Pellagra is characterized by the ''3 D''s'': Dermatitis, Diarrhea, and Dementia."],"explanationHi":"इस विटामिन की कमी से त्वचा पर चकत्ते (Dermatitis), पेट खराब होना और मानसिक भ्रम (Dementia) जैसी समस्याएं हो जाती हैं।","explanationEn":"Deficiency of this vitamin causes skin rashes, upset stomach, and mental confusion.","memoryTip":"B-3 कम होने पर त्वचा की ''परत'' (पैलाग्रा) खराब होने लगती है।","memoryTipEn":"Pellagra attacks the skin (Pelle means skin).","related":["Niacin","Water-soluble vitamins","Dermatitis"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QJ-br5ILdGK1acLeJdBl3', 'General Science', 'मछलियों के यकृत-तेल (Liver oil) में किसकी प्रचुरता होती है?', 'Fish liver oil is rich in which vitamin?', 'विटामिन D (तथा A)', 'Vitamin D (and A)', 91, 0, '{"facts":["कॉड लिवर ऑयल (Cod liver oil) विटामिन D और ओमेगा-3 फैटी एसिड का एक बहुत अच्छा स्रोत है।","विटामिन A भी इसमें अच्छी मात्रा में होता है।"],"factsEn":["Cod liver oil is an excellent source of Vitamin D and Omega-3 fatty acids.","Vitamin A is also present in good amounts."],"explanationHi":"सर्दियों या कम धूप वाले इलाकों में रहने वाले लोग हड्डियों को मजबूत रखने के लिए इसे सप्लीमेंट के रूप में लेते हैं।","explanationEn":"People living in regions with less sunlight take it as a supplement to keep their bones strong.","memoryTip":"मछली के तेल से ''धूप'' (Vitamin D) जैसी ताकत मिलती है।","memoryTipEn":"Fish oil fortifies bones with D.","related":["Cod Liver Oil","Omega-3 Fatty Acids","Rickets"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CJhBWurPyN1mh2A_0unPt', 'General Science', 'भूस्थिर उपग्रह (Geostationary Satellite) की पृथ्वी से ऊँचाई कितनी होती है?', 'What is the height of a geostationary satellite from the Earth?', '36,000 किलोमीटर', '36,000 Kilometers', 93, 0, '{"facts":["इन उपग्रहों का परिक्रमण काल (Orbital period) पृथ्वी के घूर्णन काल (24 घंटे) के बराबर होता है।","ये हमेशा भूमध्य रेखा (Equator) के ठीक ऊपर होते हैं।"],"factsEn":["The orbital period of these satellites is equal to Earth''s rotation period (24 hours).","They are always positioned directly above the Equator."],"explanationHi":"चूंकि इनकी गति पृथ्वी के घूमने की गति से मेल खाती है, इसलिए पृथ्वी से देखने पर ये आकाश में एक ही स्थान पर स्थिर (Stationary) दिखाई देते हैं।","explanationEn":"Since their speed matches Earth''s rotation, they appear stationary in the sky to an observer on the ground.","memoryTip":"36 हज़ार किमी की ऊंचाई से टीवी और मौसम का प्रसारण होता है।","memoryTipEn":"36k keeps it still in the sky.","related":["Communication Satellites","Geosynchronous Orbit","ISRO"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xb4xKj52sM5B8fuzJw3Kb', 'General Science', 'मनुष्य के शरीर का तापमान कितना होता है?', 'What is the normal body temperature of a human?', '37°C या 98.4°F', '37°C or 98.4°F (approx. 98.6°F)', 95, 0, '{"facts":["केल्विन (Kelvin) पैमाने पर मानव शरीर का सामान्य तापमान 310 K होता है।","हाइपोथैलेमस (मस्तिष्क का हिस्सा) शरीर के तापमान को नियंत्रित करता है।"],"factsEn":["On the Kelvin scale, the normal human body temperature is 310 K.","The hypothalamus (part of the brain) regulates body temperature."],"explanationHi":"मानव ''समतापी'' (Warm-blooded) प्राणी है, इसलिए हमारा शरीर बाहरी मौसम के बावजूद अंदरूनी तापमान को 37°C पर बनाए रखता है।","explanationEn":"Humans are warm-blooded, maintaining an internal core temperature of 37°C regardless of external weather conditions.","memoryTip":"डिग्री में 37, फॉरेनहाइट में 98 के पार।","memoryTipEn":"37 degrees keeps humans warm.","related":["Hypothalamus","Thermometer","Warm-blooded (Endotherms)"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-s8Ve6iylWzfh3wACWjJZ', 'General Science', 'लेंस की क्षमता का मात्रक क्या है?', 'What is the unit of power of a lens?', 'डायोप्टर (Diopter)', 'Diopter', 94, 0, '{"facts":["लेंस की क्षमता (Power) उसकी फोकस दूरी (Focal length) के व्युत्क्रमानुपाती (Inversely proportional) होती है (P = 1/f)।","उत्तल लेंस की क्षमता धनात्मक (+) और अवतल लेंस की ऋणात्मक (-) होती है।"],"factsEn":["Power of a lens is inversely proportional to its focal length (P = 1/f in meters).","Power is positive (+) for convex lenses and negative (-) for concave lenses."],"explanationHi":"जब डॉक्टर चश्मे का नंबर बताते हैं (जैसे +2.0 या -1.5), तो वह डायोप्टर में लेंस की क्षमता ही बता रहे होते हैं।","explanationEn":"When an eye doctor gives an eyeglass prescription (like +2.0 or -1.5), it denotes the lens power in Diopters.","memoryTip":"लेंस की ''डायरेक्शन'' ठीक करने की क्षमता = डायोप्टर।","memoryTipEn":"Diopter Dictates the lens power.","related":["Focal Length","Convex Lens","Myopia"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DP_zxxXQzD2TRUDvs7TZh', 'General Science', 'कम्प्यूटर की IC चिप्स किस पदार्थ की बनी होती हैं?', 'Computer IC chips are made of which material?', 'सिलिकन (Silicon) की', 'Silicon', 93, 0, '{"facts":["IC का पूर्ण रूप ''Integrated Circuit'' (एकीकृत परिपथ) है।","सिलिकॉन एक अर्धचालक (Semiconductor) सामग्री है।"],"factsEn":["IC stands for ''Integrated Circuit''.","Silicon is a semiconductor material."],"explanationHi":"सिलिकॉन विद्युत प्रवाह को आसानी से नियंत्रित कर सकता है, इसलिए इसे दुनिया भर के सभी इलेक्ट्रॉनिक उपकरणों में उपयोग किया जाता है।","explanationEn":"Silicon can easily control the flow of electricity, making it the foundational material for all electronic devices globally.","memoryTip":"कंप्यूटर का दिमाग ''सिली'' (Silicon) नहीं, बहुत तेज होता है।","memoryTipEn":"Silicon powers the circuit.","related":["Semiconductor","Silicon Valley","Jack Kilby (Inventor of IC)"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('98m_cGaP2l4mSYml_3Fnn', 'General Science', 'पारसेक (Parsec) किसकी इकाई है?', 'Parsec is a unit of what?', 'खगोलीय दूरी की', 'Astronomical Distance', 92, 0, '{"facts":["एक पारसेक लगभग 3.26 प्रकाश वर्ष (Light Years) के बराबर होता है।","यह ब्रह्मांड में दूरियां मापने की सबसे बड़ी मानक इकाइयों में से एक है।"],"factsEn":["One Parsec is approximately equal to 3.26 Light Years.","It is one of the largest standard units used to measure cosmic distances."],"explanationHi":"इसका उपयोग हमारे सौरमंडल के बाहर स्थित बहुत दूर के तारों और आकाशगंगाओं की दूरी मापने के लिए किया जाता है।","explanationEn":"It is used to measure the vast distances to faraway stars and galaxies outside our solar system.","memoryTip":"अंतरिक्ष को ''पार'' करने वाली दूरी = पारसेक।","memoryTipEn":"Parsec parses the universe''s distance.","related":["Light Year","Astronomical Unit (AU)","Astronomy"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zCjx1iNtSnCRtXWV-99by', 'General Science', 'पानी का घनत्व (Density) अधिकतम किस तापमान पर होता है?', 'At what temperature is the density of water maximum?', '4°C पर', 'At 4°C', 96, 0, '{"facts":["4°C के बाद पानी को ठंडा करने पर उसका घनत्व कम होने लगता है और आयतन बढ़ने लगता है।","इसी कारण बर्फ पानी पर तैरती है (बर्फ का घनत्व पानी से कम होता है)।"],"factsEn":["Cooling water below 4°C makes it less dense and increases its volume.","This is why ice floats on water (ice is less dense than liquid water)."],"explanationHi":"पानी के इस असामान्य व्यवहार (Anomalous expansion) के कारण ही ठंडे प्रदेशों में झीलों के नीचे का पानी नहीं जमता और मछलियां जीवित रहती हैं।","explanationEn":"Due to this anomalous expansion of water, the bottom of lakes in cold regions doesn''t freeze, allowing aquatic life to survive.","memoryTip":"4 डिग्री पर पानी सबसे ''भारी'' (dense) हो जाता है।","memoryTipEn":"Water gets dense at four.","related":["Anomalous Expansion of Water","Buoyancy","Freezing Point"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3a3eAbE7vNxCs4eHrtPa0', 'General Science', 'पराश्रव्य तरंगों (Ultrasonic waves) की आवृत्ति कितनी होती है?', 'What is the frequency of Ultrasonic waves?', '20,000 हर्ट्ज से अधिक', 'More than 20,000 Hz', 92, 0, '{"facts":["मानव कान इन तरंगों को नहीं सुन सकते।","चमगादड़ और डॉल्फिन इन तरंगों का उपयोग शिकार खोजने और नेविगेशन (Echolocation) के लिए करते हैं।"],"factsEn":["Human ears cannot hear these waves.","Bats and dolphins use these waves for hunting and navigation (Echolocation)."],"explanationHi":"चिकित्सा क्षेत्र में अल्ट्रासाउंड (सोनोग्राफी) मशीनें शरीर के अंदर की तस्वीरें बनाने के लिए इन्हीं तरंगों का उपयोग करती हैं।","explanationEn":"In the medical field, ultrasound (sonography) machines use these waves to create images of the inside of the body.","memoryTip":"परा (Par) मतलब परे, यानी हमारे सुनने की सीमा (20,000 Hz) के परे।","memoryTipEn":"Ultra means beyond human hearing.","related":["Infrasonic Waves (<20 Hz)","Audible Range","SONAR"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rPa2TXQfYcQzCtwYXPJqh', 'General Science', 'मनुष्य का वैज्ञानिक नाम क्या है?', 'What is the scientific name of human beings?', 'होमो सेपियन्स (Homo sapiens)', 'Homo sapiens', 94, 0, '{"facts":["''होमो'' जीनस (Genus) है और ''सेपियन्स'' प्रजाति (Species) है।","लैटिन भाषा में ''होमो सेपियन्स'' का अर्थ है ''बुद्धिमान व्यक्ति'' (Wise Man)।"],"factsEn":["''Homo'' is the genus and ''sapiens'' is the species.","In Latin, ''Homo sapiens'' translates to ''Wise Man''."],"explanationHi":"कार्ल लिनिअस ने 1758 में जीवों के नामकरण की इस द्विपद (Binomial) प्रणाली की शुरुआत की थी।","explanationEn":"Carl Linnaeus introduced this binomial nomenclature system for classifying living organisms in 1758.","memoryTip":"इंसान ''होमो'' की दुनिया का ''समझदार'' (सपियन्स) प्राणी है।","memoryTipEn":"Homo sapiens means wise human.","related":["Binomial Nomenclature","Carl Linnaeus","Taxonomy"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_6NqbHu5GfYmBJfhoyJRk', 'General Knowledge', 'ब्रिटिश संसद के लिए चुने जाने वाले पहले भारतीय कौन थे?', 'Who was the first Indian to be elected to the British Parliament?', 'दादा भाई नौरोजी', 'Dadabhai Naoroji', 95, 0, '{"facts":["उन्हें ''भारत का वयोवृद्ध पुरुष'' (Grand Old Man of India) कहा जाता है।","वे 1892 में लिबरल पार्टी के टिकट पर हाउस ऑफ कॉमन्स के लिए चुने गए थे।"],"factsEn":["He is known as the ''Grand Old Man of India''.","He was elected to the House of Commons in 1892 on a Liberal Party ticket."],"explanationHi":"उन्होंने ''धन निष्कासन सिद्धांत'' (Drain of Wealth theory) दिया था, जिसमें बताया गया कि कैसे अंग्रेज भारत का धन लूट रहे हैं।","explanationEn":"He formulated the ''Drain of Wealth'' theory, explaining how the British were exploiting India''s wealth.","memoryTip":"देश के ''दादा'' ने ब्रिटेन की संसद में भारत की आवाज़ उठाई।","memoryTipEn":"Dadabhai Naoroji was the Grand Old pioneer.","related":["Grand Old Man of India","Drain of Wealth Theory","Poverty and Un-British Rule in India"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('axwuTFvC4pbE4a8gkWl7k', 'General Knowledge', 'भारत के किस राज्य में चावल का सबसे अधिक उत्पादन होता है?', 'Which state is the largest producer of rice in India?', 'पश्चिमी बंगाल', 'West Bengal', 93, 0, '{"facts":["गंगा और ब्रह्मपुत्र के उपजाऊ डेल्टा क्षेत्र के कारण यहाँ चावल की खेती सबसे अच्छी होती है।","इसके बाद उत्तर प्रदेश और पंजाब का स्थान आता है।"],"factsEn":["Rice cultivation thrives here due to the fertile delta region of the Ganga and Brahmaputra.","It is followed by Uttar Pradesh and Punjab."],"explanationHi":"पश्चिम बंगाल की जलवायु (भारी वर्षा और उच्च आर्द्रता) चावल की फसल (धान) के लिए बहुत अनुकूल है।","explanationEn":"West Bengal''s climate (heavy rainfall and high humidity) is highly favorable for the rice crop (paddy).","memoryTip":"बंगाल में ''माछ-भात'' (मछली-चावल) मशहूर है, क्योंकि चावल खूब उगता है।","memoryTipEn":"Bengal grows the most grains of rice.","related":["Paddy Cultivation","Ganges Delta","Uttar Pradesh (Highest Wheat)"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('tRs9pmNcZB5dn90dnIV5H', 'General Knowledge', 'भारत में ब्रह्मा जी का एकमात्र मंदिर कहाँ है?', 'Where is the only temple of Lord Brahma in India located?', 'पुष्कर (राजस्थान)', 'Pushkar (Rajasthan)', 88, 0, '{"facts":["यह मंदिर पुष्कर झील के पास स्थित है।","यहाँ हर साल प्रसिद्ध ''पुष्कर ऊंट मेला'' (Pushkar Camel Fair) लगता है।"],"factsEn":["The temple is located near the Pushkar Lake.","The famous ''Pushkar Camel Fair'' is held here annually."],"explanationHi":"पौराणिक कथाओं के अनुसार एक श्राप के कारण भगवान ब्रह्मा की पूजा मुख्य रूप से केवल पुष्कर में ही की जाती है।","explanationEn":"According to mythology, due to a curse, Lord Brahma is primarily worshipped only at Pushkar.","memoryTip":"ब्रह्मा जी ''पुष्प'' (कमल) पर बैठते हैं, और उनका मंदिर ''पुष्कर'' में है।","memoryTipEn":"Pushkar holds the rare Brahma temple.","related":["Pushkar Camel Fair","Lord Brahma","Rajasthan Tourism"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xRpiFigE_LN65anBL0V4Z', 'General Science', 'पागल कुत्ते के काटने से कौनसा रोग होता है?', 'Which disease is caused by the bite of a mad dog?', 'रैबीज या हाइड्रोफोबिया', 'Rabies or Hydrophobia', 96, 0, '{"facts":["यह एक जानलेवा वायरल संक्रमण है जो केंद्रीय तंत्रिका तंत्र को प्रभावित करता है।","''हाइड्रोफोबिया'' का अर्थ है पानी से डर लगना, जो इस बीमारी का एक प्रमुख लक्षण है।"],"factsEn":["It is a fatal viral infection affecting the central nervous system.","''Hydrophobia'' means fear of water, which is a primary symptom of this disease."],"explanationHi":"यह वायरस जानवरों की लार से इंसानों में फैलता है। लुई पाश्चर ने रैबीज का पहला टीका विकसित किया था।","explanationEn":"The virus is transmitted from the saliva of animals to humans. Louis Pasteur developed the first rabies vaccine.","memoryTip":"कुत्ते के काटने से पानी (Hydro) से फोबिया (डर) हो जाता है।","memoryTipEn":"Rabid dogs pass the rabies virus.","related":["Louis Pasteur","Viral Disease","Central Nervous System"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2Ngx5vMXu599Cv-leIVfN', 'General Knowledge', 'राज्यसभा का पदेन सभापति (Ex-officio Chairman) कौन होता है?', 'Who is the ex-officio Chairman of the Rajya Sabha?', 'उपराष्ट्रपति', 'Vice President', 94, 0, '{"facts":["संविधान के अनुच्छेद 64 के अनुसार भारत का उपराष्ट्रपति राज्यसभा का पदेन सभापति होता है।","वे राज्यसभा के सदस्य नहीं होते हैं और उन्हें मतदान का अधिकार केवल ''निर्णायक मत'' (Casting vote) की स्थिति में होता है।"],"factsEn":["Under Article 64, the Vice President of India is the ex-officio Chairman of the Rajya Sabha.","They are not a member of the Rajya Sabha and can only cast a vote in case of a tie (Casting vote)."],"explanationHi":"यह व्यवस्था अमेरिका के संविधान से ली गई है, जहाँ उपराष्ट्रपति सीनेट (Senate) का अध्यक्ष होता है।","explanationEn":"This arrangement is borrowed from the US Constitution, where the VP is the President of the Senate.","memoryTip":"उपराष्ट्रपति के पास दूसरा कोई काम नहीं होता, इसलिए वे राज्यसभा संभालते हैं।","memoryTipEn":"Vice President presides over the upper house.","related":["Article 64","Lok Sabha Speaker","Parliament of India"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('c3WkCt7XmFCkjLXC03w7z', 'General Science', 'दो बार नोबल पुरस्कार प्राप्त करने वाले प्रथम व्यक्ति कौन है?', 'Who is the first person to receive the Nobel Prize twice?', 'मैडम मैरी क्यूरी', 'Marie Curie', 95, 0, '{"facts":["उन्हें 1903 में भौतिकी (Physics) में और 1911 में रसायन विज्ञान (Chemistry) में नोबेल पुरस्कार मिला।","उन्होंने रेडियम और पोलोनियम तत्वों की खोज की थी।"],"factsEn":["She won the Nobel in Physics in 1903 and in Chemistry in 1911.","She discovered the elements Radium and Polonium."],"explanationHi":"वे न केवल पहली महिला नोबेल विजेता थीं, बल्कि दो अलग-अलग वैज्ञानिक क्षेत्रों में नोबेल जीतने वाली आज तक की एकमात्र व्यक्ति हैं।","explanationEn":"Not only was she the first woman to win a Nobel, but she remains the only person to win in two different scientific fields.","memoryTip":"मैडम ''क्यूरी'' का दिमाग दो नोबेल लाने जितना ''क्यूरियस'' (उत्सुक) था।","memoryTipEn":"Marie Curie secured two distinct Nobels.","related":["Radioactivity","Radium","Pierre Curie"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oo38XW_K1eVkBh_2RgQK6', 'General Knowledge', 'SAARC (सार्क) या दक्षेस का मुख्यालय कहाँ है?', 'Where is the headquarters of SAARC located?', 'काठमांडू (नेपाल)', 'Kathmandu (Nepal)', 92, 0, '{"facts":["SAARC (South Asian Association for Regional Cooperation) की स्थापना 1985 में हुई थी।","इसमें 8 सदस्य देश हैं।"],"factsEn":["SAARC was established in 1985.","It consists of 8 member countries."],"explanationHi":"यह दक्षिण एशिया के देशों का एक आर्थिक और राजनीतिक संगठन है, जो आपसी सहयोग को बढ़ावा देता है।","explanationEn":"It is an economic and political organization of South Asian countries aiming to promote regional cooperation.","memoryTip":"दक्षिण के आठ देश ''काठमांडू'' में बैठक करते हैं।","memoryTipEn":"Kathmandu hosts the SAARC meetings.","related":["Member Countries of SAARC","BIMSTEC","Regional Organizations"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Qntu2qPL-7fG5v6jzAwAt', 'General Knowledge', 'प्रथम परमवीर चक्र विजेता कौन थे?', 'Who was the first recipient of the Param Vir Chakra?', 'मेजर सोमनाथ शर्मा', 'Major Somnath Sharma', 93, 0, '{"facts":["उन्हें 1947 के भारत-पाकिस्तान युद्ध (बडगाम की लड़ाई) में उनके अदम्य साहस के लिए मरणोपरांत यह पुरस्कार दिया गया।","वे कुमाऊं रेजिमेंट की चौथी बटालियन से थे।"],"factsEn":["He was awarded posthumously for his supreme gallantry during the 1947 Indo-Pak war (Battle of Badgam).","He belonged to the 4th Battalion of the Kumaon Regiment."],"explanationHi":"परमवीर चक्र भारत का सर्वोच्च सैन्य सम्मान है जो युद्ध के दौरान वीरता के लिए दिया जाता है।","explanationEn":"The Param Vir Chakra is India''s highest military decoration awarded for valor during wartime.","memoryTip":"सबसे ''परम'' वीर ''सोमनाथ'' शर्मा थे।","memoryTipEn":"Somnath Sharma was the First Param Vir.","related":["Param Vir Chakra","Indo-Pak War 1947","Kumaon Regiment"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('OJ6SlqAxEhRDn-OTMIB9f', 'General Knowledge', 'भारतीय राष्ट्रीय कांग्रेस की पहली भारतीय महिला अध्यक्ष कौन थी?', 'Who was the first Indian woman President of the Indian National Congress?', 'सरोजिनी नायडू', 'Sarojini Naidu', 95, 0, '{"facts":["उन्होंने 1925 में कांग्रेस के कानपुर अधिवेशन की अध्यक्षता की थी।","इन्हें ''भारत कोकिला'' (Nightingale of India) भी कहा जाता है।"],"factsEn":["She presided over the Kanpur session of Congress in 1925.","She is also known as the ''Nightingale of India''."],"explanationHi":"यदि सिर्फ ''पहली महिला अध्यक्ष'' पूछा जाए तो उत्तर ऐनी बेसेंट (1917) होगा, लेकिन ''भारतीय महिला'' सरोजिनी नायडू थीं।","explanationEn":"If asked for the ''first woman president'', it was Annie Besant (1917), but the ''first Indian woman'' was Sarojini Naidu.","memoryTip":"पहली भारतीय महिला अध्यक्ष ''नायडू'' जी थीं।","memoryTipEn":"Sarojini Naidu was the first native lady to lead INC.","related":["Annie Besant","Kanpur Session 1925","First Female Governor"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CSBYTlMWzM3L4OthxVsv7', 'General Knowledge', 'सन 1983 की विश्व कप विजेता भारतीय क्रिकेट टीम के कप्तान कौन थे?', 'Who was the captain of the 1983 World Cup-winning Indian cricket team?', 'कपिल देव', 'Kapil Dev', 90, 0, '{"facts":["भारत ने फाइनल में शक्तिशाली वेस्टइंडीज (West Indies) को हराया था।","कपिल देव को ''हरियाणा हरिकेन'' (Haryana Hurricane) भी कहा जाता है।"],"factsEn":["India defeated the mighty West Indies in the final.","Kapil Dev is also known as the ''Haryana Hurricane''."],"explanationHi":"यह क्रिकेट इतिहास में भारत का पहला विश्व कप था, जिसने देश में क्रिकेट को सबसे लोकप्रिय खेल बना दिया।","explanationEn":"It was India''s first World Cup victory in cricket history, transforming it into the nation''s most popular sport.","memoryTip":"1983 में ''कपिल'' के ''देव''त्व से भारत ने कप जीता।","memoryTipEn":"Kapil Dev led the 83 victory.","related":["1983 Cricket World Cup","Haryana Hurricane","M.S. Dhoni (2011 WC Captain)"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JXHhZ9QSGu6EzCs_aMUB4', 'General Knowledge', 'राष्ट्रपति राज्यसभा में कितने सदस्य मनोनीत कर सकता है?', 'How many members can the President nominate to the Rajya Sabha?', '12', '12', 95, 0, '{"facts":["ये सदस्य साहित्य, विज्ञान, कला और समाज सेवा के क्षेत्र में विशेष ज्ञान या व्यावहारिक अनुभव रखने वाले लोग होते हैं।","राज्यसभा की अधिकतम सदस्य संख्या 250 हो सकती है।"],"factsEn":["These members are individuals with special knowledge or practical experience in literature, science, art, and social service.","The maximum strength of the Rajya Sabha can be 250."],"explanationHi":"इस मनोनयन का उद्देश्य यह सुनिश्चित करना है कि देश के प्रतिष्ठित और अनुभवी व्यक्ति बिना चुनाव लड़े संसद के माध्यम से देश सेवा कर सकें।","explanationEn":"The purpose of this nomination is to ensure that eminent and experienced persons can serve the country through parliament without contesting elections.","memoryTip":"राज्यसभा में 1 दर्जन (12) लोगों को राष्ट्रपति सीधे बिठाता है।","memoryTipEn":"President picks a dozen for the upper house.","related":["Rajya Sabha","Article 80","Parliament of India"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4nkgm9_gLAOr7ENEEdpY-', 'General Knowledge', 'नोबल पुरस्कार किस वर्ष शुरु हुए?', 'In which year were the Nobel Prizes started?', '1901', '1901', 92, 0, '{"facts":["ये पुरस्कार अल्फ्रेड नोबेल (स्वीडिश वैज्ञानिक, डायनामाइट के आविष्कारक) की वसीयत के आधार पर दिए जाते हैं।","अर्थशास्त्र का नोबेल पुरस्कार 1968 में स्वीडन के केंद्रीय बैंक द्वारा जोड़ा गया।"],"factsEn":["These prizes are awarded based on the will of Alfred Nobel (Swedish scientist, inventor of dynamite).","The Nobel Prize in Economics was added in 1968 by Sweden''s central bank."],"explanationHi":"हर साल 10 दिसंबर को अल्फ्रेड नोबेल की पुण्यतिथि पर स्टॉकहोम (और शांति के लिए ओस्लो) में ये पुरस्कार दिए जाते हैं।","explanationEn":"These prizes are awarded every year on Dec 10, the death anniversary of Alfred Nobel, in Stockholm (and Oslo for Peace).","memoryTip":"1901 (शुरुआती 20वीं सदी) से दुनिया के सबसे बड़े पुरस्कार की शुरुआत हुई।","memoryTipEn":"Nobel began in nineteen-o-one.","related":["Alfred Nobel","Nobel Peace Prize (Oslo)","Nobel Prize in Literature"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YYZxadx-uL83eeE08jucA', 'General Knowledge', 'बंग्लादेश की मुद्रा कौनसी है?', 'What is the currency of Bangladesh?', 'टका', 'Taka', 88, 0, '{"facts":["बांग्लादेश की राजधानी ढाका है।","इसका केंद्रीय बैंक ''बांग्लादेश बैंक'' कहलाता है।"],"factsEn":["The capital of Bangladesh is Dhaka.","Its central bank is called ''Bangladesh Bank''."],"explanationHi":"प्राचीन काल में ''टका'' का इस्तेमाल चांदी के सिक्कों के लिए होता था, जिसे बाद में बांग्लादेश ने अपनी राष्ट्रीय मुद्रा के रूप में अपनाया।","explanationEn":"Historically, ''Taka'' was used to refer to silver coins, which Bangladesh later adopted as its national currency.","memoryTip":"बांग्ला में सब कुछ ''टका-टक'' (टका) चलता है।","memoryTipEn":"Take a Taka to Bangladesh.","related":["Dhaka","Rupee (India)","Neighbouring Countries"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XRSuyA2nS3LXnyuXihtYk', 'General Knowledge', 'रामायण किसने लिखी?', 'Who wrote the Ramayana?', 'महर्षि बाल्मीकि', 'Maharishi Valmiki', 93, 0, '{"facts":["मूल रामायण संस्कृत भाषा में लिखी गई थी।","इसमें सात ''कांड'' (अध्याय) और 24,000 श्लोक हैं।"],"factsEn":["The original Ramayana was written in Sanskrit.","It consists of seven ''Kandas'' (books) and 24,000 verses."],"explanationHi":"तुलसीदास जी ने जो अवधी भाषा में लिखा है उसे ''रामचरितमानस'' कहते हैं, जबकि मूल संस्कृत महाकाव्य बाल्मीकि जी का है।","explanationEn":"The version written by Tulsidas in Awadhi is called ''Ramcharitmanas'', while the original Sanskrit epic is by Valmiki.","memoryTip":"''बाल'' (बाल्मीकि) अवस्था से ही राम की कथा सुनी।","memoryTipEn":"Valmiki composed the original Ramayana.","related":["Ramcharitmanas (Tulsidas)","Mahabharata (Ved Vyas)","Sanskrit Epics"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('O3r2RNVynLPO9FfM8kUWs', 'General Knowledge', 'भारत में गन्ने (Sugarcane) का सर्वाधिक उत्पादन किस राज्य में होता है?', 'Which state is the largest producer of sugarcane in India?', 'उत्तर प्रदेश', 'Uttar Pradesh', 94, 0, '{"facts":["उत्तर प्रदेश को भारत का ''चीनी का कटोरा'' (Sugar bowl of India) भी कहा जाता है।","गन्ने के उत्पादन में महाराष्ट्र दूसरे स्थान पर है।"],"factsEn":["Uttar Pradesh is also known as the ''Sugar bowl of India''.","Maharashtra stands second in sugarcane production."],"explanationHi":"गंगा के उपजाऊ मैदानी इलाके और सिंचाई की अच्छी सुविधा के कारण यूपी में गन्ना भारी मात्रा में उगाया जाता है।","explanationEn":"Due to the fertile Gangetic plains and good irrigation facilities, sugarcane is grown in massive quantities in UP.","memoryTip":"गन्ने की ''मिठास'' सबसे ज्यादा ''यूपी'' में है।","memoryTipEn":"UP produces the most sugar.","related":["Sugar Bowl of India","Cash Crop","Maharashtra (Sugarcane)"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NtaX1PYAkbS8RhZbYRAoo', 'General Science', 'पायोरिया (Pyorrhea) रोग शरीर के किस अंग को प्रभावित करता है?', 'Pyorrhea disease affects which part of the body?', 'दांत और मसूड़े', 'Teeth and Gums', 91, 0, '{"facts":["यह एक मसूड़ों का संक्रमण है (Periodontitis) जो दांतों को सहारा देने वाली हड्डी को नुकसान पहुंचाता है।","इससे मुंह से दुर्गंध आती है और मसूड़ों से खून निकलता है।"],"factsEn":["It is a gum infection (Periodontitis) that damages the bone supporting the teeth.","It causes bad breath and bleeding gums."],"explanationHi":"मुंह की सही सफाई न रखने के कारण बैक्टीरिया का निर्माण होता है, जो अंततः दांतों के झड़ने का कारण बन सकता है।","explanationEn":"Poor oral hygiene leads to bacterial buildup, which can eventually cause tooth loss.","memoryTip":"पायोरिया से ''दांत'' पीले पड़ जाते हैं।","memoryTipEn":"Pyorrhea plagues the gums.","related":["Periodontitis","Scurvy (Bleeding Gums - Vitamin C)","Dental Hygiene"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('41C_tbaMmDbcC7oLObh_U', 'General Knowledge', 'नासिक किस नदी के किनारे स्थित है?', 'Nashik is situated on the banks of which river?', 'गोदावरी', 'Godavari', 92, 0, '{"facts":["गोदावरी नदी का उद्गम नासिक जिले के त्र्यंबकेश्वर से ही होता है।","नासिक में हर 12 साल में कुंभ मेला (सिंहस्थ) लगता है।"],"factsEn":["The Godavari river originates from Trimbakeshwar in the Nashik district itself.","The Kumbh Mela (Simhastha) is held in Nashik every 12 years."],"explanationHi":"यह महाराष्ट्र का एक प्रमुख धार्मिक और ऐतिहासिक शहर है, जिसे ''भारत की वाइन राजधानी'' (Wine Capital of India) भी कहा जाता है।","explanationEn":"It is a major religious and historical city in Maharashtra, also known as the ''Wine Capital of India''.","memoryTip":"नासिक की ''गोद'' से गोदावरी निकलती है।","memoryTipEn":"Nashik nurtures the Godavari.","related":["Trimbakeshwar","Kumbh Mela","Dakshin Ganga"]}', 'published', 1776083709, 1776083709);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZKCHEsyo13w3ADIpC0NOh', 'General Knowledge', 'राष्ट्रपति को शपथ कौन दिलाता है?', 'Who administers the oath to the President?', 'सर्वोच्च न्यायालय का मुख्य न्यायधीश', 'Chief Justice of the Supreme Court', 95, 0, '{"facts":["संविधान के अनुच्छेद 60 के तहत राष्ट्रपति को शपथ दिलाई जाती है।","मुख्य न्यायाधीश की अनुपस्थिति में सर्वोच्च न्यायालय के सबसे वरिष्ठ न्यायाधीश शपथ दिलाते हैं।"],"factsEn":["The oath to the President is administered under Article 60 of the Constitution.","In the absence of the Chief Justice, the senior-most judge of the Supreme Court administers the oath."],"explanationHi":"भारत के राष्ट्रपति को पद और गोपनीयता की शपथ भारत के मुख्य न्यायाधीश द्वारा दिलाई जाती है।","explanationEn":"The President of India is administered the oath of office and secrecy by the Chief Justice of India.","memoryTip":"देश के सबसे बड़े नेता को देश का सबसे बड़ा जज शपथ दिलाता है।","memoryTipEn":"Top Judge swears in the Top Leader.","related":["Article 60","Chief Justice of India","Impeachment of President"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yRJ8eeudV8QBd2ARlRQ05', 'General Knowledge', 'जापान की मुद्रा कौनसी है?', 'What is the currency of Japan?', 'येन', 'Yen', 90, 0, '{"facts":["जापान की राजधानी टोक्यो है।","येन दुनिया में तीसरी सबसे अधिक कारोबार वाली मुद्रा है।"],"factsEn":["The capital of Japan is Tokyo.","Yen is the third most traded currency in the world."],"explanationHi":"जापानी येन जापान की आधिकारिक मुद्रा है और इसे (¥) प्रतीक द्वारा दर्शाया जाता है।","explanationEn":"The Japanese Yen is the official currency of Japan and is denoted by the symbol (¥).","memoryTip":"जापान में लोग ''येन'' (Yen) से सामान खरीदते हैं।","memoryTipEn":"Yen in Japan.","related":["Tokyo","Yuan (China)","Asian Currencies"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HsRV1JTWcYmxyOokCQON1', 'General Knowledge', 'इंडियन मिलेट्री अकादमी कहाँ स्थित है?', 'Where is the Indian Military Academy (IMA) located?', 'देहरादून', 'Dehradun', 92, 0, '{"facts":["IMA की स्थापना 1 अक्टूबर 1932 को हुई थी।","यह भारतीय सेना के अधिकारियों के लिए एक प्रमुख प्रशिक्षण संस्थान है।"],"factsEn":["IMA was established on October 1, 1932.","It is a premier training institute for Indian Army officers."],"explanationHi":"उत्तराखंड के देहरादून में स्थित यह अकादमी कैडेटों को भारतीय सेना में सैन्य अधिकारियों के रूप में तैयार करती है।","explanationEn":"Located in Dehradun, Uttarakhand, this academy trains cadets to become military officers in the Indian Army.","memoryTip":"मिलिट्री की ट्रेनिंग ''दून'' (देहरादून) की वादियों में होती है।","memoryTipEn":"Dehradun develops defenders.","related":["National Defence Academy (NDA)","Indian Army","Uttarakhand"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yoAQke9SmspT_qGRsAEMA', 'General Knowledge', 'माऊंट एवरेस्ट पर चढ़ने वाली पहली भारतीय महिला कौन है?', 'Who is the first Indian woman to climb Mount Everest?', 'बछेंद्री पाल', 'Bachendri Pal', 96, 0, '{"facts":["उन्होंने 1984 में यह उपलब्धि हासिल की थी।","उन्हें 2019 में भारत सरकार द्वारा पद्म भूषण से सम्मानित किया गया।"],"factsEn":["She achieved this feat in 1984.","She was awarded the Padma Bhushan by the Govt of India in 2019."],"explanationHi":"बछेंद्री पाल ने 1984 के भारत के एवरेस्ट अभियान के दौरान यह ऐतिहासिक मुकाम हासिल किया और भारत का नाम रोशन किया।","explanationEn":"Bachendri Pal achieved this historic milestone during India''s 1984 Everest expedition, bringing glory to the nation.","memoryTip":"एवरेस्ट पर भारत का ''बचपन'' (बछेंद्री) भी चढ़ गया।","memoryTipEn":"Bachendri braved the peak.","related":["Santosh Yadav","Mount Everest","Mountaineering"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IgVjh-PkH3lR363ADLzCp', 'General Knowledge', 'डेविस कप का सम्बन्ध किस खेल से है?', 'Davis Cup is associated with which sport?', 'टेनिस', 'Tennis', 91, 0, '{"facts":["यह पुरुषों की टेनिस टीमों के बीच एक प्रमुख अंतरराष्ट्रीय प्रतियोगिता है।","इसे टेनिस का ''विश्व कप'' भी कहा जाता है।"],"factsEn":["It is a premier international team event in men''s tennis.","It is often described as the ''World Cup of Tennis''."],"explanationHi":"यह वार्षिक प्रतियोगिता विभिन्न देशों की राष्ट्रीय टीमों के बीच नॉक-आउट प्रारूप में खेली जाती है।","explanationEn":"This annual competition is played in a knock-out format between national teams of various countries.","memoryTip":"टेनिस में जीतने के लिए ''डेविश'' (Davis) ताकत चाहिए।","memoryTipEn":"Davis dominates Tennis.","related":["Fed Cup (Billie Jean King Cup)","Grand Slams","Hopman Cup"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AhPE2GD8QIJKpDAdU6zoo', 'General Knowledge', 'माऊंट एवरेस्ट पर दो बार चढ़ने वाली पहली भारतीय महिला कौन है?', 'Who is the first Indian woman to climb Mount Everest twice?', 'संतोष यादव', 'Santosh Yadav', 94, 0, '{"facts":["उन्होंने 1992 और 1993 में लगातार दो बार एवरेस्ट फतह किया।","वे कंगशुंग फेस (Kangshung Face) से एवरेस्ट पर चढ़ने वाली पहली महिला भी हैं।"],"factsEn":["She summited Everest twice consecutively in 1992 and 1993.","She is also the first woman to successfully climb Everest from the Kangshung Face."],"explanationHi":"लगातार दो वर्षों में दुनिया की सबसे ऊंची चोटी पर चढ़ने का उनका रिकॉर्ड पर्वतारोहण के इतिहास में मील का पत्थर है।","explanationEn":"Her record of climbing the world''s highest peak in consecutive years is a milestone in mountaineering history.","memoryTip":"एक बार में ''संतोष'' नहीं हुआ, इसलिए दो बार चढ़ीं।","memoryTipEn":"Santosh was not satisfied with just one climb.","related":["Bachendri Pal","Mount Everest","Kangshung Face"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HOQC5HgIb2-dvmYjcLbVl', 'General Knowledge', 'सर्वोच्च न्यायालय का मुख्य न्यायधीश कब तक अपने पद पर रहता है?', 'Until what age does the Chief Justice of the Supreme Court hold office?', '65 वर्ष की आयु तक', 'Until the age of 65 years', 95, 0, '{"facts":["संविधान में सर्वोच्च न्यायालय के न्यायाधीशों के लिए कोई निश्चित कार्यकाल (fixed tenure) नहीं है, केवल सेवानिवृत्ति की आयु 65 वर्ष है।","उच्च न्यायालय (High Court) के न्यायाधीशों की सेवानिवृत्ति की आयु 62 वर्ष होती है।"],"factsEn":["The Constitution does not prescribe a fixed tenure for Supreme Court judges, only a retirement age of 65.","The retirement age for High Court judges is 62 years."],"explanationHi":"सर्वोच्च न्यायालय के मुख्य न्यायाधीश और अन्य न्यायाधीश 65 वर्ष की आयु पूरी होने तक अपने पद पर बने रह सकते हैं।","explanationEn":"The Chief Justice and other judges of the Supreme Court hold office until they attain the age of 65 years.","memoryTip":"सुप्रीम कोर्ट में 65, हाई कोर्ट में 62।","memoryTipEn":"Supreme is 65, High is 62.","related":["Chief Justice of India","High Court Judges","Article 124"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('X678WISfee_m_4rld1RTg', 'General Knowledge', 'संसद का उच्च सदन कौनसा है?', 'Which is the upper house of the Parliament?', 'राज्यसभा', 'Rajya Sabha', 93, 0, '{"facts":["राज्यसभा एक स्थायी सदन है जिसे कभी भंग (dissolve) नहीं किया जा सकता।","इसे ''राज्यों की परिषद'' (Council of States) भी कहा जाता है।"],"factsEn":["Rajya Sabha is a permanent house and is not subject to dissolution.","It is also known as the ''Council of States''."],"explanationHi":"संसद के दो सदन होते हैं: लोकसभा (निम्न सदन) और राज्यसभा (उच्च सदन)। राज्यसभा राज्यों का प्रतिनिधित्व करती है।","explanationEn":"Parliament has two houses: Lok Sabha (lower house) and Rajya Sabha (upper house). Rajya Sabha represents the states.","memoryTip":"''राज्य'' का सदन ''उच्च'' होता है।","memoryTipEn":"Rajya Sabha is the Upper House.","related":["Lok Sabha","Parliament of India","Vice President of India"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bTjGBYnrfESixB3OsrSFn', 'General Knowledge', 'पंचतंत्र का लेखक कौन है?', 'Who is the author of Panchatantra?', 'विष्णु शर्मा', 'Vishnu Sharma', 92, 0, '{"facts":["यह संस्कृत में लिखी गई प्राचीन भारतीय पशु दंतकथाओं का एक संग्रह है।","इसे मूल रूप से तीन राजकुमारों को राजनीति और व्यवहारिक ज्ञान सिखाने के लिए लिखा गया था।"],"factsEn":["It is an ancient Indian collection of interrelated animal fables in Sanskrit.","It was originally written to teach political and practical wisdom to three princes."],"explanationHi":"पंचतंत्र दुनिया में सबसे अधिक अनुवादित गैर-धार्मिक पुस्तकों में से एक है, जिसमें जानवरों के माध्यम से नैतिक शिक्षा दी गई है।","explanationEn":"Panchatantra is one of the most widely translated non-religious books in the world, imparting moral lessons through animals.","memoryTip":"पांच (पंच) तंत्र ''विष्णु'' भगवान ने बनाए।","memoryTipEn":"Vishnu shared the five (Pancha) principles.","related":["Hitopadesha","Ancient Indian Literature","Fables"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8KUnEZa2ALY8Dk8tE42cQ', 'General Knowledge', 'सन 1954 में हुआ भारत-चीन समझौता किस नाम से जाना जाता है?', 'By what name is the India-China agreement of 1954 known?', 'पंचशील समझौता', 'Panchsheel Agreement', 95, 0, '{"facts":["इस समझौते में शांतिपूर्ण सह-अस्तित्व के पांच सिद्धांत (Five Principles of Peaceful Coexistence) शामिल थे।","यह समझौता भारत के प्रधानमंत्री जवाहरलाल नेहरू और चीन के प्रधानमंत्री चाउ एन-लाई के बीच हुआ था।"],"factsEn":["The agreement included the Five Principles of Peaceful Coexistence.","It was signed between Indian PM Jawaharlal Nehru and Chinese Premier Zhou Enlai."],"explanationHi":"इस समझौते का मुख्य उद्देश्य दोनों देशों के बीच शांति और एक-दूसरे की संप्रभुता का सम्मान सुनिश्चित करना था।","explanationEn":"The main objective was to ensure peace and respect for each other''s sovereignty between the two nations.","memoryTip":"चीन के साथ 5 (पंच) शील (शांति) के वादे किए गए थे।","memoryTipEn":"Panch (Five) Sheel (Virtues) for peace.","related":["Sino-Indian War 1962","Jawaharlal Nehru","Zhou Enlai"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CjlydhwMDr-dYXKF_PWhg', 'General Knowledge', 'सन 2010 में फुटबॉल विश्वकप किस देश ने जीता था?', 'Which country won the Football World Cup in 2010?', 'स्पेन', 'Spain', 85, 0, '{"facts":["2010 का फीफा विश्व कप दक्षिण अफ्रीका में आयोजित किया गया था।","स्पेन ने फाइनल में नीदरलैंड को 1-0 से हराकर अपना पहला विश्व कप जीता था।"],"factsEn":["The 2010 FIFA World Cup was hosted by South Africa.","Spain won their first World Cup by defeating the Netherlands 1-0 in the final."],"explanationHi":"यह अफ्रीकी महाद्वीप पर आयोजित होने वाला पहला फीफा विश्व कप था और इसके एंथम ''वाका वाका'' ने भी बहुत लोकप्रियता हासिल की थी।","explanationEn":"It was the first FIFA World Cup hosted on the African continent, and its anthem ''Waka Waka'' gained massive popularity.","memoryTip":"2010 में ''पेन'' (स्पेन) से फुटबॉल का इतिहास लिखा गया।","memoryTipEn":"Spain reigned in 2010.","related":["FIFA World Cup","South Africa 2010","Andres Iniesta"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xgLEwcTwwu2xInTOz1dYu', 'General Knowledge', 'राष्ट्रीय रक्षा अकादमी (NDA) कहाँ स्थित है?', 'Where is the National Defence Academy (NDA) located?', 'पूना के पास खड़कवासला में', 'Khadakwasla near Pune', 92, 0, '{"facts":["NDA भारतीय सशस्त्र बलों की संयुक्त सेवा अकादमी है।","यहाँ थल सेना, नौसेना और वायु सेना के कैडेट एक साथ प्रशिक्षण प्राप्त करते हैं।"],"factsEn":["NDA is the joint services academy of the Indian Armed Forces.","Cadets of the Army, Navy, and Air Force train together here."],"explanationHi":"खड़कवासला (महाराष्ट्र) में स्थित यह दुनिया की पहली त्रिकोणीय-सेवा (Tri-service) अकादमी है।","explanationEn":"Located in Khadakwasla (Maharashtra), it is the first tri-service academy in the world.","memoryTip":"डिफेन्स (रक्षा) के लोग ''खड़क'' (मजबूत) होते हैं (खड़कवासला)।","memoryTipEn":"NDA cadets are tough as rock (Khadak).","related":["Indian Military Academy (IMA)","Indian Naval Academy","Pune"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5AjgzySfET_XY6V5jLCx4', 'General Knowledge', '''डिस्कवरी ऑफ़ इंडिया'' पुस्तक किसने लिखी?', 'Who wrote the book ''Discovery of India''?', 'जवाहरलाल नेहरु', 'Jawaharlal Nehru', 94, 0, '{"facts":["यह पुस्तक नेहरू जी ने 1942-1946 के दौरान अहमदनगर किले में अपने कारावास के दौरान लिखी थी।","यह पुस्तक भारत के इतिहास, संस्कृति और दर्शन का एक व्यापक अवलोकन है।"],"factsEn":["Nehru wrote this book during his imprisonment at Ahmednagar Fort between 1942-1946.","The book is a broad overview of Indian history, culture, and philosophy."],"explanationHi":"नेहरू जी ने इस पुस्तक के माध्यम से सिंधु घाटी सभ्यता से लेकर ब्रिटिश राज तक के भारत की समृद्ध सांस्कृतिक विरासत को प्रस्तुत किया।","explanationEn":"Through this book, Nehru presented India''s rich cultural heritage from the Indus Valley Civilization to the British Raj.","memoryTip":"नेहरू जी ने जेल में बैठे-बैठे भारत की ''डिस्कवरी'' (खोज) कर डाली।","memoryTipEn":"Nehru Discovered India in prison.","related":["Glimpses of World History","Ahmednagar Fort","Indian History"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9tWWp66tRcd-_DAUnNoSc', 'General Science', 'एक स्वस्थ मनुष्य का हृदय एक मिनट में कितनी बार धड़कता है?', 'How many times does the heart of a healthy human beat in one minute?', '72 बार', '72 times', 95, 0, '{"facts":["सामान्य विश्राम हृदय गति (Resting heart rate) आमतौर पर 60 से 100 बीट प्रति मिनट के बीच होती है।","हृदय की धड़कन को स्टेथोस्कोप (Stethoscope) द्वारा सुना जाता है।"],"factsEn":["A normal resting heart rate usually ranges between 60 and 100 beats per minute.","The heartbeat is listened to using a stethoscope."],"explanationHi":"औसतन, एक वयस्क का हृदय आराम की स्थिति में प्रति मिनट 72 बार धड़कता है और शरीर में रक्त पंप करता है।","explanationEn":"On average, an adult''s heart beats 72 times per minute while resting, pumping blood throughout the body.","memoryTip":"1 मिनट = 60 सेकंड, और धड़कन 72 बार।","memoryTipEn":"72 beats to keep the rhythm sweet.","related":["Pulse Rate","Cardiovascular System","Stethoscope"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xH2reGscyjFwKNADsrcRo', 'General Knowledge', 'भारत में पहली बार जनगणना (Census) कब हुई?', 'When was the first census conducted in India?', '1872', '1872', 96, 0, '{"facts":["यह जनगणना ब्रिटिश वायसराय ''लॉर्ड मेयो'' (Lord Mayo) के कार्यकाल में हुई थी।","पहली ''नियमित'' और ''समकालिक'' (Synchronous) जनगणना 1881 में लॉर्ड रिपन के समय हुई थी।"],"factsEn":["This census was conducted during the tenure of British Viceroy ''Lord Mayo''.","The first ''regular'' and ''synchronous'' census took place in 1881 under Lord Ripon."],"explanationHi":"1872 में जनगणना के माध्यम से पहली बार भारतीय उपमहाद्वीप की जनसांख्यिकी का आकलन करने का प्रयास किया गया था।","explanationEn":"The 1872 census was the first attempt to assess the demographics of the Indian subcontinent.","memoryTip":"18-72 में लोगों को गिनना (जनगणना) ''मेयो'' (मुझे) अच्छा लगा।","memoryTipEn":"Counted first in ''72 by Mayo.","related":["Lord Mayo","1881 Census","Demographics of India"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('X6bkqzTTBSllNSepv9gak', 'General Knowledge', '''डबल फाल्ट'' (Double Fault) शब्द किस खेल में प्रयुक्त होता है?', 'The term ''Double Fault'' is used in which sport?', 'टेनिस', 'Tennis', 90, 0, '{"facts":["जब कोई खिलाड़ी लगातार दो बार वैध सर्व (Service) करने में विफल रहता है, तो उसे ''डबल फाल्ट'' कहा जाता है।","डबल फाल्ट होने पर विरोधी खिलाड़ी को एक अंक (Point) मिल जाता है।"],"factsEn":["When a player fails to make a valid serve twice consecutively, it''s a ''Double Fault''.","A double fault results in a point for the opponent."],"explanationHi":"टेनिस में सर्व करते समय गेंद को सर्विस बॉक्स के अंदर गिरना चाहिए, दो बार चूकने पर फाल्ट माना जाता है।","explanationEn":"In tennis, the serve must land inside the service box; missing it twice is a fault.","memoryTip":"टेनिस में दो बार (डबल) गलती (फाल्ट) करोगे तो पॉइंट हारोगे।","memoryTipEn":"Double fault gives away the tennis point.","related":["Ace (Tennis)","Love (Tennis)","Deuce"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rBpk5Yqt2W8fYI5roiV8F', 'General Knowledge', 'भारतीय थल सेना के पहले भारतीय सेनाध्यक्ष कौन थे?', 'Who was the first Indian Commander-in-Chief of the Indian Army?', 'जनरल के. एम्. करियप्पा', 'General K. M. Cariappa', 95, 0, '{"facts":["उन्होंने 15 जनवरी 1949 को ब्रिटिश कमांडर सर रॉय बुचर से पदभार ग्रहण किया था।","इसी उपलक्ष्य में हर साल 15 जनवरी को ''सेना दिवस'' (Army Day) मनाया जाता है।"],"factsEn":["He took over from British Commander Sir Roy Bucher on Jan 15, 1949.","To commemorate this, ''Army Day'' is celebrated every year on Jan 15."],"explanationHi":"वे फील्ड मार्शल के फाइव-स्टार रैंक तक पहुंचने वाले केवल दो भारतीय सेना अधिकारियों में से एक हैं (दूसरे सैम मानेकशॉ हैं)।","explanationEn":"He is one of only two Indian Army officers to hold the five-star rank of Field Marshal (the other being Sam Manekshaw).","memoryTip":"सेना की कमान सबसे पहले ''करियप्पा'' के हाथों ''कर'' (हाथ) में आई।","memoryTipEn":"Cariappa commanded the troops first.","related":["Army Day (Jan 15)","Sam Manekshaw","Indian Army"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('t0U0ztCHzf9nICB3HdtsT', 'General Knowledge', '''लाई हरोबा'' किस राज्य का लोकनृत्य है?', '''Lai Haraoba'' is a folk dance of which state?', 'मणिपुर', 'Manipur', 89, 0, '{"facts":["यह एक प्राचीन उत्सव और नृत्य है जिसे मेइती समुदाय (Meitei community) द्वारा मनाया जाता है।","''लाई हरोबा'' का अर्थ ''देवताओं का आनंद'' (Merrymaking of the Gods) है।"],"factsEn":["It is an ancient festival and dance celebrated by the Meitei community.","''Lai Haraoba'' translates to ''Merrymaking of the Gods''."],"explanationHi":"इस उत्सव में ब्रह्मांड के निर्माण की कहानी को नृत्य और अनुष्ठानों के माध्यम से दर्शाया जाता है।","explanationEn":"The festival depicts the story of the creation of the universe through dance and rituals.","memoryTip":"मणि (रत्न) देखकर देवी-देवता ''हरोबा'' (आनंदित) हो गए।","memoryTipEn":"Manipur makes the gods merry (Haraoba).","related":["Meitei Community","Manipuri Classical Dance","Northeast Indian Festivals"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5YcotcdE1HsulXlVcynMI', 'General Knowledge', 'भारत के किस राज्य में रबर का सबसे अधिक उत्पादन होता है?', 'Which state is the largest producer of rubber in India?', 'केरल', 'Kerala', 94, 0, '{"facts":["केरल भारत के कुल प्राकृतिक रबर उत्पादन का लगभग 70-80% उत्पादित करता है।","रबर के पेड़ को गर्म और आर्द्र जलवायु की आवश्यकता होती है।"],"factsEn":["Kerala accounts for about 70-80% of India''s total natural rubber production.","The rubber tree requires a hot and humid climate."],"explanationHi":"केरल की उष्णकटिबंधीय जलवायु और भारी वर्षा प्राकृतिक रबर की खेती के लिए सबसे उपयुक्त है।","explanationEn":"Kerala''s tropical climate and heavy rainfall are highly suitable for the cultivation of natural rubber.","memoryTip":"केरल की ''करेले'' जैसी जलवायु रबर के लिए अच्छी है।","memoryTipEn":"Kerala''s climate creates the best rubber.","related":["Natural Rubber","Cash Crops","Tripura (2nd largest producer)"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wmmucSy1sFF3ctpk1Eb7H', 'General Knowledge', 'कोलकाता किस नदी के किनारे है?', 'Kolkata is situated on the banks of which river?', 'हुगली', 'Hooghly', 91, 0, '{"facts":["हुगली नदी गंगा नदी की एक वितरिका (Distributary) है।","प्रसिद्ध हावड़ा ब्रिज (Howrah Bridge) इसी नदी पर बना है।"],"factsEn":["The Hooghly River is a distributary of the Ganges river.","The famous Howrah Bridge is built over this river."],"explanationHi":"कोलकाता भारत के सबसे बड़े बंदरगाह शहरों में से एक है, और हुगली नदी इसे बंगाल की खाड़ी से जोड़ती है।","explanationEn":"Kolkata is one of India''s largest port cities, and the Hooghly river connects it to the Bay of Bengal.","memoryTip":"कोलकाता की ''गली-गली'' (हुगली) में रसगुल्ला मिलता है।","memoryTipEn":"Kolkata hugs the Hooghly.","related":["Howrah Bridge","Ganges Distributary","West Bengal"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('sxplynziaYNylcc_UafRz', 'General Science', '''पौधों में जीवन होता है'' यह किस भारतीय वैज्ञानिक ने बताया था?', 'Which Indian scientist proved that ''plants have life''?', 'जगदीश चन्द्र बसु', 'Jagadish Chandra Bose', 96, 0, '{"facts":["उन्होंने क्रेस्कोग्राफ (Crescograph) नामक एक उपकरण का आविष्कार किया था।","इस उपकरण का उपयोग पौधों की वृद्धि और उत्तेजनाओं के प्रति उनकी प्रतिक्रिया को मापने के लिए किया गया था।"],"factsEn":["He invented an instrument called the Crescograph.","This device was used to measure plant growth and their response to stimuli."],"explanationHi":"जे.सी. बोस ने वैज्ञानिक प्रयोगों के माध्यम से दुनिया को दिखाया कि पौधे भी गर्मी, सर्दी, प्रकाश और दर्द को महसूस कर सकते हैं।","explanationEn":"J.C. Bose scientifically demonstrated to the world that plants can also feel heat, cold, light, and pain.","memoryTip":"पौधों के ''जग'' (संसार) के ''ईश'' (भगवान) बने जगदीश चन्द्र।","memoryTipEn":"Bose brought biology to the plants.","related":["Crescograph","Radio Microwaves","Biophysics"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('x5ODMeL6ddBWR_czRYbXx', 'General Knowledge', 'महात्मा गाँधी द्वारा साबरमती आश्रम कहाँ स्थापित किया गया?', 'Where was the Sabarmati Ashram established by Mahatma Gandhi?', 'अहमदाबाद', 'Ahmedabad', 93, 0, '{"facts":["यह गुजरात में साबरमती नदी के तट पर स्थित है।","इसे मूल रूप से 1915 में कोचरब (Kochrab) में स्थापित किया गया था और 1917 में साबरमती ले जाया गया।"],"factsEn":["It is located on the banks of the Sabarmati river in Gujarat.","It was originally established in Kochrab in 1915 and moved to Sabarmati in 1917."],"explanationHi":"यह आश्रम भारतीय स्वतंत्रता संग्राम के कई महत्वपूर्ण आंदोलनों, विशेषकर 1930 की दांडी यात्रा (नमक सत्याग्रह), का केंद्र था।","explanationEn":"The ashram was the epicentre of many crucial movements of the Indian freedom struggle, notably the Dandi March (Salt Satyagraha) of 1930.","memoryTip":"अहमदाबाद में बापू ''साबरमती'' के संत बने।","memoryTipEn":"Ahmedabad hosts Gandhi''s ashram.","related":["Dandi March","Salt Satyagraha","Gujarat"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('J0_wj7JGJg5x7Mysh9P0R', 'General Science', 'मनुष्य के शरीर में कितने गुणसूत्र (Chromosomes) होते हैं?', 'How many chromosomes are there in the human body?', '23 जोड़े या 46', '23 pairs or 46', 96, 0, '{"facts":["इनमें से 22 जोड़े ''ऑटोसोम'' (Autosomes) होते हैं और 1 जोड़ा ''सेक्स क्रोमोसोम'' (Sex Chromosome) होता है।","महिलाओं में XX और पुरुषों में XY सेक्स क्रोमोसोम होते हैं।"],"factsEn":["Out of these, 22 pairs are ''Autosomes'' and 1 pair is the ''Sex Chromosome''.","Females have XX and males have XY sex chromosomes."],"explanationHi":"गुणसूत्र कोशिका के केंद्रक (Nucleus) में पाए जाते हैं और इनमें आनुवंशिक जानकारी (DNA) होती है जो माता-पिता से बच्चों में जाती है।","explanationEn":"Chromosomes are found in the nucleus of a cell and contain genetic information (DNA) passed from parents to offspring.","memoryTip":"23 माता से, 23 पिता से = 46 कुल।","memoryTipEn":"23 pairs make you who you are.","related":["DNA","Genetics","Sex Chromosomes"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('W1UmsXgcM8QUSzNuv0082', 'General Science', 'चंद्रग्रहण कब लगता है?', 'When does a lunar eclipse occur?', 'पूर्णिमा (Full Moon)', 'Full Moon', 95, 0, '{"facts":["चंद्रग्रहण तब होता है जब पृथ्वी, सूर्य और चंद्रमा के बीच आ जाती है।","सूर्यग्रहण अमावस्या (New Moon) के दिन होता है।"],"factsEn":["A lunar eclipse occurs when the Earth comes exactly between the Sun and the Moon.","A solar eclipse occurs on a New Moon day."],"explanationHi":"इस स्थिति में पृथ्वी की छाया चंद्रमा पर पड़ती है, जिससे चंद्रमा का प्रकाश छिप जाता है। यह हमेशा पूर्णिमा की रात को ही संभव है।","explanationEn":"In this alignment, Earth''s shadow falls on the Moon, obscuring its light. This is only possible on a Full Moon night.","memoryTip":"जब चाँद पूरा (पूर्णिमा) होता है, तभी उस पर ''ग्रहण'' (छाया) लग सकता है।","memoryTipEn":"Full moon gets fully eclipsed.","related":["Solar Eclipse","New Moon","Earth''s Shadow"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9QsoyWXqwwLh7ShPzlgtb', 'General Knowledge', 'भारत छोड़ो आन्दोलन (Quit India Movement) कब शुरु हुआ?', 'When did the Quit India Movement start?', '8 अगस्त 1942', '8 August 1942', 97, 0, '{"facts":["इसे ''अगस्त क्रांति'' (August Kranti) भी कहा जाता है।","इस आंदोलन की शुरुआत बॉम्बे के गोवालिया टैंक मैदान से हुई थी।"],"factsEn":["It is also known as the ''August Kranti''.","The movement was launched from the Gowalia Tank Maidan in Bombay."],"explanationHi":"इसी आंदोलन के दौरान महात्मा गांधी ने देशवासियों को ''करो या मरो'' (Do or Die) का ऐतिहासिक नारा दिया था।","explanationEn":"During this movement, Mahatma Gandhi gave the historic ''Do or Die'' call to the nation.","memoryTip":"42 में अंग्रेजों से कहा: ''भारत छोड़ो''।","memoryTipEn":"Quit India in ''42.","related":["Do or Die","August Kranti Maidan","Mahatma Gandhi"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qqGB4iFGFKuvkLTtgG7vW', 'General Science', 'मनुष्य के शरीर का सामान्य रक्तदाब (Blood Pressure) कितना होता है?', 'What is the normal blood pressure of a human body?', '80 से 120 मि.मी. (120/80 mmHg)', '120/80 mmHg', 96, 0, '{"facts":["120 सिस्टोलिक (Systolic) दबाव है (जब हृदय धड़कता है)।","80 डायस्टोलिक (Diastolic) दबाव है (धड़कनों के बीच आराम का समय)।"],"factsEn":["120 is the Systolic pressure (when the heart beats).","80 is the Diastolic pressure (resting time between beats)."],"explanationHi":"इसे स्फिग्मोमैनोमीटर (Sphygmomanometer) नामक यंत्र से मापा जाता है। इससे अधिक दबाव को हाई ब्लड प्रेशर (Hypertension) कहते हैं।","explanationEn":"It is measured using a Sphygmomanometer. Higher pressure is termed High Blood Pressure (Hypertension).","memoryTip":"120 ऊपर, 80 नीचे = स्वस्थ जीवन।","memoryTipEn":"120 over 80 keeps you healthy.","related":["Sphygmomanometer","Hypertension","Systolic/Diastolic"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('eKu7cpJ3VulHW3Lyk69bI', 'General Knowledge', 'उत्तरी गोलार्द्ध (Northern Hemisphere) में सबसे छोटा दिन कब होता है?', 'When is the shortest day in the Northern Hemisphere?', '22 दिसंबर', '22 December', 94, 0, '{"facts":["इसे ''शीत अयनांत'' (Winter Solstice) कहा जाता है।","इस दिन सूर्य की किरणें मकर रेखा (Tropic of Capricorn) पर सीधी पड़ती हैं।"],"factsEn":["It is called the ''Winter Solstice''.","On this day, the sun''s rays fall directly on the Tropic of Capricorn."],"explanationHi":"चूंकि सूर्य उत्तरी गोलार्ध से सबसे दूर होता है, इसलिए यहाँ दिन सबसे छोटा और रात सबसे लंबी होती है। (दक्षिणी गोलार्ध में यह सबसे बड़ा दिन होता है)।","explanationEn":"Since the sun is farthest from the Northern Hemisphere, the day is the shortest and the night is the longest here. (It''s the longest day in the Southern Hemisphere).","memoryTip":"दिसंबर की ठंड में दिन जल्दी ''छोटा'' हो जाता है।","memoryTipEn":"December 22 is dark and brief.","related":["Winter Solstice","Summer Solstice (June 21)","Tropic of Capricorn"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7iFRzyTfQxaIv1ZewGxJR', 'General Knowledge', '''रामचरितमानस'' किसने लिखी?', 'Who wrote ''Ramcharitmanas''?', 'तुलसीदास', 'Tulsidas', 95, 0, '{"facts":["यह 16वीं शताब्दी में अवधी भाषा (Awadhi dialect) में लिखी गई थी।","मूल रामायण महर्षि वाल्मीकि द्वारा संस्कृत में लिखी गई थी।"],"factsEn":["It was written in the 16th century in the Awadhi dialect.","The original Ramayana was written in Sanskrit by Maharishi Valmiki."],"explanationHi":"गोस्वामी तुलसीदास ने भगवान राम की कथा को आम जनता की भाषा (अवधी) में प्रस्तुत किया, जिससे यह उत्तरी भारत में बहुत लोकप्रिय हुई।","explanationEn":"Goswami Tulsidas presented Lord Ram''s story in the language of the common people (Awadhi), making it highly popular in North India.","memoryTip":"तुलसी के ''मानस'' (मन) में राम बसे थे।","memoryTipEn":"Tulsidas translated Ram''s tale.","related":["Awadhi","Valmiki Ramayana","Bhakti Movement"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('whr7lbGJc9PJkup6SIhso', 'General Knowledge', 'प्रथम एशियाई खेल कब और कहाँ आयोजित किए गए?', 'When and where were the first Asian Games held?', 'मई 1951 में नयी दिल्ली में', 'May 1951 in New Delhi', 91, 0, '{"facts":["इन खेलों का उद्घाटन भारत के पहले राष्ट्रपति डॉ. राजेंद्र प्रसाद ने किया था।","भारत ने 1982 में भी एशियाई खेलों की मेजबानी की थी।"],"factsEn":["The games were inaugurated by India''s first President, Dr. Rajendra Prasad.","India hosted the Asian Games again in 1982."],"explanationHi":"यह एशिया के नव-स्वतंत्र देशों के बीच खेल और मैत्री को बढ़ावा देने की एक बड़ी पहल थी, जिसका विचार गुरु दत्त सोंधी (G.D. Sondhi) ने दिया था।","explanationEn":"It was a major initiative to promote sports and friendship among the newly independent Asian nations, an idea proposed by G.D. Sondhi.","memoryTip":"एशिया का पहला ''खेल'' नई दिल्ली (51) में शुरू हुआ।","memoryTipEn":"New Delhi debuted the Asian Games in ''51.","related":["Asian Games","1982 Asian Games","G.D. Sondhi"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('p-OF0P_ClfdKsPktEDlql', 'General Science', 'वायुमंडलीय दाब (Atmospheric Pressure) किस यंत्र से मापा जाता है?', 'Which instrument is used to measure Atmospheric Pressure?', 'बैरोमीटर (Barometer)', 'Barometer', 95, 0, '{"facts":["बैरोमीटर का आविष्कार इवेंजेलिस्ता टोरिसेली (Evangelista Torricelli) ने किया था।","पारे (Mercury) का उपयोग अक्सर पारंपरिक बैरोमीटर में किया जाता है।"],"factsEn":["The barometer was invented by Evangelista Torricelli.","Mercury is often used in traditional barometers."],"explanationHi":"बैरोमीटर की रीडिंग में अचानक गिरावट आंधी या तूफान का संकेत देती है, जबकि धीरे-धीरे वृद्धि साफ मौसम का संकेत देती है।","explanationEn":"A sudden drop in the barometer reading indicates a storm, while a gradual rise indicates clear weather.","memoryTip":"हवा के ''भार'' (दाब) को ''बैरो'' मीटर मापता है।","memoryTipEn":"Barometer bears the pressure.","related":["Evangelista Torricelli","Atmospheric Pressure","Altimeter"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Mv1cJblIrhqDTXvgNrru3', 'General Knowledge', 'हरियाणा का पहला महिला विश्वविद्यालय कौनसा है और कहाँ है?', 'Which is the first women''s university in Haryana and where is it located?', 'भगत फूल सिंह महिला विश्वविद्यालय, खानपुर कलां (सोनीपत)', 'Bhagat Phool Singh Mahila Vishwavidyalaya, Khanpur Kalan (Sonipat)', 82, 0, '{"facts":["इसकी स्थापना 2006 में हुई थी।","यह उत्तर भारत का पहला राज्य संचालित महिला विश्वविद्यालय है।"],"factsEn":["It was established in 2006.","It is North India''s first state-run women''s university."],"explanationHi":"यह संस्थान भगत फूल सिंह द्वारा शुरू किए गए एक गुरुकुल से विकसित हुआ है, जिसका उद्देश्य ग्रामीण महिलाओं को सशक्त बनाना है।","explanationEn":"The institution evolved from a gurukul started by Bhagat Phool Singh, aimed at empowering rural women.","memoryTip":"हरियाणा की महिलाओं के लिए ''फूल'' (भगत फूल सिंह) जैसा विश्वविद्यालय।","memoryTipEn":"Phool Singh university for women in Sonipat.","related":["Sonipat","Women Empowerment","Haryana Universities"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IefxCCaX1T7tr46T_aibc', 'General Knowledge', 'टेस्ट मैचों की एक पारी में सभी दसों विकेट लेने वाला भारतीय कौन है?', 'Who is the Indian to take all ten wickets in an innings of a Test match?', 'अनिल कुंबले', 'Anil Kumble', 92, 0, '{"facts":["उन्होंने यह कारनामा 1999 में दिल्ली के फिरोजशाह कोटला मैदान में पाकिस्तान के खिलाफ किया था।","जिम लेकर (इंग्लैंड) और एजाज पटेल (न्यूजीलैंड) भी यह उपलब्धि हासिल कर चुके हैं।"],"factsEn":["He achieved this feat against Pakistan at the Feroz Shah Kotla ground in Delhi in 1999.","Jim Laker (England) and Ajaz Patel (New Zealand) have also achieved this feat."],"explanationHi":"कुंबले ने एक ही पारी में सभी 10 विकेट चटकाकर क्रिकेट इतिहास में अपना नाम सुनहरे अक्षरों में दर्ज करा लिया।","explanationEn":"Kumble etched his name in cricket history by taking all 10 wickets in a single innings.","memoryTip":"कुंबले की ''जंबो'' स्पिन ने 10 विकेट झटक लिए।","memoryTipEn":"Kumble swept all 10 wickets.","related":["Jim Laker","Ajaz Patel","Feroz Shah Kotla (Arun Jaitley Stadium)"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_ZOdvvAGSvngsnXwq6xfF', 'General Knowledge', 'सन 2018 में फुटबॉल विश्वकप कहाँ होगा (हुआ था)?', 'Where was the Football World Cup held in 2018?', 'रूस (Russia)', 'Russia', 86, 0, '{"facts":["2018 का फीफा विश्व कप फ्रांस ने क्रोएशिया को हराकर जीता था।","2022 का विश्व कप कतर (Qatar) में आयोजित किया गया था।"],"factsEn":["The 2018 FIFA World Cup was won by France, defeating Croatia.","The 2022 World Cup was hosted in Qatar."],"explanationHi":"यह पूर्वी यूरोप में आयोजित होने वाला पहला विश्व कप था और रूस ने इसकी शानदार मेजबानी की।","explanationEn":"It was the first World Cup held in Eastern Europe, and Russia hosted it grandly.","memoryTip":"2018 में फुटबॉल का ''रश'' (रूस) था।","memoryTipEn":"Russia rolled the ball in ''18.","related":["FIFA World Cup","France (2018 Winner)","Qatar 2022"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8Lpy5hjL2PEqK7WYAXbMN', 'General Knowledge', 'संसार में सर्वाधिक जनसंख्या वाला देश कौनसा है?', 'Which is the most populous country in the world?', 'चीन (ऐतिहासिक रूप से / पीडीएफ अनुसार)', 'China (Historically / As per PDF)', 90, 0, '{"facts":["नोट: संयुक्त राष्ट्र की 2023 की रिपोर्ट के अनुसार, अब भारत दुनिया का सबसे अधिक आबादी वाला देश बन गया है।","चीन ने लंबे समय तक ''वन चाइल्ड पॉलिसी'' (One-child policy) लागू की थी, जिससे उसकी जनसंख्या वृद्धि दर कम हो गई।"],"factsEn":["Note: According to UN reports in 2023, India has now surpassed China as the most populous country.","China implemented a ''One-child policy'' for a long time, slowing its population growth."],"explanationHi":"पीडीएफ के समय चीन सबसे अधिक आबादी वाला था, लेकिन हालिया जनसांख्यिकीय बदलावों के कारण भारत आगे निकल गया है।","explanationEn":"At the time of the PDF, China was the most populous, but due to recent demographic shifts, India has overtaken it.","memoryTip":"चीन की जनसंख्या का रिकॉर्ड अब ''भारत'' ने तोड़ दिया है।","memoryTipEn":"China led, India now leads.","related":["India Population","One-child Policy","Demographics"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('P8pc1yNNVPI9vg6UO7Mk-', 'General Knowledge', 'राष्ट्रपति लोकसभा में कितने सदस्य मनोनीत कर सकता है?', 'How many members can the President nominate to the Lok Sabha?', '2 (एंग्लो-इंडियन)', '2 (Anglo-Indians)', 88, 0, '{"facts":["महत्वपूर्ण अद्यतन: 104वें संविधान संशोधन अधिनियम (2019) द्वारा लोकसभा में एंग्लो-इंडियन के मनोनयन को समाप्त कर दिया गया है।","पहले, यदि समुदाय का पर्याप्त प्रतिनिधित्व नहीं होता था, तो राष्ट्रपति 2 सदस्यों को मनोनीत करते थे।"],"factsEn":["Important Update: The nomination of Anglo-Indians to the Lok Sabha was abolished by the 104th Constitutional Amendment Act (2019).","Previously, if the community was inadequately represented, the President nominated 2 members."],"explanationHi":"यद्यपि पुराने पाठ्यक्रम (पीडीएफ) के अनुसार उत्तर ''2'' है, वर्तमान प्रतियोगी परीक्षाओं के लिए यह ध्यान रखना आवश्यक है कि यह प्रावधान अब लागू नहीं है।","explanationEn":"While the answer according to older syllabi (PDF) is ''2'', for current exams it is essential to note that this provision is no longer active.","memoryTip":"लोकसभा में ''2'' का नियम अब 104वें संशोधन से ''जीरो'' हो गया।","memoryTipEn":"Anglo-Indian seats are abolished.","related":["104th Amendment Act","Anglo-Indian Community","Rajya Sabha Nominations (12)"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Qxn4lw9omC_oF7xIMqlvx', 'General Science', 'सर्वग्राही (Universal Recipient) रक्त समूह कौन सा है?', 'Which blood group is the Universal Recipient?', 'AB', 'AB (specifically AB Positive)', 96, 0, '{"facts":["AB+ रक्त समूह वाला व्यक्ति किसी भी रक्त समूह (A, B, AB, O) वाले व्यक्ति से रक्त प्राप्त कर सकता है।","O- (ओ नेगेटिव) रक्त समूह को ''सर्वदाता'' (Universal Donor) कहा जाता है।"],"factsEn":["A person with the AB+ blood group can receive blood from anyone (A, B, AB, O).","The O- (O negative) blood group is called the ''Universal Donor''."],"explanationHi":"AB रक्त समूह में रक्त प्लाज्मा में एंटी-A या एंटी-B एंटीबॉडी नहीं होते हैं, इसलिए वे किसी भी प्रकार के रक्त को बिना किसी प्रतिक्रिया के स्वीकार कर सकते हैं।","explanationEn":"The AB blood group lacks both anti-A and anti-B antibodies in the blood plasma, so they can accept any blood type without an adverse reaction.","memoryTip":"AB का मतलब ''Accepts Blood'' (सबका खून ले सकता है)।","memoryTipEn":"AB Accepts from All.","related":["Universal Donor (O-)","Blood Antibodies","Karl Landsteiner"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ndcTK6sbp-Qiw1mYJXEDU', 'General Knowledge', 'असहयोग आन्दोलन (Non-Cooperation Movement) किस वर्ष शुरु हुआ?', 'In which year did the Non-Cooperation Movement start?', '1920', '1920', 97, 0, '{"facts":["यह आंदोलन महात्मा गांधी के नेतृत्व में शुरू किया गया था।","जलियांवाला बाग हत्याकांड और रॉलेट एक्ट के खिलाफ विरोध के रूप में इसकी शुरुआत हुई।"],"factsEn":["This movement was launched under the leadership of Mahatma Gandhi.","It started as a protest against the Jallianwala Bagh massacre and the Rowlatt Act."],"explanationHi":"इस आंदोलन में लोगों से ब्रिटिश वस्तुओं, स्कूलों और अदालतों का बहिष्कार करने का आग्रह किया गया। चौरी-चौरा की हिंसक घटना के बाद 1922 में इसे वापस ले लिया गया।","explanationEn":"The movement urged people to boycott British goods, schools, and courts. It was called off in 1922 after the violent Chauri Chaura incident.","memoryTip":"1920 में अंग्रेजों के साथ ''असहयोग'' (No Cooperation) शुरू किया।","memoryTipEn":"1920: Non-Cooperation began.","related":["Chauri Chaura Incident","Rowlatt Act","Mahatma Gandhi"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('hFfzybuu2Hi-34wt0DOkG', 'General Knowledge', '''पेनाल्टी स्ट्रोक'' (Penalty Stroke) किस खेल में प्रयुक्त होता है?', 'The term ''Penalty Stroke'' is used in which sport?', 'हॉकी', 'Hockey', 91, 0, '{"facts":["यह तब दिया जाता है जब डिफेंडिंग टीम पेनल्टी सर्कल के अंदर एक गंभीर फाउल करती है जिससे निश्चित गोल रुक जाता है।","''पेनाल्टी किक'' (Penalty Kick) फुटबॉल में प्रयुक्त होती है।"],"factsEn":["It is awarded when the defending team commits a severe foul inside the penalty circle that prevents a probable goal.","''Penalty Kick'' is used in Football."],"explanationHi":"पेनाल्टी स्ट्रोक के दौरान, केवल एक हमलावर (Attacker) और विरोधी टीम का गोलकीपर शामिल होते हैं; हमलावर गोल से 7 गज की दूरी से गेंद को पुश या फ्लिक करता है।","explanationEn":"During a penalty stroke, only one attacker and the opposing goalkeeper are involved; the attacker pushes or flicks the ball from 7 yards away.","memoryTip":"हॉकी की स्टिक से ''स्ट्रोक'' मारा जाता है।","memoryTipEn":"Stroke with a hockey stick.","related":["Penalty Corner","Field Hockey","Penalty Kick (Football)"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wJRRrcMODJPXP9BWlCR2B', 'General Knowledge', 'भारतीय संसद का निम्न सदन (Lower House) कौनसा है?', 'Which is the Lower House of the Indian Parliament?', 'लोकसभा', 'Lok Sabha', 95, 0, '{"facts":["लोकसभा के सदस्यों का चुनाव सीधे जनता द्वारा किया जाता है।","लोकसभा का कार्यकाल 5 वर्ष का होता है और इसे राष्ट्रपति द्वारा भंग किया जा सकता है।"],"factsEn":["Members of the Lok Sabha are directly elected by the people.","The term of the Lok Sabha is 5 years and it can be dissolved by the President."],"explanationHi":"इसे ''हाउस ऑफ द पीपल'' भी कहा जाता है। यह संसद का अधिक शक्तिशाली सदन है, विशेष रूप से वित्तीय मामलों (धन विधेयक) में।","explanationEn":"It is also known as the ''House of the People''. It is the more powerful house of Parliament, especially in financial matters (Money Bills).","memoryTip":"''लोक'' (जनता) का सदन हमेशा ''निम्न'' स्तर से जुड़ता है।","memoryTipEn":"Lok Sabha is for the local people (Lower house).","related":["Rajya Sabha (Upper House)","Money Bill","Parliament of India"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('T9mGfWu55ENIR55V06jvG', 'General Knowledge', 'सिख धर्म की स्थापना किसने की थी?', 'Who founded Sikhism?', 'गुरु नानकदेव ने', 'Guru Nanak Dev', 96, 0, '{"facts":["वे सिखों के दस गुरुओं में से पहले गुरु थे।","उनका जन्म 1469 में तलवंडी (अब पाकिस्तान में ननकाना साहिब) में हुआ था।"],"factsEn":["He was the first of the ten Sikh Gurus.","He was born in 1469 in Talwandi (now Nankana Sahib in Pakistan)."],"explanationHi":"गुरु नानक जी ने 15वीं शताब्दी में समानता, बंधुत्व और एक ईश्वर (एकेश्वरवाद) की शिक्षा देकर सिख धर्म की नींव रखी।","explanationEn":"Guru Nanak Dev laid the foundation of Sikhism in the 15th century by preaching equality, brotherhood, and the concept of one God (monotheism).","memoryTip":"सिख धर्म के ''नानक'' (जनक) गुरु नानक देव हैं।","memoryTipEn":"Nanak founded the Sikh faith.","related":["Guru Granth Sahib","Nankana Sahib","Ten Sikh Gurus"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7oeSSnrbWFniHQmLSQLKU', 'General Knowledge', 'भारत में जनगणना (Census) कितने वर्षों बाद होती है?', 'After how many years is the census conducted in India?', '10 वर्ष', '10 years', 93, 0, '{"facts":["भारत में पहली नियमित (दशकीय) जनगणना 1881 में शुरू हुई थी।","स्वतंत्र भारत की पहली जनगणना 1951 में हुई थी।"],"factsEn":["The first regular (decennial) census in India began in 1881.","The first census of independent India was conducted in 1951."],"explanationHi":"जनगणना से देश की जनसंख्या, साक्षरता, लिंगानुपात और अन्य महत्वपूर्ण जनसांख्यिकीय डेटा के बारे में जानकारी मिलती है, जो सरकार को नीतियां बनाने में मदद करती है।","explanationEn":"The census provides data on the country''s population, literacy, sex ratio, and other demographics, helping the government formulate policies.","memoryTip":"हर दशक (10 साल) में देश के लोगों को गिना जाता है।","memoryTipEn":"Decade brings a new demographic count.","related":["Lord Ripon","1881 Census","Registrar General and Census Commissioner"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lw9LAyeJeXI3s36qxd_uN', 'General Knowledge', 'मेघदूत किसकी रचना है?', 'Who is the author of ''Meghaduta''?', 'कालिदास', 'Kalidasa', 94, 0, '{"facts":["यह संस्कृत में लिखा गया एक प्रसिद्ध ''गीतिकाव्य'' (lyric poem) है।","''मेघदूत'' का अर्थ है ''बादल रूपी दूत'' (Cloud Messenger)।"],"factsEn":["It is a famous lyric poem written in Sanskrit.","''Meghaduta'' translates to ''Cloud Messenger''."],"explanationHi":"इस कविता में एक यक्ष (यक्ष) अपनी पत्नी को एक बादल (मेघ) के माध्यम से संदेश भेजता है। कालिदास को भारत का शेक्सपियर कहा जाता है।","explanationEn":"In this poem, a Yaksha sends a message to his wife through a cloud (Megha). Kalidasa is known as the Shakespeare of India.","memoryTip":"काले-काले ''मेघ'' (बादल) ''कालिदास'' की कविता में दूत बने।","memoryTipEn":"Kalidasa communicated via clouds.","related":["Abhijnanashakuntalam","Kumārasambhava","Sanskrit Literature"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3n8ln69e0UtWJ6I-zQugG', 'General Knowledge', 'भारत की स्वतंत्रता के समय ब्रिटेन का प्रधानमंत्री कौन था?', 'Who was the Prime Minister of Britain at the time of India''s independence?', 'क्लेमेंट एटली (Clement Attlee)', 'Clement Attlee', 95, 0, '{"facts":["वे ब्रिटिश लेबर पार्टी (Labour Party) के नेता थे।","उन्होंने विंस्टन चर्चिल को हराकर 1945 में चुनाव जीता था।"],"factsEn":["He was the leader of the British Labour Party.","He defeated Winston Churchill to win the 1945 election."],"explanationHi":"एटली सरकार ने भारत को सत्ता हस्तांतरित करने का निर्णय लिया और माउंटबेटन को भारत का अंतिम वायसराय बनाकर भेजा।","explanationEn":"The Attlee government decided to transfer power to India and sent Mountbatten as the final Viceroy to oversee it.","memoryTip":"आज़ादी के समय ब्रिटेन की कुर्सी पर ''एटली'' बैठे थे।","memoryTipEn":"Attlee approved India''s autonomy.","related":["Labour Party","Winston Churchill","Lord Mountbatten"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yS58_jdzxVNR7WuS9pmh5', 'General Science', 'एक्जीमा (Eczema) रोग शरीर के किस अंग को प्रभावित करता है?', 'Eczema disease affects which part of the body?', 'त्वचा (Skin)', 'Skin', 90, 0, '{"facts":["इस बीमारी में त्वचा लाल हो जाती है, खुजली होती है और पपड़ी (rashes) पड़ने लगती है।","यह एक गैर-संक्रामक (non-contagious) रोग है, अक्सर एलर्जी या अस्थमा से जुड़ा होता है।"],"factsEn":["In this disease, the skin becomes red, itchy, and develops rashes.","It is a non-contagious condition, often linked to allergies or asthma."],"explanationHi":"एक्जीमा एक पुरानी त्वचा की स्थिति है जो प्रतिरक्षा प्रणाली की अतिसक्रिय प्रतिक्रिया के कारण होती है।","explanationEn":"Eczema is a chronic skin condition caused by an overactive response of the immune system.","memoryTip":"खुजली और त्वचा का लाल होना = एक्जीमा।","memoryTipEn":"Eczema exposes the skin to itch.","related":["Dermatitis","Psoriasis","Allergies"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('E2Bd7Mf6O8D4gcC9YKAbd', 'General Knowledge', '''स्काउट एंड गाइड्स'' (Scout and Guides) संस्था की स्थापना किसने की थी?', 'Who founded the ''Scout and Guides'' organization?', 'रोबर्ट बाडेन पॉवेल', 'Robert Baden-Powell', 88, 0, '{"facts":["लड़कों के लिए ''बॉय स्काउट'' आंदोलन 1907 में इंग्लैंड में शुरू हुआ था।","लड़कियों के लिए ''गर्ल गाइड्स'' की शुरुआत 1910 में उनकी बहन एग्नेस बाडेन-पॉवेल के साथ हुई।"],"factsEn":["The ''Boy Scout'' movement for boys started in England in 1907.","The ''Girl Guides'' started in 1910 with his sister Agnes Baden-Powell."],"explanationHi":"इस संस्था का मुख्य उद्देश्य युवाओं में शारीरिक, मानसिक और आध्यात्मिक विकास को बढ़ावा देना है ताकि वे समाज में रचनात्मक भूमिका निभा सकें।","explanationEn":"The primary aim is to promote the physical, mental, and spiritual development of young people so they can play constructive roles in society.","memoryTip":"स्काउटिंग के ''पॉवेल'' (पावर) से बच्चों में अनुशासन आता है।","memoryTipEn":"Baden-Powell built the boys into scouts.","related":["Boy Scouts","Girl Guides","Youth Movements"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ViXPWbWgaCSQnvph0O2AT', 'General Knowledge', 'संसार का सबसे बड़ा महासागर कौनसा है?', 'Which is the largest ocean in the world?', 'प्रशांत महासागर (Pacific Ocean)', 'Pacific Ocean', 95, 0, '{"facts":["यह पृथ्वी के सतह क्षेत्र के एक तिहाई से अधिक हिस्से को कवर करता है।","पृथ्वी का सबसे गहरा बिंदु ''मारियाना ट्रेंच'' (Mariana Trench) इसी महासागर में स्थित है।"],"factsEn":["It covers more than one-third of the Earth''s surface area.","The deepest point on Earth, the ''Mariana Trench'', is located in this ocean."],"explanationHi":"यह महासागर एशिया और ऑस्ट्रेलिया को अमेरिका से अलग करता है और इसका नाम फर्डिनेंड मैगलन ने इसके शांत पानी के कारण ''पैसिफिक'' (Pacific/शांत) रखा था।","explanationEn":"It separates Asia and Australia from the Americas and was named ''Pacific'' (peaceful) by Ferdinand Magellan due to its calm waters.","memoryTip":"सबसे विशाल (बड़ा) सागर सबसे ''प्रशांत'' (शांत) है।","memoryTipEn":"Pacific covers the planet the most.","related":["Mariana Trench","Atlantic Ocean (2nd Largest)","Ring of Fire"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yiFsXu9FSen73Q0E_MdDz', 'General Knowledge', '''पैनल्टी किक'' (Penalty Kick) शब्द किस खेल में प्रयुक्त होता है?', 'The term ''Penalty Kick'' is used in which sport?', 'फुटबॉल', 'Football (Soccer)', 91, 0, '{"facts":["यह तब दी जाती है जब कोई खिलाड़ी अपने ही पेनल्टी क्षेत्र (Penalty box) के अंदर एक गंभीर फाउल करता है।","पेनल्टी किक गोल लाइन से 11 मीटर (12 गज) की दूरी से ली जाती है।"],"factsEn":["It is awarded when a player commits a severe foul inside their own penalty box.","The kick is taken from 11 meters (12 yards) out from the goal line."],"explanationHi":"इसमें केवल गेंद को किक मारने वाला खिलाड़ी और डिफेंडिंग टीम का गोलकीपर शामिल होते हैं, जिससे गोल होने की संभावना बहुत अधिक होती है।","explanationEn":"It involves only the kicker and the defending goalkeeper, resulting in a very high probability of a goal being scored.","memoryTip":"पैर से किक मारना = फुटबॉल।","memoryTipEn":"Kick the ball = Football.","related":["Penalty Stroke (Hockey)","Free Kick","Red Card"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('LLfX0S6AR2UvNKXvLGPx_', 'General Knowledge', 'रणजी ट्रॉफी (Ranji Trophy) का सम्बन्ध किस खेल से है?', 'Ranji Trophy is associated with which sport?', 'क्रिकेट', 'Cricket', 94, 0, '{"facts":["यह भारत की प्रमुख घरेलू प्रथम श्रेणी (First-class) क्रिकेट चैम्पियनशिप है।","इसका नाम भारत के पहले अंतरराष्ट्रीय क्रिकेटर ''रणजीत सिंह जी'' (Ranjitsinhji) के नाम पर रखा गया है।"],"factsEn":["It is India''s premier domestic first-class cricket championship.","It is named after ''Ranjitsinhji'', India''s first international cricketer."],"explanationHi":"यह टूर्नामेंट भारत के विभिन्न राज्यों और क्रिकेट संघों की टीमों के बीच खेला जाता है, और मुंबई ने इसे सबसे ज्यादा बार जीता है।","explanationEn":"This tournament is played between teams representing various states and cricket associations in India, with Mumbai winning it the most times.","memoryTip":"क्रिकेट के ''रण'' (मैदान) में ''रणजी'' ट्रॉफी जीती जाती है।","memoryTipEn":"Ranji rules domestic Cricket.","related":["Duleep Trophy","Irani Cup","Ranjitsinhji"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jx5z1_OQeulkSCTb5iqdB', 'General Knowledge', 'ज्ञानपीठ पुरस्कार (Jnanpith Award) किस क्षेत्र से सम्बंधित है?', 'Jnanpith Award is associated with which field?', 'साहित्य (Literature)', 'Literature', 96, 0, '{"facts":["यह भारत का सर्वोच्च साहित्यिक सम्मान है।","पहले ज्ञानपीठ पुरस्कार विजेता मलयालम लेखक जी. शंकर कुरुप (1965) थे।"],"factsEn":["It is the highest literary award in India.","The first recipient was Malayalam writer G. Sankara Kurup (1965)."],"explanationHi":"यह पुरस्कार भारतीय संविधान की आठवीं अनुसूची में शामिल किसी भी मान्यता प्राप्त भारतीय भाषा और अंग्रेजी में उत्कृष्ट साहित्यिक योगदान के लिए दिया जाता है।","explanationEn":"It is awarded for outstanding literary contribution in any of the recognized Indian languages in the 8th Schedule of the Constitution, as well as English.","memoryTip":"ज्ञान का पीठ (केंद्र) = साहित्य।","memoryTipEn":"Jnan (Knowledge) is found in Literature.","related":["Sahitya Akademi Award","Saraswati Samman","G. Sankara Kurup"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NcDZMR7QLyC8ZwA81v8Wd', 'General Knowledge', 'भारत का सर्वोच्च खेल पुरस्कार कौनसा है?', 'Which is the highest sports award in India?', 'राजीव गाँधी खेल रत्न पुरस्कार (अब मेजर ध्यानचंद खेल रत्न)', 'Rajiv Gandhi Khel Ratna (Now Major Dhyan Chand Khel Ratna)', 95, 0, '{"facts":["महत्वपूर्ण अद्यतन: 2021 में भारत सरकार ने इसका नाम बदलकर ''मेजर ध्यानचंद खेल रत्न पुरस्कार'' कर दिया है।","इसके पहले प्राप्तकर्ता शतरंज के ग्रैंडमास्टर विश्वनाथन आनंद (1991-92) थे।"],"factsEn":["Important Update: In 2021, the Govt of India renamed it to ''Major Dhyan Chand Khel Ratna Award''.","The first recipient was Chess Grandmaster Viswanathan Anand (1991-92)."],"explanationHi":"यह पुरस्कार पिछले चार वर्षों की अवधि में खेल के क्षेत्र में शानदार और उत्कृष्ट प्रदर्शन के लिए किसी खिलाड़ी को दिया जाता है।","explanationEn":"It is awarded for spectacular and most outstanding performance in the field of sports by a sportsperson over a period of four years.","memoryTip":"खेलों का सबसे बड़ा ''रत्न'' = खेल रत्न (अब मेजर ध्यानचंद)।","memoryTipEn":"Khel Ratna is the jewel of sports.","related":["Major Dhyan Chand","Arjuna Award","Viswanathan Anand"]}', 'published', 1776084070, 1776084070);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UQhYdKx3MDvOnzhAeoEMI', 'General Knowledge', 'अर्जुन पुरस्कार किस वर्ष शुरु हुए?', 'In which year were the Arjuna Awards instituted?', '1961', '1961', 92, 0, '{"facts":["यह पुरस्कार भारत सरकार द्वारा खेल में उत्कृष्ट प्रदर्शन के लिए दिया जाता है।","इसमें अर्जुन की एक कांस्य प्रतिमा और नकद पुरस्कार शामिल होता है।"],"factsEn":["This award is given by the Government of India for outstanding performance in sports.","It includes a bronze statuette of Arjuna and a cash prize."],"explanationHi":"यह मेजर ध्यानचंद खेल रत्न के बाद भारत का दूसरा सबसे बड़ा खेल सम्मान है।","explanationEn":"It is the second-highest sporting honor of India, after the Major Dhyan Chand Khel Ratna.","memoryTip":"अर्जुन के ''तीर'' का लक्ष्य 61 पर लगा (1961)।","memoryTipEn":"Arjuna aimed in ''61.","related":["Dronacharya Award","Major Dhyan Chand Khel Ratna","National Sports Awards"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MjV7rXOYCV4tx_TqgOfa9', 'General Knowledge', 'भारत की मानक समय रेखा कौनसी है?', 'Which is the Standard Time Meridian of India?', '82.5 डिग्री पूर्वी देशांतर रेखा', '82.5 degrees East Longitude', 95, 0, '{"facts":["यह रेखा उत्तर प्रदेश के इलाहाबाद (अब प्रयागराज) के पास मिर्ज़ापुर से होकर गुजरती है।","भारतीय मानक समय (IST) ग्रीनविच मीन टाइम (GMT) से 5 घंटे 30 मिनट आगे है।"],"factsEn":["This line passes through Mirzapur near Allahabad (now Prayagraj) in Uttar Pradesh.","Indian Standard Time (IST) is 5 hours and 30 minutes ahead of Greenwich Mean Time (GMT)."],"explanationHi":"चूंकि भारत का पूर्व-पश्चिम विस्तार बड़ा है, इसलिए पूरे देश में एक ही समय बनाए रखने के लिए 82.5° E को मानक देशांतर चुना गया है।","explanationEn":"Since India has a large east-west extent, 82.5° E is chosen as the standard meridian to maintain a single time across the country.","memoryTip":"साढ़े बयासी (82.5) डिग्री से भारत का समय सेट होता है।","memoryTipEn":"82.5 degrees keeps India on time.","related":["IST","Greenwich Mean Time","Mirzapur"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Fsy1Cq6esUIg81TV3OR92', 'General Knowledge', 'मैग्सेसे पुरस्कार पाने वाले पहले भारतीय कौन थे?', 'Who was the first Indian to receive the Ramon Magsaysay Award?', 'विनोबा भावे', 'Vinoba Bhave', 94, 0, '{"facts":["उन्हें 1958 में सामुदायिक नेतृत्व (Community Leadership) के लिए यह पुरस्कार मिला था।","विनोबा भावे ''भूदान आंदोलन'' (Bhoodan Movement) के संस्थापक थे।"],"factsEn":["He received this award in 1958 for Community Leadership.","Vinoba Bhave was the founder of the ''Bhoodan Movement'' (Land Gift Movement)."],"explanationHi":"रेमन मैग्सेसे पुरस्कार को अक्सर ''एशिया का नोबेल पुरस्कार'' कहा जाता है। भावे को उनके अहिंसक और सामाजिक सुधार कार्यों के लिए सम्मानित किया गया था।","explanationEn":"The Ramon Magsaysay Award is often called the ''Nobel Prize of Asia''. Bhave was honored for his non-violent and social reform work.","memoryTip":"भूदान करने वाले ''भावे'' को एशिया का नोबेल (मैग्सेसे) मिला।","memoryTipEn":"Bhave brought the first Magsaysay to India.","related":["Bhoodan Movement","Ramon Magsaysay","Asia''s Nobel Prize"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('S0WTo_ketyivroPSg_7Cc', 'General Knowledge', '''मोनालिसा'' किसकी विश्वविख्यात पेंटिंग है?', '''Mona Lisa'' is a world-famous painting by whom?', 'लियोनार्डो-दा-विंची', 'Leonardo da Vinci', 93, 0, '{"facts":["यह पेंटिंग वर्तमान में पेरिस (फ्रांस) के लौवर संग्रहालय (Louvre Museum) में रखी गई है।","यह इतालवी पुनर्जागरण (Italian Renaissance) की एक उत्कृष्ट कृति है।"],"factsEn":["This painting is currently housed in the Louvre Museum in Paris, France.","It is a masterpiece of the Italian Renaissance."],"explanationHi":"यह चित्र अपनी विषयवस्तु की रहस्यमयी मुस्कान (enigmatic smile) के लिए दुनिया भर में प्रसिद्ध है।","explanationEn":"The portrait is world-famous for the subject''s enigmatic smile.","memoryTip":"''विंची'' की कूंची (Brush) से बनी ''मोनालिसा''।","memoryTipEn":"Da Vinci drew the mysterious smile.","related":["The Last Supper","Louvre Museum","Renaissance Art"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('43JhVbaZa4sjcLdpqNnsI', 'General Knowledge', 'स्वांग किस राज्य की लोकनृत्य कला है?', 'Swang is a folk dance art of which state?', 'हरियाणा', 'Haryana', 86, 0, '{"facts":["यह एक लोकप्रिय लोक नाट्य (Folk Theatre) का रूप है।","इसमें संगीत, नृत्य और संवाद के माध्यम से पौराणिक और ऐतिहासिक कहानियाँ बताई जाती हैं।"],"factsEn":["It is a popular form of folk theatre.","It tells mythological and historical stories through music, dance, and dialogue."],"explanationHi":"यह मुख्य रूप से खुले मंच पर किया जाता है, और हरियाणा के अलावा राजस्थान और उत्तर प्रदेश के कुछ हिस्सों में भी लोकप्रिय है।","explanationEn":"It is mainly performed on an open stage and is also popular in parts of Rajasthan and Uttar Pradesh, besides Haryana.","memoryTip":"हरियाणा के लोग ''स्वांग'' (नाटक) रचने में माहिर हैं।","memoryTipEn":"Swang is the stage of Haryana.","related":["Saang","Folk Theatre","Nautanki"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BnHuOO_vJtu_QumUkFj5d', 'General Knowledge', 'भारत में कितने उच्च न्यायालय (High Courts) हैं?', 'How many High Courts are there in India?', '24 (वर्तमान में 25)', '24 (Currently 25)', 88, 0, '{"facts":["पीडीएफ के अनुसार उत्तर 24 है, लेकिन 2019 में आंध्र प्रदेश उच्च न्यायालय के गठन के बाद भारत में 25 उच्च न्यायालय हैं।","सबसे नया (25वां) उच्च न्यायालय अमरावती (आंध्र प्रदेश) में है।"],"factsEn":["Per the PDF the answer is 24, but with the formation of the AP High Court in 2019, there are 25 High Courts.","The newest (25th) High Court is in Amaravati (Andhra Pradesh)."],"explanationHi":"प्रत्येक राज्य का अपना उच्च न्यायालय हो सकता है, या दो या अधिक राज्यों/केंद्र शासित प्रदेशों का एक साझा उच्च न्यायालय हो सकता है (जैसे पंजाब और हरियाणा उच्च न्यायालय)।","explanationEn":"Each state can have its own High Court, or two or more states/UTs can share a common High Court (like the Punjab and Haryana High Court).","memoryTip":"हाई कोर्ट्स का ''चौथाई शतक'' (25) पूरा हो गया।","memoryTipEn":"A quarter-century (25) of High Courts in India.","related":["Supreme Court","Calcutta High Court (Oldest)","Jurisdiction"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FHtSKRkmLjEw-TEYh0Vny', 'General Knowledge', 'कोई विधेयक धन विधेयक है या नहीं इसका फैसला कौन करता है?', 'Who decides whether a bill is a Money Bill or not?', 'लोकसभा अध्यक्ष', 'Speaker of the Lok Sabha', 95, 0, '{"facts":["संविधान के अनुच्छेद 110 में धन विधेयक को परिभाषित किया गया है।","लोकसभा अध्यक्ष का यह निर्णय अंतिम होता है।"],"factsEn":["Article 110 of the Constitution defines a Money Bill.","The decision of the Lok Sabha Speaker on this is final."],"explanationHi":"धन विधेयक केवल लोकसभा में पेश किया जा सकता है, और इसे पारित करने के मामले में राज्यसभा की शक्तियां सीमित (केवल 14 दिन की देरी) होती हैं।","explanationEn":"A Money Bill can only be introduced in the Lok Sabha, and the Rajya Sabha has limited powers regarding it (can only delay it by 14 days).","memoryTip":"धन (पैसे) का फैसला जनता के प्रतिनिधि (लोकसभा) का अध्यक्ष करेगा।","memoryTipEn":"Speaker holds the purse strings.","related":["Article 110","Financial Bill","Rajya Sabha powers"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AWZfjcuE1BQVv3lNLzHMZ', 'General Knowledge', 'अंतिम मुग़ल सम्राट कौन था?', 'Who was the last Mughal Emperor?', 'बहादुर शाह जफ़र द्वितीय', 'Bahadur Shah Zafar II', 94, 0, '{"facts":["उन्हें 1857 के विद्रोह का नाममात्र का नेता बनाया गया था।","विद्रोह के बाद, अंग्रेजों ने उन्हें रंगून (अब म्यांमार) निर्वासित कर दिया, जहाँ उनकी मृत्यु हो गई।"],"factsEn":["He was made the nominal leader of the 1857 revolt.","After the revolt, the British exiled him to Rangoon (now Myanmar), where he died."],"explanationHi":"बहादुर शाह ज़फ़र एक प्रसिद्ध उर्दू कवि भी थे। उनके निर्वासन के साथ ही भारत में तीन सदियों से चले आ रहे मुग़ल साम्राज्य का अंत हो गया।","explanationEn":"Bahadur Shah Zafar was also a renowned Urdu poet. His exile marked the end of the three-century-old Mughal Empire in India.","memoryTip":"मुग़ल सल्तनत का ''बहादुर'' शासक ''ज़फर'' (पराजय) के साथ खत्म हुआ।","memoryTipEn":"Zafar was the last Zealous Mughal.","related":["Revolt of 1857","Mughal Empire","Rangoon"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2D1GnSCQ-qi57mXu-XOJ1', 'General Knowledge', 'तम्बाकू पर पूरी तरह प्रतिबन्ध लगाने वाला विश्व का पहला देश कौनसा है?', 'Which is the first country in the world to completely ban tobacco?', 'भूटान', 'Bhutan', 89, 0, '{"facts":["भूटान ने 2004 में तम्बाकू की बिक्री और उत्पादन पर पूर्ण प्रतिबंध लगा दिया था।","भूटान की राजधानी थिम्पू है।"],"factsEn":["Bhutan completely banned the sale and production of tobacco in 2004.","The capital of Bhutan is Thimphu."],"explanationHi":"भूटान एक ऐसा देश है जो ''ग्रॉस नेशनल हैप्पीनेस'' (Gross National Happiness) को अपनी प्राथमिकता मानता है, जिसमें सार्वजनिक स्वास्थ्य एक महत्वपूर्ण घटक है।","explanationEn":"Bhutan is a country that prioritizes ''Gross National Happiness'', in which public health is a crucial component.","memoryTip":"तम्बाकू पीने वाले ''भूत'' (भूटान) बन जाते हैं, इसलिए वहां बैन है।","memoryTipEn":"Bhutan banned the burning tobacco.","related":["Gross National Happiness","Thimphu","Public Health"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ubktSgzmmeZADXUqUSMll', 'General Knowledge', '''गोदान'' किसकी रचना है?', 'Who is the author of ''Godan''?', 'मुंशी प्रेमचंद', 'Munshi Premchand', 95, 0, '{"facts":["यह 1936 में प्रकाशित एक प्रसिद्ध हिंदी उपन्यास है।","''गोदान'' का अर्थ ''गाय का दान'' (The Gift of a Cow) है।"],"factsEn":["It is a famous Hindi novel published in 1936.","''Godan'' translates to ''The Gift of a Cow''."],"explanationHi":"यह उपन्यास भारतीय किसान जीवन, उनके संघर्ष, गरीबी और जमींदारी प्रथा के शोषण का एक मार्मिक और यथार्थवादी चित्रण है।","explanationEn":"The novel is a poignant and realistic depiction of Indian peasant life, their struggles, poverty, and the exploitation by the Zamindari system.","memoryTip":"प्रेमचंद ने ''गाय के दान'' (गोदान) पर सबसे श्रेष्ठ उपन्यास लिखा।","memoryTipEn":"Premchand penned the peasant''s plight in Godan.","related":["Gaban","Karmabhoomi","Hindi Literature"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('475CnoDsS1SF-klE5lrsZ', 'General Science', '''स्वाइन फ्लू'' बीमारी किस विषाणु से फैलती है?', 'Swine flu disease is caused by which virus?', 'H1N1', 'H1N1', 92, 0, '{"facts":["यह एक इन्फ्लूएंजा ए (Influenza A) वायरस है।","2009 में विश्व स्वास्थ्य संगठन (WHO) ने स्वाइन फ्लू को एक महामारी (Pandemic) घोषित किया था।"],"factsEn":["It is an Influenza A virus subtype.","In 2009, the WHO declared swine flu a pandemic."],"explanationHi":"यह वायरस मूल रूप से सूअरों (Swine) में पाया जाता था, लेकिन यह उत्परिवर्तित (mutate) होकर मनुष्यों में भी आसानी से फैलने लगा।","explanationEn":"The virus originally circulated in pigs (swine), but it mutated and started spreading easily from human to human.","memoryTip":"स्वाइन फ्लू का वायरस H और N (H1N1) से मिलकर बना है।","memoryTipEn":"H1N1 hits humans and hogs.","related":["Bird Flu (H5N1)","Pandemic","Influenza"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('snwTL94i8cP9c4o3Z3zlY', 'General Knowledge', 'राष्ट्रीय मतदाता दिवस (National Voters'' Day) कब मनाया जाता है?', 'When is National Voters'' Day celebrated?', '25 जनवरी', '25 January', 93, 0, '{"facts":["25 जनवरी 1950 को भारत के चुनाव आयोग (Election Commission of India) की स्थापना हुई थी।","मतदाता दिवस मनाने की शुरुआत 2011 में हुई थी।"],"factsEn":["The Election Commission of India was established on January 25, 1950.","The celebration of Voters'' Day started in 2011."],"explanationHi":"इस दिन का मुख्य उद्देश्य युवाओं को मतदान के प्रति जागरूक करना और चुनावी प्रक्रिया में उनकी भागीदारी बढ़ाना है।","explanationEn":"The main objective of this day is to encourage, facilitate and maximize enrolment, especially for new voters.","memoryTip":"गणतंत्र दिवस (26 जनवरी) से एक दिन पहले ''वोटर'' तैयार होते हैं।","memoryTipEn":"Vote on the 25th to celebrate the Republic on the 26th.","related":["Election Commission of India","Republic Day","Sukumar Sen"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ttWCfb5O5yCqddTMI6nKO', 'General Knowledge', 'भारत सरकार का संवैधानिक मुखिया कौन होता है?', 'Who is the constitutional head of the Government of India?', 'राष्ट्रपति', 'President', 95, 0, '{"facts":["संविधान के अनुच्छेद 53 के अनुसार, संघ की कार्यकारी शक्ति राष्ट्रपति में निहित होती है।","हालांकि, वास्तविक कार्यकारी शक्तियां प्रधानमंत्री के नेतृत्व वाली मंत्रिपरिषद के पास होती हैं।"],"factsEn":["According to Article 53, the executive power of the Union is vested in the President.","However, the real executive powers are exercised by the Council of Ministers led by the Prime Minister."],"explanationHi":"राष्ट्रपति ''राज्य का प्रमुख'' (Head of State) होता है, जबकि प्रधानमंत्री ''सरकार का प्रमुख'' (Head of Government) होता है।","explanationEn":"The President is the ''Head of State'', whereas the Prime Minister is the ''Head of Government''.","memoryTip":"संविधान में सबसे ऊपर ''राष्ट्रपति'' का नाम होता है।","memoryTipEn":"President is the formal figurehead.","related":["Article 53","Prime Minister","Head of State"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HkSNQrdvw6_fjLq2CW8eA', 'General Knowledge', 'किस संविधान संशोधन द्वारा मौलिक कर्तव्यों (Fundamental Duties) को संविधान में जोड़ा गया?', 'By which Constitutional Amendment were Fundamental Duties added to the Constitution?', '42वें', '42nd Amendment', 96, 0, '{"facts":["ये कर्तव्य सरदार स्वर्ण सिंह समिति की सिफारिशों के आधार पर 1976 में जोड़े गए थे।","शुरुआत में 10 मौलिक कर्तव्य थे; 86वें संशोधन (2002) द्वारा 11वां कर्तव्य जोड़ा गया।"],"factsEn":["These duties were added in 1976 on the recommendations of the Sardar Swaran Singh Committee.","Initially there were 10 duties; the 11th was added by the 86th Amendment (2002)."],"explanationHi":"मौलिक कर्तव्य सोवियत संघ (USSR) के संविधान से प्रेरित हैं और इन्हें संविधान के भाग IVA (अनुच्छेद 51A) में रखा गया है।","explanationEn":"Fundamental Duties are inspired by the USSR constitution and are placed in Part IVA (Article 51A) of the Constitution.","memoryTip":"4 और 2 (42) मिलकर देश के लिए ''कर्तव्य'' बनाते हैं।","memoryTipEn":"42nd Amendment gave 10 Duties.","related":["Swaran Singh Committee","Article 51A","Mini Constitution"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4MlvFXYOR7J49gtl03eLU', 'General Knowledge', 'नमक कानून को तोड़ने के लिए महात्मा गाँधी ने कौनसा आन्दोलन शुरु किया?', 'Which movement was launched by Mahatma Gandhi to break the salt law?', 'सविनय अवज्ञा आन्दोलन', 'Civil Disobedience Movement', 97, 0, '{"facts":["इसकी शुरुआत 12 मार्च 1930 को ''दांडी मार्च'' (Dandi March) के साथ हुई थी।","गांधीजी ने साबरमती आश्रम से दांडी (गुजरात तट) तक 385 किमी की पैदल यात्रा की थी।"],"factsEn":["It started on March 12, 1930, with the ''Dandi March''.","Gandhiji walked 385 km from Sabarmati Ashram to Dandi (Gujarat coast)."],"explanationHi":"6 अप्रैल 1930 को दांडी पहुंचकर गांधीजी ने समुद्र के पानी से नमक बनाकर प्रतीकात्मक रूप से ब्रिटिश कानून तोड़ा और इस राष्ट्रव्यापी आंदोलन की शुरुआत की।","explanationEn":"On April 6, 1930, Gandhiji reached Dandi and symbolically broke the British law by making salt from seawater, launching this nationwide movement.","memoryTip":"नमक बनाकर अंग्रेजों की ''अवज्ञा'' (Disobedience) की गई।","memoryTipEn":"Salt March started Civil Disobedience.","related":["Dandi March","Salt Satyagraha","Gandhi-Irwin Pact"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qmZ-IGu5udvpk4Rhf86mS', 'General Knowledge', 'उपराष्ट्रपति का चुनाव कौन करता है?', 'Who elects the Vice President?', 'संसद सदस्य', 'Members of Parliament', 94, 0, '{"facts":["उपराष्ट्रपति का चुनाव एक निर्वाचक मंडल द्वारा किया जाता है जिसमें लोकसभा और राज्यसभा दोनों के सदस्य शामिल होते हैं।","राष्ट्रपति चुनाव के विपरीत, इसमें राज्य विधानसभाओं के सदस्य (MLA) भाग नहीं लेते हैं।"],"factsEn":["The VP is elected by an electoral college consisting of members of both the Lok Sabha and the Rajya Sabha.","Unlike the President''s election, MLAs (State assembly members) do not participate."],"explanationHi":"इस चुनाव में संसद के निर्वाचित (Elected) और मनोनीत (Nominated) दोनों प्रकार के सदस्य वोट डालते हैं।","explanationEn":"In this election, both elected and nominated members of the Parliament cast their votes.","memoryTip":"उपराष्ट्रपति को ''पूरी संसद'' (लोकसभा+राज्यसभा) चुनती है।","memoryTipEn":"Both houses vote for the Vice President.","related":["Presidential Election","Electoral College","Article 66"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nMb0_gKf6HXhnSVyBDPet', 'General Knowledge', 'विजयस्तंभ कहाँ स्थित है?', 'Where is Vijay Stambha (Tower of Victory) located?', 'चित्तोड़गढ़ में', 'Chittorgarh', 88, 0, '{"facts":["इसे मेवाड़ के राजा राणा कुंभा (Rana Kumbha) ने बनवाया था।","यह भगवान विष्णु को समर्पित 9 मंजिला एक विशाल मीनार है।"],"factsEn":["It was built by Rana Kumbha, the king of Mewar.","It is a massive 9-storey tower dedicated to Lord Vishnu."],"explanationHi":"राणा कुंभा ने 1448 में मालवा और गुजरात की संयुक्त सेनाओं पर अपनी जीत का जश्न मनाने के लिए इस विजय स्तंभ का निर्माण करवाया था।","explanationEn":"Rana Kumbha built this victory tower in 1448 to commemorate his victory over the combined armies of Malwa and Gujarat.","memoryTip":"चित्तौड़गढ़ में राणा कुंभा की ''विजय'' का ''स्तंभ'' है।","memoryTipEn":"Victory at Chittorgarh stands tall.","related":["Rana Kumbha","Mahmud Khilji","Rajputana Architecture"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PxACgsex0FQPJ7sqjplzu', 'General Knowledge', 'विश्व का सबसे लम्बा रेलमार्ग ट्रांस-साइबेरिया किन दो शहरों को जोड़ता है?', 'Which two cities does the world''s longest railway line, the Trans-Siberian Railway, connect?', 'सेंट पीटर्सबर्ग से ब्लादीवोस्तक (रूस)', 'St. Petersburg (Moscow) to Vladivostok (Russia)', 92, 0, '{"facts":["यह रेलमार्ग लगभग 9,289 किलोमीटर (5,772 मील) लंबा है।","यह एक छोर से दूसरे छोर तक यात्रा करने में लगभग 7 दिन का समय लेता है।"],"factsEn":["The railway line is approximately 9,289 kilometers (5,772 miles) long.","It takes about 7 days to travel from one end to the other."],"explanationHi":"यह रूस के यूरोपीय हिस्से (पश्चिम) को प्रशांत महासागर के तट (पूरब) से जोड़ता है, जो 8 अलग-अलग समय क्षेत्रों (Time zones) से होकर गुजरता है।","explanationEn":"It connects European Russia (West) to the Pacific coast (East), passing through 8 different time zones.","memoryTip":"साइबेरिया में ''पीट'' (Petersburg) से लेकर ''व्लादी'' (Vladivostok) तक ट्रेन दौड़ती है।","memoryTipEn":"Trans-Siberian crosses all of Russia.","related":["Russia","Siberia","Longest Railway Network"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZfgWxhu7HFhbgqew_fJjW', 'General Knowledge', 'अमरकंटक किस नदी का उद्गम स्थल है?', 'Amarkantak is the source of which river?', 'नर्मदा', 'Narmada', 94, 0, '{"facts":["नर्मदा नदी पश्चिम की ओर बहने वाली भारत की सबसे लंबी प्रायद्वीपीय नदी है।","अमरकंटक से एक और महत्वपूर्ण नदी ''सोन'' (Son River) भी निकलती है।"],"factsEn":["Narmada is the longest west-flowing peninsular river in India.","Another important river, the ''Son'', also originates from Amarkantak."],"explanationHi":"अमरकंटक मध्य प्रदेश के अनूपपुर जिले में मैकाल पहाड़ियों में स्थित है। नर्मदा नदी दरार घाटी (Rift valley) से होकर बहती है।","explanationEn":"Amarkantak is located in the Maikal Hills in the Anuppur district of Madhya Pradesh. The Narmada flows through a rift valley.","memoryTip":"नर्मदा नदी ''अमर'' है, जो अमरकंटक से निकलती है।","memoryTipEn":"Amarkantak mothers the Narmada.","related":["Son River","Rift Valley","West-flowing rivers"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FbVUGezCgp6GciLlDeAQi', 'General Knowledge', 'भारत में जिप्सम (Gypsum) का सर्वाधिक उत्पादन किस राज्य में होता है?', 'Which state is the largest producer of Gypsum in India?', 'राजस्थान', 'Rajasthan', 88, 0, '{"facts":["भारत के कुल जिप्सम उत्पादन का लगभग 90% से अधिक हिस्सा राजस्थान से आता है।","जिप्सम का उपयोग मुख्य रूप से सीमेंट और प्लास्टर ऑफ पेरिस (POP) बनाने में किया जाता है।"],"factsEn":["More than 90% of India''s total gypsum production comes from Rajasthan.","Gypsum is mainly used in making cement and Plaster of Paris (POP)."],"explanationHi":"राजस्थान के शुष्क (dry) क्षेत्रों, विशेष रूप से बीकानेर और जैसलमेर में जिप्सम के विशाल भंडार पाए जाते हैं।","explanationEn":"Vast deposits of gypsum are found in the dry regions of Rajasthan, especially Bikaner and Jaisalmer.","memoryTip":"राजस्थान के रेगिस्तान में ''जिप्सम'' (Gypsum) का भंडार छिपा है।","memoryTipEn":"Rajasthan is rich in Gypsum.","related":["Plaster of Paris","Cement Industry","Bikaner"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SfG9DK4r3fyLtsb2RiAYq', 'General Knowledge', 'अंग्रेजी ईस्ट इंडिया कम्पनी ने भारत में पहला कारखाना कहाँ लगाया?', 'Where did the English East India Company establish its first factory in India?', 'सूरत (गुजरात) में', 'Surat (Gujarat)', 95, 0, '{"facts":["यह कारखाना 1613 ईस्वी में स्थापित किया गया था।","मुगल सम्राट जहाँगीर ने थॉमस रो (Thomas Roe) के प्रयासों के बाद अंग्रेजों को यह अनुमति दी थी।"],"factsEn":["This factory was established in 1613 AD.","Mughal Emperor Jahangir granted this permission after the efforts of Thomas Roe."],"explanationHi":"अंग्रेजों ने भारत में व्यापार (मुख्य रूप से मसाले और कपड़े) करने के लिए सूरत को अपने पहले स्थायी व्यापारिक केंद्र के रूप में चुना।","explanationEn":"The British chose Surat as their first permanent trading post to conduct business (mainly spices and textiles) in India.","memoryTip":"अंग्रेजों ने ''सूरत'' (शक्ल) देखकर ''सूरत'' में कारखाना लगाया।","memoryTipEn":"Surat saw the first British factory.","related":["Jahangir","Sir Thomas Roe","East India Company"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('u8SJYnXIHaUxk8Bph2o2h', 'General Knowledge', '''आईने अकबरी'' पुस्तक किसने लिखी?', 'Who wrote the book ''Ain-i-Akbari''?', 'अबुल फ़ज़ल', 'Abul Fazl', 91, 0, '{"facts":["यह ''अकबरनामा'' (Akbarnama) का तीसरा और अंतिम खंड है।","अबुल फ़ज़ल सम्राट अकबर के ''नवरत्नों'' (Nine Jewels) में से एक थे।"],"factsEn":["It is the third and final volume of the ''Akbarnama''.","Abul Fazl was one of the ''Navaratnas'' (Nine Jewels) of Emperor Akbar."],"explanationHi":"यह पुस्तक 16वीं शताब्दी में मुगल साम्राज्य की सेना, राजस्व, समाज और प्रशासन के बारे में विस्तृत जानकारी देती है।","explanationEn":"This book provides detailed information about the army, revenues, society, and administration of the Mughal Empire in the 16th century.","memoryTip":"अकबर का ''आईना'' अबुल ''फ़ज़ल'' ने दिखाया।","memoryTipEn":"Fazl framed Akbar''s reign.","related":["Akbarnama","Navaratnas","Mughal Administration"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zLzGsUHtRbCdSYCw7detX', 'General Knowledge', '''बुली'' (Bully) शब्द किस खेल में प्रयुक्त होता है?', 'The term ''Bully'' is used in which sport?', 'हॉकी', 'Hockey', 87, 0, '{"facts":["जब खेल में कोई रुकावट आती है (जैसे चोट लगना या नियम टूटना), तो खेल को ''बुली'' के माध्यम से फिर से शुरू किया जाता है।","इसमें दोनों टीमों के एक-एक खिलाड़ी आमने-सामने खड़े होकर गेंद को हिट करने का प्रयास करते हैं।"],"factsEn":["When play is interrupted (like an injury or rule breach), it is restarted via a ''Bully''.","One player from each team faces off, trying to hit the ball."],"explanationHi":"हालांकि आधुनिक हॉकी नियमों में ''बुली'' का उपयोग कम कर दिया गया है, लेकिन यह हॉकी की शब्दावली का एक महत्वपूर्ण हिस्सा रहा है।","explanationEn":"Although its use is reduced in modern hockey rules, ''bully'' remains a significant part of hockey terminology.","memoryTip":"हॉकी के मैदान में ''बुली'' (बदमाशी) करोगे तो पेनल्टी मिलेगी।","memoryTipEn":"Bully for the hockey ball.","related":["Field Hockey","Penalty Corner","Scoop"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NLo4DCaRhvFLS64L-CBpt', 'General Knowledge', '''उड़न परी'' (Flying Nymph/Girl) किसे पुकारा जाता है?', 'Who is called the ''Udan Pari'' (Flying Nymph)?', 'पी.टी. उषा', 'P.T. Usha', 93, 0, '{"facts":["उन्हें ''पय्योली एक्सप्रेस'' (Payyoli Express) भी कहा जाता है।","वे 1984 के लॉस एंजिल्स ओलंपिक में 400 मीटर बाधा दौड़ (Hurdles) में एक सेकंड के 1/100वें हिस्से से कांस्य पदक से चूक गई थीं।"],"factsEn":["She is also known as the ''Payyoli Express''.","She missed the bronze medal by 1/100th of a second in the 400m hurdles at the 1984 Los Angeles Olympics."],"explanationHi":"भारतीय एथलेटिक्स में उनकी अभूतपूर्व गति और उपलब्धियों (विशेषकर 1980 के दशक में) के कारण उन्हें यह उपनाम दिया गया।","explanationEn":"She was given this nickname due to her phenomenal speed and achievements in Indian athletics, especially during the 1980s.","memoryTip":"ट्रैक पर पी.टी. उषा ''परी'' की तरह ''उड़'' जाती थीं।","memoryTipEn":"PT Usha flew like a fairy on the track.","related":["Payyoli Express","Indian Athletics","1984 Olympics"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('b212gd2DyOn__T1nCfXOj', 'General Knowledge', 'झीलों की नगरी (City of Lakes) कौनसा शहर कहलाता है?', 'Which city is known as the ''City of Lakes''?', 'उदयपुर', 'Udaipur', 94, 0, '{"facts":["यह राजस्थान राज्य में स्थित है।","इसे ''पूर्व का वेनिस'' (Venice of the East) भी कहा जाता है।"],"factsEn":["It is located in the state of Rajasthan.","It is also called the ''Venice of the East''."],"explanationHi":"उदयपुर में कई कृत्रिम झीलों का एक जटिल नेटवर्क है, जिनमें पिछोला झील (Lake Pichola) और फतेह सागर झील सबसे प्रसिद्ध हैं।","explanationEn":"Udaipur has a complex network of several artificial lakes, with Lake Pichola and Fateh Sagar Lake being the most famous.","memoryTip":"सूर्य ''उदय'' होते ही झीलें चमकने लगती हैं (उदयपुर)।","memoryTipEn":"Udaipur shines with lakes.","related":["Lake Pichola","Rajasthan Tourism","Venice of the East"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dL7bDoKR5Vqy_4lUBQ38h', 'General Knowledge', 'आर्यसमाज की स्थापना कब और कहाँ की गयी थी?', 'When and where was the Arya Samaj founded?', 'मुंबई में (1875 में)', 'In Mumbai (in 1875)', 95, 0, '{"facts":["इसकी स्थापना स्वामी दयानंद सरस्वती ने की थी।","इसका मुख्य उद्देश्य हिंदू धर्म में सुधार लाना और ''वेदों की ओर लौटो'' का संदेश फैलाना था।"],"factsEn":["It was founded by Swami Dayanand Saraswati.","Its main objective was to reform Hinduism and spread the message of ''Go back to Vedas''."],"explanationHi":"आर्य समाज मूर्ति पूजा, बाल विवाह और जाति व्यवस्था का विरोध करता है और महिलाओं की शिक्षा का समर्थन करता है।","explanationEn":"Arya Samaj opposes idol worship, child marriage, and the caste system, and strongly supports women''s education.","memoryTip":"1875 में ''मुंबई'' में ''आर्यों'' ने अपना समाज बनाया।","memoryTipEn":"Arya Samaj arose in Mumbai in 1875.","related":["Swami Dayanand Saraswati","Go back to Vedas","Satyarth Prakash"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('cFXFwrksThI4x-I6waWW4', 'General Knowledge', 'सबसे प्राचीन वेद कौनसा है?', 'Which is the oldest Veda?', 'ऋग्वेद', 'Rigveda', 96, 0, '{"facts":["यह हिंदू धर्म के चार वेदों में सबसे पुराना है, जिसमें 10 मंडल और 1028 सूक्त हैं।","प्रसिद्ध ''गायत्री मंत्र'' इसी वेद से लिया गया है।"],"factsEn":["It is the oldest of the four Vedas of Hinduism, containing 10 Mandalas and 1028 hymns.","The famous ''Gayatri Mantra'' is taken from this Veda."],"explanationHi":"यह मुख्य रूप से वैदिक देवताओं (अग्नि, इंद्र, सोम आदि) की स्तुति में रचित भजनों का संग्रह है।","explanationEn":"It is primarily a collection of hymns composed in praise of Vedic deities (Agni, Indra, Soma, etc.).","memoryTip":"सबसे प्राचीन ''ऋषि'' ने ''ऋग्वेद'' लिखा।","memoryTipEn":"Rigveda is the Root of all Vedas.","related":["Samaveda","Yajurveda","Atharvaveda"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Q6DakkES5wFNKLBO36aNj', 'General Knowledge', 'राष्ट्रीय ''शिक्षा दिवस'' (National Education Day) कब मनाया जाता है?', 'When is the National Education Day celebrated?', '11 नवंबर को', '11 November', 91, 0, '{"facts":["यह दिन स्वतंत्र भारत के पहले शिक्षा मंत्री ''मौलाना अबुल कलाम आजाद'' के जन्मदिन पर मनाया जाता है।","भारत में इसकी शुरुआत 2008 में हुई थी।"],"factsEn":["This day is celebrated on the birthday of ''Maulana Abul Kalam Azad'', the first Education Minister of independent India.","It was started in India in 2008."],"explanationHi":"उन्होंने भारत में शिक्षा प्रणाली और IIT तथा UGC जैसी उच्च शिक्षण संस्थाओं की स्थापना में महत्वपूर्ण भूमिका निभाई थी।","explanationEn":"He played a crucial role in establishing the education system and higher education institutes like IITs and UGC in India.","memoryTip":"1 और 1 (11) मिलकर अच्छी शिक्षा (Education) बनाते हैं।","memoryTipEn":"Nov 11 stands for National Education.","related":["Maulana Abul Kalam Azad","Teachers'' Day (Sep 5)","UGC"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1seBNwTNpe4FiqxF0kBcr', 'General Knowledge', 'किसके जन्मदिन को शिक्षा दिवस के रूप में मनाते हैं?', 'Whose birthday is celebrated as Education Day?', 'भारत के पहले शिक्षा मंत्री मौलाना अबुलकलाम आजाद', 'Maulana Abul Kalam Azad, India''s first Education Minister', 90, 0, '{"facts":["वे एक प्रमुख स्वतंत्रता सेनानी और 1923 में भारतीय राष्ट्रीय कांग्रेस के सबसे कम उम्र के अध्यक्ष थे।","उन्हें 1992 में मरणोपरांत भारत रत्न से सम्मानित किया गया था।"],"factsEn":["He was a prominent freedom fighter and the youngest President of the INC in 1923.","He was posthumously awarded the Bharat Ratna in 1992."],"explanationHi":"उनके समाचार पत्र ''अल-हिलाल'' (Al-Hilal) ने हिंदू-मुस्लिम एकता और राष्ट्रवाद को बढ़ावा दिया था।","explanationEn":"His newspaper ''Al-Hilal'' promoted Hindu-Muslim unity and nationalism.","memoryTip":"''आजाद'' भारत की ''शिक्षा'' की नींव मौलाना आजाद ने रखी।","memoryTipEn":"Azad advocated for India''s Education.","related":["Al-Hilal","India Wins Freedom (Book)","National Education Day"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5WJhYiU3Att9r418Az8hl', 'General Science', 'भाभा परमाणु अनुसन्धान केंद्र (BARC) कहाँ स्थित है?', 'Where is the Bhabha Atomic Research Centre (BARC) located?', 'ट्राम्बे (मुंबई) में', 'Trombay (Mumbai)', 93, 0, '{"facts":["इसकी स्थापना 1954 में डॉ. होमी जहाँगीर भाभा ने की थी।","यह भारत का प्रमुख परमाणु अनुसंधान केंद्र है जो नाभिकीय ऊर्जा के शांतिपूर्ण उपयोग पर काम करता है।"],"factsEn":["It was founded in 1954 by Dr. Homi J. Bhabha.","It is India''s premier nuclear research facility working on peaceful applications of nuclear energy."],"explanationHi":"डॉ. भाभा को ''भारतीय परमाणु कार्यक्रम का जनक'' (Father of the Indian nuclear program) कहा जाता है। उनके निधन के बाद इस केंद्र का नाम उनके सम्मान में रखा गया।","explanationEn":"Dr. Bhabha is known as the ''Father of the Indian nuclear program''. After his death, the centre was renamed in his honor.","memoryTip":"भाभा (BARC) का ''बॉम्ब'' (Trombay/Bombay) में रिसर्च होता है।","memoryTipEn":"BARC is based in Bombay (Trombay).","related":["Homi J. Bhabha","Nuclear Power Corporation of India","Apsara (First Nuclear Reactor)"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3VOqMbOKs3sqBUMbMNpRO', 'General Knowledge', 'सन 1928 के बारदोली आन्दोलन का नेतृत्व किसने किया था?', 'Who led the Bardoli Satyagraha of 1928?', 'सरदार वल्लभ भाई पटेल ने', 'Sardar Vallabhbhai Patel', 95, 0, '{"facts":["यह गुजरात के बारदोली में किसानों का एक प्रमुख कर-विरोधी (No-tax) आंदोलन था।","इस आंदोलन की सफलता के बाद ही वहां की महिलाओं ने उन्हें ''सरदार'' (Sardar) की उपाधि दी थी।"],"factsEn":["It was a major no-tax movement by farmers in Bardoli, Gujarat.","It was after the success of this movement that the local women gave him the title ''Sardar'' (Leader)."],"explanationHi":"ब्रिटिश सरकार ने अनुचित रूप से लगान (Tax) में 22% की वृद्धि कर दी थी, जिसे पटेल जी के नेतृत्व में हुए सफल सत्याग्रह के बाद वापस लेना पड़ा।","explanationEn":"The British government had unjustly increased the land tax by 22%, which they were forced to roll back after the successful Satyagraha led by Patel.","memoryTip":"''बारदोली'' में ''बल्लभ'' (पटेल) की धाक जम गई और वे ''सरदार'' बन गए।","memoryTipEn":"Bardoli birthed the ''Sardar''.","related":["Sardar Title","Peasant Movements","Iron Man of India"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NArs4W3_HXkzf_RT4DogR', 'General Knowledge', 'खालसा पंथ की स्थापना किसने की थी?', 'Who founded the Khalsa Panth?', 'गुरु गोबिंद सिंह', 'Guru Gobind Singh', 94, 0, '{"facts":["खालसा पंथ की स्थापना 1699 में बैसाखी के दिन की गई थी।","गुरु गोबिंद सिंह सिखों के 10वें और अंतिम मानव गुरु थे।"],"factsEn":["The Khalsa Panth was established in 1699 on the day of Baisakhi.","Guru Gobind Singh was the 10th and the last human Sikh Guru."],"explanationHi":"खालसा का अर्थ है ''शुद्ध''। गुरु जी ने सिखों को एक सैन्य-संत समुदाय (Warrior-Saint community) में बदल दिया और उन्हें ''पंच ककार'' (5 K''s) धारण करने का आदेश दिया।","explanationEn":"Khalsa means ''Pure''. The Guru transformed Sikhs into a Warrior-Saint community and instructed them to wear the ''Five K''s'' (Kesh, Kangha, Kara, Kachera, Kirpan).","memoryTip":"गोबिंद सिंह जी ने ''खालसा'' की फौज तैयार की।","memoryTipEn":"Gobind Singh created the Khalsa warriors.","related":["Baisakhi","Five K''s (Panj Kakka)","Sikhism"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7s6thgCEaukE9NBAh9W07', 'General Knowledge', 'मुगल वंश की स्थापना किसने की थी?', 'Who founded the Mughal Dynasty?', 'बाबर', 'Babur', 96, 0, '{"facts":["बाबर ने 1526 ई. में पानीपत के प्रथम युद्ध में इब्राहिम लोदी को हराकर मुगल वंश की नींव रखी।","वह फरगना (उज्बेकिस्तान) से आया था।"],"factsEn":["Babur laid the foundation of the Mughal Dynasty after defeating Ibrahim Lodi in the First Battle of Panipat in 1526 AD.","He hailed from Fergana (Uzbekistan)."],"explanationHi":"उसने युद्ध में पहली बार बारूद (Gunpowder) और तोपखाने (Artillery) का प्रभावी इस्तेमाल किया, जो उसकी जीत का मुख्य कारण था।","explanationEn":"He effectively used gunpowder and artillery for the first time in an Indian battle, which was a major reason for his victory.","memoryTip":"''बाबर'' आया और मुगल राज लाया।","memoryTipEn":"Babur began the Mughal empire.","related":["First Battle of Panipat 1526","Ibrahim Lodi","Humayun"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UvAaAla2p9TZDfxAmPk1n', 'General Knowledge', 'भारत की पहली महिला I.P.S. अधिकारी कौन थी?', 'Who was the first female I.P.S. officer of India?', 'किरण बेदी', 'Kiran Bedi', 95, 0, '{"facts":["वे 1972 में भारतीय पुलिस सेवा (IPS) में शामिल हुई थीं।","उन्होंने तिहाड़ जेल में पुलिस महानिरीक्षक (IG) के रूप में जेल सुधारों के लिए रेमन मैग्सेसे पुरस्कार जीता था।"],"factsEn":["She joined the Indian Police Service (IPS) in 1972.","She won the Ramon Magsaysay Award for her prison reforms as IG at Tihar Jail."],"explanationHi":"सेवा से निवृत्त होने के बाद वे राजनीति में आईं और पुडुचेरी की उपराज्यपाल (Lieutenant Governor) के रूप में भी कार्य किया।","explanationEn":"After retiring from service, she entered politics and also served as the Lieutenant Governor of Puducherry.","memoryTip":"पुलिस की वर्दी (IPS) सबसे पहले किरण ''बेदी'' ने पहनी।","memoryTipEn":"Kiran Bedi broke the police glass ceiling.","related":["Tihar Jail Reforms","Ramon Magsaysay Award","Anna Rajam Malhotra (First woman IAS)"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8gjp7WGCOD-w9NmKLePGQ', 'General Knowledge', 'कथक किस राज्य का शास्त्रीय नृत्य है?', 'Kathak is a classical dance of which state?', 'उत्तर प्रदेश (उत्तर भारत)', 'Uttar Pradesh (North India)', 94, 0, '{"facts":["''कथक'' शब्द ''कथा'' (Story) से लिया गया है; कथक करने वालों को ''कथाकार'' कहा जाता था।","प्रसिद्ध नर्तक बिरजू महाराज (Birju Maharaj) इसी नृत्य शैली से संबंधित थे।"],"factsEn":["The word ''Kathak'' is derived from ''Katha'' (Story); performers were called storytellers.","Famous dancer Birju Maharaj was associated with this dance form."],"explanationHi":"यह नृत्य मंदिरों, मुग़ल दरबारों और बाद में ब्रिटिश राज के दौरान विकसित हुआ। इसमें पैरों की जटिल लयबद्ध गतियाँ (Footwork) और चक्कर (Spins) प्रमुख हैं।","explanationEn":"This dance evolved through temples, Mughal courts, and later British rule. It is characterized by intricate rhythmic footwork and spins.","memoryTip":"उत्तर प्रदेश में ''कथा'' (कथक) सुनाकर नृत्य करते हैं।","memoryTipEn":"Kathak tells the tales of the North.","related":["Pandit Birju Maharaj","Lucknow Gharana","Classical Dances of India"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3nNT03BkHgUtTau3W2YLU', 'General Knowledge', 'टीपू सुल्तान की राजधानी कौनसी थी?', 'What was the capital of Tipu Sultan?', 'श्रीरंगपट्टनम', 'Srirangapatna', 92, 0, '{"facts":["टीपू सुल्तान को ''मैसूर का शेर'' (Tiger of Mysore) भी कहा जाता है।","उन्होंने अंग्रेजों के खिलाफ चार ''एंग्लो-मैसूर युद्ध'' लड़े थे।"],"factsEn":["Tipu Sultan is also known as the ''Tiger of Mysore''.","He fought four ''Anglo-Mysore Wars'' against the British."],"explanationHi":"चतुर्थ आंग्ल-मैसूर युद्ध (1799) में अपनी राजधानी श्रीरंगपट्टनम की रक्षा करते हुए टीपू सुल्तान वीरगति को प्राप्त हुए थे।","explanationEn":"Tipu Sultan died defending his capital Srirangapatna in the Fourth Anglo-Mysore War (1799).","memoryTip":"टीपू ने ''श्रीरंग'' (श्रीरंगपट्टनम) में अपना किला बनाया।","memoryTipEn":"Srirangapatna was Tipu''s stronghold.","related":["Anglo-Mysore Wars","Hyder Ali","Treaty of Srirangapatna"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('S825Bg2S1o5NDTBnCpBDS', 'General Knowledge', '''चाइनामैन'' (Chinaman) शब्द किस खेल में प्रयुक्त होता है?', 'The term ''Chinaman'' is used in which sport?', 'क्रिकेट', 'Cricket', 89, 0, '{"facts":["यह एक प्रकार की गेंदबाज़ी शैली है जिसे ''लेफ्ट-आर्म अनऑर्थोडॉक्स स्पिन'' (Left-arm unorthodox spin) कहा जाता है।","भारत के ''कुलदीप यादव'' एक प्रसिद्ध चाइनामैन गेंदबाज हैं।"],"factsEn":["It is a bowling style referred to as ''Left-arm unorthodox spin''.","India''s ''Kuldeep Yadav'' is a famous Chinaman bowler."],"explanationHi":"जब कोई बाएँ हाथ का गेंदबाज़ अपनी कलाई (Wrist) का उपयोग करके गेंद को टर्न कराता है (जो दाएँ हाथ के बल्लेबाज़ के लिए अंदर की ओर आती है), तो उसे ''चाइनामैन'' गेंदबाज़ी कहते हैं।","explanationEn":"When a left-arm bowler uses their wrist to spin the ball (turning it into a right-handed batsman), it is called ''Chinaman'' bowling.","memoryTip":"क्रिकेट के मैदान में ''चाइनामैन'' फिरकी (Spin) डालता है।","memoryTipEn":"Chinaman spins the cricket ball.","related":["Kuldeep Yadav","Wrist Spin","Ellis Achong (First ''Chinaman'' bowler)"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('A1q6HIaSC_xMt9de_lMBk', 'General Science', 'सबसे कठोरतम पदार्थ कौन सा है?', 'Which is the hardest substance?', 'हीरा (Diamond)', 'Diamond', 95, 0, '{"facts":["हीरा कार्बन (Carbon) का एक प्राकृतिक अपररूप (Allotrope) है।","यह प्रकाश का पूर्ण आंतरिक परावर्तन (Total Internal Reflection) करता है, जिससे यह चमकता है।"],"factsEn":["Diamond is a natural allotrope of Carbon.","It causes Total Internal Reflection of light, giving it its brilliance."],"explanationHi":"हीरे में कार्बन परमाणु बहुत ही मजबूत सहसंयोजक बंधों (Covalent bonds) के साथ एक 3D नेटवर्क में जुड़े होते हैं, जो इसे अत्यधिक कठोर बनाते हैं।","explanationEn":"In a diamond, carbon atoms are linked in a 3D network by very strong covalent bonds, making it exceptionally hard.","memoryTip":"हीरा इतना ''हार्ड'' है कि शीशा भी काट देता है।","memoryTipEn":"Diamond is carbon''s hardest form.","related":["Allotropes of Carbon","Total Internal Reflection","Graphite"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6wRpjZcZaw8PeVvaviOre', 'General Science', 'डायनामाईट का आविष्कार किसने किया?', 'Who invented Dynamite?', 'अल्फ्रेड नोबल ने', 'Alfred Nobel', 94, 0, '{"facts":["अल्फ्रेड नोबेल एक स्वीडिश रसायनज्ञ और इंजीनियर थे।","उन्होंने नाइट्रोग्लिसरीन (Nitroglycerin) का उपयोग करके डायनामाइट बनाया।"],"factsEn":["Alfred Nobel was a Swedish chemist and engineer.","He created dynamite using Nitroglycerin."],"explanationHi":"डायनामाइट की खोज ने खनन और निर्माण को आसान बना दिया। इसी खोज से कमाए गए धन से उन्होंने ''नोबेल पुरस्कार'' (Nobel Prize) की स्थापना की।","explanationEn":"The invention of dynamite made mining and construction easier. He used the fortune from this invention to establish the ''Nobel Prizes''.","memoryTip":"डायनामाइट का ''नोबल'' (Nobel) विचार एक पुरस्कार बन गया।","memoryTipEn":"Nobel invented the explosive dynamite.","related":["Nobel Prize","Nitroglycerin","Explosives"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('retRloHXbtvULLDdO7Pl9', 'General Knowledge', 'बिस्मिल्ला खान का संबंध किस वाद्ययंत्र से है?', 'Bismillah Khan is associated with which musical instrument?', 'शहनाई', 'Shehnai', 92, 0, '{"facts":["उन्हें 2001 में भारत के सर्वोच्च नागरिक सम्मान ''भारत रत्न'' से सम्मानित किया गया था।","15 अगस्त 1947 को स्वतंत्रता के दिन उन्होंने लाल किले पर शहनाई बजाई थी।"],"factsEn":["He was awarded India''s highest civilian honor, the ''Bharat Ratna'', in 2001.","He played the Shehnai at the Red Fort on Independence Day, August 15, 1947."],"explanationHi":"उन्होंने शहनाई जैसे लोक वाद्य यंत्र को भारतीय शास्त्रीय संगीत के मुख्य मंच पर लाकर वैश्विक ख्याति दिलाई।","explanationEn":"He brought the folk instrument Shehnai to the centre stage of Indian classical music, giving it global recognition.","memoryTip":"बिस्मिल्लाह बोलकर ''शहनाई'' की तान छेड़ते थे।","memoryTipEn":"Bismillah blew life into the Shehnai.","related":["Bharat Ratna","Indian Classical Music","Red Fort 1947"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('cwviNmo1sG-Pxp9ICoz3o', 'General Knowledge', 'ऑस्कर पुरस्कार (Oscar Award) का संबंध किस क्षेत्र से है?', 'The Oscar Award is associated with which field?', 'फिल्म (सिनेमा)', 'Film (Cinema)', 95, 0, '{"facts":["ऑस्कर को आधिकारिक तौर पर ''अकादमी पुरस्कार'' (Academy Awards) कहा जाता है।","ऑस्कर जीतने वाले पहले भारतीय ''भानु अथैया'' (Bhanu Athaiya) थे (फिल्म गांधी में कॉस्ट्यूम डिजाइन के लिए)।"],"factsEn":["Oscars are officially known as the ''Academy Awards''.","The first Indian to win an Oscar was ''Bhanu Athaiya'' (for costume design in the film Gandhi)."],"explanationHi":"यह पुरस्कार संयुक्त राज्य अमेरिका में ''एकेडमी ऑफ मोशन पिक्चर आर्ट्स एंड साइंसेज'' द्वारा सिनेमा उद्योग में कलात्मक और तकनीकी योग्यता के लिए दिया जाता है।","explanationEn":"It is given by the Academy of Motion Picture Arts and Sciences in the USA for artistic and technical merit in the film industry.","memoryTip":"हॉलीवुड की ''फिल्मों'' को ''ऑस्कर'' की ट्रॉफी मिलती है।","memoryTipEn":"Oscar is the gold of Cinema.","related":["Academy Awards","Bhanu Athaiya","AR Rahman"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('t7nwwUL6As9QTBNALJqml', 'General Science', 'AIDS का पूर्ण विस्तार क्या होगा?', 'What is the full form of AIDS?', 'अक्वायर्ड इम्यूनो डेफिशियेंसी सिंड्रोम (Acquired Immunodeficiency Syndrome)', 'Acquired Immunodeficiency Syndrome', 96, 0, '{"facts":["यह HIV (Human Immunodeficiency Virus) नामक वायरस के कारण होता है।","विश्व एड्स दिवस हर साल 1 दिसंबर को मनाया जाता है।"],"factsEn":["It is caused by a virus called HIV (Human Immunodeficiency Virus).","World AIDS Day is observed every year on December 1."],"explanationHi":"यह एक बीमारी है जिसमें एचआईवी वायरस मानव शरीर की प्रतिरक्षा प्रणाली (Immune system) को पूरी तरह से नष्ट कर देता है, जिससे शरीर बीमारियों से लड़ नहीं पाता।","explanationEn":"It is a condition where the HIV virus completely destroys the human immune system, leaving the body unable to fight off infections.","memoryTip":"AIDS = शरीर का ''इम्यून सिस्टम'' ''डेफिशिएंट'' (कमजोर) हो जाना।","memoryTipEn":"Acquired lack of Immunity.","related":["HIV","World AIDS Day","Immune System"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-DNvRe6pKQq5opB8rMdLb', 'General Knowledge', 'जलियाँवाला बाग में गोलीबारी का आदेश किस जनरल ने दिया था?', 'Which General gave the order to fire at Jallianwala Bagh?', 'माइकल ओ डायर (रेजिनाल्ड डायर)', 'Michael O''Dwyer / Reginald Dyer', 97, 0, '{"facts":["नोट: पीडीएफ में ''माइकल ओ डायर'' लिखा है (जो उस समय पंजाब का लेफ्टिनेंट गवर्नर था)। लेकिन वास्तव में गोलियां चलाने का आदेश ''कर्नल रेजिनाल्ड डायर'' (General Reginald Dyer) ने दिया था।","यह नरसंहार 13 अप्रैल 1919 को हुआ था।"],"factsEn":["Note: The PDF says ''Michael O''Dwyer'' (who was the Lt. Gov of Punjab). But the actual firing order was given by ''Col. Reginald Dyer''.","This massacre took place on April 13, 1919."],"explanationHi":"शांतिपूर्ण तरीके से रॉलेट एक्ट का विरोध कर रहे निहत्थे लोगों पर डायर ने गोलियां चलवा दीं। माइकल ओ''ड्वायर ने इस कृत्य का समर्थन किया था, जिसकी बाद में उधम सिंह ने हत्या कर दी।","explanationEn":"Dyer ordered firing on unarmed people peacefully protesting the Rowlatt Act. Michael O''Dwyer endorsed the act and was later assassinated by Udham Singh.","memoryTip":"डायर (Dyer) ने बाग में ''डायर'' (Dire - भयानक) स्थिति पैदा कर दी।","memoryTipEn":"Dyer directed the deadly fire.","related":["Jallianwala Bagh Massacre","Rowlatt Act","Udham Singh"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('VLx6sOExg3-juWccQRyoc', 'General Knowledge', 'पटना का प्राचीन नाम क्या था?', 'What was the ancient name of Patna?', 'पाटलिपुत्र', 'Pataliputra', 93, 0, '{"facts":["इसे मगध साम्राज्य के शासक अजातशत्रु और उदायिन द्वारा गंगा और सोन नदियों के संगम पर बसाया गया था।","यह मौर्य साम्राज्य (चंद्रगुप्त, अशोक) और गुप्त साम्राज्य की राजधानी रही है।"],"factsEn":["It was founded by Magadha rulers Ajatashatru and Udayin at the confluence of the Ganges and Son rivers.","It served as the capital of the Mauryan (Chandragupta, Ashoka) and Gupta Empires."],"explanationHi":"प्राचीन काल में यह शहर शिक्षा, वाणिज्य और कला का एक बहुत बड़ा केंद्र था।","explanationEn":"In ancient times, this city was a massive center for learning, commerce, and art.","memoryTip":"पटना के ''पाट'' पर ''पुत्र'' (पाटलिपुत्र) का राज था।","memoryTipEn":"Patna was Pataliputra of the past.","related":["Magadha Empire","Mauryan Empire","Udayin"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rgBQcbYc3ZKbdQ7Eb4Bz8', 'General Knowledge', 'दिल्ली में लाल किला (Red Fort) किसने बनवाया?', 'Who built the Red Fort in Delhi?', 'मुगल बादशाह शाहजहाँ ने', 'Mughal Emperor Shah Jahan', 95, 0, '{"facts":["लाल किले का निर्माण 1638 में शुरू हुआ और 1648 में पूरा हुआ।","यह लाल बलुआ पत्थर (Red Sandstone) से बना है, जिससे इसका नाम लाल किला पड़ा।"],"factsEn":["Construction of the Red Fort started in 1638 and was completed in 1648.","It is built of red sandstone, giving it the name Red Fort."],"explanationHi":"शाहजहां ने अपनी राजधानी को आगरा से दिल्ली स्थानांतरित करने के लिए इस किले (शाहजहानाबाद) का निर्माण करवाया था। हर साल स्वतंत्रता दिवस पर प्रधानमंत्री यहीं झंडा फहराते हैं।","explanationEn":"Shah Jahan built this fort (Shahjahanabad) to shift his capital from Agra to Delhi. The PM hoists the flag here every Independence Day.","memoryTip":"आगरा का ''ताज'' और दिल्ली का ''लाल किला'' दोनों ''शाहजहाँ'' ने बनवाए।","memoryTipEn":"Shah Jahan shifted the Red Fort to Delhi.","related":["Shah Jahan","Taj Mahal","Independence Day (Aug 15)"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('h4NZVJrdK7HOMK3fVC9GQ', 'General Knowledge', 'नेताजी सुभाष राष्ट्रीय खेल संस्थान कहाँ स्थित है?', 'Where is the Netaji Subhas National Institute of Sports (NIS) located?', 'पटियाला (पंजाब)', 'Patiala (Punjab)', 90, 0, '{"facts":["यह एशिया का सबसे बड़ा खेल संस्थान है।","यह भारतीय खेल प्राधिकरण (Sports Authority of India - SAI) का मुख्य शैक्षणिक केंद्र है।"],"factsEn":["It is the largest sports institute in Asia.","It is the academic wing of the Sports Authority of India (SAI)."],"explanationHi":"यहाँ भारतीय खेल टीमों के कोच (Coaches) और एथलीटों को प्रशिक्षित किया जाता है।","explanationEn":"It is the primary center for training coaches and elite athletes for Indian sports teams.","memoryTip":"पटियाला के ''पेग'' नहीं, पटियाला के ''खेल'' संस्थान (NIS) मशहूर हैं।","memoryTipEn":"Patiala prepares the players.","related":["Sports Authority of India (SAI)","Subhas Chandra Bose","Sports Coaching"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1iJYjzkc1YZSWGmGO-yh2', 'General Knowledge', 'आगा खां कप (Agha Khan Cup) किस खेल से संबंधित है?', 'Aga Khan Cup is related to which sport?', 'हॉकी', 'Hockey', 91, 0, '{"facts":["यह भारत के सबसे पुराने और सबसे प्रतिष्ठित हॉकी टूर्नामेंटों में से एक है।","मेजर ध्यानचंद टूर्नामेंट और सुल्तान अजलान शाह कप भी हॉकी से जुड़े हैं।"],"factsEn":["It is one of the oldest and most prestigious hockey tournaments in India.","Major Dhyan Chand Tournament and Sultan Azlan Shah Cup are also related to hockey."],"explanationHi":"इस कप का आयोजन पश्चिमी भारत (विशेषकर मुंबई) में किया जाता रहा है।","explanationEn":"This cup has been organized primarily in Western India (especially Mumbai).","memoryTip":"हॉकी खेलने के लिए ''आगे'' (आगा) आओ।","memoryTipEn":"Aga Khan commands Hockey.","related":["Field Hockey Tournaments","Dhyan Chand Trophy","Sultan Azlan Shah Cup"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('b7mc0FNQ0PC3dcQE9m4Jh', 'General Knowledge', 'बांदीपुर अभयारण्य (Bandipur National Park) किस राज्य में स्थित है?', 'Bandipur Sanctuary is located in which state?', 'कर्नाटक', 'Karnataka', 92, 0, '{"facts":["यह ''प्रोजेक्ट टाइगर'' (Project Tiger) के तहत एक महत्वपूर्ण बाघ अभयारण्य (Tiger Reserve) है।","यह नीलगिरि बायोस्फीयर रिजर्व (Nilgiri Biosphere Reserve) का एक हिस्सा है।"],"factsEn":["It is an important Tiger Reserve under ''Project Tiger''.","It is a part of the Nilgiri Biosphere Reserve."],"explanationHi":"यह पार्क कभी मैसूर साम्राज्य के महाराजाओं का निजी शिकारगाह हुआ करता था, लेकिन आज यह वन्यजीव संरक्षण (विशेषकर हाथियों और बाघों) के लिए प्रसिद्ध है।","explanationEn":"Once the private hunting ground of the Maharajas of Mysore, it is now famous for wildlife conservation (especially elephants and tigers).","memoryTip":"''कर्नाटक'' के जंगलों में बाघों को ''बंदी'' (बांदीपुर) नहीं बनाया जाता, बल्कि बचाया जाता है।","memoryTipEn":"Bandipur''s tigers roam in Karnataka.","related":["Project Tiger","Nagarhole National Park","Nilgiri Biosphere Reserve"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oN0qcKV0R_FD587lcPaeH', 'General Science', 'भाप इंजन (Steam Engine) का आविष्कार किसने किया था?', 'Who invented the Steam Engine?', 'जेम्स वाट (James Watt)', 'James Watt', 94, 0, '{"facts":["जेम्स वाट ने 18वीं सदी में थॉमस न्यूकोमेन के पुराने इंजन में बड़े सुधार किए थे।","जेम्स वाट के नाम पर ही शक्ति की इकाई ''वाट'' (Watt) का नाम रखा गया है।"],"factsEn":["James Watt made major improvements to Thomas Newcomen''s earlier engine in the 18th century.","The unit of power, ''Watt'', is named after him."],"explanationHi":"उनके द्वारा विकसित भाप इंजन ने पूरी दुनिया में ''औद्योगिक क्रांति'' (Industrial Revolution) की नींव रखी, जिससे कारखानों और ट्रेनों को चलाना संभव हुआ।","explanationEn":"His improved steam engine laid the foundation for the ''Industrial Revolution'' worldwide, powering factories and trains.","memoryTip":"इंजन ने ऐसी ''भाप'' छोड़ी कि सबकी ''वाट'' लग गई।","memoryTipEn":"Watt powered the steam.","related":["Industrial Revolution","Watt (Unit of Power)","Thomas Newcomen"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yf4bnXzX_IK4sfGL91SJB', 'General Science', 'रेडियो का आविष्कार किसने किया?', 'Who invented the Radio?', 'इटली निवासी मारकोनी ने (Guglielmo Marconi)', 'Guglielmo Marconi (of Italy)', 91, 0, '{"facts":["मारकोनी ने 1895 में पहला सफल वायरलेस टेलीग्राफ (Wireless telegraph) बनाया था।","उन्हें 1909 में भौतिकी का नोबेल पुरस्कार मिला।"],"factsEn":["Marconi built the first successful wireless telegraph in 1895.","He received the Nobel Prize in Physics in 1909."],"explanationHi":"मारकोनी ने रेडियो तरंगों के माध्यम से लंबी दूरी तक बिना तारों के संदेश भेजने की तकनीक का विकास किया, जिससे संचार की दुनिया बदल गई।","explanationEn":"Marconi developed the technology to send messages wirelessly over long distances using radio waves, revolutionizing communication.","memoryTip":"रेडियो न चले तो ''मार कोहनी'' (मारकोनी) और चालू कर।","memoryTipEn":"Marconi made the waves connect.","related":["Wireless Telegraphy","Heinrich Hertz","Nobel Prize in Physics"]}', 'published', 1776084283, 1776084283);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('P69ty78RKMd1ilagl7pDp', 'General Knowledge', 'किस भारतीय राज्य की राजभाषा अंग्रेजी है?', 'Which Indian state has English as its official language?', 'नागालैंड', 'Nagaland', 92, 0, '{"facts":["नागालैंड पूर्वोत्तर भारत का एक राज्य है।","यहाँ की मुख्य जनसंख्या विभिन्न जनजातियों (Naga tribes) से बनी है, इसलिए संपर्क भाषा के रूप में अंग्रेजी का उपयोग किया जाता है।"],"factsEn":["Nagaland is a state in Northeast India.","Its population mainly consists of various Naga tribes, hence English is used as the link language."],"explanationHi":"भाषाई विविधता को जोड़ने और आधिकारिक कार्यों को सुगम बनाने के लिए नागालैंड ने 1967 में अंग्रेजी को अपनी राजभाषा घोषित किया था।","explanationEn":"To bridge linguistic diversity and facilitate official work, Nagaland declared English as its official language in 1967.","memoryTip":"नाग (Naga) लैंड में लोग ''इंग्लिश'' बोलते हैं।","memoryTipEn":"Nagaland natively navigates in English.","related":["Arunachal Pradesh (English official)","Meghalaya (English official)","Eighth Schedule"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YT_CDgXTDnJKpPCbw0X9Z', 'General Knowledge', 'भारतीय राष्ट्रीय कांग्रेस का प्रथम मुस्लिम अध्यक्ष कौन था?', 'Who was the first Muslim President of the Indian National Congress?', 'बदरुद्दीन तैयब जी', 'Badruddin Tyabji', 95, 0, '{"facts":["उन्होंने 1887 में कांग्रेस के तीसरे अधिवेशन (मद्रास) की अध्यक्षता की थी।","वे बॉम्बे उच्च न्यायालय के पहले भारतीय बैरिस्टर भी थे।"],"factsEn":["He presided over the third session of the Congress in Madras in 1887.","He was also the first Indian barrister in the Bombay High Court."],"explanationHi":"स्वतंत्रता संग्राम के शुरुआती चरण में वे एक प्रमुख उदारवादी (Moderate) नेता थे जिन्होंने मुसलमानों को कांग्रेस में शामिल होने के लिए प्रोत्साहित किया।","explanationEn":"He was a prominent moderate leader in the early phase of the freedom struggle who encouraged Muslims to join the Congress.","memoryTip":"कांग्रेस के पहले मुस्लिम अध्यक्ष की ''तैयब'' (Tabiyat) बहुत अच्छी थी।","memoryTipEn":"Tyabji took the third turn.","related":["W. C. Bonnerjee","Madras Session 1887","Indian National Congress"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yWmvt8fGACuvoGBBJzut2', 'General Knowledge', 'भारत के प्रथम गृह मन्त्री कौन थे?', 'Who was the first Home Minister of India?', 'सरदार वल्लभभाई पटेल', 'Sardar Vallabhbhai Patel', 96, 0, '{"facts":["वे भारत के पहले उप प्रधानमंत्री (Deputy PM) भी थे।","उन्होंने 562 से अधिक देसी रियासतों (Princely states) का भारत में विलय कराया।"],"factsEn":["He was also the first Deputy PM of India.","He integrated over 562 princely states into the Indian Union."],"explanationHi":"उनके लौह संकल्प और कूटनीति के कारण उन्हें ''भारत का लौह पुरुष'' (Iron Man of India) और ''भारत का बिस्मार्क'' कहा जाता है।","explanationEn":"Due to his iron will and diplomacy, he is known as the ''Iron Man of India'' and the ''Bismarck of India''.","memoryTip":"देश के पहले ''गृह'' (घर) को सरदार ने मजबूत किया।","memoryTipEn":"Sardar secured the home front.","related":["Iron Man of India","Statue of Unity","Integration of Princely States"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kIv12gzuMxAjr8ftdRcjs', 'General Knowledge', 'संसार की प्रथम महिला प्रधान मन्त्री कौन हैं?', 'Who is the first female Prime Minister in the world?', 'सिरिमाओ भंडारनायके', 'Sirimavo Bandaranaike', 90, 0, '{"facts":["वे श्रीलंका (उस समय सिलोन) की प्रधानमंत्री थीं।","उन्होंने 1960 में पहली बार पदभार ग्रहण किया था।"],"factsEn":["She was the Prime Minister of Sri Lanka (then Ceylon).","She assumed office for the first time in 1960."],"explanationHi":"अपने पति (तत्कालीन पीएम) की हत्या के बाद उन्होंने राजनीति में प्रवेश किया और तीन बार श्रीलंका की प्रधानमंत्री बनीं।","explanationEn":"She entered politics after the assassination of her husband (the then PM) and became the Prime Minister of Sri Lanka three times.","memoryTip":"पूरी दुनिया की ''सिरमौर'' (सिरिमाओ) महिला पीएम।","memoryTipEn":"Sirimavo steered Sri Lanka.","related":["Indira Gandhi","Sri Lanka","Ceylon"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('a7eNnJ0DHxpEMSIrDdQfg', 'General Knowledge', 'हड़प्पा की सभ्यता किस युग से सम्बन्धित है?', 'Harappan civilization is associated with which age?', 'कांस्य युग (Bronze Age)', 'Bronze Age', 95, 0, '{"facts":["हड़प्पा सभ्यता (Indus Valley Civilization) अपनी उन्नत नगर नियोजन प्रणाली (Town planning) के लिए जानी जाती है।","इन्होंने उपकरण और हथियार बनाने के लिए तांबे और टिन को मिलाकर कांस्य (Bronze) का उपयोग किया।"],"factsEn":["The Harappan (Indus Valley) Civilization is known for its advanced town planning.","They used bronze (an alloy of copper and tin) to make tools and weapons."],"explanationHi":"चूंकि इस सभ्यता के लोगों को लोहे का ज्ञान नहीं था, इसलिए उनका पूरा तकनीकी विकास कांस्य धातु पर निर्भर था।","explanationEn":"Since the people of this civilization did not have knowledge of iron, their technological advancement was heavily reliant on bronze.","memoryTip":"हड़प्पा के लोग ''कांस्य'' के बर्तनों में खाते थे।","memoryTipEn":"Harappans hammered the Bronze.","related":["Indus Valley Civilization","Town Planning","Chalcolithic Age"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nSRAPBBCc7gilc-I7N3mw', 'General Knowledge', '"दीन-ए-इलाही" धर्म किस मुगल शासक ने चलाया था?', 'Which Mughal ruler started the religion "Din-i-Ilahi"?', 'अकबर', 'Akbar', 94, 0, '{"facts":["इसकी स्थापना 1582 ई. में हुई थी।","बीरबल एकमात्र हिंदू थे जिन्होंने इस धर्म को अपनाया था।"],"factsEn":["It was founded in 1582 AD.","Birbal was the only Hindu to adopt this religion."],"explanationHi":"अकबर ने सभी धर्मों (हिंदू, इस्लाम, जैन, पारसी, ईसाई) के अच्छे सिद्धांतों को मिलाकर इस नए समधर्मी (Syncretic) पंथ की शुरुआत की थी।","explanationEn":"Akbar started this new syncretic cult by combining the good principles of all religions (Hinduism, Islam, Jainism, Zoroastrianism, Christianity).","memoryTip":"अकबर ने ''दीन'' (धर्म) में ''इलाही'' (ईश्वर) को मिलाया।","memoryTipEn":"Akbar aimed for divine faith.","related":["Ibadat Khana","Sulh-i-Kul","Birbal"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yoLz5p9OZmr8rsP5wKPK9', 'General Science', 'उगते और डूबते समय सूर्य लाल प्रतीत क्यों होता है?', 'Why does the sun appear red during sunrise and sunset?', 'क्योंकि लाल रंग का प्रकीर्णन (Scattering) सबसे कम होता है', 'Because the scattering of red light is the least', 93, 0, '{"facts":["लाल रंग की तरंगदैर्घ्य (Wavelength) सबसे अधिक होती है।","नीले रंग का प्रकीर्णन सबसे अधिक होता है, इसलिए दोपहर में आसमान नीला दिखता है।"],"factsEn":["Red color has the longest wavelength.","Blue color scatters the most, hence the sky appears blue at noon."],"explanationHi":"सूर्योदय और सूर्यास्त के समय प्रकाश को वायुमंडल की मोटी परत से गुजरना पड़ता है। बाकी रंग बिखर जाते हैं, केवल लाल रंग हमारी आँखों तक पहुँच पाता है।","explanationEn":"During sunrise and sunset, light travels through a thicker layer of the atmosphere. Other colors scatter away, and only red reaches our eyes.","memoryTip":"लाल रंग ''डेंजर'' होता है, इसलिए दूर तक बिना बिखरे दिखता है।","memoryTipEn":"Red rays reach right through.","related":["Rayleigh Scattering","Wavelength","Blue Sky"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_pVmu4A1YSrJrzmMJr2bD', 'General Science', 'इन्द्रधनुष (Rainbow) में कितने रंग होते हैं?', 'How many colors are there in a rainbow?', 'सात (7)', 'Seven', 90, 0, '{"facts":["रंगों का क्रम VIBGYOR (बैंगनी, जामुनी, नीला, हरा, पीला, नारंगी, लाल) होता है।","यह प्रकाश के विक्षेपण (Dispersion), अपवर्तन और पूर्ण आंतरिक परावर्तन के कारण बनता है।"],"factsEn":["The order of colors is VIBGYOR (Violet, Indigo, Blue, Green, Yellow, Orange, Red).","It is formed due to dispersion, refraction, and total internal reflection of light."],"explanationHi":"बारिश के बाद पानी की बूंदें छोटे प्रिज्म (Prism) की तरह काम करती हैं, जो सफेद सूरज की रोशनी को सात रंगों में बांट देती हैं।","explanationEn":"After rain, water droplets act like tiny prisms, splitting white sunlight into seven colors.","memoryTip":"सप्ताह में सात दिन, इन्द्रधनुष में सात रंग।","memoryTipEn":"VIBGYOR spells the seven.","related":["Prism","Dispersion of Light","VIBGYOR"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('A9RWgkaHy7TIzGAwz_7Ue', 'General Science', 'भूस्थिर उपग्रह (Geostationary Satellite) की पृथ्वी से ऊँचाई कितनी होती है?', 'What is the height of a geostationary satellite from the Earth?', '36,000 किलोमीटर', '36,000 km', 92, 0, '{"facts":["इसका परिक्रमण काल पृथ्वी के घूर्णन (24 घंटे) के ठीक बराबर होता है।","यह हमेशा भूमध्य रेखा (Equator) के ऊपर स्थित होता है।"],"factsEn":["Its orbital period is exactly equal to Earth''s rotation (24 hours).","It is always positioned above the Equator."],"explanationHi":"पृथ्वी के साथ समान गति से घूमने के कारण, ये उपग्रह पृथ्वी से देखने पर आसमान में एक ही स्थान पर स्थिर दिखाई देते हैं। संचार के लिए इनका उपयोग किया जाता है।","explanationEn":"Because they rotate at the same speed as Earth, they appear stationary at a single spot in the sky. They are used for communications.","memoryTip":"36 का आंकड़ा बनाकर सैटेलाइट ऊपर (36000 किमी) टिक गया है।","memoryTipEn":"36k keeps the satellite still.","related":["Communication Satellites","Geosynchronous Orbit","Equator"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IPKAdiqQZTAmU1nRUstB8', 'General Science', 'चेचक के टीके (Smallpox Vaccine) की खोज किसने की?', 'Who discovered the smallpox vaccine?', 'एडवर्ड जेनर', 'Edward Jenner', 96, 0, '{"facts":["यह दुनिया की पहली सफल वैक्सीन थी (1796 में)।","जेनर ने देखा था कि जिन ग्वालों को ''काउपोक्स'' (Cowpox) हुआ था, उन्हें चेचक नहीं होता था।"],"factsEn":["It was the world''s first successful vaccine (in 1796).","Jenner observed that milkmaids who got ''cowpox'' did not catch smallpox."],"explanationHi":"इस खोज ने अंततः 1980 में दुनिया से चेचक (Smallpox) के पूर्ण उन्मूलन (Eradication) का मार्ग प्रशस्त किया।","explanationEn":"This discovery eventually led to the global eradication of smallpox in 1980.","memoryTip":"चेचक का इलाज ''जेनर'' ने जन-जन को दिया।","memoryTipEn":"Jenner generated the first vaccine.","related":["Smallpox Eradication","Vaccination","Cowpox"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4IJ1yFZxpjGerlN76ZIuz', 'General Science', 'रेबीज के टीके की खोज किसने की?', 'Who discovered the rabies vaccine?', 'लुई पाश्चर', 'Louis Pasteur', 95, 0, '{"facts":["रेबीज मुख्य रूप से संक्रमित जानवरों (जैसे कुत्तों) के काटने से फैलता है।","लुई पाश्चर ने दूध के ''पाश्चुरीकरण'' (Pasteurization) की प्रक्रिया भी खोजी थी।"],"factsEn":["Rabies is primarily spread through the bite of infected animals (like dogs).","Louis Pasteur also invented the process of milk ''Pasteurization''."],"explanationHi":"पाश्चर ने 1885 में पहली बार एक बच्चे पर रैबीज वैक्सीन का सफलतापूर्वक परीक्षण किया था, जिसे पागल कुत्ते ने काट लिया था।","explanationEn":"Pasteur successfully tested the rabies vaccine in 1885 on a child who had been bitten by a rabid dog.","memoryTip":"कुत्ते के काटने पर ''पाश्चर'' ने प्राण बचाए।","memoryTipEn":"Pasteur protected against the pup''s bite.","related":["Rabies","Pasteurization","Microbiology"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Qieh0zNCKeH8wF5gVHifp', 'General Science', 'दूध से दही किस जीवाणु (Bacterium) के कारण बनता है?', 'Which bacterium causes milk to turn into curd?', 'लैक्टोबैसिलस', 'Lactobacillus', 96, 0, '{"facts":["यह जीवाणु दूध में मौजूद लैक्टोज (Lactose) शर्करा को लैक्टिक एसिड (Lactic acid) में बदल देता है।","लैक्टिक एसिड के कारण ही दही का स्वाद खट्टा होता है।"],"factsEn":["This bacterium converts the lactose sugar present in milk into lactic acid.","It is the lactic acid that gives curd its sour taste."],"explanationHi":"यह प्रक्रिया ''किण्वन'' (Fermentation) कहलाती है। यह जीवाणु हमारे पाचन तंत्र (Gut health) के लिए भी बहुत लाभदायक होता है।","explanationEn":"This process is called ''Fermentation''. This bacterium is also highly beneficial for our digestive system (gut health).","memoryTip":"दूध की मिठास (लैक्टोज) को दही (लैक्टोबैसिलस) बनाता है।","memoryTipEn":"Lacto relates to milk.","related":["Lactic Acid","Fermentation","Probiotics"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wyokCcKA7WnJJAoS4geSv', 'General Science', 'पराश्रव्य तरंगों (Ultrasonic waves) की आवृति कितनी होती है?', 'What is the frequency of ultrasonic waves?', '20,000 हर्ट्ज़ (Hz) से अधिक', 'More than 20,000 Hz', 92, 0, '{"facts":["मनुष्य के कान 20 Hz से 20,000 Hz तक की ही ध्वनि सुन सकते हैं।","चमगादड़ और डॉल्फिन इन तरंगों को पैदा भी कर सकते हैं और सुन भी सकते हैं।"],"factsEn":["Human ears can only hear sounds between 20 Hz and 20,000 Hz.","Bats and dolphins can both produce and hear these waves."],"explanationHi":"चिकित्सा क्षेत्र में सोनोग्राफी (Ultrasound) और समुद्र की गहराई मापने के लिए ''सोनार'' (SONAR) में इन तरंगों का प्रयोग होता है।","explanationEn":"These waves are used in the medical field for sonography (Ultrasound) and in SONAR to measure ocean depths.","memoryTip":"परा (पार) का मतलब है 20 हज़ार की सीमा के पार।","memoryTipEn":"Ultra means beyond human limits.","related":["Infrasonic Waves","SONAR","Echolocation"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Qsfk_8GdfWfrbLMdYMBj0', 'General Science', 'परमाणु बम किस सिद्धांत पर कार्य करता है?', 'On which principle does an atomic bomb work?', 'नाभिकीय विखंडन (Nuclear Fission)', 'Nuclear Fission', 95, 0, '{"facts":["इस प्रक्रिया में एक भारी नाभिक (जैसे यूरेनियम या प्लूटोनियम) टूटकर हल्के नाभिकों में बदल जाता है और भारी ऊर्जा निकलती है।","हाइड्रोजन बम (H-Bomb) नाभिकीय संलयन (Nuclear Fusion) पर काम करता है।"],"factsEn":["In this process, a heavy nucleus (like Uranium or Plutonium) splits into lighter nuclei, releasing massive energy.","A Hydrogen bomb works on Nuclear Fusion."],"explanationHi":"नाभिकीय रिएक्टरों में भी इसी सिद्धांत (नियंत्रित विखंडन) का उपयोग बिजली बनाने के लिए किया जाता है।","explanationEn":"Nuclear reactors also use this principle (controlled fission) to generate electricity.","memoryTip":"परमाणु ''खंड-खंड'' (विखंडन) होकर तबाह कर देता है।","memoryTipEn":"Fission causes the splits.","related":["Nuclear Fusion","Uranium-235","Manhattan Project"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('OrEMU8uCs3WjsEOTdLVRF', 'General Science', 'विद्युत् धारा की इकाई कौनसी है?', 'What is the unit of electric current?', 'एम्पीयर', 'Ampere', 94, 0, '{"facts":["इसे प्रतीक ''A'' द्वारा दर्शाया जाता है।","विद्युत धारा को मापने वाले उपकरण को एमीटर (Ammeter) कहा जाता है।"],"factsEn":["It is denoted by the symbol ''A''.","The instrument used to measure electric current is called an Ammeter."],"explanationHi":"यह उन सात मूलभूत SI इकाइयों में से एक है, जो किसी परिपथ (circuit) में इलेक्ट्रॉनों के प्रवाह की दर को मापती है।","explanationEn":"It is one of the seven fundamental SI units, measuring the rate of flow of electrons in a circuit.","memoryTip":"करंट लगे तो ''एम्प'' (Ampere) जैसी आवाज आती है।","memoryTipEn":"Amp up the current.","related":["Ammeter","Volt (Voltage)","Ohm (Resistance)"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-a3z8og_D38tjz5l8ZSUr', 'General Science', 'हृदय की धड़कन को नियंत्रित करने के लिए कौनसा खनिज (Mineral) आवश्यक है?', 'Which mineral is necessary to control the heartbeat?', 'पोटेशियम', 'Potassium', 90, 0, '{"facts":["केले, आलू और पालक में पोटेशियम भरपूर मात्रा में पाया जाता है।","यह एक महत्वपूर्ण इलेक्ट्रोलाइट (Electrolyte) है जो तंत्रिका संकेतों (nerve signals) को संचालित करता है।"],"factsEn":["Bananas, potatoes, and spinach are rich in potassium.","It is a crucial electrolyte that conducts nerve signals."],"explanationHi":"रक्त में पोटेशियम का स्तर कम या ज्यादा होने से हृदय की धड़कन अनियमित (Arrhythmia) हो सकती है, जो जानलेवा भी हो सकता है।","explanationEn":"Low or high levels of potassium in the blood can cause an irregular heartbeat (Arrhythmia), which can be fatal.","memoryTip":"हार्ट को ''पोट'' (Potassium) में सुरक्षित रखें।","memoryTipEn":"Potassium protects the pulse.","related":["Arrhythmia","Sodium-Potassium Pump","Electrolytes"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('maz9urB9MJiRHDkbcvrr5', 'General Science', 'पेनिसिलिन (Penicillin) की खोज किसने की?', 'Who discovered Penicillin?', 'अलेक्जेंडर फ्लेमिंग', 'Alexander Fleming', 96, 0, '{"facts":["यह दुनिया का पहला एंटीबायोटिक (Antiobiotic) था।","इसे 1928 में ''पेनिसिलियम नोटेटम'' (Penicillium notatum) नामक कवक (Fungus/Mold) से खोजा गया था।"],"factsEn":["It was the world''s first antibiotic.","It was discovered in 1928 from a fungus (mold) called ''Penicillium notatum''."],"explanationHi":"इस खोज ने चिकित्सा विज्ञान में क्रांति ला दी और द्वितीय विश्व युद्ध के दौरान लाखों घायल सैनिकों की जान बचाई।","explanationEn":"This discovery revolutionized medicine and saved millions of wounded soldiers'' lives during World War II.","memoryTip":"फ्लेमिंग ने बीमारी को ''पेन'' (Penicillin) से मार दिया।","memoryTipEn":"Fleming found the fungus cure.","related":["Antibiotics","Penicillium notatum","Bacterial Infections"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mO9aF7MLiDRg7PqE44GOg', 'General Science', 'मलेरिया की दवा ''कुनैन'' (Quinine) किस पौधे से प्राप्त होती है?', 'The malaria drug ''Quinine'' is obtained from which plant?', 'सिनकोना (Cinchona)', 'Cinchona', 95, 0, '{"facts":["कुनैन को सिनकोना पेड़ की छाल (Bark) से निकाला जाता है।","मलेरिया मादा एनाफ्लीज मच्छर (Female Anopheles mosquito) के काटने से फैलता है।"],"factsEn":["Quinine is extracted from the bark of the Cinchona tree.","Malaria is spread by the bite of the female Anopheles mosquito."],"explanationHi":"सदियों तक यह मलेरिया का एकमात्र प्रभावी उपचार था, हालांकि आज कई कृत्रिम दवाएं भी उपलब्ध हैं।","explanationEn":"For centuries, this was the only effective treatment for malaria, though many synthetic drugs are available today.","memoryTip":"''मलेरिया'' को ''सिन'' (पाप) मानकर ''सिनकोना'' से मिटाया।","memoryTipEn":"Cinchona cures the mosquito''s curse.","related":["Malaria","Plasmodium","Female Anopheles Mosquito"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WyL_jjRL7zfZygWYuQ8We', 'General Science', 'संसार का सबसे बड़ा फूल कौनसा है?', 'Which is the largest flower in the world?', 'रफ्लेसिया (Rafflesia)', 'Rafflesia', 91, 0, '{"facts":["यह मुख्य रूप से इंडोनेशिया और मलेशिया के जंगलों में पाया जाता है।","इस फूल का वजन 10 किलोग्राम तक हो सकता है।"],"factsEn":["It is mainly found in the forests of Indonesia and Malaysia.","This flower can weigh up to 10 kilograms."],"explanationHi":"यह एक परजीवी पौधा (Parasitic plant) है। इसमें सड़े हुए मांस जैसी भयानक बदबू आती है, जो कीटों को आकर्षित करती है।","explanationEn":"It is a parasitic plant. It emits a terrible odor like rotting meat, which attracts insects for pollination.","memoryTip":"''रफ'' (Rafflesia) है ये फूल, बहुत बदबू देता है।","memoryTipEn":"Rafflesia is a massive, rough-smelling bloom.","related":["Parasitic Plant","Corpse Flower","Wolffia (Smallest Flower)"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('i_CFnnNxGc8BWrw1J4ixO', 'General Science', 'सबसे बड़ा जीवित पक्षी कौनसा है?', 'Which is the largest living bird?', 'शुतुरमुर्ग (Ostrich)', 'Ostrich', 89, 0, '{"facts":["यह उड़ नहीं सकता (Flightless bird), लेकिन 70 किमी/घंटा की गति से दौड़ सकता है।","शुतुरमुर्ग का अंडा दुनिया की सबसे बड़ी एकल कोशिका (Single cell) है।"],"factsEn":["It is a flightless bird but can run at speeds of 70 km/h.","An ostrich egg is the largest single cell in the world."],"explanationHi":"यह मुख्य रूप से अफ्रीकी महाद्वीप के शुष्क मैदानों में पाया जाता है और इसकी आंखें सभी जमीन वाले जानवरों में सबसे बड़ी होती हैं।","explanationEn":"It is primarily found in the dry plains of the African continent and has the largest eyes of any land animal.","memoryTip":"सबसे बड़े पक्षी के पैर ''शुतुरमुर्ग'' की तरह तेज़ होते हैं।","memoryTipEn":"Ostriches outrun the rest.","related":["Flightless Birds","Largest Cell","Emu"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wt3JmnLhdUnDyjPhcaMjo', 'General Science', 'संसार में सबसे छोटा पक्षी कौनसा है?', 'Which is the smallest bird in the world?', 'हमिंग बर्ड (Hummingbird)', 'Hummingbird (Specifically Bee Hummingbird)', 89, 0, '{"facts":["हमिंग बर्ड दुनिया का एकमात्र पक्षी है जो पीछे की ओर (Backwards) उड़ सकता है।","इसके पंख इतनी तेजी से फड़फड़ाते हैं कि उनसे गुनगुनाने (Humming) की आवाज आती है।"],"factsEn":["The hummingbird is the only bird in the world that can fly backwards.","Its wings flap so fast that they produce a humming sound."],"explanationHi":"क्यूबा का ''बी हमिंगबर्ड'' सबसे छोटा है, जिसका वजन एक सिक्के (coin) से भी कम होता है।","explanationEn":"The ''Bee Hummingbird'' of Cuba is the absolute smallest, weighing less than a coin.","memoryTip":"इतना छोटा कि ''हम'' (Hum) की आवाज़ करता है।","memoryTipEn":"Hummingbird hovers like a tiny helicopter.","related":["Ostrich (Largest Bird)","Backward Flight","Nectar"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WaUERUY2SJwaiHT4HQNu4', 'General Knowledge', 'मनुष्य ने सबसे पहले किस जंतु को पालतू बनाया?', 'Which animal was first domesticated by humans?', 'कुत्ता', 'Dog', 92, 0, '{"facts":["कुत्तों को मध्य पाषाण काल (Mesolithic Age) में पालतू बनाया गया था।","मनुष्यों ने शिकार करने और सुरक्षा के लिए सबसे पहले भेड़ियों के वंशजों को पालना शुरू किया।"],"factsEn":["Dogs were domesticated during the Mesolithic Age.","Humans first started domesticating wolf descendants for hunting and security."],"explanationHi":"यह मनुष्य और जानवरों के बीच पहला सहजीवी संबंध था, जिसने शुरुआती मानव बस्तियों को सुरक्षित बनाने में मदद की।","explanationEn":"This was the first symbiotic relationship between humans and animals, which helped secure early human settlements.","memoryTip":"सबसे ''वफादार'' जानवर कुत्ता ही इंसान का पहला दोस्त बना।","memoryTipEn":"Dogs have been man''s best friend since the beginning.","related":["Mesolithic Age","Domestication","Agriculture (Neolithic Age)"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('An5JyRGDAflOragBVMVnV', 'General Science', 'अंतरिक्ष यात्री को बाह्य आकाश कैसा दिखाई देता है?', 'How does the outer sky appear to an astronaut?', 'काला', 'Black', 93, 0, '{"facts":["पृथ्वी का आकाश वायुमंडल के कारण नीला दिखता है (नीले प्रकाश का प्रकीर्णन/Scattering)।","अंतरिक्ष में हवा या गैसें नहीं होतीं, इसलिए प्रकाश बिखरता नहीं है।"],"factsEn":["Earth''s sky looks blue due to the atmosphere (scattering of blue light).","There is no air or gases in space, so light does not scatter."],"explanationHi":"किसी माध्यम की अनुपस्थिति के कारण, अंतरिक्ष पूरी तरह से अंधकारमय (काला) दिखाई देता है, जहाँ सूर्य और तारे स्पष्ट चमकते हैं।","explanationEn":"Due to the absence of a medium, space appears completely dark (black), where the sun and stars shine clearly.","memoryTip":"बिना हवा के रंग नहीं बिखरते, सब कुछ ''काला'' हो जाता है।","memoryTipEn":"No air to scatter light equals pitch black.","related":["Scattering of Light","Vacuum","Atmosphere"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dhUwXlLfJ7eUlWxeemtGb', 'General Knowledge', 'ATM का पूर्ण विस्तार क्या होगा?', 'What is the full form of ATM?', 'ऑटोमेटेड टेलर मशीन (Automated Teller Machine)', 'Automated Teller Machine', 94, 0, '{"facts":["दुनिया का पहला ATM 1967 में लंदन में (बार्कलेज बैंक द्वारा) स्थापित किया गया था।","भारत का पहला ATM 1987 में मुंबई में HSBC बैंक द्वारा लगाया गया था।"],"factsEn":["The world''s first ATM was installed in London in 1967 (by Barclays Bank).","India''s first ATM was installed in Mumbai in 1987 by HSBC Bank."],"explanationHi":"यह एक इलेक्ट्रो-मैकेनिकल मशीन है जो ग्राहकों को बैंक शाखा में जाए बिना वित्तीय लेनदेन (जैसे नकदी निकालना) करने की सुविधा देती है।","explanationEn":"It is an electro-mechanical machine that allows customers to perform financial transactions (like withdrawing cash) without visiting a bank branch.","memoryTip":"ATM में मशीन ''ऑटोमैटिक'' टेलर (कैशियर) का काम करती है।","memoryTipEn":"Automated Teller serves your cash.","related":["PIN (Personal Identification Number)","Banking","John Shepherd-Barron (Inventor)"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('A9NGcjGkLHTYX6rtgWdG2', 'General Knowledge', 'संसद का संयुक्त अधिवेशन (Joint Session) कौन बुलाता है?', 'Who calls the joint session of the Parliament?', 'राष्ट्रपति', 'President', 95, 0, '{"facts":["संविधान के अनुच्छेद 108 के तहत राष्ट्रपति इसे बुला (Summon) सकते हैं।","इस संयुक्त अधिवेशन की अध्यक्षता हमेशा ''लोकसभा अध्यक्ष'' (Speaker) करता है।"],"factsEn":["Under Article 108 of the Constitution, the President can summon it.","The ''Speaker of the Lok Sabha'' always presides over this joint session."],"explanationHi":"जब किसी सामान्य विधेयक (Ordinary Bill) पर लोकसभा और राज्यसभा के बीच असहमति (Deadlock) हो जाती है, तब यह अधिवेशन बुलाया जाता है।","explanationEn":"This session is called when there is a deadlock between the Lok Sabha and the Rajya Sabha over an ordinary bill.","memoryTip":"बुलाता राष्ट्रपति है, लेकिन कुर्सी पर स्पीकर बैठता है।","memoryTipEn":"President summons, Speaker presides.","related":["Article 108","Lok Sabha Speaker","Parliament Deadlock"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3rqpmCP54ewkIsAVzQeUj', 'General Knowledge', 'एलबीडबल्यू (LBW) शब्द किस खेल से है?', 'The term LBW is related to which sport?', 'क्रिकेट', 'Cricket', 91, 0, '{"facts":["LBW का पूर्ण रूप ''Leg Before Wicket'' है।","यह क्रिकेट में बल्लेबाज को आउट (Dismiss) करने के कई तरीकों में से एक है।"],"factsEn":["The full form of LBW is ''Leg Before Wicket''.","It is one of the several ways a batsman can be dismissed in cricket."],"explanationHi":"यदि गेंद सीधे विकेट से टकराने वाली हो और बल्लेबाज के पैर (या शरीर के किसी अंग) से रुक जाए, तो अंपायर उसे LBW आउट दे सकता है।","explanationEn":"If the ball is on a trajectory to hit the wickets but is obstructed by the batsman''s leg (or body part), the umpire can rule them out LBW.","memoryTip":"विकेट से पहले ''लेग'' (पैर) आ गया = LBW।","memoryTipEn":"Leg blocking the wicket gets you out.","related":["Cricket Dismissals","Stumped","DRS (Decision Review System)"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TcOJY2R_CSfFkhb1XQb_t', 'General Science', 'वायुमंडल की कौन सी परत हमें सूर्य से आने वाली अल्ट्रावायलेट किरणों (UV Rays) से बचाती है?', 'Which layer of the atmosphere protects us from the ultraviolet rays of the sun?', 'ओजोन (Ozone)', 'Ozone', 96, 0, '{"facts":["ओजोन गैस का रासायनिक सूत्र O3 (ऑक्सीजन के 3 परमाणु) है।","ओजोन परत वायुमंडल के ''समताप मंडल'' (Stratosphere) में पाई जाती है।"],"factsEn":["The chemical formula of ozone gas is O3 (3 oxygen atoms).","The ozone layer is found in the ''Stratosphere'' of the atmosphere."],"explanationHi":"यह परत हानिकारक यूवी किरणों को अवशोषित कर लेती है, जो इंसानों में त्वचा कैंसर (Skin cancer) और मोतियाबिंद का कारण बन सकती हैं। क्लोरोफ्लोरोकार्बन (CFCs) इस परत को नुकसान पहुंचाते हैं।","explanationEn":"This layer absorbs harmful UV rays, which can cause skin cancer and cataracts in humans. Chlorofluorocarbons (CFCs) damage this layer.","memoryTip":"सूर्य की ''ओह'' करने वाली किरणों से ''ओजोन'' बचाती है।","memoryTipEn":"Ozone is Earth''s sunblock.","related":["Stratosphere","Chlorofluorocarbons (CFCs)","Montreal Protocol"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kj3O8lPugo6l-oAFYzQ-c', 'General Knowledge', 'ख्वाजा मोईनुद्दीन चिश्ती की दरगाह कहाँ है?', 'Where is the shrine of Khwaja Moinuddin Chishti?', 'अजमेर', 'Ajmer', 93, 0, '{"facts":["वे 12वीं शताब्दी के एक प्रसिद्ध सूफी संत थे।","इन्होंने भारतीय उपमहाद्वीप में ''चिश्ती संप्रदाय'' (Chishti Order) की स्थापना की थी।"],"factsEn":["He was a renowned Sufi saint of the 12th century.","He founded the ''Chishti Order'' in the Indian subcontinent."],"explanationHi":"अजमेर शरीफ की दरगाह हिंदू और मुस्लिम दोनों धर्मों के लोगों के लिए आस्था का एक बड़ा केंद्र है। यहाँ लगने वाले ''उर्स'' (Urs) मेले में लाखों लोग आते हैं।","explanationEn":"The Ajmer Sharif Dargah is a major centre of faith for both Hindus and Muslims. Millions attend the annual ''Urs'' festival held here.","memoryTip":"ख्वाजा का दरबार ''अजमेर'' में सजता है।","memoryTipEn":"Ajmer embraces the Sufi saint.","related":["Sufism","Urs Festival","Chishti Order"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('iL3uiY_Di7i3QcfhmssY0', 'General Knowledge', 'सम्राट अशोक ने किस युद्ध के बाद बोद्ध धर्म ग्रहण कर लिया था?', 'After which war did Emperor Ashoka embrace Buddhism?', 'कलिंग युद्ध', 'Kalinga War', 96, 0, '{"facts":["यह युद्ध 261 ईसा पूर्व में लड़ा गया था।","कलिंग आधुनिक ''ओडिशा'' (Odisha) राज्य का प्राचीन नाम है।"],"factsEn":["This war was fought in 261 BCE.","Kalinga is the ancient name of the modern state of ''Odisha''."],"explanationHi":"इस युद्ध में हुए भारी रक्तपात और विनाश को देखकर अशोक का हृदय परिवर्तन हो गया। उन्होंने युद्ध (Bherighosha) की नीति छोड़कर शांति और धर्म (Dhammaghosha) की नीति अपना ली।","explanationEn":"Witnessing the massive bloodshed and destruction, Ashoka had a change of heart. He abandoned war (Bherighosha) and adopted peace and righteousness (Dhammaghosha).","memoryTip":"''कलिंग'' में खून देखकर अशोक ''शांति'' के मार्ग पर चल पड़े।","memoryTipEn":"Kalinga killed Ashoka''s thirst for war.","related":["Upagupta (Monk who initiated Ashoka)","Mauryan Empire","Dhamma"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vHL4YWeIvFSST9EyXCTNZ', 'General Knowledge', 'भारत का केन्द्रीय बैंक कौनसा है?', 'Which is the Central Bank of India?', 'भारतीय रिज़र्व बैंक (RBI)', 'Reserve Bank of India (RBI)', 95, 0, '{"facts":["इसकी स्थापना 1 अप्रैल 1935 को हिल्टन-यंग कमीशन की सिफारिशों पर हुई थी।","1949 में इसका राष्ट्रीयकरण (Nationalization) किया गया था।"],"factsEn":["It was established on April 1, 1935, on the recommendations of the Hilton-Young Commission.","It was nationalized in 1949."],"explanationHi":"यह भारत में मुद्रा (Currency) जारी करता है और बैंकिंग प्रणाली (Monetary Policy) को नियंत्रित करता है। इसे ''बैंकों का बैंक'' भी कहा जाता है।","explanationEn":"It issues currency and regulates the banking system (Monetary Policy) in India. It is also known as the ''Bank of Banks''.","memoryTip":"सभी बैंकों का ''रिज़र्व'' (बॉस) RBI है।","memoryTipEn":"RBI Regulates the Banks of India.","related":["Monetary Policy","Shaktikanta Das","Hilton-Young Commission"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gs_2rXyCTObN1qOzWszdT', 'General Knowledge', 'सालारजंग म्यूजियम कहाँ है?', 'Where is the Salar Jung Museum located?', 'हैदराबाद', 'Hyderabad', 88, 0, '{"facts":["यह भारत के तीन राष्ट्रीय संग्रहालयों में से एक है।","यह मूसी नदी के दक्षिणी तट पर स्थित है।"],"factsEn":["It is one of the three National Museums of India.","It is located on the southern bank of the Musi River."],"explanationHi":"यह दुनिया के सबसे बड़े एक-व्यक्ति संग्रह (One-man collections) कलाकृतियों वाले संग्रहालयों में से एक है, जिसे नवाब मीर यूसुफ अली खान (सालार जंग III) ने एकत्र किया था।","explanationEn":"It is one of the largest one-man collections of antiques in the world, sourced by Nawab Mir Yousuf Ali Khan (Salar Jung III).","memoryTip":"हैदराबाद की ''सालार'' में बहुत सी पुरानी चीजें हैं।","memoryTipEn":"Salar Jung showcases art in Hyderabad.","related":["Hyderabad","Musi River","National Museums"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SL8kxlu8UrfghoY16WWXg', 'General Knowledge', 'भारत में सबसे लम्बे समय तक मुख्यमंत्री कौन रहा है (पीडीएफ स्रोत अनुसार)?', 'Who has been the Chief Minister for the longest time in India (as per PDF source)?', 'ज्योति बसु (पश्चिम बंगाल)', 'Jyoti Basu (West Bengal)', 85, 0, '{"facts":["महत्वपूर्ण अद्यतन: वर्तमान में सिक्किम के ''पवन कुमार चामलिंग'' (24 वर्ष से अधिक) के नाम भारत में सबसे लंबे समय तक मुख्यमंत्री रहने का रिकॉर्ड है। उनके बाद नवीन पटनायक (सिक्किम) का स्थान आता है।","ज्योति बसु मार्क्सवादी कम्युनिस्ट पार्टी (CPI-M) के नेता थे और 23 साल तक सीएम रहे।"],"factsEn":["Important Update: Currently, ''Pawan Kumar Chamling'' of Sikkim holds the record (over 24 years). He is followed by Naveen Patnaik.","Jyoti Basu was a CPI(M) leader and served as CM for 23 years."],"explanationHi":"परीक्षाओं में नवीनतम आंकड़ों (पवन कुमार चामलिंग/नवीन पटनायक) का ध्यान रखें। पीडीएफ के समय ज्योति बसु का रिकॉर्ड था।","explanationEn":"Keep the latest data in mind for exams (Pawan Kumar Chamling/Naveen Patnaik). At the time of the PDF, Jyoti Basu held the record.","memoryTip":"अब ''पवन'' (चामलिंग) ने बसु का रिकॉर्ड उड़ा दिया है।","memoryTipEn":"Chamling holds the current crown, Basu was the old record.","related":["Pawan Kumar Chamling","Naveen Patnaik","Longest serving CMs"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vtzZm0VWuMauTfSd9ck1Z', 'General Knowledge', 'संसार की सबसे लम्बी नदी कौनसी है?', 'Which is the longest river in the world?', 'नील (Nile)', 'Nile', 94, 0, '{"facts":["यह नदी अफ्रीका महाद्वीप में बहती है और भूमध्य सागर (Mediterranean Sea) में गिरती है।","मिस्र (Egypt) को ''नील नदी का वरदान'' कहा जाता है।"],"factsEn":["This river flows in the African continent and empties into the Mediterranean Sea.","Egypt is called the ''Gift of the Nile''."],"explanationHi":"यह लगभग 6,650 किमी लंबी है। ''अमेज़ॅन'' (Amazon) पानी की मात्रा (Volume) के हिसाब से दुनिया की सबसे बड़ी नदी है, लेकिन नील लंबाई में सबसे आगे है।","explanationEn":"It is about 6,650 km long. The ''Amazon'' is the largest river by water volume, but the Nile is the longest.","memoryTip":"अफ्रीका की ''नीली'' (Nile) रेखा सबसे लंबी है।","memoryTipEn":"Nile is a long blue line in Africa.","related":["Amazon River (Largest by volume)","Egypt","Lake Victoria"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('T6m7uvUSEJrmm0ppgnUhD', 'General Science', 'किस तापमान पर सेल्सियस और फारेनहाइट तापमान बराबर होता है?', 'At what temperature are the Celsius and Fahrenheit scales equal?', '-40 डिग्री', '-40 degrees', 95, 0, '{"facts":["तापमान बदलने का सूत्र है: F = (C × 9/5) + 32","यदि आप दोनों जगह -40 रखते हैं, तो समीकरण संतुलित हो जाता है (-40°C = -40°F)।"],"factsEn":["The temperature conversion formula is: F = (C × 9/5) + 32","If you plug in -40 on both sides, the equation balances out (-40°C = -40°F)."],"explanationHi":"यह विज्ञान का एक प्रसिद्ध तथ्य है जहाँ दोनों अलग-अलग पैमाने एक ही बिंदु पर आकर मिलते हैं।","explanationEn":"This is a famous scientific fact where two distinct scales intersect at exactly the same numerical value.","memoryTip":"माइनस चालीस (-40) पर दोनों थर्मामीटर ''भाई-भाई'' बन जाते हैं।","memoryTipEn":"Minus 40 matches them both.","related":["Celsius","Fahrenheit","Kelvin Scale"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2sYPPOqtwy0M8aPG1S8T5', 'General Science', 'कांसा (Bronze) किसकी मिश्रधातु है?', 'Bronze is an alloy of which metals?', 'तांबा और टिन', 'Copper and Tin', 93, 0, '{"facts":["सिंधु घाटी सभ्यता एक ''कांस्य युगीन'' (Bronze Age) सभ्यता थी।","पीतल (Brass) तांबे और जस्ते (Zinc) का मिश्रण होता है।"],"factsEn":["The Indus Valley Civilization was a ''Bronze Age'' civilization.","Brass is a mixture of Copper and Zinc."],"explanationHi":"टिन मिलाने से तांबा अधिक कठोर और टिकाऊ हो जाता है, जिससे मूर्तियां और मेडल बनाए जाते हैं।","explanationEn":"Adding tin makes copper harder and more durable, which is why it is used to make statues and medals.","memoryTip":"कांस्य पदक ''टन-टन'' (टिन) बजता है।","memoryTipEn":"Bronze blends Tin and Copper.","related":["Brass (Copper + Zinc)","Bronze Age","Alloys"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uhjO3BZuETJM8uuzOhGC8', 'General Knowledge', 'दलीप ट्राफी (Duleep Trophy) का सम्बन्ध किस खेल से है?', 'Duleep Trophy is associated with which sport?', 'क्रिकेट', 'Cricket', 90, 0, '{"facts":["यह भारत की एक घरेलू प्रथम श्रेणी (First-class) क्रिकेट प्रतियोगिता है।","इसका नाम कुमार श्री दलीपसिंहजी (नवानगर) के नाम पर रखा गया है।"],"factsEn":["It is a domestic first-class cricket competition in India.","It is named after Kumar Shri Duleepsinhji of Nawanagar."],"explanationHi":"रणजी ट्रॉफी के विपरीत, जो राज्य टीमों के बीच खेली जाती है, दलीप ट्रॉफी पारंपरिक रूप से भौगोलिक क्षेत्रों (Zones) की टीमों के बीच खेली जाती है।","explanationEn":"Unlike the Ranji Trophy which is contested by state teams, the Duleep Trophy is traditionally contested by teams representing geographical zones.","memoryTip":"क्रिकेट के ''दिलीप'' ने ट्रॉफी जीती।","memoryTipEn":"Duleep drives domestic cricket.","related":["Ranji Trophy","Irani Cup","First-class Cricket"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SK5FKoQbQQqOzStHJh0vq', 'General Science', 'LPG का पूर्ण विस्तार क्या होगा?', 'What is the full form of LPG?', 'लिक्विफाइड पेट्रोलियम गैस (Liquefied Petroleum Gas)', 'Liquefied Petroleum Gas', 94, 0, '{"facts":["इसमें मुख्य रूप से ब्यूटेन (Butane) और प्रोपेन (Propane) गैसें होती हैं।","रिसाव (Leakage) का पता लगाने के लिए इसमें तीखी गंध वाला ''इथाइल मर्केप्टन'' मिलाया जाता है।"],"factsEn":["It primarily consists of Butane and Propane gases.","To detect leaks, a strong-smelling compound ''Ethyl Mercaptan'' is added."],"explanationHi":"यह गैसों का मिश्रण है जिसे दबाव डालकर तरल (Liquefied) रूप में सिलेंडरों में भरा जाता है, जिसका उपयोग घरों में खाना पकाने के लिए होता है।","explanationEn":"It is a mixture of gases pressurized into a liquid state in cylinders, commonly used as a cooking fuel in households.","memoryTip":"Liquid (तरल) की हुई Petroleum (पेट्रोलियम) Gas (गैस) = LPG।","memoryTipEn":"Liquefied gas for cooking.","related":["Butane","Propane","CNG (Compressed Natural Gas)"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rdtSGHkieNyZHIqXrrSWq', 'General Knowledge', '''गीता रहस्य'' पुस्तक किसने लिखी?', 'Who wrote the book ''Gita Rahasya''?', 'बाल गंगाधर तिलक', 'Bal Gangadhar Tilak', 93, 0, '{"facts":["तिलक ने इस पुस्तक को 1915 में मांडले जेल (बर्मा/म्यांमार) में अपने कारावास के दौरान लिखा था।","यह श्रीमद्भगवद्गीता का एक दार्शनिक विश्लेषण है।"],"factsEn":["Tilak wrote this book during his imprisonment in Mandalay Jail (Burma/Myanmar) in 1915.","It is a philosophical analysis of the Shrimad Bhagavad Gita."],"explanationHi":"तिलक ने इस पुस्तक के माध्यम से यह संदेश दिया कि गीता केवल संन्यास (त्याग) नहीं, बल्कि कर्म योग (निःस्वार्थ कार्य) का उपदेश देती है।","explanationEn":"Through this book, Tilak conveyed that the Gita does not merely teach renunciation, but rather Karma Yoga (selfless action).","memoryTip":"जेल में ''तिलक'' लगाकर तिलक ने ''गीता का रहस्य'' खोजा।","memoryTipEn":"Tilak unlocked the Gita''s secrets in jail.","related":["Lokmanya Tilak","Mandalay Jail","Karma Yoga"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('v9zlKpgiFMgPsQD8Id_Ua', 'General Knowledge', 'राज्यसभा के कितने सदस्यों का चुनाव हर 2 वर्ष बाद होता है?', 'How many members of the Rajya Sabha are elected every 2 years?', 'एक-तिहाई', 'One-third', 95, 0, '{"facts":["राज्यसभा एक स्थायी सदन है, जिसे कभी पूरी तरह से भंग (dissolve) नहीं किया जा सकता।","प्रत्येक सदस्य का कार्यकाल 6 वर्ष का होता है।"],"factsEn":["Rajya Sabha is a permanent house, which can never be completely dissolved.","Each member has a term of 6 years."],"explanationHi":"सदस्यों की सेवानिवृत्ति की यह व्यवस्था सुनिश्चित करती है कि सदन हमेशा काम करता रहे और कभी भी खाली न हो।","explanationEn":"This staggered retirement system ensures that the house remains continuous and is never completely empty.","memoryTip":"हर 2 साल में एक-तिहाई (1/3) सदस्य रिटायर होकर घर जाते हैं।","memoryTipEn":"One-third leave every two years.","related":["Parliament of India","Upper House","Term of Rajya Sabha members"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('S4WQCKAoPci-4rxA-bKH6', 'General Knowledge', 'अमेरिकी राष्ट्रपति का कार्यकाल कितने वर्ष होता है?', 'What is the tenure of an American President?', 'चार वर्ष', 'Four years', 90, 0, '{"facts":["अमेरिका में एक व्यक्ति अधिकतम 2 बार (यानी 8 वर्ष) राष्ट्रपति बन सकता है।","22वें संविधान संशोधन (1951) द्वारा यह सीमा तय की गई थी।"],"factsEn":["In the US, a person can be elected President for a maximum of 2 terms (i.e., 8 years).","This limit was set by the 22nd Constitutional Amendment (1951)."],"explanationHi":"भारत के विपरीत जहाँ राष्ट्रपति 5 वर्ष के लिए चुने जाते हैं और कितनी भी बार फिर से चुने जा सकते हैं, अमेरिका में यह नियम सख्त है।","explanationEn":"Unlike India where the President is elected for 5 years and can be re-elected any number of times, the US has strict term limits.","memoryTip":"अमेरिका में हर चार साल में नया चुनाव ''चार'' चाँद लगाता है।","memoryTipEn":"Four years to lead the free world.","related":["22nd Amendment (US)","US Constitution","President of India (5 years)"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ARXrV0ET5af4BcQ-PzSlu', 'General Knowledge', 'अयोध्या किस नदी के किनारे है?', 'Ayodhya is situated on the banks of which river?', 'सरयू', 'Sarayu', 94, 0, '{"facts":["अयोध्या भगवान राम की जन्मस्थली के रूप में दुनिया भर में प्रसिद्ध है।","सरयू नदी को कुछ स्थानों पर ''घाघरा'' नदी के नाम से भी जाना जाता है।"],"factsEn":["Ayodhya is world-famous as the birthplace of Lord Rama.","The Sarayu river is also known as the ''Ghaghara'' river in some places."],"explanationHi":"रामायण के अनुसार, भगवान राम के जीवन और अयोध्या शहर के विकास में सरयू नदी का बहुत गहरा और पवित्र महत्व है।","explanationEn":"According to the Ramayana, the Sarayu river holds deep sacred significance in the life of Lord Rama and the city of Ayodhya.","memoryTip":"राम जी ''सरयू'' के किनारे अयोध्या में बसते हैं।","memoryTipEn":"Sarayu surrounds sacred Ayodhya.","related":["Lord Rama","Uttar Pradesh","Ghaghara River"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DNyWqxIj736rXtN1kwF9q', 'General Knowledge', 'जयपुर की स्थापना किसने की थी?', 'Who founded Jaipur?', 'आमेर के राजा सवाई जयसिंह ने', 'King Sawai Jai Singh of Amer', 92, 0, '{"facts":["इसकी स्थापना 1727 में की गई थी।","जयपुर को भारत का ''गुलाबी शहर'' (Pink City) कहा जाता है।"],"factsEn":["It was founded in 1727.","Jaipur is known as the ''Pink City'' of India."],"explanationHi":"सवाई जयसिंह द्वितीय एक महान खगोलशास्त्री (astronomer) भी थे जिन्होंने जयपुर सहित कई शहरों में ''जंतर मंतर'' वेधशालाओं का निर्माण करवाया।","explanationEn":"Sawai Jai Singh II was also a great astronomer who built the ''Jantar Mantar'' observatories in multiple cities, including Jaipur.","memoryTip":"''जय'' सिंह ने अपने ही नाम पर ''जय''पुर बसाया।","memoryTipEn":"Jai Singh birthed Jaipur.","related":["Pink City","Jantar Mantar","Rajasthan"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TyAnWeExJtEeY4-gVf-Lz', 'General Knowledge', 'भारतीय संविधान में पहला संशोधन कब किया गया?', 'When was the first amendment made to the Indian Constitution?', '1951 में', 'In 1951', 95, 0, '{"facts":["यह संशोधन भारत के पहले आम चुनाव होने से पहले ही अनंतिम संसद (Provisional Parliament) द्वारा किया गया था।","इसके द्वारा संविधान में ''नौवीं अनुसूची'' (Ninth Schedule) जोड़ी गई।"],"factsEn":["This amendment was passed by the Provisional Parliament even before India''s first general elections.","It added the ''Ninth Schedule'' to the Constitution."],"explanationHi":"इसका मुख्य उद्देश्य जमींदारी उन्मूलन और भूमि सुधार कानूनों को अदालतों में चुनौती देने से बचाना था।","explanationEn":"Its main objective was to protect zamindari abolition and land reform laws from being challenged in courts.","memoryTip":"संविधान बनते ही 51 में पहला ''सुधार'' (संशोधन) करना पड़ा।","memoryTipEn":"1951 marked the first constitutional fix.","related":["Ninth Schedule","Land Reforms","Article 31A and 31B"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1VstvQa8R6D6Jf4MT6hZZ', 'General Knowledge', 'डूरंड कप (Durand Cup) किस खेल से संबंधित है?', 'Durand Cup is related to which sport?', 'फुटबॉल', 'Football', 91, 0, '{"facts":["यह एशिया का सबसे पुराना और दुनिया का तीसरा सबसे पुराना फुटबॉल टूर्नामेंट है।","इसकी शुरुआत 1888 में शिमला में हुई थी।"],"factsEn":["It is the oldest football tournament in Asia and the third oldest in the world.","It was started in Shimla in 1888."],"explanationHi":"प्रारंभ में यह केवल ब्रिटिश भारतीय सेना के लिए था, लेकिन बाद में इसे नागरिक टीमों (Civilian teams) के लिए भी खोल दिया गया।","explanationEn":"Initially meant only for the British Indian Army, it was later opened up to civilian teams as well.","memoryTip":"डूरंड कप में बॉल को ''दूर'' (Durand) किक करते हैं।","memoryTipEn":"Durand Cup kicks off Football.","related":["Santosh Trophy","Rovers Cup","Oldest Football Tournament"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GODpXhcK5IXO4xKkbH_Qx', 'General Knowledge', 'सन 1907 में शुरु किया गया साहित्य का नोबल पुरस्कार किसे दिया गया?', 'Who was awarded the Nobel Prize in Literature started in 1907 (actually he received it in 1907)?', 'रुडयार्ड किपलिंग', 'Rudyard Kipling', 88, 0, '{"facts":["नोट: नोबेल पुरस्कार वास्तव में 1901 में शुरू हुए थे, किपलिंग ने इसे 1907 में जीता था।","वे अंग्रेजी भाषा में साहित्य का नोबेल जीतने वाले पहले लेखक थे।"],"factsEn":["Note: Nobel Prizes actually started in 1901; Kipling won it in 1907.","He was the first English-language writer to win the Nobel in Literature."],"explanationHi":"वे प्रसिद्ध पुस्तक ''द जंगल बुक'' (The Jungle Book) के लेखक हैं, जो भारत की पृष्ठभूमि पर आधारित है।","explanationEn":"He is the author of the famous book ''The Jungle Book'', which is set in the Indian context.","memoryTip":"''जंगल बुक'' लिखकर किपलिंग ने नोबेल ''कीप'' (रख) लिया।","memoryTipEn":"Kipling claimed the literary Nobel.","related":["The Jungle Book","Nobel Prize in Literature","Mowgli"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9mw7N3E8hQkdORGf-OcXW', 'General Knowledge', 'किसके शासनकाल में मोरक्को का यात्री इब्नबतूता भारत आया?', 'During whose reign did the Moroccan traveler Ibn Battuta come to India?', 'मोहम्मद बिन तुगलक', 'Muhammad bin Tughluq', 94, 0, '{"facts":["वह मोरक्को (अफ्रीका) का एक प्रसिद्ध मुस्लिम विद्वान और खोजकर्ता था।","इब्नबतूता ने ''रेहला'' (Rihla) नामक यात्रा वृत्तांत लिखा।"],"factsEn":["He was a famous Moroccan (African) Muslim scholar and explorer.","Ibn Battuta wrote a travelogue named ''Rihla''."],"explanationHi":"तुगलक ने इब्नबतूता की विद्वता से प्रभावित होकर उसे दिल्ली का ''काजी'' (न्यायाधीश) नियुक्त किया था।","explanationEn":"Impressed by his scholarship, Tughluq appointed Ibn Battuta as the ''Qazi'' (Judge) of Delhi.","memoryTip":"''इब्नबतूता'' ने ''तुगलक'' के राज में जूता (पैर) रखा।","memoryTipEn":"Ibn Battuta traveled to Tughluq''s India.","related":["Rihla","Muhammad bin Tughluq","Delhi Sultanate"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nOlEJqeD4UNrwl290IPgG', 'General Knowledge', 'भारत के पहले कानून मंत्री कौन थे?', 'Who was the first Law Minister of India?', 'डॉ. भीमराव अम्बेडकर', 'Dr. B. R. Ambedkar', 96, 0, '{"facts":["वे भारतीय संविधान की मसौदा समिति (Drafting Committee) के अध्यक्ष भी थे।","उन्हें ''भारतीय संविधान का जनक'' (Father of the Indian Constitution) कहा जाता है।"],"factsEn":["He was also the Chairman of the Drafting Committee of the Indian Constitution.","He is known as the ''Father of the Indian Constitution''."],"explanationHi":"स्वतंत्र भारत के पहले मंत्रिमंडल (Nehru cabinet) में उन्होंने देश के कानूनी ढांचे और संविधान को आकार देने में सबसे अहम भूमिका निभाई।","explanationEn":"In the first cabinet of independent India, he played the most pivotal role in shaping the country''s legal framework and Constitution.","memoryTip":"जिसने ''कानून'' (संविधान) लिखा, वही पहला कानून मंत्री बना।","memoryTipEn":"Ambedkar authored the laws of the land.","related":["Drafting Committee","Father of the Constitution","Poona Pact"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-I-XjCR8eBluJzi8U226x', 'General Knowledge', '''अभिज्ञान शाकुन्तलम'' के लेखक कौन थे?', 'Who was the author of ''Abhijnanashakuntalam''?', 'कालिदास', 'Kalidasa', 95, 0, '{"facts":["यह संस्कृत साहित्य का सबसे प्रसिद्ध नाटक (Play) है।","यह महाभारत की एक कहानी पर आधारित है, जिसमें राजा दुष्यंत और शकुंतला की प्रेम कथा है।"],"factsEn":["It is the most famous play in Sanskrit literature.","It is based on a story from the Mahabharata, depicting the love story of King Dushyanta and Shakuntala."],"explanationHi":"यह पहला भारतीय नाटक था जिसका पश्चिमी भाषाओं (जैसे अंग्रेजी और जर्मन) में अनुवाद किया गया था।","explanationEn":"It was the first Indian play to be translated into Western languages (like English and German).","memoryTip":"कालिदास का सबसे बड़ा ''ज्ञान'' (अभिज्ञान) शकुंतला की कहानी में है।","memoryTipEn":"Kalidasa scripted Shakuntala''s story.","related":["King Dushyanta","Sanskrit Literature","Meghaduta"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('walhcZoilxLVFCv2JQpOe', 'General Knowledge', 'श्रमिक दिवस (Labour Day) कब मनाया जाता है?', 'When is Labour Day celebrated?', '1 मई', '1 May', 92, 0, '{"facts":["इसे अंतर्राष्ट्रीय श्रमिक दिवस या ''मई दिवस'' (May Day) भी कहा जाता है।","भारत में पहली बार मज़दूर दिवस 1923 में चेन्नई (तत्कालीन मद्रास) में मनाया गया था।"],"factsEn":["It is also known as International Workers'' Day or ''May Day''.","In India, Labour Day was first celebrated in Chennai (then Madras) in 1923."],"explanationHi":"यह दिन दुनिया भर के मजदूरों और श्रमिक वर्ग के संघर्षों, अधिकारों (जैसे 8 घंटे काम का नियम) और उपलब्धियों को समर्पित है।","explanationEn":"This day is dedicated to the struggles, rights (like the 8-hour workday), and achievements of workers and the labor class worldwide.","memoryTip":"मई की पहली (1 मई) तारीख मजदूरों की मेहनत के नाम।","memoryTipEn":"May 1 is for the workers.","related":["May Day","Labor Rights","8-hour workday"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oieUPEtavvq3Q9dV0aHBp', 'General Knowledge', '''ओडिसी'' किस राज्य का शास्त्रीय नृत्य है?', '''Odissi'' is a classical dance of which state?', 'ओड़िसा', 'Odisha', 93, 0, '{"facts":["यह भारत के आठ मान्यता प्राप्त शास्त्रीय नृत्यों में से एक है।","इसकी मुद्राएं और मूर्तियां कोणार्क सूर्य मंदिर और जगन्नाथ मंदिर में उकेरी गई हैं।"],"factsEn":["It is one of the eight recognized classical dances of India.","Its postures and sculptures are carved in the Konark Sun Temple and Jagannath Temple."],"explanationHi":"यह नृत्य अपनी ''त्रिभंग'' (Tribhangi) मुद्रा के लिए बहुत प्रसिद्ध है, जिसमें शरीर तीन हिस्सों (सिर, धड़ और पैर) में मुड़ा होता है।","explanationEn":"The dance is highly renowned for its ''Tribhangi'' posture, where the body is bent in three parts (head, torso, and legs).","memoryTip":"नाम में ही राज्य छिपा है: ओडिसी = ओड़िसा।","memoryTipEn":"Odissi originates in Odisha.","related":["Tribhangi Posture","Classical Dances of India","Kelucharan Mohapatra"]}', 'published', 1776084494, 1776084494);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9AvMiSpAeOSzL2NyG2Ud1', 'General Knowledge', 'भाखड़ा बांध किस नदी पर बनाया गया है?', 'On which river is the Bhakra Dam built?', 'सतलुज', 'Sutlej', 95, 0, '{"facts":["यह हिमाचल प्रदेश और पंजाब की सीमा पर स्थित है।","गोबिंद सागर झील इसी बांध का जलाशय है।"],"factsEn":["It is located on the border of Himachal Pradesh and Punjab.","Gobind Sagar Lake is the reservoir of this dam."],"explanationHi":"भाखड़ा नांगल परियोजना भारत की सबसे बड़ी बहुउद्देशीय नदी घाटी परियोजनाओं में से एक है।","explanationEn":"The Bhakra Nangal project is one of the largest multipurpose river valley projects in India.","memoryTip":"भाखड़ा बांध ''सत'' (सच्ची) मजबूती के साथ ''लुज'' (Sutlej) नदी पर खड़ा है।","memoryTipEn":"Bhakra stands strong on Sutlej.","related":["Nangal Dam","Gobind Sagar Lake","Multipurpose Projects"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vwJ6GW95MOXiDS8jyX8yg', 'General Knowledge', 'भारत का क्षेत्रफल कितना है?', 'What is the total area of India?', '32,87,263 वर्ग कि.मी.', '3,287,263 sq km', 92, 0, '{"facts":["क्षेत्रफल की दृष्टि से भारत विश्व का सातवाँ सबसे बड़ा देश है।","यह विश्व के कुल भौगोलिक क्षेत्रफल का लगभग 2.4% हिस्सा कवर करता है।"],"factsEn":["India is the 7th largest country in the world by area.","It covers about 2.4% of the world''s total geographical area."],"explanationHi":"भारत उत्तर में हिमालय से लेकर दक्षिण में हिंद महासागर तक फैला हुआ एक विशाल देश है।","explanationEn":"India is a vast country stretching from the Himalayas in the north to the Indian Ocean in the south.","memoryTip":"32 लाख 87 हज़ार याद रखें, बाकी विकल्प देखकर पहचान लेंगे।","memoryTipEn":"Starts with 32 and ends with 263.","related":["Geography of India","Russia (Largest by area)","Indian Subcontinent"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wFe_B9QzsDXdw7ty9a1Qq', 'General Knowledge', 'अमेरिका ने जापान के हिरोशिमा पर परमाणु बम कब गिराया था?', 'When did America drop the atomic bomb on Hiroshima in Japan?', '6 अगस्त 1945 को', 'On August 6, 1945', 96, 0, '{"facts":["हिरोशिमा पर गिराए गए बम का नाम ''लिटिल बॉय'' (Little Boy) था।","9 अगस्त 1945 को नागासाकी पर ''फैट मैन'' (Fat Man) नामक दूसरा बम गिराया गया।"],"factsEn":["The bomb dropped on Hiroshima was codenamed ''Little Boy''.","The second bomb, ''Fat Man'', was dropped on Nagasaki on August 9, 1945."],"explanationHi":"इस बमबारी के बाद जापान ने आत्मसमर्पण कर दिया, जिससे द्वितीय विश्व युद्ध समाप्त हो गया।","explanationEn":"Following these bombings, Japan surrendered, bringing an end to World War II.","memoryTip":"6 अगस्त को ''हीरो'' (हिरोशिमा) और 9 अगस्त को ''नाग'' (नागासाकी)।","memoryTipEn":"August 6 for Little Boy, August 9 for Fat Man.","related":["Nagasaki","World War II","Manhattan Project"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TjcMZQTm5rm0qLJv1PhdJ', 'General Knowledge', 'राष्ट्रपति चुनाव में कौन वोट डालता है?', 'Who votes in the Presidential election?', 'संसद तथा राज्य विधानसभाओं के चुने हुए सदस्य', 'Elected members of the Parliament and State Legislative Assemblies', 94, 0, '{"facts":["राष्ट्रपति का चुनाव एक निर्वाचक मंडल (Electoral College) द्वारा होता है।","इसमें मनोनीत सदस्य (Nominated members) और विधान परिषदों (Legislative Councils) के सदस्य भाग नहीं लेते।"],"factsEn":["The President is elected by an Electoral College.","Nominated members and members of Legislative Councils do not participate."],"explanationHi":"यह चुनाव आनुपातिक प्रतिनिधित्व प्रणाली के अनुसार एकल संक्रमणीय मत द्वारा अप्रत्यक्ष रूप से होता है।","explanationEn":"The election is held indirectly using a single transferable vote under the proportional representation system.","memoryTip":"केवल ''चुने हुए'' (Elected) प्रतिनिधि ही देश के सबसे बड़े पद को चुनते हैं।","memoryTipEn":"Only Elected MPs and MLAs choose the President.","related":["Electoral College","Article 54","Single Transferable Vote"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GAeIPg6aOtrACA27q85Iy', 'General Knowledge', 'उत्तरी ध्रुव को दक्षिणी ध्रुव से मिलाने वाली काल्पनिक रेखा क्या कहलाती है?', 'What is the imaginary line connecting the North Pole to the South Pole called?', 'देशांतर रेखा', 'Longitude', 93, 0, '{"facts":["इन रेखाओं को मध्याह्न रेखाएँ (Meridians) भी कहा जाता है।","0 डिग्री देशांतर को ''प्राइम मेरिडियन'' (Prime Meridian) कहा जाता है जो ग्रीनविच से गुजरती है।"],"factsEn":["These lines are also known as Meridians.","0 degree longitude is called the ''Prime Meridian'', passing through Greenwich."],"explanationHi":"देशांतर रेखाएँ पृथ्वी पर समय (Time zones) निर्धारित करने में मदद करती हैं, जबकि अक्षांश (Latitude) जलवायु और दूरी बताते हैं।","explanationEn":"Longitudes help determine time zones on Earth, whereas latitudes indicate climate zones and distance from the equator.","memoryTip":"देश के ''अंतर'' (देशांतर) को पार करते हुए उत्तर से दक्षिण जाती है।","memoryTipEn":"Longitudes are ''LONG'' lines from pole to pole.","related":["Latitude","Prime Meridian","Equator"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RXX_TkG7WmIaKCcxENpHc', 'General Knowledge', 'महात्मा गाँधी की हत्या कब और किसने की?', 'When and by whom was Mahatma Gandhi assassinated?', '30 जनवरी 1948 को नाथूराम गोडसे द्वारा', 'On January 30, 1948, by Nathuram Godse', 96, 0, '{"facts":["यह घटना नई दिल्ली के बिड़ला हाउस (अब गांधी स्मृति) में हुई थी।","इस दिन को भारत में ''शहीद दिवस'' (Martyrs'' Day) के रूप में मनाया जाता है।"],"factsEn":["The incident occurred at Birla House (now Gandhi Smriti) in New Delhi.","This day is observed as ''Martyrs'' Day'' in India."],"explanationHi":"शाम की प्रार्थना सभा में जाते समय गांधीजी को तीन गोलियां मारी गई थीं। उनके अंतिम शब्द ''हे राम'' थे।","explanationEn":"Gandhiji was shot three times on his way to an evening prayer meeting. His last words were ''Hey Ram''.","memoryTip":"आज़ादी के कुछ महीनों बाद ही (जनवरी 1948) बापू शहीद हो गए।","memoryTipEn":"January 30 marks Martyrs'' Day.","related":["Martyrs'' Day","Birla House","Hey Ram"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('sQK5JtTl0oQJq7xt9Ge7O', 'General Knowledge', 'भारत में कौनसा अनाज सबसे ज्यादा खाया जाता है?', 'Which grain is consumed the most in India?', 'चावल', 'Rice', 91, 0, '{"facts":["भारत दुनिया में चीन के बाद चावल का दूसरा सबसे बड़ा उत्पादक देश है।","पश्चिम बंगाल भारत में चावल का सबसे बड़ा उत्पादक राज्य है।"],"factsEn":["India is the second-largest producer of rice in the world after China.","West Bengal is the largest rice-producing state in India."],"explanationHi":"दक्षिण, पूर्वी और तटीय भारत में चावल मुख्य आहार (Staple food) है।","explanationEn":"Rice is the staple food in southern, eastern, and coastal regions of India.","memoryTip":"भारत के आधे से अधिक हिस्से में ''चावल'' की थाली सजी होती है।","memoryTipEn":"Rice is the staple of the subcontinent.","related":["Kharif Crop","Wheat (2nd most consumed)","West Bengal"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zRaEiUbAZuuFywPWP_L0-', 'General Knowledge', 'थल सेना दिवस (Army Day) कब मनाया जाता है?', 'When is Army Day celebrated?', '15 जनवरी', '15 January', 95, 0, '{"facts":["इसी दिन 1949 में जनरल के. एम. करियप्पा ने ब्रिटिश कमांडर से भारतीय थल सेना की कमान ली थी।","हर साल दिल्ली में इंडिया गेट के पास अमर जवान ज्योति पर शहीदों को श्रद्धांजलि दी जाती है।"],"factsEn":["On this day in 1949, General K.M. Cariappa took command of the Indian Army from the British commander.","Tributes are paid to martyrs at Amar Jawan Jyoti near India Gate in Delhi every year."],"explanationHi":"यह दिन भारतीय सैनिकों की वीरता और बलिदान का सम्मान करने के लिए पूरे देश में मनाया जाता है।","explanationEn":"This day is celebrated across the country to honor the gallantry and sacrifice of Indian soldiers.","memoryTip":"साल के पहले ही महीने (15 जनवरी) में सेना अपनी ताकत दिखाती है।","memoryTipEn":"January 15, the Army takes charge.","related":["General K.M. Cariappa","Navy Day (Dec 4)","Air Force Day (Oct 8)"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DngJmu2shwSf3i0cgxhp6', 'General Knowledge', 'राजस्थान के माउन्ट आबू स्थित दिलवाड़ा के मंदिर किस धर्म से संबंधित हैं?', 'To which religion are the Dilwara Temples situated at Mount Abu in Rajasthan related?', 'जैन धर्म', 'Jainism', 94, 0, '{"facts":["ये मंदिर अपनी असाधारण संगमरमर की नक्काशी (Marble carvings) के लिए विश्व प्रसिद्ध हैं।","इनका निर्माण 11वीं और 13वीं शताब्दी के बीच चालुक्य (सोलंकी) वंश के दौरान हुआ था।"],"factsEn":["These temples are world-famous for their extraordinary marble carvings.","They were built between the 11th and 13th centuries during the Chalukya (Solanki) dynasty."],"explanationHi":"यह जैनियों के लिए एक पवित्र तीर्थस्थल है, जहाँ पांच मंदिरों का एक समूह है, जिनमें विमल वसाही मंदिर सबसे पुराना है।","explanationEn":"It is a sacred pilgrimage site for Jains, consisting of a group of five temples, with Vimal Vasahi being the oldest.","memoryTip":"''दिल'' वालों का मंदिर है दिलवाड़ा, जहाँ ''जैन'' धर्म की शांति बसती है।","memoryTipEn":"Dilwara displays Jain devotion.","related":["Mount Abu","Jain Tirthankaras","Marble Architecture"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('fmpW61npuz_TBtbwDDZ-Z', 'General Knowledge', 'दिल्ली स्थित जामा मस्जिद किसने बनवाई?', 'Who built the Jama Masjid located in Delhi?', 'शाहजहाँ', 'Shah Jahan', 93, 0, '{"facts":["यह भारत की सबसे बड़ी मस्जिदों में से एक है।","इसका निर्माण 1650 में शुरू हुआ और 1656 में पूरा हुआ था।"],"factsEn":["It is one of the largest mosques in India.","Its construction started in 1650 and was completed in 1656."],"explanationHi":"मुगल सम्राट शाहजहाँ ने इसे लाल किले के ठीक सामने बनवाया था, जिसे मूल रूप से ''मस्जिद-ए-जहाँ नुमा'' (दुनिया की कमान संभालने वाली मस्जिद) कहा जाता था।","explanationEn":"Mughal Emperor Shah Jahan built it right across from the Red Fort; it was originally called ''Masjid-i Jehan-Numa'' (Mosque commanding the view of the world).","memoryTip":"दिल्ली का लाल किला और जामा मस्जिद दोनों ''शाहजहाँ'' की शान हैं।","memoryTipEn":"Shah Jahan built the Jama Masjid.","related":["Red Fort","Mughal Architecture","Taj Mahal"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IwH5_07C4hJAGSiw5wE8Q', 'General Knowledge', 'शांतिकाल का सर्वोच्च सैन्य पुरस्कार कौनसा है?', 'Which is the highest peacetime military award?', 'अशोक चक्र', 'Ashoka Chakra', 96, 0, '{"facts":["यह युद्ध के मैदान से दूर (शांतिकाल में) वीरता और आत्म-बलिदान के लिए दिया जाता है।","कीर्ति चक्र और शौर्य चक्र इसके बाद आते हैं।"],"factsEn":["It is awarded for valor, courageous action, and self-sacrifice away from the battlefield (during peacetime).","Kirti Chakra and Shaurya Chakra follow it in order of precedence."],"explanationHi":"परमवीर चक्र युद्ध के समय का सर्वोच्च सम्मान है, जबकि अशोक चक्र शांतिकाल का सर्वोच्च वीरता सम्मान है। यह नागरिकों को भी दिया जा सकता है।","explanationEn":"Param Vir Chakra is the highest wartime honor, whereas Ashoka Chakra is the highest peacetime gallantry award. It can also be awarded to civilians.","memoryTip":"शांति (अशोक ने भी युद्ध छोड़ शांति अपनाई थी) का चक्र = अशोक चक्र।","memoryTipEn":"Ashoka brings peace.","related":["Param Vir Chakra","Kirti Chakra","Shaurya Chakra"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('I6P6gsaA_aTHF5SIpTCn8', 'General Knowledge', 'राष्ट्रीय डेयरी अनुसंधान संस्थान (NDRI) कहाँ स्थित है?', 'Where is the National Dairy Research Institute (NDRI) located?', 'करनाल (हरियाणा)', 'Karnal (Haryana)', 90, 0, '{"facts":["यह भारत में डेयरी अनुसंधान और शिक्षा का प्रमुख संस्थान है।","शुरुआत में यह 1923 में बैंगलोर में इंपीरियल इंस्टीट्यूट ऑफ एनिमल हसबेंडरी के रूप में स्थापित हुआ था।"],"factsEn":["It is the premier institute for dairy research and education in India.","It was originally established in 1923 in Bangalore as the Imperial Institute of Animal Husbandry."],"explanationHi":"1955 में इसका मुख्यालय करनाल स्थानांतरित कर दिया गया। यह पशुओं की नस्ल सुधार और दूध उत्पादन की तकनीक पर शोध करता है।","explanationEn":"Its headquarters shifted to Karnal in 1955. It researches animal breed improvement and milk production technologies.","memoryTip":"करनाल में ''डेयरी'' (दूध) का काम बहुत ''कमाल'' होता है।","memoryTipEn":"Karnal takes care of dairy.","related":["White Revolution","Operation Flood","Haryana"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_5kqW3eGASuGy0kD0JogW', 'General Knowledge', 'भगवान बुद्ध द्वारा सारनाथ में दिया गया पहला प्रवचन बौद्ध धर्म में क्या कहलाता है?', 'What is the first sermon given by Lord Buddha at Sarnath called in Buddhism?', 'धर्मचक्रप्रवर्तन', 'Dharmachakra Pravartana', 95, 0, '{"facts":["इसका अर्थ है ''धर्म के पहिये को घुमाना'' (Turning the Wheel of Dharma)।","यह उपदेश उन्होंने अपने पांच पूर्व साथियों (भिक्षुओं) को दिया था।"],"factsEn":["It translates to ''Turning the Wheel of Dharma''.","He delivered this sermon to his five former ascetic companions."],"explanationHi":"इस उपदेश में बुद्ध ने ''चार आर्य सत्य'' (Four Noble Truths) और ''अष्टांगिक मार्ग'' (Eightfold Path) की व्याख्या की थी।","explanationEn":"In this sermon, Buddha explained the ''Four Noble Truths'' and the ''Eightfold Path''.","memoryTip":"ज्ञान का ''चक्र'' सारनाथ से घुमाया (धर्मचक्रप्रवर्तन)।","memoryTipEn":"Buddha turned the wheel of Dharma.","related":["Sarnath","Four Noble Truths","Mahaparinirvana"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wPem79HQl7wFWDuUIiei3', 'General Knowledge', 'वायुसेना दिवस (Air Force Day) कब मनाया जाता है?', 'When is Air Force Day celebrated?', '8 अक्टूबर', '8 October', 93, 0, '{"facts":["8 अक्टूबर 1932 को भारतीय वायु सेना (Indian Air Force) की आधिकारिक स्थापना हुई थी।","हिंडन वायु सेना स्टेशन (गाजियाबाद) में इसका मुख्य समारोह आयोजित किया जाता है।"],"factsEn":["The Indian Air Force was officially established on October 8, 1932.","The main celebration is held at the Hindon Air Force Station (Ghaziabad)."],"explanationHi":"इस दिन भारतीय वायुसेना अपनी ताकत, कौशल और विभिन्न लड़ाकू विमानों का हवाई प्रदर्शन (Air show) करती है।","explanationEn":"On this day, the IAF displays its strength, skill, and an air show of various fighter aircraft.","memoryTip":"अक्टूबर के महीने में 8 दिशाओं में विमान उड़ते हैं।","memoryTipEn":"October 8, flying great.","related":["Indian Air Force","Army Day (Jan 15)","Navy Day (Dec 4)"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4jfoILyOvAmFRiOamaWnz', 'General Knowledge', '1526, 1556 और 1761 के तीन ऐतिहासिक युद्ध किस नगर में हुए?', 'In which city did the three historic battles of 1526, 1556, and 1761 take place?', 'पानीपत (हरियाणा)', 'Panipat (Haryana)', 96, 0, '{"facts":["पानीपत का पहला युद्ध (1526): बाबर और इब्राहिम लोदी के बीच (मुगल वंश की स्थापना)।","पानीपत का दूसरा युद्ध (1556): अकबर और हेमू के बीच।"],"factsEn":["First Battle of Panipat (1526): Between Babur and Ibrahim Lodi (establishing the Mughal Empire).","Second Battle of Panipat (1556): Between Akbar and Hemu."],"explanationHi":"पानीपत का तीसरा युद्ध (1761) मराठों और अहमद शाह अब्दाली के बीच लड़ा गया था। ये तीनों युद्ध भारतीय इतिहास के निर्णायक मोड़ थे।","explanationEn":"The Third Battle of Panipat (1761) was fought between the Marathas and Ahmad Shah Abdali. These three battles were turning points in Indian history.","memoryTip":"''पानी''पत में खून की नदियां बहीं (तीन बड़े युद्ध)।","memoryTipEn":"Panipat changed India''s destiny thrice.","related":["Babur","Akbar","Ahmad Shah Abdali"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DQP7Ltg9KMarwJcXafu0U', 'General Knowledge', 'भारत के पश्चिमी तट पर कौनसा सागर है?', 'Which sea is on the western coast of India?', 'अरब सागर', 'Arabian Sea', 92, 0, '{"facts":["अरब सागर हिंद महासागर का हिस्सा है।","मुंबई, कोच्चि और मंगलुरु जैसे प्रमुख भारतीय बंदरगाह इसी सागर के तट पर स्थित हैं।"],"factsEn":["The Arabian Sea is a region of the Indian Ocean.","Major Indian ports like Mumbai, Kochi, and Mangaluru are located on its coast."],"explanationHi":"भारत के पूर्व में बंगाल की खाड़ी, पश्चिम में अरब सागर और दक्षिण में हिंद महासागर है।","explanationEn":"India is bounded by the Bay of Bengal on the east, the Arabian Sea on the west, and the Indian Ocean on the south.","memoryTip":"पश्चिम में ''अरब'' देशों का रास्ता जाता है, इसलिए ''अरब सागर''।","memoryTipEn":"West faces the Arabian sands.","related":["Bay of Bengal","Indian Ocean","Western Ghats"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('p6r3uJuHsgTihXIhjxRZA', 'General Knowledge', 'UNESCO (यूनेस्को) का मुख्यालय कहाँ है?', 'Where is the headquarters of UNESCO?', 'पेरिस (फ्रांस)', 'Paris (France)', 94, 0, '{"facts":["UNESCO का पूर्ण रूप United Nations Educational, Scientific and Cultural Organization है।","इसकी स्थापना 1945 में हुई थी।"],"factsEn":["UNESCO stands for United Nations Educational, Scientific and Cultural Organization.","It was established in 1945."],"explanationHi":"यह विश्व धरोहर स्थलों (World Heritage Sites) को घोषित करता है और शिक्षा, विज्ञान और संस्कृति के माध्यम से वैश्विक शांति को बढ़ावा देता है।","explanationEn":"It designates World Heritage Sites and promotes global peace through education, science, and culture.","memoryTip":"कला और संस्कृति का केंद्र ''पेरिस'', वहीं है यूनेस्को।","memoryTipEn":"UNESCO preserves culture in Paris.","related":["World Heritage Sites","United Nations","UNICEF"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NfXpQgXl4wykbUzksKZcr', 'General Knowledge', 'विश्व व्यापार संगठन (WTO) की स्थापना कब हुई?', 'When was the World Trade Organization (WTO) established?', '1995 में', '1995', 92, 0, '{"facts":["WTO ने ''GATT'' (General Agreement on Tariffs and Trade) का स्थान लिया।","इसका मुख्यालय जिनेवा, स्विट्जरलैंड में है।"],"factsEn":["The WTO replaced ''GATT'' (General Agreement on Tariffs and Trade).","Its headquarters is in Geneva, Switzerland."],"explanationHi":"यह एकमात्र वैश्विक अंतरराष्ट्रीय संगठन है जो राष्ट्रों के बीच व्यापार के नियमों (Trade rules) से निपटता है।","explanationEn":"It is the only global international organization dealing with the rules of trade between nations.","memoryTip":"95 में विश्व ने ''व्यापार'' के नए नियम बनाए।","memoryTipEn":"WTO traded GATT in ''95.","related":["Geneva","GATT","International Trade"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ycDLBoASf37K3rxlTRSHe', 'General Knowledge', 'शिक्षा की किंडरगार्टन (Kindergarten) पद्यति किसकी देन है?', 'Who originated the Kindergarten system of education?', 'फ्रोबेल (Friedrich Froebel)', 'Friedrich Froebel', 89, 0, '{"facts":["फ्रोबेल एक जर्मन शिक्षक थे।","किंडरगार्टन का जर्मन में अर्थ ''बच्चों का बगीचा'' (Children''s Garden) होता है।"],"factsEn":["Froebel was a German educator.","Kindergarten translates to ''Children''s Garden'' in German."],"explanationHi":"फ्रोबेल का मानना था कि छोटे बच्चे पौधों की तरह होते हैं जिन्हें खेल, गीत और गतिविधियों के माध्यम से एक बगीचे में पोषित किया जाना चाहिए।","explanationEn":"Froebel believed that young children are like plants needing to be nurtured in a garden through play, songs, and activities.","memoryTip":"बच्चों को ''फ्री'' (फ्रोबेल) होकर खेलने दो।","memoryTipEn":"Froebel framed the Kindergarten.","related":["Maria Montessori","Early Childhood Education"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gZhTosyFZzPPAR14y1esS', 'General Knowledge', 'NCERT की स्थापना कब हुई?', 'When was NCERT established?', '1961 में', '1961', 90, 0, '{"facts":["NCERT का पूर्ण रूप National Council of Educational Research and Training है।","इसका मुख्यालय नई दिल्ली में है।"],"factsEn":["NCERT stands for National Council of Educational Research and Training.","Its headquarters is in New Delhi."],"explanationHi":"यह भारत सरकार द्वारा स्थापित एक स्वायत्त संगठन है जो स्कूल शिक्षा में सुधार के लिए केंद्र और राज्य सरकारों को सलाह देता है और पाठ्यपुस्तकें प्रकाशित करता है।","explanationEn":"It is an autonomous organization set up by the Govt of India to advise central and state governments on policies to improve school education and publish textbooks.","memoryTip":"61 में शिक्षा को ''सर्टिफाई'' (NCERT) किया गया।","memoryTipEn":"NCERT was established in 1961.","related":["CBSE","UGC","Education Policy"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RwA-qhVXvJokGNWnyXzCC', 'General Knowledge', 'तानसेन किसके दरबार में संगीतज्ञ था?', 'Tansen was a musician in whose court?', 'अकबर', 'Akbar', 93, 0, '{"facts":["वे अकबर के दरबार के ''नवरत्नों'' (Nine Jewels) में से एक थे।","उनका असली नाम रामतनु पांडेय था।"],"factsEn":["He was one of the ''Navaratnas'' (Nine Jewels) in Akbar''s court.","His real name was Ramtanu Pandey."],"explanationHi":"तानसेन एक महान हिंदुस्तानी शास्त्रीय संगीतकार थे। ऐसा माना जाता है कि उनके गाए रागों (''राग दीपक'' और ''राग मेघ मल्हार'') से दीपक जल उठते थे और बारिश होने लगती थी।","explanationEn":"Tansen was a legendary Hindustani classical musician. Legends say his singing of Ragas (''Deepak'' and ''Megh Malhar'') could light lamps and cause rain.","memoryTip":"अकबर के दरबार में तानसेन की ''तान'' गूंजती थी।","memoryTipEn":"Tansen tuned Akbar''s court.","related":["Navaratnas","Hindustani Classical Music","Gwalior (Tansen''s Tomb)"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('r3pUlfoBOKZka6NcVVx54', 'General Knowledge', 'कौन 4 वर्ष तक अकबर का संरक्षक (Regent) रहा?', 'Who was the regent (protector) of Akbar for 4 years?', 'बैरम खान', 'Bairam Khan', 92, 0, '{"facts":["अकबर जब केवल 13 वर्ष का था तब हुमायूँ की मृत्यु के बाद उसे गद्दी पर बैठाया गया।","पानीपत के दूसरे युद्ध (1556) में अकबर की सेना का नेतृत्व बैरम खान ने ही किया था।"],"factsEn":["Akbar was placed on the throne at the young age of 13 after Humayun''s death.","Bairam Khan led Akbar''s army in the Second Battle of Panipat (1556)."],"explanationHi":"बैरम खान मुगल साम्राज्य का एक शक्तिशाली सैन्य कमांडर था, जिसने युवा अकबर की ओर से शासन चलाया जब तक कि अकबर वयस्क नहीं हो गया।","explanationEn":"Bairam Khan was a powerful military commander of the Mughal Empire who ruled on behalf of the young Akbar until he came of age.","memoryTip":"बैरम खान ने अकबर को दुश्मनों से ''बैर'' (रक्षार्थ) बचाए रखा।","memoryTipEn":"Bairam shielded the boy king.","related":["Second Battle of Panipat","Hemu","Humayun"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('V3rEG7V7oG2uUhusDkWIt', 'General Knowledge', 'पंडित रविशंकर का संबंध किस वाद्य यंत्र से है?', 'Pandit Ravi Shankar is associated with which musical instrument?', 'सितार', 'Sitar', 94, 0, '{"facts":["उन्हें 1999 में भारत का सर्वोच्च नागरिक सम्मान ''भारत रत्न'' मिला।","उन्होंने पश्चिमी दुनिया (जैसे द बीटल्स) को भारतीय शास्त्रीय संगीत से परिचित कराने में महत्वपूर्ण भूमिका निभाई।"],"factsEn":["He received India''s highest civilian honor ''Bharat Ratna'' in 1999.","He played a key role in introducing Indian classical music to the Western world (like The Beatles)."],"explanationHi":"पंडित रविशंकर 20वीं शताब्दी के उत्तरार्ध में उत्तर भारतीय शास्त्रीय संगीत के सबसे प्रसिद्ध प्रतिपादक थे।","explanationEn":"Pandit Ravi Shankar was the most renowned exponent of North Indian classical music in the second half of the 20th century.","memoryTip":"''रवि'' (सूर्य) की तरह ''सितार'' में चमके पंडित जी।","memoryTipEn":"Ravi''s Sitar resonated globally.","related":["Bharat Ratna","Ustad Bismillah Khan (Shehnai)","Hindustani Classical Music"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WJKxY4C0gC6tttbSV2H7Q', 'General Knowledge', '''पैनल्टी कार्नर'' (Penalty Corner) का संबंध किस खेल से है?', 'The term ''Penalty Corner'' is associated with which sport?', 'हॉकी', 'Hockey', 90, 0, '{"facts":["यह तब दिया जाता है जब बचाव करने वाली टीम शूटिंग सर्कल (D) के अंदर फाउल करती है।","इसे ''शॉर्ट कॉर्नर'' भी कहा जाता है।"],"factsEn":["It is awarded when the defending team commits a foul inside the shooting circle (D).","It is also known as a ''Short Corner''."],"explanationHi":"पेनल्टी कॉर्नर के दौरान, हमलावर टीम को गोल करने का एक विशेष अवसर मिलता है जिसमें गेंद को बैकलाइन से पुश किया जाता है।","explanationEn":"During a penalty corner, the attacking team gets a special opportunity to score where the ball is pushed out from the backline.","memoryTip":"हॉकी के ''डी'' (सर्कल) में फाउल होने पर कॉर्नर मिलता है।","memoryTipEn":"Hockey has a D and a penalty corner.","related":["Field Hockey","Penalty Stroke","Drag Flick"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5foxoFMPLR66qCfCSRzLq', 'General Knowledge', 'उत्तरी भारत में सर्दियों में वर्षा का कारण क्या है?', 'What is the cause of winter rainfall in Northern India?', 'पश्चिमी विक्षोभ (Western Disturbances)', 'Western Disturbances', 94, 0, '{"facts":["ये विक्षोभ भूमध्य सागर (Mediterranean Sea) से उत्पन्न होने वाले चक्रवाती तूफान हैं।","सर्दियों की यह बारिश ''रबी'' की फसलों (विशेषकर गेहूं) के लिए बहुत फायदेमंद होती है।"],"factsEn":["These disturbances are cyclonic storms originating from the Mediterranean Sea.","This winter rain is highly beneficial for ''Rabi'' crops (especially wheat)."],"explanationHi":"पछुआ हवाएं (Westerly winds) इस नमी को भूमध्य सागर से लेकर भारत के उत्तर-पश्चिमी हिस्सों (पंजाब, हरियाणा, दिल्ली) तक लाती हैं।","explanationEn":"Westerly winds carry this moisture from the Mediterranean Sea to the northwestern parts of India (Punjab, Haryana, Delhi).","memoryTip":"''पश्चिम'' की तरफ से आने वाली हवाएं ''विक्षोभ'' (बारिश) लाती हैं।","memoryTipEn":"Western winds drop winter rains.","related":["Rabi Crops","Mediterranean Sea","Jet Streams"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IfBuhnbb-wlM_H2WLfHQW', 'General Knowledge', 'देवधर ट्राफी (Deodhar Trophy) का संबंध किस खेल से है?', 'Deodhar Trophy is related to which sport?', 'क्रिकेट', 'Cricket', 88, 0, '{"facts":["यह एक भारतीय घरेलू लिस्ट-ए (List-A) क्रिकेट प्रतियोगिता है।","इसका नाम क्रिकेट प्रशासक प्रो. डी.बी. देवधर के नाम पर रखा गया है, जिन्हें ''भारतीय क्रिकेट का ग्रैंड ओल्ड मैन'' कहा जाता है।"],"factsEn":["It is an Indian domestic List-A cricket competition.","It is named after cricket administrator Prof. D.B. Deodhar, known as the ''Grand Old Man of Indian Cricket''."],"explanationHi":"यह 50-ओवर का टूर्नामेंट है जो क्षेत्रीय टीमों (Zonal teams) या इंडिया ए, बी, सी के बीच खेला जाता है।","explanationEn":"It is a 50-over tournament played between Zonal teams or India A, B, and C.","memoryTip":"क्रिकेट के ''देव'' (देवधर) को ट्रॉफी मिली।","memoryTipEn":"Deodhar drives List-A cricket.","related":["Ranji Trophy","Vijay Hazare Trophy","Domestic Cricket"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('g0z-QcjriutSokW8DEP1j', 'General Knowledge', 'रूस (Russia) की मुद्रा कौनसी है?', 'What is the currency of Russia?', 'रुबल (Ruble)', 'Ruble', 89, 0, '{"facts":["रूस की राजधानी मॉस्को है।","रूस क्षेत्रफल के हिसाब से दुनिया का सबसे बड़ा देश है।"],"factsEn":["The capital of Russia is Moscow.","Russia is the largest country in the world by area."],"explanationHi":"रूसी रुबल सोवियत संघ के पतन के बाद से ही आधुनिक रूस की आधिकारिक मुद्रा रही है।","explanationEn":"The Russian Ruble has been the official currency of modern Russia since the collapse of the Soviet Union.","memoryTip":"रूस (R-u-s) की मुद्रा रुबल (R-u-b-l-e)।","memoryTipEn":"Russia trades in Rubles.","related":["Moscow","Vladimir Putin","Eurasia"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GU-ekrEzFXqBJlwaDKSDg', 'General Knowledge', 'जैन धर्म के प्रथम तीर्थंकर कौन थे?', 'Who was the first Tirthankara of Jainism?', 'ऋषभदेव (आदिनाथ)', 'Rishabhanatha (Adinatha)', 95, 0, '{"facts":["जैन धर्म में कुल 24 तीर्थंकर माने गए हैं।","ऋषभदेव को ''आदिनाथ'' भी कहा जाता है और उनका प्रतीक चिन्ह ''बैल'' (Bull) है।"],"factsEn":["There are a total of 24 Tirthankaras in Jainism.","Rishabhanatha is also known as ''Adinatha'' and his symbol is the ''Bull''."],"explanationHi":"मान्यता है कि ऋषभदेव ने ही मानव समाज को कृषि, कला और लिपि का ज्ञान दिया था। भगवान महावीर 24वें तीर्थंकर थे।","explanationEn":"It is believed that Rishabhanatha imparted the knowledge of agriculture, art, and script to human society. Lord Mahavira was the 24th Tirthankara.","memoryTip":"जैन धर्म के ''ऋषि'' (ऋषभदेव) ने सबसे पहले ज्ञान दिया।","memoryTipEn":"Rishabhanatha is the Root of Jainism.","related":["Mahavira","Parshvanatha (23rd)","Tirthankara"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WNwRZ37NA4cP6pkB7AZdY', 'General Knowledge', 'गौतम बुद्ध का जन्म कहाँ हुआ?', 'Where was Gautam Buddha born?', 'लुम्बिनी (जो नेपाल में है)', 'Lumbini (in Nepal)', 96, 0, '{"facts":["बुद्ध का जन्म 563 ईसा पूर्व एक शाक्य क्षत्रिय परिवार में हुआ था।","लुम्बिनी एक यूनेस्को विश्व धरोहर स्थल (UNESCO World Heritage Site) है।"],"factsEn":["Buddha was born in 563 BCE in a Shakya Kshatriya family.","Lumbini is a UNESCO World Heritage Site."],"explanationHi":"सम्राट अशोक ने तीसरी शताब्दी ईसा पूर्व में लुम्बिनी की यात्रा की थी और बुद्ध के जन्मस्थान को चिह्नित करने के लिए एक स्तंभ (Pillar) बनवाया था।","explanationEn":"Emperor Ashoka visited Lumbini in the 3rd century BCE and erected a pillar to mark the birthplace of the Buddha.","memoryTip":"बुद्ध ने ''लुम्बिनी'' के वन में जन्म लिया।","memoryTipEn":"Lumbini is where the Light began.","related":["Bodh Gaya (Enlightenment)","Sarnath (First Sermon)","Kushinagar (Death)"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GBZabXwcyNdeCG16Fa6UB', 'General Knowledge', 'भगवान महाबीर जैन धर्म के कौनसे तीर्थंकर थे?', 'Lord Mahavira was which Tirthankara of Jainism?', '24वें (अंतिम)', '24th (Last)', 95, 0, '{"facts":["उनका जन्म वैशाली के पास कुंडाग्राम में हुआ था।","उनके बचपन का नाम वर्धमान था और उनका प्रतीक चिन्ह ''शेर'' (Lion) है।"],"factsEn":["He was born in Kundagrama near Vaishali.","His childhood name was Vardhamana and his symbol is the ''Lion''."],"explanationHi":"महावीर ने ही जैन धर्म के पांचवें व्रत ''ब्रह्मचर्य'' (Celibacy) को जोड़ा, बाकी चार व्रत पार्श्वनाथ (23वें तीर्थंकर) द्वारा दिए गए थे।","explanationEn":"Mahavira added the fifth vow ''Brahmacharya'' (Celibacy) to Jainism; the other four vows were given by Parshvanatha (23rd Tirthankara).","memoryTip":"24 घंटे महावीर के सिद्धांतों का पालन करो।","memoryTipEn":"Mahavira finalized the 24.","related":["Rishabhanatha (1st)","Parshvanatha (23rd)","Ahimsa"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FDVhULhmo1KYXW7bVJXui', 'General Knowledge', 'भारत की पहली महिला राष्ट्रपति कौन हैं?', 'Who is the first female President of India?', 'प्रतिभा पाटिल', 'Pratibha Patil', 94, 0, '{"facts":["उन्होंने 2007 से 2012 तक भारत के 12वें राष्ट्रपति के रूप में कार्य किया।","राष्ट्रपति बनने से पहले वे राजस्थान की राज्यपाल थीं।"],"factsEn":["She served as the 12th President of India from 2007 to 2012.","Before becoming President, she was the Governor of Rajasthan."],"explanationHi":"वे स्वतंत्र भारत के इतिहास में सर्वोच्च संवैधानिक पद पर पहुंचने वाली पहली महिला बनीं। (द्रौपदी मुर्मू दूसरी महिला और पहली आदिवासी महिला हैं)।","explanationEn":"She became the first woman in the history of independent India to reach the highest constitutional office. (Droupadi Murmu is the second woman and first tribal woman).","memoryTip":"''प्रतिभा'' ने देश के सबसे बड़े पद पर अपना परचम लहराया।","memoryTipEn":"Pratibha proved women can lead.","related":["Droupadi Murmu","Indira Gandhi (First Female PM)","President of India"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('P1C8TO4pTh8B9whEzqwlH', 'General Knowledge', 'कटक (Cuttack) किस नदी पर बसा है?', 'Cuttack is situated on the banks of which river?', 'महानदी', 'Mahanadi', 90, 0, '{"facts":["कटक ओडिशा का एक प्रमुख और ऐतिहासिक शहर है।","नेताजी सुभाष चंद्र बोस का जन्म कटक में ही हुआ था।"],"factsEn":["Cuttack is a major and historical city in Odisha.","Netaji Subhas Chandra Bose was born in Cuttack."],"explanationHi":"यह शहर महानदी और उसकी प्रमुख वितरिका काठजोड़ी के मुहाने पर स्थित है, जिसे ओडिशा की ''मिलेनियम सिटी'' भी कहा जाता है।","explanationEn":"The city is located at the apex of the Mahanadi and its major distributary Kathajodi, and is also known as the ''Millennium City'' of Odisha.","memoryTip":"महानदी पर कटक (कटक-कटक दांत बजते हैं)।","memoryTipEn":"Cuttack sits on the Mahanadi.","related":["Hirakud Dam","Odisha","Subhas Chandra Bose"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('519iF0npryYo0OJYX7O2z', 'General Science', 'बाइनरी (Binary) भाषा में कितने अक्षर होते हैं?', 'How many characters (digits) are there in the binary language?', '2 (0 और 1)', '2 (0 and 1)', 95, 0, '{"facts":["बाइनरी सिस्टम आधार-2 (Base-2) संख्या प्रणाली है।","कंप्यूटर की सभी गणनाएं और डेटा स्टोरेज इसी बाइनरी भाषा में होते हैं।"],"factsEn":["The binary system is a Base-2 numeral system.","All computer calculations and data storage occur in this binary language."],"explanationHi":"कंप्यूटर ट्रांजिस्टर का उपयोग करते हैं जो केवल दो अवस्थाओं को पहचानते हैं: ''ऑन'' (1) और ''ऑफ़'' (0)।","explanationEn":"Computers use transistors that only recognize two states: ''On'' (1) and ''Off'' (0).","memoryTip":"बाइ (Bi) का मतलब ही दो होता है।","memoryTipEn":"Binary means ''two'' (0 and 1).","related":["Bits and Bytes","Boolean Logic","Computer Programming"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-rRJ98YMFz8tZB53J9CEn', 'General Science', 'LAN का विस्तार (Full form) क्या होगा?', 'What is the full form of LAN?', 'लोकल एरिया नेटवर्क (Local Area Network)', 'Local Area Network', 93, 0, '{"facts":["यह एक कंप्यूटर नेटवर्क है जो एक छोटे भौगोलिक क्षेत्र (जैसे घर, स्कूल या ऑफिस) में कंप्यूटरों को जोड़ता है।","WAN (Wide Area Network) बड़े क्षेत्रों (देश या दुनिया) को जोड़ता है।"],"factsEn":["It is a computer network that interconnects computers within a limited area (like a home, school, or office).","WAN (Wide Area Network) covers larger areas (countries or the world)."],"explanationHi":"LAN का उपयोग करके एक ही इमारत में मौजूद कई कंप्यूटर प्रिंटर, फाइलें और इंटरनेट कनेक्शन साझा (Share) कर सकते हैं।","explanationEn":"Using a LAN, multiple computers in the same building can share printers, files, and internet connections.","memoryTip":"''लोकल'' काम के लिए ''LAN'' लगाते हैं।","memoryTipEn":"Local connects close by.","related":["WAN","Wi-Fi","Ethernet"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('pF-ONqvLreACxMMml3zJ4', 'General Knowledge', 'गौतम बुद्ध की मृत्यु कहाँ हुई थी?', 'Where did Gautam Buddha die (attain Mahaparinirvana)?', 'कुशीनगर में', 'Kushinagar', 96, 0, '{"facts":["कुशीनगर उत्तर प्रदेश राज्य में स्थित है।","बौद्ध धर्म में उनकी मृत्यु की इस घटना को ''महापरिनिर्वाण'' (Mahaparinirvana) कहा जाता है।"],"factsEn":["Kushinagar is located in the state of Uttar Pradesh.","In Buddhism, the event of his death is called ''Mahaparinirvana''."],"explanationHi":"80 वर्ष की आयु में 483 ईसा पूर्व में कुशीनगर (मल्ल गणराज्य) में उन्होंने अपने शरीर का त्याग किया।","explanationEn":"He left his physical body at the age of 80 in 483 BCE in Kushinagar (Malla Republic).","memoryTip":"बुद्ध को ''कुशी'' (खुशी) से ''नगर'' (कुशीनगर) में मोक्ष मिला।","memoryTipEn":"Kushinagar brought peace to the Buddha.","related":["Mahaparinirvana","Lumbini (Birth)","Bodh Gaya (Enlightenment)"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-iyRP9iOdpi00MSYUOZSA', 'General Knowledge', 'गोवा पुर्तगाली शासन से कब आजाद हुआ?', 'When was Goa liberated from Portuguese rule?', '1961', '1961', 94, 0, '{"facts":["भारतीय सेना ने ''ऑपरेशन विजय'' (Operation Vijay) के तहत गोवा को मुक्त कराया।","पुर्तगालियों ने गोवा पर लगभग 450 वर्षों तक शासन किया था।"],"factsEn":["The Indian Army liberated Goa under ''Operation Vijay''.","The Portuguese ruled Goa for about 450 years."],"explanationHi":"पुर्तगाली सबसे पहले भारत आने वाले यूरोपीय (1498) थे और सबसे अंत में (1961 में) भारत से जाने वाले भी वही थे।","explanationEn":"The Portuguese were the first Europeans to arrive in India (1498) and the last to leave (1961).","memoryTip":"1947 में देश आज़ाद हुआ, लेकिन गोवा को 14 साल और लग गए (1961)।","memoryTipEn":"Goa gained freedom in ''61.","related":["Operation Vijay","Vasco da Gama","Daman and Diu"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KcKqMiIjxXyKfmQzlrcrN', 'General Knowledge', 'बक्सर का युद्ध कब हुआ जिसके परिणामस्वरूप अंग्रेजों का बंगाल, बिहार और ओड़िसा पर अधिकार हो गया था?', 'When did the Battle of Buxar take place, resulting in British control over Bengal, Bihar, and Odisha?', '1764 में', 'In 1764', 96, 0, '{"facts":["यह युद्ध हेक्टर मुनरो के नेतृत्व वाली ब्रिटिश ईस्ट इंडिया कंपनी और मीर कासिम, शुजा-उद-दौला तथा शाह आलम द्वितीय की संयुक्त सेना के बीच लड़ा गया।","इसके बाद 1765 में ''इलाहाबाद की संधि'' (Treaty of Allahabad) हुई।"],"factsEn":["The battle was fought between the British East India Company led by Hector Munro and the combined forces of Mir Qasim, Shuja-ud-Daula, and Shah Alam II.","It was followed by the ''Treaty of Allahabad'' in 1765."],"explanationHi":"प्लासी के युद्ध (1757) ने अंग्रेजों को बंगाल में पैर जमाने का मौका दिया, जबकि बक्सर के युद्ध (1764) ने उन्हें पूरे उत्तर भारत में एक मजबूत राजनीतिक ताकत बना दिया।","explanationEn":"While the Battle of Plassey (1757) gave the British a foothold in Bengal, the Battle of Buxar (1764) firmly established them as a political power in North India.","memoryTip":"''बक्सर'' (Buxar) में अंग्रेजों ने 64 के स्कोर से सबको हरा दिया।","memoryTipEn":"Buxar in ''64 broke the nawabs.","related":["Battle of Plassey (1757)","Treaty of Allahabad","Hector Munro"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nesIzjfBc990FY5KY2k9k', 'General Knowledge', 'रेगुलेटिंग एक्ट (Regulating Act) कब लागु हुआ?', 'When did the Regulating Act come into force?', '1773 में', 'In 1773', 95, 0, '{"facts":["यह ब्रिटिश संसद द्वारा भारत में ईस्ट इंडिया कंपनी के कार्यों को नियंत्रित करने के लिए पारित पहला अधिनियम था।","इसी एक्ट के तहत कलकत्ता (अब कोलकाता) में एक सुप्रीम कोर्ट की स्थापना की गई।"],"factsEn":["It was the first act passed by the British Parliament to control the affairs of the East India Company in India.","Under this act, a Supreme Court was established in Calcutta."],"explanationHi":"इस एक्ट ने बंगाल के गवर्नर को ''गवर्नर-जनरल ऑफ बंगाल'' बना दिया (वारेन हेस्टिंग्स पहले गवर्नर-जनरल बने)।","explanationEn":"This act designated the Governor of Bengal as the ''Governor-General of Bengal'' (Warren Hastings became the first).","memoryTip":"कंपनी को ''रेगुलेट'' (कंट्रोल) करने के लिए 73 में पहला एक्ट आया।","memoryTipEn":"1773 Regulated the Company.","related":["Warren Hastings","Pitt''s India Act 1784","East India Company"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3mXZHz8NHwsdLtmZfRO1b', 'General Knowledge', '1857 की क्रांति के बाद अंग्रेजों ने मुगल बादशाह बहादुरशाह जफ़र को कैद करके कहाँ भेजा?', 'After the revolt of 1857, where did the British exile the Mughal Emperor Bahadur Shah Zafar?', 'बर्मा (म्यांमार) के रंगून में', 'Rangoon, Burma (Myanmar)', 93, 0, '{"facts":["उन्हें हुमायूं के मकबरे से गिरफ्तार किया गया था।","रंगून में ही 1862 में उनकी मृत्यु हो गई और उन्हें वहीं दफनाया गया।"],"factsEn":["He was arrested from Humayun''s Tomb.","He died in Rangoon in 1862 and was buried there."],"explanationHi":"ज़फ़र एक शायर थे; उन्होंने अपनी एक ग़ज़ल में लिखा था कि उन्हें अपनी मातृभूमि में दफन होने के लिए \"दो गज़ ज़मीन\" भी नसीब नहीं हुई।","explanationEn":"Zafar was a poet; he famously wrote in a ghazal how unfortunate he was not to get even ''two yards of land'' for burial in his motherland.","memoryTip":"मुग़ल सल्तनत का ''रंग'' ''रंगून'' में फीका पड़ गया।","memoryTipEn":"Zafar rested in Rangoon.","related":["Revolt of 1857","Mughal Empire","Humayun''s Tomb"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4cNos8YxeLRYFKFu5z69l', 'General Knowledge', 'गाँधी जी दक्षिणी अफ्रीका से भारत कब लौटे?', 'When did Gandhiji return to India from South Africa?', '9 जनवरी 1915', '9 January 1915', 95, 0, '{"facts":["गांधीजी लगभग 21 वर्षों तक दक्षिण अफ्रीका में रहे थे।","इसी दिन की याद में भारत में ''प्रवासी भारतीय दिवस'' (Pravasi Bharatiya Divas) मनाया जाता है।"],"factsEn":["Gandhiji lived in South Africa for about 21 years.","To commemorate this day, ''Pravasi Bharatiya Divas'' (NRI Day) is celebrated in India."],"explanationHi":"उनके गुरु गोपाल कृष्ण गोखले के अनुरोध पर वे भारत लौटे और भारतीय राष्ट्रीय आंदोलन की कमान संभाली।","explanationEn":"He returned to India at the request of his mentor Gopal Krishna Gokhale and took charge of the Indian National Movement.","memoryTip":"9 जनवरी को देश के सबसे बड़े ''प्रवासी'' (गांधी जी) लौट कर आए।","memoryTipEn":"Jan 9 marks the return of the Mahatma.","related":["Pravasi Bharatiya Divas","Gopal Krishna Gokhale","Champaran Satyagraha"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('h8Yi1VVKWHU2KgOzV_o7i', 'General Knowledge', 'भारत की पहली बोलती फिल्म कौनसी थी?', 'Which was India''s first talkie (sound) film?', 'आलमआरा', 'Alam Ara', 94, 0, '{"facts":["यह फिल्म 1931 में रिलीज़ हुई थी।","इसके निर्देशक अर्देशिर ईरानी (Ardeshir Irani) थे।"],"factsEn":["This film was released in 1931.","Its director was Ardeshir Irani."],"explanationHi":"पहली मूक (बिना आवाज की) फिल्म ''राजा हरिश्चंद्र'' (1913) थी, जबकि ''आलम आरा'' ने भारतीय सिनेमा में संवाद और गानों की शुरुआत की।","explanationEn":"The first silent film was ''Raja Harishchandra'' (1913), while ''Alam Ara'' introduced dialogue and songs to Indian cinema.","memoryTip":"सिनेमा में आवाज़ आने से ''आलम'' (दुनिया) बदल गया।","memoryTipEn":"Alam Ara added audio.","related":["Raja Harishchandra","Ardeshir Irani","Indian Cinema"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zGwcbBMjUOhFbqjpPuw8X', 'General Knowledge', 'क्षेत्रफल की दृष्टि से भारत का विश्व में कौनसा स्थान है?', 'What is India''s rank in the world in terms of area?', 'सातवाँ (7th)', 'Seventh (7th)', 95, 0, '{"facts":["भारत का कुल क्षेत्रफल 3.28 मिलियन वर्ग किलोमीटर है।","रूस, कनाडा, चीन, अमेरिका, ब्राजील और ऑस्ट्रेलिया क्षेत्रफल में भारत से बड़े हैं।"],"factsEn":["India''s total area is 3.28 million square kilometers.","Russia, Canada, China, USA, Brazil, and Australia are larger than India in area."],"explanationHi":"जनसंख्या के मामले में भारत अब दुनिया का सबसे बड़ा देश बन गया है, लेकिन भौगोलिक क्षेत्रफल में यह 7वें स्थान पर ही है।","explanationEn":"In terms of population, India has now become the largest country in the world, but in geographical area, it remains at the 7th position.","memoryTip":"दुनिया के 7 अजूबे और 7वें नंबर पर हमारा भारत (क्षेत्रफल में)।","memoryTipEn":"7th largest landmass.","related":["Russia (1st)","Geography of India","Population (1st)"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oBByEfqcRcyXOl6_mRhGH', 'General Knowledge', 'भारत की स्थलीय सीमा (Land border) कितनी है?', 'What is the length of India''s land border?', '15,200 कि.मी.', '15,200 km', 88, 0, '{"facts":["भारत 7 देशों के साथ अपनी जमीनी सीमा साझा करता है।","सबसे लंबी स्थलीय सीमा बांग्लादेश (4,096 किमी) के साथ लगती है।"],"factsEn":["India shares its land border with 7 countries.","The longest land border is shared with Bangladesh (4,096 km)."],"explanationHi":"भारत की तटीय रेखा (Coastline) की लंबाई 7,516 किलोमीटर है (द्वीपों सहित)।","explanationEn":"The length of India''s coastline is 7,516 kilometers (including islands).","memoryTip":"15 और 200 (15,200) किमी लंबी ज़मीन की सरहद।","memoryTipEn":"15,200 km of terrestrial boundaries.","related":["Bangladesh Border","Coastline of India (7516 km)","Line of Control (LAC)"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('A3Rp-F9nbr1R_ERA7etyr', 'General Knowledge', 'भारत का पूर्व से पश्चिम तक विस्तार कितना है?', 'What is the East to West extent of India?', '2933 कि.मी.', '2933 km', 87, 0, '{"facts":["उत्तर से दक्षिण तक भारत का विस्तार 3,214 कि.मी. है।","पूर्वी छोर अरुणाचल प्रदेश (किबिथू) और पश्चिमी छोर गुजरात (गुहार मोती) है।"],"factsEn":["The North to South extent of India is 3,214 km.","The easternmost point is Kibithu (Arunachal Pradesh) and the westernmost is Guhar Moti (Gujarat)."],"explanationHi":"पूर्व-पश्चिम विस्तार के कारण गुजरात और अरुणाचल प्रदेश के स्थानीय समय में लगभग 2 घंटे का अंतर होता है।","explanationEn":"Due to the East-West extent, there is a time difference of almost 2 hours in the local time between Gujarat and Arunachal Pradesh.","memoryTip":"2-9-3-3 (दो नौ तीन तीन)।","memoryTipEn":"2933 across the middle.","related":["North-South Extent (3214 km)","Indian Standard Time","Indira Col / Indira Point"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bg45INjHI7RfMw23pAqGx', 'General Knowledge', 'तिरंगे झंडे को संविधान सभा ने कब राष्ट्रीय झंडे के रूप में अपनाया?', 'When did the Constituent Assembly adopt the Tricolor as the National Flag?', '22 जुलाई 1947 को', 'On July 22, 1947', 96, 0, '{"facts":["राष्ट्रीय ध्वज का डिजाइन पिंगली वेंकय्या (Pingali Venkayya) ने तैयार किया था।","झंडे की लंबाई और चौड़ाई का अनुपात 3:2 है।"],"factsEn":["The design of the National Flag was prepared by Pingali Venkayya.","The ratio of the length to the width of the flag is 3:2."],"explanationHi":"भारत को स्वतंत्रता मिलने (15 अगस्त) से ठीक कुछ दिन पहले इस ध्वज को आधिकारिक तौर पर अपनाया गया था।","explanationEn":"The flag was officially adopted just a few days before India attained independence (August 15).","memoryTip":"आज़ादी से 24 दिन पहले (22 जुलाई) तिरंगे को अपनाया।","memoryTipEn":"July 22 secured the Tricolor.","related":["Pingali Venkayya","Ashoka Chakra","Flag Code of India"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('X18MD7KcP4lm08-XnS_iy', 'General Knowledge', '''जन-गण-मन'' को संविधान सभा ने राष्ट्रगान कब घोषित किया?', 'When did the Constituent Assembly declare ''Jana Gana Mana'' as the National Anthem?', '24 जनवरी, 1950 को', 'On January 24, 1950', 95, 0, '{"facts":["इसी दिन ''वंदे मातरम'' को राष्ट्रगीत (National Song) का दर्जा भी दिया गया।","यह संविधान सभा की अंतिम बैठक का दिन था।"],"factsEn":["On the same day, ''Vande Mataram'' was accorded the status of the National Song.","It was the day of the last meeting of the Constituent Assembly."],"explanationHi":"गणतंत्र दिवस (26 जनवरी 1950) से ठीक दो दिन पहले भारत के राष्ट्रगान और राष्ट्रगीत को आधिकारिक रूप से अपनाया गया।","explanationEn":"Exactly two days before Republic Day (Jan 26, 1950), India''s National Anthem and National Song were officially adopted.","memoryTip":"गणतंत्र बनने से 2 दिन पहले (24 जन) गान तय हुआ।","memoryTipEn":"Two days before Republic Day.","related":["Rabindranath Tagore","Vande Mataram","Republic Day"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Jp_iSgAmp5Hq7sNspbmcX', 'General Knowledge', '''खुदा बक्श'' पुस्तकालय कहाँ है?', 'Where is the ''Khuda Bakhsh'' Oriental Public Library located?', 'पटना', 'Patna', 86, 0, '{"facts":["यह 1891 में आम जनता के लिए खोला गया था।","यह भारत के राष्ट्रीय पुस्तकालयों में से एक है।"],"factsEn":["It was opened to the public in 1891.","It is one of the National Libraries of India."],"explanationHi":"इस पुस्तकालय में दुर्लभ फारसी और अरबी पांडुलिपियों (Manuscripts) और राजपूत तथा मुगल चित्रों का एक असाधारण संग्रह है।","explanationEn":"The library houses an extraordinary collection of rare Persian and Arabic manuscripts and Rajput and Mughal paintings.","memoryTip":"''खुदा'' ने ''पटना'' को यह लाइब्रेरी ''बख्शी'' (दी) है।","memoryTipEn":"Khuda Bakhsh is Patna''s pride.","related":["National Library of India (Kolkata)","Arabic Manuscripts","Bihar"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kg_P8uNwbJ0_nue44O6vQ', 'General Knowledge', '1784 में कोलकाता में किसने ''एशियाटिक सोसाइटी'' की स्थापना की थी?', 'Who founded the ''Asiatic Society'' in Kolkata in 1784?', 'विलियम जोन्स', 'Sir William Jones', 93, 0, '{"facts":["सर विलियम जोन्स एक एंग्लो-वेल्श दार्शनिक और ब्रिटिश सुप्रीम कोर्ट के न्यायाधीश थे।","इस संस्था का उद्देश्य एशियाई (मुख्य रूप से भारतीय) इतिहास, साहित्य और कला का अध्ययन करना था।"],"factsEn":["Sir William Jones was an Anglo-Welsh philologist and a judge of the British Supreme Court.","The society aimed to study Asian (primarily Indian) history, literature, and art."],"explanationHi":"इसी संस्था ने भारत की प्राचीन संस्कृतियों की खोज करने और गीता तथा उपनिषदों जैसी पुस्तकों का अंग्रेजी में अनुवाद करने का बीड़ा उठाया था।","explanationEn":"This institution spearheaded the discovery of ancient Indian cultures and the translation of books like the Gita and Upanishads into English.","memoryTip":"एशिया के इतिहास को ''जोन्स'' ने खोजा।","memoryTipEn":"Jones joined the Asiatic study.","related":["Orientalism","Warren Hastings","Indology"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XC6rKqSC5QkqYewrEC1Xx', 'General Knowledge', 'भारत में बैंकों का राष्ट्रीयकरण (Nationalization of Banks) कब किया गया?', 'When were banks nationalized in India?', '1969 में (14 प्रमुख बैंकों का)', 'In 1969 (14 major banks)', 95, 0, '{"facts":["यह साहसिक कदम तत्कालीन प्रधानमंत्री इंदिरा गांधी द्वारा उठाया गया था।","1980 में 6 और बैंकों का राष्ट्रीयकरण किया गया।"],"factsEn":["This bold step was taken by the then Prime Minister Indira Gandhi.","In 1980, 6 more banks were nationalized."],"explanationHi":"राष्ट्रीयकरण का मुख्य उद्देश्य ग्रामीण क्षेत्रों और कृषि (Agriculture) तक बैंकिंग सेवाओं और ऋण (Credit) को पहुँचाना था, जो पहले केवल बड़े उद्योगपतियों तक सीमित थे।","explanationEn":"The main goal was to extend banking services and credit to rural areas and agriculture, which were previously limited to large industrialists.","memoryTip":"69 में इंदिरा ने 14 बैंकों को ''नेशनल'' बना दिया।","memoryTipEn":"1969 marked the banking revolution.","related":["Indira Gandhi","Reserve Bank of India","Five-Year Plans"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('x75dgR1WWU-gczgeFrjTE', 'General Knowledge', 'किस संविधान संशोधन द्वारा 6-14 वर्ष की आयु के बच्चों के लिए शिक्षा को मौलिक अधिकार बनाया गया?', 'By which constitutional amendment was education made a fundamental right for children aged 6-14 years?', '86वाँ संशोधन (2002)', '86th Amendment (2002)', 97, 0, '{"facts":["इस संशोधन ने संविधान के भाग III में नया ''अनुच्छेद 21A'' जोड़ा।","इसी के आधार पर बाद में ''शिक्षा का अधिकार अधिनियम'' (RTE Act, 2009) पारित किया गया।"],"factsEn":["This amendment added a new ''Article 21A'' to Part III of the Constitution.","Based on this, the ''Right to Education Act'' (RTE Act, 2009) was later passed."],"explanationHi":"यह सुनिश्चित करता है कि राज्य सभी बच्चों को 6 से 14 वर्ष की आयु तक मुफ्त और अनिवार्य शिक्षा (Free and Compulsory Education) प्रदान करेगा।","explanationEn":"It ensures that the State shall provide free and compulsory education to all children of the age of 6 to 14 years.","memoryTip":"8 और 6 (86) मिलकर बच्चों की ''शिक्षा'' तय करते हैं।","memoryTipEn":"86th opens the school gates.","related":["Article 21A","RTE Act 2009","Fundamental Duties (11th duty added)"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qjuRGy5Mbuq6jXkpJLOC7', 'General Knowledge', 'किस मौलिक अधिकार को 44वें संविधान संशोधन द्वारा हटा दिया गया?', 'Which fundamental right was removed by the 44th Constitutional Amendment?', 'संपत्ति का अधिकार (Right to Property)', 'Right to Property', 96, 0, '{"facts":["यह संशोधन 1978 में मोरारजी देसाई की जनता पार्टी सरकार द्वारा लाया गया था।","संपत्ति का अधिकार पहले अनुच्छेद 31 के तहत एक मौलिक अधिकार था।"],"factsEn":["This amendment was brought in 1978 by the Janata Party government of Morarji Desai.","The Right to Property was previously a fundamental right under Article 31."],"explanationHi":"हटाए जाने के बाद, इसे अनुच्छेद 300A के तहत केवल एक ''कानूनी अधिकार'' (Legal Right) बना दिया गया है।","explanationEn":"After removal, it was made merely a ''Legal Right'' under Article 300A.","memoryTip":"4 और 4 (44) ने संपत्ति का ''बराबर'' बंटवारा कर दिया (अधिकार हटा दिया)।","memoryTipEn":"44th took the property right away.","related":["Article 300A","42nd Amendment","Fundamental Rights"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('U5hFay4tTkBfGa5lacoPS', 'General Knowledge', '23.5 डिग्री उत्तरी अक्षांश रेखा (North Latitude) क्या कहलाती है?', 'What is the 23.5 degree North latitude line called?', 'कर्क रेखा (Tropic of Cancer)', 'Tropic of Cancer', 95, 0, '{"facts":["यह रेखा भारत के लगभग बीचों-बीच से होकर गुजरती है।","यह भारत के 8 राज्यों (गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा, मिजोरम) से गुजरती है।"],"factsEn":["This line passes almost through the middle of India.","It passes through 8 Indian states."],"explanationHi":"23.5 डिग्री दक्षिणी अक्षांश को मकर रेखा (Tropic of Capricorn) कहा जाता है। 21 जून को सूर्य कर्क रेखा पर सीधा चमकता है (Summer Solstice)।","explanationEn":"The 23.5 degree South latitude is called the Tropic of Capricorn. The sun shines directly over the Tropic of Cancer on June 21 (Summer Solstice).","memoryTip":"मित्र पर गमछा झार (मिजोरम, त्रिपुरा, पश्चिम बंगाल, राजस्थान, गुजरात, मध्य प्रदेश, छत्तीसगढ़, झारखंड)।","memoryTipEn":"Cancer sits in the North (23.5).","related":["Tropic of Capricorn","Equator","Summer Solstice"]}', 'published', 1776084698, 1776084698);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jJUW_Y2EUeoOgMr7TVdc4', 'General Knowledge', 'सशस्त्र सेना झंडा दिवस कब मनाया जाता है?', 'When is the Armed Forces Flag Day celebrated?', '7 दिसंबर', '7 December', 92, 0, '{"facts":["यह दिवस 1949 से प्रतिवर्ष मनाया जा रहा है।","इस दिन धन एकत्र कर इसका उपयोग सैनिकों और उनके परिवारों के कल्याण के लिए किया जाता है।"],"factsEn":["This day has been observed annually since 1949.","Funds collected on this day are used for the welfare of soldiers and their families."],"explanationHi":"यह दिन भारत की रक्षा करने वाले शहीदों और वर्दीधारी पुरुषों व महिलाओं को सम्मानित करने के लिए समर्पित है।","explanationEn":"This day is dedicated to honoring the martyrs and the men and women in uniform who protect India.","memoryTip":"साल के आखिरी महीने (दिसंबर) के 7वें दिन सेना का झंडा फहराता है।","memoryTipEn":"December 7 honors the armed forces'' flag.","related":["Army Day (Jan 15)","Navy Day (Dec 4)","Air Force Day (Oct 8)"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('LHsUa1U7Mnw8qSkwtGRhB', 'General Knowledge', 'भारत-पाक सीमा रेखा किस नाम से पुकारी जाती है?', 'By what name is the India-Pakistan border line called?', 'रेडक्लिफ रेखा (Radcliffe Line)', 'Radcliffe Line', 96, 0, '{"facts":["यह रेखा 17 अगस्त 1947 को प्रकाशित हुई थी।","इसका नाम इसके वास्तुकार, सर सिरिल रेडक्लिफ के नाम पर रखा गया है।"],"factsEn":["This line was published on August 17, 1947.","It is named after its architect, Sir Cyril Radcliffe."],"explanationHi":"यह सीमा रेखा विभाजन के समय भारत और नव-निर्मित पाकिस्तान (पश्चिमी और पूर्वी पाकिस्तान, अब बांग्लादेश) के बीच खींची गई थी।","explanationEn":"This border line was drawn during the partition between India and newly formed Pakistan (West and East Pakistan, now Bangladesh).","memoryTip":"भारत-पाक सीमा पर हमेशा ''रेड'' (खून/खतरा) का अलर्ट रहता है, इसलिए रेडक्लिफ।","memoryTipEn":"Redcliffe is the red line of partition.","related":["McMahon Line (India-China)","Durand Line","Line of Control (LoC)"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jP1mmGvap8YBVhhbwa09y', 'General Knowledge', 'भारत में एकमात्र सक्रिय ज्वालामुखी (Active Volcano) कहाँ है?', 'Where is the only active volcano in India located?', 'बैरन द्वीप (अंडमान निकोबार)', 'Barren Island (Andaman & Nicobar)', 95, 0, '{"facts":["यह अंडमान सागर में पोर्ट ब्लेयर से लगभग 138 किमी उत्तर-पूर्व में स्थित है।","यह दक्षिण एशिया का भी एकमात्र पुष्ट सक्रिय ज्वालामुखी है।"],"factsEn":["It is located in the Andaman Sea, about 138 km northeast of Port Blair.","It is also the only confirmed active volcano in South Asia."],"explanationHi":"बैरन (Barren) का अर्थ है ''बंजर'', क्योंकि यहाँ कोई मानव आबादी नहीं है और इसका पर्यावरण ज्वालामुखी के कारण कठोर है।","explanationEn":"Barren means ''empty'', as it has no human population and its environment is harsh due to the volcano.","memoryTip":"ज्वालामुखी के कारण यह द्वीप ''बंजर'' (Barren) हो गया है।","memoryTipEn":"Barren Island is barren because of the lava.","related":["Narcondam Island","Andaman and Nicobar Islands","Ring of Fire"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('diqNtbTLf7hnZ0NzbztyT', 'General Knowledge', 'किस भारतीय राज्य की दो राजधानियाँ हैं (ऐतिहासिक रूप से)?', 'Which Indian state has two capitals (historically)?', 'जम्मू-कश्मीर', 'Jammu and Kashmir', 88, 0, '{"facts":["श्रीनगर ग्रीष्मकालीन (Summer) राजधानी और जम्मू शीतकालीन (Winter) राजधानी होती थी।","2019 में जम्मू-कश्मीर को एक केंद्र शासित प्रदेश (Union Territory) बना दिया गया है।"],"factsEn":["Srinagar was the summer capital and Jammu the winter capital.","In 2019, Jammu & Kashmir was reconstituted as a Union Territory."],"explanationHi":"यह 6 महीने राजधानी बदलने की परंपरा डोगरा शासकों द्वारा ''दरबार मूव'' के नाम से शुरू की गई थी, जिसे हाल ही में समाप्त कर दिया गया है। (नोट: हिमाचल प्रदेश, महाराष्ट्र और उत्तराखंड की भी दो राजधानियां हैं)।","explanationEn":"This tradition of shifting the capital every 6 months, known as ''Darbar Move'', was started by Dogra rulers and has been recently halted. (Note: HP, Maharashtra, and Uttarakhand also have two capitals).","memoryTip":"ठंड में ''जम्मू'' जाओ, गर्मी में ''श्रीनगर''।","memoryTipEn":"J&K changes base with the weather.","related":["Darbar Move","Article 370","Himachal Pradesh (Shimla/Dharamshala)"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UGvvJMBvKtzcbPhFcoRBQ', 'General Knowledge', 'अमेरिका ने कौनसा राज्य 1867 में रूस से खरीदा था?', 'Which state did the USA buy from Russia in 1867?', 'अलास्का', 'Alaska', 91, 0, '{"facts":["अमेरिका ने अलास्का को रूस से मात्र 7.2 मिलियन डॉलर (2 सेंट प्रति एकड़) में खरीदा था।","क्षेत्रफल के हिसाब से अलास्का अमेरिका का सबसे बड़ा राज्य है।"],"factsEn":["The US bought Alaska from Russia for just $7.2 million (2 cents an acre).","Alaska is the largest US state by area."],"explanationHi":"रूस को आर्थिक तंगी और युद्ध के खतरे के कारण इसे बेचना पड़ा। उस समय इस सौदे की आलोचना ''सीवार्ड की मूर्खता'' (Seward''s Folly) के रूप में की गई थी, जो बाद में संसाधनों से भरपूर निकला।","explanationEn":"Russia had to sell it due to financial strain and war threats. The deal was mocked as ''Seward''s Folly'' at the time, but it later proved extremely rich in resources.","memoryTip":"रूस ने अपना ''लास्ट'' हिस्सा (अलास्का) अमेरिका को बेच दिया।","memoryTipEn":"Alaska was Russia''s lost land.","related":["Seward''s Folly","Russian Empire","USA 50 States"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('weT6lBhLX7Xk3TnCkg_vy', 'General Knowledge', 'विश्व विकलांग दिवस (International Day of Persons with Disabilities) कब मनाया जाता है?', 'When is the International Day of Persons with Disabilities celebrated?', '3 दिसंबर', '3 December', 90, 0, '{"facts":["इसे संयुक्त राष्ट्र (UN) द्वारा 1992 से मनाया जा रहा है।","इसका उद्देश्य विकलांग व्यक्तियों के अधिकारों और कल्याण को बढ़ावा देना है।"],"factsEn":["It is being observed by the UN since 1992.","The aim is to promote the rights and well-being of persons with disabilities."],"explanationHi":"भारत सरकार ने विकलांग शब्द की जगह सम्मानजनक शब्द ''दिव्यांग'' (Divyang) का प्रयोग शुरू किया है।","explanationEn":"The Indian Government has started using the respectful term ''Divyang'' (people with divine abilities) instead of handicapped.","memoryTip":"साल के आखिरी महीने (दिसंबर) की 3 तारीख को दिव्यांगों का सम्मान होता है।","memoryTipEn":"December 3 stands for Dignity and Disability.","related":["United Nations","Divyangjan","Accessibility"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('slJTo9A7nBR39HUuNwr6S', 'General Knowledge', 'होपमैन कप (Hopman Cup) किस खेल से संबंधित है?', 'Hopman Cup is related to which sport?', 'टेनिस', 'Tennis', 86, 0, '{"facts":["यह एक अंतरराष्ट्रीय मिश्रित (Mixed-gender) टीम टेनिस टूर्नामेंट है।","इसे प्रसिद्ध ऑस्ट्रेलियाई टेनिस खिलाड़ी हैरी होपमैन के नाम पर शुरू किया गया था।"],"factsEn":["It is an international mixed-gender team tennis tournament.","It is named after famous Australian tennis player Harry Hopman."],"explanationHi":"इस कप में दुनिया भर के देशों की टीमें भाग लेती हैं, जिसमें एक पुरुष और एक महिला खिलाड़ी शामिल होते हैं।","explanationEn":"Teams from countries around the world participate in this cup, comprising one male and one female player.","memoryTip":"टेनिस खेलते समय हमेशा जीतने की ''होप'' (Hope) रहती है।","memoryTipEn":"Hoping for a Tennis Trophy.","related":["Davis Cup","Billie Jean King Cup","Grand Slam"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('K2RKfwHUIXp-g4DAmhjSP', 'General Knowledge', 'नवगठित तेलंगाना राज्य का पहला मुख्यमंत्री कौन बना?', 'Who became the first Chief Minister of the newly formed state of Telangana?', 'के. चंद्रशेखर राव', 'K. Chandrashekar Rao (KCR)', 93, 0, '{"facts":["तेलंगाना भारत का 29वां राज्य बना (अब 28वां, जम्मू कश्मीर के UT बनने के बाद)।","इस राज्य का गठन 2 जून 2014 को आंध्र प्रदेश से अलग होकर हुआ।"],"factsEn":["Telangana became the 29th state of India (now 28th after J&K became a UT).","It was formed on June 2, 2014, separating from Andhra Pradesh."],"explanationHi":"केसीआर (KCR) ने भारत राष्ट्र समिति (पूर्व में TRS) पार्टी की स्थापना की थी और अलग राज्य के आंदोलन का नेतृत्व किया था।","explanationEn":"KCR founded the Bharat Rashtra Samithi (formerly TRS) party and spearheaded the separate statehood movement.","memoryTip":"तेलंगाना के आसमान पर ''चंद्र'' (चंद्रशेखर) चमका।","memoryTipEn":"KCR created Telangana''s crown.","related":["Telangana Movement","Andhra Pradesh Reorganisation Act, 2014","Hyderabad"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TU-Bo510MEzwwHB6l9iWa', 'General Knowledge', 'भारत-श्रीलंका के बीच कौनसी खाड़ी (Gulf) है?', 'Which gulf is located between India and Sri Lanka?', 'मन्नार की खाड़ी', 'Gulf of Mannar', 95, 0, '{"facts":["यह खाड़ी हिंद महासागर में लक्षद्वीप सागर का एक हिस्सा है।","पाक जलडमरूमध्य (Palk Strait) भी भारत और श्रीलंका को अलग करता है।"],"factsEn":["This gulf is a part of the Laccadive Sea in the Indian Ocean.","The Palk Strait also separates India and Sri Lanka."],"explanationHi":"यह क्षेत्र अपनी समृद्ध समुद्री जैव विविधता (Marine biodiversity) के लिए जाना जाता है और यहाँ मन्नार की खाड़ी समुद्री राष्ट्रीय उद्यान स्थित है।","explanationEn":"The region is known for its rich marine biodiversity and houses the Gulf of Mannar Marine National Park.","memoryTip":"श्रीलंका और भारत के बीच कोई ''मना'' (मन्नार) नहीं कर सकता कि गहरा नाता है।","memoryTipEn":"Mannar lies between the landmasses.","related":["Palk Strait","Ram Setu (Adam''s Bridge)","Marine National Park"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4rVlwnMN95WgINlIJaXCc', 'General Knowledge', 'अरावली पर्वतमाला की सबसे ऊँची चोटी कौनसी है?', 'Which is the highest peak of the Aravalli Range?', 'गुरु शिखर', 'Guru Shikhar', 94, 0, '{"facts":["यह राजस्थान के माउंट आबू में स्थित है।","इसकी ऊँचाई 1,722 मीटर (5,650 फीट) है।"],"factsEn":["It is located in Mount Abu, Rajasthan.","Its height is 1,722 meters (5,650 feet)."],"explanationHi":"अरावली दुनिया की सबसे पुरानी पर्वत श्रृंखलाओं (Oldest fold mountains) में से एक है। चोटी पर भगवान दत्तात्रेय का मंदिर स्थित है।","explanationEn":"The Aravallis are one of the oldest fold mountains in the world. The peak houses a temple dedicated to Lord Dattatreya.","memoryTip":"पहाड़ों में सबसे ऊंचा हमेशा ''गुरु'' होता है (गुरु शिखर)।","memoryTipEn":"Guru is the peak of knowledge and the mountain.","related":["Mount Abu","Aravalli Range","Dilwara Temples"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HV6Yynfz2BxAlmsUBax8q', 'General Knowledge', 'किस देश की समुद्री सीमा (Coastline) सबसे बड़ी है?', 'Which country has the longest coastline in the world?', 'कनाडा (Canada)', 'Canada', 96, 0, '{"facts":["कनाडा की तटीय रेखा लगभग 202,080 किलोमीटर लंबी है।","यह तीन महासागरों: प्रशांत, अटलांटिक और आर्कटिक महासागरों से घिरा हुआ है।"],"factsEn":["Canada''s coastline is approximately 202,080 kilometers long.","It is bordered by three oceans: the Pacific, Atlantic, and Arctic."],"explanationHi":"कनाडा में बहुत सारे छोटे-बड़े द्वीप (Islands) और कटी-फटी तटरेखा होने के कारण इसकी कुल समुद्री सीमा सबसे लंबी हो जाती है।","explanationEn":"Canada has numerous large and small islands and an highly indented shoreline, which makes its total coastline the longest.","memoryTip":"कनाडा की ''नाड़ी'' (नदी/समुद्र) बहुत लंबी है।","memoryTipEn":"Canada spans from coast to coast to coast.","related":["Norway (2nd longest coastline)","Indonesia","Area of Canada"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4oQWinQKYR44EHBLRuwPR', 'General Knowledge', 'किस देश की स्थल सीमा (Land border) सबसे बड़ी है?', 'Which country has the longest land border?', 'चीन (China)', 'China', 95, 0, '{"facts":["चीन की कुल स्थल सीमा 22,000 किलोमीटर से अधिक लंबी है।","यह 14 अलग-अलग देशों के साथ अपनी सीमाएं साझा करता है।"],"factsEn":["China''s total land border is over 22,000 kilometers long.","It shares its borders with 14 different countries."],"explanationHi":"अपने विशाल क्षेत्रफल और मध्य एशिया में स्थिति के कारण, चीन की सीमा रूस, भारत, मंगोलिया आदि देशों से मिलती है। (रूस भी 14 देशों से सीमा साझा करता है)।","explanationEn":"Due to its vast area and central location in Asia, China borders countries like Russia, India, Mongolia, etc. (Russia also borders 14 countries).","memoryTip":"चीन की ''दीवार'' की तरह ही उसकी सीमा भी सबसे बड़ी है।","memoryTipEn":"China''s Great Wall matches its massive border.","related":["Russia","Land Borders","Geography of China"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GVxvnVD5SANpj4A9Up5rh', 'General Knowledge', 'म्यांमार (बर्मा) की मुद्रा कौनसी है?', 'What is the currency of Myanmar (Burma)?', 'क्यात (Kyat)', 'Kyat', 89, 0, '{"facts":["म्यांमार की राजधानी ''नेपीडा'' (Naypyidaw) है।","म्यांमार भारत का एक प्रमुख पूर्वी पड़ोसी देश है।"],"factsEn":["The capital of Myanmar is ''Naypyidaw''.","Myanmar is a major eastern neighbor of India."],"explanationHi":"1989 में बर्मा का नाम बदलकर म्यांमार कर दिया गया था। यहाँ की मुद्रा को ''म्यांमार क्यात'' कहा जाता है।","explanationEn":"Burma was renamed Myanmar in 1989. Its currency is officially known as the ''Myanmar Kyat''.","memoryTip":"बर्मा में ''क्या'' (क्यात) बात है!","memoryTipEn":"Kyat is the cash in Myanmar.","related":["Naypyidaw","Yangon (Rangoon)","Asian Currencies"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vYABlcuKoWyLuqIqao84b', 'General Science', 'मौसम संबंधित परिवर्तन वायुमंडल की किस परत में होते हैं?', 'Weather-related changes occur in which layer of the atmosphere?', 'क्षोभमंडल (Troposphere)', 'Troposphere', 96, 0, '{"facts":["यह पृथ्वी के वायुमंडल की सबसे निचली परत है।","वायुमंडल का लगभग 75% द्रव्यमान और लगभग सारा जलवाष्प (Water vapor) इसी परत में है।"],"factsEn":["This is the lowest layer of Earth''s atmosphere.","About 75% of the atmosphere''s mass and almost all of its water vapor are in this layer."],"explanationHi":"बादल का बनना, बारिश, तूफान और आंधी जैसी सभी मौसम संबंधी गतिविधियां केवल क्षोभमंडल तक ही सीमित रहती हैं।","explanationEn":"All weather-related activities like cloud formation, rain, thunderstorms, and wind are confined to the troposphere.","memoryTip":"मौसम के कारण होने वाला ''क्षोभ'' (हंगामा) क्षोभमंडल में होता है।","memoryTipEn":"Tropo means change; Weather changes here.","related":["Stratosphere","Ozone Layer","Atmospheric Layers"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GihLtGTh0Qh3blSff_aDr', 'General Knowledge', 'संसार का सबसे बड़ा सागर (Sea) कौनसा है?', 'Which is the largest sea in the world?', 'दक्षिणी चीन सागर (South China Sea)', 'South China Sea', 90, 0, '{"facts":["यह प्रशांत महासागर का एक हिस्सा है।","फिलीपीन सागर (Philippine Sea) और कोरल सागर (Coral Sea) भी क्षेत्रफल में बहुत बड़े हैं।"],"factsEn":["It is a marginal sea of the Western Pacific Ocean.","The Philippine Sea and Coral Sea are also extremely large in area."],"explanationHi":"ध्यान दें: ''महासागर'' (Ocean) में प्रशांत महासागर सबसे बड़ा है, लेकिन अगर ''सागर'' (Sea - जमीन से घिरा जल क्षेत्र) की बात करें, तो दक्षिणी चीन सागर (या फिलीपीन सागर) सबसे बड़ा माना जाता है।","explanationEn":"Note: In terms of ''Oceans'', the Pacific is the largest, but among ''Seas'' (partially enclosed by land), the South China Sea (or Philippine Sea) is considered the largest.","memoryTip":"समुद्रों (सागर) में चीन ने दक्षिण तक फैलाव कर रखा है।","memoryTipEn":"South China Sea covers vast Asian coasts.","related":["Pacific Ocean","Caribbean Sea","Nine-Dash Line"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2Fd98cLXck-stHb-Pvo0g', 'General Knowledge', 'गौतम बुद्ध द्वारा 29 वर्ष की आयु में गृह-त्याग की घटना क्या कहलाती है?', 'What is the event of Gautam Buddha leaving his home at the age of 29 called?', 'महाभिनिष्क्रमण', 'Mahabhinishkramana (Great Departure)', 94, 0, '{"facts":["बुद्ध ने अपनी पत्नी यशोधरा और पुत्र राहुल को छोड़कर संन्यास का मार्ग चुना।","इस घटना का प्रतीक बौद्ध धर्म में ''घोड़ा'' (Horse) है।"],"factsEn":["Buddha left his wife Yashodhara and son Rahula to choose the path of asceticism.","The symbol for this event in Buddhism is the ''Horse''."],"explanationHi":"सिद्धार्थ (बुद्ध) ने एक बूढ़े व्यक्ति, एक बीमार व्यक्ति, एक शव और एक संन्यासी को देखने के बाद दुनिया के दुखों का कारण जानने के लिए घर छोड़ दिया था।","explanationEn":"Siddhartha (Buddha) left home to seek the cause of worldly suffering after seeing an old man, a sick man, a corpse, and an ascetic.","memoryTip":"घर से ''निष्क्रमण'' (निकलना) = महाभिनिष्क्रमण।","memoryTipEn":"Great Departure leads to enlightenment.","related":["Mahaparinirvana (Death)","Dharmachakra Pravartana (First Sermon)","Buddhism"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_KdkGH7yYgP0_CMhKwwM_', 'General Knowledge', 'भारत में पंचवर्षीय योजना का अनुमोदन करने वाला सर्वोच्च निकाय कौनसा है?', 'Which is the highest body to approve the Five-Year Plans in India?', 'राष्ट्रीय विकास परिषद् (National Development Council - NDC)', 'National Development Council (NDC)', 92, 0, '{"facts":["इसकी स्थापना 6 अगस्त 1952 को हुई थी।","भारत के प्रधानमंत्री इसके पदेन अध्यक्ष होते हैं।"],"factsEn":["It was set up on August 6, 1952.","The Prime Minister of India is its ex-officio chairman."],"explanationHi":"योजना आयोग (अब नीति आयोग) योजनाएं बनाता था, लेकिन राज्यों के मुख्यमंत्रियों के साथ मिलकर उन योजनाओं को अंतिम मंजूरी NDC देती थी।","explanationEn":"The Planning Commission (now NITI Aayog) formulated the plans, but the NDC, involving state Chief Ministers, gave the final approval.","memoryTip":"देश के ''विकास'' की योजना ''विकास परिषद्'' ही पास करेगी।","memoryTipEn":"NDC approves what NITI plans.","related":["Planning Commission","NITI Aayog","Five-Year Plans"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Sn8_XbwUeEzirDilE5Ulg', 'General Knowledge', 'भारत के किस राज्य की सीमा चीन, नेपाल और भूटान से मिलती है?', 'Which Indian state shares its borders with China, Nepal, and Bhutan?', 'सिक्किम', 'Sikkim', 95, 0, '{"facts":["सिक्किम 1975 में भारत का 22वां राज्य बना था।","इसकी राजधानी गंगटोक है।"],"factsEn":["Sikkim became the 22nd state of India in 1975.","Its capital is Gangtok."],"explanationHi":"यह भारत का एक छोटा लेकिन रणनीतिक रूप से अत्यंत महत्वपूर्ण राज्य है जो तीन तरफ से अंतरराष्ट्रीय सीमाओं से घिरा है।","explanationEn":"It is a small but strategically highly significant Indian state surrounded by international borders on three sides.","memoryTip":"सिक्किम एक ''सिक्के'' की तरह तीन देशों के बीच फंसा है।","memoryTipEn":"Sikkim is sandwiched between three nations.","related":["Kanchenjunga","Doklam Standoff","Nathu La Pass"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gTnzjldKZlEky6ZTHlfb4', 'General Knowledge', 'नाथुला दर्रा (Nathu La Pass) किस राज्य में स्थित है?', 'Nathu La Pass is located in which state?', 'सिक्किम', 'Sikkim', 96, 0, '{"facts":["यह हिमालय का एक पहाड़ी दर्रा है जो भारतीय राज्य सिक्किम को चीन के तिब्बत स्वायत्त क्षेत्र से जोड़ता है।","यह प्राचीन सिल्क रूट (Silk Route) का एक हिस्सा है।"],"factsEn":["It is a Himalayan mountain pass connecting the Indian state of Sikkim with China''s Tibet Autonomous Region.","It forms a part of the ancient Silk Route."],"explanationHi":"1962 के युद्ध के बाद इसे बंद कर दिया गया था और 2006 में व्यापार और तीर्थयात्रा (कैलाश मानसरोवर) के लिए इसे फिर से खोला गया।","explanationEn":"It was sealed after the 1962 war and reopened in 2006 for trade and pilgrimage (Kailash Mansarovar).","memoryTip":"''नाथू'' ने ''सिक्का'' (सिक्किम) पार किया।","memoryTipEn":"Nathu La leads from Sikkim to Tibet.","related":["Silk Route","Jelep La Pass","Kailash Mansarovar"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('fpOS-TrqkonEAWU6cidIA', 'General Knowledge', '1912 में अल-हिलाल (Al-Hilal) समाचार-पत्र किसने शुरु किया?', 'Who started the newspaper ''Al-Hilal'' in 1912?', 'मौलाना अबुलकलाम आजाद', 'Maulana Abul Kalam Azad', 93, 0, '{"facts":["यह उर्दू भाषा का एक साप्ताहिक समाचार पत्र था।","ब्रिटिश सरकार ने 1914 में प्रेस अधिनियम के तहत इस पर प्रतिबंध लगा दिया था।"],"factsEn":["It was a weekly newspaper in the Urdu language.","The British government banned it under the Press Act in 1914."],"explanationHi":"आजाद ने इस पत्र का उपयोग भारतीय मुसलमानों में राष्ट्रवाद जगाने और ब्रिटिश राज की आलोचना करने के लिए किया था।","explanationEn":"Azad used this paper to awaken nationalism among Indian Muslims and to criticize the British Raj.","memoryTip":"''आज़ाद'' विचारों से ''अल-हिलाल'' छपता था।","memoryTipEn":"Azad authored Al-Hilal.","related":["Maulana Abul Kalam Azad","Al-Balagh","Indian Independence Movement"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('o_uxr_aCd5Gr6o2O-2ggc', 'General Knowledge', 'महान चिकित्सक चरक किसके दरबार में थे?', 'The great physician Charaka was in whose court?', 'कनिष्क', 'Kanishka', 95, 0, '{"facts":["चरक को ''आयुर्वेद का जनक'' (Father of Ayurveda) भी माना जाता है।","उन्होंने आयुर्वेद का एक मौलिक ग्रंथ ''चरक संहिता'' (Charaka Samhita) लिखा।"],"factsEn":["Charaka is considered the ''Father of Ayurveda''.","He authored the foundational Ayurvedic text, the ''Charaka Samhita''."],"explanationHi":"कनिष्क कुषाण वंश (Kushan Dynasty) का सबसे महान सम्राट था, जिसके दरबार में चरक राजवैद्य (Royal Physician) थे।","explanationEn":"Kanishka was the greatest emperor of the Kushan Dynasty, in whose court Charaka served as the Royal Physician.","memoryTip":"''चरक'' ने ''कनिष्क'' के काल में चिकित्सा की।","memoryTipEn":"Charaka cured in Kanishka''s court.","related":["Charaka Samhita","Kushan Empire","Sushruta"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oixAqo25ij8YeIqQl5v1J', 'General Knowledge', 'भारत में ''मेट्रो-पुरुष'' (Metro Man) कौन कहलाते हैं?', 'Who is known as the ''Metro Man'' of India?', 'ई. श्रीधरन', 'E. Sreedharan', 94, 0, '{"facts":["उन्होंने दिल्ली मेट्रो और कोंकण रेलवे जैसी विशाल बुनियादी ढांचा परियोजनाओं का सफलतापूर्वक नेतृत्व किया।","उन्हें 2008 में पद्म विभूषण से सम्मानित किया गया था।"],"factsEn":["He successfully led massive infrastructure projects like the Delhi Metro and Konkan Railway.","He was awarded the Padma Vibhushan in 2008."],"explanationHi":"समय-सीमा और बजट के भीतर विश्व स्तरीय परिवहन प्रणालियों के निर्माण में उनके शानदार काम के लिए उन्हें यह उपाधि मिली।","explanationEn":"He earned this title for his stellar execution in building world-class transport systems within deadlines and budgets.","memoryTip":"''श्री'' धरन ने ''मेट्रो'' को धरती पर उतारा।","memoryTipEn":"Sreedharan steered the Metro.","related":["Delhi Metro","Konkan Railway","Civil Engineering"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9oy1nGT2D25IqagW1-pbH', 'General Knowledge', 'भारत की स्वतंत्रता के समय कांग्रेस अध्यक्ष कौन थे?', 'Who was the President of the Indian National Congress at the time of India''s independence?', 'जे. बी. कृपलानी', 'J. B. Kripalani', 95, 0, '{"facts":["वे 1946 के मेरठ अधिवेशन में कांग्रेस अध्यक्ष चुने गए थे।","उनकी पत्नी सुचेता कृपलानी भारत की पहली महिला मुख्यमंत्री (उत्तर प्रदेश) बनीं।"],"factsEn":["He was elected Congress President at the Meerut session in 1946.","His wife Sucheta Kriplani became India''s first female Chief Minister (UP)."],"explanationHi":"आजादी (15 अगस्त 1947) के समय वे कांग्रेस के सर्वोच्च पद पर थे। बाद में नेहरू से मतभेदों के कारण उन्होंने इस्तीफा दे दिया था।","explanationEn":"He held the top post of the Congress at the time of independence (Aug 15, 1947). Later, he resigned due to differences with Nehru.","memoryTip":"आज़ादी के समय भगवान की ''कृपा'' (कृपलानी) थी।","memoryTipEn":"Kripalani kept the chair during independence.","related":["Indian National Congress","Sucheta Kriplani","Meerut Session 1946"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('VTD4SaXY4DuAIINMDO-eh', 'General Knowledge', 'कांग्रेस और मुस्लिम लीग के बीच लखनऊ समझौता (Lucknow Pact) किस वर्ष हुआ?', 'In which year did the Lucknow Pact between Congress and the Muslim League take place?', '1916', '1916', 96, 0, '{"facts":["इस समझौते में बाल गंगाधर तिलक और मुहम्मद अली जिन्ना ने प्रमुख भूमिका निभाई।","इस अधिवेशन में कांग्रेस के ''नरम दल'' और ''गरम दल'' भी फिर से एक हो गए थे।"],"factsEn":["Bal Gangadhar Tilak and Muhammad Ali Jinnah played key roles in this pact.","The ''Moderates'' and ''Extremists'' of Congress also reunited in this session."],"explanationHi":"इस समझौते के तहत कांग्रेस ने मुसलमानों के लिए ''पृथक निर्वाचन क्षेत्र'' (Separate Electorates) की मांग को स्वीकार कर लिया था, जिससे हिंदू-मुस्लिम एकता को बढ़ावा मिला।","explanationEn":"Under this pact, Congress accepted the demand for ''Separate Electorates'' for Muslims, fostering Hindu-Muslim unity against the British.","memoryTip":"16 में ''लखनऊ'' में सब एक (One-Six) हो गए।","memoryTipEn":"1916: Lucknow brought unity.","related":["Bal Gangadhar Tilak","Muhammad Ali Jinnah","Separate Electorate"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zBJohrW4uCoAY4yrc0-nq', 'General Knowledge', 'पानीपत का तीसरा युद्ध किनके बीच हुआ?', 'Between whom was the Third Battle of Panipat fought?', 'मराठों और अहमदशाह अब्दाली', 'Marathas and Ahmad Shah Abdali', 97, 0, '{"facts":["यह युद्ध 14 जनवरी 1761 को लड़ा गया था।","इस भयंकर युद्ध में मराठों की हार हुई थी।"],"factsEn":["The battle was fought on January 14, 1761.","The Marathas were defeated in this fierce battle."],"explanationHi":"अहमदशाह अब्दाली (दुर्रानी) अफगान शासक था। इस हार ने पूरे भारत में मराठा साम्राज्य के विस्तार को रोक दिया और अंग्रेजों के उदय का मार्ग प्रशस्त किया।","explanationEn":"Ahmad Shah Abdali was an Afghan ruler. This defeat halted the Maratha empire''s expansion across India and paved the way for the rise of the British.","memoryTip":"तीसरे युद्ध में ''मराठा'' और ''अब्दाली'' भिड़े।","memoryTipEn":"Abdali ambushed the Marathas in 1761.","related":["Ahmad Shah Durrani","Sadashivrao Bhau","First Battle of Panipat"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ucLGhyqvUDrUB4Rv0J-2I', 'Quantitative Aptitude', 'RBI के नए नियमों के अनुसार चेक (Cheque) और बैंक ड्राफ्ट की वैद्यता (Validity) कितने समय तक होती है?', 'According to the new RBI rules, what is the validity period of a Cheque and Bank Draft?', '3 मास (महीने)', '3 months', 89, 0, '{"facts":["पहले चेक और बैंक ड्राफ्ट 6 महीने के लिए वैध होते थे।","भारतीय रिज़र्व बैंक (RBI) ने 1 अप्रैल 2012 से यह नया नियम लागू किया।"],"factsEn":["Earlier, cheques and bank drafts were valid for 6 months.","The Reserve Bank of India (RBI) implemented this new rule from April 1, 2012."],"explanationHi":"बैंकिंग धोखाधड़ी को कम करने और काले धन के प्रवाह को रोकने के लिए इस वैधता अवधि को 6 महीने से घटाकर 3 महीने कर दिया गया।","explanationEn":"The validity period was reduced from 6 months to 3 months to mitigate banking frauds and curb the circulation of black money.","memoryTip":"चेक को 3 महीने के अंदर कैश करा लो।","memoryTipEn":"Cash the cheque within a quarter (3 months).","related":["Reserve Bank of India","Demand Draft","Banking Regulations"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('V19h36RvaAGCIKxwJJXAT', 'General Knowledge', 'भारत का सबसे लम्बा राष्ट्रीय राजमार्ग (National Highway) कौनसा है? (ऐतिहासिक)', 'Which is the longest National Highway in India? (Historical/Text Context)', 'NH-7, वाराणसी से कन्याकुमारी तक (वर्तमान में NH-44)', 'NH-7, Varanasi to Kanyakumari (Currently NH-44)', 92, 0, '{"facts":["महत्वपूर्ण अद्यतन: राजमार्गों के पुनर्नामकरण के बाद, अब ''NH-44'' भारत का सबसे लंबा राजमार्ग है (श्रीनगर से कन्याकुमारी, 3,745 किमी)।","NH-7 पुराने नंबरिंग सिस्टम के तहत सबसे लंबा था।"],"factsEn":["Important Update: After the renumbering of highways, ''NH-44'' is now the longest highway in India (Srinagar to Kanyakumari, 3,745 km).","NH-7 was the longest under the old numbering system."],"explanationHi":"प्रतियोगी परीक्षाओं में अक्सर पुराने संदर्भ (NH-7) पूछे जाते थे, लेकिन अब सही उत्तर NH-44 है जो उत्तर को दक्षिण से जोड़ता है।","explanationEn":"Competitive exams often asked for the old reference (NH-7), but the correct answer now is NH-44, connecting the North to the South.","memoryTip":"पुराना 7, नया 44। 4 और 4 (44) पूरे देश को जोड़ते हैं।","memoryTipEn":"NH-44 covers the floor from Srinagar to Kanyakumari.","related":["National Highway 44","National Highways Authority of India (NHAI)","Golden Quadrilateral"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BKEsudIShdTIKKXlYGY9Z', 'General Science', 'संगमरमर (Marble) किसका परिवर्तित (Metamorphic) रूप है?', 'Marble is a metamorphic form of what?', 'चूना पत्थर (Limestone) का', 'Limestone', 95, 0, '{"facts":["संगमरमर एक रूपांतरित चट्टान (Metamorphic rock) है।","ताजमहल और विक्टोरिया मेमोरियल जैसे प्रसिद्ध स्मारक सफेद संगमरमर से बने हैं।"],"factsEn":["Marble is a metamorphic rock.","Famous monuments like the Taj Mahal and Victoria Memorial are built of white marble."],"explanationHi":"जब चूना पत्थर (Limestone) पृथ्वी के भीतर अत्यधिक गर्मी और दबाव (Heat and Pressure) के संपर्क में आता है, तो वह क्रिस्टलीकृत होकर संगमरमर बन जाता है।","explanationEn":"When limestone is subjected to intense heat and pressure deep within the Earth, it recrystallizes into marble.","memoryTip":"''चूना'' पत्थर पर दबाव पड़ा तो ''संगमरमर'' बन गया।","memoryTipEn":"Limestone transforms under pressure into Marble.","related":["Metamorphic Rocks","Limestone","Taj Mahal"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dc4P_KFjRvMwtvi52hMno', 'General Knowledge', 'विश्व व्यापार संगठन (WTO) का मुख्यालय कहाँ है?', 'Where is the headquarters of the World Trade Organization (WTO)?', 'जेनेवा (स्विट्ज़रलैंड)', 'Geneva (Switzerland)', 94, 0, '{"facts":["WTO की स्थापना 1 जनवरी 1995 को हुई थी।","WHO, ILO और WIPO जैसे कई अन्य अंतरराष्ट्रीय संगठनों का मुख्यालय भी जिनेवा में है।"],"factsEn":["WTO was established on January 1, 1995.","Many other international organizations like WHO, ILO, and WIPO are also headquartered in Geneva."],"explanationHi":"यह देशों के बीच व्यापार के वैश्विक नियमों (Global rules of trade) से निपटने वाला एकमात्र अंतर्राष्ट्रीय संगठन है।","explanationEn":"It is the only international organization dealing with the global rules of trade between nations.","memoryTip":"विश्व का ''व्यापार'' जिनेवा के ''जान'' (जेनेवा) में बसता है।","memoryTipEn":"Geneva governs global trade.","related":["GATT","World Health Organization (WHO)","Switzerland"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5-XUi00F8JfcK9LacbZN-', 'General Knowledge', 'चौरी-चौरा कांड के बाद महात्मा गाँधी ने कौनसा आन्दोलन स्थगित (suspend) कर दिया था?', 'Which movement was suspended by Mahatma Gandhi after the Chauri Chaura incident?', 'असहयोग आन्दोलन (Non-Cooperation Movement)', 'Non-Cooperation Movement', 97, 0, '{"facts":["चौरी-चौरा कांड 4 फरवरी 1922 को गोरखपुर (यूपी) में हुआ था।","इस घटना में प्रदर्शनकारियों की भीड़ ने एक पुलिस स्टेशन में आग लगा दी थी, जिसमें 22 पुलिसकर्मी मारे गए।"],"factsEn":["The Chauri Chaura incident took place on February 4, 1922, in Gorakhpur (UP).","A mob of protesters set fire to a police station, killing 22 policemen."],"explanationHi":"गांधीजी का मानना था कि आंदोलन को पूरी तरह से अहिंसक होना चाहिए। हिंसा देखकर उन्होंने निराश होकर 1920 में शुरू हुए असहयोग आंदोलन को वापस ले लिया।","explanationEn":"Gandhiji believed the movement should be strictly non-violent. Distressed by the violence, he called off the Non-Cooperation movement launched in 1920.","memoryTip":"चौरी-चौरा की ''हिंसा'' से ''असहयोग'' रुक गया।","memoryTipEn":"Chauri Chaura''s fire extinguished the Non-Cooperation Movement.","related":["Non-Cooperation Movement","Mahatma Gandhi","Gorakhpur"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kmdUyQPxOq7LOffNltXoy', 'General Knowledge', 'केरल के तट (Coast) को क्या कहते हैं?', 'What is the coast of Kerala called?', 'मालाबार तट', 'Malabar Coast', 95, 0, '{"facts":["मालाबार तट भारत के दक्षिण-पश्चिमी भाग में स्थित है।","भारत के पूर्वी तट (तमिलनाडु-आंध्र प्रदेश) को कोरोमंडल तट (Coromandel Coast) कहा जाता है।"],"factsEn":["The Malabar Coast is located in the southwestern part of India.","The eastern coast of India (Tamil Nadu-Andhra) is called the Coromandel Coast."],"explanationHi":"यह तट ऐतिहासिक रूप से मसालों (Spices) के व्यापार के लिए प्रसिद्ध रहा है और वास्को डी गामा सबसे पहले इसी तट (कालीकट) पर पहुंचा था।","explanationEn":"This coast has been historically famous for the spice trade, and Vasco da Gama first arrived on this very coast (Calicut).","memoryTip":"केरल में ''मसालों की माला'' (मालाबार) मिलती है।","memoryTipEn":"Kerala''s coast makes Malabar.","related":["Coromandel Coast","Konkan Coast","Western Ghats"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('f47LFxWa2J39JIlBg6wKj', 'General Knowledge', 'जेंद-अवेस्ता (Zend Avesta) किस धर्म की धार्मिक पुस्तक है?', 'Zend Avesta is the religious book of which religion?', 'पारसी (Zoroastrianism)', 'Parsi (Zoroastrianism)', 93, 0, '{"facts":["यह धर्म पैगंबर ज़रथुस्त्र (Zoroaster) की शिक्षाओं पर आधारित है।","पारसी लोग अग्नि (Fire) को बहुत पवित्र मानते हैं और उनके मंदिरों को ''फायर टेम्पल'' (Fire Temple) कहा जाता है।"],"factsEn":["This religion is based on the teachings of the prophet Zoroaster.","Parsis consider Fire highly sacred, and their temples are called ''Fire Temples''."],"explanationHi":"जेंद-अवेस्ता प्राचीन अवेस्तन (Avestan) भाषा में लिखी गई है, जो वेदों की प्राचीन संस्कृत भाषा से बहुत मिलती-जुलती है।","explanationEn":"Zend Avesta is written in the ancient Avestan language, which is very similar to the ancient Vedic Sanskrit.","memoryTip":"पारसी लोग ''अवेस्ता'' का पाठ करते हैं।","memoryTipEn":"Zend Avesta is Zoroaster''s book.","related":["Zoroastrianism","Fire Temple","Navroz"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XmjZ88m0lVb3I6pWNTIkR', 'General Knowledge', 'भारत का राष्ट्रगान (National Anthem) सबसे पहले कब गाया गया था?', 'When was the National Anthem of India sung for the first time?', '1911 के कांग्रेस के कोलकाता अधिवेशन में', 'At the 1911 Kolkata session of Congress', 96, 0, '{"facts":["राष्ट्रगान ''जन-गण-मन'' रवीन्द्रनाथ टैगोर द्वारा लिखा गया था।","इसे 24 जनवरी 1950 को आधिकारिक तौर पर भारत के राष्ट्रगान के रूप में अपनाया गया।"],"factsEn":["The National Anthem ''Jana Gana Mana'' was written by Rabindranath Tagore.","It was officially adopted as India''s National Anthem on January 24, 1950."],"explanationHi":"यह गीत पहली बार 27 दिसंबर 1911 को कलकत्ता (अब कोलकाता) में भारतीय राष्ट्रीय कांग्रेस के 26वें अधिवेशन में गाया गया था।","explanationEn":"The song was first sung on December 27, 1911, at the 26th session of the Indian National Congress in Calcutta (now Kolkata).","memoryTip":"11 में गान (Anthem) गाया, 50 में अपनाया।","memoryTipEn":"1911 heard the first Jana Gana Mana.","related":["Jana Gana Mana","Rabindranath Tagore","Calcutta Session 1911"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XX2DO1fQDuztNjNxVaohe', 'General Science', 'पानी का रासायनिक सूत्र क्या है?', 'What is the chemical formula of water?', 'H₂O', 'H₂O', 92, 0, '{"facts":["पानी का एक अणु (Molecule) हाइड्रोजन के 2 परमाणुओं और ऑक्सीजन के 1 परमाणु से मिलकर बनता है।","भारी जल (Heavy Water) का सूत्र D₂O (Deuterium oxide) होता है।"],"factsEn":["A water molecule is composed of 2 atoms of Hydrogen and 1 atom of Oxygen.","The formula for Heavy Water is D₂O (Deuterium oxide)."],"explanationHi":"यह पृथ्वी पर जीवन के लिए सबसे आवश्यक यौगिक है और इसका पीएच (pH) मान शुद्ध अवस्था में 7 (Neutral) होता है।","explanationEn":"It is the most essential compound for life on Earth, and its pH value in pure state is 7 (Neutral).","memoryTip":"H (Two) O = Water.","memoryTipEn":"Two H''s and an O make the water flow.","related":["Hydrogen Bonds","Heavy Water (D2O)","pH scale"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6W5Vag8wH9q3qDJi8U6NG', 'General Science', 'प्रकृति में पाया जाने वाला कठोरतम पदार्थ कौनसा है?', 'Which is the hardest substance found in nature?', 'हीरा (Diamond)', 'Diamond', 95, 0, '{"facts":["हीरा कार्बन (Carbon) का एक अपररूप (Allotrope) है।","ग्रेफाइट (Graphite) भी कार्बन का रूप है, लेकिन यह बहुत नरम होता है।"],"factsEn":["Diamond is an allotrope of Carbon.","Graphite is also a form of carbon, but it is very soft."],"explanationHi":"हीरे में मौजूद मजबूत सहसंयोजक बंध (Covalent bonds) की त्रिविमीय (3D) संरचना के कारण यह पृथ्वी पर मौजूद सबसे कठोर प्राकृतिक सामग्री है।","explanationEn":"Due to the 3D structure of strong covalent bonds in a diamond, it is the hardest natural material on Earth.","memoryTip":"हीरा सबसे ''हार्ड'' है।","memoryTipEn":"Diamonds are forever hard.","related":["Carbon Allotropes","Graphite","Mohs scale of hardness"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('683TaO6YMKMw9ENJr33rc', 'General Science', 'समुद्री जल में लवण (Salt) की औसत मात्रा कितनी होती है?', 'What is the average amount of salt (salinity) in seawater?', '3.5%', '3.5%', 90, 0, '{"facts":["इसे आमतौर पर 35 भाग प्रति हजार (35 parts per thousand या 35 ppt) के रूप में व्यक्त किया जाता है।","समुद्री जल में सबसे अधिक पाया जाने वाला नमक सोडियम क्लोराइड (NaCl) है।"],"factsEn":["It is usually expressed as 35 parts per thousand (35 ppt).","The most abundant salt in seawater is Sodium Chloride (NaCl)."],"explanationHi":"इसका मतलब है कि 1 किलोग्राम समुद्री जल में लगभग 35 ग्राम घुले हुए लवण होते हैं। मृत सागर (Dead Sea) में लवणता सबसे अधिक है।","explanationEn":"This means that 1 kilogram of seawater contains about 35 grams of dissolved salts. The Dead Sea has one of the highest salinities.","memoryTip":"समुद्र का पानी 3.5 गुना ज्यादा खारा है।","memoryTipEn":"35 grams in a kilo makes the ocean salty.","related":["Salinity","Sodium Chloride","Dead Sea"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('pvz4qdZ_9F0mmUokA1Y3G', 'General Knowledge', 'राष्ट्रीय विकास परिषद् (NDC) का अध्यक्ष कौन होता है?', 'Who is the Chairman of the National Development Council (NDC)?', 'प्रधानमंत्री', 'Prime Minister', 92, 0, '{"facts":["NDC की स्थापना 1952 में हुई थी।","सभी राज्यों के मुख्यमंत्री और केंद्रीय कैबिनेट मंत्री इसके सदस्य होते हैं।"],"factsEn":["The NDC was established in 1952.","Chief Ministers of all states and Union Cabinet Ministers are its members."],"explanationHi":"योजना आयोग (अब नीति आयोग) द्वारा बनाई गई पंचवर्षीय योजनाओं को अंतिम मंजूरी देने का काम राष्ट्रीय विकास परिषद ही करती थी।","explanationEn":"The Five-Year Plans formulated by the Planning Commission (now NITI Aayog) were given final approval by the National Development Council.","memoryTip":"देश के विकास का ''अध्यक्ष'' प्रधानमंत्री होता है।","memoryTipEn":"PM guides National Development.","related":["NITI Aayog","Planning Commission","Five-Year Plans"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('67dDS-s-iiskLNAoeU4t7', 'General Knowledge', 'सिकंदर (Alexander) ने भारत पर कब आक्रमण किया?', 'When did Alexander the Great invade India?', '326 BC (ईसा पूर्व)', '326 BC', 94, 0, '{"facts":["सिकंदर ने हाइडेस्पीज के युद्ध (Battle of the Hydaspes) में राजा पोरस को हराया था।","हाइडेस्पीज युद्ध झेलम नदी के तट पर लड़ा गया था।"],"factsEn":["Alexander defeated King Porus in the Battle of the Hydaspes.","The Battle of Hydaspes was fought on the banks of the Jhelum River."],"explanationHi":"सिकंदर की सेना लंबी लड़ाई और थकान के कारण ब्यास (Beas) नदी से आगे बढ़ने से इनकार कर दिया, जिससे उसे वापस लौटना पड़ा।","explanationEn":"Alexander''s army, exhausted from long campaigns, refused to cross the Beas River, forcing him to turn back.","memoryTip":"3-2-6 (तीन-दो-छह), सिकंदर ने किया भारत पर आक्रमण।","memoryTipEn":"326 BC: Alexander''s march to India.","related":["King Porus","Battle of Hydaspes","Jhelum River"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KQoqPZP6Dyw04HgYFqomp', 'General Knowledge', 'भारत का संविधान कितने समय में तैयार हुआ?', 'How much time did it take to prepare the Constitution of India?', '2 साल 11 मास (महीने) 18 दिन', '2 years 11 months and 18 days', 96, 0, '{"facts":["संविधान सभा की पहली बैठक 9 दिसंबर 1946 को हुई थी।","संविधान 26 नवंबर 1949 को अंगीकृत (Adopted) किया गया था।"],"factsEn":["The first meeting of the Constituent Assembly was held on December 9, 1946.","The Constitution was adopted on November 26, 1949."],"explanationHi":"डॉ. बी.आर. अंबेडकर की अध्यक्षता में प्रारूप समिति (Drafting Committee) ने दुनिया का सबसे लंबा लिखित संविधान तैयार करने में यह समय लिया।","explanationEn":"The Drafting Committee, chaired by Dr. B.R. Ambedkar, took this time to prepare the longest written constitution in the world.","memoryTip":"3 साल में बस 12 दिन कम।","memoryTipEn":"Almost 3 years (minus 12 days).","related":["Constituent Assembly","Dr. B.R. Ambedkar","November 26 (Constitution Day)"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wI9bsk3x23oVVE3chgtQC', 'General Knowledge', 'भारतीय संविधान में मौलिक कर्तव्य (Fundamental Duties) किस देश के संविधान से लिए गए हैं?', 'From which country''s constitution were the Fundamental Duties adopted in the Indian Constitution?', 'रूस (सोवियत संघ) के संविधान से [पीडीएफ में ''अमेरिकी'' त्रुटिपूर्ण है]', 'Russia (USSR) [Note: PDF erroneously says ''American'']', 95, 0, '{"facts":["ध्यान दें: पीडीएफ में ''अमेरिकी संविधान'' लिखा है, जो कि एक तथ्यात्मक त्रुटि है। मौलिक अधिकार (Fundamental Rights) अमेरिका से लिए गए हैं, जबकि मौलिक कर्तव्य तत्कालीन सोवियत संघ (USSR) से प्रेरित हैं।","मौलिक कर्तव्य 42वें संविधान संशोधन (1976) द्वारा स्वर्ण सिंह समिति की सिफारिश पर जोड़े गए।"],"factsEn":["Note: The PDF mistakenly says ''American''. Fundamental Rights were taken from the USA, but Fundamental Duties were inspired by the USSR.","Fundamental Duties were added by the 42nd Amendment (1976) on the recommendation of the Swaran Singh Committee."],"explanationHi":"संविधान के भाग IV-A में अनुच्छेद 51A के तहत नागरिकों के 11 मौलिक कर्तव्यों का वर्णन किया गया है।","explanationEn":"Part IV-A, Article 51A of the Constitution enumerates the 11 Fundamental Duties of citizens.","memoryTip":"ड्यूटी (Duty) ''रूस'' ने सिखाई, अधिकार (Right) ''अमेरिका'' ने।","memoryTipEn":"Duties from USSR, Rights from USA.","related":["42nd Amendment","Swaran Singh Committee","USSR Constitution"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7J131JEIVQ_Lms2QZoQjJ', 'General Knowledge', 'संविधान की किस धारा (अनुच्छेद) के अंतर्गत राज्यपाल किसी राज्य में राष्ट्रपति शासन लगाने की सिफारिश करता है?', 'Under which article of the Constitution does the Governor recommend the imposition of President''s Rule in a state?', 'अनुच्छेद 356 (धारा 356)', 'Article 356', 96, 0, '{"facts":["इसे ''राज्य आपातकाल'' (State Emergency) या ''राष्ट्रपति शासन'' (President''s Rule) कहा जाता है।","अनुच्छेद 352 ''राष्ट्रीय आपातकाल'' और अनुच्छेद 360 ''वित्तीय आपातकाल'' से संबंधित है।"],"factsEn":["It is called ''State Emergency'' or ''President''s Rule''.","Article 352 relates to ''National Emergency'' and Article 360 to ''Financial Emergency''."],"explanationHi":"यदि राज्यपाल को लगता है कि राज्य सरकार संविधान के प्रावधानों के अनुसार काम नहीं कर रही है (संवैधानिक तंत्र की विफलता), तो वह राष्ट्रपति से इसे लागू करने की सिफारिश करता है।","explanationEn":"If the Governor feels the state government cannot be carried on in accordance with the Constitution (failure of constitutional machinery), they recommend the President to invoke this rule.","memoryTip":"352 (देश), 356 (राज्य), 360 (पैसा)।","memoryTipEn":"356 rules the state when the machinery breaks.","related":["President''s Rule","Emergency Provisions","Article 352"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ylhXO4C4x0qTecedj5bQZ', 'General Science', 'प्रोटोन (Proton) की खोज किसने की थी?', 'Who discovered the Proton?', 'रदरफोर्ड (Rutherford)', 'Ernest Rutherford', 94, 0, '{"facts":["यद्यपि ''गोल्डस्टीन'' ने कैनाल किरणों (पॉजिटिव किरणों) की खोज की थी, लेकिन रदरफोर्ड ने 1920 में इसका नाम प्रोटॉन रखा और परमाणु के नाभिक में इसकी पुष्टि की।","इलेक्ट्रॉन की खोज जे.जे. थॉमसन और न्यूट्रॉन की खोज जेम्स चैडविक ने की।"],"factsEn":["Though ''Goldstein'' discovered canal rays (positive rays), Rutherford named it Proton in 1920 and confirmed its presence in the nucleus.","Electron was discovered by J.J. Thomson and Neutron by James Chadwick."],"explanationHi":"प्रोटॉन एक उप-परमाणु कण (Subatomic particle) है जिस पर धनात्मक (Positive) विद्युत आवेश होता है और यह परमाणु के केंद्र (Nucleus) में पाया जाता है।","explanationEn":"A proton is a subatomic particle with a positive electrical charge, found in the nucleus of an atom.","memoryTip":"PEN = RTC (Proton-Rutherford, Electron-Thomson, Neutron-Chadwick).","memoryTipEn":"Rutherford revealed the positive Proton.","related":["Electron (J.J. Thomson)","Neutron (James Chadwick)","Atomic Nucleus"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QM6ZzW6BDnfV-iknw5PyE', 'General Science', 'भारत में प्रथम परमाणु बिजलीघर कहाँ स्थापित किया गया?', 'Where was the first nuclear power station established in India?', 'तारापुर', 'Tarapur', 93, 0, '{"facts":["तारापुर परमाणु ऊर्जा स्टेशन महाराष्ट्र के पालघर जिले में स्थित है।","इसका वाणिज्यिक संचालन 1969 में शुरू हुआ था।"],"factsEn":["Tarapur Atomic Power Station is located in the Palghar district of Maharashtra.","Its commercial operation began in 1969."],"explanationHi":"यह अमेरिका के सहयोग से बनाया गया था और यह भारत का सबसे पुराना वाणिज्यिक परमाणु ऊर्जा स्टेशन है।","explanationEn":"It was built with the collaboration of the United States and is India''s oldest commercial nuclear power station.","memoryTip":"बिजली का ''तारा'' महाराष्ट्र के तारापुर में चमका।","memoryTipEn":"Tarapur triggered nuclear power in India.","related":["Nuclear Power Corporation of India","Kudankulam (Largest NPP)","Maharashtra"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('B2m2AUzEIVqHabrKp2YgW', 'General Knowledge', 'शान्तिनिकेतन (Shantiniketan) की स्थापना किसने की?', 'Who founded Shantiniketan?', 'रवीन्द्रनाथ टैगोर', 'Rabindranath Tagore', 91, 0, '{"facts":["शांतिनिकेतन पश्चिम बंगाल के बीरभूम जिले में स्थित है।","यहीं पर टैगोर ने विश्वभारती विश्वविद्यालय (Visva-Bharati University) की स्थापना की।"],"factsEn":["Shantiniketan is located in the Birbhum district of West Bengal.","Here, Tagore established the Visva-Bharati University."],"explanationHi":"यह पारंपरिक कक्षा शिक्षा से हटकर प्रकृति के बीच और खुले माहौल में सीखने का एक अनूठा शैक्षिक केंद्र है।","explanationEn":"It is a unique educational center that breaks away from traditional classroom learning, encouraging learning amidst nature and in an open environment.","memoryTip":"टैगोर ने ''शांति'' का ''निकेतन'' (घर) बंगाल में बनाया।","memoryTipEn":"Tagore''s abode of peace (Shanti-niketan).","related":["Visva-Bharati University","Rabindranath Tagore","West Bengal"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TjDAQmH9XOHApIwH7l0zp', 'General Knowledge', 'अर्थशास्त्र का नोबल पुरस्कार किस वर्ष शुरु हुआ?', 'In which year was the Nobel Prize in Economics instituted?', '1969', '1969', 88, 0, '{"facts":["इसे स्वीडन के केंद्रीय बैंक (Sveriges Riksbank) द्वारा 1968 में स्थापित किया गया था और पहली बार 1969 में दिया गया।","अर्थशास्त्र का नोबेल अल्फ्रेड नोबेल की मूल वसीयत का हिस्सा नहीं था।"],"factsEn":["It was established by Sweden''s central bank in 1968 and first awarded in 1969.","The Economics Nobel was not part of Alfred Nobel''s original will."],"explanationHi":"आधिकारिक तौर पर इसे ''अल्फ्रेड नोबेल की स्मृति में आर्थिक विज्ञान में स्वेरिजेस रिक्सबैंक पुरस्कार'' कहा जाता है। अमर्त्य सेन (1998) इसे जीतने वाले पहले भारतीय थे।","explanationEn":"Officially it is called the ''Sveriges Riksbank Prize in Economic Sciences in Memory of Alfred Nobel''. Amartya Sen (1998) was the first Indian to win it.","memoryTip":"69 में ''धन'' (अर्थशास्त्र) का नोबेल शुरू हुआ।","memoryTipEn":"1969 extended the Nobel to Economics.","related":["Alfred Nobel","Amartya Sen","Nobel Prize Categories"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wzSJa5kNkcKmjdtQteGxA', 'General Knowledge', 'गौतम बुद्ध द्वारा देह-त्याग (Death) की घटना क्या कहलाती है?', 'What is the event of the death of Gautam Buddha called?', 'महापरिनिर्वाण', 'Mahaparinirvana', 96, 0, '{"facts":["यह घटना कुशीनगर (उत्तर प्रदेश) में 483 ईसा पूर्व में हुई थी।","इस घटना का प्रतीक बौद्ध धर्म में ''स्तूप'' (Stupa) है।"],"factsEn":["This event took place in Kushinagar (UP) in 483 BCE.","The symbol for this event in Buddhism is the ''Stupa''."],"explanationHi":"बौद्ध धर्म में ''निर्वाण'' का अर्थ है जन्म और मरण के चक्र से मुक्ति प्राप्त कर लेना।","explanationEn":"In Buddhism, ''Nirvana'' means attaining liberation from the cycle of birth and rebirth.","memoryTip":"शरीर त्यागने के बाद बुद्ध को ''महान निर्वाण'' (महापरिनिर्वाण) प्राप्त हुआ।","memoryTipEn":"Mahaparinirvana signifies the final release.","related":["Kushinagar","Dharmachakra Pravartana","Mahabhinishkramana"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('erdPZ6WQdzdqI7zYg3zrX', 'General Knowledge', 'प्रथम बौध कौंसिल (Council) कब, कहाँ और किसके शासनकाल में हुई?', 'When, where, and during whose reign was the First Buddhist Council held?', '483 BC, राजगृह, अजातशत्रु', '483 BC, Rajagriha, Ajatashatru', 94, 0, '{"facts":["यह परिषद बुद्ध की मृत्यु (महापरिनिर्वाण) के तुरंत बाद आयोजित की गई थी।","इसकी अध्यक्षता महाकस्सप (Mahakassapa) ने की थी।"],"factsEn":["The council was held immediately after the death (Mahaparinirvana) of Buddha.","It was presided over by Mahakassapa."],"explanationHi":"इस परिषद का मुख्य उद्देश्य बुद्ध की शिक्षाओं (सुत्त पिटक) और मठवासी नियमों (विनय पिटक) को संकलित करना था।","explanationEn":"The primary purpose of this council was to compile the Buddha''s teachings (Sutta Pitaka) and monastic rules (Vinaya Pitaka).","memoryTip":"पहली कौंसिल: R-V-P-K (Rajagriha, Vaishali, Pataliputra, Kashmir). पहली ''राजगृह'' में।","memoryTipEn":"First council was organized by Ajatashatru at Rajagriha.","related":["Ajatashatru","Sutta Pitaka","Vinaya Pitaka"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('n3Dvops99fD77ByPTGZhv', 'General Science', 'सूर्य की सतह (Surface) का तापमान कितना होता है?', 'What is the surface temperature of the Sun?', '6000 डिग्री सेल्सिअस', '6000 Degree Celsius', 92, 0, '{"facts":["सूर्य की इस दिखाई देने वाली सतह को ''फोटोस्फीयर'' (Photosphere) कहा जाता है।","सूर्य के केंद्र (Core) का तापमान लगभग 15 मिलियन डिग्री सेल्सियस होता है।"],"factsEn":["This visible surface of the sun is called the ''Photosphere''.","The temperature at the core of the sun is about 15 million degrees Celsius."],"explanationHi":"सूर्य नाभिकीय संलयन (Nuclear Fusion) के माध्यम से इतनी विशाल ऊर्जा और उच्च तापमान उत्पन्न करता है।","explanationEn":"The Sun generates such massive energy and high temperatures through Nuclear Fusion.","memoryTip":"सूरज की चमड़ी (सतह) 6 हज़ार डिग्री पर जल रही है।","memoryTipEn":"6000 degrees on the Photosphere.","related":["Photosphere","Nuclear Fusion","Solar Core"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7jwJvyaoHqIaMyZMuz35S', 'General Knowledge', 'सवाना (Savanna) घास के मैदान किस महाद्वीप में हैं?', 'In which continent are the Savanna grasslands located?', 'अफ्रीका', 'Africa', 91, 0, '{"facts":["सवाना उष्णकटिबंधीय (Tropical) घास के मैदान हैं जिनमें बिखरे हुए पेड़ पाए जाते हैं।","यह क्षेत्र शेरों, जेब्रा और हाथियों जैसे बड़े स्तनधारियों के लिए प्रसिद्ध है (जैसे सेरेनगेटी)।"],"factsEn":["Savannas are tropical grasslands with scattered trees.","The region is famous for large mammals like lions, zebras, and elephants (e.g., Serengeti)."],"explanationHi":"यहाँ स्पष्ट शुष्क और नम मौसम (dry and wet seasons) होते हैं। यह अफ्रीका के एक बहुत बड़े हिस्से को कवर करता है।","explanationEn":"There are distinct dry and wet seasons here. It covers a very large portion of Africa.","memoryTip":"अफ्रीका में सब घास ''सवाना'' जैसी है।","memoryTipEn":"Savanna safaris in Africa.","related":["Prairies (North America)","Pampas (North America)","Veld (South America)"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('07kqK3Ld2XRbZrcgCw91g', 'General Knowledge', 'किस संविधान संशोधन द्वारा पंचायती राज व्यवस्था लागु की गयी?', 'By which constitutional amendment was the Panchayati Raj system implemented?', '73वें संशोधन द्वारा', '73rd Amendment', 97, 0, '{"facts":["यह संशोधन 1992 में पारित हुआ था।","इसने संविधान में ''भाग IX'' और ''ग्यारहवीं अनुसूची'' (11th Schedule) को जोड़ा।"],"factsEn":["This amendment was passed in 1992.","It added ''Part IX'' and the ''11th Schedule'' to the Constitution."],"explanationHi":"इस संशोधन ने भारत में ग्रामीण स्थानीय स्वशासन (Local self-government) को संवैधानिक दर्जा प्रदान किया, जिसमें तीन-स्तरीय (ग्राम, ब्लॉक, जिला) पंचायत व्यवस्था शामिल है।","explanationEn":"This amendment provided constitutional status to rural local self-government in India, featuring a three-tier (Village, Block, District) Panchayat system.","memoryTip":"73वें से गांव (पंचायत) और 74वें से शहर (नगरपालिका) का विकास।","memoryTipEn":"73rd empowers the Panchayat.","related":["11th Schedule","Balwant Rai Mehta Committee","74th Amendment (Municipalities)"]}', 'published', 1776085064, 1776085064);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8Uzy2dkCwQQl7UICRhoYF', 'General Knowledge', 'राष्ट्रपति यदि इस्तीफा देना चाहे तो किसे सौंपेगा?', 'To whom will the President submit his resignation if he wishes to resign?', 'उपराष्ट्रपति', 'Vice President', 95, 0, '{"facts":["संविधान के अनुच्छेद 56 के अनुसार राष्ट्रपति अपना इस्तीफा उपराष्ट्रपति को देते हैं।","उपराष्ट्रपति इसकी सूचना तुरंत लोकसभा अध्यक्ष को देते हैं।"],"factsEn":["Under Article 56 of the Constitution, the President submits his resignation to the Vice President.","The Vice President immediately communicates this to the Speaker of the Lok Sabha."],"explanationHi":"यदि राष्ट्रपति का पद खाली हो जाता है, तो नए राष्ट्रपति के चुनाव तक उपराष्ट्रपति कार्यवाहक राष्ट्रपति के रूप में कार्य करता है।","explanationEn":"If the President''s office falls vacant, the Vice President acts as the President until a new President is elected.","memoryTip":"राष्ट्रपति के बाद नंबर 2 (उपराष्ट्रपति) ही चार्ज लेगा।","memoryTipEn":"President resigns to the VP.","related":["Article 56","Impeachment of President","Vice President of India"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('p2NbvgrnuB1b4nVkBEu7b', 'General Knowledge', 'किस राज्य में लोकसभा की सर्वाधिक सीटें हैं?', 'Which state has the maximum number of Lok Sabha seats?', '80, उत्तर प्रदेश', '80, Uttar Pradesh', 96, 0, '{"facts":["उत्तर प्रदेश जनसंख्या के मामले में भारत का सबसे बड़ा राज्य है।","महाराष्ट्र (48 सीटें) लोकसभा सीटों के मामले में दूसरे स्थान पर है।"],"factsEn":["Uttar Pradesh is the most populous state in India.","Maharashtra (48 seats) is second in terms of Lok Sabha seats."],"explanationHi":"लोकसभा सीटों का आवंटन उस राज्य की जनसंख्या के आधार पर किया जाता है, इसलिए यूपी में सबसे अधिक प्रतिनिधि हैं।","explanationEn":"The allocation of Lok Sabha seats is based on the population of that state, hence UP has the most representatives.","memoryTip":"जिसका जन ''उत्तर'' (UP) में सबसे ज्यादा, उसकी सीटें 80।","memoryTipEn":"UP holds 80 Lok Sabha keys.","related":["Lok Sabha","Rajya Sabha Seats in UP (31)","Delimitation Commission"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IyDLlL5tc9E0Ufc0vuhza', 'General Knowledge', 'भगवान महावीर का जन्म कहाँ हुआ?', 'Where was Lord Mahavira born?', 'कुंडाग्राम (वैशाली)', 'Kundagrama (Vaishali)', 94, 0, '{"facts":["वे जैन धर्म के 24वें और अंतिम तीर्थंकर थे।","उनका जन्म एक क्षत्रिय परिवार (ज्ञातृक वंश) में 599 ईसा पूर्व में हुआ था।"],"factsEn":["He was the 24th and last Tirthankara of Jainism.","He was born in a Kshatriya family (Jnatrika clan) in 599 BCE."],"explanationHi":"कुंडाग्राम आधुनिक बिहार राज्य के वैशाली जिले के पास स्थित था।","explanationEn":"Kundagrama was located near the Vaishali district of modern-day Bihar state.","memoryTip":"महावीर का जन्म ''कुंडा'' (कुंडाग्राम) में हुआ।","memoryTipEn":"Mahavira born in Kundagrama.","related":["Jainism","Tirthankara","Pavapuri (Place of Death)"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9LsjIdY3TMkywedO1z4OV', 'General Knowledge', 'चौथी बौध कौंसिल कब, कहाँ और किसके संरक्षण में हुई?', 'When, where, and under whose patronage was the Fourth Buddhist Council held?', '98 AD, कुंडलवन (कश्मीर), कनिष्क', '98 AD, Kundalvana (Kashmir), Kanishka', 92, 0, '{"facts":["इस परिषद की अध्यक्षता वसुमित्र और अश्वघोष ने की थी।","इसी कौंसिल में बौद्ध धर्म दो संप्रदायों: हीनयान और महायान में विभाजित हो गया।"],"factsEn":["This council was presided over by Vasumitra and Ashvaghosha.","In this council, Buddhism split into two sects: Hinayana and Mahayana."],"explanationHi":"कुषाण सम्राट कनिष्क ने महायान बौद्ध धर्म का समर्थन किया था और इसे मध्य एशिया तक फैलाया।","explanationEn":"Kushan emperor Kanishka patronized Mahayana Buddhism and helped spread it to Central Asia.","memoryTip":"चौथी (4th) कौंसिल कश्मीर के ''कुंडलवन'' में ''कनिष्क'' के काल में हुई (K-K-K)।","memoryTipEn":"Kashmir, Kanishka, Kundalvana.","related":["Mahayana Buddhism","Hinayana Buddhism","Kushan Empire"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('c4SZikMd_MmMurG3BNr2G', 'General Science', 'पृथ्वी अपनी धुरी पर कितने कोण पर झुकी है?', 'At what angle is the Earth tilted on its axis?', '23.5 डिग्री', '23.5 degrees', 93, 0, '{"facts":["इस झुकाव को ''अक्षीय झुकाव'' (Axial tilt) कहा जाता है।","इसी झुकाव के कारण पृथ्वी पर मौसम (Seasons) बदलते हैं।"],"factsEn":["This tilt is called the ''Axial tilt''.","This tilt is the primary reason for the changing seasons on Earth."],"explanationHi":"यदि पृथ्वी झुकी हुई नहीं होती, तो हर जगह दिन और रात हमेशा बराबर होते और कोई ऋतु परिवर्तन नहीं होता।","explanationEn":"If the Earth were not tilted, day and night would always be equal everywhere, and there would be no changing of seasons.","memoryTip":"कर्क रेखा भी 23.5° है, और पृथ्वी का झुकाव भी 23.5° है।","memoryTipEn":"Earth tilts at 23.5 degrees.","related":["Seasons","Tropic of Cancer","Equinox"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PtOPbsmwDjpglc5EbX3wR', 'General Science', 'वायुमंडल में ऑक्सीजन की मात्रा कितनी है?', 'What is the percentage of Oxygen in the atmosphere?', '21%', '21%', 95, 0, '{"facts":["वायुमंडल में सबसे प्रचुर गैस नाइट्रोजन (78%) है।","ऑक्सीजन दहन (जलने) और अधिकांश जीवों के श्वसन के लिए आवश्यक है।"],"factsEn":["The most abundant gas in the atmosphere is Nitrogen (78%).","Oxygen is essential for combustion and respiration in most living organisms."],"explanationHi":"पौधे प्रकाश संश्लेषण के दौरान ऑक्सीजन छोड़ते हैं, जो हमारे वायुमंडल में इसके स्तर को बनाए रखने में मदद करता है।","explanationEn":"Plants release oxygen during photosynthesis, which helps maintain its level in our atmosphere.","memoryTip":"हवा का पांचवा हिस्सा (21%) ऑक्सीजन है।","memoryTipEn":"21 is the age of breath.","related":["Nitrogen (78%)","Atmosphere","Photosynthesis"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ipuvhdDwW7R2B9otIyvUz', 'General Science', 'वायुमंडल में कार्बनडाइऑक्साइड की मात्रा कितनी है?', 'What is the percentage of Carbon Dioxide in the atmosphere?', '0.03%', '0.03% (Historically; Now approx 0.04%)', 92, 0, '{"facts":["नोट: ग्लोबल वार्मिंग के कारण वर्तमान में यह मात्रा बढ़कर लगभग 0.04% हो गई है।","यह एक महत्वपूर्ण ग्रीनहाउस गैस है जो पृथ्वी के तापमान को बनाए रखती है।"],"factsEn":["Note: Due to global warming, this has currently increased to approximately 0.04%.","It is a crucial greenhouse gas that maintains Earth''s temperature."],"explanationHi":"पौधे प्रकाश संश्लेषण के दौरान कार्बन डाइऑक्साइड लेते हैं और ऑक्सीजन छोड़ते हैं। इसकी अधिकता से ''ग्लोबल वार्मिंग'' होती है।","explanationEn":"Plants take in carbon dioxide during photosynthesis and release oxygen. Its excess causes ''Global Warming''.","memoryTip":"0.03% (बहुत कम) होकर भी यह पृथ्वी का तापमान बढ़ा सकती है।","memoryTipEn":"Trace amounts of CO2 cause global warming.","related":["Greenhouse Effect","Global Warming","Argon (0.93%)"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('evDESut0RbIu21Y5ZcLT6', 'General Knowledge', 'ब्रॉड गेज रेलवे लाइन की चौड़ाई कितनी होती है?', 'What is the width of a Broad Gauge railway line?', '1.676 मीटर', '1.676 meters', 89, 0, '{"facts":["इसे ''इंडियन गेज'' (Indian gauge) भी कहा जाता है।","मीटर गेज (Meter Gauge) की चौड़ाई ठीक 1 मीटर होती है।"],"factsEn":["It is also known as the ''Indian gauge''.","The width of a Meter Gauge is exactly 1 meter."],"explanationHi":"ब्रॉड गेज भारत में रेलवे का सबसे व्यापक रूप से इस्तेमाल किया जाने वाला गेज है, जो बेहतर स्थिरता और अधिक भार ले जाने की क्षमता प्रदान करता है।","explanationEn":"Broad gauge is the most widely used gauge for railways in India, providing better stability and higher load-carrying capacity.","memoryTip":"1 मीटर और 676 मिलीमीटर (1.676m)।","memoryTipEn":"Broad gauge is wider than a meter (1.676m).","related":["Meter Gauge","Narrow Gauge","Indian Railways"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('84hOccZbmEXZEMf6QghoV', 'General Knowledge', 'भारत में पशुओं का सबसे बड़ा मेला कहाँ भरता है?', 'Where is the largest animal fair held in India?', 'सोनपुर (बिहार)', 'Sonepur (Bihar)', 88, 0, '{"facts":["यह मेला कार्तिक पूर्णिमा (नवंबर-दिसंबर) पर आयोजित किया जाता है।","इसे ''हरिहर क्षेत्र मेला'' (Harihar Kshetra Mela) भी कहा जाता है।"],"factsEn":["The fair is held on Kartik Poornima (Nov-Dec).","It is also known as the ''Harihar Kshetra Mela''."],"explanationHi":"यह एशिया का सबसे बड़ा पशु मेला है जहाँ हाथी, घोड़े, ऊंट, और पक्षियों सहित कई प्रकार के जानवरों का व्यापार होता है।","explanationEn":"It is the largest animal fair in Asia where various animals including elephants, horses, camels, and birds are traded.","memoryTip":"पशुओं का ''सोना'' (कीमती मेला) सोनपुर में लगता है।","memoryTipEn":"Sonepur hosts the biggest cattle show.","related":["Pushkar Camel Fair","Harihar Kshetra Mela","Bihar"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BB6flZPnzcezWw0OIdQJ9', 'General Knowledge', '38वीं पैरेलल (38th Parallel) किन दो देशों को बाँटती है?', 'The 38th Parallel divides which two countries?', 'उत्तर और दक्षिण कोरिया', 'North and South Korea', 92, 0, '{"facts":["यह 38° उत्तरी अक्षांश (North latitude) रेखा है।","द्वितीय विश्व युद्ध के अंत में कोरिया को इसी रेखा के पास विभाजित किया गया था।"],"factsEn":["It is the line of 38° North latitude.","Korea was divided near this line at the end of World War II."],"explanationHi":"आज ''कोरियाई असैन्यीकृत क्षेत्र'' (Demilitarized Zone - DMZ) इस 38वें समानांतर रेखा के पास ही स्थित है।","explanationEn":"Today, the ''Korean Demilitarized Zone'' (DMZ) is located near this 38th parallel.","memoryTip":"3 और 8 (38) ने कोरिया के दो टुकड़े कर दिए।","memoryTipEn":"38th Parallel splits Korea.","related":["49th Parallel (USA and Canada)","Korean War","DMZ"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('LBkXd13ta791cIbiG6xCk', 'General Knowledge', '''अष्टाध्यायी'' किसने लिखी?', 'Who wrote the ''Ashtadhyayi''?', 'पाणिनि', 'Panini', 94, 0, '{"facts":["यह संस्कृत व्याकरण (Grammar) का सबसे प्राचीन और प्रामाणिक ग्रंथ है।","''अष्टाध्यायी'' का अर्थ है ''आठ अध्याय'' (Eight Chapters)।"],"factsEn":["It is the oldest and most authentic text on Sanskrit grammar.","''Ashtadhyayi'' translates to ''Eight Chapters''."],"explanationHi":"पाणिनि ने इस ग्रंथ में संस्कृत भाषा के नियमों को लगभग 4,000 सूत्रों में पिरोया है।","explanationEn":"Panini encapsulated the rules of the Sanskrit language into nearly 4,000 sutras in this text.","memoryTip":"8 अध्याय का ''पानी'' (पाणिनि) पियो और व्याकरण सीखो।","memoryTipEn":"Panini penned the grammar rules.","related":["Sanskrit Grammar","Patanjali (Mahabhashya)","Ancient Indian Literature"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('V1UbNF9FFWd5usL7WWmoQ', 'General Science', 'बल्ब का फिलामेंट किसका बना होता है?', 'What is the filament of an electric bulb made of?', 'टंगस्टन', 'Tungsten', 95, 0, '{"facts":["टंगस्टन का प्रतीक ''W'' (Wolfram) है।","इसका गलनांक (Melting point) बहुत उच्च (लगभग 3422°C) होता है।"],"factsEn":["The symbol for Tungsten is ''W'' (Wolfram).","It has a very high melting point (approx 3422°C)."],"explanationHi":"उच्च गलनांक के कारण यह बिजली प्रवाहित होने पर अत्यधिक गर्म होकर पिघले बिना प्रकाश (Light) देता है।","explanationEn":"Due to its high melting point, it glows intensely without melting when an electric current passes through it, producing light.","memoryTip":"बल्ब के अंदर का तार 3 हज़ार डिग्री तक ''टंग'' (टंगस्टन) जाता है।","memoryTipEn":"Tungsten withstands the heat.","related":["Melting Point","Inert Gas (Argon in bulbs)","Incandescent Bulb"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('veipaRU4jotpL8G2-LAuV', 'General Knowledge', 'तीसरी बौध कौंसिल कब, कहाँ और किसके संरक्षण में हुई?', 'When, where, and under whose patronage was the Third Buddhist Council held?', '250 BC में, पाटलिपुत्र में अशोक के शासनकाल में', 'In 250 BC, at Pataliputra, under the reign of Ashoka', 93, 0, '{"facts":["इस परिषद की अध्यक्षता ''मोग्गलिपुत्त तिस्स'' (Moggaliputta Tissa) ने की थी।","इस कौंसिल में ''अभिधम्म पिटक'' (Abhidhamma Pitaka) का संकलन किया गया था।"],"factsEn":["This council was presided over by ''Moggaliputta Tissa''.","The ''Abhidhamma Pitaka'' was compiled during this council."],"explanationHi":"सम्राट अशोक ने इस परिषद का आयोजन बौद्ध धर्म को शुद्ध करने और संघ में बढ़ते मतभेदों को दूर करने के लिए किया था।","explanationEn":"Emperor Ashoka convened this council to purify Buddhism and resolve growing dissensions within the Sangha.","memoryTip":"तीसरी कौंसिल के 3 ''A'': Ashoka, Abhidhamma, And Pataliputra (P is close).","memoryTipEn":"Ashoka organized the third council at Pataliputra.","related":["Moggaliputta Tissa","Abhidhamma Pitaka","First Buddhist Council"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IVLecOFuLziggieZeL_6U', 'General Knowledge', '''त्रिपिटक'' किस धर्म के ग्रंथ हैं और किस भाषा में लिखे गए हैं?', '''Tripitaka'' are the sacred texts of which religion and in which language are they written?', 'बौद्ध धर्म, पाली', 'Buddhism, Pali', 96, 0, '{"facts":["''त्रिपिटक'' का अर्थ है ''तीन टोकरियाँ'' (Three Baskets)।","ये तीन पिटक हैं: विनय पिटक, सुत्त पिटक और अभिधम्म पिटक।"],"factsEn":["''Tripitaka'' translates to ''Three Baskets''.","The three Pitakas are: Vinaya Pitaka, Sutta Pitaka, and Abhidhamma Pitaka."],"explanationHi":"बौद्ध भिक्षुओं ने बुद्ध की शिक्षाओं और मठवासी नियमों को इन ग्रंथों में संकलित किया था, जो आम जन की भाषा ''पाली'' में लिखे गए थे।","explanationEn":"Buddhist monks compiled the Buddha''s teachings and monastic rules in these texts, written in ''Pali'', the language of the common people.","memoryTip":"बौद्धों के तीन ''पिटारे'' (त्रिपिटक) ''पाली'' भाषा में हैं।","memoryTipEn":"Three baskets of Buddhism in Pali.","related":["Sutta Pitaka","Vinaya Pitaka","Gautama Buddha"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gY_uG5Sm-BIIgK7FvMumE', 'General Knowledge', 'भारतीय प्रायद्वीप (Indian Peninsula) का क्या नाम है?', 'What is the Indian Peninsula called?', 'दक्कन का पठार (Deccan Plateau)', 'Deccan Plateau', 91, 0, '{"facts":["यह एक बड़ा त्रिकोणीय पठार है जो भारत के अधिकांश दक्षिणी भाग को कवर करता है।","इसके पश्चिम में पश्चिमी घाट (Western Ghats) और पूर्व में पूर्वी घाट (Eastern Ghats) हैं।"],"factsEn":["It is a large triangular plateau that covers most of the southern part of India.","It is bordered by the Western Ghats on the west and the Eastern Ghats on the east."],"explanationHi":"प्रायद्वीप (Peninsula) वह भूमि होती है जो तीन ओर से पानी से घिरी होती है। दक्कन का पठार पुरानी आग्नेय (Igneous) चट्टानों से बना है।","explanationEn":"A peninsula is a piece of land surrounded by water on three sides. The Deccan Plateau is made up of old igneous rocks.","memoryTip":"दक्षिण (South) का विशाल हिस्सा = दक्कन (Deccan)।","memoryTipEn":"Deccan dominates the South.","related":["Western Ghats","Peninsular Plateau","Eastern Ghats"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('MCE_rOP6iohAYU1b0RxFk', 'General Knowledge', 'गुजरात से गोवा तक समुद्री तट क्या कहलाता है?', 'What is the sea coast from Gujarat to Goa called?', 'कोंकण (Konkan)', 'Konkan', 92, 0, '{"facts":["यह भारत के पश्चिमी तट का एक ऊबड़-खाबड़ खंड है।","कोंकण रेलवे इसी तट के किनारे-किनारे चलती है, जो एक इंजीनियरिंग चमत्कार है।"],"factsEn":["It is a rugged section of the western coastline of India.","The Konkan Railway runs along this coast, known as an engineering marvel."],"explanationHi":"गोवा के दक्षिण में, कर्नाटक और केरल के तट को ''मालाबार तट'' (Malabar Coast) कहा जाता है।","explanationEn":"South of Goa, the coast of Karnataka and Kerala is called the ''Malabar Coast''.","memoryTip":"गुजरात और गोवा के बीच के ''कण-कण'' को ''कोंकण'' कहते हैं।","memoryTipEn":"Konkan coast connects Gujarat and Goa.","related":["Malabar Coast","Coromandel Coast","Konkan Railway"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zZqJO6dg7Wa0YU0YJRM4V', 'General Knowledge', 'अंडमान निकोबार द्वीप समूह में कितने द्वीप हैं?', 'How many islands are there in the Andaman and Nicobar Islands group?', '324 (पीडीएफ स्रोत अनुसार)', '324 (As per PDF source)', 88, 0, '{"facts":["नोट: वर्तमान भारत सरकार के आधिकारिक आंकड़ों के अनुसार, अंडमान और निकोबार में कुल 572 द्वीप हैं (जिनमें से केवल 38 बसे हुए हैं)।","इनकी राजधानी पोर्ट ब्लेयर (Port Blair) है।"],"factsEn":["Note: According to current official Govt of India data, there are 572 islands in total (only 38 are inhabited).","Their capital is Port Blair."],"explanationHi":"परीक्षाओं में पुरानी किताबों (324) और नए आंकड़ों (572) दोनों का ध्यान रखें। ये द्वीप बंगाल की खाड़ी में स्थित हैं।","explanationEn":"Be mindful of both old textbook figures (324) and new data (572) for exams. These islands are located in the Bay of Bengal.","memoryTip":"बंगाल की खाड़ी में 324 (या 572) द्वीपों का समूह है।","memoryTipEn":"572 dots in the Bay of Bengal.","related":["Barren Island","Ten Degree Channel","Port Blair"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oaPTFvCUsquWmDSB-NzYe', 'General Knowledge', '42वें संविधान संशोधन द्वारा कौनसे 2 शब्द प्रस्तावना (Preamble) में जोड़े गए?', 'Which two words were added to the Preamble by the 42nd Constitutional Amendment?', 'धर्मनिरपेक्ष (Secular) और समाजवादी (Socialist)', 'Secular and Socialist', 97, 0, '{"facts":["इनके अलावा एक और शब्द ''अखंडता'' (Integrity) भी जोड़ा गया था।","42वां संशोधन 1976 में आपातकाल के दौरान लाया गया था।"],"factsEn":["Besides these, the word ''Integrity'' was also added.","The 42nd Amendment was enacted during the Emergency in 1976."],"explanationHi":"यह एकमात्र अवसर है जब भारतीय संविधान की प्रस्तावना (Preamble) में संशोधन किया गया है। 42वें संशोधन को ''मिनी संविधान'' भी कहते हैं।","explanationEn":"This is the only time the Preamble to the Indian Constitution has been amended. The 42nd Amendment is also called the ''Mini Constitution''.","memoryTip":"42 में प्रस्तावना में ''समाज'' को ''धर्म'' (निरपेक्ष) से जोड़ा।","memoryTipEn":"Secular, Socialist, and Integrity added in ''76.","related":["Preamble of India","Mini Constitution","Integrity"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('otBCOdLmpZumJThsszm6o', 'General Knowledge', 'एक रुपए के नोट पर किसके हस्ताक्षर होते हैं?', 'Whose signature is on the one rupee note?', 'सचिव, वित्त मंत्रालय (Finance Secretary)', 'Finance Secretary, Ministry of Finance', 95, 0, '{"facts":["1 रुपये के नोट को छोड़कर बाकी सभी करेंसी नोटों पर ''रिज़र्व बैंक के गवर्नर'' (RBI Governor) के हस्ताक्षर होते हैं।","1 रुपये का नोट भारत सरकार (Government of India) द्वारा जारी किया जाता है, न कि RBI द्वारा।"],"factsEn":["Except for the 1 rupee note, all other currency notes bear the signature of the ''RBI Governor''.","The 1 rupee note is issued by the Government of India, not the RBI."],"explanationHi":"इसे ''सिक्का अधिनियम'' के तहत मुद्रित किया जाता है और यह एक ''फिएट मनी'' (Fiat money) है।","explanationEn":"It is printed under the Coinage Act and is a form of ''fiat money''.","memoryTip":"सबसे छोटा नोट (1 रुपया) बैंक का गवर्नर नहीं, वित्त सचिव साइन करता है।","memoryTipEn":"One rupee note is the Secretary''s signature.","related":["RBI Governor","Fiat Money","Ministry of Finance"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('O6Op9sK3vJd3eebIKxOqj', 'General Knowledge', 'संसद के दो सत्रों (Sessions) के बीच अधिकतम अवधि कितनी हो सकती है?', 'What is the maximum gap allowed between two sessions of Parliament?', '6 मास (महीने)', '6 months', 94, 0, '{"facts":["संविधान के अनुसार, संसद की बैठक एक वर्ष में कम से कम दो बार होनी चाहिए।","भारत में आमतौर पर तीन सत्र होते हैं: बजट, मानसून और शीतकालीन सत्र।"],"factsEn":["According to the Constitution, Parliament must meet at least twice a year.","In India, there are usually three sessions: Budget, Monsoon, and Winter session."],"explanationHi":"यह नियम सुनिश्चित करता है कि सरकार लोकतांत्रिक रूप से जवाबदेह (Accountable) बनी रहे और नियमित रूप से विधायी कार्य होते रहें।","explanationEn":"This rule ensures that the government remains democratically accountable and legislative work occurs regularly.","memoryTip":"संसद को हर ''छमाही'' (6 महीने) में मिलना ही पड़ेगा।","memoryTipEn":"Six months maximum gap for sessions.","related":["Parliament Sessions","Budget Session","Monsoon Session"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0dWIHTnc5z6sj1mndU4NG', 'General Knowledge', '''ऋतुसंहार'', ''कुमारसंभव'', ''रघुवंशम'' किसकी रचनाएँ हैं?', '''Ritusamhara'', ''Kumarasambhava'', and ''Raghuvamsha'' are the works of whom?', 'कालिदास', 'Kalidasa', 95, 0, '{"facts":["कालिदास गुप्त काल के महान संस्कृत कवि और नाटककार थे।","उनकी सबसे प्रसिद्ध रचना नाटक ''अभिज्ञानशाकुंतलम्'' है।"],"factsEn":["Kalidasa was a great Sanskrit poet and dramatist of the Gupta period.","His most famous work is the play ''Abhijnanashakuntalam''."],"explanationHi":"''रघुवंशम'' भगवान राम के वंशजों (इक्ष्वाकु वंश) का वर्णन करता है, और ''कुमारसंभव'' भगवान शिव और पार्वती के पुत्र कार्तिकेय के जन्म की कहानी है।","explanationEn":"''Raghuvamsha'' describes the descendants of Lord Rama (Ikshvaku dynasty), and ''Kumarasambhava'' is the story of the birth of Kartikeya, son of Shiva and Parvati.","memoryTip":"कालिदास ने ''ऋतुओं'' और ''कुमारों'' (कुमारसंभव) का सुंदर वर्णन किया।","memoryTipEn":"Kalidasa composed the classic Sanskrit epics.","related":["Abhijnanashakuntalam","Meghaduta","Sanskrit Literature"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9GYfRk8mImg-FPdICjtTs', 'General Knowledge', 'अजन्ता और एलोरा की गुफाएँ कहाँ हैं?', 'Where are the Ajanta and Ellora caves located?', 'औरंगाबाद (महाराष्ट्र)', 'Aurangabad (Maharashtra)', 96, 0, '{"facts":["अजंता की गुफाएं मुख्य रूप से बौद्ध धर्म से संबंधित भित्तिचित्रों (Fresco paintings) के लिए प्रसिद्ध हैं।","एलोरा की गुफाओं में हिंदू, बौद्ध और जैन धर्मों के मंदिर हैं (जैसे प्रसिद्ध कैलाश मंदिर)।"],"factsEn":["Ajanta caves are famous mainly for Buddhist fresco paintings.","Ellora caves feature Hindu, Buddhist, and Jain temples (like the famous Kailash Temple)."],"explanationHi":"ये दोनों ही यूनेस्को (UNESCO) विश्व धरोहर स्थल हैं और प्राचीन भारतीय रॉक-कट (चट्टान काटकर बनाई गई) वास्तुकला के उत्कृष्ट उदाहरण हैं।","explanationEn":"Both are UNESCO World Heritage Sites and are outstanding examples of ancient Indian rock-cut architecture.","memoryTip":"अजंता-एलोरा ''औरंगाबाद'' के गौरव हैं।","memoryTipEn":"Aurangabad hosts the ancient caves.","related":["Kailash Temple (Ellora)","UNESCO World Heritage","Rock-cut Architecture"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('10slqUBQr3c972iZU3hxH', 'General Knowledge', 'महाबलीपुरम के रथ मंदिर (Rath Temples) किसने बनवाए थे?', 'Who built the Rath Temples of Mahabalipuram?', 'पल्लव राजा नरसिंहवर्मन ने', 'Pallava King Narasimhavarman I', 93, 0, '{"facts":["इन्हें ''पंच रथ'' (Pancha Rathas) भी कहा जाता है, जो पांडवों के नाम पर हैं।","ये तमिलनाडु के कांचीपुरम जिले में स्थित हैं।"],"factsEn":["They are also known as ''Pancha Rathas'' named after the Pandavas.","They are located in the Kanchipuram district of Tamil Nadu."],"explanationHi":"ये एक ही बड़ी चट्टान (Monolithic) को काटकर रथ के आकार में बनाए गए मंदिर हैं, जो पल्लव वास्तुकला का बेहतरीन उदाहरण हैं।","explanationEn":"These are temples carved out of a single large rock (Monolithic) in the shape of chariots, presenting a fine example of Pallava architecture.","memoryTip":"महाबली (महान बली) नरसिंह ने रथ बनवाए।","memoryTipEn":"Narasimhavarman sculpted the monolithic chariots.","related":["Pallava Dynasty","Monolithic Architecture","Shore Temple"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('maSbOFRJpTFuLyOOt8p_n', 'General Knowledge', 'भारत के कितने प्रतिशत भू-भाग पर वन (Forests) हैं?', 'What percentage of India''s land area is covered by forests?', '19% (ऐतिहासिक/पीडीएफ अनुसार)', '19% (Historically / As per PDF)', 88, 0, '{"facts":["महत्वपूर्ण अद्यतन: ''इंडिया स्टेट ऑफ फॉरेस्ट रिपोर्ट'' (ISFR 2021) के अनुसार भारत का कुल वन और वृक्ष आवरण लगभग 24.62% है।","राष्ट्रीय वन नीति के अनुसार देश के 33% भू-भाग पर वन होने चाहिए।"],"factsEn":["Important Update: As per the ''India State of Forest Report'' (ISFR 2021), India''s total forest and tree cover is approx 24.62%.","According to the National Forest Policy, 33% of the land area should be under forest cover."],"explanationHi":"परीक्षाओं के लिए नवीनतम रिपोर्ट (24.62%) याद रखें। मध्य प्रदेश में सबसे बड़ा वन क्षेत्र है।","explanationEn":"Remember the latest report (24.62%) for exams. Madhya Pradesh has the largest forest cover area.","memoryTip":"लक्ष्य 33% है, लेकिन अभी 24% के आसपास ही पहुंचे हैं।","memoryTipEn":"Forests cover about a quarter of India now.","related":["ISFR 2021","Madhya Pradesh (Highest Forest Area)","National Forest Policy"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3NGLrwXhV51sZrP__oPlx', 'General Knowledge', 'जिम कॉर्बेट नेशनल पार्क कहाँ स्थित है?', 'Where is the Jim Corbett National Park located?', 'नैनीताल के पास (उत्तराखंड)', 'Near Nainital (Uttarakhand)', 95, 0, '{"facts":["यह भारत का सबसे पुराना राष्ट्रीय उद्यान है (1936 में हेली नेशनल पार्क के रूप में स्थापित)।","यह प्रोजेक्ट टाइगर पहल (1973) के तहत आने वाला पहला पार्क था।"],"factsEn":["It is the oldest national park in India (established in 1936 as Hailey National Park).","It was the first park to come under the Project Tiger initiative (1973)."],"explanationHi":"इसका नाम प्रसिद्ध ब्रिटिश शिकारी से संरक्षणवादी (conservationist) बने जिम कॉर्बेट के नाम पर रखा गया है, जो ''बंगाल टाइगर'' के संरक्षण के लिए प्रसिद्ध है।","explanationEn":"It is named after the famous British hunter-turned-conservationist Jim Corbett, and is famous for the protection of the ''Bengal Tiger''.","memoryTip":"भारत का पहला ''पार्क'' जिम कॉर्बेट उत्तराखंड में है।","memoryTipEn":"Corbett is India''s first tiger park.","related":["Project Tiger","Bengal Tiger","Hailey National Park"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('93C1fy44tyvlX-nH8oQGm', 'General Knowledge', '''बर्डी'' (Birdie), ''ईगल'' (Eagle), ''बोगी'' (Bogey), ''पार'' (Par), ''टी'' (Tee), ''होल-इन-वन'' (Hole-in-one), शब्द किस खेल से संबंधित हैं?', 'The terms ''Birdie'', ''Eagle'', ''Bogey'', ''Par'', ''Tee'', and ''Hole-in-one'' are associated with which sport?', 'गोल्फ (Golf)', 'Golf', 89, 0, '{"facts":["गोल्फ एक ऐसा खेल है जिसमें गेंद को कम से कम स्ट्रोक (Hits) में एक छोटे छेद (Hole) में डालना होता है।","जीव मिल्खा सिंह और टाइगर वुड्स प्रसिद्ध गोल्फ खिलाड़ी हैं।"],"factsEn":["Golf is a game where the ball has to be hit into a small hole in the fewest strokes.","Jeev Milkha Singh and Tiger Woods are famous golf players."],"explanationHi":"''पार'' (Par) एक छेद को पूरा करने के लिए निर्धारित स्ट्रोक की संख्या है। ''बर्डी'' का मतलब पार से 1 कम स्ट्रोक है, और ''बोगी'' का मतलब पार से 1 ज्यादा है।","explanationEn":"''Par'' is the designated number of strokes to complete a hole. ''Birdie'' means 1 stroke under par, and ''Bogey'' means 1 stroke over par.","memoryTip":"पक्षियों के नाम (बर्डी, ईगल) गोल्फ के हरे मैदानों पर इस्तेमाल होते हैं।","memoryTipEn":"Birdie and Eagle soar in Golf.","related":["Tiger Woods","Ryder Cup","Golf Course"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('auRc_FVTz2_hW4EIodGZj', 'General Knowledge', 'साम्भर झील (Sambhar Lake) जिससे नमक बनता है, किस राज्य में है?', 'Sambhar Lake, from which salt is produced, is in which state?', 'राजस्थान', 'Rajasthan', 92, 0, '{"facts":["यह भारत की सबसे बड़ी अंतर्देशीय (Inland) खारे पानी की झील है।","यह जयपुर से लगभग 80 किमी दूर स्थित है।"],"factsEn":["It is India''s largest inland salt lake.","It is located about 80 km from Jaipur."],"explanationHi":"यह झील एक महत्वपूर्ण रामसर आर्द्रभूमि (Ramsar site) भी है जो सर्दियों के दौरान हजारों राजहंसों (Flamingos) को आकर्षित करती है। यहाँ बड़े पैमाने पर नमक उत्पादन होता है।","explanationEn":"The lake is also a crucial Ramsar wetland that attracts thousands of flamingos during winter. Large scale salt production happens here.","memoryTip":"राजस्थान के ''खारे'' रेगिस्तान में ''सांभर'' (नमक वाली) झील है।","memoryTipEn":"Sambhar is the salty lake of Rajasthan.","related":["Inland Salt Lake","Chilika Lake (Largest coastal lagoon)","Ramsar Site"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mHUkZS_SUOgkKnwKguv0x', 'General Knowledge', 'गुलाम वंश का कौनसा शासक चौगान (पोलो) खेलते समय घोड़े से गिरकर मृत्यु को प्राप्त हुआ?', 'Which ruler of the Slave Dynasty died after falling from his horse while playing Chaugan (Polo)?', 'कुतुबुद्दीन ऐबक', 'Qutb-ud-din Aibak', 95, 0, '{"facts":["वह दिल्ली सल्तनत का पहला सुल्तान और गुलाम वंश (Slave Dynasty) का संस्थापक था।","उसकी मृत्यु 1210 ई. में लाहौर में हुई थी।"],"factsEn":["He was the first Sultan of the Delhi Sultanate and the founder of the Slave Dynasty.","He died in Lahore in 1210 AD."],"explanationHi":"ऐबक मुहम्मद गोरी का एक तुर्क गुलाम था। उसे ''लाख बख्श'' (लाखों का दान देने वाला) भी कहा जाता था। उसने ही कुतुबमीनार का निर्माण शुरू कराया था।","explanationEn":"Aibak was a Turkic slave of Muhammad Ghori. He was also called ''Lakh Bakhsh'' (giver of lakhs). He initiated the construction of Qutub Minar.","memoryTip":"पोलो (चौगान) खेलते समय घोड़े से गिरकर ''ऐबक'' का खेल खत्म हो गया।","memoryTipEn":"Aibak fell playing polo.","related":["Slave Dynasty","Qutub Minar","Lakh Bakhsh"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BF24Eko9OUSeuMEItoEAZ', 'General Knowledge', '''गीत गोविन्द'' (Gita Govinda) किसने लिखी?', 'Who wrote ''Gita Govinda''?', 'जयदेव', 'Jayadeva', 93, 0, '{"facts":["यह 12वीं शताब्दी का एक संस्कृत काव्य है।","इसमें भगवान कृष्ण और राधा के प्रेम और रासलीला का सुंदर वर्णन किया गया है।"],"factsEn":["It is a 12th-century Sanskrit poem.","It beautifully describes the love and Raslila of Lord Krishna and Radha."],"explanationHi":"जयदेव बंगाल के सेन वंश के राजा लक्ष्मण सेन के दरबार के प्रमुख कवियों में से एक थे। इस ग्रंथ का भारतीय शास्त्रीय नृत्यों पर गहरा प्रभाव पड़ा है।","explanationEn":"Jayadeva was one of the prominent poets in the court of King Lakshmana Sen of the Sena dynasty of Bengal. This text deeply influenced Indian classical dances.","memoryTip":"कृष्ण (गोविंद) की ''जय'' हो = जयदेव ने गीत गोविंद लिखा।","memoryTipEn":"Jayadeva sang the songs of Govinda.","related":["Sanskrit Literature","Radha Krishna","Bhakti Movement"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3uamNzwoiZfFy0RQdiI65', 'General Knowledge', 'खुजराहो के मंदिर किस वंश के शासकों ने बनवाए?', 'The temples of Khajuraho were built by the rulers of which dynasty?', 'चंदेल (Chandela)', 'Chandela', 96, 0, '{"facts":["ये मंदिर मध्य प्रदेश के छतरपुर जिले में स्थित हैं।","इनका निर्माण 950 ई. से 1050 ई. के बीच हुआ था।"],"factsEn":["These temples are located in the Chhatarpur district of Madhya Pradesh.","They were built between 950 AD and 1050 AD."],"explanationHi":"खजुराहो के मंदिर हिंदू और जैन धर्म दोनों को समर्पित हैं और अपनी नागर वास्तुकला (Nagara style) तथा कामुक मूर्तियों (Erotic sculptures) के लिए विश्व धरोहर स्थल हैं।","explanationEn":"The Khajuraho temples are dedicated to both Hinduism and Jainism and are a World Heritage Site famous for their Nagara style architecture and erotic sculptures.","memoryTip":"खजुराहो के मंदिर ''चांद'' (चंदेल) की रोशनी में चमकते हैं।","memoryTipEn":"Chandelas carved Khajuraho.","related":["Nagara Architecture","Madhya Pradesh","Kandariya Mahadeva Temple"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3GK99nQ8CLDBpcMlLXNvo', 'General Knowledge', 'विजयनगर साम्राज्य की स्थापना कब और किसने की थी?', 'When and who founded the Vijayanagara Empire?', '1336 में हरिहर और बुक्का ने', 'In 1336 by Harihara and Bukka', 95, 0, '{"facts":["इस साम्राज्य की राजधानी ''हम्पी'' (Hampi) थी, जो कर्नाटक में तुंगभद्रा नदी के तट पर स्थित है।","राजा कृष्णदेव राय (Krishnadevaraya) इस साम्राज्य के सबसे महान शासक थे।"],"factsEn":["The capital of this empire was ''Hampi'', located on the banks of the Tungabhadra River in Karnataka.","King Krishnadevaraya was the greatest ruler of this empire."],"explanationHi":"मध्यकालीन दक्षिण भारत में यह एक बहुत ही शक्तिशाली हिंदू साम्राज्य था जिसने दक्कन में इस्लामी सल्तनतों के विस्तार को रोका था।","explanationEn":"It was a very powerful Hindu empire in medieval South India that halted the expansion of Islamic sultanates in the Deccan.","memoryTip":"दो भाइयों (हरिहर-बुक्का) ने मिलकर ''विजय'' का नगर बसाया।","memoryTipEn":"Harihara and Bukka built the city of Victory (Vijayanagara).","related":["Hampi","Krishnadevaraya","Tungabhadra River"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dexSHLdnOOyJXRMHLzcCn', 'General Knowledge', 'घना पक्षी विहार (Keoladeo National Park) कहाँ स्थित है?', 'Where is the Ghana Bird Sanctuary (Keoladeo National Park) located?', 'भरतपुर (राजस्थान)', 'Bharatpur (Rajasthan)', 92, 0, '{"facts":["इसे पहले ''भरतपुर पक्षी अभयारण्य'' के नाम से जाना जाता था।","यह एक यूनेस्को विश्व धरोहर स्थल (UNESCO World Heritage Site) है।"],"factsEn":["It was formerly known as the ''Bharatpur Bird Sanctuary''.","It is a UNESCO World Heritage Site."],"explanationHi":"सर्दियों के दौरान यह स्थान हजारों प्रवासी पक्षियों (जैसे साइबेरियन क्रेन) का घर बन जाता है। यह पक्षी विज्ञानियों (Ornithologists) के लिए स्वर्ग है।","explanationEn":"During winter, this place becomes home to thousands of migratory birds (like the Siberian Crane). It is a paradise for ornithologists.","memoryTip":"भरतपुर के ''घने'' जंगल में पक्षी रहते हैं।","memoryTipEn":"Bharatpur is a bird''s paradise.","related":["Keoladeo National Park","Siberian Crane","Migratory Birds"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vTY7Oan379XndGTicanAp', 'General Knowledge', 'भारत में जंगली गधे (Wild Asses) कहाँ पाए जाते हैं?', 'Where are Wild Asses found in India?', 'कच्छ के रण (गुजरात) में', 'Rann of Kutch (Gujarat)', 94, 0, '{"facts":["कच्छ का रण एक विशाल नमक का दलदल (Salt marsh) है।","यहाँ ''भारतीय जंगली गधा अभयारण्य'' (Indian Wild Ass Sanctuary) स्थित है, जो भारत का सबसे बड़ा वन्यजीव अभयारण्य है।"],"factsEn":["The Rann of Kutch is a massive salt marsh.","The ''Indian Wild Ass Sanctuary'' located here is the largest wildlife sanctuary in India."],"explanationHi":"भारतीय जंगली गधे को स्थानीय भाषा में ''घुड़खुर'' (Ghudkhur) कहा जाता है। यह एक लुप्तप्राय (Endangered) प्रजाति है जो केवल इसी क्षेत्र में पाई जाती है।","explanationEn":"The Indian Wild Ass is locally called ''Ghudkhur''. It is an endangered species found exclusively in this region.","memoryTip":"गुजरात के सफेद रण में ''गधे'' आज़ाद घूमते हैं।","memoryTipEn":"Wild asses roam the Rann of Kutch.","related":["Rann of Kutch","Asiatic Lion (Gir, Gujarat)","Salt Marsh"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('EYOoCDpSufG4GBzZdd2bd', 'General Knowledge', 'मीन कैम्फ (Mein Kampf - ''मेरा संघर्ष'') किसकी जीवनी है?', 'Whose autobiography is ''Mein Kampf'' (My Struggle)?', 'अडोल्फ हिटलर', 'Adolf Hitler', 93, 0, '{"facts":["हिटलर ने यह पुस्तक 1924 में एक असफल तख्तापलट (Beer Hall Putsch) के बाद जेल में रहने के दौरान लिखी थी।","इस पुस्तक में उसने अपनी घृणित यहूदी विरोधी (Antisemitic) विचारधारा और जर्मनी के भविष्य की योजनाओं का वर्णन किया है।"],"factsEn":["Hitler wrote this book while in prison in 1924 following a failed coup (Beer Hall Putsch).","In this book, he outlined his hateful antisemitic ideology and plans for Germany''s future."],"explanationHi":"यह पुस्तक जर्मनी की नाज़ी पार्टी (Nazi Party) का बाइबिल बन गई थी, जिसके कारण अंततः द्वितीय विश्व युद्ध और होलोकॉस्ट हुआ।","explanationEn":"This book became the bible of Germany''s Nazi Party, which ultimately led to World War II and the Holocaust.","memoryTip":"हिटलर का घृणित ''संघर्ष'' = मीन कैम्फ।","memoryTipEn":"Hitler''s hate was written in Mein Kampf.","related":["Nazi Germany","World War II","Holocaust"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ioXdjrKBvoUJuMgMbUiy_', 'General Knowledge', 'दास कैपिटल (Das Kapital) किसकी रचना है?', 'Who is the author of ''Das Kapital''?', 'कार्ल मार्क्स (Karl Marx)', 'Karl Marx', 95, 0, '{"facts":["यह पुस्तक 1867 में प्रकाशित हुई थी।","कार्ल मार्क्स ने फ्रेडरिक एंगेल्स के साथ मिलकर ''द कम्युनिस्ट मेनिफेस्टो'' (The Communist Manifesto) भी लिखा था।"],"factsEn":["This book was published in 1867.","Karl Marx also co-authored ''The Communist Manifesto'' with Friedrich Engels."],"explanationHi":"इस पुस्तक में मार्क्स ने पूंजीवाद (Capitalism) की कड़ी आलोचना की है और बताया है कि यह किस तरह से मज़दूर वर्ग का शोषण करता है।","explanationEn":"In this book, Marx heavily critiques Capitalism and explains how it exploits the working class.","memoryTip":"मार्क्स ने ''कैपिटल'' (पूंजीवाद) के खिलाफ ''दास कैपिटल'' लिखी।","memoryTipEn":"Marx critiqued Capital in Das Kapital.","related":["Communism","Friedrich Engels","The Communist Manifesto"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nnxiQOoKFBaLgbdxP0r4a', 'General Knowledge', 'महमूद गजनवी ने सोमनाथ मंदिर को कब लुटा था?', 'When did Mahmud of Ghazni plunder the Somnath Temple?', '1025 ईस्वी में', 'In 1025 AD', 94, 0, '{"facts":["सोमनाथ मंदिर गुजरात के पश्चिमी तट (सौराष्ट्र) पर स्थित है।","यह भगवान शिव के बारह ज्योतिर्लिंगों में से पहला माना जाता है।"],"factsEn":["The Somnath Temple is located on the western coast (Saurashtra) of Gujarat.","It is considered the first of the twelve Jyotirlingas of Lord Shiva."],"explanationHi":"गजनवी ने भारत पर 17 बार आक्रमण किया। सोमनाथ पर उसका 16वां आक्रमण था, जिसमें उसने मंदिर से अथाह संपत्ति और सोना लूटा।","explanationEn":"Ghazni invaded India 17 times. Somnath was his 16th attack, during which he plundered immense wealth and gold from the temple.","memoryTip":"10-25 (दस-पच्चीस) में सोमनाथ पर महमूद गजनवी का हमला।","memoryTipEn":"1025 AD: Ghazni stripped Somnath of its gold.","related":["Somnath Temple","Jyotirlinga","Gujarat"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XnXIp7HN-ncg_KNKpCFyN', 'General Knowledge', 'कौनसा अभयारण्य (Sanctuary) एक सींग वाले गैंडों (One-horned Rhinos) के लिए प्रसिद्ध है?', 'Which sanctuary is famous for the one-horned rhinoceros?', 'काजीरंगा (असम)', 'Kaziranga (Assam)', 96, 0, '{"facts":["काजीरंगा राष्ट्रीय उद्यान एक यूनेस्को विश्व धरोहर स्थल (UNESCO World Heritage Site) है।","यहाँ दुनिया के दो-तिहाई ''महान एक सींग वाले गैंडे'' (Great One-horned Rhinoceros) पाए जाते हैं।"],"factsEn":["Kaziranga National Park is a UNESCO World Heritage Site.","It hosts two-thirds of the world''s ''Great One-horned Rhinoceros'' population."],"explanationHi":"ब्रह्मपुत्र नदी के बाढ़ के मैदानों में स्थित यह पार्क न केवल गैंडों के लिए बल्कि बाघों, हाथियों और जंगली भैंसों के लिए भी प्रसिद्ध है।","explanationEn":"Located in the floodplains of the Brahmaputra river, this park is famous not only for rhinos but also for tigers, elephants, and wild water buffaloes.","memoryTip":"असम का ''काज़ी'' एक सींग वाले गैंडे की रक्षा करता है।","memoryTipEn":"Kaziranga protects the rhinos.","related":["Manas National Park","Brahmaputra River","UNESCO Heritage"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('T-d2yjP1EBHQARw32m6zp', 'General Knowledge', '''रिपब्लिक'' (The Republic) पुस्तक किसने लिखी?', 'Who wrote the book ''The Republic''?', 'प्लेटो ने (Plato)', 'Plato', 92, 0, '{"facts":["प्लेटो प्राचीन यूनान (Greece) के एक महान दार्शनिक थे।","वे सुकरात (Socrates) के छात्र और अरस्तू (Aristotle) के शिक्षक थे।"],"factsEn":["Plato was a great philosopher of ancient Greece.","He was the student of Socrates and the teacher of Aristotle."],"explanationHi":"इस पुस्तक में न्याय (Justice), एक आदर्श समाज के आदेश और एक दार्शनिक राजा (Philosopher King) की अवधारणा पर चर्चा की गई है।","explanationEn":"The book discusses justice, the order of an ideal society, and the concept of a ''Philosopher King''.","memoryTip":"प्लेटो की ''प्लेट'' में ''रिपब्लिक'' (न्याय) परोसा गया।","memoryTipEn":"Plato pondered the Republic.","related":["Socrates","Aristotle","Greek Philosophy"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Zm7M1XF_b4CtZWf8KFYye', 'General Knowledge', 'तैमूरलंग (Timur) ने दिल्ली को कब लुटा?', 'When did Timur plunder Delhi?', '1398 में', 'In 1398 AD', 93, 0, '{"facts":["तैमूर मध्य एशिया (उज्बेकिस्तान) का एक क्रूर तुर्क-मंगोल विजेता था।","उस समय दिल्ली पर तुगलक वंश (नासिरुद्दीन महमूद शाह तुगलक) का शासन था।"],"factsEn":["Timur was a ruthless Turco-Mongol conqueror from Central Asia (Uzbekistan).","At that time, Delhi was ruled by the Tughlaq dynasty (Nasiruddin Mahmud Shah Tughlaq)."],"explanationHi":"तैमूर के आक्रमण ने दिल्ली को पूरी तरह से बर्बाद कर दिया, हजारों लोगों को मार डाला और शहर की सारी संपत्ति लूट ली, जिससे तुगलक वंश का पतन हो गया।","explanationEn":"Timur''s invasion completely devastated Delhi, massacring thousands and looting all the city''s wealth, leading to the collapse of the Tughlaq dynasty.","memoryTip":"13-98 में तैमूर ने दिल्ली में 98% तबाही मचाई।","memoryTipEn":"Timur''s terror in 1398.","related":["Tughlaq Dynasty","Nadir Shah (1739)","Mongol Invasions"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('z-DCs5EtzsnKxVmSDLqsB', 'General Knowledge', 'ओलंपिक खेलों में हॉकी कब शामिल किया गया?', 'When was Field Hockey included in the Olympic Games?', '1928 के एम्स्टर्डम (हॉलैंड) ओलंपिक में', 'In the 1928 Amsterdam (Holland) Olympics', 91, 0, '{"facts":["इसी ओलंपिक में भारत ने अपना पहला हॉकी स्वर्ण पदक जीता था।","हॉकी के जादूगर ''मेजर ध्यानचंद'' उस टीम के मुख्य आकर्षण थे।"],"factsEn":["India won its first hockey gold medal in this very Olympics.","The hockey wizard ''Major Dhyan Chand'' was the star attraction of that team."],"explanationHi":"भारत ने इसके बाद 1928 से 1956 तक लगातार 6 ओलंपिक स्वर्ण पदक जीतकर हॉकी में अपना अभूतपूर्व दबदबा कायम किया।","explanationEn":"India went on to establish an unprecedented dominance in hockey by winning 6 consecutive Olympic gold medals from 1928 to 1956.","memoryTip":"1928 से भारत के हॉकी का ''स्वर्णिम'' युग (Amsterdam) शुरू हुआ।","memoryTipEn":"Amsterdam 1928 began India''s Hockey Gold rush.","related":["Major Dhyan Chand","Indian National Hockey Team","1928 Summer Olympics"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4y2NGLx2IM8lEK4Y7tj0J', 'General Knowledge', 'शेरशाह सूरी को कहाँ दफनाया गया?', 'Where is Sher Shah Suri buried?', 'सासाराम (बिहार)', 'Sasaram (Bihar)', 94, 0, '{"facts":["शेरशाह सूरी का मकबरा (Tomb) एक कृत्रिम झील के बीचो-बीच बना हुआ एक शानदार इंडो-इस्लामिक स्मारक है।","शेरशाह ने हुमायूँ को हराकर भारत में ''सूरी साम्राज्य'' की स्थापना की थी।"],"factsEn":["The tomb of Sher Shah Suri is a magnificent Indo-Islamic monument built in the middle of an artificial lake.","Sher Shah defeated Humayun and established the ''Suri Empire'' in India."],"explanationHi":"उसकी मृत्यु 1545 में कालिंजर किले की घेराबंदी के दौरान एक बारूद विस्फोट के कारण हुई थी। उसने ही ''ग्रांड ट्रंक रोड'' (GT Road) का निर्माण कराया था।","explanationEn":"He died in 1545 due to a gunpowder explosion during the siege of the Kalinjar fort. He is the one who built the ''Grand Trunk Road'' (GT Road).","memoryTip":"शेर को ''सास'' (सासाराम) ने दफनाया।","memoryTipEn":"Sher Shah sleeps in Sasaram.","related":["Grand Trunk Road","Suri Empire","Humayun"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5Ftk2jgraaXDBT-VvMSme', 'General Science', 'न्यूट्रान (Neutron) की खोज किसने की?', 'Who discovered the Neutron?', 'जेम्स चेडविक ने (James Chadwick)', 'James Chadwick', 95, 0, '{"facts":["चेडविक ने 1932 में न्यूट्रॉन की खोज की थी।","इस खोज के लिए उन्हें 1935 में भौतिकी का नोबेल पुरस्कार मिला था।"],"factsEn":["Chadwick discovered the neutron in 1932.","He received the Nobel Prize in Physics in 1935 for this discovery."],"explanationHi":"न्यूट्रॉन परमाणु के नाभिक (Nucleus) में मौजूद एक उप-परमाणु कण है जिस पर कोई विद्युत आवेश (Neutral) नहीं होता है।","explanationEn":"A neutron is a subatomic particle found in the nucleus of an atom that carries no electrical charge (Neutral).","memoryTip":"PEN = RTC (Proton-Rutherford, Electron-Thomson, Neutron-Chadwick).","memoryTipEn":"Chadwick charted the Neutron.","related":["Proton (Rutherford)","Electron (J.J. Thomson)","Atomic Nucleus"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('k9_-cfYEoFjoyiZ3jvBUd', 'General Science', 'परमाणु रिएक्टर (Nuclear Reactor) में मंदक (Moderator) के रूप में किसका प्रयोग किया जाता है?', 'What is used as a moderator in a nuclear reactor?', 'भारी पानी और ग्रेफाइट का', 'Heavy water and Graphite', 94, 0, '{"facts":["भारी पानी (Heavy Water) का रासायनिक सूत्र D₂O (Deuterium oxide) होता है।","कैडमियम या बोरॉन की छड़ों का उपयोग ''नियंत्रक छड़'' (Control rods) के रूप में किया जाता है।"],"factsEn":["The chemical formula of Heavy Water is D₂O (Deuterium oxide).","Rods of Cadmium or Boron are used as ''Control rods''."],"explanationHi":"मंदक का कार्य नाभिकीय विखंडन के दौरान निकलने वाले तेज़ न्यूट्रॉनों (Neutrons) की गति को धीमा करना है ताकि श्रृंखला प्रतिक्रिया (Chain reaction) निरंतर चलती रहे।","explanationEn":"The moderator''s job is to slow down the fast neutrons released during nuclear fission so that the chain reaction can be sustained.","memoryTip":"रिएक्टर की स्पीड ''मंद'' करने के लिए ''भारी'' पानी डालते हैं।","memoryTipEn":"Heavy water calms the reactor down.","related":["Deuterium Oxide (D2O)","Nuclear Fission","Control Rods"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Rit6ztf8hHNGjBpylyGzx', 'General Knowledge', 'विश्व का सबसे छोटा महाद्वीप कौनसा है?', 'Which is the smallest continent in the world?', 'ऑस्ट्रेलिया (Australia)', 'Australia', 92, 0, '{"facts":["ऑस्ट्रेलिया को एक ''द्वीप महाद्वीप'' (Island Continent) भी कहा जाता है क्योंकि यह पूरी तरह से पानी से घिरा है।","क्षेत्रफल के हिसाब से एशिया सबसे बड़ा महाद्वीप है।"],"factsEn":["Australia is also called an ''Island Continent'' because it is completely surrounded by water.","Asia is the largest continent by area."],"explanationHi":"ऑस्ट्रेलिया एकमात्र ऐसा स्थान है जिसे एक ही समय में एक देश और एक महाद्वीप माना जाता है। यह अपने अद्वितीय वन्यजीवों (जैसे कंगारू और कोआला) के लिए जाना जाता है।","explanationEn":"Australia is the only place that is considered both a country and a continent. It is known for its unique wildlife (like kangaroos and koalas).","memoryTip":"ऑस्ट्रेलिया महाद्वीप इतना छोटा है कि एक ही देश है।","memoryTipEn":"Australia is a country sized continent.","related":["Oceania","Asia (Largest Continent)","Island Continent"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('hzv47WWU5-kd2Nk4YKn33', 'General Knowledge', 'N.C.C. की स्थापना किस वर्ष हुई?', 'In which year was the N.C.C. established?', '1948 में', 'In 1948', 89, 0, '{"facts":["N.C.C. का पूर्ण रूप ''National Cadet Corps'' (राष्ट्रीय कैडेट कोर) है।","इसका आदर्श वाक्य (Motto) ''एकता और अनुशासन'' (Unity and Discipline) है।"],"factsEn":["N.C.C. stands for ''National Cadet Corps''.","Its motto is ''Unity and Discipline''."],"explanationHi":"यह भारतीय सशस्त्र बलों की युवा शाखा है, जिसका मुख्यालय नई दिल्ली में है और यह हाई स्कूल व कॉलेज के छात्रों के लिए स्वैच्छिक है।","explanationEn":"It is the youth wing of the Indian Armed Forces, headquartered in New Delhi, open to high school and college students on a voluntary basis.","memoryTip":"आज़ादी के एक साल बाद (1948) युवाओं की ''कोर'' (NCC) बन गई।","memoryTipEn":"NCC started post-independence in 1948.","related":["National Cadet Corps","Indian Armed Forces","Youth Organization"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('H4Sq22seUV5tsVGPWz-B0', 'General Knowledge', 'अमजद अली खान कोनसा वाद्य यंत्र बजाते हैं?', 'Which musical instrument does Amjad Ali Khan play?', 'सरोद (Sarod)', 'Sarod', 91, 0, '{"facts":["वे भारत के प्रसिद्ध शास्त्रीय सरोद वादक हैं।","उन्हें 2001 में भारत के दूसरे सबसे बड़े नागरिक सम्मान ''पद्म विभूषण'' से सम्मानित किया गया था।"],"factsEn":["He is a famous Indian classical Sarod player.","He was awarded India''s second-highest civilian honor, the ''Padma Vibhushan'', in 2001."],"explanationHi":"सरोद एक भारतीय तार वाला वाद्य यंत्र है (लूट परिवार का)। अमजद अली खान ने इसे अंतरराष्ट्रीय स्तर पर लोकप्रिय बनाया है।","explanationEn":"Sarod is an Indian stringed musical instrument (lute family). Amjad Ali Khan has popularized it internationally.","memoryTip":"अमजद अली ने ''सरोद'' के सुर छेड़े।","memoryTipEn":"Amjad Ali strikes the Sarod strings.","related":["Hindustani Classical Music","Padma Vibhushan","Pandit Ravi Shankar (Sitar)"]}', 'published', 1776085471, 1776085471);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RNTJdkLQADiZ-N9QWm0fm', 'General Knowledge', 'भारत का सबसे ऊँचा जलप्रपात कौनसा है?', 'Which is the highest waterfall in India?', 'जोग या गरसोप्पा (शरावती नदी पर, कर्नाटक)', 'Jog or Gersoppa Falls (on Sharavati river, Karnataka)', 92, 0, '{"facts":["इसे महात्मा गांधी जलप्रपात भी कहा जाता है।","नोट: वर्तमान डेटा के अनुसार कुंचीकल जलप्रपात (कर्नाटक) भारत का सबसे ऊँचा जलप्रपात है, लेकिन परीक्षाओं में ऐतिहासिक रूप से ''जोग'' पूछा जाता है।"],"factsEn":["It is also known as Mahatma Gandhi Falls.","Note: As per current data, Kunchikal Falls (Karnataka) is the highest, but ''Jog'' is historically popular in exams."],"explanationHi":"यह कर्नाटक के शिमोगा जिले में शरावती नदी पर स्थित है और सीधे नीचे गिरने वाले (plunge) पानी के लिए प्रसिद्ध है।","explanationEn":"Located on the Sharavati River in Shimoga district of Karnataka, it is famous for its direct plunge of water.","memoryTip":"शरावती नदी पर पानी ''जोग'' (जोग फॉल्स) लगाता है।","memoryTipEn":"Jog falls jumps from Sharavati.","related":["Kunchikal Falls","Sharavati River","Karnataka"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('keDmcUcIdL6P8_RCSqFQo', 'General Science', 'चन्द्रमा की पृथ्वी से दूरी कितनी है?', 'What is the distance of the Moon from the Earth?', '3,85,000 कि.मी. (लगभग)', '385,000 km (Approx)', 90, 0, '{"facts":["चंद्रमा की पृथ्वी से सटीक औसत दूरी 3,84,400 किलोमीटर है।","चंद्रमा पृथ्वी का एकमात्र प्राकृतिक उपग्रह है।"],"factsEn":["The exact average distance is 384,400 kilometers.","The Moon is Earth''s only natural satellite."],"explanationHi":"यह दूरी अपोलो मिशन के दौरान छोड़े गए लेज़र रिफ्लेक्टर का उपयोग करके बहुत सटीकता से मापी गई है।","explanationEn":"This distance has been measured very precisely using laser reflectors left behind during the Apollo missions.","memoryTip":"3 लाख 85 हज़ार किलोमीटर दूर है चंदा मामा।","memoryTipEn":"385k km to the moon.","related":["Speed of Light","Apollo 11","Tides"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('TZlXGdWtV5_aPrh0aZHq0', 'General Knowledge', 'विश्व का सबसे कम जनसंख्या वाला देश कौनसा है?', 'Which is the least populated country in the world?', 'वैटिकन सिटी', 'Vatican City', 91, 0, '{"facts":["यहाँ की जनसंख्या लगभग 800 से 1000 के बीच है।","क्षेत्रफल की दृष्टि से भी यह दुनिया का सबसे छोटा देश है।"],"factsEn":["Its population is between 800 and 1000 approximately.","It is also the smallest country in the world by area."],"explanationHi":"यह रोम (इटली) के बीच स्थित एक स्वतंत्र राज्य है और कैथोलिक ईसाइयों का सर्वोच्च धार्मिक केंद्र है।","explanationEn":"It is an independent state located within Rome (Italy) and is the supreme religious center for Catholic Christians.","memoryTip":"सबसे छोटी ''सिटी'' (वैटिकन) में सबसे कम लोग रहते हैं।","memoryTipEn":"Vatican is tiny in size and population.","related":["Pope","Rome","Smallest Country"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0Ubp7x92kp7Yd4jPiXdSF', 'General Knowledge', 'भारत में सोने (Gold) की खान कहाँ है?', 'Where are the gold mines located in India?', 'कोलार (कर्नाटक) में', 'Kolar (Karnataka)', 94, 0, '{"facts":["इसे कोलार गोल्ड फील्ड्स (KGF) के नाम से जाना जाता है।","यह दुनिया की सबसे गहरी खदानों में से एक थी, जिसे 2001 में बंद कर दिया गया था।"],"factsEn":["It is famously known as Kolar Gold Fields (KGF).","It was one of the deepest mines in the world, closed in 2001."],"explanationHi":"लंबे समय तक KGF भारत में सोने के उत्पादन का प्राथमिक स्रोत रहा। इसके अलावा हट्टी (Hutti) खदानें भी कर्नाटक में हैं।","explanationEn":"For a long time, KGF was the primary source of gold production in India. Besides this, Hutti gold mines are also in Karnataka.","memoryTip":"कोलार का सोना (KGF) पूरे भारत में मशहूर है।","memoryTipEn":"KGF stands for Kolar Gold Fields.","related":["KGF","Hutti Gold Mines","Karnataka"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4x96j-f0TjdY9M9VwkiGP', 'General Knowledge', 'भारतीय संविधान में कितनी अनुसूचियां (Schedules) हैं?', 'How many schedules are there in the Indian Constitution?', '12 अनुसूची', '12 Schedules', 96, 0, '{"facts":["मूल संविधान (1949) में केवल 8 अनुसूचियां थीं।","बाद में संशोधनों के माध्यम से 4 नई अनुसूचियां (9, 10, 11, 12) जोड़ी गईं।"],"factsEn":["The original constitution (1949) had only 8 schedules.","Later, 4 new schedules (9, 10, 11, 12) were added through amendments."],"explanationHi":"अनुसूचियों में सरकारी नीति, राज्य सूची, भाषाएं और पंचायत जैसे विस्तृत विवरण होते हैं जो अनुच्छेदों में नहीं आते।","explanationEn":"Schedules contain detailed lists regarding government policy, state territories, languages, and panchayats that are not covered in the articles.","memoryTip":"घड़ी में 12 बजते हैं, संविधान में 12 अनुसूचियां हैं।","memoryTipEn":"12 months, 12 schedules.","related":["Eighth Schedule (Languages)","Tenth Schedule (Anti-defection)","Articles of Constitution"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('85Bmu9x4v0CC2wqz7xc7x', 'General Science', 'सूर्य का प्रकाश (परावर्तित) चन्द्रमा से पृथ्वी तक पहुँचने में कितना समय लेता है?', 'How much time does reflected sunlight take to reach Earth from the Moon?', '1.3 सेकंड', '1.3 Seconds', 93, 0, '{"facts":["पृथ्वी और चंद्रमा के बीच की दूरी लगभग 3,84,400 किमी है।","प्रकाश की गति 3,00,000 किमी/सेकंड है।"],"factsEn":["The distance between Earth and Moon is about 384,400 km.","The speed of light is 300,000 km/s."],"explanationHi":"समय = दूरी / गति (3,84,400 / 3,00,000 = 1.28 सेकंड)। इसलिए चाँद की रोशनी को आने में लगभग 1.3 सेकंड लगते हैं।","explanationEn":"Time = Distance / Speed (384,400 / 300,000 = 1.28 seconds). Hence, moonlight takes about 1.3 seconds to arrive.","memoryTip":"सूरज को 500 सेकंड, तो चंदा मामा को बस 1.3 सेकंड लगते हैं।","memoryTipEn":"1.3 seconds from the moon.","related":["Speed of Light","Sunlight to Earth (8m 20s)","Lunar Eclipse"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uiBjXoRKcKmUfleMWHwAz', 'General Knowledge', 'पन्ना (मध्य प्रदेश) की खानें किसके लिए प्रसिद्ध है?', 'The mines of Panna (Madhya Pradesh) are famous for what?', 'हीरा (Diamond)', 'Diamond', 95, 0, '{"facts":["मध्य प्रदेश भारत का एकमात्र राज्य है जहाँ हीरे की व्यावसायिक खदानें हैं।","पन्ना को भारत की ''हीरा नगरी'' (Diamond City) भी कहा जाता है।"],"factsEn":["Madhya Pradesh is the only Indian state with commercial diamond mines.","Panna is also known as the ''Diamond City'' of India."],"explanationHi":"यहाँ हीरे का खनन राष्ट्रीय खनिज विकास निगम (NMDC) द्वारा किया जाता है।","explanationEn":"Diamond mining here is operated by the National Mineral Development Corporation (NMDC).","memoryTip":"पन्ना एक ''रत्न'' का नाम भी है, और यहाँ ''हीरा'' (दूसरा रत्न) मिलता है।","memoryTipEn":"Panna produces precious diamonds.","related":["NMDC","Golconda Diamonds","Madhya Pradesh"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZDpofTlJ1YdV0h_7TnnZt', 'General Knowledge', 'नील नदी का उपहार (Gift of the Nile) कौनसा देश कहलाता है?', 'Which country is called the ''Gift of the Nile''?', 'मिस्र (Egypt)', 'Egypt', 94, 0, '{"facts":["नील नदी दुनिया की सबसे लंबी नदी है।","यह कथन प्राचीन यूनानी इतिहासकार ''हेरोडोटस'' ने दिया था।"],"factsEn":["The Nile is the longest river in the world.","This statement was coined by the ancient Greek historian ''Herodotus''."],"explanationHi":"मिस्र एक रेगिस्तानी इलाका है; यदि नील नदी न होती, तो वहाँ कृषि और प्राचीन मिस्र सभ्यता का विकास संभव नहीं था।","explanationEn":"Egypt is largely a desert; without the Nile River, agriculture and the ancient Egyptian civilization could not have thrived.","memoryTip":"मिस्र (Egypt) की सभ्यता नील नदी के पानी से ही फली-फूली।","memoryTipEn":"Egypt is the gift of the Nile.","related":["Herodotus","Ancient Egypt","Longest River"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FltSkihDD_ntWBdfU0CZ_', 'General Knowledge', '''जय जवान, जय किसान, जय विज्ञान'' का नारा किसने दिया?', 'Who gave the slogan ''Jai Jawan, Jai Kisan, Jai Vigyan''?', 'अटल बिहारी वाजपेयी', 'Atal Bihari Vajpayee', 96, 0, '{"facts":["मूल नारा ''जय जवान, जय किसान'' लाल बहादुर शास्त्री ने दिया था।","1998 में पोखरण परमाणु परीक्षण की सफलता के बाद वाजपेयी जी ने इसमें ''जय विज्ञान'' जोड़ा।"],"factsEn":["The original slogan ''Jai Jawan, Jai Kisan'' was given by Lal Bahadur Shastri.","After the successful Pokhran nuclear tests in 1998, Vajpayee added ''Jai Vigyan'' to it."],"explanationHi":"यह नारा भारत के विकास में सैनिकों, किसानों और वैज्ञानिकों (विज्ञान) के महत्व को दर्शाता है। हाल ही में पीएम मोदी ने इसमें ''जय अनुसंधान'' भी जोड़ा है।","explanationEn":"This slogan reflects the importance of soldiers, farmers, and scientists (science) in India''s progress. PM Modi recently added ''Jai Anusandhan'' to it.","memoryTip":"विज्ञान (Vigyan) के युग में ''वाजपेयी'' जी ने परमाणु बम बनाया।","memoryTipEn":"Vajpayee valued Vigyan.","related":["Lal Bahadur Shastri","Pokhran-II","Narendra Modi (Jai Anusandhan)"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('d5tXtVVHzMspbvfO8_44K', 'General Knowledge', 'घाना (Ghana) देश का पुराना नाम क्या है?', 'What is the old name of the country Ghana?', 'गोल्ड कोस्ट (Gold Coast)', 'Gold Coast', 88, 0, '{"facts":["घाना पश्चिमी अफ्रीका में स्थित एक देश है।","यूरोपीय लोगों ने यहाँ प्रचुर मात्रा में सोने की खोज की थी, इसलिए इसे ''गोल्ड कोस्ट'' कहा गया।"],"factsEn":["Ghana is a country located in West Africa.","Europeans found abundant gold here, hence the name ''Gold Coast''."],"explanationHi":"1957 में ब्रिटेन से अपनी स्वतंत्रता प्राप्त करने के बाद, इस देश ने प्राचीन घाना साम्राज्य के सम्मान में अपना नाम बदलकर घाना रख लिया।","explanationEn":"After gaining independence from Britain in 1957, the country changed its name to Ghana in honor of the ancient Ghana Empire.","memoryTip":"घाना में ''घना'' (बहुत सारा) गोल्ड (Gold) था।","memoryTipEn":"Ghana was the Gold Coast.","related":["West Africa","British Empire","Kwame Nkrumah"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5x_RzTZkneHTpQV5VCGva', 'General Knowledge', 'उस्ताद जाकिर हुसैन का संबंध किस वाद्ययंत्र से हैं?', 'Ustad Zakir Hussain is associated with which musical instrument?', 'तबला', 'Tabla', 93, 0, '{"facts":["वे प्रसिद्ध तबला वादक उस्ताद अल्ला रक्खा के पुत्र हैं।","उन्हें 2023 में भारत के दूसरे सबसे बड़े नागरिक सम्मान ''पद्म विभूषण'' से सम्मानित किया गया था।"],"factsEn":["He is the son of the famous tabla player Ustad Alla Rakha.","He was awarded India''s second-highest civilian honor ''Padma Vibhushan'' in 2023."],"explanationHi":"जाकिर हुसैन ने तबला वादन को अंतरराष्ट्रीय स्तर पर नई ऊंचाइयां दी हैं और कई ग्रैमी (Grammy) पुरस्कार भी जीते हैं।","explanationEn":"Zakir Hussain has elevated Tabla playing to new international heights and has also won multiple Grammy Awards.","memoryTip":"जाकिर हुसैन के हाथ ''तबले'' पर जादू करते हैं (वाह उस्ताद)।","memoryTipEn":"Zakir taps the Tabla.","related":["Ustad Alla Rakha","Padma Vibhushan","Hindustani Classical Music"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WoSfo2EXhY3N_uL_xyyR1', 'General Knowledge', 'अमेरिका की खोज किसने की?', 'Who discovered America?', '1492 में क्रिस्टोफर कोलंबस ने', 'Christopher Columbus in 1492', 95, 0, '{"facts":["कोलंबस एक इतालवी खोजकर्ता था, जिसने स्पेन के राजा-रानी द्वारा वित्तपोषित अभियान का नेतृत्व किया।","वह भारत (एशिया) के लिए एक नया समुद्री मार्ग खोजने निकला था।"],"factsEn":["Columbus was an Italian explorer who led an expedition funded by the Spanish monarchs.","He set out to find a new sea route to India (Asia)."],"explanationHi":"गलती से वह कैरेबियाई द्वीपों पर पहुँच गया, जिसे उसने ''इंडीज'' समझा। इसीलिए वहाँ के मूल निवासियों को ''रेड इंडियन'' कहा गया।","explanationEn":"He accidentally landed in the Caribbean islands, which he mistook for the ''Indies''. That''s why the natives were called ''Red Indians''.","memoryTip":"कोलंबस 1492 में भटक कर अमेरिका पहुँच गया।","memoryTipEn":"In 1492, Columbus sailed the ocean blue.","related":["Amerigo Vespucci","Vasco da Gama","Red Indians"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('sXrLfrA-UR1zqEadauPx7', 'General Knowledge', 'वंदेमातरम् को सर्वप्रथम कांग्रेस के किस अधिवेशन में गाया गया?', 'In which session of the Congress was ''Vande Mataram'' sung for the first time?', '1896 में (कलकत्ता अधिवेशन)', 'In 1896 (Calcutta Session)', 94, 0, '{"facts":["इसे स्वयं रवीन्द्रनाथ टैगोर ने गाकर प्रस्तुत किया था।","यह गीत बंकिम चंद्र चटर्जी के उपन्यास ''आनंदमठ'' से लिया गया है।"],"factsEn":["It was sung and presented by Rabindranath Tagore himself.","The song is taken from Bankim Chandra Chatterjee''s novel ''Anandamath''."],"explanationHi":"यह गीत स्वतंत्रता संग्राम के दौरान क्रांतिकारियों के लिए एक महान प्रेरणा स्रोत (Battle cry) बन गया था।","explanationEn":"This song became a great source of inspiration (battle cry) for revolutionaries during the freedom struggle.","memoryTip":"1896 में पहली बार भारत माता की ''वंदना'' हुई।","memoryTipEn":"1896 heard the first Vande Mataram.","related":["Bankim Chandra Chatterjee","Anandamath","National Song"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('92jwqTHUAcRmp94kqEQIQ', 'General Science', '''सापेक्षता का सिद्धांत'' (Theory of Relativity) किसने खोजा था?', 'Who discovered the ''Theory of Relativity''?', 'एल्बर्ट आईन्स्टाईन (Albert Einstein)', 'Albert Einstein', 96, 0, '{"facts":["इसमें दो सिद्धांत शामिल हैं: विशेष सापेक्षता (Special Relativity, 1905) और सामान्य सापेक्षता (General Relativity, 1915)।","प्रसिद्ध समीकरण E=mc² इसी सिद्धांत से निकला है।"],"factsEn":["It includes two theories: Special Relativity (1905) and General Relativity (1915).","The famous equation E=mc² is derived from this theory."],"explanationHi":"इस सिद्धांत ने गुरुत्वाकर्षण, अंतरिक्ष और समय (Space-time) की हमारी समझ को पूरी तरह से बदल दिया। (नोट: उन्हें नोबेल पुरस्कार ''प्रकाश विद्युत प्रभाव'' के लिए मिला था)।","explanationEn":"This theory completely revolutionized our understanding of gravity, space, and time. (Note: He received the Nobel Prize for the ''Photoelectric Effect'').","memoryTip":"आइंस्टीन का E=mc² ही सापेक्षता है।","memoryTipEn":"Einstein related space and time.","related":["E=mc2","Photoelectric Effect","Physics"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kBBIOLF8MXp15glxwJy0z', 'General Science', 'वायुयान (Airplane) की खोज किसने की?', 'Who invented the Airplane?', 'ऑलिवर और विल्बर राइट बन्धु (Wright Brothers)', 'Orville and Wilbur Wright (Wright Brothers)', 95, 0, '{"facts":["उन्होंने 1903 में अमेरिका के किटी हॉक में पहली सफल उड़ान भरी थी।","उनके पहले हवाई जहाज का नाम ''राइट फ्लायर'' (Wright Flyer) था।"],"factsEn":["They made the first successful flight in Kitty Hawk, USA, in 1903.","Their first airplane was named the ''Wright Flyer''."],"explanationHi":"यह मानव इतिहास में पहली बार था जब किसी इंजन वाले, भारी-से-हवा (heavier-than-air) विमान ने नियंत्रित उड़ान भरी।","explanationEn":"This was the first time in human history that a powered, heavier-than-air aircraft achieved a controlled, sustained flight.","memoryTip":"उड़ने का ''राइट'' (Right) तरीका राइट बंधुओं ने खोजा।","memoryTipEn":"Wright Brothers took the right flight.","related":["Aviation","Kitty Hawk","1903"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vIG1bhrM92qyzqerLZqbR', 'General Science', 'प्रथम हृदय प्रत्यारोपण (Heart Transplant) किसने किया था?', 'Who performed the first Heart Transplant?', 'डॉ. क्रिश्चियन बर्नार्ड (दक्षिणी अफ्रीका)', 'Dr. Christiaan Barnard (South Africa)', 94, 0, '{"facts":["यह सफल ऑपरेशन 3 दिसंबर 1967 को केप टाउन में किया गया था।","मरीज का नाम लुई वाशकांस्की (Louis Washkansky) था।"],"factsEn":["This successful operation was performed on Dec 3, 1967, in Cape Town.","The patient''s name was Louis Washkansky."],"explanationHi":"इस सर्जरी ने चिकित्सा विज्ञान के इतिहास में एक नए युग की शुरुआत की, हालांकि मरीज सर्जरी के 18 दिन बाद निमोनिया से मर गया था।","explanationEn":"This surgery heralded a new era in the history of medical science, although the patient died of pneumonia 18 days later.","memoryTip":"दिल (हृदय) का ऑपरेशन ''बर्नार्ड'' ने किया।","memoryTipEn":"Barnard brought a new beating heart.","related":["Organ Transplant","Cardiology","Cape Town"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NPMoLLxc0lWUCrK1WR-LR', 'General Knowledge', 'सात पहाड़ियों का नगर (City of Seven Hills) कौनसा कहलाता है?', 'Which city is known as the ''City of Seven Hills''?', 'रोम (इटली)', 'Rome (Italy)', 91, 0, '{"facts":["रोम इटली की राजधानी है।","प्राचीन रोम की स्थापना इन सात पहाड़ियों (Palatine, Aventine, etc.) के इर्द-गिर्द ही हुई थी।"],"factsEn":["Rome is the capital of Italy.","Ancient Rome was founded around these seven hills (Palatine, Aventine, etc.)."],"explanationHi":"यह शहर अपनी ऐतिहासिक विरासत, रोमन साम्राज्य के केंद्र और वैटिकन सिटी को अपने अंदर समेटे होने के लिए प्रसिद्ध है।","explanationEn":"The city is famous for its historical heritage, being the center of the Roman Empire, and encompassing Vatican City within it.","memoryTip":"सात पहाड़ों पर ''रोम-रोम'' (रोम) बसा है।","memoryTipEn":"Rome rests on seven ridges.","related":["Italy","Vatican City","Colosseum"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YfEwYpm5wn5by4yt44d7J', 'General Knowledge', 'शक संवत को राष्ट्रीय पंचांग के रूप में कब अपनाया गया?', 'When was the Saka Samvat adopted as the National Calendar?', '22 मार्च 1957', '22 March 1957', 92, 0, '{"facts":["इसे ग्रेगोरियन कैलेंडर (Gregorian Calendar) के साथ आधिकारिक उद्देश्यों के लिए अपनाया गया था।","इसका पहला महीना चैत्र (Chaitra) होता है।"],"factsEn":["It was adopted alongside the Gregorian Calendar for official purposes.","Its first month is Chaitra."],"explanationHi":"यह कैलेंडर 78 ईस्वी में शक युग के शुरू होने पर आधारित है, जिसे कनिष्क (कुषाण सम्राट) ने शुरू किया था।","explanationEn":"This calendar is based on the start of the Saka Era in 78 AD, initiated by Kanishka (Kushan Emperor).","memoryTip":"57 में शक संवत को राष्ट्रीय पहचान मिली।","memoryTipEn":"1957 saw the Saka shift.","related":["Chaitra Month","Gregorian Calendar","Kanishka"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zRFB2GlGkx0Zm92z82x86', 'General Science', 'रेडियम की खोज किसने की?', 'Who discovered Radium?', 'पियरे और मैरी क्यूरी', 'Pierre and Marie Curie', 95, 0, '{"facts":["उन्होंने 1898 में पिंचब्लेंड (Pitchblende) नामक यूरेनियम अयस्क से इसे खोजा।","मैरी क्यूरी को इस कार्य के लिए 1911 में रसायन विज्ञान का नोबेल पुरस्कार मिला।"],"factsEn":["They discovered it in 1898 from a uranium ore called Pitchblende.","Marie Curie received the Nobel Prize in Chemistry in 1911 for this work."],"explanationHi":"रेडियम एक अत्यधिक रेडियोधर्मी (Radioactive) तत्व है जो अंधेरे में चमकता है। इसका उपयोग शुरुआती दौर में कैंसर के इलाज में किया गया था।","explanationEn":"Radium is a highly radioactive element that glows in the dark. It was initially used in cancer treatments.","memoryTip":"रेडियोएक्टिव रेडियम ''क्यूरी'' दंपत्ति की खोज है।","memoryTipEn":"Curie cured with Radium.","related":["Radioactivity","Polonium","Pitchblende"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8LJkSGFGWzytklchGhFy8', 'General Science', 'कितनी ऊँचाई पर जाने से तापमान 1 डिग्री C की कमी होती है?', 'At what height increase does the temperature drop by 1 degree C?', '165 मीटर', '165 meters', 90, 0, '{"facts":["इसे ''सामान्य ह्रास दर'' (Normal Lapse Rate) कहा जाता है।","यह घटना मुख्य रूप से क्षोभमंडल (Troposphere) में होती है।"],"factsEn":["This is called the ''Normal Lapse Rate''.","This phenomenon primarily occurs in the Troposphere."],"explanationHi":"जैसे-जैसे हम वायुमंडल में ऊपर जाते हैं, हवा का दबाव कम होता है और हवा फैलती है, जिससे तापमान कम (प्रति किलोमीटर लगभग 6.5°C) हो जाता है।","explanationEn":"As we go higher in the atmosphere, air pressure decreases and air expands, causing the temperature to drop (approx 6.5°C per kilometer).","memoryTip":"165 मीटर ऊपर जाओ, 1 डिग्री ठंड पाओ।","memoryTipEn":"165 meters makes it 1 degree cooler.","related":["Normal Lapse Rate","Troposphere","Atmospheric Pressure"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('43TY4nBqTp14ZxavmZdai', 'General Science', 'किस ग्रह के चारों ओर वलय (Rings) हैं?', 'Which planet has rings around it?', 'शनि (Saturn)', 'Saturn', 93, 0, '{"facts":["शनि के वलय मुख्य रूप से बर्फ के कणों, चट्टानों और धूल से बने हैं।","बृहस्पति, अरुण (Uranus) और वरुण (Neptune) के भी वलय हैं, लेकिन शनि के वलय सबसे प्रमुख और चमकदार हैं।"],"factsEn":["Saturn''s rings are primarily made of ice particles, rocky debris, and dust.","Jupiter, Uranus, and Neptune also have rings, but Saturn''s are the most prominent and bright."],"explanationHi":"शनि हमारे सौरमंडल का दूसरा सबसे बड़ा ग्रह है और इसका घनत्व (Density) पानी से भी कम है (यह पानी पर तैर सकता है)।","explanationEn":"Saturn is the second largest planet in our solar system and its density is less than water (it could float on water).","memoryTip":"''शनि'' ने छल्ले (रिंग) पहन रखे हैं।","memoryTipEn":"Saturn is the Lord of the Rings.","related":["Gas Giants","Titan (Saturn''s Moon)","Cassini Mission"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9bz8L3nNcWuK46mDhcJS1', 'General Knowledge', 'विश्व में सर्वाधिक शाखाओं (Branches) वाला बैंक कौनसा है?', 'Which bank has the maximum number of branches in the world?', 'भारतीय स्टेट बैंक (SBI)', 'State Bank of India (SBI)', 90, 0, '{"facts":["SBI की भारत और विदेशों में 22,000 से अधिक शाखाएँ हैं।","1955 में इंपीरियल बैंक ऑफ इंडिया का राष्ट्रीयकरण कर इसका नाम SBI रखा गया।"],"factsEn":["SBI has over 22,000 branches in India and abroad.","In 1955, the Imperial Bank of India was nationalized and renamed SBI."],"explanationHi":"यह संपत्ति, जमा और शाखाओं के मामले में भारत का सबसे बड़ा वाणिज्यिक बैंक है।","explanationEn":"It is India''s largest commercial bank in terms of assets, deposits, and branches.","memoryTip":"भारत का ''स्टेट'' बैंक पूरी दुनिया में फैला है।","memoryTipEn":"SBI serves the largest state.","related":["Imperial Bank of India","Nationalization of Banks","Public Sector Banks"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ei4k76ujeG6q9p2k9Oe7p', 'General Knowledge', 'सफेद हाथियों का देश (Land of White Elephants) कौनसा है?', 'Which is the ''Land of White Elephants''?', 'थाईलैंड', 'Thailand', 92, 0, '{"facts":["थाईलैंड दक्षिण पूर्व एशिया का एक देश है जिसकी राजधानी बैंकॉक है।","सफेद हाथी (एल्बिनो हाथी) थाईलैंड में पवित्र और शाही शक्ति के प्रतीक माने जाते हैं।"],"factsEn":["Thailand is a Southeast Asian country whose capital is Bangkok.","White elephants (albino elephants) are considered sacred and symbols of royal power in Thailand."],"explanationHi":"थाई संस्कृति में, खोजे गए सभी सफेद हाथियों को कानूनी रूप से राजा की संपत्ति माना जाता है।","explanationEn":"In Thai culture, all discovered white elephants are legally considered the property of the King.","memoryTip":"सफेद हाथी को ''थाई'' मसाज पसंद है।","memoryTipEn":"Thailand treasures the white tusks.","related":["Bangkok","Albino Animals","Southeast Asia"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kitMTjiZM_Zhdv3uFrGns', 'General Knowledge', 'कंगारू किस देश का राष्ट्रीय चिह्न है?', 'Kangaroo is the national symbol of which country?', 'ऑस्ट्रेलिया', 'Australia', 94, 0, '{"facts":["कंगारू केवल ऑस्ट्रेलिया में प्राकृतिक रूप से पाए जाने वाले मार्सुपियल्स (Marsupials) हैं (जिनके पेट में थैली होती है)।","ऑस्ट्रेलियाई राष्ट्रीय कोट ऑफ आर्म्स (Coat of arms) पर एमु पक्षी के साथ कंगारू बना हुआ है।"],"factsEn":["Kangaroos are marsupials naturally found only in Australia (they have an abdominal pouch).","The Australian national coat of arms features a kangaroo alongside an emu."],"explanationHi":"इन जानवरों को इसलिए चुना गया क्योंकि ये पीछे की ओर नहीं चल सकते, जो एक राष्ट्र के आगे बढ़ने (Moving forward) का प्रतीक है।","explanationEn":"These animals were chosen because they cannot easily move backwards, symbolizing a nation moving forward.","memoryTip":"क्रिकेट में भी ऑस्ट्रेलिया की टीम को ''कंगारू'' कहते हैं।","memoryTipEn":"Kangaroos jump only in Australia.","related":["Marsupials","Emu","Australian Cricket Team"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FUtBi-A855B1LV3at2cbV', 'General Knowledge', 'सुन्दरलाल बहुगुणा का संबंध किस आन्दोलन से है?', 'Sunderlal Bahuguna is associated with which movement?', 'चिपको आन्दोलन (Chipko Movement)', 'Chipko Movement', 96, 0, '{"facts":["यह एक पर्यावरण रक्षा आंदोलन था जो 1973 में उत्तराखंड (तत्कालीन यूपी) के चमोली जिले में शुरू हुआ था।","''चिपको'' का अर्थ पेड़ों को गले लगाना है (Hug the trees)।"],"factsEn":["It was an environmental defense movement started in 1973 in Chamoli district of Uttarakhand (then UP).","''Chipko'' literally means ''to hug'' (hug the trees)."],"explanationHi":"स्थानीय लोगों, विशेषकर महिलाओं ने लकड़हारों से पेड़ों को कटने से बचाने के लिए उन्हें गले लगा लिया था। बहुगुणा ने इस आंदोलन को राष्ट्रीय पहचान दिलाई।","explanationEn":"Locals, especially women, hugged trees to protect them from loggers. Bahuguna brought national recognition to this movement.","memoryTip":"पेड़ों की ''सुंदर''ता बचाने के लिए ''चिपको''।","memoryTipEn":"Bahuguna hugged the beautiful trees.","related":["Environmental Conservation","Uttarakhand","Appiko Movement"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0k-2Nc1NE3v_wgO1sa4gV', 'General Knowledge', 'सन 1923 में स्वराज पार्टी का गठन किसने किया था?', 'Who formed the Swaraj Party in 1923?', 'चितरंजन दास (सी. आर. दास) और मोतीलाल नेहरु', 'Chittaranjan Das (C.R. Das) and Motilal Nehru', 94, 0, '{"facts":["असहयोग आंदोलन को वापस लेने के गांधीजी के फैसले से असंतुष्ट होकर इन्होंने यह पार्टी बनाई।","इस पार्टी का उद्देश्य विधान परिषदों (Legislative Councils) में प्रवेश कर भीतर से ब्रिटिश सरकार का विरोध करना था।"],"factsEn":["They formed this party being dissatisfied with Gandhi''s decision to withdraw the Non-Cooperation Movement.","The party''s objective was to enter the Legislative Councils and oppose the British government from within."],"explanationHi":"सी. आर. दास अध्यक्ष थे और मोतीलाल नेहरू सचिव बने। 1925 में दास की मृत्यु के बाद यह पार्टी कमजोर हो गई।","explanationEn":"C.R. Das was the President and Motilal Nehru the Secretary. The party weakened after Das''s death in 1925.","memoryTip":"23 में ''स्वराज'' के लिए ''दास'' और ''नेहरू'' एक हुए।","memoryTipEn":"Das and Nehru demanded Swaraj from within.","related":["Non-Cooperation Movement","Deshbandhu (C.R. Das)","Indian National Congress"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5LH6Bey_yQqK3M2mVQacb', 'General Knowledge', 'भगतसिंह, सुखदेव, राजगुरु को फांसी कब दी गयी?', 'When were Bhagat Singh, Sukhdev, and Rajguru hanged?', '23 मार्च, 1931', '23 March 1931', 97, 0, '{"facts":["उन्हें लाहौर षडयंत्र केस (जॉन सांडर्स की हत्या) में दोषी ठहराया गया था।","इस दिन को भारत में ''शहीद दिवस'' (Martyrs'' Day) के रूप में याद किया जाता है।"],"factsEn":["They were convicted in the Lahore Conspiracy Case (assassination of John Saunders).","This day is remembered as ''Martyrs'' Day'' in India."],"explanationHi":"फांसी की निर्धारित तारीख 24 मार्च थी, लेकिन जनता के विद्रोह के डर से ब्रिटिश सरकार ने उन्हें एक दिन पहले ही (23 मार्च की शाम) गुपचुप तरीके से फांसी दे दी।","explanationEn":"The scheduled date was March 24, but fearing public revolt, the British government secretly hanged them a day early (evening of March 23).","memoryTip":"23 मार्च को देश के 3 वीर ''शहीद'' हो गए।","memoryTipEn":"March 23 honors the 3 martyrs.","related":["Lahore Conspiracy Case","John Saunders","Shaheed-e-Azam"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PGoesLeIrCZC72jCZNn5I', 'General Knowledge', 'माउन्ट एवरेस्ट पर सबसे पहले कौन चढ़ा?', 'Who were the first to climb Mount Everest?', 'तेनजिंग नोर्गे (भारत/नेपाल) और एडमंड हिलेरी (न्यूजीलैंड)', 'Tenzing Norgay (India/Nepal) and Edmund Hillary (New Zealand)', 95, 0, '{"facts":["उन्होंने 29 मई 1953 को एवरेस्ट के शिखर पर सफलतापूर्वक कदम रखा था।","यह एक ब्रिटिश अभियान था जिसका नेतृत्व जॉन हंट कर रहे थे।"],"factsEn":["They successfully stepped on the summit of Everest on May 29, 1953.","It was a British expedition led by John Hunt."],"explanationHi":"तेनजिंग एक शेरपा (Sherpa) थे जो नेपाल और भारत दोनों से जुड़े थे। उन्होंने मानव क्षमता की सीमाओं को पार कर इतिहास रचा।","explanationEn":"Tenzing was a Sherpa associated with both Nepal and India. They made history by pushing the limits of human capability.","memoryTip":"एवरेस्ट को सबसे पहले ''हिलेरी'' और ''तेनजिंग'' ने हिलाया।","memoryTipEn":"Hillary and Norgay scaled the heights in ''53.","related":["Mount Everest","Sherpa","Bachendri Pal"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('LZdFOqBJEKDpVDp3PMxef', 'General Knowledge', 'पद्मावत (Padmavat) की रचना किसने की?', 'Who wrote ''Padmavat''?', 'मलिक मोहम्मद जायसी', 'Malik Muhammad Jayasi', 94, 0, '{"facts":["यह 1540 ई. में अवधी भाषा में लिखी गई एक सूफी प्रेमाख्यान (Sufi epic) कविता है।","इसमें चित्तौड़ की रानी पद्मिनी (पद्मावती) और दिल्ली के सुल्तान अलाउद्दीन खिलजी की कहानी है।"],"factsEn":["It is a Sufi epic poem written in the Awadhi language in 1540 CE.","It narrates the story of Queen Padmini (Padmavati) of Chittor and the Sultan of Delhi, Alauddin Khalji."],"explanationHi":"यह ऐतिहासिक रोमांस हिंदी साहित्य की सबसे महत्वपूर्ण कृतियों में से एक है।","explanationEn":"This historical romance is one of the most important works of Hindi literature.","memoryTip":"पद्मावती का ''जायका'' (जायसी) ऐसा था कि सुल्तान दीवाना हो गया।","memoryTipEn":"Jayasi penned the poem of Padmavati.","related":["Alauddin Khalji","Rani Padmini","Chittorgarh"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-rc7dWmdIKXaq6z074_vc', 'General Knowledge', 'अमेरिका के पहले राष्ट्रपति कौन थे?', 'Who was the first President of the United States of America?', 'जॉर्ज वाशिंगटन', 'George Washington', 93, 0, '{"facts":["वे 1789 से 1797 तक अमेरिका के राष्ट्रपति रहे।","उन्होंने अमेरिकी क्रांतिकारी युद्ध (American Revolutionary War) में ब्रिटिश सेना के खिलाफ ''महाद्वीपीय सेना'' का नेतृत्व किया था।"],"factsEn":["He served as US President from 1789 to 1797.","He led the ''Continental Army'' against the British in the American Revolutionary War."],"explanationHi":"उन्हें ''संयुक्त राज्य अमेरिका के संस्थापक पिता'' (Founding Father) में से एक माना जाता है और अमेरिकी राजधानी (Washington D.C.) का नाम उन्हीं के नाम पर है।","explanationEn":"He is considered one of the ''Founding Fathers of the USA'', and the American capital (Washington D.C.) is named after him.","memoryTip":"अमेरिका की ''वॉशिंग'' (सफाई) करके वाशिंगटन पहले प्रेसिडेंट बने।","memoryTipEn":"Washington washed away British rule.","related":["American Revolution","Founding Fathers","Abraham Lincoln"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ABTvYy8K-9nL0Nke5iKdx', 'General Knowledge', 'जर्मनी का एकीकरण (Unification of Germany) किसने किया था?', 'Who carried out the Unification of Germany?', 'ओटो वॉन बिस्मार्क', 'Otto von Bismarck', 95, 0, '{"facts":["इन्हें ''लौह चांसलर'' (Iron Chancellor) के नाम से भी जाना जाता है।","इन्होंने ''रक्त और लौह'' (Blood and Iron) की नीति अपनाई थी।"],"factsEn":["He is also known as the ''Iron Chancellor''.","He adopted the policy of ''Blood and Iron''."],"explanationHi":"बिस्मार्क ने अपनी कुशल कूटनीति और मजबूत सेना के बल पर 1871 में अनेक छोटे जर्मन राज्यों को मिलाकर एक मजबूत जर्मन साम्राज्य की स्थापना की। भारत के एकीकरण में सरदार पटेल की भूमिका के कारण उन्हें ''भारत का बिस्मार्क'' कहा जाता है।","explanationEn":"Through shrewd diplomacy and a strong military, Bismarck unified numerous small German states into a powerful German Empire in 1871. Sardar Patel is called the ''Bismarck of India'' for his similar role.","memoryTip":"जर्मनी के सारे ''मार्क'' (निशान) मिटाकर उसे एक किया बिस्मार्क ने।","memoryTipEn":"Bismarck bonded the German states.","related":["Iron Chancellor","Blood and Iron Policy","Sardar Vallabhbhai Patel (Bismarck of India)"]}', 'published', 1776085892, 1776085892);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kqG0BfGlNPNdys_OndYqW', 'General Knowledge', 'भारत के प्रथम उपराष्ट्रपति कौन थे?', 'Who was the first Vice President of India?', 'डॉ. सर्वपल्ली राधाकृष्णन', 'Dr. Sarvepalli Radhakrishnan', 95, 0, '{"facts":["उन्होंने 1952 से 1962 तक भारत के पहले उपराष्ट्रपति के रूप में कार्य किया।","बाद में वे भारत के दूसरे राष्ट्रपति (1962-1967) बने।"],"factsEn":["He served as the first Vice President of India from 1952 to 1962.","He later became the second President of India (1962-1967)."],"explanationHi":"वे एक महान दार्शनिक और शिक्षक थे, जिनके जन्मदिन (5 सितंबर) को भारत में ''शिक्षक दिवस'' के रूप में मनाया जाता है।","explanationEn":"He was a great philosopher and teacher whose birthday (September 5) is celebrated as ''Teachers'' Day'' in India.","memoryTip":"उपराष्ट्रपति की कुर्सी पर सबसे पहले ''राधा-कृष्ण'' (राधाकृष्णन) का नाम आया।","memoryTipEn":"Radhakrishnan radiated knowledge as the first VP.","related":["Teachers'' Day","Dr. Rajendra Prasad","President of India"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4Mas-B31oNsnBqnKFxkC_', 'General Knowledge', 'विश्व का सबसे गहरा गर्त (Trench) कौनसा है?', 'Which is the deepest trench in the world?', 'मारियाना गर्त (Mariana Trench)', 'Mariana Trench', 92, 0, '{"facts":["यह पश्चिमी प्रशांत महासागर में स्थित है।","इसकी अधिकतम गहराई लगभग 11,034 मीटर (चैलेंजर डीप) है।"],"factsEn":["It is located in the western Pacific Ocean.","Its maximum depth is approximately 11,034 meters (Challenger Deep)."],"explanationHi":"यह गर्त इतना गहरा है कि यदि माउंट एवरेस्ट को इसमें डाल दिया जाए, तो उसकी चोटी भी पानी के 2 किलोमीटर नीचे होगी।","explanationEn":"This trench is so deep that if Mount Everest were dropped into it, its peak would still be over 2 kilometers underwater.","memoryTip":"''मारियाना'' की गहराई मापना आसान नहीं है।","memoryTipEn":"Mariana is a massive marine mystery.","related":["Pacific Ocean","Challenger Deep","Mount Everest"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_ZK6cZ5JtlTOE4EWmJwy1', 'General Knowledge', 'भारत की प्रथम महिला प्रधानमंत्री कौन थीं?', 'Who was the first female Prime Minister of India?', 'इंदिरा गाँधी', 'Indira Gandhi', 96, 0, '{"facts":["वे 1966 में पहली बार भारत की प्रधानमंत्री बनीं।","उन्हें 1971 में भारत रत्न से सम्मानित किया गया था।"],"factsEn":["She became the Prime Minister of India for the first time in 1966.","She was awarded the Bharat Ratna in 1971."],"explanationHi":"वे जवाहरलाल नेहरू की बेटी थीं और अपने दृढ़ राजनीतिक निर्णयों (जैसे 1971 का युद्ध और बैंकों का राष्ट्रीयकरण) के लिए ''आयरन लेडी ऑफ इंडिया'' के रूप में जानी जाती हैं।","explanationEn":"She was the daughter of Jawaharlal Nehru and is known as the ''Iron Lady of India'' for her strong political decisions (like the 1971 war and bank nationalization).","memoryTip":"पहली महिला पीएम ने देश में ''इंद्रा'' (इंद्र) के समान राज किया।","memoryTipEn":"Indira introduced iron-willed leadership.","related":["Iron Lady of India","1971 Indo-Pak War","Jawaharlal Nehru"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('h9xix5UU-m3ff45VONx4X', 'General Science', 'हीटर के तार (Coil) किस धातु के बने होते हैं?', 'Heater wires (coils) are made of which metal?', 'नाइक्रोम (Nichrome)', 'Nichrome', 94, 0, '{"facts":["नाइक्रोम, निकेल (Nickel) और क्रोमियम (Chromium) की एक मिश्र धातु (Alloy) है।","इसका गलनांक (Melting point) बहुत उच्च होता है।"],"factsEn":["Nichrome is an alloy of Nickel and Chromium.","It has a very high melting point."],"explanationHi":"उच्च विद्युत प्रतिरोध (High electrical resistance) और उच्च गलनांक के कारण यह बिजली प्रवाहित होने पर बिना पिघले अत्यधिक गर्मी (Heat) पैदा करता है।","explanationEn":"Due to its high electrical resistance and high melting point, it produces excessive heat without melting when an electric current is passed through it.","memoryTip":"हीटर ''नाई'' (Nichrome) की तरह गरमा-गरम हवा देता है।","memoryTipEn":"Nichrome handles the heat.","related":["Electrical Resistance","Alloys","Tungsten (Bulb filament)"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GlWh6pxUS-Z_KES-n2p1J', 'General Science', 'लोहे पर जंग लगने (Rusting) से उसके भार (Weight) पर क्या प्रभाव पड़ता है?', 'How does rusting affect the weight of iron?', 'भार बढ़ जाता है', 'Weight increases', 95, 0, '{"facts":["जंग लगने की प्रक्रिया एक रासायनिक परिवर्तन (Chemical change) है जिसे ऑक्सीकरण (Oxidation) कहते हैं।","जंग का रासायनिक नाम आयरन ऑक्साइड (Iron Oxide) है।"],"factsEn":["Rusting is a chemical change known as oxidation.","The chemical name for rust is Iron Oxide."],"explanationHi":"जब लोहे पर जंग लगता है, तो लोहा हवा की ऑक्सीजन और नमी के साथ मिलकर आयरन ऑक्साइड बनाता है। अतिरिक्त ऑक्सीजन के जुड़ने से उसका कुल वजन बढ़ जाता है।","explanationEn":"When iron rusts, it reacts with oxygen and moisture in the air to form iron oxide. The addition of oxygen atoms increases its total weight.","memoryTip":"जंग लगने पर लोहे ने ''ऑक्सीजन'' का ''भार'' भी उठा लिया।","memoryTipEn":"Rust adds oxygen, adding weight.","related":["Oxidation","Iron Oxide","Galvanization"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Q0U8E4flIEuPiRwXYepTp', 'General Knowledge', 'विश्व का सबसे बड़ा नदी द्वीप ''माजुली'' भारत के किस राज्य में स्थित है?', 'In which Indian state is ''Majuli'', the world''s largest river island, located?', 'असम (Assam)', 'Assam', 91, 0, '{"facts":["माजुली द्वीप ब्रह्मपुत्र नदी के मध्य में स्थित है।","2016 में यह भारत का पहला ऐसा द्वीप बना जिसे एक पूर्ण जिला (District) घोषित किया गया।"],"factsEn":["Majuli island is situated in the middle of the Brahmaputra River.","In 2016, it became the first island in India to be made a full-fledged district."],"explanationHi":"यह अपनी समृद्ध असमिया नव-वैष्णव (Neo-Vaishnavite) संस्कृति और प्राकृतिक सुंदरता के लिए प्रसिद्ध है, लेकिन वर्तमान में कटाव (Erosion) के कारण सिकुड़ रहा है।","explanationEn":"It is famous for its rich Assamese Neo-Vaishnavite culture and scenic beauty, but is currently shrinking due to severe soil erosion.","memoryTip":"ब्रह्मपुत्र के पानी में ''माजुली'' (मजे ले) द्वीप।","memoryTipEn":"Majuli makes its mark in the Brahmaputra.","related":["Brahmaputra River","River Island","Assam"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('o5Kl3k956hxxoF2mLCDWA', 'General Science', 'ध्वनि की चाल (Speed of Sound) अधिकतम किस माध्यम में होती है?', 'In which medium is the speed of sound maximum?', 'ठोस में (जैसे स्टील)', 'In solids (like Steel)', 94, 0, '{"facts":["ध्वनि को यात्रा करने के लिए एक भौतिक माध्यम की आवश्यकता होती है (यह निर्वात में यात्रा नहीं कर सकती)।","हवा में ध्वनि की गति लगभग 343 मीटर प्रति सेकंड है, जबकि स्टील में यह लगभग 5,960 मीटर प्रति सेकंड होती है।"],"factsEn":["Sound requires a material medium to travel (it cannot travel in a vacuum).","The speed of sound in air is approx 343 m/s, whereas in steel it is about 5,960 m/s."],"explanationHi":"ठोस पदार्थों में अणु एक-दूसरे के बहुत करीब होते हैं, इसलिए कंपन (vibrations) गैसों या तरल पदार्थों की तुलना में बहुत तेजी से एक कण से दूसरे कण में स्थानांतरित होते हैं।","explanationEn":"In solids, molecules are packed very closely together, so vibrations transfer from one particle to another much faster than in gases or liquids.","memoryTip":"ट्रेन की आवाज़ हवा से पहले पटरियों (ठोस स्टील) में सुनाई देती है।","memoryTipEn":"Sound speeds through solid steel.","related":["Vacuum (No sound)","Acoustics","Mechanical Waves"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4VNM_7nWqNk_rlpnpKbZ0', 'General Knowledge', 'प्लासी का युद्ध (Battle of Plassey) कब लड़ा गया था?', 'When was the Battle of Plassey fought?', '1757 ई.', '1757 AD', 96, 0, '{"facts":["यह युद्ध रॉबर्ट क्लाइव (British East India Company) और बंगाल के नवाब सिराजुद्दौला के बीच हुआ था।","मीर जाफर के विश्वासघात के कारण नवाब की हार हुई थी।"],"factsEn":["The battle was fought between Robert Clive (British EIC) and Siraj-ud-Daulah, the Nawab of Bengal.","The Nawab lost due to the betrayal of Mir Jafar."],"explanationHi":"इस युद्ध ने भारत में ब्रिटिश साम्राज्य की नींव रखी और अंग्रेजों को बंगाल का नियंत्रण सौंप दिया।","explanationEn":"This battle laid the foundation of the British Empire in India and handed over the control of Bengal to the British.","memoryTip":"57 के विद्रोह (1857) से ठीक 100 साल पहले प्लासी (1757) हुआ था।","memoryTipEn":"Plassey paved the path in 1757.","related":["Battle of Buxar (1764)","Siraj-ud-Daulah","Robert Clive"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1ShiwpS1SxWv5mHPluMZi', 'General Knowledge', 'भारत का प्रथम वायसराय (Viceroy) कौन था?', 'Who was the first Viceroy of India?', 'लॉर्ड कैनिंग', 'Lord Canning', 95, 0, '{"facts":["वे 1857 के विद्रोह के समय भारत के गवर्नर-जनरल भी थे।","गवर्नमेंट ऑफ इंडिया एक्ट 1858 के तहत उन्हें पहला ''वायसराय'' बनाया गया।"],"factsEn":["He was also the Governor-General of India during the 1857 revolt.","He was made the first ''Viceroy'' under the Government of India Act 1858."],"explanationHi":"1857 की क्रांति के बाद ईस्ट इंडिया कंपनी का शासन खत्म हो गया और भारत सीधे ब्रिटिश ताज (Crown) के अधीन आ गया, जिसके प्रतिनिधि को ''वायसराय'' कहा गया।","explanationEn":"After the 1857 revolt, EIC''s rule ended and India came directly under the British Crown, whose representative was called the ''Viceroy''.","memoryTip":"क्रांति के ''कैन'' (तूफान) को ''कैनिंग'' ने ही झेला और पहला वायसराय बना।","memoryTipEn":"Canning carried the Crown''s rule.","related":["Revolt of 1857","Government of India Act 1858","Lord Mountbatten (Last Viceroy)"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Rx8270iSzyK_9Xo0Qq55t', 'General Knowledge', 'स्वतंत्र भारत के प्रथम गवर्नर जनरल कौन थे?', 'Who was the first Governor-General of independent India?', 'लॉर्ड माउंटबेटन', 'Lord Mountbatten', 94, 0, '{"facts":["वे भारत के अंतिम ब्रिटिश वायसराय भी थे।","यदि ''प्रथम भारतीय'' गवर्नर जनरल पूछा जाए, तो उत्तर सी. राजगोपालाचारी होगा।"],"factsEn":["He was also the last British Viceroy of India.","If asked for the ''first Indian'' Governor-General, the answer would be C. Rajagopalachari."],"explanationHi":"15 अगस्त 1947 को भारत के आज़ाद होने पर नेहरू जी के अनुरोध पर माउंटबेटन ने कुछ समय तक स्वतंत्र भारत के पहले गवर्नर जनरल के रूप में कार्य किया।","explanationEn":"Upon India''s independence on Aug 15, 1947, at Nehru''s request, Mountbatten served as the first Governor-General of independent India for some time.","memoryTip":"भारत को आज़ादी देकर भी ''माउंट'' पर बैठे रहे माउंटबेटन।","memoryTipEn":"Mountbatten managed the transition.","related":["C. Rajagopalachari","Mountbatten Plan","Indian Independence Act 1947"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CEch0rDLgiNIB_WMCrWSK', 'General Knowledge', 'प्रार्थना समाज (Prarthana Samaj) की स्थापना किसने की थी?', 'Who founded the Prarthana Samaj?', 'आत्माराम पांडुरंग', 'Atmaram Pandurang', 91, 0, '{"facts":["इसकी स्थापना 1867 में बॉम्बे (मुंबई) में हुई थी।","बाद में प्रसिद्ध समाज सुधारक एम. जी. रानाडे भी इससे जुड़े, जिससे यह बहुत लोकप्रिय हुआ।"],"factsEn":["It was founded in 1867 in Bombay (Mumbai).","Later, famous social reformer M. G. Ranade joined it, making it very popular."],"explanationHi":"प्रार्थना समाज का मुख्य उद्देश्य जाति व्यवस्था का विरोध करना, विधवा विवाह को बढ़ावा देना और महिला शिक्षा का समर्थन करना था।","explanationEn":"The main objective of Prarthana Samaj was to oppose the caste system, promote widow remarriage, and support women''s education.","memoryTip":"''आत्मा'' से ''प्रार्थना'' करो (आत्माराम = प्रार्थना समाज)।","memoryTipEn":"Atmaram advocated prayers and reform.","related":["M. G. Ranade","Brahmo Samaj","Social Reforms in India"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GVyZUkOvlNFS9_b00721v', 'General Knowledge', 'थियोसोफिकल सोसाइटी (Theosophical Society) की स्थापना किसने की थी?', 'Who founded the Theosophical Society?', 'मैडम एच.पी. ब्लवात्स्की और कर्नल एच.एस. ओल्कॉट', 'Madam H.P. Blavatsky and Col. H.S. Olcott', 88, 0, '{"facts":["इसकी स्थापना 1875 में न्यूयॉर्क, अमेरिका में की गई थी।","1882 में इसका अंतर्राष्ट्रीय मुख्यालय भारत के ''अड्यार'' (मद्रास/चेन्नई के पास) में स्थानांतरित कर दिया गया।"],"factsEn":["It was founded in 1875 in New York, USA.","In 1882, its international headquarters was moved to ''Adyar'' (near Madras/Chennai) in India."],"explanationHi":"इस संस्था ने भारतीय दर्शन (विशेषकर उपनिषदों) का अध्ययन किया और एनी बेसेंट के नेतृत्व में भारत में बहुत लोकप्रियता हासिल की।","explanationEn":"This organization studied Indian philosophy (especially Upanishads) and gained immense popularity in India under the leadership of Annie Besant.","memoryTip":"थियोसोफी की शुरुआत अमेरिका में हुई, पर भारत में चमकी।","memoryTipEn":"Blavatsky and Olcott brought Theosophy to life.","related":["Annie Besant","Adyar","Central Hindu College (BHU)"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('W_2YNFr1N953tevtvnSb3', 'General Knowledge', 'लोकसभा के सदस्य का कार्यकाल कितने वर्ष का होता है?', 'What is the term (tenure) of a member of the Lok Sabha?', '5 वर्ष', '5 Years', 95, 0, '{"facts":["लोकसभा संसद का ''निचला सदन'' (Lower House) है।","आपातकाल (Emergency) के दौरान लोकसभा के कार्यकाल को कानून द्वारा एक वर्ष के लिए बढ़ाया जा सकता है।"],"factsEn":["Lok Sabha is the ''Lower House'' of the Parliament.","During an Emergency, the term of the Lok Sabha can be extended by law for one year at a time."],"explanationHi":"हालाँकि कार्यकाल 5 वर्ष है, लेकिन प्रधानमंत्री की सलाह पर राष्ट्रपति इसे 5 वर्ष से पहले भी भंग (Dissolve) कर सकते हैं।","explanationEn":"Although the term is 5 years, the President can dissolve it even before 5 years on the advice of the Prime Minister.","memoryTip":"जनता का राज (लोकसभा) हर 5 साल में चुना जाता है।","memoryTipEn":"Lok Sabha lasts five.","related":["Rajya Sabha (6 years)","Parliament of India","Dissolution of Lok Sabha"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2Qw5hh7ZFzw6FJrEhNPeT', 'General Science', 'मानव शरीर की सबसे छोटी ग्रंथि (Gland) कौनसी है?', 'Which is the smallest gland in the human body?', 'पीनियल ग्रंथि (Pineal Gland)', 'Pineal Gland', 91, 0, '{"facts":["यह मस्तिष्क के केंद्र में स्थित होती है।","यह ''मेलाटोनिन'' (Melatonin) हार्मोन स्रावित करती है जो हमारे सोने-जागने के चक्र (Sleep-wake cycle) को नियंत्रित करता है।"],"factsEn":["It is located deep in the center of the brain.","It secretes the ''Melatonin'' hormone which regulates our sleep-wake cycle."],"explanationHi":"नोट: कई बार पुराने विकल्पों में पीयूष ग्रंथि (Pituitary Gland) को सबसे छोटी मान लिया जाता है, लेकिन जैविक रूप से पीनियल सबसे छोटी (चावल के दाने के आकार की) होती है। पीयूष को ''मास्टर ग्रंथि'' कहते हैं।","explanationEn":"Note: Sometimes older options consider the Pituitary as the smallest, but biologically the Pineal (rice-grain sized) is the smallest. The Pituitary is the ''Master Gland''.","memoryTip":"''पिन'' (Pin) के बराबर होती है पीनियल ग्रंथि।","memoryTipEn":"Pineal is as small as a pin.","related":["Melatonin","Pituitary Gland","Endocrine System"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oeFiEcBvOkO45jSxvmFzR', 'General Knowledge', 'कारगिल युद्ध (Kargil War) किस वर्ष हुआ था?', 'In which year did the Kargil War take place?', '1999', '1999', 96, 0, '{"facts":["यह युद्ध भारत और पाकिस्तान के बीच जम्मू-कश्मीर के कारगिल जिले में लड़ा गया था।","भारतीय सेना के सफल अभियान को ''ऑपरेशन विजय'' (Operation Vijay) नाम दिया गया था।"],"factsEn":["This war was fought between India and Pakistan in the Kargil district of Jammu and Kashmir.","The successful operation by the Indian Army was named ''Operation Vijay''."],"explanationHi":"यह संघर्ष मई से जुलाई 1999 के बीच हुआ, जब पाकिस्तानी घुसपैठियों ने भारतीय चोटियों पर कब्ज़ा कर लिया था। 26 जुलाई को ''कारगिल विजय दिवस'' मनाया जाता है।","explanationEn":"The conflict occurred between May and July 1999 when Pakistani intruders occupied Indian peaks. July 26 is celebrated as ''Kargil Vijay Diwas''.","memoryTip":"99 के फेर में पाकिस्तान ने कारगिल में हार खाई।","memoryTipEn":"Kargil conflict climaxed in ''99.","related":["Operation Vijay","Kargil Vijay Diwas","Line of Control (LoC)"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZscPFm2I_wHQGCPzqo--4', 'General Knowledge', 'नीली क्रांति (Blue Revolution) का संबंध किस क्षेत्र से है?', 'The Blue Revolution is associated with which sector?', 'मत्स्य पालन (मछली उत्पादन)', 'Fisheries (Fish Production)', 93, 0, '{"facts":["भारत में नीली क्रांति की शुरुआत 7वीं पंचवर्षीय योजना (1985-1990) के दौरान हुई थी।","डॉ. हीरालाल चौधरी और डॉ. अरुण कृष्णन को इसका जनक माना जाता है।"],"factsEn":["The Blue Revolution in India started during the 7th Five-Year Plan (1985-1990).","Dr. Hiralal Chaudhuri and Dr. Arun Krishnan are considered its fathers."],"explanationHi":"इसका उद्देश्य आधुनिक तकनीकों का उपयोग करके समुद्री और अंतर्देशीय मछली उत्पादन को भारी मात्रा में बढ़ाना था।","explanationEn":"Its objective was to massively increase marine and inland fish production using modern technologies.","memoryTip":"पानी ''नीला'' होता है, और मछलियां पानी में रहती हैं।","memoryTipEn":"Blue relates to the deep sea and fish.","related":["White Revolution (Milk)","Green Revolution (Agriculture)","Aquaculture"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('cgrsFtHBzUl8ZuVLMLiX3', 'General Knowledge', 'भारत में हरित क्रांति (Green Revolution) के जनक कौन माने जाते हैं?', 'Who is considered the father of the Green Revolution in India?', 'एम. एस. स्वामीनाथन', 'M. S. Swaminathan', 97, 0, '{"facts":["भारत में हरित क्रांति की शुरुआत 1960 के दशक (मुख्यतः 1965-68) में हुई थी।","विश्व स्तर पर हरित क्रांति का जनक ''नॉर्मन बोरलॉग'' (Norman Borlaug) को माना जाता है।"],"factsEn":["The Green Revolution in India started in the 1960s (mainly 1965-68).","Globally, ''Norman Borlaug'' is considered the father of the Green Revolution."],"explanationHi":"इस क्रांति ने उच्च उपज वाले बीजों (HYV), उर्वरकों और सिंचाई का उपयोग करके भारत को खाद्यान्न (विशेषकर गेहूं और चावल) में आत्मनिर्भर बनाया।","explanationEn":"This revolution made India self-sufficient in food grains (especially wheat and rice) by using High Yielding Variety (HYV) seeds, fertilizers, and irrigation.","memoryTip":"खेतों का ''स्वामी'' (स्वामीनाथन) जिसने भारत को भूख से बचाया।","memoryTipEn":"Swaminathan sowed the seeds of plenty.","related":["Norman Borlaug","High Yielding Variety (HYV)","White Revolution"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_i6epuAbk7IGp0SpboO5Z', 'General Knowledge', 'प्रसिद्ध पुस्तक ''विंग्स ऑफ फायर'' (Wings of Fire) के लेखक कौन हैं?', 'Who is the author of the famous book ''Wings of Fire''?', 'डॉ. ए.पी.जे. अब्दुल कलाम', 'Dr. A.P.J. Abdul Kalam', 94, 0, '{"facts":["यह भारत के पूर्व राष्ट्रपति और ''मिसाइल मैन'' डॉ. कलाम की आत्मकथा (Autobiography) है।","इस पुस्तक को उन्होंने अरुण तिवारी के साथ मिलकर लिखा है।"],"factsEn":["This is the autobiography of former Indian President and ''Missile Man'' Dr. Kalam.","He co-authored this book with Arun Tiwari."],"explanationHi":"इस पुस्तक में रामेश्वरम के एक साधारण लड़के से लेकर भारत के शीर्ष वैज्ञानिक और राष्ट्रपति बनने तक की उनकी प्रेरणादायक यात्रा का वर्णन है।","explanationEn":"The book describes his inspiring journey from being an ordinary boy in Rameswaram to becoming India''s top scientist and President.","memoryTip":"कलाम जी की मिसाइलें ''आग के पंख'' (Wings of Fire) लगाकर उड़ती थीं।","memoryTipEn":"Kalam gave wings to India''s missiles.","related":["Missile Man of India","Ignited Minds","ISRO/DRDO"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('toqRfGFnKHJQHBOp8jgIb', 'General Knowledge', 'भारत के पहले मुख्य चुनाव आयुक्त (Chief Election Commissioner) कौन थे?', 'Who was the first Chief Election Commissioner of India?', 'सुकुमार सेन', 'Sukumar Sen', 92, 0, '{"facts":["उन्होंने 1950 से 1958 तक इस पद पर कार्य किया।","भारत का चुनाव आयोग (Election Commission) 25 जनवरी 1950 को स्थापित हुआ था।"],"factsEn":["He served in this position from 1950 to 1958.","The Election Commission of India was established on Jan 25, 1950."],"explanationHi":"सुकुमार सेन ने स्वतंत्र भारत के पहले दो आम चुनावों (1951-52 और 1957) का सफलतापूर्वक आयोजन कराया था, जो एक बहुत बड़ी चुनौती थी।","explanationEn":"Sukumar Sen successfully organized independent India''s first two general elections (1951-52 and 1957), which was a monumental challenge.","memoryTip":"चुनाव का काम ''सुकुमार'' (सरलता) से संपन्न कराया।","memoryTipEn":"Sukumar smoothed the voting process.","related":["Election Commission of India","National Voters'' Day (Jan 25)","First General Election"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Ybko1CG7UmigD3ax-BiJh', 'General Knowledge', 'नीति आयोग (NITI Aayog) की स्थापना किस वर्ष हुई थी?', 'In which year was the NITI Aayog established?', '2015', '2015', 95, 0, '{"facts":["इसकी स्थापना 1 जनवरी 2015 को हुई थी।","NITI का पूर्ण रूप ''National Institution for Transforming India'' है।"],"factsEn":["It was established on January 1, 2015.","NITI stands for ''National Institution for Transforming India''."],"explanationHi":"इसने भारत के 65 साल पुराने ''योजना आयोग'' (Planning Commission) का स्थान लिया है और यह सरकार के थिंक टैंक (Think Tank) के रूप में काम करता है।","explanationEn":"It replaced India''s 65-year-old ''Planning Commission'' and serves as the primary policy ''Think Tank'' of the Government of India.","memoryTip":"2015 में नई सरकार ने नई ''नीति'' बनाई।","memoryTipEn":"NITI planned the future in 2015.","related":["Planning Commission","Think Tank","Prime Minister (Chairman)"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qxkBoUsipKj1Y29DhS-kW', 'General Knowledge', 'भारत में पंचायती राज व्यवस्था सबसे पहले किस राज्य में लागू की गई थी?', 'In which state was the Panchayati Raj system first implemented in India?', 'राजस्थान (नागौर जिला)', 'Rajasthan (Nagaur district)', 96, 0, '{"facts":["यह 2 अक्टूबर 1959 को लागू की गई थी (गांधी जयंती के दिन)।","इसका उद्घाटन तत्कालीन प्रधानमंत्री जवाहरलाल नेहरू ने किया था।"],"factsEn":["It was implemented on October 2, 1959 (on Gandhi Jayanti).","It was inaugurated by the then Prime Minister Jawaharlal Nehru."],"explanationHi":"यह व्यवस्था बलवंत राय मेहता समिति की सिफारिशों (त्रि-स्तरीय पंचायत) पर आधारित थी। राजस्थान के बाद इसे आंध्र प्रदेश में लागू किया गया।","explanationEn":"This system was based on the recommendations of the Balwant Rai Mehta Committee (3-tier panchayat). After Rajasthan, it was implemented in Andhra Pradesh.","memoryTip":"पंचों का ''राज'' सबसे पहले ''राज''स्थान में आया।","memoryTipEn":"Rajasthan ruled the rural reforms.","related":["Balwant Rai Mehta Committee","73rd Amendment","Local Self-Government"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8Wcq5o07zvxluaa1n5mO5', 'General Knowledge', 'संविधान के किस अनुच्छेद में ''अस्पृश्यता का अंत'' (Abolition of Untouchability) किया गया है?', 'Which article of the Constitution deals with the ''Abolition of Untouchability''?', 'अनुच्छेद 17', 'Article 17', 97, 0, '{"facts":["यह भारतीय संविधान के भाग III (मौलिक अधिकार) के तहत ''समानता के अधिकार'' (Right to Equality) का हिस्सा है।","अस्पृश्यता का किसी भी रूप में आचरण करना एक दंडनीय अपराध है।"],"factsEn":["It is a part of the ''Right to Equality'' under Part III (Fundamental Rights) of the Indian Constitution.","The practice of untouchability in any form is a punishable offence."],"explanationHi":"यह अनुच्छेद भारतीय समाज की एक पुरानी कुप्रथा (छुआछूत) को कानूनी रूप से समाप्त करता है और मानव गरिमा सुनिश्चित करता है।","explanationEn":"This article legally abolishes the age-old evil practice of untouchability in Indian society and ensures human dignity.","memoryTip":"17 पर खतरा (अस्पृश्यता का खात्मा)।","memoryTipEn":"Article 17 ended the untouchable sin.","related":["Fundamental Rights","Right to Equality","Civil Rights Act 1955"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8jq-dlSJVHSm7c0lv87dV', 'General Knowledge', 'भारतीय संविधान में ''मूल अधिकार'' (Fundamental Rights) किस देश के संविधान से लिए गए हैं?', 'From which country''s constitution were the ''Fundamental Rights'' borrowed in the Indian Constitution?', 'संयुक्त राज्य अमेरिका (USA)', 'United States of America (USA)', 96, 0, '{"facts":["अमेरिकी संविधान में इन्हें ''बिल ऑफ राइट्स'' (Bill of Rights) कहा जाता है।","ये भारतीय संविधान के भाग III (अनुच्छेद 12 से 35) में वर्णित हैं।"],"factsEn":["In the US Constitution, they are referred to as the ''Bill of Rights''.","They are enshrined in Part III (Articles 12 to 35) of the Indian Constitution."],"explanationHi":"मूल अधिकार नागरिकों को राज्य के कठोर नियमों से बचाते हैं और उनके सर्वांगीण विकास के लिए आवश्यक हैं। इन्हें अदालतों द्वारा लागू (Justiciable) कराया जा सकता है।","explanationEn":"Fundamental rights protect citizens from harsh state rules and are essential for their overall development. They are justiciable by the courts.","memoryTip":"अधिकार (Rights) सबसे ''अमीर'' देश (अमेरिका) से लिए गए।","memoryTipEn":"Rights arose from the American constitution.","related":["Bill of Rights","Part III of Constitution","Fundamental Duties (USSR)"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jzKP50P3XGI-hatfR6rQR', 'General Knowledge', 'भारतीय संविधान में ''राज्य के नीति निर्देशक तत्व'' (Directive Principles) किस देश से लिए गए हैं?', 'From which country were the ''Directive Principles of State Policy'' borrowed in the Indian Constitution?', 'आयरलैंड', 'Ireland', 95, 0, '{"facts":["ये संविधान के भाग IV (अनुच्छेद 36 से 51) में वर्णित हैं।","ये तत्व अदालतों द्वारा प्रवर्तनीय (Non-justiciable) नहीं हैं।"],"factsEn":["These are enshrined in Part IV (Articles 36 to 51) of the Constitution.","These principles are non-justiciable by the courts."],"explanationHi":"इनका उद्देश्य देश में एक ''कल्याणकारी राज्य'' (Welfare State) की स्थापना करना और सरकार को नीतियां बनाते समय मार्गदर्शन देना है।","explanationEn":"Their objective is to establish a ''Welfare State'' in the country and provide guidance to the government while formulating policies.","memoryTip":"नीति हमेशा ''आयरन'' (आयरलैंड) की तरह मजबूत होनी चाहिए।","memoryTipEn":"Ireland inspired the Directives.","related":["Part IV of Constitution","Welfare State","Fundamental Rights"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DKwbPXq3PJMQG9NpIIGlc', 'General Knowledge', 'भारत का सबसे दक्षिणी बिंदु (Southernmost point) कौनसा है?', 'Which is the southernmost point of India?', 'इंदिरा पॉइंट (Indira Point)', 'Indira Point', 94, 0, '{"facts":["यह अंडमान और निकोबार द्वीप समूह (ग्रेट निकोबार द्वीप) में स्थित है।","इसे पहले ''पिग्मेलियन पॉइंट'' (Pygmalion Point) कहा जाता था।"],"factsEn":["It is located in the Andaman and Nicobar Islands (Great Nicobar Island).","It was formerly known as ''Pygmalion Point''."],"explanationHi":"2004 की भयंकर सूनामी के दौरान इंदिरा पॉइंट का एक बड़ा हिस्सा समुद्र में डूब गया था। यदि ''मुख्य भूमि'' (Mainland) का दक्षिणी बिंदु पूछा जाए, तो वह कन्याकुमारी है।","explanationEn":"A large part of Indira Point was submerged during the catastrophic 2004 Tsunami. If asked for the southernmost point of the ''mainland'', it is Kanyakumari.","memoryTip":"भारत का नक्शा ''इंदिरा'' (कॉल) से शुरू होकर ''इंदिरा'' (पॉइंट) पर खत्म होता है।","memoryTipEn":"Indira Point dips into the ocean.","related":["Indira Col (Northernmost point)","Kanyakumari","Great Nicobar"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aJH90Z3Qd52Of93bGIobY', 'General Knowledge', 'डूरंड रेखा (Durand Line) किन दो देशों के बीच की सीमा रेखा है?', 'The Durand Line is the boundary line between which two countries?', 'पाकिस्तान और अफगानिस्तान', 'Pakistan and Afghanistan', 91, 0, '{"facts":["इस रेखा का निर्धारण 1893 में ब्रिटिश अधिकारी मोर्टिमर डूरंड और अफगान अमीर अब्दुर रहमान खान के बीच हुआ था।","मूल रूप से यह ब्रिटिश भारत और अफगानिस्तान के बीच की सीमा थी।"],"factsEn":["This line was established in 1893 between British official Mortimer Durand and Afghan Amir Abdur Rahman Khan.","Originally, it was the border between British India and Afghanistan."],"explanationHi":"1947 में विभाजन के बाद, इसका अधिकांश हिस्सा पाकिस्तान और अफगानिस्तान के बीच की सीमा बन गया (हालाँकि POK के जरिए भारत का एक छोटा हिस्सा भी अफगानिस्तान को छूता है)।","explanationEn":"After partition in 1947, most of it became the border between Pakistan and Afghanistan (though a small part of India via POK still touches Afghanistan).","memoryTip":"अफगानों को ''दूर'' (डूरंड) रखने के लिए अंग्रेजों ने लाइन खींची।","memoryTipEn":"Durand divides the Afghan lands.","related":["Radcliffe Line (India-Pak)","McMahon Line (India-China)","Mortimer Durand"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dQxgIT8Kg0I4VovQCtJ8_', 'General Knowledge', 'कर्क रेखा (Tropic of Cancer) भारत के कितने राज्यों से होकर गुजरती है?', 'The Tropic of Cancer passes through how many states of India?', '8 (आठ)', '8 (Eight)', 95, 0, '{"facts":["ये राज्य हैं: गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा और मिजोरम।","यह 23.5 डिग्री उत्तरी अक्षांश रेखा है।"],"factsEn":["These states are: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram.","It is the 23.5 degrees North latitude line."],"explanationHi":"यह काल्पनिक रेखा भारत को लगभग दो समान जलवायु क्षेत्रों में विभाजित करती है: उष्णाकटिबंधीय (Tropical) और उपोष्णकटिबंधीय (Sub-tropical)।","explanationEn":"This imaginary line divides India into almost two equal climatic zones: Tropical and Sub-tropical.","memoryTip":"''मित्र पर गमछा झार'' (Mizoram, Tripura, W.Bengal, Rajasthan, Gujarat, MP, Chhattisgarh, Jharkhand)।","memoryTipEn":"Eight states divide the nation''s climate.","related":["Equator","Tropic of Capricorn","Indian Standard Meridian"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mhi4EnFjIlBGFMOXnJc3W', 'General Knowledge', 'विश्व की सबसे गहरी झील कौनसी है?', 'Which is the deepest lake in the world?', 'बैकाल झील (Lake Baikal)', 'Lake Baikal', 90, 0, '{"facts":["यह रूस (साइबेरिया) में स्थित है।","यह मात्रा (Volume) के हिसाब से दुनिया की सबसे बड़ी मीठे पानी की झील भी है।"],"factsEn":["It is located in Russia (Siberia).","It is also the world''s largest freshwater lake by volume."],"explanationHi":"बैकाल झील इतनी विशाल है कि इसमें दुनिया का लगभग 20% बिना जमा हुआ मीठा पानी (Freshwater) मौजूद है।","explanationEn":"Lake Baikal is so massive that it contains roughly 20% of the world''s unfrozen freshwater.","memoryTip":"रूस के पास पानी का सबसे गहरा ''काल'' (बैकाल) है।","memoryTipEn":"Baikal is the deepest basin.","related":["Lake Superior (Largest by surface area)","Caspian Sea","Siberia"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('miDffS50NTZc6BIp5vAKG', 'General Knowledge', 'प्रथम विश्व युद्ध (First World War) किस वर्ष शुरू हुआ था?', 'In which year did the First World War begin?', '1914', '1914', 93, 0, '{"facts":["यह युद्ध 1914 से 1918 तक चला।","इसकी शुरुआत ऑस्ट्रिया के आर्कड्यूक फ्रांज फर्डिनेंड की हत्या के कारण हुई थी।"],"factsEn":["The war lasted from 1914 to 1918.","It was triggered by the assassination of Archduke Franz Ferdinand of Austria."],"explanationHi":"यह युद्ध ''मित्र राष्ट्रों'' (Allied Powers - जैसे ब्रिटेन, फ्रांस, रूस) और ''केंद्रीय शक्तियों'' (Central Powers - जर्मनी, ऑस्ट्रिया-हंगरी) के बीच लड़ा गया था।","explanationEn":"The war was fought between the ''Allied Powers'' (e.g., Britain, France, Russia) and the ''Central Powers'' (Germany, Austria-Hungary).","memoryTip":"14 में शुरू हुआ और 18 में खत्म (1914-1918)।","memoryTipEn":"World War I fired up in ''14.","related":["Treaty of Versailles","Second World War (1939)","Archduke Franz Ferdinand"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('olXYXU_QjI3ZEJeDwdjeJ', 'General Knowledge', '''सारे जहाँ से अच्छा हिन्दोस्तां हमारा'' गीत के रचयिता कौन हैं?', 'Who is the creator of the song ''Sare Jahan se Accha Hindustan Hamara''?', 'अल्लामा इकबाल', 'Allama Iqbal', 94, 0, '{"facts":["यह गीत 1904 में पहली बार प्रकाशित हुआ था।","इसे ''तराना-ए-हिंदी'' (Anthem of the People of Hindustan) के नाम से भी जाना जाता है।"],"factsEn":["This song was first published in 1904.","It is also known as ''Tarana-e-Hindi'' (Anthem of the People of Hindustan)."],"explanationHi":"शुरुआत में यह गीत भारत की एकता का प्रतीक था, हालाँकि बाद में इकबाल ने मुसलमानों के लिए एक अलग राष्ट्र (पाकिस्तान) के विचार का समर्थन किया।","explanationEn":"Initially, the song was a symbol of Indian unity, though later Iqbal supported the idea of a separate nation (Pakistan) for Muslims.","memoryTip":"''इकबाल'' ने बुलंद किया हिन्दोस्तां का नाम।","memoryTipEn":"Iqbal penned the patriotic poem.","related":["National Song (Vande Mataram)","Rabindranath Tagore","Patriotic Songs"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mFIiFXvFXFsZkydGdun_3', 'General Science', 'इलेक्ट्रॉन (Electron) की खोज किसने की थी?', 'Who discovered the Electron?', 'जे. जे. थॉमसन', 'J. J. Thomson', 95, 0, '{"facts":["थॉमसन ने 1897 में कैथोड रे ट्यूब (Cathode Ray Tube) प्रयोगों के माध्यम से इसकी खोज की।","इस खोज के लिए उन्हें 1906 में भौतिकी का नोबेल पुरस्कार मिला।"],"factsEn":["Thomson discovered it in 1897 through Cathode Ray Tube experiments.","He received the Nobel Prize in Physics in 1906 for this discovery."],"explanationHi":"इलेक्ट्रॉन एक उप-परमाणु कण (Subatomic particle) है जिस पर ऋणात्मक (Negative) विद्युत आवेश होता है और यह नाभिक के चारों ओर चक्कर लगाता है।","explanationEn":"An electron is a subatomic particle with a negative electrical charge that orbits around the nucleus.","memoryTip":"ईंट पर नाच (E=Electron T=Thomson, P=Proton R=Rutherford, N=Neutron Ch=Chadwick)।","memoryTipEn":"Thomson tracked the negative charge.","related":["Proton (Rutherford)","Neutron (Chadwick)","Cathode Rays"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('je1PBUlgF9wovRMOZ1NE-', 'General Knowledge', 'भारत का सबसे बड़ा नागरिक सम्मान (Highest Civilian Award) कौनसा है?', 'Which is the Highest Civilian Award of India?', 'भारत रत्न', 'Bharat Ratna', 96, 0, '{"facts":["इसकी शुरुआत 1954 में की गई थी।","यह पुरस्कार कला, साहित्य, विज्ञान और सार्वजनिक सेवा में असाधारण योगदान के लिए दिया जाता है (अब किसी भी क्षेत्र में)।"],"factsEn":["It was instituted in 1954.","It is awarded for exceptional contribution in art, literature, science, and public service (now in any field of human endeavor)."],"explanationHi":"यह पदक पीपल के पत्ते के आकार का होता है। खान अब्दुल गफ्फार खान और नेल्सन मंडेला ऐसे दो गैर-भारतीय हैं जिन्हें यह सम्मान मिला है।","explanationEn":"The medal is shaped like a Peepal leaf. Khan Abdul Ghaffar Khan and Nelson Mandela are the two non-Indians who have received this honor.","memoryTip":"देश का सबसे अनमोल ''रत्न'' = भारत रत्न।","memoryTipEn":"Bharat Ratna is the Jewel of India.","related":["Padma Vibhushan","C. V. Raman","Civilian Awards"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-tEWQOzblartcWUjjBP7t', 'General Science', 'मानव शरीर में रक्त की मात्रा शरीर के भार का लगभग कितना प्रतिशत होती है?', 'The volume of blood in the human body is approximately what percentage of body weight?', '7%', '7%', 91, 0, '{"facts":["एक सामान्य वयस्क मनुष्य के शरीर में औसतन 5 से 6 लीटर रक्त होता है।","रक्त का pH मान 7.4 (हल्का क्षारीय/Basic) होता है।"],"factsEn":["A normal adult human body contains an average of 5 to 6 liters of blood.","The pH value of blood is 7.4 (slightly basic)."],"explanationHi":"रक्त एक तरल संयोजी ऊतक (Fluid connective tissue) है जो ऑक्सीजन, पोषक तत्वों और हार्मोन को शरीर की कोशिकाओं तक पहुँचाता है।","explanationEn":"Blood is a fluid connective tissue that transports oxygen, nutrients, and hormones to the body''s cells.","memoryTip":"साप्ताहिक 7 दिन की तरह, शरीर में 7% खून दौड़ता है।","memoryTipEn":"7% keeps the body pumping.","related":["Blood Plasma","Red Blood Cells (RBC)","Bone Marrow"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5zYjrxxB-H53m-34SNl1P', 'General Knowledge', 'भारत के किस शहर को ''गुलाबी शहर'' (Pink City) कहा जाता है?', 'Which city of India is known as the ''Pink City''?', 'जयपुर', 'Jaipur', 93, 0, '{"facts":["जयपुर राजस्थान की राजधानी है।","इसे 1727 में सवाई जयसिंह द्वितीय ने बसाया था।"],"factsEn":["Jaipur is the capital of Rajasthan.","It was founded in 1727 by Sawai Jai Singh II."],"explanationHi":"1876 में वेल्स के राजकुमार (प्रिंस अल्बर्ट) के स्वागत के लिए महाराजा राम सिंह ने पूरे शहर को गुलाबी रंग से रंगवा दिया था, जो आतिथ्य (Hospitality) का प्रतीक है।","explanationEn":"To welcome the Prince of Wales (Prince Albert) in 1876, Maharaja Ram Singh painted the entire city pink, which is a symbol of hospitality.","memoryTip":"राजस्थान के ''जय'' में ''गुलाबी'' रंग घुला है।","memoryTipEn":"Jaipur wears the pink of hospitality.","related":["Hawa Mahal","Sawai Jai Singh II","Golden Triangle (Delhi-Agra-Jaipur)"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qLBmxYs-0dmxyCxZYex8p', 'General Science', 'सूर्य की ऊर्जा का मुख्य स्रोत क्या है?', 'What is the main source of the Sun''s energy?', 'नाभिकीय संलयन (Nuclear Fusion)', 'Nuclear Fusion', 96, 0, '{"facts":["इस प्रक्रिया में हाइड्रोजन के हल्के नाभिक आपस में जुड़कर हीलियम बनाते हैं।","यही सिद्धांत ''हाइड्रोजन बम'' (H-Bomb) में भी कार्य करता है।"],"factsEn":["In this process, light hydrogen nuclei fuse together to form helium.","The same principle operates in a ''Hydrogen Bomb'' (H-Bomb)."],"explanationHi":"सूर्य के केंद्र (Core) में अत्यधिक तापमान और दबाव के कारण संलयन होता है, जिससे अपार मात्रा में प्रकाश और ऊष्मा (ऊर्जा) निकलती है।","explanationEn":"Due to extreme temperature and pressure at the Sun''s core, fusion occurs, releasing immense amounts of light and heat (energy).","memoryTip":"सूरज में अणु ''मिलकर'' (संलयन) रोशनी फैलाते हैं।","memoryTipEn":"Fusion fuses hydrogen to light the solar system.","related":["Hydrogen and Helium","Nuclear Fission","Solar Core"]}', 'published', 1776086268, 1776086268);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YbaM4aP8PeLHoo8aOX2bk', 'General Knowledge', 'मध्य प्रदेश का स्थापना दिवस कब मनाया जाता है?', 'When is the foundation day of Madhya Pradesh celebrated?', '1 नवंबर 1956', '1 November 1956', 99, 0, '{"facts":["मध्य प्रदेश का गठन राज्य पुनर्गठन अधिनियम 1956 के तहत किया गया था।","गठन के समय इसकी राजधानी भोपाल को बनाया गया, जो उस समय सीहोर जिले की एक तहसील थी।"],"factsEn":["Madhya Pradesh was formed under the States Reorganisation Act, 1956.","At the time of formation, Bhopal was made its capital, which was then a tehsil of Sehore district."],"explanationHi":"विभिन्न हिंदी भाषी क्षेत्रों (मध्य भारत, विंध्य प्रदेश, भोपाल राज्य) को मिलाकर आधुनिक मध्य प्रदेश की स्थापना की गई थी।","explanationEn":"Modern Madhya Pradesh was established by merging various Hindi-speaking regions (Madhya Bharat, Vindhya Pradesh, Bhopal State).","memoryTip":"1 नवंबर को ''मध्य'' (बीच) में ''प्रदेश'' बना।","memoryTipEn":"Nov 1st is the birthday of the heart of India.","related":["State Reorganisation Act 1956","Fazal Ali Commission","Bhopal State"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yaN8t2nrRs6ZLT1Vz44Nz', 'General Knowledge', 'मध्य प्रदेश का पुनर्गठन (छत्तीसगढ़ का विभाजन) कब हुआ था?', 'When was Madhya Pradesh reorganized (separation of Chhattisgarh)?', '1 नवंबर 2000', '1 November 2000', 98, 0, '{"facts":["मध्य प्रदेश से अलग होकर छत्तीसगढ़ भारत का 26वां राज्य बना।","विभाजन से पहले क्षेत्रफल की दृष्टि से मध्य प्रदेश भारत का सबसे बड़ा राज्य था।"],"factsEn":["Chhattisgarh became the 26th state of India after separating from Madhya Pradesh.","Before the partition, Madhya Pradesh was the largest state in India by area."],"explanationHi":"84वें संविधान संशोधन विधेयक के माध्यम से 1 नवंबर 2000 को 16 जिलों के साथ छत्तीसगढ़ को अलग राज्य का दर्जा दिया गया।","explanationEn":"Through the 84th Constitutional Amendment Bill, Chhattisgarh was granted separate statehood with 16 districts on November 1, 2000.","memoryTip":"सन 2000 में एमपी के 2 टुकड़े (MP और CG) हो गए।","memoryTipEn":"Y2K brought a new state CG from MP.","related":["Chhattisgarh Formation","Digvijaya Singh (CM at that time)","Area of MP"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('I3f8ne6GtEPC0QMx7NaKK', 'General Knowledge', 'मध्य प्रदेश का राजकीय पशु क्या है?', 'What is the state animal of Madhya Pradesh?', 'बारहसिंगा (Barasingha)', 'Barasingha (Swamp Deer)', 95, 0, '{"facts":["यह ''रुसर्वस डौवासेली'' (Rucervus duvaucelii) प्रजाति का है, विशेष रूप से ''ब्रेडरी प्रजाति'' जो कान्हा राष्ट्रीय उद्यान में पाई जाती है।","इसे 1981 में राजकीय पशु घोषित किया गया था।"],"factsEn":["It belongs to the ''Rucervus duvaucelii'' species, specifically the ''Brandri species'' found in Kanha National Park.","It was declared the state animal in 1981."],"explanationHi":"कान्हा नेशनल पार्क भारत का एकमात्र ऐसा पार्क है जिसने अपने शुभंकर ''भूरसिंह द बारहसिंगा'' को आधिकारिक तौर पर अपनाया है।","explanationEn":"Kanha National Park is the only park in India to officially adopt a mascot, ''Bhoorsingh the Barasingha''.","memoryTip":"एमपी के कान्हा में ''बारह सींग'' वाला हिरण दौड़ता है।","memoryTipEn":"12 horns (Bara-singha) crown the MP forests.","related":["Kanha Kisli National Park","Bhoorsingh the Barasingha","Swamp Deer"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('tglKNyCrpbbDt1jIffSek', 'General Knowledge', 'मध्य प्रदेश का राजकीय पक्षी क्या है?', 'What is the state bird of Madhya Pradesh?', 'दूधराज या शाहबुलबुल (Asian Paradise Flycatcher)', 'Dhudhraj or Shah Bulbul (Asian Paradise Flycatcher)', 94, 0, '{"facts":["इसका वैज्ञानिक नाम ''टेरप्सिफोन पैराडाइसी'' (Terpsiphone paradisi) है।","इसे भी 1 नवंबर 1981 को (25वें स्थापना दिवस पर) राजकीय पक्षी घोषित किया गया था।"],"factsEn":["Its scientific name is ''Terpsiphone paradisi''.","It was also declared the state bird on Nov 1, 1981 (on the 25th foundation day)."],"explanationHi":"यह एक अत्यंत सुंदर पक्षी है जिसकी लंबी सफेद या लाल पूंछ होती है। यह मुख्य रूप से कीड़े-मकोड़े खाता है।","explanationEn":"It is an extremely beautiful bird with a long white or rufous tail. It primarily feeds on insects.","memoryTip":"एमपी का पक्षी ''दूध'' जैसा सफेद ''राज'' (दूधराज) करता है।","memoryTipEn":"Paradise flies in the skies of MP.","related":["State Symbols of MP","Sardarpur Sanctuary","Sailana Sanctuary"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WjLv7xQCS8OfmIOOLOptk', 'General Knowledge', 'मध्य प्रदेश की राजकीय मछली कौनसी है?', 'Which is the state fish of Madhya Pradesh?', 'महाशीर (Mahseer)', 'Mahseer', 90, 0, '{"facts":["इसे ''टोर टोर'' (Tor Tor) के नाम से भी जाना जाता है।","इसे 2011 में मध्य प्रदेश की राजकीय मछली घोषित किया गया था।"],"factsEn":["It is also known scientifically as ''Tor Tor''.","It was declared the state fish of MP in 2011."],"explanationHi":"यह मछली नर्मदा नदी में प्रमुखता से पाई जाती है और इसे ''नदियों का बाघ'' (Tiger of Rivers) भी कहा जाता है। यह विलुप्तप्राय श्रेणी में आती है।","explanationEn":"This fish is prominently found in the Narmada River and is also called the ''Tiger of Rivers''. It falls under the endangered category.","memoryTip":"नर्मदा की ''महान'' मछली = महाशीर।","memoryTipEn":"Mahseer rules the Narmada waters.","related":["Narmada River","Tor Tor","Endangered Species"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2Bd783JdXdbc8VeVn0WrC', 'General Knowledge', 'मध्य प्रदेश की राजकीय फसल कौनसी है?', 'Which is the state crop of Madhya Pradesh?', 'सोयाबीन', 'Soybean', 95, 0, '{"facts":["मध्य प्रदेश भारत का सबसे बड़ा सोयाबीन उत्पादक राज्य है।","इसी कारण मध्य प्रदेश को ''सोया स्टेट'' (Soya State) भी कहा जाता है।"],"factsEn":["Madhya Pradesh is the largest soybean-producing state in India.","Due to this, MP is also known as the ''Soya State''."],"explanationHi":"सोयाबीन एक खरीफ (Kharif) की फसल है और यह प्रोटीन का बहुत ही समृद्ध स्रोत (लगभग 40-42%) है। उज्जैन में एशिया का सबसे बड़ा सोयाबीन संयंत्र स्थित है।","explanationEn":"Soybean is a Kharif crop and a very rich source of protein (approx 40-42%). Asia''s largest soybean plant is located in Ujjain.","memoryTip":"एमपी ''सोता'' नहीं, ''सोया'' (बीन) उगाता है।","memoryTipEn":"MP is the Soya State of India.","related":["Ujjain Soybean Plant","Kharif Crops","Protein Source"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HGH-OQoELpJ8onpA-1d96', 'General Knowledge', 'मध्य प्रदेश की सबसे ऊँची चोटी कौनसी है?', 'Which is the highest peak in Madhya Pradesh?', 'धूपगढ़ (Dhupgarh)', 'Dhupgarh', 97, 0, '{"facts":["इसकी ऊँचाई 1350 मीटर है।","यह पचमढ़ी (Pachmarhi) में सतपुड़ा पर्वतमाला (महादेव पहाड़ियों) पर स्थित है।"],"factsEn":["Its elevation is 1350 meters.","It is located in Pachmarhi on the Satpura mountain range (Mahadeo Hills)."],"explanationHi":"धूपगढ़ मध्य प्रदेश का सबसे ऊंचा स्थान है और यहां का सूर्योदय तथा सूर्यास्त का नज़ारा बहुत प्रसिद्ध है। पचमढ़ी को ''सतपुड़ा की रानी'' कहा जाता है।","explanationEn":"Dhupgarh is the highest point in MP, and its sunrise and sunset views are very famous. Pachmarhi is called the ''Queen of Satpura''.","memoryTip":"सबसे ऊँची चोटी पर सबसे तेज़ ''धूप'' (धूपगढ़) लगती है।","memoryTipEn":"Dhupgarh touches the highest sun in MP.","related":["Pachmarhi","Satpura Range","Mahadeo Hills"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('EKdW8y5MTFRvZlluieQEl', 'General Knowledge', 'मध्य प्रदेश की सबसे लंबी नदी कौनसी है?', 'Which is the longest river in Madhya Pradesh?', 'नर्मदा', 'Narmada', 99, 0, '{"facts":["यह भारत की पांचवीं सबसे लंबी नदी और पश्चिम की ओर बहने वाली सबसे लंबी नदी है।","नर्मदा की कुल लंबाई 1312 किमी है, जिसमें से 1077 किमी मध्य प्रदेश में बहती है।"],"factsEn":["It is the 5th longest river in India and the longest west-flowing river.","The total length of Narmada is 1312 km, out of which 1077 km flows in MP."],"explanationHi":"इसे ''मध्य प्रदेश की जीवन रेखा'' (Lifeline of MP) कहा जाता है। यह अमरकंटक (अनूपपुर जिले) से निकलती है और खंभात की खाड़ी (अरब सागर) में गिरती है।","explanationEn":"It is called the ''Lifeline of MP''. It originates from Amarkantak (Anuppur district) and falls into the Gulf of Khambhat (Arabian Sea).","memoryTip":"एमपी की जीवन-रेखा ''नर्म'' (नर्मदा) होकर बहती है।","memoryTipEn":"Narmada nurtures Madhya Pradesh.","related":["Amarkantak","Lifeline of MP","West-flowing Rivers"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('eta74cRbYbeVlda8sUR6-', 'General Knowledge', 'प्रदूषण के आधार पर ''मध्य प्रदेश की गंगा'' किसे कहा जाता है?', 'Based on pollution, which river is called the ''Ganga of Madhya Pradesh''?', 'बेतवा (Betwa)', 'Betwa', 94, 0, '{"facts":["पवित्रता के आधार पर नर्मदा को एमपी की गंगा कहा जाता है, लेकिन प्रदूषण के स्तर की तुलना के कारण बेतवा को एमपी की गंगा कहा जाता है।","बेतवा रायसेन जिले के कुमरागाँव से निकलती है।"],"factsEn":["Based on sanctity, Narmada is called the Ganga of MP, but due to pollution levels, Betwa is called the Ganga of MP.","Betwa originates from Kumragaon in Raisen district."],"explanationHi":"प्रसिद्ध सांची का स्तूप और ओरछा शहर बेतवा नदी के किनारे ही स्थित हैं। यह यमुना की एक महत्वपूर्ण सहायक नदी है।","explanationEn":"The famous Sanchi Stupa and Orchha town are situated on the banks of the Betwa river. It is a major tributary of the Yamuna.","memoryTip":"''बेतवा'' प्रदूषित होकर एमपी की ''गंगा'' कहलाने लगी।","memoryTipEn":"Betwa bears the title of MP''s Ganga.","related":["Raisen","Orchha","Yamuna Tributary"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('68VU8SHDtZYksN8e8r82y', 'General Knowledge', 'खजुराहो के प्रसिद्ध मंदिरों का निर्माण किस वंश के शासकों ने करवाया था?', 'The famous temples of Khajuraho were built by the rulers of which dynasty?', 'चंदेल वंश', 'Chandela Dynasty', 98, 0, '{"facts":["इन मंदिरों का निर्माण 950 ई. से 1050 ई. के बीच करवाया गया था।","खजुराहो मध्य प्रदेश के छतरपुर जिले में स्थित है।"],"factsEn":["These temples were built between 950 AD and 1050 AD.","Khajuraho is located in the Chhatarpur district of Madhya Pradesh."],"explanationHi":"ये मंदिर नागर शैली (Nagara architecture) की वास्तुकला और कामुक मूर्तिकला के लिए विश्व प्रसिद्ध हैं। 1986 में इसे यूनेस्को विश्व धरोहर घोषित किया गया।","explanationEn":"These temples are world-famous for their Nagara style architecture and erotic sculptures. It was declared a UNESCO World Heritage Site in 1986.","memoryTip":"खजुराहो के मंदिर ''चाँद'' (चंदेल) की रोशनी में चमकते हैं।","memoryTipEn":"Chandelas carved the Khajuraho stones.","related":["Chhatarpur","Kandariya Mahadeva Temple","UNESCO World Heritage"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kfeK3TMQvwvB1H6QM8P3B', 'General Knowledge', 'मध्य प्रदेश में ''झीलों का शहर'' (City of Lakes) किसे कहा जाता है?', 'Which city is known as the ''City of Lakes'' in Madhya Pradesh?', 'भोपाल', 'Bhopal', 95, 0, '{"facts":["भोपाल मध्य प्रदेश की राजधानी है।","यहाँ की ''बड़ी झील'' (Upper Lake / भोजताल) का निर्माण परमार राजा भोज ने 11वीं सदी में करवाया था।"],"factsEn":["Bhopal is the capital of Madhya Pradesh.","Its ''Upper Lake'' (Bhojtal) was built by the Paramara King Bhoja in the 11th century."],"explanationHi":"अपनी अनेक प्राकृतिक और कृत्रिम झीलों के कारण भोपाल को यह उपनाम दिया गया है। (भारत स्तर पर झीलों का शहर उदयपुर को कहा जाता है)।","explanationEn":"Bhopal is given this nickname due to its numerous natural and artificial lakes. (On a national level, Udaipur is called the City of Lakes).","memoryTip":"''भोज'' की ताल (भोजताल) से ''भोपाल'' बना झीलों का शहर।","memoryTipEn":"Bhopal boasts beautiful lakes.","related":["Bhojtal","Raja Bhoj","Upper Lake"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xuDvLRzCltLvQHWpIe1Ls', 'General Knowledge', 'मध्य प्रदेश की ''ऊर्जा राजधानी'' (Energy Capital) किसे कहा जाता है?', 'Which city is known as the ''Energy Capital'' of Madhya Pradesh?', 'सिंगरौली', 'Singrauli', 92, 0, '{"facts":["सिंगरौली मध्य प्रदेश का सबसे पूर्वी (Easternmost) जिला है।","यह सीधी (Sidhi) जिले से अलग होकर 2008 में नया जिला बना।"],"factsEn":["Singrauli is the easternmost district of Madhya Pradesh.","It was carved out of Sidhi district to form a new district in 2008."],"explanationHi":"यहाँ कोयले के विशाल भंडार और एनटीपीसी (NTPC) के कई थर्मल पावर प्लांट स्थित हैं (विंध्याचल सुपर थर्मल पावर स्टेशन), जो भारी मात्रा में बिजली पैदा करते हैं।","explanationEn":"It houses massive coal reserves and multiple NTPC thermal power plants (Vindhyachal Super Thermal Power Station) that generate a huge amount of electricity.","memoryTip":"सिंगरौली का कोयला एमपी की ''ऊर्जा'' है।","memoryTipEn":"Singrauli supplies the spark (energy).","related":["Vindhyachal Thermal Power Station","Coal Reserves","Easternmost District of MP"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SjJ7QDcZljUAUW5gDPPhh', 'General Knowledge', 'मध्य प्रदेश का सबसे बड़ा राष्ट्रीय उद्यान कौनसा है?', 'Which is the largest national park in Madhya Pradesh?', 'कान्हा किसली', 'Kanha Kisli', 96, 0, '{"facts":["यह मंडला और बालाघाट जिलों में फैला हुआ है।","इसका क्षेत्रफल 940 वर्ग किलोमीटर है।"],"factsEn":["It is spread across Mandla and Balaghat districts.","Its total area is 940 square kilometers."],"explanationHi":"यह 1955 में राष्ट्रीय उद्यान बना और 1973-74 में ''प्रोजेक्ट टाइगर'' के तहत शामिल होने वाला मध्य प्रदेश का पहला टाइगर रिजर्व है।","explanationEn":"It became a national park in 1955 and was the first tiger reserve in MP to be included under ''Project Tiger'' in 1973-74.","memoryTip":"एमपी के जंगलों का ''कान्हा'' सबसे बड़ा है।","memoryTipEn":"Kanha covers the most kilometers.","related":["Mandla","Project Tiger","Bhoorsingh the Barasingha"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('knWxTKwAEZuV7s0NlMQDc', 'General Knowledge', 'मध्य प्रदेश के प्रथम मुख्यमंत्री कौन थे?', 'Who was the first Chief Minister of Madhya Pradesh?', 'पं. रविशंकर शुक्ल', 'Pt. Ravishankar Shukla', 95, 0, '{"facts":["इन्होंने 1 नवंबर 1956 को मध्य प्रदेश के पहले सीएम के रूप में कार्यभार संभाला।","उनका कार्यकाल बहुत छोटा रहा, क्योंकि 31 दिसंबर 1956 को उनका निधन हो गया था।"],"factsEn":["He took charge as the first CM of MP on Nov 1, 1956.","His tenure was very short, as he passed away on Dec 31, 1956."],"explanationHi":"गठन से पहले, वे ''मध्य प्रांत और बरार'' (Central Provinces and Berar) के मुख्यमंत्री (तब प्रीमियर कहलाते थे) भी रहे थे।","explanationEn":"Before the formation, he had also served as the Chief Minister (then called Premier) of the ''Central Provinces and Berar''.","memoryTip":"एमपी की शुरुआत ''रवि'' (सूर्य) की चमक (रविशंकर) से हुई।","memoryTipEn":"Ravishankar rose as the first CM.","related":["Dr. Pattabhi Sitaramayya","Central Provinces and Berar","First Cabinet of MP"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('hVmRdggLJtmeX0KLVVl5i', 'General Knowledge', 'मध्य प्रदेश के प्रथम राज्यपाल कौन थे?', 'Who was the first Governor of Madhya Pradesh?', 'डॉ. पट्टाभि सीतारमैया', 'Dr. Pattabhi Sitaramayya', 92, 0, '{"facts":["वे 1 नवंबर 1956 को मध्य प्रदेश के पहले राज्यपाल बने।","वे एक प्रमुख स्वतंत्रता सेनानी और कांग्रेस के नेता थे।"],"factsEn":["He became the first Governor of MP on Nov 1, 1956.","He was a prominent freedom fighter and Congress leader."],"explanationHi":"सीतारमैया वही नेता हैं जिन्हें 1939 के त्रिपुरी कांग्रेस अधिवेशन में सुभाष चंद्र बोस ने अध्यक्ष पद के चुनाव में हराया था (जो गांधीजी के उम्मीदवार थे)।","explanationEn":"Sitaramayya is the same leader whom Subhas Chandra Bose defeated in the presidential election at the 1939 Tripuri Congress session (he was Gandhi''s candidate).","memoryTip":"एमपी की पहली गद्दी पर ''सीता-राम'' (सीतारमैया) विराजमान हुए।","memoryTipEn":"Sitaramayya sat on the first Governor''s seat.","related":["Tripuri Session 1939","Subhas Chandra Bose","History of Indian National Congress"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uaEbE3JwLdmTivXTAkpk6', 'General Knowledge', 'मध्य प्रदेश की पहली महिला मुख्यमंत्री कौन थीं?', 'Who was the first female Chief Minister of Madhya Pradesh?', 'उमा भारती', 'Uma Bharti', 93, 0, '{"facts":["वे दिसंबर 2003 से अगस्त 2004 तक मध्य प्रदेश की मुख्यमंत्री रहीं।","वे टीकमगढ़ जिले (मध्य प्रदेश) से ताल्लुक रखती हैं।"],"factsEn":["She served as the CM of MP from Dec 2003 to Aug 2004.","She belongs to the Tikamgarh district of MP."],"explanationHi":"उनके नेतृत्व में बीजेपी ने 2003 के विधानसभा चुनावों में दिग्विजय सिंह की 10 साल पुरानी कांग्रेस सरकार को हराया था।","explanationEn":"Under her leadership, the BJP defeated Digvijaya Singh''s 10-year-old Congress government in the 2003 assembly elections.","memoryTip":"एमपी की ''उमा'' (माँ) ने पहली बार सत्ता संभाली।","memoryTipEn":"Uma ushered in the first female rule in MP.","related":["Sarla Grewal (First Female Governor of MP)","Digvijaya Singh","Tikamgarh"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wZjxERdEJSV8pV7181Ox5', 'General Knowledge', 'तानसेन का मकबरा (Tomb of Tansen) कहाँ स्थित है?', 'Where is the Tomb of Tansen located?', 'ग्वालियर', 'Gwalior', 97, 0, '{"facts":["यह मकबरा मोहम्मद गौस के मकबरे के ठीक बगल में स्थित है।","तानसेन (रामतनु पांडेय) अकबर के नवरत्नों में से एक थे।"],"factsEn":["The tomb is situated right next to the tomb of Mohammad Ghaus.","Tansen (Ramtanu Pandey) was one of the Navaratnas of Akbar."],"explanationHi":"यह मध्य प्रदेश के सबसे बड़े मकबरों में से एक है। यहाँ हर साल प्रसिद्ध ''तानसेन समारोह'' (Tansen Samaroh) संगीत उत्सव आयोजित किया जाता है।","explanationEn":"It is one of the largest tombs in Madhya Pradesh. The famous musical festival ''Tansen Samaroh'' is held here every year.","memoryTip":"''ग्वालियर'' के गानों में तानसेन की तान है।","memoryTipEn":"Gwalior guards Tansen''s grave.","related":["Tansen Samaroh","Akbar''s Navaratnas","Mohammad Ghaus"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('J8J6wIvdzm2kF0unaBi-z', 'General Knowledge', 'देवी अहिल्याबाई होल्कर की राजधानी कहाँ थी?', 'Where was the capital of Devi Ahilyabai Holkar?', 'महेश्वर (खरगोन)', 'Maheshwar (Khargone)', 94, 0, '{"facts":["महेश्वर नर्मदा नदी के तट पर स्थित एक सुंदर और ऐतिहासिक नगर है।","अहिल्याबाई होल्कर मालवा साम्राज्य (मराठा) की महारानी थीं।"],"factsEn":["Maheshwar is a beautiful and historical town located on the banks of the Narmada River.","Ahilyabai Holkar was the Queen of the Malwa Empire (Maratha)."],"explanationHi":"उन्होंने अपनी राजधानी इंदौर से महेश्वर स्थानांतरित कर दी थी। महेश्वर अपने सुंदर घाटों और ''माहेश्वरी साड़ियों'' (Maheshwari Sarees) के लिए विश्व प्रसिद्ध है।","explanationEn":"She shifted her capital from Indore to Maheshwar. Maheshwar is world-famous for its beautiful ghats and ''Maheshwari Sarees''.","memoryTip":"अहिल्या ''महान'' थीं, इसलिए ''महेश्वर'' में राजधानी बनाई।","memoryTipEn":"Maheshwar matched Ahilya''s majesty.","related":["Maheshwari Sarees","Holkar Dynasty","Indore"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bgQCj644jH6p-Rd_ZwZE3', 'General Knowledge', 'मध्य प्रदेश में सिंहस्थ (कुंभ) मेला कहाँ लगता है?', 'Where is the Simhastha (Kumbh) Mela held in Madhya Pradesh?', 'उज्जैन', 'Ujjain', 98, 0, '{"facts":["यह मेला हर 12 साल में क्षिप्रा (Kshipra) नदी के तट पर लगता है।","पिछला सिंहस्थ 2016 में लगा था और अगला 2028 में लगेगा।"],"factsEn":["This fair is held every 12 years on the banks of the Kshipra River.","The last Simhastha was held in 2016 and the next will be in 2028."],"explanationHi":"उज्जैन को ''महाकाल की नगरी'' कहा जाता है। भारत में 4 स्थानों (हरिद्वार, प्रयागराज, नासिक, उज्जैन) पर कुंभ मेला लगता है।","explanationEn":"Ujjain is called the ''City of Mahakal''. The Kumbh Mela is held at 4 places in India (Haridwar, Prayagraj, Nashik, Ujjain).","memoryTip":"उज्जैन के ''महाकाल'' सिंहस्थ कुंभ में विराजमान होते हैं।","memoryTipEn":"Ujjain unites the pilgrims on Kshipra.","related":["Kshipra River","Mahakaleshwar Jyotirlinga","Kumbh Mela"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aoGiRklCa5mxi_RdE76jX', 'General Knowledge', 'सिक्योरिटी पेपर मिल (Security Paper Mill) मध्य प्रदेश में कहाँ स्थित है?', 'Where is the Security Paper Mill located in Madhya Pradesh?', 'नर्मदापुरम (होशंगाबाद)', 'Narmadapuram (Hoshangabad)', 92, 0, '{"facts":["इसकी स्थापना 1968 में हुई थी।","होशंगाबाद जिले का नाम बदलकर अब ''नर्मदापुरम'' कर दिया गया है।"],"factsEn":["It was established in 1968.","The name of the Hoshangabad district has now been changed to ''Narmadapuram''."],"explanationHi":"यहाँ बैंक नोट, पासपोर्ट, स्टाम्प पेपर और अन्य सरकारी दस्तावेजों को छापने के लिए विशेष सुरक्षा कागज (Security paper) तैयार किया जाता है।","explanationEn":"Special security paper is manufactured here for printing bank notes, passports, stamp papers, and other government documents.","memoryTip":"कागज को ''होश'' (होशंगाबाद) में सुरक्षित रखा जाता है।","memoryTipEn":"Hoshangabad handles the secure paper.","related":["Bank Note Press Dewas","Currency Printing","Narmadapuram"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2EryCBVLa9Ple0sGZEAlN', 'General Knowledge', 'बैंक नोट प्रेस (Bank Note Press) मध्य प्रदेश में कहाँ स्थित है?', 'Where is the Bank Note Press located in Madhya Pradesh?', 'देवास (Dewas)', 'Dewas', 93, 0, '{"facts":["इसकी स्थापना 1974 में हुई थी।","यह भारत सरकार के वित्त मंत्रालय (SPMCIL) के अधीन कार्य करता है।"],"factsEn":["It was established in 1974.","It operates under the Ministry of Finance, Govt of India (SPMCIL)."],"explanationHi":"देवास बैंक नोट प्रेस में उच्च मूल्यवर्ग के बैंक नोटों (जैसे ₹500, ₹2000 आदि) की छपाई होती है।","explanationEn":"High denomination bank notes (like ₹500, ₹2000, etc.) are printed at the Dewas Bank Note Press.","memoryTip":"''देवों'' (देवास) के पास ही धन (बैंक नोट) छपता है।","memoryTipEn":"Dewas dispenses the currency.","related":["Security Paper Mill","SPMCIL","Currency Note Press Nashik"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GuLdLe33v7hX2p1_MzKUl', 'General Knowledge', 'नेपानगर (Nepanagar) किस उद्योग के लिए प्रसिद्ध है?', 'Nepanagar is famous for which industry?', 'अखबारी कागज (Newsprint Paper)', 'Newsprint Paper', 91, 0, '{"facts":["नेपानगर मध्य प्रदेश के बुरहानपुर (Burhanpur) जिले में स्थित है।","यहाँ ''नेशनल न्यूजप्रिंट एंड पेपर मिल्स'' (Nepa Mills) स्थित है।"],"factsEn":["Nepanagar is located in the Burhanpur district of Madhya Pradesh.","The ''National Newsprint and Paper Mills'' (Nepa Mills) is located here."],"explanationHi":"यह भारत की पहली अखबारी कागज मिल है, जिसे 1948 में स्थापित किया गया था और 1956 में केंद्र सरकार ने इसका अधिग्रहण कर लिया।","explanationEn":"It is India''s first newsprint paper mill, established in 1948 and taken over by the Central Government in 1956.","memoryTip":"''न्यूज़पेपर'' का ''नेपा'' नगर।","memoryTipEn":"Nepa means Newsprint.","related":["Burhanpur","Paper Industry","Security Paper Mill"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2fu4EPG8x16ieEX9v65Kl', 'General Knowledge', 'भारत में हीरे (Diamond) की एकमात्र खदान मध्य प्रदेश में कहाँ है?', 'Where is the only diamond mine in India located in Madhya Pradesh?', 'पन्ना (Panna)', 'Panna', 96, 0, '{"facts":["मझगवां (Majhgawan) और हिनौता (Hinota) खदानें पन्ना जिले की प्रमुख हीरा खदानें हैं।","यहाँ खनन ''राष्ट्रीय खनिज विकास निगम'' (NMDC) द्वारा किया जाता है।"],"factsEn":["Majhgawan and Hinota are the major diamond mines in the Panna district.","Mining here is done by the National Mineral Development Corporation (NMDC)."],"explanationHi":"पन्ना को ''डायमंड सिटी ऑफ इंडिया'' कहा जाता है। विंध्य पर्वत श्रृंखला के इस क्षेत्र में हीरे के बड़े भंडार मौजूद हैं।","explanationEn":"Panna is called the ''Diamond City of India''. Large reserves of diamonds exist in this region of the Vindhya mountain range.","memoryTip":"पन्ना खुद एक ''रत्न'' है, जहाँ ''हीरा'' मिलता है।","memoryTipEn":"Panna produces precious diamonds.","related":["NMDC","Diamond City","Majhgawan Mine"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5E73ZDOGF-tKEX-izJK9l', 'General Knowledge', 'मलाजखंड (Malajkhand) किस खनिज के उत्पादन के लिए प्रसिद्ध है?', 'Malajkhand is famous for the production of which mineral?', 'तांबा (Copper)', 'Copper', 95, 0, '{"facts":["मलाजखंड मध्य प्रदेश के बालाघाट (Balaghat) जिले में स्थित है।","यह एशिया की सबसे बड़ी ओपन-कास्ट (Open-cast) तांबे की खदान है।"],"factsEn":["Malajkhand is located in the Balaghat district of Madhya Pradesh.","It is the largest open-cast copper mine in Asia."],"explanationHi":"यहाँ खनन ''हिंदुस्तान कॉपर लिमिटेड'' (HCL) द्वारा किया जाता है। मध्य प्रदेश भारत में तांबे का सबसे बड़ा उत्पादक राज्य है।","explanationEn":"Mining here is done by Hindustan Copper Limited (HCL). Madhya Pradesh is the largest producer of copper in India.","memoryTip":"तांबे से ''माल'' (मलाजखंड) बहुत मिलता है।","memoryTipEn":"Malajkhand mines the copper metal.","related":["Balaghat","Hindustan Copper Limited","Khetri (Rajasthan)"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('biKsnGYa0GCRLyKv5K0Mn', 'General Knowledge', 'भारवेली खदान (Bharveli Mine) जो एशिया की सबसे बड़ी खदानों में से एक है, किस खनिज के लिए प्रसिद्ध है?', 'The Bharveli Mine, one of the largest in Asia, is famous for which mineral?', 'मैंगनीज (Manganese)', 'Manganese', 92, 0, '{"facts":["यह खदान भी मध्य प्रदेश के बालाघाट (Balaghat) जिले में स्थित है।","यहाँ से उच्च गुणवत्ता वाला (high-grade) मैंगनीज अयस्क निकाला जाता है।"],"factsEn":["This mine is also located in the Balaghat district of Madhya Pradesh.","High-grade manganese ore is extracted from here."],"explanationHi":"मध्य प्रदेश मैंगनीज उत्पादन में भारत के अग्रणी राज्यों में से एक है, और बालाघाट जिला इसकी ''मैंगनीज राजधानी'' (Manganese Capital) है।","explanationEn":"Madhya Pradesh is one of the leading states in manganese production in India, and Balaghat district is its ''Manganese Capital''.","memoryTip":"मैंगनीज बहुत ''भारी'' (भारवेली) होता है।","memoryTipEn":"Bharveli brings out Manganese.","related":["Balaghat","Manganese Ore India Limited (MOIL)","Malajkhand"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('EYM8mMmynEz6jsvFR_61G', 'General Knowledge', 'ग्वालियर के किले (Gwalior Fort) का निर्माण किसने करवाया था?', 'Who built the Gwalior Fort?', 'राजा सूरजसेन', 'King Suraj Sen', 93, 0, '{"facts":["राजा सूरजसेन ने 8वीं शताब्दी में इस किले का निर्माण करवाया था।","इस किले को ''भारत के किलों का जिब्राल्टर'' (Gibraltar of India) कहा जाता है।"],"factsEn":["King Suraj Sen built this fort in the 8th century.","This fort is known as the ''Gibraltar of India''."],"explanationHi":"यह किला गोपांचल पर्वत (Gopachal hill) पर स्थित है। मुगल सम्राट बाबर ने इसे ''हिंद के किलों के गले का मोती'' (Pearl amongst the fortresses in India) कहा था।","explanationEn":"The fort is situated on the Gopachal hill. Mughal Emperor Babur called it the ''Pearl amongst the fortresses in India''.","memoryTip":"ग्वालियर का किला ''सूरज'' (सूरजसेन) की तरह चमकता है।","memoryTipEn":"Suraj Sen setup the strongest fort.","related":["Gibraltar of India","Maan Singh Tomar","Gopachal Hill"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('C1BmQiTKdV0HEHAU_tA65', 'General Knowledge', 'कैप्टन रूप सिंह स्टेडियम मध्य प्रदेश में कहाँ स्थित है?', 'Where is the Captain Roop Singh Stadium located in Madhya Pradesh?', 'ग्वालियर', 'Gwalior', 94, 0, '{"facts":["यह मूल रूप से एक हॉकी स्टेडियम था, जिसे बाद में क्रिकेट स्टेडियम में बदल दिया गया।","कैप्टन रूप सिंह महान हॉकी खिलाड़ी मेजर ध्यानचंद के छोटे भाई थे।"],"factsEn":["It was originally a hockey stadium, which was later converted into a cricket stadium.","Captain Roop Singh was the younger brother of the great hockey player Major Dhyan Chand."],"explanationHi":"इसी स्टेडियम में 2010 में सचिन तेंदुलकर ने दक्षिण अफ्रीका के खिलाफ एकदिवसीय क्रिकेट (ODI) इतिहास का पहला दोहरा शतक (200*) लगाया था।","explanationEn":"In this very stadium, Sachin Tendulkar scored the first-ever double century (200*) in ODI cricket history against South Africa in 2010.","memoryTip":"''रूप'' सिंह का ''ग्वालियर'' में बड़ा नाम है।","memoryTipEn":"Roop Singh scored in Gwalior.","related":["Sachin Tendulkar (First ODI 200)","Major Dhyan Chand","Holkar Stadium (Indore)"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('el6e_PQSylkk-qzXFzSo1', 'General Knowledge', 'मध्य प्रदेश का राजकीय नृत्य (State Dance) कौनसा है?', 'Which is the state dance of Madhya Pradesh?', 'राई (Raai)', 'Raai', 91, 0, '{"facts":["यह मुख्य रूप से बुंदेलखंड (Bundelkhand) क्षेत्र का पारंपरिक लोक नृत्य है।","यह नृत्य बेड़नी (Bedia) समुदाय की महिलाओं द्वारा खुशी और उत्सव के अवसरों पर किया जाता है।"],"factsEn":["It is primarily a traditional folk dance of the Bundelkhand region.","It is performed by the women of the Bedia community on joyous and festive occasions."],"explanationHi":"राई नृत्य में तेज गति और ढोलक की थाप पर शानदार लयबद्ध गतियाँ होती हैं। यह मध्य प्रदेश की सांस्कृतिक पहचान का हिस्सा है।","explanationEn":"The Raai dance involves fast-paced and brilliant rhythmic movements to the beat of a dholak. It is part of MP''s cultural identity.","memoryTip":"एमपी में ''राई'' का पहाड़ (नाच-नाच कर) बना देते हैं।","memoryTipEn":"Raai rules the rhythm of MP.","related":["Bundelkhand","Maach (State Drama)","Bedia Community"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_7wiJ_J6HnnaZ48h6d863', 'General Knowledge', 'मध्य प्रदेश का राजकीय नाट्य (State Drama) कौनसा है?', 'Which is the state drama of Madhya Pradesh?', 'माच (Maach)', 'Maach', 90, 0, '{"facts":["यह मुख्य रूप से मालवा (Malwa) क्षेत्र, विशेषकर उज्जैन का पारंपरिक लोक नाट्य है।","''माच'' शब्द ''मंच'' (Stage) से उत्पन्न हुआ है।"],"factsEn":["It is primarily a traditional folk drama of the Malwa region, especially Ujjain.","The word ''Maach'' is derived from ''Manch'' (Stage)."],"explanationHi":"यह एक संगीतमय नाटक है जो खुले मंच पर प्रस्तुत किया जाता है और इसमें पौराणिक कथाओं तथा स्थानीय कहानियों का वर्णन होता है।","explanationEn":"It is a musical drama performed on an open stage, depicting mythological stories and local folklore.","memoryTip":"नाटक के लिए ''मंच'' (माच) चाहिए।","memoryTipEn":"Maach is the MP theater match.","related":["Malwa Region","Raai (State Dance)","Folk Theatre"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('32qtxRnmZmRZ9w8xCg0FH', 'General Knowledge', 'कर्क रेखा (Tropic of Cancer) मध्य प्रदेश के कितने जिलों से होकर गुजरती है?', 'The Tropic of Cancer passes through how many districts of Madhya Pradesh?', '14 जिलों से', '14 Districts', 98, 0, '{"facts":["यह रेखा मध्य प्रदेश को लगभग दो बराबर भागों (उत्तरी और दक्षिणी) में बांटती है।","प्रमुख जिलों में रतलाम, उज्जैन, भोपाल, सीहोर, विदिशा, रायसेन, सागर आदि शामिल हैं।"],"factsEn":["This line divides Madhya Pradesh into almost two equal halves (Northern and Southern).","Major districts include Ratlam, Ujjain, Bhopal, Sehore, Vidisha, Raisen, Sagar, etc."],"explanationHi":"उज्जैन में महाकालेश्वर मंदिर के ठीक ऊपर से कर्क रेखा गुजरने की मान्यता है, इसीलिए प्राचीन काल से उज्जैन भारत की समय-गणना का केंद्र रहा है।","explanationEn":"It is believed that the Tropic of Cancer passes right above the Mahakaleshwar Temple in Ujjain, making it the ancient center of Indian time calculation.","memoryTip":"कर्क रेखा एमपी के 14 जिलों का ''चीरहरण'' करती है।","memoryTipEn":"14 districts feel the Tropic sun.","related":["Tropic of Cancer in India (8 States)","Ujjain Mahakal","Geography of MP"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('G-XPAQBD4nDA2MzLDjx9g', 'General Knowledge', 'क्षेत्रफल की दृष्टि से मध्य प्रदेश का सबसे छोटा जिला कौनसा है?', 'Which is the smallest district of Madhya Pradesh by area?', 'निवाड़ी (Niwari)', 'Niwari', 92, 0, '{"facts":["निवाड़ी 1 अक्टूबर 2018 को टीकमगढ़ जिले से अलग होकर मध्य प्रदेश का 52वां जिला बना था।","यह क्षेत्रफल और जनसंख्या दोनों ही दृष्टि से मध्य प्रदेश का सबसे छोटा जिला है।"],"factsEn":["Niwari was carved out of Tikamgarh district on October 1, 2018, to become the 52nd district of MP.","It is the smallest district in MP both by area and population."],"explanationHi":"प्रसिद्ध पर्यटन स्थल ओरछा (Orchha) अब इसी नए निवाड़ी जिले के अंतर्गत आता है। (नोट: मैहर और पांढुर्णा नए जिले बने हैं, लेकिन निवाड़ी अभी भी सबसे छोटा माना जाता है)।","explanationEn":"The famous tourist destination Orchha now falls under this new Niwari district. (Note: Maihar and Pandhurna are newer districts, but Niwari is still considered the smallest).","memoryTip":"जो सबसे ''नया'' (निवाड़ी) है, वो सबसे छोटा है।","memoryTipEn":"Niwari is the newest and narrowest.","related":["Tikamgarh","Orchha","Chhindwara (Largest District)"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('cTL76ScnMYiur-bzDc4Tx', 'General Knowledge', 'क्षेत्रफल की दृष्टि से मध्य प्रदेश का सबसे बड़ा जिला कौनसा है?', 'Which is the largest district of Madhya Pradesh by area?', 'छिंदवाड़ा (Chhindwara)', 'Chhindwara', 93, 0, '{"facts":["छिंदवाड़ा जिले का क्षेत्रफल 11,815 वर्ग किलोमीटर है।","प्रसिद्ध ''पातालकोट'' (Patalkot) घाटी, जो भारिया जनजाति का निवास है, इसी जिले में है।"],"factsEn":["The area of Chhindwara district is 11,815 square kilometers.","The famous ''Patalkot'' valley, home to the Bharia tribe, is in this district."],"explanationHi":"यह जिला क्षेत्रफल में इतना बड़ा है कि इसे दो जिलों में बांटने (पांढुर्णा जिला बनाने) की घोषणा की गई है, फिर भी इसका मूल क्षेत्रफल सबसे अधिक रहा है।","explanationEn":"The district is so large that a new district (Pandhurna) was carved out of it, yet its original area remains historically the largest.","memoryTip":"इतना बड़ा जिला है कि इसमें ''छेद'' (छिंदवाड़ा) करना पड़ा।","memoryTipEn":"Chhindwara covers the most ground.","related":["Patalkot","Bharia Tribe","Niwari (Smallest District)"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IGn3S_XREeVWu5vBUYk8N', 'General Knowledge', 'मध्य प्रदेश का सबसे ऊँचा जलप्रपात कौनसा है?', 'Which is the highest waterfall in Madhya Pradesh?', 'बहुटी जलप्रपात (Bahuti Falls)', 'Bahuti Falls', 95, 0, '{"facts":["इसकी ऊँचाई लगभग 198 मीटर (650 फीट) है।","यह रीवा (Rewa) जिले में सेलर (Sellar) नदी पर स्थित है, जो बीहड़ नदी की एक सहायक नदी है।"],"factsEn":["Its height is approximately 198 meters (650 feet).","It is located on the Sellar River (a tributary of the Bihad River) in the Rewa district."],"explanationHi":"पहले ''चचाई जलप्रपात'' (Chachai Falls) को सबसे ऊंचा माना जाता था, लेकिन नवीनतम मापों के अनुसार ''बहुटी'' मध्य प्रदेश का सबसे ऊंचा जलप्रपात है।","explanationEn":"Earlier ''Chachai Falls'' was considered the highest, but according to latest measurements, ''Bahuti'' is the highest waterfall in MP.","memoryTip":"सबसे ऊँची पहाड़ी से पानी ''बहुत'' (बहुटी) नीचे गिरता है।","memoryTipEn":"Bahuti is a beauty from a great height.","related":["Chachai Falls","Rewa District","Keoti Falls"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('b1Cn4FY37uq9281qFOGl6', 'General Knowledge', 'मध्य प्रदेश उच्च न्यायालय (High Court) का मुख्यालय कहाँ स्थित है?', 'Where is the principal seat (headquarters) of the Madhya Pradesh High Court located?', 'जबलपुर', 'Jabalpur', 94, 0, '{"facts":["इसकी स्थापना 1 नवंबर 1956 को राज्य पुनर्गठन अधिनियम के तहत की गई थी।","जबलपुर उच्च न्यायालय का भवन एक शानदार इतालवी गॉथिक (Italian Gothic) वास्तुकला का उदाहरण है।"],"factsEn":["It was established on November 1, 1956, under the States Reorganisation Act.","The building of the Jabalpur High Court is a splendid example of Italian Gothic architecture."],"explanationHi":"मध्य प्रदेश उच्च न्यायालय की दो खंडपीठ (Benches) भी हैं, जो ''इंदौर'' और ''ग्वालियर'' में स्थित हैं। (भोपाल में कोई खंडपीठ नहीं है)।","explanationEn":"The Madhya Pradesh High Court also has two benches, which are located in ''Indore'' and ''Gwalior''. (There is no bench in Bhopal).","memoryTip":"कानून का सबसे ''प्रबल'' (मजबूत) फैसला ''जबल''पुर में होता है।","memoryTipEn":"Jabalpur judges the justice of MP.","related":["Indore Bench","Gwalior Bench","M. Hidayatullah (First Chief Justice of MP)"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AT2VVBB0hMDXZxB7jBPhq', 'General Knowledge', 'सांची का स्तूप किसने बनवाया था?', 'Who built the Sanchi Stupa?', 'सम्राट अशोक', 'Emperor Ashoka', 96, 0, '{"facts":["यह मध्य प्रदेश के रायसेन (Raisen) जिले में स्थित है।","इसे तीसरी शताब्दी ईसा पूर्व (3rd Century BCE) में भगवान बुद्ध के अवशेषों को सुरक्षित रखने के लिए बनवाया गया था।"],"factsEn":["It is located in the Raisen district of Madhya Pradesh.","It was built in the 3rd Century BCE to preserve the relics of Lord Buddha."],"explanationHi":"सांची का स्तूप भारत की सबसे पुरानी पत्थर की संरचनाओं में से एक है। 1989 में इसे यूनेस्को (UNESCO) विश्व धरोहर स्थल का दर्जा दिया गया था। 200 रुपये के नोट पर इसकी तस्वीर है।","explanationEn":"The Sanchi Stupa is one of the oldest stone structures in India. It was granted UNESCO World Heritage status in 1989. Its image is featured on the ₹200 note.","memoryTip":"''अशोक'' ने बुद्ध की ''सच्चाई'' (सांची) को स्तूप में सजाया।","memoryTipEn":"Ashoka sculpted the Sanchi stones.","related":["Raisen District","UNESCO World Heritage Site","Buddhism"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Jdi1-ge5iT6zpLDN2FP1-', 'General Knowledge', 'वीरांगना रानी दुर्गावती की समाधि कहाँ स्थित है?', 'Where is the tomb (samadhi) of brave Queen Durgavati located?', 'जबलपुर (बरेला)', 'Jabalpur (Barela)', 92, 0, '{"facts":["रानी दुर्गावती गोंडवाना साम्राज्य (गढ़ा-मंडला) की एक महान गोंड रानी थीं।","उन्होंने 1564 में अकबर के सेनापति आसफ खान (Asaf Khan) के खिलाफ युद्ध लड़ा था।"],"factsEn":["Rani Durgavati was a great Gond queen of the Gondwana kingdom (Garha-Mandla).","She fought against Akbar''s commander Asaf Khan in 1564."],"explanationHi":"अकबर की विशाल सेना से लड़ते हुए हार सुनिश्चित देखकर उन्होंने अपने ही खंजर (Dagger) से खुद को समाप्त कर लिया था। जबलपुर के बरेला ग्राम में उनकी समाधि है।","explanationEn":"Seeing defeat imminent against Akbar''s massive army, she chose to end her life with her own dagger. Her samadhi is in Barela village, Jabalpur.","memoryTip":"दुर्गावती की वीरता के ''बल'' (जबलपुर) को आज भी याद किया जाता है।","memoryTipEn":"Jabalpur honors the brave Durgavati.","related":["Gondwana Kingdom","Asaf Khan","Rani Durgavati Vishwavidyalaya"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RhOT7QrtNDomugQ2ejdWd', 'General Knowledge', 'संगमरमर की चट्टानों (Marble Rocks) के लिए प्रसिद्ध भेड़ाघाट किस नदी पर स्थित है?', 'Bhedaghat, famous for its Marble Rocks, is situated on which river?', 'नर्मदा', 'Narmada', 95, 0, '{"facts":["भेड़ाघाट मध्य प्रदेश के जबलपुर जिले में स्थित एक विश्व प्रसिद्ध पर्यटन स्थल है।","यहाँ नर्मदा नदी सफेद संगमरमर की ऊंची चट्टानों के बीच से बहती है।"],"factsEn":["Bhedaghat is a world-famous tourist spot located in the Jabalpur district of Madhya Pradesh.","Here, the Narmada River flows between high, white marble rocks."],"explanationHi":"यहीं पर नर्मदा नदी एक सुंदर जलप्रपात बनाती है जिसे ''धुआंधार जलप्रपात'' (Dhuandhar Falls) कहा जाता है, जहाँ पानी गिरने से धुएं जैसा दृश्य बनता है।","explanationEn":"Right here, the Narmada River forms a beautiful waterfall called the ''Dhuandhar Falls'', where the falling water creates a smoke-like visual.","memoryTip":"नर्मदा के किनारे ''भेड़'' (भेड़ाघाट) सफेद ''संगमरमर'' जैसी दिखती हैं।","memoryTipEn":"Narmada navigates the marble rocks.","related":["Dhuandhar Falls","Jabalpur","Chausath Yogini Temple"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('maOOWD3Z4sGMFZXxpm3qV', 'General Knowledge', 'मध्य प्रदेश का कौन सा शहर ''मिनी मुंबई'' के नाम से जाना जाता है?', 'Which city of Madhya Pradesh is known as ''Mini Mumbai''?', 'इंदौर', 'Indore', 93, 0, '{"facts":["इंदौर मध्य प्रदेश का सबसे बड़ा (जनसंख्या में) और वाणिज्यिक (Commercial) शहर है।","यह भारत का एकमात्र शहर है जहाँ IIT (भारतीय प्रौद्योगिकी संस्थान) और IIM (भारतीय प्रबंधन संस्थान) दोनों स्थित हैं।"],"factsEn":["Indore is the largest (by population) and the commercial city of Madhya Pradesh.","It is the only city in India that houses both an IIT and an IIM."],"explanationHi":"अपने तेजी से बढ़ते व्यापार, कपड़ा उद्योग और महानगरीय (Cosmopolitan) जीवन शैली के कारण इसे मिनी मुंबई कहा जाता है। यह लगातार कई वर्षों से भारत का सबसे ''स्वच्छ शहर'' (Cleanest City) भी है।","explanationEn":"Due to its rapidly growing trade, textile industry, and cosmopolitan lifestyle, it is called Mini Mumbai. It has also been India''s ''Cleanest City'' for several consecutive years.","memoryTip":"व्यापार और साफ-सफाई में इंदौर ने एमपी का ''दौर'' (Indore) बदल दिया (मिनी मुंबई)।","memoryTipEn":"Indore is the commercial heart, like Mumbai.","related":["Cleanest City of India","Ahilyabai Holkar","Commercial Capital of MP"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bfbJmWWLQafoZsZvHSL4O', 'General Knowledge', 'मध्य प्रदेश के किस शहर को ''संस्कार राजधानी'' (Cultural Capital) कहा जाता है?', 'Which city of Madhya Pradesh is called the ''Cultural Capital'' (Sanskar Dhani)?', 'जबलपुर', 'Jabalpur', 91, 0, '{"facts":["यह नाम प्रसिद्ध समाज सुधारक ''विनोबा भावे'' (Vinoba Bhave) ने दिया था।","जबलपुर मध्य प्रदेश का एक प्रमुख शिक्षा और सैन्य (Cantonment) केंद्र है।"],"factsEn":["This name was coined by the famous social reformer ''Vinoba Bhave''.","Jabalpur is a major educational and military (cantonment) hub of Madhya Pradesh."],"explanationHi":"जबलपुर अपने सांस्कृतिक और बौद्धिक माहौल के लिए जाना जाता है। (उज्जैन को ''धार्मिक राजधानी'' और इंदौर को ''वाणिज्यिक राजधानी'' कहा जाता है)।","explanationEn":"Jabalpur is known for its cultural and intellectual environment. (Ujjain is called the ''Religious Capital'' and Indore the ''Commercial Capital'').","memoryTip":"जबलपुर के लोगों में बहुत ''बल'' और ''संस्कार'' हैं।","memoryTipEn":"Jabalpur judges culture and law (High court).","related":["Vinoba Bhave","High Court of MP","Bhedaghat"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bC3G6fS8S7rk9aMndM2ec', 'General Knowledge', 'भीमबेटका की गुफाएँ (Bhimbetka Caves) किसके लिए प्रसिद्ध हैं?', 'What are the Bhimbetka Caves famous for?', 'शैलचित्रों (Rock Paintings) के लिए', 'Rock Paintings (Prehistoric Cave Art)', 96, 0, '{"facts":["यह मध्य प्रदेश के रायसेन (Raisen) जिले में स्थित है।","इसकी खोज 1957 में प्रसिद्ध पुरातत्वविद् ''वी. एस. वाकणकर'' (V.S. Wakankar) ने की थी।"],"factsEn":["It is located in the Raisen district of Madhya Pradesh.","It was discovered in 1957 by famous archaeologist ''V.S. Wakankar''."],"explanationHi":"यहाँ पुरापाषाण काल (Paleolithic) से लेकर मध्यपाषाण काल (Mesolithic) तक के गुफा चित्र मिलते हैं, जो मानव विकास के सबसे शुरुआती निशानों में से एक हैं। 2003 में इसे यूनेस्को विश्व धरोहर स्थल घोषित किया गया।","explanationEn":"It contains cave paintings from the Paleolithic to the Mesolithic periods, representing some of the earliest traces of human evolution. It was declared a UNESCO World Heritage Site in 2003.","memoryTip":"''भीम'' की बैठक (भीमबेटका) में पुराने जमाने की ''पेंटिंग'' लगी है।","memoryTipEn":"Bhimbetka boasts ancient rock brushes.","related":["V.S. Wakankar","UNESCO World Heritage Site","Raisen District"]}', 'published', 1776086988, 1776086988);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('58-bmrE5yHeL8PV9YRMEH', 'General Knowledge', 'मध्य प्रदेश पुलिस का ध्येय वाक्य (Motto) क्या है?', 'What is the motto of the Madhya Pradesh Police?', 'देशभक्ति - जनसेवा', 'Deshbhakti - Janseva (Patriotism - Public Service)', 100, 0, '{"facts":["यह ध्येय वाक्य मध्य प्रदेश पुलिस के लोगो (Logo) पर भी अंकित है।","मध्य प्रदेश पुलिस की स्थापना राज्य के गठन (1956) के साथ ही हुई थी।"],"factsEn":["This motto is also inscribed on the logo of Madhya Pradesh Police.","MP Police was established alongside the formation of the state in 1956."],"explanationHi":"यह वाक्य पुलिस बल को राष्ट्र के प्रति समर्पण और आम जनता की सेवा करने के उनके मूल कर्तव्य की याद दिलाता है।","explanationEn":"This phrase reminds the police force of their core duty of dedication to the nation and service to the common people.","memoryTip":"पुलिस का काम: पहले देश (देशभक्ति), फिर जनता (जनसेवा)।","memoryTipEn":"Patriotism first, Public Service always.","related":["MP Police Foundation Day","DGP of MP","Police Headquarters Bhopal"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RkYyUCP_sagdplgCIJnJy', 'General Knowledge', 'मध्य प्रदेश के प्रथम पुलिस महानिरीक्षक (IG) कौन थे?', 'Who was the first Inspector General (IG) of Madhya Pradesh Police?', 'बी. जी. घाटे (B. G. Ghate)', 'B. G. Ghate', 95, 0, '{"facts":["1956 में राज्य गठन के समय पुलिस का सर्वोच्च पद महानिरीक्षक (IG) होता था।","1982 में सर्वोच्च पद को पुलिस महानिदेशक (DGP) कर दिया गया।"],"factsEn":["At the time of state formation in 1956, IG was the highest post in the police.","In 1982, the highest post was upgraded to Director General of Police (DGP)."],"explanationHi":"बी.जी. घाटे ने नवगठित मध्य प्रदेश में विभिन्न क्षेत्रों की पुलिस व्यवस्था को एकीकृत करने में महत्वपूर्ण भूमिका निभाई।","explanationEn":"B.G. Ghate played a crucial role in integrating the police systems of various regions in the newly formed MP.","memoryTip":"एमपी पुलिस ने शुरुआत में दुश्मनों को ''घाटे'' (Ghate) में डाल दिया।","memoryTipEn":"Ghate guarded the state first.","related":["First DGP V. P. Dubey","MP Police History"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('m5nOd0yMXRtW4KpNv_0Rx', 'General Knowledge', 'मध्य प्रदेश के प्रथम पुलिस महानिदेशक (DGP) कौन थे?', 'Who was the first Director General of Police (DGP) of Madhya Pradesh?', 'वी. पी. दुबे (V. P. Dubey)', 'V. P. Dubey', 96, 0, '{"facts":["1982 में मध्य प्रदेश पुलिस में DGP का पद सृजित किया गया था।","DGP राज्य पुलिस बल का प्रशासनिक और परिचालन प्रमुख होता है।"],"factsEn":["The post of DGP was created in the MP Police in 1982.","The DGP is the administrative and operational head of the state police force."],"explanationHi":"वी.पी. दुबे के कार्यकाल से मध्य प्रदेश पुलिस का आधुनिकीकरण और पुनर्गठन शुरू हुआ।","explanationEn":"The modernization and reorganization of the MP Police began during the tenure of V.P. Dubey.","memoryTip":"पुलिस में ''डूब'' (Dubey) कर जनसेवा करने वाले पहले DGP।","memoryTipEn":"Dubey directed the police first.","related":["B. G. Ghate (First IG)","Police Headquarters Bhopal"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aJ310Tm5aoy1fRARu_wTY', 'General Knowledge', 'मध्य प्रदेश पुलिस अकादमी (MP Police Academy) कहाँ स्थित है?', 'Where is the MP Police Academy located?', 'भौरी (भोपाल)', 'Bhauri (Bhopal)', 94, 0, '{"facts":["यहाँ उप पुलिस अधीक्षक (DSP) और उप-निरीक्षक (Sub-Inspector) स्तर के अधिकारियों को प्रशिक्षित किया जाता है।","जवाहरलाल नेहरू पुलिस अकादमी सागर में स्थित है।"],"factsEn":["Officers of Deputy Superintendent of Police (DSP) and Sub-Inspector levels are trained here.","Jawaharlal Nehru Police Academy is located in Sagar."],"explanationHi":"भौरी में स्थित यह नई और अत्याधुनिक अकादमी पुलिस बल को उन्नत अपराध जांच और कानून व्यवस्था का प्रशिक्षण देती है।","explanationEn":"Located in Bhauri, this new, state-of-the-art academy trains the police force in advanced crime investigation and law and order.","memoryTip":"पुलिस ट्रेनिंग से अपराधी ''भौंचक्के'' (भौरी) रह जाते हैं।","memoryTipEn":"Bhauri builds the best cops.","related":["JNPA Sagar","Police Training School (PTS)"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('A0qG_yfTHGBgxRhlQ6mtv', 'General Knowledge', 'मध्य प्रदेश का प्रथम ''ISO प्रमाणित'' थाना कौनसा है?', 'Which is the first ''ISO Certified'' police station in Madhya Pradesh?', 'देवास (कोतवाली)', 'Dewas (Kotwali)', 92, 0, '{"facts":["इसे अपनी बेहतरीन कार्यप्रणाली और रिकॉर्ड प्रबंधन के लिए ISO 9001 प्रमाण पत्र मिला।","देवास बैंक नोट प्रेस के लिए भी जाना जाता है।"],"factsEn":["It received the ISO 9001 certification for its excellent functioning and record management.","Dewas is also known for the Bank Note Press."],"explanationHi":"ISO प्रमाणन का मतलब है कि थाना अंतरराष्ट्रीय मानकों के अनुसार जन-सुविधाएं और गुणवत्तापूर्ण सेवाएं दे रहा है।","explanationEn":"ISO certification means the police station is providing public facilities and quality services according to international standards.","memoryTip":"''देवों'' (देवास) के थाने को सबसे पहले ISO सर्टिफिकेट मिला।","memoryTipEn":"Dewas sets the standard (ISO).","related":["ISO 9001","MP Police Innovations"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nP2IUe6a_FNqR2pZ_Qqyy', 'General Knowledge', 'मध्य प्रदेश का क्षेत्रफल भारत के कुल क्षेत्रफल का कितने प्रतिशत है?', 'What is the percentage of Madhya Pradesh''s area to the total area of India?', '9.38%', '9.38%', 95, 0, '{"facts":["मध्य प्रदेश का कुल क्षेत्रफल 3,08,252 वर्ग किलोमीटर है।","यह राजस्थान (10.4%) के बाद भारत का दूसरा सबसे बड़ा राज्य है।"],"factsEn":["The total area of Madhya Pradesh is 3,08,252 square kilometers.","It is the second-largest state in India after Rajasthan (10.4%)."],"explanationHi":"विभाजन (2000) से पहले मध्य प्रदेश भारत का सबसे बड़ा राज्य था, जो देश के लगभग 13.43% हिस्से को कवर करता था।","explanationEn":"Before partition (2000), MP was the largest state in India, covering about 13.43% of the country''s area.","memoryTip":"9 के बाद 3, और 3 का 8 (9.38)।","memoryTipEn":"9 point 3 8 covers the state.","related":["Area of MP","Rajasthan","Chhattisgarh Partition"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mpIZ0r0T9UeFecQKYp_Jf', 'General Knowledge', 'मध्य प्रदेश की सबसे बड़ी जनजाति कौनसी है?', 'Which is the largest tribe in Madhya Pradesh?', 'भील (Bhil)', 'Bhil', 98, 0, '{"facts":["भील जनजाति मुख्य रूप से पश्चिमी मध्य प्रदेश (झाबुआ, अलीराजपुर, धार, बड़वानी) में पाई जाती है।","गोंड (Gond) मध्य प्रदेश की दूसरी सबसे बड़ी जनजाति है।"],"factsEn":["The Bhil tribe is mainly found in western MP (Jhabua, Alirajpur, Dhar, Barwani).","Gond is the second-largest tribe in Madhya Pradesh."],"explanationHi":"भील शब्द की उत्पत्ति ''बिल्लू'' से हुई है जिसका अर्थ ''धनुष'' होता है। भगोरिया (Bhagoria) इनका प्रमुख और प्रसिद्ध त्योहार है।","explanationEn":"The word Bhil originates from ''Billu'', meaning ''bow''. Bhagoria is their major and famous festival.","memoryTip":"एमपी के पश्चिम में ''भील'' अपने धनुष के साथ रहते हैं।","memoryTipEn":"Bhils bow to the west of MP.","related":["Bhagoria Haat","Jhabua","Gond Tribe"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BtaL2Zv9FEumzEaldJNWF', 'General Knowledge', 'उज्जैन का प्राचीन नाम क्या था?', 'What was the ancient name of Ujjain?', 'अवन्तिका (Avantika)', 'Avantika', 93, 0, '{"facts":["यह 16 महाजनपदों में से एक ''अवंति'' की राजधानी थी।","यहाँ राजा विक्रमादित्य ने शासन किया था।"],"factsEn":["It was the capital of ''Avanti'', one of the 16 Mahajanapadas.","King Vikramaditya ruled here."],"explanationHi":"प्राचीन काल से ही यह शहर खगोल विज्ञान, शिक्षा और व्यापार का एक महत्वपूर्ण केंद्र रहा है। महाकालेश्वर मंदिर यहाँ की पहचान है।","explanationEn":"Since ancient times, it has been an important center of astronomy, education, and trade. The Mahakaleshwar temple is its hallmark.","memoryTip":"महाकाल की नगरी पहले ''अवंतिका'' कहलाती थी।","memoryTipEn":"Avantika aged into Ujjain.","related":["Mahajanapada","King Vikramaditya","Mahakaleshwar"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gtjXbfamazdnKFHuKUgw7', 'General Knowledge', 'मध्य प्रदेश का प्रथम ''बायोस्फीयर रिजर्व'' (Biosphere Reserve) कौनसा है?', 'Which is the first Biosphere Reserve of Madhya Pradesh?', 'पचमढ़ी (Pachmarhi)', 'Pachmarhi', 94, 0, '{"facts":["इसे 1999 में भारत सरकार द्वारा बायोस्फीयर रिजर्व घोषित किया गया था।","2009 में इसे यूनेस्को (UNESCO) के ''मैन एंड बायोस्फीयर'' (MAB) प्रोग्राम में शामिल किया गया।"],"factsEn":["It was declared a Biosphere Reserve by the Govt of India in 1999.","In 2009, it was included in UNESCO''s Man and the Biosphere (MAB) program."],"explanationHi":"सतपुड़ा पहाड़ियों में स्थित पचमढ़ी अपनी अनूठी वनस्पतियों और जीवों (जैव विविधता) के लिए जाना जाता है।","explanationEn":"Located in the Satpura hills, Pachmarhi is known for its unique flora and fauna (biodiversity).","memoryTip":"प्रकृति के ''पांच'' (पच) रंग पचमढ़ी के रिज़र्व में दिखते हैं।","memoryTipEn":"Pachmarhi protects pristine nature.","related":["Achanakmar-Amarkantak","Panna Biosphere Reserve","Satpura National Park"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('79ZvDVmUEXi4L_PRyi_CY', 'General Knowledge', 'बाघ की गुफाएं (Bagh Caves) मध्य प्रदेश के किस जिले में स्थित हैं?', 'In which district of Madhya Pradesh are the Bagh Caves located?', 'धार (Dhar)', 'Dhar', 91, 0, '{"facts":["ये गुफाएं बाघिनी (Baghini) नदी के तट पर स्थित हैं।","इन गुफाओं की वास्तुकला और भित्तिचित्र (Mural paintings) अजंता की गुफाओं के समान हैं।"],"factsEn":["These caves are situated on the banks of the Baghini river.","The architecture and mural paintings of these caves are similar to the Ajanta caves."],"explanationHi":"ये 9 रॉक-कट (चट्टान काटकर बनाई गई) बौद्ध गुफाएं हैं, जो 5वीं-6वीं शताब्दी के दौरान बनाई गई थीं।","explanationEn":"These are 9 rock-cut Buddhist caves, created during the 5th-6th century.","memoryTip":"धार (तेज़ हथियार) से काटकर ''बाघ'' की गुफाएं बनाई गईं।","memoryTipEn":"Dhar hides the Bagh (Tiger) caves.","related":["Bagh Prints","Ajanta Caves","Buddhist Rock-cut Architecture"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nmJHKgI_pJVsBI1r7bNrd', 'General Knowledge', 'मध्य प्रदेश की पहली खुली जेल (Open Prison) कहाँ स्थापित की गई थी?', 'Where was the first Open Prison established in Madhya Pradesh?', 'मुंगावली (अशोकनगर)', 'Mungaoli (Ashoknagar)', 88, 0, '{"facts":["इसकी स्थापना 1973 में ''नवजीवन शिविर'' के रूप में की गई थी।","इसका उद्देश्य चंबल के आत्मसमर्पण करने वाले डकैतों को समाज की मुख्यधारा में वापस लाना था।"],"factsEn":["It was established in 1973 as ''Navjeevan Shivir''.","Its objective was to bring surrendered dacoits of Chambal back into the mainstream of society."],"explanationHi":"खुली जेल की अवधारणा कैदियों को सलाखों के बिना एक सामान्य जीवन जीने और सुधार करने का अवसर देती है।","explanationEn":"The concept of an open prison gives inmates the opportunity to live a normal life without bars and to reform themselves.","memoryTip":"''मुंगावली'' में डाकुओं का ''नवजीवन'' शुरू हुआ।","memoryTipEn":"Mungaoli opened its doors to reform.","related":["Navjeevan Shivir","Hoshangabad Open Jail","Ashoknagar"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('45caYALlHP9R_p8PwxWhT', 'General Knowledge', 'मध्य प्रदेश की प्रथम ''पर्यटन नगरी'' (Tourist City) का दर्जा किसे प्राप्त है?', 'Which city holds the status of the first ''Tourist City'' of Madhya Pradesh?', 'शिवपुरी', 'Shivpuri', 90, 0, '{"facts":["शिवपुरी ग्वालियर के सिंधिया राजवंश की ग्रीष्मकालीन राजधानी (Summer Capital) हुआ करती थी।","माधव राष्ट्रीय उद्यान (Madhav National Park) यहीं स्थित है।"],"factsEn":["Shivpuri used to be the summer capital of the Scindia dynasty of Gwalior.","Madhav National Park is located here."],"explanationHi":"अपनी झीलों (जैसे सांख्य सागर), जंगलों और ऐतिहासिक छतरियों (Cenotaphs) के कारण इसे पर्यटन नगरी का दर्जा दिया गया है।","explanationEn":"Due to its lakes (like Sankhya Sagar), forests, and historical Cenotaphs (Chhatris), it was granted the status of a tourist city.","memoryTip":"''शिव'' की नगरी (शिवपुरी) में पर्यटक सबसे पहले जाते हैं।","memoryTipEn":"Shivpuri showcases Scindia''s summer.","related":["Madhav National Park","Scindia Chhatris","George Castle"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AzUFA8gcFxF74AYIkMta5', 'General Knowledge', 'चंदेरी की साड़ियाँ (Chanderi Sarees) मध्य प्रदेश के किस जिले से संबंधित हैं?', 'Chanderi Sarees are associated with which district of Madhya Pradesh?', 'अशोकनगर', 'Ashoknagar', 93, 0, '{"facts":["चंदेरी साड़ियाँ रेशम और सूती धागों की बारीक बुनाई (Handloom) के लिए विश्व प्रसिद्ध हैं।","इन्हें भारत सरकार द्वारा ''भौगोलिक संकेत'' (Geographical Indication - GI Tag) मिला हुआ है।"],"factsEn":["Chanderi sarees are world-famous for their fine handloom weaving of silk and cotton threads.","They have been granted a ''Geographical Indication'' (GI Tag) by the Govt of India."],"explanationHi":"चंदेरी का इतिहास महाभारत काल (शिशुपाल की राजधानी) से जुड़ा हुआ है। यहाँ का ''चंदेरी का किला'' भी बहुत प्रसिद्ध है।","explanationEn":"Chanderi''s history is linked to the Mahabharata era (capital of Shishupala). The ''Chanderi Fort'' here is also very famous.","memoryTip":"अशोक की नगरी (अशोकनगर) की ''चंदेरी'' साड़ियाँ।","memoryTipEn":"Chanderi weaves Ashoknagar''s pride.","related":["Maheshwari Sarees","GI Tag","Chanderi Fort"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('w5re6zorHzuaRhm3KZEsk', 'General Knowledge', 'ताप्ती नदी (Tapti River) का उद्गम स्थल मध्य प्रदेश में कहाँ है?', 'Where is the origin of the Tapti River located in Madhya Pradesh?', 'मुलताई (बैतूल जिला)', 'Multai (Betul district)', 95, 0, '{"facts":["ताप्ती नदी नर्मदा की तरह पूर्व से पश्चिम की ओर बहती है और खंभात की खाड़ी में गिरती है।","इसे ''सूर्य की पुत्री'' (Daughter of Sun) भी कहा जाता है।"],"factsEn":["Like the Narmada, the Tapti River flows from east to west and empties into the Gulf of Khambhat.","It is also known as the ''Daughter of the Sun''."],"explanationHi":"यह मध्य प्रदेश और महाराष्ट्र के बीच एक प्राकृतिक सीमा बनाती है। सूरत शहर ताप्ती नदी के मुहाने पर ही बसा है।","explanationEn":"It forms a natural boundary between Madhya Pradesh and Maharashtra. The city of Surat is situated near its mouth.","memoryTip":"सूर्य की ''तपन'' (ताप्ती) ''मुलताई'' से निकलती है।","memoryTipEn":"Tapti starts from the Multai mountains.","related":["West Flowing Rivers","Narmada River","Surat"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0CakDzLvZ1xoZ4XVH3re8', 'General Knowledge', 'जैन तीर्थस्थल ''बावनगजा'' (Bawangaja) मध्य प्रदेश के किस जिले में है?', 'The Jain pilgrimage site ''Bawangaja'' is located in which district of Madhya Pradesh?', 'बड़वानी (Barwani)', 'Barwani', 89, 0, '{"facts":["यह सतपुड़ा पर्वत श्रृंखला में स्थित है।","यहाँ भगवान आदिनाथ (ऋषभदेव) की 84 फीट (52 गज़) ऊँची भव्य चट्टान काटकर बनाई गई मूर्ति है।"],"factsEn":["It is situated in the Satpura mountain range.","It features an 84-foot (52 yards) tall magnificent rock-cut statue of Lord Adinath (Rishabhanatha)."],"explanationHi":"चूंकि मूर्ति की ऊंचाई 52 (बावन) गज है, इसलिए इस स्थान का नाम ''बावनगजा'' पड़ गया। यह जैनियों के लिए एक पवित्र स्थल है।","explanationEn":"Since the height of the statue is 52 (Bawan) Gaj (yards), the place is named ''Bawangaja''. It is a sacred site for Jains.","memoryTip":"''बावन'' (52) गज की मूर्ति ''बड़वानी'' में है।","memoryTipEn":"Barwani holds the Bawangaja giant.","related":["Lord Adinath","Jain Pilgrimage","Satpura Range"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CC6vH69U5R0L-GC93BF5S', 'General Knowledge', 'पातालपानी जलप्रपात (Patalpani Waterfall) कहाँ स्थित है?', 'Where is the Patalpani Waterfall located?', 'इंदौर (महु के पास)', 'Indore (near Mhow)', 90, 0, '{"facts":["यह चोरल नदी (Choral River) पर स्थित है।","स्थानीय किंवदंती है कि यहाँ पानी का कुंड इतना गहरा है कि यह सीधे ''पाताल'' (Underworld) तक जाता है।"],"factsEn":["It is located on the Choral River.","Local legend says the pool here is so deep that it reaches straight to the ''Underworld'' (Patal)."],"explanationHi":"यह एक प्रसिद्ध पिकनिक स्पॉट और हेरिटेज ट्रेन मार्ग है। हाल ही में इस रेलवे स्टेशन का नाम आदिवासी नायक ''टंट्या भील'' के नाम पर रखा गया है।","explanationEn":"It is a famous picnic spot and heritage train route. The railway station was recently renamed after tribal hero ''Tantya Bhil''.","memoryTip":"इंदौर का पानी सीधे ''पाताल'' (पातालपानी) में जाता है।","memoryTipEn":"Patalpani plunges near Indore.","related":["Choral River","Tantya Bhil","Mhow"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RFLlq46kwfn-TXBWUDdhP', 'General Knowledge', 'ग्वालियर स्थित ''जय विलास महल'' (Jai Vilas Palace) का निर्माण किसने करवाया था?', 'Who built the ''Jai Vilas Palace'' located in Gwalior?', 'महाराजा जयाजीराव सिंधिया', 'Maharaja Jayajirao Scindia', 91, 0, '{"facts":["इसका निर्माण 1874 में ब्रिटेन के किंग एडवर्ड VII (तत्कालीन प्रिंस ऑफ वेल्स) के स्वागत के लिए किया गया था।","यह इटालियन, टस्कन और कोरिंथियन वास्तुकला का मिश्रण है।"],"factsEn":["It was built in 1874 to welcome King Edward VII (then Prince of Wales) of Britain.","It is a blend of Italian, Tuscan, and Corinthian architecture."],"explanationHi":"महल का दरबार हॉल दुनिया के सबसे बड़े झूमरों (Chandeliers) और डाइनिंग टेबल पर चलने वाली चाँदी की ट्रेन (Silver Train) के लिए प्रसिद्ध है।","explanationEn":"The Durbar Hall of the palace is famous for some of the world''s largest chandeliers and a silver train that runs along the dining table.","memoryTip":"''जय'' विलास महल को ''जयाजीराव'' ने बनवाया।","memoryTipEn":"Jayajirao brought joy to Jai Vilas.","related":["Scindia Dynasty","Gwalior","European Architecture"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bdraaHN_GDAlJsXTb6kpI', 'General Knowledge', 'मध्य प्रदेश का पहला मेडिकल कॉलेज कौनसा है?', 'Which is the first Medical College of Madhya Pradesh?', 'गजरा राजा मेडिकल कॉलेज, ग्वालियर', 'Gajra Raja Medical College, Gwalior', 89, 0, '{"facts":["इसकी स्थापना 1946 में हुई थी।","इसका उद्घाटन तत्कालीन जीवाजीराव सिंधिया द्वारा अपनी माता ''गजरा राजा'' की स्मृति में किया गया था।"],"factsEn":["It was established in 1946.","It was inaugurated by the then Jiwajirao Scindia in memory of his mother ''Gajra Raja''."],"explanationHi":"यह मध्य प्रदेश का सबसे पुराना और 11वां भारतीय मेडिकल कॉलेज है, जो चिकित्सा शिक्षा के क्षेत्र में राज्य का अग्रणी संस्थान है।","explanationEn":"It is the oldest medical college in MP and the 11th in India, being a pioneering institute in medical education in the state.","memoryTip":"ग्वालियर में ''राजा'' की तरह सबसे पहले मेडिकल कॉलेज खुला।","memoryTipEn":"Gajra Raja started medical history in MP.","related":["Gwalior","Jiwajirao Scindia","Medical Education in MP"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('fwemJ3RzhPbeV-JlmouYp', 'General Knowledge', 'एशिया का सबसे बड़ा और पहला ''लेजर किरण परमाणु ऊर्जा अनुसंधान केंद्र'' मध्य प्रदेश में कहाँ है?', 'Where is Asia''s largest and first ''Laser Beam Atomic Energy Research Centre'' located in MP?', 'इंदौर (RRCAT)', 'Indore (RRCAT)', 92, 0, '{"facts":["इसका नाम ''राजा रमन्ना प्रगत प्रौद्योगिकी केन्द्र'' (Raja Ramanna Centre for Advanced Technology - RRCAT) है।","इसकी स्थापना 1984 में भारत के परमाणु ऊर्जा विभाग द्वारा की गई थी।"],"factsEn":["Its name is ''Raja Ramanna Centre for Advanced Technology'' (RRCAT).","It was established in 1984 by the Department of Atomic Energy, India."],"explanationHi":"यह लेजर, कण त्वरक (Particle accelerators), और क्रायोजेनिक्स जैसे उन्नत वैज्ञानिक क्षेत्रों में अनुसंधान और विकास करता है।","explanationEn":"It conducts research and development in advanced scientific fields like lasers, particle accelerators, and cryogenics.","memoryTip":"इंदौर के कैट (CAT) में लेजर की रोशनी चमकती है।","memoryTipEn":"Indore illuminates with lasers at RRCAT.","related":["Department of Atomic Energy","Raja Ramanna","Particle Accelerators"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vDG7pIh-2vX3JFVbycYDu', 'General Knowledge', 'मध्य प्रदेश का प्रथम ''सौर ऊर्जा ग्राम'' (Solar Village) कौनसा है?', 'Which is the first ''Solar Village'' of Madhya Pradesh?', 'कस्तूरबा ग्राम (इंदौर)', 'Kasturba Gram (Indore)', 88, 0, '{"facts":["कस्तूरबा ग्राम इंदौर के बाहरी इलाके में स्थित है।","यह पूरी तरह से सौर ऊर्जा से विद्युतीकृत होने वाला राज्य का पहला गांव था।"],"factsEn":["Kasturba Gram is located on the outskirts of Indore.","It was the first village in the state to be fully electrified by solar energy."],"explanationHi":"यह गांव पर्यावरण के अनुकूल जीवन और ग्रामीण सशक्तिकरण (विशेषकर महिलाओं के लिए) का एक शानदार उदाहरण है, जिसे महात्मा गांधी के आदर्शों पर बसाया गया था।","explanationEn":"This village is a prime example of eco-friendly living and rural empowerment (especially for women), built on the ideals of Mahatma Gandhi.","memoryTip":"बापू की पत्नी (कस्तूरबा) के नाम वाले गाँव में सूरज की रोशनी से बिजली बनती है।","memoryTipEn":"Kasturba shines bright with solar light.","related":["Renewable Energy","Indore","Rural Electrification"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('f9NqYT2-tVBQLNeFZhxkT', 'General Knowledge', '''ऐशबाग स्टेडियम'' (Aishbagh Stadium) मध्य प्रदेश में कहाँ स्थित है?', 'Where is ''Aishbagh Stadium'' located in Madhya Pradesh?', 'भोपाल', 'Bhopal', 90, 0, '{"facts":["यह मुख्य रूप से एक फील्ड हॉकी (Field Hockey) स्टेडियम है।","यहाँ प्रसिद्ध ''ओबैदुल्ला खान गोल्ड कप'' (Obaidullah Khan Gold Cup) हॉकी टूर्नामेंट आयोजित किया जाता है।"],"factsEn":["It is primarily a Field Hockey stadium.","The famous ''Obaidullah Khan Gold Cup'' hockey tournament is held here."],"explanationHi":"भोपाल को ऐतिहासिक रूप से भारत की ''हॉकी नर्सरी'' माना जाता है, और ऐशबाग स्टेडियम ने कई अंतरराष्ट्रीय हॉकी मैच देखे हैं।","explanationEn":"Bhopal is historically considered a ''Hockey Nursery'' of India, and Aishbagh Stadium has witnessed many international hockey matches.","memoryTip":"भोपाल के नवाब ''ऐश'' (ऐशबाग) से हॉकी खेलते थे।","memoryTipEn":"Aishbagh aims for the hockey goal in Bhopal.","related":["Obaidullah Khan Gold Cup","Tatya Tope Stadium (Bhopal)","Roop Singh Stadium (Gwalior)"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZHJfRP3yXlZff6RKSzTZd', 'General Science', 'मानव रक्त का pH मान (pH Value) कितना होता है?', 'What is the pH value of human blood?', '7.4 (हल्का क्षारीय)', '7.4 (Slightly Basic/Alkaline)', 97, 0, '{"facts":["pH पैमाना 0 से 14 तक होता है (7 तटस्थ/Neutral है)।","यदि रक्त का pH 7.35 से कम या 7.45 से अधिक हो जाता है, तो यह जानलेवा हो सकता है।"],"factsEn":["The pH scale ranges from 0 to 14 (7 is Neutral).","If blood pH drops below 7.35 or rises above 7.45, it can be fatal."],"explanationHi":"हमारा शरीर बफर सिस्टम (Buffer system) और फेफड़ों/किडनी के माध्यम से इस 7.4 के बहुत ही संकीर्ण pH स्तर को सख्ती से बनाए रखता है।","explanationEn":"Our body strictly maintains this very narrow pH level of 7.4 through buffer systems and the lungs/kidneys.","memoryTip":"सप्ताह के 7 दिन, 4 दिशाओं में खून दौड़ता है (7.4)।","memoryTipEn":"7 point 4 keeps the body core.","related":["Acid-Base Balance","Buffer Solution","Homeostasis"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('X4hDWnqatUue9KjnDEH_Y', 'General Knowledge', 'संविधान का ''अनुच्छेद 32'' (Article 32) किसे संदर्भित करता है?', 'What does ''Article 32'' of the Constitution refer to?', 'संवैधानिक उपचारों का अधिकार', 'Right to Constitutional Remedies', 99, 0, '{"facts":["डॉ. बी.आर. अंबेडकर ने इसे ''संविधान का हृदय और आत्मा'' (Heart and Soul of the Constitution) कहा था।","यह सर्वोच्च न्यायालय को मौलिक अधिकारों को लागू करने के लिए ''रिट'' (Writs) जारी करने की शक्ति देता है।"],"factsEn":["Dr. B.R. Ambedkar called it the ''Heart and Soul of the Constitution''.","It empowers the Supreme Court to issue ''Writs'' to enforce Fundamental Rights."],"explanationHi":"यदि किसी नागरिक के मौलिक अधिकारों का उल्लंघन होता है, तो वह अनुच्छेद 32 के तहत सीधे भारत के सर्वोच्च न्यायालय का दरवाजा खटखटा सकता है।","explanationEn":"If a citizen''s fundamental rights are violated, they can directly approach the Supreme Court of India under Article 32.","memoryTip":"32 नंबर का अनुच्छेद संविधान की ''आत्मा'' है।","memoryTipEn":"Article 32 fixes the fundamental breach.","related":["Writs (Habeas Corpus, Mandamus, etc.)","Dr. B.R. Ambedkar","Article 226 (High Court Writs)"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('sRMRRK9Z-OiTr0V9k-cg6', 'General Science', 'प्रकृति में पाया जाने वाला सबसे भारी तत्व (Heaviest naturally occurring element) कौनसा है?', 'Which is the heaviest naturally occurring element in nature?', 'यूरेनियम (Uranium)', 'Uranium', 93, 0, '{"facts":["यूरेनियम का परमाणु क्रमांक (Atomic number) 92 है।","यह एक अत्यधिक रेडियोधर्मी (Radioactive) धातु है।"],"factsEn":["The atomic number of Uranium is 92.","It is a highly radioactive metal."],"explanationHi":"ऑस्मियम और इरिडियम सबसे अधिक ''घनत्व'' (Densely) वाले तत्व हैं, लेकिन उच्चतम परमाणु भार के साथ प्राकृतिक रूप से पाया जाने वाला तत्व यूरेनियम ही है, जिसका उपयोग परमाणु रिएक्टरों में ईंधन के रूप में होता है।","explanationEn":"Osmium and Iridium are the most ''dense'' elements, but Uranium is the heaviest naturally occurring element by atomic weight, used as fuel in nuclear reactors.","memoryTip":"सबसे ''भारी'' तत्व ''यूरेनियम'' बम में गिरता है।","memoryTipEn":"Uranium is the ultimate heavy metal.","related":["Nuclear Fission","Radioactivity","Atomic Number 92"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wNWkU2PXOv0QoPjgp6Vp6', 'General Knowledge', 'मांडू (Mandu) मध्य प्रदेश के किस जिले में स्थित है?', 'Mandu is located in which district of Madhya Pradesh?', 'धार (Dhar)', 'Dhar', 95, 0, '{"facts":["मांडू को ''सिटी ऑफ जॉय'' (City of Joy - आनंद की नगरी) भी कहा जाता है।","यह बाज बहादुर और रानी रूपमती की ऐतिहासिक प्रेम कहानी के लिए प्रसिद्ध है।"],"factsEn":["Mandu is also called the ''City of Joy''.","It is famous for the historical love story of Baz Bahadur and Rani Roopmati."],"explanationHi":"यह विंध्य पर्वतमाला पर स्थित एक प्राचीन किला शहर है। यहाँ जहाज महल, हिंडोला महल और होशंग शाह का मकबरा (भारत की पहली संगमरमर संरचना) जैसी बेहतरीन अफगान वास्तुकला है।","explanationEn":"It is an ancient fort city on the Vindhya range. It boasts fine Afghan architecture like Jahaz Mahal, Hindola Mahal, and Hoshang Shah''s Tomb (India''s first marble structure).","memoryTip":"धार के किनारे ''मांडू'' में आनंद (Joy) आता है।","memoryTipEn":"Mandu is the joy of Dhar.","related":["Jahaz Mahal","Rani Roopmati Pavilion","Hoshang Shah''s Tomb"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('J2Q4vFf-eGO9MoJgI8-87', 'General Knowledge', 'मध्य प्रदेश की पहली और भारत की तीसरी ''वंदे भारत एक्सप्रेस'' किन स्टेशनों के बीच चली?', 'Madhya Pradesh''s first and India''s third ''Vande Bharat Express'' ran between which stations?', 'रानी कमलापति (भोपाल) से नई दिल्ली', 'Rani Kamlapati (Bhopal) to New Delhi', 92, 0, '{"facts":["रानी कमलापति रेलवे स्टेशन (पहले हबीबगंज) भारत का पहला विश्व स्तरीय (World-class) रेलवे स्टेशन है।","इस ट्रेन को 1 अप्रैल 2023 को हरी झंडी दिखाई गई थी।"],"factsEn":["Rani Kamlapati Railway Station (formerly Habibganj) is India''s first world-class railway station.","This train was flagged off on April 1, 2023."],"explanationHi":"वंदे भारत एक्सप्रेस भारत की पहली स्वदेशी रूप से विकसित इंजन-रहित (Engine-less) हाई-स्पीड ट्रेन (Train 18) है।","explanationEn":"Vande Bharat Express is India''s first indigenously developed engine-less high-speed train (Train 18).","memoryTip":"''रानी'' के स्टेशन से ''वंदे भारत'' ने दौड़ लगाई।","memoryTipEn":"Vande Bharat raced from Rani''s realm.","related":["Train 18","Rani Kamlapati Station","Indian Railways"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_jArvpMEa2IigUNheAJJ4', 'General Knowledge', 'मध्य प्रदेश का ''कान्हा राष्ट्रीय उद्यान'' किस जानवर के संरक्षण के लिए सबसे अधिक प्रसिद्ध है?', 'Madhya Pradesh''s ''Kanha National Park'' is most famous for the conservation of which animal?', 'बाघ (Tiger) और बारहसिंगा (Swamp Deer)', 'Tiger and Barasingha (Swamp Deer)', 96, 0, '{"facts":["कान्हा को विशेष रूप से हार्ड ग्राउंड ''बारहसिंगा'' को विलुप्त होने से बचाने का श्रेय दिया जाता है।","रुडयार्ड किपलिंग की प्रसिद्ध ''द जंगल बुक'' (The Jungle Book) के लिए प्रेरणा कान्हा और पेंच के जंगलों से ही मिली थी।"],"factsEn":["Kanha is specially credited with saving the hard ground ''Barasingha'' from extinction.","The inspiration for Rudyard Kipling''s famous ''The Jungle Book'' came from the forests of Kanha and Pench."],"explanationHi":"यह उद्यान अपनी उत्कृष्ट वन्यजीव प्रबंधन प्रथाओं के लिए पूरे एशिया में जाना जाता है।","explanationEn":"This park is renowned across Asia for its excellent wildlife management practices.","memoryTip":"कान्हा के जंगल में ''बाघ'' और ''बारहसिंगा'' दोनों मस्ती करते हैं।","memoryTipEn":"Kanha keeps the Tiger and Barasingha safe.","related":["Project Tiger","The Jungle Book","State Animal of MP"]}', 'published', 1776087723, 1776087723);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PDnTaqKvo1KjS2t7KMAO4', 'General Knowledge', 'मध्य प्रदेश का राजकीय खेल कौनसा है?', 'Which is the state sport of Madhya Pradesh?', 'मलखंब', 'Malkhamb', 96, 0, '{"facts":["इसे 2013 में मध्य प्रदेश का राजकीय खेल घोषित किया गया था।","इस खेल में एक लकड़ी के खंभे पर जिमनास्टिक करतब दिखाए जाते हैं।"],"factsEn":["It was declared the state sport of MP in 2013.","Gymnastic feats are performed on a wooden pole in this sport."],"explanationHi":"यह प्राचीन भारतीय मार्शल आर्ट और व्यायाम का एक रूप है, जो शरीर को लचीला और मजबूत बनाता है। उज्जैन में मलखंब अकादमी स्थित है।","explanationEn":"It is an ancient Indian martial art and form of exercise that makes the body flexible and strong. A Malkhamb academy is located in Ujjain.","memoryTip":"एमपी के ''मल'' (पहलवान) ''खंभे'' पर करतब दिखाते हैं।","memoryTipEn":"Malkhamb tests the muscles on a pole.","related":["Prabhash Joshi Award","Ujjain Malkhamb Academy","State Symbols of MP"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gBzFpBIB8EC1BQuLFSMxv', 'General Knowledge', 'मध्य प्रदेश का राजकीय वृक्ष कौनसा है?', 'Which is the state tree of Madhya Pradesh?', 'बरगद (बट वृक्ष)', 'Banyan Tree', 92, 0, '{"facts":["इसे 1981 में राज्य के 25वें स्थापना दिवस पर राजकीय वृक्ष घोषित किया गया था।","बरगद का वैज्ञानिक नाम ''फाइकस बेनघालेंसिस'' (Ficus benghalensis) है।"],"factsEn":["It was declared the state tree on the 25th foundation day of the state in 1981.","The scientific name of the Banyan tree is ''Ficus benghalensis''."],"explanationHi":"बरगद का पेड़ अपनी विशालता और लंबी उम्र के लिए जाना जाता है, जो मध्य प्रदेश की ऐतिहासिक और सांस्कृतिक जड़ों की गहराई का प्रतीक है।","explanationEn":"The Banyan tree is known for its immensity and long life, symbolizing the depth of Madhya Pradesh''s historical and cultural roots.","memoryTip":"भारत और मध्य प्रदेश दोनों का ''बड़ा'' पेड़ बरगद ही है।","memoryTipEn":"Banyan covers MP like an umbrella.","related":["State Symbols of MP","Flora of MP","Ficus benghalensis"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4HXrUzavmCpYM-LcempKJ', 'General Knowledge', 'मध्य प्रदेश का राजकीय पुष्प कौनसा है?', 'Which is the state flower of Madhya Pradesh?', 'सफेद लिली', 'White Lily', 91, 0, '{"facts":["सफेद लिली का वैज्ञानिक नाम ''लिलियम कैंडिडम'' (Lilium candidum) है।","यह मुख्य रूप से नम और दलदली क्षेत्रों में उगता है।"],"factsEn":["The scientific name of the White Lily is ''Lilium candidum''.","It primarily grows in moist and swampy areas."],"explanationHi":"सफेद लिली पवित्रता और सुंदरता का प्रतीक है। यह मध्य प्रदेश के विभिन्न हिस्सों में व्यापक रूप से पाई जाती है।","explanationEn":"The White Lily is a symbol of purity and beauty. It is widely found in various parts of Madhya Pradesh.","memoryTip":"एमपी की प्रकृति ''लिली'' की तरह सफेद और स्वच्छ है।","memoryTipEn":"White Lily lights up the MP landscape.","related":["Lilium candidum","State Symbols of MP"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FQvpr6_T5txGGrnmETW-L', 'General Knowledge', 'राजा भोज की राजधानी मध्य प्रदेश के किस शहर में थी?', 'In which city of Madhya Pradesh was the capital of Raja Bhoj located?', 'धार (Dhar)', 'Dhar', 95, 0, '{"facts":["राजा भोज परमार वंश (Paramara dynasty) के सबसे महान शासक थे।","उन्होंने धार में ''सरस्वती मंदिर'' (भोजशाला) का निर्माण करवाया था।"],"factsEn":["Raja Bhoj was the greatest ruler of the Paramara dynasty.","He built the ''Saraswati Temple'' (Bhojshala) in Dhar."],"explanationHi":"राजा भोज एक महान विद्वान, कवि और वास्तुकार थे। उन्होंने ही भोपाल शहर (भोजपाल) और वहाँ की बड़ी झील का निर्माण करवाया था।","explanationEn":"Raja Bhoj was a great scholar, poet, and architect. He founded the city of Bhopal (Bhojpal) and built its Upper Lake.","memoryTip":"भोज ने ज्ञान की ''धार'' बहाई।","memoryTipEn":"Bhoja ruled from Dhar.","related":["Paramara Dynasty","Bhojshala","Upper Lake Bhopal"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('g0vWtR1yE12gRSRlAbr_m', 'General Knowledge', 'भारत का पहला ''जनजातीय विश्वविद्यालय'' (Tribal University) मध्य प्रदेश में कहाँ स्थित है?', 'Where is India''s first ''Tribal University'' located in Madhya Pradesh?', 'अमरकंटक (अनूपपुर)', 'Amarkantak (Anuppur)', 94, 0, '{"facts":["इसका नाम ''इंदिरा गांधी राष्ट्रीय जनजातीय विश्वविद्यालय'' (IGNTU) है।","इसकी स्थापना 2008 में संसद के एक अधिनियम द्वारा की गई थी।"],"factsEn":["Its name is ''Indira Gandhi National Tribal University'' (IGNTU).","It was established in 2008 by an Act of Parliament."],"explanationHi":"इसका मुख्य उद्देश्य भारत की जनजातीय आबादी (Tribal population) को उच्च शिक्षा प्रदान करना और उनकी कला, संस्कृति तथा परंपराओं पर शोध करना है।","explanationEn":"Its main objective is to provide higher education to India''s tribal population and to research their art, culture, and traditions.","memoryTip":"आदिवासियों की शिक्षा को ''अमर'' करने के लिए अमरकंटक में यूनिवर्सिटी बनी।","memoryTipEn":"Amarkantak educates the indigenous.","related":["IGNTU","Tribes of MP","Anuppur District"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JSfwVPOisU0O2BE2cPFEW', 'General Knowledge', 'दुनिया की पहली ''व्हाइट टाइगर सफारी'' (White Tiger Safari) मध्य प्रदेश में कहाँ शुरू की गई?', 'Where was the world''s first ''White Tiger Safari'' started in Madhya Pradesh?', 'मुकुंदपुर (सतना/रीवा के पास)', 'Mukundpur (near Satna/Rewa)', 96, 0, '{"facts":["इसका उद्घाटन अप्रैल 2016 में किया गया था।","रीवा के महाराजा मार्तंड सिंह ने 1951 में ''मोहन'' नाम का पहला सफेद बाघ पकड़ा था।"],"factsEn":["It was inaugurated in April 2016.","Maharaja Martand Singh of Rewa captured the first white tiger named ''Mohan'' in 1951."],"explanationHi":"यह सफारी सफेद बाघों को उनके मूल निवास स्थान (रीवा क्षेत्र) में वापस लाने का एक प्रयास है। तकनीकी रूप से मुकुंदपुर सतना जिले में आता है, लेकिन यह रीवा से बहुत करीब है।","explanationEn":"This safari is an effort to bring white tigers back to their original habitat (Rewa region). Technically, Mukundpur falls in Satna district but is very close to Rewa.","memoryTip":"सफेद बाघ ने ''मुकुट'' (मुकुंदपुर) पहन लिया।","memoryTipEn":"Mukundpur makes a home for white tigers.","related":["Mohan the White Tiger","Rewa State","Bandhavgarh National Park"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BJ1yCyUZA85SmvJgjQDpo', 'General Knowledge', 'मध्य प्रदेश के किस शहर को ''दक्षिण भारत का प्रवेश द्वार'' (Gateway to South India) कहा जाता है?', 'Which city of Madhya Pradesh is known as the ''Gateway to South India''?', 'बुरहानपुर', 'Burhanpur', 93, 0, '{"facts":["बुरहानपुर ताप्ती नदी के किनारे स्थित है।","यहाँ का ''असीरगढ़ का किला'' (Asirgarh Fort) दक्कन की कुंजी (Key to the Deccan) माना जाता था।"],"factsEn":["Burhanpur is situated on the banks of the Tapti River.","The ''Asirgarh Fort'' located here was considered the ''Key to the Deccan''."],"explanationHi":"प्राचीन और मध्यकाल में उत्तर भारत से दक्षिण भारत जाने वाले सभी व्यापारिक और सैन्य मार्ग बुरहानपुर से होकर ही गुजरते थे। मुमताज महल की पहली कब्र भी यहीं थी।","explanationEn":"In ancient and medieval times, all trade and military routes from North to South India passed through Burhanpur. Mumtaz Mahal''s initial tomb was also here.","memoryTip":"दक्षिण जाने वालों को बुरहानपुर का ''बुरका'' (दरवाजा) पार करना पड़ता था।","memoryTipEn":"Burhanpur is the border to the Deccan.","related":["Asirgarh Fort","Tapti River","Mumtaz Mahal"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bVqeTx0OdqzyALsZ3GGE8', 'General Science', 'कोशिका की ''आत्मघाती थैली'' (Suicide Bag) किसे कहा जाता है?', 'What is known as the ''Suicide Bag'' of the cell?', 'लाइसोसोम (Lysosome)', 'Lysosome', 95, 0, '{"facts":["इसमें शक्तिशाली पाचक एंजाइम (Digestive enzymes) होते हैं।","इनकी खोज क्रिश्चियन डी डुवे (Christian de Duve) ने की थी।"],"factsEn":["It contains powerful digestive enzymes.","They were discovered by Christian de Duve."],"explanationHi":"जब कोशिका क्षतिग्रस्त हो जाती है, तो लाइसोसोम फट सकते हैं और इसके एंजाइम अपनी ही कोशिका को पचा (खा) जाते हैं, इसलिए इसे आत्मघाती थैली कहा जाता है।","explanationEn":"When the cell is damaged, lysosomes may burst and their enzymes digest their own cell, hence they are called suicide bags.","memoryTip":"अपनी ही सेल को ''लॉस'' (Lyso) कर दे = लाइसोसोम।","memoryTipEn":"Lysosomes lyse (break down) the cell.","related":["Mitochondria (Powerhouse)","Ribosome (Protein Factory)","Cell Biology"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('VL0rtOrVKujdvTjrETOoM', 'General Science', 'कमरे के तापमान पर तरल अवस्था (Liquid state) में पाई जाने वाली एकमात्र अधातु (Non-metal) कौनसी है?', 'Which is the only non-metal found in a liquid state at room temperature?', 'ब्रोमीन (Bromine)', 'Bromine', 92, 0, '{"facts":["ब्रोमीन एक गहरे लाल-भूरे रंग का तरल पदार्थ है।","पारा (Mercury) एकमात्र ''धातु'' (Metal) है जो तरल अवस्था में रहता है।"],"factsEn":["Bromine is a dark red-brown liquid.","Mercury is the only ''metal'' that remains in a liquid state."],"explanationHi":"ब्रोमीन हैलोजन (Halogen) समूह का सदस्य है। इसका उपयोग कृषि रसायनों, कीटनाशकों और ज्वाला मंदक (flame retardants) में किया जाता है।","explanationEn":"Bromine is a member of the Halogen group. It is used in agricultural chemicals, insecticides, and flame retardants.","memoryTip":"पानी में ''ब्रो'' (Bromine) तैरता है (तरल है)।","memoryTipEn":"Bromine is the liquid brother of non-metals.","related":["Mercury (Liquid Metal)","Halogens","Periodic Table"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uTBCAlki5zwhUM7wBNXm5', 'General Science', 'ठोस कार्बन डाइऑक्साइड (Solid Carbon Dioxide) को किस नाम से जाना जाता है?', 'By what name is solid Carbon Dioxide known?', 'शुष्क बर्फ (Dry Ice)', 'Dry Ice', 94, 0, '{"facts":["इसे ''शुष्क बर्फ'' इसलिए कहा जाता है क्योंकि यह पिघलकर तरल (Liquid) नहीं बनती, बल्कि सीधे गैस में बदल जाती है।","इस प्रक्रिया को उर्ध्वपातन (Sublimation) कहते हैं।"],"factsEn":["It is called ''dry ice'' because it does not melt into a liquid but turns directly into a gas.","This process is called Sublimation."],"explanationHi":"इसका तापमान बहुत कम (-78.5°C) होता है, इसलिए इसका उपयोग खाद्य पदार्थों और मेडिकल सप्लाई (जैसे वैक्सीन) को ठंडा रखने और शिपिंग के लिए किया जाता है।","explanationEn":"It has a very low temperature (-78.5°C), hence it is used for cooling and shipping food items and medical supplies (like vaccines).","memoryTip":"बिना पानी छोड़े उड़ जाने वाली बर्फ = ड्राई आइस (CO2)।","memoryTipEn":"Dry ice dries up into gas.","related":["Sublimation","Carbon Dioxide","Refrigerants"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SyCmn4D4JZ3bbJFgAGCJk', 'General Science', 'आलू के चिप्स के पैकेट में कौनसी गैस भरी जाती है?', 'Which gas is filled in potato chips packets?', 'नाइट्रोजन (Nitrogen)', 'Nitrogen', 93, 0, '{"facts":["नाइट्रोजन एक अक्रिय (unreactive) गैस है जो चिप्स को ऑक्सीकरण (Oxidation) से बचाती है।","यह चिप्स को सील (soggy) होने और बासी होने से रोकती है।"],"factsEn":["Nitrogen is an unreactive gas that prevents the oxidation of chips.","It prevents the chips from getting soggy and stale."],"explanationHi":"पैकेट में ऑक्सीजन होने से चिप्स का तेल खराब हो सकता है (Rancidity)। नाइट्रोजन चिप्स को टूटने से बचाने के लिए एक कुशन (गद्दे) का काम भी करती है।","explanationEn":"Presence of oxygen can make the oil in chips go bad (Rancidity). Nitrogen also acts as a cushion to prevent the chips from breaking.","memoryTip":"चिप्स को ''नाईट'' (Nitrogen) तक कुरकुरा रखती है।","memoryTipEn":"Nitrogen keeps the crunch.","related":["Rancidity","Antioxidants","Atmospheric Gases"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6fvkUCBxRozr-q9kwGCve', 'General Science', 'बल (Force) का SI मात्रक (Unit) क्या है?', 'What is the SI unit of Force?', 'न्यूटन (Newton)', 'Newton', 97, 0, '{"facts":["इसे प्रतीक ''N'' द्वारा दर्शाया जाता है।","एक न्यूटन उस बल के बराबर है जो 1 किलोग्राम द्रव्यमान की वस्तु में 1 मीटर/सेकंड² का त्वरण (acceleration) उत्पन्न करता है।"],"factsEn":["It is denoted by the symbol ''N''.","One Newton is the force needed to accelerate a 1-kilogram mass by 1 meter/second²."],"explanationHi":"यह मात्रक प्रसिद्ध भौतिक विज्ञानी सर आइजैक न्यूटन के सम्मान में रखा गया है, जिन्होंने गति के नियमों (Laws of Motion) की खोज की थी।","explanationEn":"This unit is named in honor of the famous physicist Sir Isaac Newton, who discovered the Laws of Motion.","memoryTip":"सेब गिरने का ''बल'' न्यूटन ने मापा।","memoryTipEn":"Newton forced the laws of physics.","related":["Joule (Work/Energy)","Pascal (Pressure)","Laws of Motion"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ctF-sOoZDDsUxqsYejRUi', 'General Science', 'निकट दृष्टि दोष (Myopia) को दूर करने के लिए किस लेंस का उपयोग किया जाता है?', 'Which lens is used to correct short-sightedness (Myopia)?', 'अवतल लेंस (Concave Lens)', 'Concave Lens', 96, 0, '{"facts":["मायोपिया में दूर की वस्तुएं धुंधली दिखाई देती हैं।","दूर दृष्टि दोष (Hypermetropia) के लिए ''उत्तल लेंस'' (Convex Lens) का उपयोग किया जाता है।"],"factsEn":["In Myopia, distant objects appear blurry.","For long-sightedness (Hypermetropia), a ''Convex Lens'' is used."],"explanationHi":"मायोपिया में प्रकाश किरणें रेटिना से पहले ही केंद्रित हो जाती हैं। अवतल लेंस किरणों को फैलाकर उन्हें सही जगह (रेटिना) पर केंद्रित करता है।","explanationEn":"In myopia, light rays focus in front of the retina. A concave lens diverges the rays to focus them correctly on the retina.","memoryTip":"''निकट'' के लिए ''अवतल'' (बड़ा शब्द), ''दूर'' के लिए ''उत्तल'' (छोटा शब्द)।","memoryTipEn":"Cave in to clear near vision.","related":["Hypermetropia","Retina","Diopter"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GlT4b0CubHYns4QMXaP6X', 'General Knowledge', 'भारत के राष्ट्रपति बनने के लिए न्यूनतम आयु (Minimum Age) कितनी होनी चाहिए?', 'What should be the minimum age to become the President of India?', '35 वर्ष', '35 Years', 98, 0, '{"facts":["उपराष्ट्रपति और राज्यों के राज्यपाल (Governor) बनने के लिए भी न्यूनतम आयु 35 वर्ष ही है।","राज्यसभा का सदस्य बनने के लिए न्यूनतम आयु 30 वर्ष है।"],"factsEn":["The minimum age to become Vice President and State Governor is also 35 years.","The minimum age to become a Rajya Sabha member is 30 years."],"explanationHi":"संविधान के अनुच्छेद 58 के अनुसार, राष्ट्रपति पद के उम्मीदवार को भारत का नागरिक होना चाहिए और उसमें लोकसभा सदस्य बनने की योग्यता होनी चाहिए।","explanationEn":"According to Article 58 of the Constitution, a Presidential candidate must be a citizen of India and qualified to be a member of the Lok Sabha.","memoryTip":"35 की उम्र में आप देश (राष्ट्रपति) या राज्य (राज्यपाल) के मुखिया बन सकते हैं।","memoryTipEn":"35 years to hold the highest seat.","related":["Qualifications of President","Lok Sabha Age (25 Years)","Panchayat Age (21 Years)"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AVblZhYF20Uj4zNpwyQsP', 'General Knowledge', 'राज्य के राज्यपाल (Governor) को पद की शपथ कौन दिलाता है?', 'Who administers the oath of office to the Governor of a state?', 'संबंधित राज्य के उच्च न्यायालय का मुख्य न्यायाधीश', 'Chief Justice of the concerned State High Court', 95, 0, '{"facts":["यदि मुख्य न्यायाधीश अनुपस्थित है, तो उच्च न्यायालय का सबसे वरिष्ठ न्यायाधीश शपथ दिलाता है।","राज्यपाल की ''नियुक्ति'' (Appointment) भारत के राष्ट्रपति द्वारा की जाती है।"],"factsEn":["If the Chief Justice is absent, the senior-most judge of the High Court administers the oath.","The ''Appointment'' of the Governor is done by the President of India."],"explanationHi":"यह राष्ट्रपति के समान ही प्रक्रिया है (राष्ट्रपति को सुप्रीम कोर्ट का मुख्य न्यायाधीश शपथ दिलाता है)।","explanationEn":"This is a process parallel to the President (the President is administered the oath by the Chief Justice of the Supreme Court).","memoryTip":"नियुक्ति ''दिल्ली'' (राष्ट्रपति) से, लेकिन शपथ ''राज्य'' (हाई कोर्ट) में।","memoryTipEn":"Appointed by the Center, Sworn in by the State.","related":["High Court of MP","Presidential Oath","Article 159"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('f2ZTvle0-srNfppx7zm-X', 'General Knowledge', 'भारत की सबसे बड़ी मीठे पानी (Freshwater) की झील कौनसी है?', 'Which is the largest freshwater lake in India?', 'वुलर झील (Wular Lake)', 'Wular Lake', 94, 0, '{"facts":["यह जम्मू और कश्मीर में बांदीपोरा जिले में स्थित है।","इस झील का निर्माण विवर्तनिक गतिविधि (Tectonic activity) के कारण हुआ था।"],"factsEn":["It is located in the Bandipora district in Jammu & Kashmir.","This lake was formed as a result of tectonic activity."],"explanationHi":"वुलर झील में मुख्य रूप से झेलम नदी (Jhelum River) का पानी आता है। भारत की सबसे बड़ी खारे पानी की झील ''चिल्का झील'' (ओडिशा) है।","explanationEn":"Wular Lake is primarily fed by the Jhelum River. India''s largest brackish water lake is ''Chilika Lake'' (Odisha).","memoryTip":"कश्मीर की ''वूलन'' (ऊन) की तरह मीठी और ठंडी है वुलर झील।","memoryTipEn":"Wular waters the Kashmir valley.","related":["Chilika Lake","Jhelum River","Dal Lake"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HkNodycteYcK-BXzduXGv', 'General Knowledge', 'हल्दीघाटी का युद्ध (Battle of Haldighati) कब लड़ा गया था?', 'When was the Battle of Haldighati fought?', '1576 ई.', '1576 AD', 96, 0, '{"facts":["यह युद्ध मेवाड़ के महाराणा प्रताप और मुग़ल सम्राट अकबर की सेना (जिसका नेतृत्व मानसिंह ने किया) के बीच हुआ था।","हल्दीघाटी राजस्थान के राजसमंद जिले में स्थित है।"],"factsEn":["The battle was fought between Maharana Pratap of Mewar and the Mughal emperor Akbar''s army (led by Man Singh).","Haldighati is located in the Rajsamand district of Rajasthan."],"explanationHi":"महाराणा प्रताप ने मुगलों की अधीनता स्वीकार करने से इनकार कर दिया था। इस युद्ध में राणा प्रताप के प्रसिद्ध घोड़े ''चेतक'' (Chetak) ने वीरगति पाई थी।","explanationEn":"Maharana Pratap refused to submit to the Mughals. In this battle, Rana Pratap''s famous horse ''Chetak'' attained martyrdom.","memoryTip":"15 और 76, मुगलों के छूट गए छक्के।","memoryTipEn":"1576: The Haldighati clash.","related":["Maharana Pratap","Chetak","Akbar"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('w-qWnnUau5CZU-jvLcR-X', 'General Knowledge', 'बंगाल का प्रथम गवर्नर-जनरल (First Governor-General of Bengal) कौन था?', 'Who was the first Governor-General of Bengal?', 'वारेन हेस्टिंग्स (Warren Hastings)', 'Warren Hastings', 93, 0, '{"facts":["उन्हें 1773 के रेगुलेटिंग एक्ट के तहत इस पद पर नियुक्त किया गया था।","भारत के प्रथम गवर्नर-जनरल ''लॉर्ड विलियम बेंटिक'' (1833) थे।"],"factsEn":["He was appointed to this post under the Regulating Act of 1773.","The first Governor-General of India was ''Lord William Bentinck'' (1833)."],"explanationHi":"वारेन हेस्टिंग्स ने बंगाल में द्वैध शासन (Dual Government) को समाप्त किया और न्याय प्रणाली की नींव रखी। उन पर बाद में ब्रिटिश संसद में महाभियोग (Impeachment) चलाया गया था।","explanationEn":"Warren Hastings ended the Dual Government in Bengal and laid the foundation of the judicial system. He was later impeached in the British Parliament.","memoryTip":"गवर्नर-जनरल बनने की ''हेस्ट'' (जल्दी) हेस्टिंग्स को थी।","memoryTipEn":"Hastings headed Bengal first.","related":["Regulating Act 1773","Lord William Bentinck","Robert Clive"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('F7taIEg_PCYHvkDXUlPRL', 'General Science', 'सौरमंडल का ''लाल ग्रह'' (Red Planet) किसे कहा जाता है?', 'Which planet in the solar system is known as the ''Red Planet''?', 'मंगल (Mars)', 'Mars', 95, 0, '{"facts":["मंगल ग्रह की मिट्टी में ''आयरन ऑक्साइड'' (Iron Oxide) की प्रचुरता के कारण इसका रंग लाल होता है।","इसके दो प्राकृतिक उपग्रह (Moons) हैं: फोबोस और डीमोस (Phobos and Deimos)।"],"factsEn":["Its red color is due to the abundance of ''Iron Oxide'' in the Martian soil.","It has two natural moons: Phobos and Deimos."],"explanationHi":"सौरमंडल का सबसे ऊंचा ज्वालामुखी पर्वत ''ओलंपस मॉन्स'' (Olympus Mons) मंगल ग्रह पर ही स्थित है।","explanationEn":"The highest volcanic mountain in the solar system, ''Olympus Mons'', is located on Mars.","memoryTip":"लाल रंग ''मंगल'' (हनुमान जी/मंगलवार) का प्रतीक है।","memoryTipEn":"Mars is rusted red.","related":["Phobos and Deimos","Olympus Mons","Mangalyaan (ISRO)"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_-GP1EPCrRCXh4ngbLJxP', 'General Knowledge', 'सिखों के 10वें और अंतिम गुरु कौन थे?', 'Who was the 10th and last Guru of the Sikhs?', 'गुरु गोबिंद सिंह', 'Guru Gobind Singh', 97, 0, '{"facts":["उन्होंने 1699 में ''खालसा पंथ'' (Khalsa Panth) की स्थापना की थी।","सिख धर्म के पहले गुरु और संस्थापक ''गुरु नानक देव'' थे।"],"factsEn":["He established the ''Khalsa Panth'' in 1699.","The first Guru and founder of Sikhism was ''Guru Nanak Dev''."],"explanationHi":"गुरु गोबिंद सिंह ने अपने बाद किसी भी मानव गुरु की परंपरा को समाप्त कर दिया और सिखों के पवित्र ग्रंथ ''गुरु ग्रंथ साहिब'' (Guru Granth Sahib) को शाश्वत गुरु घोषित किया।","explanationEn":"Guru Gobind Singh ended the line of human gurus and declared the holy Sikh scripture, the ''Guru Granth Sahib'', as the eternal Guru.","memoryTip":"गोबिंद सिंह ने सिखों को ''खालसा'' (शुद्ध) सैनिक बनाया।","memoryTipEn":"Gobind Singh guided the Khalsa.","related":["Khalsa Panth","Guru Granth Sahib","Patna Sahib (Birthplace)"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('d2O_Y-K_ThbwLCZLhfx6B', 'General Science', 'मानव शरीर का सबसे बड़ा अंग (Largest Organ) कौनसा है?', 'Which is the largest organ of the human body?', 'त्वचा (Skin)', 'Skin', 92, 0, '{"facts":["त्वचा एक बाहरी अंग है जो शरीर के कुल वजन का लगभग 15-16% होता है।","यदि ''सबसे बड़ा आंतरिक अंग'' (Largest internal organ) या ''सबसे बड़ी ग्रंथि'' पूछा जाए, तो उत्तर ''यकृत'' (Liver) होगा।"],"factsEn":["Skin is an external organ making up about 15-16% of total body weight.","If asked for the ''largest internal organ'' or ''largest gland'', the answer is ''Liver''."],"explanationHi":"त्वचा हमारे शरीर को बाहरी संक्रमणों से बचाती है, तापमान नियंत्रित करती है, और विटामिन डी के संश्लेषण में मदद करती है।","explanationEn":"Skin protects our body from external infections, regulates temperature, and helps in synthesizing Vitamin D.","memoryTip":"त्वचा ने पूरे शरीर को ढंक रखा है, इसलिए सबसे बड़ी है।","memoryTipEn":"Skin covers it all.","related":["Liver (Largest Gland)","Femur (Largest Bone)","Epidermis"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('h9hfQqI2W80NZfqy3p26s', 'General Science', 'मानव शरीर की सबसे लंबी मांसपेशी (Longest Muscle) कौनसी है?', 'Which is the longest muscle in the human body?', 'सार्टोरियस (Sartorius)', 'Sartorius', 88, 0, '{"facts":["यह मांसपेशी कूल्हे (Hip) से शुरू होकर जांघ के सामने से होते हुए घुटने (Knee) के नीचे तक जाती है।","सबसे मजबूत मांसपेशी जबड़े (Jaw) की ''मासेटर'' (Masseter) होती है।"],"factsEn":["This muscle runs from the hip, across the front of the thigh, down to below the knee.","The strongest muscle is the ''Masseter'' of the jaw."],"explanationHi":"सार्टोरियस मांसपेशी हमें चौकड़ी मारकर (Cross-legged) बैठने में मदद करती है, इसलिए इसे कभी-कभी ''टेलर की मांसपेशी'' (Tailor''s muscle) भी कहा जाता है।","explanationEn":"The Sartorius muscle helps us sit cross-legged, which is why it is sometimes called the ''Tailor''s muscle''.","memoryTip":"''सरपट'' दौड़ने के लिए ''सार्टोरियस'' (पैर की मांसपेशी) चाहिए।","memoryTipEn":"Sartorius stretches down the thigh.","related":["Femur (Bone)","Masseter (Strongest muscle)","Gluteus Maximus (Largest muscle)"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yNUtRLWG1A6QaY36JcU3p', 'General Science', 'हमारी आकाशगंगा (मिल्की वे) के सबसे निकटतम सर्पिलाकार आकाशगंगा (Spiral Galaxy) कौनसी है?', 'Which is the nearest spiral galaxy to our Milky Way?', 'एन्ड्रोमेडा (Andromeda)', 'Andromeda', 90, 0, '{"facts":["यह पृथ्वी से लगभग 2.5 मिलियन प्रकाश वर्ष दूर है।","वैज्ञानिकों का अनुमान है कि अरबों वर्षों बाद मिल्की वे और एन्ड्रोमेडा का आपस में टकराव (Collision) होगा।"],"factsEn":["It is approximately 2.5 million light-years away from Earth.","Scientists predict that the Milky Way and Andromeda will collide in billions of years."],"explanationHi":"इसे ''मेसियर 31'' (M31) के नाम से भी जाना जाता है। यह उन कुछ आकाशगंगाओं में से एक है जिन्हें पृथ्वी से बिना दूरबीन के (नग्न आंखों से) देखा जा सकता है।","explanationEn":"It is also known as ''Messier 31'' (M31). It is one of the few galaxies that can be seen from Earth with the naked eye.","memoryTip":"अंतरिक्ष के ''अंधेरे'' (Andro) में हमारी पड़ोसी है एंड्रोमेडा।","memoryTipEn":"Andromeda is our galactic neighbor.","related":["Milky Way","Light Year","Local Group"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1USucK5uhiCIuWOgxCYgk', 'General Science', 'पोलियो (Polio) की वैक्सीन (टीका) का आविष्कार किसने किया था?', 'Who invented the Polio vaccine?', 'जोनास साल्क (Jonas Salk)', 'Jonas Salk', 95, 0, '{"facts":["साल्क ने 1953 में पहला सुरक्षित और प्रभावी ''इंजेक्टेबल'' (Inactivated) पोलियो टीका विकसित किया था।","बाद में ''अल्बर्ट साबिन'' (Albert Sabin) ने ''ओरल'' (मुंह से दी जाने वाली) पोलियो ड्रॉप विकसित की।"],"factsEn":["Salk developed the first safe and effective ''injectable'' (Inactivated) polio vaccine in 1953.","Later, ''Albert Sabin'' developed the ''oral'' polio drop."],"explanationHi":"भारत 2014 से आधिकारिक तौर पर पोलियो-मुक्त (Polio-free) देश है। जोनास साल्क ने कभी अपनी वैक्सीन का पेटेंट नहीं कराया ताकि यह सबके लिए उपलब्ध हो सके।","explanationEn":"India is officially a polio-free country since 2014. Jonas Salk never patented his vaccine so that it could be available to everyone.","memoryTip":"पोलियो के वाइरस को ''साल'' (साल्क) कर दिया।","memoryTipEn":"Salk solved the Polio problem.","related":["Albert Sabin (Oral Vaccine)","Edward Jenner (Smallpox)","Pulse Polio Campaign"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jfm1bUi0qozm1qKLS19RZ', 'General Science', 'अंतरिक्ष में जाने वाली पहली भारतीय मूल की महिला कौन थीं?', 'Who was the first woman of Indian origin to go into space?', 'कल्पना चावला', 'Kalpana Chawla', 96, 0, '{"facts":["उनका जन्म हरियाणा के करनाल (Karnal) में हुआ था।","वे 1997 में पहली बार स्पेस शटल कोलंबिया (Space Shuttle Columbia) से अंतरिक्ष में गई थीं।"],"factsEn":["She was born in Karnal, Haryana.","She first went to space in 1997 aboard the Space Shuttle Columbia."],"explanationHi":"फरवरी 2003 में, अपने दूसरे अंतरिक्ष मिशन से लौटते समय, स्पेस शटल कोलंबिया के पृथ्वी के वायुमंडल में प्रवेश करते समय दुर्घटनाग्रस्त होने से उनकी और चालक दल के अन्य 6 सदस्यों की मृत्यु हो गई।","explanationEn":"In February 2003, while returning from her second space mission, she and the other 6 crew members died when the Space Shuttle Columbia disintegrated upon re-entering Earth''s atmosphere.","memoryTip":"भारत की ''कल्पना'' ने अंतरिक्ष की उड़ान भरी।","memoryTipEn":"Kalpana soared from Karnal to the Cosmos.","related":["Space Shuttle Columbia","Rakesh Sharma (First Indian)","Sunita Williams"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-064xdqJl_USq8rN9HRi4', 'General Knowledge', 'विश्व का सबसे बड़ा मरुस्थल (Desert) कौनसा है?', 'Which is the largest desert in the world?', 'सहारा (Sahara)', 'Sahara', 94, 0, '{"facts":["सहारा उत्तरी अफ्रीका में स्थित है और दुनिया का सबसे बड़ा ''गर्म'' मरुस्थल है।","भारत का सबसे बड़ा मरुस्थल ''थार'' (Thar) है, जो राजस्थान में है।"],"factsEn":["The Sahara is located in North Africa and is the world''s largest ''hot'' desert.","India''s largest desert is ''Thar'', located in Rajasthan."],"explanationHi":"तकनीकी रूप से अंटार्कटिका (Antarctica) दुनिया का सबसे बड़ा ''ठंडा'' मरुस्थल है, लेकिन जब सिर्फ ''मरुस्थल'' पूछा जाता है, तो उत्तर आमतौर पर सहारा ही होता है।","explanationEn":"Technically, Antarctica is the world''s largest ''cold'' desert, but when just ''desert'' is asked, the answer is usually the Sahara.","memoryTip":"रेत का ''सहारा'' लेकर अफ्रीका में बहुत बड़ा मरुस्थल है।","memoryTipEn":"Sahara covers the sands of Africa.","related":["Thar Desert","Gobi Desert","Antarctica"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wuBEHHZSvV1CHU6VczyxC', 'General Knowledge', 'पानी की मात्रा (Volume) के हिसाब से विश्व की सबसे बड़ी नदी कौनसी है?', 'Which is the largest river in the world by water volume?', 'अमेज़न (Amazon)', 'Amazon', 95, 0, '{"facts":["यह दक्षिण अमेरिका महाद्वीप में बहती है।","लंबाई के हिसाब से ''नील नदी'' (Nile) सबसे लंबी है।"],"factsEn":["It flows in the South American continent.","By length, the ''Nile'' is the longest river."],"explanationHi":"अमेज़न नदी का बेसिन दुनिया का सबसे बड़ा वर्षावन (Amazon Rainforest) है, जिसे ''पृथ्वी के फेफड़े'' (Lungs of the Earth) कहा जाता है।","explanationEn":"The Amazon river basin hosts the world''s largest rainforest (Amazon Rainforest), known as the ''Lungs of the Earth''.","memoryTip":"''अमेज़न'' से भारी मात्रा में ''पानी'' (सामान) डिलीवर होता है।","memoryTipEn":"Amazon holds an amazing amount of water.","related":["Nile River","Amazon Rainforest","South America"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('LCMcl6LlCl4XGz1gJ5csN', 'General Knowledge', 'विश्व का सबसे ऊँचा जलप्रपात (Highest Waterfall) कौनसा है?', 'Which is the highest waterfall in the world?', 'एंजिल जलप्रपात (Angel Falls)', 'Angel Falls', 93, 0, '{"facts":["यह वेनेजुएला (दक्षिण अमेरिका) में स्थित है।","इसकी ऊंचाई 979 मीटर (3,212 फीट) है।"],"factsEn":["It is located in Venezuela (South America).","Its height is 979 meters (3,212 feet)."],"explanationHi":"यह जलप्रपात इतना ऊंचा है कि नीचे तक पहुंचने से पहले ही पानी का एक बड़ा हिस्सा धुंध (Mist) के रूप में वाष्पित हो जाता है।","explanationEn":"The waterfall is so high that before reaching the ground, much of the water evaporates or is carried away as a fine mist.","memoryTip":"''एन्जिल'' (फरिश्ते) सबसे ऊँचाई पर रहते हैं।","memoryTipEn":"Angels fall from the highest skies.","related":["Venezuela","Niagara Falls","Jog Falls (India)"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('LlqgQT-4WfCIpLjKXmZXZ', 'General Science', 'ब्रह्मांड की सबसे हल्की गैस (Lightest Gas) कौनसी है?', 'Which is the lightest gas in the universe?', 'हाइड्रोजन (Hydrogen)', 'Hydrogen', 95, 0, '{"facts":["यह ब्रह्मांड में सबसे प्रचुर (Abundant) तत्व भी है।","हाइड्रोजन अत्यधिक ज्वलनशील (flammable) गैस है।"],"factsEn":["It is also the most abundant element in the universe.","Hydrogen is a highly flammable gas."],"explanationHi":"चूंकि यह ज्वलनशील है, इसलिए गुब्बारों और एयरशिप में सुरक्षित विकल्प के रूप में अक्सर दूसरी सबसे हल्की गैस ''हीलियम'' (Helium) का उपयोग किया जाता है।","explanationEn":"Since it is flammable, the second lightest gas ''Helium'' is often used as a safer alternative in balloons and airships.","memoryTip":"हाइड्रोजन का एटॉमिक नंबर ''1'' है, इसलिए सबसे हल्का है।","memoryTipEn":"Hydrogen is element number one, and the lightest.","related":["Helium","Nuclear Fusion (Sun)","Periodic Table"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('yR1ScTWJ3JDHQ_0M9LIKM', 'General Science', 'पृथ्वी की पपड़ी (Earth''s crust) में सबसे अधिक मात्रा में पाया जाने वाला तत्व (Element) कौनसा है?', 'Which is the most abundant element found in the Earth''s crust?', 'ऑक्सीजन', 'Oxygen', 94, 0, '{"facts":["पृथ्वी की पपड़ी का लगभग 46.6% हिस्सा ऑक्सीजन से बना है।","दूसरा सबसे प्रचुर तत्व सिलिकॉन (Silicon - लगभग 27.7%) है।"],"factsEn":["About 46.6% of the Earth''s crust is made of Oxygen.","The second most abundant element is Silicon (approx 27.7%)."],"explanationHi":"यदि ''धातु'' (Metal) पूछा जाए तो सबसे प्रचुर एल्युमिनियम है। ऑक्सीजन चट्टानों में ऑक्साइड खनिजों के रूप में फंसी होती है।","explanationEn":"If ''Metal'' is asked, the most abundant is Aluminium. Oxygen is trapped in rocks in the form of oxide minerals.","memoryTip":"हवा में नहीं, ज़मीन (Crust) में भी ''ऑक्सीजन'' सबसे ज्यादा है।","memoryTipEn":"Oxygen occupies the crust as oxides.","related":["Silicon","Aluminium (Most abundant metal)","Atmosphere Composition"]}', 'published', 1776092032, 1776092032);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JetqttcN2agMoTRi2yXbU', 'General Knowledge', 'रुस्तमजी सशस्त्र पुलिस प्रशिक्षण महाविद्यालय (RAPTC) मध्य प्रदेश में कहाँ स्थित है?', 'Where is the Rustomji Armed Police Training College (RAPTC) located in Madhya Pradesh?', 'इंदौर', 'Indore', 95, 0, '{"facts":["इसकी स्थापना 1980 में हुई थी।","यह मध्य प्रदेश पुलिस के सशस्त्र बलों को प्रशिक्षण देने वाला प्रमुख संस्थान है।"],"factsEn":["It was established in 1980.","It is the premier institute for training the armed forces of the Madhya Pradesh Police."],"explanationHi":"यह संस्थान पुलिस जवानों को हथियार चलाने, दंगा नियंत्रण और सामरिक संचालन में उच्च स्तरीय प्रशिक्षण प्रदान करता है।","explanationEn":"This institute provides high-level training to police personnel in weapons handling, riot control, and tactical operations.","memoryTip":"पुलिस की ''आर्म्ड'' ट्रेनिंग इंदौर में होती है।","memoryTipEn":"Indore instructs the armed cops.","related":["MP Police Academy Bhauri","Jawaharlal Nehru Police Academy Sagar"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RNc6QBgFX74BKkmYyxdlC', 'General Knowledge', 'मध्य प्रदेश में ''राज्य न्यायालयिक विज्ञान प्रयोगशाला'' (State Forensic Science Laboratory) कहाँ स्थित है?', 'Where is the State Forensic Science Laboratory located in Madhya Pradesh?', 'सागर', 'Sagar', 93, 0, '{"facts":["यहाँ अपराध स्थल से एकत्र किए गए भौतिक साक्ष्यों (Physical Evidence) की वैज्ञानिक जांच की जाती है।","सागर में ही मध्य प्रदेश की सबसे पुरानी यूनिवर्सिटी (हरि सिंह गौर यूनिवर्सिटी) भी है।"],"factsEn":["Scientific examination of physical evidence collected from crime scenes is conducted here.","Sagar also houses the oldest university of MP (Hari Singh Gour University)."],"explanationHi":"फोरेंसिक साइंस लैब पुलिस को जटिल आपराधिक मामलों को सुलझाने के लिए डीएनए, फिंगरप्रिंट और रासायनिक विश्लेषण जैसी तकनीकी सहायता प्रदान करती है।","explanationEn":"The Forensic Science Lab provides technical assistance to the police like DNA, fingerprint, and chemical analysis to solve complex criminal cases.","memoryTip":"अपराध के सुबूत ''सागर'' (FSL) में डूबकर निकाले जाते हैं।","memoryTipEn":"Sagar solves the forensic secrets.","related":["Forensic Science","DNA Profiling","Police Training School"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BDYoHV8yniTGon7a3ih2q', 'General Knowledge', 'प्रसिद्ध ''पशुपतिनाथ मंदिर'' मध्य प्रदेश के किस जिले में स्थित है?', 'The famous ''Pashupatinath Temple'' is located in which district of Madhya Pradesh?', 'मंदसौर', 'Mandsaur', 91, 0, '{"facts":["यह मंदिर शिवना नदी (Shivna River) के तट पर स्थित है।","इस मंदिर की मूर्ति नेपाल के काठमांडू स्थित पशुपतिनाथ मंदिर की मूर्ति के समान है।"],"factsEn":["This temple is situated on the banks of the Shivna River.","The idol of this temple resembles the idol of the Pashupatinath temple in Kathmandu, Nepal."],"explanationHi":"इस मंदिर में भगवान शिव की अनूठी आठ मुखी (अष्टमुखी) शिवलिंग स्थापित है।","explanationEn":"A unique eight-faced (Ashtamukhi) Shivling of Lord Shiva is installed in this temple.","memoryTip":"''मंद'' (मंदसौर) ''शिव'' (शिवना नदी) पशुपतिनाथ में हैं।","memoryTipEn":"Mandsaur holds the majestic Pashupatinath.","related":["Shivna River","Ashtamukhi Shivling","Kathmandu Pashupatinath"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ti84eEx68aGHrJqHUL8Cf', 'General Knowledge', 'चंबल नदी का उद्गम स्थल मध्य प्रदेश में कहाँ है?', 'Where is the origin of the Chambal River in Madhya Pradesh?', 'जानापाव पहाड़ी (महू, इंदौर)', 'Janapav Hill (Mhow, Indore)', 96, 0, '{"facts":["चंबल यमुना नदी की एक प्रमुख सहायक नदी है।","यह नदी बीहड़ों (Ravines) के निर्माण और घड़ियाल संरक्षण के लिए प्रसिद्ध है।"],"factsEn":["Chambal is a major tributary of the Yamuna River.","This river is famous for forming ravines and for Gharial conservation."],"explanationHi":"चंबल नदी मध्य प्रदेश, राजस्थान और उत्तर प्रदेश से होकर बहती है। इस पर गांधी सागर, राणा प्रताप सागर और जवाहर सागर बांध बने हैं।","explanationEn":"The Chambal River flows through MP, Rajasthan, and UP. Gandhi Sagar, Rana Pratap Sagar, and Jawahar Sagar dams are built on it.","memoryTip":"चंबल के डाकू ''महू'' के ''जानापाव'' से डरते हैं।","memoryTipEn":"Chambal churns from Janapav.","related":["Yamuna River","Chambal Ravines","Mhow"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GeaRMfHZrgIftcjRCOAat', 'General Knowledge', 'क्षिप्रा (Shipra) नदी का उद्गम स्थल कहाँ है?', 'Where is the origin of the Shipra River?', 'काकरी बरडी पहाड़ी (इंदौर)', 'Kakri Bardi Hill (Indore)', 93, 0, '{"facts":["इसे ''मालवा की गंगा'' (Ganga of Malwa) भी कहा जाता है।","पवित्र शहर उज्जैन और प्रसिद्ध महाकालेश्वर मंदिर इसी नदी के तट पर स्थित हैं।"],"factsEn":["It is also known as the ''Ganga of Malwa''.","The holy city of Ujjain and the famous Mahakaleshwar temple are situated on its banks."],"explanationHi":"यह चंबल नदी की एक सहायक नदी है। हर 12 साल में क्षिप्रा नदी के तट पर सिंहस्थ कुंभ मेला लगता है।","explanationEn":"It is a tributary of the Chambal River. The Simhastha Kumbh Mela is held every 12 years on the banks of the Shipra River.","memoryTip":"''काकरी'' (कंकड़) वाली पहाड़ी से क्षिप्रा निकलती है।","memoryTipEn":"Shipra starts from Kakri Bardi.","related":["Simhastha Kumbh Mela","Ujjain","Malwa Region"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kh3nmwzoOZtbzyRcMDeBw', 'General Science', 'विद्युत प्रतिरोध (Electrical Resistance) का SI मात्रक क्या है?', 'What is the SI unit of Electrical Resistance?', 'ओम (Ohm)', 'Ohm', 94, 0, '{"facts":["इसे ग्रीक अक्षर ओमेगा (Ω) द्वारा दर्शाया जाता है।","प्रतिरोध वह गुण है जो किसी परिपथ में विद्युत धारा के प्रवाह का विरोध करता है।"],"factsEn":["It is denoted by the Greek letter Omega (Ω).","Resistance is the property that opposes the flow of electric current in a circuit."],"explanationHi":"जर्मन भौतिक विज्ञानी जॉर्ज साइमन ओम के नाम पर इसका नाम रखा गया है, जिन्होंने ''ओम का नियम'' (V = IR) दिया था।","explanationEn":"It is named after the German physicist Georg Simon Ohm, who formulated ''Ohm''s Law'' (V = IR).","memoryTip":"करंट को रोकने के लिए ''ओम'' का जाप करो।","memoryTipEn":"Ohm opposes the current.","related":["Ohm''s Law","Ampere (Current)","Volt (Voltage)"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('DV80SptA4NAwQ25BAGv8Y', 'General Science', 'ब्लीचिंग पाउडर (विरंजक चूर्ण) का रासायनिक सूत्र क्या है?', 'What is the chemical formula of Bleaching Powder?', 'CaOCl2', 'CaOCl2', 90, 0, '{"facts":["इसका रासायनिक नाम कैल्शियम हाइपोक्लोराइट (Calcium hypochlorite) है।","इसका उपयोग पानी को कीटाणुरहित (Disinfect) करने के लिए किया जाता है।"],"factsEn":["Its chemical name is Calcium hypochlorite.","It is used to disinfect water."],"explanationHi":"यह एक पीला-सफेद पाउडर होता है जिससे क्लोरीन की तेज गंध आती है। इसका उपयोग कपड़ा और कागज उद्योगों में रंग उड़ाने (Bleaching) के लिए भी होता है।","explanationEn":"It is a pale-yellowish powder with a strong smell of chlorine. It is also used for bleaching in the textile and paper industries.","memoryTip":"कैल्शियम (Ca), ऑक्सीजन (O) और क्लोरीन (Cl2) का चूर्ण।","memoryTipEn":"Calcium oxygenates the chlorine.","related":["Calcium Hypochlorite","Disinfectant","Chlorine Gas"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3WxLJKMzrZIbD2bb56r2G', 'General Science', 'शुद्ध जल का pH मान कितना होता है?', 'What is the pH value of pure water?', '7 (तटस्थ/Neutral)', '7 (Neutral)', 95, 0, '{"facts":["pH पैमाने पर 7 से कम मान वाले पदार्थ अम्लीय (Acidic) होते हैं।","pH पैमाने पर 7 से अधिक मान वाले पदार्थ क्षारीय (Basic) होते हैं।"],"factsEn":["Substances with a pH value less than 7 are acidic.","Substances with a pH value more than 7 are basic."],"explanationHi":"शुद्ध पानी में हाइड्रोजन आयन (H+) और हाइड्रॉक्साइड आयन (OH-) की सांद्रता समान होती है, इसलिए यह न तो अम्लीय होता है और न ही क्षारीय।","explanationEn":"Pure water has an equal concentration of hydrogen ions (H+) and hydroxide ions (OH-), making it neither acidic nor basic.","memoryTip":"पानी के 7 गुण, इसलिए pH भी 7।","memoryTipEn":"Seven is the neutral center.","related":["pH Scale","Acids and Bases","Sørensen (pH scale inventor)"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('S0B7yOqoG8ytNeNy13zV1', 'General Science', 'विटामिन A का रासायनिक नाम क्या है?', 'What is the chemical name of Vitamin A?', 'रेटिनॉल (Retinol)', 'Retinol', 96, 0, '{"facts":["यह वसा में घुलनशील (Fat-soluble) विटामिन है।","इसकी कमी से रतौंधी (Night Blindness) नामक रोग हो जाता है।"],"factsEn":["It is a fat-soluble vitamin.","Its deficiency causes a disease called Night Blindness."],"explanationHi":"विटामिन A आंखों के स्वास्थ्य (विशेषकर रेटिना), त्वचा और प्रतिरक्षा प्रणाली के लिए बहुत महत्वपूर्ण है। गाजर इसका उत्कृष्ट स्रोत है।","explanationEn":"Vitamin A is vital for eye health (especially the retina), skin, and the immune system. Carrots are an excellent source.","memoryTip":"A से आँख की ''रेटिना'', और नाम ''रेटिनॉल''।","memoryTipEn":"Retinol is for the Retina.","related":["Night Blindness","Carrots","Fat-soluble Vitamins"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ThRwTc6KROCo5t4XvEcet', 'General Science', 'विटामिन E का रासायनिक नाम क्या है?', 'What is the chemical name of Vitamin E?', 'टोकोफेरॉल (Tocopherol)', 'Tocopherol', 92, 0, '{"facts":["इसे ''ब्यूटी विटामिन'' (Beauty Vitamin) भी कहा जाता है।","इसकी कमी से प्रजनन क्षमता में कमी (Infertility) आ सकती है।"],"factsEn":["It is also known as the ''Beauty Vitamin''.","Its deficiency can lead to a decrease in fertility (Infertility)."],"explanationHi":"यह एक मजबूत एंटीऑक्सीडेंट है जो कोशिकाओं को मुक्त कणों (Free radicals) से होने वाले नुकसान से बचाता है।","explanationEn":"It is a strong antioxidant that protects cells from damage caused by free radicals.","memoryTip":"E की कमी से बांझपन का ''टोक'' (टोकोफेरॉल) लगता है।","memoryTipEn":"Tocopherol takes care of tissues.","related":["Antioxidant","Infertility","Fat-soluble Vitamins"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('q14D1KaE59FdRzi-3zoN3', 'General Science', 'विटामिन K का रासायनिक नाम क्या है?', 'What is the chemical name of Vitamin K?', 'फिलोक्विनोन (Phylloquinone)', 'Phylloquinone', 94, 0, '{"facts":["यह रक्त का थक्का (Blood clotting) जमाने के लिए आवश्यक है।","इसकी कमी होने पर चोट लगने पर खून का बहना बंद नहीं होता।"],"factsEn":["It is essential for blood clotting.","If deficient, bleeding does not stop easily when injured."],"explanationHi":"विटामिन K प्राकृतिक रूप से हरी पत्तेदार सब्जियों (जैसे पालक, ब्रोकली) में प्रचुर मात्रा में पाया जाता है।","explanationEn":"Vitamin K is naturally found in abundance in green leafy vegetables (like spinach, broccoli).","memoryTip":"K से खून का थक्का ''फिल'' (फिलोक्विनोन) करता है।","memoryTipEn":"Phylloquinone fixes the clot.","related":["Blood Clotting","Prothrombin","Hemorrhage"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PdD8LmMy1SEdNoemR2SsM', 'General Knowledge', 'भारत के सर्वोच्च न्यायालय (Supreme Court) की पहली महिला न्यायाधीश कौन थीं?', 'Who was the first female judge of the Supreme Court of India?', 'फातिमा बीवी (Fathima Beevi)', 'Fathima Beevi', 95, 0, '{"facts":["उन्हें 1989 में सर्वोच्च न्यायालय की न्यायाधीश नियुक्त किया गया था।","वे भारत ही नहीं, बल्कि एशिया के किसी भी सर्वोच्च न्यायालय की पहली महिला न्यायाधीश थीं।"],"factsEn":["She was appointed as a Supreme Court judge in 1989.","She was the first female judge of any Supreme Court in Asia, not just India."],"explanationHi":"सुप्रीम कोर्ट से सेवानिवृत्त होने के बाद उन्होंने राष्ट्रीय मानवाधिकार आयोग की सदस्य और तमिलनाडु की राज्यपाल के रूप में भी कार्य किया।","explanationEn":"After retiring from the Supreme Court, she also served as a member of the National Human Rights Commission and Governor of Tamil Nadu.","memoryTip":"सुप्रीम कोर्ट की पहली महिला की ''फातिमा'' के नाम से शुरुआत हुई।","memoryTipEn":"Fathima pioneered female judges in the SC.","related":["Supreme Court of India","Anna Chandy (First female judge in India - HC)","Tamil Nadu"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Lr2JZTBzscp3_R1XKqwMi', 'General Knowledge', 'भारत की पहली महिला आई.ए.एस. (IAS) अधिकारी कौन थीं?', 'Who was the first female IAS officer of India?', 'अन्ना राजम मल्होत्रा', 'Anna Rajam Malhotra', 89, 0, '{"facts":["वे 1951 बैच की भारतीय प्रशासनिक सेवा (IAS) अधिकारी थीं।","भारत की पहली महिला IPS अधिकारी किरण बेदी (1972) थीं।"],"factsEn":["She was an Indian Administrative Service (IAS) officer of the 1951 batch.","India''s first female IPS officer was Kiran Bedi (1972)."],"explanationHi":"अन्ना राजम मल्होत्रा ने मद्रास कैडर में कार्य किया और कई महत्वपूर्ण प्रशासनिक पदों पर अपनी सेवाएं दीं।","explanationEn":"Anna Rajam Malhotra served in the Madras cadre and held several important administrative positions.","memoryTip":"आईएएस बनकर उन्होंने देश का ''अन्न'' (अन्ना) और ''राज'' (राजम) संभाला।","memoryTipEn":"Anna broke the administrative glass ceiling.","related":["Kiran Bedi (First IPS)","Civil Services of India","Women Empowerment"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YCAVV9Rt6eS-ER4Y1hHhd', 'General Knowledge', 'किस संविधान संशोधन द्वारा मतदान की आयु 21 वर्ष से घटाकर 18 वर्ष कर दी गई?', 'By which Constitutional Amendment was the voting age reduced from 21 years to 18 years?', '61वां संशोधन (1989)', '61st Amendment (1989)', 97, 0, '{"facts":["यह संशोधन राजीव गांधी के प्रधानमंत्री कार्यकाल के दौरान पारित किया गया था।","इसने संविधान के अनुच्छेद 326 (Article 326) में संशोधन किया।"],"factsEn":["This amendment was passed during the prime ministership of Rajiv Gandhi.","It amended Article 326 of the Constitution."],"explanationHi":"इस ऐतिहासिक कदम ने देश के युवाओं को मतदान का अधिकार देकर भारतीय लोकतंत्र को और अधिक व्यापक और समावेशी बना दिया।","explanationEn":"This historic step broadened and made Indian democracy more inclusive by granting the right to vote to the nation''s youth.","memoryTip":"6 और 1 (61) मिलकर 18 साल के युवाओं को वोट देने का अधिकार लाए।","memoryTipEn":"61st brought the youth to the polls.","related":["Article 326","Universal Adult Franchise","Election Commission"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Yv58RBTdVBSiwmMceWjBG', 'General Knowledge', 'संविधान का 74वां संशोधन किससे संबंधित है?', 'What is the 74th Amendment of the Constitution related to?', 'नगर पालिकाओं (शहरी स्थानीय स्वशासन) से', 'Municipalities (Urban Local Self-Government)', 95, 0, '{"facts":["यह संशोधन 1992 में पारित हुआ था।","इसने संविधान में ''भाग IX-A'' और ''बारहवीं अनुसूची'' (12th Schedule) को जोड़ा।"],"factsEn":["This amendment was passed in 1992.","It added ''Part IX-A'' and the ''12th Schedule'' to the Constitution."],"explanationHi":"जहां 73वां संशोधन ग्रामीण (ग्राम पंचायत) स्वशासन से संबंधित है, वहीं 74वां संशोधन शहरों में नगर पालिका और नगर निगमों को संवैधानिक दर्जा देता है।","explanationEn":"While the 73rd amendment deals with rural (Gram Panchayat) self-government, the 74th amendment grants constitutional status to municipalities and municipal corporations in urban areas.","memoryTip":"73 गांव के लिए, 74 शहर के लिए।","memoryTipEn":"74 empowers the urban core.","related":["73rd Amendment","12th Schedule","Local Self-Government"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AN0hmudJlLqJcuAsdP7HB', 'General Knowledge', 'संविधान के किस अनुच्छेद में ''उपाधियों के अंत'' (Abolition of Titles) का प्रावधान है?', 'Which article of the Constitution provides for the ''Abolition of Titles''?', 'अनुच्छेद 18', 'Article 18', 92, 0, '{"facts":["यह अनुच्छेद ब्रिटिश काल की उपाधियों (जैसे सर, राय बहादुर) को प्रतिबंधित करता है।","सैन्य (Military) और शैक्षणिक (Academic) विशिष्टताओं को इस प्रतिबंध से छूट दी गई है।"],"factsEn":["This article prohibits titles from the British era (like Sir, Rai Bahadur).","Military and academic distinctions are exempted from this prohibition."],"explanationHi":"इसका उद्देश्य समाज में समानता स्थापित करना है ताकि कोई भी नागरिक जन्म या वंश के आधार पर विशेष विशेषाधिकार का दावा न कर सके।","explanationEn":"Its purpose is to establish equality in society so that no citizen can claim special privileges based on birth or lineage.","memoryTip":"18 के बाद तुम ''सर'' या ''लॉर्ड'' नहीं कहलाओगे (उपाधि खत्म)।","memoryTipEn":"Article 18 ends elitist titles.","related":["Right to Equality","Article 17 (Untouchability)","Bharat Ratna"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zNAEbfdHr5FmjmAQO-zdV', 'General Knowledge', 'संविधान का कौन सा अनुच्छेद ''जीवन और व्यक्तिगत स्वतंत्रता के अधिकार'' की गारंटी देता है?', 'Which article of the Constitution guarantees the ''Right to Life and Personal Liberty''?', 'अनुच्छेद 21', 'Article 21', 98, 0, '{"facts":["यह एक अत्यंत महत्वपूर्ण मौलिक अधिकार है जिसे राष्ट्रीय आपातकाल (National Emergency) के दौरान भी निलंबित नहीं किया जा सकता।","अनुच्छेद 21A इसी के तहत ''शिक्षा का अधिकार'' प्रदान करता है।"],"factsEn":["It is a highly crucial fundamental right that cannot be suspended even during a National Emergency.","Article 21A provides the ''Right to Education'' under this framework."],"explanationHi":"अनुच्छेद 21 सुनिश्चित करता है कि कानून द्वारा स्थापित प्रक्रिया (Procedure established by law) के अलावा किसी भी व्यक्ति को उसके जीवन या व्यक्तिगत स्वतंत्रता से वंचित नहीं किया जाएगा।","explanationEn":"Article 21 ensures that no person shall be deprived of his life or personal liberty except according to procedure established by law.","memoryTip":"21 की उम्र में पूरी ''स्वतंत्रता'' और ''जीवन'' जीने का अधिकार मिलता है।","memoryTipEn":"Article 21 guarantees life for everyone.","related":["Fundamental Rights","National Emergency","Article 20"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_wWGRbHgMIZN-p3tOhI2T', 'General Knowledge', 'संविधान का अनुच्छेद 40 किससे संबंधित है?', 'What is Article 40 of the Constitution related to?', 'ग्राम पंचायतों के संगठन से', 'Organization of Village Panchayats', 95, 0, '{"facts":["यह ''राज्य के नीति निर्देशक सिद्धांतों'' (DPSP) का हिस्सा है।","यह अनुच्छेद महात्मा गांधी के ''ग्राम स्वराज'' (Gram Swaraj) के सपने पर आधारित है।"],"factsEn":["It is a part of the ''Directive Principles of State Policy'' (DPSP).","This article is based on Mahatma Gandhi''s dream of ''Gram Swaraj''."],"explanationHi":"यह अनुच्छेद राज्य को निर्देश देता है कि वह ग्राम पंचायतों को व्यवस्थित करने के लिए कदम उठाए और उन्हें स्वशासन (Self-government) की इकाइयों के रूप में कार्य करने की शक्तियां दे।","explanationEn":"This article directs the State to take steps to organize village panchayats and endow them with powers to function as units of self-government.","memoryTip":"40 गांवों को मिलाकर एक ''पंचायत'' बनाई।","memoryTipEn":"Article 40 forms the village councils.","related":["73rd Amendment","Panchayati Raj","DPSP"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('hB5j_xFjycwb8t4trFVPk', 'General Knowledge', 'संविधान का कौन सा अनुच्छेद ''समान नागरिक संहिता'' (Uniform Civil Code) से संबंधित है?', 'Which article of the Constitution relates to the ''Uniform Civil Code''?', 'अनुच्छेद 44', 'Article 44', 96, 0, '{"facts":["यह भी ''राज्य के नीति निर्देशक सिद्धांतों'' (DPSP) के अंतर्गत आता है।","गोवा भारत का एकमात्र राज्य है जहाँ समान नागरिक संहिता लागू है।"],"factsEn":["This also falls under the ''Directive Principles of State Policy'' (DPSP).","Goa is the only state in India where a Uniform Civil Code is implemented."],"explanationHi":"समान नागरिक संहिता का अर्थ है कि देश के सभी नागरिकों के लिए (चाहे वे किसी भी धर्म के हों) विवाह, तलाक, विरासत और गोद लेने जैसे मामलों में एक समान कानून होना।","explanationEn":"A Uniform Civil Code means having a common set of laws governing personal matters like marriage, divorce, inheritance, and adoption for all citizens irrespective of their religion.","memoryTip":"4 और 4 ''समान'' अंक हैं, इसलिए ''समान'' नागरिक संहिता (अनुच्छेद 44)।","memoryTipEn":"44 means Uniform (equal digits).","related":["Personal Laws","DPSP","Goa Civil Code"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SjajDGNohh_5bJyTW4Iau', 'General Knowledge', 'तराइन का प्रथम युद्ध (First Battle of Tarain) कब और किसके बीच हुआ था?', 'When and between whom was the First Battle of Tarain fought?', '1191 ई., पृथ्वीराज चौहान और मुहम्मद गौरी', '1191 AD, Prithviraj Chauhan and Muhammad Ghori', 94, 0, '{"facts":["इस युद्ध में राजपूत शासक पृथ्वीराज चौहान की शानदार जीत हुई थी।","तराइन (तरावड़ी) हरियाणा राज्य के करनाल जिले में स्थित है।"],"factsEn":["The Rajput ruler Prithviraj Chauhan won a resounding victory in this battle.","Tarain (Taraori) is located in the Karnal district of Haryana state."],"explanationHi":"पृथ्वीराज चौहान ने मुहम्मद गौरी को बुरी तरह हराया, लेकिन उसकी जान बख्श दी और उसे भागने दिया, जो इतिहास की एक बड़ी भूल मानी जाती है।","explanationEn":"Prithviraj Chauhan defeated Muhammad Ghori badly but spared his life and allowed him to flee, which is considered a major historical blunder.","memoryTip":"11-91 में पृथ्वीराज नंबर 1 (जीता) रहा।","memoryTipEn":"1191: Prithviraj prevails.","related":["Second Battle of Tarain","Muhammad Ghori","Rajput Dynasty"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CjXN8siTeaBeGOv3tenKE', 'General Knowledge', 'तराइन के द्वितीय युद्ध (1192 ई.) में किसकी जीत हुई थी?', 'Who won the Second Battle of Tarain (1192 AD)?', 'मुहम्मद गौरी', 'Muhammad Ghori', 95, 0, '{"facts":["इस युद्ध में मुहम्मद गौरी ने पृथ्वीराज चौहान को हरा दिया था।","कन्नौज के राजा जयचंद ने इस युद्ध में पृथ्वीराज चौहान का साथ नहीं दिया था।"],"factsEn":["Muhammad Ghori defeated Prithviraj Chauhan in this battle.","King Jaichand of Kannauj did not support Prithviraj Chauhan in this war."],"explanationHi":"इस युद्ध के परिणाम ने भारत के इतिहास की दिशा बदल दी, क्योंकि इसी जीत के साथ भारत में मुस्लिम शासन (दिल्ली सल्तनत) की नींव पड़ी।","explanationEn":"The outcome of this battle changed the course of Indian history, as this victory laid the foundation for Muslim rule (Delhi Sultanate) in India.","memoryTip":"11-92 में गौरी ने पृथ्वीराज को 2 नंबर (हरा) कर दिया।","memoryTipEn":"1192 changed India''s destiny.","related":["Delhi Sultanate","Qutb ud-Din Aibak","Battle of Chandawar"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wn0GL0x2rpBZc0FiXeD2s', 'General Knowledge', 'चौसा का युद्ध (Battle of Chausa) 1539 में किनके बीच लड़ा गया था?', 'Between whom was the Battle of Chausa fought in 1539?', 'शेरशाह सूरी और हुमायूं', 'Sher Shah Suri and Humayun', 91, 0, '{"facts":["इस युद्ध में अफगान शासक शेरशाह सूरी ने मुगल सम्राट हुमायूं को बुरी तरह हराया था।","चौसा वर्तमान बिहार के बक्सर जिले में स्थित है।"],"factsEn":["In this battle, Afghan ruler Sher Shah Suri badly defeated Mughal Emperor Humayun.","Chausa is located in the present-day Buxar district of Bihar."],"explanationHi":"इस हार के बाद हुमायूं को गंगा नदी में कूदकर अपनी जान बचानी पड़ी, जहाँ एक भिश्ती (Nizam) ने उसकी मदद की। इसके बाद 1540 में कन्नौज के युद्ध में हुमायूं पूरी तरह हार कर भारत से निर्वासित हो गया।","explanationEn":"After this defeat, Humayun had to jump into the Ganges to save his life, aided by a water carrier. Following the Battle of Kannauj in 1540, he was completely exiled from India.","memoryTip":"शेरशाह ने हुमायूं का ''चौसा'' (जूस) निकाल दिया।","memoryTipEn":"Sher Shah shook Humayun at Chausa.","related":["Battle of Kannauj (Bilgram)","Suri Empire","Humayun''s Exile"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6cVIrLQPDsG8atNqagXwG', 'General Knowledge', 'गांधी-इरविन समझौता (Gandhi-Irwin Pact) किस वर्ष हुआ था?', 'In which year did the Gandhi-Irwin Pact take place?', '1931', '1931', 93, 0, '{"facts":["यह समझौता 5 मार्च 1931 को महात्मा गांधी और तत्कालीन वायसराय लॉर्ड इरविन के बीच हुआ था।","इसे ''दिल्ली समझौता'' (Delhi Pact) भी कहा जाता है।"],"factsEn":["The pact was signed on March 5, 1931, between Mahatma Gandhi and the then Viceroy Lord Irwin.","It is also known as the ''Delhi Pact''."],"explanationHi":"इस समझौते के तहत गांधीजी ने सविनय अवज्ञा आंदोलन (Civil Disobedience Movement) रोक दिया और लंदन में द्वितीय गोलमेज सम्मेलन (Second Round Table Conference) में भाग लेने के लिए सहमत हुए।","explanationEn":"Under this pact, Gandhiji suspended the Civil Disobedience Movement and agreed to participate in the Second Round Table Conference in London.","memoryTip":"31 में इरविन ने गांधीजी के सामने घुटने टेके।","memoryTipEn":"1931 paused the salt protests.","related":["Round Table Conferences","Civil Disobedience Movement","Salt Satyagraha"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Xz0bDGE4hxFd16sNnhSA9', 'General Knowledge', 'पूना पैक्ट (Poona Pact) 1932 किन दो नेताओं के बीच हुआ था?', 'Between which two leaders did the Poona Pact 1932 take place?', 'महात्मा गांधी और डॉ. बी.आर. अंबेडकर', 'Mahatma Gandhi and Dr. B.R. Ambedkar', 95, 0, '{"facts":["यह समझौता 24 सितंबर 1932 को यरवदा सेंट्रल जेल (पुणे) में हुआ था।","यह ब्रिटिश प्रधानमंत्री रामसे मैकडोनाल्ड के ''सांप्रदायिक पंचाट'' (Communal Award) के विरोध में था।"],"factsEn":["This agreement was signed on Sept 24, 1932, at Yerwada Central Jail (Pune).","It was in response to the ''Communal Award'' of British PM Ramsay MacDonald."],"explanationHi":"अंबेडकर ''दलित वर्गों'' (Depressed Classes) के लिए अलग निर्वाचन मंडल चाहते थे, लेकिन गांधीजी इसके खिलाफ आमरण अनशन पर बैठ गए। अंततः पूना पैक्ट के तहत अलग निर्वाचन मंडल की जगह आरक्षित सीटें (Reserved seats) देने पर सहमति बनी।","explanationEn":"Ambedkar wanted separate electorates for the ''Depressed Classes'', but Gandhi went on a fast unto death against it. Eventually, the Poona Pact agreed on reserved seats instead of separate electorates.","memoryTip":"पुणे की जेल में ''गांधी'' और ''अंबेडकर'' का पैक्ट हुआ।","memoryTipEn":"Poona Pact unified the electorates.","related":["Communal Award","Yerwada Jail","Separate Electorates"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UbVj9RqKlgn3NRpK7dtUw', 'General Knowledge', 'साइमन कमीशन (Simon Commission) भारत किस वर्ष आया था?', 'In which year did the Simon Commission arrive in India?', '1928', '1928', 92, 0, '{"facts":["इस कमीशन का असली नाम ''भारतीय वैधानिक आयोग'' (Indian Statutory Commission) था।","इसका गठन 1927 में ब्रिटेन में किया गया था और यह 1928 में भारत (बॉम्बे) पहुंचा।"],"factsEn":["The real name of this commission was the ''Indian Statutory Commission''.","It was formed in Britain in 1927 and arrived in India (Bombay) in 1928."],"explanationHi":"इस आयोग में सात ब्रिटिश सांसद थे और कोई भी भारतीय सदस्य नहीं था, इसलिए इसे ''श्वेत आयोग'' (White Commission) कहा गया और पूरे भारत में ''साइमन गो बैक'' के नारों के साथ इसका विरोध हुआ।","explanationEn":"The commission comprised seven British MPs and zero Indian members, leading it to be called the ''White Commission'' and sparking nationwide protests with ''Simon Go Back'' slogans.","memoryTip":"28 में ''साइमन'' गो बैक (वापस जाओ) का नारा लगा।","memoryTipEn":"1928 sent Simon back.","related":["Lala Lajpat Rai (Death during protest)","Government of India Act 1919","Nehru Report"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3IjqwMJo1jOZu90eWvNxv', 'General Knowledge', 'बांधवगढ़ राष्ट्रीय उद्यान मध्य प्रदेश के किस जिले में स्थित है?', 'Bandhavgarh National Park is located in which district of Madhya Pradesh?', 'उमरिया', 'Umaria', 96, 0, '{"facts":["यह उद्यान भारत में ''बाघों के सबसे अधिक घनत्व'' (Highest Tiger Density) के लिए विश्व प्रसिद्ध है।","इसे 1968 में राष्ट्रीय उद्यान घोषित किया गया था।"],"factsEn":["This park is world-famous for having the ''Highest Tiger Density'' in India.","It was declared a National Park in 1968."],"explanationHi":"यह स्थान ऐतिहासिक रूप से रीवा के महाराजाओं का शिकारगाह था। यहीं के जंगलों में ''सफेद बाघ'' (White Tigers) पहली बार देखे गए थे। इस उद्यान में एक प्राचीन ''बांधवगढ़ का किला'' भी है।","explanationEn":"Historically, it was the hunting ground of the Maharajas of Rewa. ''White Tigers'' were first discovered in these forests. The park also houses an ancient ''Bandhavgarh Fort''.","memoryTip":"''उम्र'' (उमरिया) भर बाघों को ''बांध'' (बांधवगढ़) कर नहीं रख सकते।","memoryTipEn":"Bandhavgarh boasts the best tiger spotting.","related":["Tiger Density","White Tiger (Mohan)","Rewa Maharajas"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('OFxFgwlB54xey7ybik-yq', 'General Knowledge', 'माधव राष्ट्रीय उद्यान मध्य प्रदेश में कहाँ स्थित है?', 'Where is Madhav National Park located in Madhya Pradesh?', 'शिवपुरी', 'Shivpuri', 90, 0, '{"facts":["यह उद्यान 1958 में स्थापित किया गया था।","राष्ट्रीय राजमार्ग NH-46 (पुराना NH-3) इस राष्ट्रीय उद्यान के बीच से होकर गुजरता है।"],"factsEn":["The park was established in 1958.","National Highway NH-46 (formerly NH-3) passes right through the middle of this park."],"explanationHi":"यह ग्वालियर के सिंधिया राजघराने (Scindia royal family) का शिकारगाह था। उद्यान के अंदर एक पहाड़ी पर सुंदर ''जॉर्ज कैसल'' (George Castle) बना हुआ है।","explanationEn":"It was the hunting preserve of the Scindia royal family of Gwalior. A beautiful building named ''George Castle'' is built on a hill inside the park.","memoryTip":"माधव (कृष्ण) और शिव (शिवपुरी) दोनों भगवान के नाम हैं।","memoryTipEn":"Madhav and Shiv are divine names.","related":["George Castle","Sankhya Sagar Lake","Scindia Dynasty"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dRoOk3_5PnplfsBU8SiTq', 'General Knowledge', 'पेंच राष्ट्रीय उद्यान मध्य प्रदेश के किन जिलों में फैला है?', 'Pench National Park is spread across which districts of Madhya Pradesh?', 'सिवनी और छिंदवाड़ा', 'Seoni and Chhindwara', 92, 0, '{"facts":["इसका नाम पेंच नदी (Pench River) के नाम पर रखा गया है, जो इस उद्यान के बीच से बहती है।","इस उद्यान को ''मोगली लैंड'' (Mowgli Land) भी कहा जाता है।"],"factsEn":["It is named after the Pench River, which flows through the middle of the park.","This park is also known as ''Mowgli Land''."],"explanationHi":"रुडयार्ड किपलिंग की विश्व प्रसिद्ध किताब ''द जंगल बुक'' (The Jungle Book) और इसके नायक मोगली की कहानी इसी पेंच राष्ट्रीय उद्यान के जंगलों से प्रेरित है।","explanationEn":"Rudyard Kipling''s world-famous book ''The Jungle Book'' and its protagonist Mowgli''s story are inspired by the forests of this Pench National Park.","memoryTip":"सिवनी और छिंदवाड़ा के बीच ''पेंच'' फंसा हुआ है।","memoryTipEn":"Pench is the true Jungle Book.","related":["The Jungle Book","Rudyard Kipling","Mowgli Utsav"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('puN2Ywvy_KpXOeZSiw605', 'General Knowledge', 'भारत का सबसे ऊँचा बांध कौनसा है?', 'Which is the highest dam in India?', 'टिहरी बांध (उत्तराखंड)', 'Tehri Dam (Uttarakhand)', 96, 0, '{"facts":["यह भागीरथी नदी (Bhagirathi River) पर बना हुआ है।","इसकी ऊंचाई 260.5 मीटर (855 फीट) है।"],"factsEn":["It is built on the Bhagirathi River.","Its height is 260.5 meters (855 feet)."],"explanationHi":"यह न केवल भारत का बल्कि दुनिया के सबसे ऊंचे बांधों में से एक है। यह एक ''रॉक और अर्थ-फिल'' (Earth and rock-fill) बांध है जो पनबिजली (Hydropower) पैदा करता है। (भाखड़ा बांध सबसे बड़ा गुरुत्वीय/Gravity बांध है)।","explanationEn":"It is not only India''s but one of the highest dams in the world. It is an earth and rock-fill dam generating hydropower. (Bhakra dam is the highest straight gravity dam).","memoryTip":"सबसे ऊपर टी (T) से ''टिहरी'' (Tehri) खड़ा है।","memoryTipEn":"Tehri towers above all.","related":["Bhagirathi River","Bhakra Nangal Dam","Hirakud Dam (Longest)"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ePh0RWXz5pw10XyTFGMm1', 'General Knowledge', 'भारत की सबसे बड़ी खारे पानी की झील (Saltwater Lake) कौनसी है?', 'Which is the largest saltwater lake in India?', 'चिल्का झील (ओडिशा)', 'Chilika Lake (Odisha)', 95, 0, '{"facts":["यह एक लैगून (Lagoon) झील है जो बंगाल की खाड़ी से जुड़ी है।","यह सर्दियों में प्रवासी पक्षियों के लिए भारतीय उपमहाद्वीप का सबसे बड़ा निवास स्थान है।"],"factsEn":["It is a lagoon lake connected to the Bay of Bengal.","It is the largest wintering ground for migratory birds on the Indian subcontinent."],"explanationHi":"भारत की सबसे बड़ी अंतर्देशीय (Inland) खारे पानी की झील ''सांभर झील'' (राजस्थान) है, लेकिन कुल मिलाकर ''चिल्का'' सबसे बड़ी खारे पानी की झील है।","explanationEn":"India''s largest inland saltwater lake is ''Sambhar Lake'' (Rajasthan), but overall ''Chilika'' is the largest saltwater lake (coastal).","memoryTip":"ओडिशा के तट पर ''चील'' (चिल्का) उड़ती है।","memoryTipEn":"Chilika is a massive marine lagoon.","related":["Lagoon","Wular Lake (Freshwater)","Sambhar Lake"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7UhYvG1oalDKM7WGX24H8', 'General Knowledge', 'जनसंख्या की दृष्टि से भारत का सबसे छोटा राज्य कौनसा है?', 'Which is the smallest state in India by population?', 'सिक्किम', 'Sikkim', 93, 0, '{"facts":["2011 की जनगणना के अनुसार सिक्किम की जनसंख्या मात्र 6 लाख के आसपास है।","क्षेत्रफल (Area) की दृष्टि से सबसे छोटा राज्य ''गोवा'' है।"],"factsEn":["As per the 2011 census, Sikkim''s population is merely around 6 lakhs.","By area, the smallest state is ''Goa''."],"explanationHi":"सिक्किम हिमालय में स्थित है और तीन देशों (चीन, भूटान और नेपाल) के साथ अंतर्राष्ट्रीय सीमा साझा करता है। यह भारत का पहला ''जैविक राज्य'' (Organic State) भी है।","explanationEn":"Sikkim is nestled in the Himalayas and shares international borders with three countries (China, Bhutan, and Nepal). It is also India''s first ''Organic State''.","memoryTip":"जनसंख्या ''सिक्के'' (सिक्किम) जितनी कम है।","memoryTipEn":"Sikkim has a small sum of citizens.","related":["Goa (Smallest by Area)","Uttar Pradesh (Largest by Population)","Organic Farming"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9RjnA8PaFOABQ76eXbtLC', 'General Knowledge', 'भारत में सबसे अधिक साक्षरता दर (Literacy Rate) वाला राज्य कौनसा है?', 'Which state has the highest literacy rate in India?', 'केरल', 'Kerala', 94, 0, '{"facts":["2011 की जनगणना के अनुसार केरल की साक्षरता दर 94% है।","सबसे कम साक्षरता दर (Lowest literacy rate) वाला राज्य बिहार (61.8%) है।"],"factsEn":["According to the 2011 census, Kerala''s literacy rate is 94%.","The state with the lowest literacy rate is Bihar (61.8%)."],"explanationHi":"केरल ने शिक्षा और स्वास्थ्य सेवाओं में भारी निवेश किया है। यह राज्य पुरुषों और महिलाओं दोनों के लिए उच्च साक्षरता दर बनाए हुए है।","explanationEn":"Kerala has heavily invested in education and healthcare services. The state maintains high literacy rates for both men and women.","memoryTip":"केरल के लोग ''किताबें'' (साक्षरता) बहुत पढ़ते हैं।","memoryTipEn":"Kerala keeps the highest literacy.","related":["2011 Census","Bihar (Lowest Literacy)","Sex Ratio (Kerala is highest)"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HGRwQsIIDmEyJeHaly1g5', 'General Knowledge', 'भारतीय अंतरिक्ष कार्यक्रम का जनक (Father of Indian Space Program) किसे माना जाता है?', 'Who is considered the Father of the Indian Space Program?', 'डॉ. विक्रम साराभाई', 'Dr. Vikram Sarabhai', 96, 0, '{"facts":["उन्होंने 1969 में ISRO (Indian Space Research Organisation) की स्थापना में महत्वपूर्ण भूमिका निभाई थी।","अहमदाबाद में भौतिक अनुसंधान प्रयोगशाला (Physical Research Laboratory) की स्थापना भी उन्होंने ही की थी।"],"factsEn":["He played a crucial role in establishing ISRO in 1969.","He also founded the Physical Research Laboratory (PRL) in Ahmedabad."],"explanationHi":"वे एक महान दूरदर्शी थे जिन्होंने राष्ट्र के विकास में अंतरिक्ष विज्ञान के महत्व को समझा। भारत के मून लैंडर ''चंद्रयान'' के विक्रम लैंडर का नाम उन्हीं के नाम पर रखा गया है।","explanationEn":"He was a great visionary who understood the importance of space science in national development. The Vikram lander of India''s Moon mission ''Chandrayaan'' is named after him.","memoryTip":"अंतरिक्ष में भारत का ''पराक्रम'' (विक्रम) उन्होंने ही दिखाया।","memoryTipEn":"Vikram envisioned the space frontier.","related":["ISRO","A. P. J. Abdul Kalam","Chandrayaan"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('sHElWQEwaCswiVDfJFo4g', 'General Knowledge', 'भारतीय परमाणु कार्यक्रम का जनक किसे कहा जाता है?', 'Who is called the Father of the Indian Nuclear Program?', 'डॉ. होमी जहाँगीर भाभा', 'Dr. Homi J. Bhabha', 95, 0, '{"facts":["वे भारत के परमाणु ऊर्जा आयोग के पहले अध्यक्ष थे।","उन्होंने मुंबई में ''टाटा इंस्टीट्यूट ऑफ फंडामेंटल रिसर्च'' (TIFR) की स्थापना की।"],"factsEn":["He was the first Chairman of the Atomic Energy Commission of India.","He founded the ''Tata Institute of Fundamental Research'' (TIFR) in Mumbai."],"explanationHi":"उनके नेतृत्व में भारत ने परमाणु ऊर्जा के शांतिपूर्ण उपयोग की दिशा में काम शुरू किया। उनके सम्मान में ही ''BARC'' (Bhabha Atomic Research Centre) का नाम रखा गया है।","explanationEn":"Under his leadership, India began working towards the peaceful use of nuclear energy. The ''BARC'' is named in his honor.","memoryTip":"परमाणु का ''भाभा'' (भभका/धमाका) डॉ. भाभा के नाम में है।","memoryTipEn":"Bhabha built the atomic base.","related":["BARC","Department of Atomic Energy","Nuclear Reactor Apsara"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IUKdnDsZKzTii41B8xyT6', 'General Science', 'विद्युत बल्ब में मुख्य रूप से कौनसी गैस भरी जाती है?', 'Which gas is mainly filled in an electric bulb?', 'आर्गन (तथा नाइट्रोजन)', 'Argon (and Nitrogen)', 93, 0, '{"facts":["आर्गन एक अक्रिय गैस (Inert Gas) है, जो अन्य तत्वों के साथ प्रतिक्रिया नहीं करती।","बल्ब का फिलामेंट टंगस्टन (Tungsten) का बना होता है।"],"factsEn":["Argon is an Inert Gas that does not react with other elements.","The filament of the bulb is made of Tungsten."],"explanationHi":"अगर बल्ब में ऑक्सीजन (हवा) होगी, तो उच्च तापमान पर टंगस्टन फिलामेंट तुरंत जलकर टूट जाएगा। आर्गन और नाइट्रोजन फिलामेंट को जलने से रोककर बल्ब की उम्र बढ़ाते हैं।","explanationEn":"If the bulb contains oxygen (air), the hot tungsten filament will immediately burn out. Argon and nitrogen prevent the filament from burning, increasing the bulb''s lifespan.","memoryTip":"बल्ब के अंदर की गैस ''आर्गन'' (आग न) लगने देती है।","memoryTipEn":"Argon averts the fire.","related":["Tungsten","Inert Gases","Incandescent Bulb"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1v0ceWt6dVZsQwX9cssLD', 'General Science', 'अग्निशामक यंत्रों (Fire Extinguishers) में कौनसी गैस का प्रयोग होता है?', 'Which gas is used in fire extinguishers?', 'कार्बन डाइऑक्साइड (CO2)', 'Carbon Dioxide (CO2)', 94, 0, '{"facts":["CO2 एक गैर-ज्वलनशील गैस (non-flammable gas) है और ऑक्सीजन से भारी होती है।","यह आग पर कंबल की तरह फैल जाती है, जिससे आग को ऑक्सीजन मिलना बंद हो जाता है।"],"factsEn":["CO2 is a non-flammable gas and is heavier than oxygen.","It spreads over the fire like a blanket, cutting off the oxygen supply to the fire."],"explanationHi":"ऑक्सीजन कट जाने पर आग तुरंत बुझ जाती है। CO2 का प्रयोग बिजली की आग (Electrical fires) बुझाने के लिए विशेष रूप से सुरक्षित है क्योंकि यह विद्युत कुचालक है।","explanationEn":"Cutting off oxygen immediately extinguishes the fire. CO2 is particularly safe for putting out electrical fires because it does not conduct electricity.","memoryTip":"ऑक्सीजन आग जलाती है, CO2 आग बुझाती है।","memoryTipEn":"CO2 chokes the fire.","related":["Combustion","Dry Ice","Electrical Fires"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('okuDaO1MvU84wJkKcVmrz', 'General Science', 'प्रकृति में सबसे हल्की धातु (Lightest metal) कौनसी है?', 'Which is the lightest metal in nature?', 'लिथियम (Lithium)', 'Lithium', 92, 0, '{"facts":["लिथियम का प्रतीक ''Li'' और परमाणु क्रमांक (Atomic number) 3 है।","यह इतनी हल्की है कि पानी पर तैर सकती है।"],"factsEn":["The symbol for Lithium is ''Li'' and its atomic number is 3.","It is so light that it can float on water."],"explanationHi":"लिथियम का उपयोग मुख्य रूप से मोबाइल फोन, लैपटॉप और इलेक्ट्रिक वाहनों (EVs) की रिचार्जेबल बैटरी (Lithium-ion batteries) बनाने में किया जाता है।","explanationEn":"Lithium is primarily used in making rechargeable batteries (Lithium-ion batteries) for mobile phones, laptops, and Electric Vehicles (EVs).","memoryTip":"हल्का ''ली'' (लिथियम) बैटरी में इस्तेमाल होता है।","memoryTipEn":"Lithium lifts the battery power lightly.","related":["Alkali Metals","Lithium-ion Battery","Osmium (Heaviest Metal)"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aOxW57c14jK4d65eAaWrf', 'General Science', 'प्रकृति में सबसे भारी धातु (Heaviest metal) कौनसी है?', 'Which is the heaviest metal in nature?', 'ऑस्मियम (Osmium)', 'Osmium', 90, 0, '{"facts":["ऑस्मियम का प्रतीक ''Os'' और परमाणु क्रमांक 76 है।","यह प्राकृतिक रूप से पाया जाने वाला सबसे अधिक घनत्व (Densely packed) वाला तत्व है।"],"factsEn":["The symbol for Osmium is ''Os'' and its atomic number is 76.","It is the densest naturally occurring element."],"explanationHi":"इसका घनत्व शीशे (Lead) से दोगुना और पानी से लगभग 22.6 गुना अधिक होता है। इरिडियम (Iridium) घनत्व के मामले में इसके बहुत करीब है।","explanationEn":"Its density is twice that of lead and about 22.6 times that of water. Iridium is very close to it in terms of density.","memoryTip":"सबसे भारी चीज़ को ''औंस'' (Osmium) में मत मापो।","memoryTipEn":"Osmium outweighs them all.","related":["Iridium","Density","Lithium (Lightest Metal)"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jfk3m5aWm7SCDiUXSwbFt', 'General Science', 'सर्वाधिक आघातवर्ध्य (Malleable) धातु कौनसी है?', 'Which is the most malleable metal?', 'सोना (Gold)', 'Gold', 91, 0, '{"facts":["आघातवर्ध्यता (Malleability) वह गुण है जिसके कारण धातुओं को पीट-पीटकर पतली चादर (sheets) में बदला जा सकता है।","सोना (Au) सबसे अधिक ''तन्य'' (Ductile - तार खींचने की क्षमता) धातु भी है।"],"factsEn":["Malleability is the property that allows metals to be beaten into thin sheets.","Gold (Au) is also the most ''ductile'' metal (ability to be drawn into wires)."],"explanationHi":"1 ग्राम सोने से लगभग 2 किलोमीटर लंबा तार खींचा जा सकता है और इसकी इतनी पतली चादर बनाई जा सकती है कि वह पारदर्शी हो जाए।","explanationEn":"A wire about 2 kilometers long can be drawn from 1 gram of gold, and it can be beaten into a sheet so thin that it becomes translucent.","memoryTip":"सोने के गहने किसी भी आकार में ''मुड़'' जाते हैं।","memoryTipEn":"Gold gives the thinnest foil.","related":["Ductility","Metals properties","Silver (Ag)"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wGoNpgD-lqfYpIvtmVX9y', 'General Science', 'जर्मन सिल्वर (German Silver) किन धातुओं की मिश्र धातु है?', 'German Silver is an alloy of which metals?', 'तांबा, जस्ता और निकेल', 'Copper, Zinc, and Nickel', 95, 0, '{"facts":["महत्वपूर्ण तथ्य: ''जर्मन सिल्वर'' में 0% सिल्वर (चांदी) होता है।","इसकी चांदी जैसी सफेद चमक के कारण इसे यह नाम दिया गया है।"],"factsEn":["Crucial Fact: ''German Silver'' contains 0% silver.","It is named so because of its silvery-white appearance."],"explanationHi":"प्रतियोगी परीक्षाओं में यह सवाल अक्सर छात्रों को भ्रमित करने के लिए पूछा जाता है। इसमें आमतौर पर 60% तांबा, 20% जस्ता और 20% निकेल होता है।","explanationEn":"This question is frequently asked in competitive exams to confuse students. It generally consists of 60% copper, 20% zinc, and 20% nickel.","memoryTip":"जर्मन सिल्वर ''चांदी'' नहीं है, बस तांबा, जस्ता और निकेल का ''धोखा'' है।","memoryTipEn":"German Silver is a silvery scam; no silver in it.","related":["Brass (Cu + Zn)","Bronze (Cu + Sn)","Alloys"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nsCgkuH7CT0ICwIJJtl5D', 'General Knowledge', 'कूनो राष्ट्रीय उद्यान (Kuno National Park), जहाँ अफ्रीकी चीते लाए गए हैं, मध्य प्रदेश के किस जिले में है?', 'Kuno National Park, where African cheetahs have been introduced, is in which district of MP?', 'श्योपुर (Sheopur)', 'Sheopur', 98, 0, '{"facts":["2022 में भारत सरकार द्वारा ''प्रोजेक्ट चीता'' (Project Cheetah) के तहत यहाँ नामीबिया और दक्षिण अफ्रीका से चीते लाए गए।","भारत में चीते 1952 में विलुप्त (Extinct) घोषित कर दिए गए थे।"],"factsEn":["Under ''Project Cheetah'' in 2022, cheetahs from Namibia and South Africa were relocated here by the Govt of India.","Cheetahs were declared extinct in India in 1952."],"explanationHi":"कूनो मध्य भारत के विंध्यन पहाड़ियों में स्थित है। इसके खुले घास के मैदान (Grasslands) चीतों के दौड़ने और शिकार करने के लिए एक आदर्श वातावरण प्रदान करते हैं।","explanationEn":"Kuno is situated in the Vindhyan hills of central India. Its open grasslands provide an ideal environment for cheetahs to run and hunt.","memoryTip":"''श्यो''पुर में चीतों का ''शो'' (Show) चल रहा है।","memoryTipEn":"Sheopur shelters the speedy cheetahs.","related":["Project Cheetah","Namibia","Extinction of Cheetah in India"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WhWMuSCgfupPBH195jQbO', 'General Knowledge', 'तवा नदी किसकी प्रमुख सहायक नदी है?', 'Tawa River is a major tributary of which river?', 'नर्मदा नदी', 'Narmada River', 93, 0, '{"facts":["तवा नदी सतपुड़ा रेंज (पचमढ़ी के पास) से निकलती है।","होशंगाबाद (नर्मदापुरम) जिले में तवा नदी नर्मदा में मिल जाती है।"],"factsEn":["The Tawa river originates from the Satpura range (near Pachmarhi).","The Tawa river joins the Narmada in Hoshangabad (Narmadapuram) district."],"explanationHi":"तवा नदी पर ''तवा बांध'' (Tawa Dam) बना है, जो मध्य प्रदेश के सबसे बड़े जलाशयों में से एक है। तवा और नर्मदा के संगम पर ''बांद्राभान'' (Bandrabhan) स्थित है।","explanationEn":"The ''Tawa Dam'' is built on the Tawa river, which is one of the largest reservoirs in MP. ''Bandrabhan'' is located at the confluence of Tawa and Narmada.","memoryTip":"''तवा'' (गरम) को ''नर्म'' (नर्मदा) पानी में डाल दिया।","memoryTipEn":"Tawa meets the Narmada.","related":["Tawa Dam","Narmada Tributaries","Pachmarhi"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7n3aiOqbfESuE04tPn7cd', 'General Knowledge', 'मध्य प्रदेश का सबसे लंबा राजकीय राजमार्ग (State Highway) कौनसा है?', 'Which is the longest State Highway in Madhya Pradesh?', 'SH-19', 'SH-19', 87, 0, '{"facts":["यह राजमार्ग उत्तर प्रदेश की सीमा (जैतपुर) से शुरू होकर महाराष्ट्र की सीमा (छिंदवाड़ा) तक जाता है।","इसकी कुल लंबाई लगभग 743 किलोमीटर है।"],"factsEn":["This highway starts from the Uttar Pradesh border (Jaitpur) and goes up to the Maharashtra border (Chhindwara).","Its total length is approximately 743 kilometers."],"explanationHi":"यह मध्य प्रदेश के कई प्रमुख जिलों से होकर गुजरता है। (राष्ट्रीय राजमार्गों में NH-46 पूरी तरह से एमपी के भीतर सबसे लंबा है)।","explanationEn":"It passes through several major districts of MP. (Among National Highways, NH-46 is the longest entirely within MP).","memoryTip":"एमपी का ''19'' (उन्नीस) नंबर का हाईवे सबसे लंबा है।","memoryTipEn":"SH-19 stretches the state.","related":["NH-44 (Longest NH in India)","NH-46 (Longest NH inside MP)","State Highways"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('A_3KDM2w2L4yWrKhIfUb8', 'General Knowledge', 'चंदेरी का युद्ध (1528) किनके बीच हुआ था?', 'Between whom was the Battle of Chanderi (1528) fought?', 'बाबर और मेदिनी राय', 'Babur and Medini Rai', 92, 0, '{"facts":["चंदेरी मध्य प्रदेश के अशोकनगर जिले में एक ऐतिहासिक शहर है।","इस युद्ध में मुग़ल सम्राट बाबर की जीत हुई थी।"],"factsEn":["Chanderi is a historical town in the Ashoknagar district of Madhya Pradesh.","Mughal Emperor Babur emerged victorious in this battle."],"explanationHi":"बाबर ने पानीपत (1526) और खानवा (1527) के बाद राजपूताना और मालवा पर नियंत्रण के लिए 1528 में मेदिनी राय (जो राणा सांगा के सहयोगी थे) पर हमला किया।","explanationEn":"After Panipat (1526) and Khanwa (1527), Babur attacked Medini Rai (an ally of Rana Sanga) in 1528 to gain control over Rajputana and Malwa.","memoryTip":"बाबर ने ''चंदेरी'' (चादर) फाड़कर ''मेदिनी'' को हराया।","memoryTipEn":"Babur conquered Chanderi in 1528.","related":["Battle of Khanwa","Babur''s Battles","Chanderi Fort"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('D7XcwJ0-Y-uOjPKvS73x0', 'General Knowledge', 'मध्य प्रदेश लोक सेवा आयोग (MPPSC) का मुख्यालय कहाँ है?', 'Where is the headquarters of the Madhya Pradesh Public Service Commission (MPPSC)?', 'इंदौर', 'Indore', 94, 0, '{"facts":["MPPSC का गठन 1 नवंबर 1956 को राज्य पुनर्गठन अधिनियम की धारा 118(3) के तहत किया गया था।","संविधान के भाग XIV (अनुच्छेद 315-323) में राज्य लोक सेवा आयोग का प्रावधान है।"],"factsEn":["MPPSC was constituted on Nov 1, 1956, under Section 118(3) of the States Reorganisation Act.","Part XIV (Articles 315-323) of the Constitution provides for a State Public Service Commission."],"explanationHi":"यह आयोग मध्य प्रदेश सरकार में सिविल सेवाओं (जैसे डिप्टी कलेक्टर, डीएसपी) के लिए राजपत्रित (Gazetted) अधिकारियों की भर्ती परीक्षा आयोजित करता है।","explanationEn":"This commission conducts recruitment exams for Gazetted officers for civil services (like Deputy Collector, DSP) in the MP Government.","memoryTip":"एमपी के अफ़सर ''इंदौर'' से चुनकर आते हैं।","memoryTipEn":"Indore initiates the administrators.","related":["UPSC","Article 315","Madhya Pradesh Government"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4H7aqoWoUyugsZRaqiS6X', 'General Knowledge', 'मध्य प्रदेश का ''सिंगापुर'' या ''भारत का डेट्रायट'' किसे कहा जाता है?', 'Which place is called the ''Singapore'' of MP or ''Detroit of India''?', 'पीथमपुर (धार)', 'Pithampur (Dhar)', 95, 0, '{"facts":["पीथमपुर मध्य प्रदेश के धार (Dhar) जिले में स्थित है।","यहाँ एक बहुत बड़ा ''विशेष आर्थिक क्षेत्र'' (Special Economic Zone - SEZ) (ऑटो क्लस्टर) है।"],"factsEn":["Pithampur is located in the Dhar district of Madhya Pradesh.","It houses a massive ''Special Economic Zone'' (SEZ) (Auto Cluster)."],"explanationHi":"डेट्रायट (अमेरिका) ऑटोमोबाइल उद्योग के लिए प्रसिद्ध है। पीथमपुर में भी कमर्शियल और यात्री वाहनों की सैकड़ों बड़ी निर्माण इकाइयाँ (Tata, Volvo Eicher, Force Motors) होने के कारण इसे ''भारत का डेट्रायट'' कहा जाता है।","explanationEn":"Detroit (USA) is famous for its automobile industry. Since Pithampur also has hundreds of large manufacturing units for commercial and passenger vehicles, it is called the ''Detroit of India''.","memoryTip":"''पीथमपुर'' में कारों के पहिए (ऑटोमोबाइल) घूमते हैं।","memoryTipEn":"Pithampur is the auto hub of MP.","related":["Automobile Industry","Special Economic Zone","Dhar District"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HEm0XEXZHbIryahCeW7vJ', 'General Knowledge', 'हबीबगंज रेलवे स्टेशन का नया नाम क्या रखा गया है?', 'What is the new name of Habibganj Railway Station?', 'रानी कमलापति रेलवे स्टेशन', 'Rani Kamlapati Railway Station', 96, 0, '{"facts":["यह स्टेशन भोपाल (मध्य प्रदेश) में स्थित है।","यह भारत का पहला ISO-प्रमाणित और निजी सार्वजनिक भागीदारी (PPP) मॉडल पर विकसित विश्व स्तरीय स्टेशन है।"],"factsEn":["This station is located in Bhopal (Madhya Pradesh).","It is India''s first ISO-certified and world-class station developed on the Public-Private Partnership (PPP) model."],"explanationHi":"गोंड रानी कमलापति के सम्मान में इसका नाम बदला गया। यह स्टेशन आधुनिक सुविधाओं (जैसे एयरपोर्ट) से लैस है।","explanationEn":"It was renamed in honor of the Gond queen Rani Kamlapati. The station is equipped with modern, airport-like facilities.","memoryTip":"हबीबगंज अब ''रानी'' का महल (रेलवे स्टेशन) बन गया है।","memoryTipEn":"Rani Kamlapati rules the rail hub.","related":["PPP Model","Gond Dynasty","Vande Bharat Express"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gY5o9RiPucSxz_QIil3xJ', 'General Knowledge', 'होशंगाबाद शहर का नया नाम क्या कर दिया गया है?', 'What is the new name of Hoshangabad city?', 'नर्मदापुरम', 'Narmadapuram', 93, 0, '{"facts":["फरवरी 2022 में मध्य प्रदेश सरकार ने आधिकारिक तौर पर इसका नाम बदल दिया।","यह शहर जीवनदायिनी ''नर्मदा नदी'' के तट पर स्थित है।"],"factsEn":["In February 2022, the MP Government officially changed its name.","The city is situated on the banks of the life-giving ''Narmada River''."],"explanationHi":"इस शहर का पुराना नाम मालवा के शासक ''होशंग शाह'' के नाम पर रखा गया था। यहाँ का ''सेठानी घाट'' बहुत प्रसिद्ध है।","explanationEn":"The city''s old name was based on the Malwa ruler ''Hoshang Shah''. The ''Sethani Ghat'' here is very famous.","memoryTip":"होशंगाबाद की पहचान नर्मदा है, इसलिए नाम नर्मदापुरम।","memoryTipEn":"Hoshangabad honors the Narmada.","related":["Narmada River","Hoshang Shah","Sethani Ghat"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UItaCGJQ-h-Y5GODdumlH', 'General Knowledge', 'पातालकोट घाटी मध्य प्रदेश के किस जिले में है?', 'Patalkot Valley is in which district of Madhya Pradesh?', 'छिंदवाड़ा', 'Chhindwara', 92, 0, '{"facts":["यह एक गहरी (घोड़े की नाल के आकार की) घाटी है जो सतपुड़ा पहाड़ियों में स्थित है।","यहाँ की ''भारिया'' (Bharia) जनजाति बाहरी दुनिया से पूरी तरह कट कर रहने के लिए जानी जाती है।"],"factsEn":["It is a deep (horseshoe-shaped) valley located in the Satpura hills.","The ''Bharia'' tribe here is known for living completely cut off from the outside world."],"explanationHi":"यह घाटी इतनी गहरी है कि इसके कई हिस्सों में सूरज की रोशनी बहुत कम समय के लिए पहुंचती है। भारिया जनजाति औषधीय जड़ी-बूटियों (Medicinal herbs) का असीम ज्ञान रखती है।","explanationEn":"The valley is so deep that sunlight reaches many parts of it for only a short duration. The Bharia tribe holds immense knowledge of medicinal herbs.","memoryTip":"छिंदवाड़ा (छेद) के रास्ते ''पाताल'' (पातालकोट) में जाते हैं।","memoryTipEn":"Patalkot is the hidden deep of Chhindwara.","related":["Bharia Tribe","Chhindwara","Satpura Range"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xt7j2F3tQWQaCvXCdrMuy', 'General Knowledge', 'मध्य प्रदेश का ''मोगली लैंड'' किसे कहा जाता है?', 'What is known as the ''Mowgli Land'' of Madhya Pradesh?', 'पेंच राष्ट्रीय उद्यान', 'Pench National Park', 94, 0, '{"facts":["यह उद्यान सिवनी (Seoni) और छिंदवाड़ा जिलों में स्थित है।","रुडयार्ड किपलिंग की 1894 की प्रसिद्ध किताब ''द जंगल बुक'' (The Jungle Book) इसी जंगल से प्रेरित थी।"],"factsEn":["This park is located in the Seoni and Chhindwara districts.","Rudyard Kipling''s famous 1894 book ''The Jungle Book'' was inspired by this forest."],"explanationHi":"यहाँ हर साल पर्यटन को बढ़ावा देने के लिए ''मोगली उत्सव'' (Mowgli Utsav) आयोजित किया जाता है। पेंच नदी इस पार्क के बीच से बहती है।","explanationEn":"A ''Mowgli Utsav'' is organized here every year to promote tourism. The Pench River flows through the middle of this park.","memoryTip":"मोगली के ''पेंच'' (पेंच उद्यान) शेरखान से भिड़ गए।","memoryTipEn":"Pench is the home of Mowgli.","related":["The Jungle Book","Seoni","Rudyard Kipling"]}', 'published', 1776097496, 1776097496);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0doZ-pvTLA0kg9MADo3ne', 'General Knowledge', 'स्वर कोकिला लता मंगेशकर का जन्म मध्य प्रदेश के किस शहर में हुआ था?', 'In which city of Madhya Pradesh was the Melody Queen Lata Mangeshkar born?', 'इंदौर', 'Indore', 98, 0, '{"facts":["लता मंगेशकर का जन्म 28 सितंबर 1929 को इंदौर में हुआ था।","उन्हें 2001 में भारत के सर्वोच्च नागरिक सम्मान ''भारत रत्न'' से सम्मानित किया गया था।"],"factsEn":["Lata Mangeshkar was born on September 28, 1929, in Indore.","She was awarded India''s highest civilian honor, the ''Bharat Ratna'', in 2001."],"explanationHi":"उन्होंने 36 से अधिक भारतीय भाषाओं में हजारों गीत गाए। इंदौर में उनके सम्मान में एक संगीत अकादमी और संग्रहालय भी स्थापित किया जा रहा है।","explanationEn":"She sang thousands of songs in over 36 Indian languages. A music academy and museum are being established in Indore in her honor.","memoryTip":"लता जी के सुरों का ''दौर'' (इंदौर) कभी खत्म नहीं होगा।","memoryTipEn":"Indore birthed India''s voice.","related":["Bharat Ratna","Playback Singing","Asha Bhosle"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HekpTGfeyi93-Oyiq7_QI', 'General Knowledge', 'प्रसिद्ध पार्श्व गायक किशोर कुमार का जन्म मध्य प्रदेश में कहाँ हुआ था?', 'Where was the famous playback singer Kishore Kumar born in Madhya Pradesh?', 'खंडवा', 'Khandwa', 95, 0, '{"facts":["उनका असली नाम आभास कुमार गांगुली था।","खंडवा में उनकी याद में ''किशोर कुमार स्मारक'' स्थित है।"],"factsEn":["His real name was Abhas Kumar Ganguly.","A ''Kishore Kumar Memorial'' is situated in Khandwa in his memory."],"explanationHi":"किशोर कुमार न केवल एक महान गायक थे, बल्कि एक अभिनेता, निर्देशक और निर्माता भी थे। मध्य प्रदेश सरकार उनके नाम पर ''राष्ट्रीय किशोर कुमार सम्मान'' देती है।","explanationEn":"Kishore Kumar was not only a great singer but also an actor, director, and producer. The MP government awards the ''National Kishore Kumar Samman'' in his name.","memoryTip":"किशोर कुमार की आवाज़ का कोई ''खंडन'' (खंडवा) नहीं कर सकता।","memoryTipEn":"Khandwa''s Kishore is the king of yodeling.","related":["National Kishore Kumar Samman","Abhas Kumar Ganguly","Bollywood"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('28nNkPED48B7bXYe9zr2v', 'General Knowledge', 'नोबेल शांति पुरस्कार से सम्मानित कैलाश सत्यार्थी मध्य प्रदेश के किस जिले से हैं?', 'Nobel Peace Prize laureate Kailash Satyarthi is from which district of Madhya Pradesh?', 'विदिशा', 'Vidisha', 97, 0, '{"facts":["उन्होंने ''बचपन बचाओ आंदोलन'' (BBA) की स्थापना की।","उन्हें 2014 में मलाला यूसुफजई के साथ संयुक्त रूप से नोबेल शांति पुरस्कार मिला था।"],"factsEn":["He founded the ''Bachpan Bachao Andolan'' (BBA).","He jointly received the Nobel Peace Prize in 2014 along with Malala Yousafzai."],"explanationHi":"सत्यार्थी ने बाल श्रम (Child Labour) के खिलाफ एक वैश्विक अभियान चलाया और हजारों बच्चों को कारखानों से मुक्त कराया।","explanationEn":"Satyarthi led a global campaign against child labour and rescued thousands of children from factories.","memoryTip":"कैलाश जी ने ''विदिशा'' (दिशा) दिखाई और बचपन बचाया।","memoryTipEn":"Vidisha''s visionary saved childhoods.","related":["Bachpan Bachao Andolan","Nobel Peace Prize 2014","Child Labour"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IRae5HEgz0y9_5QJ0cMwg', 'General Knowledge', 'उदयगिरि की गुफाएँ (Udayagiri Caves) मध्य प्रदेश के किस जिले में स्थित हैं?', 'In which district of Madhya Pradesh are the Udayagiri Caves located?', 'विदिशा', 'Vidisha', 94, 0, '{"facts":["ये गुफाएँ गुप्त काल (Gupta Empire) के दौरान (चौथी-पांचवीं शताब्दी में) बनाई गई थीं।","यहाँ गुफा संख्या 5 में भगवान विष्णु के ''वराह अवतार'' की एक विशाल और प्रसिद्ध मूर्ति है।"],"factsEn":["These caves were built during the Gupta Empire (in the 4th-5th century).","Cave No. 5 here contains a massive and famous sculpture of Lord Vishnu''s ''Varaha Avatar''."],"explanationHi":"ये कुल 20 गुफाएँ हैं, जिनमें से 1 और 20 जैन धर्म से संबंधित हैं, और बाकी हिंदू धर्म से।","explanationEn":"There are a total of 20 caves, out of which 1 and 20 belong to Jainism, and the rest to Hinduism.","memoryTip":"सूर्य का ''उदय'' हर ''दिशा'' (विदिशा) से दिखता है।","memoryTipEn":"Udayagiri unveils the Varaha in Vidisha.","related":["Gupta Period","Varaha Avatar","Beshnagar"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xR5H3SP-HH80Pe-16pm9B', 'General Knowledge', 'भरहुत स्तूप (Bharhut Stupa) के अवशेष मध्य प्रदेश के किस जिले में पाए गए थे?', 'The remains of the Bharhut Stupa were found in which district of Madhya Pradesh?', 'सतना', 'Satna', 93, 0, '{"facts":["इसकी खोज 1873 में अलेक्जेंडर कनिंघम (Alexander Cunningham) ने की थी।","मूल रूप से इस स्तूप का निर्माण मौर्य काल में हुआ था, लेकिन शुंग काल (Shunga period) में इसके तोरण द्वार जोड़े गए।"],"factsEn":["It was discovered in 1873 by Alexander Cunningham.","Originally built during the Mauryan period, its gateways were added during the Shunga period."],"explanationHi":"आज यह स्तूप अपने मूल स्थान पर नहीं है; इसके बचे हुए नक्काशीदार द्वार और रेलिंग कोलकाता के भारतीय संग्रहालय (Indian Museum) में रखे गए हैं।","explanationEn":"Today, this stupa is not at its original site; its surviving carved gateways and railings are housed in the Indian Museum, Kolkata.","memoryTip":"''भर'' (भरहुत) कर ''सत्तू'' (सतना) खाया।","memoryTipEn":"Satna safeguarded the Shunga stupa.","related":["Alexander Cunningham","Shunga Dynasty","Buddhist Architecture"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8J4va-kN9ybJYwM_T3r_i', 'General Knowledge', 'सती प्रथा का पहला पुरातात्विक साक्ष्य (Archaeological Evidence) किस अभिलेख से मिलता है?', 'From which inscription is the first archaeological evidence of the Sati system found?', 'एरण अभिलेख (सागर)', 'Eran Inscription (Sagar)', 96, 0, '{"facts":["यह अभिलेख 510 ईस्वी (गुप्त काल) का है।","एरण मध्य प्रदेश के सागर जिले में बीना नदी के तट पर स्थित है।"],"factsEn":["This inscription dates back to 510 AD (Gupta period).","Eran is situated on the banks of the Bina River in the Sagar district of Madhya Pradesh."],"explanationHi":"इस अभिलेख में गुप्त सम्राट भानुगुप्त के सेनापति गोपराज की मृत्यु और उनकी पत्नी के सती होने का उल्लेख है।","explanationEn":"This inscription mentions the death of Goparaja, commander of Gupta emperor Bhanugupta, and his wife committing Sati.","memoryTip":"एरण (Sagar) के अभिलेख से ''सती'' का ''रण'' (कष्ट) पता चला।","memoryTipEn":"Eran evidences the earliest Sati.","related":["Bhanugupta","Gupta Empire","Sati System"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jWjD0p1AiteA_cAypcyyP', 'General Knowledge', 'ग्वालियर स्थित ''गुजरी महल'' (Gujari Mahal) का निर्माण किसने करवाया था?', 'Who built the ''Gujari Mahal'' located in Gwalior?', 'राजा मानसिंह तोमर', 'King Man Singh Tomar', 95, 0, '{"facts":["इसे 15वीं शताब्दी में रानी मृगनयनी (Mrignayani) के लिए बनवाया गया था।","आज यह महल एक राज्य पुरातात्विक संग्रहालय (State Archaeological Museum) में तब्दील हो चुका है।"],"factsEn":["It was built in the 15th century for Queen Mrignayani.","Today, this palace has been converted into a State Archaeological Museum."],"explanationHi":"रानी मृगनयनी गुज्जर जाति की थीं, इसलिए इस महल का नाम ''गुजरी महल'' रखा गया। यहाँ शालभंजिका (Shalabhanjika) की प्रसिद्ध मूर्ति रखी है।","explanationEn":"Queen Mrignayani belonged to the Gujjar caste, hence the palace was named ''Gujari Mahal''. The famous sculpture of Shalabhanjika is kept here.","memoryTip":"मानसिंह ने अपनी ''गुजरी'' रानी के लिए महल बनाया।","memoryTipEn":"Man Singh made a monument for Mrignayani.","related":["Gwalior Fort","Mrignayani","Tomar Dynasty"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('VI9uYiSefM3qqnuY0w5_2', 'General Knowledge', '''हिंडोला महल'' (Hindola Mahal) मध्य प्रदेश के किस ऐतिहासिक स्थल पर स्थित है?', '''Hindola Mahal'' is located at which historical site in Madhya Pradesh?', 'मांडू (धार)', 'Mandu (Dhar)', 92, 0, '{"facts":["हिंडोला महल का अर्थ ''झूलता हुआ महल'' (Swinging Palace) है।","इसकी दीवारें 77 डिग्री के कोण पर झुकी हुई हैं, जिससे यह झूलता हुआ प्रतीत होता है।"],"factsEn":["Hindola Mahal translates to ''Swinging Palace''.","Its walls are slanted at a 77-degree angle, giving it the illusion of swinging."],"explanationHi":"यह महल मालवा के सुल्तानों के दरबार (Audience hall) के रूप में इस्तेमाल किया जाता था। मांडू अपने ''जहाज महल'' के लिए भी प्रसिद्ध है।","explanationEn":"This palace was used as an audience hall by the Sultans of Malwa. Mandu is also famous for its ''Jahaz Mahal''.","memoryTip":"मांडू में महल ''हिंडोला'' (झूले) की तरह झूलता है।","memoryTipEn":"Mandu makes the walls swing (Hindola).","related":["Mandu","Jahaz Mahal","Hoshang Shah"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FLSFsP2AyN8mpVHtrXMrK', 'General Knowledge', 'इंदौर स्थित ''राजवाड़ा महल'' (Rajwada Palace) का निर्माण किस राजवंश ने करवाया था?', 'Which dynasty built the ''Rajwada Palace'' located in Indore?', 'होल्कर राजवंश', 'Holkar Dynasty', 94, 0, '{"facts":["इसका निर्माण 1747 ईस्वी में मल्हार राव होल्कर ने शुरू करवाया था।","यह मराठा, मुगल और फ्रांसीसी वास्तुकला (Architecture) का एक शानदार मिश्रण है।"],"factsEn":["Its construction was started in 1747 AD by Malhar Rao Holkar.","It is a magnificent blend of Maratha, Mughal, and French architecture."],"explanationHi":"यह एक 7 मंजिला भव्य इमारत है। राजवाड़ा इंदौर शहर की पहचान और एक प्रमुख पर्यटन स्थल है।","explanationEn":"It is a grand 7-story building. Rajwada is the identity of Indore city and a major tourist attraction.","memoryTip":"होलकरों का ''राज'' राजवाड़ा में चलता था।","memoryTipEn":"Holkars hosted at Rajwada.","related":["Malhar Rao Holkar","Ahilyabai Holkar","Lal Bagh Palace"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('In-SrtwUSyaxrpiUWFw-L', 'General Knowledge', 'एशिया की सबसे बड़ी मस्जिदों में से एक ''ताज-उल-मसाजिद'' (Taj-ul-Masajid) कहाँ स्थित है?', 'Where is ''Taj-ul-Masajid'', one of the largest mosques in Asia, located?', 'भोपाल', 'Bhopal', 95, 0, '{"facts":["इसका निर्माण भोपाल की तीसरी महिला शासिका ''शाहजहाँ बेगम'' ने शुरू करवाया था।","''ताज-उल-मसाजिद'' का अर्थ है ''मस्जिदों का ताज'' (Crown Among Mosques)।"],"factsEn":["Its construction was started by ''Shah Jahan Begum'', the third female ruler of Bhopal.","''Taj-ul-Masajid'' translates to ''Crown Among Mosques''."],"explanationHi":"यह भारत की सबसे बड़ी मस्जिद (बैठने की क्षमता के आधार पर) मानी जाती है। इसमें गुलाबी बलुआ पत्थर और शानदार सफेद गुंबद हैं।","explanationEn":"It is considered the largest mosque in India (by seating capacity). It features pink sandstone and magnificent white domes.","memoryTip":"भोपाल के नवाबों का ''ताज'' यह मस्जिद है।","memoryTipEn":"Taj-ul-Masajid towers over Bhopal.","related":["Shah Jahan Begum","Dhai Seedi Ki Masjid (Smallest Mosque, also in Bhopal)","Bhopal Nawabs"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nFdAgw3VO7AFeofvSJsRw', 'General Knowledge', 'मध्य प्रदेश का सबसे बड़ा भौतिक भू-भाग (Physical Division) कौनसा है?', 'Which is the largest physical division of Madhya Pradesh?', 'मालवा का पठार (Malwa Plateau)', 'Malwa Plateau', 96, 0, '{"facts":["यह मध्य प्रदेश के कुल क्षेत्रफल का लगभग 28% हिस्सा कवर करता है।","मालवा का पठार काली मिट्टी (Black Soil) से ढका हुआ है, जो ज्वालामुखीय बेसाल्ट चट्टानों से बनी है।"],"factsEn":["It covers about 28% of the total area of Madhya Pradesh.","The Malwa Plateau is covered with Black Soil formed from volcanic basalt rocks."],"explanationHi":"इस पठार की काली मिट्टी कपास (Cotton) और सोयाबीन (Soybean) की खेती के लिए अत्यधिक उपजाऊ है। कर्क रेखा इसके मध्य से गुजरती है।","explanationEn":"The black soil of this plateau is highly fertile for the cultivation of cotton and soybean. The Tropic of Cancer passes through its middle.","memoryTip":"एमपी का सबसे ज्यादा ''माल'' (पैसा/उपज) ''मालवा'' से आता है।","memoryTipEn":"Malwa makes the most of MP''s map.","related":["Black Soil","Soybean Production","Vindhyan Range"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('k-Ls1dsZCR_ZJh-31kGpq', 'General Knowledge', 'मध्य प्रदेश का सबसे छोटा राष्ट्रीय उद्यान (Smallest National Park) कौनसा है?', 'Which is the smallest National Park in Madhya Pradesh?', 'घुघवा जीवाश्म राष्ट्रीय उद्यान (Fossil National Park)', 'Ghughua Fossil National Park', 93, 0, '{"facts":["यह मध्य प्रदेश के डिंडोरी (Dindori) जिले में स्थित है।","इसका क्षेत्रफल मात्र 0.27 वर्ग किलोमीटर है।"],"factsEn":["It is located in the Dindori district of Madhya Pradesh.","Its area is merely 0.27 square kilometers."],"explanationHi":"इस उद्यान में 6.5 करोड़ वर्ष पुराने पौधों (जैसे पाम के पेड़) और फलों के दुर्लभ जीवाश्म (Fossils) संरक्षित हैं।","explanationEn":"This park preserves rare fossils of plants (like palm trees) and fruits dating back 65 million years.","memoryTip":"''जीवाश्म'' (फॉसिल्स) बहुत छोटी जगह (0.27 sq km) में सहेज कर रखे गए हैं।","memoryTipEn":"Dindori documents dinosaur-era flora.","related":["Dindori","Plant Fossils","Kanha National Park (Largest)"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('f4opmyj6qsU-QF7Yf2DNa', 'General Knowledge', 'संजय दुबरी राष्ट्रीय उद्यान (Sanjay-Dubri National Park) मध्य प्रदेश के किस जिले में स्थित है?', 'Sanjay-Dubri National Park is located in which district of Madhya Pradesh?', 'सीधी (Sidhi)', 'Sidhi', 89, 0, '{"facts":["यह एक प्रसिद्ध टाइगर रिजर्व भी है।","विभाजन के बाद इस राष्ट्रीय उद्यान का एक बड़ा हिस्सा छत्तीसगढ़ में चला गया (जिसे अब गुरु घासीदास राष्ट्रीय उद्यान कहा जाता है)।"],"factsEn":["It is also a famous Tiger Reserve.","After partition, a major part of this national park went to Chhattisgarh (now called Guru Ghasidas National Park)."],"explanationHi":"यह उद्यान साल (Sal) के जंगलों और बाघों के अलावा सफेद बाघ ''मोहन'' के मूल निवास क्षेत्र का हिस्सा होने के लिए जाना जाता है।","explanationEn":"The park is known for its Sal forests and tigers, and being part of the original habitat of the white tiger ''Mohan''.","memoryTip":"''संजय'' हमेशा ''सीधे'' (सीधी) रास्ते पर चलता है।","memoryTipEn":"Sidhi shelters Sanjay Dubri.","related":["Guru Ghasidas National Park","Tiger Reserve","White Tiger"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-z4RLea6poh0Z_mNqfcTk', 'General Knowledge', 'मध्य प्रदेश का वह राष्ट्रीय उद्यान कौनसा है जो एक आधुनिक चिड़ियाघर (Modern Zoo) के रूप में भी कार्य करता है?', 'Which National Park of Madhya Pradesh also functions as a modern zoo?', 'वन विहार राष्ट्रीय उद्यान (Van Vihar)', 'Van Vihar National Park', 94, 0, '{"facts":["यह भोपाल में ''बड़ी झील'' (Upper Lake) के ठीक बगल में स्थित है।","इसे 1979 में राष्ट्रीय उद्यान घोषित किया गया था।"],"factsEn":["It is located right next to the ''Upper Lake'' in Bhopal.","It was declared a National Park in 1979."],"explanationHi":"यह एक अनूठा पार्क है जहाँ जानवरों को उनके प्राकृतिक आवास (Natural habitat) में रखा जाता है और लोग एक सड़क के माध्यम से उन्हें देख सकते हैं।","explanationEn":"It is a unique park where animals are kept in their natural habitat, and people can view them from a road passing through it.","memoryTip":"भोपाल के लोग ''वन'' में ''विहार'' (घूमने) जाते हैं।","memoryTipEn":"Bhopal borders the Van Vihar.","related":["Upper Lake Bhopal","Ex-situ Conservation","Central Zoo Authority"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('y48iljiJFsCRPWGvge5Gu', 'General Knowledge', 'मध्य प्रदेश का एकमात्र ''रेप्टाइल पार्क'' (Reptile Park) किस राष्ट्रीय उद्यान में स्थित है?', 'The only ''Reptile Park'' of Madhya Pradesh is located in which National Park?', 'पन्ना राष्ट्रीय उद्यान (Panna National Park)', 'Panna National Park', 93, 0, '{"facts":["पन्ना राष्ट्रीय उद्यान छतरपुर और पन्ना जिलों में फैला है।","यह केन नदी (Ken River) द्वारा सिंचित होता है।"],"factsEn":["Panna National Park is spread across Chhatarpur and Panna districts.","It is irrigated by the Ken River."],"explanationHi":"इस उद्यान के अंदर स्थित रेप्टाइल पार्क में मगरमच्छ, घड़ियाल और विभिन्न प्रकार के सांपों का संरक्षण किया जाता है। 2011 में इसे बायोस्फीयर रिजर्व घोषित किया गया था।","explanationEn":"The reptile park inside this national park conserves crocodiles, gharials, and various types of snakes. It was declared a Biosphere Reserve in 2011.","memoryTip":"हीरे (पन्ना) की रक्षा सांप (रेप्टाइल्स) करते हैं।","memoryTipEn":"Panna protects the reptiles.","related":["Ken River","Tiger Reserve","Biosphere Reserve"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uoMwU6TNZwNQZwQ-CxGBu', 'General Knowledge', 'अविभाजित भारत का भौगोलिक केंद्र बिंदु (Geographical Centre of Undivided India) किसे माना जाता है?', 'What is considered the Geographical Centre of Undivided India?', 'करौंदी (कटनी)', 'Karondi (Katni)', 95, 0, '{"facts":["करौंदी गांव मध्य प्रदेश के कटनी (Katni) जिले में स्थित है।","इस स्थान की खोज प्रसिद्ध राम मनोहर लोहिया ने 1956 में की थी।"],"factsEn":["Karondi village is located in the Katni district of Madhya Pradesh.","This location was discovered by the famous Ram Manohar Lohia in 1956."],"explanationHi":"इस केंद्र बिंदु पर एक स्मारक भी बनाया गया है। इसे अखंड भारत (पाकिस्तान और बांग्लादेश सहित) का केंद्र माना जाता है।","explanationEn":"A monument has been built at this center point. It is considered the center of Akhand Bharat (including Pakistan and Bangladesh).","memoryTip":"''कटनी'' ने भारत को एकदम बीच से ''काटा'' (केंद्र बिंदु)।","memoryTipEn":"Katni keeps the core of Undivided India.","related":["Katni District","Ram Manohar Lohia","Center of India"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AWwI4YRgLLP8f3QexHXgI', 'General Knowledge', 'प्राचीन मान्यताओं के अनुसार पृथ्वी का केंद्र बिंदु (Centre of the Earth) किसे माना जाता है?', 'According to ancient beliefs, what is considered the Centre of the Earth?', 'मंगलनाथ (उज्जैन)', 'Mangalnath (Ujjain)', 92, 0, '{"facts":["मंगलनाथ मंदिर मध्य प्रदेश के उज्जैन शहर में स्थित है।","यहाँ से कर्क रेखा (Tropic of Cancer) गुजरने की प्राचीन मान्यता है।"],"factsEn":["Mangalnath Temple is located in the Ujjain city of Madhya Pradesh.","It is traditionally believed that the Tropic of Cancer passes through here."],"explanationHi":"मत्स्य पुराण के अनुसार, उज्जैन को पृथ्वी का नाभि (Navel/Center) माना जाता है। यह स्थान मंगल ग्रह (Mars) का जन्मस्थान भी माना जाता है।","explanationEn":"According to the Matsya Purana, Ujjain is considered the navel (center) of the Earth. It is also believed to be the birthplace of the planet Mars.","memoryTip":"पृथ्वी के ''मध्य'' (मंगलनाथ) से भूगोल शुरू होता है।","memoryTipEn":"Mangalnath is the mythic middle of Earth.","related":["Ujjain","Tropic of Cancer","Astronomy"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0hT7mfBTWQh8-7BMNw5V8', 'General Knowledge', 'सोन नदी (Son River) का उद्गम स्थल मध्य प्रदेश में कहाँ है?', 'Where is the origin of the Son River in Madhya Pradesh?', 'अमरकंटक (अनूपपुर)', 'Amarkantak (Anuppur)', 96, 0, '{"facts":["सोन नदी गंगा नदी की एक प्रमुख दक्षिणी सहायक नदी (Tributary) है।","अमरकंटक से तीन प्रमुख नदियाँ निकलती हैं: नर्मदा, सोन, और जोहिला।"],"factsEn":["Son River is a major southern tributary of the Ganges River.","Three major rivers originate from Amarkantak: Narmada, Son, and Johila."],"explanationHi":"सोन नदी पर बाणसागर बांध (Bansagar Dam) स्थित है, जो मध्य प्रदेश, उत्तर प्रदेश और बिहार की एक संयुक्त परियोजना है। यह पटना के पास गंगा में मिलती है।","explanationEn":"The Bansagar Dam is situated on the Son River, a joint project of MP, UP, and Bihar. It joins the Ganges near Patna.","memoryTip":"''अमर'' पर्वत से ''सोन'' (सोना) और ''नर्मदा'' निकलीं।","memoryTipEn":"Son streams from the sacred Amarkantak.","related":["Amarkantak","Bansagar Dam","Ganges Tributary"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FK2WOQ4p-MrDSbjl-F0tj', 'General Knowledge', 'केन नदी (Ken River) का उद्गम मध्य प्रदेश के किस जिले से होता है?', 'Ken River originates from which district of Madhya Pradesh?', 'कटनी (विंध्याचल पर्वतमाला)', 'Katni (Vindhyachal Range)', 91, 0, '{"facts":["केन नदी पन्ना राष्ट्रीय उद्यान के बीच से होकर बहती है।","यह उत्तर प्रदेश में बांदा (Banda) जिले के पास यमुना नदी में मिल जाती है।"],"factsEn":["The Ken River flows right through the Panna National Park.","It joins the Yamuna River near the Banda district in Uttar Pradesh."],"explanationHi":"केन-बेतवा नदी जोड़ो परियोजना (Ken-Betwa River Interlinking Project) भारत की पहली नदी जोड़ो परियोजना है, जिसका उद्देश्य सूखाग्रस्त बुंदेलखंड क्षेत्र को पानी उपलब्ध कराना है।","explanationEn":"The Ken-Betwa River Interlinking Project is India''s first river interlinking project, aimed at providing water to the drought-prone Bundelkhand region.","memoryTip":"''कटनी'' के ''केन'' से पानी बहता है।","memoryTipEn":"Ken catches its current in Katni.","related":["Ken-Betwa River Linking","Yamuna Tributary","Panna National Park"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('peF8DrArFEk-tpCRI040a', 'General Knowledge', 'इंदिरा सागर बांध (Indira Sagar Dam) मध्य प्रदेश में किस नदी पर बना है?', 'On which river is the Indira Sagar Dam built in Madhya Pradesh?', 'नर्मदा नदी (खंडवा)', 'Narmada River (Khandwa)', 95, 0, '{"facts":["यह बांध खंडवा जिले के पुनासा (Punasa) में स्थित है।","पानी के भंडारण (Water Storage Capacity) की दृष्टि से यह भारत का सबसे बड़ा बांध है।"],"factsEn":["This dam is located in Punasa of Khandwa district.","In terms of water storage capacity, it is the largest dam in India."],"explanationHi":"इस बहुउद्देशीय परियोजना की आधारशिला 1984 में तत्कालीन प्रधानमंत्री इंदिरा गांधी ने रखी थी। यह मध्य प्रदेश को भारी मात्रा में जलविद्युत प्रदान करता है।","explanationEn":"The foundation stone of this multipurpose project was laid in 1984 by then PM Indira Gandhi. It provides massive hydroelectric power to MP.","memoryTip":"''नर्मदा'' को रोकने का ''इंदिरा'' का ''खंड'' (खंडवा) में फैसला।","memoryTipEn":"Indira Sagar spans across Narmada in Khandwa.","related":["Narmada River","Punasa Dam","Omkareshwar Dam"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FRQAYk4UbaH9b1BWkbE8J', 'General Knowledge', 'गांधी सागर बांध (Gandhi Sagar Dam) मध्य प्रदेश के किस जिले में स्थित है?', 'In which district of Madhya Pradesh is the Gandhi Sagar Dam located?', 'मंदसौर', 'Mandsaur', 94, 0, '{"facts":["यह बांध चंबल नदी (Chambal River) पर बनाया गया है।","यह चंबल घाटी परियोजना के तहत निर्मित पहला बांध है (1960 में पूरा हुआ)।"],"factsEn":["This dam is built on the Chambal River.","It is the first dam constructed under the Chambal Valley Project (completed in 1960)."],"explanationHi":"चंबल नदी पर अन्य दो प्रमुख बांध राजस्थान में हैं: राणा प्रताप सागर और जवाहर सागर। गांधी सागर बांध मध्य प्रदेश में है और यह एमपी व राजस्थान की संयुक्त परियोजना है।","explanationEn":"The other two major dams on the Chambal river are in Rajasthan: Rana Pratap Sagar and Jawahar Sagar. Gandhi Sagar is in MP and is a joint project of MP and Rajasthan.","memoryTip":"चंबल के डाकुओं को रोकने ''गांधी'' जी ''मंदसौर'' आए।","memoryTipEn":"Gandhi Sagar curbs the Chambal in Mandsaur.","related":["Chambal River","Rana Pratap Sagar","Jawahar Sagar"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('C2oWK__XdJ9ULEDAOb0T_', 'General Knowledge', 'बरगी बांध (Bargi Dam) मध्य प्रदेश के किस जिले में स्थित है?', 'In which district of Madhya Pradesh is the Bargi Dam located?', 'जबलपुर', 'Jabalpur', 92, 0, '{"facts":["यह नर्मदा नदी पर बनने वाले शुरुआती 30 बड़े बांधों में से पहला था।","इसका आधिकारिक नाम ''रानी अवंतीबाई सागर'' (Rani Avanti Bai Sagar) है।"],"factsEn":["It was the first of the 30 initial major dams built on the Narmada River.","Its official name is ''Rani Avanti Bai Sagar''."],"explanationHi":"यह बांध जबलपुर, मंडला और सिवनी जिलों में सिंचाई का एक प्रमुख स्रोत है। बांध का बैकवाटर (Backwater) एक लोकप्रिय क्रूज पर्यटन स्थल बन गया है।","explanationEn":"The dam is a major source of irrigation in Jabalpur, Mandla, and Seoni districts. Its backwaters have become a popular cruise tourism destination.","memoryTip":"जबलपुर के ''बल'' से ''बरगी'' बांध बना।","memoryTipEn":"Bargi blocks the Narmada near Jabalpur.","related":["Narmada River","Rani Avanti Bai","Jabalpur Tourism"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('fye1eY5MjuZffpnmKUZAT', 'General Knowledge', 'मध्य प्रदेश में भारी विद्युत उपकरण कारखाना (BHEL) कहाँ स्थित है?', 'Where is the Bharat Heavy Electricals Limited (BHEL) factory located in Madhya Pradesh?', 'भोपाल', 'Bhopal', 95, 0, '{"facts":["BHEL भोपाल की स्थापना 1960 में की गई थी।","इसे ब्रिटेन (United Kingdom) की तकनीकी सहायता से स्थापित किया गया था।"],"factsEn":["BHEL Bhopal was established in 1960.","It was set up with technical assistance from the United Kingdom."],"explanationHi":"यह भारत की सबसे बड़ी इंजीनियरिंग और निर्माण (Maharatna) कंपनियों में से एक है। यहाँ ट्रांसफार्मर, टर्बाइन और रेलवे मोटर्स का निर्माण होता है।","explanationEn":"It is one of India''s largest engineering and manufacturing (Maharatna) companies. It manufactures transformers, turbines, and railway motors.","memoryTip":"''BHEL'' (भेल) भोपाल की शान है।","memoryTipEn":"BHEL powers up Bhopal.","related":["Maharatna Company","Heavy Engineering","United Kingdom"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CFx2I1exXPtjiqb8tUUGe', 'General Knowledge', 'भारत सरकार का ''अल्कलॉयड कारखाना'' (Alkaloid Factory) मध्य प्रदेश में कहाँ स्थित है?', 'Where is the Government of India''s ''Alkaloid Factory'' located in Madhya Pradesh?', 'नीमच (Neemuch)', 'Neemuch', 91, 0, '{"facts":["यह कारखाना 1935 में स्थापित किया गया था।","यहाँ अफीम (Opium) का प्रसंस्करण (Processing) करके दवाओं के लिए अल्कलॉइड निकाले जाते हैं।"],"factsEn":["This factory was established in 1935.","Here, opium is processed to extract alkaloids for pharmaceutical purposes."],"explanationHi":"नीमच और मंदसौर मध्य प्रदेश के प्रमुख अफीम उत्पादक जिले हैं। यहाँ उत्पादित दवाओं का उपयोग दर्दनिवारक (Painkillers) बनाने में किया जाता है।","explanationEn":"Neemuch and Mandsaur are the major opium-producing districts of MP. The drugs produced here are used to make painkillers.","memoryTip":"नीमच में ''नीम'' जैसी कड़वी ''अफीम'' से दवाई बनती है।","memoryTipEn":"Neemuch neutralizes opium into medicine.","related":["Opium Cultivation","Mandsaur","Narcotics"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Xc9eKXIg3AEhXLISlanQr', 'General Knowledge', 'मध्य प्रदेश का कौनसा जिला ''स्लेट पेंसिल'' (Slate Pencil) उद्योग के लिए प्रसिद्ध है?', 'Which district of Madhya Pradesh is famous for the ''Slate Pencil'' industry?', 'मंदसौर', 'Mandsaur', 89, 0, '{"facts":["मंदसौर भारत में स्लेट पेंसिल का सबसे बड़ा उत्पादक है।","स्लेट का निर्माण यहाँ बहुतायत में पाए जाने वाले ''शेल'' (Shale) पत्थर से होता है।"],"factsEn":["Mandsaur is the largest producer of slate pencils in India.","The slates are made from the abundantly found ''Shale'' stone here."],"explanationHi":"मंदसौर का यह कुटीर उद्योग (Cottage industry) देशभर में प्राथमिक स्कूलों में बच्चों द्वारा इस्तेमाल की जाने वाली स्लेट और पेंसिल की आपूर्ति करता है।","explanationEn":"This cottage industry in Mandsaur supplies slates and pencils used by children in primary schools across the country.","memoryTip":"बचपन में ''मंद'' (मंदसौर) बुद्धि वालों को ''स्लेट पेंसिल'' दी जाती है।","memoryTipEn":"Mandsaur makes the school slates.","related":["Cottage Industry","Opium District","Shale Stone"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0yJyKU0QwnZiLgo-KdE99', 'General Knowledge', 'मध्य प्रदेश राज्य ''साइबर पुलिस मुख्यालय'' कहाँ स्थित है?', 'Where is the Madhya Pradesh State ''Cyber Police Headquarters'' located?', 'भोपाल', 'Bhopal', 92, 0, '{"facts":["बढ़ते साइबर अपराधों से निपटने के लिए इसे स्थापित किया गया था।","सभी जिला स्तर के साइबर सेल (Cyber Cells) इसी मुख्यालय को रिपोर्ट करते हैं।"],"factsEn":["It was established to tackle the growing cybercrimes.","All district-level cyber cells report to this headquarters."],"explanationHi":"भोपाल स्थित यह मुख्यालय हाई-टेक फोरेंसिक उपकरणों से लैस है जो ऑनलाइन धोखाधड़ी, हैकिंग और डेटा चोरी जैसे मामलों को सुलझाता है।","explanationEn":"This Bhopal-based HQ is equipped with high-tech forensic tools to solve cases like online fraud, hacking, and data theft.","memoryTip":"राजधानी (भोपाल) से पूरे एमपी का ''साइबर'' नेटवर्क कंट्रोल होता है।","memoryTipEn":"Bhopal blocks the cyber bugs.","related":["MP Police Headquarters","Cyber Crime","Bhopal"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6aStnO8_jAJQb-9c28GJm', 'General Knowledge', 'जवाहरलाल नेहरू पुलिस अकादमी (JNPA) मध्य प्रदेश में कहाँ स्थित है?', 'Where is the Jawaharlal Nehru Police Academy (JNPA) located in Madhya Pradesh?', 'सागर', 'Sagar', 94, 0, '{"facts":["यह मध्य प्रदेश पुलिस का सबसे पुराना और प्रमुख प्रशिक्षण संस्थान है (1906 में स्थापित)।","यहाँ मुख्य रूप से राज्य पुलिस सेवा (SPS) अधिकारियों और उप-निरीक्षकों (Sub-Inspectors) को प्रशिक्षण दिया जाता है।"],"factsEn":["It is the oldest and premier training institute of MP Police (established in 1906).","It primarily trains State Police Service (SPS) officers and Sub-Inspectors."],"explanationHi":"इस अकादमी का परिसर ऐतिहासिक सागर किले के पास स्थित है। फोरेंसिक साइंस लैब (FSL) भी सागर में ही होने के कारण यह पुलिस प्रशिक्षण का एक बड़ा केंद्र है।","explanationEn":"The academy''s campus is located near the historic Sagar Fort. With the FSL also in Sagar, it is a major hub for police training.","memoryTip":"पुलिस की ट्रेनिंग में ज्ञान का ''सागर'' है।","memoryTipEn":"Sagar shapes the State Police Service.","related":["Forensic Science Lab","MP Police Training","Bhauri Police Academy"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('hpkYzsmUp0OGBOYPGLQJb', 'General Knowledge', 'मध्य प्रदेश राज्य महिला आयोग (State Women''s Commission) का गठन कब हुआ था?', 'When was the Madhya Pradesh State Women''s Commission constituted?', '23 मार्च 1998', '23 March 1998', 89, 0, '{"facts":["इसका गठन ''मध्य प्रदेश राज्य महिला आयोग अधिनियम, 1995'' के तहत किया गया था।","इसका मुख्यालय भोपाल में है।"],"factsEn":["It was constituted under the ''MP State Women''s Commission Act, 1995''.","Its headquarters is in Bhopal."],"explanationHi":"यह आयोग महिलाओं के अधिकारों की रक्षा करने, उनके खिलाफ अपराधों की जांच करने और सरकार को महिला सशक्तिकरण पर सलाह देने के लिए एक वैधानिक (Statutory) निकाय है।","explanationEn":"This commission is a statutory body to protect women''s rights, investigate crimes against them, and advise the government on women''s empowerment.","memoryTip":"98 में महिलाओं को ''8'' (आठ) दिशाओं में सुरक्षा मिली।","memoryTipEn":"1998 empowered the women of MP.","related":["National Commission for Women","Women Empowerment","Statutory Body"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('GqXjbc9vjWHF2rkeJ8EpD', 'General Knowledge', 'मध्य प्रदेश राज्य निर्वाचन आयोग (State Election Commission) का गठन कब हुआ?', 'When was the Madhya Pradesh State Election Commission constituted?', '1 फरवरी 1994', '1 February 1994', 95, 0, '{"facts":["मध्य प्रदेश पंचायती राज संस्थाओं के लिए राज्य चुनाव आयोग गठित करने वाला भारत का पहला राज्य था।","इसके प्रथम चुनाव आयुक्त ''एन. बी. लोहानी'' (N. B. Lohani) थे।"],"factsEn":["Madhya Pradesh was the first state in India to constitute a State Election Commission for Panchayati Raj institutions.","Its first Election Commissioner was ''N. B. Lohani''."],"explanationHi":"राज्य चुनाव आयोग का मुख्य कार्य पंचायतों (73वें संशोधन) और नगर पालिकाओं (74वें संशोधन) के निष्पक्ष चुनाव कराना है।","explanationEn":"The main task of the State Election Commission is to conduct fair elections for Panchayats (73rd Amendment) and Municipalities (74th Amendment).","memoryTip":"94 में पंचायतों में वोटिंग (निर्वाचन) शुरू हुई।","memoryTipEn":"1994 initiated local elections in MP.","related":["N. B. Lohani","Panchayati Raj","73rd Amendment"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('G1XYim4q2_yCVXK-B0IYr', 'General Knowledge', 'मध्य प्रदेश उच्च न्यायालय की स्थापना कब हुई थी?', 'When was the Madhya Pradesh High Court established?', '1 नवंबर 1956', '1 November 1956', 94, 0, '{"facts":["यह राज्य पुनर्गठन अधिनियम (States Reorganisation Act) 1956 के तहत स्थापित किया गया था।","इससे पहले नागपुर उच्च न्यायालय (Nagpur High Court) इस क्षेत्र के लिए कार्य करता था।"],"factsEn":["It was established under the States Reorganisation Act of 1956.","Before this, the Nagpur High Court served this region."],"explanationHi":"मध्य प्रदेश की स्थापना के साथ ही न्यायपालिका का मुख्यालय भी नागपुर से हटाकर जबलपुर कर दिया गया।","explanationEn":"With the formation of Madhya Pradesh, the headquarters of the judiciary was also shifted from Nagpur to Jabalpur.","memoryTip":"जिस दिन एमपी बना (1 नवंबर 1956), उसी दिन हाई कोर्ट बना।","memoryTipEn":"State and Court share the same birthday.","related":["Jabalpur","Nagpur High Court","State Reorganisation Act"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('n0KpKMdmVjvSwpHPQp5NO', 'General Knowledge', 'मध्य प्रदेश उच्च न्यायालय के प्रथम मुख्य न्यायाधीश (Chief Justice) कौन थे?', 'Who was the first Chief Justice of the Madhya Pradesh High Court?', 'न्यायमूर्ति एम. हिदायतुल्लाह', 'Justice M. Hidayatullah', 96, 0, '{"facts":["उन्होंने 1956 से 1958 तक मध्य प्रदेश के मुख्य न्यायाधीश के रूप में कार्य किया।","बाद में वे भारत के 11वें मुख्य न्यायाधीश (CJI) बने।"],"factsEn":["He served as the Chief Justice of MP from 1956 to 1958.","He later became the 11th Chief Justice of India (CJI)."],"explanationHi":"न्यायमूर्ति हिदायतुल्लाह भारत के एकमात्र व्यक्ति हैं जिन्होंने भारत के मुख्य न्यायाधीश, भारत के उपराष्ट्रपति और कार्यवाहक राष्ट्रपति (Acting President) तीनों सर्वोच्च पदों पर कार्य किया है।","explanationEn":"Justice Hidayatullah is the only person in India to have served in all three top posts: Chief Justice of India, Vice President of India, and Acting President.","memoryTip":"एमपी का पहला न्याय ''हिदायत'' (हिदायतुल्लाह) के साथ मिला।","memoryTipEn":"Hidayatullah headed the highest MP court.","related":["Acting President of India","Vice President of India","Jabalpur High Court"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xNziGBekWnwyZWuP9DHqX', 'General Knowledge', 'सहस्त्रधारा जलप्रपात (Sahastradhara Waterfall) मध्य प्रदेश में किस नदी पर है?', 'Sahastradhara Waterfall is on which river in Madhya Pradesh?', 'नर्मदा नदी (महेश्वर)', 'Narmada River (Maheshwar)', 93, 0, '{"facts":["यह जलप्रपात खरगोन (Khargone) जिले के महेश्वर में स्थित है।","''सहस्त्रधारा'' का अर्थ है ''हजारों धाराएं'' (A thousand streams)।"],"factsEn":["This waterfall is located in Maheshwar in the Khargone district.","''Sahastradhara'' translates to ''A thousand streams''."],"explanationHi":"यहाँ नर्मदा नदी चट्टानों से टकराकर कई छोटी-छोटी धाराओं में बंट जाती है, जिससे एक अत्यंत मनोरम दृश्य बनता है।","explanationEn":"Here, the Narmada River hits the rocks and splits into many small streams, creating a highly picturesque scene.","memoryTip":"नर्मदा ''महेश्वर'' में ''हजारों'' (सहस्त्र) धाराओं में बहती है।","memoryTipEn":"Thousands of streams flow at Maheshwar.","related":["Maheshwar","Narmada River","Khargone"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('P2_xUCjgQQYxaIWj4REON', 'General Knowledge', 'कपिलधारा जलप्रपात (Kapildhara Waterfall) कहाँ स्थित है?', 'Where is the Kapildhara Waterfall located?', 'अमरकंटक (अनूपपुर)', 'Amarkantak (Anuppur)', 94, 0, '{"facts":["यह नर्मदा नदी पर बनने वाला पहला जलप्रपात है।","यह नर्मदा के उद्गम स्थल (Origin) से मात्र 6 किलोमीटर की दूरी पर है।"],"factsEn":["It is the first waterfall formed on the Narmada River.","It is just 6 kilometers away from the origin of the Narmada."],"explanationHi":"माना जाता है कि प्राचीन काल में महान ऋषि ''कपिल मुनि'' ने यहाँ तपस्या की थी, इसीलिए इसका नाम कपिलधारा पड़ा।","explanationEn":"It is believed that the great ancient sage ''Kapil Muni'' meditated here, hence it is named Kapildhara.","memoryTip":"नर्मदा का पहला ''धारा'' (प्रपात) ''कपिल मुनि'' के नाम पर है।","memoryTipEn":"Kapil meditated at the first Narmada fall.","related":["Amarkantak","Narmada River","Dugdh Dhara Waterfall"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kTH781RGj5UE7TyoRU0YU', 'General Knowledge', 'जैन तीर्थस्थल ''गोम्मटगिरि'' (Gommatgiri) मध्य प्रदेश के किस शहर में है?', 'The Jain pilgrimage site ''Gommatgiri'' is in which city of Madhya Pradesh?', 'इंदौर', 'Indore', 88, 0, '{"facts":["यह एक छोटी पहाड़ी पर स्थित है जहाँ भगवान गोमतेश्वर (बाहुबली) की 21 फीट ऊंची मूर्ति स्थापित है।","यहाँ जैन धर्म के सभी 24 तीर्थंकरों को समर्पित 24 छोटे संगमरमर के मंदिर हैं।"],"factsEn":["It is located on a small hill where a 21-foot-tall statue of Lord Gommateshwara (Bahubali) is installed.","It has 24 small marble temples dedicated to all 24 Tirthankaras of Jainism."],"explanationHi":"इस मूर्ति को श्रवणबेलगोला (कर्नाटक) में स्थित भगवान बाहुबली की विशाल मूर्ति की प्रतिकृति (Replica) के रूप में बनाया गया है।","explanationEn":"This statue was built as a replica of the colossal statue of Lord Bahubali located in Shravanabelagola (Karnataka).","memoryTip":"इंदौर की ''गिरि'' (पहाड़ी) पर ''गोम्मट'' (जैन तीर्थ) है।","memoryTipEn":"Gommatgiri graces the hills of Indore.","related":["Lord Bahubali","Indore Tourism","Jain Pilgrimage"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('zJEXN6ha7PH27mdCWNxmk', 'General Knowledge', 'जैन तीर्थस्थल ''सोनागिरि'' (Sonagiri) मध्य प्रदेश के किस जिले में स्थित है?', 'The Jain pilgrimage site ''Sonagiri'' is located in which district of Madhya Pradesh?', 'दतिया (Datia)', 'Datia', 91, 0, '{"facts":["सोनागिरि का अर्थ है ''सोने का पहाड़'' (The Golden Peak)।","यहाँ पहाड़ियों पर 100 से अधिक सुंदर सफेद जैन मंदिर बने हुए हैं।"],"factsEn":["Sonagiri translates to ''The Golden Peak''.","There are over 100 beautiful white Jain temples built on the hills here."],"explanationHi":"यह दिगंबर जैन समुदाय का एक अति पवित्र स्थल है, जहां भगवान चंद्रप्रभु (8वें तीर्थंकर) का मुख्य मंदिर (मंदिर संख्या 57) स्थित है।","explanationEn":"It is a highly sacred site for the Digambara Jain community, housing the main temple (Temple No. 57) of Lord Chandraprabha (8th Tirthankara).","memoryTip":"दतिया के दांत ''सोने'' (सोनागिरि) के हैं।","memoryTipEn":"Datia displays the golden hills of Sonagiri.","related":["Datia","Digambara Jain","Lord Chandraprabha"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oLbSm_u7oeDzrf53Kp0e9', 'General Knowledge', 'जैन तीर्थस्थल ''मुक्तागिरि'' (Muktagiri) मध्य प्रदेश के किस जिले में है?', 'The Jain pilgrimage site ''Muktagiri'' is in which district of Madhya Pradesh?', 'बैतूल (Betul)', 'Betul', 89, 0, '{"facts":["यह सतपुड़ा पर्वतमाला में स्थित है।","यहाँ घने जंगल और झरने के बीच 52 दिगंबर जैन मंदिर बने हुए हैं।"],"factsEn":["It is located in the Satpura mountain range.","There are 52 Digambara Jain temples built amidst dense forests and a waterfall here."],"explanationHi":"मान्यता है कि यहाँ से कई जैन मुनियों ने मोक्ष (Mukti) प्राप्त किया था, इसीलिए इसे ''मुक्तागिरि'' (मोक्ष की पहाड़ी) कहा जाता है।","explanationEn":"It is believed that many Jain ascetics attained salvation (Mukti) from here, hence it is called ''Muktagiri'' (Hill of Salvation).","memoryTip":"बैतूल में जाकर मुनियों को ''मुक्ति'' (मुक्तागिरि) मिल गई।","memoryTipEn":"Betul bestows Moksha at Muktagiri.","related":["Satpura Range","Jain Pilgrimage","Moksha"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZpxWKxOO4Mcd1LLDP8zEa', 'General Knowledge', 'प्रसिद्ध शक्तिपीठ ''पीताम्बरा पीठ'' (Pitambara Peeth) कहाँ स्थित है?', 'Where is the famous Shakti Peeth ''Pitambara Peeth'' located?', 'दतिया (Datia)', 'Datia', 92, 0, '{"facts":["इसकी स्थापना 1920 के दशक में ''स्वामीजी महाराज'' (ब्रह्मलीन श्रद्धेय स्वामीजी) द्वारा की गई थी।","यहाँ देवी बगलामुखी (Maa Bagalamukhi) की विशेष पूजा की जाती है।"],"factsEn":["It was established in the 1920s by ''Swamiji Maharaj'' (Brahmaleen Shraddheya Swamiji).","Special worship of Goddess Bagalamukhi is performed here."],"explanationHi":"यह मंदिर भारत भर में तांत्रिक पूजा (Tantric worship) और राजनीतिक नेताओं के बीच अपनी अपार मान्यताओं के लिए बहुत प्रसिद्ध है।","explanationEn":"The temple is very famous across India for Tantric worship and its immense significance among political leaders.","memoryTip":"दतिया के ''पीले'' (पीताम्बर) वस्त्रों में देवी के दर्शन होते हैं।","memoryTipEn":"Datia delivers the divine power of Pitambara.","related":["Maa Bagalamukhi","Tantric Worship","Datia District"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5jjEN1UqkT1fFkDVqu8vf', 'General Knowledge', 'प्रसिद्ध ''माँ शारदा मंदिर'' (Maa Sharada Temple) किस पर्वत पर स्थित है?', 'The famous ''Maa Sharada Temple'' is situated on which mountain?', 'त्रिकुटा पर्वत (मैहर)', 'Trikuta Hill (Maihar)', 95, 0, '{"facts":["यह मंदिर मध्य प्रदेश के नवगठित ''मैहर'' (Maihar) जिले (पहले सतना का हिस्सा) में स्थित है।","भक्तों को माता के दर्शन के लिए 1063 सीढ़ियां चढ़नी पड़ती हैं।"],"factsEn":["The temple is located in the newly formed ''Maihar'' district (formerly part of Satna) of Madhya Pradesh.","Devotees have to climb 1063 steps to seek the goddess''s blessings."],"explanationHi":"लोककथाओं के अनुसार, आल्हा और उदल (Alha and Udal), जो महान योद्धा थे, सबसे पहले माता की पूजा करने रोज़ सुबह यहाँ आते हैं।","explanationEn":"According to folklore, Alha and Udal, the great warriors, are the first to come here every morning to worship the goddess.","memoryTip":"मैहर की ''शारदा'' माता 1063 सीढ़ियों के ऊपर विराजमान हैं।","memoryTipEn":"Maihar''s mountain hides Maa Sharada.","related":["Alha and Udal","Maihar District","Trikuta Hills"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-Xb4c645Ifx4ae58pGegu', 'General Knowledge', 'मितावली (मुरैना) का ''चौसठ योगिनी मंदिर'' (Chausath Yogini Temple) क्यों प्रसिद्ध है?', 'Why is the ''Chausath Yogini Temple'' of Mitawali (Morena) famous?', 'भारतीय संसद भवन (पुराना) का डिज़ाइन इसी से प्रेरित माना जाता है', 'The design of the old Indian Parliament House is believed to be inspired by it', 96, 0, '{"facts":["यह मंदिर 11वीं शताब्दी में कछपघात राजा देवपाल द्वारा बनवाया गया था।","यह एक वृत्ताकार (Circular) मंदिर है जिसमें 64 छोटे कक्ष (chambers) हैं, जिनमें से प्रत्येक में एक शिवलिंग है।"],"factsEn":["This temple was built in the 11th century by Kachchhapaghata king Devapala.","It is a circular temple with 64 small chambers, each housing a Shivling."],"explanationHi":"ब्रिटिश वास्तुकार एडविन लुटियंस और हर्बर्ट बेकर ने 1920 के दशक में पुरानी दिल्ली की संसद को डिजाइन करते समय इस मंदिर की वास्तुकला से प्रेरणा ली थी।","explanationEn":"British architects Edwin Lutyens and Herbert Baker drew inspiration from this temple''s architecture while designing the old Parliament of Delhi in the 1920s.","memoryTip":"मुरैना की ''गोलाकार'' इमारत ही दिल्ली की ''संसद'' बनी।","memoryTipEn":"Morena''s math modeled the old Parliament.","related":["Old Parliament Building","Edwin Lutyens","Morena District"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ewSPzkFFZvdKryhGdnxc6', 'General Knowledge', 'उत्तर भारत का सोमनाथ (Somnath of North India) किसे कहा जाता है?', 'Which temple is called the ''Somnath of North India''?', 'भोजपुर शिव मंदिर (रायसेन)', 'Bhojpur Shiva Temple (Raisen)', 94, 0, '{"facts":["इस मंदिर का निर्माण 11वीं शताब्दी में परमार राजा भोज (Raja Bhoj) ने करवाया था।","यहाँ भारत का सबसे बड़ा (एकल पत्थर से बना) शिवलिंग स्थापित है।"],"factsEn":["This temple was built by the Paramara King Bhoj in the 11th century.","It houses the largest (monolithic) Shivling in India."],"explanationHi":"यह मंदिर कभी पूरा नहीं बन पाया (Incomplete structure)। इसके निर्माण के नक्शे आज भी मंदिर के पास की चट्टानों पर उकेरे हुए देखे जा सकते हैं।","explanationEn":"The temple was never fully completed. The architectural plans for its construction can still be seen carved on the rocks near the temple.","memoryTip":"भोज ने रायसेन में उत्तर का ''सोमनाथ'' (भोजपुर) बनाया।","memoryTipEn":"Bhojpur boasts the biggest Shivling.","related":["Raja Bhoj","Raisen District","Paramara Architecture"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_gJ2lup1YzvVKi3Ue-P-7', 'General Knowledge', 'ग्वालियर के किले में स्थित ''तेली का मंदिर'' (Teli ka Mandir) वास्तुकला की दृष्टि से क्यों अनूठा है?', 'Why is the ''Teli ka Mandir'' located in the Gwalior Fort architecturally unique?', 'उत्तर भारत में द्रविड़ शैली (Dravidian Style) का एकमात्र मंदिर है', 'It is the only temple in North India built in the Dravidian Style', 92, 0, '{"facts":["इस मंदिर का शिखर (Roof) दक्षिण भारतीय (द्रविड़) शैली का है, जबकि इसकी नक्काशी (Decorations) उत्तर भारतीय (नागर) शैली की है।","यह 8वीं या 9वीं शताब्दी में गुर्जर-प्रतिहार शासकों द्वारा बनवाया गया था।"],"factsEn":["The roof (Shikhara) of this temple is in South Indian (Dravidian) style, while its decorations are in North Indian (Nagara) style.","It was built in the 8th or 9th century by Gurjara-Pratihara rulers."],"explanationHi":"यह ग्वालियर के किले की सबसे ऊँची इमारत (लगभग 100 फीट) है और भगवान विष्णु, शिव और मातृकाओं को समर्पित है।","explanationEn":"It is the tallest structure in the Gwalior Fort (approx 100 feet) and is dedicated to Lord Vishnu, Shiva, and Matrikas.","memoryTip":"उत्तर भारत में दक्षिण का ''तेल'' (तेली) बिका (द्रविड़ शैली)।","memoryTipEn":"Teli temple transports the South to the North.","related":["Gwalior Fort","Dravidian Architecture","Gurjara-Pratihara Dynasty"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rQG6bhqHdioc0XTBOi0Kz', 'General Knowledge', 'सास-बहू मंदिर (सहस्रबाहु मंदिर) कहाँ स्थित है?', 'Where is the Sas-Bahu Temple (Sahastrabahu Temple) located?', 'ग्वालियर के किले में', 'In Gwalior Fort', 91, 0, '{"facts":["इसका मूल नाम ''सहस्रबाहु'' (हजारों भुजाओं वाले भगवान विष्णु) मंदिर था, जो अपभ्रंश होकर ''सास-बहू'' बन गया।","इसका निर्माण 11वीं शताब्दी में कच्छपघात राजवंश (Kachchhapaghata dynasty) के राजा महिपाल ने करवाया था।"],"factsEn":["Its original name was ''Sahastrabahu'' (thousand-armed Lord Vishnu) temple, which corrupted into ''Sas-Bahu''.","It was built in the 11th century by King Mahipala of the Kachchhapaghata dynasty."],"explanationHi":"यह जुड़वां मंदिरों (Twin temples) का एक समूह है; बड़ा मंदिर भगवान विष्णु (सास) को और छोटा मंदिर भगवान शिव (बहू) को समर्पित माना जाता है।","explanationEn":"It is a group of twin temples; the larger one is considered dedicated to Lord Vishnu (mother-in-law) and the smaller to Lord Shiva (daughter-in-law).","memoryTip":"ग्वालियर के किले में ''सास-बहू'' का राज (मंदिर) है।","memoryTipEn":"Sas-Bahu shares the Gwalior Fort.","related":["Gwalior Fort","Kachchhapaghata Dynasty","Lord Vishnu"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Y0tNEsJp6WUT99oxntCbJ', 'General Knowledge', 'मध्य प्रदेश का पहला आई.टी. पार्क (IT Park) कहाँ स्थापित किया गया था?', 'Where was the first IT Park of Madhya Pradesh established?', 'भोपाल', 'Bhopal', 89, 0, '{"facts":["क्रिस्टल आईटी पार्क (Crystal IT Park) मध्य प्रदेश के सबसे प्रमुख आईटी पार्कों में से एक है, जो इंदौर में है।","हालाँकि, राज्य सरकार ने सूचना प्रौद्योगिकी क्षेत्र को बढ़ावा देने के लिए सबसे पहले भोपाल में आईटी पार्क स्थापित किया था।"],"factsEn":["Crystal IT Park is one of the most prominent IT parks in MP, located in Indore.","However, the state government first established an IT park in Bhopal to boost the Information Technology sector."],"explanationHi":"वर्तमान में इंदौर राज्य का सबसे बड़ा आईटी हब (TCS, Infosys) बन गया है, लेकिन प्रारंभिक पहल राजधानी भोपाल से शुरू हुई थी।","explanationEn":"Currently, Indore has become the state''s largest IT hub (TCS, Infosys), but the initial initiative started from the capital Bhopal.","memoryTip":"तकनीक (IT) की शुरुआत ''राजधानी'' (भोपाल) से हुई।","memoryTipEn":"Bhopal brought the first bytes to MP.","related":["Crystal IT Park (Indore)","IT Hub","TCS Indore"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gKLOIc9ksgKNs3zvh3H_7', 'General Knowledge', 'मध्य प्रदेश का सबसे बड़ा रेलवे जंक्शन (Railway Junction) कौनसा है?', 'Which is the largest railway junction in Madhya Pradesh?', 'इटारसी जंक्शन', 'Itarsi Junction', 95, 0, '{"facts":["यह नर्मदापुरम (पूर्व में होशंगाबाद) जिले में स्थित है।","यहाँ से भारत की चारों दिशाओं (North, South, East, West) के लिए ट्रेनें जाती हैं।"],"factsEn":["It is located in the Narmadapuram (formerly Hoshangabad) district.","Trains to all four directions (North, South, East, West) of India depart from here."],"explanationHi":"पश्चिम मध्य रेलवे (WCR) ज़ोन के अंतर्गत आने वाला यह जंक्शन पूरे भारत को जोड़ने वाले सबसे महत्वपूर्ण ट्रांजिट पॉइंट्स (Transit points) में से एक है।","explanationEn":"Falling under the West Central Railway (WCR) zone, this junction is one of the most vital transit points connecting all of India.","memoryTip":"सभी दिशाओं की ट्रेनें ''ईंट'' (इटारसी) की तरह एक दूसरे से जुड़ती हैं।","memoryTipEn":"Itarsi intersects all Indian routes.","related":["Narmadapuram","West Central Railway (WCR)","Bhopal Junction"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8sV8JVCu14qAn8CImyPmY', 'General Knowledge', 'मध्य प्रदेश का पहला अंतर्राष्ट्रीय हवाई अड्डा (International Airport) कौनसा है?', 'Which is the first International Airport of Madhya Pradesh?', 'देवी अहिल्याबाई होलकर हवाई अड्डा (इंदौर)', 'Devi Ahilyabai Holkar Airport (Indore)', 94, 0, '{"facts":["इसे 2019 में अंतर्राष्ट्रीय हवाई अड्डे का दर्जा प्राप्त हुआ।","पहली अंतर्राष्ट्रीय उड़ान इंदौर से दुबई के लिए शुरू हुई थी।"],"factsEn":["It received international airport status in 2019.","The first international flight operated from Indore to Dubai."],"explanationHi":"यह मध्य प्रदेश का सबसे व्यस्त (Busiest) हवाई अड्डा है जो व्यापारिक राजधानी इंदौर को वैश्विक स्तर पर जोड़ता है।","explanationEn":"It is the busiest airport in Madhya Pradesh, connecting the commercial capital Indore globally.","memoryTip":"अहिल्या की नगरी से ''विदेशी'' (International) उड़ानें भरती हैं।","memoryTipEn":"Ahilyabai takes Indore international.","related":["Raja Bhoj Airport (Bhopal)","Indore","Airports Authority of India"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('djYiLwoqzzz9NzjPdWyOG', 'General Knowledge', 'राजा भोज अंतर्राष्ट्रीय हवाई अड्डा (Raja Bhoj Airport) मध्य प्रदेश में कहाँ स्थित है?', 'Where is the Raja Bhoj International Airport located in Madhya Pradesh?', 'भोपाल', 'Bhopal', 93, 0, '{"facts":["यह इंदौर के बाद मध्य प्रदेश का दूसरा सबसे व्यस्त हवाई अड्डा है।","यहाँ भारत का पहला सोलर पावर प्लांट (एयरपोर्ट के लिए) लगाया गया था।"],"factsEn":["It is the second busiest airport in Madhya Pradesh after Indore.","India''s first solar power plant (for an airport) was installed here."],"explanationHi":"यह हवाई अड्डा परमार वंश के 10वीं शताब्दी के शासक ''राजा भोज'' के नाम पर रखा गया है।","explanationEn":"The airport is named after the 10th-century ruler of the Paramara dynasty, ''Raja Bhoj''.","memoryTip":"''भोज'' के नाम पर ''भोपाल'' का हवाई अड्डा।","memoryTipEn":"Bhoja''s airport boards in Bhopal.","related":["Raja Bhoj","Devi Ahilyabai Holkar Airport","Solar Energy"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oBwq9rXknbl5rOUN95qx-', 'General Science', 'कोशिका (Cell) की ''प्रोटीन फैक्ट्री'' (Protein Factory) किसे कहा जाता है?', 'What is known as the ''Protein Factory'' of the cell?', 'राइबोसोम (Ribosome)', 'Ribosome', 96, 0, '{"facts":["राइबोसोम कोशिका के साइटोप्लाज्म (Cytoplasm) में पाए जाने वाले छोटे कण हैं।","ये आरएनए (RNA) और प्रोटीन से मिलकर बने होते हैं।"],"factsEn":["Ribosomes are tiny particles found in the cell''s cytoplasm.","They are composed of RNA and proteins."],"explanationHi":"राइबोसोम का मुख्य कार्य अमीनो एसिड (Amino acids) को जोड़कर प्रोटीन का निर्माण (Protein Synthesis) करना है, जो शरीर के विकास के लिए आवश्यक है।","explanationEn":"The main function of ribosomes is to link amino acids together to build proteins (Protein Synthesis), which is essential for body growth.","memoryTip":"''रिबन'' (राइबोसोम) की तरह प्रोटीन को बांधता है।","memoryTipEn":"Ribosomes roll out the proteins.","related":["Lysosome (Suicide Bag)","Mitochondria (Powerhouse)","Protein Synthesis"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oT4OmlNy0JbsZgn9bLaBh', 'General Science', 'न्यूटन का गति का प्रथम नियम (Newton''s First Law of Motion) क्या कहलाता है?', 'What is Newton''s First Law of Motion called?', 'जड़त्व का नियम (Law of Inertia)', 'Law of Inertia', 95, 0, '{"facts":["इस नियम के अनुसार, कोई वस्तु अपनी स्थिर अवस्था या एकसमान गति की अवस्था में तब तक रहती है जब तक कि उस पर कोई बाहरी बल (External force) न लगाया जाए।","गैलीलियो ने सबसे पहले जड़त्व (Inertia) की अवधारणा दी थी।"],"factsEn":["According to this law, an object remains in its state of rest or uniform motion unless acted upon by an external force.","Galileo first gave the concept of inertia."],"explanationHi":"जब बस अचानक रुकती है तो यात्री आगे की ओर गिरते हैं, यह ''गति के जड़त्व'' (Inertia of motion) का एक सामान्य उदाहरण है।","explanationEn":"When a bus stops suddenly, passengers fall forward; this is a common example of ''Inertia of motion''.","memoryTip":"जो ''जड़'' (Inert) है, वो बिना फोर्स के नहीं हिलेगा।","memoryTipEn":"Inertia insists on staying put.","related":["Newton''s Second Law (F=ma)","Newton''s Third Law (Action-Reaction)","Galileo"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-krgMkR2rJa3vhJOSZpkU', 'General Science', 'हवा की गति (Wind Speed) मापने के लिए किस यंत्र का उपयोग किया जाता है?', 'Which instrument is used to measure Wind Speed?', 'एनीमोमीटर (Anemometer)', 'Anemometer', 92, 0, '{"facts":["इसमें आमतौर पर छोटी कप (Cups) होती हैं जो हवा के दबाव से घूमती हैं।","मौसम विज्ञान (Meteorology) में हवा की गति और दिशा बहुत महत्वपूर्ण होती है।"],"factsEn":["It usually has small cups that spin with the wind pressure.","Wind speed and direction are crucial in Meteorology."],"explanationHi":"हवा की दिशा मापने के लिए ''विंड वेन'' (Wind Vane) का उपयोग किया जाता है, जबकि एनीमोमीटर उसकी गति (Speed) बताता है।","explanationEn":"A ''Wind Vane'' is used to measure wind direction, whereas an anemometer tells its speed.","memoryTip":"हवा के ''एनिमी'' (दुश्मन) की स्पीड ''एनीमो''मीटर मापता है।","memoryTipEn":"Anemometer assesses the air.","related":["Barometer (Pressure)","Wind Vane (Direction)","Meteorology"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('KYFTtp4_aATHQjY23yU_M', 'General Science', 'वायुमंडल की आर्द्रता (Humidity) मापने के लिए किस यंत्र का उपयोग किया जाता है?', 'Which instrument is used to measure atmospheric Humidity?', 'हाइग्रोमीटर (Hygrometer)', 'Hygrometer', 94, 0, '{"facts":["आर्द्रता हवा में मौजूद जलवाष्प (Water vapor) की मात्रा होती है।","हाइग्रोमीटर को कभी-कभी साइक्रोमीटर (Psychrometer) भी कहा जाता है।"],"factsEn":["Humidity is the amount of water vapor present in the air.","A hygrometer is sometimes also called a Psychrometer."],"explanationHi":"उच्च आर्द्रता (High humidity) के कारण पसीना वाष्पित नहीं होता, जिससे हमें सामान्य से अधिक गर्मी और बेचैनी महसूस होती है।","explanationEn":"Due to high humidity, sweat does not evaporate, making us feel hotter and more uncomfortable than usual.","memoryTip":"''हाइड्रो'' पानी है, और ''हाइग्रो'' हवा में पानी (नमी) है।","memoryTipEn":"Hygrometer hunts for humidity.","related":["Hydrometer (Density of liquids)","Anemometer (Wind Speed)","Water Vapor"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZdQaK2UElLvfYD-5Arg84', 'General Science', 'समुद्र की गहराई (Depth of the ocean) मापने के लिए किस यंत्र का उपयोग किया जाता है?', 'Which instrument is used to measure the depth of the ocean?', 'फैदोमीटर (Fathometer)', 'Fathometer', 93, 0, '{"facts":["समुद्र की गहराई मापने की इकाई ''फैदम'' (Fathom) है।","एक फैदम (Fathom) 6 फीट (1.8 मीटर) के बराबर होता है।"],"factsEn":["The unit for measuring ocean depth is a ''Fathom''.","One fathom is equal to 6 feet (1.8 meters)."],"explanationHi":"यह यंत्र ध्वनि तरंगों (Sound waves) का उपयोग करता है। यह परावर्तित (reflected) ध्वनि (Echo) को पकड़कर गहराई की गणना करता है (इसे इको-साउंडिंग भी कहते हैं)।","explanationEn":"This instrument uses sound waves. It calculates the depth by catching the reflected sound (echo) (also called echo-sounding).","memoryTip":"समुद्र की गहराई का ''फायदा'' (फैदो) मीटर निकालता है।","memoryTipEn":"Fathoms fathom the deep ocean.","related":["SONAR","Altimeter (Altitude)","Echo-sounding"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mFbMNaRaqOmRWgWbnsy6y', 'General Science', 'मानव शरीर में पसलियों (Ribs) की कितनी जोड़ियां (Pairs) होती हैं?', 'How many pairs of ribs are there in the human body?', '12 जोड़े (कुल 24 पसलियां)', '12 pairs (total 24 ribs)', 91, 0, '{"facts":["ये पसलियां हमारे हृदय (Heart) और फेफड़ों (Lungs) की रक्षा करती हैं।","सामने की ओर ये पसलियां छाती की हड्डी (Sternum) से जुड़ी होती हैं।"],"factsEn":["These ribs protect our heart and lungs.","In the front, these ribs are attached to the breastbone (Sternum)."],"explanationHi":"नीचे की दो जोड़ियों (11वीं और 12वीं) को ''फ्लोटिंग रिब्स'' (Floating ribs) कहा जाता है क्योंकि ये सामने की छाती की हड्डी से जुड़ी नहीं होती हैं।","explanationEn":"The bottom two pairs (11th and 12th) are called ''Floating ribs'' because they are not attached to the breastbone in the front.","memoryTip":"दिन में 12 घंटे, पसलियों के 12 जोड़े।","memoryTipEn":"A dozen pairs protect the core.","related":["Sternum","Floating Ribs","Human Skeleton System (206 Bones)"]}', 'published', 1776097746, 1776097746);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BUrn8Yf2YYOKZcV_obTFI', 'General Knowledge', 'मध्य प्रदेश की ''ग्रीष्मकालीन राजधानी'' (Summer Capital) किसे कहा जाता है?', 'Which place is known as the ''Summer Capital'' of Madhya Pradesh?', 'पचमढ़ी', 'Pachmarhi', 95, 0, '{"facts":["पचमढ़ी सतपुड़ा की पहाड़ियों में स्थित मध्य प्रदेश का एकमात्र हिल स्टेशन है।","यहाँ की जलवायु गर्मियों में बहुत सुहावनी रहती है, इसलिए इसे ग्रीष्मकालीन राजधानी कहा जाता था।"],"factsEn":["Pachmarhi is the only hill station in Madhya Pradesh, located in the Satpura range.","Due to its pleasant climate during summer, it was referred to as the summer capital."],"explanationHi":"ब्रिटिश काल में कैप्टन जेम्स फोर्सिथ (James Forsyth) ने इसकी खोज की थी। यह अपनी गुफाओं, झरनों और पाइन के पेड़ों के लिए प्रसिद्ध है।","explanationEn":"It was discovered by Captain James Forsyth during the British era. It is famous for its caves, waterfalls, and pine trees.","memoryTip":"गर्मी में बचने के लिए लोग ''पचमढ़ी'' की ठंडी वादियों में जाते हैं।","memoryTipEn":"Pachmarhi is the coolest place in MP during summer.","related":["Satpura Range","Dhupgarh","Hill Station"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gAgjej4Hu4XkNE-mOzXBF', 'General Knowledge', 'मध्य प्रदेश में ''रातापानी बाघ अभयारण्य'' (Ratapani Tiger Reserve) किस जिले में है?', 'In which district is the ''Ratapani Tiger Reserve'' located in Madhya Pradesh?', 'रायसेन', 'Raisen', 92, 0, '{"facts":["रातापानी अभयारण्य विंध्याचल पर्वत श्रृंखला में स्थित है।","प्रसिद्ध ''भीमबेटका की गुफाएँ'' भी इसी अभयारण्य के भीतर स्थित हैं।"],"factsEn":["The Ratapani Sanctuary is situated in the Vindhyachal mountain range.","The famous ''Bhimbetka Caves'' are also located within this sanctuary."],"explanationHi":"यह बाघों के अलावा तेंदुओं, जंगली कुत्तों और विभिन्न प्रकार के पक्षियों का प्राकृतिक आवास है। इसे टाइगर रिजर्व का दर्जा प्राप्त है।","explanationEn":"Apart from tigers, it is a natural habitat for leopards, wild dogs, and various birds. It holds the status of a Tiger Reserve.","memoryTip":"रात (रातापानी) में सेन (रायसेन) जी बाघ देखने गए।","memoryTipEn":"Ratapani resides in Raisen.","related":["Bhimbetka Caves","Vindhyachal Range","Project Tiger"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Afrghd25KKdX2a_mmEHD2', 'General Knowledge', 'मध्य प्रदेश का सबसे छोटा वन्यजीव अभयारण्य (Wildlife Sanctuary) कौनसा है?', 'Which is the smallest wildlife sanctuary in Madhya Pradesh?', 'रालामंडल (इंदौर)', 'Ralamandal (Indore)', 94, 0, '{"facts":["इसकी स्थापना 1989 में हुई थी।","इसका क्षेत्रफल मात्र 5 वर्ग किलोमीटर है।"],"factsEn":["It was established in 1989.","Its area is merely 5 square kilometers."],"explanationHi":"यह इंदौर शहर के पास स्थित है और यहाँ लोमड़ी, चीतल और भालू जैसे जानवर पाए जाते हैं। यह ट्रेकिंग के लिए भी प्रसिद्ध है।","explanationEn":"Located near Indore city, it is home to animals like foxes, chitals, and bears. It is also famous for trekking.","memoryTip":"रालामंडल का एरिया एक ''मंडल'' (घेरे) जितना ही छोटा है।","memoryTipEn":"Ralamandal is a mini round (mandal) sanctuary.","related":["Nauradehi (Largest Sanctuary)","Indore","Wildlife Conservation"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Z10S7y2us2ZWtjajKsy0V', 'General Knowledge', '''चचाई जलप्रपात'' (Chachai Falls) मध्य प्रदेश की किस नदी पर स्थित है?', '''Chachai Falls'' is located on which river in Madhya Pradesh?', 'बीहड़ नदी', 'Bihad River', 93, 0, '{"facts":["यह जलप्रपात मध्य प्रदेश के रीवा (Rewa) जिले में स्थित है।","इसकी ऊँचाई लगभग 130 मीटर है।"],"factsEn":["This waterfall is located in the Rewa district of Madhya Pradesh.","Its height is approximately 130 meters."],"explanationHi":"बीहड़ नदी टोंस (Tamsa) नदी की एक सहायक नदी है। यह मध्य प्रदेश के सबसे ऊंचे और सुंदर झरनों में से एक है।","explanationEn":"The Bihad River is a tributary of the Tons (Tamsa) River. It is one of the highest and most beautiful waterfalls in MP.","memoryTip":"रीवा के बीहड़ में चचा (चचाई) पानी पीते हैं।","memoryTipEn":"Chachai plunges down the Bihad.","related":["Rewa","Bahuti Falls","Tons River"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RgGpErbYHwYyDL7LTVija', 'General Knowledge', 'मध्य प्रदेश में ''तात्या टोपे स्टेडियम'' (Tatya Tope Stadium) कहाँ स्थित है?', 'Where is the ''Tatya Tope Stadium'' located in Madhya Pradesh?', 'भोपाल', 'Bhopal', 91, 0, '{"facts":["यह भोपाल का एक प्रमुख मल्टी-पर्पज (Multi-purpose) स्टेडियम है।","यहाँ ''मध्य प्रदेश राज्य खेल निदेशालय'' (Sports Directorate) भी स्थित है।"],"factsEn":["It is a major multi-purpose stadium in Bhopal.","The ''Madhya Pradesh State Sports Directorate'' is also located here."],"explanationHi":"इस स्टेडियम का नाम 1857 के महान स्वतंत्रता सेनानी तात्या टोपे के नाम पर रखा गया है, जिनका मध्य प्रदेश के इतिहास में गहरा योगदान है।","explanationEn":"The stadium is named after Tatya Tope, a great freedom fighter of 1857, who has a deep contribution to MP''s history.","memoryTip":"भोपाल के लोग खेलते समय ''टोपी'' (टोपे) पहनते हैं।","memoryTipEn":"Tatya Tope stadium is the top track in Bhopal.","related":["Aishbagh Stadium","Tatya Tope","Sports Authority of India"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6uFl2BCC5HSf119g07rJf', 'General Knowledge', 'मालवा के पठार की सबसे ऊँची चोटी कौनसी है?', 'Which is the highest peak of the Malwa Plateau?', 'सिगार चोटी (Sigar Peak)', 'Sigar Peak', 90, 0, '{"facts":["सिगार चोटी की ऊँचाई 881 मीटर है।","यह इंदौर जिले के महू (Mhow) क्षेत्र के पास स्थित है।"],"factsEn":["The height of Sigar Peak is 881 meters.","It is located near the Mhow area of Indore district."],"explanationHi":"मालवा का पठार ज्वालामुखीय बेसाल्ट चट्टानों (दक्कन ट्रैप) से बना है। जानापाव (854 मीटर) भी इसी क्षेत्र की एक प्रमुख चोटी है।","explanationEn":"The Malwa Plateau is made of volcanic basalt rocks (Deccan Traps). Janapav (854 m) is also a major peak in this region.","memoryTip":"मालवा के लोग चोटी पर बैठकर ''सिगार'' पीते हैं।","memoryTipEn":"Sigar is the star of Malwa.","related":["Malwa Plateau","Janapav","Mhow"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('pLczOT_Pyf02ZrfITWRxh', 'General Knowledge', 'मध्य प्रदेश की ''खेल राजधानी'' (Sports Capital) किसे कहा जाता है?', 'Which city is known as the ''Sports Capital'' of Madhya Pradesh?', 'इंदौर', 'Indore', 95, 0, '{"facts":["इंदौर को मध्य प्रदेश की वाणिज्यिक और खेल राजधानी दोनों कहा जाता है।","प्रसिद्ध ''होलकर स्टेडियम'' (Holkar Stadium) और ''अभय प्रशाल'' (Abhay Prashal) यहीं स्थित हैं।"],"factsEn":["Indore is known as both the commercial and sports capital of Madhya Pradesh.","The famous ''Holkar Stadium'' and ''Abhay Prashal'' are located here."],"explanationHi":"इंदौर का मध्य प्रदेश में क्रिकेट, टेबल टेनिस और अन्य खेलों के विकास में बहुत बड़ा योगदान रहा है। ''अभय प्रशाल'' राज्य का सबसे बड़ा इंडोर स्टेडियम है।","explanationEn":"Indore has a massive contribution to the development of cricket, table tennis, and other sports in MP. ''Abhay Prashal'' is the state''s largest indoor stadium.","memoryTip":"खेल में हमेशा ''इन'' (Indore) रहो।","memoryTipEn":"Indore is the core of MP sports.","related":["Holkar Stadium","Abhay Prashal","Commercial Capital"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ye71I23CH-BtwX0vCZZgO', 'General Knowledge', '''नर्मदा बचाओ आंदोलन'' (Narmada Bachao Andolan) का प्रमुख नेतृत्वकर्ता कौन है?', 'Who is the main leader of the ''Narmada Bachao Andolan''?', 'मेधा पाटकर', 'Medha Patkar', 96, 0, '{"facts":["यह आंदोलन 1985 में शुरू हुआ था।","इसका मुख्य विरोध सरदार सरोवर बांध और नर्मदा नदी पर बनने वाले अन्य बड़े बांधों के खिलाफ था।"],"factsEn":["This movement started in 1985.","Its main protest was against the Sardar Sarovar Dam and other large dams on the Narmada River."],"explanationHi":"इस आंदोलन ने बांधों के कारण विस्थापित (Displaced) होने वाले आदिवासियों, किसानों और पर्यावरण की रक्षा के लिए संघर्ष किया। बाबा आमटे ने भी इसमें बड़ा योगदान दिया।","explanationEn":"This movement fought to protect the environment, farmers, and tribals displaced by the dams. Baba Amte also made a significant contribution to it.","memoryTip":"नर्मदा की ''मेधा'' (बुद्धि) पाटकर जी ने बचाई।","memoryTipEn":"Medha protests for the Narmada.","related":["Sardar Sarovar Dam","Baba Amte","Environmental Movements"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('E7xYtXK4k54-sSZ35J4QP', 'General Knowledge', 'मध्य प्रदेश में ''कालिदास अकादमी'' कहाँ स्थित है?', 'Where is the ''Kalidas Academy'' located in Madhya Pradesh?', 'उज्जैन', 'Ujjain', 94, 0, '{"facts":["कालिदास अकादमी की स्थापना 1978 में की गई थी।","इसका उद्देश्य महाकवि कालिदास के साहित्य और संस्कृत भाषा को बढ़ावा देना है।"],"factsEn":["Kalidas Academy was established in 1978.","Its objective is to promote the literature of the great poet Kalidas and the Sanskrit language."],"explanationHi":"कालिदास उज्जैन के राजा विक्रमादित्य के नवरत्नों में से एक थे। हर साल यहाँ भव्य ''कालिदास समारोह'' आयोजित किया जाता है।","explanationEn":"Kalidas was one of the Navaratnas of King Vikramaditya of Ujjain. A grand ''Kalidas Samaroh'' is organized here every year.","memoryTip":"कालिदास उज्जैन के महाकाल के भक्त थे।","memoryTipEn":"Kalidas lived and learned in Ujjain.","related":["Kalidas Samaroh","King Vikramaditya","Sanskrit Literature"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YtkEyukl27g_RAnP9b0cQ', 'General Knowledge', 'मध्य प्रदेश का ''पहला आकाशवाणी केंद्र'' (First All India Radio Station) कहाँ स्थापित किया गया था?', 'Where was the ''First All India Radio Station'' of Madhya Pradesh established?', 'इंदौर', 'Indore', 92, 0, '{"facts":["यह 22 मई 1955 को स्थापित किया गया था।","दूसरा आकाशवाणी केंद्र 1956 में भोपाल में स्थापित हुआ।"],"factsEn":["It was established on May 22, 1955.","The second AIR station was set up in Bhopal in 1956."],"explanationHi":"आकाशवाणी (AIR) का यह केंद्र मध्य प्रदेश में सूचना, शिक्षा और मनोरंजन के प्रसारण का पहला आधिकारिक माध्यम था।","explanationEn":"This AIR station was the first official medium for broadcasting information, education, and entertainment in Madhya Pradesh.","memoryTip":"हवा (आकाशवाणी) सबसे पहले ''इंदौर'' (Indoors) में आई।","memoryTipEn":"Indore aired the first radio waves in MP.","related":["All India Radio","Bhopal AIR","Broadcasting in MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qOSdZPZhNZeVrmTMcwQx3', 'General Knowledge', 'मध्य प्रदेश में ''गधों का मेला'' (Donkey Fair) कहाँ लगता है?', 'Where is the ''Donkey Fair'' held in Madhya Pradesh?', 'उज्जैन (और चित्रकूट)', 'Ujjain (and Chitrakoot)', 88, 0, '{"facts":["उज्जैन में क्षिप्रा नदी के तट पर यह अनोखा मेला लगता है।","सतना जिले के चित्रकूट में भी दीपावली के समय गधों का बड़ा मेला लगता है।"],"factsEn":["This unique fair is held on the banks of the Kshipra river in Ujjain.","A large donkey fair is also held in Chitrakoot (Satna district) during Diwali."],"explanationHi":"इस मेले में दूर-दूर से व्यापारी गधों और खच्चरों (Mules) की खरीद-फरोख्त के लिए आते हैं। यह अपनी तरह का एक अनूठा व्यापारिक मेला है।","explanationEn":"Traders from far away come to this fair for buying and selling donkeys and mules. It is a unique trading fair of its kind.","memoryTip":"उज्जैन और चित्रकूट में गधों की भी कीमत है।","memoryTipEn":"Donkeys deal in Ujjain.","related":["Chitrakoot","Ujjain","Animal Fairs"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('8lTe-47fKcdHk_OaODKpg', 'General Knowledge', 'प्रसिद्ध ''खजुराहो नृत्य समारोह'' किस जिले में आयोजित किया जाता है?', 'The famous ''Khajuraho Dance Festival'' is organized in which district?', 'छतरपुर', 'Chhatarpur', 95, 0, '{"facts":["यह भारत का सबसे बड़ा शास्त्रीय नृत्य समारोह है।","इसकी शुरुआत 1975 में हुई थी और यह हर साल फरवरी में होता है।"],"factsEn":["It is the largest classical dance festival in India.","It started in 1975 and is held every year in February."],"explanationHi":"यह समारोह खजुराहो के शानदार चंदेल कालीन मंदिरों (विश्व धरोहर) की पृष्ठभूमि में खुले आसमान के नीचे आयोजित किया जाता है।","explanationEn":"The festival is organized open-air against the backdrop of the magnificent Chandela era temples of Khajuraho (a World Heritage Site).","memoryTip":"खजुराहो के मंदिर ''छतरपुर'' जिले की ''छतरी'' के नीचे हैं।","memoryTipEn":"Chhatarpur hosts the Khajuraho rhythm.","related":["Classical Dances","Chandela Dynasty","Tourism in MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jd_OMZ5R4ctFwJCJVeG3F', 'General Knowledge', '''तानसेन सम्मान'' किस क्षेत्र में उत्कृष्ट योगदान के लिए दिया जाता है?', 'The ''Tansen Samman'' is given for outstanding contribution in which field?', 'हिन्दुस्तानी शास्त्रीय संगीत', 'Hindustani Classical Music', 96, 0, '{"facts":["यह मध्य प्रदेश सरकार के संस्कृति विभाग द्वारा प्रदान किया जाता है।","इसकी स्थापना 1980 में की गई थी।"],"factsEn":["It is conferred by the Department of Culture, Government of Madhya Pradesh.","It was established in 1980."],"explanationHi":"यह पुरस्कार ग्वालियर में आयोजित होने वाले वार्षिक ''तानसेन समारोह'' के दौरान शास्त्रीय गायन या वादन के दिग्गजों को दिया जाता है।","explanationEn":"This award is presented to stalwarts of classical singing or instrument playing during the annual ''Tansen Samaroh'' held in Gwalior.","memoryTip":"तानसेन एक गायक थे, तो सम्मान भी ''संगीत'' में मिलेगा।","memoryTipEn":"Tansen is synonymous with classical music.","related":["Gwalior","Hindustani Classical Music","Kalidas Samman"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('eqGZQHOR4GyV8OPTXWjEo', 'General Knowledge', '''गणगौर'' (Gangaur) मध्य प्रदेश के किस क्षेत्र का प्रमुख लोक नृत्य है?', '''Gangaur'' is the major folk dance of which region of Madhya Pradesh?', 'निमाड़ (Nimar)', 'Nimar', 90, 0, '{"facts":["यह नृत्य शिव (गण) और पार्वती (गौरी) की पूजा का पर्व है।","यह मुख्य रूप से चैत्र मास (मार्च-अप्रैल) में किया जाता है।"],"factsEn":["This dance is a festival worshipping Lord Shiva (Gan) and Parvati (Gauri).","It is mainly performed in the Chaitra month (March-April)."],"explanationHi":"निमाड़ क्षेत्र (खंडवा, खरगोन, बड़वानी) में गणगौर का बहुत महत्व है। इस दौरान महिलाएँ रंग-बिरंगे कपड़े पहनकर ''झालरिया'' गाते हुए नृत्य करती हैं।","explanationEn":"Gangaur holds great importance in the Nimar region (Khandwa, Khargone, Barwani). Women wear colorful clothes and dance while singing ''Jhalariya''.","memoryTip":"''निमाड़'' के लोग ''गौरी'' (गणगौर) की पूजा करते हैं।","memoryTipEn":"Nimar celebrates the Gangaur grace.","related":["Khandwa","Khargone","Folk Dances of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gLJP5-_EF9rmdgBbY81Eu', 'General Knowledge', 'प्रसिद्ध कला केंद्र ''भारत भवन'' (Bharat Bhavan) कहाँ स्थित है?', 'Where is the famous art center ''Bharat Bhavan'' located?', 'भोपाल', 'Bhopal', 95, 0, '{"facts":["यह एक बहु-कला (Multi-art) संग्रहालय और सांस्कृतिक केंद्र है।","इसकी स्थापना 1982 में हुई थी।"],"factsEn":["It is a multi-art museum and cultural center.","It was established in 1982."],"explanationHi":"भारत भवन में आर्ट गैलरी, थियेटर, और पुस्तकालय मौजूद हैं। यह भारतीय कला, साहित्य और रंगमंच को सहेजने का एक बेहतरीन मंच है।","explanationEn":"Bharat Bhavan houses art galleries, theatres, and libraries. It is an excellent platform for preserving Indian art, literature, and theatre.","memoryTip":"पूरे ''भारत'' का ''भवन'' मध्य प्रदेश की राजधानी ''भोपाल'' में है।","memoryTipEn":"Bharat Bhavan is Bhopal''s cultural core.","related":["Charles Correa","Cultural Centers","Upper Lake Bhopal"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('2s7OnqFfUROtj8zw2EZJN', 'General Knowledge', 'भोपाल स्थित ''भारत भवन'' के वास्तुकार (Architect) कौन थे?', 'Who was the architect of ''Bharat Bhavan'' located in Bhopal?', 'चार्ल्स कोरिया (Charles Correa)', 'Charles Correa', 92, 0, '{"facts":["चार्ल्स कोरिया एक विश्व प्रसिद्ध भारतीय वास्तुकार (Architect) थे।","उन्होंने मध्य प्रदेश के नए विधानसभा भवन (Indira Gandhi Vidhan Bhavan) का भी डिजाइन तैयार किया था।"],"factsEn":["Charles Correa was a world-renowned Indian architect.","He also designed the new State Assembly building of MP (Indira Gandhi Vidhan Bhavan)."],"explanationHi":"भारत भवन का डिजाइन इस तरह से बनाया गया है कि यह प्राकृतिक ढलान के साथ घुल-मिल जाता है और भोपाल की बड़ी झील (Upper Lake) का सुंदर नजारा देता है।","explanationEn":"The design of Bharat Bhavan seamlessly blends with the natural slope, offering a beautiful view of Bhopal''s Upper Lake.","memoryTip":"भारत के भवन को ''कोरिया'' के वास्तुकार ने बनाया।","memoryTipEn":"Correa crafted the cultural centre.","related":["Bharat Bhavan","Vidhan Bhavan Bhopal","Modern Architecture"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Bdoi_vmwCku1evFgLAMFn', 'General Knowledge', '''इंदिरा गांधी राष्ट्रीय मानव संग्रहालय'' (National Museum of Mankind) कहाँ स्थित है?', 'Where is the ''Indira Gandhi Rashtriya Manav Sangrahalaya'' located?', 'भोपाल', 'Bhopal', 94, 0, '{"facts":["यह भारत का अपनी तरह का एकमात्र मानव विज्ञान (Anthropology) संग्रहालय है।","यह श्यामला हिल्स, भोपाल में 200 एकड़ के विशाल क्षेत्र में फैला है।"],"factsEn":["It is the only anthropology museum of its kind in India.","It is spread over a vast 200-acre area on Shyamala Hills, Bhopal."],"explanationHi":"यह संग्रहालय भारत के विभिन्न आदिवासी समुदायों के प्राकृतिक आवासों, कला, और जीवन शैली को उनके मूल रूप (Open-air exhibits) में प्रदर्शित करता है।","explanationEn":"This museum exhibits the natural habitats, art, and lifestyle of various tribal communities of India in their original forms (open-air exhibits).","memoryTip":"''मानव'' की कहानी भोपाल की पहाड़ियों पर लिखी है।","memoryTipEn":"Mankind''s museum is in Bhopal.","related":["Anthropology","Tribal Culture","Shyamala Hills"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ESWN7HKsyTFnbXpxFJWgH', 'General Knowledge', 'मध्य प्रदेश का ''एकमात्र हिल स्टेशन'' (Hill Station) कौनसा है?', 'Which is the ''only Hill Station'' of Madhya Pradesh?', 'पचमढ़ी', 'Pachmarhi', 97, 0, '{"facts":["यह होशंगाबाद (अब नर्मदापुरम) जिले में स्थित है।","इसे ''सतपुड़ा की रानी'' (Queen of Satpura) कहा जाता है।"],"factsEn":["It is located in the Hoshangabad (now Narmadapuram) district.","It is called the ''Queen of Satpura''."],"explanationHi":"पौराणिक कथाओं के अनुसार, पांडवों ने अपने अज्ञातवास का कुछ समय यहीं बिताया था, जिसके कारण यहाँ ''पांडव गुफाएँ'' मौजूद हैं।","explanationEn":"According to mythology, the Pandavas spent part of their exile here, which is why the ''Pandav Caves'' are located here.","memoryTip":"''पच'' (पाँच) मढ़ी (गुफाएँ) = पचमढ़ी हिल स्टेशन।","memoryTipEn":"Pachmarhi is the peak of MP tourism.","related":["Dhupgarh","Satpura Range","Pandav Caves"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SFgJszEPUFdAd-ZVwCI7S', 'General Knowledge', 'वीर रस प्रधान ''आल्हा गायन'' (Alha Gayan) मध्य प्रदेश के किस क्षेत्र में लोकप्रिय है?', 'The heroic ballad ''Alha Gayan'' is popular in which region of Madhya Pradesh?', 'बुंदेलखंड', 'Bundelkhand', 93, 0, '{"facts":["आल्हा और उदल (Alha and Udal) 12वीं शताब्दी के चंदेल राजा परमार्दिदेव के महान सेनापति थे।","यह गायन मुख्य रूप से बरसात के मौसम (Monsoon) में गाया जाता है।"],"factsEn":["Alha and Udal were great generals of the 12th-century Chandela King Paramardi Deva.","This singing is primarily performed during the monsoon season."],"explanationHi":"इन वीर भाइयों ने पृथ्वीराज चौहान के खिलाफ भी युद्ध लड़ा था। आल्हा गायन में 52 युद्धों की गाथा बड़े जोश के साथ ढोलक और मंजीरे पर गाई जाती है।","explanationEn":"These brave brothers also fought against Prithviraj Chauhan. The ballad tells the tale of 52 battles with great enthusiasm on the dholak and manjeera.","memoryTip":"बुंदेलखंड के लोग ''आल्हा'' गाकर जोश में आ जाते हैं।","memoryTipEn":"Alha echoes the bravery of Bundelkhand.","related":["Bundelkhand","Chandela Dynasty","Folk Music of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CgsCdcSG4NlD6gz1qhRQO', 'General Knowledge', 'मध्य प्रदेश का ''चेरापूंजी'' किसे कहा जाता है?', 'Which place is called the ''Cherrapunji'' of Madhya Pradesh?', 'पचमढ़ी', 'Pachmarhi', 91, 0, '{"facts":["पचमढ़ी में मध्य प्रदेश की सर्वाधिक वर्षा (लगभग 200 सेमी या 199 सेमी) होती है।","यह सतपुड़ा पर्वत श्रृंखला की महादेव पहाड़ियों पर स्थित है।"],"factsEn":["Pachmarhi receives the highest rainfall in Madhya Pradesh (approx 200 cm or 199 cm).","It is located on the Mahadeo Hills of the Satpura mountain range."],"explanationHi":"पहाड़ी इलाका और घने जंगल होने के कारण यहाँ मानसूनी हवाओं से भारी बारिश होती है, इसलिए इसकी तुलना सबसे अधिक वर्षा वाले स्थान ''चेरापूंजी'' (मेघालय) से की जाती है।","explanationEn":"Due to its hilly terrain and dense forests, it receives heavy rainfall from monsoon winds, hence it is compared to the wettest place ''Cherrapunji'' (Meghalaya).","memoryTip":"चेरापूंजी जैसी झमाझम बारिश एमपी में सिर्फ पचमढ़ी में होती है।","memoryTipEn":"Pachmarhi pours like Cherrapunji.","related":["Highest Rainfall in MP","Mahadeo Hills","Satpura"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uHp8fqzuU1IDmWDzKZDjq', 'General Science', 'चंबल नदी घाटी किस प्रकार के मृदा अपरदन (Soil Erosion) के लिए कुख्यात है?', 'The Chambal River valley is notorious for which type of soil erosion?', 'अवनालिका अपरदन (Gully Erosion)', 'Gully Erosion', 95, 0, '{"facts":["इस अपरदन के कारण चंबल में गहरी और चौड़ी खाइयां बन गई हैं, जिन्हें ''चंबल के बीहड़'' (Chambal Ravines) कहा जाता है।","इससे भिंड, मुरैना और श्योपुर जिले सबसे अधिक प्रभावित हैं।"],"factsEn":["This erosion has created deep and wide ravines in Chambal, known as ''Chambal Ravines''.","Bhind, Morena, and Sheopur districts are the most affected."],"explanationHi":"पानी के तेज़ बहाव ने यहाँ की पीली/जलोढ़ मिट्टी को गहराई तक काट दिया है, जिससे कृषि योग्य भूमि नष्ट हो गई और ये बीहड़ डकैतों की शरणस्थली बन गए।","explanationEn":"The fast flow of water has deeply eroded the yellow/alluvial soil here, destroying arable land and turning these ravines into hideouts for dacoits.","memoryTip":"चंबल की ''नाली'' (अवनालिका) बहुत गहरी है।","memoryTipEn":"Gully erosion gouged the Chambal ravines.","related":["Chambal Ravines","Morena","Soil Conservation"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vQ8hq6-IC_m8joJ1tHHK8', 'General Knowledge', 'मध्य प्रदेश के किस जिले के ''कड़कनाथ'' मुर्गे को GI टैग मिला है?', 'The ''Kadaknath'' chicken of which district of Madhya Pradesh has received a GI Tag?', 'झाबुआ', 'Jhabua', 94, 0, '{"facts":["कड़कनाथ मुर्गा अपने काले रंग के पंख, मांस और यहाँ तक कि काले खून के लिए जाना जाता है।","इसे 2018 में ''भौगोलिक संकेत'' (Geographical Indication) का दर्जा मिला।"],"factsEn":["The Kadaknath chicken is known for its black feathers, black meat, and even black blood.","It received the ''Geographical Indication'' (GI) status in 2018."],"explanationHi":"यह मुर्गा औषधीय गुणों (high protein, low fat/cholesterol) से भरपूर माना जाता है। मध्य प्रदेश ने इसे लेकर छत्तीसगढ़ के साथ GI टैग की कानूनी लड़ाई जीती थी।","explanationEn":"This chicken is considered rich in medicinal properties (high protein, low fat/cholesterol). MP won the legal battle for its GI tag against Chhattisgarh.","memoryTip":"झाबुआ का ''कड़क'' मुर्गा पूरे देश में मशहूर है।","memoryTipEn":"Jhabua''s black bird boasts high protein.","related":["Geographical Indication (GI)","Jhabua District","Alirajpur"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('k2jksVyyXmux2maEQxU1C', 'General Knowledge', 'मध्य प्रदेश की सीमा कितने अन्य राज्यों को स्पर्श करती है?', 'The border of Madhya Pradesh touches how many other states?', '5 (पाँच)', '5 (Five)', 97, 0, '{"facts":["ये राज्य हैं: उत्तर प्रदेश, छत्तीसगढ़, महाराष्ट्र, गुजरात और राजस्थान।","मध्य प्रदेश एक ''लैंडलॉक'' (Landlocked) राज्य है।"],"factsEn":["These states are: Uttar Pradesh, Chhattisgarh, Maharashtra, Gujarat, and Rajasthan.","Madhya Pradesh is a ''landlocked'' state."],"explanationHi":"विभाजन (2000) से पहले मध्य प्रदेश की सीमा 7 राज्यों से लगती थी। अब इसकी कोई अंतरराष्ट्रीय सीमा या समुद्री तटरेखा नहीं है।","explanationEn":"Before the partition in 2000, MP shared its border with 7 states. Now, it has no international border or coastline.","memoryTip":"एमपी 5 उंगलियों (राज्यों) के बीच में ''मुट्ठी'' की तरह है।","memoryTipEn":"Five states surround the heart of India.","related":["Landlocked State","Geography of MP","Border States"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HlGbTt53i8beDCP2E_MKj', 'General Knowledge', 'मध्य प्रदेश की सबसे लंबी सीमा किस राज्य के साथ लगती है?', 'With which state does Madhya Pradesh share its longest border?', 'उत्तर प्रदेश', 'Uttar Pradesh', 95, 0, '{"facts":["मध्य प्रदेश के 13 जिले (निवाड़ी सहित) उत्तर प्रदेश की सीमा को छूते हैं।","मध्य प्रदेश की सबसे छोटी सीमा गुजरात (केवल झाबुआ और अलीराजपुर) के साथ लगती है।"],"factsEn":["13 districts of Madhya Pradesh (including Niwari) touch the border of UP.","MP shares its shortest border with Gujarat (only Jhabua and Alirajpur)."],"explanationHi":"उत्तरी दिशा में एमपी का विस्तार यूपी के साथ सबसे अधिक है, जहाँ चंबल, बेतवा और केन जैसी नदियां भी बहती हैं।","explanationEn":"In the north, MP''s extent is largest along UP, where rivers like Chambal, Betwa, and Ken also flow.","memoryTip":"सबसे लंबी सीमा, सबसे बड़े (जनसंख्या में) राज्य (UP) के साथ।","memoryTipEn":"UP holds the longest line with MP.","related":["Gujarat Border (Shortest)","Niwari District","Geography of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jq6fltY_0c6_90srtWQez', 'General Knowledge', 'वर्ष 2011 की जनगणना के अनुसार मध्य प्रदेश का सबसे कम साक्षरता (Lowest Literacy) वाला जिला कौनसा है?', 'According to the 2011 census, which is the district with the lowest literacy rate in Madhya Pradesh?', 'अलीराजपुर', 'Alirajpur', 92, 0, '{"facts":["अलीराजपुर की साक्षरता दर लगभग 36.1% है।","यह पूरे भारत में सबसे कम साक्षरता दर वाला जिला है।"],"factsEn":["The literacy rate of Alirajpur is around 36.1%.","It is the district with the lowest literacy rate in all of India."],"explanationHi":"यह एक आदिवासी बहुल (Tribal-dominated) क्षेत्र है। इसके विपरीत, मध्य प्रदेश में सबसे अधिक साक्षरता दर वाला जिला जबलपुर (81.1%) है।","explanationEn":"It is a tribal-dominated region. Conversely, the district with the highest literacy rate in Madhya Pradesh is Jabalpur (81.1%).","memoryTip":"अलीराजपुर में ''राज'' तो है पर ''अक्षर'' (साक्षरता) कम हैं।","memoryTipEn":"Alirajpur needs a literacy leap.","related":["Jabalpur (Highest Literacy)","2011 Census MP","Tribal Districts"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('1AhCZNKvBrSIUt-48fPOp', 'General Knowledge', '2011 की जनगणना के अनुसार मध्य प्रदेश का लिंगानुपात (Sex Ratio) कितना है?', 'According to the 2011 census, what is the sex ratio of Madhya Pradesh?', '931 (प्रति 1000 पुरुष)', '931 (per 1000 males)', 94, 0, '{"facts":["भारत का राष्ट्रीय लिंगानुपात 943 है।","मध्य प्रदेश में सबसे अधिक लिंगानुपात बालाघाट (1021) जिले में है।"],"factsEn":["India''s national sex ratio is 943.","Balaghat district has the highest sex ratio (1021) in Madhya Pradesh."],"explanationHi":"बालाघाट में पुरुषों से अधिक महिलाएं हैं। मध्य प्रदेश में सबसे कम लिंगानुपात भिंड (837) जिले में है।","explanationEn":"Balaghat has more women than men. The lowest sex ratio in MP is in Bhind district (837).","memoryTip":"9-3-1 (नौ तीन एक) का आंकड़ा है एमपी का।","memoryTipEn":"931 women for a thousand men in MP.","related":["Balaghat (Highest Sex Ratio)","Bhind (Lowest Sex Ratio)","Demographics of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('u1PN_1pu3Dy6qh-809o6b', 'General Knowledge', 'पारंपरिक ''गोटमार मेला'' (Gotmar Mela) मध्य प्रदेश के किस जिले में लगता है?', 'In which district of Madhya Pradesh is the traditional ''Gotmar Mela'' held?', 'छिंदवाड़ा', 'Chhindwara', 90, 0, '{"facts":["यह मेला पांढुर्णा (अब जिला) और सावरगांव के बीच जाम नदी (Jam River) के तट पर लगता है।","''गोटमार'' का अर्थ है पत्थर (गोट) मारना।"],"factsEn":["This fair is held on the banks of the Jam River between Pandhurna (now a district) and Savargaon.","''Gotmar'' literally translates to hitting with stones."],"explanationHi":"यह एक अनूठी और खतरनाक परंपरा है जिसमें दोनों गांवों के लोग नदी के बीच गड़े झंडे को पाने के लिए एक-दूसरे पर पत्थर फेंकते हैं।","explanationEn":"It is a unique and dangerous tradition where people from both villages hurl stones at each other to grab a flag planted in the middle of the river.","memoryTip":"छिंदवाड़ा में ''पत्थर'' (गोट) मारकर ''छेद'' कर देते हैं।","memoryTipEn":"Gotmar means throwing stones in Chhindwara.","related":["Jam River","Pandhurna","Fairs of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nUdMlrN9Jo7YGqx_7n_Ys', 'General Knowledge', '''बाघ प्रिंट'' (Bagh Print) मध्य प्रदेश के किस जिले का प्रसिद्ध हस्तशिल्प है?', '''Bagh Print'' is a famous handicraft of which district of Madhya Pradesh?', 'धार (Dhar)', 'Dhar', 92, 0, '{"facts":["यह एक पारंपरिक ब्लॉक प्रिंटिंग (Block printing) तकनीक है जिसमें प्राकृतिक रंगों का उपयोग होता है।","इसे भारत सरकार द्वारा भौगोलिक संकेत (GI Tag) प्राप्त है।"],"factsEn":["It is a traditional block printing technique using natural colors.","It has received a Geographical Indication (GI Tag) from the Govt of India."],"explanationHi":"धार जिले के ''बाघ'' नामक कस्बे में बाघिनी नदी के पानी का उपयोग करके कपड़ों पर यह छपाई की जाती है, जो इसे विशेष रंगत देती है। इस्माइल सुलेमानजी खत्री ने इसे अंतरराष्ट्रीय स्तर पर प्रसिद्ध किया।","explanationEn":"In the town of ''Bagh'' in Dhar, fabrics are printed using the water of the Baghini river, which gives it a unique tone. Ismail Sulemanji Khatri made it internationally famous.","memoryTip":"धार के ''बाघ'' कपड़ों पर छप जाते हैं।","memoryTipEn":"Dhar designs the Bagh prints.","related":["GI Tag","Handicrafts of MP","Baghini River"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('eH5WwZukhZ3jXwZ-W9QD2', 'General Knowledge', 'मध्य प्रदेश में ''माहेश्वरी साड़ी'' उद्योग को स्थापित करने का श्रेय किसे जाता है?', 'Who gets the credit for establishing the ''Maheshwari Saree'' industry in Madhya Pradesh?', 'देवी अहिल्याबाई होल्कर', 'Devi Ahilyabai Holkar', 94, 0, '{"facts":["यह उद्योग 18वीं शताब्दी में खरगोन (Khargone) जिले के महेश्वर में शुरू हुआ था।","माहेश्वरी साड़ियों को भी भौगोलिक संकेत (GI Tag) मिला हुआ है।"],"factsEn":["This industry started in the 18th century in Maheshwar, Khargone district.","Maheshwari sarees have also been granted a Geographical Indication (GI Tag)."],"explanationHi":"महारानी अहिल्याबाई ने सूरत और मालवा से कुशल बुनकरों (weavers) को महेश्वर बुलाया था ताकि शाही परिवार और मेहमानों के लिए खास साड़ियां बुनी जा सकें।","explanationEn":"Queen Ahilyabai invited skilled weavers from Surat and Malwa to Maheshwar to weave special sarees for the royal family and guests.","memoryTip":"अहिल्याबाई ''महेश्वर'' में ''माहेश्वरी'' साड़ियाँ पहनती थीं।","memoryTipEn":"Ahilyabai weaved the Maheshwari magic.","related":["Chanderi Sarees","Maheshwar","GI Tag"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Mq_48UxUFDbD42mRMHx9n', 'General Knowledge', 'मध्य प्रदेश का सर्वाधिक वन क्षेत्रफल (Highest Forest Area) वाला जिला कौनसा है?', 'Which is the district with the highest forest area in Madhya Pradesh?', 'बालाघाट', 'Balaghat', 95, 0, '{"facts":["बालाघाट जिले का लगभग 53% से अधिक हिस्सा जंगलों से ढका है।","मध्य प्रदेश पूरे भारत में सबसे अधिक वन क्षेत्र (Forest Cover) वाला राज्य है।"],"factsEn":["Over 53% of Balaghat district is covered by forests.","Madhya Pradesh is the state with the highest forest cover in all of India."],"explanationHi":"बालाघाट में घने बांस और साल के जंगल पाए जाते हैं। इसके विपरीत, सबसे कम वन क्षेत्रफल वाला जिला ''उज्जैन'' है।","explanationEn":"Balaghat is home to dense bamboo and sal forests. In contrast, the district with the lowest forest area is ''Ujjain''.","memoryTip":"जंगलों की ''बाल'' (बालाघाट) एमपी के सिर पर घनी है।","memoryTipEn":"Balaghat boasts the biggest woods.","related":["Ujjain (Lowest Forest Area)","ISFR 2021","Forests of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('r3ng9ziJ6VNeICMEY_oaz', 'General Knowledge', 'मध्य प्रदेश में ''लाडली लक्ष्मी योजना'' किस वर्ष शुरू की गई थी?', 'In which year was the ''Ladli Laxmi Yojana'' launched in Madhya Pradesh?', '2007', '2007', 96, 0, '{"facts":["यह योजना 1 अप्रैल 2007 को मुख्यमंत्री शिवराज सिंह चौहान द्वारा शुरू की गई थी।","इस योजना का उद्देश्य बालिका जन्म के प्रति सकारात्मक सोच पैदा करना और लिंगानुपात में सुधार लाना है।"],"factsEn":["This scheme was launched on April 1, 2007, by CM Shivraj Singh Chouhan.","The objective of this scheme is to create a positive attitude towards the birth of a girl child and improve the sex ratio."],"explanationHi":"यह भारत की सबसे सफल योजनाओं में से एक है, जिसे अन्य राज्यों ने भी अपनाया है। 2022 में इसका दूसरा चरण (लाडली लक्ष्मी 2.0) भी शुरू किया गया है।","explanationEn":"It is one of India''s most successful schemes, adopted by other states as well. Its second phase (Ladli Laxmi 2.0) was also launched in 2022.","memoryTip":"2007 में ''सात'' (साथ) निभाने लाडली लक्ष्मी आई।","memoryTipEn":"2007 launched the Ladli legacy.","related":["Women Empowerment","Beti Bachao Beti Padhao","Sex Ratio"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xwex1VDUegizw4G-2ngGc', 'General Knowledge', 'मध्य प्रदेश उच्च न्यायालय भवन (जबलपुर) के वास्तुकार (Architect) कौन थे?', 'Who was the architect of the Madhya Pradesh High Court building (Jabalpur)?', 'हेनरी इरविन (Henry Irwin)', 'Henry Irwin', 89, 0, '{"facts":["यह शानदार इमारत 1899 में बनकर तैयार हुई थी।","यह इतालवी गॉथिक (Italian Gothic) वास्तुकला शैली का एक उत्कृष्ट उदाहरण है।"],"factsEn":["This magnificent building was completed in 1899.","It is an outstanding example of Italian Gothic architecture style."],"explanationHi":"हेनरी इरविन ब्रिटिश राज के दौरान एक प्रमुख वास्तुकार थे, जिन्होंने मैसूर पैलेस और शिमला के वाइसरीगल लॉज का भी डिजाइन तैयार किया था।","explanationEn":"Henry Irwin was a prominent architect during the British Raj who also designed the Mysore Palace and the Viceregal Lodge in Shimla.","memoryTip":"कानून की इमारत इतनी पक्की है कि सब ''विन'' (Irwin) करना चाहते हैं।","memoryTipEn":"Irwin imagined the MP justice hall.","related":["Jabalpur","Gothic Architecture","Charles Correa (Bharat Bhavan)"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mQTBH52B8HiVNjHL67M1f', 'General Knowledge', '''ओंकारेश्वर'' (Omkareshwar) ज्योतिर्लिंग किस नदी के तट पर स्थित है?', '''Omkareshwar'' Jyotirlinga is situated on the banks of which river?', 'नर्मदा', 'Narmada', 95, 0, '{"facts":["यह मध्य प्रदेश के खंडवा (Khandwa) जिले में स्थित है।","यह भारत के 12 ज्योतिर्लिंगों में से एक है।"],"factsEn":["It is located in the Khandwa district of Madhya Pradesh.","It is one of the 12 Jyotirlingas in India."],"explanationHi":"ओंकारेश्वर मांधाता (Mandhata) नामक एक द्वीप पर स्थित है, जिसका आकार हिंदू प्रतीक ''ॐ'' (Om) के समान माना जाता है।","explanationEn":"Omkareshwar is situated on an island called Mandhata, which is believed to be shaped like the Hindu symbol ''Om''.","memoryTip":"''ॐ'' (ओंकारेश्वर) के मंत्र के साथ ''नर्मदा'' बहती है।","memoryTipEn":"Narmada flows past the Omkareshwar shrine.","related":["Mahakaleshwar (Ujjain)","Khandwa","Jyotirlinga"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('bpA-ZxGGR3eVlJGt5FY45', 'General Knowledge', 'मध्य प्रदेश में ''मंडीदीप'' (Mandideep) औद्योगिक क्षेत्र किस जिले में स्थित है?', 'In which district is the ''Mandideep'' industrial area located in Madhya Pradesh?', 'रायसेन', 'Raisen', 93, 0, '{"facts":["यह भोपाल से मात्र 23 किलोमीटर दूर है, लेकिन रायसेन जिले में आता है।","मंडीदीप में भारत का पहला ''ऑप्टिकल फाइबर'' (Optical Fiber) कारखाना स्थित है।"],"factsEn":["It is just 23 km away from Bhopal but falls in the Raisen district.","India''s first ''Optical Fiber'' factory is located in Mandideep."],"explanationHi":"यह मध्य प्रदेश के सबसे बड़े औद्योगिक हब (Industrial hubs) में से एक है, जहाँ कई बड़ी बहुराष्ट्रीय कंपनियां काम करती हैं।","explanationEn":"It is one of the largest industrial hubs in Madhya Pradesh, where several large multinational companies operate.","memoryTip":"रायसेन की ''मंडी'' में ''दीप'' जलते हैं (फैक्ट्रियां चलती हैं)।","memoryTipEn":"Mandideep makes money for Raisen.","related":["Pithampur (Dhar)","Optical Fiber Factory","Industrial Areas of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Bh6rt0m4VeESNjbCNiePh', 'General Knowledge', 'ऐतिहासिक नगर ''ओरछा'' (Orchha) किस नदी के किनारे बसा है?', 'The historical town of ''Orchha'' is situated on the banks of which river?', 'बेतवा', 'Betwa', 94, 0, '{"facts":["ओरछा मध्य प्रदेश के नए जिले ''निवाड़ी'' (Niwari) में आता है।","यह अपने ''राम राजा मंदिर'' (Ram Raja Temple) के लिए पूरे भारत में प्रसिद्ध है।"],"factsEn":["Orchha comes under the new district ''Niwari'' of MP.","It is famous all over India for its ''Ram Raja Temple''."],"explanationHi":"ओरछा की स्थापना 16वीं शताब्दी में बुंदेला शासक रुद्र प्रताप सिंह ने की थी। यहाँ भगवान राम की राजा के रूप में पूजा की जाती है और उन्हें गार्ड ऑफ ऑनर (सलामी) दी जाती है।","explanationEn":"Orchha was founded by the Bundela ruler Rudra Pratap Singh in the 16th century. Lord Rama is worshipped as a king here and is given a Guard of Honor.","memoryTip":"ओरछा के राजा ''राम'' बेतवा में स्नान करते हैं।","memoryTipEn":"Orchha borders the Betwa.","related":["Niwari","Ram Raja Temple","Bundela Architecture"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_iKnBeE3PdkyfyBfxtKhs', 'General Knowledge', 'दक्षिण का प्रवेश द्वार कहे जाने वाला ''असीरगढ़ का किला'' मध्य प्रदेश के किस जिले में है?', 'The ''Asirgarh Fort'', known as the Gateway to the South, is in which district of Madhya Pradesh?', 'बुरहानपुर', 'Burhanpur', 92, 0, '{"facts":["असीरगढ़ का किला सतपुड़ा की पहाड़ियों में स्थित है।","इसे ''दक्कन की कुंजी'' (Key to the Deccan) भी कहा जाता था।"],"factsEn":["The Asirgarh Fort is situated in the Satpura hills.","It was also called the ''Key to the Deccan''."],"explanationHi":"अकबर ने 1601 में इस अजेय किले पर कब्ज़ा किया था, जिसे उसकी अंतिम सैन्य विजय माना जाता है। उत्तर भारत से दक्षिण जाने के लिए इसी किले को पार करना पड़ता था।","explanationEn":"Akbar captured this impregnable fort in 1601, considered his last military conquest. One had to cross this fort to travel from North to South India.","memoryTip":"असीरगढ़ का ''बुरका'' (बुरहानपुर) पहनकर दक्षिण जाते हैं।","memoryTipEn":"Asirgarh is Burhanpur''s barrier.","related":["Gateway to South India","Akbar''s Conquests","Tapti River"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('7Ys1vYHFAeQBNU5wkiXbY', 'General Knowledge', 'मध्य प्रदेश का पहला राष्ट्रीय उद्यान (First National Park) कौनसा है?', 'Which is the first National Park of Madhya Pradesh?', 'कान्हा किसली', 'Kanha Kisli', 97, 0, '{"facts":["इसे 1955 में राष्ट्रीय उद्यान का दर्जा दिया गया था।","यह मंडला और बालाघाट जिलों में फैला है।"],"factsEn":["It was granted the status of a National Park in 1955.","It is spread across Mandla and Balaghat districts."],"explanationHi":"यह 1973 में टाइगर प्रोजेक्ट में शामिल होने वाला मध्य प्रदेश का पहला पार्क भी है। यहाँ बारहसिंगा (Swamp deer) का संरक्षण किया जाता है।","explanationEn":"It is also the first park in MP to be included in the Tiger Project in 1973. It conserves the Barasingha (Swamp deer).","memoryTip":"एमपी के जंगलों की शुरुआत ''कान्हा'' के नाम से हुई।","memoryTipEn":"Kanha came first in MP conservation.","related":["Largest National Park of MP","Project Tiger","Bhoorsingh Mascot"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vFRzpj2Tso_8ZIbfBceSw', 'General Knowledge', 'मध्य प्रदेश में ''सफेद बाघ'' (White Tigers) सबसे पहले कहाँ पाए गए थे?', 'Where were ''White Tigers'' first found in Madhya Pradesh?', 'रीवा', 'Rewa', 95, 0, '{"facts":["पहला सफेद बाघ 1951 में रीवा के महाराजा मार्तंड सिंह द्वारा पकड़ा गया था।","उस सफेद बाघ का नाम ''मोहन'' (Mohan) रखा गया था।"],"factsEn":["The first white tiger was captured in 1951 by Maharaja Martand Singh of Rewa.","That white tiger was named ''Mohan''."],"explanationHi":"रीवा को सफेद बाघों की भूमि (Land of White Tigers) कहा जाता है। दुनिया की पहली व्हाइट टाइगर सफारी भी यहीं के मुकुंदपुर में शुरू की गई है।","explanationEn":"Rewa is called the Land of White Tigers. The world''s first White Tiger Safari was also started here in Mukundpur.","memoryTip":"''मोहन'' नाम का सफेद बाघ ''रीवा'' के जंगलों में मिला।","memoryTipEn":"Rewa raised the white tigers.","related":["Maharaja Martand Singh","Mukundpur Safari","Bandhavgarh (Nearby Park)"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('uiJ7rObA0Tgw9Nix5ek2C', 'General Knowledge', '''मध्य प्रदेश वित्त निगम'' (MP Financial Corporation) का मुख्यालय कहाँ स्थित है?', 'Where is the headquarters of ''MP Financial Corporation'' (MPFC) located?', 'इंदौर', 'Indore', 91, 0, '{"facts":["इसकी स्थापना 1955 में की गई थी।","इसका उद्देश्य राज्य में उद्योगों की स्थापना के लिए वित्तीय सहायता (Loan) प्रदान करना है।"],"factsEn":["It was established in 1955.","Its objective is to provide financial assistance (loans) for the establishment of industries in the state."],"explanationHi":"चूंकि इंदौर मध्य प्रदेश की आर्थिक और वाणिज्यिक राजधानी है, इसलिए वित्त (Finance) और व्यापार से संबंधित अधिकांश प्रमुख मुख्यालय यहीं स्थित हैं।","explanationEn":"Since Indore is the economic and commercial capital of MP, most major headquarters related to finance and trade are located here.","memoryTip":"वित्त (पैसा) का सारा काम ''मिनी मुंबई'' (इंदौर) में होता है।","memoryTipEn":"Indore handles the state''s finances.","related":["Commercial Capital of MP","MP Audyogik Vikas Nigam","Economy of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZJpctAGkOQXFprYnv2XIl', 'General Knowledge', 'मध्य प्रदेश की ''पहली नदी घाटी परियोजना'' कौनसी थी?', 'Which was the ''first river valley project'' of Madhya Pradesh?', 'चंबल घाटी परियोजना', 'Chambal Valley Project', 94, 0, '{"facts":["यह परियोजना 1953-54 में शुरू की गई थी।","यह मध्य प्रदेश और राजस्थान की एक संयुक्त (Joint) परियोजना है।"],"factsEn":["This project was launched in 1953-54.","It is a joint project of Madhya Pradesh and Rajasthan."],"explanationHi":"इस परियोजना के तहत चंबल नदी पर तीन प्रमुख बांध बनाए गए: गांधी सागर (MP), राणा प्रताप सागर (राजस्थान) और जवाहर सागर (राजस्थान)।","explanationEn":"Under this project, three major dams were built on the Chambal River: Gandhi Sagar (MP), Rana Pratap Sagar (Rajasthan), and Jawahar Sagar (Rajasthan).","memoryTip":"एमपी ने सबसे पहले ''चंबल'' की घाटी को बांधा।","memoryTipEn":"Chambal channeled the first project.","related":["Gandhi Sagar Dam","Narmada Valley Project","Multipurpose Projects"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('f2nOKhNYZZC6LQwCYbn0N', 'General Knowledge', 'मध्य प्रदेश के किस जिले में ''हीरा'' (Diamond) का सर्वाधिक उत्पादन होता है?', 'Which district of Madhya Pradesh produces the highest amount of ''Diamonds''?', 'पन्ना', 'Panna', 98, 0, '{"facts":["मध्य प्रदेश भारत का एकमात्र हीरा उत्पादक राज्य है।","यहाँ हीरे का उत्खनन ''राष्ट्रीय खनिज विकास निगम'' (NMDC) करता है।"],"factsEn":["Madhya Pradesh is the only diamond-producing state in India.","Diamond mining here is carried out by the ''National Mineral Development Corporation'' (NMDC)."],"explanationHi":"पन्ना जिले की मझगवां (Majhgawan) और हिनौता खदानें हीरे के लिए विश्व प्रसिद्ध हैं। इसी कारण पन्ना को ''डायमंड सिटी'' कहा जाता है।","explanationEn":"The Majhgawan and Hinota mines of Panna district are world-famous for diamonds. For this reason, Panna is called the ''Diamond City''.","memoryTip":"पन्ना एक ''रत्न'' है जहाँ ''हीरे'' निकलते हैं।","memoryTipEn":"Panna possesses pure diamonds.","related":["NMDC","Majhgawan Mine","Minerals of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BmtI6Nj9yUOaBza8BySe1', 'General Knowledge', 'मध्य प्रदेश का ''मैन्चेस्टर'' (Manchester) किसे कहा जाता है?', 'Which city is known as the ''Manchester'' of Madhya Pradesh?', 'इंदौर', 'Indore', 95, 0, '{"facts":["ब्रिटेन का मैनचेस्टर शहर अपने सूती वस्त्र उद्योग (Cotton Textile Industry) के लिए प्रसिद्ध था।","भारत का मैनचेस्टर ''अहमदाबाद'' को कहा जाता है।"],"factsEn":["The city of Manchester in Britain was famous for its Cotton Textile Industry.","The Manchester of India is ''Ahmedabad''."],"explanationHi":"इंदौर को मध्य प्रदेश का मैनचेस्टर इसलिए कहा जाता है क्योंकि यह राज्य का सबसे बड़ा कपड़ा और वस्त्र उत्पादक केंद्र है, जिसकी स्थापना होल्कर काल में हुई थी।","explanationEn":"Indore is called the Manchester of MP because it is the state''s largest textile and garment producing center, established during the Holkar era.","memoryTip":"इंदौर में कपड़ों (टेक्सटाइल) का काम ''इन'' (अंदर) और आउट सब जगह है।","memoryTipEn":"Indore weaves the textiles of MP.","related":["Textile Industry","Mini Mumbai","Holkar Dynasty"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('HZsAQDizUqqx9FHQ2V7Ow', 'General Knowledge', 'भारतीय वन प्रबंधन संस्थान (IIFM) मध्य प्रदेश में कहाँ स्थित है?', 'Where is the Indian Institute of Forest Management (IIFM) located in Madhya Pradesh?', 'भोपाल', 'Bhopal', 93, 0, '{"facts":["IIFM की स्थापना 1982 में पर्यावरण, वन और जलवायु परिवर्तन मंत्रालय द्वारा की गई थी।","यह वन प्रबंधन में अनुसंधान और शिक्षा के लिए एशिया का अपनी तरह का पहला संस्थान है।"],"factsEn":["IIFM was established in 1982 by the Ministry of Environment, Forest and Climate Change.","It is the first institute of its kind in Asia for research and education in forest management."],"explanationHi":"इसकी इमारत का डिज़ाइन भी प्रसिद्ध वास्तुकार ''अनंत राजे'' ने (चार्ल्स कोरिया से प्रेरित होकर) बनाया था। यह झीलों के शहर में प्रकृति के बीच स्थित है।","explanationEn":"Its building was also designed by the famous architect ''Anant Raje'' (inspired by Charles Correa). It is situated amidst nature in the city of lakes.","memoryTip":"वन (जंगल) का मैनेजमेंट भोपाल की राजधानी से होता है।","memoryTipEn":"Bhopal manages the forests.","related":["Forestry in India","Environment Ministry","Education in MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UFxl_7MMg5PJgBDpVULhM', 'General Knowledge', 'मध्य प्रदेश की ''संस्कार राजधानी'' किसे कहा जाता है?', 'Which city is called the ''Cultural/Sanskar Capital'' of Madhya Pradesh?', 'जबलपुर', 'Jabalpur', 92, 0, '{"facts":["यह उपनाम प्रख्यात सामाजिक कार्यकर्ता ''आचार्य विनोबा भावे'' (Acharya Vinoba Bhave) ने दिया था।","यहाँ नर्मदा नदी पर प्रसिद्ध भेड़ाघाट स्थित है।"],"factsEn":["This nickname was given by the eminent social worker ''Acharya Vinoba Bhave''.","The famous Bhedaghat on the Narmada River is located here."],"explanationHi":"जबलपुर का सांस्कृतिक, ऐतिहासिक और साहित्यिक महत्व बहुत अधिक है, जिसने कई महान लेखकों और कलाकारों को प्रेरित किया है।","explanationEn":"Jabalpur holds immense cultural, historical, and literary significance, having inspired many great writers and artists.","memoryTip":"जबलपुर के लोगों में ''बल'' के साथ-साथ ''संस्कार'' भी हैं।","memoryTipEn":"Jabalpur judges the state''s sanskar.","related":["Vinoba Bhave","High Court of MP","Cultural Centers"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Fem45pGDKvcL9WUKmETmu', 'General Knowledge', 'मध्य प्रदेश का ''पहला ताप विद्युत केंद्र'' (First Thermal Power Plant) कौनसा है?', 'Which is the ''first Thermal Power Plant'' of Madhya Pradesh?', 'चांदनी ताप विद्युत केंद्र (नेपानगर)', 'Chandni Thermal Power Station (Nepanagar)', 94, 0, '{"facts":["इसकी स्थापना 1953 में बुरहानपुर जिले में की गई थी।","इसका मुख्य उद्देश्य ''नेशनल न्यूजप्रिंट एंड पेपर मिल्स'' (नेपानगर) को बिजली की आपूर्ति करना था।"],"factsEn":["It was established in 1953 in the Burhanpur district.","Its primary objective was to supply electricity to the ''National Newsprint and Paper Mills'' (Nepanagar)."],"explanationHi":"यह कोयले पर आधारित (Coal-based) प्लांट था, जिसने नवगठित राज्य के औद्योगिक विकास की शुरुआत की।","explanationEn":"It was a coal-based plant that kick-started the industrial development of the newly formed state.","memoryTip":"अंधेरे में सबसे पहले ''चांदनी'' (बिजली) नेपानगर में आई।","memoryTipEn":"Chandni brought the first spark.","related":["Nepanagar Paper Mill","Burhanpur","Thermal Power in MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('t9UyWJib8yRPGWRvAIza_', 'General Knowledge', 'मध्य प्रदेश में ''सांची बौद्ध एवं भारतीय ज्ञान अध्ययन विश्वविद्यालय'' कहाँ स्थित है?', 'Where is the ''Sanchi University of Buddhist-Indic Studies'' located in Madhya Pradesh?', 'सांची (रायसेन)', 'Sanchi (Raisen)', 90, 0, '{"facts":["इसकी आधारशिला 2012 में श्रीलंका के तत्कालीन राष्ट्रपति महिंदा राजपक्षे ने रखी थी।","यह रायसेन जिले के सांची शहर में स्थित है।"],"factsEn":["Its foundation stone was laid in 2012 by the then President of Sri Lanka, Mahinda Rajapaksa.","It is located in the town of Sanchi in Raisen district."],"explanationHi":"यह विश्वविद्यालय बौद्ध धर्म, दर्शन और प्राचीन भारतीय ज्ञान प्रणालियों के अध्ययन को बढ़ावा देने के लिए स्थापित किया गया है।","explanationEn":"This university is established to promote the study of Buddhism, philosophy, and ancient Indian knowledge systems.","memoryTip":"बुद्ध का ज्ञान सांची के स्तूपों में है, वहीं यूनिवर्सिटी बनी।","memoryTipEn":"Sanchi studies the Buddhist way.","related":["Sanchi Stupa","Buddhism","Raisen District"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('VKjYVNhL-kALzCsWOlhzy', 'General Knowledge', 'मध्य प्रदेश के किस स्थान को ''नृत्य के तीर्थ'' (Pilgrimage of Dance) के रूप में जाना जाता है?', 'Which place in Madhya Pradesh is known as the ''Pilgrimage of Dance''?', 'खजुराहो', 'Khajuraho', 95, 0, '{"facts":["यहाँ प्रतिवर्ष ''खजुराहो नृत्य समारोह'' (Khajuraho Dance Festival) आयोजित किया जाता है।","यह भारत का सबसे बड़ा शास्त्रीय नृत्य उत्सव है।"],"factsEn":["The ''Khajuraho Dance Festival'' is held here annually.","It is the largest classical dance festival in India."],"explanationHi":"छतरपुर जिले में स्थित चंदेल राजाओं द्वारा निर्मित इन भव्य मंदिरों की पृष्ठभूमि में कथक, ओडिसी, भरतनाट्यम आदि नृत्यों की प्रस्तुति इसे एक तीर्थ बना देती है।","explanationEn":"Located in Chhatarpur district, the performance of dances like Kathak, Odissi, Bharatanatyam against the backdrop of these grand temples built by Chandela kings makes it a pilgrimage.","memoryTip":"नृत्य करने वाले खजुराहो के मंदिरों में ''तीर्थ'' करने जाते हैं।","memoryTipEn":"Khajuraho is the holy ground for dancers.","related":["Khajuraho Dance Festival","Chandela Dynasty","Chhatarpur"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kCcjnhR2M1VbdXBU2jnvy', 'General Knowledge', 'मध्य प्रदेश में ''तांबे'' (Copper) की सबसे बड़ी खदान कहाँ स्थित है?', 'Where is the largest ''Copper'' mine located in Madhya Pradesh?', 'मलाजखंड (बालाघाट)', 'Malajkhand (Balaghat)', 96, 0, '{"facts":["मलाजखंड एशिया की सबसे बड़ी ओपन-कास्ट (Open-cast) तांबे की खदान है।","मध्य प्रदेश भारत में तांबे का प्रमुख उत्पादक राज्य है।"],"factsEn":["Malajkhand is the largest open-cast copper mine in Asia.","Madhya Pradesh is the leading producer of copper in India."],"explanationHi":"यहाँ तांबे का निष्कर्षण ''हिंदुस्तान कॉपर लिमिटेड'' (HCL) द्वारा किया जाता है।","explanationEn":"Copper extraction here is carried out by ''Hindustan Copper Limited'' (HCL).","memoryTip":"तांबे से ''माल'' (मलाजखंड) बहुत मिलता है।","memoryTipEn":"Malajkhand makes copper.","related":["Balaghat District","Hindustan Copper Limited","Minerals of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0cj-hLWO5wWLmsiRbf-DI', 'General Knowledge', 'मध्य प्रदेश में ''मैंगनीज'' की सबसे बड़ी खदान कहाँ है?', 'Where is the largest ''Manganese'' mine in Madhya Pradesh?', 'भारवेली (बालाघाट)', 'Bharveli (Balaghat)', 94, 0, '{"facts":["भारवेली एशिया की सबसे बड़ी भूमिगत (Underground) मैंगनीज खदानों में से एक है।","बालाघाट को ''मैंगनीज सिटी'' भी कहा जाता है।"],"factsEn":["Bharveli is one of the largest underground manganese mines in Asia.","Balaghat is also called the ''Manganese City''."],"explanationHi":"यहाँ मैंगनीज का खनन ''MOIL'' (Manganese Ore India Limited) द्वारा किया जाता है। यह भारत के कुल मैंगनीज उत्पादन का एक बड़ा हिस्सा है।","explanationEn":"Manganese mining here is done by ''MOIL'' (Manganese Ore India Limited). It accounts for a large chunk of India''s total manganese production.","memoryTip":"मैंगनीज बहुत ''भारी'' (भारवेली) होता है।","memoryTipEn":"Bharveli brings the heavy manganese.","related":["Balaghat District","MOIL","Minerals of MP"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qjz-D-ROfIgLhAacywa2G', 'General Knowledge', '''जहाज महल'' मध्य प्रदेश के किस ऐतिहासिक स्थल पर स्थित है?', '''Jahaz Mahal'' is located at which historical site in Madhya Pradesh?', 'मांडू (धार)', 'Mandu (Dhar)', 97, 0, '{"facts":["जहाज महल का निर्माण 15वीं शताब्दी में सुल्तान गयासुद्दीन खिलजी (Ghiyas-ud-din Khalji) ने करवाया था।","यह महल मुंज तालाब और कपूर तालाब के बीच स्थित है।"],"factsEn":["Jahaz Mahal was built in the 15th century by Sultan Ghiyas-ud-din Khalji.","The palace is situated between the Munj Talao and Kapur Talao lakes."],"explanationHi":"दो झीलों के बीच स्थित होने के कारण यह महल पानी में तैरते हुए एक जहाज (Ship) जैसा दिखाई देता है, इसलिए इसका नाम जहाज महल पड़ा।","explanationEn":"Being situated between two lakes, the palace looks like a ship floating in the water, hence the name Jahaz Mahal.","memoryTip":"मांडू की झीलों में ''जहाज'' (महल) तैरता है।","memoryTipEn":"Mandu moors the ship palace.","related":["Mandu","Hindola Mahal","Ghiyas-ud-din Khalji"]}', 'published', 1776100384, 1776100384);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0TmtLmRwevR6L7uBVY5AO', 'MP GK', 'मध्य प्रदेश की सबसे लंबी नदी कौन सी है?', 'Which is the longest river of Madhya Pradesh?', 'नर्मदा', 'Narmada', 100, 0, '{"facts":["कुल लंबाई 1312 किमी है; मध्य प्रदेश में लंबाई 1077 किमी है।"],"factsEn":["Total length is 1312 km; length in MP is 1077 km."],"memoryTip":"नर्मदा (Narmada) = नर्व (Nerve) - म.प्र. की जीवन रेखा (Life nerve)।","memoryTipEn":"Narmada acts as the ''Nerve'' (lifeline) of MP.","explanationHi":"नर्मदा नदी अमरकंटक (अनूपपुर) से निकलती है और खंभात की खाड़ी में गिरती है। यह पश्चिम की ओर बहने वाली नदी है।","explanationEn":"Narmada originates from Amarkantak (Anuppur) and falls into the Gulf of Khambhat. It is a west-flowing river."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('owG75vI1hqnvTljKmvx6c', 'MP GK', 'खजुराहो के मंदिरों का निर्माण किस वंश के शासकों ने करवाया था?', 'Which dynasty rulers built the temples of Khajuraho?', 'चंदेल वंश', 'Chandel Dynasty', 100, 0, '{"facts":["निर्माण 950 से 1050 ई. के बीच हुआ; यह छतरपुर जिले में स्थित है।"],"factsEn":["Built between 950 and 1050 AD; Located in Chhatarpur district."],"memoryTip":"खजुराहो के मंदिर ''चाँद'' (Chandel) की रोशनी में चमकते हैं।","memoryTipEn":"Khajuraho temples shine under the ''Chand'' (Moon - Chandel).","explanationHi":"खजुराहो अपने नागर शैली की वास्तुकला और कामुक मूर्तियों के लिए यूनेस्को विश्व धरोहर स्थल है।","explanationEn":"Khajuraho is a UNESCO World Heritage site known for its Nagara style architecture and erotic sculptures."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('aByOCMo8TRdafo5Xk3Esx', 'MP GK', 'मध्य प्रदेश का राज्य पक्षी कौन सा है?', 'What is the state bird of Madhya Pradesh?', 'दूधराज (शाह बुलबुल)', 'Dhudhraj (Asian Paradise Flycatcher)', 100, 0, '{"facts":["वैज्ञानिक नाम: Terpsiphone paradisi; इसे 1981 में घोषित किया गया था।"],"factsEn":["Scientific name: Terpsiphone paradisi; Declared in 1981."],"memoryTip":"म.प्र. में ''दूध'' (Dhudhraj) की नदियां बहती हैं।","memoryTipEn":"Dhudhraj sounds like ''Doodh'' (milk), symbolizing purity of MP.","explanationHi":"यह मुख्य रूप से सरदारपुर (धार) और सैलाना (रतलाम) अभयारण्यों में पाया जाता है।","explanationEn":"It is mainly found in Sardarpur (Dhar) and Sailana (Ratlam) sanctuaries."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('CiaFEpmkMHMHOpcMsDVaY', 'MP GK', 'तानसेन का मकबरा कहाँ स्थित है?', 'Where is the tomb of Tansen located?', 'ग्वालियर', 'Gwalior', 100, 0, '{"facts":["यह म.प्र. का सबसे बड़ा मकबरा है; तानसेन अकबर के नवरत्नों में से एक थे।"],"factsEn":["It is the largest tomb in MP; Tansen was one of Akbar''s Navaratnas."],"memoryTip":"तानसेन ''ग्वाल'' (Gwalior) की तरह सुर लगाते थे।","memoryTipEn":"Tansen sang beautifully in the ''Gwalior'' Gharana.","explanationHi":"यह मकबरा 16वीं शताब्दी में मुगल वास्तुकला शैली में बनाया गया था।","explanationEn":"The tomb was built in the 16th century in Mughal architectural style."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oTcCdZLOp5Ak1R0hCt7YO', 'MP GK', 'मध्य प्रदेश का प्रथम मुख्यमंत्री कौन था?', 'Who was the first Chief Minister of Madhya Pradesh?', 'पं. रविशंकर शुक्ल', 'Pt. Ravishankar Shukla', 100, 0, '{"facts":["कार्यकाल: 1 नवंबर 1956 से 31 दिसंबर 1956; प्रथम राज्यपाल पट्टाभि सीतारमैया थे।"],"factsEn":["Tenure: 1 Nov 1956 to 31 Dec 1956; First Governor was Pattabhi Sitaramayya."],"memoryTip":"म.प्र. की शुरुआत ''रवि'' (सूर्य) की चमक से हुई।","memoryTipEn":"MP''s dawn started with ''Ravi'' (Sun).","explanationHi":"मध्य प्रदेश के गठन (1956) के बाद इन्होंने प्रथम मुख्यमंत्री के रूप में शपथ ली थी।","explanationEn":"He took oath as the first CM after the formation of Madhya Pradesh in 1956."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('iNzhEO55TdneiQ7ej8iL9', 'MP GK', 'कान्हा किसली राष्ट्रीय उद्यान किस जिले में है?', 'In which district is Kanha Kisli National Park located?', 'मंडला (और बालाघाट)', 'Mandla (and Balaghat)', 100, 0, '{"facts":["म.प्र. का सबसे बड़ा राष्ट्रीय उद्यान; 1955 में स्थापित।"],"factsEn":["Largest National Park of MP; Established in 1955."],"memoryTip":"कान्हा जी का ''मन डोल'' (मंडला) गया।","memoryTipEn":"Kanha''s (Lord Krishna''s) ''Man'' (mind) is in ''Mandla''.","explanationHi":"यह उद्यान भूरसिंह द बारहसिंघा (शुभंकर) और प्रोजेक्ट टाइगर (1974) के लिए प्रसिद्ध है।","explanationEn":"This park is famous for Bhoorsingh the Barasingha (mascot) and Project Tiger (1974)."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NP4iznGOdj_4DaD8KtrJx', 'MP GK', 'भीमबेटका की गुफाएं किस लिए प्रसिद्ध हैं?', 'What are the Bhimbetka caves famous for?', 'शैलचित्र (Rock Paintings)', 'Rock Paintings', 100, 0, '{"facts":["रायसेन जिले में स्थित; वी.एस. वाकणकर ने 1957 में खोज की।"],"factsEn":["Located in Raisen district; Discovered by V.S. Wakankar in 1957."],"memoryTip":"भीम (महाभारत) ने चट्टानों पर ''चित्र'' बनाए।","memoryTipEn":"Bhim (Mahabharata) drew paintings on the rocks.","explanationHi":"ये पुरापाषाण काल से संबंधित हैं और 2003 में यूनेस्को विश्व धरोहर स्थल घोषित किए गए।","explanationEn":"They belong to the Paleolithic era and were declared a UNESCO World Heritage site in 2003."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QPWbwkcdBf2ABN7l4utm9', 'MP GK', 'सांची का स्तूप किसने बनवाया था?', 'Who built the Sanchi Stupa?', 'सम्राट अशोक', 'Emperor Ashoka', 100, 0, '{"facts":["रायसेन जिले में है; 1989 में यूनेस्को में शामिल।"],"factsEn":["Located in Raisen district; Included in UNESCO in 1989."],"memoryTip":"सांची में ''शोक'' (अशोक) नहीं है।","memoryTipEn":"There is no ''Shok'' (sorrow) in Sanchi (Ashoka).","explanationHi":"सांची बौद्ध धर्म का एक प्रमुख केंद्र है, जहाँ बुद्ध के शिष्यों की अस्थियां रखी हैं।","explanationEn":"Sanchi is a major center of Buddhism, housing the relics of Buddha''s disciples."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('EakwJixl6v2KPus7wVOgW', 'MP GK', 'मध्य प्रदेश का हीरा उत्पादक जिला कौन सा है?', 'Which is the diamond producing district of Madhya Pradesh?', 'पन्ना', 'Panna', 100, 0, '{"facts":["मझगवां खदान हीरे के लिए प्रसिद्ध है; भारत में म.प्र. का प्रथम स्थान है।"],"factsEn":["Majhgawan mine is famous for diamonds; MP ranks first in India."],"memoryTip":"हीरा एक कीमती ''पन्ना'' (Page/Gem) है।","memoryTipEn":"A diamond is a precious ''Panna'' (gem).","explanationHi":"पन्ना जिले में विंध्य क्रम की चट्टानों में हीरे पाए जाते हैं।","explanationEn":"Diamonds are found in the Vindhyan rock system in the Panna district."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('onWFdPuWwrSwvGbfUwCky', 'MP GK', 'कर्क रेखा मध्य प्रदेश के कितने जिलों से होकर गुजरती है?', 'Tropic of Cancer passes through how many districts of Madhya Pradesh?', '14', '14', 100, 0, '{"facts":["यह म.प्र. को लगभग दो बराबर भागों में बांटती है; रतलाम, उज्जैन, भोपाल आदि शामिल हैं।"],"factsEn":["It divides MP into almost two equal halves; includes Ratlam, Ujjain, Bhopal, etc."],"memoryTip":"कर्क रेखा ''14'' (चौदह) चांद लगाती है।","memoryTipEn":"The Tropic of Cancer is like ''14'' stars for MP.","explanationHi":"मालवा के पठार के बीचों-बीच से गुजरती है और नर्मदा नदी के समानांतर है।","explanationEn":"It passes through the middle of Malwa plateau and is parallel to the Narmada river."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vVKiAsgoKmilFI9GyIyeQ', 'History', 'प्लासी का युद्ध कब लड़ा गया था?', 'When was the Battle of Plassey fought?', '1757', '1757', 100, 0, '{"facts":["रॉबर्ट क्लाइव और सिराजुद्दौला के बीच; अंग्रेजों की जीत हुई।"],"factsEn":["Between Robert Clive and Siraj-ud-Daulah; British won."],"memoryTip":"1757 - प्लासी (P-57), 1857 - क्रांति।","memoryTipEn":"1757 Plassey sets the base for 1857 Mutiny.","explanationHi":"इस युद्ध ने भारत में ब्रिटिश साम्राज्य की नींव रखी, जो मीर जाफर के धोखे के कारण जीता गया।","explanationEn":"This battle laid the foundation of the British Empire in India, won due to Mir Jafar''s betrayal."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dXUMwS5lVvpwhfLArnLW3', 'History', 'मौर्य वंश का संस्थापक कौन था?', 'Who was the founder of the Maurya Dynasty?', 'चंद्रगुप्त मौर्य', 'Chandragupta Maurya', 100, 0, '{"facts":["चाणक्य की सहायता से नंद वंश (धनानंद) को हराया; राजधानी पाटलिपुत्र।"],"factsEn":["Defeated Nanda dynasty (Dhana Nanda) with Chanakya''s help; Capital Pataliputra."],"memoryTip":"चाँद (चंद्र) सबसे ऊपर होता है (संस्थापक)।","memoryTipEn":"''Chand'' (Moon) shines the brightest at the start.","explanationHi":"चंद्रगुप्त मौर्य ने 322 ईसा पूर्व में मौर्य साम्राज्य की स्थापना की थी।","explanationEn":"Chandragupta Maurya established the Mauryan Empire in 322 BCE."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('vlZEdXy1Ajfra3YwPuh5S', 'History', 'भारत छोड़ो आंदोलन किस वर्ष शुरू हुआ था?', 'In which year did the Quit India Movement start?', '1942', '1942', 100, 0, '{"facts":["8 अगस्त 1942 को बॉम्बे से; गांधीजी ने ''करो या मरो'' का नारा दिया।"],"factsEn":["From Bombay on 8 Aug 1942; Gandhiji gave ''Do or Die'' slogan."],"memoryTip":"42 (Four-Two) = For You (अंग्रेजों तुम्हारे लिए भारत छोड़ो)।","memoryTipEn":"42 -> Leave for (4) to (2) Britain.","explanationHi":"क्रिप्स मिशन की विफलता के बाद यह एक जन आंदोलन के रूप में उभरा।","explanationEn":"It emerged as a mass movement following the failure of the Cripps Mission."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('R4m09kXdG4_lhIoGmySop', 'History', 'पानीपत का प्रथम युद्ध किसके बीच हुआ था?', 'Between whom was the First Battle of Panipat fought?', 'बाबर और इब्राहिम लोदी', 'Babur and Ibrahim Lodi', 100, 0, '{"facts":["1526 ई. में; इस युद्ध से भारत में मुगल साम्राज्य की स्थापना हुई।"],"factsEn":["In 1526 AD; This battle established the Mughal Empire in India."],"memoryTip":"बाबर ने इब्राहिम को ''पानी'' (Panipat) पिलाया।","memoryTipEn":"Babur made Lodi drink ''Pani'' (water).","explanationHi":"बाबर ने इस युद्ध में पहली बार तोपखाने और ''तुगलमा'' युद्ध नीति का प्रयोग किया।","explanationEn":"Babur used artillery and ''Tulughma'' warfare strategy for the first time in this battle."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('l1xYpG9W-njnJWaCEKQKF', 'History', 'आर्य समाज की स्थापना किसने की थी?', 'Who founded the Arya Samaj?', 'स्वामी दयानंद सरस्वती', 'Swami Dayanand Saraswati', 100, 0, '{"facts":["1875 में बॉम्बे में स्थापना; नारा: ''वेदों की ओर लौटो''।"],"factsEn":["Founded in Bombay in 1875; Slogan: ''Go back to Vedas''."],"memoryTip":"आर्य हमेशा ''दया'' (दयानंद) करते हैं।","memoryTipEn":"Aryans show ''Daya'' (mercy/Dayanand).","explanationHi":"आर्य समाज ने हिंदू धर्म में मूर्ति पूजा और जाति व्यवस्था जैसी कुरीतियों का विरोध किया।","explanationEn":"Arya Samaj opposed evils like idol worship and the caste system in Hinduism."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('oRDyCvpd3tZqTMkyx4ETL', 'History', 'दीन-ए-इलाही धर्म की स्थापना किसने की?', 'Who founded the Din-i-Ilahi religion?', 'अकबर', 'Akbar', 100, 0, '{"facts":["1582 ई. में स्थापित; बीरबल इसे स्वीकार करने वाले एकमात्र हिंदू थे।"],"factsEn":["Established in 1582 AD; Birbal was the only Hindu to accept it."],"memoryTip":"दीन दुखियों पर ''अकबर'' रहम करता था।","memoryTipEn":"Akbar created ''Din'' (religion) for all.","explanationHi":"यह सभी धर्मों की अच्छी बातों का एक मिश्रण था, जिसका उद्देश्य धार्मिक सहिष्णुता बढ़ाना था।","explanationEn":"It was a syncretic religion intended to merge the best elements of all religions to promote tolerance."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('x-h-3zle4v0VeAdmOSnZ2', 'History', 'आजाद हिंद फौज (INA) की स्थापना किसने की?', 'Who founded the Azad Hind Fauj (INA)?', 'रासबिहारी बोस (बाद में सुभाष चंद्र बोस)', 'Rash Behari Bose (Later Subhas Chandra Bose)', 100, 0, '{"facts":["1942 में जापान में गठन; सुभाष चंद्र बोस ने 1943 में कमान संभाली।"],"factsEn":["Formed in Japan in 1942; Subhas Chandra Bose took command in 1943."],"memoryTip":"आजादी का ''रास'' (रासबिहारी) और ''बोस'' (सुभाष) दोनों ने चखा।","memoryTipEn":"The ''Bose'' brothers/namesakes led the INA.","explanationHi":"INA का उद्देश्य ब्रिटिश शासन से भारत को सशस्त्र संघर्ष के माध्यम से मुक्त कराना था।","explanationEn":"The goal of INA was to secure Indian independence from British rule via armed struggle."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('27GcBBlduq8RDzZoqgxLA', 'History', 'जलियांवाला बाग हत्याकांड कब हुआ था?', 'When did the Jallianwala Bagh massacre take place?', '13 अप्रैल 1919', '13 April 1919', 100, 0, '{"facts":["अमृतसर (पंजाब) में बैसाखी के दिन; जनरल डायर ने गोलियां चलवाईं।"],"factsEn":["On Baisakhi day in Amritsar (Punjab); General Dyer ordered the firing."],"memoryTip":"19-19 (एक-नौ, एक-नौ) गोलियां चलीं।","memoryTipEn":"19-19 repeating shots were fired.","explanationHi":"लोग रॉलेट एक्ट के तहत डॉ. सत्यपाल और सैफुद्दीन किचलू की गिरफ्तारी का शांतिपूर्ण विरोध कर रहे थे।","explanationEn":"People were peacefully protesting the arrest of Dr. Satyapal and Saifuddin Kitchlew under the Rowlatt Act."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('IwsNpNjvhRMEWzwGwUpnI', 'History', 'हड़प्पा सभ्यता की खोज किसने की थी?', 'Who discovered the Harappan civilization?', 'दयाराम साहनी', 'Dayaram Sahni', 100, 0, '{"facts":["1921 में रावी नदी के तट पर; यह एक कांस्य युगीन सभ्यता थी।"],"factsEn":["In 1921 on the banks of Ravi river; It was a Bronze Age civilization."],"memoryTip":"हड़प्पा को खोजने में ''दया'' (Dayaram) आ गई।","memoryTipEn":"Have ''Daya'' (mercy) while digging Harappa.","explanationHi":"हड़प्पा सिंधु घाटी सभ्यता का खोजा गया पहला स्थल था, जो अपनी शहरी योजना के लिए प्रसिद्ध है।","explanationEn":"Harappa was the first site discovered in the Indus Valley Civilization, famous for its urban planning."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('afxE1OwPPSBVoNKnugBMh', 'History', 'गांधी-इरविन समझौता कब हुआ था?', 'When was the Gandhi-Irwin Pact signed?', '1931', '1931', 100, 0, '{"facts":["5 मार्च 1931; सविनय अवज्ञा आंदोलन को स्थगित किया गया।"],"factsEn":["5 March 1931; Civil Disobedience Movement was suspended."],"memoryTip":"31 (तीन-एक) - गांधीजी और इरविन एक साथ बैठे।","memoryTipEn":"31 - 3 words: Gandhi Irwin Pact.","explanationHi":"इस समझौते के बाद कांग्रेस द्वितीय गोलमेज सम्मेलन में भाग लेने के लिए सहमत हुई।","explanationEn":"Following this pact, Congress agreed to participate in the Second Round Table Conference."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('57dAJpzqsPIUUDfaN1Qfj', 'Geography', 'भारत की सबसे ऊँची चोटी कौन सी है?', 'Which is the highest peak in India?', 'कंचनजंगा (K2 के बाद निर्विवाद)', 'Kangchenjunga (undisputed after K2)', 100, 0, '{"facts":["सिक्किम में स्थित है; ऊँचाई 8586 मीटर है।"],"factsEn":["Located in Sikkim; Height is 8586 meters."],"memoryTip":"चोटी सोने (कंचन) जैसी चमकती है।","memoryTipEn":"Peak shines like gold (Kanchan).","explanationHi":"K2 (गॉडविन ऑस्टिन) भारत की सबसे ऊँची चोटी है, लेकिन यह PoK में है, इसलिए कंचनजंगा पूर्णतः भारत में है।","explanationEn":"K2 is the highest, but lies in PoK. Kangchenjunga is the highest peak entirely within undisputed Indian territory."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('cBBjhCvC0UviIadTgJZmz', 'Geography', 'भारत की सबसे बड़ी मीठे पानी की झील कौन सी है?', 'Which is the largest freshwater lake in India?', 'वुलर झील', 'Wular Lake', 100, 0, '{"facts":["जम्मू-कश्मीर में स्थित; झेलम नदी द्वारा पोषित।"],"factsEn":["Located in Jammu & Kashmir; Fed by Jhelum river."],"memoryTip":"मीठा पानी पीने के लिए ''वुलर'' (कूलर) का उपयोग करें।","memoryTipEn":"Drink fresh water from a ''Wular'' (Cooler).","explanationHi":"यह विवर्तनिक (tectonic) गतिविधि के परिणामस्वरूप बनी है और एशिया की सबसे बड़ी मीठे पानी की झीलों में से एक है।","explanationEn":"It was formed as a result of tectonic activity and is one of the largest freshwater lakes in Asia."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('G0A8ydrDhC3_piSb0KmUD', 'Geography', 'सूर्य के सबसे निकट का ग्रह कौन सा है?', 'Which planet is closest to the Sun?', 'बुध (Mercury)', 'Mercury', 100, 0, '{"facts":["यह सौरमंडल का सबसे छोटा ग्रह है; इसका कोई उपग्रह नहीं है।"],"factsEn":["It is the smallest planet in the solar system; Has no moons."],"memoryTip":"सूर्य के पास ''बुद्धि'' (बुध) वाला ही जा सकता है।","memoryTipEn":"Mercury thermometer checks Sun''s temperature.","explanationHi":"बुध सबसे तेज गति से सूर्य की परिक्रमा (88 दिन) पूरी करता है।","explanationEn":"Mercury completes its revolution around the Sun the fastest (88 days)."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5Rvq6anfH-j2qwIrL8bfQ', 'Geography', 'पृथ्वी को ''नीला ग्रह'' क्यों कहा जाता है?', 'Why is Earth called the ''Blue Planet''?', 'जल की उपस्थिति के कारण', 'Due to presence of water', 100, 0, '{"facts":["पृथ्वी का लगभग 71% हिस्सा पानी से ढका है; अंतरिक्ष से नीली दिखती है।"],"factsEn":["About 71% of Earth is covered by water; Looks blue from space."],"memoryTip":"पानी का रंग नीला होता है।","memoryTipEn":"Water reflects blue skies.","explanationHi":"महासागरों में पानी की विशाल मात्रा प्रकाश को परावर्तित करती है, जिससे अंतरिक्ष से पृथ्वी नीली दिखाई देती है।","explanationEn":"The vast amount of water in the oceans reflects light, making Earth appear blue from space."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('jL0o0OVtDvz1a5m2ue_0o', 'Geography', 'विश्व का सबसे बड़ा नदी द्वीप कौन सा है?', 'Which is the world''s largest river island?', 'माजुली', 'Majuli', 100, 0, '{"facts":["असम में ब्रह्मपुत्र नदी पर स्थित; यह भारत का पहला द्वीप जिला है।"],"factsEn":["Located on Brahmaputra river in Assam; First island district of India."],"memoryTip":"''माजुली'' (माँ-जुली) नदी के बीच में है।","memoryTipEn":"''Majuli'' flows merrily in Brahmaputra.","explanationHi":"माजुली द्वीप लगातार ब्रह्मपुत्र नदी के कटाव का सामना कर रहा है, जिससे इसका आकार घट रहा है।","explanationEn":"Majuli island is constantly facing erosion from the Brahmaputra river, reducing its size."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WJ6ZzBnEf67zXEw4aEOJt', 'Geography', 'भारत की सबसे लंबी नदी कौन सी है?', 'Which is the longest river in India?', 'गंगा', 'Ganga', 100, 0, '{"facts":["लंबाई: 2525 किमी; गंगोत्री ग्लेशियर (उत्तराखंड) से निकलती है।"],"factsEn":["Length: 2525 km; Originates from Gangotri glacier (Uttarakhand)."],"memoryTip":"गंगा (2525) - ''पच्चीस पच्चीस'' का बहता नीर।","memoryTipEn":"Ganga''s length is nicely paired: 25-25.","explanationHi":"भागीरथी और अलकनंदा के देवप्रयाग में मिलने के बाद इसे गंगा के नाम से जाना जाता है।","explanationEn":"It is known as Ganga after the confluence of Bhagirathi and Alaknanda at Devprayag."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SjucJMzVCzVKa99cJgcNq', 'Geography', 'गिर राष्ट्रीय उद्यान किसके लिए प्रसिद्ध है?', 'What is Gir National Park famous for?', 'एशियाई शेर', 'Asiatic Lions', 100, 0, '{"facts":["गुजरात में स्थित है; विश्व में एशियाई शेरों का एकमात्र प्राकृतिक आवास।"],"factsEn":["Located in Gujarat; Only natural habitat of Asiatic lions in the world."],"memoryTip":"शेर को देखकर लोग ''गिर'' (Gir) जाते हैं।","memoryTipEn":"Lions make you ''Gir'' (fall) out of fear.","explanationHi":"संरक्षण प्रयासों के कारण गिर वन में एशियाई शेरों की आबादी में वृद्धि हुई है।","explanationEn":"Due to conservation efforts, the population of Asiatic lions in Gir forest has increased."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wnT6mbE_N9GJRTYAYk28l', 'Geography', 'भारत की मानक समय रेखा (IST) क्या है?', 'What is the Indian Standard Time (IST) meridian?', '82.5° पूर्वी देशांतर', '82.5° East Longitude', 100, 0, '{"facts":["यह मिर्जापुर (प्रयागराज, यूपी) से होकर गुजरती है; यह GMT से 5.5 घंटे आगे है।"],"factsEn":["Passes through Mirzapur (Prayagraj, UP); It is 5.5 hours ahead of GMT."],"memoryTip":"82.5 (साढ़े बयासी) - यूपी से समय मिलासी।","memoryTipEn":"82.5 E determines India''s clock.","explanationHi":"भारत के विस्तृत देशांतरीय विस्तार के कारण पूरे देश के लिए एक समान समय बनाए रखने के लिए इसे चुना गया।","explanationEn":"Due to India''s vast longitudinal extent, this was chosen to maintain uniform time across the country."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3l55r2bUq1R1iyFXDJ7H7', 'Geography', 'भारत का सबसे ऊँचा जलप्रपात (सीधा गिरने वाला) कौन सा है?', 'Which is the highest direct-plunge waterfall in India?', 'जोग या गरसोप्पा', 'Jog or Gersoppa', 100, 0, '{"facts":["कर्नाटक में शरावती नदी पर स्थित है। (कुंचिकल कुल ऊंचाई में सबसे बड़ा है)"],"factsEn":["Located on Sharavati river in Karnataka. (Kunchikal is highest overall)."],"memoryTip":"जल ''जोग'' (Jog) कर नीचे गिरा।","memoryTipEn":"Water ''Jogs'' down the Sharavati river.","explanationHi":"जोग जलप्रपात 253 मीटर की ऊंचाई से गिरता है और इसका नाम महात्मा गांधी जलप्रपात भी रखा गया है।","explanationEn":"Jog falls drop from 253 meters and is also renamed as Mahatma Gandhi Falls."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('_6aPIG1RZOXZyszPxLwAa', 'Geography', 'स्वेज नहर किन दो सागरों को जोड़ती है?', 'Which two seas does the Suez Canal connect?', 'भूमध्य सागर और लाल सागर', 'Mediterranean Sea and Red Sea', 100, 0, '{"facts":["यह मिस्र में स्थित है; 1869 में खोली गई।"],"factsEn":["Located in Egypt; Opened in 1869."],"memoryTip":"स्वेज नहर ''भू-लाल'' (भूमध्य + लाल) है।","memoryTipEn":"Suez makes the Med see Red.","explanationHi":"यह नहर यूरोप और एशिया के बीच एक छोटा समुद्री मार्ग प्रदान करती है, जिससे अफ्रीका का चक्कर नहीं लगाना पड़ता।","explanationEn":"This canal provides a shorter maritime route between Europe and Asia, avoiding the trip around Africa."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('JaH86eC2PayH8GMaXiLps', 'General Science', 'कोशिका का पावरहाउस किसे कहा जाता है?', 'What is known as the powerhouse of the cell?', 'माइटोकॉन्ड्रिया', 'Mitochondria', 100, 0, '{"facts":["यह एटीपी (ATP) के रूप में ऊर्जा पैदा करता है; इसमें अपना DNA होता है।"],"factsEn":["It generates energy in the form of ATP; Has its own DNA."],"memoryTip":"माइटो (Mighty) = शक्तिशाली (Power)।","memoryTipEn":"Mighty Mitochondria makes Power.","explanationHi":"कोशिकीय श्वसन के दौरान माइटोकॉन्ड्रिया ग्लूकोज को तोड़कर ऊर्जा (ATP) उत्पन्न करता है।","explanationEn":"During cellular respiration, mitochondria break down glucose to produce energy (ATP)."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9f2LHEXNc4cBnBKYkw3sE', 'General Science', 'विटामिन C की कमी से कौन सा रोग होता है?', 'Which disease is caused by Vitamin C deficiency?', 'स्कर्वी', 'Scurvy', 100, 0, '{"facts":["विटामिन C का रासायनिक नाम एस्कॉर्बिक एसिड है; खट्टे फलों में पाया जाता है।"],"factsEn":["Chemical name is Ascorbic Acid; Found in citrus fruits."],"memoryTip":"C से Scurvy (सी-स्कर्वी)।","memoryTipEn":"Vitamin C -> C-curvy (Scurvy).","explanationHi":"स्कर्वी में मसूड़ों से खून आना और घावों का धीरे भरना जैसे लक्षण दिखाई देते हैं।","explanationEn":"Scurvy shows symptoms like bleeding gums and slow healing of wounds."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Cgf_o62wn3QgQdU_TYjNJ', 'General Science', 'सबसे भारी प्राकृतिक तत्व कौन सा है?', 'Which is the heaviest natural element?', 'यूरेनियम', 'Uranium', 100, 0, '{"facts":["परमाणु क्रमांक 92 है; इसका उपयोग परमाणु ऊर्जा संयंत्रों में होता है।"],"factsEn":["Atomic number is 92; Used in nuclear power plants."],"memoryTip":"Uranium का ''U'' बहुत भारी है।","memoryTipEn":"Uranium is heavily used for Uranium power.","explanationHi":"प्रकृति में पाए जाने वाले तत्वों में यूरेनियम का परमाणु द्रव्यमान सबसे अधिक होता है।","explanationEn":"Among naturally occurring elements, Uranium has the highest atomic mass."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rGcnMiNvYz8y_6_VAsKC4', 'General Science', 'निर्वात में प्रकाश की चाल कितनी होती है?', 'What is the speed of light in a vacuum?', '3 × 10⁸ m/s', '3 × 10⁸ m/s', 100, 0, '{"facts":["प्रकाश की गति सबसे पहले रोमर (Rømer) ने मापी थी।"],"factsEn":["Speed of light was first measured by Rømer."],"memoryTip":"3 के पीछे 8 जीरो (300,000 km/s)।","memoryTipEn":"3 lakh km per sec.","explanationHi":"ब्रह्मांड में प्रकाश की गति अंतिम गति सीमा मानी जाती है।","explanationEn":"The speed of light is considered the ultimate speed limit in the universe."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5iJINQWpOglR441CUDBA0', 'General Science', 'मानव रक्त का pH मान कितना होता है?', 'What is the pH value of human blood?', '7.4', '7.4', 100, 0, '{"facts":["यह हल्का क्षारीय (Basic) होता है; 7 उदासीन होता है।"],"factsEn":["It is slightly basic/alkaline; 7 is neutral."],"memoryTip":"सच्चा (7.4) खून।","memoryTipEn":"7.4 - stay alive and more.","explanationHi":"रक्त के pH में थोड़ा सा भी बदलाव गंभीर स्वास्थ्य समस्याएं पैदा कर सकता है।","explanationEn":"Even a slight change in blood pH can cause severe health issues."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PbgwNjqMbjMCRDcVSNUbT', 'General Science', 'शरीर की ''मास्टर ग्रंथि'' किसे कहते हैं?', 'Which is called the ''Master Gland'' of the body?', 'पीयूष ग्रंथि (Pituitary Gland)', 'Pituitary Gland', 100, 0, '{"facts":["मस्तिष्क के आधार पर स्थित; मटर के दाने के आकार की होती है।"],"factsEn":["Located at the base of the brain; Pea-sized."],"memoryTip":"मास्टर हमेशा ''पीता'' (Pituitary) है (दिमाग की शक्ति)।","memoryTipEn":"Master Pitu controls the class.","explanationHi":"यह अन्य अंतःस्रावी ग्रंथियों (जैसे थायराइड, एड्रिनल) के कार्यों को नियंत्रित करती है।","explanationEn":"It controls the functions of other endocrine glands (like thyroid, adrenal)."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('trnIKKVByT462a_4wmJWn', 'General Science', 'शुष्क बर्फ (Dry Ice) क्या है?', 'What is Dry Ice?', 'ठोस कार्बन डाइऑक्साइड (CO₂)', 'Solid Carbon Dioxide (CO₂)', 100, 0, '{"facts":["यह बिना तरल बने सीधे गैस में बदल जाती है (ऊर्ध्वपातन/Sublimation)।"],"factsEn":["It converts directly into gas without becoming liquid (Sublimation)."],"memoryTip":"CO2 जम गई तो ड्राई आइस।","memoryTipEn":"Solid CO2 is too dry to be wet ice.","explanationHi":"इसका उपयोग मुख्य रूप से शीतलन (cooling) और थिएटर में धुआं उत्पन्न करने के लिए किया जाता है।","explanationEn":"It is primarily used for cooling and creating fog effects in theaters."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0vh69FgojXkKalY6Db2bG', 'General Science', 'लाफिंग गैस (हंसाने वाली गैस) का रासायनिक नाम क्या है?', 'What is the chemical name of Laughing Gas?', 'नाइट्रस ऑक्साइड (N₂O)', 'Nitrous Oxide (N₂O)', 100, 0, '{"facts":["दंत चिकित्सा में इसका उपयोग एनेस्थीसिया के रूप में किया जाता है।"],"factsEn":["Used as anesthesia in dentistry."],"memoryTip":"हंसते-हंसते ''NO'' (N2O) मत कहो।","memoryTipEn":"N2O = ''NO'' crying, only laughing.","explanationHi":"इसे सूंघने पर हल्की उत्तेजना होती है, जिससे हंसी आ सकती है।","explanationEn":"Inhaling it causes slight euphoria, which can lead to laughing."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('kbxdFpx4eTErCYVUtkSgt', 'General Science', 'बल (Force) का SI मात्रक क्या है?', 'What is the SI unit of Force?', 'न्यूटन (N)', 'Newton (N)', 100, 0, '{"facts":["F = ma (द्रव्यमान × त्वरण); CGS मात्रक डाइन (Dyne) है।"],"factsEn":["F = ma (mass × acceleration); CGS unit is Dyne."],"memoryTip":"सेब गिरने का ''बल'' न्यूटन ने देखा।","memoryTipEn":"Newton forced the apple to make sense.","explanationHi":"एक न्यूटन वह बल है जो 1 किलोग्राम द्रव्यमान वाली वस्तु में 1 m/s² का त्वरण उत्पन्न करता है।","explanationEn":"One Newton is the force that produces an acceleration of 1 m/s² in a 1 kg mass."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ib-6mYatzYxIwg1ApPLMc', 'General Science', 'मलेरिया रोग किस परजीवी के कारण होता है?', 'Malaria disease is caused by which parasite?', 'प्लास्मोडियम (Plasmodium)', 'Plasmodium', 100, 0, '{"facts":["मादा एनाफिलीज मच्छर के काटने से फैलता है; तिल्ली (Spleen) को प्रभावित करता है।"],"factsEn":["Spread by female Anopheles mosquito bites; Affects the Spleen."],"memoryTip":"मच्छर ने खून ''प्लाज्मा'' (प्लास्मोडियम) में जहर मिलाया।","memoryTipEn":"Malaria infects your blood Plasma(dium).","explanationHi":"प्लास्मोडियम लाल रक्त कोशिकाओं (RBCs) को नष्ट कर देता है, जिससे बुखार और ठंड लगती है।","explanationEn":"Plasmodium destroys red blood cells (RBCs), causing fever and chills."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('wlX6Ydf3NElwZWZK8OCRw', 'Polity', 'संविधान की आत्मा किस अनुच्छेद को कहा जाता है?', 'Which Article is called the ''Soul of the Constitution''?', 'अनुच्छेद 32', 'Article 32', 100, 0, '{"facts":["संवैधानिक उपचारों का अधिकार; डॉ. बी.आर. अंबेडकर ने इसे कहा था।"],"factsEn":["Right to Constitutional Remedies; Called so by Dr. B.R. Ambedkar."],"memoryTip":"32 दांतों की तरह ये अधिकारों की रक्षा करता है।","memoryTipEn":"Article 32 is the key to all 32 teeth (rights).","explanationHi":"अनुच्छेद 32 के तहत मौलिक अधिकारों के हनन पर सीधे सर्वोच्च न्यायालय (Supreme Court) जाया जा सकता है।","explanationEn":"Under Article 32, one can approach the Supreme Court directly if Fundamental Rights are violated."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('C1J2BxxV1KowB_G0g_Pfy', 'Polity', 'मौलिक अधिकार संविधान के किस भाग में वर्णित हैं?', 'In which Part of the Constitution are Fundamental Rights described?', 'भाग 3', 'Part 3', 100, 0, '{"facts":["अनुच्छेद 12 से 35 तक; अमेरिका के संविधान से लिए गए हैं।"],"factsEn":["From Article 12 to 35; Borrowed from the US Constitution."],"memoryTip":"अधिकार (A-D-H-I-K-A-R) - 3 अक्षर का ''हक'' (भाग 3)।","memoryTipEn":"Fundamental Rights = 3 words in Hindi (Mool-A-Dhi-Kar), Part 3.","explanationHi":"भाग 3 को भारत का ''मैग्ना कार्टा'' (Magna Carta) भी कहा जाता है।","explanationEn":"Part 3 is also referred to as the ''Magna Carta'' of India."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('YZ4RI9PIbxDBP-4v6KZ6h', 'Polity', 'भारत के राष्ट्रपति बनने के लिए न्यूनतम आयु कितनी होनी चाहिए?', 'What is the minimum age required to become the President of India?', '35 वर्ष', '35 Years', 100, 0, '{"facts":["उपराष्ट्रपति और राज्यपाल के लिए भी 35 वर्ष है; लोकसभा के लिए 25 वर्ष।"],"factsEn":["35 years for VP and Governor too; 25 years for Lok Sabha."],"memoryTip":"35 की उम्र में आदमी ''देश'' संभालने लायक होता है।","memoryTipEn":"At 35, you arrive at the peak to be Prez.","explanationHi":"अनुच्छेद 58 के अनुसार, उम्मीदवार को भारत का नागरिक होना चाहिए और 35 वर्ष की आयु पूरी कर लेनी चाहिए।","explanationEn":"According to Article 58, the candidate must be an Indian citizen and have completed 35 years of age."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('qcF3QZas6BVARUI8RmpvI', 'Polity', 'भारत के प्रथम मुख्य चुनाव आयुक्त कौन थे?', 'Who was the first Chief Election Commissioner of India?', 'सुकुमार सेन', 'Sukumar Sen', 100, 0, '{"facts":["चुनाव आयोग की स्थापना 25 जनवरी 1950 को हुई थी (राष्ट्रीय मतदाता दिवस)।"],"factsEn":["Election Commission established on 25 Jan 1950 (National Voters'' Day)."],"memoryTip":"चुनाव शांति (''सुकून'') से करवाने वाले सुकुमार।","memoryTipEn":"Sukumar brought ''Sukoon'' (peace) to elections.","explanationHi":"उन्होंने भारत के पहले दो आम चुनावों (1951-52 और 1957) को सफलतापूर्वक आयोजित करवाया था।","explanationEn":"He successfully conducted India''s first two general elections (1951-52 and 1957)."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NPctKfgewI_jmhWmJknDF', 'Polity', 'नीति (NITI) आयोग का अध्यक्ष कौन होता है?', 'Who is the Chairman of NITI Aayog?', 'प्रधानमंत्री', 'Prime Minister', 100, 0, '{"facts":["गठन 1 जनवरी 2015 को हुआ; योजना आयोग के स्थान पर।"],"factsEn":["Formed on 1 Jan 2015; Replaced the Planning Commission."],"memoryTip":"देश की ''नीति'' PM बनाते हैं।","memoryTipEn":"PM makes the ''NITI'' (Policy) of the nation.","explanationHi":"NITI (National Institution for Transforming India) सरकार के थिंक टैंक के रूप में कार्य करता है।","explanationEn":"NITI (National Institution for Transforming India) serves as the government''s think tank."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('6_scXKzMOxz2HfBmfWBZN', 'Polity', 'अस्पृश्यता का अंत किस अनुच्छेद में दिया गया है?', 'Abolition of Untouchability is given in which Article?', 'अनुच्छेद 17', 'Article 17', 100, 0, '{"facts":["यह एक मौलिक अधिकार है (समानता का अधिकार)।"],"factsEn":["It is a Fundamental Right (Right to Equality)."],"memoryTip":"17 (सत्रह) = ''खतरा'' (छुआछूत करोगे तो खतरा है)।","memoryTipEn":"17 rhymes with ''Khatra'' (danger) for untouchability.","explanationHi":"यह अनुच्छेद किसी भी रूप में छुआछूत के आचरण को अपराध घोषित करता है और दंडनीय बनाता है।","explanationEn":"This article criminalizes the practice of untouchability in any form and makes it punishable."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('AA_vhRn4dIZfEet4HGvFm', 'Polity', 'भारतीय संविधान में वर्तमान में कुल कितनी अनुसूचियां हैं?', 'How many schedules are currently there in the Indian Constitution?', '12', '12', 100, 0, '{"facts":["मूल संविधान में 8 अनुसूचियां थीं; बाद में 4 जोड़ी गईं।"],"factsEn":["Original constitution had 8 schedules; 4 were added later."],"memoryTip":"साल में 12 महीने, संविधान में 12 अनुसूचियां।","memoryTipEn":"12 months, 12 schedules.","explanationHi":"9वीं अनुसूची भूमि सुधार, 10वीं दल-बदल, 11वीं पंचायत और 12वीं नगर पालिका से संबंधित है।","explanationEn":"9th is Land reform, 10th Anti-Defection, 11th Panchayat, and 12th Municipality."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Z6YHZWe9X8G5WnhAuCcLM', 'Polity', 'राष्ट्रपति को शपथ कौन दिलाता है?', 'Who administers the oath to the President?', 'भारत के मुख्य न्यायाधीश (CJI)', 'Chief Justice of India (CJI)', 100, 0, '{"facts":["अनुच्छेद 60 के तहत शपथ ली जाती है; CJI की अनुपस्थिति में सुप्रीम कोर्ट के वरिष्ठतम न्यायाधीश।"],"factsEn":["Oath taken under Article 60; Senior-most Supreme Court judge in CJI''s absence."],"memoryTip":"देश का सबसे बड़ा नेता + देश का सबसे बड़ा जज।","memoryTipEn":"Top Executive meets Top Judiciary.","explanationHi":"राष्ट्रपति संविधान और कानून के संरक्षण, रक्षा और प्रतिरक्षण की शपथ लेते हैं।","explanationEn":"The President takes an oath to preserve, protect, and defend the Constitution and the law."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('QEJawJcRluLSs8xqi2ui3', 'General Knowledge', 'भारत की प्रथम महिला राज्यपाल कौन थीं?', 'Who was the first woman Governor of India?', 'सरोजिनी नायडू', 'Sarojini Naidu', 100, 0, '{"facts":["वे उत्तर प्रदेश (संयुक्त प्रांत) की राज्यपाल बनी थीं; इन्हें ''भारत कोकिला'' भी कहा जाता है।"],"factsEn":["Became Governor of UP (United Provinces); Also known as ''Nightingale of India''."],"memoryTip":"नायडू (Naidu) - नारी (Naari) सबसे पहले राजभवन में।","memoryTipEn":"Sarojini sang her way to the Governor''s office.","explanationHi":"वह भारतीय राष्ट्रीय कांग्रेस की पहली भारतीय महिला अध्यक्ष (1925, कानपुर अधिवेशन) भी थीं।","explanationEn":"She was also the first Indian woman President of the Indian National Congress (1925, Kanpur session)."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('mV-cSvchtjOfYYOjyfCaw', 'Polity', 'संपत्ति का अधिकार (Right to Property) अब क्या है?', 'What is the Right to Property now?', 'विधिक अधिकार (Legal Right)', 'Legal Right', 100, 0, '{"facts":["44वें संविधान संशोधन (1978) द्वारा मौलिक अधिकारों से हटाया गया; अब अनुच्छेद 300A में है।"],"factsEn":["Removed from Fundamental Rights by 44th Amendment (1978); Now in Article 300A."],"memoryTip":"4+4 = 8 (प्रॉपर्टी को मौलिक अधिकार से हटा दिया)।","memoryTipEn":"44th amendment evicted property rights.","explanationHi":"अब कोई भी व्यक्ति संपत्ति से वंचित किए जाने पर सीधे सुप्रीम कोर्ट नहीं जा सकता, यह केवल एक कानूनी अधिकार है।","explanationEn":"Now a person cannot approach the Supreme Court directly if deprived of property; it is solely a legal right."}', 'published', 1777198575, 1777198575);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lrP_iQ8hlCrxk99tZQI9E', 'MP GK', 'महाकालेश्वर ज्योतिर्लिंग किस नदी के तट पर स्थित है?', 'Mahakaleshwar Jyotirlinga is situated on the banks of which river?', 'शिप्रा', 'Shipra', 100, 0, '{"facts":["उज्जैन में स्थित है; यहाँ प्रत्येक 12 वर्ष में सिंहस्थ (कुंभ) मेला लगता है।"],"factsEn":["Located in Ujjain; Simhastha (Kumbh) Mela is held here every 12 years."],"memoryTip":"महाकाल के दर्शन ''शिप्रा'' में डुबकी लगाकर होते हैं।","memoryTipEn":"Shiva (Mahakal) sits by the Shipra.","explanationHi":"यह भारत के 12 ज्योतिर्लिंगों में से एकमात्र दक्षिणमुखी ज्योतिर्लिंग है।","explanationEn":"It is the only south-facing Jyotirlinga among the 12 Jyotirlingas in India."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('tnzwDVCMGKqg5TPTFhnM2', 'MP GK', 'मध्य प्रदेश का पहला बायोस्फीयर रिजर्व कौन सा है?', 'Which is the first Biosphere Reserve of Madhya Pradesh?', 'पचमढ़ी', 'Pachmarhi', 100, 0, '{"facts":["1999 में घोषित; यह होशंगाबाद (नर्मदापुरम) जिले में सतपुड़ा श्रेणी में है।"],"factsEn":["Declared in 1999; Located in the Satpura range in Hoshangabad (Narmadapuram) district."],"memoryTip":"पाँच मढ़ियों (पचमढ़ी) में सबसे पहले जीवन (बायो) बचा।","memoryTipEn":"Pachmarhi was the ''First'' to ''Patch'' nature together.","explanationHi":"इसे ''सतपुड़ा की रानी'' भी कहा जाता है और यह अपनी जैव विविधता के लिए प्रसिद्ध है।","explanationEn":"Also known as the ''Queen of Satpura'', it is famous for its rich biodiversity."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SbqQSauL3_DMSI1zPYnBs', 'MP GK', 'मलाजखंड खदान किस खनिज के लिए प्रसिद्ध है?', 'Malanjkhand mine is famous for which mineral?', 'तांबा (Copper)', 'Copper', 100, 0, '{"facts":["बालाघाट जिले में स्थित है; इसे तांबा नगरी भी कहते हैं।"],"factsEn":["Located in Balaghat district; Also known as Copper City."],"memoryTip":"मलों (गंदगी) को ''तांबे'' के बर्तन में साफ पानी से धोएं।","memoryTipEn":"Malanjkhand Makes Massive Copper.","explanationHi":"यह भारत की सबसे बड़ी खुली तांबे की खदान (open-cast copper mine) है।","explanationEn":"It is the largest open-cast copper mine in India."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('-VdBGwUw3IjkYcnq7daHL', 'MP GK', 'सफेद शेरों की भूमि किस जिले को कहा जाता है?', 'Which district is known as the land of white tigers?', 'रीवा', 'Rewa', 100, 0, '{"facts":["महाराजा मार्तंड सिंह ने पहले सफेद बाघ ''मोहन'' को पकड़ा था (1951)।"],"factsEn":["Maharaja Martand Singh captured the first white tiger ''Mohan'' (1951)."],"memoryTip":"रीवा के शेर ''रवा'' (सफेद सूजी) जैसे सफेद होते हैं।","memoryTipEn":"Rewa Roars with White tigers.","explanationHi":"रीवा के जंगलों में ही विश्व में पहली बार सफेद बाघ देखा गया था। मुकुंदपुर में व्हाइट टाइगर सफारी स्थित है।","explanationEn":"The world''s first white tiger was spotted in Rewa forests. Mukundpur hosts a White Tiger Safari."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('9ULW_M3USN-g_DAx_YkV8', 'MP GK', 'मध्य प्रदेश का राज्य वृक्ष कौन सा है?', 'Which is the state tree of Madhya Pradesh?', 'बरगद (Banyan)', 'Banyan', 100, 0, '{"facts":["वैज्ञानिक नाम: Ficus benghalensis; 1981 में घोषित।"],"factsEn":["Scientific name: Ficus benghalensis; Declared in 1981."],"memoryTip":"म.प्र. ''बरगद'' की तरह विशाल और छायादार है।","memoryTipEn":"MP is rooted deep like a Banyan tree.","explanationHi":"यह वृक्ष अपनी विशालता और दीर्घायु के लिए जाना जाता है, जो राज्य की स्थिरता का प्रतीक है।","explanationEn":"This tree is known for its immensity and longevity, symbolizing the state''s stability."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('18MvlWvVPZxpOKpy41tLC', 'MP GK', 'अहिल्याबाई होल्कर की राजधानी कहाँ थी?', 'Where was the capital of Ahilyabai Holkar?', 'महेश्वर', 'Maheshwar', 100, 0, '{"facts":["खरगोन जिले में नर्मदा नदी के तट पर; यहाँ का किला प्रसिद्ध है।"],"factsEn":["On the banks of Narmada in Khargone district; The fort here is famous."],"memoryTip":"अहिल्याबाई ''महान ईश्वर'' (महेश्वर) की भक्त थीं।","memoryTipEn":"Ahilyabai was as great as Maheshwar (Shiva).","explanationHi":"अहिल्याबाई ने मालवा पर शासन किया और महेश्वर को अपनी राजधानी बनाकर वहां वस्त्र उद्योग (महेश्वरी साड़ी) को बढ़ावा दिया।","explanationEn":"Ahilyabai ruled Malwa, making Maheshwar her capital and promoting the textile industry (Maheshwari Sarees)."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('RgCI6jYKLyXF8UBRRjiYP', 'MP GK', 'ग्वालियर के किले का निर्माण किसने करवाया था?', 'Who built the Gwalior Fort?', 'राजा सूरज सेन', 'Raja Suraj Sen', 100, 0, '{"facts":["इसे ''किलों का रत्न'' (Gibraltar of India) कहा जाता है।"],"factsEn":["It is known as the ''Gem of Forts'' (Gibraltar of India)."],"memoryTip":"ग्वालियर का किला ''सूरज'' की तरह चमकता है।","memoryTipEn":"The fort stands tall facing the ''Suraj'' (Sun).","explanationHi":"यह 8वीं शताब्दी में बना था और इसमें मान मंदिर और गूजरी महल स्थित हैं।","explanationEn":"Built in the 8th century, it houses the Man Mandir and Gujari Mahal."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Qf6-C9FyCcBSkv9ByW9jX', 'MP GK', 'मध्य प्रदेश का राजकीय नृत्य कौन सा है?', 'Which is the state dance of Madhya Pradesh?', 'राई (Raai)', 'Raai', 100, 0, '{"facts":["यह मुख्य रूप से बुंदेलखंड क्षेत्र का लोक नृत्य है।"],"factsEn":["It is primarily a folk dance of the Bundelkhand region."],"memoryTip":"म.प्र. के लोग हर बात पर ''राई'' (राय) देते हैं और नाचते हैं।","memoryTipEn":"Dance to the rhythm of ''Raai'' (Mustard seeds popping).","explanationHi":"यह नृत्य बेड़नी समुदाय की महिलाओं द्वारा ढोलक और मृदंग की थाप पर किया जाता है।","explanationEn":"This dance is performed by women of the Bedni community to the beats of Dholak and Mridang."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Sosm6ZNtpTuKW6Dz-VPKN', 'MP GK', 'चंदेरी की साड़ियाँ किस जिले से संबंधित हैं?', 'Chanderi sarees are associated with which district?', 'अशोकनगर', 'Ashoknagar', 100, 0, '{"facts":["इन्हें भौगोलिक संकेत (GI Tag) प्राप्त है; रेशम और सूती धागों से बनती हैं।"],"factsEn":["They hold a Geographical Indication (GI Tag); Made from silk and cotton threads."],"memoryTip":"''अशोक'' अपनी रानियों को ''चंदेरी'' की साड़ियाँ देता था।","memoryTipEn":"Ashoka loved Chanderi fabric.","explanationHi":"चंदेरी अपने हथकरघा उद्योग और ऐतिहासिक किलों के लिए जाना जाता है।","explanationEn":"Chanderi is known for its handloom industry and historical forts."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('z3sg04gClDJTCjWCINSYA', 'MP GK', 'तवा जलाशय (तवा डैम) किस जिले में है?', 'Tawa Reservoir (Tawa Dam) is in which district?', 'नर्मदापुरम (होशंगाबाद)', 'Narmadapuram (Hoshangabad)', 100, 0, '{"facts":["तवा नदी पर स्थित है, जो नर्मदा की सहायक नदी है।"],"factsEn":["Located on Tawa river, which is a tributary of Narmada."],"memoryTip":"''होश'' उड़ गए इतना बड़ा ''तवा'' देखकर।","memoryTipEn":"Tawa is hot in Hoshangabad.","explanationHi":"यह बांध सिंचाई और बिजली उत्पादन के लिए महत्वपूर्ण है और बोरी वन्यजीव अभयारण्य के पास है।","explanationEn":"The dam is vital for irrigation and power generation, located near Bori Wildlife Sanctuary."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5eNJkINJv68l11okyDZyN', 'History', 'भारतीय राष्ट्रीय कांग्रेस की स्थापना किसने की थी?', 'Who founded the Indian National Congress?', 'ए. ओ. ह्यूम (A. O. Hume)', 'A. O. Hume', 100, 0, '{"facts":["28 दिसंबर 1885 को बॉम्बे में स्थापना; प्रथम अध्यक्ष व्योमेश चंद्र बनर्जी (W.C. Bonnerjee) थे।"],"factsEn":["Founded on 28 Dec 1885 in Bombay; First president was W.C. Bonnerjee."],"memoryTip":"ह्यूम (Hume) ने कांग्रेस का ''होम'' (Home) बनाया।","memoryTipEn":"Hume provided the Home for Congress.","explanationHi":"लॉर्ड डफरिन के समय में एक सेवानिवृत्त ब्रिटिश अधिकारी ए.ओ. ह्यूम ने भारतीयों को राजनीतिक मंच देने के लिए इसे बनाया था।","explanationEn":"During Lord Dufferin''s time, a retired British official A.O. Hume created it to give Indians a political platform."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lIcOnakvBI8QXrMULLyfW', 'History', 'तराइन का प्रथम युद्ध कब और किसके बीच हुआ था?', 'When and between whom was the First Battle of Tarain fought?', '1191 (पृथ्वीराज चौहान और मोहम्मद गौरी)', '1191 (Prithviraj Chauhan and Muhammad Ghori)', 100, 0, '{"facts":["इस युद्ध में पृथ्वीराज चौहान की विजय हुई थी। 1192 में दूसरे युद्ध में वे हार गए।"],"factsEn":["Prithviraj Chauhan won this battle. He lost the second battle in 1192."],"memoryTip":"11-9-1: तराइन में एक-एक कर 9 लोग 1 चौहान से लड़े।","memoryTipEn":"1191: First time Chauhan won.","explanationHi":"यह युद्ध उत्तर भारत पर इस्लामी आक्रमणों के खिलाफ हिंदू राजपूत राजाओं के प्रतिरोध का एक प्रमुख बिंदु था।","explanationEn":"This battle was a major flashpoint of Hindu Rajput resistance against Islamic invasions in North India."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WKoMPdQYITIExoQmQnX0j', 'History', 'असहयोग आंदोलन किस वर्ष शुरू हुआ था?', 'In which year did the Non-Cooperation Movement start?', '1920', '1920', 100, 0, '{"facts":["गांधीजी द्वारा शुरू किया गया; चौरी-चौरा घटना (1922) के बाद इसे वापस ले लिया गया।"],"factsEn":["Started by Gandhiji; Withdrawn after the Chauri Chaura incident (1922)."],"memoryTip":"19-20 (उन्निस-बीस) का फर्क नहीं, सीधा असहयोग करेंगे।","memoryTipEn":"In the 20s, Indians stopped cooperating.","explanationHi":"जलियांवाला बाग हत्याकांड और रॉलेट एक्ट के विरोध में ब्रिटिश सरकार से असहयोग करने के लिए यह आंदोलन चलाया गया।","explanationEn":"It was launched to refuse cooperation with the British government in protest against the Jallianwala Bagh massacre and Rowlatt Act."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UQWJdryyC2Wnyz2o-1yHt', 'History', 'सती प्रथा का अंत किस गवर्नर जनरल के काल में हुआ था?', 'During which Governor General''s tenure was the Sati system abolished?', 'लॉर्ड विलियम बेंटिंक', 'Lord William Bentinck', 100, 0, '{"facts":["1829 में राजा राममोहन राय के प्रयासों से; नियम 17 (Regulation XVII) के तहत।"],"factsEn":["In 1829 with the efforts of Raja Rammohan Roy; under Regulation XVII."],"memoryTip":"बेंटिंक ने सती प्रथा पर ''बैन'' (Ban) लगा दिया।","memoryTipEn":"Bentinck ''Banned'' it.","explanationHi":"इस कानून ने विधवाओं को उनके पति की चिता पर जिंदा जलाने की क्रूर प्रथा को अवैध घोषित कर दिया।","explanationEn":"This law criminalized the cruel practice of burning widows alive on their husbands'' funeral pyres."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('5Dv-kvHUWXhtshrLgaVrE', 'History', 'बुलंद दरवाजा कहाँ स्थित है और इसे किसने बनवाया?', 'Where is Buland Darwaza located and who built it?', 'फतेहपुर सीकरी (अकबर)', 'Fatehpur Sikri (Akbar)', 100, 0, '{"facts":["गुजरात विजय (1572) के उपलक्ष्य में बनवाया गया; यह दुनिया का सबसे ऊँचा प्रवेश द्वार है।"],"factsEn":["Built to commemorate the victory over Gujarat (1572); It is the highest gateway in the world."],"memoryTip":"अकबर के इरादे ''बुलंद'' थे।","memoryTipEn":"Akbar''s victory was ''Buland'' (Grand).","explanationHi":"लाल बलुआ पत्थर से बना यह विशाल द्वार मुगल वास्तुकला की भव्यता को दर्शाता है।","explanationEn":"Made of red sandstone, this massive gate reflects the grandeur of Mughal architecture."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('BudagEoSa-VljaGyhh7kI', 'History', 'स्वतंत्र भारत के प्रथम भारतीय गवर्नर जनरल कौन थे?', 'Who was the first Indian Governor-General of independent India?', 'सी. राजगोपालाचारी', 'C. Rajagopalachari', 100, 0, '{"facts":["वे भारत के अंतिम गवर्नर जनरल भी थे; माउंटबेटन के बाद बने।"],"factsEn":["He was also the last Governor-General of India; Succeeded Mountbatten."],"memoryTip":"अब भारत पर भारतीयों का ''राज'' (राजगोपालाचारी) होगा।","memoryTipEn":"Rajagopalachari brought the ''Raj'' back to Indians.","explanationHi":"26 जनवरी 1950 को संविधान लागू होने पर गवर्नर जनरल का पद समाप्त कर दिया गया और राष्ट्रपति का पद सृजित हुआ।","explanationEn":"When the Constitution came into effect on Jan 26, 1950, the post of Governor-General was abolished and replaced by the President."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('dxyK4pR16Z6ftaFWUyusv', 'History', 'दांडी मार्च (नमक सत्याग्रह) किस वर्ष हुआ था?', 'In which year did the Dandi March (Salt Satyagraha) take place?', '1930', '1930', 100, 0, '{"facts":["12 मार्च 1930 को साबरमती आश्रम से शुरू; सविनय अवज्ञा आंदोलन की शुरुआत।"],"factsEn":["Started from Sabarmati Ashram on 12 March 1930; Marked the beginning of Civil Disobedience Movement."],"memoryTip":"गांधीजी ने 30 दिन (1930) चलकर नमक बनाया।","memoryTipEn":"Marching in 1930 for salty freedom.","explanationHi":"गांधीजी ने 78 अनुयायियों के साथ 385 किमी की यात्रा कर दांडी में नमक कानून तोड़ा था।","explanationEn":"Gandhiji, along with 78 followers, marched 385 km to break the salt law at Dandi."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UvNmjgblg8A7Fpyu1Slmz', 'History', 'भारत की राजधानी कलकत्ता से दिल्ली कब स्थानांतरित की गई?', 'When was the capital of India shifted from Calcutta to Delhi?', '1911 (घोषणा)', '1911 (Announcement)', 100, 0, '{"facts":["दिल्ली दरबार में किंग जॉर्ज पंचम द्वारा घोषित; लॉर्ड हार्डिंग के समय। (स्थानांतरण 1912 में पूर्ण हुआ)"],"factsEn":["Announced by King George V at Delhi Durbar; During Lord Hardinge''s time. (Shift completed in 1912)."],"memoryTip":"1-1 (एक-एक) करके सब दिल्ली चले गए।","memoryTipEn":"1911: Two ones (11) walking to Delhi.","explanationHi":"बंगाल विभाजन के विरोध और प्रशासनिक सुविधा के कारण राजधानी को दिल्ली लाया गया था।","explanationEn":"The capital was moved to Delhi due to opposition to the Bengal partition and for administrative convenience."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('OdMgOYllip0xm7764Zrpq', 'History', 'सबसे प्राचीन वेद कौन सा है?', 'Which is the oldest Veda?', 'ऋग्वेद', 'Rigveda', 100, 0, '{"facts":["इसमें 10 मंडल और 1028 सूक्त हैं; गायत्री मंत्र इसी के तीसरे मंडल में है।"],"factsEn":["It has 10 Mandalas and 1028 hymns; Gayatri Mantra is in its 3rd Mandala."],"memoryTip":"ऋषि-मुनि सबसे पहले ''ऋग्वेद'' पढ़ते थे।","memoryTipEn":"Rigveda is Rightly the oldest.","explanationHi":"यह वैदिक संस्कृत भजनों का एक प्राचीन भारतीय संग्रह है और इसे दुनिया के सबसे पुराने ज्ञात धार्मिक ग्रंथों में गिना जाता है।","explanationEn":"It is an ancient Indian collection of Vedic Sanskrit hymns and is counted among the oldest known religious texts in the world."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('eytWFVuC4o8TpMldqE32h', 'History', 'जैन धर्म के 24वें और अंतिम तीर्थंकर कौन थे?', 'Who was the 24th and last Tirthankara of Jainism?', 'भगवान महावीर', 'Lord Mahavira', 100, 0, '{"facts":["बचपन का नाम वर्धमान था; उन्होंने जैन धर्म के मूल सिद्धांतों को अंतिम रूप दिया। (प्रथम ऋषभदेव थे)"],"factsEn":["Childhood name was Vardhamana; He gave final shape to the core principles of Jainism. (First was Rishabhanatha)."],"memoryTip":"24 घंटे ''महावीर'' की तरह तपस्या की।","memoryTipEn":"Mahavira (The Great Hero) finished the line at 24.","explanationHi":"महावीर ने ''अहिंसा'' (Non-violence) पर सबसे अधिक जोर दिया और प्राकृत भाषा में उपदेश दिए।","explanationEn":"Mahavira laid extreme emphasis on ''Ahimsa'' (Non-violence) and preached in the Prakrit language."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4SsS_JOLVN9LtFakOgFEy', 'Geography', 'क्षेत्रफल की दृष्टि से भारत का सबसे बड़ा राज्य कौन सा है?', 'Which is the largest state of India in terms of area?', 'राजस्थान', 'Rajasthan', 100, 0, '{"facts":["मध्य प्रदेश दूसरे और महाराष्ट्र तीसरे स्थान पर है।"],"factsEn":["Madhya Pradesh is second and Maharashtra is third."],"memoryTip":"जिसका ''राज'' (Raj) है, उसका स्थान (स्थान) सबसे बड़ा होगा।","memoryTipEn":"Rajas (Kings) have the largest land.","explanationHi":"भारत के कुल क्षेत्रफल का लगभग 10.4% हिस्सा राजस्थान के अंतर्गत आता है।","explanationEn":"Rajasthan covers about 10.4% of the total land area of India."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('pp16yOvHdSp8W8lyNugUo', 'Geography', 'भारत में सबसे लंबी तटरेखा वाला राज्य कौन सा है?', 'Which state has the longest coastline in India?', 'गुजरात', 'Gujarat', 100, 0, '{"facts":["लंबाई लगभग 1600 किमी है; दूसरे स्थान पर आंध्र प्रदेश है।"],"factsEn":["Length is approx 1600 km; Andhra Pradesh is second."],"memoryTip":"गुजरते-गुजरते (गुजरात) तट खत्म ही नहीं होता।","memoryTipEn":"Gujarat''s jaw-like shape adds to its long coast.","explanationHi":"कच्छ और काठियावाड़ प्रायद्वीप के कारण गुजरात की तटरेखा कटी-फटी और लंबी है।","explanationEn":"Due to the Kutch and Kathiawar peninsulas, Gujarat''s coastline is indented and very long."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('tpDUNt19ebTh5sIuPhfH8', 'Geography', 'भारत का सबसे ऊँचा बाँध कौन सा है?', 'Which is the highest dam in India?', 'टिहरी बाँध (Tehri Dam)', 'Tehri Dam', 100, 0, '{"facts":["उत्तराखंड में भागीरथी और भिलंगना नदी के संगम पर स्थित है; ऊँचाई 260.5 मीटर।"],"factsEn":["Located on the confluence of Bhagirathi and Bhilangna rivers in Uttarakhand; Height is 260.5 meters."],"memoryTip":"इतना ऊँचा बाँध देखकर ''टिहरी'' (टेढ़ी) गर्दन करनी पड़ी।","memoryTipEn":"Tehri is ''Terrifically'' high.","explanationHi":"यह एक अर्थ-फिल (earth-fill) रॉक डैम है, जो भूकंप के प्रति संवेदनशील हिमालयी क्षेत्र में स्थित है।","explanationEn":"It is an earth-fill rock dam located in the seismically active Himalayan region."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('SVlhfdjDTFFnaTCNLr1Ip', 'Geography', 'भारत की सबसे बड़ी खारे पानी की झील कौन सी है?', 'Which is the largest brackish water lake in India?', 'चिल्का झील', 'Chilika Lake', 100, 0, '{"facts":["ओडिशा में स्थित है; यह एक लैगून (Lagoon) झील है।"],"factsEn":["Located in Odisha; It is a lagoon lake."],"memoryTip":"खारा पानी पीकर ''चील'' (चिल्का) उड़ गई।","memoryTipEn":"Chilika looks like a Chill Lagoon.","explanationHi":"चिल्का झील सर्दियों के दौरान प्रवासी पक्षियों के लिए भारतीय उपमहाद्वीप का सबसे बड़ा शीतकालीन मैदान है।","explanationEn":"Chilika Lake is the largest wintering ground for migratory birds on the Indian sub-continent."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('NFg3cREcD07dYkZ7X6M08', 'Geography', 'विश्व का सबसे बड़ा डेल्टा कौन सा है?', 'Which is the largest delta in the world?', 'सुंदरवन डेल्टा', 'Sundarbans Delta', 100, 0, '{"facts":["गंगा और ब्रह्मपुत्र नदियों द्वारा बनता है; भारत (पश्चिम बंगाल) और बांग्लादेश में स्थित है।"],"factsEn":["Formed by Ganga and Brahmaputra rivers; Located in India (West Bengal) and Bangladesh."],"memoryTip":"गंगा और ब्रह्मपुत्र का मिलन ''सुंदर'' है।","memoryTipEn":"The world''s biggest delta is ''Sundar'' (Beautiful).","explanationHi":"यह सुंदरी (मैंग्रोव) पेड़ों और रॉयल बंगाल टाइगर के लिए विश्व प्रसिद्ध है।","explanationEn":"It is world-famous for Sundari (mangrove) trees and the Royal Bengal Tiger."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('XyvLnouMfldjgc5CeE-lC', 'Geography', 'कर्क रेखा भारत के कितने राज्यों से होकर गुजरती है?', 'Tropic of Cancer passes through how many states of India?', '8', '8', 100, 0, '{"facts":["गुजरात, राजस्थान, म.प्र., छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा, मिजोरम।"],"factsEn":["Gujarat, Rajasthan, MP, Chhattisgarh, Jharkhand, West Bengal, Tripura, Mizoram."],"memoryTip":"मित्र पर गमछा झार (मि-त्रि-प-र-ग-म-छा-झार)।","memoryTipEn":"8 states form a belt across India.","explanationHi":"यह 23.5° उत्तरी अक्षांश रेखा है जो भारत को लगभग दो जलवायु कटिबंधों (उष्ण और उपोष्ण) में बाँटती है।","explanationEn":"It is the 23.5° North latitude that divides India into roughly two climatic zones (tropical and subtropical)."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rex7BIpp6tFW0jGPyy-wP', 'Geography', 'विश्व का सबसे गहरा महासागर कौन सा है?', 'Which is the deepest ocean in the world?', 'प्रशांत महासागर (Pacific Ocean)', 'Pacific Ocean', 100, 0, '{"facts":["मारियाना ट्रेंच (चैलेंजर डीप) इसकी सबसे गहरी जगह है (लगभग 11,034 मीटर)।"],"factsEn":["Mariana Trench (Challenger Deep) is its deepest point (approx 11,034 meters)."],"memoryTip":"सबसे ज्यादा पानी बहुत ''शांत'' (प्रशांत) होता है।","memoryTipEn":"Pacific means peaceful, but it hides extreme depths.","explanationHi":"यह महासागर क्षेत्रफल और गहराई दोनों में विश्व में प्रथम स्थान पर है।","explanationEn":"This ocean ranks first in the world in both area and depth."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('FMjGCqbIhpfhCcwVr5zEy', 'Geography', 'क्षेत्रफल की दृष्टि से भारत का सबसे छोटा राज्य कौन सा है?', 'Which is the smallest state of India in terms of area?', 'गोवा', 'Goa', 100, 0, '{"facts":["जनसंख्या की दृष्टि से सिक्किम सबसे छोटा है।"],"factsEn":["Sikkim is the smallest in terms of population."],"memoryTip":"गोवा ''गया'' और तुरंत घूम कर आ गया (क्योंकि छोटा है)।","memoryTipEn":"Goa is a tiny pearl on the coast.","explanationHi":"गोवा का क्षेत्रफल मात्र 3,702 वर्ग किलोमीटर है और 1961 में इसे पुर्तगालियों से मुक्त कराया गया था।","explanationEn":"Goa''s area is only 3,702 square kilometers and it was liberated from the Portuguese in 1961."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('3P5jYTI2e9dLWjZ97ihXX', 'Geography', 'किस नदी को ''दक्षिण गंगा'' (या वृद्ध गंगा) कहा जाता है?', 'Which river is called the ''Dakshin Ganga'' (or Vridha Ganga)?', 'गोदावरी', 'Godavari', 100, 0, '{"facts":["यह प्रायद्वीपीय भारत की सबसे लंबी नदी है; त्र्यंबकेश्वर (महाराष्ट्र) से निकलती है।"],"factsEn":["It is the longest river in peninsular India; Originates from Trimbakeshwar (Maharashtra)."],"memoryTip":"दक्षिण में ''गोद'' (Godavari) में जाकर गंगा बहती है।","memoryTipEn":"Godavari is the God of southern rivers.","explanationHi":"इसकी लंबाई और जलग्रहण क्षेत्र के विशाल आकार के कारण इसे दक्षिण भारत की गंगा कहा जाता है (पवित्रता के आधार पर कावेरी को दक्षिण भारत की गंगा कहते हैं)।","explanationEn":"Due to its length and large catchment area, it is called the Ganga of the South (Cauvery is called so based on purity)."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('xNCq3jhH1-FVQVy912dwX', 'Geography', 'विश्व में सर्वाधिक वर्षा वाला स्थान कौन सा है?', 'Which is the wettest place in the world?', 'मासिनराम (Mawsynram)', 'Mawsynram', 100, 0, '{"facts":["मेघालय के खासी हिल्स जिले में स्थित है; चेरापूंजी के बहुत करीब है।"],"factsEn":["Located in Khasi Hills district of Meghalaya; Very close to Cherrapunji."],"memoryTip":"बादल यहाँ ''मास'' (महीनों) तक बरसते हैं।","memoryTipEn":"Mawsynram has maximum rain.","explanationHi":"बंगाल की खाड़ी से आने वाली मानसूनी हवाएं कीप के आकार की पहाड़ियों (गारो, खासी, जयंतिया) में फँस जाती हैं, जिससे भारी बारिश होती है।","explanationEn":"Monsoon winds from the Bay of Bengal get trapped in the funnel-shaped hills (Garo, Khasi, Jaintia), causing heavy rainfall."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('ZJPsA-VLYfkGJi17eDztX', 'General Science', 'सर्वदाता (Universal Donor) रक्त समूह कौन सा है?', 'Which is the Universal Donor blood group?', 'O नेगेटिव (O-)', 'O Negative (O-)', 100, 0, '{"facts":["सर्वग्राही (Universal Recipient) AB पॉजिटिव (AB+) होता है।"],"factsEn":["Universal Recipient is AB Positive (AB+)."],"memoryTip":"''O'' मतलब ज़ीरो (कोई एंटीजन नहीं), इसलिए सबको खून दे सकता है।","memoryTipEn":"O- gives to all, taking nothing back.","explanationHi":"O- रक्त में कोई A, B या Rh एंटीजन नहीं होता है, इसलिए इसे किसी भी रक्त समूह वाले मरीज को चढ़ाया जा सकता है।","explanationEn":"O- blood lacks A, B, or Rh antigens, making it safe for transfusion to patients of any blood group."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('VUu1WjhVzzXoc2dHwggHi', 'General Science', 'गुब्बारों में कौन सी गैस भरी जाती है?', 'Which gas is filled in balloons?', 'हीलियम (Helium)', 'Helium', 100, 0, '{"facts":["यह हवा से हल्की होती है और अज्वलनशील (non-flammable) है। (हाइड्रोजन सबसे हल्की है पर ज्वलनशील है)"],"factsEn":["It is lighter than air and non-flammable. (Hydrogen is lightest but flammable)."],"memoryTip":"गुब्बारा हवा में ''हील'' (Heal/Helium) करते हुए उड़ता है।","memoryTipEn":"Helium helps balloons fly High.","explanationHi":"हवा से हल्की होने के कारण हीलियम गुब्बारे को ऊपर उठाती है और सुरक्षित होने के कारण इसका उपयोग किया जाता है।","explanationEn":"Being lighter than air, Helium lifts the balloon and is used because it is safe (inert)."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('eHCQQlJpp7xrNgd8K6-zE', 'General Science', 'विद्युत शक्ति (Electric Power) का SI मात्रक क्या है?', 'What is the SI unit of Electric Power?', 'वाट (Watt)', 'Watt', 100, 0, '{"facts":["1 हॉर्स पावर (HP) = 746 वाट; P = VI (वोल्टेज × करंट)।"],"factsEn":["1 Horse Power (HP) = 746 Watts; P = VI (Voltage × Current)."],"memoryTip":"बिजली का बिल देखकर ''वाट'' लग गई।","memoryTipEn":"Watt is the power of a light bulb.","explanationHi":"यह जेम्स वाट के नाम पर रखा गया है और ऊर्जा की खपत या उत्पादन की दर को मापता है।","explanationEn":"Named after James Watt, it measures the rate of energy consumption or production."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('nWxcXc2EUp6diTuLbfKEP', 'General Science', 'मानव शरीर का सबसे बड़ा अंग कौन सा है?', 'Which is the largest organ of the human body?', 'त्वचा (Skin)', 'Skin', 100, 0, '{"facts":["अगर आंतरिक अंग (Internal Organ) पूछा जाए, तो यकृत (Liver) सबसे बड़ा है।"],"factsEn":["If asked about Internal Organ, Liver is the largest."],"memoryTip":"त्वचा ने पूरे शरीर को ढँक रखा है (सबसे बड़ा)।","memoryTipEn":"Skin is the wrapper of the human body.","explanationHi":"त्वचा शरीर के कुल वजन का लगभग 15-20% होती है और संक्रमण से रक्षा करती है।","explanationEn":"The skin accounts for about 15-20% of total body weight and protects against infections."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('pjD2jYgOIyxbUDg6IKnBM', 'General Science', 'मानव शरीर की सबसे बड़ी ग्रंथि (Gland) कौन सी है?', 'Which is the largest gland of the human body?', 'यकृत (Liver)', 'Liver', 100, 0, '{"facts":["यह पित्त (Bile) का निर्माण करता है, जो गॉलब्लैडर (पित्ताशय) में जमा होता है।"],"factsEn":["It produces Bile, which is stored in the Gallbladder."],"memoryTip":"लीवर (Liver) शरीर का ''लीडर'' (सबसे बड़ा) है।","memoryTipEn":"Liver Lives Large.","explanationHi":"लीवर शरीर को डिटॉक्सिफाई करता है और पाचन के लिए महत्वपूर्ण रसायनों का उत्पादन करता है। इसमें पुनर्जनन (regeneration) की क्षमता होती है।","explanationEn":"The liver detoxifies the body and produces vital digestive chemicals. It has high regeneration capacity."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('PmMK-S-wYSur7RacdPPuC', 'General Science', 'विटामिन D की कमी से बच्चों में कौन सा रोग होता है?', 'Which disease is caused in children due to Vitamin D deficiency?', 'रिकेट्स (सूखा रोग)', 'Rickets', 100, 0, '{"facts":["वयस्कों में ऑस्टियोमलेशिया होता है; विटामिन D का मुख्य स्रोत सूर्य का प्रकाश है।"],"factsEn":["Causes Osteomalacia in adults; Main source of Vitamin D is sunlight."],"memoryTip":"D से ''धूप'' (Dhup) न मिले तो हड्डियां कमज़ोर (रिकेट्स)।","memoryTipEn":"Rickets breaks bones like weak ''Pickets''.","explanationHi":"कैल्शियम और फास्फोरस के अवशोषण के लिए विटामिन D आवश्यक है, जिसकी कमी से हड्डियां मुड़ जाती हैं।","explanationEn":"Vitamin D is essential for absorbing calcium and phosphorus; its deficiency causes bones to bend."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rkxPuOERFToOb621PZNKB', 'General Science', 'ध्वनि (Sound) किस माध्यम में यात्रा नहीं कर सकती?', 'In which medium can sound not travel?', 'निर्वात (Vacuum)', 'Vacuum', 100, 0, '{"facts":["ध्वनि सबसे तेज ठोस (स्टील) में चलती है; यह एक यांत्रिक तरंग (Mechanical wave) है।"],"factsEn":["Sound travels fastest in solids (steel); It is a mechanical wave."],"memoryTip":"जहाँ कुछ नहीं (निर्वात), वहाँ कोई आवाज़ नहीं।","memoryTipEn":"No matter, no chatter (sound).","explanationHi":"ध्वनि तरंगों को आगे बढ़ने के लिए कणों (ठोस, द्रव या गैस) के कंपन की आवश्यकता होती है, जो निर्वात में नहीं होते।","explanationEn":"Sound waves require the vibration of particles (solid, liquid, or gas) to propagate, which are absent in a vacuum."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('EENhCGr3IFPhFaWB2Psuk', 'General Science', 'कमरे के तापमान पर तरल अवस्था में पाई जाने वाली एकमात्र धातु कौन सी है?', 'Which is the only metal found in liquid state at room temperature?', 'पारा (Mercury)', 'Mercury', 100, 0, '{"facts":["प्रतीक ''Hg'' है; इसका उपयोग थर्मामीटर में किया जाता है। (ब्रोमीन एकमात्र तरल अधातु है)"],"factsEn":["Symbol is ''Hg''; Used in thermometers. (Bromine is the only liquid non-metal)."],"memoryTip":"तापमान बढ़ते ही धातु का ''पारा'' पिघल गया।","memoryTipEn":"Mercury flows like quicksilver.","explanationHi":"पारा अन्य धातुओं के साथ मिलकर ''अमलगम'' (Amalgam) बनाता है और यह ऊष्मा का अच्छा सुचालक है।","explanationEn":"Mercury forms ''Amalgams'' with other metals and is a good conductor of heat."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('cKiSYvKjETSVzMWY-bFxz', 'General Science', 'एक वयस्क मनुष्य के शरीर में कुल कितनी हड्डियाँ होती हैं?', 'What is the total number of bones in an adult human body?', '206', '206', 100, 0, '{"facts":["नवजात शिशु में लगभग 300 हड्डियाँ होती हैं, जो उम्र के साथ जुड़ जाती हैं।"],"factsEn":["A newborn baby has about 300 bones, which fuse with age."],"memoryTip":"206 हड्डी तोड़कर रख दूँगा! (फिल्मों का डायलॉग)।","memoryTipEn":"206 bones to build a human frame.","explanationHi":"सबसे बड़ी हड्डी फीमर (जांघ) है और सबसे छोटी हड्डी स्टेपीज़ (कान) है।","explanationEn":"The largest bone is Femur (thigh) and the smallest is Stapes (ear)."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('UHKs8iDryQ_UEj2mrEpCi', 'General Science', 'ग्लोबल वार्मिंग (हरित गृह प्रभाव) के लिए मुख्य रूप से कौन सी गैस जिम्मेदार है?', 'Which gas is primarily responsible for Global Warming (Greenhouse Effect)?', 'कार्बन डाइऑक्साइड (CO₂)', 'Carbon Dioxide (CO₂)', 100, 0, '{"facts":["अन्य ग्रीनहाउस गैसें मीथेन (CH4), जलवाष्प और नाइट्रस ऑक्साइड हैं।"],"factsEn":["Other greenhouse gases are Methane (CH4), water vapor, and Nitrous Oxide."],"memoryTip":"CO2 पृथ्वी को कंबल की तरह ओढ़कर गर्म कर रही है।","memoryTipEn":"CO2 traps heat like a cozy blanket.","explanationHi":"जीवाश्म ईंधन के जलने और वनों की कटाई से वायुमंडल में CO2 की मात्रा तेजी से बढ़ी है, जिससे पृथ्वी का तापमान बढ़ रहा है।","explanationEn":"Burning fossil fuels and deforestation have rapidly increased CO2 levels, raising Earth''s temperature."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Jgjawn10fL1CQGSpjjyZm', 'Polity', 'संविधान के किस अनुच्छेद में ''कानून के समक्ष समानता'' का अधिकार है?', 'Which Article of the Constitution deals with ''Equality before Law''?', 'अनुच्छेद 14', 'Article 14', 100, 0, '{"facts":["यह एक मौलिक अधिकार है; इसका विचार ब्रिटेन से लिया गया है।"],"factsEn":["It is a Fundamental Right; The concept is taken from Britain."],"memoryTip":"14 (एक-चार) - एक ही कानून चारों तरफ समान है।","memoryTipEn":"14 is uniform for all.","explanationHi":"अनुच्छेद 14 सुनिश्चित करता है कि राज्य किसी भी व्यक्ति को कानून के समक्ष समानता या भारत के क्षेत्र में कानूनों के समान संरक्षण से वंचित नहीं करेगा।","explanationEn":"Article 14 ensures that the State shall not deny to any person equality before the law or the equal protection of the laws within India."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('gLWQfx5Ny2Y9TUoM4RdlQ', 'Polity', 'भारत का ''प्रथम नागरिक'' किसे कहा जाता है?', 'Who is called the ''First Citizen'' of India?', 'राष्ट्रपति (President)', 'President', 100, 0, '{"facts":["राष्ट्रपति सशस्त्र बलों के सर्वोच्च कमांडर (Supreme Commander) भी होते हैं।"],"factsEn":["The President is also the Supreme Commander of the Armed Forces."],"memoryTip":"राष्ट्र का ''पति'' (मुखिया) सबसे पहला व्यक्ति है।","memoryTipEn":"President heads the Nation''s roster.","explanationHi":"प्रोटोकॉल के अनुसार, राष्ट्रपति भारत राज्य के औपचारिक प्रमुख होते हैं और एकता तथा अखंडता के प्रतीक हैं।","explanationEn":"According to protocol, the President is the formal head of the Indian state and a symbol of unity and integrity."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('rTk4gmTUqqe6gvaPyKMFg', 'Polity', 'लोकसभा में सदस्यों की अधिकतम संख्या कितनी हो सकती है?', 'What is the maximum strength of members in the Lok Sabha?', '550', '550', 100, 0, '{"facts":["पहले 552 थी, लेकिन 104वें संशोधन द्वारा 2 एंग्लो-इंडियन सीटों को समाप्त कर दिया गया। वर्तमान संख्या 543 है।"],"factsEn":["Earlier 552, but 2 Anglo-Indian seats were abolished by 104th Amendment. Current strength is 543."],"memoryTip":"पाँच-पाँच-ज़ीरो (550) लोगों की सभा।","memoryTipEn":"550 max voices in the lower house.","explanationHi":"लोकसभा (निचला सदन) के सदस्य सीधे जनता द्वारा चुने जाते हैं। राज्यों से 530 और केंद्र शासित प्रदेशों से 20 सदस्य हो सकते हैं।","explanationEn":"Members of Lok Sabha (Lower House) are directly elected. Max 530 from states and 20 from UTs."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('lclaUIspCRdTQZLbDKRYZ', 'General Knowledge', 'भारत की प्रथम महिला प्रधानमंत्री कौन थीं?', 'Who was the first female Prime Minister of India?', 'इंदिरा गांधी', 'Indira Gandhi', 100, 0, '{"facts":["उन्हें 1971 में भारत रत्न से सम्मानित किया गया था; उन्हें ''आयरन लेडी ऑफ इंडिया'' भी कहा जाता था।"],"factsEn":["Awarded Bharat Ratna in 1971; Also called ''Iron Lady of India''."],"memoryTip":"''इंदिरा'' ही इंडिया की पहली महिला PM बनीं।","memoryTipEn":"Indira led India first among women.","explanationHi":"उन्होंने 1966 से 1977 तक और फिर 1980 से 1984 तक प्रधानमंत्री के रूप में कार्य किया।","explanationEn":"She served as Prime Minister from 1966 to 1977 and again from 1980 to 1984."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('WQi7oB8nIH31-K8G2-OOM', 'General Knowledge', '''भारत का लौह पुरुष'' (Iron Man of India) किसे कहा जाता है?', 'Who is known as the ''Iron Man of India''?', 'सरदार वल्लभभाई पटेल', 'Sardar Vallabhbhai Patel', 100, 0, '{"facts":["वे भारत के पहले उप-प्रधानमंत्री और गृह मंत्री थे; स्टैच्यू ऑफ यूनिटी (गुजरात) उनकी ही मूर्ति है।"],"factsEn":["First Deputy PM and Home Minister of India; Statue of Unity (Gujarat) is his statue."],"memoryTip":"लोहे (Iron) जैसा मजबूत इरादा था पटेल जी का।","memoryTipEn":"Patel''s iron will united India.","explanationHi":"उन्होंने स्वतंत्रता के बाद 562 से अधिक देसी रियासतों (Princely states) को भारत संघ में मिलाने का ऐतिहासिक कार्य किया था।","explanationEn":"He played a historic role in integrating over 562 princely states into the Indian Union after independence."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Zj_KQcLf9jMK-swoHWvB-', 'Polity', 'सर्वोच्च न्यायालय (Supreme Court) के न्यायाधीशों की सेवानिवृत्ति (Retirement) आयु क्या है?', 'What is the retirement age of the judges of the Supreme Court?', '65 वर्ष', '65 Years', 100, 0, '{"facts":["उच्च न्यायालय (High Court) के न्यायाधीशों की सेवानिवृत्ति आयु 62 वर्ष है।"],"factsEn":["Retirement age of High Court judges is 62 years."],"memoryTip":"सुप्रीम (सबसे बड़ा) कोर्ट 65 तक, हाई कोर्ट 62 तक।","memoryTipEn":"Supreme stays longer (65), High stops earlier (62).","explanationHi":"अनुच्छेद 124(2) के अनुसार, सुप्रीम कोर्ट का कोई भी जज 65 वर्ष की आयु पूरी करने तक अपने पद पर बना रहता है।","explanationEn":"As per Article 124(2), a Supreme Court judge holds office until attaining the age of 65 years."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('eNvcCyl2jBxAqDgnWgH_S', 'Polity', 'भारतीय संविधान में ''मौलिक कर्तव्य'' (Fundamental Duties) किस देश से लिए गए हैं?', 'From which country were ''Fundamental Duties'' adopted in the Indian Constitution?', 'रूस (सोवियत संघ / USSR)', 'Russia (USSR)', 100, 0, '{"facts":["इन्हें 42वें संशोधन (1976) द्वारा स्वर्ण सिंह समिति की सिफारिश पर जोड़ा गया; भाग 4A (अनुच्छेद 51A)।"],"factsEn":["Added by 42nd Amendment (1976) on Swaran Singh Committee''s recommendation; Part 4A (Article 51A)."],"memoryTip":"हमारा ''कर्तव्य'' है कि पुराने दोस्त ''रूस'' को न भूलें।","memoryTipEn":"USSR gave us our Duties.","explanationHi":"वर्तमान में संविधान में कुल 11 मौलिक कर्तव्य हैं, जो नागरिकों को उनके राष्ट्रीय दायित्वों की याद दिलाते हैं।","explanationEn":"Currently, there are 11 Fundamental Duties reminding citizens of their national obligations."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('Tc3yvy23VsnlAD8wGjmWf', 'General Knowledge', 'अंतरिक्ष में जाने वाले प्रथम भारतीय कौन थे?', 'Who was the first Indian to go into space?', 'राकेश शर्मा', 'Rakesh Sharma', 100, 0, '{"facts":["उन्होंने 1984 में सोवियत अंतरिक्ष मिशन (T-11) के तहत यात्रा की; उन्होंने कहा था ''सारे जहाँ से अच्छा''।"],"factsEn":["Flew in 1984 under Soviet space mission (T-11); Said ''Sare Jahan Se Achha''."],"memoryTip":"राकेश का ''रॉकेट'' स्पेस में गया।","memoryTipEn":"Rakesh Reached space in a Rocket.","explanationHi":"वे भारतीय वायु सेना के पायलट थे और अंतरिक्ष में जाने वाले 138वें इंसान बने।","explanationEn":"He was an Indian Air Force pilot and became the 138th human to travel into space."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('4AMj0bTGXezspaF95QK7R', 'Polity', 'संविधान सभा द्वारा राष्ट्रगान (जन गण मन) को कब अपनाया गया?', 'When was the National Anthem (Jana Gana Mana) adopted by the Constituent Assembly?', '24 जनवरी 1950', '24 January 1950', 100, 0, '{"facts":["यह रवींद्रनाथ टैगोर द्वारा लिखा गया था; गाने का निर्धारित समय 52 सेकंड है।"],"factsEn":["Written by Rabindranath Tagore; Official playing time is 52 seconds."],"memoryTip":"गणतंत्र दिवस (26 जनवरी) से ठीक 2 दिन पहले राष्ट्रगान तय किया गया।","memoryTipEn":"Adopted 2 days before the Republic was born.","explanationHi":"उसी दिन राष्ट्रगीत (वंदे मातरम) को भी अपनाया गया और डॉ. राजेंद्र प्रसाद को प्रथम राष्ट्रपति चुना गया।","explanationEn":"The National Song (Vande Mataram) was adopted on the same day, and Dr. Rajendra Prasad was elected as the first President."}', 'published', 1777198716, 1777198716);
INSERT INTO "mppolice_one_liner_facts" ("id", "subject_tag", "stem_hi", "stem_en", "answer_hi", "answer_en", "importance_score", "sort_order", "extended_data", "status", "created_at", "updated_at") VALUES ('0WxBYOBWE6yscu-DCoRzq', 'General Knowledge', 'भारत में एक रुपये के नोट पर किसके हस्ताक्षर होते हैं?', 'Who signs the one-rupee note in India?', 'वित्त सचिव (Finance Secretary)', 'Finance Secretary', 100, 0, '{"facts":["बाकी सभी करेंसी नोटों पर RBI गवर्नर के हस्ताक्षर होते हैं।"],"factsEn":["All other currency notes bear the signature of the RBI Governor."],"memoryTip":"एक रुपया सबसे छोटा है, इसलिए वित्त मंत्रालय का ''सचिव'' ही साइन कर देता है।","memoryTipEn":"Only 1 Rupee goes to the Finance Secretary.","explanationHi":"एक रुपये का नोट भारत सरकार के वित्त मंत्रालय द्वारा जारी किया जाता है, न कि रिजर्व बैंक ऑफ इंडिया (RBI) द्वारा।","explanationEn":"The one-rupee note is issued by the Ministry of Finance, Government of India, not by the RBI."}', 'published', 1777198716, 1777198716);
