INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6c4759c9-0c8e-4ac6-a9a8-bbe1a6407853', 'bb6afa7a-2e4d-4b3e-9b2c-6b001440568d', 'History', 'शतपथ और तैत्तिरीय ब्राह्मण यजुर्वेद से संबंधित हैं।', 'Shatapatha and Taittiriya Brahmanas are related to the Yajurveda.', 'Yaju -> Shatapath (100 paths of sacrifice).', 'Yaju -> Shatapath (100 paths of sacrifice).', 'ऐतरेय ऋग्वेद का है, इसे यजुर्वेद से भ्रमित न करें।', 'Do not confuse Aitareya (Rigveda) with Yajurveda texts.', 'medium', 0.8, 0.9, '[{"questionId":"XrsFHw0If0wXCEhbBkuTj"}]', '["Vedic Lit","high-yield"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829238, 1773829238);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4e975f8d-bb70-4d0f-8f7a-89126d4ac86b', 'bb6afa7a-2e4d-4b3e-9b2c-6b001440568d', 'History', 'बृहदारण्यक उपनिषद में याज्ञवल्क्य-गार्गी संवाद है; सांख्य दर्शन ''सत्कार्यवाद'' पर आधारित है।', 'Brihadaranyaka Upanishad contains the Yajnavalkya-Gargi dialogue; Sankhya philosophy is based on Satkaryavada.', 'Big (Brihad) Dialogue; Sankhya = ''Sat'' (True) Numbers.', 'Big (Brihad) Dialogue; Sankhya = ''Sat'' (True) Numbers.', 'सत्कार्यवाद को वेदांत से न जोड़ें, यह कपिल मुनि के सांख्य दर्शन का मूल है।', 'Do not link Satkaryavada to Vedanta, it is the core of Kapil Muni''s Sankhya.', 'medium', 0.85, 0.95, '[{"questionId":"qc3AnoJ2GcQET_1lMBn70"},{"questionId":"YtKogftXOZ-j1JZ0Df6CZ"}]', '["Philosophy","Upanishad","Bouncer"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829239, 1773829239);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('715a0367-c491-4ec7-8c98-34b88b478485', 'e0115c75-499b-4d61-934a-e5486efbc65d', 'History', 'अण्डाल 12 अलवार संतों में एकमात्र महिला थीं; कांची का कैलासनाथर मंदिर पल्लव (राजसिम्हा) शैली का है।', 'Andal was the only female among 12 Alwar saints; Kanchi Kailasanathar temple is of Pallava (Rajasimha) style.', 'Alwar = Vaishnava (Andal is Meera of South). Kanchi = Pallava Power.', 'Alwar = Vaishnava (Andal is Meera of South). Kanchi = Pallava Power.', 'अलवार (विष्णु भक्त) और नयनार (शिव भक्त) में भ्रमित न हों।', 'Do not confuse Alwars (Vishnu) with Nayanars (Shiva).', 'medium', 0.75, 0.85, '[{"questionId":"cVIRcfZOOI-mNRUTwT2XL"},{"questionId":"71kXhuMiMkL0yKsibRLxN"}]', '["Bhakti","Architecture"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829239, 1773829239);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('ed6ca79f-60b2-4fe3-921a-411c9e12688e', 'e0115c75-499b-4d61-934a-e5486efbc65d', 'History', 'मुस्लिम लीग की ''सीधी कार्यवाही'' (16 अगस्त 1946) और सविनय अवज्ञा की शुरुआत (6 अप्रैल 1930)।', 'Muslim League''s Direct Action (16 Aug 1946) and start of Civil Disobedience (6 April 1930).', '1930 Salt, 1946 Action.', '1930 Salt, 1946 Action.', 'सविनय अवज्ञा को 12 मार्च (यात्रा शुरू) से नहीं, बल्कि 6 अप्रैल (कानून टूटने) से शुरू माना जाता है।', 'Civil Disobedience officially starts on April 6 (law broken), not March 12 (march started).', 'medium', 0.9, 0.9, '[{"questionId":"WdvSGmCuIgxNEiwehoJud"},{"questionId":"5S_Tc00VRH0-4Pub8qQ_K"}]', '["Freedom Struggle","Chronology"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829239, 1773829239);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('f37ef33c-5bc3-4d1c-bd68-b0dc62cee406', 'c714ff65-6bc2-482f-bedc-fac9401172cd', 'Geography', 'नीलगिरि पश्चिमी और पूर्वी घाट का मिलन बिंदु है; गोदावरी प्रायद्वीपीय भारत की सबसे लंबी नदी है।', 'Nilgiri is the junction of Western and Eastern Ghats; Godavari is the longest peninsular river.', 'Nilgiri Knot; Godavari = Dakshin Ganga.', 'Nilgiri Knot; Godavari = Dakshin Ganga.', 'कावेरी को ''दक्षिण भारत की गंगा'' कहा जाता है, लेकिन गोदावरी ''दक्षिण गंगा'' है।', 'Kaveri is ''Ganga of South India'', but Godavari is ''Dakshin Ganga''.', 'medium', 0.95, 0.95, '[{"questionId":"AwoWnbr9AaQ5sROWv7MkD"},{"questionId":"Mwb7NpAYkSAUdYv2nR2tk"}]', '["Rivers","Topography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829241, 1773829241);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6c24760f-2463-47ef-a4be-afd3e8cf7ff2', 'c714ff65-6bc2-482f-bedc-fac9401172cd', 'Geography', 'पर्यावरण संरक्षण अधिनियम 1986 में आया; म.प्र. में सर्वाधिक वन क्षेत्र है।', 'EPA passed in 1986; MP has the highest forest cover.', 'Bhopal Gas (1984) -> EPA (1986).', 'Bhopal Gas (1984) -> EPA (1986).', 'वन्यजीव संरक्षण 1972 है, पर्यावरण 1986 है, वन संरक्षण 1980 है।', 'Wildlife is 1972, Environment is 1986, Forest Conservation is 1980.', 'medium', 0.9, 0.9, '[{"questionId":"Mt0E6NLU5gYyFuB5wUoH0"},{"questionId":"-A-w5Z3u63tpOapBd7Mgo"}]', '["Environment Acts","Forest Report"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829241, 1773829241);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('65dd64c9-cc8e-483b-805b-31f5d23f7e72', 'c714ff65-6bc2-482f-bedc-fac9401172cd', 'Geography', 'ओडिशा लौह अयस्क भंडार में शीर्ष पर है; राजस्थान सौर ऊर्जा में और कुडनकुलम परमाणु ऊर्जा में सबसे बड़ा है।', 'Odisha leads in Iron ore reserves; Rajasthan in solar and Kudankulam in nuclear energy.', 'Iron = Odisha, Sun = Rajasthan.', 'Iron = Odisha, Sun = Rajasthan.', 'पवन ऊर्जा में तमिलनाडु/गुजरात शीर्ष पर हैं, सौर में राजस्थान।', 'For wind energy, TN/Gujarat lead, for solar it is Rajasthan.', 'medium', 0.8, 0.85, '[{"questionId":"iDJWpzAhcUtHa1Sj5cssU"},{"questionId":"_H_rpfVdnYO5gf2JFwn5i"},{"questionId":"ZIe8Jocd7tuyjKvHQPG4P"}]', '["Minerals","Energy"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829241, 1773829241);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('901e9ec4-ca25-4cf1-9fc9-2839eafa6bf5', 'd952ff39-690b-4542-8522-339f8df9ff5f', 'Economy', 'भारत दूध, दाल और मसाले में विश्व में प्रथम है; म.प्र. दाल उत्पादन में प्रथम है।', 'India is 1st globally in Milk, Pulses, and Spices; MP is 1st in Pulses.', 'Milk, Masala, Moong -> India #1.', 'Milk, Masala, Moong -> India #1.', 'चावल और गेहूं में भारत चीन के बाद दूसरे स्थान पर है।', 'India is 2nd in Rice and Wheat after China.', 'medium', 0.85, 0.9, '[{"questionId":"iXM5Z24qNs0cvGNA5iIzl"},{"questionId":"_crgF7V7O-tMWgF3XbPCx"}]', '["Agriculture Rank","Production"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829242, 1773829242);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('beb38bf0-642b-4869-8b2b-1cda464c09b3', 'd952ff39-690b-4542-8522-339f8df9ff5f', 'Economy', 'दशकीय जनसंख्या वृद्धि (2011): भारत में मेघालय सर्वाधिक, म.प्र. में इंदौर सर्वाधिक।', 'Decadal Population Growth (2011): Meghalaya highest in India, Indore highest in MP.', 'Megha grew fast in India; Indore grew fast in MP.', 'Megha grew fast in India; Indore grew fast in MP.', 'सबसे कम वृद्धि नागालैंड (नकारात्मक) में हुई थी, इसे न भूलें।', 'Do not forget Nagaland had negative growth rate.', 'medium', 0.9, 0.95, '[{"questionId":"iQBBeAxyTmpeXeoAPdMzS"},{"questionId":"zdJC51KxDuqba3FkQRF01"}]', '["Census 2011","Demographics"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829242, 1773829242);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('113be470-d956-45bd-a31a-9e379a310c50', 'd952ff39-690b-4542-8522-339f8df9ff5f', 'Economy', 'मौद्रिक नीति का लक्ष्य मूल्य स्थिरता (Inflation Targeting) है; सेवा निर्यात व्यापार घाटे को कम करता है।', 'Monetary policy aims at price stability; Services export reduces the trade deficit.', 'RBI controls inflation. IT saves the trade deficit.', 'RBI controls inflation. IT saves the trade deficit.', 'राजकोषीय नीति सरकार बनाती है, मौद्रिक नीति RBI (MPC) बनाती है।', 'Fiscal policy is by Govt, Monetary policy is by RBI (MPC).', 'medium', 0.8, 0.85, '[{"questionId":"UT3MRGvwRotFtc2HPNUlW"},{"questionId":"q1m6QzM5TjKph9iCvKn0N"}]', '["Macroeconomy","Trade"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829242, 1773829242);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9d3f24e4-7bb2-4316-86cd-d5ae6441d8d7', '8909052c-55f2-4a07-afcf-e71d4437c421', 'ICT', 'ट्रोजन हॉर्स एक वैध सॉफ्टवेयर होने का नाटक करता है; CIA Triad में C का अर्थ गोपनीयता (Confidentiality) है।', 'Trojan Horse pretends to be legit software; C in CIA Triad stands for Confidentiality.', 'Trojan = Fake Gift. CIA = Confidentiality, Integrity, Availability.', 'Trojan = Fake Gift. CIA = Confidentiality, Integrity, Availability.', 'ट्रोजन खुद की नकल (replicate) नहीं करता, जबकि वर्म (Worm) करता है।', 'Trojans do not replicate themselves, whereas Worms do.', 'medium', 0.9, 0.95, '[{"questionId":"b_0yh2yeFqiUZ_GjwneUb"},{"questionId":"vX0-ytZCE77hWqA47o7L6"}]', '["Cyber Security","Malware"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829243, 1773829243);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7442ca59-d423-40c4-941d-5a5d788f7dc5', '8909052c-55f2-4a07-afcf-e71d4437c421', 'ICT', 'नेटवर्क की विफलता से उबरने की क्षमता ''लचीलापन'' (Resilience) कहलाती है; MS-DOS एक CUI ऑपरेटिंग सिस्टम है।', 'Network''s ability to recover from faults is Resilience; MS-DOS is a CUI operating system.', 'Resilience = Bounce Back. DOS = Command Line.', 'Resilience = Bounce Back. DOS = Command Line.', 'Windows एक GUI है, जबकि DOS एक CUI (Character User Interface) है।', 'Windows is GUI, while DOS is CUI (Character User Interface).', 'medium', 0.7, 0.8, '[{"questionId":"UJrKeMVg8yFw9otZ0vBHJ"},{"questionId":"vztddKg_2EMRziJEyKpHY"}]', '["OS Basics","Networking"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829243, 1773829243);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('21302b30-36b2-4de7-995d-323da715cc26', '8909052c-55f2-4a07-afcf-e71d4437c421', 'ICT', 'गार्टनर के ई-गवर्नेंस मॉडल के 4 चरण: Information -> Interaction -> Transaction -> Transformation.', '4 stages of Gartner''s E-Gov model: Information -> Interaction -> Transaction -> Transformation.', 'I-I-T-T (Info, Interact, Transact, Transform).', 'I-I-T-T (Info, Interact, Transact, Transform).', 'Interaction और Transaction का क्रम न भूलें। पहले बातचीत, फिर लेन-देन।', 'Do not swap Interaction and Transaction. Talk first, pay later.', 'medium', 0.75, 0.85, '[{"questionId":"7_xUv5xLdk_BkOyX0RjV5"}]', '["E-Governance","Frameworks"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829243, 1773829243);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5f924cb5-c112-4d9a-ac54-aabcc55ba1fd', 'e40ed15c-5c62-4c5e-82ef-2917fa18cd09', 'MP GK', 'उचेहरा (सतना) कांसा (Bronze) शिल्प ''बटलोही'' के लिए प्रसिद्ध है; मनसुखा बघेलखंड का लोक नाट्य है।', 'Uchehara (Satna) is famous for Bronze craft ''Batlohi''; Mansukha is a folk drama of Baghelkhand.', 'Mansukha in Baghelkhand. Uchehara shines in Bronze.', 'Mansukha in Baghelkhand. Uchehara shines in Bronze.', 'मनसुखा को बुंदेलखंड से न जोड़ें, यह बघेलखंड का रासलीला रूप है।', 'Do not link Mansukha to Bundelkhand, it is Baghelkhand''s Rasleela variant.', 'medium', 0.85, 0.9, '[{"questionId":"GzLk64yH30vGvJz0fRVwc"},{"questionId":"nE04MoQtZhDo2nyYAjAyn"}]', '["Folk Art","Crafts"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829244, 1773829244);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('ba954e3d-4d0d-4f71-9cac-95bcdf9c42c8', 'e40ed15c-5c62-4c5e-82ef-2917fa18cd09', 'MP GK', 'खजुराहो का मातंगेश्वर मंदिर एकमात्र सक्रिय पूजा स्थल है; प्रबंधचिन्तामणि मेरुतुंग द्वारा लिखी गई (राजशेखर नहीं)।', 'Matangeshwar temple in Khajuraho is the only active worship site; Prabandhachintamani is by Merutunga.', 'Matanga = Shivling worship active. Meru = Prabandha.', 'Matanga = Shivling worship active. Meru = Prabandha.', 'कंदरिया महादेव सबसे बड़ा है, लेकिन पूजा मातंगेश्वर में होती है।', 'Kandariya Mahadev is largest, but worship happens in Matangeshwar.', 'medium', 0.8, 0.85, '[{"questionId":"rDfgHuMrDbyA-tSATmvyv"},{"questionId":"zDqpbWJhaXBH4kLwTkuUN"}]', '["Temples","Literature"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829244, 1773829244);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('f2d78025-f715-418d-a582-e60abb6345b3', 'e40ed15c-5c62-4c5e-82ef-2917fa18cd09', 'MP GK', '2023 का किशोर कुमार सम्मान राजकुमार हिरानी को मिला; म.प्र. बजट में शिक्षा के लिए ~15-16% आवंटित किया गया।', '2023 Kishore Kumar Samman to Rajkumar Hirani; MP Budget allocated ~15-16% for Education.', 'Hirani got Kishore Award. 15% for Education.', 'Hirani got Kishore Award. 15% for Education.', 'राष्ट्रीय तानसेन और कालिदास सम्मान के विजेताओं को भी अपडेट रखें।', 'Keep updated on Tansen and Kalidas Samman winners as well.', 'medium', 0.8, 0.8, '[{"questionId":"TsCbUNbP_0DjZKnGByNOS"},{"questionId":"_LGiMGqnmgvqowbopuTSj"}]', '["Awards","Budget"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829244, 1773829244);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('759a6346-72bd-4315-a0f9-0bf9e85fd6d6', '5f0f2309-45bd-43ad-add5-63b1920762fb', 'Current Affairs', 'चक्रवात फेंगल ने तमिलनाडु को प्रभावित किया; ''युद्ध अभ्यास'' भारत और अमेरिका के बीच होता है।', 'Cyclone Fengal hit Tamil Nadu; ''Yudh Abhyas'' is between India and USA.', 'Fengal on TN coast. Yudh with US.', 'Fengal on TN coast. Yudh with US.', 'भारत-थाईलैंड अभ्यास ''मैत्री'' है, ''युद्ध अभ्यास'' नहीं।', 'India-Thailand is ''Maitree'', not ''Yudh Abhyas''.', 'medium', 0.85, 0.9, '[{"questionId":"h7k7Sw1REYRV95LEzknAY"},{"questionId":"biX6h62CUh-iAUQxN-9MJ"}]', '["Disaster","Defence"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829245, 1773829245);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('05ae5ef2-ccdc-48e2-968d-3843b138746b', '5f0f2309-45bd-43ad-add5-63b1920762fb', 'Current Affairs', 'सिकल सेल एनीमिया उन्मूलन का लक्ष्य 2047 है; RKSK कार्यक्रम किशोरों (10-19 वर्ष) के लिए है।', 'Sickle Cell Anemia elimination target is 2047; RKSK program is for adolescents (10-19 yrs).', '100 years of independence (2047) = No Sickle Cell.', '100 years of independence (2047) = No Sickle Cell.', 'सिकल सेल मिशन म.प्र. के शहडोल से लॉन्च हुआ था, जो इसे MPPSC के लिए अति-महत्वपूर्ण बनाता है।', 'Sickle Cell mission launched from Shahdol, MP, making it hyper-relevant for MPPSC.', 'medium', 0.9, 0.95, '[{"questionId":"clDxi8tvDnj_LStzcTjpt"},{"questionId":"nralgV_MLpm6NSbxDPpxq"}]', '["Health Schemes","Targets"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829245, 1773829245);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('23028f55-e8f0-4925-a85e-f28391492949', '5f0f2309-45bd-43ad-add5-63b1920762fb', 'Current Affairs', 'SDG इंडिया इंडेक्स 3.0 में MP का स्कोर 62 था; NDRF अकादमी नागपुर में स्थित है।', 'MP scored 62 in SDG India Index 3.0; NDRF Academy is in Nagpur.', 'MP hits a Six-Two (62) in SDG.', 'MP hits a Six-Two (62) in SDG.', 'केरल SDG इंडेक्स में हमेशा शीर्ष पर रहता है।', 'Kerala consistently tops the SDG index.', 'medium', 0.7, 0.8, '[{"questionId":"r4Tgo8Qbgy7nQzMVGqEe3"},{"questionId":"YNWRZHx7cCf0NkRjz2rKS"}]', '["Index","Institutes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829245, 1773829245);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5a690d9b-dd4c-451e-8f2c-178709dfd545', 'f2ecd569-5c7e-4c80-ab1b-ea207bc940ae', 'History', 'शतपथ और तैत्तिरीय ब्राह्मण यजुर्वेद से संबंधित हैं। बृहदारण्यक उपनिषद में याज्ञवल्क्य-गार्गी का प्रसिद्ध संवाद है।', 'Shatapatha and Taittiriya Brahmanas belong to Yajurveda. Brihadaranyaka Upanishad contains the famous Yajnavalkya-Gargi dialogue.', 'यजु (Yaju) -> शतपथ (100 Paths). बृहद (Big) -> बड़ा संवाद (Yajnavalkya-Gargi).', 'Yaju -> Shatapath (100 Paths). Brihad (Big) -> Big Dialogue (Yajnavalkya-Gargi).', 'ऐतरेय को यजुर्वेद का न मानें, वह ऋग्वेद का है। गार्गी संवाद को मुंडकोपनिषद (सत्यमेव जयते) से भ्रमित न करें।', 'Do not confuse Aitareya with Yajurveda; it''s from Rigveda. Do not confuse Gargi dialogue with Mundaka (Satyameva Jayate).', 'medium', 0.9, 0.95, '[{"questionId":"XrsFHw0If0wXCEhbBkuTj"},{"questionId":"qc3AnoJ2GcQET_1lMBn70"}]', '["Vedic Literature","Upanishads","High-Yield"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829277, 1773829277);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('086af034-e116-4c24-964b-6194e2e7f782', 'f2ecd569-5c7e-4c80-ab1b-ea207bc940ae', 'History', '''सत्कार्यवाद'' सांख्य दर्शन (कपिल मुनि) का मूल सिद्धांत है। गृहस्थ आश्रम में पंच महायज्ञ अनिवार्य थे।', '''Satkaryavada'' is the core principle of Sankhya Philosophy (Kapil Muni). Pancha Mahayajnas were mandatory in the Grihastha Ashrama.', 'सांख्य (Sankhya) = सत्य (Sat/Satkaryavada). गृहस्थ (Grihastha) = महायज्ञ (Mahayajna).', 'Sankhya = Sat (True/Satkaryavada). Grihastha = Mahayajna.', 'सत्कार्यवाद को वेदांत या न्याय दर्शन का सिद्धांत मानने की गलती न करें।', 'Do not mistakenly attribute Satkaryavada to Vedanta or Nyaya philosophy.', 'medium', 0.85, 0.9, '[{"questionId":"YtKogftXOZ-j1JZ0Df6CZ"},{"questionId":"K4C8gwSIh2i8dDR5NH4t9"}]', '["Indian Philosophy","Ancient Culture"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829278, 1773829278);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c12cceaa-3b9c-4591-ab00-61edb66493d7', 'f2ecd569-5c7e-4c80-ab1b-ea207bc940ae', 'History', 'अण्डाल 12 वैष्णव अलवार संतों में एकमात्र महिला साध्वी थीं (दक्षिण की मीरा)। कांची का कैलासनाथर मंदिर पल्लव (राजसिम्हा) शैली का है।', 'Andal was the only female among the 12 Vaishnava Alvar saints (Meera of the South). Kanchi Kailasanathar temple belongs to the Pallava (Rajasimha) style.', 'अलवार (Alvar) = अण्डाल (Andal). कांची (Kanchi) = पल्लव (Pallava).', 'Alvar = Andal. Kanchi = Pallava.', 'नयनार (शैव संत) और अलवार (वैष्णव संत) के बीच स्पष्ट अंतर याद रखें। अण्डाल अलवार थीं।', 'Remember the clear distinction between Nayanars (Shaiva) and Alvars (Vaishnava). Andal was an Alvar.', 'medium', 0.88, 0.92, '[{"questionId":"cVIRcfZOOI-mNRUTwT2XL"},{"questionId":"71kXhuMiMkL0yKsibRLxN"}]', '["Bhakti Movement","Temple Architecture"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829278, 1773829278);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('660db8c2-c460-417f-81b2-552e2fcc6c61', 'f2ecd569-5c7e-4c80-ab1b-ea207bc940ae', 'History', 'मुस्लिम लीग की ''सीधी कार्यवाही'' (Direct Action) 16 अगस्त 1946 को हुई। सविनय अवज्ञा आंदोलन दांडी में नमक कानून टूटने (6 अप्रैल 1930) से शुरू हुआ।', 'Muslim League''s ''Direct Action'' was on 16 August 1946. Civil Disobedience Movement started with breaking the salt law at Dandi (6 April 1930).', '30 में नमक (Salt in 30), 46 में एक्शन (Action in 46).', 'Salt in 30, Action in 46.', 'सविनय अवज्ञा की आधिकारिक शुरुआत 12 मार्च (यात्रा प्रारंभ) नहीं, बल्कि 6 अप्रैल है।', 'The official start of Civil Disobedience is April 6, not March 12 (start of the march).', 'medium', 0.95, 0.96, '[{"questionId":"WdvSGmCuIgxNEiwehoJud"},{"questionId":"5S_Tc00VRH0-4Pub8qQ_K"}]', '["Modern History","Chronology"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829278, 1773829278);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a8f18369-6d67-41a9-bd17-dc45f897d862', 'f2702d55-8ec4-4fc6-94e0-92055b20cfe2', 'Geography', 'नीलगिरि पहाड़ियाँ पश्चिमी और पूर्वी घाट का मिलन स्थल हैं। गोदावरी (1465 किमी) प्रायद्वीपीय भारत की सबसे लंबी नदी है।', 'Nilgiri Hills act as the junction of Western and Eastern Ghats. Godavari (1465 km) is the longest peninsular river.', 'नीलगिरि गांठ (Nilgiri Knot) है। गोदावरी = दक्षिण गंगा।', 'Nilgiri is the Knot. Godavari = Dakshin Ganga.', 'कावेरी को ''दक्षिण भारत की गंगा'' कहा जाता है, गोदावरी को ''दक्षिण गंगा'' (Dakshin Ganga) कहा जाता है।', 'Kaveri is ''Ganga of South India'', Godavari is ''Dakshin Ganga'' or ''Vridha Ganga''.', 'medium', 0.95, 0.94, '[{"questionId":"AwoWnbr9AaQ5sROWv7MkD"},{"questionId":"Mwb7NpAYkSAUdYv2nR2tk"}]', '["Topography","Rivers"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829279, 1773829279);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0c4b257a-81eb-4bfa-8510-c02726fdce25', 'f2702d55-8ec4-4fc6-94e0-92055b20cfe2', 'Geography', 'दक्षिणी दोलन (Southern Oscillation) उष्णकटिबंधीय प्रशांत और हिंद महासागर के बीच वायुमंडलीय दबाव का उतार-चढ़ाव है।', 'Southern Oscillation is the fluctuation of atmospheric pressure between the tropical Pacific and Indian Oceans.', 'ENSO = El Nino (Ocean temp) + Southern Oscillation (Air Pressure).', 'ENSO = El Nino (Ocean temp) + Southern Oscillation (Air Pressure).', 'अल नीनो समुद्र के तापमान से संबंधित है, जबकि ''दक्षिणी दोलन'' वायुमंडलीय दबाव (Atmospheric Pressure) से संबंधित है।', 'El Nino relates to ocean temperature, whereas ''Southern Oscillation'' relates to atmospheric pressure.', 'medium', 0.8, 0.88, '[{"questionId":"UNWRAkUjGBU-OqdtVLRbZ"}]', '["Climate","Monsoon"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829279, 1773829279);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('258deed6-26d6-4850-b983-94f1e2619d2d', 'f2702d55-8ec4-4fc6-94e0-92055b20cfe2', 'Geography', 'पर्यावरण संरक्षण अधिनियम 1986 में (भोपाल गैस त्रासदी के बाद) पारित हुआ। जैव विविधता संशोधन अधिनियम 3 अगस्त 2023 को राजपत्रित हुआ।', 'Environment Protection Act was passed in 1986 (post Bhopal Gas Tragedy). Biodiversity Amendment Act was gazetted on Aug 3, 2023.', '84 में गैस, 86 में छाता (Umbrella Law - EPA).', 'Gas in 84, Umbrella Law (EPA) in 86.', 'वन्यजीव संरक्षण 1972 है, जल अधिनियम 1974 है, वन संरक्षण 1980 है, पर्यावरण 1986 है। क्रम याद रखें।', 'Wildlife is 1972, Water is 1974, Forest Conservation is 1980, Environment is 1986. Remember the sequence.', 'medium', 0.9, 0.95, '[{"questionId":"Mt0E6NLU5gYyFuB5wUoH0"},{"questionId":"PVCvC7GBZTMCbvY6-m0fj"}]', '["Environment Acts","Ecology"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829279, 1773829279);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('40fe7555-eb1e-4cad-99fa-9bd1e0135779', 'f2702d55-8ec4-4fc6-94e0-92055b20cfe2', 'Geography', 'लौह अयस्क भंडार में ओडिशा प्रथम है। सौर ऊर्जा क्षमता में राजस्थान और परमाणु ऊर्जा (कुडनकुलम 2000 MW) में तमिलनाडु शीर्ष पर हैं।', 'Odisha is 1st in Iron ore reserves. Rajasthan tops in Solar energy, and Tamil Nadu in Nuclear energy (Kudankulam 2000 MW).', 'लोहा (Iron) = ओडिशा। सूर्य (Sun) = राजस्थान। अणु (Nuclear) = कुडनकुलम (TN)।', 'Iron = Odisha. Sun = Rajasthan. Nuclear = Kudankulam (TN).', 'भंडार (Reserves) और उत्पादन (Production) में अंतर होता है, हालांकि लौह अयस्क में ओडिशा दोनों में शीर्ष पर है। पवन ऊर्जा में तमिलनाडु/गुजरात सबसे आगे हैं।', 'There is a difference between Reserves and Production, though Odisha tops both for Iron ore. For wind, TN/Gujarat lead.', 'medium', 0.88, 0.92, '[{"questionId":"iDJWpzAhcUtHa1Sj5cssU"},{"questionId":"_H_rpfVdnYO5gf2JFwn5i"},{"questionId":"ZIe8Jocd7tuyjKvHQPG4P"}]', '["Minerals","Energy Resources"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829279, 1773829279);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0c0c9ee7-ae38-4594-9f78-9dbdf66d8523', 'f2702d55-8ec4-4fc6-94e0-92055b20cfe2', 'Geography', 'पारिस्थितिक अनुक्रमण (Ecological Succession) में क्रमिक परिवर्तन के व्यक्तिगत चरण को ''सीयर'' (Sere) कहा जाता है। 2021 रिपोर्ट अनुसार म.प्र. में सर्वाधिक वन क्षेत्र है।', 'Individual stages of sequence change in Ecological Succession are called ''Sere''. MP has highest forest cover as per ISFR 2021.', 'Sere = Series of Steps. MP = Max Forest Area.', 'Sere = Series of Steps. MP = Max Forest Area.', 'सर्वाधिक वन ''क्षेत्रफल'' (Area) में म.प्र. है, लेकिन ''प्रतिशत'' (Percentage) में मिजोरम है।', 'Highest forest ''Area'' is MP, but highest ''Percentage'' is Mizoram.', 'medium', 0.85, 0.9, '[{"questionId":"vtrlWMp5TIdzbqtJ6jela"},{"questionId":"-A-w5Z3u63tpOapBd7Mgo"}]', '["Forest Report","Environment Concepts"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829279, 1773829279);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7381bed9-621a-48be-b5ca-074487719256', 'a4142d4d-bd76-492a-906a-0f5f29ac41bb', 'Economy', 'RBI की मौद्रिक नीति का प्राथमिक उद्देश्य मूल्य स्थिरता (Inflation Targeting) बनाए रखना है। भारत का सेवा निर्यात व्यापार घाटे (Trade Deficit) को संतुलित करता है।', 'The primary objective of RBI''s Monetary Policy is price stability (Inflation Targeting). India''s services export balances the Trade Deficit.', 'RBI = Inflation Control. IT Sector = Saves Trade Deficit.', 'RBI = Inflation Control. IT Sector = Saves Trade Deficit.', 'कर और सरकारी खर्च ''राजकोषीय नीति'' (Fiscal Policy) के भाग हैं (सरकार द्वारा), जबकि ब्याज दरें ''मौद्रिक नीति'' (RBI) का हिस्सा हैं।', 'Taxes and govt spending are ''Fiscal Policy'' (by Govt), while interest rates are ''Monetary Policy'' (by RBI).', 'medium', 0.85, 0.95, '[{"questionId":"UT3MRGvwRotFtc2HPNUlW"},{"questionId":"q1m6QzM5TjKph9iCvKn0N"}]', '["Macroeconomics","RBI","Foreign Trade"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829280, 1773829280);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('95db2b39-40d6-4e8b-92ab-b43ea466e846', 'a4142d4d-bd76-492a-906a-0f5f29ac41bb', 'Economy', 'जनगणना 2011: मेघालय में भारत की सर्वाधिक दशकीय वृद्धि दर (27.9%) रही। म.प्र. में इंदौर जिले की वृद्धि दर सर्वाधिक (32.9%) थी।', 'Census 2011: Meghalaya had highest decadal growth in India (27.9%). Indore district had highest growth in MP (32.9%).', 'बादल तेजी से बढ़े (Meghalaya grew fast). इंदौर म.प्र. का ग्रोथ इंजन है।', 'Clouds grew fast (Meghalaya). Indore is MP''s growth engine.', 'भारत में सबसे कम दशकीय वृद्धि नागालैंड (-0.6%, नकारात्मक) थी। म.प्र. में सबसे कम अनूपपुर में थी।', 'Lowest decadal growth in India was Nagaland (-0.6%, negative). Lowest in MP was Anuppur.', 'medium', 0.98, 0.98, '[{"questionId":"iQBBeAxyTmpeXeoAPdMzS"},{"questionId":"zdJC51KxDuqba3FkQRF01"}]', '["Census 2011","Demographics"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829280, 1773829280);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3a8bb6b1-5962-4674-9572-8d65ba5f66f7', 'a4142d4d-bd76-492a-906a-0f5f29ac41bb', 'Economy', 'भारत दूध, दाल और मसालों में विश्व में #1 है (गेहूं/चावल में #2)। म.प्र. क्षेत्रफल में दूसरा सबसे बड़ा राज्य है और दाल उत्पादन में प्रथम है। गुजरात पूंजी गहनता (Capital Intensity) में प्रथम है।', 'India is #1 globally in Milk, Pulses, and Spices (#2 in Wheat/Rice). MP is 2nd largest in area and 1st in Pulses. Gujarat is 1st in Capital Intensity.', '3M: Milk, Masala, Moong -> India #1. MP = Pulses Bowl. Gujarat = Capital & Industries.', '3M: Milk, Masala, Moong -> India #1. MP = Pulses Bowl. Gujarat = Capital & Industries.', 'पूंजी गहनता का अर्थ कुल उत्पादन नहीं है; इसका अर्थ है प्रति श्रमिक कितनी मशीनरी/पूंजी का उपयोग हो रहा है (रिफाइनरी के कारण गुजरात शीर्ष पर)।', 'Capital intensity doesn''t mean total output; it means machinery/capital used per worker (Gujarat leads due to refineries).', 'medium', 0.9, 0.9, '[{"questionId":"iXM5Z24qNs0cvGNA5iIzl"},{"questionId":"_crgF7V7O-tMWgF3XbPCx"},{"questionId":"G4Y3xvUZ8oRTfzcPgM4Gs"}]', '["Agriculture Ranks","Economy Ranks"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829280, 1773829280);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4a72707f-f9a9-4bbf-a1ce-a97a8583321b', '714523bd-619e-4ff6-962c-718e14d4fa5f', 'ICT', 'ट्रोजन हॉर्स एक ऐसा मैलवेयर है जो वैध/उपयोगी सॉफ्टवेयर होने का नाटक करता है। CIA Triad में ''C'' का अर्थ गोपनीयता (Confidentiality - अवैध पहुँच रोकना) है।', 'Trojan Horse is malware disguised as legitimate/useful software. ''C'' in CIA Triad stands for Confidentiality (preventing unauthorized access).', 'ट्रोजन = लकड़ी का नकली घोड़ा (धोखा)। CIA = Confidentiality, Integrity, Availability.', 'Trojan = Fake Wooden Horse (Deception). CIA = Confidentiality, Integrity, Availability.', 'वर्म (Worm) खुद की नकल करके नेटवर्क पर फैलता है, लेकिन ट्रोजन हॉर्स खुद की नकल (replicate) नहीं करता।', 'Worms self-replicate over a network, but Trojan Horses do NOT self-replicate.', 'medium', 0.95, 0.98, '[{"questionId":"b_0yh2yeFqiUZ_GjwneUb"},{"questionId":"vX0-ytZCE77hWqA47o7L6"}]', '["Cyber Security","Malware Types"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829281, 1773829281);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('132fb889-749f-463e-8ffb-f9c69be505dd', '714523bd-619e-4ff6-962c-718e14d4fa5f', 'ICT', 'नेटवर्क की त्रुटियों या विफलता के बाद सेवा बहाल करने की क्षमता को ''लचीलापन'' (Resilience) कहते हैं। MS-DOS एक कमांड-लाइन इंटरफेस (CUI) ऑपरेटिंग सिस्टम है।', 'The ability of a network to recover from faults and restore service is ''Resilience''. MS-DOS is a Command-Line Interface (CUI) Operating System.', 'विफलता से वापस आना = Resilience (बाउंस बैक)। DOS = काली स्क्रीन पर टाइपिंग (CUI)।', 'Bouncing back from failure = Resilience. DOS = Typing on black screen (CUI).', 'Windows, Linux (ज्यादातर), Android सभी GUI (ग्राफिकल) हैं। DOS पूरी तरह CUI (कमांड आधारित) है।', 'Windows, Linux (mostly), and Android are GUI (Graphical). DOS is strictly CUI (Command-based).', 'medium', 0.8, 0.85, '[{"questionId":"UJrKeMVg8yFw9otZ0vBHJ"},{"questionId":"vztddKg_2EMRziJEyKpHY"}]', '["Networking","Operating Systems"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829281, 1773829281);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('41531b4c-2e3a-4482-b7c6-06e475b13a8c', '714523bd-619e-4ff6-962c-718e14d4fa5f', 'ICT', 'ई-गवर्नेंस के गार्टनर मॉडल के 4 चरण: Information -> Interaction -> Transaction -> Transformation. राष्ट्रीय ई-गवर्नेस योजना (NeGP) के मिशन मोड प्रोजेक्ट्स के सार-संग्रह को ''सारांश'' कहा जाता है।', '4 stages of Gartner''s E-Gov model: Information -> Interaction -> Transaction -> Transformation. The compendium of Mission Mode Projects under NeGP is called ''Saaransh''.', 'I-I-T-T (Info, Interact, Transact, Transform). सारांश = Summary of Projects.', 'I-I-T-T (Info, Interact, Transact, Transform). Saaransh = Summary of Projects.', 'Interaction और Transaction के क्रम को लेकर धोखा खा सकते हैं। पहले बातचीत (Interaction) होती है, फिर लेनदेन/पैसे का भुगतान (Transaction) होता है।', 'You might confuse the order of Interaction and Transaction. Conversation (Interaction) happens first, followed by payment (Transaction).', 'medium', 0.85, 0.9, '[{"questionId":"7_xUv5xLdk_BkOyX0RjV5"},{"questionId":"414b7lHW_QaTtBBAfY0mc"}]', '["E-Governance","Frameworks"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829281, 1773829281);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e6f29ce9-52c8-4573-afa7-741e5566f21a', '714523bd-619e-4ff6-962c-718e14d4fa5f', 'ICT', 'मार्क जुकरबर्ग ने फेसबुक (2004) की स्थापना की। एडोब फोटोशॉप एक ग्राफिक्स एप्लिकेशन सॉफ्टवेयर है।', 'Mark Zuckerberg founded Facebook (2004). Adobe Photoshop is a graphics application software.', 'Face+Book = Zuckerberg.', 'Face+Book = Zuckerberg.', 'सिस्टम सॉफ्टवेयर (जैसे OS) और एप्लिकेशन सॉफ्टवेयर (जैसे फोटोशॉप, एमएस वर्ड) में अंतर स्पष्ट रखें।', 'Maintain a clear distinction between System Software (like OS) and Application Software (like Photoshop, MS Word).', 'medium', 0.7, 0.75, '[{"questionId":"CcUtcsU5kBNiDJcQnyZTd"},{"questionId":"JuQbO7QQaC_kDz3aM120l"}]', '["Software","Social Media"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829281, 1773829281);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('752a1dd3-3bff-41ed-ac23-badedc348cd7', '919db760-8a8a-4493-82cf-20cb822e206c', 'MP GK', 'सतना जिले का उचेहरा अपने पारंपरिक कांसा (Bronze) शिल्प ''बटलोही'' (खाना पकाने का बर्तन) के लिए प्रसिद्ध है। ''मनसुखा'' बघेलखंड का हास्य-प्रधान लोक नाट्य है।', 'Uchehara in Satna district is famous for its traditional Bronze craft ''Batlohi'' (cooking vessel). ''Mansukha'' is a comic folk drama of Baghelkhand.', 'उचेहरा का कांसा (Uchehara Bronze). मनसुखा = बघेलखंड (Mansukha in Baghelkhand).', 'Uchehara Bronze. Mansukha in Baghelkhand.', 'मनसुखा को बुंदेलखंड या मालवा से न जोड़ें, यह शुद्ध बघेलखंडी रासलीला रूप है।', 'Do not link Mansukha to Bundelkhand or Malwa; it is a pure Baghelkhandi Rasleela variant.', 'medium', 0.85, 0.95, '[{"questionId":"GzLk64yH30vGvJz0fRVwc"},{"questionId":"nE04MoQtZhDo2nyYAjAyn"}]', '["Folk Art","Local Crafts","GI Tags related"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829282, 1773829282);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b48b9594-d78f-41c4-8f6e-2825bd62adf0', '919db760-8a8a-4493-82cf-20cb822e206c', 'MP GK', 'खजुराहो के पश्चिमी समूह में स्थित ''मातंगेश्वर मंदिर'' एकमात्र ऐसा मंदिर है जहाँ आज भी सक्रिय पूजा होती है।', '''Matangeshwar Temple'' in the western group of Khajuraho is the only temple where active worship still takes place.', 'मातंगेश्वर में महादेव की पूजा आज भी होती है।', 'Mahadev is still worshipped in Matangeshwar.', 'खजुराहो का सबसे बड़ा मंदिर कंदरिया महादेव है, लेकिन वहाँ नियमित पूजा नहीं होती। पूजा केवल मातंगेश्वर में होती है।', 'Kandariya Mahadev is the largest temple in Khajuraho, but regular worship does not happen there. It only happens in Matangeshwar.', 'medium', 0.9, 0.9, '[{"questionId":"rDfgHuMrDbyA-tSATmvyv"}]', '["Temples","Tourism"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829282, 1773829282);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('47e2e1f7-b434-444b-904d-7a61b276cd24', '919db760-8a8a-4493-82cf-20cb822e206c', 'MP GK', '2023 का किशोर कुमार सम्मान फिल्म निर्देशक राजकुमार हिरानी को मिला। ''प्रबंधचिन्तामणि'' जैन विद्वान मेरुतुंग द्वारा लिखी गई है (राजशेखर द्वारा नहीं)।', '2023 Kishore Kumar Samman went to film director Rajkumar Hirani. ''Prabandhachintamani'' is written by Jain scholar Merutunga (not Rajashekhara).', 'हिरानी को किशोर अवार्ड (Hirani gets Kishore Award). मेरुतुंग = प्रबंध (Meru = Prabandha).', 'Hirani gets Kishore Award. Meru = Prabandha.', 'राजशेखर की रचनाएँ (बालरामायण, कर्पूरमंजरी) बहुत पूछी जाती हैं, उन्हें मेरुतुंग की रचनाओं से अलग रखें।', 'Rajashekhara''s works (Balaramayana, Karpuramanjari) are frequently asked; keep them distinct from Merutunga''s.', 'medium', 0.8, 0.85, '[{"questionId":"TsCbUNbP_0DjZKnGByNOS"},{"questionId":"zDqpbWJhaXBH4kLwTkuUN"}]', '["Awards","Ancient Literature"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829282, 1773829282);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('52359462-14e9-4eac-a408-5c614489b344', '919db760-8a8a-4493-82cf-20cb822e206c', 'MP GK', 'म.प्र. बजट 2023-24 में शिक्षा के लिए लगभग 15-16% आवंटित किया गया। म.प्र. में प्याज सबसे अधिक उत्पादकता वाली सब्जी है।', 'MP Budget 2023-24 allocated around 15-16% for Education. Onion is the highest productivity vegetable in MP.', '15% for Edu. MP produces massive Onions (Khandwa/Malwa belt).', '15% for Edu. MP produces massive Onions (Khandwa/Malwa belt).', 'म.प्र. प्याज उत्पादन में महाराष्ट्र के बाद दूसरे स्थान पर है, लेकिन राज्य के भीतर इसकी उत्पादकता (प्रति हेक्टेयर) सबसे अधिक है।', 'MP is second after Maharashtra in Onion production, but within the state, its productivity (per hectare) is the highest.', 'medium', 0.7, 0.8, '[{"questionId":"_LGiMGqnmgvqowbopuTSj"},{"questionId":"XI-ypnZFUZn0Nj_CpcBPB"}]', '["MP Budget","MP Agriculture"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829282, 1773829282);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d0bd7a7b-dc4e-41f4-b6c2-686b6bd8c46c', '7b305731-d2cf-4098-afa9-8c23db9c7bec', 'Current Affairs', 'राष्ट्रीय सिकल सेल एनीमिया उन्मूलन मिशन का लक्ष्य 2047 तक इसे खत्म करना है (शहडोल, म.प्र. से लॉन्च)। RKSK कार्यक्रम 10-19 वर्ष के किशोरों के लिए है।', 'National Sickle Cell Anemia Elimination Mission targets elimination by 2047 (launched from Shahdol, MP). RKSK program is for adolescents aged 10-19 years.', 'आजादी के 100 साल (2047) = सिकल सेल मुक्त भारत। किशोर = 10 से 19 (Teenagers).', '100 yrs of Independence (2047) = Sickle Cell Free India. Adolescent = 10 to 19 (Teenagers).', 'सिकल सेल मिशन विशेष रूप से म.प्र. (शहडोल) से लॉन्च हुआ था, जो इसे MPPSC के लिए सबसे महत्वपूर्ण ''राष्ट्रीय'' मिशन बनाता है।', 'Sickle Cell Mission was specifically launched from MP (Shahdol), making it the most critical ''National'' mission for MPPSC.', 'medium', 0.95, 0.98, '[{"questionId":"clDxi8tvDnj_LStzcTjpt"},{"questionId":"nralgV_MLpm6NSbxDPpxq"}]', '["Health Schemes","Targets","MP Connection"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829283, 1773829283);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7f5168ac-bab0-4670-b250-626bf5e1ebd3', '7b305731-d2cf-4098-afa9-8c23db9c7bec', 'Current Affairs', '''युद्ध अभ्यास'' (Yudh Abhyas) भारत और अमेरिका के बीच सैन्य अभ्यास है। चक्रवात ''फेंगल'' (Fengal) ने नवंबर 2024 में तमिलनाडु तट को प्रभावित किया।', '''Yudh Abhyas'' is a military exercise between India and USA. Cyclone ''Fengal'' hit the Tamil Nadu coast in Nov 2024.', 'महाशक्ति (US) के साथ ''युद्ध अभ्यास''। फेंगल का फन (Fang) तमिलनाडु पर।', 'Yudh Abhyas with Superpower (US). Fengal''s Fang on Tamil Nadu.', 'भारत और थाईलैंड के बीच अभ्यास को ''मैत्री'' (Maitree) कहते हैं। ''युद्ध अभ्यास'' केवल अमेरिका के साथ होता है।', 'India-Thailand exercise is ''Maitree''. ''Yudh Abhyas'' is exclusively with USA.', 'medium', 0.9, 0.92, '[{"questionId":"biX6h62CUh-iAUQxN-9MJ"},{"questionId":"h7k7Sw1REYRV95LEzknAY"}]', '["Defence","Disaster Management"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829284, 1773829284);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9d046542-87bd-4f49-a125-8909a1ee4ea2', '7b305731-d2cf-4098-afa9-8c23db9c7bec', 'Current Affairs', 'नीति आयोग के SDG इंडिया इंडेक्स 3.0 (2020-21) में म.प्र. का स्कोर 62 (''Performer'' श्रेणी) था। NDRF अकादमी नागपुर (महाराष्ट्र) में स्थित है।', 'MP scored 62 (''Performer'' category) in NITI Aayog''s SDG India Index 3.0 (2020-21). NDRF Academy is located in Nagpur (Maharashtra).', 'म.प्र. ने SDG में ''सिक्स-टू'' (62) मारा। आपदा का ''नाग'' (Nagpur) -> NDRF.', 'MP hit a ''Six-Two'' (62) in SDG. Disaster Snake (Nagpur) -> NDRF.', 'SDG इंडेक्स में केरल हमेशा शीर्ष पर रहता है। म.प्र. का स्कोर हमेशा 60-65 के बीच रहता है।', 'Kerala consistently tops the SDG index. MP''s score usually hovers between 60-65.', 'medium', 0.8, 0.85, '[{"questionId":"r4Tgo8Qbgy7nQzMVGqEe3"},{"questionId":"YNWRZHx7cCf0NkRjz2rKS"}]', '["Indices","Institutes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829284, 1773829284);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c5f7f31d-89f7-4db1-883f-6fe401d23fea', '7b305731-d2cf-4098-afa9-8c23db9c7bec', 'Current Affairs', 'मानव शरीर की सबसे छोटी मांसपेशी ''स्टेपीडियस'' (Stapedius) है जो मध्य कान में होती है। भारतीय पेट्रोलियम संस्थान (IIP) देहरादून में स्थित है।', 'The smallest muscle in the human body is ''Stapedius'', located in the middle ear. Indian Institute of Petroleum (IIP) is in Dehradun.', 'कान की सबसे छोटी हड्डी (Stapes) से जुड़ी मांसपेशी = Stapedius. तेल (Petroleum) = देहरा ''दून'' (Doon valley).', 'Muscle attached to the smallest bone (Stapes) = Stapedius. Oil (Petroleum) = Dehra ''Doon'' valley.', 'सार्टोरियस (Sartorius) शरीर की सबसे लंबी मांसपेशी है, स्टेपीडियस सबसे छोटी।', 'Sartorius is the longest muscle in the body, Stapedius is the smallest.', 'medium', 0.75, 0.8, '[{"questionId":"9n6WezTqHUVNB7fhSxQb1"},{"questionId":"jYpVwdBQfprms6JxVJaTA"}]', '["Biology Facts","Research Institutes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829284, 1773829284);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0e5d7b4c-1ff3-4cb1-90dd-ad3e6ea7055a', '1fecfd62-1493-4ccf-8a8f-d914fa553c56', 'MP GK', 'म.प्र. भारत में मैंगनीज और तांबे का सबसे बड़ा उत्पादक है (मलाजखंड बालाघाट तांबे के लिए, भारवेली मैंगनीज के लिए)।', 'MP is the largest producer of Manganese and Copper in India (Malajkhand in Balaghat for Copper, Bharveli for Manganese).', 'बालाघाट = म.प्र. का ''तांबा और मैंगनीज'' हब।', 'Balaghat = MP''s ''Copper and Manganese'' Hub.', 'मैंगनीज के भंडार (Reserves) में ओडिशा प्रथम है, लेकिन उत्पादन (Production) में म.प्र. प्रथम है। दोनों में भ्रमित न हों।', 'Odisha is 1st in Manganese Reserves, but MP is 1st in Production. Don''t confuse the two.', 'medium', 0.9, 0.95, '[{"questionId":"zckDEpzzQ8lRyWYY52KXZ"},{"questionId":"y9KChvi_Sa8RXsrCY8ima"}]', '["Minerals","Balaghat","High-Yield"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829299, 1773829299);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('acb96d58-6f7a-483e-aa26-fc155330204a', '1fecfd62-1493-4ccf-8a8f-d914fa553c56', 'MP GK', 'काली मिट्टी (Regur Soil) में चूना, लोहा और मैग्नीशियम अधिक होता है, लेकिन नाइट्रोजन, फॉस्फोरस और ह्यूमस की कमी होती है।', 'Black soil (Regur Soil) is rich in lime, iron, and magnesium, but lacks nitrogen, phosphorus, and humus.', 'भारतीय मिट्टियों में हमेशा N, P, K (Nitrogen, Phosphorus) की कमी होती है।', 'Indian soils consistently lack N, P, K (Nitrogen, Phosphorus).', 'काली मिट्टी का काला रंग टिटेनीफेरस मैग्नेटाइट के कारण होता है, इसे कार्बन या ह्यूमस की अधिकता न समझें।', 'The black color is due to Titaniferous Magnetite, do not mistake it for excess carbon or humus.', 'medium', 0.85, 0.92, '[{"questionId":"o2_WwJh5KMoXosPnhepHl"}]', '["Soils","Agriculture"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829299, 1773829299);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e55c7d07-112e-4176-beef-b539f950dd9c', '1fecfd62-1493-4ccf-8a8f-d914fa553c56', 'MP GK', 'ओरछा बेतवा नदी पर है, मुलताई से ताप्ती निकलती है, और उज्जैन क्षिप्रा के तट पर है।', 'Orchha is on the Betwa river, Tapti originates from Multai, and Ujjain is on the banks of Kshipra.', 'उज्जैन-क्षिप्रा (महाकाल), मुलताई-ताप्ती (MT), ओरछा-बेतवा (OB)।', 'Ujjain-Kshipra (Mahakal), Multai-Tapti (MT), Orchha-Betwa (OB).', 'नर्मदा और ताप्ती दोनों पश्चिम की ओर बहती हैं, लेकिन ताप्ती मुलताई (बैतूल) से और नर्मदा अमरकंटक से निकलती है।', 'Both Narmada and Tapti flow west, but Tapti originates from Multai (Betul) and Narmada from Amarkantak.', 'medium', 0.8, 0.88, '[{"questionId":"xYAF8eU50_2hyBx5T1KpA"}]', '["Rivers","Cities"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829299, 1773829299);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('bdb205d8-a238-4a80-aa86-b14bffea6f1a', '4001a1e6-d4ad-49ca-bf87-3a52adb037da', 'MP GK', 'चरण पादुका गोलीकांड (छतरपुर, 1931) में कर्नल फिशर ने गोली चलवाई। इसे म.प्र. का जलियाँवाला बाग कहा जाता है।', 'Colonel Fisher ordered firing in Charan Paduka massacre (Chhatarpur, 1931). It''s called the Jallianwala Bagh of MP.', 'छतरपुर के चरण पादुका पर ''फिशर'' (Fisher) का क्रूर वार।', 'Cruel strike by ''Fisher'' on Charan Paduka in Chhatarpur.', 'जनरल डायर को टिक न करें (वह जलियाँवाला बाग से था)। म.प्र. के संदर्भ में हमेशा कर्नल फिशर को याद रखें।', 'Do not tick General Dyer (he was in Jallianwala Bagh). In MP''s context, always remember Col. Fisher.', 'medium', 0.95, 0.98, '[{"questionId":"nnqTCs2y1atds6AAMsp8b"}]', '["Freedom Struggle","Massacre"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829300, 1773829300);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a45f5360-c501-4427-999e-49163dcf4a00', '4001a1e6-d4ad-49ca-bf87-3a52adb037da', 'MP GK', 'टुरिया जंगल सत्याग्रह (सिवनी, 1930) का नेतृत्व गोंड और कोरकू आदिवासियों (गंजन सिंह कोरकू) ने किया था।', 'Turiya Jungle Satyagraha (Seoni, 1930) was led by Gond and Korku tribals (Ganjan Singh Korku).', 'टुरिया (सिवनी) के जंगल में ''गंजन'' (Ganjan) की गूंज।', 'Echo of ''Ganjan'' in the jungles of Turiya (Seoni).', 'घोड़ाडोंगरी (बैतूल) सत्याग्रह का नेतृत्व भी गंजन सिंह ने किया था, इसलिए दोनों स्थानों को याद रखें।', 'Ghoradongri (Betul) satyagraha was also led by Ganjan Singh, so remember both locations.', 'medium', 0.88, 0.92, '[{"questionId":"5qwS_Gfy1LBGScDlhgz_-"}]', '["Tribal Revolt","Jungle Satyagraha"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829300, 1773829300);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('bd533d99-d59d-43cb-ab5b-a0fdb97caf79', '4001a1e6-d4ad-49ca-bf87-3a52adb037da', 'MP GK', 'डॉ. वी.एस. वाकणकर ने 1957-58 में भीमबैठका की खोज की; बाघ गुफा (धार) की गुफा सं. 4 को ''रंग महल'' कहते हैं।', 'Dr. V.S. Wakankar discovered Bhimbetka in 1957-58; Cave no. 4 of Bagh Caves (Dhar) is called ''Rang Mahal''.', 'वाकणकर की 57 की खोज (Bhimbetka). गुफा 4 = चार रंग (Rang Mahal).', 'Wakankar''s 57 discovery (Bhimbetka). Cave 4 = Four Colors (Rang Mahal).', 'बाघ गुफाएं बौद्ध धर्म से संबंधित हैं (अजंता के समकालीन), इन्हें जैन या हिन्दू गुफाओं से भ्रमित न करें।', 'Bagh Caves are related to Buddhism (contemporary to Ajanta), do not confuse them with Jain or Hindu caves.', 'medium', 0.9, 0.9, '[{"questionId":"V7ZGVJ0-bLUZyyJJwQmAc"},{"questionId":"4HvUsCT2zY7g6xhfQpMzv"}]', '["Archaeology","Caves","UNESCO"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829300, 1773829300);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e3e07c99-ed49-46f6-944f-ffb15b22fd1a', '97f7f232-419e-45bc-a59e-6281067b4ded', 'MP GK', 'म.प्र. में 3 विशेष पिछड़ी जनजातियाँ (PVTG) हैं: बैगा, भारिया और सहरिया। ''आहार अनुदान योजना'' इन्हीं 3 जनजातियों के कुपोषण को दूर करने के लिए है।', 'There are 3 PVTGs in MP: Baiga, Bharia, and Saharia. ''Aahar Anudan Yojana'' aims to eradicate malnutrition specifically among these 3 tribes.', 'B-B-S (Baiga, Bharia, Saharia) को मिलेगा आहार (Food).', 'B-B-S (Baiga, Bharia, Saharia) will get Aahar (Food).', 'भील और गोंड म.प्र. की सबसे बड़ी जनजातियाँ हैं, लेकिन वे PVTG (विशेष पिछड़ी) की श्रेणी में नहीं आती हैं।', 'Bhil and Gond are the largest tribes in MP, but they do NOT fall under the PVTG (Particularly Vulnerable) category.', 'medium', 0.98, 0.99, '[{"questionId":"ZhUhXCfu2uZDk6We2wyEE"},{"questionId":"T3ygRo4agKgldyOM90jXW"}]', '["PVTG","Tribal Welfare","Schemes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829301, 1773829301);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('76fd3792-13c4-4205-a61a-7a09e0e9ec8d', '97f7f232-419e-45bc-a59e-6281067b4ded', 'MP GK', 'पातालकोट (छिंदवाड़ा) भारिया जनजाति का निवास है। ICMR का आदिवासी स्वास्थ्य अनुसंधान संस्थान (NIRTH) जबलपुर में है।', 'Patalkot (Chhindwara) is the abode of the Bharia tribe. ICMR''s Tribal Health Research Institute (NIRTH) is in Jabalpur.', 'पाताल (Deep Valley) में भारिया। जबलपुर आदिवासियों की ''हेल्थ कैपिटल''।', 'Bharia in Patala (Deep Valley). Jabalpur is the ''Health Capital'' for tribals.', 'भारिया केवल पातालकोट तक सीमित माने जाते हैं, जबकि गोंड पूरे महाकोशल क्षेत्र में फैले हैं।', 'Bharias are considered confined to Patalkot, whereas Gonds are spread across the Mahakoshal region.', 'medium', 0.9, 0.95, '[{"questionId":"brDgwdF-gg3fzoZ5yYw9e"},{"questionId":"AcPC6EMGst800Z-259OnV"}]', '["Tribal Demographics","Institutes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829301, 1773829301);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('90f3a1ee-5376-403c-baf4-9de4d6d1d652', '97f7f232-419e-45bc-a59e-6281067b4ded', 'MP GK', '''The Baiga'' पुस्तक वेरियर एल्विन ने लिखी है। जगनिक ने ''आल्हाखण्ड'' और केशवदास ने ''कविप्रिया'', ''रामचन्द्रिका'' लिखी है।', 'The book ''The Baiga'' is written by Verrier Elwin. Jagnik wrote ''Alhakhand'' and Keshavdas wrote ''Kavipriya'', ''Ramchandrika''.', 'बैगा के लिए एल्विन (Elwin for Baiga)। आल्हा गाता जगनिक (Alha sung by Jagnik)।', 'Elwin for Baiga. Alha sung by Jagnik.', '''राम रसायन'' केशवदास की नहीं, पद्माकर की रचना है। केशवदास को ''कठिन काव्य का प्रेत'' कहा जाता है।', '''Ram Rasayan'' is by Padmakar, not Keshavdas. Keshavdas is known as the ''Ghost of difficult poetry''.', 'medium', 0.85, 0.88, '[{"questionId":"5lZ6eIeWjdljM9gNBbw76"},{"questionId":"MiVEiouV63yQTjVT3J5b3"},{"questionId":"tQVOw7psPIgGLohIlbexi"}]', '["Literature","Tribal Books"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829301, 1773829301);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3d731694-c980-4c78-b5a8-341dbad2639a', '3569dcbc-e489-469f-8285-fa4aab7a40ad', 'MP GK', 'म.प्र. में केवल एक तेल रिफाइनरी ''बीना'' (सागर) में है। महान एल्युमीनियम प्लांट (हिंडाल्को) सिंगरौली में 2013 से कार्यरत है।', 'MP has only one oil refinery in ''Bina'' (Sagar). Mahan Aluminium Plant (Hindalco) has been operating in Singrauli since 2013.', 'तेल (Oil) बीना में। एल्युमीनियम (Al) सिंगरौली में।', 'Oil in Bina. Aluminum in Singrauli.', 'बीना रिफाइनरी ओमान के सहयोग (BORL) से बनी थी, लेकिन अब यह पूरी तरह से BPCL के अधीन है।', 'Bina Refinery was built with Oman''s help (BORL), but now it is fully owned by BPCL.', 'medium', 0.88, 0.94, '[{"questionId":"W4CJMKcMFj3u50uYF0EOq"},{"questionId":"Zw_2sV3vY5t0WiZYCWb2-"}]', '["Heavy Industry","Energy"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829302, 1773829302);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('f20c4b03-ee9b-4d5c-bea4-0eef5b95ca8e', '3569dcbc-e489-469f-8285-fa4aab7a40ad', 'MP GK', 'सीमेंट कारखाने: बानमोर (मुरैना), मालनपुर (भिण्ड), मैहर (सतना/मैहर)। छतरपुर का ODOP उत्पाद ''लकड़ी का फर्नीचर'' है।', 'Cement factories: Banmore (Morena), Malanpur (Bhind), Maihar (Satna/Maihar). Chhatarpur''s ODOP product is ''Wooden Furniture''.', 'बानमोर-मुरैना की सीमेंट (ACC)। छतरपुर का फर्नीचर (Furniture)।', 'Banmore-Morena Cement (ACC). Chhatarpur''s Furniture.', 'बानमोर को मालनपुर से कन्फ्यूज न करें। बानमोर मुरैना में है (म.प्र. की पहली सीमेंट फैक्ट्री), जबकि मालनपुर भिण्ड में है।', 'Do not confuse Banmore with Malanpur. Banmore is in Morena (MP''s first cement factory), while Malanpur is in Bhind.', 'medium', 0.85, 0.9, '[{"questionId":"s-e1iBUoDiSaRDqCBJnw4"},{"questionId":"9hG21wk3RZ6OvsDxKBNkA"}]', '["Industrial Areas","ODOP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829302, 1773829302);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('46245dff-f576-45cb-ae5b-707996281245', '3569dcbc-e489-469f-8285-fa4aab7a40ad', 'MP GK', 'लाड़ली बहना योजना महिलाओं के आर्थिक स्वावलंबन और पोषण के लिए है। उद्यम क्रांति योजना युवाओं को गारंटी-रहित (Collateral-free) ऋण देती है।', 'Ladli Behna Yojana is for women''s economic independence and nutrition. Udyam Kranti Yojana provides collateral-free loans to youth.', 'बहना = पैसा + पोषण। उद्यम = नो गारंटी लोन।', 'Behna = Money + Nutrition. Udyam = No Guarantee Loan.', 'लाड़ली लक्ष्मी योजना (लड़कियों की शिक्षा) और लाड़ली बहना योजना (महिलाओं को नकद) के उद्देश्यों को स्पष्ट रूप से अलग रखें।', 'Keep the objectives of Ladli Laxmi Yojana (girls'' education) and Ladli Behna Yojana (cash to women) strictly separate.', 'medium', 0.95, 0.95, '[{"questionId":"M7djolJSyhmf_4Lh3UHP0"},{"questionId":"U5FKU0b3eWY-ZTQN2evse"}]', '["Flagship Schemes","Economy"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829302, 1773829302);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('aee595d2-e67b-4800-87fc-8267e87e9a4d', '0e82b86f-50f1-42b6-9cc1-b67d72341419', 'Polity', 'अनुच्छेद 338: SC आयोग। 338A: ST आयोग। 342: ST को अधिसूचित करने की राष्ट्रपति की शक्ति। 332: विधानसभा में ST आरक्षण।', 'Article 338: SC Commission. 338A: ST Commission. 342: President''s power to notify STs. 332: ST reservation in State Assembly.', '338(SC) -> 338A(ST). 341(SC) -> 342(ST).', '338(SC) -> 338A(ST). 341(SC) -> 342(ST).', 'अनुच्छेद 330 (लोकसभा में आरक्षण) और 332 (विधानसभा में आरक्षण) के बीच भ्रमित न हों।', 'Do not get confused between Article 330 (Reservation in Lok Sabha) and 332 (Reservation in Vidhan Sabha).', 'medium', 0.95, 0.98, '[{"questionId":"0Ng18y_RKrbk73vdF4YMr"},{"questionId":"a_crV_m8Fb99749MxmUtC"},{"questionId":"GQ4tHuc-rpBHzmzUO-I8x"}]', '["Important Articles","SC/ST Provisions"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829303, 1773829303);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('67f157ae-de5f-4c0d-9550-4c0c54ad65cd', '0e82b86f-50f1-42b6-9cc1-b67d72341419', 'Polity', 'संविधान सभा की पहली बैठक 9 दिसंबर 1946 को हुई, जिसमें नेहरू जी मौजूद थे (उन्होंने 13 दिसंबर को उद्देश्य प्रस्ताव पेश किया)।', 'The first meeting of the Constituent Assembly was on Dec 9, 1946, where Nehru was present (he moved the Objectives Resolution on Dec 13).', '9 (पहली बैठक) -> 11 (राजेन्द्र प्रसाद अध्यक्ष) -> 13 (नेहरू का प्रस्ताव)।', '9 (1st meet) -> 11 (Rajendra Prasad Prez) -> 13 (Nehru''s Resolution).', 'नेहरू जी को संविधान सभा में आमंत्रित न करने वाला कथन एक सफेद झूठ (Trap) था।', 'The statement about Nehru not being invited to the Constituent Assembly was a blatant trap.', 'medium', 0.85, 0.9, '[{"questionId":"vVif4NrOqd2Q0Btq9iCKT"}]', '["Constituent Assembly","Making of Constitution"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829303, 1773829303);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b2111920-f5d7-4756-bb8a-d257d8dad0a7', '0e82b86f-50f1-42b6-9cc1-b67d72341419', 'Polity', 'राष्ट्रपति पर महाभियोग (Art 61) केवल ''संविधान के उल्लंघन'' पर लगता है। संपत्ति का अधिकार (Art 300A) 44वें संशोधन द्वारा कानूनी अधिकार बना।', 'Impeachment of President (Art 61) is only on grounds of ''Violation of Constitution''. Right to Property (Art 300A) became a legal right via 44th Amendment.', 'महाभियोग = 61 (Violation). संपत्ति आउट = 44 (1978).', 'Impeachment = 61 (Violation). Property out = 44 (1978).', '''संविधान का उल्लंघन'' संविधान में परिभाषित नहीं है। संपत्ति का अधिकार अब मौलिक अधिकार नहीं है।', '''Violation of Constitution'' is NOT defined in the Constitution. Right to property is NO longer a fundamental right.', 'medium', 0.9, 0.95, '[{"questionId":"npgxWKNEJIIgkW8goCedS"},{"questionId":"RJnh7vTu9dGwyMKmaS2mN"}]', '["Fundamental Rights","President"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829304, 1773829304);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('8f0c8b1d-7323-45e2-86d5-d1bfc54d6772', '0e82b86f-50f1-42b6-9cc1-b67d72341419', 'Polity', '1977 में म.प्र. में प्रथम राष्ट्रपति शासन के समय राज्यपाल ''सत्य नारायण सिन्हा'' थे। ''पट्टाभि सीतारमैया'' का कार्यकाल सबसे छोटा था।', 'During the 1st President''s Rule in MP (1977), Governor was ''Satya Narayan Sinha''. ''Pattabhi Sitaramayya'' had the shortest tenure.', '77 में सिन्हा (Sinha in 77). पट्टाभि सबसे छोटे (Pattabhi shortest).', 'Sinha in 77. Pattabhi shortest.', 'म.प्र. में 3 बार राष्ट्रपति शासन लगा है (1977, 1980, 1992)। तीनों के समय के सीएम और गवर्नर याद रखें।', 'President rule was imposed 3 times in MP (1977, 1980, 1992). Remember the CMs and Governors during all three.', 'medium', 0.8, 0.85, '[{"questionId":"50MYgGrobgMZJxbVEfOH9"},{"questionId":"z8xSMFfR18_KgT18WgyRE"}]', '["State Executive","MP Governors"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829304, 1773829304);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5dae8823-4efa-4eb6-a296-e64834f9eb80', '9d69a8ab-60c7-4e37-9989-770b7897c32c', 'Current Affairs', 'चंद्रयान-3 की सफलता के उपलक्ष्य में 23 अगस्त को ''राष्ट्रीय अंतरिक्ष दिवस'' घोषित किया गया है।', 'To commemorate the success of Chandrayaan-3, August 23 has been declared ''National Space Day''.', '23 अगस्त = शिव शक्ति लैंडिंग = स्पेस डे।', 'Aug 23 = Shiv Shakti landing = Space Day.', 'अंतरिक्ष विज्ञान में नए दिवस और लैंडिंग साइट के नाम (''शिव शक्ति'' और ''तिरंगा'' पॉइंट) सीधे पूछे जाते हैं।', 'New dates and landing site names (''Shiv Shakti'' and ''Tiranga'' points) in Space science are directly asked.', 'medium', 0.9, 0.98, '[{"questionId":"BBBO5vnWFoAXfLIjFPJ9L"}]', '["Space Tech","Important Days"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829305, 1773829305);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('38841642-7f16-4713-aa7e-633996604ff0', '9d69a8ab-60c7-4e37-9989-770b7897c32c', 'Current Affairs', 'T20 विश्व कप 2024 का फाइनल बारबाडोस (वेस्टइंडीज) में भारत और दक्षिण अफ्रीका के बीच हुआ था।', 'The T20 World Cup 2024 final was held in Barbados (West Indies) between India and South Africa.', 'बारबाडोस में भारत की विश्व विजय।', 'India''s World Victory in Barbados.', 'मेजबान देश यूएसए और वेस्टइंडीज दोनों थे, लेकिन फाइनल बारबाडोस में था।', 'The host nations were both USA and West Indies, but the final was in Barbados.', 'medium', 0.85, 0.92, '[{"questionId":"HkTGvWZwybs-Zmvr8M0NL"}]', '["Sports","Cricket"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829305, 1773829305);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4f8a2d13-e1a5-4009-ba9b-1477ba1e9377', '9d69a8ab-60c7-4e37-9989-770b7897c32c', 'Current Affairs', 'अन्नू रानी (एशियाई खेल 2023) ने भाला फेंक में स्वर्ण जीता। हॉकी गोलकीपर पी.आर. श्रीजेश को पद्म श्री मिला है, पद्म भूषण नहीं।', 'Annu Rani (Asian Games 2023) won gold in Javelin. Hockey goalkeeper P.R. Sreejesh received Padma Shri, not Padma Bhushan.', 'अन्नू का भाला (Annu''s Javelin)। श्रीजेश = द वॉल (The Wall)।', 'Annu''s Javelin. Sreejesh = The Wall.', 'खिलाड़ियों के खेलों (Sports) और उन्हें मिले सर्वोच्च नागरिक/खेल पुरस्कारों का मिलान जरूर पूछा जाता है।', 'Matching players with their sports and their highest civilian/sports awards is definitely asked.', 'medium', 0.8, 0.88, '[{"questionId":"1NBeEMbiS6H7PNIjRQL_5"},{"questionId":"eUoiJyj9B-K24PcoWjqr3"}]', '["Sports Awards","Asian Games"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829305, 1773829305);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('472d0e89-234d-4d65-90a4-832e1c7bd9c6', '9d69a8ab-60c7-4e37-9989-770b7897c32c', 'Current Affairs', 'AI चिप्स में FPGA (Field Programmable Gate Array) का उपयोग होता है। AICRA भारत में रोबोटिक्स का मानक निकाय है।', 'FPGA (Field Programmable Gate Array) is used in AI chips. AICRA is the standard body for Robotics in India.', 'FPGA = Field Programmable (ग्राहक खुद सेट करे)। AICRA = AI + Robotics Council.', 'FPGA = Field Programmable (Customer sets it). AICRA = AI + Robotics Council.', 'FPGA का फुल फॉर्म तकनीकी है, इसे ''फॉरेंसिक'' या ''फास्ट'' जैसे शब्दों से कन्फ्यूज न करें।', 'FPGA full form is technical, don''t confuse it with words like ''Forensic'' or ''Fast''.', 'medium', 0.75, 0.85, '[{"questionId":"94duKHWHuF5KVTaWZvDZC"},{"questionId":"e_B20swCyt-zv9LCJyNzl"}]', '["AI","Robotics","Abbreviations"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829305, 1773829305);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a67c11d9-54fe-4cbb-bb92-8ce6bd8c72b9', '64a26b2e-a3ce-43cc-a906-459770b4b964', 'Current Affairs', 'सुधा मूर्ति को 2024 में राज्यसभा के लिए मनोनीत किया गया। डी. गुकेश 17 वर्ष की आयु में FIDE कैंडिडेट्स जीतने वाले सबसे युवा खिलाड़ी बने।', 'Sudha Murty was nominated to Rajya Sabha in 2024. D. Gukesh became the youngest to win FIDE Candidates at age 17.', 'राज्यसभा में ''मूर्ति'' (Murty in RS)। शतरंज का युवा बादशाह ''गुकेश'' (Young King Gukesh).', 'Murty in RS. Young King of Chess ''Gukesh''.', 'प्रज्ञानानंद भी शतरंज के युवा खिलाड़ी हैं, लेकिन कैंडिडेट्स 2024 गुकेश ने जीता।', 'Praggnanandhaa is also a young chess player, but Gukesh won the Candidates 2024.', 'medium', 0.9, 0.96, '[{"questionId":"jPJqG0xoZbEqI3PCskgQV"},{"questionId":"Suh_MLyzgecT7X55PGw3P"}]', '["Polity Current Affairs","Sports"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829326, 1773829326);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0e630621-cfba-4710-b297-dc026ba53b17', '3368d533-4c6b-449f-bd78-05cb92c2d9e0', 'Geography', 'ओज़ोन परत की मोटाई डब्सन (Dobson) इकाई में मापी जाती है। जल (प्रदूषण निवारण) अधिनियम 1974 में पारित हुआ था।', 'Ozone layer thickness is measured in Dobson Units. The Water (Prevention of Pollution) Act was passed in 1974.', 'डब्सन = ओज़ोन की ढाल (Defense)। 74 का जल (Water of ''74)।', 'Dobson = Ozone Defense. Water of ''74.', 'पर्यावरण अधिनियम 1986 में है, जबकि जल अधिनियम पहले (1974) आ गया था।', 'Environment Act is 1986, while the Water Act came earlier in 1974.', 'medium', 0.9, 0.95, '[{"questionId":"tGcleimsrbdupEiQF_B0w"},{"questionId":"uEkieDzhrulR3N1I6-i77"}]', '["Environment Acts","Units of Measurement"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829327, 1773829327);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('94dda638-6940-4274-ae5a-f56e4e3ca476', '3368d533-4c6b-449f-bd78-05cb92c2d9e0', 'Geography', 'कोयले के सर्वाधिक भंडार झारखंड और ओडिशा में हैं (50% से अधिक)। बॉक्साइट का सबसे बड़ा भंडार ओडिशा में है।', 'Highest coal reserves are in Jharkhand and Odisha (>50%). Largest bauxite reserves are in Odisha.', 'कोयला = झारखंड-ओडिशा। बॉक्साइट = ओडिशा (कालाहांडी)।', 'Coal = Jharkhand-Odisha. Bauxite = Odisha (Kalahandi).', 'कोयले के उत्पादन (Production) में छत्तीसगढ़ और ओडिशा आगे हैं, लेकिन भंडार (Reserves) में झारखंड प्रथम है।', 'In coal Production, Chhattisgarh and Odisha lead, but in Reserves, Jharkhand is 1st.', 'medium', 0.85, 0.94, '[{"questionId":"gbu2GU30OiOfL2LC1jJPz"},{"questionId":"2Q-_VTWBIzhKZAVlH392k"}]', '["Minerals","Economic Geography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829327, 1773829327);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('cbda9966-7be4-4aeb-8a3b-eabf955b09a1', '3368d533-4c6b-449f-bd78-05cb92c2d9e0', 'Geography', 'नदियों का मिलान: ताप्ती -> मुलताई (म.प्र.), कावेरी -> ब्रह्मगिरि (कर्नाटक), साबरमती -> अरावली (राज.), दामोदर -> छोटा नागपुर (झारखंड)।', 'River matching: Tapti -> Multai (MP), Kaveri -> Brahmagiri (Kar), Sabarmati -> Aravalli (Raj), Damodar -> Chhota Nagpur (Jhar).', 'मुलताई की ताप्ती, ब्रह्म की कावेरी, अरावली की साबरमती।', 'Multai''s Tapti, Brahma''s Kaveri, Aravalli''s Sabarmati.', 'कावेरी महाबलेश्वर से नहीं, ब्रह्मगिरि पहाड़ियों (कुर्ग) से निकलती है।', 'Kaveri originates from Brahmagiri hills (Coorg), not Mahabaleshwar.', 'medium', 0.95, 0.9, '[{"questionId":"XDYIYkZNuM6agM32hgdio"}]', '["Rivers","Origins"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829327, 1773829327);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('98eb3334-006d-425d-9225-478c614987f9', '3368d533-4c6b-449f-bd78-05cb92c2d9e0', 'Geography', 'जनगणना 2011 में अरुणाचल प्रदेश का जनसंख्या घनत्व सबसे कम (17 व्यक्ति/वर्ग किमी) था।', 'Arunachal Pradesh had the lowest population density in Census 2011 (17 persons/sq km).', 'अरुण की भूमि सबसे खाली (Arun''s land is most empty).', 'Arun''s land is most empty.', 'सबसे कम जनसंख्या सिक्किम में है, लेकिन सबसे कम ''घनत्व'' अरुणाचल में है।', 'Sikkim has the lowest population, but Arunachal has the lowest ''density''.', 'medium', 0.9, 0.9, '[{"questionId":"koCFcdlCH78ElpJtXTk3d"}]', '["Census 2011"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829327, 1773829327);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('2f0eefdb-048b-41a5-87a0-316b1c8a626e', 'dafc8c11-df14-48ba-8007-3b255419641f', 'History', 'मंदसौर का दशपुर अभिलेख (कुमारगुप्त) ''वत्सभट्टि'' ने लिखा था। यशोधर्मन का सौंदनी अभिलेख ''वासुल'' ने रचा था।', 'Dashpur inscription of Mandsaur (Kumargupta) was written by ''Vatsabhatti''. Sondani inscription of Yashodharman was composed by ''Vasula''.', 'दशपुर = वत्सभट्टि (Vatsa)। सौंदनी = वासुल (Vasula)।', 'Dashpur = Vatsa. Sondani = Vasula.', 'दशपुर अभिलेख को ''भवभूति'' से न जोड़ें। भवभूति 8वीं सदी के कवि थे।', 'Do not link Dashpur inscription with ''Bhavabhuti''. Bhavabhuti was an 8th-century poet.', 'medium', 0.95, 0.98, '[{"questionId":"h9vz_KA_EMFuinKJPHIFa"},{"questionId":"MX__XQCj6SeM9XkgHWLq0"}]', '["Ancient Inscriptions","MP History"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829329, 1773829329);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('81b5107c-7563-4580-9f15-750209767b7a', 'dafc8c11-df14-48ba-8007-3b255419641f', 'History', 'ऋग्वेद सबसे पुराना वेद है। अथर्ववेद में ''सभा'' और ''समिति'' को प्रजापति की दो पुत्रियां कहा गया है। क्षत्रियों के उपनयन में ''त्रिष्टुभ'' मंत्र का प्रयोग होता था।', 'Rigveda is the oldest Veda. Atharvaveda calls ''Sabha'' and ''Samiti'' the two daughters of Prajapati. Kshatriya upanayana used the ''Trishtubh'' mantra.', 'अथर्व में दो पुत्रियाँ (2 Daughters in Atharva)। क्षत्रिय = त्रिष्टुभ (T for Warrior)।', '2 Daughters in Atharva. Kshatriya = Trishtubh (T for Warrior).', 'ब्राह्मणों के लिए गायत्री मंत्र था, वैश्यों के लिए जगती मंत्र था।', 'Gayatri mantra was for Brahmins, Jagati mantra for Vaishyas.', 'medium', 0.85, 0.9, '[{"questionId":"mra2BUeIOa8fBN3u3zTEZ"},{"questionId":"izbYyHCdOd7j6m8nOpN8-"},{"questionId":"QgJXSS1pWX_87YEuH3KFg"}]', '["Vedic Culture","Ancient Texts"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829329, 1773829329);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7df7c99e-0e45-4a63-984b-0c85c2d704ab', 'dafc8c11-df14-48ba-8007-3b255419641f', 'History', 'मौर्य प्रशासन में ''प्रदेष्टा'' फौजदारी (Criminal) न्यायालय का न्यायाधीश होता था।', 'In Mauryan admin, ''Pradeshta'' was the judge of the Kantakashodhana (Criminal) court.', 'प्रदेष्टा = क्रिमिनल/फौजदारी (Pradeshta = Police/Criminal).', 'Pradeshta = Police/Criminal.', '''धर्मस्थीय'' दीवानी (Civil) न्यायालय था, जिसके जज को ''व्यवहारिक'' कहा जाता था।', '''Dharmasthiya'' was the Civil court, whose judge was called ''Vyavaharika''.', 'medium', 0.8, 0.88, '[{"questionId":"cU3j3_aSwbFEl7jfABCpW"}]', '["Mauryan Administration"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829329, 1773829329);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('910d74f2-f2d2-4580-be6f-d2fb4913b4bd', 'dafc8c11-df14-48ba-8007-3b255419641f', 'History', 'एलोरा की गुफा संख्या 16 में प्रसिद्ध एक-चट्टानी (Monolithic) कैलाश मंदिर है। अष्टांग योग में ''धारणा'' पहली अन्तरंग साधना है।', 'Ellora Cave No. 16 houses the famous monolithic Kailash Temple. In Ashtanga Yoga, ''Dharana'' is the first internal (Antaranga) practice.', '16वां कैलाश (16th Kailash)। अन्तरंग की शुरुआत ''धारणा'' से (Internal starts with Dharana)।', '16th Kailash. Internal starts with Dharana.', 'प्रत्याहार ''बहिरंग'' (External) साधना की अंतिम सीढ़ी है, जबकि ''धारणा'' अन्तरंग (Internal) की पहली।', 'Pratyahara is the last step of ''External'' (Bahiranga) practice, while ''Dharana'' is the first of ''Internal'' (Antaranga).', 'medium', 0.88, 0.92, '[{"questionId":"CCK-w-ruKeaMQM3pgxvPq"},{"questionId":"NFPRPJ7dJzZZ1iG6J25Ii"}]', '["Art & Culture","Indian Philosophy"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829329, 1773829329);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('34a8b882-dcdb-4fb9-b072-7e1c74a42e47', 'f5335203-eb21-4d8c-bf2a-6a3ec06a440c', 'ICT', 'UNIX ऑपरेटिंग सिस्टम का मुख्य/केन्द्रीय भाग ''कर्नल'' (Kernel) कहलाता है। मशीन लर्निंग (Machine Learning) आर्टिफिशियल इंटेलिजेंस की एक शाखा है।', 'The central part of the UNIX OS is called the ''Kernel''. Machine Learning is a branch of Artificial Intelligence.', 'कर्नल = OS का दिल (Heart of OS)।', 'Kernel = Heart of OS.', 'शेल (Shell) केवल यूजर इंटरफेस है, सिस्टम का मुख्य कोर कर्नल (Kernel) ही होता है।', 'Shell is just the user interface; the main core of the system is the Kernel.', 'medium', 0.9, 0.95, '[{"questionId":"9OV6Q01hUEHwEZT6CztSw"},{"questionId":"BYkObw_mwpOdXpKqbFQmg"}]', '["Operating Systems","AI basics"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829330, 1773829330);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e23551b3-1f8a-48be-9ea8-cc9ddd59cda7', 'f5335203-eb21-4d8c-bf2a-6a3ec06a440c', 'ICT', 'भ्रामक ईमेल या संदेश के जरिए पासवर्ड या जानकारी चुराना ''फिशिंग'' (Phishing) कहलाता है।', 'Stealing passwords or information via deceptive emails or messages is called ''Phishing''.', 'फिशिंग = मछली (यूजर) को चारा (Email) डालकर फंसाना।', 'Phishing = Baiting the fish (user) with an email.', 'स्पूफिंग (Spoofing) में पहचान छिपाई जाती है, जबकि फिशिंग (Phishing) में धोखा देकर जानकारी मांगी जाती है।', 'In Spoofing, identity is hidden; in Phishing, information is deceitfully extracted.', 'medium', 0.95, 0.98, '[{"questionId":"-BJnQE18J5AQMcoVIBaRM"}]', '["Cyber Security","Malware & Attacks"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829330, 1773829330);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('eaeea363-f8b5-488c-8692-6096e6773374', 'f5335203-eb21-4d8c-bf2a-6a3ec06a440c', 'ICT', 'एलन ट्यूरिंग के परीक्षण का मूल नाम ''द इमिटेशन गेम'' (The Imitation Game) था, जो यह जांचता है कि मशीन सोच सकती है या नहीं।', 'The original name of Alan Turing''s test was ''The Imitation Game'', which checks if a machine can think.', 'ट्यूरिंग टेस्ट = इमिटेशन (नकल करने का) गेम।', 'Turing Test = Imitation Game.', 'यह AI के इतिहास का सबसे बुनियादी प्रश्न है, इसे आधुनिक वीडियो गेम से न जोड़ें।', 'This is a fundamental question in AI history; do not link it to modern video games.', 'medium', 0.85, 0.88, '[{"questionId":"6JTWTilXRfke9YuYyCrbD"}]', '["History of Computing","AI"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829330, 1773829330);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('249aad33-214b-4f07-bbac-bcb2dfce387f', 'f5335203-eb21-4d8c-bf2a-6a3ec06a440c', 'ICT', 'W3C का पूर्ण रूप ''World Wide Web Consortium'' है (यह वेब के मानक तय करता है)। MPEG का अर्थ ''Moving Picture Experts Group'' है (ऑडियो/वीडियो मानक)।', 'W3C stands for ''World Wide Web Consortium'' (sets web standards). MPEG stands for ''Moving Picture Experts Group'' (audio/video standards).', 'W3 = WWW. C = Consortium. MPEG = Moving Picture.', 'W3 = WWW. C = Consortium. MPEG = Moving Picture.', 'Consortium की स्पेलिंग और अर्थ (समूह) पर ध्यान दें, विकल्पों में ''Corporation'' या ''Center'' देकर फंसाया जाता है।', 'Pay attention to the word Consortium; options trap you with ''Corporation'' or ''Center''.', 'medium', 0.9, 0.92, '[{"questionId":"4VD6MV70yzdm86Jo4Dbbe"},{"questionId":"iZmQv9BShsBtDcDBaf8ss"}]', '["Abbreviations","Web Standards"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829330, 1773829330);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b506fff9-3e23-4347-9a21-ccce123cdbbf', 'f5335203-eb21-4d8c-bf2a-6a3ec06a440c', 'ICT', 'ई-गवर्नेंस के 4 स्तंभ हैं: लोग (People), प्रक्रिया (Process), प्रौद्योगिकी (Technology), और संसाधन (Resources)।', 'The 4 pillars of E-Governance are: People, Process, Technology, and Resources.', 'PPTR (People, Process, Technology, Resources)।', 'PPTR (People, Process, Technology, Resources).', 'गार्टनर के ई-गवर्नेंस के ''4 चरण'' (Info, Interact, Transact, Transform) अलग हैं, और ''4 स्तंभ'' (PPTR) अलग हैं।', 'Gartner''s ''4 stages'' of e-gov (Info, Interact, Transact, Transform) are different from the ''4 pillars'' (PPTR).', 'medium', 0.85, 0.9, '[{"questionId":"DDpEY-KluGxgI9i1_nRNi"}]', '["E-Governance","Frameworks"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829330, 1773829330);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('08c55291-1e34-4328-b346-9b9976e67df7', 'b4386481-85c5-4d0b-88a9-dbb9ad638af0', 'Economy', 'गुणसूत्र 21 की ट्राइसोमी (3 प्रतियाँ) ''डाउन सिंड्रोम'' (Down Syndrome) का कारण बनती है।', 'Trisomy of chromosome 21 (3 copies) causes ''Down Syndrome''.', '21 साल की उम्र में डाउन (Down at 21)।', 'Down at 21.', 'टर्नर सिंड्रोम (45,X) और क्लाइनफेल्टर सिंड्रोम (47,XXY) लिंग गुणसूत्रों से संबंधित हैं, जबकि डाउन सिंड्रोम ऑटोसोम (21वें) से संबंधित है।', 'Turner (45,X) and Klinefelter (47,XXY) relate to sex chromosomes, while Down syndrome relates to autosomes (21st).', 'medium', 0.9, 0.95, '[{"questionId":"j6Jtblty2f7wY2ZcMDiUm"}]', '["Genetics","Diseases"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829331, 1773829331);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3b6f0e7f-b132-42ba-9558-7e28d26c59d6', 'b4386481-85c5-4d0b-88a9-dbb9ad638af0', 'Economy', 'लगातार ''खेसारी दाल'' (Lathyrus sativus) खाने से पैरों में लकवा (Paralysis) हो जाता है, जिसे ''लेथाइरिज्म'' कहते हैं।', 'Continuous consumption of ''Khesari Dal'' (Lathyrus sativus) causes leg paralysis, a condition known as ''Lathyrism''.', 'खेसारी दाल = पैरों का हाल बुरा (लेथाइरिज्म)।', 'Khesari Dal = Lathyrism (Paralysis).', 'इसे प्रोटीन की कमी (क्वाशिओरकोर/मैरास्मस) से न जोड़ें, यह दाल में मौजूद न्यूरोटॉक्सिन के कारण होता है।', 'Do not link this to protein deficiency (Kwashiorkor/Marasmus); it is caused by a neurotoxin present in the dal.', 'medium', 0.82, 0.88, '[{"questionId":"7So3rQsGjUqqce0laH59I"}]', '["Human Health","Nutrition"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829331, 1773829331);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7db12809-923c-40bc-b36d-85531253d0b3', 'b4386481-85c5-4d0b-88a9-dbb9ad638af0', 'Economy', 'मानव शरीर की गर्दन में 7 ग्रीवा कशेरुकाएं (Cervical Vertebrae) होती हैं।', 'There are 7 Cervical Vertebrae in the human neck.', 'गर्दन में 7 (Cervical 7), छाती में 12 (Thoracic 12), कमर में 5 (Lumbar 5)।', 'Neck 7 (Cervical), Chest 12 (Thoracic), Waist 5 (Lumbar).', 'मनुष्य और जिराफ दोनों की गर्दन में 7 ही कशेरुकाएं होती हैं (जिराफ की बस लंबी होती हैं)।', 'Both humans and giraffes have exactly 7 cervical vertebrae (giraffes'' are just longer).', 'medium', 0.8, 0.85, '[{"questionId":"NDAU41rko-d-OBf-hsJ_d"}]', '["Human Anatomy","Skeletal System"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829331, 1773829331);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('10b35e9f-07bb-4a85-90d3-a31dc312d4d2', 'b4386481-85c5-4d0b-88a9-dbb9ad638af0', 'Economy', '2007 में बैंकिंग संशोधन द्वारा SLR (वैधानिक तरलता अनुपात) की 25% की ''न्यूनतम सीमा'' (Floor Limit) को हटा दिया गया था।', 'The 25% ''floor limit'' of SLR (Statutory Liquidity Ratio) was removed by a banking amendment in 2007.', '2007 में SLR की फर्श (Floor) हटा दी गई।', 'SLR floor was removed in 2007.', 'CRAR (कैपिटल एडिक्वेसी रेशियो) अलग है। SLR वह पैसा है जो बैंक खुद के पास सुरक्षित रखते हैं।', 'CRAR (Capital Adequacy Ratio) is different. SLR is the money banks keep safe with themselves.', 'medium', 0.8, 0.9, '[{"questionId":"MQ-2GPKuxU08LFo-HN00u"}]', '["Banking","RBI Policies"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829332, 1773829332);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('ea310643-43fa-48c7-9f1f-c0bceddce0e1', 'b4386481-85c5-4d0b-88a9-dbb9ad638af0', 'Economy', 'समग्र शिक्षा अभियान में SSA (सर्व शिक्षा), RMSA (राष्ट्रीय माध्यमिक) और TE (शिक्षक शिक्षा) को मिला दिया गया है।', 'Samagra Shiksha Abhiyan merges SSA (Sarva Shiksha), RMSA (Rashtriya Madhyamik), and TE (Teacher Education).', 'समग्र = सब कुछ (Primary + Secondary + Teachers)।', 'Samagra = Everything (Primary + Secondary + Teachers).', 'रूसा (RUSA - उच्च शिक्षा) इसमें शामिल नहीं है। यह केवल स्कूली शिक्षा के लिए है।', 'RUSA (Higher Education) is NOT included. This is only for school education.', 'medium', 0.85, 0.88, '[{"questionId":"WK126j9lYS3DBOzrgwOGW"}]', '["Government Schemes","Education"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829332, 1773829332);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4688a4f2-05f7-4e54-b66d-e6a9b3d9d924', '3177dad0-3044-4b4b-a5cc-59b536b6c2e0', 'Current Affairs', 'पहला G20 ''नेताओं का शिखर सम्मेलन'' (Leaders'' Summit) 2008 में वाशिंगटन डी.सी. (USA) में हुआ था।', 'The first G20 ''Leaders'' Summit'' was held in Washington D.C. (USA) in 2008.', '2008 की मंदी (Crisis) -> वाशिंगटन में पहली मीटिंग (First Summit)।', '2008 Crisis -> First Summit in Washington.', 'G20 की स्थापना 1999 में हुई थी (वित्त मंत्रियों के स्तर पर), लेकिन ''शिखर सम्मेलन'' (राष्ट्रपतियों/प्रधानमंत्रियों का) 2008 में शुरू हुआ।', 'G20 was founded in 1999 (at Finance Ministers'' level), but the ''Leaders'' Summit'' started in 2008.', 'medium', 0.85, 0.9, '[{"questionId":"tGuOzM3yQq0Rx8NZnOYVZ"}]', '["International Organizations","Summits"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829343, 1773829343);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6b7596e0-91e5-4fe1-a0b5-9b2856b8a47d', '3177dad0-3044-4b4b-a5cc-59b536b6c2e0', 'Current Affairs', 'नीति आयोग के SDG इंडेक्स की श्रेणियां: Aspirant (0-49), Performer (50-64), Front-runner (65-99), और Achiever (100)।', 'Categories of NITI Aayog''s SDG Index: Aspirant (0-49), Performer (50-64), Front-runner (65-99), and Achiever (100).', 'A-P-F-A (Aspirant, Performer, Front-runner, Achiever). 50 और 65 कटऑफ हैं।', 'A-P-F-A (Aspirant, Performer, Front-runner, Achiever). 50 and 65 are cutoffs.', 'स्कोर रेंज को ध्यान से याद रखें। 65 से ''फ्रंट-रनर'' शुरू होता है, 60 से नहीं।', 'Memorize the score ranges carefully. ''Front-runner'' starts from 65, not 60.', 'medium', 0.9, 0.95, '[{"questionId":"2IwYnEcAbE-dXpaazt1ED"}]', '["NITI Aayog","Indices","SDG"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829343, 1773829343);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5cc730d8-fc25-45fb-90f4-cee0eb05b32b', 'd737bfd1-8a80-441f-8437-2f599dd9911a', 'MP GK', 'MP की प्रति व्यक्ति आय भारत की औसत आय से काफी कम है (स्थिर कीमतों पर)। भारत के कुल कारखानों में MP का हिस्सा मात्र ~1.9% है।', 'MP''s per capita income is significantly lower than India''s average (at constant prices). MP''s share in India''s total factories is merely ~1.9%.', 'MP कृषि प्रधान (Agriculture dominant) है, कारखाने (Factories) बहुत कम (<2%) हैं।', 'MP is Agriculture dominant, Factories are very few (<2%).', 'MP के ''तेज विकास दर'' के दावों के बावजूद, औद्योगिक आधार (Industrial base) और प्रति व्यक्ति आय के निरपेक्ष मूल्य (Absolute value) अभी भी राष्ट्रीय औसत से पीछे हैं।', 'Despite claims of MP''s ''fast growth rate'', the absolute values of industrial base and per capita income still lag behind the national average.', 'medium', 0.88, 0.92, '[{"questionId":"C1s-ToKUNAQlaW6YpH7kv"},{"questionId":"zK2rXE6tg1oiogLEX750F"}]', '["Macroeconomics","Industrial Data"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829343, 1773829343);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b6819e47-b0ec-4dd4-9ffe-a27be636c0a7', 'd737bfd1-8a80-441f-8437-2f599dd9911a', 'MP GK', 'MP में सोयाबीन की खेती देवास (1962) से शुरू हुई। गेहूं MP की दूसरी सबसे महत्वपूर्ण फसल है (धान के बाद क्षेत्रफल में)।', 'Soybean cultivation in MP started from Dewas (1962). Wheat is MP''s second most important crop (after paddy in area).', 'सोयाबीन का ''देव'' (Dewas for Soya)।', 'Dewas for Soya.', 'गेहूं उत्पादन में MP अक्सर भारत में दूसरे/तीसरे स्थान पर रहता है (UP और पंजाब के साथ प्रतिस्पर्धा), लेकिन राज्य के भीतर फसल क्षेत्रफल (Crop Area) के आधार पर आयोग ने इसे ''द्वितीय'' (Second) माना है।', 'In wheat production, MP often ranks 2nd/3rd in India (competing with UP/Punjab), but based on crop area within the state, the commission considered it ''Second''.', 'medium', 0.85, 0.9, '[{"questionId":"9KQ949bF5-GI2fazK3PoH"},{"questionId":"rA5A-2Pj4ORyx1VPBMnFw"}]', '["Agriculture History","Crop Ranking"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829344, 1773829344);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a5cf4a40-ed1b-4d6f-850d-c50cf3295ee9', 'd737bfd1-8a80-441f-8437-2f599dd9911a', 'MP GK', 'सरदार सरोवर परियोजना (नर्मदा) 4 राज्यों (MP, GJ, MH, RJ) की संयुक्त परियोजना है।', 'Sardar Sarovar Project (Narmada) is a joint project of 4 states (MP, GJ, MH, RJ).', 'सरदार के 4 राज्य (MP, GJ, MH, RJ)।', 'Sardar''s 4 states (MP, GJ, MH, RJ).', 'राजस्थान को केवल पानी (सिंचाई/पेयजल) मिलता है, बिजली (Hydro-electricity) नहीं। बिजली MP (57%), MH (27%) और GJ (16%) में बंटती है।', 'Rajasthan only gets water (irrigation/drinking), not hydro-electricity. Power is shared among MP (57%), MH (27%) and GJ (16%).', 'medium', 0.92, 0.96, '[{"questionId":"4LMrgV4VDvoP8QBermgt4"}]', '["Irrigation Projects","Interstate Treaties"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829344, 1773829344);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b17637b6-0d6c-4a5c-9ceb-4e13d329c97f', 'd737bfd1-8a80-441f-8437-2f599dd9911a', 'MP GK', 'चिन्नौर चावल (GI टैग) बालाघाट का उत्पाद है। UNNATI (एग्री-जीआईएस) मृदा/फसल मानचित्रण परियोजना है।', 'Chinnor Rice (GI Tag) is a product of Balaghat. UNNATI (Agri-GIS) is a soil/crop mapping project.', 'चिन्नौर की महक बालाघाट में (Chinnor''s aroma in Balaghat)। उन्नति = सैटेलाइट से खेती (UNNATI = Farming via satellite)।', 'Chinnor''s aroma in Balaghat. UNNATI = Farming via satellite.', 'जीआई टैग उत्पादों को उनके विशिष्ट जिलों से मिलाना अत्यंत आवश्यक है (जैसे मुरैना की गजक, रीवा का सुंदरजा आम)।', 'Matching GI tag products with their specific districts is absolutely essential (e.g., Morena Gajak, Rewa Sunderja Mango).', 'medium', 0.9, 0.94, '[{"questionId":"YrigDczNdsfNE_Nw2ESNm"},{"questionId":"Im_c3XvIrzkGV-wugyRhN"}]', '["GI Tags","Agri-Tech"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829344, 1773829344);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e3ae17f8-697c-421b-a0b8-9e115ec8b00b', '084bb18e-c113-498f-8654-93d202c646be', 'MP GK', 'गोंड जनजाति का त्यौहार ''मांडवरा'' है। ''बिरहा'' गोंड/बैगा महिलाओं का लोकगीत (बघेलखंड) है। ''कोहबर'' विवाह का भित्ति चित्र (बघेलखंड/मिथिला) है।', '''Mandavara'' is a festival of the Gond tribe. ''Birha'' is a folk song (Baghelkhand) of Gond/Baiga women. ''Kohbar'' is a marriage wall painting (Baghelkhand/Mithila).', 'मांडवरा-गोंड। बिरहा-बघेलखंड। कोहबर-विवाह कक्ष (Marriage room)।', 'Mandavara-Gond. Birha-Baghelkhand. Kohbar-Marriage room.', 'लोकगीतों और भित्ति चित्रों के ''क्षेत्र'' (Region) बहुत पूछे जाते हैं (मालवा, निमाड़, बुंदेलखंड, बघेलखंड)। क्षेत्र को स्पष्ट रूप से याद रखें।', 'The ''Region'' of folk songs and paintings is highly tested. Remember the region clearly.', 'medium', 0.9, 0.94, '[{"questionId":"CA1qGTX2ZUFfYGl-82Zn6"},{"questionId":"8_j3rUz_rXGP4Gl7leJF1"},{"questionId":"FxlLJM4IpJxHIC3psjt-w"}]', '["Folk Culture","Tribal Festivals"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829345, 1773829345);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9636024c-23fd-47c7-8c43-3e40c4f1ca83', '084bb18e-c113-498f-8654-93d202c646be', 'MP GK', 'ओम प्रकाश शर्मा ''माच'' (मालवा) के कलाकार हैं। गम्मत (निमाड़) के सूत्रधार को ''कुड़गर्‍या'' कहते हैं। शंकर राव पंडित ख्याल गायन (ग्वालियर घराना) से जुड़े थे।', 'Om Prakash Sharma is an artist of ''Maach'' (Malwa). The narrator of Gammat (Nimar) is called ''Kudgarya''. Shankar Rao Pandit was associated with Khayal singing (Gwalior Gharana).', 'माच के ओम (Om of Maach)। गम्मत का जोकर कुड़गर्‍या (Joker of Gammat Kudgarya)। ग्वालियर का ख्याल (Gwalior''s Khayal)।', 'Om of Maach. Joker of Gammat Kudgarya. Gwalior''s Khayal.', '''माच'' मालवा का है, ''गम्मत'' निमाड़ का है। दोनों लोकनाट्य हैं, इनके क्षेत्रों को आपस में न बदलें।', '''Maach'' is from Malwa, ''Gammat'' is from Nimar. Both are folk dramas, do not swap their regions.', 'medium', 0.92, 0.96, '[{"questionId":"kX1cZ836eD501EUg9hVhO"},{"questionId":"m1-0s7MbDObyAYt9oDi_W"},{"questionId":"m_Nfn6H5A7uehPd_ATrWg"}]', '["Folk Drama","Classical Music"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829345, 1773829345);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('02698e2b-909c-4f0e-86fa-8cee198d3885', '084bb18e-c113-498f-8654-93d202c646be', 'MP GK', '''देवी अहिल्या सम्मान'' आदिवासी कलाओं के लिए केवल ''महिलाओं'' को दिया जाता है। ''वीर शंकर शाह-रघुनाथ शाह सम्मान'' जनजातीय जीवन पर ''साहित्य'' के लिए है।', '''Devi Ahilya Samman'' is given only to ''women'' for tribal arts. ''Veer Shankar Shah-Raghunath Shah Samman'' is for ''literature'' on tribal life.', 'अहिल्या = महिला कलाकार (Women artists)। शंकर-रघुनाथ = साहित्यकार (Writers)।', 'Ahilya = Women artists. Shankar-Raghunath = Writers.', 'तुलसी सम्मान (केवल पुरुषों के लिए) और देवी अहिल्या सम्मान (केवल महिलाओं के लिए) के बीच का लिंग-भेद (Gender distinction) बहुत महत्वपूर्ण है।', 'The gender distinction between Tulsi Samman (Men only) and Devi Ahilya Samman (Women only) is highly critical.', 'medium', 0.88, 0.95, '[{"questionId":"N1NuuUU8KrjmfW2qoml_D"},{"questionId":"mZE7PuPdFn5tIXCznnpxW"}]', '["State Awards"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829345, 1773829345);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('2f99edd9-6c6b-4661-a241-df6f60b1d67a', '084bb18e-c113-498f-8654-93d202c646be', 'MP GK', '2011 जनगणना: भोपाल में नगरीय जनसंख्या का प्रतिशत सर्वाधिक (80.9%) है। अटल बिहारी वाजपेयी सुशासन संस्थान (AIGGPA) भोपाल में है।', '2011 Census: Bhopal has the highest percentage of urban population (80.9%). Atal Bihari Vajpayee Institute of Good Governance (AIGGPA) is in Bhopal.', 'राजधानी भोपाल सबसे ''शहरी'' (Urban) और ''सुशासन'' (Governance) का केंद्र है।', 'Capital Bhopal is the most ''Urban'' and center of ''Governance''.', 'कुल ''संख्या'' में सबसे बड़ा शहर इंदौर है, लेकिन ''प्रतिशत'' (Percentage) के आधार पर सबसे शहरीकृत जिला भोपाल है।', 'In absolute ''numbers'', Indore is the largest city, but in terms of ''percentage'', Bhopal is the most urbanized district.', 'medium', 0.9, 0.92, '[{"questionId":"jZjlhIg9VIfdbr308vxyY"},{"questionId":"suT1_Zz4rt3TLLyFsUBX2"}]', '["Census","Institutes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829345, 1773829345);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c91a1d78-deed-46ef-bdde-553b1ff92566', '395a2471-0203-4ae8-be96-83c9383a4e83', 'MP GK', 'MP के दक्षिण-पूर्वी भाग (शहडोल/बालाघाट) में ''बंगाल की खाड़ी'' शाखा से सर्वाधिक वर्षा होती है। काली मिट्टी बेसाल्ट चट्टानों (दक्कन ट्रैप) से बनी है।', 'SE part of MP (Shahdol/Balaghat) receives maximum rainfall from ''Bay of Bengal'' branch. Black soil is formed from Basalt rocks (Deccan Trap).', 'पूरब में बंगाल की खाड़ी (East = Bay of Bengal)। काली मिट्टी = बेसाल्ट (Black = Basalt)।', 'East = Bay of Bengal. Black = Basalt.', 'MP के पश्चिमी भाग (मालवा) में वर्षा मुख्य रूप से ''अरब सागर'' शाखा से होती है।', 'Western MP (Malwa) receives rainfall mainly from the ''Arabian Sea'' branch.', 'medium', 0.9, 0.94, '[{"questionId":"kv27qq-58nkpXaP2oLa_n"},{"questionId":"vsas89U2AS2ZdcDjCyNCH"}]', '["Monsoon","Soils"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829347, 1773829347);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('12bd0068-1dc9-4f37-94e3-ae74f7118412', '395a2471-0203-4ae8-be96-83c9383a4e83', 'MP GK', 'विन्ध्यन स्कार्पलैण्ड का दक्षिणी भाग ''भाण्डेर पठार'' कहलाता है। लमहेटा गाँव (जबलपुर) में भारत का पहला ''जियो पार्क'' बनेगा।', 'Southern part of Vindhyan Scarpland is ''Bhander Plateau''. Lamheta village (Jabalpur) will host India''s first ''Geo Park''.', 'विंध्य के दक्षिण में भाण्डेर (Bhander south of Vindhya)। डायनासोर का लमहेटा (Dinosaur''s Lamheta)।', 'Bhander south of Vindhya. Dinosaur''s Lamheta.', 'अमरकंटक मैकाल श्रेणी का हिस्सा है (सतपुड़ा का भाग), विंध्य का नहीं।', 'Amarkantak is part of Maikal range (Satpura), not Vindhya.', 'medium', 0.85, 0.9, '[{"questionId":"0myVeEDl2euP9uAMxaWh6"},{"questionId":"UAWNFeURqDM67rKLzTgqh"}]', '["Geomorphology","Current Projects"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829347, 1773829347);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c51d0399-d956-4ec5-aebe-931a39ec2f94', '395a2471-0203-4ae8-be96-83c9383a4e83', 'MP GK', 'घाटीगाँव अभयारण्य ग्वालियर में है (सोन चिड़िया के लिए)। बाँस का राष्ट्रीयकरण 1973 में हुआ। रॉक फॉस्फेट (झाबुआ) का उपयोग उर्वरक उद्योग में होता है।', 'Ghatigaon sanctuary is in Gwalior (for Great Indian Bustard). Bamboo nationalization happened in 1973. Rock Phosphate (Jhabua) is used in fertilizer industry.', 'ग्वालियर की घाटी (Valley of Gwalior)। 73 का बांस (Bamboo of 73)। फॉस्फेट = खाद (Fertilizer)।', 'Valley of Gwalior. Bamboo of 73. Phosphate = Fertilizer.', 'तेंदूपत्ता का राष्ट्रीयकरण पहले (1964) हुआ था, बाँस का बाद में (1973)।', 'Tendu leaf was nationalized first (1964), Bamboo later (1973).', 'medium', 0.88, 0.92, '[{"questionId":"hyKCoaguUexF9xWr_m7YB"},{"questionId":"djA6aujlhzbWWrRQUoeSn"},{"questionId":"VKnNRzM3nFgbdhQyUPcuw"}]', '["Wildlife","Forestry","Minerals"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829347, 1773829347);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5c4344fc-6efa-454b-93b8-7c99decb4ec2', '395a2471-0203-4ae8-be96-83c9383a4e83', 'MP GK', 'आदिवासी नायक: टंट्या मामा (भील), रघुनाथ सिंह मण्डलोई (भिलाला - निमाड़ 1857), बादल भोई (गोंड - छिंदवाड़ा)। भिम्मा गोंडों की उप-जाति है।', 'Tribal Heroes: Tantia Mama (Bhil), Raghunath Singh Mandloi (Bhilala - Nimar 1857), Badal Bhoi (Gond - Chhindwara). Bhimma is a sub-caste of Gonds.', 'टंट्या मामा (भील)। बादल भोई (छिंदवाड़ा)। रघुनाथ (निमाड़)।', 'Tantia Mama (Bhil). Badal Bhoi (Chhindwara). Raghunath (Nimar).', 'इन स्वतंत्रता सेनानियों की जनजातीय संबद्धता (Tribal Affiliation) और उनके कार्यक्षेत्र (Region) का सटीक मिलान करना सबसे ज्यादा जरूरी है।', 'It is absolutely crucial to accurately match the tribal affiliation and the region of operation for these freedom fighters.', 'medium', 0.95, 0.98, '[{"questionId":"lDDJfT5u8Zypg9lYx8azb"},{"questionId":"SeoEcWR_9N-6P5cXJAsWq"},{"questionId":"crbUhcjbA9luJxIHDnKad"},{"questionId":"yb4YdfgBh8Nqo-W5JyjnR"}]', '["Tribal Personalities","Freedom Fighters"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829347, 1773829347);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d92d8acc-f2ca-4603-9052-c69e3133a67e', '395a2471-0203-4ae8-be96-83c9383a4e83', 'MP GK', 'BHEL (भोपाल) ब्रिटेन के सहयोग से बना। ''वन्या'' प्रतिष्ठान (जनजातीय साहित्य) 1980 में स्थापित। प्राची यादव (ग्वालियर) पैरा-कैनो अर्जुन अवार्डी हैं।', 'BHEL (Bhopal) was built with Britain''s help. ''Vanya'' establishment (Tribal literature) was founded in 1980. Prachi Yadav (Gwalior) is a Para-Canoe Arjuna Awardee.', 'BHEL = Britain। वन्या 1980। प्राची यादव नाव (Canoe) चलाती हैं।', 'BHEL = Britain. Vanya 1980. Prachi Yadav rows canoe.', 'BHEL भोपाल ब्रिटेन के सहयोग से बना था, जबकि भिलाई स्टील प्लांट (छत्तीसगढ़, पहले MP) रूस के सहयोग से बना था।', 'BHEL Bhopal was built with British help, while Bhilai Steel Plant (CG, formerly MP) was built with Russian help.', 'medium', 0.85, 0.9, '[{"questionId":"qP9ttT7wWqMHRlA4pVpfJ"},{"questionId":"knI7InADFhcm31OmKMmty"},{"questionId":"V-4yF8kRY1wZBOhF_i-nC"}]', '["Industries","Institutions","Sports Personalities"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829348, 1773829348);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a5d2d024-557a-4795-9729-079762affe13', '395a2471-0203-4ae8-be96-83c9383a4e83', 'MP GK', 'नर्मदा का पहला साहित्यिक उल्लेख ''शतपथ ब्राह्मण'' (रेवोत्तरस) में है। कायथा (उज्जैन) वराहमिहिर की जन्मस्थली है। मोहनखेड़ा (धार) जैन तीर्थ है।', 'First literary mention of Narmada is in ''Shatapatha Brahmana'' (Revottaras). Kaytha (Ujjain) is Varahamihira''s birthplace. Mohankheda (Dhar) is a Jain pilgrimage.', 'शतपथ की रेवा (Narmada)। कायथा का वराह (Varahamihira)। मोहनखेड़ा जैन तीर्थ।', 'Shatapatha''s Rewa (Narmada). Kaytha''s Varaha (Varahamihira). Mohankheda Jain site.', 'कायथा (उज्जैन) ताम्रपाषाण स्थल है और वराहमिहिर की जन्मस्थली है, जबकि एरण (सागर) सती प्रथा के साक्ष्य के लिए जाना जाता है।', 'Kaytha (Ujjain) is a chalcolithic site and Varahamihira''s birthplace, whereas Eran (Sagar) is known for evidence of Sati.', 'medium', 0.9, 0.94, '[{"questionId":"3I9VDv-ly-gBSZ-kkAYUi"},{"questionId":"0N3KQgigTyGzmu1A05LOP"},{"questionId":"EqUAIE_AJqmT5ZiyIReCr"}]', '["Ancient MP","Pilgrimage"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829348, 1773829348);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('adec81c3-23cc-4d58-8067-00125cf39fd3', '2447de5b-d3c7-4361-a7f2-71af9b24a8b3', 'Polity', 'चंपकम दोराईराजन (1951) केस में SC ने DPSP पर मौलिक अधिकारों (FRs) की सर्वोच्चता घोषित की। 44वें संशोधन (1978) ने आपातकाल (Art 352) के लिए ''कैबिनेट की लिखित सलाह'' अनिवार्य की।', 'In Champakam Dorairajan (1951) case, SC declared FRs supreme over DPSP. 44th Amendment (1978) mandated ''written advice of Cabinet'' for Emergency (Art 352).', 'चंपकम = FR > DPSP। 44वां संशोधन = मोरारजी देसाई ने आपातकाल कड़ा किया (Written advice)।', 'Champakam = FR > DPSP. 44th Amendment = Morarji Desai tightened Emergency rules.', 'आपातकाल के लिए केवल ''प्रधानमंत्री'' की सलाह पर्याप्त नहीं है (1975 में ऐसा ही हुआ था), अब ''कैबिनेट'' की लिखित सलाह चाहिए।', 'Advice from just the ''Prime Minister'' is not enough for Emergency (as happened in 1975); now written advice from the ''Cabinet'' is required.', 'medium', 0.95, 0.98, '[{"questionId":"6o0Zp08TqOlWrpfecYVQj"},{"questionId":"6P3jtLkler4873nxNkYob"}]', '["Landmark Cases","Amendments","Emergency"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829349, 1773829349);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0d9c0f3c-d61b-4315-9622-028124009ce5', '2447de5b-d3c7-4361-a7f2-71af9b24a8b3', 'Polity', 'महान्यायवादी (AG - Art 76) बनने के लिए सुप्रीम कोर्ट के जज की योग्यता चाहिए। महाधिवक्ता (Advocate General - Art 165) ''राज्यपाल के प्रसादपर्यंत'' पद पर रहता है (मंत्रिमंडल के नहीं)।', 'To become Attorney General (AG - Art 76), qualifications of a Supreme Court judge are needed. Advocate General (Art 165) holds office during the ''pleasure of the Governor'' (not Cabinet).', 'AG = SC Judge Level। AG State = Pleasure of Governor।', 'AG = SC Judge Level. AG State = Pleasure of Governor.', 'महाधिवक्ता सरकार को सलाह देता है, लेकिन वह ''मंत्रिमंडल के प्रसादपर्यंत'' नहीं, बल्कि ''राज्यपाल के प्रसादपर्यंत'' कार्य करता है।', 'Advocate General advises the govt, but works at the ''pleasure of the Governor'', not the ''pleasure of the Cabinet''.', 'medium', 0.92, 0.95, '[{"questionId":"eKC1-QQpM_el-kw6FaeMS"},{"questionId":"G7GCiEXC_icT3eWlJ6iEJ"}]', '["Constitutional Bodies","State Executive"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829349, 1773829349);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('184fea2c-5b63-4673-8775-94be29441303', '2447de5b-d3c7-4361-a7f2-71af9b24a8b3', 'Polity', 'चुनाव आयोग (EC) में CEC और ECs के बीच मतभेद होने पर निर्णय ''बहुमत'' (Majority) से होता है।', 'In the Election Commission (EC), if there''s a difference of opinion between CEC and ECs, the decision is taken by ''Majority''.', 'Election Commission = 3 Member Body (Decision by 2-1 Majority).', 'Election Commission = 3 Member Body (Decision by 2-1 Majority).', 'मुख्य चुनाव आयुक्त (CEC) के पास ''वीटो'' शक्ति नहीं होती। सभी तीनों आयुक्तों की शक्ति समान (Equal) होती है।', 'Chief Election Commissioner (CEC) does NOT have veto power. All three commissioners have equal power.', 'medium', 0.85, 0.9, '[{"questionId":"xrrDBGuAcFBTi7MhrgPWZ"}]', '["Election Commission"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829349, 1773829349);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('41f2805d-4814-4d78-aed0-44de9c84588c', '2447de5b-d3c7-4361-a7f2-71af9b24a8b3', 'Polity', 'GST परिषद (Art 279A) जैसे संघीय ढांचे (Federal) के संशोधनों के लिए संसद के साथ कम से कम ''आधे राज्यों'' के अनुसमर्थन की आवश्यकता होती है। 11वीं अनुसूची में पंचायतों के 29 विषय हैं।', 'Amendments to federal structures like GST Council (Art 279A) require ratification by at least ''half the states'' along with Parliament. 11th Schedule has 29 subjects for Panchayats.', 'Federal Tax (GST) = Half States Must Agree। 11th Schedule = 2+9=11 (29 subjects)।', 'Federal Tax (GST) = Half States Must Agree. 11th Schedule = 2+9=11 (29 subjects).', 'साधारण विधेयक या नागरिकता से जुड़े मामलों में राज्यों के अनुसमर्थन की आवश्यकता नहीं होती, केवल संघीय ढांचे (Federal Structure) में होती है।', 'Ordinary bills or citizenship matters don''t need state ratification; it''s only for the Federal Structure.', 'medium', 0.9, 0.92, '[{"questionId":"D1JzoGZtnO7KBLYLgZRL0"},{"questionId":"gO402VwuH6znjMqTiQPR9"}]', '["Amendment Process","Panchayati Raj"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829349, 1773829349);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('78afdfe6-05dc-4a0a-9ffa-51251db568de', '2447de5b-d3c7-4361-a7f2-71af9b24a8b3', 'Polity', 'के.एम. मुंशी (K.M. Munshi) संविधान सभा की ''प्रारूप समिति'' (Drafting Committee) के सदस्य थे।', 'K.M. Munshi was a member of the ''Drafting Committee'' of the Constituent Assembly.', 'मुंशी जी ड्राफ्टिंग में थे (Munshi ji was in Drafting)।', 'Munshi ji was in Drafting.', 'प्रारूप समिति के 7 सदस्यों के नाम याद रखें। मुंशी जी एकमात्र ऐसे सदस्य थे जो मूल रूप से कांग्रेसी थे।', 'Remember the names of all 7 members of the Drafting Committee. Munshi ji was the only original Congressman.', 'medium', 0.8, 0.85, '[{"questionId":"W713WidEbcavhai5EqJZ4"}]', '["Constituent Assembly","Drafting Committee"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829349, 1773829349);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('bf26fa2c-68dc-4fb9-8c7d-f6433cd5bd01', 'b6e19726-f0a7-4983-8d7e-5b769b3fa900', 'Science', 'ISRO ने 2017 में PSLV-C37 रॉकेट का उपयोग करके एक ही उड़ान में 104 उपग्रह लॉन्च करके विश्व रिकॉर्ड बनाया था।', 'ISRO set a world record in 2017 by launching 104 satellites in a single flight using the PSLV-C37 rocket.', 'PSLV-C37 ने 104 का ''सेंचुरी'' (Century) मारा।', 'PSLV-C37 hit a ''Century'' of 104.', 'यह रिकॉर्ड 2021 में SpaceX (143 सैटेलाइट) ने तोड़ा, लेकिन भारत के इतिहास का यह सबसे बड़ा रिकॉर्ड (PSLV-C37) बार-बार पूछा जाता है।', 'This record was broken by SpaceX (143 satellites) in 2021, but this biggest record in Indian history (PSLV-C37) is repeatedly asked.', 'medium', 0.9, 0.95, '[{"questionId":"97wQt8ND0zT6JeLq-PXUw"}]', '["ISRO","Space Records"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829349, 1773829349);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('14ca4860-f1eb-4143-9e0a-2ba8f9035833', 'b6e19726-f0a7-4983-8d7e-5b769b3fa900', 'Science', 'मंगलयान (Mars Orbiter Mission - MOM), भारत का पहला अंतर-ग्रहीय मिशन, 5 नवंबर 2013 को सफलतापूर्वक लॉन्च किया गया था।', 'Mangalyaan (Mars Orbiter Mission - MOM), India''s first inter-planetary mission, was successfully launched on November 5, 2013.', '2013 में मंगल पर भारत का ''मंगल'' (Auspicious) प्रवेश।', 'India''s ''Mangal'' entry to Mars in 2013.', 'लॉन्च 2013 में हुआ था, लेकिन यह मंगल की कक्षा में 2014 में पहुंचा था। लॉन्च वर्ष (2013) याद रखें।', 'It was launched in 2013, but reached Mars orbit in 2014. Remember the launch year (2013).', 'medium', 0.95, 0.98, '[{"questionId":"Q30kqgr46rBful-ejQtkl"}]', '["Inter-planetary Missions","ISRO History"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829350, 1773829350);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('eabcd111-9591-4a6f-b9ef-e2e618412845', '3d7d42aa-dd68-4046-82fc-92b54b497c84', 'ICT', 'न्यायमूर्ति ए.एम. खानविलकर को 2024 में भारत का (दूसरा) लोकपाल अध्यक्ष नियुक्त किया गया है। सी.आर. राव को सांख्यिकी का 2023 का अंतर्राष्ट्रीय पुरस्कार मिला।', 'Justice A.M. Khanwilkar was appointed as the (second) Lokpal Chairman of India in 2024. C.R. Rao received the 2023 International Prize in Statistics.', 'लोकपाल = खानविलकर। सांख्यिकी के ''राव'' (Rao of Statistics)।', 'Lokpal = Khanwilkar. ''Rao'' of Statistics.', 'पिनाकी चंद्र घोष पहले लोकपाल थे, खानविलकर वर्तमान (2024) हैं।', 'Pinaki Chandra Ghose was the first Lokpal; Khanwilkar is the current (2024).', 'medium', 0.85, 0.95, '[{"questionId":"7kps5gEA8N3B_UMKbv1FR"},{"questionId":"CgOAv5Fa94WOv4rChsFBQ"}]', '["Appointments","Awards"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829365, 1773829365);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a991c50e-0b85-4b91-8f8e-26988e4f301f', '3d7d42aa-dd68-4046-82fc-92b54b497c84', 'ICT', 'सुधा मूर्ति को मार्च 2024 में राज्यसभा के 12वें सदस्य के रूप में मनोनीत किया गया।', 'Sudha Murty was nominated as the 12th member of Rajya Sabha in March 2024.', 'राज्यसभा में परोपकार की ''मूर्ति'' (Murty of philanthropy in RS)।', 'Murty of philanthropy in RS.', 'वे इंफोसिस फाउंडेशन से जुड़ी हैं, इसे उनकी नियुक्ति का एकमात्र आधार न समझें, उन्हें साहित्य और समाज सेवा के लिए चुना गया है।', 'She is associated with Infosys Foundation, don''t consider it the sole basis; she was chosen for literature and social service.', 'medium', 0.8, 0.88, '[{"questionId":"jPJqG0xoZbEqI3PCskgQV"}]', '["Polity Current Affairs","Nominations"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829365, 1773829365);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4d5bba06-6991-405c-a082-9c60005a77e9', '3d7d42aa-dd68-4046-82fc-92b54b497c84', 'ICT', 'डी. गुकेश 17 वर्ष की आयु में FIDE कैंडिडेट्स (शतरंज) जीतने वाले सबसे कम उम्र के खिलाड़ी बने। भारत ने इंग्लैंड को 2024 की टेस्ट श्रृंखला में 4-1 से हराया।', 'D. Gukesh became the youngest player to win FIDE Candidates (Chess) at age 17. India beat England 4-1 in the 2024 Test series.', 'शतरंज का युवा बादशाह ''गुकेश''। क्रिकेट में 4-1 से जीत (Hit a Four and won)।', 'Young King of Chess ''Gukesh''. Won 4-1 in cricket (Hit a Four and won).', 'कैंडिडेट्स में प्रज्ञानानंद भी थे, लेकिन विजेता गुकेश रहे।', 'Praggnanandhaa was also in Candidates, but the winner was Gukesh.', 'medium', 0.9, 0.92, '[{"questionId":"Suh_MLyzgecT7X55PGw3P"},{"questionId":"z1QMFvIyxa-i47xHeCXKd"}]', '["Sports","Chess","Cricket"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829365, 1773829365);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e5e58e91-bf66-43c7-96a2-7c3b54d2d647', 'd99b61cb-66d1-4511-a938-ca39e91f899c', 'Geography', 'जल (प्रदूषण निवारण एवं नियंत्रण) अधिनियम 1974 में पारित हुआ था।', 'The Water (Prevention and Control of Pollution) Act was passed in 1974.', '74 का जल (Water of ''74)।', 'Water of ''74.', 'पर्यावरण संरक्षण अधिनियम 1986 में है, जबकि जल अधिनियम 1974 और वायु अधिनियम 1981 में आया था।', 'Environment Protection Act is 1986, while Water Act came in 1974 and Air Act in 1981.', 'medium', 0.9, 0.95, '[{"questionId":"uEkieDzhrulR3N1I6-i77"}]', '["Environment Acts"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829366, 1773829366);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b96215a7-3be4-409f-9b76-773d662cb0fd', 'd99b61cb-66d1-4511-a938-ca39e91f899c', 'Geography', 'विश्व की पहली ''वैदिक घड़ी'' उज्जैन (जंतर-मंतर) में स्थापित की गई है (मार्च 2024)।', 'The world''s first ''Vedic Clock'' has been installed in Ujjain (Jantar Mantar) in March 2024.', 'उज्जैन: महाकाल और वैदिक समय का केंद्र (Greenwich of India)।', 'Ujjain: Center of Mahakal and Vedic Time (Greenwich of India).', 'इसे जयपुर या दिल्ली के जंतर-मंतर से भ्रमित न करें, यह म.प्र. के उज्जैन में है।', 'Do not confuse it with Jaipur or Delhi Jantar Mantar; it is in Ujjain, MP.', 'medium', 0.88, 0.92, '[{"questionId":"PrOPRJ3p7Zcrqia920Vcs"}]', '["MP Current Affairs","First in World"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829366, 1773829366);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('bde6c4fb-3384-4eda-847f-e1d35788a8cf', 'd99b61cb-66d1-4511-a938-ca39e91f899c', 'Geography', 'राष्ट्रीय स्वास्थ्य नीति 2017 में ''यात्री सुरक्षा'' (रेलवे) शामिल नहीं है; यह ''स्वच्छ भारत'', ''निर्भया नारी'' और पोषण पर केंद्रित है।', 'National Health Policy 2017 does not include ''Yatri Suraksha'' (railways); it focuses on ''Swachh Bharat'', ''Nirbhaya Nari'', and nutrition.', 'यात्री सुरक्षा रेलवे का काम है, स्वास्थ्य नीति का नहीं।', 'Passenger safety is Railways'' job, not Health Policy.', 'स्वास्थ्य नीति के सात प्राथमिकता वाले क्षेत्रों (7 Priority Areas) को एक बार सरसरी तौर पर देख लें।', 'Briefly review the 7 priority areas of the Health Policy.', 'medium', 0.75, 0.85, '[{"questionId":"0TAj19hrUa9GUUbBdWG77"}]', '["Government Policies"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829366, 1773829366);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('93993e6e-8d3a-400f-b330-38e9779d0f77', 'cc283dd9-e577-48b4-b3a3-f22db60045e8', 'Geography', 'तौक्ते (Tauktae) चक्रवात मई 2021 में भारत के पश्चिमी तट (गुजरात/महाराष्ट्र) पर आया था।', 'Cyclone Tauktae hit the western coast of India (Gujarat/Maharashtra) in May 2021.', 'तौक्ते (Tauktae) = पश्चिमी तट (West Coast) पर तबाही।', 'Tauktae = Havoc on the West Coast.', 'इसे ''यास'' (Yaas) चक्रवात से न मिलाएं, जो 2021 में ही पूर्वी तट (बंगाल/ओडिशा) पर आया था।', 'Do not mix it up with Cyclone ''Yaas'', which hit the East Coast (Bengal/Odisha) in 2021.', 'medium', 0.85, 0.88, '[{"questionId":"yN-sVoF-VwjLM0BzAIc6T"}]', '["Disaster Management","Cyclones"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829366, 1773829366);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a1857e34-3fd9-4255-835c-9700139a8af7', 'cc283dd9-e577-48b4-b3a3-f22db60045e8', 'Geography', 'ओज़ोन परत की मोटाई डब्सन (Dobson Unit - DU) में मापी जाती है।', 'Ozone layer thickness is measured in Dobson Units (DU).', 'डब्सन = ओज़ोन की ढाल (Defense)।', 'Dobson = Ozone Defense.', 'डेसिबल (Decibel) ध्वनि की तीव्रता मापता है, डब्सन (Dobson) ओज़ोन की मोटाई।', 'Decibel measures sound intensity, Dobson measures ozone thickness.', 'medium', 0.9, 0.96, '[{"questionId":"tGcleimsrbdupEiQF_B0w"}]', '["Units of Measurement","Environment"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829366, 1773829366);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b26458e9-ccb8-4e42-a79b-7e0f60233c7f', 'cc283dd9-e577-48b4-b3a3-f22db60045e8', 'Geography', 'पारिस्थितिकी तंत्र में कवक (Fungi) और जीवाणु (Bacteria) ''अपघटक'' (Decomposers) के रूप में कार्य करते हैं।', 'In an ecosystem, Fungi and Bacteria act as ''Decomposers''.', 'सफाईकर्मी = कवक और जीवाणु (Decomposers)।', 'Cleaners = Fungi and Bacteria (Decomposers).', 'इन्हें उत्पादक (Producers) न समझें; उत्पादक हरे पौधे/शैवाल होते हैं।', 'Do not consider them Producers; producers are green plants/algae.', 'medium', 0.85, 0.9, '[{"questionId":"4v6py8vnv5k0LPF5Aq6gh"}]', '["Ecology","Food Chain"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829367, 1773829367);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d7d2e3e6-ad09-422b-ab64-75e5e032baa7', 'cc283dd9-e577-48b4-b3a3-f22db60045e8', 'Geography', 'एल नीनो (El Nino) हर साल नहीं होती; यह 2 से 7 साल के अंतराल पर होने वाली आवधिक घटना है।', 'El Nino is NOT an annual event; it is a periodic event occurring at intervals of 2 to 7 years.', 'एल नीनो कभी-कभी आता है (2-7 साल में), हर साल नहीं।', 'El Nino comes occasionally (2-7 years), not every year.', 'कथन आधारित प्रश्नों में ''हर साल'' (every year) शब्द एक ट्रैप (धोखा) होता है।', 'In statement-based questions, the word ''every year'' is a trap.', 'medium', 0.88, 0.92, '[{"questionId":"Q5hNMx6amdq1Qd7EAGGGW"}]', '["Climatology","Monsoon"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829367, 1773829367);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('31f91891-bafd-438c-9ee7-deaaa59f7733', 'c67c15c2-02b7-4dd3-aa59-39a7f6aac252', 'Geography', 'नर्मदा (1312 km) प्रायद्वीपीय भारत की प्रमुख और सबसे लंबी पश्चिम की ओर बहने वाली नदी है। ताप्ती मुलताई (म.प्र.) से, कावेरी ब्रह्मगिरि (कर्नाटक) से निकलती है।', 'Narmada (1312 km) is a major and longest west-flowing river of peninsular India. Tapti originates from Multai (MP), Kaveri from Brahmagiri (Kar).', 'नर्मदा सबसे लंबी (पश्चिम की ओर)। मुलताई की ताप्ती, ब्रह्म की कावेरी।', 'Narmada longest (west-flowing). Multai''s Tapti, Brahma''s Kaveri.', 'गोदावरी पूरे प्रायद्वीपीय भारत की सबसे लंबी है, लेकिन दिए गए विकल्पों में (नर्मदा, ताप्ती, सोन, कावेरी) नर्मदा सबसे लंबी थी।', 'Godavari is the longest in all of peninsular India, but among the given options (Narmada, Tapti, Son, Kaveri), Narmada was the longest.', 'medium', 0.95, 0.9, '[{"questionId":"WFWjo4mpH_9QHYL_c4rA7"},{"questionId":"XDYIYkZNuM6agM32hgdio"}]', '["Rivers","Origins"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829367, 1773829367);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('fdf38e3d-7f3f-4dd6-b2c1-d0352156541c', 'c67c15c2-02b7-4dd3-aa59-39a7f6aac252', 'Geography', 'अनाईमुड़ी (2695m) दक्षिण भारत की सबसे ऊंची चोटी है, उसके बाद गुरु शिखर (अरावली), महेंद्रगिरि (पूर्वी घाट) और पंचमढ़ी का स्थान आता है।', 'Anaimudi (2695m) is the highest peak in South India, followed by Guru Shikhar (Aravalli), Mahendragiri (Eastern Ghats) and Pachmarhi.', 'दक्षिण का ताज अनाईमुड़ी (Crown of South is Anaimudi)।', 'Crown of South is Anaimudi.', 'महेंद्रगिरि पूर्वी घाट की एक प्रमुख चोटी है, लेकिन पूर्वी घाट की सबसे ऊंची चोटी अब जिंधागड़ा (Jindhagada) मानी जाती है।', 'Mahendragiri is a major peak of the Eastern Ghats, but the highest peak of the Eastern Ghats is now considered to be Jindhagada.', 'medium', 0.85, 0.88, '[{"questionId":"HubvyQzpzkQXYHYAqllKJ"}]', '["Mountain Peaks","Topography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829367, 1773829367);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4f51d7f1-8b56-42ea-bd33-ce7d49eaec36', 'abe4ebc3-3e52-4cda-9b47-de9cf79a0a12', 'Economy', 'सितंबर 2023 के अंत में भारत का बाह्य ऋण जीडीपी का 18.6% था।', 'At the end of September 2023, India''s external debt was 18.6% of GDP.', 'बाहरी कर्ज ~18% (External debt ~18%).', 'External debt ~18%.', 'यह एक बहुत ही विशिष्ट (micro) डेटा पॉइंट था। भारत का अधिकांश बाहरी ऋण ''दीर्घकालिक'' (Long term) है।', 'This was a very specific micro data point. Most of India''s external debt is ''long-term''.', 'medium', 0.75, 0.85, '[{"questionId":"FqQP9vDVVU1w3oltOq6le"}]', '["Macroeconomics","External Debt"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829368, 1773829368);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('09846f35-69e8-40bb-bfd2-925a8bdcc668', 'abe4ebc3-3e52-4cda-9b47-de9cf79a0a12', 'Economy', 'SDG 1: गरीबी की समाप्ति, SDG 2: भुखमरी से मुक्ति, SDG 9: उद्योग, नवाचार और अवसंरचना।', 'SDG 1: No Poverty, SDG 2: Zero Hunger, SDG 9: Industry, Innovation & Infrastructure.', 'सबसे पहले गरीबी हटाओ (1), फिर खाना खिलाओ (2), फिर फैक्ट्री लगाओ (9)।', 'First remove poverty (1), then feed (2), then build factories (9).', 'कुल 17 SDGs हैं। शुरुआत के 5 (गरीबी, भूख, स्वास्थ्य, शिक्षा, लिंग समानता) एकदम कंठस्थ होने चाहिए।', 'There are 17 SDGs in total. The first 5 (Poverty, Hunger, Health, Education, Gender Equality) must be memorized thoroughly.', 'medium', 0.92, 0.95, '[{"questionId":"ttd3A5qAMRrqRYRtxNf6I"}]', '["SDG","NITI Aayog"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829368, 1773829368);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a3732068-8d60-4932-ab2d-eee227cd657d', 'f6935e7f-2d37-4e4d-8ee7-106b0e8f47ed', 'History', 'आधुनिक इतिहास: दादाभाई नौरोजी को ''आधुनिक भारत का पहला कूटनीतिज्ञ'' कहा गया। 1921 में असहयोग आंदोलन के दौरान वेल्स के राजकुमार का बहिष्कार किया गया। देवेन्द्रनाथ ठाकुर ने केशव चन्द्र सेन को ब्रह्म समाज का आचार्य बनाया था।', 'Modern History: Dadabhai Naoroji was called the ''first diplomat of modern India''. Prince of Wales was boycotted during the Non-Cooperation Movement in 1921. Devendranath Thakur appointed Keshab Chandra Sen as Acharya of Brahmo Samaj.', 'नौरोजी = पहले कूटनीतिज्ञ (First Diplomat)। 1921 = राजकुमार का बहिष्कार।', 'Naoroji = First Diplomat. 1921 = Boycott of Prince.', 'वेल्स के राजकुमार 1921 में आए थे, साइमन कमीशन 1928 में आया था। दोनों के बहिष्कार को मिक्स न करें।', 'Prince of Wales came in 1921, Simon Commission in 1928. Don''t mix up their boycotts.', 'medium', 0.9, 0.94, '[{"questionId":"sAjFmyTD4KezrHN59FBBX"},{"questionId":"Atw42l9FEoG0hp1ZRpb_y"},{"questionId":"Qc-BiOgU4rnAf86JhkqkN"},{"questionId":"N5So0fFt6VEsS-sMRcqxN"}]', '["Modern History","Freedom Struggle","Social Reforms"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829371, 1773829371);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('30415665-205a-480f-bdbe-95937fb80852', 'f6935e7f-2d37-4e4d-8ee7-106b0e8f47ed', 'History', 'भारत में दालों का सबसे बड़ा उत्पादक म.प्र. (2021-22) है। चावल का सबसे बड़ा उत्पादक पश्चिम बंगाल है।', 'MP is the largest producer of pulses in India (2021-22). West Bengal is the largest producer of rice.', 'दाल = MP (सोया-दाल स्टेट)। चावल = बंगाल (Fish and Rice)।', 'Dal = MP. Rice = Bengal.', 'गेहूं उत्पादन में उत्तर प्रदेश सबसे आगे है, चावल में बंगाल, और दालों/सोयाबीन में म.प्र।', 'UP leads in Wheat production, Bengal in Rice, and MP in Pulses/Soybean.', 'medium', 0.8, 0.85, '[{"questionId":"Tlat1Wd9HDkFHEJCs3gSo"},{"questionId":"HqJ07mnRMH91JSznR_XAH"}]', '["Agriculture Data","Geography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829371, 1773829371);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9518956b-beb4-4c3e-9ff0-4006620c3642', '0ed066be-2e29-4c1c-9267-60d9bc79e6ad', 'ICT', 'पेशेवरों (Professionals) के लिए सोशल नेटवर्किंग साइट ''LinkedIn'' है। ट्विटर के संस्थापक ''जैक डोर्सी'' (Jack Dorsey) हैं। Kurrently एक पुराना रीयल-टाइम सर्च इंजन था।', 'The social networking site for professionals is ''LinkedIn''. Twitter''s founder is ''Jack Dorsey''. Kurrently was an old real-time search engine.', 'प्रोफेशनल्स के लिंक्स (LinkedIn)। ट्विटर की चिड़िया जैक के पास (Jack''s Twitter bird)।', 'Links of professionals (LinkedIn). Jack''s Twitter bird.', 'अब ट्विटर का नाम X है (एलोन मस्क के अधीन), लेकिन संस्थापक के रूप में हमेशा जैक डोर्सी (और उनके साथी) का नाम आएगा।', 'Twitter is now X (under Elon Musk), but the founder will always be Jack Dorsey (and co-founders).', 'medium', 0.8, 0.85, '[{"questionId":"QDpGPQbN6f6psSN9iyKBI"},{"questionId":"7QVly3pBFyOV61Jv2gKpw"},{"questionId":"jSsvN0I8pkIYTT--dqwWt"}]', '["Social Media","Founders"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829372, 1773829372);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6bc2d107-6b4d-4b1c-8b7f-ac8e3606c80c', '5e666709-ac5e-4e0e-a100-4ee5e9044e0d', 'ICT', 'संयुक्त राष्ट्र (UN) ने 2024 को ''अंतर्राष्ट्रीय कैमेलिड (उष्ट्रगण) वर्ष'' घोषित किया है।', 'The United Nations (UN) has declared 2024 as the ''International Year of Camelids''.', '2023 में मोटा अनाज (Millets), 2024 में ऊंट (Camelids)।', 'Millets in 2023, Camelids in 2024.', '2023 और 2024 के घोषित वर्षों में भ्रमित न हों; बाजरा (Millets) 2023 था।', 'Do not confuse the declared years for 2023 and 2024; Millets was 2023.', 'medium', 0.85, 0.95, '[{"questionId":"rbh0SQBc7IgbT4qqCCeMk"}]', '["UN Declarations","Important Years"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829386, 1773829386);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('01e6aeb4-3486-4c2f-9b52-3008593b4cd5', '5e666709-ac5e-4e0e-a100-4ee5e9044e0d', 'ICT', 'पहला अंतर्राष्ट्रीय योग दिवस 21 जून 2015 को मनाया गया था (घोषणा 2014 में हुई थी)।', 'The first International Yoga Day was celebrated on June 21, 2015 (declared in 2014).', '14 में बोला, 15 में किया (Declared in ''14, Celebrated in ''15)।', 'Declared in ''14, Celebrated in ''15.', 'प्रस्ताव 2014 में पारित हुआ था, लेकिन पहली बार ''मनाया'' (Celebrated) 2015 में गया था। प्रश्न के शब्दों पर ध्यान दें।', 'The resolution was passed in 2014, but it was ''celebrated'' for the first time in 2015. Pay attention to the wording of the question.', 'medium', 0.92, 0.9, '[{"questionId":"n93dwWf8em5iph2x6hGuZ"}]', '["Important Days","India''s Global Initiative"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829386, 1773829386);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d5c162b4-4886-4e8d-8caf-47c0a9a3b9a6', '5e666709-ac5e-4e0e-a100-4ee5e9044e0d', 'ICT', 'लांस नायक मंजू भारतीय सेना की पहली महिला सैनिक स्काईडाइवर (First Woman Soldier Skydiver) बनीं। श्रीनिवास वर्धन को विज्ञान के लिए पद्म विभूषण (2023) मिला।', 'Lance Naik Manju became the Indian Army''s First Woman Soldier Skydiver. Srinivasa Varadhan received the Padma Vibhushan (2023) for Science.', 'आसमान से कूदी ''मंजू'' (Manju jumped from sky)। विज्ञान के ''वर्धन'' (Varadhan of Science)।', 'Manju jumped from sky. Varadhan of Science.', 'पद्म विभूषण विजेताओं के ''क्षेत्र'' (Field) को उनके नाम के साथ सख्ती से याद करें (जैसे दिलीप महालनाबिस - चिकित्सा)।', 'Strictly memorize the ''Field'' of Padma Vibhushan winners along with their names (e.g., Dilip Mahalanabis - Medicine).', 'medium', 0.8, 0.88, '[{"questionId":"YKLorodaV-ctHHwRJ0GhN"},{"questionId":"eDnbUnl45BI0E9sp8ECtN"}]', '["First in India","Awards & Honours"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829386, 1773829386);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c64fc797-5825-4038-8404-8b2c809c25f8', 'eb420dda-f74b-4707-8534-796b904db187', 'Economy', 'डॉ. सी. रंगराजन 12वें वित्त आयोग (Finance Commission) के अध्यक्ष थे। नीति आयोग की स्थापना 1 जनवरी 2015 को योजना आयोग के स्थान पर हुई थी।', 'Dr. C. Rangarajan was the chairman of the 12th Finance Commission. NITI Aayog was established on January 1, 2015, replacing the Planning Commission.', '12वें में रंग (Ranga in 12th)। 2015 में नई नीति (New NITI in 2015)।', 'Ranga in 12th. New NITI in 2015.', '14वें (Y.V. Reddy), 15वें (N.K. Singh) और 16वें (Arvind Panagariya) वित्त आयोग के अध्यक्षों के नाम वर्तमान परीक्षाओं के लिए सबसे ज्यादा महत्वपूर्ण हैं।', 'The names of the chairmen of the 14th (Y.V. Reddy), 15th (N.K. Singh), and 16th (Arvind Panagariya) Finance Commissions are most crucial for current exams.', 'medium', 0.95, 0.98, '[{"questionId":"43HhSIYfEeZQ4woXHnGd-"},{"questionId":"yuWY4XWc_J5Zk7n-GCnIF"}]', '["Constitutional Bodies","Economic Institutions"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829387, 1773829387);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7b91095f-473f-45e1-b3a9-90661966f295', 'eb420dda-f74b-4707-8534-796b904db187', 'Economy', 'RBI गवर्नर शक्तिकांत दास को सेन्ट्रल बैंकिंग अवार्ड्स 2023 में ''गवर्नर ऑफ द ईयर'' (Governor of the Year) पुरस्कार दिया गया।', 'RBI Governor Shaktikanta Das was awarded the ''Governor of the Year'' at the Central Banking Awards 2023.', 'शक्तिकांत की शक्ति को वैश्विक सम्मान (Global honor to Shaktikanta''s power)।', 'Global honor to Shaktikanta''s power.', 'रघुराम राजन को भी यह पुरस्कार मिल चुका है (2015), इसलिए वर्ष (2023) पर ध्यान दें।', 'Raghuram Rajan has also received this award (2015), so pay attention to the year (2023).', 'medium', 0.8, 0.88, '[{"questionId":"Lnt4qpX4Do78aKHoq8Iaa"}]', '["RBI","Awards"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829387, 1773829387);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('1130c882-082c-49f3-950e-153384a71552', 'b9671e84-695c-4edd-8b89-985cd6f79664', 'Geography', 'भारत में 4 जैव विविधता हॉटस्पॉट हैं: हिमालय, पश्चिमी घाट, इंडो-बर्मा क्षेत्र, सुंडालैंड। ''ग्रीन मफलर'' पेड़ों के माध्यम से ध्वनि प्रदूषण (Noise Pollution) को कम करने की तकनीक है।', 'India has 4 biodiversity hotspots: Himalayas, Western Ghats, Indo-Burma region, Sundaland. ''Green Muffler'' is a technique to reduce Noise Pollution using trees.', 'मफलर कानों (ध्वनि) को ढकता है (Muffler covers ears/noise)। 4 हॉटस्पॉट (4 Hotspots)।', 'Muffler covers ears/noise. 4 Hotspots.', 'ग्रीन मफलर को वायु प्रदूषण से न जोड़ें, इसका प्राथमिक उद्देश्य ध्वनि को अवशोषित करना है। अरावली या पूर्वी घाट हॉटस्पॉट नहीं हैं।', 'Do not link Green Muffler primarily to air pollution; its main goal is to absorb sound. Aravalli or Eastern Ghats are NOT hotspots.', 'medium', 0.9, 0.94, '[{"questionId":"7-orLnYzH2_I1X0ezQG8S"},{"questionId":"aFk7OCeinjDKMs_VorPhg"}]', '["Biodiversity","Pollution Control"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829388, 1773829388);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5812873b-7681-4c70-8f3d-ddfa15fb2868', 'b9671e84-695c-4edd-8b89-985cd6f79664', 'Geography', 'समुद्री (Marine) पारिस्थितिकी तंत्र पृथ्वी पर सबसे स्थिर (Stable) है। पारिस्थितिकी तंत्र में उच्च पोषण स्तर पर जाने पर ऊर्जा कम होती है (ऊष्मागतिकी का दूसरा नियम/10% नियम)।', 'Marine ecosystem is the most stable on Earth. Energy decreases as it moves to higher trophic levels in an ecosystem (Second Law of Thermodynamics/10% Rule).', 'विशाल समुद्र सबसे स्थिर (Vast ocean is most stable)। ऊपर जाने पर 90% ऊर्जा नष्ट (90% energy lost on moving up)।', 'Vast ocean is most stable. 90% energy lost on moving up.', 'वन (Forest) पारिस्थितिकी तंत्र स्थिर हो सकता है, लेकिन ''सबसे स्थिर'' महासागर ही होते हैं क्योंकि वे जलवायु परिवर्तनों के प्रति कम संवेदनशील होते हैं।', 'Forest ecosystems can be stable, but oceans are the ''most stable'' as they are less susceptible to sudden climate changes.', 'medium', 0.95, 0.96, '[{"questionId":"sIVmz38BcaHU0nDmqJEgI"},{"questionId":"UbDoVkiAbm3aXUAqAjsVD"}]', '["Ecosystem","Energy Flow"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829388, 1773829388);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a5298c9e-781a-4c22-9771-5816f927364f', 'b9671e84-695c-4edd-8b89-985cd6f79664', 'Geography', 'जिम कार्बेट (उत्तराखंड) 1973 में घोषित भारत का प्रथम टाइगर रिजर्व है। राष्ट्रीय हरित अधिकरण (NGT) का मुख्यालय नई दिल्ली में है।', 'Jim Corbett (Uttarakhand) is India''s first Tiger Reserve declared in 1973. National Green Tribunal (NGT) is headquartered in New Delhi.', 'पहला बाघ कार्बेट में (First tiger in Corbett)। NGT दिल्ली से नजर रखता है (NGT watches from Delhi)।', 'First tiger in Corbett. NGT watches from Delhi.', 'म.प्र. का पहला टाइगर रिजर्व कान्हा (1974) है, भारत का जिम कार्बेट है।', 'MP''s first tiger reserve is Kanha (1974), India''s is Jim Corbett.', 'medium', 0.85, 0.9, '[{"questionId":"L2pMYzMgyV_OCh68dSbrT"},{"questionId":"pmw8Y84RFJKkFp0h1PVe6"}]', '["Conservation","Institutions"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829388, 1773829388);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('138d58ed-2da9-4c41-baf9-9696e6af7838', 'b9671e84-695c-4edd-8b89-985cd6f79664', 'Geography', 'बायोस्फीयर रिजर्व मिलान: नोकरेक (मेघालय), मानस (असम), सिमलीपाल (ओडिशा), शेषाचलम (आंध्र प्रदेश)। कीटनाशक (Insecticides) गैर-बायोडिग्रेडेबल प्रदूषक हैं।', 'Biosphere Reserve Match: Nokrek (Meghalaya), Manas (Assam), Similipal (Odisha), Seshachalam (Andhra Pradesh). Insecticides are non-biodegradable pollutants.', 'नोकरेक के मेघ (Nokrek''s clouds), मानस का असम (Assam''s Manas), सिमलीपाल ओडिशा।', 'Nokrek''s clouds, Assam''s Manas, Similipal Odisha.', 'बायोस्फीयर रिजर्व और उनके राज्यों की मैपिंग MPPSC का एक क्लासिक ''मैच द कॉलम'' प्रश्न है।', 'Mapping Biosphere Reserves to their states is a classic MPPSC ''Match the Column'' question.', 'medium', 0.9, 0.95, '[{"questionId":"50u-gdgV7ZTaQapxlWmKC"},{"questionId":"wQnkeFTxcYPVoBe4v7cdt"}]', '["Biosphere Reserves","Pollutants"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829388, 1773829388);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('78551fa4-a145-4afc-9a64-acddd640e02e', '47ccd514-09e3-4c35-85e2-36f2e7a5ac12', 'Geography', '2011 जनगणना साक्षरता क्रम: केरल > मिजोरम > गोवा > त्रिपुरा। मिजोरम को ''मोलेसिस बेसिन'' (नरम चट्टानें) भी कहा जाता है।', '2011 Census Literacy Order: Kerala > Mizoram > Goa > Tripura. Mizoram is also called ''Molasses basin'' (soft rocks).', 'साक्षरता में K-M-G-T। मिजोरम का मोलेसिस (Mizoram Molasses)।', 'Literacy K-M-G-T. Mizoram Molasses.', 'त्रिपुरा ने साक्षरता में तेजी से सुधार किया है, लेकिन 2011 के आंकड़ों के अनुसार गोवा उससे ऊपर है।', 'Tripura has improved its literacy rapidly, but as per 2011 data, Goa is above it.', 'medium', 0.95, 0.98, '[{"questionId":"WmKxFUpF6ZxWqiIeIdWRO"},{"questionId":"-8F2_4MIt5ZEg_yepjRse"}]', '["Census","Topography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829389, 1773829389);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7e4a0484-672f-47b9-bd3d-6b4970f9154f', '47ccd514-09e3-4c35-85e2-36f2e7a5ac12', 'Geography', 'पटल विरूपण (Diastrophism) में भूकंप, महाद्वीप निर्माण और पर्वत निर्माण शामिल हैं, ''विषमांगी'' (Heterogenic) नहीं। क्षोभमंडल (Troposphere) मौसम संबंधी परिवर्तनों की परत है।', 'Diastrophism includes earthquakes, continent building, and mountain building, NOT ''Heterogenic''. Troposphere is the layer of weather changes.', 'डायस्ट्रोफिज़्म = धरती का रूप बदलना (Earth shaping)। मौसम = सबसे नीचे (Weather at the bottom)।', 'Diastrophism = Earth shaping. Weather at the bottom.', 'ओजोन परत समतापमंडल (Stratosphere) में होती है, क्षोभमंडल में नहीं। हवाई जहाज भी समतापमंडल में उड़ते हैं।', 'Ozone layer is in Stratosphere, not Troposphere. Airplanes also fly in the Stratosphere.', 'medium', 0.85, 0.88, '[{"questionId":"soyZtrrOlJCuFTgKAw45W"},{"questionId":"pptl59pL6Rvn-YOZ5da19"}]', '["Geomorphology","Atmosphere"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829389, 1773829389);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('fbfabcee-1540-434b-8682-97cdede8a5ab', '47ccd514-09e3-4c35-85e2-36f2e7a5ac12', 'Geography', 'लौह अयस्क खदानें: बैलाडिला (छत्तीसगढ़) और कुद्रेमुख (कर्नाटक)। वैतरणा नदी नासिक (त्रिंबक) से निकलती है। भूतापीय ऊर्जा का प्रथम प्रयोग बोइज़े, इडाहो (USA) में हुआ था।', 'Iron ore mines: Bailadila (Chhattisgarh) and Kudremukh (Karnataka). Vaitarna river originates from Nashik (Trimbak). First use of Geothermal energy was in Boise, Idaho (USA).', 'बैलाडिला-CG, कुद्रेमुख-KA (लौह अयस्क)। नासिक की वैतरणा। भूताप (Geothermal) USA में शुरू।', 'Bailadila-CG, Kudremukh-KA (Iron Ore). Nashik''s Vaitarna. Geothermal started in USA.', 'बैलाडिला (छत्तीसगढ़) एशिया की सबसे बड़ी यंत्रीकृत (mechanized) लौह खदान है, इसे ओडिशा में न समझें।', 'Bailadila (CG) is Asia''s largest mechanized iron mine, do not mistake it to be in Odisha.', 'medium', 0.85, 0.9, '[{"questionId":"cHYjN4AHjz4WJGjwOkKB5"},{"questionId":"Jd6RrjDoovjEftwD77lwf"},{"questionId":"3_6nKNGfJgn430OGOwr_S"}]', '["Minerals","Rivers","Energy"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829389, 1773829389);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('96cf8e57-0179-481e-97a5-acb82265a417', '47ccd514-09e3-4c35-85e2-36f2e7a5ac12', 'Geography', 'टाटीपाका तेल रिफाइनरी आंध्र प्रदेश में है। गाज़ा पट्टी (Gaza Strip) भूमध्य सागर (Mediterranean Sea) के तट पर स्थित है।', 'Tatipaka oil refinery is in Andhra Pradesh. Gaza Strip is located on the coast of the Mediterranean Sea.', 'टाटीपाका - AP। गाज़ा - भूमध्य सागर (Mediterranean)।', 'Tatipaka - AP. Gaza - Mediterranean.', 'भौगोलिक संघर्ष वाले क्षेत्रों (जैसे गाजा, यमन, ताइवान) के आस-पास के जल निकायों (Water bodies) को जरूर मैप करें।', 'Always map the water bodies surrounding geographical conflict zones (like Gaza, Yemen, Taiwan).', 'medium', 0.8, 0.85, '[{"questionId":"H0XfQA-ruf9n0CW2p0Cu-"},{"questionId":"zh-oksNpBwwa9mvpKAg3u"}]', '["World Geography","Industries"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829390, 1773829390);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b09cf91f-3c48-44c1-8b8d-ca5f34021bf6', '408ddc20-f33e-4a2f-aea2-3be1bd79e865', 'History', 'कांग्रेस का पहला अधिवेशन 1885 में बम्बई में हुआ। 1907 के ''सूरत अधिवेशन'' में कांग्रेस नरम और गरम दल में बँट गई।', 'The first Congress session was held in Bombay in 1885. In the 1907 ''Surat session'', Congress split into moderates and extremists.', '85 में बम्बई (Start in Bombay)। 1907 में सूरत की ''फूट'' (Surat Split)।', 'Start in Bombay in 85. Surat Split in 1907.', 'पहला अधिवेशन पुणे में होना था, लेकिन प्लेग के कारण बम्बई शिफ्ट हुआ। सूरत फूट की अध्यक्षता रास बिहारी घोष ने की थी, बोस ने नहीं।', 'The first session was planned for Pune but shifted to Bombay due to plague. Surat split was chaired by Rash Behari Ghosh, not Bose.', 'medium', 0.95, 0.98, '[{"questionId":"ZFOBdj2NuvNqowmE11LuA"},{"questionId":"e0I6qvdtwKjafLHezZFU5"}]', '["INC Sessions","Modern History"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829391, 1773829391);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d329e268-e7cd-4407-a56e-79b2e7f5a3b4', '408ddc20-f33e-4a2f-aea2-3be1bd79e865', 'History', '1929 के लाहौर अधिवेशन (नेहरू अध्यक्ष) में ''पूर्ण स्वराज'' का संकल्प लिया गया। 1939 के त्रिपुरी (जबलपुर) अधिवेशन में सुभाष चंद्र बोस ने पट्टाभि सीतारमैया को हराया।', '''Purna Swaraj'' resolution was taken in the 1929 Lahore session (Nehru president). In the 1939 Tripuri (Jabalpur) session, S.C. Bose defeated Pattabhi Sitaramayya.', 'लाहौर में पूर्ण स्वराज (Purna Swaraj in Lahore)। त्रिपुरी में बोस की जीत (Bose wins in Tripuri)।', 'Purna Swaraj in Lahore. Bose wins in Tripuri.', 'हरिपुरा अधिवेशन (1938) और त्रिपुरी अधिवेशन (1939) दोनों में बोस जीते थे, लेकिन विवाद त्रिपुरी में हुआ था (MP का होने के कारण यह बहुत महत्वपूर्ण है)।', 'Bose won both Haripura (1938) and Tripuri (1939), but the conflict happened in Tripuri (highly important as it''s in MP).', 'medium', 0.92, 0.96, '[{"questionId":"jw6_ocJn2KnsG4y0MIx7W"},{"questionId":"B5ho5EKPadyEfmI1JEZpg"}]', '["INC Sessions","Freedom Struggle"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829391, 1773829391);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('69bfccf5-189b-4461-b798-44a1d76fd4ed', '408ddc20-f33e-4a2f-aea2-3be1bd79e865', 'History', 'दांडी यात्रा 12 मार्च 1930 को साबरमती से शुरू हुई। जलियाँवाला बाग हत्याकांड 13 अप्रैल 1919 को हुआ था। ''स्वराज मेरा जन्मसिद्ध अधिकार है...'' तिलक ने कहा था।', 'Dandi March started from Sabarmati on March 12, 1930. Jallianwala Bagh massacre occurred on April 13, 1919. ''Swaraj is my birthright...'' was said by Tilak.', '13 अप्रैल 1919 (बैसाखी का खून)। 12 मार्च 1930 (नमक यात्रा शुरू)।', 'April 13, 1919 (Bloody Baisakhi). March 12, 1930 (Salt march starts).', 'सविनय अवज्ञा आंदोलन की आधिकारिक शुरुआत 6 अप्रैल 1930 (दांडी में नमक कानून टूटने) से मानी जाती है, 12 मार्च से नहीं।', 'The official start of Civil Disobedience is April 6, 1930 (breaking of salt law at Dandi), not March 12.', 'medium', 0.9, 0.95, '[{"questionId":"chi_rkVjQTXVqSU3d_AhO"},{"questionId":"SvFzsXbUqUuizYlkUZexf"},{"questionId":"d2aovUiATKFcOBRhCUb5D"}]', '["Modern History","Key Events"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829392, 1773829392);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('1a3ce93f-64d4-4572-ba59-9574b498db83', '408ddc20-f33e-4a2f-aea2-3be1bd79e865', 'History', 'ऋग्वेद में गाय को ''अघन्या'' (न मारने योग्य) कहा गया है। कुरु महाजनपद की राजधानी ''इंद्रप्रस्थ'' थी (अहिच्छत्र नहीं)।', 'In Rigveda, the cow is called ''Aghanya'' (not to be killed). The capital of Kuru Mahajanapada was ''Indraprastha'' (not Ahichchhatra).', 'अघन्या = गाय (Cow)। कुरु = इंद्रप्रस्थ (महाभारत काल)।', 'Aghanya = Cow. Kuru = Indraprastha (Mahabharata era).', 'अहिच्छत्र ''पांचाल'' महाजनपद (उत्तरी भाग) की राजधानी थी। 16 महाजनपदों की राजधानियाँ रट लें।', 'Ahichchhatra was the capital of ''Panchala'' Mahajanapada (Northern part). Rote learn the capitals of the 16 Mahajanapadas.', 'medium', 0.85, 0.9, '[{"questionId":"_tpfHUOTdeVrkfe5-HTCg"},{"questionId":"vhOKjkfbsmn9cC3m-sqEn"}]', '["Vedic Period","Mahajanapadas"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829392, 1773829392);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('35307668-c903-4a07-bc11-ffe85ac5b537', '408ddc20-f33e-4a2f-aea2-3be1bd79e865', 'History', 'समुद्रगुप्त को ''कविराज'' की उपाधि मिली थी। चीनी यात्री फाह्यान चंद्रगुप्त द्वितीय (विक्रमादित्य) के समय भारत आया।', 'Samudragupta held the title of ''Kaviraj''. Chinese traveler Fa-Hien came to India during Chandragupta II (Vikramaditya).', 'वीणा बजाता समुद्रगुप्त (कविराज)। फाह्यान = चंद्रगुप्त 2।', 'Samudragupta playing Veena (Kaviraj). Fa-Hien = Chandragupta 2.', 'ह्वेनसांग (Hiuen Tsang) हर्षवर्धन के समय आया था (H से H)। फाह्यान चंद्रगुप्त द्वितीय के समय।', 'Hiuen Tsang came during Harshavardhana (H to H). Fa-Hien during Chandragupta II.', 'medium', 0.88, 0.92, '[{"questionId":"eoIWKl0KxsKlSXYm0eoog"},{"questionId":"9dQE_JkqmVkQ3fTrWiK82"}]', '["Gupta Empire","Ancient Travelers"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829392, 1773829392);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('53c39ce3-03a4-4512-afbe-5630b4e933be', '408ddc20-f33e-4a2f-aea2-3be1bd79e865', 'History', 'बलबन ने ''लौह और रक्त'' की नीति अपनाई। विजयनगर साम्राज्य की स्थापना 1336 में हरिहर-बुक्का ने की। तुगलक वंश 1320 में गयासुद्दीन तुगलक ने शुरू किया। अबुल फजल ने ''अकबरनामा'' लिखा।', 'Balban adopted the ''Blood and Iron'' policy. Vijayanagara Empire was founded in 1336 by Harihara-Bukka. Tughlaq dynasty started in 1320 by Ghiyasuddin. Abul Fazl wrote ''Akbarnama''.', 'बलबन = रक्त/लौह। विजयनगर = 1336। तुगलक = 1320।', 'Balban = Blood/Iron. Vijayanagara = 1336. Tughlaq = 1320.', 'विजयनगर साम्राज्य (1336) और बहमनी साम्राज्य (1347) की स्थापना वर्ष आसपास हैं, इन्हें स्पष्ट रखें।', 'The founding years of Vijayanagara (1336) and Bahmani (1347) are close, keep them distinct.', 'medium', 0.85, 0.88, '[{"questionId":"nxNfFc6XJaF3oho9hhdE7"},{"questionId":"Z07mYzpjycUzl41rv30ob"},{"questionId":"Yej8gnTAW1ITBa1XaDQu1"},{"questionId":"8PiTGjlisfiUPJzlYHzoi"}]', '["Delhi Sultanate","Vijayanagara","Mughal Literature"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829392, 1773829392);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('48ca2fd4-1ab8-46d7-9ad2-5fecc0136d08', 'ad6207f6-6c8d-47de-a64c-c362984222a6', 'ICT', 'DSL (Digital Subscriber Line) इंटरनेट कनेक्शन के लिए पारंपरिक टेलीफोन लाइनों का उपयोग करता है।', 'DSL (Digital Subscriber Line) uses traditional telephone lines for internet connection.', 'टेलीफोन लाइन से डिजिटल डेटा (Digital data from phone line = DSL)।', 'Digital data from phone line = DSL.', 'डायल-अप (Dial-up) भी टेलीफोन लाइन का उपयोग करता है, लेकिन DSL उससे बहुत तेज़ (Broadband) है।', 'Dial-up also uses telephone lines, but DSL is much faster (Broadband).', 'medium', 0.8, 0.85, '[{"questionId":"mCbDAFa2xdVpSbRYltOwE"}]', '["Internet Technologies"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829393, 1773829393);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5aff6fac-4abe-462f-9fb3-7eaa0441dd97', 'ad6207f6-6c8d-47de-a64c-c362984222a6', 'ICT', 'याहू (Yahoo) एक सर्च इंजन/वेब पोर्टल है, यह वेब ब्राउज़र नहीं है (जैसे क्रोम, फायरफॉक्स)।', 'Yahoo is a search engine/web portal, it is NOT a web browser (like Chrome, Firefox).', 'ब्राउज़र वेबसाइट खोलता है, सर्च इंजन वेबसाइट ढूंढता है। (Browser opens, Search engine finds).', 'Browser opens, Search engine finds.', 'Google एक कंपनी/सर्च इंजन है, लेकिन Google Chrome एक ब्राउज़र है। दोनों में अंतर स्पष्ट रखें।', 'Google is a company/search engine, but Google Chrome is a browser. Keep the difference clear.', 'medium', 0.95, 0.9, '[{"questionId":"cLjE2DKRgkrOCi6Sodb1R"}]', '["Software Basics","Web Browsers"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829393, 1773829393);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d13e8935-c838-4b1b-ae15-ef39068ae103', 'ad6207f6-6c8d-47de-a64c-c362984222a6', 'ICT', 'कंप्यूटर की दूसरी पीढ़ी (2nd Gen) में वैक्यूम ट्यूब की जगह ''ट्रांजिस्टर'' (Transistors) का प्रयोग किया गया था।', 'In the second generation (2nd Gen) of computers, ''Transistors'' replaced vacuum tubes.', 'पहली पीढ़ी ट्यूब, दूसरी ट्रांजिस्टर, तीसरी चिप (IC)। (1-Tube, 2-Transistor, 3-IC).', '1-Tube, 2-Transistor, 3-IC.', 'माइक्रोप्रोसेसर (Microprocessor) 4थी पीढ़ी में आए थे। पीढ़ियों के हार्डवेयर को क्रम से याद रखें।', 'Microprocessors came in the 4th generation. Remember the hardware of the generations in order.', 'medium', 0.9, 0.95, '[{"questionId":"LZkcrGPqlR3Ph_ZN-N0Sp"}]', '["Computer Generations","Hardware History"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829393, 1773829393);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('28b652d2-48c8-4d74-b02b-b84c2144905b', 'ad6207f6-6c8d-47de-a64c-c362984222a6', 'ICT', 'भ्रामक ईमेल या संदेश के जरिए पासवर्ड या जानकारी चुराना ''फिशिंग'' (Phishing) कहलाता है। UNIX का मुख्य भाग ''कर्नल'' (Kernel) है।', 'Stealing passwords or information via deceptive emails or messages is called ''Phishing''. The core of UNIX is ''Kernel''.', 'फिशिंग = मछली (यूजर) को चारा (Email) डालकर फंसाना। कर्नल = OS का दिल।', 'Phishing = Baiting the fish (user) with an email. Kernel = Heart of OS.', 'स्पूफिंग (Spoofing) में पहचान छिपाई जाती है, जबकि फिशिंग में धोखा देकर जानकारी मांगी जाती है।', 'In Spoofing, identity is hidden; in Phishing, information is deceitfully extracted.', 'medium', 0.88, 0.92, '[{"questionId":"-BJnQE18J5AQMcoVIBaRM"},{"questionId":"9OV6Q01hUEHwEZT6CztSw"}]', '["Cyber Security","Operating Systems"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829393, 1773829393);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('8ce9168c-74e1-4dbb-8263-0a266941c2ca', 'ad6207f6-6c8d-47de-a64c-c362984222a6', 'ICT', 'एलन ट्यूरिंग के परीक्षण का मूल नाम ''द इमिटेशन गेम'' (The Imitation Game) था। जैक डोर्सी ट्विटर (X) के संस्थापक हैं।', 'The original name of Alan Turing''s test was ''The Imitation Game''. Jack Dorsey is the founder of Twitter (X).', 'ट्यूरिंग टेस्ट = इमिटेशन गेम। ट्विटर की चिड़िया जैक के पास।', 'Turing Test = Imitation Game. Jack''s Twitter bird.', 'अब ट्विटर का नाम X है, लेकिन संस्थापक हमेशा जैक डोर्सी ही रहेंगे।', 'Twitter is now X, but the founder will always be Jack Dorsey.', 'medium', 0.8, 0.85, '[{"questionId":"6JTWTilXRfke9YuYyCrbD"},{"questionId":"7QVly3pBFyOV61Jv2gKpw"}]', '["AI History","Social Media"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829393, 1773829393);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('144aab13-6b60-44e2-9332-255656fc3671', 'b68350d3-ad39-4cd6-8e47-b615e11e020b', 'ICT', 'संचार प्रक्रिया में, प्राप्तकर्ता (Receiver) संदेश को समझने के लिए ''डिकोडिंग'' (Decoding) करता है। ChatGPT (AI टूल) को ''OpenAI'' द्वारा विकसित किया गया है।', 'In the communication process, the receiver ''decodes'' the message to understand it. ChatGPT (AI tool) was developed by ''OpenAI''.', 'भेजने वाला Encode (ताला), पाने वाला Decode (चाबी)। Chat = OpenAI।', 'Sender Encodes (Lock), Receiver Decodes (Key). Chat = OpenAI.', 'ChatGPT को Microsoft या Google का प्रोडक्ट न समझें। Microsoft सिर्फ एक निवेशक है, डेवलपर OpenAI ही है।', 'Do not mistake ChatGPT as a Microsoft or Google product. Microsoft is just an investor; the developer is OpenAI.', 'medium', 0.9, 0.95, '[{"questionId":"nXACvrXnzW_f5P76KskDi"},{"questionId":"nkEv1KtL51koZJUCP7E8X"}]', '["Communication Basics","AI","Current Tech"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829401, 1773829401);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('437720f5-a048-4736-8e79-7c085ecaa439', 'b68350d3-ad39-4cd6-8e47-b615e11e020b', 'ICT', 'भ्रामक संदेशों (धोखे) से संवेदनशील जानकारी चुराना ''फिशिंग'' (Phishing) कहलाता है। नेटवर्क को अनधिकृत पहुँच (Unauthorized access) से बचाने के लिए ''फ़ायरवॉल'' (Firewall) का उपयोग होता है।', 'Stealing sensitive info via deceptive messages (trickery) is ''Phishing''. ''Firewall'' is used to protect networks from unauthorized access.', 'फिशिंग (Phishing) = मछली (User) को चारा डालना। फायरवॉल = आग की दीवार (सुरक्षा)।', 'Phishing = Baiting the fish (user). Firewall = Wall of fire (protection).', 'फ़ायरवॉल वायरस को ''हटाने'' (Antivirus) का काम नहीं करता, यह केवल ट्रैफ़िक को ''रोकता/फ़िल्टर'' करता है।', 'A firewall does not ''remove'' viruses (that''s Antivirus); it only ''blocks/filters'' traffic.', 'medium', 0.95, 0.98, '[{"questionId":"ETKBCaWekwpAoo3eOpzL5"},{"questionId":"koic7Vl7FuwG7FK4CFHX3"}]', '["Cyber Security","Malware & Defenses"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829401, 1773829401);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('eb8a90ca-374d-48ee-86c1-d14b2f1d83a8', 'b68350d3-ad39-4cd6-8e47-b615e11e020b', 'ICT', 'अमेज़ॅन (Amazon) और फ्लिपकार्ट (Flipkart) B2C (Business-to-Consumer) ई-कॉमर्स मॉडल के उदाहरण हैं। ई-कॉमर्स का सबसे बड़ा लाभ इसका 24/7 संचालन है।', 'Amazon and Flipkart are examples of the B2C (Business-to-Consumer) e-commerce model. The biggest advantage of e-commerce is its 24/7 operation.', 'कम्पनी से सीधे ग्राहक (Company to Customer) = B2C।', 'Company direct to Customer = B2C.', 'अलीबाबा (Alibaba) मुख्य रूप से B2B है, लेकिन जब अमेज़न/फ्लिपकार्ट के साथ पूछा जाए, तो समूह के आधार पर B2C सबसे उपयुक्त विकल्प बनता है।', 'Alibaba is primarily B2B, but when asked alongside Amazon/Flipkart, B2C becomes the most appropriate choice based on the grouping.', 'medium', 0.85, 0.9, '[{"questionId":"NlXm7q3ezlQBowm_lnXYb"},{"questionId":"ixVpTszsouA2DHsLJGQVw"}]', '["E-Commerce Models"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829402, 1773829402);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5a98de5c-4e6a-4025-a6c9-6d43b55e2cfc', 'e6495741-7951-4d20-aa4f-6b082180c7b8', 'MP GK', 'पंडित कुंजीलाल दुबे मध्य प्रदेश विधानसभा के प्रथम अध्यक्ष थे। कैलाश जोशी म.प्र. के प्रथम गैर-कांग्रेसी (जनता पार्टी - 1977) मुख्यमंत्री थे।', 'Pandit Kunjilal Dubey was the first Speaker of the MP Legislative Assembly. Kailash Joshi was the first non-Congress (Janata Party - 1977) Chief Minister of MP.', 'कुंजीलाल के पास विधानसभा की कुंजी (Key) थी। कैलाश जोशी = राजनीति के संत (1977)।', 'Kunjilal held the Key to the Assembly. Kailash Joshi = Saint of Politics (1977).', 'वीरेंद्र कुमार सखलेचा भी 1977-1980 के दौरान गैर-कांग्रेसी सीएम थे, लेकिन ''पहले'' कैलाश जोशी (1977) थे।', 'Virendra Kumar Sakhlecha was also a non-Congress CM during 1977-1980, but the ''first'' was Kailash Joshi (1977).', 'medium', 0.95, 0.98, '[{"questionId":"Vj4CDx42dp-OF_2TrU7c9"},{"questionId":"9StNTS8iN1u-qu2Dk1HT-"}]', '["MP Polity","First in MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829403, 1773829403);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7765674c-00cb-4811-9587-4d563dbf3772', 'e6495741-7951-4d20-aa4f-6b082180c7b8', 'MP GK', 'मध्य प्रदेश में ''पंचायती राज अधिनियम'' 30 दिसंबर 1993 को पारित हुआ (73वें संशोधन के बाद)। वर्तमान में म.प्र. में 16 नगर निगम हैं।', '''Panchayati Raj Act'' was passed in MP on Dec 30, 1993 (post 73rd Amendment). Currently, there are 16 Municipal Corporations in MP.', '73वां संशोधन आते ही MP पहला राज्य बना (1993-94)। 16 बड़े शहर = 16 नगर निगम।', 'MP became the first state as soon as the 73rd Amendment came (1993-94). 16 big cities = 16 Nagar Nigams.', 'भिंड और दतिया प्रस्तावित नगर निगम हैं। विकल्पों में 16, 17, 18 दिए जाने पर वर्तमान आधिकारिक गजट अधिसूचना (16) पर ही भरोसा करें।', 'Bhind and Datia are proposed municipal corporations. If options give 16, 17, 18, rely only on the current official gazette notification (16).', 'medium', 0.9, 0.92, '[{"questionId":"xW4GN5W6Dn-LiH5DEhF63"},{"questionId":"q7T9RnDDGUPnsNtE4_aYV"}]', '["Local Self Government","Administration"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829403, 1773829403);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a5b228e7-a991-4aa0-9d3d-184f0bcf4a2b', 'e6495741-7951-4d20-aa4f-6b082180c7b8', 'MP GK', 'मध्य प्रदेश के वर्तमान विधानसभा भवन का नाम ''इंदिरा गाँधी विधान भवन'' है (1996 में उद्घाटित)।', 'The current Legislative Assembly building of MP is named ''Indira Gandhi Vidhan Bhavan'' (inaugurated in 1996).', 'नया भवन = इंदिरा गाँधी (1996)। पुराना भवन = मिंटो हॉल।', 'New Building = Indira Gandhi (1996). Old Building = Minto Hall.', 'सचिवालय (Secretariat) का नाम ''वल्लभ भवन'' है। विधानसभा (Assembly) और सचिवालय के नामों में भ्रमित न हों।', 'The Secretariat is named ''Vallabh Bhavan''. Do not confuse the names of the Assembly and the Secretariat.', 'medium', 0.85, 0.9, '[{"questionId":"yEFaTsQGYeW0cD9iVTKPS"}]', '["State Buildings"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829403, 1773829403);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('35e6f40f-7adb-4e1b-a6bc-835daa70418c', 'e6495741-7951-4d20-aa4f-6b082180c7b8', 'MP GK', 'MP Online नागरिकों को सेवाएं (G2C) देने वाला पोर्टल है, यह सरकारी खरीद (e-Procurement) पोर्टल नहीं है (GeM खरीद पोर्टल है)।', 'MP Online is a portal providing services to citizens (G2C); it is NOT a government procurement portal (GeM is for procurement).', 'MP Online = फॉर्म भरना/बिल जमा करना। GeM = सरकार की Amazon (Govt shopping)।', 'MP Online = Form filling/Bill payment. GeM = Govt''s Amazon.', 'ई-गवर्नेंस के विभिन्न प्रकारों (G2C, G2B, G2G) के सटीक पोर्टल उदाहरण याद रखें।', 'Memorize the exact portal examples of different types of e-governance (G2C, G2B, G2G).', 'medium', 0.8, 0.85, '[{"questionId":"HfyI3Y8AfQ_nxJrTA4lvW"}]', '["E-Governance Portals"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829403, 1773829403);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('47232052-bdec-4d27-8430-7aaf0a3bceb4', 'e67a10d2-fd6d-42f0-bbb6-a468dc8ee2c7', 'MP GK', 'टंट्या ''मामा'' (भील) का वास्तविक नाम तांतिया (Tantia) था। वे ''इंडियन रॉबिन हुड'' कहलाते हैं। बादल भोई (गोंड) छिंदवाड़ा के महान आदिवासी सेनानी थे।', 'Tantia ''Mama''s'' (Bhil) real name was Tantia. He is called the ''Indian Robin Hood''. Badal Bhoi (Gond) was a great tribal fighter from Chhindwara.', 'पातालपानी के रॉबिन हुड = तांतिया। छिंदवाड़ा के बादल = भोई।', 'Robin Hood of Patalpani = Tantia. Clouds of Chhindwara = Bhoi.', 'आयोग ने ''टूँदरा'' को भी सही माना है, लेकिन ऐतिहासिक दस्तावेजों में ''तांतिया'' प्रमुख है। आदिवासी नायकों के क्षेत्र (जैसे बादल भोई-छिंदवाड़ा) अक्सर मिलाए जाते हैं।', 'The commission has also accepted ''Tundra'', but ''Tantia'' is prominent in historical docs. The regions of tribal heroes (like Badal Bhoi-Chhindwara) are frequently matched.', 'medium', 0.95, 0.98, '[{"questionId":"3CGmRcDfFQRdGx8xlytDN"},{"questionId":"crbUhcjbA9luJxIHDnKad"}]', '["Tribal Personalities","Freedom Fighters"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829404, 1773829404);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('65bf2ccd-f43b-4db1-90d9-fcae533cc489', 'e67a10d2-fd6d-42f0-bbb6-a468dc8ee2c7', 'MP GK', 'तात्या टोपे की समाधि शिवपुरी में स्थित है (1859 में यहीं फांसी)। विदिशा का प्राचीन नाम ''भेलसा'' (Bhilsa) था। चित्रकूट को ''ब्रह्मपुरी'' भी कहा जाता था।', 'Tantia Tope''s tomb is located in Shivpuri (hanged here in 1859). The ancient name of Vidisha was ''Bhilsa''. Chitrakoot was also known as ''Brahmapuri''.', 'शिव की नगरी में तात्या (Tatya in Shiv''s city)। भेलसा = विदिशा।', 'Tatya in Shiv''s city. Bhilsa = Vidisha.', 'तात्या टोपे कानपुर या ग्वालियर के नहीं, शिवपुरी में शहीद हुए थे। सांची का प्राचीन नाम काकनाद (Kakanad) था, विदिशा का भेलसा।', 'Tantia Tope was martyred in Shivpuri, not Kanpur or Gwalior. Sanchi''s ancient name was Kakanad, Vidisha''s was Bhilsa.', 'medium', 0.9, 0.94, '[{"questionId":"X4UzvTFV7SW033nH9GkhA"},{"questionId":"Dg5p_iWNYEoSh4oMoLsUY"},{"questionId":"epOoijILBj4ersQ1uST2z"}]', '["Historical Places","1857 Revolt"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829404, 1773829404);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0eba5cd2-e19b-4eec-8391-c8d221a816d7', 'e67a10d2-fd6d-42f0-bbb6-a468dc8ee2c7', 'MP GK', 'सुभद्रा कुमारी चौहान की प्रसिद्ध कृति ''मुकुल'' (और त्रिधारा) है। बालकृष्ण शर्मा ''नवीन'' ने गणेश शंकर विद्यार्थी के बलिदान पर ''प्रणार्पण'' लिखा।', 'Subhadra Kumari Chauhan''s famous work is ''Mukul'' (and Tridhara). Balkrishna Sharma ''Naveen'' wrote ''Pranarpan'' on the sacrifice of Ganesh Shankar Vidyarthi.', 'झांसी की रानी = सुभद्रा (मुकुल)। नवीन = प्रणार्पण (समर्पण)।', 'Jhansi ki Rani = Subhadra (Mukul). Naveen = Pranarpan (Dedication).', 'सुभद्रा कुमारी चौहान जबलपुर/खंडवा से जुड़ी थीं, जबकि ''नवीन'' जी शाजापुर से। साहित्यकारों की जन्मस्थली भी पूछी जाती है।', 'Subhadra Kumari Chauhan was associated with Jabalpur/Khandwa, while ''Naveen'' ji was from Shajapur. Birthplaces of literary figures are also asked.', 'medium', 0.85, 0.9, '[{"questionId":"01I-toEPFMZv6E3ulpZWV"},{"questionId":"9fuS1JV38ZA48Ksw1Mi2h"}]', '["MP Literature","Authors"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829404, 1773829404);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('8d5ef35f-e143-41df-ab6c-10a264b9c6e9', 'e67a10d2-fd6d-42f0-bbb6-a468dc8ee2c7', 'MP GK', 'न्यायमूर्ति एम. हिदायतुल्ला मध्य प्रदेश उच्च न्यायालय के प्रथम मुख्य न्यायाधीश थे।', 'Justice M. Hidayatullah was the first Chief Justice of the Madhya Pradesh High Court.', 'प्रथम न्याय = हिदायतुल्ला (First Justice = Hidayatullah)।', 'First Justice = Hidayatullah.', 'वे भारत के मुख्य न्यायाधीश (CJI) और कार्यवाहक राष्ट्रपति भी बने। उनका नाम MP के सबसे गौरवशाली नामों में से एक है।', 'He also became the Chief Justice of India (CJI) and Acting President. His name is one of the most glorious from MP.', 'medium', 0.9, 0.92, '[{"questionId":"vnY_XyG2ALocTm0qLTzTl"}]', '["MP Polity","Important Personalities"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829404, 1773829404);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e4ffe699-e581-42d2-81f7-5e38f80ec311', 'f0cdb7e2-fd34-449b-88b8-3fa43bd55a3b', 'MP GK', '2011 जनगणना: अलीराजपुर (36.1%) की साक्षरता दर म.प्र. (और भारत) में सबसे कम है। न्यूनतम से उच्चतम दशकीय वृद्धि दर: अनूपपुर < बैतूल < छिंदवाड़ा < मंदसौर।', '2011 Census: Alirajpur (36.1%) has the lowest literacy rate in MP (and India). Decadal growth rate from lowest to highest: Anuppur < Betul < Chhindwara < Mandsaur.', 'अलीराजपुर = सबसे कम पढ़ा-लिखा (Lowest Literacy)। अनूपपुर की वृद्धि सबसे कम (Anuppur lowest growth)।', 'Alirajpur = Lowest Literacy. Anuppur lowest growth.', 'सबसे कम साक्षरता अलीराजपुर में है, लेकिन सबसे कम महिला साक्षरता और पुरुष साक्षरता में भी यही जिला सबसे नीचे है। सर्वाधिक साक्षरता जबलपुर में है।', 'Lowest literacy is in Alirajpur; it is also at the bottom in both female and male literacy. Highest literacy is in Jabalpur.', 'medium', 0.95, 0.98, '[{"questionId":"scURLcenXPyaD-QTUv7C9"},{"questionId":"1wfxhXwCid2LBtNugAiCM"}]', '["MP Census 2011","Demography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829406, 1773829406);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('21d214d3-e057-4c7c-a05e-1ce64c243411', 'f0cdb7e2-fd34-449b-88b8-3fa43bd55a3b', 'MP GK', 'गोंड जनजाति मिट्टी से दीवार पर ''नोहडोरा'' (Nohdora) अलंकरण बनाती है। ढोकरा कला धातु शिल्प (Metal Craft - लॉस्ट वैक्स कास्टिंग) है, न कि कपड़ा कला।', 'Gond tribe creates ''Nohdora'' mud decorations on walls. Dhokra art is a Metal Craft (Lost Wax Casting), not textile art.', 'नोहडोरा = गोंडों की दीवार (Gond''s wall)। ढोकरा = धातु (Dhokra = Metal)।', 'Nohdora = Gond''s wall. Dhokra = Metal.', 'ढोकरा कला मुख्य रूप से बैतूल/छिंदवाड़ा क्षेत्र के ''भरेवा'' समुदाय द्वारा की जाती है। इसे पिथौरा (भील) या गोंड चित्रकला से न मिलाएं।', 'Dhokra art is mainly practiced by the ''Bharewa'' community of Betul/Chhindwara region. Don''t mix it with Pithora (Bhil) or Gond painting.', 'medium', 0.88, 0.92, '[{"questionId":"6WoGeH5tcBsO2lo5tSyjv"},{"questionId":"ad4y3tsoOXtpZtpiPDF1A"}]', '["Tribal Art","Handicrafts"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829406, 1773829406);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('aca8c824-d633-4965-901e-416fef14ee23', 'f0cdb7e2-fd34-449b-88b8-3fa43bd55a3b', 'MP GK', 'ग्वालियर ट्रांसफॉर्मर और संबद्ध उत्पादों का प्रमुख क्लस्टर है। मलखम्ब को 2013 में मध्य प्रदेश का राजकीय खेल घोषित किया गया था।', 'Gwalior is a major cluster for Transformers and allied products. Mallakhamba was declared the state sport of MP in 2013.', 'ग्वालियर का ट्रांसफॉर्मर (Gwalior Transformer)। 2013 में मलखम्ब (2013 Mallakhamb)।', 'Gwalior Transformer. 2013 Mallakhamb.', 'पीथमपुर (ऑटोमोबाइल) और ग्वालियर (इलेक्ट्रिकल/ट्रांसफॉर्मर) के औद्योगिक क्लस्टर्स में अंतर स्पष्ट रखें।', 'Keep the distinction clear between industrial clusters of Pithampur (Automobiles) and Gwalior (Electricals/Transformers).', 'medium', 0.85, 0.88, '[{"questionId":"cmHLSxoy9LEnyewpQikGx"},{"questionId":"qQ1xDNm_tr3tFpr0jBcXM"}]', '["MP Economy","State Symbols"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829406, 1773829406);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('f6168d2e-1873-4286-b4b2-773140b62709', 'f0cdb7e2-fd34-449b-88b8-3fa43bd55a3b', 'MP GK', 'काली मिट्टी (कपास की मिट्टी) उज्जैन (मालवा) में पाई जाती है। तवा नदी नर्मदा की सहायक है, यमुना की नहीं (चंबल, केन, बेतवा यमुना की हैं)।', 'Black soil (cotton soil) is found in Ujjain (Malwa). Tawa river is a tributary of Narmada, not Yamuna (Chambal, Ken, Betwa are of Yamuna).', 'मालवा = काली मिट्टी (Malwa = Black soil)। तवा = नर्मदा (Tawa meets Narmada)।', 'Malwa = Black soil. Tawa meets Narmada.', 'चंबल, सिंध, बेतवा और केन (CSBK) उत्तर की ओर बहकर यमुना में मिलती हैं। नर्मदा और उसकी सहायक नदियाँ पश्चिम की ओर बहती हैं।', 'Chambal, Sindh, Betwa, and Ken (CSBK) flow north to join Yamuna. Narmada and its tributaries flow west.', 'medium', 0.92, 0.95, '[{"questionId":"4cquV32HaD3CxtPPUqiY5"},{"questionId":"EISIji60P0jEK_n-ru9SZ"}]', '["MP Geography","Rivers","Soils"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829407, 1773829407);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4e01e6b5-8926-4db8-9057-764c32a75e50', 'f0cdb7e2-fd34-449b-88b8-3fa43bd55a3b', 'MP GK', 'खजुराहो के ''मतंगेश्वर मंदिर'' में आज भी नियमित पूजा होती है। टंट्या मामा आर्थिक कल्याण योजना ST वर्ग के युवाओं को स्वरोजगार (आर्थिक कल्याण) हेतु ऋण देती है। निर्मल वर्मा पुरस्कार हिंदी के प्रचार के लिए प्रवासी भारतीयों को मिलता है।', 'Regular worship still takes place in the ''Matangeshwar Temple'' of Khajuraho. Tantia Mama Arthik Kalyan Yojana provides loans for self-employment (economic welfare) to ST youth. Nirmal Verma Award is given to NRIs for Hindi promotion.', 'मतंगेश्वर में पूजा चालू (Worship active in Matangeshwar)। टंट्या मामा = आदिवासियों को रोजगार।', 'Worship active in Matangeshwar. Tantia Mama = Employment to tribals.', 'खजुराहो का कंदरिया महादेव सबसे बड़ा है, लेकिन पूजा केवल मतंगेश्वर में होती है।', 'Kandariya Mahadev is the largest in Khajuraho, but worship happens only in Matangeshwar.', 'medium', 0.88, 0.9, '[{"questionId":"4wmMVARhTQIgh4dn6xD4q"},{"questionId":"czgvbl-5A96ARpscndN1C"},{"questionId":"C2Jiikf-MUtq2D647VXKb"}]', '["Temple Architecture","Govt Schemes","State Awards"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829407, 1773829407);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('ff2853ad-c2d0-4e73-ae90-0cf2668e6a37', 'bd4e2d7f-3086-4276-9331-82bc95665411', 'Polity', 'उच्च न्यायालय (HC) के न्यायाधीशों की सेवानिवृत्ति आयु 62 वर्ष है (SC के लिए 65 वर्ष)। CAG का कार्यकाल 6 वर्ष या 65 वर्ष की आयु (जो पहले हो) तक होता है।', 'Retirement age of High Court (HC) judges is 62 years (65 for SC). The tenure of CAG is 6 years or 65 years of age (whichever is earlier).', 'HC 62, SC 65। CAG = 6 या 65।', 'HC 62, SC 65. CAG = 6 or 65.', 'चुनाव आयुक्त (CEC) का कार्यकाल भी 6/65 होता है। UPSC अध्यक्ष का 6/65, लेकिन State PSC का 6/62 होता है। तुलनात्मक रूप से याद रखें।', 'Tenure of CEC is also 6/65. UPSC Chairman is 6/65, but State PSC is 6/62. Remember comparatively.', 'medium', 0.95, 0.98, '[{"questionId":"jB_8dJ0B9l5rWQ7RZeob7"},{"questionId":"qWfh2GVx8NhYxtzgdNUdS"}]', '["Constitutional Bodies","Tenures"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829408, 1773829408);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('999259eb-9cce-4972-bccd-219ccb9f693b', 'bd4e2d7f-3086-4276-9331-82bc95665411', 'Polity', '74वां संविधान संशोधन (1992) नगरपालिकाओं (शहरी निकायों) से संबंधित है। अनुच्छेद 243 में ''पंचायत'' और ''ग्राम सभा'' की परिभाषा दी गई है।', 'The 74th Amendment (1992) deals with Municipalities (Urban bodies). Article 243 defines ''Panchayat'' and ''Gram Sabha''.', '73 = गांव (पंचायत), 74 = शहर (नगरपालिका)।', '73 = Village (Panchayat), 74 = City (Municipality).', 'अनुच्छेद 243 में परिभाषाएं हैं, 243A में ग्राम सभा और 243B में पंचायतों का गठन है। सटीक खंड (Clause) याद रखें।', 'Article 243 has definitions, 243A has Gram Sabha, and 243B has constitution of Panchayats. Remember the exact clause.', 'medium', 0.9, 0.95, '[{"questionId":"zjE0wTlVtrLhV1C7SVwzY"},{"questionId":"Qj2Lfy7A9pjkpzL6S27dN"}]', '["Local Self Government","Amendments"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829409, 1773829409);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('010602b2-c104-4a02-a6ac-e421078c7adc', 'bd4e2d7f-3086-4276-9331-82bc95665411', 'Polity', 'राष्ट्रीय ST आयोग (Art 338A) में 1 अध्यक्ष, 1 उपाध्यक्ष और 3 अन्य सदस्य (कुल 5) होते हैं। MPPSC में 1 अध्यक्ष और अधिकतम 4 सदस्य (कुल 5) हो सकते हैं।', 'National ST Commission (Art 338A) has 1 Chairman, 1 VC, and 3 other members (total 5). MPPSC can have 1 Chairman and max 4 members (total 5).', 'ST आयोग = 1+1+3 = 5। MPPSC = 1+4 = 5।', 'ST Commission = 1+1+3 = 5. MPPSC = 1+4 = 5.', 'आयोगों की संरचना (Composition) बहुत महत्वपूर्ण है। SC, ST और OBC तीनों राष्ट्रीय आयोगों की संरचना 1+1+3 ही है।', 'Composition of commissions is very important. All three National Commissions (SC, ST, OBC) have 1+1+3 structure.', 'medium', 0.88, 0.92, '[{"questionId":"SiYqf9mbgwJ0JU-2dmH7I"},{"questionId":"PAXE50ICX6yVc8Dqt25Up"}]', '["Commissions","Composition"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829409, 1773829409);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('1840480d-fcda-410d-bafe-cefffa4e801d', 'bd4e2d7f-3086-4276-9331-82bc95665411', 'Polity', 'राज्य विधानसभा में ''धन विधेयक'' का निर्णय ''विधानसभा अध्यक्ष'' (Speaker) करता है। लोक सेवा आयोगों का खर्च (व्यय) अनुच्छेद 322 के तहत संचित निधि पर भारित है।', 'In the State Assembly, the decision of a ''Money Bill'' is made by the ''Speaker''. Expenses of PSCs are charged on the Consolidated Fund under Article 322.', 'पैसे (Money Bill) का फैसला स्पीकर (Speaker) करेगा। 322 में आयोग का खर्चा (Expenses in 322)।', 'Decision of Money Bill is by the Speaker. Expenses of Commission in 322.', 'केंद्र में धन विधेयक का निर्णय लोकसभा स्पीकर (Art 110) करता है, राज्य में विधानसभा स्पीकर (Art 199)। राज्यपाल/राष्ट्रपति नहीं करते।', 'At center, Lok Sabha Speaker decides (Art 110), in state Vidhan Sabha Speaker (Art 199). Governor/President don''t decide.', 'medium', 0.85, 0.9, '[{"questionId":"utvys4JCftsPRncjGWTso"},{"questionId":"3FjsWY3leLIK6PTFj59MD"}]', '["State Legislature","Articles"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829409, 1773829409);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('2633cb98-27e1-4557-b295-45efbf3a7dc0', 'bd4e2d7f-3086-4276-9331-82bc95665411', 'Polity', 'मानवाधिकार (PHR Act 1993) में जीवन, स्वतंत्रता, समानता और गरिमा शामिल हैं (शिक्षा स्पष्ट रूप से नहीं)। राष्ट्रीय महिला आयोग के कार्य धारा 10 में हैं। खाद्य आयोग NFSA 2013 के तहत बनता है।', 'Human Rights (PHR Act 1993) includes life, liberty, equality, and dignity (education not explicitly). Functions of National Commission for Women are in Section 10. Food Commission is formed under NFSA 2013.', 'मानवाधिकार = Life, Liberty, Equality, Dignity। महिला आयोग का काम ''दस'' (Section 10)। खाद्य = NFSA 2013।', 'Human Rights = Life, Liberty, Equality, Dignity. Women Comm function ''Ten'' (Section 10). Food = NFSA 2013.', 'राष्ट्रीय और राज्य स्तर के सभी सांविधिक (Statutory) आयोगों के ''अधिनियम का वर्ष'' और ''धारा'' (Section) जिसमें उनके कार्य लिखे हैं, रट लें।', 'Rote learn the ''Year of Act'' and the ''Section'' describing functions for all statutory commissions at National and State levels.', 'medium', 0.9, 0.94, '[{"questionId":"9Vmp9zzYM3ywpJDmFbATY"},{"questionId":"-KEAixOIGEukE7SBzy_lM"},{"questionId":"SMuwpaky4u9mHIBgXGtOn"}]', '["Statutory Bodies","Acts"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829409, 1773829409);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('65880c8a-8cb5-4f07-88c2-adc7f0bd5332', '008e003a-0c79-4bdc-8dae-a849d5deab4e', 'Current Affairs', '2022 का मेजर ध्यानचंद खेल रत्न पुरस्कार टेबल टेनिस खिलाड़ी ''अचंता शरत कमल'' को दिया गया था (एकमात्र विजेता)।', 'The 2022 Major Dhyan Chand Khel Ratna Award was given to Table Tennis player ''Achanta Sharath Kamal'' (sole winner).', 'खेलों का ''कमल'' (Kamal of Sports - Sharath Kamal)।', 'Kamal of Sports - Sharath Kamal.', 'मेजर ध्यानचंद खेल रत्न भारत का सर्वोच्च खेल पुरस्कार है (पहले इसे राजीव गांधी खेल रत्न कहा जाता था)। वर्ष 2023 के लिए यह सात्विकसाईराज और चिराग शेट्टी (बैडमिंटन) को मिला है।', 'Major Dhyan Chand Khel Ratna is India''s highest sports award (formerly Rajiv Gandhi Khel Ratna). For 2023, it went to Satwiksairaj and Chirag Shetty (Badminton).', 'medium', 0.95, 0.98, '[{"questionId":"qJwSQCgjKHbnU4qtSAbl4"}]', '["Sports Awards","Table Tennis"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829410, 1773829410);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('db90b0ac-3e16-423b-95ba-cf7f39e40caf', '008e003a-0c79-4bdc-8dae-a849d5deab4e', 'Current Affairs', 'भारत ने अपना पहला ODI (एकदिवसीय) क्रिकेट मैच 1974 में इंग्लैंड के खिलाफ खेला था।', 'India played its first ODI (One Day International) cricket match against England in 1974.', 'ODI की शुरुआत 74 से (ODI start in ''74)।', 'ODI start in ''74.', 'पहला टेस्ट 1932 में खेला था, पहला T20 2006 में। ODI वर्ष (1974) याद रखें।', 'First Test was played in 1932, first T20 in 2006. Remember the ODI year (1974).', 'medium', 0.8, 0.85, '[{"questionId":"sFq6zeILRxxI-VV4pLI3J"}]', '["Cricket History","Sports"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829410, 1773829410);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('107b00b7-2300-4722-98de-edae91253b0c', '008e003a-0c79-4bdc-8dae-a849d5deab4e', 'Current Affairs', 'वन्दना कटारिया, सुशीला चानू और मोनिका टोक्यो ओलंपिक 2020 में शानदार प्रदर्शन (चौथा स्थान) करने वाली भारतीय महिला हॉकी टीम का हिस्सा थीं।', 'Vandana Katariya, Sushila Chanu, and Monika were part of the Indian women''s hockey team that performed brilliantly (4th place) at Tokyo Olympics 2020.', 'हॉकी की शेरनियां: वन्दना, सुशीला, मोनिका।', 'Lionesses of Hockey: Vandana, Sushila, Monika.', 'वन्दना कटारिया ने ओलंपिक में हैट्रिक लगाई थी (ऐसा करने वाली पहली भारतीय महिला)। खिलाड़ियों के नाम और उनके खेल का मिलान बहुत सामान्य प्रश्न है।', 'Vandana Katariya scored a hat-trick in the Olympics (first Indian woman to do so). Matching players'' names with their sports is a very common question.', 'medium', 0.85, 0.9, '[{"questionId":"4CggouH72OVc3GOWH8W-w"}]', '["Olympics","Hockey","Sports Personalities"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829410, 1773829410);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('2ee6b2ba-3e03-434f-86f8-952279051fd5', '008e003a-0c79-4bdc-8dae-a849d5deab4e', 'Current Affairs', 'एमेच्योर कबड्डी फेडरेशन ऑफ इंडिया (AKFI) का मुख्यालय जयपुर (राजस्थान) में स्थित है।', 'The headquarters of Amateur Kabaddi Federation of India (AKFI) is located in Jaipur (Rajasthan).', 'कबड्डी का गढ़ = जयपुर (जयपुर पिंक पैंथर्स याद करें)।', 'Hub of Kabaddi = Jaipur (Think Jaipur Pink Panthers).', 'खेल संघों के मुख्यालय अक्सर नई दिल्ली में होते हैं, इसलिए इस अपवाद (जयपुर) को विशेष रूप से याद रखें।', 'Headquarters of sports federations are often in New Delhi, so specifically remember this exception (Jaipur).', 'medium', 0.75, 0.82, '[{"questionId":"iLu5AnvmLyQvk9DFi6OIn"}]', '["Sports Institutes","Kabaddi"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829410, 1773829410);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3510d2cd-e476-4625-9559-fa6166fd8d21', 'f9770ced-b1ef-4edd-8582-1f321b4ad674', 'ICT', 'अप्रैल 2023 में भारतीय थल सेनाध्यक्ष जनरल मनोज पांडे थे (वे कोर ऑफ इंजीनियर्स से बनने वाले पहले सेनाध्यक्ष हैं)।', 'In April 2023, the Chief of the Army Staff was Gen. Manoj Pande (first from the Corps of Engineers to become COAS).', 'मनोज पांडे = इंजीनियर से सेना प्रमुख (Engineer to Army Chief)।', 'Manoj Pande = Engineer to Army Chief.', 'रक्षा नियुक्तियों (सेना, नौसेना, वायुसेना प्रमुख) को हमेशा परीक्षा से ठीक पहले अपडेट कर लें।', 'Always update defense appointments (Army, Navy, Air Force Chiefs) just before the exam.', 'medium', 0.85, 0.9, '[{"questionId":"FY389BNtYsvQ-TGQxAYJZ"}]', '["Defense Appointments","Current Affairs"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829416, 1773829416);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('f805df57-8b60-4ee9-b056-e261bdbdf1fb', 'f9770ced-b1ef-4edd-8582-1f321b4ad674', 'ICT', 'AFINDEX-2023 (अफ्रीका-इंडिया फील्ड ट्रेनिंग एक्सरसाइज) का दूसरा संस्करण पुणे (महाराष्ट्र) में आयोजित हुआ।', 'The second edition of AFINDEX-2023 (Africa-India Field Training Exercise) was held in Pune (Maharashtra).', 'AFINDEX (Africa-India) = पुणे में अभ्यास (Exercise in Pune)।', 'AFINDEX (Africa-India) = Exercise in Pune.', 'विदेशी सेनाओं के साथ होने वाले प्रमुख सैन्य अभ्यासों (Military Exercises) के नाम और स्थान (विशेषकर यदि भारत में हुए हों) अनिवार्य हैं।', 'Names and locations of major military exercises with foreign armies (especially if held in India) are mandatory.', 'medium', 0.8, 0.88, '[{"questionId":"7UvyeUfLOAhEyD76ZVq76"}]', '["Military Exercises"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829416, 1773829416);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('579add16-774b-464c-aef3-b7c24fb004b8', 'd9b8326e-48a9-423e-9891-8b1a04d4c81b', 'Economy', 'विदेशी व्यापार (Foreign Trade) से बाजार में प्रतिस्पर्धा (Competition) बढ़ती है, जो दक्षता और गुणवत्ता के लिए लाभदायक है।', 'Foreign trade increases competition in the market, which is beneficial for efficiency and quality.', 'व्यापार = प्रतिस्पर्धा (Trade = Competition)।', 'Trade = Competition.', 'यह एक वैचारिक (Conceptual) प्रश्न था। विदेशी व्यापार से एकाधिकार (Monopoly) टूटता है और ग्राहकों को फायदा होता है।', 'This was a conceptual question. Foreign trade breaks monopolies and benefits consumers.', 'medium', 0.7, 0.85, '[{"questionId":"o23z5Ie3-yf3CsGtEhDkO"}]', '["Foreign Trade","Economic Concepts"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829417, 1773829417);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6207b9cf-1475-4627-92a8-fdf3b326246a', 'd9b8326e-48a9-423e-9891-8b1a04d4c81b', 'Economy', 'भारतीय रिज़र्व बैंक (RBI) का राष्ट्रीयकरण 1 जनवरी 1949 को किया गया था।', 'The Reserve Bank of India (RBI) was nationalized on January 1, 1949.', 'आजादी (1947) के ठीक बाद, 49 में RBI सरकार का हुआ।', 'Right after Independence (1947), RBI became Govt''s in ''49.', 'स्थापना 1935 में हुई थी, लेकिन ''राष्ट्रीयकरण'' 1949 में हुआ। प्रश्न को ध्यान से पढ़ें। 14 बैंकों का राष्ट्रीयकरण 1969 में हुआ था।', 'Established in 1935, but ''nationalized'' in 1949. Read carefully. 14 banks were nationalized in 1969.', 'medium', 0.95, 0.98, '[{"questionId":"wjR18lQcACPhpsy9d3_mk"}]', '["RBI History","Banking"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829417, 1773829417);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('25d33353-a580-41aa-96c6-ea6278a34d8f', 'e5aa91a0-2cc5-4869-9b9a-bd42385bcddb', 'Polity', 'प्रसंस्कृत फल उत्पादों (Processed Fruit Products - जैसे जैम, जूस) के लिए ''FPO (Fruit Products Order)'' मार्क अनिवार्य है।', 'For processed fruit products (like jams, juices), the ''FPO (Fruit Products Order)'' mark is mandatory.', 'F for Fruit, F for FPO.', 'F for Fruit, F for FPO.', 'Agmark (कृषि उत्पाद), ISI (औद्योगिक), और Hallmark (आभूषण) को स्पष्ट रूप से अलग रखें।', 'Keep Agmark (Agricultural), ISI (Industrial), and Hallmark (Jewelry) clearly distinct.', 'medium', 0.85, 0.88, '[{"questionId":"zxUYErPEDHqlUevdEgCeE"}]', '["Certification Marks","Acts"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829417, 1773829417);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3f61f3a4-4781-4023-832a-e0e95a3c2730', 'e9693e57-5d71-4384-9433-5715a72ab48b', 'Geography', 'दो पारिस्थितिकी तंत्रों के मध्य संक्रमण क्षेत्र (Transition zone) को ''इकोटोन (Ecotone)'' कहा जाता है (जैसे जंगल और घास के मैदान के बीच का क्षेत्र)।', 'The transition zone between two ecosystems is called ''Ecotone'' (e.g., the area between a forest and a grassland).', 'इकोटोन = दो टोन (Ecosystems) का मिलन।', 'Ecotone = Meeting of two tones (Ecosystems).', 'यहाँ जैव विविधता सबसे अधिक होती है, जिसे ''एज इफ़ेक्ट (Edge Effect)'' कहते हैं। इकोटाइप (Ecotype) एक अलग अवधारणा है।', 'Biodiversity is highest here, called the ''Edge Effect''. Ecotype is a different concept.', 'medium', 0.9, 0.94, '[{"questionId":"SBlMOXvBjdYyb0-h_25kK"}]', '["Ecology Concepts","Definitions"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829418, 1773829418);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('ef05f887-2f47-4caa-8ca1-296d030ee037', 'e9693e57-5d71-4384-9433-5715a72ab48b', 'Geography', 'पश्चिमी घाट (Western Ghats) भारत का एक प्रमुख ''जैव-विविधता हॉटस्पॉट'' (Biodiversity Hotspot) है।', 'The Western Ghats is a major ''Biodiversity Hotspot'' in India.', 'पश्चिमी घाट = हॉटस्पॉट (बहुत बारिश, बहुत पेड़)।', 'Western Ghats = Hotspot (Heavy rain, lots of trees).', 'भारत में केवल 4 हॉटस्पॉट हैं। पूर्वी घाट (Eastern Ghats) हॉटस्पॉट नहीं है।', 'There are only 4 hotspots in India. Eastern Ghats is NOT a hotspot.', 'medium', 0.95, 0.96, '[{"questionId":"gu4T9DmIoOGzBcSwOSfmZ"}]', '["Biodiversity","Indian Geography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829418, 1773829418);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a6b7ed7d-7fc2-4f91-8a54-db778b0e26f8', 'e9693e57-5d71-4384-9433-5715a72ab48b', 'Geography', 'कैडमियम (Cadmium) प्रदूषण के कारण मनुष्यों में ''इटाई-इटाई'' (Itai-Itai) नामक रोग होता है (हड्डियों में दर्द)।', 'Cadmium pollution causes ''Itai-Itai'' disease in humans (severe bone pain).', 'कैडमियम -> इटाई-इटाई (दर्द की आवाज़)।', 'Cadmium -> Itai-Itai (Sound of pain).', 'पारा (Mercury) मिनामाता रोग करता है, जबकि कैडमियम इटाई-इटाई। दोनों जापानी नाम हैं, भ्रमित न हों।', 'Mercury causes Minamata, while Cadmium causes Itai-Itai. Both are Japanese names, don''t confuse them.', 'medium', 0.92, 0.95, '[{"questionId":"BtxD_SYlF9244bvCRq7pR"}]', '["Pollution Diseases","Human Health"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829418, 1773829418);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('fd71c85f-8e3f-415b-aa7f-6d289028b581', '77992496-6a6a-4ee3-bf98-091f4ce08ffa', 'Science', 'विटामिन K (Phylloquinone) रक्त का थक्का (Blood Clotting) जमने में सहायक होता है।', 'Vitamin K (Phylloquinone) helps in Blood Clotting.', 'K = Klotting (Clotting)।', 'K = Klotting.', 'विटामिन E रिकेट्स के लिए है, B12 एनीमिया के लिए। थक्के के लिए हमेशा K को चुनें।', 'Vitamin E is for Rickets, B12 for Anemia. Always choose K for clotting.', 'medium', 0.95, 0.98, '[{"questionId":"b_3wSXqnJOlij4dixVjCq"}]', '["Vitamins","Human Biology"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829418, 1773829418);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('ae501a49-b674-4d7a-9ebf-5ade7348efb4', '77992496-6a6a-4ee3-bf98-091f4ce08ffa', 'Science', 'गर्दन की एटलस (C1) और अक्ष (C2) कशेरुकाओं के बीच ''पिवोट जॉइंट'' (Pivot Joint) होता है, जो सिर को घुमाने में मदद करता है।', 'The joint between the Atlas (C1) and Axis (C2) vertebrae in the neck is a ''Pivot Joint'', which helps rotate the head.', 'एटलस दुनिया (सिर) का भार उठाता है, पिवोट उसे घुमाता है।', 'Atlas carries the world (head), Pivot rotates it.', 'कंधे और कूल्हे में ''बॉल एंड सॉकेट'' (Ball & Socket) जॉइंट होता है। पिवोट (धुराग्र) गर्दन में होता है।', 'Shoulder and hip have ''Ball & Socket'' joints. Pivot is in the neck.', 'medium', 0.8, 0.88, '[{"questionId":"x2yomHYbqZ_w8ZWproFFB"}]', '["Skeletal System","Joints"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829418, 1773829418);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7817fdbd-ee3d-4882-ab78-aafb6253e515', '77992496-6a6a-4ee3-bf98-091f4ce08ffa', 'Science', 'अत्यंत उच्च गति स्विचिंग (High-speed switching) के लिए ''शॉट्की डायोड'' (Schottky Diode) का उपयोग किया जाता है।', 'The ''Schottky Diode'' is used for extremely high-speed switching electronic circuits.', 'शॉट्की = शॉट (तेज/Fast)।', 'Schottky = Shot (Fast).', 'जेनर डायोड (Zener Diode) का उपयोग वोल्टेज रेगुलेशन (Voltage Regulation) के लिए होता है।', 'Zener Diode is used for Voltage Regulation.', 'medium', 0.75, 0.85, '[{"questionId":"NR2sbAvIfsd6s6ii1nsv5"}]', '["Electronics","Diodes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829418, 1773829418);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('8dabb072-e64e-4fea-8e5b-0892a20b5195', '77992496-6a6a-4ee3-bf98-091f4ce08ffa', 'Science', 'इलेक्ट्रॉनिक उपकरणों में ''अशुद्धि अन्तःक्षेप'' (Impurity Injection/Doping) का उपयोग बहुसंख्यक वाहक बढ़ाने के लिए होता है, इसे ''इलेक्ट्रॉन-होल युग्म'' जनरेशन नहीं कहते (जो ऊष्मा या प्रकाश से होता है)।', 'In electronics, ''Impurity Injection'' (Doping) increases majority carriers, it is NOT considered generation of ''electron-hole pairs'' (which happens via heat or light).', 'डोपिंग से एक प्रकार का कैरियर (Electron या Hole) बढ़ता है, जोड़ी (Pair) नहीं।', 'Doping increases one type of carrier (Electron or Hole), not a Pair.', 'यह एक वैचारिक (Conceptual Physics) प्रश्न था। थर्मल या ऑप्टिकल ऊर्जा इलेक्ट्रॉन और होल दोनों की जोड़ी (Pair) बनाती है।', 'This was a conceptual physics question. Thermal or optical energy generates a pair (both electron and hole).', 'medium', 0.7, 0.8, '[{"questionId":"p4Pu__fR2ee73Wojvm4wf"}]', '["Semiconductors","Physics"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829418, 1773829418);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('67796c44-c67d-4e49-adc4-d93fdd18abb1', '242a939c-7a9f-47ca-9af0-f12c7f956b12', 'History', 'गुजरात भारत में मूंगफली (Groundnut) का सबसे बड़ा उत्पादक राज्य है।', 'Gujarat is the largest producer of groundnut in India.', 'G for Gujarat, G for Groundnut।', 'G for Gujarat, G for Groundnut.', 'मूंगफली एक खरीफ (Kharif) फसल है। राजस्थान सरसों में और म.प्र. सोयाबीन में आगे है।', 'Groundnut is a Kharif crop. Rajasthan leads in Mustard, MP in Soybean.', 'medium', 0.85, 0.9, '[{"questionId":"bdBcPuux_Uq8ot7y5oj1k"}]', '["Agriculture Rank","Geography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829419, 1773829419);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6336178c-4a1b-487e-b2b5-26d148a4da65', '242a939c-7a9f-47ca-9af0-f12c7f956b12', 'History', 'जनगणना 2011: मेघालय की दशकीय जनसंख्या वृद्धि दर (27.9%) सर्वाधिक थी।', 'Census 2011: Meghalaya had the highest decadal population growth rate (27.9%).', 'मेघालय में जनसंख्या बादलों (Megha) की तरह बढ़ी।', 'Population grew like clouds (Megha) in Meghalaya.', 'सबसे कम (ऋणात्मक) वृद्धि दर नागालैंड (-0.6%) में थी।', 'The lowest (negative) growth rate was in Nagaland (-0.6%).', 'medium', 0.95, 0.96, '[{"questionId":"JnKb2hN2W3ilc-fWkvMZ4"}]', '["Census 2011","Demography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829419, 1773829419);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('111199fc-b33f-492b-b4ae-3903fd60a55e', '242a939c-7a9f-47ca-9af0-f12c7f956b12', 'History', 'जनगणना 2011: मिजोरम की साक्षरता दर (और महिला साक्षरता) केरल के बाद सबसे अधिक है। (दिए गए विकल्पों में सर्वोच्च)।', 'Census 2011: Mizoram''s literacy rate (and female literacy) is second only to Kerala. (Highest among the given options).', 'केरल (1st), मिजोरम (2nd)।', 'Kerala (1st), Mizoram (2nd).', 'अक्सर ''केरल'' विकल्प में नहीं दिया जाता है, तब आपको मिजोरम (Mizoram) को चुनना होता है।', 'Often ''Kerala'' is not given in the options, then you have to choose Mizoram.', 'medium', 0.92, 0.95, '[{"questionId":"c_Kyacc_dlwJPMPTYAQW7"}]', '["Census 2011","Literacy"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829419, 1773829419);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3150d91c-e952-4f8d-94cf-4d3beeaf1940', '3863d9e2-1e8a-4009-9d93-25a923ce1a4d', 'Geography', 'सुन्दरबन (पश्चिम बंगाल) ''तटीय या ज्वारीय वन'' (Littoral or Tidal forests / Mangroves) के उदाहरण हैं।', 'Sundarbans (West Bengal) are examples of ''Littoral or Tidal forests'' (Mangroves).', 'तट (Coast) पर ज्वार (Tide) आता है, जहाँ सुंदरबन (Mangroves) हैं।', 'Tide comes on the coast, where Sundarbans (Mangroves) are.', 'इन्हें उष्णकटिबंधीय सदाबहार (Tropical Evergreen) वन न कहें, उनकी विशेषताएं अलग होती हैं। मैंग्रोव खारे पानी में पनपते हैं।', 'Do not call them Tropical Evergreen forests, their characteristics are different. Mangroves thrive in saline water.', 'medium', 0.9, 0.94, '[{"questionId":"uPk4GJzTsi0e5KsGVS9kD"}]', '["Forest Types","Geography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829420, 1773829420);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c2c95d4a-4140-446f-aa59-1231de09804f', '3863d9e2-1e8a-4009-9d93-25a923ce1a4d', 'Geography', 'भारत में पवन ऊर्जा (Wind Energy) क्षमता में तमिलनाडु, गुजरात और महाराष्ट्र शीर्ष पर हैं। मध्य प्रदेश इस सूची में काफी नीचे है।', 'Tamil Nadu, Gujarat, and Maharashtra top India''s Wind Energy capacity. Madhya Pradesh is far below on this list.', 'हवा तटों पर तेज़ चलती है (Wind is strong on coasts: TN, Gujarat)।', 'Wind is strong on coasts: TN, Gujarat.', 'सौर ऊर्जा (Solar Energy) में राजस्थान शीर्ष पर है, लेकिन पवन (Wind) में तमिलनाडु/गुजरात।', 'Rajasthan tops in Solar Energy, but TN/Gujarat in Wind.', 'medium', 0.85, 0.88, '[{"questionId":"ULFD_h8CCF3emNJUMItbG"}]', '["Renewable Energy","State Rankings"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829420, 1773829420);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('32d78b16-41b0-4f2f-895d-93c3687581a3', '3863d9e2-1e8a-4009-9d93-25a923ce1a4d', 'Geography', 'नर्मदा (1312 km) प्रायद्वीपीय भारत की प्रमुख और पश्चिम की ओर बहने वाली सबसे लंबी नदी है।', 'Narmada (1312 km) is a major and the longest west-flowing river of peninsular India.', 'नर्मदा सबसे लंबी (पश्चिम की ओर)।', 'Narmada longest (west-flowing).', 'गोदावरी पूरे प्रायद्वीप की सबसे लंबी है, लेकिन दिए गए विकल्पों (ताप्ती, कावेरी, सोन) में नर्मदा सबसे लंबी थी।', 'Godavari is the longest of the entire peninsula, but among the given options (Tapti, Kaveri, Son), Narmada was the longest.', 'medium', 0.95, 0.96, '[{"questionId":"WFWjo4mpH_9QHYL_c4rA7"}]', '["Rivers","Geography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829420, 1773829420);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4297e302-b9b0-43b5-939f-5c9adb432307', '3863d9e2-1e8a-4009-9d93-25a923ce1a4d', 'Geography', 'पारिस्थितिकी तंत्र में ऊर्जा का प्रवाह 10% नियम (Lindeman) का पालन करता है; यह ऊष्मागतिकी के दूसरे नियम (Second Law of Thermodynamics) पर आधारित है।', 'Energy flow in an ecosystem follows the 10% rule (Lindeman); it is based on the Second Law of Thermodynamics.', '10% ही आगे जाएगा, बाकी ऊष्मा (Heat) बनकर उड़ेगा (Thermodynamics)।', 'Only 10% goes forward, rest evaporates as heat (Thermodynamics).', 'ऊर्जा प्रवाह हमेशा एकदिशीय (Unidirectional) होता है, यह कभी वापस नहीं लौटता।', 'Energy flow is always Unidirectional, it never reverses.', 'medium', 0.88, 0.92, '[{"questionId":"UbDoVkiAbm3aXUAqAjsVD"}]', '["Ecology","Energy Flow"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829420, 1773829420);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7790f025-1618-44a0-8205-d618545dd6c1', 'ee2fe9b8-0290-43a5-9ab0-dc897c578bf0', 'Science', 'सौभाग्य योजना (PM Sahaj Bijli Har Ghar Yojana) 2017 में विद्युत मंत्रालय (Ministry of Power) द्वारा शुरू की गई थी।', 'Saubhagya Yojana (PM Sahaj Bijli Har Ghar Yojana) was launched in 2017 by the Ministry of Power.', 'सौभाग्य = बिजली (Sahaj Bijli)।', 'Saubhagya = Electricity.', 'इसे ''उजाला'' (LED बल्ब) या ''उज्ज्वला'' (LPG गैस) योजना से भ्रमित न करें।', 'Do not confuse it with ''Ujala'' (LED bulbs) or ''Ujjwala'' (LPG gas) schemes.', 'medium', 0.85, 0.88, '[{"questionId":"SHwKdlsTS6gznfqw-ZrPk"}]', '["Government Schemes","Power Sector"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829420, 1773829420);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('76dde61d-7548-43df-854c-5bed2e7bdf7b', 'ee2fe9b8-0290-43a5-9ab0-dc897c578bf0', 'Science', 'AYUSH का अर्थ है: Ayurveda, Yoga & Naturopathy, Unani, Siddha, Homeopathy।', 'AYUSH stands for: Ayurveda, Yoga & Naturopathy, Unani, Siddha, Homeopathy.', 'A-Y-U-S-H: 5 पारंपरिक चिकित्सा प्रणालियां।', 'A-Y-U-S-H: 5 traditional medicine systems.', '''A'' का मतलब Allopathy नहीं है (वह आधुनिक चिकित्सा है)। ''S'' का मतलब Surgery नहीं है।', '''A'' does not mean Allopathy (that''s modern medicine). ''S'' does not mean Surgery.', 'medium', 0.9, 0.95, '[{"questionId":"Cpiki1lywKye1JoqitT36"}]', '["Abbreviations","Health"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829420, 1773829420);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('77f32d0e-2c05-4fe9-9305-ecf6c552fd69', 'ee2fe9b8-0290-43a5-9ab0-dc897c578bf0', 'Science', 'केन्द्रीय भारतीय भाषा संस्थान (CIIL) मैसूर (Mysuru, Karnataka) में स्थित है।', 'The Central Institute of Indian Languages (CIIL) is located in Mysuru (Karnataka).', 'भाषा = मैसूर (Language in Mysore)।', 'Language in Mysore.', 'संस्थानों के मुख्यालयों के ''मैच द कॉलम'' प्रश्नों में इसका अक्सर उपयोग होता है। इसे दिल्ली या मुम्बई में न मानें।', 'It is frequently used in ''Match the Column'' questions for institute headquarters. Don''t assume it''s in Delhi or Mumbai.', 'medium', 0.8, 0.85, '[{"questionId":"NxhBf528t94AXo8bFMtKf"}]', '["Institutions","Education"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829420, 1773829420);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a914b66c-2cd0-44d9-a09d-60b7dc3b780a', '07a4c57c-82b0-4c4d-81a6-243fc16acaea', 'History', 'सांची स्तूप (MP) के तोरण द्वार पर अशोक की बोधिवृक्ष तीर्थयात्रा का अंकन है। ''बलसार'' (गुजरात) में बौद्ध गुफाएं नहीं हैं (बाघ, अजंता में हैं)।', 'The gateway (Torana) of Sanchi Stupa (MP) depicts Ashoka''s pilgrimage to the Bodhi Tree. ''Balsar'' (Gujarat) does not have Buddhist caves (Bagh, Ajanta do).', 'सांची के तोरण पर अशोक की यात्रा। बाघ (धार) में बौद्ध गुफाएं।', 'Ashoka''s journey on Sanchi''s Torana. Buddhist caves in Bagh (Dhar).', 'सांची में गौतम बुद्ध के अवशेष नहीं हैं, बल्कि उनके शिष्यों (सारिपुत्र और महामोग्गलायन) के हैं।', 'Sanchi does NOT contain the relics of Gautam Buddha, but of his disciples (Sariputra and Mahamoggallana).', 'medium', 0.9, 0.96, '[{"questionId":"RH1ZXtPVQZ-_R_mTyJM1_"},{"questionId":"C_i1wsr-sDITxni6KB75t"}]', '["Buddhism","Art & Architecture"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829421, 1773829421);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0633e402-5bc8-4229-b4c6-68f8cd65909f', '07a4c57c-82b0-4c4d-81a6-243fc16acaea', 'History', 'भक्ति आंदोलन: अलवार (विष्णु भक्त) 12 थे, और नयनार (शिव भक्त) 63 थे। कबीर ने कहा था: ''ढाई आखर प्रेम का, पढ़े सो पंडित होय''।', 'Bhakti Movement: Alvars (Vishnu devotees) were 12, and Nayanars (Shiva devotees) were 63. Kabir said: ''Reading two and a half letters of Love makes one a scholar''.', 'अलवार (12) कम थे, नयनार (63) ज्यादा। कबीर = प्रेम के ढाई आखर।', 'Alvars (12) were fewer, Nayanars (63) more. Kabir = Two and a half letters of Love.', 'अलवार और नयनार के ''देवता'' (विष्णु/शिव) को उल्टा न करें।', 'Do not swap the ''deity'' (Vishnu/Shiva) of Alvars and Nayanars.', 'medium', 0.88, 0.94, '[{"questionId":"zZmCrrek454fOvy9h-3bG"},{"questionId":"1M0NGJy7wf5L3KUBInHd1"}]', '["Bhakti Movement","Literature"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829421, 1773829421);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('baab3bc2-a317-4d50-ad52-f06da81a95ad', '07a4c57c-82b0-4c4d-81a6-243fc16acaea', 'History', 'विजयनगर साम्राज्य की स्थापना 1336 में हरिहर और बुक्का ने की थी। ''तहकीक-ए-हिन्द'' (किताब-उल-हिन्द) अल-बरूनी की रचना है।', 'Vijayanagara Empire was established in 1336 by Harihara and Bukka. ''Tahqiq-i-Hind'' (Kitab-ul-Hind) is authored by Al-Biruni.', 'विजयनगर (1336)। अल-बरूनी की हिन्द (Biruni''s Hind)।', 'Vijayanagara (1336). Al-Biruni''s Hind.', 'अल-बरूनी महमूद गजनवी के साथ आया था, इब्न बतूता मुहम्मद बिन तुगलक के समय।', 'Al-Biruni came with Mahmud Ghaznavi, Ibn Battuta during Muhammad bin Tughlaq.', 'medium', 0.92, 0.95, '[{"questionId":"SQReWb6rRtruI4UJRYRcE"},{"questionId":"Lpp0AkA5CFGtigJ4W2R1j"}]', '["Medieval History","Foreign Travelers"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829421, 1773829421);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('296803e8-42c0-494c-bf6b-7435cea967ba', '940aec25-37b6-4c8d-8d7e-4a61872d7b6b', 'History', 'भारत छोड़ो आंदोलन 9 अगस्त 1942 को शुरू हुआ। संथाल विद्रोह (1855) का नेतृत्व सिद्धो और कान्हू ने किया था।', 'Quit India Movement started on August 9, 1942. Santhal Rebellion (1855) was led by Siddhu and Kanhu.', 'अगस्त क्रांति 1942 (August Kranti 1942)। संथाल = सिद्धो/कान्हू।', 'August Kranti 1942. Santhal = Siddhu/Kanhu.', 'मुंडा विद्रोह (बिरसा मुंडा, 1899) अलग है और संथाल (1855) अलग है। दोनों झारखंड क्षेत्र के महान विद्रोह हैं।', 'Munda Rebellion (Birsa Munda, 1899) is different from Santhal (1855). Both are great rebellions of the Jharkhand region.', 'medium', 0.95, 0.98, '[{"questionId":"Y8u2elQEPjv_mvttenJb0"},{"questionId":"G5kaLjS5DN4gN4qb5z-AW"}]', '["Freedom Movement","Tribal Revolts"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829422, 1773829422);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e5655fac-24cb-4670-b452-8faa18ef8528', '940aec25-37b6-4c8d-8d7e-4a61872d7b6b', 'History', 'चम्पारण सत्याग्रह (1917) ''तिनकठिया पद्धति'' (3/20 भाग पर नील की खेती) के खिलाफ था।', 'Champaran Satyagraha (1917) was against the ''Tinkathia system'' (indigo cultivation on 3/20th part of land).', 'चंपारण (पहला सत्याग्रह) = तिनकठिया (नील)।', 'Champaran (First Satyagraha) = Tinkathia (Indigo).', 'खेड़ा सत्याग्रह (1918) लगान माफी के लिए था, अहमदाबाद मिल हड़ताल (1918) प्लेग बोनस के लिए।', 'Kheda Satyagraha (1918) was for revenue exemption, Ahmedabad Mill Strike (1918) for plague bonus.', 'medium', 0.9, 0.96, '[{"questionId":"exfVtGTUSMogdkkXRa_6e"}]', '["Gandhian Era","Peasant Movements"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829422, 1773829422);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a36dbe16-75b2-4653-9e86-67cbaa24074f', '940aec25-37b6-4c8d-8d7e-4a61872d7b6b', 'History', 'प्रार्थना समाज (1867) और परमहंस मंडली (1849) दोनों की स्थापना महाराष्ट्र (बॉम्बे) में हुई थी।', 'Both Prarthana Samaj (1867) and Paramahansa Mandali (1849) were founded in Maharashtra (Bombay).', 'महाराष्ट्र में प्रार्थना (Prayer in Maharashtra)।', 'Prayer in Maharashtra.', 'आत्मीय सभा और ब्रह्म समाज बंगाल में स्थापित हुए थे, प्रार्थना समाज महाराष्ट्र में।', 'Atmiya Sabha and Brahmo Samaj were founded in Bengal, Prarthana Samaj in Maharashtra.', 'medium', 0.85, 0.88, '[{"questionId":"WE9jXwHAZ4fUqW9Rxc71l"},{"questionId":"FzzNyel5AnYdJkxIkRpH0"}]', '["Social Reforms"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829422, 1773829422);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('48f0bd4b-2de3-4609-95cf-b244afad2cac', '940aec25-37b6-4c8d-8d7e-4a61872d7b6b', 'History', '1919 के अधिनियम (मोंटेग्यू-चेम्सफोर्ड) ने ''प्रांतों'' (Provinces) में ''द्वैध शासन'' (Dyarchy) की स्थापना की।', 'The Act of 1919 (Montagu-Chelmsford) established ''Dyarchy'' in the ''Provinces''.', '1919 = प्रांत में द्वैध (Dyarchy in Province)। 1935 = केंद्र में द्वैध (Dyarchy at Center)।', '1919 = Dyarchy in Province. 1935 = Dyarchy at Center.', '1935 के अधिनियम ने प्रांतों में द्वैध शासन ''समाप्त'' कर दिया और इसे ''केंद्र'' में लागू किया। यह सबसे आम ट्रैप है।', 'The Act of 1935 ''abolished'' dyarchy in provinces and applied it at the ''Center''. This is the most common trap.', 'medium', 0.98, 0.99, '[{"questionId":"F7_jJJoVs_kP4iUqTgZFM"}]', '["Constitutional History","British Acts"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829422, 1773829422);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6c4a1098-7e50-4404-82eb-c1d7e15ba1be', '3ac7f321-0f6f-45fe-8473-0433c9730846', 'Current Affairs', 'फीफा विश्व कप 2022 (कतर) में लियोनेल मेस्सी (अर्जेंटीना) ने ''गोल्डन बॉल'' (सर्वश्रेष्ठ खिलाड़ी) पुरस्कार जीता।', 'Lionel Messi (Argentina) won the ''Golden Ball'' (Best Player) award at the FIFA World Cup 2022 (Qatar).', 'मेस्सी = बॉल (Best Player), एम्बाप्पे = बूट (Most Goals)।', 'Messi = Ball, Mbappe = Boot.', 'गोल्डन बॉल (प्लेयर) और गोल्डन बूट (गोल स्कोरर) में हमेशा भ्रम पैदा किया जाता है।', 'Golden Ball (Player) and Golden Boot (Goal Scorer) are always confused.', 'medium', 0.85, 0.95, '[{"questionId":"Fh1RKaFLGnbaPlOUAZr6X"}]', '["Sports Events","Football"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829434, 1773829434);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('10432b4e-93c3-4ecb-886c-ca2636900729', '3ac7f321-0f6f-45fe-8473-0433c9730846', 'Current Affairs', 'अप्रैल 2023 में भारतीय थल सेनाध्यक्ष ''जनरल मनोज पांडे'' थे (कोर ऑफ इंजीनियर्स से पहले)।', 'In April 2023, the Chief of Army Staff was ''General Manoj Pande'' (first from Corps of Engineers).', 'मनोज पांडे = सेना के इंजीनियर चीफ।', 'Manoj Pande = Engineer Chief of Army.', 'रक्षा प्रमुखों (सेना, नौसेना, वायुसेना) के नाम परीक्षा के महीने के अनुसार अपडेट रखें।', 'Keep the names of Defense Chiefs (Army, Navy, Airforce) updated according to the exam month.', 'medium', 0.8, 0.88, '[{"questionId":"FY389BNtYsvQ-TGQxAYJZ"}]', '["Appointments","Defence"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829435, 1773829435);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0aaa0895-476e-4f93-b65a-b5b8b805f4f1', '3ac7f321-0f6f-45fe-8473-0433c9730846', 'Current Affairs', 'AFINDEX 2023 (अफ्रीका-भारत फील्ड प्रशिक्षण अभ्यास) का दूसरा संस्करण पुणे (महाराष्ट्र) में हुआ। भारतीय सेना ने 2021 में महू (Mhow, MP) में क्वांटम प्रयोगशाला स्थापित की।', 'The 2nd edition of AFINDEX 2023 (Africa-India Field Training Exercise) was held in Pune (Maharashtra). Indian Army established a Quantum Lab in Mhow (MP) in 2021.', 'AFINDEX पुणे में। क्वांटम महू (MP) में।', 'AFINDEX in Pune. Quantum in Mhow (MP).', 'चूंकि महू मध्य प्रदेश में है, इसलिए सैन्य/रक्षा संस्थानों का राज्य-विशिष्ट करंट अफेयर्स बहुत महत्वपूर्ण है।', 'Since Mhow is in MP, state-specific current affairs regarding military/defense institutes is highly important.', 'medium', 0.85, 0.92, '[{"questionId":"7UvyeUfLOAhEyD76ZVq76"},{"questionId":"WgayhFaUqgY9MVQ25Dv0J"}]', '["Military Exercises","Defence Tech"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829435, 1773829435);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('522bc505-8cc5-4734-b1de-bdc9d81a9015', '3ac7f321-0f6f-45fe-8473-0433c9730846', 'Current Affairs', 'खेल कप मिलान: शीश महल (क्रिकेट), यादविंद्र (हॉकी), रोवर्स कप (फुटबॉल)। रंगास्वामी कप हॉकी से है, पोलो से नहीं।', 'Sports Cup Match: Sheesh Mahal (Cricket), Yadavindra (Hockey), Rovers Cup (Football). Rangaswami Cup is Hockey, not Polo.', 'रंगास्वामी की हॉकी (Rangaswami''s Hockey)।', 'Rangaswami''s Hockey.', 'घरेलू टूर्नामेंट (Domestic tournaments) और उनके संबंधित खेलों का मिलान एक क्लासिक MPPSC प्रश्न है।', 'Matching domestic tournaments with their respective sports is a classic MPPSC question.', 'medium', 0.8, 0.85, '[{"questionId":"ieChuvta04cRvD-Hb-Eyw"}]', '["Sports Trophies"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829435, 1773829435);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('2ac68017-a14a-49c8-82c6-71e7e1f26108', 'e6d7b2fb-759e-4714-9383-7d805a23b211', 'Geography', 'नाइन्टी ईस्ट रिज (90°E Ridge) हिन्द महासागर (Indian Ocean) में स्थित एक जलमग्न पर्वत श्रंखला है।', 'The Ninety East Ridge (90°E Ridge) is a submarine mountain chain located in the Indian Ocean.', 'भारत हिन्द महासागर में है और 90° पूर्वी देशांतर (East Longitude) के करीब है।', 'India is in the Indian Ocean and close to the 90° East Longitude.', 'इसे ''मिड-अटलांटिक रिज'' (Mid-Atlantic Ridge) से भ्रमित न करें, जो अटलांटिक महासागर में है।', 'Do not confuse it with the ''Mid-Atlantic Ridge'', which is in the Atlantic Ocean.', 'medium', 0.8, 0.88, '[{"questionId":"1x0bBWbMizRYZGIHoj2BH"}]', '["Oceanography","Indian Ocean"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829435, 1773829435);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('283e8bf6-e39a-4264-a31c-1e80d4232668', 'e6d7b2fb-759e-4714-9383-7d805a23b211', 'Geography', 'एटलस पर्वत (Atlas Mountains) उत्तरी अफ्रीका महाद्वीप (मोरक्को, अल्जीरिया) में स्थित है।', 'The Atlas Mountains are located in the North African continent (Morocco, Algeria).', 'एटलस (Atlas) = अफ़्रीका (Africa)।', 'A for Atlas, A for Africa.', 'यह एक वलित पर्वत (Fold Mountain) है, जैसे हिमालय या आल्प्स। इसे यूरोप में न मानें।', 'It is a Fold Mountain, like the Himalayas or Alps. Do not place it in Europe.', 'medium', 0.85, 0.9, '[{"questionId":"sfonJNNuzG3_yffTe_m-T"}]', '["World Mountains","Continents"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829435, 1773829435);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0a527847-1c11-41bc-a27a-2d4a87701281', 'e6d7b2fb-759e-4714-9383-7d805a23b211', 'Geography', 'मीकांग (Mekong) नदी दक्षिण-पूर्व एशिया (चीन, म्यांमार, लाओस, थाईलैंड, कंबोडिया, वियतनाम) में बहती है, लेकिन बांग्लादेश में नहीं।', 'The Mekong river flows through Southeast Asia (China, Myanmar, Laos, Thailand, Cambodia, Vietnam), but NOT in Bangladesh.', 'मीकांग = वियतनाम/थाईलैंड की जीवनरेखा (Lifeline of Vietnam/Thailand)।', 'Mekong = Lifeline of Vietnam/Thailand.', 'बांग्लादेश में गंगा (पद्मा) और ब्रह्मपुत्र (जमुना) बहती हैं। मीकांग बहुत पूर्व में है।', 'Ganga (Padma) and Brahmaputra (Jamuna) flow in Bangladesh. Mekong is far to the east.', 'medium', 0.9, 0.92, '[{"questionId":"nbzzlkqw5w47CEx6DXWDJ"}]', '["World Rivers","Southeast Asia"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829435, 1773829435);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a8530020-aaf2-4532-82f2-6d73021e9242', 'e6d7b2fb-759e-4714-9383-7d805a23b211', 'Geography', 'एशिया में लाओस, नेपाल, और भूटान ''स्थलरुद्ध'' (Landlocked) देश हैं। थाईलैंड स्थलरुद्ध नहीं है (इसकी समुद्री सीमा है)।', 'In Asia, Laos, Nepal, and Bhutan are ''Landlocked'' countries. Thailand is NOT landlocked (it has a coastline).', 'लाओस ''लॉक'' है (Laos is Locked)।', 'L for Laos, L for Locked.', 'दक्षिण-पूर्व एशिया (ASEAN क्षेत्र) में लाओस एकमात्र लैंडलॉक देश है। कजाकिस्तान दुनिया का सबसे बड़ा लैंडलॉक देश है।', 'Laos is the only landlocked country in Southeast Asia (ASEAN region). Kazakhstan is the world''s largest landlocked country.', 'medium', 0.92, 0.95, '[{"questionId":"WdcnZhtGYJcLqsSWm0eEj"}]', '["Political Geography","Landlocked Countries"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829435, 1773829435);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d20add78-d08c-4d67-b9b5-8054edfa3f33', 'c5b09d49-5e6f-4f85-a6f1-86e9d6534916', 'MP GK', 'प्रथम सीएम: पं. रविशंकर शुक्ल (1956)। प्रथम विधानसभा अध्यक्ष: पं. कुंजीलाल दुबे। प्रथम महिला राज्यपाल: सुश्री सरला ग्रेवाल। प्रथम गैर-कांग्रेसी सीएम: कैलाश जोशी (1977)।', 'First CM: Pt. Ravishankar Shukla (1956). First Speaker: Pt. Kunjilal Dubey. First Woman Governor: Ms. Sarla Grewal. First Non-Congress CM: Kailash Joshi (1977).', 'शुक्ल-CM, कुंजी-विधानसभा, सरला-राज्यपाल।', 'Shukla-CM, Kunji-Speaker, Sarla-Gov.', '''प्रथम'' व्यक्तियों की सूची रट लें। उमा भारती पहली ''महिला'' सीएम थीं, सरला ग्रेवाल ''राज्यपाल'' थीं।', 'Rote learn the list of ''First'' persons. Uma Bharti was the first ''Woman'' CM, Sarla Grewal was ''Governor''.', 'medium', 0.95, 0.98, '[{"questionId":"1sbxzWE3VyBblSWBb4kJO"},{"questionId":"Vj4CDx42dp-OF_2TrU7c9"},{"questionId":"N6TYHX8yjvi8lFn5X6cKN"},{"questionId":"9StNTS8iN1u-qu2Dk1HT-"}]', '["First in MP","MP Polity"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829437, 1773829437);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('41fd5906-87cf-4195-b894-576796a518ab', 'c5b09d49-5e6f-4f85-a6f1-86e9d6534916', 'MP GK', 'म.प्र. में तीन बार राष्ट्रपति शासन लगा है: 1977, 1980, और 1992।', 'President''s Rule has been imposed three times in MP: 1977, 1980, and 1992.', '77, 80, 92। (अंतिम दो बार सुंदरलाल पटवा सीएम थे)।', '77, 80, 92. (Sunderlal Patwa was CM during the last two).', '1992 में बाबरी मस्जिद विध्वंस के कारण शासन लगा था। इन तीनों वर्षों के राज्यपालों के नाम (S.N. Sinha, C.M. Poonacha, Kunwar Mehmood Ali) भी पूछे जाते हैं।', 'In 1992, rule was imposed due to Babri Masjid demolition. The names of Governors during these three years are also asked.', 'medium', 0.9, 0.95, '[{"questionId":"OidFU3HUDgnux3cpLcYaY"}]', '["President''s Rule","Emergency"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829437, 1773829437);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e7e62530-ae53-4736-be50-9695f8c2b71c', 'c5b09d49-5e6f-4f85-a6f1-86e9d6534916', 'MP GK', 'म.प्र. पंचायती राज अधिनियम 30 दिसंबर 1993 को पारित हुआ। राज्य निर्वाचन आयोग का गठन 1 फरवरी 1994 को हुआ। एक ग्राम पंचायत के लिए न्यूनतम जनसंख्या 1000 है।', 'MP Panchayati Raj Act was passed on Dec 30, 1993. State Election Commission was formed on Feb 1, 1994. Minimum population for a Gram Panchayat is 1000.', '73वें संशोधन (1993) के तुरंत बाद MP पहला राज्य (1994) बना। 1 गांव = 1000 लोग।', 'Right after 73rd Amendment (1993), MP was first state (1994). 1 Village = 1000 people.', 'यदि एक गाँव की जनसंख्या 1000 से कम है, तो दो या अधिक गाँवों को मिलाकर एक ग्राम पंचायत बनाई जाती है।', 'If a village''s population is less than 1000, two or more villages are combined to form one Gram Panchayat.', 'medium', 0.92, 0.94, '[{"questionId":"xW4GN5W6Dn-LiH5DEhF63"},{"questionId":"zheHTaZ2zRjRzbxTC1Omo"},{"questionId":"uXYdaSvsBYLzRQbh3r5tT"}]', '["Local Self Government","Institutions"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829437, 1773829437);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b18c371d-35d0-4ed3-825f-932317b9de3a', 'c5b09d49-5e6f-4f85-a6f1-86e9d6534916', 'MP GK', 'वर्तमान में म.प्र. में 16 नगर निगम हैं। म.प्र. विधानसभा भवन का नाम ''इंदिरा गाँधी विधान भवन'' (1996) है।', 'Currently, there are 16 Municipal Corporations in MP. The name of the MP Legislative Assembly building is ''Indira Gandhi Vidhan Bhavan'' (1996).', '16 बड़े शहर = 16 निगम। नया भवन = इंदिरा गाँधी।', '16 big cities = 16 Nigams. New building = Indira Gandhi.', 'पुराना विधानसभा भवन ''मिंटो हॉल'' था। वल्लभ भवन राज्य ''सचिवालय'' (Secretariat) है।', 'The old assembly building was ''Minto Hall''. Vallabh Bhavan is the State ''Secretariat''.', 'medium', 0.85, 0.88, '[{"questionId":"q7T9RnDDGUPnsNtE4_aYV"},{"questionId":"yEFaTsQGYeW0cD9iVTKPS"}]', '["Urban Bodies","State Buildings"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829437, 1773829437);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('704b783e-b1fe-4435-b459-9271fc00c302', 'c5b09d49-5e6f-4f85-a6f1-86e9d6534916', 'MP GK', 'लाडली बहना योजना 2023 में शुरू हुई, जिसमें महिलाओं को प्रति माह वित्तीय सहायता (आरंभ में ₹1000) दी जाती है।', 'Ladli Behna Yojana started in 2023, providing monthly financial assistance (initially ₹1000) to women.', 'बहना को हर महीने पैसे (Money to sister every month)।', 'Money to sister every month.', 'यह राशि बाद में बढ़ाकर ₹1250 कर दी गई थी, लेकिन योजना की घोषणा और शुरुआत (PYQ के समय) ₹1000 से हुई थी।', 'The amount was later increased to ₹1250, but the scheme was announced and started (during PYQ time) with ₹1000.', 'medium', 0.95, 0.95, '[{"questionId":"T3SOd6a2zeLh6OOb-DKOX"}]', '["Government Schemes","Women Empowerment"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829437, 1773829437);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4bb92d95-1f96-44bc-a84a-d6d7c6c7444e', '5710d4f3-fb60-4dfe-82c2-a1f58d93f69d', 'MP GK', 'स्वतंत्रता सेनानी: सादत खान (इंदौर/महू 1857), टंट्या भील (तांतिया - रॉबिन हुड), बादल भोई (गोंड - छिंदवाड़ा), तात्या टोपे (समाधि शिवपुरी)।', 'Freedom Fighters: Saadat Khan (Indore/Mhow 1857), Tantia Bhil (Tantia - Robin Hood), Badal Bhoi (Gond - Chhindwara), Tatya Tope (Tomb in Shivpuri).', 'इंदौर में सादत (Saadat in Indore)। शिवपुरी में तात्या (Tatya in Shivpuri)। छिंदवाड़ा के बादल (Clouds of Chhindwara)।', 'Saadat in Indore. Tatya in Shivpuri. Clouds of Chhindwara.', 'विद्रोहियों के भौगोलिक क्षेत्र (Regions) को मिलाना सबसे अहम है (जैसे रघुनाथ सिंह मण्डलोई - निमाड़)।', 'Matching the geographical regions of the rebels is paramount (e.g., Raghunath Singh Mandloi - Nimar).', 'medium', 0.95, 0.98, '[{"questionId":"kd6dpahRP2G9zASzGx8Q5"},{"questionId":"3CGmRcDfFQRdGx8xlytDN"},{"questionId":"crbUhcjbA9luJxIHDnKad"},{"questionId":"X4UzvTFV7SW033nH9GkhA"}]', '["Freedom Struggle","1857 Revolt","Tribal Heroes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829439, 1773829439);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('541859da-8a39-46f5-8db1-78684c988819', '5710d4f3-fb60-4dfe-82c2-a1f58d93f69d', 'MP GK', 'ऐतिहासिक नाम: विदिशा = भेलसा। चित्रकूट = ब्रह्मपुरी। धर्म राजेश्वर गुफा मंदिर = मंदसौर (दशपुर)।', 'Historical names: Vidisha = Bhilsa. Chitrakoot = Brahmapuri. Dharmarajeshwar Cave Temple = Mandsaur (Dashpur).', 'भेलसा-विदिशा, ब्रह्म-चित्रकूट, धर्म-मंदसौर।', 'Bhilsa-Vidisha, Brahma-Chitrakoot, Dharma-Mandsaur.', 'सांची का प्राचीन नाम काकनाद (Kakanad) था, विदिशा का भेलसा। इन्हें न मिलाएं।', 'Sanchi''s ancient name was Kakanad, Vidisha''s was Bhilsa. Don''t mix them up.', 'medium', 0.88, 0.94, '[{"questionId":"Dg5p_iWNYEoSh4oMoLsUY"},{"questionId":"epOoijILBj4ersQ1uST2z"},{"questionId":"s1sNnGHZX_Vxt8Z0xX3V5"}]', '["Ancient History","Historical Sites"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829439, 1773829439);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c604ebae-b286-4792-abac-d5737fa68b6c', '5710d4f3-fb60-4dfe-82c2-a1f58d93f69d', 'MP GK', 'साहित्य: अल-बरूनी की ''तहकीक-ए-हिन्द'' (गांगेयदेव-त्रिपुरी का जिक्र), सुभद्रा कुमारी चौहान (''मुकुल''), बालकृष्ण शर्मा ''नवीन'' (''प्रणार्पण'')।', 'Literature: Al-Biruni''s ''Tahqiq-i-Hind'' (mentions Gangeyadeva-Tripuri), Subhadra Kumari Chauhan (''Mukul''), Balkrishna Sharma ''Naveen'' (''Pranarpan'').', 'मुकुल की सुभद्रा (Subhadra''s Mukul)। नवीन का समर्पण (Naveen''s Dedication)।', 'Subhadra''s Mukul. Naveen''s Dedication.', 'साहित्यकारों की रचनाओं के साथ उनके जन्म-स्थान (जैसे नवीन जी-शाजापुर) भी पूछे जाते हैं।', 'Along with literary works, the birthplaces of authors (like Naveen ji-Shajapur) are also asked.', 'medium', 0.85, 0.9, '[{"questionId":"DSf14mCzz4xUiEzUaIcj8"},{"questionId":"01I-toEPFMZv6E3ulpZWV"},{"questionId":"9fuS1JV38ZA48Ksw1Mi2h"}]', '["Literature","Medieval History"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829440, 1773829440);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('dcfa529e-ea9a-4f0d-b829-9f854948cd01', '5710d4f3-fb60-4dfe-82c2-a1f58d93f69d', 'MP GK', 'कला एवं संस्कृति: ढोकरा कला एक ''धातु शिल्प'' है। गोंड महिलाएँ दीवार पर ''नोहडोरा'' बनाती हैं। ओम प्रकाश शर्मा ''माच'' (मालवा) से जुड़े हैं।', 'Art & Culture: Dhokra art is a ''Metal Craft''. Gond women create ''Nohdora'' on walls. Om Prakash Sharma is associated with ''Maach'' (Malwa).', 'ढोकरा = धातु (Dhokra=Metal)। नोहडोरा = गोंड दीवार (Nohdora=Gond Wall)। माच = मालवा (Maach=Malwa)।', 'Dhokra=Metal. Nohdora=Gond Wall. Maach=Malwa.', 'ढोकरा को कपड़ा कला न समझें। ''माच'' मालवा का लोकनाट्य है, जबकि ''गम्मत'' निमाड़ का।', 'Do not mistake Dhokra for textile art. ''Maach'' is Malwa''s folk drama, while ''Gammat'' is Nimar''s.', 'medium', 0.9, 0.95, '[{"questionId":"ad4y3tsoOXtpZtpiPDF1A"},{"questionId":"6WoGeH5tcBsO2lo5tSyjv"},{"questionId":"kX1cZ836eD501EUg9hVhO"}]', '["Folk Art","Tribal Culture"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829440, 1773829440);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('cba5269c-bcbe-450c-be8b-acf97993807f', 'f68b0869-c246-42a8-bb70-7645198da977', 'Polity', 'अनुच्छेद 61: राष्ट्रपति पर महाभियोग। अनुच्छेद 72: राष्ट्रपति की क्षमादान शक्ति। अनुच्छेद 222: HC न्यायाधीशों का स्थानांतरण। अनुच्छेद 315: संघ/राज्य लोक सेवा आयोग। अनुच्छेद 338: SC आयोग।', 'Article 61: President''s Impeachment. Article 72: President''s Pardoning power. Article 222: Transfer of HC judges. Article 315: UPSC/SPSC. Article 338: SC Commission.', '61=हटाना (Remove), 72=क्षमा (Pardon), 222=ट्रांसफर (Transfer)।', '61=Remove, 72=Pardon, 222=Transfer.', 'राष्ट्रपति की क्षमादान (Art 72) और राज्यपाल की क्षमादान (Art 161) शक्तियों में अंतर होता है (राज्यपाल मृत्युदंड माफ नहीं कर सकता)।', 'There is a difference between President''s pardoning (Art 72) and Governor''s pardoning (Art 161) powers (Governor cannot pardon death sentence).', 'medium', 0.95, 0.98, '[{"questionId":"9S01W0fCyLDvsDeCD1wUR"},{"questionId":"5EW8dubRR-jBC02XDnoWP"},{"questionId":"Iu90jjhPI6i4OYQP0AscA"},{"questionId":"gzr2eWAUgClckUd7Vfrz6"},{"questionId":"PIBntn8ohoQollq_cJbJ6"}]', '["Important Articles","President","Judiciary"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829441, 1773829441);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4ad653c8-8dcd-48a2-a5b1-d7524fcdd50c', 'f68b0869-c246-42a8-bb70-7645198da977', 'Polity', 'CAG के वेतन/भत्ते संविधान की ''दूसरी अनुसूची'' (Second Schedule) में वर्णित हैं। 91वें संशोधन (2003) ने मंत्रिपरिषद का आकार अधिकतम 15% तय किया।', 'Salaries/allowances of CAG are detailed in the ''Second Schedule'' of the Constitution. The 91st Amendment (2003) capped the Council of Ministers size at max 15%.', 'दूसरी अनुसूची = पैसा (Salary in 2nd)। 91वां संशोधन = 15% सीमा (15% Limit)।', 'Salary in 2nd. 91st Amendment = 15% Limit.', 'पहली अनुसूची राज्य/UTs के लिए है, दूसरी वेतन के लिए, तीसरी शपथ (Oath) के लिए।', 'First Schedule is for States/UTs, Second for Salaries, Third for Oaths.', 'medium', 0.9, 0.94, '[{"questionId":"oRa65_a-79emM2Y0f4XYG"},{"questionId":"jn72AW5Jnc4Lp9DbDqjeX"}]', '["Schedules","Constitutional Amendments"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829441, 1773829441);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('77837b86-f217-4051-8823-c71083113760', 'f68b0869-c246-42a8-bb70-7645198da977', 'Polity', 'जवाहरलाल नेहरू ने 13 दिसंबर 1946 को ''उद्देश्य प्रस्ताव'' पेश किया था। जी.वी. मावलंकर लोकसभा के प्रथम अध्यक्ष थे। नीति आयोग के उपाध्यक्ष की नियुक्ति ''प्रधानमंत्री'' करते हैं।', 'Jawaharlal Nehru moved the ''Objectives Resolution'' on Dec 13, 1946. G.V. Mavalankar was the first Speaker of Lok Sabha. ''Prime Minister'' appoints the Vice-Chairman of NITI Aayog.', 'नेहरू का 13 दिसंबर का प्रस्ताव (Nehru''s Dec 13 Resolution)। मावलंकर = लोकसभा के जनक (Father of Lok Sabha)।', 'Nehru''s Dec 13 Resolution. Mavalankar = Father of Lok Sabha.', 'नीति आयोग के उपाध्यक्ष की नियुक्ति राष्ट्रपति नहीं करते, बल्कि अध्यक्ष (प्रधानमंत्री) करते हैं।', 'The Vice-Chairman of NITI Aayog is NOT appointed by the President, but by the Chairman (Prime Minister).', 'medium', 0.85, 0.9, '[{"questionId":"Qb68nQcUNayKCppz1gz-0"},{"questionId":"oLbJLLw6rwWZeVpFytcIQ"},{"questionId":"wMrV7BUDLPYz7WsTS_cuX"}]', '["Constituent Assembly","Parliament","NITI Aayog"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829442, 1773829442);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b6c54ef6-4d70-49e6-9ae8-d53d5d46cd7f', 'f68b0869-c246-42a8-bb70-7645198da977', 'Polity', 'आयोग: केंद्रीय सतर्कता आयोग (CVC) - संथानम समिति (1964)। राज्य मानवाधिकार आयोग (SHRC) की चयन समिति का अध्यक्ष ''मुख्यमंत्री'' होता है। सूचना आयुक्त सांसद/विधायक नहीं हो सकता।', 'Commissions: Central Vigilance Commission (CVC) - Santhanam Committee (1964). The selection committee for SHRC is chaired by the ''Chief Minister''. Information Commissioner cannot be an MP/MLA.', 'भ्रष्टाचार रोको = संथानम (Anti-corruption = Santhanam)। राज्य के आयोगों में CM की चलती है (CM leads state committees)।', 'Anti-corruption = Santhanam. CM leads state committees.', 'राष्ट्रीय मानवाधिकार आयोग (NHRC) की चयन समिति का अध्यक्ष प्रधानमंत्री होता है, राज्य (SHRC) में मुख्यमंत्री होता है।', 'The PM chairs the selection committee for NHRC, while the CM chairs it for the state (SHRC).', 'medium', 0.92, 0.96, '[{"questionId":"ENwaCKE-aimVYIQQRQMar"},{"questionId":"yrGpB8RmfvhoNApOWrq-O"},{"questionId":"_jcqw8PlsGifRsqHQEzAz"}]', '["Statutory Commissions","Committees"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829442, 1773829442);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c7b1f01c-fc94-48a8-a15d-eaf92c802bfe', 'fcd1fec7-b8de-4eac-9bac-4de9a4dcdcf3', 'History', 'कांग्रेस अधिवेशन: 1885 बम्बई (पहला), 1907 सूरत (विभाजन/नरम-गरम दल), 1929 लाहौर (पूर्ण स्वराज - नेहरू)।', 'Congress Sessions: 1885 Bombay (First), 1907 Surat (Split/Moderates-Extremists), 1929 Lahore (Purna Swaraj - Nehru).', '85 में शुरू, 07 में सूरत बिगड़ी (Split), 29 में पूर्ण आजादी (Purna Swaraj)।', 'Started in 85, Surat Split in 07, Purna Swaraj in 29.', 'पहला अधिवेशन पुणे में प्रस्तावित था, लेकिन बम्बई में हुआ (प्लेग के कारण)।', 'The first session was proposed in Pune, but held in Bombay (due to plague).', 'medium', 0.95, 0.98, '[{"questionId":"ZFOBdj2NuvNqowmE11LuA"},{"questionId":"e0I6qvdtwKjafLHezZFU5"},{"questionId":"jw6_ocJn2KnsG4y0MIx7W"}]', '["INC Sessions","Freedom Movement"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829443, 1773829443);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9f4606ac-7b13-4345-832d-3df9b3469654', 'fcd1fec7-b8de-4eac-9bac-4de9a4dcdcf3', 'History', 'आंदोलन की तिथियां: चंपारण (1917 - तिनकठिया नील), जलियांवाला बाग (13 अप्रैल 1919), दांडी मार्च (12 मार्च 1930), भारत छोड़ो (9 अगस्त 1942)।', 'Movement Dates: Champaran (1917 - Tinkathia Indigo), Jallianwala Bagh (April 13, 1919), Dandi March (March 12, 1930), Quit India (August 9, 1942).', 'चंपारण से शुरुआत (Start at Champaran)। 30 में नमक (Salt in 30), 42 में भारत छोड़ो (Quit in 42)।', 'Start at Champaran. Salt in 30, Quit in 42.', 'सविनय अवज्ञा आंदोलन 6 अप्रैल 1930 (दांडी पहुंचने पर) शुरू हुआ था, जबकि यात्रा 12 मार्च को शुरू हुई थी।', 'Civil Disobedience started on April 6, 1930 (upon reaching Dandi), while the march started on March 12.', 'medium', 0.92, 0.96, '[{"questionId":"exfVtGTUSMogdkkXRa_6e"},{"questionId":"SvFzsXbUqUuizYlkUZexf"},{"questionId":"chi_rkVjQTXVqSU3d_AhO"},{"questionId":"Y8u2elQEPjv_mvttenJb0"}]', '["Gandhian Movements","Chronology"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829443, 1773829443);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('2504c27b-ef73-4a64-b422-0f19e909f49d', 'fcd1fec7-b8de-4eac-9bac-4de9a4dcdcf3', 'History', 'महत्वपूर्ण कथन/तथ्य: ''स्वराज मेरा जन्मसिद्ध अधिकार है...'' (तिलक)। भारत में ''स्थानीय स्वशासन'' के जनक लॉर्ड रिपन (1882) थे। 1919 के अधिनियम ने ''प्रांतों'' में ''द्वैध शासन'' (Dyarchy) लागू किया।', 'Key Statements/Facts: ''Swaraj is my birthright...'' (Tilak). Father of ''Local Self-Government'' in India was Lord Ripon (1882). Act of 1919 introduced ''Dyarchy'' in ''Provinces''.', 'तिलक का स्वराज (Tilak''s Swaraj)। रिपन का स्वशासन (Ripon''s Self-gov)। 1919 = प्रांत में द्वैध (Province Dyarchy)।', 'Tilak''s Swaraj. Ripon''s Self-gov. 1919 = Province Dyarchy.', '1935 के अधिनियम ने प्रांतों में द्वैध शासन समाप्त कर केंद्र में लागू किया। यह एक क्लासिक ट्रैप है।', 'The Act of 1935 abolished dyarchy in provinces and applied it at the center. This is a classic trap.', 'medium', 0.9, 0.95, '[{"questionId":"d2aovUiATKFcOBRhCUb5D"},{"questionId":"N_3jMSCCCc_aOsIGogp-V"},{"questionId":"F7_jJJoVs_kP4iUqTgZFM"}]', '["Modern History Quotes","British Acts","Viceroys"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829443, 1773829443);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('23daf10b-2be7-41cc-8324-1abd7bbf4040', '444338ab-d7c4-45fc-953d-34fe7f2110cd', 'Science', 'इसरो का सूर्य मिशन ''आदित्य-L1'' (Aditya-L1) है, जो सूर्य-पृथ्वी लैग्रेंज बिंदु 1 (L1) पर स्थित है। भारत का पहला मंगल मिशन ''मंगलयान'' (MOM) 2013 में लॉन्च हुआ था।', 'ISRO''s solar mission is ''Aditya-L1'', positioned at the Sun-Earth Lagrange point 1 (L1). India''s first Mars mission ''Mangalyaan'' (MOM) was launched in 2013.', 'सूर्य के लिए आदित्य (Aditya for Sun)। मंगल पर 2013 में (Mars in 2013)।', 'Aditya for Sun. Mars in 2013.', 'आदित्य-L1 सूर्य पर नहीं उतरेगा, यह दूर से अध्ययन करेगा। ''L1'' का मतलब लैग्रेंज पॉइंट 1 है।', 'Aditya-L1 will not land on the Sun; it will study it from afar. ''L1'' stands for Lagrange Point 1.', 'medium', 0.95, 0.98, '[{"questionId":"jQaJJF1dlbPLcarH-tRql"}]', '["ISRO Missions","Space Tech"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829444, 1773829444);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6f0a5a4d-fab3-4472-8c6b-4de61a549ed0', '444338ab-d7c4-45fc-953d-34fe7f2110cd', 'Science', 'बी.टी. बैंगन (Bt Brinjal) को ''कीट प्रतिरोध'' (Insect Resistance) के लिए जेनेटिक रूप से मॉडिफाई किया गया है (विशेषकर शूट बोरर कीड़े के खिलाफ)।', 'Bt Brinjal is genetically modified for ''Insect Resistance'' (especially against the shoot borer insect).', 'Bt = Bacillus thuringiensis (कीड़े मारने वाला बैक्टीरिया)।', 'Bt = Bacillus thuringiensis (insect-killing bacteria).', 'भारत में व्यावसायिक खेती के लिए केवल ''Bt कपास'' (Bt Cotton) को मंजूरी मिली है। Bt बैंगन को मंजूरी नहीं मिली है।', 'Only ''Bt Cotton'' is approved for commercial cultivation in India. Bt Brinjal is NOT approved.', 'medium', 0.85, 0.9, '[{"questionId":"U9HZpF_rcgUEhayKcFaDk"}]', '["Biotechnology","Agriculture"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829444, 1773829444);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b8893c48-6d7e-4d97-a886-e478dcb97143', 'e7ad88fa-7307-42a8-8250-f2044cf4fb7b', 'Polity', 'RTI अधिनियम की धारा 20 के तहत, सूचना न देने पर केंद्रीय सूचना आयोग (CIC) और राज्य सूचना आयोग (SIC) दोनों जुर्माना (अधिकतम ₹25,000) लगा सकते हैं।', 'Under Section 20 of the RTI Act, both CIC and SIC can impose penalties (max ₹25,000) for non-disclosure of information.', 'सूचना के ''बॉस'' (CIC/SIC) ही जुर्माना लगा सकते हैं।', 'Only the ''Bosses'' of Information (CIC/SIC) can impose fines.', 'जुर्माना लगाने का अधिकार ''प्रथम अपीलीय प्राधिकारी'' (First Appellate Authority) को नहीं होता, केवल आयोग (CIC/SIC) को होता है।', 'The ''First Appellate Authority'' does NOT have the power to impose fines, only the Commission (CIC/SIC) does.', 'medium', 0.85, 0.95, '[{"questionId":"Kf4G72GYVN3yVzyHNfTtb"}]', '["RTI Act","Statutory Bodies"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829450, 1773829450);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('63d18f1b-4b86-4a26-af36-192d2c009fe3', 'e7ad88fa-7307-42a8-8250-f2044cf4fb7b', 'Polity', 'राज्य मानवाधिकार आयोग (SHRC) के अध्यक्ष एवं सदस्यों की नियुक्ति की सिफारिश करने वाली समिति में मुख्यमंत्री (अध्यक्ष), गृह मंत्री, विधानसभा अध्यक्ष और नेता प्रतिपक्ष शामिल होते हैं।', 'The committee recommending the appointment of the Chairperson and members of SHRC includes the Chief Minister (Head), Home Minister, Speaker of the Legislative Assembly, and Leader of the Opposition.', 'राज्य के सभी ''मुख्य'' नेता (CM, Home, Speaker, Opposition) समिति में होते हैं।', 'All ''Chief'' leaders of the state (CM, Home, Speaker, Opposition) are in the committee.', 'इस समिति में ''राज्यपाल'' या ''मुख्य न्यायाधीश'' शामिल नहीं होते हैं (राज्यपाल केवल नियुक्ति करता है)।', 'The ''Governor'' or ''Chief Justice'' are NOT included in this committee (The Governor only appoints).', 'medium', 0.9, 0.98, '[{"questionId":"7LJOfTWT33QuRx_80Alod"}]', '["Human Rights Commission","Committees"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829450, 1773829450);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('70bca609-0a59-452b-b4db-ddce77fd04fb', 'e7ad88fa-7307-42a8-8250-f2044cf4fb7b', 'Polity', 'विकास निगरानी और मूल्यांकन कार्यालय (DMEO) का गठन 18 सितम्बर 2015 को नीति आयोग (NITI Aayog) के एक संलग्न कार्यालय के रूप में किया गया था।', 'The Development Monitoring and Evaluation Office (DMEO) was formed on September 18, 2015, as an attached office of NITI Aayog.', '2015 (नीति आयोग का वर्ष) + सितंबर = DMEO।', '2015 (NITI Aayog''s year) + September = DMEO.', 'यह एक अत्यंत विशिष्ट (Micro) तथ्यात्मक प्रश्न है। DMEO सीधे नीति आयोग से जुड़ा है, वित्त मंत्रालय से नहीं।', 'This is a very specific (Micro) factual question. DMEO is directly attached to NITI Aayog, not the Finance Ministry.', 'medium', 0.75, 0.85, '[{"questionId":"DByG0KKcyNJfOcqDt2z0z"}]', '["NITI Aayog","Government Offices"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829450, 1773829450);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c3879028-4e5e-45d7-951c-f62e084dc3c1', 'd7bdedd3-0451-4937-a61a-1de3261eb890', 'Science', 'सर्टोली कोशिकाएं (Sertoli cells) पुरुष प्रजनन अंग ''वृषण'' (Testis) में पाई जाती हैं और शुक्राणुओं (Sperms) को पोषण प्रदान करती हैं।', 'Sertoli cells are found in the male reproductive organ ''Testis'' and provide nourishment to sperms.', 'सर्टोली = ''नर्स'' कोशिकाएं (शुक्राणु की देखभाल)।', 'Sertoli = ''Nurse'' cells (care for sperm).', 'इन्हें लीडिग कोशिकाओं (Leydig cells) से भ्रमित न करें, जो टेस्टोस्टेरोन हार्मोन बनाती हैं।', 'Do not confuse them with Leydig cells, which produce the testosterone hormone.', 'medium', 0.85, 0.9, '[{"questionId":"611Du_zXgaX6ixPNt00g3"}]', '["Human Reproduction","Cells"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829451, 1773829451);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('116c2940-83fc-4db5-8a08-2e64c234bd22', 'd7bdedd3-0451-4937-a61a-1de3261eb890', 'Science', 'हाइड्रोक्लोरिक एसिड (HCl) अमाशय (Stomach) की गैस्ट्रिक ग्रंथियों द्वारा स्रावित होता है जो पाचन (पेप्सिन को सक्रिय करने) में मदद करता है।', 'Hydrochloric Acid (HCl) is secreted by the gastric glands of the Stomach, which helps in digestion (activating pepsin).', 'पेट (Stomach) का तेज़ाब = HCl।', 'Stomach acid = HCl.', 'पित्त रस (Bile juice) यकृत (Liver) से निकलता है, अमाशय से नहीं।', 'Bile juice is secreted by the Liver, not the Stomach.', 'medium', 0.9, 0.95, '[{"questionId":"A7c7cBte89g9-RtjsA7yD"}]', '["Digestive System","Human Anatomy"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829451, 1773829451);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('959d6b52-a968-476b-99f4-6b3e1d1eb9a9', 'd7bdedd3-0451-4937-a61a-1de3261eb890', 'Science', 'स्कर्वी रोग विटामिन ''सी'' (एस्कॉर्बिक एसिड) की कमी से होता है (मसूड़ों में सूजन/खून)।', 'Scurvy disease is caused by the deficiency of Vitamin ''C'' (Ascorbic Acid) (swollen/bleeding gums).', 'C for C-curvy (Scurvy)।', 'C for C-curvy (Scurvy).', 'रिकेट्स विटामिन D की कमी से होता है, बेरीबेरी B1 की कमी से।', 'Rickets is caused by Vitamin D deficiency, Beri-beri by B1.', 'medium', 0.95, 0.98, '[{"questionId":"aZ_lCpW04Q8M7bJk2C23z"}]', '["Vitamins","Diseases"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829451, 1773829451);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('139841ac-b4e8-48bb-9dc2-ddd7660c04b0', '79b7a58d-f4d5-4a5a-9028-522071dca98a', 'Current Affairs', 'संयुक्त राष्ट्र ने 2023 को ''अंतर्राष्ट्रीय पोषक अनाज/बाजरा (Millets) वर्ष'' घोषित किया। मध्य प्रदेश ने पैंगोलिन के संरक्षण के लिए उसे रेडियो टैग (Radio-tag) किया।', 'The UN declared 2023 as the ''International Year of Millets''. Madhya Pradesh radio-tagged a Pangolin for its conservation.', '2023 = बाजरा (Millets) का साल। MP में पैंगोलिन को टैग।', '2023 = Year of Millets. Pangolin tagged in MP.', '2024 कैमेलिड (उष्ट्रगण) वर्ष है, 2023 बाजरा वर्ष है। दोनों में स्पष्ट अंतर रखें।', '2024 is Camelids year, 2023 is Millets year. Keep a clear distinction between the two.', 'medium', 0.9, 0.95, '[{"questionId":"UwXu5buEb1FyrkiYTe3e2"},{"questionId":"X4PJc88lISdUiXje-PWnT"}]', '["UN Declarations","Wildlife Conservation","MP Current Affairs"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829452, 1773829452);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('933c7aee-a3e1-4e5c-9247-f3e87f7ca911', '79b7a58d-f4d5-4a5a-9028-522071dca98a', 'Current Affairs', 'WHO की स्थापना 7 अप्रैल 1948 को हुई थी (विश्व स्वास्थ्य दिवस)। यूनिसेफ (UNICEF) का मुख्यालय न्यूयॉर्क (USA) में है।', 'WHO was founded on April 7, 1948 (World Health Day). UNICEF is headquartered in New York (USA).', '7-4-48 (WHO)। बच्चों का फंड (UNICEF) न्यूयॉर्क में।', '7-4-48 (WHO). Children''s fund (UNICEF) in New York.', 'WHO का मुख्यालय जिनेवा में है, लेकिन UNICEF का न्यूयॉर्क में है। यूनेस्को (UNESCO) पेरिस में है। मुख्यालयों के मिलान में बहुत गलती होती है।', 'WHO HQ is in Geneva, but UNICEF is in New York. UNESCO is in Paris. Matching HQs is a highly error-prone area.', 'medium', 0.95, 0.98, '[{"questionId":"8XwiE9t49VZApvZPpkocQ"},{"questionId":"ADx0ovyXJ9a5kfFHLQ0nW"}]', '["International Organizations","Headquarters"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829452, 1773829452);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d73605d9-6900-4e70-916c-b45c64e08c9f', '79b7a58d-f4d5-4a5a-9028-522071dca98a', 'Current Affairs', 'कटलिन नोवाक (Katalin Novak) हंगरी की पहली महिला राष्ट्रपति बनीं (मार्च 2022)।', 'Katalin Novak became the first female President of Hungary (March 2022).', 'नोवाक (Novak) हंगरी (Hungry) की राष्ट्रपति।', 'Novak President of Hungary (Hungry).', 'अंतर्राष्ट्रीय नियुक्तियों में ''पहली महिला'' (First Female) राष्ट्रपति/प्रधानमंत्री हमेशा उच्च प्राथमिकता वाले प्रश्न होते हैं।', 'In international appointments, ''First Female'' Presidents/PMs are always high-priority questions.', 'medium', 0.8, 0.88, '[{"questionId":"fOuzD2RMOZ3y8v46GbQzb"}]', '["International Appointments","Women in News"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829452, 1773829452);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('96652795-24d4-479f-8e96-a8c4ed6a3ff3', '79b7a58d-f4d5-4a5a-9028-522071dca98a', 'Current Affairs', 'मध्याह्न भोजन योजना (Mid Day Meal) 15 अगस्त 1995 को शुरू की गई थी (अब PM POSHAN)।', 'Mid Day Meal scheme was launched on August 15, 1995 (Now PM POSHAN).', 'मिड डे = मिड 90s (1995)।', 'Mid Day = Mid 90s (1995).', 'योजना का नया नाम (PM POSHAN) याद रखना आवश्यक है।', 'It is essential to remember the new name of the scheme (PM POSHAN).', 'medium', 0.85, 0.92, '[{"questionId":"3zIuJqaNoTQEo-tO1LZpi"}]', '["Government Schemes","Education"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829452, 1773829452);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3d9e47a9-eb45-4f00-b0e8-62f3c590db39', '88cc5784-9269-4484-a39b-c8f355130338', 'ICT', 'C2C (Consumer-to-Consumer) मॉडल में नीलामी (Auction) मुख्य रूप से होती है (जैसे eBay, OLX)। C2B (Consumer-to-Business) में उपभोक्ता अपनी कीमत/सेवा व्यवसाय को पेश करते हैं (जैसे फ्रीलांसिंग)।', 'Auctions are primarily seen in the C2C (Consumer-to-Consumer) model (e.g., eBay, OLX). In C2B (Consumer-to-Business), the consumer offers their price/service to the business (e.g., Freelancing).', 'नीलामी (Auction) = C2C। उपभोक्ता से कंपनी (Customer to Company) = C2B।', 'Auction = C2C. Customer to Company = C2B.', 'B2C (Amazon) और C2B (Freelancing) के बीच का अंतर याद रखें। B2C में कंपनी कीमत तय करती है, C2B में ग्राहक।', 'Remember the difference between B2C (Amazon) and C2B (Freelancing). In B2C, the company sets the price; in C2B, the customer does.', 'medium', 0.9, 0.94, '[{"questionId":"NETQCRxh1LA0H5mawZVe5"},{"questionId":"pDKI3Wsn4ZDHGRgXp6Pbz"}]', '["E-Commerce Models"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829453, 1773829453);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7c59e28e-dc44-445b-a398-7274f664a65d', '88cc5784-9269-4484-a39b-c8f355130338', 'ICT', 'ईमेल ''स्पूफिंग'' (Spoofing) में प्रेषक की पहचान छिपाई जाती है ताकि ईमेल विश्वसनीय स्रोत (जैसे बैंक) से आता हुआ लगे। वर्चुअल कीबोर्ड कीलॉगर्स (Keyloggers) से सुरक्षा करते हैं।', 'In email ''Spoofing'', the sender''s identity is hidden so the email appears to come from a trusted source (like a bank). Virtual keyboards protect against Keyloggers.', 'स्पूफ = भेष बदलना (Disguise)। वर्चुअल कीबोर्ड = स्क्रीन पर टाइपिंग (नो हार्डवेयर ट्रैकिंग)।', 'Spoof = Disguise. Virtual Keyboard = Typing on screen (No hardware tracking).', 'फिशिंग (Phishing) में जानकारी चुराई जाती है, स्पूफिंग (Spoofing) फिशिंग का ही एक तकनीकी तरीका है (ईमेल का पता बदलना)।', 'Phishing steals info; Spoofing is a technical method of Phishing (forging the email address).', 'medium', 0.92, 0.95, '[{"questionId":"Hcv_7FGGlbLQwH7bqq_Yn"},{"questionId":"477yzv9RQZ33D3Iq2uVVi"}]', '["Cyber Security","Malware"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829454, 1773829454);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c18dd85d-d3be-4f2d-9f02-cb32ec2627d0', '88cc5784-9269-4484-a39b-c8f355130338', 'ICT', 'बस, स्टार, और रिंग मानक नेटवर्क टोपोलॉजी (Topology) हैं। ''ग्रिड'' (Grid) एक कंप्यूटिंग शैली है, टोपोलॉजी नहीं। DNS (Domain Name System) इंटरनेट की फोनबुक है जो नामों को IP में बदलती है।', 'Bus, Star, and Ring are standard network topologies. ''Grid'' is a computing style, not a topology. DNS (Domain Name System) is the internet''s phonebook that translates names to IPs.', 'टोपोलॉजी = नेटवर्क का आकार (Shape)। DNS = नाम को नंबर (IP) बनाना।', 'Topology = Shape of network. DNS = Name to Number (IP).', 'मेश (Mesh) भी एक टोपोलॉजी है, ग्रिड (Grid) नहीं।', 'Mesh is also a topology, Grid is not.', 'medium', 0.85, 0.9, '[{"questionId":"uVh2eg7zNvcqtDpu-0I9b"},{"questionId":"P5OkPtm78A4FBTWLWKDVF"}]', '["Networking","Internet Protocols"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829454, 1773829454);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('b6fdc16e-aec4-4467-bdba-2930c0410f5e', '88cc5784-9269-4484-a39b-c8f355130338', 'ICT', 'प्लेटो के अनुसार, ज्ञान (Knowledge) की परिभाषा ''सच्चा न्यायोचित विश्वास'' (Justified True Belief) है (यह AI और दर्शनशास्त्र का मूल है)।', 'According to Plato, the definition of knowledge is ''Justified True Belief'' (core to AI and Philosophy).', 'ज्ञान = सच्चा + विश्वास + न्यायोचित (Knowledge = True + Belief + Justified)।', 'Knowledge = True + Belief + Justified.', 'यह प्रश्न ''आर्टिफिशियल इंटेलिजेंस'' (AI) में ज्ञान प्रतिनिधित्व (Knowledge Representation) की गहरी दार्शनिक जड़ों से था।', 'This question was from the deep philosophical roots of Knowledge Representation in Artificial Intelligence (AI).', 'medium', 0.7, 0.8, '[{"questionId":"wwSeyFdOIzm3XRXVWFRD1"}]', '["AI Basics","Philosophy of Tech"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829454, 1773829454);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('8a4f0716-633b-4a73-8a07-914a66d6cd20', '86a04662-101a-496e-a21a-ea34c8b13867', 'Geography', '2011 जनगणना: भारत की नगरीय जनसंख्या 31.15% थी (ग्रामीण 68.85%)। भारत और चीन (तिब्बत) के बीच ''मैकमोहन रेखा'' (McMahon Line) है।', '2011 Census: India''s urban population was 31.15% (rural 68.85%). The boundary between India and China (Tibet) is the ''McMahon Line''.', 'शहर में 31% लोग (31% Urban)। मैकमोहन = M-C (McMahon-China)।', '31% Urban. McMahon = M-C (McMahon-China).', 'रेडक्लिफ (Radcliffe) रेखा भारत-पाकिस्तान के बीच है, डूरंड (Durand) भारत-अफगानिस्तान/पाक-अफगानिस्तान के बीच। मैकमोहन केवल उत्तर-पूर्व में चीन के साथ है।', 'Radcliffe Line is between India-Pak, Durand between India-Afghan/Pak-Afghan. McMahon is only with China in the Northeast.', 'medium', 0.95, 0.98, '[{"questionId":"lGSExcnGKGJsvTgqGPJ45"},{"questionId":"75ret317R9sQSn3WJhv6u"}]', '["Census Data","International Boundaries"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829456, 1773829456);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4ae92bcb-4d8a-4b92-b048-000b15952cb6', '86a04662-101a-496e-a21a-ea34c8b13867', 'Geography', 'हिमालय, रॉकी (Rocky) और आल्प्स (Alps) नवीन वलित पर्वत (Young Fold Mountains) हैं। सियरा नेवादा एक ब्लॉक पर्वत है।', 'Himalayas, Rockies, and Alps are Young Fold Mountains. Sierra Nevada is a block mountain.', 'R-H-A (Rocky, Himalaya, Alps) = नवीन वलित (Young Fold)।', 'R-H-A (Rocky, Himalaya, Alps) = Young Fold.', 'अरावली (Aravalli) एक ''अवशिष्ट'' (Residual) या बहुत पुराना वलित पर्वत है, ''नवीन'' नहीं।', 'Aravalli is a ''Residual'' or very old fold mountain, NOT ''Young''.', 'medium', 0.9, 0.94, '[{"questionId":"mE52U3nF57P8NXyyZcVNL"}]', '["Geomorphology","Mountains"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829456, 1773829456);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('08ad4952-35a5-425b-8846-8da2daa35d17', '86a04662-101a-496e-a21a-ea34c8b13867', 'Geography', 'स्वेज़ नहर (Suez Canal) लाल सागर और भूमध्य सागर को जोड़ती है (व्यापारिक रूप से अति महत्वपूर्ण)। मारक्वेत श्रेणी (USA) लौह अयस्क के लिए प्रसिद्ध है।', 'Suez Canal connects the Red Sea and Mediterranean Sea (highly important commercially). Marquette Range (USA) is famous for Iron Ore.', 'Suez = Shortcut (लाल + भूमध्य)। मारक्वेत (Marquette) = लोहे का मार्केट (Iron Market)।', 'Suez = Shortcut (Red + Med). Marquette = Iron Market.', 'पनामा नहर प्रशांत और अटलांटिक को जोड़ती है। स्वेज नहर एशिया और यूरोप के बीच की दूरी कम करती है।', 'Panama canal connects Pacific and Atlantic. Suez canal reduces distance between Asia and Europe.', 'medium', 0.88, 0.92, '[{"questionId":"APAY-qCVX78k3OuSn0pPJ"},{"questionId":"zQFu4l3nyJOHRh_o9AMba"}]', '["World Geography","Canals","Minerals"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829456, 1773829456);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('85be26b9-9a0f-430c-8d8f-48657cb42091', '86a04662-101a-496e-a21a-ea34c8b13867', 'Geography', 'जीवाश्म ईंधन (कोयला, पेट्रोलियम) केवल अवसादी चट्टानों (Sedimentary Rocks) में पाए जाते हैं। सारगैसो सागर (Sargasso Sea) उत्तरी अटलांटिक में है (बिना तटरेखा वाला)।', 'Fossil fuels (Coal, Petroleum) are found ONLY in Sedimentary Rocks. Sargasso Sea is in the North Atlantic (without a coastline).', 'जीवाश्म = परतदार चट्टान (Sedimentary)। सारगैसो = अटलांटिक के बीच में घास (Weed in middle of Atlantic)।', 'Fossils = Layered rock (Sedimentary). Sargasso = Weed in middle of Atlantic.', 'आग्नेय (Igneous) या कायांतरित (Metamorphic) चट्टानों में कोयला/पेट्रोल कभी नहीं मिलता।', 'Coal/petroleum is NEVER found in Igneous or Metamorphic rocks.', 'medium', 0.92, 0.95, '[{"questionId":"xLnvgFBe64R0TkrN89MNt"},{"questionId":"esY96hda69_Vcu7sSyePv"}]', '["Geology","Oceans"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829456, 1773829456);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('fae5cde0-af55-4ae4-a5c2-3f41ae6afb6a', '86a04662-101a-496e-a21a-ea34c8b13867', 'Geography', 'इंदिरा गांधी नहर (राजस्थान) ने थार मरुस्थल को कृषि योग्य बनाया है। परिप्रशान्त महासागरीय पेटी (Ring of Fire) में सर्वाधिक ज्वालामुखी विस्फोट होते हैं।', 'Indira Gandhi Canal (Rajasthan) has made the Thar desert cultivable. Circum-Pacific belt (Ring of Fire) has the highest volcanic eruptions.', 'इंदिरा नहर = मरुस्थल की जीवनरेखा। रिंग ऑफ फायर = ज्वालामुखी।', 'Indira Canal = Lifeline of desert. Ring of Fire = Volcanoes.', 'इंदिरा गांधी नहर सतलज और व्यास नदियों (हरिके बैराज) से पानी लेती है।', 'Indira Gandhi Canal draws water from Sutlej and Beas rivers (Harike Barrage).', 'medium', 0.85, 0.9, '[{"questionId":"Hr0huAkgjAOd0BA_WtiGz"},{"questionId":"BGV-y-EyzVIOLcJwpb6oF"}]', '["Indian Geography","Volcanoes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829456, 1773829456);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('86efcb36-0eee-4594-aaeb-b0e251135b8b', '86a04662-101a-496e-a21a-ea34c8b13867', 'Geography', 'MP की नदियाँ: बेतवा (यमुना की), क्षिप्रा (चंबल की), वैनगंगा (गोदावरी की)। कर्क रेखा MP के 14 जिलों से गुजरती है (इंदौर से नहीं)। बघेलखण्ड में काली मिट्टी नहीं (लाल-पीली) होती है।', 'MP Rivers: Betwa (of Yamuna), Kshipra (of Chambal), Wainganga (of Godavari). Tropic of Cancer passes through 14 MP districts (not Indore). Baghelkhand has no black soil (Red-Yellow).', 'यमुना-बेतवा (Y-B), चंबल-क्षिप्रा। इंदौर कर्क रेखा के नीचे है।', 'Yamuna-Betwa (Y-B), Chambal-Kshipra. Indore is below Tropic of Cancer.', 'मालवा में गहरी काली मिट्टी है, जबकि पूर्वी MP (बघेलखंड) में लाल-पीली। कर्क रेखा के 14 जिलों के नाम याद रखें।', 'Malwa has deep black soil, while eastern MP (Baghelkhand) has red-yellow. Remember names of 14 districts on Tropic of Cancer.', 'medium', 0.94, 0.96, '[{"questionId":"PAzPwcOquG0QYRHsmc9zU"},{"questionId":"e9m-1k7CrSvXjL8xRd3yD"},{"questionId":"0tBCSTtR-h7Ne9ynvZbg8"}]', '["MP Geography","Rivers","Tropic of Cancer"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829457, 1773829457);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('05ff884f-148c-471d-bc53-522261ede8b7', 'e81f4916-95f9-4c81-a06e-72f8ffe89e06', 'History', 'चोल साम्राज्य अपनी ''ग्राम स्वायत्तता'' (Village Autonomy / Local Self-Govt) के लिए प्रसिद्ध था (उत्तरमेरुर अभिलेख)।', 'The Chola Empire was famous for its ''Village Autonomy / Local Self-Govt'' (Uttaramerur inscription).', 'चोल = शानदार गाँव (Cholas = Superb Villages)।', 'Cholas = Superb Villages.', 'नौसेना (Navy) भी चोलों की ताकत थी, लेकिन प्रशासनिक विशेषता में ग्राम स्वायत्तता सबसे अहम है।', 'Navy was also a Chola strength, but in administrative features, village autonomy is paramount.', 'medium', 0.9, 0.95, '[{"questionId":"ES6XOYlXxYBVt7lxn8C3c"}]', '["Chola Empire","Administration"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829458, 1773829458);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7f27ec61-e7ff-433e-9306-2de430fd77e1', 'e81f4916-95f9-4c81-a06e-72f8ffe89e06', 'History', 'सिंधु घाटी की मुहरों (Seals) पर अक्सर ''पीपल'' के वृक्ष की आकृति मिलती है। ''मुद्राराक्षस'' विशाखदत्त की रचना है। मालव संवत को ''कृत संवत'' (या विक्रम संवत) कहा जाता था।', 'Indus Valley seals often depict the ''Peepal'' tree. ''Mudrarakshasa'' is authored by Vishakhadatta. Malava Samvat was called ''Krita Samvat'' (or Vikram Samvat).', 'हड़प्पा में पीपल (Peepal in Harappa)। राक्षस = विशाखदत्त। मालव = कृत (Malava = Krita)।', 'Peepal in Harappa. Rakshasa = Vishakhadatta. Malava = Krita.', 'मुद्राराक्षस में गुप्तकाल का नहीं, मौर्यकाल (चंद्रगुप्त/चाणक्य) का वर्णन है। शक संवत (78 AD) को विक्रम संवत (57 BC) से न मिलाएं।', 'Mudrarakshasa describes Mauryan era (Chandragupta/Chanakya), not Gupta era. Don''t mix Shaka Samvat (78 AD) with Vikram (57 BC).', 'medium', 0.88, 0.92, '[{"questionId":"P7YX3CijHi0h2JEFZP4E3"},{"questionId":"0tkqIjpxn8BbRH0F0vLuy"},{"questionId":"QPy5GVnekTTTaj10FASyT"}]', '["Ancient India","Literature","IVC"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829458, 1773829458);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9717a726-2477-4f0e-86af-db65292d65a5', 'e81f4916-95f9-4c81-a06e-72f8ffe89e06', 'History', 'चन्देल शासक ''विद्याधर'' ने महमूद गज़नवीं के आक्रमण का सफलतापूर्वक सामना किया था। एलोरा व एलीफेंटा मुख्य रूप से ''राष्ट्रकूट'' काल के हैं।', 'Chandela ruler ''Vidyadhar'' successfully faced the invasion of Mahmud Ghaznavi. Ellora & Elephanta are mainly from the ''Rashtrakuta'' period.', 'विद्याधर ने गज़नवीं को विद्या पढ़ाई (Vidyadhar taught Ghaznavi a lesson)। एलोरा = राष्ट्रकूट।', 'Vidyadhar taught Ghaznavi a lesson. Ellora = Rashtrakutas.', 'खजुराहो के मंदिर भी चन्देलों ने बनाए (विद्याधर ने कंदरिया महादेव बनाया)। एलोरा में बौद्ध/जैन गुफाएं भी हैं, लेकिन कैलाश मंदिर राष्ट्रकूटों का है।', 'Khajuraho temples also built by Chandelas (Vidyadhar built Kandariya Mahadev). Ellora has Buddhist/Jain caves too, but Kailash temple is Rashtrakuta.', 'medium', 0.9, 0.94, '[{"questionId":"y9tTNemhVmpsPvXXY-vQg"},{"questionId":"pBQYXQFCherZUzzj_OKBd"}]', '["Medieval India","Architecture"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829458, 1773829458);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('57a27305-bd27-421e-87f1-6153cfd1ae68', 'e81f4916-95f9-4c81-a06e-72f8ffe89e06', 'History', 'लॉर्ड डलहौजी की ''व्यपगत सिद्धान्त'' (Doctrine of Lapse) के तहत विलय किया गया प्रथम राज्य ''सतारा'' (1848) था। महाराजा रणजीत सिंह ''शुकरचकिया'' मिसल से थे।', 'The first state annexed under Lord Dalhousie''s ''Doctrine of Lapse'' was ''Satara'' (1848). Maharaja Ranjit Singh belonged to the ''Sukerchakia'' Misl.', 'हड़प नीति का पहला शिकार सतारा (Satara first victim of Lapse)। रणजीत सिंह = शुकर (Shukarchakia)।', 'Satara first victim of Lapse. Ranjit Singh = Shukarchakia.', 'झांसी और अवध का विलय बाद में हुआ। सतारा सबसे पहला था। कुल 12 सिख मिसल थे।', 'Jhansi and Awadh were annexed later. Satara was the very first. There were 12 Sikh Misls in total.', 'medium', 0.95, 0.98, '[{"questionId":"IkDSUIwNvKr9wzXlrwlav"},{"questionId":"B3Sh8iXMr6JBmbtFSrIOo"}]', '["Modern History","British Policies"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829459, 1773829459);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9c94cb59-9f41-4a75-861c-776d956641bb', 'e81f4916-95f9-4c81-a06e-72f8ffe89e06', 'History', 'दांडी यात्रा साबरमती आश्रम से शुरू हुई (12 मार्च 1930)। लाला लाजपत राय ने कांग्रेस सम्मेलनों को ''शिक्षित भारतीयों का मेला'' कहा था। अंतरिम सरकार में रियासत विभाग सरदार पटेल को मिला।', 'Dandi March started from Sabarmati Ashram (March 12, 1930). Lala Lajpat Rai called Congress sessions an ''annual fair of educated Indians''. States Department in Interim Govt went to Sardar Patel.', 'दांडी यात्रा साबरमती से (Dandi from Sabarmati)। पटेल = रियासतों का एकीकरण (Patel = Integration of States)।', 'Dandi from Sabarmati. Patel = Integration of States.', 'गरम दल के नेता (लाल-बाल-पाल) कांग्रेस के शुरुआती स्वरूप (नरम दल) के घोर आलोचक थे।', 'Extremist leaders (Lal-Bal-Pal) were severe critics of the early form of Congress (Moderates).', 'medium', 0.92, 0.96, '[{"questionId":"BNCy3PvJBi0QC1I4TvRoN"},{"questionId":"_ulNzg-_LRwlrJV4PDIKh"},{"questionId":"GTVpfKjgDrVtEJKZgWYcK"}]', '["Freedom Struggle","National Leaders"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829459, 1773829459);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5d155a2a-008b-48d4-84a1-4b6cea5acc77', '2b874f75-7902-49d2-a57a-12a920b7a7dc', 'Economy', 'BHEL (भारत हैवी इलेक्ट्रिकल्स लिमिटेड) को 2013 में ''महारत्न'' (Maharatna) उद्यम का दर्जा मिला था।', 'BHEL (Bharat Heavy Electricals Limited) was granted ''Maharatna'' enterprise status in 2013.', 'BHEL = 13 (तेरा भला हो / BHEL 13)।', 'BHEL = 13.', 'महारत्न कंपनियों की कुल संख्या और नवीनतम कंपनियों (जैसे Oil India) के नाम अक्सर पूछे जाते हैं।', 'The total number of Maharatna companies and names of the newest ones (like Oil India) are frequently asked.', 'medium', 0.8, 0.88, '[{"questionId":"C6i8K4d0wvXx-dZK2B__5"}]', '["Maharatna Companies","Public Sector"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829459, 1773829459);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('06c4e682-1378-4537-b330-0501a0be322e', '2b874f75-7902-49d2-a57a-12a920b7a7dc', 'Economy', 'आर्थिक सर्वेक्षण 2020-21 ने वित्त वर्ष 2021-22 के लिए 11.5% की वास्तविक विकास दर (GDP) का अनुमान लगाया था।', 'The Economic Survey 2020-21 projected a real GDP growth rate of 11.5% for the financial year 2021-22.', 'कोविड के बाद वी-शेप (V-shaped) रिकवरी की उम्मीद (11.5%)।', 'V-shaped recovery expectation post-Covid (11.5%).', 'यह एक पुराना (2021 का) करंट अफेयर्स डेटा है। आगामी परीक्षा के लिए नवीनतम ''आर्थिक सर्वेक्षण'' और बजट के GDP अनुमानों को याद करें।', 'This is old (2021) current affairs data. For upcoming exams, memorize the GDP projections from the latest ''Economic Survey'' and Budget.', 'medium', 0.75, 0.85, '[{"questionId":"xhFMMUOlNTq0OeymNGPi6"}]', '["Economic Survey","GDP Projections"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829459, 1773829459);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6a57cf5c-4ce1-47b4-bc71-634e940de5dd', '922e69f6-9b07-4607-a11f-f88c81f04eeb', 'MP GK', 'राम सहाय पाण्डे बुंदेलखंड के प्रसिद्ध ''राई'' नृत्य कलाकार हैं (पद्मश्री से सम्मानित)। राई MP का राजकीय लोकनृत्य है।', 'Ram Sahay Pandey is a famous ''Rai'' dance artist from Bundelkhand (awarded Padma Shri). Rai is the state folk dance of MP.', '''राई'' का सहारा = राम सहाय। बुंदेलखंड का गौरव।', 'Support of ''Rai'' = Ram Sahay. Pride of Bundelkhand.', 'राई को मालवा या निमाड़ का नृत्य न समझें, यह विशुद्ध रूप से बुंदेलखंड का है।', 'Do not consider Rai a dance of Malwa or Nimar; it is purely from Bundelkhand.', 'medium', 0.9, 0.95, '[{"questionId":"Z2zm00T3hVC-qaYf2RYIo"}]', '["Folk Dance","Padma Awards"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829471, 1773829471);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('ae540473-41be-4b5a-a4ec-c44f825c8456', '922e69f6-9b07-4607-a11f-f88c81f04eeb', 'MP GK', 'दुर्गा बाई व्याम ''दिग्ना'' (Digna) कला के लिए प्रसिद्ध गोंड कलाकार हैं। नाना साहेब पेनसे पखावज वादक (संगीतकार) थे, चित्रकार नहीं।', 'Durga Bai Vyam is a famous Gond artist known for ''Digna'' art. Nana Saheb Panse was a Pakhawaj player (musician), not a painter.', 'दुर्गा बाई = दिग्ना (D-D)। पेनसे = पखावज (P-P)।', 'Durga Bai = Digna (D-D). Panse = Pakhawaj (P-P).', 'चित्रकारों और संगीतकारों के नामों को अक्सर विकल्पों में मिलाया जाता है। विष्णु चिंचालकर और सैयद हैदर रज़ा चित्रकार हैं।', 'Names of painters and musicians are often mixed in options. Vishnu Chinchalkar and S.H. Raza are painters.', 'medium', 0.85, 0.92, '[{"questionId":"xW-rYHSMi1yk38csmKqBr"},{"questionId":"MRzpr4k8DIILkpPe5_MF6"}]', '["Tribal Art","Personalities"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829472, 1773829472);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('770589db-a8fe-4f8f-b177-ffda241ca1c0', '922e69f6-9b07-4607-a11f-f88c81f04eeb', 'MP GK', 'तुर्रा कलंगी निमाड़ क्षेत्र का प्रसिद्ध लोकनाट्य है जिसमें शिव (तुर्रा) और पार्वती (कलंगी) के अखाड़ों के बीच संगीतमय संवाद होता है।', 'Turra Kalangi is a famous folk drama of the Nimar region involving a musical dialogue between the akhadas of Shiva (Turra) and Parvati (Kalangi).', 'कलंगी सर पर सजती है (निमाड़ का ताज)। शिव और शक्ति का संवाद।', 'Kalangi adorns the head (Crown of Nimar). Dialogue of Shiva and Shakti.', 'यह मालवा में भी खेला जाता है, लेकिन इसका मूल उद्गम/प्रमुखता निमाड़ क्षेत्र (और राजस्थान) है।', 'It is also performed in Malwa, but its primary origin/prominence is the Nimar region (and Rajasthan).', 'medium', 0.8, 0.88, '[{"questionId":"8xII9rco-eM5c871C4PIj"}]', '["Folk Drama","Nimar"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829472, 1773829472);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('adc2e4e1-44b2-4790-b232-8ecdc5be3964', '7cc954cf-841c-4f7a-b88f-8be016a0de7a', 'MP GK', 'गोविन्द नारायण सिंह के मुख्यमंत्री कार्यकाल के दौरान राजमाता विजयाराजे सिंधिया को विधानसभा में सदन का नेता (Leader of the House) माना गया था।', 'During Govind Narayan Singh''s tenure as CM, Rajmata Vijayaraje Scindia was considered the Leader of the House in the Legislative Assembly.', 'गोविन्द CM थे, लेकिन ''राजमाता'' लीडर थीं। (1967 की संविद सरकार)।', 'Govind was CM, but ''Rajmata'' was the Leader. (SVD govt of 1967).', 'आमतौर पर मुख्यमंत्री ही सदन का नेता होता है, लेकिन यह म.प्र. के इतिहास का एक अनूठा अपवाद था।', 'Usually, the CM is the Leader of the House, but this was a unique exception in MP''s history.', 'medium', 0.8, 0.9, '[{"questionId":"lUOLYNVJKXGEuFBj_tuAN"}]', '["MP Polity","Chief Ministers"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829472, 1773829472);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('15c5fd31-810f-41d7-aed9-fdcf76dc7a12', '7cc954cf-841c-4f7a-b88f-8be016a0de7a', 'MP GK', 'रामकिशोर शुक्ला मध्य प्रदेश विधानसभा के एकमात्र व्यक्ति हैं जो प्रोटेम स्पीकर, अध्यक्ष और उपाध्यक्ष तीनों पदों पर रहे हैं।', 'Ramkishore Shukla is the only person in the MP Legislative Assembly to have held all three posts: Pro-tem Speaker, Speaker, and Deputy Speaker.', 'शुक्ला जी = ''ऑल-इन-वन'' स्पीकर।', 'Shukla ji = ''All-in-one'' Speaker.', 'कुंजीलाल दुबे सबसे लंबे समय तक अध्यक्ष रहे, लेकिन तीनों पदों पर केवल शुक्ला जी रहे हैं।', 'Kunjilal Dubey was the longest-serving Speaker, but only Shukla ji held all three posts.', 'medium', 0.85, 0.95, '[{"questionId":"1zP9h9d_1GLe9urD1dbuX"}]', '["Legislative Assembly","Firsts in MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829472, 1773829472);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('bc4b4668-47cf-4597-8398-592ea6fecd40', '7cc954cf-841c-4f7a-b88f-8be016a0de7a', 'MP GK', 'म.प्र. के पूर्व राज्यपाल निरंजन नाथ वान्चू (N.N. Wanchoo) भारत की संविधान सभा के सदस्य नहीं थे।', 'Former MP Governor Niranjan Nath Wanchoo was NOT a member of the Constituent Assembly of India.', 'वान्चू संविधान सभा से ''वंचित'' रह गए।', 'Wanchoo was ''deprived'' (vanchit) of the Constituent Assembly.', 'हरि विनायक पाटस्कर, के.सी. रेड्डी, सी.एम. पुनाचा जैसे कई राज्यपाल संविधान सभा के सदस्य थे। अपवादों को याद रखें।', 'Many Governors like H.V. Pataskar, K.C. Reddy, C.M. Poonacha were members of the Constituent Assembly. Remember the exceptions.', 'medium', 0.75, 0.85, '[{"questionId":"llpu4R5rGFK3F3tb413Tm"}]', '["Governors of MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829472, 1773829472);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('2c4e2464-8d05-415d-8ec5-7aa1b3a74ed6', 'ff0a5131-0bf3-464b-b71a-24fd7de131ff', 'MP GK', 'मध्य प्रदेश में इंदौर (देवी अहिल्याबाई होलकर) और भोपाल (राजा भोज) ही आधिकारिक रूप से अंतर्राष्ट्रीय हवाई अड्डे हैं।', 'In Madhya Pradesh, only Indore (Devi Ahilyabai Holkar) and Bhopal (Raja Bhoj) are officially International Airports.', 'बड़े शहर, बड़ी उड़ानें (इंदौर और भोपाल)। खजुराहो घरेलू है।', 'Big cities, big flights (Indore and Bhopal). Khajuraho is domestic.', 'खजुराहो और ग्वालियर महत्वपूर्ण हैं लेकिन ''अंतर्राष्ट्रीय'' उड़ानों के लिए मुख्य रूप से इंदौर/भोपाल ही अधिकृत हैं।', 'Khajuraho and Gwalior are important, but primarily Indore/Bhopal are authorized for ''international'' flights.', 'medium', 0.85, 0.88, '[{"questionId":"aGo09rMZkDNygmuBE1_-4"}]', '["Transport","Airports"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829473, 1773829473);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('dd541442-5e7d-45e4-9ed2-2580d6aee4f4', 'ff0a5131-0bf3-464b-b71a-24fd7de131ff', 'MP GK', 'अटल प्रगति पथ (पूर्व में चंबल एक्सप्रेस-वे) राजस्थान, मध्य प्रदेश (ग्वालियर-चंबल संभाग) और उत्तर प्रदेश को जोड़ने वाली प्रमुख सड़क परियोजना है।', 'Atal Pragati Path (formerly Chambal Expressway) is a major road project connecting Rajasthan, Madhya Pradesh (Gwalior-Chambal division), and Uttar Pradesh.', 'चंबल के बीहड़ों में अटल विकास (Atal development in Chambal ravines)।', 'Atal development in Chambal ravines.', 'इसे नर्मदा एक्सप्रेस-वे (नर्मदा प्रगति पथ) से भ्रमित न करें जो पूर्व से पश्चिम की ओर है।', 'Do not confuse it with Narmada Expressway (Narmada Pragati Path) which is East to West.', 'medium', 0.88, 0.92, '[{"questionId":"3J4QEZdiABa78AFOEutwS"}]', '["Infrastructure","Expressways"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829473, 1773829473);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('02c09bd9-a85b-42b3-a1ec-c4c67e1f7e9e', 'ff0a5131-0bf3-464b-b71a-24fd7de131ff', 'MP GK', 'दोंगालिया मुंडी (खरगोन) मध्य प्रदेश में एक प्रमुख ''तापीय विद्युत केंद्र'' (Thermal Power Plant) के रूप में जाना जाता है (संत सिंगाजी ताप विद्युत परियोजना)।', 'Dongalia Mundi (Khargone) is known as a major ''Thermal Power Plant'' in Madhya Pradesh (Sant Singaji Thermal Power Project).', 'मुंडी में सिंगाजी (Singaji in Mundi) कोयला जलाते हैं।', 'Singaji burns coal in Mundi.', 'हाइड्रो (जल) और थर्मल (ताप) पावर प्लांट्स के स्थानों को अच्छी तरह से अलग रखें।', 'Keep the locations of Hydro and Thermal power plants well separated.', 'medium', 0.8, 0.85, '[{"questionId":"1RgvxRCdA9o3UFZeRk2jS"}]', '["Energy Sector","Thermal Plants"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829473, 1773829473);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('abae5a0b-b886-43a4-be1f-a5e4884f01e4', '77461108-2fdd-42f0-ac07-cf54b4750ebb', 'MP GK', 'मध्य प्रदेश में ''विमुक्त जाति दिवस'' 31 अगस्त को मनाया जाता है (1952 में आपराधिक जनजाति अधिनियम को निरस्त करने की याद में)।', 'In Madhya Pradesh, ''Vimukt Jati Diwas'' (Denotified Tribes Day) is celebrated on August 31 (to commemorate the repeal of the Criminal Tribes Act in 1952).', 'अगस्त का अंतिम दिन = घुमक्कड़ जातियों की आज़ादी (31 August)।', 'Last day of August = Freedom of nomadic tribes (31 August).', 'इसे जनजातीय गौरव दिवस (15 नवंबर - बिरसा मुंडा) से भ्रमित न करें।', 'Do not confuse this with Janjatiya Gaurav Divas (15 November - Birsa Munda).', 'medium', 0.85, 0.9, '[{"questionId":"6UY7BDL7iRv22sCVB0yDg"}]', '["Important Days","Tribal Welfare"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829473, 1773829473);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('bc7b6d5c-8867-4538-96af-02645ab9f897', '77461108-2fdd-42f0-ac07-cf54b4750ebb', 'MP GK', 'राष्ट्रीय राजमार्गों का मिलान: NH-44 (सागर), NH-46 (भोपाल), NH-30 (जबलपुर), NH-39 (खजुराहो)।', 'National Highways matching: NH-44 (Sagar), NH-46 (Bhopal), NH-30 (Jabalpur), NH-39 (Khajuraho).', '44 सागर के पार (Kashmir to Kanyakumari)। 46 राजधानी (Bhopal) का रास्ता।', '44 across Sagar (Kashmir to Kanyakumari). 46 is the capital''s (Bhopal) path.', 'राजमार्गों के नए नंबरिंग सिस्टम पर ही सवाल आते हैं, पुराने (जैसे NH-3) अब अप्रचलित हैं।', 'Questions are only based on the new numbering system of highways; old ones (like NH-3) are obsolete.', 'medium', 0.92, 0.94, '[{"questionId":"7mwl030u8zla6SySwypmM"}]', '["Transport","Highways"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829473, 1773829473);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('71268cba-1121-4500-9b4b-a03a4af77c1e', '77461108-2fdd-42f0-ac07-cf54b4750ebb', 'MP GK', 'मालवा का पठार काली मिट्टी से ढका है, जो कपास उत्पादन के लिए सर्वोत्तम है। इसी कारण यहाँ सूती वस्त्र मिलों (Textile Mills) की स्थापना हुई है।', 'The Malwa plateau is covered with black soil, which is best for cotton production. Due to this, cotton textile mills have been established here.', 'मालवा की काली मिट्टी = कपास = सूती कपड़े (इंदौर को मिनी मुंबई कहते हैं)।', 'Malwa''s black soil = Cotton = Textiles (Indore is called Mini Mumbai).', 'यह एक कारण-प्रभाव (Cause-Effect) वाला प्रश्न था। भूगोल का सीधा प्रभाव अर्थव्यवस्था पर पड़ता है।', 'This was a Cause-Effect question. Geography has a direct impact on the economy.', 'medium', 0.9, 0.95, '[{"questionId":"N-Z-PHKwgvK9ZBWo3SU1s"}]', '["Economic Geography","Soil"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829473, 1773829473);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a8afe6df-f262-4cc4-934c-d6778dec3e34', '213137ae-acf7-46eb-8d49-463c72683009', 'MP GK', 'बारना परियोजना (Barna Project) रायसेन जिले में स्थित है (उज्जैन में नहीं)। बरगी बांध का नाम रानी अवंतीबाई सागर है।', 'Barna Project is located in Raisen district (not Ujjain). Bargi Dam is named Rani Avantibai Sagar.', 'बार-बार राय देना (Barna = Raisen)।', 'Giving advice repeatedly (Barna = Raisen).', 'तवा परियोजना होशंगाबाद में है। परियोजनाओं के जिलों को मिलाना एक निश्चित प्रश्न है।', 'Tawa project is in Hoshangabad. Matching projects to districts is a definite question.', 'medium', 0.9, 0.94, '[{"questionId":"5oTN4g6-KTa6eTZXM5JIj"}]', '["Irrigation Projects","Geography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829474, 1773829474);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('2d6cd878-a997-43b3-8712-a1160408ad8b', '213137ae-acf7-46eb-8d49-463c72683009', 'MP GK', 'मलंजखंड (बालाघाट) को भारत की ''कॉपर सिटी'' (Copper City) कहा जाता है। हिंदुस्तान कॉपर लिमिटेड का प्रोजेक्ट यहीं है।', 'Malanjkhand (Balaghat) is called the ''Copper City'' of India. Hindustan Copper Limited''s project is here.', 'बालाघाट में तांबे की खान (Malanjkhand) और मैंगनीज (Bharveli)।', 'Copper mine (Malanjkhand) and Manganese (Bharveli) in Balaghat.', 'मलंजखंड तांबे के लिए है, जबकि भरवेली मैंगनीज के लिए (दोनों बालाघाट में)।', 'Malanjkhand is for copper, while Bharveli is for manganese (both in Balaghat).', 'medium', 0.95, 0.98, '[{"questionId":"xG_Ul4hPbAc550C9dUj7L"}]', '["Minerals","Industries"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829474, 1773829474);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9da6e0c6-b599-4be4-bd37-4a35e271f21e', '213137ae-acf7-46eb-8d49-463c72683009', 'MP GK', 'मध्यकालीन शहर ''सिरोंज'' (वर्तमान विदिशा जिला) अपने उत्तम छपे हुए सूती कपड़े ''छींट'' (Chinth) के लिए विश्व प्रसिद्ध था।', 'The medieval city ''Sironj'' (present-day Vidisha district) was world-famous for its fine printed cotton cloth ''Chinth''.', 'सिरोंज का सूट और छींट (Suit and Chinth of Sironj)।', 'Suit and Chinth of Sironj.', 'सिरोंज मूल रूप से राजस्थान का हिस्सा था जिसे 1956 में मध्य प्रदेश (विदिशा) में मिलाया गया।', 'Sironj was originally part of Rajasthan and was merged into Madhya Pradesh (Vidisha) in 1956.', 'medium', 0.8, 0.85, '[{"questionId":"BX7EJyujhrXNR0V-kcvLO"}]', '["Medieval History","Textiles"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829474, 1773829474);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('de2fbb9f-a472-4672-a97f-10ca36e9599a', '213137ae-acf7-46eb-8d49-463c72683009', 'MP GK', '1857 की क्रांति के दौरान ''सिपाही बहादुर सरकार'' की स्थापना सीहोर (Sehore) में हुई थी (इंदौर में नहीं)।', 'During the 1857 revolt, the ''Sipahi Bahadur Sarkar'' was established in Sehore (not Indore).', 'सीहोर के सिपाही बहादुर (Brave soldiers of Sehore)।', 'Brave soldiers of Sehore.', 'इंदौर के महू में सादत खान ने विद्रोह किया था। स्थानीय समानांतर सरकारों के स्थान याद रखें।', 'Saadat Khan revolted in Mhow, Indore. Remember the locations of local parallel governments.', 'medium', 0.82, 0.88, '[{"questionId":"q7pBlXiyKwxhIvQ4b7jIk"}]', '["1857 Revolt","Modern History"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829474, 1773829474);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('923d809c-9417-4694-9c66-d89259895db5', '4e8156f5-f8da-4f1a-bd20-564c2ad7b3c1', 'MP GK', 'सरपंच और उप-सरपंच की अनुपस्थिति में ग्रामसभा की बैठक की अध्यक्षता ग्रामसभा द्वारा उसी समय चुना गया ''पंच'' करता है।', 'In the absence of the Sarpanch and Deputy Sarpanch, a ''Panch'' elected by the Gram Sabha at that time presides over the meeting.', 'बड़े नेता नहीं, तो ''पंच'' ही प्रधान।', 'If no big leaders, the ''Panch'' is the chief.', 'अध्यक्षता BDO या सचिव (Secretary) नहीं करता, बल्कि एक निर्वाचित प्रतिनिधि (पंच) ही करता है।', 'The meeting is NOT presided over by the BDO or Secretary, but by an elected representative (Panch).', 'medium', 0.88, 0.92, '[{"questionId":"6KCgDvyjFuyeLxgbRdMaW"}]', '["Local Self Government","Panchayati Raj"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829475, 1773829475);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('cc25cc48-ba32-4930-9e0f-018442210c52', '4e8156f5-f8da-4f1a-bd20-564c2ad7b3c1', 'MP GK', 'जिला पंचायत में कुल 5 स्थायी समितियाँ होती हैं, जिनमें सामान्य प्रशासन, कृषि, और शिक्षा समिति प्रमुख हैं।', 'A District Panchayat has a total of 5 standing committees, prominent among them being General Administration, Agriculture, and Education.', 'प्रशासन, कृषि, शिक्षा = जिले का विकास।', 'Administration, Agriculture, Education = District Development.', 'जिला पंचायत अध्यक्ष स्वतः ''सामान्य प्रशासन समिति'' का अध्यक्ष होता है।', 'The District Panchayat President is automatically the chairman of the ''General Administration Committee''.', 'medium', 0.8, 0.85, '[{"questionId":"Q-lRBzAk-rAfIORhlVcD3"}]', '["Zila Panchayat","Committees"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829475, 1773829475);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('34c92d9f-cedd-4c36-b5d6-37728cd682e5', '4e8156f5-f8da-4f1a-bd20-564c2ad7b3c1', 'MP GK', 'चिंकी यादव (भोपाल) मध्य प्रदेश की एक प्रसिद्ध निशानेबाज (Shooter - 25m पिस्टल) हैं।', 'Chinki Yadav (Bhopal) is a famous shooter (25m Pistol) from Madhya Pradesh.', 'चिंकी का अचूक निशाना (Chinki''s perfect aim)।', 'Chinki''s perfect aim.', 'खिलाड़ियों के खेल और उनके शहर को याद रखना आवश्यक है।', 'It is necessary to remember the players'' sports and their cities.', 'medium', 0.85, 0.9, '[{"questionId":"INF-XQRSIp-xvSePKC4hf"}]', '["Sports Personalities","Shooting"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829475, 1773829475);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('8cc30f2e-f4b1-46cc-90c8-11ac5b2babf2', '4e8156f5-f8da-4f1a-bd20-564c2ad7b3c1', 'MP GK', 'विवेक सागर प्रसाद (होशंगाबाद) भारतीय हॉकी टीम के प्रमुख मिडफील्डर हैं (टोक्यो ओलंपिक कांस्य पदक विजेता टीम का हिस्सा)।', 'Vivek Sagar Prasad (Hoshangabad) is a key midfielder of the Indian Hockey team (part of the Tokyo Olympics bronze medal-winning team).', 'विवेक की हॉकी ने सागर पार किया (Vivek''s hockey crossed the ocean)।', 'Vivek''s hockey crossed the ocean.', 'उन्हें मध्य प्रदेश सरकार द्वारा डीएसपी (DSP) के पद पर नियुक्त किया गया है।', 'He has been appointed as a DSP by the Madhya Pradesh government.', 'medium', 0.92, 0.95, '[{"questionId":"jlFsbFNnBnCKRaz2CPsUc"}]', '["Hockey","Olympics"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829475, 1773829475);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('95588ae7-1b08-46c9-9e88-de801d4a2cf7', 'c1cb356c-87d3-43bd-9142-73f337c90c05', 'MP GK', 'गोटमार मेला छिन्दवाड़ा जिले के पांढुर्णा कस्बे में जाम नदी के तट पर आयोजित किया जाता है (यहाँ दो गाँवों के लोग पत्थर फेंकते हैं)।', 'Gotmar Mela is organized on the banks of Jam river in Pandhurna town of Chhindwara district (people of two villages throw stones at each other).', 'गोट (पत्थर) मार = पांढुर्णा (छिंदवाड़ा), जाम नदी।', 'Got (Stone) Maar = Pandhurna (Chhindwara), Jam river.', 'अब पांढुर्णा को छिंदवाड़ा से अलग कर एक नया जिला बना दिया गया है, इसलिए भविष्य के प्रश्नों में पांढुर्णा जिला सही उत्तर होगा।', 'Now Pandhurna has been separated from Chhindwara to form a new district, so in future questions, Pandhurna district will be the correct answer.', 'medium', 0.9, 0.95, '[{"questionId":"6QFgwpZ8-78VYnV_vxES0"}]', '["Fairs and Festivals","Chhindwara/Pandhurna"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829475, 1773829475);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('90e15d2b-b687-4f3c-8967-62f796024cc8', '3fb375f0-6f70-40d7-a4e2-2081ebe2e705', 'Polity', '1935 के अधिनियम ने ''अखिल भारतीय संघ'' (All India Federation) का प्रस्ताव रखा था, जो कभी अस्तित्व में नहीं आया क्योंकि रियासतों ने मना कर दिया।', 'The Act of 1935 proposed an ''All India Federation'', which never came into existence because the princely states refused to join.', '1935 = फेडरेशन का फ्लॉप प्लान (Flop Federation Plan)।', '1935 = Flop Federation Plan.', '1935 के एक्ट ने केंद्र में द्वैध शासन (Dyarchy) लागू किया था।', 'The 1935 Act introduced Dyarchy at the Center.', 'medium', 0.9, 0.95, '[{"questionId":"D1O-zAQA5OI11_7L2j72G"}]', '["Historical Acts","Constitution"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829476, 1773829476);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('bd90b052-ce54-47f6-aa0a-dc0ef2a691f2', '3fb375f0-6f70-40d7-a4e2-2081ebe2e705', 'Polity', 'नेहरू जी ने 13 दिसंबर 1946 को संविधान सभा के पहले सत्र की ''तीसरी'' बैठक में ''उद्देश्य प्रस्ताव'' (Objectives Resolution) रखा था।', 'Nehru ji moved the ''Objectives Resolution'' in the ''third'' meeting of the first session of the Constituent Assembly on Dec 13, 1946.', '9 (पहली) -> 11 (दूसरी) -> 13 (तीसरी, नेहरू का प्रस्ताव)।', '9 (First) -> 11 (Second) -> 13 (Third, Nehru''s resolution).', 'उद्देश्य प्रस्ताव ही बाद में संविधान की ''प्रस्तावना'' (Preamble) बना।', 'The Objectives Resolution later became the ''Preamble'' of the Constitution.', 'medium', 0.95, 0.98, '[{"questionId":"EhKAH4bYgKxNyy4pB3sVv"}]', '["Constituent Assembly","Preamble"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829476, 1773829476);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('296b5724-f176-4124-9103-4c15b8d85cfe', '3fb375f0-6f70-40d7-a4e2-2081ebe2e705', 'Polity', 'अनुच्छेद 79: संसद = राष्ट्रपति + लोकसभा + राज्यसभा। अनुच्छेद 108: राष्ट्रपति संयुक्त बैठक (Joint Sitting) बुलाने का ''आशय'' (Intention) सूचित करता है।', 'Article 79: Parliament = President + Lok Sabha + Rajya Sabha. Article 108: President notifies the ''Intention'' to summon a Joint Sitting.', '79 = संसद के 3 अंग। 108 = एम्बुलेंस (जब दोनों सदनों में झगड़ा हो तो 108 बुलाओ)।', '79 = 3 parts of Parliament. 108 = Ambulance (Call 108 when two houses fight).', 'संयुक्त बैठक बुलाता राष्ट्रपति है, लेकिन उसकी अध्यक्षता ''लोकसभा अध्यक्ष'' (Speaker) करता है (Art 118)।', 'The President summons the joint sitting, but it is presided over by the ''Lok Sabha Speaker'' (Art 118).', 'medium', 0.92, 0.96, '[{"questionId":"rgR3qevbeqen1y18HEE1r"},{"questionId":"3cdYIpgo0DY5sI8dKT5Vq"}]', '["Parliament","Articles"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829476, 1773829476);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0cccff51-1d6b-4ddb-8f66-ea5e5531da8c', '3fb375f0-6f70-40d7-a4e2-2081ebe2e705', 'Polity', 'अनुच्छेद 17 ''अस्पृश्यता'' (Untouchability) का अंत करता है।', 'Article 17 abolishes ''Untouchability''.', '17 = सतरा = खतरा (अस्पृश्यता छुआ तो खतरा)।', '17 = Satra = Khatra (Danger if you practice untouchability).', 'यह एक निरपेक्ष (Absolute) मौलिक अधिकार है, जिसका कोई अपवाद नहीं है।', 'This is an absolute fundamental right with no exceptions.', 'medium', 0.98, 0.99, '[{"questionId":"5IQZBQc7Ju6EXoXJHcDwt"}]', '["Fundamental Rights","Articles"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829476, 1773829476);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('1ed5428b-f2c6-4d6d-a63d-fb10a3d5f730', 'eb958aa6-c2da-432b-9226-6e62a09d1028', 'Polity', 'आईटी एक्ट 2000 ने ''डिजिटल हस्ताक्षर'', ''इलेक्ट्रॉनिक रिकॉर्ड'' और ''प्रमाणन प्राधिकरण'' (Certifying Authority) को कानूनी मान्यता प्रदान की।', 'The IT Act 2000 provided legal recognition to ''Digital Signatures'', ''Electronic Records'', and ''Certifying Authorities''.', 'ई-कॉमर्स और ई-गवर्नेंस का कानूनी आधार = IT Act 2000।', 'Legal basis of e-commerce and e-governance = IT Act 2000.', 'यह अधिनियम 17 अक्टूबर 2000 को लागू हुआ था। साइबर अपराधों (हैक करना, अश्लीलता) के लिए दंड भी इसी में हैं (जैसे धारा 66)।', 'This act came into force on Oct 17, 2000. Penalties for cyber crimes (hacking, obscenity) are also in this (e.g., Section 66).', 'medium', 0.8, 0.85, '[{"questionId":"xwNPYJCqAiOXXWLhhZ9dm"}]', '["Cyber Law","IT Act"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829476, 1773829476);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('42d7abac-0a00-45fb-bdea-96f7f6f63302', 'b516f65e-809b-4832-b46d-7be677a1e35d', 'Science', 'दूध का पाश्चुरीकरण (Pasteurization) सही तरीके से हुआ है या नहीं, इसकी जांच के लिए ''फास्फेटेज परीक्षण'' (Phosphatase Test) किया जाता है।', 'To check whether the pasteurization of milk has been done correctly, the ''Phosphatase Test'' is conducted.', 'कच्चे दूध में फास्फेटेज एंजाइम होता है, पाश्चुरीकरण की गर्मी उसे नष्ट कर देती है।', 'Raw milk has phosphatase enzyme, heat of pasteurization destroys it.', 'लैक्टोमीटर दूध का ''घनत्व'' (मिलावट) मापता है, फास्फेटेज टेस्ट ''पाश्चुरीकरण'' की गुणवत्ता जांचता है। दोनों को अलग रखें।', 'Lactometer measures the ''density'' (adulteration) of milk, Phosphatase test checks the quality of ''pasteurization''. Keep both separate.', 'medium', 0.85, 0.9, '[{"questionId":"xOK9Jyuc1Sear5GlmuNM6"}]', '["Food Tech","Everyday Science"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829477, 1773829477);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('00424944-b86c-4e2b-ae39-54ed47ba52af', 'b516f65e-809b-4832-b46d-7be677a1e35d', 'Science', 'ISRO का पूर्ण रूप Indian Space Research Organisation (भारतीय अंतरिक्ष अनुसंधान संगठन) है।', 'The full form of ISRO is Indian Space Research Organisation.', '''I'' stands for India (Not Indian/International in confused options).', '''I'' stands for India (Not Indian/International in confused options).', 'विकल्पों में ''Indian'' और ''International'' या ''Institute'' डालकर भ्रमित किया जाता है। स्थापना: 15 अगस्त 1969।', 'Options confuse by putting ''Indian'' and ''International'' or ''Institute''. Est: 15 Aug 1969.', 'medium', 0.88, 0.92, '[{"questionId":"YArEB6gQFOrEzJB-2SOD1"}]', '["Abbreviations","Space Tech"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829477, 1773829477);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('82409446-f008-489b-aa0a-63f4e0f1d2f5', 'e86713fe-4915-4706-b035-e248493337f5', 'ICT', 'रूटर (Router) एक नेटवर्किंग डिवाइस है जो दो या दो से अधिक कंप्यूटर नेटवर्क के बीच डेटा पैकेट को ''रास्ता'' (Route) दिखाता है।', 'A Router is a networking device that forwards (''routes'') data packets between two or more computer networks.', 'रास्ता दिखाने वाला = Router (Traffic Police of Internet)।', 'One who shows the route = Router (Traffic Police of Internet).', 'स्विच (Switch) एक ही नेटवर्क (LAN) के भीतर उपकरणों को जोड़ता है, जबकि रूटर (Router) अलग-अलग नेटवर्कों (जैसे LAN को WAN से) को जोड़ता है।', 'A Switch connects devices within the same network (LAN), while a Router connects different networks (like LAN to WAN).', 'medium', 0.85, 0.9, '[{"questionId":"hQfcgz6hIXHGH2zLn6mrn"}]', '["Networking Devices","Internet"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829477, 1773829477);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5905dd59-f914-4120-9b74-46dcfaa852c2', 'c9829d1f-c229-4a3b-9acf-677ef5c68f31', 'MP GK', 'गोविन्द नारायण सिंह के मुख्यमंत्री कार्यकाल (संविद सरकार) के दौरान राजमाता विजयाराजे सिंधिया को विधानसभा में सदन का नेता (Leader of the House) माना गया था।', 'During Govind Narayan Singh''s tenure as CM (SVD govt), Rajmata Vijayaraje Scindia was considered the Leader of the House in the Legislative Assembly.', 'गोविन्द CM थे, लेकिन ''राजमाता'' लीडर थीं।', 'Govind was CM, but ''Rajmata'' was the Leader.', 'आमतौर पर मुख्यमंत्री ही सदन का नेता होता है, लेकिन यह म.प्र. के इतिहास का एक अनूठा अपवाद (Exception) था।', 'Usually, the CM is the Leader of the House, but this was a unique exception in MP''s history.', 'medium', 0.8, 0.9, '[{"questionId":"lUOLYNVJKXGEuFBj_tuAN"}]', '["MP Chief Ministers","Political Exceptions"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829499, 1773829499);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6b7f5544-08eb-4750-869d-8667289d8afe', 'c9829d1f-c229-4a3b-9acf-677ef5c68f31', 'MP GK', 'दिग्विजय सिंह और मोतीलाल वोरा कभी भी मध्य प्रदेश विधानसभा में नेता प्रतिपक्ष (Leader of Opposition) नहीं रहे।', 'Digvijaya Singh and Motilal Vora were never the Leader of Opposition in the MP Legislative Assembly.', 'दिग्विजय और मोतीलाल हमेशा सत्ता पक्ष में रहे (या केंद्र में)।', 'Digvijaya and Motilal were always in the ruling party (or at the center).', 'वीरेन्द्र कुमार सखलेचा और श्यामाचरण शुक्ल ने नेता प्रतिपक्ष का पद संभाला था।', 'Virendra Kumar Sakhlecha and Shyama Charan Shukla had held the post of Leader of Opposition.', 'medium', 0.75, 0.85, '[{"questionId":"5AppPT9ucNCqkgC-dL7j0"}]', '["MP Politicians"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829499, 1773829499);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('86134ee1-8f7c-45e1-be85-cb2e48096527', 'c9829d1f-c229-4a3b-9acf-677ef5c68f31', 'MP GK', 'डॉ. भगवत दयाल शर्मा हरियाणा के पहले मुख्यमंत्री थे और बाद में मध्य प्रदेश के राज्यपाल (1980-1984) बने।', 'Dr. Bhagwat Dayal Sharma was the first Chief Minister of Haryana and later became the Governor of Madhya Pradesh (1980-1984).', 'हरियाणा का CM, MP का राज्यपाल (Sharma ji)।', 'Haryana''s CM, MP''s Governor (Sharma ji).', 'राज्यपालों के पिछले राजनीतिक पदों (जैसे रामनरेश यादव - यूपी के सीएम) से बहुत प्रश्न बनते हैं।', 'Many questions are formed from the previous political posts of Governors (like Ramnaresh Yadav - UP CM).', 'medium', 0.88, 0.92, '[{"questionId":"glphfKCQFkGvF47rO0xg8"}]', '["MP Governors"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829500, 1773829500);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('ece43706-2c74-4c1e-bcb1-dc257eb2d649', 'c9829d1f-c229-4a3b-9acf-677ef5c68f31', 'MP GK', 'मध्य प्रदेश राज्य निर्वाचन आयोग का गठन 1 फरवरी 1994 को हुआ था (73वें संशोधन के तहत पहला राज्य)।', 'The Madhya Pradesh State Election Commission was formed on February 1, 1994 (the first state under the 73rd Amendment).', 'पंचायती राज (1993) लागू होते ही 1994 के शुरू (फरवरी) में आयोग बन गया।', 'As soon as Panchayati Raj (1993) was implemented, the commission was formed in early 1994 (Feb).', 'MPPSC का गठन 1956 (धारा 118-3) में हुआ था, लेकिन चुनाव आयोग 1994 में। दोनों के स्थापना वर्ष में भ्रमित न हों।', 'MPPSC was formed in 1956 (Section 118-3), but the Election Commission in 1994. Don''t confuse their establishment years.', 'medium', 0.95, 0.96, '[{"questionId":"0zbu10zmmQCMC8a3_Uytr"},{"questionId":"7oSPOtqzSGJ8GCcUauEgC"}]', '["State Commissions","Panchayati Raj"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829500, 1773829500);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('db99b293-7473-4192-9f6f-823a4c84743b', 'c9829d1f-c229-4a3b-9acf-677ef5c68f31', 'MP GK', 'विधानसभा की कार्यवाही का सही क्रम: शपथ/प्रतिज्ञान -> राज्यपाल का अभिभाषण -> मंत्रियों का परिचय -> निधन सम्बन्धी उल्लेख।', 'Correct sequence of Assembly proceedings: Oath/Affirmation -> Governor''s Address -> Introduction of Ministers -> Obituary References.', 'पहले सदस्य बनेंगे (शपथ), फिर बॉस बोलेंगे (राज्यपाल), फिर टीम दिखाएंगे (मंत्री), अंत में दुख जताएंगे (निधन)।', 'First become members (Oath), then Boss speaks (Governor), then show the team (Ministers), finally express sorrow (Obituary).', 'यह प्रश्न संसदीय प्रक्रिया की गहरी समझ पर आधारित था, इसे रटना होगा।', 'This question was based on a deep understanding of parliamentary procedure; it must be rote-learned.', 'medium', 0.7, 0.8, '[{"questionId":"jymuyFk4HBGHuKORlMCE6"}]', '["Legislative Procedures"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829500, 1773829500);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('38d9fe37-8461-4da8-a006-b86ccebcac1c', '4730488a-99aa-4a5e-9486-3f4716582b21', 'MP GK', 'पद्मश्री विजेता कलाकार: भूरी बाई (झाबुआ) ''पिथौरा'' भील कला के लिए, और दुर्गा बाई व्याम (डिंडौरी) ''दिग्ना'' गोंड कला के लिए प्रसिद्ध हैं।', 'Padma Shri winning artists: Bhuri Bai (Jhabua) is famous for ''Pithora'' Bhil art, and Durga Bai Vyam (Dindori) for ''Digna'' Gond art.', 'B-B-P (Bhuri Bai - Bheel - Pithora)। D-D (Durga - Digna)।', 'B-B-P (Bhuri Bai - Bheel - Pithora). D-D (Durga - Digna).', 'राम सहाय पाण्डे ''राई'' नृत्य (बुंदेलखंड) से हैं। चित्रकारों और नर्तकों को आपस में न मिलाएं।', 'Ram Sahay Pandey is from ''Rai'' dance (Bundelkhand). Don''t mix up painters and dancers.', 'medium', 0.95, 0.98, '[{"questionId":"pDQe0cPi85eHL44222iQe"},{"questionId":"xW-rYHSMi1yk38csmKqBr"},{"questionId":"Z2zm00T3hVC-qaYf2RYIo"}]', '["Tribal Art","Padma Awards"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829502, 1773829502);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('ef0e250e-0544-4e97-98d8-8313a8ab4aaf', '4730488a-99aa-4a5e-9486-3f4716582b21', 'MP GK', 'मध्य प्रदेश जनजातीय संग्रहालय भोपाल में है। 84 महादेव की परिक्रमा उज्जैन (अवंतिका) में होती है।', 'Madhya Pradesh Tribal Museum is in Bhopal. The parikrama of 84 Mahadevs takes place in Ujjain (Avantika).', 'राजधानी में जनजातीय संग्रहालय (Tribal Museum in Capital)। महाकाल के शहर में 84 महादेव।', 'Tribal Museum in Capital. 84 Mahadevs in Mahakal''s city.', 'छिंदवाड़ा में ''बादल भोई'' जनजातीय संग्रहालय है। दोनों में स्पष्ट अंतर रखें।', 'Chhindwara has the ''Badal Bhoi'' Tribal Museum. Keep a clear distinction between the two.', 'medium', 0.9, 0.94, '[{"questionId":"ScyQf5-dVzVOcoYF15D4T"},{"questionId":"h925i885zBK_4Efbaqg7D"}]', '["Museums","Culture"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829502, 1773829502);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('59d13115-2432-448f-a9cd-80154a5372a7', '4730488a-99aa-4a5e-9486-3f4716582b21', 'MP GK', '1857 की क्रांति: ''सिपाही बहादुर सरकार'' सीहोर में स्थापित हुई। सादत खान और भागीरथ सिलावट ने इंदौर (महू) में विद्रोह किया।', '1857 Revolt: ''Sipahi Bahadur Sarkar'' was established in Sehore. Saadat Khan and Bhagirath Silawat revolted in Indore (Mhow).', 'सीहोर के सिपाही। इंदौर के सादत।', 'Soldiers of Sehore. Saadat of Indore.', 'स्थानीय नेताओं और उनके विद्रोह के केंद्रों का सटीक मिलान करना MPPSC का मुख्य पैटर्न है।', 'Accurately matching local leaders with their centers of revolt is a core MPPSC pattern.', 'medium', 0.88, 0.92, '[{"questionId":"q7pBlXiyKwxhIvQ4b7jIk"},{"questionId":"kd6dpahRP2G9zASzGx8Q5"}]', '["1857 Revolt","Modern History of MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829502, 1773829502);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('daf88c39-73c6-40ed-82e7-322e6ddd5649', '4730488a-99aa-4a5e-9486-3f4716582b21', 'MP GK', 'प्राचीन/मध्यकालीन शहर: सिरोंज (विदिशा) ''छींट'' (सूती कपड़े) के लिए प्रसिद्ध था। धर्म राजेश्वर मंदिर मंदसौर (दशपुर) में है। सांची का प्राचीन नाम काकणाम/काकणदबोट था।', 'Ancient/Medieval cities: Sironj (Vidisha) was famous for ''Chinth'' (cotton cloth). Dharmarajeshwar temple is in Mandsaur (Dashpur). Ancient name of Sanchi was Kakanam/Kakanadabota.', 'सिरोंज का छींट। सांची का ''क'' (Kakanad)। धर्म का मन्दिर (मंदसौर)।', 'Chinth of Sironj. ''K'' of Sanchi (Kakanad). Temple of Dharma (Mandsaur).', 'विदिशा का प्राचीन नाम भेलसा था, सांची का काकनाद। दोनों पास हैं, लेकिन नाम अलग हैं।', 'Vidisha''s ancient name was Bhilsa, Sanchi''s was Kakanad. They are close, but names are different.', 'medium', 0.85, 0.9, '[{"questionId":"BX7EJyujhrXNR0V-kcvLO"},{"questionId":"s1sNnGHZX_Vxt8Z0xX3V5"},{"questionId":"u1X_-YbVkkpyjtLTK4kJX"}]', '["Historical Sites","Ancient MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829502, 1773829502);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('8c500606-bb97-4218-90cd-476cfa57914c', '4730488a-99aa-4a5e-9486-3f4716582b21', 'MP GK', 'विद्वान/साहित्यकार: बालकवि बैरागी का असली नाम ''नंदराम दास'' था। ''हिमतरंगिनी'' माखनलाल चतुर्वेदी की रचना है। राजा भोज के कवि धनपाल (तिलकमंजरी) ने जैन धर्म अपनाया।', 'Scholars/Writers: Balkavi Bairagi''s real name was ''Nandram Das''. ''Himtarangini'' is a work by Makhanlal Chaturvedi. Raja Bhoj''s poet Dhanpal (Tilakmanjari) adopted Jainism.', 'नंदलाल = बालकवि। हिम (बर्फ) = माखन (सफेद)। धन का त्याग कर जैन बने।', 'Nandlal = Balkavi. Snow = Butter (White). Gave up wealth to become Jain.', 'हिमतरंगिनी को भवानी प्रसाद मिश्र की रचना न समझें (उनकी ''गीत फरोश'' है)।', 'Do not mistake Himtarangini as Bhavani Prasad Mishra''s work (his is ''Geet Farosh'').', 'medium', 0.82, 0.88, '[{"questionId":"IS0fuN2nhzjifaiDlScyC"},{"questionId":"kehHgloPsgdZcZ5XWyexO"},{"questionId":"Gawucq2tteH7Pn_eG55hw"}]', '["Literature","MP Personalities"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829502, 1773829502);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6932601b-6295-45c9-8a22-e3953b328405', '4730488a-99aa-4a5e-9486-3f4716582b21', 'MP GK', 'अल-बरूनी (तहकीक-ए-हिन्द) ने कलचुरी शासक गांगेयदेव (त्रिपुरी) का विवरण दिया है। दोस्त मोहम्मद खाँ ने भोपाल रियासत बसाई। वीरसिंह देव की राजधानी गहोरा थी।', 'Al-Biruni (Tahqiq-i-Hind) described Kalachuri ruler Gangeyadeva (Tripuri). Dost Mohammad Khan founded the Bhopal princely state. Vir Singh Deo''s capital was Gahora.', 'भोपाल का दोस्त (Friend of Bhopal)। बघेलों का घर = गहोरा।', 'Friend of Bhopal. Home of Baghels = Gahora.', 'भोपाल शहर राजा भोज ने बसाया था, लेकिन ''रियासत'' दोस्त मोहम्मद खाँ ने।', 'Bhopal city was founded by Raja Bhoj, but the ''princely state'' by Dost Mohammad Khan.', 'medium', 0.85, 0.92, '[{"questionId":"DSf14mCzz4xUiEzUaIcj8"},{"questionId":"BNg9aUtHQDu71xr2ogsCI"},{"questionId":"GOWWwyPdmC_Fw-hZhqFC5"}]', '["Medieval MP","Dynasties"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829502, 1773829502);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('1b5e7d5b-bb66-4632-8420-aa87b2d7b24b', '1b08126e-d577-467f-af83-4e906a5ed6f9', 'Polity', 'संविधान सभा की तीसरी बैठक (13 दिसंबर 1946) में नेहरू जी ने ''उद्देश्य प्रस्ताव'' पेश किया। फ्रैंक एंथोनी पहले मनोनीत उप-सभापति थे।', 'In the third meeting of the Constituent Assembly (Dec 13, 1946), Nehru introduced the ''Objectives Resolution''. Frank Anthony was the first nominated Deputy Chairman.', '13 को प्रस्ताव। फ्रैंक (Frank) तरीके से पहले उप-सभापति बने।', 'Resolution on 13th. Became Deputy Chairman in a ''Frank'' manner.', 'उद्देश्य प्रस्ताव ही बाद में ''प्रस्तावना'' (Preamble) बना। एच.सी. मुखर्जी ''निर्वाचित'' उप-सभापति थे, जबकि फ्रैंक एंथोनी ''मनोनीत''।', 'The Objectives Resolution later became the Preamble. H.C. Mukherjee was the ''elected'' Deputy Chairman, while Frank Anthony was ''nominated''.', 'medium', 0.92, 0.95, '[{"questionId":"EhKAH4bYgKxNyy4pB3sVv"},{"questionId":"6CZAszheOI0OVoijs5XCq"}]', '["Constituent Assembly","Historical Background"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829506, 1773829506);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e99b27f6-fb30-4c74-94e6-34756187d767', '1b08126e-d577-467f-af83-4e906a5ed6f9', 'Polity', '1935 के अधिनियम ने ''अखिल भारतीय संघ'' (All India Federation) का प्रस्ताव रखा था। 1919 के अधिनियम के तहत अंतिम केंद्रीय चुनाव 1945 में हुए थे।', 'The Act of 1935 proposed an ''All India Federation''. Under the Act of 1919, the last central elections were held in 1945.', '1935 = फेडरेशन का फ्लॉप प्लान। 1919 का कानून आज़ादी के ठीक पहले (1945) तक चला।', '1935 = Flop Federation Plan. 1919 Act lasted until just before independence (1945).', '1935 के तहत संघ कभी नहीं बना क्योंकि रियासतों ने मना कर दिया। 1935 का एक्ट आने के बाद भी केंद्र के चुनाव 1919 के एक्ट से ही हुए।', 'The federation under 1935 was never formed as princely states refused. Even after the 1935 Act, central elections were held under the 1919 Act.', 'medium', 0.9, 0.96, '[{"questionId":"D1O-zAQA5OI11_7L2j72G"},{"questionId":"V9znKAX76Q9Lh5ot3w2BS"}]', '["British Acts","Constitutional History"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829506, 1773829506);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('49e19bf9-c316-426b-8336-bb19d418d692', '1b08126e-d577-467f-af83-4e906a5ed6f9', 'Polity', 'अनुच्छेद 17 अस्पृश्यता (Untouchability) का अंत करता है। अनुच्छेद 24 बाल श्रम (Child Labor) पर ''पूर्ण निषेध'' लगाता है।', 'Article 17 abolishes Untouchability. Article 24 imposes an ''absolute prohibition'' on Child Labor.', '17 = सतरा = खतरा (छुआछूत)। 24 घंटे बच्चों से काम नहीं (No child labor 24x7)।', '17 = Satra = Khatra (Untouchability). No child labor 24x7.', 'अनुच्छेद 24 में जोखिम वाले कामों के लिए कोई अपवाद नहीं है (पूर्ण निषेध)।', 'There is no exception for hazardous work in Article 24 (absolute prohibition).', 'medium', 0.98, 0.99, '[{"questionId":"5IQZBQc7Ju6EXoXJHcDwt"},{"questionId":"sf5CmoX-CzCfTZsuuPnJR"}]', '["Fundamental Rights","Articles"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829506, 1773829506);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('55059027-52e4-4258-86c4-cd0fc43829f4', '1b08126e-d577-467f-af83-4e906a5ed6f9', 'Polity', 'अनुच्छेद 108: राष्ट्रपति संयुक्त बैठक (Joint Sitting) बुलाने का ''आशय'' (Intention) सूचित करता है। अनुच्छेद 79: संसद = राष्ट्रपति + लोकसभा + राज्यसभा।', 'Article 108: President notifies the ''Intention'' to summon a Joint Sitting. Article 79: Parliament = President + Lok Sabha + Rajya Sabha.', '108 = एम्बुलेंस (झगड़ा होने पर)। 79 = संसद के 3 अंग।', '108 = Ambulance (when there''s a fight). 79 = 3 parts of Parliament.', 'संयुक्त बैठक बुलाता राष्ट्रपति है, लेकिन उसकी अध्यक्षता ''लोकसभा अध्यक्ष'' करता है (Art 118)।', 'The President summons the joint sitting, but it is presided over by the ''Lok Sabha Speaker'' (Art 118).', 'medium', 0.94, 0.95, '[{"questionId":"Z9Ae5amSGyn9Zywnz3R8i"},{"questionId":"3cdYIpgo0DY5sI8dKT5Vq"},{"questionId":"rgR3qevbeqen1y18HEE1r"}]', '["Parliament","Legislative Procedures"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829506, 1773829506);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9c328689-2b2e-4536-ad57-d99509cf173e', '1b08126e-d577-467f-af83-4e906a5ed6f9', 'Polity', 'आयोग (Commissions): राज्य निर्वाचन आयुक्त की नियुक्ति राज्यपाल करता है (Art 243K)। SPSC (राज्य लोक सेवा आयोग) की नियुक्ति राज्यपाल करता है (Art 316)। CAG अपनी रिपोर्ट राष्ट्रपति को सौंपता है (Art 151)।', 'Commissions: State Election Commissioner is appointed by Governor (Art 243K). SPSC is appointed by Governor (Art 316). CAG submits his report to the President (Art 151).', 'राज्य के आयोग = राज्यपाल की नियुक्ति। CAG की रिपोर्ट = राष्ट्रपति।', 'State Commissions = Governor''s appointment. CAG report = President.', 'SPSC के सदस्यों की नियुक्ति राज्यपाल करता है, लेकिन उन्हें ''हटाने'' (Removal) का अधिकार केवल राष्ट्रपति के पास है।', 'SPSC members are appointed by the Governor, but the power to ''remove'' them rests ONLY with the President.', 'medium', 0.95, 0.96, '[{"questionId":"p_Fv6g6KKQ-Rj1sKypmk2"},{"questionId":"vf-uh0G-7Sciyl7SGSPrN"},{"questionId":"Qjj3lI0nSg03ss6iNf-Ov"},{"questionId":"qOdSU-7YYCkR6X0Nnggvq"}]', '["Constitutional Bodies","State Executive"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829506, 1773829506);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a4f35e61-8283-4081-ab82-3515e4b7ffe0', '1b08126e-d577-467f-af83-4e906a5ed6f9', 'Polity', 'सुप्रीम कोर्ट (SC) में अनुच्छेद 127 के तहत केवल ''तदर्थ न्यायाधीशों'' (Ad hoc) की नियुक्ति होती है (''अतिरिक्त न्यायाधीश'' केवल हाई कोर्ट में)। अनुच्छेद 131 SC का ''मूल क्षेत्राधिकार'' (केंद्र-राज्य विवाद) है।', 'Only ''Ad hoc'' judges are appointed in SC under Article 127 (''Additional judges'' are only in High Courts). Article 131 is SC''s ''Original Jurisdiction'' (Center-State disputes).', 'सुप्रीम कोर्ट में केवल ''तदर्थ'' (Ad hoc)। केंद्र-राज्य झगड़ा = सीधे SC (Original)।', 'Only ''Ad hoc'' in Supreme Court. Center-State fight = Directly SC (Original).', 'अतिरिक्त (Additional) और कार्यकारी (Acting) न्यायाधीश हाई कोर्ट में होते हैं। सुप्रीम कोर्ट में कोरम पूरा न होने पर तदर्थ (Ad hoc) जज बुलाए जाते हैं।', 'Additional and Acting judges are in High Courts. Ad hoc judges are called in SC when there is a lack of quorum.', 'medium', 0.88, 0.92, '[{"questionId":"ZHJSxWIybUcLR7pMy4ux7"},{"questionId":"pZPeqhHoOXM9VGvLQDxLe"}]', '["Judiciary","Supreme Court"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829506, 1773829506);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5a44f12e-7df2-4d52-a773-3e8b4b1957c3', '1b08126e-d577-467f-af83-4e906a5ed6f9', 'Polity', 'अनुच्छेद 243-T (243-द) नगरपालिकाओं में SC/ST आरक्षण सुनिश्चित करता है। चुनाव संघ सूची (प्रविष्टि 72) का विषय है।', 'Article 243-T ensures SC/ST reservation in Municipalities. Elections are a Union List subject (Entry 72).', 'T for Town (Municipalities Reservation)। चुनाव करवाना ''केंद्र'' की जिम्मेदारी।', 'T for Town (Municipalities Reservation). Conducting elections is Center''s responsibility.', 'पंचायतों में आरक्षण 243-D में है, जबकि नगरपालिकाओं में 243-T में।', 'Reservation in Panchayats is in 243-D, while in Municipalities it is in 243-T.', 'medium', 0.85, 0.9, '[{"questionId":"cQRczXV8DTjPZYl8ZUGb7"},{"questionId":"zlGcx20qR-91EVnZAM-Dh"}]', '["Local Self Government","Schedules"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829506, 1773829506);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d3eeb2fc-0500-408f-9ef5-1e3cda72f762', 'ec5b1141-d675-443c-ada7-17a57b7cfe43', 'Geography', 'भारत में खनिज एकाधिकार: पन्ना (MP) भारत में ''हीरा'' (Diamond) उत्पादन का एकमात्र स्थान है। जबलपुर का संगमरमर (Marble) एक ''अधात्विक'' (Non-metallic) खनिज है।', 'Mineral Monopoly in India: Panna (MP) is the only place in India producing ''Diamond''. Jabalpur''s Marble is a ''Non-metallic'' mineral.', 'MP का रत्न = पन्ना (हीरा)। संगमरमर में धातु नहीं (Non-metallic)।', 'Gem of MP = Panna (Diamond). Marble has no metal (Non-metallic).', 'संगमरमर एक रूपांतरित (Metamorphic) चट्टान है। इसे चूना पत्थर (अवसादी) से भ्रमित न करें।', 'Marble is a Metamorphic rock. Do not confuse it with Limestone (Sedimentary).', 'medium', 0.95, 0.98, '[{"questionId":"-2o2kliXYfgT7Z-spuNCi"},{"questionId":"nDA9k9JmQ-qPlLhZUYFj1"},{"questionId":"1TTvYqDIGvfL9aMh5NWVQ"}]', '["Minerals of MP","Geology"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829510, 1773829510);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('756ba216-d71a-4756-8b78-397ff9fd688b', 'ec5b1141-d675-443c-ada7-17a57b7cfe43', 'Geography', 'चंबल नदी घाटी परियोजनाएं: गांधी सागर (MP), राणा प्रताप सागर (RJ), और जवाहर सागर (RJ)। बेतवा नदी (MP की गंगा) रायसेन के कुमरागाँव से निकलती है।', 'Chambal River Valley Projects: Gandhi Sagar (MP), Rana Pratap Sagar (RJ), and Jawahar Sagar (RJ). Betwa river (Ganga of MP) originates from Kumragaon in Raisen.', 'G-R-J (गांधी, राणा, जवाहर) चंबल पर। B-V (Betwa-Vindhyachal/Raisen)।', 'G-R-J (Gandhi, Rana, Jawahar) on Chambal. B-V (Betwa-Vindhyachal/Raisen).', 'गांधी सागर MP (मंदसौर) में है, बाकी दोनों राजस्थान में हैं।', 'Gandhi Sagar is in MP (Mandsaur), the other two are in Rajasthan.', 'medium', 0.9, 0.95, '[{"questionId":"8447A3Zfua4SrjwwpEBQY"},{"questionId":"LFlW1HchYLv5V4Nn1gTP9"},{"questionId":"8O5OlPbsQypYytvtEpBCK"}]', '["Rivers of MP","Irrigation Projects"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829510, 1773829510);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0b51d6fd-39cd-44b2-862c-ad3278c6b16c', 'ec5b1141-d675-443c-ada7-17a57b7cfe43', 'Geography', 'MP वन एवं कृषि: भारत में सर्वाधिक ''सागौन'' (Teak) वन MP में हैं (कुल वन क्षेत्र का ~20%)। MP की प्रमुख खाद्यान्न फसल ''गेहूँ'' है।', 'MP Forests & Agriculture: India''s maximum ''Teak'' forests are in MP (~20% of total forest area). MP''s main food grain crop is ''Wheat''.', 'MP = Maximum Plants (Teak)। मालवा का गेहूँ (Wheat of Malwa)।', 'MP = Maximum Plants (Teak). Wheat of Malwa.', 'MP को ''सोया स्टेट'' कहा जाता है (व्यापारिक), लेकिन ''खाद्यान्न'' में गेहूँ का क्षेत्रफल/उत्पादन सबसे ज्यादा है।', 'MP is called ''Soya State'' (commercial), but in ''food grains'', wheat has the largest area/production.', 'medium', 0.88, 0.92, '[{"questionId":"C7GiZ3GllY5XrenCfPL_-"},{"questionId":"w0MN3pH5nKW0WUa6Ozi0y"},{"questionId":"ofInu3nb225zJjHaeN6jn"}]', '["Agriculture in MP","Forests of MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829510, 1773829510);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6d562199-a61a-417e-ab55-b3ef4d3c96d6', 'ec5b1141-d675-443c-ada7-17a57b7cfe43', 'Geography', 'MP जलवायु: उत्तरी भाग (ग्वालियर/चंबल) समुद्र से दूर होने के कारण ''महाद्वीपीय'' जलवायु (अधिक तापान्तर) का अनुभव करता है। दक्षिण से उत्तर जाने पर ग्रीष्म ऋतु में तापमान बढ़ता है।', 'MP Climate: The northern part (Gwalior/Chambal) experiences ''Continental'' climate (high temperature range) due to distance from the sea. Temperature increases in summer from south to north.', 'समुद्र से दूर = भयंकर गर्मी, भयंकर सर्दी (ग्वालियर)। ऊपर जाओ, गर्मी पाओ (Go North, get hotter)।', 'Far from sea = Extreme hot, extreme cold (Gwalior). Go North, get hotter.', 'मालवा (इंदौर) की जलवायु समशीतोष्ण (Temperate) है, जो फाह्यान के अनुसार दुनिया की ''सर्वश्रेष्ठ जलवायु'' है।', 'Malwa''s (Indore) climate is temperate, which according to Fa-Hien is the ''best climate'' in the world.', 'medium', 0.85, 0.88, '[{"questionId":"9XkJhgSS6nSTFOQwG_Zm4"},{"questionId":"QeMO1wKrAFjV4esGdPjV5"}]', '["Climate of MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829510, 1773829510);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('772075e8-2575-46ba-8c3f-de0a587bc645', 'ec5b1141-d675-443c-ada7-17a57b7cfe43', 'Geography', '2011 जनगणना MP: बालाघाट में सर्वाधिक लिंगानुपात (1021) है। भिंड में सबसे कम (837) है।', '2011 Census MP: Balaghat has the highest sex ratio (1021). Bhind has the lowest (837).', 'बालाघाट (Balaghat) = Best (B)।', 'Balaghat (B) = Best.', 'केवल बालाघाट, अलीराजपुर, मंडला और डिंडौरी (4 जिले) का लिंगानुपात 1000 से ऊपर है।', 'Only Balaghat, Alirajpur, Mandla, and Dindori (4 districts) have a sex ratio above 1000.', 'medium', 0.92, 0.95, '[{"questionId":"1NBWdOokKsAHqlXR56XOb"}]', '["MP Census 2011"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829510, 1773829510);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('462996bc-b9e2-411b-9e7b-396a4226c6d5', 'ec5b1141-d675-443c-ada7-17a57b7cfe43', 'Geography', 'विश्व भूगोल: ''ट्रक कृषि'' (Truck farming) ताजी सब्जियों की खेती है जो रात भर में ट्रक से बाजार पहुंचाई जाती है।', 'World Geography: ''Truck farming'' is the cultivation of fresh vegetables which are transported to the market overnight by truck.', 'ट्रक = ताजी सब्जियां (Fresh vegetables)।', 'Truck = Fresh vegetables.', 'इसका ''परिवहन वाहनों'' की खेती से कोई संबंध नहीं है। यह बागवानी (Horticulture) का एक रूप है।', 'It has nothing to do with farming ''transport vehicles''. It''s a form of horticulture.', 'medium', 0.75, 0.8, '[{"questionId":"Ahr3o1ZvjDWseNt1UwVvH"}]', '["Agricultural Practices"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829510, 1773829510);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a1996c75-1f04-4ddb-a8f9-c8975ee86e65', '1087cbe2-4923-435a-85e0-70cb2b60a5a2', 'Economy', 'ऑयल इंडिया लिमिटेड (OIL) 2020 तक ''नवरत्न'' कंपनी थी। (नोट: अगस्त 2023 में इसे 13वीं ''महारत्न'' कंपनी का दर्जा मिल गया है)।', 'Oil India Limited (OIL) was a ''Navratna'' company till 2020. (Note: In Aug 2023, it was upgraded to the 13th ''Maharatna'' company).', 'IOCL, ONGC पहले से महारत्न हैं, OIL सबसे नया (13वां) है।', 'IOCL, ONGC are already Maharatnas, OIL is the newest (13th).', 'महारत्न कंपनियों की नवीनतम सूची (13) को हमेशा परीक्षा से पहले अपडेट करें।', 'Always update the latest list (13) of Maharatna companies before the exam.', 'medium', 0.9, 0.95, '[{"questionId":"1QqtuC1wVSwtbIWfW61Eb"}]', '["Public Sector Undertakings","Maharatna"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829511, 1773829511);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d592843f-4c6b-4a92-b540-728e0b125378', '1087cbe2-4923-435a-85e0-70cb2b60a5a2', 'Economy', 'वित्तीय क्षेत्र के मूल्यांकन समिति (Committee on Financial Sector Assessment) की सह-अध्यक्षता RBI के डिप्टी गवर्नर और वित्त सचिव करते हैं।', 'The Committee on Financial Sector Assessment is co-chaired by the RBI Deputy Governor and the Finance Secretary.', 'वित्त (Finance Secretary) + बैंक (RBI Deputy)।', 'Finance (Finance Secretary) + Bank (RBI Deputy).', 'इसे RBI गवर्नर और वित्त मंत्री (Finance Minister) से न मिलाएं; यह नौकरशाहों (Bureaucrats) की समिति है।', 'Do not mix it with RBI Governor and Finance Minister; it is a committee of bureaucrats.', 'medium', 0.75, 0.85, '[{"questionId":"37acV022Y0tPjTZge3JBu"}]', '["Financial Committees","RBI"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829511, 1773829511);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('1dca534d-06b7-4f6e-9c07-947bcffd4b3f', '1087cbe2-4923-435a-85e0-70cb2b60a5a2', 'Economy', 'RBI ने 23 फरवरी 2018 को गैर-बैंकिंग वित्तीय कंपनियों (NBFCs) के लिए ''लोकपाल योजना'' (Ombudsman Scheme) पेश की।', 'RBI introduced the ''Ombudsman Scheme'' for Non-Banking Financial Companies (NBFCs) on Feb 23, 2018.', 'NBFC के ग्राहकों की शिकायत = 2018 का लोकपाल।', 'NBFC customer complaints = 2018 Ombudsman.', '2021 में RBI ने सभी लोकपाल योजनाओं (बैंक, NBFC, डिजिटल लेनदेन) को मिलाकर ''One Nation One Ombudsman'' (एकीकृत लोकपाल) योजना बना दी है।', 'In 2021, RBI merged all ombudsman schemes (Banks, NBFCs, Digital) into the ''One Nation One Ombudsman'' (Integrated Ombudsman) scheme.', 'medium', 0.8, 0.88, '[{"questionId":"B8oxAyXPK1vFajAtppV2M"}]', '["Banking Reforms","RBI"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829511, 1773829511);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('04756cba-abd4-4f79-8b0d-eefb8ec46d68', '1087cbe2-4923-435a-85e0-70cb2b60a5a2', 'Economy', '750 मेगावाट का ''रीवा अल्ट्रा मेगा सोलर पावर प्लांट'' (Rewa Ultra Mega Solar Power Plant) मध्य प्रदेश के रीवा जिले (गुढ़ तहसील) में स्थित है।', 'The 750 MW ''Rewa Ultra Mega Solar Power Plant'' is located in Rewa district (Gurh tehsil) of Madhya Pradesh.', 'रीवा की रे (Ray) से 750 MW बिजली (Delhi Metro को 24%)।', '750 MW electricity from Rewa''s Ray (24% to Delhi Metro).', 'ओंकारेश्वर में 600 MW का ''तैरता हुआ'' (Floating) सोलर प्लांट बन रहा है, दोनों में अंतर रखें।', 'A 600 MW ''floating'' solar plant is being built in Omkareshwar, keep the difference in mind.', 'medium', 0.94, 0.96, '[{"questionId":"Cfp-apiJUTkNoDIt26Atf"}]', '["Renewable Energy","MP Economy"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829511, 1773829511);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9a6b8865-958e-4f5c-831d-e33ca35b1baa', '18d03bac-878b-4d89-8e52-63eb0435aa3b', 'ICT', 'करेंट अफेयर्स: 1 फरवरी 2021 को म्यांमार में सेना (टाटमाडॉ) ने तख्तापलट किया। चौरी-चौरा शताब्दी समारोह (1922-2022) 4 फरवरी 2021 को शुरू हुआ। भारत-नॉर्वे ने ''नीली अर्थव्यवस्था'' (Blue Economy) टास्क फोर्स बनाई।', 'Current Affairs: Military coup in Myanmar on Feb 1, 2021. Chauri Chaura Centenary (1922-2022) began on Feb 4, 2021. India-Norway formed a ''Blue Economy'' Task Force.', 'M-M (Myanmar Military)। नॉर्वे की नीली लहर (Norway''s Blue Wave)।', 'M-M (Myanmar Military). Norway''s Blue Wave.', 'चौरी-चौरा की घटना असहयोग आंदोलन (Non-Cooperation) से जुड़ी है, सविनय अवज्ञा से नहीं।', 'Chauri Chaura incident is linked to the Non-Cooperation Movement, not Civil Disobedience.', 'medium', 0.8, 0.88, '[{"questionId":"W6Sn8-Jp6OartTmV0c1Cl"},{"questionId":"abwJMFQO-3DTKRxFDt_bR"},{"questionId":"dkVIO7X30onZZIhf9pmjZ"}]', '["International Events","Bilateral Ties","Historical Anniversaries"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829514, 1773829514);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0764250c-3234-4ba0-8248-99fe7ddc4d5b', '18d03bac-878b-4d89-8e52-63eb0435aa3b', 'ICT', 'कंप्यूटर बेसिक्स: RAM एक ''प्राथमिक'' (Primary) मेमोरी है (अस्थिर/Volatile)। IPv6 पते 128-बिट के होते हैं (IPv4 32-बिट के थे)।', 'Computer Basics: RAM is a ''Primary'' memory (Volatile). IPv6 addresses are 128-bit (IPv4 was 32-bit).', 'RAM = बिजली गई, डेटा गया (Volatile)। 6 का मतलब बड़ा (128-bit)।', 'RAM = Power gone, data gone (Volatile). 6 means huge (128-bit).', 'ROM भी प्राथमिक मेमोरी है, लेकिन वह गैर-वाष्पशील (Non-volatile) है। हार्ड डिस्क, SSD ''माध्यमिक'' (Secondary) हैं।', 'ROM is also primary memory, but it is Non-volatile. Hard disks, SSDs are ''Secondary''.', 'medium', 0.92, 0.95, '[{"questionId":"-N0LulP-Eq4vUNs7B29vE"},{"questionId":"VFcnNs2XUXz-Ff2aab60E"}]', '["Computer Memory","Networking"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829514, 1773829514);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('09e755c9-7831-4c67-9ce5-bf77986e0d5c', '18d03bac-878b-4d89-8e52-63eb0435aa3b', 'ICT', 'साइबर सुरक्षा/नेटवर्क: ''स्पूफिंग'' (Spoofing) में पहचान छिपाई जाती है (नकली ईमेल)। ''वर्चुअल कीबोर्ड'' कीलॉगर्स से बचाते हैं। ''ब्लोफिश'' (Blowfish) एक सिमेट्रिक-की एन्क्रिप्शन साइफर है।', 'Cyber Sec/Network: In ''Spoofing'', identity is hidden (fake email). ''Virtual Keyboards'' protect against keyloggers. ''Blowfish'' is a symmetric-key encryption cipher.', 'स्पूफ = भेष बदलना। ब्लोफिश = सेम की (Symmetric Key)।', 'Spoof = Disguise. Blowfish = Same key (Symmetric Key).', 'असममित (Asymmetric) एन्क्रिप्शन में पब्लिक और प्राइवेट दो अलग-अलग keys होती हैं (जैसे RSA)।', 'Asymmetric encryption has two different keys: Public and Private (like RSA).', 'medium', 0.85, 0.9, '[{"questionId":"Hcv_7FGGlbLQwH7bqq_Yn"},{"questionId":"477yzv9RQZ33D3Iq2uVVi"},{"questionId":"6QpaNiu7zj1N2FS8mgktn"}]', '["Cyber Security","Cryptography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829514, 1773829514);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('89520f3e-6a33-47f7-b8a0-a410d573a78f', '18d03bac-878b-4d89-8e52-63eb0435aa3b', 'ICT', 'वेब तकनीक: ''सहयोगात्मक फिल्टरिंग'' (Collaborative Filtering) अमेज़ॅन जैसी साइटों पर सुझाव (Recommendations) देने की तकनीक है। XML का अर्थ ''Extensible Markup Language'' है।', 'Web Tech: ''Collaborative Filtering'' is the recommendation tech used on sites like Amazon. XML stands for ''Extensible Markup Language''.', 'सहयोग से अनुमान लगाना (Guessing together = Collaborative filtering)। XML = eXtensible.', 'Guessing together = Collaborative filtering. XML = eXtensible.', 'HTML वेब पेज का ढांचा बनाता है, जबकि XML डेटा ले जाने (Transport) का काम करता है।', 'HTML structures the web page, while XML transports the data.', 'medium', 0.8, 0.85, '[{"questionId":"xv-GXhdJ9WBNt-NKCDYqA"},{"questionId":"ULZVatZQgIe6JGuQfHbgO"}]', '["AI Algorithms","Web Languages"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829514, 1773829514);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3b31b747-be00-4169-8416-b275e12cc4f7', '18d03bac-878b-4d89-8e52-63eb0435aa3b', 'ICT', 'रोबोटिक्स/ई-गवर्नेंस: ''PUMA'' (Programmable Universal Machine for Assembly) एक रोबोटिक आर्म है। गार्टनर ई-गवर्नेंस मॉडल: सूचना -> सहभागिता -> लेन-देन -> परिवर्तन।', 'Robotics/E-Gov: ''PUMA'' is a robotic arm. Gartner E-Gov model: Information -> Interaction -> Transaction -> Transformation.', 'PUMA रोबोट (Assembly के लिए)। I-I-T-T (गार्टनर के 4 चरण)।', 'PUMA robot (for Assembly). I-I-T-T (Gartner''s 4 stages).', 'PUMA जूतों का ब्रांड है, लेकिन रोबोटिक्स में यह एक ''यूनिवर्सल मशीन'' (Universal Machine) है।', 'PUMA is a shoe brand, but in robotics, it''s a ''Universal Machine''.', 'medium', 0.82, 0.88, '[{"questionId":"2Z2VI-XMxRc3KHvXFHAMu"},{"questionId":"x29Pm0pZUsh1kopyt5rUe"}]', '["Robotics","E-Governance"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829514, 1773829514);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('42227e9a-aea7-40fa-b13a-a7aca4a7b61b', '3b34af96-13e9-4955-bdc4-2c2604bbe1d9', 'Science', 'राष्ट्रीय विषाणु-विज्ञान संस्थान (NIV) पुणे (महाराष्ट्र) में स्थित है। कोरोना वायरस से MERS (2012), SARS (2003) और COVID-19 (2019) जैसी बीमारियां होती हैं।', 'The National Institute of Virology (NIV) is located in Pune (Maharashtra). Corona viruses cause diseases like MERS (2012), SARS (2003), and COVID-19 (2019).', 'वायरस की लैब = पुणे (V-P)। कोरोना के 3 रूप (SARS, MERS, COVID)।', 'Virus Lab = Pune (V-P). 3 forms of Corona (SARS, MERS, COVID).', 'सीरम इंस्टीट्यूट (Serum Institute) भी पुणे में है (जिसने कोविशील्ड बनाई), जबकि भारत बायोटेक (कोवैक्सिन) हैदराबाद में है।', 'Serum Institute is also in Pune (made Covishield), while Bharat Biotech (Covaxin) is in Hyderabad.', 'medium', 0.9, 0.95, '[{"questionId":"Qzt1EdIO5I9eDF_cTQVyx"},{"questionId":"OGaqlbIM7DFexAUjz9t5r"}]', '["Institutes","Viral Diseases"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829516, 1773829516);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('147a3f9a-f6f0-4d47-9004-10789a596934', '3b34af96-13e9-4955-bdc4-2c2604bbe1d9', 'Science', 'मानव शरीर में 12 जोड़ी ''कपाल तंत्रिकाएं'' (Cranial Nerves) और 31 जोड़ी ''मेरु तंत्रिकाएं'' (Spinal Nerves) होती हैं।', 'The human body has 12 pairs of ''Cranial Nerves'' and 31 pairs of ''Spinal Nerves''.', 'कपाल छोटा (12), रीढ़ की हड्डी लंबी (31)। (Brain is small 12, Spine is long 31).', 'Brain is small (12), Spine is long (31).', '12 और 31 के आंकड़े को आपस में न बदलें (12 Cranial, 31 Spinal)। पसलियां (Ribs) भी 12 जोड़ी होती हैं।', 'Do not swap the figures 12 and 31 (12 Cranial, 31 Spinal). Ribs are also 12 pairs.', 'medium', 0.88, 0.92, '[{"questionId":"4m2OhTpFgJnrXnIOYohCE"}]', '["Nervous System","Human Anatomy"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829516, 1773829516);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('72a8824b-2998-4af8-af0e-46fd7550477c', '3b34af96-13e9-4955-bdc4-2c2604bbe1d9', 'Science', 'जेनेटिक कोड सार्वत्रिक (Universal) होता है, 3 न्यूक्लियोटाइड क्षारकों (Triplet) का बना होता है, और इसमें एक प्रारम्भन (Start) व एक समापन (Stop) कोडॉन होता है।', 'Genetic code is Universal, made of 3 nucleotide bases (Triplet), and has one Start and one Stop codon.', 'डीएनए का कोड = 3 अक्षरों का ''यूनिवर्सल'' पासवर्ड। (AUG शुरू, UAA खत्म)।', 'DNA code = 3 letter ''Universal'' password. (AUG start, UAA stop).', 'सभी जीवों (बैक्टीरिया से इंसान तक) में जेनेटिक कोड लगभग समान होता है, इसलिए इसे ''सार्वत्रिक'' कहा जाता है।', 'The genetic code is nearly identical in all organisms (from bacteria to humans), hence it''s called ''Universal''.', 'medium', 0.8, 0.88, '[{"questionId":"H9K19p6YFmeW0f5zVinwB"}]', '["Genetics","Biology"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829516, 1773829516);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3b13e0c5-a5c4-42a4-aa34-e3cb83b64869', '3b34af96-13e9-4955-bdc4-2c2604bbe1d9', 'Science', 'माइक्रोवेव (Microwaves) की आवृत्ति (Frequency) सीमा 1 GHz से 300 GHz के बीच होती है।', 'The frequency range of Microwaves is between 1 GHz and 300 GHz.', 'Giga = Great frequency (Microwaves)।', 'Giga = Great frequency (Microwaves).', 'तरंगदैर्ध्य (Wavelength) और आवृत्ति (Frequency) एक-दूसरे के विपरीत (Inversely proportional) होते हैं। माइक्रोवेव रेडियो तरंगों से छोटी, लेकिन इन्फ्रारेड से बड़ी होती हैं।', 'Wavelength and Frequency are inversely proportional. Microwaves are shorter than radio waves, but longer than infrared.', 'medium', 0.75, 0.85, '[{"questionId":"ARj5ADPyx5gEsTe-46ihC"}]', '["Electromagnetic Spectrum","Physics"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829516, 1773829516);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('fb80aa22-d58a-4eb5-8ac4-719fb70a5b60', '3b34af96-13e9-4955-bdc4-2c2604bbe1d9', 'Science', 'योजनाएं: ''जननी सुरक्षा योजना'' का मुख्य उद्देश्य संस्थागत प्रसव (Institutional Delivery) को बढ़ावा देना है। ''आकांक्षा योजना'' (MP) ST छात्रों को मुफ़्त कोचिंग (JEE/NEET) देती है।', 'Schemes: The main objective of ''Janani Suraksha Yojana'' is to promote Institutional Delivery. ''Akanksha Yojana'' (MP) provides free coaching (JEE/NEET) to ST students.', 'जननी (मां) सुरक्षित अस्पताल में (Hospital Delivery)। आकांक्षा = ST बच्चों के सपने (JEE/NEET)।', 'Mother safe in hospital (Hospital Delivery). Akanksha = Dreams of ST kids (JEE/NEET).', 'आकांक्षा योजना केवल ''आदिवासी'' (ST) छात्रों के लिए है, सभी के लिए नहीं।', 'Akanksha Yojana is ONLY for ''Tribal'' (ST) students, not for all.', 'medium', 0.9, 0.94, '[{"questionId":"sj-KRAV_cEo1TpUW1H_4f"},{"questionId":"9A5jTNos9-70UzItvi0og"}]', '["Health Schemes","Welfare Schemes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829516, 1773829516);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9aab9c76-a11f-4efb-b9c8-a06502adb0f1', '3b34af96-13e9-4955-bdc4-2c2604bbe1d9', 'Science', '''व्योमित्र'' (Vyommitra) इसरो द्वारा विकसित एक ''अर्ध-मानवीय महिला रोबोट'' (Half-humanoid) है (गगनयान के लिए)। ''रत्ना'' आम की किस्म (नीलम + अल्फांसो) का क्रॉस है। MSG (अजीनोमोटो) स्वाद बढ़ाता है।', '''Vyommitra'' is a ''half-humanoid female robot'' developed by ISRO (for Gaganyaan). ''Ratna'' is a crossbreed of mango (Neelum + Alphonso). MSG (Ajinomoto) is a flavor enhancer.', 'व्योम (Space) का मित्र (Friend) = ISRO रोबोट। N-A-R (Neelum + Alphonso = Ratna)।', 'Friend of Space = ISRO robot. N-A-R (Neelum + Alphonso = Ratna).', 'रत्ना और अल्फांसो का क्रॉस ''सिंधु'' (बीजरहित आम) बनाता है। कृषि संकर (Hybrids) MPPSC में अक्सर पूछे जाते हैं।', 'The cross of Ratna and Alphonso creates ''Sindhu'' (seedless mango). Agriculture hybrids are frequently asked in MPPSC.', 'medium', 0.88, 0.9, '[{"questionId":"387BZIVfA4ZfXFNWMsrx_"},{"questionId":"8pANe6RwgFOxAA6SG4dqO"},{"questionId":"vr1o_TBo0JCBipvDclqpG"}]', '["Space Tech","Agriculture","Food Tech"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829516, 1773829516);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('1c84a0a3-f3e4-4013-adf9-232835e41e97', 'd277c8b3-99cb-43a5-a353-b880a4d91575', 'MP GK', 'नीति आयोग की रिपोर्ट (2023) के अनुसार, MP के ''अलीराजपुर'' जिले ने बहुआयामी गरीबी (Multidimensional Poverty) कम करने में सबसे अधिक सुधार दर्ज किया।', 'According to NITI Aayog''s report (2023), MP''s ''Alirajpur'' district recorded the highest improvement in reducing Multidimensional Poverty.', 'अलीराजपुर सबसे गरीब था, इसलिए उसने सबसे ज्यादा सुधार भी किया।', 'Alirajpur was the poorest, so it made the most improvement too.', 'अलीराजपुर साक्षरता (2011) में सबसे नीचे है, लेकिन गरीबी कम करने के ''सुधार'' (Improvement rate) में सबसे आगे रहा (2023 डेटा)।', 'Alirajpur is at the bottom in literacy (2011), but led in the ''improvement rate'' of reducing poverty (2023 data).', 'medium', 0.9, 0.95, '[{"questionId":"S_rt41KF4-rwx_APg8vK0"}]', '["MP Economy","NITI Aayog Reports"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829522, 1773829522);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9240f995-ac70-4d9a-96b9-981ff57b42e9', 'd277c8b3-99cb-43a5-a353-b880a4d91575', 'MP GK', 'जमशेद जे. ईरानी को ''भारत का इस्पात पुरुष'' (Steel Man of India) कहा जाता है (वे टाटा स्टील के एमडी थे, 2022 में निधन)।', 'Jamshed J. Irani is called the ''Steel Man of India'' (He was MD of Tata Steel, died in 2022).', 'ईरानी = इस्पात (Irani = Ispat/Steel)।', 'Irani = Ispat/Steel.', 'लक्ष्मी मित्तल या रतन टाटा को टिक न करें, यह एक विशिष्ट उपाधि है जो जे.जे. ईरानी को दी गई थी।', 'Do not tick Lakshmi Mittal or Ratan Tata; this is a specific title given to J.J. Irani.', 'medium', 0.85, 0.88, '[{"questionId":"Gn9ovug_bVGFCN8qX85-I"}]', '["Personalities","Industry"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829522, 1773829522);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('f4e88bea-0857-4bc2-85fa-bab40fda3235', 'd277c8b3-99cb-43a5-a353-b880a4d91575', 'MP GK', 'सहरिया (Sahariya) जनजाति (उत्तरी MP) के मुखिया को सम्मानपूर्वक ''खुटिया पटेल'' कहा जाता है।', 'The head of the Sahariya tribe (Northern MP) is respectfully called ''Khutiya Patel''.', 'सहरिया का पटेल = खुटिया पटेल।', 'Sahariya''s Patel = Khutiya Patel.', 'सहरिया, बैगा और भारिया मध्य प्रदेश की तीन ''विशेष पिछड़ी जनजातियां'' (PVTGs) हैं। उनके सांस्कृतिक शब्दों पर गहराई से प्रश्न आते हैं।', 'Sahariya, Baiga, and Bharia are the three PVTGs of MP. Deep questions are asked on their cultural terms.', 'medium', 0.88, 0.92, '[{"questionId":"oHJAjc4obj5z97Peokq-8"}]', '["Tribes of MP","Cultural Terms"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829522, 1773829522);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('cfa43f2c-0bcc-4275-a0e1-07bf719d73d4', 'd277c8b3-99cb-43a5-a353-b880a4d91575', 'MP GK', 'BRAP (बिजनेस रिफॉर्म एक्शन प्लान) 2020 की रैंकिंग में मध्य प्रदेश ''Achievers'' (अचीवर्स) श्रेणी में था (Top Achievers में नहीं)।', 'In the BRAP (Business Reform Action Plan) 2020 rankings, Madhya Pradesh was in the ''Achievers'' category (not Top Achievers).', 'MP अचीवर (Achiever) है।', 'MP is an Achiever.', 'ईज ऑफ डूइंग बिजनेस (EoDB) रिपोर्ट में राज्यों की श्रेणियां (Top Achievers, Achievers, Aspirers) याद रखें।', 'Remember the categories of states (Top Achievers, Achievers, Aspirers) in the Ease of Doing Business (EoDB) report.', 'medium', 0.75, 0.85, '[{"questionId":"l81UoTjkkFil_YJVuoNp9"}]', '["EoDB Rankings","Economy"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829522, 1773829522);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4cc31ac6-fc4b-4b51-a01f-e39ceea0934a', 'd277c8b3-99cb-43a5-a353-b880a4d91575', 'MP GK', 'कृषि पद्धतियों का सही क्रम: मिट्टी तैयार करना -> बुआई (Sowing) -> सिंचाई (Irrigation) -> कटाई (Harvesting)।', 'Correct sequence of agricultural practices: Soil preparation -> Sowing -> Irrigation -> Harvesting.', 'पहले जमीन (मिट्टी), फिर बीज (बुआई), फिर पानी (सिंचाई), अंत में फल (कटाई)।', 'First land (soil), then seed (sowing), then water (irrigation), finally fruit (harvest).', 'यह एक बुनियादी समझ (Common Sense) का प्रश्न था, लेकिन जल्दबाजी में गलत हो सकता है।', 'It was a basic common sense question, but can go wrong in haste.', 'medium', 0.7, 0.8, '[{"questionId":"XkALargoSdhXy3wQaLDjt"}]', '["Agriculture Basics"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829522, 1773829522);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('04fa4613-bed4-44cb-a494-2858da59a9ff', 'd277c8b3-99cb-43a5-a353-b880a4d91575', 'MP GK', 'ऑस्टियोक्लास्ट (Osteoclasts) कोशिकाएं ''हड्डी'' (Bone) को तोड़ने/घोलने से संबंधित हैं (हड्डी की मरम्मत के दौरान)। राष्ट्रीय मौखिक स्वास्थ्य कार्यक्रम (Oral Health) पोषण से नहीं, बल्कि दांतों की स्वच्छता से जुड़ा है।', 'Osteoclasts cells are related to breaking down/resorbing ''Bone'' (during bone repair). National Oral Health Program is related to dental hygiene, not nutrition.', 'ऑस्टियो = हड्डी (Osteo = Bone)।', 'Osteo = Bone.', 'ऑस्टियोब्लास्ट (Osteoblast) हड्डी ''बनाते'' हैं, जबकि ऑस्टियोक्लास्ट (Osteoclast) हड्डी ''तोड़ते'' (Remodeling के लिए) हैं।', 'Osteoblasts ''build'' bone, while Osteoclasts ''break'' bone (for remodeling).', 'medium', 0.85, 0.9, '[{"questionId":"FpKva_dOyYQvuxeXT7TwD"},{"questionId":"iMEpCcfv3gjHiOVrCDxLL"}]', '["Human Anatomy","Health Programs"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773829522, 1773829522);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('adaa35f5-2fe8-49fa-88ce-d0242379b9ad', '0e7ae3b5-e91c-4d8b-9901-1637cb7feff8', 'MP GK', '2011 की जनगणना: मध्य प्रदेश में सबसे कम लिंगानुपात (Sex Ratio) ''भिंड'' (837) जिले में है। न्यूनतम जनसंख्या घनत्व (Population Density) ''डिंडौरी'' (94) में है।', '2011 Census: MP has the lowest sex ratio in ''Bhind'' (837) district. The lowest population density is in ''Dindori'' (94).', 'लिंगानुपात में भिंड सबसे नीचे, घनत्व में डिंडौरी।', 'Bhind at bottom in sex ratio, Dindori in density.', 'सबसे अधिक लिंगानुपात बालाघाट (1021) में है और सबसे अधिक घनत्व भोपाल (855) में है। इन 4 जिलों को रट लें।', 'Highest sex ratio is in Balaghat (1021) and highest density in Bhopal (855). Rote learn these 4 districts.', 'medium', 0.98, 0.99, '[{"questionId":"Aj-ccQTa1R-1zqdxRCSUv"},{"questionId":"VdUFzs_umeUrd_lh3Hs9E"}]', '["MP Census 2011","Demography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842049, 1773842049);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c6e84026-7e62-48bd-b9f4-9c4e6f5423fd', '0e7ae3b5-e91c-4d8b-9901-1637cb7feff8', 'MP GK', 'इंदिरा गांधी राष्ट्रीय जनजातीय विश्वविद्यालय (IGNTU) अमरकंटक (अनूपपुर) में स्थित है।', 'Indira Gandhi National Tribal University (IGNTU) is located in Amarkantak (Anuppur).', 'जनजातियों का विकास अमरकंटक से (Tribal university in Amarkantak)।', 'Tribal university in Amarkantak.', 'यह एक ''केंद्रीय विश्वविद्यालय'' (Central University) है। इसे भोपाल या जबलपुर में न मानें।', 'It is a ''Central University''. Do not assume it is in Bhopal or Jabalpur.', 'medium', 0.9, 0.95, '[{"questionId":"wguCJiSDmXQTenzbOY_8a"}]', '["Universities","Tribal Education"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842049, 1773842049);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('9e19c17b-70c2-4035-8122-040bad9842b1', '0e7ae3b5-e91c-4d8b-9901-1637cb7feff8', 'MP GK', 'बैगा विकास अभिकरण मंडला, डिंडौरी, शहडोल और बालाघाट में हैं, ''रायसेन'' में नहीं।', 'Baiga Development Agencies are in Mandla, Dindori, Shahdol, and Balaghat, NOT in ''Raisen''.', 'बैगा (Baiga) दक्षिण-पूर्व (South-East) में हैं, मध्य (Raisen) में नहीं।', 'Baiga are in South-East, not in Central (Raisen).', 'सहरिया, बैगा और भारिया मध्य प्रदेश की तीन ''विशेष पिछड़ी जनजातियां'' (PVTGs) हैं। उनके क्षेत्रों को अच्छी तरह से मैप करें।', 'Sahariya, Baiga, and Bharia are the three PVTGs of MP. Map their regions well.', 'medium', 0.88, 0.9, '[{"questionId":"bQQ38PR9j2kGGpdSPiqjn"}]', '["Tribal Agencies","PVTGs"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842049, 1773842049);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('00e79e50-797e-4043-b54a-c39e8808f61a', 'c8990844-2e2e-4034-b4d3-ed2c80dece76', 'MP GK', 'तीर्थस्थल ''ओंकारेश्वर'' (खंडवा जिला) का प्राचीन नाम ''मांधाता'' (Mandhata) था।', 'The ancient name of the pilgrimage site ''Omkareshwar'' (Khandwa dist) was ''Mandhata''.', 'मांधाता पर्वत पर ओंकार (Omkar on Mandhata mountain)।', 'Omkar on Mandhata mountain.', 'उज्जैन का प्राचीन नाम अवंतिका था और सांची का काकनाद।', 'Ujjain''s ancient name was Avantika and Sanchi''s was Kakanad.', 'medium', 0.88, 0.9, '[{"questionId":"03ZWET1kCIg-MaaWctm4q"}]', '["Ancient Names","Pilgrimage"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842050, 1773842050);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('35c5baa8-2bb9-41b4-8ea7-8700499c7644', 'c8990844-2e2e-4034-b4d3-ed2c80dece76', 'MP GK', 'भोपाल गैस त्रासदी 2-3 दिसंबर 1984 की रात को हुई थी (यूनियन कार्बाइड फैक्ट्री, MIC गैस)।', 'Bhopal Gas Tragedy occurred on the night of Dec 2-3, 1984 (Union Carbide factory, MIC gas).', '1984 का काला दिसंबर (Black December of 1984)।', 'Black December of 1984.', 'गैस का नाम मिथाइल आइसोसाइनेट (MIC) था, मिथाइल साइनाइड नहीं।', 'The gas name was Methyl Isocyanate (MIC), not Methyl Cyanide.', 'medium', 0.9, 0.95, '[{"questionId":"cfxyXj-p3hmMRa44Om-U9"}]', '["MP History","Disasters"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842050, 1773842050);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6613ecb4-17cc-4fdf-96b4-36115d37204e', 'c8990844-2e2e-4034-b4d3-ed2c80dece76', 'MP GK', 'मध्य प्रदेश लोक सेवा आयोग (MPPSC) में नियमों के अनुसार अधिकतम ''पाँच'' (5) सदस्य हो सकते हैं (अध्यक्ष सहित)।', 'As per rules, the Madhya Pradesh Public Service Commission (MPPSC) can have a maximum of ''five'' (5) members (including the Chairman).', 'MPPSC में 5 लोग (1 अध्यक्ष + 4 सदस्य)।', '5 people in MPPSC (1 Chair + 4 members).', 'UPSC में सदस्यों की संख्या (9 से 11) अलग होती है। राज्य PSC की संख्या राज्यपाल तय करता है।', 'UPSC member count (9 to 11) is different. State PSC count is decided by the Governor.', 'medium', 0.8, 0.88, '[{"questionId":"0MrvSnLhub9xIzCySGhMp"}]', '["State Commissions","MP Polity"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842050, 1773842050);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e3e746d5-c118-470f-a0dd-485bad10a596', 'c8990844-2e2e-4034-b4d3-ed2c80dece76', 'MP GK', 'भारतीय रियासतों के शासकों को मिलने वाले विशेष अधिकार और ''प्रिवी पर्स'' (Privy Purse) को 26वें संविधान संशोधन अधिनियम, 1971 द्वारा समाप्त कर दिया गया था।', 'The special privileges and ''Privy Purse'' given to the rulers of Indian princely states were abolished by the 26th Constitutional Amendment Act, 1971.', 'इंदिरा गांधी का 1971 का कड़ा कदम = प्रिवी पर्स खत्म।', 'Indira Gandhi''s strict step in 1971 = Privy Purse abolished.', 'यह एक बड़ा राजनीतिक सुधार था। इसे 42वें संशोधन (1976) से न मिलाएं।', 'This was a major political reform. Do not mix it with the 42nd Amendment (1976).', 'medium', 0.88, 0.95, '[{"questionId":"JAjBId53VYdLp7OmWhoJT"}]', '["Constitutional Amendments","Post-Independence History"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842050, 1773842050);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c347de06-c820-41ce-8fed-fd8cd885ec23', 'bcbeaad7-e11e-49e8-8098-4fd78df83997', 'MP GK', 'कान्हा राष्ट्रीय उद्यान (MP) भारत का पहला टाइगर रिजर्व है जिसने ''भूरसिंह द बारासिंघा'' नामक आधिकारिक शुभंकर (Mascot) जारी किया (2017)।', 'Kanha National Park (MP) is the first tiger reserve in India to release an official mascot named ''Bhoorsingh the Barasingha'' (2017).', 'कान्हा का भूरसिंह (Bhoorsingh of Kanha)।', 'Bhoorsingh of Kanha.', 'बारासिंघा (Hard ground swamp deer) मध्य प्रदेश का राजकीय पशु है, जो केवल कान्हा में पाया जाता है।', 'Barasingha (Hard ground swamp deer) is the state animal of MP, found ONLY in Kanha.', 'medium', 0.92, 0.98, '[{"questionId":"-ie4yBXqsOwmR6iDizzgW"}]', '["National Parks","Wildlife Conservation"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842052, 1773842052);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3c61f253-efcb-451f-82b1-a53288decdc8', 'bcbeaad7-e11e-49e8-8098-4fd78df83997', 'MP GK', 'खनिज उत्पादन: बालाघाट में ''मैंगनीज'' (भरवेली) और तांबे (मलंजखंड) के सबसे बड़े भंडार हैं। कोयला उत्पादन में MP का भारत में तीसरा/चौथा स्थान है।', 'Mineral Production: Balaghat has the largest reserves of ''Manganese'' (Bharveli) and Copper (Malanjkhand). MP ranks 3rd/4th in Coal production in India.', 'बालाघाट = मैंगनीज की खान (भरवेली)।', 'Balaghat = Manganese mine (Bharveli).', 'लौह अयस्क (Iron ore) उत्पादन में MP शीर्ष 3 में नहीं है (ओडिशा, छत्तीसगढ़ आगे हैं)। कथन आधारित प्रश्नों में यह एक क्लासिक ट्रैप है।', 'MP is NOT in the top 3 in Iron ore production (Odisha, CG lead). This is a classic trap in statement-based questions.', 'medium', 0.9, 0.95, '[{"questionId":"px-9rxrHi0vNDIg882EYc"},{"questionId":"0-gKfji7XZ2OBDPHhIWu0"},{"questionId":"cF8LcSBCwKmU5wFGO3Up7"},{"questionId":"uCZ4PZbWtWDDpO49Iusex"}]', '["Minerals","Economic Geography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842052, 1773842052);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('8347817a-2652-4adf-9d3f-590b16a39393', 'bcbeaad7-e11e-49e8-8098-4fd78df83997', 'MP GK', 'भूगोल/मिट्टी: मालवा पठार में गहरी काली मिट्टी है। बघेलखंड में लाल-पीली मिट्टी है। उत्तरी-पश्चिमी भाग (भिंड/मुरैना) में जलोढ़ (Alluvial) मिट्टी पाई जाती है।', 'Geography/Soils: Malwa plateau has deep black soil. Baghelkhand has red-yellow soil. North-western part (Bhind/Morena) has Alluvial soil.', 'मालवा = काली (कपास)। बघेलखंड = लाल-पीली (चावल)। भिंड = जलोढ़ (नदियाँ)।', 'Malwa = Black (Cotton). Baghelkhand = Red-yellow (Rice). Bhind = Alluvial (Rivers).', 'लाल-पीली मिट्टी की उर्वरता (Fertility) कम होती है, अधिक नहीं। यह कथन वाले प्रश्नों में फंसाता है।', 'The fertility of red-yellow soil is LOW, not high. This traps you in statement-based questions.', 'medium', 0.88, 0.92, '[{"questionId":"2lnnMjMYy6OXqZqKOB0IB"}]', '["Soils of MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842053, 1773842053);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('cf99ae08-ddce-46fa-958a-5755cf3ccc1a', 'bcbeaad7-e11e-49e8-8098-4fd78df83997', 'MP GK', 'सिंचाई एवं नदियाँ: MP में सिंचाई का प्रमुख साधन ''कुएँ और नलकूप'' (Wells/Tube wells - ~67%) हैं। बीना नदी, बेतवा की सहायक नदी है। सुक्ता सिंचाई परियोजना खंडवा में है (बैतूल में नहीं)।', 'Irrigation & Rivers: The main source of irrigation in MP is ''Wells and Tube wells'' (~67%). Bina river is a tributary of Betwa. Sukta irrigation project is in Khandwa (not Betul).', 'MP में सबसे ज्यादा खेती बोरवेल (नलकूप) से होती है।', 'Most farming in MP is done via borewells (Tube wells).', 'नहरें (Canals) सिंचाई का दूसरा सबसे बड़ा साधन हैं। बीना नदी पर सागर में ''भालकुंड जलप्रपात'' है।', 'Canals are the second largest source of irrigation. The ''Bhalkund Waterfall'' is on the Bina river in Sagar.', 'medium', 0.85, 0.88, '[{"questionId":"c27C2LFx8bcDiqLCLRl_w"},{"questionId":"rrh70jcRe2bLUayvRLEPu"},{"questionId":"FDFObgLh96KJc1puPMvyo"}]', '["Irrigation","Rivers of MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842053, 1773842053);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('8ab82402-12c2-4932-b2ec-a3d8781602e9', 'bcbeaad7-e11e-49e8-8098-4fd78df83997', 'MP GK', 'भौगोलिक तथ्य: नर्मदा नदी अखरानी और मथवार पहाड़ियों (बड़वानी/अलीराजपुर) के मध्य गहरी कन्दरा (Gorge) बनाती है। प्रतिशत के आधार पर श्योपुर (दिए गए विकल्पों में) में वन क्षेत्र सर्वाधिक है। भारतीय वन प्रबंधन संस्थान (IIFM) भोपाल में है।', 'Geographical Facts: Narmada river forms a deep gorge between Akhrani and Mathwar hills (Barwani/Alirajpur). Forest cover percentage is highest in Sheopur (among given options). Indian Institute of Forest Management (IIFM) is in Bhopal.', 'IIFM (मैनेजमेंट) भोपाल में।', 'IIFM (Management) in Bhopal.', 'उज्जैन में वन क्षेत्र प्रतिशत सबसे कम है। बालाघाट राज्य में सबसे ऊपर है, लेकिन विकल्पों में श्योपुर सही था।', 'Ujjain has the lowest forest cover percentage. Balaghat is top in the state, but Sheopur was correct among options.', 'medium', 0.8, 0.85, '[{"questionId":"jxCpluZZywZkOBnppCAOg"},{"questionId":"dGnvQoH3OWEB-R0iYzi1B"},{"questionId":"fMHwAciy98NpogrEDFDPi"}]', '["Forests","Topography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842053, 1773842053);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('2f3ffc90-6997-47a8-9dfb-a7e95dece3d9', 'bcbeaad7-e11e-49e8-8098-4fd78df83997', 'MP GK', 'जलवायु और कृषि: मध्य प्रदेश को 11 कृषि-जलवायु क्षेत्रों में बांटा गया है। बुरहानपुर कपास और केले के लिए प्रसिद्ध है। दक्षिण-पूर्वी MP (मंडला) में वर्षा अधिक होती है। उत्तरी क्षेत्र (मुरैना/दतिया) में अत्यधिक गर्मी पड़ती है।', 'Climate & Agri: MP is divided into 11 agro-climatic zones. Burhanpur is famous for cotton and banana. South-eastern MP (Mandla) receives higher rainfall. Northern region (Morena/Datia) experiences extreme heat.', 'MP के 11 कृषि जोन। बुरहानपुर का केला।', '11 Agro zones of MP. Banana of Burhanpur.', 'उत्तरी क्षेत्र में जलवायु ''महाद्वीपीय'' (Continental) होती है, जहाँ गर्मियों में तापमान कम नहीं रहता बल्कि बहुत अधिक बढ़ जाता है।', 'In the northern region, the climate is ''Continental'', where temperature in summer does not remain low but increases significantly.', 'medium', 0.88, 0.9, '[{"questionId":"vYAg77RWVVPjjAlWHaV2U"},{"questionId":"dVDTT3xRcUXXxi4J_qZhq"},{"questionId":"HwDkmOCjUsotj_llCNBvD"},{"questionId":"d9YnhOFvJP3-mhPizMbBc"},{"questionId":"xwntqy-FQhV_O1A1mzo79"}]', '["Agriculture","Climate of MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842053, 1773842053);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('98bbbae0-c484-4688-b8b3-a4703f986cbc', 'bcbeaad7-e11e-49e8-8098-4fd78df83997', 'MP GK', 'करेंट अफेयर्स और अन्य तथ्य: वायु की गति ''ऐनीमोमीटर'' (Anemometer) से मापी जाती है। ओंकारेश्वर में 600 MW का फ्लोटिंग सोलर प्रोजेक्ट है। एक जिला एक उत्पाद (ODOP) सूची: बालाघाट-कोदो कुटकी, बैतूल-सागौन, खरगोन-मिर्च। ग्लोबल इन्वेस्टर्स समिट 2023 ''इंदौर'' में आयोजित की गई।', 'Current Affairs & Other Facts: Wind speed is measured by ''Anemometer''. Omkareshwar has a 600 MW floating solar project. ODOP list: Balaghat-Kodo Kutki, Betul-Teak, Khargone-Chilli. Global Investors Summit 2023 was held in ''Indore''.', 'ओंकारेश्वर की लहरों पर सोलर। एनिमो = हवा।', 'Solar on Omkareshwar waves. Anemo = Wind.', 'ढोकरा कला एक ''धातु शिल्प'' (Metal craft) है, कपड़ा कला नहीं। निर्मल वर्मा पुरस्कार ''प्रवासी भारतीयों'' को दिया जाता है।', 'Dhokra art is a ''Metal craft'', not cloth art. Nirmal Verma Award is given to ''NRIs''.', 'medium', 0.9, 0.92, '[{"questionId":"UvmZC6Yk-qp7D371pKsL4"},{"questionId":"nuRxxaa8pa8q3JKy_KzEq"},{"questionId":"xwntqy-FQhV_O1A1mzo79"},{"questionId":"2hYLzai9-zS2Efssl65Gr"},{"questionId":"iPSCtg7IzzQ_YheY0jdiO"},{"questionId":"6LJi_M4HtwrmplU2KULJQ"}]', '["Current Affairs","ODOP","Renewable Energy","Art & Awards"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842053, 1773842053);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('8e386771-3cbc-4543-85a6-4fea13c88e31', '1467d5e6-325f-4656-aee7-1ac01c0eecef', 'ICT', 'जॉन मैक्कार्थी (John McCarthy) को ''कृत्रिम बुद्धिमत्ता'' (Artificial Intelligence) का जनक माना जाता है। AI में ''क्षमता'' (Ability) पक्षपात (Bias) का स्रोत नहीं है (डेटा और एल्गोरिदम होते हैं)।', 'John McCarthy is considered the father of ''Artificial Intelligence''. In AI, ''Ability'' is NOT a source of bias (Data and Algorithms are).', 'MacCarthy ने AI बनाया।', 'MacCarthy made AI.', 'एलन ट्यूरिंग को आधुनिक कंप्यूटर विज्ञान का जनक कहा जाता है (इमिटेशन गेम), AI शब्द मैक्कार्थी ने गढ़ा था।', 'Alan Turing is the father of modern computer science (Imitation Game), the term AI was coined by McCarthy.', 'medium', 0.9, 0.95, '[{"questionId":"BpetKlEAp5xfpSj2ILmhr"},{"questionId":"pl7GEcoVZT6KuRY41LjSI"}]', '["AI Basics","Founders"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842054, 1773842054);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('665b536a-cacd-4f8d-9242-eb02670444e2', '1467d5e6-325f-4656-aee7-1ac01c0eecef', 'ICT', 'ई-कॉमर्स: ''विश्वव्यापी पहुँच'' (Global Reach) व्यापार को सीमाओं के पार ले जाता है। नीलामी (Auction) मुख्य रूप से C2C मॉडल (जैसे eBay) में होती है। उपभोक्ता द्वारा कीमत तय करना C2B मॉडल है।', 'E-Commerce: ''Global Reach'' takes business across borders. Auctions are primarily in the C2C model (like eBay). Consumer setting the price is the C2B model.', 'Global Reach = पूरी दुनिया का बाजार। नीलामी (Auction) = C2C।', 'Global Reach = Whole world market. Auction = C2C.', 'अमेज़ॅन (Amazon) और फ्लिपकार्ट (Flipkart) B2C (Business-to-Consumer) मॉडल के उदाहरण हैं।', 'Amazon and Flipkart are examples of the B2C (Business-to-Consumer) model.', 'medium', 0.9, 0.94, '[{"questionId":"1pSmRh9Ud2Acsh9ufsIeT"}]', '["E-Commerce Models"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842054, 1773842054);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('867f8e69-be3c-41c6-8d9d-deed0f76559a', '1467d5e6-325f-4656-aee7-1ac01c0eecef', 'ICT', 'साइबर सुरक्षा/खतरे: ''स्पूफिंग'' (Spoofing) में पहचान छिपाई जाती है (नकली ईमेल)। ''फिशिंग'' (Phishing) में भ्रामक संदेशों से संवेदनशील जानकारी (पासवर्ड) चुराई जाती है। साइबर सुरक्षा में डेटा का बचाव, नियमों का अनुपालन (Compliance) और खतरों की रोकथाम शामिल है।', 'Cyber Sec/Threats: In ''Spoofing'', identity is hidden (fake email). In ''Phishing'', sensitive info (passwords) is stolen via deceptive messages. Cyber security includes data protection, compliance, and threat prevention.', 'स्पूफ = भेष बदलना (Disguise)। फिशिंग = मछली (यूजर) को चारा डालना।', 'Spoof = Disguise. Phishing = Baiting the fish (user).', 'स्पूफिंग फिशिंग का ही एक तकनीकी तरीका है (ईमेल का पता बदलना)। वर्चुअल कीबोर्ड कीलॉगर्स से बचाते हैं।', 'Spoofing is a technical method of Phishing (forging the email address). Virtual keyboards protect against keyloggers.', 'medium', 0.95, 0.98, '[{"questionId":"EwP-Ypl1ifZzwwigWn3ud"}]', '["Cyber Security","Malware & Attacks"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842054, 1773842054);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6d4e9f33-741c-454e-9526-6545430c54a4', '1467d5e6-325f-4656-aee7-1ac01c0eecef', 'ICT', 'नेटवर्किंग और वेब तकनीक: ई-गवर्नेन्स का सटीक अर्थ ''तकनीकी आधारित शासन'' (Technology driven governance) है। सोशल मीडिया अनुकूलन (SMO) का अर्थ है सोशल नेटवर्क द्वारा प्रचार करना।', 'Networking & Web Tech: The precise meaning of E-Governance is ''Technology driven governance''. Social Media Optimization (SMO) means publicity through social networks.', 'E-Gov = Tech + Govt। SMO = Social Media Publicity.', 'E-Gov = Tech + Govt. SMO = Social Media Publicity.', 'SEO (सर्च इंजन) और SMO (सोशल मीडिया) के बीच का अंतर स्पष्ट रखें।', 'Keep the difference between SEO (Search Engine) and SMO (Social Media) clear.', 'medium', 0.88, 0.92, '[{"questionId":"BpUVSAouNbuFxBCoimspI"},{"questionId":"m7fA05gPkes_rMS16VG5v"}]', '["E-Governance","Digital Marketing"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842054, 1773842054);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4a84c11b-d0b8-4435-ae63-726affac7c7c', '1467d5e6-325f-4656-aee7-1ac01c0eecef', 'ICT', 'रोबोटिक्स और अन्य तथ्य: ''PUMA'' (Programmable Universal Machine for Assembly) एक औद्योगिक रोबोटिक आर्म है। ''Cortesa'' कोई प्रसिद्ध वर्चुअल असिस्टेंट नहीं है (Siri, Alexa, Cortana हैं)। नौकरियों का जाना (Job displacement) रोबोटिक्स का नुकसान है, फायदा नहीं।', 'Robotics & Other Facts: ''PUMA'' is an industrial robotic arm. ''Cortesa'' is NOT a famous virtual assistant (Siri, Alexa, Cortana are). Job displacement is a disadvantage of robotics, not an advantage.', 'PUMA रोबोट (Assembly के लिए)।', 'PUMA robot (for Assembly).', 'PUMA जूतों का ब्रांड है, लेकिन रोबोटिक्स में यह एक ''यूनिवर्सल मशीन'' है।', 'PUMA is a shoe brand, but in robotics, it''s a ''Universal Machine''.', 'medium', 0.8, 0.85, '[{"questionId":"atpbj2UU9Cu4166Lcagze"},{"questionId":"lWGbCvlVvAnXrzE2f1ka5"}]', '["Robotics","AI Basics"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842054, 1773842054);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('dd2c151e-1ae1-4c7b-b300-ad4e2ce776aa', '22684ec7-7be4-469b-bd3c-9d67c5827dfa', 'Current Affairs', 'खाद्य और कृषि संगठन (FAO) का मुख्यालय रोम (इटली) में अवस्थित है।', 'The headquarters of the Food and Agriculture Organization (FAO) is located in Rome (Italy).', 'खाना (Food) = रोम (Rome)।', 'Food = Rome.', 'विश्व खाद्य कार्यक्रम (WFP) का मुख्यालय भी रोम में है।', 'The World Food Programme (WFP) HQ is also in Rome.', 'medium', 0.88, 0.92, '[{"questionId":"4kmFRv2Rj68Aqfi8tLax5"}]', '["UN Agencies","Headquarters"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842055, 1773842055);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('f2a13e4d-8b34-4ba7-b16c-b0d351426089', '22684ec7-7be4-469b-bd3c-9d67c5827dfa', 'Current Affairs', 'अन्तर्राष्ट्रीय ओलम्पिक समिति (IOC) का मुख्यालय लुसाने (Lausanne), स्विट्जरलैंड में स्थित है।', 'The headquarters of the International Olympic Committee (IOC) is located in Lausanne, Switzerland.', 'ओलंपिक की शान ''लुसाने'' में।', 'Olympic pride in ''Lausanne''.', 'जिनेवा (Geneva) में कई मुख्यालय हैं (WHO, WTO), लेकिन IOC लुसाने में है।', 'Geneva has many HQs (WHO, WTO), but IOC is in Lausanne.', 'medium', 0.9, 0.95, '[{"questionId":"o8pZUDMth-cqlq7vdBgGT"}]', '["International Organizations","Sports HQ"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842055, 1773842055);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('7505b35d-6912-4762-9c50-33ac25806ef9', '22684ec7-7be4-469b-bd3c-9d67c5827dfa', 'Current Affairs', 'कर्नम मल्लेश्वरी (Karnam Malleswari) व्यक्तिगत खेल में सर्वप्रथम ओलंपिक पदक (सिडनी 2000, भारोत्तोलन) जीतने वाली भारतीय महिला हैं।', 'Karnam Malleswari is the first Indian woman to win an individual Olympic medal (Sydney 2000, Weightlifting).', 'कर्नम ने 2000 में ''कमाल'' किया।', 'Karnam did a ''Kamaal'' (miracle) in 2000.', 'पी.वी. सिंधु दो ओलंपिक पदक जीतने वाली पहली महिला हैं, लेकिन ''पहली बार'' पदक कर्नम ने जीता था।', 'P.V. Sindhu is the first woman to win two Olympic medals, but the ''first ever'' medal was won by Karnam.', 'medium', 0.94, 0.96, '[{"questionId":"hTEHMwiw-hABl1733BDzy"}]', '["Olympics History","First in India"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842055, 1773842055);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('4333223c-fba0-4917-80d2-b09e6476ce86', '22684ec7-7be4-469b-bd3c-9d67c5827dfa', 'Current Affairs', 'मध्य प्रदेश शासन द्वारा खेल ''प्रशिक्षकों'' (Coaches) को दिया जाने वाला सर्वोच्च पुरस्कार ''विश्वामित्र पुरस्कार'' है।', 'The highest award given to sports ''coaches'' by the Madhya Pradesh government is the ''Vishwamitra Award''.', 'गुरु विश्वामित्र (Coach = Vishwamitra)।', 'Guru Vishwamitra (Coach = Vishwamitra).', 'खिलाड़ियों के लिए ''विक्रम पुरस्कार'' (सीनियर) और ''एकलव्य पुरस्कार'' (जूनियर) है। ''प्रशिक्षक'' शब्द पर ध्यान दें।', 'For players, it is ''Vikram Award'' (Senior) and ''Eklavya Award'' (Junior). Pay attention to the word ''Coach''.', 'medium', 0.9, 0.94, '[{"questionId":"9oZC7ejuCqoaWqW80_LpQ"}]', '["State Sports Awards"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842055, 1773842055);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('00bef64d-e7e4-49f3-940b-25c382b9bee4', '22684ec7-7be4-469b-bd3c-9d67c5827dfa', 'Current Affairs', 'मध्य प्रदेश राज्य ''तीरंदाजी एकेडमी'' (Archery Academy) जबलपुर में स्थित है।', 'Madhya Pradesh State ''Archery Academy'' is located in Jabalpur.', 'तीर (Arrow) चलाने के लिए बल (Jabal-pur) चाहिए।', 'You need ''Bal'' (force/Jabalpur) to shoot an arrow.', 'अधिकांश खेल अकादमियां भोपाल (हॉकी, शूटिंग) या ग्वालियर (बैडमिंटन, महिला हॉकी) में हैं, जबलपुर की तीरंदाजी एकेडमी एक महत्वपूर्ण अपवाद है।', 'Most sports academies are in Bhopal (Hockey, Shooting) or Gwalior (Badminton, Women''s Hockey), the Archery Academy in Jabalpur is an important exception.', 'medium', 0.85, 0.88, '[{"questionId":"Dhtjj7mTgfEPiI4tXsVXx"}]', '["Sports Institutes of MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842055, 1773842055);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('18a2dcc7-2bed-4690-9dd2-bb9dc23edd65', 'a27b354a-e536-495f-86f5-89f43a4c4e65', 'ICT', 'जॉन मैक्कार्थी (John McCarthy) को ''कृत्रिम बुद्धिमत्ता'' (AI) का जनक माना जाता है। AI में ''क्षमता'' (Ability) पक्षपात (Bias) का स्रोत नहीं है।', 'John McCarthy is considered the father of ''Artificial Intelligence''. In AI, ''Ability'' is NOT a source of bias.', 'MacCarthy ने AI बनाया। क्षमता पक्षपात नहीं करती, डेटा करता है।', 'MacCarthy made AI. Ability doesn''t bias, data does.', 'एलन ट्यूरिंग को आधुनिक कंप्यूटर विज्ञान का जनक कहा जाता है, AI शब्द मैक्कार्थी ने गढ़ा था।', 'Alan Turing is the father of modern computer science, the term AI was coined by McCarthy.', 'medium', 0.9, 0.95, '[{"questionId":"BpetKlEAp5xfpSj2ILmhr"},{"questionId":"pl7GEcoVZT6KuRY41LjSI"}]', '["AI Basics","Founders"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842609, 1773842609);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('15665097-08a6-47ca-82a1-eecfa9314ed7', 'a27b354a-e536-495f-86f5-89f43a4c4e65', 'ICT', 'ई-कॉमर्स का ''विश्वव्यापी पहुँच'' (Global Reach) आयाम व्यापार को सीमाओं के पार ले जाता है। ई-गवर्नेन्स का सटीक अर्थ ''तकनीकी आधारित शासन'' है।', 'The ''Global Reach'' dimension of e-commerce takes business across borders. The precise meaning of E-Governance is ''Technology driven governance''.', 'Global Reach = पूरी दुनिया का बाजार। E-Gov = Tech + Govt.', 'Global Reach = Whole world market. E-Gov = Tech + Govt.', 'सोशल मीडिया अनुकूलन (SMO) का अर्थ सोशल नेटवर्क द्वारा प्रचार करना है, सर्च इंजन (SEO) द्वारा नहीं।', 'SMO means publicity through social networks, not search engines (SEO).', 'medium', 0.88, 0.92, '[{"questionId":"1pSmRh9Ud2Acsh9ufsIeT"},{"questionId":"m7fA05gPkes_rMS16VG5v"},{"questionId":"BpUVSAouNbuFxBCoimspI"}]', '["E-Commerce","E-Governance"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842609, 1773842609);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('f8bfd177-ab91-46a0-a4a6-746836c84508', 'a27b354a-e536-495f-86f5-89f43a4c4e65', 'ICT', 'साइबर सुरक्षा में नियमों का अनुपालन (Compliance), आंतरिक/बाहरी खतरों से बचाव और रोकथाम शामिल है। ''Cortesa'' कोई प्रसिद्ध वर्चुअल असिस्टेंट नहीं है।', 'Cyber security includes compliance, protection from internal/external threats, and prevention. ''Cortesa'' is NOT a famous virtual assistant.', 'Siri, Alexa, Cortana वर्चुअल असिस्टेंट हैं। PUMA एक रोबोटिक आर्म है।', 'Siri, Alexa, Cortana are virtual assistants. PUMA is a robotic arm.', 'नौकरियों का जाना (Job displacement) रोबोटिक्स का नुकसान है, फायदा नहीं।', 'Job displacement is a disadvantage of robotics, not an advantage.', 'medium', 0.85, 0.88, '[{"questionId":"lWGbCvlVvAnXrzE2f1ka5"},{"questionId":"EwP-Ypl1ifZzwwigWn3ud"},{"questionId":"atpbj2UU9Cu4166Lcagze"}]', '["Cyber Security","Robotics"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842609, 1773842609);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('e7fd6160-b30f-4377-b749-fec6b98d9361', '8fe835b1-69a2-4aef-909a-cc5adfa0b7b8', 'MP GK', 'मध्य प्रदेश में सर्वाधिक पाई जाने वाली जनजाति ''भील'' है (2011 जनगणना)। भारत की सबसे बड़ी जनजाति ''गोंड'' है।', 'The most populous tribe in Madhya Pradesh is ''Bhil'' (2011 Census). India''s largest tribe is ''Gond''.', 'MP में Bheel (B), India में Gond (G)।', 'Bheel (B) in MP, Gond (G) in India.', 'गोंड और भील के बीच हमेशा कन्फ्यूजन होता है। MP के लिए भील को ही सर्वोच्च मानें।', 'There is always confusion between Gond and Bhil. For MP, consider Bhil as the largest.', 'medium', 0.95, 0.98, '[{"questionId":"3QBN901lY79G6vG7maz6E"}]', '["Tribes of MP","Census 2011"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842609, 1773842609);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('78284ee9-3a6b-4825-91d6-5b519a7b4673', '8fe835b1-69a2-4aef-909a-cc5adfa0b7b8', 'MP GK', 'इंदिरा गांधी राष्ट्रीय जनजातीय विश्वविद्यालय (IGNTU) अमरकंटक (अनूपपुर) में स्थित है। ढोकरा कला एक ''धातु शिल्प'' (Metal craft) है।', 'Indira Gandhi National Tribal University (IGNTU) is located in Amarkantak (Anuppur). Dhokra art is a ''Metal craft''.', 'जनजातियों का विकास अमरकंटक से। ढोकरा = धातु।', 'Tribal development from Amarkantak. Dhokra = Metal.', 'ढोकरा कला को कपड़ा कला न समझें। यह बैतूल के भारेवा समुदाय द्वारा बनाई जाती है।', 'Do not mistake Dhokra art for textile art. It is made by the Bharewa community of Betul.', 'medium', 0.9, 0.94, '[{"questionId":"wguCJiSDmXQTenzbOY_8a"},{"questionId":"iPSCtg7IzzQ_YheY0jdiO"}]', '["Universities","Tribal Art"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842609, 1773842609);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('f249b21e-c5b1-4f80-a79e-2253cb7f72d3', '8fe835b1-69a2-4aef-909a-cc5adfa0b7b8', 'MP GK', 'बैगा विकास अभिकरण मंडला, डिंडौरी, शहडोल और बालाघाट में हैं, ''रायसेन'' में नहीं। निर्मल वर्मा पुरस्कार ''प्रवासी भारतीयों'' (NRIs) को हिंदी प्रचार के लिए दिया जाता है।', 'Baiga Development Agencies are in Mandla, Dindori, Shahdol, and Balaghat, NOT in ''Raisen''. Nirmal Verma Award is given to ''NRIs'' for Hindi promotion.', 'बैगा दक्षिण-पूर्व (South-East) में हैं। निर्मल वर्मा = विदेश में हिंदी।', 'Baiga are in South-East. Nirmal Verma = Hindi abroad.', 'रायसेन मध्य क्षेत्र में है जहाँ बैगाओं का सघन निवास नहीं है।', 'Raisen is in the central region where there is no dense Baiga population.', 'medium', 0.88, 0.92, '[{"questionId":"bQQ38PR9j2kGGpdSPiqjn"},{"questionId":"6LJi_M4HtwrmplU2KULJQ"}]', '["PVTGs","State Awards"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842610, 1773842610);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('097b5382-d62a-4117-a6a9-d4f952341545', '9b2f642e-f66a-4cac-b607-ac36c953116a', 'MP GK', 'उत्तरी क्षेत्र (मुरैना/दतिया) में महाद्वीपीय जलवायु के कारण अत्यधिक गर्मी पड़ती है। दक्षिण-पूर्वी MP (मंडला) में वर्षा ऋतु में सर्वाधिक वर्षा होती है।', 'Northern region (Morena/Datia) experiences extreme heat due to continental climate. South-eastern MP (Mandla) gets max rain in the monsoon.', 'उत्तर में भयंकर गर्मी। दक्षिण-पूर्व में ज्यादा बारिश।', 'Extreme heat in North. More rain in South-East.', 'मालवा (पश्चिमी MP) की जलवायु समशीतोष्ण (Temperate) होती है, जहाँ तापमान मध्यम रहता है।', 'Malwa (Western MP) has a temperate climate, where the temperature remains moderate.', 'medium', 0.88, 0.92, '[{"questionId":"HwDkmOCjUsotj_llCNBvD"},{"questionId":"d9YnhOFvJP3-mhPizMbBc"}]', '["Climate of MP","Rainfall"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842611, 1773842611);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('0e47ad52-3c27-43c1-9d8e-9ee913e42568', '9b2f642e-f66a-4cac-b607-ac36c953116a', 'MP GK', 'विश्व का सबसे बड़ा (600 MW) तैरता हुआ सोलर प्लांट ओंकारेश्वर बांध पर बन रहा है। कान्हा नेशनल पार्क का शुभंकर ''भूरसिंह द बारासिंघा'' है।', 'World''s largest (600 MW) floating solar plant is being built on Omkareshwar Dam. Mascot of Kanha National Park is ''Bhoorsingh the Barasingha''.', 'ओंकारेश्वर की लहरों पर सोलर। कान्हा का भूरसिंह।', 'Solar on Omkareshwar waves. Bhoorsingh of Kanha.', 'रीवा सोलर प्लांट जमीन पर है (750 MW), जबकि ओंकारेश्वर फ्लोटिंग है।', 'Rewa solar plant is on land (750 MW), while Omkareshwar is floating.', 'medium', 0.92, 0.94, '[{"questionId":"nuRxxaa8pa8q3JKy_KzEq"},{"questionId":"-ie4yBXqsOwmR6iDizzgW"}]', '["Renewable Energy","National Parks"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842611, 1773842611);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('6a4c5bc0-14fc-44cf-ad5d-2a24ac2e193e', '45d2de04-54b2-43ec-b621-8e5aca4dabf3', 'Current Affairs', 'अन्तर्राष्ट्रीय ओलम्पिक समिति (IOC) का मुख्यालय ''लुसाने'' (स्विट्जरलैंड) में और खाद्य एवं कृषि संगठन (FAO) का मुख्यालय ''रोम'' (इटली) में है।', 'The headquarters of the International Olympic Committee (IOC) is in ''Lausanne'' (Switzerland) and the Food and Agriculture Organization (FAO) is in ''Rome'' (Italy).', 'ओलंपिक की शान ''लुसाने'' में। खाना (Food) = रोम।', 'Olympic pride in ''Lausanne''. Food = Rome.', 'जिनेवा में कई मुख्यालय हैं (WHO, WTO), लेकिन IOC लुसाने में है।', 'Geneva has many HQs (WHO, WTO), but IOC is in Lausanne.', 'medium', 0.9, 0.95, '[{"questionId":"o8pZUDMth-cqlq7vdBgGT"},{"questionId":"4kmFRv2Rj68Aqfi8tLax5"}]', '["International Organizations","Headquarters"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842611, 1773842611);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('02a5606e-bf45-490c-8e56-4c244b4493fe', '45d2de04-54b2-43ec-b621-8e5aca4dabf3', 'Current Affairs', 'MP सरकार द्वारा खेल ''प्रशिक्षकों'' (Coaches) को ''विश्वामित्र पुरस्कार'' दिया जाता है। MP तीरंदाजी (Archery) एकेडमी ''जबलपुर'' में है। ग्लोबल इन्वेस्टर्स समिट 2023 ''इंदौर'' में हुई थी।', 'MP Govt gives the ''Vishwamitra Award'' to sports ''Coaches''. MP Archery Academy is in ''Jabalpur''. Global Investors Summit 2023 was held in ''Indore''.', 'कोच = विश्वामित्र। तीरंदाजी के लिए बल (जबलपुर) चाहिए।', 'Coach = Vishwamitra. You need force (Bal/Jabalpur) for archery.', 'खिलाड़ियों के लिए ''विक्रम पुरस्कार'' (सीनियर) और ''एकलव्य पुरस्कार'' (जूनियर) है। अधिकांश अकादमियां भोपाल/ग्वालियर में हैं, जबलपुर अपवाद है।', 'For players, it is ''Vikram Award'' (Senior) and ''Eklavya Award'' (Junior). Most academies are in Bhopal/Gwalior, Jabalpur is an exception.', 'medium', 0.88, 0.92, '[{"questionId":"9oZC7ejuCqoaWqW80_LpQ"},{"questionId":"Dhtjj7mTgfEPiI4tXsVXx"},{"questionId":"2hYLzai9-zS2Efssl65Gr"}]', '["State Sports Awards","Current Affairs MP"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842612, 1773842612);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a7414a25-b118-4ac1-afcc-143da75132a6', '5b26914c-49b7-4f4c-8cc3-6e6c6948fd7f', 'Polity', 'तीर्थस्थल ''ओंकारेश्वर'' का प्राचीन नाम ''मांधाता'' (Mandhata) था। भोपाल गैस त्रासदी 2-3 दिसंबर 1984 की रात को हुई थी (MIC गैस)।', 'The ancient name of the pilgrimage site ''Omkareshwar'' was ''Mandhata''. Bhopal Gas Tragedy occurred on the night of Dec 2-3, 1984 (MIC gas).', 'मांधाता पर्वत पर ओंकार। 1984 का काला दिसंबर।', 'Omkar on Mandhata mountain. Black December of 1984.', 'गैस का नाम मिथाइल आइसोसाइनेट (MIC) था, मिथाइल साइनाइड नहीं।', 'The gas name was Methyl Isocyanate (MIC), not Methyl Cyanide.', 'medium', 0.9, 0.95, '[{"questionId":"03ZWET1kCIg-MaaWctm4q"},{"questionId":"cfxyXj-p3hmMRa44Om-U9"}]', '["Ancient Names","MP History"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842612, 1773842612);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a6de6f56-ff9e-418b-8c2d-e56869a51941', 'fffa3853-9e9e-4c9d-a7d0-7ed6c2476caf', 'Geography', 'भारत में लौह अयस्क (Iron Ore) के भंडार मुख्य रूप से ओडिशा, झारखंड, छत्तीसगढ़ और कर्नाटक में पाए जाते हैं। मध्य प्रदेश इसमें अग्रणी (शीर्ष 3 में) नहीं है।', 'Iron ore reserves in India are mainly found in Odisha, Jharkhand, Chhattisgarh, and Karnataka. Madhya Pradesh is NOT a leader (in the top 3) in this.', 'लोहे का त्रिकोण (Iron Triangle) = ओडिशा, झारखंड, छत्तीसगढ़।', 'Iron Triangle = Odisha, Jharkhand, Chhattisgarh.', 'कथन आधारित प्रश्नों में MP को लौह अयस्क का सबसे बड़ा भंडार बताकर फंसाया जाता है। MP तांबा, मैंगनीज और हीरा में आगे है।', 'In statement-based questions, MP is falsely claimed as the largest iron ore reserve to trap students. MP leads in Copper, Manganese, and Diamond.', 'medium', 0.88, 0.94, '[{"questionId":"uCZ4PZbWtWDDpO49Iusex"}]', '["Mineral Resources","Economic Geography"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773842612, 1773842612);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('ccf7408d-225f-404c-893c-5af58f419ab5', '763f7cc0-2bd8-43f3-acb1-e5d2b4171dca', 'History', 'बुद्ध घोष की कृति ''समन्त पासादिका'' में स्पष्ट उल्लेख है कि बिन्दुसार के शासन काल में अशोक ने अवन्ति महाजनपद जीतकर मौर्य साम्राज्य में मिला लिया था।', 'Buddhaghosa''s work ''Samantapasadika'' clearly mentions that during Bindusara''s reign, Ashoka conquered the Avanti Mahajanapada and annexed it to the Mauryan Empire.', 'अशोक ''समन्त'' (साम्राज्य) को फैलाने अवंति गया।', 'Ashoka went to Avanti to expand the ''Samanta'' (Empire).', 'अशोक से जुड़े ''दीपवंश'' या ''महावंश'' (श्रीलंकाई ग्रंथ) विकल्पों में देकर भ्रमित किया जाता है; यह विशिष्ट उल्लेख ''समन्त पासादिका'' में है।', 'Options like ''Dipavamsa'' or ''Mahavamsa'' (Sri Lankan texts) are given to confuse; this specific mention is in ''Samantapasadika''.', 'medium', 0.85, 0.9, '[{"questionId":"xBi4klily7NLw1Ldh0Vv9"}]', '["Ancient Texts","Mauryan Empire"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773843564, 1773843564);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('c8ad07b0-c405-410f-a227-7cb30babb90b', '763f7cc0-2bd8-43f3-acb1-e5d2b4171dca', 'History', 'अमीर खुसरो ने अलाउद्दीन खिलजी के दक्षिण अभियानों के संदर्भ में कहा था: ''माण्डु विजय, दक्षिण विजय की कुंजी था'' (Conquest of Mandu was the key to the South)।', 'Amir Khusro said regarding Alauddin Khilji''s southern campaigns: ''The conquest of Mandu was the key to the conquest of the South''.', 'दक्षिण की ''खुश''खबरी (खुसरो) माण्डू से मिली।', 'Good news (Khusro) of the South came from Mandu.', 'इसे जलालुद्दीन खिलजी या अकबर के अभियानों से न जोड़ें। खुसरो ने अलाउद्दीन के अभियानों का आँखों देखा हाल लिखा था।', 'Do not link this to the campaigns of Jalaluddin Khilji or Akbar. Khusro wrote an eyewitness account of Alauddin''s campaigns.', 'medium', 0.8, 0.88, '[{"questionId":"6KnBaaDW4VNqW7QAKu9aL"}]', '["Medieval History","Quotes","Delhi Sultanate"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773843564, 1773843564);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('edb44e77-f37d-4f95-a6e1-ee1274c9e469', '763f7cc0-2bd8-43f3-acb1-e5d2b4171dca', 'History', 'सिंध के इतिहास का प्रमुख अरबी स्रोत ''चचनामा'' है, जिसके अनुसार 6वीं-7वीं सदी में सिंध की राजधानी ''अरोड़'' (Aror / Alor) थी।', 'The primary Arabic source of Sindh''s history is ''Chachnama'', according to which the capital of Sindh in the 6th-7th century was ''Aror'' (Alor).', 'सिंध का ''रोड़'' (Aror in Sindh)।', 'Aror in Sindh.', 'इसे देबल (जो एक बंदरगाह था) या मुल्तान से न मिलाएं। राजा दाहिर की राजधानी अरोड़ ही थी।', 'Do not confuse it with Debal (which was a port) or Multan. King Dahir''s capital was Aror.', 'medium', 0.8, 0.85, '[{"questionId":"ESi0rucbjGDOVdahnfTLY"}]', '["Ancient India","Historical Books"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773843564, 1773843564);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('5e9028f6-678b-42df-854e-fe45e42760c5', '763f7cc0-2bd8-43f3-acb1-e5d2b4171dca', 'History', 'मुगलकालीन ग्रंथ ''मासिर-ए-आलमगिरी'' (औरंगजेब के शासनकाल का आधिकारिक इतिहास) साकी मुस्तैद खाँ द्वारा रचित है।', 'The Mughal-era book ''Maasir-i-Alamgiri'' (official history of Aurangzeb''s reign) is authored by Saqi Mustaid Khan.', 'साकी ने औरंगजेब के ''आलम'' (World) की बातें लिखीं।', 'Saqi wrote about Aurangzeb''s ''Alam'' (World).', 'इसे अबुल फजल (''अकबरनामा'') या अब्दुल हामिद लाहौरी (''पादशाहनामा'') की रचना न समझें। ''आलमगीर'' औरंगजेब की उपाधि थी।', 'Do not mistake it as the work of Abul Fazl (''Akbarnama'') or Abdul Hamid Lahori (''Padshahnama''). ''Alamgir'' was Aurangzeb''s title.', 'medium', 0.85, 0.88, '[{"questionId":"WhrxP95CqhNCj6EeQuk4v"}]', '["Mughal Literature","Authors"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773843564, 1773843564);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('843ffb63-0dd4-45eb-ad32-4ecba59397e9', '763f7cc0-2bd8-43f3-acb1-e5d2b4171dca', 'History', 'मध्यकालीन भारतीय इतिहास में ''पनही'' (Panahi) तथा ''उपानह'' (Upanah) शब्द जूतों (Footwear/Shoes) के लिए प्रयोग होते थे।', 'In medieval Indian history, the words ''Panahi'' and ''Upanah'' were used for shoes/footwear.', '''पनही'' = ''पांव'' (Feet) में पहनने वाला।', '''Panahi'' = Worn on ''Paon'' (Feet).', 'इन्हें मध्यकालीन हथियारों, सिक्कों, आभूषणों या वस्त्रों (कपड़े) से जोड़ने के विकल्प देकर फंसाया जाता है।', 'Traps are set by giving options linking them to medieval weapons, coins, jewelry, or clothing.', 'medium', 0.7, 0.8, '[{"questionId":"c6Bp89Qvhb-AdnggLVwMO"}]', '["Terminology","Medieval Society"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773843564, 1773843564);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('a61616a0-bb99-4241-a4b7-b39121e477ad', '83dd10e6-32b8-4d5f-b16c-0e059d4b8525', 'History', 'इतिहासकार डॉ. आर. सी. मजूमदार और एस. एन. सेन का मानना था कि 19वीं शताब्दी के मध्य (1857 के विद्रोह के समय) भारतीय राष्ट्रवाद ''भ्रूणावस्था'' (Embryonic stage) में था।', 'Historians Dr. R.C. Majumdar and S.N. Sen believed that in the mid-19th century (during the 1857 revolt), Indian nationalism was in an ''embryonic stage''.', 'मजूमदार = 1857 पर सख्त टिप्पणी (न प्रथम, न राष्ट्रीय)।', 'Majumdar = Strict comment on 1857 (Neither first, nor national).', 'वी.डी. सावरकर ने इसे ''प्रथम स्वतंत्रता संग्राम'' कहा था। राष्ट्रवाद की ''भ्रूणावस्था'' वाली आलोचनात्मक टिप्पणी मजूमदार/सेन की है।', 'V.D. Savarkar called it the ''First War of Independence''. The critical comment of ''embryonic'' nationalism belongs to Majumdar/Sen.', 'medium', 0.88, 0.92, '[{"questionId":"gnAMbxUwJy7dSk1ecEEgV"}]', '["1857 Revolt","Historical Quotes","Historians"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773843564, 1773843564);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('3db86df2-5259-40ca-bbde-f5bbd8a0679a', '83dd10e6-32b8-4d5f-b16c-0e059d4b8525', 'History', 'विलियम हावर्ड रसल (William Howard Russell) 1857 में लंदन से प्रकाशित होने वाले समाचारपत्र ''टाइम्स'' (The Times) के संवाददाता थे, जिन्होंने उत्तर भारत में अंग्रेजों के प्रति भारी नफरत को रिपोर्ट किया था।', 'William Howard Russell was the correspondent for ''The Times'' (London) in 1857, who reported the immense hatred against the British in Northern India.', 'रसल (Russell) ने टाइम्स में 1857 की ''असल'' (Asal/Real) बात बताई।', 'Russell told the ''Real'' story of 1857 in The Times.', 'विदेशी संवाददाताओं के नाम अक्सर पूछे जाते हैं (जैसे भारत छोड़ो आंदोलन के समय लुई फिशर)। ''टाइम्स'' के लिए 1857 में रसल थे।', 'Names of foreign correspondents are often asked (e.g., Louis Fischer during Quit India). For ''The Times'' in 1857, it was Russell.', 'medium', 0.75, 0.85, '[{"questionId":"md1hsRWzahrix1-sdSmuv"}]', '["1857 Revolt","Press History"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773843564, 1773843564);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('d58293cb-365f-4e06-ab17-1e759cf8d633', '83dd10e6-32b8-4d5f-b16c-0e059d4b8525', 'History', 'सर चार्ल्स मेटकाफ (Sir Charles Metcalfe) ने भारत की आत्मनिर्भर ग्राम व्यवस्था का वर्णन करते हुए कहा था कि ''भारत की ग्राम व्यवस्था छोटे-छोटे गणतन्त्र (Little Republics) हैं''।', 'Sir Charles Metcalfe, describing India''s self-reliant village system, said that ''Indian villages are Little Republics''.', 'मेटकाफ = गाँव एक गणतंत्र (Village Republics)।', 'Metcalfe = Village Republics.', 'चार्ल्स मेटकाफ को ''भारतीय प्रेस का मुक्तिदाता'' (Liberator of Indian Press) भी कहा जाता है। इसे स्थानीय स्वशासन के जनक (लॉर्ड रिपन) से न मिलाएं।', 'Charles Metcalfe is also called the ''Liberator of Indian Press''. Do not mix him with the father of local self-government (Lord Ripon).', 'medium', 0.9, 0.94, '[{"questionId":"TmNkqCIx3IK-W-fn8wkjM"}]', '["British Administration","Quotes"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773843565, 1773843565);
INSERT INTO "pyq_fact_bank" ("id", "topic_id", "subject", "fact_text", "fact_text_en", "memory_tip", "memory_tip_en", "scam_alert", "scam_alert_en", "difficulty", "frequency_score", "importance_score", "pyq_refs", "tags", "status", "source", "created_by", "created_at", "updated_at") VALUES ('557c92f0-20fa-4a09-b221-e9c581358907', '83dd10e6-32b8-4d5f-b16c-0e059d4b8525', 'History', '1866 में ब्रह्म समाज के विभाजन के बाद ''देवेन्द्रनाथ टैगोर'' के गुट/समूह को ''आदि ब्रह्म समाज'' (Adi Brahmo Samaj) कहा गया।', 'After the split of Brahmo Samaj in 1866, the group led by ''Devendranath Tagore'' was called the ''Adi Brahmo Samaj''.', '''आदि'' (पुराने/मूल) विचारों वाले ''देवेन्द्रनाथ'' थे।', '''Devendranath'' held the older/original (Adi) views.', 'राजा राममोहन राय ने मूल ''ब्रह्म समाज'' (1828) बनाया था। 1866 के विभाजन के बाद केशव चन्द्र सेन ने ''भारतीय ब्रह्म समाज'' (Brahmo Samaj of India) बनाया।', 'Raja Ram Mohan Roy founded the original ''Brahmo Samaj'' (1828). After the 1866 split, Keshab Chandra Sen formed the ''Brahmo Samaj of India''.', 'medium', 0.95, 0.96, '[{"questionId":"Sfjn2GlWWT6ULHqDPZvtf"}]', '["Socio-Religious Reforms","Institutions"]', 'published', 'ai', '323a5d2d-ce28-4641-8c14-4c01d56a7aa1', 1773843565, 1773843565);
