INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('bb6afa7a-2e4d-4b3e-9b2c-6b001440568d', 'History', 'ancient-india-philosophy', 'प्राचीन भारत और दर्शन', 'Ancient India & Philosophy', 'High-yield core concepts covering Vedic texts, Ashrama system, and Indian philosophical schools.', 1, 1773829238, 1773829238, '{"must_know_lists":[{"list_title":"वेद और उनके ब्राह्मण ग्रंथ","list_title_en":"Vedas and their Brahmanas","items":["ऋग्वेद - ऐतरेय, कौषीतकि","सामवेद - पंचविश, ताण्ड्य","यजुर्वेद - शतपथ (शुक्ल), तैत्तिरीय (कृष्ण)","अथर्ववेद - गोपथ"],"items_en":["Rigveda - Aitareya, Kaushitaki","Samaveda - Panchavimsha, Tandya","Yajurveda - Shatapatha (Shukla), Taittiriya (Krishna)","Atharvaveda - Gopatha"],"memory_hook":"RG-Ai, SA-Pa, YA-Sha, AT-Go","memory_hook_en":"RG-Ai, SA-Pa, YA-Sha, AT-Go"}],"concept_capsule":"प्राचीन भारतीय इतिहास में आश्रम व्यवस्था (गृहस्थ सर्वोच्च) और दर्शन (जैसे सांख्य का सत्कार्यवाद) से सीधे प्रश्न आते हैं। दर्शन और उनके प्रवर्तक (सांख्य-कपिल, योग-पतंजलि, न्याय-गौतम) को कंठस्थ करें।","concept_capsule_en":"Ancient Indian history tests core structures like Ashramas (Grihastha being supreme) and philosophical doctrines (Satkaryavada of Sankhya). Memorize the 6 schools of philosophy and their founders.","practice_prompts":["Revise the founders of the 6 orthodox schools of Indian Philosophy.","Review the core theme of major Upanishads (e.g., Mundaka for Satyameva Jayate)."],"practice_prompts_en":["Revise the founders of the 6 orthodox schools of Indian Philosophy.","Review the core theme of major Upanishads (e.g., Mundaka for Satyameva Jayate)."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e0115c75-499b-4d61-934a-e5486efbc65d', 'History', 'indian-art-culture-modern-movements', 'भारतीय कला, संस्कृति और आधुनिक आंदोलन', 'Indian Art, Culture & Modern Movements', 'Fusion of South Indian temple architecture, Bhakti saints, and major pre-independence movements.', 1, 1773829239, 1773829239, '{"must_know_lists":[{"list_title":"दक्षिण भारतीय मंदिर शैलियाँ","list_title_en":"South Indian Temple Styles","items":["पल्लव - रथ मंदिर (महाबलीपुरम), राजसिम्हा शैली (कांची)","चोल - बृहदेश्वर (तंजौर)","विजयनगर - विट्ठल मंदिर (हम्पी)"],"items_en":["Pallava - Rathas (Mahabalipuram), Rajasimha style (Kanchi)","Chola - Brihadeshwara (Tanjore)","Vijayanagara - Vitthala Temple (Hampi)"],"memory_hook":"Pallava = Kanchi, Chola = Tanjore","memory_hook_en":"Pallava = Kanchi, Chola = Tanjore"}],"concept_capsule":"भारतीय राष्ट्रीय आंदोलन में महत्वपूर्ण तिथियों (Chronology) का सीधा परीक्षण होता है। दांडी मार्च, भारत छोड़ो, और कैबिनेट मिशन के बाद की घटनाओं का क्रम हमेशा याद रखें।","concept_capsule_en":"Indian National Movement heavily tests exact chronology. Always memorize the exact sequence of events from 1930 (Dandi) to 1947.","practice_prompts":["Arrange the events of 1946-1947 in chronological order.","Review the differences between Dravidian and Nagara temple architectures."],"practice_prompts_en":["Arrange the events of 1946-1947 in chronological order.","Review the differences between Dravidian and Nagara temple architectures."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('c714ff65-6bc2-482f-bedc-fac9401172cd', 'Geography', 'physical-environmental-resource-geography', 'भौतिक, पर्यावरण और संसाधन भूगोल', 'Physical, Environmental & Resource Geography', 'Integration of physical geography (Rivers, Hills), ecology (Succession, Laws), and mineral/energy resources.', 1, 1773829239, 1773829239, '{"must_know_lists":[{"list_title":"पर्यावरण के प्रमुख अधिनियम","list_title_en":"Major Environmental Acts","items":["वन्यजीव संरक्षण - 1972","जल प्रदूषण - 1974","वन संरक्षण - 1980","पर्यावरण (छाता विधान) - 1986","जैव विविधता - 2002 (संशोधन 2023)"],"items_en":["Wildlife Protection - 1972","Water Pollution - 1974","Forest Conservation - 1980","Environment (Umbrella) - 1986","Biodiversity - 2002 (Amended 2023)"],"memory_hook":"72 Wildlife -> 74 Water -> 80 Forest -> 86 Env","memory_hook_en":"72 Wildlife -> 74 Water -> 80 Forest -> 86 Env"}],"concept_capsule":"भूगोल में संसाधनों (विशेषकर ऊर्जा और खनिज) के अद्यतन डेटा से प्रश्न आते हैं। साथ ही, ENSO (अल नीनो और दक्षिणी दोलन) जैसे जलवायु पैटर्न भारतीय मानसून को कैसे प्रभावित करते हैं, यह एक मुख्य अवधारणा है।","concept_capsule_en":"Geography heavily relies on updated mineral and energy data. Also, conceptual understanding of climate phenomena like ENSO (El Nino and Southern Oscillation) is critical for monsoon-related questions.","practice_prompts":["Check the latest mineral production vs reserve data for Copper and Coal.","Map out the major nuclear power plants of India."],"practice_prompts_en":["Check the latest mineral production vs reserve data for Copper and Coal.","Map out the major nuclear power plants of India."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('d952ff39-690b-4542-8522-339f8df9ff5f', 'Economy', 'macroeconomy-agriculture-demographics', 'मैक्रोइकॉनॉमी, कृषि और जनसांख्यिकी', 'Macroeconomy, Agriculture & Demographics', 'Key macroeconomic indicators, India''s agricultural ranks, and essential 2011 Census facts.', 1, 1773829241, 1773829241, '{"must_know_lists":[{"list_title":"कृषि उत्पादन रैंक (ताजा रुझान)","list_title_en":"Agriculture Production Ranks","items":["भारत #1 - दूध, दाल, जूट, मसाले","भारत #2 - चावल, गेहूं, फल, सब्जियां, कपास","म.प्र. #1 - सोयाबीन, दालें, हीरा"],"items_en":["India #1 - Milk, Pulses, Jute, Spices","India #2 - Rice, Wheat, Fruits, Veggies, Cotton","MP #1 - Soybean, Pulses, Diamond"],"memory_hook":"MP is the Pulses Bowl.","memory_hook_en":"MP is the Pulses Bowl."}],"concept_capsule":"अर्थव्यवस्था में बुनियादी अवधारणाओं (जैसे मौद्रिक नीति) और वर्तमान रुझानों (जैसे पूंजी गहनता में गुजरात शीर्ष पर, सेवा क्षेत्र का अधिशेष) का संयोजन होता है। 2011 की जनगणना अभी भी राज्य और राष्ट्रीय दोनों स्तरों पर उच्च-उपज वाला विषय है।","concept_capsule_en":"Economy mixes basic concepts (Monetary Policy) with current trends (Gujarat leading capital intensity, services surplus). Census 2011 remains a high-yield topic for both MP and National levels.","practice_prompts":["Compare the Fiscal Deficit vs Trade Deficit concepts.","Memorize the top 3 and bottom 3 states for Literacy and Sex Ratio in Census 2011."],"practice_prompts_en":["Compare the Fiscal Deficit vs Trade Deficit concepts.","Memorize the top 3 and bottom 3 states for Literacy and Sex Ratio in Census 2011."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('8909052c-55f2-4a07-afcf-e71d4437c421', 'ICT', 'cyber-security-e-governance-networks', 'साइबर सुरक्षा, ई-गवर्नेंस और नेटवर्क', 'Cyber Security, E-Governance & Networks', 'Core computer network concepts, malware types, and major e-Governance frameworks.', 1, 1773829242, 1773829242, '{"must_know_lists":[{"list_title":"मैलवेयर के प्रकार","list_title_en":"Types of Malware","items":["वायरस - फाइल से जुड़ता है","वर्म - नेटवर्क पर खुद फैलता है","ट्रोजन - उपयोगी सॉफ्टवेयर का दिखावा","रैनसमवेयर - डेटा लॉक करके फिरौती मांगता है"],"items_en":["Virus - Attaches to files","Worm - Self-replicates over network","Trojan - Disguises as useful software","Ransomware - Locks data for money"],"memory_hook":"Worms Wiggle Everywhere (Replicate).","memory_hook_en":"Worms Wiggle Everywhere (Replicate)."}],"concept_capsule":"ई-गवर्नेंस और साइबर सुरक्षा से सैद्धांतिक प्रश्न लगातार आते हैं। ई-गवर्नेंस के मॉडल (गार्टनर) और सरकारी पहल (जैसे NeGP का सारांश) को अच्छे से पढ़ें।","concept_capsule_en":"Theoretical questions from E-Governance and Cyber Security are consistent. Study E-Gov models (Gartner) and Govt initiatives (like NeGP''s Saaransh compendium).","practice_prompts":["Define Phishing vs Spoofing.","List 5 major Mission Mode Projects under NeGP."],"practice_prompts_en":["Define Phishing vs Spoofing.","List 5 major Mission Mode Projects under NeGP."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e40ed15c-5c62-4c5e-82ef-2917fa18cd09', 'MP GK', 'mp-art-culture-economy-miscellany', 'मध्य प्रदेश कला, संस्कृति, अर्थव्यवस्था और विविध', 'MP Art, Culture, Economy & Miscellany', 'Comprehensive mix of MP''s unique local crafts, historical literature, budget highlights, and awards.', 1, 1773829243, 1773829243, '{"must_know_lists":[{"list_title":"म.प्र. के प्रमुख लोक नाट्य","list_title_en":"Major Folk Dramas of MP","items":["मालवा - माच","निमाड़ - गम्मत","बुंदेलखंड - स्वांग","बघेलखंड - छाहुर, मनसुखा"],"items_en":["Malwa - Maach","Nimar - Gammat","Bundelkhand - Swang","Baghelkhand - Chhahur, Mansukha"],"memory_hook":"Malwa=Maach, Nimar=Gammat, Bundel=Swang","memory_hook_en":"Malwa=Maach, Nimar=Gammat, Bundel=Swang"}],"concept_capsule":"एमपी जीके में अब बहुत गहराई (Micro-topics) से प्रश्न पूछे जा रहे हैं। जिले-वार प्रमुख शिल्प (जैसे उचेहरा का कांसा) और लोक संस्कृति के बारीक विवरण (मनसुखा) पर विशेष ध्यान दें।","concept_capsule_en":"MP GK now tests high-depth micro-topics. Focus strictly on district-specific crafts (like Bronze of Uchehara) and minute details of folk culture.","practice_prompts":["Map the GI tags of Madhya Pradesh to their respective districts.","Revise the builders of the major temples in the Khajuraho Western Group."],"practice_prompts_en":["Map the GI tags of Madhya Pradesh to their respective districts.","Revise the builders of the major temples in the Khajuraho Western Group."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('5f0f2309-45bd-43ad-add5-63b1920762fb', 'Current Affairs', 'current-affairs-defence-health-schemes', 'करंट अफेयर्स, रक्षा और स्वास्थ्य योजनाएं', 'Current Affairs, Defence & Health Schemes', 'Recent storms, military exercises, indices, and national health missions.', 1, 1773829244, 1773829244, '{"must_know_lists":[{"list_title":"भारत सरकार के प्रमुख स्वास्थ्य लक्ष्य","list_title_en":"Major Health Targets of GoI","items":["टीबी (TB) उन्मूलन - 2025","मलेरिया उन्मूलन - 2030","कालाजार उन्मूलन - 2023","सिकल सेल एनीमिया - 2047"],"items_en":["TB Elimination - 2025","Malaria Elimination - 2030","Kala-azar Elimination - 2023","Sickle Cell Anemia - 2047"],"memory_hook":"TB 25, Malaria 30, Sickle 47","memory_hook_en":"TB 25, Malaria 30, Sickle 47"}],"concept_capsule":"समसामयिक मामलों में रक्षा अभ्यास, प्रमुख चक्रवात और सरकार के उन्मूलन लक्ष्य (Elimination targets) सबसे ज्यादा पूछे जाते हैं। 2024-25 के सभी सैन्य अभ्यासों की सूची तैयार रखें।","concept_capsule_en":"Current affairs heavily target Defence Exercises, recent cyclones, and Govt elimination targets. Keep a list of all 2024-25 military exercises handy.","practice_prompts":["List the top 5 civilian awards (Padma) given in the current year.","Match the recent Cyclones (Dana, Remal, Biparjoy) with the affected states."],"practice_prompts_en":["List the top 5 civilian awards (Padma) given in the current year.","Match the recent Cyclones (Dana, Remal, Biparjoy) with the affected states."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('f2ecd569-5c7e-4c80-ab1b-ea207bc940ae', 'History', 'ancient-indian-texts-philosophy-modern-chronology', 'प्राचीन भारतीय ग्रंथ, दर्शन और आधुनिक कालक्रम', 'Ancient Indian Texts, Philosophy & Modern Chronology', 'एक अत्यधिक उच्च-उपज वाला खंड जिसमें वैदिक साहित्य (ब्राह्मण/उपनिषद), दार्शनिक संप्रदाय, दक्षिण भारतीय भक्ति संत और आधुनिक इतिहास की महत्वपूर्ण घटनाएं शामिल हैं।', 1, 1773829277, 1773829277, '{"must_know_lists":[{"list_title":"छह आस्तिक दर्शन (षड्दर्शन) और उनके प्रवर्तक","list_title_en":"Six Orthodox Schools of Indian Philosophy & Founders","items":["सांख्य - कपिल मुनि (सत्कार्यवाद)","योग - पतंजलि","न्याय - गौतम मुनि","वैशेषिक - कणाद","पूर्व मीमांसा - जैमिनी","उत्तर मीमांसा (वेदांत) - बादरायण"],"items_en":["Sankhya - Kapil Muni (Satkaryavada)","Yoga - Patanjali","Nyaya - Gautama Muni","Vaisheshika - Kanada","Purva Mimamsa - Jaimini","Uttara Mimamsa (Vedanta) - Badarayana"],"memory_hook":"S-K, Y-P, N-G, V-K, P-J, U-B","memory_hook_en":"S-K, Y-P, N-G, V-K, P-J, U-B"}],"concept_capsule":"प्राचीन भारतीय इतिहास में दार्शनिक संप्रदाय (Philosophy) और वैदिक साहित्य का मिलान (Matching) MPPSC का पसंदीदा क्षेत्र है। ब्राह्मण ग्रंथों को उनके संबंधित वेदों से जोड़ना सीखें। आधुनिक इतिहास में 1930 से 1947 तक की घटनाओं की क्रोनोलॉजी (तिथियों सहित) बिल्कुल कंठस्थ होनी चाहिए।","concept_capsule_en":"In Ancient Indian History, matching philosophical schools and Vedic literature is a favorite MPPSC area. Learn to map Brahmana texts to their respective Vedas. In Modern History, the strict chronology of events from 1930 to 1947 (including exact dates) must be memorized.","practice_prompts":["मैचिंग अभ्यास: चारों वेदों के नाम लिखें और उनके सामने उनके ब्राह्मण ग्रंथों और उपवेदों के नाम लिखें।","क्रोनोलॉजी टेस्ट: कैबिनेट मिशन, माउंटबेटन योजना, क्रिप्स मिशन और वेवेल योजना को सही क्रम में व्यवस्थित करें।"],"practice_prompts_en":["Matching Exercise: Write the names of all four Vedas and map them to their Brahmanas and Upavedas.","Chronology Test: Arrange Cabinet Mission, Mountbatten Plan, Cripps Mission, and Wavell Plan in correct order."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('f2702d55-8ec4-4fc6-94e0-92055b20cfe2', 'Geography', 'physical-geography-climate-ecology-resources', 'भौतिक भूगोल, जलवायु, पारिस्थितिकी और संसाधन', 'Physical Geography, Climate, Ecology & Resources', 'भारत और विश्व भूगोल का एक व्यापक मिश्रण, जिसमें नदियाँ, जलवायु पैटर्न (ENSO), पारिस्थितिकी (पारिस्थितिक अनुक्रमण), पर्यावरण अधिनियम और प्रमुख ऊर्जा/खनिज संसाधन शामिल हैं।', 1, 1773829278, 1773829278, '{"must_know_lists":[{"list_title":"भारत के प्रमुख ऊर्जा/खनिज उत्पादक राज्य (अद्यतन)","list_title_en":"Top Energy/Mineral Producing States of India (Updated)","items":["लौह अयस्क - ओडिशा (भंडार और उत्पादन दोनों)","सौर ऊर्जा - राजस्थान (16 GW+)","पवन ऊर्जा - गुजरात / तमिलनाडु","परमाणु ऊर्जा संयंत्र - कुडनकुलम (TN, सबसे बड़ा), तारापुर (MH, सबसे पुराना)","कोयला - ओडिशा (उत्पादन), झारखंड (भंडार)"],"items_en":["Iron Ore - Odisha (Both Reserve & Production)","Solar Energy - Rajasthan (16 GW+)","Wind Energy - Gujarat / Tamil Nadu","Nuclear Plants - Kudankulam (TN, Largest), Tarapur (MH, Oldest)","Coal - Odisha (Production), Jharkhand (Reserves)"],"memory_hook":"Iron->Odisha, Solar->Rajasthan, Wind->Gujarat","memory_hook_en":"Iron->Odisha, Solar->Rajasthan, Wind->Gujarat"}],"concept_capsule":"भूगोल में पर्यावरण पारिस्थितिकी (अनुक्रमण, खाद्य श्रृंखला) और अद्यतन संसाधन डेटा (ISFR वन रिपोर्ट, खनिज रिपोर्ट 2023-24) का दबदबा है। ऊर्जा क्षेत्र में नवीकरणीय (Solar/Wind) क्षमता के नवीनतम आंकड़े और प्रमुख परमाणु ऊर्जा संयंत्रों की मैपिंग बहुत उच्च-उपज वाले विषय हैं।","concept_capsule_en":"Geography is dominated by Environmental Ecology (succession, food chains) and updated resource data (ISFR Forest Report, Mineral Data 2023-24). In energy, the latest renewable capacity stats and mapping of major nuclear plants are extremely high-yield.","practice_prompts":["भारत के 7 प्रमुख परमाणु ऊर्जा संयंत्रों और उनके राज्यों की सूची बनाएं।","पारिस्थितिक अनुक्रमण के प्राथमिक और द्वितीयक चरणों (Primary vs Secondary Succession) में क्या अंतर है?"],"practice_prompts_en":["List the 7 major nuclear power plants of India and their respective states.","What is the difference between Primary and Secondary Ecological Succession?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('a4142d4d-bd76-492a-906a-0f5f29ac41bb', 'Economy', 'macroeconomy-demographics-census-2011-agriculture', 'मैक्रोइकॉनॉमी, जनसांख्यिकी (जनगणना 2011) और कृषि', 'Macroeconomy, Demographics (Census 2011) & Agriculture', 'अर्थव्यवस्था के मूल सिद्धांत (मौद्रिक नीति, व्यापार घाटा), भारत और म.प्र. की कृषि रैंकिंग, और 2011 की जनगणना के महत्वपूर्ण जनसांख्यिकीय आंकड़े।', 1, 1773829279, 1773829279, '{"must_know_lists":[{"list_title":"कृषि उत्पादन: वैश्विक और राष्ट्रीय रैंकिंग","list_title_en":"Agricultural Production: Global & National Rankings","items":["भारत विश्व में प्रथम - दूध, दालें, मसाले, जूट","भारत विश्व में द्वितीय - चावल, गेहूं, फल, सब्जियां, कपास","मध्यप्रदेश भारत में प्रथम - सोयाबीन, दालें, चना, हीरा (खनिज)","मध्यप्रदेश भारत में द्वितीय - प्याज, सरसों"],"items_en":["India 1st Globally - Milk, Pulses, Spices, Jute","India 2nd Globally - Rice, Wheat, Fruits, Veggies, Cotton","MP 1st in India - Soybean, Pulses, Gram, Diamond (Mineral)","MP 2nd in India - Onion, Mustard"],"memory_hook":"MP is the Pulses & Soybean State.","memory_hook_en":"MP is the Pulses & Soybean State."}],"concept_capsule":"जनगणना 2011 MPPSC का सबसे वफादार विषय है; साक्षरता, लिंगानुपात, और जनसंख्या वृद्धि के राष्ट्रीय और राज्य-स्तरीय शीर्ष 3/निचले 3 जिले/राज्य हमेशा याद रखें। अर्थव्यवस्था में, व्यापार घाटा (माल बनाम सेवाएं) और RBI की मुद्रास्फीति लक्ष्यीकरण समिति (MPC) मुख्य अवधारणाएं हैं।","concept_capsule_en":"Census 2011 is MPPSC''s most loyal topic; always memorize the National and State-level Top 3 / Bottom 3 for Literacy, Sex Ratio, and Population Growth. In Economy, trade deficit dynamics (Merchandise vs Services) and RBI''s MPC inflation targeting are core concepts.","practice_prompts":["म.प्र. के सर्वाधिक और न्यूनतम लिंगानुपात (Sex Ratio) वाले शीर्ष 3 जिलों की सूची बनाएं।","चालू खाता घाटा (Current Account Deficit) और व्यापार घाटा (Trade Deficit) के बीच मुख्य अंतर स्पष्ट करें।"],"practice_prompts_en":["List the top 3 districts in MP with the highest and lowest Sex Ratios.","Explain the core difference between Current Account Deficit and Trade Deficit."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('714523bd-619e-4ff6-962c-718e14d4fa5f', 'ICT', 'cyber-security-e-governance-networks-os', 'साइबर सुरक्षा, ई-गवर्नेंस, नेटवर्क और ओएस', 'Cyber Security, E-Governance, Networks & OS', 'सूचना संचार प्रौद्योगिकी (ICT) की बुनियादी अवधारणाएं, मैलवेयर के प्रकार, नेटवर्क का लचीलापन, और राष्ट्रीय ई-गवर्नेंस पहल।', 1, 1773829280, 1773829280, '{"must_know_lists":[{"list_title":"मैलवेयर के प्रमुख प्रकार","list_title_en":"Major Types of Malware","items":["वायरस (Virus) - किसी फाइल या प्रोग्राम से जुड़कर फैलता है (मानव क्रिया की आवश्यकता)।","वर्म (Worm) - नेटवर्क पर स्व-प्रतिकृति (Self-replicate) बनाता है।","ट्रोजन हॉर्स (Trojan) - उपयोगी सॉफ्टवेयर होने का नाटक करता है।","रैनसमवेयर (Ransomware) - डेटा को एन्क्रिप्ट कर फिरौती मांगता है।","स्पाइवेयर (Spyware) - गुप्त रूप से उपयोगकर्ता की निगरानी करता है (उदा: पेगासस)।"],"items_en":["Virus - Attaches to a file/program (requires human action).","Worm - Self-replicates over a network.","Trojan - Disguises as useful software.","Ransomware - Encrypts data and demands money.","Spyware - Secretly monitors user activity (e.g., Pegasus)."],"memory_hook":"Worms Wiggle (Replicate), Trojans Trick (Disguise).","memory_hook_en":"Worms Wiggle (Replicate), Trojans Trick (Disguise)."}],"concept_capsule":"ई-गवर्नेंस मॉडल (जैसे गार्टनर) और साइबर सुरक्षा के मूल सिद्धांत (CIA Triad, मैलवेयर के प्रकार) MPPSC के सिलेबस के सबसे ''स्टेटिक'' हिस्से हैं, जो बार-बार पूछे जाते हैं। NeGP के तहत UMANG, CSC, और SWAN जैसे बुनियादी ई-गवर्नेंस ढांचे को गहराई से पढ़ें।","concept_capsule_en":"E-governance models (like Gartner) and core cybersecurity principles (CIA Triad, malware types) are the most ''static'' parts of the MPPSC syllabus, repeating constantly. Deeply study foundational E-Gov frameworks under NeGP like UMANG, CSC, and SWAN.","practice_prompts":["ई-गवर्नेंस में G2C, G2B, और G2G मॉडल के दो-दो उदाहरण दें।","फिशिंग (Phishing) और स्पूफिंग (Spoofing) के बीच तकनीकी अंतर स्पष्ट करें।"],"practice_prompts_en":["Give two examples each for G2C, G2B, and G2G E-Governance models.","Explain the technical difference between Phishing and Spoofing."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('919db760-8a8a-4493-82cf-20cb822e206c', 'MP GK', 'mp-art-culture-local-crafts-budget', 'मध्य प्रदेश कला, संस्कृति, स्थानीय शिल्प और बजट', 'MP Art, Culture, Local Crafts & Budget', 'मध्य प्रदेश के विशिष्ट स्थानीय शिल्प, लोक नाट्य, प्रमुख मंदिर, साहित्य और राज्य के बजट आवंटन से संबंधित अति-विशिष्ट (Micro) तथ्य।', 1, 1773829281, 1773829281, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के प्रमुख अंचल-वार लोक नाट्य","list_title_en":"Region-wise Major Folk Dramas of MP","items":["मालवा - माच (Maach)","निमाड़ - गम्मत (Gammat)","बुंदेलखंड - स्वांग (Swang)","बघेलखंड - छाहुर (Chhahur), मनसुखा (Mansukha), हिंगोला (Hingola)"],"items_en":["Malwa - Maach","Nimar - Gammat","Bundelkhand - Swang","Baghelkhand - Chhahur, Mansukha, Hingola"],"memory_hook":"मालवा का माच, निमाड़ की गम्मत। बुंदेल में स्वांग, बघेल में मनसुखा।","memory_hook_en":"Malwa''s Maach, Nimar''s Gammat. Bundel''s Swang, Baghel''s Mansukha."}],"concept_capsule":"MPPSC अब ऊपरी जानकारी से संतुष्ट नहीं है; वे ''माइक्रो-लोकल'' तथ्य पूछते हैं (जैसे उचेहरा का कांसा)। मध्य प्रदेश के जीआई (GI) टैग वाले उत्पादों, जिला-एक-उत्पाद (ODOP) सूची, और खजुराहो के मंदिरों के बारीक विवरणों को गहराई से तैयार करें।","concept_capsule_en":"MPPSC is no longer satisfied with superficial knowledge; they ask ''micro-local'' facts (like Uchehara''s Bronze). Deeply prepare MP''s GI Tagged products, One District One Product (ODOP) lists, and minute details of Khajuraho temples.","practice_prompts":["मध्य प्रदेश के सभी GI टैग प्राप्त उत्पादों की सूची बनाएं और उनके संबंधित जिलों को मैप करें।","राष्ट्रीय कालिदास सम्मान और तानसेन सम्मान के नवीनतम (2023-24) विजेताओं के नाम याद करें।"],"practice_prompts_en":["List all GI tagged products of MP and map them to their respective districts.","Memorize the latest (2023-24) winners of the National Kalidas Samman and Tansen Samman."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('7b305731-d2cf-4098-afa9-8c23db9c7bec', 'Current Affairs', 'national-health-missions-defence-exercises-major-events', 'राष्ट्रीय स्वास्थ्य मिशन, रक्षा अभ्यास और प्रमुख कार्यक्रम', 'National Health Missions, Defence Exercises & Major Events', 'भारत सरकार के महत्वाकांक्षी स्वास्थ्य लक्ष्य, प्रमुख सैन्य अभ्यास, चक्रवात आपदाएं, और महत्वपूर्ण सूचकांक/संस्थान।', 1, 1773829282, 1773829282, '{"must_know_lists":[{"list_title":"भारत सरकार के प्रमुख स्वास्थ्य उन्मूलन लक्ष्य","list_title_en":"Major Health Elimination Targets of GoI","items":["कालाजार उन्मूलन - 2023","टीबी (TB) उन्मूलन - 2025","मलेरिया उन्मूलन - 2030","सिकल सेल एनीमिया उन्मूलन - 2047","लिम्फेटिक फाइलेरियासिस - 2027"],"items_en":["Kala-azar Elimination - 2023","TB Elimination - 2025","Malaria Elimination - 2030","Sickle Cell Anemia Elimination - 2047","Lymphatic Filariasis - 2027"],"memory_hook":"TB-25, Malaria-30, Sickle-47","memory_hook_en":"TB-25, Malaria-30, Sickle-47"}],"concept_capsule":"समसामयिक मामलों (Current Affairs) में नियुक्तियाँ, प्रमुख आपदाएं (चक्रवात), सूचकांक, और भारत के रक्षा अभ्यास सबसे ज्यादा पूछे जाते हैं। इसके अलावा, भारत सरकार के स्वास्थ्य लक्ष्यों (Targets) पर सीधा प्रश्न आता है। हाल ही में पद्म पुरस्कार और भारत रत्न विजेताओं की सूची परीक्षा के लिए अति-आवश्यक है।","concept_capsule_en":"In Current Affairs, appointments, major disasters (cyclones), indices, and India''s defence exercises are asked the most. Also, direct questions come from Govt of India''s health targets. The recent list of Padma Awards and Bharat Ratna winners is ultra-essential.","practice_prompts":["पिछले 1 वर्ष में भारत तट पर आए 3 प्रमुख चक्रवातों और उनके नामकरण करने वाले देशों की सूची बनाएं।","वर्ष 2024-25 के सभी 5 पद्म विभूषण विजेताओं और उनके क्षेत्रों के नाम याद करें।"],"practice_prompts_en":["List the 3 major cyclones that hit the Indian coast in the last 1 year and the countries that named them.","Memorize the names and fields of all 5 Padma Vibhushan winners of 2024-25."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('1fecfd62-1493-4ccf-8a8f-d914fa553c56', 'MP GK', 'mp-physical-geography-minerals', 'मध्य प्रदेश भौतिक भूगोल और खनिज', 'MP Physical Geography & Minerals', 'मध्य प्रदेश की नदियों के किनारे बसे शहर, जलवायु की विशेषताएँ, मिट्टी (काली मिट्टी) के गुण और प्रमुख खनिज भंडारों (तांबा, हीरा, मैंगनीज) का गहन विश्लेषण।', 1, 1773829298, 1773829298, '{"must_know_lists":[{"list_title":"म.प्र. के प्रमुख खनिज और उनके प्रसिद्ध क्षेत्र","list_title_en":"Major Minerals of MP and their Famous Areas","items":["तांबा - मलाजखंड (बालाघाट)","मैंगनीज - भारवेली (बालाघाट), गोदावरी घाटी (छिंदवाड़ा)","हीरा - हिनोता (पन्ना), मझगवां (पन्ना)","स्लेट - मंदसौर (भारत का एकमात्र स्लेट उत्पादक जिला)","बॉक्साइट - अमरकंटक (अनूपपुर/शहडोल)"],"items_en":["Copper - Malajkhand (Balaghat)","Manganese - Bharveli (Balaghat), Godavari Valley (Chhindwara)","Diamond - Hinota (Panna), Majhgawan (Panna)","Slate - Mandsaur (India''s only slate producing district)","Bauxite - Amarkantak (Anuppur/Shahdol)"],"memory_hook":"तांबा-मैंगनीज = बालाघाट, हीरा = पन्ना, स्लेट = मंदसौर","memory_hook_en":"Copper-Manganese = Balaghat, Diamond = Panna, Slate = Mandsaur"}],"concept_capsule":"मध्य प्रदेश के भूगोल में खनिज उत्पादन और नदियों के उद्गम/किनारे बसे शहरों से ''मैच द कॉलम'' (Match the following) प्रश्न निश्चित आते हैं। ISFR 2021 के अनुसार भिण्ड, उज्जैन और शाजापुर में वन आवरण सबसे कम है।","concept_capsule_en":"In MP Geography, ''Match the column'' questions from mineral production and river origins/riverside cities are certain. As per ISFR 2021, Bhind, Ujjain, and Shajapur have the lowest forest cover.","practice_prompts":["मैचिंग: वैनगंगा, चंबल, ताप्ती और बेतवा नदियों के उद्गम स्थलों का मिलान करें।","मध्य प्रदेश के किन तीन जिलों में वन आवरण का प्रतिशत सबसे कम है?"],"practice_prompts_en":["Matching: Match the origins of Wainganga, Chambal, Tapti, and Betwa rivers.","Which three districts of Madhya Pradesh have the lowest percentage of forest cover?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('4001a1e6-d4ad-49ca-bf87-3a52adb037da', 'MP GK', 'mp-history-freedom-struggle-archaeology', 'मध्य प्रदेश इतिहास, स्वतंत्रता संग्राम और पुरातत्व', 'MP History, Freedom Struggle & Archaeology', 'म.प्र. में स्वतंत्रता संग्राम के प्रमुख केंद्र (चरण पादुका, टुरिया सत्याग्रह), आदिवासी नायक, और विश्व धरोहर स्थल (भीमबैठका, बाघ गुफाएं)।', 1, 1773829299, 1773829299, '{"must_know_lists":[{"list_title":"म.प्र. में ब्रिटिश विरोधी प्रमुख घटनाएं","list_title_en":"Major Anti-British Events in MP","items":["1824 - सीहोर का विद्रोह (कुंवर चैन सिंह)","1857 - नीमच छावनी से म.प्र. में क्रांति शुरू","1859 - ठाकुर रणमत सिंह (रीवा) को आगरा में फाँसी","1930 - जंगल सत्याग्रह (सिवनी और बैतूल)","1931 - चरण पादुका गोलीकांड (छतरपुर)"],"items_en":["1824 - Sehore Rebellion (Kunwar Chain Singh)","1857 - Revolt started in MP from Neemuch Cantt","1859 - Thakur Ranmat Singh (Rewa) hanged in Agra","1930 - Jungle Satyagraha (Seoni and Betul)","1931 - Charan Paduka Massacre (Chhatarpur)"],"memory_hook":"Chain (24) -> Neemuch (57) -> Jungle (30) -> Charan (31)","memory_hook_en":"Chain (24) -> Neemuch (57) -> Jungle (30) -> Charan (31)"}],"concept_capsule":"मध्य प्रदेश के इतिहास में आदिवासी विद्रोह (भीमा नायक, खाज्या नायक, टंट्या भील, गंजन सिंह) और प्रमुख पुरातात्विक खोजों (भीमबैठका, एरण, नवदाटोली) पर सबसे ज्यादा फोकस रहता है। तिथियों और खोजकर्ताओं के नाम अचूक याद रखें।","concept_capsule_en":"MP History questions heavily focus on Tribal Rebellions (Bhima Nayak, Khajya Nayak, Tantia Bhil, Ganjan Singh) and major archaeological discoveries (Bhimbetka, Eran, Navdatoli). Accurately remember dates and discoverers.","practice_prompts":["मध्य प्रदेश के 3 यूनेस्को विश्व धरोहर स्थलों के नाम और उन्हें घोषित करने के वर्ष लिखें।","जबलपुर झंडा सत्याग्रह (1923) का नेतृत्व किन नेताओं ने किया था?"],"practice_prompts_en":["Write the names of the 3 UNESCO World Heritage Sites of MP and their respective years of declaration.","Which leaders led the Jabalpur Flag Satyagraha (1923)?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('97f7f232-419e-45bc-a59e-6281067b4ded', 'MP GK', 'mp-tribes-tribal-welfare-literature', 'मध्य प्रदेश जनजातियां, जनजातीय कल्याण और साहित्य', 'MP Tribes, Tribal Welfare & Literature', 'मध्य प्रदेश की विशेष पिछड़ी जनजातियाँ (PVTG), उनके कल्याण के लिए सरकारी योजनाएँ (आहार अनुदान), संस्थान (NIRTH) और साहित्य रचनाएँ।', 1, 1773829300, 1773829300, '{"must_know_lists":[{"list_title":"म.प्र. की आदिवासी कल्याण योजनाएँ","list_title_en":"Tribal Welfare Schemes of MP","items":["आहार अनुदान - PVTGs महिलाओं को पोषण भत्ते","शंकर शाह और रानी दुर्गावती पुरस्कार - ST मेधावी छात्र (10वीं/12वीं)","टंट्या भील स्वरोजगार योजना - एसटी युवाओं को ऋण","एकीकृत जनजातीय विकास परियोजना (ITDP) - म.प्र. में कुल 31 संचालित"],"items_en":["Aahar Anudan - Nutrition allowance to PVTG women","Shankar Shah & Rani Durgavati Award - ST Meritorious students (10th/12th)","Tantia Bhil Swarozgar Yojana - Loans to ST youth","Integrated Tribal Dev Project (ITDP) - 31 operational in MP"],"memory_hook":"शंकर-दुर्गावती पढ़ाई (Education), टंट्या भील कमाई (Employment), आहार पोषण (Nutrition)","memory_hook_en":"Shankar-Durgavati Education, Tantia Bhil Employment, Aahar Nutrition"}],"concept_capsule":"मध्य प्रदेश की जनसंख्या में ST वर्ग 21.1% है, इसलिए MPPSC का यह सबसे पसंदीदा ''निश्चित'' (Sure-shot) टॉपिक है। PVTGs (बैगा, भारिया, सहरिया) की भौगोलिक स्थिति, उनके नृत्य, विवाह प्रथाएँ और कल्याणकारी योजनाएँ विस्तार से पढ़ें।","concept_capsule_en":"Since the ST population in MP is 21.1%, this is MPPSC''s most favorite ''sure-shot'' topic. Study the geographical locations, dances, marriage customs, and welfare schemes of the PVTGs (Baiga, Bharia, Saharia) in detail.","practice_prompts":["बैगा, भारिया और सहरिया जनजातियों के मुख्य निवास जिलों को मैप पर चिह्नित करें।","गोंड और भील जनजातियों के प्रमुख नृत्यों (Dances) में क्या अंतर है?"],"practice_prompts_en":["Mark the main residential districts of Baiga, Bharia, and Saharia tribes on a map.","What are the major differences between the traditional dances of Gond and Bhil tribes?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('3569dcbc-e489-469f-8285-fa4aab7a40ad', 'MP GK', 'mp-economy-industry-govt-schemes', 'मध्य प्रदेश अर्थव्यवस्था, उद्योग और सरकारी योजनाएं', 'MP Economy, Industry & Govt Schemes', 'मध्य प्रदेश की औद्योगिक बेल्ट (सीमेंट, रिफाइनरी, एल्युमीनियम), ODOP उत्पाद और महिलाओं/युवाओं के लिए प्रमुख आर्थिक योजनाएँ।', 1, 1773829301, 1773829301, '{"must_know_lists":[{"list_title":"म.प्र. के प्रमुख औद्योगिक केंद्र (Industrial Hubs)","list_title_en":"Major Industrial Hubs of MP","items":["पीथमपुर - धार (ऑटोमोबाइल हब / Detroit of MP)","मंडीदीप - धार (ऑप्टिकल फाइबर)","बानमोर - मुरैना (सीमेंट, कत्था)","मालनपुर - भिण्ड (रक्षा उत्पादन, सूखा बंदरगाह)","मेघनगर - झाबुआ","मनेरी - मंडला"],"items_en":["Pithampur - Dhar (Automobile hub / Detroit of MP)","Mandideep - Dhar (Optical Fiber)","Banmore - Morena (Cement, Katha)","Malanpur - Bhind (Defense production, Dry port)","Meghnagar - Jhabua","Maneri - Mandla"],"memory_hook":"पीथम-धार, बान-मुरैना, माल-भिण्ड","memory_hook_en":"Pitham-Dhar, Ban-Morena, Mal-Bhind"}],"concept_capsule":"मध्य प्रदेश की अर्थव्यवस्था में मुख्यमंत्री की ''फ्लैगशिप'' योजनाएं (जैसे लाड़ली बहना, सीको कमाओ) और औद्योगिकीकरण (Industrial Parks) से हर साल सवाल आते हैं। साथ ही, 2011 से 2024 तक प्रति व्यक्ति आय में 4 गुनी वृद्धि जैसे मैक्रो-आर्थिक रुझान याद रखें।","concept_capsule_en":"In MP Economy, the Chief Minister''s ''Flagship'' schemes (like Ladli Behna, Seekho Kamao) and industrialization (Industrial Parks) yield questions every year. Also, remember macro-economic trends like the 4-fold increase in Per Capita Income from 2011 to 2024.","practice_prompts":["मध्य प्रदेश के ''एक जिला एक उत्पाद'' (ODOP) के तहत जबलपुर, रीवा और ग्वालियर के उत्पादों के नाम लिखें।","मध्य प्रदेश के 5 प्रमुख सूखा बंदरगाहों (Dry Ports) के नाम बताएं।"],"practice_prompts_en":["Write the names of the products of Jabalpur, Rewa, and Gwalior under MP''s ''One District One Product'' (ODOP).","Name the 5 major Dry Ports of Madhya Pradesh."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('0e82b86f-50f1-42b6-9cc1-b67d72341419', 'Polity', 'constitution-governance-important-articles', 'संविधान, शासन और महत्वपूर्ण अनुच्छेद', 'Constitution, Governance & Important Articles', 'भारतीय संविधान के महत्वपूर्ण अनुच्छेद (ST/SC आरक्षण), न्यायपालिका (बेसिक स्ट्रक्चर), और म.प्र. के राज्यपालों का कार्यकाल।', 1, 1773829302, 1773829302, '{"must_know_lists":[{"list_title":"भारतीय संविधान के लैंडमार्क जजमेंट और समितियां","list_title_en":"Landmark Judgments and Committees of Indian Constitution","items":["केशवानन्द भारती (1973) - आधारभूत ढाँचा (Basic Structure)","सप्रू समिति (1945) - न्यायपालिका की स्वतंत्रता और मौलिक अधिकार","फजल अली आयोग (1953) - राज्य पुनर्गठन (14 राज्य, 6 UT)","स्वर्ण सिंह समिति (1976) - मौलिक कर्तव्य"],"items_en":["Kesavananda Bharati (1973) - Basic Structure Doctrine","Sapru Committee (1945) - Judicial Independence & Fundamental Rights","Fazl Ali Commission (1953) - State Reorganization (14 States, 6 UTs)","Swaran Singh Committee (1976) - Fundamental Duties"],"memory_hook":"केशव का बेस (Basic), सप्रू का न्याय, फजल का राज्य।","memory_hook_en":"Keshav''s Base, Sapru''s Justice, Fazl''s State."}],"concept_capsule":"भारतीय राजव्यवस्था में आयोग (Commissions) और उनके अनुच्छेद, विशेषकर SC/ST/OBC वर्ग से संबंधित, MPPSC के फेवरेट हैं। इसके अतिरिक्त, राज्य के संदर्भ में (गवर्नर, सीएम की सूची और राष्ट्रपति शासन) हमेशा गहराई से पढ़ें।","concept_capsule_en":"In Indian Polity, Commissions and their Articles, especially relating to SC/ST/OBC, are MPPSC''s favorites. Additionally, read the State context (list of Governors, CMs, and President Rules) in extreme depth.","practice_prompts":["1977, 1980 और 1992 में मध्य प्रदेश में लगे राष्ट्रपति शासन के दौरान मुख्यमंत्री और राज्यपाल कौन थे?","अनुच्छेद 330, 331, 332 और 333 में क्या अंतर है?"],"practice_prompts_en":["Who were the CMs and Governors during the President''s Rule in MP in 1977, 1980, and 1992?","What is the difference between Articles 330, 331, 332, and 333?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('9d69a8ab-60c7-4e37-9989-770b7897c32c', 'Current Affairs', 'current-affairs-sports-science-tech', 'करंट अफेयर्स, खेल और विज्ञान तकनीक', 'Current Affairs, Sports & Science Tech', 'राष्ट्रीय अंतरिक्ष दिवस, खेल जगत के पदक विजेता (एशियाई खेल, T20 विश्व कप), और आधुनिक प्रौद्योगिकी (AI, FPGA, रोबोटिक्स)।', 1, 1773829304, 1773829304, '{"must_know_lists":[{"list_title":"हाल ही में घोषित महत्वपूर्ण राष्ट्रीय दिवस","list_title_en":"Recently Declared Important National Days","items":["23 अगस्त - राष्ट्रीय अंतरिक्ष दिवस (चंद्रयान-3)","15 नवंबर - जनजातीय गौरव दिवस (बिरसा मुंडा जयंती)","7 अगस्त - राष्ट्रीय भाला फेंक दिवस (नीरज चोपड़ा)","14 अगस्त - विभाजन विभीषिका स्मृति दिवस","26 दिसंबर - वीर बाल दिवस"],"items_en":["23 August - National Space Day (Chandrayaan-3)","15 November - Janjatiya Gaurav Divas (Birsa Munda)","7 August - National Javelin Day (Neeraj Chopra)","14 August - Partition Horrors Remembrance Day","26 December - Veer Baal Diwas"],"memory_hook":"अगस्त में भाला (7) और स्पेस (23)। नवंबर में गौरव (15)।","memory_hook_en":"Javelin (7) and Space (23) in August. Gaurav (15) in Nov."}],"concept_capsule":"करेंट अफेयर्स में ''स्पोर्ट्स'' (विशेषकर बड़े इवेंट्स जैसे वर्ल्ड कप, एशियन गेम्स, ओलंपिक्स) और ''साइंस एंड टेक'' (इसरो मिशन, AI) का बोलबाला है। नए घोषित राष्ट्रीय दिवसों से 1-2 प्रश्न पक्के हैं।","concept_capsule_en":"Current Affairs is dominated by ''Sports'' (major events like World Cups, Asian Games, Olympics) and ''Science & Tech'' (ISRO missions, AI). 1-2 questions from newly declared National Days are guaranteed.","practice_prompts":["पेरिस ओलंपिक 2024 में भारत के सभी 6 पदक विजेताओं और उनके खेलों के नाम लिखें।","आर्टिफिशियल इंटेलिजेंस में प्रयुक्त होने वाले प्रमुख चिप आर्किटेक्चर (GPU, TPU, FPGA) में क्या अंतर है?"],"practice_prompts_en":["Write the names of all 6 Indian medalists at the Paris Olympics 2024 and their respective sports.","What is the difference between major chip architectures (GPU, TPU, FPGA) used in Artificial Intelligence?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('64a26b2e-a3ce-43cc-a906-459770b4b964', 'Current Affairs', 'national-international-events-appointments-sports', 'राष्ट्रीय और अंतर्राष्ट्रीय घटनाएं, नियुक्तियां और खेल', 'National & International Events, Appointments & Sports', 'वर्ष 2023-24 की महत्वपूर्ण नियुक्तियाँ (लोकपाल), प्रमुख पुरस्कार (सांख्यिकी), विश्व रिकॉर्ड (उज्जैन की वैदिक घड़ी), और खेल जगत (शतरंज, क्रिकेट) के अद्यतन तथ्य।', 1, 1773829325, 1773829325, '{"must_know_lists":[{"list_title":"हाल के प्रमुख खेल और नियुक्तियाँ (2023-24)","list_title_en":"Recent Major Sports and Appointments (2023-24)","items":["लोकपाल अध्यक्ष - ए.एम. खानविलकर","राज्यसभा मनोनीत - सुधा मूर्ति (परोपकार/साहित्य)","शतरंज (FIDE कैंडिडेट्स) - डी. गुकेश","क्रिकेट - भारत ने इंग्लैंड को टेस्ट सीरीज में 4-1 से हराया"],"items_en":["Lokpal Chairman - A.M. Khanwilkar","Rajya Sabha Nominee - Sudha Murty (Philanthropy/Lit)","Chess (FIDE Candidates) - D. Gukesh","Cricket - India beat England 4-1 in Test Series"],"memory_hook":"खानविलकर लोकपाल, गुकेश शतरंज, मूर्ति राज्यसभा।","memory_hook_en":"Khanwilkar Lokpal, Gukesh Chess, Murty Rajya Sabha."}],"concept_capsule":"समसामयिक मामलों में MPPSC हमेशा ''प्रथम'', ''सबसे युवा'' या ''राष्ट्रीय महत्व'' की नियुक्तियों पर ध्यान केंद्रित करता है। साथ ही, नवीनतम क्रिकेट और शतरंज प्रतियोगिताओं के सटीक परिणाम याद रखें। भारत का बाह्य ऋण GDP का लगभग 18.6% (सितंबर 2023) था, जो अर्थव्यवस्था के समसामयिक डेटा का उदाहरण है।","concept_capsule_en":"In Current Affairs, MPPSC always focuses on ''firsts'', ''youngest'', or appointments of ''national importance''. Also, remember exact outcomes of recent cricket and chess tournaments. India''s external debt was ~18.6% of GDP (Sep 2023), exemplifying economy current affairs.","practice_prompts":["वर्तमान में भारत के मुख्य चुनाव आयुक्त और मुख्य सूचना आयुक्त कौन हैं?","पेरिस ओलंपिक 2024 में भारत के ध्वजवाहक कौन थे?"],"practice_prompts_en":["Who are the current Chief Election Commissioner and Chief Information Commissioner of India?","Who were India''s flag bearers at the Paris Olympics 2024?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('3368d533-4c6b-449f-bd78-05cb92c2d9e0', 'Geography', 'physical-environmental-economic-geography', 'भौतिक, पर्यावरण और आर्थिक भूगोल', 'Physical, Environmental & Economic Geography', 'भारत की नदियों के उद्गम, पर्वत चोटियों की ऊँचाई का क्रम, पर्यावरण संरक्षण से जुड़े अधिनियम, ओज़ोन मापन, और खनिज (कोयला, बॉक्साइट) उत्पादन के मुख्य राज्य।', 1, 1773829326, 1773829326, '{"must_know_lists":[{"list_title":"पर्यावरण और सतत विकास (Environment & SDGs)","list_title_en":"Environment & Sustainable Development","items":["SDG 1 - गरीबी की समाप्ति (No Poverty)","SDG 2 - भुखमरी से मुक्ति (Zero Hunger)","SDG 9 - उद्योग, नवाचार और अवसंरचना","अपघटक (Decomposers) - कवक (Fungi) और जीवाणु (Bacteria)"],"items_en":["SDG 1 - No Poverty","SDG 2 - Zero Hunger","SDG 9 - Industry, Innovation & Infrastructure","Decomposers - Fungi and Bacteria"],"memory_hook":"SDG 1=No Poor, 2=No Hungry, 9=Industry.","memory_hook_en":"SDG 1=No Poor, 2=No Hungry, 9=Industry."}],"concept_capsule":"भूगोल में खनिजों के भंडार बनाम उत्पादन वाले राज्यों में अंतर हमेशा टेस्ट किया जाता है। इसके अलावा, हिमालयी और प्रायद्वीपीय पर्वत चोटियों को उनकी ऊँचाई के क्रम में व्यवस्थित करना (Descending order) एक दोहराया जाने वाला पैटर्न है। जलवायु विज्ञान में, याद रखें कि एल नीनो (El Nino) वार्षिक घटना नहीं है, यह 2-7 वर्षों में एक बार होता है।","concept_capsule_en":"In Geography, the distinction between states leading in mineral reserves vs production is always tested. Additionally, arranging Himalayan and Peninsular peaks in descending order of height is a recurring pattern. In climatology, remember that El Nino is NOT an annual event; it occurs once every 2-7 years.","practice_prompts":["SDG 3, 4 और 5 किससे संबंधित हैं?","भारत की शीर्ष 5 सबसे लंबी नदियों को अवरोही क्रम में व्यवस्थित करें।"],"practice_prompts_en":["What are SDG 3, 4, and 5 related to?","Arrange the top 5 longest rivers of India in descending order."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('dafc8c11-df14-48ba-8007-3b255419641f', 'History', 'ancient-modern-indian-history-literature-mp-relevance', 'प्राचीन और आधुनिक भारतीय इतिहास, साहित्य और म.प्र. प्रासंगिकता', 'Ancient & Modern Indian History, Literature & MP Relevance', 'प्राचीन अभिलेख (दशपुर, सौंदनी), वैदिक संस्कृति, 1857 के विद्रोह के मध्य प्रदेश के नायक, और आधुनिक भारतीय राष्ट्रीय आंदोलन के महत्वपूर्ण मील के पत्थर।', 1, 1773829327, 1773829327, '{"must_know_lists":[{"list_title":"1857 की क्रांति और मध्य प्रदेश के प्रमुख नेतृत्वकर्ता","list_title_en":"1857 Revolt and Major Leaders in MP","items":["राजा मर्दन सिंह - भानपुर (ललितपुर/सागर क्षेत्र)","राजा बख्तवली - शाहगढ़","शहादत खान / मुराद अली - महू (इंदौर)","रानी अवंतीबाई - रामगढ़ (मंडला)","शेख रमजान - सागर"],"items_en":["Raja Mardan Singh - Bhanpur (Lalitpur/Sagar region)","Raja Bakhtwali - Shahgarh","Saadat Khan / Murad Ali - Mhow (Indore)","Rani Avantibai - Ramgarh (Mandla)","Sheikh Ramzan - Sagar"],"memory_hook":"महू में शहादत, शाहगढ़ में बख्तवली।","memory_hook_en":"Saadat in Mhow, Bakhtwali in Shahgarh."}],"concept_capsule":"मध्य प्रदेश के प्राचीन इतिहास में ''अभिलेखों के रचयिता'' (जैसे मंदसौर का वत्सभट्टि) एक अत्यंत गहराई वाला (Micro) विषय है। वैदिक युग के प्रशासनिक और सामाजिक नियम (जैसे विवाह, संस्कार, सभा/समिति) तथा 1857 के स्थानीय विद्रोहियों की उनके क्षेत्र (Match the column) से जोड़ी मिलाना MPPSC का निश्चित पैटर्न है।","concept_capsule_en":"In MP''s ancient history, ''composers of inscriptions'' (like Vatsabhatti of Mandsaur) is a highly micro-depth topic. Vedic administrative terms (Sabha/Samiti) and matching 1857 local rebels to their regions is a definitive MPPSC pattern.","practice_prompts":["ब्रह्म समाज की स्थापना कब हुई और 1866 में इसके विभाजन के क्या कारण थे?","मौर्यकालीन प्रशासन में ''सीताध्यक्ष'' और ''पण्याध्यक्ष'' के क्या कार्य थे?"],"practice_prompts_en":["When was Brahmo Samaj founded, and what were the reasons for its split in 1866?","What were the roles of ''Sitadhyaksha'' and ''Panyadhyaksha'' in Mauryan administration?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('f5335203-eb21-4d8c-bf2a-6a3ec06a440c', 'ICT', 'computer-basics-cyber-security-web-e-governance', 'कंप्यूटर मूल बातें, साइबर सुरक्षा, वेब और ई-गवर्नेंस', 'Computer Basics, Cyber Security, Web & E-Governance', 'सूचना संचार प्रौद्योगिकी (ICT) के अंतर्गत ऑपरेटिंग सिस्टम (UNIX), साइबर हमले (Phishing), वेब मानक (W3C), आर्टिफिशियल इंटेलिजेंस (Machine Learning) और ई-गवर्नेंस के बुनियादी स्तंभ।', 1, 1773829329, 1773829329, '{"must_know_lists":[{"list_title":"महत्वपूर्ण ICT फुल फॉर्म्स (Abbreviations)","list_title_en":"Important ICT Abbreviations","items":["W3C - World Wide Web Consortium","MPEG - Moving Picture Experts Group","JPEG - Joint Photographic Experts Group","FPGA - Field Programmable Gate Array","SMTP - Simple Mail Transfer Protocol"],"items_en":["W3C - World Wide Web Consortium","MPEG - Moving Picture Experts Group","JPEG - Joint Photographic Experts Group","FPGA - Field Programmable Gate Array","SMTP - Simple Mail Transfer Protocol"],"memory_hook":"W3=WWW, M=Moving, J=Joint","memory_hook_en":"W3=WWW, M=Moving, J=Joint"}],"concept_capsule":"सूचना एवं संचार प्रौद्योगिकी (ICT) में ''संस्थापक/खोजकर्ता'', ''फुल फॉर्म्स'' (W3C, MPEG), और साइबर हमलों की परिभाषा (Phishing, Spoofing) से सबसे सीधे सवाल बनते हैं। ई-गवर्नेंस के सैद्धांतिक हिस्से (स्तंभ, मॉडल) को ध्यान से पढ़ें क्योंकि वहाँ शब्दों (Process vs Program) में फंसाया जाता है।","concept_capsule_en":"In ICT, direct questions are formed from ''Founders/Inventors'', ''Abbreviations'' (W3C, MPEG), and definitions of Cyber Attacks (Phishing, Spoofing). Read the theoretical part of E-governance (pillars, models) carefully as traps are set using similar words (Process vs Program).","practice_prompts":["स्पाईवेयर, मैलवेयर और रैनसमवेयर के बीच मुख्य अंतर क्या है?","ई-कॉमर्स के B2B, B2C और C2C मॉडल्स के एक-एक उदाहरण दीजिए।"],"practice_prompts_en":["What is the main difference between Spyware, Malware, and Ransomware?","Give one example each of B2B, B2C, and C2C E-commerce models."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('b4386481-85c5-4d0b-88a9-dbb9ad638af0', 'Economy', 'economy-general-science', 'अर्थव्यवस्था और सामान्य विज्ञान', 'Economy & General Science', 'अर्थव्यवस्था के प्रमुख आंकड़े (बाह्य ऋण, SLR), मानव जीव विज्ञान (गुणसूत्र, कशेरुका), और पोषण/स्वास्थ्य से जुड़ी सरकारी योजनाएं (समग्र शिक्षा)।', 1, 1773829331, 1773829331, '{"must_know_lists":[{"list_title":"मानव शरीर की महत्वपूर्ण हड्डियां / संख्या","list_title_en":"Important Bones / Numbers of Human Body","items":["सर्वाइकल कशेरुकाएं (गर्दन) - 7","थोरैसिक कशेरुकाएं (वक्ष) - 12","लम्बर कशेरुकाएं (कमर) - 5","पसलियां (Ribs) - 12 जोड़े (24 हड्डियां)","सबसे छोटी हड्डी - स्टेपीज (कान)"],"items_en":["Cervical Vertebrae (Neck) - 7","Thoracic Vertebrae (Chest) - 12","Lumbar Vertebrae (Waist) - 5","Ribs - 12 pairs (24 bones)","Smallest bone - Stapes (Ear)"],"memory_hook":"C-7, T-12, L-5","memory_hook_en":"C-7, T-12, L-5"}],"concept_capsule":"जीव विज्ञान में आनुवंशिक रोग (Genetic disorders like Down syndrome) और पोषण संबंधी कमियों/विषाक्तता (Nutrition toxicity like Lathyrism) से सीधे प्रश्न पूछे जाते हैं। अर्थव्यवस्था में बैंकिंग सुधार (जैसे SLR की सीमा हटाना) और महत्वपूर्ण मैक्रोइकॉनॉमिक डेटा (जैसे GDP का 18.6% बाह्य ऋण) उच्च स्तर के (Bouncer) प्रश्न बनाते हैं।","concept_capsule_en":"In Biology, direct questions are asked from genetic disorders (Down syndrome) and nutritional toxicity (Lathyrism). In Economy, banking reforms (like removing SLR limits) and crucial macroeconomic data (like 18.6% external debt to GDP) form high-level ''bouncer'' questions.","practice_prompts":["CRASH (CRR) और SLR के बीच क्या अंतर है और इनका मुद्रास्फीति पर क्या प्रभाव पड़ता है?","हीमोफीलिया और कलर ब्लाइंडनेस (वर्णांधता) किस प्रकार के आनुवंशिक रोग हैं?"],"practice_prompts_en":["What is the difference between CRR and SLR, and how do they impact inflation?","What type of genetic disorders are Hemophilia and Color Blindness?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('3177dad0-3044-4b4b-a5cc-59b536b6c2e0', 'Current Affairs', 'international-summits-indias-performance-indices', 'अंतर्राष्ट्रीय शिखर सम्मेलन और भारत के प्रदर्शन सूचकांक', 'International Summits & India''s Performance Indices', 'वैश्विक शिखर सम्मेलनों का इतिहास (G20) और भारत के भीतर राज्यों के प्रदर्शन को मापने वाले महत्वपूर्ण सूचकांक (NITI Aayog SDG Index)।', 1, 1773829342, 1773829342, '{"must_know_lists":[{"list_title":"G20 शिखर सम्मेलनों की महत्वपूर्ण शृंखला (हालिया)","list_title_en":"Important Sequence of G20 Summits (Recent)","items":["2022 - इंडोनेशिया (बाली)","2023 - भारत (नई दिल्ली) - थीम: वसुधैव कुटुंबकम","2024 - ब्राज़ील (रियो डी जनेरियो)","2025 - दक्षिण अफ्रीका"],"items_en":["2022 - Indonesia (Bali)","2023 - India (New Delhi) - Theme: Vasudhaiva Kutumbakam","2024 - Brazil (Rio de Janeiro)","2025 - South Africa"],"memory_hook":"I-I-B-S (Indonesia, India, Brazil, South Africa) - Troika progression.","memory_hook_en":"I-I-B-S (Indonesia, India, Brazil, South Africa) - Troika progression."}],"concept_capsule":"Current Affairs में ''पहली बार'' हुई घटनाओं का ऐतिहासिक संदर्भ (जैसे G20 की शुरुआत) और नीति आयोग (NITI Aayog) द्वारा जारी किए जाने वाले प्रमुख सूचकांकों (SDG, Health, Export) की कार्यप्रणाली (Methodology) हमेशा महत्वपूर्ण होती है।","concept_capsule_en":"In Current Affairs, the historical context of ''first-time'' events (like the start of G20) and the methodology of major indices released by NITI Aayog (SDG, Health, Export) are always crucial.","practice_prompts":["नीति आयोग के ''बहुआयामी गरीबी सूचकांक'' (MPI) के तीन मुख्य आयाम (Dimensions) क्या हैं?","BRICS का पहला शिखर सम्मेलन कब और कहाँ हुआ था?"],"practice_prompts_en":["What are the three main dimensions of NITI Aayog''s ''Multidimensional Poverty Index'' (MPI)?","When and where was the first BRICS summit held?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('d737bfd1-8a80-441f-8437-2f599dd9911a', 'MP GK', 'mp-economy-agriculture-infrastructure', 'मध्य प्रदेश अर्थव्यवस्था, कृषि और बुनियादी ढांचा', 'MP Economy, Agriculture & Infrastructure', 'मध्य प्रदेश की अर्थव्यवस्था का मैक्रो-परिपक्ष्य (कारखानों का हिस्सा, प्रति व्यक्ति आय), कृषि (गेहूं, सोयाबीन, जीआई टैग), और प्रमुख जल/सिंचाई परियोजनाएं।', 1, 1773829343, 1773829343, '{"must_know_lists":[{"list_title":"मध्य प्रदेश की प्रमुख अंतर्राज्यीय नदी घाटी परियोजनाएं","list_title_en":"Major Interstate River Valley Projects of MP","items":["सरदार सरोवर (नर्मदा) - 4 राज्य (MP, GJ, MH, RJ)","बाणसागर (सोन) - 3 राज्य (MP, UP, Bihar - 2:1:1)","राजघाट / माताटीला (बेतवा) - 2 राज्य (MP, UP)","पेंच परियोजना - 2 राज्य (MP, MH)"],"items_en":["Sardar Sarovar (Narmada) - 4 states (MP, GJ, MH, RJ)","Bansagar (Son) - 3 states (MP, UP, Bihar - 2:1:1)","Rajghat / Matatila (Betwa) - 2 states (MP, UP)","Pench Project - 2 states (MP, MH)"],"memory_hook":"नर्मदा 4, सोन 3, बेतवा 2।","memory_hook_en":"Narmada 4, Son 3, Betwa 2."}],"concept_capsule":"मध्य प्रदेश की अर्थव्यवस्था में कृषि डेटा (Agri-data) का प्रभुत्व है। फसलों के उत्पत्ति स्थान (सोयाबीन-देवास), GI टैग वाले कृषि उत्पाद (चिन्नौर-बालाघाट, शरबती-सीहोर) और कृषि में तकनीक (UNNATI) से सीधे प्रश्न बनते हैं। सिंचाई परियोजनाओं में भागीदार राज्यों (Partner States) की संख्या और नाम कंठस्थ होने चाहिए।","concept_capsule_en":"Agri-data dominates the MP economy section. Direct questions are formed from crop origins (Soybean-Dewas), GI tagged agri-products (Chinnor-Balaghat, Sharbati-Sehore), and tech in agriculture (UNNATI). The number and names of partner states in irrigation projects must be memorized.","practice_prompts":["मध्य प्रदेश के 5 प्रमुख GI टैग प्राप्त कृषि उत्पादों और उनके जिलों के नाम लिखें।","चंबल घाटी परियोजना में MP और राजस्थान की हिस्सेदारी का अनुपात क्या है?"],"practice_prompts_en":["Write the names of 5 major GI tagged agricultural products of MP and their districts.","What is the sharing ratio between MP and Rajasthan in the Chambal Valley Project?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('084bb18e-c113-498f-8654-93d202c646be', 'MP GK', 'mp-art-culture-awards-demographics', 'मध्य प्रदेश कला, संस्कृति, पुरस्कार और जनसांख्यिकी', 'MP Art, Culture, Awards & Demographics', 'मध्य प्रदेश के लोक नाट्य (माच, गम्मत), लोकगीत (बिरहा), भित्ति चित्र (कोहबर), राज्य स्तरीय सम्मान (देवी अहिल्या, वीर शंकर शाह), और 2011 जनगणना के नगरीय आंकड़े।', 1, 1773829344, 1773829344, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के प्रमुख लोकनाट्य और उनके अंचल","list_title_en":"Major Folk Dramas of MP and their Regions","items":["मालवा - माच (राज्य नाट्य), भवाई","निमाड़ - गम्मत, रासलीला","बुंदेलखंड - स्वांग (Swang), अखाड़ा","बघेलखंड - छाहुर, मनसुखा, हिंगोला"],"items_en":["Malwa - Maach (State Drama), Bhavai","Nimar - Gammat, Rasleela","Bundelkhand - Swang, Akhada","Baghelkhand - Chhahur, Mansukha, Hingola"],"memory_hook":"मालवा का माच, निमाड़ की गम्मत, बुंदेल का स्वांग, बघेल का मनसुखा।","memory_hook_en":"Malwa''s Maach, Nimar''s Gammat, Bundel''s Swang, Baghel''s Mansukha."}],"concept_capsule":"मध्य प्रदेश की कला और संस्कृति खंड ''रटने'' (Rote learning) पर आधारित है। विशिष्ट कलाकारों के नाम (ओम प्रकाश शर्मा - माच), वाद्य यंत्र, लोकगीत/नृत्य के अंचल (Region) और राज्य स्तरीय सम्मानों के ''पात्रता मानदंड'' (Eligibility criteria) पर सूक्ष्म (Micro) सवाल आते हैं।","concept_capsule_en":"MP Art and Culture section relies heavily on rote learning. Micro questions are framed on names of specific artists (Om Prakash Sharma - Maach), instruments, regions of folk songs/dances, and ''eligibility criteria'' of state awards.","practice_prompts":["मध्य प्रदेश के तानसेन सम्मान और कालिदास सम्मान की स्थापना वर्ष और पुरस्कार राशि क्या है?","राई, बधाई और शैरा (Saira) लोकनृत्य किस अंचल से संबंधित हैं?"],"practice_prompts_en":["What are the establishment years and prize money for MP''s Tansen Samman and Kalidas Samman?","Rai, Badhai, and Saira folk dances belong to which region?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('395a2471-0203-4ae8-be96-83c9383a4e83', 'MP GK', 'mp-physical-geography-tribes-historical-personalities', 'मध्य प्रदेश भौतिक भूगोल, जनजातियां और ऐतिहासिक व्यक्तित्व', 'MP Physical Geography, Tribes & Historical Personalities', 'विंध्यन पठार (भाण्डेर), दक्षिण-पूर्वी मानसून वर्षा, खनिज उद्योग (रॉक फॉस्फेट), वन संसाधन (बाँस), और भील/गोंड आदिवासी नायकों का ऐतिहासिक महत्व।', 1, 1773829345, 1773829345, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के प्रमुख जिले और उनके अनूठे उत्पाद/विशेषताएँ","list_title_en":"Major Districts of MP and their Unique Products/Features","items":["अशोकनगर - चंदेरी साड़ियाँ","खरगोन - महेश्वरी साड़ियाँ (अहिल्याबाई होलकर)","बुरहानपुर - केले का उत्पादन","मंदसौर - लहसुन (और अफीम, स्लेट)","धार - मोहनखेड़ा जैन तीर्थ, बाघ गुफाएं"],"items_en":["Ashoknagar - Chanderi Sarees","Khargone - Maheshwari Sarees (Ahilyabai Holkar)","Burhanpur - Banana production","Mandsaur - Garlic (also Opium, Slate)","Dhar - Mohankheda Jain Tirth, Bagh Caves"],"memory_hook":"चंदेरी अशोक, महेश्वर खरगोन, बुरहानपुर केला।","memory_hook_en":"Chanderi Ashok, Maheshwar Khargone, Burhanpur Banana."}],"concept_capsule":"मध्य प्रदेश के प्राचीन इतिहास (ताम्रपाषाण स्थल), जनजातीय नायकों के स्वतंत्रता संग्राम में योगदान, और विशिष्ट भौगोलिक स्थानों (जियो पार्क, जैन तीर्थ, अभयारण्य) को जिलों (Districts) से मैप करना MPPSC का सबसे महत्वपूर्ण पैटर्न है। हर स्थान का जिला कंठस्थ होना चाहिए।","concept_capsule_en":"Mapping MP''s ancient history (Chalcolithic sites), tribal heroes'' contribution to freedom struggle, and specific geographical locations (Geo parks, Jain Tirths, Sanctuaries) to their respective ''Districts'' is the most critical MPPSC pattern. The district for every location must be memorized.","practice_prompts":["मध्य प्रदेश के 5 प्रमुख ताम्रपाषाण कालीन (Chalcolithic) स्थलों और उनके जिलों के नाम लिखें।","टंट्या भील, भीमा नायक और खाज्या नायक के विद्रोह का मुख्य भौगोलिक क्षेत्र (अंचल) कौन सा था?"],"practice_prompts_en":["Write the names of 5 major Chalcolithic sites of MP and their districts.","What was the main geographical region (Anchal) of the rebellion by Tantia Bhil, Bhima Nayak, and Khajya Nayak?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('2447de5b-d3c7-4361-a7f2-71af9b24a8b3', 'Polity', 'constitutional-amendments-institutions-high-level-appointments', 'संवैधानिक संशोधन, संस्थान और उच्च स्तरीय नियुक्तियां', 'Constitutional Amendments, Institutions & High-Level Appointments', 'मौलिक अधिकारों बनाम DPSP का संघर्ष, महान्यायवादी (AG) की नियुक्ति, चुनाव आयोग की कार्यप्रणाली, और आपातकाल (Art 352) से जुड़े संविधान संशोधन।', 1, 1773829348, 1773829348, '{"must_know_lists":[{"list_title":"संविधान के महत्वपूर्ण बहुमत (Majorities) नियम","list_title_en":"Important Majority Rules in Constitution","items":["राष्ट्रपति पर महाभियोग (Art 61) - संसद के ''कुल सदस्यों'' का 2/3 बहुमत","संविधान संशोधन (Art 368) - उपस्थित और मतदान करने वालों का 2/3 + सदन का कुल बहुमत","संघीय संशोधन (Art 368) - विशेष बहुमत + आधे से अधिक राज्यों की विधानसभाओं का संकल्प","आपातकाल अनुमोदन - विशेष बहुमत (44वें संशोधन के बाद)"],"items_en":["Impeachment of President (Art 61) - 2/3rd of ''Total Membership'' of Parliament","Const. Amendment (Art 368) - 2/3rd Present & Voting + Absolute Majority","Federal Amendment (Art 368) - Special Majority + Ratification by 1/2 State Legislatures","Emergency Approval - Special Majority (post 44th Amendment)"],"memory_hook":"महाभियोग सबसे कठिन (Total 2/3)। संघीय ढांचा = संसद + राज्य।","memory_hook_en":"Impeachment is toughest (Total 2/3). Federal = Parliament + States."}],"concept_capsule":"भारतीय राजव्यवस्था में आयोग (Election Commission), विधि अधिकारी (AG, Advocate General) की नियुक्ति/योग्यताएं और 42वें/44वें संविधान संशोधन के सूक्ष्म प्रभाव (Micro-impacts) पर उच्च-स्तरीय प्रश्न बनते हैं। ''प्रसादपर्यंत'' (Doctrine of Pleasure) का सिद्धांत किस पद पर लागू होता है, यह स्पष्ट होना चाहिए।","concept_capsule_en":"In Indian Polity, high-level questions are framed on Commissions (EC), Law Officers (AG, Advocate General) appointments/qualifications, and the micro-impacts of the 42nd/44th Amendments. It must be clear which posts operate under the ''Doctrine of Pleasure''.","practice_prompts":["संविधान की ''प्रारूप समिति'' (Drafting Committee) के सभी 7 सदस्यों के नाम लिखिए।","अनुच्छेद 352, 356 और 360 के तहत घोषित होने वाले आपातकालों के बीच 3 मुख्य अंतर क्या हैं?"],"practice_prompts_en":["Write the names of all 7 members of the Drafting Committee of the Constitution.","What are the 3 main differences between emergencies declared under Articles 352, 356, and 360?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('b6e19726-f0a7-4983-8d7e-5b769b3fa900', 'Science', 'space-missions-isro-milestones', 'अंतरिक्ष मिशन और इसरो उपलब्धियां', 'Space Missions & ISRO Milestones', 'भारतीय अंतरिक्ष अनुसंधान संगठन (ISRO) के ऐतिहासिक मील के पत्थर, जिसमें 104 उपग्रहों का विश्व रिकॉर्ड और भारत का पहला अंतर-ग्रहीय (Inter-planetary) मिशन शामिल है।', 1, 1773829349, 1773829349, '{"must_know_lists":[{"list_title":"ISRO के ऐतिहासिक मिशन और उनके प्रक्षेपण यान (Launch Vehicles)","list_title_en":"ISRO''s Historic Missions and their Launch Vehicles","items":["चंद्रयान-1 (2008) - PSLV-C11","मंगलयान (2013) - PSLV-C25","104 उपग्रह रिकॉर्ड (2017) - PSLV-C37","चंद्रयान-2 (2019) - GSLV Mk III-M1","चंद्रयान-3 (2023) - LVM3-M4"],"items_en":["Chandrayaan-1 (2008) - PSLV-C11","Mangalyaan (2013) - PSLV-C25","104 Satellites Record (2017) - PSLV-C37","Chandrayaan-2 (2019) - GSLV Mk III-M1","Chandrayaan-3 (2023) - LVM3-M4"],"memory_hook":"Ch-1(C11), Mangal(C25), 104(C37), Ch-3(LVM3).","memory_hook_en":"Ch-1(C11), Mangal(C25), 104(C37), Ch-3(LVM3)."}],"concept_capsule":"विज्ञान और प्रौद्योगिकी (Science & Tech) खंड में ISRO के मिशन MPPSC के लिए ''हॉट टॉपिक'' हैं। मिशन का नाम, लॉन्च का वर्ष और विशेष रूप से उपयोग किए गए ''प्रक्षेपण यान'' (Launch Vehicle जैसे PSLV/GSLV का विशिष्ट कोड) को सख्ती से याद करें।","concept_capsule_en":"ISRO missions are ''Hot Topics'' for MPPSC in the Science & Tech section. Strictly memorize the mission name, launch year, and specifically the ''Launch Vehicle'' used (the specific code like PSLV/GSLV).","practice_prompts":["आदित्य-L1 (Aditya-L1) मिशन का प्राथमिक उद्देश्य क्या है और इसे किस रॉकेट से लॉन्च किया गया?","गगनयान (Gaganyaan) मिशन के 3 मुख्य चरण क्या हैं?"],"practice_prompts_en":["What is the primary objective of the Aditya-L1 mission and which rocket launched it?","What are the 3 main phases of the Gaganyaan mission?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('3d7d42aa-dd68-4046-82fc-92b54b497c84', 'ICT', 'current-affairs-persons-in-news-sports', 'करंट अफेयर्स - चर्चा में व्यक्ति और खेल', 'Current Affairs - Persons in News & Sports', 'वर्ष 2023-24 में भारत के प्रमुख पदों पर नियुक्तियाँ (लोकपाल), अंतर्राष्ट्रीय सम्मान प्राप्तकर्ता (सांख्यिकी) और वैश्विक खेल प्रतियोगिताओं (शतरंज, क्रिकेट) के परिणाम।', 1, 1773829365, 1773829365, '{"must_know_lists":[{"list_title":"हाल के प्रमुख खेल और नियुक्तियाँ (2023-24)","list_title_en":"Recent Major Sports and Appointments (2023-24)","items":["लोकपाल अध्यक्ष - ए.एम. खानविलकर","राज्यसभा मनोनीत - सुधा मूर्ति (परोपकार/साहित्य)","शतरंज (FIDE कैंडिडेट्स) - डी. गुकेश","सांख्यिकी अंतर्राष्ट्रीय पुरस्कार - सी.आर. राव"],"items_en":["Lokpal Chairman - A.M. Khanwilkar","Rajya Sabha Nominee - Sudha Murty (Philanthropy/Lit)","Chess (FIDE Candidates) - D. Gukesh","Statistics International Prize - C.R. Rao"],"memory_hook":"खानविलकर लोकपाल, गुकेश शतरंज, मूर्ति राज्यसभा।","memory_hook_en":"Khanwilkar Lokpal, Gukesh Chess, Murty Rajya Sabha."}],"concept_capsule":"समसामयिक मामलों में MPPSC हमेशा ''प्रथम'', ''सबसे युवा'' (जैसे गुकेश) या ''राष्ट्रीय महत्व'' की नियुक्तियों (जैसे लोकपाल) पर ध्यान केंद्रित करता है। साथ ही, नवीनतम क्रिकेट श्रृंखलाओं (विशेषकर घरेलू मैदान पर) के सटीक परिणाम याद रखें।","concept_capsule_en":"In Current Affairs, MPPSC always focuses on ''firsts'', ''youngest'' (like Gukesh), or appointments of ''national importance'' (like Lokpal). Also, remember exact outcomes of recent cricket series (especially on home ground).","practice_prompts":["वर्तमान में भारत के मुख्य चुनाव आयुक्त (CEC) कौन हैं?","पेरिस ओलंपिक 2024 में भारत के ध्वजवाहक कौन थे?"],"practice_prompts_en":["Who is the current Chief Election Commissioner (CEC) of India?","Who were India''s flag bearers at the Paris Olympics 2024?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('d99b61cb-66d1-4511-a938-ca39e91f899c', 'Geography', 'environment-acts-summits-mp-innovations', 'पर्यावरण अधिनियम, शिखर सम्मेलन और म.प्र. नवाचार', 'Environment Acts, Summits & MP Innovations', 'पर्यावरण संरक्षण के महत्वपूर्ण अधिनियम (जल अधिनियम), वैश्विक शिखर सम्मेलनों का इतिहास (G20), और विश्व की पहली वैदिक घड़ी।', 1, 1773829365, 1773829365, '{"must_know_lists":[{"list_title":"पर्यावरण संरक्षण अधिनियम क्रोनोलॉजी","list_title_en":"Chronology of Environment Protection Acts","items":["1972 - वन्यजीव संरक्षण अधिनियम","1974 - जल (प्रदूषण निवारण) अधिनियम","1980 - वन संरक्षण अधिनियम","1981 - वायु (प्रदूषण निवारण) अधिनियम","1986 - पर्यावरण संरक्षण अधिनियम (छाता विधान)"],"items_en":["1972 - Wildlife Protection Act","1974 - Water (Prevention of Pollution) Act","1980 - Forest Conservation Act","1981 - Air (Prevention of Pollution) Act","1986 - Environment Protection Act (Umbrella Legislation)"],"memory_hook":"72-Wild, 74-Water, 80-Forest, 81-Air, 86-Env.","memory_hook_en":"72-Wild, 74-Water, 80-Forest, 81-Air, 86-Env."}],"concept_capsule":"भारत में पर्यावरण अधिनियमों का क्रम (Chronology) MPPSC का पसंदीदा है। ''पहली बार'' हुई घटनाओं का ऐतिहासिक संदर्भ (जैसे G20 की शुरुआत) और म.प्र. की अनूठी पहल (वैदिक घड़ी) को हमेशा प्राथमिकता दें।","concept_capsule_en":"The chronology of Environmental Acts in India is an MPPSC favorite. Always prioritize the historical context of ''first-time'' events (like the start of G20) and unique initiatives of MP (Vedic Clock).","practice_prompts":["BRICS का पहला शिखर सम्मेलन कब और कहाँ हुआ था?","जैव विविधता अधिनियम (Biodiversity Act) किस वर्ष पारित किया गया था?"],"practice_prompts_en":["When and where was the first BRICS summit held?","In which year was the Biodiversity Act passed?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('cc283dd9-e577-48b4-b3a3-f22db60045e8', 'Geography', 'physical-geography-climate-ecology', 'भौतिक भूगोल, जलवायु और पारिस्थितिकी', 'Physical Geography, Climate & Ecology', 'चक्रवात (तौक्ते), ओज़ोन मापन (डब्सन), जलीय पारिस्थितिकी (अपघटक), और एल नीनो की अवधारणा।', 1, 1773829366, 1773829366, '{"must_know_lists":[{"list_title":"हाल के प्रमुख चक्रवात और प्रभावित तट","list_title_en":"Recent Major Cyclones and Affected Coasts","items":["तौक्ते (2021) - पश्चिमी तट (गुजरात)","यास (2021) - पूर्वी तट (ओडिशा/बंगाल)","बिपरजॉय (2023) - पश्चिमी तट (गुजरात)","फेंगल (2024) - पूर्वी तट (तमिलनाडु)"],"items_en":["Tauktae (2021) - West Coast (Gujarat)","Yaas (2021) - East Coast (Odisha/Bengal)","Biparjoy (2023) - West Coast (Gujarat)","Fengal (2024) - East Coast (Tamil Nadu)"],"memory_hook":"तौक्ते और बिपरजॉय पश्चिम में, यास और फेंगल पूर्व में।","memory_hook_en":"Tauktae and Biparjoy in West, Yaas and Fengal in East."}],"concept_capsule":"भूगोल में पर्यावरण पारिस्थितिकी (अपघटक, ओज़ोन) और जलवायु विज्ञान (एल नीनो) की बुनियादी समझ आवश्यक है। हाल के चक्रवातों के नाम और उनके प्रभावित क्षेत्रों (पूर्वी बनाम पश्चिमी तट) को याद रखना करंट अफेयर्स के नजरिए से महत्वपूर्ण है।","concept_capsule_en":"Basic understanding of environmental ecology (Decomposers, Ozone) and climatology (El Nino) is essential in Geography. Remembering the names of recent cyclones and their affected areas (East vs. West Coast) is important from a current affairs perspective.","practice_prompts":["ला नीना (La Nina) का भारतीय मानसून पर क्या प्रभाव पड़ता है?","पारिस्थितिकी तंत्र में प्राथमिक और द्वितीयक उपभोक्ताओं के बीच क्या अंतर है?"],"practice_prompts_en":["What is the impact of La Nina on the Indian Monsoon?","What is the difference between primary and secondary consumers in an ecosystem?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('c67c15c2-02b7-4dd3-aa59-39a7f6aac252', 'Geography', 'indian-geography-minerals-topography-demographics', 'भारतीय भूगोल - खनिज, स्थलाकृति और जनसांख्यिकी', 'Indian Geography - Minerals, Topography & Demographics', 'भारत के प्रमुख खनिज भंडार (कोयला, बॉक्साइट), नदियों का मिलान, पर्वत चोटियों की ऊँचाई और 2011 जनगणना के महत्वपूर्ण आंकड़े (न्यूनतम घनत्व)।', 1, 1773829367, 1773829367, '{"must_know_lists":[{"list_title":"भारत के प्रमुख खनिज और उनके भंडार राज्य","list_title_en":"Major Minerals of India and their Reserve States","items":["कोयला (भंडार) - झारखंड, ओडिशा","बॉक्साइट - ओडिशा (50%+)","लौह अयस्क (हेमेटाइट) - ओडिशा","तांबा - राजस्थान (भंडार), म.प्र. (उत्पादन)"],"items_en":["Coal (Reserves) - Jharkhand, Odisha","Bauxite - Odisha (50%+)","Iron Ore (Hematite) - Odisha","Copper - Rajasthan (Reserves), MP (Production)"],"memory_hook":"ओडिशा खनिजों (बॉक्साइट, लोहा, कोयला) का पावरहाउस है।","memory_hook_en":"Odisha is the powerhouse of minerals (Bauxite, Iron, Coal)."}],"concept_capsule":"भूगोल में खनिजों के ''भंडार'' (Reserves) बनाम ''उत्पादन'' (Production) वाले राज्यों में अंतर हमेशा टेस्ट किया जाता है। इसके अलावा, प्रायद्वीपीय पर्वत चोटियों को उनकी ऊँचाई के क्रम में व्यवस्थित करना और नदियों के उद्गम स्थलों का मिलान एक दोहराया जाने वाला पैटर्न है।","concept_capsule_en":"In Geography, the distinction between states leading in mineral ''reserves'' vs ''production'' is always tested. Additionally, arranging peninsular peaks in order of height and matching river origins is a recurring pattern.","practice_prompts":["भारत की शीर्ष 5 सबसे लंबी नदियों को अवरोही क्रम में व्यवस्थित करें।","2011 की जनगणना के अनुसार भारत के सर्वाधिक और न्यूनतम जनसंख्या घनत्व वाले राज्य कौन से हैं?"],"practice_prompts_en":["Arrange the top 5 longest rivers of India in descending order.","Which are the states with the highest and lowest population density in India according to the 2011 census?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('abe4ebc3-3e52-4cda-9b47-de9cf79a0a12', 'Economy', 'macroeconomics-external-debt-sdg-goals', 'मैक्रोइकॉनॉमिक्स, विदेशी ऋण और एसडीजी लक्ष्य', 'Macroeconomics, External Debt & SDG Goals', 'अर्थव्यवस्था के प्रमुख आंकड़े (बाह्य ऋण, SLR), और नीति आयोग/UN के सतत विकास लक्ष्यों (SDGs) का ज्ञान।', 1, 1773829368, 1773829368, '{"must_know_lists":[{"list_title":"पहले 5 सतत विकास लक्ष्य (SDGs)","list_title_en":"First 5 Sustainable Development Goals (SDGs)","items":["SDG 1 - गरीबी की पूर्णतः समाप्ति (No Poverty)","SDG 2 - भुखमरी की समाप्ति (Zero Hunger)","SDG 3 - अच्छा स्वास्थ्य और जीवन स्तर (Good Health)","SDG 4 - गुणवत्तापूर्ण शिक्षा (Quality Education)","SDG 5 - लैंगिक समानता (Gender Equality)"],"items_en":["SDG 1 - No Poverty","SDG 2 - Zero Hunger","SDG 3 - Good Health and Well-being","SDG 4 - Quality Education","SDG 5 - Gender Equality"],"memory_hook":"गरीबी (1) मिटेगी तो भूख (2) मिटेगी, स्वास्थ्य (3) सुधरेगा, शिक्षा (4) मिलेगी और समानता (5) आएगी।","memory_hook_en":"No Poverty(1) leads to No Hunger(2), better Health(3), Education(4), and Equality(5)."}],"concept_capsule":"अर्थव्यवस्था में बैंकिंग सुधार (जैसे SLR की सीमा हटाना) और महत्वपूर्ण मैक्रोइकॉनॉमिक डेटा (जैसे GDP का 18.6% बाह्य ऋण) उच्च स्तर के (Bouncer) प्रश्न बनाते हैं। SDGs के क्रमांक (1 से 17) को याद रखना MPPSC के लिए बहुत स्कोरिंग (High-yield) है।","concept_capsule_en":"In Economy, banking reforms (like removing SLR limits) and crucial macroeconomic data (like 18.6% external debt to GDP) form high-level ''bouncer'' questions. Memorizing the SDG numbers (1 to 17) is highly scoring for MPPSC.","practice_prompts":["CRR और SLR के बीच क्या अंतर है और इनका मुद्रास्फीति (Inflation) पर क्या प्रभाव पड़ता है?","SDG 13 और SDG 14 किससे संबंधित हैं?"],"practice_prompts_en":["What is the difference between CRR and SLR, and how do they impact inflation?","What are SDG 13 and SDG 14 related to?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('de0e4e88-b3ab-48ff-851b-cc698379fd97', 'Science', 'human-biology-education-schemes', 'मानव जीव विज्ञान और शिक्षा योजनाएं', 'Human Biology & Education Schemes', 'मानव आनुवंशिकी (डाउन सिंड्रोम), शारीरिक रचना (गर्दन की हड्डियां), पोषण जनित रोग (लेथाइरिज्म), और स्कूली शिक्षा की समग्र योजना।', 1, 1773829368, 1773829368, '{"must_know_lists":[{"list_title":"मानव शरीर की महत्वपूर्ण हड्डियां / संख्या","list_title_en":"Important Bones / Numbers of Human Body","items":["सर्वाइकल कशेरुकाएं (गर्दन) - 7","थोरैसिक कशेरुकाएं (वक्ष) - 12","लम्बर कशेरुकाएं (कमर) - 5","पसलियां (Ribs) - 12 जोड़े (24 हड्डियां)","सबसे छोटी हड्डी - स्टेपीज (कान)"],"items_en":["Cervical Vertebrae (Neck) - 7","Thoracic Vertebrae (Chest) - 12","Lumbar Vertebrae (Waist) - 5","Ribs - 12 pairs (24 bones)","Smallest bone - Stapes (Ear)"],"memory_hook":"C-7, T-12, L-5","memory_hook_en":"C-7, T-12, L-5"}],"concept_capsule":"जीव विज्ञान में आनुवंशिक रोग (Genetic disorders like Down syndrome) और पोषण संबंधी कमियों/विषाक्तता (Nutrition toxicity like Lathyrism) से सीधे प्रश्न पूछे जाते हैं। मानव कंकाल तंत्र (Skeletal System) के मूल तथ्य (जैसे हड्डियों की संख्या) हमेशा उच्च-उपज वाले होते हैं।","concept_capsule_en":"In Biology, direct questions are asked from genetic disorders (Down syndrome) and nutritional toxicity (Lathyrism). Basic facts of the human Skeletal System (like the number of bones) are always high-yield.","practice_prompts":["हीमोफीलिया और कलर ब्लाइंडनेस (वर्णांधता) किस प्रकार के आनुवंशिक रोग हैं?","क्वाशिओरकोर (Kwashiorkor) और मैरास्मस (Marasmus) रोगों का मुख्य कारण क्या है?"],"practice_prompts_en":["What type of genetic disorders are Hemophilia and Color Blindness?","What is the main cause of Kwashiorkor and Marasmus diseases?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('f6935e7f-2d37-4e4d-8ee7-106b0e8f47ed', 'History', 'ancient-modern-indian-history', 'प्राचीन और आधुनिक भारतीय इतिहास', 'Ancient & Modern Indian History', 'प्राचीन काल के अभिलेख (मंदसौर, सौंदनी), मौर्य प्रशासन (प्रदेष्टा), 1857 के विद्रोह के केंद्र, और आधुनिक काल के साहित्य व समाज सुधार आंदोलन।', 1, 1773829369, 1773829369, '{"must_know_lists":[{"list_title":"1857 की क्रांति और मध्य प्रदेश के प्रमुख नेतृत्वकर्ता","list_title_en":"1857 Revolt and Major Leaders in MP","items":["राजा मर्दन सिंह - भानपुर (ललितपुर/सागर क्षेत्र)","राजा बख्तवली - शाहगढ़","शहादत खान / मुराद अली - महू (इंदौर)","रानी अवंतीबाई - रामगढ़ (मंडला)","शेख रमजान - सागर"],"items_en":["Raja Mardan Singh - Bhanpur (Lalitpur/Sagar region)","Raja Bakhtwali - Shahgarh","Saadat Khan / Murad Ali - Mhow (Indore)","Rani Avantibai - Ramgarh (Mandla)","Sheikh Ramzan - Sagar"],"memory_hook":"महू में शहादत, शाहगढ़ में बख्तवली।","memory_hook_en":"Saadat in Mhow, Bakhtwali in Shahgarh."}],"concept_capsule":"मध्य प्रदेश के प्राचीन इतिहास में ''अभिलेखों के रचयिता'' (जैसे मंदसौर का वत्सभट्टि) एक अत्यंत गहराई वाला (Micro) विषय है। वैदिक युग के प्रशासनिक और सामाजिक नियम (जैसे विवाह, संस्कार, सभा/समिति) तथा 1857 के स्थानीय विद्रोहियों की उनके क्षेत्र (Match the column) से जोड़ी मिलाना MPPSC का निश्चित पैटर्न है।","concept_capsule_en":"In MP''s ancient history, ''composers of inscriptions'' (like Vatsabhatti of Mandsaur) is a highly micro-depth topic. Vedic administrative terms (Sabha/Samiti) and matching 1857 local rebels to their regions is a definitive MPPSC pattern.","practice_prompts":["ब्रह्म समाज की स्थापना कब हुई और 1866 में इसके विभाजन के क्या कारण थे?","मौर्यकालीन प्रशासन में ''सीताध्यक्ष'' और ''पण्याध्यक्ष'' के क्या कार्य थे?"],"practice_prompts_en":["When was Brahmo Samaj founded, and what were the reasons for its split in 1866?","What were the roles of ''Sitadhyaksha'' and ''Panyadhyaksha'' in Mauryan administration?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('0ed066be-2e29-4c1c-9267-60d9bc79e6ad', 'ICT', 'computer-architecture-cyber-security-e-governance-social-media', 'कंप्यूटर आर्किटेक्चर, साइबर सुरक्षा, ई-गवर्नेंस और सोशल मीडिया', 'Computer Architecture, Cyber Security, E-Governance & Social Media', 'ऑपरेटिंग सिस्टम का कोर (कर्नल), फिशिंग जैसे साइबर खतरे, W3C और MPEG जैसे तकनीकी मानक, ट्यूरिंग टेस्ट का इतिहास और ई-गवर्नेंस के स्तंभ।', 1, 1773829371, 1773829371, '{"must_know_lists":[{"list_title":"महत्वपूर्ण ICT फुल फॉर्म्स (Abbreviations)","list_title_en":"Important ICT Abbreviations","items":["W3C - World Wide Web Consortium","MPEG - Moving Picture Experts Group","JPEG - Joint Photographic Experts Group","FPGA - Field Programmable Gate Array","SMTP - Simple Mail Transfer Protocol"],"items_en":["W3C - World Wide Web Consortium","MPEG - Moving Picture Experts Group","JPEG - Joint Photographic Experts Group","FPGA - Field Programmable Gate Array","SMTP - Simple Mail Transfer Protocol"],"memory_hook":"W3=WWW, M=Moving, J=Joint","memory_hook_en":"W3=WWW, M=Moving, J=Joint"}],"concept_capsule":"सूचना एवं संचार प्रौद्योगिकी (ICT) में ''संस्थापक/खोजकर्ता'', ''फुल फॉर्म्स'' (W3C, MPEG), और साइबर हमलों की परिभाषा (Phishing, Spoofing) से सबसे सीधे सवाल बनते हैं। ई-गवर्नेंस के सैद्धांतिक हिस्से (स्तंभ, मॉडल) को ध्यान से पढ़ें क्योंकि वहाँ शब्दों (Process vs Program) में फंसाया जाता है।","concept_capsule_en":"In ICT, direct questions are formed from ''Founders/Inventors'', ''Abbreviations'' (W3C, MPEG), and definitions of Cyber Attacks (Phishing, Spoofing). Read the theoretical part of E-governance (pillars, models) carefully as traps are set using similar words (Process vs Program).","practice_prompts":["स्पाईवेयर, मैलवेयर और रैनसमवेयर के बीच मुख्य अंतर क्या है?","ई-कॉमर्स के B2B, B2C और C2C मॉडल्स के एक-एक उदाहरण दीजिए।"],"practice_prompts_en":["What is the main difference between Spyware, Malware, and Ransomware?","Give one example each of B2B, B2C, and C2C E-commerce models."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('5e666709-ac5e-4e0e-a100-4ee5e9044e0d', 'ICT', 'current-affairs-important-days-appointments', 'करंट अफेयर्स - महत्वपूर्ण दिवस और नियुक्तियां', 'Current Affairs - Important Days & Appointments', 'संयुक्त राष्ट्र द्वारा घोषित महत्वपूर्ण अंतर्राष्ट्रीय वर्ष, योग दिवस का इतिहास, और भारत में प्रमुख पदों पर नियुक्तियाँ।', 1, 1773829386, 1773829386, '{"must_know_lists":[{"list_title":"हाल के महत्वपूर्ण अंतर्राष्ट्रीय वर्ष (UN)","list_title_en":"Recent Important International Years (UN)","items":["2022 - सतत पर्वतीय विकास का अंतर्राष्ट्रीय वर्ष","2023 - अंतर्राष्ट्रीय मोटा अनाज (Millets) वर्ष","2024 - अंतर्राष्ट्रीय कैमेलिड (Camelids) वर्ष","2025 - अंतर्राष्ट्रीय ग्लेशियर संरक्षण वर्ष"],"items_en":["2022 - International Year of Sustainable Mountain Development","2023 - International Year of Millets","2024 - International Year of Camelids","2025 - International Year of Glaciers'' Preservation"],"memory_hook":"पहाड़ (22) पर बाजरा (23) खाते हुए ऊंट (24) ग्लेशियर (25) की ओर गए।","memory_hook_en":"Camel (24) eating Millets (23) on Mountain (22) went towards Glacier (25)."}],"concept_capsule":"समसामयिक मामलों में ''संयुक्त राष्ट्र द्वारा घोषित वर्ष/दशक'' और ''भारत में प्रथम महिला'' (रक्षा/अंतरिक्ष क्षेत्र में) MPPSC के पसंदीदा विषय हैं। पद्म पुरस्कारों (विशेषकर पद्म विभूषण) के विजेताओं और उनके संबंधित क्षेत्रों का गहराई से अध्ययन करें।","concept_capsule_en":"In Current Affairs, ''UN declared Years/Decades'' and ''First Women in India'' (in Defense/Space sectors) are MPPSC''s favorite topics. Study the winners of Padma Awards (especially Padma Vibhushan) and their respective fields in depth.","practice_prompts":["वर्ष 2024 के सभी पद्म विभूषण विजेताओं के नाम और उनके क्षेत्र लिखिए।","संयुक्त राष्ट्र ने किस दशक (Decade) को ''पारिस्थितिकी तंत्र की बहाली पर संयुक्त राष्ट्र दशक'' घोषित किया है?"],"practice_prompts_en":["Write the names and fields of all Padma Vibhushan winners of 2024.","Which decade has been declared by the UN as the ''UN Decade on Ecosystem Restoration''?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('eb420dda-f74b-4707-8534-796b904db187', 'Economy', 'economy-institutions', 'अर्थव्यवस्था और संस्थान', 'Economy & Institutions', 'वित्त आयोग के अध्यक्षों का इतिहास, नीति आयोग की स्थापना और अंतर्राष्ट्रीय बैंकिंग सम्मान।', 1, 1773829386, 1773829386, '{"must_know_lists":[{"list_title":"हालिया वित्त आयोग और उनके अध्यक्ष","list_title_en":"Recent Finance Commissions and their Chairmen","items":["13वां वित्त आयोग - डॉ. विजय एल. केलकर","14वां वित्त आयोग - डॉ. वाई. वी. रेड्डी (42% राज्य हिस्सा)","15वां वित्त आयोग - श्री एन. के. सिंह (41% राज्य हिस्सा)","16वां वित्त आयोग - डॉ. अरविंद पनगढ़िया (नवगठित)"],"items_en":["13th Finance Commission - Dr. Vijay L. Kelkar","14th Finance Commission - Dr. Y. V. Reddy (42% state share)","15th Finance Commission - Shri N. K. Singh (41% state share)","16th Finance Commission - Dr. Arvind Panagariya (Newly formed)"],"memory_hook":"केलकर (13) -> रेड्डी (14) -> सिंह (15) -> पनगढ़िया (16)","memory_hook_en":"Kelkar (13) -> Reddy (14) -> Singh (15) -> Panagariya (16)"}],"concept_capsule":"भारतीय अर्थव्यवस्था में ''संस्थागत इतिहास'' (Institutional History) से सीधे प्रश्न आते हैं, जैसे वित्त आयोग के अध्यक्षों की सूची या नीति आयोग का गठन। आर्थिक निकायों के वर्तमान प्रमुखों और उनके द्वारा जीते गए अंतर्राष्ट्रीय सम्मानों को याद रखें।","concept_capsule_en":"Direct questions are asked from the ''Institutional History'' of the Indian Economy, such as the list of Finance Commission chairmen or the formation of NITI Aayog. Memorize the current heads of economic bodies and any international honors they have won.","practice_prompts":["संविधान के किस अनुच्छेद के तहत वित्त आयोग (Finance Commission) का गठन किया जाता है?","नीति आयोग की शासी परिषद (Governing Council) में कौन-कौन शामिल होते हैं?"],"practice_prompts_en":["Under which Article of the Constitution is the Finance Commission formed?","Who comprises the Governing Council of NITI Aayog?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('b9671e84-695c-4edd-8b89-985cd6f79664', 'Geography', 'environment-ecology-conservation', 'पर्यावरण, पारिस्थितिकी और संरक्षण', 'Environment, Ecology & Conservation', 'भारत के जैव विविधता हॉटस्पॉट, पारिस्थितिकी तंत्र की स्थिरता, प्रदूषण के प्रकार (बायोडिग्रेडेबल/ग्रीन मफलर), और राष्ट्रीय उद्यानों का इतिहास।', 1, 1773829387, 1773829387, '{"must_know_lists":[{"list_title":"भारत के प्रमुख बायोस्फीयर रिजर्व (MAB प्रोग्राम के तहत)","list_title_en":"Major Biosphere Reserves of India (Under MAB Program)","items":["नीलगिरि (पहला - 1986) - TN, Kerala, Karnataka","नंदा देवी - उत्तराखंड","मन्नार की खाड़ी - तमिलनाडु","सुंदरबन - पश्चिम बंगाल","पचमढ़ी, अचानकमार-अमरकंटक, पन्ना - मध्य प्रदेश"],"items_en":["Nilgiri (First - 1986) - TN, Kerala, Karnataka","Nanda Devi - Uttarakhand","Gulf of Mannar - Tamil Nadu","Sundarbans - West Bengal","Pachmarhi, Achanakmar-Amarkantak, Panna - Madhya Pradesh"],"memory_hook":"MP has 3 MAB reserves: PAP (Pachmarhi, Amarkantak, Panna).","memory_hook_en":"MP has 3 MAB reserves: PAP (Pachmarhi, Amarkantak, Panna)."}],"concept_capsule":"पर्यावरण भूगोल में ''पारिस्थितिकी तंत्र के सिद्धांत'' (ऊर्जा प्रवाह, 10% नियम) और ''संरक्षण इतिहास'' (प्रोजेक्ट टाइगर 1973, NGT 2010) से हर साल प्रश्न आते हैं। इसके अलावा, भारत के 18 बायोस्फीयर रिजर्व्स को उनके संबंधित राज्यों के साथ मैप करना सबसे महत्वपूर्ण है।","concept_capsule_en":"In Environmental Geography, ''ecosystem principles'' (energy flow, 10% rule) and ''conservation history'' (Project Tiger 1973, NGT 2010) yield questions every year. Also, mapping India''s 18 Biosphere Reserves with their respective states is extremely crucial.","practice_prompts":["लिंडेमैन का 10% ऊर्जा प्रवाह नियम (10% Energy Flow Rule) क्या है?","भारत में कुल कितने बायोस्फीयर रिजर्व यूनेस्को के ''वर्ल्ड नेटवर्क ऑफ बायोस्फीयर रिजर्व्स'' (MAB) में शामिल हैं?"],"practice_prompts_en":["What is Lindeman''s 10% Energy Flow Rule?","How many Biosphere Reserves in India are included in UNESCO''s ''World Network of Biosphere Reserves'' (MAB)?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('47ccd514-09e3-4c35-85e2-36f2e7a5ac12', 'Geography', 'physical-geography-demographics-natural-resources', 'भौतिक भूगोल, जनसांख्यिकी और प्राकृतिक संसाधन', 'Physical Geography, Demographics & Natural Resources', 'भारत की साक्षरता दर (जनगणना 2011), भू-आकृतिक विशेषताएं (पटल विरूपण, मोलेसिस बेसिन), वायुमंडलीय परतें, और ऊर्जा/खनिज (भूतापीय ऊर्जा, बैलाडिला)।', 1, 1773829388, 1773829388, '{"must_know_lists":[{"list_title":"वायुमंडल की परतें (नीचे से ऊपर)","list_title_en":"Layers of the Atmosphere (Bottom to Top)","items":["क्षोभमंडल (Troposphere) - मौसम परिवर्तन","समतापमंडल (Stratosphere) - ओजोन परत, विमान उड़ान","मध्यमंडल (Mesosphere) - उल्कापिंड जलते हैं","आयनमंडल (Thermosphere/Ionosphere) - रेडियो तरंगें परावर्तित","बाह्यमंडल (Exosphere) - कृत्रिम उपग्रह"],"items_en":["Troposphere - Weather changes","Stratosphere - Ozone layer, Airplane flights","Mesosphere - Meteors burn up","Thermosphere/Ionosphere - Radio waves reflected","Exosphere - Artificial satellites"],"memory_hook":"T-S-M-I-E (Trust Sam to Make Interesting Experiences)","memory_hook_en":"T-S-M-I-E (Trust Sam to Make Interesting Experiences)"}],"concept_capsule":"जनगणना 2011 (विशेषकर साक्षरता और घनत्व) MPPSC का सबसे वफादार विषय है। इसके अतिरिक्त, लौह अयस्क खदानों (बैलाडिला, कुद्रेमुख) और दुनिया के संघर्षरत क्षेत्रों (गाजा पट्टी, लाल सागर) की मैपिंग से सीधे सवाल आते हैं।","concept_capsule_en":"Census 2011 (especially literacy and density) is MPPSC''s most loyal topic. In addition, direct questions come from the mapping of Iron ore mines (Bailadila, Kudremukh) and conflict zones of the world (Gaza strip, Red Sea).","practice_prompts":["भारत के सबसे अधिक और सबसे कम साक्षरता वाले शीर्ष 3 राज्यों की सूची बनाएं।","लाल सागर (Red Sea) किन देशों की सीमाओं को छूता है?"],"practice_prompts_en":["List the top 3 states with the highest and lowest literacy rates in India.","Which countries border the Red Sea?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('408ddc20-f33e-4a2f-aea2-3be1bd79e865', 'History', 'modern-indian-history-ancient-society', 'आधुनिक भारतीय इतिहास और प्राचीन समाज', 'Modern Indian History & Ancient Society', 'राष्ट्रीय आंदोलन के प्रमुख अधिवेशन (सूरत, लाहौर, त्रिपुरी), दांडी यात्रा, और प्राचीन वैदिक समाज (अघन्या, महाजनपद)।', 1, 1773829390, 1773829390, '{"must_know_lists":[{"list_title":"कांग्रेस के महत्वपूर्ण अधिवेशन और उनके अध्यक्ष","list_title_en":"Important Congress Sessions and their Presidents","items":["1885 (बम्बई) - डब्ल्यू.सी. बनर्जी (पहला)","1907 (सूरत) - रास बिहारी घोष (कांग्रेस का विभाजन)","1916 (लखनऊ) - ए.सी. मजूमदार (नरम-गरम दल का मिलन)","1924 (बेलगाम) - महात्मा गांधी (एकमात्र)","1929 (लाहौर) - जवाहरलाल नेहरू (पूर्ण स्वराज)","1939 (त्रिपुरी, MP) - सुभाष चंद्र बोस (गांधीजी से विवाद)"],"items_en":["1885 (Bombay) - W.C. Bonnerjee (First)","1907 (Surat) - Rash Behari Ghosh (Congress split)","1916 (Lucknow) - A.C. Majumdar (Moderates-Extremists reunite)","1924 (Belgaum) - Mahatma Gandhi (Only one)","1929 (Lahore) - Jawaharlal Nehru (Purna Swaraj)","1939 (Tripuri, MP) - S.C. Bose (Dispute with Gandhi)"],"memory_hook":"85-बॉम्बे, 07-सूरत फूट, 24-गांधी, 29-लाहौर, 39-त्रिपुरी।","memory_hook_en":"85-Bombay, 07-Surat Split, 24-Gandhi, 29-Lahore, 39-Tripuri."}],"concept_capsule":"आधुनिक भारतीय इतिहास में कांग्रेस के अधिवेशन (विशेषकर MP में हुए जैसे त्रिपुरी) और गांधीवादी आंदोलनों (दांडी यात्रा, असहयोग) की तिथियां MPPSC का मुख्य आधार हैं। प्राचीन इतिहास में 16 महाजनपदों की राजधानियां और गुप्त/मौर्य काल के शासकों की उपाधियां (Titles) हमेशा पूछी जाती हैं।","concept_capsule_en":"In Modern Indian History, dates of Congress sessions (especially those in MP like Tripuri) and Gandhian movements (Dandi March, Non-Cooperation) are the bedrock of MPPSC. In Ancient History, capitals of the 16 Mahajanapadas and titles of Gupta/Mauryan rulers are always asked.","practice_prompts":["16 महाजनपदों में से ''चेदि'' और ''अवंति'' की राजधानियाँ क्या थीं?","लॉर्ड रिपन (1880-1884) के कार्यकाल के 3 प्रमुख सुधार क्या थे?"],"practice_prompts_en":["What were the capitals of ''Chedi'' and ''Avanti'' among the 16 Mahajanapadas?","What were the 3 major reforms during the tenure of Lord Ripon (1880-1884)?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('ad6207f6-6c8d-47de-a64c-c362984222a6', 'ICT', 'internet-technologies-cyber-security-computer-generations', 'इंटरनेट प्रौद्योगिकियां, साइबर सुरक्षा और कंप्यूटर पीढ़ियां', 'Internet Technologies, Cyber Security & Computer Generations', 'इंटरनेट कनेक्शन के प्रकार (DSL), वेब ब्राउज़र बनाम सर्च इंजन, फिशिंग जैसे साइबर खतरे, और कंप्यूटर की पीढ़ियों (Generations) में प्रयुक्त हार्डवेयर।', 1, 1773829392, 1773829392, '{"must_know_lists":[{"list_title":"कंप्यूटर की पीढ़ियां (Generations of Computers)","list_title_en":"Generations of Computers","items":["प्रथम पीढ़ी (1st Gen) - वैक्यूम ट्यूब (Vacuum Tubes)","द्वितीय पीढ़ी (2nd Gen) - ट्रांजिस्टर (Transistors)","तृतीय पीढ़ी (3rd Gen) - इंटीग्रेटेड सर्किट (ICs)","चतुर्थ पीढ़ी (4th Gen) - माइक्रोप्रोसेसर (VLSI)","पंचम पीढ़ी (5th Gen) - कृत्रिम बुद्धिमत्ता (AI / ULSI)"],"items_en":["1st Gen - Vacuum Tubes","2nd Gen - Transistors","3rd Gen - Integrated Circuits (ICs)","4th Gen - Microprocessor (VLSI)","5th Gen - Artificial Intelligence (AI / ULSI)"],"memory_hook":"Tube -> Transistor -> IC -> Micro -> AI","memory_hook_en":"Tube -> Transistor -> IC -> Micro -> AI"}],"concept_capsule":"कंप्यूटर की बुनियादी संरचना (पीढ़ियां, हार्डवेयर) और इंटरनेट की मूल बातें (ब्राउज़र बनाम सर्च इंजन) ICT खंड के सबसे ''स्टेटिक'' (अपरिवर्तनीय) हिस्से हैं। साइबर सुरक्षा में फिशिंग, स्पूफिंग और रैनसमवेयर के बीच के बारीक अंतर को समझना अनिवार्य है।","concept_capsule_en":"Basic computer structure (generations, hardware) and internet basics (browsers vs search engines) are the most ''static'' parts of the ICT section. In cyber security, understanding the subtle differences between phishing, spoofing, and ransomware is mandatory.","practice_prompts":["वेब 1.0, वेब 2.0 और वेब 3.0 के बीच मुख्य अंतर क्या हैं?","MAC एड्रेस और IP एड्रेस में क्या अंतर है?"],"practice_prompts_en":["What are the main differences between Web 1.0, Web 2.0, and Web 3.0?","What is the difference between a MAC address and an IP address?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('b68350d3-ad39-4cd6-8e47-b615e11e020b', 'ICT', 'internet-cyber-security-e-commerce', 'इंटरनेट, साइबर सुरक्षा और ई-कॉमर्स', 'Internet, Cyber Security & E-Commerce', 'इंटरनेट संचार के मूल सिद्धांत (डिकोडिंग), एआई का विकास (ChatGPT), साइबर सुरक्षा के उपकरण (फ़ायरवॉल) और खतरे (फिशिंग), तथा ई-कॉमर्स (B2C) के मॉडल।', 1, 1773829400, 1773829400, '{"must_know_lists":[{"list_title":"ई-कॉमर्स के प्रमुख मॉडल (E-Commerce Models)","list_title_en":"Major E-Commerce Models","items":["B2B (Business to Business) - IndiaMart, Alibaba, TradeIndia","B2C (Business to Consumer) - Amazon, Flipkart, Myntra","C2C (Consumer to Consumer) - OLX, Quikr, eBay","C2B (Consumer to Business) - Monster.com, Freelancer platforms"],"items_en":["B2B (Business to Business) - IndiaMart, Alibaba, TradeIndia","B2C (Business to Consumer) - Amazon, Flipkart, Myntra","C2C (Consumer to Consumer) - OLX, Quikr, eBay","C2B (Consumer to Business) - Monster.com, Freelancer platforms"],"memory_hook":"B2C=खरीदारी (Shopping), C2C=पुरानी चीजें बेचना (Second-hand).","memory_hook_en":"B2C=Shopping, C2C=Second-hand selling."}],"concept_capsule":"ICT में साइबर सुरक्षा (विशेष रूप से फिशिंग, फायरवॉल) और ई-कॉमर्स मॉडल (B2C, C2C) सबसे अधिक पूछे जाने वाले विषय हैं। इसके अलावा, AI के क्षेत्र में हालिया विकास (जैसे OpenAI, Gemini) पर अपडेट रहना अत्यंत आवश्यक है।","concept_capsule_en":"Cyber security (especially Phishing, Firewalls) and E-commerce models (B2C, C2C) are the most frequently asked topics in ICT. Additionally, staying updated on recent developments in AI (like OpenAI, Gemini) is absolutely essential.","practice_prompts":["ई-गवर्नेंस पोर्टल (G2C) और ई-कॉमर्स पोर्टल (B2C) के बीच मुख्य अंतर क्या है?","डीपफेक (Deepfake) तकनीक किस साइबर खतरे से संबंधित है?"],"practice_prompts_en":["What is the main difference between an E-Governance portal (G2C) and an E-Commerce portal (B2C)?","Deepfake technology is related to which cyber threat?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e6495741-7951-4d20-aa4f-6b082180c7b8', 'MP GK', 'mp-politics-administration-e-governance', 'मध्य प्रदेश राजनीति, प्रशासन और ई-गवर्नेंस', 'MP Politics, Administration & E-Governance', 'मध्य प्रदेश की राजनीतिक संरचना (प्रथम अध्यक्ष, मुख्यमंत्री), प्रशासनिक इकाइयाँ (नगर निगम), और सरकारी वेब पोर्टल (MP Online बनाम GeM)।', 1, 1773829402, 1773829402, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के प्रमुख ''प्रथम'' (First in MP)","list_title_en":"Major ''Firsts'' of Madhya Pradesh","items":["प्रथम राज्यपाल - डॉ. पट्टाभि सीतारमैया","प्रथम मुख्यमंत्री - पंडित रविशंकर शुक्ल","प्रथम महिला मुख्यमंत्री - सुश्री उमा भारती","प्रथम विधानसभा अध्यक्ष - पं. कुंजीलाल दुबे","प्रथम मुख्य न्यायाधीश - न्यायमूर्ति एम. हिदायतुल्ला"],"items_en":["First Governor - Dr. Pattabhi Sitaramayya","First Chief Minister - Pt. Ravishankar Shukla","First Woman CM - Sushri Uma Bharti","First Assembly Speaker - Pt. Kunjilal Dubey","First Chief Justice - Justice M. Hidayatullah"],"memory_hook":"पट्टाभि-गवर्नर, शुक्ल-CM, कुंजी-विधानसभा, हिदायतुल्ला-जज।","memory_hook_en":"Pattabhi-Gov, Shukla-CM, Kunji-Assembly, Hidayatullah-Judge."}],"concept_capsule":"मध्य प्रदेश की राजनीतिक संरचना (MP Polity) में ''प्रथम व्यक्ति'', मुख्यमंत्री/राज्यपालों का क्रम, और पंचायती राज अधिनियम (विशेषकर 1993-94 के मील के पत्थर) सबसे अधिक पूछे जाने वाले विषय हैं। विधानसभा भवन और सचिवालय के नाम कंठस्थ होने चाहिए।","concept_capsule_en":"In MP''s political structure (MP Polity), the ''first persons'', chronology of CMs/Governors, and the Panchayati Raj Act (especially the 1993-94 milestones) are the most frequently asked topics. The names of the Assembly building and Secretariat must be memorized.","practice_prompts":["मध्य प्रदेश में अब तक कितनी बार राष्ट्रपति शासन (President''s Rule) लागू हुआ है? उनके वर्ष लिखें।","राज्य सचिवालय (State Secretariat) और राज्य संचालनालय (State Directorate) के भवनों के नाम क्या हैं?"],"practice_prompts_en":["How many times has President''s Rule been imposed in Madhya Pradesh so far? Write their years.","What are the names of the State Secretariat and State Directorate buildings?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e67a10d2-fd6d-42f0-bbb6-a468dc8ee2c7', 'MP GK', 'mp-history-personalities-freedom-struggle', 'मध्य प्रदेश इतिहास, व्यक्तित्व और स्वतंत्रता संग्राम', 'MP History, Personalities & Freedom Struggle', 'मध्य प्रदेश के प्रमुख आदिवासी स्वतंत्रता सेनानी (टंट्या भील, बादल भोई), 1857 के क्रांतिकारी (तात्या टोपे), साहित्यकार (सुभद्रा कुमारी चौहान) और ऐतिहासिक स्थलों के प्राचीन नाम।', 1, 1773829403, 1773829403, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के ऐतिहासिक स्थलों के प्राचीन नाम","list_title_en":"Ancient Names of Historical Places of MP","items":["विदिशा - भेलसा, बेसनगर, दशार्ण","सांची - काकनाद, बोट","ग्वालियर - गोपाचल","उज्जैन - अवंतिका, उज्जयिनी","खजुराहो - जेजाकभुक्ति"],"items_en":["Vidisha - Bhilsa, Besnagar, Dasharna","Sanchi - Kakanad, Bot","Gwalior - Gopachal","Ujjain - Avantika, Ujjayini","Khajuraho - Jejakabhukti"],"memory_hook":"भेलसा(विदिशा), काकनाद(सांची), जेजाक(खजुराहो)।","memory_hook_en":"Bhilsa(Vidisha), Kakanad(Sanchi), Jejak(Khajuraho)."}],"concept_capsule":"मध्य प्रदेश के इतिहास में ''व्यक्तित्व'' (Personalities) सबसे महत्वपूर्ण हैं। आदिवासी नायकों (भीमा, टंट्या) का विद्रोह क्षेत्र, 1857 के नायकों (तात्या टोपे, रानी लक्ष्मीबाई) की समाधियां, और प्रसिद्ध साहित्यकारों की रचनाएं MPPSC की रीढ़ हैं।","concept_capsule_en":"''Personalities'' are the most important in the history of Madhya Pradesh. The rebellion regions of tribal heroes (Bhima, Tantia), tombs of 1857 heroes (Tatya Tope, Rani Lakshmibai), and works of famous writers are the backbone of MPPSC.","practice_prompts":["रानी दुर्गावती और रानी अवंतीबाई की समाधियां कहाँ स्थित हैं?","माखनलाल चतुर्वेदी और गजानन माधव मुक्तिबोध का जन्म मध्य प्रदेश के किन जिलों में हुआ था?"],"practice_prompts_en":["Where are the tombs of Rani Durgavati and Rani Avantibai located?","In which districts of Madhya Pradesh were Makhanlal Chaturvedi and Gajanan Madhav Muktibodh born?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('f0cdb7e2-fd34-449b-88b8-3fa43bd55a3b', 'MP GK', 'mp-demography-culture-geography-economy', 'मध्य प्रदेश जनसांख्यिकी, संस्कृति, भूगोल और अर्थव्यवस्था', 'MP Demography, Culture, Geography & Economy', 'जनगणना 2011 के आंकड़े (साक्षरता, वृद्धि दर), जनजातीय चित्रकला (नोहडोरा), औद्योगिक क्लस्टर (ग्वालियर), और आदिवासी कल्याण योजनाएं।', 1, 1773829404, 1773829404, '{"must_know_lists":[{"list_title":"मध्य प्रदेश की प्रमुख नदियों का अपवाह तंत्र (Drainage System)","list_title_en":"Drainage System of Major Rivers of MP","items":["यमुना अपवाह तंत्र (उत्तर की ओर) - चंबल, सिंध, बेतवा, केन, धसान","गंगा अपवाह तंत्र (पूर्व की ओर) - टोंस, सोन, बीहड़","नर्मदा अपवाह तंत्र (पश्चिम की ओर) - तवा, शक्कर, दूधी, हिरन","गोदावरी अपवाह तंत्र (दक्षिण की ओर) - वैनगंगा, वर्धा, पेंच"],"items_en":["Yamuna System (Northward) - Chambal, Sindh, Betwa, Ken, Dhasan","Ganga System (Eastward) - Tons, Son, Bihad","Narmada System (Westward) - Tawa, Shakkar, Dudhi, Hiran","Godavari System (Southward) - Wainganga, Wardha, Pench"],"memory_hook":"CSBK -> यमुना, Narmada -> पश्चिम, Wainganga -> दक्षिण।","memory_hook_en":"CSBK -> Yamuna, Narmada -> West, Wainganga -> South."}],"concept_capsule":"मध्य प्रदेश का भूगोल (विशेषकर अपवाह तंत्र और मिट्टी) और 2011 की जनगणना (न्यूनतम/अधिकतम वाले 3 जिले) MPPSC के सिलेबस के सबसे ''स्कोरिंग'' हिस्से हैं। आदिवासी योजनाओं के ''मुख्य उद्देश्य'' (जैसे टंट्या मामा - स्वरोजगार) पर स्पष्टता होनी चाहिए।","concept_capsule_en":"MP Geography (especially drainage system and soils) and 2011 Census (top/bottom 3 districts) are the most ''scoring'' parts of the MPPSC syllabus. There must be clarity on the ''main objectives'' of tribal schemes (like Tantia Mama - Self-employment).","practice_prompts":["मध्य प्रदेश के किन तीन जिलों में जनसंख्या घनत्व (Population Density) सबसे अधिक है?","चंबल नदी पर बनी तीन प्रमुख जलविद्युत परियोजनाओं के नाम और उनके राज्य बताइए।"],"practice_prompts_en":["Which three districts of Madhya Pradesh have the highest Population Density?","Name the three major hydroelectric projects built on the Chambal river and their respective states."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('bd4e2d7f-3086-4276-9331-82bc95665411', 'Polity', 'judiciary-constitutional-bodies-rights-amendments', 'न्यायपालिका, संवैधानिक निकाय, अधिकार और संशोधन', 'Judiciary, Constitutional Bodies, Rights & Amendments', 'उच्च न्यायालय के न्यायाधीशों की आयु, CAG का कार्यकाल, मानवाधिकारों की परिभाषा, पंचायती राज संशोधन (74वां), और खाद्य/महिला आयोगों के कानूनी प्रावधान।', 1, 1773829407, 1773829407, '{"must_know_lists":[{"list_title":"प्रमुख संवैधानिक / सांविधिक निकायों का कार्यकाल (Tenure)","list_title_en":"Tenure of Major Constitutional / Statutory Bodies","items":["CAG, CEC, UPSC अध्यक्ष - 6 वर्ष या 65 वर्ष की आयु","MPPSC अध्यक्ष / राज्य निर्वाचन आयुक्त - 6 वर्ष या 62 वर्ष की आयु","राष्ट्रीय मानवाधिकार आयोग (NHRC) - 3 वर्ष या 70 वर्ष की आयु","राष्ट्रीय महिला आयोग (NCW) - 3 वर्ष या 65 वर्ष की आयु"],"items_en":["CAG, CEC, UPSC Chairman - 6 yrs or 65 yrs age","MPPSC Chairman / State EC - 6 yrs or 62 yrs age","NHRC - 3 yrs or 70 yrs age","NCW - 3 yrs or 65 yrs age"],"memory_hook":"संघ (Union) के लिए 65, राज्य (State) के लिए 62, मानवाधिकार के लिए 70।","memory_hook_en":"65 for Union, 62 for State, 70 for Human Rights."}],"concept_capsule":"भारतीय राजव्यवस्था में ''आयोगों (Commissions)'' का एक बहुत बड़ा वेटेज (Weightage) है। उनकी संरचना (कुल सदस्य), नियुक्ति प्राधिकारी (राष्ट्रपति/राज्यपाल), हटाने की प्रक्रिया और कार्यकाल (Tenure) पर सीधे सवाल आते हैं। इसके अलावा, अनुच्छेद 21 (जीवन का अधिकार) की व्यापक व्याख्या पर वैचारिक प्रश्न बनते हैं।","concept_capsule_en":"''Commissions'' hold a massive weightage in Indian Polity. Direct questions cover their composition (total members), appointing authority (President/Governor), removal process, and tenure. Furthermore, conceptual questions are framed on the broad interpretation of Article 21 (Right to Life).","practice_prompts":["राज्य मानवाधिकार आयोग (SHRC) के अध्यक्ष और सदस्यों की नियुक्ति करने वाली समिति में कौन-कौन शामिल होते हैं?","अनुच्छेद 21 के तहत ''निजता का अधिकार'' (Right to Privacy) किस ऐतिहासिक मामले में घोषित किया गया था?"],"practice_prompts_en":["Who are the members of the committee that appoints the Chairman and members of the State Human Rights Commission (SHRC)?","In which landmark case was the ''Right to Privacy'' declared under Article 21?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('008e003a-0c79-4bdc-8dae-a849d5deab4e', 'Current Affairs', 'sports-tournaments-awards-institutes', 'खेल टूर्नामेंट, पुरस्कार और संस्थान', 'Sports Tournaments, Awards & Institutes', 'खेल रत्न पुरस्कार, ओलंपिक इतिहास (महिला हॉकी), क्रिकेट के प्रथम एकदिवसीय मैच और खेल संघों (कबड्डी) के मुख्यालय।', 1, 1773829409, 1773829409, '{"must_know_lists":[{"list_title":"भारत के सर्वोच्च खेल पुरस्कार (हालिया विजेता)","list_title_en":"India''s Highest Sports Awards (Recent Winners)","items":["मेजर ध्यानचंद खेल रत्न 2023 - सात्विकसाईराज रंकीरेड्डी और चिराग शेट्टी (बैडमिंटन)","मेजर ध्यानचंद खेल रत्न 2022 - अचंता शरत कमल (टेबल टेनिस)","द्रोणाचार्य पुरस्कार (लाइफटाइम) 2023 - जसकीरत सिंह ग्रेवाल (गोल्फ), भास्करन ई (कबड्डी)","अर्जुन पुरस्कार 2023 - प्राची यादव (पैरा-कैनो, MP), मोहम्मद शमी (क्रिकेट), ओजस प्रवीण देवताले (तीरंदाजी)"],"items_en":["Major Dhyan Chand Khel Ratna 2023 - Satwiksairaj Rankireddy & Chirag Shetty (Badminton)","Major Dhyan Chand Khel Ratna 2022 - Achanta Sharath Kamal (Table Tennis)","Dronacharya Award (Lifetime) 2023 - Jaskirat Singh Grewal (Golf), Bhaskaran E (Kabaddi)","Arjuna Award 2023 - Prachi Yadav (Para-Canoe, MP), Mohammed Shami (Cricket), Ojas Pravin Deotale (Archery)"],"memory_hook":"23 में बैडमिंटन की जोड़ी (Satwik-Chirag), 22 में टीटी (Sharath)।","memory_hook_en":"Badminton duo in ''23 (Satwik-Chirag), TT in ''22 (Sharath)."}],"concept_capsule":"खेल (Sports) करंट अफेयर्स में सबसे ज्यादा स्कोरिंग सेक्शन है। ''खेल रत्न'' और ''अर्जुन पुरस्कार'' विजेताओं (विशेषकर मध्य प्रदेश के) के नाम उनके खेल के साथ याद रखें। ओलंपिक, एशियाई खेल और क्रिकेट विश्व कप के ऐतिहासिक ''प्रथम'' (Firsts) और ''अनोखे'' रिकॉर्ड भी अक्सर पूछे जाते हैं।","concept_capsule_en":"Sports is the most scoring section in Current Affairs. Memorize the names of ''Khel Ratna'' and ''Arjuna Award'' winners (especially from MP) along with their sports. Historic ''Firsts'' and ''unique'' records from Olympics, Asian Games, and Cricket World Cups are also frequently asked.","practice_prompts":["भारत ने ओलंपिक इतिहास में अब तक हॉकी में कितने स्वर्ण पदक (Gold Medals) जीते हैं?","विश्वनाथन आनंद के अलावा भारत के किन्हीं दो चेस ग्रैंडमास्टर्स (Chess Grandmasters) के नाम बताइए जिन्हें ''खेल रत्न'' मिला हो।"],"practice_prompts_en":["How many gold medals has India won in Hockey in Olympic history so far?","Apart from Viswanathan Anand, name any two Indian Chess Grandmasters who have received the ''Khel Ratna''."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('f9770ced-b1ef-4edd-8582-1f321b4ad674', 'ICT', 'current-affairs-defence', 'करंट अफेयर्स - रक्षा', 'Current Affairs - Defence', 'भारतीय थल सेना के प्रमुख और अफ्रीका-भारत सैन्य अभ्यास (AFINDEX)।', 1, 1773829416, 1773829416, '{"must_know_lists":[{"list_title":"भारत के प्रमुख बहुराष्ट्रीय/द्विपक्षीय सैन्य अभ्यास (हालिया)","list_title_en":"India''s Major Multinational/Bilateral Military Exercises (Recent)","items":["AFINDEX - अफ्रीका और भारत (पुणे)","मालबार (Malabar) - भारत, अमेरिका, जापान, ऑस्ट्रेलिया (Quad)","सूर्य किरण (Surya Kiran) - भारत और नेपाल","सिम्बेक्स (SIMBEX) - भारत और सिंगापुर","युद्ध अभ्यास (Yudh Abhyas) - भारत और अमेरिका"],"items_en":["AFINDEX - Africa and India (Pune)","Malabar - India, USA, Japan, Australia (Quad)","Surya Kiran - India and Nepal","SIMBEX - India and Singapore","Yudh Abhyas - India and USA"],"memory_hook":"सूर्य नेपाल में, युद्ध अमेरिका से, मालबार में चार।","memory_hook_en":"Surya in Nepal, Yudh with US, Malabar has four."}],"concept_capsule":"रक्षा क्षेत्र (Defence) से 1-2 प्रश्न निश्चित होते हैं। थल, नौसेना और वायु सेना के प्रमुखों के नाम और वर्ष के प्रमुख सैन्य अभ्यासों (Exercises) की सूची कंठस्थ होनी चाहिए।","concept_capsule_en":"1-2 questions from the Defence sector are certain. The names of Army, Navy, and Air Force chiefs, along with a list of major military exercises of the year, must be memorized.","practice_prompts":["वर्तमान में भारत के चीफ ऑफ डिफेंस स्टाफ (CDS) कौन हैं?","''मित्र शक्ति'' (Mitra Shakti) सैन्य अभ्यास भारत किस देश के साथ करता है?"],"practice_prompts_en":["Who is currently the Chief of Defence Staff (CDS) of India?","India conducts the ''Mitra Shakti'' military exercise with which country?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('d9b8326e-48a9-423e-9891-8b1a04d4c81b', 'Economy', 'economy', 'अर्थव्यवस्था', 'Economy', 'विदेशी व्यापार के लाभ और भारतीय रिज़र्व बैंक (RBI) के राष्ट्रीयकरण का वर्ष।', 1, 1773829416, 1773829416, '{"must_know_lists":[{"list_title":"भारत में बैंकिंग का इतिहास: महत्वपूर्ण तिथियां","list_title_en":"History of Banking in India: Important Dates","items":["1935 - RBI की स्थापना (हिल्टन यंग कमीशन)","1949 - RBI का राष्ट्रीयकरण","1955 - इंपीरियल बैंक बना SBI (State Bank of India)","1969 - 14 प्रमुख वाणिज्यिक बैंकों का राष्ट्रीयकरण (इंदिरा गांधी)","1980 - 6 और बैंकों का राष्ट्रीयकरण"],"items_en":["1935 - Establishment of RBI (Hilton Young Commission)","1949 - Nationalization of RBI","1955 - Imperial Bank became SBI (State Bank of India)","1969 - Nationalization of 14 major commercial banks (Indira Gandhi)","1980 - Nationalization of 6 more banks"],"memory_hook":"35 में बना, 49 में सरकार का हुआ, 69 में 14 और आए।","memory_hook_en":"Built in ''35, Govt owned in ''49, 14 more in ''69."}],"concept_capsule":"RBI की स्थापना और राष्ट्रीयकरण भारतीय अर्थव्यवस्था का एक अत्यंत महत्वपूर्ण और ''स्टेटिक'' (स्थिर) विषय है। इसी तरह, भारत में विदेशी व्यापार (LPG सुधार 1991) के प्रभावों की वैचारिक समझ आवश्यक है।","concept_capsule_en":"The establishment and nationalization of RBI is an extremely important and ''static'' topic of the Indian Economy. Similarly, a conceptual understanding of the impacts of foreign trade (LPG reforms 1991) in India is essential.","practice_prompts":["RBI के पहले भारतीय गवर्नर (First Indian Governor) कौन थे?","1991 के आर्थिक सुधारों (LPG) का मुख्य उद्देश्य क्या था?"],"practice_prompts_en":["Who was the first Indian Governor of RBI?","What was the main objective of the 1991 economic reforms (LPG)?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e5aa91a0-2cc5-4869-9b9a-bd42385bcddb', 'Polity', 'economypolity', 'अर्थव्यवस्था/राजव्यवस्था', 'Economy/Polity', 'खाद्य सुरक्षा और मानक अधिनियम के तहत प्रमाणन चिह्न (Certification Marks)।', 1, 1773829417, 1773829417, '{"must_know_lists":[{"list_title":"भारत में प्रमुख प्रमाणन चिह्न (Certification Marks)","list_title_en":"Major Certification Marks in India","items":["FPO मार्क - प्रसंस्कृत फल उत्पाद (Fruit Products)","एगमार्क (Agmark) - कृषि उत्पाद (Agricultural Products)","ISI मार्क - औद्योगिक उत्पाद (Industrial Products)","हॉलमार्क (Hallmark) - सोने/चांदी के आभूषण (Jewelry)","ईकोमार्क (Ecomark) - पर्यावरण के अनुकूल उत्पाद (Eco-friendly)"],"items_en":["FPO Mark - Processed Fruit Products","Agmark - Agricultural Products","ISI Mark - Industrial Products","Hallmark - Gold/Silver Jewelry","Ecomark - Eco-friendly products"],"memory_hook":"Agmark for Agri, FPO for Fruit, ISI for Industry.","memory_hook_en":"Agmark for Agri, FPO for Fruit, ISI for Industry."}],"concept_capsule":"भारत में उपभोक्ता संरक्षण (Consumer Protection) और मानक (Standards) से जुड़े चिह्न अक्सर ''मैच द कॉलम'' (Match the following) या सीधे प्रश्न के रूप में आते हैं। FSSAI (2006 अधिनियम) की भूमिका को भी समझना चाहिए।","concept_capsule_en":"Certification marks related to Consumer Protection and Standards in India often appear as ''Match the following'' or direct questions. The role of FSSAI (2006 Act) should also be understood.","practice_prompts":["FSSAI का फुल फॉर्म क्या है और यह किस मंत्रालय के अधीन कार्य करता है?","भारत में हॉलमार्किंग (Hallmarking) योजना किस संस्था द्वारा संचालित की जाती है?"],"practice_prompts_en":["What is the full form of FSSAI and under which ministry does it operate?","Which organization operates the Hallmarking scheme in India?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e9693e57-5d71-4384-9433-5715a72ab48b', 'Geography', 'environment', 'पर्यावरण', 'Environment', 'पारिस्थितिकी तंत्र के संक्रमण क्षेत्र (इकोटोन), जैव-विविधता हॉटस्पॉट (पश्चिमी घाट) और पर्यावरण प्रदूषण जनित रोग (इटाई-इटाई)।', 1, 1773829417, 1773829417, '{"must_know_lists":[{"list_title":"भारत के जैव-विविधता हॉटस्पॉट (Biodiversity Hotspots)","list_title_en":"Biodiversity Hotspots of India","items":["हिमालय क्षेत्र (Himalayas)","पश्चिमी घाट (Western Ghats - सबसे सघन)","इंडो-बर्मा क्षेत्र (Indo-Burma Region)","सुंडालैंड (Sundaland - अंडमान निकोबार द्वीप समूह शामिल)"],"items_en":["Himalayan Region","Western Ghats (Most dense)","Indo-Burma Region","Sundaland (Includes Andaman & Nicobar Islands)"],"memory_hook":"उत्तर(हिमालय), पश्चिम(पश्चिमी घाट), पूर्व(इंडो-बर्मा), द्वीप(सुंडालैंड)।","memory_hook_en":"North(Himalayas), West(W.Ghats), East(Indo-Burma), Islands(Sundaland)."},{"list_title":"प्रदूषण जनित प्रमुख रोग","list_title_en":"Major Pollution-borne Diseases","items":["कैडमियम (Cadmium) - इटाई-इटाई (Itai-Itai)","पारा (Mercury) - मिनामाता (Minamata)","नाइट्रेट (Nitrate) - ब्लू बेबी सिंड्रोम (Blue Baby Syndrome)","आर्सेनिक (Arsenic) - ब्लैक फुट रोग (Black Foot Disease)","फ्लोराइड (Fluoride) - फ्लोरोसिस (दांत/हड्डी की समस्या)"],"items_en":["Cadmium - Itai-Itai","Mercury - Minamata","Nitrate - Blue Baby Syndrome","Arsenic - Black Foot Disease","Fluoride - Fluorosis (Teeth/Bone issues)"],"memory_hook":"पारा-मिनामाता, कैडमियम-इटाई, नाइट्रेट-ब्लू बेबी।","memory_hook_en":"Mercury-Minamata, Cadmium-Itai, Nitrate-Blue Baby."}],"concept_capsule":"पर्यावरण विज्ञान में ''परिभाषाएं'' (जैसे इकोटोन) और ''बीमारियों के कारण'' (भारी धातु विषाक्तता) अत्यंत उच्च-उपज वाले विषय हैं। हॉटस्पॉट्स की संख्या और उनके नाम (विशेषकर पश्चिमी घाट) हर साल किसी न किसी रूप में पूछे जाते हैं।","concept_capsule_en":"In Environmental Science, ''definitions'' (like Ecotone) and ''causes of diseases'' (heavy metal toxicity) are extremely high-yield topics. The number of hotspots and their names (especially Western Ghats) are asked in some form every year.","practice_prompts":["''एज इफ़ेक्ट'' (Edge Effect) क्या है और यह इकोटोन से कैसे संबंधित है?","''ब्लू बेबी सिंड्रोम'' पानी में किस रसायन की अधिकता के कारण होता है?"],"practice_prompts_en":["What is the ''Edge Effect'' and how is it related to an Ecotone?","''Blue Baby Syndrome'' is caused by the excess of which chemical in water?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('77992496-6a6a-4ee3-bf98-091f4ce08ffa', 'Science', 'general-science', 'सामान्य विज्ञान', 'General Science', 'मानव शरीर विज्ञान (विटामिन K, कशेरुकाएं), और इलेक्ट्रॉनिक्स (शॉट्की डायोड, डोपिंग)।', 1, 1773829418, 1773829418, '{"must_know_lists":[{"list_title":"महत्वपूर्ण विटामिन और उनकी कमी से होने वाले रोग","list_title_en":"Important Vitamins and Deficiency Diseases","items":["विटामिन A (रेटिनॉल) - रतौंधी (Night Blindness)","विटामिन B1 (थायमीन) - बेरीबेरी (Beri-beri)","विटामिन C (एस्कॉर्बिक एसिड) - स्कर्वी (Scurvy)","विटामिन D (कैल्सिफेरॉल) - रिकेट्स (Rickets)","विटामिन K (फिलोक्विनोन) - रक्त का थक्का न जमना (Bleeding)"],"items_en":["Vitamin A (Retinol) - Night Blindness","Vitamin B1 (Thiamine) - Beri-beri","Vitamin C (Ascorbic Acid) - Scurvy","Vitamin D (Calciferol) - Rickets","Vitamin K (Phylloquinone) - Non-clotting of blood"],"memory_hook":"A-आंख(Eye), C-स्कर्वी(Skin), D-हड्डी(Bone), K-खून(Blood)।","memory_hook_en":"A-Eye, C-Scurvy(Skin), D-Bone, K-Blood."}],"concept_capsule":"सामान्य विज्ञान में जीव विज्ञान (मानव शरीर के तंत्र और पोषण) सबसे महत्वपूर्ण है। भौतिकी में सेमीकंडक्टर (डायोड, पी-एन जंक्शन) से ''कठिन'' (Bouncer) प्रश्न बनाए जाते हैं।","concept_capsule_en":"In General Science, Biology (Human Body systems and Nutrition) is the most important. In Physics, ''hard'' (bouncer) questions are framed from semiconductors (Diodes, P-N Junctions).","practice_prompts":["मानव शरीर में सबसे बड़ी हड्डी (Bone) और सबसे बड़ी ग्रंथि (Gland) कौन सी है?","जेनर डायोड (Zener Diode) का प्राथमिक उपयोग क्या है?"],"practice_prompts_en":["Which is the largest bone and largest gland in the human body?","What is the primary application of a Zener Diode?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('242a939c-7a9f-47ca-9af0-f12c7f956b12', 'History', 'geography-agriculture-census', 'भूगोल - कृषि और जनगणना', 'Geography - Agriculture & Census', 'मूंगफली का सबसे बड़ा उत्पादक राज्य और 2011 जनगणना के दशकीय वृद्धि/महिला साक्षरता के आंकड़े।', 1, 1773829418, 1773829418, '{"must_know_lists":[{"list_title":"जनगणना 2011: साक्षरता दर (Literacy Rate) के शीर्ष 4 राज्य","list_title_en":"Census 2011: Top 4 States in Literacy Rate","items":["1. केरल (Kerala) - 94.0%","2. मिजोरम (Mizoram) - 91.3%","3. गोवा (Goa) - 88.7%","4. त्रिपुरा (Tripura) - 87.2%"],"items_en":["1. Kerala - 94.0%","2. Mizoram - 91.3%","3. Goa - 88.7%","4. Tripura - 87.2%"],"memory_hook":"K-M-G-T (केरल, मिजोरम, गोवा, त्रिपुरा)","memory_hook_en":"K-M-G-T (Kerala, Mizoram, Goa, Tripura)"}],"concept_capsule":"भारतीय भूगोल में 2011 की जनगणना ''अमर'' (Immortal) विषय है। जब तक नई जनगणना के आंकड़े नहीं आते, 2011 के साक्षरता, घनत्व, लिंगानुपात और वृद्धि दर के शीर्ष 3 और निचले 3 राज्यों को रट कर रखें। कृषि उत्पादन रैंकिंग भी लगातार पूछी जाती है।","concept_capsule_en":"In Indian Geography, the 2011 Census is an ''immortal'' topic. Until new census data arrives, rote learn the top 3 and bottom 3 states for literacy, density, sex ratio, and growth rate of 2011. Agricultural production rankings are also continuously asked.","practice_prompts":["2011 की जनगणना के अनुसार भारत का लिंगानुपात (Sex Ratio) और शिशु लिंगानुपात (Child Sex Ratio) क्या है?","भारत में सरसों (Mustard) और सोयाबीन (Soybean) के सबसे बड़े उत्पादक राज्य कौन से हैं?"],"practice_prompts_en":["What is the Sex Ratio and Child Sex Ratio of India according to the 2011 census?","Which are the largest producer states of Mustard and Soybean in India?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('3863d9e2-1e8a-4009-9d93-25a923ce1a4d', 'Geography', 'geography-forests-rivers-ecosystem', 'भूगोल - वन, नदियां और पारिस्थितिकी तंत्र', 'Geography - Forests, Rivers & Ecosystem', 'सुन्दरबन के प्रकार (मैंग्रोव/तटीय वन), प्रायद्वीपीय नदियां, पवन ऊर्जा क्षमता और ऊर्जा प्रवाह (थर्मोडायनामिक्स)।', 1, 1773829419, 1773829419, '{"must_know_lists":[{"list_title":"भारत में वनों के प्रमुख प्रकार (Major Forest Types)","list_title_en":"Major Forest Types in India","items":["उष्णकटिबंधीय पर्णपाती (Tropical Deciduous) - सबसे बड़े क्षेत्र में (मानसून वन, सागौन/साल)।","उष्णकटिबंधीय सदाबहार (Tropical Evergreen) - पश्चिमी घाट, अंडमान, पूर्वोत्तर (वर्षा > 200cm)।","तटीय / ज्वारीय (Littoral / Swamp) - सुन्दरबन, महानदी डेल्टा (मैंग्रोव)।","पर्वतीय वन (Montane) - हिमालय क्षेत्र (चीड़, देवदार)।"],"items_en":["Tropical Deciduous - Largest area (Monsoon forests, Teak/Sal).","Tropical Evergreen - Western Ghats, Andaman, NE (Rain > 200cm).","Littoral / Swamp - Sundarbans, Mahanadi Delta (Mangroves).","Montane - Himalayan region (Pine, Deodar)."],"memory_hook":"पर्णपाती (Deciduous) भारत के ''राजा'' वन हैं।","memory_hook_en":"Deciduous are the ''King'' forests of India."}],"concept_capsule":"भारतीय भूगोल में वनों के प्रकार और ऊर्जा/खनिज उत्पादन के राज्य-वार आंकड़े (State Rankings) महत्वपूर्ण हैं। पारिस्थितिकी (Ecology) के वैचारिक प्रश्न (Conceptual questions) ऊष्मागतिकी के नियमों पर आधारित होते हैं।","concept_capsule_en":"In Indian Geography, forest types and state-wise data (rankings) for energy/mineral production are crucial. Conceptual questions of Ecology are based on the laws of thermodynamics.","practice_prompts":["भारत के किन राज्यों में मैंग्रोव वन (Mangrove Forests) मुख्य रूप से पाए जाते हैं?","भारत की शीर्ष 3 सबसे लंबी नदियां कौन सी हैं?"],"practice_prompts_en":["In which states of India are Mangrove forests mainly found?","Which are the top 3 longest rivers of India?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('ee2fe9b8-0290-43a5-9ab0-dc897c578bf0', 'Science', 'govt-schemes-science-institutes', 'सरकारी योजनाएं और विज्ञान संस्थान', 'Govt Schemes & Science Institutes', 'सौभाग्य योजना (विद्युतीकरण), आयुष मंत्रालय का पूर्ण रूप, और केंद्रीय भारतीय भाषा संस्थान (CIIL) का स्थान।', 1, 1773829420, 1773829420, '{"must_know_lists":[{"list_title":"भारत सरकार की ''U'' (उ) अक्षर से शुरू होने वाली प्रमुख योजनाएं","list_title_en":"Major GoI Schemes starting with the letter ''U''","items":["उज्ज्वला (Ujjwala) - BPL महिलाओं को LPG गैस कनेक्शन।","उजाला (Ujala) - ऊर्जा बचाने के लिए सस्ते LED बल्ब।","उड़ान (UDAN) - ''उड़े देश का आम नागरिक'' (सस्ती हवाई यात्रा)।","उदय (UDAY) - बिजली वितरण कंपनियों (DISCOMs) का आर्थिक सुधार।"],"items_en":["Ujjwala - LPG gas connections to BPL women.","Ujala - Cheap LED bulbs to save energy.","UDAN - ''Ude Desh Ka Aam Naagrik'' (Cheap air travel).","UDAY - Financial turnaround of Power DISCOMs."],"memory_hook":"Ujjwala=Gas, Ujala=Bulb, UDAN=Flight, UDAY=DISCOMs.","memory_hook_en":"Ujjwala=Gas, Ujala=Bulb, UDAN=Flight, UDAY=DISCOMs."}],"concept_capsule":"भारत सरकार की प्रमुख ''फ्लैगशिप'' योजनाओं का नोडल मंत्रालय और उनका मुख्य उद्देश्य (Core Objective) हमेशा पूछा जाता है। ''AYUSH'' जैसे एक्रोनिम्स (Abbreviations) का फुल फॉर्म और राष्ट्रीय संस्थानों के मुख्यालयों को कंठस्थ करें।","concept_capsule_en":"The nodal ministry and core objective of GoI''s ''flagship'' schemes are always asked. Memorize full forms of acronyms like ''AYUSH'' and the headquarters of National Institutes.","practice_prompts":["''स्वच्छ भारत मिशन'' (SBM) ग्रामीण और शहरी किस-किस मंत्रालय के अधीन आते हैं?","राष्ट्रीय पर्यावरण अभियांत्रिकी अनुसंधान संस्थान (NEERI) कहाँ स्थित है?"],"practice_prompts_en":["Under which ministries do the ''Swachh Bharat Mission'' (SBM) Rural and Urban fall?","Where is the National Environmental Engineering Research Institute (NEERI) located?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('07a4c57c-82b0-4c4d-81a6-243fc16acaea', 'History', 'ancient-medieval-india', 'प्राचीन और मध्यकालीन भारत', 'Ancient & Medieval India', 'सांची स्तूप का कलात्मक विवरण, भक्ति संत (अलवार/नयनार), विजयनगर साम्राज्य की स्थापना और अल-बरूनी की पुस्तक।', 1, 1773829420, 1773829420, '{"must_know_lists":[{"list_title":"मध्यकालीन भारत के प्रमुख विदेशी यात्री और उनकी पुस्तकें","list_title_en":"Major Foreign Travelers of Medieval India & their Books","items":["अल-बरूनी (उज्बेकिस्तान) - तहकीक-ए-हिन्द (गजनवी के साथ)","इब्न बतूता (मोरक्को) - रेहला (मुहम्मद बिन तुगलक के समय)","अब्दुर रज्जाक (फारस) - विजयनगर साम्राज्य आया (देवराय द्वितीय)","डोमिंगो पेस (पुर्तगाल) - विजयनगर (कृष्णदेव राय के समय)"],"items_en":["Al-Biruni (Uzbekistan) - Tahqiq-i-Hind (With Ghaznavi)","Ibn Battuta (Morocco) - Rihla (During MBT)","Abdur Razzaq (Persia) - Visited Vijayanagara (Devaraya II)","Domingo Paes (Portugal) - Vijayanagara (Krishnadeva Raya)"],"memory_hook":"बरूनी की हिन्द, बतूता का रेहला।","memory_hook_en":"Biruni''s Hind, Battuta''s Rihla."}],"concept_capsule":"प्राचीन और मध्यकालीन इतिहास में ''कला और वास्तुकला'' (विशेषकर सांची और बौद्ध स्थल) MPPSC का मुख्य फोकस है। भक्ति संतों (अलवार/नयनार) की मूल विशेषताएं और विजयनगर साम्राज्य के विदेशी यात्रियों का क्रम हमेशा उच्च-उपज वाला विषय है।","concept_capsule_en":"In Ancient and Medieval History, ''Art and Architecture'' (especially Sanchi and Buddhist sites) is MPPSC''s primary focus. Basic traits of Bhakti saints (Alvar/Nayanar) and the sequence of foreign travelers to the Vijayanagara Empire are always high-yield topics.","practice_prompts":["शंकराचार्य और रामानुजाचार्य के दार्शनिक सिद्धांतों (Philosophy) का क्या नाम है?","सांची स्तूप को यूनेस्को विश्व धरोहर (UNESCO World Heritage) किस वर्ष घोषित किया गया था?"],"practice_prompts_en":["What are the names of the philosophical principles of Shankaracharya and Ramanujacharya?","In which year was Sanchi Stupa declared a UNESCO World Heritage site?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('940aec25-37b6-4c8d-8d7e-4a61872d7b6b', 'History', 'indian-freedom-struggle-social-reforms', 'भारतीय स्वतंत्रता संग्राम और समाज सुधार', 'Indian Freedom Struggle & Social Reforms', 'भारत छोड़ो आंदोलन (1942), चंपारण का तिनकठिया नियम, संथाल विद्रोह, प्रार्थना समाज और 1919 के द्वैध शासन अधिनियम के महत्वपूर्ण तथ्य।', 1, 1773829421, 1773829421, '{"must_know_lists":[{"list_title":"गांधीजी के शुरुआती आंदोलन (क्रमानुसार)","list_title_en":"Gandhiji''s Early Movements (Chronological)","items":["1. चंपारण सत्याग्रह (1917) - तिनकठिया प्रथा (नील)","2. अहमदाबाद मिल हड़ताल (1918) - पहली भूख हड़ताल (प्लेग बोनस)","3. खेड़ा सत्याग्रह (1918) - प्रथम असहयोग (फसल खराब होने पर लगान माफी)","4. रॉलेट सत्याग्रह (1919) - राष्ट्रव्यापी हड़ताल"],"items_en":["1. Champaran Satyagraha (1917) - Tinkathia system (Indigo)","2. Ahmedabad Mill Strike (1918) - First Hunger Strike (Plague bonus)","3. Kheda Satyagraha (1918) - First Non-Cooperation (Revenue exemption on crop failure)","4. Rowlatt Satyagraha (1919) - Nationwide strike"],"memory_hook":"CAK (Champaran, Ahmedabad, Kheda) - गांधीजी का ''केक'' (Cake)।","memory_hook_en":"CAK (Champaran, Ahmedabad, Kheda) - Gandhiji''s ''Cake''."}],"concept_capsule":"आधुनिक भारतीय इतिहास में ''गांधीवादी युग'' (1917-1947), ''जनजातीय/किसान विद्रोह'' (संथाल, मुंडा, मोपला) और ''संवैधानिक विकास'' (1909, 1919, 1935 के अधिनियम) कोर विषय हैं। 1919 और 1935 के अधिनियमों के बीच ''द्वैध शासन'' (Dyarchy) के स्तर (प्रांत बनाम केंद्र) का अंतर हमेशा स्पष्ट रखें।","concept_capsule_en":"In Modern Indian History, the ''Gandhian Era'' (1917-1947), ''Tribal/Peasant Revolts'' (Santhal, Munda, Moplah), and ''Constitutional Development'' (Acts of 1909, 1919, 1935) are core subjects. Always maintain clarity on the level (Province vs. Center) of ''Dyarchy'' between the Acts of 1919 and 1935.","practice_prompts":["1909 के ''मार्ले-मिंटो सुधार'' (Morley-Minto Reforms) की सबसे महत्वपूर्ण विशेषता क्या थी?","ब्रह्म समाज, आर्य समाज और रामकृष्ण मिशन के संस्थापकों के नाम लिखें।"],"practice_prompts_en":["What was the most important feature of the ''Morley-Minto Reforms'' of 1909?","Write the names of the founders of Brahmo Samaj, Arya Samaj, and Ramakrishna Mission."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('3ac7f321-0f6f-45fe-8473-0433c9730846', 'Current Affairs', 'sports-awards-appointments', 'खेल, पुरस्कार और नियुक्तियां', 'Sports, Awards & Appointments', 'वर्ष 2022-23 की प्रमुख खेल घटनाएं (FIFA, ओलंपिक), खेल पुरस्कार (द्रोणाचार्य, अर्जुन), सैन्य नियुक्तियां और अंतर्राष्ट्रीय अभ्यास।', 1, 1773829434, 1773829434, '{"must_know_lists":[{"list_title":"भारत के प्रमुख घरेलू खेल टूर्नामेंट","list_title_en":"Major Domestic Sports Tournaments in India","items":["हॉकी - रंगास्वामी कप, आगा खां कप, ध्यानचंद ट्रॉफी","क्रिकेट - रणजी, दलीप, देवधर, ईरानी, सैयद मुश्ताक अली","फुटबॉल - डूरंड कप, रोवर्स कप, संतोष ट्रॉफी","बैडमिंटन - थॉमस कप (पुरुष), उबेर कप (महिला), सैयद मोदी (घरेलू)"],"items_en":["Hockey - Rangaswami Cup, Agha Khan Cup, Dhyan Chand Trophy","Cricket - Ranji, Duleep, Deodhar, Irani, Syed Mushtaq Ali","Football - Durand Cup, Rovers Cup, Santosh Trophy","Badminton - Thomas Cup (Men), Uber Cup (Women), Syed Modi (Domestic)"],"memory_hook":"रोवर्स फुट से (Football), रंगास्वामी स्टिक से (Hockey)।","memory_hook_en":"Rovers with Foot, Rangaswami with Stick."}],"concept_capsule":"खेल समसामयिकी (Sports Current Affairs) में 3 चीजें सबसे ज्यादा पूछी जाती हैं: 1. बड़े अंतरराष्ट्रीय इवेंट्स के विजेता (FIFA, Olympics), 2. राष्ट्रीय खेल पुरस्कार (खिलाड़ी और कोच - द्रोणाचार्य), 3. ट्रॉफियों का उनके खेलों से मिलान।","concept_capsule_en":"In Sports Current Affairs, 3 things are asked the most: 1. Winners of major international events (FIFA, Olympics), 2. National Sports Awards (Players and Coaches - Dronacharya), 3. Matching trophies with their sports.","practice_prompts":["टोक्यो ओलंपिक 2020 में भारत ने कितने पदक जीते और उनमें स्वर्ण (Gold) किसने जीता?","भारतीय नौसेना (Indian Navy) द्वारा आयोजित सबसे बड़ा द्विवार्षिक बहुपक्षीय (Multilateral) अभ्यास कौन सा है?"],"practice_prompts_en":["How many medals did India win in the Tokyo Olympics 2020, and who won the Gold?","What is the largest biennial multilateral exercise hosted by the Indian Navy?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e6d7b2fb-759e-4714-9383-7d805a23b211', 'Geography', 'world-geography-oceans-mountains-topography', 'विश्व भूगोल - महासागर, पर्वत और स्थलाकृति', 'World Geography - Oceans, Mountains & Topography', 'विश्व के प्रमुख महासागरों की संरचनाएं (नाइन्टी ईस्ट रिज), महाद्वीपीय पर्वतमालाएं (एटलस पर्वत), और दक्षिण-पूर्व एशिया की भू-राजनीति (मीकांग नदी, स्थलरुद्ध देश)।', 1, 1773829435, 1773829435, '{"must_know_lists":[{"list_title":"महाद्वीपों की सबसे लंबी नदियां और पर्वतमालाएं","list_title_en":"Longest Rivers and Mountain Ranges of Continents","items":["अफ्रीका - नील नदी (Nile), एटलस पर्वत","दक्षिण अमेरिका - अमेज़न (Amazon), एंडीज पर्वत (Andes)","उत्तरी अमेरिका - मिसिसिपी-मिसौरी, रॉकी पर्वत (Rockies)","एशिया - यांग्त्ज़ी (Yangtze), हिमालय (Himalayas)","यूरोप - वोल्गा (Volga), आल्प्स/काकेशस (Alps/Caucasus)"],"items_en":["Africa - Nile River, Atlas Mountains","South America - Amazon, Andes Mountains","North America - Mississippi-Missouri, Rocky Mountains","Asia - Yangtze, Himalayas","Europe - Volga, Alps/Caucasus"],"memory_hook":"एंडीज़ दक्षिण में, रॉकी उत्तर में (अमेरिका)।","memory_hook_en":"Andes in South, Rockies in North (Americas)."}],"concept_capsule":"विश्व भूगोल (World Geography) में ''स्थान-आधारित'' (Location-based) प्रश्न जैसे पर्वत श्रृंखलाएं (एटलस), जल निकाय (नाइन्टी ईस्ट रिज), और देशों की भू-राजनीतिक विशेषताएं (लैंडलॉक देश, अंतरराष्ट्रीय नदियां) सबसे अधिक उच्च-उपज वाले विषय हैं। मानचित्र (Map) का अध्ययन अनिवार्य है।","concept_capsule_en":"In World Geography, ''location-based'' questions like mountain ranges (Atlas), water bodies (Ninety East Ridge), and geopolitical features of countries (Landlocked countries, international rivers) are the most high-yield topics. Map study is mandatory.","practice_prompts":["विश्व का सबसे बड़ा और सबसे छोटा (क्षेत्रफल के अनुसार) स्थलरुद्ध (Landlocked) देश कौन सा है?","पनामा नहर (Panama Canal) किन दो महासागरों को जोड़ती है?"],"practice_prompts_en":["Which are the largest and smallest (by area) landlocked countries in the world?","Which two oceans are connected by the Panama Canal?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('c5b09d49-5e6f-4f85-a6f1-86e9d6534916', 'MP GK', 'mp-polity-administration-e-governance', 'मध्य प्रदेश राजव्यवस्था, प्रशासन और ई-गवर्नेंस', 'MP Polity, Administration & E-Governance', 'मध्य प्रदेश की राजनीतिक संरचना (प्रथम अध्यक्ष, मुख्यमंत्री), राष्ट्रपति शासन, पंचायती राज अधिनियम के मील के पत्थर, और सरकारी नीतियां (लाडली बहना)।', 1, 1773829436, 1773829436, '{"must_know_lists":[{"list_title":"मध्य प्रदेश राज्य के प्रमुख आयोग और स्थापना वर्ष","list_title_en":"Major Commissions of MP State and Established Years","items":["राज्य निर्वाचन आयोग - 1994","राज्य वित्त आयोग - 1994","राज्य मानवाधिकार आयोग - 1995","राज्य महिला आयोग - 1998","राज्य सूचना आयोग - 2005"],"items_en":["State Election Commission - 1994","State Finance Commission - 1994","State Human Rights Commission - 1995","State Women''s Commission - 1998","State Information Commission - 2005"],"memory_hook":"चुनाव-वित्त 94, मानवाधिकार 95, महिला 98।","memory_hook_en":"Election-Finance 94, Human Rights 95, Women 98."}],"concept_capsule":"मध्य प्रदेश की राजव्यवस्था (MP Polity) ''स्थिर'' (Static) और ''तथ्यात्मक'' (Factual) है। राज्य के पहले अधिकारियों की सूची, विधानसभा/सचिवालय के भवनों के नाम, और पंचायती राज/नगर निगम के आंकड़े हमेशा उच्च-प्राथमिकता (High-yield) वाले होते हैं। ''लाडली बहना'' जैसी फ्लैगशिप योजनाओं की नकद राशि और तिथियां जरूर रटें।","concept_capsule_en":"MP Polity is ''Static'' and ''Factual''. The list of state''s first officials, names of Assembly/Secretariat buildings, and data on Panchayati Raj/Municipal Corporations are always high-yield. Definitely rote learn the cash amounts and dates of flagship schemes like ''Ladli Behna''.","practice_prompts":["मध्य प्रदेश में विधानसभा, लोकसभा और राज्यसभा की कितनी-कितनी सीटें हैं?","राज्य नीति एवं योजना आयोग (State Policy and Planning Commission) का पदेन अध्यक्ष कौन होता है?"],"practice_prompts_en":["How many seats are there in the Vidhan Sabha, Lok Sabha, and Rajya Sabha for Madhya Pradesh?","Who is the ex-officio chairman of the State Policy and Planning Commission?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('5710d4f3-fb60-4dfe-82c2-a1f58d93f69d', 'MP GK', 'mp-history-culture-tribal-heritage', 'मध्य प्रदेश इतिहास, संस्कृति और जनजातीय विरासत', 'MP History, Culture & Tribal Heritage', 'स्वतंत्रता संग्राम के आदिवासी नायक (टंट्या मामा, सादत खान), प्राचीन व मध्यकालीन साहित्य (अल-बरूनी, सुभद्रा कुमारी चौहान), और विशिष्ट लोक कलाएं (ढोकरा, नोहडोरा)।', 1, 1773829437, 1773829437, '{"must_know_lists":[{"list_title":"मध्य प्रदेश की प्रमुख जनजातियाँ और उनकी कलाएं","list_title_en":"Major Tribes of MP and their Arts","items":["भील - पिथौरा चित्रकला (पेमा फत्या)","गोंड - नोहडोरा (भित्ति चित्र), डिग्ना","भारेवा समुदाय (बैतूल) - ढोकरा कला (धातु शिल्प)","बैगा/गोंड महिलाएँ - बिरहा (शृंगार लोकगीत)"],"items_en":["Bhil - Pithora Painting (Pema Fatya)","Gond - Nohdora (Wall painting), Digna","Bharewa community (Betul) - Dhokra art (Metal craft)","Baiga/Gond women - Birha (Romantic folk song)"],"memory_hook":"भील-पिथौरा, गोंड-नोहडोरा, भारेवा-ढोकरा।","memory_hook_en":"Bhil-Pithora, Gond-Nohdora, Bharewa-Dhokra."}],"concept_capsule":"MPGK के इतिहास और संस्कृति खंड में ''माइक्रो-लोकल'' (सूक्ष्म-स्थानीय) जानकारी पूछी जाती है। आदिवासी नायकों के वास्तविक नाम, लोकनाट्यों के कलाकारों के नाम (ओम प्रकाश शर्मा), और लोक कलाओं की तकनीकी प्रकृति (जैसे ढोकरा लॉस्ट-वैक्स धातु शिल्प है) पर पैनी नजर रखें।","concept_capsule_en":"The History and Culture section of MPGK asks ''micro-local'' information. Keep a sharp eye on real names of tribal heroes, names of folk drama artists (Om Prakash Sharma), and the technical nature of folk arts (like Dhokra is lost-wax metal craft).","practice_prompts":["तुलसी शोध संस्थान (Tulsi Shodh Sansthan) और प्रेमचंद सृजन पीठ मध्य प्रदेश में कहाँ स्थित हैं?","मध्य प्रदेश के 3 प्रमुख आदिवासी विद्रोह और उनके नेताओं के नाम लिखिए।"],"practice_prompts_en":["Where are the Tulsi Shodh Sansthan and Premchand Srijan Peeth located in MP?","Write the names of 3 major tribal revolts in MP and their leaders."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('f68b0869-c246-42a8-bb70-7645198da977', 'Polity', 'constitutional-articles-judiciary-statutory-commissions', 'संवैधानिक अनुच्छेद, न्यायपालिका और वैधानिक आयोग', 'Constitutional Articles, Judiciary & Statutory Commissions', 'भारत के नियंत्रक एवं महालेखा परीक्षक (CAG) के प्रावधान, न्यायपालिका के अधिकार (महाभियोग, स्थानांतरण), और मानवाधिकार व खाद्य आयोगों के कानूनी स्वरूप।', 1, 1773829440, 1773829440, '{"must_know_lists":[{"list_title":"संविधान की अनुसूचियाँ (Schedules) - त्वरित पुनरीक्षण","list_title_en":"Schedules of the Constitution - Quick Revision","items":["अनुसूची 1 - राज्य और संघ शासित प्रदेश","अनुसूची 2 - वेतन, भत्ते और परिलब्धियाँ","अनुसूची 3 - शपथ और प्रतिज्ञान","अनुसूची 10 - दलबदल विरोधी कानून (52वां संशोधन)","अनुसूची 11 - पंचायतें (73वां संशोधन)"],"items_en":["Schedule 1 - States and UTs","Schedule 2 - Salaries, Allowances, Emoluments","Schedule 3 - Oaths and Affirmations","Schedule 10 - Anti-Defection Law (52nd Amendment)","Schedule 11 - Panchayats (73rd Amendment)"],"memory_hook":"1-State, 2-Salary, 3-Swear, 10-Defection, 11-Village.","memory_hook_en":"1-State, 2-Salary, 3-Swear, 10-Defection, 11-Village."}],"concept_capsule":"भारतीय राजव्यवस्था में ''आयोग'' (Commissions) एक स्वर्ण खदान (Goldmine) हैं। उनकी नियुक्ति समितियों के सदस्य (विशेषकर NHRC, SHRC, CIC, CVC) और उनके अयोग्यता मानदंड (जैसे सांसद/विधायक न होना) पर सीधे सवाल बनते हैं। इसके अलावा, संविधान के महत्वपूर्ण अनुच्छेदों (जैसे राष्ट्रपति की शक्तियां) का रट्टा मारना अनिवार्य है।","concept_capsule_en":"In Indian Polity, ''Commissions'' are a goldmine. Direct questions are framed on the members of their appointment committees (especially NHRC, SHRC, CIC, CVC) and their disqualification criteria (like not being an MP/MLA). Also, rote learning important constitutional articles (like President''s powers) is mandatory.","practice_prompts":["संविधान के अनुच्छेद 352, 356 और 360 में क्या अंतर है?","राज्य निर्वाचन आयोग (State Election Commission) किस अनुच्छेद के तहत कार्य करता है और इसके क्या कार्य हैं?"],"practice_prompts_en":["What is the difference between Articles 352, 356, and 360 of the Constitution?","Under which Article does the State Election Commission operate and what are its functions?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('fcd1fec7-b8de-4eac-9bac-4de9a4dcdcf3', 'History', 'modern-history-indian-national-movement', 'आधुनिक इतिहास और भारतीय राष्ट्रीय आंदोलन', 'Modern History & Indian National Movement', 'कांग्रेस के ऐतिहासिक अधिवेशन (सूरत, लाहौर), प्रमुख गांधीवादी आंदोलन (दांडी मार्च, भारत छोड़ो) और 1919 का भारत सरकार अधिनियम।', 1, 1773829442, 1773829442, '{"must_know_lists":[{"list_title":"भारत सरकार अधिनियम 1919 (मोंटेग्यू-चेम्सफोर्ड) की प्रमुख विशेषताएं","list_title_en":"Key Features of Government of India Act 1919 (Montagu-Chelmsford)","items":["प्रांतों में द्वैध शासन (Dyarchy in Provinces) - आरक्षित और हस्तांतरित विषय","केंद्र में द्विसदनीय विधायिका (Bicameralism)","सिखों, ईसाइयों और एंग्लो-इंडियन के लिए पृथक निर्वाचन (विस्तार)","लोक सेवा आयोग (PSC) की स्थापना का प्रावधान"],"items_en":["Dyarchy in Provinces - Reserved and Transferred subjects","Bicameralism at the Center","Extension of separate electorates to Sikhs, Christians, Anglo-Indians","Provision for establishment of Public Service Commission (PSC)"],"memory_hook":"1919 = प्रांत में द्वैध (Province Dyarchy), केंद्र में दो सदन (Center Bicameral)।","memory_hook_en":"1919 = Province Dyarchy, Center Bicameral."}],"concept_capsule":"आधुनिक भारतीय इतिहास में ''क्रोनोलॉजी'' (घटनाओं का क्रम) सबसे अधिक पूछा जाता है, विशेषकर गांधीवादी युग (1917-1947) का। इसके अलावा, सामाजिक-धार्मिक सुधार आंदोलनों (संस्थापक, वर्ष, स्थान) और ब्रिटिश अधिनियमों (विशेष रूप से 1919 और 1935) के प्रमुख प्रावधानों को अच्छी तरह से याद करें।","concept_capsule_en":"In Modern Indian History, ''Chronology'' of events is asked the most, especially of the Gandhian Era (1917-1947). Furthermore, thoroughly memorize the founders, years, and locations of Socio-religious reform movements and the key provisions of British Acts (especially 1919 and 1935).","practice_prompts":["भारत सरकार अधिनियम 1935 की 3 प्रमुख विशेषताएं क्या थीं?","सविनय अवज्ञा आंदोलन (Civil Disobedience) और भारत छोड़ो आंदोलन (Quit India) के बीच मुख्य वैचारिक अंतर क्या था?"],"practice_prompts_en":["What were the 3 main features of the Government of India Act 1935?","What was the main ideological difference between the Civil Disobedience Movement and the Quit India Movement?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('444338ab-d7c4-45fc-953d-34fe7f2110cd', 'Science', 'general-science-technology-environment', 'सामान्य विज्ञान, प्रौद्योगिकी और पर्यावरण', 'General Science, Technology & Environment', 'भारत के अंतरिक्ष मिशन (मंगलयान, आदित्य-L1), आनुवंशिक रूप से संशोधित फसलें (Bt बैंगन), और विज्ञान से जुड़े प्रमुख अधिनियम व संस्थान।', 1, 1773829443, 1773829443, '{"must_know_lists":[{"list_title":"ISRO के आगामी और हालिया प्रमुख मिशन","list_title_en":"ISRO''s Upcoming and Recent Major Missions","items":["आदित्य-L1 - सूर्य का अध्ययन (Halo Orbit)","चंद्रयान-3 - चंद्रमा के दक्षिणी ध्रुव पर सॉफ्ट लैंडिंग (शिव शक्ति पॉइंट)","गगनयान - भारत का पहला मानव अंतरिक्ष उड़ान मिशन","निसार (NISAR) - NASA और ISRO का संयुक्त रडार सैटेलाइट","शुक्रयान - शुक्र (Venus) ग्रह के लिए प्रस्तावित मिशन"],"items_en":["Aditya-L1 - Study of the Sun (Halo Orbit)","Chandrayaan-3 - Soft landing on Moon''s South Pole (Shiv Shakti Point)","Gaganyaan - India''s first human spaceflight mission","NISAR - Joint radar satellite by NASA and ISRO","Shukrayaan - Proposed mission to Venus"],"memory_hook":"सूर्य-आदित्य, चाँद-चंद्रयान, इंसान-गगनयान, शुक्र-शुक्रयान।","memory_hook_en":"Sun-Aditya, Moon-Chandrayaan, Human-Gaganyaan, Venus-Shukrayaan."}],"concept_capsule":"विज्ञान और प्रौद्योगिकी (Science & Tech) में ''ISRO के मिशन'' (वर्तमान और ऐतिहासिक) सबसे उच्च-प्राथमिकता वाला क्षेत्र है। इसके अलावा, बायोटेक्नोलॉजी में आनुवंशिक रूप से संशोधित (GM) फसलों के उद्देश्य (कीट प्रतिरोध, सूखा सहिष्णुता) और भारत में उनकी कानूनी स्थिति (GEAC की मंजूरी) के बारे में वैचारिक स्पष्टता होनी चाहिए।","concept_capsule_en":"In Science & Tech, ''ISRO Missions'' (current and historical) are the highest priority area. Additionally, in Biotechnology, there should be conceptual clarity regarding the objectives of Genetically Modified (GM) crops (insect resistance, drought tolerance) and their legal status in India (GEAC approval).","practice_prompts":["जेनेटिक इंजीनियरिंग मूल्यांकन समिति (GEAC) किस मंत्रालय के अंतर्गत कार्य करती है?","PSLV और GSLV लॉन्च वाहनों के बीच मुख्य तकनीकी अंतर क्या है?"],"practice_prompts_en":["Under which ministry does the Genetic Engineering Appraisal Committee (GEAC) function?","What is the main technical difference between PSLV and GSLV launch vehicles?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e7ad88fa-7307-42a8-8250-f2044cf4fb7b', 'Polity', 'constitutional-and-statutory-bodies', 'संवैधानिक और वैधानिक निकाय', 'Constitutional and Statutory Bodies', 'सूचना का अधिकार, राज्य मानवाधिकार आयोग, और विकास निगरानी एवं मूल्यांकन कार्यालय (DMEO) के कार्य एवं नियुक्तियाँ।', 1, 1773829450, 1773829450, '{"must_know_lists":[{"list_title":"विभिन्न आयोगों की नियुक्ति समितियों के अध्यक्ष","list_title_en":"Chairpersons of Appointment Committees for Various Commissions","items":["राष्ट्रीय मानवाधिकार आयोग (NHRC) - प्रधानमंत्री","राज्य मानवाधिकार आयोग (SHRC) - मुख्यमंत्री","केंद्रीय सूचना आयोग (CIC) - प्रधानमंत्री","राज्य सूचना आयोग (SIC) - मुख्यमंत्री","केंद्रीय सतर्कता आयोग (CVC) - प्रधानमंत्री"],"items_en":["NHRC - Prime Minister","SHRC - Chief Minister","CIC - Prime Minister","SIC - Chief Minister","CVC - Prime Minister"],"memory_hook":"केंद्र में PM, राज्य में CM ही बॉस होते हैं।","memory_hook_en":"PM is the boss at the Center, CM at the State."}],"concept_capsule":"भारतीय राजव्यवस्था में ''आयोगों (Commissions)'' और ''अधिनियमों (Acts)'' की धाराएं (जैसे RTI की धारा 20) MPPSC के लिए अत्यधिक स्कोरिंग हैं। नियुक्ति समितियों की संरचना (Composition) और जुर्माना लगाने के अधिकारों को स्पष्ट रूप से याद रखें।","concept_capsule_en":"In Indian Polity, ''Commissions'' and sections of ''Acts'' (like Section 20 of RTI) are highly scoring for MPPSC. Clearly memorize the composition of appointment committees and the powers to impose fines.","practice_prompts":["राष्ट्रीय मानवाधिकार आयोग (NHRC) की नियुक्ति समिति में कौन-कौन से केंद्रीय मंत्री शामिल होते हैं?","केंद्रीय सूचना आयुक्त (CIC) का कार्यकाल कितना होता है (RTI संशोधन 2019 के बाद)?"],"practice_prompts_en":["Which Union Ministers are included in the appointment committee of the National Human Rights Commission (NHRC)?","What is the tenure of the Chief Information Commissioner (CIC) (after the RTI Amendment 2019)?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('d7bdedd3-0451-4937-a61a-1de3261eb890', 'Science', 'human-anatomy-nutrition-diseases', 'मानव शारीरिक रचना और पोषण संबंधी रोग', 'Human Anatomy & Nutrition Diseases', 'सर्टोली कोशिकाएं, पेट में एसिड स्राव (HCl), और विटामिन सी की कमी (स्कर्वी)।', 1, 1773829450, 1773829450, '{"must_know_lists":[{"list_title":"पाचन तंत्र के प्रमुख एंजाइम/स्राव","list_title_en":"Major Enzymes/Secretions of the Digestive System","items":["लार (Saliva) - एमाइलेज (Amylase - स्टार्च का पाचन)","अमाशय (Stomach) - HCl, पेप्सिन (प्रोटीन का पाचन)","यकृत (Liver) - पित्त रस (Bile - वसा का पायसीकरण)","अग्न्याशय (Pancreas) - लाइपेज (Lipase), ट्रिप्सिन (Trypsin)"],"items_en":["Saliva - Amylase (Digests starch)","Stomach - HCl, Pepsin (Digests proteins)","Liver - Bile (Emulsifies fats)","Pancreas - Lipase, Trypsin"],"memory_hook":"मुंह में स्टार्च, पेट में प्रोटीन, लिवर में फैट।","memory_hook_en":"Starch in mouth, Protein in stomach, Fat in liver."}],"concept_capsule":"मानव जीव विज्ञान (Human Biology) में पाचन तंत्र (ग्रंथियां, एंजाइम) और पोषण (विटामिन, कमी से रोग) सबसे मौलिक और दोहराए जाने वाले विषय हैं। वैज्ञानिक नामों (जैसे एस्कॉर्बिक एसिड) को बीमारियों से जोड़ना सीखें।","concept_capsule_en":"In Human Biology, the Digestive System (glands, enzymes) and Nutrition (vitamins, deficiency diseases) are the most fundamental and repeated topics. Learn to link scientific names (like Ascorbic Acid) to diseases.","practice_prompts":["विटामिन B12 का वैज्ञानिक नाम क्या है और इसकी कमी से कौन सा रोग होता है?","मानव शरीर में इंसुलिन (Insulin) का उत्पादन किस ग्रंथि द्वारा होता है?"],"practice_prompts_en":["What is the scientific name of Vitamin B12 and what disease is caused by its deficiency?","Which gland produces Insulin in the human body?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('79b7a58d-f4d5-4a5a-9028-522071dca98a', 'Current Affairs', 'global-declarations-organizations-international-appointments', 'वैश्विक घोषणाएं, संगठन और अंतर्राष्ट्रीय नियुक्तियां', 'Global Declarations, Organizations & International Appointments', 'UN द्वारा घोषित वर्ष (बाजरा वर्ष), वैश्विक संगठनों की स्थापना/मुख्यालय (WHO, UNICEF), और प्रमुख महिला राष्ट्राध्यक्ष।', 1, 1773829451, 1773829451, '{"must_know_lists":[{"list_title":"प्रमुख UN संस्थाएं और उनके मुख्यालय","list_title_en":"Major UN Agencies and their Headquarters","items":["WHO, WTO, ILO, WMO - जिनेवा (स्विट्जरलैंड)","UN, UNICEF, UNDP - न्यूयॉर्क (USA)","UNESCO - पेरिस (फ्रांस)","FAO, WFP - रोम (इटली)","ICJ (अंतर्राष्ट्रीय न्यायालय) - द हेग (नीदरलैंड)"],"items_en":["WHO, WTO, ILO, WMO - Geneva (Switzerland)","UN, UNICEF, UNDP - New York (USA)","UNESCO - Paris (France)","FAO, WFP - Rome (Italy)","ICJ (International Court of Justice) - The Hague (Netherlands)"],"memory_hook":"स्वास्थ्य/व्यापार (Health/Trade) = जिनेवा। बच्चे/पैसे (Kids/Funds) = न्यूयॉर्क। खाना (Food) = रोम।","memory_hook_en":"Health/Trade = Geneva. Kids/Funds = New York. Food = Rome."}],"concept_capsule":"वैश्विक संस्थाओं (UN Agencies) के मुख्यालय और स्थापना वर्ष MPPSC के सबसे ''स्टेटिक'' करेंट अफेयर्स हैं। इसके साथ ही, UN द्वारा घोषित ''वर्ष'' (Millets 2023) और वैश्विक स्तर पर महिलाओं की ऐतिहासिक नियुक्तियाँ (First female heads of state) अवश्य रटें।","concept_capsule_en":"Headquarters and establishment years of UN Agencies are the most ''static'' current affairs for MPPSC. Along with this, UN declared ''Years'' (Millets 2023) and historic female appointments globally (First female heads of state) must be rote learned.","practice_prompts":["विश्व व्यापार संगठन (WTO) की पहली महिला महानिदेशक कौन हैं?","संयुक्त राष्ट्र पर्यावरण कार्यक्रम (UNEP) का मुख्यालय कहाँ स्थित है?"],"practice_prompts_en":["Who is the first female Director-General of the World Trade Organization (WTO)?","Where is the headquarters of the United Nations Environment Programme (UNEP) located?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('88cc5784-9269-4484-a39b-c8f355130338', 'ICT', 'internet-e-commerce-network-topologies', 'इंटरनेट, ई-कॉमर्स और नेटवर्क टोपोलॉजी', 'Internet, E-Commerce & Network Topologies', 'ई-कॉमर्स के मॉडल (C2C, C2B), साइबर सुरक्षा (वर्चुअल कीबोर्ड, स्पूफिंग), और नेटवर्क आर्किटेक्चर (टॉपोलॉजी, DNS)।', 1, 1773829452, 1773829452, '{"must_know_lists":[{"list_title":"साइबर सुरक्षा के प्रमुख खतरे (Threats)","list_title_en":"Major Cyber Security Threats","items":["फिशिंग (Phishing) - धोखे से पासवर्ड/कार्ड डिटेल चुराना","स्पूफिंग (Spoofing) - गलत पहचान (Fake IP/Email) से आना","कीलॉगर (Keylogger) - कीबोर्ड पर दबाई गई कुंजियों (Keys) को रिकॉर्ड करना","रैनसमवेयर (Ransomware) - डेटा लॉक करके फिरौती (पैसे) मांगना","डीडॉस (DDoS) - नकली ट्रैफ़िक भेजकर सर्वर को ठप कर देना"],"items_en":["Phishing - Stealing passwords/card details via deceit","Spoofing - Arriving with a fake identity (Fake IP/Email)","Keylogger - Recording keystrokes pressed on the keyboard","Ransomware - Locking data and demanding ransom (money)","DDoS - Flooding a server with fake traffic to crash it"],"memory_hook":"फिशिंग(धोखा), स्पूफिंग(भेष), रैनसम(पैसा), DDoS(ट्रैफिक जाम)।","memory_hook_en":"Phishing(Cheat), Spoofing(Disguise), Ransom(Money), DDoS(Traffic Jam)."}],"concept_capsule":"ई-कॉमर्स के चारों मॉडल (B2B, B2C, C2C, C2B) और साइबर हमलों की सटीक परिभाषा (फिशिंग बनाम स्पूफिंग) ICT के सबसे बुनियादी और स्कोरिंग भाग हैं। नेटवर्किंग में टोपोलॉजी (Bus, Star, Ring, Mesh) की आकृतियों को समझना आवश्यक है।","concept_capsule_en":"The four models of E-commerce (B2B, B2C, C2C, C2B) and exact definitions of cyber attacks (Phishing vs. Spoofing) are the most basic and scoring parts of ICT. Understanding the shapes of network topologies (Bus, Star, Ring, Mesh) is necessary.","practice_prompts":["LAN, MAN और WAN नेटवर्क्स के बीच उनकी भौगोलिक सीमा (Geographical Range) के आधार पर क्या अंतर है?","ई-कॉमर्स में B2B मॉडल के दो भारतीय उदाहरण (कंपनियों के नाम) दीजिए।"],"practice_prompts_en":["What is the difference between LAN, MAN, and WAN networks based on their geographical range?","Give two Indian examples (company names) of the B2B model in e-commerce."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('86a04662-101a-496e-a21a-ea34c8b13867', 'Geography', 'indian-world-geography-demography-environment', 'भारतीय और विश्व भूगोल, जनसांख्यिकी और पर्यावरण', 'Indian & World Geography, Demography & Environment', '2011 जनगणना (नगरीकरण), भारत की नदियाँ, पर्वत (नवीन वलित), अंतर्राष्ट्रीय सीमाएँ (मैकमोहन रेखा) और प्रमुख नहरें (इंदिरा गांधी)।', 1, 1773829454, 1773829454, '{"must_know_lists":[{"list_title":"विश्व की प्रमुख सीमा रेखाएं (Boundary Lines)","list_title_en":"Major Boundary Lines of the World","items":["मैकमोहन रेखा - भारत और चीन (तिब्बत)","रेडक्लिफ रेखा - भारत और पाकिस्तान (तथा बांग्लादेश)","डूरंड रेखा - भारत और अफगानिस्तान (अब मुख्य रूप से पाक-अफगान)","49वीं समानांतर (49th Parallel) - USA और कनाडा (सबसे शांतिपूर्ण सीमा)","38वीं समानांतर (38th Parallel) - उत्तर और दक्षिण कोरिया"],"items_en":["McMahon Line - India and China (Tibet)","Radcliffe Line - India and Pakistan (and Bangladesh)","Durand Line - India and Afghanistan (now mostly Pak-Afghan)","49th Parallel - USA and Canada (Most peaceful border)","38th Parallel - North and South Korea"],"memory_hook":"मैक-चीन (Mc-China), रेड-पाक (Red-Pak), 49-USA, 38-कोरिया।","memory_hook_en":"Mc-China, Red-Pak, 49-USA, 38-Korea."},{"list_title":"चट्टानों के प्रकार और उनमें पाए जाने वाले संसाधन","list_title_en":"Types of Rocks and Resources Found in Them","items":["आग्नेय (Igneous) - सोना, चांदी, तांबा, लोहा (धात्विक खनिज)","अवसादी (Sedimentary) - कोयला, पेट्रोलियम, प्राकृतिक गैस (जीवाश्म)","कायांतरित (Metamorphic) - संगमरमर, हीरा, स्लेट"],"items_en":["Igneous - Gold, Silver, Copper, Iron (Metallic minerals)","Sedimentary - Coal, Petroleum, Natural Gas (Fossils)","Metamorphic - Marble, Diamond, Slate"],"memory_hook":"जीवाश्म = अवसादी (Fossils = Sedimentary)। धातु = आग्नेय (Metal = Igneous)।","memory_hook_en":"Fossils = Sedimentary. Metal = Igneous."}],"concept_capsule":"भूगोल में ''मैच द कॉलम'' प्रश्नों (विशेषकर नदियों की सहायक नदियां और अंतर्राष्ट्रीय सीमाएं) का बहुत महत्व है। चट्टानों के प्रकार (अवसादी में जीवाश्म) और पर्वतों की प्रकृति (वलित बनाम ब्लॉक) जैसे मूलभूत वैचारिक प्रश्न अक्सर पूछे जाते हैं। MP की जलवायु और कर्क रेखा के जिले रटे हुए होने चाहिए।","concept_capsule_en":"In Geography, ''Match the Column'' questions (especially tributaries of rivers and international boundaries) are highly important. Fundamental conceptual questions like rock types (fossils in sedimentary) and nature of mountains (fold vs block) are frequently asked. MP''s climate and districts on the Tropic of Cancer must be rote-learned.","practice_prompts":["मलक्का जलसंधि (Strait of Malacca) किन दो जल निकायों (Water bodies) को जोड़ती है?","कर्क रेखा (Tropic of Cancer) भारत के किन 8 राज्यों से होकर गुजरती है?"],"practice_prompts_en":["Which two water bodies are connected by the Strait of Malacca?","Through which 8 states of India does the Tropic of Cancer pass?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e81f4916-95f9-4c81-a06e-72f8ffe89e06', 'History', 'ancient-medieval-modern-indian-history', 'प्राचीन, मध्यकालीन और आधुनिक भारतीय इतिहास', 'Ancient, Medieval & Modern Indian History', 'सिंधु घाटी की मुहरें, चोल प्रशासन (ग्राम स्वायत्तता), डलहौजी की हड़प नीति, गांधीजी की दांडी यात्रा, और राजा रणजीत सिंह का मिसल।', 1, 1773829457, 1773829457, '{"must_know_lists":[{"list_title":"लॉर्ड डलहौजी का ''व्यपगत सिद्धान्त'' (Doctrine of Lapse) - विलय का क्रम","list_title_en":"Lord Dalhousie''s ''Doctrine of Lapse'' - Order of Annexation","items":["1. सतारा (1848) - सबसे पहला","2. जैतपुर और सम्बलपुर (1849)","3. बघाट (1850)","4. उदयपुर (1852)","5. झाँसी (1853)","6. नागपुर (1854)","7. अवध (1856) - कुशासन (Misgovernance) के आरोप में"],"items_en":["1. Satara (1848) - The First","2. Jaitpur & Sambalpur (1849)","3. Baghat (1850)","4. Udaipur (1852)","5. Jhansi (1853)","6. Nagpur (1854)","7. Awadh (1856) - On charges of Misgovernance"],"memory_hook":"S-J-S-B-U-J-N-A (सतारा से अवध तक)। अवध विलय कुशासन पर था, गोद प्रथा पर नहीं।","memory_hook_en":"S-J-S-B-U-J-N-A. Awadh was annexed on misgovernance, not adoption."}],"concept_capsule":"इतिहास में ''उपाधियां/कथन'' (जैसे ''शिक्षितों का मेला''), ''प्राचीन काल की प्रशासनिक विशेषताएं'' (चोल ग्राम स्वशासन) और ''अंग्रेजों की नीतियां'' (डलहौजी का विलय) हमेशा परीक्षा के केंद्र में रहते हैं। मंदसौर (दशपुर) का रेशम बुनकर अभिलेख MP इतिहास का एक बहुत ही विशेष तथ्य है।","concept_capsule_en":"In History, ''Titles/Quotes'' (like ''fair of educated''), ''administrative features of ancient times'' (Chola village self-gov), and ''British policies'' (Dalhousie''s annexations) are always at the center of exams. Mandsaur''s (Dashpur) silk weavers'' inscription is a very special fact of MP history.","practice_prompts":["हड़प्पा सभ्यता के किन स्थलों से ''बंदरगाह'' (Dockyard) और ''जुते हुए खेत'' के साक्ष्य मिले हैं?","1946 में बनी ''अंतरिम सरकार'' (Interim Government) में वित्त मंत्री (Finance Minister) कौन थे?"],"practice_prompts_en":["From which sites of Harappan civilization is evidence of a ''Dockyard'' and a ''Ploughed field'' found?","Who was the Finance Minister in the ''Interim Government'' formed in 1946?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('2b874f75-7902-49d2-a57a-12a920b7a7dc', 'Economy', 'current-economic-survey-finance', 'वर्तमान आर्थिक सर्वेक्षण और वित्त', 'Current Economic Survey & Finance', 'आर्थिक सर्वेक्षण के अनुमान (GDP) और BHEL को महारत्न का दर्जा।', 1, 1773829459, 1773829459, '{"must_know_lists":[{"list_title":"महारत्न कंपनियों के दर्जे के लिए मानदंड (Criteria)","list_title_en":"Criteria for Maharatna Company Status","items":["पहले से ही ''नवरत्न'' (Navratna) का दर्जा प्राप्त होना चाहिए।","पिछले 3 वर्षों का औसत वार्षिक टर्नओवर > ₹25,000 करोड़।","पिछले 3 वर्षों की औसत वार्षिक शुद्ध संपत्ति (Net Worth) > ₹15,000 करोड़।","पिछले 3 वर्षों का औसत शुद्ध लाभ (Net Profit) > ₹5,000 करोड़।","स्टॉक एक्सचेंज में सूचीबद्ध (Listed) होना चाहिए।"],"items_en":["Must already have ''Navratna'' status.","Average annual turnover of last 3 years > ₹25,000 crore.","Average annual net worth of last 3 years > ₹15,000 crore.","Average net profit of last 3 years > ₹5,000 crore.","Must be listed on the Indian stock exchange."],"memory_hook":"25-15-5 (टर्नओवर-संपत्ति-लाभ)।","memory_hook_en":"25-15-5 (Turnover-Networth-Profit)."}],"concept_capsule":"अर्थव्यवस्था में, सार्वजनिक क्षेत्र के उपक्रमों (PSUs) का वर्गीकरण (महारत्न, नवरत्न) और केंद्रीय बजट/आर्थिक सर्वेक्षण के सटीक आंकड़े (जैसे राजकोषीय घाटा %, GDP वृद्धि दर) सबसे महत्वपूर्ण तथ्य हैं जिन्हें परीक्षा से ठीक पहले अद्यतन (Update) करना चाहिए।","concept_capsule_en":"In Economy, the classification of PSUs (Maharatna, Navratna) and exact figures from the Union Budget/Economic Survey (like Fiscal Deficit %, GDP growth rate) are the most crucial facts that must be updated right before the exam.","practice_prompts":["वर्तमान में भारत में कुल कितनी ''महारत्न'' कंपनियां हैं? नवीनतम का नाम बताएं।","केंद्रीय बजट में ''राजकोषीय घाटा'' (Fiscal Deficit) क्या दर्शाता है?"],"practice_prompts_en":["How many total ''Maharatna'' companies are there in India currently? Name the latest one.","What does the ''Fiscal Deficit'' indicate in the Union Budget?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('922e69f6-9b07-4607-a11f-f88c81f04eeb', 'MP GK', 'mp-art-culture-personalities', 'मध्य प्रदेश कला, संस्कृति और व्यक्तित्व', 'MP Art, Culture & Personalities', 'मध्य प्रदेश के प्रमुख लोक नृत्य (राई), जनजातीय कलाएं (दिग्ना), संगीत घराने/कलाकार और क्षेत्रीय लोकनाट्य (तुर्रा कलंगी)।', 1, 1773829471, 1773829471, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के पद्म पुरस्कार विजेता (कला और संस्कृति - 2021/22)","list_title_en":"Padma Awardees of MP (Art & Culture - 2021/22)","items":["राम सहाय पाण्डे - राई नृत्य (बुंदेलखंड)","दुर्गा बाई व्याम - गोंड चित्रकला (डिंडौरी)","भूरी बाई - भील चित्रकला (पिथौरा)","अर्जुन सिंह धुर्वे - बैगा परधोनी नृत्य"],"items_en":["Ram Sahay Pandey - Rai Dance (Bundelkhand)","Durga Bai Vyam - Gond Painting (Dindori)","Bhuri Bai - Bhil Painting (Pithora)","Arjun Singh Dhurve - Baiga Pardhoni Dance"],"memory_hook":"पाण्डे का राई, दुर्गा का दिग्ना, भूरी की पिथौरा।","memory_hook_en":"Pandey''s Rai, Durga''s Digna, Bhuri''s Pithora."}],"concept_capsule":"मध्य प्रदेश के कला और संस्कृति खंड में ''माइक्रो-लोकल'' (सूक्ष्म-स्थानीय) जानकारी पूछी जाती है। आदिवासी कलाकारों (विशेषकर जिन्हें हाल ही में पद्म पुरस्कार मिला हो) की विशिष्ट कला शैली (जैसे दिग्ना, पिथौरा) और लोकनाट्यों के अंचल (Region) पर पैनी नजर रखें।","concept_capsule_en":"The Art and Culture section of MPGK asks ''micro-local'' information. Keep a sharp eye on the specific art styles of tribal artists (especially recent Padma awardees, like Digna, Pithora) and the regions of folk dramas.","practice_prompts":["मध्य प्रदेश के मालवा और बुंदेलखंड अंचल के प्रमुख लोक गायन (Folk Songs) कौन-से हैं?","सैयद हैदर रज़ा और मकबूल फिदा हुसैन का संबंध मध्य प्रदेश के किन जिलों से था?"],"practice_prompts_en":["What are the major folk songs of the Malwa and Bundelkhand regions of MP?","Syed Haider Raza and Maqbool Fida Husain were associated with which districts of Madhya Pradesh?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('7cc954cf-841c-4f7a-b88f-8be016a0de7a', 'MP GK', 'mp-legislature-administration', 'मध्य प्रदेश विधायिका और प्रशासन', 'MP Legislature & Administration', 'मध्य प्रदेश विधानसभा के ऐतिहासिक तथ्य, प्रोटेम स्पीकर, सदन के नेता और राज्यपालों से जुड़े अनोखे रिकॉर्ड।', 1, 1773829472, 1773829472, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के राजनैतिक इतिहास के ''अपवाद'' (Exceptions)","list_title_en":"Exceptions in MP''s Political History","items":["मुख्यमंत्री जो सदन के नेता नहीं रहे - गोविन्द नारायण सिंह","राज्यपाल जो हरियाणा के CM रहे - भगवत दयाल शर्मा","अध्यक्ष जो बाद में CM बने - कुंजीलाल दुबे (कार्यवाहक), ईश्वरदास रोहाणी","प्रोटेम, अध्यक्ष, उपाध्यक्ष तीनों पदों पर - रामकिशोर शुक्ला"],"items_en":["CM who was not Leader of the House - Govind Narayan Singh","Governor who was CM of Haryana - Bhagwat Dayal Sharma","Speaker who later became CM - Kunjilal Dubey (Acting), Ishwardas Rohani","Held Pro-tem, Speaker, Deputy Speaker posts - Ramkishore Shukla"],"memory_hook":"MP Polity के अपवाद हमेशा परीक्षा के सवाल बनते हैं।","memory_hook_en":"Exceptions in MP Polity always become exam questions."}],"concept_capsule":"MPPSC हमेशा राज्य के मुख्यमंत्रियों, राज्यपालों और विधानसभा अध्यक्षों के ''ऐतिहासिक ट्रिविया'' (अनोखे रिकॉर्ड, पूर्व पद, संविधान सभा से संबंध) पर गहराई से सवाल पूछता है। पूरी सूची का बारीकी से अध्ययन करें।","concept_capsule_en":"MPPSC always asks in-depth questions on the ''historical trivia'' (unique records, previous posts, relation to Constituent Assembly) of the State''s CMs, Governors, and Assembly Speakers. Study the entire list meticulously.","practice_prompts":["मध्य प्रदेश के ऐसे 3 राज्यपालों के नाम बताइए जो मध्य प्रदेश के जन्म (1956) से पूर्व पैदा हुए और संविधान सभा का हिस्सा रहे?","मध्य प्रदेश के सबसे छोटे कार्यकाल वाले मुख्यमंत्री कौन थे?"],"practice_prompts_en":["Name 3 Governors of MP who were born before the creation of MP (1956) and were part of the Constituent Assembly?","Who was the Chief Minister of Madhya Pradesh with the shortest tenure?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('ff0a5131-0bf3-464b-b71a-24fd7de131ff', 'MP GK', 'mp-transport-infrastructure-thermal-power', 'मध्य प्रदेश परिवहन, बुनियादी ढांचा और थर्मल पावर', 'MP Transport, Infrastructure & Thermal Power', 'मध्य प्रदेश के अंतर्राष्ट्रीय हवाई अड्डे, प्रमुख एक्सप्रेस-वे (अटल प्रगति पथ) और तापीय विद्युत केंद्र।', 1, 1773829472, 1773829472, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के प्रमुख एक्सप्रेस-वे (निर्माणाधीन/प्रस्तावित)","list_title_en":"Major Expressways of MP (Under Construction/Proposed)","items":["अटल प्रगति पथ (चंबल एक्सप्रेस-वे) - 404 किमी (MP में)","नर्मदा प्रगति पथ (नर्मदा एक्सप्रेस-वे) - 900+ किमी (अमरकंटक से अलीराजपुर)","विंध्य एक्सप्रेस-वे - भोपाल से सिंगरौली","दिल्ली-मुंबई इंडस्ट्रियल कॉरिडोर (DMIC) - MP के पश्चिमी हिस्से से"],"items_en":["Atal Pragati Path (Chambal Expressway) - 404 km (in MP)","Narmada Pragati Path (Narmada Expressway) - 900+ km (Amarkantak to Alirajpur)","Vindhya Expressway - Bhopal to Singrauli","Delhi-Mumbai Industrial Corridor (DMIC) - Through western MP"],"memory_hook":"उत्तर में अटल, मध्य में नर्मदा, पूर्व में विंध्य।","memory_hook_en":"Atal in North, Narmada in Middle, Vindhya in East."}],"concept_capsule":"मध्य प्रदेश के बुनियादी ढांचे (हवाई अड्डे, राजमार्ग 44/46) और ऊर्जा क्षेत्र (सिंगाजी, विंध्याचल ताप विद्युत) के अद्यतन आंकड़े परीक्षा में सीधे मिलान (Match the following) के रूप में आते हैं।","concept_capsule_en":"Updated figures of MP''s infrastructure (airports, highways 44/46) and energy sector (Singaji, Vindhyachal thermal power) appear directly as ''Match the following'' in the exam.","practice_prompts":["मध्य प्रदेश का सबसे बड़ा तापीय विद्युत केंद्र (Thermal Power Plant) कौन-सा है और इसकी क्षमता कितनी है?","NH-46 मध्य प्रदेश के किन प्रमुख शहरों से होकर गुजरता है?"],"practice_prompts_en":["Which is the largest Thermal Power Plant in MP and what is its capacity?","Through which major cities of MP does NH-46 pass?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('77461108-2fdd-42f0-ac07-cf54b4750ebb', 'MP GK', 'mp-important-days-geography-soil', 'मध्य प्रदेश महत्वपूर्ण दिवस, भूगोल और मिट्टी', 'MP Important Days, Geography & Soil', 'मध्य प्रदेश में विमुक्त जाति दिवस, राष्ट्रीय राजमार्गों का मिलान, और मालवा पठार की कृषि-भूगोल (काली मिट्टी और कपास)।', 1, 1773829473, 1773829473, '{"must_know_lists":[{"list_title":"मध्य प्रदेश से गुजरने वाले प्रमुख नए राष्ट्रीय राजमार्ग","list_title_en":"Major New National Highways passing through MP","items":["NH-46: ग्वालियर - शिवपुरी - गुना - भोपाल - बैतूल (MP का सबसे लंबा राजकीय NH)","NH-44: श्रीनगर से कन्याकुमारी (मुरैना, ग्वालियर, सागर, नरसिंहपुर, सिवनी)","NH-47: गुजरात से महाराष्ट्र वाया इंदौर, बैतूल","NH-30: सितारगंज से विजयवाड़ा (रीवा, कटनी, जबलपुर, मंडला)"],"items_en":["NH-46: Gwalior - Shivpuri - Guna - Bhopal - Betul (Longest internal NH of MP)","NH-44: Srinagar to Kanyakumari (Morena, Gwalior, Sagar, Narsinghpur, Seoni)","NH-47: Gujarat to Maharashtra via Indore, Betul","NH-30: Sitarganj to Vijayawada (Rewa, Katni, Jabalpur, Mandla)"],"memory_hook":"46 भोपाल का, 44 पूरे देश का।","memory_hook_en":"46 is Bhopal''s, 44 is for the whole country."}],"concept_capsule":"मध्य प्रदेश के आर्थिक भूगोल (Economic Geography) में कृषि आधारित उद्योगों (जैसे सूती वस्त्र-मालवा, चीनी-उत्तरी MP) का क्षेत्रीय वितरण मिट्टी और जलवायु पर निर्भर करता है। राष्ट्रीय राजमार्गों के नए क्रमांकों (New Numbering) का मिलान अति-महत्वपूर्ण है।","concept_capsule_en":"In MP''s Economic Geography, the regional distribution of agro-based industries (like cotton textiles in Malwa, sugar in North MP) depends on soil and climate. Matching the new numbering of National Highways is hyper-important.","practice_prompts":["मध्य प्रदेश में काली मिट्टी का निर्माण किन चट्टानों के क्षरण (Weathering) से हुआ है?","NH-44 और NH-46 मध्य प्रदेश के किस शहर में एक-दूसरे को काटते/मिलते हैं?"],"practice_prompts_en":["Black soil in Madhya Pradesh is formed by the weathering of which rocks?","In which city of Madhya Pradesh do NH-44 and NH-46 intersect/meet?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('213137ae-acf7-46eb-8d49-463c72683009', 'MP GK', 'mp-irrigation-minerals-history', 'मध्य प्रदेश सिंचाई, खनिज और इतिहास', 'MP Irrigation, Minerals & History', 'मध्य प्रदेश की नदी घाटी परियोजनाएं (बारना), खनिज संपदा (मलंजखंड कॉपर), और मध्यकालीन इतिहास (सिरोंज का कपड़ा व्यापार)।', 1, 1773829473, 1773829473, '{"must_know_lists":[{"list_title":"मध्य प्रदेश की प्रमुख सिंचाई परियोजनाएं और नदियां","list_title_en":"Major Irrigation Projects and Rivers of MP","items":["बाणसागर - सोन नदी (शहडोल)","माताटीला / राजघाट - बेतवा नदी (अशोकनगर/UP सीमा)","तवा - तवा नदी (होशंगाबाद)","बारना - बारना नदी (रायसेन)","गांधी सागर - चंबल नदी (मंदसौर)"],"items_en":["Bansagar - Son river (Shahdol)","Matatila / Rajghat - Betwa river (Ashoknagar/UP border)","Tawa - Tawa river (Hoshangabad)","Barna - Barna river (Raisen)","Gandhi Sagar - Chambal river (Mandsaur)"],"memory_hook":"गांधी-चंबल, माता-बेतवा, बाण-सोन।","memory_hook_en":"Gandhi-Chambal, Mata-Betwa, Ban-Son."}],"concept_capsule":"मध्य प्रदेश के खनिज (Minerals) और सिंचाई परियोजनाएं (Projects) हर साल ''गलत युग्म पहचानें'' (Identify the wrong pair) प्रारूप में पूछे जाते हैं। 1857 के विद्रोह के दौरान सीहोर और महू जैसे छोटे केंद्रों की घटनाओं पर विशेष ध्यान दें।","concept_capsule_en":"Minerals and Irrigation Projects of MP are asked every year in the ''Identify the wrong pair'' format. Pay special attention to events in smaller centers like Sehore and Mhow during the 1857 revolt.","practice_prompts":["मध्य प्रदेश में ''हीरा'' (Diamond) का उत्पादन मुख्य रूप से किन खदानों से होता है?","चंबल नदी पर स्थित ''राणा प्रताप सागर'' बांध किस राज्य में है?"],"practice_prompts_en":["From which mines is ''Diamond'' mainly produced in Madhya Pradesh?","In which state is the ''Rana Pratap Sagar'' dam located on the Chambal River?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('4e8156f5-f8da-4f1a-bd20-564c2ad7b3c1', 'MP GK', 'mp-panchayati-raj-sports', 'मध्य प्रदेश पंचायती राज और खेल', 'MP Panchayati Raj & Sports', 'पंचायती राज की कार्यप्रणाली (ग्रामसभा बैठक, समितियां) और मध्य प्रदेश के प्रसिद्ध खेल व्यक्तित्व (चिंकी यादव, विवेक सागर)।', 1, 1773829474, 1773829474, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के प्रमुख खिलाड़ी और उनके खेल","list_title_en":"Major Sports Personalities of MP and their Sports","items":["ऐश्वर्य प्रताप सिंह तोमर - निशानेबाजी (Shooting)","विवेक सागर - हॉकी (Hockey)","मुस्कान किरार - तीरंदाजी (Archery)","आवेश खान - क्रिकेट (Cricket)","प्राची यादव - पैरा-कैनो (Para-canoe)"],"items_en":["Aishwary Pratap Singh Tomar - Shooting","Vivek Sagar - Hockey","Muskan Kirar - Archery","Avesh Khan - Cricket","Prachi Yadav - Para-canoe"],"memory_hook":"चिंकी/ऐश्वर्य (निशाना), मुस्कान (तीर), विवेक (हॉकी)।","memory_hook_en":"Chinki/Aishwary (Aim), Muskan (Arrow), Vivek (Hockey)."}],"concept_capsule":"मध्य प्रदेश पंचायती राज अधिनियम के व्यावहारिक नियम (जैसे बैठकों की अध्यक्षता) और हाल ही में चर्चा में रहे राज्य के खेल व्यक्तित्व (Olympics/Asian Games में भाग लेने वाले) परीक्षा में सीधे पूछे जाते हैं।","concept_capsule_en":"The practical rules of the MP Panchayati Raj Act (like presiding over meetings) and recently discussed state sports personalities (participants in Olympics/Asian Games) are asked directly in the exam.","practice_prompts":["मध्य प्रदेश में ग्राम सभा की बैठक वर्ष में न्यूनतम कितनी बार होना अनिवार्य है?","मध्य प्रदेश राज्य शूटिंग अकादमी किस शहर में स्थित है?"],"practice_prompts_en":["What is the minimum mandatory number of times a Gram Sabha meeting must be held in a year in Madhya Pradesh?","In which city is the Madhya Pradesh State Shooting Academy located?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('c1cb356c-87d3-43bd-9142-73f337c90c05', 'MP GK', 'mp-fairs-festivals-literature', 'मध्य प्रदेश मेले, उत्सव और साहित्य', 'MP Fairs, Festivals & Literature', 'गोटमार मेला (छिंदवाड़ा) की अनूठी परंपरा और मध्य प्रदेश के प्रसिद्ध कवि/लेखक (माखनलाल चतुर्वेदी)।', 1, 1773829475, 1773829475, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के विशिष्ट मेले और स्थान","list_title_en":"Unique Fairs of MP and Locations","items":["गोटमार मेला - पांढुर्णा (नया जिला)","नागाजी का मेला - पोरसा (मुरैना)","हीरा भूमिया का मेला - ग्वालियर / गुना","जलविहार का मेला - छतरपुर","बरमान का मेला - नरसिंहपुर (गाडरवारा)"],"items_en":["Gotmar Mela - Pandhurna (New District)","Nagaji Mela - Porsa (Morena)","Hira Bhumia Mela - Gwalior / Guna","Jalvihar Mela - Chhatarpur","Barman Mela - Narsinghpur (Gadarwara)"],"memory_hook":"गोटमार पांढुर्णा में, नागाजी मुरैना में, बरमान नरसिंहपुर में।","memory_hook_en":"Gotmar in Pandhurna, Nagaji in Morena, Barman in Narsinghpur."}],"concept_capsule":"मध्य प्रदेश के मेलों और उत्सवों को उनके विशिष्ट शहरों/कस्बों या नदियों (जैसे जाम नदी) के साथ मैप करना एक मानक MPPSC पैटर्न है। नए जिलों के निर्माण (जैसे पांढुर्णा, मैहर) के बाद इन स्थानों का अद्यतन ज्ञान आवश्यक है।","concept_capsule_en":"Mapping MP''s fairs and festivals with their specific cities/towns or rivers (like Jam river) is a standard MPPSC pattern. Updated knowledge of these locations is necessary after the creation of new districts (like Pandhurna, Maihar).","practice_prompts":["मध्य प्रदेश में ''सिंहस्थ कुंभ मेला'' किस नदी के तट पर और कितने वर्षों के अंतराल पर लगता है?","जोगेश्वरी देवी का मेला (Jogeshwari Devi Mela) किस जिले में आयोजित होता है?"],"practice_prompts_en":["On the banks of which river and at what interval of years is the ''Simhastha Kumbh Mela'' held in Madhya Pradesh?","In which district is the Jogeshwari Devi Mela organized?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('3fb375f0-6f70-40d7-a4e2-2081ebe2e705', 'Polity', 'constitutional-acts-articles-parliament', 'संवैधानिक अधिनियम, अनुच्छेद और संसद', 'Constitutional Acts, Articles & Parliament', 'भारत सरकार अधिनियम 1935 (अखिल भारतीय संघ), उद्देश्य प्रस्ताव, संसद के अंग, अनुच्छेद 17 (अस्पृश्यता) और संयुक्त बैठक (अनुच्छेद 108)।', 1, 1773829475, 1773829475, '{"must_know_lists":[{"list_title":"संविधान सभा की प्रमुख बैठकें (दिसंबर 1946)","list_title_en":"Major Meetings of the Constituent Assembly (Dec 1946)","items":["9 दिसंबर - पहली बैठक (सच्चिदानंद सिन्हा अस्थायी अध्यक्ष बने)","11 दिसंबर - दूसरी बैठक (डॉ. राजेंद्र प्रसाद स्थायी अध्यक्ष चुने गए)","13 दिसंबर - तीसरी बैठक (जवाहरलाल नेहरू ने उद्देश्य प्रस्ताव पेश किया)","22 जनवरी 1947 - उद्देश्य प्रस्ताव को सर्वसम्मति से स्वीकार किया गया"],"items_en":["9 Dec - First meeting (Sachchidananda Sinha became temporary president)","11 Dec - Second meeting (Dr. Rajendra Prasad elected permanent president)","13 Dec - Third meeting (Jawaharlal Nehru presented Objectives Resolution)","22 Jan 1947 - Objectives Resolution unanimously adopted"],"memory_hook":"9, 11, 13 -> सिन्हा, प्रसाद, नेहरू।","memory_hook_en":"9, 11, 13 -> Sinha, Prasad, Nehru."}],"concept_capsule":"भारतीय राजव्यवस्था में संविधान सभा का घटनाक्रम (Chronology), संसद की संरचना (राष्ट्रपति की भूमिका), और मौलिक अधिकारों के सीधे अनुच्छेद (जैसे Art 17) सबसे अधिक दोहराए जाने वाले (High-yield) प्रश्न हैं। संयुक्त बैठक (Art 108) की बारीकियां जरूर समझें।","concept_capsule_en":"In Indian Polity, the chronology of the Constituent Assembly, the structure of Parliament (President''s role), and direct articles of Fundamental Rights (like Art 17) are the most highly repeated (High-yield) questions. Definitely understand the nuances of Joint Sitting (Art 108).","practice_prompts":["संविधान के अनुच्छेद 18 और अनुच्छेद 19 में क्या प्रावधान हैं?","धन विधेयक (Money Bill) के मामले में राज्यसभा के पास कितने दिनों तक उसे रोकने की शक्ति होती है?"],"practice_prompts_en":["What are the provisions in Article 18 and Article 19 of the Constitution?","In the case of a Money Bill, for how many days does the Rajya Sabha have the power to withhold it?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('eb958aa6-c2da-432b-9226-6e62a09d1028', 'Polity', 'information-technology-act-2000', 'सूचना प्रौद्योगिकी अधिनियम 2000', 'Information Technology Act 2000', 'IT एक्ट 2000 के तहत डिजिटल हस्ताक्षर और इलेक्ट्रॉनिक रिकॉर्ड की कानूनी मान्यता।', 1, 1773829476, 1773829476, '{"must_know_lists":[{"list_title":"IT अधिनियम 2000 की प्रमुख धाराएं (Sections)","list_title_en":"Key Sections of IT Act 2000","items":["धारा 43 - कंप्यूटर सिस्टम को नुकसान पहुंचाना (जुर्माना)","धारा 66 - कंप्यूटर से संबंधित अपराध (हैकिंग)","धारा 66A - आपत्तिजनक संदेश भेजना (सुप्रीम कोर्ट द्वारा निरस्त - श्रेया सिंघल केस)","धारा 67 - अश्लील सामग्री का प्रकाशन"],"items_en":["Section 43 - Damage to computer system (Penalty)","Section 66 - Computer related offenses (Hacking)","Section 66A - Sending offensive messages (Struck down by SC - Shreya Singhal case)","Section 67 - Publishing obscene material"],"memory_hook":"66 हैकिंग, 67 अश्लीलता।","memory_hook_en":"66 Hacking, 67 Obscenity."}],"concept_capsule":"सूचना प्रौद्योगिकी अधिनियम 2000 (IT Act 2000) भारत में साइबर कानूनों का आधार है। इसकी प्रमुख धाराओं (विशेषकर अपराध और दंड) और इसके द्वारा पेश की गई अवधारणाओं (इलेक्ट्रॉनिक रिकॉर्ड की कानूनी मान्यता) से सीधे प्रश्न बनते हैं।","concept_capsule_en":"The Information Technology Act 2000 is the bedrock of cyber laws in India. Direct questions are framed from its key sections (especially crimes and penalties) and the concepts it introduced (legal recognition of electronic records).","practice_prompts":["सुप्रीम कोर्ट ने किस प्रसिद्ध मामले में IT अधिनियम की धारा 66A को असंवैधानिक घोषित किया था?","साइबर अपीलीय न्यायाधिकरण (Cyber Appellate Tribunal) का गठन IT एक्ट की किस धारा के तहत होता है?"],"practice_prompts_en":["In which famous case did the Supreme Court declare Section 66A of the IT Act unconstitutional?","Under which section of the IT Act is the Cyber Appellate Tribunal constituted?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('b516f65e-809b-4832-b46d-7be677a1e35d', 'Science', 'applied-science-space-tech', 'अनुप्रयुक्त विज्ञान और अंतरिक्ष तकनीक', 'Applied Science & Space Tech', 'दूध के पाश्चुरीकरण की जांच (फास्फेटेज परीक्षण) और ISRO का पूर्ण रूप।', 1, 1773829476, 1773829476, '{"must_know_lists":[{"list_title":"विज्ञान में सामान्य परीक्षण (Common Scientific Tests)","list_title_en":"Common Scientific Tests in Science","items":["फास्फेटेज टेस्ट (Phosphatase) - दूध का पाश्चुरीकरण","एलिसा टेस्ट (ELISA) - एचआईवी / एड्स (HIV/AIDS)","विडाल टेस्ट (Widal) - टाइफाइड (Typhoid)","ईसीजी (ECG) - हृदय की गतिविधि (Heart)","ईईजी (EEG) - मस्तिष्क की गतिविधि (Brain)"],"items_en":["Phosphatase Test - Milk Pasteurization","ELISA Test - HIV/AIDS","Widal Test - Typhoid","ECG - Heart activity","EEG - Brain activity"],"memory_hook":"विडाल=टाइफाइड, एलिसा=एड्स, फास्फेटेज=दूध।","memory_hook_en":"Widal=Typhoid, ELISA=AIDS, Phosphatase=Milk."}],"concept_capsule":"सामान्य विज्ञान (Everyday Science) में रोजमर्रा के रसायनों, बीमारियों के परीक्षण (Tests) और प्रमुख वैज्ञानिक/अंतरिक्ष संस्थानों के फुल फॉर्म पर सीधे प्रश्न आते हैं। दूध से जुड़े वैज्ञानिक तथ्य (लैक्टोबैसिलस, केसिन प्रोटीन) हमेशा उच्च-उपज वाले होते हैं।","concept_capsule_en":"In Everyday Science, direct questions come from everyday chemicals, disease tests, and full forms of major scientific/space institutes. Scientific facts related to milk (Lactobacillus, Casein protein) are always high-yield.","practice_prompts":["दूध का सफेद रंग और हल्का पीलापन किन वर्णकों (Pigments/Proteins) के कारण होता है?","DRDO और BARC के फुल फॉर्म क्या हैं?"],"practice_prompts_en":["The white color and slight yellowness of milk are due to which pigments/proteins?","What are the full forms of DRDO and BARC?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e86713fe-4915-4706-b035-e248493337f5', 'ICT', 'computer-networking', 'कंप्यूटर नेटवर्किंग', 'Computer Networking', 'नेटवर्किंग डिवाइस (रूटर) का कार्य और OSI मॉडल में इसकी भूमिका।', 1, 1773829477, 1773829477, '{"must_know_lists":[{"list_title":"प्रमुख नेटवर्किंग उपकरण और उनके कार्य","list_title_en":"Major Networking Devices and their Functions","items":["हब (Hub) - डेटा को नेटवर्क के सभी पोर्ट्स पर ब्रॉडकास्ट करता है (Dumb device)।","स्विच (Switch) - डेटा को केवल गंतव्य (Destination) मैक एड्रेस पर भेजता है (Smart hub)।","रूटर (Router) - IP एड्रेस के आधार पर दो अलग नेटवर्कों के बीच डेटा पैकेट भेजता है।","मॉडेम (Modem) - डिजिटल सिग्नल को एनालॉग (Modulation) और एनालॉग को डिजिटल (Demodulation) में बदलता है।","गेटवे (Gateway) - दो बिल्कुल अलग प्रोटोकॉल वाले नेटवर्कों को जोड़ता है (अनुवादक)।"],"items_en":["Hub - Broadcasts data to all ports on the network (Dumb device).","Switch - Sends data only to the destination MAC address (Smart hub).","Router - Forwards data packets between two different networks based on IP address.","Modem - Converts digital signals to analog (Modulation) and vice versa (Demodulation).","Gateway - Connects two networks with completely different protocols (Translator)."],"memory_hook":"स्विच=MAC एड्रेस (LAN), रूटर=IP एड्रेस (WAN), मॉडेम=सिग्नल बदलना।","memory_hook_en":"Switch=MAC address (LAN), Router=IP address (WAN), Modem=Change signal."}],"concept_capsule":"कंप्यूटर नेटवर्किंग (Computer Networking) में हार्डवेयर उपकरणों (Hub, Switch, Router, Gateway) के बीच तकनीकी अंतर समझना सबसे महत्वपूर्ण है। OSI मॉडल की परतों (जैसे Network Layer पर Router) को याद करने से इन प्रश्नों को हल करना आसान हो जाता है।","concept_capsule_en":"Understanding the technical differences between hardware devices (Hub, Switch, Router, Gateway) in Computer Networking is paramount. Memorizing the layers of the OSI model (like Router on Network Layer) makes solving these questions easier.","practice_prompts":["OSI मॉडल (Open Systems Interconnection) में कुल कितनी परतें (Layers) होती हैं? उनके नाम क्रम से लिखें।","LAN, MAN और WAN का फुल फॉर्म क्या है?"],"practice_prompts_en":["How many total layers are there in the OSI model (Open Systems Interconnection)? Write their names in order.","What are the full forms of LAN, MAN, and WAN?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('c9829d1f-c229-4a3b-9acf-677ef5c68f31', 'MP GK', 'mp-politics-administration', 'मध्य प्रदेश राजनीति और प्रशासन', 'MP Politics & Administration', 'मध्य प्रदेश के राज्यपाल, मुख्यमंत्री, पंचायती राज अधिनियम और निर्वाचन आयोग से जुड़े ऐतिहासिक तथ्य एवं अपवाद।', 1, 1773829498, 1773829498, '{"must_know_lists":[{"list_title":"मध्य प्रदेश राजव्यवस्था के अनूठे तथ्य (Unique Facts)","list_title_en":"Unique Facts of MP Polity","items":["राज्यपाल जो संविधान सभा के सदस्य नहीं थे - निरंजन नाथ वान्चू (N.N. Wanchoo)","MP के CJ जो सुप्रीम कोर्ट के जज नहीं बने - एस. के. झा (S.K. Jha)","एकमात्र प्रोटेम, अध्यक्ष और उपाध्यक्ष - रामकिशोर शुक्ला","MP के CJ जो भारत के CJI और कार्यवाहक राष्ट्रपति बने - एम. हिदायतुल्ला"],"items_en":["Governor who was NOT a member of Constituent Assembly - Niranjan Nath Wanchoo","MP CJ who did NOT become SC Judge - S.K. Jha","Only Pro-tem, Speaker, and Deputy Speaker - Ramkishore Shukla","MP CJ who became CJI and Acting President - M. Hidayatullah"],"memory_hook":"वान्चू वंचित रहे (संविधान सभा से)। झा जी सुप्रीम कोर्ट नहीं गए।","memory_hook_en":"Wanchoo was deprived (of Const. Assembly). Jha ji didn''t go to SC."}],"concept_capsule":"मध्य प्रदेश की राजव्यवस्था (MP Polity) में सबसे ज्यादा (Bouncer) प्रश्न राजनेताओं (CM, Governor, Speaker, Judges) के पिछले रिकॉर्ड या अपवादों (Exceptions) से पूछे जाते हैं। इन सूचियों का तुलनात्मक अध्ययन अनिवार्य है।","concept_capsule_en":"In MP Polity, the most difficult (bouncer) questions are asked from the past records or exceptions of politicians (CM, Governor, Speaker, Judges). A comparative study of these lists is mandatory.","practice_prompts":["मध्य प्रदेश के ऐसे दो मुख्यमंत्रियों के नाम बताइए जो बाद में किसी राज्य के राज्यपाल बने।","मध्य प्रदेश लोक सेवा आयोग (MPPSC) के अध्यक्ष को पद से हटाने की प्रक्रिया क्या है?"],"practice_prompts_en":["Name two Chief Ministers of Madhya Pradesh who later became Governors of any state.","What is the procedure to remove the Chairman of the Madhya Pradesh Public Service Commission (MPPSC)?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('4730488a-99aa-4a5e-9486-3f4716582b21', 'MP GK', 'mp-history-art-culture', 'मध्य प्रदेश इतिहास, कला और संस्कृति', 'MP History, Art & Culture', 'मध्य प्रदेश के ऐतिहासिक राजवंश (चंदेल, परमार), 1857 के स्थानीय विद्रोह (सीहोर), पद्मश्री विजेता जनजातीय कलाकार (भूरी बाई), और साहित्यकार।', 1, 1773829500, 1773829500, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के प्रमुख लोकनाट्य (Folk Dramas)","list_title_en":"Major Folk Dramas of MP","items":["निमाड़ - तुर्रा कलंगी (शिव-पार्वती अखाड़ा), गम्मत","मालवा - माच (राज्य नाट्य - ओमप्रकाश शर्मा), भवाई","बुंदेलखंड - स्वांग (Swang)","बघेलखंड - छाहुर, मनसुखा, हिंगोला"],"items_en":["Nimar - Turra Kalangi (Shiva-Parvati Akhada), Gammat","Malwa - Maach (State Drama - Om Prakash Sharma), Bhavai","Bundelkhand - Swang","Baghelkhand - Chhahur, Mansukha, Hingola"],"memory_hook":"निमाड़ की कलंगी, मालवा का माच।","memory_hook_en":"Nimar''s Kalangi, Malwa''s Maach."}],"concept_capsule":"मध्य प्रदेश का इतिहास और संस्कृति पूरी तरह से ''सूक्ष्म तथ्यों'' (Micro-facts) पर निर्भर है। प्राचीन साहित्यकारों की रचनाएं, आदिवासी कलाकारों की विधा (Genre), और 1857 के स्थानीय नेताओं के कार्यक्षेत्र को रटना ही सफलता की कुंजी है। नोबेल विजेता कैलाश सत्यार्थी (विदिशा) जैसी आधुनिक हस्तियां भी महत्वपूर्ण हैं।","concept_capsule_en":"MP''s History and Culture relies entirely on ''Micro-facts''. Rote learning the works of ancient writers, genres of tribal artists, and areas of operation of 1857 local leaders is the key to success. Modern figures like Nobel laureate Kailash Satyarthi (Vidisha) are also important.","practice_prompts":["मध्य प्रदेश के किन 3 आदिवासी नायकों को ''रॉबिन हुड'' की उपाधि से जोड़ा जाता है?","कवि पद्माकर और गजानन माधव मुक्तिबोध का संबंध मध्य प्रदेश के किन जिलों से है?"],"practice_prompts_en":["Which 3 tribal heroes of MP are associated with the title ''Robin Hood''?","Poet Padmakar and Gajanan Madhav Muktibodh are associated with which districts of MP?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('1b08126e-d577-467f-af83-4e906a5ed6f9', 'Polity', 'constitution-commissions-national-acts', 'संविधान, आयोग और राष्ट्रीय अधिनियम', 'Constitution, Commissions & National Acts', 'भारत सरकार अधिनियम (1919, 1935), संविधान सभा की बैठकें, चुनाव/SC/ST/CAG आयोगों के प्रावधान और बाल श्रम/अस्पृश्यता से जुड़े मौलिक अधिकार।', 1, 1773829502, 1773829502, '{"must_know_lists":[{"list_title":"संविधान के महत्वपूर्ण अनुच्छेद (आयोग और निकाय)","list_title_en":"Important Articles of Constitution (Commissions & Bodies)","items":["अनुच्छेद 148 - नियंत्रक एवं महालेखा परीक्षक (CAG)","अनुच्छेद 280 - वित्त आयोग","अनुच्छेद 315 - संघ और राज्य लोक सेवा आयोग","अनुच्छेद 324 - निर्वाचन आयोग","अनुच्छेद 338 - राष्ट्रीय अनुसूचित जाति आयोग (NCSC)","अनुच्छेद 338A - राष्ट्रीय अनुसूचित जनजाति आयोग (NCST)"],"items_en":["Article 148 - Comptroller and Auditor General (CAG)","Article 280 - Finance Commission","Article 315 - UPSC and SPSC","Article 324 - Election Commission","Article 338 - National Commission for SCs","Article 338A - National Commission for STs"],"memory_hook":"CAG(148), Finance(280), PSC(315), Election(324), SC(338).","memory_hook_en":"CAG(148), Finance(280), PSC(315), Election(324), SC(338)."}],"concept_capsule":"भारतीय राजव्यवस्था में ''संवैधानिक और वैधानिक आयोगों'' की कार्यप्रणाली (नियुक्ति, त्यागपत्र, रिपोर्ट किसे देते हैं) MPPSC का सबसे सघन परीक्षण क्षेत्र है। इसके अलावा, संसद की प्रक्रियाएं (संयुक्त बैठक, विधेयक) और सर्वोच्च न्यायालय के क्षेत्राधिकार (Original, Appellate) को गहराई से समझें।","concept_capsule_en":"In Indian Polity, the functioning of ''Constitutional and Statutory Commissions'' (appointment, resignation, who they report to) is MPPSC''s most intensely tested area. Furthermore, deeply understand parliamentary procedures (Joint sitting, Bills) and the jurisdiction of the Supreme Court (Original, Appellate).","practice_prompts":["संविधान के अनुच्छेद 368 के तहत संशोधन के कितने तरीके दिए गए हैं?","भारत के 6 प्रधानमंत्री जो पहले मुख्यमंत्री रह चुके हैं, उनके नाम बताएं।"],"practice_prompts_en":["How many methods of amendment are provided under Article 368 of the Constitution?","Name the 6 Prime Ministers of India who had previously been Chief Ministers."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('ec5b1141-d675-443c-ada7-17a57b7cfe43', 'Geography', 'indian-world-geography-environment-census', 'भारतीय और विश्व भूगोल, पर्यावरण और जनगणना', 'Indian & World Geography, Environment & Census', 'भारत के प्रमुख कृषि क्षेत्र (कपास-काली मिट्टी), खनिज (पन्ना-हीरा), नदियां (चंबल, बेतवा), जलवायु (महाद्वीपीय), और 2011 जनगणना के जनसांख्यिकीय आंकड़े (लिंगानुपात)।', 1, 1773829507, 1773829507, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के कृषि-जलवायु क्षेत्र (Agro-Climatic Zones)","list_title_en":"Agro-Climatic Zones of Madhya Pradesh","items":["मध्य प्रदेश को 11 कृषि-जलवायु क्षेत्रों में विभाजित किया गया है।","मालवा का पठार - काली मिट्टी, सोयाबीन/कपास","नर्मदा घाटी - गहरी काली मिट्टी, गेहूँ","छत्तीसगढ़ का मैदान (बालाघाट) - लाल-पीली मिट्टी, धान (चावल)","बुंदेलखंड/मध्य भारत - मिश्रित मिट्टी, ज्वार/सरसों"],"items_en":["MP is divided into 11 Agro-Climatic Zones.","Malwa Plateau - Black soil, Soybean/Cotton","Narmada Valley - Deep black soil, Wheat","Chhattisgarh plains (Balaghat) - Red-yellow soil, Paddy (Rice)","Bundelkhand/Central India - Mixed soil, Jowar/Mustard"],"memory_hook":"मिट्टी के रंग से फसल तय होती है: काली (कपास), पीली (धान)।","memory_hook_en":"Crop is decided by soil color: Black (Cotton), Yellow (Paddy)."}],"concept_capsule":"मध्य प्रदेश के भूगोल में नदियां (विशेषकर नर्मदा और चंबल घाटी) और खनिज (पन्ना, बालाघाट) सबसे स्थिर और ''निश्चित'' प्रश्न क्षेत्र हैं। 2011 की जनगणना (MP और भारत दोनों) के शीर्ष और निचले जिले/राज्य रटे हुए होने चाहिए।","concept_capsule_en":"In MP Geography, rivers (especially Narmada and Chambal valley) and minerals (Panna, Balaghat) are the most stable and ''definite'' question areas. The top and bottom districts/states of the 2011 Census (both MP and India) must be rote-learned.","practice_prompts":["मध्य प्रदेश का सबसे बड़ा और सबसे छोटा राष्ट्रीय उद्यान (National Park) कौन-सा है?","कर्क रेखा (Tropic of Cancer) मध्य प्रदेश के किन 14 जिलों से होकर गुजरती है?"],"practice_prompts_en":["Which is the largest and smallest National Park in Madhya Pradesh?","Through which 14 districts of Madhya Pradesh does the Tropic of Cancer pass?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('1087cbe2-4923-435a-85e0-70cb2b60a5a2', 'Economy', 'indian-economy-institutions-schemes', 'भारतीय अर्थव्यवस्था, संस्थान और योजनाएं', 'Indian Economy, Institutions & Schemes', 'भारत के नवरत्न/महारत्न उद्यम, वित्तीय क्षेत्र की मूल्यांकन समिति, NBFC लोकपाल, और कृषि/सौर ऊर्जा परियोजनाएं।', 1, 1773829510, 1773829510, '{"must_know_lists":[{"list_title":"भारत में बैंकिंग / वित्तीय लोकपाल (Ombudsman)","list_title_en":"Banking / Financial Ombudsman in India","items":["बैंकिंग लोकपाल योजना - 1995 (2006 में संशोधित)","NBFC लोकपाल योजना - 2018","डिजिटल लेनदेन के लिए लोकपाल - 2019","एकीकृत लोकपाल योजना (Integrated Ombudsman) - 2021 (सभी को मिला दिया गया)"],"items_en":["Banking Ombudsman Scheme - 1995 (Amended in 2006)","NBFC Ombudsman Scheme - 2018","Ombudsman for Digital Transactions - 2019","Integrated Ombudsman Scheme - 2021 (All merged)"],"memory_hook":"अब RBI का एक ही ''बॉस'' (लोकपाल) है - ''One Nation, One Ombudsman''.","memory_hook_en":"Now RBI has only one ''Boss'' (Ombudsman) - ''One Nation, One Ombudsman''."}],"concept_capsule":"अर्थव्यवस्था में RBI की संस्थागत पहल (लोकपाल, समितियां) और सार्वजनिक क्षेत्र की कंपनियों (महारत्न/नवरत्न) का दर्जा सबसे महत्वपूर्ण (Static) प्रश्न हैं। MP की अर्थव्यवस्था में ऊर्जा (विशेषकर सौर-रीवा, ओंकारेश्वर) और कृषि विकास दर के आंकड़े (Economic Survey) प्रमुख हैं।","concept_capsule_en":"In the Economy, RBI''s institutional initiatives (Ombudsman, Committees) and the status of Public Sector Companies (Maharatna/Navratna) are the most important (static) questions. In MP''s economy, figures of energy (especially solar-Rewa, Omkareshwar) and agricultural growth rate (Economic Survey) are prominent.","practice_prompts":["मुद्रास्फीति (Inflation) को नियंत्रित करने के लिए RBI ''रेपो रेट'' (Repo Rate) को बढ़ाता है या घटाता है?","मध्य प्रदेश में ''ग्लोबल इन्वेस्टर्स समिट'' (GIS) 2023 किस शहर में आयोजित किया गया था?"],"practice_prompts_en":["Does RBI increase or decrease the ''Repo Rate'' to control inflation?","In which city was the ''Global Investors Summit'' (GIS) 2023 held in Madhya Pradesh?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('18d03bac-878b-4d89-8e52-63eb0435aa3b', 'ICT', 'current-affairs-technologies-cyber-security', 'करंट अफेयर्स, प्रौद्योगिकियां और साइबर सुरक्षा', 'Current Affairs, Technologies & Cyber Security', 'वैश्विक घटनाएं (म्यांमार तख्तापलट), नीली अर्थव्यवस्था, कंप्यूटर नेटवर्क (IPv6, टोपोलॉजी), साइबर खतरे (स्पूफिंग) और AI (रोबोटिक्स)।', 1, 1773829512, 1773829512, '{"must_know_lists":[{"list_title":"AI और मशीन लर्निंग की प्रमुख शब्दावली (Terminology)","list_title_en":"Key Terminology of AI and Machine Learning","items":["डीप लर्निंग (Deep Learning) - न्यूरल नेटवर्क पर आधारित मशीन लर्निंग का हिस्सा।","सहयोगात्मक फिल्टरिंग (Collaborative Filtering) - यूजर के व्यवहार से उत्पाद सुझाना (Netflix, Amazon)।","नेचुरल लैंग्वेज प्रोसेसिंग (NLP) - मशीन को मानव भाषा (टेक्स्ट/आवाज़) समझाना (Alexa, Siri)।","ट्यूरिंग टेस्ट (Turing Test) - मशीन की बुद्धिमत्ता (इंसान जैसी है या नहीं) जांचने का टेस्ट।"],"items_en":["Deep Learning - Subset of ML based on neural networks.","Collaborative Filtering - Recommending products based on user behavior (Netflix, Amazon).","Natural Language Processing (NLP) - Making machines understand human language (Alexa, Siri).","Turing Test - Test to check machine''s intelligence (whether it''s human-like)."],"memory_hook":"NLP=भाषा, ट्यूरिंग=इंसानियत का टेस्ट, फिल्टरिंग=सुझाव।","memory_hook_en":"NLP=Language, Turing=Humanity test, Filtering=Recommendations."}],"concept_capsule":"कंप्यूटर विज्ञान (ICT) में ''नेटवर्क प्रोटोकॉल'' (IPv4 vs IPv6), ''मेमोरी प्रकार'' (RAM vs ROM) और ''साइबर सुरक्षा खतरे'' (फिशिंग, स्पूफिंग, ब्लोफिश एन्क्रिप्शन) सर्वाधिक स्थिर और स्कोरिंग (Static & Scoring) विषय हैं। करेंट अफेयर्स में अंतर्राष्ट्रीय शिखर सम्मेलन (G20, BRICS) और कूटनीतिक संबंध (Task forces) महत्वपूर्ण हैं।","concept_capsule_en":"In Computer Science (ICT), ''Network Protocols'' (IPv4 vs IPv6), ''Memory Types'' (RAM vs ROM), and ''Cyber Security Threats'' (Phishing, Spoofing, Blowfish encryption) are the most stable and scoring topics. In Current Affairs, international summits (G20, BRICS) and diplomatic ties (Task forces) are important.","practice_prompts":["कम्पाइलर (Compiler) और इंटरप्रेटर (Interpreter) के बीच मुख्य कार्यप्रणाली अंतर क्या है?","मेटावर्स (Metaverse) और ऑगमेंटेड रियलिटी (Augmented Reality) क्या हैं?"],"practice_prompts_en":["What is the main functional difference between a Compiler and an Interpreter?","What are Metaverse and Augmented Reality (AR)?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('3b34af96-13e9-4955-bdc4-2c2604bbe1d9', 'Science', 'general-science-biology-govt-schemes', 'सामान्य विज्ञान, जीव विज्ञान और सरकारी योजनाएं', 'General Science, Biology & Govt Schemes', 'विषाणु-विज्ञान संस्थान (NIV), मानव कंकाल/तंत्रिका तंत्र, जेनेटिक कोड, सूक्ष्म तरंगें (Microwaves), और सरकारी कल्याण योजनाएं (जननी सुरक्षा, आकांक्षा)।', 1, 1773829514, 1773829514, '{"must_know_lists":[{"list_title":"विद्युत चुम्बकीय स्पेक्ट्रम (आवृत्ति के बढ़ते क्रम में)","list_title_en":"Electromagnetic Spectrum (Increasing order of Frequency)","items":["1. रेडियो तरंगें (Radio Waves) - सबसे कम आवृत्ति, सबसे लंबी तरंगदैर्ध्य","2. सूक्ष्म तरंगें (Microwaves) - रडार, ओवन","3. अवरक्त किरणें (Infrared) - टीवी रिमोट, नाइट विजन","4. दृश्य प्रकाश (Visible Light) - VIBGYOR","5. पराबैंगनी किरणें (Ultraviolet) - ओजोन अवशोषित करती है","6. एक्स-रे (X-Rays) - चिकित्सा इमेजिंग","7. गामा किरणें (Gamma Rays) - सबसे अधिक आवृत्ति, सबसे अधिक ऊर्जा"],"items_en":["1. Radio Waves - Lowest freq, Longest wavelength","2. Microwaves - Radar, Oven","3. Infrared - TV remote, Night vision","4. Visible Light - VIBGYOR","5. Ultraviolet - Absorbed by Ozone","6. X-Rays - Medical imaging","7. Gamma Rays - Highest freq, Highest energy"],"memory_hook":"R-M-I-V-U-X-G (Rich Men In Vegas Use eXpensive Gadgets).","memory_hook_en":"R-M-I-V-U-X-G (Rich Men In Vegas Use eXpensive Gadgets)."}],"concept_capsule":"सामान्य विज्ञान में ''मानव शरीर रचना'' (कंकाल, तंत्रिकाएं) और ''विषाणुजनित रोग'' (Viral diseases) कोर विषय हैं। भौतिकी में इलेक्ट्रोमैग्नेटिक स्पेक्ट्रम का क्रम (आवृत्ति/तरंगदैर्ध्य) हमेशा स्कोरिंग रहता है। कल्याणकारी योजनाओं (जननी सुरक्षा, मिड डे मील) के ''मुख्य लक्ष्य समूह'' को याद रखें।","concept_capsule_en":"In General Science, ''Human Anatomy'' (skeleton, nerves) and ''Viral diseases'' are core topics. In Physics, the order of the Electromagnetic Spectrum (frequency/wavelength) is always scoring. Remember the ''main target group'' of welfare schemes (Janani Suraksha, Mid Day Meal).","practice_prompts":["एक्स-रे (X-Rays) की खोज किसने की थी?","प्रधानमंत्री मातृ वंदना योजना (PMMVY) के तहत गर्भवती महिलाओं को कितनी नकद सहायता दी जाती है?"],"practice_prompts_en":["Who discovered X-Rays?","How much cash assistance is provided to pregnant women under the Pradhan Mantri Matru Vandana Yojana (PMMVY)?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('37e89360-f23d-4523-a86d-309e93a0f592', 'MP GK', 'panchayati-raj-state-commissions', 'पंचायती राज और राज्य आयोग', 'Panchayati Raj & State Commissions', 'मध्य प्रदेश में राज्य निर्वाचन आयोग की स्थापना और 73वें संविधान संशोधन (पंचायती राज) के अंतर्गत राज्य विधानसभा द्वारा पारित अधिनियम के महत्वपूर्ण तथ्य।', 1, 1773829518, 1773829518, '{"must_know_lists":[{"list_title":"मध्य प्रदेश पंचायती राज - महत्वपूर्ण तिथियां","list_title_en":"MP Panchayati Raj - Important Dates","items":["30 दिसंबर 1993 - MP विधानसभा द्वारा पंचायती राज अधिनियम पारित।","24 जनवरी 1994 - राज्यपाल की स्वीकृति।","25 जनवरी 1994 - अधिनियम लागू (MP 73वें संशोधन को लागू करने वाला पहला राज्य बना)।","1 फरवरी 1994 - राज्य निर्वाचन आयोग का गठन।"],"items_en":["Dec 30, 1993 - Panchayati Raj Act passed by MP Assembly.","Jan 24, 1994 - Governor''s assent.","Jan 25, 1994 - Act implemented (MP became the first state to implement the 73rd Amendment).","Feb 1, 1994 - Formation of State Election Commission."],"memory_hook":"दिसंबर 93 में पास, जनवरी 94 में लागू, फरवरी 94 में आयोग।","memory_hook_en":"Passed in Dec 93, Implemented in Jan 94, Commission in Feb 94."}],"concept_capsule":"पंचायती राज (विशेषकर मध्य प्रदेश के संदर्भ में) MPPSC का अत्यंत प्रिय विषय है। राज्य निर्वाचन आयोग (अनुच्छेद 243K) और राज्य वित्त आयोग (अनुच्छेद 243I) के गठन वर्ष और पहले अध्यक्षों के नाम कंठस्थ होने चाहिए।","concept_capsule_en":"Panchayati Raj (especially in the context of MP) is a very favorite topic of MPPSC. The formation years and names of the first chairpersons of the State Election Commission (Article 243K) and State Finance Commission (Article 243I) must be rote-learned.","practice_prompts":["मध्य प्रदेश के पहले राज्य निर्वाचन आयुक्त (State Election Commissioner) कौन थे?","भारत निर्वाचन आयोग (ECI) संविधान के किस भाग और अनुच्छेद में वर्णित है?"],"practice_prompts_en":["Who was the first State Election Commissioner of Madhya Pradesh?","In which Part and Article of the Constitution is the Election Commission of India (ECI) described?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('e42d2638-d9bf-45fb-861f-84d31cc4011d', 'Polity', 'constitutional-articles-amendments', 'संवैधानिक अनुच्छेद और संशोधन', 'Constitutional Articles & Amendments', 'भारत निर्वाचन आयोग के अनुच्छेद और संविधान संशोधन (अनुच्छेद 368) से जुड़ी बारीक कानूनी जानकारी।', 1, 1773829518, 1773829518, '{"must_know_lists":[{"list_title":"संविधान के भाग XV (निर्वाचन) के प्रमुख अनुच्छेद","list_title_en":"Key Articles of Part XV (Elections) of the Constitution","items":["324 - निर्वाचन आयोग का गठन (अधीक्षण, निदेशन और नियंत्रण)","325 - धर्म, मूलवंश, जाति या लिंग के आधार पर भेदभाव नहीं","326 - लोकसभा और विधानसभाओं के चुनाव ''वयस्क मताधिकार'' (Adult Suffrage) पर होंगे"],"items_en":["324 - Formation of Election Commission (Superintendence, direction, and control)","325 - No discrimination on grounds of religion, race, caste or sex","326 - Elections to Lok Sabha and Legislative Assemblies to be on the basis of ''Adult Suffrage''"],"memory_hook":"324 में आयोग बना, 326 में सबको वोट मिला।","memory_hook_en":"Commission formed in 324, Everyone got to vote in 326."}],"concept_capsule":"भारतीय राजव्यवस्था में ''आयोगों'' से जुड़े अनुच्छेद सबसे बुनियादी और स्कोरिंग हैं। हालांकि, संविधान संशोधन (विशेषकर 42वां, 44वां, 73वां, 74वां और नवीनतम संशोधन जैसे 101वां GST) से जुड़े तकनीकी प्रश्न अक्सर छात्रों को फंसाने के लिए दिए जाते हैं।","concept_capsule_en":"Articles related to ''Commissions'' in Indian Polity are the most basic and scoring. However, technical questions related to Constitutional Amendments (especially 42nd, 44nd, 73rd, 74th, and recent ones like 101st GST) are often given to trap students.","practice_prompts":["संविधान के किस अनुच्छेद के तहत ''वयस्क मताधिकार'' (Adult Suffrage) की गारंटी दी गई है?","61वें संविधान संशोधन (1989) का क्या महत्व है?"],"practice_prompts_en":["Under which Article of the Constitution is ''Adult Suffrage'' guaranteed?","What is the significance of the 61st Constitutional Amendment (1989)?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('f7ea7138-f9bc-40ab-90da-fee69cc31c29', 'MP GK', 'mp-culture-tribes-education', 'मध्य प्रदेश संस्कृति, जनजातियां और शिक्षा', 'MP Culture, Tribes & Education', 'मध्य प्रदेश की जनजातीय संस्कृति (भगोरिया हाट), कृषि शिक्षा संस्थान, और प्रमुख व्यक्तियों के उपनाम/सम्मान।', 1, 1773829519, 1773829519, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के प्रमुख जनजातीय उत्सव और उनके अंचल","list_title_en":"Major Tribal Festivals of MP and their Regions","items":["भगोरिया - भील/भिलाला (झाबुआ, अलीराजपुर, धार)","मड़ई (Madai) - गोंड (मंडला, डिंडौरी, बस्तर क्षेत्र)","मेघनाद पर्व - गोंड (फाल्गुन मास में)","लारूकाज - गोंड (सुअर की बलि, नारायण देव के लिए)"],"items_en":["Bhagoria - Bhil/Bhilala (Jhabua, Alirajpur, Dhar)","Madai - Gond (Mandla, Dindori, Bastar region)","Meghnad Parv - Gond (in Phalguna month)","Larukaaj - Gond (Pig sacrifice, for Narayan Dev)"],"memory_hook":"भील का भगोरिया, गोंड की मड़ई।","memory_hook_en":"Bhil''s Bhagoria, Gond''s Madai."}],"concept_capsule":"मध्य प्रदेश की जनजातीय संस्कृति (विशेषकर भील और गोंड) MPPSC का मुख्य आधार है। त्योहारों (भगोरिया), कला (पिथौरा) और नृत्यों को उनके जिलों के साथ मैप करें। साहित्य में, आधुनिक कवियों (माखनलाल, सुभद्रा कुमारी, मुक्तिबोध) की प्रसिद्ध कृतियाँ रट लें।","concept_capsule_en":"Tribal culture of Madhya Pradesh (especially Bhil and Gond) is the mainstay of MPPSC. Map festivals (Bhagoria), arts (Pithora), and dances to their districts. In literature, rote learn the famous works of modern poets (Makhanlal, Subhadra Kumari, Muktibodh).","practice_prompts":["भगोरिया हाट के 3 मुख्य चरण कौन-से होते हैं?","सुभद्रा कुमारी चौहान का जन्म कहाँ हुआ था और उनकी सबसे प्रसिद्ध कविता कौन सी है?"],"practice_prompts_en":["What are the 3 main phases of the Bhagoria Haat?","Where was Subhadra Kumari Chauhan born and what is her most famous poem?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('c9c8a4c6-3302-4704-8b97-8fb4c11256cc', 'Science', 'general-science-human-biology-botany', 'सामान्य विज्ञान - मानव जीव विज्ञान और वनस्पति विज्ञान', 'General Science - Human Biology & Botany', 'दाँतों का अध्ययन (ओडोन्टोलॉजी), रक्त रोग (एनीमिया, पॉलीसिथेमिया), ''ब्लड बैंक'' (तिल्ली/स्प्लीन), खनिज (एस्बेस्टस) और बायोडीजल वनस्पति (जेट्रोफा)।', 1, 1773829519, 1773842050, '{"must_know_lists":[{"list_title":"विज्ञान की प्रमुख शाखाएं (Branches of Science)","list_title_en":"Major Branches of Science","items":["ओडोन्टोलॉजी (Odontology) - दाँतों का अध्ययन","ऑस्टियोलॉजी (Osteology) - हड्डियों का अध्ययन","हेमेटोलॉजी (Hematology) - रक्त (Blood) का अध्ययन","साइटोलॉजी (Cytology) - कोशिकाओं (Cells) का अध्ययन","हिस्टोलॉजी (Histology) - ऊतकों (Tissues) का अध्ययन"],"items_en":["Odontology - Study of teeth","Osteology - Study of bones","Hematology - Study of blood","Cytology - Study of cells","Histology - Study of tissues"],"memory_hook":"ओडो-दांत, ऑस्टियो-हड्डी, हेमेटो-खून।","memory_hook_en":"Odo-Teeth, Osteo-Bone, Hemato-Blood."}],"concept_capsule":"मानव शरीर रचना (Human Anatomy) विशेष रूप से रक्त (RBC, WBC, Spleen) और पोषण संबंधी बीमारियाँ (एनीमिया) सामान्य विज्ञान के सबसे उच्च-उपज वाले विषय हैं। विज्ञान की शाखाओं (Logy) का ''मैच द कॉलम'' बहुत लोकप्रिय है।","concept_capsule_en":"Human Anatomy, especially blood (RBC, WBC, Spleen) and nutritional diseases (Anemia), are the highest-yield topics in General Science. ''Match the Column'' for branches of science (-logy) is very popular.","practice_prompts":["मानव शरीर में लाल रक्त कणिकाओं (RBC) का जीवनकाल कितना होता है?","विटामिन B12 का रासायनिक नाम क्या है और यह किस रोग को रोकता है?"],"practice_prompts_en":["What is the lifespan of Red Blood Cells (RBCs) in the human body?","What is the chemical name of Vitamin B12 and which disease does it prevent?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('bcbeaad7-e11e-49e8-8098-4fd78df83997', 'MP GK', 'mp-environment-geography-resources', 'मध्य प्रदेश पर्यावरण, भूगोल और संसाधन', 'MP Environment, Geography & Resources', 'राष्ट्रीय उद्यान (कान्हा का शुभंकर), वनावरण (श्योपुर), भौगोलिक विशेषताएं (नर्मदा कंदरा, जलवायु क्षेत्र), और खनिज/सिंचाई (मैंगनीज, नलकूप)।', 1, 1773829520, 1773842051, '{"must_know_lists":[{"list_title":"मध्य प्रदेश की मिट्टी और उनका क्षेत्र","list_title_en":"Soils of MP and their Regions","items":["काली मिट्टी (Black Soil) - मालवा पठार, नर्मदा घाटी (कपास/सोयाबीन)।","लाल-पीली मिट्टी (Red-Yellow Soil) - बघेलखंड (पूर्वी MP), धान।","जलोढ़ मिट्टी (Alluvial Soil) - भिंड, मुरैना, श्योपुर (उत्तरी MP), सरसों/गेहूँ।","मिश्रित मिट्टी (Mixed Soil) - बुंदेलखंड क्षेत्र।"],"items_en":["Black Soil - Malwa Plateau, Narmada Valley (Cotton/Soybean).","Red-Yellow Soil - Baghelkhand (Eastern MP), Paddy.","Alluvial Soil - Bhind, Morena, Sheopur (Northern MP), Mustard/Wheat.","Mixed Soil - Bundelkhand region."],"memory_hook":"पश्चिम में काली (Black), पूर्व में पीली (Yellow), उत्तर में जलोढ़ (Alluvial)।","memory_hook_en":"Black in West, Yellow in East, Alluvial in North."}],"concept_capsule":"मध्य प्रदेश के भूगोल में खनिज खदानें (पन्ना, बालाघाट) और मिट्टियों का क्षेत्रीय वितरण सबसे ''स्कोरिंग'' (High-yield) क्षेत्र है। नदी परियोजनाओं (जैसे सुक्ता, बारना) को उनके जिलों से मिलाना (Match the following) हर बार पूछा जाता है। 2011 जनगणना (डिंडौरी घनत्व) और ODOP जैसी पहलें भी रटी हुई होनी चाहिए।","concept_capsule_en":"In MP Geography, mineral mines (Panna, Balaghat) and the regional distribution of soils are the most ''scoring'' (high-yield) areas. Matching river projects (like Sukta, Barna) to their districts is asked every time. Initiatives like 2011 Census (Dindori density) and ODOP must also be rote-learned.","practice_prompts":["मध्य प्रदेश में ''हीरा'' (Diamond) और ''तांबा'' (Copper) की सबसे बड़ी खदानें कहाँ स्थित हैं?","नर्मदा नदी किन दो पर्वत श्रृंखलाओं के बीच एक भ्रंश घाटी (Rift Valley) में बहती है?"],"practice_prompts_en":["Where are the largest ''Diamond'' and ''Copper'' mines located in Madhya Pradesh?","Between which two mountain ranges does the Narmada river flow in a Rift Valley?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('d277c8b3-99cb-43a5-a353-b880a4d91575', 'MP GK', 'mp-economy-govt-schemes-personalities', 'मध्य प्रदेश अर्थव्यवस्था, सरकारी योजनाएं और व्यक्तित्व', 'MP Economy, Govt Schemes & Personalities', 'मध्य प्रदेश की प्रमुख योजनाएं (लाडली बहना), अर्थव्यवस्था की रैंकिंग (BRAP), कृषि विकास दर, और प्रसिद्ध उद्योगपति (जमशेद जे. ईरानी)।', 1, 1773829521, 1773829521, '{"must_know_lists":[{"list_title":"मध्य प्रदेश की विशेष पिछड़ी जनजातियां (PVTGs) और उनके क्षेत्र","list_title_en":"Particularly Vulnerable Tribal Groups (PVTGs) of MP and their Regions","items":["बैगा (Baiga) - मंडला, डिंडौरी, बालाघाट (मैकाल श्रेणी)","भारिया (Bharia) - पातालकोट (छिंदवाड़ा)","सहरिया (Sahariya) - ग्वालियर, चंबल संभाग (शिवपुरी, श्योपुर, गुना)"],"items_en":["Baiga - Mandla, Dindori, Balaghat (Maikal range)","Bharia - Patalkot (Chhindwara)","Sahariya - Gwalior, Chambal division (Shivpuri, Sheopur, Guna)"],"memory_hook":"दक्षिण-पूर्व में बैगा, दक्षिण में भारिया, उत्तर में सहरिया।","memory_hook_en":"Baiga in South-East, Bharia in South, Sahariya in North."}],"concept_capsule":"मध्य प्रदेश की अर्थव्यवस्था और जनजातियों से प्रश्न हमेशा ''सूक्ष्म तथ्यों'' (Micro-facts) पर होते हैं। नीति आयोग की रिपोर्टों में MP की रैंकिंग (जैसे MPI, BRAP), और PVTGs (बैगा, भारिया, सहरिया) की विशिष्ट सांस्कृतिक शब्दावली (जैसे खुटिया पटेल) को गहराई से पढ़ें।","concept_capsule_en":"Questions from MP''s Economy and Tribes are always based on ''Micro-facts''. Deeply study MP''s rankings in NITI Aayog reports (like MPI, BRAP), and the specific cultural vocabulary (like Khutiya Patel) of PVTGs (Baiga, Bharia, Sahariya).","practice_prompts":["मध्य प्रदेश में ''आहार अनुदान योजना'' (Aahar Anudan Yojana) किन जनजातियों के लिए चलाई जा रही है?","भारत सरकार द्वारा घोषित ''महारत्न'' और ''नवरत्न'' कंपनियों में मुख्य अंतर क्या है?"],"practice_prompts_en":["For which tribes is the ''Aahar Anudan Yojana'' being run in Madhya Pradesh?","What is the main difference between ''Maharatna'' and ''Navratna'' companies declared by the GoI?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('a8ebf619-7168-4216-9667-c24ea8e18160', 'Polity', 'constitutional-articles-bodies-amendments', 'संवैधानिक अनुच्छेद, निकाय और संशोधन', 'Constitutional Articles, Bodies & Amendments', 'भारत के चुनाव आयोग, राज्य विधानमंडल चुनाव के अनुसूचियां और अनुच्छेद 368 (संविधान संशोधन) से संबंधित अति-विशिष्ट कानूनी प्रश्न।', 1, 1773842047, 1773842047, '{"must_know_lists":[{"list_title":"संविधान के भाग XV (निर्वाचन) के प्रमुख अनुच्छेद","list_title_en":"Key Articles of Part XV (Elections) of the Constitution","items":["324 - निर्वाचन आयोग का गठन (अधीक्षण, निदेशन और नियंत्रण)","325 - धर्म, मूलवंश, जाति या लिंग के आधार पर भेदभाव नहीं","326 - लोकसभा और विधानसभाओं के चुनाव ''वयस्क मताधिकार'' (Adult Suffrage) पर होंगे"],"items_en":["324 - Formation of Election Commission (Superintendence, direction, and control)","325 - No discrimination on grounds of religion, race, caste or sex","326 - Elections to Lok Sabha and Legislative Assemblies to be on the basis of ''Adult Suffrage''"],"memory_hook":"324 में आयोग बना, 326 में सबको वोट मिला।","memory_hook_en":"Commission formed in 324, Everyone got to vote in 326."}],"concept_capsule":"भारतीय राजव्यवस्था में ''आयोगों'' से जुड़े अनुच्छेद सबसे बुनियादी और स्कोरिंग हैं। हालांकि, संविधान संशोधन (विशेषकर 42वां, 44वां, 73वां, 74वां और नवीनतम संशोधन जैसे 101वां GST) से जुड़े तकनीकी प्रश्न अक्सर छात्रों को फंसाने के लिए दिए जाते हैं।","concept_capsule_en":"Articles related to ''Commissions'' in Indian Polity are the most basic and scoring. However, technical questions related to Constitutional Amendments (especially 42nd, 44nd, 73rd, 74th, and recent ones like 101st GST) are often given to trap students.","practice_prompts":["संविधान के किस अनुच्छेद के तहत ''वयस्क मताधिकार'' (Adult Suffrage) की गारंटी दी गई है?","61वें संविधान संशोधन (1989) का क्या महत्व है?"],"practice_prompts_en":["Under which Article of the Constitution is ''Adult Suffrage'' guaranteed?","What is the significance of the 61st Constitutional Amendment (1989)?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('0e7ae3b5-e91c-4d8b-9901-1637cb7feff8', 'MP GK', 'mp-demography-culture-education', 'मध्य प्रदेश जनसांख्यिकी, संस्कृति और शिक्षा', 'MP Demography, Culture & Education', 'मध्य प्रदेश की जनजातीय संस्कृति (भगोरिया हाट), कृषि शिक्षा संस्थान, और 2011 जनगणना के जनसांख्यिकीय आंकड़े (न्यूनतम घनत्व/लिंगानुपात)।', 1, 1773842048, 1773842048, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के प्रमुख जनजातीय उत्सव और उनके अंचल","list_title_en":"Major Tribal Festivals of MP and their Regions","items":["भगोरिया - भील/भिलाला (झाबुआ, अलीराजपुर, धार)","मड़ई (Madai) - गोंड (मंडला, डिंडौरी, बस्तर क्षेत्र)","मेघनाद पर्व - गोंड (फाल्गुन मास में)","लारूकाज - गोंड (सुअर की बलि, नारायण देव के लिए)"],"items_en":["Bhagoria - Bhil/Bhilala (Jhabua, Alirajpur, Dhar)","Madai - Gond (Mandla, Dindori, Bastar region)","Meghnad Parv - Gond (in Phalguna month)","Larukaaj - Gond (Pig sacrifice, for Narayan Dev)"],"memory_hook":"भील का भगोरिया, गोंड की मड़ई।","memory_hook_en":"Bhil''s Bhagoria, Gond''s Madai."}],"concept_capsule":"मध्य प्रदेश की जनजातीय संस्कृति (विशेषकर भील और गोंड) और 2011 की जनगणना (न्यूनतम/अधिकतम वाले जिले) MPPSC का मुख्य आधार हैं। त्योहारों (भगोरिया) और शिक्षा संस्थानों (जैसे IGNTU अमरकंटक) को उनके जिलों के साथ मैप करें।","concept_capsule_en":"Tribal culture of Madhya Pradesh (especially Bhil and Gond) and 2011 Census (top/bottom districts) are the mainstay of MPPSC. Map festivals (Bhagoria) and educational institutes (like IGNTU Amarkantak) to their districts.","practice_prompts":["भगोरिया हाट के 3 मुख्य चरण कौन-से होते हैं?","2011 की जनगणना के अनुसार मध्य प्रदेश के किन 2 जिलों की साक्षरता दर सबसे अधिक है?"],"practice_prompts_en":["What are the 3 main phases of the Bhagoria Haat?","According to the 2011 census, which 2 districts of Madhya Pradesh have the highest literacy rate?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('c8990844-2e2e-4034-b4d3-ed2c80dece76', 'MP GK', 'mp-history-literature-institutions', 'मध्य प्रदेश इतिहास, साहित्य और संस्थान', 'MP History, Literature & Institutions', 'साहित्यकारों की रचनाओं का मिलान, प्राचीन तीर्थस्थलों के नाम, भोपाल गैस त्रासदी और राज्य लोक सेवा आयोग की संरचना।', 1, 1773842049, 1773842049, '{"must_know_lists":[{"list_title":"मध्य प्रदेश के ऐतिहासिक स्थलों के प्राचीन नाम","list_title_en":"Ancient Names of Historical Places of MP","items":["विदिशा - भेलसा, बेसनगर","सांची - काकनाद, काकणदबोट","मंदसौर - दशपुर","उज्जैन - अवंतिका","महेश्वर - महिष्मती","ओंकारेश्वर - मांधाता"],"items_en":["Vidisha - Bhilsa, Besnagar","Sanchi - Kakanad, Kakanadabota","Mandsaur - Dashpur","Ujjain - Avantika","Maheshwar - Mahishmati","Omkareshwar - Mandhata"],"memory_hook":"भेलसा-विदिशा, काकनाद-सांची, दशपुर-मंदसौर।","memory_hook_en":"Bhilsa-Vidisha, Kakanad-Sanchi, Dashpur-Mandsaur."}],"concept_capsule":"साहित्यकारों की रचनाएं और मध्य प्रदेश के प्राचीन नगरों के नाम MPPSC की रीढ़ हैं। भोपाल गैस त्रासदी जैसी प्रमुख ऐतिहासिक घटनाओं का वर्ष और गैस का नाम (MIC) हमेशा रटा होना चाहिए। राज्य लोक सेवा आयोग की संरचना (अधिकतम 5 सदस्य) भी महत्वपूर्ण है।","concept_capsule_en":"Works of literary figures and ancient names of MP''s cities are the backbone of MPPSC. The year and gas name (MIC) of major historical events like the Bhopal Gas Tragedy must always be rote learned. The composition of the State Public Service Commission (max 5 members) is also important.","practice_prompts":["भोपाल गैस त्रासदी की जाँच के लिए किस आयोग (Commission) का गठन किया गया था?","कवि पद्माकर और गजानन माधव मुक्तिबोध का संबंध मध्य प्रदेश के किन जिलों से है?"],"practice_prompts_en":["Which commission was formed to investigate the Bhopal Gas Tragedy?","Poet Padmakar and Gajanan Madhav Muktibodh are associated with which districts of MP?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('1467d5e6-325f-4656-aee7-1ac01c0eecef', 'ICT', 'internet-technologies-cyber-security-ai-e-commerce', 'इंटरनेट प्रौद्योगिकियां, साइबर सुरक्षा, एआई और ई-कॉमर्स', 'Internet Technologies, Cyber Security, AI & E-Commerce', 'ई-कॉमर्स के मॉडल (C2C, B2C), साइबर सुरक्षा (फिशिंग, स्पूफिंग, ब्लोफिश), आर्टिफिशियल इंटेलिजेंस के जनक, और वेब/नेटवर्किंग तकनीकें (IPv6, DNS, PUMA)।', 1, 1773842053, 1773842053, '{"must_know_lists":[{"list_title":"AI और मशीन लर्निंग की प्रमुख शब्दावली (Terminology)","list_title_en":"Key Terminology of AI and Machine Learning","items":["डीप लर्निंग (Deep Learning) - न्यूरल नेटवर्क पर आधारित मशीन लर्निंग का हिस्सा।","सहयोगात्मक फिल्टरिंग (Collaborative Filtering) - यूजर के व्यवहार से उत्पाद सुझाना (Netflix, Amazon)।","नेचुरल लैंग्वेज प्रोसेसिंग (NLP) - मशीन को मानव भाषा (टेक्स्ट/आवाज़) समझाना (Alexa, Siri)।","ट्यूरिंग टेस्ट (Turing Test) - मशीन की बुद्धिमत्ता (इंसान जैसी है या नहीं) जांचने का टेस्ट।"],"items_en":["Deep Learning - Subset of ML based on neural networks.","Collaborative Filtering - Recommending products based on user behavior (Netflix, Amazon).","Natural Language Processing (NLP) - Making machines understand human language (Alexa, Siri).","Turing Test - Test to check machine''s intelligence (whether it''s human-like)."],"memory_hook":"NLP=भाषा, ट्यूरिंग=इंसानियत का टेस्ट, फिल्टरिंग=सुझाव।","memory_hook_en":"NLP=Language, Turing=Humanity test, Filtering=Recommendations."}],"concept_capsule":"ई-कॉमर्स के चारों मॉडल (B2B, B2C, C2C, C2B) और साइबर हमलों की सटीक परिभाषा (फिशिंग बनाम स्पूफिंग) ICT के सबसे बुनियादी और स्कोरिंग भाग हैं। AI के जनक, इसके पूर्वाग्रह (Bias) के कारण और लोकप्रिय वर्चुअल असिस्टेंट्स की सूची अच्छे से याद रखें।","concept_capsule_en":"The four models of E-commerce (B2B, B2C, C2C, C2B) and exact definitions of cyber attacks (Phishing vs. Spoofing) are the most basic and scoring parts of ICT. Memorize the father of AI, causes of AI bias, and the list of popular virtual assistants.","practice_prompts":["ई-गवर्नेंस के G2C, G2B और G2G मॉडल्स के बीच क्या अंतर है?","स्पाईवेयर, मैलवेयर और रैनसमवेयर के बीच मुख्य अंतर क्या है?"],"practice_prompts_en":["What is the difference between G2C, G2B, and G2G models of E-Governance?","What is the main difference between Spyware, Malware, and Ransomware?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('22684ec7-7be4-469b-bd3c-9d67c5827dfa', 'Current Affairs', 'international-organizations-sports-awards', 'अंतर्राष्ट्रीय संगठन, खेल और पुरस्कार', 'International Organizations, Sports & Awards', 'FAO का मुख्यालय, ओलंपिक की ''प्रथम'' भारतीय महिला पदक विजेता, अंतर्राष्ट्रीय ओलंपिक समिति (IOC) का मुख्यालय, और मध्य प्रदेश का सर्वोच्च खेल ''प्रशिक्षक'' पुरस्कार।', 1, 1773842055, 1773842055, '{"must_know_lists":[{"list_title":"भारत और मध्य प्रदेश के प्रमुख खेल पुरस्कार","list_title_en":"Major Sports Awards of India and MP","items":["मेजर ध्यानचंद खेल रत्न (राष्ट्रीय) - सर्वोच्च खेल सम्मान (खिलाड़ियों के लिए)।","द्रोणाचार्य पुरस्कार (राष्ट्रीय) - खेल प्रशिक्षकों (Coaches) के लिए।","विश्वामित्र पुरस्कार (मध्य प्रदेश) - खेल प्रशिक्षकों के लिए।","विक्रम पुरस्कार (मध्य प्रदेश) - सीनियर खिलाड़ियों के लिए।","एकलव्य पुरस्कार (मध्य प्रदेश) - जूनियर खिलाड़ियों के लिए (19 वर्ष से कम)।"],"items_en":["Major Dhyan Chand Khel Ratna (National) - Highest sports honor (for players).","Dronacharya Award (National) - For sports coaches.","Vishwamitra Award (MP) - For sports coaches.","Vikram Award (MP) - For senior players.","Eklavya Award (MP) - For junior players (under 19 years)."],"memory_hook":"राष्ट्रीय कोच=द्रोणाचार्य, MP कोच=विश्वामित्र।","memory_hook_en":"National Coach=Dronacharya, MP Coach=Vishwamitra."}],"concept_capsule":"खेल (Sports) Current Affairs में सबसे ज्यादा स्कोरिंग सेक्शन है। MP के राज्य पुरस्कारों (विश्वामित्र, विक्रम) के मानदंड और खेल अकादमियों की मैपिंग (जैसे तीरंदाजी-जबलपुर) अवश्य याद करें। ''भारत में प्रथम'' (First in India) ओलंपिक विजेताओं का इतिहास भी पसंदीदा विषय है। वैश्विक संस्थाओं (UN Agencies, IOC) के मुख्यालय MPPSC के सबसे ''स्टेटिक'' करेंट अफेयर्स हैं।","concept_capsule_en":"Sports is the most scoring section in Current Affairs. Definitely memorize the criteria for MP state awards (Vishwamitra, Vikram) and mapping of sports academies (like Archery-Jabalpur). The history of ''First in India'' Olympic medalists is also a favorite topic. Headquarters of global institutions (UN Agencies, IOC) are the most ''static'' current affairs of MPPSC.","practice_prompts":["विश्व स्वास्थ्य संगठन (WHO) और यूनिसेफ (UNICEF) के मुख्यालय कहाँ स्थित हैं?","पेरिस ओलंपिक 2024 में भारत के ध्वजवाहक कौन थे?"],"practice_prompts_en":["Where are the headquarters of the World Health Organization (WHO) and UNICEF located?","Who were India''s flag bearers at the Paris Olympics 2024?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('a27b354a-e536-495f-86f5-89f43a4c4e65', 'ICT', 'ai-cyber-security-e-commerce', 'एआई, साइबर सुरक्षा और ई-कॉमर्स', 'AI, Cyber Security & E-Commerce', 'आर्टिफिशियल इंटेलिजेंस के जनक, साइबर सुरक्षा के मुख्य आयाम, और ई-कॉमर्स की वैश्विक पहुंच।', 1, 1773842608, 1773842608, '{"must_know_lists":[{"list_title":"AI और रोबोटिक्स के महत्वपूर्ण तथ्य","list_title_en":"Important Facts of AI and Robotics","items":["AI का जनक - जॉन मैक्कार्थी","रोबोटिक्स के तीन नियम - आइजैक असिमोव","सोफिया (Sophia) - नागरिकता पाने वाली पहली रोबोट","व्योमित्र (Vyommitra) - ISRO का ह्यूमनॉइड रोबोट"],"items_en":["Father of AI - John McCarthy","Three Laws of Robotics - Isaac Asimov","Sophia - First robot to get citizenship","Vyommitra - ISRO''s humanoid robot"],"memory_hook":"मैक्कार्थी ने AI बनाया, असिमोव ने नियम बनाए।","memory_hook_en":"McCarthy made AI, Asimov made laws."}],"concept_capsule":"ICT खंड में AI (आर्टिफिशियल इंटेलिजेंस) के मूल सिद्धांत और ई-कॉमर्स के आयामों (Global Reach, Ubiquity) पर लगातार प्रश्न पूछे जाते हैं। रोबोटिक्स के लाभ-हानि (Job replacement) का वैचारिक मूल्यांकन स्पष्ट होना चाहिए।","concept_capsule_en":"In the ICT section, questions are consistently asked on the basic principles of AI and dimensions of e-commerce (Global Reach, Ubiquity). Conceptual evaluation of robotics pros/cons (Job replacement) must be clear.","practice_prompts":["ई-गवर्नेंस के G2C, G2B और G2G मॉडल्स के बीच क्या अंतर है?","मशीन लर्निंग (Machine Learning) और डीप लर्निंग (Deep Learning) में क्या अंतर है?"],"practice_prompts_en":["What is the difference between G2C, G2B, and G2G models of E-Governance?","What is the difference between Machine Learning and Deep Learning?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('8fe835b1-69a2-4aef-909a-cc5adfa0b7b8', 'MP GK', 'tribes-art-culture', 'जनजातियां, कला और संस्कृति', 'Tribes, Art & Culture', 'मध्य प्रदेश की सबसे बड़ी जनजाति, विशेष जनजातीय अभिकरण (PVTGs), और प्रमुख कला व सम्मान।', 1, 1773842609, 1773842609, '{"must_know_lists":[{"list_title":"मध्य प्रदेश की विशेष पिछड़ी जनजातियां (PVTGs)","list_title_en":"PVTGs of Madhya Pradesh","items":["बैगा (Baiga) - मंडला, डिंडौरी, शहडोल, बालाघाट","भारिया (Bharia) - पातालकोट (छिंदवाड़ा)","सहरिया (Sahariya) - शिवपुरी, श्योपुर, गुना, मुरैना"],"items_en":["Baiga - Mandla, Dindori, Shahdol, Balaghat","Bharia - Patalkot (Chhindwara)","Sahariya - Shivpuri, Sheopur, Guna, Morena"],"memory_hook":"दक्षिण-पूर्व में बैगा, दक्षिण में भारिया, उत्तर में सहरिया।","memory_hook_en":"Baiga in South-East, Bharia in South, Sahariya in North."}],"concept_capsule":"मध्य प्रदेश की आदिवासी संस्कृति और विशेष पिछड़ी जनजातियों (PVTGs) के विकास प्राधिकरणों के जिले कंठस्थ होने चाहिए। राज्य सरकार के साहित्य और कला पुरस्कारों (निर्मल वर्मा, कबीर, तानसेन) के उद्देश्य को गहराई से पढ़ें।","concept_capsule_en":"MP''s tribal culture and the districts of PVTG development authorities must be rote-learned. Deeply read the objectives of the state government''s literature and art awards (Nirmal Verma, Kabir, Tansen).","practice_prompts":["मध्य प्रदेश में ''भगोरिया हाट'' किस जनजाति द्वारा और किस अवसर पर मनाया जाता है?","तानसेन सम्मान और कालिदास सम्मान किस क्षेत्र में दिए जाते हैं?"],"practice_prompts_en":["By which tribe and on what occasion is the ''Bhagoria Haat'' celebrated in MP?","In which fields are the Tansen Samman and Kalidas Samman awarded?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('9b2f642e-f66a-4cac-b607-ac36c953116a', 'MP GK', 'geography-demography-climate', 'भूगोल, जनसांख्यिकी और जलवायु', 'Geography, Demography & Climate', '2011 जनगणना के आंकड़े, 11 कृषि-जलवायु क्षेत्र, ओडीओपी (ODOP) उत्पाद, और ओंकारेश्वर सोलर प्रोजेक्ट।', 1, 1773842610, 1773842610, '{"must_know_lists":[{"list_title":"मध्य प्रदेश ''एक जिला एक उत्पाद'' (ODOP)","list_title_en":"MP ''One District One Product'' (ODOP)","items":["बालाघाट - कोदो कुटकी (और चिन्नौर चावल)","बैतूल - सागौन (Teak wood)","खरगोन - मिर्च (Chilli)","नरसिंहपुर - तुअर दाल / गुड़","छतरपुर - लकड़ी का फर्नीचर"],"items_en":["Balaghat - Kodo Kutki (and Chinnor Rice)","Betul - Teak wood","Khargone - Chilli","Narsinghpur - Toor Dal / Jaggery","Chhatarpur - Wooden Furniture"],"memory_hook":"खरगोन की मिर्ची, बैतूल का सागौन।","memory_hook_en":"Khargone Chilli, Betul Teak."}],"concept_capsule":"मध्य प्रदेश का आर्थिक व भौतिक भूगोल सबसे अधिक प्रश्न उत्पन्न करता है। 2011 की जनगणना के ''चरम'' (Extreme) जिले (घनत्व, लिंगानुपात, साक्षरता) हमेशा परीक्षा में होते हैं। ODOP योजना और वृहद सौर परियोजनाओं (रीवा, ओंकारेश्वर) को कंठस्थ करें।","concept_capsule_en":"MP''s Economic and Physical Geography generates the most questions. The ''extreme'' districts (density, sex ratio, literacy) of the 2011 Census are always in the exam. Rote learn the ODOP scheme and mega solar projects (Rewa, Omkareshwar).","practice_prompts":["कर्क रेखा (Tropic of Cancer) मध्य प्रदेश के कितने और किन प्रमुख जिलों से गुजरती है?","मध्य प्रदेश के 3 सबसे बड़े राष्ट्रीय उद्यानों के नाम लिखिए।"],"practice_prompts_en":["Through how many and which major districts of MP does the Tropic of Cancer pass?","Write the names of the 3 largest National Parks of Madhya Pradesh."]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('45d2de04-54b2-43ec-b621-8e5aca4dabf3', 'Current Affairs', 'sports-global-organizations', 'खेल और वैश्विक संगठन', 'Sports & Global Organizations', 'ओलंपिक समिति और FAO के मुख्यालय, प्रथम ओलंपिक पदक विजेता महिला, और MP के खेल पुरस्कार।', 1, 1773842611, 1773842611, '{"must_know_lists":[{"list_title":"मध्य प्रदेश की प्रमुख खेल अकादमियां","list_title_en":"Major Sports Academies of MP","items":["तीरंदाजी अकादमी - जबलपुर","एथलेटिक्स / पुरुष हॉकी अकादमी - भोपाल","महिला हॉकी / बैडमिंटन अकादमी - ग्वालियर","मलखम्ब अकादमी - उज्जैन","टेबल टेनिस अकादमी - इंदौर"],"items_en":["Archery Academy - Jabalpur","Athletics / Men''s Hockey Academy - Bhopal","Women''s Hockey / Badminton Academy - Gwalior","Mallakhamba Academy - Ujjain","Table Tennis Academy - Indore"],"memory_hook":"तीर-जबलपुर, मलखम्ब-उज्जैन, महिला हॉकी-ग्वालियर।","memory_hook_en":"Arrow-Jabalpur, Mallakhamb-Ujjain, Women Hockey-Gwalior."}],"concept_capsule":"खेलों का इतिहास (Olympics firsts), खेल अकादमियों के मुख्यालय, और संयुक्त राष्ट्र एजेंसियों (UN Agencies) के मुख्यालय समसामयिकी (Current Affairs) के सबसे सीधे और स्कोरिंग प्रश्न हैं।","concept_capsule_en":"The history of sports (Olympics firsts), HQs of sports academies, and HQs of UN Agencies are the most direct and scoring questions in Current Affairs.","practice_prompts":["विश्व व्यापार संगठन (WTO) और विश्व बैंक (World Bank) के मुख्यालय कहाँ स्थित हैं?","मध्य प्रदेश के ''प्रभाष जोशी पुरस्कार'' का संबंध किस खेल से है?"],"practice_prompts_en":["Where are the headquarters of the World Trade Organization (WTO) and World Bank located?","The ''Prabhash Joshi Award'' of Madhya Pradesh is related to which sport?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('5b26914c-49b7-4f4c-8cc3-6e6c6948fd7f', 'Polity', 'constitutional-amendments-mp-history', 'संवैधानिक संशोधन और मध्य प्रदेश इतिहास', 'Constitutional Amendments & MP History', 'प्रिवी पर्स की समाप्ति, MPPSC की संरचना, और भोपाल गैस त्रासदी जैसे ऐतिहासिक घटनाक्रम।', 1, 1773842612, 1773842612, '{"must_know_lists":[{"list_title":"भारत के प्रमुख संविधान संशोधन","list_title_en":"Major Constitutional Amendments of India","items":["26वां (1971) - प्रिवी पर्स की समाप्ति","42वां (1976) - ''मिनी संविधान'' (समाजवादी, पंथनिरपेक्ष)","44वां (1978) - संपत्ति का अधिकार मौलिक अधिकार से हटा","61वां (1989) - मतदान की आयु 21 से 18 वर्ष"],"items_en":["26th (1971) - Abolition of Privy Purse","42nd (1976) - ''Mini Constitution'' (Socialist, Secular)","44th (1978) - Right to Property removed from FRs","61st (1989) - Voting age reduced from 21 to 18"],"memory_hook":"26=राजा खत्म, 42=मिनी, 44=प्रॉपर्टी, 61=वोट।","memory_hook_en":"26=Kings gone, 42=Mini, 44=Property, 61=Vote."}],"concept_capsule":"भारतीय राजव्यवस्था में संविधान संशोधन (Amendments) स्वतंत्रता के बाद के इतिहास (Post-independence history) से गहराई से जुड़े हैं। MP के प्राचीन शहरों के नाम और बड़ी ऐतिहासिक घटनाओं की तिथियां (जैसे 1984) हर बार पूछी जाती हैं।","concept_capsule_en":"In Indian Polity, Constitutional Amendments are deeply connected with post-independence history. The ancient names of MP''s cities and dates of major historical events (like 1984) are asked every time.","practice_prompts":["संविधान की प्रस्तावना (Preamble) में अब तक कितनी बार संशोधन किया गया है?","भोपाल गैस त्रासदी की जाँच के लिए किस आयोग (Commission) का गठन किया गया था?"],"practice_prompts_en":["How many times has the Preamble of the Constitution been amended so far?","Which commission was formed to investigate the Bhopal Gas Tragedy?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('fffa3853-9e9e-4c9d-a7d0-7ed6c2476caf', 'Geography', 'indian-minerals', 'भारतीय खनिज', 'Indian Minerals', 'भारत में लौह अयस्क के भौगोलिक वितरण का विश्लेषण।', 1, 1773842612, 1773842612, '{"must_know_lists":[{"list_title":"भारत के प्रमुख खनिज और उनके भंडार राज्य","list_title_en":"Major Minerals of India and their Reserve States","items":["लौह अयस्क (हेमेटाइट) - ओडिशा, झारखंड, छत्तीसगढ़","कोयला (भंडार) - झारखंड, ओडिशा","बॉक्साइट - ओडिशा (50%+)","तांबा - राजस्थान (भंडार), म.प्र. (उत्पादन)"],"items_en":["Iron Ore (Hematite) - Odisha, Jharkhand, Chhattisgarh","Coal (Reserves) - Jharkhand, Odisha","Bauxite - Odisha (50%+)","Copper - Rajasthan (Reserves), MP (Production)"],"memory_hook":"ओडिशा खनिजों (बॉक्साइट, लोहा, कोयला) का पावरहाउस है।","memory_hook_en":"Odisha is the powerhouse of minerals (Bauxite, Iron, Coal)."}],"concept_capsule":"भूगोल में खनिजों का ''राज्य-वार वितरण'' (State-wise distribution) हमेशा ''सही/गलत कथन पहचानें'' वाले प्रश्नों में पूछा जाता है। भंडार (Reserves) और उत्पादन (Production) के बीच का अंतर स्पष्ट होना चाहिए।","concept_capsule_en":"In Geography, the ''state-wise distribution'' of minerals is always asked in ''identify true/false statement'' questions. The difference between Reserves and Production must be clear.","practice_prompts":["भारत की सबसे बड़ी यंत्रीकृत लौह अयस्क खदान (Mechanized Iron Ore Mine) कौन सी है और वह किस राज्य में है?","भारत में यूरेनियम (Uranium) की सबसे प्रसिद्ध खदान कहाँ स्थित है?"],"practice_prompts_en":["Which is India''s largest mechanized iron ore mine and in which state is it located?","Where is the most famous Uranium mine located in India?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('763f7cc0-2bd8-43f3-acb1-e5d2b4171dca', 'History', 'ancient-medieval-history', 'प्राचीन और मध्यकालीन इतिहास', 'Ancient & Medieval History', 'मध्यकालीन शब्दावली, प्राचीन अभिलेख/ग्रंथ (समन्त पासादिका, चचनामा), मुगलकालीन साहित्य और अलाउद्दीन खिलजी के दक्षिण अभियानों के ऐतिहासिक उद्धरण।', 1, 1773843563, 1773843563, '{"must_know_lists":[{"list_title":"प्राचीन एवं मध्यकालीन ऐतिहासिक पुस्तकें और उनके लेखक","list_title_en":"Ancient & Medieval Historical Books and their Authors","items":["समन्त पासादिका - बुद्ध घोष (Buddhaghosa)","मासिर-ए-आलमगिरी - साकी मुस्तैद खाँ (Saqi Mustaid Khan)","तहकीक-ए-हिन्द - अल-बरूनी (Al-Biruni)","मुद्राराक्षस - विशाखदत्त (Vishakhadatta)","चचनामा - अली अहमद / अबू बक्र कुफ़ी (सिंध का इतिहास)"],"items_en":["Samantapasadika - Buddhaghosa","Maasir-i-Alamgiri - Saqi Mustaid Khan","Tahqiq-i-Hind - Al-Biruni","Mudrarakshasa - Vishakhadatta","Chachnama - Ali Ahmad / Abu Bakr Kufi (History of Sindh)"],"memory_hook":"मुस्तैद का आलम, घोष का समन्त।","memory_hook_en":"Mustaid''s Alam, Ghosh''s Samanta."}],"concept_capsule":"मध्यकालीन और प्राचीन इतिहास में ''शब्दावली'' (Terminology like Panahi/Upanah), ऐतिहासिक पुस्तकों के लेखक, और ''कथन/उद्धरण'' (Quotes like Amir Khusro''s) MPPSC के सबसे चुनौतीपूर्ण (Bouncer) प्रश्न बनाते हैं। इन सूक्ष्म तथ्यों पर विशेष ध्यान दें क्योंकि ये मेरिट तय करते हैं।","concept_capsule_en":"In Medieval and Ancient History, ''Terminology'' (like Panahi/Upanah), authors of historical books, and ''Quotes'' (like Amir Khusro''s) form the most challenging (bouncer) questions in MPPSC. Pay special attention to these micro-facts as they decide the merit.","practice_prompts":["विजयनगर साम्राज्य में ''अमरम'' (Amaram) शब्द का क्या अर्थ था?","हर्षवर्धन के शासनकाल का विस्तृत विवरण किस चीनी यात्री की पुस्तक ''सी-यू-की'' (Si-Yu-Ki) में मिलता है?"],"practice_prompts_en":["What was the meaning of the word ''Amaram'' in the Vijayanagara Empire?","A detailed account of Harshavardhana''s reign is found in the book ''Si-Yu-Ki'' by which Chinese traveler?"]}');
INSERT INTO "pyq_topics" ("id", "subject", "topic_slug", "topic_title", "topic_title_en", "description", "is_active", "created_at", "updated_at", "ai_content") VALUES ('83dd10e6-32b8-4d5f-b16c-0e059d4b8525', 'History', 'modern-history-social-reforms', 'आधुनिक इतिहास और समाज सुधार', 'Modern History & Social Reforms', '1857 की क्रांति पर इतिहासकारों और विदेशी संवाददाताओं के विचार, ब्रिटिश कालीन प्रशासन के प्रसिद्ध उद्धरण और 19वीं सदी के समाज सुधार आंदोलन (ब्रह्म समाज)।', 1, 1773843564, 1773843564, '{"must_know_lists":[{"list_title":"1857 के विद्रोह पर प्रसिद्ध इतिहासकारों के कथन","list_title_en":"Famous Statements by Historians on the 1857 Revolt","items":["वी. डी. सावरकर - ''यह प्रथम राष्ट्रीय स्वतंत्रता संग्राम था।''","डॉ. आर. सी. मजूमदार - ''यह न तो प्रथम, न राष्ट्रीय और न ही स्वतंत्रता संग्राम था।'' (राष्ट्रवाद भ्रूणावस्था में था)","बेंजामिन डिज़रायली - ''यह एक राष्ट्रीय विद्रोह था।''","टी. आर. होम्स - ''यह बर्बरता और सभ्यता के बीच युद्ध था।''"],"items_en":["V.D. Savarkar - ''It was the First National War of Independence.''","Dr. R.C. Majumdar - ''It was neither first, nor national, nor a war of independence.'' (Nationalism in embryonic stage)","Benjamin Disraeli - ''It was a national revolt.''","T.R. Holmes - ''It was a conflict between barbarism and civilization.''"],"memory_hook":"सावरकर ने प्रथम कहा, मजूमदार ने नकारा। होम्स को बर्बरता दिखी।","memory_hook_en":"Savarkar said First, Majumdar denied it. Holmes saw barbarism."}],"concept_capsule":"आधुनिक भारतीय इतिहास में ब्रिटिश प्रशासनिक अधिकारियों के ''उद्धरण'' (Quotes like ''Little Republics'') और समाज सुधार आंदोलनों के ''विभाजन'' (Splits in Brahmo Samaj, Arya Samaj) MPPSC के अत्यंत गहराई वाले प्रश्न होते हैं। इन्हें तथ्यात्मक रूप से रटना आवश्यक है।","concept_capsule_en":"In Modern Indian History, ''Quotes'' of British administrative officers (like ''Little Republics'') and ''Splits'' in social reform movements (Brahmo Samaj, Arya Samaj) are highly in-depth MPPSC questions. Rote learning them factually is necessary.","practice_prompts":["सत्यशोधक समाज (Satyashodhak Samaj) की स्थापना किसने और किस वर्ष की थी?","भारत छोड़ो आंदोलन (Quit India Movement) के दौरान अमेरिकी पत्रकार कौन था जो महात्मा गांधी के साथ था?"],"practice_prompts_en":["Who founded the Satyashodhak Samaj and in which year?","Who was the American journalist present with Mahatma Gandhi during the Quit India Movement?"]}');
