INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ma1aTncKKcduPThRFL9u3', 'FFPEWTMww259TMakCWyYF', '₹5000 पर 10% वार्षिक दर से 2 वर्ष का साधारण ब्याज क्या है?', '"[\"₹1000\",\"₹500\",\"₹1100\",\"₹1200\"]"', '0.0', 'SI = (P*R*T)/100 = (5000*10*2)/100 = 1000.', 2, 0, 38, 'Quantitative Aptitude', 'What is the Simple Interest on ₹5000 at 10% p.a. for 2 years?', 'SI formula calculation.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('HN_PyGd9i9CcOz9WPkxZa', 'FFPEWTMww259TMakCWyYF', '5 लड़के एक पंक्ति में बैठे हैं। A, B के दाईं ओर है, E, B के बाईं ओर है, लेकिन C के दाईं ओर है। यदि A, D के बाईं ओर है, तो बीच में कौन बैठा है?', '"[\"B\",\"E\",\"A\",\"C\"]"', '0.0', 'क्रम: C - E - B - A - D. बीच में B है।', 2, 0, 39, 'Reasoning', '5 boys are sitting in a row. A is right of B, E is left of B but right of C. If A is left of D, who is sitting in the middle?', 'Order is C-E-B-A-D. B is in the middle.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('JtFRFQo1v7NOzIErfEL1M', 'FFPEWTMww259TMakCWyYF', 'एक सिक्के को दो बार उछाला जाता है। कम से कम एक चित (Head) आने की प्रायिकता क्या है?', '"[\"1/2\",\"1/4\",\"3/4\",\"1\"]"', '2.0', 'परिणाम: HH, HT, TH, TT. अनुकूल: HH, HT, TH (3). प्रायिकता = 3/4.', 2, 0, 40, 'Quantitative Aptitude', 'A coin is tossed twice. What is the probability of getting at least one Head?', 'Total outcomes 4. Favorable (at least 1 H) are 3. So 3/4.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3n6yU4k8HRgR6cJy7wNTK', 'FFPEWTMww259TMakCWyYF', 'यदि ''पानी'' को ''भोजन'', ''भोजन'' को ''पेड़'', ''पेड़'' को ''आकाश'' और ''आकाश'' को ''दीवार'' कहा जाए, तो फल कहाँ उगेंगे?', '"[\"Tree\",\"Sky\",\"Food\",\"Wall\"]"', '1.0', 'फल पेड़ पर उगते हैं, और पेड़ को ''आकाश'' कहा गया है।', 2, 0, 41, 'Reasoning', 'If ''Water'' is called ''Food'', ''Food'' is called ''Tree'', ''Tree'' is called ''Sky'', and ''Sky'' is called ''Wall'', where will fruit grow?', 'Fruit grows on Tree, and Tree is called Sky.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sFyqa_iXC9CkE8EbR6upC', 'FFPEWTMww259TMakCWyYF', '3, 10, 29, 66, ?', '"[\"127\",\"125\",\"130\",\"115\"]"', '0.0', 'पैटर्न: n³ + 2. (1³+2=3, 2³+2=10, 3³+2=29, 4³+2=66). अगला 5³+2 = 127.', 2, 0, 42, 'Reasoning', '3, 10, 29, 66, ?', 'Pattern is cube of n plus 2.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ckm8ZcXHczucemTiMHYVs', 'FFPEWTMww259TMakCWyYF', 'पारस्परिक संचार (Interpersonal Communication) में, ''प्रतिपुष्टि'' (Feedback) का मुख्य उद्देश्य क्या है?', '"[\"संचार को समाप्त करना / To end communication\",\"समझ की पुष्टि करना / To confirm understanding\",\"प्रेषक को भ्रमित करना / To confuse the sender\",\"संदेश को नजरअंदाज करना / To ignore the message\"]"', '1.0', 'फीडबैक यह सुनिश्चित करता है कि संदेश सही ढंग से समझा गया है।', 2, 0, 43, 'Communication', 'In Interpersonal Communication, what is the main purpose of ''Feedback''?', 'Feedback confirms understanding.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sn2LAkfRgdYwLOB7vIaPS', 'FFPEWTMww259TMakCWyYF', 'निम्नलिखित में से कौन संचार में एक मनोवैज्ञानिक बाधा (Psychological Barrier) है?', '"[\"शोर / Noise\",\"पूर्वाग्रह / Prejudice\",\"दूरी / Distance\",\"तकनीकी विफलता / Technical failure\"]"', '1.0', 'पूर्वाग्रह मन की स्थिति है जो संदेश को ग्रहण करने में बाधा डालता है।', 2, 0, 44, 'Communication', 'Which of the following is a Psychological Barrier in communication?', 'Prejudice is a mindset affecting reception.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3QlHCEIKYZX1jIVVQyOxJ', 'FFPEWTMww259TMakCWyYF', 'संचार शैलियों को सुमेलित करें:', '"[\"(1)-(b), (2)-(c), (3)-(a), (4)-(d)\",\"(1)-(a), (2)-(b), (3)-(c), (4)-(d)\",\"(1)-(c), (2)-(d), (3)-(a), (4)-(b)\",\"(1)-(d), (2)-(a), (3)-(b), (4)-(c)\"]"', '0.0', 'Aggressive is dominating, Passive is submissive, Assertive is balanced.', 2, 0, 45, 'Communication', 'Match the communication styles:', 'Aggressive is dominating, Passive is submissive, Assertive is balanced.', 60, 'matching', '[{"id":"(1)","label":"Aggressive","match":"Win-Win","matchId":"(a)"},{"id":"(2)","label":"Passive","match":"I win, You lose","matchId":"(b)"},{"id":"(3)","label":"Assertive","match":"I lose, You win","matchId":"(c)"},{"id":"(4)","label":"Passive-Aggressive","match":"Indirect sabotage","matchId":"(d)"}]', NULL, NULL, 'mppsc');
