INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8E4JkQZVvdfHy3WOa768E', 'FFPEWTMww259TMakCWyYF', 'निर्देश: एक परिवार में A और B भाई हैं। C और D बहनें हैं। A का बेटा D का भाई है। B का C से क्या संबंध है?', '"[\"पिता / Father\",\"भाई / Brother\",\"चाचा / Uncle\",\"दादा / Grandfather\"]"', '2.0', 'A के बच्चे D और C (बहनें) और A का बेटा (D का भाई) हैं। B, A का भाई है, इसलिए B, C का चाचा है।', 2, 0, 54, 'Reasoning', 'Direction: A and B are brothers. C and D are sisters. A''s son is D''s brother. How is B related to C?', 'B is the brother of C''s father (A). So Uncle.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Z37dFpl3q2pr6vWPLcGPF', 'FFPEWTMww259TMakCWyYF', 'एक मानचित्र पर 1 सेमी = 10 किमी है। यदि मानचित्र पर दूरी 5 सेमी है, तो वास्तविक दूरी क्या है?', '"[\"50 km\",\"5 km\",\"500 km\",\"0.5 km\"]"', '0.0', '5 * 10 = 50.', 2, 0, 55, 'Quantitative Aptitude', 'On a map 1 cm = 10 km. If map distance is 5 cm, actual distance is?', 'Simple multiplication.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('B0k7c86xunK55PI-wgtBJ', 'FFPEWTMww259TMakCWyYF', '**निर्देश: निम्नलिखित गद्यांश को पढ़ें:**
