INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('XeytPILYxMDhrisvJf2uu', 'drcNxyFKGMfTnD-GGZ89b', 'संचार का ''शानोन-वीवर'' मॉडल (Shannon-Weaver Model) मुख्य रूप से किस पर केंद्रित है?', '"[\"मनोवैज्ञानिक पहलू / Psychological aspect\",\"तकनीकी और प्रसारण / Technical and transmission\",\"सांस्कृतिक बाधाएं / Cultural barriers\",\"अंतर-वैयक्तिक संबंध / Interpersonal relations\"]"', '1.0', 'यह एक गणितीय/तकनीकी मॉडल है जो सिग्नल ट्रांसमिशन पर केंद्रित है।', 2, 0, 46, 'Communication', 'Shannon-Weaver Model primarily focuses on:', 'It''s a linear, technical model.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('svLPDpk1dHSnDXO0qLOwO', 'drcNxyFKGMfTnD-GGZ89b', 'इनमें से कौन ''सिमेंटिक बाधा'' (Semantic Barrier) का उदाहरण है?', '"[\"शोरगुल वाला कमरा / Noisy room\",\"खराब इंटरनेट / Bad internet\",\"तकनीकी शब्दजाल / Technical Jargon\",\"समय की कमी / Lack of time\"]"', '2.0', 'भाषा या शब्दों (Jargon) की नासमझी सिमेंटिक बाधा है।', 2, 0, 47, 'Communication', 'Which is an example of Semantic Barrier?', 'Jargon creates language understanding issues.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('FXhqVOm8hg7hBsL9z8hVh', 'drcNxyFKGMfTnD-GGZ89b', '3 पुरुष या 5 महिलाएं एक काम को 12 दिनों में कर सकते हैं। 6 पुरुष और 5 महिलाएं इसे कितने दिनों में करेंगे?', '"[\"4 days\",\"5 days\",\"3 days\",\"6 days\"]"', '0.0', '3M = 5W. 6M = 10W. Total 10W + 5W = 15W. 5W -> 12 days. 15W -> 12/3 = 4 days.', 2, 0, 48, 'Quantitative Aptitude', '3 Men or 5 Women can do a work in 12 days. How long for 6 Men and 5 Women?', 'Convert all to women equivalent. 4 days.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
