INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2ySxwYNx2K9mqzQCEPCfz', 'drcNxyFKGMfTnD-GGZ89b', 'जोहरी खिड़की (Johari Window) मॉडल का उपयोग किसके लिए किया जाता है?', '"[\"नेटवर्क विश्लेषण / Network analysis\",\"आत्म-जागरूकता और आपसी समझ / Self-awareness and mutual understanding\",\"बाजार अनुसंधान / Market research\",\"वित्त प्रबंधन / Financial management\"]"', '1.0', 'यह व्यक्तिगत विकास और टीम डायनेमिक्स के लिए एक मनोवैज्ञानिक उपकरण है।', 2, 0, 51, 'Communication', 'Johari Window model is used for?', 'Psychological tool for self-awareness.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Iv5V3YHg9yPJX-8_yd-JQ', 'drcNxyFKGMfTnD-GGZ89b', 'संचार प्रक्रिया में ''डिकोडिंग'' कौन करता है?', '"[\"प्रेषक / Sender\",\"प्राप्तकर्ता / Receiver\",\"माध्यम / Medium\",\"इनमें से कोई नहीं / None\"]"', '1.0', 'प्राप्तकर्ता संदेश (प्रतीकों) को अर्थ में बदलता (डिकोड) है।', 2, 0, 52, 'Communication', 'Who performs ''Decoding'' in the communication process?', 'Receiver translates symbols into meaning.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('-Ze-9a8pJrfTmRAHADrom', 'drcNxyFKGMfTnD-GGZ89b', 'एक दुकानदार अपनी वस्तुओं पर क्रय मूल्य से 20% अधिक अंकित करता है और 10% छूट देता है। उसका लाभ % क्या है?', '"[\"10%\",\"8%\",\"12%\",\"15%\"]"', '1.0', '100 -> 120 -> 10% छूट (12) -> 108. लाभ 8%।', 2, 0, 53, 'Quantitative Aptitude', 'Shopkeeper marks goods 20% above CP and gives 10% discount. Profit %?', '120 - 12 = 108. Profit 8%.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('YY4VxqHJVn0w18xOuDtYN', 'drcNxyFKGMfTnD-GGZ89b', '60 किमी/घंटा की गति से चलने वाली कार 15 मिनट में कितनी दूरी तय करेगी?', '"[\"10 km\",\"15 km\",\"20 km\",\"25 km\"]"', '1.0', '1 घंटे में 60 किमी। 15 मिनट (1/4 घंटा) में 15 किमी।', 2, 0, 54, 'Quantitative Aptitude', 'Distance covered by a car moving at 60 km/hr in 15 mins?', '60 * (15/60) = 15.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ESMU7jNMM5WE9KBBFxB1I', 'drcNxyFKGMfTnD-GGZ89b', 'निम्नलिखित भिन्न में सबसे बड़ा कौन सा है: 2/3, 3/5, 5/8?', '"[\"2/3\",\"3/5\",\"5/8\",\"All equal\"]"', '0.0', '2/3=0.66, 3/5=0.60, 5/8=0.625.', 2, 0, 55, 'Quantitative Aptitude', 'Largest fraction among: 2/3, 3/5, 5/8?', 'Decimal conversion shows 0.66 is largest.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e_Z3QVaIqNE6pbg9_1jdD', 'drcNxyFKGMfTnD-GGZ89b', '**निर्देश: गद्यांश पढ़ें:**
आर्टिफिशियल इंटेलिजेंस (AI) हमारे जीवन को बदल रहा है। यह स्वास्थ्य, शिक्षा और परिवहन में क्रांति ला रहा है। हालांकि, इससे रोजगार छिनने और निजता के हनन का डर भी बना हुआ है। हमें इसका नैतिक उपयोग सुनिश्चित करना चाहिए।

----------------------------
**प्रश्न:** AI किस क्षेत्र में क्रांति ला रहा है?', '"[\"कृषि / Agriculture\",\"स्वास्थ्य और शिक्षा / Health and Education\",\"खनन / Mining\",\"मत्स्य पालन / Fishing\"]"', '1.0', NULL, 2, 0, 56, 'Reading Comprehension', '**Direction: Read passage:**
Artificial Intelligence (AI) is transforming our lives. It is revolutionizing health, education, and transport. However, fears of job loss and privacy breach persist. We must ensure its ethical use.

----------------------------
**Question:** In which sector is AI bringing a revolution?', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0jXGQh6q1elaNmTdy55mN', 'drcNxyFKGMfTnD-GGZ89b', '**निर्देश: गद्यांश पढ़ें:**
आर्टिफिशियल इंटेलिजेंस (AI) हमारे जीवन को बदल रहा है। यह स्वास्थ्य, शिक्षा और परिवहन में क्रांति ला रहा है। हालांकि, इससे रोजगार छिनने और निजता के हनन का डर भी बना हुआ है। हमें इसका नैतिक उपयोग सुनिश्चित करना चाहिए।

----------------------------
