INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3lWezB3onf2PyKiyUGSZx', '3bIu3iTfpozIvU5_YWpTk', '''मौन'' (Silence) संचार का कौन सा रूप है?', '"[\"शाब्दिक / Verbal\",\"अशाब्दिक / Non-Verbal\",\"लिखित / Written\",\"औपचारिक / Formal\"]"', '1.0', 'मौन एक शक्तिशाली अशाब्दिक संकेत है।', 2, 0, 43, 'Communication', 'What form of communication is ''Silence''?', 'Silence is non-verbal communication.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
