INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('oCmqNDgihf-tOsReTan8X', '3bIu3iTfpozIvU5_YWpTk', '5 संख्याओं का औसत 27 है। यदि एक संख्या हटा दी जाए, तो औसत 25 हो जाता है। हटाई गई संख्या क्या है?', '"[\"35\",\"25\",\"27\",\"30\"]"', '0.0', 'योग अंतर: (5*27) - (4*25) = 135 - 100 = 35।', 2, 0, 48, 'Quantitative Aptitude', 'Average of 5 numbers is 27. If one is excluded, average becomes 25. Excluded number?', 'Sum difference: 135 - 100 = 35.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('GStMCe-7LSWBZZDtH-hZ_', '3bIu3iTfpozIvU5_YWpTk', 'शतरंज के बोर्ड में कितने वर्ग होते हैं (सभी आकारों के)?', '"[\"64\",\"204\",\"100\",\"256\"]"', '1.0', 'सूत्र: 1² + 2² + ... + 8² = 204।', 2, 0, 49, 'Quantitative Aptitude', 'How many squares are there on a chessboard (of all sizes)?', 'Sum of squares from 1 to 8.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dHHz0vS72-b_MlOMn3bvp', '3bIu3iTfpozIvU5_YWpTk', 'यदि ''A'' + ''A'' = 2, ''B'' + ''B'' = 4, तो ''A'' + ''B'' = ?', '"[\"3\",\"6\",\"5\",\"2\"]"', '0.0', 'A=1, B=2. 1+2=3.', 2, 0, 50, 'Reasoning', 'If ''A''+''A''=2, ''B''+''B''=4, then ''A''+''B''=?', 'Values of A and B.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('yjhlRpznhny43-ffIKkdC', '3bIu3iTfpozIvU5_YWpTk', 'लेन-देन विश्लेषण (Transactional Analysis) में ''माता-पिता अहंकार अवस्था'' (Parent Ego State) क्या दर्शाती है?', '"[\"तार्किक सोच / Logical thinking\",\"सिखाए गए व्यवहार और नियम / Taught behaviors and rules\",\"बचकाना व्यवहार / Childish behavior\",\"रचनात्मकता / Creativity\"]"', '1.0', 'पैरेंट ईगो स्टेट में अधिकार, नियम और सीखे गए पूर्वाग्रह शामिल होते हैं।', 2, 0, 51, 'Communication', 'In Transactional Analysis, what does ''Parent Ego State'' represent?', 'Represents authority, rules, and learned values.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('PFY42YxPG0s6gAuDpDhrX', '3bIu3iTfpozIvU5_YWpTk', 'संचार में ''प्रतिपुष्टि'' (Feedback) कब पूरी होती है?', '"[\"जब संदेश भेजा जाता है / When message is sent\",\"जब रिसीवर संदेश को समझकर प्रतिक्रिया देता है / When receiver understands and responds\",\"जब शोर होता है / When there is noise\",\"जब चैनल चुना जाता है / When channel is selected\"]"', '1.0', 'प्रतिक्रिया लूप रिसीवर के जवाब के साथ बंद होता है।', 2, 0, 52, 'Communication', 'When is ''Feedback'' complete in communication?', 'Cycle closes with response.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('syrsL-pjyyamGvinfGr8D', '3bIu3iTfpozIvU5_YWpTk', 'एक संख्या का 3/5 भाग उसके 40% से 40 अधिक है। संख्या क्या है?', '"[\"100\",\"150\",\"200\",\"400\"]"', '2.0', '3/5 = 60%. 60%x - 40%x = 40. 20%x = 40. x = 200.', 2, 0, 53, 'Quantitative Aptitude', '3/5 of a number is 40 more than its 40%. The number is?', '20% difference equals 40. Total 200.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('P52wXW8OegbF9OYFgPwuU', '3bIu3iTfpozIvU5_YWpTk', 'यदि x + 1/x = 2, तो x¹⁰⁰ + 1/x¹⁰⁰ = ?', '"[\"2\",\"0\",\"1\",\"100\"]"', '0.0', 'यदि x + 1/x = 2, तो x = 1 संतुष्ट करता है। 1 + 1 = 2.', 2, 0, 54, 'Quantitative Aptitude', 'If x + 1/x = 2, then x¹⁰⁰ + 1/x¹⁰⁰ = ?', 'x=1 satisfies the condition.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
