INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('CLbu_U2gD4a9haCDjPLO-', '3bIu3iTfpozIvU5_YWpTk', '**निर्देश: गद्यांश पढ़ें:**
