INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('IO2_DzoLBrKd2j8QVOkD4', '3bIu3iTfpozIvU5_YWpTk', 'निम्नलिखित में से कौन सा शब्द विशेषण है?', '"[\"सुंदरता\",\"सुंदर\",\"सौंदर्य\",\"मिठास\"]"', '1.0', '''सुंदर'' गुणवाचक विशेषण है। बाकी भाववाचक संज्ञाएं हैं।', 2, 0, 98, 'Hindi Grammar', 'N/A', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('YOe9pAFNK7ZMBb2Kx4pEq', '3bIu3iTfpozIvU5_YWpTk', 'चौपाई छंद के प्रत्येक चरण में कितनी मात्राएं होती हैं?', '"[\"16\",\"14\",\"12\",\"18\"]"', '0.0', '16 मात्राएं।', 2, 0, 99, 'Hindi Grammar', 'N/A', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Qehaig2h6pYTtSSHdZ1ct', '3bIu3iTfpozIvU5_YWpTk', 'देवनागरी लिपि का विकास किस लिपि से हुआ?', '"[\"ब्राह्मी\",\"खरोष्ठी\",\"रोमन\",\"फारसी\"]"', '0.0', 'ब्राह्मी लिपि से।', 2, 0, 100, 'Hindi Grammar', 'N/A', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('53ec113f-d42e-4e95-a280-d3877a2c32ae', '491941d1-1508-44c2-9c41-bd862625df0e', 'ऋग्वेद के ''पुरुष सूक्त'' (Purusha Sukta) में चारों वर्णों की उत्पत्ति एक विराट पुरुष के विभिन्न अंगों से बताई गई है। इसमें ''क्षत्रिय'' (Kshatriya) की उत्पत्ति किस अंग से मानी गई है?', '[{"id":"A","text":"मुख (Mouth)","text_en":"मुख (Mouth)"},{"id":"B","text":"बाहु/भुजाएं (Arms)","text_en":"बाहु/भुजाएं (Arms)"},{"id":"C","text":"जंघा (Thighs)","text_en":"जंघा (Thighs)"},{"id":"D","text":"चरण (Feet)","text_en":"चरण (Feet)"}]', '1', '**✅ Correct Logic:** पुरुष सूक्त (10.90) के अनुसार: ''ब्राह्मणोऽस्य मुखमासीद् बाहू राजन्यः कृतः'' (ब्राह्मण मुख से, क्षत्रिय भुजाओं से)। भुजाएं ''शक्ति और रक्षा'' (Power and Protection) का प्रतीक हैं।

**💡 Exam Fact:** वैश्य (जंघा - व्यापार/गति) और शूद्र (पैर - सेवा/आधार) से उत्पन्न माने गए हैं।

**🧠 Memory Tip:** Arms = Army = Kshatriya.

**🚫 Scam Alert:** अक्सर छात्र ''सिर'' (Head) सोच लेते हैं, लेकिन ''मुख'' (Mouth) सही शब्द है ब्राह्मण के लिए।', 2, 0, 1, NULL, 'In the ''Purusha Sukta'' of Rigveda, the origin of the four Varnas is described from different parts of a Cosmic Man. From which part is the ''Kshatriya'' said to have originated?', '**✅ Correct Logic:** According to Purusha Sukta (10.90): ''Brahmano''sya mukhamasid bahu rajanyah kritah'' (Brahmin from mouth, Kshatriya from arms). Arms symbolize ''Power and Protection''.

**💡 Exam Fact:** Vaishya (Thighs - Trade/Motion) and Shudra (Feet - Service/Base).

**🧠 Memory Tip:** Arms = Army = Kshatriya.

**🚫 Scam Alert:** Students often think ''Head'', but ''Mouth'' is the specific term for Brahmin.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('da887242-b177-4a1f-ad96-1a6a60e88395', '491941d1-1508-44c2-9c41-bd862625df0e', 'भगवद्गीता में वर्ण व्यवस्था का आधार ''जन्म'' (Birth) न मानकर क्या माना गया है?', '[{"id":"A","text":"धन और संपत्ति (Wealth and Property)","text_en":"धन और संपत्ति (Wealth and Property)"},{"id":"B","text":"गुण और कर्म (Guna and Karma)","text_en":"गुण और कर्म (Guna and Karma)"},{"id":"C","text":"शिक्षा और उपाधि (Education and Degree)","text_en":"शिक्षा और उपाधि (Education and Degree)"},{"id":"D","text":"शारीरिक बल (Physical Strength)","text_en":"शारीरिक बल (Physical Strength)"}]', '1', '**✅ Correct Logic:** गीता (4.13) में कृष्ण कहते हैं: "चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः"। यानी वर्णों का विभाजन व्यक्ति के गुणों (सत्व, रज, तम) और उसके कर्मों (Actions) के आधार पर किया गया है, जन्म के आधार पर नहीं।

**💡 Exam Fact:** यह प्राचीन भारत में ''सामाजिक गतिशीलता'' (Social Mobility) का प्रमाण है।

**🧠 Memory Tip:** G+K = **G**una (Nature) + **K**arma (Work) = Varna.

**🚫 Scam Alert:** बाद के स्मृतिकारों ने इसे जन्मना (By birth) बना दिया, लेकिन गीता का मूल सिद्धांत गुण-कर्म है।', 2, 0, 2, NULL, 'In Bhagavad Gita, what is considered the basis of Varna system instead of ''Birth''?', '**✅ Correct Logic:** In Gita (4.13), Krishna says: "Chaturvarnyam maya srishtam guna-karma vibhagashah". Meaning, Varnas are divided based on Gunas (Sattva, Rajas, Tamas) and Karma (Actions), not birth.

**💡 Exam Fact:** This is proof of ''Social Mobility'' in ancient India.

**🧠 Memory Tip:** G+K = **G**una (Nature) + **K**arma (Work) = Varna.

**🚫 Scam Alert:** Later Smriti writers made it hereditary, but Gita''s core principle is Guna-Karma.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b0ee9a48-6776-4942-99d4-7e0dc1f79c26', '491941d1-1508-44c2-9c41-bd862625df0e', 'निम्नलिखित में से कौन ''द्विज'' (Dwija) की श्रेणी में शामिल नहीं था?', '[{"id":"A","text":"ब्राह्मण (Brahmin)","text_en":"ब्राह्मण (Brahmin)"},{"id":"B","text":"क्षत्रिय (Kshatriya)","text_en":"क्षत्रिय (Kshatriya)"},{"id":"C","text":"वैश्य (Vaishya)","text_en":"वैश्य (Vaishya)"},{"id":"D","text":"शूद्र (Shudra)","text_en":"शूद्र (Shudra)"}]', '3', '**✅ Correct Logic:** ''द्विज'' का अर्थ है ''दो बार जन्म लेने वाला'' (पहला भौतिक जन्म, दूसरा उपनयन संस्कार से विद्या जन्म)। केवल पहले तीन वर्णों (ब्राह्मण, क्षत्रिय, वैश्य) को ही उपनयन (जनेऊ) का अधिकार था, इसलिए वे ''द्विज'' कहलाते थे। शूद्र इसमें शामिल नहीं थे।

**💡 Exam Fact:** वेदों का अध्ययन भी केवल द्विजों तक सीमित कर दिया गया था।

**🧠 Memory Tip:** **Top 3** get the thread (Janeu) = Dwija.

**🚫 Scam Alert:** वैश्य व्यापार करता था, लेकिन वह भी ''द्विज'' था। इसे अक्सर छात्र भूल जाते हैं।', 2, 0, 3, NULL, 'Who among the following was NOT included in the category of ''Dwija'' (Twice-born)?', '**✅ Correct Logic:** ''Dwija'' means ''Twice-born'' (First physical birth, second spiritual birth via Upanayana). Only the first three Varnas (Brahmin, Kshatriya, Vaishya) had the right to Upanayana (Sacred Thread), so they were ''Dwija''. Shudras were excluded.

**💡 Exam Fact:** Study of Vedas was also restricted to Dwijas.

**🧠 Memory Tip:** **Top 3** get the thread (Janeu) = Dwija.

**🚫 Scam Alert:** Vaishya was a trader, but he was also ''Dwija''. Students often forget this.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4d02d577-2c84-4126-825e-3ef865943d05', '491941d1-1508-44c2-9c41-bd862625df0e', '''आश्रम व्यवस्था'' (Ashrama System) का मुख्य उद्देश्य क्या था?', '[{"id":"A","text":"केवल मोक्ष प्राप्त करना (Only to attain Moksha)","text_en":"केवल मोक्ष प्राप्त करना (Only to attain Moksha)"},{"id":"B","text":"मनुष्य के जीवन को 100 वर्ष मानकर उसे व्यवस्थित और संतुलित करना (To organize and balance human life assuming it to be 100 years)","text_en":"मनुष्य के जीवन को 100 वर्ष मानकर उसे व्यवस्थित और संतुलित करना (To organize and balance human life assuming it to be 100 years)"},{"id":"C","text":"समाज में वर्णों को अलग करना (To separate Varnas in society)","text_en":"समाज में वर्णों को अलग करना (To separate Varnas in society)"},{"id":"D","text":"वृद्धावस्था में देखभाल करना (Care in old age)","text_en":"वृद्धावस्था में देखभाल करना (Care in old age)"}]', '1', '**✅ Correct Logic:** आश्रम व्यवस्था जीवन को चार चरणों (ब्रह्मचर्य, गृहस्थ, वानप्रस्थ, संन्यास) में बांटकर ''पुरुषार्थों'' (धर्म, अर्थ, काम, मोक्ष) के बीच संतुलन बनाने की मनोवैज्ञानिक और सामाजिक व्यवस्था थी।

**💡 Exam Fact:** इसे ''जीवन की सीढ़ियाँ'' (Stages of Life) भी कहा जाता है।

**🧠 Memory Tip:** Ashrama = **A**rrangement of Life (25-25-25-25).

**🚫 Scam Alert:** केवल मोक्ष अंतिम लक्ष्य है, लेकिन आश्रम व्यवस्था का उद्देश्य ''सभी'' पुरुषार्थों की प्राप्ति है (गृहस्थ में काम/अर्थ)।', 2, 0, 4, NULL, 'What was the main objective of the ''Ashrama System''?', '**✅ Correct Logic:** The Ashrama system was a psychological and social arrangement to balance the ''Purusharthas'' by dividing life into four stages (Brahmacharya, Grihastha, Vanaprastha, Sannyasa).

**💡 Exam Fact:** It is also called ''Stages of Life''.

**🧠 Memory Tip:** Ashrama = **A**rrangement of Life (25-25-25-25).

**🚫 Scam Alert:** Moksha is the final goal, but the system''s aim is the attainment of ''all'' Purusharthas (Kama/Artha in Grihastha).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ceea5367-fa4e-4d72-9576-c92f20489870', '491941d1-1508-44c2-9c41-bd862625df0e', 'आश्रमों को उनके मुख्य कर्तव्यों से सुमेलित करें (Match the Ashramas with their primary duties):', '[{"id":"A","text":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)","text_en":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"}]', '0', '**✅ Correct Logic:**
* **ब्रह्मचर्य:** 25 वर्ष तक शिक्षा।
* **गृहस्थ:** सबसे महत्वपूर्ण आश्रम, क्योंकि यह बाकी तीनों का भरण-पोषण करता है।
* **वानप्रस्थ:** धीरे-धीरे मोह त्यागना।
* **संन्यास:** पूर्ण विरक्ति।

**💡 Exam Fact:** मनुस्मृति में ''गृहस्थ आश्रम'' को ''ज्येष्ठ'' (Eldest/Best) कहा गया है क्योंकि यह समाज की रीढ़ है।

**🧠 Memory Tip:** Student -> Family Man -> Retiree -> Monk.

**🚫 Scam Alert:** वानप्रस्थ में घर छोड़ते हैं लेकिन समाज से पूरी तरह नहीं कटते (सलाहकार रहते हैं), संन्यास में पूर्णतः कट जाते हैं।', 2, 0, 5, NULL, 'Match the Ashramas with their primary duties:', '**✅ Correct Logic:**
* **Brahmacharya:** Education till 25.
* **Grihastha:** Most important, as it supports the other three.
* **Vanaprastha:** Gradual detachment.
* **Sannyasa:** Total renunciation.

**💡 Exam Fact:** Manusmriti calls Grihastha the ''Eldest/Best'' as it is the backbone of society.

**🧠 Memory Tip:** Student -> Family Man -> Retiree -> Monk.

**🚫 Scam Alert:** In Vanaprastha one leaves home but not society fully (acts as advisor), in Sannyasa one cuts off completely.', 60, 'matching', '[{"id":"(1)","label":"ब्रह्मचर्य (Brahmacharya)","match":"विद्या अध्ययन और अनुशासन (Study and Discipline)","matchId":"(c)"},{"id":"(2)","label":"गृहस्थ (Grihastha)","match":"तीन ऋणों से मुक्ति और पुरुषार्थ सिद्धि (Repaying 3 debts and fulfilling Purusharthas)","matchId":"(a)"},{"id":"(3)","label":"वानप्रस्थ (Vanaprastha)","match":"समाज से अलगाव और वनों में चिंतन (Detachment and contemplation in forests)","matchId":"(d)"},{"id":"(4)","label":"संन्यास (Sannyasa)","match":"पूर्ण त्याग और मोक्ष की साधना (Total renunciation and pursuit of Moksha)","matchId":"(b)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2eff9b1a-8754-471f-9de7-381257f4fa4e', '491941d1-1508-44c2-9c41-bd862625df0e', 'किस आश्रम को ''सभी आश्रमों का आधार'' (Backbone of all Ashramas) कहा गया है?', '[{"id":"A","text":"संन्यास (Sannyasa)","text_en":"संन्यास (Sannyasa)"},{"id":"B","text":"गृहस्थ (Grihastha)","text_en":"गृहस्थ (Grihastha)"},{"id":"C","text":"ब्रह्मचर्य (Brahmacharya)","text_en":"ब्रह्मचर्य (Brahmacharya)"},{"id":"D","text":"वानप्रस्थ (Vanaprastha)","text_en":"वानप्रस्थ (Vanaprastha)"}]', '1', '**✅ Correct Logic:** जैसे सभी नदियाँ सागर में मिलती हैं, वैसे ही सभी आश्रम ''गृहस्थ'' पर निर्भर हैं। ब्रह्मचारी, वानप्रस्थी और संन्यासी भिक्षा/भोजन के लिए गृहस्थ पर ही आश्रित होते हैं। इसलिए इसे श्रेष्ठ माना गया है।

**💡 Exam Fact:** पंच महायज्ञ केवल गृहस्थ के लिए अनिवार्य थे।

**🧠 Memory Tip:** Grihastha = **G**iver (Feeds everyone).

**🚫 Scam Alert:** संन्यास को आध्यात्मिक रूप से ऊंचा माना जा सकता है, लेकिन ''आधार'' (Base/Support) गृहस्थ ही है।', 2, 0, 6, NULL, 'Which Ashrama is called the ''Backbone of all Ashramas''?', '**✅ Correct Logic:** Just as all rivers meet the ocean, all Ashramas depend on ''Grihastha''. Students, hermits, and monks depend on the householder for food/alms. Hence it is considered the best.

**💡 Exam Fact:** Pancha Mahayagyas were mandatory only for Grihasthas.

**🧠 Memory Tip:** Grihastha = **G**iver (Feeds everyone).

**🚫 Scam Alert:** Sannyasa might be spiritually highest, but the ''Base/Support'' is Grihastha.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('558b9ea0-b6da-45ce-9b78-06c840b6875c', '491941d1-1508-44c2-9c41-bd862625df0e', '''शूद्रों'' को किस रूप में सेवा करने का कर्तव्य सौंपा गया था?', '[{"id":"A","text":"वेदों का अध्ययन (Studying Vedas)","text_en":"वेदों का अध्ययन (Studying Vedas)"},{"id":"B","text":"युद्ध करना (Fighting war)","text_en":"युद्ध करना (Fighting war)"},{"id":"C","text":"तीनों उच्च वर्णों की सेवा करना (Serving the three upper varnas)","text_en":"तीनों उच्च वर्णों की सेवा करना (Serving the three upper varnas)"},{"id":"D","text":"व्यापार करना (Trading)","text_en":"व्यापार करना (Trading)"}]', '2', '**✅ Correct Logic:** धर्मशास्त्रों के अनुसार, शूद्र का मुख्य धर्म ''सेवा'' (Service) था। उन्हें समाज के पैरों (Feet) के रूप में देखा गया जो पूरे शरीर (समाज) का भार उठाते हैं।

**💡 Exam Fact:** बाद में ''सच्चिदानंद'' जैसे आंदोलनों और भक्ति काल ने शूद्रों को आध्यात्मिक अधिकार भी दिलाए।

**🧠 Memory Tip:** Feet = Support/Service.

**🚫 Scam Alert:** कृषि और पशुपालन (Agriculture) भी कभी-कभी शूद्रों का कार्य बताया गया, लेकिन प्राथमिक कर्तव्य ''सेवा'' था। (वैश्यों का मुख्य कार्य कृषि/व्यापार था)।', 2, 0, 7, NULL, 'What duty was assigned to the ''Shudras''?', '**✅ Correct Logic:** According to Dharmashastras, the main duty of a Shudra was ''Service''. They were seen as the feet carrying the weight of the social body.

**💡 Exam Fact:** Later Bhakti movements gave spiritual rights to Shudras.

**🧠 Memory Tip:** Feet = Support/Service.

**🚫 Scam Alert:** Agriculture is sometimes linked to Shudras, but the primary duty was Service. (Agriculture/Trade was Vaishya''s domain).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bd23e4b9-2f3a-48d5-98d7-41e35152115f', '491941d1-1508-44c2-9c41-bd862625df0e', 'कथन (A): वर्ण व्यवस्था शुरू में लचीली (Flexible) थी, लेकिन उत्तर वैदिक काल में यह कठोर (Rigid) हो गई।
कारण (R): उत्तर वैदिक काल में वर्ण का निर्धारण ''कर्म'' के बजाय ''जन्म'' से होने लगा।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic:** ऋग्वेद में एक ही परिवार में अलग-अलग पेशे वाले लोग होते थे (पिता वैद्य, पुत्र कवि)। लेकिन उत्तर वैदिक काल में जैसे-जैसे समाज जटिल हुआ, वर्ण ''जाति'' (Caste) में बदलने लगा और जन्म आधारित हो गया, जिससे कठोरता आई।

**💡 Exam Fact:** "मैं कवि हूँ, मेरे पिता वैद्य हैं..." - यह प्रसिद्ध कथन ऋग्वेद (9.112) का है।

**🧠 Memory Tip:** Early = Easy (Flexible). Later = Locked (Rigid).

**🚫 Scam Alert:** यह इतिहास का एक स्थापित सत्य है।', 2, 0, 8, NULL, 'Assertion (A): Varna system was initially flexible, but became rigid in Later Vedic period.
Reason (R): In Later Vedic period, Varna was determined by ''Birth'' instead of ''Karma''.
Select the correct option:', '**✅ Correct Logic:** In Rigveda, people of same family had different professions (Father doctor, son poet). But in Later Vedic times, Varna turned into ''Caste'' based on birth, leading to rigidity.

**💡 Exam Fact:** "I am a poet, my father is a physician..." - This famous quote is from Rigveda (9.112).

**🧠 Memory Tip:** Early = Easy (Flexible). Later = Locked (Rigid).

**🚫 Scam Alert:** This is an established historical fact.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d136e5de-4bf1-4bb4-86af-01fcf06926e3', '491941d1-1508-44c2-9c41-bd862625df0e', 'किस आश्रम में प्रवेश करने पर व्यक्ति ''परिव्राजक'' (Wanderer) कहलाता है?', '[{"id":"A","text":"वानप्रस्थ (Vanaprastha)","text_en":"वानप्रस्थ (Vanaprastha)"},{"id":"B","text":"संन्यास (Sannyasa)","text_en":"संन्यास (Sannyasa)"},{"id":"C","text":"ब्रह्मचर्य (Brahmacharya)","text_en":"ब्रह्मचर्य (Brahmacharya)"},{"id":"D","text":"गृहस्थ (Grihastha)","text_en":"गृहस्थ (Grihastha)"}]', '1', '**✅ Correct Logic:** ''परिव्राजक'' का अर्थ है ''चारों ओर घूमने वाला'' (बिना घर का)। यह संन्यास आश्रम की अवस्था है जहाँ व्यक्ति एक स्थान पर नहीं रुकता (वर्षावास को छोड़कर) ताकि उसे किसी स्थान से मोह न हो।

**💡 Exam Fact:** बुद्ध को भी ''परिव्राजक'' परंपरा का हिस्सा माना जाता है।

**🧠 Memory Tip:** Parivrajaka = **P**arikrama (Roaming around) = Sannyasi.

**🚫 Scam Alert:** वानप्रस्थ में व्यक्ति वन में ''स्थिर'' कुटिया बनाकर रहता है, संन्यासी ''घूमता'' रहता है।', 2, 0, 9, NULL, 'Entering which Ashrama does a person become a ''Parivrajaka'' (Wanderer)?', '**✅ Correct Logic:** ''Parivrajaka'' means ''Wanderer'' (Homeless). This is the state of Sannyasa where one doesn''t stay at one place (except rainy season) to avoid attachment.

**💡 Exam Fact:** Buddha is also considered part of the ''Parivrajaka'' tradition.

**🧠 Memory Tip:** Parivrajaka = **P**arikrama (Roaming around) = Sannyasi.

**🚫 Scam Alert:** In Vanaprastha one stays in a fixed hut in forest; Sannyasi keeps moving.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('84d8d1ec-d7b3-41da-a868-e975720099d0', '491941d1-1508-44c2-9c41-bd862625df0e', 'वर्णसंकर (Varna-sankara) की स्थिति कब उत्पन्न होती है?', '[{"id":"A","text":"जब वर्ण अपने कर्तव्यों का पालन करते हैं (When Varnas perform their duties)","text_en":"जब वर्ण अपने कर्तव्यों का पालन करते हैं (When Varnas perform their duties)"},{"id":"B","text":"जब विभिन्न वर्णों के बीच विवाह (अनुलोम/प्रतिलोम) होता है (When inter-marriage (Anuloma/Pratiloma) happens between different Varnas)","text_en":"जब विभिन्न वर्णों के बीच विवाह (अनुलोम/प्रतिलोम) होता है (When inter-marriage (Anuloma/Pratiloma) happens between different Varnas)"},{"id":"C","text":"जब सभी संन्यास ले लेते हैं (When everyone takes Sannyasa)","text_en":"जब सभी संन्यास ले लेते हैं (When everyone takes Sannyasa)"},{"id":"D","text":"जब राजा युद्ध जीतता है (When King wins war)","text_en":"जब राजा युद्ध जीतता है (When King wins war)"}]', '1', '**✅ Correct Logic:** धर्मशास्त्रों के अनुसार, जब अलग-अलग वर्णों के स्त्री-पुरुष विवाह करते हैं (विशेषकर निषिद्ध विवाह), तो उससे उत्पन्न संतान ''वर्णसंकर'' कहलाती है (जैसे चांडाल, निषाद)। गीता में अर्जुन इसे ''कुलनाश'' का कारण मानता है।

**💡 Exam Fact:** इससे अनेक उप-जातियों (Sub-castes) का जन्म हुआ।

**🧠 Memory Tip:** Sankara = Hybrid/Mixture.

**🚫 Scam Alert:** इसे सामाजिक व्यवस्था के लिए खतरा माना जाता था।', 2, 0, 10, NULL, 'When does the situation of ''Varna-sankara'' (Mixture of Varnas) arise?', '**✅ Correct Logic:** According to Dharmashastras, when man and woman of different Varnas marry (especially forbidden ones), the offspring is ''Varna-sankara'' (e.g., Chandala, Nishada). In Gita, Arjuna calls it the cause of family destruction.

**💡 Exam Fact:** This led to the birth of many Sub-castes.

**🧠 Memory Tip:** Sankara = Hybrid/Mixture.

**🚫 Scam Alert:** This was considered a threat to social order.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('99a35d9b-365b-4fb8-a3f5-1cf1a6a5d832', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'भारतीय दर्शन में ''पुरुषार्थ'' (Purushartha) की कुल संख्या कितनी मानी गई है?', '[{"id":"A","text":"3 (त्रिवर्ग)","text_en":"3 (त्रिवर्ग)"},{"id":"B","text":"4 (चतुष्टय)","text_en":"4 (चतुष्टय)"},{"id":"C","text":"5 (पंचम)","text_en":"5 (पंचम)"},{"id":"D","text":"2 (द्वय)","text_en":"2 (द्वय)"}]', '1', '**✅ Correct Logic:** पुरुषार्थ 4 हैं: धर्म, अर्थ, काम, मोक्ष। इन्हें ''पुरुषार्थ चतुष्टय'' कहा जाता है।

**💡 Exam Fact:** आरंभ में केवल 3 (त्रिवर्ग) थे, ''मोक्ष'' को बाद में जोड़ा गया जब उपनिषदिक चिंतन प्रबल हुआ।

**🧠 Memory Tip:** 4 Legs of Human Life = 4 Purusharthas.

**🚫 Scam Alert:** त्रिवर्ग (D-A-K) भी एक अवधारणा है, लेकिन ''कुल'' संख्या 4 ही मान्य है।', 2, 0, 1, NULL, 'What is the total number of ''Purusharthas'' in Indian philosophy?', '**✅ Correct Logic:** There are 4 Purusharthas: Dharma, Artha, Kama, Moksha. Called ''Purushartha Chatushtaya''.

**💡 Exam Fact:** Initially there were only 3 (Trivarga); ''Moksha'' was added later with Upanishadic thought.

**🧠 Memory Tip:** 4 Legs of Human Life = 4 Purusharthas.

**🚫 Scam Alert:** Trivarga (D-A-K) is also a concept, but ''Total'' number is 4.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6aa02067-6a6b-4d0f-ae7d-85a1799a86bb', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'पुरुषार्थों में किसे ''मूल'' (Root) या नियामक माना गया है जिसके बिना अन्य पुरुषार्थ अनियंत्रित हो सकते हैं?', '[{"id":"A","text":"अर्थ (Artha)","text_en":"अर्थ (Artha)"},{"id":"B","text":"काम (Kama)","text_en":"काम (Kama)"},{"id":"C","text":"धर्म (Dharma)","text_en":"धर्म (Dharma)"},{"id":"D","text":"मोक्ष (Moksha)","text_en":"मोक्ष (Moksha)"}]', '2', '**✅ Correct Logic:** ''धर्म'' (नैतिक कर्तव्य) वह नींव है जिस पर अर्थ और काम को साधा जाता है। धर्म के बिना ''अर्थ'' लालच बन जाता है और ''काम'' वासना। इसलिए धर्म प्रथम और नियामक है।

**💡 Exam Fact:** कौटिल्य भी कहते हैं: "सुखस्य मूलं धर्मः" (सुख का मूल धर्म है)।

**🧠 Memory Tip:** Dharma = **D**iscipline. Without discipline, money and desire destroy you.

**🚫 Scam Alert:** मोक्ष ''अंतिम'' लक्ष्य है, लेकिन जीवन जीने का ''आधार'' (Base) धर्म है।', 2, 0, 2, NULL, 'Which Purushartha is considered the ''Root'' or regulator without which other Purusharthas can become uncontrolled?', '**✅ Correct Logic:** ''Dharma'' (Moral Duty) is the foundation. Without Dharma, ''Artha'' becomes greed and ''Kama'' becomes lust. Hence Dharma is the first and regulator.

**💡 Exam Fact:** Kautilya says: "Sukhasya Moolam Dharmah" (Root of happiness is Dharma).

**🧠 Memory Tip:** Dharma = **D**iscipline. Without discipline, money and desire destroy you.

**🚫 Scam Alert:** Moksha is ''Final'' goal, but ''Base'' is Dharma.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a86c3787-29b8-45d4-9789-e40560889886', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'निम्नलिखित में से कौन ''त्रिवर्ग'' (Trivarga) का हिस्सा नहीं है?', '[{"id":"A","text":"धर्म (Dharma)","text_en":"धर्म (Dharma)"},{"id":"B","text":"अर्थ (Artha)","text_en":"अर्थ (Artha)"},{"id":"C","text":"काम (Kama)","text_en":"काम (Kama)"},{"id":"D","text":"मोक्ष (Moksha)","text_en":"मोक्ष (Moksha)"}]', '3', '**✅ Correct Logic:** ''त्रिवर्ग'' का संबंध सांसारिक जीवन (प्रवृत्ति मार्ग) से है। इसमें धर्म, अर्थ और काम आते हैं। ''मोक्ष'' निवृत्ति मार्ग (सांसारिक जीवन से मुक्ति) है, इसलिए यह त्रिवर्ग से अलग चौथा पुरुषार्थ है।

**💡 Exam Fact:** मनुस्मृति में त्रिवर्ग के संतुलन पर जोर दिया गया है।

**🧠 Memory Tip:** Trivarga = Worldly Trio (Duty, Money, Desire). Moksha = Exit.

**🚫 Scam Alert:** यह बहुत बार पूछा जाने वाला प्रश्न है। मोक्ष त्रिवर्ग में नहीं है।', 2, 0, 3, NULL, 'Which of the following is NOT a part of ''Trivarga''?', '**✅ Correct Logic:** ''Trivarga'' relates to worldly life (Pravritti). It includes Dharma, Artha, Kama. ''Moksha'' is Nivritti (Liberation), so it is the 4th, outside Trivarga.

**💡 Exam Fact:** Manusmriti emphasizes the balance of Trivarga.

**🧠 Memory Tip:** Trivarga = Worldly Trio (Duty, Money, Desire). Moksha = Exit.

**🚫 Scam Alert:** Most repeated question. Moksha is not in Trivarga.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('04884379-9ef4-43ab-bb89-343ff7dd9d3c', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'पुरुषार्थों और उनके अर्थ/उद्देश्य को सुमेलित करें (Match the Purusharthas with their meaning/objective):', '[{"id":"A","text":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)","text_en":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"}]', '0', '**✅ Correct Logic:**
* **धर्म:** सही आचरण (Righteousness)।
* **अर्थ:** जीवन जीने के साधन (Means)।
* **काम:** जीवन का आनंद (Pleasure)।
* **मोक्ष:** परम लक्ष्य (Ultimate Goal)।

**💡 Exam Fact:** वात्स्यायन ने ''कामसूत्र'' में काम को और कौटिल्य ने ''अर्थशास्त्र'' में अर्थ को प्रधानता दी है।

**🧠 Memory Tip:** D-A-K-M sequence.

**🚫 Scam Alert:** ''काम'' को केवल वासना (Sex) न समझें, यह कला, संगीत और सौंदर्य का आनंद भी है।', 2, 0, 5, NULL, 'Match the Purusharthas with their meaning/objective:', '**✅ Correct Logic:**
* **Dharma:** Righteousness.
* **Artha:** Means of living.
* **Kama:** Pleasure/Desire.
* **Moksha:** Ultimate Goal.

**💡 Exam Fact:** Vatsyayana prioritized Kama in Kamasutra, Kautilya prioritized Artha in Arthashastra.

**🧠 Memory Tip:** D-A-K-M sequence.

**🚫 Scam Alert:** Don''t limit ''Kama'' to just sex; it includes art, music, and aesthetic pleasure.', 60, 'matching', '[{"id":"(1)","label":"धर्म (Dharma)","match":"नैतिक मूल्य और कर्तव्य (Moral values and Duty)","matchId":"(c)"},{"id":"(2)","label":"अर्थ (Artha)","match":"भौतिक संसाधन और धन (Material resources and Wealth)","matchId":"(a)"},{"id":"(3)","label":"काम (Kama)","match":"इच्छाओं की पूर्ति और सौंदर्यानुभूति (Fulfillment of desires and Aesthetics)","matchId":"(d)"},{"id":"(4)","label":"मोक्ष (Moksha)","match":"जन्म-मरण के चक्र से मुक्ति (Liberation from cycle of birth-death)","matchId":"(b)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a694db06-fbcc-4f1f-b26c-8fc5fd0bfd1e', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'कौटिल्य ने अपने ''अर्थशास्त्र'' में किस पुरुषार्थ को सबसे प्रधान (Most Important) माना है?', '[{"id":"A","text":"धर्म (Dharma)","text_en":"धर्म (Dharma)"},{"id":"B","text":"अर्थ (Artha)","text_en":"अर्थ (Artha)"},{"id":"C","text":"काम (Kama)","text_en":"काम (Kama)"},{"id":"D","text":"मोक्ष (Moksha)","text_en":"मोक्ष (Moksha)"}]', '1', '**✅ Correct Logic:** कौटिल्य का मानना था कि "अर्थ ही प्रधान है (अर्थ एवं प्रधानः), क्योंकि धर्म और काम अर्थ पर ही निर्भर हैं।" बिना धन/संसाधन के न तो धर्म का पालन हो सकता है, न इच्छाओं की पूर्ति।

**💡 Exam Fact:** यह यथार्थवादी (Realistic) दृष्टिकोण है।

**🧠 Memory Tip:** Arthashastra writer will obviously vote for **Artha**.

**🚫 Scam Alert:** सामान्यतः धर्म प्रधान है, लेकिन ''कौटिल्य के अनुसार'' अर्थ प्रधान है।', 2, 0, 4, NULL, 'Which Purushartha did Kautilya consider the Most Important in his ''Arthashastra''?', '**✅ Correct Logic:** Kautilya believed "Artha is supreme (Artha eva pradhanah), because Dharma and Kama depend on Artha." Without resources, neither duty can be done nor desires fulfilled.

**💡 Exam Fact:** This is a Realistic approach.

**🧠 Memory Tip:** Arthashastra writer will obviously vote for **Artha**.

**🚫 Scam Alert:** Generally Dharma is supreme, but ''According to Kautilya'', Artha is supreme.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('99c08c62-9bfd-4bd5-bf14-8625cbae6f2a', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', '''परम पुरुषार्थ'' (Supreme Purushartha) किसे कहा जाता है?', '[{"id":"A","text":"धर्म (Dharma)","text_en":"धर्म (Dharma)"},{"id":"B","text":"अर्थ (Artha)","text_en":"अर्थ (Artha)"},{"id":"C","text":"काम (Kama)","text_en":"काम (Kama)"},{"id":"D","text":"मोक्ष (Moksha)","text_en":"मोक्ष (Moksha)"}]', '3', '**✅ Correct Logic:** ''मोक्ष'' (Moksha) को परम पुरुषार्थ या ''निःश्रेयस'' कहा जाता है क्योंकि यह जीवन का अंतिम लक्ष्य है जहाँ सभी दुख समाप्त हो जाते हैं। बाकी तीन ''साधन'' हैं, मोक्ष ''साध्य'' है।

**💡 Exam Fact:** उपनिषदों का पूरा जोर मोक्ष पर है।

**🧠 Memory Tip:** Moksha = **M**aximum (Highest).

**🚫 Scam Alert:** धर्म ''मूल'' है, मोक्ष ''शिखर'' (Supreme) है।', 2, 0, 6, NULL, 'Which is called the ''Supreme Purushartha'' (Parama Purushartha)?', '**✅ Correct Logic:** ''Moksha'' is called Supreme Purushartha or ''Nihshreyasa'' because it is the ultimate goal where all suffering ends. The other three are ''Means'', Moksha is the ''End''.

**💡 Exam Fact:** Upanishads focus entirely on Moksha.

**🧠 Memory Tip:** Moksha = **M**aximum (Highest).

**🚫 Scam Alert:** Dharma is ''Root'', Moksha is ''Peak'' (Supreme).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c90a39cf-19ab-4814-a7ee-5d3befe9d6d5', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'किस पुरुषार्थ का संबंध मुख्य रूप से ''गृहस्थ आश्रम'' से है?', '[{"id":"A","text":"केवल मोक्ष (Only Moksha)","text_en":"केवल मोक्ष (Only Moksha)"},{"id":"B","text":"केवल धर्म (Only Dharma)","text_en":"केवल धर्म (Only Dharma)"},{"id":"C","text":"अर्थ और काम (Artha and Kama)","text_en":"अर्थ और काम (Artha and Kama)"},{"id":"D","text":"उपर्युक्त में से कोई नहीं (None of the above)","text_en":"उपर्युक्त में से कोई नहीं (None of the above)"}]', '2', '**✅ Correct Logic:** वैसे तो धर्म सभी में है, लेकिन ''अर्थ'' (धन कमाना) और ''काम'' (संतानोत्पत्ति/सुख) का भोग केवल गृहस्थ आश्रम में ही वैध (Valid) है। अन्य आश्रमों में इनका निषेध है।

**💡 Exam Fact:** इसलिए गृहस्थ को ''कर्मभूमि'' कहा जाता है।

**🧠 Memory Tip:** Family man needs **Money** (Artha) and **Love** (Kama).

**🚫 Scam Alert:** गृहस्थ में धर्म भी है, लेकिन अर्थ-काम की विशिष्टता (Exclusivity) इसी आश्रम में है।', 2, 0, 7, NULL, 'Which Purushartha is mainly related to ''Grihastha Ashrama''?', '**✅ Correct Logic:** While Dharma is in all, ''Artha'' (earning wealth) and ''Kama'' (Procreation/Pleasure) are valid ONLY in Grihastha Ashrama. They are prohibited in others.

**💡 Exam Fact:** Hence Grihastha is called ''Karmabhumi''.

**🧠 Memory Tip:** Family man needs **Money** (Artha) and **Love** (Kama).

**🚫 Scam Alert:** Dharma is there too, but Artha-Kama are specific to this Ashrama.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b1e74ba0-d203-4c8f-8321-bf44d557acf9', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'कथन (A): पुरुषार्थ व्यवस्था भौतिकवाद और आध्यात्मिकता के बीच संतुलन बनाती है।
कारण (R): इसमें अर्थ और काम (भौतिक) को धर्म (नैतिक) और मोक्ष (आध्यात्मिक) के साथ रखा गया है।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic:** भारतीय संस्कृति न तो पूर्णत: भौतिकवादी (चार्वाक) है, न पूर्णतः त्यागवादी। पुरुषार्थ व्यवस्था में शरीर (अर्थ/काम) और आत्मा (धर्म/मोक्ष) दोनों की जरूरतों को स्वीकार किया गया है।

**💡 Exam Fact:** इसे ''समन्वयवादी संस्कृति'' (Synthetic Culture) कहते हैं।

**🧠 Memory Tip:** Balance of Body (Artha/Kama) and Soul (Moksha).

**🚫 Scam Alert:** दोनों सही हैं और R, A की सही व्याख्या है।', 2, 0, 8, NULL, 'Assertion (A): Purushartha system balances Materialism and Spirituality.
Reason (R): It places Artha and Kama (Material) along with Dharma (Moral) and Moksha (Spiritual).
Select the correct option:', '**✅ Correct Logic:** Indian culture is neither fully Materialistic (Charvaka) nor fully Renunciatory. Purushartha system accepts the needs of both Body (Artha/Kama) and Soul (Dharma/Moksha).

**💡 Exam Fact:** This is called ''Synthetic Culture''.

**🧠 Memory Tip:** Balance of Body (Artha/Kama) and Soul (Moksha).

**🚫 Scam Alert:** Both are true and R explains A correctly.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fe5b1bab-5f19-40fc-bcf1-ebbef6bddc8a', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', '''काम'' (Kama) का व्यापक अर्थ भारतीय संस्कृति में क्या है?', '[{"id":"A","text":"केवल यौन इच्छा (Only sexual desire)","text_en":"केवल यौन इच्छा (Only sexual desire)"},{"id":"B","text":"सभी प्रकार की इंद्रिय-जनित सुख और सौंदर्य बोध (All kinds of sensory pleasures and aesthetic sense)","text_en":"सभी प्रकार की इंद्रिय-जनित सुख और सौंदर्य बोध (All kinds of sensory pleasures and aesthetic sense)"},{"id":"C","text":"धन कमाने की इच्छा (Desire to earn money)","text_en":"धन कमाने की इच्छा (Desire to earn money)"},{"id":"D","text":"ईश्वर प्राप्ति की इच्छा (Desire to attain God)","text_en":"ईश्वर प्राप्ति की इच्छा (Desire to attain God)"}]', '1', '**✅ Correct Logic:** काम केवल संभोग नहीं है। यह पाँचों इंद्रियों (देखना, सुनना, चखना आदि) से प्राप्त होने वाला सुख, कला, साहित्य और भावनात्मक संतुष्टि है। यह सृजन (Creativity) की शक्ति है।

**💡 Exam Fact:** अथर्ववेद में काम को ''सृष्टि का प्रथम बीज'' कहा गया है।

**🧠 Memory Tip:** Kama = Passion/Desire for Beauty & Life.

**🚫 Scam Alert:** संकीर्ण अर्थ (Sex) से बचें, व्यापक अर्थ चुनें।', 2, 0, 9, NULL, 'What is the broader meaning of ''Kama'' in Indian culture?', '**✅ Correct Logic:** Kama is not just sex. It is the pleasure derived from all five senses (sight, sound, taste etc.), art, literature, and emotional satisfaction. It is the power of Creativity.

**💡 Exam Fact:** Atharvaveda calls Kama the ''Primal Seed of Creation''.

**🧠 Memory Tip:** Kama = Passion/Desire for Beauty & Life.

**🚫 Scam Alert:** Avoid the narrow meaning (Sex), choose the broader one.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e306927d-316a-4570-bcf3-61888316f132', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', '''धर्म'' (Dharma) शब्द किस धातु से बना है और इसका अर्थ क्या है?', '[{"id":"A","text":"धृ (Dhri) - धारण करना (To sustain/uphold)","text_en":"धृ (Dhri) - धारण करना (To sustain/uphold)"},{"id":"B","text":"धी (Dhi) - बुद्धि (Intellect)","text_en":"धी (Dhi) - बुद्धि (Intellect)"},{"id":"C","text":"धम् (Dham) - नियम (Rule)","text_en":"धम् (Dham) - नियम (Rule)"},{"id":"D","text":"धाम (Dham) - घर (Abode)","text_en":"धाम (Dham) - घर (Abode)"}]', '0', '**✅ Correct Logic:** धर्म ''धृ'' धातु से बना है: ''धार्यते इति धर्मः'' (जो धारण किया जाए या जो समाज को धारण करे)। यह केवल पूजा-पाठ नहीं, बल्कि वह नियम है जो ब्रह्मांड और समाज को बिखरने से रोकता है।

**💡 Exam Fact:** महाभारत में कहा गया है: "धर्मो रक्षति रक्षितः" (धर्म उसकी रक्षा करता है जो धर्म की रक्षा करता है)।

**🧠 Memory Tip:** Dhri -> Dharma -> Dharan (Hold/Sustain).

**🚫 Scam Alert:** धर्म = Religion (Western concept) नहीं है। धर्म = Duty/Law है।', 2, 0, 10, NULL, 'The word ''Dharma'' is derived from which root and what does it mean?', '**✅ Correct Logic:** Dharma comes from ''Dhri'': ''Dharyate iti Dharmah'' (That which is upheld or which sustains society). It is not just worship, but the law that prevents the universe/society from falling apart.

**💡 Exam Fact:** Mahabharata says: "Dharmo Rakshati Rakshitah".

**🧠 Memory Tip:** Dhri -> Dharma -> Dharan (Hold/Sustain).

**🚫 Scam Alert:** Dharma is not Religion. Dharma is Duty/Cosmic Law.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('29cedaf2-4085-41e9-be42-1a38185c133d', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'प्राचीन भारतीय परंपरा में मनुष्य जन्म से ही कितने ''ऋण'' (Debts) लेकर पैदा होता है?', '[{"id":"A","text":"2","text_en":"2"},{"id":"B","text":"3","text_en":"3"},{"id":"C","text":"4","text_en":"4"},{"id":"D","text":"5","text_en":"5"}]', '1', '**✅ Correct Logic:** मुख्य रूप से **3 ऋण** (ऋण-त्रय) माने गए हैं: 1. ऋषि ऋण, 2. पितृ ऋण, 3. देव ऋण। (शतपथ ब्राह्मण और तैत्तिरीय संहिता)।

**💡 Exam Fact:** कुछ ग्रंथों (जैसे महाभारत) में ''मनुष्य ऋण'' (Human Debt) को जोड़कर 4 माने गए हैं, लेकिन मानक संख्या 3 है।

**🧠 Memory Tip:** **3** Debts for **3** stages of life support.

**🚫 Scam Alert:** ''पंच महायज्ञ'' 5 हैं, लेकिन ''ऋण'' 3 हैं। कंफ्यूज न हों।', 2, 0, 1, NULL, 'According to ancient Indian tradition, a human is born with how many ''Rins'' (Debts)?', '**✅ Correct Logic:** Primarily **3 Rins** (Rina-traya) are considered: 1. Rishi Rin, 2. Pitra Rin, 3. Deva Rin. (Satapatha Brahmana).

**💡 Exam Fact:** Some texts add ''Manushya Rin'' making it 4, but standard is 3.

**🧠 Memory Tip:** **3** Debts for **3** stages of life support.

**🚫 Scam Alert:** ''Panch Mahayagya'' are 5, but ''Rins'' are 3. Don''t confuse.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4b0783e9-a351-498f-a9eb-56641d2a1d82', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', '''पितृ ऋण'' (Pitra Rin) से मुक्ति कैसे मिलती है?', '[{"id":"A","text":"यज्ञ करके (By performing Yajna)","text_en":"यज्ञ करके (By performing Yajna)"},{"id":"B","text":"वेदों का अध्ययन करके (By studying Vedas)","text_en":"वेदों का अध्ययन करके (By studying Vedas)"},{"id":"C","text":"संतान उत्पत्ति (विशेषकर पुत्र) करके (By procreating children, esp. son)","text_en":"संतान उत्पत्ति (विशेषकर पुत्र) करके (By procreating children, esp. son)"},{"id":"D","text":"दान देकर (By giving alms)","text_en":"दान देकर (By giving alms)"}]', '2', '**✅ Correct Logic:** हमारे पूर्वजों ने वंश परंपरा हम तक पहुंचाई। ''पितृ ऋण'' चुकाने के लिए व्यक्ति को विवाह कर ''संतान'' (प्रजा) उत्पन्न करनी होती है ताकि वंश चलता रहे।

**💡 Exam Fact:** ''पुत्र'' शब्द का अर्थ है - ''पुत्'' नामक नरक से त्राण (रक्षा) करने वाला।

**🧠 Memory Tip:** Pitra = Parents. Become a Parent to pay Parents.

**🚫 Scam Alert:** श्राद्ध करने से पितृ संतुष्ट होते हैं, लेकिन ''ऋण'' मुक्ति संतान उत्पत्ति से मानी गई है (तैत्तिरीय संहिता)।', 2, 0, 2, NULL, 'How does one get liberation from ''Pitra Rin'' (Debt to Ancestors)?', '**✅ Correct Logic:** Ancestors passed the lineage to us. To repay ''Pitra Rin'', one must marry and procreate (Praja) to continue the lineage.

**💡 Exam Fact:** ''Putra'' means one who saves from ''Put'' hell.

**🧠 Memory Tip:** Pitra = Parents. Become a Parent to pay Parents.

**🚫 Scam Alert:** Shraddha satisfies ancestors, but debt is cleared by procreation.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a6b7faa3-0507-46b1-8f53-6da0e2bc3766', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', '''स्वाध्याय'' (Self-study of Vedas) किस ऋण से मुक्ति का साधन है?', '[{"id":"A","text":"देव ऋण (Deva Rin)","text_en":"देव ऋण (Deva Rin)"},{"id":"B","text":"ऋषि ऋण (Rishi Rin)","text_en":"ऋषि ऋण (Rishi Rin)"},{"id":"C","text":"पितृ ऋण (Pitra Rin)","text_en":"पितृ ऋण (Pitra Rin)"},{"id":"D","text":"अतिथि ऋण (Atithi Rin)","text_en":"अतिथि ऋण (Atithi Rin)"}]', '1', '**✅ Correct Logic:** ऋषियों ने वेदों का ज्ञान सुरक्षित रखा और हमें दिया। वेदों का अध्ययन (स्वाध्याय) करना और ज्ञान को अगली पीढ़ी को देना ''ऋषि ऋण'' (या ब्रह्म ऋण) चुकाना है।

**💡 Exam Fact:** इसे ब्रह्मचर्य आश्रम में मुख्य रूप से चुकाया जाता है।

**🧠 Memory Tip:** Rishi gave Knowledge -> You study Knowledge.

**🚫 Scam Alert:** देव ऋण यज्ञ से चुकता है, ऋषि ऋण पढ़ाई से।', 2, 0, 3, NULL, '''Swadhyaya'' (Self-study of Vedas) is the means to get liberated from which Debt?', '**✅ Correct Logic:** Rishis preserved Vedic knowledge. Studying Vedas (Swadhyaya) and passing it to the next generation is repaying ''Rishi Rin'' (or Brahma Rin).

**💡 Exam Fact:** It is primarily repaid in Brahmacharya Ashrama.

**🧠 Memory Tip:** Rishi gave Knowledge -> You study Knowledge.

**🚫 Scam Alert:** Deva Rin is paid by Yajna, Rishi Rin by Study.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('00741d71-b4b4-4b47-b585-0a27ba20ce27', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'ऋण और उसे चुकाने के माध्यम को सुमेलित करें (Match the Debt with the means to repay it):', '[{"id":"A","text":"(1)-(c), (2)-(a), (3)-(b), (4)-(d)","text_en":"(1)-(c), (2)-(a), (3)-(b), (4)-(d)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(b), (3)-(a), (4)-(d)","text_en":"(1)-(c), (2)-(b), (3)-(a), (4)-(d)"},{"id":"D","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"}]', '0', '**✅ Correct Logic:**
* **देव:** देवताओं ने प्रकृति (वर्षा, धूप) दी -> बदले में यज्ञ (आहुति) दो।
* **ऋषि:** ज्ञान दिया -> पढ़ो।
* **पितृ:** जीवन दिया -> जीवन आगे बढ़ाओ।
* **मनुष्य:** समाज का सहयोग -> अतिथि सेवा।

**💡 Exam Fact:** यह ''Give and Take'' का ब्रह्मांडीय नियम है।

**🧠 Memory Tip:** Gods like Fire (Yajna). Sages like Books (Study). Fathers like Grandkids.

**🚫 Scam Alert:** यह जोड़ी बनाने के लिए सबसे आसान और महत्वपूर्ण टॉपिक है।', 2, 0, 5, NULL, 'Match the Debt with the means to repay it:', '**✅ Correct Logic:**
* **Deva:** Gave Nature (Rain/Sun) -> Give Yajna.
* **Rishi:** Gave Knowledge -> Study.
* **Pitra:** Gave Life -> Continue Life.
* **Manushya:** Social help -> Hospitality.

**💡 Exam Fact:** This is the Cosmic Law of ''Give and Take''.

**🧠 Memory Tip:** Gods like Fire (Yajna). Sages like Books (Study). Fathers like Grandkids.

**🚫 Scam Alert:** Easiest and most important topic for matching.', 60, 'matching', '[{"id":"(1)","label":"देव ऋण (Deva Rin)","match":"यज्ञ और अनुष्ठान (Yajna and Rituals)","matchId":"(c)"},{"id":"(2)","label":"ऋषि ऋण (Rishi Rin)","match":"वेदाध्ययन/स्वाध्याय (Study of Vedas)","matchId":"(a)"},{"id":"(3)","label":"पितृ ऋण (Pitra Rin)","match":"संतान उत्पत्ति (Procreation)","matchId":"(b)"},{"id":"(4)","label":"मनुष्य ऋण (Manushya Rin)","match":"अतिथि सत्कार/सेवा (Hospitality/Service)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1bc25b7e-53f8-4eea-9047-f3ab85165190', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'ऋण व्यवस्था का सामाजिक महत्व क्या था?', '[{"id":"A","text":"लोगों को डराना (To scare people)","text_en":"लोगों को डराना (To scare people)"},{"id":"B","text":"कृतज्ञता और जिम्मेदारी की भावना विकसित करना (To develop a sense of Gratitude and Responsibility)","text_en":"कृतज्ञता और जिम्मेदारी की भावना विकसित करना (To develop a sense of Gratitude and Responsibility)"},{"id":"C","text":"राजा का खजाना भरना (To fill King''s treasury)","text_en":"राजा का खजाना भरना (To fill King''s treasury)"},{"id":"D","text":"युद्ध के लिए सेना तैयार करना (To prepare army for war)","text_en":"युद्ध के लिए सेना तैयार करना (To prepare army for war)"}]', '1', '**✅ Correct Logic:** ऋण अवधारणा सिखाती है कि हम ''स्वयंभू'' (Self-made) नहीं हैं। हम पर प्रकृति, समाज, पूर्वजों और गुरुओं का कर्ज है। यह व्यक्ति को स्वार्थी होने से रोकती है और समाज के प्रति जिम्मेदार बनाती है।

**💡 Exam Fact:** यह ''अधिकार'' (Rights) के बजाय ''कर्तव्य'' (Duties) पर केंद्रित है।

**🧠 Memory Tip:** Payback society for what you got.

**🚫 Scam Alert:** यह आर्थिक कर्ज (Financial Debt) नहीं, नैतिक कर्ज (Moral Debt) है।', 2, 0, 4, NULL, 'What was the social significance of the Rin system?', '**✅ Correct Logic:** Rin concept teaches that we are not ''Self-made''. We owe debts to nature, society, ancestors, and teachers. It prevents selfishness and builds Responsibility.

**💡 Exam Fact:** It focuses on ''Duties'' rather than ''Rights''.

**🧠 Memory Tip:** Payback society for what you got.

**🚫 Scam Alert:** This is not Financial Debt, but Moral Debt.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('87b1bc7f-60e6-4ec2-9b90-86265bb0e9c1', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'तैत्तिरीय संहिता में कितने ऋणों का उल्लेख है?', '[{"id":"A","text":"3 (ऋषि, देव, पितृ)","text_en":"3 (ऋषि, देव, पितृ)"},{"id":"B","text":"2 (देव, पितृ)","text_en":"2 (देव, पितृ)"},{"id":"C","text":"4 (देव, पितृ, ऋषि, मनुष्य)","text_en":"4 (देव, पितृ, ऋषि, मनुष्य)"},{"id":"D","text":"5 (पंच ऋण)","text_en":"5 (पंच ऋण)"}]', '0', '**✅ Correct Logic:** तैत्तिरीय संहिता (6.3.10.5) स्पष्ट रूप से कहती है: "जायमानो वै ब्राह्मणस्त्रिभिर्ऋणवा जायते..." (जन्म लेते ही ब्राह्मण/मनुष्य तीन ऋणों से युक्त होता है)।

**💡 Exam Fact:** यह ऋण सिद्धांत का प्राचीनतम स्रोत है।

**🧠 Memory Tip:** Taittiriya starts with T -> **T**hree Rins.

**🚫 Scam Alert:** महाभारत में 4 हैं, लेकिन संहिता (वेद) में 3 ही हैं।', 2, 0, 6, NULL, 'How many Rins are mentioned in Taittiriya Samhita?', '**✅ Correct Logic:** Taittiriya Samhita explicitly states: "Jayamano vai Brahmanastribhirinava jayate..." (A person is born with three debts).

**💡 Exam Fact:** This is the oldest source of Rin theory.

**🧠 Memory Tip:** Taittiriya starts with T -> **T**hree Rins.

**🚫 Scam Alert:** Mahabharata has 4, but Samhita (Veda) has only 3.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dd866192-8750-4388-817c-a2f00242b246', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'किस आश्रम में रहकर ''तीनों ऋणों'' को चुकाना संभव है?', '[{"id":"A","text":"ब्रह्मचर्य (Brahmacharya)","text_en":"ब्रह्मचर्य (Brahmacharya)"},{"id":"B","text":"गृहस्थ (Grihastha)","text_en":"गृहस्थ (Grihastha)"},{"id":"C","text":"वानप्रस्थ (Vanaprastha)","text_en":"वानप्रस्थ (Vanaprastha)"},{"id":"D","text":"संन्यास (Sannyasa)","text_en":"संन्यास (Sannyasa)"}]', '1', '**✅ Correct Logic:** यद्यपि ऋषि ऋण ब्रह्मचर्य में शुरू होता है, लेकिन देव ऋण (यज्ञ) और पितृ ऋण (संतान) केवल गृहस्थ आश्रम में ही संभव हैं। इसलिए गृहस्थ ही तीनों ऋणों से पूर्ण मुक्ति दिलाता है।

**💡 Exam Fact:** बिना ऋण चुकाए संन्यास लेना निषिद्ध (Prohibited) था (मनुस्मृति)।

**🧠 Memory Tip:** Only a Family Man can do Yajna + Have Kids + Study.

**🚫 Scam Alert:** ब्रह्मचारी केवल ऋषि ऋण चुकाता है, बाकी दो नहीं।', 2, 0, 7, NULL, 'In which Ashrama is it possible to repay ''All Three Debts''?', '**✅ Correct Logic:** Although Rishi Rin starts in Brahmacharya, Deva Rin (Yajna) and Pitra Rin (Children) are possible ONLY in Grihastha. Thus, only Grihastha enables full repayment.

**💡 Exam Fact:** Taking Sannyasa without repaying debts was prohibited (Manusmriti).

**🧠 Memory Tip:** Only a Family Man can do Yajna + Have Kids + Study.

**🚫 Scam Alert:** Brahmachari repays only Rishi Rin, not the other two.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dd6f0c05-d1c3-4801-bb63-8a49fb5c0099', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'कथन (A): ''अनृणी'' (ऋण मुक्त) होना भारतीय जीवन का लक्ष्य था।
कारण (R): ऋणों को चुकाए बिना मोक्ष की प्राप्ति संभव नहीं मानी जाती थी।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic:** मनुस्मृति कहती है कि जो व्यक्ति ऋण चुकाए बिना मोक्ष का प्रयास करता है, वह नरक में जाता है (पतन होता है)। इसलिए ''अनृणी'' होना मोक्ष की पूर्व-शर्त (Pre-condition) है।

**💡 Exam Fact:** कालिदास के ''रघुवंश'' में भी अनृणी होने का उल्लेख है।

**🧠 Memory Tip:** No Dues Certificate is needed for Moksha entry.

**🚫 Scam Alert:** दोनों सही हैं और कारण स्पष्ट है।', 2, 0, 8, NULL, 'Assertion (A): Becoming ''Anrini'' (Debt-free) was a goal of Indian life.
Reason (R): Attainment of Moksha was not considered possible without repaying debts.
Select the correct option:', '**✅ Correct Logic:** Manusmriti says one who tries for Moksha without repaying debts falls down (goes to hell). Being ''Anrini'' is a pre-condition for Moksha.

**💡 Exam Fact:** Kalidasa''s ''Raghuvansha'' also mentions being Anrini.

**🧠 Memory Tip:** No Dues Certificate is needed for Moksha entry.

**🚫 Scam Alert:** Both are true and Reason is clear.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3abd6a15-db2d-4b63-a8bc-3770ae8d8c89', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', '''देव ऋण'' चुकाने के लिए कौन सा कार्य आवश्यक है?', '[{"id":"A","text":"यज्ञ करना (Performing Yajna)","text_en":"यज्ञ करना (Performing Yajna)"},{"id":"B","text":"तीर्थयात्रा करना (Pilgrimage)","text_en":"तीर्थयात्रा करना (Pilgrimage)"},{"id":"C","text":"मंदिर बनवाना (Building Temple)","text_en":"मंदिर बनवाना (Building Temple)"},{"id":"D","text":"उपवास रखना (Fasting)","text_en":"उपवास रखना (Fasting)"}]', '0', '**✅ Correct Logic:** देवताओं का भोजन ''हवि'' (आहुति) है जो यज्ञ के माध्यम से उन तक पहुँचता है। यज्ञ द्वारा देवताओं को पुष्टि मिलती है और वे बदले में वर्षा/समृद्धि देते हैं।

**💡 Exam Fact:** गीता (3.11): "परस्परं भावयन्तः श्रेयः परमवाप्स्यथ" (एक दूसरे को उन्नत करते हुए कल्याण प्राप्त करो)।

**🧠 Memory Tip:** Feed the Gods with Fire (Yajna).

**🚫 Scam Alert:** मंदिर और तीर्थ बाद की अवधारणाएं (पौराणिक) हैं। वैदिक ''ऋण'' यज्ञ से जुड़ा है।', 2, 0, 9, NULL, 'Which action is necessary to repay ''Deva Rin''?', '**✅ Correct Logic:** Gods'' food is ''Havi'' (Oblation) offered via Yajna. Yajna nourishes Gods, and they give rain/prosperity in return.

**💡 Exam Fact:** Gita (3.11): "Parasparam bhavayantah..." (Cherishing one another, attain the highest good).

**🧠 Memory Tip:** Feed the Gods with Fire (Yajna).

**🚫 Scam Alert:** Temples/Pilgrimage are later (Puranic). Vedic ''Rin'' is linked to Yajna.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a2705658-1865-465d-99d7-ca28067735b4', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'किस ग्रंथ में ''चौथा ऋण'' (मनुष्य ऋण) जोड़ा गया है?', '[{"id":"A","text":"शतपथ ब्राह्मण (Satapatha Brahmana)","text_en":"शतपथ ब्राह्मण (Satapatha Brahmana)"},{"id":"B","text":"तैत्तिरीय संहिता (Taittiriya Samhita)","text_en":"तैत्तिरीय संहिता (Taittiriya Samhita)"},{"id":"C","text":"महाभारत (Mahabharata)","text_en":"महाभारत (Mahabharata)"},{"id":"D","text":"ऋग्वेद (Rigveda)","text_en":"ऋग्वेद (Rigveda)"}]', '0', '**✅ Correct Logic:** शतपथ ब्राह्मण में 4 ऋणों का उल्लेख मिलता है: देव, पितृ, ऋषि और ''मनुष्य''। मनुष्य ऋण का अर्थ है साथी मनुष्यों के प्रति दया और सहायता (अतिथि सत्कार)।

**💡 Exam Fact:** तैत्तिरीय में 3 हैं, शतपथ में 4 का विस्तार है।

**🧠 Memory Tip:** Satapatha = Big Book = More Rins (4).

**🚫 Scam Alert:** महाभारत में भी है, लेकिन शतपथ (ब्राह्मण साहित्य) प्राथमिक स्रोत है जहाँ चौथा जोड़ा गया।', 2, 0, 10, NULL, 'In which text is the ''Fourth Debt'' (Manushya Rin) added?', '**✅ Correct Logic:** Satapatha Brahmana mentions 4 Rins: Deva, Pitra, Rishi, and ''Manushya''. Manushya Rin means kindness and help to fellow humans (Hospitality).

**💡 Exam Fact:** Taittiriya has 3, Satapatha expands to 4.

**🧠 Memory Tip:** Satapatha = Big Book = More Rins (4).

**🚫 Scam Alert:** Mahabharata also has it, but Satapatha is the primary source for the addition.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('81881e6c-26c8-4f0d-a035-bdd7f98ac674', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'गौतम धर्मसूत्र के अनुसार संस्कारों की कुल संख्या कितनी मानी गई है?', '[{"id":"A","text":"16","text_en":"16"},{"id":"B","text":"40","text_en":"40"},{"id":"C","text":"12","text_en":"12"},{"id":"D","text":"8","text_en":"8"}]', '1', '**✅ Correct Logic:** गौतम धर्मसूत्र (प्राचीनतम धर्मसूत्र) में संस्कारों की संख्या **40** बताई गई है, जिसमें महायज्ञ और आत्मगुण भी शामिल हैं। बाद में स्मृतियों (व्यास, मनु) में इसे घटाकर **16** (षोडश संस्कार) कर दिया गया जो प्रचलित है।

**💡 Exam Fact:** वर्तमान में 16 संस्कार मान्य हैं, लेकिन गौतम ने 40 बताए थे।

**🧠 Memory Tip:** Gautama (Oldest) = Maximum (40). Now = Sweet 16.

**🚫 Scam Alert:** यदि पूछे ''प्रचलित'' (Standard) तो 16। यदि पूछे ''गौतम के अनुसार'' तो 40।', 2, 0, 1, NULL, 'According to Gautama Dharmasutra, what is the total number of Sanskaras?', '**✅ Correct Logic:** Gautama Dharmasutra (Oldest) lists **40** Sanskaras, including sacrifices and moral virtues. Later Smritis reduced it to **16** (Shodasha Sanskara) which is standard now.

**💡 Exam Fact:** Currently 16 are followed, but Gautama listed 40.

**🧠 Memory Tip:** Gautama (Oldest) = Maximum (40). Now = Sweet 16.

**🚫 Scam Alert:** If asked ''Standard'', it''s 16. If ''According to Gautama'', it''s 40.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d2147621-83bb-4d7e-8c4b-cf59341388dc', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'गर्भावस्था के दौरान बच्चे के मानसिक विकास और अमंगल से रक्षा के लिए कौन सा संस्कार किया जाता है?', '[{"id":"A","text":"गर्भाधान (Garbhadhana)","text_en":"गर्भाधान (Garbhadhana)"},{"id":"B","text":"पुंसवन (Pumsavana)","text_en":"पुंसवन (Pumsavana)"},{"id":"C","text":"सीमंतोन्नयन (Simantonnayana)","text_en":"सीमंतोन्नयन (Simantonnayana)"},{"id":"D","text":"जातकर्म (Jatakarma)","text_en":"जातकर्म (Jatakarma)"}]', '2', '**✅ Correct Logic:** ''सीमंतोन्नयन'' (Parting of hair) संस्कार गर्भावस्था के चौथे से आठवें महीने में होता है। इसमें पति पत्नी के बाल संवारता है ताकि वह खुश रहे, जिससे गर्भस्थ शिशु का मानसिक विकास अच्छा हो।

**💡 Exam Fact:** पुंसवन (Pumsavana) पुत्र प्राप्ति की कामना के लिए होता है।

**🧠 Memory Tip:** Simanta = Head/Mind -> Mental development.

**🚫 Scam Alert:** गर्भाधान गर्भ ठहरने के लिए है, सीमंतोन्नयन ''दौरान'' (During) रक्षा के लिए है।', 2, 0, 2, NULL, 'Which Sanskara is performed during pregnancy for the mental development of the child and protection from evil?', '**✅ Correct Logic:** ''Simantonnayana'' (Parting of hair) is done in 4th-8th month. Husband parts wife''s hair to keep her happy, ensuring good mental development of the fetus.

**💡 Exam Fact:** Pumsavana is for desiring a male child.

**🧠 Memory Tip:** Simanta = Head/Mind -> Mental development.

**🚫 Scam Alert:** Garbhadhana is for conception; Simantonnayana is for protection ''during'' pregnancy.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('20aa41a9-652f-4d27-bd02-02cb85bbe85a', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'किस संस्कार को ''द्विजत्व'' (Second Birth) का द्वार माना जाता है?', '[{"id":"A","text":"विद्यारंभ (Vidyarambha)","text_en":"विद्यारंभ (Vidyarambha)"},{"id":"B","text":"उपनयन (Upanayana)","text_en":"उपनयन (Upanayana)"},{"id":"C","text":"वेदारंभ (Vedarambha)","text_en":"वेदारंभ (Vedarambha)"},{"id":"D","text":"समावर्तन (Samavartana)","text_en":"समावर्तन (Samavartana)"}]', '1', '**✅ Correct Logic:** ''उपनयन'' (यज्ञोपवीत/जनेऊ) संस्कार से बालक गुरु के पास जाता है। इसे आध्यात्मिक जन्म माना जाता है। यहीं से वह ''द्विज'' बनता है और शिक्षा का अधिकारी होता है।

**💡 Exam Fact:** ''उप+नयन'' का अर्थ है ''(गुरु के) पास ले जाना''।

**🧠 Memory Tip:** Upa-Nayana = New Eyes (Knowledge) = Second Birth.

**🚫 Scam Alert:** विद्यारंभ (अक्षर ज्ञान) 5 साल में होता है, लेकिन ''द्विज'' उपनयन (8-12 साल) से बनते हैं।', 2, 0, 3, NULL, 'Which Sanskara is considered the gateway to ''Dwijatva'' (Second Birth)?', '**✅ Correct Logic:** ''Upanayana'' (Sacred Thread) marks the entry to Guru''s house. It is the spiritual birth. Here one becomes ''Dwija'' and eligible for education.

**💡 Exam Fact:** ''Upa+Nayana'' means ''Leading near (Guru)''.

**🧠 Memory Tip:** Upa-Nayana = New Eyes (Knowledge) = Second Birth.

**🚫 Scam Alert:** Vidyarambha is alphabet learning (age 5), but ''Dwija'' status comes from Upanayana.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('236eb6f8-e969-41e2-b952-4cad0fefb526', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'संस्कारों और उनके सही क्रम/उद्देश्य को सुमेलित करें (Match the Sanskaras with their correct order/purpose):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)","text_en":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)"},{"id":"D","text":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)","text_en":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)"}]', '0', '**✅ Correct Logic:**
* **जातकर्म:** नाल काटने से पहले। मेधा (बुद्धि) जनन के लिए।
* **नामकरण:** पहचान के लिए।
* **निष्क्रमण:** प्रकृति (सूर्य/चंद्र) से परिचय।
* **अन्नप्राशन:** शारीरिक वृद्धि के लिए ठोस आहार।

**💡 Exam Fact:** निष्क्रमण चौथे महीने में होता है।

**🧠 Memory Tip:** Born (Jata) -> Name -> Go Out (Nishkraman) -> Eat Food (Anna).

**🚫 Scam Alert:** क्रम (Sequence) याद रखें: J-N-N-A.', 2, 0, 5, NULL, 'Match the Sanskaras with their correct order/purpose:', '**✅ Correct Logic:**
* **Jatakarma:** Before cutting umbilical cord. For intelligence.
* **Namakarana:** Identity.
* **Nishkramana:** Intro to nature (Sun/Moon).
* **Annaprashana:** Solid food for growth.

**💡 Exam Fact:** Nishkramana is in 4th month.

**🧠 Memory Tip:** Born (Jata) -> Name -> Go Out (Nishkraman) -> Eat Food (Anna).

**🚫 Scam Alert:** Remember sequence: J-N-N-A.', 60, 'matching', '[{"id":"(1)","label":"जातकर्म (Jatakarma)","match":"जन्म के तुरंत बाद, पिता द्वारा शहद-घी चटाना (Immediately after birth, father feeds honey-ghee)","matchId":"(b)"},{"id":"(2)","label":"नामकरण (Namakarana)","match":"जन्म के 10वें/12वें दिन नाम रखना (Naming on 10th/12th day)","matchId":"(a)"},{"id":"(3)","label":"निष्क्रमण (Nishkramana)","match":"पहली बार घर से बाहर निकालना/सूर्य दर्शन (First outing/Sun gazing)","matchId":"(d)"},{"id":"(4)","label":"अन्नप्राशन (Annaprashana)","match":"6 माह की आयु में पहली बार अन्न खिलाना (First feeding of solid food at 6 months)","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('43ae185a-4a7d-48b0-ae8f-b26b72d36d52', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'शिक्षा समाप्ति पर गुरु के घर से लौटते समय कौन सा संस्कार किया जाता था?', '[{"id":"A","text":"केशांत (Keshanta)","text_en":"केशांत (Keshanta)"},{"id":"B","text":"समावर्तन (Samavartana)","text_en":"समावर्तन (Samavartana)"},{"id":"C","text":"वेदारंभ (Vedarambha)","text_en":"वेदारंभ (Vedarambha)"},{"id":"D","text":"विवाह (Vivaha)","text_en":"विवाह (Vivaha)"}]', '1', '**✅ Correct Logic:** ''समावर्तन'' का अर्थ है ''लौटना'' (Returning). यह आधुनिक ''दीक्षांत समारोह'' (Convocation) जैसा था। इसके बाद ब्रह्मचारी ''स्नातक'' कहलाता था और गृहस्थ आश्रम में प्रवेश करता था।

**💡 Exam Fact:** इसमें ''स्नान'' (Ceremonial Bath) मुख्य था, इसलिए उसे ''स्नातक'' कहा जाता था।

**🧠 Memory Tip:** Samavartana = **S**amapti (End of study).

**🚫 Scam Alert:** केशांत (गोदान) 16 साल में होता था (दाढ़ी मूछ बनाना), लेकिन विदाई संस्कार ''समावर्तन'' है।', 2, 0, 4, NULL, 'Which Sanskara was performed while returning from Guru''s house after completion of education?', '**✅ Correct Logic:** ''Samavartana'' means ''Returning''. It was like modern ''Convocation''. After this, the student was called ''Snataka'' and entered Grihastha Ashrama.

**💡 Exam Fact:** ''Ceremonial Bath'' was key, hence the term ''Snataka'' (Graduate).

**🧠 Memory Tip:** Samavartana = **S**amapti (End of study).

**🚫 Scam Alert:** Keshanta (Godana) was shaving at 16, but the farewell ceremony is ''Samavartana''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1d9be508-25d3-4a0d-8bbe-96cdab37ce17', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', '16 संस्कारों में ''प्रथम'' और ''अंतिम'' संस्कार कौन से हैं?', '[{"id":"A","text":"जातकर्म और अंत्येष्टि (Jatakarma and Antyeshti)","text_en":"जातकर्म और अंत्येष्टि (Jatakarma and Antyeshti)"},{"id":"B","text":"गर्भाधान और अंत्येष्टि (Garbhadhana and Antyeshti)","text_en":"गर्भाधान और अंत्येष्टि (Garbhadhana and Antyeshti)"},{"id":"C","text":"नामकरण और समावर्तन (Namakarana and Samavartana)","text_en":"नामकरण और समावर्तन (Namakarana and Samavartana)"},{"id":"D","text":"गर्भाधान और विवाह (Garbhadhana and Vivaha)","text_en":"गर्भाधान और विवाह (Garbhadhana and Vivaha)"}]', '1', '**✅ Correct Logic:** संस्कार जन्म से पहले शुरू होते हैं और मृत्यु के बाद तक चलते हैं।
* **प्रथम:** गर्भाधान (Conception)।
* **अंतिम:** अंत्येष्टि (Funeral Rite).

**💡 Exam Fact:** अंत्येष्टि को ''दाह संस्कार'' या ''और्ध्वदैहिक'' भी कहते हैं।

**🧠 Memory Tip:** From Womb (Garbha) to Tomb (Antyeshti).

**🚫 Scam Alert:** जातकर्म जन्म के बाद पहला है, लेकिन संस्कारों की सूची गर्भाधान (Conception) से शुरू होती है।', 2, 0, 6, NULL, 'Which are the ''First'' and ''Last'' Sanskaras among the 16 Sanskaras?', '**✅ Correct Logic:** Sanskaras start before birth and continue after death.
* **First:** Garbhadhana (Conception).
* **Last:** Antyeshti (Funeral Rite).

**💡 Exam Fact:** Antyeshti is also called ''Dah Sanskara''.

**🧠 Memory Tip:** From Womb (Garbha) to Tomb (Antyeshti).

**🚫 Scam Alert:** Jatakarma is first *after birth*, but the list starts with Garbhadhana.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('eac93726-8780-4901-9d4f-a56bad5555ef', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', '''केशांत'' (Keshanta) संस्कार को और किस नाम से जाना जाता था, जिसमें पहली बार दाढ़ी-मूंछ मुंडवाई जाती थी?', '[{"id":"A","text":"गोदान (Godana)","text_en":"गोदान (Godana)"},{"id":"B","text":"चूडाकर्म (Chudakarma)","text_en":"चूडाकर्म (Chudakarma)"},{"id":"C","text":"कर्णवेध (Karnavedha)","text_en":"कर्णवेध (Karnavedha)"},{"id":"D","text":"उपनयन (Upanayana)","text_en":"उपनयन (Upanayana)"}]', '0', '**✅ Correct Logic:** ''केशांत'' (16 वर्ष की आयु में) में ब्रह्मचारी पहली बार क्षौर कर्म (shaving) करवाता था और गुरु को ''गाय'' (Go) दान करता था। इसलिए इसे ''गोदान'' संस्कार भी कहते हैं।

**💡 Exam Fact:** यह ब्रह्मचर्य के अंत का सूचक था।

**🧠 Memory Tip:** Keshanta = Kesh (Hair) End. Give **Go** (Cow) -> Godana.

**🚫 Scam Alert:** चूडाकर्म (Mundan) बचपन (1-3 वर्ष) में सिर मुंडाना है। केशांत (16 वर्ष) में दाढ़ी बनाना है।', 2, 0, 7, NULL, 'By what other name was ''Keshanta'' Sanskara known, in which the beard and moustache were shaved for the first time?', '**✅ Correct Logic:** In ''Keshanta'' (at age 16), the student shaved for the first time and gifted a ''Cow'' (Go) to the Guru. Hence it is also called ''Godana''.

**💡 Exam Fact:** This marked the end of adolescence.

**🧠 Memory Tip:** Keshanta = Kesh (Hair) End. Give **Go** (Cow) -> Godana.

**🚫 Scam Alert:** Chudakarma (Mundan) is head shaving in childhood (1-3 yrs). Keshanta is beard shaving at 16.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4c65314d-6d5b-45d1-a686-eebf1a9a3a0b', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'प्राचीन काल में ''कर्णवेध'' (Karnavedha) संस्कार का मुख्य उद्देश्य क्या था?', '[{"id":"A","text":"केवल आभूषण पहनना (Wearing ornaments only)","text_en":"केवल आभूषण पहनना (Wearing ornaments only)"},{"id":"B","text":"स्वास्थ्य और व्याधि रक्षा (Health and protection from diseases)","text_en":"स्वास्थ्य और व्याधि रक्षा (Health and protection from diseases)"},{"id":"C","text":"जाति की पहचान (Caste identity)","text_en":"जाति की पहचान (Caste identity)"},{"id":"D","text":"सजा देना (Punishment)","text_en":"सजा देना (Punishment)"}]', '1', '**✅ Correct Logic:** सुश्रुत संहिता के अनुसार, कान छेदने (कर्णवेध) से ''आंत्र वृद्धि'' (Hernia) और ''अण्डकोष'' की बीमारियों से रक्षा होती है। यह एक्यूपंक्चर जैसा चिकित्सीय संस्कार था।

**💡 Exam Fact:** यह सामान्यतः 3 से 5 वर्ष की आयु में होता था।

**🧠 Memory Tip:** Piercing for Health (Acupuncture point).

**🚫 Scam Alert:** यह केवल फैशन (आभूषण) के लिए नहीं था, इसका वैज्ञानिक/स्वास्थ्य आधार था।', 2, 0, 8, NULL, 'What was the main purpose of ''Karnavedha'' (Ear piercing) Sanskara in ancient times?', '**✅ Correct Logic:** According to Sushruta Samhita, Karnavedha prevents ''Hernia'' and hydrocele. It was a therapeutic rite like Acupuncture.

**💡 Exam Fact:** Usually done between 3 to 5 years.

**🧠 Memory Tip:** Piercing for Health (Acupuncture point).

**🚫 Scam Alert:** It wasn''t just for fashion (ornaments), it had a medical basis.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f18de201-527d-4e23-917d-126486ce2602', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'विवाह संस्कार में ''पाणिग्रहण'' (Panigrahana) का क्या अर्थ है?', '[{"id":"A","text":"अग्नि के फेरे लेना (Circling the fire)","text_en":"अग्नि के फेरे लेना (Circling the fire)"},{"id":"B","text":"वर द्वारा वधू का हाथ थामना (Groom holding the Bride''s hand)","text_en":"वर द्वारा वधू का हाथ थामना (Groom holding the Bride''s hand)"},{"id":"C","text":"सिंदूर लगाना (Applying Vermilion)","text_en":"सिंदूर लगाना (Applying Vermilion)"},{"id":"D","text":"मंगलसूत्र पहनाना (Tying Mangalsutra)","text_en":"मंगलसूत्र पहनाना (Tying Mangalsutra)"}]', '1', '**✅ Correct Logic:** ''पाणि'' (हाथ) + ''ग्रहण'' (पकड़ना)। इसमें वर, वधू का हाथ पकड़कर जीवन भर साथ निभाने की प्रतिज्ञा करता है। यह विवाह का एक अत्यंत महत्वपूर्ण चरण है।

**💡 Exam Fact:** ''सप्तपदी'' (सात फेरे) विवाह का कानूनी रूप से पूर्ण होने का सूचक है।

**🧠 Memory Tip:** Pani = Hand. Grahan = Hold.

**🚫 Scam Alert:** फेरे ''सप्तपदी'' हैं। पाणिग्रहण हाथ पकड़ना है।', 2, 0, 9, NULL, 'What is the meaning of ''Panigrahana'' in Vivaha Sanskara?', '**✅ Correct Logic:** ''Pani'' (Hand) + ''Grahana'' (Holding). The groom holds the bride''s hand taking a vow of lifelong companionship. It is a crucial step.

**💡 Exam Fact:** ''Saptapadi'' (7 steps) marks the legal completion of marriage.

**🧠 Memory Tip:** Pani = Hand. Grahan = Hold.

**🚫 Scam Alert:** Circling is ''Saptapadi''. Panigrahana is holding hands.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2fdee784-d5ae-4c3d-8018-baecb8abe456', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'संस्कारों का मुख्य मनोवैज्ञानिक उद्देश्य (Psychological Purpose) क्या था?', '[{"id":"A","text":"धन खर्च करना (Spending money)","text_en":"धन खर्च करना (Spending money)"},{"id":"B","text":"व्यक्तित्व का परिष्करण और पवित्रता (Refinement and Purification of Personality)","text_en":"व्यक्तित्व का परिष्करण और पवित्रता (Refinement and Purification of Personality)"},{"id":"C","text":"भीड़ इकट्ठा करना (Gathering crowd)","text_en":"भीड़ इकट्ठा करना (Gathering crowd)"},{"id":"D","text":"अंधविश्वास फैलाना (Spreading superstition)","text_en":"अंधविश्वास फैलाना (Spreading superstition)"}]', '1', '**✅ Correct Logic:** ''संस्कार'' का अर्थ है ''शुद्धिकरण'' (Purification)। इसका उद्देश्य व्यक्ति के जीवन के हर मोड़ (Transition) पर उसे मानसिक रूप से तैयार करना और उसके व्यक्तित्व को ''गुणी'' (Refined) बनाना था। जैसे कच्चा लोहा संस्कारित होकर इस्पात बनता है।

**💡 Exam Fact:** कालिदास ने शकुंतला के लिए कहा था: "संस्कारवती कन्या" (Refined/Cultured girl)।

**🧠 Memory Tip:** Sanskara = Polish/Refine the Soul.

**🚫 Scam Alert:** यह केवल रस्म नहीं, बल्कि व्यक्तित्व विकास (Personality Development) का प्राचीन तरीका था।', 2, 0, 10, NULL, 'What was the main Psychological Purpose of Sanskaras?', '**✅ Correct Logic:** ''Sanskara'' means ''Purification''. Its aim was to mentally prepare a person at every transition of life and Refine the personality. Like raw iron becomes steel after processing.

**💡 Exam Fact:** Kalidasa referred to Shakuntala as "Sanskaravati Kanya".

**🧠 Memory Tip:** Sanskara = Polish/Refine the Soul.

**🚫 Scam Alert:** Not just a ritual, but ancient Personality Development.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('66a78014-93e9-4d6f-b742-d647b60edde2', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'मध्य प्रदेश में ''घोड़ाडोंगरी'' (बैतूल) का जंगल सत्याग्रह किस वर्ष हुआ था और इसका नेतृत्व किसने किया था?', '[{"id":"A","text":"1930; गंजन सिंह कोरकू","text_en":"1930; गंजन सिंह कोरकू"},{"id":"B","text":"1923; माखनलाल चतुर्वेदी","text_en":"1923; माखनलाल चतुर्वेदी"},{"id":"C","text":"1931; सेठ गोविंद दास","text_en":"1931; सेठ गोविंद दास"},{"id":"D","text":"1942; बिरसा मुंडा","text_en":"1942; बिरसा मुंडा"}]', '0', '✅ **Correct Logic**: 1930 में सविनय अवज्ञा आंदोलन के दौरान बैतूल के घोड़ाडोंगरी में आदिवासियों ने गंजन सिंह कोरकू के नेतृत्व में जंगल सत्याग्रह किया था।
💡 **Exam Fact**: इसी तरह का सत्याग्रह सिवनी में ''दुर्गा शंकर मेहता'' के नेतृत्व में हुआ था।
🧠 **Memory Tip**: ''G'' for Ghoradongri and ''G'' for Ganjan Singh.
🚫 **Scam Alert**: माखनलाल चतुर्वेदी ने 1920 के कसाईखाना आंदोलन का नेतृत्व किया था, जंगल सत्याग्रह का नहीं।', 2, 0, 1, NULL, 'In which year did the ''Ghoradongri'' (Betul) Forest Satyagraha take place in MP and who led it?', '✅ **Correct Logic**: During the Civil Disobedience Movement in 1930, tribals in Ghoradongri (Betul) performed Forest Satyagraha under Ganjan Singh Korku.
💡 **Exam Fact**: A similar satyagraha took place in Seoni under Durga Shankar Mehta.
🧠 **Memory Tip**: ''G'' for Ghoradongri and ''G'' for Ganjan Singh.
🚫 **Scam Alert**: Makhanlal Chaturvedi led the 1920 Anti-Slaughterhouse movement, not the Forest Satyagraha.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('479d5814-74f1-4db3-bcd5-dda67ea09df9', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'निम्नलिखित में से किसे ''मध्य प्रदेश का जलियांवाला बाग'' कहा जाता है?', '[{"id":"A","text":"झंडा सत्याग्रह (Jhanda Satyagraha)","text_en":"झंडा सत्याग्रह (Jhanda Satyagraha)"},{"id":"B","text":"चरण पादुका नरसंहार (Charan Paduka Massacre)","text_en":"चरण पादुका नरसंहार (Charan Paduka Massacre)"},{"id":"C","text":"चावल आंदोलन (Rice Movement)","text_en":"चावल आंदोलन (Rice Movement)"},{"id":"D","text":"सोहावल नरसंहार (Sohawal Massacre)","text_en":"सोहावल नरसंहार (Sohawal Massacre)"}]', '1', '✅ **Correct Logic**: 14 जनवरी 1931 को छतरपुर जिले में उर्मिल नदी के तट पर शांतिपूर्ण भीड़ पर अंधाधुंध गोलियां चलाई गईं, जिसे चरण पादुका नरसंहार कहा जाता है।
💡 **Exam Fact**: आदेश देने वाले अंग्रेज अधिकारी का नाम ''फिशर'' (Fisher) था।
🧠 **Memory Tip**: CP-MP (Charan Paduka = MP''s Jallianwala).
🚫 **Scam Alert**: सोहावल नरसंहार को ''माजन गोली कांड'' कहा जाता है, जलियांवाला बाग नहीं।', 2, 0, 2, NULL, 'Which of the following is known as the ''Jallianwala Bagh of Madhya Pradesh''?', '✅ **Correct Logic**: On Jan 14, 1931, in Chhatarpur district on the banks of Urmil river, peaceful protesters were shot, known as the Charan Paduka Massacre.
💡 **Exam Fact**: The British officer who gave the orders was Agent Fisher.
🧠 **Memory Tip**: CP-MP (Charan Paduka = MP''s Jallianwala).
🚫 **Scam Alert**: Sohawal massacre is known as ''Majan Goli Kaand'', not the Jallianwala of MP.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4cd67890-2846-4a04-aa60-7bc466e9a401', 'deddbde4-947b-43c0-8598-79c1c09e73e8', '1923 के ''झंडा सत्याग्रह'' के संबंध में कौन सा कथन सही है?
1. इसकी शुरुआत जबलपुर से हुई थी।
2. सुंदरलाल जैन को इसमें कारावास की सजा हुई थी।
3. बाद में इसका नेतृत्व नागपुर में सरदार पटेल ने किया।

सही विकल्प चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"केवल 1 और 3","text_en":"केवल 1 और 3"},{"id":"D","text":"1, 2 और 3","text_en":"1, 2 और 3"}]', '3', '✅ **Correct Logic**: तीनों कथन सही हैं। झंडा सत्याग्रह की ज्वाला जबलपुर से उठी जब तिरंगे का अपमान किया गया।
💡 **Exam Fact**: झंडा सत्याग्रह के दौरान जबलपुर नगर पालिका भवन पर पहली बार झंडा फहराया गया था।
🧠 **Memory Tip**: JSN (Jabalpur, Sundarlal, Nagpur).
🚫 **Scam Alert**: ध्यान रहे कि झंडा सत्याग्रह 1923 में हुआ था, 1930 में नहीं।', 2, 0, 3, NULL, 'Which statement is correct regarding the ''Jhanda Satyagraha'' of 1923?
1. It started from Jabalpur.
2. Sundarlal Jain was sentenced to imprisonment.
3. Later, its leadership was taken over by Sardar Patel in Nagpur.

Choose the correct option:', '✅ **Correct Logic**: All statements are correct. The flame of Jhanda Satyagraha arose from Jabalpur when the tricolor was insulted.
💡 **Exam Fact**: During this, the flag was hoisted for the first time on the Jabalpur Municipal Corporation building.
🧠 **Memory Tip**: JSN (Jabalpur, Sundarlal, Nagpur).
🚫 **Scam Alert**: Remember, Jhanda Satyagraha happened in 1923, not 1930.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b58aebe0-6c26-40ba-9200-2f711b2a0115', 'deddbde4-947b-43c0-8598-79c1c09e73e8', '1939 में कांग्रेस का ऐतिहासिक ''त्रिपुरी अधिवेशन'' मध्य प्रदेश के किस शहर के पास आयोजित हुआ था?', '[{"id":"A","text":"इंदौर","text_en":"इंदौर"},{"id":"B","text":"ग्वालियर","text_en":"ग्वालियर"},{"id":"C","text":"जबलपुर","text_en":"जबलपुर"},{"id":"D","text":"भोपाल","text_en":"भोपाल"}]', '2', '✅ **Correct Logic**: त्रिपुरी, जबलपुर के निकट स्थित है। यहाँ सुभाष चंद्र बोस ने पट्टाभि सीतारामैया को हराकर अध्यक्ष पद जीता था।
💡 **Exam Fact**: गांधी जी के समर्थन वाले उम्मीदवार की हार के बाद बोस ने इस्तीफा दे दिया और ''फॉरवर्ड ब्लॉक'' बनाया।
🧠 **Memory Tip**: TJ (Tripuri-Jabalpur).
🚫 **Scam Alert**: पट्टाभि सीतारामैया बाद में मध्य प्रदेश के पहले राज्यपाल बने।', 2, 0, 4, NULL, 'Near which city of MP was the historic ''Tripuri Session'' of Congress held in 1939?', '✅ **Correct Logic**: Tripuri is located near Jabalpur. Subhash Chandra Bose won the presidency here by defeating Pattabhi Sitaramayya.
💡 **Exam Fact**: After the defeat of Gandhi''s preferred candidate, Bose resigned and formed the ''Forward Bloc''.
🧠 **Memory Tip**: TJ (Tripuri-Jabalpur).
🚫 **Scam Alert**: Pattabhi Sitaramayya later became the first Governor of MP.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('23cd2589-a5c5-496b-9fcd-f4a4adf44f0f', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'क्रांतिकारी घटनाओं और उनके स्थानों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: पंजाब मेल हत्याकांड खंडवा रेलवे स्टेशन पर हुआ। चावल आंदोलन रीवा (1947) में हुआ। त्रिपुरी जबलपुर में और टुरिया जंगल सत्याग्रह सिवनी में हुआ।
💡 **Exam Fact**: पंजाब मेल हत्याकांड में यशवंत सिंह, देवनारायण तिवारी और दलपत राव शामिल थे।
🧠 **Memory Tip**: Punjab Mail - Khandwa Junction.
🚫 **Scam Alert**: टुरिया सिवनी में है, इसे घोड़ाडोंगरी (बैतूल) से न जोड़ें।', 2, 0, 5, NULL, 'Match the revolutionary events and their locations:', '✅ **Correct Logic**: Punjab Mail massacre occurred at Khandwa station. Rice movement happened in Rewa (1947). Tripuri is in Jabalpur and Turia forest satyagraha in Seoni.
💡 **Exam Fact**: Yashwant Singh, Devnarayan Tiwari, and Dalpat Rao were involved in the Punjab Mail incident.
🧠 **Memory Tip**: Punjab Mail - Khandwa Junction.
🚫 **Scam Alert**: Turia is in Seoni; do not confuse it with Ghoradongri (Betul).', 60, 'matching', '[{"id":"(1)","label":"पंजाब मेल हत्याकांड","match":"खंडवा","matchId":"(a)"},{"id":"(2)","label":"चावल आंदोलन","match":"रीवा","matchId":"(b)"},{"id":"(3)","label":"त्रिपुरी अधिवेशन","match":"जबलपुर","matchId":"(c)"},{"id":"(4)","label":"जंगल सत्याग्रह (सिवनी)","match":"टुरिया","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('09f36360-8ce0-4091-a614-97f97c1a9bc9', 'deddbde4-947b-43c0-8598-79c1c09e73e8', '1857 के विद्रोह के दौरान ''नीमच'' से विद्रोह की शुरुआत किस तारीख को हुई थी?', '[{"id":"A","text":"10 मई 1857","text_en":"10 मई 1857"},{"id":"B","text":"3 जून 1857","text_en":"3 जून 1857"},{"id":"C","text":"14 जून 1857","text_en":"14 जून 1857"},{"id":"D","text":"20 जून 1857","text_en":"20 जून 1857"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश में 1857 की क्रांति की शुरुआत 3 जून 1857 को नीमच छावनी से हुई थी।
💡 **Exam Fact**: यहाँ विद्रोह का नेतृत्व मोहम्मद अली बेग ने किया था।
🧠 **Memory Tip**: N3 (Neemuch-3rd June).
🚫 **Scam Alert**: 10 मई को मेरठ (UP) में क्रांति शुरू हुई थी, MP में 3 जून को।', 2, 0, 6, NULL, 'On which date did the revolt start from ''Neemuch'' during the 1857 uprising?', '✅ **Correct Logic**: The 1857 revolution in MP started from the Neemuch Cantonment on June 3, 1857.
💡 **Exam Fact**: The revolt here was led by Mohammad Ali Beg.
🧠 **Memory Tip**: N3 (Neemuch-3rd June).
🚫 **Scam Alert**: May 10 was the start in Meerut (UP); in MP, it was June 3.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d54045a7-003a-4290-b2ec-bdcd14d3eb79', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'इंदौर के पास ''महू'' छावनी में 1857 के विद्रोह का नेतृत्व किसने किया था?', '[{"id":"A","text":"शहादत खान (Saadat Khan)","text_en":"शहादत खान (Saadat Khan)"},{"id":"B","text":"भगीरथ सिलावट (Bhagirath Silawat)","text_en":"भगीरथ सिलावट (Bhagirath Silawat)"},{"id":"C","text":"वंश गोपाल","text_en":"वंश गोपाल"},{"id":"D","text":"A और B दोनों","text_en":"A और B दोनों"}]', '3', '✅ **Correct Logic**: महू में शहादत खान और भगीरथ सिलावट ने मिलकर अंग्रेजों के विरुद्ध विद्रोह का बिगुल फूँका था।
💡 **Exam Fact**: शहादत खान होलकर सेना के एक घुड़सवार थे।
🧠 **Memory Tip**: MS (Mhow-Saadat).
🚫 **Scam Alert**: राजा बख्तावर सिंह ने अमझेरा (धार) से नेतृत्व किया था, महू से नहीं।', 2, 0, 7, NULL, 'Who led the 1857 revolt in the ''Mhow'' cantonment near Indore?', '✅ **Correct Logic**: In Mhow, Saadat Khan and Bhagirath Silawat together sounded the bugle of rebellion against the British.
💡 **Exam Fact**: Saadat Khan was a cavalryman in the Holkar army.
🧠 **Memory Tip**: MS (Mhow-Saadat).
🚫 **Scam Alert**: Raja Bakhtawar Singh led from Amjhera (Dhar), not Mhow.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2a33f074-628f-4cd8-af5b-20ffb4b15c19', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'चंद्रशेखर आज़ाद का जन्म मध्य प्रदेश के किस जिले में हुआ था (वर्तमान स्थिति के अनुसार)?', '[{"id":"A","text":"झाबुआ","text_en":"झाबुआ"},{"id":"B","text":"अलीराजपुर","text_en":"अलीराजपुर"},{"id":"C","text":"धार","text_en":"धार"},{"id":"D","text":"बड़वानी","text_en":"बड़वानी"}]', '1', '✅ **Correct Logic**: उनका जन्म ''भाबरा'' गाँव में हुआ था, जो पहले झाबुआ में था लेकिन अब अलीराजपुर जिले का हिस्सा है।
💡 **Exam Fact**: भाबरा का नाम बदलकर अब ''चंद्रशेखर आज़ाद नगर'' कर दिया गया है।
🧠 **Memory Tip**: A-A (Azad - Alirajpur).
🚫 **Scam Alert**: पुराने डेटा में झाबुआ मिलेगा, लेकिन नए जिला गठन के बाद अलीराजपुर सही उत्तर है।', 2, 0, 8, NULL, 'In which district of MP was Chandra Shekhar Azad born (as per current status)?', '✅ **Correct Logic**: He was born in ''Bhabra'' village, which was earlier in Jhabua but is now part of the Alirajpur district.
💡 **Exam Fact**: Bhabra has been renamed ''Chandra Shekhar Azad Nagar''.
🧠 **Memory Tip**: A-A (Azad - Alirajpur).
🚫 **Scam Alert**: Older data might say Jhabua, but after district reorganization, Alirajpur is the correct answer.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('00d17bc0-448a-4442-9d38-2eeafaccf527', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'सीहोर के टाउन हॉल में अंग्रेजों के खिलाफ लड़ते हुए कौन शहीद हुआ था, जिन्हें ''मध्य प्रदेश का मंगल पांडे'' कहा जाता है?', '[{"id":"A","text":"कुंवर चैन सिंह","text_en":"कुंवर चैन सिंह"},{"id":"B","text":"तातिया टोपे","text_en":"तातिया टोपे"},{"id":"C","text":"भीमा नायक","text_en":"भीमा नायक"},{"id":"D","text":"शहजादा हुमायूँ","text_en":"शहजादा हुमायूँ"}]', '0', '✅ **Correct Logic**: नरसिंहगढ़ के राजकुमार कुंवर चैन सिंह 1824 में सीहोर में अंग्रेजों से लड़ते हुए शहीद हुए।
💡 **Exam Fact**: उन्हें मध्य प्रदेश का प्रथम स्वतंत्रता सेनानी माना जाता है।
🧠 **Memory Tip**: Chain Singh - Sehore.
🚫 **Scam Alert**: मंगल पांडे 1857 के थे, लेकिन चैन सिंह 1824 में ही शहीद हो गए थे।', 2, 0, 9, NULL, 'Who was martyred while fighting against the British at the Town Hall of Sehore and is called the ''Mangal Pandey of MP''?', '✅ **Correct Logic**: Prince Kunwar Chain Singh of Narsinghgarh attained martyrdom in 1824 while fighting the British in Sehore.
💡 **Exam Fact**: He is considered the first freedom fighter of Madhya Pradesh.
🧠 **Memory Tip**: Chain Singh - Sehore.
🚫 **Scam Alert**: Mangal Pandey was of 1857, but Chain Singh was martyred earlier in 1824.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cff7c856-d117-45b3-a56e-45cef170204c', 'deddbde4-947b-43c0-8598-79c1c09e73e8', '1942 के ''भारत छोड़ो आंदोलन'' की शुरुआत मध्य प्रदेश में कहाँ से हुई थी?', '[{"id":"A","text":"जबलपुर","text_en":"जबलपुर"},{"id":"B","text":"विदिशा","text_en":"विदिशा"},{"id":"C","text":"सागर","text_en":"सागर"},{"id":"D","text":"इंदौर","text_en":"इंदौर"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश में 1942 के भारत छोड़ो आंदोलन की शुरुआत विदिशा (रियासत काल में ग्वालियर राज्य का हिस्सा) से मानी जाती है।
💡 **Exam Fact**: इस दौरान रीवा में ''जबरन लेवी'' के विरुद्ध आंदोलन हुआ था।
🧠 **Memory Tip**: V for Vidisha, V for Victory (1942).
🚫 **Scam Alert**: जबलपुर से झंडा सत्याग्रह शुरू हुआ था, भारत छोड़ो आंदोलन नहीं।', 2, 0, 10, NULL, 'From where did the ''Quit India Movement'' start in Madhya Pradesh in 1942?', '✅ **Correct Logic**: The start of the 1942 Quit India Movement in MP is attributed to Vidisha (then part of Gwalior State).
💡 **Exam Fact**: During this time, a movement against ''forced levy'' occurred in Rewa.
🧠 **Memory Tip**: V for Vidisha, V for Victory (1942).
🚫 **Scam Alert**: Jhanda Satyagraha started from Jabalpur, not the Quit India Movement.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2bdfebe7-5b1b-435f-8676-096e0d10a324', '84f43923-f20e-4508-a23f-c3c345cb5536', 'हिमालय के अनुदैर्ध्य विभाजन (Longitudinal divisions) के संदर्भ में, निम्नलिखित में से कौन सा युग्म ''कुमाऊँ हिमालय'' की सीमाओं को सही ढंग से दर्शाता है?', '[{"id":"A","text":"सिंधु और सतलज नदियाँ (Indus and Satluj Rivers)","text_en":"सिंधु और सतलज नदियाँ (Indus and Satluj Rivers)"},{"id":"B","text":"सतलज और काली नदियाँ (Satluj and Kali Rivers)","text_en":"सतलज और काली नदियाँ (Satluj and Kali Rivers)"},{"id":"C","text":"काली और तीस्ता नदियाँ (Kali and Teesta Rivers)","text_en":"काली और तीस्ता नदियाँ (Kali and Teesta Rivers)"},{"id":"D","text":"तीस्ता और दिहांग नदियाँ (Teesta and Dihang Rivers)","text_en":"तीस्ता और दिहांग नदियाँ (Teesta and Dihang Rivers)"}]', '1', '**✅ Correct Logic:** कुमाऊँ हिमालय **सतलज** और **काली** नदियों के बीच स्थित है। इसे अक्सर गढ़वाल हिमालय (पश्चिम) और कुमाऊँ हिमालय (पूर्व) में विभाजित किया जाता है।

**💡 Exam Fact:** नंदा देवी, कामेत, त्रिशूल और बद्रीनाथ जैसी प्रमुख चोटियाँ इसी खंड (कुमाऊँ हिमालय) का हिस्सा हैं।

**🧠 Memory Tip:** **SK** (S-Kumeon-K) -> **S**atluj to **K**ali = **K**umaon.

**🚫 Scam Alert:** 
* सिंधु-सतलज = पंजाब/कश्मीर हिमालय।
* काली-तीस्ता = नेपाल हिमालय।
* तीस्ता-दिहांग = असम हिमालय।', 2, 0, 1, NULL, 'With reference to the longitudinal divisions of the Himalayas, which of the following pairs correctly represents the boundaries of the ''Kumaon Himalayas''?', '**✅ Correct Logic:** The Kumaon Himalayas are situated between the **Satluj** and **Kali** rivers. It is often subdivided into Garhwal Himalayas (West) and Kumaon Himalayas (East).

**💡 Exam Fact:** Major peaks like Nanda Devi, Kamet, Trishul, and Badrinath are part of this section (Kumaon Himalayas).

**🧠 Memory Tip:** **SK** (S-Kumeon-K) -> **S**atluj to **K**ali = **K**umaon.

**🚫 Scam Alert:** 
* Indus-Satluj = Punjab/Kashmir Himalayas.
* Kali-Teesta = Nepal Himalayas.
* Teesta-Dihang = Assam Himalayas.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('597cdbad-e24d-44bb-9839-ac43510df521', '84f43923-f20e-4508-a23f-c3c345cb5536', 'प्रायद्वीपीय भारत की निम्नलिखित पहाड़ियों को उत्तर से दक्षिण दिशा (North to South) में व्यवस्थित करें:
1. नल्लामाला पहाड़ियाँ (Nallamala Hills)
2. नीलगिरी पहाड़ियाँ (Nilgiri Hills)
3. जावदी पहाड़ियाँ (Javadi Hills)
4. पालकोंडा पहाड़ियाँ (Palkonda Hills)', '[{"id":"A","text":"1, 4, 3, 2","text_en":"1, 4, 3, 2"},{"id":"B","text":"1, 3, 4, 2","text_en":"1, 3, 4, 2"},{"id":"C","text":"4, 1, 3, 2","text_en":"4, 1, 3, 2"},{"id":"D","text":"1, 4, 2, 3","text_en":"1, 4, 2, 3"}]', '0', '**✅ Correct Logic:** सही क्रम (उत्तर से दक्षिण) है: **नल्लामाला** (आंध्र प्रदेश) → **पालकोंडा** (आंध्र प्रदेश) → **जावदी** (तमिलनाडु) → **नीलगिरी** (तमिलनाडु/केरल/कर्नाटक जंक्शन)।

**💡 Exam Fact:** पूर्वी घाट और पश्चिमी घाट **नीलगिरी पहाड़ियों** पर मिलते हैं। दोदाबेटा (Doda Betta) नीलगिरी की सबसे ऊंची चोटी है।

**🧠 Memory Tip:** **N**a**P** **J**aa **N**il (नप जा नील) -> Nallamala, Palkonda, Javadi, Nilgiri.

**🚫 Scam Alert:** जावदी पहाड़ियाँ (तमिलनाडु) पालकोंडा (आंध्र प्रदेश) के दक्षिण में हैं। कई छात्र आंध्र और तमिलनाडु की सीमा पर भ्रमित हो जाते हैं।', 2, 0, 2, NULL, 'Arrange the following hills of Peninsular India in North to South direction:
1. Nallamala Hills
2. Nilgiri Hills
3. Javadi Hills
4. Palkonda Hills', '**✅ Correct Logic:** The correct order (North to South) is: **Nallamala** (AP) → **Palkonda** (AP) → **Javadi** (TN) → **Nilgiri** (TN/Kerala/Karnataka junction).

**💡 Exam Fact:** The Eastern Ghats and Western Ghats meet at the **Nilgiri Hills**. Doda Betta is the highest peak of the Nilgiris.

**🧠 Memory Tip:** **N**a**P** **J**aa **N**il -> Nallamala, Palkonda, Javadi, Nilgiri.

**🚫 Scam Alert:** Javadi Hills (Tamil Nadu) are south of Palkonda (Andhra Pradesh). Many students get confused at the AP-TN border.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('967f36a4-366d-43b7-ac72-c6e60c61e8bc', '84f43923-f20e-4508-a23f-c3c345cb5536', 'ट्रांस-हिमालय (Trans-Himalayas) के संबंध में निम्नलिखित कथनों पर विचार करें:
1. इसका निर्माण हिमालय से पूर्व हुआ था।
2. लद्दाख श्रेणी और ज़स्कर श्रेणी इसी का हिस्सा हैं।
3. माउंट गॉडविन-ऑस्टिन (K2) वृहद हिमालय (Great Himalayas) में स्थित है।
सही कथन कौन से हैं?', '[{"id":"A","text":"केवल 1 और 2 (Only 1 and 2)","text_en":"केवल 1 और 2 (Only 1 and 2)"},{"id":"B","text":"केवल 2 और 3 (Only 2 and 3)","text_en":"केवल 2 और 3 (Only 2 and 3)"},{"id":"C","text":"केवल 1 और 3 (Only 1 and 3)","text_en":"केवल 1 और 3 (Only 1 and 3)"},{"id":"D","text":"1, 2 और 3 (1, 2 and 3)","text_en":"1, 2 और 3 (1, 2 and 3)"}]', '0', '**✅ Correct Logic:** कथन 1 सही है (ये टेथिस सागर के अवसादों से हिमालय से पहले बने थे)। कथन 2 सही है (काराकोरम, लद्दाख, ज़स्कर, और कैलाश श्रेणियाँ ट्रांस-हिमालय का हिस्सा हैं)। कथन 3 **गलत** है क्योंकि K2 (8611 मी) **काराकोरम श्रेणी** (ट्रांस-हिमालय) में है, न कि वृहद हिमालय में।

**💡 Exam Fact:** लद्दाख श्रेणी और ज़स्कर श्रेणी के बीच **सिंधु नदी** बहती है।

**🧠 Memory Tip:** **KL Z** (KaL ZaP without P) -> Karakoram, Ladakh, Zaskar are Trans-Himalayan.

**🚫 Scam Alert:** K2 भारत की सबसे ऊंची चोटी है, लेकिन यह ''वृहद हिमालय'' (Himadri) का हिस्सा नहीं है, यह उससे भी उत्तर में ''ट्रांस-हिमालय'' में है।', 2, 0, 3, NULL, 'Consider the following statements regarding Trans-Himalayas:
1. It was formed before the Himalayas.
2. Ladakh Range and Zaskar Range are part of it.
3. Mount Godwin-Austen (K2) is located in the Great Himalayas.
Which statements are correct?', '**✅ Correct Logic:** Statement 1 is correct (formed from Tethys sediments before Himalayas). Statement 2 is correct (Karakoram, Ladakh, Zaskar, and Kailash ranges are part of Trans-Himalayas). Statement 3 is **INCORRECT** because K2 (8611m) is in the **Karakoram Range** (Trans-Himalayas), not the Great Himalayas.

**💡 Exam Fact:** The **Indus River** flows between the Ladakh and Zaskar ranges.

**🧠 Memory Tip:** **KL Z** -> Karakoram, Ladakh, Zaskar are Trans-Himalayan.

**🚫 Scam Alert:** K2 is India''s highest peak, but it is NOT part of ''Great Himalayas'' (Himadri); it lies further north in the ''Trans-Himalayas''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c9a8e68f-701d-4417-a010-fa58b396bc7b', '84f43923-f20e-4508-a23f-c3c345cb5536', 'पश्चिमी घाट (Western Ghats) को स्थानीय रूप से महाराष्ट्र और कर्नाटक में ''सह्याद्रि'' कहा जाता है। 16° उत्तरी अक्षांश (जो गोवा से गुजरती है) सह्याद्रि को किन दो भागों में विभाजित करती है?', '[{"id":"A","text":"कोंकण और मालाबार (Konkan and Malabar)","text_en":"कोंकण और मालाबार (Konkan and Malabar)"},{"id":"B","text":"उत्तरी सह्याद्रि और दक्षिणी सह्याद्रि (Northern Sahyadri and Southern Sahyadri)","text_en":"उत्तरी सह्याद्रि और दक्षिणी सह्याद्रि (Northern Sahyadri and Southern Sahyadri)"},{"id":"C","text":"कर्नाटक पठार और दक्कन पठार (Karnataka Plateau and Deccan Plateau)","text_en":"कर्नाटक पठार और दक्कन पठार (Karnataka Plateau and Deccan Plateau)"},{"id":"D","text":"काठियावाड़ और कोंकण (Kathiawar and Konkan)","text_en":"काठियावाड़ और कोंकण (Kathiawar and Konkan)"}]', '1', '**✅ Correct Logic:** 16° N अक्षांश सह्याद्रि को **उत्तरी सह्याद्रि** (बेसाल्टिक लावा से निर्मित) और **दक्षिणी सह्याद्रि** (आर्कियन ग्रेनाइट और नीस से निर्मित) में विभाजित करती है।

**💡 Exam Fact:** उत्तरी सह्याद्रि की सबसे ऊंची चोटी **कलसुबाई** (1646 मी) है, जबकि दक्षिणी सह्याद्रि की **कुद्रेमुख** प्रमुख चोटी है।

**🧠 Memory Tip:** **16 ka Batwara** -> 16 degree divides Sahyadri into North and South.

**🚫 Scam Alert:** कोंकण और मालाबार तटीय मैदानों के नाम हैं, न कि पहाड़ों के विभाजन के भूवैज्ञानिक नाम।', 2, 0, 4, NULL, 'The Western Ghats are locally known as ''Sahyadri'' in Maharashtra and Karnataka. The 16° N latitude (passing through Goa) divides the Sahyadri into which two parts?', '**✅ Correct Logic:** The 16° N latitude divides the Sahyadri into **Northern Sahyadri** (made of Basaltic Lava) and **Southern Sahyadri** (made of Archean Granite and Gneiss).

**💡 Exam Fact:** The highest peak of Northern Sahyadri is **Kalsubai** (1646m), while **Kudremukh** is a major peak of Southern Sahyadri.

**🧠 Memory Tip:** **16 ka Batwara** -> 16 degree divides Sahyadri into North and South.

**🚫 Scam Alert:** Konkan and Malabar are names of coastal plains, not the geological division of the mountains themselves.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4f83134c-6508-49a4-b2a3-5569edb8833c', '84f43923-f20e-4508-a23f-c3c345cb5536', 'निम्नलिखित में से कौन सा ''असम हिमालय'' की सबसे ऊंची चोटी है?', '[{"id":"A","text":"कंचनजंगा (Kanchenjunga)","text_en":"कंचनजंगा (Kanchenjunga)"},{"id":"B","text":"नामचा बरवा (Namcha Barwa)","text_en":"नामचा बरवा (Namcha Barwa)"},{"id":"C","text":"कूला कांगरी (Kula Kangri)","text_en":"कूला कांगरी (Kula Kangri)"},{"id":"D","text":"चो ओयू (Cho Oyu)","text_en":"चो ओयू (Cho Oyu)"}]', '1', '**✅ Correct Logic:** **नामचा बरवा** (7782 मी) असम हिमालय (तीस्ता से दिहांग नदी) की सबसे ऊंची चोटी है। यह अरुणाचल प्रदेश-तिब्बत सीमा पर स्थित है।

**💡 Exam Fact:** ब्रह्मपुत्र नदी नामचा बरवा के पास एक गहरा गॉर्ज (U-turn) बनाती है और भारत में प्रवेश करती है।

**🧠 Memory Tip:** **Assam ka Nam** -> Namcha Barwa is in the Assam Himalayan section.

**🚫 Scam Alert:** कंचनजंगा (8586 मी) नेपाल हिमालय का हिस्सा है (हालांकि यह सिक्किम सीमा पर है, लेकिन वर्गीकरण में इसे अक्सर नेपाल हिमालय या नेपाल-सिक्किम सीमा के तहत रखा जाता है, लेकिन नामचा बरवा सुदूर पूर्व का निर्विवाद नेता है)।', 2, 0, 5, NULL, 'Which of the following is the highest peak of the ''Assam Himalayas''?', '**✅ Correct Logic:** **Namcha Barwa** (7782m) is the highest peak of the Assam Himalayas (Teesta to Dihang river). It is located on the Arunachal Pradesh-Tibet border.

**💡 Exam Fact:** The Brahmaputra river creates a deep gorge (U-turn) near Namcha Barwa and enters India.

**🧠 Memory Tip:** **Assam ka Nam** -> Namcha Barwa is in the Assam Himalayan section.

**🚫 Scam Alert:** Kanchenjunga (8586m) is part of the Nepal Himalayas (though on the Sikkim border, mostly classified under Nepal section in longitudinal division, whereas Namcha Barwa is the undisputed leader of the far east ''Assam'' section).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('755a0409-3f89-4f4d-85a9-eaeba390ea7e', '84f43923-f20e-4508-a23f-c3c345cb5536', 'निम्नलिखित में से कौन सी पहाड़ी श्रृंखला ''ब्लॉक पर्वत'' (Block Mountain) का एक उदाहरण है जो नर्मदा और ताप्ती नदियों के बीच स्थित है?', '[{"id":"A","text":"विंध्याचल श्रेणी (Vindhyachal Range)","text_en":"विंध्याचल श्रेणी (Vindhyachal Range)"},{"id":"B","text":"सतपुड़ा श्रेणी (Satpura Range)","text_en":"सतपुड़ा श्रेणी (Satpura Range)"},{"id":"C","text":"अरावली श्रेणी (Aravali Range)","text_en":"अरावली श्रेणी (Aravali Range)"},{"id":"D","text":"अजंता श्रेणी (Ajanta Range)","text_en":"अजंता श्रेणी (Ajanta Range)"}]', '1', '**✅ Correct Logic:** **सतपुड़ा श्रेणी** एक ब्लॉक पर्वत है जो उत्तर में नर्मदा की भ्रंश घाटी और दक्षिण में ताप्ती की भ्रंश घाटी के बीच स्थित है। इसे ''Horst'' भी कहा जाता है।

**💡 Exam Fact:** सतपुड़ा की सबसे ऊंची चोटी **धूपगढ़** (1350 मी) है, जो पचमढ़ी (MP) में महादेव पहाड़ियों पर स्थित है।

**🧠 Memory Tip:** **N-S-T** -> Narmada - **Satpura** - Tapti.

**🚫 Scam Alert:** विंध्याचल एक ''अवशिष्ट पर्वत'' (Residual) या ''कगार'' (Escarpment) के रूप में जाना जाता है, ब्लॉक पर्वत के रूप में सतपुड़ा सबसे सटीक उदाहरण है।', 2, 0, 6, NULL, 'Which of the following mountain ranges is an example of a ''Block Mountain'' situated between the Narmada and Tapti rivers?', '**✅ Correct Logic:** The **Satpura Range** is a Block Mountain situated between the rift valley of Narmada in the north and the rift valley of Tapti in the south. It is also known as a ''Horst''.

**💡 Exam Fact:** The highest peak of Satpura is **Dhupgarh** (1350m), located on the Mahadeo Hills in Pachmarhi (MP).

**🧠 Memory Tip:** **N-S-T** -> Narmada - **Satpura** - Tapti.

**🚫 Scam Alert:** Vindhyachal is known more as a ''Residual Mountain'' or ''Escarpment''; Satpura is the most accurate example of a Block Mountain here.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('087a181b-3237-4c77-a966-d04091bf1b9f', '84f43923-f20e-4508-a23f-c3c345cb5536', 'पूर्वोत्तर भारत की ''लुशाई पहाड़ियाँ'' (Lushai Hills) किस पर्वत श्रृंखला का हिस्सा हैं और वे किस राज्य में प्रमुखता से स्थित हैं?', '[{"id":"A","text":"पटकाई बूम - अरुणाचल प्रदेश (Patkai Bum - Arunachal Pradesh)","text_en":"पटकाई बूम - अरुणाचल प्रदेश (Patkai Bum - Arunachal Pradesh)"},{"id":"B","text":"पूर्वांचल रेंज - मिजोरम (Purvanchal Range - Mizoram)","text_en":"पूर्वांचल रेंज - मिजोरम (Purvanchal Range - Mizoram)"},{"id":"C","text":"बरेल रेंज - असम (Barail Range - Assam)","text_en":"बरेल रेंज - असम (Barail Range - Assam)"},{"id":"D","text":"मेघालय पठार - मेघालय (Meghalaya Plateau - Meghalaya)","text_en":"मेघालय पठार - मेघालय (Meghalaya Plateau - Meghalaya)"}]', '1', '**✅ Correct Logic:** लुशाई पहाड़ियों को **मिज़ो पहाड़ियाँ** भी कहा जाता है। ये **पूर्वांचल श्रेणी** (Himalayan bend) का हिस्सा हैं और मुख्य रूप से **मिजोरम** में स्थित हैं।

**💡 Exam Fact:** ''ब्लू माउंटेन'' (फांगपुई - Phawngpui) लुशाई पहाड़ियों की सबसे ऊंची चोटी है।

**🧠 Memory Tip:** **Lushai** sounds like **Loose-Eye** -> Mizoram starts with M (My) -> My Loose Eye -> Or simply Lushai = Mizo (Old name of Mizoram was Lushai Hills District).

**🚫 Scam Alert:** मेघालय पठार (गारो, खासी, जयंतिया) प्रायद्वीपीय पठार का हिस्सा है, हिमालय का नहीं। लुशाई हिमालय (पूर्वांचल) का हिस्सा है।', 2, 0, 7, NULL, 'The ''Lushai Hills'' of North-East India are part of which mountain range and are predominantly located in which state?', '**✅ Correct Logic:** Lushai Hills are also known as **Mizo Hills**. They are part of the **Purvanchal Range** (Himalayan bend) and are predominantly located in **Mizoram**.

**💡 Exam Fact:** ''Blue Mountain'' (Phawngpui) is the highest peak of the Lushai Hills.

**🧠 Memory Tip:** Lushai = Mizo (The old name of Mizoram was Lushai Hills District).

**🚫 Scam Alert:** The Meghalaya Plateau (Garo, Khasi, Jaintia) is part of the Peninsular Plateau, not the Himalayas. Lushai IS part of the Himalayas (Purvanchal).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6c233793-c87c-4a3d-a6e6-6bbefe350a89', '84f43923-f20e-4508-a23f-c3c345cb5536', '''सिंटैक्सियल बेंड'' (Syntaxial Bend) के संदर्भ में, हिमालय दक्षिण की ओर तीखा मोड़ लेता है। पश्चिमी छोर पर यह मोड़ किस पर्वत के पास स्थित है?', '[{"id":"A","text":"नंगा पर्वत (Nanga Parbat)","text_en":"नंगा पर्वत (Nanga Parbat)"},{"id":"B","text":"नामचा बरवा (Namcha Barwa)","text_en":"नामचा बरवा (Namcha Barwa)"},{"id":"C","text":"राकापोशी (Rakaposhi)","text_en":"राकापोशी (Rakaposhi)"},{"id":"D","text":"गुरला मंधाता (Gurla Mandhata)","text_en":"गुरला मंधाता (Gurla Mandhata)"}]', '0', '**✅ Correct Logic:** हिमालय में दो सिंटैक्सियल बेंड हैं। पश्चिमी मोड़ **नंगा पर्वत** (Nanga Parbat) के पास है (जहां से सिंधु मुड़ती है) और पूर्वी मोड़ **नामचा बरवा** (Namcha Barwa) के पास है।

**💡 Exam Fact:** नंगा पर्वत (8126 मी) को ''कतिल पहाड़'' (Killer Mountain) भी कहा जाता है।

**🧠 Memory Tip:** West is **Nanga**, East is **Namcha**. (W-Nanga, E-Namcha).

**🚫 Scam Alert:** राकापोशी दुनिया की सबसे खड़ी ढलान वाली चोटी है (लद्दाख श्रेणी में), लेकिन यह सिंटैक्सियल बेंड का मुख्य बिंदु नहीं है।', 2, 0, 8, NULL, 'With reference to the ''Syntaxial Bend'', the Himalayas take a sharp southward turn. Near which mountain is this bend located on the Western end?', '**✅ Correct Logic:** The Himalayas have two syntaxial bends. The Western bend is near **Nanga Parbat** (where Indus turns) and the Eastern bend is near **Namcha Barwa**.

**💡 Exam Fact:** Nanga Parbat (8126m) is also known as the ''Killer Mountain''.

**🧠 Memory Tip:** West is **Nanga**, East is **Namcha**. (W-Nanga, E-Namcha).

**🚫 Scam Alert:** Rakaposhi is the world''s steepest peak (in Ladakh range), but not the pivot point of the syntaxial bend.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ae75e381-5579-4848-a181-45c56c14d162', '84f43923-f20e-4508-a23f-c3c345cb5536', 'दक्षिण भारत की सबसे ऊंची चोटी ''अनामुडी'' (Anamudi) निम्नलिखित में से किस पहाड़ी का हिस्सा है?', '[{"id":"A","text":"नीलगिरी पहाड़ियाँ (Nilgiri Hills)","text_en":"नीलगिरी पहाड़ियाँ (Nilgiri Hills)"},{"id":"B","text":"अन्नामलाई पहाड़ियाँ (Annamalai Hills)","text_en":"अन्नामलाई पहाड़ियाँ (Annamalai Hills)"},{"id":"C","text":"इलायची पहाड़ियाँ (Cardamom Hills)","text_en":"इलायची पहाड़ियाँ (Cardamom Hills)"},{"id":"D","text":"पालनी पहाड़ियाँ (Palani Hills)","text_en":"पालनी पहाड़ियाँ (Palani Hills)"}]', '1', '**✅ Correct Logic:** **अनामुडी** (2695 मी) **अन्नामलाई पहाड़ियों** (केरल) में स्थित है। यह प्रायद्वीपीय भारत की सबसे ऊंची चोटी है।

**💡 Exam Fact:** अनामुडी एक पर्वतीय गांठ (knot) है जहां अन्नामलाई (उत्तर), पालनी (उत्तर-पूर्व) और इलायची (दक्षिण) पहाड़ियाँ मिलती हैं।

**🧠 Memory Tip:** **Ana**mudi belongs to **Anna**malai. (Ana-Anna connection).

**🚫 Scam Alert:** दोदाबेटा (Doda Betta) नीलगिरी की सबसे ऊंची चोटी है, दक्षिण भारत की नहीं। अनामुडी उससे ऊंची है।', 2, 0, 9, NULL, 'South India''s highest peak ''Anamudi'' is part of which of the following hills?', '**✅ Correct Logic:** **Anamudi** (2695m) is located in the **Annamalai Hills** (Kerala). It is the highest peak of Peninsular India.

**💡 Exam Fact:** Anamudi is a mountain knot where Annamalai (North), Palani (North-East), and Cardamom (South) hills meet.

**🧠 Memory Tip:** **Ana**mudi belongs to **Anna**malai. (Ana-Anna connection).

**🚫 Scam Alert:** Doda Betta is the highest peak of Nilgiris, NOT South India. Anamudi is taller.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0bd09068-7968-4fa1-981c-4ecb7d8bc0bb', '84f43923-f20e-4508-a23f-c3c345cb5536', 'निम्नलिखित पर्वत श्रेणियों को उनकी सर्वोच्च चोटियों के साथ सुमेलित करें (Match the following mountain ranges with their highest peaks):', '[{"id":"A","text":"(1)-(b), (2)-(d), (3)-(c), (4)-(a)","text_en":"(1)-(b), (2)-(d), (3)-(c), (4)-(a)"},{"id":"B","text":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)","text_en":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(d), (4)-(b)","text_en":"(1)-(a), (2)-(c), (3)-(d), (4)-(b)"},{"id":"D","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"}]', '1', '**✅ Correct Matching:**
* **अरावली** की सबसे ऊंची चोटी **गुरु शिखर** (1722 मी, माउंट आबू) है। -> (1)-(b)
* **सतपुड़ा** की सबसे ऊंची चोटी **धूपगढ़** (1350 मी) है। -> (2)-(d)
* **मैकाल** श्रेणी की सबसे ऊंची चोटी **अमरकंटक** (1065 मी) है। -> (3)-(a)
* **विंध्याचल** (भान्डेर/कैमूर क्षेत्र) की सबसे ऊंची चोटी **सद्भावना शिखर** (गुडविल पीक/कालुमार, 752 मी, दमोह) है। -> (4)-(c)

**💡 Exam Fact:** अमरकंटक से तीन प्रमुख नदियाँ निकलती हैं: नर्मदा, सोन और जोहिला।

**🧠 Memory Tip:** **Guru** of Aravali, **Dhup** in Satpura, **Amar** in Maikal, **Goodwill** in Vindhya.

**🚫 Scam Alert:** अक्सर छात्र विंध्याचल की चोटी में भ्रमित होते हैं। एमपीपीएससी में ''सिद् बाबा'' या ''सद्भावना शिखर'' (Goodwill Peak) को विंध्य की सर्वोच्च चोटी माना जाता है।', 2, 0, 10, NULL, 'Match the following mountain ranges with their highest peaks:', '**✅ Correct Matching:**
* Highest peak of **Aravali** is **Guru Shikhar** (1722m, Mt Abu). -> (1)-(b)
* Highest peak of **Satpura** is **Dhupgarh** (1350m). -> (2)-(d)
* Highest peak of **Maikal** range is **Amarkantak** (1065m). -> (3)-(a)
* Highest peak of **Vindhyachal** is **Sadbhavna Shikhar** (Goodwill Peak/Kalumar, 752m). -> (4)-(c)

**💡 Exam Fact:** Three major rivers originate from Amarkantak: Narmada, Son, and Johila.

**🧠 Memory Tip:** **Guru** of Aravali, **Dhup** in Satpura, **Amar** in Maikal, **Goodwill** in Vindhya.

**🚫 Scam Alert:** Students often get confused with Vindhya''s peak. In MPPSC, ''Siddha Baba'' or ''Sadbhavna Shikhar'' (Goodwill Peak) is considered the highest.', 60, 'matching', '[{"id":"(1)","label":"अरावली (Aravali)","match":"अमरकंटक (Amarkantak)","matchId":"(a)"},{"id":"(2)","label":"सतपुड़ा (Satpura)","match":"गुरु शिखर (Guru Shikhar)","matchId":"(b)"},{"id":"(3)","label":"मैकाल (Maikal)","match":"सद्भावना शिखर (Goodwill Peak/Kalumar)","matchId":"(c)"},{"id":"(4)","label":"विंध्याचल (Vindhyachal)","match":"धूपगढ़ (Dhupgarh)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c9ea4a54-6333-45b3-990a-ef08e0a9c3aa', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'खजुराहो के मंदिरों के संबंध में निम्नलिखित कथनों पर विचार करें:
1. इनका निर्माण 950-1050 ईस्वी के बीच चंदेल शासकों द्वारा किया गया था।
2. यहाँ के मंदिर नागर शैली के उत्कृष्ट उदाहरण हैं।
3. लक्ष्मण मंदिर का निर्माण राजा धंग देव ने करवाया था।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '0', '✅ **Correct Logic**: कथन 1 और 2 सही हैं। लक्ष्मण मंदिर का निर्माण राजा यशोवर्मन ने करवाया था, धंग देव ने नहीं।
💡 **Exam Fact**: खजुराहो को 1986 में यूनेस्को विश्व धरोहर स्थल घोषित किया गया था।
🧠 **Memory Tip**: L-Y (Lakshman-Yashovarman).
🚫 **Scam Alert**: धंग देव ने ''विश्वनाथ मंदिर'' बनवाया था, लक्ष्मण मंदिर यशोवर्मन की कृति है।', 2, 0, 1, NULL, 'Consider the following statements regarding Khajuraho temples:
1. They were built between 950-1050 AD by Chandela rulers.
2. The temples here are excellent examples of Nagara style.
3. The Lakshmana Temple was built by King Dhanga Deva.

Choose the correct statement:', '✅ **Correct Logic**: Statements 1 and 2 are correct. Lakshmana temple was built by King Yashovarman, not Dhanga Deva.
💡 **Exam Fact**: Khajuraho was declared a UNESCO World Heritage site in 1986.
🧠 **Memory Tip**: L-Y (Lakshman-Yashovarman).
🚫 **Scam Alert**: Dhanga Deva built the Vishvanatha temple, while the Lakshmana temple is the work of Yashovarman.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('71a2c878-2d7f-4b2d-b970-3b6c0bf5f696', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'धार स्थित ''बाघ की गुफाओं'' की तुलना अक्सर अजंता की गुफाओं से की जाती है। इन गुफाओं का संबंध किस धर्म से है?', '[{"id":"A","text":"जैन धर्म","text_en":"जैन धर्म"},{"id":"B","text":"बौद्ध धर्म","text_en":"बौद्ध धर्म"},{"id":"C","text":"हिंदू धर्म","text_en":"हिंदू धर्म"},{"id":"D","text":"शैव धर्म","text_en":"शैव धर्म"}]', '1', '✅ **Correct Logic**: बाघ की गुफाएं पूर्णतः बौद्ध धर्म से संबंधित हैं। यहाँ कुल 9 गुफाएं थीं जिनमें से अब केवल 5 अस्तित्व में हैं।
💡 **Exam Fact**: इन गुफाओं की खोज 1818 में डेंजरफील्ड (Dangerfield) ने की थी।
🧠 **Memory Tip**: Bagh (Tiger) follows Buddha (Peace).
🚫 **Scam Alert**: उदयगिरि की गुफाएं जैन और हिंदू धर्म से संबंधित हैं, जबकि बाघ केवल बौद्ध धर्म से।', 2, 0, 2, NULL, 'The ''Bagh Caves'' in Dhar are often compared to the Ajanta Caves. Which religion are these caves associated with?', '✅ **Correct Logic**: The Bagh caves are entirely associated with Buddhism. There were 9 caves in total, but only 5 exist now.
💡 **Exam Fact**: These caves were discovered by Dangerfield in 1818.
🧠 **Memory Tip**: Bagh (Tiger) follows Buddha (Peace).
🚫 **Scam Alert**: Udayagiri caves relate to Jainism/Hinduism, while Bagh is exclusively Buddhist.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5ef5dc43-5e69-4b7c-96c7-6521bdf12b41', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'विदिशा में स्थित ''हेलियोडोरस स्तंभ'' किस धर्म की लोकप्रियता का प्राचीनतम साक्ष्य है?', '[{"id":"A","text":"शैव धर्म","text_en":"शैव धर्म"},{"id":"B","text":"भागवत धर्म","text_en":"भागवत धर्म"},{"id":"C","text":"बौद्ध धर्म","text_en":"बौद्ध धर्म"},{"id":"D","text":"शक्ति धर्म","text_en":"शक्ति धर्म"}]', '1', '✅ **Correct Logic**: यह स्तंभ ''भागवत (वैष्णव) धर्म'' से संबंधित है, जिसे ग्रीक राजदूत हेलियोडोरस ने भगवान विष्णु को समर्पित किया था।
💡 **Exam Fact**: स्थानीय लोग इसे ''खाम बाबा'' के नाम से जानते हैं।
🧠 **Memory Tip**: Helio-V (Heliodorus - Vaishnava/Bhagavat).
🚫 **Scam Alert**: यह शुंग काल का है, गुप्त काल का नहीं।', 2, 0, 3, NULL, 'The ''Heliodorus Pillar'' in Vidisha is the oldest evidence of the popularity of which religion?', '✅ **Correct Logic**: This pillar belongs to the ''Bhagavat (Vaishnava) religion'', dedicated to Lord Vishnu by the Greek ambassador Heliodorus.
💡 **Exam Fact**: Local people refer to it as ''Kham Baba''.
🧠 **Memory Tip**: Helio-V (Heliodorus - Vaishnava/Bhagavat).
🚫 **Scam Alert**: It belongs to the Shunga period, not the Gupta period.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('795eed09-f6dd-4de5-803a-a7a14d70e1d2', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'ग्वालियर किले में स्थित ''तेली का मंदिर'' किस वास्तुकला शैली का मिश्रण है?', '[{"id":"A","text":"द्रविड़ और नागर","text_en":"द्रविड़ और नागर"},{"id":"B","text":"नागर और बेसर","text_en":"नागर और बेसर"},{"id":"C","text":"द्रविड़ और बेसर","text_en":"द्रविड़ और बेसर"},{"id":"D","text":"ईरानी और नागर","text_en":"ईरानी और नागर"}]', '0', '✅ **Correct Logic**: इस मंदिर का शिखर द्रविड़ शैली में है जबकि इसकी नक्काशी और मूर्तियां नागर शैली में हैं।
💡 **Exam Fact**: यह उत्तर भारत का एकमात्र मंदिर है जिसका शिखर द्रविड़ शैली का है।
🧠 **Memory Tip**: T-D (Teli-Dravida Top).
🚫 **Scam Alert**: सास-बहू मंदिर (सहस्त्रबाहु) पास में ही है, पर उसकी शैली पूरी तरह अलग है।', 2, 0, 4, NULL, 'The ''Teli ka Mandir'' in Gwalior Fort is a blend of which architectural styles?', '✅ **Correct Logic**: The Shikhara (tower) of this temple is in Dravidian style, while the carvings and sculptures are in Nagara style.
💡 **Exam Fact**: It is the only temple in North India with a Dravidian style shikhara.
🧠 **Memory Tip**: T-D (Teli-Dravida Top).
🚫 **Scam Alert**: Saas-Bahu temple is nearby but has a completely different style.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('041be048-75da-4687-80b1-2656e0abff33', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'स्थापत्य कला और उनके संबंधित स्थान को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: जहाज महल मांडू में है। गुजरी महल मानसिंह तोमर ने ग्वालियर में बनवाया। मितावली का चौसठ योगिनी मंदिर संसद भवन के डिजाइन का आधार माना जाता है।
💡 **Exam Fact**: खूनी दरवाजा चंदेरी किले का मुख्य द्वार है।
🧠 **Memory Tip**: Ship (Jahaj) in Mandu city of joy.
🚫 **Scam Alert**: जबलपुर (भेड़ाघाट) में भी एक चौसठ योगिनी मंदिर है, भ्रमित न हों।', 2, 0, 5, NULL, 'Match the architecture and their respective locations:', '✅ **Correct Logic**: Jahaz Mahal is in Mandu. Gujari Mahal was built by Man Singh Tomar in Gwalior. Mitawali''s Chausath Yogini temple is said to be the inspiration for the old Parliament House.
💡 **Exam Fact**: Khooni Darwaza is a main gate in Chanderi Fort.
🧠 **Memory Tip**: Ship (Jahaj) in Mandu city of joy.
🚫 **Scam Alert**: There is another Chausath Yogini temple in Bhedaghat (Jabalpur), don''t confuse them.', 60, 'matching', '[{"id":"(1)","label":"जहाज महल","match":"मांडू","matchId":"(a)"},{"id":"(2)","label":"गुजरी महल","match":"ग्वालियर","matchId":"(b)"},{"id":"(3)","label":"चौसठ योगिनी मंदिर","match":"मितावली (मुरैना)","matchId":"(c)"},{"id":"(4)","label":"खूनी दरवाजा","match":"चंदेरी","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ce471158-8469-4e86-9d38-c3687b22dfec', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'पिथोरा भित्ति चित्र (Wall Paintings) किस जनजाति की प्रमुख कला है?', '[{"id":"A","text":"गोंड","text_en":"गोंड"},{"id":"B","text":"भील","text_en":"भील"},{"id":"C","text":"बैगा","text_en":"बैगा"},{"id":"D","text":"सहारिया","text_en":"सहारिया"}]', '1', '✅ **Correct Logic**: पिथोरा चित्रकला भील जनजाति की प्रसिद्ध लोक कला है। इसमें घोड़ों के चित्र मुख्य होते हैं।
💡 **Exam Fact**: पेमा फाल्या और भूरी बाई इस कला के प्रसिद्ध कलाकार रहे हैं।
🧠 **Memory Tip**: B-P (Bheel-Pithora).
🚫 **Scam Alert**: गोंडों की चित्रकला ''नोहडोरा'' या गोंडी पेंटिंग कहलाती है, पिथोरा नहीं।', 2, 0, 6, NULL, 'Pithora wall painting is a major art form of which tribe?', '✅ **Correct Logic**: Pithora painting is a famous folk art of the Bhil tribe, predominantly featuring horses.
💡 **Exam Fact**: Pema Falya and Bhuri Bai have been famous artists of this form.
🧠 **Memory Tip**: B-P (Bheel-Pithora).
🚫 **Scam Alert**: Gond paintings are called Gondi or Nohdora, not Pithora.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d053331c-fc7e-4d6b-bd6a-091b5508df34', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'उदयगिरि की गुफा संख्या 5 में किस देवता की प्रसिद्ध ''वराह अवतार'' की विशाल प्रतिमा है?', '[{"id":"A","text":"भगवान शिव","text_en":"भगवान शिव"},{"id":"B","text":"भगवान विष्णु","text_en":"भगवान विष्णु"},{"id":"C","text":"भगवान ब्रह्मा","text_en":"भगवान ब्रह्मा"},{"id":"D","text":"तीर्थंकर पार्श्वनाथ","text_en":"तीर्थंकर पार्श्वनाथ"}]', '1', '✅ **Correct Logic**: गुफा संख्या 5 (विदिशा) में भगवान विष्णु के वराह अवतार की शानदार प्रतिमा है।
💡 **Exam Fact**: उदयगिरि में कुल 20 गुफाएं हैं, जो गुप्त काल की हैं।
🧠 **Memory Tip**: V-V (Varaha-Vishnu).
🚫 **Scam Alert**: यहाँ गुफा संख्या 1 और 20 जैन धर्म से संबंधित हैं, बाकी हिंदू धर्म से।', 2, 0, 7, NULL, 'In cave number 5 of Udayagiri, there is a famous massive idol of which deity''s ''Varaha'' incarnation?', '✅ **Correct Logic**: Cave number 5 (Vidisha) houses a magnificent statue of Lord Vishnu''s Varaha incarnation.
💡 **Exam Fact**: There are 20 caves in Udayagiri, dating back to the Gupta period.
🧠 **Memory Tip**: V-V (Varaha-Vishnu).
🚫 **Scam Alert**: Cave 1 and 20 are Jain, while others are Hindu.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('87da4823-fd0c-4da5-b9f5-ad86c9132dd8', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'भीमबेटका की खोज किसने की थी और यहाँ किस प्रकार की कला पाई जाती है?', '[{"id":"A","text":"एच.डी. सांकलिया; मूर्तिकला","text_en":"एच.डी. सांकलिया; मूर्तिकला"},{"id":"B","text":"वी.एस. वाकणकर; शैल चित्रकला","text_en":"वी.एस. वाकणकर; शैल चित्रकला"},{"id":"C","text":"अलेक्जेंडर कनिंघम; स्थापत्य कला","text_en":"अलेक्जेंडर कनिंघम; स्थापत्य कला"},{"id":"D","text":"जॉन मार्शल; टेराकोटा कला","text_en":"जॉन मार्शल; टेराकोटा कला"}]', '1', '✅ **Correct Logic**: 1957-58 में डॉ. विष्णु श्रीधर वाकणकर ने भीमबेटका के शैल चित्रों (Rock Paintings) की खोज की थी।
💡 **Exam Fact**: यह रायसेन जिले में स्थित है और आदिमानव के जीवन को दर्शाता है।
🧠 **Memory Tip**: BW (Bhimbetka-Wakankar).
🚫 **Scam Alert**: कनिंघम ने भरहुत स्तूप की खोज की थी, भीमबेटका की नहीं।', 2, 0, 8, NULL, 'Who discovered Bhimbetka and what type of art is found here?', '✅ **Correct Logic**: Dr. Vishnu Shridhar Wakankar discovered the rock paintings of Bhimbetka in 1957-58.
💡 **Exam Fact**: Located in Raisen district, it depicts the life of early humans.
🧠 **Memory Tip**: BW (Bhimbetka-Wakankar).
🚫 **Scam Alert**: Cunningham discovered Bharhut Stupa, not Bhimbetka.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('73cab7b9-e383-4e60-9c3a-8e8bc365026b', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'चंदेरी साड़ियों को किस वर्ष भारत का पहला भौगोलिक संकेत (GI Tag) प्राप्त हुआ था?', '[{"id":"A","text":"2004-05","text_en":"2004-05"},{"id":"B","text":"2008-09","text_en":"2008-09"},{"id":"C","text":"2012-13","text_en":"2012-13"},{"id":"D","text":"2001-02","text_en":"2001-02"}]', '0', '✅ **Correct Logic**: चंदेरी साड़ियों को 2004-05 में जीआई टैग मिला था, जो मध्य प्रदेश का पहला उत्पाद था।
💡 **Exam Fact**: महेश्वर साड़ियों को इसके बहुत बाद 2012-13 में टैग मिला।
🧠 **Memory Tip**: C-1st (Chanderi is first).
🚫 **Scam Alert**: 2008-09 में ''चमड़े के खिलौने'' (इंदौर) को टैग मिला था।', 2, 0, 9, NULL, 'In which year did Chanderi sarees receive India''s first Geographical Indication (GI Tag)?', '✅ **Correct Logic**: Chanderi sarees received the GI tag in 2004-05, being the first product from MP to get it.
💡 **Exam Fact**: Maheshwari sarees received the tag much later in 2012-13.
🧠 **Memory Tip**: C-1st (Chanderi is first).
🚫 **Scam Alert**: Leather toys of Indore got the tag in 2008-09.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('63fe2e05-ec8f-4d52-ba7e-d9794d4f1d01', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'भरहुत स्तूप की कलाकृतियां वर्तमान में किस संग्रहालय में मुख्य रूप से सुरक्षित हैं?', '[{"id":"A","text":"भोपाल संग्रहालय","text_en":"भोपाल संग्रहालय"},{"id":"B","text":"ग्वालियर संग्रहालय","text_en":"ग्वालियर संग्रहालय"},{"id":"C","text":"भारतीय संग्रहालय, कोलकाता","text_en":"भारतीय संग्रहालय, कोलकाता"},{"id":"D","text":"सतना संग्रहालय","text_en":"सतना संग्रहालय"}]', '2', '✅ **Correct Logic**: भरहुत स्तूप (सतना) के अधिकांश अवशेष ''इंडियन म्यूजियम, कोलकाता'' में रखे गए हैं।
💡 **Exam Fact**: कुछ अवशेष प्रयागराज संग्रहालय में भी हैं।
🧠 **Memory Tip**: B-K (Bharhut - Kolkata).
🚫 **Scam Alert**: सतना में स्तूप था, पर उसके अवशेष अब वहां बहुत कम बचे हैं।', 2, 0, 10, NULL, 'In which museum are the artifacts of Bharhut Stupa primarily preserved currently?', '✅ **Correct Logic**: Most remains of the Bharhut Stupa (Satna) are kept in the ''Indian Museum, Kolkata''.
💡 **Exam Fact**: Some remains are also in the Prayagraj Museum.
🧠 **Memory Tip**: B-K (Bharhut - Kolkata).
🚫 **Scam Alert**: The Stupa was in Satna, but very few remains are left at the original site.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('55062dd2-6935-4716-b703-da8b2b382f2c', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'मध्य प्रदेश की ''भारिया'' जनजाति के संदर्भ में ''पातालकोट'' क्षेत्र किस जिले में स्थित है?', '[{"id":"A","text":"छिंदवाड़ा (Chhindwara)","text_en":"छिंदवाड़ा (Chhindwara)"},{"id":"B","text":"बैतूल (Betul)","text_en":"बैतूल (Betul)"},{"id":"C","text":"मंडला (Mandla)","text_en":"मंडला (Mandla)"},{"id":"D","text":"झाबुआ (Jhabua)","text_en":"झाबुआ (Jhabua)"}]', '0', '✅ **Correct Logic**: पातालकोट छिंदवाड़ा जिले के तामिया विकासखंड में स्थित है, जहाँ भारिया जनजाति निवास करती है।
💡 **Exam Fact**: 1981 की जनगणना में भारियाओं को ''जंगलियों के भी जंगली'' कहा गया था।
🧠 **Memory Tip**: P-C (Patalkot-Chhindwara).
🚫 **Scam Alert**: बैतूल में कोरकू जनजाति की प्रधानता है, भारिया की नहीं।', 2, 0, 1, NULL, 'In which district is the ''Patalkot'' region located with respect to the ''Bharia'' tribe of Madhya Pradesh?', '✅ **Correct Logic**: Patalkot is located in the Tamia block of Chhindwara district, inhabited by the Bharia tribe.
💡 **Exam Fact**: In the 1981 census, Bharias were called ''Wilder than the wild''.
🧠 **Memory Tip**: P-C (Patalkot-Chhindwara).
🚫 **Scam Alert**: Betul is dominated by the Korku tribe, not Bharia.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6f933f9d-595a-48a8-9594-ce7c0d57f31d', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'निम्नलिखित में से कौन सी जनजाति ''दूध लौटावा'' विवाह प्रथा का पालन करती है?', '[{"id":"A","text":"भील (Bheel)","text_en":"भील (Bheel)"},{"id":"B","text":"गोंड (Gond)","text_en":"गोंड (Gond)"},{"id":"C","text":"सहारिया (Sahariya)","text_en":"सहारिया (Sahariya)"},{"id":"D","text":"बैगा (Baiga)","text_en":"बैगा (Baiga)"}]', '1', '✅ **Correct Logic**: गोंड जनजाति में ममेरे-फुफेरे भाई-बहनों के बीच विवाह को प्राथमिकता दी जाती है, जिसे ''दूध लौटावा'' कहते हैं।
💡 **Exam Fact**: गोंड शब्द की उत्पत्ति तेलुगु के ''कोंड'' शब्द से हुई है जिसका अर्थ ''पर्वत'' है।
🧠 **Memory Tip**: G-D (Gond-Doodh Lautawa).
🚫 **Scam Alert**: भील जनजाति में ''गोल गधेड़ो'' प्रथा प्रसिद्ध है, दूध लौटावा नहीं।', 2, 0, 2, NULL, 'Which of the following tribes follows the ''Doodh Lautawa'' marriage custom?', '✅ **Correct Logic**: The Gond tribe prioritizes marriage between cross-cousins, known as ''Doodh Lautawa''.
💡 **Exam Fact**: The word Gond is derived from the Telugu word ''Kond'', meaning ''mountain''.
🧠 **Memory Tip**: G-D (Gond-Doodh Lautawa).
🚫 **Scam Alert**: The Bhil tribe is famous for ''Gol Ghadhedo'', not Doodh Lautawa.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4ad5da2a-9f61-4ce2-ab37-f6f6e5f30459', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'बैगा जनजाति के प्रमुख देवता कौन हैं जो ''साज'' के वृक्ष में निवास करते हैं?', '[{"id":"A","text":"बूढ़ा देव (Budha Dev)","text_en":"बूढ़ा देव (Budha Dev)"},{"id":"B","text":"दूल्हा देव (Dulha Dev)","text_en":"दूल्हा देव (Dulha Dev)"},{"id":"C","text":"लोहासुर (Lohasur)","text_en":"लोहासुर (Lohasur)"},{"id":"D","text":"बड़ा देव (Bada Dev)","text_en":"बड़ा देव (Bada Dev)"}]', '0', '✅ **Correct Logic**: बैगा जनजाति ''बूढ़ा देव'' को अपना प्रमुख देवता मानती है और विश्वास करती है कि वे साज वृक्ष में रहते हैं।
💡 **Exam Fact**: बैगाओं को ''पवित्र पुजारी'' के रूप में भी जाना जाता है।
🧠 **Memory Tip**: B-B (Baiga - Budha Dev).
🚫 **Scam Alert**: लोहापुर अगरिया जनजाति के देवता हैं जो भट्टी में निवास करते हैं।', 2, 0, 3, NULL, 'Who is the primary deity of the Baiga tribe believed to reside in the ''Saaj'' tree?', '✅ **Correct Logic**: The Baiga tribe considers ''Budha Dev'' as their main deity and believes he resides in the Saaj tree.
💡 **Exam Fact**: Baigas are also known as ''Holy Priests''.
🧠 **Memory Tip**: B-B (Baiga - Budha Dev).
🚫 **Scam Alert**: Lohasur is the deity of the Agaria tribe, residing in furnaces.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('baa5deaa-0b23-4c48-b73f-bac2d0cfdddc', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'मध्य प्रदेश की किस जनजाति को ''आदिम जनजाति समूह'' (PVTG) में शामिल नहीं किया गया है?', '[{"id":"A","text":"बैगा (Baiga)","text_en":"बैगा (Baiga)"},{"id":"B","text":"सहारिया (Sahariya)","text_en":"सहारिया (Sahariya)"},{"id":"C","text":"भारिया (Bharia)","text_en":"भारिया (Bharia)"},{"id":"D","text":"कोल (Kol)","text_en":"कोल (Kol)"}]', '3', '✅ **Correct Logic**: MP की तीन जनजातियाँ - बैगा, सहारिया और भारिया PVTG में हैं। कोल इसमें शामिल नहीं है।
💡 **Exam Fact**: भारत में कुल 75 और MP में 3 PVTG हैं।
🧠 **Memory Tip**: B-S-B (Baiga-Sahariya-Bharia).
🚫 **Scam Alert**: कोल मध्य प्रदेश की तीसरी सबसे बड़ी जनजाति है, लेकिन इसे PVTG का दर्जा प्राप्त नहीं है।', 2, 0, 4, NULL, 'Which tribe of MP is NOT included in the ''Particularly Vulnerable Tribal Groups'' (PVTG)?', '✅ **Correct Logic**: Three tribes of MP—Baiga, Sahariya, and Bharia—are in PVTG. Kol is not included.
💡 **Exam Fact**: There are 75 PVTGs in India and 3 in MP.
🧠 **Memory Tip**: B-S-B (Baiga-Sahariya-Bharia).
🚫 **Scam Alert**: Kol is the third largest tribe in MP but does not have PVTG status.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('96f12b7c-82a7-40be-8c31-4eaf3874da43', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'जनजाति और उनके प्रमुख नृत्य को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: भील - भगोरिया, बैगा - परधौनी (विवाह के समय), कोरकू - चटकोरा, भारिया - भड़म/सेतम।
💡 **Exam Fact**: भगोरिया वास्तव में एक उत्सव है जिसमें हाट (बाजार) लगता है।
🧠 **Memory Tip**: K-C (Korku-Chatkora).
🚫 **Scam Alert**: सेला नृत्य बैगा और गोंड दोनों द्वारा किया जाता है, पर भगोरिया केवल भील का है।', 2, 0, 5, NULL, 'Match the tribe with their primary dance:', '✅ **Correct Logic**: Bheel - Bhagoria, Baiga - Pardhauni, Korku - Chatkora, Bharia - Bhadam.
💡 **Exam Fact**: Bhagoria is actually a festival featuring a Haat (market).
🧠 **Memory Tip**: K-C (Korku-Chatkora).
🚫 **Scam Alert**: Saila dance is done by both Baiga and Gond, but Bhagoria is exclusive to Bheel.', 60, 'matching', '[{"id":"(1)","label":"भील","match":"भगोरिया","matchId":"(a)"},{"id":"(2)","label":"बैगा","match":"परधौनी","matchId":"(b)"},{"id":"(3)","label":"कोरकू","match":"चटकोरा","matchId":"(c)"},{"id":"(4)","label":"भारिया","match":"भड़म","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('97bc4195-be21-4af9-9651-4788ad2a0257', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'सहारिया जनजाति का निवास स्थान ''सहराना'' कहलाता है। यह जनजाति मुख्य रूप से किस क्षेत्र में पाई जाती है?', '[{"id":"A","text":"उत्तर-पश्चिम मध्य प्रदेश (North-West MP)","text_en":"उत्तर-पश्चिम मध्य प्रदेश (North-West MP)"},{"id":"B","text":"दक्षिण-पूर्व मध्य प्रदेश (South-East MP)","text_en":"दक्षिण-पूर्व मध्य प्रदेश (South-East MP)"},{"id":"C","text":"मध्य मध्य प्रदेश (Central MP)","text_en":"मध्य मध्य प्रदेश (Central MP)"},{"id":"D","text":"पश्चिमी मध्य प्रदेश (Western MP)","text_en":"पश्चिमी मध्य प्रदेश (Western MP)"}]', '0', '✅ **Correct Logic**: सहारिया जनजाति ग्वालियर, शिवपुरी, गुना और श्योपुर जैसे उत्तर-पश्चिमी जिलों में निवास करती है।
💡 **Exam Fact**: श्योपुर जिले को सहारियाओं की संख्या के कारण ''भारत का इथियोपिया'' (कुपोषण के कारण) भी कहा जाता है।
🧠 **Memory Tip**: S for Sahariya, S for Shivpuri/Sheopur.
🚫 **Scam Alert**: पश्चिमी मध्य प्रदेश भील बहुल है, न कि सहारिया।', 2, 0, 6, NULL, 'The residence of the Sahariya tribe is called ''Saharana''. In which region is this tribe primarily found?', '✅ **Correct Logic**: Sahariya tribe resides in North-Western districts like Gwalior, Shivpuri, Guna, and Sheopur.
💡 **Exam Fact**: Sheopur is often called the ''Ethiopia of India'' due to high malnutrition among Sahariyas.
🧠 **Memory Tip**: S for Sahariya, S for Shivpuri/Sheopur.
🚫 **Scam Alert**: Western MP is dominated by Bheels, not Sahariyas.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ad886951-499e-4938-abe3-5d52d55ae771', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'भील जनजाति में ''दापा'' प्रथा का क्या अर्थ है?', '[{"id":"A","text":"वर पक्ष द्वारा वधू पक्ष को दिया जाने वाला मूल्य","text_en":"वर पक्ष द्वारा वधू पक्ष को दिया जाने वाला मूल्य"},{"id":"B","text":"वधू पक्ष द्वारा वर पक्ष को दिया जाने वाला दहेज","text_en":"वधू पक्ष द्वारा वर पक्ष को दिया जाने वाला दहेज"},{"id":"C","text":"मृत्यु भोज की एक रस्म","text_en":"मृत्यु भोज की एक रस्म"},{"id":"D","text":"खेती करने का एक तरीका","text_en":"खेती करने का एक तरीका"}]', '0', '✅ **Correct Logic**: दापा प्रथा के तहत वर पक्ष को वधू के पिता को कन्या मूल्य देना पड़ता है।
💡 **Exam Fact**: इसे रोकने के लिए ''साथीदार'' अभियान चलाया गया था।
🧠 **Memory Tip**: Dapa = Dena (To give for the bride).
🚫 **Scam Alert**: यह दहेज का उल्टा है, जहाँ लड़का पैसे देता है।', 2, 0, 7, NULL, 'What does the ''Dapa'' custom mean in the Bheel tribe?', '✅ **Correct Logic**: Under Dapa, the groom''s side has to pay a bride price to the father of the bride.
💡 **Exam Fact**: The ''Sathidar'' campaign was launched to curb this practice.
🧠 **Memory Tip**: Dapa = Dena (To give for the bride).
🚫 **Scam Alert**: It is the reverse of dowry, where the boy pays the money.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6a1a9329-9499-4526-881c-b15ae05e5df7', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'गोंड जनजाति की कौन सी उप-जाति लोहे का काम करने वाली मानी जाती है?', '[{"id":"A","text":"प्रधान (Pradhan)","text_en":"प्रधान (Pradhan)"},{"id":"B","text":"अगरिया (Agaria)","text_en":"अगरिया (Agaria)"},{"id":"C","text":"ओझा (Ojha)","text_en":"ओझा (Ojha)"},{"id":"D","text":"सोलहस (Solhas)","text_en":"सोलहस (Solhas)"}]', '1', '✅ **Correct Logic**: अगरिया गोंडों की वह उप-जाति है जो लोहे को गलाकर औजार बनाने का काम करती है।
💡 **Exam Fact**: ओझा तंत्र-मंत्र और प्रधान पूजा-पाठ का काम करते हैं।
🧠 **Memory Tip**: Ag-Agaria (Ag = Fire/Iron work).
🚫 **Scam Alert**: अगरिया और बैगा अलग-अलग जनजातियाँ हैं, हालांकि अगरिया गोंड की भी उपजाति है।', 2, 0, 8, NULL, 'Which sub-caste of the Gond tribe is considered to be iron-smiths?', '✅ **Correct Logic**: Agaria is the sub-caste of Gonds that works as blacksmiths.
💡 **Exam Fact**: Ojha deals with tantra-mantra and Pradhan with priestly duties.
🧠 **Memory Tip**: Ag-Agaria (Ag = Fire/Iron work).
🚫 **Scam Alert**: Agaria and Baiga are distinct, though Agaria is a sub-caste of Gond.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e82a4150-11b5-41b5-a336-cf87c43ea445', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'जनजातियों के संबंध में निम्नलिखित कथनों पर विचार करें:
1. कोल जनजाति मध्य प्रदेश की तीसरी सबसे बड़ी जनजाति है।
2. ''गो हिया'' कोल जनजाति की पंचायत को कहा जाता है।
3. कोल जनजाति मुख्य रूप से रीवा-सीधी क्षेत्र में पाई जाती है।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 3","text_en":"केवल 1 और 3"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '2', '✅ **Correct Logic**: तीनों कथन सही हैं। कोल जनजाति की पंचायत को ''गोहिया'' कहते हैं और यह मुंडा समूह की जनजाति है।
💡 **Exam Fact**: ''कोल दहका'' इनका प्रसिद्ध लोक नृत्य है।
🧠 **Memory Tip**: Kol-Gohiya (KG Class).
🚫 **Scam Alert**: कोरकू की पंचायत और कोल की पंचायत में भ्रमित न हों, कोल की गोहिया है।', 2, 0, 9, NULL, 'Consider the following statements regarding tribes:
1. Kol is the third largest tribe of MP.
2. ''Gohiya'' is the name of the Kol tribe''s panchayat.
3. Kol tribe is mainly found in the Rewa-Sidhi region.

Choose the correct statement:', '✅ **Correct Logic**: All statements are correct. The Kol panchayat is called ''Gohiya'' and they belong to the Munda group.
💡 **Exam Fact**: ''Kol Dahka'' is their famous folk dance.
🧠 **Memory Tip**: Kol-Gohiya (KG Class).
🚫 **Scam Alert**: Do not confuse the panchayats of Korku and Kol; Kol has Gohiya.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('04c2068f-fb76-4953-96e4-156e9123d37f', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'मध्य प्रदेश के झाबुआ में आयोजित होने वाले ''भगोरिया हाट'' में कौन सा पक्ष विवाह का प्रस्ताव ''गुलाल'' लगाकर देता है?', '[{"id":"A","text":"केवल लड़का","text_en":"केवल लड़का"},{"id":"B","text":"केवल लड़की","text_en":"केवल लड़की"},{"id":"C","text":"लड़का और लड़की दोनों","text_en":"लड़का और लड़की दोनों"},{"id":"D","text":"बुजुर्गों द्वारा","text_en":"बुजुर्गों द्वारा"}]', '2', '✅ **Correct Logic**: भगोरिया हाट में यदि लड़का किसी लड़की को गुलाल लगाता है और बदले में लड़की भी गुलाल लगा देती है, तो इसे विवाह की सहमति माना जाता है।
💡 **Exam Fact**: यह होली के उत्सव के समय सात दिनों तक चलता है।
🧠 **Memory Tip**: B-G (Bhagoria-Gulal).
🚫 **Scam Alert**: यह केवल प्रेम विवाह का माध्यम नहीं है, बल्कि एक सामाजिक मिलन का त्योहार है।', 2, 0, 10, NULL, 'In the ''Bhagoria Haat'' held in Jhabua, which side proposes marriage by applying ''Gulal''?', '✅ **Correct Logic**: In Bhagoria Haat, if a boy applies gulal to a girl and she reciprocates, it''s considered consent for marriage.
💡 **Exam Fact**: It lasts for seven days during the Holi festival.
🧠 **Memory Tip**: B-G (Bhagoria-Gulal).
🚫 **Scam Alert**: It is not just about elopement/marriage; it''s a major social gathering.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5054cc8a-3c81-427c-b955-6ced062ce7dc', '0f904fbf-45cc-4965-8ae3-107af61a3e39', '''कुरुक'' (Kurukh) बोली मध्य प्रदेश की किस जनजाति द्वारा मुख्य रूप से बोली जाती है?', '[{"id":"A","text":"उरांव (Oraon)","text_en":"उरांव (Oraon)"},{"id":"B","text":"बंजारा (Banjara)","text_en":"बंजारा (Banjara)"},{"id":"C","text":"पनिका (Panika)","text_en":"पनिका (Panika)"},{"id":"D","text":"कंवर (Kanwar)","text_en":"कंवर (Kanwar)"}]', '0', '✅ **Correct Logic**: उरांव जनजाति की अपनी विशिष्ट बोली ''कुरुक'' है, जो द्रविड़ भाषा परिवार से संबंधित है।
💡 **Exam Fact**: यह जनजाति मुख्य रूप से मध्य प्रदेश के पूर्वी जिलों (अनूपपुर, शहडोल) में पाई जाती है।
🧠 **Memory Tip**: O-K (Oraon-Kurukh).
🚫 **Scam Alert**: बंजारा जनजाति ''लंबानी'' या ''गोरबोली'' बोलती है, कुरुक नहीं।', 2, 0, 1, NULL, 'The ''Kurukh'' dialect is primarily spoken by which tribe of Madhya Pradesh?', '✅ **Correct Logic**: The Oraon tribe has its own distinct dialect called ''Kurukh'', which belongs to the Dravidian language family.
💡 **Exam Fact**: This tribe is mainly found in the eastern districts of MP (Anuppur, Shahdol).
🧠 **Memory Tip**: O-K (Oraon-Kurukh).
🚫 **Scam Alert**: The Banjara tribe speaks ''Lambani'' or ''Gorboli'', not Kurukh.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2df0a905-b95f-48ee-9821-df42c201e8c1', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'निम्नलिखित में से कौन सी बोली ''ऑस्ट्रो-एशियाटिक'' (मुंडा) भाषा परिवार के अंतर्गत आती है?', '[{"id":"A","text":"कोरकू (Korku)","text_en":"कोरकू (Korku)"},{"id":"B","text":"गोंडी (Gondi)","text_en":"गोंडी (Gondi)"},{"id":"C","text":"भीली (Bhili)","text_en":"भीली (Bhili)"},{"id":"D","text":"बैगाली (Baigali)","text_en":"बैगाली (Baigali)"}]', '0', '✅ **Correct Logic**: कोरकू बोली मुंडा भाषा परिवार का हिस्सा है। मध्य प्रदेश में कोरकू और कोल इसी परिवार से संबंधित हैं।
💡 **Exam Fact**: यह बोली बैतूल, होशंगाबाद और छिंदवाड़ा क्षेत्र में प्रचलित है।
🧠 **Memory Tip**: K-M (Korku-Munda).
🚫 **Scam Alert**: गोंडी बोली द्रविड़ परिवार की है, जबकि भीली इंडो-आर्यन परिवार की है।', 2, 0, 2, NULL, 'Which of the following dialects falls under the ''Austro-Asiatic'' (Munda) language family?', '✅ **Correct Logic**: The Korku dialect is part of the Munda language family. In MP, Korku and Kol belong to this family.
💡 **Exam Fact**: This dialect is prevalent in Betul, Hoshangabad, and Chhindwara regions.
🧠 **Memory Tip**: K-M (Korku-Munda).
🚫 **Scam Alert**: Gondi belongs to the Dravidian family, while Bhili is from the Indo-Aryan family.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ee028d3f-9831-4942-828f-5222f2503822', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'भीली बोली के संबंध में ''सर्वेक्षण'' करने वाले पहले भाषाविद् कौन थे, जिन्होंने इसे ''भीली'' नाम दिया?', '[{"id":"A","text":"जी.ए. ग्रियर्सन (G.A. Grierson)","text_en":"जी.ए. ग्रियर्सन (G.A. Grierson)"},{"id":"B","text":"मैक्स मूलर","text_en":"मैक्स मूलर"},{"id":"C","text":"डॉ. धीरेंद्र वर्मा","text_en":"डॉ. धीरेंद्र वर्मा"},{"id":"D","text":"एल.पी. टेसिटोरी","text_en":"एल.पी. टेसिटोरी"}]', '0', '✅ **Correct Logic**: जॉर्ज अब्राहम ग्रियर्सन ने अपने ''भाषाई सर्वेक्षण'' में भीली को एक स्वतंत्र बोली के रूप में पहचाना।
💡 **Exam Fact**: भीली बोली पर गुजराती और राजस्थानी का गहरा प्रभाव है।
🧠 **Memory Tip**: G for Grierson, G for Gujarati influence.
🚫 **Scam Alert**: भीली केवल एक बोली नहीं बल्कि बोलियों का एक समूह है (जैसे बारेली, पाल्या)।', 2, 0, 3, NULL, 'Who was the first linguist to ''survey'' the Bhili dialect and give it the name ''Bhili''?', '✅ **Correct Logic**: George Abraham Grierson identified Bhili as an independent dialect in his ''Linguistic Survey of India''.
💡 **Exam Fact**: Bhili is heavily influenced by Gujarati and Rajasthani.
🧠 **Memory Tip**: G for Grierson, G for Gujarati influence.
🚫 **Scam Alert**: Bhili is not just a single dialect but a group of dialects (like Bareli, Palya).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2fe3bc9c-256f-4f49-a1d4-728893ac8071', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'निम्नलिखित कथनों पर विचार करें:
1. गोंडी बोली द्रविड़ भाषा परिवार की एक सदस्य है।
2. ''परधान'' गोंडों की वह उपजाति है जो गोंडी भाषा में लोक गाथाएं गाती है।
3. गोंडी की अपनी लिपि है जिसे ''गुंजल गोंडी'' कहा जाता है।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '2', '✅ **Correct Logic**: तीनों कथन सही हैं। गोंडी एक समृद्ध भाषा है जिसकी अपनी ऐतिहासिक लिपि (गुंजल) भी खोजी गई है।
💡 **Exam Fact**: मध्य प्रदेश के छिंदवाड़ा, सिवनी और मंडला में यह व्यापक रूप से बोली जाती है।
🧠 **Memory Tip**: G-D (Gondi-Dravidian).
🚫 **Scam Alert**: बहुत से लोग मानते हैं कि जनजातियों की अपनी लिपि नहीं होती, लेकिन गोंडी इसका अपवाद है।', 2, 0, 4, NULL, 'Consider the following statements:
1. Gondi dialect is a member of the Dravidian language family.
2. ''Pradhan'' is the sub-tribe of Gonds that sings folk epics in Gondi.
3. Gondi has its own script called ''Gunjala Gondi''.

Choose the correct statement:', '✅ **Correct Logic**: All three statements are correct. Gondi is a rich language with its own historical script (Gunjala) discovered recently.
💡 **Exam Fact**: It is widely spoken in Chhindwara, Seoni, and Mandla districts of MP.
🧠 **Memory Tip**: G-D (Gondi-Dravidian).
🚫 **Scam Alert**: Many believe tribes don''t have scripts, but Gondi is a notable exception.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('830f2caf-568e-4f71-b857-2a53802141b3', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'जनजाति और उनकी विशिष्ट बोली/भाषा को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: बारेली भीलों की उप-बोली है। दोर्ली दक्षिण मध्य प्रदेश के गोंडों द्वारा बोली जाती है। लंबानी बंजारा की और नहाली कोरकू से संबंधित (लुप्तप्राय) बोली है।
💡 **Exam Fact**: नहाली को अक्सर भाषाविदों द्वारा एक ''भाषा पृथक'' (Language Isolate) माना जाता है।
🧠 **Memory Tip**: L-B (Lambani-Banjara).
🚫 **Scam Alert**: बारेली को बरेली (शहर) से न जोड़ें, यह निमाड़ की भीली बोली है।', 2, 0, 5, NULL, 'Match the tribe and their specific dialect/language:', '✅ **Correct Logic**: Bareli is a sub-dialect of Bhili. Dorli is spoken by Gonds of South MP. Lambani belongs to Banjara, and Nahali is related to Korku.
💡 **Exam Fact**: Nahali is often considered a ''Language Isolate'' by linguists.
🧠 **Memory Tip**: L-B (Lambani-Banjara).
🚫 **Scam Alert**: Don''t link Bareli with Bareilly city; it''s a Bhili dialect of Nimar.', 60, 'matching', '[{"id":"(1)","label":"बारेली (Bareli)","match":"भील","matchId":"(a)"},{"id":"(2)","label":"दोर्ली (Dorli)","match":"गोंड","matchId":"(b)"},{"id":"(3)","label":"लंबानी (Lambani)","match":"बंजारा","matchId":"(c)"},{"id":"(4)","label":"नहाली (Nahali)","match":"कोरकू","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('555df591-39b5-49a6-b813-52efc3e81828', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'पातालकोट के भारियाओं द्वारा बोली जाने वाली बोली को क्या कहा जाता है?', '[{"id":"A","text":"भरियाटी (Bhariyati)","text_en":"भरियाटी (Bhariyati)"},{"id":"B","text":"भर्नोटी (Bharnoti)","text_en":"भर्नोटी (Bharnoti)"},{"id":"C","text":"भरनोती (Bharnoti)","text_en":"भरनोती (Bharnoti)"},{"id":"D","text":"शहरी (Shahari)","text_en":"शहरी (Shahari)"}]', '1', '✅ **Correct Logic**: भारिया जनजाति की बोली को ''भर्नोटी'' कहा जाता है, जिसमें द्रविड़ शब्दों का प्रभाव मिलता है।
💡 **Exam Fact**: पातालकोट के भारिया बाहरी दुनिया से संपर्क कम होने के कारण अपनी मूल बोली को बचाए हुए हैं।
🧠 **Memory Tip**: B-B (Bharia-Bharnoti).
🚫 **Scam Alert**: ''भरियाटी'' जैसा कोई आधिकारिक शब्द भाषा विज्ञान में प्रचलित नहीं है।', 2, 0, 6, NULL, 'What is the dialect spoken by the Bhariyas of Patalkot called?', '✅ **Correct Logic**: The dialect of the Bharia tribe is called ''Bharnoti'', which shows Dravidian influences.
💡 **Exam Fact**: Due to isolation in Patalkot, Bhariyas have preserved their original dialect.
🧠 **Memory Tip**: B-B (Bharia-Bharnoti).
🚫 **Scam Alert**: ''Bhariyati'' is not a standard linguistic term for this dialect.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('69210068-3936-4667-bd5e-c9e10ad9cffd', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'मध्य प्रदेश की ''कोल'' जनजाति की बोली मुख्य रूप से किस भाषा से प्रभावित है?', '[{"id":"A","text":"बघेली","text_en":"बघेली"},{"id":"B","text":"बुंदेली","text_en":"बुंदेली"},{"id":"C","text":"मालवी","text_en":"मालवी"},{"id":"D","text":"निमाड़ी","text_en":"निमाड़ी"}]', '0', '✅ **Correct Logic**: कोल जनजाति बघेलखंड क्षेत्र (रीवा, सतना) में रहती है, इसलिए उनकी बोली पर ''बघेली'' का गहरा प्रभाव है।
💡 **Exam Fact**: हालांकि कोल मुंडा परिवार से हैं, लेकिन अब वे काफी हद तक स्थानीय बघेली को अपना चुके हैं।
🧠 **Memory Tip**: K-B (Kol-Bagheli).
🚫 **Scam Alert**: कोल मुंडा भाषा परिवार के हैं, लेकिन उनकी वर्तमान बोली द्रविड़ परिवार की नहीं है।', 2, 0, 7, NULL, 'The dialect of the ''Kol'' tribe of MP is primarily influenced by which language?', '✅ **Correct Logic**: The Kol tribe resides in the Baghelkhand region (Rewa, Satna), so their dialect is heavily influenced by ''Bagheli''.
💡 **Exam Fact**: Although Kols are from the Munda family, they have largely adopted the local Bagheli.
🧠 **Memory Tip**: K-B (Kol-Bagheli).
🚫 **Scam Alert**: Kols are Austro-Asiatic, but their current spoken tongue is not Dravidian.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9137699f-70aa-4a15-8b41-cc7ee37a8dd2', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'सहारिया जनजाति की बोली पर किस पड़ोसी राज्य की भाषा का सर्वाधिक प्रभाव देखा जाता है?', '[{"id":"A","text":"राजस्थान (Rajasthani)","text_en":"राजस्थान (Rajasthani)"},{"id":"B","text":"महाराष्ट्र (Marathi)","text_en":"महाराष्ट्र (Marathi)"},{"id":"C","text":"गुजरात (Gujarati)","text_en":"गुजरात (Gujarati)"},{"id":"D","text":"छत्तीसगढ़ (Chhattisgarhi)","text_en":"छत्तीसगढ़ (Chhattisgarhi)"}]', '0', '✅ **Correct Logic**: सहारिया जनजाति ग्वालियर-चंबल संभाग में रहती है, जो राजस्थान से सटा है, इसलिए इनकी बोली पर राजस्थानी (हाड़ौती/ब्रज) का प्रभाव है।
💡 **Exam Fact**: इनकी बोली को ''सहारिया'' ही कहा जाता है, जो हिंदी की एक उप-बोली जैसी लगती है।
🧠 **Memory Tip**: S-R (Sahariya-Rajasthan border).
🚫 **Scam Alert**: भीलों पर गुजराती का प्रभाव है, जबकि सहारियाओं पर राजस्थानी का।', 2, 0, 8, NULL, 'The dialect of the Sahariya tribe shows the maximum influence of which neighboring state''s language?', '✅ **Correct Logic**: The Sahariya tribe lives in the Gwalior-Chambal division adjacent to Rajasthan, hence the influence of Rajasthani (Hadoti/Braj).
💡 **Exam Fact**: Their dialect is called ''Sahariya'', which sounds like a sub-dialect of Hindi.
🧠 **Memory Tip**: S-R (Sahariya-Rajasthan border).
🚫 **Scam Alert**: Bhili is influenced by Gujarati, whereas Sahariya is influenced by Rajasthani.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c884fab7-562b-4c37-a956-450debbdfc85', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'मध्य प्रदेश में बोली जाने वाली ''निमाड़ी'' बोली को ''दक्षिणी हिंदी'' किसने कहा था?', '[{"id":"A","text":"जी.ए. ग्रियर्सन","text_en":"जी.ए. ग्रियर्सन"},{"id":"B","text":"डॉ. रामकुमार वर्मा","text_en":"डॉ. रामकुमार वर्मा"},{"id":"C","text":"कामता प्रसाद गुरु","text_en":"कामता प्रसाद गुरु"},{"id":"D","text":"आचार्य रामचंद्र शुक्ल","text_en":"आचार्य रामचंद्र शुक्ल"}]', '0', '✅ **Correct Logic**: ग्रियर्सन ने निमाड़ी की विशेषताओं के कारण इसे ''दक्षिणी हिंदी'' की संज्ञा दी थी।
💡 **Exam Fact**: निमाड़ी को ''मालवी'' की एक उप-बोली भी माना जाता है।
🧠 **Memory Tip**: G-N (Grierson-Nimadi).
🚫 **Scam Alert**: निमाड़ी केवल जनजातियों की नहीं, बल्कि पूरे निमाड़ क्षेत्र की प्रमुख बोली है।', 2, 0, 9, NULL, 'Who called the ''Nimadi'' dialect, spoken in MP, as ''Southern Hindi''?', '✅ **Correct Logic**: Grierson termed Nimadi as ''Southern Hindi'' due to its linguistic characteristics.
💡 **Exam Fact**: Nimadi is also considered a sub-dialect of Malvi.
🧠 **Memory Tip**: G-N (Grierson-Nimadi).
🚫 **Scam Alert**: Nimadi is not just tribal; it is the dominant dialect of the entire Nimar region.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4d8987fa-4f03-4c22-bcdf-a36de3e0598f', '0f904fbf-45cc-4965-8ae3-107af61a3e39', '''बैगाली'' बोली मुख्य रूप से मध्य प्रदेश के किन जिलों में बोली जाती है?', '[{"id":"A","text":"मंडला, बालाघाट, डिंडोरी","text_en":"मंडला, बालाघाट, डिंडोरी"},{"id":"B","text":"झाबुआ, धार, अलीराजपुर","text_en":"झाबुआ, धार, अलीराजपुर"},{"id":"C","text":"ग्वालियर, शिवपुरी, भिंड","text_en":"ग्वालियर, शिवपुरी, भिंड"},{"id":"D","text":"इंदौर, उज्जैन, देवास","text_en":"इंदौर, उज्जैन, देवास"}]', '0', '✅ **Correct Logic**: बैगा जनजाति ''मैकल श्रेणी'' (मंडला, डिंडोरी, बालाघाट) में निवास करती है, जहाँ ''बैगाली'' बोली जाती है।
💡 **Exam Fact**: बैगाली बघेली का ही एक मिश्रित रूप है।
🧠 **Memory Tip**: B-M (Baiga-Mandla).
🚫 **Scam Alert**: बैगा जनजाति पश्चिमी मध्य प्रदेश में नहीं पाई जाती, इसलिए झाबुआ गलत विकल्प है।', 2, 0, 10, NULL, 'The ''Baigali'' dialect is primarily spoken in which districts of MP?', '✅ **Correct Logic**: The Baiga tribe resides in the ''Maikal Range'' (Mandla, Dindori, Balaghat), where ''Baigali'' is spoken.
💡 **Exam Fact**: Baigali is a mixed form of Bagheli.
🧠 **Memory Tip**: B-M (Baiga-Mandla).
🚫 **Scam Alert**: Baigas are not found in Western MP, so Jhabua is an incorrect option.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a4f95629-6f69-40de-a168-8b9774c6b596', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'पूर्वी घाट (Eastern Ghats) की निम्नलिखित पहाड़ियों को उत्तर से दक्षिण (North to South) क्रम में व्यवस्थित करें:
1. शेवरॉय पहाड़ियाँ (Shevaroy Hills)
2. जावदी पहाड़ियाँ (Javadi Hills)
3. पालकोंडा पहाड़ियाँ (Palkonda Hills)
4. सिरुमलाई पहाड़ियाँ (Sirumalai Hills)', '[{"id":"A","text":"3, 2, 1, 4","text_en":"3, 2, 1, 4"},{"id":"B","text":"2, 3, 1, 4","text_en":"2, 3, 1, 4"},{"id":"C","text":"3, 1, 2, 4","text_en":"3, 1, 2, 4"},{"id":"D","text":"2, 1, 3, 4","text_en":"2, 1, 3, 4"}]', '0', '**✅ Correct Logic:** सही क्रम: **पालकोंडा** (आंध्र) → **जावदी** (तमिलनाडु) → **शेवरॉय** (तमिलनाडु, सलेम) → **सिरुमलाई** (तमिलनाडु, डिंडीगुल)।

**💡 Exam Fact:** शेवरॉय पहाड़ियों पर प्रसिद्ध हिल स्टेशन **यercaud** स्थित है। सिरुमलाई पहाड़ियाँ डिंडीगुल में हैं।

**🧠 Memory Tip:** **PJSS** (Palkonda, Javadi, Shevaroy, Sirumalai).

**🚫 Scam Alert:** जावदी और शेवरॉय दोनों तमिलनाडु में हैं, लेकिन जावदी (वेल्लोर) शेवरॉय (सलेम) के उत्तर में है।', 2, 0, 1, NULL, 'Arrange the following hills of the Eastern Ghats in North to South order:
1. Shevaroy Hills
2. Javadi Hills
3. Palkonda Hills
4. Sirumalai Hills', '**✅ Correct Logic:** Correct Order: **Palkonda** (AP) → **Javadi** (TN) → **Shevaroy** (TN, Salem) → **Sirumalai** (TN, Dindigul).

**💡 Exam Fact:** The famous hill station **Yercaud** is located on Shevaroy Hills.

**🧠 Memory Tip:** **PJSS** (Palkonda, Javadi, Shevaroy, Sirumalai).

**🚫 Scam Alert:** Both Javadi and Shevaroy are in TN, but Javadi (Vellore) is North of Shevaroy (Salem).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2bbc5900-c563-4464-9bf6-fcc607a808da', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'प्रायद्वीपीय भारत में ''बाबा बुदन गिरी'' (Baba Budan Giri) पहाड़ियाँ किस अयस्क और फसल के लिए प्रसिद्ध हैं?', '[{"id":"A","text":"मैंगनीज और चाय (Manganese and Tea)","text_en":"मैंगनीज और चाय (Manganese and Tea)"},{"id":"B","text":"लौह अयस्क और कॉफी (Iron Ore and Coffee)","text_en":"लौह अयस्क और कॉफी (Iron Ore and Coffee)"},{"id":"C","text":"बॉक्साइट और रबर (Bauxite and Rubber)","text_en":"बॉक्साइट और रबर (Bauxite and Rubber)"},{"id":"D","text":"तांबा और मसाले (Copper and Spices)","text_en":"तांबा और मसाले (Copper and Spices)"}]', '1', '**✅ Correct Logic:** बाबा बुदन गिरी पहाड़ियाँ (कर्नाटक) **लौह अयस्क** (हेमेटाइट/मैग्नेटाइट) और **कॉफी** की खेती के लिए प्रसिद्ध हैं।

**💡 Exam Fact:** माना जाता है कि बाबा बुदन ने यमन से कॉफी के 7 बीज लाकर यहाँ बोए थे। यहाँ की सबसे ऊंची चोटी **मुल्लायनगिरी** (Mullayanagiri - 1930m) है जो कर्नाटक की सबसे ऊंची चोटी है।

**🧠 Memory Tip:** **Baba ki Coffee** me **Iron** hai.

**🚫 Scam Alert:** कुद्रेमुख भी पास में है और लोहे के लिए प्रसिद्ध है, लेकिन ''कॉफी'' का ऐतिहासिक संबंध बाबा बुदन गिरी से है।', 2, 0, 2, NULL, 'For which ore and crop are the ''Baba Budan Giri'' hills in Peninsular India famous?', '**✅ Correct Logic:** Baba Budan Giri hills (Karnataka) are famous for **Iron Ore** and **Coffee** cultivation.

**💡 Exam Fact:** It is believed Baba Budan brought 7 coffee beans from Yemen. The highest peak here is **Mullayanagiri** (1930m), which is the highest in Karnataka.

**🧠 Memory Tip:** **Baba ki Coffee** me **Iron** hai.

**🚫 Scam Alert:** Kudremukh is also nearby and famous for Iron, but the historical link to ''Coffee'' is with Baba Budan Giri.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c3b71820-8bc2-494b-9352-ecb6b97f96ce', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'गुजरात में स्थित ''मांडव पहाड़ियाँ'' (Mandav Hills) का संबंध किस पर्वतमाला से नहीं है, बल्कि यह एक स्वतंत्र उच्चभूमि है। यह मुख्य रूप से किस जिले में है?', '[{"id":"A","text":"जूनागढ़ (Junagadh)","text_en":"जूनागढ़ (Junagadh)"},{"id":"B","text":"कच्छ (Kutch)","text_en":"कच्छ (Kutch)"},{"id":"C","text":"अमरेली (Amreli)","text_en":"अमरेली (Amreli)"},{"id":"D","text":"सुरेंद्रनगर (Surendranagar)","text_en":"सुरेंद्रनगर (Surendranagar)"}]', '3', '**✅ Correct Logic:** मांडव पहाड़ियाँ काठियावाड़ प्रायद्वीप के मध्य भाग (मुख्य रूप से **सुरेंद्रनगर** और राजकोट सीमा) में स्थित हैं।

**💡 Exam Fact:** गिरनार पहाड़ियाँ (जूनागढ़) मांडव पहाड़ियों से अलग हैं और दक्षिण में हैं। मांडव पहाड़ियों की सबसे ऊंची चोटी ''चोटिला'' (Chotila) है।

**🧠 Memory Tip:** Mandav in MP is famous for Forts, **Mandav** in Gujarat is in **Surendra**nagar.

**🚫 Scam Alert:** मांडव (MP) विंध्याचल में है, लेकिन प्रश्न ''गुजरात'' की मांडव पहाड़ियों के बारे में है। गिरनार से भ्रमित न हों।', 2, 0, 3, NULL, '''Mandav Hills'' located in Gujarat are not related to any major mountain range but are an independent highland. In which district are they mainly located?', '**✅ Correct Logic:** Mandav Hills are located in the central part of Kathiawar peninsula (mainly **Surendranagar**). 

**💡 Exam Fact:** Girnar Hills (Junagadh) are distinct from Mandav and lie to the south. The highest point of Mandav hills is ''Chotila''.

**🧠 Memory Tip:** Mandav in MP is famous for Forts, **Mandav** in Gujarat is in **Surendra**nagar.

**🚫 Scam Alert:** Mandav (MP) is in Vindhyas, but the question is about ''Gujarat''s'' Mandav Hills. Do not confuse with Girnar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0dcdc761-5982-4848-a40d-3d1d004729de', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', '''बरैल रेंज'' (Barail Range) पूर्वोत्तर भारत में एक महत्वपूर्ण विभाजक है। यह किन दो पहाड़ियों को अलग करती है?', '[{"id":"A","text":"गारो और खासी पहाड़ियाँ (Garo and Khasi Hills)","text_en":"गारो और खासी पहाड़ियाँ (Garo and Khasi Hills)"},{"id":"B","text":"नागा और मणिपुर पहाड़ियाँ (Naga and Manipur Hills)","text_en":"नागा और मणिपुर पहाड़ियाँ (Naga and Manipur Hills)"},{"id":"C","text":"मिज़ो और त्रिपुरा पहाड़ियाँ (Mizo and Tripura Hills)","text_en":"मिज़ो और त्रिपुरा पहाड़ियाँ (Mizo and Tripura Hills)"},{"id":"D","text":"डाफला और मिरी पहाड़ियाँ (Dafla and Miri Hills)","text_en":"डाफला और मिरी पहाड़ियाँ (Dafla and Miri Hills)"}]', '1', '**✅ Correct Logic:** बरैल रेंज असम, मणिपुर और नागालैंड की सीमा पर है। यह संरचनात्मक रूप से **नागा पहाड़ियों** (उत्तर) और **मणिपुर पहाड़ियों** (दक्षिण) को जोड़ती भी है और उनके बीच एक संक्रमण क्षेत्र बनाती है। यह ब्रह्मपुत्र और बराक बेसिन को भी अलग करती है।

**💡 Exam Fact:** यह पूर्वांचल हिमालय और मेघालय पठार के बीच की कड़ी भी मानी जाती है।

**🧠 Memory Tip:** **Barail** is the **Barrier** between Naga (North) and Manipur (South).

**🚫 Scam Alert:** गारो-खासी-जयंतिया मेघालय पठार का हिस्सा हैं, बरैल रेंज उनके पूर्व में स्थित है।', 2, 0, 4, NULL, '''Barail Range'' is an important divider in Northeast India. It separates which two hills?', '**✅ Correct Logic:** Barail range is on the border of Assam, Manipur, and Nagaland. Structurally, it separates/connects the **Naga Hills** (North) and **Manipur Hills** (South). It also acts as a water divide between Brahmaputra and Barak basins.

**💡 Exam Fact:** It is considered the link between Purvanchal Himalayas and Meghalaya Plateau.

**🧠 Memory Tip:** **Barail** is the **Barrier** between Naga (North) and Manipur (South).

**🚫 Scam Alert:** Garo-Khasi-Jaintia are part of Meghalaya Plateau; Barail is to their East.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9de87fc1-0c22-42da-b7cf-dd866aa37667', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'महाराष्ट्र की निम्नलिखित पर्वत श्रेणियों को उत्तर से दक्षिण (North to South) क्रम में लगाइए:
1. अजंता श्रेणी (Ajanta Range)
2. हरिश्चंद्र श्रेणी (Harishchandra Range)
3. सातमाला श्रेणी (Satmala Range)', '[{"id":"A","text":"1, 3, 2","text_en":"1, 3, 2"},{"id":"B","text":"1, 2, 3","text_en":"1, 2, 3"},{"id":"C","text":"3, 1, 2","text_en":"3, 1, 2"},{"id":"D","text":"3, 2, 1","text_en":"3, 2, 1"}]', '0', '**✅ Correct Logic:** सही क्रम: **अजंता** (ताप्ती और गोदावरी के बीच) → **सातमाला** (नासिक के पास) → **हरिश्चंद्र** (गोदावरी और भीमा के बीच)।

**💡 Exam Fact:** हरिश्चंद्र श्रेणी गोदावरी और भीमा नदी घाटियों के बीच जल विभाजक (Water Divide) का कार्य करती है।

**🧠 Memory Tip:** **A**a **S**aat **H**aris (Ajanta -> Satmala -> Harishchandra).

**🚫 Scam Alert:** सातमाला और अजंता अक्सर समानांतर दिखती हैं, लेकिन अजंता का विस्तार अधिक उत्तर (औरंगाबाद) की ओर है।', 2, 0, 5, NULL, 'Arrange the following mountain ranges of Maharashtra in North to South order:
1. Ajanta Range
2. Harishchandra Range
3. Satmala Range', '**✅ Correct Logic:** Correct Order: **Ajanta** (Between Tapti & Godavari) → **Satmala** (Near Nashik) → **Harishchandra** (Between Godavari & Bhima).

**💡 Exam Fact:** Harishchandra range acts as a water divide between Godavari and Bhima river basins.

**🧠 Memory Tip:** **A**a **S**aat **H**aris (Ajanta -> Satmala -> Harishchandra).

**🚫 Scam Alert:** Satmala and Ajanta often look parallel, but Ajanta extends more northerly (Aurangabad).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a008cdf2-22b1-4456-9556-a8a3708e2f16', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', '''शेषाचलम पहाड़ियाँ'' (Seshachalam Hills), जो भारत का पहला बायोस्फीयर रिजर्व भी घोषित किया गया था (दक्षिण भारत में), किस पर्वत श्रृंखला का हिस्सा हैं?', '[{"id":"A","text":"पश्चिमी घाट (Western Ghats)","text_en":"पश्चिमी घाट (Western Ghats)"},{"id":"B","text":"पूर्वी घाट (Eastern Ghats)","text_en":"पूर्वी घाट (Eastern Ghats)"},{"id":"C","text":"सतपुड़ा (Satpura)","text_en":"सतपुड़ा (Satpura)"},{"id":"D","text":"नीलगिरी (Nilgiri)","text_en":"नीलगिरी (Nilgiri)"}]', '1', '**✅ Correct Logic:** शेषाचलम पहाड़ियाँ **पूर्वी घाट** (आंध्र प्रदेश के कडपा और चित्तूर जिलों में) का हिस्सा हैं।

**💡 Exam Fact:** यह क्षेत्र **लाल चंदन** (Red Sanders) के लिए विश्व प्रसिद्ध है। तिरुपति मंदिर इन्हीं पहाड़ियों पर स्थित है।

**🧠 Memory Tip:** **Pushpa** movie (Red Sanders) -> Seshachalam -> Eastern Ghats.

**🚫 Scam Alert:** नीलगिरी और पश्चिमी घाट बायोस्फीयर रिजर्व के लिए प्रसिद्ध हैं, लेकिन शेषाचलम विशेष रूप से पूर्वी घाट में है और अलग बायोस्फीयर रिजर्व (2010) है।', 2, 0, 6, NULL, '''Seshachalam Hills'', which was also declared a Biosphere Reserve (in South India), is part of which mountain range?', '**✅ Correct Logic:** Seshachalam Hills are part of the **Eastern Ghats** (Kadapa and Chittoor districts of AP).

**💡 Exam Fact:** This region is world-famous for **Red Sanders** (Rakt Chandan). Tirupati temple is located on these hills.

**🧠 Memory Tip:** **Pushpa** movie (Red Sanders) -> Seshachalam -> Eastern Ghats.

**🚫 Scam Alert:** Nilgiris are famous Biosphere Reserves, but Seshachalam is distinct, in the Eastern Ghats, and designated in 2010.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b4902352-31ea-4b2a-afc1-df3706ca7f3f', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'निम्नलिखित में से कौन सी पहाड़ियाँ ''मेघालय पठार'' का हिस्सा **नहीं** हैं, बल्कि असम हिमालय का हिस्सा मानी जाती हैं?', '[{"id":"A","text":"गारो पहाड़ियाँ (Garo Hills)","text_en":"गारो पहाड़ियाँ (Garo Hills)"},{"id":"B","text":"खासी पहाड़ियाँ (Khasi Hills)","text_en":"खासी पहाड़ियाँ (Khasi Hills)"},{"id":"C","text":"मिकिर पहाड़ियाँ (Mikir Hills)","text_en":"मिकिर पहाड़ियाँ (Mikir Hills)"},{"id":"D","text":"जयंतिया पहाड़ियाँ (Jaintia Hills)","text_en":"जयंतिया पहाड़ियाँ (Jaintia Hills)"}]', '2', '**✅ Correct Logic:** **मिकिर पहाड़ियाँ** (और रेंगमा पहाड़ियाँ) असम में हैं और भूगर्भीय रूप से मेघालय पठार (कार्बी-एंगलोंग पठार) का विस्तार मानी जाती हैं, लेकिन अक्सर वर्गीकरण में ''मिकिर'' को ब्रह्मपुत्र के दक्षिण में अलग पहाड़ी माना जाता है, जबकि गारो-खासी-जयंतिया मुख्य मेघालय पठार ब्लॉक हैं। *Wait, correction for Exam Clarity:* मिकिर पहाड़ियाँ **प्रायद्वीपीय पठार** (Peninsular Shield) का ही हिस्सा हैं (कार्बी एंगलोंग), न कि हिमालय का। लेकिन प्रश्न पूछता है मेघालय पठार का मुख्य हिस्सा नहीं? गारो, खासी, जयंतिया एक साथ हैं। मिकिर अलग है (असम में)।
*Better Logic based on standard MCQs:* मिकिर पहाड़ियाँ **असम** में हैं (काजीरंगा के दक्षिण में), जबकि गारो-खासी-जयंतिया **मेघालय** राज्य में हैं।', 2, 0, 7, NULL, 'Which of the following hills are **NOT** part of the ''Meghalaya Plateau'' but are considered part of the Assam Himalayas/Purvanchal?', '**✅ Correct Logic:** **Mikir Hills** are in **Assam** (south of Kaziranga), whereas Garo, Khasi, and Jaintia hills constitute the main block of the **Meghalaya** state. While geologically Mikir is also an extension of the Peninsular block (Karbi Anglong), geographically it is detached from the main Meghalaya plateau block.

**💡 Exam Fact:** Mikir Hills are famous for hot springs and are surrounded by the Brahmaputra bend.

**🧠 Memory Tip:** Garo-Khasi-Jaintia are the 3 sisters of Meghalaya. Mikir is the cousin in Assam.

**🚫 Scam Alert:** All are peninsular extensions geologically, but politically and geographically, Mikir is distinct from the Meghalaya trio.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('09f7317d-3c50-4219-87bc-2a183ba81f88', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'झारखंड में स्थित ''पारसनाथ पहाड़ी'' (Parasnath Hill) किस पठार/पहाड़ी श्रृंखला का सर्वोच्च शिखर है?', '[{"id":"A","text":"हजारीबाग पठार (Hazaribagh Plateau)","text_en":"हजारीबाग पठार (Hazaribagh Plateau)"},{"id":"B","text":"राजमहल पहाड़ियाँ (Rajmahal Hills)","text_en":"राजमहल पहाड़ियाँ (Rajmahal Hills)"},{"id":"C","text":"कोडरमा पठार (Koderma Plateau)","text_en":"कोडरमा पठार (Koderma Plateau)"},{"id":"D","text":"कैमूर रेंज (Kaimur Range)","text_en":"कैमूर रेंज (Kaimur Range)"}]', '0', '**✅ Correct Logic:** पारसनाथ (सम्मेद शिखर) **हजारीबाग पठार** (छोटा नागपुर पठार का हिस्सा) की सबसे ऊंची चोटी (1370 मी) है।

**💡 Exam Fact:** यह जैन धर्म का सबसे महत्वपूर्ण तीर्थ स्थल है (24 में से 20 तीर्थंकरों को यहाँ मोक्ष मिला)।

**🧠 Memory Tip:** **Paras** stone turns iron to gold -> Found in Mineral rich Hazaribagh/Chotanagpur.

**🚫 Scam Alert:** राजमहल पहाड़ियाँ भी झारखंड में हैं, लेकिन पारसनाथ हजारीबाग पठार (गिरीडीह जिला) का हिस्सा है।', 2, 0, 8, NULL, '''Parasnath Hill'' in Jharkhand is the highest peak of which plateau/hill range?', '**✅ Correct Logic:** Parasnath (Sammed Shikhar) is the highest peak (1370m) of the **Hazaribagh Plateau** (part of Chota Nagpur).

**💡 Exam Fact:** It is the most important pilgrimage site for Jains (20 out of 24 Tirthankaras attained salvation here).

**🧠 Memory Tip:** **Paras** stone turns iron to gold -> Found in Mineral rich Hazaribagh/Chotanagpur.

**🚫 Scam Alert:** Rajmahal hills are also in Jharkhand, but Parasnath belongs to the Hazaribagh plateau (Giridih district).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4057e251-52b7-4967-8e6b-3954ba813618', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', '''डालमा पहाड़ियाँ'' (Dalma Hills) मुख्य रूप से किस राज्य में स्थित हैं और अपनी किस विशेषता के लिए जानी जाती हैं?', '[{"id":"A","text":"ओडिशा - बॉक्साइट खदानें (Odisha - Bauxite Mines)","text_en":"ओडिशा - बॉक्साइट खदानें (Odisha - Bauxite Mines)"},{"id":"B","text":"झारखंड - ज्वालामुखी उद्गम (Jharkhand - Volcanic Origin)","text_en":"झारखंड - ज्वालामुखी उद्गम (Jharkhand - Volcanic Origin)"},{"id":"C","text":"पश्चिम बंगाल - चाय बागान (West Bengal - Tea Gardens)","text_en":"पश्चिम बंगाल - चाय बागान (West Bengal - Tea Gardens)"},{"id":"D","text":"छत्तीसगढ़ - लौह अयस्क (Chhattisgarh - Iron Ore)","text_en":"छत्तीसगढ़ - लौह अयस्क (Chhattisgarh - Iron Ore)"}]', '1', '**✅ Correct Logic:** डालमा पहाड़ियाँ **झारखंड** (जमशेदपुर के पास) में हैं। ये **ज्वालामुखी उद्गम** (Volcanic origin) की मानी जाती हैं और यहाँ डालमा वन्यजीव अभयारण्य (हाथियों के लिए) स्थित है।

**💡 Exam Fact:** डालमा ट्रैप (Dalma Trap) का निर्माण प्री-कैम्ब्रियन युग में ज्वालामुखी गतिविधियों से हुआ था।

**🧠 Memory Tip:** **Dalma** -> **Dam**aka (Explosion/Volcano) -> Jharkhand.

**🚫 Scam Alert:** ओडिशा की पहाड़ियों (जैसे गंधमर्दन) के साथ भ्रमित न हों।', 2, 0, 9, NULL, '''Dalma Hills'' are primarily located in which state and are known for which feature?', '**✅ Correct Logic:** Dalma Hills are in **Jharkhand** (near Jamshedpur). They are of **Volcanic Origin** and host the Dalma Wildlife Sanctuary (famous for Elephants).

**💡 Exam Fact:** Dalma Trap was formed by volcanic activities in the Pre-Cambrian era.

**🧠 Memory Tip:** **Dalma** -> **Dam**aka (Explosion/Volcano) -> Jharkhand.

**🚫 Scam Alert:** Do not confuse with hills of Odisha (like Gandhamardan).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fb677b96-e418-49fe-952d-5d683b9e0fb1', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'निम्नलिखित पहाड़ियों को संबंधित राज्यों से सुमेलित करें (Match the following hills with their respective states):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)","text_en":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **अबुझमाड़** (छत्तीसगढ़ का चेरापूंजी कहा जाता है) -> (1)-(b)
* **मलयगिरी** (गढ़जात पहाड़ियाँ, ओडिशा की ऊंची चोटी) -> (2)-(a)
* **रामगढ़ पहाड़ियाँ** (राजमहल ट्रैप का हिस्सा, झारखंड में एक अलग रामगढ़ क्रेटर राजस्थान में भी है, लेकिन पहाड़ियों के संदर्भ में और विकल्पों को देखते हुए झारखंड सही है। *Note: Ramgarh is a district in Jharkhand too*) -> (3)-(d)
* **बिलीगिरि रंगन हिल्स (BR Hills)** (पूर्वी और पश्चिमी घाट का संगम, कर्नाटक) -> (4)-(c)

**💡 Exam Fact:** BR Hills (कर्नाटक) में बाघ अभयारण्य भी है।

**🧠 Memory Tip:** **Abujh** (Unsolved puzzle) is in Naxal area (CG). **Malaya** is in Odisha. **BR** is in Karnataka.

**🚫 Scam Alert:** रामगढ़ क्रेटर (उल्कापिंड वाला) राजस्थान में है, लेकिन रामगढ़ की पहाड़ियाँ/कोयला क्षेत्र झारखंड में प्रसिद्ध हैं।', 2, 0, 10, NULL, 'Match the following hills with their respective states:', '**✅ Correct Matching:**
* **Abujhmar** (Called Cherrapunji of Chhattisgarh) -> (1)-(b)
* **Malayagiri** (Garhjat Hills, Odisha) -> (2)-(a)
* **Ramgarh Hills** (Part of Jharkhand, Ramgarh district) -> (3)-(d)
* **Biligiri Rangan Hills (BR Hills)** (Junction of E & W Ghats, Karnataka) -> (4)-(c)

**💡 Exam Fact:** BR Hills (Karnataka) is also a Tiger Reserve.

**🧠 Memory Tip:** **Abujh** (Unsolved puzzle) is in CG. **Malaya** is in Odisha. **BR** is in Karnataka.

**🚫 Scam Alert:** Ramgarh Crater (Meteorite) is in Rajasthan, but Ramgarh Hills/Coal fields are famous in Jharkhand.', 60, 'matching', '[{"id":"(1)","label":"अबुझमाड़ पहाड़ियाँ (Abujhmar Hills)","match":"ओडिशा (Odisha)","matchId":"(a)"},{"id":"(2)","label":"मलयगिरी (Malayagiri)","match":"छत्तीसगढ़ (Chhattisgarh)","matchId":"(b)"},{"id":"(3)","label":"रामगढ़ पहाड़ियाँ (Ramgarh Hills)","match":"कर्नाटक (Karnataka)","matchId":"(c)"},{"id":"(4)","label":"बिलीगिरि रंगन हिल्स (BR Hills)","match":"झारखंड (Jharkhand)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0289b6f5-e977-4c60-895b-6b419db3c87e', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'छोटा नागपुर पठार में ''पैट भूमि'' (Patlands) क्या है?', '[{"id":"A","text":"निचली नदी घाटियाँ (Lower River Valleys)","text_en":"निचली नदी घाटियाँ (Lower River Valleys)"},{"id":"B","text":"समतल शीर्ष वाले लेटेराइट पठार (Flat-topped Laterite Plateaus)","text_en":"समतल शीर्ष वाले लेटेराइट पठार (Flat-topped Laterite Plateaus)"},{"id":"C","text":"जलोढ़ मैदान (Alluvial Plains)","text_en":"जलोढ़ मैदान (Alluvial Plains)"},{"id":"D","text":"हिमनद निक्षेप (Glacial Deposits)","text_en":"हिमनद निक्षेप (Glacial Deposits)"}]', '1', '**✅ Correct Logic:** **पैट भूमि** (Pat Region) छोटा नागपुर पठार का पश्चिमी भाग है (नेतरहाट के पास)। यह ऊंचे, **समतल शीर्ष वाले (Flat-topped)** मेसा (Mesa) जैसी संरचनाएं हैं जो **लेटेराइट** (Laterite) से ढकी होती हैं।

**💡 Exam Fact:** नेतरहाट (छोटा नागपुर की रानी) एक ''पैट'' है। बॉक्साइट यहाँ प्रचुर मात्रा में मिलता है।

**🧠 Memory Tip:** **Pat** means Flat board/Slate -> Flat topped hill.

**🚫 Scam Alert:** यह नदी घाटी नहीं, बल्कि पठार का सबसे ऊंचा हिस्सा (पारसनाथ को छोड़कर) है।', 2, 0, 1, NULL, 'What are ''Patlands'' in the Chota Nagpur Plateau?', '**✅ Correct Logic:** **Patlands** are the western part of Chota Nagpur Plateau (near Netarhat). These are high, **Flat-topped** mesa-like structures capped with **Laterite**.

**💡 Exam Fact:** Netarhat (Queen of Chota Nagpur) is a ''Pat''. Bauxite is abundant here.

**🧠 Memory Tip:** **Pat** means Flat board -> Flat topped hill.

**🚫 Scam Alert:** It is not a valley, but the highest flat surface of the plateau.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c03990cf-eb60-4947-b08f-8dd525618717', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'निम्नलिखित कथनों पर विचार करें:
1. मालदा गैप (Malda Gap) मेघालय पठार को प्रायद्वीपीय भारत से अलग करता है।
2. मालदा गैप का निर्माण गंगा और ब्रह्मपुत्र नदियों के अवसादन (Sedimentation) से भर जाने वाले भ्रंश (Fault) के कारण हुआ है।
सही कथन चुनें:', '[{"id":"A","text":"केवल 1 (Only 1)","text_en":"केवल 1 (Only 1)"},{"id":"B","text":"केवल 2 (Only 2)","text_en":"केवल 2 (Only 2)"},{"id":"C","text":"1 और 2 दोनों (Both 1 and 2)","text_en":"1 और 2 दोनों (Both 1 and 2)"},{"id":"D","text":"ना तो 1 ना ही 2 (Neither 1 nor 2)","text_en":"ना तो 1 ना ही 2 (Neither 1 nor 2)"}]', '2', '**✅ Correct Logic:** दोनों कथन सही हैं। मेघालय पठार (और कार्बी एंगलोंग) भारतीय प्रायद्वीप का ही विस्तार है। बीच में **राजमहल-गारो गैप** (या मालदा गैप) नामक एक भ्रंश (Down-warping) बन गया था, जिसे बाद में गंगा-ब्रह्मपुत्र ने भर दिया।

**💡 Exam Fact:** इसे ''गारो-राजमहल गैप'' भी कहते हैं क्योंकि यह पश्चिम में राजमहल और पूर्व में गारो पहाड़ियों के बीच है।

**🧠 Memory Tip:** **Gap** was filled by **Ganga**.

**🚫 Scam Alert:** कई छात्र सोचते हैं मेघालय हिमालय का हिस्सा है, लेकिन यह गैप साबित करता है कि यह प्रायद्वीप का टूटा हुआ हिस्सा है।', 2, 0, 2, NULL, 'Consider the following statements:
1. Malda Gap separates the Meghalaya Plateau from Peninsular India.
2. Malda Gap was formed due to a fault that was filled by sedimentation from Ganga and Brahmaputra rivers.
Choose the correct statement:', '**✅ Correct Logic:** Both statements are correct. Meghalaya Plateau is an extension of the Peninsular block. A fault (down-warping) called **Rajmahal-Garo Gap** (or Malda Gap) was created, which was later filled by Ganga-Brahmaputra sediments.

**💡 Exam Fact:** Also called ''Garo-Rajmahal Gap'' as it lies between Rajmahal (West) and Garo (East).

**🧠 Memory Tip:** **Gap** was filled by **Ganga**.

**🚫 Scam Alert:** Many students think Meghalaya is part of Himalayas, but this Gap proves it is a detached part of the Peninsula.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e48bd7a1-0022-4b3d-a459-fa2e693ac1f9', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'बुंदेलखंड पठार (Bundelkhand Plateau) की भूगर्भीय संरचना मुख्य रूप से किस चट्टान से बनी है, जिसके कारण यहाँ जल धारण क्षमता कम है?', '[{"id":"A","text":"बेसाल्ट (Basalt)","text_en":"बेसाल्ट (Basalt)"},{"id":"B","text":"ग्रेनाइट और नीस (Granite and Gneiss)","text_en":"ग्रेनाइट और नीस (Granite and Gneiss)"},{"id":"C","text":"चूना पत्थर (Limestone)","text_en":"चूना पत्थर (Limestone)"},{"id":"D","text":"बलुआ पत्थर (Sandstone)","text_en":"बलुआ पत्थर (Sandstone)"}]', '1', '**✅ Correct Logic:** बुंदेलखंड पठार प्राचीन **ग्रेनाइट और नीस** (Granite and Gneiss) चट्टानों से बना है। ये कठोर और अपारगम्य (impervious) होती हैं, जिससे भूजल (Groundwater) का रिसाव नहीं हो पाता, अतः यह सूखाग्रस्त क्षेत्र है।

**💡 Exam Fact:** चंबल और यमुना के बीहड़ (Ravines) इसी क्षेत्र (और आस-पास के जलोढ़) में बने हैं।

**🧠 Memory Tip:** **Bundel**khand is hard like **Granite** -> No water.

**🚫 Scam Alert:** बेसाल्ट दक्कन ट्रैप (मालवा) में है, बुंदेलखंड में ग्रेनाइट है।', 2, 0, 3, NULL, 'The geological structure of Bundelkhand Plateau is mainly composed of which rock, leading to low water retention capacity?', '**✅ Correct Logic:** Bundelkhand Plateau is made of ancient **Granite and Gneiss**. These are hard and impervious, preventing groundwater percolation, making it a drought-prone region.

**💡 Exam Fact:** Ravines of Chambal and Yamuna are formed in this region (and nearby alluvium).

**🧠 Memory Tip:** **Bundel**khand is hard like **Granite** -> No water.

**🚫 Scam Alert:** Basalt is in Deccan Trap (Malwa), Bundelkhand is Granite.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0b824721-0360-4dc5-add4-14bb6ccda9f4', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'दंडकारण्य पठार (Dandakaranya Plateau) भारत के किस हिस्से में स्थित है और यह किस नदी का बेसिन है?', '[{"id":"A","text":"मध्य-पूर्व भारत (इंद्रावती नदी) - Central-East India (Indravati River)","text_en":"मध्य-पूर्व भारत (इंद्रावती नदी) - Central-East India (Indravati River)"},{"id":"B","text":"दक्षिण भारत (कावेरी नदी) - South India (Kaveri River)","text_en":"दक्षिण भारत (कावेरी नदी) - South India (Kaveri River)"},{"id":"C","text":"पश्चिम भारत (माही नदी) - West India (Mahi River)","text_en":"पश्चिम भारत (माही नदी) - West India (Mahi River)"},{"id":"D","text":"उत्तर भारत (सोन नदी) - North India (Son River)","text_en":"उत्तर भारत (सोन नदी) - North India (Son River)"}]', '0', '**✅ Correct Logic:** दंडकारण्य पठार छत्तीसगढ़ (बस्तर), ओडिशा और आंध्र प्रदेश के कुछ हिस्सों में फैला है। यह मुख्य रूप से **इंद्रावती नदी** (गोदावरी की सहायक) का बेसिन है।

**💡 Exam Fact:** बैलाडीला (Bailadila) की लौह अयस्क खदानें और भारत का एकमात्र टिन (Tin) उत्पादक क्षेत्र इसी पठार में है।

**🧠 Memory Tip:** **Danda** (Punishment) given in **Bastar** jungles near **Indravati**.

**🚫 Scam Alert:** सोन नदी बघेलखंड में है, दंडकारण्य में नहीं।', 2, 0, 4, NULL, 'Dandakaranya Plateau is located in which part of India and is the basin of which river?', '**✅ Correct Logic:** Dandakaranya Plateau spans across Chhattisgarh (Bastar), Odisha, and AP. It is primarily the basin of the **Indravati River** (Tributary of Godavari).

**💡 Exam Fact:** Bailadila iron ore mines and India''s only Tin producing region are in this plateau.

**🧠 Memory Tip:** **Danda** (Punishment) given in **Bastar** jungles near **Indravati**.

**🚫 Scam Alert:** Son river is in Baghelkhand, not Dandakaranya.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0661f8fa-da3e-4fa9-abef-e50fc5b3039b', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'दक्कन ट्रैप (Deccan Trap) के निर्माण के संदर्भ में, यह घटना किस काल (Period) से संबंधित है?', '[{"id":"A","text":"प्री-कैम्ब्रियन (Pre-Cambrian)","text_en":"प्री-कैम्ब्रियन (Pre-Cambrian)"},{"id":"B","text":"क्रिटेशियस-टर्शियरी (Cretaceous-Tertiary)","text_en":"क्रिटेशियस-टर्शियरी (Cretaceous-Tertiary)"},{"id":"C","text":"कार्बोनिफेरस (Carboniferous)","text_en":"कार्बोनिफेरस (Carboniferous)"},{"id":"D","text":"जुरासिक (Jurassic)","text_en":"जुरासिक (Jurassic)"}]', '1', '**✅ Correct Logic:** दक्कन ट्रैप का निर्माण **क्रिटेशियस काल के अंत और टर्शियरी काल के प्रारंभ** (लगभग 66 मिलियन वर्ष पूर्व) में हुआ था, जब भारत ''रीयूनियन हॉटस्पॉट'' (Reunion Hotspot) के ऊपर से गुजर रहा था।

**💡 Exam Fact:** यह बेसाल्टिक लावा प्रवाह सीढ़ीनुमा (Step-like) आकृति बनाता है, इसलिए इसे ''ट्रैप'' (स्वीडिश शब्द ''Trappa'' = सीढ़ियाँ) कहते हैं।

**🧠 Memory Tip:** Dinosaurs died in **Cretaceous**, Deccan Trap formed in **Cretaceous**. (Mass extinction link).

**🚫 Scam Alert:** धारवाड़ चट्टानें प्री-कैम्ब्रियन हैं, गोंडवाना कोयला कार्बोनिफेरस/जुरासिक का है, लेकिन दक्कन लावा क्रिटेशियस है।', 2, 0, 5, NULL, 'With reference to the formation of the Deccan Trap, to which period does this event belong?', '**✅ Correct Logic:** Deccan Trap was formed during the **Late Cretaceous and early Tertiary** period (approx 66 mya) when India moved over the ''Reunion Hotspot''.

**💡 Exam Fact:** The basaltic lava flow creates a step-like structure, hence called ''Trap'' (Swedish word ''Trappa'' = Stairs).

**🧠 Memory Tip:** Dinosaurs died in **Cretaceous**, Deccan Trap formed in **Cretaceous**.

**🚫 Scam Alert:** Dharwar rocks are Pre-Cambrian, Gondwana coal is Carboniferous/Jurassic, but Deccan Lava is Cretaceous.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('99ef7d5e-1760-464f-883e-168f63c93fdd', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'मेवाड़ पठार (Mewar Plateau) अरावली और मालवा पठार के बीच स्थित है। यह किस नदी अपवाह तंत्र (Drainage System) का हिस्सा है?', '[{"id":"A","text":"बनास नदी (Banas River)","text_en":"बनास नदी (Banas River)"},{"id":"B","text":"लूनी नदी (Luni River)","text_en":"लूनी नदी (Luni River)"},{"id":"C","text":"साबरमती नदी (Sabarmati River)","text_en":"साबरमती नदी (Sabarmati River)"},{"id":"D","text":"नर्मदा नदी (Narmada River)","text_en":"नर्मदा नदी (Narmada River)"}]', '0', '**✅ Correct Logic:** मेवाड़ पठार (पूर्वी राजस्थान) मुख्य रूप से **बनास नदी** (चंबल की सहायक) द्वारा अपवाहित (Drained) होता है।

**💡 Exam Fact:** बनास को ''वन की आशा'' (Hope of the Forest) भी कहा जाता है।

**🧠 Memory Tip:** **Mewar** warriors lived in **Ban** (Forest/Banas).

**🚫 Scam Alert:** लूनी पश्चिमी राजस्थान (मरुस्थल) में बहती है, मेवाड़ (पठार) में बनास प्रमुख है।', 2, 0, 6, NULL, 'Mewar Plateau lies between Aravali and Malwa Plateau. It is part of which river drainage system?', '**✅ Correct Logic:** Mewar Plateau (Eastern Rajasthan) is primarily drained by the **Banas River** (Tributary of Chambal).

**💡 Exam Fact:** Banas is also known as ''Van Ki Asha'' (Hope of the Forest).

**🧠 Memory Tip:** **Mewar** warriors lived in **Ban** (Forest/Banas).

**🚫 Scam Alert:** Luni flows in West Rajasthan (Desert), whereas Banas flows in Mewar (Plateau).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8990f60c-a79a-43fd-a317-e3cb57daf96b', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'छोटा नागपुर पठार में ''दामोदर भ्रंश'' (Damodar Trough) किन दो सूक्ष्म पठारों को अलग करता है?', '[{"id":"A","text":"हजारीबाग और कोडरमा (Hazaribagh and Koderma)","text_en":"हजारीबाग और कोडरमा (Hazaribagh and Koderma)"},{"id":"B","text":"हजारीबाग और रांची (Hazaribagh and Ranchi)","text_en":"हजारीबाग और रांची (Hazaribagh and Ranchi)"},{"id":"C","text":"रांची और पलामू (Ranchi and Palamu)","text_en":"रांची और पलामू (Ranchi and Palamu)"},{"id":"D","text":"कोडरमा और राजमहल (Koderma and Rajmahal)","text_en":"कोडरमा और राजमहल (Koderma and Rajmahal)"}]', '1', '**✅ Correct Logic:** दामोदर नदी एक भ्रंश घाटी (Rift Valley) में बहती है जो **हजारीबाग पठार** (उत्तर) और **रांची पठार** (दक्षिण) को अलग करती है।

**💡 Exam Fact:** रांची का पठार ''सम्पतित पेनिप्लेन'' (Intersecting Peneplain) का उदाहरण है।

**🧠 Memory Tip:** **HR** (Human Resource) divided by **Damodar**. (H-Hazaribagh, R-Ranchi).

**🚫 Scam Alert:** कोडरमा हजारीबाग का ही हिस्सा है। मुख्य विभाजन हजारीबाग और रांची के बीच है।', 2, 0, 7, NULL, 'In the Chota Nagpur Plateau, the ''Damodar Trough'' separates which two micro-plateaus?', '**✅ Correct Logic:** Damodar river flows in a Rift Valley separating **Hazaribagh Plateau** (North) and **Ranchi Plateau** (South).

**💡 Exam Fact:** Ranchi plateau is an example of an ''Intersecting Peneplain''.

**🧠 Memory Tip:** **HR** divided by **Damodar**. (H-Hazaribagh, R-Ranchi).

**🚫 Scam Alert:** Koderma is part of Hazaribagh. The main division is between Hazaribagh and Ranchi.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('16a8e97f-a4e8-4539-8aab-4c425ed69af9', '9b8fb8ae-157c-4003-b07c-4665830aca5e', '''शिलॉन्ग शिखर'' (Shillong Peak) के संबंध में सही तथ्य क्या है?', '[{"id":"A","text":"यह एक ज्वालामुखी शंकु है (It is a volcanic cone)","text_en":"यह एक ज्वालामुखी शंकु है (It is a volcanic cone)"},{"id":"B","text":"यह मेघालय पठार की सबसे ऊंची चोटी है (It is the highest peak of Meghalaya Plateau)","text_en":"यह मेघालय पठार की सबसे ऊंची चोटी है (It is the highest peak of Meghalaya Plateau)"},{"id":"C","text":"यह गारो पहाड़ियों में स्थित है (It is located in Garo Hills)","text_en":"यह गारो पहाड़ियों में स्थित है (It is located in Garo Hills)"},{"id":"D","text":"यह हिमालय का हिस्सा है (It is part of Himalayas)","text_en":"यह हिमालय का हिस्सा है (It is part of Himalayas)"}]', '1', '**✅ Correct Logic:** शिलॉन्ग पीक (1961 मी) **मेघालय पठार की सबसे ऊंची चोटी** है और यह **खासी पहाड़ियों** में स्थित है।

**💡 Exam Fact:** इसकी आकृति एक तश्तरी (Saucer) जैसी है। चेरापूंजी और मासिनराम भी खासी पहाड़ियों में ही हैं।

**🧠 Memory Tip:** **Shillong** is the capital, so it has the **Highest** peak.

**🚫 Scam Alert:** यह गारो में नहीं, खासी में है। नोकरेक (Nokrek) गारो की सबसे ऊंची चोटी है।', 2, 0, 8, NULL, 'What is the correct fact regarding ''Shillong Peak''?', '**✅ Correct Logic:** Shillong Peak (1961m) is the **highest peak of the Meghalaya Plateau** and is located in the **Khasi Hills**.

**💡 Exam Fact:** It has a saucer-like shape. Cherrapunji and Mawsynram are also in Khasi Hills.

**🧠 Memory Tip:** **Shillong** is the capital, so it has the **Highest** peak.

**🚫 Scam Alert:** It is not in Garo, but in Khasi. Nokrek is the highest peak of Garo.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('37556ce8-58ba-4490-ae0a-66a275a5ea4d', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'रायलसीमा पठार (Rayalaseema Plateau) भौगोलिक रूप से किस कारण से ''वृष्टि छाया क्षेत्र'' (Rain Shadow Region) बना हुआ है?', '[{"id":"A","text":"पूर्वी घाट की उपस्थिति के कारण (Due to presence of Eastern Ghats)","text_en":"पूर्वी घाट की उपस्थिति के कारण (Due to presence of Eastern Ghats)"},{"id":"B","text":"पश्चिमी घाट की उपस्थिति के कारण (Due to presence of Western Ghats)","text_en":"पश्चिमी घाट की उपस्थिति के कारण (Due to presence of Western Ghats)"},{"id":"C","text":"अरावली के समानांतर होने के कारण (Due to being parallel to Aravalis)","text_en":"अरावली के समानांतर होने के कारण (Due to being parallel to Aravalis)"},{"id":"D","text":"समुद्र से अत्यधिक दूरी के कारण (Due to extreme distance from sea)","text_en":"समुद्र से अत्यधिक दूरी के कारण (Due to extreme distance from sea)"}]', '1', '**✅ Correct Logic:** रायलसीमा (आंध्र प्रदेश) **पश्चिमी घाट** के पूर्व में स्थित है। जब दक्षिण-पश्चिम मानसून पश्चिमी घाट से टकराता है, तो सारी बारिश पश्चिमी तट पर हो जाती है, और रायलसीमा ''वृष्टि छाया'' (Rain Shadow) में सूखा रह जाता है।

**💡 Exam Fact:** यह भारत के सबसे सूखे क्षेत्रों में से एक है।

**🧠 Memory Tip:** **Shadow** of the **West** falls on Rayalaseema.

**🚫 Scam Alert:** पूर्वी घाट विच्छेदित (broken) हैं, वे बारिश नहीं रोकते। मुख्य विलेन पश्चिमी घाट है।', 2, 0, 9, NULL, 'Geographically, why does the Rayalaseema Plateau remain a ''Rain Shadow Region''?', '**✅ Correct Logic:** Rayalaseema (AP) lies to the east of the **Western Ghats**. When the SW Monsoon hits the Western Ghats, heavy rain falls on the coast, leaving Rayalaseema dry in the ''Rain Shadow''.

**💡 Exam Fact:** It is one of the most drought-prone regions of India.

**🧠 Memory Tip:** **Shadow** of the **West** falls on Rayalaseema.

**🚫 Scam Alert:** Eastern Ghats are broken and don''t stop rain effectively. The main villain is the Western Ghats.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f4a57a70-787a-420d-b83e-fd999da2329c', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'निम्नलिखित पठारों को उनकी प्रमुख नदी/विशेषता से सुमेलित करें (Match the following plateaus with their major river/feature):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)","text_en":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(b), (3)-(a), (4)-(c)","text_en":"(1)-(d), (2)-(b), (3)-(a), (4)-(c)"}]', '0', '**✅ Correct Matching:**
* **बघेलखंड** (MP/CG) गंगा बेसिन (सोन) और महानदी बेसिन को अलग करता है। -> (1)-(a)
* **मालवा** (MP) चंबल नदी द्वारा अपवाहित है और अवनालिका अपरदन (Gully Erosion/Ravines) के लिए प्रसिद्ध है। -> (2)-(b)
* **तेलंगाना** पठार में गोदावरी और कृष्णा नदियाँ बहती हैं। -> (3)-(c)
* **काठियावाड़** (गुजरात) भी दक्कन ट्रैप की तरह ज्वालामुखी क्रिया से बना है। -> (4)-(d)

**💡 Exam Fact:** बघेलखंड में सफेद बाघ (White Tigers) पाए गए थे (रीवा)।

**🧠 Memory Tip:** **Baghel** divides basins. **Malwa** has ravines. **Telangana** has big rivers.

**🚫 Scam Alert:** आसान लग सकता है, लेकिन बघेलखंड की ''जल विभाजक'' भूमिका अक्सर परीक्षाओं में पूछी जाती है।', 2, 0, 10, NULL, 'Match the following plateaus with their major river/feature:', '**✅ Correct Matching:**
* **Baghelkhand** separates Ganga system (Son) and Mahanadi system. -> (1)-(a)
* **Malwa** is drained by Chambal and famous for Ravines/Gully erosion. -> (2)-(b)
* **Telangana** plateau hosts Godavari and Krishna. -> (3)-(c)
* **Kathiawar** is also formed by volcanic activity like Deccan Trap. -> (4)-(d)

**💡 Exam Fact:** White Tigers were found in Baghelkhand (Rewa).

**🧠 Memory Tip:** **Baghel** divides basins. **Malwa** has ravines.

**🚫 Scam Alert:** Looks easy, but the ''Water Divide'' role of Baghelkhand is a high-yield exam fact.', 60, 'matching', '[{"id":"(1)","label":"बघेलखंड पठार (Baghelkhand)","match":"सोन और महानदी के बीच जल विभाजक (Water divide between Son & Mahanadi)","matchId":"(a)"},{"id":"(2)","label":"मालवा पठार (Malwa)","match":"चंबल और बीहड़ (Chambal and Ravines)","matchId":"(b)"},{"id":"(3)","label":"तेलंगाना पठार (Telangana)","match":"गोदावरी और कृष्णा बेसिन (Godavari & Krishna Basin)","matchId":"(c)"},{"id":"(4)","label":"काठियावाड़ पठार (Kathiawar)","match":"रीयूनियन हॉटस्पॉट ज्वालामुखी (Reunion Hotspot Volcanism)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6c4d4f7e-9397-41af-bcbb-308e792556e7', '689ff095-5286-4197-ad00-fbad55edea78', 'गृहस्थों के लिए प्रतिदिन किए जाने वाले ''पंचमहायज्ञों'' में से कौन सा यज्ञ ''चींटियों, पक्षियों और अन्य जीवों'' के लिए भोजन देने से संबंधित है?', '[{"id":"A","text":"नृ यज्ञ (Nri Yajna)","text_en":"नृ यज्ञ (Nri Yajna)"},{"id":"B","text":"भूत यज्ञ (Bhuta Yajna)","text_en":"भूत यज्ञ (Bhuta Yajna)"},{"id":"C","text":"ब्रह्म यज्ञ (Brahma Yajna)","text_en":"ब्रह्म यज्ञ (Brahma Yajna)"},{"id":"D","text":"पितृ यज्ञ (Pitra Yajna)","text_en":"पितृ यज्ञ (Pitra Yajna)"}]', '1', '**✅ Correct Logic:** ''भूत'' का अर्थ है प्राणी (Beings)। भूत यज्ञ (जिसे बलि-वैश्वदेव भी कहते हैं) में समस्त प्राणियों (कुत्ते, कौवे, चींटी आदि) के लिए भोजन निकाला जाता है। यह पारिस्थितिक संतुलन (Ecological balance) का प्रतीक है।

**💡 Exam Fact:** ''नृ यज्ञ'' (अतिथि यज्ञ) मनुष्यों के लिए है।

**🧠 Memory Tip:** Bhuta = Being (Animals/Insects). Feed the Bhutas.

**🚫 Scam Alert:** ''भूत'' शब्द देखकर इसे प्रेत-आत्माओं से न जोड़ें, यहाँ इसका अर्थ ''जीव-जंतु'' है।', 2, 0, 1, NULL, 'Which of the daily ''Pancha Mahayagyas'' for householders is related to offering food to ''ants, birds, and other creatures''?', '**✅ Correct Logic:** ''Bhuta'' means Beings. In Bhuta Yajna (also called Bali-Vaishvadeva), food is offered to all creatures (dogs, crows, ants etc.). It symbolizes ecological balance.

**💡 Exam Fact:** ''Nri Yajna'' (Guest sacrifice) is for humans.

**🧠 Memory Tip:** Bhuta = Being (Animals/Insects). Feed the Bhutas.

**🚫 Scam Alert:** Don''t associate ''Bhuta'' with ghosts here; it means ''living creatures''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4bf3f645-ab26-4d72-b14b-f10d32ed4d14', '689ff095-5286-4197-ad00-fbad55edea78', '''ब्रह्म यज्ञ'' (Brahma Yajna) का संपादन मुख्य रूप से कैसे किया जाता है?', '[{"id":"A","text":"अग्नि में आहुति देकर (By offering oblations in fire)","text_en":"अग्नि में आहुति देकर (By offering oblations in fire)"},{"id":"B","text":"वेदों के स्वाध्याय और पठन-पाठन द्वारा (By self-study and teaching of Vedas)","text_en":"वेदों के स्वाध्याय और पठन-पाठन द्वारा (By self-study and teaching of Vedas)"},{"id":"C","text":"माता-पिता की सेवा करके (By serving parents)","text_en":"माता-पिता की सेवा करके (By serving parents)"},{"id":"D","text":"अतिथियों को भोजन कराकर (By feeding guests)","text_en":"अतिथियों को भोजन कराकर (By feeding guests)"}]', '1', '**✅ Correct Logic:** ''ब्रह्म'' का अर्थ यहाँ ''वेद'' या ''ज्ञान'' है। ऋषियों के प्रति कृतज्ञता व्यक्त करने के लिए वेदों का अध्ययन (स्वाध्याय) और अध्यापन करना ही ब्रह्म यज्ञ है। इसे ''ऋषि यज्ञ'' भी कहते हैं।

**💡 Exam Fact:** यह प्राचीन भारत में शिक्षा की निरंतरता बनाए रखने का तरीका था।

**🧠 Memory Tip:** Brahma = Knowledge/Vedas. Yajna of Knowledge = Study.

**🚫 Scam Alert:** अग्नि में आहुति ''देव यज्ञ'' है, ब्रह्म यज्ञ नहीं।', 2, 0, 2, NULL, 'How is ''Brahma Yajna'' primarily performed?', '**✅ Correct Logic:** ''Brahma'' here means ''Veda'' or ''Knowledge''. Studying (Swadhyaya) and teaching Vedas to express gratitude to Rishis is Brahma Yajna. Also called ''Rishi Yajna''.

**💡 Exam Fact:** This was the method to maintain continuity of education in ancient India.

**🧠 Memory Tip:** Brahma = Knowledge/Vedas. Yajna of Knowledge = Study.

**🚫 Scam Alert:** Offering in fire is ''Deva Yajna'', not Brahma Yajna.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dc3d2f67-c000-46bb-92a5-bd7c78b02778', '689ff095-5286-4197-ad00-fbad55edea78', 'मनुस्मृति के अनुसार ''अतिथि देवो भव'' की भावना किस महायज्ञ का मूल आधार है?', '[{"id":"A","text":"नृ यज्ञ / मनुष्य यज्ञ (Nri Yajna / Manushya Yajna)","text_en":"नृ यज्ञ / मनुष्य यज्ञ (Nri Yajna / Manushya Yajna)"},{"id":"B","text":"देव यज्ञ (Deva Yajna)","text_en":"देव यज्ञ (Deva Yajna)"},{"id":"C","text":"पितृ यज्ञ (Pitra Yajna)","text_en":"पितृ यज्ञ (Pitra Yajna)"},{"id":"D","text":"भूत यज्ञ (Bhuta Yajna)","text_en":"भूत यज्ञ (Bhuta Yajna)"}]', '0', '**✅ Correct Logic:** ''नृ'' का अर्थ है ''नर'' (मनुष्य)। नृ यज्ञ में अतिथियों (Guest) का सत्कार, भोजन और सेवा की जाती है। इसे ''मनुष्य यज्ञ'' भी कहते हैं।

**💡 Exam Fact:** अतिथि वह है जिसके आने की ''तिथि'' निश्चित न हो।

**🧠 Memory Tip:** Nri = Nar (Human). Guest is a Human.

**🚫 Scam Alert:** ''देवो भव'' सुनकर इसे ''देव यज्ञ'' न समझें। यह अतिथि (इंसान) के लिए है।', 2, 0, 3, NULL, 'According to Manusmriti, the spirit of ''Atithi Devo Bhava'' is the basis of which Mahayagya?', '**✅ Correct Logic:** ''Nri'' means ''Nar'' (Human). Nri Yajna involves hospitality, feeding, and serving guests. Also called ''Manushya Yajna''.

**💡 Exam Fact:** ''Atithi'' is one whose date (Tithi) of arrival is not fixed.

**🧠 Memory Tip:** Nri = Nar (Human). Guest is a Human.

**🚫 Scam Alert:** Hearing ''Devo Bhava'', don''t mistake it for ''Deva Yajna''. It is for the Guest (Human).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7063c4b7-930e-4547-be0c-8aeedddffacc', '689ff095-5286-4197-ad00-fbad55edea78', 'पंचमहायज्ञों को उनके लाभार्थियों (Beneficiaries) से सुमेलित करें (Match the Pancha Mahayagyas with their Beneficiaries):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)","text_en":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)"},{"id":"D","text":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)","text_en":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)"}]', '0', '**✅ Correct Logic:**
* **देव:** अग्नि में हवन (देवताओं के लिए)।
* **पितृ:** तर्पण/श्राद्ध (पूर्वजों के लिए)।
* **ब्रह्म:** स्वाध्याय (ऋषियों के लिए)।
* **भूत:** बलि/भोजन (मूक प्राणियों के लिए)।

**💡 Exam Fact:** ये यज्ञ ''हिंसा'' (जैसे भोजन पकाने में अनजाने में हुई जीव हत्या) के प्रायश्चित (Expiation) माने जाते हैं।

**🧠 Memory Tip:** Deva=God. Pitra=Parent. Brahma=Book. Bhuta=Bird.

**🚫 Scam Alert:** यह जोड़ी बनाने के लिए सबसे आसान और महत्वपूर्ण है।', 2, 0, 5, NULL, 'Match the Pancha Mahayagyas with their Beneficiaries:', '**✅ Correct Logic:**
* **Deva:** Havan in fire (for Gods).
* **Pitra:** Tarpan/Shraddha (for Ancestors).
* **Brahma:** Swadhyaya (for Sages).
* **Bhuta:** Bali/Food (for animals).

**💡 Exam Fact:** These Yajnas are considered expiation for the violence committed unknowingly (e.g., while cooking).

**🧠 Memory Tip:** Deva=God. Pitra=Parent. Brahma=Book. Bhuta=Bird.

**🚫 Scam Alert:** Easiest and most important for matching.', 60, 'matching', '[{"id":"(1)","label":"देव यज्ञ (Deva Yajna)","match":"देवता (Gods/Environment)","matchId":"(b)"},{"id":"(2)","label":"पितृ यज्ञ (Pitra Yajna)","match":"पूर्वज (Ancestors)","matchId":"(a)"},{"id":"(3)","label":"ब्रह्म यज्ञ (Brahma Yajna)","match":"ऋषि/गुरु (Sages/Gurus)","matchId":"(d)"},{"id":"(4)","label":"भूत यज्ञ (Bhuta Yajna)","match":"पशु-पक्षी (Animals/Birds)","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('62199a09-a1c8-4451-a8e9-2ed64904cafc', '689ff095-5286-4197-ad00-fbad55edea78', '''अग्निहोत्र'' (Agnihotra) किस प्रकार का यज्ञ है?', '[{"id":"A","text":"दैनिक हवन जो सुबह-शाम किया जाता है (Daily fire sacrifice performed morning and evening)","text_en":"दैनिक हवन जो सुबह-शाम किया जाता है (Daily fire sacrifice performed morning and evening)"},{"id":"B","text":"वर्ष में एक बार किया जाने वाला सोम यज्ञ (Soma sacrifice performed once a year)","text_en":"वर्ष में एक बार किया जाने वाला सोम यज्ञ (Soma sacrifice performed once a year)"},{"id":"C","text":"राजा के राज्याभिषेक का यज्ञ (Sacrifice for King''s coronation)","text_en":"राजा के राज्याभिषेक का यज्ञ (Sacrifice for King''s coronation)"},{"id":"D","text":"शत्रु नाश के लिए किया जाने वाला यज्ञ (Sacrifice for destruction of enemy)","text_en":"शत्रु नाश के लिए किया जाने वाला यज्ञ (Sacrifice for destruction of enemy)"}]', '0', '**✅ Correct Logic:** ''अग्निहोत्र'' एक नित्य (Daily) वैदिक यज्ञ है जिसे गृहस्थ प्रतिदिन सूर्योदय और सूर्यास्त के समय करते हैं। इसमें दूध, चावल या घी की आहुति दी जाती है।

**💡 Exam Fact:** यह ''स्मार्त'' और ''श्रौत'' दोनों परंपराओं में आता है, लेकिन मूलतः यह दैनिक कर्तव्य है।

**🧠 Memory Tip:** Agni (Fire) + Hotra (Offering) = Daily Routine.

**🚫 Scam Alert:** यह कोई विशाल या वार्षिक यज्ञ नहीं है, यह रोज का काम है।', 2, 0, 4, NULL, 'What type of Yajna is ''Agnihotra''?', '**✅ Correct Logic:** ''Agnihotra'' is a daily (Nitya) Vedic sacrifice performed by householders at sunrise and sunset. Oblations of milk, rice, or ghee are offered.

**💡 Exam Fact:** It falls under both ''Smarta'' and ''Shrauta'' traditions, but basically it is a daily duty.

**🧠 Memory Tip:** Agni (Fire) + Hotra (Offering) = Daily Routine.

**🚫 Scam Alert:** It''s not a massive or annual sacrifice; it''s a daily routine.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('44b78537-96ff-46f0-af29-293df87546d7', '689ff095-5286-4197-ad00-fbad55edea78', 'पंचमहायज्ञ की अवधारणा का मुख्य सामाजिक उद्देश्य क्या है?', '[{"id":"A","text":"व्यक्तिगत मोक्ष (Personal Moksha)","text_en":"व्यक्तिगत मोक्ष (Personal Moksha)"},{"id":"B","text":"स्वार्थ का त्याग और ''जगत के प्रति ऋण'' चुकाना (Renunciation of selfishness and repaying ''Debt to the World'')","text_en":"स्वार्थ का त्याग और ''जगत के प्रति ऋण'' चुकाना (Renunciation of selfishness and repaying ''Debt to the World'')"},{"id":"C","text":"पुरोहितों को धनवान बनाना (Making priests rich)","text_en":"पुरोहितों को धनवान बनाना (Making priests rich)"},{"id":"D","text":"केवल देवताओं को प्रसन्न करना (Pleasing only Gods)","text_en":"केवल देवताओं को प्रसन्न करना (Pleasing only Gods)"}]', '1', '**✅ Correct Logic:** पंचमहायज्ञ मनुष्य को यह याद दिलाते हैं कि वह अकेला नहीं है। वह समाज, प्रकृति और पूर्वजों के सहयोग से जीवित है, इसलिए उसे प्रतिदिन अपने भोजन का एक हिस्सा इन सबको (त्याग) देना चाहिए। यह ''सह-अस्तित्व'' (Co-existence) का पाठ है।

**💡 Exam Fact:** इसे ''पञ्चसूना'' (पांच पाप - चक्की, चूल्हा आदि से होने वाली हिंसा) के दोष को मिटाने वाला माना गया है।

**🧠 Memory Tip:** 5 Yajnas = 5 ways to say "Thank You" to the Universe.

**🚫 Scam Alert:** यह केवल पूजा नहीं, बल्कि सामाजिक जिम्मेदारी (Social Responsibility) है।', 2, 0, 6, NULL, 'What is the main social objective of the concept of Pancha Mahayagya?', '**✅ Correct Logic:** Pancha Mahayagyas remind man that he is not alone. He survives with the help of society, nature, and ancestors, so he must offer a part of his food to them daily. It is a lesson in ''Co-existence''.

**💡 Exam Fact:** It is considered to remove the sin of ''Panchasuna'' (5 sins of violence via pestle, stove etc.).

**🧠 Memory Tip:** 5 Yajnas = 5 ways to say "Thank You" to the Universe.

**🚫 Scam Alert:** It is not just worship, but Social Responsibility.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('afd4c983-4df6-4a6b-8a6e-adff8616c61d', '689ff095-5286-4197-ad00-fbad55edea78', 'वैदिक काल में ''वाजपेय यज्ञ'' (Vajapeya Yajna) का मुख्य आकर्षण क्या था?', '[{"id":"A","text":"रथ दौड़ (Chariot Race)","text_en":"रथ दौड़ (Chariot Race)"},{"id":"B","text":"जुआ खेलना (Gambling)","text_en":"जुआ खेलना (Gambling)"},{"id":"C","text":"सोम रस पान (Drinking Soma)","text_en":"सोम रस पान (Drinking Soma)"},{"id":"D","text":"शस्त्र प्रदर्शन (Weapon display)","text_en":"शस्त्र प्रदर्शन (Weapon display)"}]', '0', '**✅ Correct Logic:** वाजपेय का अर्थ है ''शक्ति का पान'' (Drink of Strength)। इसमें राजा अपनी शक्ति और श्रेष्ठता सिद्ध करने के लिए ''रथ दौड़'' (Chariot Race) का आयोजन करता था, जिसमें राजा का रथ सदैव जीतता था (प्रतीकात्मक)।

**💡 Exam Fact:** यह यज्ञ राजा को ''सम्राट'' की उपाधि दिलाता था।

**🧠 Memory Tip:** Vaja = Speed/Strength. **V**ajapeya = **V**ehicle (Chariot) Race.

**🚫 Scam Alert:** ''राजसूय'' में जुआ (Dice) होता था, ''वाजपेय'' में रथ दौड़।', 2, 0, 7, NULL, 'What was the main attraction of the ''Vajapeya Yajna'' in the Vedic period?', '**✅ Correct Logic:** Vajapeya means ''Drink of Strength''. In this, the King organized a ''Chariot Race'' to prove his might, where the King''s chariot always won (symbolically).

**💡 Exam Fact:** This Yajna gave the title of ''Samrat'' to the King.

**🧠 Memory Tip:** Vaja = Speed/Strength. **V**ajapeya = **V**ehicle (Chariot) Race.

**🚫 Scam Alert:** ''Rajasuya'' had Gambling (Dice), ''Vajapeya'' had Chariot Race.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2fec048a-daa6-4a6c-b83d-bb31ba695033', '689ff095-5286-4197-ad00-fbad55edea78', '''अश्वमेध यज्ञ'' (Ashvamedha Yajna) का मुख्य उद्देश्य क्या था?', '[{"id":"A","text":"पुत्र प्राप्ति (To get a son)","text_en":"पुत्र प्राप्ति (To get a son)"},{"id":"B","text":"साम्राज्य विस्तार और सार्वभौम सत्ता (Territorial expansion and Universal Sovereignty)","text_en":"साम्राज्य विस्तार और सार्वभौम सत्ता (Territorial expansion and Universal Sovereignty)"},{"id":"C","text":"वर्षा कराना (To cause rain)","text_en":"वर्षा कराना (To cause rain)"},{"id":"D","text":"पाप मुक्ति (Absolution of sins)","text_en":"पाप मुक्ति (Absolution of sins)"}]', '1', '**✅ Correct Logic:** अश्वमेध यज्ञ में एक घोड़ा छोड़ा जाता था। वह जहाँ तक जाता, वह क्षेत्र राजा का हो जाता था (यदि कोई उसे न रोके)। यह ''चक्रवर्ती'' बनने और राजनीतिक विस्तार का प्रतीक था।

**💡 Exam Fact:** पुष्यमित्र शुंग और समुद्रगुप्त ने अश्वमेध यज्ञ किए थे।

**🧠 Memory Tip:** Ashva (Horse) runs = Border expands.

**🚫 Scam Alert:** पुत्र प्राप्ति के लिए ''पुत्र्येष्टि'' यज्ञ होता था।', 2, 0, 8, NULL, 'What was the main objective of ''Ashvamedha Yajna''?', '**✅ Correct Logic:** In Ashvamedha, a horse was let loose. Wherever it went, that territory belonged to the King (if unchallenged). It symbolized becoming ''Chakravartin'' and political expansion.

**💡 Exam Fact:** Pushyamitra Shunga and Samudragupta performed Ashvamedha.

**🧠 Memory Tip:** Ashva (Horse) runs = Border expands.

**🚫 Scam Alert:** ''Putryeshti'' Yajna was for getting a son.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('daacf468-ae87-450f-a13f-3a801c536d96', '689ff095-5286-4197-ad00-fbad55edea78', 'कथन (A): ''श्राद्ध'' (Shraddha) पितृ यज्ञ का ही एक रूप है।
कारण (R): श्राद्ध में ''पिंडदान'' (Offering of rice balls) के माध्यम से पितरों को तृप्त किया जाता है।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic:** पितृ यज्ञ का उद्देश्य पूर्वजों के प्रति श्रद्धा (Gratitude) जताना है। श्राद्ध और तर्पण इसी प्रक्रिया के भाग हैं जिसमें जल और भोजन (पिंड) अर्पित किया जाता है।

**💡 Exam Fact:** ''गया'' (बिहार) पिंडदान के लिए प्रसिद्ध है।

**🧠 Memory Tip:** Shraddha = Faith/Respect for Pitras.

**🚫 Scam Alert:** दोनों सही हैं और R, A की प्रक्रिया (Process) बताता है।', 2, 0, 9, NULL, 'Assertion (A): ''Shraddha'' is a form of Pitra Yajna.
Reason (R): In Shraddha, ancestors are satisfied through ''Pindadana'' (Offering of rice balls).
Select the correct option:', '**✅ Correct Logic:** The aim of Pitra Yajna is to show Gratitude (Shraddha) to ancestors. Shraddha and Tarpan are parts of this process where water and food (Pinda) are offered.

**💡 Exam Fact:** ''Gaya'' (Bihar) is famous for Pindadana.

**🧠 Memory Tip:** Shraddha = Faith/Respect for Pitras.

**🚫 Scam Alert:** Both are true and R explains the process.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e2b605ae-39e4-47ac-98aa-bec8ac69f54b', '689ff095-5286-4197-ad00-fbad55edea78', 'निम्नलिखित में से कौन सा यज्ञ ''सोम यज्ञ'' (Soma Sacrifice) की श्रेणी में आता है?', '[{"id":"A","text":"अग्निष्टोम (Agnishtoma)","text_en":"अग्निष्टोम (Agnishtoma)"},{"id":"B","text":"पितृ यज्ञ (Pitra Yajna)","text_en":"पितृ यज्ञ (Pitra Yajna)"},{"id":"C","text":"ब्रह्म यज्ञ (Brahma Yajna)","text_en":"ब्रह्म यज्ञ (Brahma Yajna)"},{"id":"D","text":"उपनयन (Upanayana)","text_en":"उपनयन (Upanayana)"}]', '0', '**✅ Correct Logic:** ''अग्निष्टोम'' एक प्रमुख सोम यज्ञ है जो वसंत ऋतु में किया जाता था और 5 दिनों तक चलता था। इसमें सोम रस का पान और देवताओं को आहुति दी जाती थी।

**💡 Exam Fact:** इसमें 12 स्तोत्र गाए जाते थे।

**🧠 Memory Tip:** Soma = Special Drink. Agnishtoma = Special Party (Yajna).

**🚫 Scam Alert:** बाकी तीन दैनिक महायज्ञ या संस्कार हैं, अग्निष्टोम विशिष्ट श्रौत यज्ञ है।', 2, 0, 10, NULL, 'Which of the following falls under the category of ''Soma Sacrifice''?', '**✅ Correct Logic:** ''Agnishtoma'' is a major Soma sacrifice performed in Spring, lasting 5 days. It involved drinking Soma juice and offering it to Gods.

**💡 Exam Fact:** 12 Stotras were sung in this.

**🧠 Memory Tip:** Soma = Special Drink. Agnishtoma = Special Party (Yajna).

**🚫 Scam Alert:** The other three are daily duties or rites; Agnishtoma is a specific Shrauta Yajna.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4492bb41-2e86-406f-9b7f-9fa4907c8335', '56d1fe30-34a0-410e-893b-5bc629864355', 'भारतीय दर्शन में ''कर्म'' (Karma) का मूल अर्थ क्या है?', '[{"id":"A","text":"केवल पूजा-पाठ (Only Worship)","text_en":"केवल पूजा-पाठ (Only Worship)"},{"id":"B","text":"भाग्य (Fate)","text_en":"भाग्य (Fate)"},{"id":"C","text":"क्रिया और उसका फल (Action and its Result)","text_en":"क्रिया और उसका फल (Action and its Result)"},{"id":"D","text":"निष्क्रियता (Inaction)","text_en":"निष्क्रियता (Inaction)"}]', '2', '**✅ Correct Logic:** कर्म का शाब्दिक अर्थ है ''करना'' (To do)। दर्शन में इसका अर्थ है कोई भी शारीरिक, मानसिक या वाचिक क्रिया (Action) और उसका अपरिहार्य परिणाम (Result)। ''जैसा बोओगे, वैसा काटोगे''।

**💡 Exam Fact:** न्यूटन का तीसरा नियम (Action-Reaction) कर्म सिद्धांत का भौतिक रूप है।

**🧠 Memory Tip:** Karma = Cause & Effect.

**🚫 Scam Alert:** कर्म ''भाग्य'' (Luck) नहीं है। भाग्य कर्म का ''परिणाम'' है।', 2, 0, 1, NULL, 'What is the basic meaning of ''Karma'' in Indian philosophy?', '**✅ Correct Logic:** Karma literally means ''To do''. In philosophy, it means any physical, mental, or verbal Action and its inevitable Result. ''As you sow, so shall you reap''.

**💡 Exam Fact:** Newton''s 3rd Law (Action-Reaction) is the physical form of Karma theory.

**🧠 Memory Tip:** Karma = Cause & Effect.

**🚫 Scam Alert:** Karma is not ''Luck''. Luck is the ''Result'' of Karma.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('982c2958-5b57-410a-95ff-fcf7b0a9d4a1', '56d1fe30-34a0-410e-893b-5bc629864355', 'भगवद्गीता में ''निष्काम कर्म'' (Nishkama Karma) का क्या अर्थ बताया गया है?', '[{"id":"A","text":"कर्म करना ही छोड़ देना (Giving up action altogether)","text_en":"कर्म करना ही छोड़ देना (Giving up action altogether)"},{"id":"B","text":"बिना फल की आसक्ति के कर्तव्य करना (Performing duty without attachment to the fruit)","text_en":"बिना फल की आसक्ति के कर्तव्य करना (Performing duty without attachment to the fruit)"},{"id":"C","text":"केवल अच्छे कर्म करना (Doing only good deeds)","text_en":"केवल अच्छे कर्म करना (Doing only good deeds)"},{"id":"D","text":"धन के लिए कर्म करना (Working for money)","text_en":"धन के लिए कर्म करना (Working for money)"}]', '1', '**✅ Correct Logic:** "कर्मण्येवाधिकारस्ते मा फलेषु कदाचन"। निष्काम कर्म का अर्थ है फल (Result) की चिंता किए बिना अपना कर्तव्य पूरी निष्ठा से करना। यह कर्म के बंधन से मुक्ति दिलाता है।

**💡 Exam Fact:** यह ''कर्मयोग'' का मूल मंत्र है।

**🧠 Memory Tip:** Nish-Kama = No-Desire (for result). Do your job, forget the pay check (mentally).

**🚫 Scam Alert:** इसका मतलब ''फ्री में काम करना'' नहीं है, बल्कि ''मानसिक आसक्ति'' (Mental Attachment) का त्याग है।', 2, 0, 2, NULL, 'What is the meaning of ''Nishkama Karma'' as described in Bhagavad Gita?', '**✅ Correct Logic:** "Karmanyevadhikaraste Ma Phaleshu Kadachana". Nishkama Karma means performing duty without attachment to the result. It liberates one from the bondage of Karma.

**💡 Exam Fact:** This is the core mantra of ''Karma Yoga''.

**🧠 Memory Tip:** Nish-Kama = No-Desire (for result). Do your job, forget the pay check (mentally).

**🚫 Scam Alert:** It doesn''t mean ''Working for free'', but giving up ''Mental Attachment''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dd0ce6dc-b71c-40fc-9db3-a9340c53b864', '56d1fe30-34a0-410e-893b-5bc629864355', 'कर्म के तीन प्रकारों में से ''प्रारब्ध कर्म'' (Prarabdha Karma) किसे कहते हैं?', '[{"id":"A","text":"जो कर्म हम अभी कर रहे हैं (Karma we are doing right now)","text_en":"जो कर्म हम अभी कर रहे हैं (Karma we are doing right now)"},{"id":"B","text":"भविष्य में किए जाने वाले कर्म (Karma to be done in future)","text_en":"भविष्य में किए जाने वाले कर्म (Karma to be done in future)"},{"id":"C","text":"संचित कर्म का वह भाग जो इस जन्म में फल देने लगा है (That part of Sanchita Karma which has started giving fruit in this life)","text_en":"संचित कर्म का वह भाग जो इस जन्म में फल देने लगा है (That part of Sanchita Karma which has started giving fruit in this life)"},{"id":"D","text":"जो कर्म नष्ट हो चुके हैं (Karma which are destroyed)","text_en":"जो कर्म नष्ट हो चुके हैं (Karma which are destroyed)"}]', '2', '**✅ Correct Logic:** प्रारब्ध वह ''तीर'' है जो कमान से छूट चुका है। यह हमारे पिछले जन्मों के कर्मों का वह हिस्सा है जो वर्तमान जन्म (शरीर, परिवार, सुख-दुख) का कारण बना है। इसे भोगना ही पड़ता है।

**💡 Exam Fact:** इसे बदला नहीं जा सकता, केवल भोगा जा सकता है।

**🧠 Memory Tip:** Prarabdha = **P**resent Life''s Package (Pre-destined).

**🚫 Scam Alert:** जो अभी कर रहे हैं, वह ''क्रियमाण'' है। जो जमा है, वह ''संचित'' है।', 2, 0, 3, NULL, 'Among the three types of Karma, what is ''Prarabdha Karma''?', '**✅ Correct Logic:** Prarabdha is the ''arrow'' that has left the bow. It is that part of past Karmas which has caused the present birth (body, family, joy-sorrow). It must be experienced.

**💡 Exam Fact:** It cannot be changed, only experienced.

**🧠 Memory Tip:** Prarabdha = **P**resent Life''s Package (Pre-destined).

**🚫 Scam Alert:** What we are doing now is ''Kriyamana''. What is stored is ''Sanchita''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5ce56510-e1b5-4414-9baf-16bbe4156c14', '56d1fe30-34a0-410e-893b-5bc629864355', 'कर्म के प्रकारों को उनकी परिभाषा से सुमेलित करें (Match the types of Karma with their definition):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)","text_en":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(c), (3)-(a), (4)-(d)","text_en":"(1)-(b), (2)-(c), (3)-(a), (4)-(d)"},{"id":"D","text":"(1)-(c), (2)-(a), (3)-(b), (4)-(d)","text_en":"(1)-(c), (2)-(a), (3)-(b), (4)-(d)"}]', '0', '**✅ Correct Logic:**
* **संचित:** बैंक बैलेंस (Total).
* **प्रारब्ध:** विद्ड्रॉ किया हुआ कैश (Current Use).
* **क्रियमाण:** नया डिपॉजिट (New Action).
* **विकर्म:** गलत ट्रांजैक्शन (Sin).

**💡 Exam Fact:** ज्ञान (Knowledge) से ''संचित'' कर्म जल सकते हैं, लेकिन ''प्रारब्ध'' भोगना ही पड़ता है।

**🧠 Memory Tip:** **S**anchita = **S**torage. **P**rarabdha = **P**laying now. **K**riyamana = **K**riya (Action) now.

**🚫 Scam Alert:** यह कर्म सिद्धांत का सबसे तकनीकी और महत्वपूर्ण हिस्सा है।', 2, 0, 5, NULL, 'Match the types of Karma with their definition:', '**✅ Correct Logic:**
* **Sanchita:** Bank Balance (Total).
* **Prarabdha:** Withdrawn Cash (Current Use).
* **Kriyamana:** New Deposit (New Action).
* **Vikarma:** Wrong Transaction (Sin).

**💡 Exam Fact:** ''Sanchita'' can be burnt by Knowledge, but ''Prarabdha'' must be experienced.

**🧠 Memory Tip:** **S**anchita = **S**torage. **P**rarabdha = **P**laying now. **K**riyamana = **K**riya (Action) now.

**🚫 Scam Alert:** This is the most technical part of Karma theory.', 60, 'matching', '[{"id":"(1)","label":"संचित कर्म (Sanchita)","match":"अतीत के सभी कर्मों का कुल जमा भंडार (Total accumulated store of all past actions)","matchId":"(b)"},{"id":"(2)","label":"प्रारब्ध कर्म (Prarabdha)","match":"संचित का वह भाग जो वर्तमान जीवन बना है (Part of Sanchita that formed present life)","matchId":"(a)"},{"id":"(3)","label":"क्रियमाण/आगामी (Kriyamana)","match":"वर्तमान में किया जाने वाला नया कर्म (New actions being done in present)","matchId":"(c)"},{"id":"(4)","label":"विकर्म (Vikarma)","match":"निषिद्ध या पाप कर्म (Forbidden or Sinful actions)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ad08e27f-14bd-4e44-b947-f2dda5acd629', '56d1fe30-34a0-410e-893b-5bc629864355', 'कर्म के सिद्धांत और ''पुनर्जन्म'' (Rebirth) के बीच क्या संबंध है?', '[{"id":"A","text":"कोई संबंध नहीं है (No relationship)","text_en":"कोई संबंध नहीं है (No relationship)"},{"id":"B","text":"पुनर्जन्म कर्मों के फल भोगने के लिए होता है (Rebirth happens to experience the fruit of Karmas)","text_en":"पुनर्जन्म कर्मों के फल भोगने के लिए होता है (Rebirth happens to experience the fruit of Karmas)"},{"id":"C","text":"पुनर्जन्म संयोग मात्र है (Rebirth is just a coincidence)","text_en":"पुनर्जन्म संयोग मात्र है (Rebirth is just a coincidence)"},{"id":"D","text":"कर्म पुनर्जन्म को रोकता है (Karma stops rebirth)","text_en":"कर्म पुनर्जन्म को रोकता है (Karma stops rebirth)"}]', '1', '**✅ Correct Logic:** कर्म सिद्धांत के अनुसार, कोई भी कर्म बिना फल दिए नष्ट नहीं होता। यदि एक जीवन में फल नहीं मिल पाया, तो आत्मा को फल भोगने के लिए नया शरीर (पुनर्जन्म) लेना पड़ता है। अतः कर्म ही पुनर्जन्म का कारण है।

**💡 Exam Fact:** जब कर्म शेष नहीं रहते (शून्य), तब मोक्ष मिलता है और पुनर्जन्म रुकता है।

**🧠 Memory Tip:** Unpaid Bills (Karma) -> Come back to pay (Rebirth).

**🚫 Scam Alert:** कर्म पुनर्जन्म को रोकता नहीं, बल्कि ''बनाए रखता'' है। कर्म-मुक्त होना ही मोक्ष है।', 2, 0, 4, NULL, 'What is the relationship between the Principle of Karma and ''Rebirth''?', '**✅ Correct Logic:** According to Karma theory, no action goes without result. If result is not experienced in one life, the soul takes a new body (Rebirth) to experience it. Thus, Karma is the cause of Rebirth.

**💡 Exam Fact:** When Karmas are exhausted (Zero), Moksha is attained and Rebirth stops.

**🧠 Memory Tip:** Unpaid Bills (Karma) -> Come back to pay (Rebirth).

**🚫 Scam Alert:** Karma doesn''t stop rebirth, it ''sustains'' it. Being free of Karma is Moksha.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ced894f7-ab89-4229-92c0-f006b389f199', '56d1fe30-34a0-410e-893b-5bc629864355', 'जैन दर्शन में कर्म को किस रूप में देखा जाता है?', '[{"id":"A","text":"एक अमूर्त नैतिक नियम (An abstract moral law)","text_en":"एक अमूर्त नैतिक नियम (An abstract moral law)"},{"id":"B","text":"पुद्गल (भौतिक कण) जो आत्मा से चिपक जाते हैं (Pudgala / Material particles that stick to the soul)","text_en":"पुद्गल (भौतिक कण) जो आत्मा से चिपक जाते हैं (Pudgala / Material particles that stick to the soul)"},{"id":"C","text":"ईश्वर का आदेश (God''s command)","text_en":"ईश्वर का आदेश (God''s command)"},{"id":"D","text":"माया या भ्रम (Maya or Illusion)","text_en":"माया या भ्रम (Maya or Illusion)"}]', '1', '**✅ Correct Logic:** जैन धर्म में कर्म केवल विचार नहीं, बल्कि सूक्ष्म ''भौतिक द्रव्य'' (Karma Matter) हैं। जब हम राग-द्वेष करते हैं, तो ये कण आत्मा की ओर आकर्षित होकर उससे चिपक जाते हैं, जिससे आत्मा भारी हो जाती है और बंधन में पड़ती है।

**💡 Exam Fact:** इसे ''आस्रव'' (Inflow of Karma) कहते हैं।

**🧠 Memory Tip:** Jain Karma = Sticky Dust on Soul.

**🚫 Scam Alert:** हिंदू धर्म में कर्म ''नियम'' है, जैन धर्म में कर्म ''पदार्थ'' (Matter) है। यह बड़ा अंतर है।', 2, 0, 6, NULL, 'How is Karma viewed in Jain philosophy?', '**✅ Correct Logic:** In Jainism, Karma is not just an idea, but subtle ''Material Matter'' (Pudgala). When we have attachment/aversion, these particles get attracted to the soul and stick to it, binding it.

**💡 Exam Fact:** This is called ''Asrava'' (Inflow of Karma).

**🧠 Memory Tip:** Jain Karma = Sticky Dust on Soul.

**🚫 Scam Alert:** In Hinduism Karma is a ''Law'', in Jainism it is ''Matter''. Big difference.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('42d737a3-32f1-447f-bf25-d87807e1de35', '56d1fe30-34a0-410e-893b-5bc629864355', 'कथन (A): ज्ञान प्राप्त होने पर ''संचित कर्म'' नष्ट हो जाते हैं।
कारण (R): ज्ञान अग्नि के समान है जो कर्मों को जला देता है।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic:** गीता (4.37) कहती है: "ज्ञानाग्निः सर्वकर्माणि भस्मसात्कुरुते तथा" (जैसे आग लकड़ी को जला देती है, वैसे ही ज्ञान की आग सभी कर्मों को जला देती है)। यह केवल संचित कर्मों पर लागू होता है, प्रारब्ध पर नहीं।

**💡 Exam Fact:** प्रारब्ध कर्म तीर की तरह हैं जो छूट चुके हैं, उन्हें ज्ञान नहीं रोक सकता।

**🧠 Memory Tip:** Knowledge = Fire. Sanchita = Wood.

**🚫 Scam Alert:** दोनों सही हैं।', 2, 0, 7, NULL, 'Assertion (A): ''Sanchita Karmas'' are destroyed upon attaining Knowledge.
Reason (R): Knowledge is like fire which burns the Karmas.
Select the correct option:', '**✅ Correct Logic:** Gita (4.37) says: "Jnanagnih sarvakarmani..." (As fire burns wood to ashes, so does the fire of knowledge burn all Karmas). This applies to Sanchita, not Prarabdha.

**💡 Exam Fact:** Prarabdha are like arrows shot, Knowledge cannot stop them.

**🧠 Memory Tip:** Knowledge = Fire. Sanchita = Wood.

**🚫 Scam Alert:** Both are true.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fc12110b-259a-44ca-b2af-e87f420d8e24', '56d1fe30-34a0-410e-893b-5bc629864355', '''क्रिया-प्रतिक्रिया'' (Action-Reaction) का नियम कर्म सिद्धांत के किस पक्ष को दर्शाता है?', '[{"id":"A","text":"नैतिक न्याय (Moral Justice)","text_en":"नैतिक न्याय (Moral Justice)"},{"id":"B","text":"वैज्ञानिक कार्य-कारण संबंध (Scientific Cause-Effect relationship)","text_en":"वैज्ञानिक कार्य-कारण संबंध (Scientific Cause-Effect relationship)"},{"id":"C","text":"धार्मिक अनुष्ठान (Religious Ritual)","text_en":"धार्मिक अनुष्ठान (Religious Ritual)"},{"id":"D","text":"मोक्ष (Moksha)","text_en":"मोक्ष (Moksha)"}]', '1', '**✅ Correct Logic:** कर्म सिद्धांत अंधविश्वास नहीं, बल्कि ''कार्य-कारण'' (Causality) का विज्ञान है। हर कार्य (Cause) का एक प्रभाव (Effect) होना तय है। यह ब्रह्मांड का मौलिक नियम है।

**💡 Exam Fact:** बौद्ध धर्म में इसे ''प्रतीत्यसमुत्पाद'' (Dependent Origination) के रूप में समझाया गया है।

**🧠 Memory Tip:** Karma is Physics of Soul.

**🚫 Scam Alert:** इसे केवल ''नैतिक'' न मानें, यह एक सार्वभौमिक नियम (Universal Law) है।', 2, 0, 8, NULL, 'The law of ''Action-Reaction'' represents which aspect of Karma theory?', '**✅ Correct Logic:** Karma theory is not superstition, but the science of ''Causality''. Every Cause must have an Effect. It is the fundamental law of the universe.

**💡 Exam Fact:** In Buddhism, it is explained as ''Pratityasamutpada'' (Dependent Origination).

**🧠 Memory Tip:** Karma is Physics of Soul.

**🚫 Scam Alert:** Don''t consider it just ''Moral'', it''s a ''Universal Law''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f03c47ea-a3f2-4c8a-a490-cabf16cd2e5e', '56d1fe30-34a0-410e-893b-5bc629864355', 'महर्षि पतंजलि के अनुसार कर्म के फल (विपाक) कितने प्रकार के होते हैं?', '[{"id":"A","text":"2 (सुख, दुख)","text_en":"2 (सुख, दुख)"},{"id":"B","text":"3 (जाति, आयु, भोग)","text_en":"3 (जाति, आयु, भोग)"},{"id":"C","text":"4 (धर्म, अर्थ, काम, मोक्ष)","text_en":"4 (धर्म, अर्थ, काम, मोक्ष)"},{"id":"D","text":"5 (क्लेश)","text_en":"5 (क्लेश)"}]', '1', '**✅ Correct Logic:** योगसूत्र (2.13) के अनुसार: "सति मूले तद्विपाको जात्यायुर्भोगाः"। कर्म संस्कार के तीन परिणाम होते हैं: 1. **जाति** (जन्म/योनि), 2. **आयु** (जीवन काल), 3. **भोग** (सुख-दुख का अनुभव)।

**💡 Exam Fact:** यही प्रारब्ध का निर्माण करते हैं।

**🧠 Memory Tip:** J-A-B (Jati, Ayu, Bhoga).

**🚫 Scam Alert:** सुख-दुख केवल ''भोग'' का हिस्सा हैं। पूरा पैकेज J-A-B है।', 2, 0, 9, NULL, 'According to Maharishi Patanjali, Karma-phala (Vipaka) results in how many forms?', '**✅ Correct Logic:** According to Yoga Sutras (2.13): "Sati mule tadvipako jatyayurbhogah". Karma results in 3 things: 1. **Jati** (Birth/Species), 2. **Ayu** (Lifespan), 3. **Bhoga** (Experience of pleasure/pain).

**💡 Exam Fact:** These form the Prarabdha.

**🧠 Memory Tip:** J-A-B (Jati, Ayu, Bhoga).

**🚫 Scam Alert:** Pleasure/Pain is just ''Bhoga''. The full package is J-A-B.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('84933a89-2d65-4e7a-9e57-f0420e033697', '56d1fe30-34a0-410e-893b-5bc629864355', '''सकाम कर्म'' (Sakama Karma) का परिणाम क्या होता है?', '[{"id":"A","text":"मोक्ष (Moksha)","text_en":"मोक्ष (Moksha)"},{"id":"B","text":"जन्म-मृत्यु का बंधन (Bondage of Birth and Death)","text_en":"जन्म-मृत्यु का बंधन (Bondage of Birth and Death)"},{"id":"C","text":"पाप का नाश (Destruction of Sin)","text_en":"पाप का नाश (Destruction of Sin)"},{"id":"D","text":"ईश्वर प्राप्ति (Attainment of God)","text_en":"ईश्वर प्राप्ति (Attainment of God)"}]', '1', '**✅ Correct Logic:** जब हम फल की इच्छा (Desire) से कर्म करते हैं (सकाम), तो वह कर्म ''बीज'' बन जाता है जिसका फल भोगने के लिए हमें बार-बार जन्म लेना पड़ता है। यह ''बंधन'' (Bondage) का कारण है।

**💡 Exam Fact:** स्वर्ग प्राप्ति भी एक ''बंधन'' है (सोने की जंजीर), क्योंकि पुण्य खत्म होने पर वापस आना पड़ता है (क्षीणे पुण्ये मर्त्यलोकं विशन्ति)।

**🧠 Memory Tip:** Desire = Glue. It sticks you to the world.

**🚫 Scam Alert:** अच्छे कर्म (पुण्य) भी यदि सकाम हैं, तो वे मोक्ष नहीं देते, केवल स्वर्ग (Temporary Resort) देते हैं।', 2, 0, 10, NULL, 'What is the result of ''Sakama Karma'' (Action with desire)?', '**✅ Correct Logic:** When we act with Desire (Sakama), that action becomes a ''seed'' forcing us to be reborn to experience the result. This causes ''Bondage''.

**💡 Exam Fact:** Even attaining Heaven is a ''Bondage'' (Golden Chain), as one must return when merit is exhausted.

**🧠 Memory Tip:** Desire = Glue. It sticks you to the world.

**🚫 Scam Alert:** Even Good Deeds (Punya), if done with desire, do not give Moksha, only Heaven (Temporary Resort).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('66bd390e-006a-473a-956a-df9183228922', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', '''बोधिसत्व'' (Bodhisattva) की अवधारणा बौद्ध धर्म की किस शाखा की मुख्य विशेषता है?', '[{"id":"A","text":"हीनयान / थेरवाद (Hinayana / Theravada)","text_en":"हीनयान / थेरवाद (Hinayana / Theravada)"},{"id":"B","text":"महायान (Mahayana)","text_en":"महायान (Mahayana)"},{"id":"C","text":"वज्रयान (Vajrayana)","text_en":"वज्रयान (Vajrayana)"},{"id":"D","text":"जैन धर्म (Jainism)","text_en":"जैन धर्म (Jainism)"}]', '1', '**✅ Correct Logic:** हीनयान का आदर्श ''अर्हत'' (स्वयं की मुक्ति) है, जबकि महायान का आदर्श ''बोधिसत्व'' है। बोधिसत्व वह है जो निर्वाण प्राप्त कर सकता है, लेकिन "करुणा" के कारण संसार के सभी जीवों को मुक्त कराने के लिए अपने निर्वाण को स्थगित (Postpone) कर देता है।

**💡 Exam Fact:** बोधिसत्व = बोधि (ज्ञान) + सत्व (प्राणी/सार)।

**🧠 Memory Tip:** **M**ahayana = **M**any (Saves many) = Bodhisattva.

**🚫 Scam Alert:** हीनयान में भी जातक कथाओं में बोधिसत्व शब्द है, लेकिन केंद्रीय आदर्श (Ideal) के रूप में यह महायान की पहचान है।', 2, 0, 1, NULL, 'The concept of ''Bodhisattva'' is the central feature of which branch of Buddhism?', '**✅ Correct Logic:** Hinayana''s ideal is ''Arhat'' (Self-liberation), while Mahayana''s ideal is ''Bodhisattva''. A Bodhisattva is one who can attain Nirvana but postpones it out of "Compassion" to save all beings.

**💡 Exam Fact:** Bodhisattva = Bodhi (Wisdom) + Sattva (Being/Essence).

**🧠 Memory Tip:** **M**ahayana = **M**any (Saves many) = Bodhisattva.

**🚫 Scam Alert:** Hinayana uses the term in Jatakas, but as a central Ideal, it belongs to Mahayana.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('de919a8f-6294-49f8-839c-7ada6db65f9a', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'किस बोधिसत्व को ''पद्मपाणि'' (Padmapani) भी कहा जाता है, जो हाथ में कमल धारण करते हैं?', '[{"id":"A","text":"मैत्रेय (Maitreya)","text_en":"मैत्रेय (Maitreya)"},{"id":"B","text":"अवलोकितेश्वर (Avalokiteshvara)","text_en":"अवलोकितेश्वर (Avalokiteshvara)"},{"id":"C","text":"मंजुश्री (Manjushri)","text_en":"मंजुश्री (Manjushri)"},{"id":"D","text":"वज्रपाणि (Vajrapani)","text_en":"वज्रपाणि (Vajrapani)"}]', '1', '**✅ Correct Logic:** ''अवलोकितेश्वर'' (जो नीचे जगत को करुणा से देखता है) सबसे लोकप्रिय बोधिसत्व हैं। उन्हें ''पद्मपाणि'' (हाथ में कमल) कहा जाता है। अजंता की गुफा नं. 1 में इनका प्रसिद्ध चित्र है।

**💡 Exam Fact:** दलाई लामा को अवलोकितेश्वर का ही अवतार माना जाता है।

**🧠 Memory Tip:** Avalokiteshvara = **A**vatar of Compassion = **L**otus (Love).

**🚫 Scam Alert:** वज्रपाणि हाथ में वज्र (Thunderbolt) रखते हैं। पद्मपाणि = कमल।', 2, 0, 2, NULL, 'Which Bodhisattva is also known as ''Padmapani'', holding a Lotus in hand?', '**✅ Correct Logic:** ''Avalokiteshvara'' (The Lord who looks down with compassion) is the most popular. He is called ''Padmapani'' (Lotus in hand). Famous painting in Ajanta Cave 1.

**💡 Exam Fact:** Dalai Lama is considered an incarnation of Avalokiteshvara.

**🧠 Memory Tip:** Avalokiteshvara = **A**vatar of Compassion = **L**otus (Love).

**🚫 Scam Alert:** Vajrapani holds Vajra. Padmapani = Lotus.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('74c19e82-0766-4f81-9488-6413af2a35e1', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'भविष्य में अवतार लेने वाले बुद्ध (Future Buddha) के रूप में किस बोधिसत्व को जाना जाता है?', '[{"id":"A","text":"अवलोकितेश्वर (Avalokiteshvara)","text_en":"अवलोकितेश्वर (Avalokiteshvara)"},{"id":"B","text":"मंजुश्री (Manjushri)","text_en":"मंजुश्री (Manjushri)"},{"id":"C","text":"मैत्रेय (Maitreya)","text_en":"मैत्रेय (Maitreya)"},{"id":"D","text":"क्षितिगर्भ (Kshitigarbha)","text_en":"क्षितिगर्भ (Kshitigarbha)"}]', '2', '**✅ Correct Logic:** ''मैत्रेय'' (Maitreya) भावी बुद्ध हैं जो अभी तुषित स्वर्ग में निवास कर रहे हैं और भविष्य में धरती पर धर्म की पुनः स्थापना करेंगे। उन्हें अक्सर कलश (Water pot) धारण किए दिखाया जाता है।

**💡 Exam Fact:** इनका नाम ''मित्र'' (Friendship/Love) शब्द से बना है।

**🧠 Memory Tip:** Maitreya = **M**etrow (Future transport) -> Future Buddha.

**🚫 Scam Alert:** अमिताभ (Amitabha) अलग हैं, वे ''ध्यानी बुद्ध'' हैं। मैत्रेय ''भावी बुद्ध'' हैं।', 2, 0, 3, NULL, 'Which Bodhisattva is known as the ''Future Buddha'' destined to incarnate?', '**✅ Correct Logic:** ''Maitreya'' is the Future Buddha currently residing in Tushita Heaven, destined to restore Dharma on earth. Often depicted holding a Water pot.

**💡 Exam Fact:** His name comes from ''Mitra'' (Friendship).

**🧠 Memory Tip:** Maitreya = **M**etrow (Future transport) -> Future Buddha.

**🚫 Scam Alert:** Amitabha is different (Dhyani Buddha). Maitreya is Future Buddha.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('415c11be-9948-42de-9c80-163e5c868f7a', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'बोधिसत्वों को उनके प्रतीक/विशेषता से सुमेलित करें (Match the Bodhisattvas with their attributes/symbols):', '[{"id":"A","text":"(1)-(b), (2)-(c), (3)-(a), (4)-(d)","text_en":"(1)-(b), (2)-(c), (3)-(a), (4)-(d)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)","text_en":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)"}]', '0', '**✅ Correct Logic:**
* **मंजुश्री:** तलवार (अज्ञान काटने के लिए) और प्रज्ञापारमिता सूत्र (पुस्तक)।
* **वज्रपाणि:** इंद्र के समान, बुद्ध के रक्षक। कठोर रूप।
* **अवलोकितेश्वर:** सौम्य, करुणा।
* **क्षितिगर्भ:** पाताल/नरक में फंसे जीवों के रक्षक।

**💡 Exam Fact:** मंजुश्री सबसे पुराने बोधिसत्वों में से एक हैं।

**🧠 Memory Tip:** Manjushri = **M**ind (Wisdom). Vajrapani = **V**iolence (Power). Avalokiteshvara = **A**ffection.

**🚫 Scam Alert:** मंजुश्री की तलवार हिंसा के लिए नहीं, अज्ञान नाश के लिए है।', 2, 0, 5, NULL, 'Match the Bodhisattvas with their attributes/symbols:', '**✅ Correct Logic:**
* **Manjushri:** Sword (to cut ignorance) and Book (Wisdom).
* **Vajrapani:** Like Indra, protector of Buddha. Stern form.
* **Avalokiteshvara:** Gentle, Compassion.
* **Kshitigarbha:** Savior of beings in Hell/Underworld.

**💡 Exam Fact:** Manjushri is one of the oldest Bodhisattvas.

**🧠 Memory Tip:** Manjushri = **M**ind (Wisdom). Vajrapani = **V**iolence (Power). Avalokiteshvara = **A**ffection.

**🚫 Scam Alert:** Manjushri''s sword is not for violence, but for cutting ignorance.', 60, 'matching', '[{"id":"(1)","label":"मंजुश्री (Manjushri)","match":"प्रज्ञा/बुद्धि, हाथ में खड्ग और पुस्तक (Wisdom, Sword and Book in hand)","matchId":"(b)"},{"id":"(2)","label":"वज्रपाणि (Vajrapani)","match":"पाप/असत्य का नाश करने वाला, हाथ में वज्र (Destroyer of Sin/Falsehood, Vajra in hand)","matchId":"(c)"},{"id":"(3)","label":"अवलोकितेश्वर (Avalokiteshvara)","match":"अपार करुणा (Great Compassion)","matchId":"(a)"},{"id":"(4)","label":"क्षितिगर्भ (Kshitigarbha)","match":"नरक के जीवों की मुक्ति (Savior of beings in Hell)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a9f78e6c-701f-47f0-b3dd-94b8c4d683ac', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'बोधिसत्व बनने के लिए किन गुणों का विकास करना आवश्यक है?', '[{"id":"A","text":"त्रि-रत्न (Tri-Ratna)","text_en":"त्रि-रत्न (Tri-Ratna)"},{"id":"B","text":"पारमिता (Paramitas)","text_en":"पारमिता (Paramitas)"},{"id":"C","text":"पंच-महाव्रत (Pancha Mahavrata)","text_en":"पंच-महाव्रत (Pancha Mahavrata)"},{"id":"D","text":"स्याद्वाद (Syadvada)","text_en":"स्याद्वाद (Syadvada)"}]', '1', '**✅ Correct Logic:** बोधिसत्व को 6 या 10 ''पारमिताओं'' (Perfections) का अभ्यास करना होता है। इनमें दान, शील, क्षांति (धैर्य), वीर्य (साहस), ध्यान और प्रज्ञा शामिल हैं। ''प्रज्ञा-पारमिता'' सबसे महत्वपूर्ण है।

**💡 Exam Fact:** ''पारमिता'' का अर्थ है ''परम अवस्था'' या ''पार जाना''।

**🧠 Memory Tip:** Paramita = **P**erfection required for Bodhisattva.

**🚫 Scam Alert:** पंच-महाव्रत जैन धर्म के हैं। त्रि-रत्न दोनों में हैं, लेकिन ''पारमिता'' विशिष्ट रूप से बोधिसत्व का मार्ग है।', 2, 0, 4, NULL, 'Which virtues are essential to develop to become a Bodhisattva?', '**✅ Correct Logic:** A Bodhisattva must practice 6 or 10 ''Paramitas'' (Perfections). They include Dana (Giving), Shila (Morality), Kshanti (Patience), Virya (Vigor), Dhyana, and Prajna (Wisdom).

**💡 Exam Fact:** ''Paramita'' means ''Supreme state'' or ''Going beyond''.

**🧠 Memory Tip:** Paramita = **P**erfection required for Bodhisattva.

**🚫 Scam Alert:** Pancha-Mahavrata belongs to Jainism. Paramita is specifically the Bodhisattva path.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('190ccc3a-c82f-4fe3-bfbd-dd1003554b7a', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'कथन (A): बोधिसत्व अपनी मुक्ति (निर्वाण) को स्थगित कर देते हैं।
कारण (R): उनका उद्देश्य ''महाकरुणा'' से प्रेरित होकर समस्त प्राणियों को दुख से मुक्त करना है।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic:** बोधिसत्व का प्रसिद्ध संकल्प है: "जब तक एक भी प्राणी दुख में है, मैं निर्वाण में प्रवेश नहीं करूँगा।" यह ''स्व'' (Self) के पूर्ण त्याग और महाकरुणा (Great Compassion) का प्रतीक है।

**💡 Exam Fact:** इसे हीनयान के ''अर्हत'' (Self-liberation) से श्रेष्ठ माना गया है।

**🧠 Memory Tip:** Bodhisattva = Lifeboat Captain (Leaves ship last).

**🚫 Scam Alert:** वे निर्वाण पाने में ''असमर्थ'' नहीं हैं, वे स्वेच्छा से ''रुकते'' हैं।', 2, 0, 6, NULL, 'Assertion (A): Bodhisattvas postpone their own liberation (Nirvana).
Reason (R): Their aim is guided by ''Great Compassion'' to liberate all beings from suffering.
Select the correct option:', '**✅ Correct Logic:** The famous vow of Bodhisattva is: "As long as even one being is in suffering, I shall not enter Nirvana." This symbolizes total loss of Self and Great Compassion.

**💡 Exam Fact:** This is considered superior to Hinayana''s ''Arhat''.

**🧠 Memory Tip:** Bodhisattva = Lifeboat Captain (Leaves ship last).

**🚫 Scam Alert:** They are not ''unable'' to get Nirvana, they voluntarily ''wait''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ce53656a-882c-4a11-ad24-99a82534d88f', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', '''अमिताभ'' (Amitabha) कौन हैं?', '[{"id":"A","text":"सुखावती स्वर्ग के ध्यानी बुद्ध (Dhyani Buddha of Sukhavati Heaven)","text_en":"सुखावती स्वर्ग के ध्यानी बुद्ध (Dhyani Buddha of Sukhavati Heaven)"},{"id":"B","text":"एक बोधिसत्व (A Bodhisattva)","text_en":"एक बोधिसत्व (A Bodhisattva)"},{"id":"C","text":"एक जैन तीर्थंकर (A Jain Tirthankara)","text_en":"एक जैन तीर्थंकर (A Jain Tirthankara)"},{"id":"D","text":"बुद्ध के शिष्य (Disciple of Buddha)","text_en":"बुद्ध के शिष्य (Disciple of Buddha)"}]', '0', '**✅ Correct Logic:** अमिताभ (अमित + आभा = अनंत प्रकाश) महायान बौद्ध धर्म के प्रमुख ''ध्यानी बुद्ध'' हैं। वे पश्चिमी स्वर्ग ''सुखावती'' (Pure Land) के शासक माने जाते हैं। बोधिसत्व अवलोकितेश्वर इन्हीं के अंश माने जाते हैं।

**💡 Exam Fact:** जापान और चीन में ''Pure Land Buddhism'' इन्हीं पर केंद्रित है।

**🧠 Memory Tip:** Amitabha = **A**mit (Infinite) Light.

**🚫 Scam Alert:** वे बोधिसत्व नहीं, बल्कि ''बुद्ध'' (Tathagata) की श्रेणी में हैं।', 2, 0, 7, NULL, 'Who is ''Amitabha''?', '**✅ Correct Logic:** Amitabha (Infinite Light) is a major ''Dhyani Buddha'' of Mahayana. He rules the Western Paradise ''Sukhavati'' (Pure Land). Bodhisattva Avalokiteshvara is considered his emanation.

**💡 Exam Fact:** ''Pure Land Buddhism'' in Japan/China focuses on him.

**🧠 Memory Tip:** Amitabha = **A**mit (Infinite) Light.

**🚫 Scam Alert:** He is not a Bodhisattva, but in the category of ''Buddha'' (Tathagata).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2f1aee7c-e6c3-4d9f-ab49-767c0629a206', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'किस बोधिसत्व को ''वज्र'' (Thunderbolt) धारण करने के कारण ग्रीक देवता ''हरक्यूलिस'' या ''ज्यूस'' के समान माना गया है?', '[{"id":"A","text":"वज्रपाणि (Vajrapani)","text_en":"वज्रपाणि (Vajrapani)"},{"id":"B","text":"पद्मपाणि (Padmapani)","text_en":"पद्मपाणि (Padmapani)"},{"id":"C","text":"मैत्रेय (Maitreya)","text_en":"मैत्रेय (Maitreya)"},{"id":"D","text":"समंतभद्र (Samantabhadra)","text_en":"समंतभद्र (Samantabhadra)"}]', '0', '**✅ Correct Logic:** वज्रपाणि (वज्र + पाणि = हाथ में वज्र)। गांधार कला (Gandhara Art) में उन्हें अत्यंत बलिष्ठ (Muscular) दिखाया गया है, जो ग्रीक प्रभाव (हरक्यूलिस) को दर्शाता है। वे बुद्ध के अंगरक्षक माने जाते हैं।

**💡 Exam Fact:** वे ''शक्ति'' (Power) का प्रतीक हैं।

**🧠 Memory Tip:** Vajra = Thunderbolt = Zeus/Indra power.

**🚫 Scam Alert:** नाम में ही ''वज्र'' है, उत्तर आसान है, लेकिन ग्रीक कनेक्शन याद रखें।', 2, 0, 8, NULL, 'Which Bodhisattva is considered similar to Greek god ''Hercules'' or ''Zeus'' because of holding a ''Vajra'' (Thunderbolt)?', '**✅ Correct Logic:** Vajrapani (Vajra in hand). In Gandhara Art, he is depicted as very muscular, showing Greek influence (Hercules). He is the bodyguard of Buddha.

**💡 Exam Fact:** He symbolizes ''Power''.

**🧠 Memory Tip:** Vajra = Thunderbolt = Zeus/Indra power.

**🚫 Scam Alert:** Name has ''Vajra'', answer is easy, but remember the Greek connection.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fbc6b672-6ced-4bcb-9586-f8a9da9bb763', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'महायान बौद्ध धर्म में ''प्रज्ञापारमिता'' (Prajnaparamita) का मानवीकरण किस रूप में किया गया है?', '[{"id":"A","text":"एक देवी (A Goddess)","text_en":"एक देवी (A Goddess)"},{"id":"B","text":"एक पुरुष देवता (A Male Deity)","text_en":"एक पुरुष देवता (A Male Deity)"},{"id":"C","text":"एक जानवर (An Animal)","text_en":"एक जानवर (An Animal)"},{"id":"D","text":"एक स्तूप (A Stupa)","text_en":"एक स्तूप (A Stupa)"}]', '0', '**✅ Correct Logic:** प्रज्ञापारमिता (पूर्ण ज्ञान) को ''सभी बुद्धों की माता'' (Mother of all Buddhas) माना जाता है और इसे एक देवी के रूप में पूजा जाता है। तारा (Tara) भी एक प्रमुख बौद्ध देवी हैं जो अवलोकितेश्वर से जुड़ी हैं।

**💡 Exam Fact:** यह बौद्ध धर्म में ''स्त्री शक्ति'' (Feminine divine) का उदय दर्शाता है।

**🧠 Memory Tip:** Prajna (Wisdom) is feminine -> Goddess.

**🚫 Scam Alert:** आम तौर पर बुद्ध पुरुष हैं, लेकिन प्रज्ञापारमिता ''देवी'' हैं।', 2, 0, 9, NULL, 'In Mahayana Buddhism, ''Prajnaparamita'' is personified as:', '**✅ Correct Logic:** Prajnaparamita (Perfection of Wisdom) is considered ''Mother of all Buddhas'' and worshiped as a Goddess. Tara is also a major Buddhist goddess linked to Avalokiteshvara.

**💡 Exam Fact:** This shows the rise of ''Feminine divine'' in Buddhism.

**🧠 Memory Tip:** Prajna (Wisdom) is feminine -> Goddess.

**🚫 Scam Alert:** Usually Buddhas are male, but Prajnaparamita is a ''Goddess''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3f5ffc13-35a8-4348-8873-e130d5b67239', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'किस बोधिसत्व का संबंध ''जापान'' में बच्चों और यात्रियों के संरक्षक (Jizo) के रूप में है?', '[{"id":"A","text":"क्षितिगर्भ (Kshitigarbha)","text_en":"क्षितिगर्भ (Kshitigarbha)"},{"id":"B","text":"मैत्रेय (Maitreya)","text_en":"मैत्रेय (Maitreya)"},{"id":"C","text":"अवलोकितेश्वर (Avalokiteshvara)","text_en":"अवलोकितेश्वर (Avalokiteshvara)"},{"id":"D","text":"आकाशगर्भ (Akashagarbha)","text_en":"आकाशगर्भ (Akashagarbha)"}]', '0', '**✅ Correct Logic:** क्षितिगर्भ (Kshitigarbha) ने कसम खाई थी कि जब तक नरक खाली नहीं होगा, वे बुद्ध नहीं बनेंगे। जापान में उन्हें ''Jizo'' कहा जाता है, जो बच्चों (विशेषकर जो जन्म नहीं ले पाए) और यात्रियों की रक्षा करते हैं।

**💡 Exam Fact:** इनका चित्रण अक्सर एक भिक्षु के रूप में होता है।

**🧠 Memory Tip:** Kshiti = Earth. Savior on Earth and Hell.

**🚫 Scam Alert:** यह थोड़ा कठिन प्रश्न है, लेकिन ''क्षितिगर्भ'' करुणा के रक्षक हैं।', 2, 0, 10, NULL, 'Which Bodhisattva is associated as the guardian of children and travelers (Jizo) in Japan?', '**✅ Correct Logic:** Kshitigarbha vowed not to become Buddha until Hell is empty. In Japan, he is called ''Jizo'', protecting children (esp. unborn) and travelers.

**💡 Exam Fact:** Often depicted as a monk.

**🧠 Memory Tip:** Kshiti = Earth. Savior on Earth and Hell.

**🚫 Scam Alert:** Tough question, but ''Kshitigarbha'' is the guardian.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9f5cd76e-1fd2-42cb-abf4-e10038cb69b1', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'जैन धर्म में ''तीर्थंकर'' का शाब्दिक अर्थ क्या है?', '[{"id":"A","text":"तीर्थ यात्रा कराने वाला (One who organizes pilgrimage)","text_en":"तीर्थ यात्रा कराने वाला (One who organizes pilgrimage)"},{"id":"B","text":"संसार रूपी सागर से पार उतारने के लिए ''तीर्थ'' (घाट/मार्ग) बनाने वाला (Ford-maker who builds a ford/path to cross the ocean of existence)","text_en":"संसार रूपी सागर से पार उतारने के लिए ''तीर्थ'' (घाट/मार्ग) बनाने वाला (Ford-maker who builds a ford/path to cross the ocean of existence)"},{"id":"C","text":"ईश्वर का अवतार (Incarnation of God)","text_en":"ईश्वर का अवतार (Incarnation of God)"},{"id":"D","text":"कठोर तपस्वी (Severe Ascetic)","text_en":"कठोर तपस्वी (Severe Ascetic)"}]', '1', '**✅ Correct Logic:** ''तीर्थ'' का अर्थ है नदी का वह घाट (Ford) जिससे आसानी से पार जाया जा सके। तीर्थंकर वे महापुरुष हैं जो धर्म रूपी तीर्थ की रचना करते हैं ताकि जीव संसार सागर (जन्म-मरण) को पार कर सकें।

**💡 Exam Fact:** जैन धर्म में कुल 24 तीर्थंकर माने गए हैं।

**🧠 Memory Tip:** Tirthankara = **T**ransit maker (Bridge builder for souls).

**🚫 Scam Alert:** वे ''अवतार'' नहीं हैं, वे मनुष्य थे जिन्होंने अपनी मेहनत से कैवल्य पाया।', 2, 0, 1, NULL, 'What is the literal meaning of ''Tirthankara'' in Jainism?', '**✅ Correct Logic:** ''Tirtha'' means a Ford/Crossing place. Tirthankaras are those who create the ''Tirtha'' (Path of Dharma) to help beings cross the ocean of existence (Cycle of birth-death).

**💡 Exam Fact:** There are total 24 Tirthankaras.

**🧠 Memory Tip:** Tirthankara = **T**ransit maker (Bridge builder for souls).

**🚫 Scam Alert:** They are not ''Avatars''; they were humans who attained Kaivalya by effort.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b02ebc8c-79c0-4dbe-860a-357eac50886a', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'प्रथम तीर्थंकर ऋषभदेव (आदिनाथ) का प्रतीक चिन्ह (Symbol) क्या है?', '[{"id":"A","text":"सिंह (Lion)","text_en":"सिंह (Lion)"},{"id":"B","text":"सर्प (Snake/Serpent)","text_en":"सर्प (Snake/Serpent)"},{"id":"C","text":"वृषभ/बैल (Bull)","text_en":"वृषभ/बैल (Bull)"},{"id":"D","text":"शंख (Conch)","text_en":"शंख (Conch)"}]', '2', '**✅ Correct Logic:** ऋषभ का अर्थ ही ''बैल'' (Bull) होता है। इसलिए इनका प्रतीक वृषभ है। ऋग्वेद में भी इनका उल्लेख मिलता है।

**💡 Exam Fact:** इनका जन्म अयोध्या में हुआ माना जाता है।

**🧠 Memory Tip:** **Rishabh** sounds like **Vrishabh** (Bull).

**🚫 Scam Alert:** सिंह महावीर का है, सर्प पार्श्वनाथ का।', 2, 0, 2, NULL, 'What is the symbol of the first Tirthankara Rishabhdeva (Adinatha)?', '**✅ Correct Logic:** Rishabh literally means ''Bull''. Hence his symbol is Bull. He is also mentioned in Rigveda.

**💡 Exam Fact:** Believed to be born in Ayodhya.

**🧠 Memory Tip:** **Rishabh** sounds like **Vrishabh** (Bull).

**🚫 Scam Alert:** Lion is Mahavira''s, Snake is Parsvanath''s.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('66dfbfe2-ab39-4490-a205-d76af0987c05', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', '23वें तीर्थंकर पार्श्वनाथ ने ''चातुर्याम धर्म'' (Fourfold restraint) प्रतिपादित किया था। महावीर स्वामी ने उसमें पांचवां कौन सा व्रत जोड़ा?', '[{"id":"A","text":"अहिंसा (Non-violence)","text_en":"अहिंसा (Non-violence)"},{"id":"B","text":"सत्य (Truth)","text_en":"सत्य (Truth)"},{"id":"C","text":"ब्रह्मचर्य (Celibacy)","text_en":"ब्रह्मचर्य (Celibacy)"},{"id":"D","text":"अपरिग्रह (Non-possession)","text_en":"अपरिग्रह (Non-possession)"}]', '2', '**✅ Correct Logic:** पार्श्वनाथ के 4 व्रत थे: सत्य, अहिंसा, अस्तेय, अपरिग्रह। महावीर स्वामी ने महसूस किया कि इंद्रिय संयम के बिना ये कठिन हैं, इसलिए उन्होंने 5वां व्रत ''ब्रह्मचर्य'' (Celibacy) जोड़ा।

**💡 Exam Fact:** पार्श्वनाथ के अनुयायियों को ''निर्ग्रंथ'' कहा जाता था और वे वस्त्र पहन सकते थे, लेकिन महावीर ने नग्नता (दिगंबर) पर जोर दिया।

**🧠 Memory Tip:** Mahavira = Maha Vow (Brahmacharya).

**🚫 Scam Alert:** अहिंसा जैन धर्म का मूल है, लेकिन वह पहले से (पार्श्वनाथ के समय से) था।', 2, 0, 3, NULL, '23rd Tirthankara Parsvanath propounded ''Chaturyama Dharma''. Which fifth vow did Mahavira Swami add to it?', '**✅ Correct Logic:** Parsvanath''s 4 vows were: Satya, Ahimsa, Asteya, Aparigraha. Mahavira added the 5th vow ''Brahmacharya'' (Celibacy).

**💡 Exam Fact:** Parsvanath''s followers were called ''Nirgranthas'' and could wear clothes, but Mahavira emphasized nudity (Digambara).

**🧠 Memory Tip:** Mahavira = Maha Vow (Brahmacharya).

**🚫 Scam Alert:** Ahimsa is core, but it existed before Mahavira (from Parsvanath).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('231639af-1ea6-4b19-a328-1fa5875f4f3c', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'तीर्थंकरों को उनके प्रतीक चिन्ह से सुमेलित करें (Match the Tirthankaras with their Symbols):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Logic:**
* **महावीर:** सिंह (वीरता का प्रतीक)।
* **पार्श्वनाथ:** सर्प (कथा है कि नाग ने उनकी रक्षा की थी)।
* **नेमिनाथ:** शंख (इन्हें कृष्ण का चचेरा भाई माना जाता है, शंख कृष्ण से जुड़ा है)।
* **मल्लिनाथ:** कलश (श्वेतांबर इन्हें स्त्री मानते हैं, दिगंबर पुरुष)।

**💡 Exam Fact:** अजीतनाथ (दूसरे) का प्रतीक ''हाथी'' है।

**🧠 Memory Tip:** Mahavira = Lion King. Parsva = Snake. Nemi = Krishna''s bro = Conch.

**🚫 Scam Alert:** नेमिनाथ और अरिष्टनेमि एक ही हैं (22वें)। 21वें नमिनाथ अलग हैं (नील कमल)।', 2, 0, 5, NULL, 'Match the Tirthankaras with their Symbols:', '**✅ Correct Logic:**
* **Mahavira:** Lion (Bravery).
* **Parsvanath:** Snake (Legend of snake protecting him).
* **Neminath:** Conch (Considered cousin of Krishna).
* **Mallinath:** Pot (Shvetambaras consider female, Digambaras male).

**💡 Exam Fact:** Ajitnath (2nd) symbol is Elephant.

**🧠 Memory Tip:** Mahavira = Lion King. Parsva = Snake. Nemi = Krishna''s bro = Conch.

**🚫 Scam Alert:** Neminath and Arishtanemi are same (22nd). Naminath (21st) is different.', 60, 'matching', '[{"id":"(1)","label":"महावीर (Mahavira)","match":"सिंह (Lion)","matchId":"(a)"},{"id":"(2)","label":"पार्श्वनाथ (Parsvanath)","match":"सर्प फण (Snake Hood)","matchId":"(b)"},{"id":"(3)","label":"नेमिनाथ (Neminath)","match":"शंख (Conch Shell)","matchId":"(c)"},{"id":"(4)","label":"मल्लिनाथ (Mallinath)","match":"कलश (Water Pot)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('60645def-0007-4886-b736-c1eeb48b75ba', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'किस तीर्थंकर को ऐतिहासिक रूप से प्रथम प्रमाणित (First Historically Verified) माना जाता है?', '[{"id":"A","text":"ऋषभदेव (Rishabhdeva)","text_en":"ऋषभदेव (Rishabhdeva)"},{"id":"B","text":"पार्श्वनाथ (Parsvanath)","text_en":"पार्श्वनाथ (Parsvanath)"},{"id":"C","text":"महावीर (Mahavira)","text_en":"महावीर (Mahavira)"},{"id":"D","text":"अजितनाथ (Ajitnath)","text_en":"अजितनाथ (Ajitnath)"}]', '1', '**✅ Correct Logic:** यद्यपि ऋषभदेव पहले हैं, लेकिन ऐतिहासिक प्रमाणों (Historical evidence) के आधार पर 23वें तीर्थंकर ''पार्श्वनाथ'' को पहला ऐतिहासिक व्यक्ति माना जाता है। वे महावीर से 250 वर्ष पूर्व हुए थे और बनारस के राजा अश्वसेन के पुत्र थे।

**💡 Exam Fact:** ऋषभदेव और अरिष्टनेमि का उल्लेख ऋग्वेद में है, लेकिन ऐतिहासिकता पार्श्वनाथ से सिद्ध होती है।

**🧠 Memory Tip:** Parsvanath = **P**roven History.

**🚫 Scam Alert:** महावीर 24वें हैं, लेकिन उनसे पहले पार्श्वनाथ ऐतिहासिक सिद्ध हो चुके हैं।', 2, 0, 4, NULL, 'Which Tirthankara is considered the ''First Historically Verified'' figure?', '**✅ Correct Logic:** Although Rishabhdeva is first, based on historical evidence, 23rd Tirthankara ''Parsvanath'' is considered the first historical figure. He lived 250 years before Mahavira and was son of King Ashvasena of Banaras.

**💡 Exam Fact:** Rishabhdeva and Arishtanemi are mentioned in Rigveda, but historicity starts with Parsvanath.

**🧠 Memory Tip:** Parsvanath = **P**roven History.

**🚫 Scam Alert:** Mahavira is 24th, but Parsvanath before him is historically proven.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d02fabb7-197c-49cf-bc7e-399f6774b695', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'श्वेतांबर परंपरा के अनुसार, एकमात्र ''स्त्री'' तीर्थंकर कौन थीं?', '[{"id":"A","text":"मल्लिनाथ (Mallinath)","text_en":"मल्लिनाथ (Mallinath)"},{"id":"B","text":"नेमिनाथ (Neminath)","text_en":"नेमिनाथ (Neminath)"},{"id":"C","text":"शांतिनाथ (Shantinath)","text_en":"शांतिनाथ (Shantinath)"},{"id":"D","text":"वासुपूज्य (Vasupujya)","text_en":"वासुपूज्य (Vasupujya)"}]', '0', '**✅ Correct Logic:** 19वें तीर्थंकर ''मल्लिनाथ'' को श्वेतांबर ''मल्ली कुमारी'' (स्त्री) मानते हैं, जबकि दिगंबर उन्हें पुरुष मानते हैं (क्योंकि दिगंबरों के अनुसार स्त्री मुक्ति नहीं पा सकती)।

**💡 Exam Fact:** मल्लिनाथ का प्रतीक ''कलश'' है जो स्त्री सुलभ (घरेलू) प्रतीक माना जा सकता है।

**🧠 Memory Tip:** Malli sounds like a girl''s name.

**🚫 Scam Alert:** यह श्वेतांबर-दिगंबर का प्रमुख विवाद है।', 2, 0, 6, NULL, 'According to Shvetambara tradition, who was the only ''Female'' Tirthankara?', '**✅ Correct Logic:** 19th Tirthankara ''Mallinath'' is considered ''Malli Kumari'' (Female) by Shvetambaras, while Digambaras consider him Male (as they believe women cannot attain liberation).

**💡 Exam Fact:** Mallinath''s symbol is ''Pot'', often linked to domestic/female sphere.

**🧠 Memory Tip:** Malli sounds like a girl''s name.

**🚫 Scam Alert:** This is a major dispute between Shvetambara and Digambara.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6a0b70ae-3c81-4a48-aea7-8da7abc63dbd', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'महावीर स्वामी को किस नदी के तट पर ''कैवल्य'' (पूर्ण ज्ञान) की प्राप्ति हुई थी?', '[{"id":"A","text":"निरंजना (Niranjana)","text_en":"निरंजना (Niranjana)"},{"id":"B","text":"ऋजुपालिका (Rijupalika)","text_en":"ऋजुपालिका (Rijupalika)"},{"id":"C","text":"गंगा (Ganga)","text_en":"गंगा (Ganga)"},{"id":"D","text":"यमुना (Yamuna)","text_en":"यमुना (Yamuna)"}]', '1', '**✅ Correct Logic:** महावीर स्वामी को 12 वर्ष की कठोर तपस्या के बाद जृम्भिकग्राम के पास ''ऋजुपालिका'' नदी के तट पर साल वृक्ष के नीचे ज्ञान (कैवल्य) मिला।

**💡 Exam Fact:** बुद्ध को ''निरंजना'' नदी के तट पर ज्ञान मिला था। इन दोनों नदियों में अक्सर कन्फ्यूजन होता है।

**🧠 Memory Tip:** Mahavi**R**a = **R**ijupalika. Buddha = Niranjana.

**🚫 Scam Alert:** निरंजना (फाल्गु) बुद्ध से जुड़ी है। ऋजुपालिका महावीर से।', 2, 0, 7, NULL, 'On the banks of which river did Mahavira Swami attain ''Kaivalya'' (Omniscience)?', '**✅ Correct Logic:** Mahavira attained Kaivalya after 12 years of penance near Jrimbhikagrama on the banks of ''Rijupalika'' river under a Sal tree.

**💡 Exam Fact:** Buddha attained enlightenment on banks of ''Niranjana''. Confusion is common.

**🧠 Memory Tip:** Mahavi**R**a = **R**ijupalika. Buddha = Niranjana.

**🚫 Scam Alert:** Niranjana is linked to Buddha. Rijupalika to Mahavira.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2920c4f4-cae3-4049-a343-0cc54560e4a2', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'किस तीर्थंकर का संबंध भगवान श्री कृष्ण का ''निकट संबंधी'' (Cousin) माना जाता है?', '[{"id":"A","text":"ऋषभदेव (Rishabhdeva)","text_en":"ऋषभदेव (Rishabhdeva)"},{"id":"B","text":"अरिष्टनेमि / नेमिनाथ (Arishtanemi / Neminath)","text_en":"अरिष्टनेमि / नेमिनाथ (Arishtanemi / Neminath)"},{"id":"C","text":"पार्श्वनाथ (Parsvanath)","text_en":"पार्श्वनाथ (Parsvanath)"},{"id":"D","text":"संभवनाथ (Sambhavnath)","text_en":"संभवनाथ (Sambhavnath)"}]', '1', '**✅ Correct Logic:** 22वें तीर्थंकर ''अरिष्टनेमि'' (नेमिनाथ) को अंधक-वृष्णि वंश का माना जाता है और पौराणिक परंपरा में उन्हें श्री कृष्ण का चचेरा भाई बताया गया है।

**💡 Exam Fact:** छांदोग्य उपनिषद में घोर आंगिरस के शिष्य के रूप में देवकी पुत्र कृष्ण का उल्लेख है, जो जैन परंपरा से साम्य रखता है।

**🧠 Memory Tip:** Nemi = Name closer to Krishna mythology.

**🚫 Scam Alert:** केवल नेमिनाथ, अन्य कोई नहीं।', 2, 0, 8, NULL, 'Which Tirthankara is considered a ''Close Relative'' (Cousin) of Lord Krishna?', '**✅ Correct Logic:** 22nd Tirthankara ''Arishtanemi'' (Neminath) belongs to Andhaka-Vrishni clan and is considered a cousin of Krishna in Puranic tradition.

**💡 Exam Fact:** Chandogya Upanishad mentions Krishna, son of Devaki, as disciple of Ghora Angirasa.

**🧠 Memory Tip:** Nemi = Name closer to Krishna mythology.

**🚫 Scam Alert:** Only Neminath, no one else.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('aaafb41c-7c47-4073-8317-0025b53a94e4', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'जैन धर्म के ''त्रिरत्न'' (Three Jewels) में निम्नलिखित में से कौन शामिल नहीं है?', '[{"id":"A","text":"सम्यक दर्शन (Right Faith)","text_en":"सम्यक दर्शन (Right Faith)"},{"id":"B","text":"सम्यक ज्ञान (Right Knowledge)","text_en":"सम्यक ज्ञान (Right Knowledge)"},{"id":"C","text":"सम्यक आचरण/चरित्र (Right Conduct)","text_en":"सम्यक आचरण/चरित्र (Right Conduct)"},{"id":"D","text":"सम्यक वाणी (Right Speech)","text_en":"सम्यक वाणी (Right Speech)"}]', '3', '**✅ Correct Logic:** जैन त्रिरत्न हैं: 1. सम्यक दर्शन (विश्वास), 2. सम्यक ज्ञान, 3. सम्यक चरित्र (आचरण)। ''सम्यक वाणी'' अष्टांगिक मार्ग (बौद्ध धर्म) का हिस्सा है, जैन त्रिरत्न का नहीं।

**💡 Exam Fact:** जैन धर्म में मोक्ष के लिए तीनों का एक साथ होना आवश्यक है (जैसे दवा पर विश्वास, जानकारी और सेवन)।

**🧠 Memory Tip:** KFC (Knowledge, Faith, Conduct).

**🚫 Scam Alert:** बौद्ध धर्म में भी त्रिरत्न हैं (बुद्ध, धम्म, संघ), लेकिन यह जैन ''दर्शन'' के त्रिरत्न पूछ रहा है।', 2, 0, 9, NULL, 'Which of the following is NOT included in the ''Triratna'' (Three Jewels) of Jainism?', '**✅ Correct Logic:** Jain Triratnas are: 1. Right Faith, 2. Right Knowledge, 3. Right Conduct. ''Right Speech'' is part of Eightfold Path (Buddhism).

**💡 Exam Fact:** In Jainism, all three together are necessary for Moksha.

**🧠 Memory Tip:** KFC (Knowledge, Faith, Conduct).

**🚫 Scam Alert:** Buddhism also has Triratna (Buddha, Dhamma, Sangha), but this asks for Jain ''Philosophy'' Triratna.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5930387d-f8ff-4608-8f64-ab00354d4018', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', '''स्याद्वाद'' (Syadvada) या ''सप्तभंगी नय'' किस धर्म का मौलिक दार्शनिक सिद्धांत है?', '[{"id":"A","text":"बौद्ध (Buddhism)","text_en":"बौद्ध (Buddhism)"},{"id":"B","text":"जैन (Jainism)","text_en":"जैन (Jainism)"},{"id":"C","text":"सांख्य (Sankhya)","text_en":"सांख्य (Sankhya)"},{"id":"D","text":"अजीवक (Ajivika)","text_en":"अजीवक (Ajivika)"}]', '1', '**✅ Correct Logic:** स्याद्वाद (Theory of ''Maybe'' or Relativity of Truth) जैन धर्म का सिद्धांत है। इसके अनुसार, सत्य अनंत है और हम उसे केवल एक दृष्टिकोण से देखते हैं। "शायद यह है, शायद यह नहीं है"।

**💡 Exam Fact:** इसे ''अनेकांतवाद'' का तार्किक रूप कहा जाता है। हाथी और अंधों की कहानी इसका उदाहरण है।

**🧠 Memory Tip:** Syad = Shaayad (Maybe). Jainism respects all views.

**🚫 Scam Alert:** यह बौद्ध धर्म के ''शून्यवाद'' से अलग है। स्याद्वाद = जैन।', 2, 0, 10, NULL, '''Syadvada'' or ''Saptabhangi Naya'' is the fundamental philosophical doctrine of which religion?', '**✅ Correct Logic:** Syadvada (Theory of Relativity of Truth) is a Jain doctrine. Truth has infinite aspects. "Maybe it is, Maybe it is not".

**💡 Exam Fact:** It is the logical form of ''Anekantavada''. Story of Elephant and Blind men explains it.

**🧠 Memory Tip:** Syad = Shaayad (Maybe). Jainism respects all views.

**🚫 Scam Alert:** Different from Buddhist ''Shunyavada''. Syadvada = Jain.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dfbd976c-a51f-4334-8edc-dbf75fe8a05f', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', '''लोकरंग महोत्सव'' का आयोजन प्रतिवर्ष भोपाल में किस अवसर पर किया जाता है?', '[{"id":"A","text":"मकर संक्रांति","text_en":"मकर संक्रांति"},{"id":"B","text":"गणतंत्र दिवस (26 जनवरी)","text_en":"गणतंत्र दिवस (26 जनवरी)"},{"id":"C","text":"मध्य प्रदेश स्थापना दिवस (1 नवंबर)","text_en":"मध्य प्रदेश स्थापना दिवस (1 नवंबर)"},{"id":"D","text":"स्वतंत्रता दिवस","text_en":"स्वतंत्रता दिवस"}]', '1', '✅ **Correct Logic**: लोकरंग महोत्सव 26 जनवरी (गणतंत्र दिवस) से शुरू होकर 5 दिनों तक चलता है। यह आदिवासी और लोक कलाओं का उत्सव है।
💡 **Exam Fact**: इसका आयोजन मध्य प्रदेश आदिवासी लोक कला अकादमी द्वारा किया जाता है।
🧠 **Memory Tip**: L-G (Lokrang-Gantantra).
🚫 **Scam Alert**: 1 नवंबर को ''मध्य पर्व'' मनाया जाता है, लोकरंग नहीं।', 2, 0, 1, NULL, 'On which occasion is the ''Lokrang Mahotsav'' organized annually in Bhopal?', '✅ **Correct Logic**: Lokrang Mahotsav starts on 26th January (Republic Day) and lasts for 5 days. It celebrates tribal and folk arts.
💡 **Exam Fact**: It is organized by the MP Tribal Folk Art Academy.
🧠 **Memory Tip**: L-R (Lokrang-Republic).
🚫 **Scam Alert**: ''Madhya Parva'' is celebrated on 1st November, not Lokrang.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9d4d1989-5ea5-4441-ba83-1f4ca672d804', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'बघेलखंड क्षेत्र में ''हरेली'' त्योहार के दौरान किस देवता की पूजा की जाती है, जो मुख्य रूप से किसानों का त्योहार है?', '[{"id":"A","text":"इंद्र देव","text_en":"इंद्र देव"},{"id":"B","text":"कुतुल देव","text_en":"कुतुल देव"},{"id":"C","text":"खेर माता और कृषि उपकरण","text_en":"खेर माता और कृषि उपकरण"},{"id":"D","text":"बूढ़ा देव","text_en":"बूढ़ा देव"}]', '2', '✅ **Correct Logic**: हरेली (सावन अमावस्या) को किसान अपनी खेती के औजारों और खेर माता की पूजा करते हैं ताकि फसल अच्छी हो।
💡 **Exam Fact**: इसे छत्तीसगढ़ और पूर्वी MP में बड़े उत्साह से मनाया जाता है।
🧠 **Memory Tip**: Hareli = Hariyali (Greenery/Farming).
🚫 **Scam Alert**: कुतुल देव मांडू उत्सव से संबंधित हो सकते हैं, पर हरेली विशुद्ध कृषि पर्व है।', 2, 0, 2, NULL, 'Which deity is worshipped during the ''Hareli'' festival in the Baghelkhand region, primarily a farmers'' festival?', '✅ **Correct Logic**: During Hareli (Sawan Amavasya), farmers worship their agricultural tools and Kher Mata for a good harvest.
💡 **Exam Fact**: It is celebrated with great zeal in Chhattisgarh and Eastern MP.
🧠 **Memory Tip**: Hareli = Hariyali (Greenery/Farming).
🚫 **Scam Alert**: Kutul Dev is not associated with this agrarian festival.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('080d6d77-4872-412c-9a8f-eb2dd2fdc2de', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'मालवा क्षेत्र में कुंवारी कन्याओं द्वारा मनाया जाने वाला ''संजा'' (Sanjha) उत्सव किस समय मनाया जाता है?', '[{"id":"A","text":"दीपावली के दौरान","text_en":"दीपावली के दौरान"},{"id":"B","text":"पितृपक्ष (Shradh Paksha) के दौरान","text_en":"पितृपक्ष (Shradh Paksha) के दौरान"},{"id":"C","text":"होली के बाद","text_en":"होली के बाद"},{"id":"D","text":"चैत्र नवरात्रि में","text_en":"चैत्र नवरात्रि में"}]', '1', '✅ **Correct Logic**: संजा उत्सव पितृपक्ष के 16 दिनों के दौरान मनाया जाता है, जिसमें कन्याएँ दीवारों पर गोबर से आकृतियाँ बनाती हैं।
💡 **Exam Fact**: इसे बुंदेलखंड में ''मामुलिया'' के नाम से जाना जाता है।
🧠 **Memory Tip**: S-S (Sanjha - Shradh).
🚫 **Scam Alert**: नवरात्रि में ''सुआरता'' मनाया जाता है, संजा नहीं।', 2, 0, 3, NULL, 'At what time is the ''Sanjha'' festival celebrated by unmarried girls in the Malwa region?', '✅ **Correct Logic**: Sanjha is celebrated during the 16 days of Pitru-Paksha (Shradh), where girls make motifs on walls using cow dung.
💡 **Exam Fact**: In Bundelkhand, it is known as ''Mamuliya''.
🧠 **Memory Tip**: S-S (Sanjha - Shradh).
🚫 **Scam Alert**: ''Suarta'' is celebrated during Navratri, not Sanjha.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('41f2d258-4565-4b8c-aadd-a35e8580a234', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'खजुराहो नृत्य समारोह की शुरुआत किस वर्ष हुई थी और यह किस माह में आयोजित किया जाता है?', '[{"id":"A","text":"1976; फरवरी","text_en":"1976; फरवरी"},{"id":"B","text":"1986; मार्च","text_en":"1986; मार्च"},{"id":"C","text":"1976; दिसंबर","text_en":"1976; दिसंबर"},{"id":"D","text":"1990; जनवरी","text_en":"1990; जनवरी"}]', '0', '✅ **Correct Logic**: यह 1976 में शुरू हुआ था और आमतौर पर फरवरी माह के अंत में आयोजित होता है।
💡 **Exam Fact**: यह भारत का सबसे बड़ा शास्त्रीय नृत्य समारोह है।
🧠 **Memory Tip**: Khajuraho-76 (Double digit 7-6).
🚫 **Scam Alert**: 1986 में खजुराहो को यूनेस्को में शामिल किया गया था, समारोह 10 साल पहले शुरू हो चुका था।', 2, 0, 4, NULL, 'In which year did the Khajuraho Dance Festival start and in which month is it organized?', '✅ **Correct Logic**: It started in 1976 and is typically held at the end of February.
💡 **Exam Fact**: It is India''s largest classical dance festival.
🧠 **Memory Tip**: Khajuraho-76 (Double digit 7-6).
🚫 **Scam Alert**: In 1986, Khajuraho was added to UNESCO, but the festival started 10 years earlier.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f9d167b5-fbc1-40d3-9be6-f379e152f008', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'महोत्सव और उनके आयोजन स्थल को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: तानसेन ग्वालियर, कालिदास उज्जैन, निमाड़ उत्सव मुख्य रूप से महेश्वर (खरगोन) और ध्रुपद भोपाल में आयोजित होता है।
💡 **Exam Fact**: निमाड़ उत्सव महेश्वर के अलावा खंडवा और बड़वानी में भी मनाया जाता है।
🧠 **Memory Tip**: Kalidas-Ujjain (Ancient connection).
🚫 **Scam Alert**: अलाउद्दीन खान संगीत समारोह मैहर (सतना) में होता है, भोपाल में नहीं।', 2, 0, 5, NULL, 'Match the festivals and their venues:', '✅ **Correct Logic**: Tansen in Gwalior, Kalidas in Ujjain, Nimar Utsav primarily in Maheshwar, and Dhrupad in Bhopal.
💡 **Exam Fact**: Nimar Utsav is also celebrated in Khandwa and Barwani.
🧠 **Memory Tip**: Kalidas-Ujjain (Ancient connection).
🚫 **Scam Alert**: Alauddin Khan Sangeet Samaroh happens in Maihar, not Bhopal.', 60, 'matching', '[{"id":"(1)","label":"तानसेन समारोह","match":"ग्वालियर","matchId":"(a)"},{"id":"(2)","label":"कालिदास समारोह","match":"उज्जैन","matchId":"(b)"},{"id":"(3)","label":"निमाड़ उत्सव","match":"महेश्वर","matchId":"(c)"},{"id":"(4)","label":"ध्रुपद समारोह","match":"भोपाल","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('34753b32-cb7a-47b8-9275-89c84d6fdc87', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'गोंड जनजाति द्वारा मनाया जाने वाला ''लारू काज'' (Laru Kaj) उत्सव किसके सम्मान में मनाया जाता है?', '[{"id":"A","text":"नारायण देव (Narayan Dev)","text_en":"नारायण देव (Narayan Dev)"},{"id":"B","text":"बूढ़ा देव","text_en":"बूढ़ा देव"},{"id":"C","text":"नाग देव","text_en":"नाग देव"},{"id":"D","text":"खेर माता","text_en":"खेर माता"}]', '0', '✅ **Correct Logic**: लारू काज सूअर के विवाह का प्रतीक है और यह ''नारायण देव'' के सम्मान में मनाया जाता है।
💡 **Exam Fact**: यह उत्सव परिवार की सुख-समृद्धि के लिए होता है।
🧠 **Memory Tip**: L-N (Laru-Narayan).
🚫 **Scam Alert**: नारायण देव को सूअर की बलि दी जाती है, इसे क्रूर नहीं बल्कि धार्मिक माना जाता है।', 2, 0, 6, NULL, 'In whose honor is the ''Laru Kaj'' festival, celebrated by the Gond tribe, held?', '✅ **Correct Logic**: Laru Kaj symbolizes the marriage of a pig and is celebrated in honor of ''Narayan Dev''.
💡 **Exam Fact**: It is held for the prosperity and happiness of the family.
🧠 **Memory Tip**: L-N (Laru-Narayan).
🚫 **Scam Alert**: Narayan Dev is offered a pig sacrifice; it''s a deep-rooted religious belief.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('aa0318e1-1b31-4b59-997d-6a30c4261f8e', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'बुंदेलखंड में प्रचलित ''नौरता'' (Navrata) त्योहार के बारे में क्या सही है?', '[{"id":"A","text":"यह विवाहित महिलाओं का पर्व है।","text_en":"यह विवाहित महिलाओं का पर्व है।"},{"id":"B","text":"इसमें मिट्टी के बने ''सुआर'' की पूजा होती है।","text_en":"इसमें मिट्टी के बने ''सुआर'' की पूजा होती है।"},{"id":"C","text":"यह अविवाहित कन्याओं द्वारा मनाया जाता है।","text_en":"यह अविवाहित कन्याओं द्वारा मनाया जाता है।"},{"id":"D","text":"B और C दोनों।","text_en":"B और C दोनों।"}]', '3', '✅ **Correct Logic**: नौरता अविवाहित कन्याओं द्वारा मनाया जाता है और इसमें सुआरता (राक्षस) की मिट्टी की मूर्ति बनाकर पूजा की जाती है।
💡 **Exam Fact**: यह अश्विन माह की नवरात्रि में मनाया जाता है।
🧠 **Memory Tip**: N-N (Navrata-Navratri).
🚫 **Scam Alert**: नौरता को संजा का बुंदेलखंडी रूप माना जाता है, लेकिन इसकी विधि अलग है।', 2, 0, 7, NULL, 'What is correct about the ''Navrata'' festival prevalent in Bundelkhand?', '✅ **Correct Logic**: Navrata is celebrated by unmarried girls and involves worshipping clay idols of Suar (mythical figure).
💡 **Exam Fact**: It is celebrated during the Ashwin month''s Navratri.
🧠 **Memory Tip**: N-N (Navrata-Navratri).
🚫 **Scam Alert**: Navrata is considered the Bundelkhandi version of Sanjha, but the ritual is different.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9f0e395c-d9e0-4dd7-8a34-79e03fe5036b', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'भील जनजाति का ''भगोरिया'' उत्सव होली के कितने दिन पहले शुरू होता है?', '[{"id":"A","text":"3 दिन","text_en":"3 दिन"},{"id":"B","text":"7 दिन","text_en":"7 दिन"},{"id":"C","text":"10 दिन","text_en":"10 दिन"},{"id":"D","text":"15 दिन","text_en":"15 दिन"}]', '1', '✅ **Correct Logic**: भगोरिया उत्सव होली से 7 दिन पहले शुरू होता है और होली के दिन तक चलता है।
💡 **Exam Fact**: यह तीन चरणों में होता है: गुलालिया, गोल-गधेड़ो और उजाड़िया।
🧠 **Memory Tip**: Bhagoria Week (7 days).
🚫 **Scam Alert**: उजाड़िया अंतिम दो दिनों को कहा जाता है जब बाजार (हाट) खत्म होने लगता है।', 2, 0, 8, NULL, 'How many days before Holi does the ''Bhagoria'' festival of the Bheel tribe begin?', '✅ **Correct Logic**: Bhagoria starts 7 days before Holi and lasts until the day of Holi.
💡 **Exam Fact**: It has three stages: Gulaliya, Gol-Ghadhedo, and Ujadiya.
🧠 **Memory Tip**: Bhagoria Week (7 days).
🚫 **Scam Alert**: Ujadiya refers specifically to the last two days when the market starts winding down.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('71446862-1332-46f0-9682-5ef15b3a2513', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'मध्य प्रदेश के किस जिले में ''आलमी तबलीगी इज्तिमा'' का आयोजन किया जाता है, जो दुनिया के सबसे बड़े मुस्लिम समागमों में से एक है?', '[{"id":"A","text":"इंदौर","text_en":"इंदौर"},{"id":"B","text":"उज्जैन","text_en":"उज्जैन"},{"id":"C","text":"भोपाल","text_en":"भोपाल"},{"id":"D","text":"ग्वालियर","text_en":"ग्वालियर"}]', '2', '✅ **Correct Logic**: आलमी तबलीगी इज्तिमा प्रतिवर्ष भोपाल में आयोजित होता है।
💡 **Exam Fact**: इसकी शुरुआत 1949 में हुई थी।
🧠 **Memory Tip**: B-I (Bhopal-Ijtima).
🚫 **Scam Alert**: पहले यह ताज-उल-मसाजिद में होता था, अब यह शहर के बाहर ईंटखेड़ी में आयोजित होता है।', 2, 0, 9, NULL, 'In which district of MP is the ''Alami Tablighi Ijtima'' organized, one of the world''s largest Muslim congregations?', '✅ **Correct Logic**: Alami Tablighi Ijtima is held annually in Bhopal.
💡 **Exam Fact**: It started in 1949.
🧠 **Memory Tip**: B-I (Bhopal-Ijtima).
🚫 **Scam Alert**: It used to be held at Taj-ul-Masajid, but now it''s held at Intkheri outside the city.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7b38b36e-4d65-4dfa-aecb-9871ae5c8471', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'मालवा का ''नोन-दौरा'' (Noh-Dora) पर्व किससे संबंधित है?', '[{"id":"A","text":"दीवारों पर चित्रकारी","text_en":"दीवारों पर चित्रकारी"},{"id":"B","text":"फसल की कटाई","text_en":"फसल की कटाई"},{"id":"C","text":"वर्षा के देवता","text_en":"वर्षा के देवता"},{"id":"D","text":"विवाह संस्कार","text_en":"विवाह संस्कार"}]', '0', '✅ **Correct Logic**: नोन-दौरा दीवारों पर की जाने वाली एक अलंकरण कला या पर्व है जो अक्सर दीपावली के समय मालवा और गोंड क्षेत्रों में देखा जाता है।
💡 **Exam Fact**: इसे ''नोहडोरा'' भी कहा जाता है।
🧠 **Memory Tip**: Nora-Draw (Drawing on walls).
🚫 **Scam Alert**: यह कोई नृत्य शैली नहीं है, बल्कि एक अलंकरण परंपरा है।', 2, 0, 10, NULL, 'The ''Noh-Dora'' festival of Malwa is related to which of the following?', '✅ **Correct Logic**: Noh-Dora is a wall decoration ritual or festival often seen during Diwali in Malwa and Gond regions.
💡 **Exam Fact**: It is also spelled as ''Nohdora''.
🧠 **Memory Tip**: Nora-Draw (Drawing on walls).
🚫 **Scam Alert**: It is not a dance form but a decoration tradition.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8eKwhIJX_q-NawR6YNVkF', '-chUrwczP5DdYXa_jZP2M', 'संचार में ''पैराफ्रेजिंग'' (Paraphrasing) का क्या महत्व है?', '"[\"संदेश को दोहराना / Repeating the message exactly\",\"अपने शब्दों में संदेश के अर्थ को फिर से बताना / Restating the message meaning in own words\",\"संदेश की आलोचना करना / Criticizing the message\",\"विषय बदलना / Changing the topic\"]"', '1.0', 'पैराफ्रेजिंग यह पुष्टि करता है कि श्रोता ने संदेश को सही ढंग से समझा है।', 2, 0, 1, 'Communication', 'What is the importance of ''Paraphrasing'' in communication?', 'Paraphrasing confirms the listener has understood the meaning correctly.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('GuBQuVxKv3FATtAJRcnDu', '-chUrwczP5DdYXa_jZP2M', 'संचार के अवरोधों (Barriers) को उनके उदाहरणों से सुमेलित करें:', '"[\"(1)-(b), (2)-(a), (3)-(d), (4)-(c)\",\"(1)-(a), (2)-(b), (3)-(c), (4)-(d)\",\"(1)-(d), (2)-(c), (3)-(b), (4)-(a)\",\"(1)-(c), (2)-(d), (3)-(a), (4)-(b)\"]"', '0.0', 'Semantic=Language; Physical=Environment; Psychological=Mindset; Organizational=Structure.', 2, 0, 2, 'Communication', 'Match Communication Barriers with their examples:', 'Semantic=Language; Physical=Environment; Psychological=Mindset; Organizational=Structure.', 60, 'matching', '[{"id":"(1)","label":"Semantic Barrier","match":"Poor lighting","matchId":"(a)"},{"id":"(2)","label":"Physical Barrier","match":"Different languages/Jargon","matchId":"(b)"},{"id":"(3)","label":"Psychological Barrier","match":"Complex hierarchy","matchId":"(c)"},{"id":"(4)","label":"Organizational Barrier","match":"Premature evaluation","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2nnSaYF2OrbGdymI9_Dnn', '-chUrwczP5DdYXa_jZP2M', 'एक प्रभावी संचारक के लिए ''सहानुभूति'' (Empathy) और ''समानुभूति'' (Sympathy) में क्या अंतर है?', '"[\"दोनों समान हैं / Both are same\",\"सहानुभूति में हम दूसरे की भावनाओं को महसूस करते हैं, समानुभूति में केवल दया दिखाते हैं / In Empathy we feel others'' emotions, in Sympathy we only show pity\",\"समानुभूति बेहतर है / Sympathy is better\",\"सहानुभूति में हम निर्णय लेते हैं / In Empathy we judge\"]"', '1.0', 'सहानुभूति (Empathy) गहरा जुड़ाव है, जबकि समानुभूति (Sympathy) बाहरी दया भाव है।', 2, 0, 3, 'Communication', 'What is the difference between ''Empathy'' and ''Sympathy'' for an effective communicator?', 'Empathy is feeling WITH someone; Sympathy is feeling FOR someone.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Gq68deHLRC0l2wBLfJsBt', '-chUrwczP5DdYXa_jZP2M', 'यदि किसी कूट भाषा में ''DELHI'' को ''CCIDD'' लिखा जाता है, तो ''BOMBAY'' को क्या लिखा जाएगा?', '"[\"AMJXVS\",\"AMKXYT\",\"AJMTVT\",\"WXYZAX\"]"', '0.0', 'पैटर्न: -1, -2, -3, -4, -5. D-1=C, E-2=C, L-3=I, H-4=D, I-5=D. BOMBAY: B-1=A, O-2=M, M-3=J, B-4=X, A-5=V, Y-6=S.', 2, 0, 4, 'Reasoning', 'If ''DELHI'' is coded as ''CCIDD'', how is ''BOMBAY'' coded?', 'Decreasing series subtraction pattern.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('wktbWzzJVE4dUqv4mZ2fl', '-chUrwczP5DdYXa_jZP2M', 'एक घड़ी में 4:30 बज रहे हैं। यदि मिनट की सुई पूर्व की ओर है, तो घंटे की सुई किस दिशा में होगी?', '"[\"North-East\",\"South-East\",\"North-West\",\"South-West\"]"', '0.0', '4:30 पर मिनट सुई (6 पर) नीचे होती है (South)। लेकिन प्रश्न में इसे East कहा गया है (90° एंटी-क्लॉकवाइज रोटेशन)। घंटे की सुई 4 और 5 के बीच (South-East) होती है। इसे भी 90° एंटी-क्लॉकवाइज घुमाएं -> North-East।', 2, 0, 5, 'Reasoning', 'It is 4:30 in a clock. If the minute hand points East, in which direction is the hour hand?', 'Real position: Minute(S), Hour(SE). Shift S to E (+90 deg anti-clock). Shift SE +90 deg anti-clock = NE.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('-pulcMZGMJrNMiOTbxq1u', '-chUrwczP5DdYXa_jZP2M', 'अगला पद ज्ञात करें: 2, 10, 30, 68, ?', '"[\"125\",\"130\",\"128\",\"135\"]"', '1.0', 'पैटर्न: n³ + n. 1³+1=2, 2³+2=10, 3³+3=30, 4³+4=68. अगला: 5³+5 = 125+5 = 130.', 2, 0, 6, 'Reasoning', 'Find the next term: 2, 10, 30, 68, ?', 'Pattern is n cubed plus n.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4eRIOrGgCCrgZPCIFmTuP', '-chUrwczP5DdYXa_jZP2M', 'कथन: कोई भी मोबाइल घड़ी नहीं है। सभी घड़ियां कैलकुलेटर हैं। निष्कर्ष: (I) कोई कैलकुलेटर मोबाइल नहीं है। (II) कुछ कैलकुलेटर घड़ियां हैं।', '"[\"केवल I\",\"केवल II\",\"दोनों\",\"कोई नहीं\"]"', '1.0', 'निष्कर्ष II सही है क्योंकि सभी घड़ियां कैलकुलेटर हैं। निष्कर्ष I गलत है क्योंकि मोबाइल, कैलकुलेटर के उस हिस्से को छू सकता है जो घड़ी नहीं है।', 2, 0, 7, 'Reasoning', 'Statements: No mobile is a watch. All watches are calculators. Conclusions: (I) No calculator is a mobile. (II) Some calculators are watches.', 'Only II follows. Mobile can overlap with Calculator outside the Watch circle.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('NJ14IN6GzcdZO9E1E8hE-', '-chUrwczP5DdYXa_jZP2M', 'यदि ''A'' की आय ''B'' से 25% अधिक है, तो ''B'' की आय ''A'' से कितने प्रतिशत कम है?', '"[\"25%\",\"20%\",\"15%\",\"33.33%\"]"', '1.0', 'सूत्र: [R / (100+R)] * 100. [25/125]*100 = 1/5 * 100 = 20%.', 2, 0, 8, 'Quantitative Aptitude', 'If A''s income is 25% more than B, by what percent is B''s income less than A?', 'Formula application for percentage comparison.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Gg3s6mKSavROvE2FhiIFG', '-chUrwczP5DdYXa_jZP2M', 'एक नाव शांत जल में 10 किमी/घंटा की गति से चलती है। यदि धारा की गति 2 किमी/घंटा है, तो धारा के प्रतिकूल 24 किमी जाने में कितना समय लगेगा?', '"[\"2 hours\",\"3 hours\",\"4 hours\",\"2.5 hours\"]"', '1.0', 'प्रतिकूल गति = 10 - 2 = 8 किमी/घंटा। समय = दूरी / गति = 24 / 8 = 3 घंटे।', 2, 0, 9, 'Quantitative Aptitude', 'Boat speed in still water is 10 km/hr. Stream speed is 2 km/hr. Time taken to go 24 km upstream?', 'Upstream speed = 8 km/hr. Time = 24/8 = 3 hrs.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('WLhfZGnfJJ10V05CjrqJ1', '-chUrwczP5DdYXa_jZP2M', 'शब्द ''EDUCATION'' के अक्षरों से कितने 4 अक्षरों वाले शब्द बनाए जा सकते हैं (बिना दोहराव के)?', '"[\"3024\",\"1512\",\"5040\",\"9!\"]"', '0.0', 'कुल 9 अक्षर हैं। क्रमचय (Permutation) ⁹P₄ = 9 × 8 × 7 × 6 = 3024.', 2, 0, 10, 'Quantitative Aptitude', 'How many 4-letter words can be formed from ''EDUCATION'' (no repetition)?', 'Permutation 9P4 calculation.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1FiXKaXANhEZE2erGX3an', '-chUrwczP5DdYXa_jZP2M', 'यदि ''15 अगस्त 2003'' को शुक्रवार था, तो ''15 अगस्त 2004'' को कौन सा दिन था?', '"[\"Saturday\",\"Sunday\",\"Monday\",\"Tuesday\"]"', '1.0', '2004 एक लीप वर्ष है और फरवरी शामिल है। इसलिए +2 दिन। शुक्रवार + 2 = रविवार।', 2, 0, 11, 'Reasoning', 'If 15 Aug 2003 was Friday, what day was 15 Aug 2004?', 'Leap year involves Feb 29, so add 2 odd days. Friday + 2 = Sunday.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0hL6FZ29RcaVU2e_b_tgI', '-chUrwczP5DdYXa_jZP2M', 'A और B किसी काम को 15 दिनों में करते हैं। B और C उसी काम को 20 दिनों में, और C और A 30 दिनों में करते हैं। A अकेले उसे कितने दिनों में करेगा?', '"[\"40\",\"60\",\"80\",\"120\"]"', '0.0', 'Work equation solve. (3M+4W)*7 = (2M+3W)*10. 21M+28W = 20M+30W => 1M = 2W. Total Work (convert to W) = (6W+4W)*7 = 70W units. 1M+1W = 2W+1W = 3W. Time = 70/3 = 23.33 days? Let''s check calculation. 21M+28W = 20M+30W -> M=2W. Correct. Eq 1: (3*2+4)*7 = 10*7 = 70. Eq 2: (2*2+3)*10 = 7*10 = 70. Correct. Required: 1M+1W = 3W. Time = 70/3 days. Option not matching. Let''s re-read standard problem types or check option closest. Maybe logic error in options. Let''s provide a simpler Work question to avoid ambiguity in FLT generation.', 2, 0, 12, 'Quantitative Aptitude', 'A+B do work in 15 days, B+C in 20 days, C+A in 30 days. How many days for A alone?', '2(A+B+C) = 1/15 + 1/20 + 1/30 = (4+3+2)/60 = 9/60 = 3/20. A+B+C = 3/40. A = (A+B+C) - (B+C) = 3/40 - 1/20 = 1/40. So 40 days.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('zw3gLTS7xGqXSVk07vfoI', '-chUrwczP5DdYXa_jZP2M', 'रीजनिंग: बेमेल चुनें (Odd One Out):', '"[\"Iron\",\"Mercury\",\"Copper\",\"Aluminum\"]"', '1.0', 'पारा (Mercury) कमरे के तापमान पर तरल है, अन्य सभी ठोस धातुएं हैं।', 2, 0, 13, 'Reasoning', 'Reasoning: Choose the Odd One Out:', 'Mercury is liquid at room temp.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('upXT1h3rL8V2BZMsHjdnh', '-chUrwczP5DdYXa_jZP2M', 'एक समचतुर्भुज (Rhombus) के विकर्ण 16 सेमी और 30 सेमी हैं। उसका परिमाप ज्ञात करें।', '"[\"68 cm\",\"60 cm\",\"64 cm\",\"70 cm\"]"', '0.0', 'विकर्ण एक-दूसरे को 90° पर समद्विभाजित करते हैं। भुजा = √(8² + 15²) = √(64+225) = √289 = 17। परिमाप = 4 * 17 = 68।', 2, 0, 14, 'Quantitative Aptitude', 'Diagonals of a Rhombus are 16 cm and 30 cm. Find its perimeter.', 'Side = hypotenuse of half-diagonals (8, 15). Side=17. Perimeter=68.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('uQ604byJKsL4VUuKjb6iv', '-chUrwczP5DdYXa_jZP2M', 'वेन आरेख: ''डॉक्टर, पुरुष, अभिनेता'' का सही प्रतिनिधित्व कौन करता है?', '"[\"तीनों अलग-अलग / Three separate\",\"एक के अंदर एक / Concentric\",\"तीनों एक-दूसरे को काटते हुए / All three intersecting\",\"दो अलग, एक काटता हुआ / Two separate, one intersecting\"]"', '2.0', 'एक पुरुष डॉक्टर हो सकता है, अभिनेता भी। एक डॉक्टर अभिनेता भी हो सकता है। तीनों में ओवरलैप संभव है।', 2, 0, 15, 'Reasoning', 'Venn Diagram: Which represents ''Doctor, Male, Actor''?', 'Intersection implies some males are doctors and actors, etc.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('x-rzVWhv-bNvrFqHErs1e', '-chUrwczP5DdYXa_jZP2M', 'नैतिक निर्णय: आपके कार्यालय में एक वरिष्ठ सहकर्मी महिला कर्मचारियों के प्रति अनुचित टिप्पणी करता है। कोई शिकायत नहीं करता क्योंकि वह प्रभावशाली है। आप क्या करेंगे?', '"[\"इसे नजरअंदाज करेंगे / Ignore it\",\"महिला कर्मचारियों को चुप रहने की सलाह देंगे / Advise women to stay quiet\",\"गुमनाम रूप से उच्च प्रबंधन/HR को सूचित करेंगे / Inform HR/Management anonymously\",\"स्वयं उससे लड़ेंगे / Fight with him personally\"]"', '2.0', 'उचित चैनल (HR) के माध्यम से रिपोर्ट करना सबसे सही और पेशेवर कदम है।', 2, 0, 16, 'Decision Making', 'Ethical Decision: A senior colleague makes inappropriate comments to female staff. No one complains as he is influential. What will you do?', 'Reporting to authority via proper channel is the correct ethical step.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fS-a1PJvZReQZT0NTVYoW', '-chUrwczP5DdYXa_jZP2M', 'दो संख्याओं का अनुपात 3:4 है। यदि प्रत्येक में 6 जोड़ा जाए, तो अनुपात 4:5 हो जाता है। संख्याओं का अंतर क्या है?', '"[\"6\",\"12\",\"18\",\"24\"]"', '0.0', 'अनुपात अंतर (4-3=1, 5-4=1) समान है। 1 इकाई = 6। संख्याओं का अंतर (4-3) = 1 इकाई = 6।', 2, 0, 17, 'Quantitative Aptitude', 'Two numbers are in ratio 3:4. If 6 is added to each, ratio becomes 4:5. Difference of numbers?', 'Ratio gap is 1 unit = 6. Difference is 1 unit. Ans = 6.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ycPw9W1qsUzVp6YzaSiqO', '-chUrwczP5DdYXa_jZP2M', 'एक दुकानदार 1 किलो चाय के साथ 50 ग्राम धूल मिलाता है। यदि वह मिश्रण को चाय के क्रय मूल्य पर बेचता है, तो उसका लाभ % क्या है?', '"[\"5%\",\"4.76%\",\"5.26%\",\"10%\"]"', '0.0', 'लाभ = मिलावट/शुद्ध मात्रा * 100? नहीं। कुल मिश्रण = 1050 ग्राम। लागत 1000 ग्राम की लगी। बेचा 1050 ग्राम के भाव पर। लाभ 50 ग्राम का। % = (50/1000)*100 = 5%।', 2, 0, 18, 'Quantitative Aptitude', 'A shopkeeper mixes 50g dust with 1kg tea. Sells mixture at Cost Price of tea. Profit %?', 'Investment for 1000g, Revenue for 1050g. Profit is on 1000g base. 50/1000 = 5%.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('mUNyXV2ipTJ73ykljAY39', '-chUrwczP5DdYXa_jZP2M', '50 छात्रों की एक कक्षा का औसत वजन 45 किलो है। यदि शिक्षक का वजन शामिल किया जाए, तो औसत 500 ग्राम बढ़ जाता है। शिक्षक का वजन क्या है?', '"[\"70.5 kg\",\"75 kg\",\"72 kg\",\"60 kg\"]"', '0.0', 'नया औसत = 45.5। कुल लोग = 51। कुल वृद्धि = 51 * 0.5 = 25.5 किलो। शिक्षक = 45 + 25.5 = 70.5।', 2, 0, 19, 'Quantitative Aptitude', 'Average weight of 50 students is 45kg. If teacher included, avg increases by 500g. Teacher''s weight?', 'Teacher brings own 45kg + distributes 0.5kg to 51 people. 45 + 25.5 = 70.5.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('QbWvR1Vt1mPIg97mbXr0I', '-chUrwczP5DdYXa_jZP2M', 'यदि ''P'' का अर्थ ''÷'', ''Q'' का अर्थ ''×'', ''R'' का अर्थ ''+'', ''S'' का अर्थ ''-'' है, तो: 18 Q 12 P 4 R 5 S 6 = ?', '"[\"53\",\"59\",\"65\",\"40\"]"', '0.0', '18 × 12 ÷ 4 + 5 - 6. BODMAS: 18 × 3 + 5 - 6 = 54 + 5 - 6 = 53.', 2, 0, 20, 'Reasoning', 'If P=÷, Q=×, R=+, S=-, then 18 Q 12 P 4 R 5 S 6 = ?', '18*3 + 5 - 6 = 53.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a67hrwbDLhoUepjmTEfEn', '-chUrwczP5DdYXa_jZP2M', 'एक शंकु (Cone) और बेलन (Cylinder) की त्रिज्या और ऊंचाई समान हैं। उनके आयतनों का अनुपात क्या है?', '"[\"1:3\",\"3:1\",\"1:2\",\"2:1\"]"', '0.0', 'शंकु = (1/3)πr²h. बेलन = πr²h. अनुपात = 1/3 : 1 = 1:3.', 2, 0, 21, 'Quantitative Aptitude', 'Radius and height of a Cone and Cylinder are equal. Ratio of their volumes?', 'Cone is 1/3rd of Cylinder.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('czlYEHQdYsLAojWYkoHJh', '-chUrwczP5DdYXa_jZP2M', 'श्रृंखला: 0, 6, 24, 60, 120, 210, ?', '"[\"336\",\"290\",\"240\",\"504\"]"', '0.0', 'पैटर्न: n³ - n. 1³-1=0, 2³-2=6, 3³-3=24... 7³-7 = 343-7 = 336.', 2, 0, 22, 'Reasoning', 'Series: 0, 6, 24, 60, 120, 210, ?', 'n cubed minus n pattern.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('asRE0kJwWDL582h-BzjnG', '-chUrwczP5DdYXa_jZP2M', 'एक चुनाव में दो उम्मीदवार थे। एक को 60% वोट मिले और वह 1600 वोटों से जीता। कुल वोट कितने थे?', '"[\"8000\",\"10000\",\"6000\",\"12000\"]"', '0.0', 'विजेता 60%, हारने वाला 40%। अंतर = 20%। 20% = 1600. 100% = 1600/20 * 100 = 8000.', 2, 0, 23, 'Quantitative Aptitude', 'In an election between two candidates, one got 60% votes and won by 1600 votes. Total votes?', '20% diff = 1600. Total = 8000.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Jm_cQIZVG8Rg03RaNdltc', '-chUrwczP5DdYXa_jZP2M', 'यदि ''ROSE'' को ''TQUG'' लिखा जाता है, तो ''BLUE'' को क्या लिखा जाएगा?', '"[\"DNWG\",\"DMWG\",\"CMVF\",\"DNVH\"]"', '0.0', 'पैटर्न: +2, +2, +2, +2. B+2=D, L+2=N, U+2=W, E+2=G.', 2, 0, 24, 'Reasoning', 'If ''ROSE'' is coded as ''TQUG'', how is ''BLUE'' coded?', '+2 forward shift.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3cZ3zJjoxSxrMvn8Rv5-Y', '-chUrwczP5DdYXa_jZP2M', '₹8000 पर 5% वार्षिक दर से 2 वर्ष का चक्रवृद्धि ब्याज (CI) और साधारण ब्याज (SI) का अंतर क्या है?', '"[\"₹20\",\"₹25\",\"₹15\",\"₹30\"]"', '0.0', 'अंतर = P(R/100)². 8000 * (5/100)² = 8000 * 1/400 = 20.', 2, 0, 25, 'Quantitative Aptitude', 'Difference between CI and SI on ₹8000 at 5% p.a. for 2 years?', 'Diff = P(R/100)^2.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('jxqBt1L3AagyA-FFvRe5n', '-chUrwczP5DdYXa_jZP2M', 'एक टैंक को पाइप A 20 मिनट में और B 30 मिनट में भर सकता है। यदि दोनों खुले हों, तो टैंक कितने समय में भरेगा?', '"[\"12 min\",\"10 min\",\"15 min\",\"25 min\"]"', '0.0', '1/20 + 1/30 = 5/60 = 1/12. समय = 12 मिनट।', 2, 0, 26, 'Quantitative Aptitude', 'Pipe A fills tank in 20 min, B in 30 min. If both open, time taken?', 'Product/Sum formula: (20*30)/(20+30) = 12.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('PrP7oWQDIaYHgyV0LiJW0', '-chUrwczP5DdYXa_jZP2M', 'लुप्त अक्षर: Z, X, V, T, R, ?', '"[\"O\",\"P\",\"Q\",\"S\"]"', '1.0', '-2 पैटर्न। R(18) - 2 = P(16)।', 2, 0, 27, 'Reasoning', 'Missing letter: Z, X, V, T, R, ?', 'Backward skip 2.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('v7Cku2fV-EKmGLlj2Byv8', '-chUrwczP5DdYXa_jZP2M', '75 का 30% - 45 का 20% = ?', '"[\"13.5\",\"15\",\"12.5\",\"10\"]"', '0.0', '22.5 - 9 = 13.5.', 2, 0, 28, 'Quantitative Aptitude', '30% of 75 - 20% of 45 = ?', '22.5 - 9 = 13.5.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('SdjlNC9nGx2zsXnJoDRqI', '-chUrwczP5DdYXa_jZP2M', 'कौन सा लीप वर्ष नहीं है?', '"[\"2000\",\"1600\",\"1900\",\"2004\"]"', '2.0', 'शताब्दी वर्ष (Century years) केवल तभी लीप होते हैं जब 400 से विभाज्य हों। 1900, 400 से विभाज्य नहीं है।', 2, 0, 29, 'Reasoning', 'Which is NOT a leap year?', '1900 is not divisible by 400.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2IsbHv0BrL9oyO1dL5B4t', '-chUrwczP5DdYXa_jZP2M', 'रवि ने ₹500 में एक घड़ी खरीदी और ₹550 में बेच दी। लाभ प्रतिशत क्या है?', '"[\"10%\",\"20%\",\"5%\",\"15%\"]"', '0.0', 'लाभ = 50. % = (50/500)*100 = 10%.', 2, 0, 30, 'Quantitative Aptitude', 'Ravi bought a watch for ₹500 and sold for ₹550. Profit %?', '50/500 = 1/10 = 10%.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dQ-cGJMiHEcb8oHjpA4fa', '-chUrwczP5DdYXa_jZP2M', 'एक पासा फेंका जाता है। 4 से बड़ी संख्या आने की प्रायिकता क्या है?', '"[\"1/3\",\"1/2\",\"1/6\",\"2/3\"]"', '0.0', 'अनुकूल परिणाम: 5, 6 (2 संख्याएं)। प्रायिकता = 2/6 = 1/3।', 2, 0, 31, 'Quantitative Aptitude', 'A dice is thrown. Probability of getting a number greater than 4?', 'Outcomes {5,6}. 2/6 = 1/3.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Myc2QhG_C2hgjeRHwVBvT', '-chUrwczP5DdYXa_jZP2M', 'यदि x + y = 14 और x - y = 4, तो xy = ?', '"[\"45\",\"40\",\"48\",\"35\"]"', '0.0', 'x=9, y=5. xy = 45.', 2, 0, 32, 'Quantitative Aptitude', 'If x + y = 14 and x - y = 4, then xy = ?', 'Solve equations: x=9, y=5.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dCmDXg9WXJr01WIolR3R0', '-chUrwczP5DdYXa_jZP2M', 'डेटा व्याख्या: एक कक्षा में 30% छात्र अंग्रेजी में, 40% हिंदी में, और 20% दोनों में फेल हुए। केवल एक विषय में फेल होने वालों का प्रतिशत?', '"[\"30%\",\"50%\",\"40%\",\"20%\"]"', '0.0', 'केवल Eng = 30-20=10. केवल Hindi = 40-20=20. कुल केवल एक = 10+20=30%.', 2, 0, 33, 'Reasoning', 'DI: In a class, 30% failed in English, 40% in Hindi, 20% in both. Percentage failed in exactly one subject?', 'Only Eng (10) + Only Hin (20) = 30%.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('BechihlDV04FjRUI4_rFX', '-chUrwczP5DdYXa_jZP2M', 'A, B की बहन है। C, B की माँ है। D, C का पिता है। A का D से क्या संबंध है?', '"[\"पोती / Granddaughter\",\"बेटी / Daughter\",\"माँ / Mother\",\"दादी / Grandmother\"]"', '0.0', 'A, C की बेटी है। C, D की बेटी है। A, D की नातिन (Granddaughter) है।', 2, 0, 34, 'Reasoning', 'A is B''s sister. C is B''s mother. D is C''s father. How is A related to D?', 'A is daughter of C, C is daughter of D. So Granddaughter.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('VHI1Q-tvvj-UHYLh1ueNj', '-chUrwczP5DdYXa_jZP2M', '100 और 200 के बीच कितनी संख्याएं 9 से पूर्णतः विभाज्य हैं?', '"[\"11\",\"10\",\"12\",\"13\"]"', '0.0', 'पहली: 108, आखिरी: 198। n = [(198-108)/9] + 1 = 10 + 1 = 11।', 2, 0, 35, 'Quantitative Aptitude', 'How many numbers between 100 and 200 are divisible by 9?', 'AP series formula. 11 numbers.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('XnDi6G22Vemr6xzQfrYTk', '-chUrwczP5DdYXa_jZP2M', 'दिए गए शब्दों को शब्दकोश क्रम में व्यवस्थित करें: 1. Science, 2. Scenery, 3. Script, 4. School', '"[\"2, 4, 1, 3\",\"2, 1, 4, 3\",\"4, 2, 1, 3\",\"2, 4, 3, 1\"]"', '0.0', 'Scenery (Sce), School (Sch), Science (Sci), Script (Scr).', 2, 0, 36, 'Reasoning', 'Arrange in dictionary order: 1. Science, 2. Scenery, 3. Script, 4. School', 'Alphabetical sorting.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bp_M-1eC74-vvm97RHIG4', '-chUrwczP5DdYXa_jZP2M', 'एक कमरे में 10 लोग हैं। यदि हर कोई एक-दूसरे से एक बार हाथ मिलाता है, तो कुल कितने हैंडशेक होंगे?', '"[\"45\",\"90\",\"50\",\"100\"]"', '0.0', 'सूत्र: n(n-1)/2. 10*9/2 = 45.', 2, 0, 37, 'Quantitative Aptitude', '10 people in a room. If everyone shakes hands once with everyone else, total handshakes?', 'Combination 10C2 = 45.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('yHaqLsYb-mt3_GgESpy0h', '-chUrwczP5DdYXa_jZP2M', 'यदि ''MAN'' = 28, ''CAT'' = 24, तो ''DOG'' = ?', '"[\"26\",\"25\",\"27\",\"28\"]"', '0.0', 'M(13)+A(1)+N(14) = 28. D(4)+O(15)+G(7) = 26.', 2, 0, 38, 'Reasoning', 'If ''MAN'' = 28, ''CAT'' = 24, then ''DOG'' = ?', 'Sum of letter positions.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('QlUFH_15pdIspD-7yaVRZ', '-chUrwczP5DdYXa_jZP2M', '1, 2, 6, 24, 120, ?', '"[\"720\",\"600\",\"500\",\"700\"]"', '0.0', 'पैटर्न: ×2, ×3, ×4, ×5, ×6. 120 × 6 = 720.', 2, 0, 39, 'Reasoning', '1, 2, 6, 24, 120, ?', 'Factorial series or multiplication increment.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('NkCPB03IHGhc9stIObcxR', '-chUrwczP5DdYXa_jZP2M', 'एक वर्ग का विकर्ण 10 सेमी है। इसका क्षेत्रफल क्या है?', '"[\"50 cm²\",\"100 cm²\",\"25 cm²\",\"40 cm²\"]"', '0.0', 'क्षेत्रफल = (विकर्ण)² / 2 = 100/2 = 50.', 2, 0, 40, 'Quantitative Aptitude', 'Diagonal of a square is 10 cm. Its Area?', 'Area = d^2 / 2.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('PJvYbobE0bCWZtoqfUku9', '-chUrwczP5DdYXa_jZP2M', 'यदि ''सफेद'' को ''काला'', ''काला'' को ''लाल'', ''लाल'' को ''पीला'' कहा जाए, तो मानव रक्त का रंग क्या है?', '"[\"Yellow\",\"Red\",\"Black\",\"White\"]"', '0.0', 'रक्त लाल होता है, लाल को पीला कहा गया है।', 2, 0, 41, 'Reasoning', 'If White is Black, Black is Red, Red is Yellow, what is color of human blood?', 'Blood is Red, Red is called Yellow.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5Xsvy0dxnEITd4rhWJpjp', '-chUrwczP5DdYXa_jZP2M', '16:56 :: 32:?', '"[\"96\",\"112\",\"118\",\"120\"]"', '1.0', '16 × 3.5 = 56. 32 × 3.5 = 112. (या 16:56 अनुपात 2:7 है। 32:x = 2:7 -> x=112).', 2, 0, 42, 'Reasoning', '16:56 :: 32:?', 'Ratio 2:7 logic.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xeCCjDcr0bbGTKj_D8_p3', '-chUrwczP5DdYXa_jZP2M', 'कक्षा में शिक्षक द्वारा ''आंखों का संपर्क'' (Eye Contact) बनाए रखना किस प्रकार का कौशल है?', '"[\"शाब्दिक / Verbal\",\"अशाब्दिक / Non-verbal\",\"लिखित / Written\",\"यांत्रिक / Mechanical\"]"', '1.0', 'आंखों का संपर्क बॉडी लैंग्वेज (अशाब्दिक) का हिस्सा है।', 2, 0, 43, 'Communication', 'Maintaining ''Eye Contact'' by a teacher in class is which type of skill?', 'Eye contact is non-verbal.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('FmcsozNzqkJyoE0gJmuej', '-chUrwczP5DdYXa_jZP2M', 'संचार में ''क्रोनेमिक्स'' (Chronemics) का संबंध किससे है?', '"[\"रंग / Color\",\"समय / Time\",\"स्पर्श / Touch\",\"जगह / Space\"]"', '1.0', 'क्रोनेमिक्स संचार में समय के उपयोग का अध्ययन है।', 2, 0, 44, 'Communication', 'In communication, ''Chronemics'' relates to?', 'Chronemics is the study of time in communication.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
