INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Z8u2xKoYJJ21tWzUgz2Zq', '-chUrwczP5DdYXa_jZP2M', 'एक ''सक्रिय श्रोता'' (Active Listener) की विशेषता क्या नहीं है?', '"[\"प्रश्न पूछना / Asking questions\",\"निर्णय सुनाना / Judging prematurely\",\"सिर हिलाना / Nodding\",\"ध्यान देना / Paying attention\"]"', '1.0', 'समय से पहले निर्णय लेना (Judging) सक्रिय श्रवण में बाधा है।', 2, 0, 46, 'Communication', 'What is NOT a characteristic of an ''Active Listener''?', 'Premature judgment blocks understanding.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('YRmobX3RsNExUSpdiKKMB', '-chUrwczP5DdYXa_jZP2M', 'अंतर्वैयक्तिक संचार (Intrapersonal Communication) का क्या अर्थ है?', '"[\"दो लोगों के बीच बात / Talk between two people\",\"स्वयं से बात करना / Talking to oneself\",\"समूह में बात / Group talk\",\"भाषण देना / Delivering speech\"]"', '1.0', 'Intra = भीतर। स्वयं से संचार (चिंतन/मनन)।', 2, 0, 47, 'Communication', 'What does ''Intrapersonal Communication'' mean?', 'Communication within oneself.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('KTodzzn8LJsotI56xWhz6', '-chUrwczP5DdYXa_jZP2M', 'एक आयत की लंबाई 20% बढ़ाई जाती है और चौड़ाई 20% घटाई जाती है। क्षेत्रफल में क्या परिवर्तन होगा?', '"[\"No change\",\"4% increase\",\"4% decrease\",\"1% decrease\"]"', '2.0', 'सूत्र: x - y - (xy/100). 20 - 20 - 400/100 = -4%.', 2, 0, 48, 'Quantitative Aptitude', 'Length of rectangle increased by 20%, breadth decreased by 20%. Change in Area?', 'Always x^2/100 decrease in such cases. 4% decrease.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('OngGrJk1uM8wzSvZ_CEME', '-chUrwczP5DdYXa_jZP2M', '2²⁰/2 = ?', '"[\"2¹⁹\",\"2¹⁰\",\"1²⁰\",\"2²¹\"]"', '0.0', 'घातांक नियम: a^m / a^n = a^(m-n). 20-1=19.', 2, 0, 49, 'Quantitative Aptitude', '2²⁰/2 = ?', 'Exponent subtraction rule.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('QVfD5rTbo2-i49QUt52TS', '-chUrwczP5DdYXa_jZP2M', 'यदि ''CAB'' = 6, ''BED'' = 40, तो ''HAD'' = ?', '"[\"32\",\"50\",\"13\",\"16\"]"', '0.0', 'गुणनफल: C(3)*A(1)*B(2)=6. B(2)*E(5)*D(4)=40. H(8)*A(1)*D(4)=32.', 2, 0, 50, 'Reasoning', 'If ''CAB'' = 6, ''BED'' = 40, then ''HAD'' = ?', 'Multiplication of letter positions.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5dOp4CEuUdcKVIZytBHLj', '-chUrwczP5DdYXa_jZP2M', 'कौन सा संचार का ''7 C'' नहीं है?', '"[\"Clarity\",\"Conciseness\",\"Character\",\"Correctness\"]"', '2.0', '''Character'' 7Cs सूची में नहीं है (Courtesy, Concrete, Complete, etc. हैं)।', 2, 0, 51, 'Communication', 'Which is NOT one of the ''7 Cs'' of communication?', 'Character is not a standard 7C.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('hVLBQKxZAfMDJGBIHWczM', '-chUrwczP5DdYXa_jZP2M', 'अशाब्दिक संचार (Non-verbal) में आवाज के उतार-चढ़ाव (Pitch/Tone) को क्या कहते हैं?', '"[\"Haptics\",\"Paralanguage\",\"Proxemics\",\"Kinesics\"]"', '1.0', 'पैरालैंग्वेज (Paralanguage) में स्वर, टोन और वॉल्यूम शामिल हैं।', 2, 0, 52, 'Communication', 'What is Pitch/Tone called in Non-verbal communication?', 'Paralanguage involves how we say things.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('uHSMFH-5t4BYr2h15TAOK', '-chUrwczP5DdYXa_jZP2M', 'एक संख्या के 1/3 का 1/4 यदि 15 है, तो उस संख्या का 3/10 क्या है?', '"[\"54\",\"36\",\"45\",\"72\"]"', '0.0', '(1/12)x = 15 => x = 180. 180 का 3/10 = 18 * 3 = 54.', 2, 0, 53, 'Quantitative Aptitude', 'If 1/4 of 1/3 of a number is 15, what is 3/10 of that number?', 'Number is 180. 30% is 54.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('oz20uh54V-Us6FRPeTrX4', '-chUrwczP5DdYXa_jZP2M', 'तीन घंटियाँ क्रमशः 12, 15 और 18 मिनट के अंतराल पर बजती हैं। यदि वे सुबह 9:00 बजे एक साथ बजीं, तो अगली बार कब बजेंगी?', '"[\"12:00 PM\",\"10:30 AM\",\"9:45 AM\",\"11:00 AM\"]"', '0.0', 'LCM(12, 15, 18) = 180 मिनट = 3 घंटे। 9:00 + 3 = 12:00 PM.', 2, 0, 54, 'Quantitative Aptitude', 'Three bells ring at intervals of 12, 15, 18 mins. If they rang together at 9:00 AM, when next?', 'Find LCM of intervals. 180 mins = 3 hours.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('za7SGf0NIDO5HdWUAKzCC', '-chUrwczP5DdYXa_jZP2M', 'किसी वस्तु को ₹900 में बेचने पर हुआ लाभ उसे ₹600 में बेचने पर हुई हानि का दोगुना है। क्रय मूल्य क्या है?', '"[\"₹700\",\"₹650\",\"₹750\",\"₹800\"]"', '0.0', '(900 - CP) = 2 * (CP - 600). 900 - CP = 2CP - 1200. 3CP = 2100. CP = 700.', 2, 0, 55, 'Quantitative Aptitude', 'Profit on selling at ₹900 is double the loss on selling at ₹600. Cost Price?', 'Equation setup. 3CP = 2100.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sSXJBmQ6rUOlyx6XfnNky', '-chUrwczP5DdYXa_jZP2M', '**निर्देश: गद्यांश पढ़ें:**
टिकाऊ विकास (Sustainable Development) का अर्थ है भविष्य की पीढ़ियों की जरूरतों से समझौता किए बिना वर्तमान जरूरतों को पूरा करना। इसके लिए हमें प्राकृतिक संसाधनों का विवेकपूर्ण उपयोग करना होगा। यह पर्यावरण संरक्षण और आर्थिक विकास के बीच संतुलन बनाता है।

----------------------------
**प्रश्न:** टिकाऊ विकास का मुख्य लक्ष्य क्या है?', '"[\"तेजी से अमीर बनना\",\"संसाधनों का दोहन\",\"भविष्य और वर्तमान में संतुलन\",\"उद्योग बंद करना\"]"', '2.0', NULL, 2, 0, 56, 'Reading Comprehension', '**Direction: Read passage:**
Sustainable Development means meeting present needs without compromising the needs of future generations. We must use natural resources wisely. It balances environmental protection and economic growth.

----------------------------
**Question:** What is the main goal of Sustainable Development?', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
