INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('BCPEYMv6AaMplnEEjZiAM', '-chUrwczP5DdYXa_jZP2M', 'दोहा छंद में कितनी मात्राएं होती हैं?', '"[\"24 (13-11)\",\"26\",\"28\",\"16\"]"', '0.0', 'पहले और तीसरे चरण में 13, दूसरे और चौथे में 11। कुल 24।', 2, 0, 99, 'Hindi Grammar', 'N/A', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xIDAryedZ02VxatyJnjyS', '-chUrwczP5DdYXa_jZP2M', 'संविधान के किस अनुच्छेद में हिंदी को राजभाषा कहा गया है?', '"[\"343\",\"351\",\"345\",\"370\"]"', '0.0', 'अनुच्छेद 343(1)।', 2, 0, 100, 'Hindi Grammar', 'N/A', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fbe89296-0712-438c-a8c8-5296bd781f02', '7b85d2a9-23eb-4599-adfb-06821e1186fb', 'बघेलखंड क्षेत्र में ''बंसदेवा'' (Basdeva) गायन किस जाति द्वारा किया जाता है और इसमें किसका वर्णन होता है?', '[{"id":"A","text":"हरबोला जाति; श्रवण कुमार की कथा","text_en":"हरबोला जाति; श्रवण कुमार की कथा"},{"id":"B","text":"भोंपा जाति; पाबूजी की कथा","text_en":"भोंपा जाति; पाबूजी की कथा"},{"id":"C","text":"नाथ पंथी; राजा भर्तृहरि की कथा","text_en":"नाथ पंथी; राजा भर्तृहरि की कथा"},{"id":"D","text":"कलगी तुरा; शक्ति की महिमा","text_en":"कलगी तुरा; शक्ति की महिमा"}]', '0', '✅ **Correct Logic**: बंसदेवा बघेलखंड का पारंपरिक गायन है जिसे ''हरबोला'' जाति के लोग पीत वस्त्र पहनकर गाते हैं। इसमें मुख्य रूप से श्रवण कुमार की कथा गाई जाती है।
💡 **Exam Fact**: इन्हें ''वासुदेवा'' भी कहा जाता है।
🧠 **Memory Tip**: B-H-S (Basdeva - Harbola - Shravan).
🚫 **Scam Alert**: राजा भर्तृहरि की कथा मालवा के ''भरथरी गायन'' में गाई जाती है, बंसदेवा में नहीं।', 2, 0, 1, NULL, 'By which caste is ''Basdeva'' singing performed in the Baghelkhand region and what does it describe?', '✅ **Correct Logic**: Basdeva is a traditional folk singing of Baghelkhand performed by the ''Harbola'' caste wearing yellow clothes. It primarily narrates the story of Shravan Kumar.
💡 **Exam Fact**: They are also known as ''Vasudevas''.
🧠 **Memory Tip**: B-H-S (Basdeva - Harbola - Shravan).
🚫 **Scam Alert**: The story of King Bhartrihari is sung in ''Bhartari'' of Malwa, not Basdeva.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('60d7263e-e99e-411f-b192-12f5cbb3c19b', '7b85d2a9-23eb-4599-adfb-06821e1186fb', 'मालवा के ''भरथरी गायन'' (Bhartari) में किस वाद्य यंत्र का मुख्य रूप से प्रयोग किया जाता है?', '[{"id":"A","text":"चिंकारा और सारंगी","text_en":"चिंकारा और सारंगी"},{"id":"B","text":"मृदंग और झाँझ","text_en":"मृदंग और झाँझ"},{"id":"C","text":"ढोलक और मंजीरा","text_en":"ढोलक और मंजीरा"},{"id":"D","text":"इकतारा और खड़ताल","text_en":"इकतारा और खड़ताल"}]', '0', '✅ **Correct Logic**: भरथरी गायन नाथ पंथ के लोगों द्वारा चिंकारा और सारंगी जैसे वाद्य यंत्रों की मदद से किया जाता है।
💡 **Exam Fact**: इसमें राजा भर्तृहरि और रानी पिंगला के वैराग्य की कथा होती है।
🧠 **Memory Tip**: B-C-S (Bhartari - Chikara - Sarangi).
🚫 **Scam Alert**: इकतारा का प्रयोग अधिकतर कबीर गायन या निर्गुणी भजनों में होता है।', 2, 0, 2, NULL, 'Which musical instrument is primarily used in ''Bhartari'' singing of Malwa?', '✅ **Correct Logic**: Bhartari singing is performed by followers of the Nath sect using instruments like Chikara and Sarangi.
💡 **Exam Fact**: It focuses on the story of renunciation of King Bhartrihari and Queen Pingala.
🧠 **Memory Tip**: B-C-S (Bhartari - Chikara - Sarangi).
🚫 **Scam Alert**: Ektara is mostly used in Kabir singing or Nirguni bhajans.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('44e6eb66-5012-4a94-8cde-55e411989763', '7b85d2a9-23eb-4599-adfb-06821e1186fb', 'बुंदेलखंड के ''आल्हा गायन'' (Alha Gayan) के संबंध में कौन सा कथन गलत है?', '[{"id":"A","text":"यह वीर रस प्रधान गायन है।","text_en":"यह वीर रस प्रधान गायन है।"},{"id":"B","text":"इसमें आल्हा-ऊदल की 52 लड़ाइयों का वर्णन है।","text_en":"इसमें आल्हा-ऊदल की 52 लड़ाइयों का वर्णन है।"},{"id":"C","text":"इसे मुख्य रूप से शरद ऋतु में गाया जाता है।","text_en":"इसे मुख्य रूप से शरद ऋतु में गाया जाता है।"},{"id":"D","text":"जगानिक इसके मूल रचयिता माने जाते हैं।","text_en":"जगानिक इसके मूल रचयिता माने जाते हैं।"}]', '2', '✅ **Correct Logic**: आल्हा गायन मुख्य रूप से ''वर्षा ऋतु'' (Rainy Season) में गाया जाता है, न कि शरद ऋतु में।
💡 **Exam Fact**: जगानिक ने ''परमाल रासो'' में आल्हा खंड की रचना की थी।
🧠 **Memory Tip**: A-R (Alha - Rain).
🚫 **Scam Alert**: 52 लड़ाइयाँ सही तथ्य है, भ्रमित होकर इसे 12 या 22 न समझें।', 2, 0, 3, NULL, 'Which statement is incorrect regarding the ''Alha Gayan'' of Bundelkhand?', '✅ **Correct Logic**: Alha Gayan is primarily performed during the ''Rainy Season'', not the winter/autumn season.
💡 **Exam Fact**: Jaganik composed the Alha Khand within ''Parmal Raso''.
🧠 **Memory Tip**: A-R (Alha - Rain).
🚫 **Scam Alert**: 52 battles is a correct fact; don''t confuse it with 12 or 22.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('edc91e4e-6f8c-4e39-a341-d4176de61a0a', '7b85d2a9-23eb-4599-adfb-06821e1186fb', 'निमाड़ क्षेत्र के ''कलगी तुरा'' (Kalgi Turra) गायन में ''कलगी'' किसका प्रतीक माना जाता है?', '[{"id":"A","text":"शिव","text_en":"शिव"},{"id":"B","text":"शक्ति (पार्वती)","text_en":"शक्ति (पार्वती)"},{"id":"C","text":"ब्रह्मा","text_en":"ब्रह्मा"},{"id":"D","text":"विष्णु","text_en":"विष्णु"}]', '1', '✅ **Correct Logic**: कलगी तुरा एक प्रतिस्पर्धात्मक गायन है जहाँ ''कलगी'' शक्ति का और ''तुरा'' शिव का प्रतीक माना जाता है।
💡 **Exam Fact**: यह निमाड़ में काफी लोकप्रिय है और अखाड़ों के माध्यम से प्रस्तुत किया जाता है।
🧠 **Memory Tip**: K-S (Kalgi-Shakti).
🚫 **Scam Alert**: कलगी शिव का नहीं बल्कि पार्वती (शक्ति) का पक्ष है।', 2, 0, 4, NULL, 'In the ''Kalgi Turra'' singing of the Nimar region, what is ''Kalgi'' considered a symbol of?', '✅ **Correct Logic**: Kalgi Turra is a competitive folk singing where ''Kalgi'' represents Shakti and ''Turra'' represents Shiva.
💡 **Exam Fact**: It is very popular in Nimar and presented through ''Akharas''.
🧠 **Memory Tip**: K-S (Kalgi-Shakti).
🚫 **Scam Alert**: Kalgi represents the side of Parvati (Shakti), not Shiva.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('34e69144-995a-4a2e-a069-6fad500eb7ea', '7b85d2a9-23eb-4599-adfb-06821e1186fb', 'लोक संगीत और उनके संबंधित क्षेत्रों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: फाग होली पर गाया जाता है। संजा मालवा की कन्याओं का गीत है। मसान्या निमाड़ का मृत्यु गीत है। बिरहा बघेलखंड का प्रमुख लोक गीत है।
💡 **Exam Fact**: मसान्या को ''कायाखोज'' भी कहते हैं क्योंकि इसमें आत्मा की अमरता का वर्णन होता है।
🧠 **Memory Tip**: Birha-Baghelkhand (B-B).
🚫 **Scam Alert**: संजा गीत केवल पितृपक्ष के 16 दिनों में ही गाए जाते हैं।', 2, 0, 5, NULL, 'Match the folk music with their respective regions:', '✅ **Correct Logic**: Phag is sung during Holi. Sanjha is a song of Malwa girls. Masanya is a death song of Nimar. Birha is a major folk song of Baghelkhand.
💡 **Exam Fact**: Masanya is also called ''Kayakhoj'' as it describes the immortality of the soul.
🧠 **Memory Tip**: Birha-Baghelkhand (B-B).
🚫 **Scam Alert**: Sanjha songs are only sung during the 16 days of Pitrupaksha.', 60, 'matching', '[{"id":"(1)","label":"फाग गायन","match":"बुंदेलखंड/बघेलखंड","matchId":"(a)"},{"id":"(2)","label":"संजा गीत","match":"मालवा","matchId":"(b)"},{"id":"(3)","label":"मसान्या (कायाखोज)","match":"निमाड़","matchId":"(c)"},{"id":"(4)","label":"बिरहा","match":"बघेलखंड","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('73d20f0a-b7ac-4bdc-8dcb-3f927a11c3ae', '7b85d2a9-23eb-4599-adfb-06821e1186fb', 'निमाड़ में प्रचलित ''गर्बा-गर्बी'' (Garba-Garbi) गायन के संबंध में ''गर्बी'' मुख्य रूप से किसके द्वारा गाया जाता है?', '[{"id":"A","text":"केवल महिलाओं द्वारा","text_en":"केवल महिलाओं द्वारा"},{"id":"B","text":"केवल पुरुषों द्वारा","text_en":"केवल पुरुषों द्वारा"},{"id":"C","text":"महिला और पुरुष दोनों द्वारा","text_en":"महिला और पुरुष दोनों द्वारा"},{"id":"D","text":"बच्चों द्वारा","text_en":"बच्चों द्वारा"}]', '1', '✅ **Correct Logic**: निमाड़ में ''गर्बा'' स्त्री प्रधान और ''गर्बी'' पुरुष प्रधान गायन शैली है।
💡 **Exam Fact**: इसमें कृष्ण भक्ति के गीत गाए जाते हैं।
🧠 **Memory Tip**: Garb-I (Stri/Female), Garb-I (Purush/Male - tricky tip: I for Insaan/Male in this local context).
🚫 **Scam Alert**: गुजरात के गरबा से प्रभावित होने के बावजूद निमाड़ में पुरुषों का ''गर्बी'' गाना एक विशिष्ट विशेषता है।', 2, 0, 6, NULL, 'Regarding the ''Garba-Garbi'' singing prevalent in Nimar, by whom is ''Garbi'' primarily sung?', '✅ **Correct Logic**: In Nimar, ''Garba'' is female-centric and ''Garbi'' is male-centric singing style.
💡 **Exam Fact**: It features songs dedicated to Lord Krishna.
🧠 **Memory Tip**: Garba-Female, Garbi-Male.
🚫 **Scam Alert**: Despite the influence of Gujarati Garba, the male-centric ''Garbi'' is a unique feature of Nimar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0ec38bda-c847-4297-b71d-273e9056de44', '7b85d2a9-23eb-4599-adfb-06821e1186fb', '''भोला गीत'' या ''बम्बुलिया'' (Bambuliyam) किस क्षेत्र का लोक गीत है और यह किस अवसर पर गाया जाता है?', '[{"id":"A","text":"बुंदेलखंड; शिव-शक्ति की पूजा","text_en":"बुंदेलखंड; शिव-शक्ति की पूजा"},{"id":"B","text":"मालवा; वर्षा ऋतु","text_en":"मालवा; वर्षा ऋतु"},{"id":"C","text":"निमाड़; दीपावली","text_en":"निमाड़; दीपावली"},{"id":"D","text":"बघेलखंड; फसल कटाई","text_en":"बघेलखंड; फसल कटाई"}]', '0', '✅ **Correct Logic**: भोला गीत बुंदेलखंड का प्रसिद्ध लोक गीत है, जो शिवरात्रि, मकर संक्रांति और बसंत पंचमी पर गाया जाता है।
💡 **Exam Fact**: इसे ''लमतैरा'' (Lamtera) भी कहा जाता है।
🧠 **Memory Tip**: Bhola = Bholenath (Shiv).
🚫 **Scam Alert**: यह बिना किसी वाद्य यंत्र के गाया जाने वाला गीत है।', 2, 0, 7, NULL, 'In which region is ''Bhola Geet'' or ''Bambuliyam'' a folk song and on what occasion is it sung?', '✅ **Correct Logic**: Bhola Geet is a famous folk song of Bundelkhand sung during Shivratri, Makar Sankranti, and Basant Panchami.
💡 **Exam Fact**: It is also known as ''Lamtera''.
🧠 **Memory Tip**: Bhola = Bholenath (Shiv).
🚫 **Scam Alert**: This song is uniquely performed without any musical instruments.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('685691cc-33b1-4c93-a60d-184096d1e61a', '7b85d2a9-23eb-4599-adfb-06821e1186fb', 'बघेलखंड में ''विदेशीया'' (Videshiya) गायन का मुख्य विषय क्या है?', '[{"id":"A","text":"विरह और मिलन","text_en":"विरह और मिलन"},{"id":"B","text":"वीर गाथा","text_en":"वीर गाथा"},{"id":"C","text":"बच्चों का जन्म","text_en":"बच्चों का जन्म"},{"id":"D","text":"हास्य व्यंग्य","text_en":"हास्य व्यंग्य"}]', '0', '✅ **Correct Logic**: विदेशीया गायन में नायक और नायिका के बिछड़ने (विरह) और पुनः मिलन का वर्णन होता है।
💡 **Exam Fact**: यह मुख्य रूप से गडरिया, तेली और कोटवार जातियों में प्रचलित है।
🧠 **Memory Tip**: Videsh (Foreign) - someone has gone away (Virah).
🚫 **Scam Alert**: इसे केवल पुरुषों का गीत न समझें, यह एक संवाद शैली जैसा भी हो सकता है।', 2, 0, 8, NULL, 'What is the main theme of ''Videshiya'' singing in Baghelkhand?', '✅ **Correct Logic**: Videshiya singing describes the separation (Virah) and reunion of the hero and heroine.
💡 **Exam Fact**: It is primarily prevalent among Gadaria, Teli, and Kotwar castes.
🧠 **Memory Tip**: Videsh (Foreign) - someone has gone away (Virah).
🚫 **Scam Alert**: Do not consider it only a male song; it can be like a dialogue style.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ab0e8c44-643b-4c33-9136-ae06289aad1b', '7b85d2a9-23eb-4599-adfb-06821e1186fb', 'मालवा के ''हीड गायन'' (Heed Gayan) के संबंध में निम्नलिखित कथनों पर विचार करें:
1. यह अहीर जाति द्वारा गाया जाता है।
2. यह श्रावण माह (वर्षा ऋतु) में प्रचलित है।
3. इसमें कृष्ण की महिमा का वर्णन होता है।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '2', '✅ **Correct Logic**: तीनों कथन सही हैं। हीड गायन मालवा के चरवाहों और अहीर जाति का प्रमुख वर्षाकालीन गीत है।
💡 **Exam Fact**: इसमें राधा-कृष्ण के प्रेम के साथ-साथ खेती-किसानी की बातें भी होती हैं।
🧠 **Memory Tip**: Heed - Shravan (H-S).
🚫 **Scam Alert**: यह बुंदेलखंड का नहीं बल्कि मालवा का गीत है।', 2, 0, 9, NULL, 'Consider the following statements regarding ''Heed Gayan'' of Malwa:
1. It is sung by the Ahir caste.
2. It is prevalent in the month of Shravan (rainy season).
3. It describes the glory of Lord Krishna.

Choose the correct statement:', '✅ **Correct Logic**: All three statements are correct. Heed Gayan is a major monsoon song of shepherds and the Ahir caste in Malwa.
💡 **Exam Fact**: It encompasses Radha-Krishna''s love along with themes of farming.
🧠 **Memory Tip**: Heed - Shravan (H-S).
🚫 **Scam Alert**: It is a song of Malwa, not Bundelkhand.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0d1e91ad-b393-44ee-b5f8-114a92a5d106', '7b85d2a9-23eb-4599-adfb-06821e1186fb', '''देवारी गायन'' (Devari Gayan) किस क्षेत्र का प्रमुख लोक गीत है जो दीपावली के अवसर पर अहीर, गवली और धोबी जातियों द्वारा किया जाता है?', '[{"id":"A","text":"बुंदेलखंड","text_en":"बुंदेलखंड"},{"id":"B","text":"बघेलखंड","text_en":"बघेलखंड"},{"id":"C","text":"मालवा","text_en":"मालवा"},{"id":"D","text":"निमाड़","text_en":"निमाड़"}]', '0', '✅ **Correct Logic**: देवारी गायन बुंदेलखंड का प्रमुख लोक गीत है। इसमें दोहे गाए जाते हैं और नर्तक रंगीन कपड़े पहनकर नृत्य भी करते हैं।
💡 **Exam Fact**: इसे ''दिवाली'' के अपभ्रंश ''देवारी'' से लिया गया है।
🧠 **Memory Tip**: Devari = Diwali in Bundelkhand.
🚫 **Scam Alert**: बघेलखंड में भी अहीर नृत्य करते हैं, लेकिन ''देवारी'' शब्द बुंदेलखंड के लिए विशिष्ट है।', 2, 0, 10, NULL, 'In which region is ''Devari Gayan'' a major folk song performed by Ahir, Gawli, and Dhobi castes on the occasion of Diwali?', '✅ **Correct Logic**: Devari Gayan is a major folk song of Bundelkhand. It involves singing couplets (Dohas) and dancers wearing colorful attire.
💡 **Exam Fact**: The word is derived from ''Devari'', a dialectal variation of Diwali.
🧠 **Memory Tip**: Devari = Diwali in Bundelkhand.
🚫 **Scam Alert**: While Ahirs in Baghelkhand also dance, the term ''Devari'' is specific to Bundelkhand.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('82785022-deb1-4208-851c-6a829cddb904', 'fb972289-af1a-4b18-a380-b34b04e8a852', 'निम्नलिखित में से कौन सी नदियाँ ''पूर्ववर्ती अपवाह'' (Antecedent Drainage) का उदाहरण हैं, जो हिमालय के उत्थान से पहले भी अस्तित्व में थीं?
1. सिंधु (Indus)
2. सतलज (Satluj)
3. ब्रह्मपुत्र (Brahmaputra)
4. गंगा (Ganga)', '[{"id":"A","text":"केवल 1 और 3 (Only 1 and 3)","text_en":"केवल 1 और 3 (Only 1 and 3)"},{"id":"B","text":"केवल 1, 2 और 3 (Only 1, 2 and 3)","text_en":"केवल 1, 2 और 3 (Only 1, 2 and 3)"},{"id":"C","text":"केवल 2 और 4 (Only 2 and 4)","text_en":"केवल 2 और 4 (Only 2 and 4)"},{"id":"D","text":"1, 2, 3 और 4 (1, 2, 3 and 4)","text_en":"1, 2, 3 और 4 (1, 2, 3 and 4)"}]', '1', '**✅ Correct Logic:** **सिंधु, सतलज और ब्रह्मपुत्र** तीनों नदियाँ तिब्बत (मान सरोवर) से निकलती हैं और हिमालय को काटकर गहरे गॉर्ज बनाती हैं। ये हिमालय के बनने से पहले से बह रही हैं। **गंगा** का उद्गम हिमालय के निर्माण के बाद हुआ है (परिवर्ती/Consequent River)।

**💡 Exam Fact:** कोसी और गंडक को भी अक्सर पूर्ववर्ती नदियों की श्रेणी में रखा जाता है।

**🧠 Memory Tip:** **SBI** (Satluj, Brahmaputra, Indus) are the old bosses (Antecedent).

**🚫 Scam Alert:** गंगा भारत की राष्ट्रीय नदी है, लेकिन यह भूगर्भीय रूप से ''युवा'' है और हिमालय की ढलानों का अनुसरण करती है, जबकि SBI हिमालय को काटती हैं।', 2, 0, 1, NULL, 'Which of the following rivers are examples of ''Antecedent Drainage'', existing even before the upliftment of the Himalayas?
1. Indus
2. Satluj
3. Brahmaputra
4. Ganga', '**✅ Correct Logic:** **Indus, Satluj, and Brahmaputra** originate from Tibet (Mansarovar) and cut across the Himalayas creating deep gorges. They existed before the Himalayas were formed. **Ganga** originated after the formation of Himalayas (Consequent River).

**💡 Exam Fact:** Kosi and Gandak are also often categorized as antecedent rivers.

**🧠 Memory Tip:** **SBI** (Satluj, Brahmaputra, Indus) are the old bosses (Antecedent).

**🚫 Scam Alert:** Ganga is the national river, but geologically it is ''young'' and follows the slope (Consequent), whereas SBI cuts through the ranges.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0d3dada3-0a01-4861-94ad-007d09c169d5', 'fb972289-af1a-4b18-a380-b34b04e8a852', 'पंच प्रयाग (Panch Prayag) के संदर्भ में, अलकनंदा नदी किस स्थान पर मंदाकिनी नदी से मिलती है?', '[{"id":"A","text":"रुद्रप्रयाग (Rudraprayag)","text_en":"रुद्रप्रयाग (Rudraprayag)"},{"id":"B","text":"कर्णप्रयाग (Karnaprayag)","text_en":"कर्णप्रयाग (Karnaprayag)"},{"id":"C","text":"नंदप्रयाग (Nandaprayag)","text_en":"नंदप्रयाग (Nandaprayag)"},{"id":"D","text":"देवप्रयाग (Devprayag)","text_en":"देवप्रयाग (Devprayag)"}]', '0', '**✅ Correct Logic:** अलकनंदा और **मंदाकिनी** का संगम **रुद्रप्रयाग** में होता है।

**💡 Exam Fact:**
* देवप्रयाग: अलकनंदा + भागीरथी (यहाँ से ''गंगा'' बनती है)।
* कर्णप्रयाग: अलकनंदा + पिंडर।
* विष्णुप्रयाग: अलकनंदा + धौलीगंगा।

**🧠 Memory Tip:** **Rudra** (Shiva) did Tandav specifically on **Manda**kini -> Rudraprayag.

**🚫 Scam Alert:** देवप्रयाग सबसे प्रसिद्ध है, लेकिन मंदाकिनी (केदारनाथ से आने वाली) रुद्रप्रयाग में मिलती है।', 2, 0, 2, NULL, 'With reference to Panch Prayag, at which location does the Alaknanda River meet the Mandakini River?', '**✅ Correct Logic:** The confluence of Alaknanda and **Mandakini** is at **Rudraprayag**.

**💡 Exam Fact:**
* Devprayag: Alaknanda + Bhagirathi (Forms ''Ganga'').
* Karnaprayag: Alaknanda + Pindar.
* Vishnuprayag: Alaknanda + Dhauliganga.

**🧠 Memory Tip:** **Rudra** (Shiva) -> Mandakini -> Rudraprayag.

**🚫 Scam Alert:** Devprayag is most famous, but Mandakini (from Kedarnath) meets at Rudraprayag.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4b17df09-1409-4311-a9bd-7aad2722ce4a', 'fb972289-af1a-4b18-a380-b34b04e8a852', 'प्रायद्वीपीय भारत की नदियों के जलग्रहण क्षेत्र (Catchment Area) के आधार पर घटते क्रम (Descending Order) में सही अनुक्रम क्या है?', '[{"id":"A","text":"गोदावरी > कृष्णा > महानदी > कावेरी","text_en":"गोदावरी > कृष्णा > महानदी > कावेरी"},{"id":"B","text":"गोदावरी > महानदी > कृष्णा > कावेरी","text_en":"गोदावरी > महानदी > कृष्णा > कावेरी"},{"id":"C","text":"कृष्णा > गोदावरी > कावेरी > महानदी","text_en":"कृष्णा > गोदावरी > कावेरी > महानदी"},{"id":"D","text":"महानदी > गोदावरी > कृष्णा > कावेरी","text_en":"महानदी > गोदावरी > कृष्णा > कावेरी"}]', '0', '**✅ Correct Logic:** सही क्रम: **गोदावरी** (सबसे बड़ी) > **कृष्णा** (दूसरी) > **महानदी** (तीसरी) > **कावेरी**।

**💡 Exam Fact:** गोदावरी का बेसिन क्षेत्र लगभग 3.12 लाख वर्ग किमी है, जो भारत के कुल क्षेत्र का लगभग 10% है।

**🧠 Memory Tip:** **GK** **M**a**K**es sense. (Godavari, Krishna, Mahanadi, Kaveri).

**🚫 Scam Alert:** अक्सर छात्र महानदी और कृष्णा में भ्रमित होते हैं। कृष्णा का बेसिन महानदी से बड़ा है।', 2, 0, 3, NULL, 'What is the correct sequence of Peninsular India rivers in descending order of their Catchment Area?', '**✅ Correct Logic:** Correct Order: **Godavari** (Largest) > **Krishna** (2nd) > **Mahanadi** (3rd) > **Kaveri**.

**💡 Exam Fact:** Godavari basin is approx 3.12 lakh sq km, covering ~10% of India''s area.

**🧠 Memory Tip:** **GK** **M**a**K**es sense. (Godavari, Krishna, Mahanadi, Kaveri).

**🚫 Scam Alert:** Students often confuse Mahanadi and Krishna. Krishna basin is larger than Mahanadi.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3e75bd23-c7b6-41fd-8eee-c1f67bcdf17e', 'fb972289-af1a-4b18-a380-b34b04e8a852', 'निम्नलिखित में से किस नदी को ''दक्षिण की गंगा'' (Ganga of the South) कहा जाता है, विशेष रूप से उसकी पवित्रता के कारण, जबकि गोदावरी को ''दक्षिण गंगा'' (Dakshin Ganga) कहा जाता है?', '[{"id":"A","text":"कावेरी (Kaveri)","text_en":"कावेरी (Kaveri)"},{"id":"B","text":"कृष्णा (Krishna)","text_en":"कृष्णा (Krishna)"},{"id":"C","text":"तुंगभद्रा (Tungabhadra)","text_en":"तुंगभद्रा (Tungabhadra)"},{"id":"D","text":"नर्मदा (Narmada)","text_en":"नर्मदा (Narmada)"}]', '0', '**✅ Correct Logic:** **कावेरी** को उसकी **पवित्रता** और बारहमासी (perennial) प्रकृति के कारण ''दक्षिण की गंगा'' (Ganga of the South) कहा जाता है। **गोदावरी** को उसके **आकार और आयु** (बूढ़ी गंगा) के कारण ''दक्षिण गंगा'' (Dakshin Ganga) कहा जाता है।

**💡 Exam Fact:** कावेरी एकमात्र प्रायद्वीपीय नदी है जिसमें ग्रीष्म (दक्षिण-पश्चिम मानसून) और शीत (उत्तर-पूर्वी मानसून) दोनों ऋतुओं में पानी रहता है।

**🧠 Memory Tip:** **K**averi is **K**ind (Pavitra like Ganga). Godavari is Grand (Old like Ganga).

**🚫 Scam Alert:** यह एक क्लासिक कन्फ्यूजन प्रश्न है। पवित्रता = कावेरी। लंबाई/बुढ़ापा = गोदावरी।', 2, 0, 4, NULL, 'Which of the following rivers is called ''Ganga of the South'' specifically due to its sanctity, whereas Godavari is called ''Dakshin Ganga''?', '**✅ Correct Logic:** **Kaveri** is called ''Ganga of the South'' due to its **sanctity** and perennial nature. **Godavari** is called ''Dakshin Ganga'' due to its **size and age** (Vriddha Ganga).

**💡 Exam Fact:** Kaveri is the only major peninsular river that receives rainfall in both summer (SW Monsoon) and winter (NE Monsoon).

**🧠 Memory Tip:** **K**averi is **K**ind (Sanctity). Godavari is Grand (Size).

**🚫 Scam Alert:** Classic confusion. Sanctity = Kaveri. Size/Age = Godavari.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('848b4b39-3846-4102-87e0-ab9f9abed51d', 'fb972289-af1a-4b18-a380-b34b04e8a852', 'अमरकंटक पठार (Amarkantak Plateau) से निकलने वाली नदियाँ किस प्रकार के अपवाह प्रतिरूप (Drainage Pattern) का सबसे अच्छा उदाहरण प्रस्तुत करती हैं?', '[{"id":"A","text":"जालीनुमा प्रतिरूप (Trellis Pattern)","text_en":"जालीनुमा प्रतिरूप (Trellis Pattern)"},{"id":"B","text":"वृक्षाकार प्रतिरूप (Dendritic Pattern)","text_en":"वृक्षाकार प्रतिरूप (Dendritic Pattern)"},{"id":"C","text":"अरीय प्रतिरूप (Radial Pattern)","text_en":"अरीय प्रतिरूप (Radial Pattern)"},{"id":"D","text":"अभिकेंद्रीय प्रतिरूप (Centripetal Pattern)","text_en":"अभिकेंद्रीय प्रतिरूप (Centripetal Pattern)"}]', '2', '**✅ Correct Logic:** अमरकंटक एक गुंबद (Dome) जैसा पठार है जहाँ से नदियाँ अलग-अलग दिशाओं में निकलती हैं (नर्मदा पश्चिम में, सोन उत्तर में, जोहिला पूर्व में)। इसे **अरीय प्रतिरूप** (Radial Drainage) कहते हैं।

**💡 Exam Fact:** गिरनार पहाड़ियाँ (गुजरात) भी अरीय अपवाह का उदाहरण हैं।

**🧠 Memory Tip:** Like **Rays** from the Sun -> **Radial** from Amarkantak.

**🚫 Scam Alert:** गंगा मैदान में वृक्षाकार (Dendritic) है, लेकिन अमरकंटक एक पहाड़ी चोटी है, इसलिए यहाँ Radial है।', 2, 0, 5, NULL, 'The rivers originating from the Amarkantak Plateau present the best example of which type of Drainage Pattern?', '**✅ Correct Logic:** Amarkantak is a dome-shaped plateau from where rivers flow in different directions (Narmada to West, Son to North, Johila to East). This is called **Radial Drainage**.

**💡 Exam Fact:** Girnar Hills (Gujarat) are also an example of Radial drainage.

**🧠 Memory Tip:** Like **Rays** from the Sun -> **Radial** from Amarkantak.

**🚫 Scam Alert:** Ganga plains have Dendritic, but Amarkantak is a hill peak, so Radial.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e63600c2-d88e-46d2-a4f1-0661cf05c57c', 'fb972289-af1a-4b18-a380-b34b04e8a852', 'यमुना नदी की निम्नलिखित सहायक नदियों को पश्चिम से पूर्व (West to East) दिशा में व्यवस्थित करें:
1. बेतवा (Betwa)
2. केन (Ken)
3. चंबल (Chambal)
4. सिंध (Sind)', '[{"id":"A","text":"3, 4, 1, 2","text_en":"3, 4, 1, 2"},{"id":"B","text":"3, 1, 4, 2","text_en":"3, 1, 4, 2"},{"id":"C","text":"4, 3, 1, 2","text_en":"4, 3, 1, 2"},{"id":"D","text":"3, 4, 2, 1","text_en":"3, 4, 2, 1"}]', '0', '**✅ Correct Logic:** यमुना में मिलने का सही क्रम (पश्चिम से पूर्व): **चंबल** (इटावा) → **सिंध** (जालौन) → **बेतवा** (हमीरपुर) → **केन** (बांदा)।

**💡 Exam Fact:** ये सभी नदियाँ प्रायद्वीपीय पठार (विंध्याचल) से निकलती हैं और यमुना (दाएं तट) में मिलती हैं।

**🧠 Memory Tip:** **CSBK** (Chambal, Sind, Betwa, Ken) - CS Bank.

**🚫 Scam Alert:** ''सिंध'' और ''काली सिंध'' में अंतर है। काली सिंध चंबल की सहायक है, जबकि सिंध सीधे यमुना की सहायक है। क्रम CSBK है।', 2, 0, 6, NULL, 'Arrange the following tributaries of River Yamuna in West to East direction:
1. Betwa
2. Ken
3. Chambal
4. Sind', '**✅ Correct Logic:** Correct order joining Yamuna (West to East): **Chambal** (Etawah) → **Sind** (Jalaun) → **Betwa** (Hamirpur) → **Ken** (Banda).

**💡 Exam Fact:** All these rivers originate from the Peninsular Plateau (Vindhyas) and join Yamuna (Right bank).

**🧠 Memory Tip:** **CSBK** (Chambal, Sind, Betwa, Ken) - CS Bank.

**🚫 Scam Alert:** Difference between ''Sind'' and ''Kali Sind''. Kali Sind is tributary of Chambal, while Sind joins Yamuna directly. Order is CSBK.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a8067645-b3ae-440a-a22c-6b32e0dda727', 'fb972289-af1a-4b18-a380-b34b04e8a852', 'बराक नदी (Barak River) भारत के किन राज्यों से होकर बहती है और यह किस देश में ''मेघना'' बन जाती है?', '[{"id":"A","text":"मणिपुर, मिजोरम, असम -> बांग्लादेश (Manipur, Mizoram, Assam -> Bangladesh)","text_en":"मणिपुर, मिजोरम, असम -> बांग्लादेश (Manipur, Mizoram, Assam -> Bangladesh)"},{"id":"B","text":"अरुणाचल प्रदेश, असम -> बांग्लादेश (Arunachal, Assam -> Bangladesh)","text_en":"अरुणाचल प्रदेश, असम -> बांग्लादेश (Arunachal, Assam -> Bangladesh)"},{"id":"C","text":"त्रिपुरा, मेघालय, असम -> म्यांमार (Tripura, Meghalaya, Assam -> Myanmar)","text_en":"त्रिपुरा, मेघालय, असम -> म्यांमार (Tripura, Meghalaya, Assam -> Myanmar)"},{"id":"D","text":"मणिपुर, नागालैंड, असम -> म्यांमार (Manipur, Nagaland, Assam -> Myanmar)","text_en":"मणिपुर, नागालैंड, असम -> म्यांमार (Manipur, Nagaland, Assam -> Myanmar)"}]', '0', '**✅ Correct Logic:** बराक नदी **मणिपुर** पहाड़ियों से निकलती है, **मिजोरम** और **असम** (कछार घाटी) से बहते हुए **बांग्लादेश** में प्रवेश करती है, जहाँ यह सुरमा और कुशियारा में बँटती है और अंततः **मेघना** कहलाती है।

**💡 Exam Fact:** राष्ट्रीय जलमार्ग 6 (NW-6) बराक नदी पर लखीपुर से भांगा तक स्थित है।

**🧠 Memory Tip:** **MMA** fighter goes to **Bangla**. (Manipur, Mizoram, Assam -> Bangladesh).

**🚫 Scam Alert:** यह ब्रह्मपुत्र की सहायक नदी नहीं है (सीधे तौर पर), यह मेघना बनकर मिलती है। अरुणाचल में इसका कोई प्रवाह नहीं है।', 2, 0, 7, NULL, 'Barak River flows through which Indian states and becomes ''Meghna'' in which country?', '**✅ Correct Logic:** Barak River originates in **Manipur** hills, flows through **Mizoram** and **Assam** (Cachar Valley), enters **Bangladesh**, splits into Surma and Kushiyara, and finally becomes **Meghna**.

**💡 Exam Fact:** National Waterway 6 (NW-6) is on Barak river (Lakhipur to Bhanga).

**🧠 Memory Tip:** **MMA** fighter goes to **Bangla**. (Manipur, Mizoram, Assam -> Bangladesh).

**🚫 Scam Alert:** It is not a direct tributary of Brahmaputra; it meets as Meghna. No flow in Arunachal.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c8564a1a-9d20-4323-8bcf-5449acc153bc', 'fb972289-af1a-4b18-a380-b34b04e8a852', 'सिंधु जल संधि (Indus Water Treaty), 1960 के तहत, भारत को किन तीन नदियों के जल का अनन्य उपयोग (Exclusive usage) अधिकार प्राप्त है?', '[{"id":"A","text":"सिंधु, झेलम, चिनाब (Indus, Jhelum, Chenab)","text_en":"सिंधु, झेलम, चिनाब (Indus, Jhelum, Chenab)"},{"id":"B","text":"रावी, व्यास, सतलज (Ravi, Beas, Satluj)","text_en":"रावी, व्यास, सतलज (Ravi, Beas, Satluj)"},{"id":"C","text":"सतलज, सिंधु, झेलम (Satluj, Indus, Jhelum)","text_en":"सतलज, सिंधु, झेलम (Satluj, Indus, Jhelum)"},{"id":"D","text":"चिनाब, रावी, व्यास (Chenab, Ravi, Beas)","text_en":"चिनाब, रावी, व्यास (Chenab, Ravi, Beas)"}]', '1', '**✅ Correct Logic:** संधि के तहत, पूर्वी नदियाँ (**रावी, व्यास, सतलज**) भारत को दी गईं और पश्चिमी नदियाँ (**सिंधु, झेलम, चिनाब**) पाकिस्तान को दी गईं।

**💡 Exam Fact:** यह संधि विश्व बैंक (World Bank) की मध्यस्थता में कराची में हस्ताक्षरित हुई थी।

**🧠 Memory Tip:** India controls the **East** (RBS), Pakistan controls the **West** (IJC).

**🚫 Scam Alert:** सिंधु नाम संधि में है, लेकिन भारत को सिंधु नदी के पानी पर पूर्ण अधिकार नहीं है (केवल 20% उपयोग)।', 2, 0, 8, NULL, 'Under the Indus Water Treaty, 1960, India has exclusive usage rights over the waters of which three rivers?', '**✅ Correct Logic:** Under the treaty, Eastern Rivers (**Ravi, Beas, Satluj**) were allocated to India, and Western Rivers (**Indus, Jhelum, Chenab**) to Pakistan.

**💡 Exam Fact:** Treaty was brokered by the World Bank and signed in Karachi.

**🧠 Memory Tip:** India controls the **East** (RBS), Pakistan controls the **West** (IJC).

**🚫 Scam Alert:** Indus is the name of the treaty, but India does NOT have exclusive rights to Indus river water (only 20% usage).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7d50da32-e7d1-4bb2-9917-c6b89bcdc941', 'fb972289-af1a-4b18-a380-b34b04e8a852', 'निम्नलिखित में से कौन सी नदी ''भ्रंश घाटी'' (Rift Valley) से होकर नहीं बहती है, लेकिन अक्सर भ्रंश घाटी वाली नदियों के साथ भ्रमित की जाती है?', '[{"id":"A","text":"नर्मदा (Narmada)","text_en":"नर्मदा (Narmada)"},{"id":"B","text":"ताप्ती (Tapti)","text_en":"ताप्ती (Tapti)"},{"id":"C","text":"दामोदर (Damodar)","text_en":"दामोदर (Damodar)"},{"id":"D","text":"गोदावरी (Godavari)","text_en":"गोदावरी (Godavari)"}]', '3', '**✅ Correct Logic:** नर्मदा, ताप्ती और दामोदर तीनों प्रसिद्ध **भ्रंश घाटी** (Rift Valley) नदियाँ हैं। **गोदावरी** एक भ्रंशित घाटी में नहीं बहती (हालांकि कुछ छोटे खंड हो सकते हैं, लेकिन भूवैज्ञानिक रूप से यह एक पूर्ववर्ती ढलान का पालन करती है)। *Note: Mahanadi flows in a fault basin but Godavari is strictly Peninsular slope.* कुछ स्रोतों में माही को भी भ्रंश में बताया जाता है, लेकिन गोदावरी स्पष्ट रूप से बाहर है।

**💡 Exam Fact:** नर्मदा भारत की सबसे लंबी पश्चिम की ओर बहने वाली नदी है।

**🧠 Memory Tip:** **DTN** (Damodar, Tapti, Narmada) live in Rifts.

**🚫 Scam Alert:** दामोदर पूर्व में बहती है फिर भी भ्रंश घाटी में है (Down-warping)। गोदावरी नहीं है।', 2, 0, 9, NULL, 'Which of the following rivers does NOT flow through a ''Rift Valley'' but is often confused with rift valley rivers?', '**✅ Correct Logic:** Narmada, Tapti, and Damodar are the three famous **Rift Valley** rivers. **Godavari** does not flow in a rift valley (it follows the general slope of the plateau). 

**💡 Exam Fact:** Narmada is the longest west-flowing river of India.

**🧠 Memory Tip:** **DTN** (Damodar, Tapti, Narmada) live in Rifts.

**🚫 Scam Alert:** Damodar flows East but is still in a Rift (Trough). Godavari is not.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f37d5b56-0c3c-48c3-aaab-59b099857829', 'fb972289-af1a-4b18-a380-b34b04e8a852', 'निम्नलिखित नदियों को उनके उद्गम स्थल से सुमेलित करें (Match the following rivers with their origin):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)","text_en":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)"}]', '1', '**✅ Correct Matching:**
* **कृष्णा**: महाबलेश्वर (महाराष्ट्र)। -> (1)-(a)
* **गोदावरी**: त्र्यंबकेश्वर (नासिक, महाराष्ट्र)। -> (2)-(b)
* **कावेरी**: तालकावेरी/ब्रह्मगिरी पहाड़ियाँ (कूर्ग, कर्नाटक)। -> (3)-(c)
* **ताप्ती**: मुलताई (बैतूल जिला, म.प्र.)। -> (4)-(d)

**💡 Exam Fact:** मुलताई का अर्थ है ''ताप्ती का मूल'' (Root of Tapti)।

**🧠 Memory Tip:** **K**rishna is **M**aha (Mahabaleshwar). **G**odavari is **T**ri (Trimbakeshwar). **K**averi is **B**rahma. **T**apti is **M**ultai.

**🚫 Scam Alert:** महाबलेश्वर और त्र्यंबकेश्वर दोनों महाराष्ट्र में हैं, अक्सर छात्र इन्हें उल्टा कर देते हैं।', 2, 0, 10, NULL, 'Match the following rivers with their origin:', '**✅ Correct Matching:**
* **Krishna**: Mahabaleshwar (MH). -> (1)-(a)
* **Godavari**: Trimbakeshwar (Nashik, MH). -> (2)-(b)
* **Kaveri**: Brahmagiri Hills (Coorg, KA). -> (3)-(c)
* **Tapti**: Multai (Betul, MP). -> (4)-(d)

**💡 Exam Fact:** Multai means ''Origin of Tapti''.

**🧠 Memory Tip:** **K**rishna is **M**aha. **G**odavari is **T**ri. **K**averi is **B**rahma.

**🚫 Scam Alert:** Mahabaleshwar and Trimbakeshwar are both in MH, students often swap them.', 60, 'matching', '[{"id":"(1)","label":"कृष्णा (Krishna)","match":"महाबलेश्वर (Mahabaleshwar)","matchId":"(a)"},{"id":"(2)","label":"गोदावरी (Godavari)","match":"त्र्यंबकेश्वर (Trimbakeshwar)","matchId":"(b)"},{"id":"(3)","label":"कावेरी (Kaveri)","match":"ब्रह्मगिरी पहाड़ियाँ (Brahmagiri Hills)","matchId":"(c)"},{"id":"(4)","label":"ताप्ती (Tapti)","match":"मुलताई (Multai)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8d52020b-5bb4-41aa-a304-73098601006a', '9222871b-10f1-4e91-989f-c20de785e0a7', 'लोकटक झील (Loktak Lake) के बारे में निम्नलिखित कथनों पर विचार करें:
1. यह पूर्वोत्तर भारत की सबसे बड़ी मीठे पानी की झील है।
2. यह अपनी ''फुमुदी'' (Phumdis) या तैरते हुए द्वीपों के लिए प्रसिद्ध है।
3. इसे मोंट्रेक्स रिकॉर्ड (Montreux Record) से हटा दिया गया है।
सही कथन कौन से हैं?', '[{"id":"A","text":"केवल 1 और 2 (Only 1 and 2)","text_en":"केवल 1 और 2 (Only 1 and 2)"},{"id":"B","text":"केवल 2 और 3 (Only 2 and 3)","text_en":"केवल 2 और 3 (Only 2 and 3)"},{"id":"C","text":"केवल 1 और 3 (Only 1 and 3)","text_en":"केवल 1 और 3 (Only 1 and 3)"},{"id":"D","text":"1, 2 और 3 (1, 2 and 3)","text_en":"1, 2 और 3 (1, 2 and 3)"}]', '0', '**✅ Correct Logic:** कथन 1 और 2 सही हैं। कथन 3 **गलत** है। लोकटक झील (मणिपुर) अभी भी **मोंट्रेक्स रिकॉर्ड** (रामसर कन्वेंशन के तहत खतरे वाली साइटों की सूची) में शामिल है। (दूसरी साइट केवलादेव है)। चिल्का झील को हटा दिया गया था।

**💡 Exam Fact:** दुनिया का एकमात्र तैरता हुआ राष्ट्रीय उद्यान ''केइबुल लामजाओ'' (Keibul Lamjao) इसी झील में है, जहाँ **संगाई हिरण** (Dancing Deer) पाया जाता है।

**🧠 Memory Tip:** Loktak has **Locked** the Deer on floating grass.

**🚫 Scam Alert:** छात्र अक्सर चिल्का और लोकटक के मोंट्रेक्स स्टेटस में भ्रमित होते हैं। चिल्का out, Loktak in.', 2, 0, 1, NULL, 'Consider the following statements about Loktak Lake:
1. It is the largest freshwater lake in Northeast India.
2. It is famous for its ''Phumdis'' or floating islands.
3. It has been removed from the Montreux Record.
Which statements are correct?', '**✅ Correct Logic:** Statements 1 and 2 are correct. Statement 3 is **INCORRECT**. Loktak Lake (Manipur) is **Still** in the **Montreux Record** (List of threatened Ramsar sites). (The other one is Keoladeo). Chilika was removed.

**💡 Exam Fact:** World''s only floating National Park ''Keibul Lamjao'' is here, home to **Sangai Deer**.

**🧠 Memory Tip:** Loktak has **Locked** the Deer.

**🚫 Scam Alert:** Students confuse Montreux status of Chilika and Loktak. Chilika is OUT, Loktak is IN.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3b6c5ab2-e376-40de-991b-f4d26440a1d8', '9222871b-10f1-4e91-989f-c20de785e0a7', 'लोनार झील (Lonar Lake), जिसका पानी कभी-कभी गुलाबी हो जाता है, भूवैज्ञानिक रूप से किस प्रकार की झील है?', '[{"id":"A","text":"गोखुर झील (Oxbow Lake)","text_en":"गोखुर झील (Oxbow Lake)"},{"id":"B","text":"लैगून झील (Lagoon Lake)","text_en":"लैगून झील (Lagoon Lake)"},{"id":"C","text":"क्रेटर/इम्पैक्ट झील (Crater/Impact Lake)","text_en":"क्रेटर/इम्पैक्ट झील (Crater/Impact Lake)"},{"id":"D","text":"हिमनद झील (Glacial Lake)","text_en":"हिमनद झील (Glacial Lake)"}]', '2', '**✅ Correct Logic:** लोनार झील (बुलढाणा, महाराष्ट्र) एक **क्रेटर झील** है जो प्लेइस्टोसिन युग में एक उल्कापिंड (Meteorite) के टकराने से बनी थी। यह बेसाल्टिक चट्टान में स्थित है।

**💡 Exam Fact:** हाल ही में ''हेलोआर्किया'' (Haloarchaea) रोगाणुओं के कारण इसका पानी गुलाबी हो गया था। यह एक रामसर साइट भी है।

**🧠 Memory Tip:** **Lonar** sounds like **Lunar** (Moon/Space) -> Meteor came from space.

**🚫 Scam Alert:** यह ज्वालामुखी क्रेटर नहीं (Volcanic Crater), बल्कि उल्कापिंड इम्पैक्ट क्रेटर है। दोनों में थोड़ा अंतर है।', 2, 0, 2, NULL, 'Lonar Lake, whose water sometimes turns pink, is geologically which type of lake?', '**✅ Correct Logic:** Lonar Lake (Buldhana, MH) is a **Crater/Impact Lake** formed by a Meteorite impact during the Pleistocene Epoch. It sits in basaltic rock.

**💡 Exam Fact:** Recently its water turned pink due to ''Haloarchaea'' microbes. It is a Ramsar site.

**🧠 Memory Tip:** **Lonar** sounds like **Lunar** -> Meteor from space.

**🚫 Scam Alert:** It is an Impact Crater, not a Volcanic Crater.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8f1049d6-fac9-42ea-8654-142e872f5a00', '9222871b-10f1-4e91-989f-c20de785e0a7', 'भारत की सबसे लंबी झील ''वेम्बनाड'' (Vembanad) किस राज्य में स्थित है और इसमें कौन सी प्रसिद्ध प्रतियोगिता आयोजित की जाती है?', '[{"id":"A","text":"केरल - नेहरू ट्रॉफी नौका दौड़ (Kerala - Nehru Trophy Boat Race)","text_en":"केरल - नेहरू ट्रॉफी नौका दौड़ (Kerala - Nehru Trophy Boat Race)"},{"id":"B","text":"तमिलनाडु - जल्लीकट्टू (Tamil Nadu - Jallikattu)","text_en":"तमिलनाडु - जल्लीकट्टू (Tamil Nadu - Jallikattu)"},{"id":"C","text":"आंध्र प्रदेश - फ्लेमिंगो फेस्टिवल (Andhra Pradesh - Flamingo Festival)","text_en":"आंध्र प्रदेश - फ्लेमिंगो फेस्टिवल (Andhra Pradesh - Flamingo Festival)"},{"id":"D","text":"ओडिशा - बाली जात्रा (Odisha - Bali Yatra)","text_en":"ओडिशा - बाली जात्रा (Odisha - Bali Yatra)"}]', '0', '**✅ Correct Logic:** वेम्बनाड झील **केरल** में है और यह भारत की **सबसे लंबी** (longest) झील है। यहाँ ओणम के दौरान **नेहरू ट्रॉफी बोट रेस** (Snake Boat Race) होती है।

**💡 Exam Fact:** कोच्चि शहर और वेलिंगटन द्वीप इसी झील के मुहाने पर स्थित हैं।

**🧠 Memory Tip:** **Vembanad** -> **Bamboo** (Long) -> Longest lake -> Boat race.

**🚫 Scam Alert:** सबसे बड़ी (Area) चिल्का है, लेकिन सबसे लंबी (Length ~96km) वेम्बनाड है।', 2, 0, 3, NULL, 'India''s longest lake ''Vembanad'' is located in which state and which famous competition is held in it?', '**✅ Correct Logic:** Vembanad Lake is in **Kerala** and is India''s **Longest** lake. The **Nehru Trophy Boat Race** (Snake Boat Race) is held here during Onam.

**💡 Exam Fact:** Kochi city and Wellington Island are located at its mouth.

**🧠 Memory Tip:** **Vembanad** -> **Bamboo** (Long) -> Longest lake.

**🚫 Scam Alert:** Largest (Area) is Chilika, but Longest (Length) is Vembanad.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0a3b88a4-5539-4eed-843a-9114cf7e4e2b', '9222871b-10f1-4e91-989f-c20de785e0a7', 'निम्नलिखित में से कौन सी झील ''गोखुर झील'' (Oxbow Lake) का एक उदाहरण है जो मीठे पानी की सबसे बड़ी झीलों में से एक है?', '[{"id":"A","text":"वुलर झील (Wular Lake)","text_en":"वुलर झील (Wular Lake)"},{"id":"B","text":"डडल झील (Dal Lake)","text_en":"डडल झील (Dal Lake)"},{"id":"C","text":"सांभर झील (Sambhar Lake)","text_en":"सांभर झील (Sambhar Lake)"},{"id":"D","text":"पेंगोंग त्सो (Pangong Tso)","text_en":"पेंगोंग त्सो (Pangong Tso)"}]', '0', '**✅ Correct Logic:** **वुलर झील** (कश्मीर) झेलम नदी के विसर्प (meandering) से बनी एक **गोखुर झील** है (हालांकि इसमें विवर्तनिक/tectonic गतिविधि का भी हाथ है)। यह भारत की सबसे बड़ी मीठे पानी की झीलों में से एक है।

**💡 Exam Fact:** तुलबुल परियोजना (Tulbul Project) इसी झील के मुहाने पर स्थित है।

**🧠 Memory Tip:** **Wular** -> **Wool** -> Sheep walk in curves -> Meandering/Oxbow.

**🚫 Scam Alert:** डल झील एक हिमनद/फ्लुवियल झील है। सांभर लवणीय है। वुलर गोखुर का क्लासिक उदाहरण है (झेलम)।', 2, 0, 4, NULL, 'Which of the following lakes is an example of an ''Oxbow Lake'' and is one of the largest freshwater lakes?', '**✅ Correct Logic:** **Wular Lake** (Kashmir) is formed by the meandering of Jhelum river acting as an **Oxbow Lake** (though tectonic activity also played a part). It is one of the largest freshwater lakes.

**💡 Exam Fact:** Tulbul Project is located at its mouth.

**🧠 Memory Tip:** **Wular** -> **Wool** -> Curves -> Oxbow.

**🚫 Scam Alert:** Dal is Glacial/Fluvial. Sambhar is Saline. Wular is the Oxbow example.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1739590f-baa1-44f5-90d8-ab131487c0c0', '9222871b-10f1-4e91-989f-c20de785e0a7', 'पुलीकट झील (Pulicat Lake) के बारे में क्या सत्य है?', '[{"id":"A","text":"यह पूरी तरह से तमिलनाडु में स्थित है। (It is entirely in Tamil Nadu)","text_en":"यह पूरी तरह से तमिलनाडु में स्थित है। (It is entirely in Tamil Nadu)"},{"id":"B","text":"यह भारत की सबसे बड़ी लैगून झील है। (It is India''s largest lagoon lake)","text_en":"यह भारत की सबसे बड़ी लैगून झील है। (It is India''s largest lagoon lake)"},{"id":"C","text":"श्रीहरिकोटा द्वीप इसे बंगाल की खाड़ी से अलग करता है। (Sriharikota Island separates it from Bay of Bengal)","text_en":"श्रीहरिकोटा द्वीप इसे बंगाल की खाड़ी से अलग करता है। (Sriharikota Island separates it from Bay of Bengal)"},{"id":"D","text":"यह एक मीठे पानी की झील है। (It is a freshwater lake)","text_en":"यह एक मीठे पानी की झील है। (It is a freshwater lake)"}]', '2', '**✅ Correct Logic:** पुलीकट झील आंध्र प्रदेश (96%) और तमिलनाडु (4%) की सीमा पर है। **श्रीहरिकोटा** (ISRO लॉन्च पैड) इसे समुद्र से अलग करता है। यह खारे पानी की (Brackish) लैगून है।

**💡 Exam Fact:** यह चिल्का के बाद भारत की **दूसरी** सबसे बड़ी खारे पानी की झील/लैगून है।

**🧠 Memory Tip:** **Puli**cat -> **Puli** (Space jump) -> Sriharikota launch pad.

**🚫 Scam Alert:** यह पूरी तरह तमिलनाडु में नहीं है (बड़ा हिस्सा आंध्र में है)। सबसे बड़ी चिल्का है।', 2, 0, 5, NULL, 'What is true about Pulicat Lake?', '**✅ Correct Logic:** Pulicat Lake is on the border of AP (96%) and TN (4%). **Sriharikota** (ISRO launch pad) separates it from the sea. It is a brackish water lagoon.

**💡 Exam Fact:** It is the **second** largest brackish water lake/lagoon after Chilika.

**🧠 Memory Tip:** **Puli**cat -> **Puli** (Jump) -> Sriharikota.

**🚫 Scam Alert:** Not entirely in TN. Chilika is the largest.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0155301b-52d3-448a-965e-40c0ef6ecc1e', '9222871b-10f1-4e91-989f-c20de785e0a7', 'भारत की सबसे बड़ी अंतर्देशीय खारे पानी की झील (Largest Inland Saline Lake) कौन सी है?', '[{"id":"A","text":"चिल्का (Chilika)","text_en":"चिल्का (Chilika)"},{"id":"B","text":"सांभर (Sambhar)","text_en":"सांभर (Sambhar)"},{"id":"C","text":"लोनार (Lonar)","text_en":"लोनार (Lonar)"},{"id":"D","text":"पुलिकट (Pulicat)","text_en":"पुलिकट (Pulicat)"}]', '1', '**✅ Correct Logic:** **सांभर झील** (जयपुर, राजस्थान) भारत की **सबसे बड़ी अंतर्देशीय** (Inland) खारे पानी की झील है। भारत का लगभग 9% नमक उत्पादन यहीं से होता है।

**💡 Exam Fact:** चिल्का सबसे बड़ी झील है लेकिन वह ''लैगून'' (तटीय) है। सांभर ''अंतर्देशीय'' (Landlocked) है।

**🧠 Memory Tip:** **Sambhar** Idli (Salty) -> Inland Salt.

**🚫 Scam Alert:** चिल्का मत चुनना! चिल्का लैगून है, सांभर इनलैंड है।', 2, 0, 6, NULL, 'Which is the Largest Inland Saline Lake of India?', '**✅ Correct Logic:** **Sambhar Lake** (Jaipur, RJ) is India''s **Largest Inland** saline lake. Approx 9% of India''s salt comes from here.

**💡 Exam Fact:** Chilika is the largest lake but it is a ''Lagoon'' (Coastal). Sambhar is ''Inland''.

**🧠 Memory Tip:** **Sambhar** Idli (Salty) -> Inland Salt.

**🚫 Scam Alert:** Don''t pick Chilika! Chilika is a lagoon, Sambhar is Inland.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f1692fe2-9947-4279-807c-e91cc658e91c', '9222871b-10f1-4e91-989f-c20de785e0a7', 'सिक्किम में स्थित ''चोलामू झील'' (Cholamu Lake) या ''त्सो ल्हामो'' की क्या विशेषता है?', '[{"id":"A","text":"यह भारत की सबसे गहरी झील है (Deepest lake)","text_en":"यह भारत की सबसे गहरी झील है (Deepest lake)"},{"id":"B","text":"यह भारत की सबसे अधिक ऊंचाई पर स्थित झील है (Highest altitude lake)","text_en":"यह भारत की सबसे अधिक ऊंचाई पर स्थित झील है (Highest altitude lake)"},{"id":"C","text":"यह तीस्ता नदी का उद्गम स्थल है (Source of Teesta river)","text_en":"यह तीस्ता नदी का उद्गम स्थल है (Source of Teesta river)"},{"id":"D","text":"विकल्प B और C दोनों (Both Option B and C)","text_en":"विकल्प B और C दोनों (Both Option B and C)"}]', '3', '**✅ Correct Logic:** चोलामू झील (17,487 फीट) भारत की **सबसे ऊंची** झील है और यह **तीस्ता नदी** का उद्गम स्थल भी मानी जाती है।

**💡 Exam Fact:** गुरुडोंगमार झील (Gurudongmar) भी सिक्किम में बहुत ऊंचाई पर है और पवित्र मानी जाती है।

**🧠 Memory Tip:** **Cho**lamu is on the **Cho**ti (Top/Peak).

**🚫 Scam Alert:** वुलर सबसे बड़ी है, चोलामू सबसे ऊंची है।', 2, 0, 7, NULL, 'What is the special feature of ''Cholamu Lake'' or ''Tso Lhamo'' located in Sikkim?', '**✅ Correct Logic:** Cholamu Lake (17,487 ft) is India''s **Highest** lake and is also considered the source of the **Teesta River**.

**💡 Exam Fact:** Gurudongmar Lake is also in Sikkim at high altitude and is sacred.

**🧠 Memory Tip:** **Cho**lamu is on the **Cho**ti (Top).

**🚫 Scam Alert:** Wular is largest, Cholamu is highest.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7100f6a7-1f05-4b79-b537-a72a5080aebb', '9222871b-10f1-4e91-989f-c20de785e0a7', 'निम्नलिखित में से कौन सी झील एक ''मानव निर्मित'' (Artificial) झील है?', '[{"id":"A","text":"नैनीताल (Nainital)","text_en":"नैनीताल (Nainital)"},{"id":"B","text":"रेणुका झील (Renuka Lake)","text_en":"रेणुका झील (Renuka Lake)"},{"id":"C","text":"गोबिंद बल्लभ पंत सागर (Gobind Ballabh Pant Sagar)","text_en":"गोबिंद बल्लभ पंत सागर (Gobind Ballabh Pant Sagar)"},{"id":"D","text":"लोकटक (Loktak)","text_en":"लोकटक (Loktak)"}]', '2', '**✅ Correct Logic:** **गोबिंद बल्लभ पंत सागर** (रिहंद बांध का जलाशय) भारत की सबसे बड़ी मानव निर्मित झील है। यह उत्तर प्रदेश और मध्य प्रदेश की सीमा (सोनभद्र) पर स्थित है।

**💡 Exam Fact:** स्टेनली जलाशय (मैटूर बांध) और नागार्जुन सागर भी कृत्रिम झीलें हैं।

**🧠 Memory Tip:** **Gobind** was a man -> Man-made lake.

**🚫 Scam Alert:** रेणुका (HP) सबसे छोटी रामसर साइट है (प्राकृतिक)। नैनीताल टेक्टोनिक/प्राकृतिक है।', 2, 0, 8, NULL, 'Which of the following is an ''Artificial'' (Man-made) lake?', '**✅ Correct Logic:** **Gobind Ballabh Pant Sagar** (Reservoir of Rihand Dam) is India''s largest man-made lake. Located on UP-MP border.

**💡 Exam Fact:** Stanley Reservoir (Mettur) and Nagarjuna Sagar are also artificial.

**🧠 Memory Tip:** **Gobind** was a man -> Man-made lake.

**🚫 Scam Alert:** Renuka (HP) is the smallest Ramsar site (Natural). Nainital is Natural.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d34d4ed3-a6b4-4d46-9fc4-42fbd2b7e139', '9222871b-10f1-4e91-989f-c20de785e0a7', 'कोलेरू झील (Kolleru Lake) किन दो प्रमुख नदी डेल्टाओं के बीच स्थित है?', '[{"id":"A","text":"महानदी और गोदावरी (Mahanadi and Godavari)","text_en":"महानदी और गोदावरी (Mahanadi and Godavari)"},{"id":"B","text":"गोदावरी और कृष्णा (Godavari and Krishna)","text_en":"गोदावरी और कृष्णा (Godavari and Krishna)"},{"id":"C","text":"कृष्णा और कावेरी (Krishna and Kaveri)","text_en":"कृष्णा और कावेरी (Krishna and Kaveri)"},{"id":"D","text":"कावेरी और वैगई (Kaveri and Vaigai)","text_en":"कावेरी और वैगई (Kaveri and Vaigai)"}]', '1', '**✅ Correct Logic:** कोलेरू झील (आंध्र प्रदेश) **गोदावरी** और **कृष्णा** नदियों के डेल्टा के बीच एक मीठे पानी की झील (Freshwater lake) है।

**💡 Exam Fact:** यह पहले एक लैगून थी, लेकिन डेल्टा के विस्तार के कारण अब यह समुद्र से दूर हो गई है। ''ऑपरेशन कोलेरू'' (2006) मछली के तालाबों को हटाने के लिए चलाया गया था।

**🧠 Memory Tip:** **G-K** ke beech me **Ko**lleru.

**🚫 Scam Alert:** यह गोदावरी-कृष्णा के बीच है, न कि महानदी-गोदावरी (वहाँ चिल्का पास है)।', 2, 0, 9, NULL, 'Kolleru Lake is located between which two major river deltas?', '**✅ Correct Logic:** Kolleru Lake (AP) is a freshwater lake located between the deltas of **Godavari** and **Krishna**.

**💡 Exam Fact:** It was formerly a lagoon, but delta expansion cut it off from the sea. ''Operation Kolleru'' was launched to clear encroachments.

**🧠 Memory Tip:** **G-K** ke beech me **Ko**lleru.

**🚫 Scam Alert:** Not Mahanadi-Godavari (Chilika is near there).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f509e73b-a42f-4840-b411-d6404169b428', '9222871b-10f1-4e91-989f-c20de785e0a7', 'निम्नलिखित झीलों को उनके राज्यों से सुमेलित करें (Match the following lakes with their states):', '[{"id":"A","text":"(1)-(b), (2)-(c), (3)-(a), (4)-(d)","text_en":"(1)-(b), (2)-(c), (3)-(a), (4)-(d)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)","text_en":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)"},{"id":"D","text":"(1)-(c), (2)-(b), (3)-(d), (4)-(a)","text_en":"(1)-(c), (2)-(b), (3)-(d), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **रूपकुंड**: उत्तराखंड (इसे ''कंकाल झील''/Skeleton Lake भी कहते हैं)। -> (1)-(b)
* **सास्तमकोट्टा**: केरल (इसे ''झीलों की रानी'' कहते हैं, यह केरल की सबसे बड़ी मीठे पानी की झील है)। -> (2)-(c)
* **दीपोर बील**: असम (गुवाहाटी के पास, रामसर साइट)। -> (3)-(a)
* **तसो मोरीरी**: लद्दाख (ऊंचाई पर स्थित लवणीय झील)। -> (4)-(d)

**💡 Exam Fact:** ''बील'' (Beel) शब्द असम/बंगाल में झील के लिए प्रयोग होता है।

**🧠 Memory Tip:** **Roop** in UK (Uttarakhand). **Sastam** in Kerala. **Beel** in Assam. **Tso** in Ladakh.

**🚫 Scam Alert:** सास्तमकोट्टा और अष्टमुडी केरल में हैं। रूपकुंड (Skeleton) बहुत प्रसिद्ध है, इसे हिमाचल से न जोड़ें।', 2, 0, 10, NULL, 'Match the following lakes with their states:', '**✅ Correct Matching:**
* **Roopkund**: Uttarakhand (Skeleton Lake). -> (1)-(b)
* **Sasthamkotta**: Kerala (Queen of Lakes). -> (2)-(c)
* **Deepor Beel**: Assam (Ramsar site). -> (3)-(a)
* **Tso Moriri**: Ladakh. -> (4)-(d)

**💡 Exam Fact:** ''Beel'' means lake in Assam/Bengal.

**🧠 Memory Tip:** **Roop** in UK. **Sastam** in Kerala. **Beel** in Assam. **Tso** in Ladakh.

**🚫 Scam Alert:** Don''t confuse Roopkund with Himachal. It''s in UK.', 60, 'matching', '[{"id":"(1)","label":"रूपकुंड (Roopkund)","match":"असम (Assam)","matchId":"(a)"},{"id":"(2)","label":"सास्तमकोट्टा (Sasthamkotta)","match":"उत्तराखंड (Uttarakhand)","matchId":"(b)"},{"id":"(3)","label":"दीपोर बील (Deepor Beel)","match":"केरल (Kerala)","matchId":"(c)"},{"id":"(4)","label":"तसो मोरीरी (Tso Moriri)","match":"लद्दाख (Ladakh)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1d975eb2-3529-4624-a259-5cd88d4c9c15', '5574c107-dc85-437c-8622-24b33e33c424', 'अल-नीनो (El Nino) घटना के दौरान, प्रशांत महासागर के किस हिस्से में समुद्र की सतह का तापमान (SST) सामान्य से अधिक हो जाता है?', '[{"id":"A","text":"पश्चिमी प्रशांत (Western Pacific)","text_en":"पश्चिमी प्रशांत (Western Pacific)"},{"id":"B","text":"पूर्वी और मध्य प्रशांत (Eastern and Central Pacific)","text_en":"पूर्वी और मध्य प्रशांत (Eastern and Central Pacific)"},{"id":"C","text":"उत्तरी प्रशांत (Northern Pacific)","text_en":"उत्तरी प्रशांत (Northern Pacific)"},{"id":"D","text":"हिंद महासागर (Indian Ocean)","text_en":"हिंद महासागर (Indian Ocean)"}]', '1', '**✅ Correct Logic:** अल-नीनो में, **पूर्वी और मध्य प्रशांत** (पेरू तट के पास) का पानी गर्म हो जाता है। सामान्य स्थिति में यहाँ ठंडा पानी (हम्बोल्ट धारा) होता है।

**💡 Exam Fact:** इसका नाम ''द लिटिल बॉय'' (Child Christ) है क्योंकि यह अक्सर क्रिसमस के आसपास दिखाई देता है।

**🧠 Memory Tip:** **E**l Nino warms the **E**ast (Peru side).

**🚫 Scam Alert:** पश्चिमी प्रशांत (ऑस्ट्रेलिया/इंडोनेशिया) अल-नीनो के दौरान *ठंडा* हो जाता है, जिससे वहाँ सूखा पड़ता है।', 2, 0, 1, NULL, 'During an El Nino event, in which part of the Pacific Ocean does the Sea Surface Temperature (SST) become higher than normal?', '**✅ Correct Logic:** In El Nino, the **Eastern and Central Pacific** (near Peru coast) waters become warmer. Normally, this area has cold water (Humboldt Current).

**💡 Exam Fact:** Named ''The Little Boy'' (Child Christ) as it appears around Christmas.

**🧠 Memory Tip:** **E**l Nino warms the **E**ast.

**🚫 Scam Alert:** Western Pacific (Australia) becomes *cooler* during El Nino, causing drought there.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2a6da059-3f84-4a32-a94f-a925ae2b5b4a', '5574c107-dc85-437c-8622-24b33e33c424', 'भारतीय मानसून पर ''अल-नीनो'' का सामान्यतः क्या प्रभाव पड़ता है?', '[{"id":"A","text":"अत्यधिक वर्षा और बाढ़ (Excess rainfall and floods)","text_en":"अत्यधिक वर्षा और बाढ़ (Excess rainfall and floods)"},{"id":"B","text":"कम वर्षा और सूखा (Deficient rainfall and drought)","text_en":"कम वर्षा और सूखा (Deficient rainfall and drought)"},{"id":"C","text":"मानसून का जल्दी आगमन (Early arrival of monsoon)","text_en":"मानसून का जल्दी आगमन (Early arrival of monsoon)"},{"id":"D","text":"कोई प्रभाव नहीं (No impact)","text_en":"कोई प्रभाव नहीं (No impact)"}]', '1', '**✅ Correct Logic:** अल-नीनो आमतौर पर भारतीय मानसून को **कमजोर** करता है, जिससे **कम वर्षा और सूखा** (Drought) की स्थिति बनती है। (गर्म हवाएँ प्रशांत में ऊपर उठती हैं, जिससे हिंद महासागर के ऊपर अवतलन/sinking air होता है)।

**💡 Exam Fact:** ला-नीना (La Nina) इसका उल्टा है, जो भारत में अच्छी बारिश लाता है।

**🧠 Memory Tip:** El Nino is a **Bad Boy** for India (Drought).

**🚫 Scam Alert:** हर अल-नीनो साल सूखा नहीं होता (IOD इसे संतुलित कर सकता है), लेकिन ''सामान्य प्रभाव'' नकारात्मक ही है।', 2, 0, 2, NULL, 'What is generally the impact of ''El Nino'' on the Indian Monsoon?', '**✅ Correct Logic:** El Nino generally **weakens** the Indian Monsoon, leading to **deficient rainfall and drought**. (Warm air rises in Pacific, causing sinking air over Indian Ocean).

**💡 Exam Fact:** La Nina is the opposite, bringing good rains to India.

**🧠 Memory Tip:** El Nino is a **Bad Boy** for India.

**🚫 Scam Alert:** Not every El Nino year is a drought (IOD can offset it), but the ''general impact'' is negative.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('29fa4c70-1c2e-4331-affb-dbc8dac2501d', '5574c107-dc85-437c-8622-24b33e33c424', 'निम्नलिखित कथनों पर विचार करें:
1. ''दक्षिणी दोलन'' (Southern Oscillation) वायुमंडलीय दबाव में बदलाव से संबंधित है।
2. जब ताहिती (Tahiti) में दबाव डार्विन (Darwin) से कम होता है, तो यह अल-नीनो की स्थिति को इंगित करता है।
सही कथन चुनें:', '[{"id":"A","text":"केवल 1 (Only 1)","text_en":"केवल 1 (Only 1)"},{"id":"B","text":"केवल 2 (Only 2)","text_en":"केवल 2 (Only 2)"},{"id":"C","text":"1 और 2 दोनों (Both 1 and 2)","text_en":"1 और 2 दोनों (Both 1 and 2)"},{"id":"D","text":"ना तो 1 ना ही 2 (Neither 1 nor 2)","text_en":"ना तो 1 ना ही 2 (Neither 1 nor 2)"}]', '2', '**✅ Correct Logic:** दोनों सही हैं। दक्षिणी दोलन (SO) हिंद महासागर और प्रशांत महासागर के बीच वायुदाब का ''सी-सॉ'' (See-Saw) है। अल-नीनो में, पूर्वी प्रशांत (ताहिती) में **दबाव कम** (Low Pressure) हो जाता है और पश्चिमी प्रशांत (डार्विन, ऑस्ट्रेलिया) में दबाव बढ़ जाता है। इसे ''Negative SOI'' कहते हैं।

**💡 Exam Fact:** ENSO = El Nino + Southern Oscillation (महासागरीय + वायुमंडलीय घटना)।

**🧠 Memory Tip:** **Tahiti** (East) Low = **E**l Nino. **Darwin** (West) High = Drought in Aus/India.

**🚫 Scam Alert:** सामान्य स्थिति में ताहिती में हाई प्रेशर और डार्विन में लो प्रेशर होता है। अल-नीनो में यह उल्टा हो जाता है।', 2, 0, 3, NULL, 'Consider the following statements:
1. ''Southern Oscillation'' relates to the change in atmospheric pressure.
2. When pressure at Tahiti is lower than Darwin, it indicates an El Nino condition.
Choose the correct statement:', '**✅ Correct Logic:** Both correct. Southern Oscillation (SO) is the pressure see-saw between Indian and Pacific Oceans. In El Nino, pressure in East Pacific (Tahiti) becomes **Low**, and West Pacific (Darwin) becomes High. This is ''Negative SOI''.

**💡 Exam Fact:** ENSO = El Nino + Southern Oscillation.

**🧠 Memory Tip:** **Tahiti** Low = **E**l Nino.

**🚫 Scam Alert:** Normally Tahiti has High Pressure. In El Nino, it reverses.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ee8f4a2c-1b40-42f3-9ce8-8d64dd5ca53f', '5574c107-dc85-437c-8622-24b33e33c424', '''वॉकर सेल'' (Walker Cell) का कमजोर होना या उलटा होना किस घटना से जुड़ा है?', '[{"id":"A","text":"ला-नीना (La Nina)","text_en":"ला-नीना (La Nina)"},{"id":"B","text":"अल-नीनो (El Nino)","text_en":"अल-नीनो (El Nino)"},{"id":"C","text":"पश्चिमी विक्षोभ (Western Disturbance)","text_en":"पश्चिमी विक्षोभ (Western Disturbance)"},{"id":"D","text":"जेट स्ट्रीम (Jet Stream)","text_en":"जेट स्ट्रीम (Jet Stream)"}]', '1', '**✅ Correct Logic:** सामान्य वॉकर सेल में पश्चिमी प्रशांत (इंडोनेशिया) में हवा ऊपर उठती है और पूर्वी प्रशांत (पेरू) में नीचे आती है। **अल-नीनो** में यह सेल **कमजोर** हो जाता है या **उलट** जाता है (पेरू में हवा ऊपर उठती है)।

**💡 Exam Fact:** वॉकर सेल का नाम सर गिल्बर्ट वॉकर के नाम पर रखा गया है, जो भारत मौसम विभाग (IMD) के महानिदेशक थे।

**🧠 Memory Tip:** **Walker** gets tired and stops walking during **El Nino**.

**🚫 Scam Alert:** ला-नीना में वॉकर सेल ''मजबूत'' (Stronger) होता है, कमजोर नहीं।', 2, 0, 4, NULL, 'The weakening or reversal of the ''Walker Cell'' is associated with which phenomenon?', '**✅ Correct Logic:** Normally, Walker Cell has rising air over West Pacific (Indonesia) and sinking over East (Peru). In **El Nino**, this cell **weakens** or **reverses** (air rises over Peru).

**💡 Exam Fact:** Named after Sir Gilbert Walker, former DG of IMD.

**🧠 Memory Tip:** **Walker** gets tired during **El Nino**.

**🚫 Scam Alert:** In La Nina, Walker Cell becomes **Stronger**, not weaker.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('362a34e3-59db-4c61-ae7c-ed29d62a591a', '5574c107-dc85-437c-8622-24b33e33c424', '''अल-नीनो मोदोकी'' (El Nino Modoki) सामान्य अल-नीनो से किस प्रकार भिन्न है?', '[{"id":"A","text":"इसमें वार्मिंग केवल पेरू तट पर होती है (Warming only at Peru coast)","text_en":"इसमें वार्मिंग केवल पेरू तट पर होती है (Warming only at Peru coast)"},{"id":"B","text":"इसमें वार्मिंग मध्य प्रशांत महासागर में होती है (Warming happens in Central Pacific)","text_en":"इसमें वार्मिंग मध्य प्रशांत महासागर में होती है (Warming happens in Central Pacific)"},{"id":"C","text":"यह हमेशा मानसून के लिए अच्छा होता है (Always good for monsoon)","text_en":"यह हमेशा मानसून के लिए अच्छा होता है (Always good for monsoon)"},{"id":"D","text":"इसका संबंध अटलांटिक महासागर से है (Related to Atlantic Ocean)","text_en":"इसका संबंध अटलांटिक महासागर से है (Related to Atlantic Ocean)"}]', '1', '**✅ Correct Logic:** ''मोदोकी'' जापानी शब्द है जिसका अर्थ है ''समान लेकिन अलग''। सामान्य अल-नीनो में पूर्वी प्रशांत (पेरू) गर्म होता है, जबकि **अल-नीनो मोदोकी** में **मध्य प्रशांत** (Central Pacific) गर्म होता है और पूर्वी/पश्चिमी दोनों छोर ठंडे होते हैं।

**💡 Exam Fact:** मोदोकी भारत में सामान्य अल-नीनो की तुलना में अधिक सूखा ला सकता है क्योंकि यह वॉकर सेल को दो भागों में तोड़ देता है।

**🧠 Memory Tip:** **M**odoki is in the **M**iddle (Central Pacific).

**🚫 Scam Alert:** मोदोकी को ''हल्का'' न समझें, इसका प्रभाव कभी-कभी अधिक गंभीर होता है।', 2, 0, 5, NULL, 'How is ''El Nino Modoki'' different from a normal El Nino?', '**✅ Correct Logic:** Modoki (Japanese for ''Similar but different'') involves warming in the **Central Pacific**, while both East and West flanks are cooler. Normal El Nino warms the East.

**💡 Exam Fact:** Modoki can cause more droughts in India than normal El Nino.

**🧠 Memory Tip:** **M**odoki is in the **M**iddle (Central Pacific).

**🚫 Scam Alert:** Don''t consider Modoki milder; its impact can be severe.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f84e1658-60d9-4065-8a48-66361fd75f62', '5574c107-dc85-437c-8622-24b33e33c424', 'ला-नीना (La Nina) के संदर्भ में, पेरू तट पर क्या होता है?', '[{"id":"A","text":"अपवेलिंग (Upwelling) बंद हो जाती है।","text_en":"अपवेलिंग (Upwelling) बंद हो जाती है।"},{"id":"B","text":"अपवेलिंग और ठंडी जलधारा मजबूत हो जाती है। (Upwelling and cold current strengthens)","text_en":"अपवेलिंग और ठंडी जलधारा मजबूत हो जाती है। (Upwelling and cold current strengthens)"},{"id":"C","text":"समुद्र का तापमान असामान्य रूप से बढ़ जाता है।","text_en":"समुद्र का तापमान असामान्य रूप से बढ़ जाता है।"},{"id":"D","text":"मछली उत्पादन में भारी गिरावट आती है।","text_en":"मछली उत्पादन में भारी गिरावट आती है।"}]', '1', '**✅ Correct Logic:** ला-नीना सामान्य स्थिति का ही ''अति'' (Intense) रूप है। इसमें पेरू तट पर ठंडी हम्बोल्ट धारा और **अपवेलिंग** (नीचे से पोषक तत्व आना) **मजबूत** हो जाती है। इससे मछलियों (Anchovies) की भरमार होती है।

**💡 Exam Fact:** ला-नीना को ''द लिटिल गर्ल'' कहा जाता है।

**🧠 Memory Tip:** **La** Nina -> **La**na (To bring) -> Brings lots of fish and rain.

**🚫 Scam Alert:** अल-नीनो में अपवेलिंग रुक जाती है (मछली मर जाती है)। ला-नीना में अपवेलिंग बढ़ती है।', 2, 0, 6, NULL, 'With reference to La Nina, what happens at the Peru coast?', '**✅ Correct Logic:** La Nina is the intense version of normal conditions. The cold Humboldt current and **Upwelling** (nutrients rising) **strengthens** off Peru coast. This leads to abundant fish.

**💡 Exam Fact:** La Nina is called ''The Little Girl''.

**🧠 Memory Tip:** **La** Nina -> Brings fish and rain.

**🚫 Scam Alert:** In El Nino, upwelling stops. In La Nina, it increases.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7eb66493-6360-4704-8f81-2febad46309b', '5574c107-dc85-437c-8622-24b33e33c424', 'इंडियन ओशन डाइपोल (IOD) का ''सकारात्मक चरण'' (Positive Phase) भारतीय मानसून को कैसे प्रभावित करता है?', '[{"id":"A","text":"यह मानसून को कमजोर करता है (Weakens Monsoon)","text_en":"यह मानसून को कमजोर करता है (Weakens Monsoon)"},{"id":"B","text":"यह मानसून को मजबूत करता है और अल-नीनो के प्रभाव को कम कर सकता है (Strengthens Monsoon and can counter El Nino)","text_en":"यह मानसून को मजबूत करता है और अल-नीनो के प्रभाव को कम कर सकता है (Strengthens Monsoon and can counter El Nino)"},{"id":"C","text":"यह चक्रवातों को रोकता है (Prevents Cyclones)","text_en":"यह चक्रवातों को रोकता है (Prevents Cyclones)"},{"id":"D","text":"इसका कोई प्रभाव नहीं होता (No Impact)","text_en":"इसका कोई प्रभाव नहीं होता (No Impact)"}]', '1', '**✅ Correct Logic:** **पॉजिटिव IOD** में पश्चिमी हिंद महासागर (अफ्रीका तट) गर्म होता है और पूर्वी हिंद महासागर (इंडोनेशिया) ठंडा। इससे भारत की ओर नमी वाली हवाएँ आती हैं, जो **मानसून को मजबूत** करती हैं। यह कभी-कभी अल-नीनो के नकारात्मक प्रभाव को भी बेअसर (Counter) कर देता है (जैसे 2019 में)।

**💡 Exam Fact:** इसे ''भारतीय नीनो'' (Indian Nino) भी कहते हैं।

**🧠 Memory Tip:** **Positive** is **Good** for India (Rain).

**🚫 Scam Alert:** नेगेटिव IOD मानसून के लिए बुरा होता है। अल-नीनो बुरा है, लेकिन पॉजिटिव IOD अच्छा है।', 2, 0, 7, NULL, 'How does the ''Positive Phase'' of Indian Ocean Dipole (IOD) affect the Indian Monsoon?', '**✅ Correct Logic:** In **Positive IOD**, Western Indian Ocean (Africa) is warmer than Eastern (Indonesia). This pushes moisture towards India, **strengthening the Monsoon**. It can even **counter** El Nino (e.g., 2019).

**💡 Exam Fact:** Also called ''Indian Nino''.

**🧠 Memory Tip:** **Positive** is **Good** for India.

**🚫 Scam Alert:** Negative IOD is bad. Positive IOD is good.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cbb11cf7-c803-4d03-8a90-7e1daf19c8ba', '5574c107-dc85-437c-8622-24b33e33c424', 'प्रशांत महासागर में ''थर्मोकलाइन'' (Thermocline) की गहराई पर अल-नीनो का क्या प्रभाव पड़ता है?', '[{"id":"A","text":"थर्मोकलाइन ऊपर उठ जाती है (Thermocline rises)","text_en":"थर्मोकलाइन ऊपर उठ जाती है (Thermocline rises)"},{"id":"B","text":"थर्मोकलाइन गहरी हो जाती है (Thermocline deepens/flattened)","text_en":"थर्मोकलाइन गहरी हो जाती है (Thermocline deepens/flattened)"},{"id":"C","text":"थर्मोकलाइन गायब हो जाती है (Thermocline disappears)","text_en":"थर्मोकलाइन गायब हो जाती है (Thermocline disappears)"},{"id":"D","text":"कोई बदलाव नहीं (No change)","text_en":"कोई बदलाव नहीं (No change)"}]', '1', '**✅ Correct Logic:** सामान्य स्थिति में पूर्वी प्रशांत (पेरू) में थर्मोकलाइन (गर्म और ठंडे पानी के बीच की परत) सतह के पास होती है (उथली)। **अल-नीनो** में, गर्म पानी का ढेर जमा होने से थर्मोकलाइन **गहरी** (Deepens/Flattened) हो जाती है, जिससे ठंडे पानी का ऊपर आना (Upwelling) रुक जाता है।

**💡 Exam Fact:** यही कारण है कि मछलियों को पोषक तत्व नहीं मिलते।

**🧠 Memory Tip:** El Nino pushes warm water down -> Thermocline goes **Down/Deep**.

**🚫 Scam Alert:** ला-नीना में थर्मोकलाइन ऊपर (उथली) आती है।', 2, 0, 8, NULL, 'What is the effect of El Nino on the depth of the ''Thermocline'' in the Eastern Pacific?', '**✅ Correct Logic:** Normally, Thermocline is shallow in East Pacific. In **El Nino**, the pile-up of warm water pushes the Thermocline **Deeper**, stopping the cold nutrient-rich water from rising (Upwelling).

**💡 Exam Fact:** This is why fish die (no nutrients).

**🧠 Memory Tip:** El Nino pushes warm water down -> Thermocline goes **Deep**.

**🚫 Scam Alert:** In La Nina, Thermocline rises (shallower).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a5d2368c-7f50-4485-8696-fcd48a2c5929', '5574c107-dc85-437c-8622-24b33e33c424', 'मेडेन-जूलियन ऑसिलेशन (MJO) जब अपने सक्रिय चरण (Active Phase) में हिंद महासागर के ऊपर होता है, तो इसका परिणाम क्या होता है?', '[{"id":"A","text":"भारत में वर्षा बढ़ती है (Rainfall increases in India)","text_en":"भारत में वर्षा बढ़ती है (Rainfall increases in India)"},{"id":"B","text":"भारत में सूखा पड़ता है (Drought in India)","text_en":"भारत में सूखा पड़ता है (Drought in India)"},{"id":"C","text":"मानसून में देरी होती है (Delay in Monsoon)","text_en":"मानसून में देरी होती है (Delay in Monsoon)"},{"id":"D","text":"प्रशांत महासागर में चक्रवात (Cyclones in Pacific)","text_en":"प्रशांत महासागर में चक्रवात (Cyclones in Pacific)"}]', '0', '**✅ Correct Logic:** MJO एक चलता-फिरता बादलों का समूह है (Moving pulse of clouds) जो भूमध्य रेखा के पास पूर्व की ओर बढ़ता है। जब यह **हिंद महासागर** के ऊपर होता है, तो यह संवहन (Convection) बढ़ाता है और **भारत में वर्षा** को बढ़ावा देता है।

**💡 Exam Fact:** MJO की चक्र अवधि 30-60 दिन होती है।

**🧠 Memory Tip:** **MJ** (Michael Jackson) dancing over India -> Rain starts.

**🚫 Scam Alert:** यदि MJO प्रशांत में चला जाता है, तो भारत में वर्षा कम हो सकती है (Suppressed phase)।', 2, 0, 9, NULL, 'When the Madden-Julian Oscillation (MJO) is in its Active Phase over the Indian Ocean, what is the result?', '**✅ Correct Logic:** MJO is a moving pulse of clouds/rainfall that travels eastward along the equator. When over the **Indian Ocean**, it enhances convection and **increases rainfall** in India.

**💡 Exam Fact:** MJO cycle is 30-60 days.

**🧠 Memory Tip:** **MJ** dancing over India -> Rain.

**🚫 Scam Alert:** If MJO moves to Pacific, rainfall in India might be suppressed.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2e5674ec-6620-42af-bbc7-11116d11d3dd', '5574c107-dc85-437c-8622-24b33e33c424', 'निम्नलिखित जलवायु घटनाओं को उनके अर्थ/प्रभाव से सुमेलित करें (Match the following climate phenomena with their meaning/effect):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **अल-नीनो**: पेरू तट पर गर्म पानी का आना। -> (1)-(a)
* **ला-नीना**: ट्रेड विंड्स (Trade Winds) बहुत तेज हो जाती हैं, गर्म पानी को एशिया की ओर धकेलती हैं। -> (2)-(b)
* **वॉकर सेल**: भूमध्य रेखा पर वायुमंडल का क्षैतिज (पूर्व-पश्चिम) परिसंचरण। -> (3)-(c)
* **हम्बोल्ट धारा**: सामान्य स्थिति में पेरू तट पर बहने वाली ठंडी धारा (पेरू धारा)। -> (4)-(d)

**💡 Exam Fact:** हम्बोल्ट धारा दुनिया के सबसे उत्पादक समुद्री पारिस्थितिक तंत्रों में से एक है।

**🧠 Memory Tip:** Straight forward definitions. **Humboldt** is cold. **El Nino** is warm.

**🚫 Scam Alert:** वॉकर सेल (पूर्व-पश्चिम) और हैडली सेल (उत्तर-दक्षिण) में अंतर याद रखें।', 2, 0, 10, NULL, 'Match the following climate phenomena with their meaning/effect:', '**✅ Correct Matching:**
* **El Nino**: Warm water off Peru. -> (1)-(a)
* **La Nina**: Trade Winds strengthen excessively. -> (2)-(b)
* **Walker Cell**: East-West atmospheric circulation. -> (3)-(c)
* **Humboldt Current**: Cold current off Peru (Normal). -> (4)-(d)

**💡 Exam Fact:** Humboldt current supports rich fisheries.

**🧠 Memory Tip:** **Humboldt** is cold. **El Nino** is warm.

**🚫 Scam Alert:** Walker Cell (East-West) vs Hadley Cell (North-South).', 60, 'matching', '[{"id":"(1)","label":"अल-नीनो (El Nino)","match":"पेरू तट पर गर्म जलधारा (Warm current off Peru coast)","matchId":"(a)"},{"id":"(2)","label":"ला-नीना (La Nina)","match":"व्यापारिक पवनों का मजबूत होना (Strengthening of Trade Winds)","matchId":"(b)"},{"id":"(3)","label":"वॉकर सेल (Walker Cell)","match":"पूर्व-पश्चिम वायुमंडलीय परिसंचरण (East-West Atmospheric Circulation)","matchId":"(c)"},{"id":"(4)","label":"हम्बोल्ट धारा (Humboldt Current)","match":"पेरू तट पर ठंडी जलधारा (Cold current off Peru coast)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5ec599e1-a794-402f-971a-d4765bdbbafb', '54876285-daa5-4fb3-add8-25e1da0d24d0', 'प्राचीन भारत में ''श्रेणी'' (Shreni/Guilds) का मुख्य कार्य क्या था?', '[{"id":"A","text":"केवल धार्मिक अनुष्ठान करना (Performing only religious rituals)","text_en":"केवल धार्मिक अनुष्ठान करना (Performing only religious rituals)"},{"id":"B","text":"व्यापारियों और कारीगरों के हितों की रक्षा और मानक निर्धारण (Protecting interests of traders/artisans and setting standards)","text_en":"व्यापारियों और कारीगरों के हितों की रक्षा और मानक निर्धारण (Protecting interests of traders/artisans and setting standards)"},{"id":"C","text":"राजा के लिए सेना भर्ती करना (Recruiting army for the King)","text_en":"राजा के लिए सेना भर्ती करना (Recruiting army for the King)"},{"id":"D","text":"विदेश नीति तय करना (Deciding foreign policy)","text_en":"विदेश नीति तय करना (Deciding foreign policy)"}]', '1', '**✅ Correct Logic:** श्रेणी एक ही पेशे वाले लोगों (व्यापारी/कारीगर) का संगठन था। यह अपने सदस्यों के लिए नियम बनाता था, गुणवत्ता (Quality) नियंत्रित करता था, और यहां तक कि अपने सिक्के भी जारी करता था। यह आधुनिक ट्रेड यूनियन और बैंक का मिश्रण था।

**💡 Exam Fact:** विदिशा और मंदसौर के अभिलेखों में श्रेणियों द्वारा मंदिर निर्माण के लिए दान देने का उल्लेख है।

**🧠 Memory Tip:** Shreni = Series/Group = **G**uild.

**🚫 Scam Alert:** श्रेणियों के पास अपनी छोटी सेना (श्रेणी-बल) होती थी, लेकिन उनका ''मुख्य कार्य'' व्यापारिक नियमन था।', 2, 0, 1, NULL, 'What was the main function of ''Shreni'' (Guilds) in ancient India?', '**✅ Correct Logic:** Shreni was an organization of people of the same profession. It made rules for members, controlled quality, and even issued coins. It was a mix of modern Trade Union and Bank.

**💡 Exam Fact:** Inscriptions at Vidisha and Mandsaur mention Shrenis donating for temple construction.

**🧠 Memory Tip:** Shreni = Series/Group = **G**uild.

**🚫 Scam Alert:** Shrenis had small militia (Shreni-bala), but their ''Main Function'' was trade regulation.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('40a453fe-5dcc-484b-a237-904d1cee48c4', '54876285-daa5-4fb3-add8-25e1da0d24d0', 'प्राचीन भारतीय गणितज्ञ जिसने पहली बार ''शून्य'' (Zero) को एक संख्या के रूप में मान्यता दी और उसके गणना नियम बताए?', '[{"id":"A","text":"आर्यभट्ट (Aryabhata)","text_en":"आर्यभट्ट (Aryabhata)"},{"id":"B","text":"ब्रह्मगुप्त (Brahmagupta)","text_en":"ब्रह्मगुप्त (Brahmagupta)"},{"id":"C","text":"वराहमिहिर (Varahamihira)","text_en":"वराहमिहिर (Varahamihira)"},{"id":"D","text":"भास्कराचार्य (Bhaskaracharya)","text_en":"भास्कराचार्य (Bhaskaracharya)"}]', '1', '**✅ Correct Logic:** यद्यपि आर्यभट्ट ने शून्य का प्रयोग किया, लेकिन **ब्रह्मगुप्त** (7वीं सदी) ने अपनी पुस्तक ''ब्रह्मस्फुटसिद्धांत'' में पहली बार शून्य (0) के साथ जोड़, घटाव और गुणा के स्पष्ट नियम दिए। उन्होंने इसे एक संख्या (Number) माना।

**💡 Exam Fact:** ब्रह्मगुप्त ने ही गुरुत्वाकर्षण के नियम का भी पूर्व-संकेत दिया था।

**🧠 Memory Tip:** **B**rahmagupta gave rules for **B**ig Zero.

**🚫 Scam Alert:** आर्यभट्ट ने ''स्थान मान'' (Place Value) में शून्य का उपयोग किया, लेकिन गणितीय संक्रियाओं (Operations) के नियम ब्रह्मगुप्त ने दिए।', 2, 0, 2, NULL, 'Ancient Indian mathematician who first recognized ''Zero'' as a number and gave rules for its calculation?', '**✅ Correct Logic:** Although Aryabhata used Zero, **Brahmagupta** (7th Century) in his ''Brahmasphutasiddhanta'' first gave clear rules for addition, subtraction, and multiplication with Zero. He treated it as a Number.

**💡 Exam Fact:** Brahmagupta also hinted at the law of gravity.

**🧠 Memory Tip:** **B**rahmagupta gave rules for **B**ig Zero.

**🚫 Scam Alert:** Aryabhata used Zero in Place Value, but Brahmagupta gave rules for mathematical operations.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1e250430-16af-4b6b-85f8-2a14a81cf2be', '54876285-daa5-4fb3-add8-25e1da0d24d0', 'मध्यकालीन भारत में ''इक्ता'' (Iqta) व्यवस्था का मुख्य उद्देश्य क्या था?', '[{"id":"A","text":"किसानों को भूमि का मालिकाना हक देना (Giving land ownership to farmers)","text_en":"किसानों को भूमि का मालिकाना हक देना (Giving land ownership to farmers)"},{"id":"B","text":"सैनिक और असैनिक अधिकारियों को वेतन के बदले भूमि राजस्व का अधिकार देना (Giving land revenue rights to military/civil officers instead of salary)","text_en":"सैनिक और असैनिक अधिकारियों को वेतन के बदले भूमि राजस्व का अधिकार देना (Giving land revenue rights to military/civil officers instead of salary)"},{"id":"C","text":"धार्मिक कार्यों के लिए भूमि दान (Land grant for religious works)","text_en":"धार्मिक कार्यों के लिए भूमि दान (Land grant for religious works)"},{"id":"D","text":"सिंचाई कर वसूलना (Collecting irrigation tax)","text_en":"सिंचाई कर वसूलना (Collecting irrigation tax)"}]', '1', '**✅ Correct Logic:** इल्तुतमिश ने भारत में ''इक्ता'' प्रणाली को संस्थागत रूप दिया। इसमें अधिकारियों (इक्तादार) को नकद वेतन के बदले एक क्षेत्र (इक्ता) का राजस्व वसूलने का अधिकार दिया जाता था, जिससे वे अपना और अपनी सेना का खर्च चलाते थे।

**💡 Exam Fact:** यह भूमि का स्वामित्व (Ownership) नहीं, बल्कि केवल राजस्व (Revenue) का हस्तांतरण था।

**🧠 Memory Tip:** Iqta = **I**ncome from Land (Instead of Salary).

**🚫 Scam Alert:** यह सामंतवाद जैसा लग सकता है, लेकिन इक्तादार का पद वंशानुगत (Hereditary) नहीं था (शुरुआत में)। उनका तबादला होता रहता था।', 2, 0, 3, NULL, 'What was the main objective of the ''Iqta'' system in Medieval India?', '**✅ Correct Logic:** Iltutmish institutionalized ''Iqta'' in India. Officers (Iqtadars) were given rights to collect revenue from a region (Iqta) instead of cash salary, to maintain themselves and their troops.

**💡 Exam Fact:** It was transfer of Revenue, not Ownership.

**🧠 Memory Tip:** Iqta = **I**ncome from Land (Instead of Salary).

**🚫 Scam Alert:** Looks like Feudalism, but Iqtadar post was NOT hereditary (initially) and transferable.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('82ff4c76-896c-4206-b06d-34fb9b270344', '54876285-daa5-4fb3-add8-25e1da0d24d0', 'कथन (A): प्राचीन भारत में ''सामंतवाद'' (Feudalism) का उदय भूमि अनुदान (Land Grants) प्रथा से हुआ।
कारण (R): सातवाहन और गुप्त काल में ब्राह्मणों और अधिकारियों को कर-मुक्त भूमि दी गई, जिससे वे स्वतंत्र शक्ति बन गए।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic:** आर.एस. शर्मा के अनुसार, भारतीय सामंतवाद की जड़ें भूमि अनुदान में हैं। जब राजा ने दानग्रहीता को प्रशासनिक और न्यायिक अधिकार भी दे दिए, तो केंद्रीय सत्ता कमजोर हुई और स्थानीय सामंत शक्तिशाली हो गए।

**💡 Exam Fact:** सबसे पहला भूमि अनुदान अभिलेख (नानाघाट) सातवाहनों का है।

**🧠 Memory Tip:** Land Grant -> Power Grant -> Feudal Lord.

**🚫 Scam Alert:** दोनों कथन सही हैं और R प्रक्रिया (Process) समझाता है।', 2, 0, 4, NULL, 'Assertion (A): ''Feudalism'' in ancient India emerged from the practice of Land Grants.
Reason (R): In Satavahana and Gupta periods, tax-free land was given to Brahmins and officers, making them independent powers.
Select the correct option:', '**✅ Correct Logic:** According to R.S. Sharma, Indian Feudalism is rooted in Land Grants. When kings gave administrative and judicial rights to grantees, central power weakened and local lords became powerful.

**💡 Exam Fact:** First land grant inscription (Nanaghat) belongs to Satavahanas.

**🧠 Memory Tip:** Land Grant -> Power Grant -> Feudal Lord.

**🚫 Scam Alert:** Both are true and R explains the process.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f042e75e-547c-410f-9e4d-144fa155c2d2', '54876285-daa5-4fb3-add8-25e1da0d24d0', 'प्राचीन/मध्यकालीन शब्दों को उनके अर्थ से सुमेलित करें (Match the Ancient/Medieval terms with their meanings):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(c), (3)-(d), (4)-(a)","text_en":"(1)-(b), (2)-(c), (3)-(d), (4)-(a)"},{"id":"D","text":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)","text_en":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)"}]', '0', '**✅ Correct Logic:**
* **विष्टि:** गुप्त काल में प्रचलित ''बेगार'' (बिना वेतन के काम)।
* **भाग:** भू-राजस्व (Land Tax), अक्सर 1/6।
* **अग्रहार:** शिक्षा और धर्म के लिए दी गई भूमि।
* **सार्थवाह:** व्यापारियों का प्रमुख।

**💡 Exam Fact:** जूनागढ़ अभिलेख में कहा गया है कि सुदर्शन झील की मरम्मत ''विष्टि'' (बेगार) के बिना की गई थी।

**🧠 Memory Tip:** Vishti = Waste (Unpaid work). Sarthavaha = Saath (Together) travel leader.

**🚫 Scam Alert:** विष्टि बहुत महत्वपूर्ण शब्द है, इसे याद रखें।', 2, 0, 5, NULL, 'Match the Ancient/Medieval terms with their meanings:', '**✅ Correct Logic:**
* **Vishti:** ''Forced Labor'' (Unpaid) prevalent in Gupta period.
* **Bhaga:** Land Tax, usually 1/6.
* **Agrahara:** Land given for education/religion.
* **Sarthavaha:** Caravan leader.

**💡 Exam Fact:** Junagadh inscription states Sudarshan Lake was repaired without ''Vishti''.

**🧠 Memory Tip:** Vishti = Waste (Unpaid work). Sarthavaha = Saath (Together) travel leader.

**🚫 Scam Alert:** Vishti is a very important term.', 60, 'matching', '[{"id":"(1)","label":"विष्टि (Vishti)","match":"बेगार / बलात श्रम (Forced Labor)","matchId":"(b)"},{"id":"(2)","label":"भाग (Bhaga)","match":"राजा का उपज में हिस्सा (King''s share in produce)","matchId":"(a)"},{"id":"(3)","label":"अग्रहार (Agrahara)","match":"ब्राह्मणों को दी गई कर-मुक्त भूमि (Tax-free land to Brahmins)","matchId":"(d)"},{"id":"(4)","label":"सार्थवाह (Sarthavaha)","match":"व्यापारी काफिले का नेता (Leader of merchant caravan)","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7c681e97-7991-4fe9-ab52-795e607c72a4', '54876285-daa5-4fb3-add8-25e1da0d24d0', 'दक्षिण भारत में ''मणिग्रामम्'' और ''नानादेशी'' क्या थे?', '[{"id":"A","text":"प्रसिद्ध मंदिर (Famous Temples)","text_en":"प्रसिद्ध मंदिर (Famous Temples)"},{"id":"B","text":"व्यापारिक संघ / गिल्ड (Trade Guilds)","text_en":"व्यापारिक संघ / गिल्ड (Trade Guilds)"},{"id":"C","text":"सैन्य टुकड़ियां (Military Troops)","text_en":"सैन्य टुकड़ियां (Military Troops)"},{"id":"D","text":"प्रशासनिक इकाइयां (Administrative Units)","text_en":"प्रशासनिक इकाइयां (Administrative Units)"}]', '1', '**✅ Correct Logic:** पल्लव और चोल काल में दक्षिण भारत में शक्तिशाली व्यापारिक श्रेणियां (Guilds) थीं। ''मणिग्रामम्'' आंतरिक व्यापार और ''नानादेशी'' (विभिन्न देशों के) विदेशी व्यापार करते थे। ''अय्यवोल'' (Aihole) 500 स्वामियों का प्रसिद्ध संघ था।

**💡 Exam Fact:** इनके पास अपने निजी सैनिक और जहाज होते थे।

**🧠 Memory Tip:** Nana-deshi = Many Countries = Foreign Trade Guild.

**🚫 Scam Alert:** नाम से ''ग्राम'' (Village) लगता है, लेकिन ये ''व्यापारिक संघ'' थे।', 2, 0, 6, NULL, 'What were ''Manigramam'' and ''Nanadeshi'' in South India?', '**✅ Correct Logic:** In Pallava/Chola times, South India had powerful Trade Guilds. ''Manigramam'' handled internal trade, ''Nanadeshi'' handled foreign trade. ''Ayyavole'' was a famous guild of 500 swamis.

**💡 Exam Fact:** They had their own private armies and ships.

**🧠 Memory Tip:** Nana-deshi = Many Countries = Foreign Trade Guild.

**🚫 Scam Alert:** Name sounds like ''Gram'' (Village), but they were ''Trade Guilds''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dc394ef2-309f-4989-8613-15c7e4f6006b', '54876285-daa5-4fb3-add8-25e1da0d24d0', 'मध्यकाल में ''भक्ति आंदोलन'' का सबसे महत्वपूर्ण सामाजिक प्रभाव क्या था?', '[{"id":"A","text":"संस्कृत भाषा का पुनरुत्थान (Revival of Sanskrit)","text_en":"संस्कृत भाषा का पुनरुत्थान (Revival of Sanskrit)"},{"id":"B","text":"क्षेत्रीय भाषाओं का विकास और जाति-भेद में कमी (Development of Regional languages and reduction in Caste distinctions)","text_en":"क्षेत्रीय भाषाओं का विकास और जाति-भेद में कमी (Development of Regional languages and reduction in Caste distinctions)"},{"id":"C","text":"मंदिर निर्माण में वृद्धि (Increase in temple construction)","text_en":"मंदिर निर्माण में वृद्धि (Increase in temple construction)"},{"id":"D","text":"विदेशी आक्रमणों का प्रतिरोध (Resistance to foreign invasions)","text_en":"विदेशी आक्रमणों का प्रतिरोध (Resistance to foreign invasions)"}]', '1', '**✅ Correct Logic:** भक्ति संतों (कबीर, नानक, तुकाराम) ने जनभाषा (Vernaculars) में उपदेश दिए और जाति व्यवस्था पर प्रहार किया। उन्होंने ईश्वर के सामने सबकी समानता (Equality) पर जोर दिया।

**💡 Exam Fact:** कबीर ने कहा: "जाति-पांति पूछै नहिं कोई, हरि को भजै सो हरि का होई।"

**🧠 Memory Tip:** Bhakti = Love = Equality + Local Language.

**🚫 Scam Alert:** संस्कृत का विकास गुप्त काल में हुआ, भक्ति काल ''लोक भाषाओं'' (Vernaculars) का स्वर्ण युग था।', 2, 0, 7, NULL, 'What was the most important social impact of the ''Bhakti Movement'' in the medieval period?', '**✅ Correct Logic:** Bhakti saints (Kabir, Nanak, Tukaram) preached in Vernaculars and attacked the Caste system. They emphasized Equality before God.

**💡 Exam Fact:** Kabir said: "Jati-panti puchai nahi koi..." (No one asks caste, he who worships God is God''s).

**🧠 Memory Tip:** Bhakti = Love = Equality + Local Language.

**🚫 Scam Alert:** Sanskrit revival was Gupta age; Bhakti age was Golden Age of ''Vernaculars''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('03e7fcc1-356b-4d7b-ad20-3979ac40ae6e', '54876285-daa5-4fb3-add8-25e1da0d24d0', 'प्राचीन भारत में ''सती प्रथा'' का प्रथम अभिलेखीय प्रमाण (Epigraphic Evidence) कहाँ से मिलता है?', '[{"id":"A","text":"प्रयाग प्रशस्ति (Prayag Prashasti)","text_en":"प्रयाग प्रशस्ति (Prayag Prashasti)"},{"id":"B","text":"एरण अभिलेख (Eran Inscription)","text_en":"एरण अभिलेख (Eran Inscription)"},{"id":"C","text":"जूनागढ़ अभिलेख (Junagadh Inscription)","text_en":"जूनागढ़ अभिलेख (Junagadh Inscription)"},{"id":"D","text":"नासिक अभिलेख (Nasik Inscription)","text_en":"नासिक अभिलेख (Nasik Inscription)"}]', '1', '**✅ Correct Logic:** 510 ई. का ''एरण अभिलेख'' (भानुगुप्त का) सती प्रथा का पहला लिखित पुरातात्विक प्रमाण है। इसमें गोपराज नामक सेनापति की पत्नी के सती होने का उल्लेख है।

**💡 Exam Fact:** यह मध्य प्रदेश के सागर जिले में स्थित है।

**🧠 Memory Tip:** Eran = **E**rror of Society (Sati).

**🚫 Scam Alert:** साहित्य में (महाभारत आदि) उल्लेख पहले से है, लेकिन ''अभिलेखीय'' (Inscriptional) प्रमाण एरण है।', 2, 0, 8, NULL, 'Where is the first Epigraphic Evidence of ''Sati Pratha'' found in ancient India?', '**✅ Correct Logic:** ''Eran Inscription'' (of Bhanugupta) dated 510 AD is the first written archaeological proof of Sati. It mentions the wife of general Goparaj committing Sati.

**💡 Exam Fact:** Located in Sagar district, MP.

**🧠 Memory Tip:** Eran = **E**rror of Society (Sati).

**🚫 Scam Alert:** Literature mentions it earlier, but ''Epigraphic'' evidence is Eran.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a04d10cc-c21d-491a-933b-de6e881ec586', '54876285-daa5-4fb3-add8-25e1da0d24d0', 'मध्यकालीन भारत में ''जजिया'' (Jizya) क्या था?', '[{"id":"A","text":"व्यापार कर (Trade Tax)","text_en":"व्यापार कर (Trade Tax)"},{"id":"B","text":"गैर-मुसलमानों (जिम्मियों) से लिया जाने वाला सुरक्षा कर (Protection tax collected from Non-Muslims/Dhimmis)","text_en":"गैर-मुसलमानों (जिम्मियों) से लिया जाने वाला सुरक्षा कर (Protection tax collected from Non-Muslims/Dhimmis)"},{"id":"C","text":"सिंचाई कर (Irrigation Tax)","text_en":"सिंचाई कर (Irrigation Tax)"},{"id":"D","text":"युद्ध की लूट (War Booty)","text_en":"युद्ध की लूट (War Booty)"}]', '1', '**✅ Correct Logic:** जजिया एक धार्मिक कर था जो इस्लामी राज्य में गैर-मुसलमानों (Dhimmi) से उनकी जान-माल की सुरक्षा के बदले लिया जाता था। बदले में उन्हें सैन्य सेवा से छूट मिलती थी।

**💡 Exam Fact:** अकबर ने 1564 में जजिया समाप्त किया, लेकिन औरंगजेब ने 1679 में पुनः लगा दिया।

**🧠 Memory Tip:** Jizya = Tax on being Just you (Non-Muslim).

**🚫 Scam Alert:** खम्स (Khams) युद्ध की लूट थी। जजिया ''धार्मिक सुरक्षा कर'' था।', 2, 0, 9, NULL, 'What was ''Jizya'' in Medieval India?', '**✅ Correct Logic:** Jizya was a religious tax collected from Non-Muslims (Dhimmis) in an Islamic state in return for protection of life and property. In return, they were exempt from military service.

**💡 Exam Fact:** Akbar abolished it in 1564, but Aurangzeb reimposed it in 1679.

**🧠 Memory Tip:** Jizya = Tax on being Just you (Non-Muslim).

**🚫 Scam Alert:** Khams was War Booty. Jizya was ''Religious Protection Tax''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('04759aba-7e6b-4e75-aa6a-1d9a56978616', '54876285-daa5-4fb3-add8-25e1da0d24d0', 'विजयनगर साम्राज्य की विशेष ''नायंकार'' (Nayankara) व्यवस्था किससे संबंधित थी?', '[{"id":"A","text":"नौसेना (Navy)","text_en":"नौसेना (Navy)"},{"id":"B","text":"न्याय विभाग (Justice Department)","text_en":"न्याय विभाग (Justice Department)"},{"id":"C","text":"प्रांतीय प्रशासन और सैन्य सामंत (Provincial Administration and Military Feudatories)","text_en":"प्रांतीय प्रशासन और सैन्य सामंत (Provincial Administration and Military Feudatories)"},{"id":"D","text":"मंदिर प्रबंधन (Temple Management)","text_en":"मंदिर प्रबंधन (Temple Management)"}]', '2', '**✅ Correct Logic:** नायंकार व्यवस्था दिल्ली सल्तनत की ''इक्ता'' व्यवस्था के समान थी। राजा ''अमर-नायक'' (सैन्य प्रमुख) को भूमि देता था, जो बदले में एक निश्चित सेना रखता था और राजस्व राजा को देता था।

**💡 Exam Fact:** यही व्यवस्था बाद में विजयनगर के पतन और ''पॉलीगारों'' (Poligars) के उदय का कारण बनी।

**🧠 Memory Tip:** Nayak = Leader/Army Chief. Nayankara = Rule by Chiefs.

**🚫 Scam Alert:** ''न्याय'' शब्द से कन्फ्यूज न हों। यह ''नायक'' (Leader) से बना है।', 2, 0, 10, NULL, 'The special ''Nayankara'' system of Vijayanagara Empire was related to?', '**✅ Correct Logic:** Nayankara system was similar to ''Iqta'' of Delhi Sultanate. The King gave land to ''Amara-Nayakas'' (Military Chiefs), who in return maintained a fixed army and paid revenue.

**💡 Exam Fact:** This system later led to the fall of Vijayanagara and rise of ''Poligars''.

**🧠 Memory Tip:** Nayak = Leader/Army Chief. Nayankara = Rule by Chiefs.

**🚫 Scam Alert:** Don''t confuse with ''Nyaya'' (Justice). It comes from ''Nayak'' (Leader).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1eb271be-a251-4cff-827d-d33abbfb3b7f', '236e9574-e114-4b26-b1d1-63356903da51', 'मौर्य प्रशासन में ''सप्तांग सिद्धांत'' (Saptanga Theory) का प्रतिपादन किसने किया था?', '[{"id":"A","text":"मेगस्थनीज (Megasthenes)","text_en":"मेगस्थनीज (Megasthenes)"},{"id":"B","text":"कौटिल्य (Kautilya)","text_en":"कौटिल्य (Kautilya)"},{"id":"C","text":"अशोक (Ashoka)","text_en":"अशोक (Ashoka)"},{"id":"D","text":"विशाखदत्त (Vishakhadatta)","text_en":"विशाखदत्त (Vishakhadatta)"}]', '1', '**✅ Correct Logic:** कौटिल्य (चाणक्य) ने ''अर्थशास्त्र'' में राज्य के 7 अंग बताए: 1. स्वामी (राजा), 2. अमात्य (मंत्री), 3. जनपद (क्षेत्र/जनता), 4. दुर्ग (किला), 5. कोष (खजाना), 6. दण्ड (सेना), 7. मित्र (दोस्त)। यह राज्य की जैविक अवधारणा (Organic Theory) है।

**💡 Exam Fact:** कौटिल्य ने ''स्वामी'' (राजा) को शीर्ष स्थान दिया।

**🧠 Memory Tip:** 7 Limbs of Body = 7 Limbs of State (Saptanga).

**🚫 Scam Alert:** मेगस्थनीज ने ''7 जातियों'' का वर्णन किया, ''7 अंगों'' का नहीं।', 2, 0, 1, NULL, 'Who propounded the ''Saptanga Theory'' in Mauryan administration?', '**✅ Correct Logic:** Kautilya (Chanakya) in ''Arthashastra'' described 7 limbs of state: 1. Swami (King), 2. Amatya (Minister), 3. Janapada (Territory), 4. Durga (Fort), 5. Kosha (Treasury), 6. Danda (Army), 7. Mitra (Ally). This is Organic Theory.

**💡 Exam Fact:** Kautilya gave top position to ''Swami''.

**🧠 Memory Tip:** 7 Limbs of Body = 7 Limbs of State (Saptanga).

**🚫 Scam Alert:** Megasthenes described ''7 Castes'', not ''7 Limbs''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d38289fe-d813-45bb-8c1b-6e43bd84f270', '236e9574-e114-4b26-b1d1-63356903da51', 'चोल साम्राज्य अपनी किस विशिष्ट प्रशासनिक व्यवस्था के लिए प्रसिद्ध था?', '[{"id":"A","text":"मजबूत घुड़सवार सेना (Strong Cavalry)","text_en":"मजबूत घुड़सवार सेना (Strong Cavalry)"},{"id":"B","text":"स्थानीय स्वशासन / ग्राम स्वायत्तता (Local Self-Government / Village Autonomy)","text_en":"स्थानीय स्वशासन / ग्राम स्वायत्तता (Local Self-Government / Village Autonomy)"},{"id":"C","text":"केंद्रीय गुप्तचर व्यवस्था (Central Spy System)","text_en":"केंद्रीय गुप्तचर व्यवस्था (Central Spy System)"},{"id":"D","text":"बाजार नियंत्रण (Market Control)","text_en":"बाजार नियंत्रण (Market Control)"}]', '1', '**✅ Correct Logic:** चोल प्रशासन की सबसे बड़ी विशेषता ''उर'' और ''सभा'' (ग्राम सभाएं) थीं। ''उत्तरमेरूर अभिलेख'' में चुनाव प्रणाली (Kudavolai - लॉटरी सिस्टम) और ग्राम प्रशासन का विस्तृत वर्णन है। यह पंचायती राज का प्राचीन रूप था।

**💡 Exam Fact:** चोलों के पास शक्तिशाली नौसेना भी थी, लेकिन ''स्थानीय स्वशासन'' (Local Self Govt) उनका ट्रेडमार्क है।

**🧠 Memory Tip:** Chola = **C**ommunity Rule (Village).

**🚫 Scam Alert:** बाजार नियंत्रण अलाउद्दीन खिलजी का है। चोल = ग्राम सभा।', 2, 0, 2, NULL, 'The Chola Empire was famous for which specific administrative system?', '**✅ Correct Logic:** The unique feature of Chola administration was ''Ur'' and ''Sabha'' (Village Assemblies). ''Uttaramerur Inscription'' details the election system (Kudavolai - Lottery) and village admin. It was ancient Panchayati Raj.

**💡 Exam Fact:** Cholas also had strong Navy, but ''Local Self Govt'' is their trademark.

**🧠 Memory Tip:** Chola = **C**ommunity Rule (Village).

**🚫 Scam Alert:** Market control is Alauddin Khilji. Chola = Village Assembly.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('51b7a78e-3836-4fbb-9594-ac7c3735d5dd', '236e9574-e114-4b26-b1d1-63356903da51', 'मुगल प्रशासन में ''मनसबदारी प्रथा'' (Mansabdari System) किसने शुरू की थी?', '[{"id":"A","text":"बाबर (Babur)","text_en":"बाबर (Babur)"},{"id":"B","text":"शेरशाह सूरी (Sher Shah Suri)","text_en":"शेरशाह सूरी (Sher Shah Suri)"},{"id":"C","text":"अकबर (Akbar)","text_en":"अकबर (Akbar)"},{"id":"D","text":"औरंगजेब (Aurangzeb)","text_en":"औरंगजेब (Aurangzeb)"}]', '2', '**✅ Correct Logic:** अकबर ने 1571 में मनसबदारी व्यवस्था शुरू की। यह मंगोलों की दशमलव प्रणाली पर आधारित थी। हर अधिकारी को एक ''मनसब'' (Rank) दिया जाता था जो उसका वेतन और सैन्य दायित्व (जात और सवार) तय करता था।

**💡 Exam Fact:** ''जात'' (Zat) व्यक्तिगत पद था, ''सवार'' (Sawar) घुड़सवारों की संख्या थी।

**🧠 Memory Tip:** Akbar = Administrator = **M**ansabdar.

**🚫 Scam Alert:** शेरशाह ने भी सुधार किए, लेकिन मनसबदारी अकबर का मौलिक ढांचा था।', 2, 0, 3, NULL, 'Who introduced the ''Mansabdari System'' in Mughal administration?', '**✅ Correct Logic:** Akbar started Mansabdari system in 1571. Based on Mongol decimal system. Every officer was given a ''Mansab'' (Rank) determining salary and military duty (Zat and Sawar).

**💡 Exam Fact:** ''Zat'' was personal rank, ''Sawar'' was number of horsemen.

**🧠 Memory Tip:** Akbar = Administrator = **M**ansabdar.

**🚫 Scam Alert:** Sher Shah did reforms, but Mansabdari was Akbar''s original framework.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('baca578d-3124-4354-9217-575d55124bdb', '236e9574-e114-4b26-b1d1-63356903da51', 'मौर्य काल में ''सीताध्यक्ष'' (Sitadhyaksha) किस विभाग का प्रमुख होता था?', '[{"id":"A","text":"धार्मिक विभाग (Religious Department)","text_en":"धार्मिक विभाग (Religious Department)"},{"id":"B","text":"राजकीय कृषि और भूमि (Royal Agriculture and Land)","text_en":"राजकीय कृषि और भूमि (Royal Agriculture and Land)"},{"id":"C","text":"व्यापार और वाणिज्य (Trade and Commerce)","text_en":"व्यापार और वाणिज्य (Trade and Commerce)"},{"id":"D","text":"मुद्रा टकसाल (Mint)","text_en":"मुद्रा टकसाल (Mint)"}]', '1', '**✅ Correct Logic:** ''सीता'' का अर्थ है ''हल की रेखा'' (या कृषि भूमि)। सीताध्यक्ष राजकीय भूमि (Crown Land) पर खेती की निगरानी करता था। मौर्य राज्य कृषि में सक्रिय रूप से शामिल था।

**💡 Exam Fact:** ''पण्याध्यक्ष'' व्यापार का और ''लक्षणाध्यक्ष'' टकसाल (Mint) का प्रमुख था।

**🧠 Memory Tip:** Sita (Ramayana) found in furrow/earth -> Sita = Agriculture.

**🚫 Scam Alert:** सीता नाम देखकर इसे महिला विभाग या धर्म से न जोड़ें।', 2, 0, 4, NULL, 'In Mauryan period, ''Sitadhyaksha'' was the head of which department?', '**✅ Correct Logic:** ''Sita'' means ''plough line'' (or agricultural land). Sitadhyaksha supervised cultivation on Crown Land. Mauryan state was actively involved in agriculture.

**💡 Exam Fact:** ''Panyadhyaksha'' was for Trade, ''Lakshanadhyaksha'' for Mint.

**🧠 Memory Tip:** Sita (Ramayana) found in furrow/earth -> Sita = Agriculture.

**🚫 Scam Alert:** Don''t link ''Sita'' to Women''s dept or Religion.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9e6cbf75-71b4-4a80-bb71-17d1dfe83ec5', '236e9574-e114-4b26-b1d1-63356903da51', 'ऐतिहासिक अधिकारियों को उनके कार्य से सुमेलित करें (Match the historical officers with their functions):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(c), (3)-(d), (4)-(a)","text_en":"(1)-(b), (2)-(c), (3)-(d), (4)-(a)"},{"id":"D","text":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)","text_en":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)"}]', '0', '**✅ Correct Logic:**
* **समाहर्ता:** ''समाहार'' (इकट्ठा करना) -> कलेक्टर।
* **सन्निधाता:** सन्निधि (Store) -> खजांची।
* **महासंधिविग्रहिक:** संधि (Peace) + विग्रह (War) -> विदेश मंत्री (हरिषेण समुद्रगुप्त का महासंधिविग्रहिक था)।
* **मुहतसिब:** आचरण रक्षक (औरंगजेब ने नियुक्त किए)।

**💡 Exam Fact:** ये पद अक्सर पूछे जाते हैं। समाहर्ता (DM) और सन्निधाता (Treasurer) में अंतर याद रखें।

**🧠 Memory Tip:** Samaharta = Sum (Total) Collector.

**🚫 Scam Alert:** समाहर्ता = कलेक्टर (DM of Mauryas).', 2, 0, 5, NULL, 'Match the historical officers with their functions:', '**✅ Correct Logic:**
* **Samaharta:** ''Samahar'' (Collect) -> Collector.
* **Sannidhata:** Sannidhi (Store) -> Treasurer.
* **Mahasandhivigrahika:** Sandhi (Peace) + Vigraha (War) -> Foreign Minister (Harishena was one).
* **Muhtasib:** Moral police (appointed by Aurangzeb).

**💡 Exam Fact:** Samaharta (DM) vs Sannidhata (Treasurer) is a common confusion.

**🧠 Memory Tip:** Samaharta = Sum (Total) Collector.

**🚫 Scam Alert:** Samaharta = Collector (DM of Mauryas).', 60, 'matching', '[{"id":"(1)","label":"समाहर्ता (Samaharta) [मौर्य]","match":"राजस्व संग्रहकर्ता (Revenue Collector)","matchId":"(b)"},{"id":"(2)","label":"सन्निधाता (Sannidhata) [मौर्य]","match":"कोषाध्यक्ष (Treasurer)","matchId":"(a)"},{"id":"(3)","label":"महासंधिविग्रहिक (Mahasandhivigrahika) [गुप्त]","match":"युद्ध और शांति का मंत्री (Minister of War and Peace)","matchId":"(d)"},{"id":"(4)","label":"मुहतसिब (Muhtasib) [मुगल]","match":"लोक आचरण/नैतिकता का निरीक्षक (Censor of Public Morals)","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4430c6e5-143a-4130-83ba-78fd6dcfece2', '236e9574-e114-4b26-b1d1-63356903da51', 'अलाउद्दीन खिलजी की ''बाजार नियंत्रण नीति'' (Market Control Policy) का मुख्य उद्देश्य क्या था?', '[{"id":"A","text":"प्रजा का कल्याण (Welfare of subjects)","text_en":"प्रजा का कल्याण (Welfare of subjects)"},{"id":"B","text":"कम वेतन पर एक विशाल सेना बनाए रखना (Maintaining a large army on low salaries)","text_en":"कम वेतन पर एक विशाल सेना बनाए रखना (Maintaining a large army on low salaries)"},{"id":"C","text":"व्यापारियों को दंडित करना (Punishing merchants)","text_en":"व्यापारियों को दंडित करना (Punishing merchants)"},{"id":"D","text":"अकाल से निपटना (Dealing with famine)","text_en":"अकाल से निपटना (Dealing with famine)"}]', '1', '**✅ Correct Logic:** अलाउद्दीन को मंगोल आक्रमणों का सामना करने के लिए विशाल सेना की जरूरत थी। खजाना सीमित था, इसलिए उसने वेतन कम रखा। सैनिक कम वेतन में जी सकें, इसके लिए उसने वस्तुओं (अनाज, कपड़ा, घोड़ा) के दाम निश्चित (Fix) कर दिए।

**💡 Exam Fact:** उसने ''शहना-ए-मंडी'' (बाजार अधीक्षक) नियुक्त किया।

**🧠 Memory Tip:** Low Salary + Low Prices = Happy Army = Strong Defense.

**🚫 Scam Alert:** बर्नी ने इसे ''सैनिक जरूरत'' बताया, अमीर खुसरो ने ''जनकल्याण''। पर मुख्य उद्देश्य ''सैन्य'' था।', 2, 0, 6, NULL, 'What was the main objective of Alauddin Khilji''s ''Market Control Policy''?', '**✅ Correct Logic:** Alauddin needed a huge army to fight Mongols. Treasury was limited, so he kept salaries low. To let soldiers survive on low pay, he Fixed prices of goods. 

**💡 Exam Fact:** Appointed ''Shahna-i-Mandi'' (Market Superintendent).

**🧠 Memory Tip:** Low Salary + Low Prices = Happy Army = Strong Defense.

**🚫 Scam Alert:** Barani said ''Military need'', Khusro said ''Welfare''. But primary aim was ''Military''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ec232263-080a-499a-a4a0-863a8511e0ef', '236e9574-e114-4b26-b1d1-63356903da51', 'शिवाजी के प्रशासन ''अष्टप्रधान'' (Ashtapradhan) में वित्त मंत्री को क्या कहा जाता था?', '[{"id":"A","text":"पेशवा (Peshwa)","text_en":"पेशवा (Peshwa)"},{"id":"B","text":"अमात्य / मजूमदार (Amatya / Majumdar)","text_en":"अमात्य / मजूमदार (Amatya / Majumdar)"},{"id":"C","text":"सुमंत / दबीर (Sumant / Dabir)","text_en":"सुमंत / दबीर (Sumant / Dabir)"},{"id":"D","text":"सुरनवीस / सचिव (Surnavis / Sachiv)","text_en":"सुरनवीस / सचिव (Surnavis / Sachiv)"}]', '1', '**✅ Correct Logic:** शिवाजी के 8 मंत्रियों में:
* **पेशवा:** प्रधानमंत्री।
* **अमात्य/मजूमदार:** वित्त और राजस्व मंत्री (Finance).
* **सुमंत:** विदेश मंत्री।
* **सुरनवीस:** पत्राचार/सचिव।

**💡 Exam Fact:** ये मंत्री केवल सलाहकार थे, इनके पास स्वतंत्र अधिकार नहीं थे (जैसा पेशवा काल में बाद में हुआ)।

**🧠 Memory Tip:** Amatya sounds like ''Amount'' (Money) -> Finance.

**🚫 Scam Alert:** पेशवा सबसे ऊपर था, लेकिन वित्त विभाग अमात्य के पास था।', 2, 0, 7, NULL, 'What was the Finance Minister called in Shivaji''s ''Ashtapradhan'' administration?', '**✅ Correct Logic:** In Shivaji''s 8 ministers:
* **Peshwa:** PM.
* **Amatya/Majumdar:** Finance & Revenue.
* **Sumant:** Foreign Minister.
* **Surnavis:** Secretary.

**💡 Exam Fact:** These were advisory only, unlike later Peshwa period.

**🧠 Memory Tip:** Amatya sounds like ''Amount'' (Money) -> Finance.

**🚫 Scam Alert:** Peshwa was top, but Finance was Amatya.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a08be1c9-acbf-4dc4-a797-81e568b9ddc5', '236e9574-e114-4b26-b1d1-63356903da51', 'प्राचीन भारत में ''दास प्रथा'' (Slavery) के संदर्भ में कौटिल्य का क्या मत था?', '[{"id":"A","text":"भारत में दास प्रथा नहीं थी (Slavery did not exist in India)","text_en":"भारत में दास प्रथा नहीं थी (Slavery did not exist in India)"},{"id":"B","text":"दास आजीवन बंधुआ होते थे (Slaves were bonded for life)","text_en":"दास आजीवन बंधुआ होते थे (Slaves were bonded for life)"},{"id":"C","text":"आर्यों को दास नहीं बनाया जा सकता था और दासों के कुछ कानूनी अधिकार थे (Aryans could not be enslaved and slaves had legal rights)","text_en":"आर्यों को दास नहीं बनाया जा सकता था और दासों के कुछ कानूनी अधिकार थे (Aryans could not be enslaved and slaves had legal rights)"},{"id":"D","text":"दासों के साथ पशुओं जैसा व्यवहार होता था (Slaves were treated like animals)","text_en":"दासों के साथ पशुओं जैसा व्यवहार होता था (Slaves were treated like animals)"}]', '2', '**✅ Correct Logic:** कौटिल्य ने कहा "न त्वेवार्यस्य दासभावः" (आर्य कभी दास नहीं हो सकता)। यदि कोई आर्य (स्वतंत्र व्यक्ति) कर्ज के कारण दास बनता है, तो पैसा चुकाकर वह मुक्त हो सकता है। भारत में दास प्रथा यूनान की तरह कठोर नहीं थी।

**💡 Exam Fact:** मेगस्थनीज ने कहा ''भारत में दास नहीं हैं'' क्योंकि वह भारतीय दासों की बेहतर स्थिति को यूनानी दासों से अलग समझ नहीं पाया।

**🧠 Memory Tip:** Kautilya = Rules. Even slaves had Rights.

**🚫 Scam Alert:** मेगस्थनीज ने कहा ''नहीं थी'', कौटिल्य ने कहा ''थी, पर उदार (Liberal) थी''।', 2, 0, 8, NULL, 'What was Kautilya''s view regarding ''Slavery'' in ancient India?', '**✅ Correct Logic:** Kautilya said "Na tvevaryasya dasabhavah" (An Aryan can never be a slave). Even temporary slaves could buy freedom. Indian slavery was not harsh like Greek slavery.

**💡 Exam Fact:** Megasthenes said ''No slaves in India'' because he couldn''t distinguish the mild Indian slavery from harsh Greek slavery.

**🧠 Memory Tip:** Kautilya = Rules. Even slaves had Rights.

**🚫 Scam Alert:** Megasthenes said ''No'', Kautilya said ''Yes, but Liberal''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('94237344-d84f-494b-ab29-8760045832ee', '236e9574-e114-4b26-b1d1-63356903da51', 'दिल्ली सल्तनत में ''दीवान-ए-आरिज'' (Diwan-i-Arz) किस विभाग से संबंधित था?', '[{"id":"A","text":"राजस्व विभाग (Revenue Dept)","text_en":"राजस्व विभाग (Revenue Dept)"},{"id":"B","text":"सैन्य विभाग (Military Dept)","text_en":"सैन्य विभाग (Military Dept)"},{"id":"C","text":"पत्राचार विभाग (Correspondence Dept)","text_en":"पत्राचार विभाग (Correspondence Dept)"},{"id":"D","text":"दान विभाग (Charity Dept)","text_en":"दान विभाग (Charity Dept)"}]', '1', '**✅ Correct Logic:** ''दीवान-ए-आरिज'' सैन्य विभाग था, जिसे बलबन ने स्थापित किया था ताकि मंगोलों से लड़ा जा सके। इसका प्रधान ''आरिज-ए-मुमालिक'' होता था जो सैनिकों की भर्ती और हुलिया रखता था।

**💡 Exam Fact:** अलाउद्दीन खिलजी ने इसी विभाग में ''दाग और चेहरा'' प्रथा लागू की।

**🧠 Memory Tip:** Arz = Army.

**🚫 Scam Alert:** ''दीवान-ए-वजारत'' (वित्त/PM) से अलग है।', 2, 0, 9, NULL, 'In Delhi Sultanate, ''Diwan-i-Arz'' was related to which department?', '**✅ Correct Logic:** ''Diwan-i-Arz'' was Military Dept, established by Balban to fight Mongols. Headed by ''Ariz-i-Mumalik'' (Recruitment/Muster roll).

**💡 Exam Fact:** Alauddin Khilji introduced ''Dagh and Chehra'' here.

**🧠 Memory Tip:** Arz = Army.

**🚫 Scam Alert:** Different from ''Diwan-i-Wajarat'' (Finance).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0812e430-84cf-48db-a2d5-c8d602a917f4', '236e9574-e114-4b26-b1d1-63356903da51', 'मुगल काल में ''दहसाला'' (Dahsala) भू-राजस्व प्रणाली किसने तैयार की थी?', '[{"id":"A","text":"अकबर (Akbar)","text_en":"अकबर (Akbar)"},{"id":"B","text":"टोडरमल (Todarmal)","text_en":"टोडरमल (Todarmal)"},{"id":"C","text":"मान सिंह (Man Singh)","text_en":"मान सिंह (Man Singh)"},{"id":"D","text":"शाहजहां (Shah Jahan)","text_en":"शाहजहां (Shah Jahan)"}]', '1', '**✅ Correct Logic:** राजा टोडरमल (अकबर के वित्त मंत्री) ने 1580 में ''आईन-ए-दहसाला'' लागू की। इसमें पिछले 10 वर्षों (Dah = 10) की उपज और कीमतों का औसत निकालकर राजस्व तय किया जाता था। इसे ''टोडरमल बंदोबस्त'' भी कहते हैं।

**💡 Exam Fact:** यह ''जब्ती'' प्रणाली का सुधरा हुआ रूप था।

**🧠 Memory Tip:** Dah = Das (10). Todarmal = Tax master.

**🚫 Scam Alert:** यह अकबर के काल में हुआ, पर ''बनाने वाला'' (Architect) टोडरमल था।', 2, 0, 10, NULL, 'Who devised the ''Dahsala'' land revenue system in Mughal period?', '**✅ Correct Logic:** Raja Todarmal (Akbar''s Finance Minister) introduced ''Ain-i-Dahsala'' in 1580. It calculated tax based on Average of last 10 years'' (Dah=10) produce/prices. Also called ''Todarmal Bandobast''.

**💡 Exam Fact:** Improved version of ''Zabti'' system.

**🧠 Memory Tip:** Dah = Das (10). Todarmal = Tax master.

**🚫 Scam Alert:** Happened in Akbar''s time, but Todarmal was the Architect.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('814aed5c-f524-4a5f-8475-371d6320e22b', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'बुंदेलखंड की प्रसिद्ध ''सुरैती'' (Suraiti) लोक कला का संबंध किस अवसर से है?', '[{"id":"A","text":"दीपावली","text_en":"दीपावली"},{"id":"B","text":"होली","text_en":"होली"},{"id":"C","text":"विवाह","text_en":"विवाह"},{"id":"D","text":"नवरात्रि","text_en":"नवरात्रि"}]', '0', '✅ **Correct Logic**: सुरैती दीपावली के अवसर पर लक्ष्मी पूजा के समय घर की दीवारों पर गेरू से बनाई जाने वाली एक जालीदार आकृति होती है।
💡 **Exam Fact**: यह बुंदेलखंड की भित्ति चित्रकला का एक अभिन्न अंग है।
🧠 **Memory Tip**: S-L (Suraiti-Laxmi Puja).
🚫 **Scam Alert**: संजा मालवा की कला है, सुरैती बुंदेलखंड की।', 2, 0, 1, NULL, 'With which occasion is the famous ''Suraiti'' folk art of Bundelkhand associated?', '✅ **Correct Logic**: Suraiti is a latticed figure made with ochre (Geru) on house walls during Lakshmi Puja on Diwali.
💡 **Exam Fact**: It is an integral part of Bundelkhand''s wall painting tradition.
🧠 **Memory Tip**: S-L (Suraiti-Laxmi Puja).
🚫 **Scam Alert**: Sanjha belongs to Malwa, while Suraiti belongs to Bundelkhand.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('69338243-9faf-4d51-9c3a-7ab7307ef5c0', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'निमाड़ क्षेत्र में ''थापा'' (Thapa) लोक कला मुख्य रूप से किस अवसर पर बनाई जाती है?', '[{"id":"A","text":"दीपावली","text_en":"दीपावली"},{"id":"B","text":"शैली सप्तमी","text_en":"शैली सप्तमी"},{"id":"C","text":"गंगा दशमी","text_en":"गंगा दशमी"},{"id":"D","text":"हरियाली अमावस्या","text_en":"हरियाली अमावस्या"}]', '1', '✅ **Correct Logic**: थापा शैली सप्तमी के अवसर पर हाथ के थापे लगाकर बनाई जाने वाली कला है।
💡 **Exam Fact**: इसमें गेरू और हल्दी का उपयोग किया जाता है।
🧠 **Memory Tip**: T-S (Thapa-Saptami).
🚫 **Scam Alert**: ''पगलया'' निमाड़ की ही कला है लेकिन वह जन्म के अवसर पर बनाई जाती है।', 2, 0, 2, NULL, 'In which occasion is the ''Thapa'' folk art primarily made in the Nimar region?', '✅ **Correct Logic**: Thapa is an art form made by applying handprints on the occasion of Shaili Saptami.
💡 **Exam Fact**: It utilizes ochre and turmeric for colors.
🧠 **Memory Tip**: T-S (Thapa-Saptami).
🚫 **Scam Alert**: ''Paglya'' is also from Nimar but made during the birth of a child.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('55c27ed2-f68f-40fa-a8cb-d48fb4ce913e', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'बघेलखंड की ''कोहबर'' (Kohbar) चित्रकला के संबंध में कौन सा कथन सही है?
1. यह विवाह के अवसर पर बनाई जाती है।
2. इसमें वैवाहिक जोड़े के इष्टदेव का चित्रण होता है।
3. यह केवल पुरुष कलाकारों द्वारा बनाई जाती है।

सही विकल्प चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '0', '✅ **Correct Logic**: कोहबर विवाह के समय बनाया जाता है, लेकिन यह मुख्य रूप से महिलाओं द्वारा बनाया जाता है, पुरुषों द्वारा नहीं।
💡 **Exam Fact**: यह चित्र वैवाहिक कक्ष (कोहबर घर) की दीवार पर बनाया जाता है।
🧠 **Memory Tip**: Kohbar-Kabool (Marriage agreement).
🚫 **Scam Alert**: बघेलखंड की कोहबर और मधुबनी की कोहबर में समानताएँ हैं, लेकिन तकनीक स्थानीय है।', 2, 0, 3, NULL, 'Which statement is correct regarding the ''Kohbar'' painting of Baghelkhand?
1. It is made during marriage ceremonies.
2. It depicts the tutelary deity of the wedding couple.
3. It is made only by male artists.

Choose the correct option:', '✅ **Correct Logic**: Kohbar is made during weddings, but it is primarily created by women, not men.
💡 **Exam Fact**: It is drawn on the walls of the nuptial chamber.
🧠 **Memory Tip**: Kohbar-Kabool (Marriage agreement).
🚫 **Scam Alert**: While similar to Madhubani Kohbar, the technique here is localized to Baghelkhand.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0a2f3a84-833d-4ce9-bd4d-dbcae303fab0', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'मालवा की ''चित्रावण'' (Chitravan) कला किस समुदाय द्वारा परंपरागत रूप से की जाती है?', '[{"id":"A","text":"चितेरा","text_en":"चितेरा"},{"id":"B","text":"हरबोला","text_en":"हरबोला"},{"id":"C","text":"ओझा","text_en":"ओझा"},{"id":"D","text":"बंजारा","text_en":"बंजारा"}]', '0', '✅ **Correct Logic**: चित्रावण मालवा की एक मंदिर और महल चित्रकला शैली है जिसे ''चितेरा'' जाति के लोग करते हैं।
💡 **Exam Fact**: यह शैली धीरे-धीरे लुप्त हो रही है, इसे उज्जैन के आसपास अधिक देखा जा सकता है।
🧠 **Memory Tip**: C-C (Chitravan-Chitera).
🚫 **Scam Alert**: यह कागज पर नहीं बल्कि दीवारों और लकड़ी पर की जाने वाली कला है।', 2, 0, 4, NULL, 'The ''Chitravan'' art of Malwa is traditionally performed by which community?', '✅ **Correct Logic**: Chitravan is a style of temple and palace painting in Malwa performed by the ''Chitera'' community.
💡 **Exam Fact**: This style is gradually disappearing; it is most prevalent around Ujjain.
🧠 **Memory Tip**: C-C (Chitravan-Chitera).
🚫 **Scam Alert**: This is not paper art; it is done on walls and wood.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4456b75b-ee4c-47e0-87cd-41b75ef486ec', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'लोक कला और उनके संबंधित क्षेत्र को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: पगलया निमाड़ में जन्म के समय बनता है। मांडणा मालवा-निमाड़ की आँगन चित्रकला है। मोरते बुंदेलखंड में विवाह के समय मुख्य द्वार पर बनता है। तिलंगा बघेलखंड में कोयले से बनाई जाने वाली आकृति है।
💡 **Exam Fact**: तिलंगा में तिल के तेल और कोयले का उपयोग होता है।
🧠 **Memory Tip**: Pag-N (Paglya in Nimar).
🚫 **Scam Alert**: मांडणा राजस्थान में भी प्रसिद्ध है, लेकिन MP के मालवा में इसका अपना स्थानीय स्वरूप है।', 2, 0, 5, NULL, 'Match the folk art and their respective regions:', '✅ **Correct Logic**: Paglya is made in Nimar at birth. Mandana is floor art of Malwa-Nimar. Morte is made on main gates in Bundelkhand during weddings. Tilanga is a coal-based figure in Baghelkhand.
💡 **Exam Fact**: Tilanga uses sesame oil and coal.
🧠 **Memory Tip**: Pag-N (Paglya in Nimar).
🚫 **Scam Alert**: Mandana is also famous in Rajasthan, but Malwa has its own local variation.', 60, 'matching', '[{"id":"(1)","label":"पगलया","match":"निमाड़","matchId":"(a)"},{"id":"(2)","label":"मांडणा","match":"मालवा/निमाड़","matchId":"(b)"},{"id":"(3)","label":"मोरते","match":"बुंदेलखंड","matchId":"(c)"},{"id":"(4)","label":"तिलंगा","match":"बघेलखंड","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b73d6e3d-8c29-4883-9965-6edcef9cb851', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'बुंदेलखंड में प्रचलित ''गोवर्धन पूजा'' के समय बनाई जाने वाली कला ''मौरला'' (Maurela) में किसका अंकन मुख्य रूप से होता है?', '[{"id":"A","text":"मोर (Peacock)","text_en":"मोर (Peacock)"},{"id":"B","text":"हाथी","text_en":"हाथी"},{"id":"C","text":"गाय","text_en":"गाय"},{"id":"D","text":"भगवान विष्णु","text_en":"भगवान विष्णु"}]', '0', '✅ **Correct Logic**: मौरला में मोर का अंकन मुख्य रूप से किया जाता है। यह दीपावली के अगले दिन गोवर्धन पूजा पर बनाई जाती है।
💡 **Exam Fact**: इसे ''मोर-मौरला'' भी कहा जाता है।
🧠 **Memory Tip**: Maur = More (Peacock).
🚫 **Scam Alert**: मौरला और मोरते में भ्रमित न हों; मोरते विवाह के समय द्वार पर बनता है।', 2, 0, 6, NULL, 'In the ''Maurela'' art made during Govardhan Puja in Bundelkhand, what is primarily depicted?', '✅ **Correct Logic**: Maurela primarily features peacocks. It is made on the day following Diwali during Govardhan Puja.
💡 **Exam Fact**: It is also colloquially called ''Mor-Maurela''.
🧠 **Memory Tip**: Maur = More (Peacock).
🚫 **Scam Alert**: Don''t confuse Maurela with Morte; Morte is made on the door during weddings.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('44fb6a7e-cc36-44b1-832e-22ef77846df1', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'बघेलखंड की ''अंगोंछा'' (Angoncha) लोक कला किससे संबंधित है?', '[{"id":"A","text":"वस्त्रों पर छपाई","text_en":"वस्त्रों पर छपाई"},{"id":"B","text":"मिट्टी की कला","text_en":"मिट्टी की कला"},{"id":"C","text":"काष्ठ कला","text_en":"काष्ठ कला"},{"id":"D","text":"भित्ति चित्र","text_en":"भित्ति चित्र"}]', '0', '✅ **Correct Logic**: अंगोंछा बघेलखंड की एक पारंपरिक वस्त्र छपाई (Textile printing) कला है।
💡 **Exam Fact**: इसमें प्राकृतिक रंगों का उपयोग किया जाता है।
🧠 **Memory Tip**: Angoncha (Towel/Cloth).
🚫 **Scam Alert**: यह कोई चित्रकला नहीं बल्कि हस्तशिल्प (वस्त्र) कला है।', 2, 0, 7, NULL, 'With what is the ''Angoncha'' folk art of Baghelkhand related?', '✅ **Correct Logic**: Angoncha is a traditional textile printing art of Baghelkhand.
💡 **Exam Fact**: Natural dyes are used in this process.
🧠 **Memory Tip**: Angoncha (Towel/Cloth).
🚫 **Scam Alert**: This is not a painting style but a handicraft (textile) art.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('081941ec-f5aa-46c5-9b7d-ac93595b4e41', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'निम्न में से कौन सी लोक कला ''नाग पंचमी'' के अवसर पर बनाई जाती है?', '[{"id":"A","text":"नाग भित्ति चित्र","text_en":"नाग भित्ति चित्र"},{"id":"B","text":"ईरत","text_en":"ईरत"},{"id":"C","text":"सांझी","text_en":"सांझी"},{"id":"D","text":"गोदना","text_en":"गोदना"}]', '0', '✅ **Correct Logic**: नाग पंचमी पर घर के दरवाजों पर नाग के चित्र (Nag Paintings) बनाए जाते हैं, जो लगभग सभी क्षेत्रों में प्रचलित है।
💡 **Exam Fact**: बघेलखंड में इसे ''नाग चित्र'' कहा जाता है।
🧠 **Memory Tip**: Nag-Nag (Simple association).
🚫 **Scam Alert**: ''ईरत'' निमाड़ की विवाह देवी का चित्र है।', 2, 0, 8, NULL, 'Which of the following folk arts is made on the occasion of ''Nag Panchami''?', '✅ **Correct Logic**: On Nag Panchami, figures of snakes are painted on doors, a practice common across regions.
💡 **Exam Fact**: In Baghelkhand, it is specifically referred to as ''Nag Chitra''.
🧠 **Memory Tip**: Nag-Nag (Simple association).
🚫 **Scam Alert**: ''Eerat'' is a painting of the marriage goddess in Nimar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('46a366d1-e65f-4523-9416-1f5bc8968abb', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'बुंदेलखंड की ''मामुलिया'' (Mamuliya) कला में किस पेड़ की टहनी को सजाया जाता है?', '[{"id":"A","text":"कदम","text_en":"कदम"},{"id":"B","text":"अमरूद","text_en":"अमरूद"},{"id":"C","text":"साज","text_en":"साज"},{"id":"D","text":"पीपल","text_en":"पीपल"}]', '1', '✅ **Correct Logic**: मामुलिया में कुंवारी कन्याएँ अमरूद की टहनी को फूल-पत्तियों और रंगीन कपड़ों से सजाती हैं।
💡 **Exam Fact**: यह मालवा की ''सांझी'' के समकक्ष है।
🧠 **Memory Tip**: M-A (Mamuliya-Amrud).
🚫 **Scam Alert**: यह श्राद्ध पक्ष (पितृपक्ष) के दौरान किया जाता है।', 2, 0, 9, NULL, 'In the ''Mamuliya'' art of Bundelkhand, the branch of which tree is decorated?', '✅ **Correct Logic**: In Mamuliya, unmarried girls decorate a guava (Amrud) branch with flowers, leaves, and colorful clothes.
💡 **Exam Fact**: It is the Bundelkhandi equivalent of Malwa''s ''Sanjha''.
🧠 **Memory Tip**: M-A (Mamuliya-Amrud).
🚫 **Scam Alert**: This ritual is performed during the Pitrupaksha period.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3ea622e8-2327-44bd-a10c-d5e5006e467e', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'गोंड जनजाति की लोक कला ''नोहडोरा'' (Nohdora) के बारे में क्या सत्य है?', '[{"id":"A","text":"यह मिट्टी के घरों की दीवारों पर उभरी हुई नक्काशी है।","text_en":"यह मिट्टी के घरों की दीवारों पर उभरी हुई नक्काशी है।"},{"id":"B","text":"यह एक प्रकार का नृत्य है।","text_en":"यह एक प्रकार का नृत्य है।"},{"id":"C","text":"यह लोहे की कलाकृति है।","text_en":"यह लोहे की कलाकृति है।"},{"id":"D","text":"यह सिर की टोपी का प्रकार है।","text_en":"यह सिर की टोपी का प्रकार है।"}]', '0', '✅ **Correct Logic**: नोहडोरा गोंडों द्वारा मिट्टी की दीवारों पर बनाई जाने वाली उभरी हुई मिट्टी की आकृतियाँ (Clay Relief) हैं।
💡 **Exam Fact**: इसमें अक्सर ज्यामितीय पैटर्न या पशु-पक्षियों के चित्र होते हैं।
🧠 **Memory Tip**: Noh-Dora (Wall relief).
🚫 **Scam Alert**: यह केवल पेंटिंग नहीं है, इसमें मिट्टी को उभाड़कर डिजाइन बनाया जाता है।', 2, 0, 10, NULL, 'What is true about the ''Nohdora'' folk art of the Gond tribe?', '✅ **Correct Logic**: Nohdora consists of clay relief patterns made by Gonds on the walls of their mud houses.
💡 **Exam Fact**: It often features geometric patterns or flora and fauna.
🧠 **Memory Tip**: Noh-Dora (Wall relief).
🚫 **Scam Alert**: It is not just a flat painting; it involves embossed clay designs.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('16a91185-10bd-49a2-b93a-b119b14d2cab', 'f8eb92c7-162e-4ed1-92a0-dc6da33d99b2', 'संत सिंगाजी के आध्यात्मिक गीतों और साहित्यों को मुख्य रूप से किस बोली में लिपिबद्ध किया गया है?', '[{"id":"A","text":"मालवी","text_en":"मालवी"},{"id":"B","text":"निमाड़ी","text_en":"निमाड़ी"},{"id":"C","text":"बुंदेली","text_en":"बुंदेली"},{"id":"D","text":"बघेली","text_en":"बघेली"}]', '1', '✅ **Correct Logic**: संत सिंगाजी को ''निमाड़ का कबीर'' कहा जाता है। उनके साहित्य की रचना निमाड़ी बोली में हुई है।
💡 **Exam Fact**: इनका जन्म बड़वानी के खजूरी गाँव में हुआ था और इनकी समाधि खंडवा (पिंपल्या) में है।
🧠 **Memory Tip**: S-N (Singaji-Nimadi).
🚫 **Scam Alert**: हालांकि वे कबीर के समकालीन विचारों के थे, पर उनकी भाषा मालवी नहीं बल्कि शुद्ध निमाड़ी है।', 2, 0, 1, NULL, 'In which dialect are the spiritual songs and literature of Sant Singaji primarily recorded?', '✅ **Correct Logic**: Sant Singaji is known as the ''Kabir of Nimar''. His literature is composed in the Nimadi dialect.
💡 **Exam Fact**: He was born in Khajuri village of Barwani and his samadhi is in Khandwa (Piplya).
🧠 **Memory Tip**: S-N (Singaji-Nimadi).
🚫 **Scam Alert**: Although his thoughts align with Kabir, his language is purely Nimadi, not Malvi.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4594334b-f3e3-4036-bd10-1b31c6909ffb', 'f8eb92c7-162e-4ed1-92a0-dc6da33d99b2', 'जगानिक द्वारा रचित ''आल्हा खण्ड'' विश्व की सबसे लंबी लोक गाथाओं में से एक मानी जाती है। यह किस काल के साहित्य का हिस्सा है?', '[{"id":"A","text":"आदिकाल (Early Period)","text_en":"आदिकाल (Early Period)"},{"id":"B","text":"मध्यकाल (Medieval Period)","text_en":"मध्यकाल (Medieval Period)"},{"id":"C","text":"आधुनिक काल (Modern Period)","text_en":"आधुनिक काल (Modern Period)"},{"id":"D","text":"रीतिकाल","text_en":"रीतिकाल"}]', '0', '✅ **Correct Logic**: जगानिक चंदेल राजा परमार्दिदेव के दरबारी कवि थे। यह वीरगाथा काल या आदिकाल (1000-1350 ई.) का साहित्य है।
💡 **Exam Fact**: इसमें आल्हा-ऊदल की 52 लड़ाइयों का वीर रस में वर्णन है।
🧠 **Memory Tip**: A-A (Alha-Adikal).
🚫 **Scam Alert**: भ्रमित न हों, जगानिक मध्यकालीन नहीं बल्कि प्राचीन/आदिकाल के कवि थे।', 2, 0, 2, NULL, 'The ''Alha Khand'' composed by Jaganik is considered one of the longest folk epics in the world. To which period of literature does it belong?', '✅ **Correct Logic**: Jaganik was the court poet of Chandela King Parmardideva. This belongs to the Vir-Gatha or Adi-Kaal (Early Period).
💡 **Exam Fact**: It describes 52 battles of Alha-Udal in the brave (Veer) sentiment.
🧠 **Memory Tip**: A-A (Alha-Adikal).
🚫 **Scam Alert**: Do not be confused; Jaganik was an ancient/early period poet, not medieval.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f0faea06-43c6-4974-a800-f4e8b49a9f31', 'f8eb92c7-162e-4ed1-92a0-dc6da33d99b2', 'निम्नलिखित में से किसे ''बुंदेलखंड का जयदेव'' कहा जाता है, जिन्होंने नीतिपरक और श्रृंगारिक लोक साहित्य की रचना की?', '[{"id":"A","text":"ईसुरी","text_en":"ईसुरी"},{"id":"B","text":"घाघ","text_en":"घाघ"},{"id":"C","text":"संत सिंगाजी","text_en":"संत सिंगाजी"},{"id":"D","text":"जगानिक","text_en":"जगानिक"}]', '0', '✅ **Correct Logic**: ईसुरी को उनकी फागों के कारण बुंदेलखंड का जयदेव कहा जाता है। उन्होंने लोक जीवन को अपनी रचनाओं का आधार बनाया।
💡 **Exam Fact**: ईसुरी की फागें ''चतुष्पदी'' (चार लाइनों की) होती हैं।
🧠 **Memory Tip**: Isuri - Jayadev (I-J).
🚫 **Scam Alert**: घाघ कृषि पंडित थे, जबकि ईसुरी प्रेम और भक्ति के कवि थे।', 2, 0, 3, NULL, 'Who among the following is called the ''Jayadeva of Bundelkhand'', known for composing ethical and romantic folk literature?', '✅ **Correct Logic**: Isuri is called the Jayadeva of Bundelkhand due to his ''Phags''. He made folk life the basis of his creations.
💡 **Exam Fact**: Isuri''s Phags are ''Chatushpadi'' (quadruplets).
🧠 **Memory Tip**: Isuri - Jayadev (I-J).
🚫 **Scam Alert**: Ghagh was an agricultural expert/poet, whereas Isuri was a poet of love and devotion.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2ab24eac-08a9-4a94-86b4-2b0c6e5133a2', 'f8eb92c7-162e-4ed1-92a0-dc6da33d99b2', 'कवि ''घाघ'' (Ghagh) के साहित्य का मुख्य विषय क्या है?', '[{"id":"A","text":"वीर गाथा","text_en":"वीर गाथा"},{"id":"B","text":"कृषि और मौसम संबंधी कहावतें","text_en":"कृषि और मौसम संबंधी कहावतें"},{"id":"C","text":"राजाओं का वर्णन","text_en":"राजाओं का वर्णन"},{"id":"D","text":"तांत्रिक विद्या","text_en":"तांत्रिक विद्या"}]', '1', '✅ **Correct Logic**: घाघ को ''कृषि पंडित'' कहा जाता है। उनके साहित्य में वर्षा, खेती और पशुपालन से संबंधित व्यावहारिक ज्ञान की कहावतें हैं।
💡 **Exam Fact**: घाघ अकबर के समकालीन माने जाते हैं।
🧠 **Memory Tip**: Ghagh = Grass/Agriculture.
🚫 **Scam Alert**: घाघ की कहावतें केवल बुंदेलखंड में ही नहीं, बल्कि पूरे उत्तर भारत में प्रसिद्ध हैं।', 2, 0, 4, NULL, 'What is the main subject of the literature of poet ''Ghagh''?', '✅ **Correct Logic**: Ghagh is known as the ''Agro-Scholar''. His literature contains proverbs of practical knowledge regarding rain, farming, and cattle.
💡 **Exam Fact**: Ghagh is believed to be a contemporary of Akbar.
🧠 **Memory Tip**: Ghagh = Grass/Agriculture.
🚫 **Scam Alert**: Ghagh''s proverbs are famous across North India, not just in Bundelkhand.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ae5a3121-9b5c-4072-8b0c-fb832826314f', 'f8eb92c7-162e-4ed1-92a0-dc6da33d99b2', 'लोक साहित्यकार और उनकी पहचान को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: जगानिक ने वीरता, ईसुरी ने प्रेम (फाग), घाघ ने कृषि और सिंगाजी ने आध्यात्मिकता पर लिखा।
💡 **Exam Fact**: ईसुरी का पूरा नाम ''हरताल ईसुरी'' था।
🧠 **Memory Tip**: All are correctly aligned in Option A.
🚫 **Scam Alert**: सिंगाजी का साहित्य ''भक्ति काल'' से प्रेरित है, ईसुरी का ''रीति काल'' से।', 2, 0, 5, NULL, 'Match the folk litterateurs and their identities:', '✅ **Correct Logic**: Jaganik wrote on bravery, Isuri on love, Ghagh on agriculture, and Singaji on spirituality.
💡 **Exam Fact**: Isuri''s full name was ''Hartal Isuri''.
🧠 **Memory Tip**: All are correctly aligned in Option A.
🚫 **Scam Alert**: Singaji''s literature is inspired by Bhakti Kaal, Isuri''s by Reeti Kaal.', 60, 'matching', '[{"id":"(1)","label":"जगानिक","match":"आल्हा खण्ड","matchId":"(a)"},{"id":"(2)","label":"ईसुरी","match":"ईसुरी की फागें","matchId":"(b)"},{"id":"(3)","label":"घाघ","match":"कृषि संबंधी कहावतें","matchId":"(c)"},{"id":"(4)","label":"संत सिंगाजी","match":"आध्यात्मिक निमाड़ी पद","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('27c11d6c-e38a-4f0d-8be7-d321b460bc61', 'f8eb92c7-162e-4ed1-92a0-dc6da33d99b2', 'बुंदेलखंड के लोक कवि ईसुरी की प्रेमिका का क्या नाम था, जिनका उल्लेख उनकी रचनाओं में मिलता है?', '[{"id":"A","text":"पिंगला","text_en":"पिंगला"},{"id":"B","text":"रजऊ (Rajau)","text_en":"रजऊ (Rajau)"},{"id":"C","text":"ललिता","text_en":"ललिता"},{"id":"D","text":"बिजुरी","text_en":"बिजुरी"}]', '1', '✅ **Correct Logic**: ईसुरी की फागों में ''रजऊ'' नामक गोपी/प्रेमिका का बहुत अधिक वर्णन मिलता है।
💡 **Exam Fact**: रजऊ के प्रति उनके प्रेम को ईश्वरीय प्रेम का प्रतीक भी माना जाता है।
🧠 **Memory Tip**: R-I (Rajau-Isuri).
🚫 **Scam Alert**: पिंगला राजा भर्तृहरि की पत्नी थीं, ईसुरी की नहीं।', 2, 0, 6, NULL, 'What was the name of the beloved of the Bundelkhandi folk poet Isuri, mentioned in his creations?', '✅ **Correct Logic**: In Isuri''s Phags, there is extensive mention of a beloved named ''Rajau''.
💡 **Exam Fact**: His love for Rajau is also considered a symbol of divine love.
🧠 **Memory Tip**: R-I (Rajau-Isuri).
🚫 **Scam Alert**: Pingala was the wife of King Bhartrihari, not Isuri.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('561edc08-120c-43cc-afb4-dd0355858dcf', 'f8eb92c7-162e-4ed1-92a0-dc6da33d99b2', 'मालवा के लोक साहित्य में ''भरथरी कथा'' का मुख्य रस क्या है?', '[{"id":"A","text":"वीर रस","text_en":"वीर रस"},{"id":"B","text":"करुण एवं शांत रस (वैराग्य)","text_en":"करुण एवं शांत रस (वैराग्य)"},{"id":"C","text":"हास्य रस","text_en":"हास्य रस"},{"id":"D","text":"रौद्र रस","text_en":"रौद्र रस"}]', '1', '✅ **Correct Logic**: भरथरी कथा राजा के संसार को त्याग कर वैराग्य धारण करने की कथा है, अतः इसमें शांत और करुण रस की प्रधानता है।
💡 **Exam Fact**: इसे मुख्य रूप से नाथ संप्रदाय के लोग गाते हैं।
🧠 **Memory Tip**: B-V (Bhartari-Vairagya).
🚫 **Scam Alert**: आल्हा में वीर रस है, लेकिन भरथरी में वैराग्य (शांत रस) है।', 2, 0, 7, NULL, 'What is the main sentiment (Rasa) of ''Bhartari Katha'' in Malwa''s folk literature?', '✅ **Correct Logic**: Bhartari Katha is the story of a king renouncing the world; hence, it is dominated by Shanta (peace) and Karuna (pathos) sentiments.
💡 **Exam Fact**: It is primarily sung by the Nath community.
🧠 **Memory Tip**: B-V (Bhartari-Vairagya).
🚫 **Scam Alert**: Alha features Veer Rasa, but Bhartari features Vairagya (Shanta Rasa).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('402d783f-3058-4e12-a160-b9a43b6090bc', 'f8eb92c7-162e-4ed1-92a0-dc6da33d99b2', 'लोक साहित्य के विकास के लिए ''मध्य प्रदेश आदिवासी लोक कला एवं बोली अकादमी'' कहाँ स्थित है?', '[{"id":"A","text":"भोपाल","text_en":"भोपाल"},{"id":"B","text":"उज्जैन","text_en":"उज्जैन"},{"id":"C","text":"जबलपुर","text_en":"जबलपुर"},{"id":"D","text":"ग्वालियर","text_en":"ग्वालियर"}]', '0', '✅ **Correct Logic**: इसकी स्थापना भोपाल में की गई है जो लोक साहित्य और कलाओं के संरक्षण का कार्य करती है।
💡 **Exam Fact**: इसकी स्थापना 1980 में हुई थी।
🧠 **Memory Tip**: A-B (Academy-Bhopal).
🚫 **Scam Alert**: कालिदास अकादमी उज्जैन में है, लोक कला अकादमी भोपाल में।', 2, 0, 8, NULL, 'Where is the ''MP Tribal Folk Art and Dialect Academy'' located for the development of folk literature?', '✅ **Correct Logic**: It was established in Bhopal and works for the preservation of folk literature and arts.
💡 **Exam Fact**: It was established in 1980.
🧠 **Memory Tip**: A-B (Academy-Bhopal).
🚫 **Scam Alert**: Kalidas Academy is in Ujjain; Folk Art Academy is in Bhopal.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('29490394-0794-40a0-9221-f706af82e6a9', 'f8eb92c7-162e-4ed1-92a0-dc6da33d99b2', 'बघेलखंड के लोक साहित्य में ''बिरहा'' और ''विदेशीया'' को क्या माना जाता है?', '[{"id":"A","text":"लोक गाथा (Folk Epic)","text_en":"लोक गाथा (Folk Epic)"},{"id":"B","text":"मुक्तक लोकगीत","text_en":"मुक्तक लोकगीत"},{"id":"C","text":"पहेलियाँ","text_en":"पहेलियाँ"},{"id":"D","text":"नाटक","text_en":"नाटक"}]', '1', '✅ **Correct Logic**: बिरहा और विदेशीया बघेलखंड के लोकप्रिय मुक्तक लोकगीत हैं जो मौखिक परंपरा से साहित्य का हिस्सा बने।
💡 **Exam Fact**: ये गीत विरह (Separation) की भावनाओं को व्यक्त करते हैं।
🧠 **Memory Tip**: B-V (Baghelkhand-Birha-Videshiya).
🚫 **Scam Alert**: लोक गाथा लंबी कहानी होती है, जबकि बिरहा संक्षिप्त गीत होता है।', 2, 0, 9, NULL, 'What are ''Birha'' and ''Videshiya'' considered in the folk literature of Baghelkhand?', '✅ **Correct Logic**: Birha and Videshiya are popular lyric folk songs of Baghelkhand that became part of literature through oral tradition.
💡 **Exam Fact**: These songs express sentiments of separation (Virah).
🧠 **Memory Tip**: B-V (Baghelkhand-Birha-Videshiya).
🚫 **Scam Alert**: A folk epic is a long story, whereas Birha is a brief song.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bc5600a7-620b-49f0-a6f6-6057ec8b93bd', 'f8eb92c7-162e-4ed1-92a0-dc6da33d99b2', 'किस लोक साहित्यकार की तुलना शेक्सपियर से की जाती है (बुंदेलखंडी फागों के संदर्भ में)?', '[{"id":"A","text":"ईसुरी","text_en":"ईसुरी"},{"id":"B","text":"घाघ","text_en":"घाघ"},{"id":"C","text":"भडरी","text_en":"भडरी"},{"id":"D","text":"जगानिक","text_en":"जगानिक"}]', '0', '✅ **Correct Logic**: ईसुरी की कल्पनाशीलता और वर्णन शैली के कारण कभी-कभी विद्वान उनकी तुलना महान साहित्यकारों से करते हैं (हालांकि जयदेव से तुलना अधिक प्रचलित है)।
💡 **Exam Fact**: उनकी फागें ग्रामीण सौंदर्य का चित्रण करती हैं।
🧠 **Memory Tip**: I for Isuri.
🚫 **Scam Alert**: घाघ की तुलना भडरी से की जाती है (दोनों कृषि कवि थे), ईसुरी की नहीं।', 2, 0, 10, NULL, 'Which folk litterateur is compared to Shakespeare (in the context of Bundelkhandi Phags)?', '✅ **Correct Logic**: Due to his imagination and descriptive style, scholars sometimes compare Isuri to great litterateurs (though the comparison with Jayadeva is more common).
💡 **Exam Fact**: His Phags depict rural beauty.
🧠 **Memory Tip**: I for Isuri.
🚫 **Scam Alert**: Ghagh is compared to Bhadri (both were agricultural poets), not Isuri.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('890528cf-1704-436c-9a5b-c6aee7a7e885', '0221761c-8213-44cb-9441-16c3cd6cb8e5', 'संस्कृत के महान कवि कालिदास की किस रचना में अमरकंटक के सौंदर्य का चित्रण मिलता है?', '[{"id":"A","text":"कुमारसंभवम्","text_en":"कुमारसंभवम्"},{"id":"B","text":"मेघदूतम्","text_en":"मेघदूतम्"},{"id":"C","text":"अभिज्ञान शाकुन्तलम्","text_en":"अभिज्ञान शाकुन्तलम्"},{"id":"D","text":"ऋतुसंहारम्","text_en":"ऋतुसंहारम्"}]', '1', '✅ **Correct Logic**: ''मेघदूतम्'' में अलकापुरी जाते समय बादल (मेघ) के मार्ग में अमरकंटक (आम्रकूट पर्वत) और नर्मदा के सौंदर्य का वर्णन है।
💡 **Exam Fact**: कालिदास को ''भारत का शेक्सपियर'' कहा जाता है।
🧠 **Memory Tip**: M-A (Meghdoot-Amarkantak).
🚫 **Scam Alert**: कुमारसंभवम् में भगवान शिव और पार्वती के पुत्र कार्तिकेय के जन्म की कथा है, न कि अमरकंटक का मुख्य वर्णन।', 2, 0, 1, NULL, 'In which work of the great Sanskrit poet Kalidasa is the beauty of Amarkantak depicted?', '✅ **Correct Logic**: In ''Meghadootam'', while describing the path of the cloud to Alkapuri, the beauty of Amarkantak (Amrakuta mountain) and Narmada is depicted.
💡 **Exam Fact**: Kalidasa is known as the ''Shakespeare of India''.
🧠 **Memory Tip**: M-A (Meghdoot-Amarkantak).
🚫 **Scam Alert**: Kumarasambhavam describes the birth of Kartikeya, son of Shiva and Parvati, not primarily Amarkantak.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('78a7874c-e8e1-4149-9e10-30fb5bc76d07', '0221761c-8213-44cb-9441-16c3cd6cb8e5', 'पंडित माखनलाल चतुर्वेदी ने अपनी प्रसिद्ध कविता ''पुष्प की अभिलाषा'' मध्य प्रदेश की किस जेल में लिखी थी?', '[{"id":"A","text":"जबलपुर जेल","text_en":"जबलपुर जेल"},{"id":"B","text":"बिलासपुर जेल (तत्कालीन CP)","text_en":"बिलासपुर जेल (तत्कालीन CP)"},{"id":"C","text":"ग्वालियर जेल","text_en":"ग्वालियर जेल"},{"id":"D","text":"भोपाल जेल","text_en":"भोपाल जेल"}]', '1', '✅ **Correct Logic**: 1921 में राजद्रोह के आरोप में गिरफ्तार होने के बाद उन्होंने बिलासपुर जेल (जो उस समय मध्य प्रांत का हिस्सा था) में यह कविता लिखी थी।
💡 **Exam Fact**: उन्हें ''एक भारतीय आत्मा'' के नाम से जाना जाता है।
🧠 **Memory Tip**: P-B (Pushp - Bilaspur).
🚫 **Scam Alert**: उनका जन्म बाबई (नर्मदापुरम) में हुआ था, लेकिन कविता बिलासपुर जेल की देन है।', 2, 0, 2, NULL, 'In which jail of MP did Pandit Makhanlal Chaturvedi write his famous poem ''Pushp ki Abhilasha''?', '✅ **Correct Logic**: After being arrested for sedition in 1921, he wrote this poem in Bilaspur Jail (then part of Central Provinces).
💡 **Exam Fact**: He is famously known as ''Ek Bhartiya Atma''.
🧠 **Memory Tip**: P-B (Pushp - Bilaspur).
🚫 **Scam Alert**: He was born in Babai (Narmadapuram), but the poem was composed in Bilaspur jail.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4bfa8640-a296-4187-a042-0304884d85f4', '0221761c-8213-44cb-9441-16c3cd6cb8e5', 'गजानन माधव ''मुक्तिबोध'' की प्रसिद्ध रचना ''चाँद का मुँह टेढ़ा है'' किस साहित्य विधा के अंतर्गत आती है?', '[{"id":"A","text":"उपन्यास","text_en":"उपन्यास"},{"id":"B","text":"कहानी संग्रह","text_en":"कहानी संग्रह"},{"id":"C","text":"काव्य संग्रह","text_en":"काव्य संग्रह"},{"id":"D","text":"नाटक","text_en":"नाटक"}]', '2', '✅ **Correct Logic**: यह मुक्तिबोध का सबसे प्रसिद्ध काव्य संग्रह (Poetry collection) है।
💡 **Exam Fact**: मुक्तिबोध को ''भयानक खबरों का कवि'' भी कहा जाता है।
🧠 **Memory Tip**: C-M-K (Chand-Muktibodh-Kavya).
🚫 **Scam Alert**: ''काठ का सपना'' उनकी कहानी संग्रह है, इसे काव्य संग्रह से भ्रमित न करें।', 2, 0, 3, NULL, 'Under which literary genre does Gajanan Madhav ''Muktibodh''s'' famous work ''Chand ka Muh Tedha Hai'' fall?', '✅ **Correct Logic**: This is the most famous poetry collection of Muktibodh.
💡 **Exam Fact**: Muktibodh is also called the ''Poet of Dreadful News''.
🧠 **Memory Tip**: C-M-K (Chand-Muktibodh-Kavya).
🚫 **Scam Alert**: ''Kath ka Sapna'' is his story collection; don''t confuse it with this poetry collection.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('10e311e0-9153-4bc1-be19-37ed1326bae3', '0221761c-8213-44cb-9441-16c3cd6cb8e5', 'कवि पद्माकर का जन्म मध्य प्रदेश के किस शहर में हुआ था और वे किस काल के कवि थे?', '[{"id":"A","text":"सागर; रीतिकाल","text_en":"सागर; रीतिकाल"},{"id":"B","text":"टीकमगढ़; आदिकाल","text_en":"टीकमगढ़; आदिकाल"},{"id":"C","text":"दतिया; भक्ति काल","text_en":"दतिया; भक्ति काल"},{"id":"D","text":"जबलपुर; आधुनिक काल","text_en":"जबलपुर; आधुनिक काल"}]', '0', '✅ **Correct Logic**: पद्माकर का जन्म 1753 में सागर में हुआ था और वे रीतिकाल के अंतिम प्रसिद्ध कवि माने जाते हैं।
💡 **Exam Fact**: सागर में प्रतिवर्ष ''पद्माकर समारोह'' आयोजित किया जाता है।
🧠 **Memory Tip**: P-S (Padmakar - Sagar).
🚫 **Scam Alert**: उन्हें जयपुर नरेश ने ''कविराज शिरोमणि'' की उपाधि दी थी, पर जन्म सागर का है।', 2, 0, 4, NULL, 'In which city of MP was poet Padmakar born and to which period did he belong?', '✅ **Correct Logic**: Padmakar was born in 1753 in Sagar and is considered the last famous poet of the Riti era.
💡 **Exam Fact**: The ''Padmakar Samaroh'' is organized annually in Sagar.
🧠 **Memory Tip**: P-S (Padmakar - Sagar).
🚫 **Scam Alert**: He was given the title ''Kaviraj Shiromani'' by the King of Jaipur, but his birthplace is Sagar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1a4189ef-37db-415d-ab1b-00907927ce71', '0221761c-8213-44cb-9441-16c3cd6cb8e5', 'साहित्यकार और उनकी प्रसिद्ध कृतियों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: परसाई व्यंग्यकार हैं (नागफनी), मिश्र जी गांधीवादी कवि (बुनी रस्सी), शरद जोशी प्रसिद्ध व्यंग्यकार (इल्लियाँ) और सुभद्रा जी की कहानी ''बिखरे मोती'' है।
💡 **Exam Fact**: भवानी प्रसाद मिश्र को ''कविताओं का गांधी'' कहा जाता है।
🧠 **Memory Tip**: All are primary famous works for each author.
🚫 **Scam Alert**: शरद जोशी व्यंग्य लिखते थे, जबकि सुभद्रा कुमारी चौहान वीर रस और करुण रस की कवयित्री थीं।', 2, 0, 5, NULL, 'Match the litterateurs and their famous works:', '✅ **Correct Logic**: Parsai is a satirist (Nagfani), Mishra is a Gandhian poet (Buni Rassi), Sharad Joshi is a satirist (Illiyan), and Subhadra Kumari''s story is ''Bikhre Moti''.
💡 **Exam Fact**: Bhawani Prasad Mishra is known as the ''Gandhi of Poems''.
🧠 **Memory Tip**: All are primary famous works for each author.
🚫 **Scam Alert**: Sharad Joshi wrote satires, while Subhadra Kumari Chauhan wrote in Veer and Karun sentiments.', 60, 'matching', '[{"id":"(1)","label":"हरिशंकर परसाई","match":"रानी नागफनी की कहानी","matchId":"(a)"},{"id":"(2)","label":"भवानी प्रसाद मिश्र","match":"बुनी हुई रस्सी","matchId":"(b)"},{"id":"(3)","label":"शरद जोशी","match":"जीप पर सवार इल्लियाँ","matchId":"(c)"},{"id":"(4)","label":"सुभद्रा कुमारी चौहान","match":"बिखरे मोती","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b9429b58-a52a-42f9-9cb1-58cc1181215a', '0221761c-8213-44cb-9441-16c3cd6cb8e5', 'मध्य प्रदेश के किस साहित्यकार को ''कठिन काव्य का प्रेत'' कहा जाता है?', '[{"id":"A","text":"केशवदास","text_en":"केशवदास"},{"id":"B","text":"भूषण","text_en":"भूषण"},{"id":"C","text":"पद्माकर","text_en":"पद्माकर"},{"id":"D","text":"बिहारी","text_en":"बिहारी"}]', '0', '✅ **Correct Logic**: आचार्य केशवदास की भाषा अत्यंत क्लिष्ट और अलंकारिक थी, इसलिए उन्हें ''कठिन काव्य का प्रेत'' कहा जाता है।
💡 **Exam Fact**: वे ओरछा नरेश रामसिंह के भाई इन्द्रजीत सिंह के दरबारी कवि थे।
🧠 **Memory Tip**: K-K (Keshav-Kathin).
🚫 **Scam Alert**: ''कठिन गद्य का प्रेत'' अज्ञेय को कहा जाता है, काव्य का केशवदास को।', 2, 0, 6, NULL, 'Which litterateur of MP is called the ''Ghost of difficult poetry'' (Kathin Kavya ka Pret)?', '✅ **Correct Logic**: Acharya Keshavdas used very complex and ornamental language, earning him this title.
💡 **Exam Fact**: He was the court poet of Indrajit Singh, brother of Orchha King Ram Singh.
🧠 **Memory Tip**: K-K (Keshav-Kathin).
🚫 **Scam Alert**: ''Ghost of difficult prose'' refers to Agyeya, while ''Ghost of difficult poetry'' refers to Keshavdas.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bd034b3f-cc07-4adb-a62e-dee39dff6b9c', '0221761c-8213-44cb-9441-16c3cd6cb8e5', 'मध्य प्रदेश के उज्जैन में जन्मे प्रसिद्ध नाटककार ''हबीब तनवीर'' का पहला नाटक कौन सा था जिसने उन्हें अंतरराष्ट्रीय ख्याति दिलाई?', '[{"id":"A","text":"मिट्टी की गाड़ी","text_en":"मिट्टी की गाड़ी"},{"id":"B","text":"चरणदास चोर","text_en":"चरणदास चोर"},{"id":"C","text":"आगरा बाजार","text_en":"आगरा बाजार"},{"id":"D","text":"कामदेव का अपना वसंत","text_en":"कामदेव का अपना वसंत"}]', '2', '✅ **Correct Logic**: ''आगरा बाजार'' (1954) उनका पहला बड़ा नाटक था, हालांकि ''चरणदास चोर'' उनका सबसे प्रसिद्ध नाटक माना जाता है।
💡 **Exam Fact**: उन्होंने भोपाल में ''नया थिएटर'' संस्था की स्थापना की थी।
🧠 **Memory Tip**: A for Agra, A for Arab (Habib).
🚫 **Scam Alert**: चरणदास चोर एडिनबर्ग फेस्टिवल में अवार्ड जीतने वाला पहला नाटक था, पर आगरा बाजार शुरुआती कृति थी।', 2, 0, 7, NULL, 'Which was the first play by famous playwright ''Habib Tanvir'', born in MP (Raipur, later active in MP), that brought him international fame?', '✅ **Correct Logic**: ''Agra Bazar'' (1954) was his first major play, though ''Charandas Chor'' is considered his most famous.
💡 **Exam Fact**: He founded the ''Naya Theatre'' organization in Bhopal.
🧠 **Memory Tip**: A for Agra, A for Arab (Habib).
🚫 **Scam Alert**: Charandas Chor was the first play to win at the Edinburgh Festival, but Agra Bazar was the early work.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f10a9ab3-a081-47eb-a254-ff83d445c99e', '0221761c-8213-44cb-9441-16c3cd6cb8e5', 'प्रसिद्ध कवयित्री सुभद्रा कुमारी चौहान की कर्मस्थली मध्य प्रदेश का कौन सा शहर रहा?', '[{"id":"A","text":"जबलपुर","text_en":"जबलपुर"},{"id":"B","text":"खंडवा","text_en":"खंडवा"},{"id":"C","text":"इंदौर","text_en":"इंदौर"},{"id":"D","text":"होशंगाबाद","text_en":"होशंगाबाद"}]', '0', '✅ **Correct Logic**: सुभद्रा कुमारी चौहान का जन्म इलाहाबाद में हुआ था, लेकिन विवाह के बाद वे जबलपुर में बस गईं और वहीं से स्वाधीनता आंदोलन में भाग लिया।
💡 **Exam Fact**: वे मध्य प्रदेश की पहली महिला सत्याग्रही थीं।
🧠 **Memory Tip**: S-J (Subhadra-Jabalpur).
🚫 **Scam Alert**: ''झांसी की रानी'' कविता उन्होंने लिखी थी, पर वे झांसी की रहने वाली नहीं थीं।', 2, 0, 8, NULL, 'Which city of MP was the workplace (Karmasthali) of the famous poetess Subhadra Kumari Chauhan?', '✅ **Correct Logic**: Born in Allahabad, she settled in Jabalpur after marriage and participated in the freedom struggle from there.
💡 **Exam Fact**: She was the first woman Satyagrahi of MP.
🧠 **Memory Tip**: S-J (Subhadra-Jabalpur).
🚫 **Scam Alert**: She wrote the poem ''Jhansi ki Rani'', but she was not from Jhansi.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d9d36d9e-c2f7-41af-a829-e0f6e2e8d796', '0221761c-8213-44cb-9441-16c3cd6cb8e5', 'निम्नलिखित में से कौन सी रचना राजा भोज द्वारा नहीं लिखी गई है?', '[{"id":"A","text":"सरस्वती कंठाभरण","text_en":"सरस्वती कंठाभरण"},{"id":"B","text":"समरांगण सूत्रधार","text_en":"समरांगण सूत्रधार"},{"id":"C","text":"आयुर्वेद सर्वस्व","text_en":"आयुर्वेद सर्वस्व"},{"id":"D","text":"प्रियदर्शिका","text_en":"प्रियदर्शिका"}]', '3', '✅ **Correct Logic**: ''प्रियदर्शिका'' राजा हर्षवर्धन की रचना है, राजा भोज की नहीं।
💡 **Exam Fact**: राजा भोज ने लगभग 84 ग्रंथों की रचना की थी।
🧠 **Memory Tip**: Bhoj = Knowledge base (Ayurveda, Vastu/Samrangana).
🚫 **Scam Alert**: समरांगण सूत्रधार स्थापत्य कला (Architecture) पर आधारित विश्वकोश है।', 2, 0, 9, NULL, 'Which of the following works was NOT written by Raja Bhoj?', '✅ **Correct Logic**: ''Priyadarshika'' was written by King Harshavardhana, not Raja Bhoj.
💡 **Exam Fact**: Raja Bhoj is credited with composing nearly 84 books.
🧠 **Memory Tip**: Bhoj = Knowledge base (Ayurveda, Vastu/Samrangana).
🚫 **Scam Alert**: Samarangana Sutradhara is an encyclopedic work on architecture.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('578d916a-109e-4bac-8a4d-edc2e5f7cd36', '0221761c-8213-44cb-9441-16c3cd6cb8e5', 'बालकृष्ण शर्मा ''नवीन'' का जन्म मध्य प्रदेश के किस जिले में हुआ था?', '[{"id":"A","text":"शाजापुर","text_en":"शाजापुर"},{"id":"B","text":"ग्वालियर","text_en":"ग्वालियर"},{"id":"C","text":"मुरैना","text_en":"मुरैना"},{"id":"D","text":"भिंड","text_en":"भिंड"}]', '0', '✅ **Correct Logic**: उनका जन्म शाजापुर जिले के भयाना गाँव में हुआ था।
💡 **Exam Fact**: ''कुंकुम'', ''रश्मिरेखा'' और ''अपलक'' उनकी प्रमुख काव्य कृतियाँ हैं।
🧠 **Memory Tip**: B-N-S (Balkrishna Navin Shajapur).
🚫 **Scam Alert**: वे कानपुर में अधिक सक्रिय रहे, लेकिन जन्मभूमि शाजापुर (MP) है।', 2, 0, 10, NULL, 'In which district of MP was Balkrishna Sharma ''Navin'' born?', '✅ **Correct Logic**: He was born in Bhayana village of Shajapur district.
💡 **Exam Fact**: ''Kumkum'', ''Rashmirekha'', and ''Apalak'' are his major poetic works.
🧠 **Memory Tip**: B-N-S (Balkrishna Navin Shajapur).
🚫 **Scam Alert**: He was more active in Kanpur, but his birthplace is Shajapur (MP).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cb506cdf-a512-49ef-b909-54960bd30e3f', 'bfac4716-0179-4db8-ba56-0572455da619', 'मध्य प्रदेश के किस पुरातात्विक स्थल से सती प्रथा के प्रथम लिखित साक्ष्य प्राप्त हुए हैं?', '[{"id":"A","text":"कायथा (Kayatha)","text_en":"कायथा (Kayatha)"},{"id":"B","text":"एरण (Eran)","text_en":"एरण (Eran)"},{"id":"C","text":"आदमगढ़ (Adamgarh)","text_en":"आदमगढ़ (Adamgarh)"},{"id":"D","text":"नवादाटोली (Navdatoli)","text_en":"नवादाटोली (Navdatoli)"}]', '1', '✅ **Correct Logic**: सागर जिले में स्थित ''एरण'' से 510 ईस्वी का भानुगुप्त का अभिलेख मिला है, जिसमें सती प्रथा का उल्लेख है।
💡 **Exam Fact**: एरण का प्राचीन नाम ''एरिकिण'' था और यह वीणा नदी के तट पर स्थित है।
🧠 **Memory Tip**: E-S (Eran-Sati).
🚫 **Scam Alert**: कायथा उज्जैन में है और वराहमिहिर की जन्मस्थली मानी जाती है, सती साक्ष्य के लिए नहीं।', 2, 0, 1, NULL, 'From which archaeological site in Madhya Pradesh have the first written evidences of the Sati system been found?', '✅ **Correct Logic**: The Eran inscription of Bhanugupta (510 AD) in Sagar district contains the first written record of Sati.
💡 **Exam Fact**: The ancient name of Eran was ''Airikina'' and it is situated on the banks of the Bina river.
🧠 **Memory Tip**: E-S (Eran-Sati).
🚫 **Scam Alert**: Kayatha is in Ujjain and is the birthplace of Varahamihira, not the site for Sati evidence.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7f9828de-a388-40ad-a6a6-cd2511b78947', 'bfac4716-0179-4db8-ba56-0572455da619', 'ओंकारेश्वर ज्योतिर्लिंग के संबंध में कौन सा कथन सत्य है?
1. यह नर्मदा और कावेरी (स्थानीय धारा) नदियों के संगम पर स्थित है।
2. यहाँ स्थित मंदिर ''मान्धाता'' द्वीप पर बना है।
3. यह भारत के 12 ज्योतिर्लिंगों में से एक है।

सही विकल्प चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 3","text_en":"केवल 3"}]', '2', '✅ **Correct Logic**: तीनों कथन सत्य हैं। ओंकारेश्वर नर्मदा के बीच ओम् आकार के द्वीप पर स्थित है जिसे मान्धाता पर्वत कहा जाता है।
💡 **Exam Fact**: यहाँ स्थित ममलेश्वर मंदिर को भी ज्योतिर्लिंग का ही हिस्सा माना जाता है।
🧠 **Memory Tip**: O-M (Omkareshwar-Mandhata).
🚫 **Scam Alert**: भ्रमित न हों, यहाँ की कावेरी दक्षिण भारत वाली नदी नहीं बल्कि नर्मदा की एक सहायक धारा है।', 2, 0, 2, NULL, 'Which statement is true regarding the Omkareshwar Jyotirlinga?
1. It is located at the confluence of Narmada and Kaveri (local stream).
2. The temple here is built on ''Mandhata'' island.
3. It is one of the 12 Jyotirlingas of India.

Choose the correct option:', '✅ **Correct Logic**: All three statements are true. Omkareshwar is located on an Om-shaped island called Mandhata mountain.
💡 **Exam Fact**: The Mamleshwar temple located here is also considered a part of the Jyotirlinga.
🧠 **Memory Tip**: O-M (Omkareshwar-Mandhata).
🚫 **Scam Alert**: Don''t be confused; the Kaveri here is a local tributary of Narmada, not the major South Indian river.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0f1406d3-e4c8-4f43-83dc-021c02136b85', 'bfac4716-0179-4db8-ba56-0572455da619', 'मध्य प्रदेश का कौन सा पुरातात्विक स्थल ''टोलेमी'' द्वारा ''मोजोडास'' के रूप में वर्णित किया गया है?', '[{"id":"A","text":"महिष्मति","text_en":"महिष्मति"},{"id":"B","text":"उज्जैनी","text_en":"उज्जैनी"},{"id":"C","text":"मंदसौर","text_en":"मंदसौर"},{"id":"D","text":"विदिशा","text_en":"विदिशा"}]', '2', '✅ **Correct Logic**: प्रसिद्ध भूगोलवेत्ता टोलेमी ने मंदसौर (दशपुर) को ''मोजोडास'' नाम से संबोधित किया था।
💡 **Exam Fact**: मंदसौर शिवना नदी के तट पर स्थित है और पशुपतिनाथ मंदिर के लिए प्रसिद्ध है।
🧠 **Memory Tip**: M-M (Mandsaur-Mojodas).
🚫 **Scam Alert**: विदिशा का प्राचीन नाम भेलसा या बेसनगर था, मोजोडास नहीं।', 2, 0, 3, NULL, 'Which archaeological site in Madhya Pradesh was described as ''Mojodas'' by Ptolemy?', '✅ **Correct Logic**: The famous geographer Ptolemy referred to Mandsaur (Dashpur) as ''Mojodas''.
💡 **Exam Fact**: Mandsaur is situated on the banks of Shivna river and is famous for the Pashupatinath temple.
🧠 **Memory Tip**: M-M (Mandsaur-Mojodas).
🚫 **Scam Alert**: Vidisha''s ancient name was Bhilsa or Besnagar, not Mojodas.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('816c6827-0fc4-4733-857a-2af24dd6a9ee', 'bfac4716-0179-4db8-ba56-0572455da619', 'होशंगाबाद (नर्मदापुरम) में स्थित ''आदमगढ़'' की गुफाएं किस काल से संबंधित हैं?', '[{"id":"A","text":"पुरापाषाण काल","text_en":"पुरापाषाण काल"},{"id":"B","text":"मध्यपाषाण काल","text_en":"मध्यपाषाण काल"},{"id":"C","text":"नवपाषाण काल","text_en":"नवपाषाण काल"},{"id":"D","text":"लौह युग","text_en":"लौह युग"}]', '1', '✅ **Correct Logic**: आदमगढ़ मुख्य रूप से मध्यपाषाण काल (Mesolithic age) का स्थल है जहाँ पशुपालन के प्रथम साक्ष्य मिले हैं।
💡 **Exam Fact**: इसकी खोज मनोरंजन घोष (Manoranjan Ghosh) ने 1922 में की थी।
🧠 **Memory Tip**: A-M (Adamgarh - Mesolithic).
🚫 **Scam Alert**: भीमबेटका पुरापाषाण से मध्यपाषाण तक विस्तृत है, पर आदमगढ़ की प्रसिद्धि मध्यपाषाण के पशुपालन साक्ष्य के लिए है।', 2, 0, 4, NULL, 'To which period do the ''Adamgarh'' caves in Hoshangabad (Narmadapuram) belong?', '✅ **Correct Logic**: Adamgarh is primarily a Mesolithic site where the first evidences of animal husbandry were found.
💡 **Exam Fact**: It was discovered by Manoranjan Ghosh in 1922.
🧠 **Memory Tip**: A-M (Adamgarh - Mesolithic).
🚫 **Scam Alert**: While Bhimbetka spans from Palaeolithic to Mesolithic, Adamgarh is famous specifically for Mesolithic domestication evidence.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9aff7081-e2e5-4df8-8c21-be9b810c5b74', 'bfac4716-0179-4db8-ba56-0572455da619', 'सांस्कृतिक पर्यटन स्थल और उनके जिलों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: पीताम्बरा दतिया में, चौसठ योगिनी मुरैना (संसद भवन का आधार), राम राजा ओरछा में (जहाँ राम राजा के रूप में पूजे जाते हैं) और पशुपतिनाथ मंदसौर में हैं।
💡 **Exam Fact**: पशुपतिनाथ की मूर्ति अष्टमुखी (8 मुख) है।
🧠 **Memory Tip**: Ram-Orchha (The only place where Ram is King).
🚫 **Scam Alert**: ओरछा अब टीकमगढ़ जिले में नहीं बल्कि निवाड़ी जिले में आता है।', 2, 0, 5, NULL, 'Match the cultural tourism sites and their districts:', '✅ **Correct Logic**: Pitambara in Datia, Chausath Yogini in Morena, Ram Raja in Orchha (where Ram is worshipped as a King), and Pashupatinath in Mandsaur.
💡 **Exam Fact**: The Pashupatinath idol in Mandsaur is eight-faced (Ashtamukhi).
🧠 **Memory Tip**: Ram-Orchha (The only place where Ram is King).
🚫 **Scam Alert**: Orchha is no longer in Tikamgarh district; it is in Niwari district.', 60, 'matching', '[{"id":"(1)","label":"पीताम्बरा पीठ","match":"दतिया","matchId":"(a)"},{"id":"(2)","label":"चौसठ योगिनी मंदिर","match":"मुरैना (मितावली)","matchId":"(b)"},{"id":"(3)","label":"राम राजा मंदिर","match":"निवाड़ी (ओरछा)","matchId":"(c)"},{"id":"(4)","label":"पशुपतिनाथ मंदिर","match":"मंदसौर","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c4f0bf76-809c-41d4-9a9f-a62196527c8f', 'bfac4716-0179-4db8-ba56-0572455da619', 'धार जिले में स्थित ''डायनासोर जीवाश्म राष्ट्रीय उद्यान'' का महत्व क्या है?', '[{"id":"A","text":"यहाँ 6.5 करोड़ वर्ष पुराने डायनासोर के अंडे मिले हैं।","text_en":"यहाँ 6.5 करोड़ वर्ष पुराने डायनासोर के अंडे मिले हैं।"},{"id":"B","text":"यहाँ जीवित डायनासोर रखे गए हैं।","text_en":"यहाँ जीवित डायनासोर रखे गए हैं।"},{"id":"C","text":"यह केवल एक मनोरंजन पार्क है।","text_en":"यह केवल एक मनोरंजन पार्क है।"},{"id":"D","text":"यहाँ से केवल वनस्पति जीवाश्म मिले हैं।","text_en":"यहाँ से केवल वनस्पति जीवाश्म मिले हैं।"}]', '0', '✅ **Correct Logic**: धार में बाघ और जोबट के पास 6.5 करोड़ वर्ष पुराने डायनासोर के अंडे और जीवाश्म मिले हैं।
💡 **Exam Fact**: यह मध्य प्रदेश का दूसरा जीवाश्म राष्ट्रीय उद्यान है (पहला डिंडोरी में है)।
🧠 **Memory Tip**: Dhar - Dinosaur (D-D).
🚫 **Scam Alert**: डिंडोरी का पार्क ''घुघवा'' वनस्पति जीवाश्मों (Plants) के लिए प्रसिद्ध है, धार का डायनासोर के लिए।', 2, 0, 6, NULL, 'What is the significance of the ''Dinosaur Fossil National Park'' located in Dhar district?', '✅ **Correct Logic**: Dinosaur eggs and fossils dating back 6.5 crore years were found near Bagh and Jobat in Dhar.
💡 **Exam Fact**: This is the second fossil national park in MP (the first is in Dindori).
🧠 **Memory Tip**: Dhar - Dinosaur (D-D).
🚫 **Scam Alert**: Dindori''s ''Ghughua'' park is famous for plant fossils, whereas Dhar''s is for Dinosaur remains.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ecc03fa7-2d7e-48f7-9d00-ebdebc636fab', 'bfac4716-0179-4db8-ba56-0572455da619', '''ककनमठ मंदिर'', जो अपनी विशिष्ट स्थापत्य शैली के लिए प्रसिद्ध है, कहाँ स्थित है?', '[{"id":"A","text":"सिहोनिया (मुरैना)","text_en":"सिहोनिया (मुरैना)"},{"id":"B","text":"बदरवास (शिवपुरी)","text_en":"बदरवास (शिवपुरी)"},{"id":"C","text":"महिष्मति (खरगोन)","text_en":"महिष्मति (खरगोन)"},{"id":"D","text":"खजुराहो (छतरपुर)","text_en":"खजुराहो (छतरपुर)"}]', '0', '✅ **Correct Logic**: ककनमठ मंदिर मुरैना के सिहोनिया में स्थित है। इसका निर्माण कच्छपघात वंश के राजा कीर्तिराज ने करवाया था।
💡 **Exam Fact**: यह मंदिर बिना किसी गारे या सीमेंट (mortarless) के केवल पत्थरों को संतुलित करके बनाया गया है।
🧠 **Memory Tip**: K-S (Kakanmath-Sihoniya).
🚫 **Scam Alert**: ग्वालियर के पास होने के कारण लोग इसे ग्वालियर समझते हैं, पर यह जिला मुरैना में आता है।', 2, 0, 7, NULL, 'Where is the ''Kakanmath Temple'', famous for its unique architectural style, located?', '✅ **Correct Logic**: Kakanmath Temple is located in Sihoniya, Morena. It was built by King Kirtiraj of the Kachchhapaghata dynasty.
💡 **Exam Fact**: The temple is constructed without mortar, simply by balancing stones.
🧠 **Memory Tip**: K-S (Kakanmath-Sihoniya).
🚫 **Scam Alert**: Due to proximity to Gwalior, many think it''s in Gwalior district, but it falls under Morena.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('021b70b2-8dbc-41d8-9f87-9eea74caad84', 'bfac4716-0179-4db8-ba56-0572455da619', 'रीवा जिले में स्थित ''त्यौथर'' (Tyouthar) पुरातात्विक स्थल का संबंध किस प्राचीन काल से है?', '[{"id":"A","text":"बौद्ध काल","text_en":"बौद्ध काल"},{"id":"B","text":"जैन काल","text_en":"जैन काल"},{"id":"C","text":"हड़प्पा काल","text_en":"हड़प्पा काल"},{"id":"D","text":"मुगल काल","text_en":"मुगल काल"}]', '0', '✅ **Correct Logic**: त्यौथर एक महत्वपूर्ण बौद्ध पुरातात्विक स्थल है जहाँ से बौद्ध स्तूपों और विहारों के अवशेष प्राप्त हुए हैं।
💡 **Exam Fact**: रीवा क्षेत्र में ''देउर कोठार'' भी एक प्रमुख बौद्ध स्थल है।
🧠 **Memory Tip**: T-B (Tyouthar-Buddhist).
🚫 **Scam Alert**: हड़प्पा काल के साक्ष्य मध्य प्रदेश में नहीं मिलते हैं।', 2, 0, 8, NULL, 'The ''Tyouthar'' archaeological site in Rewa district is associated with which ancient period?', '✅ **Correct Logic**: Tyouthar is an important Buddhist archaeological site from which remains of stupas and viharas have been found.
💡 **Exam Fact**: ''Deur Kothar'' is another major Buddhist site in the Rewa region.
🧠 **Memory Tip**: T-B (Tyouthar-Buddhist).
🚫 **Scam Alert**: Harappan remains are not found in Madhya Pradesh.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4eddd0a9-2bdf-4d10-8859-3405ad75be80', 'bfac4716-0179-4db8-ba56-0572455da619', 'ग्वालियर स्थित ''जय विलास पैलेस'' की वास्तुकला शैली क्या है?', '[{"id":"A","text":"केवल इतालवी","text_en":"केवल इतालवी"},{"id":"B","text":"केवल मुगल","text_en":"केवल मुगल"},{"id":"C","text":"इतालवी, टस्कन और कोरिंथियन का मिश्रण","text_en":"इतालवी, टस्कन और कोरिंथियन का मिश्रण"},{"id":"D","text":"द्रविड़ शैली","text_en":"द्रविड़ शैली"}]', '2', '✅ **Correct Logic**: जय विलास पैलेस की वास्तुकला में यूरोपीय शैलियों (इतालवी, टस्कन और कोरिंथियन) का शानदार मिश्रण मिलता है।
💡 **Exam Fact**: इसके वास्तुकार ''माइकल फिलोस'' थे।
🧠 **Memory Tip**: J-E (Jai Vilas - European style).
🚫 **Scam Alert**: ग्वालियर किला भारतीय शैली का है, पर पैलेस पूरी तरह विदेशी वास्तुकला से प्रेरित है।', 2, 0, 9, NULL, 'What is the architectural style of the ''Jai Vilas Palace'' in Gwalior?', '✅ **Correct Logic**: Jai Vilas Palace features a magnificent blend of European styles (Italian, Tuscan, and Corinthian).
💡 **Exam Fact**: Its architect was Michael Filose.
🧠 **Memory Tip**: J-E (Jai Vilas - European style).
🚫 **Scam Alert**: While Gwalior Fort is Indian in style, the palace is heavily inspired by foreign architecture.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d3bff55f-cecc-4ae6-ac1a-8a878009d198', 'bfac4716-0179-4db8-ba56-0572455da619', 'मध्य प्रदेश के किस जिले को ''शिल्प कला का तीर्थ'' कहा जाता है?', '[{"id":"A","text":"ग्वालियर","text_en":"ग्वालियर"},{"id":"B","text":"छतरपुर (खजुराहो)","text_en":"छतरपुर (खजुराहो)"},{"id":"C","text":"उज्जैन","text_en":"उज्जैन"},{"id":"D","text":"धार","text_en":"धार"}]', '1', '✅ **Correct Logic**: खजुराहो के मंदिरों की अद्भुत नक्काशी के कारण छतरपुर को ''शिल्प कला का तीर्थ'' कहा जाता है।
💡 **Exam Fact**: यहाँ के मंदिरों का निर्माण 950-1050 ईस्वी के बीच हुआ था।
🧠 **Memory Tip**: Khajuraho - Khajura (Sculpture).
🚫 **Scam Alert**: उज्जैन को ''मंदिरों और मूर्तियों का नगर'' कहा जाता है, पर शिल्प कला का तीर्थ खजुराहो है।', 2, 0, 10, NULL, 'Which district of MP is called the ''Pilgrimage of Sculpture''?', '✅ **Correct Logic**: Due to the exquisite carvings of the Khajuraho temples, Chhatarpur is referred to as the ''Pilgrimage of Sculpture''.
💡 **Exam Fact**: These temples were built between 950 and 1050 AD.
🧠 **Memory Tip**: Khajuraho - Khajura (Sculpture).
🚫 **Scam Alert**: Ujjain is known as the ''City of Temples and Idols'', but Khajuraho is specifically the Pilgrimage of Sculpture.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0706f7f3-30d4-420c-a554-158fb90a3007', 'b03f6c29-2dd7-4582-984b-e927672f7577', 'मध्य प्रदेश के किस विश्व धरोहर स्थल को ''पत्थर पर लिखी कविता'' के रूप में जाना जाता है?', '[{"id":"A","text":"सांची के स्तूप","text_en":"सांची के स्तूप"},{"id":"B","text":"खजुराहो के मंदिर","text_en":"खजुराहो के मंदिर"},{"id":"C","text":"भीमबेटका की गुफाएं","text_en":"भीमबेटका की गुफाएं"},{"id":"D","text":"ग्वालियर का किला","text_en":"ग्वालियर का किला"}]', '1', '✅ **Correct Logic**: खजुराहो के मंदिरों की सूक्ष्म नक्काशी और सौंदर्य के कारण उन्हें ''पत्थर पर लिखी कविता'' कहा जाता है।
💡 **Exam Fact**: खजुराहो को 1986 में यूनेस्को की सूची में शामिल किया गया था।
🧠 **Memory Tip**: K-P (Khajuraho-Poetry).
🚫 **Scam Alert**: सांची को शांति का प्रतीक माना जाता है, पर शिल्प सौंदर्य के लिए खजुराहो प्रसिद्ध है।', 2, 0, 1, NULL, 'Which World Heritage Site of Madhya Pradesh is known as ''Poetry on Stone''?', '✅ **Correct Logic**: Due to the intricate carvings and aesthetic beauty of Khajuraho temples, they are referred to as ''Poetry on Stone''.
💡 **Exam Fact**: Khajuraho was added to the UNESCO list in 1986.
🧠 **Memory Tip**: K-P (Khajuraho-Poetry).
🚫 **Scam Alert**: Sanchi is a symbol of peace, but Khajuraho is renowned for its architectural poetry.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('09a15075-3e98-4a99-96f5-59124f5b23a7', 'b03f6c29-2dd7-4582-984b-e927672f7577', 'भीमबेटका (2003) की गुफाओं के संबंध में निम्नलिखित कथनों पर विचार करें:
1. इनकी खोज 1957 में डॉ. विष्णु श्रीधर वाकणकर ने की थी।
2. यहाँ विश्व के सबसे पुराने शैल चित्र (Rock Paintings) पाए जाते हैं।
3. यह स्थल रायसेन जिले की विंध्याचल पहाड़ियों में स्थित है।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '2', '✅ **Correct Logic**: तीनों कथन पूर्णतः सत्य हैं। भीमबेटका मानव विकास के प्रारंभिक चरणों का वैश्विक साक्ष्य है।
💡 **Exam Fact**: भीमबेटका में कुल 600 से अधिक गुफाएं हैं जिनमें से लगभग 275 में चित्रकारी है।
🧠 **Memory Tip**: B-W-R (Bhimbetka-Wakankar-Raisen).
🚫 **Scam Alert**: भ्रमित न हों, भीमबेटका भोपाल के पास है पर प्रशासनिक रूप से रायसेन जिले में आता है।', 2, 0, 2, NULL, 'Consider the following statements regarding Bhimbetka (2003):
1. They were discovered in 1957 by Dr. Vishnu Shridhar Wakankar.
2. The world''s oldest rock paintings are found here.
3. This site is located in the Vindhyachal ranges of Raisen district.

Choose the correct statement:', '✅ **Correct Logic**: All three statements are true. Bhimbetka is global evidence of early human evolution.
💡 **Exam Fact**: There are over 600 caves in Bhimbetka, with about 275 containing paintings.
🧠 **Memory Tip**: B-W-R (Bhimbetka-Wakankar-Raisen).
🚫 **Scam Alert**: Don''t be confused; Bhimbetka is near Bhopal but administratively falls under Raisen district.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cbd380eb-3a13-4113-892a-f985c338675f', 'b03f6c29-2dd7-4582-984b-e927672f7577', 'सांची के स्तूप संख्या-1 (महास्तूप) के तोरण द्वारों पर किस जातक कथा का सबसे प्रमुख अंकन मिलता है?', '[{"id":"A","text":"महाकपि जातक","text_en":"महाकपि जातक"},{"id":"B","text":"वेसांतर जातक","text_en":"वेसांतर जातक"},{"id":"C","text":"छदंत जातक","text_en":"छदंत जातक"},{"id":"D","text":"उपरोक्त सभी","text_en":"उपरोक्त सभी"}]', '3', '✅ **Correct Logic**: सांची के तोरण द्वारों पर बुद्ध के पूर्व जन्मों की कई कथाएँ जैसे महाकपि, वेसांतर और छदंत जातक का विस्तार से वर्णन है।
💡 **Exam Fact**: सांची को 1989 में यूनेस्को विश्व धरोहर स्थल का दर्जा मिला।
🧠 **Memory Tip**: S-J (Sanchi-Jataka).
🚫 **Scam Alert**: सांची में बुद्ध के शरीर के अवशेष नहीं, बल्कि उनके शिष्यों (सारिपुत्र और महामोगलायन) के अवशेष हैं।', 2, 0, 3, NULL, 'Which Jataka tale is most prominently depicted on the gateways (Toranas) of Sanchi Stupa No. 1?', '✅ **Correct Logic**: The gateways of Sanchi depict several Jataka tales of Buddha''s previous births in detail.
💡 **Exam Fact**: Sanchi was designated a UNESCO World Heritage site in 1989.
🧠 **Memory Tip**: S-J (Sanchi-Jataka).
🚫 **Scam Alert**: Sanchi does not house Buddha''s remains but those of his disciples, Sariputra and Mahamogallayana.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9915e123-3573-4e30-aaf6-e2f2640942ba', 'b03f6c29-2dd7-4582-984b-e927672f7577', 'यूनेस्को द्वारा 2020 में ''अर्बन लैंडस्केप सिटी'' (Urban Landscape City) प्रोग्राम के तहत मध्य प्रदेश के किन दो शहरों को शामिल किया गया था?', '[{"id":"A","text":"इंदौर और भोपाल","text_en":"इंदौर और भोपाल"},{"id":"B","text":"ग्वालियर और ओरछा","text_en":"ग्वालियर और ओरछा"},{"id":"C","text":"जबलपुर और उज्जैन","text_en":"जबलपुर और उज्जैन"},{"id":"D","text":"खजुराहो और मांडू","text_en":"खजुराहो और मांडू"}]', '1', '✅ **Correct Logic**: ग्वालियर और ओरछा को उनके ऐतिहासिक और सांस्कृतिक महत्व के कारण अर्बन लैंडस्केप सिटी के रूप में चुना गया।
💡 **Exam Fact**: यह पूर्ण विश्व धरोहर स्थल (WHS) का दर्जा नहीं है, बल्कि शहरी नियोजन के लिए एक विशेष श्रेणी है।
🧠 **Memory Tip**: G-O (Gwalior-Orchha).
🚫 **Scam Alert**: इंदौर स्वच्छता में नंबर 1 है पर इस यूनेस्को प्रोग्राम में ग्वालियर और ओरछा शामिल हैं।', 2, 0, 4, NULL, 'Which two cities of MP were included under UNESCO''s ''Urban Landscape City'' program in 2020?', '✅ **Correct Logic**: Gwalior and Orchha were selected as Urban Landscape Cities due to their historical and cultural significance.
💡 **Exam Fact**: This is not a full WHS status, but a special category for urban heritage planning.
🧠 **Memory Tip**: G-O (Gwalior-Orchha).
🚫 **Scam Alert**: Indore is #1 in cleanliness, but Gwalior and Orchha are the ones in this UNESCO program.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7a8ece19-356e-4547-b09e-0c9512e28f5a', 'b03f6c29-2dd7-4582-984b-e927672f7577', 'धरोहर स्थल और उनके यूनेस्को में शामिल होने के वर्ष को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: खजुराहो (1986) सबसे पहले शामिल हुआ, फिर सांची (1989) और भीमबेटका (2003)। भेड़ाघाट अभी अस्थायी सूची (Tentative List) में है।
💡 **Exam Fact**: सतपुड़ा टाइगर रिजर्व भी 2021 से अस्थायी सूची में शामिल है।
🧠 **Memory Tip**: 86, 89, 03 (Remember the sequence).
🚫 **Scam Alert**: ओरछा और ग्वालियर ''अस्थायी सूची'' का हिस्सा थे पर अब उन्हें अर्बन लैंडस्केप का विशेष दर्जा प्राप्त है।', 2, 0, 5, NULL, 'Match the heritage sites and the year of their inclusion in UNESCO:', '✅ **Correct Logic**: Khajuraho (1986) was included first, followed by Sanchi (1989) and Bhimbetka (2003). Bhedaghat is currently in the Tentative List.
💡 **Exam Fact**: Satpura Tiger Reserve is also in the tentative list since 2021.
🧠 **Memory Tip**: 86, 89, 03 (Remember the sequence).
🚫 **Scam Alert**: Orchha and Gwalior were part of the tentative list but now have special status as Urban Landscape Cities.', 60, 'matching', '[{"id":"(1)","label":"खजुराहो समूह","match":"1986","matchId":"(a)"},{"id":"(2)","label":"सांची स्तूप","match":"1989","matchId":"(b)"},{"id":"(3)","label":"भीमबेटका शैलाश्रय","match":"2003","matchId":"(c)"},{"id":"(4)","label":"भेड़ाघाट-लम्हेटाघाट (अस्थायी)","match":"2021","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a9a44263-2ee1-4cfa-9f12-b192df3acfa3', 'b03f6c29-2dd7-4582-984b-e927672f7577', 'सांची में स्थित ''स्तूप संख्या-2'' का मुख्य महत्व क्या है?', '[{"id":"A","text":"इसमें बुद्ध के दांत रखे गए हैं।","text_en":"इसमें बुद्ध के दांत रखे गए हैं।"},{"id":"B","text":"इसमें अशोक के अवशेष हैं।","text_en":"इसमें अशोक के अवशेष हैं।"},{"id":"C","text":"इसमें विभिन्न बौद्ध भिक्षुओं और आचार्यों के अवशेष हैं।","text_en":"इसमें विभिन्न बौद्ध भिक्षुओं और आचार्यों के अवशेष हैं।"},{"id":"D","text":"यह सांची का सबसे बड़ा स्तूप है।","text_en":"यह सांची का सबसे बड़ा स्तूप है।"}]', '2', '✅ **Correct Logic**: स्तूप संख्या-2 में बुद्ध के समय के विभिन्न धर्मगुरुओं और आचार्यों की अस्थियां रखी गई हैं।
💡 **Exam Fact**: स्तूप-3 में सारिपुत्र और महामोगलायन के अवशेष हैं।
🧠 **Memory Tip**: Stupa 1 (Main), Stupa 2 (Teachers), Stupa 3 (Disciples).
🚫 **Scam Alert**: स्तूप-1 सबसे बड़ा है, स्तूप-2 नहीं।', 2, 0, 6, NULL, 'What is the primary significance of ''Stupa No. 2'' at Sanchi?', '✅ **Correct Logic**: Stupa No. 2 contains the relics of various Buddhist monks and teachers from Buddha''s era.
💡 **Exam Fact**: Stupa No. 3 contains the relics of Sariputra and Mahamogallayana.
🧠 **Memory Tip**: Stupa 1 (Main), Stupa 2 (Teachers), Stupa 3 (Disciples).
🚫 **Scam Alert**: Stupa 1 is the ''Great Stupa'' (largest), not Stupa 2.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e9c1f530-6ae7-4b0a-a6a9-8f44f52f88f4', 'b03f6c29-2dd7-4582-984b-e927672f7577', 'खजुराहो के किस मंदिर को ''कंदरिया महादेव मंदिर'' का लघु रूप माना जाता है, हालांकि वह स्वयं भव्य है?', '[{"id":"A","text":"लक्ष्मण मंदिर","text_en":"लक्ष्मण मंदिर"},{"id":"B","text":"विश्वनाथ मंदिर","text_en":"विश्वनाथ मंदिर"},{"id":"C","text":"दुल्हादेव मंदिर","text_en":"दुल्हादेव मंदिर"},{"id":"D","text":"जवारी मंदिर","text_en":"जवारी मंदिर"}]', '1', '✅ **Correct Logic**: विश्वनाथ मंदिर की बनावट कंदरिया महादेव से काफी मिलती-जुलती है।
💡 **Exam Fact**: कंदरिया महादेव मंदिर विद्याधर द्वारा निर्मित खजुराहो का सबसे बड़ा मंदिर है।
🧠 **Memory Tip**: V-K (Vishvanatha-Kandariya resemblance).
🚫 **Scam Alert**: दुल्हादेव मंदिर खजुराहो का अंतिम निर्मित बड़ा मंदिर माना जाता है।', 2, 0, 7, NULL, 'Which temple in Khajuraho is considered a smaller version of the ''Kandariya Mahadev Temple'', though it is magnificent itself?', '✅ **Correct Logic**: The design of the Vishvanatha temple closely resembles that of the Kandariya Mahadev temple.
💡 **Exam Fact**: Kandariya Mahadev temple, built by Vidyadhara, is the largest in Khajuraho.
🧠 **Memory Tip**: V-K (Vishvanatha-Kandariya resemblance).
🚫 **Scam Alert**: Dulhadeo temple is considered the last major temple built in Khajuraho.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('15e6c4b2-9555-4c6b-b6ec-23171d58ff3e', 'b03f6c29-2dd7-4582-984b-e927672f7577', 'यूनेस्को द्वारा ''सृजनात्मक शहरों का नेटवर्क'' (Creative Cities Network) में संगीत की श्रेणी में मध्य प्रदेश के किस शहर को शामिल किया गया है?', '[{"id":"A","text":"इंदौर","text_en":"इंदौर"},{"id":"B","text":"ग्वालियर","text_en":"ग्वालियर"},{"id":"C","text":"भोपाल","text_en":"भोपाल"},{"id":"D","text":"मैहर","text_en":"मैहर"}]', '1', '✅ **Correct Logic**: ग्वालियर को उसकी समृद्ध संगीत विरासत (तानसेन और ग्वालियर घराना) के कारण यूनेस्को ने ''City of Music'' घोषित किया है।
💡 **Exam Fact**: यह घोषणा 2023 में की गई थी।
🧠 **Memory Tip**: G-M (Gwalior-Music).
🚫 **Scam Alert**: मैहर संगीत नगरी जरूर है, पर यूनेस्को की इस सूची में फिलहाल ग्वालियर ही है।', 2, 0, 8, NULL, 'Which city of MP has been included in the UNESCO ''Creative Cities Network'' under the category of Music?', '✅ **Correct Logic**: Gwalior was declared the ''City of Music'' by UNESCO due to its rich musical heritage (Tansen and Gwalior Gharana).
💡 **Exam Fact**: This announcement was made in late 2023.
🧠 **Memory Tip**: G-M (Gwalior-Music).
🚫 **Scam Alert**: While Maihar is known as the city of music, only Gwalior is currently in this specific UNESCO network.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4f917b45-e8d5-464f-bb71-524017b130b7', 'b03f6c29-2dd7-4582-984b-e927672f7577', 'भीमबेटका में पाए गए चित्रों में किस रंग का प्रयोग सर्वाधिक हुआ है?', '[{"id":"A","text":"सफेद और लाल","text_en":"सफेद और लाल"},{"id":"B","text":"पीला और नीला","text_en":"पीला और नीला"},{"id":"C","text":"काला और हरा","text_en":"काला और हरा"},{"id":"D","text":"केवल भूरा","text_en":"केवल भूरा"}]', '0', '✅ **Correct Logic**: भीमबेटका के शैलचित्रों में मुख्य रूप से गेरू (लाल) और सफेद रंग का प्रयोग किया गया है, जो प्राकृतिक खनिजों से बने थे।
💡 **Exam Fact**: यहाँ हरे और पीले रंगों के चित्र भी मिलते हैं पर वे कम मात्रा में हैं।
🧠 **Memory Tip**: W-R (White-Red).
🚫 **Scam Alert**: इन चित्रों की चमक आज भी बरकरार है क्योंकि ये चट्टानों के खनिजों के साथ रसायनिक क्रिया कर चुके हैं।', 2, 0, 9, NULL, 'Which color has been used most extensively in the paintings found at Bhimbetka?', '✅ **Correct Logic**: The rock paintings of Bhimbetka primarily use ochre (red) and white colors, derived from natural minerals.
💡 **Exam Fact**: Green and yellow colors are also found but in smaller quantities.
🧠 **Memory Tip**: W-R (White-Red).
🚫 **Scam Alert**: The brilliance of these colors remains intact today as they have chemically bonded with the rock minerals.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c064c98d-1629-42ca-bd7d-e6c0b2e2b1d7', 'b03f6c29-2dd7-4582-984b-e927672f7577', 'मध्य प्रदेश का वह कौन सा स्थल है जिसे यूनेस्को की ''अस्थायी सूची'' में ''नर्मदा घाटी के भेड़ाघाट-लम्हेटाघाट'' के रूप में शामिल किया गया है?', '[{"id":"A","text":"जबलपुर","text_en":"जबलपुर"},{"id":"B","text":"होशंगाबाद","text_en":"होशंगाबाद"},{"id":"C","text":"खंडवा","text_en":"खंडवा"},{"id":"D","text":"धार","text_en":"धार"}]', '0', '✅ **Correct Logic**: भेड़ाघाट (जबलपुर) अपनी संगमरमर की चट्टानों और धुआंधार जलप्रपात के लिए प्रसिद्ध है और इसे यूनेस्को की अस्थायी सूची में रखा गया है।
💡 **Exam Fact**: लम्हेटाघाट डायनासोर के जीवाश्मों के लिए भी महत्वपूर्ण है।
🧠 **Memory Tip**: J-B (Jabalpur-Bhedaghat).
🚫 **Scam Alert**: अस्थायी सूची का मतलब यह नहीं है कि इसे पूर्ण दर्जा मिल गया है, यह नामांकन की प्रक्रिया का हिस्सा है।', 2, 0, 10, NULL, 'Which site in MP has been included in the UNESCO ''Tentative List'' as ''Bhedaghat-Lamhetaghat of Narmada Valley''?', '✅ **Correct Logic**: Bhedaghat (Jabalpur) is famous for its marble rocks and Dhuandhar falls and is currently on the UNESCO tentative list.
💡 **Exam Fact**: Lamhetaghat is also significant for its dinosaur fossils.
🧠 **Memory Tip**: J-B (Jabalpur-Bhedaghat).
🚫 **Scam Alert**: Inclusion in the tentative list doesn''t mean final status; it is a step in the nomination process.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('782d2ea9-e8f0-42f3-b084-bbc55e7d6f98', '3d4c9e68-0c7e-4b10-abb1-c8352a9127de', 'किसे ''निमाड़ का रॉबिनहुड'' कहा जाता है, जिन्होंने 1857 की क्रांति में अंग्रेजों के खिलाफ छापामार युद्ध किया था?', '[{"id":"A","text":"टंट्या भील (Tantya Bheel)","text_en":"टंट्या भील (Tantya Bheel)"},{"id":"B","text":"भीमा नायक (Bhima Nayak)","text_en":"भीमा नायक (Bhima Nayak)"},{"id":"C","text":"खज्या नायक","text_en":"खज्या नायक"},{"id":"D","text":"गुंजन सिंह कोरकू","text_en":"गुंजन सिंह कोरकू"}]', '1', '✅ **Correct Logic**: भीमा नायक को निमाड़ का रॉबिनहुड कहा जाता है। उन्होंने मंडलेश्वर और बड़वानी क्षेत्र से विद्रोह का नेतृत्व किया था।
💡 **Exam Fact**: उन्हें अंडमान की पोर्ट ब्लेयर जेल भेजा गया था जहाँ उनकी मृत्यु हुई।
🧠 **Memory Tip**: Bhima - Big/Powerful Hero of Nimar.
🚫 **Scam Alert**: टंट्या भील को ''भारत का रॉबिनहुड'' कहा जाता है, जबकि भीमा नायक विशिष्ट रूप से ''निमाड़ के रॉबिनहुड'' कहलाते हैं।', 2, 0, 1, NULL, 'Who is known as the ''Robin Hood of Nimar'', who fought guerrilla warfare against the British in the 1857 revolution?', '✅ **Correct Logic**: Bhima Nayak is known as the Robin Hood of Nimar. He led the revolt from Mandleshwar and Barwani regions.
💡 **Exam Fact**: He was sent to Port Blair jail in Andaman, where he died.
🧠 **Memory Tip**: Bhima - Big/Powerful Hero of Nimar.
🚫 **Scam Alert**: Tantya Bheel is called the ''Robin Hood of India'', whereas Bhima Nayak is specifically termed the ''Robin Hood of Nimar''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('50ff9d71-bc66-4dfc-afaa-b7f0fa5bfec1', '3d4c9e68-0c7e-4b10-abb1-c8352a9127de', 'पद्मश्री से सम्मानित ''भूरी बाई'' का संबंध किस जनजातीय कला से है?', '[{"id":"A","text":"गोंड पेंटिंग","text_en":"गोंड पेंटिंग"},{"id":"B","text":"पिथोरा पेंटिंग (भील कला)","text_en":"पिथोरा पेंटिंग (भील कला)"},{"id":"C","text":"बैगा नृत्य","text_en":"बैगा नृत्य"},{"id":"D","text":"काष्ठ शिल्प","text_en":"काष्ठ शिल्प"}]', '1', '✅ **Correct Logic**: भूरी बाई झाबुआ की प्रसिद्ध भील कलाकार हैं जिन्होंने पिथोरा चित्रकला को अंतरराष्ट्रीय ख्याति दिलाई।
💡 **Exam Fact**: वह भारत भवन, भोपाल में मजदूरी करती थीं, जहाँ उनकी कला को पहचाना गया।
🧠 **Memory Tip**: B-B (Bhuri-Bheel/Pithora).
🚫 **Scam Alert**: जनगण सिंह श्याम गोंड कला से संबंधित हैं, भूरी बाई भील कला से।', 2, 0, 2, NULL, 'Padma Shri awardee ''Bhuri Bai'' is associated with which tribal art form?', '✅ **Correct Logic**: Bhuri Bai is a famous Bhil artist from Jhabua who brought international fame to Pithora painting.
💡 **Exam Fact**: She used to work as a laborer at Bharat Bhavan, Bhopal, where her talent was discovered.
🧠 **Memory Tip**: B-B (Bhuri-Bheel/Pithora).
🚫 **Scam Alert**: Jangarh Singh Shyam is associated with Gond art, whereas Bhuri Bai is with Bhil art.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('881331e7-13a0-4f0e-86a8-e8042469bf4d', '3d4c9e68-0c7e-4b10-abb1-c8352a9127de', '''टंट्या भील'' का वास्तविक नाम क्या था और उन्हें किस स्थान पर फांसी दी गई थी?', '[{"id":"A","text":"तंतिया; जबलपुर","text_en":"तंतिया; जबलपुर"},{"id":"B","text":"तांदिया; इंदौर (पातालपानी)","text_en":"तांदिया; इंदौर (पातालपानी)"},{"id":"C","text":"टंट्या; नागपुर","text_en":"टंट्या; नागपुर"},{"id":"D","text":"तंतिया; जबलपुर (फांसी के बाद शव पातालपानी फेंका गया)","text_en":"तंतिया; जबलपुर (फांसी के बाद शव पातालपानी फेंका गया)"}]', '3', '✅ **Correct Logic**: उनका वास्तविक नाम ''तंतिया'' था। उन्हें जबलपुर जेल में फांसी दी गई थी और शव को इंदौर के पास पातालपानी में फेंक दिया गया था।
💡 **Exam Fact**: पातालपानी रेलवे स्टेशन का नाम अब ''टंट्या मामा रेलवे स्टेशन'' कर दिया गया है।
🧠 **Memory Tip**: T-J (Tantya-Jabalpur Hang).
🚫 **Scam Alert**: फांसी पातालपानी में नहीं हुई थी, वहाँ केवल उनका स्मारक/समाधि है।', 2, 0, 3, NULL, 'What was the real name of ''Tantya Bheel'' and at which place was he hanged?', '✅ **Correct Logic**: His real name was ''Tantia''. He was hanged in Jabalpur jail, and his body was thrown near Patalpani, Indore.
💡 **Exam Fact**: Patalpani railway station has been renamed ''Tantya Mama Railway Station''.
🧠 **Memory Tip**: T-J (Tantya-Jabalpur Hang).
🚫 **Scam Alert**: The hanging did not occur in Patalpani; only his memorial/samadhi is located there.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3731ed54-3f38-459e-a45e-2eb8c8a54837', '3d4c9e68-0c7e-4b10-abb1-c8352a9127de', 'गोंड चित्रकला को नई ऊंचाइयों पर ले जाने वाले ''जनगण सिंह श्याम'' का जन्म मध्य प्रदेश के किस जिले में हुआ था?', '[{"id":"A","text":"डिंडोरी","text_en":"डिंडोरी"},{"id":"B","text":"मंडला","text_en":"मंडला"},{"id":"C","text":"शहडोल","text_en":"शहडोल"},{"id":"D","text":"बालाघाट","text_en":"बालाघाट"}]', '0', '✅ **Correct Logic**: जनगण सिंह श्याम का जन्म डिंडोरी जिले के पाटनगढ़ गाँव में हुआ था।
💡 **Exam Fact**: उन्होंने ''जनगण कलम'' नामक एक नई शैली विकसित की थी। उनकी मृत्यु जापान में हुई थी।
🧠 **Memory Tip**: J-D (Jangarh-Dindori).
🚫 **Scam Alert**: पाटनगढ़ को ''चित्रकारों का गाँव'' कहा जाता है।', 2, 0, 4, NULL, 'In which district of MP was ''Jangarh Singh Shyam'', who took Gond painting to new heights, born?', '✅ **Correct Logic**: Jangarh Singh Shyam was born in Patangarh village of Dindori district.
💡 **Exam Fact**: He developed a new style called ''Jangarh Kalam''. He passed away in Japan.
🧠 **Memory Tip**: J-D (Jangarh-Dindori).
🚫 **Scam Alert**: Patangarh is often referred to as the ''Village of Painters''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6a1d64c9-7d53-47a1-903a-b2e049dd7db8', '3d4c9e68-0c7e-4b10-abb1-c8352a9127de', 'जनजातीय व्यक्तित्व और उनके कार्यक्षेत्र/पहचान को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: बादल भोई छिंदवाड़ा के महान नेता थे (संग्रहालय उन्हीं के नाम पर है)। पेमा फाल्या पिथोरा के शिखर पुरुष थे। जोधइया बाई उमरिया से बैगा कला के लिए प्रसिद्ध हैं और दुर्गाबाई गोंड कला की प्रमुख हस्ती हैं।
💡 **Exam Fact**: जोधइया बाई और दुर्गाबाई दोनों को पद्मश्री मिल चुका है।
🧠 **Memory Tip**: Badal-Chhindwara (B-C).
🚫 **Scam Alert**: पेमा फाल्या पुरुष थे, उन्हें महिला कलाकार समझने की गलती न करें।', 2, 0, 5, NULL, 'Match the tribal personalities and their field/identity:', '✅ **Correct Logic**: Badal Bhoi was a great leader from Chhindwara. Pema Falya was a pinnacle figure of Pithora. Jodhaiya Bai is famous for Baiga art from Umaria, and Durgabai is a key figure in Gond art.
💡 **Exam Fact**: Both Jodhaiya Bai and Durgabai have received the Padma Shri.
🧠 **Memory Tip**: Badal-Chhindwara (B-C).
🚫 **Scam Alert**: Pema Falya was a male artist; don''t mistake him for a female artist.', 60, 'matching', '[{"id":"(1)","label":"बादल भोई","match":"स्वतंत्रता सेनानी (छिंदवाड़ा)","matchId":"(a)"},{"id":"(2)","label":"पेमा फाल्या","match":"पिथोरा कलाकार","matchId":"(b)"},{"id":"(3)","label":"जोधइया बाई","match":"बैगा चित्रकला","matchId":"(c)"},{"id":"(4)","label":"दुर्गाबाई व्याम","match":"गोंड चित्रकला","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('72bb3ed0-1e82-4ccb-b54d-d2ce8f8eef46', '3d4c9e68-0c7e-4b10-abb1-c8352a9127de', 'रानी दुर्गावती के संबंध में कौन सा कथन गलत है?', '[{"id":"A","text":"वे चंदेल राजकुमारी थीं।","text_en":"वे चंदेल राजकुमारी थीं।"},{"id":"B","text":"उनका विवाह गोंड शासक दलपत शाह से हुआ था।","text_en":"उनका विवाह गोंड शासक दलपत शाह से हुआ था।"},{"id":"C","text":"उन्होंने मुगल शासक अकबर के सेनापति आसफ खान से युद्ध किया था।","text_en":"उन्होंने मुगल शासक अकबर के सेनापति आसफ खान से युद्ध किया था।"},{"id":"D","text":"उनकी समाधि मंडला में स्थित है।","text_en":"उनकी समाधि मंडला में स्थित है।"}]', '3', '✅ **Correct Logic**: रानी दुर्गावती की समाधि जबलपुर के पास ''बरेला'' में स्थित है, मंडला में नहीं।
💡 **Exam Fact**: उन्होंने 1564 में नर्रई नाले के पास मुगल सेना से लड़ते हुए वीरगति प्राप्त की थी।
🧠 **Memory Tip**: D-B (Durgavati-Barela).
🚫 **Scam Alert**: वे महोबा के चंदेल राजा की पुत्री थीं, पर शासन गोंडवाना पर किया।', 2, 0, 6, NULL, 'Which statement is incorrect regarding Rani Durgavati?', '✅ **Correct Logic**: Rani Durgavati''s samadhi is located in ''Barela'' near Jabalpur, not in Mandla.
💡 **Exam Fact**: She attained martyrdom in 1564 while fighting the Mughal army near Narrai Nala.
🧠 **Memory Tip**: D-B (Durgavati-Barela).
🚫 **Scam Alert**: She was the daughter of a Chandela King of Mahoba but ruled over Gondwana.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2b30f985-8bb9-4257-86ce-575f88beb4b9', '3d4c9e68-0c7e-4b10-abb1-c8352a9127de', '1857 के विद्रोह के दौरान ''अमझेरा'' (धार) के किस शासक ने अंग्रेजों को कड़ी चुनौती दी थी?', '[{"id":"A","text":"राजा बख्तावर सिंह","text_en":"राजा बख्तावर सिंह"},{"id":"B","text":"शहादत खान","text_en":"शहादत खान"},{"id":"C","text":"भीमा नायक","text_en":"भीमा नायक"},{"id":"D","text":"ठाकुर रणमत सिंह","text_en":"ठाकुर रणमत सिंह"}]', '0', '✅ **Correct Logic**: राजा बख्तावर सिंह अमझेरा रियासत के शासक थे जिन्होंने धार और आसपास के क्षेत्रों में विद्रोह का नेतृत्व किया।
💡 **Exam Fact**: उन्हें इंदौर में फांसी दी गई थी।
🧠 **Memory Tip**: A-B (Amjhera-Bakhtawar).
🚫 **Scam Alert**: शहादत खान इंदौर के होलकर विद्रोह से संबंधित थे, अमझेरा से नहीं।', 2, 0, 7, NULL, 'During the 1857 revolt, which ruler of ''Amjhera'' (Dhar) gave a tough challenge to the British?', '✅ **Correct Logic**: Raja Bakhtawar Singh was the ruler of Amjhera state who led the revolt in Dhar and nearby areas.
💡 **Exam Fact**: He was executed by hanging in Indore.
🧠 **Memory Tip**: A-B (Amjhera-Bakhtawar).
🚫 **Scam Alert**: Saadat Khan was related to the Holkar revolt in Indore, not Amjhera.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b8912544-2d06-40ba-a011-122111b3664f', '3d4c9e68-0c7e-4b10-abb1-c8352a9127de', '2021 में पद्मश्री से सम्मानित ''अर्जुन सिंह धुर्वे'' का संबंध किस जनजातीय नृत्य से है?', '[{"id":"A","text":"बैगा परधौनी नृत्य","text_en":"बैगा परधौनी नृत्य"},{"id":"B","text":"गोंड कर्मा नृत्य","text_en":"गोंड कर्मा नृत्य"},{"id":"C","text":"सहारिया दुलदुल घोड़ी","text_en":"सहारिया दुलदुल घोड़ी"},{"id":"D","text":"भील भगोरिया","text_en":"भील भगोरिया"}]', '0', '✅ **Correct Logic**: अर्जुन सिंह धुर्वे बैगा जनजाति के प्रसिद्ध नर्तक हैं जिन्हें ''परधौनी'' नृत्य के लिए जाना जाता है।
💡 **Exam Fact**: वे डिंडोरी जिले से संबंधित हैं।
🧠 **Memory Tip**: A-P (Arjun-Pardhauni).
🚫 **Scam Alert**: परधौनी नृत्य मुख्य रूप से विवाह के अवसर पर बारात के स्वागत के समय किया जाता है।', 2, 0, 8, NULL, 'Arjun Singh Dhurve, awarded the Padma Shri in 2021, is associated with which tribal dance?', '✅ **Correct Logic**: Arjun Singh Dhurve is a famous dancer of the Baiga tribe known for ''Pardhauni'' dance.
💡 **Exam Fact**: He belongs to the Dindori district.
🧠 **Memory Tip**: A-P (Arjun-Pardhauni).
🚫 **Scam Alert**: Pardhauni dance is primarily performed during the welcome of the wedding procession (Baraat).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('50294057-3de6-45b5-bfb1-dc764f0ba23e', '3d4c9e68-0c7e-4b10-abb1-c8352a9127de', 'मध्य प्रदेश की ''झाबुआ की गुड़िया'' (Jhabua Dolls) को लोकप्रिय बनाने वाली जनजातीय महिला कलाकार कौन हैं?', '[{"id":"A","text":"भूरी बाई","text_en":"भूरी बाई"},{"id":"B","text":"शांति परमार","text_en":"शांति परमार"},{"id":"C","text":"बत्तो बाई","text_en":"बत्तो बाई"},{"id":"D","text":"लहरी बाई","text_en":"लहरी बाई"}]', '2', '✅ **Correct Logic**: बत्तो बाई ने झाबुआ की पारंपरिक गुड़िया शिल्प (Doll making) को देश-विदेश में ख्याति दिलाई।
💡 **Exam Fact**: लहरी बाई को ''मिलेट वुमन'' (श्री अन्न) के रूप में जाना जाता है।
🧠 **Memory Tip**: B-G (Batto-Gudiya).
🚫 **Scam Alert**: शांति परमार भी कला से जुड़ी हैं लेकिन गुड़िया शिल्प के लिए बत्तो बाई अधिक प्रसिद्ध हैं।', 2, 0, 9, NULL, 'Who is the tribal female artist who popularized the ''Jhabua Dolls'' of Madhya Pradesh?', '✅ **Correct Logic**: Batto Bai brought fame to the traditional doll-making craft of Jhabua both nationally and internationally.
💡 **Exam Fact**: Lahari Bai is known as the ''Millet Woman'' of MP.
🧠 **Memory Tip**: B-G (Batto-Gudiya).
🚫 **Scam Alert**: Shanti Parmar is also an artist, but Batto Bai is more famous for the dolls.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8d66c7d6-4bf4-41ff-967b-e813cb41f911', '3d4c9e68-0c7e-4b10-abb1-c8352a9127de', '1857 की क्रांति के दौरान ''सेंधवा'' (बड़वानी) से विद्रोह का नेतृत्व किसने किया था?', '[{"id":"A","text":"भीमा नायक","text_en":"भीमा नायक"},{"id":"B","text":"खज्या नायक","text_en":"खज्या नायक"},{"id":"C","text":"सीताराम कंवर","text_en":"सीताराम कंवर"},{"id":"D","text":"A और B दोनों","text_en":"A और B दोनों"}]', '1', '✅ **Correct Logic**: खज्या नायक ने सेंधवा घाट से अंग्रेजों के खिलाफ विद्रोह का नेतृत्व किया था। वे भीमा नायक के बहनोई थे।
💡 **Exam Fact**: खज्या नायक पहले अंग्रेजों की पुलिस में थे, लेकिन बाद में वे बागी हो गए।
🧠 **Memory Tip**: K-S (Khajya-Sendhwa).
🚫 **Scam Alert**: भीमा नायक मुख्य नेता थे, पर सेंधवा का विशिष्ट नेतृत्व खज्या नायक ने किया था।', 2, 0, 10, NULL, 'Who led the revolt from ''Sendhwa'' (Barwani) during the 1857 revolution?', '✅ **Correct Logic**: Khajya Nayak led the revolt against the British from the Sendhwa Pass. He was the brother-in-law of Bhima Nayak.
💡 **Exam Fact**: Khajya Nayak was initially in the British police force before turning into a rebel.
🧠 **Memory Tip**: K-S (Khajya-Sendhwa).
🚫 **Scam Alert**: While Bhima Nayak was the main leader, the specific leadership of Sendhwa was held by Khajya Nayak.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c4ca7766-0f6a-49ed-b63f-8388fe7e4cbd', '622ec19d-2feb-4f97-9353-3dda30a0438a', 'राजा राममोहन राय द्वारा स्थापित ''आत्मीय सभा'' (Atmiya Sabha) का गठन किस वर्ष किया गया था?', '[{"id":"A","text":"1815","text_en":"1815"},{"id":"B","text":"1828","text_en":"1828"},{"id":"C","text":"1829","text_en":"1829"},{"id":"D","text":"1817","text_en":"1817"}]', '0', '**✅ Correct Logic:** राजा राममोहन राय ने 1815 में कोलकाता में ''आत्मीय सभा'' (मित्रों की सभा) की स्थापना की। इसका उद्देश्य एकेश्वरवाद (Monotheism) का प्रचार करना और मूर्तिपूजा का विरोध करना था।

**💡 Exam Fact:** ''ब्रह्म समाज'' की स्थापना 1828 में हुई थी।

**🧠 Memory Tip:** Atmiya (Soul/Self) comes first (1815), Brahma (God) comes later (1828).

**🚫 Scam Alert:** छात्र अक्सर 1828 (ब्रह्म समाज) या 1817 (हिंदू कॉलेज) से भ्रमित होते हैं।', 2, 0, 1, NULL, 'In which year was the ''Atmiya Sabha'' established by Raja Ram Mohan Roy?', '**✅ Correct Logic:** Raja Ram Mohan Roy established ''Atmiya Sabha'' (Association of Friends) in Kolkata in 1815. Its aim was to propagate Monotheism and oppose idolatry.

**💡 Exam Fact:** ''Brahmo Samaj'' was established in 1828.

**🧠 Memory Tip:** Atmiya (Soul/Self) comes first (1815), Brahma (God) comes later (1828).

**🚫 Scam Alert:** Students often confuse it with 1828 (Brahmo Samaj) or 1817 (Hindu College).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('08c7adbe-6665-448a-956d-734cd301ff04', '622ec19d-2feb-4f97-9353-3dda30a0438a', 'स्वामी दयानंद सरस्वती ने ''सत्यार्थ प्रकाश'' (Satyarth Prakash) की रचना मुख्य रूप से किस भाषा में की थी?', '[{"id":"A","text":"संस्कृत (Sanskrit)","text_en":"संस्कृत (Sanskrit)"},{"id":"B","text":"हिंदी (Hindi)","text_en":"हिंदी (Hindi)"},{"id":"C","text":"गुजराती (Gujarati)","text_en":"गुजराती (Gujarati)"},{"id":"D","text":"मराठी (Marathi)","text_en":"मराठी (Marathi)"}]', '1', '**✅ Correct Logic:** यद्यपि दयानंद जी गुजराती थे और संस्कृत के विद्वान थे, लेकिन केशव चंद्र सेन की सलाह पर उन्होंने जनता तक पहुँचने के लिए ''सत्यार्थ प्रकाश'' (1875) ''हिंदी'' में लिखी।

**💡 Exam Fact:** आर्य समाज की स्थापना मुंबई (1875) में हुई, लेकिन मुख्यालय लाहौर (1877) बना।

**🧠 Memory Tip:** Satyarth Prakash = Light of Truth for **Masses** (Hindi).

**🚫 Scam Alert:** वेदों के विद्वान होने के कारण ''संस्कृत'' एक मजबूत भ्रामक विकल्प है।', 2, 0, 2, NULL, 'In which language did Swami Dayanand Saraswati primarily write ''Satyarth Prakash''?', '**✅ Correct Logic:** Although Dayanand ji was Gujarati and a Sanskrit scholar, on the advice of Keshav Chandra Sen, he wrote ''Satyarth Prakash'' (1875) in ''Hindi'' to reach the masses.

**💡 Exam Fact:** Arya Samaj was founded in Mumbai (1875), but HQ shifted to Lahore (1877).

**🧠 Memory Tip:** Satyarth Prakash = Light of Truth for **Masses** (Hindi).

**🚫 Scam Alert:** ''Sanskrit'' is a strong distractor because he was a Vedic scholar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9682a6bc-6057-4403-a046-78767b7c4320', '622ec19d-2feb-4f97-9353-3dda30a0438a', '''सत्यशोधक समाज'' (Satyashodhak Samaj) की स्थापना किसने और कब की?', '[{"id":"A","text":"बी.आर. अम्बेडकर, 1920 (B.R. Ambedkar, 1920)","text_en":"बी.आर. अम्बेडकर, 1920 (B.R. Ambedkar, 1920)"},{"id":"B","text":"ज्योतिबा फुले, 1873 (Jyotiba Phule, 1873)","text_en":"ज्योतिबा फुले, 1873 (Jyotiba Phule, 1873)"},{"id":"C","text":"ई.वी. रामास्वामी नायकर, 1925 (E.V. Ramasamy Naicker, 1925)","text_en":"ई.वी. रामास्वामी नायकर, 1925 (E.V. Ramasamy Naicker, 1925)"},{"id":"D","text":"नारायण गुरु, 1903 (Narayana Guru, 1903)","text_en":"नारायण गुरु, 1903 (Narayana Guru, 1903)"}]', '1', '**✅ Correct Logic:** ज्योतिबा फुले ने 24 सितंबर 1873 को पुणे में ''सत्यशोधक समाज'' (Truth Seekers'' Society) की स्थापना की। इसका उद्देश्य निम्न जातियों को ब्राह्मणवादी शोषण से मुक्त कराना था। उनकी प्रसिद्ध पुस्तक ''गुलामगिरी'' है।

**💡 Exam Fact:** सावित्रीबाई फुले (भारत की पहली महिला शिक्षिका) इनकी पत्नी थीं।

**🧠 Memory Tip:** Phule = Flower = Truth (Satya) blooms like a flower in 1873.

**🚫 Scam Alert:** अंबेडकर ने ''बहिष्कृत हितकारिणी सभा'' (1924) बनाई थी।', 2, 0, 3, NULL, 'Who founded ''Satyashodhak Samaj'' and when?', '**✅ Correct Logic:** Jyotiba Phule founded ''Satyashodhak Samaj'' in Pune on 24 Sept 1873. Aim was to liberate lower castes from Brahmanical exploitation. His famous book is ''Gulamgiri''.

**💡 Exam Fact:** Savitribai Phule (India''s first female teacher) was his wife.

**🧠 Memory Tip:** Phule = Flower = Truth (Satya) blooms like a flower in 1873.

**🚫 Scam Alert:** Ambedkar founded ''Bahishkrit Hitakarini Sabha'' (1924).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3c79114b-6cdf-4559-99c1-04bf41007295', '622ec19d-2feb-4f97-9353-3dda30a0438a', 'समाज सुधारकों को उनके संगठनों/संस्थाओं से सुमेलित करें (Match the Social Reformers with their Organizations):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)","text_en":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)"},{"id":"D","text":"(1)-(c), (2)-(a), (3)-(b), (4)-(d)","text_en":"(1)-(c), (2)-(a), (3)-(b), (4)-(d)"}]', '0', '**✅ Correct Logic:**
* **केशव चंद्र सेन:** ब्रह्म समाज के विभाजन (1866) के बाद ''भारतीय ब्रह्म समाज'' बनाया।
* **देवेन्द्रनाथ:** आदि ब्रह्म समाज (मूल) और तत्वबोधिनी सभा (1839)।
* **आत्माराम:** केशव चंद्र सेन की प्रेरणा से बंबई में प्रार्थना समाज (1867)।
* **विवेकानंद:** बेलूर मठ और रामकृष्ण मिशन (1897)।

**💡 Exam Fact:** महादेव गोविंद रानाडे प्रार्थना समाज के वास्तविक संचालक थे, पर संस्थापक आत्माराम थे।

**🧠 Memory Tip:** Keshav = India (Brahmo Samaj of **India**). Debendra = Dad (Adi/Old).

**🚫 Scam Alert:** ब्रह्म समाज के दो टुकड़े हुए थे, केशव वाला ''भारतीय'' था और देवेन्द्र वाला ''आदि'' था।', 2, 0, 5, NULL, 'Match the Social Reformers with their Organizations:', '**✅ Correct Logic:**
* **Keshav Chandra Sen:** Formed ''Brahmo Samaj of India'' after split (1866).
* **Debendranath:** Adi Brahmo Samaj and Tattvabodhini Sabha (1839).
* **Atmaram:** Prarthana Samaj (1867) in Bombay inspired by Keshav.
* **Vivekananda:** Ramakrishna Mission (1897).

**💡 Exam Fact:** MG Ranade was the real force behind Prarthana Samaj, but Atmaram was founder.

**🧠 Memory Tip:** Keshav = India (Brahmo Samaj of **India**). Debendra = Dad (Adi/Old).

**🚫 Scam Alert:** Brahmo Samaj split: Keshav''s was ''of India'', Debendra''s was ''Adi'' (Original).', 60, 'matching', '[{"id":"(1)","label":"केशव चंद्र सेन (Keshav Chandra Sen)","match":"भारतीय ब्रह्म समाज (Brahmo Samaj of India)","matchId":"(b)"},{"id":"(2)","label":"देवेन्द्रनाथ टैगोर (Debendranath Tagore)","match":"तत्वबोधिनी सभा (Tattvabodhini Sabha)","matchId":"(a)"},{"id":"(3)","label":"आत्माराम पांडुरंग (Atmaram Pandurang)","match":"प्रार्थना समाज (Prarthana Samaj)","matchId":"(d)"},{"id":"(4)","label":"स्वामी विवेकानंद (Swami Vivekananda)","match":"रामकृष्ण मिशन (Ramakrishna Mission)","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4d18999d-2e2b-4584-a9cb-69e07001e41e', '622ec19d-2feb-4f97-9353-3dda30a0438a', 'अलीगढ़ आंदोलन (Aligarh Movement) का मुख्य उद्देश्य क्या था?', '[{"id":"A","text":"मुसलमानों में आधुनिक शिक्षा और अंग्रेजी का प्रसार (Spread of modern education and English among Muslims)","text_en":"मुसलमानों में आधुनिक शिक्षा और अंग्रेजी का प्रसार (Spread of modern education and English among Muslims)"},{"id":"B","text":"ब्रिटिश शासन का विरोध (Opposition to British rule)","text_en":"ब्रिटिश शासन का विरोध (Opposition to British rule)"},{"id":"C","text":"खिलाफत की स्थापना (Establishment of Caliphate)","text_en":"खिलाफत की स्थापना (Establishment of Caliphate)"},{"id":"D","text":"हिंदू-मुस्लिम एकता (Hindu-Muslim Unity)","text_en":"हिंदू-मुस्लिम एकता (Hindu-Muslim Unity)"}]', '0', '**✅ Correct Logic:** सर सैयद अहमद खान ने 1875 में ''मुहम्मदन एंग्लो-ओरिएंटल कॉलेज'' (बाद में AMU) की स्थापना की। उनका मानना था कि कुरान की शिक्षा और आधुनिक विज्ञान/अंग्रेजी में कोई विरोध नहीं है। वे मुसलमानों को सरकारी नौकरियों के योग्य बनाना चाहते थे।

**💡 Exam Fact:** उन्होंने ''तहज़ीब-उल-अखलाक'' पत्रिका निकाली।

**🧠 Memory Tip:** Aligarh = **A**nglo (English) Education.

**🚫 Scam Alert:** शुरू में वे हिंदू-मुस्लिम एकता के समर्थक थे, लेकिन आंदोलन का ''कोर'' उद्देश्य आधुनिक शिक्षा था।', 2, 0, 4, NULL, 'What was the main objective of the Aligarh Movement?', '**✅ Correct Logic:** Sir Syed Ahmed Khan founded ''Muhammadan Anglo-Oriental College'' (later AMU) in 1875. He believed Quranic teachings and modern science/English were compatible. Aim was to make Muslims eligible for govt jobs.

**💡 Exam Fact:** He published ''Tahzib-ul-Akhlaq'' journal.

**🧠 Memory Tip:** Aligarh = **A**nglo (English) Education.

**🚫 Scam Alert:** Initially he supported unity, but the ''Core'' objective was Modern Education.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ae4e277a-9408-40b1-b368-d50977ddf289', '622ec19d-2feb-4f97-9353-3dda30a0438a', '''यंग बंगाल आंदोलन'' (Young Bengal Movement) के प्रणेता कौन थे?', '[{"id":"A","text":"राजा राममोहन राय (Raja Ram Mohan Roy)","text_en":"राजा राममोहन राय (Raja Ram Mohan Roy)"},{"id":"B","text":"हेनरी विवियन डेरोजियो (Henry Vivian Derozio)","text_en":"हेनरी विवियन डेरोजियो (Henry Vivian Derozio)"},{"id":"C","text":"डेविड हेयर (David Hare)","text_en":"डेविड हेयर (David Hare)"},{"id":"D","text":"ईश्वर चंद्र विद्यासागर (Ishwar Chandra Vidyasagar)","text_en":"ईश्वर चंद्र विद्यासागर (Ishwar Chandra Vidyasagar)"}]', '1', '**✅ Correct Logic:** हेनरी विवियन डेरोजियो, हिंदू कॉलेज के एक युवा एंग्लो-इंडियन शिक्षक थे। वे फ्रांसीसी क्रांति से प्रेरित थे और छात्रों को तर्क (Logic) और प्रश्न पूछने के लिए प्रेरित करते थे। उनके अनुयायियों को ''डेरोजियन्स'' कहा जाता था।

**💡 Exam Fact:** उन्हें ''आधुनिक भारत का प्रथम राष्ट्रवादी कवि'' भी माना जाता है।

**🧠 Memory Tip:** Young = Derozio (He died very young at 22).

**🚫 Scam Alert:** डेविड हेयर उनके सहयोगी थे, लेकिन आंदोलन डेरोजियो का था।', 2, 0, 6, NULL, 'Who was the leader of the ''Young Bengal Movement''?', '**✅ Correct Logic:** Henry Vivian Derozio was a young Anglo-Indian teacher at Hindu College. Inspired by the French Revolution, he encouraged students to use Logic. Followers were called ''Derozians''.

**💡 Exam Fact:** Considered ''First Nationalist Poet of Modern India''.

**🧠 Memory Tip:** Young = Derozio (He died very young at 22).

**🚫 Scam Alert:** David Hare was an associate, but the movement belonged to Derozio.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9411be02-6b0a-4ab0-8a57-35750fd7e51f', '622ec19d-2feb-4f97-9353-3dda30a0438a', 'शिकागो में ''विश्व धर्म संसद'' (Parliament of World''s Religions) में स्वामी विवेकानंद ने अपना ऐतिहासिक भाषण कब दिया था?', '[{"id":"A","text":"1891","text_en":"1891"},{"id":"B","text":"1893","text_en":"1893"},{"id":"C","text":"1897","text_en":"1897"},{"id":"D","text":"1899","text_en":"1899"}]', '1', '**✅ Correct Logic:** 11 सितंबर 1893 को शिकागो में उन्होंने "अमेरिका के भाइयों और बहनों" कहकर भाषण शुरू किया। इसने हिंदू धर्म को विश्व पटल पर स्थापित किया।

**💡 Exam Fact:** खेतड़ी के महाराज (अजीत सिंह) ने उन्हें ''विवेकानंद'' नाम दिया था और शिकागो जाने का खर्च उठाया था।

**🧠 Memory Tip:** 1893 -> Gandhi went to Africa, Annie Besant came to India, Vivekananda went to America. Big Year!

**🚫 Scam Alert:** 1897 में रामकृष्ण मिशन की स्थापना हुई थी। भाषण 1893 में था।', 2, 0, 7, NULL, 'When did Swami Vivekananda deliver his historic speech at the ''Parliament of World''s Religions'' in Chicago?', '**✅ Correct Logic:** On 11 Sept 1893, in Chicago, he started with "Sisters and Brothers of America". This placed Hinduism on the world map.

**💡 Exam Fact:** Maharaja of Khetri (Ajit Singh) gave him the name ''Vivekananda'' and sponsored the trip.

**🧠 Memory Tip:** 1893 -> Gandhi went to Africa, Annie Besant came to India, Vivekananda went to America. Big Year!

**🚫 Scam Alert:** 1897 is founding of RK Mission. Speech was 1893.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a7b97e8c-68c0-4f43-9b05-3920e89d93c7', '622ec19d-2feb-4f97-9353-3dda30a0438a', '1929 का ''शारदा अधिनियम'' (Sarda Act) मुख्य रूप से किससे संबंधित था?', '[{"id":"A","text":"विधवा पुनर्विवाह (Widow Remarriage)","text_en":"विधवा पुनर्विवाह (Widow Remarriage)"},{"id":"B","text":"बाल विवाह निषेध (Prohibition of Child Marriage)","text_en":"बाल विवाह निषेध (Prohibition of Child Marriage)"},{"id":"C","text":"सती प्रथा का अंत (Abolition of Sati)","text_en":"सती प्रथा का अंत (Abolition of Sati)"},{"id":"D","text":"स्त्री शिक्षा (Women Education)","text_en":"स्त्री शिक्षा (Women Education)"}]', '1', '**✅ Correct Logic:** हरबिलास शारदा के प्रयासों से 1929 में ''बाल विवाह निरोधक अधिनियम'' पास हुआ। इसमें लड़कियों की विवाह आयु 14 वर्ष और लड़कों की 18 वर्ष तय की गई।

**💡 Exam Fact:** यह इरविन (Lord Irwin) के कार्यकाल में पास हुआ।

**🧠 Memory Tip:** Sarda stops **S**mall kids form marriage.

**🚫 Scam Alert:** ''सती'' 1829 (बेंटिक) है, ''शारदा'' 1929 (इरविन) है। 100 साल का अंतर है।', 2, 0, 8, NULL, 'The ''Sarda Act'' of 1929 was primarily related to what?', '**✅ Correct Logic:** Passed in 1929 due to efforts of Harbilas Sarda. It fixed marriage age for girls at 14 and boys at 18.

**💡 Exam Fact:** Passed during tenure of Lord Irwin.

**🧠 Memory Tip:** Sarda stops **S**mall kids form marriage.

**🚫 Scam Alert:** ''Sati'' is 1829 (Bentinck), ''Sarda'' is 1929 (Irwin). 100 years gap.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('339183e4-dfba-448e-9e6d-45f77e835a90', '622ec19d-2feb-4f97-9353-3dda30a0438a', 'थियोसोफिकल सोसाइटी (Theosophical Society) का अंतर्राष्ट्रीय मुख्यालय भारत में कहाँ स्थापित किया गया था?', '[{"id":"A","text":"बेलूर (Belur)","text_en":"बेलूर (Belur)"},{"id":"B","text":"अड्यार (Adyar)","text_en":"अड्यार (Adyar)"},{"id":"C","text":"पुणे (Pune)","text_en":"पुणे (Pune)"},{"id":"D","text":"ऋषिकेश (Rishikesh)","text_en":"ऋषिकेश (Rishikesh)"}]', '1', '**✅ Correct Logic:** थियोसोफिकल सोसाइटी की स्थापना न्यूयॉर्क (1875) में हुई थी, लेकिन 1882 में इसका मुख्यालय मद्रास के पास ''अड्यार'' (Adyar) में स्थानांतरित किया गया। एनी बेसेंट ने इसे लोकप्रिय बनाया।

**💡 Exam Fact:** एनी बेसेंट 1917 में कांग्रेस की पहली महिला अध्यक्ष बनीं।

**🧠 Memory Tip:** Theosophy = **A**ddyar (Madras).

**🚫 Scam Alert:** बेलूर रामकृष्ण मिशन का मुख्यालय है।', 2, 0, 9, NULL, 'Where was the International Headquarters of the Theosophical Society established in India?', '**✅ Correct Logic:** Founded in New York (1875), but HQ moved to ''Adyar'' (Madras) in 1882. Annie Besant popularized it.

**💡 Exam Fact:** Annie Besant became first female Congress President in 1917.

**🧠 Memory Tip:** Theosophy = **A**ddyar (Madras).

**🚫 Scam Alert:** Belur is HQ of Ramakrishna Mission.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f0d45283-6c44-4e6c-9844-bc0c6d4ba9f7', '622ec19d-2feb-4f97-9353-3dda30a0438a', '''सर्वेंट्स ऑफ इंडिया सोसाइटी'' (Servants of India Society) की स्थापना 1905 में किसने की थी?', '[{"id":"A","text":"बाल गंगाधर तिलक (Bal Gangadhar Tilak)","text_en":"बाल गंगाधर तिलक (Bal Gangadhar Tilak)"},{"id":"B","text":"गोपाल कृष्ण गोखले (Gopal Krishna Gokhale)","text_en":"गोपाल कृष्ण गोखले (Gopal Krishna Gokhale)"},{"id":"C","text":"लाला लाजपत राय (Lala Lajpat Rai)","text_en":"लाला लाजपत राय (Lala Lajpat Rai)"},{"id":"D","text":"दादाभाई नौरोजी (Dadabhai Naoroji)","text_en":"दादाभाई नौरोजी (Dadabhai Naoroji)"}]', '1', '**✅ Correct Logic:** गोपाल कृष्ण गोखले (गांधीजी के राजनीतिक गुरु) ने पुणे में इसकी स्थापना की। उद्देश्य था - देशसेवा के लिए समर्पित प्रचारक तैयार करना। सदस्यों को सादगी से रहना होता था।

**💡 Exam Fact:** श्रीनिवास शास्त्री और हृदयनाथ कुंजरू इसके प्रमुख सदस्य थे।

**🧠 Memory Tip:** Gokhale -> **G**andhi''s Guru -> Servants of Nation.

**🚫 Scam Alert:** तिलक उग्रवादी थे, गोखले उदारवादी थे। यह संस्था रचनात्मक कार्य (Constructive work) के लिए थी।', 2, 0, 10, NULL, 'Who founded the ''Servants of India Society'' in 1905?', '**✅ Correct Logic:** Gopal Krishna Gokhale (Gandhi''s political guru) founded it in Pune. Aim was to train missionaries for service of India. Members lived simply.

**💡 Exam Fact:** Srinivasa Sastri and Hridayanath Kunzru were key members.

**🧠 Memory Tip:** Gokhale -> **G**andhi''s Guru -> Servants of Nation.

**🚫 Scam Alert:** Tilak was extremist, Gokhale moderate. This was for constructive work.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ea9bd8a3-3b1c-4f2b-9c49-26bf08c9a3b6', '8755d3c7-b12c-484a-8096-ea9f6169fb6c', '1857 के विद्रोह के समय भारत का गवर्नर जनरल कौन था?', '[{"id":"A","text":"लॉर्ड डलहौजी (Lord Dalhousie)","text_en":"लॉर्ड डलहौजी (Lord Dalhousie)"},{"id":"B","text":"लॉर्ड कैनिंग (Lord Canning)","text_en":"लॉर्ड कैनिंग (Lord Canning)"},{"id":"C","text":"लॉर्ड कर्जन (Lord Curzon)","text_en":"लॉर्ड कर्जन (Lord Curzon)"},{"id":"D","text":"लॉर्ड बेंटिक (Lord Bentinck)","text_en":"लॉर्ड बेंटिक (Lord Bentinck)"}]', '1', '**✅ Correct Logic:** विद्रोह की शुरुआत लॉर्ड कैनिंग के कार्यकाल (1856-1862) में हुई। विद्रोह के बाद 1858 के अधिनियम से वे भारत के ''पहले वायसराय'' बने।

**💡 Exam Fact:** डलहौजी की ''हड़प नीति'' (Doctrine of Lapse) विद्रोह का एक बड़ा कारण थी, पर विद्रोह कैनिंग के समय फूटा।

**🧠 Memory Tip:** Cunning people survived the revolt -> Lord **Canning**.

**🚫 Scam Alert:** डलहौजी ने बारूद बिछाया, लेकिन धमाका कैनिंग के समय हुआ।', 2, 0, 1, NULL, 'Who was the Governor General of India during the Revolt of 1857?', '**✅ Correct Logic:** Revolt started during Lord Canning''s tenure (1856-1862). After the revolt, he became the ''First Viceroy'' via Act of 1858.

**💡 Exam Fact:** Dalhousie''s ''Doctrine of Lapse'' was a cause, but revolt exploded under Canning.

**🧠 Memory Tip:** Cunning people survived the revolt -> Lord **Canning**.

**🚫 Scam Alert:** Dalhousie laid the gunpowder, but explosion happened under Canning.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c48d3e06-5fc6-48a5-8794-c5a02fab3ffb', '8755d3c7-b12c-484a-8096-ea9f6169fb6c', 'भारतीय राष्ट्रीय कांग्रेस की स्थापना (1885) के समय ''सेफ्टी वाल्व'' (Safety Valve) का सिद्धांत किसने दिया था?', '[{"id":"A","text":"ए.ओ. ह्यूम (A.O. Hume)","text_en":"ए.ओ. ह्यूम (A.O. Hume)"},{"id":"B","text":"लाला लाजपत राय (Lala Lajpat Rai)","text_en":"लाला लाजपत राय (Lala Lajpat Rai)"},{"id":"C","text":"गोपाल कृष्ण गोखले (Gopal Krishna Gokhale)","text_en":"गोपाल कृष्ण गोखले (Gopal Krishna Gokhale)"},{"id":"D","text":"लॉर्ड डफरिन (Lord Dufferin)","text_en":"लॉर्ड डफरिन (Lord Dufferin)"}]', '1', '**✅ Correct Logic:** ''सेफ्टी वाल्व'' सिद्धांत लाला लाजपत राय ने अपने अखबार ''यंग इंडिया'' (1916) में दिया। उनका तर्क था कि अंग्रेजों (ह्यूम और डफरिन) ने 1857 जैसी क्रांति को रोकने के लिए कांग्रेस को एक निकास नली (Safety Valve) के रूप में बनाया।

**💡 Exam Fact:** ह्यूम कांग्रेस के महासचिव थे, लेकिन यह ''सिद्धांत'' (आलोचना) लाजपत राय ने दिया।

**🧠 Memory Tip:** Lala ji exposed the **Valve**.

**🚫 Scam Alert:** ह्यूम संस्थापक थे, डफरिन वायसराय थे, लेकिन ''थ्योरी'' लाला जी की है।', 2, 0, 2, NULL, 'Who gave the ''Safety Valve'' theory regarding the formation of Indian National Congress (1885)?', '**✅ Correct Logic:** Lala Lajpat Rai proposed this theory in ''Young India'' (1916). He argued British (Hume & Dufferin) formed Congress to release pent-up anger and prevent another 1857 (Safety Valve).

**💡 Exam Fact:** Hume was Gen Sec, but the ''Theory'' (Criticism) came from Lajpat Rai.

**🧠 Memory Tip:** Lala ji exposed the **Valve**.

**🚫 Scam Alert:** Hume founded it, Dufferin was Viceroy, but Theory is by Lala ji.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8f693c76-b167-4885-9538-1945e334cd39', '8755d3c7-b12c-484a-8096-ea9f6169fb6c', 'महात्मा गांधी ने भारत में अपना पहला प्रमुख ''सत्याग्रह'' कहाँ किया था?', '[{"id":"A","text":"खेड़ा (Kheda)","text_en":"खेड़ा (Kheda)"},{"id":"B","text":"अहमदाबाद (Ahmedabad)","text_en":"अहमदाबाद (Ahmedabad)"},{"id":"C","text":"चंपारण (Champaran)","text_en":"चंपारण (Champaran)"},{"id":"D","text":"बारदोली (Bardoli)","text_en":"बारदोली (Bardoli)"}]', '2', '**✅ Correct Logic:** गांधीजी का भारत में पहला सत्याग्रह 1917 में बिहार के ''चंपारण'' में नील की खेती करने वाले किसानों (तीनकठिया पद्धति) के समर्थन में था। राजकुमार शुक्ल उन्हें बुलाने गए थे।

**💡 Exam Fact:** अहमदाबाद (1918) में पहली बार ''भूख हड़ताल'' की।

**🧠 Memory Tip:** **C**hamparan = **C**hampion''s debut.

**🚫 Scam Alert:** दक्षिण अफ्रीका में प्रयोग कर चुके थे, पर ''भारत में'' चंपारण पहला था।', 2, 0, 3, NULL, 'Where did Mahatma Gandhi conduct his first major ''Satyagraha'' in India?', '**✅ Correct Logic:** First Satyagraha in India was in ''Champaran'' (Bihar, 1917) against Indigo cultivation (Tinkathia system). Rajkumar Shukla invited him.

**💡 Exam Fact:** First ''Hunger Strike'' was in Ahmedabad (1918).

**🧠 Memory Tip:** **C**hamparan = **C**hampion''s debut.

**🚫 Scam Alert:** He did it in S. Africa, but ''In India'', Champaran was first.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c704e130-bf44-4288-82ec-0cfdabea9155', '8755d3c7-b12c-484a-8096-ea9f6169fb6c', 'क्रांतिकारी घटनाओं को उनके वर्ष से सुमेलित करें (Match the Revolutionary events with their years):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)","text_en":"(1)-(b), (2)-(d), (3)-(a), (4)-(c)"},{"id":"D","text":"(1)-(c), (2)-(a), (3)-(b), (4)-(d)","text_en":"(1)-(c), (2)-(a), (3)-(b), (4)-(d)"}]', '0', '**✅ Correct Logic:**
* **काकोरी:** HRA द्वारा (बिस्मिल, अशफाक)। अब इसे ''काकोरी ट्रेन एक्शन'' कहते हैं।
* **चटगांव:** सूर्य सेन (मास्टर दा)।
* **असेंबली बम:** भगत सिंह और बटुकेश्वर दत्त।
* **गदर:** लाला हरदयाल (सैन फ्रांसिस्को)।

**💡 Exam Fact:** काकोरी कांड 9 अगस्त को हुआ था।

**🧠 Memory Tip:** Ghadar (13) -> Kakori (25) -> Bomb (29) -> Chittagong (30).

**🚫 Scam Alert:** 1929 में सांडर्स हत्या और बम कांड दोनों हैं।', 2, 0, 5, NULL, 'Match the Revolutionary events with their years:', '**✅ Correct Logic:**
* **Kakori:** HRA (Bismil, Ashfaq). Now called ''Train Action''.
* **Chittagong:** Surya Sen (Master Da).
* **Assembly Bomb:** Bhagat Singh & Batukeshwar Dutt.
* **Ghadar:** Lala Hardayal (San Francisco).

**💡 Exam Fact:** Kakori happened on 9th August.

**🧠 Memory Tip:** Ghadar (13) -> Kakori (25) -> Bomb (29) -> Chittagong (30).

**🚫 Scam Alert:** 1929 has both Saunders murder and Bomb case.', 60, 'matching', '[{"id":"(1)","label":"काकोरी ट्रेन एक्शन (Kakori Train Action)","match":"1925","matchId":"(b)"},{"id":"(2)","label":"चटगांव शस्त्रागार छापा (Chittagong Armoury Raid)","match":"1930","matchId":"(a)"},{"id":"(3)","label":"सेंट्रल असेंबली बम कांड (Central Assembly Bomb Case)","match":"1929","matchId":"(d)"},{"id":"(4)","label":"गदर पार्टी स्थापना (Ghadar Party Formation)","match":"1913","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('397562c7-6c47-43d3-b1a3-41c1ef5da0d7', '8755d3c7-b12c-484a-8096-ea9f6169fb6c', '''करो या मरो'' (Do or Die) का नारा गांधीजी ने किस आंदोलन के दौरान दिया था?', '[{"id":"A","text":"असहयोग आंदोलन (Non-Cooperation Movement)","text_en":"असहयोग आंदोलन (Non-Cooperation Movement)"},{"id":"B","text":"सविनय अवज्ञा आंदोलन (Civil Disobedience Movement)","text_en":"सविनय अवज्ञा आंदोलन (Civil Disobedience Movement)"},{"id":"C","text":"भारत छोड़ो आंदोलन (Quit India Movement)","text_en":"भारत छोड़ो आंदोलन (Quit India Movement)"},{"id":"D","text":"खिलाफत आंदोलन (Khilafat Movement)","text_en":"खिलाफत आंदोलन (Khilafat Movement)"}]', '2', '**✅ Correct Logic:** 8 अगस्त 1942 को ग्वालिया टैंक मैदान (मुंबई) में ''भारत छोड़ो आंदोलन'' शुरू करते हुए गांधीजी ने कहा: "मैं आपको एक मंत्र देता हूँ - करो या मरो। हम भारत को आजाद कराएंगे या इस प्रयास में अपनी जान दे देंगे।"

**💡 Exam Fact:** इसी आंदोलन में ''ऑपरेशन जीरो ऑवर'' के तहत सभी बड़े नेता गिरफ्तार कर लिए गए।

**🧠 Memory Tip:** Final Strike = Do or Die = Quit India (1942).

**🚫 Scam Alert:** यह गांधीजी का सबसे उग्र नारा था, जो अहिंसा के उनके सामान्य स्वर से अलग था।', 2, 0, 4, NULL, 'During which movement did Gandhiji give the slogan ''Do or Die''?', '**✅ Correct Logic:** On 8 Aug 1942 at Gowalia Tank (Mumbai), launching ''Quit India'', Gandhi said: "I give you a mantra - Do or Die. We shall either free India or die in the attempt."

**💡 Exam Fact:** Leaders were arrested under ''Operation Zero Hour''.

**🧠 Memory Tip:** Final Strike = Do or Die = Quit India (1942).

**🚫 Scam Alert:** This was his most aggressive slogan, unlike his usual tone.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6e34b7cb-2b7e-4aa7-9f7b-66e045105336', '8755d3c7-b12c-484a-8096-ea9f6169fb6c', 'सुभाष चंद्र बोस ने 1939 में कांग्रेस छोड़ने के बाद किस दल की स्थापना की?', '[{"id":"A","text":"इंडियन नेशनल आर्मी (INA)","text_en":"इंडियन नेशनल आर्मी (INA)"},{"id":"B","text":"फॉरवर्ड ब्लॉक (Forward Bloc)","text_en":"फॉरवर्ड ब्लॉक (Forward Bloc)"},{"id":"C","text":"स्वराज पार्टी (Swaraj Party)","text_en":"स्वराज पार्टी (Swaraj Party)"},{"id":"D","text":"अभिनव भारत (Abhinav Bharat)","text_en":"अभिनव भारत (Abhinav Bharat)"}]', '1', '**✅ Correct Logic:** त्रिपुरी अधिवेशन (1939) में गांधीजी से मतभेद के बाद बोस ने इस्तीफा दिया और कांग्रेस के भीतर ही ''फॉरवर्ड ब्लॉक'' का गठन किया।

**💡 Exam Fact:** INA (आजाद हिंद फौज) की स्थापना रासबिहारी बोस और मोहन सिंह ने की थी, सुभाष ने बाद में कमान संभाली।

**🧠 Memory Tip:** Subhash always moved **Forward**.

**🚫 Scam Alert:** INA का गठन सुभाष ने नहीं किया, उन्होंने उसे पुनर्जीवित (Revive) किया। फॉरवर्ड ब्लॉक उनकी अपनी पार्टी थी।', 2, 0, 6, NULL, 'Which party did Subhash Chandra Bose found after leaving Congress in 1939?', '**✅ Correct Logic:** After differences with Gandhi at Tripuri Session (1939), Bose resigned and formed ''Forward Bloc'' within Congress.

**💡 Exam Fact:** INA was founded by Rashbehari Bose and Mohan Singh; Subhash took over later.

**🧠 Memory Tip:** Subhash always moved **Forward**.

**🚫 Scam Alert:** Bose didn''t found INA, he revived it. Forward Bloc was his baby.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('578e0f67-5228-4942-b202-457d69102ebf', '8755d3c7-b12c-484a-8096-ea9f6169fb6c', '1907 के ''सूरत विभाजन'' (Surat Split) का मुख्य कारण क्या था?', '[{"id":"A","text":"मुस्लिम लीग की स्थापना (Formation of Muslim League)","text_en":"मुस्लिम लीग की स्थापना (Formation of Muslim League)"},{"id":"B","text":"नरम दल और गरम दल के बीच अध्यक्ष पद और बहिष्कार नीति को लेकर मतभेद (Differences between Moderates and Extremists regarding Presidency and Boycott policy)","text_en":"नरम दल और गरम दल के बीच अध्यक्ष पद और बहिष्कार नीति को लेकर मतभेद (Differences between Moderates and Extremists regarding Presidency and Boycott policy)"},{"id":"C","text":"बंगाल विभाजन का रद्द होना (Annulment of Bengal Partition)","text_en":"बंगाल विभाजन का रद्द होना (Annulment of Bengal Partition)"},{"id":"D","text":"राजधानी का स्थानांतरण (Transfer of Capital)","text_en":"राजधानी का स्थानांतरण (Transfer of Capital)"}]', '1', '**✅ Correct Logic:** गरम दल (तिलक, लाला जी) चाहते थे कि स्वदेशी आंदोलन पूरे भारत में फैले और तिलक अध्यक्ष बनें। नरम दल (गोखले, फिरोजशाह) इसे बंगाल तक सीमित रखना चाहते थे और रासबिहारी घोष को अध्यक्ष बनाना चाहते थे। इस पर मारपीट हो गई।

**💡 Exam Fact:** विभाजन ताप्ती नदी के किनारे हुआ। 1916 (लखनऊ) में फिर एक हुए।

**🧠 Memory Tip:** Surat = Face. They punched each other''s faces (Split).

**🚫 Scam Alert:** रासबिहारी ''घोष'' (नरम) अध्यक्ष बने, रासबिहारी ''बोस'' (क्रांतिकारी) नहीं।', 2, 0, 7, NULL, 'What was the main reason for the ''Surat Split'' of 1907?', '**✅ Correct Logic:** Extremists (Tilak) wanted Swadeshi across India and Tilak as President. Moderates (Gokhale) wanted to limit it to Bengal and wanted Rashbehari Ghosh. This led to a fight.

**💡 Exam Fact:** Happened on banks of Tapti. Reunited in 1916 (Lucknow).

**🧠 Memory Tip:** Surat = Face. They punched each other''s faces (Split).

**🚫 Scam Alert:** Rashbehari ''Ghosh'' (Moderate) became prez, not ''Bose'' (Revolutionary).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('146da1e4-dc31-41e0-979b-5c487bbc99be', '8755d3c7-b12c-484a-8096-ea9f6169fb6c', '''पूना पैक्ट'' (1932) किनके बीच हस्ताक्षरित हुआ था?', '[{"id":"A","text":"गांधीजी और इरविन (Gandhiji and Irwin)","text_en":"गांधीजी और इरविन (Gandhiji and Irwin)"},{"id":"B","text":"गांधीजी और अंबेडकर (Gandhiji and Ambedkar)","text_en":"गांधीजी और अंबेडकर (Gandhiji and Ambedkar)"},{"id":"C","text":"अंबेडकर और मैकडोनाल्ड (Ambedkar and MacDonald)","text_en":"अंबेडकर और मैकडोनाल्ड (Ambedkar and MacDonald)"},{"id":"D","text":"नेहरू और जिन्ना (Nehru and Jinnah)","text_en":"नेहरू और जिन्ना (Nehru and Jinnah)"}]', '1', '**✅ Correct Logic:** मैकडोनाल्ड के ''सांप्रदायिक पंचाट'' (Communal Award) में दलितों को पृथक निर्वाचन (Separate Electorate) देने के विरोध में गांधीजी ने जेल में अनशन किया। अंततः अंबेडकर और गांधीजी (मदन मोहन मालवीय ने गांधी की ओर से साइन किए) के बीच समझौता हुआ। दलितों को पृथक निर्वाचन की जगह आरक्षित सीटें (Reserved Seats) मिलीं।

**💡 Exam Fact:** यह यरवदा जेल (पुणे) में हुआ।

**🧠 Memory Tip:** Poona = Pact for Depressed Classes.

**🚫 Scam Alert:** गांधीजी ने खुद साइन नहीं किए थे, मालवीय जी ने किए थे, लेकिन समझौता गांधी-अंबेडकर के बीच ही माना जाता है।', 2, 0, 8, NULL, 'Between whom was the ''Poona Pact'' (1932) signed?', '**✅ Correct Logic:** Gandhi fasted in jail against ''Separate Electorate'' for Dalits in Communal Award. Finally, pact was signed between Ambedkar and Gandhi (MM Malviya signed for Gandhi). Dalits got Reserved Seats instead of Separate Electorate.

**💡 Exam Fact:** Happened in Yerwada Jail.

**🧠 Memory Tip:** Poona = Pact for Depressed Classes.

**🚫 Scam Alert:** Gandhi didn''t sign personally (Malviya did), but it''s known as Gandhi-Ambedkar pact.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5d00f66c-b17d-4eb2-b6b6-dfe69d0b2bd7', '8755d3c7-b12c-484a-8096-ea9f6169fb6c', 'जलियांवाला बाग हत्याकांड (1919) के विरोध में किसने अपनी ''नाइटहुड'' (Knighthood) की उपाधि लौटा दी थी?', '[{"id":"A","text":"महात्मा गांधी (Mahatma Gandhi)","text_en":"महात्मा गांधी (Mahatma Gandhi)"},{"id":"B","text":"रवींद्रनाथ टैगोर (Rabindranath Tagore)","text_en":"रवींद्रनाथ टैगोर (Rabindranath Tagore)"},{"id":"C","text":"शंकरन नायर (Sankaran Nair)","text_en":"शंकरन नायर (Sankaran Nair)"},{"id":"D","text":"मोतीलाल नेहरू (Motilal Nehru)","text_en":"मोतीलाल नेहरू (Motilal Nehru)"}]', '1', '**✅ Correct Logic:** रवींद्रनाथ टैगोर ने वायसराय को पत्र लिखकर अपनी ''सर/नाइटहुड'' की उपाधि त्यागी और कहा: "सम्मान के तमगे अब हमारे अपमान को बेपर्दा करते हैं।"

**💡 Exam Fact:** गांधीजी ने ''कैसर-ए-हिंद'' की उपाधि असहयोग आंदोलन (1920) के दौरान लौटाई थी। शंकरन नायर ने वायसराय की कार्यकारिणी से इस्तीफा दिया था।

**🧠 Memory Tip:** Tagore = Night (Knight) is dark due to massacre.

**🚫 Scam Alert:** गांधी ने कैसर-ए-हिंद लौटाई, टैगोर ने नाइटहुड। दोनों अलग हैं।', 2, 0, 9, NULL, 'Who returned his ''Knighthood'' title in protest against the Jallianwala Bagh Massacre (1919)?', '**✅ Correct Logic:** Rabindranath Tagore returned his ''Knighthood'' writing: "Badges of honour make our shame glaring..."

**💡 Exam Fact:** Gandhi returned ''Kaiser-i-Hind'' during Non-Cooperation (1920). Sankaran Nair resigned from Viceroy''s Executive Council.

**🧠 Memory Tip:** Tagore = Night (Knight) is dark due to massacre.

**🚫 Scam Alert:** Gandhi returned Kaiser-i-Hind, Tagore returned Knighthood.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d44cf82a-06f6-4b87-8afc-6d4b170f8329', '8755d3c7-b12c-484a-8096-ea9f6169fb6c', 'भारत के विभाजन के समय (1947) भारतीय राष्ट्रीय कांग्रेस के अध्यक्ष कौन थे?', '[{"id":"A","text":"जवाहरलाल नेहरू (Jawaharlal Nehru)","text_en":"जवाहरलाल नेहरू (Jawaharlal Nehru)"},{"id":"B","text":"जे.बी. कृपलानी (J.B. Kripalani)","text_en":"जे.बी. कृपलानी (J.B. Kripalani)"},{"id":"C","text":"मौलाना आजाद (Maulana Azad)","text_en":"मौलाना आजाद (Maulana Azad)"},{"id":"D","text":"सरदार पटेल (Sardar Patel)","text_en":"सरदार पटेल (Sardar Patel)"}]', '1', '**✅ Correct Logic:** स्वतंत्रता के समय (अगस्त 1947) जे.बी. कृपलानी कांग्रेस अध्यक्ष थे। उन्होंने मेरठ अधिवेशन (1946) में अध्यक्षता संभाली थी।

**💡 Exam Fact:** मौलाना आजाद सबसे लंबे समय तक (1940-46) अध्यक्ष रहे।

**🧠 Memory Tip:** Kripalani = **Kripa** (Grace) needed during Partition crisis.

**🚫 Scam Alert:** नेहरू पीएम बने, लेकिन पार्टी अध्यक्ष कृपलानी थे।', 2, 0, 10, NULL, 'Who was the President of Indian National Congress at the time of Partition of India (1947)?', '**✅ Correct Logic:** J.B. Kripalani was Congress President during independence (Aug 1947). He took over in Meerut Session (1946).

**💡 Exam Fact:** Maulana Azad was president for longest continuous term (1940-46).

**🧠 Memory Tip:** Kripalani = **Kripa** (Grace) needed during Partition crisis.

**🚫 Scam Alert:** Nehru became PM, but Party Prez was Kripalani.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('76c6eb75-22c1-4e06-bb8e-3b8d9a6ba8ae', 'a12aa742-7b0e-4e02-86b8-87233f212e99', 'सरदार वल्लभभाई पटेल ने ''ऑपरेशन पोलो'' (Operation Polo) किस रियासत को भारत में मिलाने के लिए चलाया था?', '[{"id":"A","text":"जूनागढ़ (Junagadh)","text_en":"जूनागढ़ (Junagadh)"},{"id":"B","text":"कश्मीर (Kashmir)","text_en":"कश्मीर (Kashmir)"},{"id":"C","text":"हैदराबाद (Hyderabad)","text_en":"हैदराबाद (Hyderabad)"},{"id":"D","text":"गोवा (Goa)","text_en":"गोवा (Goa)"}]', '2', '**✅ Correct Logic:** हैदराबाद का निजाम भारत में मिलने को तैयार नहीं था और रजाकारों (निजी सेना) का आतंक था। सितंबर 1948 में पुलिस कार्रवाई (सैन्य बल) द्वारा उसे मिलाया गया। इस गुप्त सैन्य अभियान का नाम ''ऑपरेशन पोलो'' था।

**💡 Exam Fact:** जूनागढ़ में ''जनमत संग्रह'' (Referendum) हुआ था।

**🧠 Memory Tip:** Hyderabad had many **Polo** grounds.

**🚫 Scam Alert:** यह ''पुलिस कार्रवाई'' थी, पूर्ण ''युद्ध'' नहीं कहा गया।', 2, 0, 1, NULL, 'Sardar Vallabhbhai Patel launched ''Operation Polo'' to integrate which princely state into India?', '**✅ Correct Logic:** Nizam of Hyderabad refused to join India. In Sept 1948, Police Action (Military force) was used to integrate it. Code name was ''Operation Polo''.

**💡 Exam Fact:** Junagadh had a ''Referendum''.

**🧠 Memory Tip:** Hyderabad had many **Polo** grounds.

**🚫 Scam Alert:** Termed ''Police Action'', not ''War''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('355d1d4e-a7c2-4632-9651-7b2270f44755', 'a12aa742-7b0e-4e02-86b8-87233f212e99', 'भाषाई आधार पर गठित होने वाला भारत का पहला राज्य कौन सा था?', '[{"id":"A","text":"महाराष्ट्र (Maharashtra)","text_en":"महाराष्ट्र (Maharashtra)"},{"id":"B","text":"आंध्र प्रदेश (Andhra Pradesh)","text_en":"आंध्र प्रदेश (Andhra Pradesh)"},{"id":"C","text":"तमिलनाडु (Tamil Nadu)","text_en":"तमिलनाडु (Tamil Nadu)"},{"id":"D","text":"गुजरात (Gujarat)","text_en":"गुजरात (Gujarat)"}]', '1', '**✅ Correct Logic:** पोट्टी श्रीरामुलु के 56 दिनों के अनशन और मृत्यु के बाद भड़के दंगों के कारण 1 अक्टूबर 1953 को मद्रास से अलग करके ''आंध्र प्रदेश'' (तेलुगु भाषी) बनाया गया।

**💡 Exam Fact:** इसके बाद ही 1953 में ''फजल अली आयोग'' (राज्य पुनर्गठन आयोग) बना।

**🧠 Memory Tip:** Andhra = First Alphabet ''A'' = First State.

**🚫 Scam Alert:** 1956 का एक्ट बाद में आया, आंध्र 1953 में ही बन गया था।', 2, 0, 2, NULL, 'Which was the first state in India to be formed on linguistic basis?', '**✅ Correct Logic:** Following the death of Potti Sriramulu after 56 days hunger strike, ''Andhra Pradesh'' (Telugu) was carved out of Madras on 1 Oct 1953.

**💡 Exam Fact:** This forced the formation of ''Fazl Ali Commission'' (1953).

**🧠 Memory Tip:** Andhra = First Alphabet ''A'' = First State.

**🚫 Scam Alert:** Act came in 1956, but Andhra was created in 1953.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c3b8647a-9907-4508-a28d-33091a7eca6b', 'a12aa742-7b0e-4e02-86b8-87233f212e99', 'राज्य पुनर्गठन अधिनियम, 1956 के तहत भारत में कितने राज्य और केंद्र शासित प्रदेश बनाए गए?', '[{"id":"A","text":"14 राज्य, 6 केंद्र शासित प्रदेश (14 States, 6 UTs)","text_en":"14 राज्य, 6 केंद्र शासित प्रदेश (14 States, 6 UTs)"},{"id":"B","text":"16 राज्य, 3 केंद्र शासित प्रदेश (16 States, 3 UTs)","text_en":"16 राज्य, 3 केंद्र शासित प्रदेश (16 States, 3 UTs)"},{"id":"C","text":"28 राज्य, 8 केंद्र शासित प्रदेश (28 States, 8 UTs)","text_en":"28 राज्य, 8 केंद्र शासित प्रदेश (28 States, 8 UTs)"},{"id":"D","text":"29 राज्य, 7 केंद्र शासित प्रदेश (29 States, 7 UTs)","text_en":"29 राज्य, 7 केंद्र शासित प्रदेश (29 States, 7 UTs)"}]', '0', '**✅ Correct Logic:** फजल अली आयोग की सिफारिशों (कुछ संशोधनों के साथ) पर 1956 में A, B, C, D श्रेणी के राज्यों को समाप्त कर 14 राज्य और 6 UTs बनाए गए।

**💡 Exam Fact:** 7वें संविधान संशोधन (1956) द्वारा यह लागू हुआ।

**🧠 Memory Tip:** 1956 -> 14 & 6. (Double of 7 is 14).

**🚫 Scam Alert:** वर्तमान संख्या (28, 8) से कन्फ्यूज न हों। 1956 का डेटा पूछा है।', 2, 0, 3, NULL, 'How many States and Union Territories were created under the States Reorganization Act, 1956?', '**✅ Correct Logic:** Based on Fazl Ali Commission, the A, B, C, D categories were abolished and 14 States & 6 UTs were formed in 1956.

**💡 Exam Fact:** Implemented by 7th Constitutional Amendment (1956).

**🧠 Memory Tip:** 1956 -> 14 & 6. (Double of 7 is 14).

**🚫 Scam Alert:** Don''t confuse with current data (28, 8). Question asks for 1956.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d9a7be04-2261-4367-bcb0-d78e0da83d2a', 'a12aa742-7b0e-4e02-86b8-87233f212e99', 'रियासतों के विलय के माध्यम को सुमेलित करें (Match the Princely States with mode of integration):', '[{"id":"A","text":"(1)-(b), (2)-(c), (3)-(a), (4)-(d)","text_en":"(1)-(b), (2)-(c), (3)-(a), (4)-(d)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(a), (3)-(b), (4)-(d)","text_en":"(1)-(c), (2)-(a), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)","text_en":"(1)-(b), (2)-(a), (3)-(c), (4)-(d)"}]', '0', '**✅ Correct Logic:**
* **J&K:** राजा हरि सिंह ने पाक आक्रमण के बाद विलय पत्र (26 Oct 1947) पर साइन किए।
* **हैदराबाद:** ऑपरेशन पोलो।
* **जूनागढ़:** दीवान शाहनवाज भुट्टो के भागने के बाद जनता ने वोट (Referendum) दिया।
* **मणिपुर:** बोधचंद्र सिंह पर दबाव डालकर विलय समझौता हुआ।

**💡 Exam Fact:** वी.पी. मेनन रियासती विभाग के सचिव थे।

**🧠 Memory Tip:** Kashmir = Paper sign. Hyderabad = Police danda. Junagadh = Public vote.

**🚫 Scam Alert:** जूनागढ़ और हैदराबाद के तरीके अक्सर बदल दिए जाते हैं।', 2, 0, 5, NULL, 'Match the Princely States with mode of integration:', '**✅ Correct Logic:**
* **J&K:** Hari Singh signed Instrument of Accession (26 Oct 1947).
* **Hyderabad:** Operation Polo.
* **Junagadh:** Referendum (Public vote) after Diwan fled.
* **Manipur:** King Bodhchandra Singh signed Merger Agreement.

**💡 Exam Fact:** VP Menon was Secretary of States Department.

**🧠 Memory Tip:** Kashmir = Paper sign. Hyderabad = Police danda. Junagadh = Public vote.

**🚫 Scam Alert:** Junagadh and Hyderabad modes are often swapped.', 60, 'matching', '[{"id":"(1)","label":"जम्मू और कश्मीर (Jammu & Kashmir)","match":"विलय पत्र (Instrument of Accession)","matchId":"(b)"},{"id":"(2)","label":"हैदराबाद (Hyderabad)","match":"पुलिस कार्रवाई (Police Action)","matchId":"(c)"},{"id":"(3)","label":"जूनागढ़ (Junagadh)","match":"जनमत संग्रह (Referendum)","matchId":"(a)"},{"id":"(4)","label":"मणिपुर (Manipur)","match":"विलय समझौता (Merger Agreement)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8d9e7e41-f100-49db-9cc9-582bb2913379', 'a12aa742-7b0e-4e02-86b8-87233f212e99', 'सिक्किम भारत का ''पूर्ण राज्य'' (Full State) किस वर्ष बना?', '[{"id":"A","text":"1974","text_en":"1974"},{"id":"B","text":"1975","text_en":"1975"},{"id":"C","text":"1961","text_en":"1961"},{"id":"D","text":"1987","text_en":"1987"}]', '1', '**✅ Correct Logic:** 36वें संविधान संशोधन, 1975 द्वारा सिक्किम को भारत का 22वां पूर्ण राज्य बनाया गया। इससे पहले 35वें संशोधन (1974) से उसे ''सह-राज्य'' (Associate State) का दर्जा मिला था। वहां चोग्याल वंश का शासन था।

**💡 Exam Fact:** गोवा 1987 में पूर्ण राज्य बना (1961 में केवल आजाद हुआ था)।

**🧠 Memory Tip:** Sikkim = Seven-Five (75).

**🚫 Scam Alert:** 1974 में ''सह-राज्य'' था, पूर्ण राज्य 1975 में बना।', 2, 0, 4, NULL, 'In which year did Sikkim become a ''Full State'' of India?', '**✅ Correct Logic:** By 36th Amendment 1975, Sikkim became the 22nd full state. Before that, 35th Amendment (1974) made it an ''Associate State''. It was ruled by Chogyal dynasty.

**💡 Exam Fact:** Goa became full state in 1987 (Liberated in 1961).

**🧠 Memory Tip:** Sikkim = Seven-Five (75).

**🚫 Scam Alert:** In 1974 it was ''Associate'', Full state in 1975.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ce6d33ed-545a-4f3a-baa2-43dd48b8b680', 'a12aa742-7b0e-4e02-86b8-87233f212e99', 'गोवा को पुर्तगालियों से मुक्त कराने के लिए भारतीय सेना ने 1961 में कौन सा ऑपरेशन चलाया था?', '[{"id":"A","text":"ऑपरेशन विजय (Operation Vijay)","text_en":"ऑपरेशन विजय (Operation Vijay)"},{"id":"B","text":"ऑपरेशन मेघदूत (Operation Meghdoot)","text_en":"ऑपरेशन मेघदूत (Operation Meghdoot)"},{"id":"C","text":"ऑपरेशन कैक्टस (Operation Cactus)","text_en":"ऑपरेशन कैक्टस (Operation Cactus)"},{"id":"D","text":"ऑपरेशन ब्लू स्टार (Operation Blue Star)","text_en":"ऑपरेशन ब्लू स्टार (Operation Blue Star)"}]', '0', '**✅ Correct Logic:** 18-19 दिसंबर 1961 को ''ऑपरेशन विजय'' के तहत भारतीय सेना ने गोवा, दमन और दीव को पुर्तगालियों से आजाद कराया। पुर्तगाली गवर्नर ने आत्मसमर्पण किया।

**💡 Exam Fact:** कारगिल युद्ध (1999) का नाम भी ''ऑपरेशन विजय'' था।

**🧠 Memory Tip:** Victory over Portuguese = Operation **Vijay**.

**🚫 Scam Alert:** पुर्तगाली सबसे पहले आए (1498) और सबसे बाद में गए (1961)।', 2, 0, 6, NULL, 'Which operation was launched by Indian Army in 1961 to liberate Goa from Portuguese?', '**✅ Correct Logic:** Under ''Operation Vijay'' (18-19 Dec 1961), Indian Army liberated Goa, Daman & Diu. Portuguese Governor surrendered.

**💡 Exam Fact:** Kargil War (1999) was also named ''Operation Vijay''.

**🧠 Memory Tip:** Victory over Portuguese = Operation **Vijay**.

**🚫 Scam Alert:** Portuguese came first (1498) and left last (1961).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a49c4a9f-6bc1-4178-aadf-e9195e2af986', 'a12aa742-7b0e-4e02-86b8-87233f212e99', 'राज्य पुनर्गठन आयोग (1953) के अध्यक्ष कौन थे?', '[{"id":"A","text":"के.एम. पणिक्कर (K.M. Panikkar)","text_en":"के.एम. पणिक्कर (K.M. Panikkar)"},{"id":"B","text":"हृदयनाथ कुंजरू (Hridayanath Kunzru)","text_en":"हृदयनाथ कुंजरू (Hridayanath Kunzru)"},{"id":"C","text":"फजल अली (Fazl Ali)","text_en":"फजल अली (Fazl Ali)"},{"id":"D","text":"एस.के. धर (S.K. Dhar)","text_en":"एस.के. धर (S.K. Dhar)"}]', '2', '**✅ Correct Logic:** 1953 में गठित आयोग के अध्यक्ष न्यायमूर्ति ''फजल अली'' थे। अन्य दो सदस्य के.एम. पणिक्कर और एच.एन. कुंजरू थे। इसलिए इसे ''फजल अली आयोग'' भी कहते हैं।

**💡 Exam Fact:** एस.के. धर आयोग (1948) ने भाषाई आधार को खारिज किया था।

**🧠 Memory Tip:** Fazl Ali = Father of States Reorganization.

**🚫 Scam Alert:** तीनों सदस्य थे, लेकिन ''अध्यक्ष'' फजल अली थे।', 2, 0, 7, NULL, 'Who was the Chairman of the States Reorganization Commission (1953)?', '**✅ Correct Logic:** Justice ''Fazl Ali'' was the Chairman. Other two members were KM Panikkar and HN Kunzru. Hence called ''Fazl Ali Commission''.

**💡 Exam Fact:** SK Dhar Commission (1948) had rejected linguistic basis.

**🧠 Memory Tip:** Fazl Ali = Father of States Reorganization.

**🚫 Scam Alert:** All three were members, but ''Chairman'' was Fazl Ali.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2d9ef614-c20d-4911-9416-de951cf2a45a', 'a12aa742-7b0e-4e02-86b8-87233f212e99', 'स्वतंत्रता के बाद ''रियासती मंत्रालय'' (States Ministry) का कार्यभार किसे सौंपा गया था?', '[{"id":"A","text":"जवाहरलाल नेहरू (Jawaharlal Nehru)","text_en":"जवाहरलाल नेहरू (Jawaharlal Nehru)"},{"id":"B","text":"वल्लभभाई पटेल (Vallabhbhai Patel)","text_en":"वल्लभभाई पटेल (Vallabhbhai Patel)"},{"id":"C","text":"वी.पी. मेनन (V.P. Menon)","text_en":"वी.पी. मेनन (V.P. Menon)"},{"id":"D","text":"राजेंद्र प्रसाद (Rajendra Prasad)","text_en":"राजेंद्र प्रसाद (Rajendra Prasad)"}]', '1', '**✅ Correct Logic:** 562 रियासतों के एकीकरण के लिए 27 जून 1947 को रियासती मंत्रालय बनाया गया। इसके मंत्री सरदार पटेल थे और सचिव वी.पी. मेनन थे। पटेल की कूटनीति ने भारत का नक्शा तय किया।

**💡 Exam Fact:** पटेल को ''भारत का बिस्मार्क'' (Iron Man) कहा जाता है।

**🧠 Memory Tip:** Patel = Police/Power to Unite.

**🚫 Scam Alert:** मेनन सचिव थे, मंत्री पटेल थे।', 2, 0, 8, NULL, 'Who was entrusted with the charge of ''States Ministry'' after independence?', '**✅ Correct Logic:** States Ministry was formed on 27 June 1947. Sardar Patel was the Minister and VP Menon was the Secretary. Patel''s diplomacy defined India''s map.

**💡 Exam Fact:** Patel is called ''Bismarck of India'' (Iron Man).

**🧠 Memory Tip:** Patel = Police/Power to Unite.

**🚫 Scam Alert:** Menon was Secretary, Patel was Minister.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f01875ef-2c07-43dd-aa57-62495b834a69', 'a12aa742-7b0e-4e02-86b8-87233f212e99', '''JVP समिति'' (1948) का गठन किस उद्देश्य से किया गया था?', '[{"id":"A","text":"भाषाई आधार पर राज्यों के गठन की मांग की जांच करना (To examine the demand for linguistic states)","text_en":"भाषाई आधार पर राज्यों के गठन की मांग की जांच करना (To examine the demand for linguistic states)"},{"id":"B","text":"रियासतों का एकीकरण (Integration of Princely States)","text_en":"रियासतों का एकीकरण (Integration of Princely States)"},{"id":"C","text":"संविधान निर्माण (Constitution Drafting)","text_en":"संविधान निर्माण (Constitution Drafting)"},{"id":"D","text":"शरणार्थी पुनर्वास (Refugee Rehabilitation)","text_en":"शरणार्थी पुनर्वास (Refugee Rehabilitation)"}]', '0', '**✅ Correct Logic:** धर आयोग की रिपोर्ट (जिसने भाषा को आधार मानने से मना किया) की समीक्षा के लिए कांग्रेस ने JVP समिति (जवाहरलाल, वल्लभभाई, पट्टाभि सीतारमैया) बनाई। इसने भी भाषाई आधार को ''राष्ट्रीय एकता के लिए खतरा'' बताकर खारिज कर दिया।

**💡 Exam Fact:** इसके बाद ही पोट्टी श्रीरामुलु का आंदोलन शुरू हुआ।

**🧠 Memory Tip:** JVP = Just Vetoed Pattern (of Language).

**🚫 Scam Alert:** यह समिति राज्यों के गठन के लिए थी, लेकिन इसने भाषा के आधार को नकारा था।', 2, 0, 9, NULL, 'For what purpose was the ''JVP Committee'' (1948) formed?', '**✅ Correct Logic:** Formed to review Dhar Commission report. JVP (Jawaharlal, Vallabhbhai, Pattabhi) also rejected linguistic basis citing threat to national unity.

**💡 Exam Fact:** This rejection triggered Potti Sriramulu''s agitation.

**🧠 Memory Tip:** JVP = Just Vetoed Pattern (of Language).

**🚫 Scam Alert:** It was for state formation, but it Rejected linguistic basis.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('292e2a25-b69b-4bc0-9e89-fe8b2f678d42', 'a12aa742-7b0e-4e02-86b8-87233f212e99', 'पांडिचेरी (पुदुच्चेरी) को किस यूरोपीय शक्ति से 1954 में भारत में मिलाया गया?', '[{"id":"A","text":"पुर्तगाली (Portuguese)","text_en":"पुर्तगाली (Portuguese)"},{"id":"B","text":"डच (Dutch)","text_en":"डच (Dutch)"},{"id":"C","text":"फ्रांसीसी (French)","text_en":"फ्रांसीसी (French)"},{"id":"D","text":"ब्रिटिश (British)","text_en":"ब्रिटिश (British)"}]', '2', '**✅ Correct Logic:** पांडिचेरी, माहे, यनम और कराइकल फ्रांसीसी बस्तियां थीं। 1954 में फ्रांस ने इन्हें भारत को सौंप दिया (De facto transfer)। 1962 में कानूनी रूप से (De jure) संधि की पुष्टि हुई।

**💡 Exam Fact:** गोवा पुर्तगालियों के पास था, पांडिचेरी फ्रांसीसियों के पास।

**🧠 Memory Tip:** **P**ondicherry = **P**aris (French).

**🚫 Scam Alert:** पुर्तगाली गोवा में थे। पांडिचेरी में फ्रेंच थे।', 2, 0, 10, NULL, 'From which European power was Pondicherry (Puducherry) integrated into India in 1954?', '**✅ Correct Logic:** Pondicherry, Mahe, Yanam, Karaikal were French settlements. France handed them over in 1954 (De facto). Legal treaty ratified in 1962.

**💡 Exam Fact:** Goa was with Portuguese, Pondicherry with French.

**🧠 Memory Tip:** **P**ondicherry = **P**aris (French).

**🚫 Scam Alert:** Portuguese were in Goa. French were in Pondicherry.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9460448b-e98d-410d-9de1-ee1e185fda3e', '2c6a54b8-2334-424e-a607-1abe7bb69806', 'पश्चिमी विक्षोभ (Western Disturbances) की उत्पत्ति मुख्य रूप से किस जल निकाय के ऊपर होती है?', '[{"id":"A","text":"हिंद महासागर (Indian Ocean)","text_en":"हिंद महासागर (Indian Ocean)"},{"id":"B","text":"भूमध्य सागर (Mediterranean Sea)","text_en":"भूमध्य सागर (Mediterranean Sea)"},{"id":"C","text":"कैस्पियन सागर (Caspian Sea)","text_en":"कैस्पियन सागर (Caspian Sea)"},{"id":"D","text":"अरब सागर (Arabian Sea)","text_en":"अरब सागर (Arabian Sea)"}]', '1', '**✅ Correct Logic:** पश्चिमी विक्षोभ एक बाह्य-उष्णकटिबंधीय चक्रवात (Extra-tropical cyclone) है जो **भूमध्य सागर** (Mediterranean Sea) में उत्पन्न होता है। वहाँ से यह पूर्व की ओर बढ़ता है।

**💡 Exam Fact:** यह काला सागर (Black Sea) और कैस्पियन सागर से भी नमी ग्रहण करता है, लेकिन मुख्य उत्पत्ति भूमध्य सागर है।

**🧠 Memory Tip:** **Med**iterranean is in the **West** -> Western Disturbance.

**🚫 Scam Alert:** अरब सागर से मानसून आता है, विक्षोभ नहीं।', 2, 0, 1, NULL, 'Western Disturbances mainly originate over which water body?', '**✅ Correct Logic:** Western Disturbance is an extra-tropical cyclone originating over the **Mediterranean Sea**. From there, it moves eastwards.

**💡 Exam Fact:** It also picks up moisture from the Black Sea and Caspian Sea, but the primary origin is Mediterranean.

**🧠 Memory Tip:** **Med**iterranean is in the **West** -> Western Disturbance.

**🚫 Scam Alert:** Monsoon comes from Arabian Sea, not Disturbances.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8d2be2e7-b09a-4aa7-a3d3-2f7e3434e3de', '2c6a54b8-2334-424e-a607-1abe7bb69806', 'भारत में पश्चिमी विक्षोभ को लाने में कौन सी वायुमंडलीय परिघटना (Atmospheric Phenomenon) महत्वपूर्ण भूमिका निभाती है?', '[{"id":"A","text":"पूर्वी जेट स्ट्रीम (Easterly Jet Stream)","text_en":"पूर्वी जेट स्ट्रीम (Easterly Jet Stream)"},{"id":"B","text":"उपोष्णकटिबंधीय पश्चिमी जेट स्ट्रीम (Subtropical Westerly Jet Stream)","text_en":"उपोष्णकटिबंधीय पश्चिमी जेट स्ट्रीम (Subtropical Westerly Jet Stream)"},{"id":"C","text":"व्यापारिक पवनें (Trade Winds)","text_en":"व्यापारिक पवनें (Trade Winds)"},{"id":"D","text":"दक्षिण-पश्चिम मानसून (South-West Monsoon)","text_en":"दक्षिण-पश्चिम मानसून (South-West Monsoon)"}]', '1', '**✅ Correct Logic:** **उपोष्णकटिबंधीय पश्चिमी जेट स्ट्रीम** (Westerly Jet Stream) इन विक्षोभों को भूमध्य सागर से हिमालय की तलहटी तक ले जाती है। सर्दियों में जेट स्ट्रीम हिमालय के दक्षिण में खिसक आती है।

**💡 Exam Fact:** तिब्बती पठार जेट स्ट्रीम को दो शाखाओं में विभाजित करता है।

**🧠 Memory Tip:** **West**ern Disturbance needs **West**erly Jet.

**🚫 Scam Alert:** पूर्वी जेट स्ट्रीम (Easterly) मानसून के दौरान सक्रिय होती है (गर्मियों में), सर्दियों में नहीं।', 2, 0, 2, NULL, 'Which atmospheric phenomenon plays a crucial role in bringing Western Disturbances to India?', '**✅ Correct Logic:** The **Subtropical Westerly Jet Stream** steers these disturbances from the Mediterranean to the Himalayan foothills. In winter, the Jet Stream shifts south of the Himalayas.

**💡 Exam Fact:** The Tibetan Plateau splits the Jet Stream into two branches.

**🧠 Memory Tip:** **West**ern Disturbance needs **West**erly Jet.

**🚫 Scam Alert:** Easterly Jet is active during Monsoon (Summer), not Winter.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('af6731af-f31c-470b-9d66-27cfd099fe67', '2c6a54b8-2334-424e-a607-1abe7bb69806', 'राजस्थान में पश्चिमी विक्षोभ से होने वाली शीतकालीन वर्षा को स्थानीय भाषा में क्या कहा जाता है?', '[{"id":"A","text":"मैंगो शावर (Mango Shower)","text_en":"मैंगो शावर (Mango Shower)"},{"id":"B","text":"मावट (Mawat)","text_en":"मावट (Mawat)"},{"id":"C","text":"काल बैशाखी (Kal Baisakhi)","text_en":"काल बैशाखी (Kal Baisakhi)"},{"id":"D","text":"चेरी ब्लॉसम (Cherry Blossom)","text_en":"चेरी ब्लॉसम (Cherry Blossom)"}]', '1', '**✅ Correct Logic:** राजस्थान में सर्दियों में होने वाली इस वर्षा को **''मावट''** (Mawat) कहा जाता है। यह रबी की फसल (विशेषकर गेहूं) के लिए ''अमृत'' मानी जाती है।

**💡 Exam Fact:** इसे ''Golden Drops'' भी कहा जाता है।

**🧠 Memory Tip:** **Mawat** = **M**ost **A**wesome **W**heat **T**onic.

**🚫 Scam Alert:** मैंगो शावर और चेरी ब्लॉसम प्री-मानसून (गर्मियों की) बारिश है, सर्दियों की नहीं।', 2, 0, 3, NULL, 'What is the winter rainfall caused by Western Disturbances locally called in Rajasthan?', '**✅ Correct Logic:** In Rajasthan, this winter rain is locally called **''Mawat''**. It is considered ''Nectar'' for Rabi crops (especially Wheat).

**💡 Exam Fact:** It is also known as ''Golden Drops''.

**🧠 Memory Tip:** **Mawat** = **M**ost **A**wesome **W**heat **T**onic.

**🚫 Scam Alert:** Mango Shower and Cherry Blossom are Pre-monsoon (Summer) rains, not Winter.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('abdd384e-f31b-45b2-a178-f84de9722f4d', '2c6a54b8-2334-424e-a607-1abe7bb69806', 'पश्चिमी विक्षोभ का निम्नलिखित में से किस फसल पर सकारात्मक प्रभाव पड़ता है?', '[{"id":"A","text":"चावल (Rice)","text_en":"चावल (Rice)"},{"id":"B","text":"कपास (Cotton)","text_en":"कपास (Cotton)"},{"id":"C","text":"गेहूं (Wheat)","text_en":"गेहूं (Wheat)"},{"id":"D","text":"जूट (Jute)","text_en":"जूट (Jute)"}]', '2', '**✅ Correct Logic:** पश्चिमी विक्षोभ सर्दियों (Rabi Season) में आता है। **गेहूं** (Wheat) भारत की प्रमुख रबी फसल है, जिसे पकने के लिए ठंडे मौसम और हल्की बारिश की आवश्यकता होती है।

**💡 Exam Fact:** कश्मीर में यह सेब (Apple) की खेती के लिए भी महत्वपूर्ण है (बर्फबारी)।

**🧠 Memory Tip:** **W**estern Disturbance for **W**heat.

**🚫 Scam Alert:** चावल और जूट खरीफ (मानसून) फसलें हैं। कपास को पाले (Frost) से नुकसान होता है, जो विक्षोभ ला सकता है।', 2, 0, 4, NULL, 'Western Disturbances have a positive impact on which of the following crops?', '**✅ Correct Logic:** Western Disturbances occur in Winter (Rabi Season). **Wheat** is the major Rabi crop which needs cold weather and light rain to mature.

**💡 Exam Fact:** In Kashmir, it is also important for Apple cultivation (Snowfall).

**🧠 Memory Tip:** **W**estern Disturbance for **W**heat.

**🚫 Scam Alert:** Rice and Jute are Kharif (Monsoon) crops. Cotton can be damaged by frost brought by disturbances.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7f8da3a9-80bd-4788-a530-73a92fa44c02', '2c6a54b8-2334-424e-a607-1abe7bb69806', 'पश्चिमी विक्षोभ के बारे में निम्नलिखित कथनों पर विचार करें:
1. यह उष्णकटिबंधीय चक्रवातों (Tropical Cyclones) की तुलना में अधिक विनाशकारी होते हैं।
2. इनकी गति पूर्व से पश्चिम की ओर होती है।
सही कथन चुनें:', '[{"id":"A","text":"केवल 1","text_en":"केवल 1"},{"id":"B","text":"केवल 2","text_en":"केवल 2"},{"id":"C","text":"1 और 2 दोनों","text_en":"1 और 2 दोनों"},{"id":"D","text":"ना तो 1 ना ही 2","text_en":"ना तो 1 ना ही 2"}]', '3', '**✅ Correct Logic:** दोनों कथन **गलत** हैं। (1) उष्णकटिबंधीय चक्रवात (जैसे जो ओडिशा में आते हैं) अधिक विनाशकारी होते हैं; पश्चिमी विक्षोभ हल्के होते हैं। (2) इनकी दिशा **पश्चिम से पूर्व** (West to East) होती है (पछुआ हवाओं के साथ)।

**💡 Exam Fact:** मानसून पूर्व से पश्चिम (E to W) चलता है (गंगा मैदान में), लेकिन विक्षोभ पश्चिम से पूर्व (W to E) चलते हैं।

**🧠 Memory Tip:** **West**ern Disturbance moves from **West**.

**🚫 Scam Alert:** ट्रॉपिकल साइक्लोन ''उल्टा'' (East to West) चलते हैं, लेकिन ये एक्स्ट्रा-ट्रॉपिकल हैं।', 2, 0, 5, NULL, 'Consider the following statements about Western Disturbances:
1. They are more destructive than Tropical Cyclones.
2. Their movement is from East to West.
Choose the correct statement:', '**✅ Correct Logic:** Both statements are **INCORRECT**. (1) Tropical cyclones are far more destructive; Western Disturbances are mild. (2) They move from **West to East** (driven by Westerlies).

**💡 Exam Fact:** Monsoon moves East to West (in Ganga plain), but Disturbances move West to East.

**🧠 Memory Tip:** **West**ern Disturbance moves from **West**.

**🚫 Scam Alert:** Tropical cyclones move East to West, but these are Extra-Tropical.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('33374f09-5ccf-4281-bda6-d99a6461c788', '2c6a54b8-2334-424e-a607-1abe7bb69806', 'भारत के किन राज्यों में पश्चिमी विक्षोभ से वर्षण (Precipitation) मुख्य रूप से बर्फबारी (Snowfall) के रूप में होता है?', '[{"id":"A","text":"पंजाब और हरियाणा (Punjab and Haryana)","text_en":"पंजाब और हरियाणा (Punjab and Haryana)"},{"id":"B","text":"जम्मू-कश्मीर और हिमाचल प्रदेश (J&K and Himachal Pradesh)","text_en":"जम्मू-कश्मीर और हिमाचल प्रदेश (J&K and Himachal Pradesh)"},{"id":"C","text":"राजस्थान और गुजरात (Rajasthan and Gujarat)","text_en":"राजस्थान और गुजरात (Rajasthan and Gujarat)"},{"id":"D","text":"उत्तर प्रदेश और बिहार (UP and Bihar)","text_en":"उत्तर प्रदेश और बिहार (UP and Bihar)"}]', '1', '**✅ Correct Logic:** पहाड़ी राज्यों (**J&K, हिमाचल, उत्तराखंड**) में तापमान कम होने के कारण पश्चिमी विक्षोभ से **बर्फबारी** होती है। मैदानी इलाकों (पंजाब, हरियाणा) में यह बारिश (Rain) के रूप में होती है।

**💡 Exam Fact:** यह बर्फबारी हिमालयी नदियों (गंगा, यमुना) में गर्मियों के प्रवाह (Glacial melt) को बनाए रखने के लिए महत्वपूर्ण है।

**🧠 Memory Tip:** **Snow** on the **Top** (Mountains).

**🚫 Scam Alert:** पंजाब में भी बारिश होती है, लेकिन प्रश्न ''बर्फबारी'' पूछ रहा है।', 2, 0, 6, NULL, 'In which Indian states does precipitation from Western Disturbances occur mainly as Snowfall?', '**✅ Correct Logic:** In hilly states (**J&K, HP, UK**), due to low temperatures, precipitation occurs as **Snowfall**. In plains (Punjab, Haryana), it falls as rain.

**💡 Exam Fact:** This snow is crucial for sustaining summer flow in Himalayan rivers (Glacial melt).

**🧠 Memory Tip:** **Snow** on the **Top** (Mountains).

**🚫 Scam Alert:** Punjab gets rain, but the question asks specifically for ''Snowfall''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e7e0a420-003d-4e1f-b403-9311ac3247ab', '2c6a54b8-2334-424e-a607-1abe7bb69806', 'कभी-कभी पश्चिमी विक्षोभ के कारण ''शीत लहर'' (Cold Wave) की स्थिति क्यों उत्पन्न होती है?', '[{"id":"A","text":"क्योंकि वे अपने साथ ध्रुवीय हवा लाते हैं (They bring polar air)","text_en":"क्योंकि वे अपने साथ ध्रुवीय हवा लाते हैं (They bring polar air)"},{"id":"B","text":"वर्षा के बाद आसमान साफ होने पर विकिरण शीतलन (Radiative cooling) और पहाड़ों से ठंडी हवा आने के कारण","text_en":"वर्षा के बाद आसमान साफ होने पर विकिरण शीतलन (Radiative cooling) और पहाड़ों से ठंडी हवा आने के कारण"},{"id":"C","text":"क्योंकि वे सूर्य की रोशनी को रोक देते हैं (They block sunlight)","text_en":"क्योंकि वे सूर्य की रोशनी को रोक देते हैं (They block sunlight)"},{"id":"D","text":"वे जेट स्ट्रीम को रोक देते हैं (They stop the Jet Stream)","text_en":"वे जेट स्ट्रीम को रोक देते हैं (They stop the Jet Stream)"}]', '1', '**✅ Correct Logic:** विक्षोभ के गुजर जाने के बाद, आसमान साफ हो जाता है (जिससे रात में गर्मी निकल जाती है - Radiational Cooling) और पहाड़ों पर गिरी बर्फ से ठंडी उत्तरी हवाएँ मैदानों की ओर चलती हैं, जिससे **शीत लहर** आती है।

**💡 Exam Fact:** शीत लहर की आधिकारिक घोषणा तब होती है जब तापमान सामान्य से 4.5°C से 6.4°C कम हो जाए।

**🧠 Memory Tip:** **After** the storm comes the **Chill**.

**🚫 Scam Alert:** विक्षोभ के *दौरान* बादल होने से रातें गर्म होती हैं, *जाने के बाद* ठंड बढ़ती है।', 2, 0, 7, NULL, 'Why do Western Disturbances sometimes lead to ''Cold Wave'' conditions?', '**✅ Correct Logic:** After the disturbance passes, the sky clears (leading to Radiational Cooling at night) and cold northern winds from the snow-clad mountains blow towards the plains, causing a **Cold Wave**.

**💡 Exam Fact:** Cold wave is officially declared when temperature drops 4.5°C to 6.4°C below normal.

**🧠 Memory Tip:** **After** the storm comes the **Chill**.

**🚫 Scam Alert:** *During* the disturbance, clouds make nights warmer. The chill comes *after*.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ac7414a1-8b22-4dc5-8298-93ba754c0e3a', '2c6a54b8-2334-424e-a607-1abe7bb69806', 'लद्दाख में ''चिल्लई कलां'' (Chillai Kalan) क्या है, जिसका संबंध पश्चिमी विक्षोभ से है?', '[{"id":"A","text":"एक विशेष प्रकार का ऊनी कपड़ा (A type of woolen cloth)","text_en":"एक विशेष प्रकार का ऊनी कपड़ा (A type of woolen cloth)"},{"id":"B","text":"40 दिनों की सबसे कठोर सर्दी की अवधि (40 days of harshest winter)","text_en":"40 दिनों की सबसे कठोर सर्दी की अवधि (40 days of harshest winter)"},{"id":"C","text":"वसंत ऋतु का आगमन (Arrival of Spring)","text_en":"वसंत ऋतु का आगमन (Arrival of Spring)"},{"id":"D","text":"एक स्थानीय त्यौहार (A local festival)","text_en":"एक स्थानीय त्यौहार (A local festival)"}]', '1', '**✅ Correct Logic:** **चिल्लई कलां** कश्मीर और लद्दाख में **40 दिनों** की सबसे कठोर सर्दी (21 दिसंबर से 30 जनवरी) को कहते हैं। इस दौरान पश्चिमी विक्षोभ से भारी बर्फबारी होती है।

**💡 Exam Fact:** इसके बाद ''चिल्लई खुर्द'' (20 दिन) और ''चिल्लई बच्चा'' (10 दिन) आता है।

**🧠 Memory Tip:** **Kalan** means Big/Major -> Big Cold.

**🚫 Scam Alert:** यह कोई कपड़ा नहीं है, हालांकि ''फेरन'' (Pheran) कपड़ा है जो इस दौरान पहना जाता है।', 2, 0, 8, NULL, 'What is ''Chillai Kalan'' in Ladakh/Kashmir, which is related to Western Disturbances?', '**✅ Correct Logic:** **Chillai Kalan** is the period of **40 days** of harshest winter (Dec 21 to Jan 30) in Kashmir/Ladakh. Heavy snowfall from Western Disturbances occurs during this time.

**💡 Exam Fact:** Followed by ''Chillai Khurd'' (Small Cold) and ''Chillai Bachha'' (Baby Cold).

**🧠 Memory Tip:** **Kalan** means Big -> Big Cold.

**🚫 Scam Alert:** Not a cloth, though ''Pheran'' is worn during this time.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5c153365-327a-455c-a64d-6d821bfa23d9', '2c6a54b8-2334-424e-a607-1abe7bb69806', 'पश्चिमी विक्षोभ भारत की कुल वार्षिक वर्षा (Annual Rainfall) में लगभग कितना योगदान देता है?', '[{"id":"A","text":"20-25%","text_en":"20-25%"},{"id":"B","text":"2-3%","text_en":"2-3%"},{"id":"C","text":"10-15%","text_en":"10-15%"},{"id":"D","text":"50%","text_en":"50%"}]', '1', '**✅ Correct Logic:** पश्चिमी विक्षोभ का योगदान बहुत कम, लगभग **2-3%** (या 5% तक उत्तर भारत में) है। भारत की 75% बारिश दक्षिण-पश्चिम मानसून से होती है।

**💡 Exam Fact:** मात्रा कम है, लेकिन आर्थिक मूल्य (Economic Value - Wheat production) बहुत अधिक है।

**🧠 Memory Tip:** Small packet, Big Dhamaka (Only 3% rain but saves 100% Wheat).

**🚫 Scam Alert:** 10-15% उत्तर-पूर्वी मानसून (लौटता हुआ मानसून) से होता है।', 2, 0, 9, NULL, 'Approximately how much does Western Disturbance contribute to India''s total Annual Rainfall?', '**✅ Correct Logic:** The contribution is very small, approx **2-3%** (up to 5% in North India). 75% of India''s rain comes from SW Monsoon.

**💡 Exam Fact:** Quantity is low, but Economic Value (Wheat) is high.

**🧠 Memory Tip:** Small packet, Big Dhamaka.

**🚫 Scam Alert:** 10-15% is from North-East Monsoon (Retreating Monsoon).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cb5f31e4-136d-4d37-9d67-2494fce03677', '2c6a54b8-2334-424e-a607-1abe7bb69806', 'निम्नलिखित शीतकालीन मौसम प्रणालियों को उनके क्षेत्र से सुमेलित करें (Match the following winter weather systems with their region):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(b), (3)-(d), (4)-(c)","text_en":"(1)-(a), (2)-(b), (3)-(d), (4)-(c)"},{"id":"D","text":"(1)-(b), (2)-(c), (3)-(a), (4)-(d)","text_en":"(1)-(b), (2)-(c), (3)-(a), (4)-(d)"}]', '0', '**✅ Correct Matching:**
* **पश्चिमी विक्षोभ**: उत्तर-पश्चिम भारत (पंजाब, हरियाणा)। -> (1)-(a)
* **उत्तर-पूर्वी मानसून**: तमिलनाडु (चेन्नई) में सर्दियों में बारिश करता है। -> (2)-(b)
* **नॉर्वेस्टर**: यद्यपि भारत में काल बैशाखी को कहते हैं, लेकिन विश्व स्तर पर न्यूजीलैंड की गर्म हवा भी है (Exam trick). यहाँ संदर्भ में अगर भारत की बात हो तो भी बंगाल सही होता, लेकिन विकल्पों में सेट बैठ रहा है।
* **शीतकालीन कोहरा**: दिल्ली/यूपी/बिहार (गंगा मैदान) की प्रमुख विशेषता। -> (4)-(d)

**💡 Exam Fact:** तमिलनाडु भारत का एकमात्र राज्य है जहाँ सर्दियों (NE Monsoon) में मुख्य बारिश होती है, गर्मियों में नहीं।

**🧠 Memory Tip:** **West**ern Disturbance in **West** India. **East** Monsoon in **East** Coast (TN).

**🚫 Scam Alert:** छात्र अक्सर पश्चिमी विक्षोभ को तमिलनाडु की बारिश से जोड़ देते हैं। याद रखें: उत्तर में विक्षोभ, दक्षिण में लौटता मानसून।', 2, 0, 10, NULL, 'Match the following winter weather systems with their region:', '**✅ Correct Matching:**
* **Western Disturbance**: North-West India. -> (1)-(a)
* **North-East Monsoon**: Tamil Nadu (Coromandel) rains in winter. -> (2)-(b)
* **Norwesters**: Often refers to NZ winds or Kalbaisakhi context. -> (3)-(c)
* **Winter Fog**: Main feature of Ganga Plains (Delhi/UP). -> (4)-(d)

**💡 Exam Fact:** TN is the only state receiving major rain in Winter (NE Monsoon).

**🧠 Memory Tip:** **West**ern Disturbance in **North**, **East** Monsoon in **South**.

**🚫 Scam Alert:** Do not confuse Western Disturbance with TN rains.', 60, 'matching', '[{"id":"(1)","label":"पश्चिमी विक्षोभ (Western Disturbance)","match":"उत्तर-पश्चिम भारत (North-West India)","matchId":"(a)"},{"id":"(2)","label":"उत्तर-पूर्वी मानसून (North-East Monsoon)","match":"कोरोमंडल तट/तमिलनाडु (Coromandel Coast)","matchId":"(b)"},{"id":"(3)","label":"नॉर्वेस्टर (Norwesters)","match":"न्यूजीलैंड (New Zealand) - *Note: In India called Kalbaisakhi but globally specific*","matchId":"(c)"},{"id":"(4)","label":"शीतकालीन कोहरा (Winter Fog)","match":"गंगा का मैदान (Ganga Plains)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cbbfd422-38da-4f63-9c21-4d5a51721ccd', 'bec323d8-0560-4160-9daa-75a482200b54', 'भारत वन स्थिति रिपोर्ट (ISFR) 2021 के अनुसार, भारत में कुल वन और वृक्ष आवरण (Total Forest and Tree Cover) भौगोलिक क्षेत्र का कितना प्रतिशत है?', '[{"id":"A","text":"21.71%","text_en":"21.71%"},{"id":"B","text":"24.62%","text_en":"24.62%"},{"id":"C","text":"33.00%","text_en":"33.00%"},{"id":"D","text":"22.80%","text_en":"22.80%"}]', '1', '**✅ Correct Logic:** कुल वन और वृक्ष आवरण **24.62%** (80.9 मिलियन हेक्टेयर) है। केवल वन आवरण (Forest Cover) **21.71%** है और वृक्ष आवरण (Tree Cover) 2.91% है।

**💡 Exam Fact:** राष्ट्रीय वन नीति 1988 का लक्ष्य **33%** है।

**🧠 Memory Tip:** 24 hours in a day -> **24**.62% cover.

**🚫 Scam Alert:** 21.71% केवल ''जंगल'' (Forest) है। प्रश्न में ''वन और वृक्ष'' (Forest + Tree) दोनों पूछा है।', 2, 0, 1, NULL, 'As per India State of Forest Report (ISFR) 2021, what is the percentage of Total Forest and Tree Cover in India regarding geographical area?', '**✅ Correct Logic:** Total Forest and Tree cover is **24.62%**. Only Forest Cover is **21.71%** and Tree Cover is 2.91%.

**💡 Exam Fact:** National Forest Policy 1988 target is **33%**.

**🧠 Memory Tip:** 24 hours -> **24**.62%.

**🚫 Scam Alert:** 21.71% is ONLY Forest. Question asks Forest + Tree.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e1cf79af-bee3-4561-86ca-ad5267dd3e77', 'bec323d8-0560-4160-9daa-75a482200b54', 'क्षेत्रफल (Area) के हिसाब से भारत में सबसे बड़ा वन क्षेत्र किस राज्य में है (ISFR 2021)?', '[{"id":"A","text":"अरुणाचल प्रदेश (Arunachal Pradesh)","text_en":"अरुणाचल प्रदेश (Arunachal Pradesh)"},{"id":"B","text":"मध्य प्रदेश (Madhya Pradesh)","text_en":"मध्य प्रदेश (Madhya Pradesh)"},{"id":"C","text":"छत्तीसगढ़ (Chhattisgarh)","text_en":"छत्तीसगढ़ (Chhattisgarh)"},{"id":"D","text":"ओडिशा (Odisha)","text_en":"ओडिशा (Odisha)"}]', '1', '**✅ Correct Logic:** **मध्य प्रदेश** में क्षेत्रफल के हिसाब से सबसे बड़ा वन क्षेत्र है। इसके बाद अरुणाचल प्रदेश, छत्तीसगढ़ और ओडिशा का स्थान है।

**💡 Exam Fact:** प्रतिशत (Percentage) के हिसाब से **मिजोरम** (84.53%) शीर्ष पर है।

**🧠 Memory Tip:** **M**adhya Pradesh is **M**assive in Forest.

**🚫 Scam Alert:** अरुणाचल दूसरे नंबर पर है। पूर्वोत्तर राज्यों में प्रतिशत अधिक है, लेकिन कुल क्षेत्रफल में एमपी राजा है।', 2, 0, 2, NULL, 'Which state has the largest forest cover in India in terms of Area (ISFR 2021)?', '**✅ Correct Logic:** **Madhya Pradesh** has the largest forest cover by Area. Followed by Arunachal, Chhattisgarh, and Odisha.

**💡 Exam Fact:** By Percentage, **Mizoram** (84.53%) is at the top.

**🧠 Memory Tip:** **M**adhya Pradesh is **M**assive in Forest.

**🚫 Scam Alert:** Arunachal is 2nd. NE states have high %, but MP has total Area.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('aad931c9-8aec-403d-a23b-33cbad61305c', 'bec323d8-0560-4160-9daa-75a482200b54', 'भारत में किस प्रकार के वन सर्वाधिक विस्तृत क्षेत्र (Most Widespread) में पाए जाते हैं?', '[{"id":"A","text":"उष्णकटिबंधीय सदाबहार वन (Tropical Evergreen)","text_en":"उष्णकटिबंधीय सदाबहार वन (Tropical Evergreen)"},{"id":"B","text":"उष्णकटिबंधीय पर्णपाती वन (Tropical Deciduous)","text_en":"उष्णकटिबंधीय पर्णपाती वन (Tropical Deciduous)"},{"id":"C","text":"मैंग्रोव वन (Mangrove)","text_en":"मैंग्रोव वन (Mangrove)"},{"id":"D","text":"पर्वतीय वन (Montane)","text_en":"पर्वतीय वन (Montane)"}]', '1', '**✅ Correct Logic:** **उष्णकटिबंधीय पर्णपाती वन** (Tropical Deciduous Forests), जिन्हें ''मानसून वन'' भी कहा जाता है, भारत में सबसे अधिक पाए जाते हैं। ये उन क्षेत्रों में होते हैं जहाँ वर्षा 70-200 सेमी होती है।

**💡 Exam Fact:** सागौन (Teak) और साल (Sal) इन वनों के सबसे महत्वपूर्ण वृक्ष हैं।

**🧠 Memory Tip:** India is a Monsoon land -> **Monsoon Forests** (Deciduous) are maximum.

**🚫 Scam Alert:** सदाबहार वन केवल पश्चिमी घाट और पूर्वोत्तर में हैं। पर्णपाती पूरे भारत (एमपी, यूपी, बिहार, दक्षिण) में हैं।', 2, 0, 3, NULL, 'Which type of forests are most widespread in India?', '**✅ Correct Logic:** **Tropical Deciduous Forests** (also called Monsoon Forests) are the most widespread. Found where rainfall is 70-200 cm.

**💡 Exam Fact:** Teak and Sal are the most important trees here.

**🧠 Memory Tip:** India is Monsoon land -> **Monsoon Forests** (Deciduous) are maximum.

**🚫 Scam Alert:** Evergreen are only in Western Ghats/NE. Deciduous covers the heartland.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('29212a47-d1eb-493f-b5ed-91654cd185c1', 'bec323d8-0560-4160-9daa-75a482200b54', 'ISFR 2021 के अनुसार, वन आवरण में ''सर्वाधिक वृद्धि'' (Maximum Increase) दर्ज करने वाला राज्य कौन सा है?', '[{"id":"A","text":"तेलंगाना (Telangana)","text_en":"तेलंगाना (Telangana)"},{"id":"B","text":"आंध्र प्रदेश (Andhra Pradesh)","text_en":"आंध्र प्रदेश (Andhra Pradesh)"},{"id":"C","text":"ओडिशा (Odisha)","text_en":"ओडिशा (Odisha)"},{"id":"D","text":"कर्नाटक (Karnataka)","text_en":"कर्नाटक (Karnataka)"}]', '1', '**✅ Correct Logic:** **आंध्र प्रदेश** ने वन आवरण में सबसे अधिक वृद्धि (647 वर्ग किमी) दर्ज की है। इसके बाद तेलंगाना (632 वर्ग किमी) का स्थान है।

**💡 Exam Fact:** पूर्वोत्तर के 5 राज्यों (अरुणाचल, मणिपुर, मेघालय, मिजोरम, नागालैंड) में वन क्षेत्र में *गिरावट* आई है।

**🧠 Memory Tip:** **A**ndhra **A**dded the most.

**🚫 Scam Alert:** कर्नाटक पिछली रिपोर्ट (2019) में टॉप पर था, 2021 में आंध्र प्रदेश टॉप पर है। डेटा अपडेट करें!', 2, 0, 4, NULL, 'As per ISFR 2021, which state has recorded the ''Maximum Increase'' in forest cover?', '**✅ Correct Logic:** **Andhra Pradesh** recorded the maximum increase (647 sq km). Followed by Telangana.

**💡 Exam Fact:** 5 NE states showed a *decline*.

**🧠 Memory Tip:** **A**ndhra **A**dded the most.

**🚫 Scam Alert:** Karnataka was top in 2019. In 2021, it''s Andhra. Update your data!', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9169e408-911f-426e-aca4-68de7182ac8f', 'bec323d8-0560-4160-9daa-75a482200b54', 'चंदन (Sandalwood) के वृक्ष मुख्य रूप से किस प्रकार के वनों में पाए जाते हैं?', '[{"id":"A","text":"उष्णकटिबंधीय आर्द्र पर्णपाती (Tropical Moist Deciduous)","text_en":"उष्णकटिबंधीय आर्द्र पर्णपाती (Tropical Moist Deciduous)"},{"id":"B","text":"उष्णकटिबंधीय शुष्क पर्णपाती (Tropical Dry Deciduous)","text_en":"उष्णकटिबंधीय शुष्क पर्णपाती (Tropical Dry Deciduous)"},{"id":"C","text":"उष्णकटिबंधीय सदाबहार (Tropical Evergreen)","text_en":"उष्णकटिबंधीय सदाबहार (Tropical Evergreen)"},{"id":"D","text":"कटीले वन (Thorn Forests)","text_en":"कटीले वन (Thorn Forests)"}]', '1', '**✅ Correct Logic:** चंदन **उष्णकटिबंधीय शुष्क पर्णपाती** (Dry Deciduous) वनों (और कभी-कभी आर्द्र) का वृक्ष है, जो मुख्य रूप से कर्नाटक, तमिलनाडु पठार क्षेत्र में पाया जाता है। *Correction:* तकनीकी रूप से यह Deciduous (Moist और Dry दोनों के बीच संक्रमण) में आता है, लेकिन NCERT और MPPSC ''शुष्क पर्णपाती'' या ''पर्णपाती'' को सही मानते हैं। दिए गए विकल्पों में सबसे सटीक ''शुष्क पर्णपाती'' (Dry Deciduous) है क्योंकि यह कम वर्षा वाले पठारी क्षेत्रों में उगता है।

**💡 Exam Fact:** लाल चंदन (Red Sanders) पूर्वी घाट के शुष्क पर्णपाती वनों में मिलता है।

**🧠 Memory Tip:** Sandal is dry wood (smell comes when rubbed dry).

**🚫 Scam Alert:** सदाबहार मत लगा देना, चंदन को बहुत ज्यादा बारिश नहीं चाहिए।', 2, 0, 5, NULL, 'Sandalwood trees are mainly found in which type of forests?', '**✅ Correct Logic:** Sandalwood belongs to **Tropical Dry Deciduous** forests (found in Karnataka/TN plateau). 

**💡 Exam Fact:** Red Sanders is found in Dry Deciduous forests of Eastern Ghats.

**🧠 Memory Tip:** Sandal is dry wood.

**🚫 Scam Alert:** Don''t pick Evergreen. Sandalwood doesn''t need excessive rain.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1ca46fa2-4369-4093-a288-380528d55ece', 'bec323d8-0560-4160-9daa-75a482200b54', 'सुंदरी वृक्ष (Sundari Trees), जिनके नाम पर सुंदरबन का नाम पड़ा, किस प्रकार की वनस्पति हैं?', '[{"id":"A","text":"उष्णकटिबंधीय पर्णपाती (Tropical Deciduous)","text_en":"उष्णकटिबंधीय पर्णपाती (Tropical Deciduous)"},{"id":"B","text":"मैंग्रोव / ज्वारीय वन (Mangrove / Tidal Forests)","text_en":"मैंग्रोव / ज्वारीय वन (Mangrove / Tidal Forests)"},{"id":"C","text":"अल्पाइन वन (Alpine Forest)","text_en":"अल्पाइन वन (Alpine Forest)"},{"id":"D","text":"शंकुधारी वन (Coniferous Forest)","text_en":"शंकुधारी वन (Coniferous Forest)"}]', '1', '**✅ Correct Logic:** सुंदरी (Heritiera fomes) एक **मैंग्रोव** (Mangrove) प्रजाति है जो ज्वारीय और खारे पानी वाले क्षेत्रों में उगती है। इनमें श्वसन जड़ें (Pneumatophores) होती हैं।

**💡 Exam Fact:** सुंदरबन दुनिया का सबसे बड़ा मैंग्रोव डेल्टा है।

**🧠 Memory Tip:** **Sundari** likes **Salt** (Mangrove).

**🚫 Scam Alert:** यह पर्णपाती नहीं है। यह हमेशा हरा रहता है लेकिन ''सदाबहार'' श्रेणी में नहीं, ''मैंग्रोव'' श्रेणी में आता है।', 2, 0, 6, NULL, 'Sundari trees, after which Sundarbans are named, belong to which type of vegetation?', '**✅ Correct Logic:** Sundari is a **Mangrove** species found in tidal/saline areas. It has breathing roots (Pneumatophores).

**💡 Exam Fact:** Sundarbans is the world''s largest Mangrove delta.

**🧠 Memory Tip:** **Sundari** likes **Salt**.

**🚫 Scam Alert:** Not Deciduous. It falls under ''Littoral/Swamp'' or Mangrove.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5248e778-a8ca-4eba-a121-8ae7bf4ce3a9', 'bec323d8-0560-4160-9daa-75a482200b54', 'भारत में ''सामाजिक वानिकी'' (Social Forestry) शब्द का प्रयोग पहली बार कब और किसके द्वारा किया गया था?', '[{"id":"A","text":"1976 - राष्ट्रीय कृषि आयोग (National Commission on Agriculture)","text_en":"1976 - राष्ट्रीय कृषि आयोग (National Commission on Agriculture)"},{"id":"B","text":"1988 - वन नीति (Forest Policy)","text_en":"1988 - वन नीति (Forest Policy)"},{"id":"C","text":"1952 - प्रथम वन नीति (First Forest Policy)","text_en":"1952 - प्रथम वन नीति (First Forest Policy)"},{"id":"D","text":"1972 - वन्यजीव अधिनियम (Wildlife Act)","text_en":"1972 - वन्यजीव अधिनियम (Wildlife Act)"}]', '0', '**✅ Correct Logic:** ''सामाजिक वानिकी'' शब्द का प्रयोग पहली बार **1976** में **राष्ट्रीय कृषि आयोग** (NCA) द्वारा किया गया था। इसका उद्देश्य ग्रामीण आबादी के लिए जलाऊ लकड़ी और चारे की आपूर्ति करना था।

**💡 Exam Fact:** इसके तीन घटक हैं: शहरी वानिकी, ग्रामीण वानिकी और फार्म वानिकी।

**🧠 Memory Tip:** Society got Focus in **76**.

**🚫 Scam Alert:** 1952 और 1988 वन नीतियों के वर्ष हैं, लेकिन ''सामाजिक वानिकी'' शब्द 1976 में गढ़ा गया।', 2, 0, 7, NULL, 'When and by whom was the term ''Social Forestry'' used for the first time in India?', '**✅ Correct Logic:** Term ''Social Forestry'' was first used in **1976** by **National Commission on Agriculture** (NCA). Aim was to supply firewood/fodder.

**💡 Exam Fact:** Components: Urban, Rural, and Farm Forestry.

**🧠 Memory Tip:** Society got Focus in **76**.

**🚫 Scam Alert:** 1952/1988 are policies, but the TERM came in 1976.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('84787774-c0b6-4213-a06f-ec8986266066', 'bec323d8-0560-4160-9daa-75a482200b54', 'मध्य प्रदेश का कौन सा जिला सर्वाधिक वन आवरण प्रतिशत (Highest Forest Cover Percentage) वाला है (ISFR 2021 के अनुसार)?', '[{"id":"A","text":"बालाघाट (Balaghat)","text_en":"बालाघाट (Balaghat)"},{"id":"B","text":"श्योपुर (Sheopur)","text_en":"श्योपुर (Sheopur)"},{"id":"C","text":"उमरिया (Umaria)","text_en":"उमरिया (Umaria)"},{"id":"D","text":"मंडला (Mandla)","text_en":"मंडला (Mandla)"}]', '0', '**✅ Correct Logic:** **बालाघाट** (53% से अधिक) मध्य प्रदेश में प्रतिशत और क्षेत्रफल दोनों के हिसाब से सबसे अधिक वन वाला जिला है।

**💡 Exam Fact:** उज्जैन में सबसे कम वन क्षेत्र (प्रतिशत और क्षेत्रफल दोनों) है।

**🧠 Memory Tip:** **Bala** (Girl) likes **Forests**. Balaghat Top.

**🚫 Scam Alert:** मंडला और श्योपुर में भी वन हैं, लेकिन बालाघाट निर्विवाद रूप से नंबर 1 है।', 2, 0, 8, NULL, 'Which district of Madhya Pradesh has the Highest Forest Cover Percentage (as per ISFR 2021)?', '**✅ Correct Logic:** **Balaghat** has the highest forest cover in MP by both Percentage and Area.

**💡 Exam Fact:** Ujjain has the lowest forest cover.

**🧠 Memory Tip:** **Bala** likes **Forests**.

**🚫 Scam Alert:** Mandla is dense, but Balaghat is Rank 1.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8bb7b385-dee5-40dd-9e9c-1aba7b05bb15', 'bec323d8-0560-4160-9daa-75a482200b54', 'सागौन (Teak) का वानस्पतिक नाम (Botanical Name) क्या है?', '[{"id":"A","text":"टेक्टोना ग्रैंडिस (Tectona grandis)","text_en":"टेक्टोना ग्रैंडिस (Tectona grandis)"},{"id":"B","text":" शोरिया रोबस्टा (Shorea robusta)","text_en":" शोरिया रोबस्टा (Shorea robusta)"},{"id":"C","text":"मधुका इंडिका (Madhuca indica)","text_en":"मधुका इंडिका (Madhuca indica)"},{"id":"D","text":"ब्यूटिया मोनोस्पर्मा (Butea monosperma)","text_en":"ब्यूटिया मोनोस्पर्मा (Butea monosperma)"}]', '0', '**✅ Correct Logic:** सागौन का नाम **टेक्टोना ग्रैंडिस** है। यह भारत (विशेषकर एमपी) का सबसे मूल्यवान टिम्बर है।

**💡 Exam Fact:** शोरिया रोबस्टा = साल। ब्यूटिया मोनोस्पर्मा = पलाश (जंगल की आग)।

**🧠 Memory Tip:** **T**eak = **T**ectona.

**🚫 Scam Alert:** साल (Shorea) और सागौन (Tectona) में कंफ्यूज न हों।', 2, 0, 9, NULL, 'What is the Botanical Name of Teak?', '**✅ Correct Logic:** Teak is **Tectona grandis**. Most valuable timber.

**💡 Exam Fact:** Shorea robusta = Sal. Butea monosperma = Palash (Flame of Forest).

**🧠 Memory Tip:** **T**eak = **T**ectona.

**🚫 Scam Alert:** Don''t confuse Sal (Shorea) with Teak (Tectona).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1e2d5086-51f8-4ade-8ca3-5ad14f8763b3', 'bec323d8-0560-4160-9daa-75a482200b54', 'निम्नलिखित वृक्षों को उनके प्रमुख उपयोग/विशेषता से सुमेलित करें (Match the following trees with their major use/feature):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(b), (3)-(d), (4)-(c)","text_en":"(1)-(a), (2)-(b), (3)-(d), (4)-(c)"},{"id":"D","text":"(1)-(c), (2)-(b), (3)-(a), (4)-(d)","text_en":"(1)-(c), (2)-(b), (3)-(a), (4)-(d)"}]', '0', '**✅ Correct Matching:**
* **तेंदू पत्ता**: बीड़ी बनाने के लिए (MP इसका सबसे बड़ा उत्पादक है)। -> (1)-(a)
* **खैर**: इसकी लकड़ी से कत्था (Pan masala ing.) निकाला जाता है। -> (2)-(b)
* **पलाश**: इसके लाल फूलों के कारण इसे ''जंगल की आग'' कहते हैं। -> (3)-(c)
* **साल**: इसकी लकड़ी बहुत कठोर होती है, पहले रेलवे स्लीपर इसी से बनते थे। -> (4)-(d)

**💡 Exam Fact:** तेंदू पत्ता संग्राहकों के लिए ''चरण पादुका योजना'' एमपी में प्रसिद्ध है।

**🧠 Memory Tip:** **Tendu** for **Tobacco** (Bidi). **Khair** for **Kattha**. **Palash** is **Fire**. **Sal** is **Strong**.

**🚫 Scam Alert:** ये सभी ''Minor Forest Produce'' (MFP) में आते हैं (लकड़ी को छोड़कर)।', 2, 0, 10, NULL, 'Match the following trees with their major use/feature:', '**✅ Correct Matching:**
* **Tendu**: Bidi making (MP is largest producer). -> (1)-(a)
* **Khair**: Kattha extracted from wood. -> (2)-(b)
* **Palash**: Flame of the Forest due to red flowers. -> (3)-(c)
* **Sal**: Very hard wood, used for Railway Sleepers. -> (4)-(d)

**💡 Exam Fact:** Charan Paduka Yojana for Tendu collectors.

**🧠 Memory Tip:** **Tendu**-Bidi. **Khair**-Kattha.

**🚫 Scam Alert:** Common economic botany questions.', 60, 'matching', '[{"id":"(1)","label":"तेंदू पत्ता (Tendu Leaf)","match":"बीड़ी उद्योग (Bidi Industry)","matchId":"(a)"},{"id":"(2)","label":"खैर (Khair)","match":"कत्था निर्माण (Kattha extraction)","matchId":"(b)"},{"id":"(3)","label":"पलाश (Palash)","match":"जंगल की आग (Flame of the Forest)","matchId":"(c)"},{"id":"(4)","label":"साल (Sal)","match":"रेलवे स्लीपर (Railway Sleepers - old usage)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e6683117-ba16-461f-a08e-b19376dbcd5d', '36a9b33e-de9c-4723-826b-4bb8623717b3', 'भारत में ''अबरक'' (Mica) का सबसे बड़ा उत्पादक राज्य कौन सा है?', '[{"id":"A","text":"झारखंड (Jharkhand)","text_en":"झारखंड (Jharkhand)"},{"id":"B","text":"आंध्र प्रदेश (Andhra Pradesh)","text_en":"आंध्र प्रदेश (Andhra Pradesh)"},{"id":"C","text":"राजस्थान (Rajasthan)","text_en":"राजस्थान (Rajasthan)"},{"id":"D","text":"बिहार (Bihar)","text_en":"बिहार (Bihar)"}]', '1', '**✅ Correct Logic:** वर्तमान आंकड़ों (IBM Data) के अनुसार, **आंध्र प्रदेश** (नेल्लोर जिला) अभ्रक का सबसे बड़ा उत्पादक है। पहले झारखंड (कोडरमा) था, लेकिन अब आंध्र प्रदेश शीर्ष पर है।

**💡 Exam Fact:** कोडरमा (झारखंड) को ''अभ्रक राजधानी'' (Mica Capital) कहा जाता है, लेकिन उत्पादन में एपी आगे है।

**🧠 Memory Tip:** **A**ndhra produces **A**bhrak.

**🚫 Scam Alert:** पुरानी किताबों में झारखंड/बिहार मिलता है। अपडेट रहें, आंध्र प्रदेश सही उत्तर है।', 2, 0, 1, NULL, 'Which state is the largest producer of ''Mica'' in India?', '**✅ Correct Logic:** Currently, **Andhra Pradesh** (Nellore) is the largest producer. Jharkhand used to be, but now AP leads.

**💡 Exam Fact:** Koderma (Jharkhand) is called ''Mica Capital'' historically.

**🧠 Memory Tip:** **A**ndhra produces **A**bhrak.

**🚫 Scam Alert:** Old books say Jharkhand. Updated data says AP.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6e35caca-5cd9-4e47-9e0b-0b4053b3dffc', '36a9b33e-de9c-4723-826b-4bb8623717b3', '''बैलाडीला'' (Bailadila) खानें किसके लिए प्रसिद्ध हैं और किस राज्य में हैं?', '[{"id":"A","text":"कोयला - झारखंड (Coal - Jharkhand)","text_en":"कोयला - झारखंड (Coal - Jharkhand)"},{"id":"B","text":"लौह अयस्क - छत्तीसगढ़ (Iron Ore - Chhattisgarh)","text_en":"लौह अयस्क - छत्तीसगढ़ (Iron Ore - Chhattisgarh)"},{"id":"C","text":"तांबा - मध्य प्रदेश (Copper - Madhya Pradesh)","text_en":"तांबा - मध्य प्रदेश (Copper - Madhya Pradesh)"},{"id":"D","text":"बॉक्साइट - ओडिशा (Bauxite - Odisha)","text_en":"बॉक्साइट - ओडिशा (Bauxite - Odisha)"}]', '1', '**✅ Correct Logic:** बैलाडीला (बैल के कूबड़ जैसी आकृति) खानें **छत्तीसगढ़** (दंतेवाड़ा) में हैं और उच्च गुणवत्ता वाले **हेमेटाइट लौह अयस्क** (Iron Ore) के लिए विश्व प्रसिद्ध हैं।

**💡 Exam Fact:** यहाँ का लोहा विशाखापत्तनम बंदरगाह से जापान को निर्यात किया जाता है।

**🧠 Memory Tip:** **Bail** (Ox) is strong like **Iron**. Bailadila -> Iron.

**🚫 Scam Alert:** बालाघाट (एमपी) तांबे/मैंगनीज के लिए है, बैलाडीला (सीजी) लोहे के लिए है।', 2, 0, 2, NULL, 'What are ''Bailadila'' mines famous for and in which state are they located?', '**✅ Correct Logic:** Bailadila (Hump of Ox) mines are in **Chhattisgarh** and famous for high quality **Hematite Iron Ore**.

**💡 Exam Fact:** Iron from here is exported to Japan via Vizag port.

**🧠 Memory Tip:** **Bail** (Ox) -> Iron.

**🚫 Scam Alert:** Balaghat (MP) is Copper/Mn. Bailadila (CG) is Iron.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('181403ba-c381-4adb-a3c0-fd6ed05e872e', '36a9b33e-de9c-4723-826b-4bb8623717b3', 'निम्नलिखित में से कौन सा खनिज ''मोनाजाइट रेत'' (Monazite Sand) में पाया जाता है?', '[{"id":"A","text":"यूरेनियम (Uranium)","text_en":"यूरेनियम (Uranium)"},{"id":"B","text":"थोरियम (Thorium)","text_en":"थोरियम (Thorium)"},{"id":"C","text":"प्लूटोनियम (Plutonium)","text_en":"प्लूटोनियम (Plutonium)"},{"id":"D","text":"कोयला (Coal)","text_en":"कोयला (Coal)"}]', '1', '**✅ Correct Logic:** मोनाजाइट रेत में **थोरियम** (Thorium) प्रचुर मात्रा में पाया जाता है। यह केरल के मालाबार तट पर मिलता है।

**💡 Exam Fact:** भारत के पास दुनिया का सबसे बड़ा थोरियम भंडार है, जो भविष्य के परमाणु कार्यक्रमों (Stage 3) के लिए महत्वपूर्ण है।

**🧠 Memory Tip:** **Thor** (Avenger) plays in **Sand** (Kerala beach).

**🚫 Scam Alert:** जादुगुडा (झारखंड) में यूरेनियम है, लेकिन केरल की रेत में थोरियम है।', 2, 0, 3, NULL, 'Which of the following minerals is found in ''Monazite Sand''?', '**✅ Correct Logic:** Monazite sand is rich in **Thorium**. Found on Malabar coast of Kerala.

**💡 Exam Fact:** India has world''s largest Thorium reserves, vital for Stage 3 Nuclear program.

**🧠 Memory Tip:** **Thor** plays in **Sand**.

**🚫 Scam Alert:** Jaduguda has Uranium. Sands have Thorium.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('73e77674-444f-4f49-8eb5-392266ed06d0', '36a9b33e-de9c-4723-826b-4bb8623717b3', 'भारत की सबसे बड़ी तांबे की खान ''मलांजखंड'' (Malanjkhand) किस राज्य में स्थित है?', '[{"id":"A","text":"राजस्थान (Rajasthan)","text_en":"राजस्थान (Rajasthan)"},{"id":"B","text":"झारखंड (Jharkhand)","text_en":"झारखंड (Jharkhand)"},{"id":"C","text":"मध्य प्रदेश (Madhya Pradesh)","text_en":"मध्य प्रदेश (Madhya Pradesh)"},{"id":"D","text":"कर्नाटक (Karnataka)","text_en":"कर्नाटक (Karnataka)"}]', '2', '**✅ Correct Logic:** मलांजखंड **मध्य प्रदेश** (बालाघाट जिला) में स्थित है। इसे ''तांबा नगरी'' भी कहते हैं। भारत का लगभग 50%+ तांबा एमपी से आता है।

**💡 Exam Fact:** खेतड़ी (राजस्थान) भी तांबे के लिए प्रसिद्ध है, लेकिन मलांजखंड सबसे बड़ा है।

**🧠 Memory Tip:** **M**alanjkhand in **M**P.

**🚫 Scam Alert:** खेतड़ी (सिंधु घाटी सभ्यता काल से) ऐतिहासिक है, लेकिन वर्तमान उत्पादन/भंडार में मलांजखंड प्रमुख है।', 2, 0, 4, NULL, 'India''s largest copper mine ''Malanjkhand'' is located in which state?', '**✅ Correct Logic:** Malanjkhand is in **Madhya Pradesh** (Balaghat). Known as ''Copper City''. MP produces 50%+ of India''s copper.

**💡 Exam Fact:** Khetri (Rajasthan) is also famous, but Malanjkhand is larger.

**🧠 Memory Tip:** **M**alanjkhand in **M**P.

**🚫 Scam Alert:** Khetri is historical, Malanjkhand is the current giant.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1ada5e8d-12fc-4a1c-915f-0943e9c7bc9b', '36a9b33e-de9c-4723-826b-4bb8623717b3', '''काला सोना'' (Black Gold) के रूप में जाना जाने वाला पेट्रोलियम, भारत में सबसे पहले कहाँ खोजा गया था?', '[{"id":"A","text":"बॉम्बे हाई (Bombay High)","text_en":"बॉम्बे हाई (Bombay High)"},{"id":"B","text":"डिगबोई (Digboi)","text_en":"डिगबोई (Digboi)"},{"id":"C","text":"अंलेश्वर (Ankleshwar)","text_en":"अंलेश्वर (Ankleshwar)"},{"id":"D","text":"बाड़मेर (Barmer)","text_en":"बाड़मेर (Barmer)"}]', '1', '**✅ Correct Logic:** भारत में तेल सबसे पहले असम के **डिगबोई** (1866/1889) में खोजा गया था। यह एशिया की सबसे पुरानी तेल रिफाइनरी (1901) भी है।

**💡 Exam Fact:** बॉम्बे हाई (1974) वर्तमान में सबसे बड़ा उत्पादक है, लेकिन डिगबोई सबसे पुराना है।

**🧠 Memory Tip:** British said **Dig-Boy-Dig** -> Digboi.

**🚫 Scam Alert:** सबसे ज्यादा उत्पादन बॉम्बे हाई से होता है, लेकिन ''पहला'' डिगबोई था।', 2, 0, 5, NULL, 'Petroleum, known as ''Black Gold'', was first discovered in India at which place?', '**✅ Correct Logic:** Oil was first discovered in **Digboi** (Assam) in 1866/1889. It hosts Asia''s oldest refinery (1901).

**💡 Exam Fact:** Bombay High (1974) is current largest producer, but Digboi is oldest.

**🧠 Memory Tip:** **Dig-Boy-Dig**.

**🚫 Scam Alert:** Largest is Bombay High, First is Digboi.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('30aa2344-1048-4e96-98ed-19224778db58', '36a9b33e-de9c-4723-826b-4bb8623717b3', '''कोरापुट'' (Koraput) किस खनिज के लिए प्रसिद्ध है?', '[{"id":"A","text":"लौह अयस्क (Iron Ore)","text_en":"लौह अयस्क (Iron Ore)"},{"id":"B","text":"बॉक्साइट (Bauxite)","text_en":"बॉक्साइट (Bauxite)"},{"id":"C","text":"मैंगनीज (Manganese)","text_en":"मैंगनीज (Manganese)"},{"id":"D","text":"सोना (Gold)","text_en":"सोना (Gold)"}]', '1', '**✅ Correct Logic:** कोरापुट (ओडिशा) **बॉक्साइट** (एल्युमीनियम का अयस्क) के लिए प्रसिद्ध है। ओडिशा भारत का सबसे बड़ा बॉक्साइट उत्पादक राज्य है।

**💡 Exam Fact:** नाल्को (NALCO) का संयंत्र यहीं पास (दमनजोड़ी) में स्थित है।

**🧠 Memory Tip:** **Box**er lives in **Kora**put -> Bauxite.

**🚫 Scam Alert:** क्योंझर (Keonjhar) लोहे/मैंगनीज के लिए है, कोरापुट बॉक्साइट के लिए है।', 2, 0, 6, NULL, 'For which mineral is ''Koraput'' famous?', '**✅ Correct Logic:** Koraput (Odisha) is famous for **Bauxite**. Odisha is India''s largest Bauxite producer.

**💡 Exam Fact:** NALCO plant is located nearby at Damanjodi.

**🧠 Memory Tip:** **Box**er lives in **Kora**put.

**🚫 Scam Alert:** Keonjhar is for Iron/Mn, Koraput is for Bauxite.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ea0f551f-1fce-44ff-9627-e164eef9a92a', '36a9b33e-de9c-4723-826b-4bb8623717b3', 'जादुगुडा (Jaduguda) की खानें किस लिए जानी जाती हैं?', '[{"id":"A","text":"हीरा (Diamond)","text_en":"हीरा (Diamond)"},{"id":"B","text":"यूरेनियम (Uranium)","text_en":"यूरेनियम (Uranium)"},{"id":"C","text":"जिंक (Zinc)","text_en":"जिंक (Zinc)"},{"id":"D","text":"क्रोमाइट (Chromite)","text_en":"क्रोमाइट (Chromite)"}]', '1', '**✅ Correct Logic:** जादुगुडा (सिंहभूम जिला, झारखंड) भारत की पहली और सबसे महत्वपूर्ण **यूरेनियम** खदान है। इसका संचालन UCIL द्वारा किया जाता है।

**💡 Exam Fact:** तुमलापल्ली (आंध्र प्रदेश) में भी विशाल यूरेनियम भंडार मिले हैं।

**🧠 Memory Tip:** **Jadu** (Magic) -> Nuclear power is magic -> Uranium.

**🚫 Scam Alert:** पन्ना (MP) हीरे के लिए है, जावर (राजस्थान) जिंक के लिए है। जादुगुडा यूरेनियम है।', 2, 0, 7, NULL, 'What are the mines of Jaduguda known for?', '**✅ Correct Logic:** Jaduguda (Jharkhand) is India''s first and most important **Uranium** mine. Operated by UCIL.

**💡 Exam Fact:** Tummalapalle (AP) also has huge uranium reserves.

**🧠 Memory Tip:** **Jadu** (Magic) -> Uranium.

**🚫 Scam Alert:** Panna is Diamond. Jaduguda is Uranium.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c17b5282-024e-47aa-969b-8e274a52c471', '36a9b33e-de9c-4723-826b-4bb8623717b3', 'छोटा नागपुर पठार को ''भारत का रूर'' (Ruhr of India) क्यों कहा जाता है?', '[{"id":"A","text":"घने वनों के कारण (Due to dense forests)","text_en":"घने वनों के कारण (Due to dense forests)"},{"id":"B","text":"खनिज संपदा की प्रचुरता के कारण (Due to abundance of mineral wealth)","text_en":"खनिज संपदा की प्रचुरता के कारण (Due to abundance of mineral wealth)"},{"id":"C","text":"उपजाऊ मिट्टी के कारण (Due to fertile soil)","text_en":"उपजाऊ मिट्टी के कारण (Due to fertile soil)"},{"id":"D","text":"पर्यटन क्षमता के कारण (Due to tourism potential)","text_en":"पर्यटन क्षमता के कारण (Due to tourism potential)"}]', '1', '**✅ Correct Logic:** जर्मनी की ''रूर घाटी'' (Ruhr Valley) कोयला और खनिजों के लिए प्रसिद्ध है। उसी तरह, छोटा नागपुर पठार में भारत का सर्वाधिक **खनिज** (कोयला, लोहा, अभ्रक) पाया जाता है, इसलिए इसे यह उपमा दी गई है।

**💡 Exam Fact:** दामोदर घाटी को ''औद्योगिक भारत की रीढ़'' कहते हैं।

**🧠 Memory Tip:** **Ruhr** is **Rich** in rocks.

**🚫 Scam Alert:** रूर जर्मनी में है, तुलना खनिजों के कारण है।', 2, 0, 8, NULL, 'Why is Chota Nagpur Plateau called ''Ruhr of India''?', '**✅ Correct Logic:** Like Germany''s ''Ruhr Valley'' (famous for coal/minerals), Chota Nagpur is rich in **Minerals** (Coal, Iron, Mica). Hence the nickname.

**💡 Exam Fact:** Damodar Valley is the backbone of industrial India.

**🧠 Memory Tip:** **Ruhr** is **Rich**.

**🚫 Scam Alert:** Comparison is based on Minerals, not agriculture.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fee2dc7b-80cb-4184-b2eb-67eef5be6aa3', '36a9b33e-de9c-4723-826b-4bb8623717b3', 'एंथ्रेसाइट (Anthracite) कोयले की सर्वोत्तम किस्म है। भारत में यह मुख्य रूप से कहाँ पाया जाता है?', '[{"id":"A","text":"रानीगंज (Raniganj)","text_en":"रानीगंज (Raniganj)"},{"id":"B","text":"नेवेली (Neyveli)","text_en":"नेवेली (Neyveli)"},{"id":"C","text":"रियासी (जम्मू-कश्मीर) (Reasi - J&K)","text_en":"रियासी (जम्मू-कश्मीर) (Reasi - J&K)"},{"id":"D","text":"सिंगरौली (Singrauli)","text_en":"सिंगरौली (Singrauli)"}]', '2', '**✅ Correct Logic:** भारत में उच्च कोटि का एंथ्रेसाइट कोयला बहुत कम मात्रा में केवल **जम्मू-कश्मीर (रियासी जिला)** में पाया जाता है। भारत का अधिकांश कोयला ''बिटुमिनस'' (Bituminous - गोंडवाना) प्रकार का है।

**💡 Exam Fact:** नेवेली (तमिलनाडु) में ''लिग्नाइट'' (भूरा कोयला) मिलता है।

**🧠 Memory Tip:** **A**nthracite at the **A**pex (Top of India - J&K).

**🚫 Scam Alert:** रानीगंज और झरिया में बिटुमिनस है। एंथ्रेसाइट केवल J&K में है।', 2, 0, 9, NULL, 'Anthracite is the best quality of coal. Where is it mainly found in India?', '**✅ Correct Logic:** High quality Anthracite is found only in **J&K (Reasi district)** in India. Most Indian coal is Bituminous.

**💡 Exam Fact:** Neyveli has Lignite (Brown Coal).

**🧠 Memory Tip:** **A**nthracite at the **A**pex (J&K).

**🚫 Scam Alert:** Raniganj has Bituminous. Anthracite is rare.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ee7f2cd7-5f99-4ffb-ac4b-8e9a44db0ead', '36a9b33e-de9c-4723-826b-4bb8623717b3', 'निम्नलिखित खनिजों को उनके प्रमुख खनन केंद्रों से सुमेलित करें (Match the following minerals with their major mining centers):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **हीरा**: पन्ना (म.प्र.)। एशिया की एकमात्र सक्रिय मैकेनाइज्ड हीरा खदान। -> (1)-(a)
* **सोना**: कोलार गोल्ड फील्ड्स (KGF) और हट्टी (कर्नाटक)। -> (2)-(b)
* **जिंक/सीसा**: जावर खानें (उदयपुर, राजस्थान)। इन्हें ''जुड़वा खनिज'' (Twin Minerals) कहते हैं। -> (3)-(c)
* **लिग्नाइट**: नेवेली (तमिलनाडु)। -> (4)-(d)

**💡 Exam Fact:** गोलकुंडा (ऐतिहासिक) से कोहिनूर मिला था।

**🧠 Memory Tip:** **Panna** is Diamond. **KGF** is Gold. **Zawar** is Zinc. **Neyveli** is Brown Coal.

**🚫 Scam Alert:** बहुत सीधा सवाल है, लेकिन जिंक और सीसा हमेशा साथ मिलते हैं (Galena ore)।', 2, 0, 10, NULL, 'Match the following minerals with their major mining centers:', '**✅ Correct Matching:**
* **Diamond**: Panna (MP). -> (1)-(a)
* **Gold**: Kolar/Hutti (Karnataka). -> (2)-(b)
* **Zinc/Lead**: Zawar (Rajasthan). Twin Minerals. -> (3)-(c)
* **Lignite**: Neyveli (TN). -> (4)-(d)

**💡 Exam Fact:** Zinc and Lead are found together.

**🧠 Memory Tip:** **Panna**-Diamond. **KGF**-Gold.

**🚫 Scam Alert:** Simple but high yield.', 60, 'matching', '[{"id":"(1)","label":"हीरा (Diamond)","match":"पन्ना (Panna)","matchId":"(a)"},{"id":"(2)","label":"सोना (Gold)","match":"कोलार/हट्टी (Kolar/Hutti)","matchId":"(b)"},{"id":"(3)","label":"जिंक/सीसा (Zinc/Lead)","match":"जावर (Zawar)","matchId":"(c)"},{"id":"(4)","label":"लिग्नाइट (Lignite)","match":"नेवेली (Neyveli)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('266b7e77-1744-4c27-b556-55964769ba61', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'मध्य प्रदेश राज्य वन विकास निगम (MPSFDC) की स्थापना किस वर्ष की गई थी?', '[{"id":"A","text":"24 जुलाई 1975","text_en":"24 जुलाई 1975"},{"id":"B","text":"1 नवंबर 1956","text_en":"1 नवंबर 1956"},{"id":"C","text":"13 फरवरी 1964","text_en":"13 फरवरी 1964"},{"id":"D","text":"24 जुलाई 1980","text_en":"24 जुलाई 1980"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश राज्य वन विकास निगम की स्थापना 24 जुलाई 1975 को की गई थी। इसका मुख्य उद्देश्य कम मूल्य के वनों को उच्च मूल्य के वनों में बदलना है।
💡 **Exam Fact**: यह निगम वनों के वैज्ञानिक प्रबंधन में मदद करता है।
🧠 **Memory Tip**: 1975 - आपातकाल के समय ''वन'' का विकास शुरू हुआ (Just a trick).
🚫 **Scam Alert**: 1956 मध्य प्रदेश की स्थापना का वर्ष है, इसे निगम की स्थापना से न जोड़ें।', 2, 0, 1, NULL, 'In which year was the Madhya Pradesh State Forest Development Corporation (MPSFDC) established?', '✅ **Correct Logic**: The MP State Forest Development Corporation was established on July 24, 1975. Its main goal is to convert low-value forests into high-value forest crops.
💡 **Exam Fact**: This corporation assists in the scientific management of forests.
🧠 **Memory Tip**: 1975 - Think of forest development starting during the Emergency era (Mnemonic).
🚫 **Scam Alert**: 1956 is the formation year of MP, don''t confuse it with the corporation''s establishment.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c448343c-3841-49bc-9517-75bc8f5b71ca', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'भारतीय वन स्थिति रिपोर्ट (ISFR) 2021 के अनुसार, मध्य प्रदेश के किस जिले में सर्वाधिक वन क्षेत्र (Area wise) पाया जाता है?', '[{"id":"A","text":"बालाघाट","text_en":"बालाघाट"},{"id":"B","text":"छिंदवाड़ा","text_en":"छिंदवाड़ा"},{"id":"C","text":"बैतूल","text_en":"बैतूल"},{"id":"D","text":"श्योपुर","text_en":"श्योपुर"}]', '0', '✅ **Correct Logic**: बालाघाट में सर्वाधिक वन क्षेत्र (4,923 वर्ग किमी) पाया जाता है।
💡 **Exam Fact**: बालाघाट में वन प्रतिशत (Percentage) भी सर्वाधिक है।
🧠 **Memory Tip**: ''B'' for Balaghat, ''B'' for Big Forest Area.
🚫 **Scam Alert**: छिंदवाड़ा क्षेत्रफल में बड़ा जिला है, लेकिन वन क्षेत्र में बालाघाट के बाद दूसरे स्थान पर आता है।', 2, 0, 2, NULL, 'According to the India State of Forest Report (ISFR) 2021, which district of MP has the maximum forest cover (Area wise)?', '✅ **Correct Logic**: Balaghat has the highest forest cover area (4,923 sq km) in Madhya Pradesh.
💡 **Exam Fact**: Balaghat also leads in forest percentage.
🧠 **Memory Tip**: ''B'' for Balaghat, ''B'' for Big Forest Area.
🚫 **Scam Alert**: While Chhindwara is a large district by geography, it ranks second after Balaghat in terms of forest area.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('208b5407-8abd-4de4-a451-b625161d66dc', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'निम्नलिखित में से कौन सी वनोपज मध्य प्रदेश में ''हरा सोना'' (Green Gold) के नाम से जानी जाती है?', '[{"id":"A","text":"सागौन","text_en":"सागौन"},{"id":"B","text":"तेंदूपत्ता","text_en":"तेंदूपत्ता"},{"id":"C","text":"बाँस","text_en":"बाँस"},{"id":"D","text":"महुआ","text_en":"महुआ"}]', '1', '✅ **Correct Logic**: तेंदूपत्ता को मध्य प्रदेश में ''हरा सोना'' कहा जाता है क्योंकि यह राज्य के राजस्व और जनजातीय अर्थव्यवस्था का प्रमुख आधार है।
💡 **Exam Fact**: मध्य प्रदेश तेंदूपत्ता उत्पादन में भारत में प्रथम स्थान पर है।
🧠 **Memory Tip**: Tendu - Tea - Green Gold (Visual connection).
🚫 **Scam Alert**: बाँस को दुनिया भर में ''हरा सोना'' कहा जाता है, लेकिन मध्य प्रदेश के विशिष्ट संदर्भ में तेंदूपत्ता के लिए यह शब्द प्रयोग होता है।', 2, 0, 3, NULL, 'Which of the following forest produce is known as ''Green Gold'' in Madhya Pradesh?', '✅ **Correct Logic**: Tendu leaf is called ''Green Gold'' in MP as it is a major source of revenue and tribal livelihood.
💡 **Exam Fact**: Madhya Pradesh ranks first in India in Tendu leaf production.
🧠 **Memory Tip**: Tendu - Tea - Green Gold (Visual connection).
🚫 **Scam Alert**: While Bamboo is globally called Green Gold, in the specific context of MP''s forest produce exams, Tendu leaf is the correct answer.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('32c9f3a4-4d7f-4665-8f43-23b7bfe55145', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'प्रशासनिक आधार पर मध्य प्रदेश के वनों को तीन श्रेणियों में बाँटा गया है। इनमें से किसका प्रतिशत सर्वाधिक है?', '[{"id":"A","text":"आरक्षित वन (Reserved Forests)","text_en":"आरक्षित वन (Reserved Forests)"},{"id":"B","text":"संरक्षित वन (Protected Forests)","text_en":"संरक्षित वन (Protected Forests)"},{"id":"C","text":"अवर्गीकृत वन (Unclassified Forests)","text_en":"अवर्गीकृत वन (Unclassified Forests)"},{"id":"D","text":"निजी वन","text_en":"निजी वन"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश में लगभग 65% वन ''आरक्षित वन'' की श्रेणी में आते हैं।
💡 **Exam Fact**: आरक्षित वनों में मानवीय गतिविधियाँ पूरी तरह प्रतिबंधित होती हैं।
🧠 **Memory Tip**: R for Reserved, R for Rigorous/Restrictive (Maximum control).
🚫 **Scam Alert**: संरक्षित वन लगभग 33% हैं, इन्हें आरक्षित से अधिक न समझें।', 2, 0, 4, NULL, 'Based on administrative classification, forests of MP are divided into three categories. Which of these has the highest percentage?', '✅ **Correct Logic**: About 65% of forests in MP fall under the ''Reserved Forest'' category.
💡 **Exam Fact**: Human activities are strictly prohibited in Reserved Forests.
🧠 **Memory Tip**: R for Reserved, R for Rigorous/Restrictive (Maximum control).
🚫 **Scam Alert**: Protected forests account for about 33%; do not mistake them for being higher than Reserved forests.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0376f50c-44fa-4b76-b782-c988e7779d91', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'वनोपज और उनके उपयोग के संबंध में सही मिलान करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: खैर से कत्था, भिलाला से स्याही, हर्रा से चर्म शोधन और लाख का उपयोग चूड़ियों के लिए किया जाता है।
💡 **Exam Fact**: कत्था बनाने का सरकारी कारखाना शिवपुरी और बानमोर (मुरैना) में है।
🧠 **Memory Tip**: Khair-Katha (K-K).
🚫 **Scam Alert**: लाख कीड़ों (Laccifer Lacca) से प्राप्त होता है, पेड़ों का फल नहीं है।', 2, 0, 5, NULL, 'Match the following forest produce and their uses:', '✅ **Correct Logic**: Khair is used for Katha, Bhilala for ink, Harra for tanning, and Lac for bangles.
💡 **Exam Fact**: Government Katha factories are located in Shivpuri and Banmore (Morena).
🧠 **Memory Tip**: Khair-Katha (K-K).
🚫 **Scam Alert**: Lac is obtained from insects (Laccifer Lacca), it is not a fruit of the tree.', 60, 'matching', '[{"id":"(1)","label":"खैर (Khair)","match":"कत्था निर्माण","matchId":"(a)"},{"id":"(2)","label":"भिलाला (Bhilala)","match":"स्याही और पेंट","matchId":"(b)"},{"id":"(3)","label":"हर्रा (Harra)","match":"चर्म शोधन (Tanning)","matchId":"(c)"},{"id":"(4)","label":"लाख (Lac)","match":"चूड़ी और आभूषण","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7f243840-0110-441c-afab-12c3fa1f9590', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'मध्य प्रदेश का वह जिला कौन सा है जिसे ''सागौन का कटोरा'' कहा जाता है क्योंकि यहाँ उच्च गुणवत्ता का सागौन पाया जाता है?', '[{"id":"A","text":"होशंगाबाद (नर्मदापुरम)","text_en":"होशंगाबाद (नर्मदापुरम)"},{"id":"B","text":"धार","text_en":"धार"},{"id":"C","text":"शिवपुरी","text_en":"शिवपुरी"},{"id":"D","text":"झाबुआ","text_en":"झाबुआ"}]', '0', '✅ **Correct Logic**: होशंगाबाद की ''बोरी घाटी'' (Bori Valley) अपने सर्वश्रेष्ठ सागौन वनों के लिए प्रसिद्ध है।
💡 **Exam Fact**: सागौन (Tectona grandis) मध्य प्रदेश का सबसे प्रमुख वृक्ष है (कुल वनों का ~19%)।
🧠 **Memory Tip**: Bori Valley - Boras of Teak (Just to remember).
🚫 **Scam Alert**: सागौन काली मिट्टी वाले क्षेत्रों में अधिक होता है, इसलिए चंबल क्षेत्र में यह कम पाया जाता है।', 2, 0, 6, NULL, 'Which district of MP is called the ''Bowl of Teak'' because of the high-quality teak found there?', '✅ **Correct Logic**: Bori Valley in Hoshangabad is famous for its premier quality teak forests.
💡 **Exam Fact**: Teak (Tectona grandis) is the most dominant tree species in MP (~19% of total forests).
🧠 **Memory Tip**: Bori Valley - Think of bags/sacks full of Teak.
🚫 **Scam Alert**: Teak thrives in black soil areas; hence, it is scarce in the Chambal region.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('83124348-d1b3-420f-bb7b-12fc473e2123', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'मध्य प्रदेश की पहली ''वन नीति'' किस वर्ष घोषित की गई थी?', '[{"id":"A","text":"1952","text_en":"1952"},{"id":"B","text":"1956","text_en":"1956"},{"id":"C","text":"2005","text_en":"2005"},{"id":"D","text":"2002","text_en":"2002"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश की पहली वन नीति 1952 में घोषित की गई थी। नई वन नीति 2005 में आई।
💡 **Exam Fact**: 1952 की नीति राष्ट्रीय वन नीति के अनुरूप थी।
🧠 **Memory Tip**: MP was formed in 56, but policy came in 52 (Pre-formation).
🚫 **Scam Alert**: 2005 वर्तमान/नवीनतम नीति है, पहली नहीं।', 2, 0, 7, NULL, 'In which year was the first ''Forest Policy'' of Madhya Pradesh announced?', '✅ **Correct Logic**: The first Forest Policy of MP was announced in 1952. The new policy came in 2005.
💡 **Exam Fact**: The 1952 policy was in line with the National Forest Policy.
🧠 **Memory Tip**: MP was formed in ''56, but the forest policy dates back to ''52.
🚫 **Scam Alert**: 2005 is the current/latest policy, not the first.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8f52cdde-d7a1-4c69-a798-d9f671129843', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'उष्णकटिबंधीय पर्णपाती वनों (Tropical Deciduous Forests) के संबंध में निम्नलिखित कथनों पर विचार करें:
1. ये वन 75 से 100 सेमी वर्षा वाले क्षेत्रों में पाए जाते हैं।
2. सागौन इन वनों का मुख्य वृक्ष है।
3. ये वन ग्रीष्म ऋतु में अपनी पत्तियाँ गिरा देते हैं।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '2', '✅ **Correct Logic**: तीनों कथन सत्य हैं। मध्य प्रदेश में सर्वाधिक क्षेत्र पर उष्णकटिबंधीय पर्णपाती वन ही पाए जाते हैं।
💡 **Exam Fact**: ये वन सागर, दमोह, जबलपुर और होशंगाबाद जिलों में फैले हैं।
🧠 **Memory Tip**: Deciduous = Decide to drop leaves.
🚫 **Scam Alert**: 150 सेमी से अधिक वर्षा वाले क्षेत्रों में ''सदाबहार'' वन पाए जाते हैं, न कि पर्णपाती।', 2, 0, 8, NULL, 'Consider the following statements regarding Tropical Deciduous Forests:
1. These forests are found in areas with 75-100 cm rainfall.
2. Teak is the main tree of these forests.
3. These forests shed their leaves in the summer season.

Choose the correct statement:', '✅ **Correct Logic**: All three statements are true. Tropical deciduous forests occupy the largest area in MP.
💡 **Exam Fact**: These forests are spread across Sagar, Damoh, Jabalpur, and Hoshangabad districts.
🧠 **Memory Tip**: Deciduous = They ''decide'' to drop leaves to save water.
🚫 **Scam Alert**: Areas with >150 cm rainfall support ''Evergreen'' forests, not deciduous.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('56d1c67d-440e-443a-ae49-c8cc514e1eb0', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'मध्य प्रदेश में ''लाख'' (Lac) बनाने का सरकारी कारखाना कहाँ स्थित है?', '[{"id":"A","text":"उमरिया","text_en":"उमरिया"},{"id":"B","text":"सिवनी","text_en":"सिवनी"},{"id":"C","text":"शहडोल","text_en":"शहडोल"},{"id":"D","text":"जबलपुर","text_en":"जबलपुर"}]', '0', '✅ **Correct Logic**: उमरिया में लाख बनाने का सरकारी कारखाना स्थित है।
💡 **Exam Fact**: लाख पलाश और कुसुम के पेड़ों पर रहने वाले कीटों से प्राप्त होता है।
🧠 **Memory Tip**: ''U'' for Umaria, ''U'' for Unique Lac factory.
🚫 **Scam Alert**: सिवनी में हर्रा का काम अधिक होता है, लाख के लिए उमरिया प्रसिद्ध है।', 2, 0, 9, NULL, 'Where is the government ''Lac'' factory located in Madhya Pradesh?', '✅ **Correct Logic**: The government Lac factory is situated in Umaria district.
💡 **Exam Fact**: Lac is produced from insects residing on Palash and Kusum trees.
🧠 **Memory Tip**: ''U'' for Umaria, ''U'' for Unique Lac factory.
🚫 **Scam Alert**: Seoni is known for Harra processing, while Umaria is the hub for Lac.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('85a146e9-56f1-4e15-9e02-9e4cd12c3837', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'मध्य प्रदेश वन विभाग का मुख्यालय ''सतपुड़ा भवन'' कहाँ स्थित है?', '[{"id":"A","text":"इंदौर","text_en":"इंदौर"},{"id":"B","text":"जबलपुर","text_en":"जबलपुर"},{"id":"C","text":"भोपाल","text_en":"भोपाल"},{"id":"D","text":"ग्वालियर","text_en":"ग्वालियर"}]', '2', '✅ **Correct Logic**: मध्य प्रदेश के लगभग सभी प्रमुख सरकारी विभागों के मुख्यालय भोपाल में स्थित हैं, सतपुड़ा भवन भी वहीं है।
💡 **Exam Fact**: मध्य प्रदेश वनों का राष्ट्रीयकरण (1970) करने वाला भारत का पहला राज्य है।
🧠 **Memory Tip**: S-B (Satpura Bhawan - Bhopal).
🚫 **Scam Alert**: राज्य वन अनुसंधान संस्थान (SFRI) जबलपुर में है, मुख्यालय भोपाल में।', 2, 0, 10, NULL, 'Where is ''Satpura Bhawan'', the headquarters of the MP Forest Department, located?', '✅ **Correct Logic**: Most state-level government headquarters are in Bhopal, including Satpura Bhawan.
💡 **Exam Fact**: MP was the first state to nationalize forests in 1970.
🧠 **Memory Tip**: S-B (Satpura Bhawan - Bhopal).
🚫 **Scam Alert**: The State Forest Research Institute (SFRI) is in Jabalpur, but the Department HQ is in Bhopal.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('TE8DOqzAeiNYomK6YszHC', 'Emxd0IiqwsczyIjPx1YxZ', 'संचार में ''बर्लो के मॉडल'' (Berlo''s Model) के चार घटक कौन से हैं?', '"[\"S-M-C-R (Source, Message, Channel, Receiver)\",\"S-R-M-C (Sender, Receiver, Medium, Context)\",\"M-S-C-R (Message, Source, Code, Receiver)\",\"S-E-D-R (Source, Encoder, Decoder, Receiver)\"]"', '0.0', 'बर्लो का मॉडल SMCR (स्रोत, संदेश, चैनल, रिसीवर) पर आधारित है।', 2, 0, 1, 'Communication', 'What are the four components of ''Berlo''s Model'' of communication?', 'Berlo''s model is famous as the SMCR model.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2QARCMLZjrUomCOhYUN26', 'Emxd0IiqwsczyIjPx1YxZ', 'अशाब्दिक संचार के प्रकारों को सुमेलित करें:', '"[\"(1)-(c), (2)-(a), (3)-(b), (4)-(d)\",\"(1)-(a), (2)-(b), (3)-(c), (4)-(d)\",\"(1)-(b), (2)-(c), (3)-(d), (4)-(a)\",\"(1)-(d), (2)-(a), (3)-(b), (4)-(c)\"]"', '0.0', 'Proxemics=Space, Chronemics=Time, Haptics=Touch, Kinesics=Body.', 2, 0, 2, 'Communication', 'Match types of Non-verbal communication:', 'Proxemics=Space, Chronemics=Time, Haptics=Touch, Kinesics=Body.', 60, 'matching', '[{"id":"(1)","label":"Proxemics","match":"Time usage","matchId":"(a)"},{"id":"(2)","label":"Chronemics","match":"Touch","matchId":"(b)"},{"id":"(3)","label":"Haptics","match":"Space/Distance","matchId":"(c)"},{"id":"(4)","label":"Kinesics","match":"Body movement","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8Ms9Z4cD6hn6BeCXzsIRv', 'Emxd0IiqwsczyIjPx1YxZ', 'पारस्परिक संचार में ''सुनना'' (Hearing) और ''श्रवण'' (Listening) में क्या मुख्य अंतर है?', '"[\"सुनना एक शारीरिक प्रक्रिया है, श्रवण एक मानसिक प्रक्रिया है / Hearing is physiological, Listening is psychological/mental\",\"दोनों एक ही हैं / Both are same\",\"सुनना मानसिक है, श्रवण शारीरिक है / Hearing is mental, Listening is physiological\",\"श्रवण में कानों की आवश्यकता नहीं होती / Listening doesn''t need ears\"]"', '0.0', 'सुनना (Hearing) केवल ध्वनि तरंगों का कानों तक पहुंचना है, जबकि श्रवण (Listening) उसका अर्थ समझना है।', 2, 0, 3, 'Communication', 'What is the main difference between ''Hearing'' and ''Listening'' in interpersonal communication?', 'Hearing is the physical act; Listening involves interpreting meaning.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('o6ePh3jbhKdBqzti5E_Ji', 'Emxd0IiqwsczyIjPx1YxZ', 'यदि ''GO'' = 32, ''SHE'' = 49, तो ''SOME'' = ?', '"[\"56\",\"58\",\"62\",\"64\"]"', '0.0', 'विपरीत अक्षरों का योग (Reverse position sum). G(20)+O(12)=32. S(8)+H(19)+E(22)=49. S(8)+O(12)+M(14)+E(22)=56.', 2, 0, 4, 'Reasoning', 'If ''GO'' = 32, ''SHE'' = 49, then ''SOME'' = ?', 'Sum of reverse alphabet positions (A=26... Z=1).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('V_5iteWL1_FJm8jOnpM9B', 'Emxd0IiqwsczyIjPx1YxZ', 'एक व्यक्ति पश्चिम की ओर मुंह करके खड़ा है। वह 45° दक्षिणावर्त (clockwise) मुड़ता है और फिर 180° उसी दिशा में मुड़ता है। अंत में वह 270° वामावर्त (anti-clockwise) मुड़ता है। अब वह किस दिशा में है?', '"[\"South-West\",\"North-West\",\"West\",\"South\"]"', '0.0', 'पश्चिम (West) से शुरू। नेट रोटेशन = +45 + 180 - 270 = 225 - 270 = -45° (वामावर्त)। पश्चिम से 45° वामावर्त = दक्षिण-पश्चिम (South-West)।', 2, 0, 5, 'Reasoning', 'A person is facing West. He turns 45° clockwise, then 180° in same direction, then 270° anti-clockwise. Which direction is he facing now?', 'Net movement: 45 (CW) + 180 (CW) - 270 (ACW) = -45 (ACW). West - 45° = SW.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('YjEdNZ9PMSXxzjZ-RWIvT', 'Emxd0IiqwsczyIjPx1YxZ', 'श्रृंखला: 10, 14, 26, 42, 70, ?', '"[\"100\",\"102\",\"114\",\"118\"]"', '2.0', 'पैटर्न: पिछले दो पदों का योग - 2? नहीं। अंतर देखें: 4, 12, 16, 28... स्पष्ट नहीं। वैकल्पिक: 10+14+2=26. 14+26+2=42. 26+42+2=70. 42+70+2=114.', 2, 0, 6, 'Reasoning', 'Series: 10, 14, 26, 42, 70, ?', 'Sum of previous two terms + 2. (42+70)+2 = 114.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('SZgcc4LJjfhImqGaX34MY', 'Emxd0IiqwsczyIjPx1YxZ', 'कथन: सभी चाबियाँ ताले हैं। सभी ताले दरवाजे हैं। कुछ दरवाजे खिड़कियाँ हैं। निष्कर्ष: (I) कुछ चाबियाँ खिड़कियाँ हैं। (II) कुछ दरवाजे ताले हैं।', '"[\"केवल I\",\"केवल II\",\"दोनों\",\"कोई नहीं\"]"', '1.0', 'चाबियाँ और खिड़कियों में सीधा संबंध नहीं है (I गलत)। चूंकि सभी ताले दरवाजे हैं, तो दरवाजों का कुछ हिस्सा ताले हैं (II सही)।', 2, 0, 7, 'Reasoning', 'Statements: All keys are locks. All locks are doors. Some doors are windows. Conclusions: (I) Some keys are windows. (II) Some doors are locks.', 'Keys are inside Doors. Windows touch Doors. Keys don''t necessarily touch Windows. II follows.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4WEFGGdEgwcXLRiPYw_jg', 'Emxd0IiqwsczyIjPx1YxZ', 'A किसी काम को 12 दिनों में कर सकता है। B, A से 60% अधिक कुशल है। B उसी काम को कितने दिनों में करेगा?', '"[\"7.5 days\",\"8 days\",\"6 days\",\"10 days\"]"', '0.0', 'दक्षता अनुपात A:B = 100:160 = 5:8। समय अनुपात = 8:5। यदि 8 इकाई = 12 दिन, तो 5 इकाई = (12/8)*5 = 7.5 दिन।', 2, 0, 8, 'Quantitative Aptitude', 'A can do a work in 12 days. B is 60% more efficient than A. How many days will B take?', 'Efficiency ratio 5:8 -> Time ratio 8:5. 8u=12 -> 5u=7.5.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cb09cKC-NBcnFvrAL_JNt', 'Emxd0IiqwsczyIjPx1YxZ', 'एक संख्या के 75% में जब 75 जोड़ा जाता है, तो परिणाम वही संख्या होती है। संख्या ज्ञात करें।', '"[\"300\",\"150\",\"200\",\"400\"]"', '0.0', '75%x + 75 = x. 25%x = 75. x = 75 * 4 = 300.', 2, 0, 9, 'Quantitative Aptitude', 'When 75 is added to 75% of a number, the result is the number itself. Find the number.', 'Remaining 25% is 75. Total is 300.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('YwKpQKlyKk6EKz4bglqTf', 'Emxd0IiqwsczyIjPx1YxZ', 'यदि ''A'' का अर्थ ''+'', ''B'' का अर्थ ''-'', ''C'' का अर्थ ''×'' है, तो (7 C 4) B (2 C 5) A 6 = ?', '"[\"24\",\"20\",\"18\",\"22\"]"', '0.0', '(7×4) - (2×5) + 6 = 28 - 10 + 6 = 24.', 2, 0, 10, 'Reasoning', 'If A=+, B=-, C=×, then (7 C 4) B (2 C 5) A 6 = ?', '28 - 10 + 6 = 24.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('uTeHBuVQTK2qLXExPbVxm', 'Emxd0IiqwsczyIjPx1YxZ', '40 छात्रों की एक पंक्ति में, ''मोहित'' दाईं ओर से 14वें स्थान पर है। बाईं ओर से उसका स्थान क्या है?', '"[\"26\",\"27\",\"25\",\"28\"]"', '1.0', 'बाएं = कुल - दाएं + 1 = 40 - 14 + 1 = 27.', 2, 0, 11, 'Reasoning', 'In a row of 40 students, Mohit is 14th from the right. What is his rank from the left?', 'Total - Right + 1 = 27.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3XAg91dLDSL6C0vZLkcX3', 'Emxd0IiqwsczyIjPx1YxZ', 'कितने समय में ₹5000 की राशि 10% वार्षिक चक्रवृद्धि ब्याज पर ₹6655 हो जाएगी?', '"[\"2 years\",\"3 years\",\"4 years\",\"2.5 years\"]"', '1.0', 'A = P(1 + R/100)^n. 6655/5000 = (11/10)^n. 1331/1000 = (1.1)^n. (1.1)^3 = 1.331. n=3.', 2, 0, 12, 'Quantitative Aptitude', 'In what time will ₹5000 become ₹6655 at 10% CI?', '1331/1000 is cube of 11/10.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('XB91lhnLa22mUbFQ31tWD', 'Emxd0IiqwsczyIjPx1YxZ', 'निम्नलिखित शब्दों को तार्किक क्रम में व्यवस्थित करें: 1. बीज, 2. फल, 3. पौधा, 4. भोजन', '"[\"1, 3, 2, 4\",\"1, 2, 3, 4\",\"3, 1, 2, 4\",\"4, 1, 3, 2\"]"', '0.0', 'बीज -> पौधा -> फल -> भोजन।', 2, 0, 13, 'Reasoning', 'Arrange logically: 1. Seed, 2. Fruit, 3. Plant, 4. Food', 'Seed grows to Plant, yields Fruit, becomes Food.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('uMuPciEkl7jTQQ4K6G5E2', 'Emxd0IiqwsczyIjPx1YxZ', 'यदि 2¹² को 9 से विभाजित किया जाए, तो शेषफल क्या होगा?', '"[\"1\",\"8\",\"4\",\"2\"]"', '0.0', '2³ = 8. 2¹² = (2³)⁴ = 8⁴. 8 को 9 से भाग देने पर शेष -1 है। (-1)⁴ = 1।', 2, 0, 14, 'Quantitative Aptitude', 'If 2¹² is divided by 9, what is the remainder?', 'Modular arithmetic: 2^3 is congruent to -1 mod 9. (-1)^4 = 1.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cdTgs9YlhZ90b0TUqONqN', 'Emxd0IiqwsczyIjPx1YxZ', 'वेन आरेख: पुरुष, पिता, भाई।', '"[\"Concentric circles\",\"Two intersecting circles inside a big circle\",\"Three intersecting circles\",\"Separate circles\"]"', '1.0', 'सभी पिता और भाई पुरुष हैं (बड़े वृत्त के अंदर)। कुछ पिता भाई भी हो सकते हैं और कुछ भाई पिता भी (काटते हुए)।', 2, 0, 15, 'Reasoning', 'Venn Diagram: Men, Fathers, Brothers.', 'Fathers and Brothers overlap, and both are entirely inside Men.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('OGI60KAyX229o7c6Oq7D3', 'Emxd0IiqwsczyIjPx1YxZ', 'निर्णय लेना: आप एक ट्रैफिक पुलिस अधिकारी हैं। एक मंत्री की गाड़ी ने रेड लाइट जंप की है। आप क्या करेंगे?', '"[\"उसे जाने देंगे / Let him go\",\"चालान काटेंगे / Issue a challan\",\"उससे माफी मांगेंगे / Apologize to him\",\"वरिष्ठों से पूछेंगे / Ask seniors\"]"', '1.0', 'कानून सभी के लिए समान है। कर्तव्य का पालन (चालान) सही निर्णय है।', 2, 0, 16, 'Decision Making', 'Decision Making: You are a Traffic Police Officer. A Minister''s car jumped a red light. What will you do?', 'Rule of law applies to everyone.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('LWk8CFrp55NbvFJdXGzql', 'Emxd0IiqwsczyIjPx1YxZ', 'एक आयताकार मैदान की लंबाई उसकी चौड़ाई की दोगुनी है। यदि ₹2 प्रति मीटर की दर से बाड़ लगाने की लागत ₹1200 है, तो लंबाई क्या है?', '"[\"200 m\",\"100 m\",\"150 m\",\"300 m\"]"', '0.0', 'परिमाप = 1200/2 = 600m. 2(l+b) = 600. l+b=300. l=2b. 3b=300 -> b=100, l=200.', 2, 0, 17, 'Quantitative Aptitude', 'Length of rectangular field is twice its breadth. If cost of fencing at ₹2/m is ₹1200, find length.', 'Perimeter is 600. l=200, b=100.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('EMPxtUtlfkGaCelYT1GEY', 'Emxd0IiqwsczyIjPx1YxZ', '4 और 9 का मध्यानुपाती (Mean Proportional) क्या है?', '"[\"6\",\"6.5\",\"36\",\"13\"]"', '0.0', '√(4 × 9) = √36 = 6.', 2, 0, 18, 'Quantitative Aptitude', 'What is the Mean Proportional of 4 and 9?', 'Root of product.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('q7fwqReulvO-L3SIBLbVJ', 'Emxd0IiqwsczyIjPx1YxZ', 'A और B एक स्थान से विपरीत दिशाओं में चलना शुरू करते हैं। A की गति 3 किमी/घंटा और B की 4 किमी/घंटा है। 2 घंटे बाद वे एक-दूसरे से कितनी दूर होंगे?', '"[\"14 km\",\"7 km\",\"10 km\",\"12 km\"]"', '0.0', 'सापेक्ष गति = 3+4=7 किमी/घंटा। दूरी = 7 × 2 = 14 किमी।', 2, 0, 19, 'Quantitative Aptitude', 'A and B start from a point in opposite directions. Speed A=3 km/hr, B=4 km/hr. Distance after 2 hrs?', 'Relative speed (opposite) adds up. 7*2=14.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('gToTXv-C6ymgwBndjR636', 'Emxd0IiqwsczyIjPx1YxZ', 'यदि ''sky'' को ''sea'', ''sea'' को ''water'', ''water'' को ''air'', ''air'' को ''cloud'' कहा जाए, तो हम प्यास लगने पर क्या पीते हैं?', '"[\"Sky\",\"Air\",\"Water\",\"Sea\"]"', '1.0', 'हम ''water'' पीते हैं, और ''water'' को ''air'' कहा गया है।', 2, 0, 20, 'Reasoning', 'If ''sky'' is ''sea'', ''sea'' is ''water'', ''water'' is ''air'', ''air'' is ''cloud'', what do we drink when thirsty?', 'We drink water, Water is called Air.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('tj6djg4hiyEVSAQPkzjdG', 'Emxd0IiqwsczyIjPx1YxZ', 'एक अर्धगोले (Hemisphere) की त्रिज्या 7 सेमी है। इसका वक्र पृष्ठीय क्षेत्रफल (CSA) क्या है?', '"[\"308 cm²\",\"154 cm²\",\"616 cm²\",\"462 cm²\"]"', '0.0', 'CSA = 2πr² = 2 × (22/7) × 49 = 44 × 7 = 308.', 2, 0, 21, 'Quantitative Aptitude', 'Radius of Hemisphere is 7 cm. Its Curved Surface Area (CSA)?', 'Formula 2*pi*r^2.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('mjnzA-adAjXRX44QKZlS5', 'Emxd0IiqwsczyIjPx1YxZ', '2, 5, 10, 17, 26, ?', '"[\"37\",\"35\",\"36\",\"34\"]"', '0.0', 'पैटर्न: n² + 1. 1²+1, 2²+1, 3²+1, 4²+1, 5²+1. अगला 6²+1=37.', 2, 0, 22, 'Reasoning', '2, 5, 10, 17, 26, ?', 'n squared plus 1.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('iZiEgm5CxtKQxXI6yIMrF', 'Emxd0IiqwsczyIjPx1YxZ', 'ताश के 52 पत्तों में से एक पत्ता खींचने पर ''हुकुम का इक्का'' (Ace of Spades) आने की प्रायिकता क्या है?', '"[\"1/13\",\"1/52\",\"1/4\",\"1/26\"]"', '1.0', 'हुकुम का इक्का केवल 1 होता है। प्रायिकता = 1/52।', 2, 0, 23, 'Quantitative Aptitude', 'Probability of drawing ''Ace of Spades'' from 52 cards?', 'Only 1 specific card. 1/52.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('lV-qQrmqmx6v6AeXVppvY', 'Emxd0IiqwsczyIjPx1YxZ', 'यदि ''M'' का स्थान 13 है और ''MAT'' = 34 है, तो ''WAX'' = ?', '"[\"48\",\"49\",\"50\",\"45\"]"', '0.0', 'M(13)+A(1)+T(20)=34. W(23)+A(1)+X(24)=48. (Correction: 23+1+24 = 48).', 2, 0, 24, 'Reasoning', 'If M=13, MAT=34, then WAX=?', 'Sum: 23+1+24=48. Answer is 48.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('baMBekHYfBy1q2fjQcoOW', 'Emxd0IiqwsczyIjPx1YxZ', '1200 का 5/8 कितना है?', '"[\"750\",\"600\",\"800\",\"700\"]"', '0.0', '1200/8 = 150. 150 × 5 = 750.', 2, 0, 25, 'Quantitative Aptitude', 'What is 5/8 of 1200?', '150 * 5 = 750.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xTwOi2-BJRt7sLYvSRcLT', 'Emxd0IiqwsczyIjPx1YxZ', 'एक क्रिकेट खिलाड़ी की 10 पारियों का औसत 32 था। अगली पारी में उसे कितने रन बनाने चाहिए ताकि औसत 4 बढ़ जाए?', '"[\"76\",\"72\",\"66\",\"70\"]"', '0.0', 'नया औसत = 36. कुल पारियां = 11. कुल रन = 36×11 = 396. पुराने रन = 32×10 = 320. अंतर = 76। (Short trick: 32 + 11×4 = 76).', 2, 0, 26, 'Quantitative Aptitude', 'Avg of 10 innings is 32. How many runs in next inning to increase avg by 4?', 'New runs = Old Avg + (New Total Innings * Increase) = 32 + (11*4) = 76.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('we_2PRRzYcdFMYx9Y-u6T', 'Emxd0IiqwsczyIjPx1YxZ', 'लुप्त पद: 3, 12, 27, 48, 75, ?', '"[\"108\",\"100\",\"99\",\"112\"]"', '0.0', '3×1², 3×2², 3×3², 3×4², 3×5². अगला 3×6² = 3×36 = 108.', 2, 0, 27, 'Reasoning', 'Missing term: 3, 12, 27, 48, 75, ?', 'Multiples of 3 with squares.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('locsiemNfBSbeDM4mHID8', 'Emxd0IiqwsczyIjPx1YxZ', 'रवि ने ₹10 में 11 संतरे खरीदे और ₹11 में 10 संतरे बेचे। लाभ % क्या है?', '"[\"21%\",\"20%\",\"11%\",\"10%\"]"', '0.0', 'CP(1) = 10/11. SP(1) = 11/10. Cross multiply: CP=100, SP=121. Profit 21%.', 2, 0, 28, 'Quantitative Aptitude', 'Ravi bought 11 oranges for ₹10 and sold 10 oranges for ₹11. Profit %?', 'Standard CP/SP cross multiplication trick. 121-100 = 21%.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ca5dli3KioCcohkvoUiX5', 'Emxd0IiqwsczyIjPx1YxZ', 'वह छोटी से छोटी संख्या जिसे 12, 15, 20 से विभाजित करने पर प्रत्येक दशा में 4 शेष बचे?', '"[\"64\",\"60\",\"56\",\"68\"]"', '0.0', 'LCM(12,15,20) = 60. संख्या = 60 + 4 = 64.', 2, 0, 29, 'Quantitative Aptitude', 'Smallest number which when divided by 12, 15, 20 leaves remainder 4?', 'LCM + Remainder = 64.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Ms4yie2HEdVfW5eCS_wqs', 'Emxd0IiqwsczyIjPx1YxZ', 'घड़ी की सुइयां 12 घंटे में कितनी बार 90° का कोण बनाती हैं?', '"[\"22\",\"24\",\"44\",\"11\"]"', '0.0', 'एक घंटे में 2 बार, लेकिन 12 घंटों में 22 बार। (3 और 9 बजे एक-एक बार कम हो जाता है)।', 2, 0, 30, 'Reasoning', 'How many times do clock hands form 90° in 12 hours?', 'Right angles happen 22 times in 12 hours.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('zI2iC1oiA0utggAUx4jfF', 'Emxd0IiqwsczyIjPx1YxZ', 'एक बैग में 3 लाल और 5 काली गेंदें हैं। एक लाल गेंद निकालने की प्रायिकता क्या है?', '"[\"3/8\",\"5/8\",\"3/5\",\"1/2\"]"', '0.0', 'कुल = 8. लाल = 3. प्रायिकता = 3/8.', 2, 0, 31, 'Quantitative Aptitude', 'A bag has 3 Red, 5 Black balls. Probability of drawing a Red ball?', 'Total 8. Favorable 3.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('w9GFKqFgOE-vnhBpnJG_Y', 'Emxd0IiqwsczyIjPx1YxZ', 'यदि x + 1/x = 3, तो x³ + 1/x³ = ?', '"[\"18\",\"27\",\"24\",\"9\"]"', '0.0', 'सूत्र: a³ - 3a. 3³ - 3(3) = 27 - 9 = 18.', 2, 0, 32, 'Quantitative Aptitude', 'If x + 1/x = 3, then x³ + 1/x³ = ?', 'Cube formula: k^3 - 3k.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('mwYt_RVsViFGZtvaSDDki', 'Emxd0IiqwsczyIjPx1YxZ', 'डेटा व्याख्या: एक कंपनी का लाभ 2020 में 50 लाख, 2021 में 60 लाख और 2022 में 75 लाख था। औसत वृद्धि (प्रति वर्ष) कितनी है?', '"[\"12.5 Lakhs\",\"10 Lakhs\",\"15 Lakhs\",\"25 Lakhs\"]"', '0.0', 'कुल वृद्धि = 75 - 50 = 25 लाख। अवधि = 2 वर्ष। औसत = 25/2 = 12.5 लाख।', 2, 0, 33, 'Quantitative Aptitude', 'DI: Profit 2020: 50L, 2021: 60L, 2022: 75L. What is the average increase per year?', 'Total growth 25L over 2 intervals. Avg = 12.5.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('89Yssrp4zKGifw7uWxBfD', 'Emxd0IiqwsczyIjPx1YxZ', 'समरूपता (Analogy): पंचांग : तिथि :: घड़ी : ?', '"[\"Time\",\"Hour\",\"Wrist\",\"Needle\"]"', '0.0', 'पंचांग तिथि बताता है, घड़ी समय बताती है।', 2, 0, 34, 'Reasoning', 'Analogy: Calendar : Date :: Clock : ?', 'Calendar shows Date, Clock shows Time.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9Y5YvqOeTiOyrPRF7xL9C', 'Emxd0IiqwsczyIjPx1YxZ', '1 से 100 तक कितनी बार अंक ''7'' आता है?', '"[\"20\",\"19\",\"21\",\"10\"]"', '0.0', '7, 17...97 (10 बार) + 70, 71...79 (10 बार)। कुल = 20।', 2, 0, 35, 'Quantitative Aptitude', 'How many times does digit ''7'' appear from 1 to 100?', 'Standard digit counting in 1-100 is 20 times.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ny2glMftlJRCXlkXLTSdJ', 'Emxd0IiqwsczyIjPx1YxZ', 'यदि परसों शुक्रवार था, तो आगामी परसों के बाद तीसरा दिन क्या होगा?', '"[\"Sunday\",\"Monday\",\"Saturday\",\"Friday\"]"', '3.0', 'परसों (शुक्रवार) -> आज (रविवार)। आगामी परसों (मंगलवार)। उसके बाद तीसरा दिन = मंगल + 3 = शुक्रवार।', 2, 0, 36, 'Reasoning', 'If day before yesterday was Friday, what will be the third day after day after yesterday?', 'Today is Sun. Day after tomorrow is Tue. 3rd day after is Friday.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ei1_zbMoV11B28VIxbHQT', 'Emxd0IiqwsczyIjPx1YxZ', '300 मीटर लंबी ट्रेन 200 मीटर लंबे पुल को 25 सेकंड में पार करती है। ट्रेन की गति?', '"[\"72 km/hr\",\"60 km/hr\",\"20 km/hr\",\"54 km/hr\"]"', '0.0', 'कुल दूरी = 500m। गति = 500/25 = 20 m/s = 20 × 18/5 = 72 किमी/घंटा।', 2, 0, 37, 'Quantitative Aptitude', '300m train crosses 200m bridge in 25 sec. Speed?', '20 m/s converted to 72 km/hr.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('IcOxsd7pGVjoUST0Swk6o', 'Emxd0IiqwsczyIjPx1YxZ', 'कौन सी संख्या एक पूर्ण वर्ग नहीं हो सकती?', '"[\"1225\",\"2025\",\"4052\",\"1296\"]"', '2.0', 'पूर्ण वर्ग संख्या का अंतिम अंक 2, 3, 7, 8 नहीं हो सकता। 4052 में 2 है।', 2, 0, 38, 'Quantitative Aptitude', 'Which number cannot be a perfect square?', 'Perfect squares never end in 2.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Z5WBg4_tBqB_d0pJfvNzw', 'Emxd0IiqwsczyIjPx1YxZ', 'श्रृंखला: Z, S, W, O, T, K, Q, G, ?', '"[\"N, C\",\"N, D\",\"O, C\",\"M, C\"]"', '0.0', 'दो श्रृंखलाएं: 1. Z(-3)W(-3)T(-3)Q(-3)N. 2. S(-4)O(-4)K(-4)G(-4)C. उत्तर: N, C.', 2, 0, 39, 'Reasoning', 'Series: Z, S, W, O, T, K, Q, G, ?', 'Alternating series subtraction.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ax0hzsttIRj46BzsAu0ku', 'Emxd0IiqwsczyIjPx1YxZ', 'एक पहिए का व्यास 1.26 मीटर है। 500 चक्करों में यह कितनी दूरी तय करेगा?', '"[\"1980 m\",\"1900 m\",\"2000 m\",\"1500 m\"]"', '0.0', 'परिधि = πd = (22/7) * 1.26 = 22 * 0.18 = 3.96m. दूरी = 500 * 3.96 = 1980m.', 2, 0, 40, 'Quantitative Aptitude', 'Diameter of wheel 1.26 m. Distance in 500 revolutions?', 'Circumference * Revolutions.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('WEPb-g-YIyTlLSFMtv5LL', 'Emxd0IiqwsczyIjPx1YxZ', 'कथन: ''ईमानदारी सबसे अच्छी नीति है''। निष्कर्ष: (I) ईमानदार लोग हमेशा सफल होते हैं। (II) बेईमानी कभी-कभी उपयोगी होती है।', '"[\"Only I\",\"Only II\",\"Both\",\"None\"]"', '3.0', 'कथन केवल एक नैतिक मूल्य है। यह सफलता की गारंटी नहीं देता, न ही बेईमानी का समर्थन करता है।', 2, 0, 41, 'Reasoning', 'Statement: ''Honesty is the best policy''. Conclusions: (I) Honest people always succeed. (II) Dishonesty is sometimes useful.', 'Proverb doesn''t imply guaranteed success or utility of dishonesty.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cyqgRbeaO3KI4ZkRlHWto', 'Emxd0IiqwsczyIjPx1YxZ', 'यदि 3#4 = 25 और 5#6 = 61, तो 4#5 = ?', '"[\"41\",\"40\",\"29\",\"20\"]"', '0.0', 'पैटर्न: (A × B) + 4? नहीं. 5×3+4=19. 8×5+9=49. तर्क बदल रहा है। दूसरा तर्क: (A+B)×2 + कुछ? 8×2+3. 13×2+? नहीं। (5×4)-1=19? (8×6)+1=49. (6×5)-1 = 29? चलिए देखते हैं। पैटर्न: A*B + (B+1)? 15+4=19. 40+6=46 (Fail). पैटर्न: A*B + A - 1? 15+5-1=19. 40+8-1=47 (Fail). पैटर्न: 2A + 3B = 10+9=19. 2(8)+3(5)=16+15=31 (Fail). पैटर्न: 6*A - B? नहीं। चलो सरल करते हैं: A*B + 4 = 19? नहीं। (A+B)*2 + 3? 16+3=19. 26+? नहीं। सही पैटर्न: A×B + (A-1) = 15+4=19. 40+7=47 (Fail). प्रश्न त्रुटिपूर्ण या जटिल। चलो नया: यदि 3#4=25, 5#6=61 (3²+4²=25, 5²+6²=61). तो 4#5 = 16+25=41.', 2, 0, 42, 'Reasoning', 'If 3#4 = 25 and 5#6 = 61, then 4#5 = ?', 'Sum of squares logic: 16+25=41.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Ew5gliwuxel74b1O6LsxZ', 'Emxd0IiqwsczyIjPx1YxZ', 'संचार में ''शोर'' (Noise) का कौन सा प्रकार ''शारीरिक पीड़ा'' (Physical pain) है?', '"[\"Physical Noise\",\"Physiological Noise\",\"Psychological Noise\",\"Semantic Noise\"]"', '1.0', 'शरीर के अंदर की बाधाएं (दर्द, भूख, बहरापन) ''Physiological Noise'' हैं।', 2, 0, 43, 'Communication', 'Which type of ''Noise'' in communication is ''Physical pain''?', 'Internal bodily states are physiological.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Y5luh7jkJhvqWyVZkfTwg', 'Emxd0IiqwsczyIjPx1YxZ', 'जन संचार (Mass Communication) की मुख्य विशेषता क्या है?', '"[\"तत्काल प्रतिक्रिया / Immediate Feedback\",\"सीमित दर्शक / Limited Audience\",\"विशाल और विविध दर्शक / Large and Heterogeneous Audience\",\"निजी संदेश / Personal Message\"]"', '2.0', 'जन संचार बड़े और विविध समूहों को संबोधित करता है (जैसे टीवी, अखबार)।', 2, 0, 44, 'Communication', 'Main feature of Mass Communication?', 'Large, anonymous, heterogeneous audience.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('FBmtTgNqr4dAS1QnVzHCk', 'Emxd0IiqwsczyIjPx1YxZ', 'संचार माध्यम (Channels) को उनकी समृद्धि (Richness) से सुमेलित करें:', '"[\"(1)-(b), (2)-(c), (3)-(a), (4)-(d)\",\"(1)-(b), (2)-(c), (3)-(d), (4)-(a)\",\"(1)-(a), (2)-(b), (3)-(c), (4)-(d)\",\"(1)-(d), (2)-(c), (3)-(b), (4)-(a)\"]"', '0.0', 'Face-to-face is highest (b), but here options logic: FtF(High), Video(Mod-High), Email(Low-Mod), Report(Lowest). Let''s fit best: (1)-b (High, wait FtF is Highest), (2)-c (Video is High but less than FtF), (3)-a (Email Low), (4)-d (Report Lowest). Wait, option A has 1-b, 2-c... No. Let''s try: FtF=High(b), Video=Mod(c)?, Email=Low(a), Report=Lowest(d). A: 1-b, 2-c, 3-a, 4-d. This fits general hierarchy.', 2, 0, 45, 'Communication', 'Match Channels with Media Richness:', 'Hierarchy: Face-to-Face > Video > Email > Documents.', 60, 'matching', '[{"id":"(1)","label":"Face-to-Face","match":"Low Richness","matchId":"(a)"},{"id":"(2)","label":"Video Call","match":"High Richness","matchId":"(b)"},{"id":"(3)","label":"Email","match":"Moderate Richness","matchId":"(c)"},{"id":"(4)","label":"Formal Report","match":"Lowest Richness","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('vikg6W4YJ0mpleA8cp-rb', 'Emxd0IiqwsczyIjPx1YxZ', '''ग्रेपवाइन'' (Grapevine) के कितने प्रकार की चेन होती हैं?', '"[\"2\",\"3\",\"4\",\"5\"]"', '2.0', '4 प्रकार: सिंगल स्ट्रैंड, गपशप (Gossip), प्रायिकता (Probability), क्लस्टर (Cluster)।', 2, 0, 46, 'Communication', 'How many types of chains are there in Grapevine communication?', 'Single strand, Gossip, Probability, Cluster.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('CARc0QDD6Pk5Gtw_R-CYz', 'Emxd0IiqwsczyIjPx1YxZ', 'संचार में ''एन्ट्रापी'' (Entropy) का अर्थ क्या है?', '"[\"संदेश की स्पष्टता / Clarity\",\"अनियंत्रित और यादृच्छिक जानकारी / Unpredictable/Randomness\",\"प्रतिक्रिया / Feedback\",\"चुप रहना / Silence\"]"', '1.0', 'एन्ट्रापी का अर्थ है अव्यवस्था या अनिश्चितता।', 2, 0, 47, 'Communication', 'What does ''Entropy'' mean in communication?', 'Entropy refers to randomness or lack of order.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xKMbK-Y9cqrnP3tTh1X4t', 'Emxd0IiqwsczyIjPx1YxZ', '6 सेमी, 8 सेमी और 10 सेमी भुजाओं वाले त्रिभुज की परिवृत्त त्रिज्या (Circumradius) क्या है?', '"[\"5 cm\",\"4 cm\",\"3 cm\",\"6 cm\"]"', '0.0', 'यह समकोण त्रिभुज है (6,8,10)। परिवृत्त त्रिज्या = कर्ण/2 = 10/2 = 5।', 2, 0, 48, 'Quantitative Aptitude', 'Circumradius of triangle with sides 6, 8, 10 cm?', 'Right triangle circumradius is half of hypotenuse.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Yod0C8vmV1mPe6QUWtdTV', 'Emxd0IiqwsczyIjPx1YxZ', 'log 2 = 0.3010, तो log 5 = ?', '"[\"0.6990\",\"0.5000\",\"0.6020\",\"0.3010\"]"', '0.0', 'log 5 = log(10/2) = log 10 - log 2 = 1 - 0.3010 = 0.6990.', 2, 0, 49, 'Quantitative Aptitude', 'log 2 = 0.3010, then log 5 = ?', 'log 10 - log 2.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('LYLxl-Ai1-3tO2yBFV2YZ', 'Emxd0IiqwsczyIjPx1YxZ', 'यदि परसों के 2 दिन बाद रविवार है, तो आज कौन सा दिन है?', '"[\"Wednesday\",\"Thursday\",\"Tuesday\",\"Friday\"]"', '0.0', 'आज (x) -> कल (x+1) -> परसों (x+2) -> 2 दिन बाद (x+4) = रविवार। x = रविवार - 4 = बुधवार।', 2, 0, 50, 'Reasoning', 'If 2 days after day after tomorrow is Sunday, what day is today?', 'Sunday minus 4 days is Wednesday.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('IY74czLNVxQJI7WIXLmwW', 'Emxd0IiqwsczyIjPx1YxZ', 'अशाब्दिक संचार का कितना प्रतिशत (मेहराबियन नियम के अनुसार) चेहरे के हाव-भाव और टोन से आता है?', '"[\"55%\",\"38%\",\"93%\",\"7%\"]"', '2.0', '55% बॉडी लैंग्वेज + 38% टोन = 93% अशाब्दिक। केवल 7% शब्द।', 2, 0, 51, 'Communication', 'According to Mehrabian rule, what % of communication is non-verbal (Body+Tone)?', '93% is non-verbal (55 body + 38 tone).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('iTalI2oQ2oc2WZbvCOKsJ', 'Emxd0IiqwsczyIjPx1YxZ', 'संचार में ''गेटकीपिंग'' (Gatekeeping) कौन करता है?', '"[\"संपादक / Editor\",\"पाठक / Reader\",\"विज्ञापनदाता / Advertiser\",\"सरकार / Government\"]"', '0.0', 'गेटकीपर (जैसे संपादक) तय करता है कि कौन सी जानकारी आगे जाएगी और कौन सी रोकी जाएगी।', 2, 0, 52, 'Communication', 'Who performs ''Gatekeeping'' in communication?', 'Editors control flow of information.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d4Gak2nXs5SU-VwXPKSwm', 'Emxd0IiqwsczyIjPx1YxZ', 'A की आय B से 10% कम है, और B की C से 10% कम है। यदि C की आय 1000 है, तो A की आय?', '"[\"810\",\"800\",\"900\",\"850\"]"', '0.0', 'C=1000. B=900. A=900 - 90 = 810.', 2, 0, 53, 'Quantitative Aptitude', 'A''s income 10% less than B, B''s 10% less than C. If C=1000, A=?', 'Sequential percent decrease.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('rTDb8I-OXcCz54AKpkijN', 'Emxd0IiqwsczyIjPx1YxZ', '√0.000441 = ?', '"[\"0.021\",\"0.21\",\"0.0021\",\"0.00021\"]"', '0.0', '√441 = 21. दशमलव 6 अंक है, वर्गमूल में 3 अंक होंगे। 0.021।', 2, 0, 54, 'Quantitative Aptitude', '√0.000441 = ?', 'Square root decimal rule.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('saXZMy8I0ZrWoO4idCys2', 'Emxd0IiqwsczyIjPx1YxZ', 'एक समबाहु भुज (Polygon) का आंतरिक कोण 144° है। भुजाओं की संख्या?', '"[\"10\",\"12\",\"8\",\"9\"]"', '0.0', 'बाह्य कोण = 180 - 144 = 36°. n = 360/36 = 10.', 2, 0, 55, 'Quantitative Aptitude', 'Interior angle of regular polygon is 144°. Number of sides?', 'Exterior angle formula: 360/n.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('x2l05yOUMusab98EyTrCw', 'Emxd0IiqwsczyIjPx1YxZ', '**निर्देश: गद्यांश पढ़ें:**
डिजिटल साक्षरता आज की दुनिया में अनिवार्य है। यह लोगों को सूचना तक पहुंचने और संवाद करने में सक्षम बनाती है। हालांकि, साइबर अपराध एक बड़ा खतरा है। हमें मजबूत पासवर्ड और सावधानी से इंटरनेट का उपयोग करना चाहिए।

----------------------------
**प्रश्न:** डिजिटल साक्षरता क्यों अनिवार्य है?', '"[\"पैसे कमाने के लिए\",\"सूचना और संवाद के लिए\",\"गेम खेलने के लिए\",\"समय बिताने के लिए\"]"', '1.0', NULL, 2, 0, 56, 'Reading Comprehension', '**Direction: Read passage:**
Digital literacy is essential in today''s world. It empowers people to access information and communicate. However, cybercrime is a major threat. We must use strong passwords and use the internet carefully.

----------------------------
**Question:** Why is digital literacy essential?', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
