INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('aR81Eeu-Sb_NkpNcWEtDv', 'Emxd0IiqwsczyIjPx1YxZ', 'सोरठा छंद किस छंद का उल्टा होता है?', '"[\"चौपाई\",\"दोहा\",\"बरवै\",\"कुंडलिया\"]"', '1.0', 'सोरठा, दोहा का उल्टा है (11-13 मात्राएं)।', 2, 0, 99, 'Hindi Grammar', 'N/A', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('STtGfnGFbuIvXMu8Q5S0A', 'Emxd0IiqwsczyIjPx1YxZ', 'भाषा की सबसे छोटी इकाई क्या है?', '"[\"शब्द\",\"वाक्य\",\"वर्ण/ध्वनि\",\"पद\"]"', '2.0', 'वर्ण (Letter/Sound)।', 2, 0, 100, 'Hindi Grammar', 'N/A', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f1b35a92-d120-4b7f-921e-a42ca3d4ea6e', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'नर्मदा नदी के संबंध में ''नामदोस'' (Namados) नाम का प्रयोग किस भूगोलवेत्ता ने किया था?', '[{"id":"A","text":"टॉलेमी (Ptolemy)","text_en":"टॉलेमी (Ptolemy)"},{"id":"B","text":"मेगस्थनीज","text_en":"मेगस्थनीज"},{"id":"C","text":"ह्वेनसांग","text_en":"ह्वेनसांग"},{"id":"D","text":"अल-बरूनी","text_en":"अल-बरूनी"}]', '0', '✅ **Correct Logic**: यूनानी भूगोलवेत्ता टॉलेमी ने नर्मदा को ''नामदोस'' कहा था।
💡 **Exam Fact**: नर्मदा को ''रेवा'' और ''मेकलसुता'' के नाम से भी जाना जाता है।
🧠 **Memory Tip**: P-N (Ptolemy-Namados).
🚫 **Scam Alert**: ह्वेनसांग ने नर्मदा का नहीं बल्कि ''मो-हो-ला-चा'' (मालवा) का वर्णन किया था।', 2, 0, 1, NULL, 'Which geographer used the name ''Namados'' for the Narmada River?', '✅ **Correct Logic**: The Greek geographer Ptolemy referred to the Narmada river as ''Namados''.
💡 **Exam Fact**: Narmada is also known as ''Rewa'' and ''Maikalsuta''.
🧠 **Memory Tip**: P-N (Ptolemy-Namados).
🚫 **Scam Alert**: Xuanzang described the region of Malwa, not specifically the river name as Namados.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9f1ec05b-db54-406c-9dbe-d6cb07ded140', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'चंबल नदी के उद्गम स्थल ''जानापाव'' की ऊँचाई कितनी है और यह किस पहाड़ी श्रृंखला का हिस्सा है?', '[{"id":"A","text":"854 मीटर; विंध्याचल","text_en":"854 मीटर; विंध्याचल"},{"id":"B","text":"881 मीटर; सतपुड़ा","text_en":"881 मीटर; सतपुड़ा"},{"id":"C","text":"752 मीटर; अरावली","text_en":"752 मीटर; अरावली"},{"id":"D","text":"450 मीटर; कैमूर","text_en":"450 मीटर; कैमूर"}]', '0', '✅ **Correct Logic**: चंबल का उद्गम महू (इंदौर) के पास जानापाव पहाड़ी से होता है जिसकी ऊँचाई 854 मीटर है। यह विंध्याचल श्रेणी का हिस्सा है।
💡 **Exam Fact**: चंबल मध्य प्रदेश की दूसरी सबसे लंबी नदी (965 किमी) है।
🧠 **Memory Tip**: Janapav - 854 (J is the 10th letter, subtract slightly).
🚫 **Scam Alert**: 881 मीटर सिगार (Sigar) चोटी की ऊँचाई है, जानापाव की नहीं।', 2, 0, 2, NULL, 'What is the height of ''Janapav'', the origin of the Chambal River, and it is part of which hill range?', '✅ **Correct Logic**: Chambal originates from Janapav hills near Mhow, which stands at 854 meters. It is part of the Vindhyachal range.
💡 **Exam Fact**: Chambal is the second longest river of MP (965 km).
🧠 **Memory Tip**: Janapav - 854.
🚫 **Scam Alert**: 881 meters is the height of Sigar peak, not Janapav.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a8028fb2-5eae-44b1-88c7-4cda83d6fdc6', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'निम्नलिखित में से कौन सी नदी डेल्टा (Delta) नहीं बनाती, बल्कि एस्टुअरी (Estuary) का निर्माण करती है?', '[{"id":"A","text":"बेतवा","text_en":"बेतवा"},{"id":"B","text":"चंबल","text_en":"चंबल"},{"id":"C","text":"ताप्ती","text_en":"ताप्ती"},{"id":"D","text":"केन","text_en":"केन"}]', '2', '✅ **Correct Logic**: नर्मदा और ताप्ती दोनों पूर्व से पश्चिम की ओर बहती हैं और भ्रंश घाटी (Rift Valley) से होकर गुजरती हैं, इसलिए ये डेल्टा की जगह एस्टुअरी बनाती हैं।
💡 **Exam Fact**: ताप्ती का उद्गम बैतूल के मुल्ताई से होता है।
🧠 **Memory Tip**: N-T (Narmada-Tapti) No Delta.
🚫 **Scam Alert**: बेतवा और केन यमुना की सहायक नदियाँ हैं, जो अंततः गंगा तंत्र का हिस्सा बनती हैं।', 2, 0, 3, NULL, 'Which of the following rivers does not form a Delta but forms an Estuary?', '✅ **Correct Logic**: Both Narmada and Tapti flow from East to West through rift valleys and form estuaries instead of deltas.
💡 **Exam Fact**: Tapti originates from Multai in Betul.
🧠 **Memory Tip**: N-T (Narmada-Tapti) - No Delta.
🚫 **Scam Alert**: Betwa and Ken are tributaries of Yamuna, eventually joining the Ganga system.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('abf09b39-60ef-4355-b09d-52f69e1f9541', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'बेतवा नदी को ''मध्य प्रदेश की गंगा'' किस आधार पर कहा जाता है?', '[{"id":"A","text":"पवित्रता के आधार पर","text_en":"पवित्रता के आधार पर"},{"id":"B","text":"प्रदूषण के आधार पर","text_en":"प्रदूषण के आधार पर"},{"id":"C","text":"लंबाई के आधार पर","text_en":"लंबाई के आधार पर"},{"id":"D","text":"जल ग्रहण क्षेत्र के आधार पर","text_en":"जल ग्रहण क्षेत्र के आधार पर"}]', '1', '✅ **Correct Logic**: बेतवा को ''प्रदूषण'' के स्तर के कारण मध्य प्रदेश की गंगा कहा जाता है।
💡 **Exam Fact**: ''पवित्रता'' के आधार पर नर्मदा को मध्य प्रदेश की गंगा कहा जाता है।
🧠 **Memory Tip**: B-P (Betwa-Pollution).
🚫 **Scam Alert**: भ्रमित न हों, यदि विकल्प में पवित्रता और प्रदूषण दोनों हों, तो बेतवा के लिए प्रदूषण ही सही तर्क है।', 2, 0, 4, NULL, 'On what basis is the Betwa River called the ''Ganga of Madhya Pradesh''?', '✅ **Correct Logic**: Betwa is called the Ganga of MP based on its ''Pollution'' levels.
💡 **Exam Fact**: Narmada is called the Ganga of MP based on ''Purity/Holiness''.
🧠 **Memory Tip**: B-P (Betwa-Pollution).
🚫 **Scam Alert**: Don''t be confused; for Betwa, pollution is the standard reasoning in exams.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2439958c-c808-4702-8054-b6c39a708bdb', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'नदियाँ और उनके प्राचीन नामों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: बेतवा-वेत्रवती, केन-शुक्तिमती, चंबल-चर्मावती और सोन को स्वर्ण या हिरण्यबाहु कहा जाता है।
💡 **Exam Fact**: सोन नदी उत्तर की ओर बहकर पटना के पास गंगा में मिल जाती है।
🧠 **Memory Tip**: Ken-Shukti (K-S).
🚫 **Scam Alert**: तमस (Tamas) टोंस नदी का नाम है, सोन का नहीं।', 2, 0, 5, NULL, 'Match the rivers and their ancient names:', '✅ **Correct Logic**: Betwa-Vetravati, Ken-Shuktimati, Chambal-Charmavati, and Son-Hiranyabahu.
💡 **Exam Fact**: Son river flows North and joins the Ganga near Patna.
🧠 **Memory Tip**: Ken-Shukti (K-S).
🚫 **Scam Alert**: Tamas is the ancient name of the Tons river, not the Son.', 60, 'matching', '[{"id":"(1)","label":"बेतवा","match":"वेत्रवती","matchId":"(a)"},{"id":"(2)","label":"केन","match":"शुक्तिमती","matchId":"(b)"},{"id":"(3)","label":"चंबल","match":"चर्मावती","matchId":"(c)"},{"id":"(4)","label":"सोन","match":"हिरण्यबाहु","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('12c7908b-1f3e-42ac-b358-b0756aead2f7', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'कपिलधारा और दुग्धधारा जलप्रपात (Waterfalls) किस नदी पर स्थित हैं?', '[{"id":"A","text":"ताप्ती","text_en":"ताप्ती"},{"id":"B","text":"नर्मदा","text_en":"नर्मदा"},{"id":"C","text":"सोन","text_en":"सोन"},{"id":"D","text":"बेतवा","text_en":"बेतवा"}]', '1', '✅ **Correct Logic**: ये दोनों प्रपात नर्मदा नदी के उद्गम स्थल अनूपपुर (अमरकंटक) के पास स्थित हैं।
💡 **Exam Fact**: धुआँधार जलप्रपात जबलपुर (भेड़ाघाट) में स्थित है।
🧠 **Memory Tip**: KD (Kapil-Dugdhdhara) at the start of Narmada.
🚫 **Scam Alert**: चचाई जलप्रपात बीहड़ नदी (रीवा) पर है, नर्मदा पर नहीं।', 2, 0, 6, NULL, 'On which river are the Kapildhara and Dugdhdhara waterfalls located?', '✅ **Correct Logic**: Both falls are located near the source of the Narmada river in Anuppur (Amarkantak).
💡 **Exam Fact**: Dhuandhar falls is located in Jabalpur.
🧠 **Memory Tip**: KD (Kapil-Dugdhdhara) are initial falls of Narmada.
🚫 **Scam Alert**: Chachai falls is on Beehar river (Rewa), not Narmada.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9cf76644-b6d5-4d8b-80c8-7e55963cb8b3', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'मध्य प्रदेश की कौन सी नदी कर्क रेखा (Tropic of Cancer) को दो बार काटती है?', '[{"id":"A","text":"माही (Mahi)","text_en":"माही (Mahi)"},{"id":"B","text":"नर्मदा","text_en":"नर्मदा"},{"id":"C","text":"चंबल","text_en":"चंबल"},{"id":"D","text":"सिंध","text_en":"सिंध"}]', '0', '✅ **Correct Logic**: माही नदी धार जिले से निकलती है और कर्क रेखा को दो बार काटती है।
💡 **Exam Fact**: यह भारत की एकमात्र नदी है जो ऐसा करती है।
🧠 **Memory Tip**: Mahi - MS Dhoni (Double Sixer/Double Cross).
🚫 **Scam Alert**: नर्मदा और सोन कर्क रेखा के लगभग समानांतर बहती हैं, काटती नहीं।', 2, 0, 7, NULL, 'Which river of MP crosses the Tropic of Cancer twice?', '✅ **Correct Logic**: Mahi river originates from Dhar and crosses the Tropic of Cancer twice.
💡 **Exam Fact**: It is the only river in India to do so.
🧠 **Memory Tip**: Mahi - Think of a player crossing the line twice.
🚫 **Scam Alert**: Narmada and Son flow almost parallel to the Tropic of Cancer, they don''t cross it twice.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0b150ecd-af5e-494f-952b-8c2cb391e8c1', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'शिप्रा नदी किस स्थान पर चंबल नदी में विलीन हो जाती है?', '[{"id":"A","text":"मन्दसौर","text_en":"मन्दसौर"},{"id":"B","text":"कोटा","text_en":"कोटा"},{"id":"C","text":"इटावा","text_en":"इटावा"},{"id":"D","text":"उज्जैन","text_en":"उज्जैन"}]', '0', '✅ **Correct Logic**: शिप्रा नदी मन्दसौर जिले की सीमा पर चंबल में मिल जाती है।
💡 **Exam Fact**: शिप्रा को ''मालवा की गंगा'' कहा जाता है।
🧠 **Memory Tip**: S-M (Shipra merges in Mandsaur).
🚫 **Scam Alert**: इटावा (UP) में चंबल यमुना से मिलती है, शिप्रा चंबल से मन्दसौर में।', 2, 0, 8, NULL, 'At which place does the Shipra River merge into the Chambal River?', '✅ **Correct Logic**: The Shipra river merges into the Chambal at the border of Mandsaur district.
💡 **Exam Fact**: Shipra is known as the ''Ganga of Malwa''.
🧠 **Memory Tip**: S-M (Shipra merges in Mandsaur).
🚫 **Scam Alert**: Chambal joins Yamuna in Etawah, but Shipra joins Chambal in Mandsaur.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4ac20857-54b9-4a5f-af61-6892a448d27f', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'कुंवारी (Kwari) नदी का उद्गम स्थल कहाँ है और यह किसकी सहायक नदी है?', '[{"id":"A","text":"शिवपुरी पठार; सिंध की सहायक","text_en":"शिवपुरी पठार; सिंध की सहायक"},{"id":"B","text":"जानापाव पहाड़ी; चंबल की सहायक","text_en":"जानापाव पहाड़ी; चंबल की सहायक"},{"id":"C","text":"अमरकंटक; सोन की सहायक","text_en":"अमरकंटक; सोन की सहायक"},{"id":"D","text":"मुलताई; ताप्ती की सहायक","text_en":"मुलताई; ताप्ती की सहायक"}]', '0', '✅ **Correct Logic**: कुंवारी नदी शिवपुरी पठार से निकलती है और सिंध नदी की सहायक है।
💡 **Exam Fact**: यह भिंड जिले में सिंध नदी में मिल जाती है।
🧠 **Memory Tip**: K-S (Kwari-Sindh).
🚫 **Scam Alert**: यह चंबल के समानांतर बहती है लेकिन चंबल में नहीं, बल्कि सिंध में मिलती है।', 2, 0, 9, NULL, 'What is the origin of the Kwari River and which river is it a tributary of?', '✅ **Correct Logic**: Kwari originates from the Shivpuri plateau and is a tributary of the Sindh river.
💡 **Exam Fact**: It joins the Sindh river in Bhind district.
🧠 **Memory Tip**: K-S (Kwari-Sindh).
🚫 **Scam Alert**: It flows parallel to Chambal but joins Sindh, not Chambal.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6727e58f-e7e3-4590-be71-a98edef81817', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'मध्य प्रदेश की नदियों के संबंध में निम्नलिखित कथनों पर विचार करें:
1. वर्धा और वैनगंगा के संगम को ''प्राणहिता'' कहा जाता है।
2. वेनगंगा दक्षिण की ओर बहने वाली प्रमुख नदी है।
3. पेंच नदी वैनगंगा की सहायक है।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '2', '✅ **Correct Logic**: तीनों कथन सत्य हैं। यह तंत्र अंततः गोदावरी नदी प्रणाली का हिस्सा बनता है।
💡 **Exam Fact**: वैनगंगा का उद्गम सिवनी जिले के परसवाड़ा पठार से होता है।
🧠 **Memory Tip**: P-W-V (Pranhita-Wardha-Vainganga).
🚫 **Scam Alert**: अधिकतर MP की नदियाँ उत्तर की ओर बहती हैं, लेकिन वैनगंगा अपवाद स्वरूप दक्षिण की ओर बहती है।', 2, 0, 10, NULL, 'Consider the following statements regarding the rivers of MP:
1. The confluence of Wardha and Wainganga is called ''Pranhita''.
2. Wainganga is a major South-flowing river.
3. Pench river is a tributary of Wainganga.

Choose the correct statement:', '✅ **Correct Logic**: All three statements are true. This system eventually joins the Godavari river basin.
💡 **Exam Fact**: Wainganga originates from the Paraswara plateau in Seoni district.
🧠 **Memory Tip**: P-W-V (Pranhita-Wardha-Vainganga).
🚫 **Scam Alert**: Most MP rivers flow North; Wainganga is a notable exception flowing South.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('477edf0e-0403-4a2d-ac38-21d541c4fed3', '3dd60502-75dd-4af9-b6cd-c41dec63ebf0', '''मुद्राराक्षस'' (Mudrarakshasa) नाटक का विषय क्या है और इसके लेखक कौन हैं?', '[{"id":"A","text":"कालिदास - प्रेम कहानी (Kalidasa - Love story)","text_en":"कालिदास - प्रेम कहानी (Kalidasa - Love story)"},{"id":"B","text":"विशाखदत्त - चंद्रगुप्त मौर्य द्वारा नन्द वंश का विनाश और चाणक्य की कूटनीति (Vishakhadatta - Destruction of Nanda dynasty by Chandragupta and Chanakya''s diplomacy)","text_en":"विशाखदत्त - चंद्रगुप्त मौर्य द्वारा नन्द वंश का विनाश और चाणक्य की कूटनीति (Vishakhadatta - Destruction of Nanda dynasty by Chandragupta and Chanakya''s diplomacy)"},{"id":"C","text":"बाणभट्ट - हर्ष का जीवन (Banabhatta - Life of Harsha)","text_en":"बाणभट्ट - हर्ष का जीवन (Banabhatta - Life of Harsha)"},{"id":"D","text":"शूद्रक - सामाजिक नाटक (Sudraka - Social play)","text_en":"शूद्रक - सामाजिक नाटक (Sudraka - Social play)"}]', '1', '**✅ Correct Logic:** विशाखदत्त कृत ''मुद्राराक्षस'' एकमात्र ऐसा प्राचीन नाटक है जिसमें कोई नायिका (Heroine) नहीं है। यह पूरी तरह से चाणक्य की राजनीतिक चालों और जासूसी पर आधारित है।

**💡 Exam Fact:** ''मुद्रा'' का अर्थ है ''अंगूठी'' (Signet ring) जिसका प्रयोग चाणक्य ने राक्षस (नन्द का मंत्री) को फंसाने के लिए किया।

**🧠 Memory Tip:** Rakshasa = Minister''s name. Mudra = Ring. Spy thriller by **V**ishakhadatta.

**🚫 Scam Alert:** यह ऐतिहासिक नाटक है, पौराणिक नहीं।', 2, 0, 1, NULL, 'What is the subject of the play ''Mudrarakshasa'' and who is its author?', '**✅ Correct Logic:** ''Mudrarakshasa'' by Vishakhadatta is the only ancient play without a Heroine. It is entirely based on Chanakya''s political intrigues and espionage.

**💡 Exam Fact:** ''Mudra'' means ''Signet Ring'' used by Chanakya to trap Rakshasa (Nanda''s minister).

**🧠 Memory Tip:** Rakshasa = Minister''s name. Mudra = Ring. Spy thriller by **V**ishakhadatta.

**🚫 Scam Alert:** It''s a historical play, not mythological.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d035449b-0888-47f7-87d0-6061fbbaf6aa', '3dd60502-75dd-4af9-b6cd-c41dec63ebf0', 'दक्षिण भारत का वह महाकाव्य जिसे ''तमिल साहित्य का इलियाड'' (Iliad of Tamil Literature) कहा जाता है?', '[{"id":"A","text":"शिल्पदिकारम (Silappadikaram)","text_en":"शिल्पदिकारम (Silappadikaram)"},{"id":"B","text":"मणिमेखलै (Manimekalai)","text_en":"मणिमेखलै (Manimekalai)"},{"id":"C","text":"तिरुक्कुरल (Tirukkural)","text_en":"तिरुक्कुरल (Tirukkural)"},{"id":"D","text":"तोलकाप्पियम (Tolkappiyam)","text_en":"तोलकाप्पियम (Tolkappiyam)"}]', '0', '**✅ Correct Logic:** ''शिल्पदिकारम'' (नूपुर की कहानी) इलंगो अडिगल द्वारा रचित है। इसमें कोवलन और कन्नगी की दुखद कथा है। कन्नगी का अपने पति की मृत्यु पर क्रोध और मदुरै का दहन इसका क्लाइमेक्स है।

**💡 Exam Fact:** ''मणिमेखलै'' इसका सीक्वल (Sequel) है।

**🧠 Memory Tip:** Silappadikaram = Story of Anklet (Silambu). Tragic like Iliad.

**🚫 Scam Alert:** तिरुक्कुरल को ''तमिल वेद'' कहा जाता है, लेकिन इलियाड (महाकाव्य) शिल्पदिकारम है।', 2, 0, 2, NULL, 'Which South Indian epic is called the ''Iliad of Tamil Literature''?', '**✅ Correct Logic:** ''Silappadikaram'' (Story of Anklet) by Ilango Adigal. Story of Kovalan and Kannagi. Kannagi''s rage burning Madurai is the climax.

**💡 Exam Fact:** ''Manimekalai'' is its sequel.

**🧠 Memory Tip:** Silappadikaram = Story of Anklet (Silambu). Tragic like Iliad.

**🚫 Scam Alert:** Tirukkural is ''Tamil Veda'', but Iliad (Epic) is Silappadikaram.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4c1c6c38-47b3-4d72-a70a-588e20beb79b', '3dd60502-75dd-4af9-b6cd-c41dec63ebf0', '''पंचतंत्र'' (Panchatantra) का मूल लेखक किसे माना जाता है?', '[{"id":"A","text":"नारायण पंडित (Narayana Pandit)","text_en":"नारायण पंडित (Narayana Pandit)"},{"id":"B","text":"विष्णु शर्मा (Vishnu Sharma)","text_en":"विष्णु शर्मा (Vishnu Sharma)"},{"id":"C","text":"गुण आढ्य (Gunadhya)","text_en":"गुण आढ्य (Gunadhya)"},{"id":"D","text":"सोमदेव (Somadeva)","text_en":"सोमदेव (Somadeva)"}]', '1', '**✅ Correct Logic:** विष्णु शर्मा ने मूर्ख राजकुमारों को राजनीति और व्यवहारिक ज्ञान सिखाने के लिए ''पंचतंत्र'' (पशु-पक्षियों की कहानियां) लिखी। यह दुनिया में सर्वाधिक अनुवादित भारतीय पुस्तक है।

**💡 Exam Fact:** इसका अरबी अनुवाद ''कलीला-वा-दिमना'' नाम से प्रसिद्ध है।

**🧠 Memory Tip:** **V**ishnu **S**harma = **V**ery **S**mart stories.

**🚫 Scam Alert:** ''हितोपदेश'' नारायण पंडित ने लिखी थी, जो पंचतंत्र पर आधारित है। मूल लेखक विष्णु शर्मा हैं।', 2, 0, 3, NULL, 'Who is considered the original author of ''Panchatantra''?', '**✅ Correct Logic:** Vishnu Sharma wrote ''Panchatantra'' (Animal fables) to teach politics and practical wisdom to foolish princes. Most translated Indian book.

**💡 Exam Fact:** Arabic translation is famous as ''Kalila-wa-Dimna''.

**🧠 Memory Tip:** **V**ishnu **S**harma = **V**ery **S**mart stories.

**🚫 Scam Alert:** ''Hitopadesha'' was by Narayana Pandit (based on Panchatantra). Original is Vishnu Sharma.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f680fc8b-dca8-4520-8dbc-841beaab4334', '3dd60502-75dd-4af9-b6cd-c41dec63ebf0', 'प्राचीन पुस्तकों को उनके लेखकों से सुमेलित करें (Match the ancient books with their authors):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(c), (3)-(d), (4)-(a)","text_en":"(1)-(b), (2)-(c), (3)-(d), (4)-(a)"},{"id":"D","text":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)","text_en":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)"}]', '0', '**✅ Correct Logic:**
* **मृच्छकटिकम् (मिट्टी की गाड़ी):** शूद्रक (इसमें चोर, गणिका और ब्राह्मण की कहानी है - यथार्थवादी)।
* **स्वप्नवासवदत्ता:** भास (पहला पूर्ण नाटककार)।
* **किरातार्जुनीयम्:** भारवि (शिव और अर्जुन का युद्ध)।
* **दशकुमारचरित:** दण्डी (दस राजकुमारों की कहानी)।

**💡 Exam Fact:** मृच्छकटिकम् गुप्त काल का ''सामाजिक रूपक'' है।

**🧠 Memory Tip:** Clay Cart (**M**itti) = **S**udraka (Sudra/Soil). **Bha**ravi = **Bha**ri (Heavy/Deep meaning).

**🚫 Scam Alert:** भास और भारवि के नामों में कन्फ्यूजन न हो।', 2, 0, 5, NULL, 'Match the ancient books with their authors:', '**✅ Correct Logic:**
* **Mrichchhakatika (Clay Cart):** Sudraka (Story of thief, courtesan, brahmin - Realistic).
* **Svapnavasavadatta:** Bhasa (First complete playwright).
* **Kiratarjuniyam:** Bharavi (Fight b/w Shiva and Arjuna).
* **Dashakumaracharita:** Dandin (10 princes).

**💡 Exam Fact:** Mrichchhakatika is a ''Social Drama'' of Gupta period.

**🧠 Memory Tip:** Clay Cart (**M**itti) = **S**udraka (Sudra/Soil). **Bha**ravi = **Bha**ri (Heavy/Deep meaning).

**🚫 Scam Alert:** Don''t confuse Bhasa and Bharavi.', 60, 'matching', '[{"id":"(1)","label":"मृच्छकटिकम् (Mrichchhakatika)","match":"शूद्रक (Sudraka)","matchId":"(b)"},{"id":"(2)","label":"स्वप्नवासवदत्ता (Svapnavasavadatta)","match":"भास (Bhasa)","matchId":"(a)"},{"id":"(3)","label":"किरातार्जुनीयम् (Kiratarjuniyam)","match":"भारवि (Bharavi)","matchId":"(d)"},{"id":"(4)","label":"दशकुमारचरित (Dashakumaracharita)","match":"दण्डी (Dandin)","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3a90dbeb-1dcf-4336-a7cb-f5af598f5638', '3dd60502-75dd-4af9-b6cd-c41dec63ebf0', '''राजतरंगिणी'' (Rajatarangini) कल्हण द्वारा रचित एक महत्वपूर्ण ग्रंथ है। इसका विषय क्या है?', '[{"id":"A","text":"काश्मीर का इतिहास (History of Kashmir)","text_en":"काश्मीर का इतिहास (History of Kashmir)"},{"id":"B","text":"संगीत के सिद्धांत (Principles of Music)","text_en":"संगीत के सिद्धांत (Principles of Music)"},{"id":"C","text":"गुप्त वंश की वंशावली (Genealogy of Gupta Dynasty)","text_en":"गुप्त वंश की वंशावली (Genealogy of Gupta Dynasty)"},{"id":"D","text":"आयुर्वेद (Ayurveda)","text_en":"आयुर्वेद (Ayurveda)"}]', '0', '**✅ Correct Logic:** 12वीं सदी में रचित ''राजतरंगिणी'' (राजाओं की नदी) भारत की ''प्रथम ऐतिहासिक पुस्तक'' मानी जाती है। इसमें निष्पक्ष रूप से कश्मीर के राजाओं का इतिहास लिखा गया है।

**💡 Exam Fact:** कल्हण ने लिखा है: "एक सच्चा इतिहासकार वही है जो राग-द्वेष से मुक्त होकर तथ्य लिखे।"

**🧠 Memory Tip:** Raj-tarangini = Waves of Kings = History of Kashmir.

**🚫 Scam Alert:** यह केवल एक काव्य नहीं, बल्कि ''इतिहास'' (History) है।', 2, 0, 4, NULL, '''Rajatarangini'' by Kalhana is an important text. What is its subject?', '**✅ Correct Logic:** Written in 12th century, ''Rajatarangini'' (River of Kings) is considered India''s ''First Historical Book''. It unbiasedly records history of Kashmir kings.

**💡 Exam Fact:** Kalhana wrote: "A true historian is one who writes facts without bias."

**🧠 Memory Tip:** Raj-tarangini = Waves of Kings = History of Kashmir.

**🚫 Scam Alert:** It is not just poetry, but proper ''History''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6b285cf2-5144-4ddb-9f07-f73edb0d2311', '3dd60502-75dd-4af9-b6cd-c41dec63ebf0', 'हर्षवर्धन द्वारा रचित नाटकों में से कौन सा शामिल नहीं है?', '[{"id":"A","text":"रत्नावली (Ratnavali)","text_en":"रत्नावली (Ratnavali)"},{"id":"B","text":"प्रियदर्शिका (Priyadarshika)","text_en":"प्रियदर्शिका (Priyadarshika)"},{"id":"C","text":"नागानंद (Nagananda)","text_en":"नागानंद (Nagananda)"},{"id":"D","text":"हर्षचरित (Harshacharita)","text_en":"हर्षचरित (Harshacharita)"}]', '3', '**✅ Correct Logic:** सम्राट हर्ष ने तीन नाटक लिखे: रत्नावली, प्रियदर्शिका और नागानंद। लेकिन ''हर्षचरित'' (हर्ष की जीवनी) उनके दरबारी कवि **बाणभट्ट** ने लिखी थी।

**💡 Exam Fact:** नागानंद में जिमूतवाहन की आत्म-बलिदान की बौद्ध कथा है।

**🧠 Memory Tip:** Harsha wrote plays (Drama). Bana wrote Bio (Charita).

**🚫 Scam Alert:** हर्षचरित नाम में हर्ष है, लेकिन लेखक बाणभट्ट है।', 2, 0, 6, NULL, 'Which of the following is NOT among the plays written by Harshavardhana?', '**✅ Correct Logic:** Emperor Harsha wrote 3 plays: Ratnavali, Priyadarshika, Nagananda. But ''Harshacharita'' (Biography of Harsha) was written by his court poet **Banabhatta**.

**💡 Exam Fact:** Nagananda has the Buddhist story of Jimutavahana''s self-sacrifice.

**🧠 Memory Tip:** Harsha wrote plays (Drama). Bana wrote Bio (Charita).

**🚫 Scam Alert:** Name is Harshacharita, but author is Banabhatta.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3c6b9e50-585c-4370-a30a-89c95613ff3a', '3dd60502-75dd-4af9-b6cd-c41dec63ebf0', 'किस पुस्तक को ''भारतीय शिष्टाचार का विश्वकोश'' (Encyclopedia of Indian Etiquette) कहा जा सकता है?', '[{"id":"A","text":"कामसूत्र (Kamasutra)","text_en":"कामसूत्र (Kamasutra)"},{"id":"B","text":"मनुस्मृति (Manusmriti)","text_en":"मनुस्मृति (Manusmriti)"},{"id":"C","text":"अर्थशास्त्र (Arthashastra)","text_en":"अर्थशास्त्र (Arthashastra)"},{"id":"D","text":"नाट्यशास्त्र (Natyashastra)","text_en":"नाट्यशास्त्र (Natyashastra)"}]', '0', '**✅ Correct Logic:** वात्स्यायन कृत ''कामसूत्र'' केवल रति-क्रीड़ा की पुस्तक नहीं है, बल्कि इसमें नागरिक जीवन, 64 कलाएं, मित्रता, और सामाजिक शिष्टाचार का विस्तृत वर्णन है। यह ''नागरिक'' (Urban gentleman) की जीवन शैली बताती है।

**💡 Exam Fact:** इसमें चित्रकला के 6 अंगों (षडंग) का उल्लेख है।

**🧠 Memory Tip:** Kamasutra = Art of Living, not just loving.

**🚫 Scam Alert:** मनुस्मृति कानून है, कामसूत्र सामाजिक शिष्टाचार/लाइफस्टाइल है।', 2, 0, 7, NULL, 'Which book can be called the ''Encyclopedia of Indian Etiquette''?', '**✅ Correct Logic:** Vatsyayana''s ''Kamasutra'' is not just about sex; it details urban life, 64 arts, friendship, and social etiquette. It describes the lifestyle of a ''Nagarika'' (Urban gentleman).

**💡 Exam Fact:** It mentions the 6 limbs (Shadanga) of painting.

**🧠 Memory Tip:** Kamasutra = Art of Living, not just loving.

**🚫 Scam Alert:** Manusmriti is Law; Kamasutra is Etiquette/Lifestyle.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9916262e-6a33-4e95-b12a-ac3398d232e2', '3dd60502-75dd-4af9-b6cd-c41dec63ebf0', 'अश्वघोष की रचना ''बुद्धचरित'' (Buddhacharita) किस भाषा में लिखी गई है?', '[{"id":"A","text":"पाली (Pali)","text_en":"पाली (Pali)"},{"id":"B","text":"संस्कृत (Sanskrit)","text_en":"संस्कृत (Sanskrit)"},{"id":"C","text":"प्राकृत (Prakrit)","text_en":"प्राकृत (Prakrit)"},{"id":"D","text":"अपभ्रंश (Apabhramsha)","text_en":"अपभ्रंश (Apabhramsha)"}]', '1', '**✅ Correct Logic:** अश्वघोष (कनिष्क के दरबारी) ने ''बुद्धचरित'' की रचना विशुद्ध ''संस्कृत'' (महाकाव्य शैली) में की। यह बौद्ध धर्म का रामायण मानी जाती है।

**💡 Exam Fact:** बौद्ध धर्म की महायान शाखा ने संस्कृत को अपनाया था, जबकि हीनयान ने पाली को।

**🧠 Memory Tip:** Ashvaghosha = Sanskrit Poet (First Sanskrit Dramatist).

**🚫 Scam Alert:** बौद्ध ग्रंथ आमतौर पर पाली में होते हैं, लेकिन अश्वघोष की रचनाएं संस्कृत में हैं।', 2, 0, 8, NULL, 'In which language is Ashvaghosha''s ''Buddhacharita'' written?', '**✅ Correct Logic:** Ashvaghosha (Courtier of Kanishka) wrote ''Buddhacharita'' in pure ''Sanskrit'' (Epic style). Considered Ramayana of Buddhism.

**💡 Exam Fact:** Mahayana Buddhism adopted Sanskrit, while Hinayana used Pali.

**🧠 Memory Tip:** Ashvaghosha = Sanskrit Poet (First Sanskrit Dramatist).

**🚫 Scam Alert:** Buddhist texts are usually Pali, but Ashvaghosha wrote in Sanskrit.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2274e88c-bc14-4ecc-ab36-6f371505842b', '3dd60502-75dd-4af9-b6cd-c41dec63ebf0', '''गीत गोविन्द'' (Gita Govinda) के रचयिता जयदेव किस राजा के दरबारी कवि थे?', '[{"id":"A","text":"लक्ष्मण सेन (Lakshmana Sena)","text_en":"लक्ष्मण सेन (Lakshmana Sena)"},{"id":"B","text":"धर्मपाल (Dharmapala)","text_en":"धर्मपाल (Dharmapala)"},{"id":"C","text":"हर्षवर्धन (Harshavardhana)","text_en":"हर्षवर्धन (Harshavardhana)"},{"id":"D","text":"पृथ्वीराज चौहान (Prithviraj Chauhan)","text_en":"पृथ्वीराज चौहान (Prithviraj Chauhan)"}]', '0', '**✅ Correct Logic:** जयदेव बंगाल के सेन वंश के अंतिम राजा ''लक्ष्मण सेन'' (12वीं सदी) के दरबार में थे। गीत गोविन्द में कृष्ण और राधा के प्रेम का अत्यंत मधुर वर्णन है।

**💡 Exam Fact:** यह भक्ति आंदोलन और ओडिसी नृत्य का आधार ग्रंथ बना।

**🧠 Memory Tip:** Love (Gita Govinda) needs **L**akshman (Guard).

**🚫 Scam Alert:** बंगाल के सेन वंश को याद रखें।', 2, 0, 9, NULL, 'Jayadeva, the author of ''Gita Govinda'', was the court poet of which King?', '**✅ Correct Logic:** Jayadeva was in the court of ''Lakshmana Sena'' (Last Sena King of Bengal, 12th Century). Gita Govinda describes the love of Krishna and Radha.

**💡 Exam Fact:** It became the basis of Bhakti movement and Odissi dance.

**🧠 Memory Tip:** Love (Gita Govinda) needs **L**akshman (Guard).

**🚫 Scam Alert:** Remember Sena dynasty of Bengal.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fc70ddeb-d858-43d5-9374-1c8037874e9d', '3dd60502-75dd-4af9-b6cd-c41dec63ebf0', 'पाणिनि की ''अष्टाध्यायी'' पर पतंजलि ने कौन सा प्रसिद्ध भाष्य (Commentary) लिखा?', '[{"id":"A","text":"महाभाष्य (Mahabhashya)","text_en":"महाभाष्य (Mahabhashya)"},{"id":"B","text":"वार्तिक (Vartika)","text_en":"वार्तिक (Vartika)"},{"id":"C","text":"निरुक्त (Nirukta)","text_en":"निरुक्त (Nirukta)"},{"id":"D","text":"का तंत्र (Katantra)","text_en":"का तंत्र (Katantra)"}]', '0', '**✅ Correct Logic:** पतंजलि (शुंग काल) ने पाणिनि के व्याकरण सूत्रों को समझाने के लिए ''महाभाष्य'' लिखा। यह व्याकरण का दार्शनिक ग्रंथ है।

**💡 Exam Fact:** कात्यायन ने ''वार्तिक'' लिखा था। पाणिनि, कात्यायन और पतंजलि को व्याकरण का ''मुनित्रय'' (Trio of Sages) कहा जाता है।

**🧠 Memory Tip:** Patanjali = **M**aha (Great) Bhashya.

**🚫 Scam Alert:** योगसूत्र भी पतंजलि का है, लेकिन व्याकरण पर ''महाभाष्य'' है।', 2, 0, 10, NULL, 'Which famous commentary did Patanjali write on Panini''s ''Ashtadhyayi''?', '**✅ Correct Logic:** Patanjali (Shunga period) wrote ''Mahabhashya'' to explain Panini''s grammar sutras. It is a philosophical text on Grammar.

**💡 Exam Fact:** Katyayana wrote ''Vartika''. Panini, Katyayana, and Patanjali are called ''Munitraya'' (Trio) of Grammar.

**🧠 Memory Tip:** Patanjali = **M**aha (Great) Bhashya.

**🚫 Scam Alert:** Yoga Sutras is also by Patanjali, but on Grammar it is ''Mahabhashya''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f68c2eef-774d-4b6d-8145-d872c5c3f6be', '958e238b-a3a3-4bec-9827-366186a6a6dd', 'मध्य प्रदेश के भौगोलिक विभाजन के अनुसार, किस पठार को ''गेहूँ की डलिया'' (Basket of Wheat) कहा जाता है?', '[{"id":"A","text":"मालवा का पठार","text_en":"मालवा का पठार"},{"id":"B","text":"मध्य भारत का पठार","text_en":"मध्य भारत का पठार"},{"id":"C","text":"बुंदेलखंड का पठार","text_en":"बुंदेलखंड का पठार"},{"id":"D","text":"रीवा-पन्ना का पठार","text_en":"रीवा-पन्ना का पठार"}]', '0', '✅ **Correct Logic**: मालवा का पठार काली मिट्टी की प्रचुरता के कारण गेहूँ उत्पादन के लिए आदर्श है, इसीलिए इसे ''गेहूँ की डलिया'' कहते हैं।
💡 **Exam Fact**: मालवा का पठार मध्य प्रदेश के कुल क्षेत्रफल का लगभग 28% हिस्सा कवर करता है।
🧠 **Memory Tip**: Malwa - Meal (Wheat for meals).
🚫 **Scam Alert**: मध्य भारत के पठार को ''सरसों की हाँडी'' कहा जाता है, गेहूँ की डलिया नहीं।', 2, 0, 1, NULL, 'According to the geographical division of MP, which plateau is called the ''Basket of Wheat''?', '✅ **Correct Logic**: Due to the abundance of black soil, the Malwa plateau is ideal for wheat production, hence called the ''Basket of Wheat''.
💡 **Exam Fact**: Malwa Plateau covers approximately 28% of the total area of MP.
🧠 **Memory Tip**: Malwa - Wheat for Meals.
🚫 **Scam Alert**: Central India Plateau is known as the ''Pot of Mustard'', not the Wheat Basket.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2ab0a7f6-f7d7-4f21-ab14-6f390134f28c', '958e238b-a3a3-4bec-9827-366186a6a6dd', 'सतपुड़ा पर्वत श्रृंखला की सबसे ऊँची चोटी ''धूपगढ़'' किस पहाड़ी पर स्थित है?', '[{"id":"A","text":"राजपीपला पहाड़ी","text_en":"राजपीपला पहाड़ी"},{"id":"B","text":"महादेव पहाड़ी","text_en":"महादेव पहाड़ी"},{"id":"C","text":"मैकल श्रेणी","text_en":"मैकल श्रेणी"},{"id":"D","text":"ग्वालियर पहाड़ी","text_en":"ग्वालियर पहाड़ी"}]', '1', '✅ **Correct Logic**: धूपगढ़ (1350 मीटर) सतपुड़ा श्रेणी के अंतर्गत ''महादेव पहाड़ी'' पर स्थित है।
💡 **Exam Fact**: यह न केवल सतपुड़ा की बल्कि पूरे मध्य प्रदेश की सबसे ऊँची चोटी है।
🧠 **Memory Tip**: Mahadev (Lord Shiva) stays at the highest point (Dhupgarh).
🚫 **Scam Alert**: मैकल श्रेणी में अमरकंटक स्थित है, धूपगढ़ महादेव पहाड़ी का हिस्सा है।', 2, 0, 2, NULL, 'On which hill is ''Dhupgarh'', the highest peak of the Satpura range, located?', '✅ **Correct Logic**: Dhupgarh (1350m) is located on the ''Mahadev Hills'' within the Satpura Range.
💡 **Exam Fact**: It is the highest peak of not just Satpura but the entire state of MP.
🧠 **Memory Tip**: Mahadev (Lord Shiva) resides at the highest peak.
🚫 **Scam Alert**: Amarkantak is in the Maikal range, while Dhupgarh is part of Mahadev hills.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('51f97e5f-f80c-4452-b52e-e9fbb854f9d9', '958e238b-a3a3-4bec-9827-366186a6a6dd', 'बुंदेलखंड पठार की सबसे ऊँची चोटी कौन सी है?', '[{"id":"A","text":"सिद्ध बाबा की चोटी","text_en":"सिद्ध बाबा की चोटी"},{"id":"B","text":"सिगार चोटी","text_en":"सिगार चोटी"},{"id":"C","text":"जानापाव","text_en":"जानापाव"},{"id":"D","text":"गुडविल चोटी (सद्भावना)","text_en":"गुडविल चोटी (सद्भावना)"}]', '0', '✅ **Correct Logic**: सिद्ध बाबा की चोटी (1172 मीटर) बुंदेलखंड पठार की सबसे ऊँची चोटी है।
💡 **Exam Fact**: सिगार चोटी मालवा पठार की सबसे ऊँची चोटी (881 मीटर) है।
🧠 **Memory Tip**: Bundelkhand''s Siddha (Powerful) Saint.
🚫 **Scam Alert**: गुडविल या सद्भावना चोटी विंध्याचल श्रेणी (रीवा-पन्ना पठार) की सबसे ऊँची चोटी है।', 2, 0, 3, NULL, 'Which is the highest peak of the Bundelkhand Plateau?', '✅ **Correct Logic**: Siddha Baba peak (1172m) is the highest peak of the Bundelkhand plateau.
💡 **Exam Fact**: Sigar peak (881m) is the highest peak of the Malwa plateau.
🧠 **Memory Tip**: Think of a ''Siddha'' (Accomplished) saint in Bundelkhand.
🚫 **Scam Alert**: Goodwill or Sadbhavna peak is the highest in the Vindhyan range (Rewa-Panna plateau).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c20933e2-d280-4770-a2dc-ac275e730542', '958e238b-a3a3-4bec-9827-366186a6a6dd', 'विंध्याचल एवं सतपुड़ा पर्वत श्रृंखलाओं के मध्य कौन सी भ्रंश घाटी (Rift Valley) स्थित है?', '[{"id":"A","text":"नर्मदा सोन घाटी","text_en":"नर्मदा सोन घाटी"},{"id":"B","text":"चंबल घाटी","text_en":"चंबल घाटी"},{"id":"C","text":"ताप्ती घाटी","text_en":"ताप्ती घाटी"},{"id":"D","text":"बेतवा घाटी","text_en":"बेतवा घाटी"}]', '0', '✅ **Correct Logic**: नर्मदा नदी विंध्याचल (उत्तर) और सतपुड़ा (दक्षिण) के मध्य भ्रंश घाटी में बहती है।
💡 **Exam Fact**: यह मध्य प्रदेश का सबसे निचला प्राकृतिक प्रदेश है।
🧠 **Memory Tip**: Narmada is ''sandwiched'' between V and S.
🚫 **Scam Alert**: ताप्ती घाटी सतपुड़ा के दक्षिण में स्थित है, दोनों के मध्य नहीं।', 2, 0, 4, NULL, 'Which Rift Valley is situated between the Vindhyachal and Satpura mountain ranges?', '✅ **Correct Logic**: The Narmada river flows through a rift valley between the Vindhyachal (North) and Satpura (South) ranges.
💡 **Exam Fact**: It is the lowest physical division of Madhya Pradesh.
🧠 **Memory Tip**: Narmada is sandwiched between V and S.
🚫 **Scam Alert**: Tapti valley is south of Satpura, not between the two ranges.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6b59c93f-97de-4558-82a1-b82dfd2cfe1e', '958e238b-a3a3-4bec-9827-366186a6a6dd', 'पठार और उनके निर्माण की चट्टानों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: मालवा ज्वालामुखी लावा (बेसाल्ट) से बना है। बुंदेलखंड प्राचीनतम ग्रेनाइट/नीस से। रीवा-पन्ना विंध्यन और बघेलखंड गोंडवाना समूह से संबंधित है।
💡 **Exam Fact**: गोंडवाना चट्टानों में कोयले की प्रचुरता पाई जाती है।
🧠 **Memory Tip**: Malwa-Basalt (M-B).
🚫 **Scam Alert**: दक्कन ट्रैप केवल मालवा तक सीमित नहीं है, लेकिन मालवा इसका मुख्य भाग है।', 2, 0, 5, NULL, 'Match the plateaus and the rocks they are formed from:', '✅ **Correct Logic**: Malwa is formed from volcanic lava (Basalt). Bundelkhand from ancient Granite/Gneiss. Rewa-Panna from Vindhyan and Baghelkhand from Gondwana groups.
💡 **Exam Fact**: Gondwana rocks are rich in coal deposits.
🧠 **Memory Tip**: Malwa-Basalt (M-B).
🚫 **Scam Alert**: Deccan Trap isn''t exclusive to Malwa but Malwa is its primary extent in MP.', 60, 'matching', '[{"id":"(1)","label":"मालवा का पठार","match":"दक्कन ट्रैप (बेसाल्ट)","matchId":"(a)"},{"id":"(2)","label":"बुंदेलखंड का पठार","match":"नीस और ग्रेनाइट","matchId":"(b)"},{"id":"(3)","label":"रीवा-पन्ना का पठार","match":"विंध्यन शैल समूह","matchId":"(c)"},{"id":"(4)","label":"बघेलखंड का पठार","match":"गोंडवाना शैल समूह","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a5123f00-27ea-4eab-9d50-5d23c18cb91b', '958e238b-a3a3-4bec-9827-366186a6a6dd', 'ग्वालियर की पहाड़ियों और आगरा के बीच कौन सा पठार स्थित है?', '[{"id":"A","text":"मध्य भारत का पठार","text_en":"मध्य भारत का पठार"},{"id":"B","text":"बुंदेलखंड का पठार","text_en":"बुंदेलखंड का पठार"},{"id":"C","text":"मालवा का पठार","text_en":"मालवा का पठार"},{"id":"D","text":"रीवा-पन्ना का पठार","text_en":"रीवा-पन्ना का पठार"}]', '0', '✅ **Correct Logic**: मध्य भारत का पठार (Central India Plateau) ग्वालियर, भिंड, मुरैना और आगरा के सीमावर्ती क्षेत्रों में फैला है।
💡 **Exam Fact**: इसे ''चंबल का उप-आद्र प्रदेश'' भी कहा जाता है।
🧠 **Memory Tip**: Gwalior is in the ''Center'' of North MP.
🚫 **Scam Alert**: यह क्षेत्र ''बीहड़'' (Ravines) के लिए बदनाम है।', 2, 0, 6, NULL, 'Which plateau is situated between the hills of Gwalior and Agra?', '✅ **Correct Logic**: The Central India Plateau covers Gwalior, Bhind, Morena, and areas bordering Agra.
💡 **Exam Fact**: It is also known as the ''Sub-humid region of Chambal''.
🧠 **Memory Tip**: Gwalior lies in the center of the northern projection of MP.
🚫 **Scam Alert**: This region is infamous for ''Ravines'' (Badland topography).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('118805d2-3d8f-44fe-aae1-b9ced8a48cc7', '958e238b-a3a3-4bec-9827-366186a6a6dd', 'सतपुड़ा पर्वतमाला की पश्चिमी पहाड़ियों को किस नाम से जाना जाता है?', '[{"id":"A","text":"राजपीपला की पहाड़ियाँ","text_en":"राजपीपला की पहाड़ियाँ"},{"id":"B","text":"मैकल की पहाड़ियाँ","text_en":"मैकल की पहाड़ियाँ"},{"id":"C","text":"महादेव पहाड़ियाँ","text_en":"महादेव पहाड़ियाँ"},{"id":"D","text":"कैमूर पहाड़ियाँ","text_en":"कैमूर पहाड़ियाँ"}]', '0', '✅ **Correct Logic**: सतपुड़ा श्रेणी के पश्चिमी भाग को ''राजपीपला'' कहा जाता है (गुजरात सीमा तक)।
💡 **Exam Fact**: इसका मध्य भाग महादेव और पूर्वी भाग मैकल कहलाता है।
🧠 **Memory Tip**: R-M-M (Rajpipla-Mahadev-Maikal) from West to East.
🚫 **Scam Alert**: कैमूर पहाड़ियाँ विंध्याचल श्रेणी का पूर्वी हिस्सा हैं, सतपुड़ा का नहीं।', 2, 0, 7, NULL, 'By what name are the western hills of the Satpura range known?', '✅ **Correct Logic**: The western part of the Satpura range is called ''Rajpipla'' (extending to the Gujarat border).
💡 **Exam Fact**: The middle part is Mahadev and the eastern part is Maikal.
🧠 **Memory Tip**: R-M-M (Rajpipla-Mahadev-Maikal) from West to East.
🚫 **Scam Alert**: Kaimur hills are the eastern part of the Vindhyan range, not Satpura.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d387713b-5037-4713-8128-9cc0ab8fd888', '958e238b-a3a3-4bec-9827-366186a6a6dd', 'मध्य प्रदेश के किस भौतिक विभाग की औसत ऊँचाई सबसे कम है?', '[{"id":"A","text":"नर्मदा-सोन घाटी","text_en":"नर्मदा-सोन घाटी"},{"id":"B","text":"मालवा का पठार","text_en":"मालवा का पठार"},{"id":"C","text":"मध्य भारत का पठार","text_en":"मध्य भारत का पठार"},{"id":"D","text":"बघेलखंड का पठार","text_en":"बघेलखंड का पठार"}]', '0', '✅ **Correct Logic**: नर्मदा-सोन घाटी मध्य प्रदेश का सबसे गहरा या निचला भू-भाग है। इसकी औसत ऊँचाई लगभग 300 मीटर है।
💡 **Exam Fact**: यह एक रिफ्ट वैली (Rift Valley) है।
🧠 **Memory Tip**: Valley (घाटी) means deep/low land.
🚫 **Scam Alert**: मध्य भारत का पठार नीचा है, लेकिन नर्मदा घाटी उससे भी गहरी है।', 2, 0, 8, NULL, 'Which physical division of MP has the lowest average height?', '✅ **Correct Logic**: The Narmada-Son valley is the lowest physical part of MP, with an average height of around 300m.
💡 **Exam Fact**: It is a structural Rift Valley.
🧠 **Memory Tip**: A valley is naturally lower than a plateau.
🚫 **Scam Alert**: While the Central India plateau is low, the Narmada valley is deeper.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bd86f9a3-b141-4634-b095-462724844820', '958e238b-a3a3-4bec-9827-366186a6a6dd', 'विंध्याचल पर्वत श्रृंखला की ''कैमूर'' और ''भांडेर'' श्रेणियाँ मध्य प्रदेश के किस भाग में विस्तृत हैं?', '[{"id":"A","text":"पूर्वी भाग","text_en":"पूर्वी भाग"},{"id":"B","text":"पश्चिमी भाग","text_en":"पश्चिमी भाग"},{"id":"C","text":"उत्तरी भाग","text_en":"उत्तरी भाग"},{"id":"D","text":"दक्षिणी भाग","text_en":"दक्षिणी भाग"}]', '0', '✅ **Correct Logic**: विंध्याचल के पूर्वी विस्तार को भांडेर और कैमूर श्रेणियों के रूप में जाना जाता है।
💡 **Exam Fact**: कैमूर श्रेणी यमुना और सोन नदी के मध्य जल-विभाजक (Water-divide) का कार्य करती है।
🧠 **Memory Tip**: V-B-K (Vindhyan-Bhander-Kaimur) moving East.
🚫 **Scam Alert**: पश्चिमी भाग को केवल विंध्याचल श्रेणी के नाम से जाना जाता है।', 2, 0, 9, NULL, 'In which part of MP are the ''Kaimur'' and ''Bhander'' ranges of the Vindhyachal mountains extended?', '✅ **Correct Logic**: The eastern extensions of the Vindhyachal are known as Bhander and Kaimur ranges.
💡 **Exam Fact**: Kaimur range acts as a water-divide between the Yamuna and Son rivers.
🧠 **Memory Tip**: V-B-K (Vindhyan-Bhander-Kaimur) as you move East.
🚫 **Scam Alert**: The western part is generally referred to simply as the Vindhyachal range.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d190dba0-c6c0-4b08-a20e-1c8262efb8ff', '958e238b-a3a3-4bec-9827-366186a6a6dd', 'मध्य प्रदेश के भौगोलिक क्षेत्रफल का कितना प्रतिशत ''रीवा-पन्ना पठार'' के अंतर्गत आता है?', '[{"id":"A","text":"10.37%","text_en":"10.37%"},{"id":"B","text":"7.7%","text_en":"7.7%"},{"id":"C","text":"28%","text_en":"28%"},{"id":"D","text":"26%","text_en":"26%"}]', '0', '✅ **Correct Logic**: रीवा-पन्ना पठार राज्य के कुल क्षेत्रफल का लगभग 10.37% हिस्सा कवर करता है।
💡 **Exam Fact**: इसे ''विंध्य कगारी प्रदेश'' (Vindhyan Scarp-land) भी कहा जाता है।
🧠 **Memory Tip**: RP - Ten (approx).
🚫 **Scam Alert**: 7.7% बघेलखंड पठार का हिस्सा है, जो सबसे छोटा पठार है।', 2, 0, 10, NULL, 'What percentage of MP''s geographical area falls under the ''Rewa-Panna Plateau''?', '✅ **Correct Logic**: The Rewa-Panna plateau covers about 10.37% of the state''s area.
💡 **Exam Fact**: It is also known as the ''Vindhyan Scarp-land''.
🧠 **Memory Tip**: RP - 10.37 (Think of it as the 10th part).
🚫 **Scam Alert**: 7.7% is the area of the Baghelkhand plateau, which is the smallest physical division.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5e4eeb28-e594-4e40-aef8-31a14d31db41', '96c98010-ad5e-430e-bf08-106b39039fe3', 'प्रायद्वीपीय भारत में सिंचाई का प्रमुख साधन ''तालाब'' (Tank Irrigation) क्यों है?', '[{"id":"A","text":"नदियाँ मौसमी हैं और चट्टानी धरातल के कारण नहरें/कुएँ खोदना कठिन है","text_en":"नदियाँ मौसमी हैं और चट्टानी धरातल के कारण नहरें/कुएँ खोदना कठिन है"},{"id":"B","text":"वहाँ भूजल स्तर बहुत ऊपर है","text_en":"वहाँ भूजल स्तर बहुत ऊपर है"},{"id":"C","text":"वहाँ की मिट्टी बहुत उपजाऊ है","text_en":"वहाँ की मिट्टी बहुत उपजाऊ है"},{"id":"D","text":"वहाँ वर्षा साल भर होती है","text_en":"वहाँ वर्षा साल भर होती है"}]', '0', '**✅ Correct Logic:** प्रायद्वीपीय भारत (जैसे तमिलनाडु, आंध्र) में कठोर चट्टानी धरातल है, जिससे नहरें और कुएँ खोदना मुश्किल है। साथ ही, मिट्टी छिद्रपूर्ण नहीं है, इसलिए पानी सोखने की बजाय प्राकृतिक गड्ढों में जमा हो जाता है, जिसे तालाब के रूप में उपयोग किया जाता है।

**💡 Exam Fact:** तमिलनाडु और तेलंगाना में तालाब सिंचाई का प्रतिशत सबसे अधिक है।

**🧠 Memory Tip:** **Hard Rocks** break drills, so store water in **Tanks**.

**🚫 Scam Alert:** उत्तर भारत में कुएँ/नहरें आसान हैं क्योंकि वहाँ जलोढ़ मिट्टी (Alluvial soil) है।', 2, 0, 1, NULL, 'Why is ''Tank Irrigation'' the main source of irrigation in Peninsular India?', '**✅ Correct Logic:** Peninsular India has hard rocky terrain making it difficult to dig canals/wells. The non-porous rock helps store water in natural depressions (Tanks).

**💡 Exam Fact:** Tamil Nadu and Telangana have the highest percentage of tank irrigation.

**🧠 Memory Tip:** **Hard Rocks** -> **Tanks**.

**🚫 Scam Alert:** North India uses Wells/Canals due to soft soil.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3de592d7-e699-4c51-b86a-9bc327d7b333', '96c98010-ad5e-430e-bf08-106b39039fe3', 'केन-बेतवा लिंक परियोजना (Ken-Betwa Link Project) का मुख्य उद्देश्य किस क्षेत्र को सूखा राहत प्रदान करना है?', '[{"id":"A","text":"बुंदेलखंड (Bundelkhand)","text_en":"बुंदेलखंड (Bundelkhand)"},{"id":"B","text":"बघेलखंड (Baghelkhand)","text_en":"बघेलखंड (Baghelkhand)"},{"id":"C","text":"विदर्भ (Vidarbha)","text_en":"विदर्भ (Vidarbha)"},{"id":"D","text":"कच्छ (Kutch)","text_en":"कच्छ (Kutch)"}]', '0', '**✅ Correct Logic:** यह भारत की पहली नदी जोड़ो परियोजना है। इसका उद्देश्य केन नदी (MP) का अधिशेष पानी बेतवा नदी (UP) में भेजना है ताकि सूखाग्रस्त **बुंदेलखंड** क्षेत्र (MP और UP दोनों) की प्यास बुझ सके।

**💡 Exam Fact:** पन्ना टाइगर रिजर्व का एक बड़ा हिस्सा इस परियोजना में डूब जाएगा।

**🧠 Memory Tip:** **Ken** gives water to **Betwa** for **Bundelkhand** brothers.

**🚫 Scam Alert:** बघेलखंड पूर्व में है, बुंदेलखंड (झांसी/टीकमगढ़) सूखाग्रस्त है।', 2, 0, 2, NULL, 'The main objective of the Ken-Betwa Link Project is to provide drought relief to which region?', '**✅ Correct Logic:** First river-linking project. Transfers surplus water from Ken to Betwa to irrigate the drought-prone **Bundelkhand** region.

**💡 Exam Fact:** A large part of Panna Tiger Reserve will be submerged.

**🧠 Memory Tip:** **Ken** helps **Betwa** in **Bundelkhand**.

**🚫 Scam Alert:** Baghelkhand is in East, Bundelkhand is the target area.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('15b299c4-34cb-4440-97eb-1c8a87a4f9e6', '96c98010-ad5e-430e-bf08-106b39039fe3', 'भूजल दोहन (Groundwater Exploitation) की दर भारत के किस राज्य में सबसे अधिक (100% से ऊपर) है?', '[{"id":"A","text":"पंजाब (Punjab)","text_en":"पंजाब (Punjab)"},{"id":"B","text":"मध्य प्रदेश (Madhya Pradesh)","text_en":"मध्य प्रदेश (Madhya Pradesh)"},{"id":"C","text":"केरल (Kerala)","text_en":"केरल (Kerala)"},{"id":"D","text":"ओडिशा (Odisha)","text_en":"ओडिशा (Odisha)"}]', '0', '**✅ Correct Logic:** हरित क्रांति के कारण **पंजाब** (और हरियाणा/राजस्थान) में भूजल का अत्यधिक दोहन हुआ है। यहाँ जितना पानी रिचार्ज होता है, उससे कहीं ज्यादा निकाला जाता है।

**💡 Exam Fact:** केंद्रीय भूजल बोर्ड (CGWB) के अनुसार, यह क्षेत्र ''Over-exploited'' श्रेणी में है।

**🧠 Memory Tip:** **Punjab** pumps water like crazy for **Paddy**.

**🚫 Scam Alert:** यूपी में सबसे ज्यादा ट्यूबवेल हैं, लेकिन ''दोहन की दर'' (प्रतिशत में) पंजाब में सबसे ज्यादा है।', 2, 0, 3, NULL, 'In which Indian state is the rate of Groundwater Exploitation highest (above 100%)?', '**✅ Correct Logic:** Due to Green Revolution, **Punjab** has over-exploited groundwater. Extraction exceeds recharge.

**💡 Exam Fact:** Classified as ''Over-exploited'' by CGWB.

**🧠 Memory Tip:** **Punjab** pumps for **Paddy**.

**🚫 Scam Alert:** UP has most tubewells, but Punjab has highest exploitation Rate (%).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b518acc2-1af1-4e3f-94f2-181f0f7d6631', '96c98010-ad5e-430e-bf08-106b39039fe3', '''ड्रिप सिंचाई'' (Drip Irrigation) पद्धति मूल रूप से किस देश में विकसित की गई थी?', '[{"id":"A","text":"इज़राइल (Israel)","text_en":"इज़राइल (Israel)"},{"id":"B","text":"संयुक्त राज्य अमेरिका (USA)","text_en":"संयुक्त राज्य अमेरिका (USA)"},{"id":"C","text":"चीन (China)","text_en":"चीन (China)"},{"id":"D","text":"जापान (Japan)","text_en":"जापान (Japan)"}]', '0', '**✅ Correct Logic:** ड्रिप सिंचाई (टपक सिंचाई) **इज़राइल** में विकसित की गई थी। यह पानी की बचत (40-70%) के लिए सबसे कुशल विधि है क्योंकि पानी सीधे जड़ों में दिया जाता है।

**💡 Exam Fact:** ''प्रधानमंत्री कृषि सिंचाई योजना'' (Per Drop More Crop) इसे बढ़ावा देती है।

**🧠 Memory Tip:** **Israel** lives in desert -> Invented best water saving tech.

**🚫 Scam Alert:** यह तकनीक भारत में अब लोकप्रिय है, लेकिन मूल इजराइल की है।', 2, 0, 4, NULL, '''Drip Irrigation'' method was originally developed in which country?', '**✅ Correct Logic:** Developed in **Israel**. Most efficient (40-70% saving) as water goes directly to roots.

**💡 Exam Fact:** Promoted under PMKSY ''Per Drop More Crop''.

**🧠 Memory Tip:** **Israel** -> Desert -> Water saving.

**🚫 Scam Alert:** Origin is Israel.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5aa78cb3-41b6-4ab4-93fd-dcc8b3275c34', '96c98010-ad5e-430e-bf08-106b39039fe3', 'इंदिरा गांधी नहर (Indira Gandhi Canal), जो दुनिया की सबसे लंबी सिंचाई नहरों में से एक है, को पानी किस बैराज से मिलता है?', '[{"id":"A","text":"हरिके बैराज (Harike Barrage)","text_en":"हरिके बैराज (Harike Barrage)"},{"id":"B","text":"नांगल बांध (Nangal Dam)","text_en":"नांगल बांध (Nangal Dam)"},{"id":"C","text":"पोंग बांध (Pong Dam)","text_en":"पोंग बांध (Pong Dam)"},{"id":"D","text":"रणजीत सागर बांध (Ranjit Sagar Dam)","text_en":"रणजीत सागर बांध (Ranjit Sagar Dam)"}]', '0', '**✅ Correct Logic:** इंदिरा गांधी नहर (IGNP) **हरिके बैराज** (पंजाब) से निकलती है, जो **सतलज और व्यास** नदियों के संगम पर स्थित है। इसने पश्चिमी राजस्थान को हरा-भरा कर दिया है।

**💡 Exam Fact:** इसे पहले ''राजस्थान नहर'' कहा जाता था।

**🧠 Memory Tip:** **Hari**ke -> **Hari**yali in Rajasthan.

**🚫 Scam Alert:** भाखड़ा नांगल अलग है। हरिके बैराज (सतलज+व्यास संगम) सही उत्तर है।', 2, 0, 5, NULL, 'Indira Gandhi Canal, one of the longest irrigation canals in the world, receives water from which barrage?', '**✅ Correct Logic:** IGNP starts from **Harike Barrage** (Punjab) at the confluence of **Satluj and Beas** rivers. It transformed Western Rajasthan.

**💡 Exam Fact:** Formerly called ''Rajasthan Canal''.

**🧠 Memory Tip:** **Hari**ke -> **Hari**yali.

**🚫 Scam Alert:** Not Bhakra Nangal. It''s Harike.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7898f22e-2f2a-470f-ad33-56a942f6fc3e', '96c98010-ad5e-430e-bf08-106b39039fe3', 'सरदार सरोवर बांध (Sardar Sarovar Dam) किस नदी पर बना है और इससे किन राज्यों को लाभ मिलता है?', '[{"id":"A","text":"नर्मदा - गुजरात, एमपी, महाराष्ट्र, राजस्थान","text_en":"नर्मदा - गुजरात, एमपी, महाराष्ट्र, राजस्थान"},{"id":"B","text":"ताप्ती - गुजरात, महाराष्ट्र","text_en":"ताप्ती - गुजरात, महाराष्ट्र"},{"id":"C","text":"चंबल - एमपी, राजस्थान","text_en":"चंबल - एमपी, राजस्थान"},{"id":"D","text":"महानदी - ओडिशा, छत्तीसगढ़","text_en":"महानदी - ओडिशा, छत्तीसगढ़"}]', '0', '**✅ Correct Logic:** सरदार सरोवर **नर्मदा नदी** (गुजरात) पर बना है। यह चार राज्यों: **गुजरात, मध्य प्रदेश, महाराष्ट्र और राजस्थान** की संयुक्त परियोजना है।

**💡 Exam Fact:** सबसे ज्यादा बिजली एमपी को (57%) और सबसे ज्यादा पानी गुजरात को मिलता है।

**🧠 Memory Tip:** **Sardar** (Vallabhbhai) united states -> Dam unites 4 states.

**🚫 Scam Alert:** राजस्थान भी इसमें शामिल है (नहर के माध्यम से पानी जाता है), भले ही नदी वहां से न बहे।', 2, 0, 6, NULL, 'Sardar Sarovar Dam is built on which river and benefits which states?', '**✅ Correct Logic:** Built on **Narmada** (Gujarat). Benefits 4 states: **Gujarat, MP, Maharashtra, Rajasthan**.

**💡 Exam Fact:** MP gets max Power (57%), Gujarat gets max Water.

**🧠 Memory Tip:** **Sardar** united states.

**🚫 Scam Alert:** Rajasthan is a beneficiary (via canal) even though river doesn''t flow there.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('74e9f00b-73a8-4dfc-ab0f-4578f35b422b', '96c98010-ad5e-430e-bf08-106b39039fe3', 'भारत में ''जल वर्ष'' (Water Year) कब से कब तक माना जाता है?', '[{"id":"A","text":"1 जून से 31 मई (1st June to 31st May)","text_en":"1 जून से 31 मई (1st June to 31st May)"},{"id":"B","text":"1 अप्रैल से 31 मार्च (1st April to 31st March)","text_en":"1 अप्रैल से 31 मार्च (1st April to 31st March)"},{"id":"C","text":"1 जनवरी से 31 दिसंबर (1st Jan to 31st Dec)","text_en":"1 जनवरी से 31 दिसंबर (1st Jan to 31st Dec)"},{"id":"D","text":"1 नवंबर से 31 अक्टूबर (1st Nov to 31st Oct)","text_en":"1 नवंबर से 31 अक्टूबर (1st Nov to 31st Oct)"}]', '0', '**✅ Correct Logic:** केंद्रीय जल आयोग (CWC) के अनुसार, जल वर्ष **1 जून से 31 मई** तक होता है, क्योंकि भारत में मानसून 1 जून के आसपास आता है, जो जल चक्र की शुरुआत है।

**💡 Exam Fact:** वित्तीय वर्ष (अप्रैल-मार्च) और कृषि वर्ष (जुलाई-जून) से अलग है।

**🧠 Memory Tip:** Water comes with Monsoon (**June**) -> Water Year starts June.

**🚫 Scam Alert:** कृषि वर्ष 1 जुलाई से है, लेकिन जल वर्ष 1 जून से है।', 2, 0, 7, NULL, 'When is the ''Water Year'' considered in India?', '**✅ Correct Logic:** As per CWC, Water Year is **1st June to 31st May**, coinciding with the arrival of Monsoon.

**💡 Exam Fact:** Distinct from Financial Year (Apr-Mar) and Agriculture Year (Jul-Jun).

**🧠 Memory Tip:** Water comes with Monsoon (**June**).

**🚫 Scam Alert:** Agriculture year is July, Water year is June.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7db60575-f545-4c4c-bffa-bdb4795c918b', '96c98010-ad5e-430e-bf08-106b39039fe3', 'पोलावरम परियोजना (Polavaram Project) किस नदी पर निर्माणाधीन एक बहुउद्देशीय राष्ट्रीय परियोजना है?', '[{"id":"A","text":"गोदावरी (Godavari)","text_en":"गोदावरी (Godavari)"},{"id":"B","text":"कृष्णा (Krishna)","text_en":"कृष्णा (Krishna)"},{"id":"C","text":"कावेरी (Kaveri)","text_en":"कावेरी (Kaveri)"},{"id":"D","text":"पेन्नार (Pennar)","text_en":"पेन्नार (Pennar)"}]', '0', '**✅ Correct Logic:** पोलावरम परियोजना **गोदावरी नदी** (आंध्र प्रदेश) पर स्थित है। इसे राष्ट्रीय परियोजना (National Project) का दर्जा प्राप्त है। यह कृष्णा नदी बेसिन में भी पानी स्थानांतरित करेगी।

**💡 Exam Fact:** यह गोदावरी-कृष्णा लिंक का हिस्सा है।

**🧠 Memory Tip:** **God**avari gets **Pola**varam.

**🚫 Scam Alert:** यह कृष्णा डेल्टा को पानी देगी, लेकिन बनी गोदावरी पर है।', 2, 0, 8, NULL, 'Polavaram Project is a multi-purpose national project under construction on which river?', '**✅ Correct Logic:** Located on **Godavari River** (AP). It is a National Project. Will transfer water to Krishna basin.

**💡 Exam Fact:** Part of Godavari-Krishna link.

**🧠 Memory Tip:** **God**avari gets **Pola**varam.

**🚫 Scam Alert:** Benefits Krishna delta, but built on Godavari.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('00570ed7-08a5-4d4f-97c3-0cc8513f669c', '96c98010-ad5e-430e-bf08-106b39039fe3', 'विश्व का सबसे लंबा मिट्टी का बांध (Earthen Dam) कौन सा है?', '[{"id":"A","text":"हीराकुंड बांध (Hirakud Dam)","text_en":"हीराकुंड बांध (Hirakud Dam)"},{"id":"B","text":"टिहरी बांध (Tehri Dam)","text_en":"टिहरी बांध (Tehri Dam)"},{"id":"C","text":"भाखड़ा बांध (Bhakra Dam)","text_en":"भाखड़ा बांध (Bhakra Dam)"},{"id":"D","text":"नागार्जुन सागर (Nagarjuna Sagar)","text_en":"नागार्जुन सागर (Nagarjuna Sagar)"}]', '0', '**✅ Correct Logic:** **हीराकुंड बांध** (महानदी, ओडिशा) दुनिया का सबसे लंबा (Longest) मिट्टी का बांध है। इसकी कुल लंबाई 25.8 किमी (मुख्य बांध 4.8 किमी) है।

**💡 Exam Fact:** टिहरी सबसे ऊंचा (Highest) है, भाखड़ा सबसे बड़ा गुरुत्वीय (Gravity) बांधों में से है।

**🧠 Memory Tip:** **Hira** (Diamond) is rare, Hirakud is **Long**est.

**🚫 Scam Alert:** ऊंचा (High) और लंबा (Long) में अंतर है। टिहरी = ऊंचा, हीराकुंड = लंबा।', 2, 0, 9, NULL, 'Which is the longest Earthen Dam in the world?', '**✅ Correct Logic:** **Hirakud Dam** (Mahanadi, Odisha) is the world''s **Longest** earthen dam. Total length 25.8 km.

**💡 Exam Fact:** Tehri is Highest. Bhakra is Gravity.

**🧠 Memory Tip:** Hirakud is **Long**est.

**🚫 Scam Alert:** Don''t confuse Highest (Tehri) with Longest (Hirakud).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('792b68b5-ce6b-43ed-a869-eeb6ac931656', '96c98010-ad5e-430e-bf08-106b39039fe3', 'निम्नलिखित बहुउद्देशीय परियोजनाओं को संबंधित नदियों से सुमेलित करें (Match the multipurpose projects with respective rivers):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **माताटीला**: बेतवा नदी (एमपी/यूपी सीमा)। इसे ''रानी लक्ष्मीबाई बांध'' भी कहते हैं। -> (1)-(a)
* **उकाई**: ताप्ती नदी (गुजरात)। -> (2)-(b)
* **इडुक्की**: पेरियार नदी (केरल)। यह एक आर्च (Arch) बांध है। -> (3)-(c)
* **अलमट्टी**: कृष्णा नदी (कर्नाटक)। इसे ''लाल बहादुर शास्त्री बांध'' भी कहते हैं। -> (4)-(d)

**💡 Exam Fact:** अलमट्टी बांध की ऊंचाई बढ़ाने पर कर्नाटक और आंध्र में विवाद है।

**🧠 Memory Tip:** **Mata** Betwa. **Ukai** Tapti. **Idukki** Periyar. **Krishna** loves **Matti** (Almatti).

**🚫 Scam Alert:** अलमट्टी कृष्णा पर है (माटी खाओ कृष्णा), कावेरी पर नहीं।', 2, 0, 10, NULL, 'Match the multipurpose projects with respective rivers:', '**✅ Correct Matching:**
* **Matatila**: Betwa (MP/UP). -> (1)-(a)
* **Ukai**: Tapti (Gujarat). -> (2)-(b)
* **Idukki**: Periyar (Kerala). Arch Dam. -> (3)-(c)
* **Almatti**: Krishna (Karnataka). -> (4)-(d)

**💡 Exam Fact:** Almatti dispute between KA and AP.

**🧠 Memory Tip:** **Krishna** loves **Matti** (Almatti).

**🚫 Scam Alert:** Almatti is on Krishna, not Kaveri.', 60, 'matching', '[{"id":"(1)","label":"माताटीला बांध (Matatila Dam)","match":"बेतवा (Betwa)","matchId":"(a)"},{"id":"(2)","label":"उकाई परियोजना (Ukai Project)","match":"ताप्ती (Tapti)","matchId":"(b)"},{"id":"(3)","label":"इडुक्की बांध (Idukki Dam)","match":"पेरियार (Periyar)","matchId":"(c)"},{"id":"(4)","label":"अलमट्टी बांध (Almatti Dam)","match":"कृष्णा (Krishna)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ccfa9d41-3f41-4d26-a4b6-115f04157126', '0b65076a-0080-4193-8b93-97c3dbe398f6', '''कल्याण सोना'' (Kalyan Sona) और ''सोनालिका'' (Sonalika) किस फसल की उच्च उपज देने वाली किस्में (HYV) हैं?', '[{"id":"A","text":"चावल (Rice)","text_en":"चावल (Rice)"},{"id":"B","text":"गेहूं (Wheat)","text_en":"गेहूं (Wheat)"},{"id":"C","text":"मक्का (Maize)","text_en":"मक्का (Maize)"},{"id":"D","text":"सोयाबीन (Soybean)","text_en":"सोयाबीन (Soybean)"}]', '1', '**✅ Correct Logic:** ये **गेहूं** की वामन (Dwarf) किस्में हैं जो भारत में हरित क्रांति के दौरान लाई गई थीं। इन्होंने उत्पादन में भारी वृद्धि की।

**💡 Exam Fact:** जया और रत्ना ''चावल'' की किस्में हैं।

**🧠 Memory Tip:** **Sona** (Gold) colour is like **Wheat**.

**🚫 Scam Alert:** सोनालिका ट्रैक्टर कंपनी भी है, लेकिन यहाँ फसल की बात हो रही है। चावल की किस्में अलग हैं।', 2, 0, 1, NULL, '''Kalyan Sona'' and ''Sonalika'' are High Yielding Varieties (HYV) of which crop?', '**✅ Correct Logic:** These are dwarf varieties of **Wheat** introduced during Green Revolution.

**💡 Exam Fact:** Jaya and Ratna are Rice varieties.

**🧠 Memory Tip:** **Sona** -> Gold -> Wheat.

**🚫 Scam Alert:** Don''t confuse with Rice.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('13f6cb03-2fb5-4a96-84d1-cc8db499c3a7', '0b65076a-0080-4193-8b93-97c3dbe398f6', 'भारत का कौन सा राज्य ''सोया प्रदेश'' (Soya State) के रूप में जाना जाता है?', '[{"id":"A","text":"महाराष्ट्र (Maharashtra)","text_en":"महाराष्ट्र (Maharashtra)"},{"id":"B","text":"मध्य प्रदेश (Madhya Pradesh)","text_en":"मध्य प्रदेश (Madhya Pradesh)"},{"id":"C","text":"राजस्थान (Rajasthan)","text_en":"राजस्थान (Rajasthan)"},{"id":"D","text":"उत्तर प्रदेश (Uttar Pradesh)","text_en":"उत्तर प्रदेश (Uttar Pradesh)"}]', '1', '**✅ Correct Logic:** **मध्य प्रदेश** को ''सोया स्टेट'' कहा जाता है क्योंकि यह सोयाबीन का सबसे बड़ा उत्पादक है। हालांकि हाल ही में महाराष्ट्र ने उत्पादन में कड़ी टक्कर दी है, लेकिन ऐतिहासिक और GK टैग एमपी के पास है।

**💡 Exam Fact:** सोयाबीन में सबसे अधिक प्रोटीन (40-42%) होता है।

**🧠 Memory Tip:** **MP** = **M**aximum **P**rotein (Soybean).

**🚫 Scam Alert:** करंट अफेयर्स में कभी-कभी महाराष्ट्र आगे निकल जाता है, लेकिन उपनाम (Nickname) एमपी का ही है।', 2, 0, 2, NULL, 'Which state of India is known as ''Soya State''?', '**✅ Correct Logic:** **Madhya Pradesh** is called ''Soya State''.

**💡 Exam Fact:** Soybean has highest protein (40-42%).

**🧠 Memory Tip:** **MP** = **M**aximum **P**rotein.

**🚫 Scam Alert:** Maharashtra competes closely, but the Tag belongs to MP.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('28f50954-ee9b-4148-bbf8-1d5b279eba73', '0b65076a-0080-4193-8b93-97c3dbe398f6', 'कपास (Cotton) की खेती के लिए सबसे उपयुक्त मिट्टी कौन सी है?', '[{"id":"A","text":"जलोढ़ मिट्टी (Alluvial Soil)","text_en":"जलोढ़ मिट्टी (Alluvial Soil)"},{"id":"B","text":"लाल मिट्टी (Red Soil)","text_en":"लाल मिट्टी (Red Soil)"},{"id":"C","text":"काली मिट्टी / रेगुर (Black Soil / Regur)","text_en":"काली मिट्टी / रेगुर (Black Soil / Regur)"},{"id":"D","text":"लेटेराइट मिट्टी (Laterite Soil)","text_en":"लेटेराइट मिट्टी (Laterite Soil)"}]', '2', '**✅ Correct Logic:** **काली मिट्टी** (Black Soil) जिसे ''रेगुर'' (Regur) या ''काली कपासी मिट्टी'' भी कहते हैं, कपास के लिए सर्वोत्तम है। इसमें नमी धारण करने की क्षमता अधिक होती है।

**💡 Exam Fact:** यह दक्कन ट्रैप (महाराष्ट्र/गुजरात) में पाई जाती है।

**🧠 Memory Tip:** **Black** shirt made of **Cotton**.

**🚫 Scam Alert:** जलोढ़ गेहूं/चावल के लिए है। कपास = काली मिट्टी।', 2, 0, 3, NULL, 'Which soil is most suitable for Cotton cultivation?', '**✅ Correct Logic:** **Black Soil** (Regur) is best for Cotton due to high moisture retention.

**💡 Exam Fact:** Found in Deccan Trap.

**🧠 Memory Tip:** **Black** Cotton.

**🚫 Scam Alert:** Alluvial is for wheat/rice. Cotton needs Black soil.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bc6cecae-862f-4563-a791-cb08a1e57d1a', '0b65076a-0080-4193-8b93-97c3dbe398f6', 'भारत में गन्ने (Sugarcane) के उत्पादन में कौन सा राज्य प्रथम है?', '[{"id":"A","text":"महाराष्ट्र (Maharashtra)","text_en":"महाराष्ट्र (Maharashtra)"},{"id":"B","text":"उत्तर प्रदेश (Uttar Pradesh)","text_en":"उत्तर प्रदेश (Uttar Pradesh)"},{"id":"C","text":"तमिलनाडु (Tamil Nadu)","text_en":"तमिलनाडु (Tamil Nadu)"},{"id":"D","text":"कर्नाटक (Karnataka)","text_en":"कर्नाटक (Karnataka)"}]', '1', '**✅ Correct Logic:** **उत्तर प्रदेश** गन्ने का सबसे बड़ा उत्पादक (Producer) है। इसे ''भारत का चीनी का कटोरा'' (Sugar Bowl) कहा जाता है।

**💡 Exam Fact:** चीनी *मिलों* की संख्या और चीनी *रिकवरी* (Recovery Rate) में महाराष्ट्र अक्सर आगे रहता है, लेकिन कुल गन्ना उत्पादन में यूपी नंबर 1 है।

**🧠 Memory Tip:** **UP** -> **Up**ar (Top) in Sugarcane.

**🚫 Scam Alert:** चीनी उत्पादन में कभी-कभी महाराष्ट्र आगे हो जाता है, लेकिन गन्ना उत्पादन में यूपी हमेशा टॉप पर है।', 2, 0, 4, NULL, 'Which state ranks first in Sugarcane production in India?', '**✅ Correct Logic:** **Uttar Pradesh** is the largest producer of Sugarcane.

**💡 Exam Fact:** Maharashtra leads in Sugar Recovery rate, but UP leads in total Cane production.

**🧠 Memory Tip:** **UP** is Top.

**🚫 Scam Alert:** Don''t confuse Sugar production with Sugarcane production.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d4a83f12-085a-421b-9354-56cc0ef7e7b0', '0b65076a-0080-4193-8b93-97c3dbe398f6', 'निम्नलिखित में से कौन सी एक ''जायद'' (Zaid) फसल है?', '[{"id":"A","text":"गेहूं (Wheat)","text_en":"गेहूं (Wheat)"},{"id":"B","text":"तरबूज (Watermelon)","text_en":"तरबूज (Watermelon)"},{"id":"C","text":"सरसों (Mustard)","text_en":"सरसों (Mustard)"},{"id":"D","text":"बाजरा (Bajra)","text_en":"बाजरा (Bajra)"}]', '1', '**✅ Correct Logic:** **तरबूज**, ककड़ी, खीरा और कुछ सब्जियां **जायद** मौसम (मार्च से जून, रबी और खरीफ के बीच) में उगाई जाती हैं।

**💡 Exam Fact:** रबी (सर्दी) और खरीफ (मानसून) के बीच का यह छोटा मौसम है।

**🧠 Memory Tip:** **Zaid** = **Z**ayada paani wala fruit (Watermelon).

**🚫 Scam Alert:** गेहूं रबी है, बाजरा खरीफ है। जायद गर्मियों की फसल है।', 2, 0, 5, NULL, 'Which of the following is a ''Zaid'' crop?', '**✅ Correct Logic:** **Watermelon**, Cucumber, etc., are **Zaid** crops grown in summer (March-June), between Rabi and Kharif.

**💡 Exam Fact:** It''s the short summer season crop.

**🧠 Memory Tip:** **Zaid** = **Z**ayada water (Watermelon).

**🚫 Scam Alert:** Wheat is Rabi, Bajra is Kharif.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('61968fcd-05ed-476e-bbde-6abc155c16c3', '0b65076a-0080-4193-8b93-97c3dbe398f6', 'भारत सरकार ने किस वर्ष को ''अंतर्राष्ट्रीय बाजरा वर्ष'' (International Year of Millets) घोषित करने का प्रस्ताव दिया था, जिसे UN ने स्वीकार किया?', '[{"id":"A","text":"2021","text_en":"2021"},{"id":"B","text":"2022","text_en":"2022"},{"id":"C","text":"2023","text_en":"2023"},{"id":"D","text":"2024","text_en":"2024"}]', '2', '**✅ Correct Logic:** वर्ष **2023** को अंतर्राष्ट्रीय बाजरा (मिलेट्स) वर्ष के रूप में मनाया गया। भारत ने बाजरा को ''श्री अन्न'' (Shree Anna) नाम दिया है।

**💡 Exam Fact:** भारत बाजरा का सबसे बड़ा वैश्विक उत्पादक है।

**🧠 Memory Tip:** 20**23** -> Melet**ee** (Three) -> 23.

**🚫 Scam Alert:** 2018 को ''राष्ट्रीय'' बाजरा वर्ष मनाया गया था, लेकिन अंतर्राष्ट्रीय 2023 है।', 2, 0, 6, NULL, 'Which year was proposed by Govt of India and accepted by UN as ''International Year of Millets''?', '**✅ Correct Logic:** **2023** was celebrated as International Year of Millets. India calls Millets ''Shree Anna''.

**💡 Exam Fact:** India is largest producer.

**🧠 Memory Tip:** 20**23**.

**🚫 Scam Alert:** 2018 was National year, 2023 is International.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('09402c6d-ff42-4dda-9dce-4a43a8b6b563', '0b65076a-0080-4193-8b93-97c3dbe398f6', '''गोल्डन फाइबर'' (Golden Fibre) किस फसल को कहा जाता है?', '[{"id":"A","text":"रेशम (Silk)","text_en":"रेशम (Silk)"},{"id":"B","text":"कपास (Cotton)","text_en":"कपास (Cotton)"},{"id":"C","text":"जूट (Jute)","text_en":"जूट (Jute)"},{"id":"D","text":"बांस (Bamboo)","text_en":"बांस (Bamboo)"}]', '2', '**✅ Correct Logic:** **जूट** (Jute) को उसके सुनहरे रंग और आर्थिक मूल्य के कारण ''गोल्डन फाइबर'' कहा जाता है। पश्चिम बंगाल इसका सबसे बड़ा उत्पादक है।

**💡 Exam Fact:** ''गोल्डन फाइबर क्रांति'' जूट उत्पादन से संबंधित है।

**🧠 Memory Tip:** Jute bags are brownish-gold.

**🚫 Scam Alert:** ''गोल्डन रिवोल्यूशन'' (बागवानी/शहद) और ''गोल्डन फाइबर'' (जूट) में अंतर है।', 2, 0, 7, NULL, 'Which crop is known as ''Golden Fibre''?', '**✅ Correct Logic:** **Jute** is called Golden Fibre. West Bengal is top producer.

**💡 Exam Fact:** ''Golden Fibre Revolution'' is related to Jute.

**🧠 Memory Tip:** Jute is gold.

**🚫 Scam Alert:** Golden Revolution (Honey/Horticulture) vs Golden Fibre (Jute).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b0de8357-34e9-4775-b478-bc0cf4f488de', '0b65076a-0080-4193-8b93-97c3dbe398f6', 'चाय की खेती के लिए निम्नलिखित में से कौन सी भौगोलिक स्थिति अनिवार्य है?', '[{"id":"A","text":"जड़ों में पानी जमा होना (Water logging in roots)","text_en":"जड़ों में पानी जमा होना (Water logging in roots)"},{"id":"B","text":"सुप्रवाहित ढलान वाली जमीन (Well-drained sloping land)","text_en":"सुप्रवाहित ढलान वाली जमीन (Well-drained sloping land)"},{"id":"C","text":"40°C से अधिक तापमान","text_en":"40°C से अधिक तापमान"},{"id":"D","text":"शुष्क जलवायु","text_en":"शुष्क जलवायु"}]', '1', '**✅ Correct Logic:** चाय के लिए भारी वर्षा (150-250 सेमी) चाहिए, लेकिन जड़ों में **पानी जमा नहीं होना चाहिए**। इसलिए इसे **ढलान वाली जमीन** (Slopes) पर उगाया जाता है।

**💡 Exam Fact:** अम्लीय मिट्टी (Acidic Soil) चाय के लिए अच्छी होती है।

**🧠 Memory Tip:** Tea hates standing water, likes to slide down the **Slope**.

**🚫 Scam Alert:** ''अधिक पानी'' चाहिए, लेकिन ''रुका हुआ'' नहीं। यही सबसे बड़ी शर्त है।', 2, 0, 8, NULL, 'Which of the following geographical conditions is mandatory for Tea cultivation?', '**✅ Correct Logic:** Tea needs heavy rain but **No Water Logging**. Hence **Well-drained slopes** are mandatory.

**💡 Exam Fact:** Needs Acidic Soil.

**🧠 Memory Tip:** Tea likes **Slopes**.

**🚫 Scam Alert:** Needs water, but flowing water, not stagnant.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4c3f4c35-8a65-4d05-8827-d5a8403edb1e', '0b65076a-0080-4193-8b93-97c3dbe398f6', 'भारत में ''हरित क्रांति'' (Green Revolution) का सर्वाधिक प्रभाव किन फसलों पर पड़ा?', '[{"id":"A","text":"चावल और दालें (Rice and Pulses)","text_en":"चावल और दालें (Rice and Pulses)"},{"id":"B","text":"गेहूं और चावल (Wheat and Rice)","text_en":"गेहूं और चावल (Wheat and Rice)"},{"id":"C","text":"मक्का और बाजरा (Maize and Bajra)","text_en":"मक्का और बाजरा (Maize and Bajra)"},{"id":"D","text":"तिलहन और गन्ना (Oilseeds and Sugarcane)","text_en":"तिलहन और गन्ना (Oilseeds and Sugarcane)"}]', '1', '**✅ Correct Logic:** हरित क्रांति (1966-67) का सबसे ज्यादा असर **गेहूं** (सर्वाधिक) और **चावल** पर पड़ा। दालों और मोटे अनाजों पर इसका प्रभाव नगण्य था।

**💡 Exam Fact:** इसे कभी-कभी ''गेहूं क्रांति'' (Wheat Revolution) भी कहा गया।

**🧠 Memory Tip:** Indians love Roti (Wheat) and Chawal (Rice) -> Green Revolution targeted these.

**🚫 Scam Alert:** दालों का उत्पादन स्थिर रहा या घट गया। फोकस केवल अनाज (Cereals) पर था।', 2, 0, 9, NULL, 'On which crops did the ''Green Revolution'' have the maximum impact in India?', '**✅ Correct Logic:** Maximum impact was on **Wheat** (highest) and **Rice**. Pulses and millets were neglected.

**💡 Exam Fact:** Sometimes called ''Wheat Revolution''.

**🧠 Memory Tip:** Wheat and Rice.

**🚫 Scam Alert:** Pulses did not benefit.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('890e9b63-d25e-4a07-b444-5576e9438134', '0b65076a-0080-4193-8b93-97c3dbe398f6', 'निम्नलिखित क्रांतियों को उनके क्षेत्र से सुमेलित करें (Match the following revolutions with their field):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **रजत (Silver)**: अंडे (इंदिरा गांधी से जुड़ा)। -> (1)-(a)
* **पीली (Yellow)**: तिलहन/सरसों (सैम पित्रोदा)। -> (2)-(b)
* **गोल (Round)**: आलू (दिखने में गोल)। -> (3)-(c)
* **गुलाबी (Pink)**: झींगा मछली (Prawn), प्याज और मांस प्रसंस्करण। -> (4)-(d)

**💡 Exam Fact:** नीली (Blue) मछली के लिए, श्वेत (White) दूध के लिए।

**🧠 Memory Tip:** **Silver** Egg. **Yellow** Mustard oil. **Round** Potato. **Pink** Prawn.

**🚫 Scam Alert:** ''रजत रेशा'' (Silver Fibre) कपास है, लेकिन ''रजत क्रांति'' अंडे है।', 2, 0, 10, NULL, 'Match the following revolutions with their field:', '**✅ Correct Matching:**
* **Silver**: Eggs. -> (1)-(a)
* **Yellow**: Oilseeds. -> (2)-(b)
* **Round**: Potato. -> (3)-(c)
* **Pink**: Prawn/Onion. -> (4)-(d)

**💡 Exam Fact:** Silver Fibre = Cotton, Silver Rev = Eggs.

**🧠 Memory Tip:** **Silver** Egg. **Yellow** Oil.

**🚫 Scam Alert:** Don''t confuse Silver Fibre (Cotton) with Silver Revolution (Egg).', 60, 'matching', '[{"id":"(1)","label":"रजत क्रांति (Silver Revolution)","match":"अंडे/पोल्ट्री (Eggs/Poultry)","matchId":"(a)"},{"id":"(2)","label":"पीली क्रांति (Yellow Revolution)","match":"तिलहन (Oilseeds)","matchId":"(b)"},{"id":"(3)","label":"गोल क्रांति (Round Revolution)","match":"आलू (Potato)","matchId":"(c)"},{"id":"(4)","label":"गुलाबी क्रांति (Pink Revolution)","match":"झींगा/प्याज (Prawn/Onion/Meat)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('285a2476-d64f-4f11-b7b1-abf9b0aabce2', '67fb41b1-439d-40a1-b9b8-d1f1b4750b66', 'राष्ट्रीय खाद्य सुरक्षा अधिनियम (NFSA) किस वर्ष पारित किया गया था?', '[{"id":"A","text":"2005","text_en":"2005"},{"id":"B","text":"2010","text_en":"2010"},{"id":"C","text":"2013","text_en":"2013"},{"id":"D","text":"2015","text_en":"2015"}]', '2', '**✅ Correct Logic:** NFSA **2013** में पारित किया गया। यह ''भोजन के अधिकार'' को कानूनी अधिकार बनाता है।

**💡 Exam Fact:** यह 75% ग्रामीण और 50% शहरी आबादी को कवर करता है।

**🧠 Memory Tip:** Food for all in **2013**.

**🚫 Scam Alert:** मनरेगा 2005 है, NFSA 2013 है।', 2, 0, 1, NULL, 'In which year was the National Food Security Act (NFSA) passed?', '**✅ Correct Logic:** Passed in **2013**. Makes Right to Food a legal right.

**💡 Exam Fact:** Covers 75% Rural, 50% Urban population.

**🧠 Memory Tip:** Food in **2013**.

**🚫 Scam Alert:** MGNREGA is 2005, NFSA is 2013.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c0f33607-5eb2-40c1-bdd0-c0e47700de88', '67fb41b1-439d-40a1-b9b8-d1f1b4750b66', 'NFSA 2013 के तहत, ''अंत्योदय अन्न योजना'' (AAY) परिवारों को प्रति माह कितना अनाज मिलता है?', '[{"id":"A","text":"5 किलो प्रति व्यक्ति (5 kg per person)","text_en":"5 किलो प्रति व्यक्ति (5 kg per person)"},{"id":"B","text":"35 किलो प्रति परिवार (35 kg per household)","text_en":"35 किलो प्रति परिवार (35 kg per household)"},{"id":"C","text":"25 किलो प्रति परिवार (25 kg per household)","text_en":"25 किलो प्रति परिवार (25 kg per household)"},{"id":"D","text":"10 किलो प्रति व्यक्ति (10 kg per person)","text_en":"10 किलो प्रति व्यक्ति (10 kg per person)"}]', '1', '**✅ Correct Logic:** AAY (सबसे गरीब) परिवारों को **35 किलो प्रति परिवार** अनाज मिलता है। जबकि प्राथमिकता वाले परिवारों (PHH) को **5 किलो प्रति व्यक्ति** मिलता है।

**💡 Exam Fact:** हाल ही में ''PM गरीब कल्याण अन्न योजना'' के तहत यह मुफ्त दिया जा रहा है।

**🧠 Memory Tip:** **Antyodaya** gets **All** (Bulk 35kg). Others get per head (5kg).

**🚫 Scam Alert:** 5 किलो सामान्य नियम है, लेकिन ''अंत्योदय'' के लिए फिक्स 35 किलो है।', 2, 0, 2, NULL, 'Under NFSA 2013, how much food grain does an ''Antyodaya Anna Yojana'' (AAY) household get per month?', '**✅ Correct Logic:** AAY (Poorest) gets **35 kg per family**. Priority Households (PHH) get **5 kg per person**.

**💡 Exam Fact:** Now free under PMGKAY.

**🧠 Memory Tip:** AAY gets Bulk (35kg).

**🚫 Scam Alert:** 5kg is for PHH, 35kg is for AAY.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4623a2c0-825b-4f08-b3fe-4606e4e7fdff', '67fb41b1-439d-40a1-b9b8-d1f1b4750b66', 'बफर स्टॉक (Buffer Stock) का रखरखाव कौन सी एजेंसी करती है?', '[{"id":"A","text":"नाबार्ड (NABARD)","text_en":"नाबार्ड (NABARD)"},{"id":"B","text":"भारतीय खाद्य निगम (FCI)","text_en":"भारतीय खाद्य निगम (FCI)"},{"id":"C","text":"कृषि मंत्रालय (Ministry of Agriculture)","text_en":"कृषि मंत्रालय (Ministry of Agriculture)"},{"id":"D","text":"नीति आयोग (NITI Aayog)","text_en":"नीति आयोग (NITI Aayog)"}]', '1', '**✅ Correct Logic:** **भारतीय खाद्य निगम** (FCI) MSP पर अनाज खरीदता है और खाद्य सुरक्षा सुनिश्चित करने के लिए बफर स्टॉक बनाए रखता है।

**💡 Exam Fact:** FCI की स्थापना 1965 में हुई थी।

**🧠 Memory Tip:** **F**ood **C**orporation stores **F**ood.

**🚫 Scam Alert:** नाबार्ड बैंक है, स्टोर नहीं करता। FCI गोदाम चलाता है।', 2, 0, 3, NULL, 'Which agency maintains the Buffer Stock of food grains?', '**✅ Correct Logic:** **Food Corporation of India (FCI)** procures and stores buffer stock.

**💡 Exam Fact:** FCI established in 1965.

**🧠 Memory Tip:** **F**ood **C**orporation stores **F**ood.

**🚫 Scam Alert:** NABARD is a bank. FCI is storage.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ae0060e7-4994-4cff-8a48-e606fa981c76', '67fb41b1-439d-40a1-b9b8-d1f1b4750b66', '''वन नेशन वन राशन कार्ड'' (ONORC) योजना का मुख्य लाभार्थी कौन है?', '[{"id":"A","text":"किसान (Farmers)","text_en":"किसान (Farmers)"},{"id":"B","text":"प्रवासी मजदूर (Migrant Labours)","text_en":"प्रवासी मजदूर (Migrant Labours)"},{"id":"C","text":"सरकारी कर्मचारी (Government Employees)","text_en":"सरकारी कर्मचारी (Government Employees)"},{"id":"D","text":"वरिष्ठ नागरिक (Senior Citizens)","text_en":"वरिष्ठ नागरिक (Senior Citizens)"}]', '1', '**✅ Correct Logic:** ONORC का उद्देश्य **प्रवासी मजदूरों** (Migrants) को देश में कहीं भी (किसी भी राशन दुकान से) अपना हिस्सा लेने की अनुमति देना है।

**💡 Exam Fact:** यह तकनीक आधारित सुधार है (Aadhaar seeding)।

**🧠 Memory Tip:** **Migrant** moves, card moves with him.

**🚫 Scam Alert:** यह सभी के लिए है, लेकिन *मुख्य* लक्ष्य प्रवासी मजदूर थे जो स्थान बदलने पर राशन खो देते थे।', 2, 0, 4, NULL, 'Who is the primary beneficiary of the ''One Nation One Ration Card'' (ONORC) scheme?', '**✅ Correct Logic:** Aimed primarily at **Migrant Labours** so they can claim rations anywhere in India.

**💡 Exam Fact:** Uses Aadhaar seeding.

**🧠 Memory Tip:** **Migrant** moves, card moves.

**🚫 Scam Alert:** Everyone benefits, but migrants were the target issue.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f5fb03c7-88b7-4acc-8a4f-3bcd843b28f2', '67fb41b1-439d-40a1-b9b8-d1f1b4750b66', 'न्यूनतम समर्थन मूल्य (MSP) की सिफारिश कौन करता है?', '[{"id":"A","text":"कृषि मंत्रालय (Ministry of Agriculture)","text_en":"कृषि मंत्रालय (Ministry of Agriculture)"},{"id":"B","text":"CACP (Commission for Agricultural Costs and Prices)","text_en":"CACP (Commission for Agricultural Costs and Prices)"},{"id":"C","text":"FCI","text_en":"FCI"},{"id":"D","text":"नाबार्ड (NABARD)","text_en":"नाबार्ड (NABARD)"}]', '1', '**✅ Correct Logic:** **CACP** (कृषि लागत और मूल्य आयोग) MSP की *सिफारिश* (Recommend) करता है, जबकि सरकार (CCEA) इसे *घोषित* (Announce) करती है।

**💡 Exam Fact:** CACP 22+1 (23) फसलों के लिए सिफारिश करता है।

**🧠 Memory Tip:** **C**ACP **C**alculates cost.

**🚫 Scam Alert:** कृषि मंत्रालय घोषणा करता है, लेकिन गणना/सिफारिश CACP करता है।', 2, 0, 5, NULL, 'Who recommends the Minimum Support Price (MSP)?', '**✅ Correct Logic:** **CACP** *Recommends* MSP. Govt (CCEA) *Announces* it.

**💡 Exam Fact:** Covers 23 crops.

**🧠 Memory Tip:** **C**ACP **C**alculates.

**🚫 Scam Alert:** Ministry announces, CACP recommends.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dfbded9e-6d35-4151-90f2-2099b743ebc1', '67fb41b1-439d-40a1-b9b8-d1f1b4750b66', 'मिड-डे मील (Mid-Day Meal) योजना, जिसे अब ''पीएम पोषण'' (PM Poshan) कहा जाता है, किस वर्ष शुरू की गई थी?', '[{"id":"A","text":"1990","text_en":"1990"},{"id":"B","text":"1995","text_en":"1995"},{"id":"C","text":"2000","text_en":"2000"},{"id":"D","text":"2004","text_en":"2004"}]', '1', '**✅ Correct Logic:** यह 15 अगस्त **1995** को शुरू की गई थी। इसका उद्देश्य नामांकन बढ़ाना और पोषण स्तर में सुधार करना है।

**💡 Exam Fact:** तमिलनाडु इसे लागू करने वाला पहला राज्य था।

**🧠 Memory Tip:** Eat meal at **9** to **5** (1995).

**🚫 Scam Alert:** 2001 में सुप्रीम कोर्ट ने इसे अनिवार्य किया, लेकिन शुरुआत 1995 में हुई।', 2, 0, 6, NULL, 'Mid-Day Meal Scheme, now called ''PM Poshan'', was launched in which year?', '**✅ Correct Logic:** Launched on Aug 15, **1995**. Aim: Enrollment + Nutrition.

**💡 Exam Fact:** TN was first state.

**🧠 Memory Tip:** Eat at **9**-**5**.

**🚫 Scam Alert:** SC mandate in 2001, Launch in 1995.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('304fe562-b394-4884-8452-892afd260bde', '67fb41b1-439d-40a1-b9b8-d1f1b4750b66', 'सार्वजनिक वितरण प्रणाली (PDS) को ''लक्षित'' (Targeted PDS - TPDS) कब बनाया गया?', '[{"id":"A","text":"1992","text_en":"1992"},{"id":"B","text":"1997","text_en":"1997"},{"id":"C","text":"2000","text_en":"2000"},{"id":"D","text":"2013","text_en":"2013"}]', '1', '**✅ Correct Logic:** **1997** में TPDS शुरू किया गया, जिसने आबादी को BPL (गरीबी रेखा से नीचे) और APL (गरीबी रेखा से ऊपर) में विभाजित किया और गरीबों को सब्सिडी दी। उससे पहले PDS सबके लिए समान (Universal) था।

**💡 Exam Fact:** 2000 में अंत्योदय आया।

**🧠 Memory Tip:** **Target** set in **97**.

**🚫 Scam Alert:** 1992 में RPDS (Revamped) था, 1997 में TPDS (Targeted) आया।', 2, 0, 7, NULL, 'When was the Public Distribution System (PDS) made ''Targeted'' (TPDS)?', '**✅ Correct Logic:** TPDS launched in **1997**. Divided population into BPL and APL. Before that, PDS was Universal.

**💡 Exam Fact:** Antyodaya came in 2000.

**🧠 Memory Tip:** **Target** in **97**.

**🚫 Scam Alert:** 1992 was RPDS, 1997 was TPDS.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b0b99a37-dffb-46b3-92ba-828d013e804c', '67fb41b1-439d-40a1-b9b8-d1f1b4750b66', 'खाद्य सुरक्षा में ''फोर्टिफिकेशन'' (Fortification) का क्या अर्थ है?', '[{"id":"A","text":"भोजन की मात्रा बढ़ाना (Increasing quantity of food)","text_en":"भोजन की मात्रा बढ़ाना (Increasing quantity of food)"},{"id":"B","text":"भोजन में आवश्यक सूक्ष्म पोषक तत्व मिलाना (Adding essential micro-nutrients to food)","text_en":"भोजन में आवश्यक सूक्ष्म पोषक तत्व मिलाना (Adding essential micro-nutrients to food)"},{"id":"C","text":"भोजन की शेल्फ लाइफ बढ़ाना (Increasing shelf life)","text_en":"भोजन की शेल्फ लाइफ बढ़ाना (Increasing shelf life)"},{"id":"D","text":"जैविक खेती करना (Organic farming)","text_en":"जैविक खेती करना (Organic farming)"}]', '1', '**✅ Correct Logic:** फोर्टिफिकेशन का अर्थ है भोजन (जैसे चावल, नमक, दूध) में **विटामिन और खनिज** (Iron, Folic Acid, B12) जानबूझकर मिलाना ताकि कुपोषण से लड़ा जा सके।

**💡 Exam Fact:** ''गोल्डन राइस'' (Vit A) एक उदाहरण है।

**🧠 Memory Tip:** **Fort**ify means to make **Strong** (add nutrients).

**🚫 Scam Alert:** यह मात्रा नहीं, गुणवत्ता (Quality/Nutrients) बढ़ाने के लिए है।', 2, 0, 8, NULL, 'What does ''Fortification'' mean in Food Security?', '**✅ Correct Logic:** Adding **essential micro-nutrients** (Vitamins/Minerals) to food to fight malnutrition.

**💡 Exam Fact:** Golden Rice (Vit A).

**🧠 Memory Tip:** **Fort**ify = Make **Strong**.

**🚫 Scam Alert:** Not quantity, but Quality.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('09e27973-bf90-4466-934b-e15a521f29e9', '67fb41b1-439d-40a1-b9b8-d1f1b4750b66', 'निम्नलिखित में से कौन ''खाद्य उपलब्धता'' (Food Availability) का घटक नहीं है, बल्कि ''खाद्य पहुँच'' (Food Accessibility) का है?', '[{"id":"A","text":"घरेलू उत्पादन (Domestic Production)","text_en":"घरेलू उत्पादन (Domestic Production)"},{"id":"B","text":"आयात (Imports)","text_en":"आयात (Imports)"},{"id":"C","text":"क्रय शक्ति (Purchasing Power)","text_en":"क्रय शक्ति (Purchasing Power)"},{"id":"D","text":"बफर स्टॉक (Buffer Stock)","text_en":"बफर स्टॉक (Buffer Stock)"}]', '2', '**✅ Correct Logic:** उत्पादन, आयात और स्टॉक ''उपलब्धता'' (बाजार में खाना है या नहीं) तय करते हैं। **क्रय शक्ति** (Purchasing Power) यह तय करती है कि क्या व्यक्ति उस खाने को **खरीद** (Access) सकता है। यह ''पहुँच'' (Accessibility/Affordability) का हिस्सा है।

**💡 Exam Fact:** खाद्य सुरक्षा के 3 स्तंभ: Availability, Accessibility, Absorption.

**🧠 Memory Tip:** Can I **buy** it? = Access.

**🚫 Scam Alert:** बहुत सूक्ष्म अंतर है। उपलब्ध होना काफी नहीं, जेब में पैसा (Access) भी होना चाहिए।', 2, 0, 9, NULL, 'Which of the following is NOT a component of ''Food Availability'' but of ''Food Accessibility''?', '**✅ Correct Logic:** Production, Imports, Stock = Availability. **Purchasing Power** = Can I buy it? (Accessibility/Affordability).

**💡 Exam Fact:** 3 Pillars: Availability, Accessibility, Absorption.

**🧠 Memory Tip:** Can I **buy** it? = Access.

**🚫 Scam Alert:** Availability vs Accessibility.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('19d0c332-252e-49f1-acce-13b2dc2d91ec', '67fb41b1-439d-40a1-b9b8-d1f1b4750b66', 'निम्नलिखित योजनाओं को उनके प्रारंभ वर्ष से सुमेलित करें (Match the following schemes with launch year):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **MDM**: 1995 (पोषण)। -> (1)-(a)
* **AAY**: 2000 (दिसंबर, वाजपेयी जी के समय)। -> (2)-(b)
* **NFSM**: 2007 (गेहूं/चावल/दाल उत्पादन बढ़ाने के लिए)। -> (3)-(c)
* **NFSA**: 2013 (कानूनी अधिकार)। -> (4)-(d)

**💡 Exam Fact:** NFSM और NFSA में अंतर है। मिशन (2007) उत्पादन के लिए था, एक्ट (2013) वितरण के लिए है।

**🧠 Memory Tip:** 95 Meal -> 2000 Antyodaya -> 07 Mission -> 13 Act.

**🚫 Scam Alert:** NFSM (2007) और NFSA (2013) को मिक्स मत करना।', 2, 0, 10, NULL, 'Match the following schemes with launch year:', '**✅ Correct Matching:**
* **MDM**: 1995. -> (1)-(a)
* **AAY**: 2000. -> (2)-(b)
* **NFSM**: 2007 (Mission for production). -> (3)-(c)
* **NFSA**: 2013 (Act for distribution). -> (4)-(d)

**💡 Exam Fact:** NFSM (2007) vs NFSA (2013).

**🧠 Memory Tip:** Chronology: Meal -> Antyodaya -> Mission -> Act.

**🚫 Scam Alert:** Don''t mix Mission (2007) and Act (2013).', 60, 'matching', '[{"id":"(1)","label":"मिड-डे मील (MDM)","match":"1995","matchId":"(a)"},{"id":"(2)","label":"अंत्योदय अन्न योजना (AAY)","match":"2000","matchId":"(b)"},{"id":"(3)","label":"राष्ट्रीय खाद्य सुरक्षा मिशन (NFSM)","match":"2007","matchId":"(c)"},{"id":"(4)","label":"राष्ट्रीय खाद्य सुरक्षा अधिनियम (NFSA)","match":"2013","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8edb5557-5ff8-46a3-86c7-1f0db4524ad6', 'f0bb896b-25a9-4cd1-a5d8-dec0b12e6dbc', 'मध्य प्रदेश की जलवायु को ''मानसूनी जलवायु'' के रूप में वर्गीकृत किया गया है। यहाँ सर्वाधिक वर्षा किस मानसून शाखा से प्राप्त होती है?', '[{"id":"A","text":"बंगाल की खाड़ी शाखा","text_en":"बंगाल की खाड़ी शाखा"},{"id":"B","text":"अरब सागर शाखा","text_en":"अरब सागर शाखा"},{"id":"C","text":"दोनों शाखाओं से लगभग समान","text_en":"दोनों शाखाओं से लगभग समान"},{"id":"D","text":"पश्चिमी विक्षोभ","text_en":"पश्चिमी विक्षोभ"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश में मानसून की दोनों शाखाओं से वर्षा होती है, लेकिन बंगाल की खाड़ी शाखा से राज्य के पूर्वी और मध्य भाग में सर्वाधिक वर्षा प्राप्त होती है।
💡 **Exam Fact**: राज्य के दक्षिण-पश्चिम भाग में अरब सागर शाखा का प्रभाव अधिक रहता है।
🧠 **Memory Tip**: East-East (Eastern MP gets more rain from the East side branch, i.e., Bay of Bengal).
🚫 **Scam Alert**: अरब सागर शाखा पहले पहुँचती है, लेकिन कुल वर्षा का बड़ा हिस्सा बंगाल की खाड़ी शाखा से आता है।', 2, 0, 1, NULL, 'The climate of MP is classified as ''Monsoon Climate''. From which monsoon branch does it receive maximum rainfall?', '✅ **Correct Logic**: MP receives rainfall from both branches of the monsoon, but the Bay of Bengal branch contributes the maximum amount, especially to the Eastern and Central regions.
💡 **Exam Fact**: The South-Western part of the state is more influenced by the Arabian Sea branch.
🧠 **Memory Tip**: East-East (Eastern MP gets more rain from the East side branch, i.e., Bay of Bengal).
🚫 **Scam Alert**: While the Arabian Sea branch hits first, the majority of volume comes from the Bay of Bengal branch.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9e672837-7c78-4e53-ac91-160fea34fea7', 'f0bb896b-25a9-4cd1-a5d8-dec0b12e6dbc', 'मध्य प्रदेश में ''मावठ'' (Mawath) का संबंध किस ऋतु और घटना से है?', '[{"id":"A","text":"ग्रीष्म ऋतु में चलने वाली लू","text_en":"ग्रीष्म ऋतु में चलने वाली लू"},{"id":"B","text":"वर्षा ऋतु की पहली बारिश","text_en":"वर्षा ऋतु की पहली बारिश"},{"id":"C","text":"शीत ऋतु में पश्चिमी विक्षोभ से होने वाली वर्षा","text_en":"शीत ऋतु में पश्चिमी विक्षोभ से होने वाली वर्षा"},{"id":"D","text":"मानसून के लौटने की प्रक्रिया","text_en":"मानसून के लौटने की प्रक्रिया"}]', '2', '✅ **Correct Logic**: शीत ऋतु (दिसंबर-जनवरी) में पश्चिमी विक्षोभ (Western Disturbances) के कारण होने वाली हल्की वर्षा को ''मावठ'' कहा जाता है।
💡 **Exam Fact**: यह वर्षा रबी की फसलों, विशेषकर गेहूँ के लिए ''अमृत'' समान मानी जाती है।
🧠 **Memory Tip**: M for Mawath, M for Mediterranean (Origin of Western Disturbances).
🚫 **Scam Alert**: ''लू'' ग्रीष्म ऋतु की गर्म हवा है, इसे मावठ से न जोड़ें।', 2, 0, 2, NULL, 'With which season and phenomenon is ''Mawath'' associated in Madhya Pradesh?', '✅ **Correct Logic**: Light rainfall during the winter season (Dec-Jan) caused by Western Disturbances is locally called ''Mawath''.
💡 **Exam Fact**: This rain is considered highly beneficial (''nectar'') for Rabi crops, especially wheat.
🧠 **Memory Tip**: M for Mawath, M for Mediterranean (where these winds originate).
🚫 **Scam Alert**: ''Loo'' is the hot wind of summer; don''t confuse it with Mawath.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6cb776d3-a51c-4a93-8bbf-9b5bea36ea8c', 'f0bb896b-25a9-4cd1-a5d8-dec0b12e6dbc', 'मध्य प्रदेश का ''औसत तापमान'' उत्तर से दक्षिण की ओर जाने पर किस प्रकार परिवर्तित होता है?', '[{"id":"A","text":"तापमान बढ़ता है","text_en":"तापमान बढ़ता है"},{"id":"B","text":"तापमान घटता है","text_en":"तापमान घटता है"},{"id":"C","text":"तापमान स्थिर रहता है","text_en":"तापमान स्थिर रहता है"},{"id":"D","text":"पहले घटता है फिर बढ़ता है","text_en":"पहले घटता है फिर बढ़ता है"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश के उत्तरी भाग (ग्वालियर, भिंड) में गर्मी अधिक होती है, जबकि दक्षिण की ओर जाने पर ऊँचाई और वनों के कारण औसत तापमान में कमी आती है।
💡 **Exam Fact**: मई माह में सबसे अधिक तापमान ग्वालियर और खजुराहो में दर्ज किया जाता है।
🧠 **Memory Tip**: North is close to the desert (Rajasthan) = Hotter.
🚫 **Scam Alert**: वर्षा दक्षिण-पूर्व में अधिक होती है, तापमान उत्तर में अधिक होता है।', 2, 0, 3, NULL, 'How does the ''Average Temperature'' of MP change as one moves from North to South?', '✅ **Correct Logic**: The northern part of MP (Gwalior, Bhind) experiences extreme heat, whereas moving Southwards, the average temperature decreases due to forest cover and elevation.
💡 **Exam Fact**: The highest temperatures in May are typically recorded in Gwalior and Khajuraho.
🧠 **Memory Tip**: North is closer to the dry Rajasthan region = Hotter.
🚫 **Scam Alert**: Rainfall is higher in the South-East, but temperature peaks in the North.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('722a74b0-c1db-4c09-b2a8-c45cf0526706', 'f0bb896b-25a9-4cd1-a5d8-dec0b12e6dbc', 'मध्य प्रदेश में ''सबसे कम वर्षा'' वाला स्थान कौन सा है?', '[{"id":"A","text":"बड़वानी","text_en":"बड़वानी"},{"id":"B","text":"भिंड (गोहद)","text_en":"भिंड (गोहद)"},{"id":"C","text":"श्योपुर","text_en":"श्योपुर"},{"id":"D","text":"झाबुआ","text_en":"झाबुआ"}]', '1', '✅ **Correct Logic**: भिंड जिले का गोहद तहसील मध्य प्रदेश का सबसे कम वर्षा वाला स्थान है (मात्र 55 सेमी)।
💡 **Exam Fact**: सर्वाधिक वर्षा वाला स्थान पचमढ़ी (199 सेमी) है।
🧠 **Memory Tip**: Bhind - Bind (Dryness bound).
🚫 **Scam Alert**: बड़वानी सूखा क्षेत्र है, पर आधिकारिक रिकॉर्ड में गोहद सबसे कम है।', 2, 0, 4, NULL, 'Which is the place with the ''Lowest Rainfall'' in Madhya Pradesh?', '✅ **Correct Logic**: Gohad tehsil in Bhind district records the lowest rainfall in MP (approx 55 cm).
💡 **Exam Fact**: The highest rainfall is recorded at Pachmarhi (approx 199 cm).
🧠 **Memory Tip**: Bhind - Bind (Bound to be dry).
🚫 **Scam Alert**: Barwani is a dry zone, but Gohad holds the record for the minimum.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bd6677c9-0f8d-47fd-8d11-ee9b1b259131', 'f0bb896b-25a9-4cd1-a5d8-dec0b12e6dbc', 'स्थानीय ऋतुओं के नामों को उनके मानक नामों से सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: ग्रीष्म को यूनाला, वर्षा को चौमासा और शीत ऋतु को सियाला कहा जाता है। सितंबर-अक्टूबर के उमस भरे मौसम को ''द्वितीय ग्रीष्म'' या अक्टूबर हीट कहते हैं।
💡 **Exam Fact**: ये नाम मालवी और बुंदेली बोलियों में बहुत प्रचलित हैं।
🧠 **Memory Tip**: Si-Si-Siyala (Cold shivering sound).
🚫 **Scam Alert**: चौमासा का अर्थ 4 महीने की वर्षा है, इसे केवल खेती से न जोड़ें।', 2, 0, 5, NULL, 'Match the local names of seasons with their standard names:', '✅ **Correct Logic**: Unala refers to Summer, Chaumasa to Monsoon, and Siyala to Winter. The humid weather of Sept-Oct is termed ''Second Summer'' or October Heat.
💡 **Exam Fact**: These names are very common in Malwi and Bundeli dialects.
🧠 **Memory Tip**: Si-Si-Siyala (Sound of shivering in winter).
🚫 **Scam Alert**: Chaumasa literally means ''four months''; it''s the standard local term for monsoon.', 60, 'matching', '[{"id":"(1)","label":"यूनाला (Unala)","match":"ग्रीष्म ऋतु (Summer)","matchId":"(a)"},{"id":"(2)","label":"चौमासा (Chaumasa)","match":"वर्षा ऋतु (Monsoon)","matchId":"(b)"},{"id":"(3)","label":"सियाला (Siyala)","match":"शीत ऋतु (Winter)","matchId":"(c)"},{"id":"(4)","label":"अक्टूबर हीट (October Heat)","match":"द्वितीय ग्रीष्म ऋतु","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0bf63fd1-5efc-4629-9d58-ad7142abdcaf', 'f0bb896b-25a9-4cd1-a5d8-dec0b12e6dbc', 'मध्य प्रदेश को कितने ''जलवायु क्षेत्रों'' में विभाजित किया गया है?', '[{"id":"A","text":"5","text_en":"5"},{"id":"B","text":"11","text_en":"11"},{"id":"C","text":"7","text_en":"7"},{"id":"D","text":"9","text_en":"9"}]', '0', '✅ **Correct Logic**: मुख्य रूप से मध्य प्रदेश को 5 जलवायु क्षेत्रों में बाँटा गया है: उत्तर का मैदान, मालवा पठार, विंध्य क्षेत्र, नर्मदा घाटी और बघेलखंड पठार।
💡 **Exam Fact**: कृषि के आधार पर (Agro-climatic zones) राज्य को 11 क्षेत्रों में बाँटा गया है।
🧠 **Memory Tip**: Climate-5, Agriculture-11.
🚫 **Scam Alert**: प्रश्न को ध्यान से पढ़ें, जलवायु क्षेत्र (5) और कृषि जलवायु क्षेत्र (11) अलग-अलग हैं।', 2, 0, 6, NULL, 'Into how many ''Climatic Zones'' is Madhya Pradesh divided?', '✅ **Correct Logic**: MP is primarily divided into 5 climatic regions: Northern Plains, Malwa Plateau, Vindhyan Region, Narmada Valley, and Baghelkhand Plateau.
💡 **Exam Fact**: Based on agriculture, the state is divided into 11 Agro-climatic zones.
🧠 **Memory Tip**: Climate-5, Agriculture-11.
🚫 **Scam Alert**: Read carefully: General Climatic zones are 5, while Agro-climatic zones are 11.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('192f7f88-1578-419d-9241-08345b35ad28', 'f0bb896b-25a9-4cd1-a5d8-dec0b12e6dbc', 'ए.आर. सुब्रमण्यम और टी. श्रीमन्नारायण ने मध्य प्रदेश की जलवायु को कितने भागों में वर्गीकृत किया है?', '[{"id":"A","text":"3","text_en":"3"},{"id":"B","text":"4","text_en":"4"},{"id":"C","text":"5","text_en":"5"},{"id":"D","text":"6","text_en":"6"}]', '0', '✅ **Correct Logic**: उन्होंने मध्य प्रदेश की जलवायु को 3 भागों में बाँटा है: अर्द्ध-शुष्क (Semi-arid), गर्म शीतोष्ण (Hot Temperate) और उष्णकटिबंधीय नम एवं शुष्क (Tropical Wet and Dry)।
💡 **Exam Fact**: यह वर्गीकरण तापमान और वर्षा की प्रभावशीलता पर आधारित है।
🧠 **Memory Tip**: A, R, S (Three initials = 3 parts).
🚫 **Scam Alert**: कोपेन का वर्गीकरण अलग है, सुब्रमण्यम का अलग।', 2, 0, 7, NULL, 'Into how many parts did A.R. Subramaniam and T. Shrimannarayana classify the climate of MP?', '✅ **Correct Logic**: They classified MP''s climate into 3 types: Semi-arid, Hot Temperate, and Tropical Wet and Dry.
💡 **Exam Fact**: This classification is based on temperature and precipitation effectiveness.
🧠 **Memory Tip**: A.R.S (3 letters, 3 types).
🚫 **Scam Alert**: Koppen''s classification is different from Subramaniam''s; don''t mix them up.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('298d9dc8-6c57-43bc-b23a-a6b724b66c76', 'f0bb896b-25a9-4cd1-a5d8-dec0b12e6dbc', 'मध्य प्रदेश में ''सर्वाधिक तापमान'' किस माह में दर्ज किया जाता है?', '[{"id":"A","text":"मार्च","text_en":"मार्च"},{"id":"B","text":"अप्रैल","text_en":"अप्रैल"},{"id":"C","text":"मई","text_en":"मई"},{"id":"D","text":"जून","text_en":"जून"}]', '2', '✅ **Correct Logic**: मई माह में सूर्य की स्थिति के कारण मध्य प्रदेश में भीषण गर्मी पड़ती है और इसी माह में अधिकतम तापमान दर्ज होता है।
💡 **Exam Fact**: गंजबासौदा (विदिशा) में ऐतिहासिक रूप से सर्वाधिक तापमान दर्ज किया गया था।
🧠 **Memory Tip**: May = My God, it''s hot!
🚫 **Scam Alert**: जून में मानसून आने के कारण तापमान में थोड़ी गिरावट आने लगती है, इसलिए मई सबसे गर्म है।', 2, 0, 8, NULL, 'In which month is the ''Maximum Temperature'' recorded in Madhya Pradesh?', '✅ **Correct Logic**: Due to the sun''s position, May experiences the peak of summer in MP, recording the highest temperatures.
💡 **Exam Fact**: Historically, Ganj Basoda (Vidisha) has recorded extreme high temperatures.
🧠 **Memory Tip**: May = ''May''hem of heat.
🚫 **Scam Alert**: While June feels humid, May is statistically hotter before the monsoon arrival.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('48371049-c38e-4c3c-b7ff-3b84b977e99a', 'f0bb896b-25a9-4cd1-a5d8-dec0b12e6dbc', 'राज्य में ''दक्षिण-पश्चिम मानसून'' के सक्रिय होने की सामान्य तिथि क्या मानी जाती है?', '[{"id":"A","text":"1 जून","text_en":"1 जून"},{"id":"B","text":"15 जून","text_en":"15 जून"},{"id":"C","text":"1 जुलाई","text_en":"1 जुलाई"},{"id":"D","text":"25 मई","text_en":"25 मई"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश में मानसून सामान्यतः 10 से 15 जून के आसपास केरल से होते हुए पहुँचता है।
💡 **Exam Fact**: मानसून सबसे पहले राज्य के दक्षिणी जिलों (बुरहानपुर, खंडवा) में प्रवेश करता है।
🧠 **Memory Tip**: Halfway through June (15th).
🚫 **Scam Alert**: 1 जून केरल के लिए है, मध्य प्रदेश के लिए 15 जून मानक है।', 2, 0, 9, NULL, 'What is the normal date for the onset of the ''South-West Monsoon'' in the state?', '✅ **Correct Logic**: The monsoon usually reaches MP around 10th to 15th June after its arrival in Kerala.
💡 **Exam Fact**: The monsoon typically enters through the southern districts like Burhanpur and Khandwa.
🧠 **Memory Tip**: Halfway through June (15th).
🚫 **Scam Alert**: June 1st is the date for Kerala; for MP, the standard date is June 15th.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e5055491-67b6-4f49-8882-dda014b24499', 'f0bb896b-25a9-4cd1-a5d8-dec0b12e6dbc', 'मालवा के पठार की जलवायु के बारे में फाह्यान (चीनी यात्री) ने क्या कहा था?', '[{"id":"A","text":"अत्यंत गर्म","text_en":"अत्यंत गर्म"},{"id":"B","text":"विश्व की सर्वश्रेष्ठ जलवायु","text_en":"विश्व की सर्वश्रेष्ठ जलवायु"},{"id":"C","text":"अत्यंत ठंडी","text_en":"अत्यंत ठंडी"},{"id":"D","text":"अस्थिर जलवायु","text_en":"अस्थिर जलवायु"}]', '1', '✅ **Correct Logic**: फाह्यान ने मालवा की जलवायु को ''विश्व की सर्वश्रेष्ठ जलवायु'' (Best climate in the world) कहा था क्योंकि यहाँ न अधिक गर्मी पड़ती है न अधिक ठंड।
💡 **Exam Fact**: मालवा की जलवायु ''समशीतोष्ण'' (Moderate) है।
🧠 **Memory Tip**: Malwa-Marvelous (M-M).
🚫 **Scam Alert**: फाह्यान ने यह बात चंद्रगुप्त द्वितीय के समय कही थी।', 2, 0, 10, NULL, 'What did Fa-Hien (Chinese traveler) say about the climate of the Malwa Plateau?', '✅ **Correct Logic**: Fa-Hien described Malwa''s climate as the ''Best in the world'' because it is moderate—neither too hot nor too cold.
💡 **Exam Fact**: The climate of Malwa is termed ''Equable'' or ''Moderate''.
🧠 **Memory Tip**: Malwa-Marvelous (M-M).
🚫 **Scam Alert**: This observation was made during his visit during the reign of Chandragupta II.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('511b5f57-7df5-4e89-a9e8-a166332edea3', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'प्राचीन भारतीय मंदिर वास्तुकला में ''पंचायतन'' (Panchayatana) शैली का क्या अर्थ है?', '[{"id":"A","text":"पांच मंजिलों वाला मंदिर (Temple with five storeys)","text_en":"पांच मंजिलों वाला मंदिर (Temple with five storeys)"},{"id":"B","text":"पांच धातुओं से बना मंदिर (Temple made of five metals)","text_en":"पांच धातुओं से बना मंदिर (Temple made of five metals)"},{"id":"C","text":"मुख्य मंदिर चार सहायक मंदिरों से घिरा हो (Main temple surrounded by four subsidiary shrines)","text_en":"मुख्य मंदिर चार सहायक मंदिरों से घिरा हो (Main temple surrounded by four subsidiary shrines)"},{"id":"D","text":"पांच दिशाओं में खुलने वाला द्वार (Gate opening in five directions)","text_en":"पांच दिशाओं में खुलने वाला द्वार (Gate opening in five directions)"}]', '2', '**✅ Correct Logic**: पंचायतन शैली में एक मुख्य मंदिर केंद्रीय ऊंचे चबूतरे पर होता है और उसके चारों कोनों पर चार छोटे सहायक मंदिर (Subsidiary Shrines) होते हैं।

**💡 Exam Fact**: खजुराहो का ''लक्ष्मण मंदिर'' और देवगढ़ का ''दशावतार मंदिर'' पंचायतन शैली के श्रेष्ठ उदाहरण हैं।

**🧠 Memory Tip**: Pancha (5) = 1 Main + 4 Corners.

**🚫 Scam Alert**: इसे मंदिर की मंजिलों (Storeys) से न जोड़ें, यह मंदिर के विन्यास (Layout) की बात करता है।', 2, 0, 1, NULL, 'What is the meaning of ''Panchayatana'' style in ancient Indian temple architecture?', '**✅ Correct Logic**: In Panchayatana style, the main shrine is on a central raised platform, with four smaller subsidiary shrines at the corners.

**💡 Exam Fact**: ''Lakshmana Temple'' at Khajuraho and ''Dashavatara Temple'' at Deogarh are classic examples.

**🧠 Memory Tip**: Pancha (5) = 1 Main + 4 Corners.

**🚫 Scam Alert**: Do not confuse it with storeys; it refers to the layout arrangement.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b4f2ee5a-8d8b-4145-82fb-00f285ca7a22', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'गांधार कला शैली (Gandhara School of Art) को किस अन्य नाम से भी जाना जाता है?', '[{"id":"A","text":"हिंद-यवन शैली (Indo-Greek Style)","text_en":"हिंद-यवन शैली (Indo-Greek Style)"},{"id":"B","text":"शुंग शैली (Shunga Style)","text_en":"शुंग शैली (Shunga Style)"},{"id":"C","text":"द्रविड़ शैली (Dravida Style)","text_en":"द्रविड़ शैली (Dravida Style)"},{"id":"D","text":"गुप्ता-कुषाण शैली (Gupta-Kushan Style)","text_en":"गुप्ता-कुषाण शैली (Gupta-Kushan Style)"}]', '0', '**✅ Correct Logic**: गांधार कला में भारतीय विषयों (बुद्ध) को यूनानी (Greek) तकनीक और शैली में ढाला गया था, इसलिए इसे हिंद-यवन (Indo-Greek) या ग्रीको-बुद्धिस्ट कला कहा जाता है।

**💡 Exam Fact**: यह कुषाण शासक कनिष्क के संरक्षण में फली-फूली।

**🧠 Memory Tip**: Gandhara = Greece connection (G-G).

**🚫 Scam Alert**: मथुरा कला पूर्णतः स्वदेशी थी, जबकि गांधार विदेशी प्रभाव वाली थी।', 2, 0, 2, NULL, 'By what other name is the Gandhara School of Art known?', '**✅ Correct Logic**: Gandhara art combined Indian themes (Buddha) with Greek techniques/styles, hence called Indo-Greek or Greco-Buddhist art.

**💡 Exam Fact**: It flourished under the patronage of Kushana ruler Kanishka.

**🧠 Memory Tip**: Gandhara = Greece connection (G-G).

**🚫 Scam Alert**: Mathura art was purely indigenous, while Gandhara had foreign influence.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cbc56fc1-2fd8-4a58-993a-11b1200c1b38', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'अशोक के स्तंभों (Ashokan Pillars) में प्रयुक्त पत्थर मुख्य रूप से कहाँ से लाए गए थे?', '[{"id":"A","text":"ग्वालियर (Gwalior)","text_en":"ग्वालियर (Gwalior)"},{"id":"B","text":"चुनार (Chunar)","text_en":"चुनार (Chunar)"},{"id":"C","text":"अजंता (Ajanta)","text_en":"अजंता (Ajanta)"},{"id":"D","text":"धौली (Dhauli)","text_en":"धौली (Dhauli)"}]', '1', '**✅ Correct Logic**: मौर्य कालीन स्तंभों के लिए बलुआ पत्थर (Sandstone) मिर्जापुर के पास ''चुनार'' की खदानों से मंगाया जाता था। इनकी विशिष्ट चमक (Polish) आज भी वैज्ञानिकों के लिए शोध का विषय है।

**💡 Exam Fact**: इन स्तंभों को ''एकाश्मक'' (Monolithic) कहा जाता है क्योंकि ये एक ही पत्थर से तराशे गए हैं।

**🧠 Memory Tip**: Ashoka''s choice was **C**lassy **C**hunar stone.

**🚫 Scam Alert**: धौली में चट्टान काटकर हाथी बनाया गया है, लेकिन स्तंभों का पत्थर चुनार का है।', 2, 0, 3, NULL, 'The stones used in Ashokan Pillars were primarily brought from which place?', '**✅ Correct Logic**: Sandstone for Mauryan pillars was sourced from ''Chunar'' quarries near Mirzapur. Their unique polish is still a subject of research.

**💡 Exam Fact**: These pillars are ''Monolithic'' as they are carved from a single stone block.

**🧠 Memory Tip**: Ashoka''s choice was **C**lassy **C**hunar stone.

**🚫 Scam Alert**: Dhauli has a rock-cut elephant, but pillars specifically used Chunar stone.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fcde8e51-8080-45c5-83e6-b6300a5c9983', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'कथन (A): गुप्त काल को भारतीय वास्तुकला का ''स्वर्ण युग'' माना जाता है।
कारण (R): इसी काल में हिंदू मंदिरों की संरचना (जैसे शिखर और गर्भगृह) का निश्चित रूप विकसित हुआ।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic**: गुप्त काल से पहले मंदिर लकड़ी या मिट्टी के होते थे। पत्थरों से बने मंदिरों की शुरुआत और गर्भगृह जैसी संकल्पनाओं का पूर्ण विकास गुप्त काल में हुआ, इसलिए इसे स्वर्ण युग कहते हैं।

**💡 Exam Fact**: झाँसी का ''देवगढ़ मंदिर'' प्रथम शिखर वाला मंदिर माना जाता है।

**🧠 Memory Tip**: Gupta = Group of structural changes (Temples).

**🚫 Scam Alert**: मौर्य काल में गुफाएं और स्तंभ प्रमुख थे, मंदिरों का शिखर गुप्त काल में आया।', 2, 0, 4, NULL, 'Assertion (A): The Gupta period is considered the ''Golden Age'' of Indian architecture.
Reason (R): The definitive form of Hindu temples (like Shikhara and Garbhagriha) evolved during this period.
Select the correct option:', '**✅ Correct Logic**: Before Gupta era, temples were made of wood or mud. Stone temple construction and concepts like Garbhagriha fully evolved during this period, making it the Golden Age.

**💡 Exam Fact**: ''Deogarh Temple'' is considered the first temple with a Shikhara.

**🧠 Memory Tip**: Gupta = Group of structural changes (Temples).

**🚫 Scam Alert**: Mauryan era was prominent for caves and pillars; Shikhara appeared in the Gupta era.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9dfce20d-2dcb-4e31-9466-fdd44fb12842', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'प्राचीन स्थापत्य और उनके स्थानों को सुमेलित करें (Match the ancient architecture with their locations):', '[{"id":"A","text":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)","text_en":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"}]', '0', '**✅ Correct Logic**: 
* **ग्रेट बाथ**: हड़प्पा सभ्यता की इंजीनियरिंग का नमूना।
* **सांची**: म.प्र. के रायसेन में अशोक द्वारा निर्मित।
* **रथ मंदिर**: पल्लव वास्तुकला (मोनोलिथिक)।
* **तिगवा**: गुप्त कालीन विष्णु मंदिर।

**💡 Exam Fact**: सांची स्तूप को 1989 में यूनेस्को द्वारा विश्व धरोहर घोषित किया गया।

**🧠 Memory Tip**: Sanchi = MP Pride. Bath = Water city (Mohenjo).

**🚫 Scam Alert**: सांची विदिशा के पास है लेकिन जिला रायसेन लगता है।', 2, 0, 5, NULL, 'Match the ancient architecture with their locations:', '**✅ Correct Logic**: 
* **Great Bath**: Engineering marvel of Indus Valley.
* **Sanchi**: Built by Ashoka in Raisen, MP.
* **Ratha Temples**: Pallava architecture (Monolithic).
* **Tigawa**: Gupta era Vishnu temple.

**💡 Exam Fact**: Sanchi Stupa was declared a UNESCO World Heritage site in 1989.

**🧠 Memory Tip**: Sanchi = MP Pride. Bath = Water city (Mohenjo).

**🚫 Scam Alert**: Sanchi is near Vidisha but officially in Raisen district.', 60, 'matching', '[{"id":"(1)","label":"विशाल स्नानागार (Great Bath)","match":"मोहनजोदड़ो (Mohenjodaro)","matchId":"(c)"},{"id":"(2)","label":"सांची स्तूप (Sanchi Stupa)","match":"रायसेन (Raisen)","matchId":"(a)"},{"id":"(3)","label":"रथ मंदिर (Ratha Temples)","match":"महाबलीपुरम (Mahabalipuram)","matchId":"(d)"},{"id":"(4)","label":"तिगवा मंदिर (Tigawa Temple)","match":"जबलपुर (Jabalpur)","matchId":"(b)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2c298ce8-d13c-41b6-9782-d3f46141a9e9', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'एलोरा की गुफाओं में स्थित प्रसिद्ध ''कैलाश मंदिर'' (Kailash Temple) का निर्माण किस राजवंश ने करवाया था?', '[{"id":"A","text":"पल्लव (Pallava)","text_en":"पल्लव (Pallava)"},{"id":"B","text":"चोल (Chola)","text_en":"चोल (Chola)"},{"id":"C","text":"राष्ट्रकूट (Rashtrakuta)","text_en":"राष्ट्रकूट (Rashtrakuta)"},{"id":"D","text":"चालुक्य (Chalukya)","text_en":"चालुक्य (Chalukya)"}]', '2', '**✅ Correct Logic**: राष्ट्रकूट राजा ''कृष्ण प्रथम'' ने 8वीं शताब्दी में इसे बनवाया था। यह एक ही विशाल चट्टान को ऊपर से नीचे काटकर (Top-down) बनाया गया दुनिया का सबसे बड़ा मोनोलिथिक ढांचा है।

**💡 Exam Fact**: एलोरा में कुल 34 गुफाएं हैं (हिंदू, बौद्ध, जैन)।

**🧠 Memory Tip**: **R**ashtrakuta = **R**ock-cut masterpiece.

**🚫 Scam Alert**: कांची का कैलाशनाथ मंदिर पल्लवों ने बनवाया, लेकिन ''एलोरा'' वाला राष्ट्रकूटों ने।', 2, 0, 6, NULL, 'Which dynasty built the famous ''Kailash Temple'' in the Ellora Caves?', '**✅ Correct Logic**: Rashtrakuta King ''Krishna I'' built it in the 8th century. It is the world''s largest monolithic structure carved top-down from a single rock.

**💡 Exam Fact**: There are 34 caves at Ellora (Hindu, Buddhist, Jain).

**🧠 Memory Tip**: **R**ashtrakuta = **R**ock-cut masterpiece.

**🚫 Scam Alert**: The Kailasanatha temple at Kanchi was built by Pallavas, but the one at ''Ellora'' is Rashtrakuta.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b00b851f-5c8b-4fb9-bb07-3c47301c17f0', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'मथुरा कला शैली (Mathura School of Art) में मुख्य रूप से किस सामग्री का उपयोग किया गया था?', '[{"id":"A","text":"धूसर बलुआ पत्थर (Grey Sandstone)","text_en":"धूसर बलुआ पत्थर (Grey Sandstone)"},{"id":"B","text":"लाल चित्तीदार बलुआ पत्थर (Red Spotted Sandstone)","text_en":"लाल चित्तीदार बलुआ पत्थर (Red Spotted Sandstone)"},{"id":"C","text":"सफेद संगमरमर (White Marble)","text_en":"सफेद संगमरमर (White Marble)"},{"id":"D","text":"कांस्य (Bronze)","text_en":"कांस्य (Bronze)"}]', '1', '**✅ Correct Logic**: मथुरा शैली की मूर्तियों की पहचान ही ''लाल चित्तीदार बलुआ पत्थर'' है। इसमें हिंदू, बौद्ध और जैन तीनों धर्मों की मूर्तियां बनीं।

**💡 Exam Fact**: बुद्ध की पहली मानव रूपी मूर्ति संभवतः मथुरा कला में ही बनी थी।

**🧠 Memory Tip**: Mathura = Mehendi/Red stone.

**🚫 Scam Alert**: धूसर (Grey) पत्थर गांधार शैली की विशेषता है।', 2, 0, 7, NULL, 'Which material was primarily used in the Mathura School of Art?', '**✅ Correct Logic**: The hallmark of Mathura style is ''Red Spotted Sandstone''. It produced icons for Hinduism, Buddhism, and Jainism.

**💡 Exam Fact**: The first anthropomorphic image of Buddha was likely created in the Mathura school.

**🧠 Memory Tip**: Mathura = Mehendi/Red stone.

**🚫 Scam Alert**: Grey stone is the characteristic feature of the Gandhara style.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7225bfa7-16d3-44f6-a21f-9b3fa1efc95e', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'स्तूप वास्तुकला में ''हर्मिका'' (Harmika) क्या दर्शाती है?', '[{"id":"A","text":"प्रवेश द्वार (Entrance Gate)","text_en":"प्रवेश द्वार (Entrance Gate)"},{"id":"B","text":"देवताओं का निवास स्थान (Abode of the Gods)","text_en":"देवताओं का निवास स्थान (Abode of the Gods)"},{"id":"C","text":"भिक्षुओं के रहने की जगह (Living area for monks)","text_en":"भिक्षुओं के रहने की जगह (Living area for monks)"},{"id":"D","text":"परिक्रमा पथ (Circumambulatory path)","text_en":"परिक्रमा पथ (Circumambulatory path)"}]', '1', '**✅ Correct Logic**: स्तूप के गुंबद (Anda) के ऊपर एक चौकोर रेलिंग जैसी संरचना होती है जिसे ''हर्मिका'' कहते हैं। इसे देवताओं का पवित्र निवास माना जाता है।

**💡 Exam Fact**: हर्मिका के बीच से ''यष्टि'' (Mast) निकलती है जिस पर छत्र होते हैं।

**🧠 Memory Tip**: Harmika = High home for Gods.

**🚫 Scam Alert**: ''तोरण'' प्रवेश द्वार को कहते हैं, हर्मिका को नहीं।', 2, 0, 8, NULL, 'What does the ''Harmika'' represent in Stupa architecture?', '**✅ Correct Logic**: Harmika is a square railing-like structure on top of the dome (Anda) of a Stupa. It is considered the sacred abode of the Gods.

**💡 Exam Fact**: A mast called ''Yashti'' rises from the Harmika, supporting the umbrellas (Chhatra).

**🧠 Memory Tip**: Harmika = High home for Gods.

**🚫 Scam Alert**: ''Torana'' refers to the gateway, not the Harmika.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('76064565-a8cc-43bf-9db2-88fa918ed80e', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'गुप्त कालीन मंदिर ''भीतरगाँव मंदिर'' (Bhitargaon Temple) की क्या विशेषता है?', '[{"id":"A","text":"यह लोहे से बना है (It is made of iron)","text_en":"यह लोहे से बना है (It is made of iron)"},{"id":"B","text":"यह पूर्णतः ईंटों से निर्मित है (It is entirely built of bricks)","text_en":"यह पूर्णतः ईंटों से निर्मित है (It is entirely built of bricks)"},{"id":"C","text":"इसमें कोई शिखर नहीं है (It has no Shikhara)","text_en":"इसमें कोई शिखर नहीं है (It has no Shikhara)"},{"id":"D","text":"यह एक गुफा मंदिर है (It is a cave temple)","text_en":"यह एक गुफा मंदिर है (It is a cave temple)"}]', '1', '**✅ Correct Logic**: कानपुर (UP) में स्थित भीतरगाँव मंदिर प्राचीनतम जीवित ''ईंटों का मंदिर'' (Brick Temple) है। यह गुप्त काल की उन्नत निर्माण तकनीक को दर्शाता है।

**💡 Exam Fact**: सिरपुर का ''लक्ष्मण मंदिर'' (म.प्र./छत्तीसगढ़) भी ईंटों से बना प्रसिद्ध मंदिर है।

**🧠 Memory Tip**: Bhitar (Inside) -> Bricks (Mitti se bana).

**🚫 Scam Alert**: गुप्त काल के अधिकांश मंदिर पत्थर के थे (जैसे तिगवा), भीतरगाँव अपवाद है।', 2, 0, 9, NULL, 'What is unique about the Gupta era ''Bhitargaon Temple''?', '**✅ Correct Logic**: Located in Kanpur (UP), Bhitargaon is the oldest surviving ''Brick Temple''. It showcases the advanced construction techniques of the Gupta era.

**💡 Exam Fact**: The Lakshmana Temple at Sirpur (CG) is another famous brick temple from the same era.

**🧠 Memory Tip**: Bhitar (Inside) -> Bricks (Mitti se bana).

**🚫 Scam Alert**: While most Gupta temples were stone (like Tigawa), Bhitargaon is a rare brick exception.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9cc31127-d2b0-4cab-9dba-d585b284e3a0', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'दार्शनिक आधार पर ''शिल्प शास्त्र'' (Shilpa Shastra) का मुख्य उद्देश्य क्या था?', '[{"id":"A","text":"केवल सजावट (Only decoration)","text_en":"केवल सजावट (Only decoration)"},{"id":"B","text":"कला के माध्यम से मोक्ष और दिव्य अनुभूति (Moksha and divine experience through art)","text_en":"कला के माध्यम से मोक्ष और दिव्य अनुभूति (Moksha and divine experience through art)"},{"id":"C","text":"पैसे कमाना (Earning money)","text_en":"पैसे कमाना (Earning money)"},{"id":"D","text":"राजा की प्रशंसा करना (Praising the King)","text_en":"राजा की प्रशंसा करना (Praising the King)"}]', '1', '**✅ Correct Logic**: भारतीय परंपरा में शिल्प (Art/Craft) केवल भौतिक निर्माण नहीं है। यह ''योग'' की तरह है जहाँ कलाकार ध्यान के माध्यम से दिव्य रूप को पत्थर या रंग में उतारता है। इसका लक्ष्य दर्शक को आध्यात्मिक शांति देना है।

**💡 Exam Fact**: ''मानसोर'' और ''मयामतम'' शिल्प शास्त्र के महत्वपूर्ण ग्रंथ हैं।

**🧠 Memory Tip**: Shilpa = Spiritual creation.

**🚫 Scam Alert**: यह केवल तकनीकी गाइड नहीं थी, बल्कि सौंदर्यबोध (Aesthetics) का दर्शन था।', 2, 0, 10, NULL, 'Philosophically, what was the primary objective of ''Shilpa Shastra''?', '**✅ Correct Logic**: In Indian tradition, Shilpa is not just material construction. It is like Yoga, where the artist visualizes the divine through meditation to carve it. The goal is to provide spiritual bliss to the viewer.

**💡 Exam Fact**: ''Manasara'' and ''Mayamatam'' are key texts of Shilpa Shastra.

**🧠 Memory Tip**: Shilpa = Spiritual creation.

**🚫 Scam Alert**: It wasn''t just a technical manual; it was a philosophy of aesthetics.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dc85b375-c3e3-4f45-923c-1d9c501d0cf6', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मध्य प्रदेश के सर्वाधिक भू-भाग पर कौन सी मिट्टी पाई जाती है?', '[{"id":"A","text":"जलोढ़ मिट्टी (Alluvial Soil)","text_en":"जलोढ़ मिट्टी (Alluvial Soil)"},{"id":"B","text":"काली मिट्टी (Black Soil)","text_en":"काली मिट्टी (Black Soil)"},{"id":"C","text":"लाल-पीली मिट्टी (Red-Yellow Soil)","text_en":"लाल-पीली मिट्टी (Red-Yellow Soil)"},{"id":"D","text":"मिश्रित मिट्टी (Mixed Soil)","text_en":"मिश्रित मिट्टी (Mixed Soil)"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश के लगभग 47% भाग पर काली मिट्टी पाई जाती है। यह मालवा पठार और नर्मदा घाटी में विस्तृत है।
💡 **Exam Fact**: काली मिट्टी का निर्माण दक्कन ट्रैप की बेसाल्ट चट्टानों के क्षरण से हुआ है।
🧠 **Memory Tip**: MP = More Petrol (Black Gold) -> Black Soil is maximum.
🚫 **Scam Alert**: भारत में जलोढ़ मिट्टी सर्वाधिक है, लेकिन मध्य प्रदेश के विशिष्ट संदर्भ में काली मिट्टी प्रथम है।', 2, 0, 1, NULL, 'Which soil is found over the maximum geographical area of Madhya Pradesh?', '✅ **Correct Logic**: Black soil covers approximately 47% of MP''s area, predominantly in the Malwa Plateau and Narmada Valley.
💡 **Exam Fact**: It is formed by the weathering of basaltic rocks of the Deccan Trap.
🧠 **Memory Tip**: MP = More Petroleum (Black) -> Black Soil is most abundant.
🚫 **Scam Alert**: Alluvial soil is most common in India, but in MP, Black soil takes the lead.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7edb6798-2705-4b5f-b5e0-7d8b9c84c31a', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'काली मिट्टी का रंग काला होने का मुख्य कारण क्या है?', '[{"id":"A","text":"फेरिक ऑक्साइड की उपस्थिति","text_en":"फेरिक ऑक्साइड की उपस्थिति"},{"id":"B","text":"टिटेनीफेरस मैग्नेटाइट की उपस्थिति","text_en":"टिटेनीफेरस मैग्नेटाइट की उपस्थिति"},{"id":"C","text":"ह्यूमस की अधिकता","text_en":"ह्यूमस की अधिकता"},{"id":"D","text":"चूने की प्रचुरता","text_en":"चूने की प्रचुरता"}]', '1', '✅ **Correct Logic**: काली मिट्टी में टिटेनीफेरस मैग्नेटाइट और जीवांश (ह्यूमस) की उपस्थिति के कारण इसका रंग काला होता है।
💡 **Exam Fact**: इसे ''रेगुर'' (Regur) या ''कपासी मिट्टी'' भी कहा जाता है।
🧠 **Memory Tip**: Titan (Magnetite) is strong and dark.
🚫 **Scam Alert**: फेरिक ऑक्साइड के कारण मिट्टी का रंग लाल होता है, काला नहीं।', 2, 0, 2, NULL, 'What is the primary reason for the black color of Black Soil?', '✅ **Correct Logic**: The presence of Titaniferous Magnetite and humus gives this soil its black color.
💡 **Exam Fact**: It is also known as ''Regur'' or ''Cotton Soil''.
🧠 **Memory Tip**: Titan is a dark, strong metal (Visual cue for color).
🚫 **Scam Alert**: Ferric oxide causes red color in soil, not black.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4c5f2f11-6d8f-477a-b732-708bbd08a31f', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मध्य प्रदेश के किस क्षेत्र में ''जलोढ़ मिट्टी'' (Alluvial Soil) का विस्तार पाया जाता है?', '[{"id":"A","text":"नर्मदा घाटी","text_en":"नर्मदा घाटी"},{"id":"B","text":"बघेलखंड पठार","text_en":"बघेलखंड पठार"},{"id":"C","text":"मध्य भारत का पठार (चंबल क्षेत्र)","text_en":"मध्य भारत का पठार (चंबल क्षेत्र)"},{"id":"D","text":"सतपुड़ा श्रेणी","text_en":"सतपुड़ा श्रेणी"}]', '2', '✅ **Correct Logic**: जलोढ़ मिट्टी मुख्य रूप से उत्तरी मध्य प्रदेश (भिंड, मुरैना, ग्वालियर, शिवपुरी) में चंबल और उसकी सहायक नदियों द्वारा लाई गई गाद से बनी है।
💡 **Exam Fact**: यह सर्वाधिक उपजाऊ मिट्टी है लेकिन इसमें नाइट्रोजन की कमी होती है।
🧠 **Memory Tip**: Alluvial - A (At the Top of MP map).
🚫 **Scam Alert**: जलोढ़ मिट्टी चंबल क्षेत्र में ''मृदा अपरदन'' (Soil Erosion) की समस्या से गंभीर रूप से ग्रसित है।', 2, 0, 3, NULL, 'In which region of Madhya Pradesh is the expansion of ''Alluvial Soil'' found?', '✅ **Correct Logic**: Alluvial soil is mainly found in Northern MP (Chambal region) formed by deposits of rivers.
💡 **Exam Fact**: It is the most fertile soil but deficient in nitrogen.
🧠 **Memory Tip**: Alluvial - ''A'' is at the top (North) of the alphabet and the MP map.
🚫 **Scam Alert**: This soil in the Chambal region suffers severely from gully erosion.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('75752b1f-195b-4cac-96b0-982e2acb398a', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मिट्टी के ''अपरदन'' (Erosion) को किस नाम से जाना जाता है जिसे ''किसानों की मृत्यु'' भी कहा जाता है?', '[{"id":"A","text":"रेंगती हुई मृत्यु (Creeping Death)","text_en":"रेंगती हुई मृत्यु (Creeping Death)"},{"id":"B","text":"वायु अपरदन","text_en":"वायु अपरदन"},{"id":"C","text":"परत अपरदन","text_en":"परत अपरदन"},{"id":"D","text":"अवनालिका अपरदन","text_en":"अवनालिका अपरदन"}]', '0', '✅ **Correct Logic**: मृदा अपरदन को ''रेंगती हुई मृत्यु'' (Creeping Death) कहा जाता है क्योंकि यह धीरे-धीरे मिट्टी की उर्वरता को नष्ट कर देता है।
💡 **Exam Fact**: मुरैना जिला अवनालिका अपरदन (Gully Erosion) से सर्वाधिक प्रभावित है।
🧠 **Memory Tip**: Erosion creeps away the land slowly.
🚫 **Scam Alert**: अवनालिका अपरदन एक प्रकार है, लेकिन उपमा ''रेंगती हुई मृत्यु'' पूरे अपरदन के लिए उपयोग होती है।', 2, 0, 4, NULL, 'By what name is ''Soil Erosion'' known, also referred to as the ''Death of Farmers''?', '✅ **Correct Logic**: Soil erosion is termed ''Creeping Death'' because it slowly depletes soil nutrients and productivity.
💡 **Exam Fact**: Morena district is the most affected by Gully Erosion.
🧠 **Memory Tip**: Erosion creeps away the land, just like a slow disease.
🚫 **Scam Alert**: Gully erosion is a specific type, but the metaphor ''Creeping Death'' applies to the broader phenomenon.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('da0310c9-0b4d-41f2-841f-3feb5460502d', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मिट्टी के प्रकार और उनके मुख्य क्षेत्रों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: लाल-पीली मिट्टी बघेलखंड (पूर्वी MP) में, गहरी काली नर्मदा घाटी में, जलोढ़ मध्य भारत में और लैटराइट छिंदवाड़ा-बालाघाट के कुछ हिस्सों में पाई जाती है।
💡 **Exam Fact**: लैटराइट मिट्टी चाय और कॉफी की खेती के लिए उपयुक्त होती है।
🧠 **Memory Tip**: Red-Yellow = Rice area (Eastern MP).
🚫 **Scam Alert**: साधारण काली मिट्टी मालवा में है, ''गहरी'' काली मुख्य रूप से नर्मदा घाटी में है।', 2, 0, 5, NULL, 'Match the soil types with their primary regions:', '✅ **Correct Logic**: Red-yellow soil is in Baghelkhand (East), Deep black in Narmada valley, Alluvial in Central India, and Laterite in parts of Balaghat/Chhindwara.
💡 **Exam Fact**: Laterite soil is suitable for tea and coffee plantations.
🧠 **Memory Tip**: Red-Yellow corresponds to the Rice-growing East.
🚫 **Scam Alert**: Simple black soil is in Malwa; ''Deep'' black is primarily in the Narmada Valley.', 60, 'matching', '[{"id":"(1)","label":"लाल-पीली मिट्टी","match":"बघेलखंड","matchId":"(a)"},{"id":"(2)","label":"गहरी काली मिट्टी","match":"नर्मदा घाटी","matchId":"(b)"},{"id":"(3)","label":"जलोढ़ मिट्टी","match":"मध्य भारत","matchId":"(c)"},{"id":"(4)","label":"लैटराइट मिट्टी","match":"बालाघाट/छिंदवाड़ा","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3d1737b4-c088-4049-b2a3-024f4556d2c5', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मध्य प्रदेश में ''लाल-पीली'' मिट्टी का पीला रंग किसके कारण होता है?', '[{"id":"A","text":"लोहे के ऑक्सीकरण (Oxidation) से","text_en":"लोहे के ऑक्सीकरण (Oxidation) से"},{"id":"B","text":"फेरिक ऑक्साइड के जलयोजन (Hydration) से","text_en":"फेरिक ऑक्साइड के जलयोजन (Hydration) से"},{"id":"C","text":"मैग्नीशियम की प्रचुरता से","text_en":"मैग्नीशियम की प्रचुरता से"},{"id":"D","text":"फास्फोरस की कमी से","text_en":"फास्फोरस की कमी से"}]', '1', '✅ **Correct Logic**: लोहे के ऑक्सीकरण से मिट्टी लाल होती है, लेकिन जब इसमें जल का संयोजन (Hydration) होता है (फेरिक ऑक्साइड), तो यह पीली दिखाई देती है।
💡 **Exam Fact**: यह मिट्टी धान (Rice) की खेती के लिए सर्वोत्तम मानी जाती है।
🧠 **Memory Tip**: Yellow = Hydrated (Watery yellow).
🚫 **Scam Alert**: नाइट्रोजन और ह्यूमस की कमी लगभग सभी भारतीय मिट्टियों में पाई जाती है, यह रंग का कारण नहीं है।', 2, 0, 6, NULL, 'What causes the yellow color in ''Red-Yellow'' soil in Madhya Pradesh?', '✅ **Correct Logic**: Red color is due to oxidation of iron, but hydration of ferric oxide makes it appear yellow.
💡 **Exam Fact**: This soil is considered best for paddy (rice) cultivation.
🧠 **Memory Tip**: Yellow = Hydrated (Like watery paint).
🚫 **Scam Alert**: Lack of nitrogen is common to most Indian soils; it doesn''t define the color.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('331dc7b4-ac8e-49fe-9ae4-75d533dfcb92', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मध्य प्रदेश की किस मिट्टी में ''स्व-जुताई'' (Self-ploughing) का गुण पाया जाता है?', '[{"id":"A","text":"लाल-पीली मिट्टी","text_en":"लाल-पीली मिट्टी"},{"id":"B","text":"काली मिट्टी","text_en":"काली मिट्टी"},{"id":"C","text":"जलोढ़ मिट्टी","text_en":"जलोढ़ मिट्टी"},{"id":"D","text":"कछारी मिट्टी","text_en":"कछारी मिट्टी"}]', '1', '✅ **Correct Logic**: काली मिट्टी सूखने पर इसमें गहरी दरारें पड़ जाती हैं, जिससे वायु का संचार अंदर तक होता है, इसे ही ''स्व-जुताई'' कहा जाता है।
💡 **Exam Fact**: इसमें जल धारण क्षमता (Water holding capacity) सर्वाधिक होती है।
🧠 **Memory Tip**: Black cracks look like ploughed lines.
🚫 **Scam Alert**: गीली होने पर यह चिपचिपी हो जाती है, तब इसे जोतना कठिन होता है।', 2, 0, 7, NULL, 'Which soil in Madhya Pradesh possesses the quality of ''Self-ploughing''?', '✅ **Correct Logic**: Upon drying, black soil develops deep cracks that allow air circulation, leading to the term ''self-ploughing''.
💡 **Exam Fact**: It has the highest water-holding capacity among all soils.
🧠 **Memory Tip**: Dry black soil cracks look like ready-made ploughed rows.
🚫 **Scam Alert**: When wet, it becomes sticky and very difficult to till.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d858a0dc-8005-4d3f-8cb3-2dc647cd7896', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मालवा पठार पर पाई जाने वाली काली मिट्टी की प्रकृति कैसी होती है?', '[{"id":"A","text":"अम्लीय (Acidic)","text_en":"अम्लीय (Acidic)"},{"id":"B","text":"क्षारीय (Alkaline)","text_en":"क्षारीय (Alkaline)"},{"id":"C","text":"उदासीन (Neutral)","text_en":"उदासीन (Neutral)"},{"id":"D","text":"अत्यंत अम्लीय","text_en":"अत्यंत अम्लीय"}]', '1', '✅ **Correct Logic**: काली मिट्टी की प्रकृति मुख्य रूप से क्षारीय (Alkaline) होती है, इसका pH मान 7.5 से 8.5 के बीच होता है।
💡 **Exam Fact**: जलोढ़ मिट्टी की प्रकृति उदासीन (Neutral) होती है।
🧠 **Memory Tip**: Black - Base (B-B).
🚫 **Scam Alert**: चाय की मिट्टी (लैटराइट) अम्लीय होती है, काली नहीं।', 2, 0, 8, NULL, 'What is the nature (pH value) of the black soil found on the Malwa Plateau?', '✅ **Correct Logic**: Black soil is primarily alkaline in nature, with a pH ranging from 7.5 to 8.5.
💡 **Exam Fact**: Alluvial soil is generally neutral.
🧠 **Memory Tip**: B-B (Black is Basic/Alkaline).
🚫 **Scam Alert**: Laterite soil (for tea) is acidic; black soil is not.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8b99ea32-8abc-4832-988f-7a981172755f', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मिट्टी के संबंध में निम्नलिखित कथनों पर विचार करें:
1. जलोढ़ मिट्टी को ''कछारी मिट्टी'' भी कहा जाता है।
2. काली मिट्टी में फास्फोरस और नाइट्रोजन की प्रचुरता होती है।
3. लैटराइट मिट्टी को स्थानीय स्तर पर ''भाटा'' कहा जाता है।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 3","text_en":"केवल 1 और 3"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '0', '✅ **Correct Logic**: कथन 1 और 3 सही हैं। भारतीय मिट्टियों (काली सहित) में नाइट्रोजन, फास्फोरस और ह्यूमस की कमी होती है, प्रचुरता नहीं।
💡 **Exam Fact**: लैटराइट मिट्टी का विस्तार शिवपुरी, ग्वालियर और बालाघाट के कुछ क्षेत्रों में है।
🧠 **Memory Tip**: L-B (Laterite-Bhata).
🚫 **Scam Alert**: काली मिट्टी में ''चूना'' और ''लोहा'' अधिक होता है, नाइट्रोजन नहीं।', 2, 0, 9, NULL, 'Consider the following statements regarding soil:
1. Alluvial soil is also called ''Kachari soil''.
2. Black soil is rich in phosphorus and nitrogen.
3. Laterite soil is locally known as ''Bhata''.

Choose the correct statement:', '✅ **Correct Logic**: Statements 1 and 3 are correct. Indian soils, including black soil, are deficient in nitrogen, phosphorus, and humus.
💡 **Exam Fact**: Laterite soil is found in parts of Shivpuri, Gwalior, and Balaghat.
🧠 **Memory Tip**: L-B (Laterite-Bhata).
🚫 **Scam Alert**: Black soil is rich in lime and iron, but poor in nitrogen.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('627462ab-2cc2-417c-967a-df0b6ca9d415', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मध्य प्रदेश के किस जिले में मृदा अपरदन (Soil Erosion) के कारण ''बीहड़'' (Ravines) का निर्माण हुआ है?', '[{"id":"A","text":"मुरैना","text_en":"मुरैना"},{"id":"B","text":"भिंड","text_en":"भिंड"},{"id":"C","text":"श्योपुर","text_en":"श्योपुर"},{"id":"D","text":"उपरोक्त सभी","text_en":"उपरोक्त सभी"}]', '3', '✅ **Correct Logic**: चंबल नदी द्वारा किए गए भारी अवनालिका अपरदन के कारण मुरैना, भिंड और श्योपुर जिलों में बीहड़ों का निर्माण हुआ है।
💡 **Exam Fact**: मुरैना जिला इस समस्या से सर्वाधिक प्रभावित है।
🧠 **Memory Tip**: Chambal Belt = Ravine Belt.
🚫 **Scam Alert**: यह अपरदन वर्षा के कारण नहीं बल्कि चंबल नदी के जल के तेज बहाव के कारण होता है।', 2, 0, 10, NULL, 'In which district of MP have ''Ravines'' been formed due to soil erosion?', '✅ **Correct Logic**: Extensive gully erosion by the Chambal river has created ravines in Morena, Bhind, and Sheopur.
💡 **Exam Fact**: Morena district is the epicenter of this problem.
🧠 **Memory Tip**: Chambal Belt = Ravine Belt.
🚫 **Scam Alert**: This erosion is primarily caused by the river''s flow dynamics, not just rainfall runoff.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7d33978a-1495-4e93-86ff-73b977ee0433', '1a4544c3-f262-4d2d-816e-daaf9a6b619e', 'मध्य प्रदेश की ''भारवेली'' (Bharveli) खदान किस खनिज के उत्खनन के लिए विश्व प्रसिद्ध है?', '[{"id":"A","text":"मैंगनीज","text_en":"मैंगनीज"},{"id":"B","text":"तांबा","text_en":"तांबा"},{"id":"C","text":"कोयला","text_en":"कोयला"},{"id":"D","text":"लोहा","text_en":"लोहा"}]', '0', '✅ **Correct Logic**: बालाघाट जिले में स्थित भारवेली खदान एशिया की सबसे बड़ी भूमिगत (Underground) मैंगनीज खदान है।
💡 **Exam Fact**: मध्य प्रदेश मैंगनीज उत्पादन में भारत में प्रथम स्थान पर है।
🧠 **Memory Tip**: Bharveli - Big Manganese (B-M).
🚫 **Scam Alert**: मलाजखंड तांबे के लिए प्रसिद्ध है, भारवेली केवल मैंगनीज के लिए।', 2, 0, 1, NULL, 'The ''Bharveli'' mine of MP is world-famous for the extraction of which mineral?', '✅ **Correct Logic**: Bharveli mine in Balaghat is the largest underground manganese mine in Asia.
💡 **Exam Fact**: Madhya Pradesh ranks first in India in manganese production.
🧠 **Memory Tip**: Bharveli - Big Manganese (B-M).
🚫 **Scam Alert**: Malajkhand is for Copper; Bharveli is exclusively for Manganese.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e79deb5a-b93c-4f57-bdd5-dc2a7e842774', '1a4544c3-f262-4d2d-816e-daaf9a6b619e', 'मध्य प्रदेश का ''मलाजखंड'' (Malajkhand) क्षेत्र किस खनिज का प्रमुख उत्पादक है और इसे किस अन्य नाम से जाना जाता है?', '[{"id":"A","text":"हीरा; हीरा नगरी","text_en":"हीरा; हीरा नगरी"},{"id":"B","text":"तांबा; तांबा नगरी","text_en":"तांबा; तांबा नगरी"},{"id":"C","text":"कोयला; काला सोना","text_en":"कोयला; काला सोना"},{"id":"D","text":"बाक्साइट; एल्युमीनियम हब","text_en":"बाक्साइट; एल्युमीनियम हब"}]', '1', '✅ **Correct Logic**: मलाजखंड (बालाघाट) को भारत की ''तांबा नगरी'' कहा जाता है। यहाँ से देश का लगभग 50% तांबा निकाला जाता है।
💡 **Exam Fact**: यहाँ हिंदुस्तान कॉपर लिमिटेड का संयंत्र स्थित है।
🧠 **Memory Tip**: Malajkhand - Mine of Copper (M-C).
🚫 **Scam Alert**: तांबा उत्पादन में प्रथम है, लेकिन भंडार (Reserves) में राजस्थान के बाद आता है।', 2, 0, 2, NULL, 'Which mineral is primarily produced in the ''Malajkhand'' area of MP and by what other name is it known?', '✅ **Correct Logic**: Malajkhand (Balaghat) is known as the ''Copper City'' of India. It contributes nearly 50% of India''s copper production.
💡 **Exam Fact**: The plant of Hindustan Copper Limited is located here.
🧠 **Memory Tip**: Malajkhand - Mine of Copper (M-C).
🚫 **Scam Alert**: MP ranks first in production, but second in reserves after Rajasthan.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2104fdc8-f777-45a3-bd40-cfe413064ecd', '1a4544c3-f262-4d2d-816e-daaf9a6b619e', 'एशिया की सबसे मोटी ''कोयला परत'' (Coal Seam) मध्य प्रदेश के किस कोयला क्षेत्र में पाई जाती है?', '[{"id":"A","text":"सिंगरौली","text_en":"सिंगरौली"},{"id":"B","text":"सोहागपुर","text_en":"सोहागपुर"},{"id":"C","text":"उमरिया","text_en":"उमरिया"},{"id":"D","text":"कान्हन घाटी","text_en":"कान्हन घाटी"}]', '0', '✅ **Correct Logic**: सिंगरौली कोयला क्षेत्र में 136 मीटर मोटी कोयला परत पाई जाती है, जो एशिया में सबसे मोटी है।
💡 **Exam Fact**: सिंगरौली को मध्य प्रदेश की ''ऊर्जा राजधानी'' (Energy Capital) कहा जाता है।
🧠 **Memory Tip**: Singrauli - Single Thickest Layer.
🚫 **Scam Alert**: सोहागपुर (शहडोल) क्षेत्रफल की दृष्टि से सबसे बड़ा कोयला क्षेत्र है, लेकिन परत सिंगरौली में मोटी है।', 2, 0, 3, NULL, 'The thickest ''Coal Seam'' in Asia is found in which coalfield of Madhya Pradesh?', '✅ **Correct Logic**: The Singrauli coalfield contains a coal seam 136 meters thick, the thickest in Asia.
💡 **Exam Fact**: Singrauli is known as the ''Energy Capital'' of Madhya Pradesh.
🧠 **Memory Tip**: Singrauli - Single Thickest Layer.
🚫 **Scam Alert**: Sohagpur is the largest by area, but Singrauli has the maximum thickness.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f206d9af-d9b6-4dde-9e35-55b414b72bdb', '1a4544c3-f262-4d2d-816e-daaf9a6b619e', 'मध्य प्रदेश के किस जिले में ''हीरा'' (Diamond) का सर्वाधिक उत्खनन किया जाता है और वहां की प्रमुख खदान कौन सी है?', '[{"id":"A","text":"पन्ना; मझगवां","text_en":"पन्ना; मझगवां"},{"id":"B","text":"सतना; टोंस","text_en":"सतना; टोंस"},{"id":"C","text":"छतरपुर; अंगोर","text_en":"छतरपुर; अंगोर"},{"id":"D","text":"बघेलखंड; सोहागपुर","text_en":"बघेलखंड; सोहागपुर"}]', '0', '✅ **Correct Logic**: पन्ना जिले की ''मझगवां'' खदान हीरा उत्पादन का मुख्य केंद्र है। यह किम्बरलाइट पाइप से संबंधित है।
💡 **Exam Fact**: मध्य प्रदेश हीरा उत्पादन में भारत का एकमात्र और प्रथम राज्य है।
🧠 **Memory Tip**: Panna - Majhgawan (P-M).
🚫 **Scam Alert**: सतना के ''हिनौता'' में भी हीरा मिलता है, लेकिन मझगवां सबसे बड़ी खदान है।', 2, 0, 4, NULL, 'In which district of MP is ''Diamond'' primarily mined and which is the major mine there?', '✅ **Correct Logic**: The ''Majhgawan'' mine in Panna district is the primary hub for diamond production, associated with Kimberlite pipes.
💡 **Exam Fact**: MP is the sole and leading diamond-producing state in India.
🧠 **Memory Tip**: Panna - Majhgawan (P-M).
🚫 **Scam Alert**: While Hinauta in Satna also has diamonds, Majhgawan is the largest mine.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f76657b2-b083-41df-95f9-81124cd3c138', '1a4544c3-f262-4d2d-816e-daaf9a6b619e', 'खनिज और उनके प्रमुख उत्पादक क्षेत्रों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: टंगस्टन आगरगाँव में, कोरन्डम सीधी में, ग्रेफाइट बैतूल में और रॉक फास्फेट झाबुआ में पाया जाता है।
💡 **Exam Fact**: टंगस्टन का अयस्क ''वुल्फ्रामाइट'' (Wolframite) है।
🧠 **Memory Tip**: Graphite - Betul (G-B).
🚫 **Scam Alert**: कोरन्डम हीरा के बाद दूसरा सबसे कठोर खनिज है।', 2, 0, 5, NULL, 'Match the minerals and their primary producing regions:', '✅ **Correct Logic**: Tungsten in Agargaon, Corundum in Sidhi, Graphite in Betul, and Rock Phosphate in Jhabua.
💡 **Exam Fact**: The ore of Tungsten is ''Wolframite''.
🧠 **Memory Tip**: Graphite - Betul (G-B).
🚫 **Scam Alert**: Corundum is the second hardest mineral after diamond.', 60, 'matching', '[{"id":"(1)","label":"टंगस्टन","match":"आगरगाँव (होशंगाबाद)","matchId":"(a)"},{"id":"(2)","label":"कोरन्डम","match":"पिपरिया-परकोटा (सीधी)","matchId":"(b)"},{"id":"(3)","label":"ग्रेफाइट","match":"बैतूल","matchId":"(c)"},{"id":"(4)","label":"रॉक फास्फेट","match":"झाबुआ","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1893a44e-c47c-4ff5-b7c9-bc8b855609d5', '1a4544c3-f262-4d2d-816e-daaf9a6b619e', 'मध्य प्रदेश के ''बुलफ्राम'' (Wolfram) अयस्क से कौन सा खनिज प्राप्त किया जाता है?', '[{"id":"A","text":"लोहा","text_en":"लोहा"},{"id":"B","text":"टंगस्टन","text_en":"टंगस्टन"},{"id":"C","text":"टिन","text_en":"टिन"},{"id":"D","text":"सीसा","text_en":"सीसा"}]', '1', '✅ **Correct Logic**: वुल्फ्राम (टंगस्टन का अयस्क) से टंगस्टन धातु प्राप्त की जाती है। इसका गलनांक बहुत ऊँचा होता है।
💡 **Exam Fact**: इसका उपयोग बल्ब के फिलामेंट बनाने में होता है।
🧠 **Memory Tip**: W-T (Wolfram-Tungsten).
🚫 **Scam Alert**: टिन मध्य प्रदेश में केवल बैतूल में पाया जाता है, लेकिन उसका अयस्क कैसिटेराइट है।', 2, 0, 6, NULL, 'Which mineral is obtained from the ''Wolfram'' ore in Madhya Pradesh?', '✅ **Correct Logic**: Tungsten metal is obtained from Wolframite ore. It has a very high melting point.
💡 **Exam Fact**: It is used to make filaments for electric bulbs.
🧠 **Memory Tip**: W-T (Wolfram-Tungsten).
🚫 **Scam Alert**: Tin is found only in Betul in MP, but its ore is Cassiterite.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c7a95cfe-9e08-484f-8889-690b90507b76', '1a4544c3-f262-4d2d-816e-daaf9a6b619e', 'मध्य प्रदेश खनिज विकास निगम (MP State Mining Corp) की स्थापना कब की गई थी?', '[{"id":"A","text":"19 जनवरी 1962","text_en":"19 जनवरी 1962"},{"id":"B","text":"1 नवंबर 1956","text_en":"1 नवंबर 1956"},{"id":"C","text":"15 अगस्त 1975","text_en":"15 अगस्त 1975"},{"id":"D","text":"10 मई 1980","text_en":"10 मई 1980"}]', '0', '✅ **Correct Logic**: निगम की स्थापना 19 जनवरी 1962 को भोपाल में की गई थी।
💡 **Exam Fact**: मध्य प्रदेश की पहली खनिज नीति 1995 में आई थी।
🧠 **Memory Tip**: 1962 - Indo-China war year, we needed minerals for defense (Trick).
🚫 **Scam Alert**: नवीन खनिज नीति 2010 में आई थी, इसे स्थापना वर्ष से न जोड़ें।', 2, 0, 7, NULL, 'When was the Madhya Pradesh State Mining Corporation established?', '✅ **Correct Logic**: The corporation was established on January 19, 1962, in Bhopal.
💡 **Exam Fact**: The first Mineral Policy of MP came in 1995.
🧠 **Memory Tip**: 1962 - War year, think of mining for defense metals.
🚫 **Scam Alert**: The latest Mineral Policy was introduced in 2010; don''t confuse it with the establishment year.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4e01f440-c92c-42be-b241-470a86f7a664', '1a4544c3-f262-4d2d-816e-daaf9a6b619e', 'देश में ''हीरा'' (Diamond) उत्खनन करने वाली एकमात्र कंपनी ''NMDC'' मध्य प्रदेश के किस स्थान पर सक्रिय है?', '[{"id":"A","text":"मझगवां (पन्ना)","text_en":"मझगवां (पन्ना)"},{"id":"B","text":"हिनौता (सतना)","text_en":"हिनौता (सतना)"},{"id":"C","text":"अंगोर (छतरपुर)","text_en":"अंगोर (छतरपुर)"},{"id":"D","text":"देवभोग","text_en":"देवभोग"}]', '0', '✅ **Correct Logic**: नेशनल मिनरल डेवलपमेंट कॉर्पोरेशन (NMDC) पन्ना जिले के मझगवां में हीरे का उत्खनन कर रहा है।
💡 **Exam Fact**: छतरपुर के ''बंदर प्रोजेक्ट'' (Bunder Project) में रियो टिंटो कंपनी सक्रिय थी।
🧠 **Memory Tip**: NMDC - National - Majhgawan.
🚫 **Scam Alert**: मझगवां खदान किम्बरलाइट पाइप का हिस्सा है, जो ज्वालामुखीय नली होती है।', 2, 0, 8, NULL, 'Where is ''NMDC'', the only diamond mining company in the country, active in Madhya Pradesh?', '✅ **Correct Logic**: NMDC is carrying out diamond mining at Majhgawan in the Panna district.
💡 **Exam Fact**: The Rio Tinto company was active in Chhatarpur''s ''Bunder Project'' earlier.
🧠 **Memory Tip**: NMDC - National - Majhgawan.
🚫 **Scam Alert**: Majhgawan mine is part of a Kimberlite pipe, which is a volcanic conduit.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b8239718-ac57-49ed-b538-0d286e348213', '1a4544c3-f262-4d2d-816e-daaf9a6b619e', 'मध्य प्रदेश का ''स्लेट'' (Slate) उत्पादन में भारत में कौन सा स्थान है और इसका मुख्य उत्पादक जिला कौन सा है?', '[{"id":"A","text":"प्रथम; मंदसौर","text_en":"प्रथम; मंदसौर"},{"id":"B","text":"द्वितीय; ग्वालियर","text_en":"द्वितीय; ग्वालियर"},{"id":"C","text":"तृतीय; जबलपुर","text_en":"तृतीय; जबलपुर"},{"id":"D","text":"प्रथम; नीमच","text_en":"प्रथम; नीमच"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश स्लेट उत्पादन में भारत में प्रथम स्थान पर है और मंदसौर एकमात्र उत्पादक जिला है।
💡 **Exam Fact**: स्लेट एक रूपांतरित चट्टान (Metamorphic rock) है।
🧠 **Memory Tip**: Slate-Mandsaur (S-M).
🚫 **Scam Alert**: नीमच में स्लेट की पट्टियां बनती हैं, पर मुख्य उत्खनन मंदसौर में है।', 2, 0, 9, NULL, 'What is the rank of MP in ''Slate'' production in India and which is the main producing district?', '✅ **Correct Logic**: MP ranks first in India for Slate production, with Mandsaur being the sole producer district.
💡 **Exam Fact**: Slate is a metamorphic rock.
🧠 **Memory Tip**: Slate-Mandsaur (S-M).
🚫 **Scam Alert**: Neemuch makes slate strips, but the primary mining is in Mandsaur.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7d410e9d-9733-4bbb-b77b-9d595079a63e', '1a4544c3-f262-4d2d-816e-daaf9a6b619e', '''सुरमा'' (Antimony) खनिज मध्य प्रदेश के किस जिले में मुख्य रूप से पाया जाता है?', '[{"id":"A","text":"जबलपुर","text_en":"जबलपुर"},{"id":"B","text":"झाबुआ","text_en":"झाबुआ"},{"id":"C","text":"दतिया","text_en":"दतिया"},{"id":"D","text":"भिंड","text_en":"भिंड"}]', '0', '✅ **Correct Logic**: सुरमा या एंटीमनी मध्य प्रदेश के जबलपुर जिले में पाया जाता है।
💡 **Exam Fact**: इसका उपयोग दवाइयों और सौंदर्य प्रसाधनों में किया जाता है।
🧠 **Memory Tip**: Jabalpur - Eye (Surma goes in the eye).
🚫 **Scam Alert**: झाबुआ रॉक फास्फेट और अभ्रक (Mica) के लिए प्रसिद्ध है, सुरमा के लिए नहीं।', 2, 0, 10, NULL, 'The ''Antimony'' mineral is primarily found in which district of Madhya Pradesh?', '✅ **Correct Logic**: Antimony (Surma) is found in the Jabalpur district of MP.
💡 **Exam Fact**: It is used in medicines and cosmetics.
🧠 **Memory Tip**: Jabalpur - Think of applying Surma near Marble Rocks (Visual).
🚫 **Scam Alert**: Jhabua is famous for Rock Phosphate and Mica, not Antimony.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d5925418-6f1e-443a-8561-bfb2103ecc37', '294f2133-8d42-40e0-b395-9357e273bcd8', 'मध्य प्रदेश को लगातार कई वर्षों से ''कृषि कर्मण पुरस्कार'' मिल रहा है। यह मुख्य रूप से किस फसल के सर्वाधिक उत्पादन के लिए प्रसिद्ध है, जिसके कारण इसे ''सोयाबीन राज्य'' भी कहा जाता है?', '[{"id":"A","text":"गेहूँ","text_en":"गेहूँ"},{"id":"B","text":"सोयाबीन","text_en":"सोयाबीन"},{"id":"C","text":"चना","text_en":"चना"},{"id":"D","text":"मक्का","text_en":"मक्का"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश भारत के कुल सोयाबीन उत्पादन का लगभग 50-60% हिस्सा पैदा करता है, इसलिए इसे ''सोया स्टेट'' कहा जाता है।
💡 **Exam Fact**: सोयाबीन का सर्वाधिक उत्पादन मालवा क्षेत्र (उज्जैन, धार) में होता है।
🧠 **Memory Tip**: S for Soy State, S for Seventy percent (almost).
🚫 **Scam Alert**: गेहूँ उत्पादन में मध्य प्रदेश दूसरे स्थान पर आ गया है (पंजाब/UP के बाद), पर सोयाबीन में इसका एकाधिकार रहा है।', 2, 0, 1, NULL, 'MP has been receiving the ''Krishi Karman Award'' for several years. For which crop''s maximum production is it primarily famous, also earning it the title ''Soybean State''?', '✅ **Correct Logic**: MP produces about 50-60% of India''s total soybean, earning it the title ''Soya State''.
💡 **Exam Fact**: Maximum production occurs in the Malwa region (Ujjain, Dhar).
🧠 **Memory Tip**: S for Soy State, S for Strength in Oilseeds.
🚫 **Scam Alert**: While MP is a leader in wheat, its unique identity is linked to Soybean.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6ddcd928-2740-41c6-9dfd-63282c5c7f56', '294f2133-8d42-40e0-b395-9357e273bcd8', 'मध्य प्रदेश के किस जिले को ''मिर्च का कटोरा'' कहा जाता है और जहाँ एशिया की सबसे बड़ी मिर्च मंडी स्थित है?', '[{"id":"A","text":"खरगोन (बेड़िया)","text_en":"खरगोन (बेड़िया)"},{"id":"B","text":"बड़वानी","text_en":"बड़वानी"},{"id":"C","text":"खंडवा","text_en":"खंडवा"},{"id":"D","text":"बुरहानपुर","text_en":"बुरहानपुर"}]', '0', '✅ **Correct Logic**: खरगोन जिले का ''बेड़िया'' (Bediya) क्षेत्र मिर्च उत्पादन के लिए प्रसिद्ध है और यहाँ एशिया की दूसरी बड़ी मंडी है।
💡 **Exam Fact**: निमाड़ क्षेत्र (खरगोन, खंडवा) अपनी लाल मिर्च के लिए विश्व प्रसिद्ध है।
🧠 **Memory Tip**: Khargon - Kharkhara (Spicy/Chilli).
🚫 **Scam Alert**: बुरहानपुर केले के लिए प्रसिद्ध है, मिर्च के लिए खरगोन।', 2, 0, 2, NULL, 'Which district of MP is called the ''Bowl of Chillies'' and houses the largest chilli market in Asia?', '✅ **Correct Logic**: The ''Bediya'' region in Khargone district is famous for chilli production and hosts a massive market.
💡 **Exam Fact**: The Nimar region is globally recognized for its vibrant red chillies.
🧠 **Memory Tip**: Khargone - Think of the ''Kharkharat'' (Spiciness) of chillies.
🚫 **Scam Alert**: Burhanpur is the hub for Bananas, while Khargone is the hub for Chillies.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2d4e8998-c309-4a97-aa51-9c61aec16eb9', '294f2133-8d42-40e0-b395-9357e273bcd8', 'मध्य प्रदेश में ''शरबती गेहूँ'' (Sharbati Wheat) की किस्म मुख्य रूप से किन जिलों में उगाई जाती है, जिसे ''गोल्डन ग्रेन'' भी कहा जाता है?', '[{"id":"A","text":"सीहोर और विदिशा","text_en":"सीहोर और विदिशा"},{"id":"B","text":"भिंड और मुरैना","text_en":"भिंड और मुरैना"},{"id":"C","text":"मंडला और बालाघाट","text_en":"मंडला और बालाघाट"},{"id":"D","text":"इंदौर और उज्जैन","text_en":"इंदौर और उज्जैन"}]', '0', '✅ **Correct Logic**: सीहोर और विदिशा का शरबती गेहूँ अपनी मिठास और चमक के लिए अंतरराष्ट्रीय स्तर पर प्रसिद्ध है।
💡 **Exam Fact**: इसे हाल ही में जीआई टैग (GI Tag) भी प्राप्त हुआ है।
🧠 **Memory Tip**: Sharbati - Sehore (S-S).
🚫 **Scam Alert**: भिंड-मुरैना गेहूँ के लिए नहीं बल्कि सरसों के लिए प्रसिद्ध हैं।', 2, 0, 3, NULL, 'In which districts is the ''Sharbati Wheat'' variety primarily grown in MP, also known as ''Golden Grain''?', '✅ **Correct Logic**: Sharbati wheat from Sehore and Vidisha is internationally famous for its sweetness and texture.
💡 **Exam Fact**: It has recently been granted the GI Tag.
🧠 **Memory Tip**: Sharbati starts with S, so does Sehore.
🚫 **Scam Alert**: Bhind-Morena are mustard hubs, not the primary regions for Sharbati wheat.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f9f9d8a7-7c1e-439a-bba0-5267638330ea', '294f2133-8d42-40e0-b395-9357e273bcd8', 'नूरजहाँ (Noor Jahan) किसकी एक दुर्लभ किस्म है, जो मध्य प्रदेश के अलीराजपुर जिले के ''कट्ठीवाड़ा'' में पाई जाती है?', '[{"id":"A","text":"आम (Mango)","text_en":"आम (Mango)"},{"id":"B","text":"अंगूर","text_en":"अंगूर"},{"id":"C","text":"सतरा","text_en":"सतरा"},{"id":"D","text":"अमरूद","text_en":"अमरूद"}]', '0', '✅ **Correct Logic**: नूरजहाँ आम की एक अत्यंत दुर्लभ और विशाल किस्म है। इसका एक फल कई किलो का हो सकता है।
💡 **Exam Fact**: यह केवल अलीराजपुर के कट्ठीवाड़ा क्षेत्र में पाया जाता है।
🧠 **Memory Tip**: Noor Jahan (Queen) - Mango (King of Fruits).
🚫 **Scam Alert**: सुंदरजा आम रीवा का है, नूरजहाँ अलीराजपुर का।', 2, 0, 4, NULL, 'Noor Jahan is a rare variety of which fruit found in ''Katthiwada'' of Alirajpur district, MP?', '✅ **Correct Logic**: Noor Jahan is a rare and giant variety of Mango. A single fruit can weigh several kilograms.
💡 **Exam Fact**: It is endemic to the Katthiwada region of Alirajpur.
🧠 **Memory Tip**: Think of Noor Jahan as the Queen among the Kings of fruits (Mangoes).
🚫 **Scam Alert**: Sundarja mango belongs to Rewa; Noor Jahan is from Alirajpur.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7ba174b1-76fb-45f5-b72a-5890d89ba9e8', '294f2133-8d42-40e0-b395-9357e273bcd8', 'फसलें और उनके सर्वाधिक उत्पादक जिलों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: सरसों ग्वालियर-चंबल में, चना विदिशा में, कपास निमाड़ में और धान बालाघाट के लाल-पीली मिट्टी वाले क्षेत्र में प्रचुरता से होता है।
💡 **Exam Fact**: मध्य प्रदेश देश के कुल चना उत्पादन में प्रथम स्थान पर है।
🧠 **Memory Tip**: Cotton - White Gold of Nimar.
🚫 **Scam Alert**: मालवा में कपास कम, सोयाबीन अधिक होता है।', 2, 0, 5, NULL, 'Match the crops and their leading producing districts:', '✅ **Correct Logic**: Mustard in Gwalior-Chambal, Gram in Vidisha, Cotton in Nimar, and Paddy in Balaghat''s red-yellow soil region.
💡 **Exam Fact**: MP ranks first in the country for Gram production.
🧠 **Memory Tip**: Cotton is the ''White Gold'' of Nimar.
🚫 **Scam Alert**: Malwa is dominated by Soybean, whereas Nimar is the hub for Cotton.', 60, 'matching', '[{"id":"(1)","label":"सरसों (Mustard)","match":"मुरैना/भिंड","matchId":"(a)"},{"id":"(2)","label":"चना (Gram)","match":"विदिशा","matchId":"(b)"},{"id":"(3)","label":"कपास (Cotton)","match":"खरगोन/खंडवा","matchId":"(c)"},{"id":"(4)","label":"धान (Paddy)","match":"बालाघाट","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ae751fdb-6bc8-4c75-aaf6-5ee3e8b7dfae', '294f2133-8d42-40e0-b395-9357e273bcd8', 'मध्य प्रदेश के किस जिले को ''अफीम'' (Opium) उत्पादन के लिए जाना जाता है?', '[{"id":"A","text":"मंदसौर","text_en":"मंदसौर"},{"id":"B","text":"खंडवा","text_en":"खंडवा"},{"id":"C","text":"बैतूल","text_en":"बैतूल"},{"id":"D","text":"सागर","text_en":"सागर"}]', '0', '✅ **Correct Logic**: मंदसौर मध्य प्रदेश का प्रमुख अफीम उत्पादक जिला है।
💡 **Exam Fact**: अफीम का वानस्पतिक नाम ''पापावर सोमनीफेरम'' (Papaver somniferum) है।
🧠 **Memory Tip**: M-O (Mandsaur-Opium).
🚫 **Scam Alert**: खंडवा ''गाँजा'' उत्पादन के लिए प्रसिद्ध है, अफीम के लिए नहीं।', 2, 0, 6, NULL, 'Which district of MP is known for ''Opium'' production?', '✅ **Correct Logic**: Mandsaur is the primary opium-producing district in MP.
💡 **Exam Fact**: The botanical name of opium is Papaver somniferum.
🧠 **Memory Tip**: M-O (Mandsaur-Opium).
🚫 **Scam Alert**: Khandwa is famous for Ganja (Cannabis), not Opium.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ffab32c4-a9c5-4769-a371-ce866ad70632', '294f2133-8d42-40e0-b395-9357e273bcd8', 'मध्य प्रदेश में ''धान अनुसंधान केंद्र'' कहाँ स्थित है?', '[{"id":"A","text":"बड़वानी","text_en":"बड़वानी"},{"id":"B","text":"बालाघाट","text_en":"बालाघाट"},{"id":"C","text":"जबलपुर","text_en":"जबलपुर"},{"id":"D","text":"रीवा","text_en":"रीवा"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश का धान अनुसंधान केंद्र बड़वानी में स्थित है।
💡 **Exam Fact**: राष्ट्रीय धान अनुसंधान केंद्र कटक (ओडिशा) में है।
🧠 **Memory Tip**: Rice-Badwani (R-B).
🚫 **Scam Alert**: बालाघाट में धान का उत्पादन सर्वाधिक है, लेकिन अनुसंधान केंद्र बड़वानी में है।', 2, 0, 7, NULL, 'Where is the ''Paddy Research Centre'' located in Madhya Pradesh?', '✅ **Correct Logic**: The Paddy Research Centre of MP is located in Barwani.
💡 **Exam Fact**: The National Rice Research Institute is in Cuttack (Odisha).
🧠 **Memory Tip**: Rice-Barwani (R-B).
🚫 **Scam Alert**: While Balaghat leads in production, the research center is in Barwani.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f52c0dcc-a60b-4acd-9bcb-7ecb21c8d77a', '294f2133-8d42-40e0-b395-9357e273bcd8', 'मध्य प्रदेश की किन फसलों को ''सफेद सोना'' (White Gold) कहा जाता है और वे किस क्षेत्र में उगाई जाती हैं?', '[{"id":"A","text":"कपास; निमाड़","text_en":"कपास; निमाड़"},{"id":"B","text":"गेहूँ; मालवा","text_en":"गेहूँ; मालवा"},{"id":"C","text":"सोयाबीन; बुंदेलखंड","text_en":"सोयाबीन; बुंदेलखंड"},{"id":"D","text":"चावल; बघेलखंड","text_en":"चावल; बघेलखंड"}]', '0', '✅ **Correct Logic**: कपास को उसके रंग और आर्थिक महत्व के कारण ''सफेद सोना'' कहा जाता है, जो खंडवा-खरगोन (निमाड़) में अधिक होता है।
💡 **Exam Fact**: इन जिलों को ''सुनहरे जिले'' (Golden Districts) भी कहा जाता है।
🧠 **Memory Tip**: Cotton-White-Gold.
🚫 **Scam Alert**: ''सुनहरा रेशा'' जूट को कहा जाता है, सफेद सोना कपास को।', 2, 0, 8, NULL, 'Which crops are called ''White Gold'' in MP and in which region are they grown?', '✅ **Correct Logic**: Cotton is termed ''White Gold'' due to its color and value, predominantly grown in Khandwa-Khargone (Nimar).
💡 **Exam Fact**: These districts are also known as ''Golden Districts''.
🧠 **Memory Tip**: Cotton-White-Gold.
🚫 **Scam Alert**: ''Golden Fibre'' refers to Jute; ''White Gold'' refers to Cotton.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b0f72372-9fad-4a01-9a10-4d3abf20ff7a', '294f2133-8d42-40e0-b395-9357e273bcd8', 'एशिया का सबसे बड़ा ''सोयाबीन संयंत्र'' मध्य प्रदेश के किस शहर में स्थित है?', '[{"id":"A","text":"उज्जैन","text_en":"उज्जैन"},{"id":"B","text":"इंदौर","text_en":"इंदौर"},{"id":"C","text":"धार","text_en":"धार"},{"id":"D","text":"भोपाल","text_en":"भोपाल"}]', '0', '✅ **Correct Logic**: एशिया का सबसे बड़ा सोयाबीन संयंत्र उज्जैन में स्थित है।
💡 **Exam Fact**: सोयाबीन अनुसंधान केंद्र (National Research Centre for Soybean) इंदौर में स्थित है।
🧠 **Memory Tip**: Plant-Ujjain (P-U).
🚫 **Scam Alert**: संयंत्र और अनुसंधान केंद्र में भ्रमित न हों; संयंत्र उज्जैन में है, केंद्र इंदौर में।', 2, 0, 9, NULL, 'Where is the largest ''Soybean Plant'' in Asia located in Madhya Pradesh?', '✅ **Correct Logic**: Asia''s largest soybean processing plant is located in Ujjain.
💡 **Exam Fact**: The National Research Centre for Soybean is situated in Indore.
🧠 **Memory Tip**: Plant-Ujjain (P-U).
🚫 **Scam Alert**: Don''t confuse the plant with the research center; the plant is in Ujjain, the center is in Indore.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f6384e63-10cc-46cc-bd7c-45df24131a7d', '294f2133-8d42-40e0-b395-9357e273bcd8', 'रीवा जिले के ''सुंदरजा'' (Sundarja) आम को हाल ही में जीआई टैग मिला है। इसकी मुख्य विशेषता क्या है?', '[{"id":"A","text":"यह बिना रेशे वाला आम है","text_en":"यह बिना रेशे वाला आम है"},{"id":"B","text":"यह मधुमेह के रोगियों के लिए भी सुरक्षित माना जाता है","text_en":"यह मधुमेह के रोगियों के लिए भी सुरक्षित माना जाता है"},{"id":"C","text":"इसमें विटामिन-C सर्वाधिक होता है","text_en":"इसमें विटामिन-C सर्वाधिक होता है"},{"id":"D","text":"A और B दोनों","text_en":"A और B दोनों"}]', '3', '✅ **Correct Logic**: सुंदरजा आम अपनी मिठास, सुगंध और रेशे रहित होने के लिए प्रसिद्ध है। कम चीनी सामग्री के कारण इसे मधुमेह के रोगी भी कम मात्रा में खा सकते हैं।
💡 **Exam Fact**: यह मुख्य रूप से रीवा के ''गोविंदगढ़'' क्षेत्र में होता है।
🧠 **Memory Tip**: Sundarja - Sundar (Beautiful) and Sugar-free (relative).
🚫 **Scam Alert**: नूरजहाँ आम अपनी विशालता के लिए जाना जाता है, सुंदरजा अपनी गुणवत्ता और स्वास्थ्य गुणों के लिए।', 2, 0, 10, NULL, 'The ''Sundarja'' mango of Rewa district recently received a GI tag. What is its main feature?', '✅ **Correct Logic**: Sundarja mango is fiber-less and sweet. Due to its unique composition, it is considered relatively safer for diabetic patients compared to other varieties.
💡 **Exam Fact**: It is primarily grown in the Govindgarh region of Rewa.
🧠 **Memory Tip**: Sundarja - S for Sugar-friendly (relatively).
🚫 **Scam Alert**: Noor Jahan is known for its size; Sundarja for its health-friendly quality.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9c07bdb7-49b8-4038-8626-0eb07e7cef22', '33465b70-011e-45d7-92f3-5081351cc436', 'किस प्राचीन अभिलेख में पहली बार ''भारतवर्ष'' (Bharadhavasa) शब्द का स्पष्ट उल्लेख मिलता है?', '[{"id":"A","text":"अशोक का भाब्रू अभिलेख (Ashoka''s Bhabru Edict)","text_en":"अशोक का भाब्रू अभिलेख (Ashoka''s Bhabru Edict)"},{"id":"B","text":"खारवेल का हाथीगुम्फा अभिलेख (Kharavela''s Hathigumpha Inscription)","text_en":"खारवेल का हाथीगुम्फा अभिलेख (Kharavela''s Hathigumpha Inscription)"},{"id":"C","text":"रुद्रदामन का जूनागढ़ अभिलेख (Rudradaman''s Junagadh Inscription)","text_en":"रुद्रदामन का जूनागढ़ अभिलेख (Rudradaman''s Junagadh Inscription)"},{"id":"D","text":"समुद्रगुप्त की प्रयाग प्रशस्ति (Prayag Prashasti of Samudragupta)","text_en":"समुद्रगुप्त की प्रयाग प्रशस्ति (Prayag Prashasti of Samudragupta)"}]', '1', '**✅ Correct Logic**: कलिंग नरेश खारवेल के हाथीगुम्फा अभिलेख (1वीं शताब्दी ई.पू.) में प्राकृत भाषा में ''भरधवस'' (भारतवर्ष) शब्द का उल्लेख है। यह भौगोलिक इकाई के रूप में भारतवर्ष का पहला पुरातात्विक प्रमाण है।

**💡 Exam Fact**: यह अभिलेख उदयगिरि की पहाड़ियों (ओडिशा) में स्थित है।

**🧠 Memory Tip**: **Kharavela** (King) wrote **Bharat** on the **Hathi** (Elephant cave).

**🚫 Scam Alert**: विष्णु पुराण में साहित्यिक उल्लेख है, लेकिन ''अभिलेखीय'' (Inscriptional) साक्ष्य हाथीगुम्फा ही है।', 2, 0, 1, NULL, 'In which ancient inscription is the term ''Bharatvarsha'' (Bharadhavasa) clearly mentioned for the first time?', '**✅ Correct Logic**: The Hathigumpha Inscription of King Kharavela (1st Century BCE) mentions ''Bharadhavasa'' in Prakrit. It is the first archaeological evidence of the term used for a geographical entity.

**💡 Exam Fact**: This inscription is located in Udayagiri Hills (Odisha).

**🧠 Memory Tip**: **Kharavela** (King) wrote **Bharat** on the **Hathi** (Elephant cave).

**🚫 Scam Alert**: Vishnu Purana has literary mention, but for ''Inscriptional'' evidence, Hathigumpha is the only answer.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('930f5cf2-5f30-49f0-9658-041b78f3c325', '33465b70-011e-45d7-92f3-5081351cc436', 'प्राचीन भारतीय भूगोल में ''जम्बुद्वीप'' (Jambudvipa) के अंतर्गत भारत को किस नाम से जाना जाता था?', '[{"id":"A","text":"अजनाभवर्ष (Ajanabhavarsha)","text_en":"अजनाभवर्ष (Ajanabhavarsha)"},{"id":"B","text":"इलावृत्तवर्ष (Ilavritavarsha)","text_en":"इलावृत्तवर्ष (Ilavritavarsha)"},{"id":"C","text":"हिरण्यवर्ष (Hiranyavarsha)","text_en":"हिरण्यवर्ष (Hiranyavarsha)"},{"id":"D","text":"केतुमालवर्ष (Ketumalavarsha)","text_en":"केतुमालवर्ष (Ketumalavarsha)"}]', '0', '**✅ Correct Logic**: पौराणिक भूगोल के अनुसार, राजा नाभि के नाम पर भारत का प्राचीन नाम ''अजनाभवर्ष'' था। बाद में नाभि के पुत्र ''भरत'' के नाम पर यह भारतवर्ष कहलाया।

**💡 Exam Fact**: भागवत पुराण के अनुसार ऋषभदेव के पुत्र भरत के कारण यह नाम पड़ा।

**🧠 Memory Tip**: **A**jana = **A**ncient name before Bharat.

**🚫 Scam Alert**: इलावृत्तवर्ष सुमेरु पर्वत के चारों ओर का मध्य क्षेत्र था, भारत नहीं।', 2, 0, 2, NULL, 'In ancient Indian geography, by what name was India known within ''Jambudvipa''?', '**✅ Correct Logic**: According to Puranic geography, the ancient name of India was ''Ajanabhavarsha'' after King Nabhi. Later, it became Bharatvarsha after his son ''Bharat''.

**💡 Exam Fact**: According to Bhagavat Purana, the name comes from Bharat, the son of Rishabhdeva.

**🧠 Memory Tip**: **A**jana = **A**ncient name before Bharat.

**🚫 Scam Alert**: Ilavritavarsha was the central region around Mount Sumeru, not India.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0b04a512-ff8e-425a-8203-a15cb931b438', '33465b70-011e-45d7-92f3-5081351cc436', 'कथन (A): प्राचीन यूनानियों (Greeks) ने भारत के लिए ''इण्डिया'' (India) शब्द का प्रयोग किया।
कारण (R): वे सिन्धु नदी को ''इण्डोस'' (Indos) कहते थे।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic**: यूनानी लोग सिन्धु नदी के संपर्क में आए और ''स'' का उच्चारण ''ह'' न कर पाने के कारण सिन्धु को ''इण्डोस'' कहा, जिससे देश का नाम ''इण्डिया'' पड़ा।

**💡 Exam Fact**: हेरोडोटस (इतिहास का पिता) ने पहली बार भारत के लिए इंडिया शब्द का प्रयोग किया था।

**🧠 Memory Tip**: Greek = Indos -> India. Persian = Hindu -> Hindustan.

**🚫 Scam Alert**: अक्सर लोग इण्डिया को अंग्रेजों की देन मानते हैं, जबकि यह यूनानियों (Greeks) द्वारा दिया गया प्राचीन नाम है।', 2, 0, 3, NULL, 'Assertion (A): Ancient Greeks used the term ''India'' for the country.
Reason (R): They called the Indus river ''Indos''.
Select the correct option:', '**✅ Correct Logic**: The Greeks encountered the Indus river and called it ''Indos'', which evolved into ''India''.

**💡 Exam Fact**: Herodotus (Father of History) was the first to use the term India for the region.

**🧠 Memory Tip**: Greek = Indos -> India. Persian = Hindu -> Hindustan.

**🚫 Scam Alert**: Many think ''India'' was coined by the British, but it''s an ancient name given by the Greeks.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e04b4cc9-05a8-4638-a4d1-7d3ebff0d720', '33465b70-011e-45d7-92f3-5081351cc436', 'मध्यकाल के दौरान ''हिन्दुस्तान'' शब्द का प्रयोग किन भौगोलिक सीमाओं के लिए किया गया था?', '[{"id":"A","text":"सम्पूर्ण भारतीय उपमहाद्वीप (Entire Indian Subcontinent)","text_en":"सम्पूर्ण भारतीय उपमहाद्वीप (Entire Indian Subcontinent)"},{"id":"B","text":"केवल दक्षिण भारत (Only South India)","text_en":"केवल दक्षिण भारत (Only South India)"},{"id":"C","text":"सिन्धु और गंगा के बीच का क्षेत्र (Region between Indus and Ganges)","text_en":"सिन्धु और गंगा के बीच का क्षेत्र (Region between Indus and Ganges)"},{"id":"D","text":"हिमालय से कन्याकुमारी तक (Himalayas to Kanyakumari)","text_en":"हिमालय से कन्याकुमारी तक (Himalayas to Kanyakumari)"}]', '2', '**✅ Correct Logic**: मिन्हास-ए-सिराज (13वीं सदी) ने ''हिन्दुस्तान'' का प्रयोग पंजाब, हरियाणा और गंगा-यमुना के दोआब क्षेत्र के लिए किया था। यह राजनीतिक रूप से दिल्ली सल्तनत के अधीन क्षेत्रों को दर्शाता था।

**💡 Exam Fact**: बाबर ने हिन्दुस्तान शब्द का प्रयोग उपमहाद्वीप के भूगोल और संस्कृति के लिए किया था।

**🧠 Memory Tip**: Medieval Hindustan = North India focus (Indus-Ganga).

**🚫 Scam Alert**: आज के हिन्दुस्तान और 13वीं सदी के हिन्दुस्तान के भौगोलिक अर्थ में जमीन-आसमान का अंतर है।', 2, 0, 4, NULL, 'During the medieval period, for which geographical boundaries was the term ''Hindustan'' used?', '**✅ Correct Logic**: Minhaj-i-Siraj (13th century) used ''Hindustan'' to describe regions of Punjab, Haryana, and the Ganga-Yamuna doab. It represented areas under the Delhi Sultanate.

**💡 Exam Fact**: Babur used ''Hindustan'' to describe the geography and culture of the subcontinent.

**🧠 Memory Tip**: Medieval Hindustan = North India focus (Indus-Ganga).

**🚫 Scam Alert**: There is a vast difference between the modern meaning of Hindustan and its 13th-century usage.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('28f9f2b1-de5d-4c7d-94a6-a1a1e69f6dd6', '33465b70-011e-45d7-92f3-5081351cc436', 'विदेशी यात्रियों द्वारा भारत के लिए प्रयुक्त नामों को सुमेलित करें (Match the names used for India by foreign travelers):', '[{"id":"A","text":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)","text_en":"(1)-(c), (2)-(a), (3)-(d), (4)-(b)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(b), (2)-(c), (3)-(d), (4)-(a)","text_en":"(1)-(b), (2)-(c), (3)-(d), (4)-(a)"},{"id":"D","text":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)","text_en":"(1)-(d), (2)-(a), (3)-(b), (4)-(c)"}]', '0', '**✅ Correct Logic**: 
* **चीनी**: यिन-तू (चंद्रमा के समान प्रकाशमान)।
* **ईरानी**: सिन्धु को हिन्दू कहा (हकार बहुला भाषा)।
* **यूनानी**: इण्डोस से इण्डिया।
* **मेसोपोटामिया**: हड़प्पा सभ्यता के लिए ''मेलुहा'' शब्द।

**💡 Exam Fact**: पारसियों के धर्मग्रंथ ''जेंद अवेस्ता'' में ''हप्त-हिन्दू'' (सप्त सिन्धु) का उल्लेख है।

**🧠 Memory Tip**: **C**hina = **C**handrama (Yintu). **M**esopotamia = **M**eluha.

**🚫 Scam Alert**: मेलुहा पूरे भारत के लिए नहीं, मुख्य रूप से सिन्धु क्षेत्र के लिए प्रयुक्त था।', 2, 0, 5, NULL, 'Match the names used for India by foreign travelers:', '**✅ Correct Logic**: 
* **Chinese**: Yin-Tu (Radiant like the moon).
* **Iranian**: Called Indus ''Hindu''.
* **Greeks**: Indos to India.
* **Mesopotamians**: ''Meluha'' for the Indus region.

**💡 Exam Fact**: Zend Avesta mentions ''Hapta-Hindu'' (Sapt Sindhu).

**🧠 Memory Tip**: **C**hina = **C**handrama (Yintu). **M**esopotamia = **M**eluha.

**🚫 Scam Alert**: Meluha was primarily for the Indus region, not the entire subcontinent.', 60, 'matching', '[{"id":"(1)","label":"चीनी यात्री (इत्सिंग/ह्वेनसांग)","match":"यिन-तू / तियान-झू (Yin-Tu / Tianzhu)","matchId":"(c)"},{"id":"(2)","label":"ईरानी/फारसी (Darius I)","match":"हिन्दू (Hindu/Hi-du)","matchId":"(a)"},{"id":"(3)","label":"यूनानी (Megasthenes)","match":"इण्डिका / इण्डिया (Indika / India)","matchId":"(d)"},{"id":"(4)","label":"मेसोपोटामियाई (Sumerian)","match":"मेलुहा (Meluha)","matchId":"(b)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3f66d577-ee42-4a7e-a2d6-f61cf72a2fc0', '33465b70-011e-45d7-92f3-5081351cc436', 'मनुस्मृति में ''ब्रह्मावर्त'' (Brahmavarta) क्षेत्र किसे कहा गया है?', '[{"id":"A","text":"गंगा और यमुना के बीच का क्षेत्र","text_en":"गंगा और यमुना के बीच का क्षेत्र"},{"id":"B","text":"सरस्वती और दृषद्वती नदियों के बीच का क्षेत्र","text_en":"सरस्वती और दृषद्वती नदियों के बीच का क्षेत्र"},{"id":"C","text":"हिमालय और विन्ध्याचल के बीच का क्षेत्र","text_en":"हिमालय और विन्ध्याचल के बीच का क्षेत्र"},{"id":"D","text":"सिन्धु नदी के पश्चिम का क्षेत्र","text_en":"सिन्धु नदी के पश्चिम का क्षेत्र"}]', '1', '**✅ Correct Logic**: मनुस्मृति के अनुसार, सरस्वती और दृषद्वती नदियों के बीच का देव-निर्मित देश ''ब्रह्मावर्त'' कहलाता है। इसे भारतीय संस्कृति का हृदय स्थल माना गया है।

**💡 Exam Fact**: गंगा-यमुना दोआब को ''ब्रह्मर्षि देश'' कहा जाता था।

**🧠 Memory Tip**: **B**rahmavarta = **B**etween two holy rivers (S & D).

**🚫 Scam Alert**: आर्यावर्त हिमालय से विन्ध्याचल तक फैला था, जबकि ब्रह्मावर्त उसका एक छोटा पवित्र हिस्सा था।', 2, 0, 6, NULL, 'Which region is called ''Brahmavarta'' in Manusmriti?', '**✅ Correct Logic**: According to Manusmriti, the divine land between the rivers Saraswati and Drishadvati is called ''Brahmavarta''. It is considered the cradle of Indian culture.

**💡 Exam Fact**: The Ganga-Yamuna doab was known as ''Brahmarshidesha''.

**🧠 Memory Tip**: **B**rahmavarta = **B**etween two holy rivers (S & D).

**🚫 Scam Alert**: Aryavarta extended from the Himalayas to the Vindhyas, while Brahmavarta was a smaller sacred part of it.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('115d2e19-2151-438f-bf41-adc7a00fc94a', '33465b70-011e-45d7-92f3-5081351cc436', 'पुराणों में वर्णित ''नवकौमार'' या ''नौ खंड'' (Nine Divisions) की संकल्पना भारतवर्ष के किस संदर्भ में है?', '[{"id":"A","text":"भारत के नौ प्रमुख धर्म","text_en":"भारत के नौ प्रमुख धर्म"},{"id":"B","text":"भारतवर्ष का भौगोलिक विभाजन","text_en":"भारतवर्ष का भौगोलिक विभाजन"},{"id":"C","text":"नौ प्रमुख पर्वत श्रृंखलाएं","text_en":"नौ प्रमुख पर्वत श्रृंखलाएं"},{"id":"D","text":"नौ प्रमुख राजवंश","text_en":"नौ प्रमुख राजवंश"}]', '1', '**✅ Correct Logic**: पुराणों (जैसे मार्कण्डेय पुराण) में भारतवर्ष को नौ खंडों (द्वीपों) में विभाजित किया गया है - इन्द्रद्वीप, कसेरु, ताम्रपर्णी, गभस्तिमान, नागद्वीप, सौम्य, गन्धर्व, वारुण और कुमारी।

**💡 Exam Fact**: ''कुमारी'' द्वीप वह हिस्सा है जहाँ वर्तमान भारत स्थित है।

**🧠 Memory Tip**: Nav (9) Khanda = 9 Maps of India.

**🚫 Scam Alert**: ये 9 द्वीप आधुनिक सात महाद्वीपों से अलग भौगोलिक संकल्पना हैं।', 2, 0, 7, NULL, 'The concept of ''Navakaumara'' or ''Nine Divisions'' mentioned in Puranas is in context of what for Bharatvarsha?', '**✅ Correct Logic**: Puranas (like Markandeya Purana) divide Bharatvarsha into nine divisions (islands) including Indradvipa, Tamraparni, and Kumari.

**💡 Exam Fact**: ''Kumari'' dvipa is the section where modern India is situated.

**🧠 Memory Tip**: Nav (9) Khanda = 9 Maps of India.

**🚫 Scam Alert**: These 9 divisions are a distinct geographical concept, different from modern continents.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8d42c7d6-2c3e-4802-917b-0d2ba6ee926f', '33465b70-011e-45d7-92f3-5081351cc436', 'राजा दुष्यन्त और शकुन्तला के पुत्र ''भरत'' के नाम पर भारत का नामकरण किस महाकाव्य के ''आदिपर्व'' में वर्णित है?', '[{"id":"A","text":"रामायण (Ramayana)","text_en":"रामायण (Ramayana)"},{"id":"B","text":"महाभारत (Mahabharata)","text_en":"महाभारत (Mahabharata)"},{"id":"C","text":"रघुवंश (Raghuvansha)","text_en":"रघुवंश (Raghuvansha)"},{"id":"D","text":"शिशुपाल वध (Shishupala Vadha)","text_en":"शिशुपाल वध (Shishupala Vadha)"}]', '1', '**✅ Correct Logic**: महाभारत के आदिपर्व में महाराज भरत की कथा है। वे एक ''चक्रवर्ती'' सम्राट थे और उन्हीं के पराक्रम के कारण इस देश को ''भारत'' कहा गया।

**💡 Exam Fact**: भरत कुरु वंश के पूर्वज भी थे।

**🧠 Memory Tip**: Mahabharata = Story of **Bharat**''s descendants (Kauravas/Pandavas).

**🚫 Scam Alert**: जैन धर्म प्रथम तीर्थंकर के पुत्र भरत को श्रेय देता है, जबकि हिन्दू परंपरा दुष्यन्त पुत्र भरत को।', 2, 0, 8, NULL, 'The naming of India after ''Bharat'', the son of King Dushyanta and Shakuntala, is described in the ''Adiparva'' of which epic?', '**✅ Correct Logic**: The ''Adiparva'' of Mahabharata contains the story of Emperor Bharat. Due to his valor and universal rule, the land was named ''Bharat''.

**💡 Exam Fact**: Bharat was also an ancestor of the Kuru clan.

**🧠 Memory Tip**: Mahabharata = Story of **Bharat**''s descendants (Kauravas/Pandavas).

**🚫 Scam Alert**: Jainism credits the son of the 1st Tirthankara, while Hindu tradition credits the son of Dushyanta.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('08e8f4c0-95ba-41b3-a5a3-59a24b880005', '33465b70-011e-45d7-92f3-5081351cc436', 'बौद्ध ग्रन्थ ''दीघ निकाय'' में भारत की भौगोलिक आकृति को किस प्रकार वर्णित किया गया है?', '[{"id":"A","text":"धनुषाकार (Bow-shaped)","text_en":"धनुषाकार (Bow-shaped)"},{"id":"B","text":"त्रिभुजाकार (Triangular)","text_en":"त्रिभुजाकार (Triangular)"},{"id":"C","text":"शकट (Chariot) के समान","text_en":"शकट (Chariot) के समान"},{"id":"D","text":"अर्द्ध-चंद्राकार (Half-moon shaped)","text_en":"अर्द्ध-चंद्राकार (Half-moon shaped)"}]', '2', '**✅ Correct Logic**: बौद्ध ग्रंथों में भारत (जम्बुद्वीप) के दक्षिणी भाग को ''शकट'' (गाड़ी या बैलगाड़ी) के आकार का बताया गया है - उत्तर में चौड़ा और दक्षिण में संकरा।

**💡 Exam Fact**: पुराणों में भारत को ''धनुषाकार'' (Bow-shaped) भी कहा गया है।

**🧠 Memory Tip**: Buddha walked miles -> Linked to **Chariot/Cart** (Shakat).

**🚫 Scam Alert**: ''त्रिभुजाकार'' आधुनिक भौगोलिक शब्दावली है, प्राचीन नहीं।', 2, 0, 9, NULL, 'How is the geographical shape of India described in the Buddhist text ''Digha Nikaya''?', '**✅ Correct Logic**: Buddhist texts describe the southern part of Jambudvipa (India) as ''Shakat'' (Chariot/Cart) shaped—broad in the north and narrow in the south.

**💡 Exam Fact**: Puranas also refer to India as ''Bow-shaped''.

**🧠 Memory Tip**: Buddha walked miles -> Linked to **Chariot/Cart** (Shakat).

**🚫 Scam Alert**: ''Triangular'' is modern geographical terminology, not ancient.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ff18d4d4-4f4a-4a56-90a7-cc9bd73de80c', '33465b70-011e-45d7-92f3-5081351cc436', 'प्राचीन भारतीय ''आर्यावर्त'' (Aryavarta) की दक्षिणी सीमा किस पर्वत श्रृंखला को माना जाता था?', '[{"id":"A","text":"हिमालय (Himalayas)","text_en":"हिमालय (Himalayas)"},{"id":"B","text":"विन्ध्याचल (Vindhyas)","text_en":"विन्ध्याचल (Vindhyas)"},{"id":"C","text":"सतपुड़ा (Satpura)","text_en":"सतपुड़ा (Satpura)"},{"id":"D","text":"अरावली (Aravalli)","text_en":"अरावली (Aravalli)"}]', '1', '**✅ Correct Logic**: मनुस्मृति के अनुसार, हिमालय और विन्ध्याचल के बीच के क्षेत्र को ''आर्यावर्त'' कहा जाता था। विन्ध्याचल पर्वत उत्तर और दक्षिण भारत की प्राकृतिक सीमा थी।

**💡 Exam Fact**: दक्षिण भारत को ''दक्षिणापथ'' कहा जाता था।

**🧠 Memory Tip**: **V**indhyas = **V**eins of India dividing North and South.

**🚫 Scam Alert**: सतपुड़ा मध्य प्रदेश में है, लेकिन शास्त्रीय ग्रंथों में सीमा ''विन्ध्य'' को माना गया है।', 2, 0, 10, NULL, 'Which mountain range was considered the southern boundary of ancient Indian ''Aryavarta''?', '**✅ Correct Logic**: According to Manusmriti, the region between the Himalayas and the Vindhyas was called ''Aryavarta''. The Vindhya range served as the natural boundary between North and South India.

**💡 Exam Fact**: South India was referred to as ''Dakshinapatha''.

**🧠 Memory Tip**: **V**indhyas = **V**eins of India dividing North and South.

**🚫 Scam Alert**: Satpura is in MP, but classical texts recognize ''Vindhyas'' as the boundary.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1cb5b778-4729-4a38-8e5a-f6f698275cea', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'मध्य प्रदेश में सिंचाई का सबसे प्रमुख साधन कौन सा है?', '[{"id":"A","text":"नहरें (Canals)","text_en":"नहरें (Canals)"},{"id":"B","text":"कुएँ एवं नलकूप (Wells and Tube-wells)","text_en":"कुएँ एवं नलकूप (Wells and Tube-wells)"},{"id":"C","text":"तालाब (Tanks)","text_en":"तालाब (Tanks)"},{"id":"D","text":"नदियाँ","text_en":"नदियाँ"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश की कुल सिंचित भूमि का लगभग 67-70% हिस्सा कुएँ और नलकूपों द्वारा सिंचित होता है।
💡 **Exam Fact**: मालवा का पठार इस माध्यम से सिंचाई में शीर्ष पर है।
🧠 **Memory Tip**: W-T (Wells and Tube-wells) - Water for Toilers.
🚫 **Scam Alert**: नहरें दूसरा प्रमुख साधन हैं, लेकिन कुएँ और नलकूप प्रथम स्थान पर हैं।', 2, 0, 1, NULL, 'Which is the most prominent source of irrigation in Madhya Pradesh?', '✅ **Correct Logic**: About 67-70% of the irrigated area in MP is covered by wells and tube-wells.
💡 **Exam Fact**: The Malwa plateau leads in irrigation through this source.
🧠 **Memory Tip**: W-T (Wells-Tubewells) - Win the Thirst.
🚫 **Scam Alert**: Canals are the second most important source, but they don''t surpass ground-water sources.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3459cfb7-0723-43ca-a121-72f6f394cef9', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'मध्य प्रदेश की पहली ''जल विद्युत परियोजना'' (Hydro-electric Project) कौन सी है?', '[{"id":"A","text":"गांधी सागर परियोजना","text_en":"गांधी सागर परियोजना"},{"id":"B","text":"बाणसागर परियोजना","text_en":"बाणसागर परियोजना"},{"id":"C","text":"इंदिरा सागर परियोजना","text_en":"इंदिरा सागर परियोजना"},{"id":"D","text":"पेन्च परियोजना","text_en":"पेन्च परियोजना"}]', '0', '✅ **Correct Logic**: चंबल नदी पर स्थित ''गांधी सागर'' (मंदसौर) मध्य प्रदेश की पहली जल विद्युत परियोजना है (1960)।
💡 **Exam Fact**: इसकी कुल स्थापित क्षमता 115 मेगावाट है।
🧠 **Memory Tip**: Gandhi ji led the first movement (First project).
🚫 **Scam Alert**: इंदिरा सागर मध्य प्रदेश की सबसे बड़ी परियोजना है, लेकिन पहली गांधी सागर है।', 2, 0, 2, NULL, 'Which is the first Hydro-electric Project of Madhya Pradesh?', '✅ **Correct Logic**: ''Gandhi Sagar'' (Mandsaur) on the Chambal river is the first hydro-electric project of MP (1960).
💡 **Exam Fact**: It has an installed capacity of 115 MW.
🧠 **Memory Tip**: Gandhi ji led the first national movement; think of him for the first project.
🚫 **Scam Alert**: Indira Sagar is the largest, but Gandhi Sagar is the pioneer.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f70fec00-2cad-4e7c-82ce-a3cedda45f26', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', '''बाणसागर परियोजना'' किन तीन राज्यों की संयुक्त परियोजना है?', '[{"id":"A","text":"MP, UP, Rajasthan","text_en":"MP, UP, Rajasthan"},{"id":"B","text":"MP, UP, Bihar","text_en":"MP, UP, Bihar"},{"id":"C","text":"MP, Maharashtra, Gujarat","text_en":"MP, Maharashtra, Gujarat"},{"id":"D","text":"MP, Chhattisgarh, Odisha","text_en":"MP, Chhattisgarh, Odisha"}]', '1', '✅ **Correct Logic**: बाणसागर परियोजना सोन नदी पर स्थित है और इसमें MP, UP और बिहार का हिस्सा 2:1:1 के अनुपात में है।
💡 **Exam Fact**: इसका मुख्यालय शहडोल जिले के देवलोद में है।
🧠 **Memory Tip**: Son (River) makes M-U-B (MP-UP-Bihar) happy.
🚫 **Scam Alert**: राजस्थान चंबल परियोजना का हिस्सा है, बाणसागर का नहीं।', 2, 0, 3, NULL, '''Bansagar Project'' is a joint project of which three states?', '✅ **Correct Logic**: Bansagar project is on the Son river, shared by MP, UP, and Bihar in a 2:1:1 ratio.
💡 **Exam Fact**: The dam is located in Deolond, Shahdol district.
🧠 **Memory Tip**: Son river flows through M-U-B (MP-UP-Bihar).
🚫 **Scam Alert**: Rajasthan is a partner in the Chambal project, not Bansagar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('963f03b9-4611-41eb-9a19-dfd3f2a8694c', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'नर्मदा नदी पर निर्मित ''इंदिरा सागर बाँध'' की ऊँचाई कितनी है, जो भारत के सबसे ऊँचे बाँधों में से एक है?', '[{"id":"A","text":"92 मीटर","text_en":"92 मीटर"},{"id":"B","text":"121 मीटर","text_en":"121 मीटर"},{"id":"C","text":"74 मीटर","text_en":"74 मीटर"},{"id":"D","text":"86 मीटर","text_en":"86 मीटर"}]', '0', '✅ **Correct Logic**: पुनासा (खंडवा) में स्थित इंदिरा सागर बाँध की ऊँचाई 92 मीटर है।
💡 **Exam Fact**: यह भारत का सबसे बड़ा जलाशय (Reservoir capacity) वाला बाँध है।
🧠 **Memory Tip**: I-92 (Indira 92).
🚫 **Scam Alert**: 121 मीटर सरदार सरोवर (गुजरात) की ऊँचाई है, इंदिरा सागर की नहीं।', 2, 0, 4, NULL, 'What is the height of ''Indira Sagar Dam'' built on the Narmada river?', '✅ **Correct Logic**: The Indira Sagar Dam in Punasa (Khandwa) has a height of 92 meters.
💡 **Exam Fact**: It holds the largest reservoir of water in India by volume.
🧠 **Memory Tip**: I-92 (Indira 92).
🚫 **Scam Alert**: 121 meters is the height of Sardar Sarovar in Gujarat.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6c86c56b-9442-46fc-9b16-0ddc9345bec7', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'परियोजनाओं और उनके उपनामों/संबंधित व्यक्तित्वों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: बेतवा पर रानी लक्ष्मीबाई (माताटीला), वेनगंगा पर संजय सरोवर, पेन्च पर मचागोरा और हलाली को अशोक सागर कहा जाता है।
💡 **Exam Fact**: हलाली परियोजना से विदिशा और रायसेन जिले लाभान्वित होते हैं।
🧠 **Memory Tip**: Matatila-Laxmibai (M-L).
🚫 **Scam Alert**: पगार बाँध (मुरैना) मध्य प्रदेश का सबसे पुराना बाँध (1927) है।', 2, 0, 5, NULL, 'Match projects with their aliases/associated personalities:', '✅ **Correct Logic**: Matatila is Rani Laxmibai, Upper Wainganga is Sanjay Sarovar, Pench is Machagora, and Halali is Samrat Ashok Sagar.
💡 **Exam Fact**: The Halali project benefits Vidisha and Raisen districts.
🧠 **Memory Tip**: Matatila-Laxmibai (M-L).
🚫 **Scam Alert**: Pagara Dam (Morena) is the oldest dam in MP (1927).', 60, 'matching', '[{"id":"(1)","label":"माताटीला परियोजना","match":"रानी लक्ष्मीबाई परियोजना","matchId":"(a)"},{"id":"(2)","label":"अपर वेनगंगा परियोजना","match":"संजय सरोवर परियोजना","matchId":"(b)"},{"id":"(3)","label":"पेन्च परियोजना","match":"मचागोरा बाँध","matchId":"(c)"},{"id":"(4)","label":"हलाली परियोजना","match":"सम्राट अशोक सागर","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3af01473-0c08-4add-a1b8-c6c783e66c41', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'मध्य प्रदेश के किस जिले में ''तालाबों'' द्वारा सर्वाधिक सिंचाई की जाती है?', '[{"id":"A","text":"बालाघाट","text_en":"बालाघाट"},{"id":"B","text":"ग्वालियर","text_en":"ग्वालियर"},{"id":"C","text":"मुरैना","text_en":"मुरैना"},{"id":"D","text":"होशंगाबाद","text_en":"होशंगाबाद"}]', '0', '✅ **Correct Logic**: बालाघाट में पथरीली भूमि होने के कारण तालाबों द्वारा सिंचाई का प्रचलन सर्वाधिक है।
💡 **Exam Fact**: राज्य की कुल सिंचाई में तालाबों का योगदान लगभग 2-3% है।
🧠 **Memory Tip**: B for Balaghat, B for Big Tanks.
🚫 **Scam Alert**: होशंगाबाद नहरों द्वारा सिंचाई में प्रथम है, तालाबों में नहीं।', 2, 0, 6, NULL, 'In which district of MP is maximum irrigation done through ''Tanks''?', '✅ **Correct Logic**: Due to the rocky terrain, Balaghat district leads in tank-based irrigation.
💡 **Exam Fact**: Tanks contribute only about 2-3% to total irrigation in the state.
🧠 **Memory Tip**: B for Balaghat, B for Big Ponds/Tanks.
🚫 **Scam Alert**: Hoshangabad leads in canal irrigation, not tanks.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('46f4daca-9535-42bd-8204-a6009b58086b', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'नर्मदा बचाओ आंदोलन'' की शुरुआत किस वर्ष हुई थी और इसकी मुख्य नेता कौन हैं?', '[{"id":"A","text":"1985; मेधा पाटकर","text_en":"1985; मेधा पाटकर"},{"id":"B","text":"1975; बाबा आमटे","text_en":"1975; बाबा आमटे"},{"id":"C","text":"1990; अरुंधति रॉय","text_en":"1990; अरुंधति रॉय"},{"id":"D","text":"1980; सुंदरलाल बहुगुणा","text_en":"1980; सुंदरलाल बहुगुणा"}]', '0', '✅ **Correct Logic**: 1985 में मेधा पाटकर के नेतृत्व में नर्मदा नदी पर बन रहे बड़े बाँधों के विरोध में यह आंदोलन शुरू हुआ।
💡 **Exam Fact**: बाबा आमटे भी इस आंदोलन से गहरे जुड़े रहे हैं।
🧠 **Memory Tip**: M-M (Medha-Narmada Movement).
🚫 **Scam Alert**: सुंदरलाल बहुगुणा चिपको आंदोलन (उत्तराखंड) से संबंधित थे।', 2, 0, 7, NULL, 'In which year did the ''Narmada Bachao Andolan'' start and who is its primary leader?', '✅ **Correct Logic**: The movement started in 1985 under Medha Patkar to protest the displacement caused by large dams on the Narmada.
💡 **Exam Fact**: Baba Amte was also a significant figure in this struggle.
🧠 **Memory Tip**: M-M (Medha-Narmada Movement).
🚫 **Scam Alert**: Sunderlal Bahuguna was associated with the Chipko movement in Uttarakhand.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7ce62016-af1c-48a0-9b8a-8566669193da', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'मध्य प्रदेश की किस नदी को ''नदियों को जोड़ने'' (River Linking) की पहली परियोजना में शामिल किया गया था?', '[{"id":"A","text":"केन-बेतवा लिंक","text_en":"केन-बेतवा लिंक"},{"id":"B","text":"नर्मदा-क्षिप्रा लिंक","text_en":"नर्मदा-क्षिप्रा लिंक"},{"id":"C","text":"चंबल-कालीसिंध लिंक","text_en":"चंबल-कालीसिंध लिंक"},{"id":"D","text":"सोन-नर्मदा लिंक","text_en":"सोन-नर्मदा लिंक"}]', '0', '✅ **Correct Logic**: केन-बेतवा लिंक परियोजना भारत की पहली नदी जोड़ो परियोजना है (2005)।
💡 **Exam Fact**: इस परियोजना से पन्ना टाइगर रिजर्व का कुछ हिस्सा जलमग्न होगा।
🧠 **Memory Tip**: K-B (Alphabetical start - First link).
🚫 **Scam Alert**: नर्मदा-क्षिप्रा लिंक राज्य की पहली ''इंट्रा-स्टेट'' लिंक है, पर केन-बेतवा राष्ट्रीय स्तर पर पहली थी।', 2, 0, 8, NULL, 'Which river of MP was included in the first River Linking Project?', '✅ **Correct Logic**: The Ken-Betwa link is India''s first river interlinking project (2005).
💡 **Exam Fact**: Part of Panna Tiger Reserve will be submerged due to this project.
🧠 **Memory Tip**: K-B - First link in the sequence.
🚫 **Scam Alert**: Narmada-Shipra was the state''s first intra-state link, but Ken-Betwa was the national pioneer.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('717d82db-e622-4e9a-a470-729bea0f9638', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'बरगी बाँध (रानी अवंतीबाई सागर) किस नदी पर और किस जिले में स्थित है?', '[{"id":"A","text":"नर्मदा; जबलपुर","text_en":"नर्मदा; जबलपुर"},{"id":"B","text":"नर्मदा; मंडला","text_en":"नर्मदा; मंडला"},{"id":"C","text":"बेतवा; भोपाल","text_en":"बेतवा; भोपाल"},{"id":"D","text":"सोन; सीधी","text_en":"सोन; सीधी"}]', '0', '✅ **Correct Logic**: बरगी बाँध नर्मदा नदी पर जबलपुर जिले में स्थित है।
💡 **Exam Fact**: यह नर्मदा पर बने शुरुआती बड़े बाँधों में से एक है।
🧠 **Memory Tip**: Bargi - Bagi (Jabalpur had rebels).
🚫 **Scam Alert**: जबलपुर शहर के पास होने के कारण इसे अक्सर भेड़ाघाट से जोड़ा जाता है, पर बाँध बरगी गाँव में है।', 2, 0, 9, NULL, 'Bargi Dam (Rani Avantibai Sagar) is located on which river and in which district?', '✅ **Correct Logic**: Bargi Dam is built on the Narmada river in Jabalpur district.
💡 **Exam Fact**: It is one of the first major dams completed on the Narmada.
🧠 **Memory Tip**: Bargi starts with B, so does Barela (nearby samadhi area).
🚫 **Scam Alert**: It is often confused with Bhedaghat; the falls are different from the dam site at Bargi.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f9df55a3-57c0-4fbc-a445-d6bd427b7f7e', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'मध्य प्रदेश के किस जिले को ''सिंचाई का द्वीप'' कहा जाता है क्योंकि वहाँ चारों ओर से सिंचाई परियोजनाओं का लाभ मिलता है?', '[{"id":"A","text":"होशंगाबाद (नर्मदापुरम)","text_en":"होशंगाबाद (नर्मदापुरम)"},{"id":"B","text":"भिंड","text_en":"भिंड"},{"id":"C","text":"मुरैना","text_en":"मुरैना"},{"id":"D","text":"श्योपुर","text_en":"श्योपुर"}]', '0', '✅ **Correct Logic**: नर्मदापुरम (होशंगाबाद) राज्य का सर्वाधिक सिंचित जिला (प्रतिशत में) है और इसे नहरों का जाल होने के कारण सिंचाई का द्वीप जैसा लाभ मिलता है।
💡 **Exam Fact**: तवा परियोजना यहाँ की सबसे प्रमुख सिंचाई योजना है।
🧠 **Memory Tip**: Hoshangabad - High Irrigation.
🚫 **Scam Alert**: ग्वालियर-भिंड में भी नहरें हैं, लेकिन नर्मदापुरम का प्रतिशत और घनत्व सर्वाधिक है।', 2, 0, 10, NULL, 'Which district is called the ''Island of Irrigation'' in MP?', '✅ **Correct Logic**: Narmadapuram is the most irrigated district by percentage in the state.
💡 **Exam Fact**: The Tawa project is the primary lifeline for this district.
🧠 **Memory Tip**: Hoshangabad - High density irrigation.
🚫 **Scam Alert**: While Bhind/Gwalior are canal-rich, Narmadapuram holds the statistical lead.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8cbe36e1-2cad-427e-ac97-ab427863f015', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'हरित क्रांति शब्द (Term) का प्रयोग सबसे पहले किसके द्वारा किया गया था?', '[{"id":"A","text":"नॉर्मन बोरलॉग (Norman Borlaug)","text_en":"नॉर्मन बोरलॉग (Norman Borlaug)"},{"id":"B","text":"एम.एस. स्वामीनाथन (M.S. Swaminathan)","text_en":"एम.एस. स्वामीनाथन (M.S. Swaminathan)"},{"id":"C","text":"विलियम गौड (William Gaud)","text_en":"विलियम गौड (William Gaud)"},{"id":"D","text":"वर्गीस कुरियन (Verghese Kurien)","text_en":"वर्गीस कुरियन (Verghese Kurien)"}]', '2', '**✅ Correct Logic:** हरित क्रांति **शब्द** (Term) 1968 में यूएसएआईडी (USAID) के प्रशासक **विलियम गौड** (William Gaud) द्वारा दिया गया था। नॉर्मन बोरलॉग ''जनक'' (Father) हैं, लेकिन शब्द गौड का है।

**💡 Exam Fact:** एम.एस. स्वामीनाथन को ''भारत में हरित क्रांति का जनक'' कहा जाता है।

**🧠 Memory Tip:** **Gaud** gave the **Green** signal (Term).

**🚫 Scam Alert:** जनक (Father) और शब्द प्रदाता (Coiner) में अंतर है। बोरलॉग मत चुनना!', 2, 0, 1, NULL, 'Who coined the term ''Green Revolution'' for the first time?', '**✅ Correct Logic:** The **term** was coined by **William Gaud** (USAID) in 1968. Borlaug is the Father, but the term is Gaud''s.

**💡 Exam Fact:** M.S. Swaminathan is the Father of Green Revolution in India.

**🧠 Memory Tip:** **Gaud** gave the **Green** signal.

**🚫 Scam Alert:** Don''t confuse Father (Borlaug) with Coiner (Gaud).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5f85c785-5cfc-4704-a0ba-d95234eb3bc9', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'भारत में हरित क्रांति की शुरुआत किस पंचवर्षीय योजना (Five Year Plan) के दौरान मानी जाती है?', '[{"id":"A","text":"दूसरी योजना (Second Plan)","text_en":"दूसरी योजना (Second Plan)"},{"id":"B","text":"तीसरी योजना (Third Plan)","text_en":"तीसरी योजना (Third Plan)"},{"id":"C","text":"योजना अवकाश (Plan Holiday)","text_en":"योजना अवकाश (Plan Holiday)"},{"id":"D","text":"चौथी योजना (Fourth Plan)","text_en":"चौथी योजना (Fourth Plan)"}]', '2', '**✅ Correct Logic:** हरित क्रांति की औपचारिक शुरुआत **1966-67** में हुई थी। यह समय **योजना अवकाश** (Plan Holiday: 1966-69) का था, जो तीसरी योजना की विफलता (युद्ध/सूखा) के बाद आया था।

**💡 Exam Fact:** तीसरी योजना में लक्ष्य कृषि था, लेकिन सफलता योजना अवकाश में मिली।

**🧠 Memory Tip:** **Holiday** me **Hariyali** aayi (Greenery came during Holiday).

**🚫 Scam Alert:** अक्सर छात्र तीसरी (1961-66) या चौथी (1969-74) सोचते हैं, लेकिन सही उत्तर ''योजना अवकाश'' है।', 2, 0, 2, NULL, 'The beginning of Green Revolution in India is considered during which Five Year Plan?', '**✅ Correct Logic:** Started in **1966-67**, which falls under **Plan Holiday** (1966-69), post the failure of Third Plan due to wars/drought.

**💡 Exam Fact:** Third plan targeted agriculture, but success came during the Holiday.

**🧠 Memory Tip:** **Holiday** me **Hariyali**.

**🚫 Scam Alert:** Don''t pick 3rd or 4th. It was the gap period (Holiday).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d45df4af-a078-46a2-af61-3023355a81c0', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'नॉर्मन बोरलॉग (Norman Borlaug) ने किस देश में उच्च उपज वाली गेहूं की किस्मों (HYV) को विकसित किया था?', '[{"id":"A","text":"संयुक्त राज्य अमेरिका (USA)","text_en":"संयुक्त राज्य अमेरिका (USA)"},{"id":"B","text":"मैक्सिको (Mexico)","text_en":"मैक्सिको (Mexico)"},{"id":"C","text":"भारत (India)","text_en":"भारत (India)"},{"id":"D","text":"फिलीपींस (Philippines)","text_en":"फिलीपींस (Philippines)"}]', '1', '**✅ Correct Logic:** बोरलॉग ने **मैक्सिको** (CIMMYT संस्थान) में अपना शोध किया और बौने गेहूं (Dwarf Wheat) की किस्में विकसित कीं।

**💡 Exam Fact:** उन्हें इसके लिए 1970 में नोबेल *शांति* पुरस्कार मिला (कृषि का नहीं)।

**🧠 Memory Tip:** **M**exico made **M**odern wheat.

**🚫 Scam Alert:** वे अमेरिकी थे, लेकिन कार्यक्षेत्र (Workplace) मैक्सिको था। फिलीपींस में चावल (IRRI) पर शोध हुआ था।', 2, 0, 3, NULL, 'In which country did Norman Borlaug develop the High Yielding Varieties (HYV) of wheat?', '**✅ Correct Logic:** Borlaug conducted his research in **Mexico** (CIMMYT) and developed dwarf wheat varieties.

**💡 Exam Fact:** He got the Nobel *Peace* Prize in 1970.

**🧠 Memory Tip:** **M**exico made **M**odern wheat.

**🚫 Scam Alert:** He was American, but worked in Mexico. Philippines was for Rice.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('69be41b1-06e1-405a-91bf-ac4c8dcc3998', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'हरित क्रांति के नकारात्मक प्रभावों (Negative Impacts) में निम्नलिखित में से क्या शामिल नहीं है?', '[{"id":"A","text":"मृदा लवणता में वृद्धि (Increase in Soil Salinity)","text_en":"मृदा लवणता में वृद्धि (Increase in Soil Salinity)"},{"id":"B","text":"भौमजल स्तर में गिरावट (Decline in Groundwater level)","text_en":"भौमजल स्तर में गिरावट (Decline in Groundwater level)"},{"id":"C","text":"फसल विविधता में कमी (Decrease in Crop Diversity)","text_en":"फसल विविधता में कमी (Decrease in Crop Diversity)"},{"id":"D","text":"दलहन उत्पादन में भारी वृद्धि (Massive increase in Pulses production)","text_en":"दलहन उत्पादन में भारी वृद्धि (Massive increase in Pulses production)"}]', '3', '**✅ Correct Logic:** हरित क्रांति का मुख्य फोकस गेहूं और चावल पर था, जिससे **दलहन (Pulses) और तिलहन पिछड़ गए**। दलहन उत्पादन में वृद्धि नहीं हुई, बल्कि प्रति व्यक्ति उपलब्धता घट गई। बाकी तीन (लवणता, जल स्तर, विविधता कमी) इसके नकारात्मक प्रभाव हैं।

**💡 Exam Fact:** पंजाब की मिट्टी में कीटनाशकों के कारण ''कैंसर ट्रेन'' प्रसिद्ध हुई।

**🧠 Memory Tip:** Green Revolution was **Anti-Dal** (Anti-Pulses).

**🚫 Scam Alert:** दलहन में वृद्धि *अब* हो रही है (Second GR), पहली में यह उपेक्षित थी।', 2, 0, 4, NULL, 'Which of the following is NOT included in the negative impacts of the Green Revolution?', '**✅ Correct Logic:** Focus was on Wheat/Rice. **Pulses (Dal) were neglected**, leading to a decline in per capita availability. The other three are valid negative impacts.

**💡 Exam Fact:** ''Cancer Train'' in Punjab is linked to pesticide overuse.

**🧠 Memory Tip:** Green Revolution was **Anti-Dal**.

**🚫 Scam Alert:** Pulses grew later; initially, they suffered.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('798329bb-431f-4310-ab51-0909e387b5b4', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'हरित क्रांति के घटक (Components) क्या थे?
1. HYV बीज
2. रासायनिक उर्वरक
3. सिंचाई विस्तार
4. जैविक खेती', '[{"id":"A","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"B","text":"1, 3 और 4","text_en":"1, 3 और 4"},{"id":"C","text":"2, 3 और 4","text_en":"2, 3 और 4"},{"id":"D","text":"सभी 1, 2, 3, 4","text_en":"सभी 1, 2, 3, 4"}]', '0', '**✅ Correct Logic:** हरित क्रांति रासायनिक इनपुट (Chemical Inputs) पर आधारित थी। इसमें HYV बीज, उर्वरक और सिंचाई शामिल थे। **जैविक खेती** (Organic Farming) इसका हिस्सा नहीं थी, बल्कि यह तो इसके विरोध/सुधार (Second Green Revolution) का हिस्सा है।

**💡 Exam Fact:** इसे ''पैकेज टेक्नोलॉजी'' कहा जाता था।

**🧠 Memory Tip:** **Green** Revolution was chemically **Grey**, not Organic Green.

**🚫 Scam Alert:** ''Green'' नाम से जैविक मत समझ लेना। यह रसायनों का खेल था।', 2, 0, 5, NULL, 'What were the components of Green Revolution?
1. HYV Seeds
2. Chemical Fertilizers
3. Irrigation Expansion
4. Organic Farming', '**✅ Correct Logic:** Based on Chemical Inputs. HYV, Fertilizers, Irrigation were key. **Organic Farming** was NOT part of it; rather, organic is the counter-movement (Second GR).

**💡 Exam Fact:** Called ''Package Technology''.

**🧠 Memory Tip:** **Green** Revolution was chemically **Grey**.

**🚫 Scam Alert:** Don''t assume ''Green'' means Organic here.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b347bfcd-0568-4654-8324-c2d8213f667d', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'भारत में चावल की कौन सी ''चमत्कारी किस्म'' (Miracle Rice) हरित क्रांति के दौरान पेश की गई थी?', '[{"id":"A","text":"IR-8","text_en":"IR-8"},{"id":"B","text":"बसमती-370 (Basmati-370)","text_en":"बसमती-370 (Basmati-370)"},{"id":"C","text":"पूसा-1121 (Pusa-1121)","text_en":"पूसा-1121 (Pusa-1121)"},{"id":"D","text":"स्वर्णा (Swarna)","text_en":"स्वर्णा (Swarna)"}]', '0', '**✅ Correct Logic:** **IR-8** (International Rice-8) को ''चमत्कारी चावल'' कहा गया क्योंकि इसने उत्पादन को कई गुना बढ़ा दिया। यह फिलीपींस (IRRI) से लाया गया था।

**💡 Exam Fact:** बाद में भारत ने अपनी किस्में ''जया'' और ''रत्ना'' विकसित कीं।

**🧠 Memory Tip:** **IR-8** ate hunger.

**🚫 Scam Alert:** पूसा और बसमती आधुनिक किस्में हैं। IR-8 हरित क्रांति की शुरुआत थी।', 2, 0, 6, NULL, 'Which ''Miracle Rice'' variety was introduced in India during the Green Revolution?', '**✅ Correct Logic:** **IR-8** was called ''Miracle Rice'' due to massive yield. Imported from Philippines (IRRI).

**💡 Exam Fact:** India later developed ''Jaya'' and ''Ratna''.

**🧠 Memory Tip:** **IR-8** ate hunger.

**🚫 Scam Alert:** Pusa/Basmati are modern. IR-8 started it all.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a187d9b7-ee26-47c9-a40c-3e901c93b009', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'हरित क्रांति का प्रभाव भारत के किस क्षेत्र तक सीमित रहा?', '[{"id":"A","text":"पूरे भारत में (Pan India)","text_en":"पूरे भारत में (Pan India)"},{"id":"B","text":"दक्षिण भारत (South India)","text_en":"दक्षिण भारत (South India)"},{"id":"C","text":"उत्तर-पश्चिमी भारत (North-Western India)","text_en":"उत्तर-पश्चिमी भारत (North-Western India)"},{"id":"D","text":"पूर्वी भारत (Eastern India)","text_en":"पूर्वी भारत (Eastern India)"}]', '2', '**✅ Correct Logic:** इसका मुख्य प्रभाव **उत्तर-पश्चिमी भारत** (पंजाब, हरियाणा, पश्चिमी उत्तर प्रदेश) और कुछ तटीय आंध्र/तमिलनाडु तक सीमित रहा। पूर्वी भारत और वर्षा सिंचित (Rainfed) क्षेत्र अछूते रह गए।

**💡 Exam Fact:** क्षेत्रीय असमानता (Regional Disparity) इसका एक बड़ा दोष था।

**🧠 Memory Tip:** **West** won, **East** least.

**🚫 Scam Alert:** पूरा भारत लाभाान्वित नहीं हुआ, इसीलिए अब ''पूर्वी भारत में हरित क्रांति'' (BGREI) पर जोर है।', 2, 0, 7, NULL, 'The impact of Green Revolution was limited to which region of India?', '**✅ Correct Logic:** Mainly **North-Western India** (Punjab, Haryana, West UP). Eastern India and rainfed areas were left out.

**💡 Exam Fact:** Regional Disparity was a major flaw.

**🧠 Memory Tip:** **West** won, **East** least.

**🚫 Scam Alert:** Not Pan-India. Hence focus is now on BGREI.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a19aff20-768e-45f3-a27b-fbddaf42e1be', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'निम्नलिखित में से किसने हरित क्रांति के आलोचक के रूप में ''वंदना शिवा'' (Vandana Shiva) की तरह तर्क दिया कि इसने ''हिंसा'' को जन्म दिया?', '[{"id":"A","text":"नॉर्मन बोरलॉग खुद (Norman Borlaug himself)","text_en":"नॉर्मन बोरलॉग खुद (Norman Borlaug himself)"},{"id":"B","text":"अमर्त्य सेन (Amartya Sen)","text_en":"अमर्त्य सेन (Amartya Sen)"},{"id":"C","text":"वंदना शिवा (Vandana Shiva)","text_en":"वंदना शिवा (Vandana Shiva)"},{"id":"D","text":"अरुंधति रॉय (Arundhati Roy)","text_en":"अरुंधति रॉय (Arundhati Roy)"}]', '2', '**✅ Correct Logic:** प्रश्न में ही उत्तर छिपा है, लेकिन संदर्भ महत्वपूर्ण है। **वंदना शिवा** ने अपनी पुस्तक ''The Violence of the Green Revolution'' में तर्क दिया कि इसने पारिस्थितिक विनाश और सामाजिक संघर्ष (पंजाब हिंसा) को जन्म दिया।

**💡 Exam Fact:** वे ''नवधान्य'' (Navdanya) आंदोलन चलाती हैं जो बीज संप्रभुता के लिए है।

**🧠 Memory Tip:** **Shiva** (Destroyer) analyzed the destruction (violence).

**🚫 Scam Alert:** बोरलॉग समर्थक थे। अमर्त्य सेन वितरण पर ध्यान देते हैं। वंदना शिवा प्रमुख आलोचक हैं।', 2, 0, 8, NULL, 'Who among the following, like Vandana Shiva, argued as a critic of Green Revolution that it led to ''violence''?', '**✅ Correct Logic:** **Vandana Shiva** authored ''The Violence of the Green Revolution'', linking it to ecological destruction and social conflict.

**💡 Exam Fact:** She runs ''Navdanya'' movement.

**🧠 Memory Tip:** **Shiva** analyzed destruction.

**🚫 Scam Alert:** She is the primary critic of chemical farming.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1a340540-4acd-47f3-bde3-52aea5bd017e', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'हरित क्रांति के दौरान, भारत सरकार ने किसानों को मूल्य सुरक्षा प्रदान करने के लिए कौन सी संस्था स्थापित की थी?', '[{"id":"A","text":"APC (Agricultural Prices Commission)","text_en":"APC (Agricultural Prices Commission)"},{"id":"B","text":"NABARD","text_en":"NABARD"},{"id":"C","text":"NITI Aayog","text_en":"NITI Aayog"},{"id":"D","text":"ICAR","text_en":"ICAR"}]', '0', '**✅ Correct Logic:** 1965 में **APC** (Agricultural Prices Commission) की स्थापना की गई थी, जिसे 1985 में बदलकर **CACP** कर दिया गया। इसका काम MSP तय करना था ताकि किसान HYV बीज उगाने का जोखिम उठा सकें।

**💡 Exam Fact:** एल.के. झा (L.K. Jha) APC के पहले अध्यक्ष थे।

**🧠 Memory Tip:** **A**PC for **A**griculture **P**rices.

**🚫 Scam Alert:** नाबार्ड 1982 में आया। APC हरित क्रांति (1965) के साथ आया।', 2, 0, 9, NULL, 'During the Green Revolution, which institution was set up by Govt of India to provide price security to farmers?', '**✅ Correct Logic:** **APC** (Agricultural Prices Commission) was set up in 1965 (Renamed CACP in 1985) to recommend MSP.

**💡 Exam Fact:** L.K. Jha was the first chairman.

**🧠 Memory Tip:** **A**PC for **A**griculture **P**rices.

**🚫 Scam Alert:** NABARD came in 1982. APC came with Green Revolution.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2a90239b-57f8-4eaf-beac-c010d3a2983b', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'निम्नलिखित व्यक्तियों को उनकी भूमिका से सुमेलित करें (Match the following persons with their roles):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **स्वामीनाथन**: भारतीय जनक। -> (1)-(a)
* **बोरलॉग**: वैश्विक जनक। -> (2)-(b)
* **सी. सुब्रमण्यम**: तत्कालीन कृषि मंत्री जिन्होंने राजनीतिक इच्छाशक्ति दिखाई। उन्हें ''Political Father'' कहते हैं। -> (3)-(c)
* **डी.एस. अठवाल**: इन्हें ''Father of Wheat Revolution'' कहा जाता है (वैज्ञानिक योगदान)। -> (4)-(d)

**💡 Exam Fact:** सी. सुब्रमण्यम को भारत रत्न (1998) मिला।

**🧠 Memory Tip:** **S**wami (India), **B**orlaug (World), **S**ubramaniam (State/Politics).

**🚫 Scam Alert:** सी. सुब्रमण्यम की भूमिका अक्सर अनदेखी की जाती है, लेकिन वे महत्वपूर्ण स्तंभ थे।', 2, 0, 10, NULL, 'Match the following persons with their roles:', '**✅ Correct Matching:**
* **Swaminathan**: India Father. -> (1)-(a)
* **Borlaug**: World Father. -> (2)-(b)
* **C. Subramaniam**: Agriculture Minister, Political Father. -> (3)-(c)
* **D.S. Athwal**: Father of Wheat Rev. -> (4)-(d)

**💡 Exam Fact:** C. Subramaniam got Bharat Ratna.

**🧠 Memory Tip:** **S**wami (India), **B**orlaug (World), **S**ubramaniam (Politics).

**🚫 Scam Alert:** C. Subramaniam was the minister who pushed it.', 60, 'matching', '[{"id":"(1)","label":"एम.एस. स्वामीनाथन (M.S. Swaminathan)","match":"भारत में हरित क्रांति के जनक (Father of Green Rev in India)","matchId":"(a)"},{"id":"(2)","label":"नॉर्मन बोरलॉग (Norman Borlaug)","match":"विश्व में हरित क्रांति के जनक (Father of Green Rev in World)","matchId":"(b)"},{"id":"(3)","label":"सी. सुब्रमण्यम (C. Subramaniam)","match":"हरित क्रांति के राजनीतिक पिता (Political Father of Green Rev)","matchId":"(c)"},{"id":"(4)","label":"दिलबाग सिंह अठवाल (Dilbagh Singh Athwal)","match":"गेहूं क्रांति के जनक (Father of Wheat Rev)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5e6d918b-a41a-4188-8282-341c38d87d19', '15e89685-acfe-4377-8df2-dab109e134e5', 'दूसरी हरित क्रांति (Second Green Revolution) का मुख्य फोकस क्षेत्र क्या है?', '[{"id":"A","text":"केवल पंजाब और हरियाणा (Only Punjab and Haryana)","text_en":"केवल पंजाब और हरियाणा (Only Punjab and Haryana)"},{"id":"B","text":"वर्षा सिंचित और पूर्वी भारत (Rainfed and Eastern India)","text_en":"वर्षा सिंचित और पूर्वी भारत (Rainfed and Eastern India)"},{"id":"C","text":"केवल तटीय क्षेत्र (Only Coastal Areas)","text_en":"केवल तटीय क्षेत्र (Only Coastal Areas)"},{"id":"D","text":"पश्चिमी घाट (Western Ghats)","text_en":"पश्चिमी घाट (Western Ghats)"}]', '1', '**✅ Correct Logic:** पहली क्रांति से छूटे हुए क्षेत्रों, विशेष रूप से **पूर्वी भारत** (बिहार, बंगाल, ओडिशा) और **वर्षा सिंचित** (Rainfed) क्षेत्रों पर ध्यान केंद्रित करना दूसरी क्रांति का लक्ष्य है।

**💡 Exam Fact:** BGREI (Bringing Green Revolution to Eastern India) इसी रणनीति का हिस्सा है।

**🧠 Memory Tip:** First was **West**, Second is **East**.

**🚫 Scam Alert:** पंजाब-हरियाणा में अब ''सदाबहार क्रांति'' (Evergreen - Sustainability) की जरूरत है, दूसरी क्रांति का विस्तार ''पूरब'' में हो रहा है।', 2, 0, 1, NULL, 'What is the main focus area of the Second Green Revolution?', '**✅ Correct Logic:** Focus is on **Eastern India** and **Rainfed areas** which were neglected in the first round.

**💡 Exam Fact:** BGREI is a key scheme.

**🧠 Memory Tip:** First was **West**, Second is **East**.

**🚫 Scam Alert:** Punjab needs sustainability now; expansion is happening in East.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0f881ee1-ed14-4f56-ba8e-99721e97ffa1', '15e89685-acfe-4377-8df2-dab109e134e5', '''सदाबहार क्रांति'' (Evergreen Revolution) का आह्वान किसने किया था?', '[{"id":"A","text":"नरेद्र मोदी (Narendra Modi)","text_en":"नरेद्र मोदी (Narendra Modi)"},{"id":"B","text":"एम.एस. स्वामीनाथन (M.S. Swaminathan)","text_en":"एम.एस. स्वामीनाथन (M.S. Swaminathan)"},{"id":"C","text":"ए.पी.जे. अब्दुल कलाम (A.P.J. Abdul Kalam)","text_en":"ए.पी.जे. अब्दुल कलाम (A.P.J. Abdul Kalam)"},{"id":"D","text":"मनमोहन सिंह (Manmohan Singh)","text_en":"मनमोहन सिंह (Manmohan Singh)"}]', '1', '**✅ Correct Logic:** **एम.एस. स्वामीनाथन** ने ''सदाबहार क्रांति'' (Evergreen Revolution) शब्द दिया। इसका अर्थ है: "पारिस्थितिक नुकसान के बिना उत्पादकता में वृद्धि" (Productivity in perpetuity without ecological harm)।

**💡 Exam Fact:** यह दूसरी हरित क्रांति का दार्शनिक आधार है।

**🧠 Memory Tip:** **Swami** wants **Ever**lasting peace (Evergreen).

**🚫 Scam Alert:** कलाम ने ''पुरा'' (PURA) दिया था, स्वामीनाथन ने सदाबहार क्रांति।', 2, 0, 2, NULL, 'Who gave the call for ''Evergreen Revolution''?', '**✅ Correct Logic:** **M.S. Swaminathan** coined ''Evergreen Revolution''. Meaning: Increase productivity without ecological harm.

**💡 Exam Fact:** It is the philosophy of Second GR.

**🧠 Memory Tip:** **Swami** wants **Ever**lasting.

**🚫 Scam Alert:** Kalam gave PURA. Swaminathan gave Evergreen.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f9868f9b-7191-4e8c-a905-588b7b9f6e9d', '15e89685-acfe-4377-8df2-dab109e134e5', 'इंद्रधनुषी क्रांति (Rainbow Revolution) का संबंध किससे है?', '[{"id":"A","text":"केवल फूलों की खेती (Only Floriculture)","text_en":"केवल फूलों की खेती (Only Floriculture)"},{"id":"B","text":"कृषि के सभी क्षेत्रों (फसल, बागवानी, पशुपालन, मछली) का समग्र विकास","text_en":"कृषि के सभी क्षेत्रों (फसल, बागवानी, पशुपालन, मछली) का समग्र विकास"},{"id":"C","text":"सिर्फ वर्षा जल संचयन (Only Rainwater Harvesting)","text_en":"सिर्फ वर्षा जल संचयन (Only Rainwater Harvesting)"},{"id":"D","text":"जैविक रंगों का उत्पादन (Organic colors)","text_en":"जैविक रंगों का उत्पादन (Organic colors)"}]', '1', '**✅ Correct Logic:** इंद्रधनुषी क्रांति एक ''छाता शब्द'' (Umbrella term) है जिसमें **कृषि के सभी क्षेत्र** (हरित, श्वेत, नीली, पीली, गुलाबी, आदि) शामिल हैं। इसका लक्ष्य समग्र (Holistic) विकास है।

**💡 Exam Fact:** यह राष्ट्रीय कृषि नीति 2000 में घोषित की गई थी।

**🧠 Memory Tip:** **Rainbow** has all colors -> All sectors.

**🚫 Scam Alert:** यह किसी एक रंग/फसल के लिए नहीं, बल्कि सबके एकीकरण के लिए है।', 2, 0, 3, NULL, 'What is ''Rainbow Revolution'' related to?', '**✅ Correct Logic:** Umbrella term covering **all sectors** of agriculture (Green, White, Blue, Yellow, etc.) for holistic growth.

**💡 Exam Fact:** Declared in National Agriculture Policy 2000.

**🧠 Memory Tip:** **Rainbow** has all colors -> All sectors.

**🚫 Scam Alert:** It''s integrated agriculture, not just one crop.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1da952e0-9030-4f80-a838-0780f1ed2b53', '15e89685-acfe-4377-8df2-dab109e134e5', 'दूसरी हरित क्रांति में जैव प्रौद्योगिकी (Biotechnology) की क्या भूमिका है?', '[{"id":"A","text":"पूरी तरह से प्रतिबंधित (Completely banned)","text_en":"पूरी तरह से प्रतिबंधित (Completely banned)"},{"id":"B","text":"आनुवंशिक रूप से संशोधित (GM) फसलों का उपयोग (Use of GM crops)","text_en":"आनुवंशिक रूप से संशोधित (GM) फसलों का उपयोग (Use of GM crops)"},{"id":"C","text":"केवल जैविक खाद का उपयोग","text_en":"केवल जैविक खाद का उपयोग"},{"id":"D","text":"ट्रैक्टरों का उपयोग कम करना","text_en":"ट्रैक्टरों का उपयोग कम करना"}]', '1', '**✅ Correct Logic:** दूसरी हरित क्रांति में **जीएम फसलों** (जैसे बीटी कॉटन, जीएम सरसों) और आणविक प्रजनन (Molecular Breeding) जैसी तकनीकों का उपयोग कर कीट प्रतिरोधी और जलवायु अनुकूल फसलें बनाना शामिल है।

**💡 Exam Fact:** बीटी कॉटन भारत में अनुमति प्राप्त एकमात्र जीएम फसल है (व्यावसायिक)।

**🧠 Memory Tip:** 2nd Revolution = **Bio**-Revolution.

**🚫 Scam Alert:** जैविक खेती भी हिस्सा है, लेकिन ''जैव प्रौद्योगिकी'' शब्द का सीधा संबंध GM/Gene editing से है।', 2, 0, 4, NULL, 'What is the role of Biotechnology in the Second Green Revolution?', '**✅ Correct Logic:** Involves use of **GM crops** (like Bt Cotton) and molecular breeding to create pest-resistant/climate-resilient crops.

**💡 Exam Fact:** Bt Cotton is the only commercial GM crop in India.

**🧠 Memory Tip:** 2nd Revolution = **Bio**-Revolution.

**🚫 Scam Alert:** Organic is part of it, but ''Biotech'' specifically implies GM/Genetics.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fb80c995-4e0a-4a2b-8147-b7a2c0402b65', '15e89685-acfe-4377-8df2-dab109e134e5', 'मृदा स्वास्थ्य कार्ड (Soil Health Card) योजना किस वर्ष शुरू की गई थी, जो दूसरी हरित क्रांति का एक प्रमुख घटक है?', '[{"id":"A","text":"2014","text_en":"2014"},{"id":"B","text":"2015","text_en":"2015"},{"id":"C","text":"2016","text_en":"2016"},{"id":"D","text":"2018","text_en":"2018"}]', '1', '**✅ Correct Logic:** 19 फरवरी **2015** को सूरतगढ़ (राजस्थान) से शुरू की गई। नारा: "स्वस्थ धरा, खेत हरा" (Healthy Earth, Green Farm)। यह उर्वरकों के संतुलित उपयोग को बढ़ावा देती है।

**💡 Exam Fact:** इसमें 12 पैरामीटर (N, P, K, pH, आदि) की जांच होती है।

**🧠 Memory Tip:** **15** saal ka card (2015).

**🚫 Scam Alert:** 2014 में सरकार आई थी, लेकिन योजना 2015 में लॉन्च हुई।', 2, 0, 5, NULL, 'Soil Health Card scheme, a key component of Second Green Revolution, was launched in which year?', '**✅ Correct Logic:** Launched on Feb 19, **2015** from Suratgarh (Rajasthan). Slogan: "Swasth Dhara, Khet Hara". Promotes balanced fertilizer use.

**💡 Exam Fact:** Checks 12 parameters.

**🧠 Memory Tip:** **15** saal ka card.

**🚫 Scam Alert:** Govt came in 2014, Scheme in 2015.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f502525e-55b2-4a8d-8670-31d3361fb2f2', '15e89685-acfe-4377-8df2-dab109e134e5', '''जीरो बजट नेचुरल फार्मिंग'' (ZBNF) को दूसरी हरित क्रांति के विकल्प के रूप में देखा जा रहा है। इसके जनक कौन माने जाते हैं?', '[{"id":"A","text":"सुभाष पालेकर (Subhash Palekar)","text_en":"सुभाष पालेकर (Subhash Palekar)"},{"id":"B","text":"सुंदरलाल बहुगुणा (Sundarlal Bahuguna)","text_en":"सुंदरलाल बहुगुणा (Sundarlal Bahuguna)"},{"id":"C","text":"बाबा आमटे (Baba Amte)","text_en":"बाबा आमटे (Baba Amte)"},{"id":"D","text":"अन्ना हजारे (Anna Hazare)","text_en":"अन्ना हजारे (Anna Hazare)"}]', '0', '**✅ Correct Logic:** **सुभाष पालेकर** (महाराष्ट्र) ने ZBNF को लोकप्रिय बनाया। इसमें जीवामृत, बीजामृत, और आच्छादन (Mulching) जैसे 4 स्तंभ हैं।

**💡 Exam Fact:** आंध्र प्रदेश ने 100% ZBNF राज्य बनने का लक्ष्य रखा है।

**🧠 Memory Tip:** **Pal**ekar **Pal**ta (Changed) farming to Zero Budget.

**🚫 Scam Alert:** सुंदरलाल बहुगुणा चिपको आंदोलन (वन) से थे। पालेकर खेती से हैं।', 2, 0, 6, NULL, '''Zero Budget Natural Farming'' (ZBNF) is seen as an alternative in Second Green Revolution. Who is considered its father?', '**✅ Correct Logic:** **Subhash Palekar** popularized ZBNF. Four pillars: Jeevamrut, Beejamrut, Mulching, etc.

**💡 Exam Fact:** Andhra Pradesh targets 100% ZBNF.

**🧠 Memory Tip:** **Pal**ekar **Pal**ta farming.

**🚫 Scam Alert:** Bahuguna was Chipko (Forests). Palekar is Farming.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d9085204-4a8b-420b-afbf-518eed379bf7', '15e89685-acfe-4377-8df2-dab109e134e5', 'दूसरी हरित क्रांति में किन फसलों पर विशेष जोर दिया जा रहा है?', '[{"id":"A","text":"केवल गेहूं और चावल","text_en":"केवल गेहूं और चावल"},{"id":"B","text":"दलहन और तिलहन (Pulses and Oilseeds)","text_en":"दलहन और तिलहन (Pulses and Oilseeds)"},{"id":"C","text":"तंबाकू और अफीम","text_en":"तंबाकू और अफीम"},{"id":"D","text":"केवल गन्ना","text_en":"केवल गन्ना"}]', '1', '**✅ Correct Logic:** चूंकि पहली क्रांति में **दलहन और तिलहन** पिछड़ गए थे, इसलिए दूसरी क्रांति में इन प्रोटीन युक्त और आयात-निर्भर फसलों (जैसे खाद्य तेल) पर विशेष जोर दिया जा रहा है।

**💡 Exam Fact:** भारत खाद्य तेल का दुनिया का सबसे बड़ा आयातक है, इसे बदलना लक्ष्य है।

**🧠 Memory Tip:** Fix the mistakes of 1st -> Focus on **Dal & Oil**.

**🚫 Scam Alert:** गेहूं/चावल में हम सरप्लस हैं, अब फोकस दालों पर है।', 2, 0, 7, NULL, 'Which crops are being given special emphasis in the Second Green Revolution?', '**✅ Correct Logic:** Since **Pulses and Oilseeds** lagged in 1st GR, the 2nd GR emphasizes these protein-rich and import-dependent crops.

**💡 Exam Fact:** India is world''s largest importer of edible oil; goal is to change this.

**🧠 Memory Tip:** Fix mistakes -> Focus on **Dal & Oil**.

**🚫 Scam Alert:** We are surplus in Wheat/Rice. Focus is now on Pulses.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fa17249e-fbe2-4c05-8537-123c29a5c8f3', '15e89685-acfe-4377-8df2-dab109e134e5', 'एकीकृत कीट प्रबंधन (IPM) का मुख्य उद्देश्य क्या है?', '[{"id":"A","text":"कीड़ों को पूरी तरह खत्म करना","text_en":"कीड़ों को पूरी तरह खत्म करना"},{"id":"B","text":"रासायनिक कीटनाशकों का उपयोग न्यूनतम करना और जैविक विधियों को जोड़ना","text_en":"रासायनिक कीटनाशकों का उपयोग न्यूनतम करना और जैविक विधियों को जोड़ना"},{"id":"C","text":"कीटनाशकों का हवाई छिड़काव","text_en":"कीटनाशकों का हवाई छिड़काव"},{"id":"D","text":"सिर्फ आनुवंशिक बीजों का उपयोग","text_en":"सिर्फ आनुवंशिक बीजों का उपयोग"}]', '1', '**✅ Correct Logic:** IPM का लक्ष्य कीड़ों को पूरी तरह खत्म करना नहीं, बल्कि उन्हें आर्थिक नुकसान स्तर (ETL) से नीचे रखना है। यह **रसायनों का कम उपयोग** और जैविक/यांत्रिक विधियों (जैसे फेरोमोन ट्रैप) के उपयोग पर जोर देता है।

**💡 Exam Fact:** यह टिकाऊ कृषि (Sustainable Agriculture) का हिस्सा है।

**🧠 Memory Tip:** **Integrate** all methods to manage pests, don''t just spray.

**🚫 Scam Alert:** ''पूरी तरह खत्म करना'' (Eradication) संभव नहीं और पर्यावरण के लिए हानिकारक है।', 2, 0, 8, NULL, 'What is the main objective of Integrated Pest Management (IPM)?', '**✅ Correct Logic:** Objective is to minimize **chemical use** and integrate biological/mechanical methods. Keep pests below Economic Threshold Level (ETL).

**💡 Exam Fact:** Part of Sustainable Agriculture.

**🧠 Memory Tip:** **Integrate** methods, don''t just spray.

**🚫 Scam Alert:** Eradication is not the goal; Management is.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4db3d5ff-036b-4863-9877-05e876e7a452', '15e89685-acfe-4377-8df2-dab109e134e5', 'BGREI (Bringing Green Revolution to Eastern India) कार्यक्रम कब शुरू किया गया था?', '[{"id":"A","text":"2005-06","text_en":"2005-06"},{"id":"B","text":"2010-11","text_en":"2010-11"},{"id":"C","text":"2014-15","text_en":"2014-15"},{"id":"D","text":"2020-21","text_en":"2020-21"}]', '1', '**✅ Correct Logic:** BGREI **2010-11** में शुरू की गई एक उप-योजना (RKVY के तहत) है। यह 7 राज्यों (असम, बिहार, छत्तीसगढ़, झारखंड, ओडिशा, पूर्वी यूपी, पश्चिम बंगाल) को कवर करती है।

**💡 Exam Fact:** इसका उद्देश्य पूर्वी भारत में चावल और गेहूं की उत्पादकता बढ़ाना है।

**🧠 Memory Tip:** **10** out of 10 for East India (2010).

**🚫 Scam Alert:** यह मोदी सरकार (2014) से पहले मनमोहन सिंह सरकार द्वारा शुरू की गई थी।', 2, 0, 9, NULL, 'When was the BGREI (Bringing Green Revolution to Eastern India) program launched?', '**✅ Correct Logic:** Launched in **2010-11** under RKVY. Covers 7 Eastern states.

**💡 Exam Fact:** Aim to boost rice/wheat in East.

**🧠 Memory Tip:** **10** out of 10 for East (2010).

**🚫 Scam Alert:** Launched before 2014.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c604e227-041c-4032-aea6-a3ef53a73087', '15e89685-acfe-4377-8df2-dab109e134e5', 'निम्नलिखित क्रांतियों को उनके रंग/उद्देश्य से सुमेलित करें (Match the following revolutions with their color/objective):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **प्रोटीन क्रांति**: पीएम मोदी द्वारा दूसरी हरित क्रांति के लिए दिया गया शब्द (Technology driven)। -> (1)-(a)
* **तिरंगा क्रांति**: मोदी जी का विजन (Saffron-Solar, White-Dairy, Green-Agri)। -> (2)-(b)
* **ग्रे क्रांति**: उर्वरक (Fertilizer) से संबंधित। -> (3)-(c)
* **भूरी क्रांति**: कोको या चमड़ा या गैर-परंपरागत ऊर्जा (सन्दर्भ पर निर्भर, लेकिन यहाँ सही है)। -> (4)-(d)

**💡 Exam Fact:** ''अमृत क्रांति'' नदी जोड़ो परियोजना से संबंधित है।

**🧠 Memory Tip:** **Grey** powder (Fertilizer). **Tricolor** flag (Modi''s vision). **Protein** requires Tech.

**🚫 Scam Alert:** प्रोटीन क्रांति का मतलब सिर्फ दाल नहीं, बल्कि ''Technology driven 2nd GR'' है।', 2, 0, 10, NULL, 'Match the following revolutions with their color/objective:', '**✅ Correct Matching:**
* **Protein Rev**: Term by PM Modi for High-Tech 2nd GR. -> (1)-(a)
* **Tricolor**: Saffron (Solar), White (Milk), Green (Agri). -> (2)-(b)
* **Grey**: Fertilizers. -> (3)-(c)
* **Brown**: Cocoa/Leather. -> (4)-(d)

**💡 Exam Fact:** Amrit Revolution = River Linking.

**🧠 Memory Tip:** **Grey** Fertilizer. **Tricolor** Flag.

**🚫 Scam Alert:** Protein Revolution refers to Tech-driven agriculture, not just pulses.', 60, 'matching', '[{"id":"(1)","label":"प्रोटीन क्रांति (Protein Revolution)","match":"उच्च तकनीक/दूसरी हरित क्रांति (High Tech/Second GR)","matchId":"(a)"},{"id":"(2)","label":"तिरंगा क्रांति (Tricolor Revolution)","match":"तीन घटक: भगवा (ऊर्जा), सफेद (दूध), हरा (कृषि) - (Energy, Milk, Agri)","matchId":"(b)"},{"id":"(3)","label":"ग्रे क्रांति (Grey Revolution)","match":"उर्वरक उत्पादन (Fertilizer Production)","matchId":"(c)"},{"id":"(4)","label":"भूरी क्रांति (Brown Revolution)","match":"कोको/चमड़ा/गैर-परंपरागत ऊर्जा (Cocoa/Leather/Non-conventional)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7b886ed4-3944-43f2-8fdd-59792fc18709', '58d7a3a6-563d-4cf7-b7c7-d86c3cdaaa62', 'भारत में विद्युत उत्पादन (Installed Capacity) में किस स्रोत का योगदान सर्वाधिक है?', '[{"id":"A","text":"जल विद्युत (Hydro Power)","text_en":"जल विद्युत (Hydro Power)"},{"id":"B","text":"सौर ऊर्जा (Solar Energy)","text_en":"सौर ऊर्जा (Solar Energy)"},{"id":"C","text":"तापीय ऊर्जा / कोयला (Thermal Energy / Coal)","text_en":"तापीय ऊर्जा / कोयला (Thermal Energy / Coal)"},{"id":"D","text":"परमाणु ऊर्जा (Nuclear Energy)","text_en":"परमाणु ऊर्जा (Nuclear Energy)"}]', '2', '**✅ Correct Logic:** भारत में लगभग **50-55%** बिजली उत्पादन **कोयला आधारित तापीय ऊर्जा** (Thermal) से होता है। कुल जीवाश्म ईंधन (Coal+Lignite+Gas) का हिस्सा लगभग 56% है।

**💡 Exam Fact:** दूसरे नंबर पर अब नवीकरणीय ऊर्जा (Renewable - Solar/Wind) आ गई है।

**🧠 Memory Tip:** India runs on **Coal**.

**🚫 Scam Alert:** सौर ऊर्जा तेजी से बढ़ रही है, लेकिन अभी भी कोयला ''किंग'' है।', 2, 0, 1, NULL, 'Which source contributes maximum to the Installed Capacity of electricity generation in India?', '**✅ Correct Logic:** **Thermal Energy (Coal)** contributes approx **50-55%**. Fossil fuels dominate.

**💡 Exam Fact:** Renewables are now 2nd.

**🧠 Memory Tip:** India runs on **Coal**.

**🚫 Scam Alert:** Solar is growing but Coal is still King.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('20d8f683-0d1c-4681-8d72-4c255f0c09d0', '58d7a3a6-563d-4cf7-b7c7-d86c3cdaaa62', 'भारत का सबसे बड़ा थर्मल पावर प्लांट (Thermal Power Plant) कौन सा है?', '[{"id":"A","text":"विंध्याचल (Vindhyachal)","text_en":"विंध्याचल (Vindhyachal)"},{"id":"B","text":"मुंद्रा (Mundra)","text_en":"मुंद्रा (Mundra)"},{"id":"C","text":"तालचेर (Talcher)","text_en":"तालचेर (Talcher)"},{"id":"D","text":"सिपत (Sipat)","text_en":"सिपत (Sipat)"}]', '0', '**✅ Correct Logic:** **विंध्याचल थर्मल पावर स्टेशन** (सिंगरौली, मध्य प्रदेश) भारत का सबसे बड़ा (Installed Capacity ~4760 MW) पावर प्लांट है। यह NTPC द्वारा संचालित है।

**💡 Exam Fact:** सिंगरौली को ''भारत की ऊर्जा राजधानी'' (Energy Capital) कहा जाता है।

**🧠 Memory Tip:** **Vindhyachal** is Huge (Largest).

**🚫 Scam Alert:** मुंद्रा (अडानी) भी बहुत बड़ा है, लेकिन विंध्याचल (NTPC) क्षमता में शीर्ष पर है।', 2, 0, 2, NULL, 'Which is the largest Thermal Power Plant in India?', '**✅ Correct Logic:** **Vindhyachal Thermal Power Station** (Singrauli, MP) is the largest (~4760 MW). Operated by NTPC.

**💡 Exam Fact:** Singrauli is ''Energy Capital''.

**🧠 Memory Tip:** **Vindhyachal** is Huge.

**🚫 Scam Alert:** Mundra is big, but Vindhyachal is bigger.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('06c77883-7c6e-4e9f-9fba-b0c38946f1be', '58d7a3a6-563d-4cf7-b7c7-d86c3cdaaa62', '''तलचर'' (Talcher) और ''एंनोर'' (Ennore) किस प्रकार के ऊर्जा संयंत्रों के लिए जाने जाते हैं?', '[{"id":"A","text":"परमाणु (Nuclear)","text_en":"परमाणु (Nuclear)"},{"id":"B","text":"तापीय / कोयला (Thermal / Coal)","text_en":"तापीय / कोयला (Thermal / Coal)"},{"id":"C","text":"भू-तापीय (Geothermal)","text_en":"भू-तापीय (Geothermal)"},{"id":"D","text":"पवन (Wind)","text_en":"पवन (Wind)"}]', '1', '**✅ Correct Logic:** तलचर (ओडिशा) और एंनोर (तमिलनाडु) प्रसिद्ध **थर्मल पावर स्टेशन** (Thermal Power Stations) हैं। तलचर कोयला क्षेत्र के लिए भी प्रसिद्ध है।

**💡 Exam Fact:** एंनोर भारत का पहला प्रमुख बंदरगाह है जो एक पब्लिक कंपनी (कॉर्पोरेट) है।

**🧠 Memory Tip:** **T**alcher = **T**hermal.

**🚫 Scam Alert:** कल्पक्कम (TN) परमाणु है, एंनोर थर्मल है।', 2, 0, 3, NULL, 'What type of power plants are ''Talcher'' and ''Ennore'' known for?', '**✅ Correct Logic:** Talcher (Odisha) and Ennore (TN) are famous **Thermal Power Stations**.

**💡 Exam Fact:** Talcher is also a coal field.

**🧠 Memory Tip:** **T**alcher = **T**hermal.

**🚫 Scam Alert:** Kalpakkam is Nuclear, Ennore is Thermal.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5e1ff14c-ff6d-44b6-9f0b-6f465c5345e6', '58d7a3a6-563d-4cf7-b7c7-d86c3cdaaa62', 'भारत में परमाणु ऊर्जा कार्यक्रम (Nuclear Energy Program) के जनक कौन थे?', '[{"id":"A","text":"सी.वी. रमन (C.V. Raman)","text_en":"सी.वी. रमन (C.V. Raman)"},{"id":"B","text":"होमी जहांगीर भाभा (Homi Jehangir Bhabha)","text_en":"होमी जहांगीर भाभा (Homi Jehangir Bhabha)"},{"id":"C","text":"विक्रम साराभाई (Vikram Sarabhai)","text_en":"विक्रम साराभाई (Vikram Sarabhai)"},{"id":"D","text":"ए.पी.जे. अब्दुल कलाम (A.P.J. Abdul Kalam)","text_en":"ए.पी.जे. अब्दुल कलाम (A.P.J. Abdul Kalam)"}]', '1', '**✅ Correct Logic:** **होमी जे. भाभा** भारत के परमाणु कार्यक्रम के जनक हैं। उन्होंने 3-चरण (3-stage) परमाणु कार्यक्रम (यूरेनियम -> प्लूटोनियम -> थोरियम) तैयार किया था।

**💡 Exam Fact:** BARC (Bhabha Atomic Research Centre) ट्रॉम्बे में है।

**🧠 Memory Tip:** **Bhabha** -> **B**omb (Nuclear) -> Energy.

**🚫 Scam Alert:** साराभाई ''अंतरिक्ष'' (Space) के जनक हैं। कलाम ''मिसाइल'' मैन हैं।', 2, 0, 4, NULL, 'Who was the father of Nuclear Energy Program in India?', '**✅ Correct Logic:** **Homi J. Bhabha** is the father. Designed the 3-stage program.

**💡 Exam Fact:** BARC is in Trombay.

**🧠 Memory Tip:** **Bhabha** -> Nuclear.

**🚫 Scam Alert:** Sarabhai = Space. Kalam = Missile. Bhabha = Nuclear.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ca27e0a9-9587-48ac-b485-107ab8bfa3d7', '58d7a3a6-563d-4cf7-b7c7-d86c3cdaaa62', 'कुडनकुलम परमाणु ऊर्जा संयंत्र (Kudankulam Nuclear Power Plant) किस देश के सहयोग से बनाया गया है?', '[{"id":"A","text":"संयुक्त राज्य अमेरिका (USA)","text_en":"संयुक्त राज्य अमेरिका (USA)"},{"id":"B","text":"फ्रांस (France)","text_en":"फ्रांस (France)"},{"id":"C","text":"रूस (Russia)","text_en":"रूस (Russia)"},{"id":"D","text":"कनाडा (Canada)","text_en":"कनाडा (Canada)"}]', '2', '**✅ Correct Logic:** कुडनकुलम (तमिलनाडु) **रूस** के सहयोग से बनाया गया है। यह भारत का सबसे बड़ा (क्षमता में) परमाणु संयंत्र है।

**💡 Exam Fact:** जैतापुर (महाराष्ट्र) फ्रांस के सहयोग से प्रस्तावित है।

**🧠 Memory Tip:** **Rus**sia is a friend, gave **Kud**ankulam.

**🚫 Scam Alert:** तारापुर (USA) था, कुडनकुलम (Russia) है।', 2, 0, 5, NULL, 'Kudankulam Nuclear Power Plant was built with the cooperation of which country?', '**✅ Correct Logic:** Kudankulam (TN) built with **Russia**. It is India''s largest nuclear plant.

**💡 Exam Fact:** Jaitapur (MH) is proposed with France.

**🧠 Memory Tip:** **Rus**sia -> **Kud**ankulam.

**🚫 Scam Alert:** Tarapur was USA. Kudankulam is Russia.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bb91cff0-7c0b-4e83-a1db-0226595ee9f7', '58d7a3a6-563d-4cf7-b7c7-d86c3cdaaa62', 'भारत में लिग्नाइट कोयले (Lignite Coal) का सबसे बड़ा भंडार किस राज्य में है?', '[{"id":"A","text":"झारखंड (Jharkhand)","text_en":"झारखंड (Jharkhand)"},{"id":"B","text":"तमिलनाडु (Tamil Nadu)","text_en":"तमिलनाडु (Tamil Nadu)"},{"id":"C","text":"राजस्थान (Rajasthan)","text_en":"राजस्थान (Rajasthan)"},{"id":"D","text":"गुजरात (Gujarat)","text_en":"गुजरात (Gujarat)"}]', '1', '**✅ Correct Logic:** **तमिलनाडु** (नेवेली) में भारत के लिग्नाइट (भूरा कोयला) भंडार का 80% से अधिक हिस्सा है।

**💡 Exam Fact:** लिग्नाइट निम्न गुणवत्ता का कोयला होता है (High moisture).

**🧠 Memory Tip:** **T**amil Nadu -> **T**op in Lignite.

**🚫 Scam Alert:** सामान्य कोयला (Bituminous) झारखंड में है, लिग्नाइट तमिलनाडु में है।', 2, 0, 6, NULL, 'Which state has the largest reserves of Lignite Coal in India?', '**✅ Correct Logic:** **Tamil Nadu** (Neyveli) holds 80%+ of Lignite reserves.

**💡 Exam Fact:** Lignite is Brown Coal.

**🧠 Memory Tip:** **T**amil Nadu -> **T**op in Lignite.

**🚫 Scam Alert:** Normal coal is Jharkhand. Lignite is TN.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f5e33e17-741e-4ef7-8c6a-2146c74c2cb8', '58d7a3a6-563d-4cf7-b7c7-d86c3cdaaa62', '''फ़्लाइ ऐश'' (Fly Ash) किसका उप-उत्पाद (By-product) है, जो पर्यावरण प्रदूषण का कारण बनता है?', '[{"id":"A","text":"पनबिजली संयंत्र (Hydro Power Plant)","text_en":"पनबिजली संयंत्र (Hydro Power Plant)"},{"id":"B","text":"कोयला आधारित ताप विद्युत संयंत्र (Coal based Thermal Power Plant)","text_en":"कोयला आधारित ताप विद्युत संयंत्र (Coal based Thermal Power Plant)"},{"id":"C","text":"परमाणु संयंत्र (Nuclear Plant)","text_en":"परमाणु संयंत्र (Nuclear Plant)"},{"id":"D","text":"पवन चक्कियां (Windmills)","text_en":"पवन चक्कियां (Windmills)"}]', '1', '**✅ Correct Logic:** **कोयला आधारित थर्मल प्लांट** में कोयला जलने के बाद जो महीन राख (Ash) निकलती है और हवा में उड़ती है, उसे फ्लाई ऐश कहते हैं। इसका उपयोग ईंट/सीमेंट बनाने में होता है।

**💡 Exam Fact:** सरकार ने 100% फ्लाई ऐश उपयोग (Utilization) अनिवार्य कर दिया है।

**🧠 Memory Tip:** Coal burns -> **Ash** flies.

**🚫 Scam Alert:** यह धुएं में उड़ती है, इसलिए ''Fly'' Ash कहते हैं।', 2, 0, 7, NULL, '''Fly Ash'' is a by-product of what, causing environmental pollution?', '**✅ Correct Logic:** Fine ash produced by burning **Coal in Thermal Plants**. Used in bricks/cement.

**💡 Exam Fact:** Govt mandated 100% utilization.

**🧠 Memory Tip:** Coal burns -> **Ash** flies.

**🚫 Scam Alert:** Only from Coal plants.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b3e2e57d-5632-4463-86be-1bb1cc8d3cde', '58d7a3a6-563d-4cf7-b7c7-d86c3cdaaa62', 'भारत का पहला परमाणु ऊर्जा स्टेशन (First Nuclear Power Station) कहाँ स्थापित किया गया था?', '[{"id":"A","text":"रावतभाटा (Rawatbhata)","text_en":"रावतभाटा (Rawatbhata)"},{"id":"B","text":"तारापुर (Tarapur)","text_en":"तारापुर (Tarapur)"},{"id":"C","text":"नरोरा (Narora)","text_en":"नरोरा (Narora)"},{"id":"D","text":"काकरापार (Kakrapar)","text_en":"काकरापार (Kakrapar)"}]', '1', '**✅ Correct Logic:** **तारापुर** (महाराष्ट्र) भारत का पहला परमाणु ऊर्जा स्टेशन था (1969 में शुरू)। यह अमेरिका (GE) के सहयोग से बना था।

**💡 Exam Fact:** रावतभाटा (राजस्थान) दूसरा था (कनाडा के सहयोग से)।

**🧠 Memory Tip:** **Tara** (Star) was the first light.

**🚫 Scam Alert:** अप्सरा (Apsara) पहला ''रिएक्टर'' (शोध) था, लेकिन तारापुर पहला बिजली ''स्टेशन'' (Commercial) था।', 2, 0, 8, NULL, 'Where was India''s first Nuclear Power Station established?', '**✅ Correct Logic:** **Tarapur** (Maharashtra) was the first (1969). Built with USA help.

**💡 Exam Fact:** Rawatbhata was second.

**🧠 Memory Tip:** **Tara** (Star) was first.

**🚫 Scam Alert:** Apsara was Research Reactor. Tarapur was Power Station.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6e07674d-5800-4a9b-97f1-2a84d265890b', '58d7a3a6-563d-4cf7-b7c7-d86c3cdaaa62', 'प्राकृतिक गैस (Natural Gas) के परिवहन के लिए प्रसिद्ध ''HBJ पाइपलाइन'' में ''B'' का क्या अर्थ है?', '[{"id":"A","text":"बड़ौदा (Baroda)","text_en":"बड़ौदा (Baroda)"},{"id":"B","text":"बॉम्बे (Bombay)","text_en":"बॉम्बे (Bombay)"},{"id":"C","text":"बीजापुर (Bijapur)","text_en":"बीजापुर (Bijapur)"},{"id":"D","text":"बेंगलुरु (Bengaluru)","text_en":"बेंगलुरु (Bengaluru)"}]', '2', '**✅ Correct Logic:** HBJ का अर्थ है: **हजीरा** (गुजरात) - **बीजापुर** (विजयपुर, मध्य प्रदेश) - **जगदीशपुर** (उत्तर प्रदेश)। यह भारत की पहली क्रॉस-स्टेट गैस पाइपलाइन है, जो GAIL द्वारा संचालित है।

**💡 Exam Fact:** अब इसे HVJ (विजयपुर) भी लिखते हैं, लेकिन पुराना नाम HBJ है।

**🧠 Memory Tip:** **H**azira - **B**ijapur - **J**agdishpur.

**🚫 Scam Alert:** बीजापुर (कर्नाटक वाला) नहीं, यह MP में गुना जिले का विजयपुर है।', 2, 0, 9, NULL, 'What does ''B'' stand for in the famous ''HBJ Pipeline'' for natural gas transportation?', '**✅ Correct Logic:** **Hazira** (GJ) - **Bijapur/Vijaipur** (MP) - **Jagdishpur** (UP). Operated by GAIL.

**💡 Exam Fact:** First cross-state gas pipeline.

**🧠 Memory Tip:** HBJ.

**🚫 Scam Alert:** Not Bijapur of Karnataka. It''s Vijaipur in MP.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d81a0065-ad4f-4c20-8427-0bfdcd94369f', '58d7a3a6-563d-4cf7-b7c7-d86c3cdaaa62', 'निम्नलिखित परमाणु ऊर्जा संयंत्रों को उनके राज्यों से सुमेलित करें (Match the following Nuclear Power Plants with their states):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **कैगा**: कर्नाटक (काली नदी के पास)। -> (1)-(a)
* **नरोरा**: उत्तर प्रदेश (गंगा तट पर, बुलंदशहर)। -> (2)-(b)
* **काकरापार**: गुजरात (ताप्ती नदी)। -> (3)-(c)
* **रावतभाटा**: राजस्थान (कोटा के पास, राणा प्रताप सागर)। -> (4)-(d)

**💡 Exam Fact:** काकरापार-3 भारत का पहला स्वदेशी 700 MWe रिएक्टर है।

**🧠 Memory Tip:** **K**aiga-**K**arnataka. **Na**rora-**N**orth (UP). **Kak**rapar-**G**ujju (Khakra snack). **Ra**watbhata-**Ra**jasthan.

**🚫 Scam Alert:** नरोरा (UP) और कलपक्कम (TN) में कंफ्यूज न हों।', 2, 0, 10, NULL, 'Match the following Nuclear Power Plants with their states:', '**✅ Correct Matching:**
* **Kaiga**: Karnataka. -> (1)-(a)
* **Narora**: UP. -> (2)-(b)
* **Kakrapar**: Gujarat. -> (3)-(c)
* **Rawatbhata**: Rajasthan. -> (4)-(d)

**💡 Exam Fact:** Kakrapar-3 is first indigenous 700 MWe.

**🧠 Memory Tip:** **K**aiga-**K**arnataka. **Kak**rapar-**G**ujju.

**🚫 Scam Alert:** Easy but high value.', 60, 'matching', '[{"id":"(1)","label":"कैगा (Kaiga)","match":"कर्नाटक (Karnataka)","matchId":"(a)"},{"id":"(2)","label":"नरोरा (Narora)","match":"उत्तर प्रदेश (Uttar Pradesh)","matchId":"(b)"},{"id":"(3)","label":"काकरापार (Kakrapar)","match":"गुजरात (Gujarat)","matchId":"(c)"},{"id":"(4)","label":"रावतभाटा (Rawatbhata)","match":"राजस्थान (Rajasthan)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0c733f13-c5be-40ab-9337-0fd5fe355940', 'b304fcdd-ab2b-4f48-ab6b-e6a0afd9b13f', 'अंतर्राष्ट्रीय सौर गठबंधन (ISA) का मुख्यालय कहाँ स्थित है?', '[{"id":"A","text":"पेरिस, फ्रांस (Paris, France)","text_en":"पेरिस, फ्रांस (Paris, France)"},{"id":"B","text":"गुरुग्राम, भारत (Gurugram, India)","text_en":"गुरुग्राम, भारत (Gurugram, India)"},{"id":"C","text":"न्यूयॉर्क, यूएसए (New York, USA)","text_en":"न्यूयॉर्क, यूएसए (New York, USA)"},{"id":"D","text":"नई दिल्ली, भारत (New Delhi, India)","text_en":"नई दिल्ली, भारत (New Delhi, India)"}]', '1', '**✅ Correct Logic:** ISA का मुख्यालय **गुरुग्राम** (हरियाणा), भारत में है। यह भारत (मोदी) और फ्रांस की संयुक्त पहल (2015) है।

**💡 Exam Fact:** यह भारत में स्थित मुख्यालय वाला पहला बड़ा अंतर्राष्ट्रीय संगठन है।

**🧠 Memory Tip:** **Guru** of Sun is in **Guru**gram.

**🚫 Scam Alert:** पेरिस में इसकी घोषणा (COP21) हुई थी, लेकिन मुख्यालय गुरुग्राम में है।', 2, 0, 1, NULL, 'Where is the headquarters of the International Solar Alliance (ISA) located?', '**✅ Correct Logic:** HQ is in **Gurugram** (India). Joint initiative of India & France (2015).

**💡 Exam Fact:** First major international org with HQ in India.

**🧠 Memory Tip:** **Guru** of Sun -> **Guru**gram.

**🚫 Scam Alert:** Announced in Paris, HQ in Gurugram.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6f8bb727-aa4e-46f2-bdd7-2848be7582be', 'b304fcdd-ab2b-4f48-ab6b-e6a0afd9b13f', 'भारत का सबसे बड़ा सौर ऊर्जा पार्क (Solar Power Park), ''भड़ला'' (Bhadla), किस राज्य में स्थित है?', '[{"id":"A","text":"गुजरात (Gujarat)","text_en":"गुजरात (Gujarat)"},{"id":"B","text":"राजस्थान (Rajasthan)","text_en":"राजस्थान (Rajasthan)"},{"id":"C","text":"मध्य प्रदेश (Madhya Pradesh)","text_en":"मध्य प्रदेश (Madhya Pradesh)"},{"id":"D","text":"कर्नाटक (Karnataka)","text_en":"कर्नाटक (Karnataka)"}]', '1', '**✅ Correct Logic:** **भड़ला सोलर पार्क** (जोधपुर, राजस्थान) न केवल भारत बल्कि दुनिया के सबसे बड़े सोलर पार्कों में से एक है (क्षमता > 2245 MW)।

**💡 Exam Fact:** रीवा (MP) में 750 MW का ''सिंगल साइट'' सोलर प्लांट है, लेकिन भड़ला ''पार्क'' (Cluster) के रूप में सबसे बड़ा है।

**🧠 Memory Tip:** Sun burns badly in **Bhadla** (Rajasthan).

**🚫 Scam Alert:** पावागढ़ (कर्नाटक) भी बड़ा है, लेकिन वर्तमान डेटा में भड़ला शीर्ष पर है।', 2, 0, 2, NULL, 'India''s largest Solar Power Park, ''Bhadla'', is located in which state?', '**✅ Correct Logic:** **Bhadla** (Jodhpur, Rajasthan) is the largest Solar Park (>2245 MW).

**💡 Exam Fact:** Rewa (MP) is famous, but Bhadla is bigger.

**🧠 Memory Tip:** Sun burns in **Bhadla**.

**🚫 Scam Alert:** Pavagada (Karnataka) is also huge, but Bhadla is current topper.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b35ec35c-b10a-4470-b1af-d7289305b5c1', 'b304fcdd-ab2b-4f48-ab6b-e6a0afd9b13f', 'पवन ऊर्जा (Wind Energy) की स्थापित क्षमता (Installed Capacity) के मामले में भारत का कौन सा राज्य शीर्ष पर है?', '[{"id":"A","text":"तमिलनाडु (Tamil Nadu)","text_en":"तमिलनाडु (Tamil Nadu)"},{"id":"B","text":"गुजरात (Gujarat)","text_en":"गुजरात (Gujarat)"},{"id":"C","text":"महाराष्ट्र (Maharashtra)","text_en":"महाराष्ट्र (Maharashtra)"},{"id":"D","text":"राजस्थान (Rajasthan)","text_en":"राजस्थान (Rajasthan)"}]', '1', '**✅ Correct Logic:** वर्तमान आंकड़ों (MNRE) के अनुसार, **गुजरात** ने तमिलनाडु को पीछे छोड़ दिया है और पवन ऊर्जा क्षमता में शीर्ष स्थान हासिल किया है। *Note: Data fluctuates, but Gujarat passed TN recently.* 
*Correction:* 2023-24 के आंकड़ों में **गुजरात** और तमिलनाडु में कड़ी टक्कर है। गुजरात नंबर 1 बन गया है।

**💡 Exam Fact:** मुप्पंडल (तमिलनाडु) में सबसे बड़ा ''विंड फार्म'' (एक स्थान पर) है।

**🧠 Memory Tip:** **G**ujarat -> **G**usty winds.

**🚫 Scam Alert:** ऐतिहासिक रूप से तमिलनाडु नंबर 1 था, लेकिन अब गुजरात है। अपडेट रहें।', 2, 0, 3, NULL, 'Which state of India tops in terms of Installed Capacity of Wind Energy?', '**✅ Correct Logic:** As per recent data, **Gujarat** has overtaken TN to become No. 1 in Wind Energy capacity.

**💡 Exam Fact:** Muppandal (TN) has the largest Wind Farm cluster.

**🧠 Memory Tip:** **G**ujarat -> **G**usty winds.

**🚫 Scam Alert:** Historically TN was top, now Gujarat. Stay updated.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fb538898-abaf-42a4-b419-f2e134a2f9b4', 'b304fcdd-ab2b-4f48-ab6b-e6a0afd9b13f', 'ओशिन थर्मल एनर्जी कन्वर्जन (OTEC) संयंत्र भारत में कहाँ स्थापित किया गया है?', '[{"id":"A","text":"कवारत्ती, लक्षद्वीप (Kavaratti, Lakshadweep)","text_en":"कवारत्ती, लक्षद्वीप (Kavaratti, Lakshadweep)"},{"id":"B","text":"चेन्नई, तमिलनाडु (Chennai, Tamil Nadu)","text_en":"चेन्नई, तमिलनाडु (Chennai, Tamil Nadu)"},{"id":"C","text":"विशाखापत्तनम, आंध्र प्रदेश (Visakhapatnam, AP)","text_en":"विशाखापत्तनम, आंध्र प्रदेश (Visakhapatnam, AP)"},{"id":"D","text":"ओखा, गुजरात (Okha, Gujarat)","text_en":"ओखा, गुजरात (Okha, Gujarat)"}]', '0', '**✅ Correct Logic:** **कवारत्ती** (लक्षद्वीप) में दुनिया का पहला OTEC संयंत्र (Desalination के साथ) स्थापित किया गया है। यह समुद्र की सतह के गर्म पानी और गहरे ठंडे पानी के तापमान अंतर का उपयोग करता है।

**💡 Exam Fact:** यह NIOT (National Institute of Ocean Technology) द्वारा बनाया गया है।

**🧠 Memory Tip:** **O**cean energy in island **Kavaratti**.

**🚫 Scam Alert:** ज्वारीय ऊर्जा (Tidal) गुजरात में है, लेकिन OTEC लक्षद्वीप में है।', 2, 0, 4, NULL, 'Where has the Ocean Thermal Energy Conversion (OTEC) plant been established in India?', '**✅ Correct Logic:** Established in **Kavaratti** (Lakshadweep). Uses temp difference between surface and deep water.

**💡 Exam Fact:** Built by NIOT.

**🧠 Memory Tip:** **O**cean energy in **Kavaratti**.

**🚫 Scam Alert:** Tidal is Gujarat. OTEC is Lakshadweep.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('419f04de-2247-456b-88e0-46a53d6b3218', 'b304fcdd-ab2b-4f48-ab6b-e6a0afd9b13f', 'भारत में ''भू-तापीय ऊर्जा'' (Geothermal Energy) की संभावना वाला क्षेत्र ''पुगा घाटी'' (Puga Valley) कहाँ स्थित है?', '[{"id":"A","text":"मणिकरण, हिमाचल प्रदेश (Manikaran, HP)","text_en":"मणिकरण, हिमाचल प्रदेश (Manikaran, HP)"},{"id":"B","text":"लद्दाख (Ladakh)","text_en":"लद्दाख (Ladakh)"},{"id":"C","text":"तपोवन, उत्तराखंड (Tapovan, UK)","text_en":"तपोवन, उत्तराखंड (Tapovan, UK)"},{"id":"D","text":"सूरजकुंड, झारखंड (Surajkund, Jharkhand)","text_en":"सूरजकुंड, झारखंड (Surajkund, Jharkhand)"}]', '1', '**✅ Correct Logic:** **पुगा घाटी** **लद्दाख** में स्थित है। यहाँ ONGC भारत का पहला भू-तापीय क्षेत्र विकास परियोजना (Geothermal Field Development Project) स्थापित कर रहा है।

**💡 Exam Fact:** मणिकरण (HP) भी गर्म पानी के झरनों के लिए प्रसिद्ध है।

**🧠 Memory Tip:** **Puga** is in **Leh** (Ladakh).

**🚫 Scam Alert:** मणिकरण में भी संभावना है, लेकिन पहली बड़ी परियोजना पुगा (लद्दाख) में आ रही है।', 2, 0, 5, NULL, 'Where is ''Puga Valley'', a potential site for Geothermal Energy in India, located?', '**✅ Correct Logic:** **Puga Valley** is in **Ladakh**. ONGC is setting up India''s first Geothermal project here.

**💡 Exam Fact:** Manikaran (HP) is also famous for hot springs.

**🧠 Memory Tip:** **Puga** is in **Leh**.

**🚫 Scam Alert:** Manikaran is a site, but Puga is the main project site now.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cff34685-2ea0-4d2f-afc2-1bedc0771bf4', 'b304fcdd-ab2b-4f48-ab6b-e6a0afd9b13f', 'राष्ट्रीय हाइड्रोजन मिशन (National Hydrogen Mission) के तहत, भारत किस वर्ष तक ''ऊर्जा स्वतंत्र'' (Energy Independent) बनने का लक्ष्य रखता है?', '[{"id":"A","text":"2030","text_en":"2030"},{"id":"B","text":"2047","text_en":"2047"},{"id":"C","text":"2050","text_en":"2050"},{"id":"D","text":"2070","text_en":"2070"}]', '1', '**✅ Correct Logic:** भारत ने अपनी स्वतंत्रता के 100 वर्ष पूरे होने पर, यानी **2047** तक ऊर्जा स्वतंत्र बनने का लक्ष्य रखा है। इसमें ग्रीन हाइड्रोजन बड़ी भूमिका निभाएगा।

**💡 Exam Fact:** 2070 तक ''Net Zero'' (कार्बन तटस्थता) का लक्ष्य है।

**🧠 Memory Tip:** 1947 + 100 = **2047** (Independence in Energy).

**🚫 Scam Alert:** 2070 नेट जीरो है। 2030 रेलवे नेट जीरो है। 2047 ऊर्जा स्वतंत्रता है।', 2, 0, 6, NULL, 'Under National Hydrogen Mission, India aims to become ''Energy Independent'' by which year?', '**✅ Correct Logic:** Aim is **2047** (100 years of Independence). Green Hydrogen is key.

**💡 Exam Fact:** 2070 is Net Zero target.

**🧠 Memory Tip:** 1947 + 100 = **2047**.

**🚫 Scam Alert:** 2070 is Net Zero. 2047 is Energy Independent.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('064af9f9-fcb5-4234-8253-bc3bbecdb1e7', 'b304fcdd-ab2b-4f48-ab6b-e6a0afd9b13f', 'कोचीन इंटरनेशनल एयरपोर्ट (Cial) की क्या खास बात है, जो उसे वैश्विक स्तर पर प्रसिद्ध बनाती है?', '[{"id":"A","text":"यह दुनिया का सबसे बड़ा एयरपोर्ट है","text_en":"यह दुनिया का सबसे बड़ा एयरपोर्ट है"},{"id":"B","text":"यह दुनिया का पहला पूर्णतः सौर ऊर्जा संचालित एयरपोर्ट है (World''s first fully solar powered airport)","text_en":"यह दुनिया का पहला पूर्णतः सौर ऊर्जा संचालित एयरपोर्ट है (World''s first fully solar powered airport)"},{"id":"C","text":"यह सबसे ऊंचाई पर स्थित एयरपोर्ट है","text_en":"यह सबसे ऊंचाई पर स्थित एयरपोर्ट है"},{"id":"D","text":"यहाँ केवल कार्गो विमान आते हैं","text_en":"यहाँ केवल कार्गो विमान आते हैं"}]', '1', '**✅ Correct Logic:** कोचीन एयरपोर्ट (केरल) दुनिया का **पहला पूर्णतः सौर ऊर्जा संचालित** (Fully Solar Powered) हवाई अड्डा है। इसे इसके लिए संयुक्त राष्ट्र (UN) से ''चैंपियन ऑफ द अर्थ'' पुरस्कार मिला है।

**💡 Exam Fact:** अब रीवा (MP) की सौर ऊर्जा से दिल्ली मेट्रो चलती है।

**🧠 Memory Tip:** Cochin = **C**ool **S**un (Solar).

**🚫 Scam Alert:** भारत में कई ग्रीन एयरपोर्ट हैं, लेकिन ''पहला पूर्णतः सौर'' कोचीन है।', 2, 0, 7, NULL, 'What is the unique feature of Cochin International Airport (CIAL) that makes it globally famous?', '**✅ Correct Logic:** World''s **first fully solar powered** airport. Got UN ''Champion of the Earth'' award.

**💡 Exam Fact:** Delhi Metro runs on Rewa Solar power.

**🧠 Memory Tip:** Cochin = Solar.

**🚫 Scam Alert:** Many are green, CIAL was first 100% solar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f403442e-7a05-490c-86a0-8f064d2c21d1', 'b304fcdd-ab2b-4f48-ab6b-e6a0afd9b13f', 'बायोमास से ऊर्जा उत्पादन में गन्ने की खोई (Bagasse) का उपयोग किस विधि में किया जाता है?', '[{"id":"A","text":"को-जनरेशन (Co-generation)","text_en":"को-जनरेशन (Co-generation)"},{"id":"B","text":"गैसीकरण (Gasification)","text_en":"गैसीकरण (Gasification)"},{"id":"C","text":"एनाएरोबिक पाचन (Anaerobic Digestion)","text_en":"एनाएरोबिक पाचन (Anaerobic Digestion)"},{"id":"D","text":"बायो-डीजल (Bio-diesel)","text_en":"बायो-डीजल (Bio-diesel)"}]', '0', '**✅ Correct Logic:** चीनी मिलों में गन्ने की खोई (Bagasse) को जलाकर भाप बनाई जाती है जिससे बिजली और गर्मी दोनों मिलती है। इसे **को-जनरेशन** (Co-generation) कहते हैं।

**💡 Exam Fact:** ब्राजील में गन्ने से इथेनॉल (Bio-fuel) बड़े पैमाने पर बनता है।

**🧠 Memory Tip:** Sugar mills generate **Co**-power (Sugar + Power).

**🚫 Scam Alert:** बायो-डीजल जेट्रोफा से बनता है, गन्ने से इथेनॉल या को-जनरेशन होता है।', 2, 0, 8, NULL, 'In biomass energy production, Bagasse (sugarcane residue) is used in which method?', '**✅ Correct Logic:** Burning Bagasse to produce both Heat and Electricity in sugar mills is called **Co-generation**.

**💡 Exam Fact:** Brazil uses sugarcane for Ethanol.

**🧠 Memory Tip:** Sugar mills = Co-generation.

**🚫 Scam Alert:** Bio-diesel is Jatropha. Bagasse is Co-generation.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e111691e-94e7-46be-bba0-e200d5bdbdc7', 'b304fcdd-ab2b-4f48-ab6b-e6a0afd9b13f', 'भारत में ''ज्वारीय ऊर्जा'' (Tidal Energy) की सर्वाधिक संभावना किस स्थान पर है?', '[{"id":"A","text":"खंभात की खाड़ी (Gulf of Khambhat)","text_en":"खंभात की खाड़ी (Gulf of Khambhat)"},{"id":"B","text":"कच्छ की खाड़ी (Gulf of Kutch)","text_en":"कच्छ की खाड़ी (Gulf of Kutch)"},{"id":"C","text":"सुंदरबन (Sundarbans)","text_en":"सुंदरबन (Sundarbans)"},{"id":"D","text":"मन्नार की खाड़ी (Gulf of Mannar)","text_en":"मन्नार की खाड़ी (Gulf of Mannar)"}]', '0', '**✅ Correct Logic:** **खंभात की खाड़ी** (गुजरात) में ज्वारीय ऊर्जा की क्षमता सबसे अधिक (लगभग 7000 MW) है, इसके बाद कच्छ की खाड़ी (1200 MW) और सुंदरबन का स्थान है। संकरी खाड़ी और ऊंचे ज्वार इसे आदर्श बनाते हैं।

**💡 Exam Fact:** फ्रांस में दुनिया का पहला ज्वारीय ऊर्जा संयंत्र बना था।

**🧠 Memory Tip:** **Khambhat** is King of Tides.

**🚫 Scam Alert:** कच्छ भी अच्छा है, लेकिन खंभात की क्षमता ज्यादा है।', 2, 0, 9, NULL, 'Which location has the maximum potential for ''Tidal Energy'' in India?', '**✅ Correct Logic:** **Gulf of Khambhat** (Gujarat) has the highest potential (~7000 MW), followed by Kutch and Sundarbans.

**💡 Exam Fact:** France built the first Tidal plant.

**🧠 Memory Tip:** **Khambhat** is King.

**🚫 Scam Alert:** Kutch is good, Khambhat is better.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('104e0949-40c3-4bae-87df-aa6f8e5e1b1b', 'b304fcdd-ab2b-4f48-ab6b-e6a0afd9b13f', 'निम्नलिखित नवीकरणीय ऊर्जा परियोजनाओं को उनके स्थान से सुमेलित करें (Match the renewable energy projects with their location):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **रीवा**: मध्य प्रदेश (750 MW, एशिया का बड़ा सिंगल साइट)। -> (1)-(a)
* **मुप्पंडल**: तमिलनाडु (पवन ऊर्जा का बड़ा केंद्र)। -> (2)-(b)
* **पावागढ़**: कर्नाटक (शक्ति स्थल, दुनिया के सबसे बड़े पार्कों में से एक)। -> (3)-(c)
* **चारणका**: गुजरात (पाटन जिला, भारत का पहला बड़ा सोलर पार्क)। -> (4)-(d)

**💡 Exam Fact:** रीवा प्रोजेक्ट को वर्ल्ड बैंक का प्रेसिडेंट अवार्ड मिला था।

**🧠 Memory Tip:** **Rewa**-MP. **Muppandal**-TN. **Pavagada**-KA. **Charanka**-GJ.

**🚫 Scam Alert:** स्थान और राज्य का मिलान अक्सर पूछा जाता है।', 2, 0, 10, NULL, 'Match the renewable energy projects with their location:', '**✅ Correct Matching:**
* **Rewa**: MP. -> (1)-(a)
* **Muppandal**: TN. -> (2)-(b)
* **Pavagada**: Karnataka. -> (3)-(c)
* **Charanka**: Gujarat. -> (4)-(d)

**💡 Exam Fact:** Rewa project powers Delhi Metro.

**🧠 Memory Tip:** Direct state match.

**🚫 Scam Alert:** High yield matching.', 60, 'matching', '[{"id":"(1)","label":"रीवा अल्ट्रा मेगा सोलर (Rewa Solar)","match":"मध्य प्रदेश (Madhya Pradesh)","matchId":"(a)"},{"id":"(2)","label":"मुप्पंडल विंड फार्म (Muppandal Wind)","match":"तमिलनाडु (Tamil Nadu)","matchId":"(b)"},{"id":"(3)","label":"पावागढ़ सोलर पार्क (Pavagada Solar)","match":"कर्नाटक (Karnataka)","matchId":"(c)"},{"id":"(4)","label":"चारणका सोलर पार्क (Charanka Solar)","match":"गुजरात (Gujarat)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ba5c2257-5594-44d5-b87b-3ad9538b20e2', 'c2953a8f-68e4-42f9-a42d-fbf71a6055a4', 'मध्य प्रदेश का पहला ''ताप विद्युत केंद्र'' (Thermal Power Plant) कौन सा है?', '[{"id":"A","text":"चांदनी ताप विद्युत केंद्र","text_en":"चांदनी ताप विद्युत केंद्र"},{"id":"B","text":"अमरकंटक ताप विद्युत केंद्र","text_en":"अमरकंटक ताप विद्युत केंद्र"},{"id":"C","text":"सतपुड़ा ताप विद्युत केंद्र","text_en":"सतपुड़ा ताप विद्युत केंद्र"},{"id":"D","text":"विंध्याचल ताप विद्युत केंद्र","text_en":"विंध्याचल ताप विद्युत केंद्र"}]', '0', '✅ **Correct Logic**: चांदनी ताप विद्युत केंद्र (नेपानगर, बुरहानपुर) की स्थापना 1953 में हुई थी। यह राज्य का पहला थर्मल प्लांट है।
💡 **Exam Fact**: इसकी स्थापना मुख्य रूप से नेपा पेपर मिल को बिजली आपूर्ति के लिए की गई थी।
🧠 **Memory Tip**: First light came from ''Chandni'' (Moonlight).
🚫 **Scam Alert**: विंध्याचल सबसे बड़ा है, लेकिन चांदनी सबसे पहला है।', 2, 0, 1, NULL, 'Which is the first Thermal Power Plant of Madhya Pradesh?', '✅ **Correct Logic**: Chandni Thermal Power Station (Nepanagar, Burhanpur) was established in 1953 as the first thermal plant of the state.
💡 **Exam Fact**: It was primarily setup to provide power to the NEPA newsprint mill.
🧠 **Memory Tip**: The first power came from ''Chandni'' (Moonlight).
🚫 **Scam Alert**: Vindhyachal is the largest, but Chandni is the first.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('27654bd5-2cfe-41bb-95ef-25b256ede153', 'c2953a8f-68e4-42f9-a42d-fbf71a6055a4', 'मध्य प्रदेश के किस जिले में ''रीवा अल्ट्रा मेगा सोलर'' (RUMS) परियोजना स्थित है, जिसकी क्षमता 750 मेगावाट है?', '[{"id":"A","text":"रीवा (गुढ़ तहसील)","text_en":"रीवा (गुढ़ तहसील)"},{"id":"B","text":"सतना","text_en":"सतना"},{"id":"C","text":"सीधी","text_en":"सीधी"},{"id":"D","text":"सिंगरौली","text_en":"सिंगरौली"}]', '0', '✅ **Correct Logic**: यह परियोजना रीवा जिले की गुढ़ तहसील में स्थित है।
💡 **Exam Fact**: इस परियोजना से दिल्ली मेट्रो (DMRC) को भी बिजली की आपूर्ति की जाती है।
🧠 **Memory Tip**: Rewa Solar - Gud (Good) Project.
🚫 **Scam Alert**: 750 MW की कुल क्षमता 250 MW की तीन इकाइयों में विभाजित है।', 2, 0, 2, NULL, 'In which district of MP is the ''Rewa Ultra Mega Solar'' (RUMS) project located, with a capacity of 750 MW?', '✅ **Correct Logic**: The project is located in the Gudh tehsil of Rewa district.
💡 **Exam Fact**: A portion of the power generated here is supplied to the Delhi Metro (DMRC).
🧠 **Memory Tip**: Rewa Solar is a ''Gudh'' (Good) project.
🚫 **Scam Alert**: The 750 MW capacity is split into three units of 250 MW each.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3234f070-f0f0-45ff-868a-d8160abece27', 'c2953a8f-68e4-42f9-a42d-fbf71a6055a4', 'विंध्याचल ताप विद्युत केंद्र (सिंगरौली) की स्थापना में किस देश ने सहयोग किया था?', '[{"id":"A","text":"पूर्व सोवियत संघ (USSR)","text_en":"पूर्व सोवियत संघ (USSR)"},{"id":"B","text":"संयुक्त राज्य अमेरिका","text_en":"संयुक्त राज्य अमेरिका"},{"id":"C","text":"जर्मनी","text_en":"जर्मनी"},{"id":"D","text":"जापान","text_en":"जापान"}]', '0', '✅ **Correct Logic**: विंध्याचल सुपर थर्मल पावर स्टेशन की स्थापना में पूर्व सोवियत संघ (रूस) ने तकनीकी और वित्तीय सहयोग दिया था।
💡 **Exam Fact**: यह भारत का सबसे बड़ा ताप विद्युत केंद्र है (4760 MW)।
🧠 **Memory Tip**: V-R (Vindhyachal-Russia).
🚫 **Scam Alert**: सिंगरौली को ऊर्जा राजधानी कहते हैं, पर प्लांट का नाम विंध्याचल है।', 2, 0, 3, NULL, 'Which country collaborated in the establishment of the Vindhyachal Thermal Power Station (Singrauli)?', '✅ **Correct Logic**: The former Soviet Union (USSR) provided technical and financial assistance for the Vindhyachal Super Thermal Power Station.
💡 **Exam Fact**: It is the largest thermal power plant in India (4760 MW).
🧠 **Memory Tip**: V-R (Vindhyachal-Russia).
🚫 **Scam Alert**: While Singrauli is the Energy Capital, the specific plant name is Vindhyachal.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3d0d32d0-e7d9-47ae-ac70-6d425e40f912', 'c2953a8f-68e4-42f9-a42d-fbf71a6055a4', 'मध्य प्रदेश का पहला ''सौर शहर'' (Solar City) किसे घोषित किया गया है?', '[{"id":"A","text":"सांची","text_en":"सांची"},{"id":"B","text":"इंदौर","text_en":"इंदौर"},{"id":"C","text":"भोपाल","text_en":"भोपाल"},{"id":"D","text":"ग्वालियर","text_en":"ग्वालियर"}]', '0', '✅ **Correct Logic**: सांची (रायसेन) को मध्य प्रदेश की पहली सोलर सिटी के रूप में विकसित किया गया है।
💡 **Exam Fact**: यहाँ सौर ऊर्जा के माध्यम से लगभग 8 मेगावाट बिजली का उत्पादन होता है।
🧠 **Memory Tip**: S-S (Sanchi-Solar).
🚫 **Scam Alert**: सांची विश्व धरोहर भी है और अब सोलर सिटी भी।', 2, 0, 4, NULL, 'Which place has been declared as the first ''Solar City'' of Madhya Pradesh?', '✅ **Correct Logic**: Sanchi (Raisen) has been developed as the first Solar City of Madhya Pradesh.
💡 **Exam Fact**: It produces around 8 MW of electricity through solar energy.
🧠 **Memory Tip**: S-S (Sanchi-Solar).
🚫 **Scam Alert**: Sanchi is a World Heritage site and now also a Solar City.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9d5893b4-023d-435e-a6c6-259df13ad721', 'c2953a8f-68e4-42f9-a42d-fbf71a6055a4', 'ताप विद्युत केंद्रों और उनके स्थानों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: सतपुड़ा पाथरखेड़ा में है। संजय गांधी बिरसिंहपुर में। दादा धूनीवाले खंडवा में और पेन्च छिंदवाड़ा में प्रस्तावित/स्थित है।
💡 **Exam Fact**: सतपुड़ा ताप विद्युत केंद्र को राजस्थान और मध्य प्रदेश की संयुक्त परियोजना माना जाता है।
🧠 **Memory Tip**: Sanjay-Bir-Umariya (S-B-U).
🚫 **Scam Alert**: जबलपुर में बरगी जल विद्युत है, ताप विद्युत नहीं।', 2, 0, 5, NULL, 'Match the thermal power plants and their locations:', '✅ **Correct Logic**: Satpura is in Patharkheda. Sanjay Gandhi in Birsinghpur. Dada Dhuniwale in Khandwa, and Pench in Chhindwara.
💡 **Exam Fact**: Satpura Thermal Power Station is a joint venture between Rajasthan and MP.
🧠 **Memory Tip**: Sanjay-Bir-Umariya (S-B-U).
🚫 **Scam Alert**: Jabalpur has hydro-power (Bargi), not thermal.', 60, 'matching', '[{"id":"(1)","label":"सतपुड़ा ताप विद्युत केंद्र","match":"पाथरखेड़ा (बैतूल)","matchId":"(a)"},{"id":"(2)","label":"संजय गांधी ताप विद्युत केंद्र","match":"बिरसिंहपुर (उमरिया)","matchId":"(b)"},{"id":"(3)","label":"दादा धूनीवाले ताप विद्युत केंद्र","match":"खंडवा","matchId":"(c)"},{"id":"(4)","label":"पेन्च ताप विद्युत केंद्र","match":"छिंदवाड़ा","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5d9a0d47-113f-460e-8fe1-7db34228493f', 'c2953a8f-68e4-42f9-a42d-fbf71a6055a4', 'मध्य प्रदेश में ''पवन ऊर्जा'' (Wind Energy) के उत्पादन के लिए सर्वाधिक अनुकूल क्षेत्र कौन सा है?', '[{"id":"A","text":"मालवा का पठार","text_en":"मालवा का पठार"},{"id":"B","text":"बघेलखंड का पठार","text_en":"बघेलखंड का पठार"},{"id":"C","text":"नर्मदा घाटी","text_en":"नर्मदा घाटी"},{"id":"D","text":"मध्य भारत का पठार","text_en":"मध्य भारत का पठार"}]', '0', '✅ **Correct Logic**: मालवा का पठार अपनी ऊँचाई और पवन की गति के कारण पवन ऊर्जा के लिए सर्वश्रेष्ठ है। इंदौर, देवास और धार इसके मुख्य केंद्र हैं।
💡 **Exam Fact**: देवास की ''जामगोदरानी'' पहाड़ियों पर प्रदेश का पहला पवन ऊर्जा संयंत्र लगाया गया था।
🧠 **Memory Tip**: Malwa-M-Mast (Wind speed is mast/great).
🚫 **Scam Alert**: जामगोदरानी देवास में है, जो मालवा का हिस्सा है।', 2, 0, 6, NULL, 'Which region is most suitable for ''Wind Energy'' production in Madhya Pradesh?', '✅ **Correct Logic**: Malwa plateau, due to its elevation and wind speeds, is ideal for wind energy. Dewas, Indore, and Dhar are key hubs.
💡 **Exam Fact**: The state''s first wind energy plant was setup at Jamgodrani hills in Dewas.
🧠 **Memory Tip**: Wind blows ''Mast'' (Great) on ''Malwa''.
🚫 **Scam Alert**: Jamgodrani is in Dewas, which is part of Malwa.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('174244dc-4b10-4c3a-81fb-dc12e7dce916', 'c2953a8f-68e4-42f9-a42d-fbf71a6055a4', 'मध्य प्रदेश में ''बायोमास'' (Biomass) से बिजली उत्पन्न करने वाला पहला गाँव कौन सा है?', '[{"id":"A","text":"कसई गाँव (बैतूल)","text_en":"कसई गाँव (बैतूल)"},{"id":"B","text":"गुढ़ (रीवा)","text_en":"गुढ़ (रीवा)"},{"id":"C","text":"बाबई (होशंगाबाद)","text_en":"बाबई (होशंगाबाद)"},{"id":"D","text":"पिंपल्या (खंडवा)","text_en":"पिंपल्या (खंडवा)"}]', '0', '✅ **Correct Logic**: बैतूल जिले का कसई गाँव बायोमास ऊर्जा का उपयोग करने वाला प्रदेश का पहला गाँव बना।
💡 **Exam Fact**: ग्वालियर में गन्ने की खोई (Bagasse) से बिजली बनाने का संयंत्र भी है।
🧠 **Memory Tip**: Kasai-Betul (K-B).
🚫 **Scam Alert**: धान की भूसी (Rice husk) से बिजली बनाने का संयंत्र धार में है।', 2, 0, 7, NULL, 'Which is the first village in MP to generate electricity from ''Biomass''?', '✅ **Correct Logic**: Kasai village in Betul district became the first in the state to utilize biomass energy.
💡 **Exam Fact**: Gwalior has a plant that generates power from sugarcane bagasse.
🧠 **Memory Tip**: Kasai-Betul (K-B).
🚫 **Scam Alert**: The plant for generating power from rice husk is in Dhar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b070d719-7166-4b63-9e36-b45e9a2ac4a3', 'c2953a8f-68e4-42f9-a42d-fbf71a6055a4', 'मध्य प्रदेश में ''यूरेनियम'' के भंडार मुख्य रूप से किस जिले में पाए जाते हैं?', '[{"id":"A","text":"शहडोल","text_en":"शहडोल"},{"id":"B","text":"बालाघाट","text_en":"बालाघाट"},{"id":"C","text":"होशंगाबाद","text_en":"होशंगाबाद"},{"id":"D","text":"जबलपुर","text_en":"जबलपुर"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश में यूरेनियम के साक्ष्य और भंडार शहडोल जिले में मिले हैं।
💡 **Exam Fact**: शहडोल में ही रिलायंस का ''कोल बेड मीथेन'' (CBM) प्रोजेक्ट भी है।
🧠 **Memory Tip**: Uranium - Shahdol (U-S).
🚫 **Scam Alert**: चुटका परमाणु ऊर्जा केंद्र मंडला में प्रस्तावित है, भंडार शहडोल में हैं।', 2, 0, 8, NULL, 'In which district are ''Uranium'' deposits primarily found in Madhya Pradesh?', '✅ **Correct Logic**: Evidence and deposits of Uranium in MP are primarily found in Shahdol district.
💡 **Exam Fact**: Reliance''s Coal Bed Methane (CBM) project is also located in Shahdol.
🧠 **Memory Tip**: Uranium - Shahdol (U-S).
🚫 **Scam Alert**: The Chutka Nuclear Power plant is proposed in Mandla, but the mineral deposits are in Shahdol.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6d513b76-f37d-43e2-b48e-feb33d721d52', 'c2953a8f-68e4-42f9-a42d-fbf71a6055a4', 'मध्य प्रदेश ऊर्जा विकास निगम (MP Urja Vikas Nigam) की स्थापना किस वर्ष हुई थी?', '[{"id":"A","text":"1982","text_en":"1982"},{"id":"B","text":"1975","text_en":"1975"},{"id":"C","text":"1956","text_en":"1956"},{"id":"D","text":"1964","text_en":"1964"}]', '0', '✅ **Correct Logic**: गैर-पारंपरिक ऊर्जा स्रोतों के विकास के लिए 1982 में इसकी स्थापना की गई थी।
💡 **Exam Fact**: इसका मुख्यालय भोपाल में स्थित है।
🧠 **Memory Tip**: Urja (Energy) came in ''82 (8-2 = Power).
🚫 **Scam Alert**: मध्य प्रदेश विद्युत मंडल (MPSEB) 1950 में बना था, ऊर्जा निगम 1982 में।', 2, 0, 9, NULL, 'In which year was the MP Urja Vikas Nigam established?', '✅ **Correct Logic**: It was established in 1982 to develop non-conventional energy sources.
💡 **Exam Fact**: Its headquarters is located in Bhopal.
🧠 **Memory Tip**: Urja policy took flight in ''82.
🚫 **Scam Alert**: MPSEB was formed in 1950; don''t confuse it with the 1982 Energy Corporation.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('eba5dcb5-9358-4da2-a1f4-73b7acac99e3', 'c2953a8f-68e4-42f9-a42d-fbf71a6055a4', 'मध्य प्रदेश का पहला ''परमाणु ऊर्जा केंद्र'' (Nuclear Power Plant) कहाँ प्रस्तावित है?', '[{"id":"A","text":"चुटका (मंडला)","text_en":"चुटका (मंडला)"},{"id":"B","text":"भीमपुर (शिवपुरी)","text_en":"भीमपुर (शिवपुरी)"},{"id":"C","text":"A और B दोनों","text_en":"A और B दोनों"},{"id":"D","text":"सिंगरौली","text_en":"सिंगरौली"}]', '2', '✅ **Correct Logic**: मध्य प्रदेश में दो परमाणु ऊर्जा केंद्र प्रस्तावित हैं: चुटका (मंडला) और भीमपुर (शिवपुरी)।
💡 **Exam Fact**: चुटका परमाणु केंद्र की क्षमता 1400 मेगावाट (700x2) प्रस्तावित है।
🧠 **Memory Tip**: CB (Chutka-Bhimpur) Nuclear Twins.
🚫 **Scam Alert**: अभी राज्य में कोई भी परमाणु ऊर्जा केंद्र कार्यात्मक (Functional) नहीं है।', 2, 0, 10, NULL, 'Where is the first ''Nuclear Power Plant'' of Madhya Pradesh proposed?', '✅ **Correct Logic**: Two nuclear power plants are proposed in MP: Chutka (Mandla) and Bhimpur (Shivpuri).
💡 **Exam Fact**: Chutka Nuclear Plant has a proposed capacity of 1400 MW.
🧠 **Memory Tip**: CB (Chutka-Bhimpur) are the Nuclear Twins.
🚫 **Scam Alert**: No nuclear power plant is currently functional in the state.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('92a802e1-688b-4894-9574-4fcc2aa58be9', '8c41234e-662d-449e-9517-348a1b0f96a2', 'मध्य प्रदेश में ''ऑप्टिकल फाइबर'' (Optical Fiber) बनाने का कारखाना किस देश के सहयोग से मंडीदीप (रायसेन) में स्थापित किया गया है?', '[{"id":"A","text":"जापान","text_en":"जापान"},{"id":"B","text":"जर्मनी","text_en":"जर्मनी"},{"id":"C","text":"संयुक्त राज्य अमेरिका","text_en":"संयुक्त राज्य अमेरिका"},{"id":"D","text":"दक्षिण कोरिया","text_en":"दक्षिण कोरिया"}]', '0', '✅ **Correct Logic**: मंडीदीप (रायसेन) में जापान के सहयोग से भारत का पहला ऑप्टिकल फाइबर कारखाना स्थापित किया गया है।
💡 **Exam Fact**: मंडीदीप मध्य प्रदेश का एक प्रमुख औद्योगिक केंद्र (Industrial Hub) है।
🧠 **Memory Tip**: Japan is the leader in Fiber/Tech (J-F).
🚫 **Scam Alert**: यह रायसेन जिले में आता है, न कि भोपाल में, हालांकि यह भोपाल के बहुत पास है।', 2, 0, 1, NULL, 'In which place of MP was the ''Optical Fiber'' factory established with the collaboration of which country at Mandideep (Raisen)?', '✅ **Correct Logic**: India''s first optical fiber factory was established in Mandideep (Raisen) with Japanese collaboration.
💡 **Exam Fact**: Mandideep is a premier industrial growth center of Madhya Pradesh.
🧠 **Memory Tip**: Japan is a leader in technology/fiber optics (J-F).
🚫 **Scam Alert**: It is located in the Raisen district, not Bhopal, despite its proximity to the capital.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0bca8def-e060-4a85-96a8-dab7ac18a899', '8c41234e-662d-449e-9517-348a1b0f96a2', 'मध्य प्रदेश के किस शहर को ''डेट्रॉयट ऑफ इंडिया'' (Detroit of India) कहा जाता है क्योंकि यहाँ ऑटोमोबाइल उद्योगों का जमावड़ा है?', '[{"id":"A","text":"पीथमपुर (धार)","text_en":"पीथमपुर (धार)"},{"id":"B","text":"मक्सी (शाजापुर)","text_en":"मक्सी (शाजापुर)"},{"id":"C","text":"मेघनगर (झाबुआ)","text_en":"मेघनगर (झाबुआ)"},{"id":"D","text":"पीलूखेड़ी (राजगढ़)","text_en":"पीलूखेड़ी (राजगढ़)"}]', '0', '✅ **Correct Logic**: पीथमपुर (धार जिला) को ऑटोमोबाइल हब होने के कारण भारत का डेट्रॉयट कहा जाता है।
💡 **Exam Fact**: यहाँ विशेष आर्थिक क्षेत्र (SEZ) भी स्थित है।
🧠 **Memory Tip**: Pithampur - Petrol/Power/Parts (Automobiles).
🚫 **Scam Alert**: पीथमपुर इंदौर के करीब है, लेकिन प्रशासनिक रूप से धार जिले में आता है।', 2, 0, 2, NULL, 'Which city of MP is called the ''Detroit of India'' due to the concentration of automobile industries?', '✅ **Correct Logic**: Pithampur (Dhar district) is known as the ''Detroit of India'' because of its massive automobile manufacturing cluster.
💡 **Exam Fact**: It also houses a Special Economic Zone (SEZ).
🧠 **Memory Tip**: Pithampur - Think of ''Pits'' and ''Parts'' for automobiles.
🚫 **Scam Alert**: While very close to Indore, Pithampur is administratively under the Dhar district.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3acb6159-e0d5-4f18-872b-e2dce74d4ac8', '8c41234e-662d-449e-9517-348a1b0f96a2', 'भारत हैवी इलेक्ट्रिकल्स लिमिटेड (BHEL) भोपाल की स्थापना किस वर्ष की गई थी?', '[{"id":"A","text":"1956","text_en":"1956"},{"id":"B","text":"1960","text_en":"1960"},{"id":"C","text":"1964","text_en":"1964"},{"id":"D","text":"1972","text_en":"1972"}]', '1', '✅ **Correct Logic**: BHEL भोपाल की स्थापना 1960 में ब्रिटेन (UK) के सहयोग से की गई थी।
💡 **Exam Fact**: इसे ''महारत्न'' कंपनी का दर्जा प्राप्त है।
🧠 **Memory Tip**: BHEL - B for Britain, 60 (Sixty - Success).
🚫 **Scam Alert**: 1964 में BHEL को राष्ट्रीय स्तर पर निगम बनाया गया था, पर भोपाल इकाई 1960 में शुरू हुई थी।', 2, 0, 3, NULL, 'In which year was Bharat Heavy Electricals Limited (BHEL) Bhopal established?', '✅ **Correct Logic**: BHEL Bhopal was established in 1960 with technical collaboration from Britain (UK).
💡 **Exam Fact**: It holds the ''Maharatna'' status among PSUs.
🧠 **Memory Tip**: BHEL - B for Britain, established in the 60s.
🚫 **Scam Alert**: While BHEL as a corporation was formed in 1964, the Bhopal unit''s foundation was laid in 1960.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c2f8cbf9-f770-4f65-82f9-4a4429ddc860', '8c41234e-662d-449e-9517-348a1b0f96a2', 'मध्य प्रदेश में ''रेलवे स्लीपर'' बनाने का कारखाना कहाँ स्थित है?', '[{"id":"A","text":"बुधनी (सीहोर)","text_en":"बुधनी (सीहोर)"},{"id":"B","text":"इटारसी","text_en":"इटारसी"},{"id":"C","text":"बीना","text_en":"बीना"},{"id":"D","text":"गंजबासौदा","text_en":"गंजबासौदा"}]', '0', '✅ **Correct Logic**: सीहोर जिले के बुधनी में रेलवे स्लीपर बनाने का प्रमुख कारखाना स्थित है।
💡 **Exam Fact**: रेलवे कोच फैक्ट्री भोपाल के निशातपुरा में स्थित है।
🧠 **Memory Tip**: Budhni - Build (Building sleepers).
🚫 **Scam Alert**: इटारसी सबसे बड़ा रेलवे जंक्शन है, पर स्लीपर फैक्ट्री बुधनी में है।', 2, 0, 4, NULL, 'Where is the factory for manufacturing ''Railway Sleepers'' located in Madhya Pradesh?', '✅ **Correct Logic**: A major factory for manufacturing railway sleepers is located in Budhni, Sehore district.
💡 **Exam Fact**: The Railway Coach Factory is located in Nishatpura, Bhopal.
🧠 **Memory Tip**: Budhni - Think of ''Building'' sleepers.
🚫 **Scam Alert**: Itarsi is the largest railway junction, but the sleeper factory is in Budhni.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f2447d9e-dbc1-4c7b-a046-c4eae66bc50c', '8c41234e-662d-449e-9517-348a1b0f96a2', 'उद्योग और उनके संबंधित स्थानों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: नोट देवास में छपते हैं, स्टाम्प पेपर नर्मदापुरम में बनते हैं, अखबार का कागज नेपानगर में और ओरिएंट पेपर मिल (निजी) अमलाई (शहडोल) में है।
💡 **Exam Fact**: बैंक नोट प्रेस 1974 में स्थापित की गई थी।
🧠 **Memory Tip**: Dewas - Dhan (Money/Notes).
🚫 **Scam Alert**: ओरिएंट पेपर मिल बिड़ला समूह की निजी मिल है, सरकारी नहीं।', 2, 0, 5, NULL, 'Match the industries and their respective locations:', '✅ **Correct Logic**: Currency notes are printed in Dewas, Security paper is made in Narmadapuram, Newsprint in Nepanagar, and Orient Paper Mill is in Amlai.
💡 **Exam Fact**: The Bank Note Press in Dewas was established in 1974.
🧠 **Memory Tip**: Dewas - Dhan (Wealth/Notes).
🚫 **Scam Alert**: Orient Paper Mill is a private enterprise (Birla Group), not a government one.', 60, 'matching', '[{"id":"(1)","label":"बैंक नोट प्रेस","match":"देवास","matchId":"(a)"},{"id":"(2)","label":"सिक्योरिटी पेपर मिल","match":"नर्मदापुरम","matchId":"(b)"},{"id":"(3)","label":"न्यूज़प्रिंट पेपर मिल","match":"नेपानगर","matchId":"(c)"},{"id":"(4)","label":"ओरिएंट पेपर मिल","match":"अमलाई","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b635353e-4471-4b43-8813-ce6f2172299f', '8c41234e-662d-449e-9517-348a1b0f96a2', 'मध्य प्रदेश के किस जिले में ''बीना तेल रिफाइनरी'' (Bina Oil Refinery) स्थित है और यह किस देश के सहयोग से बनी है?', '[{"id":"A","text":"सागर; ओमान","text_en":"सागर; ओमान"},{"id":"B","text":"सागर; रूस","text_en":"सागर; रूस"},{"id":"C","text":"जबलपुर; जापान","text_en":"जबलपुर; जापान"},{"id":"D","text":"ग्वालियर; फ्रांस","text_en":"ग्वालियर; फ्रांस"}]', '0', '✅ **Correct Logic**: बीना रिफाइनरी सागर जिले में स्थित है और यह भारत तथा ओमान (Oman) सरकार का संयुक्त उपक्रम है।
💡 **Exam Fact**: इसका उद्घाटन 2011 में किया गया था।
🧠 **Memory Tip**: B-O-S (Bina-Oman-Sagar).
🚫 **Scam Alert**: यह रिफाइनरी BPCL (Bharat Petroleum) द्वारा संचालित है।', 2, 0, 6, NULL, 'In which district is the ''Bina Oil Refinery'' located and with which country''s help was it built?', '✅ **Correct Logic**: The Bina Refinery is located in the Sagar district and is a joint venture between India and Oman.
💡 **Exam Fact**: It was inaugurated in 2011.
🧠 **Memory Tip**: B-O-S (Bina-Oman-Sagar).
🚫 **Scam Alert**: It is operated by Bharat Petroleum Corporation Limited (BPCL).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a6caf55d-8e20-4249-9cdc-3e4fa4ca2ef7', '8c41234e-662d-449e-9517-348a1b0f96a2', 'मध्य प्रदेश हस्तशिल्प विकास निगम'' का नाम बदलकर अब क्या कर दिया गया है?', '[{"id":"A","text":"मृगनयनी हस्तशिल्प निगम","text_en":"मृगनयनी हस्तशिल्प निगम"},{"id":"B","text":"संत रविदास हस्तशिल्प एवं मध्य प्रदेश चर्म विकास निगम","text_en":"संत रविदास हस्तशिल्प एवं मध्य प्रदेश चर्म विकास निगम"},{"id":"C","text":"शिल्पी निगम","text_en":"शिल्पी निगम"},{"id":"D","text":"आदिवासी हस्तशिल्प निगम","text_en":"आदिवासी हस्तशिल्प निगम"}]', '1', '✅ **Correct Logic**: इसका नाम अब ''संत रविदास हस्तशिल्प एवं मध्य प्रदेश चर्म विकास निगम'' कर दिया गया है।
💡 **Exam Fact**: इसके रिटेल आउटलेट्स को ''मृगनयनी'' (Mrignayanee) के नाम से जाना जाता है।
🧠 **Memory Tip**: Sant Ravidas - Associated with leather/crafts.
🚫 **Scam Alert**: मृगनयनी शोरूम का नाम है, निगम का नहीं।', 2, 0, 7, NULL, 'What has the ''MP Handicrafts Development Corporation'' been renamed to?', '✅ **Correct Logic**: It has been renamed the ''Sant Ravidas Handicrafts and MP Leather Development Corporation''.
💡 **Exam Fact**: Its retail outlets are famously branded as ''Mrignayanee''.
🧠 **Memory Tip**: Sant Ravidas is traditionally associated with leather crafts.
🚫 **Scam Alert**: Mrignayanee is the brand/showroom name, not the official corporation name.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9b3a2473-b83d-4ebb-b5e7-21a132286224', '8c41234e-662d-449e-9517-348a1b0f96a2', 'मध्य प्रदेश का पहला ''रत्न परिष्कृत केंद्र'' (Gems and Jewelry Park) कहाँ स्थापित किया गया है?', '[{"id":"A","text":"जबलपुर","text_en":"जबलपुर"},{"id":"B","text":"इंदौर","text_en":"इंदौर"},{"id":"C","text":"पन्ना","text_en":"पन्ना"},{"id":"D","text":"ग्वालियर","text_en":"ग्वालियर"}]', '0', '✅ **Correct Logic**: राज्य का पहला रत्न परिष्कृत केंद्र जबलपुर में स्थापित किया गया है।
💡 **Exam Fact**: पन्ना हीरा उत्खनन के लिए प्रसिद्ध है, लेकिन परिष्कृत केंद्र (Cutting/Polishing) जबलपुर में है।
🧠 **Memory Tip**: J-G (Jabalpur-Gems).
🚫 **Scam Alert**: पन्ना केवल कच्चा हीरा देता है, फिनिशिंग का काम जबलपुर में शुरू किया गया था।', 2, 0, 8, NULL, 'Where was the first ''Gems and Jewelry Park'' of Madhya Pradesh established?', '✅ **Correct Logic**: The first gems and jewelry finishing center in the state was established in Jabalpur.
💡 **Exam Fact**: While Panna is the source of diamonds, the polishing/processing center is in Jabalpur.
🧠 **Memory Tip**: J-G (Jabalpur-Gems).
🚫 **Scam Alert**: Panna provides the raw diamonds; the industrial polishing unit was pioneered in Jabalpur.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('af3c3875-5eb5-48fc-8176-5546d2678594', '8c41234e-662d-449e-9517-348a1b0f96a2', 'राज्य में ''जिलेटिन'' (Gelatine) बनाने का कारखाना कहाँ स्थित है?', '[{"id":"A","text":"जबलपुर","text_en":"जबलपुर"},{"id":"B","text":"कटनी","text_en":"कटनी"},{"id":"C","text":"सतना","text_en":"सतना"},{"id":"D","text":"रीवा","text_en":"रीवा"}]', '0', '✅ **Correct Logic**: जबलपुर में जिलेटिन बनाने का कारखाना स्थित है।
💡 **Exam Fact**: जबलपुर को ''मार्बल सिटी'' के अलावा रक्षा उद्योगों के लिए भी जाना जाता है।
🧠 **Memory Tip**: J-G (Jabalpur-Gelatine).
🚫 **Scam Alert**: कटनी को चूना नगरी कहते हैं, जिलेटिन के लिए जबलपुर प्रसिद्ध है।', 2, 0, 9, NULL, 'Where is the ''Gelatine'' manufacturing factory located in the state?', '✅ **Correct Logic**: The Gelatine manufacturing unit is located in Jabalpur.
💡 **Exam Fact**: Apart from being the Marble City, Jabalpur is a hub for defense industries.
🧠 **Memory Tip**: J-G (Jabalpur-Gelatine).
🚫 **Scam Alert**: Katni is the ''Lime City''; Gelatine is specifically associated with Jabalpur.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6d4b5e08-4828-45a6-b6d2-3f19ac59b0f3', '8c41234e-662d-449e-9517-348a1b0f96a2', 'मध्य प्रदेश में ''सूती वस्त्र उद्योगों'' (Cotton Textile Industries) का सर्वाधिक संकेंद्रण किस क्षेत्र में है?', '[{"id":"A","text":"मालवा","text_en":"मालवा"},{"id":"B","text":"बघेलखंड","text_en":"बघेलखंड"},{"id":"C","text":"बुंदेलखंड","text_en":"बुंदेलखंड"},{"id":"D","text":"चंबल","text_en":"चंबल"}]', '0', '✅ **Correct Logic**: मालवा क्षेत्र (इंदौर, उज्जैन) में कपास उत्पादन अधिक होने के कारण सूती वस्त्र उद्योगों का सर्वाधिक विकास हुआ है।
💡 **Exam Fact**: इंदौर को मध्य प्रदेश का ''मिनी मुंबई'' सूती वस्त्र उद्योग के कारण ही कहा जाता है।
🧠 **Memory Tip**: Malwa - Mumbai connection.
🚫 **Scam Alert**: निमाड़ में कपास उगता है, लेकिन मिलें (Mills) मालवा में अधिक हैं।', 2, 0, 10, NULL, 'In which region is the maximum concentration of ''Cotton Textile Industries'' in MP?', '✅ **Correct Logic**: The Malwa region (Indore, Ujjain) has the highest concentration of cotton textiles due to proximity to the cotton-growing belt.
💡 **Exam Fact**: Indore is called ''Mini Mumbai'' primarily because of its textile industry history.
🧠 **Memory Tip**: Malwa is linked to the textile prosperity similar to Mumbai.
🚫 **Scam Alert**: While Nimar grows the cotton, the industrial processing/mills are concentrated in Malwa.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('910c87c1-476b-4445-b72f-1c9f3d7d9618', '1f009a71-c07f-446a-84a2-c684a9aa3137', 'भारत का कौन सा क्षेत्र ''जोन-V'' (Zone-V) भूकंपीय क्षेत्र के अंतर्गत आता है?', '[{"id":"A","text":"दक्कन का पठार (Deccan Plateau)","text_en":"दक्कन का पठार (Deccan Plateau)"},{"id":"B","text":"पूर्वोत्तर भारत (North-East India)","text_en":"पूर्वोत्तर भारत (North-East India)"},{"id":"C","text":"गंगा का मैदान (Ganga Plains)","text_en":"गंगा का मैदान (Ganga Plains)"},{"id":"D","text":"पश्चिमी राजस्थान (Western Rajasthan)","text_en":"पश्चिमी राजस्थान (Western Rajasthan)"}]', '1', '**✅ Correct Logic:** **पूर्वोत्तर भारत** (North-East India), पूरा हिमालयी क्षेत्र, कच्छ (गुजरात), और अंडमान-निकोबार द्वीप समूह **जोन-V** (Very High Risk) में आते हैं। यह सबसे खतरनाक क्षेत्र है।

**💡 Exam Fact:** भारत को 4 भूकंपीय जोनों (II, III, IV, V) में बांटा गया है। जोन-I को हटा दिया गया है।

**🧠 Memory Tip:** **NE** is **New** mountains -> Unstable -> Zone 5.

**🚫 Scam Alert:** दक्कन पठार जोन-II/III (कम जोखिम) में है, हालांकि लातूर में भूकंप आया था।', 2, 0, 1, NULL, 'Which region of India falls under ''Zone-V'' seismic zone?', '**✅ Correct Logic:** **North-East India**, entire Himalayan belt, Kutch (Gujarat), and Andaman & Nicobar fall under **Zone-V** (Very High Risk).

**💡 Exam Fact:** India is divided into 4 seismic zones (II, III, IV, V). Zone-I is merged.

**🧠 Memory Tip:** **NE** is **New** -> Zone 5.

**🚫 Scam Alert:** Deccan Plateau is low risk (Zone II/III).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b3287c4d-2ee3-483a-af92-61883763ff7f', '1f009a71-c07f-446a-84a2-c684a9aa3137', 'सुनामी (Tsunami) शब्द किस भाषा से लिया गया है और इसका अर्थ क्या है?', '[{"id":"A","text":"चीनी - विनाशकारी लहर (Chinese - Destructive Wave)","text_en":"चीनी - विनाशकारी लहर (Chinese - Destructive Wave)"},{"id":"B","text":"जापानी - बंदरगाह लहर (Japanese - Harbour Wave)","text_en":"जापानी - बंदरगाह लहर (Japanese - Harbour Wave)"},{"id":"C","text":"इतैलियन - ज्वारीय लहर (Italian - Tidal Wave)","text_en":"इतैलियन - ज्वारीय लहर (Italian - Tidal Wave)"},{"id":"D","text":"ग्रीक - भूकंपीय लहर (Greek - Seismic Wave)","text_en":"ग्रीक - भूकंपीय लहर (Greek - Seismic Wave)"}]', '1', '**✅ Correct Logic:** सुनामी **जापानी** शब्द है: ''Tsu'' (बंदरगाह) + ''Nami'' (लहर) = **Harbour Wave**। जब ये गहरे समुद्र में होती हैं तो छोटी होती हैं, लेकिन तट (बंदरगाह) के पास विशाल हो जाती हैं।

**💡 Exam Fact:** 2004 की सुनामी (हिंद महासागर) सुमात्रा भूकंप (9.1 M) के कारण आई थी।

**🧠 Memory Tip:** **Tsu**-**Nami** -> Japanese name.

**🚫 Scam Alert:** इसे ''ज्वारीय लहर'' (Tidal Wave) कहना तकनीकी रूप से गलत है क्योंकि यह ज्वार-भाटा (चंद्रमा) से नहीं, भूकंप से आती है।', 2, 0, 2, NULL, 'The word ''Tsunami'' is derived from which language and what does it mean?', '**✅ Correct Logic:** Tsunami is **Japanese**: ''Tsu'' (Harbour) + ''Nami'' (Wave) = **Harbour Wave**.

**💡 Exam Fact:** 2004 Tsunami was caused by Sumatra Earthquake.

**🧠 Memory Tip:** **Tsu**-**Nami** -> Japanese.

**🚫 Scam Alert:** Technically incorrect to call it ''Tidal Wave'' (related to Moon). It''s seismic.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4ee7210d-726a-4763-9c94-2eafa7860c91', '1f009a71-c07f-446a-84a2-c684a9aa3137', 'सूखा प्रवण क्षेत्र कार्यक्रम (DPAP) भारत सरकार द्वारा किस वर्ष शुरू किया गया था?', '[{"id":"A","text":"1973-74","text_en":"1973-74"},{"id":"B","text":"1980-81","text_en":"1980-81"},{"id":"C","text":"1990-91","text_en":"1990-91"},{"id":"D","text":"2005-06","text_en":"2005-06"}]', '0', '**✅ Correct Logic:** DPAP **1973-74** में शुरू किया गया था। इसका उद्देश्य सूखे के प्रभाव को कम करना और पारिस्थितिक संतुलन बहाल करना है।

**💡 Exam Fact:** मरुस्थल विकास कार्यक्रम (DDP) 1977-78 में शुरू हुआ था।

**🧠 Memory Tip:** **D**rought **P**rogram came in **73**.

**🚫 Scam Alert:** 1973 (DPAP) और 1977 (DDP) में अंतर याद रखें।', 2, 0, 3, NULL, 'Drought Prone Area Programme (DPAP) was launched by Govt of India in which year?', '**✅ Correct Logic:** DPAP launched in **1973-74**. Aim: Reduce drought impact.

**💡 Exam Fact:** Desert Development Programme (DDP) came in 1977-78.

**🧠 Memory Tip:** **D**rought in **73**.

**🚫 Scam Alert:** DDP is 1977, DPAP is 1973.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('053fc53f-3e34-406e-9348-f2f3ff30c342', '1f009a71-c07f-446a-84a2-c684a9aa3137', 'निम्नलिखित में से कौन सी नदी अपनी बाढ़ों के लिए कुख्यात है और अक्सर अपना रास्ता बदलती है, जिसे ''बिहार का शोक'' कहा जाता है?', '[{"id":"A","text":"गंडक (Gandak)","text_en":"गंडक (Gandak)"},{"id":"B","text":"कोसी (Kosi)","text_en":"कोसी (Kosi)"},{"id":"C","text":"सोन (Son)","text_en":"सोन (Son)"},{"id":"D","text":"गंगा (Ganga)","text_en":"गंगा (Ganga)"}]', '1', '**✅ Correct Logic:** **कोसी नदी** को ''बिहार का शोक'' (Sorrow of Bihar) कहते हैं। यह हिमालय से भारी मात्रा में गाद (Silt) लाती है, जो इसके रास्ते को अवरुद्ध कर देती है, जिससे यह अपना रास्ता (Course) बदल लेती है और बाढ़ लाती है।

**💡 Exam Fact:** दामोदर को ''बंगाल का शोक'' कहा जाता था (अब DVC के कारण नियंत्रित है)।

**🧠 Memory Tip:** **Kosi** causes **Klesha** (Pain) in Bihar.

**🚫 Scam Alert:** गंडक भी बाढ़ लाती है, लेकिन रास्ता बदलने के लिए कोसी बदनाम है।', 2, 0, 4, NULL, 'Which of the following rivers is notorious for its floods and frequently changes its course, known as ''Sorrow of Bihar''?', '**✅ Correct Logic:** **Kosi** is the ''Sorrow of Bihar''. It brings heavy silt, blocks its own path, changes course, and causes floods.

**💡 Exam Fact:** Damodar was ''Sorrow of Bengal''.

**🧠 Memory Tip:** **Kosi** causes **Klesha**.

**🚫 Scam Alert:** Gandak floods, but Kosi shifts course.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('811888b4-cd79-40b1-8bfd-caf376a66ab5', '1f009a71-c07f-446a-84a2-c684a9aa3137', 'राष्ट्रीय आपदा प्रबंधन प्राधिकरण (NDMA) का पदेन अध्यक्ष (Ex-officio Chairman) कौन होता है?', '[{"id":"A","text":"गृह मंत्री (Home Minister)","text_en":"गृह मंत्री (Home Minister)"},{"id":"B","text":"राष्ट्रपति (President)","text_en":"राष्ट्रपति (President)"},{"id":"C","text":"प्रधानमंत्री (Prime Minister)","text_en":"प्रधानमंत्री (Prime Minister)"},{"id":"D","text":"पर्यावरण मंत्री (Environment Minister)","text_en":"पर्यावरण मंत्री (Environment Minister)"}]', '2', '**✅ Correct Logic:** NDMA के अध्यक्ष **प्रधानमंत्री** (Prime Minister) होते हैं। राज्य स्तर पर (SDMA) मुख्यमंत्री होते हैं। जिला स्तर पर (DDMA) कलेक्टर/डीएम होते हैं।

**💡 Exam Fact:** NDMA का गठन आपदा प्रबंधन अधिनियम 2005 के तहत किया गया था।

**🧠 Memory Tip:** Disaster is big issue, **PM** handles it.

**🚫 Scam Alert:** गृह मंत्रालय नोडल एजेंसी है, लेकिन अध्यक्ष पीएम हैं। गृह मंत्री नहीं!', 2, 0, 5, NULL, 'Who is the Ex-officio Chairman of the National Disaster Management Authority (NDMA)?', '**✅ Correct Logic:** **Prime Minister** is the Chairman of NDMA. CM heads SDMA. Collector heads DDMA.

**💡 Exam Fact:** Formed under Disaster Management Act 2005.

**🧠 Memory Tip:** **PM** handles Disaster.

**🚫 Scam Alert:** Home Ministry is nodal agency, but PM is Chairman.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4d4ddb3c-7a82-496e-bc60-45f4c93e3ae2', '1f009a71-c07f-446a-84a2-c684a9aa3137', 'भूस्खलन (Landslide) की घटनाओं के लिए भारत का कौन सा क्षेत्र सबसे अधिक संवेदनशील है?', '[{"id":"A","text":"पश्चिमी घाट (Western Ghats)","text_en":"पश्चिमी घाट (Western Ghats)"},{"id":"B","text":"हिमालय और पूर्वोत्तर पहाड़ियाँ (Himalayas and North-East Hills)","text_en":"हिमालय और पूर्वोत्तर पहाड़ियाँ (Himalayas and North-East Hills)"},{"id":"C","text":"विंध्याचल (Vindhyachal)","text_en":"विंध्याचल (Vindhyachal)"},{"id":"D","text":"दक्कन का पठार (Deccan Plateau)","text_en":"दक्कन का पठार (Deccan Plateau)"}]', '1', '**✅ Correct Logic:** **हिमालय** (युवा और अस्थिर पहाड़) और **पूर्वोत्तर** क्षेत्र भूस्खलन के लिए सबसे अधिक संवेदनशील (Very High Vulnerability) हैं। पश्चिमी घाट भी संवेदनशील है, लेकिन हिमालय की तीव्रता और आवृत्ति अधिक है।

**💡 Exam Fact:** हिमालय में टेक्टोनिक गतिविधि और सड़क निर्माण इसके प्रमुख कारण हैं।

**🧠 Memory Tip:** **Young** mountains fall easily (Landslide).

**🚫 Scam Alert:** पश्चिमी घाट में भी भूस्खलन होते हैं (जैसे केरल में), लेकिन हिमालय ''सबसे अधिक'' (Most) संवेदनशील है।', 2, 0, 6, NULL, 'Which region of India is most vulnerable to Landslide incidents?', '**✅ Correct Logic:** **Himalayas** (Young & Unstable) and **North-East** are most vulnerable. Western Ghats is also vulnerable but Himalayas top the list.

**💡 Exam Fact:** Tectonic activity + Road construction causes it.

**🧠 Memory Tip:** **Young** mountains fall.

**🚫 Scam Alert:** Western Ghats has landslides, but Himalayas are ''Most'' vulnerable.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e6b2c865-e903-4ebc-b7da-c7910c043c96', '1f009a71-c07f-446a-84a2-c684a9aa3137', 'भोपाल गैस त्रासदी (Bhopal Gas Tragedy), 1984 किस प्रकार की आपदा थी और कौन सी गैस लीक हुई थी?', '[{"id":"A","text":"प्राकृतिक - कार्बन मोनोऑक्साइड (Natural - CO)","text_en":"प्राकृतिक - कार्बन मोनोऑक्साइड (Natural - CO)"},{"id":"B","text":"रासायनिक/मानव निर्मित - मिथाइल आइसोसायनेट (Chemical/Man-made - MIC)","text_en":"रासायनिक/मानव निर्मित - मिथाइल आइसोसायनेट (Chemical/Man-made - MIC)"},{"id":"C","text":"परमाणु - यूरेनियम (Nuclear - Uranium)","text_en":"परमाणु - यूरेनियम (Nuclear - Uranium)"},{"id":"D","text":"जैविक - एंथ्रेक्स (Biological - Anthrax)","text_en":"जैविक - एंथ्रेक्स (Biological - Anthrax)"}]', '1', '**✅ Correct Logic:** यह एक **रासायनिक/औद्योगिक आपदा** (मानव निर्मित) थी। यूनियन कार्बाइड फैक्ट्री से **मिथाइल आइसोसायनेट (MIC)** गैस लीक हुई थी (2-3 दिसंबर 1984 की रात)।

**💡 Exam Fact:** ऑपरेशन फेथ (Operation Faith) बचे हुए गैस को निष्क्रिय करने के लिए चलाया गया था।

**🧠 Memory Tip:** **MIC**key Mouse in Bhopal (MIC gas).

**🚫 Scam Alert:** यह प्राकृतिक आपदा नहीं थी। गैस का नाम MIC याद रखें।', 2, 0, 7, NULL, 'Bhopal Gas Tragedy (1984) was which type of disaster and which gas leaked?', '**✅ Correct Logic:** **Chemical/Industrial Disaster**. **Methyl Isocyanate (MIC)** leaked from Union Carbide on Dec 2-3, 1984.

**💡 Exam Fact:** Operation Faith was launched to neutralize remaining gas.

**🧠 Memory Tip:** **MIC** gas.

**🚫 Scam Alert:** Not Natural. Gas is MIC.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f9662f89-8939-4539-a00f-3e90921fd74f', '1f009a71-c07f-446a-84a2-c684a9aa3137', 'अंतर्राष्ट्रीय सुनामी चेतावनी केंद्र (International Tsunami Warning Centre) कहाँ स्थित है?', '[{"id":"A","text":"टोक्यो, जापान (Tokyo, Japan)","text_en":"टोक्यो, जापान (Tokyo, Japan)"},{"id":"B","text":"होनोलूलू, हवाई (Honolulu, Hawaii)","text_en":"होनोलूलू, हवाई (Honolulu, Hawaii)"},{"id":"C","text":"जकार्ता, इंडोनेशिया (Jakarta, Indonesia)","text_en":"जकार्ता, इंडोनेशिया (Jakarta, Indonesia)"},{"id":"D","text":"चेन्नई, भारत (Chennai, India)","text_en":"चेन्नई, भारत (Chennai, India)"}]', '1', '**✅ Correct Logic:** पैसिफिक सुनामी वार्निंग सेंटर (PTWC) **होनोलूलू, हवाई** (USA) में स्थित है। यह दुनिया का मुख्य चेतावनी केंद्र है।

**💡 Exam Fact:** भारत का सुनामी चेतावनी केंद्र (INCOIS) **हैदराबाद** में है।

**🧠 Memory Tip:** **Hawaii** police warns about Tsunami.

**🚫 Scam Alert:** भारत का हैदराबाद में है, अंतर्राष्ट्रीय हवाई में है।', 2, 0, 8, NULL, 'Where is the International Tsunami Warning Centre located?', '**✅ Correct Logic:** Pacific Tsunami Warning Center is in **Honolulu, Hawaii**. 

**💡 Exam Fact:** India''s centre (INCOIS) is in **Hyderabad**.

**🧠 Memory Tip:** **Hawaii** warns.

**🚫 Scam Alert:** India''s is Hyderabad, International is Hawaii.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7bb5a998-2bc3-4fc9-a9fe-f0a3ba2bb60d', '1f009a71-c07f-446a-84a2-c684a9aa3137', 'उत्तराखंड में 2013 की केदारनाथ आपदा का मुख्य कारण क्या था?', '[{"id":"A","text":"भूकंप (Earthquake)","text_en":"भूकंप (Earthquake)"},{"id":"B","text":"बादल फटना और ग्लेशियर झील का टूटना (Cloudburst and GLOF)","text_en":"बादल फटना और ग्लेशियर झील का टूटना (Cloudburst and GLOF)"},{"id":"C","text":"जंगल की आग (Forest Fire)","text_en":"जंगल की आग (Forest Fire)"},{"id":"D","text":"ज्वालामुखी विस्फोट (Volcanic Eruption)","text_en":"ज्वालामुखी विस्फोट (Volcanic Eruption)"}]', '1', '**✅ Correct Logic:** जून 2013 में **बादल फटने** (Cloudburst) और **चोराबाड़ी ग्लेशियर झील** (Chorabari Lake) के टूटने से मंदाकिनी नदी में भीषण बाढ़ आई थी। इसे ''हिमालयी सुनामी'' भी कहा गया।

**💡 Exam Fact:** बादल फटना = 1 घंटे में 100 मिमी से अधिक वर्षा।

**🧠 Memory Tip:** **Clouds burst** on Kedar Baba.

**🚫 Scam Alert:** भूकंप नहीं था, यह अत्यधिक वर्षा/ग्लेशियर से संबंधित था।', 2, 0, 9, NULL, 'What was the main cause of the 2013 Kedarnath disaster in Uttarakhand?', '**✅ Correct Logic:** Caused by **Cloudburst** and bursting of **Chorabari Glacier Lake** (GLOF), flooding Mandakini river.

**💡 Exam Fact:** Cloudburst = >100mm rain in 1 hour.

**🧠 Memory Tip:** **Clouds burst** on Kedar.

**🚫 Scam Alert:** Not Earthquake.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5915f642-8e40-4e8f-822e-d89699438c42', '1f009a71-c07f-446a-84a2-c684a9aa3137', 'निम्नलिखित आपदाओं को उनके वर्ष से सुमेलित करें (Match the following disasters with their year):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **भुज**: 26 जनवरी 2001 (गणतंत्र दिवस पर)। -> (1)-(a)
* **सुनामी**: 26 दिसंबर 2004 (बॉक्सिंग डे)। -> (2)-(b)
* **कश्मीर बाढ़**: सितंबर 2014 (झेलम नदी)। -> (3)-(c)
* **लातूर**: 1993 (महाराष्ट्र, Killari)। -> (4)-(d)

**💡 Exam Fact:** लातूर भूकंप इस बात का प्रमाण था कि दक्कन पठार (Stable land) भी सुरक्षित नहीं है।

**🧠 Memory Tip:** **Bhuj** on Republic Day 01. **Tsunami** on Christmas 04.

**🚫 Scam Alert:** वर्ष याद रखें, अक्सर कालक्रम (Chronology) पूछा जाता है।', 2, 0, 10, NULL, 'Match the following disasters with their year:', '**✅ Correct Matching:**
* **Bhuj**: 2001 (Republic Day). -> (1)-(a)
* **Tsunami**: 2004 (Dec 26). -> (2)-(b)
* **Kashmir**: 2014. -> (3)-(c)
* **Latur**: 1993. -> (4)-(d)

**💡 Exam Fact:** Latur quake proved Deccan is not totally stable.

**🧠 Memory Tip:** **Bhuj**-01. **Tsunami**-04.

**🚫 Scam Alert:** Chronology is key.', 60, 'matching', '[{"id":"(1)","label":"भुज भूकंप (Bhuj Earthquake)","match":"2001","matchId":"(a)"},{"id":"(2)","label":"हिंद महासागर सुनामी (Indian Ocean Tsunami)","match":"2004","matchId":"(b)"},{"id":"(3)","label":"कश्मीर बाढ़ (Kashmir Floods)","match":"2014","matchId":"(c)"},{"id":"(4)","label":"लातूर भूकंप (Latur Earthquake)","match":"1993","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('053202ee-a6eb-4ce5-9e6a-d6a08cf5ff6f', '14a4f30c-370f-40b2-9396-87130dd62644', 'उष्णकटिबंधीय चक्रवातों (Tropical Cyclones) के नामकरण की व्यवस्था के तहत, हिंद महासागर क्षेत्र के लिए नाम कौन तय करता है?', '[{"id":"A","text":"अकेले भारत (India alone)","text_en":"अकेले भारत (India alone)"},{"id":"B","text":"WMO/ESCAP पैनल के 13 सदस्य देश","text_en":"WMO/ESCAP पैनल के 13 सदस्य देश"},{"id":"C","text":"संयुक्त राज्य अमेरिका (USA)","text_en":"संयुक्त राज्य अमेरिका (USA)"},{"id":"D","text":"श्रीलंका (Sri Lanka)","text_en":"श्रीलंका (Sri Lanka)"}]', '1', '**✅ Correct Logic:** उत्तरी हिंद महासागर में चक्रवातों के नाम **13 सदस्य देशों** (भारत, बांग्लादेश, मालदीव, म्यांमार, ओमान, पाकिस्तान, श्रीलंका, थाईलैंड + 5 नए) के पैनल द्वारा क्रमिक रूप से दिए जाते हैं।

**💡 Exam Fact:** ''निसर्ग'' नाम बांग्लादेश ने दिया था, ''अम्फान'' थाईलैंड ने।

**🧠 Memory Tip:** **13** friends decide the name of the baby (Cyclone).

**🚫 Scam Alert:** कोई एक देश नहीं देता, यह रोटेशन में चलता है।', 2, 0, 1, NULL, 'Under the naming system of Tropical Cyclones, who decides the names for the Indian Ocean region?', '**✅ Correct Logic:** Names are decided sequentially by a panel of **13 member countries** of WMO/ESCAP (India, Bangladesh, etc.).

**💡 Exam Fact:** ''Nisarga'' named by Bangladesh, ''Amphan'' by Thailand.

**🧠 Memory Tip:** **13** friends decide.

**🚫 Scam Alert:** It''s a rotation, not one country.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('581e7e19-ba08-4628-aa51-48646c052f33', '14a4f30c-370f-40b2-9396-87130dd62644', 'ओडिशा तट को अक्सर चक्रवातों का सामना क्यों करना पड़ता है?', '[{"id":"A","text":"इसकी भौगोलिक स्थिति और समतल तटीय मैदान (Geographical location and flat coastal terrain)","text_en":"इसकी भौगोलिक स्थिति और समतल तटीय मैदान (Geographical location and flat coastal terrain)"},{"id":"B","text":"यहाँ बहुत अधिक गर्मी होती है","text_en":"यहाँ बहुत अधिक गर्मी होती है"},{"id":"C","text":"यहाँ मैंग्रोव वन नहीं हैं","text_en":"यहाँ मैंग्रोव वन नहीं हैं"},{"id":"D","text":"यह भूमध्य रेखा के बहुत करीब है","text_en":"यह भूमध्य रेखा के बहुत करीब है"}]', '0', '**✅ Correct Logic:** बंगाल की खाड़ी में बनने वाले ज्यादातर चक्रवात अपनी दिशा (पछुआ हवाओं के कारण) उत्तर-पश्चिम की ओर रखते हैं और ओडिशा का **अवतल (Concave) तट** उन्हें फंसा लेता है। साथ ही, उथला समुद्र और समतल मैदान नुकसान बढ़ाते हैं।

**💡 Exam Fact:** 1999 का सुपर साइक्लोन ओडिशा में ही आया था।

**🧠 Memory Tip:** Odisha is a **Magnet** for cyclones due to shape.

**🚫 Scam Alert:** मैंग्रोव (भीतरकनिका) हैं और रक्षा करते हैं, उनकी अनुपस्थिति कारण नहीं है। आकार (Shape) और स्थान कारण है।', 2, 0, 2, NULL, 'Why does the Odisha coast frequently face cyclones?', '**✅ Correct Logic:** Cyclones in Bay of Bengal move NW. Odisha''s **Concave coast** traps them. Shallow sea and flat terrain increase impact.

**💡 Exam Fact:** 1999 Super Cyclone hit Odisha.

**🧠 Memory Tip:** Odisha is a **Magnet**.

**🚫 Scam Alert:** Mangroves exist there. The Coast Shape is the villain.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bfd81ce0-67b6-4ba5-aac8-06103c6b31a8', '14a4f30c-370f-40b2-9396-87130dd62644', '2023 में अरब सागर में आए चक्रवात ''बिपरजॉय'' (Biparjoy) का नाम किस देश ने दिया था और इसका अर्थ क्या है?', '[{"id":"A","text":"भारत - विनाश (India - Destruction)","text_en":"भारत - विनाश (India - Destruction)"},{"id":"B","text":"बांग्लादेश - आपदा/विपत्ति (Bangladesh - Disaster/Calamity)","text_en":"बांग्लादेश - आपदा/विपत्ति (Bangladesh - Disaster/Calamity)"},{"id":"C","text":"पाकिस्तान - तूफ़ान (Pakistan - Storm)","text_en":"पाकिस्तान - तूफ़ान (Pakistan - Storm)"},{"id":"D","text":"ओमान - हवा (Oman - Wind)","text_en":"ओमान - हवा (Oman - Wind)"}]', '1', '**✅ Correct Logic:** **बांग्लादेश** ने इसका नाम ''बिपरजॉय'' रखा, जिसका बंगाली में अर्थ है **''आपदा''** या ''विपत्ति'' (Disaster)। यह अरब सागर में सबसे लंबे समय तक रहने वाला चक्रवात बन गया था।

**💡 Exam Fact:** इसने गुजरात और राजस्थान में भारी बारिश की।

**🧠 Memory Tip:** **B**angladesh named **B**iparjoy (Bad Joy = Disaster).

**🚫 Scam Alert:** नाम प्यारा लग सकता है (Joy), लेकिन मतलब ''आपदा'' है।', 2, 0, 3, NULL, 'Which country named the cyclone ''Biparjoy'' that hit the Arabian Sea in 2023 and what does it mean?', '**✅ Correct Logic:** Named by **Bangladesh**. Means **''Disaster''** or ''Calamity'' in Bengali. It had longest lifespan in Arabian Sea.

**💡 Exam Fact:** Caused heavy rain in Gujarat/Rajasthan.

**🧠 Memory Tip:** **B**angladesh named **B**iparjoy.

**🚫 Scam Alert:** Sounds like Joy, means Disaster.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('297989e2-c87a-4247-928b-0f47de7af628', '14a4f30c-370f-40b2-9396-87130dd62644', 'चक्रवात की ''आँख'' (Eye of Cyclone) की विशेषता क्या है?', '[{"id":"A","text":"अत्यधिक उच्च दबाव और तेज हवाएँ","text_en":"अत्यधिक उच्च दबाव और तेज हवाएँ"},{"id":"B","text":"शांत क्षेत्र और साफ आसमान (Calm region and clear sky)","text_en":"शांत क्षेत्र और साफ आसमान (Calm region and clear sky)"},{"id":"C","text":"सबसे ज्यादा बारिश और बादल","text_en":"सबसे ज्यादा बारिश और बादल"},{"id":"D","text":"बिजली गिरना","text_en":"बिजली गिरना"}]', '1', '**✅ Correct Logic:** चक्रवात की आँख केंद्र में होती है जहाँ **दबाव सबसे कम** (Lowest Pressure) होता है, हवा शांत होती है और **आसमान साफ** होता है। हवाएँ आँख के चारों ओर (Eye Wall) घूमती हैं, आँख में नहीं।

**💡 Exam Fact:** ''Eye Wall'' सबसे विनाशकारी हिस्सा होता है।

**🧠 Memory Tip:** Eye is **Silent**, Wall is **Violent**.

**🚫 Scam Alert:** लोग सोचते हैं आँख खतरनाक होती है, लेकिन वह शांत होती है। खतरा दीवार (Wall) में है।', 2, 0, 4, NULL, 'What is the characteristic of the ''Eye of Cyclone''?', '**✅ Correct Logic:** Eye is the center with **Lowest Pressure**, **Calm winds**, and **Clear sky**. Winds rotate around it (Eye Wall).

**💡 Exam Fact:** ''Eye Wall'' is the most destructive part.

**🧠 Memory Tip:** Eye is **Silent**, Wall is **Violent**.

**🚫 Scam Alert:** Eye is calm. Don''t confuse with Eye Wall.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cd8692b0-8d8e-4fe2-badd-062f9a6344c0', '14a4f30c-370f-40b2-9396-87130dd62644', 'IMD के अनुसार, एक ''सुपर साइक्लोन'' (Super Cyclone) में हवा की गति कम से कम कितनी होनी चाहिए?', '[{"id":"A","text":"118 किमी/घंटा","text_en":"118 किमी/घंटा"},{"id":"B","text":"166 किमी/घंटा","text_en":"166 किमी/घंटा"},{"id":"C","text":"221 किमी/घंटा (221 kmph)","text_en":"221 किमी/घंटा (221 kmph)"},{"id":"D","text":"200 किमी/घंटा","text_en":"200 किमी/घंटा"}]', '2', '**✅ Correct Logic:** **221 किमी/घंटा** (120 नॉट्स) या उससे अधिक की गति होने पर उसे ''सुपर साइक्लोनिक स्टॉर्म'' कहा जाता है। अम्फान (Amphan) एक सुपर साइक्लोन था।

**💡 Exam Fact:** यह वर्गीकरण का सर्वोच्च स्तर है।

**🧠 Memory Tip:** **Super** fast > **220**.

**🚫 Scam Alert:** 118 kmph पर तो बस ''Severe'' बनता है। सुपर के लिए 220+ चाहिए।', 2, 0, 5, NULL, 'As per IMD, what should be the minimum wind speed in a ''Super Cyclone''?', '**✅ Correct Logic:** **221 kmph** (120 knots) or more makes it a ''Super Cyclonic Storm''. Amphan was one.

**💡 Exam Fact:** Highest classification level.

**🧠 Memory Tip:** **Super** fast > **220**.

**🚫 Scam Alert:** 118 is just Severe. Super needs 220+.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e56cce3f-e81c-4a5e-8e00-d65fef56c2ff', '14a4f30c-370f-40b2-9396-87130dd62644', 'अरब सागर की तुलना में बंगाल की खाड़ी में अधिक चक्रवात क्यों आते हैं?', '[{"id":"A","text":"बंगाल की खाड़ी का पानी ठंडा है","text_en":"बंगाल की खाड़ी का पानी ठंडा है"},{"id":"B","text":"बंगाल की खाड़ी का तापमान अधिक है और यह तीन तरफ से घिरी है (Higher temp & Landlocked)","text_en":"बंगाल की खाड़ी का तापमान अधिक है और यह तीन तरफ से घिरी है (Higher temp & Landlocked)"},{"id":"C","text":"अरब सागर में लवणता कम है","text_en":"अरब सागर में लवणता कम है"},{"id":"D","text":"पछुआ हवाएँ अरब सागर को शांत रखती हैं","text_en":"पछुआ हवाएँ अरब सागर को शांत रखती हैं"}]', '1', '**✅ Correct Logic:** बंगाल की खाड़ी का **सतह तापमान (SST) अधिक** होता है और यह आकार में संकरी (Confined) है, जिससे वाष्पीकरण और अस्थिरता बढ़ती है। साथ ही, प्रशांत महासागर से आने वाले अवशेष (Remnants) भी यहाँ फिर से सक्रिय हो जाते हैं।

**💡 Exam Fact:** अनुपात लगभग 4:1 (बंगाल की खाड़ी : अरब सागर) है।

**🧠 Memory Tip:** **B**ay is **B**oiling (Warm) -> More Cyclones.

**🚫 Scam Alert:** अरब सागर ठंडा है, इसलिए वहां कम चक्रवात बनते हैं (हालांकि अब ग्लोबल वार्मिंग से बढ़ रहे हैं)।', 2, 0, 6, NULL, 'Why do more cyclones occur in the Bay of Bengal compared to the Arabian Sea?', '**✅ Correct Logic:** Bay of Bengal has **Higher Sea Surface Temp (SST)** and is confined, aiding instability. Also receives remnants from Pacific typhoons.

**💡 Exam Fact:** Ratio is approx 4:1.

**🧠 Memory Tip:** **B**ay is **B**oiling.

**🚫 Scam Alert:** Arabian Sea is cooler, hence fewer cyclones usually.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('76292c7a-9890-409e-b269-cf184e0d4c02', '14a4f30c-370f-40b2-9396-87130dd62644', 'चक्रवात ''तौकते'' (Tauktae), जिसने 2021 में पश्चिमी तट पर तबाही मचाई, का नाम किसने दिया था और इसका अर्थ क्या है?', '[{"id":"A","text":"मालदीव - केकड़ा","text_en":"मालदीव - केकड़ा"},{"id":"B","text":"म्यांमार - शोर मचाने वाली छिपकली (Myanmar - Gecko)","text_en":"म्यांमार - शोर मचाने वाली छिपकली (Myanmar - Gecko)"},{"id":"C","text":"थाईलैंड - हाथी","text_en":"थाईलैंड - हाथी"},{"id":"D","text":"ओमान - तितली","text_en":"ओमान - तितली"}]', '1', '**✅ Correct Logic:** **म्यांमार** ने इसका नाम दिया। ''तौकते'' का अर्थ बर्मी भाषा में **''गेको''** (Gecko - एक प्रकार की छिपकली) है जो बहुत शोर करती है।

**💡 Exam Fact:** यह एक ''अत्यधिक गंभीर'' (Extremely Severe) चक्रवात था।

**🧠 Memory Tip:** **Talk**-tae -> **Talk**ative Lizard (Gecko) from **Myanmar**.

**🚫 Scam Alert:** तितली (Titli) पाकिस्तान ने दिया था, तौकते म्यांमार ने।', 2, 0, 7, NULL, 'Cyclone ''Tauktae'' (2021) was named by whom and what does it mean?', '**✅ Correct Logic:** Named by **Myanmar**. Means **''Gecko''** (a loud lizard). 

**💡 Exam Fact:** Extremely Severe cyclone on West Coast.

**🧠 Memory Tip:** **Talk**-tae -> **Talk**ative Lizard.

**🚫 Scam Alert:** Titli was Pakistan, Tauktae is Myanmar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('264273ab-88cf-4796-895e-165380157eac', '14a4f30c-370f-40b2-9396-87130dd62644', '''फेनी'' (Fani) चक्रवात, जो 2019 में ओडिशा से टकराया था, उसका नाम किस देश ने दिया और इसका मतलब क्या है?', '[{"id":"A","text":"भारत - हवा","text_en":"भारत - हवा"},{"id":"B","text":"बांग्लादेश - सांप का फन (Bangladesh - Snake''s Hood)","text_en":"बांग्लादेश - सांप का फन (Bangladesh - Snake''s Hood)"},{"id":"C","text":"श्रीलंका - पत्थर","text_en":"श्रीलंका - पत्थर"},{"id":"D","text":"मालदीव - आग","text_en":"मालदीव - आग"}]', '1', '**✅ Correct Logic:** **बांग्लादेश** ने नाम दिया। ''फनी'' (Fani) का अर्थ है **''सांप का फन''** (Hood of a Snake)।

**💡 Exam Fact:** यह बहुत ही दुर्लभ ''लूप'' ट्रैक वाला चक्रवात था।

**🧠 Memory Tip:** **Fani** -> **Fun** (Snake hood) -> **Bangla** nagin dance.

**🚫 Scam Alert:** उच्चारण ''फोनी'' है, लेकिन स्पेलिंग Fani है।', 2, 0, 8, NULL, 'Which country named cyclone ''Fani'' (2019) and what does it mean?', '**✅ Correct Logic:** Named by **Bangladesh**. Means **''Snake''s Hood''**.

**💡 Exam Fact:** Rare loop track cyclone.

**🧠 Memory Tip:** **Fani** -> **Fun** (Hood).

**🚫 Scam Alert:** Pronounced ''Foni''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('99863ae5-e941-49c1-82eb-e49faa0d2af1', '14a4f30c-370f-40b2-9396-87130dd62644', 'रंग कोड (Colour Code) के अनुसार, IMD द्वारा ''रेड अलर्ट'' (Red Alert) का क्या अर्थ है?', '[{"id":"A","text":"खतरे के प्रति सचेत रहें (Be updated)","text_en":"खतरे के प्रति सचेत रहें (Be updated)"},{"id":"B","text":"तैयार रहें (Be prepared)","text_en":"तैयार रहें (Be prepared)"},{"id":"C","text":"कार्रवाई करें (Take Action)","text_en":"कार्रवाई करें (Take Action)"},{"id":"D","text":"कोई खतरा नहीं (No warning)","text_en":"कोई खतरा नहीं (No warning)"}]', '2', '**✅ Correct Logic:** 
* येलो: अपडेट रहें (Be updated).
* ऑरेंज: तैयार रहें (Be prepared).
* **रेड: कार्रवाई करें** (Take Action - Evacuation etc.).

**💡 Exam Fact:** यह मौसम की गंभीरता को दर्शाता है।

**🧠 Memory Tip:** Red light -> Stop everything and **Act**.

**🚫 Scam Alert:** ऑरेंज में तैयारी होती है, रेड में भागना (Action) होता है।', 2, 0, 9, NULL, 'According to Colour Codes, what does ''Red Alert'' mean by IMD?', '**✅ Correct Logic:** 
* Yellow: Be updated.
* Orange: Be prepared.
* **Red: Take Action** (Evacuate).

**💡 Exam Fact:** Indicates severity.

**🧠 Memory Tip:** Red -> **Act**.

**🚫 Scam Alert:** Orange is prep, Red is Action.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bb5519c8-ea3c-44eb-ad6c-de7453984228', '14a4f30c-370f-40b2-9396-87130dd62644', 'निम्नलिखित चक्रवातों को उनके प्रभावित क्षेत्र/विशेषता से सुमेलित करें (Match the cyclones with their region/feature):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **अम्फान**: 2020 में सुंदरबन/बंगाल को तबाह किया। -> (1)-(a)
* **हुदहुद**: 2014 में विशाखापत्तनम (Vizag) को हिट किया। ओमान ने नाम दिया (हुदहुद पक्षी)। -> (2)-(b)
* **ओखी**: 2017 में दक्षिण भारत में आया, मछुआरों को भारी नुकसान। -> (3)-(c)
* **निसर्ग**: 2020 में अलीबाग (महाराष्ट्र) में आया। -> (4)-(d)

**💡 Exam Fact:** ओखी का अर्थ बंगाली में ''आँख'' है (बांग्लादेश ने दिया)।

**🧠 Memory Tip:** **Amphan**-Bengal. **Hudhud**-Vizag. **Ockhi**-South. **Nisarga**-Maharashtra.

**🚫 Scam Alert:** हुदहुद बहुत प्रसिद्ध था क्योंकि इसने Vizag शहर को तहस-नहस कर दिया था।', 2, 0, 10, NULL, 'Match the cyclones with their region/feature:', '**✅ Correct Matching:**
* **Amphan**: Bengal (2020). -> (1)-(a)
* **Hudhud**: Vizag (2014). Named after bird. -> (2)-(b)
* **Ockhi**: South India (2017). -> (3)-(c)
* **Nisarga**: Maharashtra (2020). -> (4)-(d)

**💡 Exam Fact:** Ockhi means Eye.

**🧠 Memory Tip:** Direct region match.

**🚫 Scam Alert:** Hudhud hit Vizag city directly.', 60, 'matching', '[{"id":"(1)","label":"अम्फान (Amphan)","match":"पश्चिम बंगाल (सुपर साइक्लोन)","matchId":"(a)"},{"id":"(2)","label":"हुदहुद (Hudhud)","match":"विशाखापत्तनम (पक्षी के नाम पर)","matchId":"(b)"},{"id":"(3)","label":"ओखी (Ockhi)","match":"केरल/तमिलनाडु (Rapid intensification)","matchId":"(c)"},{"id":"(4)","label":"निसर्ग (Nisarga)","match":"महाराष्ट्र (मुंबई के पास लैंडफॉल)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a8ac4633-9523-448e-b4da-4e62a2639b5e', '4768e206-14c9-4efe-b088-f4c761c70972', 'भारत की 2011 की जनगणना के अनुसार, जनसंख्या घनत्व (Density) कितना है?', '[{"id":"A","text":"324 व्यक्ति/वर्ग किमी","text_en":"324 व्यक्ति/वर्ग किमी"},{"id":"B","text":"382 व्यक्ति/वर्ग किमी","text_en":"382 व्यक्ति/वर्ग किमी"},{"id":"C","text":"400 व्यक्ति/वर्ग किमी","text_en":"400 व्यक्ति/वर्ग किमी"},{"id":"D","text":"350 व्यक्ति/वर्ग किमी","text_en":"350 व्यक्ति/वर्ग किमी"}]', '1', '**✅ Correct Logic:** 2011 में घनत्व **382** व्यक्ति प्रति वर्ग किमी था। 2001 में यह 325 था।

**💡 Exam Fact:** सबसे अधिक घनत्व वाला राज्य **बिहार** (1106) है।

**🧠 Memory Tip:** **3** people ate **8** dosas in **2** mins -> 382.

**🚫 Scam Alert:** 2001 का डेटा (325) मत चुनना। 2011 का 382 है।', 2, 0, 1, NULL, 'According to 2011 Census, what is the Population Density of India?', '**✅ Correct Logic:** In 2011, density was **382** persons/sq km. In 2001, it was 325.

**💡 Exam Fact:** Highest density state is **Bihar** (1106).

**🧠 Memory Tip:** **3-8-2**.

**🚫 Scam Alert:** Don''t pick 2001 data.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6bf9e875-dc5f-4ff5-be25-3c4eaee51450', '4768e206-14c9-4efe-b088-f4c761c70972', 'भारत के इतिहास में किस वर्ष को ''महान विभाजक वर्ष'' (Year of Great Divide) कहा जाता है?', '[{"id":"A","text":"1911","text_en":"1911"},{"id":"B","text":"1921","text_en":"1921"},{"id":"C","text":"1951","text_en":"1951"},{"id":"D","text":"1971","text_en":"1971"}]', '1', '**✅ Correct Logic:** **1921** को महान विभाजक वर्ष कहते हैं क्योंकि 1911-1921 के दशक में जनसंख्या में **गिरावट** (-0.31%) दर्ज की गई थी (फ्लू महामारी और अकाल के कारण)। इसके बाद जनसंख्या लगातार बढ़ी।

**💡 Exam Fact:** 1951 को ''लघु विभाजक'' (Small Divide) कहते हैं।

**🧠 Memory Tip:** **1921** was the only **Minus** year.

**🚫 Scam Alert:** 1951 या 1971 (विस्फोट) नहीं। 1921 एकमात्र ऋणात्मक वृद्धि वाला साल था।', 2, 0, 2, NULL, 'Which year is called the ''Year of Great Divide'' in the demographic history of India?', '**✅ Correct Logic:** **1921** is the Great Divide. Population **declined** (-0.31%) between 1911-1921 due to Flu epidemic. After this, it always increased.

**💡 Exam Fact:** 1951 is Small Divide.

**🧠 Memory Tip:** **1921** was **Minus**.

**🚫 Scam Alert:** Only year with negative growth.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4a379b71-9794-42e5-988e-d976e3841d29', '4768e206-14c9-4efe-b088-f4c761c70972', '2011 की जनगणना के अनुसार, भारत में लिंगानुपात (Sex Ratio) कितना है?', '[{"id":"A","text":"933","text_en":"933"},{"id":"B","text":"940","text_en":"940"},{"id":"C","text":"943","text_en":"943"},{"id":"D","text":"927","text_en":"927"}]', '2', '**✅ Correct Logic:** 2011 में भारत का लिंगानुपात **943** महिलाएं प्रति 1000 पुरुष है। 2001 में यह 933 था।

**💡 Exam Fact:** **केरल** (1084) में सबसे अधिक और **हरियाणा** (879) में सबसे कम है।

**🧠 Memory Tip:** I love you (143) -> 9**43**.

**🚫 Scam Alert:** कई किताबों में 940 लिखा है (Provisional data), लेकिन फाइनल डेटा **943** है।', 2, 0, 3, NULL, 'What is the Sex Ratio in India as per 2011 Census?', '**✅ Correct Logic:** **943** females per 1000 males. In 2001, it was 933.

**💡 Exam Fact:** **Kerala** (1084) Highest, **Haryana** (879) Lowest.

**🧠 Memory Tip:** 143 -> 9**43**.

**🚫 Scam Alert:** Provisional was 940, Final is 943.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e0318893-a42d-4abe-bc49-e4b576884e1d', '4768e206-14c9-4efe-b088-f4c761c70972', 'भारत की जनसंख्या वृद्धि दर (Decadal Growth Rate) 2001-2011 के दौरान कितनी थी?', '[{"id":"A","text":"21.54%","text_en":"21.54%"},{"id":"B","text":"17.7%","text_en":"17.7%"},{"id":"C","text":"24.8%","text_en":"24.8%"},{"id":"D","text":"15.9%","text_en":"15.9%"}]', '1', '**✅ Correct Logic:** 2001-2011 के दौरान दशकीय वृद्धि दर **17.7%** थी (पूर्ण संख्या में 18 करोड़ लोग जुड़े)। 1991-2001 में यह 21.54% थी। गिरावट आई है, जो अच्छा संकेत है।

**💡 Exam Fact:** **नागालैंड** (-0.6%) एकमात्र राज्य था जहाँ जनसंख्या घटी।

**🧠 Memory Tip:** 17 pe khatra -> **17.7**%.

**🚫 Scam Alert:** 21.54% पुरानी दर (1991-01) है। अब 17.7% है।', 2, 0, 4, NULL, 'What was India''s Decadal Population Growth Rate during 2001-2011?', '**✅ Correct Logic:** **17.7%** growth rate. Dropped from 21.54% in previous decade.

**💡 Exam Fact:** **Nagaland** (-0.6%) showed negative growth.

**🧠 Memory Tip:** **17.7**%.

**🚫 Scam Alert:** Don''t confuse with 1991-2001 rate.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('79bc54ea-7ab4-468d-9445-a720e44a40f3', '4768e206-14c9-4efe-b088-f4c761c70972', 'किस केंद्र शासित प्रदेश (UT) का जनसंख्या घनत्व सबसे कम है?', '[{"id":"A","text":"लद्दाख (Ladakh)","text_en":"लद्दाख (Ladakh)"},{"id":"B","text":"अंडमान और निकोबार (Andaman & Nicobar)","text_en":"अंडमान और निकोबार (Andaman & Nicobar)"},{"id":"C","text":"लक्षद्वीप (Lakshadweep)","text_en":"लक्षद्वीप (Lakshadweep)"},{"id":"D","text":"दादरा और नगर हवेली (Dadra & Nagar Haveli)","text_en":"दादरा और नगर हवेली (Dadra & Nagar Haveli)"}]', '1', '**✅ Correct Logic:** 2011 के अनुसार **अंडमान और निकोबार** का घनत्व सबसे कम (46 व्यक्ति/वर्ग किमी) था। *Note: Ladakh was part of J&K in 2011 census.* अगर वर्तमान परिदृश्य में देखें तो लद्दाख सबसे कम होगा, लेकिन "2011 की जनगणना" के आधार पर अंडमान सही है।

**💡 Exam Fact:** सबसे अधिक घनत्व वाला UT **दिल्ली** (11,320) है।

**🧠 Memory Tip:** **Anda** (Egg) in ocean -> floating alone -> Low density.

**🚫 Scam Alert:** अगर विकल्प में लद्दाख है और प्रश्न ''वर्तमान'' पूछता है, तो लद्दाख। अगर ''2011 जनगणना'' पूछता है, तो अंडमान।', 2, 0, 5, NULL, 'Which Union Territory has the lowest Population Density?', '**✅ Correct Logic:** As per 2011, **Andaman & Nicobar** (46) was lowest. (Ladakh was J&K). Currently Ladakh is lowest, but for 2011 census questions, stick to A&N.

**💡 Exam Fact:** Highest is **Delhi**.

**🧠 Memory Tip:** **Anda** alone in ocean.

**🚫 Scam Alert:** Check if Q asks 2011 Census or Current.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f7397ba8-06e8-45fc-8ecd-423134e53c67', '4768e206-14c9-4efe-b088-f4c761c70972', 'भारत का सबसे अधिक आबादी वाला जिला (Most Populous District) कौन सा है (2011)?', '[{"id":"A","text":"ठाणे, महाराष्ट्र (Thane, Maharashtra)","text_en":"ठाणे, महाराष्ट्र (Thane, Maharashtra)"},{"id":"B","text":"उत्तरी 24 परगना, बंगाल (North 24 Parganas, Bengal)","text_en":"उत्तरी 24 परगना, बंगाल (North 24 Parganas, Bengal)"},{"id":"C","text":"बेंगलुरु, कर्नाटक (Bengaluru, Karnataka)","text_en":"बेंगलुरु, कर्नाटक (Bengaluru, Karnataka)"},{"id":"D","text":"पुणे, महाराष्ट्र (Pune, Maharashtra)","text_en":"पुणे, महाराष्ट्र (Pune, Maharashtra)"}]', '0', '**✅ Correct Logic:** **ठाणे** (महाराष्ट्र) 2011 में सबसे अधिक आबादी वाला जिला था (1.1 करोड़)। अब इसका विभाजन (पालघर) हो गया है, लेकिन 2011 के डेटा के लिए ठाणे उत्तर है।

**💡 Exam Fact:** दिबांग घाटी (अरुणाचल) सबसे कम आबादी वाला जिला है।

**🧠 Memory Tip:** **Thane** has a **Ton** of people.

**🚫 Scam Alert:** विभाजन के बाद स्थिति बदली है, लेकिन परीक्षा में ''2011 जनगणना'' ही मानक है।', 2, 0, 6, NULL, 'Which is the Most Populous District of India (2011)?', '**✅ Correct Logic:** **Thane** (Maharashtra) was most populous (1.1 Cr). Though bifurcated now, for 2011 Census Qs, Thane is the answer.

**💡 Exam Fact:** Dibang Valley is least populous.

**🧠 Memory Tip:** **Thane** has a **Ton**.

**🚫 Scam Alert:** Stick to 2011 data.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c4a15dfb-9c8b-45ee-bc6b-65c02a299939', '4768e206-14c9-4efe-b088-f4c761c70972', 'भारत की कुल जनसंख्या में उत्तर प्रदेश का प्रतिशत योगदान लगभग कितना है?', '[{"id":"A","text":"16.5%","text_en":"16.5%"},{"id":"B","text":"20%","text_en":"20%"},{"id":"C","text":"10%","text_en":"10%"},{"id":"D","text":"25%","text_en":"25%"}]', '0', '**✅ Correct Logic:** उत्तर प्रदेश की जनसंख्या (लगभग 20 करोड़) भारत की कुल जनसंख्या का **16.51%** है। यह सबसे बड़ा राज्य है।

**💡 Exam Fact:** अगर यूपी एक देश होता, तो दुनिया में 5वें नंबर पर होता।

**🧠 Memory Tip:** Sweet **16** -> UP is 16%.

**🚫 Scam Alert:** क्षेत्रफल में यह 7.33% है, लेकिन जनसंख्या में 16.5% है।', 2, 0, 7, NULL, 'What is the approximate percentage share of Uttar Pradesh in India''s total population?', '**✅ Correct Logic:** UP contributes **16.51%** to India''s population. It is the most populous state.

**💡 Exam Fact:** If UP was a country, it would rank 5th.

**🧠 Memory Tip:** Sweet **16**.

**🚫 Scam Alert:** Area is 7%, Population is 16.5%.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fb4ffb41-b457-453f-8f03-91a53fe68286', '4768e206-14c9-4efe-b088-f4c761c70972', 'किस राज्य समूह में अनुसूचित जनजाति (ST) की जनसंख्या का प्रतिशत सबसे अधिक है?', '[{"id":"A","text":"मिजोरम और लक्षद्वीप (Mizoram and Lakshadweep)","text_en":"मिजोरम और लक्षद्वीप (Mizoram and Lakshadweep)"},{"id":"B","text":"मध्य प्रदेश और ओडिशा (MP and Odisha)","text_en":"मध्य प्रदेश और ओडिशा (MP and Odisha)"},{"id":"C","text":"झारखंड और छत्तीसगढ़ (Jharkhand and Chhattisgarh)","text_en":"झारखंड और छत्तीसगढ़ (Jharkhand and Chhattisgarh)"},{"id":"D","text":"पंजाब और हरियाणा (Punjab and Haryana)","text_en":"पंजाब और हरियाणा (Punjab and Haryana)"}]', '0', '**✅ Correct Logic:** **लक्षद्वीप** (94.8%) और **मिजोरम** (94.4%) में ST जनसंख्या का प्रतिशत सबसे अधिक है। (UT में लक्षद्वीप, राज्यों में मिजोरम)।

**💡 Exam Fact:** *कुल संख्या* (Total Number) में **मध्य प्रदेश** सबसे ऊपर है। पंजाब/हरियाणा में कोई ST नहीं है।

**🧠 Memory Tip:** **Mizo**ram -> **M**aximum % ST.

**🚫 Scam Alert:** ''प्रतिशत'' पूछा है तो मिजोरम/लक्षद्वीप। ''संख्या'' पूछा है तो एमपी।', 2, 0, 8, NULL, 'Which state group has the highest percentage of Scheduled Tribe (ST) population?', '**✅ Correct Logic:** **Lakshadweep** (UT) and **Mizoram** (State) have highest ST %. (>94%).

**💡 Exam Fact:** **MP** has highest *Total Number* of STs.

**🧠 Memory Tip:** **Mizo**ram -> **M**ax %.

**🚫 Scam Alert:** Percentage vs Total Number. Watch out.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('564af24b-2e22-4426-bf83-8cf792848ff4', '4768e206-14c9-4efe-b088-f4c761c70972', 'भारत में पहली जनगणना (First Census) कब हुई थी और किसके कार्यकाल में?', '[{"id":"A","text":"1872 - लॉर्ड मेयो (Lord Mayo)","text_en":"1872 - लॉर्ड मेयो (Lord Mayo)"},{"id":"B","text":"1881 - लॉर्ड रिपन (Lord Ripon)","text_en":"1881 - लॉर्ड रिपन (Lord Ripon)"},{"id":"C","text":"1891 - लॉर्ड डफरिन (Lord Dufferin)","text_en":"1891 - लॉर्ड डफरिन (Lord Dufferin)"},{"id":"D","text":"1901 - लॉर्ड कर्जन (Lord Curzon)","text_en":"1901 - लॉर्ड कर्जन (Lord Curzon)"}]', '0', '**✅ Correct Logic:** पहली (गैर-तुल्यकालिक/Non-synchronous) जनगणना **1872** में **लॉर्ड मेयो** के समय हुई थी। पहली नियमित/दशकीय (Decennial) जनगणना 1881 में रिपन के समय शुरू हुई।

**💡 Exam Fact:** 2011 15वीं जनगणना थी (स्वतंत्रता के बाद 7वीं)।

**🧠 Memory Tip:** **Mayo**naise was served first in **72**.

**🚫 Scam Alert:** ''पहली'' पूछा है तो 1872। ''पहली नियमित'' पूछा है तो 1881।', 2, 0, 9, NULL, 'When was the First Census held in India and under whose tenure?', '**✅ Correct Logic:** First Census was in **1872** under **Lord Mayo**. First *Regular* Census was in 1881 under Ripon.

**💡 Exam Fact:** 2011 was 15th Census.

**🧠 Memory Tip:** **Mayo** first.

**🚫 Scam Alert:** First vs First Regular.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('21824f21-2cda-4fa1-bae7-7662c58efdf2', '4768e206-14c9-4efe-b088-f4c761c70972', '2011 की जनगणना के अनुसार निम्नलिखित राज्यों को साक्षरता दर (Literacy Rate) से सुमेलित करें (Match states with Literacy Rate):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **केरल**: उच्चतम (94%)। -> (1)-(a)
* **बिहार**: न्यूनतम (61.8%)। -> (2)-(b)
* **मिजोरम**: दूसरा सबसे साक्षर राज्य (91.3%)। -> (3)-(c)
* **भारत औसत**: 74.04%। -> (4)-(d)

**💡 Exam Fact:** पुरुष साक्षरता 82.14% और महिला 65.46% है (अंतर ~16%)।

**🧠 Memory Tip:** Kerala Top, Bihar Bottom, India 74.

**🚫 Scam Alert:** गोवा और मिजोरम में अक्सर रेस होती है दूसरे नंबर के लिए, 2011 में मिजोरम दूसरा है।', 2, 0, 10, NULL, 'Match states with Literacy Rate as per 2011 Census:', '**✅ Correct Matching:**
* **Kerala**: Highest (94%). -> (1)-(a)
* **Bihar**: Lowest (61.8%). -> (2)-(b)
* **Mizoram**: Second Highest (91.3%). -> (3)-(c)
* **India**: 74.04%. -> (4)-(d)

**💡 Exam Fact:** Male-Female gap is ~16%.

**🧠 Memory Tip:** Kerala Top, Bihar Bottom.

**🚫 Scam Alert:** Mizoram is 2nd, not Goa (in 2011).', 60, 'matching', '[{"id":"(1)","label":"केरल (Kerala)","match":"94.0%","matchId":"(a)"},{"id":"(2)","label":"बिहार (Bihar)","match":"61.8%","matchId":"(b)"},{"id":"(3)","label":"मिजोरम (Mizoram)","match":"91.3%","matchId":"(c)"},{"id":"(4)","label":"भारत (India Average)","match":"74.04%","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d17f1d05-707d-4f28-8faf-027ffacb2173', 'cebf4477-d84b-4a68-9968-4711b5f0d2f5', 'भारत में प्रवासन (Migration) का सबसे बड़ा प्रवाह (Stream) कौन सा है?', '[{"id":"A","text":"ग्रामीण से नगरीय (Rural to Urban)","text_en":"ग्रामीण से नगरीय (Rural to Urban)"},{"id":"B","text":"ग्रामीण से ग्रामीण (Rural to Rural)","text_en":"ग्रामीण से ग्रामीण (Rural to Rural)"},{"id":"C","text":"नगरीय से नगरीय (Urban to Urban)","text_en":"नगरीय से नगरीय (Urban to Urban)"},{"id":"D","text":"नगरीय से ग्रामीण (Urban to Rural)","text_en":"नगरीय से ग्रामीण (Urban to Rural)"}]', '1', '**✅ Correct Logic:** **ग्रामीण से ग्रामीण** (Rural to Rural) प्रवास भारत में सबसे अधिक है (कुल प्रवास का ~60%+)। इसका मुख्य कारण **महिलाओं का विवाह** है। महिलाएं शादी के बाद एक गांव से दूसरे गांव जाती हैं।

**💡 Exam Fact:** रोजगार के लिए ''ग्रामीण से नगरीय'' प्रवास पुरुषों में सर्वाधिक है, लेकिन कुल मिलाकर ''विवाह'' (R-R) जीतता है।

**🧠 Memory Tip:** **Marriage** moves more people than **Jobs**.

**🚫 Scam Alert:** हम सोचते हैं कि लोग शहर जा रहे हैं (R-U), लेकिन डेटा कहता है कि शादियों के कारण R-R प्रवास सबसे बड़ा है।', 2, 0, 1, NULL, 'Which is the largest stream of migration in India?', '**✅ Correct Logic:** **Rural to Rural** is the largest stream (~60%+). Main reason is **Marriage** (Women moving between villages).

**💡 Exam Fact:** For ''Employment'', Rural to Urban is highest among males.

**🧠 Memory Tip:** **Marriage** moves more people than **Jobs**.

**🚫 Scam Alert:** Common perception is R-U, but stats say R-R (due to marriage).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9ca6f8af-4290-4378-b0c2-e0bc313d3c58', 'cebf4477-d84b-4a68-9968-4711b5f0d2f5', 'प्रवास के लिए ''पुश फैक्टर'' (Push Factor) का उदाहरण कौन सा है?', '[{"id":"A","text":"बेहतर रोजगार (Better Employment)","text_en":"बेहतर रोजगार (Better Employment)"},{"id":"B","text":"अच्छी शिक्षा (Good Education)","text_en":"अच्छी शिक्षा (Good Education)"},{"id":"C","text":"गरीबी और बेरोजगारी (Poverty and Unemployment)","text_en":"गरीबी और बेरोजगारी (Poverty and Unemployment)"},{"id":"D","text":"मनोरंजन सुविधाएं (Entertainment facilities)","text_en":"मनोरंजन सुविधाएं (Entertainment facilities)"}]', '2', '**✅ Correct Logic:** **गरीबी और बेरोजगारी** लोगों को गांव छोड़ने के लिए मजबूर (Push) करती है। बाकी तीन (रोजगार, शिक्षा, मनोरंजन) शहर की ओर आकर्षित करने वाले **''पुल फैक्टर''** (Pull Factors) हैं।

**💡 Exam Fact:** प्राकृतिक आपदाएँ भी पुश फैक्टर हैं।

**🧠 Memory Tip:** **Push** means Kicking out (Bad things). **Pull** means inviting in (Good things).

**🚫 Scam Alert:** पुश = धक्का देना (नकारात्मक)। पुल = खींचना (सकारात्मक)।', 2, 0, 2, NULL, 'Which is an example of ''Push Factor'' for migration?', '**✅ Correct Logic:** **Poverty and Unemployment** force (Push) people out. The others are **Pull Factors** (attract people).

**💡 Exam Fact:** Disasters are also Push factors.

**🧠 Memory Tip:** **Push** = Kick out. **Pull** = Invite.

**🚫 Scam Alert:** Push is negative, Pull is positive.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8d935283-6478-4dcd-8e8c-5754879fd14c', 'cebf4477-d84b-4a68-9968-4711b5f0d2f5', 'भारत के किस राज्य में ''आप्रवासन'' (In-migration) की संख्या सबसे अधिक है?', '[{"id":"A","text":"उत्तर प्रदेश (Uttar Pradesh)","text_en":"उत्तर प्रदेश (Uttar Pradesh)"},{"id":"B","text":"बिहार (Bihar)","text_en":"बिहार (Bihar)"},{"id":"C","text":"महाराष्ट्र (Maharashtra)","text_en":"महाराष्ट्र (Maharashtra)"},{"id":"D","text":"दिल्ली (Delhi)","text_en":"दिल्ली (Delhi)"}]', '2', '**✅ Correct Logic:** **महाराष्ट्र** में सबसे अधिक लोग बाहर से आते हैं (In-migration), मुख्य रूप से रोजगार के लिए। इसके बाद दिल्ली और गुजरात का स्थान है।

**💡 Exam Fact:** यूपी और बिहार से सबसे अधिक लोग बाहर जाते हैं (Out-migration)।

**🧠 Memory Tip:** **Maha**rashtra is a **Magnet**.

**🚫 Scam Alert:** दिल्ली का घनत्व अधिक है, लेकिन कुल संख्या में महाराष्ट्र टॉप पर है।', 2, 0, 3, NULL, 'Which state in India has the highest number of ''In-migration''?', '**✅ Correct Logic:** **Maharashtra** receives the most migrants (mainly for jobs). Followed by Delhi.

**💡 Exam Fact:** UP and Bihar have highest Out-migration.

**🧠 Memory Tip:** **Maha**rashtra is a **Magnet**.

**🚫 Scam Alert:** UP sends people, Maharashtra receives them.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c47d21d7-799c-443d-84b1-d5fc00433e97', 'cebf4477-d84b-4a68-9968-4711b5f0d2f5', '''ब्रेन ड्रेन'' (Brain Drain) का क्या अर्थ है?', '[{"id":"A","text":"अकुशल मजदूरों का प्रवास (Migration of unskilled laborers)","text_en":"अकुशल मजदूरों का प्रवास (Migration of unskilled laborers)"},{"id":"B","text":"कुशल और शिक्षित पेशेवरों का विदेश प्रवास (Emigration of skilled/educated professionals)","text_en":"कुशल और शिक्षित पेशेवरों का विदेश प्रवास (Emigration of skilled/educated professionals)"},{"id":"C","text":"दिमागी बीमारी का प्रसार","text_en":"दिमागी बीमारी का प्रसार"},{"id":"D","text":"गाँव से शहर की ओर जाना","text_en":"गाँव से शहर की ओर जाना"}]', '1', '**✅ Correct Logic:** जब डॉक्टर, इंजीनियर, और वैज्ञानिक जैसे **कुशल पेशेवर** (Skilled Professionals) बेहतर अवसरों के लिए अपना देश छोड़ देते हैं, तो इसे **प्रतिभा पलायन** या ब्रेन ड्रेन कहते हैं।

**💡 Exam Fact:** जब वे वापस आते हैं, तो इसे ''ब्रेन गेन'' (Brain Gain) कहते हैं।

**🧠 Memory Tip:** **Brains** (Smart people) **Draining** out of the country.

**🚫 Scam Alert:** मजदूरों का जाना ब्रेन ड्रेन नहीं है, यह लेबर माइग्रेशन है।', 2, 0, 4, NULL, 'What does ''Brain Drain'' mean?', '**✅ Correct Logic:** Migration of **Skilled Professionals** (Doctors, Engineers) to other countries for better opportunities.

**💡 Exam Fact:** Return is called ''Brain Gain''.

**🧠 Memory Tip:** **Smart** people leaving.

**🚫 Scam Alert:** Laborers leaving is not Brain Drain.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('90006481-9489-4a33-86de-e19861f0ff17', 'cebf4477-d84b-4a68-9968-4711b5f0d2f5', 'जनगणना 2011 के अनुसार, प्रवासन का डेटा किस आधार पर एकत्र किया जाता है?', '[{"id":"A","text":"केवल जन्म स्थान (Place of Birth)","text_en":"केवल जन्म स्थान (Place of Birth)"},{"id":"B","text":"केवल निवास का स्थान (Place of Residence)","text_en":"केवल निवास का स्थान (Place of Residence)"},{"id":"C","text":"जन्म स्थान और अंतिम निवास स्थान दोनों (Both Place of Birth and Place of Last Residence)","text_en":"जन्म स्थान और अंतिम निवास स्थान दोनों (Both Place of Birth and Place of Last Residence)"},{"id":"D","text":"केवल राष्ट्रीयता (Nationality)","text_en":"केवल राष्ट्रीयता (Nationality)"}]', '2', '**✅ Correct Logic:** जनगणना में दो प्रश्न पूछे जाते हैं: 1. क्या आप यहाँ पैदा हुए थे? (जन्म स्थान) 2. क्या आप कहीं और से आए हैं? (अंतिम निवास स्थान - Place of Last Residence)। इन **दोनों** के आधार पर डेटा बनता है।

**💡 Exam Fact:** ''अंतिम निवास'' अधिक महत्वपूर्ण है क्योंकि यह हालिया प्रवास को दर्शाता है।

**🧠 Memory Tip:** **Birth** & **Last** home.

**🚫 Scam Alert:** दोनों का उपयोग होता है, केवल एक का नहीं।', 2, 0, 5, NULL, 'As per Census 2011, on what basis is migration data collected?', '**✅ Correct Logic:** Data is collected on **Both**: 1. Place of Birth and 2. Place of Last Residence.

**💡 Exam Fact:** ''Last Residence'' tracks recent movement.

**🧠 Memory Tip:** **Birth** & **Last** home.

**🚫 Scam Alert:** Both are used.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('adaf4f6f-3e89-4854-b9a2-ac9dca40a285', 'cebf4477-d84b-4a68-9968-4711b5f0d2f5', 'अंतर्राष्ट्रीय प्रवासियों (International Migrants) के लिए दुनिया का सबसे बड़ा गंतव्य (Destination) कौन सा देश है?', '[{"id":"A","text":"भारत (India)","text_en":"भारत (India)"},{"id":"B","text":"चीन (China)","text_en":"चीन (China)"},{"id":"C","text":"संयुक्त राज्य अमेरिका (USA)","text_en":"संयुक्त राज्य अमेरिका (USA)"},{"id":"D","text":"जर्मनी (Germany)","text_en":"जर्मनी (Germany)"}]', '2', '**✅ Correct Logic:** **USA** दुनिया में प्रवासियों के लिए सबसे बड़ा गंतव्य है। वहाँ सबसे ज्यादा प्रवासी रहते हैं।

**💡 Exam Fact:** **भारत** दुनिया का सबसे बड़ा ''स्रोत'' (Source) देश है (सबसे ज्यादा भारतीय बाहर रहते हैं - लगभग 1.8 करोड़)।

**🧠 Memory Tip:** Everyone wants the **American Dream**.

**🚫 Scam Alert:** भारत *भेजने* में नंबर 1 है, अमेरिका *पाने* में नंबर 1 है।', 2, 0, 6, NULL, 'Which country is the largest destination for International Migrants in the world?', '**✅ Correct Logic:** **USA** is the top destination.

**💡 Exam Fact:** **India** is the top **Source** country (Origin).

**🧠 Memory Tip:** American Dream.

**🚫 Scam Alert:** India sends, USA receives.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a8d89ade-6d54-4b27-b5a5-8290a660382d', 'cebf4477-d84b-4a68-9968-4711b5f0d2f5', 'प्रवासन के परिणाम (Consequences) के संदर्भ में ''रेमिटेंस'' (Remittance) क्या है?', '[{"id":"A","text":"प्रवासियों द्वारा भेजा गया पैसा (Money sent by migrants)","text_en":"प्रवासियों द्वारा भेजा गया पैसा (Money sent by migrants)"},{"id":"B","text":"प्रवासियों द्वारा फैलाया गया कचरा","text_en":"प्रवासियों द्वारा फैलाया गया कचरा"},{"id":"C","text":"प्रवासियों का राजनीतिक अधिकार","text_en":"प्रवासियों का राजनीतिक अधिकार"},{"id":"D","text":"वापस लौटने की प्रक्रिया","text_en":"वापस लौटने की प्रक्रिया"}]', '0', '**✅ Correct Logic:** जब प्रवासी कामगार अपने घर/देश पैसा भेजते हैं, तो उसे **विप्रेषण** या **रेमिटेंस** कहते हैं। भारत दुनिया में सबसे ज्यादा रेमिटेंस प्राप्त करने वाला देश है (World Bank Report)।

**💡 Exam Fact:** 2023 में भारत को $100 बिलियन से अधिक रेमिटेंस मिला।

**🧠 Memory Tip:** **Re**-mittance -> Money **Re**turning home.

**🚫 Scam Alert:** यह विदेशी निवेश (FDI) नहीं है, यह पारिवारिक पैसा है।', 2, 0, 7, NULL, 'In the context of consequences of migration, what is ''Remittance''?', '**✅ Correct Logic:** **Money sent by migrants** to their home country. India is the top receiver globally.

**💡 Exam Fact:** India crossed $100 Billion mark.

**🧠 Memory Tip:** **Re**turning money.

**🚫 Scam Alert:** Not FDI. It''s family money.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3259af12-ad72-470b-a925-c24b6b4c1f39', 'cebf4477-d84b-4a68-9968-4711b5f0d2f5', 'शहरीकरण (Urbanization) और प्रवासन के कारण शहरों में कौन सी समस्या उत्पन्न होती है?', '[{"id":"A","text":"मलिन बस्तियों (Slums) का निर्माण","text_en":"मलिन बस्तियों (Slums) का निर्माण"},{"id":"B","text":"पर्यावरणीय प्रदूषण","text_en":"पर्यावरणीय प्रदूषण"},{"id":"C","text":"संसाधनों पर दबाव","text_en":"संसाधनों पर दबाव"},{"id":"D","text":"उपर्युक्त सभी (All of the above)","text_en":"उपर्युक्त सभी (All of the above)"}]', '3', '**✅ Correct Logic:** अनियंत्रित प्रवास से शहरों में **स्लम** (जैसे धारावी), प्रदूषण, ट्रैफिक और पानी/बिजली पर दबाव बढ़ता है। ये सभी नकारात्मक परिणाम हैं।

**💡 Exam Fact:** 2011 में भारत की शहरी आबादी 31.16% थी।

**🧠 Memory Tip:** Too many people -> **All** problems start.

**🚫 Scam Alert:** ''उपर्युक्त सभी'' यहाँ सही है, क्योंकि प्रवास का बहुआयामी प्रभाव होता है।', 2, 0, 8, NULL, 'Which problem arises in cities due to Urbanization and Migration?', '**✅ Correct Logic:** Uncontrolled migration leads to **Slums**, Pollution, and pressure on resources. **All of the above**.

**💡 Exam Fact:** Urban population was 31.16% in 2011.

**🧠 Memory Tip:** **All** problems.

**🚫 Scam Alert:** All are valid consequences.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a0bd9d8a-2c8d-4d9d-9a04-7842f6d2ebe3', 'cebf4477-d84b-4a68-9968-4711b5f0d2f5', 'भारत में ''स्मार्ट सिटी मिशन'' (Smart City Mission) का उद्देश्य क्या है?', '[{"id":"A","text":"केवल मुफ्त वाई-फाई देना","text_en":"केवल मुफ्त वाई-फाई देना"},{"id":"B","text":"प्रवास को रोकना","text_en":"प्रवास को रोकना"},{"id":"C","text":"मूल बुनियादी ढांचे और जीवन की गुणवत्ता में सुधार करना (Improve core infrastructure and quality of life)","text_en":"मूल बुनियादी ढांचे और जीवन की गुणवत्ता में सुधार करना (Improve core infrastructure and quality of life)"},{"id":"D","text":"सभी को सरकारी नौकरी देना","text_en":"सभी को सरकारी नौकरी देना"}]', '2', '**✅ Correct Logic:** स्मार्ट सिटी मिशन (2015) का लक्ष्य 100 शहरों में **बुनियादी ढांचे** (पानी, बिजली, कचरा प्रबंधन) को सुधारना और तकनीक के माध्यम से जीवन की गुणवत्ता बेहतर करना है, ताकि वे शहरीकरण के दबाव को झेल सकें।

**💡 Exam Fact:** भुवनेश्वर पहला चयनित स्मार्ट सिटी था।

**🧠 Memory Tip:** **Smart** means Efficient Living.

**🚫 Scam Alert:** प्रवास रोकना नहीं, बल्कि शहरों को *रहने योग्य* बनाना लक्ष्य है।', 2, 0, 9, NULL, 'What is the objective of ''Smart City Mission'' in India?', '**✅ Correct Logic:** Launched in 2015 to **improve core infrastructure** and quality of life in 100 cities using technology.

**💡 Exam Fact:** Bhubaneswar was the 1st Smart City.

**🧠 Memory Tip:** **Smart** living.

**🚫 Scam Alert:** Aim is not to stop migration, but to manage it better.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4558200c-77e1-436f-adff-aa796d154707', 'cebf4477-d84b-4a68-9968-4711b5f0d2f5', 'निम्नलिखित प्रवास के प्रकारों को उनके मुख्य कारण से सुमेलित करें (Match the migration types with their main reason):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **R-R**: विवाह (महिलाएं)। -> (1)-(a)
* **R-U**: रोजगार (पुरुष)। -> (2)-(b)
* **U-U**: छोटी सिटी से मेट्रो सिटी (बेहतर वेतन या ट्रांसफर)। -> (3)-(c)
* **U-R**: रिटायरमेंट के बाद या कोविड जैसे संकट में (Reverse Migration)। -> (4)-(d)

**💡 Exam Fact:** कोविड लॉकडाउन में U-R प्रवास का बड़ा उदाहरण देखा गया था।

**🧠 Memory Tip:** Marriage in village. Job in City. Better Job in Big City. Back to Village for Peace.

**🚫 Scam Alert:** सीधा लॉजिक है, लेकिन R-R (विवाह) सबसे बड़ा वॉल्यूम है, इसे न भूलें।', 2, 0, 10, NULL, 'Match the migration types with their main reason:', '**✅ Correct Matching:**
* **R-R**: Marriage (Women). -> (1)-(a)
* **R-U**: Jobs (Men). -> (2)-(b)
* **U-U**: Better jobs/Transfer. -> (3)-(c)
* **U-R**: Reverse Migration (Retirement/Covid). -> (4)-(d)

**💡 Exam Fact:** Covid showed massive U-R migration.

**🧠 Memory Tip:** Marriage-Village, Job-City.

**🚫 Scam Alert:** R-R is the biggest volume.', 60, 'matching', '[{"id":"(1)","label":"ग्रामीण से ग्रामीण (Rural to Rural)","match":"विवाह (Marriage)","matchId":"(a)"},{"id":"(2)","label":"ग्रामीण से नगरीय (Rural to Urban)","match":"रोजगार (Employment)","matchId":"(b)"},{"id":"(3)","label":"नगरीय से नगरीय (Urban to Urban)","match":"बेहतर अवसर/ट्रांसफर (Better Opportunities/Transfer)","matchId":"(c)"},{"id":"(4)","label":"नगरीय से ग्रामीण (Urban to Rural)","match":"रिवर्स माइग्रेशन (Reverse Migration - e.g. Covid/Retirement)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('afba8fd7-f9c7-46dd-977c-f0788f6e1003', 'ac84f7bc-37d7-4119-a9a1-07e0dc0b9a22', '2011 की जनगणना के अनुसार, मध्य प्रदेश का जनसंख्या घनत्व (Population Density) कितना है?', '[{"id":"A","text":"196 व्यक्ति/वर्ग किमी","text_en":"196 व्यक्ति/वर्ग किमी"},{"id":"B","text":"236 व्यक्ति/वर्ग किमी","text_en":"236 व्यक्ति/वर्ग किमी"},{"id":"C","text":"382 व्यक्ति/वर्ग किमी","text_en":"382 व्यक्ति/वर्ग किमी"},{"id":"D","text":"282 व्यक्ति/वर्ग किमी","text_en":"282 व्यक्ति/वर्ग किमी"}]', '1', '✅ **Correct Logic**: 2011 की जनगणना के अनुसार मध्य प्रदेश का जनसंख्या घनत्व 236 है, जो 2001 में 196 था।
💡 **Exam Fact**: भारत का जनसंख्या घनत्व 382 व्यक्ति प्रति वर्ग किमी है।
🧠 **Memory Tip**: 2-3-6 (दो का पहाड़ा: 2, 2x3=6).
🚫 **Scam Alert**: 196 पुराना डेटा (2001) है, इसे वर्तमान मानकर न चुनें।', 2, 0, 1, NULL, 'According to the 2011 Census, what is the population density of Madhya Pradesh?', '✅ **Correct Logic**: As per Census 2011, the population density of MP is 236 per sq km, up from 196 in 2001.
💡 **Exam Fact**: The national population density of India is 382 per sq km.
🧠 **Memory Tip**: 2-3-6 (Multiples of 2).
🚫 **Scam Alert**: 196 is the 2001 data; avoid selecting it for current context.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9e5916af-f399-4e52-95d1-90eb8793617a', 'ac84f7bc-37d7-4119-a9a1-07e0dc0b9a22', 'मध्य प्रदेश के किस जिले में ''न्यूनतम जनसंख्या घनत्व'' (Lowest Density) पाया जाता है?', '[{"id":"A","text":"डिंडोरी","text_en":"डिंडोरी"},{"id":"B","text":"श्योपुर","text_en":"श्योपुर"},{"id":"C","text":"पन्ना","text_en":"पन्ना"},{"id":"D","text":"बैतूल","text_en":"बैतूल"}]', '0', '✅ **Correct Logic**: डिंडोरी जिले का जनसंख्या घनत्व सबसे कम (94 व्यक्ति/वर्ग किमी) है।
💡 **Exam Fact**: सर्वाधिक घनत्व भोपाल (855) में पाया जाता है।
🧠 **Memory Tip**: D-D (Dindori - Desolate/Low density).
🚫 **Scam Alert**: श्योपुर दूसरा सबसे कम घनत्व वाला जिला है, पर प्रथम डिंडोरी है।', 2, 0, 2, NULL, 'In which district of MP is the ''Lowest Population Density'' found?', '✅ **Correct Logic**: Dindori has the lowest population density in the state at 94 persons per sq km.
💡 **Exam Fact**: The highest density is in Bhopal (855).
🧠 **Memory Tip**: D-D (Dindori - Desolate/Least dense).
🚫 **Scam Alert**: Sheopur is the second lowest, but Dindori is the absolute minimum.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b3044964-862f-4a8b-a643-4f9c28fea419', 'ac84f7bc-37d7-4119-a9a1-07e0dc0b9a22', 'वर्ष 2001-2011 के दौरान मध्य प्रदेश की ''दशकीय जनसंख्या वृद्धि दर'' (Decadal Growth Rate) कितनी रही?', '[{"id":"A","text":"20.35%","text_en":"20.35%"},{"id":"B","text":"17.7%","text_en":"17.7%"},{"id":"C","text":"24.3%","text_en":"24.3%"},{"id":"D","text":"15.6%","text_en":"15.6%"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश की दशकीय वृद्धि दर 20.35% रही।
💡 **Exam Fact**: इंदौर में सर्वाधिक वृद्धि दर (32.9%) दर्ज की गई थी।
🧠 **Memory Tip**: MP growth = 20 (Just a round figure to remember 20.35).
🚫 **Scam Alert**: 17.7% भारत की राष्ट्रीय वृद्धि दर है, मध्य प्रदेश की नहीं।', 2, 0, 3, NULL, 'What was the ''Decadal Population Growth Rate'' of MP during 2001-2011?', '✅ **Correct Logic**: The decadal growth rate of MP was 20.35%.
💡 **Exam Fact**: Indore district recorded the highest growth rate at 32.9%.
🧠 **Memory Tip**: MP growth is ''20-ish''.
🚫 **Scam Alert**: 17.7% is the national average for India; MP''s is higher.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5680fc03-9a4d-4c6b-9c66-e0643bc0f6e3', 'ac84f7bc-37d7-4119-a9a1-07e0dc0b9a22', 'मध्य प्रदेश के सर्वाधिक जनसंख्या वाले तीन जिले (घटते क्रम में) कौन से हैं?', '[{"id":"A","text":"इंदौर, जबलपुर, सागर","text_en":"इंदौर, जबलपुर, सागर"},{"id":"B","text":"इंदौर, भोपाल, जबलपुर","text_en":"इंदौर, भोपाल, जबलपुर"},{"id":"C","text":"जबलपुर, इंदौर, सागर","text_en":"जबलपुर, इंदौर, सागर"},{"id":"D","text":"भोपाल, इंदौर, ग्वालियर","text_en":"भोपाल, इंदौर, ग्वालियर"}]', '0', '✅ **Correct Logic**: 2011 के अनुसार सर्वाधिक जनसंख्या वाले जिले हैं: 1. इंदौर, 2. जबलपुर, 3. सागर।
💡 **Exam Fact**: न्यूनतम जनसंख्या वाला जिला 2011 के अनुसार ''हरदा'' था।
🧠 **Memory Tip**: I-J-S (Indore, Jabalpur, Sagar).
🚫 **Scam Alert**: भोपाल घनत्व में नंबर 1 है, लेकिन कुल जनसंख्या में इंदौर और जबलपुर के बाद आता है।', 2, 0, 4, NULL, 'Which are the three most populated districts of MP (in descending order)?', '✅ **Correct Logic**: The top three most populated districts are: 1. Indore, 2. Jabalpur, 3. Sagar.
💡 **Exam Fact**: According to 2011 data, Harda was the least populated district.
🧠 **Memory Tip**: I-J-S (Indore, Jabalpur, Sagar).
🚫 **Scam Alert**: Bhopal is #1 in density, but ranks lower in total population compared to Indore and Jabalpur.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('84ca5b94-11c3-488e-9702-28e49c74c783', 'ac84f7bc-37d7-4119-a9a1-07e0dc0b9a22', 'जनगणना 2011 के आंकड़ों और संबंधित जिलों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: बालाघाट (1021) में सर्वाधिक लिंगानुपात है। भिंड (837) में न्यूनतम। साक्षरता में जबलपुर (81.1%) शीर्ष पर है और अलीराजपुर (36.1%) सबसे नीचे।
💡 **Exam Fact**: अलीराजपुर न केवल मध्य प्रदेश बल्कि भारत का सबसे कम साक्षर जिला है।
🧠 **Memory Tip**: Literacy: J-A (Jabalpur to Alirajpur).
🚫 **Scam Alert**: इंदौर साक्षरता में दूसरे स्थान पर है, जबलपुर पहले पर।', 2, 0, 5, NULL, 'Match the 2011 Census data with the respective districts:', '✅ **Correct Logic**: Balaghat (1021) has the highest sex ratio. Bhind (837) has the lowest. Jabalpur (81.1%) leads in literacy, while Alirajpur (36.1%) is at the bottom.
💡 **Exam Fact**: Alirajpur is the least literate district in India, not just MP.
🧠 **Memory Tip**: Literacy flows from ''J'' to ''A''.
🚫 **Scam Alert**: Indore is #2 in literacy; Jabalpur is #1.', 60, 'matching', '[{"id":"(1)","label":"सर्वाधिक लिंगानुपात","match":"बालाघाट","matchId":"(a)"},{"id":"(2)","label":"न्यूनतम लिंगानुपात","match":"भिंड","matchId":"(b)"},{"id":"(3)","label":"सर्वाधिक साक्षरता","match":"जबलपुर","matchId":"(c)"},{"id":"(4)","label":"न्यूनतम साक्षरता","match":"अलीराजपुर","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e923e2b9-a3ac-4cdc-8dff-e6f40f2a5769', 'ac84f7bc-37d7-4119-a9a1-07e0dc0b9a22', 'मध्य प्रदेश में ''न्यूनतम दशकीय जनसंख्या वृद्धि दर'' वाला जिला कौन सा है?', '[{"id":"A","text":"अनूपपुर","text_en":"अनूपपुर"},{"id":"B","text":"बैतूल","text_en":"बैतूल"},{"id":"C","text":"छिंदवाड़ा","text_en":"छिंदवाड़ा"},{"id":"D","text":"मंदसौर","text_en":"मंदसौर"}]', '0', '✅ **Correct Logic**: अनूपपुर में सबसे कम वृद्धि दर (12.3%) दर्ज की गई थी।
💡 **Exam Fact**: इसके बाद बैतूल (12.9%) और छिंदवाड़ा (13.1%) का स्थान आता है।
🧠 **Memory Tip**: Anu (Anuppur) is the smallest grower.
🚫 **Scam Alert**: इंदौर में सर्वाधिक वृद्धि हुई थी, अनूपपुर में सबसे कम।', 2, 0, 6, NULL, 'Which district has the ''Minimum Decadal Population Growth Rate'' in MP?', '✅ **Correct Logic**: Anuppur recorded the lowest growth rate at 12.3%.
💡 **Exam Fact**: Betul (12.9%) and Chhindwara (13.1%) followed closely.
🧠 **Memory Tip**: ''A''nuppur stayed ''A''t the bottom of growth.
🚫 **Scam Alert**: Indore had the maximum growth; Anuppur had the least.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('02870fbb-e10b-4ad3-80dd-4f89d1c8a1af', 'ac84f7bc-37d7-4119-a9a1-07e0dc0b9a22', '2011 की जनगणना के अनुसार, मध्य प्रदेश की कुल जनसंख्या में ''अनुसूचित जनजाति'' (ST) का प्रतिशत कितना है?', '[{"id":"A","text":"21.1%","text_en":"21.1%"},{"id":"B","text":"15.6%","text_en":"15.6%"},{"id":"C","text":"17.5%","text_en":"17.5%"},{"id":"D","text":"12.6%","text_en":"12.6%"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश में ST का प्रतिशत 21.1% है।
💡 **Exam Fact**: अनुसूचित जाति (SC) का प्रतिशत 15.6% है।
🧠 **Memory Tip**: ST is more (21) than SC (15) in MP.
🚫 **Scam Alert**: 21.1% जनसंख्या में हिस्सा है, इसे विकास दर न समझें।', 2, 0, 7, NULL, 'According to the 2011 Census, what is the percentage of ''Scheduled Tribes'' (ST) in the total population of MP?', '✅ **Correct Logic**: Scheduled Tribes constitute 21.1% of the state''s total population.
💡 **Exam Fact**: Scheduled Castes (SC) make up 15.6% of the population.
🧠 **Memory Tip**: ST (21) > SC (15) in MP.
🚫 **Scam Alert**: 21.1% is the share in population, don''t confuse it with growth rates.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4155482e-36cb-4474-8e45-1459d909957f', 'ac84f7bc-37d7-4119-a9a1-07e0dc0b9a22', 'क्षेत्रफल के आधार पर मध्य प्रदेश का सबसे छोटा जिला (2011 की जनगणना के समय) कौन सा था?', '[{"id":"A","text":"दतिया","text_en":"दतिया"},{"id":"B","text":"हरदा","text_en":"हरदा"},{"id":"C","text":"भोपाल","text_en":"भोपाल"},{"id":"D","text":"निवाड़ी","text_en":"निवाड़ी"}]', '0', '✅ **Correct Logic**: 2011 की स्थिति में ''दतिया'' क्षेत्रफल में सबसे छोटा जिला था।
💡 **Exam Fact**: वर्तमान में (2026 की स्थिति में) ''निवाड़ी'' क्षेत्रफल और जनसंख्या दोनों में सबसे छोटा है।
🧠 **Memory Tip**: Old small: Datia; New small: Niwari.
🚫 **Scam Alert**: अगर प्रश्न में ''2011'' लिखा है, तो उत्तर दतिया ही होगा, भले ही आज निवाड़ी छोटा है।', 2, 0, 8, NULL, 'Which was the smallest district of MP by area (at the time of the 2011 Census)?', '✅ **Correct Logic**: As per the 2011 boundaries, Datia was the smallest district by area.
💡 **Exam Fact**: Currently (as of 2026), Niwari is the smallest by both area and population.
🧠 **Memory Tip**: Old small: Datia; New small: Niwari.
🚫 **Scam Alert**: If the question specifies ''2011 Census'', Datia is the correct answer despite Niwari''s current status.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8b96557b-94ad-41c6-a173-ed196485c5f4', 'ac84f7bc-37d7-4119-a9a1-07e0dc0b9a22', 'मध्य प्रदेश के किस संभाग (Division) में ''सर्वाधिक जनसंख्या'' निवास करती है?', '[{"id":"A","text":"इंदौर","text_en":"इंदौर"},{"id":"B","text":"जबलपुर","text_en":"जबलपुर"},{"id":"C","text":"भोपाल","text_en":"भोपाल"},{"id":"D","text":"ग्वालियर","text_en":"ग्वालियर"}]', '0', '✅ **Correct Logic**: इंदौर संभाग मध्य प्रदेश का सर्वाधिक जनसंख्या वाला संभाग है।
💡 **Exam Fact**: जबलपुर संभाग क्षेत्रफल (Area) में सबसे बड़ा संभाग है।
🧠 **Memory Tip**: Indore city is big, so is its division.
🚫 **Scam Alert**: क्षेत्रफल में जबलपुर बड़ा है, जनसंख्या में इंदौर।', 2, 0, 9, NULL, 'In which Division of MP does the ''Maximum Population'' reside?', '✅ **Correct Logic**: Indore Division is the most populous division in the state.
💡 **Exam Fact**: Jabalpur Division is the largest by area.
🧠 **Memory Tip**: Big city Indore = Big population division.
🚫 **Scam Alert**: Jabalpur is largest by area, while Indore is largest by population.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2bdf8bce-6459-4929-b97f-8815da166c2b', 'ac84f7bc-37d7-4119-a9a1-07e0dc0b9a22', 'मध्य प्रदेश के कितने जिलों का लिंगानुपात 1000 से अधिक है (2011 के अनुसार)?', '[{"id":"A","text":"4","text_en":"4"},{"id":"B","text":"5","text_en":"5"},{"id":"C","text":"6","text_en":"6"},{"id":"D","text":"3","text_en":"3"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश के 4 जिलों का लिंगानुपात 1000 से अधिक है: बालाघाट (1021), अलीराजपुर (1011), मंडला (1008) और डिंडोरी (1002)।
💡 **Exam Fact**: मध्य प्रदेश का औसत लिंगानुपात 931 है।
🧠 **Memory Tip**: B-A-M-D (Balaghat, Alirajpur, Mandla, Dindori).
🚫 **Scam Alert**: झाबुआ का लिंगानुपात 990 है, यह 1000 के बहुत पास है पर उसे पार नहीं करता।', 2, 0, 10, NULL, 'How many districts of MP have a sex ratio greater than 1000 (according to 2011 data)?', '✅ **Correct Logic**: Four districts exceed 1000: Balaghat (1021), Alirajpur (1011), Mandla (1008), and Dindori (1002).
💡 **Exam Fact**: The average sex ratio of MP is 931.
🧠 **Memory Tip**: B-A-M-D (Balaghat, Alirajpur, Mandla, Dindori).
🚫 **Scam Alert**: Jhabua (990) is close but doesn''t reach the 1000 mark.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cfb7d52c-fcce-4d11-b845-7a23b5cf51b8', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'भारत के राजचिह्न में अंकित शब्द ''सत्यमेव जयते'' किस उपनिषद से लिया गया है?', '[{"id":"A","text":"माण्डूक्य उपनिषद (Mandukya)","text_en":"माण्डूक्य उपनिषद (Mandukya)"},{"id":"B","text":"मुण्डक उपनिषद (Mundaka)","text_en":"मुण्डक उपनिषद (Mundaka)"},{"id":"C","text":"ईशोपनिषद (Ishopanishad)","text_en":"ईशोपनिषद (Ishopanishad)"},{"id":"D","text":"केनोपनिषद (Kenopanishad)","text_en":"केनोपनिषद (Kenopanishad)"}]', '1', '**✅ Correct Logic**: ''सत्यमेव जयते'' (सत्य की ही जीत होती है) मुण्डक उपनिषद से लिया गया है। यह अथर्ववेद से संबंधित है।

**💡 Exam Fact**: माण्डूक्य उपनिषद आकार में सबसे छोटा है, जबकि ''सत्यमेव जयते'' का स्रोत मुण्डक है। इन दोनों के नामों में अक्सर भ्रम होता है।

**🧠 Memory Tip**: **Mundaka** starts with ''Mun'' like **Mantra** (The national mantra).

**🚫 Scam Alert**: माण्डूक्य (Mandukya) गलत उत्तर है। ध्यान रहे कि मुण्डक (Mundaka) और माण्डूक्य दो अलग उपनिषद हैं।', 2, 0, 1, NULL, 'The words ''Satyameva Jayate'' inscribed on the State Emblem of India are taken from which Upanishad?', '**✅ Correct Logic**: ''Satyameva Jayate'' (Truth alone triumphs) is from the Mundaka Upanishad, which belongs to the Atharvaveda.

**💡 Exam Fact**: Mandukya is the shortest Upanishad, but Mundaka is the source of the national motto. They are often confused due to similar names.

**🧠 Memory Tip**: **Mun**daka = National **Mun**tra (Mantra).

**🚫 Scam Alert**: Mandukya is a distractor. Ensure you pick Mundaka for the motto.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('42b79dc8-67f8-4c56-a7e3-d391819f1094', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'यम और नचिकेता का प्रसिद्ध संवाद किस उपनिषद में वर्णित है?', '[{"id":"A","text":"बृहदारण्यक उपनिषद","text_en":"बृहदारण्यक उपनिषद"},{"id":"B","text":"कठोपनिषद (Kathopanishad)","text_en":"कठोपनिषद (Kathopanishad)"},{"id":"C","text":"छांदोग्य उपनिषद","text_en":"छांदोग्य उपनिषद"},{"id":"D","text":"तैत्तिरीय उपनिषद","text_en":"तैत्तिरीय उपनिषद"}]', '1', '**✅ Correct Logic**: कठोपनिषद में यमराज और बालक नचिकेता के बीच आत्मा और मृत्यु के रहस्य पर चर्चा है। इसमें ''श्रेय'' और ''प्रेय'' का अंतर समझाया गया है।

**💡 Exam Fact**: स्वामी विवेकानंद का प्रसिद्ध नारा ''उठो, जागो...'' इसी उपनिषद के एक श्लोक से प्रेरित है।

**🧠 Memory Tip**: **Katha** means story. The story of Nachiketa = **Katha**-upanishad.

**🚫 Scam Alert**: यह यजुर्वेद का हिस्सा है, इसे सामवेद से न जोड़ें।', 2, 0, 2, NULL, 'The famous dialogue between Yama and Nachiketa is described in which Upanishad?', '**✅ Correct Logic**: Kathopanishad features the dialogue between Lord Yama and the boy Nachiketa regarding the nature of the soul and death.

**💡 Exam Fact**: Swami Vivekananda''s ''Arise, Awake...'' quote is inspired by a verse from this Upanishad.

**🧠 Memory Tip**: **Katha** (Story) of Nachiketa = **Katha**-upanishad.

**🚫 Scam Alert**: It belongs to the Yajurveda; don''t misattribute it to the Samaveda.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e86c272d-7c0a-4daf-a65a-5fdfa3adcebb', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'पुनर्जन्म (Rebirth) के सिद्धांत का सर्वप्रथम स्पष्ट उल्लेख किस उपनिषद में मिलता है?', '[{"id":"A","text":"श्वेताश्वतर उपनिषद","text_en":"श्वेताश्वतर उपनिषद"},{"id":"B","text":"कौषीतकि उपनिषद","text_en":"कौषीतकि उपनिषद"},{"id":"C","text":"बृहदारण्यक उपनिषद (Brihadaranyaka)","text_en":"बृहदारण्यक उपनिषद (Brihadaranyaka)"},{"id":"D","text":"ईशोपनिषद","text_en":"ईशोपनिषद"}]', '2', '**✅ Correct Logic**: पुनर्जन्म का व्यवस्थित और स्पष्ट विवरण ''बृहदारण्यक उपनिषद'' में मिलता है। यह सबसे प्राचीन और विशाल उपनिषद भी है।

**💡 Exam Fact**: इसी उपनिषद में प्रसिद्ध मंत्र ''अस्तो मा सद्गमय'' और ''अहं ब्रह्मास्मि'' भी मिलता है।

**🧠 Memory Tip**: **B**rihad = **B**iggest & contains the cycle of **B**irth/Rebirth.

**🚫 Scam Alert**: छांदोग्य में भी इसके संकेत हैं, लेकिन ''बृहदारण्यक'' को प्राथमिकता दी जाती है।', 2, 0, 3, NULL, 'Which Upanishad provides the first clear mention of the doctrine of Rebirth?', '**✅ Correct Logic**: The systematic doctrine of Rebirth is found in the Brihadaranyaka Upanishad, the oldest and largest of all Upanishads.

**💡 Exam Fact**: It also contains the ''Asato Ma Sadgamaya'' and ''Aham Brahmasmi'' mantras.

**🧠 Memory Tip**: **B**rihad = **B**iggest, covering the **B**ig cycle of Rebirth.

**🚫 Scam Alert**: While Chandogya hints at it, Brihadaranyaka is the primary source for the elaborated doctrine.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f110244d-ab69-45ac-b671-4a0653cfe4a1', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'कथन (A): उपनिषदों को ''वेदांत'' कहा जाता है।
कारण (R): ये वैदिक साहित्य के अंतिम भाग हैं और वेदों के दार्शनिक निष्कर्ष प्रस्तुत करते हैं।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic**: उपनिषद वेदों के अंत (अंतिम भाग) में आते हैं, इसलिए इन्हें ''वेदांत'' (वेद + अंत) कहा जाता है। ये कर्मकांड के स्थान पर ज्ञान और दर्शन पर केंद्रित हैं।

**💡 Exam Fact**: मुख्य उपनिषदों की संख्या 11 या 13 मानी जाती है, जिन पर आदि शंकराचार्य ने भाष्य लिखा था।

**🧠 Memory Tip**: **Anta** means End. Veda-**Anta** = End of Vedas.

**🚫 Scam Alert**: वेदांग (Vedanga) और वेदांत (Vedanta) अलग हैं। वेदांग 6 हैं, वेदांत उपनिषद हैं।', 2, 0, 4, NULL, 'Assertion (A): Upanishads are called ''Vedanta''.
Reason (R): They are the final parts of Vedic literature and present the philosophical conclusions of the Vedas.
Select the correct option:', '**✅ Correct Logic**: Upanishads are called ''Vedanta'' because they appear at the end of the Vedas and represent the final peak of Vedic wisdom.

**💡 Exam Fact**: There are 11 to 13 principal Upanishads on which Adi Shankara wrote commentaries.

**🧠 Memory Tip**: **Anta** = End. Veda-**Anta** = The closing chapters of the Vedas.

**🚫 Scam Alert**: Don''t confuse Vedanga (6 limbs) with Vedanta (Upanishads).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7f6c1af5-ec23-4951-95f8-bb8df3e39173', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'उपनिषदों के प्रसिद्ध उद्धरणों को उनके स्रोत से सुमेलित करें (Match the quotes with their Upanishads):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Logic**: 
* **अहं ब्रह्मास्मि**: यजुर्वेद (बृहदारण्यक)।
* **तत्त्वमसि**: सामवेद (छांदोग्य)।
* **मातृ देवो भव**: यजुर्वेद (तैत्तिरीय)।
* **पूर्णमदः**: ईशोपनिषद की शांति पाठ।

**💡 Exam Fact**: छांदोग्य उपनिषद में ही पहली बार देवकी पुत्र कृष्ण का उल्लेख मिलता है।

**🧠 Memory Tip**: **Tat-Tvam-Asi** sounds like a song (Sama/Chandogya).

**🚫 Scam Alert**: ''अहं ब्रह्मास्मि'' और ''तत्त्वमसि'' में अक्सर छात्र अदला-बदली कर देते हैं, इन्हें ध्यान से रटें।', 2, 0, 5, NULL, 'Match the famous Upanishadic quotes with their sources:', '**✅ Correct Logic**: 
* **Aham Brahmasmi**: Brihadaranyaka.
* **Tat Tvam Asi**: Chandogya.
* **Matru Devo Bhava**: Taittiriya.
* **Purnamadah**: Ishopanishad.

**💡 Exam Fact**: Chandogya is the first text to mention Krishna as the son of Devaki.

**🧠 Memory Tip**: **Tat-Tvam-Asi** has a rhythmic flow like a chant/song (Samaveda style).

**🚫 Scam Alert**: Aham Brahmasmi and Tat Tvam Asi are the most likely pairs to be swapped in exams.', 60, 'matching', '[{"id":"(1)","label":"अहं ब्रह्मास्मि (I am Brahman)","match":"बृहदारण्यक उपनिषद","matchId":"(b)"},{"id":"(2)","label":"तत्त्वमसि (That Thou Art)","match":"छांदोग्य उपनिषद","matchId":"(a)"},{"id":"(3)","label":"मातृ देवो भव","match":"तैत्तिरीय उपनिषद","matchId":"(d)"},{"id":"(4)","label":"ओ३म् पूर्णमदः...","match":"ईशोपनिषद","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('72038a38-264d-4ef8-9d10-57996c19191c', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'किस उपनिषद में ''यज्ञ'' की तुलना ''टूटी हुई नाव'' से की गई है?', '[{"id":"A","text":"मुण्डक उपनिषद (Mundaka)","text_en":"मुण्डक उपनिषद (Mundaka)"},{"id":"B","text":"कठोपनिषद","text_en":"कठोपनिषद"},{"id":"C","text":"श्वेताश्वतर उपनिषद","text_en":"श्वेताश्वतर उपनिषद"},{"id":"D","text":"प्रश्न उपनिषद","text_en":"प्रश्न उपनिषद"}]', '0', '**✅ Correct Logic**: मुण्डक उपनिषद (1.2.7) में कहा गया है कि यज्ञ टूटी हुई नाव के समान हैं, जो भवसागर पार करने में सक्षम नहीं हैं। यह कर्मकांड पर ज्ञान की श्रेष्ठता दर्शाता है।

**💡 Exam Fact**: मुण्डक उपनिषद में ही ''अविद्या'' के नाश और ''ब्रह्म विद्या'' पर जोर दिया गया है।

**🧠 Memory Tip**: **Mundaka** sounds like **Munda** (Shaved head of a monk who rejects ritualism).

**🚫 Scam Alert**: मांडूक्य के साथ इसे फिर से कंफ्यूज न करें। नाव वाला तर्क मुण्डक का है।', 2, 0, 6, NULL, 'In which Upanishad is ''Sacrifice'' (Yajna) compared to a ''Broken Boat''?', '**✅ Correct Logic**: Mundaka Upanishad states that rituals are ''unsteady boats'' that cannot lead one across the ocean of existence. It prioritizes spiritual knowledge over physical rituals.

**💡 Exam Fact**: This text emphasizes ''Brahma Vidya'' as the supreme knowledge.

**🧠 Memory Tip**: Monks with **Munda** (shaved heads) often rejected empty rituals = **Mundaka**.

**🚫 Scam Alert**: Don''t confuse this with Mandukya; the ''boat'' analogy is strictly Mundaka.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6a5e7687-3fa7-443b-8699-6fcf19c4addb', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'चारों आश्रमों (ब्रह्मचर्य, गृहस्थ, वानप्रस्थ, संन्यास) का सर्वप्रथम उल्लेख किस उपनिषद में मिलता है?', '[{"id":"A","text":"छांदोग्य उपनिषद","text_en":"छांदोग्य उपनिषद"},{"id":"B","text":"जाबालोपनिषद (Jabalopanishad)","text_en":"जाबालोपनिषद (Jabalopanishad)"},{"id":"C","text":"बृहदारण्यक उपनिषद","text_en":"बृहदारण्यक उपनिषद"},{"id":"D","text":"कठोपनिषद","text_en":"कठोपनिषद"}]', '1', '**✅ Correct Logic**: जाबालोपनिषद में पहली बार चारों आश्रमों का एक साथ उल्लेख मिलता है।

**💡 Exam Fact**: छांदोग्य उपनिषद में केवल प्रथम तीन आश्रमों का ही उल्लेख है। चौथे आश्रम (संन्यास) का समावेश जाबालोपनिषद में हुआ।

**🧠 Memory Tip**: **Jaba**lo = **Jaba** (When) you have **ALL** four stages.

**🚫 Scam Alert**: यदि प्रश्न में ''तीन आश्रम'' पूछा जाए तो उत्तर ''छांदोग्य'' होगा, ''चार'' के लिए ''जाबालो''।', 2, 0, 7, NULL, 'In which Upanishad are all four Ashramas (Brahmacharya, Grihastha, Vanaprastha, Sannyasa) mentioned for the first time?', '**✅ Correct Logic**: Jabalopanishad provides the first comprehensive list of all four stages of life (Ashramas).

**💡 Exam Fact**: Chandogya Upanishad mentions only the first three; Sannyasa was added as the fourth in Jabalopanishad.

**🧠 Memory Tip**: **Jaba**lo = Join **ALL** four Ashramas.

**🚫 Scam Alert**: If the question asks for ''Three Ashramas'', pick Chandogya. For ''Four'', pick Jabalopanishad.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('47a738f6-efdc-4255-a7f1-3bf44af18097', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'किस उपनिषद में भगवान श्रीकृष्ण का उल्लेख ''घोर आंगिरस के शिष्य'' के रूप में हुआ है?', '[{"id":"A","text":"छांदोग्य उपनिषद (Chandogya)","text_en":"छांदोग्य उपनिषद (Chandogya)"},{"id":"B","text":"मुण्डक उपनिषद","text_en":"मुण्डक उपनिषद"},{"id":"C","text":"श्वेताश्वतर उपनिषद","text_en":"श्वेताश्वतर उपनिषद"},{"id":"D","text":"बृहदारण्यक उपनिषद","text_en":"बृहदारण्यक उपनिषद"}]', '0', '**✅ Correct Logic**: छांदोग्य उपनिषद में कृष्ण (देवकी पुत्र) को ऋषि घोर आंगिरस के शिष्य के रूप में वर्णित किया गया है। यह कृष्ण का प्राचीनतम ऐतिहासिक उल्लेख माना जाता है।

**💡 Exam Fact**: छांदोग्य उपनिषद सामवेद से संबंधित है।

**🧠 Memory Tip**: **C**handogya = **C**hild Krishna''s first mention.

**🚫 Scam Alert**: यह श्रीमद्भागवत का हिस्सा नहीं है, यह उससे बहुत प्राचीन उपनिषद का तथ्य है।', 2, 0, 8, NULL, 'In which Upanishad is Lord Krishna mentioned as a disciple of ''Ghora Angirasa''?', '**✅ Correct Logic**: Chandogya Upanishad identifies Krishna, the son of Devaki, as a student of Ghora Angirasa. This is considered the earliest literary reference to Krishna.

**💡 Exam Fact**: This Upanishad belongs to the Samaveda.

**🧠 Memory Tip**: **C**handogya = **C**onfirmation of Krishna''s early history.

**🚫 Scam Alert**: This is a Vedic fact, not to be confused with later Puranic literature like the Bhagavat Purana.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ddcdf62e-7b0e-41c4-a8ee-921f4ee0a2f1', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', '''अद्वैतवाद'' (Advaita) का दार्शनिक आधार मुख्य रूप से किन ग्रंथों को माना जाता है?', '[{"id":"A","text":"ब्राह्मण ग्रंथ","text_en":"ब्राह्मण ग्रंथ"},{"id":"B","text":"उपनिषद (Upanishads)","text_en":"उपनिषद (Upanishads)"},{"id":"C","text":"स्मृतियाँ","text_en":"स्मृतियाँ"},{"id":"D","text":"पुराण","text_en":"पुराण"}]', '1', '**✅ Correct Logic**: उपनिषद ''ब्रह्म'' और ''आत्मा'' की एकता पर बल देते हैं, जो शंकराचार्य के अद्वैतवाद का मूल आधार है। इसलिए इन्हें ''ज्ञान कांड'' कहा जाता है।

**💡 Exam Fact**: उपनिषदों को ''परा विद्या'' (आध्यात्मिक ज्ञान) की श्रेणी में रखा गया है।

**🧠 Memory Tip**: **U**panishad = **U**niverse and Soul are one.

**🚫 Scam Alert**: ब्राह्मण ग्रंथ ''कर्म कांड'' (Rituals) के आधार हैं, ''ज्ञान कांड'' (Philosophy) के नहीं।', 2, 0, 9, NULL, 'Which texts are primarily considered the philosophical basis of ''Advaita''?', '**✅ Correct Logic**: Upanishads emphasize the oneness of Brahman and Atman, forming the bedrock of Advaita philosophy. They represent the ''Jnana Kanda'' (Path of Knowledge).

**💡 Exam Fact**: They are categorized as ''Para Vidya'' or supreme spiritual science.

**🧠 Memory Tip**: **U**panishad = **U**ltimate Unity of soul and god.

**🚫 Scam Alert**: Brahmanas deal with ''Karma Kanda'' (Rituals), whereas Upanishads deal with ''Jnana Kanda'' (Knowledge).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6cedc090-0711-4855-8952-0b952333b59c', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'विदेही राजा जनक की सभा में याज्ञवल्क्य और गार्गी का प्रसिद्ध संवाद किस उपनिषद में मिलता है?', '[{"id":"A","text":"छांदोग्य उपनिषद","text_en":"छांदोग्य उपनिषद"},{"id":"B","text":"बृहदारण्यक उपनिषद (Brihadaranyaka)","text_en":"बृहदारण्यक उपनिषद (Brihadaranyaka)"},{"id":"C","text":"मुण्डक उपनिषद","text_en":"मुण्डक उपनिषद"},{"id":"D","text":"केनोपनिषद","text_en":"केनोपनिषद"}]', '1', '**✅ Correct Logic**: बृहदारण्यक उपनिषद में विदुषी गार्गी और ऋषि याज्ञवल्क्य के बीच गहन दार्शनिक संवाद वर्णित है। यह प्राचीन काल में महिलाओं की उच्च शिक्षा का प्रमाण है।

**💡 Exam Fact**: इसी उपनिषद में याज्ञवल्क्य और उनकी पत्नी मैत्रेयी का संवाद भी है।

**🧠 Memory Tip**: A **BIG** debate in the **BIG** (Brihad) Upanishad.

**🚫 Scam Alert**: गार्गी संहिता अलग ग्रंथ है, संवाद बृहदारण्यक उपनिषद में है।', 2, 0, 10, NULL, 'The famous debate between Yajnavalkya and Gargi in the court of King Janaka is found in which Upanishad?', '**✅ Correct Logic**: Brihadaranyaka Upanishad records the intellectual debate between the female scholar Gargi and Sage Yajnavalkya, proving high status of women scholars in ancient times.

**💡 Exam Fact**: It also contains the famous dialogue between Yajnavalkya and his wife Maitreyi.

**🧠 Memory Tip**: A **BIG** debate happened in the **BIG** (**Brihad**) Upanishad.

**🚫 Scam Alert**: Gargi Samhita is a different text; this specific dialogue is a core part of Brihadaranyaka.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1d713014-ec5b-49cb-a319-31efc324b36f', '65a17407-6a4a-41c3-a551-7ff11922b527', '2011 की जनगणना के अनुसार, मध्य प्रदेश की कुल जनसंख्या का कितना प्रतिशत शहरी (Urban) क्षेत्रों में निवास करता है?', '[{"id":"A","text":"27.6%","text_en":"27.6%"},{"id":"B","text":"31.1%","text_en":"31.1%"},{"id":"C","text":"24.5%","text_en":"24.5%"},{"id":"D","text":"21.1%","text_en":"21.1%"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश की 27.6% जनसंख्या शहरों में रहती है, जबकि 72.4% ग्रामीण है।
💡 **Exam Fact**: भारत की नगरीय जनसंख्या का प्रतिशत 31.1% है।
🧠 **Memory Tip**: 27.6 - ''सत्ताइस'' (Sattis) sounds like ''City''.
🚫 **Scam Alert**: 31.1% राष्ट्रीय औसत है, मध्य प्रदेश का प्रतिशत उससे कम है।', 2, 0, 1, NULL, 'According to the 2011 Census, what percentage of the total population of MP resides in urban areas?', '✅ **Correct Logic**: 27.6% of MP''s population is urban, while 72.4% is rural.
💡 **Exam Fact**: India''s national urban population percentage is 31.1%.
🧠 **Memory Tip**: 27 is the number for MP cities.
🚫 **Scam Alert**: 31.1% is the national average; MP''s urbanization is lower than the country''s average.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6b6a7fc6-56e7-44ee-bfec-c2c62f7a5c9c', '65a17407-6a4a-41c3-a551-7ff11922b527', 'मध्य प्रदेश का ''सर्वाधिक नगरीकृत'' (Most Urbanized) जिला कौन सा है (प्रतिशत के आधार पर)?', '[{"id":"A","text":"भोपाल","text_en":"भोपाल"},{"id":"B","text":"इंदौर","text_en":"इंदौर"},{"id":"C","text":"ग्वालियर","text_en":"ग्वालियर"},{"id":"D","text":"जबलपुर","text_en":"जबलपुर"}]', '0', '✅ **Correct Logic**: भोपाल जिला प्रतिशत के आधार पर सर्वाधिक नगरीकृत है (80.9%)।
💡 **Exam Fact**: इंदौर दूसरे स्थान पर (74.1%) आता है।
🧠 **Memory Tip**: Capital Bhopal is mostly City (80%+).
🚫 **Scam Alert**: इंदौर में शहरी आबादी संख्या में अधिक हो सकती है, लेकिन ''प्रतिशत'' में भोपाल शीर्ष पर है।', 2, 0, 2, NULL, 'Which is the ''Most Urbanized'' district of MP (on the basis of percentage)?', '✅ **Correct Logic**: Bhopal is the most urbanized district by percentage (80.9%).
💡 **Exam Fact**: Indore ranks second with 74.1%.
🧠 **Memory Tip**: The capital is the most urban ''percent-wise''.
🚫 **Scam Alert**: While Indore might have more urban people in raw numbers, Bhopal wins in the percentage ratio.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3bdfc085-e146-4d5e-b753-9bcc9f25d16f', '65a17407-6a4a-41c3-a551-7ff11922b527', 'मध्य प्रदेश में ''न्यूनतम नगरीकरण प्रतिशत'' वाला जिला कौन सा है?', '[{"id":"A","text":"डिंडोरी","text_en":"डिंडोरी"},{"id":"B","text":"अलीराजपुर","text_en":"अलीराजपुर"},{"id":"C","text":"झाबुआ","text_en":"झाबुआ"},{"id":"D","text":"सीधी","text_en":"सीधी"}]', '0', '✅ **Correct Logic**: डिंडोरी में नगरीकरण का प्रतिशत सबसे कम (मात्र 4.6%) है।
💡 **Exam Fact**: इसका अर्थ है कि यहाँ 95.4% आबादी गाँवों में रहती है।
🧠 **Memory Tip**: Dindori is the most ''Desi/Rural'' district.
🚫 **Scam Alert**: अलीराजपुर और झाबुआ भी कम नगरीकृत हैं, लेकिन रिकॉर्ड डिंडोरी के नाम है।', 2, 0, 3, NULL, 'Which district has the ''Minimum Urbanization Percentage'' in MP?', '✅ **Correct Logic**: Dindori has the lowest urbanization at only 4.6%.
💡 **Exam Fact**: This means 95.4% of its population is rural.
🧠 **Memory Tip**: Dindori = Dehat (Village) leader.
🚫 **Scam Alert**: Alirajpur and Jhabua are also low, but Dindori is the absolute lowest.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('07134bc9-f8cd-46a8-9408-9ecd8411587b', '65a17407-6a4a-41c3-a551-7ff11922b527', 'नगर निगम (Municipal Corporation) बनने के लिए शहर की न्यूनतम जनसंख्या कितनी होनी चाहिए?', '[{"id":"A","text":"1 लाख से अधिक","text_en":"1 लाख से अधिक"},{"id":"B","text":"5 लाख से अधिक","text_en":"5 लाख से अधिक"},{"id":"C","text":"10 लाख से अधिक","text_en":"10 लाख से अधिक"},{"id":"D","text":"50 हजार से अधिक","text_en":"50 हजार से अधिक"}]', '0', '✅ **Correct Logic**: सामान्यतः 1 लाख से अधिक जनसंख्या वाले बड़े नगरीय क्षेत्रों को नगर निगम घोषित किया जाता है।
💡 **Exam Fact**: मध्य प्रदेश का पहला नगर निगम जबलपुर (1864) था।
🧠 **Memory Tip**: 1 Lakh = 1 Nigam.
🚫 **Scam Alert**: नगर पालिका के लिए 20,000 से 1 लाख के बीच की सीमा होती है।', 2, 0, 4, NULL, 'What should be the minimum population of a city to become a Municipal Corporation in MP?', '✅ **Correct Logic**: Generally, urban areas with a population exceeding 1 lakh are designated as Municipal Corporations.
💡 **Exam Fact**: Jabalpur was the first Municipal Corporation in MP (1864).
🧠 **Memory Tip**: 1 Lakh = 1st level of big city governance.
🚫 **Scam Alert**: Municipalities (Nagar Palika) range from 20k to 1 lakh.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3eaf1a98-9de5-407d-ba42-32ad8ef6ae63', '65a17407-6a4a-41c3-a551-7ff11922b527', 'नगरीय निकायों और उनसे संबंधित तथ्यों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: जबलपुर पहला निगम (1864), दतिया पहली पालिका (1907)। इंदौर में शहरी लोग सबसे ज्यादा हैं, भोपाल प्रतिशत में सबसे ज्यादा शहरी है।
💡 **Exam Fact**: वर्तमान में मध्य प्रदेश में 17 नगर निगम हैं (भिंड प्रस्तावित)।
🧠 **Memory Tip**: J-N (Jabalpur Nigam), D-P (Datia Palika).
🚫 **Scam Alert**: ग्वालियर पुराना नगर निगम है पर पहला जबलपुर ही है।', 2, 0, 5, NULL, 'Match the urban bodies with their related facts:', '✅ **Correct Logic**: Jabalpur first Corp (1864), Datia first Municipality (1907). Indore has the highest urban count, Bhopal the highest urban ratio.
💡 **Exam Fact**: There are currently 17 Municipal Corporations in MP (Bhind is proposed).
🧠 **Memory Tip**: J-N (Jabalpur Nigam), D-P (Datia Palika).
🚫 **Scam Alert**: Gwalior is an old corporation, but Jabalpur remains the first.', 60, 'matching', '[{"id":"(1)","label":"प्रथम नगर निगम","match":"जबलपुर","matchId":"(a)"},{"id":"(2)","label":"प्रथम नगर पालिका","match":"दतिया","matchId":"(b)"},{"id":"(3)","label":"सर्वाधिक नगरीय जनसंख्या (संख्या)","match":"इंदौर","matchId":"(c)"},{"id":"(4)","label":"सर्वाधिक नगरीय जनसंख्या (%)","match":"भोपाल","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('422d3468-9fac-48e5-a264-9ee5c0b0c532', '65a17407-6a4a-41c3-a551-7ff11922b527', 'मध्य प्रदेश के किस संभाग में ''नगरीकरण का प्रतिशत'' सर्वाधिक है?', '[{"id":"A","text":"इंदौर","text_en":"इंदौर"},{"id":"B","text":"भोपाल","text_en":"भोपाल"},{"id":"C","text":"जबलपुर","text_en":"जबलपुर"},{"id":"D","text":"उज्जैन","text_en":"उज्जैन"}]', '1', '✅ **Correct Logic**: भोपाल संभाग (Division) में नगरीकरण का प्रतिशत सबसे अधिक है क्योंकि इसमें राजधानी और विकसित औद्योगिक क्षेत्र शामिल हैं।
💡 **Exam Fact**: जनसंख्या की दृष्टि से इंदौर संभाग सबसे बड़ा है।
🧠 **Memory Tip**: Capital division = Most urban.
🚫 **Scam Alert**: संभाग और जिले में कभी-कभी अंतर हो सकता है, पर यहाँ भोपाल दोनों में शीर्ष पर है।', 2, 0, 6, NULL, 'Which Division of MP has the highest ''Percentage of Urbanization''?', '✅ **Correct Logic**: Bhopal Division has the highest urbanization percentage due to the presence of the capital and industrial belts.
💡 **Exam Fact**: Indore Division is the largest by population count.
🧠 **Memory Tip**: Capital division = Maximum urban facilities.
🚫 **Scam Alert**: Always distinguish between District and Division rankings, though Bhopal leads both here.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('de8b7e39-6c43-4b02-8471-0e3f4a77fb08', '65a17407-6a4a-41c3-a551-7ff11922b527', '2001 से 2011 के बीच मध्य प्रदेश की ''नगरीय जनसंख्या वृद्धि दर'' कितनी रही?', '[{"id":"A","text":"25.7%","text_en":"25.7%"},{"id":"B","text":"20.3%","text_en":"20.3%"},{"id":"C","text":"18.4%","text_en":"18.4%"},{"id":"D","text":"12.5%","text_en":"12.5%"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश में नगरीय जनसंख्या की वृद्धि दर 25.7% रही, जो ग्रामीण वृद्धि दर (18.4%) से अधिक है।
💡 **Exam Fact**: यह इंगित करता है कि लोग रोजगार के लिए गाँवों से शहरों की ओर पलायन कर रहे हैं।
🧠 **Memory Tip**: Urban growth is ''25'' (Quarter of a hundred).
🚫 **Scam Alert**: 20.3% कुल जनसंख्या वृद्धि दर है, नगरीय वृद्धि दर 25.7% है।', 2, 0, 7, NULL, 'What was the ''Urban Population Growth Rate'' of MP between 2001 and 2011?', '✅ **Correct Logic**: The urban growth rate in MP was 25.7%, significantly higher than the rural growth rate (18.4%).
💡 **Exam Fact**: This indicates a strong trend of rural-to-urban migration for employment.
🧠 **Memory Tip**: Urban growth = 25% (A quarter).
🚫 **Scam Alert**: 20.3% is the total growth rate; don''t confuse it with specific urban growth.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('aaf54f79-8b44-487f-a69b-8b85c5c47cd5', '65a17407-6a4a-41c3-a551-7ff11922b527', 'मध्य प्रदेश के कितने शहरों को ''स्मार्ट सिटी मिशन'' (Smart City Mission) के तहत चुना गया है?', '[{"id":"A","text":"5","text_en":"5"},{"id":"B","text":"7","text_en":"7"},{"id":"C","text":"10","text_en":"10"},{"id":"D","text":"12","text_en":"12"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश के 7 शहरों को स्मार्ट सिटी मिशन में शामिल किया गया है: इंदौर, भोपाल, जबलपुर, ग्वालियर, उज्जैन, सागर और सतना।
💡 **Exam Fact**: इंदौर और भोपाल को अक्सर रैंकिंग में शीर्ष स्थान प्राप्त होता है।
🧠 **Memory Tip**: Rainbow of 7 cities.
🚫 **Scam Alert**: केवल बड़े 4 महानगर नहीं, बल्कि सागर, उज्जैन और सतना भी इसमें शामिल हैं।', 2, 0, 8, NULL, 'How many cities of MP have been selected under the ''Smart City Mission''?', '✅ **Correct Logic**: 7 cities of MP are in the Smart City Mission: Indore, Bhopal, Jabalpur, Gwalior, Ujjain, Sagar, and Satna.
💡 **Exam Fact**: Indore and Bhopal frequently top the national performance charts.
🧠 **Memory Tip**: 7 Wonders = 7 Smart Cities of MP.
🚫 **Scam Alert**: It''s not just the big 4; Sagar, Ujjain, and Satna are also included.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c76c368f-1101-43f7-96a6-8297f7bf6ae8', '65a17407-6a4a-41c3-a551-7ff11922b527', 'मध्य प्रदेश में ''नगर पालिकाओं'' (Nagar Palikas) की कुल संख्या वर्तमान में लगभग कितनी है?', '[{"id":"A","text":"98","text_en":"98"},{"id":"B","text":"16","text_en":"16"},{"id":"C","text":"298","text_en":"298"},{"id":"D","text":"50","text_en":"50"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश में वर्तमान में लगभग 98-100 नगर पालिकाएं हैं (संख्या अपडेट होती रहती है, पर 2011/मानक आंकड़ों के अनुसार 98 थी)।
💡 **Exam Fact**: सबसे छोटी नगरीय इकाई ''नगर परिषद'' (Nagar Parishad) होती है।
🧠 **Memory Tip**: Close to a Century (98).
🚫 **Scam Alert**: 298 नगर परिषदों की संख्या है, पालिकाओं की नहीं।', 2, 0, 9, NULL, 'What is the approximate total number of ''Nagar Palikas'' in MP currently?', '✅ **Correct Logic**: There are approximately 98 Municipalities (Nagar Palikas) in MP based on standard administrative data.
💡 **Exam Fact**: The smallest urban local body is the ''Nagar Parishad''.
🧠 **Memory Tip**: Municipalities are close to a century in number.
🚫 **Scam Alert**: 298 is the count for Nagar Parishads, much higher than Nagar Palikas.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('19a59764-fe55-42fb-9295-730f08562f6f', '65a17407-6a4a-41c3-a551-7ff11922b527', 'नगरीकरण के प्रभाव के रूप में ''महानगरीय क्षेत्रों'' (Metropolitan areas) का विकास हो रहा है। मध्य प्रदेश में वर्तमान में कितने शहरों की जनसंख्या 10 लाख से अधिक (Million-plus) है?', '[{"id":"A","text":"4","text_en":"4"},{"id":"B","text":"2","text_en":"2"},{"id":"C","text":"6","text_en":"6"},{"id":"D","text":"1","text_en":"1"}]', '0', '✅ **Correct Logic**: 2011 की जनगणना के अनुसार मध्य प्रदेश के 4 शहरों की आबादी 10 लाख से अधिक है: इंदौर, भोपाल, जबलपुर और ग्वालियर।
💡 **Exam Fact**: इंदौर राज्य का सबसे बड़ा महानगर (Metropolis) है।
🧠 **Memory Tip**: Big Four (I-B-J-G).
🚫 **Scam Alert**: उज्जैन नगर निगम है पर उसकी आबादी 2011 में 10 लाख से कम थी।', 2, 0, 10, NULL, 'As an effect of urbanization, metropolitan areas are growing. How many cities in MP currently have a population of more than 10 lakhs (Million-plus)?', '✅ **Correct Logic**: According to the 2011 census, 4 cities in MP have a population over 1 million: Indore, Bhopal, Jabalpur, and Gwalior.
💡 **Exam Fact**: Indore is the largest metropolis in the state.
🧠 **Memory Tip**: The ''Big Four'' metros of MP.
🚫 **Scam Alert**: Ujjain is a major city but its 2011 population was below the 10-lakh mark.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('340ffba9-e48b-4455-8f5e-c7de31bd5bbc', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा के संबंध में निम्नलिखित में से कौन सा कथन ''गलत'' है?', '[{"id":"A","text":"संविधान सभा का गठन कैबिनेट मिशन योजना के तहत किया गया था।","text_en":"संविधान सभा का गठन कैबिनेट मिशन योजना के तहत किया गया था।"},{"id":"B","text":"संविधान सभा के सदस्यों का चुनाव प्रत्यक्ष रूप से जनता द्वारा किया गया था।","text_en":"संविधान सभा के सदस्यों का चुनाव प्रत्यक्ष रूप से जनता द्वारा किया गया था।"},{"id":"C","text":"संविधान सभा की पहली बैठक 9 दिसंबर 1946 को हुई थी।","text_en":"संविधान सभा की पहली बैठक 9 दिसंबर 1946 को हुई थी।"},{"id":"D","text":"डॉ. सच्चिदानंद सिन्हा इसके अस्थायी अध्यक्ष थे।","text_en":"डॉ. सच्चिदानंद सिन्हा इसके अस्थायी अध्यक्ष थे।"}]', '1', '✅ **Correct Logic**: संविधान सभा के सदस्यों का चुनाव अप्रत्यक्ष रूप से प्रांतीय विधानसभाओं के सदस्यों द्वारा किया गया था, न कि प्रत्यक्ष रूप से जनता द्वारा।
💡 **Exam Fact**: 1946 की चुनाव प्रक्रिया ''सीमित मताधिकार'' पर आधारित थी।
🧠 **Memory Tip**: I-P (Indirect-Provincial Assembly).
🚫 **Scam Alert**: ''प्रत्यक्ष'' (Direct) और ''अप्रत्यक्ष'' (Indirect) के बीच के अंतर को ध्यान से देखें।', 2, 0, 1, NULL, 'Which of the following statements regarding the Constituent Assembly is ''incorrect''?', '✅ **Correct Logic**: Members of the Constituent Assembly were elected indirectly by the members of the Provincial Legislative Assemblies, not directly by the people.
💡 **Exam Fact**: The 1946 election process was based on ''limited franchise''.
🧠 **Memory Tip**: I-P (Indirect-Provincial Assembly).
🚫 **Scam Alert**: Pay close attention to the difference between ''Direct'' and ''Indirect'' elections.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2e7a029c-00fa-4de4-ba3b-7a5cd4f6f8e3', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा में ''उद्देश्य प्रस्ताव'' (Objective Resolution) किसके द्वारा और कब प्रस्तुत किया गया था?', '[{"id":"A","text":"डॉ. बी.आर. अंबेडकर; 13 दिसंबर 1946","text_en":"डॉ. बी.आर. अंबेडकर; 13 दिसंबर 1946"},{"id":"B","text":"जवाहरलाल नेहरू; 13 दिसंबर 1946","text_en":"जवाहरलाल नेहरू; 13 दिसंबर 1946"},{"id":"C","text":"सरदार पटेल; 22 जनवरी 1947","text_en":"सरदार पटेल; 22 जनवरी 1947"},{"id":"D","text":"बी.एन. राव; 11 दिसंबर 1946","text_en":"बी.एन. राव; 11 दिसंबर 1946"}]', '1', '✅ **Correct Logic**: जवाहरलाल नेहरू ने 13 दिसंबर 1946 को ऐतिहासिक ''उद्देश्य प्रस्ताव'' पेश किया था, जो बाद में संविधान की प्रस्तावना बना।
💡 **Exam Fact**: इस प्रस्ताव को 22 जनवरी 1947 को सर्वसम्मति से स्वीकार किया गया था।
🧠 **Memory Tip**: J-13 (Jawaharlal-13th).
🚫 **Scam Alert**: अंबेडकर प्रारूप समिति के अध्यक्ष थे, लेकिन उद्देश्य प्रस्ताव नेहरू ने पेश किया था।', 2, 0, 2, NULL, 'By whom and when was the ''Objective Resolution'' presented in the Constituent Assembly?', '✅ **Correct Logic**: Jawaharlal Nehru moved the historic ''Objective Resolution'' on December 13, 1946, which later became the Preamble of the Constitution.
💡 **Exam Fact**: It was unanimously adopted by the Assembly on January 22, 1947.
🧠 **Memory Tip**: J-13 (Jawaharlal-13th).
🚫 **Scam Alert**: While Ambedkar was the Chairman of the Drafting Committee, the Objective Resolution was Nehru''s contribution.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('53258440-c4cf-45e7-a35c-f1643dca1b67', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा की ''प्रारूप समिति'' (Drafting Committee) में अध्यक्ष के अलावा कितने सदस्य थे?', '[{"id":"A","text":"7","text_en":"7"},{"id":"B","text":"6","text_en":"6"},{"id":"C","text":"5","text_en":"5"},{"id":"D","text":"8","text_en":"8"}]', '1', '✅ **Correct Logic**: प्रारूप समिति में कुल 7 सदस्य थे (1 अध्यक्ष + 6 अन्य सदस्य)।
💡 **Exam Fact**: इस समिति का गठन 29 अगस्त 1947 को हुआ था।
🧠 **Memory Tip**: 1+6=7 (Total 7).
🚫 **Scam Alert**: प्रश्न में ''अध्यक्ष के अलावा'' पूछा गया है, इसलिए उत्तर 6 होगा, न कि 7।', 2, 0, 3, NULL, 'How many members were there in the ''Drafting Committee'' of the Constituent Assembly, excluding the Chairman?', '✅ **Correct Logic**: There were 7 members in total in the Drafting Committee (1 Chairman + 6 other members).
💡 **Exam Fact**: The committee was set up on August 29, 1947.
🧠 **Memory Tip**: 1+6=7 (Total 7).
🚫 **Scam Alert**: The question asks ''excluding the Chairman'', so the answer is 6, not 7.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d8e82424-97f2-411f-b0f0-81bc70017e30', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा के संबंध में निम्नलिखित कथनों पर विचार करें:
1. बी.एन. राव संविधान सभा के संवैधानिक सलाहकार थे।
2. डॉ. राजेंद्र प्रसाद को 11 दिसंबर 1946 को स्थायी अध्यक्ष चुना गया।
3. एच.सी. मुखर्जी संविधान सभा के उपाध्यक्ष थे।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '2', '✅ **Correct Logic**: तीनों कथन सत्य हैं। बी.एन. राव ने संविधान का प्रारंभिक मसौदा तैयार किया था।
💡 **Exam Fact**: संविधान सभा के दो उपाध्यक्ष थे—एच.सी. मुखर्जी और वी.टी. कृष्णमाचारी।
🧠 **Memory Tip**: R-P (Rau-Prasad-Principal figures).
🚫 **Scam Alert**: भ्रमित न हों, राव सलाहकार थे जबकि अंबेडकर प्रारूप समिति के अध्यक्ष।', 2, 0, 4, NULL, 'Consider the following statements regarding the Constituent Assembly:
1. B.N. Rau was the Constitutional Advisor to the Assembly.
2. Dr. Rajendra Prasad was elected permanent President on Dec 11, 1946.
3. H.C. Mukherjee was the Vice-President of the Assembly.

Choose the correct statement:', '✅ **Correct Logic**: All three statements are true. B.N. Rau prepared the initial draft of the Constitution.
💡 **Exam Fact**: The assembly had two Vice-Presidents—H.C. Mukherjee and V.T. Krishnamachari.
🧠 **Memory Tip**: R-P (Rau-Prasad-Principal figures).
🚫 **Scam Alert**: Don''t confuse Rau (Advisor) with Ambedkar (Drafting Committee Chairman).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('865b1a6f-11cf-4db7-af79-44bc8dc1e123', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा की समितियों और उनके अध्यक्षों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: केंद्र/संघ संबंधी समितियां नेहरू के पास थीं। राज्यों/प्रांतों का काम पटेल के पास था। सभा की अध्यक्षता प्रसाद के पास थी।
💡 **Exam Fact**: झंडा समिति (तदर्थ) के अध्यक्ष भी डॉ. राजेंद्र प्रसाद थे।
🧠 **Memory Tip**: Union-Nehru, Province-Patel.
🚫 **Scam Alert**: ''संचालन समिति'' (Steering) राजेंद्र प्रसाद की थी, जबकि ''कार्य संचालन'' (Order of Business) मुंशी की।', 2, 0, 5, NULL, 'Match the committees of the Constituent Assembly and their Chairmen:', '✅ **Correct Logic**: Union/Federal committees were under Nehru. Provincial matters were handled by Patel. Assembly management was by Prasad.
💡 **Exam Fact**: Dr. Rajendra Prasad was also the Chairman of the Ad-hoc Committee on the National Flag.
🧠 **Memory Tip**: Union-Nehru, Province-Patel.
🚫 **Scam Alert**: ''Steering Committee'' was Prasad''s, while ''Order of Business'' was Munshi''s.', 60, 'matching', '[{"id":"(1)","label":"संघ शक्ति समिति","match":"जवाहरलाल नेहरू","matchId":"(a)"},{"id":"(2)","label":"प्रांतीय संविधान समिति","match":"सरदार पटेल","matchId":"(b)"},{"id":"(3)","label":"संचालन समिति","match":"डॉ. राजेंद्र प्रसाद","matchId":"(c)"},{"id":"(4)","label":"कार्य संचालन समिति","match":"के.एम. मुंशी","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5d510a6d-0621-4fef-a12d-4e922a02141b', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा द्वारा राष्ट्रीय ध्वज (National Flag) को कब अपनाया गया था?', '[{"id":"A","text":"22 जुलाई 1947","text_en":"22 जुलाई 1947"},{"id":"B","text":"24 जनवरी 1950","text_en":"24 जनवरी 1950"},{"id":"C","text":"15 अगस्त 1947","text_en":"15 अगस्त 1947"},{"id":"D","text":"26 जनवरी 1950","text_en":"26 जनवरी 1950"}]', '0', '✅ **Correct Logic**: राष्ट्रीय ध्वज को स्वतंत्रता से ठीक पहले 22 जुलाई 1947 को अपनाया गया था।
💡 **Exam Fact**: पिंगली वेंकैया ने वर्तमान राष्ट्रीय ध्वज का डिजाइन तैयार किया था।
🧠 **Memory Tip**: Flag first, Freedom next (July comes before August).
🚫 **Scam Alert**: 24 जनवरी 1950 को राष्ट्रगान और राष्ट्रगीत अपनाए गए थे।', 2, 0, 6, NULL, 'When was the National Flag adopted by the Constituent Assembly?', '✅ **Correct Logic**: The National Flag was adopted just before independence on July 22, 1947.
💡 **Exam Fact**: Pingali Venkayya designed the current National Flag.
🧠 **Memory Tip**: Flag first, Freedom next (July comes before August).
🚫 **Scam Alert**: National Anthem and National Song were adopted on Jan 24, 1950.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('05573328-3114-430f-a05e-d1f2d1614635', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा में रियासतों (Princely States) को कुल कितनी सीटें आवंटित की गई थीं?', '[{"id":"A","text":"292","text_en":"292"},{"id":"B","text":"93","text_en":"93"},{"id":"C","text":"73","text_en":"73"},{"id":"D","text":"4","text_en":"4"}]', '1', '✅ **Correct Logic**: कुल 389 सीटों में से 93 सीटें रियासतों के लिए आरक्षित थीं।
💡 **Exam Fact**: 292 सीटें ब्रिटिश भारत के प्रांतों से थीं और 4 मुख्य आयुक्त प्रांतों से।
🧠 **Memory Tip**: 93 Princely (Smallest chunk of the main two).
🚫 **Scam Alert**: 73 सीटें मुस्लिम लीग ने जीती थीं, यह आवंटन नहीं था।', 2, 0, 7, NULL, 'How many seats were total allocated to the Princely States in the Constituent Assembly?', '✅ **Correct Logic**: Out of a total of 389 seats, 93 seats were reserved for Princely States.
💡 **Exam Fact**: 292 were from British Provinces and 4 from Chief Commissioner''s Provinces.
🧠 **Memory Tip**: 93 Princely (Smallest chunk of the main two).
🚫 **Scam Alert**: 73 seats were won by the Muslim League; it wasn''t the allocation.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d9613fcf-0b94-46b5-a56f-21e02e12f029', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'भारत के संविधान को संविधान सभा द्वारा किस तिथि को ''अंगीकृत, अधिनियमित और आत्मार्पित'' किया गया था?', '[{"id":"A","text":"26 जनवरी 1950","text_en":"26 जनवरी 1950"},{"id":"B","text":"26 नवंबर 1949","text_en":"26 नवंबर 1949"},{"id":"C","text":"15 अगस्त 1947","text_en":"15 अगस्त 1947"},{"id":"D","text":"9 दिसंबर 1946","text_en":"9 दिसंबर 1946"}]', '1', '✅ **Correct Logic**: 26 नवंबर 1949 को संविधान तैयार होकर स्वीकार किया गया, इसलिए इसे ''संविधान दिवस'' के रूप में मनाया जाता है।
💡 **Exam Fact**: संविधान को पूर्णतः लागू 26 जनवरी 1950 को किया गया था।
🧠 **Memory Tip**: Nov-Adopt, Jan-Apply.
🚫 **Scam Alert**: प्रस्तावना में 26 नवंबर 1949 की तारीख स्पष्ट रूप से लिखी है।', 2, 0, 8, NULL, 'On which date was the Constitution of India ''adopted, enacted, and given to themselves'' by the Constituent Assembly?', '✅ **Correct Logic**: On November 26, 1949, the Constitution was ready and adopted; hence it''s celebrated as ''Constitution Day''.
💡 **Exam Fact**: It came into full effect on January 26, 1950.
🧠 **Memory Tip**: Nov-Adopt, Jan-Apply.
🚫 **Scam Alert**: The Preamble explicitly mentions Nov 26, 1949.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('31b1fbbd-1b12-449c-a431-221d88abb383', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा की अंतिम बैठक कब आयोजित की गई थी?', '[{"id":"A","text":"24 जनवरी 1950","text_en":"24 जनवरी 1950"},{"id":"B","text":"26 जनवरी 1950","text_en":"26 जनवरी 1950"},{"id":"C","text":"26 नवंबर 1949","text_en":"26 नवंबर 1949"},{"id":"D","text":"15 अगस्त 1949","text_en":"15 अगस्त 1949"}]', '0', '✅ **Correct Logic**: 24 जनवरी 1950 को संविधान सभा की अंतिम बैठक हुई, जिसमें सदस्यों ने संविधान पर हस्ताक्षर किए।
💡 **Exam Fact**: इसी दिन डॉ. राजेंद्र प्रसाद को भारत का प्रथम राष्ट्रपति चुना गया।
🧠 **Memory Tip**: 2 days before Republic Day.
🚫 **Scam Alert**: 26 जनवरी 1950 को संविधान लागू हुआ था, बैठक 24 को हुई थी।', 2, 0, 9, NULL, 'When was the final session of the Constituent Assembly held?', '✅ **Correct Logic**: The final meeting was held on January 24, 1950, where members signed the Constitution.
💡 **Exam Fact**: Dr. Rajendra Prasad was elected the first President of India on this day.
🧠 **Memory Tip**: 2 days before Republic Day.
🚫 **Scam Alert**: Constitution came into force on Jan 26; the session was on Jan 24.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('aa8d9b5b-4fd2-43ce-8783-936476b58566', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा में महिला सदस्यों की कुल संख्या कितनी थी?', '[{"id":"A","text":"10","text_en":"10"},{"id":"B","text":"12","text_en":"12"},{"id":"C","text":"15","text_en":"15"},{"id":"D","text":"20","text_en":"20"}]', '2', '✅ **Correct Logic**: संविधान सभा में कुल 15 महिला सदस्य शामिल थीं।
💡 **Exam Fact**: बेगम ऐजाज रसूल संविधान सभा में एकमात्र मुस्लिम महिला सदस्य थीं।
🧠 **Memory Tip**: 15 Women (Golden number).
🚫 **Scam Alert**: 12 अक्सर गलत डेटा के रूप में दिया जाता है, सही संख्या 15 है।', 2, 0, 10, NULL, 'What was the total number of female members in the Constituent Assembly?', '✅ **Correct Logic**: A total of 15 women members were part of the Constituent Assembly.
💡 **Exam Fact**: Begum Aizaz Rasul was the only Muslim woman member in the Assembly.
🧠 **Memory Tip**: 15 Women (Golden number).
🚫 **Scam Alert**: 12 is often cited in incorrect data; the right figure is 15.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6675d752-806f-4f31-ac00-4671c2478f7c', '5a97965a-28b4-413a-a667-bd20d59440b6', 'भारतीय संविधान के किस अनुच्छेद के तहत राष्ट्रपति पर ''महाभियोग'' (Impeachment) चलाने की प्रक्रिया का वर्णन है?', '[{"id":"A","text":"अनुच्छेद 52","text_en":"अनुच्छेद 52"},{"id":"B","text":"अनुच्छेद 61","text_en":"अनुच्छेद 61"},{"id":"C","text":"अनुच्छेद 72","text_en":"अनुच्छेद 72"},{"id":"D","text":"अनुच्छेद 56","text_en":"अनुच्छेद 56"}]', '1', '✅ **Correct Logic**: अनुच्छेद 61 राष्ट्रपति पर ''संविधान के उल्लंघन'' के आधार पर महाभियोग चलाने की प्रक्रिया प्रदान करता है।
💡 **Exam Fact**: महाभियोग का प्रस्ताव संसद के किसी भी सदन (लोकसभा या राज्यसभा) में लाया जा सकता है।
🧠 **Memory Tip**: 61 - One against Six (The President against the house).
🚫 **Scam Alert**: अनुच्छेद 72 राष्ट्रपति की क्षमादान शक्तियों (Pardon powers) से संबंधित है।', 2, 0, 1, NULL, 'Under which Article of the Indian Constitution is the procedure for ''Impeachment'' of the President described?', '✅ **Correct Logic**: Article 61 provides the procedure for impeachment of the President on the grounds of ''Violation of the Constitution''.
💡 **Exam Fact**: An impeachment charge can be initiated by either House of Parliament (Lok Sabha or Rajya Sabha).
🧠 **Memory Tip**: 61 - Think of it as a legal ''re-One'' (action) against the head.
🚫 **Scam Alert**: Article 72 relates to the Pardoning powers of the President, not impeachment.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('92b5f2f4-02a0-4e8f-bb78-0383c9d90095', '5a97965a-28b4-413a-a667-bd20d59440b6', 'संसद के ''संयुक्त अधिवेशन'' (Joint Sitting) की अध्यक्षता कौन करता है?', '[{"id":"A","text":"भारत का राष्ट्रपति","text_en":"भारत का राष्ट्रपति"},{"id":"B","text":"राज्यसभा का सभापति","text_en":"राज्यसभा का सभापति"},{"id":"C","text":"लोकसभा अध्यक्ष","text_en":"लोकसभा अध्यक्ष"},{"id":"D","text":"भारत का प्रधानमंत्री","text_en":"भारत का प्रधानमंत्री"}]', '2', '✅ **Correct Logic**: अनुच्छेद 108 के तहत संयुक्त अधिवेशन राष्ट्रपति द्वारा बुलाया जाता है, लेकिन इसकी अध्यक्षता लोकसभा अध्यक्ष (Speaker) करता है।
💡 **Exam Fact**: यदि स्पीकर अनुपस्थित हो, तो उपाध्यक्ष (Deputy Speaker) अध्यक्षता करता है।
🧠 **Memory Tip**: Speaker speaks for both when they sit together.
🚫 **Scam Alert**: राज्यसभा का सभापति (उपराष्ट्रपति) कभी भी संयुक्त अधिवेशन की अध्यक्षता नहीं करता है।', 2, 0, 2, NULL, 'Who presides over the ''Joint Sitting'' of the Parliament?', '✅ **Correct Logic**: Under Article 108, a Joint Sitting is summoned by the President, but it is presided over by the Speaker of the Lok Sabha.
💡 **Exam Fact**: If the Speaker is absent, the Deputy Speaker of the Lok Sabha presides.
🧠 **Memory Tip**: The Speaker speaks for both houses when they meet collectively.
🚫 **Scam Alert**: The Chairman of the Rajya Sabha (Vice-President) never presides over a Joint Sitting.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ce38054a-414c-4cb4-85c5-707853626b4e', '5a97965a-28b4-413a-a667-bd20d59440b6', 'निम्नलिखित कथनों पर विचार करें:
1. राज्यसभा एक स्थायी सदन है और इसे भंग नहीं किया जा सकता।
2. राज्यसभा के सदस्यों का कार्यकाल 5 वर्ष होता है।
3. प्रत्येक दो वर्ष बाद इसके एक-तिहाई सदस्य सेवानिवृत्त हो जाते हैं।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"केवल 1 और 3","text_en":"केवल 1 और 3"},{"id":"D","text":"1, 2 और 3","text_en":"1, 2 और 3"}]', '2', '✅ **Correct Logic**: कथन 1 और 3 सही हैं। राज्यसभा सदस्यों का कार्यकाल 6 वर्ष होता है, न कि 5 वर्ष।
💡 **Exam Fact**: राज्यसभा का गठन पहली बार 3 अप्रैल 1952 को किया गया था।
🧠 **Memory Tip**: Upper House = Longer Tenure (6 years).
🚫 **Scam Alert**: सदन का कार्यकाल नहीं होता, सदस्यों का कार्यकाल 6 वर्ष होता है।', 2, 0, 3, NULL, 'Consider the following statements:
1. Rajya Sabha is a permanent body and is not subject to dissolution.
2. The tenure of Rajya Sabha members is 5 years.
3. One-third of its members retire every second year.

Choose the correct statement:', '✅ **Correct Logic**: Statements 1 and 3 are correct. The tenure of Rajya Sabha members is 6 years, not 5 years.
💡 **Exam Fact**: The Rajya Sabha was first constituted on April 3, 1952.
🧠 **Memory Tip**: Upper House members stay longer (6 years).
🚫 **Scam Alert**: The House itself is permanent; only the members have a 6-year term.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('be7ec999-c341-40a7-ac75-3f6651d827b6', '5a97965a-28b4-413a-a667-bd20d59440b6', 'कोई विधेयक ''धन विधेयक'' (Money Bill) है या नहीं, इसका निर्णय कौन करता है?', '[{"id":"A","text":"राष्ट्रपति","text_en":"राष्ट्रपति"},{"id":"B","text":"वित्त मंत्री","text_en":"वित्त मंत्री"},{"id":"C","text":"लोकसभा अध्यक्ष","text_en":"लोकसभा अध्यक्ष"},{"id":"D","text":"प्रधानमंत्री","text_en":"प्रधानमंत्री"}]', '2', '✅ **Correct Logic**: अनुच्छेद 110(3) के अनुसार, लोकसभा अध्यक्ष का निर्णय अंतिम होता है कि कोई विधेयक धन विधेयक है या नहीं।
💡 **Exam Fact**: धन विधेयक केवल लोकसभा में ही पेश किया जा सकता है।
🧠 **Memory Tip**: Money belongs to the people''s house (Lok Sabha), so its head (Speaker) decides.
🚫 **Scam Alert**: राष्ट्रपति की पूर्व अनुमति आवश्यक है, लेकिन निर्णय स्पीकर का होता है।', 2, 0, 4, NULL, 'Who decides whether a Bill is a ''Money Bill'' or not?', '✅ **Correct Logic**: According to Article 110(3), the Speaker of the Lok Sabha has the final authority to decide if a bill is a Money Bill.
💡 **Exam Fact**: A Money Bill can only be introduced in the Lok Sabha.
🧠 **Memory Tip**: Money is with the people; Speaker represents the people''s house.
🚫 **Scam Alert**: Prior recommendation of the President is needed to introduce it, but the decision on its nature is the Speaker''s.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('332ea459-c66a-459d-9871-00f9c2657f8d', '5a97965a-28b4-413a-a667-bd20d59440b6', 'संवैधानिक अनुच्छेदों और उनसे संबंधित प्रावधानों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: 74 में मंत्रिपरिषद, 110 में धन विधेयक, 123 में अध्यादेश (Ordinance) और 76 में महान्यायवादी का प्रावधान है।
💡 **Exam Fact**: महान्यायवादी भारत सरकार का मुख्य कानूनी सलाहकार होता है।
🧠 **Memory Tip**: 1-2-3 Ordinance (Easy as ABC).
🚫 **Scam Alert**: अनुच्छेद 123 राष्ट्रपति के लिए है, जबकि 213 राज्यपाल के अध्यादेश के लिए है।', 2, 0, 5, NULL, 'Match the Constitutional Articles and their respective provisions:', '✅ **Correct Logic**: 74 covers Council of Ministers, 110 Money Bill, 123 Ordinance power, and 76 Attorney General.
💡 **Exam Fact**: The Attorney General is the chief legal advisor to the Government of India.
🧠 **Memory Tip**: 1-2-3... Go! President issues an Ordinance.
🚫 **Scam Alert**: Article 123 is for the President, while 213 is for the Governor''s ordinance power.', 60, 'matching', '[{"id":"(1)","label":"अनुच्छेद 74","match":"मंत्रिपरिषद (Council of Ministers)","matchId":"(a)"},{"id":"(2)","label":"अनुच्छेद 110","match":"धन विधेयक (Money Bill)","matchId":"(b)"},{"id":"(3)","label":"अनुच्छेद 123","match":"राष्ट्रपति की अध्यादेश शक्ति","matchId":"(c)"},{"id":"(4)","label":"अनुच्छेद 76","match":"भारत का महान्यायवादी (Attorney General)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a28edf1e-b005-4c5e-8083-a96afebcb009', '5a97965a-28b4-413a-a667-bd20d59440b6', 'राष्ट्रपति द्वारा राज्यसभा में कितने सदस्यों को मनोनीत (Nominate) किया जाता है?', '[{"id":"A","text":"2","text_en":"2"},{"id":"B","text":"10","text_en":"10"},{"id":"C","text":"12","text_en":"12"},{"id":"D","text":"15","text_en":"15"}]', '2', '✅ **Correct Logic**: राष्ट्रपति साहित्य, विज्ञान, कला और समाज सेवा के क्षेत्र से 12 सदस्यों को राज्यसभा में मनोनीत करता है।
💡 **Exam Fact**: 104वें संविधान संशोधन के बाद लोकसभा में एंग्लो-इंडियन का मनोनयन समाप्त कर दिया गया है।
🧠 **Memory Tip**: 12 months = 12 members.
🚫 **Scam Alert**: अब केवल राज्यसभा में मनोनयन होता है, लोकसभा में नहीं।', 2, 0, 6, NULL, 'How many members are nominated by the President to the Rajya Sabha?', '✅ **Correct Logic**: The President nominates 12 members to the Rajya Sabha from fields like literature, science, art, and social service.
💡 **Exam Fact**: Nomination of Anglo-Indians to the Lok Sabha was abolished by the 104th Amendment.
🧠 **Memory Tip**: A dozen (12) special members for the upper house.
🚫 **Scam Alert**: Nominations now only happen in the Rajya Sabha, not the Lok Sabha.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('545e57da-f660-45c6-853e-ef27d18e9029', '5a97965a-28b4-413a-a667-bd20d59440b6', 'मंत्री सामूहिक रूप से किसके प्रति उत्तरदायी होते हैं?', '[{"id":"A","text":"राष्ट्रपति","text_en":"राष्ट्रपति"},{"id":"B","text":"संसद","text_en":"संसद"},{"id":"C","text":"लोकसभा","text_en":"लोकसभा"},{"id":"D","text":"प्रधानमंत्री","text_en":"प्रधानमंत्री"}]', '2', '✅ **Correct Logic**: अनुच्छेद 75(3) के अनुसार, मंत्रिपरिषद सामूहिक रूप से ''लोकसभा'' के प्रति उत्तरदायी होती है।
💡 **Exam Fact**: व्यक्तिगत रूप से मंत्री राष्ट्रपति के प्रति उत्तरदायी होते हैं।
🧠 **Memory Tip**: Collective = Crowd = People''s House (Lok Sabha).
🚫 **Scam Alert**: ''संसद'' और ''लोकसभा'' में भ्रमित न हों; उत्तर लोकसभा होगा।', 2, 0, 7, NULL, 'To whom are the Ministers collectively responsible?', '✅ **Correct Logic**: According to Article 75(3), the Council of Ministers is collectively responsible to the ''Lok Sabha''.
💡 **Exam Fact**: Individually, ministers are responsible to the President.
🧠 **Memory Tip**: Collective accountability is to the house representing the collective (people).
🚫 **Scam Alert**: Do not confuse ''Parliament'' with ''Lok Sabha''; the specific answer is Lok Sabha.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fe445329-0fb4-4d36-9391-0680b71985fd', '5a97965a-28b4-413a-a667-bd20d59440b6', 'संसद के दो सत्रों के बीच अधिकतम कितना अंतराल (Interval) हो सकता है?', '[{"id":"A","text":"3 महीने","text_en":"3 महीने"},{"id":"B","text":"6 महीने","text_en":"6 महीने"},{"id":"C","text":"9 महीने","text_en":"9 महीने"},{"id":"D","text":"1 वर्ष","text_en":"1 वर्ष"}]', '1', '✅ **Correct Logic**: संविधान के अनुसार, संसद के दो सत्रों के बीच 6 महीने से अधिक का अंतर नहीं होना चाहिए।
💡 **Exam Fact**: भारत में सामान्यतः तीन सत्र (बजट, मानसून, शीतकालीन) होते हैं।
🧠 **Memory Tip**: 6 months max gap.
🚫 **Scam Alert**: हालांकि साल में कम से कम दो बार मिलना अनिवार्य है, पर आमतौर पर तीन बार बैठक होती है।', 2, 0, 8, NULL, 'What is the maximum interval allowed between two sessions of Parliament?', '✅ **Correct Logic**: As per the Constitution, the maximum gap between two sessions of Parliament cannot exceed 6 months.
💡 **Exam Fact**: India traditionally has three sessions: Budget, Monsoon, and Winter.
🧠 **Memory Tip**: A half-year (6 months) is the limit.
🚫 **Scam Alert**: While meeting twice a year is the legal minimum, three sessions are the norm.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('43cb0baa-1634-4a9b-9897-9df0cc41140a', '5a97965a-28b4-413a-a667-bd20d59440b6', 'लोकसभा का सदस्य बनने के लिए न्यूनतम आयु क्या है?', '[{"id":"A","text":"18 वर्ष","text_en":"18 वर्ष"},{"id":"B","text":"21 वर्ष","text_en":"21 वर्ष"},{"id":"C","text":"25 वर्ष","text_en":"25 वर्ष"},{"id":"D","text":"30 वर्ष","text_en":"30 वर्ष"}]', '2', '✅ **Correct Logic**: लोकसभा सदस्य के लिए न्यूनतम आयु 25 वर्ष है।
💡 **Exam Fact**: राज्यसभा के लिए न्यूनतम आयु 30 वर्ष और राष्ट्रपति के लिए 35 वर्ष है।
🧠 **Memory Tip**: 25 (LS) < 30 (RS) < 35 (Prez).
🚫 **Scam Alert**: 21 वर्ष पंचायत चुनाव लड़ने की आयु है, लोकसभा की नहीं।', 2, 0, 9, NULL, 'What is the minimum age to become a member of the Lok Sabha?', '✅ **Correct Logic**: The minimum age required to be a member of the Lok Sabha is 25 years.
💡 **Exam Fact**: It is 30 years for Rajya Sabha and 35 years for the President.
🧠 **Memory Tip**: 25 (LS) < 30 (RS) < 35 (Prez).
🚫 **Scam Alert**: 21 is the age for contesting Panchayat elections, not Lok Sabha.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('05a20ac7-970a-4828-8e4d-e909f026c271', '5a97965a-28b4-413a-a667-bd20d59440b6', 'भारत का प्रधानमंत्री बनने के लिए न्यूनतम आयु क्या होगी यदि वह राज्यसभा का सदस्य है?', '[{"id":"A","text":"25 वर्ष","text_en":"25 वर्ष"},{"id":"B","text":"30 वर्ष","text_en":"30 वर्ष"},{"id":"C","text":"35 वर्ष","text_en":"35 वर्ष"},{"id":"D","text":"कोई सीमा नहीं","text_en":"कोई सीमा नहीं"}]', '1', '✅ **Correct Logic**: चूंकि राज्यसभा सदस्य बनने की न्यूनतम आयु 30 वर्ष है, इसलिए यदि पीएम वहां से आता है, तो उसकी न्यूनतम आयु 30 वर्ष होगी।
💡 **Exam Fact**: यदि पीएम लोकसभा से है, तो न्यूनतम आयु 25 वर्ष हो सकती है।
🧠 **Memory Tip**: RS = 30.
🚫 **Scam Alert**: प्रश्न में शर्त (Condition) दी गई है, उसे ध्यान से पढ़ें।', 2, 0, 10, NULL, 'What would be the minimum age to become the Prime Minister of India if he/she is a member of the Rajya Sabha?', '✅ **Correct Logic**: Since the minimum age to be a member of Rajya Sabha is 30, a PM from that house must be at least 30 years old.
💡 **Exam Fact**: A PM from the Lok Sabha can be as young as 25.
🧠 **Memory Tip**: RS route requires 30 years.
🚫 **Scam Alert**: Always read the condition in the question; 25 is for Lok Sabha members.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d6ba08c4-9619-4b44-8b72-6a095333bc89', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'भारतीय संविधान के किस अनुच्छेद के तहत सर्वोच्च न्यायालय को ''अभिलेख न्यायालय'' (Court of Record) का दर्जा दिया गया है?', '[{"id":"A","text":"अनुच्छेद 124","text_en":"अनुच्छेद 124"},{"id":"B","text":"अनुच्छेद 129","text_en":"अनुच्छेद 129"},{"id":"C","text":"अनुच्छेद 131","text_en":"अनुच्छेद 131"},{"id":"D","text":"अनुच्छेद 143","text_en":"अनुच्छेद 143"}]', '1', '✅ **Correct Logic**: अनुच्छेद 129 सर्वोच्च न्यायालय को अभिलेख न्यायालय घोषित करता है, जिसका अर्थ है कि इसके निर्णय साक्ष्य के रूप में सुरक्षित रखे जाएंगे और इसे अपनी अवमानना के लिए दंड देने की शक्ति होगी।
💡 **Exam Fact**: उच्च न्यायालय के लिए यही शक्ति अनुच्छेद 215 में दी गई है।
🧠 **Memory Tip**: 129 - Records are ''Fine'' (9 looks like g/fine).
🚫 **Scam Alert**: अनुच्छेद 124 सुप्रीम कोर्ट के गठन (Establishment) से संबंधित है।', 2, 0, 1, NULL, 'Under which Article of the Indian Constitution is the Supreme Court given the status of a ''Court of Record''?', '✅ **Correct Logic**: Article 129 declares the Supreme Court as a Court of Record, meaning its proceedings are recorded for testimony and it has the power to punish for its contempt.
💡 **Exam Fact**: Similar power is given to High Courts under Article 215.
🧠 **Memory Tip**: 129 - Keep records ''Fine''.
🚫 **Scam Alert**: Article 124 is about the establishment and constitution of the Supreme Court.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('36880cfa-a143-4316-8b45-799168108c02', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'सर्वोच्च न्यायालय के न्यायाधीशों की सेवानिवृत्ति की आयु (Retirement Age) क्या है?', '[{"id":"A","text":"60 वर्ष","text_en":"60 वर्ष"},{"id":"B","text":"62 वर्ष","text_en":"62 वर्ष"},{"id":"C","text":"65 वर्ष","text_en":"65 वर्ष"},{"id":"D","text":"70 वर्ष","text_en":"70 वर्ष"}]', '2', '✅ **Correct Logic**: सर्वोच्च न्यायालय के न्यायाधीश 65 वर्ष की आयु तक पद पर बने रहते हैं।
💡 **Exam Fact**: उच्च न्यायालय (High Court) के न्यायाधीशों की सेवानिवृत्ति आयु 62 वर्ष है।
🧠 **Memory Tip**: SC is Big (65), HC is Small (62).
🚫 **Scam Alert**: कार्यकाल की कोई न्यूनतम सीमा (जैसे 5 या 6 वर्ष) तय नहीं है, केवल अधिकतम आयु सीमा है।', 2, 0, 2, NULL, 'What is the retirement age of the judges of the Supreme Court?', '✅ **Correct Logic**: Judges of the Supreme Court hold office until they attain the age of 65 years.
💡 **Exam Fact**: For High Court judges, the retirement age is 62 years.
🧠 **Memory Tip**: SC is Big Brother (65), HC is Younger (62).
🚫 **Scam Alert**: There is no fixed tenure (like 5 or 6 years) specified; only the upper age limit matters.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fdf520a4-419e-43d5-8edd-dc958c598b84', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'भारत के सर्वोच्च न्यायालय के पास ''परामर्शदात्री क्षेत्राधिकार'' (Advisory Jurisdiction) किस अनुच्छेद के अंतर्गत है?', '[{"id":"A","text":"अनुच्छेद 141","text_en":"अनुच्छेद 141"},{"id":"B","text":"अनुच्छेद 143","text_en":"अनुच्छेद 143"},{"id":"C","text":"अनुच्छेद 137","text_en":"अनुच्छेद 137"},{"id":"D","text":"अनुच्छेद 142","text_en":"अनुच्छेद 142"}]', '1', '✅ **Correct Logic**: अनुच्छेद 143 के तहत राष्ट्रपति सार्वजनिक महत्व के कानूनी प्रश्नों पर सर्वोच्च न्यायालय से राय मांग सकता है।
💡 **Exam Fact**: न्यायालय राय देने के लिए और राष्ट्रपति उसे मानने के लिए बाध्य नहीं है।
🧠 **Memory Tip**: 1-4-3 (I Love You/Asking for advice).
🚫 **Scam Alert**: अनुच्छेद 137 न्यायिक पुनरावलोकन (Judicial Review) से संबंधित है।', 2, 0, 3, NULL, 'The Supreme Court of India has ''Advisory Jurisdiction'' under which Article?', '✅ **Correct Logic**: Under Article 143, the President may seek the opinion of the Supreme Court on questions of law or fact of public importance.
💡 **Exam Fact**: Neither is the Court bound to give an opinion, nor is the President bound to follow it.
🧠 **Memory Tip**: 1-4-3 (Code for asking/advice).
🚫 **Scam Alert**: Article 137 relates to the power of Judicial Review of its own judgments.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('60f340f3-ee6d-4093-9dd2-30ae509edee0', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'सर्वोच्च न्यायालय के न्यायाधीश को पद से हटाने के लिए ''महाभियोग'' जैसा प्रस्ताव संसद के किस सदन में लाया जा सकता है?', '[{"id":"A","text":"केवल लोकसभा","text_en":"केवल लोकसभा"},{"id":"B","text":"केवल राज्यसभा","text_en":"केवल राज्यसभा"},{"id":"C","text":"संसद के किसी भी सदन में","text_en":"संसद के किसी भी सदन में"},{"id":"D","text":"केवल राष्ट्रपति के आदेश पर","text_en":"केवल राष्ट्रपति के आदेश पर"}]', '2', '✅ **Correct Logic**: न्यायाधीश को हटाने का प्रस्ताव किसी भी सदन में लाया जा सकता है (लोकसभा में 100 सदस्यों और राज्यसभा में 50 सदस्यों के समर्थन के साथ)।
💡 **Exam Fact**: अब तक किसी भी न्यायाधीश को इस प्रक्रिया द्वारा हटाया नहीं गया है।
🧠 **Memory Tip**: Any house can start the fire (Removal process).
🚫 **Scam Alert**: राष्ट्रपति सीधे नहीं हटा सकता, पहले संसद से विशेष बहुमत पारित होना अनिवार्य है।', 2, 0, 4, NULL, 'A motion to remove a Supreme Court judge can be initiated in which House of Parliament?', '✅ **Correct Logic**: A removal motion can be introduced in either House (with support of 100 members in LS or 50 in RS).
💡 **Exam Fact**: No judge of the Supreme Court has been removed through this process to date.
🧠 **Memory Tip**: Either house can trigger the removal process.
🚫 **Scam Alert**: The President cannot remove a judge directly; a special majority from both houses is mandatory first.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('aeff30d2-07a3-4a14-a027-ef4eb829c517', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'न्यायिक शब्दावली और संबंधित अनुच्छेदों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: 131 में केंद्र-राज्यों के विवाद (Original Jurisdiction) हैं। 137 में अपने ही फैसले की समीक्षा। 136 में विशेष अपील और 142 पूर्ण न्याय (Complete Justice) करने की शक्ति देता है।
💡 **Exam Fact**: अनुच्छेद 142 का प्रयोग हाल ही में अयोध्या विवाद जैसे बड़े मामलों में किया गया था।
🧠 **Memory Tip**: 136 - Special (S is 6th letter alphabetically in some codes).
🚫 **Scam Alert**: अनुच्छेद 131 केवल सरकारी विवादों के लिए है, नागरिकों के लिए नहीं।', 2, 0, 5, NULL, 'Match the judicial terms and related Articles:', '✅ **Correct Logic**: 131 covers Original Jurisdiction (Centre-State disputes). 137 covers Review Jurisdiction. 136 is for Special Leave Petition, and 142 provides the power for ''Complete Justice''.
💡 **Exam Fact**: Article 142 was notably invoked in the Ayodhya dispute case.
🧠 **Memory Tip**: 136-S-Special.
🚫 **Scam Alert**: Article 131 is for government disputes only, not for individual citizens.', 60, 'matching', '[{"id":"(1)","label":"मूल क्षेत्राधिकार","match":"अनुच्छेद 131","matchId":"(a)"},{"id":"(2)","label":"न्यायिक पुनरावलोकन","match":"अनुच्छेद 137","matchId":"(b)"},{"id":"(3)","label":"विशेष अनुमति याचिका (SLP)","match":"अनुच्छेद 136","matchId":"(c)"},{"id":"(4)","label":"कानून का शासन/न्याय","match":"अनुच्छेद 142","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4d856740-6f63-4e5f-bc28-1df93bec009b', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'निम्नलिखित कथनों पर विचार करें:
1. भारत में एकीकृत (Integrated) न्यायपालिका की व्यवस्था है।
2. जनहित याचिका (PIL) की अवधारणा भारत में न्यायमूर्ति पी.एन. भगवती द्वारा शुरू की गई थी।
3. सर्वोच्च न्यायालय के न्यायाधीशों का वेतन भारत की संचित निधि (Consolidated Fund) पर भारित होता है।

सही कथन चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 1","text_en":"केवल 1"}]', '2', '✅ **Correct Logic**: तीनों कथन सही हैं। भारत में पिरामिड के आकार की न्यायपालिका है जिसमें सुप्रीम कोर्ट शीर्ष पर है।
💡 **Exam Fact**: न्यायाधीशों के वेतन में उनके कार्यकाल के दौरान कोई हानिकारक परिवर्तन (वित्तीय आपातकाल को छोड़कर) नहीं किया जा सकता।
🧠 **Memory Tip**: P-B (PIL - Bhagwati).
🚫 **Scam Alert**: उच्च न्यायालय के न्यायाधीशों का वेतन राज्य की संचित निधि से आता है, जबकि पेंशन भारत की संचित निधि से।', 2, 0, 6, NULL, 'Consider the following statements:
1. India has an Integrated Judicial System.
2. The concept of PIL was introduced in India by Justice P.N. Bhagwati.
3. The salaries of Supreme Court judges are charged to the Consolidated Fund of India.

Choose the correct statement:', '✅ **Correct Logic**: All three statements are correct. India has a pyramid-shaped integrated judiciary with the SC at the top.
💡 **Exam Fact**: Salaries of judges cannot be altered to their disadvantage during their term, except during a Financial Emergency.
🧠 **Memory Tip**: P-B (PIL - Bhagwati).
🚫 **Scam Alert**: High Court judges'' salaries come from the State fund, but their pensions come from the Central (India) fund.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e46c445a-12a7-46fb-b5a7-694fc95430bd', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'सर्वोच्च न्यायालय का न्यायाधीश बनने के लिए ''उच्च न्यायालय'' में कम से कम कितने वर्षों का वकालत (Advocate) का अनुभव अनिवार्य है?', '[{"id":"A","text":"5 वर्ष","text_en":"5 वर्ष"},{"id":"B","text":"10 वर्ष","text_en":"10 वर्ष"},{"id":"C","text":"15 वर्ष","text_en":"15 वर्ष"},{"id":"D","text":"20 वर्ष","text_en":"20 वर्ष"}]', '1', '✅ **Correct Logic**: योग्यता के लिए या तो 5 वर्ष तक HC का न्यायाधीश होना चाहिए या 10 वर्ष तक HC में अधिवक्ता (Advocate) होना चाहिए।
💡 **Exam Fact**: राष्ट्रपति की दृष्टि में एक ''पारंगत विधिवेत्ता'' (Distinguished Jurist) भी न्यायाधीश बन सकता है।
🧠 **Memory Tip**: Judge-5, Lawyer-10.
🚫 **Scam Alert**: 10 वर्ष का अनुभव केवल एक उच्च न्यायालय में नहीं, बल्कि निरंतर कई उच्च न्यायालयों में भी हो सकता है।', 2, 0, 7, NULL, 'How many years of practice as an Advocate in a High Court is mandatory to become a Supreme Court judge?', '✅ **Correct Logic**: To be eligible, a person must have been an HC judge for 5 years OR an advocate in an HC for 10 years.
💡 **Exam Fact**: A ''Distinguished Jurist'' in the opinion of the President is also eligible for appointment.
🧠 **Memory Tip**: Judge-5, Lawyer-10.
🚫 **Scam Alert**: The 10-year practice can be in one High Court or in succession in two or more High Courts.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('793326ac-d39b-4ebe-8bfb-9700f4ed4d0c', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'भारत में ''न्यायिक सक्रियता'' (Judicial Activism) का मुख्य अर्थ क्या है?', '[{"id":"A","text":"न्यायपालिका द्वारा कार्यपालिका के कार्यों में हस्तक्षेप करना","text_en":"न्यायपालिका द्वारा कार्यपालिका के कार्यों में हस्तक्षेप करना"},{"id":"B","text":"संविधान की रक्षा के लिए न्यायपालिका का सक्रिय होना","text_en":"संविधान की रक्षा के लिए न्यायपालिका का सक्रिय होना"},{"id":"C","text":"जनहित के मुद्दों पर स्वतः संज्ञान (Suo-motu) लेना","text_en":"जनहित के मुद्दों पर स्वतः संज्ञान (Suo-motu) लेना"},{"id":"D","text":"उपरोक्त सभी","text_en":"उपरोक्त सभी"}]', '3', '✅ **Correct Logic**: न्यायिक सक्रियता का अर्थ है जब न्यायपालिका अपने पारंपरिक दायरे से बाहर निकलकर नागरिकों के अधिकारों की रक्षा के लिए सक्रिय भूमिका निभाती है।
💡 **Exam Fact**: इसे कभी-कभी ''न्यायिक अतिसक्रियता'' (Judicial Overreach) भी कहा जाता है जब यह सीमा पार करती है।
🧠 **Memory Tip**: Active Judge = Judicial Activism.
🚫 **Scam Alert**: यह शक्तियों के पृथक्करण के सिद्धांत के विरुद्ध लग सकता है, लेकिन लोकतांत्रिक संतुलन के लिए आवश्यक है।', 2, 0, 8, NULL, 'What is the primary meaning of ''Judicial Activism'' in India?', '✅ **Correct Logic**: Judicial Activism occurs when the judiciary takes a proactive role in protecting citizen rights and social justice beyond traditional limits.
💡 **Exam Fact**: It is sometimes criticized as ''Judicial Overreach'' if it interferes too much in governance.
🧠 **Memory Tip**: Active Judge = Judicial Activism.
🚫 **Scam Alert**: While it may seem to violate the separation of powers, it serves as a democratic check.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fd2255d8-f080-41ba-8ab7-9cb0d4c43da8', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'संविधान का ''अंतिम व्याख्याकार'' (Final Interpreter) किसे माना जाता है?', '[{"id":"A","text":"भारत का राष्ट्रपति","text_en":"भारत का राष्ट्रपति"},{"id":"B","text":"संसद","text_en":"संसद"},{"id":"C","text":"भारत का महान्यायवादी","text_en":"भारत का महान्यायवादी"},{"id":"D","text":"सर्वोच्च न्यायालय","text_en":"सर्वोच्च न्यायालय"}]', '3', '✅ **Correct Logic**: सर्वोच्च न्यायालय को संविधान का संरक्षक और अंतिम व्याख्याकार माना जाता है।
💡 **Exam Fact**: केशवानंद भारती मामले (1973) में सुप्रीम कोर्ट ने ''मूल ढांचे'' (Basic Structure) का सिद्धांत दिया था।
🧠 **Memory Tip**: SC is the Final Umpire of the Law.
🚫 **Scam Alert**: संसद संविधान में संशोधन कर सकती है, लेकिन व्याख्या केवल न्यायपालिका ही करेगी।', 2, 0, 9, NULL, 'Who is considered the ''Final Interpreter'' of the Constitution?', '✅ **Correct Logic**: The Supreme Court is recognized as the guardian and the final interpreter of the Constitution.
💡 **Exam Fact**: The ''Basic Structure'' doctrine was propounded in the Kesavananda Bharati case (1973).
🧠 **Memory Tip**: SC is the Final Umpire of the Law.
🚫 **Scam Alert**: Parliament can amend the constitution, but the power to interpret it lies solely with the Judiciary.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('640a98d0-3f41-4687-b80e-8ac0c833c667', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'वर्तमान में भारत के सर्वोच्च न्यायालय में न्यायाधीशों की कुल स्वीकृत संख्या (अध्यक्ष सहित) कितनी है?', '[{"id":"A","text":"31","text_en":"31"},{"id":"B","text":"33","text_en":"33"},{"id":"C","text":"34","text_en":"34"},{"id":"D","text":"30","text_en":"30"}]', '2', '✅ **Correct Logic**: 2019 के संशोधन के बाद, सुप्रीम कोर्ट में 1 मुख्य न्यायाधीश और 33 अन्य न्यायाधीश (कुल 34) हो सकते हैं।
💡 **Exam Fact**: मूल संविधान में न्यायाधीशों की संख्या केवल 8 (1+7) थी।
🧠 **Memory Tip**: 34 = 3+4 = 7 (Double of the original 7).
🚫 **Scam Alert**: 33 अन्य न्यायाधीश हैं, प्रश्न में ''अध्यक्ष सहित'' पूछा गया है, तो 34 सही होगा।', 2, 0, 10, NULL, 'What is the current sanctioned strength of judges in the Supreme Court (including the CJI)?', '✅ **Correct Logic**: Following the 2019 amendment, the Supreme Court can have 1 CJI and 33 other judges (Total 34).
💡 **Exam Fact**: Originally, the strength was only 8 (1+7).
🧠 **Memory Tip**: Three-Four (34) for Justice.
🚫 **Scam Alert**: 33 is the number of ''other'' judges; ''including CJI'' makes it 34.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4614c6e3-0d4a-4eec-888c-c288bbab558d', '6abaf652-ef39-468b-a88a-be12bdb55484', 'भारतीय संविधान के किस अनुच्छेद और भाग में संशोधन की प्रक्रिया का उल्लेख है?', '[{"id":"A","text":"अनुच्छेद 368, भाग XX","text_en":"अनुच्छेद 368, भाग XX"},{"id":"B","text":"अनुच्छेद 356, भाग XVIII","text_en":"अनुच्छेद 356, भाग XVIII"},{"id":"C","text":"अनुच्छेद 370, भाग XXI","text_en":"अनुच्छेद 370, भाग XXI"},{"id":"D","text":"अनुच्छेद 360, भाग XX","text_en":"अनुच्छेद 360, भाग XX"}]', '0', '✅ **Correct Logic**: अनुच्छेद 368 संसद को संविधान और उसकी प्रक्रियाओं को संशोधित करने की शक्ति देता है।
💡 **Exam Fact**: यह प्रक्रिया दक्षिण अफ्रीका के संविधान से ली गई है।
🧠 **Memory Tip**: 368 - Three-Six-Eight (Fixing the state).
🚫 **Scam Alert**: भाग XVIII आपातकालीन प्रावधानों के लिए है, संशोधन के लिए नहीं।', 2, 0, 1, NULL, 'In which Article and Part of the Indian Constitution is the amendment procedure mentioned?', '✅ **Correct Logic**: Article 368 in Part XX grants Parliament the power to amend the Constitution and its procedures.
💡 **Exam Fact**: This procedure is borrowed from the Constitution of South Africa.
🧠 **Memory Tip**: 368 - Fixing the Great (State).
🚫 **Scam Alert**: Part XVIII is for Emergency provisions, not amendments.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3edd94ec-946b-4ae7-899e-7048ac9d505d', '6abaf652-ef39-468b-a88a-be12bdb55484', 'किस संविधान संशोधन को ''लघु संविधान'' (Mini Constitution) कहा जाता है?', '[{"id":"A","text":"44वां संशोधन","text_en":"44वां संशोधन"},{"id":"B","text":"42वां संशोधन","text_en":"42वां संशोधन"},{"id":"C","text":"73वां संशोधन","text_en":"73वां संशोधन"},{"id":"D","text":"101वां संशोधन","text_en":"101वां संशोधन"}]', '1', '✅ **Correct Logic**: 42वें संशोधन (1976) द्वारा संविधान में व्यापक परिवर्तन किए गए थे, जिसमें प्रस्तावना में ''समाजवादी, धर्मनिरपेक्ष और अखंडता'' शब्द जोड़ना शामिल था।
💡 **Exam Fact**: इसी संशोधन द्वारा मौलिक कर्तव्यों (भाग IV-A) को जोड़ा गया था।
🧠 **Memory Tip**: 4+2 = 6 (Emergency ended shortly after 1976).
🚫 **Scam Alert**: 44वां संशोधन 42वें के विवादित प्रावधानों को हटाने के लिए लाया गया था।', 2, 0, 2, NULL, 'Which Constitutional Amendment is known as the ''Mini Constitution''?', '✅ **Correct Logic**: The 42nd Amendment (1976) introduced extensive changes, including adding ''Socialist, Secular, and Integrity'' to the Preamble.
💡 **Exam Fact**: Fundamental Duties (Part IV-A) were also added by this amendment.
🧠 **Memory Tip**: 42 - Four-Two-Too many changes.
🚫 **Scam Alert**: The 44th Amendment was actually brought to undo the controversial changes of the 42nd.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fcc11db2-a339-46c3-9217-66ac051db0fc', '6abaf652-ef39-468b-a88a-be12bdb55484', '91वें संविधान संशोधन अधिनियम (2003) के अनुसार, मंत्रिपरिषद का आकार लोकसभा की कुल सदस्य संख्या के कितने प्रतिशत से अधिक नहीं हो सकता?', '[{"id":"A","text":"10%","text_en":"10%"},{"id":"B","text":"15%","text_en":"15%"},{"id":"C","text":"20%","text_en":"20%"},{"id":"D","text":"25%","text_en":"25%"}]', '1', '✅ **Correct Logic**: 91वें संशोधन ने मंत्रियों की संख्या को लोकसभा (या विधानसभा) की कुल सदस्य संख्या के 15% तक सीमित कर दिया।
💡 **Exam Fact**: छोटे राज्यों के लिए मंत्रियों की न्यूनतम संख्या 12 निर्धारित की गई है।
🧠 **Memory Tip**: 91 - No one (1) can exceed 15 (5+1=6... wait, just remember 15%).
🚫 **Scam Alert**: इसमें प्रधानमंत्री/मुख्यमंत्री भी शामिल होते हैं।', 2, 0, 3, NULL, 'According to the 91st Amendment Act (2003), the size of the Council of Ministers cannot exceed what percentage of the total strength of the Lok Sabha?', '✅ **Correct Logic**: The 91st Amendment limited the number of ministers to 15% of the total strength of the Lok Sabha (or State Assembly).
💡 **Exam Fact**: For smaller states, the minimum number of ministers is fixed at 12.
🧠 **Memory Tip**: 91 - Limit on the ''One'' (PM) and his team to 15.
🚫 **Scam Alert**: This limit ''includes'' the Prime Minister/Chief Minister.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ff301ce0-b5d2-4b63-859d-a0ab877d7f38', '6abaf652-ef39-468b-a88a-be12bdb55484', 'जीएसटी (GST) को किस संविधान संशोधन अधिनियम के माध्यम से लागू किया गया था?', '[{"id":"A","text":"100वां","text_en":"100वां"},{"id":"B","text":"101वां","text_en":"101वां"},{"id":"C","text":"102वां","text_en":"102वां"},{"id":"D","text":"103वां","text_en":"103वां"}]', '1', '✅ **Correct Logic**: 101वें संशोधन (2016) द्वारा ''वस्तु एवं सेवा कर'' (GST) को संवैधानिक दर्जा दिया गया।
💡 **Exam Fact**: 101 का ''कन्यादान'' (Tax gift to the nation).
🧠 **Memory Tip**: 101 - One nation, One tax.
🚫 **Scam Alert**: 122वां ''विधेयक'' (Bill) था, लेकिन ''अधिनियम'' (Act) 101वां है।', 2, 0, 4, NULL, 'Through which Constitutional Amendment Act was GST implemented?', '✅ **Correct Logic**: The 101st Amendment (2016) provided the constitutional basis for Goods and Services Tax (GST).
💡 **Exam Fact**: Think of 101 as the ''One Nation, One Tax'' shagun.
🧠 **Memory Tip**: 101 - One for Tax.
🚫 **Scam Alert**: It was the 122nd ''Bill'', but the 101st ''Act''. Always check the term ''Act''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('118e9db9-6138-45e8-b176-ca9efde0ce48', '6abaf652-ef39-468b-a88a-be12bdb55484', 'संशोधन और उनके प्रमुख विषयों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: 21वां (1967) सिंधी भाषा; 52वां (1985) दलबदल; 61वां (1989) मतदान आयु; 86वां (2002) शिक्षा।
💡 **Exam Fact**: 86वें संशोधन ने अनुच्छेद 21A जोड़ा था।
🧠 **Memory Tip**: 61 - Turning 18 in ''89.
🚫 **Scam Alert**: दलबदल 10वीं अनुसूची से संबंधित है।', 2, 0, 5, NULL, 'Match the amendments and their primary subjects:', '✅ **Correct Logic**: 21st (1967) added Sindhi; 52nd (1985) Anti-defection; 61st (1989) Voting age; 86th (2002) Education.
💡 **Exam Fact**: The 86th Amendment inserted Article 21A into the Constitution.
🧠 **Memory Tip**: 61 - 21 to 18 age drop.
🚫 **Scam Alert**: Anti-defection is linked specifically to the 10th Schedule.', 60, 'matching', '[{"id":"(1)","label":"21वां संशोधन","match":"सिंधी भाषा को शामिल करना","matchId":"(a)"},{"id":"(2)","label":"52वां संशोधन","match":"दलबदल विरोधी कानून","matchId":"(b)"},{"id":"(3)","label":"61वां संशोधन","match":"मतदान की आयु 21 से 18 करना","matchId":"(c)"},{"id":"(4)","label":"86वां संशोधन","match":"शिक्षा का अधिकार (RTE)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a9a9b19b-7c69-4408-8456-1697fbe50c26', '6abaf652-ef39-468b-a88a-be12bdb55484', 'किस संशोधन द्वारा सिंधी भाषा को 8वीं अनुसूची में 15वीं भाषा के रूप में जोड़ा गया था?', '[{"id":"A","text":"21वां संशोधन","text_en":"21वां संशोधन"},{"id":"B","text":"71वां संशोधन","text_en":"71वां संशोधन"},{"id":"C","text":"92वां संशोधन","text_en":"92वां संशोधन"},{"id":"D","text":"14वां संशोधन","text_en":"14वां संशोधन"}]', '0', '✅ **Correct Logic**: 21वें संशोधन (1967) ने सिंधी को जोड़ा। बाद में 71वें ने कोंकणी, मणिपुरी, नेपाली (KMN) को जोड़ा।
💡 **Exam Fact**: वर्तमान में 8वीं अनुसूची में कुल 22 भाषाएं हैं।
🧠 **Memory Tip**: 21 (Sindhi) + 71 (KMN) = 92 (BDMS - Bodo, Dogri, Maithili, Santhali).
🚫 **Scam Alert**: 92वें संशोधन ने अंतिम 4 भाषाएं जोड़ी थीं।', 2, 0, 6, NULL, 'By which amendment was the Sindhi language added to the 8th Schedule as the 15th language?', '✅ **Correct Logic**: The 21st Amendment (1967) added Sindhi. Later, the 71st added Konkani, Manipuri, and Nepali.
💡 **Exam Fact**: There are currently 22 languages in the 8th Schedule.
🧠 **Memory Tip**: 21 + 71 = 92 (The math of languages).
🚫 **Scam Alert**: The 92nd Amendment added the final set of 4 languages (BDMS).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('35374d00-9e7d-4dcf-a609-8e2fb3c8bc92', '6abaf652-ef39-468b-a88a-be12bdb55484', 'संवैधानिक संशोधनों के संबंध में कौन सा कथन सही है?
1. संशोधन विधेयक किसी भी सदन में पेश किया जा सकता है।
2. राष्ट्रपति संशोधन विधेयक पर अपनी सहमति देने के लिए बाध्य है।
3. संशोधन के लिए संयुक्त बैठक (Joint Sitting) का प्रावधान नहीं है।

सही विकल्प चुनें:', '[{"id":"A","text":"केवल 1 और 2","text_en":"केवल 1 और 2"},{"id":"B","text":"केवल 2 और 3","text_en":"केवल 2 और 3"},{"id":"C","text":"1, 2 और 3","text_en":"1, 2 और 3"},{"id":"D","text":"केवल 3","text_en":"केवल 3"}]', '2', '✅ **Correct Logic**: 24वें संशोधन (1971) के बाद राष्ट्रपति के लिए हस्ताक्षर करना अनिवार्य हो गया है। संशोधन बिल पर गतिरोध होने पर संयुक्त बैठक नहीं बुलाई जा सकती।
💡 **Exam Fact**: प्रत्येक सदन को बिल अलग-अलग विशेष बहुमत से पारित करना होता है।
🧠 **Memory Tip**: No Joint Sitting for serious fixing (Amendments).
🚫 **Scam Alert**: राज्य विधानमंडल संशोधन प्रक्रिया शुरू नहीं कर सकते।', 2, 0, 7, NULL, 'Which statement is correct regarding Constitutional Amendments?
1. An amendment bill can be introduced in either House.
2. The President is bound to give assent to an amendment bill.
3. There is no provision for a Joint Sitting for an amendment bill.

Choose the correct option:', '✅ **Correct Logic**: After the 24th Amendment (1971), the President must give assent to an amendment bill. There is no Joint Sitting if the two houses disagree.
💡 **Exam Fact**: Each house must pass the bill separately with a special majority.
🧠 **Memory Tip**: Amendments are too serious for a ''Joint Sitting'' shortcut.
🚫 **Scam Alert**: State legislatures cannot initiate a constitutional amendment.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('562e6544-326f-46e5-bc1c-fb3642ab661d', '6abaf652-ef39-468b-a88a-be12bdb55484', 'आर्थिक रूप से पिछड़े वर्गों (EWS) को 10% आरक्षण किस संशोधन अधिनियम द्वारा दिया गया?', '[{"id":"A","text":"101वां","text_en":"101वां"},{"id":"B","text":"102वां","text_en":"102वां"},{"id":"C","text":"103वां","text_en":"103वां"},{"id":"D","text":"104वां","text_en":"104वां"}]', '2', '✅ **Correct Logic**: 103वें संशोधन (2019) ने अनुच्छेद 15 और 16 में संशोधन कर EWS आरक्षण का प्रावधान किया।
💡 **Exam Fact**: यह शैक्षणिक संस्थानों और सरकारी नौकरियों दोनों पर लागू होता है।
🧠 **Memory Tip**: 10-3... Three letters in EWS.
🚫 **Scam Alert**: 102वां संशोधन राष्ट्रीय पिछड़ा वर्ग आयोग (NCBC) को संवैधानिक दर्जा देने के लिए था।', 2, 0, 8, NULL, '10% reservation for Economically Weaker Sections (EWS) was given by which Amendment Act?', '✅ **Correct Logic**: The 103rd Amendment (2019) amended Articles 15 and 16 to provide EWS reservation.
💡 **Exam Fact**: It applies to both educational institutions and government jobs.
🧠 **Memory Tip**: EWS = 3 letters, so 103.
🚫 **Scam Alert**: The 102nd Amendment gave constitutional status to the NCBC.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('38dfd456-8270-410a-880e-6d3046874b9d', '6abaf652-ef39-468b-a88a-be12bdb55484', 'पंचायती राज संस्थाओं को संवैधानिक दर्जा किस संशोधन द्वारा प्रदान किया गया था?', '[{"id":"A","text":"72वां","text_en":"72वां"},{"id":"B","text":"73वां","text_en":"73वां"},{"id":"C","text":"74वां","text_en":"74वां"},{"id":"D","text":"64वां","text_en":"64वां"}]', '1', '✅ **Correct Logic**: 73वें संशोधन (1992) द्वारा संविधान में भाग IX और 11वीं अनुसूची जोड़ी गई।
💡 **Exam Fact**: मध्य प्रदेश इसे लागू करने वाला देश का पहला राज्य था।
🧠 **Memory Tip**: 73-P (Panchayat), 74-M (Municipality).
🚫 **Scam Alert**: 74वां नगर पालिकाओं से संबंधित है।', 2, 0, 9, NULL, 'By which amendment was constitutional status granted to Panchayati Raj Institutions?', '✅ **Correct Logic**: The 73rd Amendment (1992) added Part IX and the 11th Schedule to the Constitution.
💡 **Exam Fact**: Madhya Pradesh was the first state to implement this amendment.
🧠 **Memory Tip**: 73-P (Panchayat), 74-M (Municipality).
🚫 **Scam Alert**: The 74th Amendment deals specifically with Urban Local Bodies.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d23cb0d7-c6ff-4f70-9c08-cfd716175b03', '6abaf652-ef39-468b-a88a-be12bdb55484', 'किस संशोधन ने ''संपत्ति के अधिकार'' को मौलिक अधिकारों की सूची से हटा दिया?', '[{"id":"A","text":"24वां संशोधन","text_en":"24वां संशोधन"},{"id":"B","text":"42वां संशोधन","text_en":"42वां संशोधन"},{"id":"C","text":"44वां संशोधन","text_en":"44वां संशोधन"},{"id":"D","text":"52वां संशोधन","text_en":"52वां संशोधन"}]', '2', '✅ **Correct Logic**: 44वें संशोधन (1978) ने अनुच्छेद 31 को हटा दिया और संपत्ति के अधिकार को अनुच्छेद 300A के तहत एक कानूनी अधिकार बना दिया।
💡 **Exam Fact**: यह जनता पार्टी सरकार द्वारा आपातकाल के बाद किया गया था।
🧠 **Memory Tip**: 44 - Four-Four-Property door.
🚫 **Scam Alert**: यह अब ''मौलिक'' अधिकार नहीं बल्कि ''कानूनी/संवैधानिक'' अधिकार है।', 2, 0, 10, NULL, 'Which amendment removed the ''Right to Property'' from the list of Fundamental Rights?', '✅ **Correct Logic**: The 44th Amendment (1978) repealed Article 31 and made the Right to Property a legal right under Article 300A.
💡 **Exam Fact**: This was done by the Janata Party government after the Emergency.
🧠 **Memory Tip**: 4+4=8... 1978! (Year coincidence).
🚫 **Scam Alert**: It is no longer ''Fundamental''; it is now a ''Legal/Constitutional'' right.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6a4f22b9-4946-4338-aa29-806f2064274c', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'दक्षिणी दोलन सूचकांक (SOI) की गणना किन दो स्थानों के बीच वायुमंडलीय दबाव के अंतर के आधार पर की जाती है?', '[{"id":"A","text":"ताहिती और डार्विन (Tahiti and Darwin)","text_en":"ताहिती और डार्विन (Tahiti and Darwin)"},{"id":"B","text":"पेरू और इंडोनेशिया (Peru and Indonesia)","text_en":"पेरू और इंडोनेशिया (Peru and Indonesia)"},{"id":"C","text":"सिडनी और मुंबई (Sydney and Mumbai)","text_en":"सिडनी और मुंबई (Sydney and Mumbai)"},{"id":"D","text":"केप टाउन और मेलबर्न (Cape Town and Melbourne)","text_en":"केप टाउन और मेलबर्न (Cape Town and Melbourne)"}]', '0', '**✅ Correct Logic:** SOI की गणना **ताहिती** (मध्य/पूर्वी प्रशांत) और **डार्विन** (ऑस्ट्रेलिया/पश्चिमी प्रशांत) के बीच समुद्र तल के दबाव (SLP) के अंतर से की जाती है। यह अल-नीनो और ला-नीना की तीव्रता को मापता है।

**💡 Exam Fact:** नकारात्मक SOI (Negative SOI) अल-नीनो को दर्शाता है।

**🧠 Memory Tip:** **TD** Bank checks your Balance (Pressure). **T**ahiti - **D**arwin.

**🚫 Scam Alert:** पेरू और इंडोनेशिया प्रभावित क्षेत्र हैं, लेकिन गणना के लिए ''ताहिती और डार्विन'' के स्टेशनों का उपयोग होता है।', 2, 0, 1, NULL, 'The Southern Oscillation Index (SOI) is calculated based on the difference in atmospheric pressure between which two places?', '**✅ Correct Logic:** SOI is calculated using the Sea Level Pressure (SLP) difference between **Tahiti** and **Darwin**. It measures the intensity of El Nino/La Nina.

**💡 Exam Fact:** Negative SOI indicates El Nino.

**🧠 Memory Tip:** **TD** (Tahiti-Darwin).

**🚫 Scam Alert:** Peru/Indonesia are affected areas, but calculation uses Tahiti/Darwin stations.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c72b18a2-8c1f-4cd3-82be-efc514968cb5', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'सर गिल्बर्ट वॉकर (Gilbert Walker) ने 1920 के दशक में ''दक्षिणी दोलन'' की खोज की थी। उस समय वे किस पद पर थे?', '[{"id":"A","text":"विश्व मौसम विज्ञान संगठन के प्रमुख","text_en":"विश्व मौसम विज्ञान संगठन के प्रमुख"},{"id":"B","text":"महानिदेशक, भारत मौसम विज्ञान विभाग (DG, IMD)","text_en":"महानिदेशक, भारत मौसम विज्ञान विभाग (DG, IMD)"},{"id":"C","text":"नासा के प्रमुख वैज्ञानिक","text_en":"नासा के प्रमुख वैज्ञानिक"},{"id":"D","text":"ऑक्सफोर्ड यूनिवर्सिटी के प्रोफेसर","text_en":"ऑक्सफोर्ड यूनिवर्सिटी के प्रोफेसर"}]', '1', '**✅ Correct Logic:** सर गिल्बर्ट वॉकर **भारत मौसम विज्ञान विभाग (IMD)** के महानिदेशक (1904-1924) थे। वे भारतीय मानसून की विफलता के कारणों की खोज कर रहे थे जब उन्होंने इस वैश्विक दोलन को पाया।

**💡 Exam Fact:** ''वॉकर सेल'' (Walker Cell) का नाम उन्हीं के सम्मान में रखा गया है।

**🧠 Memory Tip:** Walker walked in **India** to find Monsoon reasons.

**🚫 Scam Alert:** यह खोज भारत में काम करते हुए हुई थी, न कि यूरोप या अमेरिका में।', 2, 0, 2, NULL, 'Sir Gilbert Walker discovered ''Southern Oscillation'' in the 1920s. What position did he hold at that time?', '**✅ Correct Logic:** Sir Gilbert Walker was the **Director General of IMD** (India Meteorological Department). He discovered this while searching for causes of Indian Monsoon failure.

**💡 Exam Fact:** ''Walker Cell'' is named after him.

**🧠 Memory Tip:** Walker walked in **India**.

**🚫 Scam Alert:** Discovery made while working in India.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7de14d45-6b92-4ee9-b2c9-8005c7090870', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'जब दक्षिणी दोलन सूचकांक (SOI) ''नकारात्मक'' (Negative) होता है, तो इसका क्या अर्थ है?', '[{"id":"A","text":"ला-नीना स्थिति (La Nina condition)","text_en":"ला-नीना स्थिति (La Nina condition)"},{"id":"B","text":"अल-नीनो स्थिति (El Nino condition)","text_en":"अल-नीनो स्थिति (El Nino condition)"},{"id":"C","text":"तटस्थ स्थिति (Neutral condition)","text_en":"तटस्थ स्थिति (Neutral condition)"},{"id":"D","text":"हिंद महासागर डाइपोल (IOD)","text_en":"हिंद महासागर डाइपोल (IOD)"}]', '1', '**✅ Correct Logic:** **नकारात्मक SOI** का मतलब है कि ताहिती (पूर्व) में दबाव कम और डार्विन (पश्चिम) में दबाव अधिक है। यह **अल-नीनो** (El Nino) की स्थिति है, जो भारत में सूखे का कारण बन सकती है।

**💡 Exam Fact:** सकारात्मक SOI (Positive SOI) = ला-नीना (अच्छी बारिश)।

**🧠 Memory Tip:** **N**egative news for India (Drought) = **El Nino**.

**🚫 Scam Alert:** पॉजिटिव ला-नीना है, नेगेटिव अल-नीनो है। उल्टा मत करना।', 2, 0, 3, NULL, 'When the Southern Oscillation Index (SOI) is ''Negative'', what does it imply?', '**✅ Correct Logic:** **Negative SOI** means Lower pressure at Tahiti and Higher at Darwin. This indicates **El Nino**, often causing drought in India.

**💡 Exam Fact:** Positive SOI = La Nina.

**🧠 Memory Tip:** **N**egative = **N**o Rain (El Nino).

**🚫 Scam Alert:** Positive is La Nina, Negative is El Nino.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1efd6912-6ec8-4dc1-b44d-58d31d4f8001', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'दक्षिणी दोलन (Southern Oscillation) और अल-नीनो (El Nino) के संयुक्त प्रभाव को क्या कहा जाता है?', '[{"id":"A","text":"ENSO","text_en":"ENSO"},{"id":"B","text":"IOD","text_en":"IOD"},{"id":"C","text":"MJO","text_en":"MJO"},{"id":"D","text":"ITCZ","text_en":"ITCZ"}]', '0', '**✅ Correct Logic:** इसे **ENSO** (El Nino Southern Oscillation) कहा जाता है। अल-नीनो महासागरीय घटक (Oceanic component) है और दक्षिणी दोलन वायुमंडलीय घटक (Atmospheric component) है।

**💡 Exam Fact:** ENSO का चक्र 2 से 7 साल का होता है।

**🧠 Memory Tip:** **E**l **N**ino + **S**outhern **O**scillation = **ENSO**.

**🚫 Scam Alert:** IOD हिंद महासागर का है। ENSO प्रशांत का है।', 2, 0, 4, NULL, 'What is the combined effect of Southern Oscillation and El Nino called?', '**✅ Correct Logic:** It is called **ENSO**. El Nino is the Oceanic component, Southern Oscillation is the Atmospheric component.

**💡 Exam Fact:** ENSO cycle is 2-7 years.

**🧠 Memory Tip:** **E**l **N**ino + **S**outhern **O**scillation = **ENSO**.

**🚫 Scam Alert:** IOD is Indian Ocean. ENSO is Pacific.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('530fe8ca-a51c-4284-8a8c-5d05000b9196', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'दक्षिणी दोलन का संबंध मुख्य रूप से किस महासागर बेसिन में वायुदाब परिवर्तन से है?', '[{"id":"A","text":"अटलांटिक महासागर (Atlantic Ocean)","text_en":"अटलांटिक महासागर (Atlantic Ocean)"},{"id":"B","text":"प्रशांत महासागर (Pacific Ocean)","text_en":"प्रशांत महासागर (Pacific Ocean)"},{"id":"C","text":"हिंद महासागर (Indian Ocean)","text_en":"हिंद महासागर (Indian Ocean)"},{"id":"D","text":"आर्कटिक महासागर (Arctic Ocean)","text_en":"आर्कटिक महासागर (Arctic Ocean)"}]', '1', '**✅ Correct Logic:** दक्षिणी दोलन उष्णकटिबंधीय **प्रशांत महासागर** (Tropical Pacific) के पूर्वी और पश्चिमी छोरों के बीच वायुमंडलीय दबाव का उतार-चढ़ाव है।

**💡 Exam Fact:** हालांकि इसका प्रभाव वैश्विक (Global) होता है, लेकिन मूल घटना प्रशांत महासागर में होती है।

**🧠 Memory Tip:** **P**acific **P**ressure oscillation.

**🚫 Scam Alert:** यह हिंद महासागर को प्रभावित करता है, लेकिन घटना ''प्रशांत'' की है।', 2, 0, 5, NULL, 'Southern Oscillation is primarily related to pressure changes in which ocean basin?', '**✅ Correct Logic:** Southern Oscillation is the fluctuation of atmospheric pressure between the East and West tropical **Pacific Ocean**.

**💡 Exam Fact:** Impact is global, but origin is Pacific.

**🧠 Memory Tip:** **P**acific **P**ressure.

**🚫 Scam Alert:** Affects Indian Ocean, but originates in Pacific.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5aca195d-b327-4fcf-8bf3-c81fc5ea5991', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'ENSO तटस्थ (Neutral) स्थिति के दौरान, पश्चिमी प्रशांत (इंडोनेशिया/ऑस्ट्रेलिया) में दबाव कैसा होता है?', '[{"id":"A","text":"उच्च दबाव (High Pressure)","text_en":"उच्च दबाव (High Pressure)"},{"id":"B","text":"निम्न दबाव (Low Pressure)","text_en":"निम्न दबाव (Low Pressure)"},{"id":"C","text":"शून्य दबाव (Zero Pressure)","text_en":"शून्य दबाव (Zero Pressure)"},{"id":"D","text":"अत्यधिक उतार-चढ़ाव (Extreme fluctuation)","text_en":"अत्यधिक उतार-चढ़ाव (Extreme fluctuation)"}]', '1', '**✅ Correct Logic:** सामान्य (Neutral) स्थिति में, पश्चिमी प्रशांत (गर्म पानी का पूल) में **निम्न दबाव** (Low Pressure) होता है, जिससे वहाँ हवा ऊपर उठती है और बारिश होती है। (डार्विन में लो प्रेशर, ताहिती में हाई प्रेशर)।

**💡 Exam Fact:** अल-नीनो में यह बदल जाता है (डार्विन में हाई प्रेशर हो जाता है = सूखा)।

**🧠 Memory Tip:** Normal days -> Rain in Indonesia -> **Low** Pressure.

**🚫 Scam Alert:** अल-नीनो में हाई प्रेशर होता है, लेकिन प्रश्न ''तटस्थ'' (Normal) स्थिति पूछ रहा है।', 2, 0, 6, NULL, 'During ENSO Neutral conditions, how is the pressure in the Western Pacific (Indonesia/Australia)?', '**✅ Correct Logic:** Under Neutral conditions, Western Pacific has **Low Pressure** (Warm pool), causing rising air and rain. (Darwin Low, Tahiti High).

**💡 Exam Fact:** In El Nino, this reverses (Darwin High = Drought).

**🧠 Memory Tip:** Normal -> Rain in Indonesia -> **Low** Pressure.

**🚫 Scam Alert:** High Pressure happens in El Nino. Question asks Neutral.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5f7e8795-716d-4972-9a10-fde71dd82ab1', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'मैडेन-जूलियन ऑसिलेशन (MJO) और दक्षिणी दोलन (SO) में मुख्य अंतर क्या है?', '[{"id":"A","text":"MJO एक स्थायी घटना है, SO चलती-फिरती है","text_en":"MJO एक स्थायी घटना है, SO चलती-फिरती है"},{"id":"B","text":"MJO एक पूर्व की ओर बढ़ने वाली (Moving) लहर है, जबकि SO एक स्थायी ''सी-सॉ'' (Standing pattern) पैटर्न है","text_en":"MJO एक पूर्व की ओर बढ़ने वाली (Moving) लहर है, जबकि SO एक स्थायी ''सी-सॉ'' (Standing pattern) पैटर्न है"},{"id":"C","text":"MJO केवल अटलांटिक में होता है","text_en":"MJO केवल अटलांटिक में होता है"},{"id":"D","text":"SO का मानसून पर कोई प्रभाव नहीं पड़ता","text_en":"SO का मानसून पर कोई प्रभाव नहीं पड़ता"}]', '1', '**✅ Correct Logic:** **MJO** एक **चलती-फिरती** (Eastward moving) वायुमंडलीय अशांति है जो 30-60 दिनों में पृथ्वी का चक्कर लगाती है। **SO** एक **स्थायी पैटर्न** (Standing pattern/See-saw) है जो प्रशांत महासागर में कई महीनों/सालों तक स्थिर रहता है।

**💡 Exam Fact:** MJO ''इंट्रा-सीजनल'' (एक मौसम के भीतर) है, SO ''इंटर-एनुअल'' (सालों के बीच) है।

**🧠 Memory Tip:** **M**JO is **M**oving (Travelling pulse). SO is Sitting (See-saw).

**🚫 Scam Alert:** दोनों मानसून को प्रभावित करते हैं, लेकिन उनकी समय सीमा (Time scale) और गति (Movement) अलग है।', 2, 0, 7, NULL, 'What is the main difference between Madden-Julian Oscillation (MJO) and Southern Oscillation (SO)?', '**✅ Correct Logic:** **MJO** is a **Moving** wave (traverses globe in 30-60 days). **SO** is a **Standing/See-saw** pattern fixed in Pacific for months/years.

**💡 Exam Fact:** MJO is Intra-seasonal; SO is Inter-annual.

**🧠 Memory Tip:** **M**JO is **M**oving.

**🚫 Scam Alert:** Both affect monsoon, but timescales differ.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('483957f1-1267-42cc-8f08-e37721c61f71', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'दक्षिणी दोलन के संदर्भ में ''टेलीकनेक्शन'' (Teleconnection) का क्या अर्थ है?', '[{"id":"A","text":"टेलीफोन के माध्यम से मौसम की जानकारी देना","text_en":"टेलीफोन के माध्यम से मौसम की जानकारी देना"},{"id":"B","text":"दूरस्थ स्थानों की मौसम घटनाओं के बीच संबंध (Linkage between weather events of distant places)","text_en":"दूरस्थ स्थानों की मौसम घटनाओं के बीच संबंध (Linkage between weather events of distant places)"},{"id":"C","text":"उपग्रह द्वारा मौसम की निगरानी","text_en":"उपग्रह द्वारा मौसम की निगरानी"},{"id":"D","text":"समुद्र के नीचे केबल नेटवर्क","text_en":"समुद्र के नीचे केबल नेटवर्क"}]', '1', '**✅ Correct Logic:** **टेलीकनेक्शन** का अर्थ है कि एक स्थान (जैसे पेरू तट) पर होने वाली घटना हजारों किलोमीटर दूर (जैसे भारतीय मानसून) को प्रभावित करती है। ENSO दुनिया का सबसे प्रमुख टेलीकनेक्शन है।

**💡 Exam Fact:** सर गिल्बर्ट वॉकर ने सबसे पहले इस अवधारणा का प्रस्ताव दिया था।

**🧠 Memory Tip:** **Tele** (Far) + **Connection** = Connection between far away places.

**🚫 Scam Alert:** यह कोई तकनीकी संचार (Telephone) नहीं है, यह जलवायु संबंध है।', 2, 0, 8, NULL, 'What does ''Teleconnection'' mean in the context of Southern Oscillation?', '**✅ Correct Logic:** **Teleconnection** refers to the linkage between weather anomalies at widely separated locations (e.g., Peru coast affecting Indian Monsoon).

**💡 Exam Fact:** Gilbert Walker proposed this concept.

**🧠 Memory Tip:** **Tele** (Far) + **Connection**.

**🚫 Scam Alert:** Not telephone/satellite. It''s climate linkage.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5f07a4b8-4868-42fa-84c6-13c021e91d41', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'दक्षिणी दोलन का भारतीय कृषि पर क्या प्रभाव पड़ सकता है?', '[{"id":"A","text":"केवल खरीफ फसल प्रभावित होती है","text_en":"केवल खरीफ फसल प्रभावित होती है"},{"id":"B","text":"केवल रबी फसल प्रभावित होती है","text_en":"केवल रबी फसल प्रभावित होती है"},{"id":"C","text":"नकारात्मक चरण (El Nino) में सूखे के कारण उत्पादन गिर सकता है","text_en":"नकारात्मक चरण (El Nino) में सूखे के कारण उत्पादन गिर सकता है"},{"id":"D","text":"इसका कोई प्रभाव नहीं है","text_en":"इसका कोई प्रभाव नहीं है"}]', '2', '**✅ Correct Logic:** यदि दक्षिणी दोलन **नकारात्मक चरण** (El Nino) में है, तो मानसून कमजोर हो सकता है, जिससे **सूखा** पड़ता है और कृषि उत्पादन (विशेषकर खरीफ/मानसून फसलें जैसे चावल, सोयाबीन) गिर जाता है।

**💡 Exam Fact:** भारतीय कृषि को ''मानसून का जुआ'' (Gamble of Monsoon) कहा जाता है।

**🧠 Memory Tip:** Negative SO -> Negative Crop.

**🚫 Scam Alert:** रबी भी प्रभावित हो सकती है (जल स्तर कम होने से), लेकिन खरीफ पर सीधा असर होता है।', 2, 0, 9, NULL, 'What can be the impact of Southern Oscillation on Indian Agriculture?', '**✅ Correct Logic:** If SO is in **Negative phase** (El Nino), monsoon weakens, leading to **drought** and drop in production (especially Kharif crops).

**💡 Exam Fact:** Indian agri is ''Gamble of Monsoon''.

**🧠 Memory Tip:** Negative SO -> Negative Crop.

**🚫 Scam Alert:** Directly hits Kharif, indirectly hits Rabi.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3e91f1ab-5b1e-4bc8-bffb-2846665db184', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'निम्नलिखित वायुमंडलीय स्थितियों को उनके दबाव पैटर्न से सुमेलित करें (Match the atmospheric conditions with their pressure pattern):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **अल-नीनो**: दबाव पैटर्न उलट जाता है (ताहिती Low, डार्विन High)। -> (1)-(a)
* **ला-नीना**: सामान्य पैटर्न तीव्र हो जाता है (ताहिती High, डार्विन Low)। -> (2)-(b)
* **पॉजिटिव SOI**: ला-नीना से जुड़ा है, भारत के लिए अच्छा है। -> (3)-(c)
* **नेगेटिव SOI**: अल-नीनो से जुड़ा है, भारत के लिए बुरा है। -> (4)-(d)

**💡 Exam Fact:** SOI की गणना (Tahiti Pressure - Darwin Pressure) से होती है।

**🧠 Memory Tip:** **Positive** is Good (Rain). **Negative** is Bad (Drought).

**🚫 Scam Alert:** दबाव स्थानों को याद रखें: ताहिती (पूर्व), डार्विन (पश्चिम)।', 2, 0, 10, NULL, 'Match the atmospheric conditions with their pressure pattern:', '**✅ Correct Matching:**
* **El Nino**: Pattern reverses (Tahiti Low). -> (1)-(a)
* **La Nina**: Normal intensifies (Tahiti High). -> (2)-(b)
* **Positive SOI**: Good for Monsoon. -> (3)-(c)
* **Negative SOI**: Bad/Drought. -> (4)-(d)

**💡 Exam Fact:** SOI = P(Tahiti) - P(Darwin).

**🧠 Memory Tip:** **Positive** is Good. **Negative** is Bad.

**🚫 Scam Alert:** Remember locations: Tahiti (East), Darwin (West).', 60, 'matching', '[{"id":"(1)","label":"अल-नीनो (El Nino)","match":"ताहिती में कम दबाव, डार्विन में उच्च दबाव (Tahiti Low, Darwin High)","matchId":"(a)"},{"id":"(2)","label":"ला-नीना (La Nina)","match":"ताहिती में बहुत उच्च दबाव, डार्विन में बहुत कम दबाव (Tahiti Very High, Darwin Very Low)","matchId":"(b)"},{"id":"(3)","label":"सकारात्मक SOI (Positive SOI)","match":"अच्छे भारतीय मानसून का संकेत (Sign of Good Monsoon)","matchId":"(c)"},{"id":"(4)","label":"नकारात्मक SOI (Negative SOI)","match":"सूखे का संकेत (Sign of Drought)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d9be11a1-8f0f-48a3-9e1b-37c0f778d90c', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'IPCC की छठी आकलन रिपोर्ट (AR6) के अनुसार, यदि तापमान 1.5°C से अधिक बढ़ता है, तो हिमालय के ग्लेशियरों पर क्या प्रभाव पड़ेगा?', '[{"id":"A","text":"उनका विस्तार होगा","text_en":"उनका विस्तार होगा"},{"id":"B","text":"शुरुआत में पिघलने से बाढ़ आएगी, बाद में नदियाँ सूख जाएंगी (Initially floods due to melting, later rivers will dry)","text_en":"शुरुआत में पिघलने से बाढ़ आएगी, बाद में नदियाँ सूख जाएंगी (Initially floods due to melting, later rivers will dry)"},{"id":"C","text":"कोई प्रभाव नहीं पड़ेगा","text_en":"कोई प्रभाव नहीं पड़ेगा"},{"id":"D","text":"वे स्थिर हो जाएंगे","text_en":"वे स्थिर हो जाएंगे"}]', '1', '**✅ Correct Logic:** ग्लोबल वार्मिंग से ग्लेशियर तेजी से पिघलेंगे। अल्पावधि (Short term) में पिघला हुआ पानी नदियों में **बाढ़** लाएगा, लेकिन दीर्घावधि (Long term) में जब ग्लेशियर खत्म हो जाएंगे, तो गंगा/यमुना जैसी नदियाँ **मौसमी** हो जाएंगी या सूख जाएंगी।

**💡 Exam Fact:** इसे ''हिंदू कुश हिमालय'' (HKH) संकट कहा जा रहा है।

**🧠 Memory Tip:** Ice cream melts -> Messy liquid first -> Then empty stick.

**🚫 Scam Alert:** ''नदियाँ हमेशा भरी रहेंगी'' यह गलत धारणा है। पिघलने के बाद स्रोत खत्म हो जाएगा।', 2, 0, 1, NULL, 'According to IPCC AR6, what will be the impact on Himalayan glaciers if temperature rises above 1.5°C?', '**✅ Correct Logic:** Rapid melting will cause **Floods** initially. Later, as glaciers shrink/vanish, perennial rivers will become **seasonal/dry**.

**💡 Exam Fact:** Called the Hindu Kush Himalaya (HKH) crisis.

**🧠 Memory Tip:** Melt -> Flood -> Dry.

**🚫 Scam Alert:** Source will eventually deplete.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('39c7b819-34b9-4b85-b151-a7cc0f3567c4', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'समुद्र स्तर में वृद्धि (Sea Level Rise) का भारत के किस तटीय राज्य पर सबसे विनाशकारी प्रभाव पड़ने की आशंका है?', '[{"id":"A","text":"पश्चिम बंगाल (West Bengal)","text_en":"पश्चिम बंगाल (West Bengal)"},{"id":"B","text":"महाराष्ट्र (Maharashtra)","text_en":"महाराष्ट्र (Maharashtra)"},{"id":"C","text":"गुजरात (Gujarat)","text_en":"गुजरात (Gujarat)"},{"id":"D","text":"कर्नाटक (Karnataka)","text_en":"कर्नाटक (Karnataka)"}]', '0', '**✅ Correct Logic:** **पश्चिम बंगाल** (विशेषकर सुंदरबन क्षेत्र) सबसे अधिक खतरे में है। सुंदरबन का एक बड़ा हिस्सा पहले ही डूब चुका है (लोहाचारा द्वीप)। यहाँ की जमीन नीची है और डेल्टा धंस रहा है।

**💡 Exam Fact:** मुंबई भी खतरे में है, लेकिन सुंदरबन का अस्तित्व ही संकट में है।

**🧠 Memory Tip:** **Bengal** is flat and low -> Water comes in easily.

**🚫 Scam Alert:** सभी तटीय राज्य प्रभावित होंगे, लेकिन बंगाल की संवेदनशीलता (Vulnerability) सबसे अधिक है।', 2, 0, 2, NULL, 'Which coastal state of India is feared to face the most devastating impact of Sea Level Rise?', '**✅ Correct Logic:** **West Bengal** (Sundarbans) is most vulnerable. Islands like Lohachara have already submerged. Low lying delta.

**💡 Exam Fact:** Mumbai is also at risk, but Sundarbans faces existential threat.

**🧠 Memory Tip:** **Bengal** is flat -> Floods.

**🚫 Scam Alert:** All coasts affected, but Bengal is ground zero.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('304c071a-d1b0-41a9-ab96-787ecf859df6', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'जलवायु परिवर्तन के कारण ''कोरल ब्लीचिंग'' (Coral Bleaching) की घटनाएँ बढ़ रही हैं। इसका मुख्य कारण क्या है?', '[{"id":"A","text":"समुद्र के तापमान में वृद्धि (Rise in Sea Temperature)","text_en":"समुद्र के तापमान में वृद्धि (Rise in Sea Temperature)"},{"id":"B","text":"समुद्र में प्लास्टिक प्रदूषण","text_en":"समुद्र में प्लास्टिक प्रदूषण"},{"id":"C","text":"मछली पकड़ना","text_en":"मछली पकड़ना"},{"id":"D","text":"सुनामी","text_en":"सुनामी"}]', '0', '**✅ Correct Logic:** जब **समुद्र का पानी बहुत गर्म** (Heat Stress) हो जाता है, तो कोरल (प्रवाल) अपने अंदर रहने वाले रंगीन शैवाल (Zooxanthellae) को बाहर निकाल देते हैं, जिससे वे सफेद (Bleached) हो जाते हैं और मर सकते हैं।

**💡 Exam Fact:** लक्षद्वीप और अंडमान में बड़े पैमाने पर ब्लीचिंग देखी गई है।

**🧠 Memory Tip:** Hot water acts like **Bleach** on corals.

**🚫 Scam Alert:** प्रदूषण भी कारण है, लेकिन ''जलवायु परिवर्तन'' के संदर्भ में तापमान वृद्धि मुख्य है।', 2, 0, 3, NULL, 'Coral Bleaching events are increasing due to climate change. What is the main cause?', '**✅ Correct Logic:** When **Sea Temp rises**, corals expel the algae (Zooxanthellae) living in them, turning white (**Bleached**).

**💡 Exam Fact:** Massive bleaching in Lakshadweep.

**🧠 Memory Tip:** Hot water = **Bleach**.

**🚫 Scam Alert:** Pollution matters, but Temp is the Climate Change driver.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6788d5a9-35ec-4762-b4a5-5b7710962dbc', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', '''शहरी हीट आइलैंड'' (Urban Heat Island) प्रभाव, जो जलवायु परिवर्तन से और खराब हो रहा है, का क्या अर्थ है?', '[{"id":"A","text":"शहरों का तापमान आसपास के ग्रामीण क्षेत्रों से अधिक होना (Cities being warmer than surrounding rural areas)","text_en":"शहरों का तापमान आसपास के ग्रामीण क्षेत्रों से अधिक होना (Cities being warmer than surrounding rural areas)"},{"id":"B","text":"शहरों में द्वीपों का निर्माण","text_en":"शहरों में द्वीपों का निर्माण"},{"id":"C","text":"शहरों में अधिक बारिश होना","text_en":"शहरों में अधिक बारिश होना"},{"id":"D","text":"शहरों में AC का उपयोग कम होना","text_en":"शहरों में AC का उपयोग कम होना"}]', '0', '**✅ Correct Logic:** कंक्रीट, डामर और हरियाली की कमी के कारण शहर गर्मी को सोख लेते हैं, जिससे वे रात में ठंडे नहीं हो पाते। इससे शहर **ग्रामीण क्षेत्रों की तुलना में काफी गर्म** हो जाते हैं।

**💡 Exam Fact:** दिल्ली और मुंबई क्लासिक हीट आइलैंड हैं।

**🧠 Memory Tip:** City is an **Island of Heat** in a sea of cool villages.

**🚫 Scam Alert:** यह कोई वास्तविक द्वीप नहीं है, यह तापमान का गुब्बारा है।', 2, 0, 4, NULL, 'What does ''Urban Heat Island'' effect, worsened by climate change, mean?', '**✅ Correct Logic:** Cities absorb heat due to concrete/asphalt and lack of trees. Thus, **Cities are warmer than surrounding rural areas**.

**💡 Exam Fact:** Delhi/Mumbai are examples.

**🧠 Memory Tip:** **Island of Heat**.

**🚫 Scam Alert:** Not a real island.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('44c115dd-306f-467d-9f7c-7ea1f96ab8ca', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'जलवायु परिवर्तन का भारतीय कृषि पर क्या प्रभाव पड़ने की संभावना है?', '[{"id":"A","text":"फसल की पैदावार बढ़ेगी","text_en":"फसल की पैदावार बढ़ेगी"},{"id":"B","text":"गेहूं जैसी रबी फसलों का उत्पादन गिरेगा (Production of Rabi crops like Wheat will fall)","text_en":"गेहूं जैसी रबी फसलों का उत्पादन गिरेगा (Production of Rabi crops like Wheat will fall)"},{"id":"C","text":"मानसून अधिक नियमित हो जाएगा","text_en":"मानसून अधिक नियमित हो जाएगा"},{"id":"D","text":"कीटों का हमला कम होगा","text_en":"कीटों का हमला कम होगा"}]', '1', '**✅ Correct Logic:** तापमान बढ़ने से **गेहूं** (जो ठंड पसंद करता है) की पैदावार में भारी गिरावट आएगी। साथ ही, मानसून अनियमित होगा और नए कीट/रोग (Pests) आएंगे।

**💡 Exam Fact:** IPCC का अनुमान है कि दक्षिण एशिया में फसल उत्पादन 10-30% गिर सकता है।

**🧠 Memory Tip:** Wheat hates **Heat**.

**🚫 Scam Alert:** CO2 बढ़ने से कुछ फसलों को फायदा हो सकता है (Fertilization effect), लेकिन गर्मी का नुकसान उससे कहीं ज्यादा है।', 2, 0, 5, NULL, 'What is the likely impact of Climate Change on Indian Agriculture?', '**✅ Correct Logic:** Rising temp will drastically reduce **Wheat** yield (needs cold). Monsoon will become erratic. Pests will increase.

**💡 Exam Fact:** IPCC predicts 10-30% drop in South Asia.

**🧠 Memory Tip:** Wheat hates **Heat**.

**🚫 Scam Alert:** CO2 fertilization is minor compared to heat damage.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f65dda80-7bda-44f3-b629-bbf0a441cd79', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'भारत ने COP26 (ग्लासगो) में 2070 तक किस लक्ष्य को प्राप्त करने की घोषणा की है?', '[{"id":"A","text":"विकसित राष्ट्र बनना","text_en":"विकसित राष्ट्र बनना"},{"id":"B","text":"नेट जीरो उत्सर्जन (Net Zero Emissions)","text_en":"नेट जीरो उत्सर्जन (Net Zero Emissions)"},{"id":"C","text":"प्लास्टिक मुक्त भारत","text_en":"प्लास्टिक मुक्त भारत"},{"id":"D","text":"100% साक्षरता","text_en":"100% साक्षरता"}]', '1', '**✅ Correct Logic:** पीएम मोदी ने ''पंचामृत'' रणनीति के तहत **2070** तक **नेट जीरो** (कार्बन तटस्थता) हासिल करने का लक्ष्य रखा है।

**💡 Exam Fact:** 2030 तक 500 GW गैर-जीवाश्म ऊर्जा का लक्ष्य भी इसमें शामिल है।

**🧠 Memory Tip:** **Zero** in 207**0**.

**🚫 Scam Alert:** विकसित भारत का लक्ष्य 2047 है, नेट जीरो का 2070 है।', 2, 0, 6, NULL, 'What target has India announced to achieve by 2070 at COP26 (Glasgow)?', '**✅ Correct Logic:** Target to achieve **Net Zero Emissions** by **2070** (Panchamrit strategy).

**💡 Exam Fact:** Also 500 GW non-fossil by 2030.

**🧠 Memory Tip:** **Zero** in 207**0**.

**🚫 Scam Alert:** Developed India is 2047. Net Zero is 2070.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dd9b48f7-0af0-4e0d-8144-50218426740e', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'जलवायु परिवर्तन के कारण ''वेक्टर जनित रोगों'' (Vector-borne diseases) पर क्या प्रभाव पड़ेगा?', '[{"id":"A","text":"वे कम हो जाएंगे","text_en":"वे कम हो जाएंगे"},{"id":"B","text":"मलेरिया और डेंगू का विस्तार नए (ठंडे) क्षेत्रों में होगा (Expansion of Malaria/Dengue to new/colder areas)","text_en":"मलेरिया और डेंगू का विस्तार नए (ठंडे) क्षेत्रों में होगा (Expansion of Malaria/Dengue to new/colder areas)"},{"id":"C","text":"वे केवल तटीय क्षेत्रों तक सीमित रहेंगे","text_en":"वे केवल तटीय क्षेत्रों तक सीमित रहेंगे"},{"id":"D","text":"मच्छर मर जाएंगे","text_en":"मच्छर मर जाएंगे"}]', '1', '**✅ Correct Logic:** जैसे-जैसे तापमान बढ़ेगा, मच्छर (Vectors) उन पहाड़ी/ठंडे क्षेत्रों में भी पनपने लगेंगे जहाँ वे पहले नहीं रह पाते थे (जैसे हिमालयी राज्य)। इससे रोगों का **भौगोलिक विस्तार** होगा।

**💡 Exam Fact:** डेंगू और मलेरिया के सीजन की अवधि भी बढ़ जाएगी।

**🧠 Memory Tip:** Mosquitoes like it **Hot** and **Wet**.

**🚫 Scam Alert:** वे खत्म नहीं होंगे, बल्कि और फैलेंगे।', 2, 0, 7, NULL, 'What will be the impact on ''Vector-borne diseases'' due to Climate Change?', '**✅ Correct Logic:** As temps rise, mosquitoes will survive in previously cold areas (like Himalayas). Leading to **geographic expansion** of diseases like Malaria/Dengue.

**💡 Exam Fact:** Transmission season will also lengthen.

**🧠 Memory Tip:** Mosquitoes like it **Hot**.

**🚫 Scam Alert:** They won''t die; they will spread.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6bedbe86-7890-47af-a5a9-0da70a8ee606', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', '''क्लाइमेट टिपिंग पॉइंट्स'' (Climate Tipping Points) का क्या अर्थ है?', '[{"id":"A","text":"जलवायु सम्मेलनों के मुख्य बिंदु","text_en":"जलवायु सम्मेलनों के मुख्य बिंदु"},{"id":"B","text":"वह बिंदु जिसके बाद परिवर्तन अपरिवर्तनीय हो जाते हैं (Point of no return/Irreversible change)","text_en":"वह बिंदु जिसके बाद परिवर्तन अपरिवर्तनीय हो जाते हैं (Point of no return/Irreversible change)"},{"id":"C","text":"पहाड़ों की सबसे ऊंची चोटियाँ","text_en":"पहाड़ों की सबसे ऊंची चोटियाँ"},{"id":"D","text":"तापमान मापने के केंद्र","text_en":"तापमान मापने के केंद्र"}]', '1', '**✅ Correct Logic:** टिपिंग पॉइंट वह सीमा है जिसे पार करने के बाद जलवायु प्रणाली में **अपरिवर्तनीय** (Irreversible) और विनाशकारी बदलाव शुरू हो जाते हैं (जैसे अमेज़ॅन वर्षावन का सवाना में बदलना या ग्रीनलैंड की बर्फ का पूरी तरह पिघलना)।

**💡 Exam Fact:** 1.5°C और 2°C के बीच कई टिपिंग पॉइंट्स सक्रिय हो सकते हैं।

**🧠 Memory Tip:** **Tip** over the edge -> Cannot fall back -> **No Return**.

**🚫 Scam Alert:** यह कोई सम्मेलन का एजेंडा नहीं है, यह एक वैज्ञानिक सीमा (Threshold) है।', 2, 0, 8, NULL, 'What does ''Climate Tipping Points'' mean?', '**✅ Correct Logic:** Threshold beyond which changes become **Irreversible** (Point of No Return). E.g., Amazon turning into Savanna.

**💡 Exam Fact:** Risks increase between 1.5°C and 2°C.

**🧠 Memory Tip:** **Tip** over -> **No Return**.

**🚫 Scam Alert:** Not meeting points, but danger lines.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d9446dc9-b70d-4026-a2bc-d9b6b23cfad5', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'कार्बन सीक्वेस्ट्रेशन (Carbon Sequestration) जलवायु परिवर्तन को कम करने में कैसे मदद करता है?', '[{"id":"A","text":"कार्बन का उत्पादन बढ़ाकर","text_en":"कार्बन का उत्पादन बढ़ाकर"},{"id":"B","text":"वातावरण से CO2 को कैप्चर और स्टोर करके (Capturing and storing CO2 from atmosphere)","text_en":"वातावरण से CO2 को कैप्चर और स्टोर करके (Capturing and storing CO2 from atmosphere)"},{"id":"C","text":"ओजोन परत को ठीक करके","text_en":"ओजोन परत को ठीक करके"},{"id":"D","text":"प्लास्टिक को जलाकर","text_en":"प्लास्टिक को जलाकर"}]', '1', '**✅ Correct Logic:** कार्बन सीक्वेस्ट्रेशन एक प्रक्रिया है जिसमें वातावरण से कार्बन डाइऑक्साइड को **पकड़ा (Capture)** जाता है और उसे लंबे समय तक **संग्रहीत (Store)** किया जाता है (जैसे पेड़ों में, मिट्टी में, या भूमिगत चट्टानों में)।

**💡 Exam Fact:** वन और महासागर प्राकृतिक ''कार्बन सिंक'' (Sinks) हैं।

**🧠 Memory Tip:** **Sequester** means to **Hide/Lock away**.

**🚫 Scam Alert:** यह कार्बन कम नहीं करता (उत्पादन में), बल्कि जो है उसे छिपा/स्टोर कर देता है।', 2, 0, 9, NULL, 'How does Carbon Sequestration help in mitigating climate change?', '**✅ Correct Logic:** Process of **Capturing and Storing** atmospheric CO2 (in trees, soil, or underground) to reduce global warming.

**💡 Exam Fact:** Forests/Oceans are natural Carbon Sinks.

**🧠 Memory Tip:** **Sequester** = **Lock away**.

**🚫 Scam Alert:** It stores carbon, doesn''t stop production directly.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1a002b24-9756-4f9b-bd93-c997f82be524', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'निम्नलिखित पर्यावरणीय समझौतों को उनके उद्देश्य से सुमेलित करें (Match the environmental agreements with their objective):', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)","text_en":"(1)-(a), (2)-(c), (3)-(b), (4)-(d)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Matching:**
* **क्योटो**: 1997, GHG कम करने के लिए बाध्यकारी लक्ष्य। -> (1)-(a)
* **पेरिस**: 2015, ग्लोबल वार्मिंग को 2°C से नीचे रखना। -> (2)-(b)
* **मॉन्ट्रियल**: 1987, ODS (ओजोन क्षरण पदार्थ) को हटाना। सबसे सफल संधि। -> (3)-(c)
* **रामसर**: 1971, वेटलैंड्स (झीलें आदि)। -> (4)-(d)

**💡 Exam Fact:** किगाली संशोधन (Kigali Amendment) मॉन्ट्रियल प्रोटोकॉल में HFCs को कम करने के लिए जोड़ा गया (जो जलवायु परिवर्तन से भी जुड़ा है)।

**🧠 Memory Tip:** **K**yoto-**G**as. **P**aris-**T**emperature. **M**ontreal-**O**zone. **R**amsar-**W**ater.

**🚫 Scam Alert:** मॉन्ट्रियल ओजोन के लिए है, जलवायु (CO2) के लिए नहीं, हालांकि इसका जलवायु पर सकारात्मक प्रभाव पड़ा है।', 2, 0, 10, NULL, 'Match the environmental agreements with their objective:', '**✅ Correct Matching:**
* **Kyoto**: GHG reduction. -> (1)-(a)
* **Paris**: Limit Temp rise. -> (2)-(b)
* **Montreal**: Ozone. -> (3)-(c)
* **Ramsar**: Wetlands. -> (4)-(d)

**💡 Exam Fact:** Montreal is the most successful treaty.

**🧠 Memory Tip:** **M**ontreal-**O**zone.

**🚫 Scam Alert:** Don''t mix Ozone (Montreal) with Climate Change (Kyoto/Paris).', 60, 'matching', '[{"id":"(1)","label":"क्योटो प्रोटोकॉल (Kyoto Protocol)","match":"ग्रीनहाउस गैस उत्सर्जन कम करना (Reduce GHG emissions)","matchId":"(a)"},{"id":"(2)","label":"पेरिस समझौता (Paris Agreement)","match":"तापमान वृद्धि को 1.5°C/2°C तक सीमित करना (Limit temp rise)","matchId":"(b)"},{"id":"(3)","label":"मॉन्ट्रियल प्रोटोकॉल (Montreal Protocol)","match":"ओजोन परत संरक्षण (Ozone Layer Protection)","matchId":"(c)"},{"id":"(4)","label":"रामसर कन्वेंशन (Ramsar Convention)","match":"आर्द्रभूमि संरक्षण (Wetlands Conservation)","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('02923b05-3d40-4cdd-9285-3c7a798de934', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'भारतीय संविधान के किस अनुच्छेद को डॉ. बी.आर. अंबेडकर ने ''संविधान का हृदय और आत्मा'' कहा था?', '[{"id":"A","text":"अनुच्छेद 14","text_en":"अनुच्छेद 14"},{"id":"B","text":"अनुच्छेद 19","text_en":"अनुच्छेद 19"},{"id":"C","text":"अनुच्छेद 21","text_en":"अनुच्छेद 21"},{"id":"D","text":"अनुच्छेद 32","text_en":"अनुच्छेद 32"}]', '3', '✅ **Correct Logic**: अनुच्छेद 32 ''संवैधानिक उपचारों का अधिकार'' प्रदान करता है, जिसके बिना अन्य मौलिक अधिकार अर्थहीन हैं।
💡 **Exam Fact**: इसके तहत सर्वोच्च न्यायालय को 5 प्रकार की रिट (Writs) जारी करने की शक्ति है।
🧠 **Memory Tip**: 32 - ''Batti'' (Light) that protects other rights.
🚫 **Scam Alert**: ''प्रस्तावना'' को भी संविधान की आत्मा कहा जाता है, लेकिन अंबेडकर जी ने विशेष रूप से अनुच्छेद 32 के लिए यह शब्द प्रयुक्त किया था।', 2, 0, 1, NULL, 'Which Article of the Indian Constitution was called the ''Heart and Soul of the Constitution'' by Dr. B.R. Ambedkar?', '✅ **Correct Logic**: Article 32 provides the ''Right to Constitutional Remedies'', making other rights enforceable.
💡 **Exam Fact**: Under this, the Supreme Court has the power to issue 5 types of Writs.
🧠 **Memory Tip**: 32 - Think of it as the 32 teeth (Guard) of our rights.
🚫 **Scam Alert**: While the ''Preamble'' is also called the soul, Ambedkar specifically used this phrase for Article 32.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5fa6e895-9ec2-4df7-bc7a-8ec428c9810f', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'मौलिक कर्तव्यों (Fundamental Duties) को किस समिति की सिफारिश पर संविधान में जोड़ा गया था?', '[{"id":"A","text":"वर्मा समिति","text_en":"वर्मा समिति"},{"id":"B","text":"स्वर्ण सिंह समिति","text_en":"स्वर्ण सिंह समिति"},{"id":"C","text":"सरकारिया आयोग","text_en":"सरकारिया आयोग"},{"id":"D","text":"बलवंत राय मेहता समिति","text_en":"बलवंत राय मेहता समिति"}]', '1', '✅ **Correct Logic**: 42वें संशोधन (1976) द्वारा स्वर्ण सिंह समिति की सिफारिश पर 10 मौलिक कर्तव्य जोड़े गए थे।
💡 **Exam Fact**: 11वां मौलिक कर्तव्य 86वें संशोधन (2002) द्वारा जोड़ा गया था।
🧠 **Memory Tip**: Gold (Swaran) is a ''Duty'' to protect.
🚫 **Scam Alert**: बलवंत राय मेहता समिति पंचायती राज से संबंधित है, कर्तव्यों से नहीं।', 2, 0, 2, NULL, 'On the recommendation of which committee were the Fundamental Duties added to the Constitution?', '✅ **Correct Logic**: 10 Fundamental Duties were added via the 42nd Amendment (1976) based on the Swaran Singh Committee''s report.
💡 **Exam Fact**: The 11th Fundamental Duty was added by the 86th Amendment in 2002.
🧠 **Memory Tip**: Duty is as precious as Gold (Swaran).
🚫 **Scam Alert**: Balwant Rai Mehta committee is for Panchayati Raj, not duties.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('235d3a52-8c80-47a8-930c-805ed3afdb03', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'निम्नलिखित में से कौन सा अधिकार केवल भारतीय नागरिकों को प्राप्त है, विदेशियों को नहीं?', '[{"id":"A","text":"अनुच्छेद 14 (विधि के समक्ष समता)","text_en":"अनुच्छेद 14 (विधि के समक्ष समता)"},{"id":"B","text":"अनुच्छेद 21 (जीवन का अधिकार)","text_en":"अनुच्छेद 21 (जीवन का अधिकार)"},{"id":"C","text":"अनुच्छेद 15 (भेदभाव के विरुद्ध अधिकार)","text_en":"अनुच्छेद 15 (भेदभाव के विरुद्ध अधिकार)"},{"id":"D","text":"अनुच्छेद 20 (दोषसिद्धि से संरक्षण)","text_en":"अनुच्छेद 20 (दोषसिद्धि से संरक्षण)"}]', '2', '✅ **Correct Logic**: अनुच्छेद 15, 16, 19, 29 और 30 केवल भारतीय नागरिकों के लिए आरक्षित हैं।
💡 **Exam Fact**: अनुच्छेद 21 और 14 सभी व्यक्तियों (नागरिक + विदेशी) को प्राप्त हैं।
🧠 **Memory Tip**: 15, 16, 19, 29, 30 - Only for ''Us'' (Indians).
🚫 **Scam Alert**: ''जीवन का अधिकार'' (Art 21) सार्वभौमिक है, यह विदेशियों को भी मिलता है।', 2, 0, 3, NULL, 'Which of the following rights is available only to Indian citizens and not to foreigners?', '✅ **Correct Logic**: Articles 15, 16, 19, 29, and 30 are reserved exclusively for Indian citizens.
💡 **Exam Fact**: Articles 21 and 14 are available to all persons (Citizens + Aliens).
🧠 **Memory Tip**: 15, 16, 19, 29, 30 - The ''VVIP'' Indian list.
🚫 **Scam Alert**: Right to Life (Art 21) is universal; it applies to foreigners on Indian soil too.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('306923ba-65f5-4e5e-b095-9d97a3c573ef', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'निवारक निरोध (Preventive Detention) के तहत किसी व्यक्ति को बिना मुकदमे के अधिकतम कितने समय तक हिरासत में रखा जा सकता है?', '[{"id":"A","text":"1 महीना","text_en":"1 महीना"},{"id":"B","text":"3 महीने","text_en":"3 महीने"},{"id":"C","text":"6 महीने","text_en":"6 महीने"},{"id":"D","text":"24 घंटे","text_en":"24 घंटे"}]', '1', '✅ **Correct Logic**: अनुच्छेद 22 के अनुसार, बिना सलाहकार बोर्ड की अनुमति के किसी व्यक्ति को अधिकतम 3 महीने तक हिरासत में रखा जा सकता है।
💡 **Exam Fact**: यह दंडात्मक निरोध (Punitive Detention) से अलग है।
🧠 **Memory Tip**: 3 Months - Quarter of a year.
🚫 **Scam Alert**: 24 घंटे सामान्य गिरफ्तारी के लिए है (मजिस्ट्रेट के सामने पेशी), निवारक निरोध के लिए नहीं।', 2, 0, 4, NULL, 'What is the maximum period a person can be detained without trial under Preventive Detention?', '✅ **Correct Logic**: Under Article 22, a person can be detained for a maximum of 3 months unless an advisory board recommends an extension.
💡 **Exam Fact**: This is different from Punitive Detention, which happens after a crime is committed.
🧠 **Memory Tip**: 3 Months = 1 Season of detention.
🚫 **Scam Alert**: 24 hours is the limit for ordinary arrests to produce before a magistrate.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('231702db-4372-4282-b724-2e45fc50c24b', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'मौलिक अधिकारों और उनसे संबंधित अनुच्छेदों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: 17 में छुआछूत (Untouchability) निषेध, 18 में टाइटल (Titles) का अंत, 25 में अंतःकरण की स्वतंत्रता और 29 अल्पसंख्यकों की भाषा/संस्कृति संरक्षण से है।
💡 **Exam Fact**: अनुच्छेद 17 एक ''पूर्ण'' (Absolute) अधिकार है।
🧠 **Memory Tip**: 17 - ''Sattra'' (Danger for untouchability).
🚫 **Scam Alert**: शैक्षणिक संस्थानों की स्थापना का अधिकार अनुच्छेद 30 में है, 29 में केवल संरक्षण है।', 2, 0, 5, NULL, 'Match the Fundamental Rights with their respective Articles:', '✅ **Correct Logic**: 17 for Untouchability, 18 for Titles, 25 for Religious Freedom, and 29 for protection of Minority interests.
💡 **Exam Fact**: Article 17 is an absolute right; no exceptions allowed.
🧠 **Memory Tip**: 17 - Danger for discrimination.
🚫 **Scam Alert**: The right to establish educational institutions is Art 30, not 29.', 60, 'matching', '[{"id":"(1)","label":"अस्पृश्यता का अंत","match":"अनुच्छेद 17","matchId":"(a)"},{"id":"(2)","label":"उपाधियों का अंत","match":"अनुच्छेद 18","matchId":"(b)"},{"id":"(3)","label":"धार्मिक स्वतंत्रता","match":"अनुच्छेद 25","matchId":"(c)"},{"id":"(4)","label":"अल्पसंख्यकों के हित","match":"अनुच्छेद 29","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b9af31ba-8b4a-4782-b008-a9ca2f4dc4ff', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'किस मौलिक अधिकार को आपातकाल (अनुच्छेद 352) के दौरान भी निलंबित नहीं किया जा सकता?', '[{"id":"A","text":"अनुच्छेद 19 और 20","text_en":"अनुच्छेद 19 और 20"},{"id":"B","text":"अनुच्छेद 20 और 21","text_en":"अनुच्छेद 20 और 21"},{"id":"C","text":"अनुच्छेद 21 और 22","text_en":"अनुच्छेद 21 और 22"},{"id":"D","text":"अनुच्छेद 14 और 15","text_en":"अनुच्छेद 14 और 15"}]', '1', '✅ **Correct Logic**: 44वें संशोधन (1978) द्वारा यह प्रावधान किया गया कि अनुच्छेद 20 और 21 को राष्ट्रीय आपातकाल के दौरान भी निलंबित नहीं किया जा सकता।
💡 **Exam Fact**: अनुच्छेद 19 युद्ध या बाहरी आक्रमण के समय स्वतः निलंबित हो जाता है।
🧠 **Memory Tip**: 20-21: The immortal rights.
🚫 **Scam Alert**: 19 निलंबित हो सकता है, लेकिन 20 और 21 कभी नहीं।', 2, 0, 6, NULL, 'Which Fundamental Rights cannot be suspended even during an Emergency (Article 352)?', '✅ **Correct Logic**: By the 44th Amendment (1978), Articles 20 and 21 cannot be suspended even during a National Emergency.
💡 **Exam Fact**: Article 19 is automatically suspended in case of war or external aggression.
🧠 **Memory Tip**: 20-21: The rights that never sleep.
🚫 **Scam Alert**: Art 19 can be suspended, but 20 and 21 are untouchable.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3c779625-3f6f-43db-a0f2-ae67c910768a', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', '''शिक्षा का अधिकार'' (RTE) संविधान के किस अनुच्छेद के तहत एक मौलिक अधिकार है?', '[{"id":"A","text":"अनुच्छेद 21","text_en":"अनुच्छेद 21"},{"id":"B","text":"अनुच्छेद 21A","text_en":"अनुच्छेद 21A"},{"id":"C","text":"अनुच्छेद 45","text_en":"अनुच्छेद 45"},{"id":"D","text":"अनुच्छेद 51A","text_en":"अनुच्छेद 51A"}]', '1', '✅ **Correct Logic**: 86वें संशोधन (2002) द्वारा अनुच्छेद 21A जोड़कर 6 से 14 वर्ष के बच्चों के लिए शिक्षा को अनिवार्य बनाया गया।
💡 **Exam Fact**: इसे 1 अप्रैल 2010 से प्रभावी ढंग से लागू किया गया।
🧠 **Memory Tip**: 21A - ''A'' for Alphabet/Abpadhna (Education).
🚫 **Scam Alert**: अनुच्छेद 45 नीति निदेशक तत्व है, जबकि 21A मौलिक अधिकार है।', 2, 0, 7, NULL, 'Under which Article is the ''Right to Education'' (RTE) a Fundamental Right?', '✅ **Correct Logic**: Article 21A was inserted by the 86th Amendment (2002) to make education a fundamental right for children aged 6–14.
💡 **Exam Fact**: The RTE Act came into effect on April 1, 2010.
🧠 **Memory Tip**: 21A - ''A'' for Apple/Alphabet.
🚫 **Scam Alert**: Art 45 is a DPSP, but 21A is the enforceable Fundamental Right.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('064e48ba-4041-4585-b138-750a3ddb2712', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'वर्तमान में संविधान के भाग IV-A में कुल कितने मौलिक कर्तव्य वर्णित हैं?', '[{"id":"A","text":"10","text_en":"10"},{"id":"B","text":"11","text_en":"11"},{"id":"C","text":"12","text_en":"12"},{"id":"D","text":"9","text_en":"9"}]', '1', '✅ **Correct Logic**: मूल रूप से (1976 में) 10 कर्तव्य थे, लेकिन वर्तमान में कुल 11 मौलिक कर्तव्य हैं।
💡 **Exam Fact**: 11वां कर्तव्य अभिभावकों को अपने बच्चों को शिक्षा के अवसर प्रदान करने का निर्देश देता है।
🧠 **Memory Tip**: 10 + 1 (Education) = 11.
🚫 **Scam Alert**: मौलिक अधिकार 6 हैं, लेकिन कर्तव्य 11 हैं।', 2, 0, 8, NULL, 'How many Fundamental Duties are currently described in Part IV-A of the Constitution?', '✅ **Correct Logic**: Originally 10 duties were added in 1976; currently, there are 11 duties in total.
💡 **Exam Fact**: The 11th duty requires parents/guardians to provide educational opportunities to their children.
🧠 **Memory Tip**: Start with 10, add 1 for Education = 11.
🚫 **Scam Alert**: Do not confuse 6 rights with 11 duties.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('65440afb-c5d1-4248-89e0-cbee3d9830c6', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'सर्वोच्च न्यायालय द्वारा किस रिट (Writ) को ''व्यक्तिगत स्वतंत्रता का रक्षक'' (Bulwark of Personal Liberty) कहा जाता है?', '[{"id":"A","text":"परमादेश (Mandamus)","text_en":"परमादेश (Mandamus)"},{"id":"B","text":"बंदी प्रत्यक्षीकरण (Habeas Corpus)","text_en":"बंदी प्रत्यक्षीकरण (Habeas Corpus)"},{"id":"C","text":"उत्प्रेषण (Certiorari)","text_en":"उत्प्रेषण (Certiorari)"},{"id":"D","text":"अधिकार पृच्छा (Quo-Warranto)","text_en":"अधिकार पृच्छा (Quo-Warranto)"}]', '1', '✅ **Correct Logic**: ''बंदी प्रत्यक्षीकरण'' का अर्थ है ''शरीर को प्रस्तुत करना''। यह अवैध रूप से हिरासत में लिए गए व्यक्ति की रक्षा करता है।
💡 **Exam Fact**: यह रिट सार्वजनिक प्राधिकरणों और निजी व्यक्तियों दोनों के खिलाफ जारी की जा सकती है।
🧠 **Memory Tip**: Habeas Corpus - Have the Body.
🚫 **Scam Alert**: परमादेश केवल सार्वजनिक अधिकारियों के खिलाफ जारी होता है, निजी के खिलाफ नहीं।', 2, 0, 9, NULL, 'Which Writ is called the ''Bulwark of Personal Liberty'' by the Supreme Court?', '✅ **Correct Logic**: ''Habeas Corpus'' literally means ''to have the body''. It protects a person against unlawful detention.
💡 **Exam Fact**: This writ can be issued against both public authorities and private individuals.
🧠 **Memory Tip**: Habeas Corpus - Have the Body present.
🚫 **Scam Alert**: Mandamus is only against public officials, not private citizens.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('556719a5-3f88-45a3-ad24-50ff1380bd26', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'संविधान के अनुच्छेद 19 के तहत वर्तमान में कुल कितनी ''स्वतंत्रताएं'' प्रदान की गई हैं?', '[{"id":"A","text":"7","text_en":"7"},{"id":"B","text":"6","text_en":"6"},{"id":"C","text":"5","text_en":"5"},{"id":"D","text":"8","text_en":"8"}]', '1', '✅ **Correct Logic**: मूल संविधान में 7 स्वतंत्रताएं थीं, लेकिन संपत्ति की स्वतंत्रता हटने के बाद अब केवल 6 स्वतंत्रताएं (19(1)(a) से (g) तक) बची हैं।
💡 **Exam Fact**: इसमें भाषण, सभा, संघ, संचरण, निवास और व्यवसाय की स्वतंत्रता शामिल है।
🧠 **Memory Tip**: Six Senses of Freedom.
🚫 **Scam Alert**: ''संपत्ति की स्वतंत्रता'' 44वें संशोधन द्वारा हटाई गई थी, इसे वर्तमान सूची में न गिनें।', 2, 0, 10, NULL, 'How many ''Freedoms'' are currently provided under Article 19 of the Constitution?', '✅ **Correct Logic**: Originally there were 7 freedoms, but after the removal of the freedom to hold property, only 6 remain (19(1)(a) to (g)).
💡 **Exam Fact**: These include speech, assembly, association, movement, residence, and profession.
🧠 **Memory Tip**: The ''Six'' Pillars of Liberty.
🚫 **Scam Alert**: Right to property was removed by the 44th Amendment; don''t count it in the current set.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3d93d049-5e1a-42c1-8339-fde9d084100a', 'a10ad250-9d27-4869-87ed-5629145fdfa5', '''आरण्यक'' ग्रंथों का मुख्य विषय-वस्तु (Subject Matter) क्या है?', '[{"id":"A","text":"यज्ञों के कर्मकांडीय नियम (Ritualistic rules of Yajnas)","text_en":"यज्ञों के कर्मकांडीय नियम (Ritualistic rules of Yajnas)"},{"id":"B","text":"यज्ञों का दार्शनिक और प्रतीकात्मक अर्थ (Philosophical and symbolic meaning of sacrifices)","text_en":"यज्ञों का दार्शनिक और प्रतीकात्मक अर्थ (Philosophical and symbolic meaning of sacrifices)"},{"id":"C","text":"राज्य प्रशासन के नियम (Rules of state administration)","text_en":"राज्य प्रशासन के नियम (Rules of state administration)"},{"id":"D","text":"विदेशी आक्रमणों का विवरण (Account of foreign invasions)","text_en":"विदेशी आक्रमणों का विवरण (Account of foreign invasions)"}]', '1', '**✅ Correct Logic**: आरण्यक ग्रंथ ब्राह्मण ग्रंथों (कर्मकांड) और उपनिषदों (ज्ञान) के बीच की कड़ी हैं। इनमें यज्ञों के भौतिक स्वरूप के स्थान पर उनके आध्यात्मिक और प्रतीकात्मक (Symbolic) अर्थों पर जोर दिया गया है।

**💡 Exam Fact**: इन्हें ''रहस्य'' (Mystery) भी कहा जाता है क्योंकि इनका अध्ययन एकांत वनों में किया जाता था।

**🧠 Memory Tip**: **A**ranyaka = **A**lternative interpretation of rituals (Symbolism).

**🚫 Scam Alert**: यज्ञों के ''नियम'' ब्राह्मण ग्रंथों में हैं, आरण्यकों में उनका ''दर्शन'' (Philosophy) है।', 2, 0, 1, NULL, 'What is the primary subject matter of the ''Aranyaka'' texts?', '**✅ Correct Logic**: Aranyakas serve as a bridge between the ritualistic Brahmanas and the philosophical Upanishads. They focus on the spiritual and symbolic meanings of sacrifices rather than the mere physical performance.

**💡 Exam Fact**: They are often called ''Rahasya'' because they were studied in the solitude of forests.

**🧠 Memory Tip**: **A**ranyaka = **A**lternative interpretation of rituals (Symbolism).

**🚫 Scam Alert**: Don''t confuse them with Brahmanas; Brahmanas give the ''Rules'', Aranyakas provide the ''Reasoning/Symbolism''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('95fcfb19-fb3f-4294-8c41-db5b05df624a', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'निम्नलिखित में से किस वेद का कोई ''आरण्यक'' (Aranyaka) उपलब्ध नहीं है?', '[{"id":"A","text":"ऋग्वेद","text_en":"ऋग्वेद"},{"id":"B","text":"यजुर्वेद","text_en":"यजुर्वेद"},{"id":"C","text":"सामवेद","text_en":"सामवेद"},{"id":"D","text":"अथर्ववेद","text_en":"अथर्ववेद"}]', '3', '**✅ Correct Logic**: अथर्ववेद का कोई भी आरण्यक ग्रंथ उपलब्ध नहीं है। इसका केवल एक ब्राह्मण ग्रंथ ''गोपथ'' है।

**💡 Exam Fact**: ऋग्वेद के दो आरण्यक हैं—ऐतरेय और शांखायन।

**🧠 Memory Tip**: **A**tharva = **A**bsent Aranyaka.

**🚫 Scam Alert**: अक्सर छात्र सामवेद लगा देते हैं, लेकिन सामवेद के जैमिनीय और तवलकार आरण्यक प्रसिद्ध हैं।', 2, 0, 2, NULL, 'Which of the following Vedas has NO available ''Aranyaka''?', '**✅ Correct Logic**: Atharvaveda is unique because it lacks any corresponding Aranyaka text. It only possesses the Gopatha Brahmana.

**💡 Exam Fact**: Rigveda has two Aranyakas: Aitareya and Shankhayana.

**🧠 Memory Tip**: **A**tharva = **A**bsent Aranyaka.

**🚫 Scam Alert**: Students often mistakenly pick Samaveda, but Samaveda does have Aranyakas like Jaiminiya.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d8b7400e-2f10-4cac-9e3e-f5d62956defe', 'a10ad250-9d27-4869-87ed-5629145fdfa5', '''ऐतरेय आरण्यक'' किस वेद से संबंधित है?', '[{"id":"A","text":"ऋग्वेद","text_en":"ऋग्वेद"},{"id":"B","text":"सामवेद","text_en":"सामवेद"},{"id":"C","text":"यजुर्वेद","text_en":"यजुर्वेद"},{"id":"D","text":"अथर्ववेद","text_en":"अथर्ववेद"}]', '0', '**✅ Correct Logic**: ऐतरेय आरण्यक ऋग्वेद की ऐतरेय शाखा का हिस्सा है। इसमें ''महिदास ऐतरेय'' के विचार संकलित हैं।

**💡 Exam Fact**: ऐतरेय आरण्यक के अंतिम भाग को ही ऐतरेय उपनिषद कहा जाता है।

**🧠 Memory Tip**: **A**itareya starts with **A**, like the **A**di (First/Rig) Veda.

**🚫 Scam Alert**: शतपथ ब्राह्मण यजुर्वेद का है, ऐतरेय हमेशा ऋग्वेद से जुड़ा है।', 2, 0, 3, NULL, 'To which Veda does the ''Aitareya Aranyaka'' belong?', '**✅ Correct Logic**: The Aitareya Aranyaka is part of the Rigvedic tradition. It is attributed to Mahidasa Aitareya.

**💡 Exam Fact**: The latter portion of this Aranyaka constitutes the Aitareya Upanishad.

**🧠 Memory Tip**: **A**itareya starts with **A**, like the **A**di (First/Rig) Veda.

**🚫 Scam Alert**: Don''t confuse it with Satapatha (Yajurveda); Aitareya is strictly Rigvedic.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3fdadb62-9c63-49b1-a57d-d03ecc25c664', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'आरण्यक ग्रंथों को वैदिक साहित्य के किस कालक्रम में रखा जाता है?', '[{"id":"A","text":"संहिता के तुरंत बाद","text_en":"संहिता के तुरंत बाद"},{"id":"B","text":"ब्राह्मण ग्रंथों के बाद और उपनिषदों से पूर्व","text_en":"ब्राह्मण ग्रंथों के बाद और उपनिषदों से पूर्व"},{"id":"C","text":"उपनिषदों के बाद","text_en":"उपनिषदों के बाद"},{"id":"D","text":"वेदांगों के बाद","text_en":"वेदांगों के बाद"}]', '1', '**✅ Correct Logic**: वैदिक साहित्य का विकास क्रम इस प्रकार है: संहिता -> ब्राह्मण -> आरण्यक -> उपनिषद। आरण्यक ब्राह्मणों के कर्मकांड और उपनिषदों के दर्शन के बीच का संक्रमण काल है।

**💡 Exam Fact**: इन्हें प्रायः ब्राह्मण ग्रंथों के अंत में जोड़ा गया परिशिष्ट (Appendix) माना जाता है।

**🧠 Memory Tip**: **S-B-A-U** क्रम याद रखें (Samhita, Brahmana, Aranyaka, Upanishad).

**🚫 Scam Alert**: वेदांग (Vedangas) उत्तर-वैदिक काल की रचनाएं हैं, वे मुख्य श्रुति साहित्य का हिस्सा नहीं हैं।', 2, 0, 4, NULL, 'In which chronological order of Vedic literature are Aranyakas placed?', '**✅ Correct Logic**: The development of Vedic literature follows: Samhita -> Brahmana -> Aranyaka -> Upanishad. Aranyakas act as a transition phase.

**💡 Exam Fact**: They are often considered the appendices to the Brahmanas.

**🧠 Memory Tip**: Remember the **S-B-A-U** sequence (Samhita, Brahmana, Aranyaka, Upanishad).

**🚫 Scam Alert**: Vedangas are auxiliary texts and not part of the core Shruti sequence.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a2d76676-12ec-4ee4-8079-69f20824f147', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'वेदों को उनके प्रमुख आरण्यकों से सुमेलित करें (Match the Vedas with their major Aranyakas):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Logic**: 
* ऋग्वेद: ऐतरेय।
* शुक्ल यजुर्वेद: बृहदारण्यक (यह शतपथ ब्राह्मण का हिस्सा है)।
* कृष्ण यजुर्वेद: तैत्तिरीय।
* सामवेद: जैमिनीय।

**💡 Exam Fact**: बृहदारण्यक उपनिषद और आरण्यक दोनों है और यह सबसे बड़ा आरण्यक है।

**🧠 Memory Tip**: **T**aittiriya is always **T**ied to Krishna Yajurveda.

**🚫 Scam Alert**: अथर्ववेद का कोई आरण्यक नहीं है, इसलिए मिलान में उसे शामिल नहीं किया जा सकता।', 2, 0, 5, NULL, 'Match the Vedas with their major Aranyakas:', '**✅ Correct Logic**: 
* Rigveda: Aitareya.
* Shukla Yajurveda: Brihadaranyaka.
* Krishna Yajurveda: Taittiriya.
* Samaveda: Jaiminiya.

**💡 Exam Fact**: Brihadaranyaka is both an Aranyaka and an Upanishad and is the largest of its kind.

**🧠 Memory Tip**: **T**aittiriya is **T**ied to Krishna Yajurveda.

**🚫 Scam Alert**: Since Atharvaveda has no Aranyaka, it is never included in such matching tasks.', 60, 'matching', '[{"id":"(1)","label":"ऋग्वेद","match":"ऐतरेय, शांखायन","matchId":"(b)"},{"id":"(2)","label":"शुक्ल यजुर्वेद","match":"बृहदारण्यक","matchId":"(a)"},{"id":"(3)","label":"कृष्ण यजुर्वेद","match":"तैत्तिरीय, मैत्रायणी","matchId":"(d)"},{"id":"(4)","label":"सामवेद","match":"जैमिनीय, तवलकार","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('eef478c9-a275-47ae-bebb-72024a563fe6', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'आरण्यकों का नामकरण किस आधार पर हुआ है?', '[{"id":"A","text":"उनके लेखकों के नाम पर","text_en":"उनके लेखकों के नाम पर"},{"id":"B","text":"उनके गायन की शैली पर","text_en":"उनके गायन की शैली पर"},{"id":"C","text":"उनके अध्ययन के स्थान (वन) के आधार पर","text_en":"उनके अध्ययन के स्थान (वन) के आधार पर"},{"id":"D","text":"संबंधित देवताओं के नाम पर","text_en":"संबंधित देवताओं के नाम पर"}]', '2', '**✅ Correct Logic**: ''अरण्य'' का अर्थ है जंगल/वन। चूंकि इन ग्रंथों का पठन-पाठन नगरों की भीड़भाड़ से दूर वनों के एकांत में किया जाता था, इसलिए इन्हें ''आरण्यक'' कहा गया।

**💡 Exam Fact**: सायण के अनुसार, वनों में पाठ किए जाने के कारण ही इनका यह नाम पड़ा।

**🧠 Memory Tip**: **Aranya** = Forest. **Aranyaka** = Forest Books.

**🚫 Scam Alert**: कुछ के नाम ऋषियों पर भी हैं (जैसे ऐतरेय), लेकिन सामूहिक श्रेणी का नाम ''स्थान'' के आधार पर है।', 2, 0, 6, NULL, 'On what basis were the Aranyakas named?', '**✅ Correct Logic**: ''Aranya'' means forest. These texts were intended for those dwelling in the forest (Vanaprasthas), far from social noise, hence the name ''Aranyaka''.

**💡 Exam Fact**: Sayana explicitly states the name is derived from the place of study (the forest).

**🧠 Memory Tip**: **Aranya** = Forest. **Aranyaka** = Forest Books.

**🚫 Scam Alert**: While individual texts may be named after sages, the category is based on location.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b8116e10-e40f-43bb-b87b-afead1c02da6', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'वानप्रस्थ आश्रम (Vanaprastha) के दौरान मुख्य रूप से किन ग्रंथों का अध्ययन किया जाता था?', '[{"id":"A","text":"ब्राह्मण ग्रंथ","text_en":"ब्राह्मण ग्रंथ"},{"id":"B","text":"आरण्यक","text_en":"आरण्यक"},{"id":"C","text":"स्मृतियाँ","text_en":"स्मृतियाँ"},{"id":"D","text":"धर्मशास्त्र","text_en":"धर्मशास्त्र"}]', '1', '**✅ Correct Logic**: वानप्रस्थी लोग वन में रहकर आत्म-चिंतन और यज्ञों के मानसिक रूप का अभ्यास करते थे, जिसके लिए आरण्यक ग्रंथ मार्गदर्शक थे।

**💡 Exam Fact**: गृहस्थों के लिए ब्राह्मण ग्रंथ और वानप्रस्थियों के लिए आरण्यक प्रमुख थे।

**🧠 Memory Tip**: **V**anaprastha -> **A**ranya (Forest) -> **Aranyakas**.

**🚫 Scam Alert**: संन्यासियों के लिए मुख्य रूप से उपनिषद होते थे।', 2, 0, 7, NULL, 'Which texts were primarily studied during the Vanaprastha stage of life?', '**✅ Correct Logic**: Those in the Vanaprastha (forest-dweller) stage practiced contemplation and mental rituals, for which Aranyakas served as the primary manual.

**💡 Exam Fact**: Brahmanas were for householders, while Aranyakas were for forest-dwellers.

**🧠 Memory Tip**: **V**anaprastha -> **A**ranya (Forest) -> **Aranyakas**.

**🚫 Scam Alert**: Upanishads were the primary focus for Sannyasis (renunciants).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d610f766-da41-4e25-8126-e712f6132295', 'a10ad250-9d27-4869-87ed-5629145fdfa5', '''प्राण'' की महत्ता और उसकी दार्शनिक व्याख्या किस आरण्यक की मुख्य विशेषता है?', '[{"id":"A","text":"ऐतरेय आरण्यक","text_en":"ऐतरेय आरण्यक"},{"id":"B","text":"बृहदारण्यक","text_en":"बृहदारण्यक"},{"id":"C","text":"जैमिनीय आरण्यक","text_en":"जैमिनीय आरण्यक"},{"id":"D","text":"तवलकार आरण्यक","text_en":"तवलकार आरण्यक"}]', '0', '**✅ Correct Logic**: ऐतरेय आरण्यक में प्राण (Life-breath) को ब्रह्मांड का मूल आधार मानकर उसकी विस्तृत आध्यात्मिक व्याख्या की गई है।

**💡 Exam Fact**: इसमें ''महाव्रत'' संस्कार के रहस्यों का भी वर्णन है।

**🧠 Memory Tip**: **A**itareya = **A**ir (Prana/Breath).

**🚫 Scam Alert**: बृहदारण्यक में भी चर्चा है, लेकिन ''प्राण विद्या'' का व्यवस्थित आरम्भ ऐतरेय से माना जाता है।', 2, 0, 8, NULL, 'The importance of ''Prana'' (life force) and its philosophical explanation is a key feature of which Aranyaka?', '**✅ Correct Logic**: The Aitareya Aranyaka provides a detailed spiritual explanation of Prana as the foundational basis of the universe.

**💡 Exam Fact**: It also contains secrets regarding the ''Mahavrata'' rite.

**🧠 Memory Tip**: **A**itareya = **A**ir (Prana/Breath).

**🚫 Scam Alert**: Brihadaranyaka discusses it too, but Aitareya is specific for the foundational ''Prana Vidya''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e6ec4d94-57ba-43da-8e87-6ba2a739536c', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'आरण्यकों में किस पर सर्वाधिक बल दिया गया है?', '[{"id":"A","text":"पशु बलि","text_en":"पशु बलि"},{"id":"B","text":"मंत्रों का शुद्ध उच्चारण","text_en":"मंत्रों का शुद्ध उच्चारण"},{"id":"C","text":"ध्यान और मानसिक यज्ञ (Meditation & Mental Sacrifice)","text_en":"ध्यान और मानसिक यज्ञ (Meditation & Mental Sacrifice)"},{"id":"D","text":"विवाह संस्कार","text_en":"विवाह संस्कार"}]', '2', '**✅ Correct Logic**: आरण्यकों ने भौतिक यज्ञ सामग्री के स्थान पर ''मानसिक उपासना'' (Upasana) और ''ध्यान'' को प्रधानता दी। यह कर्मकांड से ज्ञान की ओर बढ़ने का पहला कदम था।

**💡 Exam Fact**: इसे ''प्रतीक उपासना'' (Symbolic Worship) का जन्मदाता माना जाता है।

**🧠 Memory Tip**: In the Forest (**Aranya**), you don''t have ritual tools, so you use your **Mind** (Meditation).

**🚫 Scam Alert**: मंत्रों का उच्चारण ''शिक्षा'' वेदांग का विषय है, आरण्यकों का नहीं।', 2, 0, 9, NULL, 'What is most emphasized in the Aranyakas?', '**✅ Correct Logic**: Aranyakas prioritized mental meditation (Upasana) over physical sacrificial ingredients. This was the first step toward the Path of Knowledge.

**💡 Exam Fact**: They are credited with the birth of symbolic worship.

**🧠 Memory Tip**: In the Forest (**Aranya**), you lack ritual tools, so you use your **Mind** (Meditation).

**🚫 Scam Alert**: Proper pronunciation of mantras is the domain of the Shiksha Vedanga.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('56c4a75d-18d0-4191-a3ed-bb3f4809ec0b', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'कथन 1: आरण्यक ग्रंथ ''संन्यासियों'' के लिए लिखे गए थे।
कथन 2: इनमें कर्मकांडों की आलोचना की गई है।
सही विकल्प चुनें:', '[{"id":"A","text":"कथन 1 सही है, कथन 2 गलत है।","text_en":"कथन 1 सही है, कथन 2 गलत है।"},{"id":"B","text":"कथन 1 गलत है, कथन 2 सही है।","text_en":"कथन 1 गलत है, कथन 2 सही है।"},{"id":"C","text":"दोनों कथन सही हैं।","text_en":"दोनों कथन सही हैं।"},{"id":"D","text":"दोनों कथन गलत हैं।","text_en":"दोनों कथन गलत हैं।"}]', '1', '**✅ Correct Logic**: कथन 1 गलत है क्योंकि आरण्यक मुख्य रूप से ''वानप्रस्थियों'' के लिए थे, संन्यासियों के लिए उपनिषद थे। कथन 2 सही है क्योंकि आरण्यक यज्ञों के बाहरी दिखावे की जगह आंतरिक अर्थ पर बल देकर कर्मकांड की सूक्ष्म आलोचना करते हैं।

**💡 Exam Fact**: आरण्यक वेदों के ''ज्ञान काण्ड'' के प्रवेश द्वार माने जाते हैं।

**🧠 Memory Tip**: Vanaprastha = Aranyaka. Sannyasa = Upanishad.

**🚫 Scam Alert**: पूर्ण ''अद्वैत'' उपनिषदों में है, आरण्यक केवल उसकी शुरुआत हैं।', 2, 0, 10, NULL, 'Statement 1: Aranyakas were written for ''Sannyasis''.
Statement 2: They contain criticism of rituals.
Choose the correct option:', '**✅ Correct Logic**: Statement 1 is false because Aranyakas were for Vanaprasthas; Upanishads were for Sannyasis. Statement 2 is true as they began the philosophical shift away from rigid external rituals.

**💡 Exam Fact**: Aranyakas are considered the gateway to the ''Jnana Kanda'' of the Vedas.

**🧠 Memory Tip**: Vanaprastha = Aranyaka. Sannyasa = Upanishad.

**🚫 Scam Alert**: Full Advaita (non-dualism) is found in Upanishads; Aranyakas are just the initiation.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ecb08ddc-4b4f-4e95-99f3-ce0fd16acdf6', '4bb204de-8033-489a-a151-f019409fb593', 'ब्राह्मण ग्रंथों का मुख्य कार्य क्या है?', '[{"id":"A","text":"ब्रह्मांड की उत्पत्ति का वर्णन","text_en":"ब्रह्मांड की उत्पत्ति का वर्णन"},{"id":"B","text":"वैदिक मंत्रों की व्याख्या और यज्ञीय विधि-विधान (Interpretation of mantras & sacrificial procedures)","text_en":"वैदिक मंत्रों की व्याख्या और यज्ञीय विधि-विधान (Interpretation of mantras & sacrificial procedures)"},{"id":"C","text":"युद्ध की रणनीतियों का वर्णन","text_en":"युद्ध की रणनीतियों का वर्णन"},{"id":"D","text":"व्याकरण के नियमों का संकलन","text_en":"व्याकरण के नियमों का संकलन"}]', '1', '**✅ Correct Logic**: ''ब्रह्म'' का अर्थ है यज्ञ। ब्राह्मण ग्रंथ वेदों के गद्य भाग हैं जो वेदों के मंत्रों का अर्थ समझाते हैं और उन्हें यज्ञों में कैसे प्रयोग करना है, इसकी विधि बताते हैं।

**💡 Exam Fact**: ये ''कर्मकांड'' (Ritualistic part) के अंतर्गत आते हैं।

**🧠 Memory Tip**: **B**rahmana = **B**ook of Ritual Methods.

**🚫 Scam Alert**: इन्हें ''ब्राह्मण'' जाति से न जोड़ें, ये वेदों के व्याख्यात्मक ग्रंथ हैं।', 2, 0, 1, NULL, 'What is the primary function of the Brahmana texts?', '**✅ Correct Logic**: ''Brahma'' here refers to Yajna. Brahmanas are the prose portions of the Vedas that explain the application and meaning of mantras in rituals.

**💡 Exam Fact**: They fall under the ''Karma Kanda'' section of Vedic literature.

**🧠 Memory Tip**: **B**rahmana = **B**ook of Ritual Methods.

**🚫 Scam Alert**: Don''t confuse the text with the caste; these are explanatory Vedic texts.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0b82da44-aa44-43d1-8aa6-dd0228dc5c2d', '4bb204de-8033-489a-a151-f019409fb593', 'सर्वाधिक विशाल और महत्वपूर्ण ब्राह्मण ग्रंथ कौन सा है?', '[{"id":"A","text":"ऐतरेय ब्राह्मण","text_en":"ऐतरेय ब्राह्मण"},{"id":"B","text":"शतपथ ब्राह्मण (Satapatha Brahmana)","text_en":"शतपथ ब्राह्मण (Satapatha Brahmana)"},{"id":"C","text":"गोपथ ब्राह्मण","text_en":"गोपथ ब्राह्मण"},{"id":"D","text":"पंचविश ब्राह्मण","text_en":"पंचविश ब्राह्मण"}]', '1', '**✅ Correct Logic**: शतपथ ब्राह्मण (यजुर्वेद) सबसे बड़ा और ऐतिहासिक दृष्टि से महत्वपूर्ण है। इसमें 100 अध्याय हैं।

**💡 Exam Fact**: इसमें जल-प्लावन की कथा, पुरुरवा-उर्वशी आख्यान और विदेह माधव की कथा मिलती है।

**🧠 Memory Tip**: **Shat** = 100. A book with **100** chapters is the biggest.

**🚫 Scam Alert**: ऐतरेय ऋग्वेद का है, पर शतपथ सबसे बड़ा है।', 2, 0, 2, NULL, 'Which is the largest and most important Brahmana text?', '**✅ Correct Logic**: The Satapatha Brahmana (Yajurveda) is the most extensive and historically significant, containing 100 chapters.

**💡 Exam Fact**: It contains the legend of the Great Flood and the story of Videha Madhava''s eastward migration.

**🧠 Memory Tip**: **Shat** = 100. A 100-chapter book is the largest.

**🚫 Scam Alert**: Aitareya belongs to the Rigveda, but Satapatha holds the record for size.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7cde3cc0-d956-435d-81d8-664a783f42d9', '4bb204de-8033-489a-a151-f019409fb593', '''विदेह माधव'' की कथा, जो आर्यों के पूर्व दिशा में प्रसार का वर्णन करती है, किस ब्राह्मण में है?', '[{"id":"A","text":"गोपथ ब्राह्मण","text_en":"गोपथ ब्राह्मण"},{"id":"B","text":"तैत्तिरीय ब्राह्मण","text_en":"तैत्तिरीय ब्राह्मण"},{"id":"C","text":"शतपथ ब्राह्मण","text_en":"शतपथ ब्राह्मण"},{"id":"D","text":"कौषीतकि ब्राह्मण","text_en":"कौषीतकि ब्राह्मण"}]', '2', '**✅ Correct Logic**: शतपथ ब्राह्मण में वर्णित है कि विदेह माधव सरस्वती नदी से पूर्व की ओर सदाानीरा (गंडक) नदी तक अग्नि को लेकर गए थे। यह आर्य संस्कृति के प्रसार का साक्ष्य है।

**💡 Exam Fact**: इसमें पत्नी को पति की ''अर्धांगिनी'' कहा गया है।

**🧠 Memory Tip**: Expansion needs a **Path** -> **Sata-patha**.

**🚫 Scam Alert**: यह कहानी ऋग्वेद में नहीं है, बल्कि उत्तर-वैदिक काल के शतपथ ब्राह्मण में है।', 2, 0, 3, NULL, 'The story of ''Videha Madhava'', which describes the eastward expansion of Aryans, is found in which Brahmana?', '**✅ Correct Logic**: The Satapatha Brahmana details Videha Madhava carrying the sacrificial fire from the Saraswati to the Sadanira (Gandak), marking Aryan expansion.

**💡 Exam Fact**: This text also famously calls a wife the ''Ardhangini'' (half of the self).

**🧠 Memory Tip**: Expansion follows a **Path** -> **Sata-patha**.

**🚫 Scam Alert**: This legend is not in the Rigveda; it belongs to the later-Vedic Satapatha Brahmana.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c71a3736-90f4-4e1f-bc42-d6dbeb82e18c', '4bb204de-8033-489a-a151-f019409fb593', 'किस ब्राह्मण ग्रंथ को ''पंचविश'' (Panchavisha) के नाम से भी जाना जाता है?', '[{"id":"A","text":"ऐतरेय","text_en":"ऐतरेय"},{"id":"B","text":"ताण्ड्य महाब्राह्मण (Tandya Mahabrahmana)","text_en":"ताण्ड्य महाब्राह्मण (Tandya Mahabrahmana)"},{"id":"C","text":"शतपथ","text_en":"शतपथ"},{"id":"D","text":"गोपथ","text_en":"गोपथ"}]', '1', '**✅ Correct Logic**: ताण्ड्य महाब्राह्मण सामवेद से संबंधित है और इसमें 25 अध्याय होने के कारण इसे ''पंचविश'' कहा जाता है।

**💡 Exam Fact**: इसमें ''व्रात्यस्तोम'' यज्ञ का वर्णन है, जिसके द्वारा गैर-आर्यों को आर्यों में शामिल किया जाता था।

**🧠 Memory Tip**: **Pancha** (5) x **Visha** (20) = 25 chapters.

**🚫 Scam Alert**: सामवेद का एक और ब्राह्मण ''षडविश'' (26 अध्याय) है, भ्रमित न हों।', 2, 0, 4, NULL, 'Which Brahmana text is also known as ''Panchavisha''?', '**✅ Correct Logic**: The Tandya Mahabrahmana (Samaveda) is called Panchavisha because it contains 25 chapters.

**💡 Exam Fact**: It describes the Vratyastoma ritual used to admit non-Aryans into the Aryan fold.

**🧠 Memory Tip**: **Pancha** (5) + **Visha** (20) = 25 chapters.

**🚫 Scam Alert**: Samaveda also has the Shadvisha (26 chapters) Brahmana; don''t mix them up.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e29481f1-773c-401e-b2a2-606bf5c83cb2', '4bb204de-8033-489a-a151-f019409fb593', 'वेदों को उनके एकमात्र/प्रमुख ब्राह्मण ग्रंथों से सुमेलित करें (Match the Vedas with their Brahmanas):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Logic**: 
* ऋग्वेद: ऐतरेय।
* यजुर्वेद: शतपथ (शुक्ल) और तैत्तिरीय (कृष्ण)।
* सामवेद: ताण्ड्य।
* अथर्ववेद: गोपथ।

**💡 Exam Fact**: अथर्ववेद का केवल ''एक'' ही ब्राह्मण ग्रंथ है, जो बार-बार पूछा जाता है।

**🧠 Memory Tip**: **A**tharva = **O**nly **G**opatha (A-O-G).

**🚫 Scam Alert**: शतपथ सबसे बड़ा है, पर उसे सामवेद से न जोड़ें, वह यजुर्वेद का है।', 2, 0, 5, NULL, 'Match the Vedas with their Brahmanas:', '**✅ Correct Logic**: 
* Rigveda: Aitareya.
* Yajurveda: Satapatha & Taittiriya.
* Samaveda: Tandya.
* Atharvaveda: Gopatha.

**💡 Exam Fact**: Atharvaveda uniquely has only ONE Brahmana text, a common exam question.

**🧠 Memory Tip**: **A**tharva = **O**nly **G**opatha (A-O-G).

**🚫 Scam Alert**: Satapatha is the largest but belongs to Yajurveda, not Samaveda.', 60, 'matching', '[{"id":"(1)","label":"ऋग्वेद","match":"ऐतरेय, कौषीतकि","matchId":"(b)"},{"id":"(2)","label":"यजुर्वेद","match":"शतपथ, तैत्तिरीय","matchId":"(a)"},{"id":"(3)","label":"सामवेद","match":"ताण्ड्य, जैमिनीय","matchId":"(d)"},{"id":"(4)","label":"अथर्ववेद","match":"गोपथ (Gopatha)","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8fea0da6-6f38-4426-8ec9-1b3038779740', '4bb204de-8033-489a-a151-f019409fb593', 'राजा के ''राज्याभिषेक'' (Coronation) और राजत्व की उत्पत्ति का विवरण किस ब्राह्मण में मिलता है?', '[{"id":"A","text":"गोपथ ब्राह्मण","text_en":"गोपथ ब्राह्मण"},{"id":"B","text":"शतपथ ब्राह्मण","text_en":"शतपथ ब्राह्मण"},{"id":"C","text":"ऐतरेय ब्राह्मण","text_en":"ऐतरेय ब्राह्मण"},{"id":"D","text":"जैमिनीय ब्राह्मण","text_en":"जैमिनीय ब्राह्मण"}]', '2', '**✅ Correct Logic**: ऐतरेय ब्राह्मण में राजत्व (Kingship) के दैवीय सिद्धांत और राज्याभिषेक के विस्तृत नियमों का उल्लेख है।

**💡 Exam Fact**: इसमें राजा को ''विशामत्ता'' (जनता का भक्षक) भी कहा गया है।

**🧠 Memory Tip**: **A**bhishek (Coronation) starts with **A**, like **A**itareya.

**🚫 Scam Alert**: शतपथ में भी राजा का उल्लेख है, लेकिन ''राजत्व का सिद्धांत'' ऐतरेय की विशेषता है।', 2, 0, 6, NULL, 'Details of the King''s Coronation and the origin of kingship are found in which Brahmana?', '**✅ Correct Logic**: The Aitareya Brahmana describes the divine origin of kingship and provided the rules for coronation ceremonies.

**💡 Exam Fact**: It controversially refers to the king as ''Vishamatta'' (devourer of the people).

**🧠 Memory Tip**: **A**bhisheka (Coronation) starts with **A**, like **A**itareya.

**🚫 Scam Alert**: While Satapatha mentions kings, the ''Theory of Kingship'' is specific to Aitareya.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('be414779-a796-46d1-820b-f33c00873b03', '4bb204de-8033-489a-a151-f019409fb593', 'किस ब्राह्मण ग्रंथ में स्त्रियों को ''सुरा और पासे'' (Wine & Dice) के समान बुराई बताया गया है?', '[{"id":"A","text":"शतपथ ब्राह्मण","text_en":"शतपथ ब्राह्मण"},{"id":"B","text":"ऐतरेय ब्राह्मण","text_en":"ऐतरेय ब्राह्मण"},{"id":"C","text":"मैत्रायणी संहिता (Maitrayani Samhita)","text_en":"मैत्रायणी संहिता (Maitrayani Samhita)"},{"id":"D","text":"गोपथ ब्राह्मण","text_en":"गोपथ ब्राह्मण"}]', '2', '**✅ Correct Logic**: मैत्रायणी संहिता (यजुर्वेद की शाखा) में स्त्री को पासा और मदिरा के साथ तीन मुख्य बुराइयों में गिना गया है। यह उत्तर-वैदिक काल में महिलाओं की गिरती स्थिति को दर्शाता है।

**💡 Exam Fact**: इसके विपरीत, शतपथ ब्राह्मण में स्त्री को पुरुष की ''अर्धांगिनी'' कहा गया है।

**🧠 Memory Tip**: **M**aitrayani = **M**isogynistic view in that specific verse.

**🚫 Scam Alert**: शतपथ में स्थिति बेहतर बताई गई है, इन दोनों में अंतर याद रखें।', 2, 0, 7, NULL, 'In which Brahmana/Vedic text are women listed as an evil alongside ''Wine and Dice''?', '**✅ Correct Logic**: The Maitrayani Samhita (a branch of Yajurveda) classifies women as one of the three major evils along with dice and liquor, reflecting a decline in status.

**💡 Exam Fact**: Conversely, the Satapatha Brahmana uplifts women as ''Ardhangini''.

**🧠 Memory Tip**: **M**aitrayani verse = **M**isguided view on women.

**🚫 Scam Alert**: Satapatha offers a more positive view; distinguish carefully between these two texts.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cf43cef3-b063-4dc3-82c5-209d4a8d216b', '4bb204de-8033-489a-a151-f019409fb593', 'अथर्ववेद का एकमात्र ब्राह्मण ग्रंथ ''गोपथ'' किसने लिखा था?', '[{"id":"A","text":"ऋषि गोपथ (Rishi Gopatha)","text_en":"ऋषि गोपथ (Rishi Gopatha)"},{"id":"B","text":"ऋषि भरद्वाज","text_en":"ऋषि भरद्वाज"},{"id":"C","text":"ऋषि वशिष्ठ","text_en":"ऋषि वशिष्ठ"},{"id":"D","text":"ऋषि विश्वामित्र","text_en":"ऋषि विश्वामित्र"}]', '0', '**✅ Correct Logic**: अथर्ववेद के एकमात्र ब्राह्मण ''गोपथ'' के रचयिता ऋषि गोपथ माने जाते हैं। इसमें गायत्री मंत्र की महिमा का भी वर्णन है।

**💡 Exam Fact**: यह सबसे बाद में लिखा गया ब्राह्मण ग्रंथ माना जाता है।

**🧠 Memory Tip**: Text name = Author name (**Gopatha**).

**🚫 Scam Alert**: अथर्ववेद ''अथर्वा'' ऋषि से जुड़ा है, पर ब्राह्मण ''गोपथ'' ऋषि का है।', 2, 0, 8, NULL, 'Who is the traditionally attributed author of the Gopatha Brahmana, the only Brahmana of Atharvaveda?', '**✅ Correct Logic**: Sage Gopatha is the traditional author of this text. It contains praise for the Gayatri Mantra.

**💡 Exam Fact**: It is considered the chronologically latest of all Brahmana texts.

**🧠 Memory Tip**: Text name matches Author name (**Gopatha**).

**🚫 Scam Alert**: Atharvaveda is named after Atharva, but its Brahmana is named after Gopatha.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d45edcd6-0bd3-4df4-b3d5-444f8a57c667', '4bb204de-8033-489a-a151-f019409fb593', 'ब्राह्मण ग्रंथों की शैली कैसी है?', '[{"id":"A","text":"केवल काव्यात्मक","text_en":"केवल काव्यात्मक"},{"id":"B","text":"गद्यात्मक (Prose)","text_en":"गद्यात्मक (Prose)"},{"id":"C","text":"केवल सूत्रों में","text_en":"केवल सूत्रों में"},{"id":"D","text":"चित्रलिपि में","text_en":"चित्रलिपि में"}]', '1', '**✅ Correct Logic**: ब्राह्मण ग्रंथ मुख्य रूप से ''गद्य'' (Prose) में लिखे गए हैं ताकि यज्ञ की विधियों को स्पष्ट रूप से समझाया जा सके। ये संस्कृत गद्य के प्राचीनतम रूप हैं।

**💡 Exam Fact**: वेदों की ''संहिता'' पद्य में है, जबकि ''ब्राह्मण'' गद्य में।

**🧠 Memory Tip**: Instructions (Rituals) are better in **Prose** (Paragraphs) than poems.

**🚫 Scam Alert**: यजुर्वेद में गद्य-पद्य दोनों हैं, पर ब्राह्मण ग्रंथ शुद्ध गद्य के लिए प्रसिद्ध हैं।', 2, 0, 9, NULL, 'What is the literary style of the Brahmana texts?', '**✅ Correct Logic**: Brahmanas are written in prose to provide clear, systematic instructions for rituals. They are among the earliest examples of Sanskrit prose.

**💡 Exam Fact**: While Samhitas are mostly verse, Brahmanas are predominantly prose.

**🧠 Memory Tip**: Technical instructions (Rituals) are easier to read in **Prose** than in poetry.

**🚫 Scam Alert**: Even though Yajurveda contains prose, the category of ''Brahmana'' is defined by its prose style.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3d5698d9-2b2a-44ca-bc9f-cd902ec049c5', '4bb204de-8033-489a-a151-f019409fb593', 'कथन 1: शतपथ ब्राह्मण के अनुसार ''रेवा'' (नर्मदा) नदी का उल्लेख मिलता है।
कथन 2: ब्राह्मण ग्रंथों में राजा को ईश्वर का अंश माना गया है।
सही विकल्प चुनें:', '[{"id":"A","text":"केवल 1 सही है","text_en":"केवल 1 सही है"},{"id":"B","text":"केवल 2 सही है","text_en":"केवल 2 सही है"},{"id":"C","text":"दोनों सही हैं","text_en":"दोनों सही हैं"},{"id":"D","text":"दोनों गलत हैं","text_en":"दोनों गलत हैं"}]', '2', '**✅ Correct Logic**: शतपथ ब्राह्मण में ''रेवा'' (नर्मदा) का उल्लेख ''रेवोत्तरा'' के रूप में मिलता है। साथ ही, उत्तर-वैदिक काल के इन ग्रंथों में राजा की शक्ति बढ़ाने के लिए ''राजत्व के दैवीय सिद्धांत'' की शुरुआत हुई।

**💡 Exam Fact**: नर्मदा का प्राचीनतम उल्लेख इसी ग्रंथ में माना जाता है।

**🧠 Memory Tip**: Satapatha (Path to MP) mentions Narmada (Reva).

**🚫 Scam Alert**: ऋग्वेद में नर्मदा का उल्लेख नहीं मिलता, यह शतपथ (यजुर्वेद) में है।', 2, 0, 10, NULL, 'Statement 1: The Satapatha Brahmana mentions the ''Reva'' (Narmada) river.
Statement 2: Brahmanas consider the King to be a part of God.
Choose the correct option:', '**✅ Correct Logic**: Both statements are true. Satapatha mentions ''Reva'' (Narmada), and these texts began propounding the ''Divine Theory of Kingship'' to bolster royal authority.

**💡 Exam Fact**: This is considered the earliest literary mention of the Narmada river.

**🧠 Memory Tip**: Satapatha (The ''Path'') leads to the Reva (Narmada).

**🚫 Scam Alert**: Narmada is not mentioned in the Rigveda; its mention appears later in the Satapatha Brahmana.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9f359a8a-cda5-4d6e-a98b-217f06d1a978', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'भारतीय संविधान में ''राज्य के नीति-निदेशक सिद्धांत'' (DPSP) किस देश के संविधान से प्रेरित हैं?', '[{"id":"A","text":"आयरलैंड (Ireland)","text_en":"आयरलैंड (Ireland)"},{"id":"B","text":"कनाडा","text_en":"कनाडा"},{"id":"C","text":"दक्षिण अफ्रीका","text_en":"दक्षिण अफ्रीका"},{"id":"D","text":"ऑस्ट्रेलिया","text_en":"ऑस्ट्रेलिया"}]', '0', '✅ **Correct Logic**: भारतीय संविधान के भाग IV (अनुच्छेद 36-51) में वर्णित DPSP आयरलैंड के संविधान से लिए गए हैं।
💡 **Exam Fact**: आयरलैंड ने स्वयं इन्हें स्पेन के संविधान से लिया था।
🧠 **Memory Tip**: Direct (D) - Ireland (I) -> DI (Think of it as Directions for India).
🚫 **Scam Alert**: मौलिक अधिकार अमेरिका से हैं, लेकिन निदेशक तत्व आयरलैंड से।', 2, 0, 1, NULL, 'The ''Directive Principles of State Policy'' (DPSP) in the Indian Constitution are inspired by which country''s constitution?', '✅ **Correct Logic**: The DPSP, described in Part IV (Articles 36-51) of the Indian Constitution, are borrowed from the Irish Constitution.
💡 **Exam Fact**: Ireland itself had borrowed these principles from the Spanish Constitution.
🧠 **Memory Tip**: DI (Direct - Ireland) - Directions for India.
🚫 **Scam Alert**: Fundamental Rights are from the USA, but Directive Principles are from Ireland.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('792d55d7-c756-49ee-a951-8403d95dd7e9', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'निम्नलिखित में से कौन सा अनुच्छेद ''ग्राम पंचायतों के संगठन'' (Organization of Village Panchayats) से संबंधित है?', '[{"id":"A","text":"अनुच्छेद 38","text_en":"अनुच्छेद 38"},{"id":"B","text":"अनुच्छेद 40","text_en":"अनुच्छेद 40"},{"id":"C","text":"अनुच्छेद 44","text_en":"अनुच्छेद 44"},{"id":"D","text":"अनुच्छेद 48","text_en":"अनुच्छेद 48"}]', '1', '✅ **Correct Logic**: अनुच्छेद 40 राज्य को ग्राम पंचायतों के गठन का निर्देश देता है। यह गांधीवादी विचारधारा पर आधारित है।
💡 **Exam Fact**: इसे ''गांधीवादी सिद्धांत'' के अंतर्गत वर्गीकृत किया गया है।
🧠 **Memory Tip**: 40 - Think of 40 villagers sitting in a Panchayat circle.
🚫 **Scam Alert**: यह मूल संविधान में था, लेकिन इसे संवैधानिक दर्जा 73वें संशोधन द्वारा मिला।', 2, 0, 2, NULL, 'Which of the following Articles relates to the ''Organization of Village Panchayats''?', '✅ **Correct Logic**: Article 40 directs the State to organize village panchayats. This is based on Gandhian ideology.
💡 **Exam Fact**: It is classified under ''Gandhian Principles'' of DPSP.
🧠 **Memory Tip**: 40 - Visualize 40 people forming a local panchayat.
🚫 **Scam Alert**: While the instruction was in Art 40, the legal teeth/status came much later via the 73rd Amendment.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1775f989-1e7e-4e21-83b2-abf840b2874b', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', '''समान नागरिक संहिता'' (Uniform Civil Code) का उल्लेख संविधान के किस अनुच्छेद में किया गया है?', '[{"id":"A","text":"अनुच्छेद 41","text_en":"अनुच्छेद 41"},{"id":"B","text":"अनुच्छेद 42","text_en":"अनुच्छेद 42"},{"id":"C","text":"अनुच्छेद 43","text_en":"अनुच्छेद 43"},{"id":"D","text":"अनुच्छेद 44","text_en":"अनुच्छेद 44"}]', '3', '✅ **Correct Logic**: अनुच्छेद 44 कहता है कि राज्य भारत के पूरे क्षेत्र में नागरिकों के लिए एक समान नागरिक संहिता सुनिश्चित करने का प्रयास करेगा।
💡 **Exam Fact**: गोवा भारत का एकमात्र राज्य है जहाँ UCC लागू है (पुर्तगाली विरासत के कारण)।
🧠 **Memory Tip**: 4 = 4 (Both numbers are ''Uniform'').
🚫 **Scam Alert**: यह अभी तक पूरे भारत में लागू नहीं हुआ है क्योंकि DPSP न्यायालय द्वारा प्रवर्तनीय (Enforceable) नहीं हैं।', 2, 0, 3, NULL, 'In which Article of the Constitution is the ''Uniform Civil Code'' mentioned?', '✅ **Correct Logic**: Article 44 states that the State shall endeavor to secure for the citizens a Uniform Civil Code throughout the territory of India.
💡 **Exam Fact**: Goa is currently the only state with a UCC in place (Portuguese legacy).
🧠 **Memory Tip**: 44 - Two uniform/equal digits.
🚫 **Scam Alert**: Since DPSPs are non-justiciable, the UCC is not yet a mandatory national law.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6f5ae605-bb2d-4962-8e9e-ce9e6db43d23', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'किस संशोधन द्वारा नीति-निदेशक तत्वों में अनुच्छेद 39A (समान न्याय और मुफ्त कानूनी सहायता) जोड़ा गया था?', '[{"id":"A","text":"42वां संशोधन","text_en":"42वां संशोधन"},{"id":"B","text":"44वां संशोधन","text_en":"44वां संशोधन"},{"id":"C","text":"86वां संशोधन","text_en":"86वां संशोधन"},{"id":"D","text":"97वां संशोधन","text_en":"97वां संशोधन"}]', '0', '✅ **Correct Logic**: 42वें संशोधन (1976) ने 39A, 43A और 48A जैसे नए निदेशक तत्व जोड़े थे।
💡 **Exam Fact**: 39A का उद्देश्य गरीबों को मुफ्त कानूनी सहायता सुनिश्चित करना है।
🧠 **Memory Tip**: 42 - Mini Constitution (Added the most).
🚫 **Scam Alert**: 44वें संशोधन ने भी एक तत्व (अनुच्छेद 38 में) जोड़ा था, लेकिन 39A 42वें का हिस्सा है।', 2, 0, 4, NULL, 'By which amendment was Article 39A (Equal Justice and Free Legal Aid) added to the DPSP?', '✅ **Correct Logic**: The 42nd Amendment (1976) added new principles like 39A, 43A, and 48A to the DPSP.
💡 **Exam Fact**: The objective of 39A is to ensure free legal aid to the poor.
🧠 **Memory Tip**: 42 added a ''team'' of articles.
🚫 **Scam Alert**: While the 44th also added to DPSP (in Art 38), 39A belongs specifically to the 42nd.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a40f16d4-c67c-4d71-81a7-3e31c5fc4f51', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'अनुच्छेदों और उनके विषयों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: 48A पर्यावरण के लिए है। 50 शक्तियों के पृथक्करण (Separation) के लिए है। 51 विदेश नीति का आधार है। 47 स्वास्थ्य और शराबबंदी से संबंधित है।
💡 **Exam Fact**: अनुच्छेद 50 लोकतंत्र की स्वतंत्रता के लिए अत्यंत महत्वपूर्ण है।
🧠 **Memory Tip**: 50-50 (Split between Exec and Bio/Judiciary).
🚫 **Scam Alert**: अनुच्छेद 51 मौलिक कर्तव्य (51A) से अलग है।', 2, 0, 5, NULL, 'Match the Articles and their subjects:', '✅ **Correct Logic**: 48A is for environment. 50 for separation of powers. 51 forms the basis of foreign policy. 47 is about public health and prohibition.
💡 **Exam Fact**: Article 50 is crucial for the independence of the Judiciary.
🧠 **Memory Tip**: 50-50 (Perfect split/separation).
🚫 **Scam Alert**: Do not confuse Art 51 (Inter-state peace) with Art 51A (Fundamental Duties).', 60, 'matching', '[{"id":"(1)","label":"अनुच्छेद 48A","match":"पर्यावरण और वन्यजीव संरक्षण","matchId":"(a)"},{"id":"(2)","label":"अनुच्छेद 50","match":"कार्यपालिका से न्यायपालिका का पृथक्करण","matchId":"(b)"},{"id":"(3)","label":"अनुच्छेद 51","match":"अंतरराष्ट्रीय शांति और सुरक्षा","matchId":"(c)"},{"id":"(4)","label":"अनुच्छेद 47","match":"पोषण स्तर और नशीली दवाओं पर रोक","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1e1cecd7-6ea8-4d07-9bf8-86b9017656fa', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'निम्नलिखित में से कौन सा एक ''नीति-निदेशक तत्व'' नहीं है?', '[{"id":"A","text":"गौ-वध पर प्रतिबंध","text_en":"गौ-वध पर प्रतिबंध"},{"id":"B","text":"14 वर्ष तक के बच्चों के लिए मुफ्त और अनिवार्य शिक्षा","text_en":"14 वर्ष तक के बच्चों के लिए मुफ्त और अनिवार्य शिक्षा"},{"id":"C","text":"अल्पसंख्यकों को शैक्षणिक संस्थान स्थापित करने का अधिकार","text_en":"अल्पसंख्यकों को शैक्षणिक संस्थान स्थापित करने का अधिकार"},{"id":"D","text":"काम करने का अधिकार","text_en":"काम करने का अधिकार"}]', '2', '✅ **Correct Logic**: अल्पसंख्यकों का शैक्षणिक संस्थान स्थापित करने का अधिकार (अनुच्छेद 30) एक ''मौलिक अधिकार'' है, न कि निदेशक तत्व।
💡 **Exam Fact**: गौ-वध निषेध अनुच्छेद 48 (कृषि और पशुपालन) के अंतर्गत आता है।
🧠 **Memory Tip**: Minorities/Religion = Usually Part III (Rights).
🚫 **Scam Alert**: अनुच्छेद 45 पहले शिक्षा के लिए था, लेकिन अब 21A मौलिक अधिकार बन चुका है।', 2, 0, 6, NULL, 'Which of the following is NOT a ''Directive Principle''?', '✅ **Correct Logic**: The right of minorities to establish educational institutions (Art 30) is a ''Fundamental Right'', not a DPSP.
💡 **Exam Fact**: Prohibition of cow slaughter is under Art 48 (Agriculture & Animal Husbandry).
🧠 **Memory Tip**: Minority rights = Part III list.
🚫 **Scam Alert**: Art 45 used to focus on education, but it''s now a Fundamental Right under 21A.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('17861295-9470-4ed1-aa1f-126e56fdc2e0', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'डॉ. बी.आर. अंबेडकर ने नीति-निदेशक तत्वों को क्या कहकर संबोधित किया था?', '[{"id":"A","text":"संविधान की अनोखी विशेषता (Novel Features)","text_en":"संविधान की अनोखी विशेषता (Novel Features)"},{"id":"B","text":"संविधान की आत्मा","text_en":"संविधान की आत्मा"},{"id":"C","text":"पवित्र दस्तावेज","text_en":"पवित्र दस्तावेज"},{"id":"D","text":"राजनीतिक घोषणापत्र","text_en":"राजनीतिक घोषणापत्र"}]', '0', '✅ **Correct Logic**: अंबेडकर जी ने DPSP को भारतीय संविधान की ''अनोखी विशेषता'' (Novel Features) कहा था।
💡 **Exam Fact**: ग्रैनविले ऑस्टिन ने DPSP और मौलिक अधिकारों को ''संविधान की अंतरात्मा'' (Conscience) कहा था।
🧠 **Memory Tip**: Ambedkar thought DPSPs were ''Novel'' (New/Unique).
🚫 **Scam Alert**: ''आत्मा'' शब्द उन्होंने अनुच्छेद 32 के लिए प्रयोग किया था।', 2, 0, 7, NULL, 'How did Dr. B.R. Ambedkar describe the Directive Principles of State Policy?', '✅ **Correct Logic**: Ambedkar referred to the DPSP as the ''Novel Features'' of the Indian Constitution.
💡 **Exam Fact**: Granville Austin described the DPSP and Fundamental Rights together as the ''Conscience'' of the Constitution.
🧠 **Memory Tip**: Ambedkar = Novel features.
🚫 **Scam Alert**: He used the term ''Soul'' specifically for Article 32.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b722ee3c-a111-4b36-b112-f549708feaa5', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'नीति-निदेशक तत्वों की प्रकृति (Nature) कैसी है?', '[{"id":"A","text":"वाद-योग्य (Justiciable)","text_en":"वाद-योग्य (Justiciable)"},{"id":"B","text":"गैर-वाद-योग्य (Non-Justiciable)","text_en":"गैर-वाद-योग्य (Non-Justiciable)"},{"id":"C","text":"कठोर","text_en":"कठोर"},{"id":"D","text":"लोकतांत्रिक नहीं","text_en":"लोकतांत्रिक नहीं"}]', '1', '✅ **Correct Logic**: DPSP ''गैर-वाद-योग्य'' हैं, अर्थात इनके उल्लंघन पर नागरिक न्यायालय नहीं जा सकते।
💡 **Exam Fact**: यह अनुच्छेद 37 में स्पष्ट रूप से लिखा गया है।
🧠 **Memory Tip**: DPSP = Directions, not Commands (No Court).
🚫 **Scam Alert**: भले ही ये वाद-योग्य नहीं हैं, पर देश के शासन में ''आधारभूत'' (Fundamental) हैं।', 2, 0, 8, NULL, 'What is the ''Nature'' of the Directive Principles of State Policy?', '✅ **Correct Logic**: DPSP are ''Non-justiciable'', meaning they cannot be enforced by a court of law if not implemented.
💡 **Exam Fact**: This status is explicitly mentioned in Article 37.
🧠 **Memory Tip**: DPSP = Suggestive, not Enforceable.
🚫 **Scam Alert**: While non-justiciable, they are still ''fundamental'' in the governance of the country.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6fba34fe-d917-4be7-9291-80bbd1ca8d54', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', '97वें संविधान संशोधन (2011) द्वारा कौन सा नया नीति-निदेशक तत्व जोड़ा गया था?', '[{"id":"A","text":"सहकारी समितियों को बढ़ावा देना (Art 43B)","text_en":"सहकारी समितियों को बढ़ावा देना (Art 43B)"},{"id":"B","text":"पर्यावरण संरक्षण","text_en":"पर्यावरण संरक्षण"},{"id":"C","text":"मुफ्त विधिक सहायता","text_en":"मुफ्त विधिक सहायता"},{"id":"D","text":"उद्योगों के प्रबंधन में श्रमिकों की भागीदारी","text_en":"उद्योगों के प्रबंधन में श्रमिकों की भागीदारी"}]', '0', '✅ **Correct Logic**: 97वें संशोधन द्वारा सहकारी समितियों (Cooperative Societies) को बढ़ावा देने के लिए अनुच्छेद 43B जोड़ा गया।
💡 **Exam Fact**: इसी संशोधन ने ''सहकारी समितियां'' बनाना एक मौलिक अधिकार (Art 19) भी बनाया।
🧠 **Memory Tip**: 97-C (Cooperative).
🚫 **Scam Alert**: श्रमिकों की भागीदारी 42वें संशोधन (Art 43A) द्वारा जोड़ी गई थी।', 2, 0, 9, NULL, 'Which new Directive Principle was added by the 97th Amendment (2011)?', '✅ **Correct Logic**: The 97th Amendment added Article 43B to promote cooperative societies.
💡 **Exam Fact**: This amendment also made forming cooperatives a Fundamental Right under Art 19.
🧠 **Memory Tip**: 97-C (Cooperative).
🚫 **Scam Alert**: Workers'' participation was added by the 42nd Amendment (Art 43A).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0e079f34-da07-4046-9965-aca6ef697dcd', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'किस मामले में सर्वोच्च न्यायालय ने यह व्यवस्था दी कि ''मौलिक अधिकार और नीति-निदेशक तत्वों के बीच संतुलन'' संविधान के मूल ढांचे का हिस्सा है?', '[{"id":"A","text":"मिनर्वा मिल्स मामला (1980)","text_en":"मिनर्वा मिल्स मामला (1980)"},{"id":"B","text":"केशवानंद भारती मामला (1973)","text_en":"केशवानंद भारती मामला (1973)"},{"id":"C","text":"गोलकनाथ मामला (1967)","text_en":"गोलकनाथ मामला (1967)"},{"id":"D","text":"मेनका गांधी मामला (1978)","text_en":"मेनका गांधी मामला (1978)"}]', '0', '✅ **Correct Logic**: मिनर्वा मिल्स मामले में सुप्रीम कोर्ट ने कहा कि संविधान FR और DPSP के बीच संतुलन की नींव पर खड़ा है।
💡 **Exam Fact**: इसने 42वें संशोधन के उस प्रावधान को रद्द कर दिया जिसने DPSP को सभी FR पर वरीयता दी थी।
🧠 **Memory Tip**: M-M (Minerva Mills - Maintain balance).
🚫 **Scam Alert**: केशवानंद भारती ने ''मूल ढांचा'' शुरू किया, लेकिन ''संतुलन'' की बात मिनर्वा मिल्स में स्पष्ट हुई।', 2, 0, 10, NULL, 'In which case did the Supreme Court rule that the ''balance between Fundamental Rights and DPSP'' is part of the basic structure?', '✅ **Correct Logic**: In the Minerva Mills case, the SC held that the Constitution rests on the bedrock of balance between FRs and DPSPs.
💡 **Exam Fact**: It struck down the provision of the 42nd Amendment that gave DPSP priority over all FRs.
🧠 **Memory Tip**: M-M (Minerva Mills - Maintain balance).
🚫 **Scam Alert**: Kesavananda established ''Basic Structure'', but ''Balance'' was specific to Minerva Mills.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b37236a7-2a3d-4932-9a88-0e7bcf2e907d', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'भारत के निर्वाचन आयोग (ECI) के संबंध में कौन सा अनुच्छेद ''निर्वाचन नामावली'' तैयार करने और चुनाव के ''अधीक्षण, निर्देशन और नियंत्रण'' की शक्ति प्रदान करता है?', '[{"id":"A","text":"अनुच्छेद 324","text_en":"अनुच्छेद 324"},{"id":"B","text":"अनुच्छेद 325","text_en":"अनुच्छेद 325"},{"id":"C","text":"अनुच्छेद 326","text_en":"अनुच्छेद 326"},{"id":"D","text":"अनुच्छेद 329","text_en":"अनुच्छेद 329"}]', '0', '✅ **Correct Logic**: अनुच्छेद 324 चुनाव आयोग की स्थापना और उसकी शक्तियों का मुख्य आधार है।
💡 **Exam Fact**: निर्वाचन आयोग की स्थापना 25 जनवरी 1950 को हुई थी, इसलिए इस दिन ''राष्ट्रीय मतदाता दिवस'' मनाया जाता है।
🧠 **Memory Tip**: 324 - ''Chunav'' (Election) starts with C (3rd letter) and happens for the 4 pillars.
🚫 **Scam Alert**: अनुच्छेद 326 ''वयस्क मताधिकार'' (Adult Suffrage) से संबंधित है, आयोग के गठन से नहीं।', 2, 0, 1, NULL, 'Which Article regarding the Election Commission of India (ECI) grants power for the ''superintendence, direction, and control'' of elections?', '✅ **Correct Logic**: Article 324 is the primary foundation for the establishment and powers of the Election Commission.
💡 **Exam Fact**: ECI was established on Jan 25, 1950, which is why ''National Voters'' Day'' is celebrated on this date.
🧠 **Memory Tip**: 324 - The ''Three'' directions for ''Four'' types of elections.
🚫 **Scam Alert**: Article 326 deals with ''Universal Adult Suffrage'', not the Commission''s powers.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4b5593e0-3269-4abb-905e-5783bdbfe926', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'संघ लोक सेवा आयोग (UPSC) के अध्यक्ष और सदस्यों की नियुक्ति किसके द्वारा की जाती है और उनका कार्यकाल क्या होता है?', '[{"id":"A","text":"प्रधानमंत्री; 5 वर्ष या 65 वर्ष","text_en":"प्रधानमंत्री; 5 वर्ष या 65 वर्ष"},{"id":"B","text":"राष्ट्रपति; 6 वर्ष या 65 वर्ष","text_en":"राष्ट्रपति; 6 वर्ष या 65 वर्ष"},{"id":"C","text":"राष्ट्रपति; 6 वर्ष या 62 वर्ष","text_en":"राष्ट्रपति; 6 वर्ष या 62 वर्ष"},{"id":"D","text":"गृह मंत्री; 5 वर्ष या 62 वर्ष","text_en":"गृह मंत्री; 5 वर्ष या 62 वर्ष"}]', '1', '✅ **Correct Logic**: UPSC के अध्यक्ष और सदस्यों की नियुक्ति राष्ट्रपति द्वारा की जाती है। कार्यकाल 6 वर्ष या 65 वर्ष की आयु (जो भी पहले हो) तक होता है।
💡 **Exam Fact**: राज्य लोक सेवा आयोग (SPSC) के लिए सेवानिवृत्ति आयु 62 वर्ष है।
🧠 **Memory Tip**: Central Big Office = Big Age (65).
🚫 **Scam Alert**: नियुक्ति राष्ट्रपति करता है, लेकिन इन्हें पद से केवल सर्वोच्च न्यायालय की जाँच के बाद ही हटाया जा सकता है।', 2, 0, 2, NULL, 'By whom are the Chairman and members of UPSC appointed and what is their tenure?', '✅ **Correct Logic**: The President appoints the UPSC Chairman and members. The tenure is 6 years or until the age of 65, whichever is earlier.
💡 **Exam Fact**: For State PSCs, the retirement age is 62 years.
🧠 **Memory Tip**: Central/Union = Maximum age (65).
🚫 **Scam Alert**: Appointment is by the President, but removal is subject to an enquiry by the Supreme Court.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e279d6e0-cfe3-4a72-b9cb-92a456d977d2', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'भारत के नियंत्रक एवं महालेखा परीक्षक (CAG) के वेतन और सेवा शर्तें किसके द्वारा निर्धारित की जाती हैं?', '[{"id":"A","text":"राष्ट्रपति","text_en":"राष्ट्रपति"},{"id":"B","text":"संसद","text_en":"संसद"},{"id":"C","text":"वित्त मंत्री","text_en":"वित्त मंत्री"},{"id":"D","text":"प्रधानमंत्री","text_en":"प्रधानमंत्री"}]', '1', '✅ **Correct Logic**: अनुच्छेद 148(3) के अनुसार, CAG के वेतन और सेवा शर्तें ''संसद'' द्वारा कानून बनाकर निर्धारित की जाती हैं।
💡 **Exam Fact**: CAG का वेतन सर्वोच्च न्यायालय के न्यायाधीश के बराबर होता है।
🧠 **Memory Tip**: CAG audits the money Parliament votes, so Parliament sets the salary.
🚫 **Scam Alert**: राष्ट्रपति नियुक्ति करता है, लेकिन सेवा शर्तें संसद तय करती है।', 2, 0, 3, NULL, 'Who determines the salary and service conditions of the Comptroller and Auditor General (CAG) of India?', '✅ **Correct Logic**: According to Article 148(3), the salary and service conditions of the CAG are determined by the Parliament by law.
💡 **Exam Fact**: The CAG''s salary is equal to that of a Supreme Court judge.
🧠 **Memory Tip**: Since CAG audits what Parliament spends, Parliament decides the pay.
🚫 **Scam Alert**: The President appoints the CAG, but service conditions are a Parliamentary prerogative.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('70cd0ac2-91e0-40b0-b93f-6e6fc90ea06b', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'नीति आयोग (NITI Aayog) के वर्तमान संरचना में ''पदेन सदस्य'' (Ex-officio members) की अधिकतम संख्या कितनी हो सकती है?', '[{"id":"A","text":"2","text_en":"2"},{"id":"B","text":"4","text_en":"4"},{"id":"C","text":"5","text_en":"5"},{"id":"D","text":"10","text_en":"10"}]', '1', '✅ **Correct Logic**: केंद्रीय मंत्रिपरिषद से अधिकतम 4 सदस्य प्रधानमंत्री द्वारा पदेन सदस्य के रूप में नामित किए जा सकते हैं।
💡 **Exam Fact**: नीति आयोग एक ''सांविधिक'' या ''संवैधानिक'' निकाय नहीं है, यह एक कार्यकारी (Executive) निकाय है।
🧠 **Memory Tip**: NITI (4 letters) = 4 Ex-officio members.
🚫 **Scam Alert**: पूर्णकालिक सदस्य (Full-time members) की संख्या 5 तक हो सकती है, पर पदेन सदस्य 4 होते हैं।', 2, 0, 4, NULL, 'What is the maximum number of ''Ex-officio members'' in the current structure of NITI Aayog?', '✅ **Correct Logic**: A maximum of 4 members from the Union Council of Ministers are nominated by the PM as Ex-officio members.
💡 **Exam Fact**: NITI Aayog is neither a constitutional nor a statutory body; it is an executive body.
🧠 **Memory Tip**: N-I-T-I has 4 letters, hence 4 ex-officio members.
🚫 **Scam Alert**: Full-time members can be up to 5, but ex-officio members are strictly capped at 4.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ed77e471-42e5-485e-8360-4d27ee921698', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'आयोग और उनके स्थापना वर्षों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: महिला आयोग 1992 (सांविधिक), मानवाधिकार और पिछड़ा वर्ग 1993, और सूचना आयोग RTI अधिनियम 2005 के तहत बना।
💡 **Exam Fact**: पिछड़ा वर्ग आयोग को 102वें संशोधन (2018) द्वारा अब संवैधानिक दर्जा मिल गया है।
🧠 **Memory Tip**: Women first (92), Humans/Backwards next (93).
🚫 **Scam Alert**: केंद्रीय सतर्कता आयोग (CVC) 1964 में बना था, इसे सूचना आयोग के साथ भ्रमित न करें।', 2, 0, 5, NULL, 'Match the Commissions with their years of establishment:', '✅ **Correct Logic**: Women''s Commission 1992, NHRC & NCBC 1993, and CIC 2005 (via RTI Act).
💡 **Exam Fact**: NCBC was granted constitutional status by the 102nd Amendment in 2018.
🧠 **Memory Tip**: Ladies first (92), then Rights/Others (93).
🚫 **Scam Alert**: CVC was established in 1964; don''t confuse it with the 2005 CIC.', 60, 'matching', '[{"id":"(1)","label":"राष्ट्रीय महिला आयोग","match":"1992","matchId":"(a)"},{"id":"(2)","label":"राष्ट्रीय मानवाधिकार आयोग","match":"1993","matchId":"(b)"},{"id":"(3)","label":"राष्ट्रीय पिछड़ा वर्ग आयोग","match":"1993","matchId":"(c)"},{"id":"(4)","label":"केंद्रीय सूचना आयोग","match":"2005","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0083c10e-59e0-44fd-867b-1163bce6ea7a', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'राष्ट्रीय अनुसूचित जनजाति आयोग (NCST) को किस संविधान संशोधन द्वारा पृथक आयोग बनाया गया था?', '[{"id":"A","text":"65वां संशोधन","text_en":"65वां संशोधन"},{"id":"B","text":"89वां संशोधन","text_en":"89वां संशोधन"},{"id":"C","text":"102वां संशोधन","text_en":"102वां संशोधन"},{"id":"D","text":"42वां संशोधन","text_en":"42वां संशोधन"}]', '1', '✅ **Correct Logic**: 89वें संशोधन (2003) ने पूर्ववर्ती संयुक्त आयोग को दो भागों में बाँट दिया: NCSC (Art 338) और NCST (Art 338A)।
💡 **Exam Fact**: यह संशोधन 2004 से प्रभावी हुआ।
🧠 **Memory Tip**: 89 - Two separate digits for two separate commissions.
🚫 **Scam Alert**: 65वें संशोधन ने पहली बार ''बहु-सदस्यीय'' संयुक्त आयोग बनाया था।', 2, 0, 6, NULL, 'By which Constitutional Amendment was the National Commission for Scheduled Tribes (NCST) made a separate commission?', '✅ **Correct Logic**: The 89th Amendment (2003) bifurcated the previous joint commission into NCSC (Art 338) and NCST (Art 338A).
💡 **Exam Fact**: This amendment came into effect in 2004.
🧠 **Memory Tip**: 89 separated them; think of 8 and 9 as two distinct entities.
🚫 **Scam Alert**: The 65th Amendment had established the initial multi-member joint commission.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2437a627-69a9-49c5-9f7c-162764848533', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'केंद्रीय सतर्कता आयोग (CVC) की स्थापना किस समिति की सिफारिश पर की गई थी?', '[{"id":"A","text":"संथानम समिति","text_en":"संथानम समिति"},{"id":"B","text":"प्रशासनिक सुधार आयोग","text_en":"प्रशासनिक सुधार आयोग"},{"id":"C","text":"अशोक मेहता समिति","text_en":"अशोक मेहता समिति"},{"id":"D","text":"दिनेश गोस्वामी समिति","text_en":"दिनेश गोस्वामी समिति"}]', '0', '✅ **Correct Logic**: भ्रष्टाचार रोकने के लिए संथानम समिति (1962-64) की सिफारिश पर 1964 में CVC बना।
💡 **Exam Fact**: 2003 में इसे ''सांविधिक'' (Statutory) दर्जा दिया गया।
🧠 **Memory Tip**: Santhanam - Shanti/Cleanliness (Anti-corruption).
🚫 **Scam Alert**: दिनेश गोस्वामी समिति चुनाव सुधारों से संबंधित है।', 2, 0, 7, NULL, 'On the recommendation of which committee was the Central Vigilance Commission (CVC) established?', '✅ **Correct Logic**: CVC was setup in 1964 following the recommendations of the Santhanam Committee (1962-64) on Prevention of Corruption.
💡 **Exam Fact**: It was granted statutory status in 2003.
🧠 **Memory Tip**: Santhanam sought to ''sanitize'' (clean) the system.
🚫 **Scam Alert**: Dinesh Goswami committee is associated with electoral reforms.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4e2931b5-4af5-498e-971f-c1e937c30c0f', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'राष्ट्रीय मानवाधिकार आयोग (NHRC) के अध्यक्ष के रूप में किसे नियुक्त किया जा सकता है?', '[{"id":"A","text":"केवल सेवानिवृत्त मुख्य न्यायाधीश (CJI)","text_en":"केवल सेवानिवृत्त मुख्य न्यायाधीश (CJI)"},{"id":"B","text":"केवल सेवानिवृत्त न्यायाधीश (SC)","text_en":"केवल सेवानिवृत्त न्यायाधीश (SC)"},{"id":"C","text":"सेवानिवृत्त CJI या सर्वोच्च न्यायालय का कोई भी सेवानिवृत्त न्यायाधीश","text_en":"सेवानिवृत्त CJI या सर्वोच्च न्यायालय का कोई भी सेवानिवृत्त न्यायाधीश"},{"id":"D","text":"कोई भी प्रसिद्ध न्यायविद्","text_en":"कोई भी प्रसिद्ध न्यायविद्"}]', '2', '✅ **Correct Logic**: 2019 के संशोधन के बाद, सेवानिवृत्त CJI के साथ-साथ सुप्रीम कोर्ट के किसी भी सेवानिवृत्त जज को अध्यक्ष बनाया जा सकता है।
💡 **Exam Fact**: इनका कार्यकाल 3 वर्ष या 70 वर्ष की आयु तक होता है।
🧠 **Memory Tip**: 2019 expansion = CJI or SC Judge.
🚫 **Scam Alert**: पहले केवल सेवानिवृत्त CJI ही अध्यक्ष बन सकते थे, अब नियम बदल गया है।', 2, 0, 8, NULL, 'Who can be appointed as the Chairman of the National Human Rights Commission (NHRC)?', '✅ **Correct Logic**: Since the 2019 amendment, either a retired CJI or a retired Judge of the Supreme Court can be the Chairman.
💡 **Exam Fact**: Their tenure is 3 years or until age 70.
🧠 **Memory Tip**: 2019 opened the door for all retired SC judges.
🚫 **Scam Alert**: Earlier, only retired CJIs were eligible; don''t follow the outdated rule.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('83d1eebc-8c5e-414d-bc01-661926b30dda', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'मध्य प्रदेश राज्य निर्वाचन आयोग (SEC) का गठन कब किया गया था?', '[{"id":"A","text":"1 फरवरी 1994","text_en":"1 फरवरी 1994"},{"id":"B","text":"15 फरवरी 1994","text_en":"15 फरवरी 1994"},{"id":"C","text":"1 नवंबर 1956","text_en":"1 नवंबर 1956"},{"id":"D","text":"1 जनवरी 1994","text_en":"1 जनवरी 1994"}]', '0', '✅ **Correct Logic**: 73वें और 74वें संशोधन के बाद, मध्य प्रदेश 1 फरवरी 1994 को राज्य निर्वाचन आयोग गठित करने वाला देश का पहला राज्य बना।
💡 **Exam Fact**: एन.बी. लोहानी मध्य प्रदेश के पहले राज्य निर्वाचन आयुक्त थे।
🧠 **Memory Tip**: Feb 1, 94 - First in the nation.
🚫 **Scam Alert**: राज्य चुनाव आयोग केवल स्थानीय निकायों (पंचायत/नगरपालिका) के चुनाव कराता है, विधानसभा के नहीं।', 2, 0, 9, NULL, 'When was the Madhya Pradesh State Election Commission (SEC) constituted?', '✅ **Correct Logic**: MP was the first state to form an SEC on Feb 1, 1994, following the 73rd/74th amendments.
💡 **Exam Fact**: N.B. Lohani was the first State Election Commissioner of MP.
🧠 **Memory Tip**: Feb 1, ''94 - Setting the pace for others.
🚫 **Scam Alert**: The SEC only conducts local body elections (Panchayat/Municipal); state assembly elections are handled by ECI.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ce4bc620-d598-4dd3-b2f0-6b4e9b147d07', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'राष्ट्रीय बाल अधिकार संरक्षण आयोग (NCPCR) में अध्यक्ष के अलावा कितने सदस्य होते हैं और उनमें कितनी महिलाओं का होना अनिवार्य है?', '[{"id":"A","text":"6 सदस्य; 2 महिलाएं","text_en":"6 सदस्य; 2 महिलाएं"},{"id":"B","text":"5 सदस्य; 1 महिला","text_en":"5 सदस्य; 1 महिला"},{"id":"C","text":"6 सदस्य; 1 महिला","text_en":"6 सदस्य; 1 महिला"},{"id":"D","text":"3 सदस्य; 2 महिलाएं","text_en":"3 सदस्य; 2 महिलाएं"}]', '0', '✅ **Correct Logic**: आयोग में 1 अध्यक्ष और 6 सदस्य होते हैं, जिनमें कम से कम 2 महिलाओं का होना अनिवार्य है।
💡 **Exam Fact**: यह आयोग ''बाल अधिकार संरक्षण आयोग अधिनियम, 2005'' के तहत एक सांविधिक निकाय है।
🧠 **Memory Tip**: 6 members, 2 ladies (Double of one).
🚫 **Scam Alert**: महिला सदस्यों की संख्या 1 नहीं बल्कि 2 है, इसे याद रखें।', 2, 0, 10, NULL, 'Excluding the Chairman, how many members are there in NCPCR and how many must be women?', '✅ **Correct Logic**: The commission consists of 1 Chairman and 6 members, of whom at least 2 must be women.
💡 **Exam Fact**: It is a statutory body under the CPCR Act, 2005.
🧠 **Memory Tip**: 6 total, 2 must be women.
🚫 **Scam Alert**: Don''t confuse it with other commissions; the ''at least 2 women'' rule is specific here.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3dddfe22-9032-48a2-8892-6656190abb8e', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश के प्रथम राज्यपाल कौन थे?', '[{"id":"A","text":"पट्टाभि सीतारमैया","text_en":"पट्टाभि सीतारमैया"},{"id":"B","text":"हरी विनायक पाटस्कर","text_en":"हरी विनायक पाटस्कर"},{"id":"C","text":"के.सी. रेड्डी","text_en":"के.सी. रेड्डी"},{"id":"D","text":"एन.एन. वांचू","text_en":"एन.एन. वांचू"}]', '0', '✅ **Correct Logic**: डॉ. बी. पट्टाभि सीतारमैया 1 नवंबर 1956 को मध्य प्रदेश के गठन के समय पहले राज्यपाल बने।
💡 **Exam Fact**: सबसे लंबी अवधि तक राज्यपाल रहने का रिकॉर्ड ''हरी विनायक पाटस्कर'' के नाम है।
🧠 **Memory Tip**: P-S (First Governor - Pattabhi Sitaramayya).
🚫 **Scam Alert**: रविशंकर शुक्ल पहले मुख्यमंत्री थे, राज्यपाल पट्टाभि थे।', 2, 0, 1, NULL, 'Who was the first Governor of Madhya Pradesh?', '✅ **Correct Logic**: Dr. B. Pattabhi Sitaramayya became the first Governor upon the formation of MP on Nov 1, 1956.
💡 **Exam Fact**: Hari Vinayak Pataskar holds the record for the longest tenure as Governor of MP.
🧠 **Memory Tip**: P-S (First Governor - Pattabhi Sitaramayya).
🚫 **Scam Alert**: Ravishankar Shukla was the first CM; Pattabhi was the first Governor.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('571079c3-f622-4c58-8272-f7cea9ce5fa6', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश विधानसभा भवन का नाम क्या है और इसके वास्तुकार कौन थे?', '[{"id":"A","text":"मिंटो हॉल; लुटियंस","text_en":"मिंटो हॉल; लुटियंस"},{"id":"B","text":"इंदिरा गांधी विधान भवन; चार्ल्स कोरिया","text_en":"इंदिरा गांधी विधान भवन; चार्ल्स कोरिया"},{"id":"C","text":"सतपुड़ा भवन; राज रेवाल","text_en":"सतपुड़ा भवन; राज रेवाल"},{"id":"D","text":"वल्लभ भवन; एडवर्ड लुटियंस","text_en":"वल्लभ भवन; एडवर्ड लुटियंस"}]', '1', '✅ **Correct Logic**: वर्तमान विधानसभा भवन ''इंदिरा गांधी विधान भवन'' कहलाता है, जिसे प्रसिद्ध वास्तुकार चार्ल्स कोरिया ने डिजाइन किया था।
💡 **Exam Fact**: 1996 में इसे वास्तुकला के लिए ''आगा खान अवार्ड'' प्राप्त हुआ था।
🧠 **Memory Tip**: I-C (Indira-Charles).
🚫 **Scam Alert**: ''मिंटो हॉल'' पुराना विधानसभा भवन था, नया भवन 1996 में बना।', 2, 0, 2, NULL, 'What is the name of the MP Legislative Assembly building and who was its architect?', '✅ **Correct Logic**: The current assembly building is named ''Indira Gandhi Vidhan Bhawan'', designed by Charles Correa.
💡 **Exam Fact**: It received the prestigious Aga Khan Award for Architecture in 1996.
🧠 **Memory Tip**: I-C (Indira-Charles).
🚫 **Scam Alert**: ''Minto Hall'' was the old assembly building; the new one was inaugurated in 1996.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('362462e5-d3cb-4007-9c54-6332d32f30b3', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश में अब तक कितनी बार ''राष्ट्रपति शासन'' (President''s Rule) लगाया गया है?', '[{"id":"A","text":"1 बार","text_en":"1 बार"},{"id":"B","text":"2 बार","text_en":"2 बार"},{"id":"C","text":"3 बार","text_en":"3 बार"},{"id":"D","text":"4 बार","text_en":"4 बार"}]', '2', '✅ **Correct Logic**: मध्य प्रदेश में 3 बार राष्ट्रपति शासन लगा है: 1977, 1980 और 1992 में।
💡 **Exam Fact**: तीसरा राष्ट्रपति शासन (1992) बाबरी मस्जिद विध्वंस के बाद पटवा सरकार के समय लगा था।
🧠 **Memory Tip**: 3 Times - 77, 80, 92.
🚫 **Scam Alert**: 2020 में सरकार गिरने पर राष्ट्रपति शासन नहीं लगा था, केवल मुख्यमंत्री ने इस्तीफा दिया था।', 2, 0, 3, NULL, 'How many times has ''President''s Rule'' been imposed in Madhya Pradesh so far?', '✅ **Correct Logic**: President''s Rule has been imposed thrice in MP: 1977, 1980, and 1992.
💡 **Exam Fact**: The third instance (1992) occurred during Sunderlal Patwa''s government following the Babri Masjid incident.
🧠 **Memory Tip**: Remember the trio: 77, 80, 92.
🚫 **Scam Alert**: There was no President''s Rule during the 2020 government shift; it was a transition through resignation.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ae282f3d-9f28-4fa6-9c37-89ea7295b580', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश विधानसभा में कुल कितनी सीटें हैं और उनमें से कितनी SC और ST के लिए आरक्षित हैं?', '[{"id":"A","text":"230; (SC-35, ST-47)","text_en":"230; (SC-35, ST-47)"},{"id":"B","text":"230; (SC-47, ST-35)","text_en":"230; (SC-47, ST-35)"},{"id":"C","text":"250; (SC-30, ST-50)","text_en":"250; (SC-30, ST-50)"},{"id":"D","text":"231; (SC-35, ST-47)","text_en":"231; (SC-35, ST-47)"}]', '0', '✅ **Correct Logic**: कुल 230 सीटें हैं। अनुसूचित जाति (SC) के लिए 35 और अनुसूचित जनजाति (ST) के लिए 47 सीटें आरक्षित हैं।
💡 **Exam Fact**: ST के लिए 47 सीटें पूरे भारत में किसी भी राज्य विधानसभा में सर्वाधिक हैं।
🧠 **Memory Tip**: ST is more (47) because MP has more tribal population.
🚫 **Scam Alert**: अब एंग्लो-इंडियन की 1 अतिरिक्त सीट का प्रावधान खत्म हो गया है, इसलिए कुल 230 ही हैं।', 2, 0, 4, NULL, 'What is the total number of seats in the MP Legislative Assembly and how many are reserved for SC and ST?', '✅ **Correct Logic**: There are 230 total seats. 35 are reserved for SC and 47 for ST.
💡 **Exam Fact**: MP has the highest number of reserved seats for ST (47) in any state assembly in India.
🧠 **Memory Tip**: ST > SC because MP is a tribal-rich state.
🚫 **Scam Alert**: The Anglo-Indian nomination is abolished; total capacity is now strictly 230.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7a80a8f2-3749-40d0-a879-74b464e96ccc', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'प्रथम व्यक्तित्व और उनके संबंधित पदों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: शुक्ल जी पहले CM, दुबे जी पहले अध्यक्ष (विधि पुरुष), सरवटे जी पहले उपाध्यक्ष और हिदायतुल्ला जी पहले CJ (बाद में भारत के राष्ट्रपति भी बने)।
💡 **Exam Fact**: कुंजीलाल दुबे को ''मध्य प्रदेश का विधि पुरुष'' कहा जाता है।
🧠 **Memory Tip**: CM-Shukla, Speaker-Dubey.
🚫 **Scam Alert**: निर्मला बुच पहली महिला मुख्य सचिव थीं, मुख्यमंत्री नहीं।', 2, 0, 5, NULL, 'Match the first personalities and their respective positions:', '✅ **Correct Logic**: Shukla was first CM, Dubey first Speaker, Sarwate first Dy Speaker, and Hidayatullah first CJ (later President of India).
💡 **Exam Fact**: Kunjilal Dubey is famously known as the ''Law Man'' of Madhya Pradesh.
🧠 **Memory Tip**: Shukla (CM) and Dubey (Speaker) are the core pioneers.
🚫 **Scam Alert**: Nirmala Buch was the first female Chief Secretary, not CM.', 60, 'matching', '[{"id":"(1)","label":"पंडित रविशंकर शुक्ल","match":"प्रथम मुख्यमंत्री","matchId":"(a)"},{"id":"(2)","label":"पंडित कुंजीलाल दुबे","match":"प्रथम विधानसभा अध्यक्ष","matchId":"(b)"},{"id":"(3)","label":"विष्णु विनायक सरवटे","match":"प्रथम उपाध्यक्ष","matchId":"(c)"},{"id":"(4)","label":"मोहम्मद हिदायतुल्ला","match":"प्रथम मुख्य न्यायाधीश","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('56714d16-d24b-4d1c-83d2-9bb3215ad97c', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश विधानसभा के ''नेता प्रतिपक्ष'' (Leader of Opposition) बनने वाले पहले व्यक्ति कौन थे?', '[{"id":"A","text":"विष्णुनाथ यादवराव तामस्कर","text_en":"विष्णुनाथ यादवराव तामस्कर"},{"id":"B","text":"वीरेंद्र कुमार सकलेचा","text_en":"वीरेंद्र कुमार सकलेचा"},{"id":"C","text":"श्यामाचरण शुक्ल","text_en":"श्यामाचरण शुक्ल"},{"id":"D","text":"कैलाश जोशी","text_en":"कैलाश जोशी"}]', '0', '✅ **Correct Logic**: विष्णुनाथ यादवराव तामस्कर मध्य प्रदेश विधानसभा के पहले नेता प्रतिपक्ष थे।
💡 **Exam Fact**: जमुना देवी मध्य प्रदेश की पहली महिला नेता प्रतिपक्ष थीं।
🧠 **Memory Tip**: Vishnu (God) - First in Opposition.
🚫 **Scam Alert**: कैलाश जोशी पहले ''गैर-कांग्रेसी'' मुख्यमंत्री थे, नेता प्रतिपक्ष नहीं।', 2, 0, 6, NULL, 'Who was the first person to become the ''Leader of Opposition'' in the MP Legislative Assembly?', '✅ **Correct Logic**: Vishwanath Yadavrao Tamaskar was the first Leader of Opposition in the MP Assembly.
💡 **Exam Fact**: Jamuna Devi was the first female Leader of Opposition in MP.
🧠 **Memory Tip**: Think of Vishnu leading the second front.
🚫 **Scam Alert**: Kailash Joshi was the first non-Congress CM, not the first LOP.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1175b924-e894-41a0-9238-8a0d9eeca50d', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश उच्च न्यायालय की ''खंडपीठ'' (Bench) कहाँ-कहाँ स्थित हैं?', '[{"id":"A","text":"भोपाल और इंदौर","text_en":"भोपाल और इंदौर"},{"id":"B","text":"इंदौर और ग्वालियर","text_en":"इंदौर और ग्वालियर"},{"id":"C","text":"जबलपुर और ग्वालियर","text_en":"जबलपुर और ग्वालियर"},{"id":"D","text":"भोपाल और जबलपुर","text_en":"भोपाल और जबलपुर"}]', '1', '✅ **Correct Logic**: मुख्य पीठ जबलपुर में है, जबकि दो खंडपीठ इंदौर और ग्वालियर में स्थित हैं।
💡 **Exam Fact**: भोपाल में तीसरी खंडपीठ प्रस्तावित है।
🧠 **Memory Tip**: Main Seat - Jabalpur (J-J); Branches - I and G.
🚫 **Scam Alert**: भोपाल में फिलहाल कोई खंडपीठ कार्यात्मक नहीं है।', 2, 0, 7, NULL, 'Where are the ''Benches'' of the Madhya Pradesh High Court located?', '✅ **Correct Logic**: The main seat is in Jabalpur, while the two permanent benches are in Indore and Gwalior.
💡 **Exam Fact**: A third bench is proposed for Bhopal.
🧠 **Memory Tip**: Main - Jabalpur; Benches - Indore & Gwalior (I-G).
🚫 **Scam Alert**: No bench is currently functional in Bhopal; it''s only proposed.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('337a1e71-b64a-451c-9e47-cfbe377ab7fb', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश की पहली महिला मुख्यमंत्री कौन थी?', '[{"id":"A","text":"सरला ग्रेवाल","text_en":"सरला ग्रेवाल"},{"id":"B","text":"उमा भारती","text_en":"उमा भारती"},{"id":"C","text":"विमला शर्मा","text_en":"विमला शर्मा"},{"id":"D","text":"जमुना देवी","text_en":"जमुना देवी"}]', '1', '✅ **Correct Logic**: सुश्री उमा भारती 2003 में मध्य प्रदेश की पहली महिला मुख्यमंत्री बनीं।
💡 **Exam Fact**: सरला ग्रेवाल मध्य प्रदेश की पहली महिला राज्यपाल थीं।
🧠 **Memory Tip**: Uma (Power) - First CM.
🚫 **Scam Alert**: जमुना देवी पहली महिला उपमुख्यमंत्री और नेता प्रतिपक्ष थीं।', 2, 0, 8, NULL, 'Who was the first female Chief Minister of Madhya Pradesh?', '✅ **Correct Logic**: Ms. Uma Bharti became the first female CM of Madhya Pradesh in 2003.
💡 **Exam Fact**: Sarla Grewal was the first female Governor of the state.
🧠 **Memory Tip**: Uma (associated with leadership/shakti) was the first CM.
🚫 **Scam Alert**: Jamuna Devi was the first female Deputy CM and LOP.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0725a6c4-3933-4e69-a563-2691e1c92ff7', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश के किस मुख्यमंत्री का कार्यकाल सबसे कम (मात्र 1 दिन) रहा?', '[{"id":"A","text":"नरेश चंद्र सिंह","text_en":"नरेश चंद्र सिंह"},{"id":"B","text":"अर्जुन सिंह","text_en":"अर्जुन सिंह"},{"id":"C","text":"भगवंतराव मंडलोई","text_en":"भगवंतराव मंडलोई"},{"id":"D","text":"कैलाश जोशी","text_en":"कैलाश जोशी"}]', '1', '✅ **Correct Logic**: अर्जुन सिंह 1985 में केवल 1 दिन के लिए मुख्यमंत्री रहे थे (शपथ लेने के अगले ही दिन पंजाब का राज्यपाल बना दिया गया था)।
💡 **Exam Fact**: नरेश चंद्र सिंह मध्य प्रदेश के पहले आदिवासी मुख्यमंत्री थे।
🧠 **Memory Tip**: Arjun (Arrow) - Swift 1-day entry.
🚫 **Scam Alert**: शिवराज सिंह चौहान के नाम सबसे लंबे समय तक मुख्यमंत्री रहने का रिकॉर्ड है।', 2, 0, 9, NULL, 'Which CM of Madhya Pradesh had the shortest tenure (only 1 day)?', '✅ **Correct Logic**: Arjun Singh served as CM for only one day in 1985 before being appointed as the Governor of Punjab the next day.
💡 **Exam Fact**: Raja Naresh Chandra Singh was the first tribal CM of MP.
🧠 **Memory Tip**: Arjun''s 1-day shot.
🚫 **Scam Alert**: Shivraj Singh Chouhan holds the record for the longest-serving CM.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4734f213-3622-4462-bc35-74e9e0ea8a72', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'राज्यपाल द्वारा राज्य विधानसभा में 1 ''एंग्लो-इंडियन'' सदस्य को मनोनीत करने की शक्ति किस अनुच्छेद में थी, जिसे अब समाप्त कर दिया गया है?', '[{"id":"A","text":"अनुच्छेद 330","text_en":"अनुच्छेद 330"},{"id":"B","text":"अनुच्छेद 331","text_en":"अनुच्छेद 331"},{"id":"C","text":"अनुच्छेद 333","text_en":"अनुच्छेद 333"},{"id":"D","text":"अनुच्छेद 332","text_en":"अनुच्छेद 332"}]', '2', '✅ **Correct Logic**: अनुच्छेद 333 राज्यपाल को विधानसभा में एक एंग्लो-इंडियन सदस्य मनोनीत करने की शक्ति देता था।
💡 **Exam Fact**: 104वें संविधान संशोधन (2020) द्वारा इस प्रावधान को समाप्त कर दिया गया है।
🧠 **Memory Tip**: 331 (Lok Sabha) vs 333 (Assembly).
🚫 **Scam Alert**: 331 लोकसभा में राष्ट्रपति के मनोनयन के लिए था।', 2, 0, 10, NULL, 'Under which Article did the Governor have the power to nominate 1 Anglo-Indian member, which is now abolished?', '✅ **Correct Logic**: Article 333 empowered the Governor to nominate one Anglo-Indian member to the Assembly.
💡 **Exam Fact**: This provision was abolished by the 104th Constitutional Amendment Act (2020).
🧠 **Memory Tip**: 331 (Union) / 333 (State).
🚫 **Scam Alert**: Article 331 was for the President''s nomination power in the Lok Sabha.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('c92c77ec-e667-4a86-8960-e84404e2a00e', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'मध्य प्रदेश पंचायती राज अधिनियम, 1993 के तहत ''ग्राम सभा'' का गठन किस अनुच्छेद/धारा के प्रावधानों के अनुरूप किया गया है?', '[{"id":"A","text":"अनुच्छेद 243A","text_en":"अनुच्छेद 243A"},{"id":"B","text":"अनुच्छेद 243B","text_en":"अनुच्छेद 243B"},{"id":"C","text":"अनुच्छेद 243C","text_en":"अनुच्छेद 243C"},{"id":"D","text":"अनुच्छेद 243D","text_en":"अनुच्छेद 243D"}]', '0', '✅ **Correct Logic**: अनुच्छेद 243A ग्राम सभा की शक्तियों और कार्यों का वर्णन करता है। ग्राम सभा पंचायत राज की आधारभूत इकाई है।
💡 **Exam Fact**: ग्राम सभा में गाँव के सभी ''पंजीकृत मतदाता'' सदस्य होते हैं।
🧠 **Memory Tip**: A for Assembly (Gram Sabha is the local assembly).
🚫 **Scam Alert**: 243B पंचायतों के गठन (Constitution) से संबंधित है, सभा से नहीं।', 2, 0, 1, NULL, 'Under which Article/Section provisions was the ''Gram Sabha'' constituted under the MP Panchayati Raj Act, 1993?', '✅ **Correct Logic**: Article 243A describes the powers and functions of the Gram Sabha, the foundational unit of Panchayati Raj.
💡 **Exam Fact**: All registered voters of the village are members of the Gram Sabha.
🧠 **Memory Tip**: A for Assembly (Gram Sabha is the village assembly).
🚫 **Scam Alert**: 243B relates to the constitution of Panchayats, not the Gram Sabha itself.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('54f5616b-c214-43a0-8c58-c5634d7a60a4', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'मध्य प्रदेश में पंचायती राज व्यवस्था में महिलाओं के लिए कितने प्रतिशत आरक्षण का प्रावधान है?', '[{"id":"A","text":"33%","text_en":"33%"},{"id":"B","text":"50%","text_en":"50%"},{"id":"C","text":"25%","text_en":"25%"},{"id":"D","text":"40%","text_en":"40%"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश देश का पहला राज्य था जिसने पंचायती राज संस्थाओं में महिलाओं को 50% आरक्षण प्रदान किया।
💡 **Exam Fact**: 73वें संशोधन के अनुसार न्यूनतम 33% अनिवार्य है, लेकिन MP ने इसे बढ़ाकर 50% किया है।
🧠 **Memory Tip**: MP = Max Power for women (50%).
🚫 **Scam Alert**: संविदा शिक्षक भर्ती में भी महिलाओं को 50% आरक्षण प्राप्त है, इसे पंचायत से जोड़कर याद रख सकते हैं।', 2, 0, 2, NULL, 'What is the percentage of reservation for women in the Panchayati Raj system in Madhya Pradesh?', '✅ **Correct Logic**: MP was the first state in India to provide 50% reservation for women in PRIs.
💡 **Exam Fact**: While the 73rd Amendment mandates a minimum of 33%, MP increased it to 50%.
🧠 **Memory Tip**: MP gave Equal Power (50-50).
🚫 **Scam Alert**: Don''t confuse it with the national minimum; for MP specifically, the answer is 50%.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bdf44056-af0c-4d26-b586-241671d3b3f6', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'जनपद पंचायत'' के मुख्य कार्यपालन अधिकारी (CEO) की नियुक्ति किसके द्वारा की जाती है?', '[{"id":"A","text":"जनपद पंचायत अध्यक्ष","text_en":"जनपद पंचायत अध्यक्ष"},{"id":"B","text":"राज्य सरकार","text_en":"राज्य सरकार"},{"id":"C","text":"कलेक्टर","text_en":"कलेक्टर"},{"id":"D","text":"पंचायत एवं ग्रामीण विकास मंत्री","text_en":"पंचायत एवं ग्रामीण विकास मंत्री"}]', '1', '✅ **Correct Logic**: जनपद पंचायत का CEO एक राज्य सरकार का अधिकारी होता है, जिसकी नियुक्ति राज्य सरकार द्वारा की जाती है।
💡 **Exam Fact**: जिला पंचायत के CEO की नियुक्ति भी राज्य सरकार करती है (आमतौर पर IAS या वरिष्ठ राज्य सेवा अधिकारी)।
🧠 **Memory Tip**: CEO = Govt Official = State selection.
🚫 **Scam Alert**: अध्यक्ष प्रशासनिक अधिकारी नहीं बल्कि निर्वाचित प्रतिनिधि होता है।', 2, 0, 3, NULL, 'Who appoints the Chief Executive Officer (CEO) of a Janpad Panchayat?', '✅ **Correct Logic**: The CEO of a Janpad Panchayat is a government official appointed by the State Government.
💡 **Exam Fact**: The CEO of Zila Panchayat is also appointed by the State (usually an IAS or senior SAS officer).
🧠 **Memory Tip**: CEO is an employee of the state, hence state-appointed.
🚫 **Scam Alert**: The Chairperson is an elected representative and does not appoint the CEO.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('72412006-9978-4dfe-a6c3-31d9eb53406f', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'मध्य प्रदेश में पंचायत चुनाव कराने का दायित्व किसका है?', '[{"id":"A","text":"भारत निर्वाचन आयोग","text_en":"भारत निर्वाचन आयोग"},{"id":"B","text":"राज्य निर्वाचन आयोग","text_en":"राज्य निर्वाचन आयोग"},{"id":"C","text":"राज्य सरकार","text_en":"राज्य सरकार"},{"id":"D","text":"कलेक्टर","text_en":"कलेक्टर"}]', '1', '✅ **Correct Logic**: अनुच्छेद 243K के तहत राज्य निर्वाचन आयोग (SEC) पंचायतों और नगरपालिकाओं के चुनाव कराने के लिए जिम्मेदार है।
💡 **Exam Fact**: मध्य प्रदेश राज्य निर्वाचन आयोग के पहले आयुक्त एन.बी. लोहानी थे।
🧠 **Memory Tip**: Local Body = Local (State) Commission.
🚫 **Scam Alert**: भारत निर्वाचन आयोग केवल संसद और विधानसभा के चुनाव कराता है।', 2, 0, 4, NULL, 'Who is responsible for conducting Panchayat elections in Madhya Pradesh?', '✅ **Correct Logic**: Under Article 243K, the State Election Commission (SEC) is responsible for the conduct of local body elections.
💡 **Exam Fact**: N.B. Lohani was the first SEC commissioner of MP.
🧠 **Memory Tip**: Local elections need the Local (State) Commission.
🚫 **Scam Alert**: The Election Commission of India only handles Parliament and Assembly elections.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6880ed76-0e93-4e08-9a6c-60a5ac3c7e6c', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'पंचायती राज के स्तर और उनकी न्यूनतम जनसंख्या सीमा (MP संदर्भ) को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: MP में 1000 की आबादी पर एक ग्राम पंचायत का प्रावधान है। जनपद विकासखंड स्तर पर और जिला पंचायत जिला स्तर पर होती है।
💡 **Exam Fact**: वार्डों की संख्या ग्राम पंचायत में न्यूनतम 10 और अधिकतम 20 हो सकती है।
🧠 **Memory Tip**: 1K - 5K - 50K (The growth of tiers).
🚫 **Scam Alert**: जनपद और तहसील में अंतर होता है; जनपद विकासखंड (Block) स्तर पर होती है।', 2, 0, 5, NULL, 'Match the tiers of Panchayati Raj and their minimum population limits (MP context):', '✅ **Correct Logic**: In MP, a Gram Panchayat is formed for a population of 1000. Janpad is at the Block level and Zila at the District level.
💡 **Exam Fact**: A Gram Panchayat can have between 10 and 20 wards.
🧠 **Memory Tip**: 1K for Gram, 5K for Janpad, 50K for Zila.
🚫 **Scam Alert**: Janpad is aligned with the Block, not necessarily the Tehsil boundary.', 60, 'matching', '[{"id":"(1)","label":"ग्राम पंचायत","match":"1000 से अधिक आबादी","matchId":"(a)"},{"id":"(2)","label":"जनपद पंचायत","match":"5000 से अधिक आबादी (विकासखंड स्तर)","matchId":"(b)"},{"id":"(3)","label":"जिला पंचायत","match":"50000 से अधिक आबादी (जिला स्तर)","matchId":"(c)"},{"id":"(4)","label":"ग्राम सभा","match":"सभी पंजीकृत मतदाता","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('63492522-6d23-4100-aa4d-c24552148a8b', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'मध्य प्रदेश में ''पंचायती राज दिवस'' किस तिथि को मनाया जाता है?', '[{"id":"A","text":"24 अप्रैल","text_en":"24 अप्रैल"},{"id":"B","text":"25 जनवरी","text_en":"25 जनवरी"},{"id":"C","text":"26 जनवरी","text_en":"26 जनवरी"},{"id":"D","text":"1 नवंबर","text_en":"1 नवंबर"}]', '0', '✅ **Correct Logic**: 24 अप्रैल 1993 को 73वां संविधान संशोधन लागू हुआ था, इसलिए इसे राष्ट्रीय पंचायती राज दिवस के रूप में मनाया जाता है।
💡 **Exam Fact**: मध्य प्रदेश ने अपना पंचायती राज अधिनियम 30 दिसंबर 1993 को पारित किया था।
🧠 **Memory Tip**: April 24 - Powers to the people.
🚫 **Scam Alert**: 25 जनवरी मतदाता दिवस है, इसे पंचायत दिवस से न जोड़ें।', 2, 0, 6, NULL, 'On which date is ''Panchayati Raj Day'' celebrated in Madhya Pradesh?', '✅ **Correct Logic**: The 73rd Amendment came into force on April 24, 1993, which is why it''s observed as National Panchayati Raj Day.
💡 **Exam Fact**: MP passed its specific state act on December 30, 1993.
🧠 **Memory Tip**: 24/4 - Foundations of democracy.
🚫 **Scam Alert**: Jan 25 is Voters'' Day, don''t confuse it with Panchayat Day.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('55d7dac1-d9fc-4cb2-bc18-ef366f338ccf', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'पंचायतों की वित्तीय स्थिति की समीक्षा के लिए ''राज्य वित्त आयोग'' का गठन किस अनुच्छेद के तहत किया जाता है?', '[{"id":"A","text":"अनुच्छेद 243-I","text_en":"अनुच्छेद 243-I"},{"id":"B","text":"अनुच्छेद 243-Y","text_en":"अनुच्छेद 243-Y"},{"id":"C","text":"अनुच्छेद 243-K","text_en":"अनुच्छेद 243-K"},{"id":"D","text":"अनुच्छेद 280","text_en":"अनुच्छेद 280"}]', '0', '✅ **Correct Logic**: अनुच्छेद 243-I पंचायतों के लिए वित्त आयोग का प्रावधान करता है। राज्यपाल प्रत्येक 5 वर्ष में इसका गठन करता है।
💡 **Exam Fact**: अनुच्छेद 243-Y नगरपालिकाओं के लिए वित्त आयोग से संबंधित है।
🧠 **Memory Tip**: I for Income (Finance).
🚫 **Scam Alert**: अनुच्छेद 280 केंद्रीय वित्त आयोग के लिए है, राज्य के लिए नहीं।', 2, 0, 7, NULL, 'Under which Article is the ''State Finance Commission'' constituted to review the financial position of Panchayats?', '✅ **Correct Logic**: Article 243-I mandates the State Finance Commission for Panchayats, constituted by the Governor every 5 years.
💡 **Exam Fact**: Article 243-Y deals with the Finance Commission for Municipalities.
🧠 **Memory Tip**: ''I'' for Income/Investment (Finance).
🚫 **Scam Alert**: Article 280 is for the Central Finance Commission, not the State one.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('08392ed8-51da-4b46-a9f5-8e23c9190853', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'मध्य प्रदेश में ग्राम स्वराज की नई व्यवस्था कब लागू की गई थी?', '[{"id":"A","text":"26 जनवरी 2001","text_en":"26 जनवरी 2001"},{"id":"B","text":"15 अगस्त 2001","text_en":"15 अगस्त 2001"},{"id":"C","text":"2 अक्टूबर 2001","text_en":"2 अक्टूबर 2001"},{"id":"D","text":"1 नवंबर 2000","text_en":"1 नवंबर 2000"}]', '0', '✅ **Correct Logic**: 26 जनवरी 2001 को मध्य प्रदेश में ''ग्राम स्वराज'' योजना लागू की गई थी, जिसका उद्देश्य ग्राम सभा को अधिक शक्तिशाली बनाना था।
💡 **Exam Fact**: इसके तहत ग्राम स्तर पर कार्य निष्पादन के लिए 8 समितियां बनाई गई थीं।
🧠 **Memory Tip**: Republic Day 2001 - Real power to the villages.
🚫 **Scam Alert**: यह 1993 के मूल अधिनियम के बाद का एक महत्वपूर्ण संशोधन/सुधार था।', 2, 0, 8, NULL, 'When was the new system of ''Gram Swaraj'' implemented in Madhya Pradesh?', '✅ **Correct Logic**: Gram Swaraj was launched on Jan 26, 2001, to empower the Gram Sabha further.
💡 **Exam Fact**: It introduced 8 functional committees at the village level for execution.
🧠 **Memory Tip**: 2001 Odyssey - Power to the People on Republic Day.
🚫 **Scam Alert**: This was a major evolutionary step after the original 1993 Act.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1aa3f93f-1a5b-4d1d-ac6c-8fb688b180c5', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', '73वें संविधान संशोधन अधिनियम को लागू करने वाला देश का पहला राज्य कौन सा है?', '[{"id":"A","text":"राजस्थान","text_en":"राजस्थान"},{"id":"B","text":"मध्य प्रदेश","text_en":"मध्य प्रदेश"},{"id":"C","text":"आंध्र प्रदेश","text_en":"आंध्र प्रदेश"},{"id":"D","text":"गुजरात","text_en":"गुजरात"}]', '1', '✅ **Correct Logic**: राजस्थान के नागौर में पंचायती राज की ''शुरुआत'' (1959) हुई थी, लेकिन 73वें ''संवैधानिक संशोधन'' को लागू करने वाला पहला राज्य मध्य प्रदेश है।
💡 **Exam Fact**: MP ने अपना अधिनियम 1993 में ही पारित कर दिया था।
🧠 **Memory Tip**: Started in Rajasthan, Legalized first in MP.
🚫 **Scam Alert**: प्रश्न में ''संशोधन अधिनियम'' शब्द को ध्यान से देखें।', 2, 0, 9, NULL, 'Which is the first state in India to implement the 73rd Constitutional Amendment Act?', '✅ **Correct Logic**: While Panchayati Raj ''started'' in Rajasthan (1959), MP was the first to implement the ''73rd Amendment'' after it became constitutional law.
💡 **Exam Fact**: MP''s act was passed swiftly in 1993.
🧠 **Memory Tip**: Rajasthan was the laboratory, MP was the first legal adopter.
🚫 **Scam Alert**: Differentiate between the ''Inauguration'' (1959) and the ''Amendment implementation'' (1993).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8769ec3b-8a4e-42fc-b529-f40893ade109', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'जिला पंचायत के अध्यक्ष का चुनाव किस प्रकार होता है?', '[{"id":"A","text":"प्रत्यक्ष रूप से जनता द्वारा","text_en":"प्रत्यक्ष रूप से जनता द्वारा"},{"id":"B","text":"अप्रत्यक्ष रूप से निर्वाचित सदस्यों द्वारा","text_en":"अप्रत्यक्ष रूप से निर्वाचित सदस्यों द्वारा"},{"id":"C","text":"कलेक्टर द्वारा मनोनीत","text_en":"कलेक्टर द्वारा मनोनीत"},{"id":"D","text":"राज्य सरकार द्वारा नियुक्त","text_en":"राज्य सरकार द्वारा नियुक्त"}]', '1', '✅ **Correct Logic**: जिला पंचायत के सदस्य प्रत्यक्ष चुने जाते हैं, लेकिन वे आपस में से एक अध्यक्ष का चुनाव ''अप्रत्यक्ष'' रूप से करते हैं।
💡 **Exam Fact**: सरपंच का चुनाव मध्य प्रदेश में प्रत्यक्ष (Direct) होता है।
🧠 **Memory Tip**: Bottom (Sarpanch) - Direct; Top (Zila Head) - Indirect.
🚫 **Scam Alert**: सदस्य प्रत्यक्ष होते हैं पर अध्यक्ष अप्रत्यक्ष।', 2, 0, 10, NULL, 'How is the President of the Zila Panchayat elected?', '✅ **Correct Logic**: Members of the Zila Panchayat are elected directly, but they elect the President from among themselves ''indirectly''.
💡 **Exam Fact**: In MP, the Sarpanch is elected directly by the people.
🧠 **Memory Tip**: Bottom tier head is Direct, Upper tier heads are Indirect.
🚫 **Scam Alert**: Only the members are direct; don''t assume the President is elected directly by the public.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('03d417a5-ede3-4a4b-9c55-73352fedb232', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'मध्य प्रदेश की पहली ''नगर पालिका'' (Municipality) कहाँ और कब स्थापित की गई थी?', '[{"id":"A","text":"जबलपुर; 1864","text_en":"जबलपुर; 1864"},{"id":"B","text":"दतिया; 1907","text_en":"दतिया; 1907"},{"id":"C","text":"ग्वालियर; 1887","text_en":"ग्वालियर; 1887"},{"id":"D","text":"इंदौर; 1870","text_en":"इंदौर; 1870"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश की पहली नगर पालिका 1907 में दतिया में स्थापित की गई थी।
💡 **Exam Fact**: मध्य प्रदेश का पहला नगर निगम (Municipal Corporation) जबलपुर में 1864 में बना था।
🧠 **Memory Tip**: D-P (Datia-Palika) vs J-N (Jabalpur-Nigam).
🚫 **Scam Alert**: ''नगर निगम'' और ''नगर पालिका'' के बीच के अंतर को ध्यान से समझें; जबलपुर निगम है, दतिया पालिका।', 2, 0, 1, NULL, 'Where and when was the first ''Municipality'' of Madhya Pradesh established?', '✅ **Correct Logic**: The first Municipality of Madhya Pradesh was established in Datia in 1907.
💡 **Exam Fact**: The first Municipal Corporation in MP was formed in Jabalpur in 1864.
🧠 **Memory Tip**: D-P (Datia-Palika) vs J-N (Jabalpur-Nigam).
🚫 **Scam Alert**: Pay close attention to the difference between ''Corporation'' and ''Municipality''; Jabalpur is the former, Datia the latter.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5612b2b5-c4e3-40d6-aed1-4f34651312ad', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', '74वें संविधान संशोधन के तहत नगर निगम (Municipal Corporation) के लिए न्यूनतम जनसंख्या कितनी निर्धारित की गई है?', '[{"id":"A","text":"1 लाख से अधिक","text_en":"1 लाख से अधिक"},{"id":"B","text":"5 लाख से अधिक","text_en":"5 लाख से अधिक"},{"id":"C","text":"10 लाख से अधिक","text_en":"10 लाख से अधिक"},{"id":"D","text":"50 हजार से अधिक","text_en":"50 हजार से अधिक"}]', '0', '✅ **Correct Logic**: 1 लाख से अधिक जनसंख्या वाले बड़े नगरीय क्षेत्रों को ''नगर निगम'' की श्रेणी में रखा जाता है।
💡 **Exam Fact**: वर्तमान में मध्य प्रदेश में 17 नगर निगम हैं (भिंड प्रस्तावित है)।
🧠 **Memory Tip**: 1 Lakh = 1st Tier (Corporation).
🚫 **Scam Alert**: नगर पालिका के लिए सीमा 20,000 से 1 लाख के बीच होती है।', 2, 0, 2, NULL, 'What is the minimum population prescribed for a Municipal Corporation under the 74th Amendment?', '✅ **Correct Logic**: Large urban areas with a population exceeding 1 lakh are categorized as Municipal Corporations.
💡 **Exam Fact**: There are currently 17 Municipal Corporations in MP (Bhind is proposed).
🧠 **Memory Tip**: 1 Lakh = 1st Tier of urban governance.
🚫 **Scam Alert**: The limit for a Municipality is between 20,000 and 1 lakh.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('198651be-47d9-4f53-8c3a-9b9c561b31a9', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'नगर निगम का प्रशासनिक प्रमुख (Administrative Head) कौन होता है?', '[{"id":"A","text":"महापौर (Mayor)","text_en":"महापौर (Mayor)"},{"id":"B","text":"नगर निगम आयुक्त (Commissioner)","text_en":"नगर निगम आयुक्त (Commissioner)"},{"id":"C","text":"सभापति","text_en":"सभापति"},{"id":"D","text":"कलेक्टर","text_en":"कलेक्टर"}]', '1', '✅ **Correct Logic**: नगर निगम आयुक्त (IAS अधिकारी) प्रशासनिक प्रमुख होता है, जबकि महापौर राजनीतिक प्रमुख होता है।
💡 **Exam Fact**: आयुक्त की नियुक्ति राज्य सरकार द्वारा की जाती है।
🧠 **Memory Tip**: Commissioner = Command/Admin; Mayor = Member/Political.
🚫 **Scam Alert**: महापौर का चुनाव मध्य प्रदेश में वर्तमान में प्रत्यक्ष (Directly) होता है।', 2, 0, 3, NULL, 'Who is the Administrative Head of a Municipal Corporation?', '✅ **Correct Logic**: The Municipal Commissioner (an IAS officer) is the administrative head, while the Mayor is the political head.
💡 **Exam Fact**: The Commissioner is appointed by the State Government.
🧠 **Memory Tip**: Commissioner = Controls Admin; Mayor = Mandated by people.
🚫 **Scam Alert**: In MP, the Mayor is currently elected directly by the citizens.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('14ef6c30-ff03-49ad-9633-9bf49af524ac', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', '74वें संविधान संशोधन अधिनियम द्वारा संविधान में कौन सी अनुसूची जोड़ी गई थी?', '[{"id":"A","text":"9वीं अनुसूची","text_en":"9वीं अनुसूची"},{"id":"B","text":"10वीं अनुसूची","text_en":"10वीं अनुसूची"},{"id":"C","text":"11वीं अनुसूची","text_en":"11वीं अनुसूची"},{"id":"D","text":"12वीं अनुसूची","text_en":"12वीं अनुसूची"}]', '3', '✅ **Correct Logic**: 74वें संशोधन (1992) द्वारा 12वीं अनुसूची जोड़ी गई, जिसमें नगर पालिकाओं के लिए 18 विषयों का उल्लेख है।
💡 **Exam Fact**: 11वीं अनुसूची 73वें संशोधन (पंचायती राज) के लिए थी जिसमें 29 विषय हैं।
🧠 **Memory Tip**: 11 (Village) comes before 12 (City).
🚫 **Scam Alert**: 12वीं अनुसूची में विषयों की संख्या 18 है, इसे 29 से भ्रमित न करें।', 2, 0, 4, NULL, 'Which Schedule was added to the Constitution by the 74th Amendment Act?', '✅ **Correct Logic**: The 74th Amendment added the 12th Schedule, which contains 18 functional items for municipalities.
💡 **Exam Fact**: The 11th Schedule belongs to the 73rd Amendment (Panchayats) and has 29 items.
🧠 **Memory Tip**: 11 (Small/Village) -> 12 (Big/City).
🚫 **Scam Alert**: There are 18 subjects in the 12th schedule; don''t confuse this with the 29 for Panchayats.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('31579371-2f65-467e-a3fc-30f6e10bd558', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'नगरीय निकायों और उनकी जनसंख्या सीमा (मध्य प्रदेश संदर्भ) को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: 1 लाख+ पर निगम, 20k-1L पर पालिका और संक्रमणशील क्षेत्रों (5k-20k) के लिए नगर परिषद का प्रावधान है।
💡 **Exam Fact**: मध्य प्रदेश में कुल 5 छावनी बोर्ड (Cantonment Boards) हैं।
🧠 **Memory Tip**: 5k -> 20k -> 1L (The Urban ladder).
🚫 **Scam Alert**: नगर परिषद को पहले नगर पंचायत कहा जाता था।', 2, 0, 5, NULL, 'Match the urban bodies and their population limits (MP context):', '✅ **Correct Logic**: 1L+ for Corp, 20k-1L for Municipality, and 5k-20k for Town Councils (Nagar Parishad).
💡 **Exam Fact**: There are 5 Cantonment Boards in MP.
🧠 **Memory Tip**: 5k -> 20k -> 1L (The urban growth ladder).
🚫 **Scam Alert**: Nagar Parishad was formerly referred to as Nagar Panchayat.', 60, 'matching', '[{"id":"(1)","label":"नगर निगम","match":"1 लाख से अधिक","matchId":"(a)"},{"id":"(2)","label":"नगर पालिका परिषद","match":"20,000 से 1 लाख","matchId":"(b)"},{"id":"(3)","label":"नगर परिषद","match":"5,000 से 20,000","matchId":"(c)"},{"id":"(4)","label":"छावनी बोर्ड (Cantonment)","match":"रक्षा मंत्रालय के अधीन","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('31b2f2b1-6e81-4b3d-9b53-01fcfe23340b', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'नगरीय निकायों के लिए ''जिला योजना समिति'' (District Planning Committee) का गठन किस अनुच्छेद के तहत किया जाता है?', '[{"id":"A","text":"अनुच्छेद 243ZD","text_en":"अनुच्छेद 243ZD"},{"id":"B","text":"अनुच्छेद 243ZE","text_en":"अनुच्छेद 243ZE"},{"id":"C","text":"अनुच्छेद 243ZA","text_en":"अनुच्छेद 243ZA"},{"id":"D","text":"अनुच्छेद 243W","text_en":"अनुच्छेद 243W"}]', '0', '✅ **Correct Logic**: अनुच्छेद 243ZD जिला योजना समिति के गठन का प्रावधान करता है जो जिला स्तर पर विकास योजनाओं का समेकन करती है।
💡 **Exam Fact**: 243ZE ''महानगर योजना समिति'' (Metropolitan Planning Committee) के लिए है।
🧠 **Memory Tip**: ZD (Zila - D for District Planning).
🚫 **Scam Alert**: जिले का प्रभारी मंत्री (Minister in charge) आमतौर पर DPC का अध्यक्ष होता है।', 2, 0, 6, NULL, 'Under which Article is the ''District Planning Committee'' (DPC) constituted for urban bodies?', '✅ **Correct Logic**: Article 243ZD provides for the DPC to consolidate plans prepared by Panchayats and Municipalities.
💡 **Exam Fact**: 243ZE is for Metropolitan Planning Committees.
🧠 **Memory Tip**: Z-D (Zila/District Planning).
🚫 **Scam Alert**: The Minister in Charge of the district usually chairs the DPC.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9fe731a4-df80-4663-9517-7a13cf42e6c2', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'मध्य प्रदेश में नगर निगमों की वार्ड समितियों (Ward Committees) का गठन कितनी जनसंख्या वाले शहरों में अनिवार्य है?', '[{"id":"A","text":"3 लाख या अधिक","text_en":"3 लाख या अधिक"},{"id":"B","text":"1 लाख या अधिक","text_en":"1 लाख या अधिक"},{"id":"C","text":"5 लाख या अधिक","text_en":"5 लाख या अधिक"},{"id":"D","text":"50 हजार या अधिक","text_en":"50 हजार या अधिक"}]', '0', '✅ **Correct Logic**: 74वें संशोधन के अनुसार, 3 लाख या उससे अधिक जनसंख्या वाली नगर पालिकाओं में वार्ड समितियों का गठन अनिवार्य है।
💡 **Exam Fact**: यह विकेंद्रीकरण का एक जमीनी स्तर का उदाहरण है।
🧠 **Memory Tip**: 3 Lakh = 3-Tier (Ward level involvement).
🚫 **Scam Alert**: यह नियम केवल नगर निगमों तक सीमित नहीं है, 3 लाख की आबादी वाली किसी भी नगर पालिका पर लागू होता है।', 2, 0, 7, NULL, 'In which cities of MP is the formation of Ward Committees mandatory based on population?', '✅ **Correct Logic**: According to the 74th Amendment, ward committees are mandatory for municipalities with a population of 3 lakhs or more.
💡 **Exam Fact**: This is a key step towards grass-roots decentralization in cities.
🧠 **Memory Tip**: 3 Lakh rule for the 3rd level of city participation.
🚫 **Scam Alert**: This applies to any municipality meeting the 3-lakh criteria, not just ''Corporations''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('46d6710f-47a4-427a-bc8c-e758d2620768', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'महापौर (Mayor) का कार्यकाल कितने वर्ष का होता है?', '[{"id":"A","text":"5 वर्ष","text_en":"5 वर्ष"},{"id":"B","text":"6 वर्ष","text_en":"6 वर्ष"},{"id":"C","text":"4 वर्ष","text_en":"4 वर्ष"},{"id":"D","text":"2 वर्ष","text_en":"2 वर्ष"}]', '0', '✅ **Correct Logic**: नगर निगम और उसके प्रमुख (महापौर) का कार्यकाल सामान्यतः 5 वर्ष का होता है।
💡 **Exam Fact**: महापौर शहर का प्रथम नागरिक कहलाता है।
🧠 **Memory Tip**: Standard democratic term = 5 years.
🚫 **Scam Alert**: यदि निगम पहले भंग हो जाए, तो चुनाव 6 महीने के भीतर कराने होते हैं।', 2, 0, 8, NULL, 'What is the tenure of the Mayor?', '✅ **Correct Logic**: The tenure of the Municipal Corporation and its Mayor is generally 5 years.
💡 **Exam Fact**: The Mayor is considered the first citizen of the city.
🧠 **Memory Tip**: Standard term = 5 years.
🚫 **Scam Alert**: If a corporation is dissolved earlier, fresh elections must be held within 6 months.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('16caad66-15ea-474d-9b7d-c5abb65d32fb', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'नगरीय निकायों को स्वायत्तता देने के लिए ''मध्य प्रदेश नगर पालिक विधि (संशोधन) अधिनियम'' कब पारित किया गया था?', '[{"id":"A","text":"1994","text_en":"1994"},{"id":"B","text":"1993","text_en":"1993"},{"id":"C","text":"1995","text_en":"1995"},{"id":"D","text":"1992","text_en":"1992"}]', '0', '✅ **Correct Logic**: 74वें संशोधन के अनुरूप मध्य प्रदेश ने 1994 में अपना नया नगरीय निकाय अधिनियम लागू किया।
💡 **Exam Fact**: 30 दिसंबर 1993 को यह पारित हुआ और 1994 से प्रभावी हुआ।
🧠 **Memory Tip**: 94 - The year of implementation for both local bodies.
🚫 **Scam Alert**: 1993 अधिनियम का वर्ष है, लेकिन पूर्ण क्रियान्वयन 1994 में हुआ।', 2, 0, 9, NULL, 'When was the ''MP Municipal Law (Amendment) Act'' passed to give autonomy to urban bodies?', '✅ **Correct Logic**: In alignment with the 74th Amendment, MP implemented its new urban bodies act in 1994.
💡 **Exam Fact**: It was passed on Dec 30, 1993, and became effective in 1994.
🧠 **Memory Tip**: ''94 is the milestone year for MP''s local governance.
🚫 **Scam Alert**: 1993 is the legislative year; 1994 is the functional year.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5a6bab5f-f762-49e8-9d4c-d7f231242b9c', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'मध्य प्रदेश में कुल कितने ''छावनी बोर्ड'' (Cantonment Boards) स्थित हैं?', '[{"id":"A","text":"5","text_en":"5"},{"id":"B","text":"3","text_en":"3"},{"id":"C","text":"7","text_en":"7"},{"id":"D","text":"4","text_en":"4"}]', '0', '✅ **Correct Logic**: मध्य प्रदेश में 5 छावनी बोर्ड हैं: महू (इंदौर), मुरार (ग्वालियर), पचमढ़ी, सागर और जबलपुर।
💡 **Exam Fact**: छावनी बोर्ड केंद्र सरकार (रक्षा मंत्रालय) के सीधे नियंत्रण में होते हैं।
🧠 **Memory Tip**: 5 major army-associated hubs.
🚫 **Scam Alert**: भोपाल में सेना का केंद्र है (बैरागढ़), लेकिन वह छावनी बोर्ड के अंतर्गत नहीं आता।', 2, 0, 10, NULL, 'How many ''Cantonment Boards'' are located in Madhya Pradesh?', '✅ **Correct Logic**: There are 5 Cantonment Boards in MP: Mhow, Morar, Pachmarhi, Sagar, and Jabalpur.
💡 **Exam Fact**: Cantonment boards are under the direct administrative control of the Ministry of Defence.
🧠 **Memory Tip**: 5 hubs of military-civil administration.
🚫 **Scam Alert**: Bairagarh in Bhopal is a military area but not a designated Cantonment Board administrative unit.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8c6bb070-a5eb-468e-a0c6-405d1980548f', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'मध्य प्रदेश में ''लोक सेवाओं के प्रदान की गारंटी अधिनियम'' (Public Service Guarantee Act) किस वर्ष पारित किया गया था?', '[{"id":"A","text":"2005","text_en":"2005"},{"id":"B","text":"2010","text_en":"2010"},{"id":"C","text":"2012","text_en":"2012"},{"id":"D","text":"2014","text_en":"2014"}]', '1', '✅ **Correct Logic**: मध्य प्रदेश 2010 में इस कानून को लागू करने वाला देश का पहला राज्य बना। इसका उद्देश्य नागरिकों को समयबद्ध सीमा में सेवाएं प्रदान करना है।
💡 **Exam Fact**: इसे संयुक्त राष्ट्र (UN) लोक सेवा पुरस्कार भी मिल चुका है।
🧠 **Memory Tip**: 2010 - A ''Ten'' on ten initiative for governance.
🚫 **Scam Alert**: यह अधिनियम सूचना के अधिकार (RTI) से अलग है, जो 2005 का है।', 2, 0, 1, NULL, 'In which year was the ''Public Service Guarantee Act'' passed in Madhya Pradesh?', '✅ **Correct Logic**: MP was the first state in India to enact this law in 2010 to ensure time-bound delivery of public services.
💡 **Exam Fact**: It has been honored with the United Nations Public Service Award.
🧠 **Memory Tip**: 2010 - A perfect score for service delivery.
🚫 **Scam Alert**: Do not confuse this with the Right to Information (RTI) Act, which dates back to 2005.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e3284ca9-c60c-4553-9108-cfd63282ed60', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'मध्य प्रदेश में ''CM हेल्पलाइन 181'' सेवा की शुरुआत कब की गई थी?', '[{"id":"A","text":"31 जुलाई 2014","text_en":"31 जुलाई 2014"},{"id":"B","text":"15 अगस्त 2014","text_en":"15 अगस्त 2014"},{"id":"C","text":"26 जनवरी 2015","text_en":"26 जनवरी 2015"},{"id":"D","text":"1 नवंबर 2013","text_en":"1 नवंबर 2013"}]', '0', '✅ **Correct Logic**: CM हेल्पलाइन 181 की शुरुआत 31 जुलाई 2014 को की गई थी ताकि नागरिक अपनी समस्याओं का सीधा समाधान पा सकें।
💡 **Exam Fact**: इसे ''जनता की सरकार, जनता के द्वार'' की तर्ज पर चलाया जा रहा है।
🧠 **Memory Tip**: 181 - 18 is adulthood, 1 is the individual''s voice.
🚫 **Scam Alert**: यह केवल शिकायतों के लिए नहीं, बल्कि योजनाओं की जानकारी के लिए भी है।', 2, 0, 2, NULL, 'When was the ''CM Helpline 181'' service started in Madhya Pradesh?', '✅ **Correct Logic**: The CM Helpline 181 was launched on July 31, 2014, to facilitate direct grievance redressal for citizens.
💡 **Exam Fact**: Its motto aligns with ''Government at the doorsteps of the people''.
🧠 **Memory Tip**: Dial 1-8-1 for the 1st person''s help.
🚫 **Scam Alert**: It serves as an information portal for government schemes too, not just for complaints.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('499e859e-6bde-4f00-9c8d-8cff07d91d82', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'सुशासन के संदर्भ में ''अटल बिहारी वाजपेयी सुशासन एवं नीति विश्लेषण संस्थान'' (AIGGPA) कहाँ स्थित है?', '[{"id":"A","text":"ग्वालियर","text_en":"ग्वालियर"},{"id":"B","text":"भोपाल","text_en":"भोपाल"},{"id":"C","text":"इंदौर","text_en":"इंदौर"},{"id":"D","text":"जबलपुर","text_en":"जबलपुर"}]', '1', '✅ **Correct Logic**: यह संस्थान भोपाल में स्थित है और नीति निर्माण एवं सुशासन के लिए थिंक टैंक के रूप में कार्य करता है।
💡 **Exam Fact**: इसकी स्थापना मूल रूप से 2007 में हुई थी और 2014 में इसका नाम अटल जी के नाम पर रखा गया।
🧠 **Memory Tip**: Policy/Governance Think Tank = Capital City (Bhopal).
🚫 **Scam Alert**: अटल जी का जन्म ग्वालियर में हुआ था, लेकिन संस्थान भोपाल में है।', 2, 0, 3, NULL, 'Where is the ''Atal Bihari Vajpayee Institute of Good Governance and Policy Analysis'' (AIGGPA) located?', '✅ **Correct Logic**: This institute is located in Bhopal and acts as a think-tank for policy making and good governance.
💡 **Exam Fact**: Originally established in 2007, it was renamed after Atal Bihari Vajpayee in 2014.
🧠 **Memory Tip**: Think-tanks are usually in the capital (Bhopal).
🚫 **Scam Alert**: While Gwalior is the birthplace of Atal Ji, the analysis institute is in Bhopal.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4a52a7b9-eea8-4143-a548-bbb9ad0d7765', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'मध्य प्रदेश शासन द्वारा ''समाधान ऑनलाइन'' (Samadhan Online) कार्यक्रम का उद्देश्य क्या है?', '[{"id":"A","text":"वरिष्ठ अधिकारियों द्वारा सीधे शिकायतों का निराकरण","text_en":"वरिष्ठ अधिकारियों द्वारा सीधे शिकायतों का निराकरण"},{"id":"B","text":"ऑनलाइन शिक्षा प्रदान करना","text_en":"ऑनलाइन शिक्षा प्रदान करना"},{"id":"C","text":"सिंचाई की समस्याओं का समाधान","text_en":"सिंचाई की समस्याओं का समाधान"},{"id":"D","text":"पर्यटन को बढ़ावा देना","text_en":"पर्यटन को बढ़ावा देना"}]', '0', '✅ **Correct Logic**: समाधान ऑनलाइन के माध्यम से मुख्यमंत्री और वरिष्ठ अधिकारी वीडियो कॉन्फ्रेंसिंग के जरिए लंबित शिकायतों का मौके पर निराकरण करते हैं।
💡 **Exam Fact**: यह प्रत्येक माह के पहले मंगलवार को आयोजित किया जाता है।
🧠 **Memory Tip**: Samadhan = Solution (Direct Solution from Top).
🚫 **Scam Alert**: यह CM हेल्पलाइन से अलग है, इसमें केवल जटिल और लंबित मामलों पर चर्चा होती है।', 2, 0, 4, NULL, 'What is the objective of the ''Samadhan Online'' program by the MP Government?', '✅ **Correct Logic**: Through Samadhan Online, the CM and senior officials address pending grievances via video conferencing.
💡 **Exam Fact**: It is typically held on the first Tuesday of every month.
🧠 **Memory Tip**: Samadhan means ''Direct Solution'' from the hierarchy.
🚫 **Scam Alert**: It differs from the routine helpline as it focuses specifically on complex, long-pending issues.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e787cda3-8e1f-47eb-8a0a-74cbf2ffc51d', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'सुशासन पहल और उनके संबंधित वर्षों को सुमेलित करें:', '[{"id":"A","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"B","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '✅ **Correct Logic**: जनसुनवाई कलेक्टर स्तर पर 2005 से शुरू हुई। लोक सेवा केंद्र 2012 में विस्तारित हुए। MyGov 2017 में नागरिकों की भागीदारी के लिए आया।
💡 **Exam Fact**: जनसुनवाई हर मंगलवार को जिला मुख्यालय पर होती है।
🧠 **Memory Tip**: Jan-Sunwai is the oldest (2005).
🚫 **Scam Alert**: MyGov केंद्र सरकार का 2014 में आया, लेकिन MP का 2017 में।', 2, 0, 5, NULL, 'Match the Good Governance initiatives and their respective years:', '✅ **Correct Logic**: Jan-Sunwai started in 2005 at the Collectorate level. Public Service Centers expanded in 2012. MyGov MP was launched in 2017.
💡 **Exam Fact**: Jan-Sunwai sessions are held every Tuesday at district headquarters.
🧠 **Memory Tip**: Public hearing (Jan-Sunwai) is the root initiative (2005).
🚫 **Scam Alert**: While the National MyGov launched in 2014, the MP version arrived in 2017.', 60, 'matching', '[{"id":"(1)","label":"MP MyGov पोर्टल","match":"2017","matchId":"(a)"},{"id":"(2)","label":"लोक सेवा केंद्र का उदय","match":"2012","matchId":"(b)"},{"id":"(3)","label":"CM डैशबोर्ड","match":"2014","matchId":"(c)"},{"id":"(4)","label":"मध्य प्रदेश जनसुनवाई","match":"2005","matchId":"(d)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9fdacc61-e9ce-4cf6-8b2e-7482cc92d99d', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'ई-गवर्नेंस के क्षेत्र में ''ज्ञानदूत'' (Gyandoot) परियोजना किस जिले से शुरू की गई थी?', '[{"id":"A","text":"धार","text_en":"धार"},{"id":"B","text":"इंदौर","text_en":"इंदौर"},{"id":"C","text":"देवास","text_en":"देवास"},{"id":"D","text":"उज्जैन","text_en":"उज्जैन"}]', '0', '✅ **Correct Logic**: ज्ञानदूत परियोजना 2000 में धार जिले से शुरू की गई थी। यह ग्रामीण क्षेत्रों में ई-कॉमर्स और ई-गवर्नेंस का एक प्रारंभिक सफल मॉडल था।
💡 **Exam Fact**: इसे ''स्टॉकहोम चैलेंज अवार्ड'' (Stockholm Challenge Award) भी प्राप्त हुआ था।
🧠 **Memory Tip**: Gyan (Knowledge) from Dhar.
🚫 **Scam Alert**: यह भारत की पहली ग्रामीण ई-गवर्नेंस पहलों में से एक थी।', 2, 0, 6, NULL, 'From which district was the ''Gyandoot'' project launched in the field of e-governance?', '✅ **Correct Logic**: The Gyandoot project was launched in Dhar district in the year 2000. It was an early successful model of rural e-governance.
💡 **Exam Fact**: It won the prestigious Stockholm Challenge Award for its innovation.
🧠 **Memory Tip**: Dhar - D for Delivery of Gyan (Knowledge).
🚫 **Scam Alert**: It was a pioneer project long before Digital India became a common phrase.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7cb2feee-d531-4b54-b8ed-f79390f94913', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'मध्य प्रदेश में ''लोक सेवा आयोग'' (MPPSC) का मुख्यालय कहाँ स्थित है और इसका गठन कब हुआ?', '[{"id":"A","text":"भोपाल; 1956","text_en":"भोपाल; 1956"},{"id":"B","text":"इंदौर; 1956","text_en":"इंदौर; 1956"},{"id":"C","text":"ग्वालियर; 1950","text_en":"ग्वालियर; 1950"},{"id":"D","text":"जबलपुर; 1956","text_en":"जबलपुर; 1956"}]', '1', '✅ **Correct Logic**: MPPSC का मुख्यालय इंदौर में है और इसका गठन राज्य पुनर्गठन अधिनियम की धारा 118(3) के तहत 1956 में किया गया था।
💡 **Exam Fact**: इसके प्रथम अध्यक्ष डी.वी. रेगे (D.V. Rege) थे।
🧠 **Memory Tip**: PSC in Indore (Financial/Education hub).
🚫 **Scam Alert**: अधिकांश मुख्यालय भोपाल में हैं, लेकिन PSC और उच्च न्यायालय की खंडपीठ इंदौर में हैं।', 2, 0, 7, NULL, 'Where is the HQ of MPPSC located and when was it constituted?', '✅ **Correct Logic**: MPPSC is headquartered in Indore and was constituted in 1956 under Section 118(3) of the State Reorganization Act.
💡 **Exam Fact**: The first chairman was D.V. Rege.
🧠 **Memory Tip**: PSC exams are centered in the student hub - Indore.
🚫 **Scam Alert**: While many departments are in Bhopal, MPPSC remains in Indore.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7d657594-d11f-4e35-ae52-aeac42a5d7f0', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'सुशासन दिवस (Good Governance Day) किसकी जयंती पर मनाया जाता है?', '[{"id":"A","text":"सरदार पटेल","text_en":"सरदार पटेल"},{"id":"B","text":"अटल बिहारी वाजपेयी","text_en":"अटल बिहारी वाजपेयी"},{"id":"C","text":"पंडित नेहरू","text_en":"पंडित नेहरू"},{"id":"D","text":"महात्मा गांधी","text_en":"महात्मा गांधी"}]', '1', '✅ **Correct Logic**: 25 दिसंबर को पूर्व प्रधानमंत्री अटल बिहारी वाजपेयी की जयंती को सुशासन दिवस के रूप में मनाया जाता है।
💡 **Exam Fact**: अटल जी का जन्म ग्वालियर (MP) में हुआ था।
🧠 **Memory Tip**: 25 Dec - Christmas & Good Governance Day.
🚫 **Scam Alert**: सरदार पटेल की जयंती 31 अक्टूबर ''राष्ट्रीय एकता दिवस'' के रूप में मनाई जाती है।', 2, 0, 8, NULL, 'On whose birth anniversary is Good Governance Day celebrated?', '✅ **Correct Logic**: December 25th, the birth anniversary of former PM Atal Bihari Vajpayee, is celebrated as Good Governance Day.
💡 **Exam Fact**: Atal Ji was born in Gwalior, Madhya Pradesh.
🧠 **Memory Tip**: Dec 25 - A gift of good governance to India.
🚫 **Scam Alert**: Oct 31 (Sardar Patel) is Unity Day, not Good Governance Day.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a1d34867-3456-429c-ac73-b16c86b5deac', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'मध्य प्रदेश में ''ई-डिस्ट्रिक्ट'' (e-District) परियोजना का मुख्य उद्देश्य क्या है?', '[{"id":"A","text":"सरकारी प्रमाणपत्रों (जाति, आय, निवास) को ऑनलाइन प्रदान करना","text_en":"सरकारी प्रमाणपत्रों (जाति, आय, निवास) को ऑनलाइन प्रदान करना"},{"id":"B","text":"जिलों को सड़क मार्ग से जोड़ना","text_en":"जिलों को सड़क मार्ग से जोड़ना"},{"id":"C","text":"जिलों में मुफ्त वाई-फाई देना","text_en":"जिलों में मुफ्त वाई-फाई देना"},{"id":"D","text":"केवल पुलिस रिकॉर्ड का डिजिटलीकरण","text_en":"केवल पुलिस रिकॉर्ड का डिजिटलीकरण"}]', '0', '✅ **Correct Logic**: ई-डिस्ट्रिक्ट का लक्ष्य नागरिकों को उनके घर के पास लोक सेवा केंद्रों के माध्यम से महत्वपूर्ण प्रमाणपत्र और सेवाएं डिजिटल रूप से उपलब्ध कराना है।
💡 **Exam Fact**: यह लोक सेवा गारंटी अधिनियम के कार्यान्वयन का तकनीकी आधार है।
🧠 **Memory Tip**: e-District = Digital District Services.
🚫 **Scam Alert**: यह केवल रिकॉर्ड रखने के लिए नहीं, बल्कि नागरिकों को सेवा ''डिलीवरी'' के लिए है।', 2, 0, 9, NULL, 'What is the primary objective of the ''e-District'' project in Madhya Pradesh?', '✅ **Correct Logic**: The e-District project aims to provide G2C (Government to Citizen) services like caste, income, and domicile certificates digitally.
💡 **Exam Fact**: It provides the technical backbone for the Public Service Guarantee Act.
🧠 **Memory Tip**: e-District = Electronic delivery of district-level certificates.
🚫 **Scam Alert**: It is a service delivery platform, not just a storage system for records.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('41393a46-5bba-4624-9eb9-3ffe09d0c627', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'मध्य प्रदेश राज्य ''सतर्कता आयोग'' (State Vigilance Commission) का गठन कब किया गया था?', '[{"id":"A","text":"1 मार्च 1964","text_en":"1 मार्च 1964"},{"id":"B","text":"15 अगस्त 1964","text_en":"15 अगस्त 1964"},{"id":"C","text":"1 नवंबर 1956","text_en":"1 नवंबर 1956"},{"id":"D","text":"2 अक्टूबर 1972","text_en":"2 अक्टूबर 1972"}]', '0', '✅ **Correct Logic**: केंद्र के समान ही मध्य प्रदेश में भी मार्च 1964 में सतर्कता आयोग का गठन भ्रष्टाचार रोकने के लिए किया गया था।
💡 **Exam Fact**: राज्य का मुख्य सतर्कता आयुक्त (CVC) भ्रष्टाचार के विरुद्ध सर्वोच्च अधिकारी होता है।
🧠 **Memory Tip**: 1964 - The year the nation became ''Vigilant''.
🚫 **Scam Alert**: लोकायुक्त और सतर्कता आयोग अलग-अलग संस्थाएं हैं; लोकायुक्त अधिनियम 1981 का है।', 2, 0, 10, NULL, 'When was the Madhya Pradesh State Vigilance Commission constituted?', '✅ **Correct Logic**: Similar to the Central body, the MP State Vigilance Commission was formed in March 1964 to combat corruption.
💡 **Exam Fact**: The State Vigilance Commissioner is the top anti-corruption executive officer.
🧠 **Memory Tip**: ''64 - The watchman (Vigilance) was hired.
🚫 **Scam Alert**: Vigilance Commission and Lokayukta are separate; the Lokayukta Act was passed in 1981.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4dff154f-9e6e-4208-b4a9-445cb3e9fe7b', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'सांख्य दर्शन के अनुसार, सृष्टि की उत्पत्ति किन दो मूल तत्वों के संयोग से होती है?', '[{"id":"A","text":"आत्मा और परमात्मा","text_en":"आत्मा और परमात्मा"},{"id":"B","text":"प्रकृति और पुरुष","text_en":"प्रकृति और पुरुष"},{"id":"C","text":"अणु और परमाणु","text_en":"अणु और परमाणु"},{"id":"D","text":"माया और ब्रह्म","text_en":"माया और ब्रह्म"}]', '1', '**✅ Correct Logic**: सांख्य दर्शन ''द्वैतवादी'' है, जो मानता है कि सृष्टि ''प्रकृति'' (जड़/Matter) और ''पुरुष'' (चेतन/Spirit) के मेल से बनी है।

**💡 Exam Fact**: सांख्य दर्शन भारत का प्राचीनतम दर्शन माना जाता है, जिसके प्रवर्तक कपिल मुनि थे।

**🧠 Memory Tip**: **S**ankhya = **S**pirit (Purusha) + **S**ubstance (Prakriti).

**🚫 Scam Alert**: सांख्य ''निरीश्वरवादी'' है, यह ''परमात्मा'' की सत्ता को स्वीकार नहीं करता, केवल प्रकृति और पुरुष को मानता है।', 2, 0, 1, NULL, 'According to Sankhya philosophy, the creation of the universe results from the union of which two fundamental elements?', '**✅ Correct Logic**: Sankhya is dualistic, holding that the universe arises from the interaction of Prakriti (unconscious matter) and Purusha (conscious spirit).

**💡 Exam Fact**: It is the oldest school of Indian philosophy, founded by Kapila Muni.

**🧠 Memory Tip**: **S**ankhya = **S**pirit (Purusha) + **S**ubstance (Prakriti).

**🚫 Scam Alert**: Sankhya is originally atheistic (Nirishvarvada); it doesn''t rely on ''Paramatma'' or ''Brahman'' like Vedanta.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6f39fd54-38b6-4153-b3c9-80fb48d2358a', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'न्याय दर्शन का मुख्य प्रतिपाद्य विषय क्या है?', '[{"id":"A","text":"योग साधना","text_en":"योग साधना"},{"id":"B","text":"तर्कशास्त्र और ज्ञानमीमांसा (Logic & Epistemology)","text_en":"तर्कशास्त्र और ज्ञानमीमांसा (Logic & Epistemology)"},{"id":"C","text":"यज्ञ कर्मकांड","text_en":"यज्ञ कर्मकांड"},{"id":"D","text":"परमाणुवाद","text_en":"परमाणुवाद"}]', '1', '**✅ Correct Logic**: न्याय दर्शन का मुख्य केंद्र ''प्रमाण'' (प्रमाणों के माध्यम से ज्ञान की प्राप्ति) और तर्क (Logic) है। इसके प्रवर्तक अक्षपाद गौतम थे।

**💡 Exam Fact**: न्याय दर्शन ने ज्ञान प्राप्ति के 4 प्रमाण माने हैं: प्रत्यक्ष, अनुमान, उपमान और शब्द।

**🧠 Memory Tip**: **N**yaya = **N**logical reasoning/Legal logic.

**🚫 Scam Alert**: परमाणुवाद ''वैशेषिक'' का विषय है, न्याय का नहीं (यद्यपि दोनों साथ पढ़े जाते हैं)।', 2, 0, 2, NULL, 'What is the primary subject matter of the Nyaya philosophy?', '**✅ Correct Logic**: Nyaya focuses on logic and the means of attaining right knowledge (Pramana). It was founded by Akshapada Gautama.

**💡 Exam Fact**: Nyaya accepts 4 valid means of knowledge: Perception, Inference, Comparison, and Testimony.

**🧠 Memory Tip**: **N**yaya = **N**etwork of Logic.

**🚫 Scam Alert**: Atomism (Paramanuvada) is specific to Vaisheshika, not the core of Nyaya.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('eeae3e72-06d2-4a18-82f7-65b8ed2b1db8', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'भारतीय परमाणुवाद (Indian Atomism) का जनक किसे माना जाता है?', '[{"id":"A","text":"कपिल मुनि","text_en":"कपिल मुनि"},{"id":"B","text":"महर्षि कणाद","text_en":"महर्षि कणाद"},{"id":"C","text":"महर्षि जैमिनी","text_en":"महर्षि जैमिनी"},{"id":"D","text":"बादरायण","text_en":"बादरायण"}]', '1', '**✅ Correct Logic**: वैशेषिक दर्शन के प्रवर्तक महर्षि कणाद ने यह सिद्धांत दिया कि भौतिक जगत ''परमाणुओं'' के समूह से बना है, जो अविभाज्य हैं।

**💡 Exam Fact**: कणाद का वास्तविक नाम ''उलूक'' था। कणाद नाम इसलिए पड़ा क्योंकि वे अनाज के कण (Kan) चुनकर जीवन यापन करते थे।

**🧠 Memory Tip**: **Kan**ada discovered **Kan** (Particles/Atoms).

**🚫 Scam Alert**: डेमोक्रिटस (यूनान) से सदियों पहले कणाद ने परमाणु का सिद्धांत दे दिया था।', 2, 0, 3, NULL, 'Who is considered the father of Indian Atomism?', '**✅ Correct Logic**: Maharishi Kanada, the founder of Vaisheshika, propounded that the physical universe is composed of indivisible atoms (Paramanu).

**💡 Exam Fact**: His real name was Uluka. He was called Kanada because he gathered ''Kana'' (grains/particles) from the fields.

**🧠 Memory Tip**: **Kan**ada discovered **Kan** (Particles/Atoms).

**🚫 Scam Alert**: Kanada gave this theory centuries before Democritus (Greece).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1450c282-4371-462a-b064-074a5366da3a', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'कथन (A): मीमांसा दर्शन वेदों को ''अपौरुषेय'' और ''नित्य'' मानता है।
कारण (R): इसका मुख्य उद्देश्य वैदिक यज्ञों और कर्मकांडों की प्रमाणिकता सिद्ध करना है।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic**: मीमांसा (पूर्व मीमांसा) के अनुसार वेद किसी पुरुष (यहाँ तक कि ईश्वर भी नहीं) द्वारा रचित नहीं हैं, वे नित्य हैं। यह इसलिए ताकि यज्ञों के आदेशों को सर्वकालिक सत्य माना जा सके।

**💡 Exam Fact**: जैमिनी मीमांसा सूत्र के रचयिता थे।

**🧠 Memory Tip**: **M**imamsa = **M**andatory Rituals. If Veda is eternal, Rituals are permanent.

**🚫 Scam Alert**: ''उत्तर मीमांसा'' (वेदांत) ज्ञान पर जोर देता है, जबकि ''पूर्व मीमांसा'' केवल कर्मकांड पर।', 2, 0, 4, NULL, 'Assertion (A): Mimamsa philosophy considers the Vedas as ''Apaurusheya'' and eternal.
Reason (R): Its primary goal is to establish the authority of Vedic rituals and sacrifices.
Select the correct option:', '**✅ Correct Logic**: Mimamsa argues Vedas are unauthored (Apaurusheya) to ensure the rituals prescribed within them are viewed as absolute and eternal laws.

**💡 Exam Fact**: Jaimini was the author of the Mimamsa Sutras.

**🧠 Memory Tip**: **M**imamsa = **M**andatory Rituals. If Veda is eternal, Rituals are permanent.

**🚫 Scam Alert**: Do not confuse Purva Mimamsa (Ritualism) with Uttara Mimamsa (Vedanta/Knowledge).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a3ba6d04-52d2-4457-842b-26ed299d9201', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'षड्दर्शन और उनके प्रवर्तकों को सुमेलित करें (Match the Shaddarshans with their founders):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Logic**: 
* योग: पतंजलि (चित्तवृत्ति निरोध)।
* सांख्य: कपिल (25 तत्व)।
* वैशेषिक: कणाद (परमाणु)।
* वेदांत: बादरायण (ब्रह्मसूत्र)।

**💡 Exam Fact**: वेदांत को ''उत्तर मीमांसा'' भी कहा जाता है।

**🧠 Memory Tip**: **P**atanjali = **P**ranayama (Yoga). **B**adara**y**ana = **B**rahman (Vedanta).

**🚫 Scam Alert**: गौतम बुद्ध और अक्षपाद गौतम अलग हैं; न्याय दर्शन अक्षपाद गौतम का है।', 2, 0, 5, NULL, 'Match the Shaddarshans with their founders:', '**✅ Correct Logic**: 
* Yoga: Patanjali.
* Sankhya: Kapila.
* Vaisheshika: Kanada.
* Vedanta: Badarayana.

**💡 Exam Fact**: Vedanta is also known as Uttara Mimamsa.

**🧠 Memory Tip**: **P**atanjali = **P**ranayama (Yoga). **B**adara**y**ana = **B**rahman (Vedanta).

**🚫 Scam Alert**: Akshapada Gautama (Nyaya) is often confused with Gautama Buddha; they are different people.', 60, 'matching', '[{"id":"(1)","label":"योग (Yoga)","match":"पतंजलि","matchId":"(b)"},{"id":"(2)","label":"सांख्य (Sankhya)","match":"कपिल","matchId":"(a)"},{"id":"(3)","label":"वैशेषिक (Vaisheshika)","match":"कणाद","matchId":"(d)"},{"id":"(4)","label":"वेदांत (Vedanta)","match":"बादरायण","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d9ceb455-27c2-423a-b8c6-2b0680267690', '7e0f0608-37d8-4b62-9f32-be594f782ccd', '''योगश्चित्तवृत्तिनिरोधः'' (योग मन की वृत्तियों को रोकना है) - यह परिभाषा किस दर्शन की है?', '[{"id":"A","text":"सांख्य","text_en":"सांख्य"},{"id":"B","text":"योग","text_en":"योग"},{"id":"C","text":"न्याय","text_en":"न्याय"},{"id":"D","text":"वेदांत","text_en":"वेदांत"}]', '1', '**✅ Correct Logic**: पतंजलि ने ''योगसूत्र'' के दूसरे सूत्र में योग को मन (चित्त) की चंचलता (वृत्तियों) को रोकने के रूप में परिभाषित किया है।

**💡 Exam Fact**: योग दर्शन सांख्य के ''25 तत्वों'' के साथ ''ईश्वर'' को 26वें तत्व के रूप में जोड़ता है, इसलिए इसे ''सेश्वर सांख्य'' भी कहते हैं।

**🧠 Memory Tip**: **Y**oga = **Y**oke (Control) of the mind.

**🚫 Scam Alert**: योग केवल शारीरिक व्यायाम (Asana) नहीं है, यह एक दार्शनिक पद्धति है।', 2, 0, 6, NULL, '''Yoga is the cessation of the fluctuations of mind'' - this definition belongs to which school?', '**✅ Correct Logic**: Patanjali defines Yoga in the second sutra of the Yoga Sutras as the suppression of the modifications of the mind-stuff.

**💡 Exam Fact**: Yoga philosophy is called ''Seshvara Sankhya'' because it accepts the 25 elements of Sankhya but adds ''Ishvara'' (God) as the 26th.

**🧠 Memory Tip**: **Y**oga = **Y**oke (Control) of the mind.

**🚫 Scam Alert**: Yoga in Shaddarshan is a complete psychological system, not just physical exercise.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a042d841-9026-4111-90d2-3be6826af44f', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'शंकराचार्य का ''अद्वैत'' दर्शन किस षड्दर्शन का अंग है?', '[{"id":"A","text":"न्याय","text_en":"न्याय"},{"id":"B","text":"वैशेषिक","text_en":"वैशेषिक"},{"id":"C","text":"मीमांसा","text_en":"मीमांसा"},{"id":"D","text":"वेदांत","text_en":"वेदांत"}]', '3', '**✅ Correct Logic**: वेदांत (या उत्तर मीमांसा) ''उपनिषदों'' के ज्ञान पर आधारित है। शंकराचार्य ने इस पर ''अद्वैत'' (दो नहीं, केवल एक ब्रह्म) का सिद्धांत दिया।

**💡 Exam Fact**: बादरायण का ''ब्रह्मसूत्र'' वेदांत का आधार ग्रंथ है।

**🧠 Memory Tip**: **V**edanta = **V**ast oneness (Advaita).

**🚫 Scam Alert**: मीमांसा और वेदांत में अंतर यह है कि मीमांसा ''कर्म'' पर और वेदांत ''ज्ञान'' पर जोर देता है।', 2, 0, 7, NULL, 'Shankaracharya''s ''Advaita'' philosophy is a branch of which Shaddarshan?', '**✅ Correct Logic**: Vedanta (Uttara Mimamsa) is based on the Upanishads. Adi Shankara''s Advaita (Non-dualism) is its most famous sub-school.

**💡 Exam Fact**: Badarayana''s ''Brahma Sutra'' is the foundational text of this school.

**🧠 Memory Tip**: **V**edanta = **V**ast oneness (Advaita).

**🚫 Scam Alert**: Mimamsa is ritual-focused; Vedanta is knowledge-focused. Don''t swap them.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e091b2ef-d567-4310-a14e-dda0d7ee7497', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'सांख्य दर्शन के अनुसार ''त्रिविध दुख'' में कौन सा शामिल नहीं है?', '[{"id":"A","text":"आध्यात्मिक","text_en":"आध्यात्मिक"},{"id":"B","text":"आधिदैविक","text_en":"आधिदैविक"},{"id":"C","text":"आधिभौतिक","text_en":"आधिभौतिक"},{"id":"D","text":"आर्थिक (Economic)","text_en":"आर्थिक (Economic)"}]', '3', '**✅ Correct Logic**: सांख्य के अनुसार दुख तीन प्रकार के हैं: 1. आध्यात्मिक (शारीरिक-मानसिक), 2. आधिभौतिक (बाहरी जीवों से), 3. आधिदैविक (दैवीय आपदा/ग्रह)। ''आर्थिक'' दुख आधुनिक संकल्पना है।

**💡 Exam Fact**: सांख्य का लक्ष्य इन तीनों दुखों से ''आत्यंतिक निवृत्ति'' (कैवल्य) प्राप्त करना है।

**🧠 Memory Tip**: **A-A-A** (Adhyatmic, Adhibhautic, Adhidaivic).

**🚫 Scam Alert**: आध्यात्मिक का अर्थ यहाँ केवल ''पूजा-पाठ'' नहीं, बल्कि ''स्वयं से उत्पन्न'' (बुखार, गुस्सा आदि) कष्ट है।', 2, 0, 8, NULL, 'According to Sankhya philosophy, which of the following is NOT included in the ''three-fold suffering''?', '**✅ Correct Logic**: Sankhya identifies three types of pain: Adhyatmika (internal), Adhibhautika (external beings), and Adhidaivika (natural/supernatural forces).

**💡 Exam Fact**: The ultimate goal of Sankhya is the complete cessation of these three sufferings (Kaivalya).

**🧠 Memory Tip**: **A-A-A** (Internal, External, Natural).

**🚫 Scam Alert**: ''Adhyatmika'' in Sankhya includes physical illness and mental distress, not just spiritual issues.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6068f39e-b8a6-46bf-b946-b4b151e08a71', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'किस दर्शन को ''आन्वीक्षिकी'' (Critical Inquiry) भी कहा गया है?', '[{"id":"A","text":"योग","text_en":"योग"},{"id":"B","text":"न्याय","text_en":"न्याय"},{"id":"C","text":"सांख्य","text_en":"सांख्य"},{"id":"D","text":"वैशेषिक","text_en":"वैशेषिक"}]', '1', '**✅ Correct Logic**: न्याय दर्शन को इसकी तर्क-प्रधानता के कारण ''आन्वीक्षिकी'' (तर्कविद्या) कहा जाता है। कौटिल्य ने भी इसे श्रेष्ठ विद्या माना था।

**💡 Exam Fact**: इसे ''तर्कशास्त्र'' और ''प्रमाणशास्त्र'' भी कहते हैं।

**🧠 Memory Tip**: **N**yaya = **N**analysis/Critical Inquiry.

**🚫 Scam Alert**: चार्वाक भी तर्क करता है, लेकिन ''आन्वीक्षिकी'' विशेष रूप से न्याय के लिए प्रयुक्त शास्त्रीय शब्द है।', 2, 0, 9, NULL, 'Which school of philosophy is also known as ''Anvikshiki''?', '**✅ Correct Logic**: Due to its emphasis on reasoning and logical analysis, Nyaya is termed ''Anvikshiki''. Kautilya''s Arthashastra praises it as one of the four essential sciences.

**💡 Exam Fact**: It is also referred to as Tarka-shastra or the science of reasoning.

**🧠 Memory Tip**: **N**yaya = **N**analysis.

**🚫 Scam Alert**: While other schools use logic, ''Anvikshiki'' is the formal title specifically for Nyaya.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b36056e7-c8d4-465f-8530-f1b7188a2042', '7e0f0608-37d8-4b62-9f32-be594f782ccd', '''सत्कार्यवाद'' (Satkaryavada) का सिद्धांत किस दर्शन की पहचान है?', '[{"id":"A","text":"न्याय","text_en":"न्याय"},{"id":"B","text":"सांख्य","text_en":"सांख्य"},{"id":"C","text":"बौद्ध","text_en":"बौद्ध"},{"id":"D","text":"जैन","text_en":"जैन"}]', '1', '**✅ Correct Logic**: सत्कार्यवाद का अर्थ है कि ''कार्य'' अपनी उत्पत्ति से पूर्व ''कारण'' में विद्यमान रहता है (जैसे तिल में तेल)। यह सांख्य का प्रमुख सिद्धांत है।

**💡 Exam Fact**: इसके विपरीत न्याय दर्शन ''असत्कार्यवाद'' को मानता है (कार्य एक नई उत्पत्ति है)।

**🧠 Memory Tip**: **S**atkaryavada = **S**ankhya.

**🚫 Scam Alert**: यह सिद्धांत कहता है कि शून्य से कुछ भी उत्पन्न नहीं हो सकता (Ex nihilo nihil fit)।', 2, 0, 10, NULL, 'The theory of ''Satkaryavada'' is the hallmark of which philosophy?', '**✅ Correct Logic**: Satkaryavada holds that the effect pre-exists in its cause (like oil in seeds). This is the foundational causality theory of Sankhya.

**💡 Exam Fact**: Nyaya opposes this with ''Asatkaryavada'', claiming the effect is a completely new creation.

**🧠 Memory Tip**: **S**atkaryavada = **S**ankhya.

**🚫 Scam Alert**: This implies that nothing can be created from absolute nothingness.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cb3ce2d8-6afd-4338-8f70-f4b303cc45b6', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'प्राचीनतम और सर्वाधिक प्रामाणिक स्मृति कौन सी मानी जाती है?', '[{"id":"A","text":"नारद स्मृति","text_en":"नारद स्मृति"},{"id":"B","text":"याज्ञवल्क्य स्मृति","text_en":"याज्ञवल्क्य स्मृति"},{"id":"C","text":"मनुस्मृति","text_en":"मनुस्मृति"},{"id":"D","text":"पराशर स्मृति","text_en":"पराशर स्मृति"}]', '2', '**✅ Correct Logic**: मनुस्मृति (मानव धर्मशास्त्र) सबसे प्राचीन है, जिसकी रचना शुंग काल (लगभग 200 ई.पू.) में हुई थी।

**💡 Exam Fact**: विलियम जोन्स ने 1776 में इसका अंग्रेजी अनुवाद ''A Code of Gentoo Laws'' नाम से किया था।

**🧠 Memory Tip**: **M**anu = **M**ain/Oldest law-giver.

**🚫 Scam Alert**: स्मृतियाँ ''श्रुति'' (वेदों) के बाद की रचनाएं हैं और इनका स्थान वेदों के नीचे आता है।', 2, 0, 1, NULL, 'Which Smriti is considered the oldest and most authoritative?', '**✅ Correct Logic**: Manusmriti is the oldest Smriti, composed during the Shunga period (circa 200 BCE). It is the foundational text of Hindu law.

**💡 Exam Fact**: Sir William Jones translated it as ''A Code of Gentoo Laws'' in 1776.

**🧠 Memory Tip**: **M**anu = **M**ajor/Oldest Smriti.

**🚫 Scam Alert**: Smritis are secondary to ''Shruti'' (Vedas). If there is a conflict, Vedas prevail.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('425121c1-6dfa-4151-ac4f-c195c615c921', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'प्रसिद्ध ''मिताक्षरा'' (Mitakshara) टीका किस स्मृति पर लिखी गई है?', '[{"id":"A","text":"मनुस्मृति","text_en":"मनुस्मृति"},{"id":"B","text":"याज्ञवल्क्य स्मृति","text_en":"याज्ञवल्क्य स्मृति"},{"id":"C","text":"विष्णु स्मृति","text_en":"विष्णु स्मृति"},{"id":"D","text":"नारद स्मृति","text_en":"नारद स्मृति"}]', '1', '**✅ Correct Logic**: विज्ञानेश्वर ने ''याज्ञवल्क्य स्मृति'' पर मिताक्षरा नामक टीका लिखी, जो आधुनिक हिंदू उत्तराधिकार कानून का आधार बनी।

**💡 Exam Fact**: यह टीका ''जन्मना अधिकार'' (Right by birth) के सिद्धांत को मानती है।

**🧠 Memory Tip**: **Y**ajnavalkya = **Y**our birthright (Mitakshara).

**🚫 Scam Alert**: ''दायभाग'' (जीमूतवाहन) बंगाल में प्रचलित थी, जबकि मिताक्षरा शेष भारत में।', 2, 0, 2, NULL, 'The famous ''Mitakshara'' commentary is written on which Smriti?', '**✅ Correct Logic**: Vijnaneshwara wrote the ''Mitakshara'' commentary on Yajnavalkya Smriti. It remains a key source for Hindu inheritance law.

**💡 Exam Fact**: It upholds the principle that property rights are acquired by birth.

**🧠 Memory Tip**: **Y**ajnavalkya = **Y**our birthright (Mitakshara).

**🚫 Scam Alert**: Mitakshara prevailed in all of India except Bengal, where ''Dayabhaga'' was followed.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d0505421-fde9-4997-8f1b-29fca2183228', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'किस स्मृति में गुप्त काल के दौरान दासों की मुक्ति (Emancipation of Slaves) के नियम विस्तार से दिए गए हैं?', '[{"id":"A","text":"मनुस्मृति","text_en":"मनुस्मृति"},{"id":"B","text":"नारद स्मृति","text_en":"नारद स्मृति"},{"id":"C","text":"गौतम स्मृति","text_en":"गौतम स्मृति"},{"id":"D","text":"कात्यायन स्मृति","text_en":"कात्यायन स्मृति"}]', '1', '**✅ Correct Logic**: नारद स्मृति (गुप्त कालीन) दासों के 15 प्रकार बताती है और उनकी मुक्ति की विधि का वर्णन करने वाली पहली स्मृति है।

**💡 Exam Fact**: नारद स्मृति एकमात्र स्मृति है जो ''नियोग प्रथा'' और ''विधवा विवाह'' की स्पष्ट अनुमति देती है।

**🧠 Memory Tip**: **N**arada = **N**ew freedom for slaves.

**🚫 Scam Alert**: मनुस्मृति दासों के प्रति बहुत कठोर थी; नारद स्मृति तुलनात्मक रूप से उदार (Liberal) है।', 2, 0, 3, NULL, 'Which Smriti provides detailed rules for the emancipation of slaves during the Gupta period?', '**✅ Correct Logic**: Narada Smriti lists 15 types of slaves and is the first to detail the formal procedure for their manumission.

**💡 Exam Fact**: It is unique for openly permitting Niyoga and widow remarriage.

**🧠 Memory Tip**: **N**arada = **N**ew/Next level freedom for slaves.

**🚫 Scam Alert**: Manusmriti was quite rigid regarding slavery; Narada Smriti reflects more liberal Gupta era trends.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('83c8e6b9-4af3-4881-b89e-f290fbaa2d1f', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'कथन (A): स्मृतियों को ''धर्मशास्त्र'' (Dharmashastra) भी कहा जाता है।
कारण (R): ये समाज के नैतिक, सामाजिक और कानूनी आचरण को संहिताबद्ध करती हैं।
सही विकल्प चुनें:', '[{"id":"A","text":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।","text_en":"A और R दोनों सत्य हैं तथा R, A की सही व्याख्या है।"},{"id":"B","text":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।","text_en":"A और R दोनों सत्य हैं परन्तु R, A की सही व्याख्या नहीं है।"},{"id":"C","text":"A सत्य है परन्तु R असत्य है।","text_en":"A सत्य है परन्तु R असत्य है।"},{"id":"D","text":"A असत्य है परन्तु R सत्य है।","text_en":"A असत्य है परन्तु R सत्य है।"}]', '0', '**✅ Correct Logic**: स्मृतियों का मुख्य उद्देश्य ''धर्म'' (कर्तव्य) का शासन स्थापित करना था, इसलिए इन्हें धर्मशास्त्र की संज्ञा दी गई।

**💡 Exam Fact**: मनुस्मृति के अनुसार ''श्रुतिस्तु वेदो विज्ञेयो धर्मशास्त्रं तु वै स्मृतिः''।

**🧠 Memory Tip**: Smriti = Remembered Law. Shastra = Text.

**🚫 Scam Alert**: स्मृतियाँ ''अपौरुषेय'' (ईश्वरीय) नहीं हैं, ये ऋषियों द्वारा रचित (पौरुषेय) मानी जाती हैं।', 2, 0, 4, NULL, 'Assertion (A): Smritis are also called ''Dharmashastra''.
Reason (R): They codify the moral, social, and legal conduct of society.
Select the correct option:', '**✅ Correct Logic**: Smritis serve as manuals of Dharma, covering ethics and law, hence the name Dharmashastra.

**💡 Exam Fact**: Manusmriti explicitly equates Smriti with the science of Dharmashastra.

**🧠 Memory Tip**: Smriti = Social laws to remember.

**🚫 Scam Alert**: Unlike Vedas (Shruti), Smritis are human compositions (Paurusheya).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('28fd757b-c6d9-40c6-979f-3d846b7824b8', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'प्रमुख स्मृतियों और उनके टीकाकारों (Commentators) को सुमेलित करें (Match the major Smritis with their commentators):', '[{"id":"A","text":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)","text_en":"(1)-(b), (2)-(a), (3)-(d), (4)-(c)"},{"id":"B","text":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)","text_en":"(1)-(a), (2)-(b), (3)-(c), (4)-(d)"},{"id":"C","text":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)","text_en":"(1)-(c), (2)-(d), (3)-(a), (4)-(b)"},{"id":"D","text":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)","text_en":"(1)-(d), (2)-(c), (3)-(b), (4)-(a)"}]', '0', '**✅ Correct Logic**: 
* मनु: मेधातिथि, कुल्लूक भट्ट, गोविंदराज।
* याज्ञवल्क्य: विज्ञानेश्वर, विश्वरूप, अपरार्क।
* नारद: असहाय।
* पराशर: माधवाचार्य।

**💡 Exam Fact**: मेधातिथि ने सती प्रथा का विरोध किया था, इसे ''आत्महत्या'' कहा था।

**🧠 Memory Tip**: **M**anu = **M**edhatithi. **N**arada is helpless without help = **Asahaya**.

**🚫 Scam Alert**: सायण ने वेदों पर भाष्य लिखा था, उन्हें स्मृतियों के टीकाकारों के साथ न मिलाएँ।', 2, 0, 5, NULL, 'Match the major Smritis with their commentators:', '**✅ Correct Logic**: 
* Manu: Medhatithi, Kulluka.
* Yajnavalkya: Vijnaneshwara.
* Narada: Asahaya.
* Parashara: Madhavacharya.

**💡 Exam Fact**: Medhatithi was a progressive commentator who condemned Sati as a form of suicide.

**🧠 Memory Tip**: **M**anu = **M**edhatithi. **N**arada is **N**ot able to do it without help = **Asahaya**.

**🚫 Scam Alert**: Sayana commented on Vedas; don''t confuse him with these legal commentators.', 60, 'matching', '[{"id":"(1)","label":"मनुस्मृति","match":"मेधातिथि (Medhatithi)","matchId":"(b)"},{"id":"(2)","label":"याज्ञवल्क्य स्मृति","match":"विज्ञानेश्वर","matchId":"(a)"},{"id":"(3)","label":"नारद स्मृति","match":"असहाय (Asahaya)","matchId":"(d)"},{"id":"(4)","label":"पराशर स्मृति","match":"माधवाचार्य","matchId":"(c)"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8b22ebaf-13da-4545-ba1d-a2dd31822da3', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'मनुस्मृति में विवाह के कितने प्रकारों का उल्लेख है?', '[{"id":"A","text":"4","text_en":"4"},{"id":"B","text":"6","text_en":"6"},{"id":"C","text":"8","text_en":"8"},{"id":"D","text":"10","text_en":"10"}]', '2', '**✅ Correct Logic**: मनुस्मृति ने 8 प्रकार के विवाह बताए हैं: ब्रह्म, दैव, आर्ष, प्रजापत्य (प्रशस्त) और आसुर, गंधर्व, राक्षस, पैशाच (अपशस्त)।

**💡 Exam Fact**: ''पैशाच'' विवाह को सबसे निकृष्ट (Worst) माना गया है।

**🧠 Memory Tip**: 4 Good + 4 Bad = **8** total.

**🚫 Scam Alert**: गंधर्व विवाह (प्रेम विवाह) को क्षत्रियों के लिए मान्य माना गया था, भले ही वह अधम श्रेणी में था।', 2, 0, 6, NULL, 'How many types of marriages are mentioned in Manusmriti?', '**✅ Correct Logic**: Manusmriti lists 8 forms of marriage, divided into four righteous (Brahma, Daiva, etc.) and four non-righteous (Asura, Gandharva, etc.).

**💡 Exam Fact**: Paishacha (rape/forced marriage) is categorized as the worst form.

**🧠 Memory Tip**: 4 Right + 4 Wrong = **8**.

**🚫 Scam Alert**: Gandharva (love marriage) was considered acceptable primarily for Kshatriyas, despite being in the lower tier.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fe85b64d-26e7-4ecb-95c0-5e2e311a59d4', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'गद्य (Prose) में लिखी गई एकमात्र स्मृति कौन सी है?', '[{"id":"A","text":"मनुस्मृति","text_en":"मनुस्मृति"},{"id":"B","text":"विष्णु स्मृति","text_en":"विष्णु स्मृति"},{"id":"C","text":"नारद स्मृति","text_en":"नारद स्मृति"},{"id":"D","text":"बृहस्पति स्मृति","text_en":"बृहस्पति स्मृति"}]', '1', '**✅ Correct Logic**: अधिकांश स्मृतियाँ श्लोकों (Verse) में हैं, लेकिन विष्णु स्मृति मुख्य रूप से गद्य में है।

**💡 Exam Fact**: विष्णु स्मृति में ही पहली बार ''मुद्राओं'' (Coins) का उल्लेख मिलता है।

**🧠 Memory Tip**: **V**ishnu is **V**ery distinct (Prose style).

**🚫 Scam Alert**: श्लोक शैली स्मृतियों का मानक है, विष्णु स्मृति एक अपवाद (Exception) है।', 2, 0, 7, NULL, 'Which is the only Smriti written primarily in prose?', '**✅ Correct Logic**: While most Smritis use verse (shlokas), Vishnu Smriti is notably written in prose.

**💡 Exam Fact**: It contains the first mention of various coins in Smriti literature.

**🧠 Memory Tip**: **V**ishnu is **V**ery different (Prose style).

**🚫 Scam Alert**: Standard Smritis are in verse; always check for this exception.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2338776b-e854-4904-b99e-3176ffe905e7', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'कलियुग के लिए किस स्मृति को सर्वाधिक प्रामाणिक माना गया है?', '[{"id":"A","text":"मनुस्मृति","text_en":"मनुस्मृति"},{"id":"B","text":"याज्ञवल्क्य स्मृति","text_en":"याज्ञवल्क्य स्मृति"},{"id":"C","text":"पराशर स्मृति","text_en":"पराशर स्मृति"},{"id":"D","text":"नारद स्मृति","text_en":"नारद स्मृति"}]', '2', '**✅ Correct Logic**: ''कलौ पाराशरः स्मृतः'' - अर्थात कलियुग में पराशर स्मृति के नियम मान्य हैं।

**💡 Exam Fact**: पराशर स्मृति सती प्रथा के विरुद्ध थी और उसने विधवा विवाह तथा नियोग का समर्थन किया था।

**🧠 Memory Tip**: **P**arashara for the **P**resent era (Kaliyuga).

**🚫 Scam Alert**: सतयुग के लिए मनु, त्रेता के लिए गौतम और द्वापर के लिए शंख-लिखित स्मृतियाँ मानी जाती हैं।', 2, 0, 8, NULL, 'Which Smriti is considered the most authoritative for the Kali Yuga?', '**✅ Correct Logic**: Traditional texts state that while Manu was for Satya Yuga, Parashara is the guiding light for the current age of Kali.

**💡 Exam Fact**: Parashara Smriti is known for its relatively humane approach to women''s rights.

**🧠 Memory Tip**: **P**arashara = **P**resent age.

**🚫 Scam Alert**: Don''t default to Manu; he is for the Golden Age (Satya Yuga).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3d208f91-3453-4325-a96e-f27184095254', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'किस स्मृति में सर्वप्रथम ''कायस्थों'' (Kayasthas) का उल्लेख एक ''जाति'' के रूप में मिलता है?', '[{"id":"A","text":"मनुस्मृति","text_en":"मनुस्मृति"},{"id":"B","text":"याज्ञवल्क्य स्मृति","text_en":"याज्ञवल्क्य स्मृति"},{"id":"C","text":"ओशनम स्मृति","text_en":"ओशनम स्मृति"},{"id":"D","text":"नारद स्मृति","text_en":"नारद स्मृति"}]', '1', '**✅ Correct Logic**: याज्ञवल्क्य स्मृति में कायस्थों का उल्लेख लेखक/लेखाकार वर्ग के रूप में हुआ है।

**💡 Exam Fact**: बाद में ''ओशनम स्मृति'' में कायस्थों को एक स्पष्ट ''जाति'' के रूप में परिभाषित किया गया।

**🧠 Memory Tip**: **Y**ajnavalkya listed the **Y**oung writers (Kayasthas).

**🚫 Scam Alert**: यदि विकल्प में ''ओशनम'' और ''याज्ञवल्क्य'' दोनों हों, तो ''लेखक'' के रूप में प्रथम उल्लेख के लिए याज्ञवल्क्य सही है।', 2, 0, 9, NULL, 'In which Smriti do we find the first mention of Kayasthas as a specific caste?', '**✅ Correct Logic**: Yajnavalkya Smriti provides the earliest reference to Kayasthas as a class of scribes.

**💡 Exam Fact**: It''s only later, in the Oshanam Smriti, that they are consolidated into a distinct caste.

**🧠 Memory Tip**: **Y**ajnavalkya = **Y**ore''s first mention of Kayasthas.

**🚫 Scam Alert**: Many students pick Oshanam because it emphasizes the ''caste'' aspect, but the chronological first mention is Yajnavalkya.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3d83ae77-5a68-4590-8a87-f83bc5000f67', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'स्मृतियों के अनुसार ''अनुलोम विवाह'' (Anuloma Vivaha) किसे कहते हैं?', '[{"id":"A","text":"उच्च वर्ण का पुरुष और निम्न वर्ण की स्त्री","text_en":"उच्च वर्ण का पुरुष और निम्न वर्ण की स्त्री"},{"id":"B","text":"उच्च वर्ण की स्त्री और निम्न वर्ण का पुरुष","text_en":"उच्च वर्ण की स्त्री और निम्न वर्ण का पुरुष"},{"id":"C","text":"समान वर्ण के वर-वधू","text_en":"समान वर्ण के वर-वधू"},{"id":"D","text":"अंतर-धार्मिक विवाह","text_en":"अंतर-धार्मिक विवाह"}]', '0', '**✅ Correct Logic**: अनुलोम (Along the hair/natural) का अर्थ है जब लड़का उच्च वर्ण का हो और लड़की निम्न वर्ण की। इसे स्मृतियों में सामाजिक रूप से स्वीकार्य माना जाता था।

**💡 Exam Fact**: इसके विपरीत ''प्रतिलोम'' (Against the hair) विवाह (उच्च वर्ण की स्त्री + निम्न वर्ण का पुरुष) को निंदनीय माना गया था।

**🧠 Memory Tip**: **A**nuloma = **A**cceptable (Upper Boy).

**🚫 Scam Alert**: चांडाल जैसी जातियों की उत्पत्ति ''प्रतिलोम'' विवाहों का परिणाम मानी गई थी।', 2, 0, 10, NULL, 'According to Smritis, what is ''Anuloma Vivaha''?', '**✅ Correct Logic**: Anuloma refers to a marriage between a man of a higher caste and a woman of a lower caste. It was legally tolerated.

**💡 Exam Fact**: Pratiloma (lower man + higher woman) was severely discouraged and viewed as a cause of social degradation.

**🧠 Memory Tip**: **A**nuloma = **A**long the natural order (acc. to Smritis).

**🚫 Scam Alert**: Outcaste groups like Chandalas were historically theorized to be the offspring of Pratiloma unions.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('lTihaBUjgwFPf0DISWmrT', 'qps5_uf8HUURKTzaRtYp1', 'निम्नलिखित में से कौन-सा गैर-लाभकारी संगठन भारत में रोबोटिक्स और ऑटोमेशन में मानक स्थापित करने के लिए शीर्ष निकाय है?', '"[\"ऑल इंडिया काउंसिल फॉर रोबोटिक्स एंड ऑटोमेशन (AICRA)\",\"नेशनल इंस्टीट्यूट ऑफ रोबोटिक्स एंड आर्टिफिशियल इंटेलीजेंस (NIRA)\",\"भारत विज्ञान, प्रौद्योगिकी, इंजीनियरिंग और गणित (STEM) मिशन\",\"भारतीय रोबोटिक्स कौशल केन्द्र (RSCI)\"]"', '0.0', '### ✅ Correct Logic
**AICRA** (All India Council for Robotics & Automation) भारत में रोबोटिक्स और ऑटोमेशन क्षेत्र के लिए मानक स्थापित करने वाला प्रमुख गैर-लाभकारी निकाय है।

### 💡 Exam Fact
यह 2014 में स्थापित किया गया था और यह उद्योगों और शैक्षणिक संस्थानों के बीच की खाई को पाटने का काम करता है।

### 🧠 Memory Tip
**AICRA = All India Council for Robot Automation**.

### 🚫 Scam Alert
अन्य नाम (NIRA, RSCI) या तो काल्पनिक हैं या छोटे संगठन हैं। ''All India Council'' शब्द इसकी आधिकारिक स्थिति का संकेत देता है।', 2, 0, 1, 'Science & Tech', 'Which one of the following not-for-profit organization is the apex body for setting up standards in Robotics and Automation in India?', '### ✅ Correct Logic
**AICRA** (All India Council for Robotics & Automation) is the leading non-profit body setting standards for the robotics and automation sector in India.

### 💡 Exam Fact
Established in 2014, it works to bridge the gap between industries and academic institutions.

### 🧠 Memory Tip
**AICRA = All India Council for Robot Automation**.

### 🚫 Scam Alert
Other names (NIRA, RSCI) are either fictional or minor bodies. The term ''All India Council'' hints at its apex status.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('GjnMqU0GhoSj_swDegIsG', 'qps5_uf8HUURKTzaRtYp1', 'एक मैलवेयर, जो एक वैध सॉफ्टवेयर की तरह दिखता है और एक बार जब यह उपयोगकर्ता को बहला कर इसे इंस्टॉल करवा देता है, तो यह काफी हद तक वायरस या वर्म की तरह कार्य करता है, इसे क्या कहा जाता है?', '"[\"कीलॉगर (Keylogger)\",\"रैन्समवेयर (Ransomware)\",\"ट्रोजन (Trojan)\",\"स्पाइवेयर (Spyware)\"]"', '2.0', '### ✅ Correct Logic
**ट्रोजन हॉर्स** (Trojan Horse) एक वैध सॉफ्टवेयर होने का नाटक करता है। उपयोगकर्ता इसे उपयोगी समझकर डाउनलोड करता है, लेकिन यह पीछे से नुकसान पहुंचाता है।

### 💡 Exam Fact
यह नाम ग्रीक पौराणिक कथाओं के ''ट्रोजन हॉर्स'' (लकड़ी का घोड़ा) से लिया गया है, जिसका उपयोग ट्रॉय शहर में घुसने के लिए किया गया था।

### 🧠 Memory Tip
**Fake Gift = Trojan** (दिखने में अच्छा, अंदर से बुरा)।

### 🚫 Scam Alert
वायरस और वर्म खुद को दोहराते (Replicate) हैं, लेकिन ट्रोजन खुद को **नकल (Replicate) नहीं करता**। यह उपयोगकर्ता की गलती (Social Engineering) पर निर्भर करता है।', 2, 0, 2, 'ICT', 'A malware, that looks like a legitimate software and once it tricks a user into installing it, acts pretty much like a virus or worm, is known as:', '### ✅ Correct Logic
**Trojan Horse** pretends to be legitimate software. The user downloads it thinking it''s useful, but it causes harm in the background.

### 💡 Exam Fact
The name is derived from the ''Trojan Horse'' of Greek mythology, used to infiltrate the city of Troy.

### 🧠 Memory Tip
**Fake Gift = Trojan** (Looks good, acts bad).

### 🚫 Scam Alert
Viruses and Worms replicate themselves, but a Trojan **does not replicate**. It relies on user error (Social Engineering).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cShegMcvN9IDqUeihFRNK', 'qps5_uf8HUURKTzaRtYp1', 'भारतीय संविधान के किस अनुच्छेद के अन्तर्गत राष्ट्रपति राज्य विशेष के लिए अनुसूचित जनजाति समुदायों के लिए लोक अधिसूचना जारी करते हैं?', '"[\"अनुच्छेद 340 (Article 340)\",\"अनुच्छेद 349 (Article 349)\",\"अनुच्छेद 342 (Article 342)\",\"अनुच्छेद 338 (Article 338)\"]"', '2.0', '### ✅ Correct Logic
**अनुच्छेद 342** राष्ट्रपति को किसी राज्य/केंद्र शासित प्रदेश के संबंध में जनजातियों को ''अनुसूचित जनजाति'' के रूप में निर्दिष्ट करने की शक्ति देता है।

### 💡 Exam Fact
* **341**: अनुसूचित जाति (SC)
* **342**: अनुसूचित जनजाति (ST)
* **340**: पिछड़ा वर्ग (OBC)

### 🧠 Memory Tip
**SC (1) -> ST (2)** (341 -> 342)।

### 🚫 Scam Alert
338 आयोग के लिए है, 342 सूची (List) के लिए है। दोनों में अंतर है।', 2, 0, 3, 'Polity', 'Under which Article of the Indian Constitution does the President issue a public notification for the Scheduled Tribes for a specific state?', '### ✅ Correct Logic
**Article 342** empowers the President to specify tribes as ''Scheduled Tribes'' in relation to a State/UT.

### 💡 Exam Fact
* **341**: Scheduled Castes (SC)
* **342**: Scheduled Tribes (ST)
* **340**: Backward Classes (OBC)

### 🧠 Memory Tip
**SC (1) -> ST (2)** (341 -> 342).

### 🚫 Scam Alert
338 is for the Commission, 342 is for the List. There is a difference.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sSdX7dRSiyzkwKN9pp-3g', 'qps5_uf8HUURKTzaRtYp1', 'मध्यप्रदेश में मैंगनीज के संबंध में निम्नलिखित कथनों को पढ़िए और सही उत्तर चुनिए:
1. 2020-21 में, म.प्र. मैंगनीज निक्षेप (Reserves) में देश में द्वितीय था।
2. 2020-21 में, म.प्र. मैंगनीज उत्पादन (Production) में देश में प्रथम था।
3. छिंदवाड़ा की गोदावरी-वर्धा घाटियों में निक्षेप हैं।
4. झाबुआ की थांदला तहसील में निक्षेप हैं।', '"[\"1, 2 एवं 3 सही हैं\",\"2, 3 एवं 4 सही हैं\",\"1, 3 एवं 4 सही हैं\",\"1, 2, 3 एवं 4 सही हैं\"]"', '3.0', '### ✅ Correct Logic
म.प्र. मैंगनीज का **सबसे बड़ा उत्पादक** (लगभग 33%) है। इसके मुख्य क्षेत्र बालाघाट और छिंदवाड़ा (गोदावरी घाटी क्षेत्र) हैं। झाबुआ (थांदला) में भी भंडार हैं। निक्षेप (Reserves) में ओडिशा प्रथम है, म.प्र. का स्थान बाद में आता है (लेकिन स्टेटमेंट 1 इसे ''द्वितीय'' कह रहा है जो कई स्रोतों के अनुसार स्वीकार्य हो सकता है या प्रश्न में ''विवादास्पद'' हो सकता है, लेकिन आयोग आमतौर पर इसे सही मानता है)।

### 💡 Exam Fact
**भरवेली (बालाघाट)** एशिया की सबसे बड़ी मैंगनीज खदान है।

### 🧠 Memory Tip
**MP = Manganese Production King**.

### 🚫 Scam Alert
निक्षेप (Reserves) और उत्पादन (Production) में अंतर हमेशा याद रखें। ओडिशा निक्षेप में राजा है, म.प्र. उत्पादन में।', 2, 0, 4, 'MP Geography', 'Read statements regarding manganese in MP:
1. In 2020-21, MP ranked 2nd in reserves.
2. In 2020-21, MP ranked 1st in production.
3. Deposits in Godavari-Wardha valleys (Chhindwara).
4. Deposits in Thandla tehsil (Jhabua).', '### ✅ Correct Logic
MP is the **largest producer** (approx 33%) of Manganese. Main areas are Balaghat and Chhindwara (Godavari valley region). Jhabua (Thandla) also has deposits. In reserves, Odisha is first, MP follows. The commission generally accepts these statements as correct in context.

### 💡 Exam Fact
**Bharveli (Balaghat)** is the largest Manganese mine in Asia.

### 🧠 Memory Tip
**MP = Manganese Production King**.

### 🚫 Scam Alert
Always distinguish between Reserves and Production. Odisha is King of Reserves, MP is King of Production.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('MloiYXD6Z7C4Tw8Ub2qQe', 'qps5_uf8HUURKTzaRtYp1', 'भारत के राष्ट्रपति पर महाभियोग निम्नलिखित में से किस आधार पर लगाया जा सकता है?', '"[\"व्यावसायिक कदाचार (Professional misconduct)\",\"संविधान का उल्लंघन (Violation of the Constitution)\",\"लाभ का व्यवसाय करना (Carrying on a vocation of profit)\",\"मानसिक अस्थिरता (Mental instability)\"]"', '1.0', '### ✅ Correct Logic
अनुच्छेद 61 के अनुसार, राष्ट्रपति पर महाभियोग केवल एक ही आधार पर लगाया जा सकता है: **''संविधान का उल्लंघन''** (Violation of the Constitution)।

### 💡 Exam Fact
संविधान में ''संविधान का उल्लंघन'' वाक्यांश को परिभाषित **नहीं** किया गया है।

### 🧠 Memory Tip
**President breaks the Supreme Law -> Gets Fired**.

### 🚫 Scam Alert
''साबित कदाचार'' (Proved Misbehavior) और ''अक्षमता'' (Incapacity) न्यायाधीशों (Judges) को हटाने के आधार हैं, राष्ट्रपति के नहीं।', 2, 0, 5, 'Polity', 'Impeachment can be imposed on the President of India on which of the following grounds?', '### ✅ Correct Logic
According to Article 61, Impeachment can be initiated against the President only on one ground: **''Violation of the Constitution''**.

### 💡 Exam Fact
The phrase ''Violation of the Constitution'' is **not defined** in the Constitution.

### 🧠 Memory Tip
**President breaks the Supreme Law -> Gets Fired**.

### 🚫 Scam Alert
''Proved Misbehavior'' and ''Incapacity'' are grounds for removing **Judges**, not the President.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0WgKeGltbdzL8sz2Pn6R4', 'qps5_uf8HUURKTzaRtYp1', 'मध्यप्रदेश में काली मिट्टी के संबंध में इनमें से कौन-सा कथन सही नहीं है?', '"[\"यह दक्कन लावा के अपक्षय से निर्मित हुई है।\",\"इस मिट्टी में नाइट्रोजन, फॉस्फोरस एवं जैव पदार्थों की मात्रा अधिक होती है।\",\"इस मिट्टी में नमी धारण करने की क्षमता अधिक होती है।\",\"यह मिट्टी मुख्यतः राज्य के पश्चिमी भागों में पाई जाती है।\"]"', '1.0', '### ✅ Correct Logic
काली मिट्टी (Regur Soil) में **नाइट्रोजन (N), फॉस्फोरस (P) और ह्यूमस की कमी** होती है। इसमें चूना, लोहा, मैग्नीशियम और एल्यूमिना अधिक होता है। अतः कथन (B) गलत है।

### 💡 Exam Fact
काली मिट्टी **''स्वतः जुताई''** (Self-ploughing) वाली मिट्टी कहलाती है क्योंकि सूखने पर इसमें दरारें पड़ जाती हैं।

### 🧠 Memory Tip
**Black lacks N-P-H** (Nitrogen, Phosphorus, Humus).

### 🚫 Scam Alert
ज्यादातर भारतीय मिट्टियों में N-P-K की कमी होती है। अगर कोई विकल्प कहता है कि मिट्टी N और P से ''भरपूर'' है, तो वह अक्सर गलत होता है (जलोढ़ को छोड़कर, लेकिन उसमें भी N कम होता है)।', 2, 0, 6, 'MP Geography', 'Which of these statements is not correct regarding black soil in Madhya Pradesh?', '### ✅ Correct Logic
Black soil (Regur Soil) is **deficient in Nitrogen (N), Phosphorus (P), and Humus**. It is rich in Lime, Iron, Magnesium, and Alumina. Hence statement (B) is incorrect.

### 💡 Exam Fact
Black soil is called **''Self-ploughing''** soil because cracks develop when it dries.

### 🧠 Memory Tip
**Black lacks N-P-H** (Nitrogen, Phosphorus, Humus).

### 🚫 Scam Alert
Most Indian soils are deficient in N-P-K. If an option says a soil is ''rich'' in N and P, it''s usually wrong (except Alluvial, but even that lacks N).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cIybqUmBWTo3CFc5iFw7L', 'qps5_uf8HUURKTzaRtYp1', 'आई.सी.एम.आर. राष्ट्रीय जनजाति स्वास्थ्य अनुसंधान संस्थान (NIRTH) मध्यप्रदेश के किस शहर में स्थापित है?', '"[\"इंदौर (Indore)\",\"भोपाल (Bhopal)\",\"ग्वालियर (Gwalior)\",\"जबलपुर (Jabalpur)\"]"', '3.0', '### ✅ Correct Logic
**NIRTH** (National Institute of Research in Tribal Health) **जबलपुर** में स्थित है। यह ICMR का एकमात्र संस्थान है जो आदिवासी स्वास्थ्य के लिए समर्पित है।

### 💡 Exam Fact
जबलपुर महाकोशल क्षेत्र का केंद्र है, जहाँ आदिवासी आबादी का घनत्व अधिक है।

### 🧠 Memory Tip
**Tribal Health -> Gondwana Area -> Jabalpur**.

### 🚫 Scam Alert
भोपाल में AIIMS और IIFM है, लेकिन NIRTH जबलपुर में है।', 2, 0, 7, 'MP GK', 'In which city of Madhya Pradesh is National Institute of Research in Tribal Health (NIRTH) located?', '### ✅ Correct Logic
**NIRTH** is located in **Jabalpur**. It is the only institute of ICMR dedicated to tribal health.

### 💡 Exam Fact
Jabalpur is the center of the Mahakoshal region, which has a high density of tribal population.

### 🧠 Memory Tip
**Tribal Health -> Gondwana Area -> Jabalpur**.

### 🚫 Scam Alert
Bhopal has AIIMS and IIFM, but NIRTH is in Jabalpur.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fgXwHYD9Zefir20yzi3t6', 'qps5_uf8HUURKTzaRtYp1', 'जनजातीय वर्ग के विद्यार्थियों को शंकर शाह और रानी दुर्गावती पुरस्कार योजना दिए जाने का उद्देश्य है:', '"[\"उच्च अध्ययन के लिए आवासीय सुविधा हेतु\",\"10वीं और 12वीं कक्षा की परीक्षाओं में मेधावी स्थान पाने वाले विद्यार्थियों को प्रोत्साहित करने हेतु\",\"तकनीकी शिक्षा में प्रोत्साहन हेतु\",\"राष्ट्रीय प्रवेश परीक्षाओं में सफल विद्यार्थियों को उच्च अध्ययन के लिए प्रोत्साहित करने हेतु\"]"', '1.0', '### ✅ Correct Logic
यह पुरस्कार **10वीं और 12वीं** में टॉप करने वाले या मेधावी स्थान प्राप्त करने वाले आदिवासी (ST) छात्रों को दिया जाता है।

### 💡 Exam Fact
शंकर शाह गोंडवाना के राजा थे और रानी दुर्गावती वीरांगना थीं। यह पुरस्कार उनके सम्मान में है। पुरस्कार राशि: 10वीं के लिए (₹1000-₹5000 रेंज) और 12वीं के लिए अलग।

### 🧠 Memory Tip
**Kings & Queens reward Toppers** (School level).

### 🚫 Scam Alert
अन्य विकल्प (तकनीकी शिक्षा, प्रवेश परीक्षा) अन्य योजनाओं (जैसे ''प्रतिभा किरण'' या ''मेधावी विद्यार्थी'') के तहत आते हैं।', 2, 0, 8, 'MP Schemes', 'The objective of conferring the Shankar Shah and Rani Durgavati award to tribal students is:', '### ✅ Correct Logic
This award is given to Tribal (ST) students who secure **meritorious positions in 10th and 12th** standards.

### 💡 Exam Fact
Shankar Shah was the King of Gondwana and Rani Durgavati was a warrior queen. The award is in their honor.

### 🧠 Memory Tip
**Kings & Queens reward Toppers** (School level).

### 🚫 Scam Alert
Other options (Technical education, Entrance exams) fall under other schemes (like ''Pratibha Kiran'' or ''Medhavi Vidyarthi'').', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('A6IDvldEhgwjjOMw_p2tn', 'qps5_uf8HUURKTzaRtYp1', 'दिनांक 23.12.2017 से ''आहार अनुदान योजना'' किस जनजातीय समुदाय के कुपोषण को दूर करने की योजना है?', '"[\"भील जनजातीय समुदाय (Bhil Tribal Community)\",\"विशेष पिछड़े जनजातीय समुदाय (Special Backward Tribal Community)\",\"अशिक्षित जनजातियाँ (Illiterate Tribes)\",\"बेरोजगार जनजातियाँ (Unemployed Tribes)\"]"', '1.0', '### ✅ Correct Logic
यह योजना म.प्र. की **विशेष पिछड़ी जनजातियों (PVTGs)** - **बैगा, भारिया और सहरिया** के लिए है। इसमें परिवार की महिला मुखिया के खाते में ₹1000/माह (अब ₹1500) दिए जाते हैं।

### 💡 Exam Fact
मध्य प्रदेश में 3 PVTGs हैं: **B**aiga, **B**haria, **S**aharia (BBS)।

### 🧠 Memory Tip
**Ahar for BBS** (Baiga, Bharia, Saharia).

### 🚫 Scam Alert
यह सभी जनजातियों (जैसे भील/गोंड) के लिए नहीं है, केवल ''अति पिछड़ी'' (Special Backward) के लिए है।', 2, 0, 9, 'MP Schemes', 'Since the date 23.12.2017, ''Ahar Anudan Yojana'' is a yojana to get rid of malnutrition of which tribal community?', '### ✅ Correct Logic
This scheme is for the **Special Backward Tribal Communities (PVTGs)** of MP - **Baiga, Bharia, and Saharia**. ₹1000/month (now ₹1500) is transferred to the female head of the family.

### 💡 Exam Fact
MP has 3 PVTGs: **B**aiga, **B**haria, **S**aharia (BBS).

### 🧠 Memory Tip
**Ahar for BBS** (Baiga, Bharia, Saharia).

### 🚫 Scam Alert
It is not for all tribes (like Bhil/Gond), only for the ''Special Backward'' ones.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('HqNFSO5593NR8iciS--Pi', 'qps5_uf8HUURKTzaRtYp1', 'मध्यप्रदेश में वर्ष 2023-24 में कुल कितनी वृहद एवं मध्यम एकीकृत जनजातीय विकास परियोजनाएँ अस्तित्व में हैं?', '"[\"20\",\"25\",\"31\",\"36\"]"', '2.0', '### ✅ Correct Logic
मध्य प्रदेश में वर्तमान में **31** एकीकृत जनजातीय विकास परियोजनाएँ (ITDP) संचालित हैं।

### 💡 Exam Fact
इसके अलावा म.प्र. में **MADA** (Modified Area Development Approach) के भी कई पॉकेट्स हैं।

### 🧠 Memory Tip
**Tribal Projects = 31** (Prime Number).

### 🚫 Scam Alert
यह एक तथ्यात्मक प्रश्न है। आर्थिक सर्वेक्षण (Economic Survey) के अनुसार संख्या बदलती नहीं है जब तक नए जिले/प्रोजेक्ट न बनें।', 2, 0, 10, 'MP Economy', 'How many total major and medium Integrated Tribal Development Projects (ITDP) are in existence in Madhya Pradesh in 2023-24?', '### ✅ Correct Logic
Currently, there are **31** Integrated Tribal Development Projects (ITDP) operational in Madhya Pradesh.

### 💡 Exam Fact
Apart from this, MP also has several **MADA** (Modified Area Development Approach) pockets.

### 🧠 Memory Tip
**Tribal Projects = 31** (Prime Number).

### 🚫 Scam Alert
This is a factual question. As per the Economic Survey, the number is static unless new projects are announced.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('alzbOjm6YaKTOEiN5WjlC', 'qps5_uf8HUURKTzaRtYp1', 'मौद्रिक नीति का मुख्य उद्देश्य क्या है?', '"[\"सरकारी खर्च बढ़ाना (Increase government spending)\",\"मूल्य स्थिरता बनाए रखना और आर्थिक वृद्धि सुनिश्चित करना (Maintain price stability while ensuring economic growth)\",\"राजकोषीय घाटा कम करना (Reduce fiscal deficit)\",\"विदेशी मुद्रा भण्डार को नियंत्रित करना (Control foreign exchange reserves)\"]"', '1.0', '### ✅ Correct Logic
RBI अधिनियम के अनुसार, मौद्रिक नीति का प्राथमिक उद्देश्य **''विकास के उद्देश्य को ध्यान में रखते हुए मूल्य स्थिरता बनाए रखना''** है।

### 💡 Exam Fact
भारत में **मुद्रास्फीति लक्ष्यीकरण** (Inflation Targeting) का लक्ष्य 4% (+/- 2%) है।

### 🧠 Memory Tip
**Policy = Stability + Growth**.

### 🚫 Scam Alert
''सरकारी खर्च'' और ''राजकोषीय घाटा'' **राजकोषीय नीति** (Fiscal Policy) का हिस्सा हैं, जो सरकार बनाती है, RBI नहीं।', 2, 0, 11, 'Economy', 'What is the primary objective of the Monetary Policy?', '### ✅ Correct Logic
According to the RBI Act, the primary objective is **''to maintain price stability while keeping in mind the objective of growth''**.

### 💡 Exam Fact
The **Inflation Targeting** goal in India is 4% (+/- 2%).

### 🧠 Memory Tip
**Policy = Stability + Growth**.

### 🚫 Scam Alert
''Government spending'' and ''Fiscal deficit'' are part of **Fiscal Policy**, managed by the Govt, not RBI.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('UQy5HTUIqW19E8uwSscDk', 'qps5_uf8HUURKTzaRtYp1', 'वित्तीय वर्ष 2023-24 में भारत के कुल व्यापार घाटे को कम करने में किस क्षेत्र ने महत्त्वपूर्ण भूमिका निभाई?', '"[\"कृषि निर्यात (Agricultural exports)\",\"माल निर्यात (Merchandise exports)\",\"सेवा निर्यात (Service exports)\",\"ऑटोमोबाइल निर्यात (Automobile exports)\"]"', '2.0', '### ✅ Correct Logic
भारत का माल (Merchandise) व्यापार हमेशा घाटे में रहता है, लेकिन **सेवा निर्यात** (IT, Business Services) अधिशेष (Surplus) में रहता है, जो कुल घाटे की भरपाई करता है।

### 💡 Exam Fact
सेवा निर्यात ने 2023-24 में लगभग $340 बिलियन का आंकड़ा छू लिया, जिससे चालू खाता घाटा (CAD) नियंत्रण में रहा।

### 🧠 Memory Tip
**IT Services save the day!**

### 🚫 Scam Alert
''माल निर्यात'' में घाटा होता है (आयात > निर्यात)। ''सेवा निर्यात'' ही वह ढाल (Cushion) है जो हमें बचाती है।', 2, 0, 12, 'Economy', 'Which sector played a key role in cushioning India''s overall trade deficit in the financial year 2023-24?', '### ✅ Correct Logic
India''s Merchandise trade is always in deficit, but **Service Exports** (IT, Business Services) run a surplus, cushioning the overall deficit.

### 💡 Exam Fact
Service exports touched approx $340 Billion in 2023-24, keeping the Current Account Deficit (CAD) in check.

### 🧠 Memory Tip
**IT Services save the day!**

### 🚫 Scam Alert
''Merchandise exports'' cause the deficit (Import > Export). ''Service exports'' act as the cushion.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('PzLRQXL34nTZFrBQrn3u6', 'qps5_uf8HUURKTzaRtYp1', 'वर्ष 2017-18 में भारत के किस राज्य में विनिर्माण क्षेत्र में पूँजी गहनता सबसे अधिक है?', '"[\"गुजरात (Gujarat)\",\"महाराष्ट्र (Maharashtra)\",\"तमिलनाडु (Tamil Nadu)\",\"मध्य प्रदेश (Madhya Pradesh)\"]"', '0.0', '### ✅ Correct Logic
**गुजरात** अपने बड़े पेट्रोकेमिकल और भारी उद्योगों (जैसे जामनगर रिफाइनरी) के कारण विनिर्माण में उच्चतम ''पूंजी निवेश'' (Capital Investment) वाला राज्य है।

### 💡 Exam Fact
पूंजी गहनता (Capital Intensity) का अर्थ है प्रति श्रमिक निवेशित पूंजी। गुजरात के उद्योग मशीनरी-भारी हैं।

### 🧠 Memory Tip
**Gujarat = Giant Machines** (Reliance, Adani).

### 🚫 Scam Alert
तमिलनाडु में ''कारखानों की संख्या'' सबसे अधिक हो सकती है, लेकिन ''पूंजी निवेश'' की मात्रा में गुजरात सबसे आगे है।', 2, 0, 13, 'Economy', 'In India, which state has the highest capital intensity in manufacturing sector in 2017-18?', '### ✅ Correct Logic
**Gujarat** has the highest ''Capital Investment'' in manufacturing due to its massive petrochemical and heavy industries (like Jamnagar Refinery).

### 💡 Exam Fact
Capital Intensity means capital invested per worker. Gujarat''s industries are machinery-heavy.

### 🧠 Memory Tip
**Gujarat = Giant Machines** (Reliance, Adani).

### 🚫 Scam Alert
Tamil Nadu might have the highest ''number of factories'', but Gujarat leads in the volume of ''Capital Investment''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('zD3AxdT8jTZ1CBXKuTIbw', 'qps5_uf8HUURKTzaRtYp1', 'भारत किन कृषि उत्पादों में सबसे बड़ा उत्पादक है?', '"[\"चावल, गेहूँ और कपास (Rice, Wheat and Cotton)\",\"दूध, दालें और मसाले (Milk, Pulses and Spices)\",\"चाय, कॉफी और जूट (Tea, Coffee and Jute)\",\"गन्ना, मक्का और तिलहन (Sugarcane, Maize and Oilseeds)\"]"', '1.0', '### ✅ Correct Logic
भारत **दूध, दालें और मसालों** का दुनिया में सबसे बड़ा उत्पादक है।

### 💡 Exam Fact
* **चावल/गेहूँ**: चीन #1, भारत #2
* **दूध**: भारत #1 (श्वेत क्रांति)
* **दालें**: भारत #1 उत्पादक और उपभोक्ता दोनों

### 🧠 Memory Tip
**M-P-S** (Milk, Pulses, Spices) = **Made in India**.

### 🚫 Scam Alert
कॉफी में ब्राजील #1 है। मक्का में अमेरिका #1 है। विकल्पों को काटें (Eliminate)।', 2, 0, 14, 'Agriculture', 'India is the largest producer of which agricultural products?', '### ✅ Correct Logic
India is the world''s largest producer of **Milk, Pulses, and Spices**.

### 💡 Exam Fact
* **Rice/Wheat**: China #1, India #2
* **Milk**: India #1 (White Revolution)
* **Pulses**: India #1 Producer & Consumer

### 🧠 Memory Tip
**M-P-S** (Milk, Pulses, Spices) = **Made in India**.

### 🚫 Scam Alert
Brazil is #1 in Coffee. USA is #1 in Maize. Eliminate options.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('kO8LinCSxUATFo4MYllhO', 'qps5_uf8HUURKTzaRtYp1', 'वर्ष 2011 की जनगणना के अनुसार, निम्नलिखित में से कौन-से जिले की जनसंख्या की दशकीय वृद्धि दर सर्वाधिक थी?', '"[\"सिंगरौली (Singrauli)\",\"भोपाल (Bhopal)\",\"इंदौर (Indore)\",\"बड़वानी (Barwani)\"]"', '2.0', '### ✅ Correct Logic
**इंदौर** की दशकीय वृद्धि दर (2001-2011) **32.9%** थी, जो म.प्र. के सभी जिलों में सर्वाधिक थी।

### 💡 Exam Fact
झाबुआ दूसरे स्थान पर था। सबसे कम वृद्धि दर **अनूपपुर** (12.3%) में थी।

### 🧠 Memory Tip
**Indore is Growing Fast** (Population & Cleanliness).

### 🚫 Scam Alert
भोपाल का घनत्व (Density) सबसे ज्यादा है, लेकिन वृद्धि दर (Growth Rate) में इंदौर टॉप पर था।', 2, 0, 15, 'MP Census', 'According to the 2011 Census, which of the following districts had the highest decadal growth rate of population?', '### ✅ Correct Logic
**Indore** had a decadal growth rate (2001-2011) of **32.9%**, which was the highest among all districts in MP.

### 💡 Exam Fact
Jhabua was second. The lowest growth rate was in **Anuppur** (12.3%).

### 🧠 Memory Tip
**Indore is Growing Fast** (Population & Cleanliness).

### 🚫 Scam Alert
Bhopal has the highest Density, but Indore topped in Growth Rate.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9dDliMwGXv0UVa5DFUUY4', 'qps5_uf8HUURKTzaRtYp1', '2020 में SDG इंडिया इंडेक्स 3.0 में मध्यप्रदेश का समग्र SDG (सतत विकास लक्ष्य) स्कोर कितना था?', '"[\"56\",\"58\",\"60\",\"62\"]"', '3.0', '### ✅ Correct Logic
नीति आयोग के SDG इंडिया इंडेक्स 3.0 (2020-21) में मध्य प्रदेश का स्कोर **62** था। इसे ''Performer'' श्रेणी में रखा गया था।

### 💡 Exam Fact
केरल (75) शीर्ष पर था। बिहार (52) सबसे नीचे था।

### 🧠 Memory Tip
**MP scored a Six-Two (62)**.

### 🚫 Scam Alert
स्कोर हर साल बदलता है। प्रश्न विशेष रूप से ''2020'' (इंडेक्स 3.0) के बारे में पूछ रहा है।', 2, 0, 16, 'Current Affairs/Index', 'What was Madhya Pradesh''s composite SDG (Sustainable Development Goals) score in the SDG India Index 3.0 in 2020?', '### ✅ Correct Logic
In NITI Aayog''s SDG India Index 3.0 (2020-21), Madhya Pradesh scored **62**. It was placed in the ''Performer'' category.

### 💡 Exam Fact
Kerala (75) was at the top. Bihar (52) was at the bottom.

### 🧠 Memory Tip
**MP scored a Six-Two (62)**.

### 🚫 Scam Alert
Scores change every year. The question specifically asks about ''2020'' (Index 3.0).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Zhr5mEMfwU0SLbiwyVda9', 'qps5_uf8HUURKTzaRtYp1', 'राष्ट्रीय पृथ्वी विज्ञान अध्ययन केन्द्र (NCESS) किस राज्य में स्थित है?', '"[\"आन्ध्र प्रदेश (Andhra Pradesh)\",\"केरल (Kerala)\",\"तमिलनाडु (Tamil Nadu)\",\"कर्नाटक (Karnataka)\"]"', '1.0', '### ✅ Correct Logic
**NCESS** (National Centre for Earth Science Studies) **तिरुवनंतपुरम, केरल** में स्थित है।

### 💡 Exam Fact
यह पृथ्वी विज्ञान मंत्रालय (MoES) के तहत एक स्वायत्त संस्थान है।

### 🧠 Memory Tip
**Earth Science near the Earth''s End (South)** -> Kerala.

### 🚫 Scam Alert
बेंगलुरु (कर्नाटक) में ISRO है, लेकिन NCESS केरल में है।', 2, 0, 17, 'Science Institutes', 'The National Centre for Earth Science Studies (NCESS) is situated in which state?', '### ✅ Correct Logic
**NCESS** (National Centre for Earth Science Studies) is located in **Thiruvananthapuram, Kerala**.

### 💡 Exam Fact
It is an autonomous institute under the Ministry of Earth Sciences (MoES).

### 🧠 Memory Tip
**Earth Science near the Earth''s End (South)** -> Kerala.

### 🚫 Scam Alert
Bangalore (Karnataka) has ISRO, but NCESS is in Kerala.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('lGrjeFeqHoDWAwDAb74XY', 'qps5_uf8HUURKTzaRtYp1', 'उद्यम क्रांति योजना का मुख्य उद्देश्य क्या है?', '"[\"MSMEs को मुफ्त बिजली प्रदान करना\",\"स्वरोजगार के लिए गारंटी रहित ऋण प्रदान करना\",\"स्टार्टअप्स के लिए कर छूट\",\"उद्यमियों के लिए मुफ्त प्रशिक्षण\"]"', '1.0', '### ✅ Correct Logic
''मुख्यमंत्री उद्यम क्रांति योजना'' का उद्देश्य युवाओं को स्वरोजगार के लिए **गारंटी रहित ऋण** (Collateral-free credit) और ब्याज सब्सिडी प्रदान करना है।

### 💡 Exam Fact
ऋण सीमा: ₹1 लाख से ₹50 लाख। सरकार 3% ब्याज सब्सिडी देती है।

### 🧠 Memory Tip
**Kranti = Credit without Guarantee**.

### 🚫 Scam Alert
यह ''मुफ्त बिजली'' या ''ट्रेनिंग'' के बारे में नहीं है। यह अपना बिजनेस शुरू करने के लिए ''पैसा'' (Loan) देने के बारे में है।', 2, 0, 18, 'MP Schemes', 'What is the main goal of the Udyam Kranti Yojna?', '### ✅ Correct Logic
''Mukhyamantri Udyam Kranti Yojana'' aims to provide **collateral-free credit** and interest subsidy to youth for self-employment.

### 💡 Exam Fact
Loan limit: ₹1 Lakh to ₹50 Lakh. Govt provides 3% interest subsidy.

### 🧠 Memory Tip
**Kranti = Credit without Guarantee**.

### 🚫 Scam Alert
It''s not about ''free electricity'' or ''training''. It''s about giving ''money'' (Loan) to start a business.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sSwaKhsdd81OJ6KGUAcIF', 'qps5_uf8HUURKTzaRtYp1', '2023-24 में मध्यप्रदेश सरकार के कुल व्यय बजट का कितना प्रतिशत शिक्षा के क्षेत्र के लिए आबंटित किया गया था?', '"[\"12-22%\",\"10-5%\",\"18-0%\",\"15-0%\"]"', '3.0', '### ✅ Correct Logic
म.प्र. बजट 2023-24 में शिक्षा के लिए आवंटन लगभग **15-16%** के आसपास था (सटीक डेटा के अनुसार 15% सबसे निकटतम सही विकल्प है)।

### 💡 Exam Fact
राज्यों के बजट में शिक्षा और स्वास्थ्य प्रमुख घटक होते हैं। म.प्र. आमतौर पर शिक्षा पर अपने बजट का एक बड़ा हिस्सा खर्च करता है।

### 🧠 Memory Tip
**Education gets Fifteen (15)**.

### 🚫 Scam Alert
बजट के आंकड़े सटीक होते हैं। 10% बहुत कम है, 20% बहुत ज्यादा। 15% मानक औसत है।', 2, 0, 19, 'MP Budget', 'What percentage of the Madhya Pradesh government''s total expenditure budget was allocated to education in 2023-24?', '### ✅ Correct Logic
In MP Budget 2023-24, the allocation for education was around **15-16%** (15% is the closest correct option based on data).

### 💡 Exam Fact
Education and Health are key components of state budgets. MP generally spends a significant chunk on education.

### 🧠 Memory Tip
**Education gets Fifteen (15)**.

### 🚫 Scam Alert
Budget figures are precise. 10% is too low, 20% is too high. 15% is the standard average.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('oomo-3D-CBnDRF3iNy2o3', 'qps5_uf8HUURKTzaRtYp1', '2023-24 में मध्यप्रदेश में सबसे अधिक उत्पादकता वाली सब्ज़ी कौन-सी थी?', '"[\"प्याज (Onion)\",\"आलू (Potato)\",\"बैंगन (Brinjal)\",\"टमाटर (Tomato)\"]"', '0.0', '### ✅ Correct Logic
म.प्र. **प्याज** का एक प्रमुख उत्पादक है (विशेष रूप से मालवा और खंडवा क्षेत्र)। इसकी उत्पादकता (Productivity) प्रति हेक्टेयर सबसे अधिक दर्ज की गई।

### 💡 Exam Fact
म.प्र., महाराष्ट्र के बाद भारत का दूसरा सबसे बड़ा प्याज उत्पादक राज्य है।

### 🧠 Memory Tip
**MP makes India cry (with Onions)**.

### 🚫 Scam Alert
आलू उत्पादन में भी म.प्र. आगे है (इंदौर/उज्जैन), लेकिन ''उत्पादकता'' (Yield per hectare) में प्याज अक्सर बाजी मार ले जाता है।', 2, 0, 20, 'MP Agriculture', 'In Madhya Pradesh, which vegetable recorded the highest productivity in 2023-24?', '### ✅ Correct Logic
MP is a major producer of **Onion** (especially Malwa and Khandwa regions). Its productivity (yield per hectare) was recorded the highest.

### 💡 Exam Fact
MP is the 2nd largest onion producer in India after Maharashtra.

### 🧠 Memory Tip
**MP makes India cry (with Onions)**.

### 🚫 Scam Alert
MP is big in Potato too (Indore/Ujjain), but in ''Productivity'', Onion often takes the lead.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('udig9i9kUMK1yQuV5_A4K', 'qps5_uf8HUURKTzaRtYp1', 'कांची का कैलासनाथर मंदिर किस शैली में बना है?', '"[\"राजसिम्हा शैली (Rajsimha style)\",\"मामल्ल शैली (Mamalla style)\",\"महेन्द्र शैली (Mahendra style)\",\"नंदीवर्मन शैली (Nandivarman style)\"]"', '0.0', NULL, 2, 0, 21, 'History & Culture', 'In which style is the Kailasanathar temple of Kanchi built?', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6LgbVjBiDgfd6Emcd73wQ', 'qps5_uf8HUURKTzaRtYp1', '''एडोब फोटोशॉप'' (Adobe Photoshop) किस प्रकार के सामान्य प्रयोजन एप्लिकेशन सॉफ्टवेयर का एक उदाहरण है?', '"[\"ग्राफिक्स सॉफ्टवेयर (Graphics Software)\",\"मल्टीमीडिया सॉफ्टवेयर\",\"वेब सीरीज़ सॉफ्टवेयर\",\"डेटाबेस सॉफ्टवेयर\"]"', '0.0', NULL, 2, 0, 22, 'ICT', 'Adobe Photoshop is an example of which type of software?', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
