INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('h-gHA1riiJH_sTtUy6bVc', 'qps5_uf8HUURKTzaRtYp1', 'ISFR 2021 के अनुसार किस जिले में वन आवरण 10% से कम है?', '"[\"अशोकनगर\",\"मुरैना\",\"भिण्ड\",\"गुना\"]"', '2.0', NULL, 2, 0, 31, 'MP Geography', 'Which MP district has forest cover less than 10%?', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
