INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('tIrr2MYZEO5qiYMsVPELQ', 'I5wtEA-CQuFwOW-vUnTP2', 'Bharat ka apna GPS system, NavIC (IRNSS), kitne satellites ka constellation hai?', '"[\"5\",\"7\",\"9\",\"11\"]"', '1.0', 'NavIC (IRNSS) 7 satellites ka constellation hai jo Bharat ko svadeshi navigation system pradan karta hai.', 3, 1, 4, 'Space Technology', 'NavIC (IRNSS), India''s own GPS system, is a constellation of how many satellites?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a12J8fhGrAmWzaUYv5EZ8', 'I5wtEA-CQuFwOW-vUnTP2', 'Shiksha (Education) ke liye Bharat ka pehla dedicated satellite kaun sa tha?', '"[\"GSAT-1\",\"EDUSAT (GSAT-3)\",\"INSAT-3A\",\"Kalpana-1\"]"', '1.0', 'EDUSAT (GSAT-3) Bharat ka pehla satellite tha jo puri tarah se shiksha ke kshetra ko samarpit tha. Ise 2004 me launch kiya gaya tha.', 3, 1, 5, 'Space Technology', 'Which was India''s first dedicated satellite for Education?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('al3HQdD_iLT8B-sYQPi2D', 'I5wtEA-CQuFwOW-vUnTP2', 'Bharat ka pehla ''Space Docking'' experiment, jisme do satellites ko space me joda gaya, kaun sa hai?', '"[\"Gaganyaan\",\"SpaDeX\",\"NISAR\",\"Aditya-L1\"]"', '1.0', 'SpaDeX (Space Docking Experiment) Bharat ka pehla mission hai jiska uddeshya space me do satellites ko aapas me jodna hai.', 3, 1, 6, 'Space Technology', 'What is India''s first ''Space Docking'' experiment, in which two satellites were joined in space?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('kLgksgfGgdnAQ5slNocvO', 'I5wtEA-CQuFwOW-vUnTP2', 'ISRO ka pehla dedicated weather satellite, jiska purana naam METSAT tha, kya hai?', '"[\"INSAT-3DR\",\"Cartosat\",\"Kalpana-1\",\"Resourcesat\"]"', '2.0', 'Kalpana-1 ISRO ka pehla dedicated weather (meteorology) satellite hai, jiska purana naam METSAT tha.', 3, 1, 7, 'Space Technology', 'What is ISRO''s first dedicated weather satellite, formerly known as METSAT?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dsiSdsIgiictOoCLgD9FU', 'I5wtEA-CQuFwOW-vUnTP2', 'Bharat ka pehla ''Human Spaceflight'' program, jiska uddeshya antariksh me insan bhejna hai, kya kehlata hai?', '"[\"Mangalyaan\",\"Chandrayaan-3\",\"Gaganyaan\",\"Axiom Mission 4\"]"', '2.0', 'Gaganyaan Bharat ka pehla Human Spaceflight program hai, jiske tahat Bhartiya antariksh yatriyon ko space me bheja jayega.', 3, 1, 8, 'Space Technology', 'What is India''s first ''Human Spaceflight'' program, aimed at sending humans to space, called?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('QlL8IZKqbnb71zGBU2_qT', 'I5wtEA-CQuFwOW-vUnTP2', 'ISRO aur NASA ka joint Earth observation mission kaun sa hai?', '"[\"NISAR\",\"Aditya-L1\",\"EOS-04\",\"GSAT-20\"]"', '0.0', 'NISAR (NASA-ISRO Synthetic Aperture Radar) ek joint mission hai jiska mukhya uddeshya Earth observation hai.', 3, 1, 9, 'Space Technology', 'Which is the joint Earth observation mission of ISRO and NASA?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('oFElACQ1agPQrqUxECQYf', 'I5wtEA-CQuFwOW-vUnTP2', 'Bharat ka apna space station, ''Bhartiya Antariksh Station'', banane ka lakshya kis varsh tak rakha gaya hai?', '"[\"2025\",\"2030\",\"2035\",\"2040\"]"', '2.0', 'Bharat ne 2035 tak apna khud ka space station, ''Bhartiya Antariksh Station'', sthapit karne ka lakshya nirdharit kiya hai.', 3, 1, 10, 'Space Technology', 'By which year has the target been set to build India''s own space station, ''Bhartiya Antariksh Station''?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('HzS36m6GWkCAaAgfh5XHq', 'l2cBBsoN7kOYyzmuQpR4p', 'भारतीय अंतरिक्ष कार्यक्रम के जनक (Father of Indian Space Program) के रूप में किसे जाना जाता है?', '"[\"डॉ. ए.पी.जे. अब्दुल कलाम (Dr. A.P.J. Abdul Kalam)\",\"डॉ. विक्रम साराभाई (Dr. Vikram Sarabhai)\",\"डॉ. होमी जे. भाभा (Dr. Homi J. Bhabha)\",\"प्रो. सतीश धवन (Prof. Satish Dhawan)\"]"', '1.0', '✅ **Correct Logic:** डॉ. विक्रम साराभाई (Dr. Vikram Sarabhai) को भारतीय अंतरिक्ष कार्यक्रम का जनक माना जाता है। उनके अथक प्रयासों से ही भारत ने अंतरिक्ष अनुसंधान की दिशा में कदम बढ़ाया।

💡 **Exam Fact (High Value):** इसरो (ISRO) की स्थापना 15 अगस्त 1969 को हुई थी।

🧠 **Memory Tip (Mnemonic):** ''Vikram'' leads the ''Viman'' (Spacecraft) -> Vikram Sarabhai.

🚫 **Scam Alert (Elimination):** डॉ. कलाम को ''मिसाइल मैन'' (Missile Man) कहा जाता है और डॉ. भाभा को ''परमाणु कार्यक्रम के जनक'' (Father of Nuclear Program) कहा जाता है।', 3, 1, 1, 'Space Technology', 'Who is known as the ''Father of Indian Space Program''?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('yTwnV9ag2Y37TNWtdzv5r', 'l2cBBsoN7kOYyzmuQpR4p', 'भारत का पहला स्वदेशी उपग्रह (First Indian Satellite) कौन सा था, जिसे 19 अप्रैल 1975 को लॉन्च किया गया था?', '"[\"रोहिणी (Rohini)\",\"भास्कर (Bhaskara)\",\"आर्यभट्ट (Aryabhata)\",\"एप्पल (APPLE)\"]"', '2.0', '✅ **Correct Logic:** भारत का पहला उपग्रह ''आर्यभट्ट'' (Aryabhata) था। इसे सोवियत संघ (रूस) की मदद से 19 अप्रैल 1975 को लॉन्च किया गया था।

💡 **Exam Fact (High Value):** यह उपग्रह पूरी तरह से भारत में बनाया गया था, लेकिन लॉन्चिंग के लिए रूसी रॉकेट (कोसमोस-3M) का उपयोग किया गया था।

🧠 **Memory Tip (Mnemonic):** ''A'' is the first letter, ''Aryabhata'' is the first satellite.

🚫 **Scam Alert (Elimination):** ''रोहिणी'' (Rohini - RS-1) भारत का पहला उपग्रह था जिसे भारतीय लॉन्च व्हीकल (SLV-3) द्वारा लॉन्च किया गया था (1980 में)।', 3, 1, 2, 'Space Technology', 'Which was India''s first indigenous satellite, launched on 19 April 1975?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xwqTYzF6CT6ogPOud0Vqb', 'l2cBBsoN7kOYyzmuQpR4p', 'सूची-I को सूची-II से सुमेलित कीजिए:

सूची-I (उपग्रह प्रणाली / Satellite System)
A. Kalpana-1 (कल्पना-1)
B. NavIC (नाविक)
C. EDUSAT (एडुसैट)
D. INSAT Series (इनसैट शृंखला)

सूची-II (उद्देश्य / Purpose)
1. शिक्षा (Education)
2. मौसम विज्ञान (Meteorology/Weather)
3. बहुउद्देशीय (TV, रेडियो, मौसम)
4. नेविगेशन/GPS (Navigation)

नीचे दिए गए कूट का उपयोग करके सही उत्तर चुनिए:', '"[\"A-2, B-4, C-1, D-3\",\"A-4, B-2, C-3, D-1\",\"A-1, B-3, C-2, D-4\",\"A-3, B-1, C-4, D-2\"]"', '0.0', '✅ **Correct Logic:** Kalpana-1 (METSAT) भारत का पहला समर्पित मौसम उपग्रह था। NavIC भारत का अपना GPS (नेविगेशन) है। EDUSAT शिक्षा के लिए है। INSAT संचार और मौसम के लिए बहुउद्देशीय (Multipurpose) है।

💡 **Exam Fact (High Value):** NavIC (IRNSS) में 7 उपग्रहों का एक समूह (Constellation) है जो भारत और उसके आसपास 1500 किमी तक सटीक स्थिति प्रदान करता है।

🧠 **Memory Tip (Mnemonic):** **Edu**sat = **Edu**cation. **Nav**IC = **Nav**igation.

🚫 **Scam Alert (Elimination):** GSAT पूरी तरह से संचार (Communication) के लिए है, जबकि INSAT बहुउद्देशीय है।', 3, 1, 3, 'Space Technology', 'Match List-I with List-II:

List-I (Satellite System)
A. Kalpana-1
B. NavIC
C. EDUSAT
D. INSAT Series

List-II (Purpose)
1. Education
2. Meteorology/Weather
3. Multipurpose (TV, Radio, Weather)
4. Navigation/GPS

Select the correct answer using the code given below:', NULL, 90, 'matching', '[{"id":"1","label":"Kalpana-1","labelEn":"Kalpana-1","match":"मौसम विज्ञान","matchId":"2","matchEn":"Meteorology/Weather"},{"id":"2","label":"NavIC","labelEn":"NavIC","match":"नेविगेशन/GPS","matchId":"4","matchEn":"Navigation/GPS"},{"id":"3","label":"EDUSAT","labelEn":"EDUSAT","match":"शिक्षा","matchId":"1","matchEn":"Education"},{"id":"4","label":"INSAT Series","labelEn":"INSAT Series","match":"बहुउद्देशीय","matchId":"3","matchEn":"Multipurpose"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('tVKMN7WFE4hZDCKtMhebA', 'l2cBBsoN7kOYyzmuQpR4p', 'भारत का पहला समर्पित सौर मिशन (Dedicated Solar Mission) कौन सा है, जिसने जनवरी 2024 में लैग्रेंज पॉइंट 1 (L1) पर सफलतापूर्वक प्रवेश किया?', '"[\"आदित्य-L1 (Aditya-L1)\",\"सूर्य-L1 (Surya-L1)\",\"भास्कर-L1 (Bhaskara-L1)\",\"रवि-L1 (Ravi-L1)\"]"', '0.0', '✅ **Correct Logic:** आदित्य-L1 (Aditya-L1) इसरो का पहला सूर्य मिशन है। यह लैग्रेंज पॉइंट 1 (L1) पर स्थित है, जो पृथ्वी से लगभग 1.5 मिलियन किलोमीटर दूर है।

💡 **Exam Fact (High Value):** L1 पॉइंट पर उपग्रह रखने का सबसे बड़ा फायदा यह है कि यहाँ से सूर्य को बिना किसी ग्रहण (Eclipse) के 24/7 देखा जा सकता है।

🧠 **Memory Tip (Mnemonic):** ''Aditya'' is a synonym for the Sun. L1 refers to its destination orbit.

🚫 **Scam Alert (Elimination):** भास्कर (Bhaskara) उपग्रह पृथ्वी अवलोकन (Earth Observation) के लिए थे, सूर्य के लिए नहीं।', 3, 1, 4, 'Space Technology', 'Which is India''s first dedicated solar mission, that successfully entered Lagrange Point 1 (L1) in January 2024?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('nQturbmLRoFwVyh6zxq4r', 'l2cBBsoN7kOYyzmuQpR4p', 'इसरो और नासा (ISRO and NASA) का एक संयुक्त मिशन ''NISAR'', जिसे 2025 में लॉन्च किया जाना है, मुख्य रूप से किस उद्देश्य के लिए बनाया गया है?', '"[\"मंगल ग्रह का अन्वेषण (Mars Exploration)\",\"क्षुद्रग्रह खनन (Asteroid Mining)\",\"पृथ्वी अवलोकन (Earth Observation)\",\"मानव अंतरिक्ष उड़ान (Human Spaceflight)\"]"', '2.0', '✅ **Correct Logic:** NISAR (NASA-ISRO Synthetic Aperture Radar) एक पृथ्वी अवलोकन (Earth Observation) उपग्रह है। यह पृथ्वी की सतह में होने वाले सूक्ष्म परिवर्तनों (जैसे भूकंप, ग्लेशियर पिघलना, कृषि) को मापने के लिए दोहरे-आवृत्ति वाले रडार (Dual-frequency Radar) का उपयोग करेगा।

💡 **Exam Fact (High Value):** यह अब तक का सबसे महंगा पृथ्वी अवलोकन उपग्रह मिशन माना जाता है।

🧠 **Memory Tip (Mnemonic):** **N**ASA-**I**SRO **S**ynthetic **A**perture **R**adar (NISAR) looks down at Earth with its radar eyes.

🚫 **Scam Alert (Elimination):** गगनयान (Gaganyaan) मानव अंतरिक्ष उड़ान मिशन है। मंगलयान (MOM) मंगल ग्रह के लिए था।', 3, 1, 5, 'Space Technology', 'The joint mission ''NISAR'' by ISRO and NASA, scheduled for launch in 2025, is primarily designed for what purpose?', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('oRTUZqS2yHmYlLBXWlaWT', 'l2cBBsoN7kOYyzmuQpR4p', 'हाल ही में ''Axiom Mission 4'' (2025) के तहत, कौन से भारतीय अंतरिक्ष यात्री (Indian Astronaut) अंतर्राष्ट्रीय अंतरिक्ष स्टेशन (ISS) की यात्रा करने वाले हैं?', '"[\"राकेश शर्मा (Rakesh Sharma)\",\"शुभांशु शुक्ला (Shubhanshu Shukla)\",\"रवीश मल्होत्रा (Ravish Malhotra)\",\"कल्पना चावला (Kalpana Chawla)\"]"', '1.0', '✅ **Correct Logic:** ''Axiom Mission 4'' (Ax-4) एक व्यावसायिक (Commercial) अंतरिक्ष उड़ान है, जिसके तहत इसरो के गगनयात्री (Gaganyatri) ''शुभांशु शुक्ला'' (Shubhanshu Shukla) अंतर्राष्ट्रीय अंतरिक्ष स्टेशन (ISS) की यात्रा करेंगे।

💡 **Exam Fact (High Value):** 1984 में सोवियत मिशन पर गए राकेश शर्मा के बाद, अंतरिक्ष में जाने वाले वे पहले भारतीय नागरिक (Indian citizen) होंगे।

🧠 **Memory Tip (Mnemonic):** **Shubh**anshu will bring **Shubh** (Auspicious) news from the ISS.

🚫 **Scam Alert (Elimination):** राकेश शर्मा 1984 में अंतरिक्ष में जाने वाले पहले भारतीय थे। कल्पना चावला अमेरिकी नागरिक थीं।', 3, 1, 6, 'Current Affairs (Space)', 'Recently under ''Axiom Mission 4'' (2025), which Indian Astronaut is scheduled to travel to the International Space Station (ISS)?', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('shTg0pOIRaAnJr3qgA5LQ', 'l2cBBsoN7kOYyzmuQpR4p', 'चंद्रयान-3 मिशन के संदर्भ में, भारत चंद्रमा के ''दक्षिणी ध्रुव'' (South Pole) पर सॉफ्ट लैंडिंग (Soft Landing) करने वाला दुनिया का कौन सा देश बन गया है?', '"[\"पहला (First)\",\"दूसरा (Second)\",\"तीसरा (Third)\",\"चौथा (Fourth)\"]"', '0.0', '✅ **Correct Logic:** 23 अगस्त 2023 को चंद्रयान-3 की सफल लैंडिंग के साथ, भारत चंद्रमा के ''दक्षिणी ध्रुव'' (South Pole) पर सॉफ्ट लैंडिंग करने वाला दुनिया का **पहला** देश बन गया।

💡 **Exam Fact (High Value):** चंद्रमा पर (कहीं भी) सॉफ्ट लैंडिंग करने वाला भारत दुनिया का चौथा देश (अमेरिका, रूस और चीन के बाद) है, लेकिन ''दक्षिणी ध्रुव'' पर पहला है।

🧠 **Memory Tip (Mnemonic):** Number 1 on the South Pole!

🚫 **Scam Alert (Elimination):** प्रश्न को ध्यान से पढ़ें! अगर ''दक्षिणी ध्रुव'' लिखा है तो उत्तर ''पहला'' होगा। अगर सिर्फ ''चंद्रमा पर'' लिखा है, तो उत्तर ''चौथा'' होगा।', 3, 1, 7, 'Space Technology', 'In the context of the Chandrayaan-3 mission, India became which country in the world to make a successful soft landing on the ''South Pole'' of the Moon?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dhdfwTvJd4oKvgRQj91Oa', 'l2cBBsoN7kOYyzmuQpR4p', 'भारत का पहला ''मानव अंतरिक्ष उड़ान कार्यक्रम'' (Human Spaceflight Program) कौन सा है, जिसका उद्देश्य अंतरिक्ष यात्रियों (गगनयात्रियों) को पृथ्वी की निचली कक्षा (LEO) में भेजना है?', '"[\"मंगलयान (Mangalyaan)\",\"चंद्रयान (Chandrayaan)\",\"गगनयान (Gaganyaan)\",\"समुद्रयान (Samudrayaan)\"]"', '2.0', '✅ **Correct Logic:** गगनयान (Gaganyaan) भारत का महत्वाकांक्षी ''मानव अंतरिक्ष उड़ान'' (Human Spaceflight) मिशन है। इसका लक्ष्य 3 अंतरिक्ष यात्रियों को 400 किमी की कक्षा (Low Earth Orbit) में भेजना और उन्हें सुरक्षित वापस लाना है।

💡 **Exam Fact (High Value):** इस मिशन की तैयारी के लिए ''व्योममित्र'' (Vyommitra) नामक रोबोट को पहले भेजा जाएगा।

🧠 **Memory Tip (Mnemonic):** **Gagan** means Sky/Space. **Yaan** means Vehicle. A vehicle for humans in the sky.

🚫 **Scam Alert (Elimination):** समुद्रयान (Samudrayaan) गहरे समुद्र (Deep Sea) के अन्वेषण के लिए है, अंतरिक्ष के लिए नहीं।', 3, 1, 8, 'Space Technology', 'Which is India''s first ''Human Spaceflight Program'', aimed at sending astronauts (Gaganyatris) to Low Earth Orbit (LEO)?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7WkXhksfa8XTUZjwnpgAH', 'l2cBBsoN7kOYyzmuQpR4p', 'इसरो का आगामी ''SpaDeX'' (2025) मिशन मुख्य रूप से किस महत्वपूर्ण अंतरिक्ष तकनीक (Space Technology) का प्रदर्शन (Demonstrate) करेगा?', '"[\"अंतरिक्ष डॉकिंग (Space Docking)\",\"पुनः प्रयोज्य लॉन्च वाहन (Reusable Launch Vehicle)\",\"क्षुद्रग्रह विक्षेपण (Asteroid Deflection)\",\"सौर पाल प्रणोदन (Solar Sail Propulsion)\"]"', '0.0', '✅ **Correct Logic:** SpaDeX (Space Docking Experiment) भारत का पहला मिशन है जहाँ अंतरिक्ष में दो उपग्रहों (Satellites) को एक साथ जोड़ा (Docked) जाएगा।

💡 **Exam Fact (High Value):** यह तकनीक भारत के भविष्य के ''भारतीय अंतरिक्ष स्टेशन'' (Bharatiya Antariksh Station) के निर्माण के लिए अत्यंत महत्वपूर्ण है, क्योंकि स्पेस स्टेशन के अलग-अलग हिस्सों को अंतरिक्ष में ले जाकर इसी तरह जोड़ा जाएगा।

🧠 **Memory Tip (Mnemonic):** Spa**DeX** -> Space **D**ocking **Ex**periment.

🚫 **Scam Alert (Elimination):** RLV-TD (Reusable Launch Vehicle Technology Demonstrator) पुनः प्रयोज्य रॉकेट तकनीक के लिए है, डॉकिंग के लिए SpaDeX है।', 3, 1, 9, 'Space Technology', 'ISRO''s upcoming ''SpaDeX'' (2025) mission will primarily demonstrate which critical space technology?', NULL, 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6p5pw1zD9Dlfrri70zzih', 'l2cBBsoN7kOYyzmuQpR4p', 'इसरो (ISRO) ने अपना खुद का ''भारतीय अंतरिक्ष स्टेशन'' (Bharatiya Antariksh Station) स्थापित करने का लक्ष्य किस वर्ष तक रखा है?', '"[\"2028\",\"2030\",\"2035\",\"2040\"]"', '2.0', '✅ **Correct Logic:** भारत सरकार और इसरो ने घोषणा की है कि भारत **2035** तक अपना खुद का ''भारतीय अंतरिक्ष स्टेशन'' (BAS) स्थापित कर लेगा।

💡 **Exam Fact (High Value):** इसके साथ ही, भारत ने 2040 तक चंद्रमा पर पहला भारतीय (Indian on Moon) भेजने का भी महत्वाकांक्षी लक्ष्य निर्धारित किया है।

🧠 **Memory Tip (Mnemonic):** First Station in Space by **2035**, then step on the Moon by **2040**.

🚫 **Scam Alert (Elimination):** 2030 तक गगनयान के कई चरण पूरे होंगे, लेकिन पूर्ण अंतरिक्ष स्टेशन 2035 का लक्ष्य है। तिथियों/वर्षों (Target Years) पर MPPSC हमेशा सवाल पूछता है।', 3, 1, 10, 'Space Technology', 'By which year has ISRO targeted to establish its own ''Bharatiya Antariksh Station'' (Indian Space Station)?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ymTqQ3jYdSaZb0RiZVKx4', 'u0af5wQQviAscTEXUXJOf', 'भारत का नवीनतम (44वां) यूनेस्को विश्व धरोहर स्थल (UNESCO World Heritage Site), जिसे 2025 में मान्यता मिली है, कौन सा है?', '"[\"ग्वालियर का किला (Gwalior Fort)\",\"अहोम राजवंश के मोइदाम (Moidams of Ahom Dynasty)\",\"मराठा सैन्य परिदृश्य (Maratha Military Landscapes)\",\"भेड़ाघाट-लम्हेटाघाट (Bhedaghat-Lametaghat)\"]"', '2.0', '✅ **Correct Logic:** 2025 में, ''मराठा सैन्य परिदृश्य'' (Maratha Military Landscapes) को भारत के 44वें यूनेस्को विश्व धरोहर स्थल के रूप में अंकित किया गया है। यह महाराष्ट्र और तमिलनाडु में फैले 12 किलों का एक नेटवर्क है।

💡 **Exam Fact (High Value):** अहोम राजवंश के मोइदाम (असम) को इससे ठीक पहले 2024 में 43वें स्थल के रूप में मान्यता मिली थी।

🧠 **Memory Tip (Mnemonic):** **44** sounds like **Four-Fort**. Maratha landscapes are all about historic forts!

🚫 **Scam Alert (Elimination):** भेड़ाघाट अभी भी ''संभावित'' (Tentative) सूची में है, स्थायी स्थल नहीं बना है। अहोम 43वां था।', 3, 1, 1, 'Art & Culture / Current Affairs', 'Which is India''s latest (44th) UNESCO World Heritage Site, recognized in 2025?', '✅ **Correct Logic:** In 2025, the ''Maratha Military Landscapes'' was inscribed as India''s 44th UNESCO World Heritage Site. It is a network of 12 forts spread across Maharashtra and Tamil Nadu.

💡 **Exam Fact (High Value):** The Moidams of the Ahom Dynasty (Assam) received recognition just before this as the 43rd site in 2024.

🧠 **Memory Tip (Mnemonic):** **44** sounds like **Four-Fort**. Maratha landscapes are all about historic forts!

🚫 **Scam Alert (Elimination):** Bhedaghat is still on the ''Tentative'' list and has not become a permanent site yet. Ahom was 43rd.', 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('02Ksh1NZiQndta3wCwxRG', 'u0af5wQQviAscTEXUXJOf', 'मध्य प्रदेश में वर्तमान में कुल कितने ''स्थायी'' (Permanent) यूनेस्को विश्व धरोहर स्थल हैं?', '"[\"2\",\"3\",\"4\",\"5\"]"', '1.0', '✅ **Correct Logic:** मध्य प्रदेश में केवल 3 स्थायी यूनेस्को स्थल हैं: खजुराहो (1986), सांची (1989), और भीमबेटका (2003)। ये तीनों ''सांस्कृतिक'' (Cultural) श्रेणी में आते हैं।

💡 **Exam Fact (High Value):** भारत में कुल 44 स्थल हैं, जिनमें से 36 सांस्कृतिक, 7 प्राकृतिक और 1 मिश्रित है।

🧠 **Memory Tip (Mnemonic):** MP has **3** crowns -> **K-S-B** (Khajuraho, Sanchi, Bhimbetka).

🚫 **Scam Alert (Elimination):** ग्वालियर, ओरछा, और भेड़ाघाट ''संभावित'' (Tentative) सूची में हैं। MPPSC स्थायी और संभावित के बीच कंफ्यूज करता है।', 3, 1, 2, 'MP GK', 'How many ''Permanent'' UNESCO World Heritage Sites are currently there in Madhya Pradesh?', '✅ **Correct Logic:** Madhya Pradesh has exactly 3 permanent UNESCO sites: Khajuraho (1986), Sanchi (1989), and Bhimbetka (2003). All three fall under the ''Cultural'' category.

💡 **Exam Fact (High Value):** India has a total of 44 sites, out of which 36 are Cultural, 7 are Natural, and 1 is Mixed.

🧠 **Memory Tip (Mnemonic):** MP has **3** crowns -> **K-S-B** (Khajuraho, Sanchi, Bhimbetka).

🚫 **Scam Alert (Elimination):** Gwalior, Orchha, and Bhedaghat are on the ''Tentative'' list. MPPSC frequently confuses students between permanent and tentative sites.', 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('nACQic1cVzsPa91LGGE3p', 'u0af5wQQviAscTEXUXJOf', 'भारत का एकमात्र ''मिश्रित'' (Mixed - Cultural + Natural) यूनेस्को विश्व धरोहर स्थल कौन सा है?', '"[\"पश्चिमी घाट (Western Ghats)\",\"नंदा देवी राष्ट्रीय उद्यान (Nanda Devi National Park)\",\"खांगचेंदज़ोंगा राष्ट्रीय उद्यान (Khangchendzonga National Park)\",\"सुंदरबन राष्ट्रीय उद्यान (Sundarbans National Park)\"]"', '2.0', '✅ **Correct Logic:** सिक्किम में स्थित खांगचेंदज़ोंगा (कंचनजंगा) राष्ट्रीय उद्यान भारत का एकमात्र मिश्रित धरोहर स्थल है। इसे इसके शानदार प्राकृतिक परिदृश्य (पहाड़, ग्लेशियर) और बौद्ध मान्यताओं (सांस्कृतिक महत्व) के लिए मान्यता प्राप्त है।

💡 **Exam Fact (High Value):** इसे 2016 में यूनेस्को की सूची में शामिल किया गया था। भारत की 44 साइटों में से केवल 1 इस श्रेणी में है।

🧠 **Memory Tip (Mnemonic):** **Mixed** up name -> Khangchendzonga is a long, mixed-up word for the only mixed site!

🚫 **Scam Alert (Elimination):** पश्चिमी घाट और सुंदरबन ''प्राकृतिक'' (Natural) स्थल हैं।', 3, 1, 3, 'Environment & Culture', 'Which is India''s only ''Mixed'' (Cultural + Natural) UNESCO World Heritage Site?', '✅ **Correct Logic:** Khangchendzonga National Park, located in Sikkim, is India''s only Mixed Heritage Site. It is recognized for its spectacular natural landscape (mountains, glaciers) and Buddhist beliefs (cultural significance).

💡 **Exam Fact (High Value):** It was added to the UNESCO list in 2016. Out of India''s 44 sites, only 1 is in this category.

🧠 **Memory Tip (Mnemonic):** **Mixed** up name -> Khangchendzonga is a long, mixed-up word for the only mixed site!

🚫 **Scam Alert (Elimination):** Western Ghats and Sundarbans are ''Natural'' sites, not mixed.', 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8O8fVa24rSmQTNYrQ6aP7', 'u0af5wQQviAscTEXUXJOf', 'सूची-I को सूची-II से सुमेलित कीजिए (मध्य प्रदेश के यूनेस्को स्थल):

सूची-I (स्थल)
A. खजुराहो (Khajuraho)
B. सांची (Sanchi)
C. भीमबेटका (Bhimbetka)

सूची-II (संबंधित राजवंश / काल)
1. पाषाण काल (Stone Age)
2. चंदेल राजवंश (Chandela Dynasty)
3. मौर्य साम्राज्य (Emperor Ashoka / Mauryan)

नीचे दिए गए कूट का उपयोग करके सही उत्तर चुनिए:', '"[\"A-2, B-3, C-1\",\"A-3, B-2, C-1\",\"A-1, B-3, C-2\",\"A-2, B-1, C-3\"]"', '0.0', '✅ **Correct Logic:** खजुराहो के मंदिर चंदेल राजाओं द्वारा बनाए गए थे। सांची का महान स्तूप सम्राट अशोक (मौर्य) द्वारा बनवाया गया था। भीमबेटका की गुफाएं प्रागैतिहासिक पाषाण काल (Stone Age) की रॉक पेंटिंग के लिए प्रसिद्ध हैं।

💡 **Exam Fact (High Value):** भीमबेटका की खोज 1957 में डॉ. वी.एस. वाकणकर ने की थी।

🧠 **Memory Tip (Mnemonic):** **C**handela = **K**hajuraho (CK). **A**shoka = **S**anchi (AS).

🚫 **Scam Alert (Elimination):** सांची में बौद्ध धर्म के स्तूप हैं, लेकिन इनका निर्माण गुप्त या शुंग काल में नहीं, बल्कि मुख्य रूप से मौर्य काल में शुरू हुआ था।', 3, 1, 4, 'MP GK', 'Match List-I with List-II (UNESCO Sites of MP):

List-I (Site)
A. Khajuraho
B. Sanchi
C. Bhimbetka

List-II (Associated Dynasty / Era)
1. Stone Age
2. Chandela Dynasty
3. Mauryan Empire (Emperor Ashoka)

Select the correct answer using the code given below:', '✅ **Correct Logic:** The Khajuraho temples were built by the Chandela kings. The Great Stupa at Sanchi was built by Emperor Ashoka (Mauryan). The Bhimbetka caves are famous for their prehistoric Stone Age rock paintings.

💡 **Exam Fact (High Value):** Bhimbetka was discovered in 1957 by Dr. V.S. Wakankar.

🧠 **Memory Tip (Mnemonic):** **C**handela = **K**hajuraho (CK). **A**shoka = **S**anchi (AS).

🚫 **Scam Alert (Elimination):** Sanchi has Buddhist stupas, but their construction was primarily started during the Mauryan period, not the Gupta or Shunga periods.', 90, 'matching', '[{"id":"1","label":"खजुराहो","labelEn":"Khajuraho","match":"चंदेल राजवंश","matchId":"2","matchEn":"Chandela Dynasty"},{"id":"2","label":"सांची","labelEn":"Sanchi","match":"मौर्य साम्राज्य","matchId":"3","matchEn":"Mauryan Empire"},{"id":"3","label":"भीमबेटका","labelEn":"Bhimbetka","match":"पाषाण काल","matchId":"1","matchEn":"Stone Age"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8iK5bCsBsBD-olTWXxXaq', 'u0af5wQQviAscTEXUXJOf', 'मध्य प्रदेश का पहला यूनेस्को विश्व धरोहर स्थल कौन सा था, जिसे 1986 में यह दर्जा मिला?', '"[\"सांची के बौद्ध स्मारक (Buddhist Monuments at Sanchi)\",\"खजुराहो के मंदिर (Khajuraho Group of Monuments)\",\"भीमबेटका शैलाश्रय (Rock Shelters of Bhimbetka)\",\"मांडू के महल (Palaces of Mandu)\"]"', '1.0', '✅ **Correct Logic:** छतरपुर जिले में स्थित खजुराहो स्मारकों के समूह को 1986 में यूनेस्को साइट घोषित किया गया था। यह मध्य प्रदेश का पहला स्थल था।

💡 **Exam Fact (High Value):** खजुराहो अपने हिंदू और जैन मंदिरों और उनकी उत्कृष्ट मूर्तिकला के लिए विश्व प्रसिद्ध है।

🧠 **Memory Tip (Mnemonic):** **K**hajuraho came **1st** in MP (1986). **S**anchi came **2nd** (1989). **B**himbetka came **3rd** (2003).

🚫 **Scam Alert (Elimination):** सांची 1989 में और भीमबेटका 2003 में शामिल हुए। वर्ष (Year) के आधार पर कालक्रम याद रखें!', 3, 1, 5, 'MP GK', 'Which was the first UNESCO World Heritage Site of Madhya Pradesh, which received this status in 1986?', '✅ **Correct Logic:** The Khajuraho Group of Monuments, located in Chhatarpur district, was declared a UNESCO site in 1986. It was the very first site from Madhya Pradesh.

💡 **Exam Fact (High Value):** Khajuraho is world-renowned for its magnificent Hindu and Jain temples and their exquisite sculptures.

🧠 **Memory Tip (Mnemonic):** **K**hajuraho came **1st** in MP (1986). **S**anchi came **2nd** (1989). **B**himbetka came **3rd** (2003).

🚫 **Scam Alert (Elimination):** Sanchi was included in 1989 and Bhimbetka in 2003. Remember the chronology based on the year!', 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('reFwsZuMun01ko0XOm9HQ', 'u0af5wQQviAscTEXUXJOf', 'भारत में वर्तमान में यूनेस्को विश्व धरोहर स्थलों की कुल संख्या 44 है। इनमें से ''प्राकृतिक'' (Natural) स्थलों की संख्या कितनी है?', '"[\"5\",\"7\",\"9\",\"36\"]"', '1.0', '✅ **Correct Logic:** भारत के 44 स्थलों का विभाजन इस प्रकार है: 36 सांस्कृतिक (Cultural), 7 प्राकृतिक (Natural), और 1 मिश्रित (Mixed)। अतः प्राकृतिक स्थलों की संख्या 7 है।

💡 **Exam Fact (High Value):** प्राकृतिक स्थलों में काजीरंगा, केवलादेव, मानस, नंदा देवी, सुंदरबन, पश्चिमी घाट और ग्रेट हिमालयन नेशनल पार्क शामिल हैं।

🧠 **Memory Tip (Mnemonic):** **36 + 7 + 1 = 44**. Nature gives us **7** days a week to enjoy it.

🚫 **Scam Alert (Elimination):** 36 ''सांस्कृतिक'' स्थल हैं, प्रश्न ''प्राकृतिक'' स्थलों की संख्या पूछ रहा है।', 3, 1, 6, 'Art & Culture', 'Currently, the total number of UNESCO World Heritage Sites in India is 44. Out of these, what is the number of ''Natural'' sites?', '✅ **Correct Logic:** The breakdown of India''s 44 sites is as follows: 36 Cultural, 7 Natural, and 1 Mixed. Hence, the number of Natural sites is 7.

💡 **Exam Fact (High Value):** The Natural sites include Kaziranga, Keoladeo, Manas, Nanda Devi, Sundarbans, Western Ghats, and Great Himalayan National Park.

🧠 **Memory Tip (Mnemonic):** **36 + 7 + 1 = 44**. Nature gives us **7** days a week to enjoy it.

🚫 **Scam Alert (Elimination):** 36 is the number of ''Cultural'' sites. The question specifically asks for the number of ''Natural'' sites.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('N7HCa-3ydhM9g181VOjLH', 'u0af5wQQviAscTEXUXJOf', 'भीमबेटका (Bhimbetka) की रॉक शेल्टर को किस वर्ष यूनेस्को विश्व धरोहर स्थल का दर्जा दिया गया था?', '"[\"1986\",\"1989\",\"2003\",\"2014\"]"', '2.0', '✅ **Correct Logic:** रायसेन जिले में स्थित भीमबेटका की गुफाओं को 2003 में यूनेस्को विश्व धरोहर स्थल घोषित किया गया था।

💡 **Exam Fact (High Value):** यह स्थल मानव विकास के शुरुआती निशानों (प्रागैतिहासिक काल) को दर्शाता है।

🧠 **Memory Tip (Mnemonic):** Khajuraho (1986) -> Sanchi (1989) -> Bhimbetka (2003). Bhimbetka is the 3rd one, in 200**3**.

🚫 **Scam Alert (Elimination):** 1986 खजुराहो का वर्ष है। 1989 सांची का वर्ष है। इन तीन वर्षों को हमेशा क्रम में याद रखें।', 3, 1, 7, 'MP GK', 'In which year were the rock shelters of Bhimbetka granted the status of a UNESCO World Heritage Site?', '✅ **Correct Logic:** The Bhimbetka rock shelters, located in the Raisen district, were declared a UNESCO World Heritage Site in 2003.

💡 **Exam Fact (High Value):** This site exhibits some of the earliest traces of human life on the Indian subcontinent (Prehistoric era).

🧠 **Memory Tip (Mnemonic):** Khajuraho (1986) -> Sanchi (1989) -> Bhimbetka (2003). Bhimbetka is the 3rd one, recognized in 200**3**.

🚫 **Scam Alert (Elimination):** 1986 is the year for Khajuraho. 1989 is the year for Sanchi. Always remember these three years chronologically.', 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('487nj_AF_T9SngGIJxDn4', 'u0af5wQQviAscTEXUXJOf', 'मध्य प्रदेश के संदर्भ में, निम्नलिखित में से कौन सा स्थल यूनेस्को की ''संभावित सूची'' (Tentative List) में शामिल है, लेकिन अभी तक स्थायी स्थल नहीं बना है?', '"[\"भीमबेटका (Bhimbetka)\",\"भेड़ाघाट-लम्हेटाघाट (Bhedaghat-Lametaghat)\",\"सांची (Sanchi)\",\"खजुराहो (Khajuraho)\"]"', '1.0', '✅ **Correct Logic:** जबलपुर का भेड़ाघाट-लम्हेटाघाट (मार्बल रॉक्स और डायनासोर जीवाश्मों के लिए प्रसिद्ध) यूनेस्को की संभावित (Tentative) सूची में है। ग्वालियर और ओरछा के ऐतिहासिक शहर भी इस सूची में हैं।

💡 **Exam Fact (High Value):** जब तक यूनेस्को की विश्व धरोहर समिति अंतिम मुहर नहीं लगाती, तब तक कोई भी स्थल स्थायी नहीं माना जाता।

🧠 **Memory Tip (Mnemonic):** Bhedaghat is still ''waiting'' in the marble rocks to be permanent.

🚫 **Scam Alert (Elimination):** खजुराहो, सांची और भीमबेटका पहले से ही स्थायी (Permanent) स्थल हैं।', 3, 1, 8, 'MP GK', 'In the context of Madhya Pradesh, which of the following sites is included in UNESCO''s ''Tentative List'' but has not yet become a permanent site?', '✅ **Correct Logic:** Bhedaghat-Lametaghat in Jabalpur (famous for marble rocks and dinosaur fossils) is currently on UNESCO''s Tentative list. The historic cities of Gwalior and Orchha are also on this list.

💡 **Exam Fact (High Value):** A site is not considered permanent until the UNESCO World Heritage Committee officially ratifies it.

🧠 **Memory Tip (Mnemonic):** Bhedaghat is still ''waiting'' in the marble rocks to become a permanent site.

🚫 **Scam Alert (Elimination):** Khajuraho, Sanchi, and Bhimbetka are already permanent sites.', 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6ehX2_LVVM1z4O3rhRKWd', 'u0af5wQQviAscTEXUXJOf', 'यूनेस्को (UNESCO) का पूर्ण रूप क्या है, जो इन विश्व धरोहर स्थलों को मान्यता प्रदान करता है?', '"[\"United Nations Environmental, Scientific and Cultural Organization\",\"United Nations Educational, Scientific and Cultural Organization\",\"Universal Network for Educational and Scientific Cooperation\",\"United Nations Economic, Social and Cultural Organization\"]"', '1.0', '✅ **Correct Logic:** यूनेस्को (UNESCO) का पूर्ण रूप ''United Nations Educational, Scientific and Cultural Organization'' (संयुक्त राष्ट्र शैक्षिक, वैज्ञानिक और सांस्कृतिक संगठन) है।

💡 **Exam Fact (High Value):** यूनेस्को का मुख्यालय पेरिस (फ्रांस) में स्थित है। यह शिक्षा, विज्ञान और संस्कृति के माध्यम से अंतर्राष्ट्रीय शांति को बढ़ावा देता है।

🧠 **Memory Tip (Mnemonic):** **E** stands for **E**ducational, not Environmental or Economic. Education comes first!

🚫 **Scam Alert (Elimination):** छात्र अक्सर ''E'' का मतलब ''Environmental'' समझ लेते हैं, लेकिन पर्यावरण के लिए UNEP (UN Environment Programme) अलग संस्था है।', 3, 1, 9, 'General Knowledge', 'What is the full form of UNESCO, which grants recognition to these World Heritage Sites?', '✅ **Correct Logic:** The full form of UNESCO is ''United Nations Educational, Scientific and Cultural Organization''.

💡 **Exam Fact (High Value):** The headquarters of UNESCO is located in Paris, France. It promotes international peace through education, science, and culture.

🧠 **Memory Tip (Mnemonic):** The **E** stands for **E**ducational, not Environmental or Economic. Education comes first!

🚫 **Scam Alert (Elimination):** Students often confuse the ''E'' for ''Environmental'', but for environmental matters, the UN has a separate body called UNEP (UN Environment Programme).', 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cGohEalDrsLMNcFT-VOrQ', 'u0af5wQQviAscTEXUXJOf', '2025 में शामिल ''मराठा सैन्य परिदृश्य'' (Maratha Military Landscapes) के संबंध में निम्नलिखित कथनों पर विचार करें:
1. यह भारत का 44वां यूनेस्को स्थल है।
2. यह ''सांस्कृतिक'' (Cultural) श्रेणी के अंतर्गत आता है।
उपरोक्त में से कौन सा/से कथन सत्य है/हैं?', '"[\"केवल 1 (Only 1)\",\"केवल 2 (Only 2)\",\"1 और 2 दोनों (Both 1 and 2)\",\"न तो 1 न ही 2 (Neither 1 nor 2)\"]"', '2.0', '✅ **Correct Logic:** दोनों कथन बिल्कुल सत्य हैं। ''मराठा सैन्य परिदृश्य'' भारत का 44वां यूनेस्को स्थल है और किले मनुष्यों द्वारा बनाए गए हैं, इसलिए यह एक ''सांस्कृतिक'' (Cultural) धरोहर है, प्राकृतिक नहीं।

💡 **Exam Fact (High Value):** इस परिदृश्य में कुल 12 किले शामिल हैं, जिनमें से 11 महाराष्ट्र में और 1 (जिंजी किला) तमिलनाडु में है। यह मराठों की असाधारण सैन्य वास्तुकला को दर्शाता है।

🧠 **Memory Tip (Mnemonic):** Forts are built by humans (Culture), and it''s the 44th one on the list.

🚫 **Scam Alert (Elimination):** अगर कोई कथन कहे कि ये किले "प्राकृतिक" श्रेणी में हैं, तो उसे तुरंत गलत कर दें, क्योंकि इंसान द्वारा बनाई गई कोई भी ऐतिहासिक संरचना ''सांस्कृतिक'' होती है।', 3, 1, 10, 'Art & Culture', 'Consider the following statements regarding the ''Maratha Military Landscapes'' included in 2025:
1. It is India''s 44th UNESCO site.
2. It falls under the ''Cultural'' category.
Which of the statements given above is/are correct?', '✅ **Correct Logic:** Both statements are absolutely correct. The ''Maratha Military Landscapes'' is India''s 44th UNESCO site, and since forts are built by humans, it is classified as a ''Cultural'' heritage, not natural.

💡 **Exam Fact (High Value):** This landscape comprises a total of 12 forts, 11 of which are in Maharashtra and 1 (Gingee Fort) is in Tamil Nadu. It showcases the extraordinary military architecture of the Marathas.

🧠 **Memory Tip (Mnemonic):** Forts are built by humans (Culture), and it''s the latest 44th site on the list.

🚫 **Scam Alert (Elimination):** If a statement claims these forts are in the ''Natural'' category, eliminate it immediately, because any historic structure built by humans falls under the ''Cultural'' category.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('_Vv3M1af-tR-4mretVFj8', 'owzOzb5J-OfGDUbFNs0n-', 'कांची का कैलासनाथर मंदिर किस शैली में बना है?', '"[\"राजसिम्हा शैली (Rajsimha style)\",\"मामल्ल शैली (Mamalla style)\",\"महेन्द्र शैली (Mahendra style)\",\"नंदीवर्मन शैली (Nandivarman style)\"]"', '0.0', '**✅ Correct Logic**: कांची का कैलासनाथर मंदिर पल्लव राजा नरसिंहवर्मन द्वितीय (जिन्हें राजसिम्हा भी कहा जाता है) द्वारा बनवाया गया था, इसलिए यह राजसिम्हा शैली का उत्कृष्ट उदाहरण है।

**💡 Exam Fact**: यह कांचीपुरम का सबसे पुराना संरचनात्मक मंदिर है और प्रारंभिक द्रविड़ वास्तुकला को दर्शाता है।

**🧠 Memory Tip**: ''कैलाश पर राजा (राजसिम्हा) का राज है'' - कैलासनाथर = राजसिम्हा।

**🚫 Scam Alert**: मामल्ल शैली से भ्रमित न हों, जो मुख्य रूप से महाबलीपुरम के मोनोलिथिक रथ मंदिरों (पल्लव काल) के लिए प्रसिद्ध है।', 2, 0, 1, 'History', 'In which style is the Kailasanathar temple of Kanchi built?', '**✅ Correct Logic**: The Kailasanathar temple was built by the Pallava King Narasimhavarman II (also known as Rajasimha), hence it belongs to the Rajasimha style.

**💡 Exam Fact**: It is the oldest structural temple in Kanchipuram and represents early Dravidian architecture.

**🧠 Memory Tip**: ''Kailash is ruled by a King (Raja)'' -> Kailasanathar = Rajasimha.

**🚫 Scam Alert**: Do not confuse with the Mamalla style, which is famous for the monolithic rathas at Mahabalipuram.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('FKILW9Bqoz_WV8uQIYrwf', 'owzOzb5J-OfGDUbFNs0n-', '''एडोब फोटोशॉप'' किस प्रकार के सामान्य प्रयोजन एप्लिकेशन सॉफ्टवेयर का एक उदाहरण है?', '"[\"ग्राफिक्स सॉफ्टवेयर (Graphics Software)\",\"मल्टीमीडिया सॉफ्टवेयर (Multimedia software)\",\"वेब सीरीज़ सॉफ्टवेयर (Web Series software)\",\"डेटाबेस सॉफ्टवेयर (Database software)\"]"', '0.0', '**✅ Correct Logic**: एडोब फोटोशॉप मुख्य रूप से इमेज एडिटिंग और निर्माण के लिए उपयोग किया जाता है, जो इसे ग्राफिक्स सॉफ्टवेयर की श्रेणी में रखता है।

**💡 Exam Fact**: फोटोशॉप एक ''रास्टर'' ग्राफिक्स एडिटर है (पिक्सेल आधारित), न कि वेक्टर एडिटर।

**🧠 Memory Tip**: फोटो = चित्र = ग्राफिक्स।

**🚫 Scam Alert**: मल्टीमीडिया सॉफ्टवेयर बहुत व्यापक है और इसमें ऑडियो/वीडियो (जैसे एडोब प्रीमियर) शामिल होता है; फोटोशॉप विशुद्ध रूप से ग्राफिक्स के लिए है।', 2, 0, 2, 'ICT', '''Adobe Photoshop'' is an example of which type of general purpose application software?', '**✅ Correct Logic**: Adobe Photoshop is primarily used for image editing and creation, classifying it as graphics software.

**💡 Exam Fact**: Photoshop is a ''raster'' graphics editor (pixel-based), not a vector editor.

**🧠 Memory Tip**: Photo = Image = Graphics.

**🚫 Scam Alert**: Multimedia software is broader and includes audio/video (like Premiere Pro); Photoshop is strictly for graphics.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d7pTLwNdARnmzEvi_6kkI', 'owzOzb5J-OfGDUbFNs0n-', 'राज्य पुनर्गठन अधिनियम, 1956 के अनुसार कितने राज्य और केन्द्र-शासित प्रदेश बनाए गए थे?', '"[\"11 राज्य और 6 केन्द्र-शासित प्रदेश (11 States and 6 Union territories)\",\"12 राज्य और 7 केन्द्र-शासित प्रदेश (12 States and 7 Union territories)\",\"13 राज्य और 7 केन्द्र-शासित प्रदेश (13 States and 7 Union territories)\",\"14 राज्य और 6 केन्द्र-शासित प्रदेश (14 States and 6 Union territories)\"]"', '3.0', '**✅ Correct Logic**: फजल अली आयोग की सिफारिशों के आधार पर राज्य पुनर्गठन अधिनियम, 1956 लागू किया गया, जिसमें भारत को 14 राज्यों और 6 केंद्र शासित प्रदेशों में विभाजित किया गया था।

**💡 Exam Fact**: भाषाई आधार पर बनने वाला पहला राज्य आंध्र प्रदेश (1953) था, जो इस अधिनियम से पहले ही बन गया था।

**🧠 Memory Tip**: 1956 में कुल 20 इकाइयाँ थीं: 14 + 6 = 20।

**🚫 Scam Alert**: आयोग ने मूल रूप से 16 राज्य और 3 केंद्र शासित प्रदेशों का सुझाव दिया था, लेकिन संसद ने 14 और 6 पारित किए।', 2, 0, 3, 'Polity', 'How many States and Union territories were created according to the States Reorganisation Act, 1956?', '**✅ Correct Logic**: Based on the Fazl Ali Commission''s recommendations, the States Reorganisation Act of 1956 divided India into 14 States and 6 Union Territories.

**💡 Exam Fact**: Andhra Pradesh was the first state created on linguistic lines in 1953, preceding this act.

**🧠 Memory Tip**: Total 20 units in 1956: 14 + 6 = 20.

**🚫 Scam Alert**: The commission originally suggested 16 states and 3 UTs, but Parliament passed 14 and 6.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('EKrmk5W2bsESdTRiA_dt3', 'owzOzb5J-OfGDUbFNs0n-', 'मुस्लिम लीग ने ''सीधी कार्यवाही'' (Direct Action) करने की घोषणा कब की?', '"[\"22 जून, 1946 (22nd June, 1946)\",\"16 अगस्त, 1946 (16th August, 1946)\",\"22 अक्टूबर, 1946 (22nd October, 1946)\",\"22 अगस्त, 1946 (22nd August, 1946)\"]"', '1.0', '**✅ Correct Logic**: कैबिनेट मिशन योजना को अस्वीकार करने के बाद, मुहम्मद अली जिन्ना ने पाकिस्तान की मांग को हासिल करने के लिए 16 अगस्त 1946 को ''डायरेक्ट एक्शन डे'' (सीधी कार्यवाही दिवस) के रूप में घोषित किया।

**💡 Exam Fact**: इस दिन कलकत्ता में बड़े पैमाने पर सांप्रदायिक दंगे हुए थे, जिसे ''ग्रेट कलकत्ता किलिंग्स'' के नाम से जाना जाता है।

**🧠 Memory Tip**: स्वतंत्रता (15 अगस्त) के ठीक एक दिन बाद की तारीख, लेकिन एक साल पहले (16 अगस्त 1946)।

**🚫 Scam Alert**: कई छात्र इसे 1947 के किसी महीने से जोड़ देते हैं, लेकिन यह कैबिनेट मिशन (1946) की विफलता का सीधा परिणाम था।', 2, 0, 4, 'History', 'When did the Muslim League announce ''Direct Action''?', '**✅ Correct Logic**: After rejecting the Cabinet Mission Plan, Muhammad Ali Jinnah declared August 16, 1946, as ''Direct Action Day'' to demand a separate nation of Pakistan.

**💡 Exam Fact**: This day led to massive communal riots in Bengal, notoriously known as the ''Great Calcutta Killings''.

**🧠 Memory Tip**: Exactly one day after independence day, but one year prior (16 August 1946).

**🚫 Scam Alert**: Often confused with events in 1947, but this was a direct response to the 1946 Cabinet Mission failure.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ahBzI8yKwCEDiD66aOnek', 'owzOzb5J-OfGDUbFNs0n-', '6 अप्रैल, 1930 की तिथि भारत के इतिहास में अच्छी तरह जानी जाती है क्योंकि यह तिथि संबंधित है:', '"[\"भारत छोड़ो आन्दोलन से (Quit India Movement)\",\"बंगाल विभाजन से (Partition of Bengal)\",\"जलियाँवाला बाग हत्याकाण्ड से (Jallianwala Bagh massacre)\",\"महात्मा गाँधी द्वारा डांडी यात्रा से (Dandi March by Mahatma Gandhi)\"]"', '3.0', '**✅ Correct Logic**: महात्मा गांधी ने 12 मार्च 1930 को साबरमती आश्रम से दांडी यात्रा शुरू की और 6 अप्रैल 1930 को समुद्र तट पर नमक कानून तोड़ा, जिससे सविनय अवज्ञा आंदोलन की शुरुआत हुई।

**💡 Exam Fact**: दांडी यात्रा 24 दिनों तक चली और इसमें गांधीजी के साथ 78 अनुयायी शामिल थे।

**🧠 Memory Tip**: 12 मार्च से 6 अप्रैल = 24 दिन का नमक का सफर।

**🚫 Scam Alert**: जलियांवाला बाग (13 अप्रैल 1919) और भारत छोड़ो (8 अगस्त 1942) अलग-अलग दशकों की घटनाएं हैं।', 2, 0, 5, 'History', 'The date 6th April, 1930 is well known in the history of India because this date is associated with:', '**✅ Correct Logic**: Mahatma Gandhi began the Dandi March on 12 March 1930 from Sabarmati Ashram and broke the salt law on the coast on 6 April 1930, marking the start of the Civil Disobedience Movement.

**💡 Exam Fact**: The march lasted for 24 days with 78 chosen followers.

**🧠 Memory Tip**: March 12 to April 6 = 24 days of salt journey.

**🚫 Scam Alert**: Do not confuse with Jallianwala Bagh (13 April 1919) or Quit India (8 Aug 1942).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('NaYx6HRa1LRStFl3rWui1', 'owzOzb5J-OfGDUbFNs0n-', 'भारत में किसी राज्य को विशेष दर्जा देने के लिए निम्नलिखित में से कौन-सा पैरामीटर सामान्यतः स्वीकार नहीं किया जाता है?', '"[\"पहाड़ी व कठिन भू-भाग (Hilly and difficult terrain)\",\"कम जनसंख्या घनत्व (Low population density)\",\"अनुसूचित जाति व अनुसूचित जनजाति की बड़ी आबादी (Sizeable SC and ST population)\",\"अन्तर्राष्ट्रीय सीमाओं के साथ रणनीतिक स्थान (Strategic location along international borders)\"]"', '2.0', '**✅ Correct Logic**: गाडगिल फॉर्मूले के तहत ''विशेष श्रेणी का दर्जा'' (SCS) देने के लिए केवल ''आदिवासी आबादी (ST) का बड़ा हिस्सा'' एक मानदंड है, अनुसूचित जाति (SC) इसमें शामिल नहीं है।

**💡 Exam Fact**: 14वें वित्त आयोग के बाद से विशेष श्रेणी के दर्जे की अवधारणा को बड़े पैमाने पर हटा दिया गया है।

**🧠 Memory Tip**: विशेष दर्जा पहाड़ों (Hilly), सीमाओं (Border) और आदिवासियों (ST) के लिए था, SC के लिए नहीं।

**🚫 Scam Alert**: विकल्प में ''SC'' जोड़कर परीक्षक ने इसे गलत बना दिया। गाडगिल फॉर्मूला केवल ST आबादी की बात करता है।', 2, 0, 6, 'Polity', 'Which of the following is not a generally accepted parameter for granting special status to a state in India?', '**✅ Correct Logic**: Under the Gadgil formula, a ''Sizeable share of tribal population (ST)'' is a criterion for Special Category Status, but Scheduled Castes (SC) are not included in this specific parameter.

**💡 Exam Fact**: The concept of Special Category Status was largely dissolved following the recommendations of the 14th Finance Commission.

**🧠 Memory Tip**: Special status targeted Hills, Borders, and Tribes (ST), not SC.

**🚫 Scam Alert**: The addition of ''SC'' in the option makes it technically incorrect, as the original formula explicitly mentions only the tribal population.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('y8KtJfnbtg-cNzylEV_5u', 'owzOzb5J-OfGDUbFNs0n-', '18वीं लोकसभा के स्पीकर द्वारा वर्ष 2024-25 के लिए गठित संसदीय समितियों के अध्यक्षों की नियुक्ति के संबंध में कौन-सा युग्म गलत है?', '"[\"लोक लेखा समिति - के.सी. वेणुगोपाल (Public Accounts Committee - K.C. Venugopal)\",\"प्राक्कलन समिति - बैजयंत पाण्डा (Estimates Committee - Panda Baijayant)\",\"अनुसूचित जाति एवं अनुसूचित जनजाति कल्याण समिति - फग्गन सिंह कुलस्ते (Committee on Welfare of Scheduled Castes and Scheduled Tribes - Faggan Singh Kulaste)\",\"अन्य पिछड़ा वर्ग कल्याण समिति - गणेश सिंह (Committee on Welfare of Other Backward Classes - Ganesh Singh)\"]"', '1.0', '**✅ Correct Logic**: 18वीं लोकसभा में प्राक्कलन समिति (Estimates Committee) के अध्यक्ष के रूप में संजय जायसवाल को नियुक्त किया गया है, न कि बैजयंत पांडा को।

**💡 Exam Fact**: लोक लेखा समिति (PAC) का अध्यक्ष परंपरानुसार हमेशा विपक्ष के नेता या विपक्ष के सांसद को दिया जाता है (जैसे के.सी. वेणुगोपाल)।

**🧠 Memory Tip**: प्राक्कलन = जायजा लेना -> जायसवाल।

**🚫 Scam Alert**: संसदीय समितियों के नए अध्यक्ष अक्सर करंट अफेयर्स में फंसाते हैं। पीएसी और एस्टीमेट सबसे महत्वपूर्ण हैं।', 2, 0, 7, 'Current Affairs', 'Which pair is incorrect regarding the appointment of Chairpersons of Parliamentary Committees constituted by the Speaker of the 18th Lok Sabha for the year 2024-25?', '**✅ Correct Logic**: For the 18th Lok Sabha, Sanjay Jaiswal was appointed as the Chairperson of the Estimates Committee, making the Baijayant Panda pairing incorrect.

**💡 Exam Fact**: By convention, the Public Accounts Committee (PAC) is chaired by a member of the opposition (like K.C. Venugopal).

**🧠 Memory Tip**: Estimate = taking stock (Jaeza) -> Jaiswal.

**🚫 Scam Alert**: Always double-check current appointments for PAC and Estimates committees as they are examiner favorites.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('LU84UaaQVeDXZzUyML-qR', 'owzOzb5J-OfGDUbFNs0n-', '2023 में हांगजोऊ, चीन में हुए एशियाई खेलों में भारतीय स्वर्ण पदक विजेताओं के लिए निम्नलिखित में से कौन-सा एथलीट-खेल युग्म गलत है?', '"[\"तजिंदरपाल सिंह तूर - शॉट पुट (पुरुष) (Tajinderpal Singh Toor - Shot Put (Men))\",\"अविनाश साबले - 3000 मीटर स्टीपलचेज (पुरुष) (Avinash Sable - 3000 m Steeplechase (Men))\",\"पारुल चौधरी - 5000 मीटर (महिला) (Parul Chaudhary - 5000 m (Women))\",\"अन्नू रानी - 100 मीटर स्प्रिन्ट (महिला) (Annu Rani - 100 m Sprint (Women))\"]"', '3.0', '**✅ Correct Logic**: अन्नू रानी एक प्रसिद्ध जेवलिन थ्रोअर (भाला फेंक) एथलीट हैं, न कि 100 मीटर स्प्रिंटर। उन्होंने 2023 एशियाई खेलों में भाला फेंक में स्वर्ण पदक जीता था।

**💡 Exam Fact**: पारुल चौधरी ने 5000 मीटर में स्वर्ण और 3000 मीटर स्टीपलचेज में रजत पदक जीता था।

**🧠 Memory Tip**: नीरज (पुरुष) और अन्नू (महिला) - दोनों भारत के गोल्डन भाला फेंक एथलीट हैं।

**🚫 Scam Alert**: स्प्रिंट इवेंट्स में भारत के स्वर्ण पदक ऐतिहासिक रूप से कम हैं, इसलिए यह विकल्प स्पष्ट रूप से संदिग्ध था।', 2, 0, 8, 'Sports', 'Which of the following athlete sport pairings is incorrect for Indian gold medalists at the 2023 Asian Games in Hangzhou, China?', '**✅ Correct Logic**: Annu Rani is a renowned Javelin thrower, not a 100m sprinter. She won the Gold medal in Women''s Javelin Throw at the Hangzhou Asian Games.

**💡 Exam Fact**: Parul Chaudhary won gold in the 5000m and silver in the 3000m steeplechase.

**🧠 Memory Tip**: Neeraj (Men) and Annu (Women) = India''s Javelin Gold duo.

**🚫 Scam Alert**: India rarely strikes gold in 100m sprints at the Asian level, making this option logically weak for a gold medalist.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('YX_WrauWMwHHpx94Pu2Dt', 'owzOzb5J-OfGDUbFNs0n-', 'निम्नलिखित में से कौन-सा देश और भारत के साथ संयुक्त सैन्य अभ्यास का युग्म गलत है?', '"[\"रूस - इन्द्र (Russia - Indra)\",\"किर्गिस्तान - खंजर (Kyrgyzstan - Khanjar)\",\"सेशेल्स - लामितिये (Seychelles - Lamitiye)\",\"थाईलैंड - युद्ध अभ्यास (Thailand - Yudh Abhyas)\"]"', '3.0', '**✅ Correct Logic**: ''युद्ध अभ्यास'' भारत और संयुक्त राज्य अमेरिका (USA) के बीच होने वाला सैन्य अभ्यास है। भारत और थाईलैंड के बीच ''मैत्री'' (Maitree) अभ्यास होता है।

**💡 Exam Fact**: लामितिये (Lamitiye) सेशेल्स के साथ होता है और यह हिंद महासागर की सुरक्षा रणनीति का एक महत्वपूर्ण हिस्सा है।

**🧠 Memory Tip**: INDRA = IND (India) + RA (Russia). YUDH ABHYAS = USA.

**🚫 Scam Alert**: देशों और उनके युद्धाभ्यास के नाम अक्सर सीधे पूछे जाते हैं, ''युद्ध अभ्यास'' बहुत प्रसिद्ध भारत-अमेरिका सैन्य ड्रिल है।', 2, 0, 9, 'Current Affairs', 'Which of the following pairs of country and joint military exercise conducted with India is incorrect?', '**✅ Correct Logic**: ''Yudh Abhyas'' is a joint military exercise between India and the USA. The exercise between India and Thailand is called ''Maitree''.

**💡 Exam Fact**: Lamitiye with Seychelles is crucial for India''s strategic footprint in the Indian Ocean Region.

**🧠 Memory Tip**: INDRA = IND(ia) + RA (Russia). Yudh Abhyas = USA.

**🚫 Scam Alert**: Since ''Yudh Abhyas'' is highly publicized and associated with the US military, it clearly mismatches with Thailand.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('TwYBGA0hxxDw_Hlf7unCC', 'owzOzb5J-OfGDUbFNs0n-', 'डेटा सुरक्षा प्रबंधन का सिद्धांत, जो ग्राहकों और संगठन के डेटा को अवैध पहुँच या प्रयोग से सुरक्षित रखने के लिए उपयोग की जाने वाली प्रक्रियाओं, नीतियों और नियंत्रणों को शामिल करता है, उसे कहा जाता है:', '"[\"इंटीग्रिटी (Integrity)\",\"प्राइवेसी (Privacy)\",\"अवेलेबिलिटी (Availability)\",\"कॉन्फिडेन्शिएलिटी (Confidentiality)\"]"', '3.0', '**✅ Correct Logic**: सूचना सुरक्षा के सीआईए ट्रायड (CIA Triad) में, ''Confidentiality'' (गोपनीयता) का अर्थ है यह सुनिश्चित करना कि डेटा तक केवल अधिकृत लोगों की ही पहुँच हो और यह अवैध पहुँच (illicit access) से सुरक्षित रहे।

**💡 Exam Fact**: CIA Triad का मतलब है: Confidentiality (गोपनीयता), Integrity (अखंडता - डेटा बदला नहीं गया है), और Availability (उपलब्धता - जब जरूरत हो तब डेटा उपलब्ध हो)।

**🧠 Memory Tip**: Confidential = Secret = No unauthorized access.

**🚫 Scam Alert**: ''Privacy'' (गोपनीयता) व्यक्तिगत अधिकारों से संबंधित है, जबकि ''Confidentiality'' सुरक्षा तंत्र और डेटा नियंत्रण से संबंधित तकनीकी सिद्धांत है।', 2, 0, 10, 'ICT', 'The principle of data security management, which covers the procedures, policies and controls utilized to secure the data of customers and the organization against illicit access or use, is known as:', '**✅ Correct Logic**: In the CIA Triad of information security, ''Confidentiality'' ensures that data is protected against unauthorized or illicit access.

**💡 Exam Fact**: The CIA Triad stands for Confidentiality, Integrity (data remains unaltered), and Availability (data is accessible when needed).

**🧠 Memory Tip**: Confidential = Kept secret from unauthorized users.

**🚫 Scam Alert**: ''Privacy'' is often an ethical or legal concept regarding personal data, whereas ''Confidentiality'' is the strict technical principle of preventing access.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('L5tL2gjtIPAmkUZNvqAT8', 'V0lPNnyqCpgQUqaxA9ZZJ', 'सारगैसो सागर कहाँ स्थित है ?', '"[\"उत्तरी अटलाण्टिक महासागर (North Atlantic Ocean)\",\"दक्षिणी अटलाण्टिक महासागर (South Atlantic Ocean)\",\"हिन्द महासागर (Indian Ocean)\",\"उत्तरी प्रशान्त महासागर (North Pacific Ocean)\"]"', '0.0', '✅ **सही तर्क**: सारगैसो सागर उत्तरी अटलांटिक महासागर में स्थित है, जो गल्फ स्ट्रीम, उत्तरी अटलांटिक धारा, कैनरी धारा और उत्तरी अटलांटिक विषुवतीय धारा द्वारा घेरा गया है [cite: 142, 144, 194, 195]।
💡 **परीक्षा तथ्य**: यह दुनिया का एकमात्र ऐसा सागर है जिसकी कोई ज़मीनी तटरेखा नहीं है।
🧠 **स्मृति टिप**: ''S-N-A'' (Sargasso - North - Atlantic) याद रखें।
🚫 **स्कैम अलर्ट**: इसे अक्सर दक्षिणी अटलांटिक से भ्रमित किया जाता है, लेकिन यह बरमूडा के पास उत्तर में स्थित है।', 2, 0, 1, 'Geography', 'Where is Sargasso sea situated?', '✅ **Correct Logic**: The Sargasso Sea is located in the North Atlantic Ocean, bounded by four currents: the Gulf Stream, North Atlantic Current, Canary Current, and North Atlantic Equatorial Current[cite: 142, 144, 194, 195].
💡 **Exam Fact**: It is the only sea in the world that has no land coastline.
🧠 **Memory Tip**: Remember ''S-N-A'' (Sargasso - North - Atlantic).
🚫 **Scam Alert**: It is often confused with the South Atlantic, but it lies in the North near Bermuda.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('WDhbbBqdsI6WkOM4Y83n1', 'V0lPNnyqCpgQUqaxA9ZZJ', 'निम्नलिखित में से किस जलमार्ग का आर्थिक तथा युद्धनीतिक महत्व अधिक है ?', '"[\"पाक जलडमरूमध्य (Pak strait)\",\"मलक्का जलडमरूमध्य (Malacca strait)\",\"स्वेज़ नहर (Suez canal)\",\"पनामा नहर (Panama canal)\"]"', '2.0', '✅ **सही तर्क**: स्वेज़ नहर भूमध्य सागर और लाल सागर को जोड़ती है, जिससे यूरोप और एशिया के बीच की दूरी कम हो जाती है, जो इसे अत्यधिक रणनीतिक बनाता है [cite: 163, 167, 203, 206]।
💡 **परीक्षा तथ्य**: स्वेज़ नहर का राष्ट्रीयकरण 1956 में मिस्र द्वारा किया गया था।
🧠 **स्मृति टिप**: ''S-E-A'' (Suez for Europe-Asia trade).
🚫 **स्कैम अलर्ट**: मलक्का भी महत्वपूर्ण है, लेकिन स्वेज़ नहर वैश्विक तेल और माल ढुलाई के लिए सबसे व्यस्ततम बिंदु है।', 2, 0, 2, 'Geography', 'Which one of the following waterways has more economic and strategic significance?', '✅ **Correct Logic**: The Suez Canal connects the Mediterranean and Red Seas, significantly shortening the distance between Europe and Asia, making it highly strategic[cite: 163, 167, 203, 206].
💡 **Exam Fact**: The Suez Canal was nationalized by Egypt in 1956.
🧠 **Memory Tip**: ''S-E-A'' (Suez for Europe-Asia trade).
🚫 **Scam Alert**: While Malacca is important, Suez is the most critical chokepoint for global oil and freight trade.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('97MQ5FAs206WhhHyAAWYG', 'V0lPNnyqCpgQUqaxA9ZZJ', 'निम्नलिखित में से कौन-सा नवीन वलित पर्वत नहीं है ?', '"[\"सियरा नेवादा (Sierra Nevada)\",\"रॉकी (Rocky)\",\"हिमालय (Himalaya)\",\"आल्प्स (Alps)\"]"', '0.0', '✅ **सही तर्क**: सियरा नेवादा एक ''ब्लॉक पर्वत'' है, जबकि अन्य विकल्प (हिमालय, रॉकी, आल्प्स) अल्पाइन काल के नवीन वलित पर्वत हैं [cite: 169, 170, 224, 225]।
💡 **परीक्षा तथ्य**: अरावली भारत में ''पुराने वलित पर्वत'' का सबसे अच्छा उदाहरण है।
🧠 **स्मृति टिप**: ''S-B'' (Sierra is a Block mountain).
🚫 **स्कैम अलर्ट**: अक्सर लोग इसके ऊंचे शिखरों के कारण इसे वलित पर्वत मान लेते हैं, लेकिन इसकी भूवैज्ञानिक संरचना अलग है।', 2, 0, 3, 'Geography', 'Among the following, which one is not a young folded mountain?', '✅ **Correct Logic**: Sierra Nevada is a ''Block Mountain,'' whereas the others (Himalayas, Rockies, Alps) are young fold mountains from the Alpine period[cite: 169, 170, 224, 225].
💡 **Exam Fact**: Aravalli is the best example of ''Old Fold Mountains'' in India.
🧠 **Memory Tip**: ''S-B'' (Sierra is a Block mountain).
🚫 **Scam Alert**: People often mistake it for a fold mountain due to its high peaks, but its geological formation is fault-based.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('feGUTHo1JHZUTSAB9ww3A', 'V0lPNnyqCpgQUqaxA9ZZJ', 'कौन-से दो देशों को ''मेकमोहन रेखा'' विभक्त करती है ?', '"[\"भारत और चीन (India and China)\",\"चीन और अफगानिस्तान (China and Afghanistan)\",\"पाकिस्तान और भारत (Pakistan and India)\",\"पाकिस्तान और अफगानिस्तान (Pakistan and Afghanistan)\"]"', '0.0', '✅ **सही तर्क**: मेकमोहन रेखा भारत के पूर्वोत्तर क्षेत्र और तिब्बत (चीन) के बीच की सीमा रेखा है [cite: 182, 183, 229, 230]।
💡 **परीक्षा तथ्य**: रेडक्लिफ रेखा भारत और पाकिस्तान के बीच है; डूरंड रेखा पाकिस्तान और अफगानिस्तान के बीच है।
🧠 **स्मृति टिप**: ''M-C'' (McMohan - China).
🚫 **स्कैम अलर्ट**: चीन अक्सर इस रेखा को मान्यता देने से इनकार करता है, जिससे यह विवादास्पद बनी रहती है।', 2, 0, 4, 'Geography', 'Which of the two countries is divided by ''McMohan Line''?', '✅ **Correct Logic**: The McMahon Line is the boundary line between the Northeast region of India and Tibet (China)[cite: 182, 183, 229, 230].
💡 **Exam Fact**: Radcliffe Line is between India and Pakistan; Durand Line is between Pakistan and Afghanistan.
🧠 **Memory Tip**: ''M-C'' (McMohan - China).
🚫 **Scam Alert**: China often refuses to officially recognize this line, keeping it a point of contention.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('zLzR5FCngRct1ky0C5len', 'V0lPNnyqCpgQUqaxA9ZZJ', '''ट्रक कृषि'' सम्बन्धित है :', '"[\"साग-सब्जी से (Vegetables)\",\"दूध से (Milk)\",\"अनाज से (Cereals)\",\"मुर्गीपालन से (Poultry)\"]"', '0.0', '✅ **सही तर्क**: ट्रक कृषि का संबंध सब्जियों की व्यावसायिक खेती से है जिन्हें रातों-रात ट्रकों द्वारा बाजारों में भेजा जाता है [cite: 235, 236, 304, 305]।
💡 **परीक्षा तथ्य**: यह शब्द फ्रेंच शब्द ''Troquer'' (ट्रोकर) से आया है, जिसका अर्थ है वस्तु विनिमय।
🧠 **स्मृति टिप**: ''T-V'' (Truck for Vegetables).
🚫 **स्कैम अलर्ट**: इसे परिवहन व्यवसाय से न जोड़ें; यह पूरी तरह से कृषि पद्धति है।', 2, 0, 5, 'Geography', '''Truck farming'' is associated with :', '✅ **Correct Logic**: Truck farming refers to the commercial production of vegetables that are transported to markets overnight by trucks[cite: 235, 236, 304, 305].
💡 **Exam Fact**: The term comes from the French word ''Troquer,'' meaning to barter.
🧠 **Memory Tip**: ''T-V'' (Truck for Vegetables).
🚫 **Scam Alert**: Do not confuse this with the logistics business; it is strictly an agricultural practice.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('g-DLF-NDyuvUQLEP2FrMc', 'V0lPNnyqCpgQUqaxA9ZZJ', 'संयुक्त राष्ट्र द्वारा वर्ष 2023 को घोषित किया गया है :', '"[\"मोटे अनाज का अन्तर्राष्ट्रीय वर्ष (The International Year of Millets)\",\"गेहूँ का अन्तर्राष्ट्रीय वर्ष (The International Year of Wheat)\",\"चावल का अन्तर्राष्ट्रीय वर्ष (The International Year of Rice)\",\"तिलहन का अन्तर्राष्ट्रीय वर्ष (The International Year of Oil-seeds)\"]"', '0.0', '✅ **सही तर्क**: भारत के प्रस्ताव पर संयुक्त राष्ट्र ने 2023 को ''अंतर्राष्ट्रीय पोषक अनाज/मोटे अनाज का वर्ष'' घोषित किया [cite: 247, 250, 316, 317]।
💡 **परीक्षा तथ्य**: बाजरा, रागी, ज्वार आदि मोटे अनाज (Millets) के उदाहरण हैं।
🧠 **स्मृति टिप**: ''2023 - M'' (2023 for Millets).
🚫 **स्कैम अलर्ट**: दालों का वर्ष 2016 था, 2023 विशेष रूप से मोटे अनाज के लिए है।', 2, 0, 6, 'Current Affairs', 'United Nation has declared the year 2023 as :', '✅ **Correct Logic**: Based on India''s proposal, the UN declared 2023 as the ''International Year of Millets''[cite: 247, 250, 316, 317].
💡 **Exam Fact**: Bajra, Ragi, and Jowar are examples of Millets.
🧠 **Memory Tip**: ''2023 - M'' (2023 for Millets).
🚫 **Scam Alert**: The year for pulses was 2016; 2023 is specifically for millets.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Rnbg7DJaY4ODTw-NfuGAc', 'V0lPNnyqCpgQUqaxA9ZZJ', 'विमुक्त जाति दिवस मध्यप्रदेश में किस दिनांक को मनाया जाता है ?', '"[\"31 अगस्त (31 August)\",\"15 जुलाई (15 July)\",\"15 सितम्बर (15 September)\",\"21 मार्च (21 March)\"]"', '0.0', '✅ **सही तर्क**: मध्यप्रदेश सरकार ने 31 अगस्त को विमुक्त जाति दिवस घोषित किया है, क्योंकि इसी दिन 1952 में ''आपराधिक जनजाति अधिनियम'' को निरस्त किया गया था [cite: 263, 272, 321, 322]।
💡 **परीक्षा तथ्य**: विमुक्त, घुमक्कड़ एवं अर्द्ध-घुमक्कड़ जातियों के कल्याण के लिए एक अलग विभाग है।
🧠 **स्मृति टिप**: ''31-A'' (31 August for Azad from old laws).
🚫 **स्कैम अलर्ट**: 15 अगस्त स्वतंत्रता दिवस है, लेकिन विमुक्त जातियों की ''वास्तविक'' मुक्ति 31 अगस्त को मनाई जाती है।', 2, 0, 7, 'MP GK', 'On which date Vimukta Jati (Denotified Tribes) Day is celebrated in Madhya Pradesh?', '✅ **Correct Logic**: The MP government declared August 31 as Vimukta Jati Day because on this day in 1952, the ''Criminal Tribes Act'' was repealed[cite: 263, 272, 321, 322].
💡 **Exam Fact**: There is a dedicated department for the welfare of Denotified, Nomadic, and Semi-Nomadic tribes.
🧠 **Memory Tip**: ''31-A'' (31 August for freedom from old laws).
🚫 **Scam Alert**: August 15 is Independence Day, but the ''actual'' liberation of these tribes is celebrated on August 31.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('wMUg-r7UZOxbV-QeSScJY', 'V0lPNnyqCpgQUqaxA9ZZJ', 'श्री राम सहाय पाण्डे किस लोक नृत्य कला से संबंधित है ?', '"[\"राई (Rai)\",\"बीहू (Beehu)\",\"लावनी (Lawani)\",\"नौटंकी (Nautanki)\"]"', '0.0', '✅ **सही तर्क**: राम सहाय पाण्डे बुंदेलखंड के प्रसिद्ध ''राई'' नृत्य कलाकार हैं और उन्हें पद्मश्री से सम्मानित किया गया है [cite: 290, 292, 328, 329]।
💡 **परीक्षा तथ्य**: राई मध्यप्रदेश का ''राजकीय लोक नृत्य'' है।
🧠 **स्मृति टिप**: ''Ram - Rai'' (दोनों R से शुरू होते हैं).
🚫 **स्कैम अलर्ट**: बीहू असम का है और लावनी महाराष्ट्र का; इन्हें म.प्र. के कलाकारों के साथ न मिलाएँ।', 2, 0, 8, 'MP GK', 'Shri Ram Sahay Pandey is associated to which folk dance art?', '✅ **Correct Logic**: Ram Sahay Pandey is a famous ''Rai'' dancer from Bundelkhand and has been honored with the Padma Shri[cite: 290, 292, 328, 329].
💡 **Exam Fact**: Rai is the ''State Folk Dance'' of Madhya Pradesh.
🧠 **Memory Tip**: ''Ram - Rai'' (Both start with R).
🚫 **Scam Alert**: Beehu belongs to Assam and Lawani to Maharashtra; do not mix them with MP artists.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fVClUNR134fGraXLNH05h', 'V0lPNnyqCpgQUqaxA9ZZJ', 'श्रीमती दुर्गा बाई व्याम किस जनजातिय कला से संबंधित है ?', '"[\"गोंड शैली (Gond Tradition)\",\"भील शैली (Bhil Tradition)\",\"बैगा शैली (Baiga Tradition)\",\"सहरिया शैली (Saharia Tradition)\"]"', '0.0', '✅ **सही तर्क**: दुर्गा बाई व्याम एक सुप्रसिद्ध गोंड चित्रकार हैं और उन्हें 2022 में पद्मश्री मिला [cite: 241, 242, 309, 310]।
💡 **परीक्षा तथ्य**: डिग्ना कला गोंड भित्ति चित्रों का एक हिस्सा है जिसमें दुर्गा बाई माहिर हैं।
🧠 **स्मृति टिप**: ''D-G'' (Durga - Gond).
🚫 **स्कैम अलर्ट**: अक्सर लोग इन्हें भील (पेमा फाल्या) या बैगा शैली से भ्रमित कर देते हैं।', 2, 0, 9, 'MP GK', 'Smt. Durga Bai Vyam is associated with which tribal art ?', '✅ **Correct Logic**: Durga Bai Vyam is a well-known Gond painter and received the Padma Shri in 2022[cite: 241, 242, 309, 310].
💡 **Exam Fact**: Digna art is a part of Gond wall paintings in which Durga Bai specializes.
🧠 **Memory Tip**: ''D-G'' (Durga - Gond).
🚫 **Scam Alert**: People often confuse her with Bhil (Pema Falya) or Baiga traditions.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('pgVR1rfu0PmHaD1XO2Tf-', 'V0lPNnyqCpgQUqaxA9ZZJ', 'सुमेलित कीजिए (Match the column):', '"[\"(1)-a, (2)-b, (3)-c, (4)-d\",\"(1)-b, (2)-a, (3)-d, (4)-c\",\"(1)-d, (2)-c, (3)-b, (4)-a\",\"(1)-d, (2)-b, (3)-c, (4)-a\"]"', '2.0', '✅ **सही तर्क**: यह ''एक जिला एक उत्पाद'' (ODOP) पर आधारित है: बालाघाट (कोदो कुटकी), बैतुल (सागौन), खरगोन (मिर्ची), और नरसिंहपुर (तुअर दाल और गुड़) [cite: 248, 252, 255, 256, 257, 258, 261, 262, 326, 327]।
💡 **परीक्षा तथ्य**: खरगोन की ''बेड़िया मंडी'' मिर्ची के लिए एशिया की सबसे बड़ी मंडियों में से एक है।
🧠 **स्मृति टिप**: ''N-G'' (Narsinghpur for Gud).
🚫 **स्कैम अलर्ट**: बालाघाट को केवल तांबे के लिए न जानें, कोदो कुटकी इसका प्रमुख कृषि उत्पाद है।', 2, 0, 10, 'MP GK', 'Match the column:', '✅ **Correct Logic**: This is based on the ''One District One Product'' (ODOP) initiative: Balaghat (Kodo Kutki), Betul (Teakwood), Khargone (Chilly), and Narsinghpur (Tuar and Jaggery)[cite: 248, 252, 255, 256, 257, 258, 261, 262, 326, 327].
💡 **Exam Fact**: Khargone''s ''Bedia Mandi'' is one of Asia''s largest chilly markets.
🧠 **Memory Tip**: ''N-G'' (Narsinghpur for Gud).
🚫 **Scam Alert**: Don''t know Balaghat only for copper; Kodo Kutki is its primary agricultural product.', 60, 'matching', '[{"id":"1","label":"बालाघाट (Balaghat)","match":"कोदो कुटकी (Kodo Kutki)","matchId":"d"},{"id":"2","label":"बैतुल (Betul)","match":"सागौन (Teakwood)","matchId":"c"},{"id":"3","label":"खरगोन (Khargone)","match":"मिर्ची एवं मिर्ची उत्पाद (Chilly and Chilly Product)","matchId":"b"},{"id":"4","label":"नरसिंहपुर (Narsinghpur)","match":"तुअर दाल एवं गुड़ (Tuar and Jaggery)","matchId":"a"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b8cszxOC0iZZfIMrBqQvD', 'FVA6aomSEdcs9hOKH4Ulz', 'भारत वन स्थिति रिपोर्ट (ISFR) 2021 के अनुसार, मध्यप्रदेश के इनमें से कौन-से जिले में वन आवरण 10 प्रतिशत (जिले के भौगोलिक क्षेत्रफल का %) से कम है?', '"[\"अशोकनगर (Ashoknagar)\",\"मुरैना (Morena)\",\"भिण्ड (Bhind)\",\"गुना (Guna)\"]"', '2.0', '✅ सही तर्क: भिण्ड, उज्जैन और शाजापुर मध्य प्रदेश के ऐसे जिले हैं जहाँ वन आवरण अत्यंत कम (लगभग 2% या उससे भी कम) है।
💡 परीक्षा तथ्य: बालाघाट जिले में मध्य प्रदेश का सर्वाधिक वन आवरण है।
🧠 स्मृति टिप: उत्तरी चंबल क्षेत्र और मालवा के कुछ हिस्सों में पेड़ सबसे कम हैं।
🚫 स्कैम अलर्ट: मुरैना में भी कम है, लेकिन भिण्ड में वन क्षेत्र राज्य में न्यूनतम स्तर पर है।', 2, 0, 1, 'Geography/Environment', 'According to India State of Forest Report (ISFR) 2021, which of these districts of Madhya Pradesh has forest cover less than 10 percent (% of the geographical area of the district)?', '✅ Correct Logic: Districts like Bhind, Ujjain, and Shajapur have extremely sparse forest cover, falling well below the 10% mark of their total geographical area.
💡 Exam Fact: Madhya Pradesh has the largest forest cover in India area-wise, with Balaghat leading the state.
🧠 Memory Tip: Bhind stands for ''Bare'' lands with minimum forests.
🚫 Scam Alert: Morena also has low coverage, but Bhind is historically and statistically among the absolute lowest.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0_19Kp0z0o7mJMAXl8OvI', 'FVA6aomSEdcs9hOKH4Ulz', 'भारतीय संविधान के अनुच्छेद 338 के अंतर्गत निम्नलिखित में से किस आयोग के गठन की बात कही गई है?', '"[\"राष्ट्रीय महिला आयोग (National Commission for Women)\",\"राष्ट्रीय अल्पसंख्यक आयोग (National Commission for Minorities)\",\"राष्ट्रीय मानवाधिकार आयोग (National Human Rights Commission)\",\"राष्ट्रीय अनुसूचित जाति आयोग (National Commission for Scheduled Castes)\"]"', '3.0', '✅ सही तर्क: अनुच्छेद 338 विशेष रूप से ''राष्ट्रीय अनुसूचित जाति आयोग'' (NCSC) के गठन का प्रावधान करता है।
💡 परीक्षा तथ्य: अनुच्छेद 338A ''राष्ट्रीय अनुसूचित जनजाति आयोग'' (NCST) और 338B ''राष्ट्रीय पिछड़ा वर्ग आयोग'' (NCBC) से संबंधित है।
🧠 स्मृति टिप: 338 = SC, 338A = ST, 338B = OBC।
🚫 स्कैम अलर्ट: महिला, अल्पसंख्यक और मानवाधिकार आयोग वैधानिक (Statutory) निकाय हैं, संवैधानिक (Constitutional) नहीं।', 2, 0, 2, 'Polity', 'Article 338 of the Indian Constitution mandates formation of which of the following Commissions?', '✅ Correct Logic: Article 338 of the Constitution explicitly establishes the National Commission for Scheduled Castes (NCSC) to safeguard their rights.
💡 Exam Fact: The 89th Amendment split the original commission, adding Article 338A to create a separate National Commission for Scheduled Tribes (NCST).
🧠 Memory Tip: 338 sets the base for SC; additions A and B cover ST and OBC.
🚫 Scam Alert: Women''s, Minorities'', and Human Rights commissions are created by Acts of Parliament, not by the Constitution itself.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Xvoqo6OsIEMC2BrX526et', 'FVA6aomSEdcs9hOKH4Ulz', '"मुख्यमंत्री लाडली बहना योजना" जो पूरे मध्यप्रदेश में क्रियान्वित की गई है, का उद्देश्य आर्थिक स्वावलंबन के अतिरिक्त निम्न भी है:', '"[\"महिलाओं की राजनीतिक भागीदारी (Women''s political participation)\",\"महिलाओं के विवाह संबंधी खर्च (Women''s marriage-related expenses)\",\"महिलाओं के स्वास्थ्य एवं पोषण (Women''s health and nutrition)\",\"आपराधिक न्याय प्रणाली में महिलाओं के अधिकार (Women''s rights in criminal justice system)\"]"', '2.0', '✅ सही तर्क: लाडली बहना योजना का मुख्य उद्देश्य महिलाओं को वित्तीय सहायता (प्रति माह) देकर उन्हें आर्थिक रूप से स्वतंत्र बनाना और उनके ''स्वास्थ्य एवं पोषण'' के स्तर में सुधार करना है।
💡 परीक्षा तथ्य: यह योजना 2023 में शुरू की गई थी।
🧠 स्मृति टिप: पैसा = अच्छा खाना (पोषण) + स्वास्थ्य।
🚫 स्कैम अलर्ट: विवाह खर्च के लिए ''मुख्यमंत्री कन्या विवाह योजना'' अलग से चलती है, दोनों को एक न समझें।', 2, 0, 3, 'MP GK/Schemes', 'The objective of "Mukhyamantri Ladli Behna Yojana" implemented in entire Madhya Pradesh, in addition to economic self-reliance is:', '✅ Correct Logic: Apart from providing direct financial assistance for economic independence, the Ladli Behna Yojana explicitly aims to improve the health and nutritional status of women and their dependent children.
💡 Exam Fact: It was launched in 2023 by the MP Government.
🧠 Memory Tip: Financial independence leads to better Food and Health.
🚫 Scam Alert: Marriage expenses are covered under a different scheme (Mukhyamantri Kanya Vivah Yojana); do not mix their objectives.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('K1_mM0i7i9e3DU_vun7qa', 'FVA6aomSEdcs9hOKH4Ulz', '30.04.1977 से 23.06.1977 के दौरान, जब मध्यप्रदेश में राष्ट्रपति शासन लागू किया गया, तब मध्यप्रदेश के राज्यपाल थे।', '"[\"श्री मोहम्मद शफी कुरेशी (Shri Mohammad Shafi Qureshi)\",\"श्री सत्य नारायण सिन्हा (Shri Satya Narayan Sinha)\",\"श्री भाई महावीर (Shri Bhai Mahavir)\",\"श्री बी.डी. शर्मा (Shri B.D. Sharma)\"]"', '1.0', '✅ सही तर्क: 1977 में जब मध्य प्रदेश में पहली बार राष्ट्रपति शासन लगा था, तब सत्य नारायण सिन्हा राज्य के राज्यपाल थे।
💡 परीक्षा तथ्य: मध्य प्रदेश में अब तक तीन बार (1977, 1980, 1992) राष्ट्रपति शासन लगा है।
🧠 स्मृति टिप: 1977 का ''सत्य'' (Satyagraha/Emergency era) = सत्य नारायण सिन्हा।
🚫 स्कैम अलर्ट: भाई महावीर 1992 के राष्ट्रपति शासन के समय राज्यपाल थे।', 2, 0, 4, 'MP Polity', '________ was the Governor of Madhya Pradesh when President''s rule was imposed in Madhya Pradesh between 30.04.1977 to 23.06.1977.', '✅ Correct Logic: Shri Satya Narayan Sinha was serving as the Governor of Madhya Pradesh during the state''s first imposition of President''s Rule in 1977.
💡 Exam Fact: Madhya Pradesh has witnessed President''s Rule three times: 1977, 1980, and 1992.
🧠 Memory Tip: First emergency in MP required ''Satya'' (Truth).
🚫 Scam Alert: Shri Bhai Mahavir was the governor during the third President''s rule in 1992; align the governors with the correct years.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('rw_QAe7QxOJlZaK5ijRhz', 'FVA6aomSEdcs9hOKH4Ulz', 'मध्यप्रदेश के निम्नलिखित राज्यपालों में से किसका कार्यकाल सबसे छोटा रहा?', '"[\"पट्टाभि सीतारमैया (Pattabhi Sitaramayya)\",\"हरि विनायक पाटस्कर (Hari Vinayak Pataskar)\",\"क्यासंबली चेंगलराया रेड्डी (Kyasamballi Chengalaraya Reddy)\",\"सत्य नारायण सिन्हा (Satya Narayan Sinha)\"]"', '0.0', '✅ सही तर्क: डॉ. बी. पट्टाभि सीतारमैया, जो मध्य प्रदेश के पहले राज्यपाल थे, का कार्यकाल सबसे छोटा (1 नवंबर 1956 से 13 जून 1957) रहा था।
💡 परीक्षा तथ्य: हरि विनायक पाटस्कर का कार्यकाल मध्य प्रदेश के राज्यपाल के रूप में सबसे लंबा था।
🧠 स्मृति टिप: पहले आए, सबसे जल्दी गए (सीतारमैया)।
🚫 स्कैम अलर्ट: कार्यवाहक (Acting) राज्यपालों का कार्यकाल भी छोटा होता है, लेकिन पूर्णकालिक राज्यपालों में सीतारमैया का सबसे छोटा है।', 2, 0, 5, 'MP Polity', 'Which of the following Governors of Madhya Pradesh had the shortest tenure?', '✅ Correct Logic: Dr. B. Pattabhi Sitaramayya, the first Governor of MP, served the shortest tenure among full-time governors, from November 1, 1956, to June 13, 1957.
💡 Exam Fact: Conversely, Hari Vinayak Pataskar holds the record for the longest tenure as MP''s Governor.
🧠 Memory Tip: The First was the Fastest to leave.
🚫 Scam Alert: Acting governors (Chief Justices) have shorter stints, but among the standard appointed list given, Sitaramayya is the correct answer.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fCtZrZstUnI9av-Ze8QYK', 'FVA6aomSEdcs9hOKH4Ulz', 'मार्च 2023 तक भारत में इनमें से कौन-से राज्य में सौर ऊर्जा की स्थापित क्षमता सर्वाधिक थी?', '"[\"तमिलनाडु (Tamil Nadu)\",\"गुजरात (Gujarat)\",\"राजस्थान (Rajasthan)\",\"कर्नाटक (Karnataka)\"]"', '2.0', '✅ सही तर्क: मार्च 2023 के आंकड़ों के अनुसार, राजस्थान भारत में सर्वाधिक स्थापित सौर ऊर्जा क्षमता (Solar Energy Capacity) वाला राज्य है।
💡 परीक्षा तथ्य: राजस्थान का ''भड़ला सोलर पार्क'' दुनिया का सबसे बड़ा सौर पार्क है।
🧠 स्मृति टिप: सबसे ज्यादा रेगिस्तान + धूप = राजस्थान = सबसे ज्यादा सौर ऊर्जा।
🚫 स्कैम अलर्ट: पवन ऊर्जा (Wind Energy) में तमिलनाडु और गुजरात आगे हैं, लेकिन सौर ऊर्जा में राजस्थान निर्विवाद नेता है।', 2, 0, 6, 'Geography/Economy', 'Which of these states had the highest installed capacity of solar energy in India as on March 2023?', '✅ Correct Logic: As of March 2023, Rajasthan leads India in terms of total installed solar power capacity due to its vast arid lands and high solar insolation.
💡 Exam Fact: The Bhadla Solar Park in Rajasthan is recognized as the largest solar park in the world.
🧠 Memory Tip: Biggest Desert + Maximum Sun = Maximum Solar Power.
🚫 Scam Alert: Tamil Nadu and Gujarat dominate in Wind Energy, but for Solar, Rajasthan is the undisputed champion.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0096OEL84Mv5utJoEXByA', 'FVA6aomSEdcs9hOKH4Ulz', 'दशक 2001-2011 में किस राज्य की जनसंख्या वृद्धि दर भारत में सर्वाधिक रही है?', '"[\"उत्तर प्रदेश (Uttar Pradesh)\",\"राजस्थान (Rajasthan)\",\"मेघालय (Meghalaya)\",\"बिहार (Bihar)\"]"', '2.0', '✅ सही तर्क: 2011 की जनगणना के अनुसार, मेघालय में सर्वाधिक दशकीय जनसंख्या वृद्धि दर (27.9%) दर्ज की गई थी।
💡 परीक्षा तथ्य: नागालैंड एकमात्र ऐसा राज्य था जहाँ नकारात्मक (-0.6%) वृद्धि दर थी।
🧠 स्मृति टिप: मेघ (बादल) की तरह यहाँ जनसंख्या भी तेजी से ''बरसी'' (बढ़ी)।
🚫 स्कैम अलर्ट: उत्तर प्रदेश की जनसंख्या सबसे अधिक है, लेकिन ''वृद्धि दर'' (Growth Rate) के मामले में मेघालय आगे था।', 2, 0, 7, 'Geography/Demography', 'Which state recorded the highest decadal growth rate of population in India during 2001-2011?', '✅ Correct Logic: According to the 2011 Census, the north-eastern state of Meghalaya registered the highest decadal population growth rate at 27.9%.
💡 Exam Fact: Nagaland was the only Indian state to record a negative decadal growth rate (-0.6%).
🧠 Memory Tip: Meghalaya''s numbers grew as fast as its rainfall.
🚫 Scam Alert: Uttar Pradesh has the highest absolute population, but growth rate percentage metrics favor Meghalaya.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ifLE3xODOuRww8Nbl24s1', 'FVA6aomSEdcs9hOKH4Ulz', 'इनमें से कौन-से चक्रवात ने नवम्बर-दिसंबर, 2024 में तमिलनाडु के तटीय भाग को प्रभावित किया था?', '"[\"असना (Asna)\",\"दाना (Dana)\",\"बिपरजॉय (Biparjoy)\",\"फंगल (Fengal)\"]"', '3.0', '✅ सही तर्क: चक्रवात ''फंगल'' (Fengal) ने नवंबर-दिसंबर 2024 में तमिलनाडु और पुदुचेरी के तटीय इलाकों में भारी तबाही मचाई थी।
💡 परीक्षा तथ्य: इस चक्रवात का नाम सऊदी अरब द्वारा सुझाया गया था।
🧠 स्मृति टिप: ''फंगल'' ने तमिलनाडु को फंसाया (नवंबर 24)।
🚫 स्कैम अलर्ट: बिपरजॉय 2023 में अरब सागर में आया था (गुजरात प्रभावित), इसे 2024 के चक्रवातों से न मिलाएँ।', 2, 0, 8, 'Geography/Current Affairs', 'Which of these cyclones affected the coastal region of Tamil Nadu during November-December, 2024?', '✅ Correct Logic: Cyclone Fengal was the severe cyclonic storm that struck the Coromandel coast (Tamil Nadu and Puducherry) in late November and early December 2024.
💡 Exam Fact: The name ''Fengal'' was proposed by Saudi Arabia under the regional naming matrix.
🧠 Memory Tip: Fengal flooded the Tamil Nadu coast at the end of 2024.
🚫 Scam Alert: Biparjoy is a 2023 cyclone that hit the west coast (Gujarat); keep the years and coasts separated.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a9awrxqWr8E6lKqvbC9AD', 'FVA6aomSEdcs9hOKH4Ulz', 'वर्ष 2024 में भारत में निम्नलिखित में से कौन-से परमाणु ऊर्जा केन्द्र की स्थापित क्षमता सर्वाधिक थी?', '"[\"काकरापार (Kakrapar)\",\"कैगा (Kaiga)\",\"कलपक्कम (Kalpakkam)\",\"कुडनकुलम (Kudankulam)\"]"', '3.0', '✅ सही तर्क: तमिलनाडु स्थित ''कुडनकुलम'' परमाणु ऊर्जा संयंत्र भारत का सबसे बड़ा न्यूक्लियर पावर स्टेशन है, जिसकी स्थापित क्षमता सर्वाधिक है।
💡 परीक्षा तथ्य: यह संयंत्र रूस (Russia) के तकनीकी सहयोग से बनाया गया है।
🧠 स्मृति टिप: सबसे बड़ा ''कुलम'' (कुडनकुलम) = सबसे ज्यादा क्षमता।
🚫 स्कैम अलर्ट: तारापुर भारत का सबसे पुराना है, लेकिन क्षमता के मामले में कुडनकुलम सबसे आगे है।', 2, 0, 9, 'Geography/Energy', 'Which of the following atomic power stations had the highest installed capacity in India in the year 2024?', '✅ Correct Logic: Kudankulam Nuclear Power Plant in Tamil Nadu is the largest nuclear power station in India by installed capacity.
💡 Exam Fact: The facility is built in collaboration with Atomstroyexport, the Russian state company.
🧠 Memory Tip: ''Kudankulam'' is the King of capacity.
🚫 Scam Alert: Tarapur is famous as the first commercial plant, but Kudankulam outranks it massively in modern MW capacity.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('PlklPeRTtDR40kvHsY101', 'FVA6aomSEdcs9hOKH4Ulz', 'किस उपनिषद में याज्ञवल्क्य और गार्गी का प्रसिद्ध संवाद मिलता है?', '"[\"बृहदारण्यक उपनिषद (Brihadaranyaka Upanishad)\",\"तैत्तिरीय उपनिषद (Taittiriya Upanishad)\",\"ऐतरेय उपनिषद (Aitareya Upanishad)\",\"प्रश्नोपनिषद (Prashnopanishad)\"]"', '0.0', '✅ सही तर्क: महान दार्शनिक याज्ञवल्क्य और विदुषी गार्गी के बीच ज्ञान-मीमांसा पर हुआ सुप्रसिद्ध संवाद ''बृहदारण्यक उपनिषद'' में वर्णित है।
💡 परीक्षा तथ्य: बृहदारण्यक उपनिषद सबसे पुराने और सबसे बड़े उपनिषदों में से एक है।
🧠 स्मृति टिप: ''बृहद'' (विशाल) संवाद = बृहदारण्यक।
🚫 स्कैम अलर्ट: कठोपनिषद में यम और नचिकेता का संवाद है, इसे गार्गी-याज्ञवल्क्य से न मिलाएँ।', 2, 0, 10, 'History/Ancient India', 'In which Upanishad is the famous dialogue of Yagnavalkya and Gargi mentioned?', '✅ Correct Logic: The intense philosophical debate between the sage Yagnavalkya and the female philosopher Gargi is beautifully documented in the Brihadaranyaka Upanishad.
💡 Exam Fact: The Brihadaranyaka is one of the Principal Upanishads and is among the oldest.
🧠 Memory Tip: A ''Brihad'' (Huge/Great) debate requires a Great Upanishad.
🚫 Scam Alert: The dialogue between Yama and Nachiketa is in the Katha Upanishad; always keep these two epic conversations distinct.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('VtXYRZoSuoKTLJvrGIFgs', '_bMt18BfXiuzYJfAr_hM7', 'निम्नलिखित में से कौन-सा गैर-लाभकारी संगठन भारत में रोबोटिक्स और ऑटोमेशन में मानक स्थापित करने के लिए शीर्ष निकाय है?', '"[\"ऑल इंडिया काउंसिल फॉर रोबोटिक्स एंड ऑटोमेशन (AICRA) / All India Council for Robotics and Automation (AICRA)\",\"नेशनल इंस्टीट्यूट ऑफ रोबोटिक्स एंड आर्टिफिशियल इंटेलीजेंस (NIRA) / National Institute of Robotics and Artificial Intelligence (NIRA)\",\"भारत विज्ञान, प्रौद्योगिकी, इंजीनियरिंग और गणित (स्टेम) मिशन / India Science, Technology, Engineering and Maths (STEM) Mission\",\"भारतीय रोबोटिक्स कौशल केन्द्र (RSCI) / Robotics Skill Centre of India (RSCI)\"]"', '0.0', '✅ सही तर्क: ऑल इंडिया काउंसिल फॉर रोबोटिक्स एंड ऑटोमेशन (AICRA) भारत में रोबोटिक्स और ऑटोमेशन के क्षेत्र में मानकों और शिक्षा को बढ़ावा देने वाला प्रमुख गैर-लाभकारी शीर्ष निकाय है।
💡 परीक्षा तथ्य: AICRA विभिन्न उद्योगों और शैक्षणिक संस्थानों के साथ मिलकर कार्य करता है।
🧠 स्मृति टिप: AICRA (All India) = पूरे भारत का रोबोटिक्स मानक।
🚫 स्कैम अलर्ट: अन्य विकल्प काल्पनिक या कम प्रासंगिक हैं, AICRA ही आधिकारिक मान्यता प्राप्त निकाय है।', 2, 0, 1, 'Science & Tech', 'Which one of the following not-for-profit organization is the apex body for setting up standards in Robotics and Automation in India?', '✅ Correct Logic: The All India Council for Robotics and Automation (AICRA) is the leading not-for-profit apex body dedicated to setting standards and promoting education in robotics and automation in India.
💡 Exam Fact: AICRA frequently organizes tech events, workshops, and standardizes robotics curriculum across institutions.
🧠 Memory Tip: ''AICRA'' sets the ''All India'' rules for Robots.
🚫 Scam Alert: The other acronyms sound official but AICRA is the established apex entity.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('93oE5pOs6mCPEvuueVcVl', '_bMt18BfXiuzYJfAr_hM7', 'एक मैलवेयर, जो एक वैध सॉफ्टवेयर की तरह दिखता है और एक बार जब यह उपयोगकर्ता को बहला कर इसे इंस्टॉल करवा देता है, तो यह काफी हद तक वायरस या वर्म की तरह कार्य करता है, इसे ________ कहा जाता है।', '"[\"कीलॉगर (Keylogger)\",\"रैन्समवेयर (Ransomware)\",\"ट्रोजन (Trojan)\",\"स्पाइवेयर (Spyware)\"]"', '2.0', '✅ सही तर्क: ट्रोजन हॉर्स (Trojan) एक ऐसा मैलवेयर है जो खुद को उपयोगी या वैध सॉफ्टवेयर का रूप देकर उपयोगकर्ता को धोखा देता है। इंस्टॉल होने के बाद यह सिस्टम को नुकसान पहुँचाता है।
💡 परीक्षा तथ्य: इसका नाम ग्रीक पौराणिक कथाओं के ''लकड़ी के घोड़े'' से लिया गया है।
🧠 स्मृति टिप: ट्रोजन = बहरूपिया सॉफ्टवेयर।
🚫 स्कैम अलर्ट: रैंसमवेयर डेटा लॉक करके फिरौती मांगता है, और स्पाइवेयर चुपचाप जासूसी करता है। धोखा देकर घुसने वाला ''ट्रोजन'' है।', 2, 0, 2, 'Information Technology', 'A malware, that looks like a legitimate software and once it tricks a user into installing it, acts pretty much like a virus or worm, is known as:', '✅ Correct Logic: A Trojan (or Trojan Horse) is a type of malicious code or software that looks legitimate but can take control of your computer once installed.
💡 Exam Fact: It is named after the legendary wooden horse used by the Greeks to enter Troy deceitfully.
🧠 Memory Tip: Trojan = The Master of Disguise.
🚫 Scam Alert: Ransomware locks files for money, Spyware watches you; Trojans specifically rely on social engineering to look like safe apps.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('v0fAEZK1_tSC0ncDzarnK', '_bMt18BfXiuzYJfAr_hM7', 'भारतीय संविधान के किस अनुच्छेद के अन्तर्गत राष्ट्रपति राज्य विशेष के लिए अनुसूचित जनजाति समुदायों के लिए लोक अधिसूचना जारी करते हैं?', '"[\"अनुच्छेद 340 (Article 340)\",\"अनुच्छेद 349 (Article 349)\",\"अनुच्छेद 342 (Article 342)\",\"अनुच्छेद 338 (Article 338)\"]"', '2.0', '✅ सही तर्क: संविधान का अनुच्छेद 342 राष्ट्रपति को यह अधिकार देता है कि वह किसी भी राज्य या केंद्र-शासित प्रदेश के संबंध में (राज्यपाल से परामर्श के बाद) अनुसूचित जनजातियों (ST) की सूची अधिसूचित कर सकते हैं।
💡 परीक्षा तथ्य: अनुच्छेद 341 में ''अनुसूचित जाति'' (SC) की सूची के लिए समान प्रावधान है।
🧠 स्मृति टिप: 341 = SC, 342 = ST (नोटिफिकेशन)।
🚫 स्कैम अलर्ट: अनुच्छेद 338 आयोग से जुड़ा है, जबकि 342 ''सूची जारी करने'' से जुड़ा है।', 2, 0, 3, 'Polity', 'Under which Article of the Indian Constitution does the President issue a public notification for the Scheduled Tribes for a specific state?', '✅ Correct Logic: Article 342 of the Constitution empowers the President to publicly notify the tribes or tribal communities to be deemed as Scheduled Tribes in relation to that State or UT.
💡 Exam Fact: While the President creates the first list, only Parliament can amend it later.
🧠 Memory Tip: 341 names the SCs, 342 names the STs.
🚫 Scam Alert: Article 338 is about the National Commission, not the notification of lists.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('MpSkGtxiLxBxNM8uysV_Z', '_bMt18BfXiuzYJfAr_hM7', 'मध्यप्रदेश में मैंगनीज के संबंध में निम्नलिखित कथनों को पढ़िए और नीचे दिए गए कूट से सही उत्तर का चयन कीजिए:
1. वर्ष 2020-21 में, मध्यप्रदेश मैंगनीज निक्षेप में देश में द्वितीय स्थान पर था।
2. वर्ष 2020-21 में, मध्यप्रदेश मैंगनीज उत्पादन में देश में प्रथम स्थान पर था।
3. छिंदवाड़ा जिले में गोदावरी एवं वर्धा नदी घाटियों में मैंगनीज के निक्षेप हैं।
4. झाबुआ जिले की थांदला तहसील में मैंगनीज के निक्षेप हैं।', '"[\"1, 2 एवं 3 सही हैं (1, 2 and 3 are correct)\",\"2, 3 एवं 4 सही हैं (2, 3 and 4 are correct)\",\"1, 3 एवं 4 सही हैं (1, 3 and 4 are correct)\",\"1, 2, 3 एवं 4 सही हैं (1, 2, 3 and 4 are correct)\"]"', '3.0', '✅ सही तर्क: दिए गए सभी कथन सत्य हैं। मध्य प्रदेश उत्पादन में प्रथम और भंडार (निक्षेप) में ओडिशा के बाद दूसरे स्थान पर है। बालाघाट-छिंदवाड़ा बेल्ट और झाबुआ मैंगनीज के प्रमुख क्षेत्र हैं।
💡 परीक्षा तथ्य: बालाघाट की ''भरवेली'' खदान एशिया की सबसे बड़ी भूमिगत मैंगनीज खदान है।
🧠 स्मृति टिप: MP: Production = 1st, Reserve = 2nd.
🚫 स्कैम अलर्ट: अक्सर भंडार (Deposit) और उत्पादन (Production) के रैंकिंग में भ्रम होता है, दोनों को स्पष्ट रूप से याद रखें।', 2, 0, 4, 'MP Geography/Economy', 'Read the following statements regarding manganese in Madhya Pradesh and select the correct answer from the codes given below:
1. In 2020-21, Madhya Pradesh was ranked second in the country for manganese deposits.
2. In 2020-21, Madhya Pradesh was ranked first in the country for manganese production.
3. There are manganese deposits in Godavari and Wardha river valleys in Chhindwara district.
4. There are manganese deposits in Thandla tehsil of Jhabua district.', '✅ Correct Logic: All four statements are factually correct. MP is the top producer but ranks second (after Odisha) in total reserves. Chhindwara-Balaghat and Jhabua are key manganese belts.
💡 Exam Fact: The ''Bharveli'' mine in Balaghat is the largest underground manganese mine in Asia.
🧠 Memory Tip: MP = Number 1 Producer, Number 2 Storer.
🚫 Scam Alert: Examiners love to flip the ''Reserves'' and ''Production'' rankings; be very cautious reading those terms.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1k323-JZGT1Kp1TYb_JtA', '_bMt18BfXiuzYJfAr_hM7', 'भारत के राष्ट्रपति पर महाभियोग निम्नलिखित में से किस आधार पर लगाया जा सकता है?', '"[\"व्यावसायिक कदाचार (Professional misconduct)\",\"संविधान का उल्लंघन (Violation of the Constitution)\",\"लाभ का व्यवसाय करना (Carrying on a vocation of profit)\",\"मानसिक अस्थिरता (Mental instability)\"]"', '1.0', '✅ सही तर्क: भारतीय संविधान के अनुच्छेद 61 के अनुसार, राष्ट्रपति पर महाभियोग चलाने का एकमात्र आधार ''संविधान का उल्लंघन'' (Violation of the Constitution) है।
💡 परीक्षा तथ्य: महाभियोग की प्रक्रिया संसद के किसी भी सदन में शुरू की जा सकती है।
🧠 स्मृति टिप: राष्ट्रपति के लिए एक ही ''पाप'' है = संविधान को तोड़ना।
🚫 स्कैम अलर्ट: ''कदाचार'' या ''अक्षमता'' सुप्रीम कोर्ट के जजों को हटाने के आधार हैं, राष्ट्रपति के लिए नहीं।', 2, 0, 5, 'Polity', 'Impeachment can be imposed on the President of India on which of the following grounds?', '✅ Correct Logic: According to Article 61 of the Indian Constitution, the only ground for the impeachment of the President is the ''Violation of the Constitution''.
💡 Exam Fact: The impeachment charge can be initiated by either House of Parliament requiring a two-thirds majority.
🧠 Memory Tip: President''s only unpardonable sin = Breaking the Constitution.
🚫 Scam Alert: ''Proved misbehavior or incapacity'' are grounds for removing Supreme Court judges, strictly NOT the President.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1UdU1ziKM6dUSjqLM9-SV', '_bMt18BfXiuzYJfAr_hM7', 'मौद्रिक नीति का मुख्य उद्देश्य क्या है?', '"[\"सरकारी खर्च बढ़ाना (Increase government spending)\",\"मूल्य स्थिरता बनाए रखना और आर्थिक वृद्धि सुनिश्चित करना (Maintain price stability while ensuring economic growth)\",\"राजकोषीय घाटा कम करना (Reduce fiscal deficit)\",\"विदेशी मुद्रा भण्डार को नियंत्रित करना (Control foreign exchange reserves)\"]"', '1.0', '✅ सही तर्क: मौद्रिक नीति (Monetary Policy) का मुख्य कार्य महंगाई (मूल्य स्थिरता) को नियंत्रित करना और अर्थव्यवस्था में विकास दर को बढ़ावा देना है।
💡 परीक्षा तथ्य: भारत में मौद्रिक नीति भारतीय रिज़र्व बैंक (RBI) की मौद्रिक नीति समिति (MPC) द्वारा तय की जाती है।
🧠 स्मृति टिप: Monetary = Money Control = Price Stability.
🚫 स्कैम अलर्ट: सरकारी खर्च बढ़ाना और राजकोषीय घाटा कम करना ''राजकोषीय नीति'' (Fiscal Policy) का हिस्सा हैं, जो सरकार बनाती है, रिज़र्व बैंक नहीं।', 2, 0, 6, 'Economy', 'What is the primary objective of the Monetary Policy?', '✅ Correct Logic: The primary objective of Monetary Policy is to maintain price stability (control inflation) while keeping in mind the objective of economic growth.
💡 Exam Fact: In India, the Monetary Policy is formulated by the Monetary Policy Committee (MPC) of the Reserve Bank of India (RBI).
🧠 Memory Tip: Monetary = Manage Money = Maintain Prices.
🚫 Scam Alert: Increasing government spending and reducing fiscal deficit are objectives of ''Fiscal Policy'' managed by the Government, not Monetary Policy.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fLjbXfprJy7YSp5qH0SnU', '_bMt18BfXiuzYJfAr_hM7', 'वित्तीय वर्ष 2023-24 में भारत के कुल व्यापार घाटे को कम करने में किस क्षेत्र ने महत्त्वपूर्ण भूमिका निभाई?', '"[\"कृषि निर्यात (Agricultural exports)\",\"माल निर्यात (Merchandise exports)\",\"सेवा निर्यात (Service exports)\",\"ऑटोमोबाइल निर्यात (Automobile exports)\"]"', '2.0', '✅ सही तर्क: भारत माल (Merchandise) के व्यापार में भारी घाटे में रहता है (हम आयात ज्यादा करते हैं), लेकिन ''सेवा निर्यात'' (Service exports - IT, BPO) हमेशा बड़े सरप्लस में रहता है जो कुल घाटे को कम (cushion) करता है।
💡 परीक्षा तथ्य: भारत दुनिया में IT और सॉफ्टवेयर सेवाओं का अग्रणी निर्यातक है।
🧠 स्मृति टिप: भारत दुनिया को ''सर्विस'' (Service) देता है।
🚫 स्कैम अलर्ट: कृषि और ऑटोमोबाइल निर्यात महत्वपूर्ण हैं, लेकिन सेवा क्षेत्र का सरप्लस इतना बड़ा है कि वह पूरे व्यापार घाटे को काफी हद तक संतुलित कर देता है।', 2, 0, 7, 'Economy', 'Which sector played a key role in cushioning India''s overall trade deficit in the financial year 2023-24?', '✅ Correct Logic: India traditionally runs a huge merchandise trade deficit (we import more goods than we export). However, our ''Service exports'' (IT, BPO, software) run a massive surplus, which cushions the overall trade deficit.
💡 Exam Fact: India is one of the world''s leading exporters of IT and software services.
🧠 Memory Tip: Services = India''s Savior in Trade.
🚫 Scam Alert: While agricultural and automobile exports exist, they don''t generate the massive surplus needed to cushion the overall trade deficit like the services sector does.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('vSksflFIka3ZTbj1ZoAEg', '_bMt18BfXiuzYJfAr_hM7', 'वर्ष 2017-18 में भारत के किस राज्य में विनिर्माण क्षेत्र में पूँजी गहनता सबसे अधिक है?', '"[\"गुजरात (Gujarat)\",\"महाराष्ट्र (Maharashtra)\",\"तमिलनाडु (Tamil Nadu)\",\"मध्यप्रदेश (Madhya Pradesh)\"]"', '0.0', '✅ सही तर्क: 2017-18 के आर्थिक आंकड़ों और ASI (Annual Survey of Industries) के अनुसार, गुजरात में विनिर्माण क्षेत्र में प्रति श्रमिक पूंजी (Capital intensity) सर्वाधिक थी।
💡 परीक्षा तथ्य: गुजरात भारत का एक प्रमुख औद्योगिक और पेट्रोकेमिकल हब है जहाँ भारी मशीनरी का उपयोग होता है।
🧠 स्मृति टिप: गुजरात = भारी उद्योग = उच्च पूँजी (High Capital).
🚫 स्कैम अलर्ट: महाराष्ट्र कुल जीडीपी में आगे हो सकता है, लेकिन ''पूंजी गहनता'' (Capital Intensity - पूँजी और श्रम का अनुपात) में गुजरात सबसे ऊपर है।', 2, 0, 8, 'Economy', 'In India, which state has the highest capital intensity in manufacturing sector in 2017-18?', '✅ Correct Logic: According to the Annual Survey of Industries (ASI) 2017-18 data, Gujarat registered the highest capital intensity (capital invested per worker) in the manufacturing sector.
💡 Exam Fact: Gujarat''s economy is highly driven by capital-intensive industries like petrochemicals and large manufacturing.
🧠 Memory Tip: Gujarat = Heavy Machinery = High Capital Intensity.
🚫 Scam Alert: Maharashtra might lead in overall GDP, but ''Capital Intensity'' is a ratio where Gujarat''s heavy industrial base puts it at the top.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('65A0rVGgGJu6NAtGhy3DI', '_bMt18BfXiuzYJfAr_hM7', 'भारत किन कृषि उत्पादों में सबसे बड़ा उत्पादक है?', '"[\"चावल, गेहूँ और कपास (Rice, Wheat and Cotton)\",\"दूध, दालें और मसाले (Milk, Pulses and Spices)\",\"चाय, कॉफी और जूट (Tea, Coffee and Jute)\",\"गन्ना, मक्का और तिलहन (Sugarcane, Maize and Oilseeds)\"]"', '1.0', '✅ सही तर्क: भारत विश्व स्तर पर दूध (Milk), दालों (Pulses) और मसालों (Spices) का दुनिया का सबसे बड़ा उत्पादक देश है।
💡 परीक्षा तथ्य: भारत जूट का भी सबसे बड़ा उत्पादक है, लेकिन चाय में चीन आगे है।
🧠 स्मृति टिप: ''D-D-M'' (दूध, दाल, मसाले) = India Number 1.
🚫 स्कैम अलर्ट: चावल और गेहूं में चीन दुनिया में पहले स्थान पर है और भारत दूसरे स्थान पर।', 2, 0, 9, 'Geography/Economy', 'India is the largest producer of which agricultural products?', '✅ Correct Logic: India consistently ranks as the world''s largest producer of Milk, Pulses, and Spices.
💡 Exam Fact: India is also the largest producer of Jute, but ranks second in Tea (behind China).
🧠 Memory Tip: ''M-P-S'' (Milk, Pulses, Spices) = India is the Boss.
🚫 Scam Alert: Do not pick Rice or Wheat; China is the top producer of both, with India at a close second.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cPMu3ZFLUJd3Zt68EIwfo', '_bMt18BfXiuzYJfAr_hM7', 'वर्ष 2011 की जनगणना के अनुसार, निम्नलिखित में से कौन-से जिले की जनसंख्या की दशकीय वृद्धि दर सर्वाधिक थी?', '"[\"सिंगरौली (Singrauli)\",\"भोपाल (Bhopal)\",\"इंदौर (Indore)\",\"बड़वानी (Barwani)\"]"', '2.0', '✅ सही तर्क: 2011 की जनगणना के अनुसार, मध्य प्रदेश के इंदौर जिले में सबसे अधिक दशकीय जनसंख्या वृद्धि दर (32.9%) दर्ज की गई थी।
💡 परीक्षा तथ्य: इसके विपरीत, अनूपपुर जिले में दशकीय वृद्धि दर राज्य में सबसे कम (12.3%) रही।
🧠 स्मृति टिप: इंदौर (Mini Mumbai) में रोजगार के लिए सबसे ज्यादा लोग आए (Highest Growth)।
🚫 स्कैम अलर्ट: भोपाल जनसंख्या घनत्व (Density) में सबसे आगे है, पर ''वृद्धि दर'' (Decadal Growth) में इंदौर अव्वल है।', 2, 0, 10, 'MP Demography', 'According to the 2011 Census, which of the following districts had the highest decadal growth rate of population?', '✅ Correct Logic: According to the 2011 Census data for Madhya Pradesh, Indore district recorded the highest decadal population growth rate at 32.9%.
💡 Exam Fact: Conversely, Anuppur district had the lowest decadal growth rate (12.3%) in the state.
🧠 Memory Tip: Indore being the commercial capital attracted the highest influx of people.
🚫 Scam Alert: Bhopal leads in population density, but for percentage growth over the decade, Indore is the correct answer.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('hwWCN32hmdTNT21-yQiE5', 'dPjxq4JIOG1tOL_YsyAiv', 'राष्ट्रीय ई-गवर्नेस योजना (NeGP) के तहत मिशन मोड परियोजनाओं का सार संग्रह कहा जाता है :', '"[\"ई-प्रमाण (E-Pramaan)\",\"डिजीलॉकर (DigiLocker)\",\"सारांश (Saaransh)\",\"एम.ई.आई.टी. वाई (MeitY)\"]"', '2.0', '✅ **सही तर्क**: राष्ट्रीय ई-गवर्नेंस योजना (NeGP) के तहत सभी मिशन मोड प्रोजेक्ट्स (MMPs) की प्रगति और विवरण वाले दस्तावेज़/सार संग्रह को ''सारांश'' (Saaransh) नाम दिया गया है।
💡 **परीक्षा तथ्य**: NeGP को 2006 में भारत सरकार द्वारा 27 मिशन मोड परियोजनाओं के साथ शुरू किया गया था।
🧠 **स्मृति टिप**: ''सार संग्रह'' का हिंदी पर्याय ही ''सारांश'' होता है।
🚫 **स्कैम अलर्ट**: ''ई-प्रमाण'' ई-प्रमाणीकरण (e-Authentication) के लिए है और ''MeitY'' एक मंत्रालय है, इन्हें प्रोजेक्ट का कम्पेंडियम न समझें।', 2, 0, 1, 'Information Technology', 'The compendium of Mission Mode Projects under National e-Governance Plan (NeGP) is known as :', '✅ **Correct Logic**: The document or compendium summarizing the progress and details of the Mission Mode Projects under the National e-Governance Plan is officially titled ''Saaransh''.
💡 **Exam Fact**: NeGP was launched in 2006, initially comprising 27 Mission Mode Projects to boost e-governance.
🧠 **Memory Tip**: A compendium means a summary, which translates to ''Saaransh'' in Hindi.
🚫 **Scam Alert**: ''E-Pramaan'' is an authentication framework, and ''MeitY'' is the IT Ministry. Do not confuse the implementing bodies with the report name.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('INR7tRjasyyRdC7t8b2h4', 'dPjxq4JIOG1tOL_YsyAiv', 'सोशल मीडिया प्लेटफॉर्म ''फेसबुक'' की स्थापना किसने की थी?', '"[\"मार्क जुकरबर्ग (Mark Zuckerberg)\",\"इलॉन मस्क (Elon Musk)\",\"बिल गेट्स (Bill Gates)\",\"जैक डोर्सी (Jack Dorsey)\"]"', '0.0', '✅ **सही तर्क**: फेसबुक (वर्तमान में मेटा) की स्थापना 2004 में मार्क जुकरबर्ग ने हार्वर्ड यूनिवर्सिटी में अपने कॉलेज के साथियों के साथ मिलकर की थी।
💡 **परीक्षा तथ्य**: फेसबुक का नाम 2021 में बदलकर ''मेटा प्लेटफ़ॉर्म्स इंक'' (Meta Platforms Inc.) कर दिया गया।
🧠 **स्मृति टिप**: एफ-बी (FB) = मार्क जुकरबर्ग का ''चेहरा'' (Face)।
🚫 **स्कैम अलर्ट**: जैक डोर्सी ट्विटर (अब X) के सह-संस्थापक थे, और इलॉन मस्क ने इसे बाद में खरीदा था।', 2, 0, 2, 'Information Technology', 'The social media platform ''Facebook'' was founded by:', '✅ **Correct Logic**: Facebook (now Meta) was founded in 2004 by Mark Zuckerberg along with his Harvard College roommates.
💡 **Exam Fact**: In 2021, the parent company of Facebook officially changed its name to Meta.
🧠 **Memory Tip**: Face = Mark Zuckerberg''s iconic creation.
🚫 **Scam Alert**: Jack Dorsey is associated with Twitter (now X), not Facebook.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('E9bGJmzEWdZ3Bdoh5pbEe', 'dPjxq4JIOG1tOL_YsyAiv', 'गार्टनर के ई-गवर्नेस के विकास मॉडल के चार चरणों का सही क्रम है :', '"[\"सूचना -> बातचीत -> लेन-देन -> परिवर्तन (Information -> Interaction -> Transaction -> Transformation)\",\"बातचीत -> लेन-देन -> परिवर्तन -> सूचना (Interaction -> Transaction -> Transformation -> Information)\",\"लेन-देन -> परिवर्तन -> बातचीत -> सूचना (Transaction -> Transformation -> Interaction -> Information)\",\"बातचीत -> लेन-देन -> सूचना -> परिवर्तन (Interaction -> Transaction -> Information -> Transformation)\"]"', '0.0', '✅ **सही तर्क**: गार्टनर के ई-गवर्नेंस परिपक्वता मॉडल में 4 चरण होते हैं: 1. सूचना (वेबसाइट पर डेटा देना), 2. बातचीत (ईमेल/फीडबैक), 3. लेन-देन (फीस भरना/ऑनलाइन फॉर्म), 4. परिवर्तन (पूरी तरह से डिजिटल बदलाव)।
💡 **परीक्षा तथ्य**: यह मॉडल 2000 में ''गार्टनर ग्रुप'' द्वारा पेश किया गया था ताकि सरकारें अपने डिजिटल विकास को माप सकें।
🧠 **स्मृति टिप**: 2-I, 2-T (Info, Interact -> Transact, Transform)।
🚫 **स्कैम अलर्ट**: हमेशा सबसे सरल (Information) से शुरू होकर सबसे जटिल (Transformation) पर खत्म होता है।', 2, 0, 3, 'Information Technology', 'The correct sequence of four phases of Gartner''s Evolution of E-Governance Model is :', '✅ **Correct Logic**: Gartner''s maturity model for e-governance dictates a linear progression: 1. Information (Web presence), 2. Interaction (Two-way comms), 3. Transaction (Online payments), 4. Transformation (Complete digital overhaul).
💡 **Exam Fact**: Introduced in 2000, it is the global standard for measuring e-government maturity.
🧠 **Memory Tip**: Remember the 2-I''s then 2-T''s (Info -> Interact -> Transact -> Transform).
🚫 **Scam Alert**: Any sequence not starting with ''Information'' (the most basic step) is automatically wrong.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('qRwDFnHCc-QS0Pj5t56o5', 'dPjxq4JIOG1tOL_YsyAiv', 'निम्नलिखित में से कौन 2024 के पद्म विभूषण पुरस्कार के प्राप्तकर्ता नहीं हैं?', '"[\"सुश्री वैजयंतीमाला बाली (Ms. Vyjayantimala Bali)\",\"श्री कोनिडेला चिरंजीवी (Shri Konidela Chiranjeevi)\",\"श्री एम. वेंकैया नायडू (Shri M. Venkaiah Naidu)\",\"श्री ए.आर. रहमान (Shri A.R. Rahman)\"]"', '3.0', '✅ **सही तर्क**: संगीतकार ए.आर. रहमान को 2010 में पद्म भूषण मिला था, लेकिन वे 2024 के पद्म विभूषण विजेताओं की सूची में शामिल नहीं हैं।
💡 **परीक्षा तथ्य**: 2024 में कुल 5 लोगों को पद्म विभूषण दिया गया (वैजयंतीमाला, चिरंजीवी, एम. वेंकैया नायडू, बिन्देश्वर पाठक, और पद्मा सुब्रह्मण्यम)।
🧠 **स्मृति टिप**: 2024 के ''पंच-रत्न'' में रहमान नहीं थे।
🚫 **स्कैम अलर्ट**: प्रसिद्ध हस्तियों के नाम देकर अक्सर करंट अफेयर्स में फंसाया जाता है; रहमान को ऑस्कर मिला है, पर 2024 का पद्म विभूषण नहीं।', 2, 0, 4, 'Current Affairs', 'Which of the following individuals was not a recipient of the Padam Vibhushan award in 2024?', '✅ **Correct Logic**: A.R. Rahman was awarded the Padma Bhushan earlier (2010), but he is not among the recipients of the Padma Vibhushan in 2024.
💡 **Exam Fact**: In 2024, only 5 individuals were honored with the Padma Vibhushan, including Vyjayantimala, Chiranjeevi, and M. Venkaiah Naidu.
🧠 **Memory Tip**: Rahman is an Oscar legend, but not part of the 2024 ''Top 5'' Padma Vibhushan list.
🚫 **Scam Alert**: Famous personalities are frequently used as distractors in awards questions. Always memorize the exact list for the current year.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('u0z26n6bcbs9xnqcS4I3c', 'dPjxq4JIOG1tOL_YsyAiv', 'भारतीय संविधान के किस अनुच्छेद में अनुसूचित जनजातियों के लिए राज्य की विधानसभा में सीटों के आरक्षण का प्रावधान है?', '"[\"अनुच्छेद 339 (Article 339)\",\"अनुच्छेद 332 (Article 332)\",\"अनुच्छेद 334 (Article 334)\",\"अनुच्छेद 243D (Article 243D)\"]"', '1.0', '✅ **सही तर्क**: भारतीय संविधान का अनुच्छेद 332 राज्यों की ''विधानसभाओं'' (Legislative Assemblies) में अनुसूचित जातियों (SC) और अनुसूचित जनजातियों (ST) के लिए सीटों के आरक्षण का प्रावधान करता है।
💡 **परीक्षा तथ्य**: अनुच्छेद 330 ''लोकसभा'' (Lok Sabha) में SC/ST के आरक्षण से संबंधित है।
🧠 **स्मृति टिप**: 330 (लोकसभा) -> 332 (विधानसभा)।
🚫 **स्कैम अलर्ट**: अनुच्छेद 243D ''पंचायतों'' में आरक्षण के लिए है, इसे विधानसभा (332) से न मिलाएँ।', 2, 0, 5, 'Polity', 'In which Article of the Indian Constitution is there a provision of reservation of seats for Scheduled Tribes in the State Assembly?', '✅ **Correct Logic**: Article 332 of the Indian Constitution specifically deals with the reservation of seats for Scheduled Castes and Scheduled Tribes in the Legislative Assemblies of the States.
💡 **Exam Fact**: Article 330 provides for similar reservations but in the Lok Sabha (House of the People).
🧠 **Memory Tip**: Remember the jump: 330 for Centre (Lok Sabha), 332 for State (Assembly).
🚫 **Scam Alert**: Article 243D provides reservation in Panchayats. Read carefully whether the question asks for State Assembly or local bodies.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Pnwlwf5hKuy_IW830PJrc', 'dPjxq4JIOG1tOL_YsyAiv', 'एफपीजीए (FPGA) एकीकृत सर्किट हैं, जिनका AI को डिप्लोय करने के लिए व्यापक रूप से उपयोग किया जाता है। एफपीजीए का विस्तृत रूप क्या है?', '"[\"फील्ड प्रोग्रामेबल गेट एरेज (Field Programmable Gate Array)\",\"फॉरवर्ड प्रोग्रामेबल ग्राफिकल एडवांसमेंट (Forward Programmable Graphical Advancements)\",\"फॉरवर्ड प्रोग्राम ग्रुप इंटेलीजेंस (Forward Programme Group Intelligence)\",\"फास्टर प्रोग्राम जेस्चर एनालिटिक्स (Faster Programme Gesture Analytics)\"]"', '0.0', '✅ **सही तर्क**: FPGA का पूर्ण रूप ''Field Programmable Gate Array'' है। ये ऐसे सेमीकंडक्टर डिवाइस हैं जिन्हें निर्माण के बाद ग्राहक द्वारा अपने अनुसार प्रोग्राम किया जा सकता है।
💡 **परीक्षा तथ्य**: आर्टिफिशियल इंटेलिजेंस (AI) और मशीन लर्निंग में डेटा को तेजी से प्रोसेस करने के लिए इनका बहुत उपयोग होता है।
🧠 **स्मृति टिप**: फील्ड (Field) में जाकर प्रोग्राम (Programmable) होने वाला ''गेट'' (Gate)।
🚫 **स्कैम अलर्ट**: ''ग्राफिकल'' या ''एनालिटिक्स'' जैसे शब्द केवल AI से जुड़ाव दिखाने के लिए गढ़े गए हैं; इसका हार्डवेयर नाम ''गेट एरे'' है।', 2, 0, 6, 'Information Technology/Science', 'FPGA are integrated circuits that are widely used to deploy AI. What is the full form of FPGA?', '✅ **Correct Logic**: FPGA stands for ''Field Programmable Gate Array''. These are integrated circuits designed to be configured by a customer or a designer after manufacturing.
💡 **Exam Fact**: FPGAs are highly valued in AI and deep learning for their ability to be re-programmed for specific, highly parallel processing tasks.
🧠 **Memory Tip**: ''Field'' means you can program the ''Gates'' locally at your desk.
🚫 **Scam Alert**: Options with ''Graphical'' try to confuse you with GPUs (Graphics Processing Units). FPGA is strictly Gate Arrays.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('pWzYgvyWhffhthv5QNbe4', 'dPjxq4JIOG1tOL_YsyAiv', 'जनजातियों पर लिखी पुस्तकों की सूची-I को उनके लेखकों की सूची-II से सुमेलित कीजिए और सूचियों के नीचे दिए गए कूट का उपयोग करके सही उत्तर का चयन कीजिए:', '"[\"(i)-3, (ii)-4, (iii)-2, (iv)-1\",\"(i)-1, (ii)-2, (iii)-4, (iv)-3\",\"(i)-4, (ii)-1, (iii)-3, (iv)-2\",\"(i)-2, (ii)-3, (iii)-1, (iv)-4\"]"', '0.0', '✅ **सही तर्क**: ''द बैगा'' वेरियर एल्विन की प्रसिद्ध रचना है। ''द भील्स'' टी.बी. नाइक ने लिखी है। ''द ट्राइब्स एण्ड कास्ट्स...'' रसेल और हीरालाल की क्लासिक किताब है।
💡 **परीक्षा तथ्य**: वेरियर एल्विन ने मध्य प्रदेश की जनजातियों पर बहुत काम किया है, उनकी ''द मुड़िया एंड देयर घोटुल'' भी बहुत पूछी जाती है।
🧠 **स्मृति टिप**: बैगा = वेरियर एल्विन (B-V), भील = नाइक (B-N)।
🚫 **स्कैम अलर्ट**: यदि आपको केवल ''द बैगा'' (iv-1) भी याद है, तो आप आसानी से सही विकल्प (A) तक पहुँच सकते हैं।', 2, 0, 7, 'MP GK/Tribes', 'Match List-I of books on tribes with List-II of their authors and select the correct answer using the codes given below:', '✅ **Correct Logic**: ''The Baiga'' is a masterpiece by Verrier Elwin. ''The Bhils: A Study'' is authored by T.B. Naik. The monumental ''Tribes and Castes of the Central Provinces'' is by R.V. Russell and R.B. Hiralal.
💡 **Exam Fact**: Verrier Elwin was a British anthropologist who lived among Indian tribes. His works are extremely frequent in MPPSC exams.
🧠 **Memory Tip**: Baiga = Elwin. Matching just (iv) to 1 gives you the correct answer immediately via elimination.
🚫 **Scam Alert**: Do not get bogged down if you don''t know ''Ajit Raizada''; use the classic texts (Elwin and Russell) to crack the code.', 60, 'matching', '[{"id":"(i)","label":"द ट्राइब्स एण्ड कास्ट्स ऑफ सेंट्रल प्रॉविंसेस ऑफ इण्डिया (The Tribes and Castes of the Central Provinces of India)","match":"आर.वी. रसेल एवं आर.बी. हीरालाल (R.V. Russell and R.B. Hiralal)","matchId":"3"},{"id":"(ii)","label":"ट्राइबल डेवलपमेंट इन म.प्र.: ए प्लानिंग पर्सपेक्टिव (Tribal Development in M.P.: A Planning Perspective)","match":"अजित रायजादा (Ajit Raizada)","matchId":"4"},{"id":"(iii)","label":"द भील्सः ए स्टडी (The Bhils: A Study)","match":"टी.बी. नाइक (T.B. Naik)","matchId":"2"},{"id":"(iv)","label":"द बैगा (The Baiga)","match":"वेरियर एल्विन (Verrier Elwin)","matchId":"1"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('JAZt35gzng9RamFofUcwq', 'dPjxq4JIOG1tOL_YsyAiv', 'किसी भी प्रकार की त्रुटि जैसे कनेक्शन विफलता, डेटा की हानि, आदि से उभरने की कंप्यूटर नेटवर्क की क्षमता कहा जाता है।', '"[\"रूटिंग (Routing)\",\"बैंडविड्द्ध (Bandwidth)\",\"विवाद (कंटेन्शन) (Contention)\",\"लचीलापन (रेसिलिएस) (Resilience)\"]"', '3.0', '✅ **सही तर्क**: नेटवर्किंग में, किसी खराबी (विफलता) के बाद नेटवर्क के जल्दी ठीक होने या बैकअप मार्ग (Backup path) से काम चालू रखने की क्षमता को ''नेटवर्क रेसिलिएंस'' (लचीलापन) कहा जाता है।
💡 **परीक्षा तथ्य**: एक ''रेसिलिएंट'' नेटवर्क में फौल्ट टॉलरेंस (Fault Tolerance) और रिडंडेंसी (Redundancy) होती है।
🧠 **स्मृति टिप**: गिर कर फिर उठने की क्षमता = रेसिलिएंस (Resilience)।
🚫 **स्कैम अलर्ट**: रूटिंग (Routing) सिर्फ डेटा भेजने का रास्ता तय करना है, खराबी से उबरना रेसिलिएंस का गुण है।', 2, 0, 8, 'Information Technology', 'The ability of a computer network to recover from any kind of error like connection failure, loss of data, etc. is known as:', '✅ **Correct Logic**: Network ''Resilience'' is the ability to provide and maintain an acceptable level of service in the face of faults and challenges to normal operation.
💡 **Exam Fact**: Redundancy (having backup paths or devices) is a primary method used to build resilient networks.
🧠 **Memory Tip**: Resilience = Bouncing back from an error.
🚫 **Scam Alert**: Routing is just pathfinding; Bandwidth is speed/capacity. Only Resilience deals with ''recovery'' from errors.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('W8aVholQV7p2OlhJSzfZA', 'dPjxq4JIOG1tOL_YsyAiv', 'निम्नलिखित में से कौन-सी पुस्तक राजशेखर द्वारा नहीं लिखी गई है?', '"[\"काव्यमीमांसा (Kavyamimamsa)\",\"कर्पूरमंजरी (Karpuramanjari)\",\"प्रबंधचिन्तामणि (Prabandhachintamani)\",\"विद्धशालभञ्जिका (Viddhashalabhanjika)\"]"', '2.0', '✅ **सही तर्क**: ''प्रबंधचिन्तामणि'' की रचना 14वीं शताब्दी में जैन विद्वान ''मेरुतुंग'' द्वारा की गई थी। अन्य तीनों (काव्यमीमांसा, कर्पूरमंजरी, विद्धशालभञ्जिका) संस्कृत के महान कवि राजशेखर की रचनाएं हैं।
💡 **परीक्षा तथ्य**: राजशेखर गुर्जर-प्रतिहार शासकों (महेन्द्रपाल प्रथम और महिपाल) के दरबारी कवि थे।
🧠 **स्मृति टिप**: मेरुतुंग को हमेशा ''चिन्ता'' (प्रबंधचिन्तामणि) रहती थी।
🚫 **स्कैम अलर्ट**: कर्पूरमंजरी बहुत प्रसिद्ध है क्योंकि यह पूरी तरह ''प्राकृत'' भाषा में लिखी गई थी (संस्कृत में नहीं), इसे राजशेखर ने अपनी पत्नी के लिए लिखा था।', 2, 0, 9, 'History/Literature', 'Which of the following books was not written by Rajasekhara?', '✅ **Correct Logic**: ''Prabandhachintamani'' was written by the Jain scholar Merutunga in 1304 AD. The other three works belong to the eminent poet Rajasekhara.
💡 **Exam Fact**: Rajasekhara was the court poet of the Gurjara-Pratihara kings Mahendrapala I and Mahipala.
🧠 **Memory Tip**: Merutunga carries the ''Chintamani''.
🚫 **Scam Alert**: ''Karpuramanjari'' is a frequent trick question as it is the only play by Rajasekhara written entirely in Prakrit, not Sanskrit. But it IS his work.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('aeDhiDH_2u9pKRlqrFiUu', 'dPjxq4JIOG1tOL_YsyAiv', 'MS-DOS निम्नलिखित में से किस प्रकार के यूजर इंटरफेस वाला एक ऑपरेटिंग सिस्टम है?', '"[\"ग्राफिकल यूजर इंटरफेस (Graphical User Interface)\",\"स्पर्श-आधारित यूजर इंटरफेस (Touch-based User Interface)\",\"कमांड-आधारित इंटरफेस (Command-based Interface)\",\"आवाज (ध्वनि) आधारित इंटरफेस (Voice-based Interface)\"]"', '2.0', '✅ **सही तर्क**: MS-DOS (Microsoft Disk Operating System) एक CUI (Command-line User Interface) आधारित ऑपरेटिंग सिस्टम है, जहाँ काम करने के लिए टेक्स्ट कमांड टाइप करने पड़ते हैं।
💡 **परीक्षा तथ्य**: विंडोज (Windows) आने से पहले 1980 के दशक में कंप्यूटर पर MS-DOS ही सबसे लोकप्रिय OS था।
🧠 **स्मृति टिप**: DOS = काला स्क्रीन + सफेद टेक्स्ट (कमांड)।
🚫 **स्कैम अलर्ट**: ग्राफिकल यूजर इंटरफेस (GUI) विंडोज, मैक और एंड्रॉइड में होता है जहाँ माउस और आइकन का उपयोग होता है; DOS पूरी तरह कमांड-आधारित है।', 2, 0, 10, 'Information Technology', 'MS-DOS is an operating system with which of the following type of user interface?', '✅ **Correct Logic**: MS-DOS operates on a Command-Line User Interface (CUI) or Command-based interface, where users must type text commands to interact with the computer.
💡 **Exam Fact**: It was the dominant operating system for IBM PC compatible personal computers during the 1980s before the GUI-based Windows took over.
🧠 **Memory Tip**: DOS = The black screen where hackers type ''commands'' in movies.
🚫 **Scam Alert**: Graphical User Interface (GUI) involves clicking icons with a mouse, which DOS inherently lacks.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9skK2XkFjNdHAr5HaUYu9', 'SbZP3cerXo6UHBWYinaD7', 'सूची-I को सूची-II से सुमेलित कीजिए और सूचियों के नीचे दिए गए कूट का उपयोग करके सही उत्तर का चयन कीजिए:', '"[\"(i)-2, (ii)-1, (iii)-4, (iv)-3\",\"(i)-1, (ii)-2, (iii)-4, (iv)-3\",\"(i)-4, (ii)-1, (iii)-3, (iv)-2\",\"(i)-3, (ii)-4, (iii)-2, (iv)-1\"]"', '0.0', '✅ सही तर्क: दमोह में ''डायमंड सीमेंट्स'' (नरसिंहगढ़) है, भिण्ड में मालनपुर औद्योगिक क्षेत्र, सतना में मैहर सीमेंट और मुरैना में बानमोर सीमेंट फैक्ट्री स्थित है।
💡 परीक्षा तथ्य: बानमोर (मुरैना) मध्य प्रदेश का पहला सीमेंट कारखाना (1922) था।
🧠 स्मृति टिप: मुरैना = बानमोर (M-B), सतना = मैहर (S-M)।
🚫 स्कैम अलर्ट: मालनपुर को ग्वालियर का हिस्सा न समझें, यह राजनीतिक रूप से भिण्ड जिले में आता है।', 2, 0, 1, 'MP Geography/Economy', 'Match List-I with List-II and select the correct answer using the codes given below the lists:', '✅ Correct Logic: Damoh houses Diamond Cements at Narsinghgarh, Bhind has the Malanpur industrial area, Satna is famous for Maihar Cements, and Morena has Banmore.
💡 Exam Fact: Banmore in Morena was the very first cement factory established in MP in 1922.
🧠 Memory Tip: Satna matches with Maihar (Maa Sharda''s city is famous for cement).
🚫 Scam Alert: Malanpur is often confused with Gwalior due to proximity, but it strictly falls under Bhind district.', 60, 'matching', '[{"id":"(i)","label":"दमोह (Damoh)","match":"नरसिंहगढ़ (Narsinghgarh)","matchId":"2"},{"id":"(ii)","label":"भिण्ड (Bhind)","match":"मालनपुर (Malanpur)","matchId":"1"},{"id":"(iii)","label":"सतना (Satna)","match":"मैहर (Maihar)","matchId":"4"},{"id":"(iv)","label":"मुरैना (Morena)","match":"बानमोर (Banmore)","matchId":"3"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0pYfWIItRWL8xQEhxP8zW', 'SbZP3cerXo6UHBWYinaD7', 'सिंगरौली जिले के महान ऐलुमिनियम प्लांट के संबंध में निम्नलिखित कथनों के आधार पर नीचे दिए गए कूट से सही उत्तर का चयन कीजिए:
1. सिंगरौली जिले के बरगवां के निकट महान ऐलुमिनियम प्लांट अवस्थित है।
2. उत्पादन 2013 से प्रारंभ हुआ।
3. इसके कुल उत्पादन का 80 प्रतिशत निर्यात किया जाता है।
4. स्मेल्टिंग के लिए फ्रांसीसी तकनीकी का उपयोग किया जाता है।', '"[\"1, 2 एवं 3 सही हैं (1, 2 and 3 are correct)\",\"2, 3 एवं 4 सही हैं (2, 3 and 4 are correct)\",\"1, 2 एवं 4 सही हैं (1, 2 and 4 are correct)\",\"1, 2, 3 एवं 4 सही हैं (1, 2, 3 and 4 are correct)\"]"', '3.0', '✅ सही तर्क: हिंडाल्को का महान एल्युमिनियम प्रोजेक्ट सिंगरौली (बरगवां) में है। यह 2013 में शुरू हुआ था, इसमें AP36 (फ्रांसीसी) तकनीक का उपयोग होता है, और इसका एक बड़ा हिस्सा निर्यात किया जाता है।
💡 परीक्षा तथ्य: सिंगरौली को मध्य प्रदेश की ''ऊर्जा राजधानी'' कहा जाता है।
🧠 स्मृति टिप: महान एल्युमिनियम = हिंडाल्को = फ्रांसीसी तकनीक।
🚫 स्कैम अलर्ट: सभी कथन बहुत विशिष्ट हैं। ऐसे प्रश्नों में यदि तकनीक और स्थान सही हैं, तो अक्सर सभी कथन सही होते हैं।', 2, 0, 2, 'MP Economy', 'Based on the following statements regarding Mahan Aluminium plant in Singrauli district, select the correct answer from the codes given below:
1. Mahan Aluminium plant is located near Bargawan in Singrauli district.
2. Production started in 2013.
3. Eighty percent of its total production is exported.
4. French technology is used for smelting.', '✅ Correct Logic: Hindalco''s Mahan Aluminium project is situated in Bargawan (Singrauli). It started in 2013, uses AP36 smelting technology from France, and is heavily export-oriented.
💡 Exam Fact: Singrauli is known as the ''Energy Capital'' of Madhya Pradesh.
🧠 Memory Tip: Mahan = Huge production = French Tech (AP36).
🚫 Scam Alert: Highly specific multi-statement questions in MPPSC often have ''All are correct'' as the safest bet if the primary location and company are accurate.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('GemMPzPl1tyYUtIqYun_a', 'SbZP3cerXo6UHBWYinaD7', 'निम्नलिखित में से कौन मध्यप्रदेश के विशेष रूप से कमजोर जनजातीय समूहों (PVTG) के अंतर्गत नहीं आते हैं?', '"[\"सहरिया (Saharia)\",\"बैगा (Baiga)\",\"भारिया (Bharia)\",\"असुर (Asur)\"]"', '3.0', '✅ सही तर्क: मध्य प्रदेश में केवल 3 जनजातियों को PVTG (विशेष पिछड़ी जनजाति) का दर्जा प्राप्त है: बैगा, भारिया और सहरिया। असुर जनजाति मुख्य रूप से झारखंड में पाई जाती है।
💡 परीक्षा तथ्य: सहरिया ग्वालियर-चंबल में, भारिया पातालकोट में और बैगा पूर्वी मध्य प्रदेश में निवास करते हैं।
🧠 स्मृति टिप: MP के ''BBS'' (Baiga, Bharia, Saharia) विशेष हैं।
🚫 स्कैम अलर्ट: असुर एक प्राचीन जनजाति है, लेकिन इसका मध्य प्रदेश की PVTG सूची से कोई संबंध नहीं है।', 2, 0, 3, 'MP Tribes', 'Which one of the following is not one of the Particularly Vulnerable Tribal Groups (PVTG) of Madhya Pradesh?', '✅ Correct Logic: The Government of India recognizes only 3 tribes as PVTGs in Madhya Pradesh: Baiga, Bharia, and Saharia. Asur is primarily found in Jharkhand.
💡 Exam Fact: Bharia tribes are heavily concentrated in the geographically isolated Patalkot valley.
🧠 Memory Tip: Memorize the ''BBS'' trio (Baiga, Bharia, Saharia) for MP''s PVTGs.
🚫 Scam Alert: Do not get confused by ''Asur''; while it is a PVTG in India, it belongs to Jharkhand, not MP.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Ngqv1U_DCWCbwp71QqPYx', 'SbZP3cerXo6UHBWYinaD7', 'छिंदवाड़ा जिले के पातालकोट क्षेत्र में कौन-सी जनजाति का बाहुल्य है?', '"[\"भील (Bhil)\",\"भारिया (Bharia)\",\"खैरवार (Khairwar)\",\"उरांव (Oraon)\"]"', '1.0', '✅ सही तर्क: छिंदवाड़ा जिले का पातालकोट अपनी गहरी घाटी और वहाँ निवास करने वाली ''भारिया'' जनजाति के लिए विश्व प्रसिद्ध है।
💡 परीक्षा तथ्य: 1981 की जनगणना में पातालकोट के भारियाओं को ''जंगलों के भी जंगली'' कहा गया था।
🧠 स्मृति टिप: ''पाताल'' में भारी (भारिया) लोग रहते हैं।
🚫 स्कैम अलर्ट: भील मध्य प्रदेश की सबसे बड़ी जनजाति है, लेकिन वे मालवा-निमाड़ (पश्चिमी MP) में रहते हैं, न कि पातालकोट में।', 2, 0, 4, 'MP Tribes', 'Which is a dominant tribe in Patalkot area of Chhindwara district?', '✅ Correct Logic: The Patalkot valley in Chhindwara district is globally famous for its isolation and its dominant inhabitants, the ''Bharia'' tribe.
💡 Exam Fact: In the 1981 census, the Bharias of Patalkot were infamously referred to as ''Junglies of the Jungles''.
🧠 Memory Tip: Deep down in Patalkot (Patal/Underworld), the Bharias reside.
🚫 Scam Alert: Bhil is the largest tribe overall in MP, but their stronghold is the western part (Jhabua/Alirajpur), not Chhindwara.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('KeHhxViQkMlIFu1X9gMLz', 'SbZP3cerXo6UHBWYinaD7', 'पी.आर. श्रीजेश को अपने कैरियर में निम्नलिखित में से कौन-सा पुरस्कार नहीं मिला?', '"[\"अर्जुन पुरस्कार (Arjuna Award)\",\"ध्यान चन्द खेल रत्न पुरस्कार (Dyan Chand Khel Ratna Award)\",\"पद्म भूषण (Padma Bhushan)\",\"द्रोणाचार्य पुरस्कार (Dronacharya Award)\"]"', '3.0', '✅ सही तर्क: द्रोणाचार्य पुरस्कार केवल ''कोचों'' (प्रशिक्षकों) को दिया जाता है। पी.आर. श्रीजेश भारतीय हॉकी टीम के महान गोलकीपर (खिलाड़ी) रहे हैं, इसलिए उन्हें द्रोणाचार्य नहीं मिल सकता।
💡 परीक्षा तथ्य: श्रीजेश को मेजर ध्यानचंद खेल रत्न और वर्ल्ड गेम्स एथलीट ऑफ द ईयर जैसे प्रतिष्ठित पुरस्कार मिल चुके हैं।
🧠 स्मृति टिप: द्रोणाचार्य गुरु थे, श्रीजेश अभी खिलाड़ी हैं।
🚫 स्कैम अलर्ट: अर्जुन और खेल रत्न खिलाड़ियों को मिलते हैं। द्रोणाचार्य नाम देखते ही समझ जाएं कि यह खिलाड़ियों के लिए नहीं है।', 2, 0, 5, 'Sports/Current Affairs', 'Which of the following awards has not been received by P.R. Sreejesh during his career?', '✅ Correct Logic: The Dronacharya Award is exclusively given to sports coaches. P.R. Sreejesh is a legendary Indian hockey goalkeeper (a player), making him ineligible for a coaching award during his playing career.
💡 Exam Fact: He was instrumental in India winning back-to-back Olympic bronze medals in hockey.
🧠 Memory Tip: Dronacharya was a Guru (Coach); Sreejesh is a player.
🚫 Scam Alert: Don''t overthink his achievements; just knowing the criteria for the Dronacharya Award eliminates it immediately.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('pYsfMVoELe2OHHkmre4f9', 'SbZP3cerXo6UHBWYinaD7', 'किस संविधान संशोधन के द्वारा 6 से 14 वर्ष तक के बच्चों के लिए निःशुल्क एवं अनिवार्य शिक्षा के अधिकार को मौलिक (मूल) अधिकार बनाया गया?', '"[\"68वें संविधान संशोधन द्वारा (By 68th Amendment)\",\"85वें संविधान संशोधन द्वारा (By 85th Amendment)\",\"86वें संविधान संशोधन द्वारा (By 86th Amendment)\",\"87वें संविधान संशोधन द्वारा (By 87th Amendment)\"]"', '2.0', '✅ सही तर्क: 86वें संविधान संशोधन (2002) के द्वारा अनुच्छेद 21A जोड़ा गया, जिसने शिक्षा को एक मौलिक अधिकार बना दिया।
💡 परीक्षा तथ्य: इसी संशोधन के द्वारा 11वां मौलिक कर्तव्य (अनुच्छेद 51A) भी जोड़ा गया था, जो माता-पिता को बच्चों को पढ़ाने का निर्देश देता है।
🧠 स्मृति टिप: 8+6=14 (14 वर्ष तक के बच्चों के लिए शिक्षा)।
🚫 स्कैम अलर्ट: शिक्षा का अधिकार (RTE) अधिनियम 2009 में पारित हुआ था, लेकिन संविधान संशोधन 2002 (86वां) था।', 2, 0, 6, 'Polity', 'Which Constitutional Amendment has added Fundamental Right to Free and Compulsory Education of Children between the age of 6 to 14 years?', '✅ Correct Logic: The 86th Constitutional Amendment Act of 2002 inserted Article 21A, making free and compulsory education a Fundamental Right for children aged 6 to 14.
💡 Exam Fact: This same amendment also added the 11th Fundamental Duty for parents/guardians under Article 51A(k).
🧠 Memory Tip: 8 + 6 = 14 (Education up to 14 years).
🚫 Scam Alert: The RTE Act was enacted later in 2009, but the constitutional foundation was laid by the 86th Amendment in 2002.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('HZ6vBKd5w09GM-8jNvbS-', 'SbZP3cerXo6UHBWYinaD7', 'सूची-I को सूची-II से सुमेलित कीजिए और सूचियों के नीचे दिए गए कूट का उपयोग करके सही उत्तर का चयन कीजिए:', '"[\"(i)-3, (ii)-2, (iii)-1, (iv)-4\",\"(i)-4, (ii)-1, (iii)-2, (iv)-3\",\"(i)-2, (ii)-4, (iii)-3, (iv)-1\",\"(i)-4, (ii)-3, (iii)-2, (iv)-1\"]"', '3.0', '✅ सही तर्क: बेतवा ओरछा से होकर बहती है, ताप्ती मुलताई (बैतूल) से निकलती है, क्षिप्रा के तट पर उज्जैन बसा है, और वैनगंगा बालाघाट से गुजरती है।
💡 परीक्षा तथ्य: उज्जैन में क्षिप्रा नदी के तट पर हर 12 साल में सिंहस्थ कुंभ लगता है।
🧠 स्मृति टिप: क्षिप्रा = उज्जैन का महाकाल। ताप्ती = मुलताई का ताप।
🚫 स्कैम अलर्ट: वैनगंगा को गंगा न समझें, यह दक्षिण की ओर बहने वाली गोदावरी अपवाह तंत्र की नदी है जो बालाघाट में प्रमुख है।', 2, 0, 7, 'MP Geography', 'Match List-I with List-II and select the correct answer using the codes given below the lists:', '✅ Correct Logic: Orchha is situated on the Betwa river, Tapti originates from Multai, Ujjain is famously on the banks of Kshipra, and Wainganga flows through Balaghat.
💡 Exam Fact: The Simhastha Kumbh Mela is held on the banks of the Kshipra river in Ujjain every 12 years.
🧠 Memory Tip: Kshipra matches with Ujjain instantly. Finding (iii)-2 directly narrows down the options.
🚫 Scam Alert: Wainganga is a south-flowing river part of the Godavari basin, do not confuse its route with the northern plains.', 60, 'matching', '[{"id":"(i)","label":"बेतवा (Betwa)","match":"ओरछा (Orchha)","matchId":"4"},{"id":"(ii)","label":"ताप्ती/तापी (Tapti/Tapi)","match":"मुलताई (Multai)","matchId":"3"},{"id":"(iii)","label":"क्षिप्रा (Kshipra)","match":"उज्जैन (Ujjain)","matchId":"2"},{"id":"(iv)","label":"वैनगंगा (Wainganga)","match":"बालाघाट (Balaghat)","matchId":"1"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Ih1yVpOxdyQg_K-dnC-Jd', 'SbZP3cerXo6UHBWYinaD7', 'मध्यप्रदेश की जलवायु के संबंध में निम्नलिखित कथनों को पढ़िए और नीचे दिए गए कूट से सही उत्तर का चयन कीजिए:
1. प्रदेश में अधिकांश वर्षा मानसून से होती है。
2. शीतकाल में वायु की गति, ग्रीष्मकाल एवं वर्षा ऋतु की अपेक्षा तीव्र होती है。
3. प्रदेश में मानसूनी वर्षा के वितरण पर समुद्र से दूरी का भी प्रभाव पड़ता है。
4. पचमढ़ी में ग्रीष्मकाल में तापमान समुद्र तल से ऊँचाई से संबंधित है।', '"[\"1, 2 एवं 3 सही हैं (1, 2 and 3 are correct)\",\"2, 3 एवं 4 सही हैं (2, 3 and 4 are correct)\",\"1, 3 एवं 4 सही हैं (1, 3 and 4 are correct)\",\"1, 2, 3 एवं 4 सही हैं (1, 2, 3 and 4 are correct)\"]"', '2.0', '✅ सही तर्क: कथन 2 गलत है। शीतकाल (सर्दियों) में हवा की गति ग्रीष्मकाल (गर्मियों - जब लू और आंधियां चलती हैं) की तुलना में धीमी होती है। 1, 3 और 4 भौगोलिक रूप से बिल्कुल सत्य हैं।
💡 परीक्षा तथ्य: पचमढ़ी मध्य प्रदेश का एकमात्र हिल स्टेशन है, ऊँचाई के कारण यहाँ तापमान कम रहता है (Normal Lapse Rate)।
🧠 स्मृति टिप: गर्मियों की आंधी (तेज हवा) > सर्दियों की शांत हवा।
🚫 स्कैम अलर्ट: मानसून और समुद्र की दूरी का सीधा संबंध है (पश्चिमी MP में कम बारिश होती है), इसे गलत न समझें।', 2, 0, 8, 'MP Geography', 'Read the following statements regarding the climate of Madhya Pradesh and select the correct answer from the codes given below:
1. Most of the rainfall in the state is received from the monsoon.
2. Wind speed during winters is faster than in summer and rainy seasons.
3. Distance from sea also affects the distribution of monsoon rains in the state.
4. Summer temperature in Pachmarhi is related to the altitude above sea level.', '✅ Correct Logic: Statement 2 is incorrect. Wind speeds in MP are generally much higher during the turbulent summer (dust storms/Loo) and monsoon seasons than in the calm winters. Statements 1, 3, and 4 are true.
💡 Exam Fact: Pachmarhi remains cool in summer due to the ''Normal Lapse Rate'' where temperature drops with an increase in altitude.
🧠 Memory Tip: Summer brings fierce dust storms; winters are calm.
🚫 Scam Alert: The ''distance from the sea'' concept is a core geographical principle; the further a place is from the coast, the less rainfall it generally receives from the monsoon branch.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('gvQftYiub5pIWnqFf6KFr', 'SbZP3cerXo6UHBWYinaD7', 'सूची-I को सूची-II से सुमेलित कीजिए और सूचियों के नीचे दिए गए कूट का उपयोग करके सही उत्तर का चयन कीजिए:', '"[\"(i)-2, (ii)-1, (iii)-4, (iv)-3\",\"(i)-3, (ii)-4, (iii)-1, (iv)-2\",\"(i)-4, (ii)-3, (iii)-2, (iv)-1\",\"(i)-2, (ii)-4, (iii)-1, (iv)-3\"]"', '1.0', '✅ सही तर्क: ताँबा बैहर (बालाघाट) में मिलता है, हीरा पन्ना की हिनोता खदान में, स्लेट उत्पादन में मंदसौर देश में प्रथम है, और बॉक्साइट का खनन शहडोल/अमरकंटक बेल्ट में होता है।
💡 परीक्षा तथ्य: मंदसौर भारत का एकमात्र स्लेट उत्पादक जिला है।
🧠 स्मृति टिप: डायमंड = हिनोता खदान। स्लेट = मंदसौर।
🚫 स्कैम अलर्ट: तांबे के लिए ''मलजखंड'' ज्यादा मशहूर है, लेकिन वह ''बैहर'' तहसील के अंतर्गत ही आता है।', 2, 0, 9, 'MP Geography/Minerals', 'Match List-I with List-II and select the correct answer using the codes given below the lists:', '✅ Correct Logic: Copper is found in Baihar (Balaghat), Diamond in Hinota (Panna), Slate is exclusively produced in Mandsaur, and Bauxite is mined in Shahdol.
💡 Exam Fact: Mandsaur is the only district in India known for slate pencil production.
🧠 Memory Tip: Diamond = Hinota pipe. Slate = Mandsaur.
🚫 Scam Alert: Malajkhand is the famous copper mine, but it is located within the Baihar tehsil; don''t get thrown off by the tehsil name.', 60, 'matching', '[{"id":"(i)","label":"ताँबा (Copper)","match":"बैहर (Baihar)","matchId":"3"},{"id":"(ii)","label":"हीरा (Diamond)","match":"हिनोता (Hinota)","matchId":"4"},{"id":"(iii)","label":"स्लेट (Slate)","match":"मंदसौर (Mandsaur)","matchId":"1"},{"id":"(iv)","label":"बॉक्साइट (Bauxite)","match":"शहडोल (Shahdol)","matchId":"2"}]', NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bYvfOXucrEDhA12vtkMA2', 'SbZP3cerXo6UHBWYinaD7', '"एक जिला एक उत्पाद" योजना के तहत छतरपुर का प्रमुख उत्पाद क्या है?', '"[\"टमाटर (Tomato)\",\"कपास (Cotton)\",\"लकड़ी के फर्नीचर (Wooden furniture)\",\"हस्तकरघा वस्त्र (Handloom textiles)\"]"', '2.0', '✅ सही तर्क: ODOP (एक जिला एक उत्पाद) के तहत छतरपुर जिले को ''लकड़ी के फर्नीचर'' (Wooden Furniture) के लिए चुना गया है।
💡 परीक्षा तथ्य: छतरपुर अपनी उत्कृष्ट काष्ठ कला और सागौन के फर्नीचर के लिए जाना जाता है।
🧠 स्मृति टिप: ''छत'' (Chhatarpur) के नीचे ''लकड़ी का फर्नीचर''।
🚫 स्कैम अलर्ट: टमाटर अशोकनगर/दमोह से जुड़ा है, और हस्तकरघा चंदेरी/महेश्वर (अशोकनगर/खरगोन) से।', 2, 0, 10, 'MP Economy/Current Affairs', 'What is the key product under the "One District One Product" initiative for Chhatarpur?', '✅ Correct Logic: Under the One District One Product (ODOP) scheme, Chhatarpur has been designated for ''Wooden furniture'' due to its rich timber resources and craftsmanship.
💡 Exam Fact: The region has a strong traditional base of carpenters working with high-quality Teakwood (Sagwan).
🧠 Memory Tip: A good ''Chhat'' (Roof/Chhatarpur) needs good ''Wooden furniture'' below it.
🚫 Scam Alert: Handloom is famous in MP but specifically tied to Maheshwar and Chanderi, not Chhatarpur.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('YmAmAanDD6BqX88Qxh5Rt', 'c4rI0m0FoPZMW32N6vN3w', '''आल्हाखण्ड'' के लेखक कौन हैं?', '"[\"चन्दबरदाई (Chand Bardai)\",\"राजशेखर (Rajasekhara)\",\"परमार्दिदेव (Parmardidev)\",\"जगनिक (Jagnik)\"]"', '3.0', '✅ सही तर्क: ''आल्हाखण्ड'' की रचना लोककवि जगनिक ने की थी। यह परमाल रासो का एक हिस्सा है, जिसमें बुंदेलखंड के वीर योद्धाओं आल्हा और ऊदल की 52 लड़ाइयों का वर्णन है।
💡 परीक्षा तथ्य: जगनिक चंदेल शासक परमार्दिदेव (परमाल) के दरबारी कवि थे।
🧠 स्मृति टिप: आल्हा ने ''जग'' (Jagnik) जीता।
🚫 स्कैम अलर्ट: चन्दबरदाई ने ''पृथ्वीराज रासो'' लिखा था। परमार्दिदेव राजा थे, कवि नहीं।', 2, 0, 1, 'MP History/Literature', 'Who is the author of ''Alhakhand''?', '✅ Correct Logic: ''Alhakhand'' was composed by Jagnik. It is an epic poem describing the 52 battles fought by the brave Bundeli warriors Alha and Udal.
💡 Exam Fact: Jagnik was the court poet of the Chandela King Parmardidev (Parmal).
🧠 Memory Tip: The legendary Alha is known throughout the ''Jag'' (World/Jagnik).
🚫 Scam Alert: Chand Bardai is famous for Prithviraj Raso. Do not confuse the Rajput epics.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('UafdGZfTGOnn4QDO1ZBgm', 'c4rI0m0FoPZMW32N6vN3w', 'निम्नलिखित में से कौन-सी पुस्तक केशवदास द्वारा नहीं लिखी गई है?', '"[\"रामचन्द्रिका (Ramchandrika)\",\"कविप्रिया (Kavipriya)\",\"रतन बावनी (Ratan Bavani)\",\"राम रसायन (Ram Rasayan)\"]"', '3.0', '✅ सही तर्क: ''राम रसायन'' पद्माकर की रचना है। रामचन्द्रिका, कविप्रिया, और रतन बावनी ओरछा के प्रसिद्ध रीतिकालीन कवि आचार्य केशवदास की रचनाएं हैं।
💡 परीक्षा तथ्य: केशवदास को ''कठिन काव्य का प्रेत'' कहा जाता है।
🧠 स्मृति टिप: ''रसायन'' का ज्ञान ''पद्माकर'' को था, केशव को नहीं।
🚫 स्कैम अलर्ट: रामचन्द्रिका केशवदास की सबसे प्रसिद्ध रचना है, ''राम'' शब्द देखकर इसे ''राम रसायन'' से न जोड़ें।', 2, 0, 2, 'MP Literature', 'Which of the following books was not written by Keshavdas?', '✅ Correct Logic: ''Ram Rasayan'' is authored by the poet Padmakar. Ramchandrika, Kavipriya, and Ratan Bavani are the classic works of Acharya Keshavdas of Orchha.
💡 Exam Fact: Keshavdas is highly revered in Hindi literature and is often called the ''Ghost of difficult poetry'' due to his complex linguistic style.
🧠 Memory Tip: ''Rasayan'' (Chemical) belongs to Padmakar.
🚫 Scam Alert: Do not assume all books starting with ''Ram'' belong to Keshavdas. He wrote Ramchandrika, but Ram Rasayan is Padmakar''s.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('tzVF_vFZSrInI01E8ayAa', 'c4rI0m0FoPZMW32N6vN3w', 'मध्यप्रदेश में मातंगेश्वर मंदिर कहाँ स्थित है?', '"[\"माण्डू (Mandu)\",\"चित्रकूट (Chitrakoot)\",\"त्रिपुरी (Tripuri)\",\"खजुराहो (Khajuraho)\"]"', '3.0', '✅ सही तर्क: मातंगेश्वर मंदिर खजुराहो में स्थित है। यह शिव को समर्पित है और खजुराहो के उन चंद मंदिरों में से एक है जहाँ आज भी सक्रिय पूजा होती है।
💡 परीक्षा तथ्य: इसका निर्माण चंदेल शासक यशोवर्मन ने करवाया था। इसमें 8 फीट ऊंचा शिवलिंग है।
🧠 स्मृति टिप: ''खजूर'' के पेड़ के पास ''मातंग'' (हाथी/शिव)।
🚫 स्कैम अलर्ट: माण्डू महलों के लिए जाना जाता है, जबकि खजुराहो अपने प्राचीन नागर शैली के मंदिरों के लिए।', 2, 0, 3, 'MP Culture/Tourism', 'Where is the Matangeshwar temple located in Madhya Pradesh?', '✅ Correct Logic: The Matangeshwar Temple is located in Khajuraho. Dedicated to Lord Shiva, it is one of the few temples in the complex that is still actively used for daily worship.
💡 Exam Fact: It was built by the Chandela king Yashovarman and features a massive 8-foot-tall Shiva Lingam.
🧠 Memory Tip: Matangeshwar = The living Shiva temple of Khajuraho.
🚫 Scam Alert: Mandu is famous for Afghan architecture (palaces/tombs), whereas Khajuraho is the hub for ancient Hindu temple architecture.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('nMQA-xxl2Pp76QRwrqDyi', 'c4rI0m0FoPZMW32N6vN3w', 'निम्नलिखित में से कौन-सी मानव शरीर में सबसे छोटी मांसपेशी है?', '"[\"बाइसेप (Bicep)\",\"सार्टोरियस (Sartorius)\",\"स्टेपीडियस (Stapedius)\",\"ट्राइसेप (Tricep)\"]"', '2.0', '✅ सही तर्क: स्टेपीडियस (Stapedius) मानव शरीर की सबसे छोटी मांसपेशी है, जो मध्य कान में पाई जाती है और ''स्टेपीज़'' (सबसे छोटी हड्डी) को सहारा देती है।
💡 परीक्षा तथ्य: सार्टोरियस (Sartorius) मानव शरीर की सबसे लंबी मांसपेशी है, जो जांघ में होती है।
🧠 स्मृति टिप: सबसे छोटी हड्डी (Stapes) = सबसे छोटी मांसपेशी (Stapedius)।
🚫 स्कैम अलर्ट: बाइसेप और ट्राइसेप हाथ की बड़ी मांसपेशियां हैं, ये उत्तर नहीं हो सकतीं।', 2, 0, 4, 'Biology', 'Which of the following is the smallest muscle in the human body?', '✅ Correct Logic: The Stapedius is the smallest skeletal muscle in the human body, located in the middle ear. Its function is to stabilize the smallest bone, the stapes.
💡 Exam Fact: In contrast, the Sartorius muscle (in the thigh) is the longest muscle in the human body.
🧠 Memory Tip: Smallest Bone (Stapes) connects to Smallest Muscle (Stapedius).
🚫 Scam Alert: Sartorius might tempt you if you misread ''smallest'' for ''longest''. Read carefully.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('13cotBZZ1Hu1SNT73JA9-', 'c4rI0m0FoPZMW32N6vN3w', 'मध्यप्रदेश के किस क्षेत्र में "मनसुखा" लोक नाट्य प्रचलित है?', '"[\"पूर्वी निमाड़ (Eastern Nimar)\",\"मालवा (Malwa)\",\"बघेलखण्ड (Baghelkhand)\",\"पश्चिमी निमाड़ (Western Nimar)\"]"', '2.0', '✅ सही तर्क: ''मनसुखा'' बघेलखण्ड क्षेत्र का एक प्रसिद्ध लोक नाट्य है। यह हास्य पर आधारित है और अक्सर रासलीला के विदूषक ''मनसुखा'' से प्रेरित होता है।
💡 परीक्षा तथ्य: बघेलखण्ड के अन्य प्रमुख लोक नाट्य ''छाहुर'' और ''लकड़बग्घा'' हैं।
🧠 स्मृति टिप: बघेल (बाघ) के सामने ''सुखा'' (मनसुखा) पड़ गया।
🚫 स्कैम अलर्ट: निमाड़ का लोक नाट्य ''गम्मत'' है और मालवा का ''माच''।', 2, 0, 5, 'MP Art & Culture', 'In which area of Madhya Pradesh is "Mansukha" folk drama prevalent?', '✅ Correct Logic: ''Mansukha'' is a popular, humor-based folk drama prevalent in the Baghelkhand region of Madhya Pradesh, often featuring a jester-like character.
💡 Exam Fact: Other notable folk dramas of Baghelkhand include Chhahur and Lakadbaggha.
🧠 Memory Tip: A Tiger (Baghel) will dry out (Sukha) anyone''s courage.
🚫 Scam Alert: Gammat is the traditional drama of Nimar, and Maach belongs to Malwa. Mansukha is uniquely Baghelkhandi.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('TfZm15yWmeSy62SOc3led', 'c4rI0m0FoPZMW32N6vN3w', '''सत्कार्यवाद'' किस दर्शन का मुख्य आधार है?', '"[\"वैशेषिक दर्शन (Vaisheshika philosophy)\",\"मीमांसा दर्शन (Mimamsa philosophy)\",\"सांख्य दर्शन (Sankhya philosophy)\",\"न्याय दर्शन (Nyaya philosophy)\"]"', '2.0', '✅ सही तर्क: सत्कार्यवाद ''सांख्य दर्शन'' (Sankhya) का मूल सिद्धांत है। इसके अनुसार ''कार्य अपने उत्पन्न होने से पहले कारण में विद्यमान रहता है'' (Effect pre-exists in its cause)।
💡 परीक्षा तथ्य: सांख्य दर्शन के प्रवर्तक महर्षि कपिल माने जाते हैं।
🧠 स्मृति टिप: ''S'' for Satkaryavada, ''S'' for Sankhya.
🚫 स्कैम अलर्ट: न्याय दर्शन ''असत्कार्यवाद'' (आरंभवाद) में विश्वास करता है, जो सत्कार्यवाद का ठीक उल्टा है।', 2, 0, 6, 'History/Indian Philosophy', '''Satkaryavada'' is the main basis of which philosophy?', '✅ Correct Logic: Satkaryavada is the core theory of causation in the ''Sankhya'' school of Indian philosophy, which states that the effect already pre-exists in its material cause before its creation.
💡 Exam Fact: Sage Kapila is universally credited as the founder of the Sankhya philosophy.
🧠 Memory Tip: Match the S: Satkaryavada = Sankhya.
🚫 Scam Alert: Nyaya and Vaisheshika follow ''Asatkaryavada'' (the theory that the effect is an entirely new creation), which is the exact opposite.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('QplzjHGnjTj0yA6KvUN0c', 'c4rI0m0FoPZMW32N6vN3w', 'किस आश्रम में रहते हुए, मनुष्य को पंच महायज्ञों का अनुष्ठान करना पड़ता था?', '"[\"ब्रह्मचर्य आश्रम (Brahmacharya Ashram)\",\"गृहस्थ आश्रम (Grihastha Ashram)\",\"वानप्रस्थ आश्रम (Vanaprastha Ashram)\",\"संन्यास आश्रम (Sanyas Ashram)\"]"', '1.0', '✅ सही तर्क: वैदिक जीवन व्यवस्था में ''गृहस्थ आश्रम'' के दौरान एक व्यक्ति को पांच दैनिक महायज्ञ (ब्रह्म, देव, पितृ, वैश्वदेव और अतिथि यज्ञ) करने का विधान था।
💡 परीक्षा तथ्य: गृहस्थ आश्रम (25-50 वर्ष) को सभी चार आश्रमों में श्रेष्ठ माना गया है क्योंकि यह समाज का भरण-पोषण करता है।
🧠 स्मृति टिप: यज्ञ करने के लिए ''गृह'' (घर) और पत्नी का होना आवश्यक था।
🚫 स्कैम अलर्ट: संन्यास या वानप्रस्थ में कर्मकाण्ड छूट जाते हैं; यज्ञ केवल गृहस्थ का कर्तव्य है।', 2, 0, 7, 'Ancient History/Culture', 'While living in which Ashram did a person have to perform the rituals of Panch Mahayagya?', '✅ Correct Logic: In the Vedic Ashrama system, a person in the ''Grihastha Ashram'' (householder stage) was strictly mandated to perform the five daily great sacrifices (Panch Mahayagya).
💡 Exam Fact: Grihastha is considered the highest of the four Ashramas because it financially and physically supports the other three.
🧠 Memory Tip: You need a house (Griha) and a family to perform sacrifices and feed guests.
🚫 Scam Alert: Ascetics in Sanyas or Vanaprastha renounce fire and rituals; they meditate instead.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('x9aK7WK5-6aeVW26U0sj4', 'c4rI0m0FoPZMW32N6vN3w', 'तमिलनाडु में वैष्णव धर्म का प्रचार अलवार संतों द्वारा किया गया। अलवार संतों में एकमात्र महिला साध्वी कौन थी?', '"[\"नाम्मालवार (Nammalvar)\",\"पोयगई (Poigai)\",\"थिरुमंगई (Thirumangayi)\",\"अण्डाल (Andal)\"]"', '3.0', '✅ सही तर्क: 12 अलवार संतों (जो भगवान विष्णु के भक्त थे) में ''अण्डाल'' (Andal) एकमात्र महिला संत थीं।
💡 परीक्षा तथ्य: अण्डाल को ''दक्षिण की मीरा'' भी कहा जाता है, उनके गीत ''तिरुप्पावै'' बहुत प्रसिद्ध हैं।
🧠 स्मृति टिप: अण्डाल = अलवारों की अकेली देवी।
🚫 स्कैम अलर्ट: अगर ''नयनार'' (शिव भक्त) संतों की बात होती, तो प्रसिद्ध महिला संत ''करैक्कल अम्मैयर'' (Karaikkal Ammaiyar) होतीं।', 2, 0, 8, 'History/Art & Culture', 'Vaishnavism was propagated by Alvar saints of Tamil Nadu. Who was the only female Sadhvi among the Alvar saints?', '✅ Correct Logic: Among the 12 Alvar saints of South India who propagated Vaishnavism, ''Andal'' was the sole female saint.
💡 Exam Fact: Because of her immense devotion to Lord Krishna/Vishnu, she is affectionately known as the ''Meera of the South''.
🧠 Memory Tip: Andal = The Alvar Angel.
🚫 Scam Alert: Do not confuse Alvars (Vishnu devotees) with Nayanars (Shiva devotees). The female Nayanar saint is Karaikkal Ammaiyar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('yN6ukxNC94aS-ps_xJ805', 'c4rI0m0FoPZMW32N6vN3w', 'वर्ष 2021-22 में, इनमें से कौन-सा राज्य देश में क्षेत्रफल में द्वितीय और दालों के उत्पादन में प्रथम स्थान पर था?', '"[\"महाराष्ट्र (Maharashtra)\",\"राजस्थान (Rajasthan)\",\"गुजरात (Gujarat)\",\"मध्यप्रदेश (Madhya Pradesh)\"]"', '3.0', '✅ सही तर्क: मध्य प्रदेश भौगोलिक क्षेत्रफल के लिहाज से भारत का दूसरा सबसे बड़ा राज्य है (राजस्थान के बाद) और यह दालों (Pulses) के उत्पादन में लगातार प्रथम स्थान पर है।
💡 परीक्षा तथ्य: मध्य प्रदेश को सोयाबीन स्टेट के साथ-साथ ''दलहन स्टेट'' भी कहा जाता है।
🧠 स्मृति टिप: मध्य (Center) में सबसे ज्यादा ''दाल'' पकती है।
🚫 स्कैम अलर्ट: राजस्थान क्षेत्रफल में प्रथम है लेकिन दलहन उत्पादन में प्रथम मध्य प्रदेश है।', 2, 0, 9, 'Geography/Economy', 'During the year 2021-22, which of these states was ranked second in area and first in production of pulses in the country?', '✅ Correct Logic: Madhya Pradesh is the second-largest state in India by geographical area (after Rajasthan) and stands first in the total production of pulses.
💡 Exam Fact: Besides pulses, MP is also the leading producer of soybeans and gram (chana) in the country.
🧠 Memory Tip: MP = Master of Pulses. Area-wise it is #2.
🚫 Scam Alert: Rajasthan is #1 in area, but the dual condition (#2 in area + #1 in pulses) uniquely points to Madhya Pradesh.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('lC-BEs099gsPEO6lDMkAc', 'c4rI0m0FoPZMW32N6vN3w', 'प्रत्येक वेद के लिए अलग-अलग ब्राह्मण ग्रंथ लिखे गए। यजुर्वेद से संबंधित ब्राह्मण ग्रंथ है:', '"[\"गोपथ (Gopatha)\",\"पञ्चविश तथा जैमिनीय (Panchvish and Jaiminiya)\",\"ऐतरेय तथा कौषीतकि (Aitareya and Kaushitaki)\",\"तैत्तिरीय तथा शतपथ (Taittiriya and Shatapatha)\"]"', '3.0', '✅ सही तर्क: ''शतपथ'' (शुक्ल यजुर्वेद) और ''तैत्तिरीय'' (कृष्ण यजुर्वेद) ब्राह्मण ग्रंथ यजुर्वेद से संबंधित हैं।
💡 परीक्षा तथ्य: ऐतरेय और कौषीतकि ऋग्वेद के हैं; गोपथ अथर्ववेद का है; पंचविश सामवेद का है।
🧠 स्मृति टिप: यजुर्वेद में यज्ञ की विधि है, और यज्ञ में ''सौ'' (शतपथ) आहुतियां दी जाती हैं।
🚫 स्कैम अलर्ट: गोपथ एकमात्र ब्राह्मण ग्रंथ है जो अथर्ववेद से जुड़ा है, इसे यजुर्वेद से न मिलाएं।', 2, 0, 10, 'History/Ancient India', 'Separate Brahmin texts were written for each Veda. The Brahmin text related to Yajurveda is:', '✅ Correct Logic: The ''Shatapatha Brahmana'' (White Yajurveda) and ''Taittiriya Brahmana'' (Black Yajurveda) are the key Brahmin texts associated with the Yajurveda.
💡 Exam Fact: Aitareya belongs to Rigveda, Panchvish to Samaveda, and Gopatha to Atharvaveda.
🧠 Memory Tip: Yajurveda is for rituals; rituals require a ''Hundred'' (Shata) paths.
🚫 Scam Alert: Memorize the mappings. Gopatha is highly asked because it is the only Brahmana for the Atharvaveda.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5uey2S4NsSTf9zqHP84xe', 'Phb5GpZkUqYbaQM-2nPjG', '''आल्हाखण्ड'' के लेखक कौन हैं?', '"[\"चन्दबरदाई (Chand Bardai)\",\"राजशेखर (Rajasekhara)\",\"परमार्दिदेव (Parmardidev)\",\"जगनिक (Jagnik)\"]"', '3.0', '✅ सही तर्क: ''आल्हाखण्ड'' की रचना लोककवि जगनिक ने की थी। यह परमाल रासो का एक हिस्सा है, जिसमें बुंदेलखंड के वीर योद्धाओं आल्हा और ऊदल की 52 लड़ाइयों का वर्णन है।
💡 परीक्षा तथ्य: जगनिक चंदेल शासक परमार्दिदेव (परमाल) के दरबारी कवि थे।
🧠 स्मृति टिप: आल्हा ने ''जग'' (Jagnik) जीता।
🚫 स्कैम अलर्ट: चन्दबरदाई ने ''पृथ्वीराज रासो'' लिखा था। परमार्दिदेव राजा थे, कवि नहीं।', 2, 0, 1, 'MP History/Literature', 'Who is the author of ''Alhakhand''?', '✅ Correct Logic: ''Alhakhand'' was composed by Jagnik. It is an epic poem describing the 52 battles fought by the brave Bundeli warriors Alha and Udal.
💡 Exam Fact: Jagnik was the court poet of the Chandela King Parmardidev (Parmal).
🧠 Memory Tip: The legendary Alha is known throughout the ''Jag'' (World/Jagnik).
🚫 Scam Alert: Chand Bardai is famous for Prithviraj Raso. Do not confuse the Rajput epics.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('93DtWXtmMnTWbpNdXD3vX', 'Phb5GpZkUqYbaQM-2nPjG', 'निम्नलिखित में से कौन-सी पुस्तक केशवदास द्वारा नहीं लिखी गई है?', '"[\"रामचन्द्रिका (Ramchandrika)\",\"कविप्रिया (Kavipriya)\",\"रतन बावनी (Ratan Bavani)\",\"राम रसायन (Ram Rasayan)\"]"', '3.0', '✅ सही तर्क: ''राम रसायन'' पद्माकर की रचना है। रामचन्द्रिका, कविप्रिया, और रतन बावनी ओरछा के प्रसिद्ध रीतिकालीन कवि आचार्य केशवदास की रचनाएं हैं।
💡 परीक्षा तथ्य: केशवदास को ''कठिन काव्य का प्रेत'' कहा जाता है।
🧠 स्मृति टिप: ''रसायन'' का ज्ञान ''पद्माकर'' को था, केशव को नहीं।
🚫 स्कैम अलर्ट: रामचन्द्रिका केशवदास की सबसे प्रसिद्ध रचना है, ''राम'' शब्द देखकर इसे ''राम रसायन'' से न जोड़ें।', 2, 0, 2, 'MP Literature', 'Which of the following books was not written by Keshavdas?', '✅ Correct Logic: ''Ram Rasayan'' is authored by the poet Padmakar. Ramchandrika, Kavipriya, and Ratan Bavani are the classic works of Acharya Keshavdas of Orchha.
💡 Exam Fact: Keshavdas is highly revered in Hindi literature and is often called the ''Ghost of difficult poetry'' due to his complex linguistic style.
🧠 Memory Tip: ''Rasayan'' (Chemical) belongs to Padmakar.
🚫 Scam Alert: Do not assume all books starting with ''Ram'' belong to Keshavdas. He wrote Ramchandrika, but Ram Rasayan is Padmakar''s.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('uZmEUb6i7ua8eXmvo9elv', 'Phb5GpZkUqYbaQM-2nPjG', 'मध्यप्रदेश में मातंगेश्वर मंदिर कहाँ स्थित है?', '"[\"माण्डू (Mandu)\",\"चित्रकूट (Chitrakoot)\",\"त्रिपुरी (Tripuri)\",\"खजुराहो (Khajuraho)\"]"', '3.0', '✅ सही तर्क: मातंगेश्वर मंदिर खजुराहो में स्थित है। यह शिव को समर्पित है और खजुराहो के उन चंद मंदिरों में से एक है जहाँ आज भी सक्रिय पूजा होती है।
💡 परीक्षा तथ्य: इसका निर्माण चंदेल शासक यशोवर्मन ने करवाया था। इसमें 8 फीट ऊंचा शिवलिंग है।
🧠 स्मृति टिप: ''खजूर'' के पेड़ के पास ''मातंग'' (हाथी/शिव)।
🚫 स्कैम अलर्ट: माण्डू महलों के लिए जाना जाता है, जबकि खजुराहो अपने प्राचीन नागर शैली के मंदिरों के लिए।', 2, 0, 3, 'MP Culture/Tourism', 'Where is the Matangeshwar temple located in Madhya Pradesh?', '✅ Correct Logic: The Matangeshwar Temple is located in Khajuraho. Dedicated to Lord Shiva, it is one of the few temples in the complex that is still actively used for daily worship.
💡 Exam Fact: It was built by the Chandela king Yashovarman and features a massive 8-foot-tall Shiva Lingam.
🧠 Memory Tip: Matangeshwar = The living Shiva temple of Khajuraho.
🚫 Scam Alert: Mandu is famous for Afghan architecture (palaces/tombs), whereas Khajuraho is the hub for ancient Hindu temple architecture.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Q5YKQvN5jBSRTXb4jofSs', 'Phb5GpZkUqYbaQM-2nPjG', 'निम्नलिखित में से कौन-सी मानव शरीर में सबसे छोटी मांसपेशी है?', '"[\"बाइसेप (Bicep)\",\"सार्टोरियस (Sartorius)\",\"स्टेपीडियस (Stapedius)\",\"ट्राइसेप (Tricep)\"]"', '2.0', '✅ सही तर्क: स्टेपीडियस (Stapedius) मानव शरीर की सबसे छोटी मांसपेशी है, जो मध्य कान में पाई जाती है और ''स्टेपीज़'' (सबसे छोटी हड्डी) को सहारा देती है।
💡 परीक्षा तथ्य: सार्टोरियस (Sartorius) मानव शरीर की सबसे लंबी मांसपेशी है, जो जांघ में होती है।
🧠 स्मृति टिप: सबसे छोटी हड्डी (Stapes) = सबसे छोटी मांसपेशी (Stapedius)।
🚫 स्कैम अलर्ट: बाइसेप और ट्राइसेप हाथ की बड़ी मांसपेशियां हैं, ये उत्तर नहीं हो सकतीं।', 2, 0, 4, 'Biology', 'Which of the following is the smallest muscle in the human body?', '✅ Correct Logic: The Stapedius is the smallest skeletal muscle in the human body, located in the middle ear. Its function is to stabilize the smallest bone, the stapes.
💡 Exam Fact: In contrast, the Sartorius muscle (in the thigh) is the longest muscle in the human body.
🧠 Memory Tip: Smallest Bone (Stapes) connects to Smallest Muscle (Stapedius).
🚫 Scam Alert: Sartorius might tempt you if you misread ''smallest'' for ''longest''. Read carefully.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4FUN_eCfAu9aCeywffwmr', 'Phb5GpZkUqYbaQM-2nPjG', 'मध्यप्रदेश के किस क्षेत्र में "मनसुखा" लोक नाट्य प्रचलित है?', '"[\"पूर्वी निमाड़ (Eastern Nimar)\",\"मालवा (Malwa)\",\"बघेलखण्ड (Baghelkhand)\",\"पश्चिमी निमाड़ (Western Nimar)\"]"', '2.0', '✅ सही तर्क: ''मनसुखा'' बघेलखण्ड क्षेत्र का एक प्रसिद्ध लोक नाट्य है। यह हास्य पर आधारित है और अक्सर रासलीला के विदूषक ''मनसुखा'' से प्रेरित होता है।
💡 परीक्षा तथ्य: बघेलखण्ड के अन्य प्रमुख लोक नाट्य ''छाहुर'' और ''लकड़बग्घा'' हैं।
🧠 स्मृति टिप: बघेल (बाघ) के सामने ''सुखा'' (मनसुखा) पड़ गया।
🚫 स्कैम अलर्ट: निमाड़ का लोक नाट्य ''गम्मत'' है और मालवा का ''माच''।', 2, 0, 5, 'MP Art & Culture', 'In which area of Madhya Pradesh is "Mansukha" folk drama prevalent?', '✅ Correct Logic: ''Mansukha'' is a popular, humor-based folk drama prevalent in the Baghelkhand region of Madhya Pradesh, often featuring a jester-like character.
💡 Exam Fact: Other notable folk dramas of Baghelkhand include Chhahur and Lakadbaggha.
🧠 Memory Tip: A Tiger (Baghel) will dry out (Sukha) anyone''s courage.
🚫 Scam Alert: Gammat is the traditional drama of Nimar, and Maach belongs to Malwa. Mansukha is uniquely Baghelkhandi.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('mscyiWddW4dCUxOGvG_ND', 'Phb5GpZkUqYbaQM-2nPjG', '''सत्कार्यवाद'' किस दर्शन का मुख्य आधार है?', '"[\"वैशेषिक दर्शन (Vaisheshika philosophy)\",\"मीमांसा दर्शन (Mimamsa philosophy)\",\"सांख्य दर्शन (Sankhya philosophy)\",\"न्याय दर्शन (Nyaya philosophy)\"]"', '2.0', '✅ सही तर्क: सत्कार्यवाद ''सांख्य दर्शन'' (Sankhya) का मूल सिद्धांत है। इसके अनुसार ''कार्य अपने उत्पन्न होने से पहले कारण में विद्यमान रहता है'' (Effect pre-exists in its cause)।
💡 परीक्षा तथ्य: सांख्य दर्शन के प्रवर्तक महर्षि कपिल माने जाते हैं।
🧠 स्मृति टिप: ''S'' for Satkaryavada, ''S'' for Sankhya.
🚫 स्कैम अलर्ट: न्याय दर्शन ''असत्कार्यवाद'' (आरंभवाद) में विश्वास करता है, जो सत्कार्यवाद का ठीक उल्टा है।', 2, 0, 6, 'History/Indian Philosophy', '''Satkaryavada'' is the main basis of which philosophy?', '✅ Correct Logic: Satkaryavada is the core theory of causation in the ''Sankhya'' school of Indian philosophy, which states that the effect already pre-exists in its material cause before its creation.
💡 Exam Fact: Sage Kapila is universally credited as the founder of the Sankhya philosophy.
🧠 Memory Tip: Match the S: Satkaryavada = Sankhya.
🚫 Scam Alert: Nyaya and Vaisheshika follow ''Asatkaryavada'' (the theory that the effect is an entirely new creation), which is the exact opposite.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('i5giVbIC42F43IyAUBwyR', 'Phb5GpZkUqYbaQM-2nPjG', 'किस आश्रम में रहते हुए, मनुष्य को पंच महायज्ञों का अनुष्ठान करना पड़ता था?', '"[\"ब्रह्मचर्य आश्रम (Brahmacharya Ashram)\",\"गृहस्थ आश्रम (Grihastha Ashram)\",\"वानप्रस्थ आश्रम (Vanaprastha Ashram)\",\"संन्यास आश्रम (Sanyas Ashram)\"]"', '1.0', '✅ सही तर्क: वैदिक जीवन व्यवस्था में ''गृहस्थ आश्रम'' के दौरान एक व्यक्ति को पांच दैनिक महायज्ञ (ब्रह्म, देव, पितृ, वैश्वदेव और अतिथि यज्ञ) करने का विधान था।
💡 परीक्षा तथ्य: गृहस्थ आश्रम (25-50 वर्ष) को सभी चार आश्रमों में श्रेष्ठ माना गया है क्योंकि यह समाज का भरण-पोषण करता है।
🧠 स्मृति टिप: यज्ञ करने के लिए ''गृह'' (घर) और पत्नी का होना आवश्यक था।
🚫 स्कैम अलर्ट: संन्यास या वानप्रस्थ में कर्मकाण्ड छूट जाते हैं; यज्ञ केवल गृहस्थ का कर्तव्य है।', 2, 0, 7, 'Ancient History/Culture', 'While living in which Ashram did a person have to perform the rituals of Panch Mahayagya?', '✅ Correct Logic: In the Vedic Ashrama system, a person in the ''Grihastha Ashram'' (householder stage) was strictly mandated to perform the five daily great sacrifices (Panch Mahayagya).
💡 Exam Fact: Grihastha is considered the highest of the four Ashramas because it financially and physically supports the other three.
🧠 Memory Tip: You need a house (Griha) and a family to perform sacrifices and feed guests.
🚫 Scam Alert: Ascetics in Sanyas or Vanaprastha renounce fire and rituals; they meditate instead.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('O-XRJX8pmPbbngN9QIIke', 'Phb5GpZkUqYbaQM-2nPjG', 'तमिलनाडु में वैष्णव धर्म का प्रचार अलवार संतों द्वारा किया गया। अलवार संतों में एकमात्र महिला साध्वी कौन थी?', '"[\"नाम्मालवार (Nammalvar)\",\"पोयगई (Poigai)\",\"थिरुमंगई (Thirumangayi)\",\"अण्डाल (Andal)\"]"', '3.0', '✅ सही तर्क: 12 अलवार संतों (जो भगवान विष्णु के भक्त थे) में ''अण्डाल'' (Andal) एकमात्र महिला संत थीं।
💡 परीक्षा तथ्य: अण्डाल को ''दक्षिण की मीरा'' भी कहा जाता है, उनके गीत ''तिरुप्पावै'' बहुत प्रसिद्ध हैं।
🧠 स्मृति टिप: अण्डाल = अलवारों की अकेली देवी।
🚫 स्कैम अलर्ट: अगर ''नयनार'' (शिव भक्त) संतों की बात होती, तो प्रसिद्ध महिला संत ''करैक्कल अम्मैयर'' (Karaikkal Ammaiyar) होतीं।', 2, 0, 8, 'History/Art & Culture', 'Vaishnavism was propagated by Alvar saints of Tamil Nadu. Who was the only female Sadhvi among the Alvar saints?', '✅ Correct Logic: Among the 12 Alvar saints of South India who propagated Vaishnavism, ''Andal'' was the sole female saint.
💡 Exam Fact: Because of her immense devotion to Lord Krishna/Vishnu, she is affectionately known as the ''Meera of the South''.
🧠 Memory Tip: Andal = The Alvar Angel.
🚫 Scam Alert: Do not confuse Alvars (Vishnu devotees) with Nayanars (Shiva devotees). The female Nayanar saint is Karaikkal Ammaiyar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('A8hcl74Sumq9UePBX6bnL', 'Phb5GpZkUqYbaQM-2nPjG', 'वर्ष 2021-22 में, इनमें से कौन-सा राज्य देश में क्षेत्रफल में द्वितीय और दालों के उत्पादन में प्रथम स्थान पर था?', '"[\"महाराष्ट्र (Maharashtra)\",\"राजस्थान (Rajasthan)\",\"गुजरात (Gujarat)\",\"मध्यप्रदेश (Madhya Pradesh)\"]"', '3.0', '✅ सही तर्क: मध्य प्रदेश भौगोलिक क्षेत्रफल के लिहाज से भारत का दूसरा सबसे बड़ा राज्य है (राजस्थान के बाद) और यह दालों (Pulses) के उत्पादन में लगातार प्रथम स्थान पर है।
💡 परीक्षा तथ्य: मध्य प्रदेश को सोयाबीन स्टेट के साथ-साथ ''दलहन स्टेट'' भी कहा जाता है।
🧠 स्मृति टिप: मध्य (Center) में सबसे ज्यादा ''दाल'' पकती है।
🚫 स्कैम अलर्ट: राजस्थान क्षेत्रफल में प्रथम है लेकिन दलहन उत्पादन में प्रथम मध्य प्रदेश है।', 2, 0, 9, 'Geography/Economy', 'During the year 2021-22, which of these states was ranked second in area and first in production of pulses in the country?', '✅ Correct Logic: Madhya Pradesh is the second-largest state in India by geographical area (after Rajasthan) and stands first in the total production of pulses.
💡 Exam Fact: Besides pulses, MP is also the leading producer of soybeans and gram (chana) in the country.
🧠 Memory Tip: MP = Master of Pulses. Area-wise it is #2.
🚫 Scam Alert: Rajasthan is #1 in area, but the dual condition (#2 in area + #1 in pulses) uniquely points to Madhya Pradesh.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('nWr9RNadm8kQ527Xfn-6i', 'Phb5GpZkUqYbaQM-2nPjG', 'प्रत्येक वेद के लिए अलग-अलग ब्राह्मण ग्रंथ लिखे गए। यजुर्वेद से संबंधित ब्राह्मण ग्रंथ है:', '"[\"गोपथ (Gopatha)\",\"पञ्चविश तथा जैमिनीय (Panchvish and Jaiminiya)\",\"ऐतरेय तथा कौषीतकि (Aitareya and Kaushitaki)\",\"तैत्तिरीय तथा शतपथ (Taittiriya and Shatapatha)\"]"', '3.0', '✅ सही तर्क: ''शतपथ'' (शुक्ल यजुर्वेद) और ''तैत्तिरीय'' (कृष्ण यजुर्वेद) ब्राह्मण ग्रंथ यजुर्वेद से संबंधित हैं।
💡 परीक्षा तथ्य: ऐतरेय और कौषीतकि ऋग्वेद के हैं; गोपथ अथर्ववेद का है; पंचविश सामवेद का है।
🧠 स्मृति टिप: यजुर्वेद में यज्ञ की विधि है, और यज्ञ में ''सौ'' (शतपथ) आहुतियां दी जाती हैं।
🚫 स्कैम अलर्ट: गोपथ एकमात्र ब्राह्मण ग्रंथ है जो अथर्ववेद से जुड़ा है, इसे यजुर्वेद से न मिलाएं।', 2, 0, 10, 'History/Ancient India', 'Separate Brahmin texts were written for each Veda. The Brahmin text related to Yajurveda is:', '✅ Correct Logic: The ''Shatapatha Brahmana'' (White Yajurveda) and ''Taittiriya Brahmana'' (Black Yajurveda) are the key Brahmin texts associated with the Yajurveda.
💡 Exam Fact: Aitareya belongs to Rigveda, Panchvish to Samaveda, and Gopatha to Atharvaveda.
🧠 Memory Tip: Yajurveda is for rituals; rituals require a ''Hundred'' (Shata) paths.
🚫 Scam Alert: Memorize the mappings. Gopatha is highly asked because it is the only Brahmana for the Atharvaveda.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('OV1_hq3fa4yGzx7F_PjUY', 'vN_6C84IUbpMY0Qr0RFSa', 'वर्ष 2021 में, भारत के कौन-से राज्य में वन क्षेत्र सर्वाधिक था?', '"[\"महाराष्ट्र (Maharashtra)\",\"मध्यप्रदेश (Madhya Pradesh)\",\"ओडिशा (Odisha)\",\"आंध्र प्रदेश (Andhra Pradesh)\"]"', '1.0', '✅ सही तर्क: भारत वन स्थिति रिपोर्ट (ISFR) 2021 के अनुसार, क्षेत्रफल के हिसाब से देश का सबसे बड़ा वन क्षेत्र मध्य प्रदेश में है।
💡 परीक्षा तथ्य: प्रतिशत के आधार पर मिजोरम (84.53%) का वन आवरण सबसे अधिक है।
🧠 स्मृति टिप: भारत के ''हृदय'' (मध्य प्रदेश) में सबसे अधिक ''हरियाली'' (वन) है।
🚫 स्कैम अलर्ट: अक्सर क्षेत्रफल (Area) और प्रतिशत (Percentage) के बीच कन्फ्यूजन होता है, यहाँ स्पष्ट रूप से ''सर्वाधिक क्षेत्र'' पूछा गया है।', 2, 0, 1, 'Geography/Environment', 'During the year 2021, which state had the largest forest cover in India?', '✅ Correct Logic: According to the India State of Forest Report (ISFR) 2021, Madhya Pradesh has the largest forest cover in the country by geographical area.
💡 Exam Fact: In terms of forest cover as a percentage of total geographical area, Mizoram (84.53%) ranks first.
🧠 Memory Tip: The ''Heart'' of India (MP) holds the maximum ''Greenery'' (Forest area).
🚫 Scam Alert: Do not confuse ''Largest Forest Cover'' (Area-wise = MP) with ''Highest Forest Percentage'' (Mizoram).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('UykXnsju0Oar_9Rz3oISg', 'vN_6C84IUbpMY0Qr0RFSa', 'बघेलखण्ड के स्वतंत्रता संग्राम सेनानी ठाकुर रणमत सिंह को कब फाँसी दी गई?', '"[\"अगस्त, 1857 (August, 1857)\",\"अगस्त, 1858 (August, 1858)\",\"अगस्त, 1859 (August, 1859)\",\"अगस्त, 1862 (August, 1862)\"]"', '2.0', '✅ सही तर्क: 1857 की क्रांति के महान सेनानी ठाकुर रणमत सिंह को अगस्त 1859 में ब्रिटिश सरकार द्वारा फाँसी दी गई थी।
💡 परीक्षा तथ्य: रणमत सिंह ने रीवा और सतना (चित्रकूट) क्षेत्र में अंग्रेजों के खिलाफ सशस्त्र विद्रोह का नेतृत्व किया था।
🧠 स्मृति टिप: क्रांति (1857) के दो साल बाद (1859) उन्हें फाँसी मिली।
🚫 स्कैम अलर्ट: 1857 क्रांति की शुरुआत का वर्ष है, लेकिन अधिकांश क्रांतवीरों को 1858 या 1859 में पकड़ा गया था।', 2, 0, 2, 'MP History', 'When was Baghelkhand''s freedom fighter Thakur Ranmat Singh hanged?', '✅ Correct Logic: Thakur Ranmat Singh, a prominent freedom fighter from the Baghelkhand region, was executed by the British in August 1859.
💡 Exam Fact: He was instrumental in organizing the 1857 rebellion in the Rewa and Satna regions.
🧠 Memory Tip: His execution came two years after the 1857 revolt began (1859).
🚫 Scam Alert: 1857 marks the beginning of the revolt; arrests and executions typically occurred in the subsequent years (1858-1859).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('tkMDZh_meia6TPRezx2jy', 'vN_6C84IUbpMY0Qr0RFSa', 'दक्षिणी दोलन इनमें से कौन-से दो महासागरों के मध्य दोलन प्रतिरूप है?', '"[\"प्रशांत एवं अटलांटिक महासागर (Pacific and Atlantic Ocean)\",\"प्रशांत एवं हिन्द महासागर (Pacific and Indian Ocean)\",\"अटलांटिक एवं हिन्द महासागर (Atlantic and Indian Ocean)\",\"उपर्युक्त में से कोई नहीं (None of the above)\"]"', '1.0', '✅ सही तर्क: दक्षिणी दोलन (Southern Oscillation) उष्णकटिबंधीय प्रशांत महासागर और हिंद महासागर के बीच वायुमंडलीय दबाव का एक झूला-नुमा (seesaw) पैटर्न है।
💡 परीक्षा तथ्य: इसे ''एल नीनो-दक्षिणी दोलन'' (ENSO) के नाम से भी जाना जाता है, जो भारतीय मानसून को गहराई से प्रभावित करता है।
🧠 स्मृति टिप: भारत (हिंद महासागर) का मौसम प्रशांत (Pacific) के साथ ''दोलन'' करता है।
🚫 स्कैम अलर्ट: अटलांटिक महासागर का भारतीय मानसून से कोई सीधा दोलन-संबंध (ENSO) नहीं है।', 2, 0, 3, 'Geography', 'The Southern Oscillation is a seesaw pattern between which of these two oceans?', '✅ Correct Logic: The Southern Oscillation is a periodic seesaw in atmospheric pressure between the tropical Indo-Pacific regions (Pacific and Indian Oceans).
💡 Exam Fact: This phenomenon is closely linked with El Niño, forming the ENSO (El Niño-Southern Oscillation) cycle, which heavily impacts the Indian Monsoon.
🧠 Memory Tip: The weather balance swings between India''s home ocean (Indian) and the largest ocean (Pacific).
🚫 Scam Alert: The Atlantic Ocean has localized phenomena (like NAO) but is not part of the ENSO pattern.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2WgzOa7Ho6yJVa8alXPwb', 'vN_6C84IUbpMY0Qr0RFSa', 'इनमें से कौन-सा राज्य भारत में लौह अयस्क के निक्षेपित भण्डार में प्रथम स्थान (2020-21) पर था?', '"[\"झारखण्ड (Jharkhand)\",\"ओडिशा (Odisha)\",\"कर्नाटक (Karnataka)\",\"छत्तीसगढ़ (Chhattisgarh)\"]"', '1.0', '✅ सही तर्क: 2020-21 के खनिज आंकड़ों के अनुसार, ओडिशा भारत में लौह अयस्क के कुल भंडार (विशेषकर उच्च कोटि के हेमेटाइट) और उत्पादन दोनों में प्रथम स्थान पर है।
💡 परीक्षा तथ्य: ओडिशा की बादामपहाड़ और गुरुमहिसानी खदानें लौह अयस्क के लिए विश्व प्रसिद्ध हैं।
🧠 स्मृति टिप: ''लोहे'' जैसी मजबूती ''ओडिशा'' के उद्योगों में है।
🚫 स्कैम अलर्ट: कर्नाटक में मैग्नेटाइट लौह अयस्क के बड़े भंडार हैं, लेकिन कुल उपयोग योग्य लौह अयस्क और उत्पादन में ओडिशा हमेशा शीर्ष पर रहता है।', 2, 0, 4, 'Geography/Economy', 'Which of these states in India was ranked first in iron-ore reserves (2020-21)?', '✅ Correct Logic: According to the Indian Minerals Yearbook (2020-21), Odisha holds the top position in both the reserves (particularly high-grade Hematite) and production of iron ore.
💡 Exam Fact: The Badampahar mines in Odisha are among the richest iron ore deposits in India.
🧠 Memory Tip: O for Odisha, O for Ore (Iron).
🚫 Scam Alert: Karnataka possesses significant Magnetite reserves, but for standard commercial iron ore (Hematite) data in exams, Odisha is the widely accepted correct answer.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('blJSoMi1qgn9SUn61iQz1', 'vN_6C84IUbpMY0Qr0RFSa', 'निम्नलिखित में से सबसे लंबी नदी कौन-सी है?', '"[\"नर्मदा (Narmada)\",\"कावेरी (Cauvery)\",\"कृष्णा (Krishna)\",\"गोदावरी (Godavari)\"]"', '3.0', '✅ सही तर्क: प्रायद्वीपीय भारत में गोदावरी सबसे लंबी नदी (लगभग 1,465 किमी) है, जिसे ''दक्षिण गंगा'' भी कहा जाता है।
💡 परीक्षा तथ्य: कृष्णा नदी (लगभग 1,400 किमी) प्रायद्वीपीय भारत की दूसरी सबसे लंबी और नर्मदा (1,312 किमी) तीसरी सबसे लंबी नदी है।
🧠 स्मृति टिप: गोदावरी (G) = ग्रेटेस्ट (सबसे बड़ी दक्षिण नदी)।
🚫 स्कैम अलर्ट: नर्मदा मध्य प्रदेश की सबसे लंबी नदी है, लेकिन जब विकल्पों में गोदावरी मौजूद हो, तो राष्ट्रीय स्तर पर गोदावरी ही सही उत्तर होगा।', 2, 0, 5, 'Geography', 'Which of the following is the longest river?', '✅ Correct Logic: Among the given options, the Godavari is the longest river (approx. 1,465 km). It is the second longest river in India after the Ganga.
💡 Exam Fact: Because of its length and vast catchment area, it is frequently referred to as the ''Dakshin Ganga'' (Ganga of the South).
🧠 Memory Tip: Godavari is the ''Ganga'' of Peninsular India, hence the longest.
🚫 Scam Alert: Narmada is the longest west-flowing river, but Godavari is the longest peninsular river overall.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3kXG1KFSKD0eHfUrQpzoC', 'vN_6C84IUbpMY0Qr0RFSa', '15 नवम्बर को ''जनजातीय गौरव दिवस'' किस जनजातीय नायक के जन्मदिन के सम्मान में आयोजित किया जाता है?', '"[\"टंट्या मामा (Tantya Mama)\",\"रानी दुर्गावती (Rani Durgavati)\",\"भगवान बिरसा मुण्डा (Bhagwan Birsa Munda)\",\"महुआ कोल (माहा सिंह) (Mahua Kol (Maha Singh))\"]"', '2.0', '✅ सही तर्क: भारत सरकार ने भगवान बिरसा मुंडा की जयंती (15 नवंबर) को उनके साहस और जनजातीय अधिकारों की लड़ाई के सम्मान में ''जनजातीय गौरव दिवस'' के रूप में घोषित किया है।
💡 परीक्षा तथ्य: बिरसा मुंडा ने ''उलगुलान'' (महाविद्रोह) नामक आंदोलन का नेतृत्व किया था।
🧠 स्मृति टिप: 15 नवंबर = बिरसा मुंडा का गौरव।
🚫 स्कैम अलर्ट: टंट्या मामा को ''इंडियन रॉबिनहुड'' कहा जाता है, लेकिन 15 नवंबर का दिन विशेष रूप से बिरसा मुंडा को समर्पित है।', 2, 0, 6, 'History/Current Affairs', '15th November is celebrated as ''Janjatiya Gaurav Divas'' in honour of birth of which tribal leader?', '✅ Correct Logic: The Government of India declared November 15 as ''Janjatiya Gaurav Divas'' to commemorate the birth anniversary of the legendary tribal freedom fighter, Bhagwan Birsa Munda.
💡 Exam Fact: He spearheaded the ''Ulgulan'' (The Great Tumult) movement against the British in the Chotanagpur region.
🧠 Memory Tip: November 15 = Pride (Gaurav) of Birsa Munda.
🚫 Scam Alert: Tantya Mama is a great MP tribal hero, but this specific national day is dedicated entirely to Birsa Munda.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('NthqwR5W6R2Z96dhQx_W5', 'vN_6C84IUbpMY0Qr0RFSa', 'T20 विश्व कप फाइनल 2024 के संबंध में कौन-सा कथन गलत है?', '"[\"यह दक्षिण अफ्रीका में खेला गया था (It was played in South Africa)\",\"प्लेयर ऑफ द मैच - विराट कोहली (Player of the Match - Virat Kohli)\",\"प्लेयर ऑफ द टूर्नामेंट - जसप्रीत बुमराह (Player of the Tournament - Jaspreet Bumrah)\",\"फाइनल में भारत ने दक्षिण अफ्रीका को 7 रन से हराया (India defeated South Africa in the final by 7 runs)\"]"', '0.0', '✅ सही तर्क: T20 विश्व कप 2024 का फाइनल ब्रिजटाउन, बारबाडोस (वेस्टइंडीज) में खेला गया था, न कि दक्षिण अफ्रीका में।
💡 परीक्षा तथ्य: इस ऐतिहासिक फाइनल में भारत ने दक्षिण अफ्रीका को हराकर दूसरी बार T20 विश्व कप जीता।
🧠 स्मृति टिप: भारत ने दक्षिण अफ्रीका को ''वेस्टइंडीज'' की धरती पर हराया था।
🚫 स्कैम अलर्ट: दक्षिण अफ्रीका फाइनल में भारत का प्रतिद्वंद्वी था, वह मेजबान देश नहीं था।', 2, 0, 7, 'Sports/Current Affairs', 'Which statement is incorrect regarding the T20 World Cup Final 2024?', '✅ Correct Logic: The 2024 ICC Men''s T20 World Cup Final was hosted in Bridgetown, Barbados (West Indies), not in South Africa.
💡 Exam Fact: India won the tournament for the second time, defeating South Africa in a thrilling final.
🧠 Memory Tip: South Africa was the opponent, West Indies/USA were the hosts.
🚫 Scam Alert: Do not confuse the opponent team with the hosting nation.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('NRE-EdDFefqTHou9c6IC9', 'vN_6C84IUbpMY0Qr0RFSa', 'मध्यप्रदेश सरकार ने रानी दुर्गावती की 500वीं जयंती मनाने के लिए कई पहल की हैं। निम्नलिखित में से कौन-सी/से सही है/हैं?
1. रानी दुर्गावती अन्न प्रोत्साहन योजना
2. जबलपुर में रानी दुर्गावती स्मारक एवं उद्यान का निर्माण
3. मध्यप्रदेश जनजाति महिला कल्याण बोर्ड की स्थापना
4. रानी दुर्गावती की जयंती पर सार्वजनिक अवकाश घोषित करना', '"[\"केवल 1 (Only 1)\",\"1 एवं 2 (1 and 2)\",\"1, 2 एवं 3 (1, 2 and 3)\",\"1, 2, 3 एवं 4 (1, 2, 3 and 4)\"]"', '3.0', '✅ सही तर्क: मध्य प्रदेश सरकार ने वीरांगना रानी दुर्गावती की 500वीं जयंती (5 अक्टूबर) पर श्रीअन्न (मोटे अनाज) प्रोत्साहन योजना, जबलपुर में 100 करोड़ का स्मारक, सार्वजनिक अवकाश और जनजातीय महिला कल्याण बोर्ड बनाने जैसी सभी घोषणाएँ की थीं।
💡 परीक्षा तथ्य: रानी दुर्गावती ने गोंडवाना साम्राज्य पर शासन किया था और अकबर की सेना से युद्ध किया था।
🧠 स्मृति टिप: 500वीं जयंती = सरकार द्वारा ''सभी'' बड़े सम्मान दिए गए।
🚫 स्कैम अलर्ट: जब राज्य सरकार के महा-आयोजनों पर ऐसे बहु-कथनात्मक प्रश्न आते हैं, तो अमूमन सभी कथन सरकार की आधिकारिक घोषणाओं का हिस्सा होते हैं।', 2, 0, 8, 'MP Current Affairs', 'The Madhya Pradesh Government has undertaken several initiatives to commemorate the 500th birth anniversary of Rani Durgavati. Which of the following is/are correct?
1. Rani Durgavati Anna Protsahan Yojana
2. Formation of Rani Durgavati Memorial and Garden in Jabalpur
3. Establishment of Madhya Pradesh Tribal Women Welfare Board
4. Declaration of a public holiday on Rani Durgavati''s birth anniversary', '✅ Correct Logic: To celebrate the 500th birth anniversary of Queen Durgavati, the MP cabinet approved all the listed initiatives, including the millet promotion scheme, a massive memorial in Jabalpur, a new welfare board, and a state holiday.
💡 Exam Fact: Rani Durgavati was the brave queen of Gondwana who martyred herself fighting against the Mughal forces of Akbar led by Asaf Khan.
🧠 Memory Tip: A 500th-anniversary mega event naturally includes ''All of the above'' government schemes.
🚫 Scam Alert: In MPPSC, exhaustive lists of state government schemes commemorating historical figures usually feature entirely correct statements.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Dz0tPVxJtdimyg81HWLBS', 'vN_6C84IUbpMY0Qr0RFSa', 'वर्ष 2023 के लिए मध्यप्रदेश सरकार के प्रतिष्ठित किशोर कुमार सम्मान के प्राप्तकर्ता कौन थे?', '"[\"कैलाश खेर (Kailash Kher)\",\"शंकर महादेवन (Shankar Mahadevan)\",\"राजकुमार हिरानी (Rajkumar Hirani)\",\"विशाल भारद्वाज (Vishal Bhardwaj)\"]"', '2.0', '✅ सही तर्क: फिल्म निर्देशन और पटकथा लेखन में उत्कृष्ट योगदान के लिए वर्ष 2023 का ''राष्ट्रीय किशोर कुमार सम्मान'' प्रसिद्ध फिल्म निर्देशक राजकुमार हिरानी को प्रदान किया गया।
💡 परीक्षा तथ्य: यह पुरस्कार मध्य प्रदेश के संस्कृति विभाग द्वारा दिया जाता है और इसमें 5 लाख रुपये की सम्मान राशि दी जाती है।
🧠 स्मृति टिप: 2023 में ''मुन्नाभाई'' वाले हिरानी जी को किशोर कुमार सम्मान मिला।
🚫 स्कैम अलर्ट: किशोर कुमार गायक थे, इसलिए छात्र कैलाश खेर या शंकर महादेवन (गायकों) को चुन सकते हैं, लेकिन यह सम्मान निर्देशन और अभिनय के लिए भी दिया जाता है।', 2, 0, 9, 'MP Current Affairs/Awards', 'Who was the recipient of the Madhya Pradesh Government''s prestigious Kishore Kumar Samman for the year 2023?', '✅ Correct Logic: The prestigious National Kishore Kumar Award for the year 2023 was conferred upon the renowned Bollywood director Rajkumar Hirani for his exceptional work in filmmaking.
💡 Exam Fact: Instituted by the MP Culture Department, this award cycles between categories like playback singing, acting, and direction.
🧠 Memory Tip: Think of the legendary director Hirani receiving the legendary singer''s award.
🚫 Scam Alert: Since Kishore Kumar was a singer, candidates intuitively guess singers like Kailash Kher. Remember, it is also awarded for direction.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7DyB9IP-M4zmRr9WDAGY6', 'vN_6C84IUbpMY0Qr0RFSa', 'अन्तर्राष्ट्रीय पर्यटन दिवस (27 सितम्बर, 2024) को, मध्यप्रदेश के तीन गाँवों को भारत सरकार के पर्यटन मंत्रालय द्वारा उनके उत्कृष्ट सतत पर्यटन प्रयासों के लिए मान्यता दी गई थी। निम्नलिखित में से कौन-सा गाँव उनमें नहीं था?', '"[\"प्राणपुर (Pranpur)\",\"साबरवानी (Sabarvani)\",\"लाडपुरा खास (Ladpura Khas)\",\"घोगरा (Ghogra)\"]"', '3.0', '✅ सही तर्क: 2024 के सर्वश्रेष्ठ पर्यटन ग्राम पुरस्कार में प्राणपुर (अशोकनगर), साबरवानी (छिंदवाड़ा), और लाडपुरा खास (निवाड़ी) को सम्मानित किया गया था। घोगरा इस सूची में नहीं था।
💡 परीक्षा तथ्य: प्राणपुर को विशेष रूप से उसके शिल्प (Craft) के लिए सर्वश्रेष्ठ पर्यटन गांव चुना गया था।
🧠 स्मृति टिप: P-S-L (Pranpur, Sabarvani, Ladpura) को पर्यटन पुरस्कार मिला।
🚫 स्कैम अलर्ट: लाडपुरा खास पहले भी UNWTO पर्यटन ग्राम पुरस्कार के लिए नामांकित हो चुका है, यह एक बहुत प्रसिद्ध पर्यटन गांव है।', 2, 0, 10, 'MP Current Affairs/Tourism', 'On International Tourism Day (September 27, 2024) three villages in Madhya Pradesh were recognized by the Ministry of Tourism, Government of India, for their outstanding sustainable tourism efforts. Which of the following village was not among them?', '✅ Correct Logic: During the Best Tourism Village Awards 2024, Pranpur (Ashoknagar), Sabarvani (Chhindwara), and Ladpura Khas (Niwari) won in different sustainable tourism categories. Ghogra was not part of this winning list.
💡 Exam Fact: Pranpur was specifically awarded for its rich handloom and craft heritage.
🧠 Memory Tip: Remember the PSL trio: Pranpur, Sabarvani, Ladpura.
🚫 Scam Alert: Ladpura Khas is a very high-profile village tourism site; don''t eliminate it just because it sounds unfamiliar.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('lYokihoVEYGdJ9ZbRrxwz', '7DMLHJzMdCOQw7WAd_kPT', 'कथन I: संविधान सभा की पहली बैठक 9 दिसंबर, 1946 को नई दिल्ली में हुई थी।
कथन II: जवाहरलाल नेहरू को संविधान सभा में आमंत्रित नहीं किया गया था।
निम्नलिखित में से कौन-सा विकल्प सही है?', '"[\"कथन I और कथन II दोनों सही हैं। (Both Statement I and Statement II are true.)\",\"कथन I और कथन II दोनों गलत हैं। (Both Statement I and Statement II are false.)\",\"कथन I सही है, लेकिन कथन II गलत है। (Statement I is true, but Statement II is false.)\",\"कथन I गलत है, लेकिन कथन II सही है। (Statement I is false, but Statement II is true.)\"]"', '2.0', '✅ सही तर्क: कथन I बिल्कुल सही है (9 दिसंबर 1946 को पहली बैठक हुई)। कथन II हास्यास्पद रूप से गलत है क्योंकि जवाहरलाल नेहरू संविधान सभा के प्रमुख सदस्य थे और उन्होंने ही ''उद्देश्य प्रस्ताव'' पेश किया था।
💡 परीक्षा तथ्य: मुस्लिम लीग ने इस पहली बैठक का बहिष्कार किया था। डॉ. सच्चिदानंद सिन्हा इसके अस्थायी अध्यक्ष चुने गए थे।
🧠 स्मृति टिप: नेहरू के बिना संविधान सभा? असंभव! दूसरा कथन सरासर गलत है।
🚫 स्कैम अलर्ट: ऐसे कथन सिर्फ आत्मविश्वास डिगाने के लिए होते हैं। बुनियादी इतिहास पर भरोसा रखें।', 2, 0, 1, 'Polity', 'Statement I: The first meeting of the Constituent Assembly was held on 9th December, 1946 in New Delhi.
Statement II: Jawaharlal Nehru was not invited to the Constituent Assembly.
Which of the following options is correct?', '✅ Correct Logic: Statement I is a historical fact (Dec 9, 1946). Statement II is absurdly false, as Jawaharlal Nehru was a central figure in the Assembly and moved the historic Objectives Resolution.
💡 Exam Fact: The Muslim League boycotted this very first meeting, which was attended by only 211 members.
🧠 Memory Tip: A Constituent Assembly without Nehru is like a car without an engine. Statement II is completely fake.
🚫 Scam Alert: Do not second-guess basic historical facts when encountering weird negative statements in exams.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2x5FfqzlljdImNrSAK4tO', '7DMLHJzMdCOQw7WAd_kPT', 'मध्यप्रदेश में वर्ष 2024 में तेल रिफाइनरी की संख्या कितनी थी?', '"[\"तीन (Three)\",\"एक (One)\",\"चार (Four)\",\"दो (Two)\"]"', '1.0', '✅ सही तर्क: मध्य प्रदेश में केवल 1 तेल रिफाइनरी है, जो सागर जिले के बीना (Bina) में स्थित है।
💡 परीक्षा तथ्य: यह ओमान ऑयल कॉरपोरेशन (OOC) और भारत पेट्रोलियम (BPCL) का संयुक्त उद्यम है, जिसे 2011 में शुरू किया गया था।
🧠 स्मृति टिप: MP में तेल की ''एक'' ही बीना (बिना/बीना) है।
🚫 स्कैम अलर्ट: हाल ही में वहां पेट्रोकेमिकल विस्तार की घोषणा हुई है, लेकिन रिफाइनरी की संख्या अभी भी ''एक'' ही है।', 2, 0, 2, 'MP Economy/Geography', 'What was the number of oil refineries in Madhya Pradesh in 2024?', '✅ Correct Logic: Madhya Pradesh hosts exactly one oil refinery, which is the Bina Refinery located in the Sagar district.
💡 Exam Fact: It was established as a joint venture between BPCL and the Oman Oil Corporation (OOC).
🧠 Memory Tip: MP runs on ''One'' Bina.
🚫 Scam Alert: Massive investments have been made recently for petrochemical expansions at Bina, but that does not increase the count of refineries. It remains 1.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('CtaeX0QiEpmePgFmoyv5p', '7DMLHJzMdCOQw7WAd_kPT', 'भारतीय संविधान के संदर्भ में ''आधारभूत ढाँचा'' सिद्धांत का प्रतिपादन सर्वप्रथम निम्नलिखित में से किस मामले में किया गया था?', '"[\"शंकरी प्रसाद बनाम भारत संघ (Sankari Prasad V. Union of India)\",\"चम्पकम दोराईराजन बनाम मद्रास राज्य (Champakam Dorairajan V. State of Madras)\",\"गोलकनाथ बनाम पंजाब राज्य (Golaknath V. State of Punjab)\",\"केशवानन्द भारती बनाम केरल राज्य (Kesavananda Bharati V. State of Kerala)\"]"', '3.0', '✅ सही तर्क: 1973 के ऐतिहासिक ''केशवानन्द भारती'' मामले में सुप्रीम कोर्ट ने पहली बार कहा था कि संसद संविधान में संशोधन तो कर सकती है, लेकिन इसके ''आधारभूत ढाँचे'' (Basic Structure) को नष्ट नहीं कर सकती।
💡 परीक्षा तथ्य: इस मामले की सुनवाई अब तक की सबसे बड़ी संविधान पीठ (13 जजों) द्वारा की गई थी।
🧠 स्मृति टिप: ''केशव'' ने संविधान का ''आधार'' बचाया (1973)।
🚫 स्कैम अलर्ट: गोलकनाथ मामले (1967) में मौलिक अधिकारों में संशोधन पर रोक लगाई गई थी, लेकिन ''आधारभूत ढाँचा'' शब्द का जन्म केशवानंद भारती केस से ही हुआ।', 2, 0, 3, 'Polity', 'The doctrine of ''basic structure'' in the context of Indian Constitution was propounded in which of the following cases for the first time?', '✅ Correct Logic: The landmark ''Kesavananda Bharati v. State of Kerala'' (1973) case birthed the ''Basic Structure Doctrine'', restricting Parliament from altering the fundamental features of the Constitution.
💡 Exam Fact: This judgement was delivered by a razor-thin 7-6 majority by the largest ever bench of 13 Supreme Court judges.
🧠 Memory Tip: Kesavananda = The Keeper of the Constitution''s Base.
🚫 Scam Alert: The Golaknath case is famous for protecting Fundamental Rights, but the specific legal term ''Basic Structure'' was invented in the 1973 Kesavananda case.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4C2cJRy0LWMFHsvCJZHaY', '7DMLHJzMdCOQw7WAd_kPT', 'उच्चतम न्यायालय एवं उच्च न्यायालयों के न्यायाधीशों की नियुक्ति के प्रावधानों को भारतीय संविधान में ________ कमेटी (1945) की प्रकाशित अनुशंसाओं को ध्यान में रखते हुए समाविष्ट किया गया था।', '"[\"हरेन्द्र कुमार (Harendra Kumar)\",\"सेन (उषा नाथ सेन) (Sen (Usha Nath Sen))\",\"वरदाचारी (एस. वरदाचारी) (Varadachari (S. Varadachari))\",\"सप्रू (सर तेज बहादुर सप्रू) (Sapru (Sir Tej Bahadur Sapru))\"]"', '3.0', '✅ सही तर्क: 1945 में सर तेज बहादुर सप्रू की अध्यक्षता में सप्रू समिति (Sapru Committee) ने न्यायपालिका की स्वतंत्रता और जजों की नियुक्ति संबंधी कई महत्त्वपूर्ण सिफारिशें की थीं, जिन्हें संविधान निर्माताओं ने अपनाया।
💡 परीक्षा तथ्य: सप्रू रिपोर्ट (1945) में मौलिक अधिकारों और अल्पसंख्यक अधिकारों पर भी जोर दिया गया था।
🧠 स्मृति टिप: सप्रू (Sapru) = सुप्रीम (Supreme) कोर्ट के नियम।
🚫 स्कैम अलर्ट: एस. वरदाचारी फेडरल कोर्ट के जज थे, लेकिन समग्र संवैधानिक सुधारों की रिपोर्ट सप्रू समिति ने दी थी।', 2, 0, 4, 'Polity/History', 'The provisions relating to appointment of Supreme Court and High Court Judges in the Indian Constitution were incorporated on the basis of published recommendations given by ________ Committee (1945).', '✅ Correct Logic: The Sapru Committee Report of 1945, chaired by Sir Tej Bahadur Sapru, provided crucial recommendations regarding the independence of the judiciary and the appointment of judges, heavily influencing the framers of the Constitution.
💡 Exam Fact: The Sapru report is also historically significant for its strong advocacy for justifiable Fundamental Rights.
🧠 Memory Tip: Sapru = Supreme Guidelines for Judges.
🚫 Scam Alert: Don''t guess Varadachari just because he was a judge; the policy-level committee was led by the liberal stalwart Sapru.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Ap2joNo4zQqVkZ1eGH23n', '7DMLHJzMdCOQw7WAd_kPT', 'वर्तमान समय में भारतीय संविधान में संपत्ति के अधिकार को निम्नलिखित में से किस रूप में स्वीकार किया गया है?', '"[\"मूल अधिकार (Fundamental Right)\",\"राज्य की नीति के निदेशक तत्त्व (Directive Principles of State Policy)\",\"मानवाधिकार (Human Right)\",\"कानूनी अधिकार (Legal Right)\"]"', '3.0', '✅ सही तर्क: संपत्ति का अधिकार अब अनुच्छेद 300A के तहत एक ''विधिक/कानूनी अधिकार'' (Legal Right) है।
💡 परीक्षा तथ्य: इसे 1978 में 44वें संविधान संशोधन द्वारा ''मौलिक अधिकारों'' (अनुच्छेद 31) की सूची से हटा दिया गया था।
🧠 स्मृति टिप: संपत्ति अब ''कानून'' के हाथ में है, ''मूल'' नहीं रही।
🚫 स्कैम अलर्ट: इसे मानवाधिकार न लिखें, भारतीय संविधान के संदर्भ में यह तकनीकी रूप से एक ''संवैधानिक/कानूनी अधिकार'' है।', 2, 0, 5, 'Polity', 'In present times, Right to Property has been accepted in the Indian Constitution in which of the following forms?', '✅ Correct Logic: The Right to Property is no longer a Fundamental Right. It is currently recognized as a ''Legal Right'' (or Constitutional Right) under Article 300A.
💡 Exam Fact: It was removed from the list of Fundamental Rights (Part III) by the 44th Constitutional Amendment Act in 1978.
🧠 Memory Tip: Property is a matter of Law (Legal), not birthright (Fundamental).
🚫 Scam Alert: ''Human Right'' sounds philosophically good, but in Indian polity terminology, it is strictly a ''Legal Right''.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('JRIl43zV5ETzDBdu-FMUa', '7DMLHJzMdCOQw7WAd_kPT', 'वर्ष 2021 में, भारत के कौन-से राज्य में वन क्षेत्र सर्वाधिक था?', '"[\"महाराष्ट्र (Maharashtra)\",\"मध्यप्रदेश (Madhya Pradesh)\",\"ओडिशा (Odisha)\",\"आंध्र प्रदेश (Andhra Pradesh)\"]"', '1.0', '✅ सही तर्क: भारत वन स्थिति रिपोर्ट (ISFR) 2021 के अनुसार, क्षेत्रफल के हिसाब से देश का सबसे बड़ा वन क्षेत्र मध्य प्रदेश में है।
💡 परीक्षा तथ्य: प्रतिशत के आधार पर मिजोरम (84.53%) का वन आवरण सबसे अधिक है।
🧠 स्मृति टिप: भारत के ''हृदय'' (मध्य प्रदेश) में सबसे अधिक ''हरियाली'' (वन) है।
🚫 स्कैम अलर्ट: अक्सर क्षेत्रफल (Area) और प्रतिशत (Percentage) के बीच कन्फ्यूजन होता है, यहाँ स्पष्ट रूप से ''सर्वाधिक क्षेत्र'' पूछा गया है।', 2, 0, 6, 'Geography/Environment', 'During the year 2021, which state had the largest forest cover in India?', '✅ Correct Logic: According to the India State of Forest Report (ISFR) 2021, Madhya Pradesh has the largest forest cover in the country by geographical area.
💡 Exam Fact: In terms of forest cover as a percentage of total geographical area, Mizoram (84.53%) ranks first.
🧠 Memory Tip: The ''Heart'' of India (MP) holds the maximum ''Greenery'' (Forest area).
🚫 Scam Alert: Do not confuse ''Largest Forest Cover'' (Area-wise = MP) with ''Highest Forest Percentage'' (Mizoram).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Ri_dS1amUZ2j0qc0qAVlS', '7DMLHJzMdCOQw7WAd_kPT', 'बघेलखण्ड के स्वतंत्रता संग्राम सेनानी ठाकुर रणमत सिंह को कब फाँसी दी गई?', '"[\"अगस्त, 1857 (August, 1857)\",\"अगस्त, 1858 (August, 1858)\",\"अगस्त, 1859 (August, 1859)\",\"अगस्त, 1862 (August, 1862)\"]"', '2.0', '✅ सही तर्क: 1857 की क्रांति के महान सेनानी ठाकुर रणमत सिंह को अगस्त 1859 में ब्रिटिश सरकार द्वारा फाँसी दी गई थी।
💡 परीक्षा तथ्य: रणमत सिंह ने रीवा और सतना (चित्रकूट) क्षेत्र में अंग्रेजों के खिलाफ सशस्त्र विद्रोह का नेतृत्व किया था।
🧠 स्मृति टिप: क्रांति (1857) के दो साल बाद (1859) उन्हें फाँसी मिली।
🚫 स्कैम अलर्ट: 1857 क्रांति की शुरुआत का वर्ष है, लेकिन अधिकांश क्रांतवीरों को 1858 या 1859 में पकड़ा गया था।', 2, 0, 7, 'MP History', 'When was Baghelkhand''s freedom fighter Thakur Ranmat Singh hanged?', '✅ Correct Logic: Thakur Ranmat Singh, a prominent freedom fighter from the Baghelkhand region, was executed by the British in August 1859.
💡 Exam Fact: He was instrumental in organizing the 1857 rebellion in the Rewa and Satna regions.
🧠 Memory Tip: His execution came two years after the 1857 revolt began (1859).
🚫 Scam Alert: 1857 marks the beginning of the revolt; arrests and executions typically occurred in the subsequent years (1858-1859).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('VBM2u6XLqR223YqnCY8a2', '7DMLHJzMdCOQw7WAd_kPT', 'दक्षिणी दोलन इनमें से कौन-से दो महासागरों के मध्य दोलन प्रतिरूप है?', '"[\"प्रशांत एवं अटलांटिक महासागर (Pacific and Atlantic Ocean)\",\"प्रशांत एवं हिन्द महासागर (Pacific and Indian Ocean)\",\"अटलांटिक एवं हिन्द महासागर (Atlantic and Indian Ocean)\",\"उपर्युक्त में से कोई नहीं (None of the above)\"]"', '1.0', '✅ सही तर्क: दक्षिणी दोलन (Southern Oscillation) उष्णकटिबंधीय प्रशांत महासागर और हिंद महासागर के बीच वायुमंडलीय दबाव का एक झूला-नुमा (seesaw) पैटर्न है।
💡 परीक्षा तथ्य: इसे ''एल नीनो-दक्षिणी दोलन'' (ENSO) के नाम से भी जाना जाता है, जो भारतीय मानसून को गहराई से प्रभावित करता है।
🧠 स्मृति टिप: भारत (हिंद महासागर) का मौसम प्रशांत (Pacific) के साथ ''दोलन'' करता है।
🚫 स्कैम अलर्ट: अटलांटिक महासागर का भारतीय मानसून से कोई सीधा दोलन-संबंध (ENSO) नहीं है।', 2, 0, 8, 'Geography', 'The Southern Oscillation is a seesaw pattern between which of these two oceans?', '✅ Correct Logic: The Southern Oscillation is a periodic seesaw in atmospheric pressure between the tropical Indo-Pacific regions (Pacific and Indian Oceans).
💡 Exam Fact: This phenomenon is closely linked with El Niño, forming the ENSO (El Niño-Southern Oscillation) cycle, which heavily impacts the Indian Monsoon.
🧠 Memory Tip: The weather balance swings between India''s home ocean (Indian) and the largest ocean (Pacific).
🚫 Scam Alert: The Atlantic Ocean has localized phenomena (like NAO) but is not part of the ENSO pattern.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('FH4-6mySUIYY7CmLnxPB4', '7DMLHJzMdCOQw7WAd_kPT', 'इनमें से कौन-सा राज्य भारत में लौह अयस्क के निक्षेपित भण्डार में प्रथम स्थान (2020-21) पर था?', '"[\"झारखण्ड (Jharkhand)\",\"ओडिशा (Odisha)\",\"कर्नाटक (Karnataka)\",\"छत्तीसगढ़ (Chhattisgarh)\"]"', '1.0', '✅ सही तर्क: 2020-21 के खनिज आंकड़ों के अनुसार, ओडिशा भारत में लौह अयस्क के कुल भंडार (विशेषकर उच्च कोटि के हेमेटाइट) और उत्पादन दोनों में प्रथम स्थान पर है।
💡 परीक्षा तथ्य: ओडिशा की बादामपहाड़ और गुरुमहिसानी खदानें लौह अयस्क के लिए विश्व प्रसिद्ध हैं।
🧠 स्मृति टिप: ''लोहे'' जैसी मजबूती ''ओडिशा'' के उद्योगों में है।
🚫 स्कैम अलर्ट: कर्नाटक में मैग्नेटाइट लौह अयस्क के बड़े भंडार हैं, लेकिन कुल उपयोग योग्य लौह अयस्क और उत्पादन में ओडिशा हमेशा शीर्ष पर रहता है।', 2, 0, 9, 'Geography/Economy', 'Which of these states in India was ranked first in iron-ore reserves (2020-21)?', '✅ Correct Logic: According to the Indian Minerals Yearbook (2020-21), Odisha holds the top position in both the reserves (particularly high-grade Hematite) and production of iron ore.
💡 Exam Fact: The Badampahar mines in Odisha are among the richest iron ore deposits in India.
🧠 Memory Tip: O for Odisha, O for Ore (Iron).
🚫 Scam Alert: Karnataka possesses significant Magnetite reserves, but for standard commercial iron ore (Hematite) data in exams, Odisha is the widely accepted correct answer.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('_xwvSnjO4jbEMWO5HTbyc', '7DMLHJzMdCOQw7WAd_kPT', 'निम्नलिखित में से सबसे लंबी नदी कौन-सी है?', '"[\"नर्मदा (Narmada)\",\"कावेरी (Cauvery)\",\"कृष्णा (Krishna)\",\"गोदावरी (Godavari)\"]"', '3.0', '✅ सही तर्क: प्रायद्वीपीय भारत में गोदावरी सबसे लंबी नदी (लगभग 1,465 किमी) है, जिसे ''दक्षिण गंगा'' भी कहा जाता है।
💡 परीक्षा तथ्य: कृष्णा नदी (लगभग 1,400 किमी) प्रायद्वीपीय भारत की दूसरी सबसे लंबी और नर्मदा (1,312 किमी) तीसरी सबसे लंबी नदी है।
🧠 स्मृति टिप: गोदावरी (G) = ग्रेटेस्ट (सबसे बड़ी दक्षिण नदी)।
🚫 स्कैम अलर्ट: नर्मदा मध्य प्रदेश की सबसे लंबी नदी है, लेकिन जब विकल्पों में गोदावरी मौजूद हो, तो राष्ट्रीय स्तर पर गोदावरी ही सही उत्तर होगा।', 2, 0, 10, 'Geography', 'Which of the following is the longest river?', '✅ Correct Logic: Among the given options, the Godavari is the longest river (approx. 1,465 km). It is the second longest river in India after the Ganga.
💡 Exam Fact: Because of its length and vast catchment area, it is frequently referred to as the ''Dakshin Ganga'' (Ganga of the South).
🧠 Memory Tip: Godavari is the ''Ganga'' of Peninsular India, hence the longest.
🚫 Scam Alert: Narmada is the longest west-flowing river, but Godavari is the longest peninsular river overall.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('SUNdRIQ6Okvw4ACsQeJVz', 'VTsigvBgGALY-DVweqAiv', 'मध्य प्रदेश की राजधानी क्या है?', '"[{\"id\":\"1\",\"text\":\"इंदौर\",\"text_en\":\"Indore\"},{\"id\":\"2\",\"text\":\"भोपाल\",\"text_en\":\"Bhopal\"},{\"id\":\"3\",\"text\":\"जबलपुर\",\"text_en\":\"Jabalpur\"},{\"id\":\"4\",\"text\":\"ग्वालियर\",\"text_en\":\"Gwalior\"}]"', '2', 'मध्य प्रदेश की राजधानी भोपाल है — यह राज्य प्रशासन का मुख्य केंद्र है।', 1, 0, 1, 'General Knowledge', 'What is the capital of Madhya Pradesh?', 'Bhopal is the capital of Madhya Pradesh.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भोपाल: MP की राजधानी; प्रशासनिक केंद्र।","MP बना 1 नवंबर 1956 को (भाषाई आधार पर पुनर्गठन)।","राज्य की विधानसभा भोपाल में।"],"mnemonics":["MP capital → Bhopal (B for both)."],"related":["CM residence / MP High Court Jabalpur","MP के मुख्य शहर: इंदौर (व्यापार), ग्वालियर (इतिहास)"],"memoryTip":"राजधानी vs सबसे बड़ा शहर अलग हो सकते हैं — कन्फ्यूज मत होना।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1AhUFyXz_wVtQTAlHOTZ9', 'VTsigvBgGALY-DVweqAiv', 'नीचे दिए वाक्य में रिक्त स्थान भरें: पानी का क्वथनांक सामान्य दबाव पर _____ °C होता है।', '"[{\"id\":\"1\",\"text\":\"90°C\",\"text_en\":\"90°C\"},{\"id\":\"2\",\"text\":\"100°C\",\"text_en\":\"100°C\"},{\"id\":\"3\",\"text\":\"110°C\",\"text_en\":\"110°C\"},{\"id\":\"4\",\"text\":\"0°C\",\"text_en\":\"0°C\"}]"', '2', 'सामान्य वायुदाब पर शुद्ध पानी 100°C पर उबलता है।', 1, 0, 2, 'General Science', 'Fill in the blank: At standard pressure, water boils at _____ °C.', 'Pure water boils at 100°C at standard atmospheric pressure.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["क्वथनांक: द्रव जिस ताप पर वाष्प दबाव = बाह्य दबाव।","समुद्र तल पर पानी: ठोस→द्रव 0°C, द्रव→वाष्प 100°C (लगभग)।","दबाव बढ़ने पर क्वथनांक बढ़ता है (प्रेशर कुकर)।"],"mnemonics":["100 = boil, 0 = freeze (water, normal pressure)."],"related":["हिमांक 0°C","वाष्पीकरण शरीर से ठंडक"],"memoryTip":"MCQ में ''standard pressure'' दिखे तो पानी = 100°C याद रखें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2y0pO7RV1D-Lzq9BTSuQC', 'D2v-iTI2lLrB1AxLhKo1P', 'सांची का स्तूप भारत के किस राज्य में स्थित है?', '"[{\"id\":\"1\",\"text\":\"उत्तर प्रदेश\",\"text_en\":\"Uttar Pradesh\"},{\"id\":\"2\",\"text\":\"मध्य प्रदेश\",\"text_en\":\"Madhya Pradesh\"},{\"id\":\"3\",\"text\":\"बिहार\",\"text_en\":\"Bihar\"},{\"id\":\"4\",\"text\":\"महाराष्ट्र\",\"text_en\":\"Maharashtra\"}]"', '2', 'सांची का महान स्तूप मध्य प्रदेश के रायसेन जिले में है। इसका निर्माण सम्राट अशोक ने करवाया था।', 1, 0, 1, 'GK', 'In which state of India is the Sanchi Stupa located?', 'The Great Stupa at Sanchi is in the Raisen district of Madhya Pradesh, built by Emperor Ashoka.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["सांची का स्तूप भारत की सबसे पुरानी पत्थर की इमारतों में से एक है। इसे मौर्य सम्राट अशोक ने तीसरी शताब्दी ईसा पूर्व में बनवाया था।","यह बौद्ध धर्म का एक प्रमुख केंद्र है, लेकिन दिलचस्प बात यह है कि भगवान बुद्ध कभी खुद सांची नहीं गए थे!","इसे 1989 में यूनेस्को (UNESCO) विश्व धरोहर स्थल घोषित किया गया था, इसलिए यह एमपी पुलिस परीक्षा का फेवरेट सवाल है।"],"factsEn":["Sanchi Stupa is one of India''s oldest stone structures, commissioned by the Mauryan Emperor Ashoka in the 3rd century BCE.","It''s a massive hub for Buddhism, yet surprisingly, Lord Buddha himself never actually visited Sanchi during his lifetime!","UNESCO tagged it as a World Heritage Site back in 1989, making it a highly frequent question in state exams."],"mnemonics":["''सांची'' में ''शांति'' है, और शांति भारत के ''मध्य'' (मध्य प्रदेश) में मिलती है।"],"mnemonicsEn":["Sanchi = Sanctuary of peace in the ''Middle'' (Madhya) of India."],"related":["रायसेन जिला","सम्राट अशोक","₹200 के नोट पर तस्वीर"],"relatedEn":["Raisen District","Emperor Ashoka","Motif on the ₹200 note"],"memoryTip":"अपनी जेब से ₹200 का नया नोट निकालें, उसके पीछे सांची का स्तूप ही छपा है!","memoryTipEn":"Check the back of a new ₹200 note; you''ll see the Sanchi Stupa printed right there!"}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5SMGoHsPRNo29_6ma6a9h', 'D2v-iTI2lLrB1AxLhKo1P', 'खजुराहो के प्रसिद्ध मंदिर किस राजवंश के राजाओं द्वारा बनवाए गए थे?', '"[{\"id\":\"1\",\"text\":\"चोल\",\"text_en\":\"Chola\"},{\"id\":\"2\",\"text\":\"चंदेल\",\"text_en\":\"Chandela\"},{\"id\":\"3\",\"text\":\"परमार\",\"text_en\":\"Paramara\"},{\"id\":\"4\",\"text\":\"गुप्त\",\"text_en\":\"Gupta\"}]"', '2', 'खजुराहो के मंदिर मध्य प्रदेश के छतरपुर जिले में हैं, जिन्हें चंदेल शासकों ने 950 से 1050 ई. के बीच बनवाया था।', 1, 0, 2, 'GK', 'The famous temples of Khajuraho were built by the kings of which dynasty?', 'Khajuraho temples, located in MP''s Chhatarpur district, were built by Chandela rulers between 950 and 1050 AD.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["खजुराहो समूह के मंदिर अपनी अद्भुत वास्तुकला और कामुक मूर्तियों (erotic sculptures) के लिए दुनिया भर में मशहूर हैं।","यहां हिंदू और जैन धर्म दोनों के मंदिर एक साथ मिलते हैं, जो उस समय की धार्मिक सहिष्णुता को दिखाता है।","इनमें ''कंदरिया महादेव मंदिर'' सबसे बड़ा और सबसे प्रसिद्ध है, जिसे विद्याधर चंदेल ने बनवाया था।"],"factsEn":["The Khajuraho group of monuments is world-renowned for its stunning Nagara-style architecture and intricate erotic sculptures.","You''ll find both Hindu and Jain temples coexisting here, showcasing the religious tolerance of that era.","The ''Kandariya Mahadeva Temple'' is the largest and most famous among them, built by Vidyadhara Chandela."],"mnemonics":["खजुराहो (Khajuraho) और चंदेल (Chandela) - दोनों में ''च'' और ''छ/ख'' का उच्चारण पास-पास है।"],"mnemonicsEn":["CHandela kings built the CHhatarpur temples (Khajuraho)."],"related":["छतरपुर जिला","कंदरिया महादेव मंदिर","नागर शैली वास्तुकला"],"relatedEn":["Chhatarpur District","Kandariya Mahadeva Temple","Nagara style architecture"],"memoryTip":"याद रखें: ''चंदेलों का खजाना'' = खजुराहो के मंदिर।","memoryTipEn":"Chandela''s crown jewel = Khajuraho."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('LviuiwCEU0YsT68Kb1Vgb', 'D2v-iTI2lLrB1AxLhKo1P', '''गेटवे ऑफ इंडिया'' (Gateway of India) कहाँ स्थित है?', '"[{\"id\":\"1\",\"text\":\"नई दिल्ली\",\"text_en\":\"New Delhi\"},{\"id\":\"2\",\"text\":\"मुंबई\",\"text_en\":\"Mumbai\"},{\"id\":\"3\",\"text\":\"चेन्नई\",\"text_en\":\"Chennai\"},{\"id\":\"4\",\"text\":\"कोलकाता\",\"text_en\":\"Kolkata\"}]"', '2', 'गेटवे ऑफ इंडिया मुंबई (महाराष्ट्र) में है। इसे किंग जॉर्ज पंचम के स्वागत के लिए बनवाया गया था।', 1, 0, 3, 'GK', 'Where is the ''Gateway of India'' located?', 'The Gateway of India is in Mumbai (Maharashtra). It was built to welcome King George V.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["अक्सर स्टूडेंट्स ''गेटवे ऑफ इंडिया'' और ''इंडिया गेट'' में कंफ्यूज हो जाते हैं। ''इंडिया गेट'' दिल्ली में है जो युद्ध स्मारक है।","गेटवे ऑफ इंडिया का निर्माण 1911 में ब्रिटिश सम्राट किंग जॉर्ज पंचम और क्वीन मैरी की भारत यात्रा की याद में शुरू किया गया था।","यह अरब सागर के तट पर अपोलो बंदर क्षेत्र में स्थित है। यह वही जगह है जहाँ से आखिरी ब्रिटिश सेना भारत से वापस लौटी थी।"],"factsEn":["Don''t fall for the classic trap! ''India Gate'' is a war memorial in New Delhi, while the ''Gateway of India'' is a monument in Mumbai.","It was erected to commemorate the landing of King George V and Queen Mary at Apollo Bunder on their visit to India in 1911.","Interestingly, the last British troops to leave India after independence marched through this very gateway."],"mnemonics":["समुद्र से भारत में ''एंट्री (Gateway)'' मुंबई से होती है, और ''दिल'' (Gate) दिल्ली में है।"],"mnemonicsEn":["Gateway is the ''Way'' in from the Sea (Mumbai). Gate is just a door in the capital (Delhi)."],"related":["किंग जॉर्ज V","अपोलो बंदर","इंडो-सरैसेनिक वास्तुकला"],"relatedEn":["King George V","Apollo Bunder","Indo-Saracenic architecture"],"memoryTip":"मुंबई समंदर किनारे है, इसलिए वहाँ से ''Gateway'' (रास्ता) है विदेशी जहाजों के लिए।","memoryTipEn":"Ships need a ''Gateway'' to enter, hence Mumbai."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('BEXm-K8skgHODK-3QbE91', 'D2v-iTI2lLrB1AxLhKo1P', 'अजंता की गुफाएँ (Ajanta Caves) मुख्य रूप से किस धर्म से संबंधित हैं?', '"[{\"id\":\"1\",\"text\":\"जैन धर्म\",\"text_en\":\"Jainism\"},{\"id\":\"2\",\"text\":\"हिंदू धर्म\",\"text_en\":\"Hinduism\"},{\"id\":\"3\",\"text\":\"बौद्ध धर्म\",\"text_en\":\"Buddhism\"},{\"id\":\"4\",\"text\":\"सिख धर्म\",\"text_en\":\"Sikhism\"}]"', '3', 'अजंता की गुफाएँ महाराष्ट्र में हैं और ये पूरी तरह से बौद्ध धर्म से जुड़ी रॉक-कट गुफाएँ और भित्ति चित्र (Paintings) हैं।', 1, 0, 4, 'GK', 'The Ajanta Caves are primarily associated with which religion?', 'Ajanta Caves in Maharashtra are entirely Buddhist rock-cut caves known for their exquisite mural paintings.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["अजंता में कुल 29 गुफाएँ हैं और यह सभी की सभी बौद्ध धर्म को समर्पित हैं। (ध्यान दें: एलोरा की गुफाओं में हिंदू, बौद्ध और जैन तीनों हैं)।","ये गुफाएँ महाराष्ट्र के छत्रपति संभाजीनगर (पुराना नाम औरंगाबाद) जिले में वाघोरा नदी के पास स्थित हैं।","यहाँ की पेंटिंग्स में भगवान बुद्ध के पिछले जन्मों की कहानियां यानी ''जातक कथाएं'' दर्शाई गई हैं।"],"factsEn":["There are 29 caves in Ajanta, and 100% of them are dedicated to Buddhism. (Unlike Ellora caves, which mix Hindu, Buddhist, and Jain monuments).","Located in the Chhatrapati Sambhajinagar (formerly Aurangabad) district of Maharashtra, near the Waghur river.","The world-famous fresco paintings here beautifully narrate the ''Jataka tales''—stories of the previous lives of Buddha."],"mnemonics":["अजंता = अ (A) + जंता = A-one जातक (Jataka) कथाएं (बौद्ध)।"],"mnemonicsEn":["Ajanta starts with ''A'' and is All About Buddha."],"related":["महाराष्ट्र","जातक कथाएं","वाकाटक वंश"],"relatedEn":["Maharashtra","Jataka Tales","Vakataka Dynasty"],"memoryTip":"अजंता सिर्फ बौद्ध है। एलोरा ''All'' (बौद्ध, हिंदू, जैन) है।","memoryTipEn":"Ajanta is purely Buddhist. Ellora stands for ''All'' (Buddhist, Hindu, Jain)."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('YP1eiGiPlSoETmGbKlU08', 'D2v-iTI2lLrB1AxLhKo1P', 'प्राचीन विजयनगर साम्राज्य की राजधानी ''हम्पी'' (Hampi) वर्तमान में किस राज्य में स्थित है?', '"[{\"id\":\"1\",\"text\":\"आंध्र प्रदेश\",\"text_en\":\"Andhra Pradesh\"},{\"id\":\"2\",\"text\":\"कर्नाटक\",\"text_en\":\"Karnataka\"},{\"id\":\"3\",\"text\":\"तमिलनाडु\",\"text_en\":\"Tamil Nadu\"},{\"id\":\"4\",\"text\":\"केरल\",\"text_en\":\"Kerala\"}]"', '2', 'हम्पी कर्नाटक राज्य में तुंगभद्रा नदी के किनारे स्थित है, जो कभी महान विजयनगर साम्राज्य की राजधानी हुआ करती थी।', 1, 0, 5, 'GK', 'The ancient capital of the Vijayanagara Empire, ''Hampi'', is currently located in which state?', 'Hampi is located in Karnataka on the banks of the Tungabhadra River, once the capital of the grand Vijayanagara Empire.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["हम्पी के खंडहर हमें याद दिलाते हैं कि विजयनगर साम्राज्य (14वीं शताब्दी) अपने समय का सबसे अमीर और शक्तिशाली हिंदू साम्राज्य था।","यहाँ का ''विट्ठल मंदिर'' बहुत मशहूर है, जिसमें एक ''पत्थर का रथ'' (Stone Chariot) है। यही रथ आपको ₹50 के नए नोट पर छपा हुआ मिलेगा।","इन मंदिरों का निर्माण मुख्य रूप से राजा कृष्णदेवराय के समय में हुआ था।"],"factsEn":["The ruins of Hampi stand as a testament to the Vijayanagara Empire (14th century), which was one of the richest and most powerful Hindu empires.","The ''Vitthala Temple'' here is famous for its iconic ''Stone Chariot''. You can spot this exact chariot on the back of India''s new ₹50 note.","The architectural brilliance reached its peak during the reign of the famous king Krishnadevaraya."],"mnemonics":["हम्पी में ''नाटक'' (कर्नाटक) देखने विजयनगर के राजा आते थे।"],"mnemonicsEn":["Hampi''s ancient ruins are a grand Drama (Kar-nataka)."],"related":["विजयनगर साम्राज्य","तुंगभद्रा नदी","₹50 का नोट"],"relatedEn":["Vijayanagara Empire","Tungabhadra River","₹50 currency note"],"memoryTip":"₹50 का नोट पलट कर देखिए, हम्पी का पत्थर का रथ आपकी जेब में ही है!","memoryTipEn":"Flip a ₹50 note to see Hampi''s Stone Chariot in your own pocket!"}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('t4g58vLYfgwn9TCZqSsNK', 'D2v-iTI2lLrB1AxLhKo1P', '''ब्लैक पैगोडा'' (Black Pagoda) के नाम से किसे जाना जाता है?', '"[{\"id\":\"1\",\"text\":\"मीनाक्षी मंदिर\",\"text_en\":\"Meenakshi Temple\"},{\"id\":\"2\",\"text\":\"कोणार्क का सूर्य मंदिर\",\"text_en\":\"Konark Sun Temple\"},{\"id\":\"3\",\"text\":\"जगन्नाथ मंदिर\",\"text_en\":\"Jagannath Temple\"},{\"id\":\"4\",\"text\":\"लिंगराज मंदिर\",\"text_en\":\"Lingaraja Temple\"}]"', '2', 'ओडिशा के कोणार्क सूर्य मंदिर को इसके गहरे रंग के पत्थरों और विशाल आकार के कारण यूरोपीय नाविकों द्वारा ''ब्लैक पैगोडा'' कहा जाता था।', 1, 0, 6, 'GK', 'Which monument is known as the ''Black Pagoda''?', 'The Konark Sun Temple in Odisha was called the ''Black Pagoda'' by European sailors due to its dark stone and massive structure.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["यह मंदिर 13वीं शताब्दी में पूर्वी गंग वंश के राजा नरसिंहदेव प्रथम द्वारा बनवाया गया था।","इसे भगवान सूर्य के विशाल रथ के आकार में बनाया गया है, जिसमें 24 बड़े पहिए (Stone wheels) और 7 घोड़े हैं।","यह रथ का पहिया (कोणार्क चक्र) भारतीय रिज़र्व बैंक के ₹10 के नोट के पीछे छपा हुआ है।"],"factsEn":["This architectural marvel was built in the 13th century by King Narasimhadeva I of the Eastern Ganga dynasty.","It is designed in the shape of a colossal chariot of the Sun God, complete with 24 beautifully carved stone wheels and 7 horses.","One of these iconic chariot wheels (Konark Chakra) is featured on the reverse side of the new ₹10 currency note."],"mnemonics":["सूर्य (Sun) के रथ का रंग काला (Black) नहीं है, फिर भी कोणार्क को ''ब्लैक'' पैगोडा कहते हैं।"],"mnemonicsEn":["The Sun is bright, but its grand temple in Konark is the ''Black'' Pagoda."],"related":["ओडिशा","राजा नरसिंहदेव I","₹10 का नोट"],"relatedEn":["Odisha","King Narasimhadeva I","₹10 currency note"],"memoryTip":"ब्लैक पैगोडा = कोणार्क सूर्य मंदिर। (व्हाइट पैगोडा = पुरी का जगन्नाथ मंदिर)।","memoryTipEn":"Black Pagoda = Konark Sun Temple. (White Pagoda = Jagannath Temple in Puri)."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6vyjN7vHQuBWbGHbxgC4Z', 'D2v-iTI2lLrB1AxLhKo1P', 'भीमबेटका (Bhimbetka) की गुफाएँ किस लिए प्रसिद्ध हैं?', '"[{\"id\":\"1\",\"text\":\"प्राचीन मूर्तियों के लिए\",\"text_en\":\"Ancient sculptures\"},{\"id\":\"2\",\"text\":\"प्रागैतिहासिक शैलचित्रों (रॉक पेंटिंग्स) के लिए\",\"text_en\":\"Prehistoric rock paintings\"},{\"id\":\"3\",\"text\":\"अशोक के शिलालेखों के लिए\",\"text_en\":\"Inscriptions of Ashoka\"},{\"id\":\"4\",\"text\":\"बौद्ध स्तूपों के लिए\",\"text_en\":\"Buddhist Stupas\"}]"', '2', 'मध्य प्रदेश में स्थित भीमबेटका की गुफाएँ आदिमानव द्वारा बनाए गए प्रागैतिहासिक शैलचित्रों (गुफा पेंटिंग) के लिए दुनिया भर में प्रसिद्ध हैं।', 1, 0, 7, 'GK', 'What are the Bhimbetka caves famous for?', 'Located in Madhya Pradesh, the Bhimbetka rock shelters are world-famous for their prehistoric rock paintings made by early humans.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["भीमबेटका मध्य प्रदेश के रायसेन जिले में विंध्य पर्वतमाला के निचले हिस्से में स्थित है। एमपी पुलिस के लिए यह ''स्टार'' प्रश्न है!","इन गुफाओं की खोज 1957 में मशहूर पुरातत्वविद् डॉ. वी. एस. वाकणकर (V.S. Wakankar) ने की थी।","यहाँ की पेंटिंग्स में शिकार करते हुए, नाचते हुए और जानवरों की सवारी करते हुए आदिमानव दिखाए गए हैं। कुछ चित्र 30,000 साल से भी ज्यादा पुराने हैं।"],"factsEn":["Bhimbetka is situated in the Raisen district of MP at the foothills of the Vindhya range. It''s a ''star'' question for MP state exams!","These rock shelters were discovered accidentally in 1957 by the renowned archaeologist Dr. V. S. Wakankar.","The paintings depict early humans hunting, dancing, and riding animals. Some of these artworks date back over 30,000 years."],"mnemonics":["भीम (महाभारत) बहुत ''पुराने'' हैं, वैसे ही ''भीमबेटका'' की पेंटिंग सबसे ''पुरानी'' (प्रागैतिहासिक) हैं।"],"mnemonicsEn":["Bhimbetka brings you Back to the Beginning (Prehistoric art)."],"related":["रायसेन जिला (एमपी)","डॉ. वी. एस. वाकणकर","पाषाण काल"],"relatedEn":["Raisen District (MP)","Dr. V.S. Wakankar","Stone Age"],"memoryTip":"भीमबेटका मतलब आदिमानव की ''ड्राइंग बुक''!","memoryTipEn":"Think of Bhimbetka as the ''drawing book'' of early cavemen."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('mbF1GK9VJUgi949yCiNPH', 'D2v-iTI2lLrB1AxLhKo1P', 'किस किले को भारत का ''जिब्राल्टर'' (Gibraltar of India) कहा जाता है?', '"[{\"id\":\"1\",\"text\":\"लाल किला (दिल्ली)\",\"text_en\":\"Red Fort (Delhi)\"},{\"id\":\"2\",\"text\":\"चित्तौड़गढ़ किला (राजस्थान)\",\"text_en\":\"Chittorgarh Fort (Rajasthan)\"},{\"id\":\"3\",\"text\":\"ग्वालियर किला (मध्य प्रदेश)\",\"text_en\":\"Gwalior Fort (Madhya Pradesh)\"},{\"id\":\"4\",\"text\":\"गोलकुंडा किला (तेलंगाना)\",\"text_en\":\"Golkonda Fort (Telangana)\"}]"', '3', 'ग्वालियर के किले को इसकी अजेयता (invincibility) के कारण भारत का ''जिब्राल्टर'' कहा जाता है।', 1, 0, 8, 'GK', 'Which fort is referred to as the ''Gibraltar of India''?', 'The Gwalior Fort is called the ''Gibraltar of India'' due to its formidable and invincible nature.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["यह मध्य प्रदेश का एक और महत्वपूर्ण प्रश्न है। मुगल सम्राट बाबर ने इस किले की तारीफ में इसे ''भारत के किलों के गले का मोती'' कहा था।","जिब्राल्टर स्पेन के पास एक ऐसी चट्टान/किला है जिसे जीतना असंभव माना जाता था। उसी की तर्ज पर ग्वालियर किले को यह नाम मिला।","किले के अंदर कई शानदार इमारतें हैं, जैसे मान सिंह महल, सास-बहू का मंदिर और तेली का मंदिर।"],"factsEn":["This is a massive point of pride for MP. The Mughal Emperor Babur famously described it as ''the pearl amongst fortresses in India''.","Gibraltar is a heavily fortified rock near Spain, known for being practically unconquerable. Gwalior Fort shares that tough reputation.","Inside the fort, you''ll find incredible structures like Man Singh Palace, Sas-Bahu Temple, and Teli ka Mandir."],"mnemonics":["ग्वालियर का ''ग'' और जिब्राल्टर का ''ज'' - दोनों मजबूती की मिसाल हैं।"],"mnemonicsEn":["Gwalior starts with G, Gibraltar starts with G. Both are Great stone giants."],"related":["राजा मान सिंह तोमर","ग्वालियर (मध्य प्रदेश)","तेली का मंदिर"],"relatedEn":["Raja Man Singh Tomar","Gwalior (MP)","Teli ka Mandir"],"memoryTip":"बाबर का कोट याद रखें: ''किलों का मोती'' = ग्वालियर का किला।","memoryTipEn":"Remember Babur''s quote: ''Pearl of fortresses'' = Gwalior Fort."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('w38FkCsMjWEWPJImxp_cJ', 'D2v-iTI2lLrB1AxLhKo1P', 'प्रसिद्ध ''मीनाक्षी अम्मन मंदिर'' किस नदी के तट पर स्थित है?', '"[{\"id\":\"1\",\"text\":\"कावेरी\",\"text_en\":\"Kaveri\"},{\"id\":\"2\",\"text\":\"वैगई\",\"text_en\":\"Vaigai\"},{\"id\":\"3\",\"text\":\"तुंगभद्रा\",\"text_en\":\"Tungabhadra\"},{\"id\":\"4\",\"text\":\"गोदावरी\",\"text_en\":\"Godavari\"}]"', '2', 'मीनाक्षी मंदिर तमिलनाडु के मदुरै शहर में ''वैगई'' नदी के दक्षिणी तट पर स्थित है।', 1, 0, 9, 'GK', 'The famous ''Meenakshi Amman Temple'' is situated on the banks of which river?', 'The Meenakshi Temple is located on the southern bank of the ''Vaigai'' River in the city of Madurai, Tamil Nadu.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["यह मंदिर देवी मीनाक्षी (पार्वती का रूप) और उनके पति सुंदरेश्वर (भगवान शिव) को समर्पित है।","यह द्रविड़ वास्तुकला (Dravidian architecture) का एक शानदार उदाहरण है, जिसके गोपुरम (प्रवेश द्वार) बहुत ऊंचे और रंगीन मूर्तियों से सजे हैं।","मदुरै शहर को ''त्यौहारों का शहर'' (City of Festivals) भी कहा जाता है, जहाँ यह ऐतिहासिक मंदिर स्थित है।"],"factsEn":["The temple is dedicated to Goddess Meenakshi (a form of Parvati) and her consort, Sundareshwar (Lord Shiva).","It''s a textbook example of magnificent Dravidian architecture. The temple''s ''Gopurams'' (gateway towers) are incredibly tall and covered in colorful stucco figures.","Madurai itself is often called the ''City of Festivals'', thriving around this central, historic temple."],"mnemonics":["मदुरै में ''मीना'' (मीनाक्षी) ''वैगई'' (गई) दर्शन करने।"],"mnemonicsEn":["M & M: Meenakshi is in Madurai."],"related":["मदुरै (तमिलनाडु)","द्रविड़ वास्तुकला","पांड्य राजवंश"],"relatedEn":["Madurai (Tamil Nadu)","Dravidian architecture","Pandya Dynasty"],"memoryTip":"मंदिर का नाम मीनाक्षी-सुंदरेश्वर है, शहर मदुरै है, और नदी वैगई है।","memoryTipEn":"Link these three: Madurai city, Meenakshi Temple, Vaigai River."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('zUmR9BH5CbETxi2g7un2V', 'D2v-iTI2lLrB1AxLhKo1P', 'विक्टोरिया मेमोरियल (Victoria Memorial) भारत के किस शहर की पहचान है?', '"[{\"id\":\"1\",\"text\":\"चेन्नई\",\"text_en\":\"Chennai\"},{\"id\":\"2\",\"text\":\"शिमला\",\"text_en\":\"Shimla\"},{\"id\":\"3\",\"text\":\"कोलकाता\",\"text_en\":\"Kolkata\"},{\"id\":\"4\",\"text\":\"मुंबई\",\"text_en\":\"Mumbai\"}]"', '3', 'विक्टोरिया मेमोरियल पश्चिम बंगाल की राजधानी कोलकाता में सफेद संगमरमर से बनी एक विशाल इमारत है।', 1, 0, 10, 'GK', 'The Victoria Memorial is a landmark of which Indian city?', 'The Victoria Memorial is a massive white marble building located in Kolkata, the capital of West Bengal.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["इसे महारानी विक्टोरिया की याद में बनवाया गया था। इसके निर्माण का सुझाव भारत के तत्कालीन वायसराय ''लॉर्ड कर्जन'' ने दिया था।","ताजमहल की तरह ही, इसे बनाने के लिए भी राजस्थान के मकराना से सफेद संगमरमर (Makrana marble) मंगवाया गया था।","इस इमारत के गुंबद पर ''एंजेल ऑफ विक्ट्री'' (जीत की परी) की एक कांस्य मूर्ति है जो हवा चलने पर घूमती है!"],"factsEn":["It was built to commemorate Queen Victoria. The idea for this grand monument was actually pitched by Lord Curzon, the then Viceroy of India.","Just like the Taj Mahal, the Victoria Memorial was constructed using premium white Makrana marble brought all the way from Rajasthan.","Look closely at the top dome: there''s a bronze statue called the ''Angel of Victory'' that doubles as a weather vane, spinning with the wind!"],"mnemonics":["कोलकाता (Kolkata) की रानी (Queen Victoria) का महल।"],"mnemonicsEn":["V for Victoria, located in the old Viceroy capital (Kolkata)."],"related":["लॉर्ड कर्जन","मकराना संगमरमर","हुगली नदी के पास"],"relatedEn":["Lord Curzon","Makrana Marble","Near Hooghly River"],"memoryTip":"अगर सफेद संगमरमर का महल अंग्रेजों ने बनवाया है, तो वह विक्टोरिया मेमोरियल (कोलकाता) है।","memoryTipEn":"White marble + British era + Memorial = Victoria Memorial in Kolkata."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9rXiUVcHWd0KT4k93V8Tv', 'D2v-iTI2lLrB1AxLhKo1P', 'हैदराबाद स्थित प्रसिद्ध स्मारक ''चारमीनार'' का निर्माण किसने करवाया था?', '"[{\"id\":\"1\",\"text\":\"कुली कुतुब शाह\",\"text_en\":\"Quli Qutb Shah\"},{\"id\":\"2\",\"text\":\"औरंगजेब\",\"text_en\":\"Aurangzeb\"},{\"id\":\"3\",\"text\":\"निज़ाम उल मुल्क\",\"text_en\":\"Nizam-ul-Mulk\"},{\"id\":\"4\",\"text\":\"टीपू सुल्तान\",\"text_en\":\"Tipu Sultan\"}]"', '1', 'चारमीनार का निर्माण 1591 में कुतुब शाही वंश के 5वें शासक मुहम्मद कुली कुतुब शाह ने करवाया था।', 1, 0, 11, 'GK', 'Who built the famous monument ''Charminar'' located in Hyderabad?', 'Charminar was built in 1591 by Muhammad Quli Qutb Shah, the fifth ruler of the Qutb Shahi dynasty.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["चारमीनार का निर्माण हैदराबाद शहर में प्लेग (Plague) नामक भयानक बीमारी के अंत का जश्न मनाने के लिए किया गया था।","यह स्मारक मूसी नदी के पूर्वी तट पर स्थित है।","इसमें चार भव्य मीनारें (Four Minarets) हैं जो इस्लाम के पहले चार खलीफाओं का प्रतीक मानी जाती हैं।"],"factsEn":["Charminar was built specifically to celebrate the eradication of a deadly plague epidemic from the city of Hyderabad.","This iconic square structure stands elegantly on the eastern bank of the Musi River.","As the name suggests, it has four grand minarets, which are often said to symbolize the first four caliphs of Islam."],"mnemonics":["हैदराबाद में ''कुली'' (Quli) ने ''चार'' (Char) मीनारें खड़ी कर दीं।"],"mnemonicsEn":["Quli Qutb Shah = Creator of the Quad (Four) minarets."],"related":["मूसी नदी","हैदराबाद (तेलंगाना)","प्लेग महामारी"],"relatedEn":["Musi River","Hyderabad (Telangana)","Plague epidemic"],"memoryTip":"चारमीनार = कुली कुतुब शाह = 1591। (इसे निज़ामों ने नहीं बनवाया था, ध्यान रखें!)","memoryTipEn":"Charminar = Quli Qutb Shah = 1591. (Trap: It wasn''t built by the Nizams!)."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('leySd2SbiHaeoCqtkpIOm', 'D2v-iTI2lLrB1AxLhKo1P', 'फतेहपुर सीकरी (Fatehpur Sikri) शहर की स्थापना किस मुग़ल सम्राट ने की थी?', '"[{\"id\":\"1\",\"text\":\"बाबर\",\"text_en\":\"Babur\"},{\"id\":\"2\",\"text\":\"अकबर\",\"text_en\":\"Akbar\"},{\"id\":\"3\",\"text\":\"जहाँगीर\",\"text_en\":\"Jahangir\"},{\"id\":\"4\",\"text\":\"शाहजहाँ\",\"text_en\":\"Shah Jahan\"}]"', '2', 'फतेहपुर सीकरी का निर्माण मुग़ल सम्राट अकबर ने 1571 में करवाया था और इसे अपनी राजधानी बनाया था।', 1, 0, 12, 'GK', 'Which Mughal emperor founded the city of Fatehpur Sikri?', 'Fatehpur Sikri was built by the Mughal Emperor Akbar in 1571 and served as his capital.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["अकबर ने इस शहर को सूफी संत सलीम चिश्ती के सम्मान में बसाया था, जिनके आशीर्वाद से अकबर को पुत्र (जहाँगीर) प्राप्त हुआ था।","गुजरात विजय (Victory over Gujarat) की खुशी में अकबर ने इसी शहर में विशाल ''बुलंद दरवाज़ा'' (Buland Darwaza) बनवाया था।","पानी की भारी कमी के कारण अकबर को 1585 में इस शानदार शहर को खाली करके लाहौर जाना पड़ा।"],"factsEn":["Akbar founded this city to honor the Sufi saint Salim Chishti, whose blessing supposedly led to the birth of Akbar''s heir (Jahangir).","To commemorate his massive military victory over Gujarat, Akbar constructed the towering ''Buland Darwaza'' (Gate of Magnificence) here.","Despite its grandeur, the city was practically abandoned by 1585, mainly due to a severe shortage of water, and the capital shifted to Lahore."],"mnemonics":["अकबर ने ''फतेह'' (जीत) हासिल की और ''सीकरी'' बसाया।"],"mnemonicsEn":["Fateh means Victory. Akbar got a Victory over Gujarat and built Fatehpur Sikri."],"related":["बुलंद दरवाज़ा","आगरा (उत्तर प्रदेश)","शेख सलीम चिश्ती"],"relatedEn":["Buland Darwaza","Agra (Uttar Pradesh)","Sheikh Salim Chishti"],"memoryTip":"अगर सवाल ''बुलंद दरवाज़ा'' का हो या ''फतेहपुर सीकरी'' का, जवाब ''अकबर'' ही होगा।","memoryTipEn":"Buland Darwaza and Fatehpur Sikri are both Akbar''s proud creations."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8RFCjRpKaiWSeCbYR0UyW', 'D2v-iTI2lLrB1AxLhKo1P', 'बोधगया (बिहार) में स्थित ''महाबोधि मंदिर'' क्यों प्रसिद्ध है?', '"[{\"id\":\"1\",\"text\":\"यहाँ भगवान बुद्ध का जन्म हुआ था\",\"text_en\":\"Lord Buddha was born here\"},{\"id\":\"2\",\"text\":\"यहाँ भगवान बुद्ध को ज्ञान की प्राप्ति हुई थी\",\"text_en\":\"Lord Buddha attained enlightenment here\"},{\"id\":\"3\",\"text\":\"यहाँ बुद्ध ने पहला उपदेश दिया था\",\"text_en\":\"Buddha gave his first sermon here\"},{\"id\":\"4\",\"text\":\"यहाँ बुद्ध का महापरिनिर्वाण हुआ था\",\"text_en\":\"Buddha attained Mahaparinirvana here\"}]"', '2', 'महाबोधि मंदिर उसी स्थान पर स्थित है जहाँ भगवान बुद्ध (सिद्धार्थ गौतम) को एक पीपल के पेड़ के नीचे ज्ञान (Enlightenment) प्राप्त हुआ था।', 1, 0, 13, 'GK', 'Why is the ''Mahabodhi Temple'' in Bodh Gaya (Bihar) famous?', 'The Mahabodhi Temple marks the exact spot where Lord Buddha (Siddhartha Gautama) attained enlightenment under a Peepal tree.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["यह बौद्ध धर्म के चार सबसे पवित्र स्थानों में से एक है। (बाकी तीन: लुंबिनी, सारनाथ और कुशीनगर हैं)।","जिस पेड़ के नीचे बुद्ध को ज्ञान मिला, उसे ''बोधि वृक्ष'' (Bodhi Tree) कहा जाता है। आज जो पेड़ वहाँ है, वह मूल पेड़ के वंश का ही है।","इस मंदिर को सम्राट अशोक ने बनवाया था और आज यह यूनेस्को की विश्व धरोहर सूची में शामिल है।"],"factsEn":["It is the most sacred site in Buddhism out of the four major ones. (The other three being Lumbini, Sarnath, and Kushinagar).","The tree under which he meditated is called the ''Bodhi Tree''. The tree standing there today is a direct descendant of that original Peepal tree.","The initial temple structure was built by Emperor Ashoka. Today, it stands proudly as a UNESCO World Heritage Site."],"mnemonics":["''बोध'' का मतलब ही ''ज्ञान'' होता है। इसलिए बोधगया में ज्ञान मिला।"],"mnemonicsEn":["''Bodh'' means Knowledge/Enlightenment. Bodh Gaya is where he got the Bodh."],"related":["बोधि वृक्ष (पीपल)","निरंजना नदी","बौद्ध धर्म"],"relatedEn":["Bodhi Tree (Peepal)","Niranjana River","Buddhism"],"memoryTip":"जन्म लुंबिनी में, ज्ञान बोधगया में, पहला उपदेश सारनाथ में, और मृत्यु कुशीनगर में।","memoryTipEn":"Birth: Lumbini. Enlightenment: Bodh Gaya. First Sermon: Sarnath. Death: Kushinagar."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('m8ShOqW4EBQILouKVLj2C', 'D2v-iTI2lLrB1AxLhKo1P', 'दिल्ली स्थित ''कुतुब मीनार'' (Qutub Minar) का निर्माण कार्य किसने पूरा करवाया था?', '"[{\"id\":\"1\",\"text\":\"कुतुबुद्दीन ऐबक\",\"text_en\":\"Qutb-ud-din Aibak\"},{\"id\":\"2\",\"text\":\"इल्तुतमिश\",\"text_en\":\"Iltutmish\"},{\"id\":\"3\",\"text\":\"अलाउद्दीन खिलजी\",\"text_en\":\"Alauddin Khalji\"},{\"id\":\"4\",\"text\":\"फ़िरोज़ शाह तुग़लक़\",\"text_en\":\"Firoz Shah Tughlaq\"}]"', '2', 'कुतुब मीनार की शुरुआत कुतुबुद्दीन ऐबक ने की थी, लेकिन इसका निर्माण कार्य उसके दामाद ''इल्तुतमिश'' ने पूरा करवाया था।', 1, 0, 14, 'GK', 'Who completed the construction of the ''Qutub Minar'' in Delhi?', 'The foundation was laid by Qutb-ud-din Aibak, but the construction of the Qutub Minar was completed by his son-in-law, ''Iltutmish''.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["यह ईंटों से बनी दुनिया की सबसे ऊंची मीनार है (ऊंचाई लगभग 73 मीटर)।","कुतुबुद्दीन ऐबक केवल इसकी पहली मंजिल ही बनवा पाया था। इसके बाद इल्तुतमिश ने इसमें तीन और मंजिलें जोड़ीं।","बाद में बिजली गिरने से इसकी ऊपरी मंजिल टूट गई थी, जिसकी मरम्मत फ़िरोज़ शाह तुग़लक़ ने करवाई और एक और मंजिल जोड़ दी।"],"factsEn":["It holds the record for being the tallest brick minaret in the world (about 73 meters high).","Qutb-ud-din Aibak could only finish the ground floor before he died. Iltutmish then added three more storeys to it.","Later, a lightning strike damaged the top tier. Firoz Shah Tughlaq repaired it and actually added a fifth storey."],"mnemonics":["''कुतुब'' ने शुरू किया, ''इल्तुत'' ने पूरा किया।"],"mnemonicsEn":["Aibak started the Action, Iltutmish Included the rest."],"related":["सूफी संत कुतुबुद्दीन बख्तियार काकी","लौह स्तंभ (Iron Pillar)","गुलाम वंश"],"relatedEn":["Sufi saint Qutbuddin Bakhtiar Kaki","Iron Pillar of Delhi","Slave Dynasty"],"memoryTip":"एग्जाम का ''ट्रैप'' (Trap) - अगर ''शुरुआत'' पूछे तो ऐबक, ''पूरा'' पूछे तो इल्तुतमिश।","memoryTipEn":"Classic exam trap: ''Started by'' Aibak, but ''Completed by'' Iltutmish."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('HDS7DDtebBFJ4zAt_0vBh', 'D2v-iTI2lLrB1AxLhKo1P', 'प्रसिद्ध ''सेलुलर जेल'' (Cellular Jail), जिसे काला पानी भी कहा जाता था, कहाँ स्थित है?', '"[{\"id\":\"1\",\"text\":\"लक्षद्वीप\",\"text_en\":\"Lakshadweep\"},{\"id\":\"2\",\"text\":\"गोवा\",\"text_en\":\"Goa\"},{\"id\":\"3\",\"text\":\"पोर्ट ब्लेयर (अंडमान)\",\"text_en\":\"Port Blair (Andaman)\"},{\"id\":\"4\",\"text\":\"पुदुचेरी\",\"text_en\":\"Puducherry\"}]"', '3', 'सेलुलर जेल अंडमान और निकोबार द्वीप समूह की राजधानी ''पोर्ट ब्लेयर'' में स्थित है।', 1, 0, 15, 'GK', 'Where is the famous ''Cellular Jail'', also known as Kala Pani, located?', 'The Cellular Jail is located in ''Port Blair'', the capital of the Andaman and Nicobar Islands.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["ब्रिटिश राज के दौरान इस जेल का इस्तेमाल भारतीय स्वतंत्रता सेनानियों को देश निकाला देकर कठोर सजा (काला पानी) देने के लिए किया जाता था।","इसका नाम ''सेलुलर'' इसलिए पड़ा क्योंकि इसमें केवल अलग-अलग कोठरियां (Cells) थीं, ताकि कैदी एक-दूसरे से बात न कर सकें।","प्रसिद्ध स्वतंत्रता सेनानी विनायक दामोदर सावरकर (वीर सावरकर) को यहीं बंदी बनाकर रखा गया था। आज यहाँ का एयरपोर्ट उन्हीं के नाम पर है।"],"factsEn":["During British rule, this isolated prison was used to exile and intensely punish Indian freedom fighters (a sentence dreaded as ''Kala Pani'').","It got the name ''Cellular'' because it was entirely made up of individual solitary cells, completely isolating prisoners from each other.","The famous revolutionary Vinayak Damodar Savarkar (Veer Savarkar) was imprisoned here. The Port Blair airport is now named after him."],"mnemonics":["काले पानी की ''सेल'' (Cell) अंडमान के बीचों-बीच है।"],"mnemonicsEn":["Cellular = Cells in the Sea (Andaman)."],"related":["वीर सावरकर","अंडमान और निकोबार","ब्रिटिश औपनिवेशिक काल"],"relatedEn":["Veer Savarkar","Andaman and Nicobar","British Colonial Era"],"memoryTip":"काला पानी = सेलुलर जेल = पोर्ट ब्लेयर।","memoryTipEn":"Kala Pani = Cellular Jail = Port Blair."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('hfFZbeWEyCRu-hBTwBEGG', 'D2v-iTI2lLrB1AxLhKo1P', 'अमृतसर के प्रसिद्ध ''स्वर्ण मंदिर'' (Golden Temple) का आधिकारिक नाम क्या है?', '"[{\"id\":\"1\",\"text\":\"श्री अकाल तख्त\",\"text_en\":\"Sri Akal Takht\"},{\"id\":\"2\",\"text\":\"श्री हरिमंदिर साहिब\",\"text_en\":\"Sri Harmandir Sahib\"},{\"id\":\"3\",\"text\":\"शीश महल\",\"text_en\":\"Sheesh Mahal\"},{\"id\":\"4\",\"text\":\"गुरुद्वारा बंगला साहिब\",\"text_en\":\"Gurudwara Bangla Sahib\"}]"', '2', 'स्वर्ण मंदिर का असली और आधिकारिक नाम ''श्री हरिमंदिर साहिब'' (Sri Harmandir Sahib) या ''दरबार साहिब'' है।', 1, 0, 16, 'GK', 'What is the official name of the famous ''Golden Temple'' of Amritsar?', 'The real and official name of the Golden Temple is ''Sri Harmandir Sahib'' or ''Darbar Sahib''.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["यह मंदिर सिखों का सबसे पवित्र धार्मिक स्थल है। यह पंजाब के अमृतसर शहर में एक पवित्र सरोवर के बीच में बना है।","अमृतसर शहर की स्थापना चौथे सिख गुरु, गुरु राम दास जी ने की थी, लेकिन मंदिर का निर्माण पांचवें गुरु, गुरु अर्जन देव जी ने करवाया था।","इस मंदिर की ऊपरी मंजिलों पर असली सोने की परत (Gold foil) चढ़ाने का काम महाराजा रणजीत सिंह ने 1830 में करवाया था, तभी से इसे ''स्वर्ण मंदिर'' कहा जाने लगा।"],"factsEn":["It is the holiest spiritual site of Sikhism, beautifully sitting right in the center of a sacred pool (Sarovar) in Amritsar, Punjab.","The city of Amritsar was founded by the 4th Sikh Guru, Guru Ram Das, but the temple itself was constructed by the 5th Guru, Guru Arjan Dev.","The iconic pure gold foil covering the upper floors was actually added much later, in 1830, by Maharaja Ranjit Singh."],"mnemonics":["''हरि'' का ''मंदिर'' जो सोने सा चमकता है (हरिमंदिर साहिब)।"],"mnemonicsEn":["Harmandir = The Temple of God (Hari), which shines like Gold."],"related":["गुरु अर्जन देव","महाराजा रणजीत सिंह","अमृत सरोवर"],"relatedEn":["Guru Arjan Dev","Maharaja Ranjit Singh","Amrit Sarovar"],"memoryTip":"हरिमंदिर साहिब को ही प्यार से गोल्डन टेम्पल बुलाते हैं।","memoryTipEn":"Harmandir Sahib is universally loved and called the Golden Temple."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Wqs6ZinBNiWhQwTJYxusp', 'D2v-iTI2lLrB1AxLhKo1P', 'जयपुर का प्रसिद्ध ''हवा महल'' (Hawa Mahal) किसने बनवाया था?', '"[{\"id\":\"1\",\"text\":\"सवाई जय सिंह द्वितीय\",\"text_en\":\"Sawai Jai Singh II\"},{\"id\":\"2\",\"text\":\"महाराजा सवाई प्रताप सिंह\",\"text_en\":\"Maharaja Sawai Pratap Singh\"},{\"id\":\"3\",\"text\":\"राजा मान सिंह\",\"text_en\":\"Raja Man Singh\"},{\"id\":\"4\",\"text\":\"महाराणा प्रताप\",\"text_en\":\"Maharana Pratap\"}]"', '2', 'हवा महल का निर्माण 1799 में जयपुर के महाराजा सवाई प्रताप सिंह ने करवाया था।', 1, 0, 17, 'GK', 'Who built the famous ''Hawa Mahal'' of Jaipur?', 'Hawa Mahal was built in 1799 by Maharaja Sawai Pratap Singh of Jaipur.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["हवा महल का डिज़ाइन लाल चंद उस्ताद ने बनाया था। यह इमारत भगवान कृष्ण के मुकुट के आकार में बनी है।","इसमें कुल 953 छोटी-छोटी खिड़कियां हैं जिन्हें ''झरोखे'' कहा जाता है।","इसे राजपूताना शाही महिलाओं के लिए बनवाया गया था, ताकि वे बिना किसी की नज़र में आए (पर्दा प्रथा के कारण) सड़क पर होने वाले उत्सवों और रोजमर्रा की जिंदगी को देख सकें।"],"factsEn":["The structure was designed by Lal Chand Ustad in the shape of Lord Krishna''s crown.","It features a staggering 953 small windows, intricately carved and known as ''Jharokhas''.","It was built specifically for the royal Rajput women. Due to the strict Purdah system, these windows allowed them to watch street festivals without being seen by the public."],"mnemonics":["हवा का ''प्रताप'' (तेज बहाव) महल में 953 खिड़कियों से आता है।"],"mnemonicsEn":["Pratap built the Palace (Mahal) of gentle breeze (Hawa)."],"related":["गुलाबी शहर (Pink City)","लाल चंद उस्ताद","953 झरोखे"],"relatedEn":["Pink City","Lal Chand Ustad","953 Jharokhas"],"memoryTip":"हवा महल जयपुर में है, और इसे प्रताप सिंह ने बनवाया था (जय सिंह ने नहीं, यह एग्जाम का आम फंदा है)।","memoryTipEn":"Trap alert: Jaipur was founded by Jai Singh, but Hawa Mahal was built by Pratap Singh!"}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('zaA2mOVuDW4vh6TBBF3l0', 'D2v-iTI2lLrB1AxLhKo1P', 'महाराष्ट्र की ''एलिफेंटा गुफाएँ'' (Elephanta Caves) मुख्य रूप से किस हिंदू देवता को समर्पित हैं?', '"[{\"id\":\"1\",\"text\":\"भगवान विष्णु\",\"text_en\":\"Lord Vishnu\"},{\"id\":\"2\",\"text\":\"भगवान शिव\",\"text_en\":\"Lord Shiva\"},{\"id\":\"3\",\"text\":\"भगवान ब्रह्मा\",\"text_en\":\"Lord Brahma\"},{\"id\":\"4\",\"text\":\"भगवान गणेश\",\"text_en\":\"Lord Ganesha\"}]"', '2', 'एलिफेंटा गुफाएँ मुख्य रूप से भगवान शिव को समर्पित हैं। यहाँ शिव के विभिन्न रूपों की विशाल मूर्तियां उकेरी गई हैं।', 1, 0, 18, 'GK', 'The ''Elephanta Caves'' in Maharashtra are primarily dedicated to which Hindu deity?', 'The Elephanta Caves are primarily dedicated to Lord Shiva, featuring massive stone carvings of his various forms.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["यह गुफाएँ मुंबई तट से कुछ दूर अरब सागर में ''घारापुरी द्वीप'' पर स्थित हैं।","पुर्तगालियों ने जब यहाँ एक विशाल हाथी की पत्थर की मूर्ति देखी, तो उन्होंने इस द्वीप का नाम ''एलिफेंटा'' रख दिया।","यहाँ की सबसे मशहूर मूर्ति ''त्रिमूर्ति सदाशिव'' की है, जो 20 फीट ऊंची है और इसमें भगवान शिव के तीन चेहरे (रचनाकार, रक्षक और संहारक) दिखाए गए हैं।"],"factsEn":["These caves are located on ''Gharapuri Island'' in the Arabian Sea, a short ferry ride from the Mumbai coast.","The Portuguese gave it the name ''Elephanta'' after they found a massive stone statue of an elephant near the landing area.","The star attraction here is the ''Trimurti Sadashiva''—a 20-foot tall, three-faced idol of Lord Shiva representing him as the creator, preserver, and destroyer."],"mnemonics":["एलिफेंटा में हाथी नहीं, भगवान ''शिव'' की त्रिमूर्ति है।"],"mnemonicsEn":["Name is Elephanta, but the star is Lord Shiva (Trimurti)."],"related":["घारापुरी द्वीप","त्रिमूर्ति","मुंबई (महाराष्ट्र)"],"relatedEn":["Gharapuri Island","Trimurti","Mumbai (Maharashtra)"],"memoryTip":"एलिफेंटा = शिव (त्रिमूर्ति)। अजंता = बुद्ध।","memoryTipEn":"Elephanta = Shiva (Trimurti). Ajanta = Buddha."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3P9c7dUFybDSDLv1FLSYT', 'D2v-iTI2lLrB1AxLhKo1P', 'भारतीय करेंसी के 100 रुपये के नए नोट के पीछे छपी ''रानी की वाव'' (Rani ki Vav) कहाँ स्थित है?', '"[{\"id\":\"1\",\"text\":\"राजस्थान\",\"text_en\":\"Rajasthan\"},{\"id\":\"2\",\"text\":\"गुजरात\",\"text_en\":\"Gujarat\"},{\"id\":\"3\",\"text\":\"मध्य प्रदेश\",\"text_en\":\"Madhya Pradesh\"},{\"id\":\"4\",\"text\":\"उत्तर प्रदेश\",\"text_en\":\"Uttar Pradesh\"}]"', '2', '''रानी की वाव'' एक प्रसिद्ध सीढ़ीदार कुआं (Stepwell) है जो गुजरात के पाटन शहर में स्थित है।', 1, 0, 19, 'GK', 'Where is ''Rani ki Vav'', printed on the reverse of the new ₹100 Indian currency note, located?', '''Rani ki Vav'' is a famous historical stepwell located in the town of Patan, Gujarat.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["यह 11वीं सदी का एक विशाल सीढ़ीदार कुआं है, जिसे सोलंकी राजवंश की रानी उदयमती ने अपने पति राजा भीमदेव प्रथम की याद में बनवाया था।","इसे उलटे मंदिर (Inverted Temple) के आकार में बनाया गया है, जो पानी की पवित्रता को दर्शाता है।","2014 में इसे यूनेस्को विश्व धरोहर घोषित किया गया था और 2018 में इसे ₹100 के नोट पर छापा गया।"],"factsEn":["It is a massive 11th-century stepwell commissioned by Queen Udayamati of the Solanki dynasty in memory of her husband, King Bhimdev I.","Interestingly, it is designed like an ''inverted temple'' stepping down towards the water, highlighting the sanctity of water.","It was recognized as a UNESCO World Heritage site in 2014 and proudly featured on the ₹100 banknote in 2018."],"mnemonics":["100 रुपये देकर ''गुजरात'' की ''रानी'' से पानी (वाव) मांगा।"],"mnemonicsEn":["Give 100 Rupees to see the Queen''s (Rani) stepwell in Gujarat."],"related":["पाटन (गुजरात)","सोलंकी राजवंश","सरस्वती नदी"],"relatedEn":["Patan (Gujarat)","Solanki Dynasty","Saraswati River"],"memoryTip":"₹100 का नोट = रानी की वाव (गुजरात)। ₹50 = हम्पी। ₹200 = सांची का स्तूप।","memoryTipEn":"₹100 note = Rani ki Vav (Gujarat). Link your currency notes to GK!"}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('nnVT_rugCWCqtO_Bdizjw', 'D2v-iTI2lLrB1AxLhKo1P', '''गोल गुम्बज'' (Gol Gumbaz) जो अपनी फुसफुसाती गैलरी (Whispering Gallery) के लिए प्रसिद्ध है, किस राज्य में है?', '"[{\"id\":\"1\",\"text\":\"कर्नाटक\",\"text_en\":\"Karnataka\"},{\"id\":\"2\",\"text\":\"आंध्र प्रदेश\",\"text_en\":\"Andhra Pradesh\"},{\"id\":\"3\",\"text\":\"तेलंगाना\",\"text_en\":\"Telangana\"},{\"id\":\"4\",\"text\":\"महाराष्ट्र\",\"text_en\":\"Maharashtra\"}]"', '1', 'गोल गुम्बज कर्नाटक के बीजापुर (विजयपुरा) शहर में स्थित है।', 1, 0, 20, 'GK', 'In which state is the ''Gol Gumbaz'', famous for its Whispering Gallery, located?', 'The Gol Gumbaz is located in the city of Bijapur (Vijayapura) in Karnataka.', 60, 'standard', NULL, NULL, '{"explanation":{"gk_science":{"facts":["यह बीजापुर के सुल्तान ''मोहम्मद आदिल शाह'' का मकबरा (Tomb) है। इसका गुंबद दुनिया के सबसे बड़े गुंबदों में से एक है।","इसकी सबसे बड़ी खासियत इसकी ''व्हिस्परिंग गैलरी'' (Whispering Gallery) है। यहाँ अगर आप बहुत धीरे से भी फुसफुसाते हैं, तो आवाज गैलरी के दूसरे छोर पर साफ़ सुनाई देती है!","यहाँ एक ताली बजाने पर उसकी गूंज (Echo) 7 से 10 बार तक सुनाई देती है। यह वास्तुकला (Acoustics) का एक अद्भुत चमत्कार है।"],"factsEn":["This monumental structure is the mausoleum (tomb) of Mohammed Adil Shah, the Sultan of Bijapur. Its dome is one of the largest in the world.","Its biggest flex is the ''Whispering Gallery''. If you whisper quietly on one side, the sound perfectly travels and can be heard on the exact opposite side!","A single clap here echoes multiple times (around 7 to 10 times). It''s a genuine marvel of acoustic engineering."],"mnemonics":["कर्नाटक के ''बीज'' (बीजापुर) से बड़ा ''गोल'' गुम्बज निकला।"],"mnemonicsEn":["Bijapur built a Big Dome (Gol Gumbaz) in Karnataka."],"related":["बीजापुर (विजयपुरा)","आदिल शाही वंश","मोहम्मद आदिल शाह"],"relatedEn":["Bijapur (Vijayapura)","Adil Shahi Dynasty","Mohammed Adil Shah"],"memoryTip":"गोल गुम्बज (मकबरा) कर्नाटक में है, जबकि गोलकोंडा (किला) तेलंगाना में है। कंफ्यूज मत होना!","memoryTipEn":"Trap: Gol Gumbaz is a tomb in Karnataka. Golkonda is a fort in Telangana."}}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('DISZSKQFU5hW5s0IziytM', '2DXBWqHiYJFoR0eKfWzav', 'राष्ट्रीय किशोर स्वास्थ्य कार्यक्रम में किस आयु वर्ग के बच्चे/किशोर सम्मिलित हैं?', '"[\"8 से 15 वर्ष (8 to 15 years)\",\"8 से 17 वर्ष (8 to 17 years)\",\"9 से 16 वर्ष (9 to 16 years)\",\"10 से 19 वर्ष (10 to 19 years)\"]"', '3.0', '✅ सही तर्क: स्वास्थ्य और परिवार कल्याण मंत्रालय द्वारा शुरू किए गए ''राष्ट्रीय किशोर स्वास्थ्य कार्यक्रम'' (RKSK) में 10 से 19 वर्ष की आयु के किशोरों को लक्षित किया गया है।
💡 परीक्षा तथ्य: यह कार्यक्रम 2014 में शुरू किया गया था और इसमें पोषण, यौन स्वास्थ्य और मानसिक स्वास्थ्य पर ध्यान केंद्रित किया गया है।
🧠 स्मृति टिप: किशोर (Teenager) की उम्र = 10 (pre-teen) से 19 (nineteen) तक।
🚫 स्कैम अलर्ट: WHO के अनुसार भी किशोरावस्था की आधिकारिक परिभाषा 10-19 वर्ष ही है।', 2, 0, 1, 'Health/Schemes', 'Which age group of children/adolescents is included in Rashtriya Kishor Swasthya Karyakram?', '✅ Correct Logic: The Rashtriya Kishor Swasthya Karyakram (RKSK) specifically targets adolescents in the age group of 10 to 19 years.
💡 Exam Fact: Launched by the Ministry of Health in 2014, the program focuses on nutrition, reproductive health, and substance abuse among teens.
🧠 Memory Tip: Adolescence universally spans from double digits (10) to the last ''teen'' (19).
🚫 Scam Alert: The WHO formally defines adolescents as individuals aged 10-19 years; any other option scientifically violates this standard.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('jL76cqH7TR1rVljySBudh', '2DXBWqHiYJFoR0eKfWzav', 'विधि एवं न्याय मंत्रालय, भारत सरकार द्वारा भारत के राजपत्र में प्रकाशित ''द बायोलॉजिकल डाइवर्सिटी (अमेंडमेंट) एक्ट'' [जैव विविधता (संशोधन) अधिनियम], 2023 किस दिनांक को प्रकाशित किया गया था?', '"[\"13 जून (13th June)\",\"03 जुलाई (03rd July)\",\"03 अगस्त (03rd August)\",\"13 सितम्बर (13th September)\"]"', '2.0', '✅ सही तर्क: जैव विविधता (संशोधन) अधिनियम 2023 को भारत के राजपत्र में 3 अगस्त 2023 को अधिसूचित और प्रकाशित किया गया था।
💡 परीक्षा तथ्य: यह संशोधन मूल ''जैव विविधता अधिनियम 2002'' में किया गया है ताकि आयुष चिकित्सकों और शोधकर्ताओं के लिए नियमों को सरल बनाया जा सके।
🧠 स्मृति टिप: विविधता (Biodiversity) = अगस्त (3 अगस्त) का महीना।
🚫 स्कैम अलर्ट: राजपत्र (Gazette) प्रकाशन की तिथियाँ एमपीपीएससी के कठिन प्रश्नों में से एक हैं, इन्हें रटना ही एकमात्र उपाय है।', 2, 0, 2, 'Environment/Current Affairs', 'The Biological Diversity (Amendment) Act, 2023 published in the Gazette of India by the Ministry of Law and Justice, Government of India, was published on which date?', '✅ Correct Logic: The Biological Diversity (Amendment) Act, 2023 received the President''s assent and was officially published in the Gazette of India on August 3, 2023.
💡 Exam Fact: The amendment relaxes several stringent provisions of the original 2002 Act to encourage Ayurvedic practitioners and domestic research.
🧠 Memory Tip: Bio-Diversity Act = Born in August (03).
🚫 Scam Alert: MPPSC is notorious for asking exact gazette publication dates for new environmental or tribal laws. Do not rely on guesses.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1urx3XZTcrJxLajg4rbbv', '2DXBWqHiYJFoR0eKfWzav', 'नेशनल डिजास्टर रिस्पाँस फोर्स एकेडमी (राष्ट्रीय आपदा मोचन बल अकादमी) की स्थापना किस शहर में की गई थी?', '"[\"नागपुर (Nagpur)\",\"कानपुर (Kanpur)\",\"भरतपुर (Bharatpur)\",\"शिमला (Shimla)\"]"', '0.0', '✅ सही तर्क: NDRF (राष्ट्रीय आपदा मोचन बल) की राष्ट्रीय अकादमी 2018 में नागपुर (महाराष्ट्र) में स्थापित की गई थी।
💡 परीक्षा तथ्य: नागपुर में राष्ट्रीय अग्निशमन सेवा महाविद्यालय (NFSC) और नागरिक सुरक्षा कॉलेज भी स्थित हैं, जिससे यह आपदा प्रबंधन प्रशिक्षण का केंद्र बन गया है।
🧠 स्मृति टिप: आपदा आने पर ''नाग'' (नागपुर) की तरह फुर्ती से रिस्पांस (NDRF)।
🚫 स्कैम अलर्ट: शिमला में बहुत भूस्खलन होते हैं, लेकिन एकेडमी केंद्रीय भारत (नागपुर) में है ताकि सभी दिशाओं में आसानी से पहुँचा जा सके।', 2, 0, 3, 'Institutions/Disaster Management', 'In which city was the National Disaster Response Force Academy established in the year 2018?', '✅ Correct Logic: The National Disaster Response Force (NDRF) Academy, a premier training institute for disaster management, was established in Nagpur, Maharashtra in 2018.
💡 Exam Fact: Nagpur was chosen because it already houses the National Fire Service College and Civil Defence training centers.
🧠 Memory Tip: A central location (Nagpur) is best for a national quick-response force.
🚫 Scam Alert: Don''t link disaster academies to disaster-prone areas like Shimla; training centers are usually in logistically central hubs.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('x3awTEc5h5YvDVEn2k65F', '2DXBWqHiYJFoR0eKfWzav', 'डॉ. विष्णु श्रीधर वाकणकर ने भीमबेटका के शैलाश्रयों की खोज कब की?', '"[\"1951-1952\",\"1954-1955\",\"1960-1961\",\"1957-1958\"]"', '3.0', '✅ सही तर्क: डॉ. वी.एस. वाकणकर ने 1957-58 में रायसेन जिले में स्थित भीमबेटका की प्रसिद्ध प्रागैतिहासिक गुफाओं की खोज की थी।
💡 परीक्षा तथ्य: भीमबेटका को 2003 में यूनेस्को (UNESCO) की विश्व धरोहर स्थल सूची में शामिल किया गया था।
🧠 स्मृति टिप: 1857 की क्रांति के ठीक 100 साल बाद (1957) भीमबेटका मिला।
🚫 स्कैम अलर्ट: 1957-58 बहुत विशिष्ट वर्ष है, इसे सांची या खजुराहो की खोज (जो बहुत पहले हुई थी) से न मिलाएं।', 2, 0, 4, 'MP History/Archaeology', 'When did Dr. Vishnu Shridhar Wakankar discover the rock shelters of Bhimbetka?', '✅ Correct Logic: The pre-historic rock shelters of Bhimbetka were discovered accidentally by archaeologist Dr. V.S. Wakankar in 1957-1958 while he was traveling to Bhopal.
💡 Exam Fact: These rock shelters boast cave paintings that are up to 30,000 years old and were designated a UNESCO World Heritage Site in 2003.
🧠 Memory Tip: Discovered exactly 100 years after the 1857 mutiny (1957).
🚫 Scam Alert: Standard MPPSC trap is giving closely clustered 1950s dates; lock in 1957-58 in your memory.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('89Sz9S-ErMFvJWFEYE9Tk', '2DXBWqHiYJFoR0eKfWzav', '"राष्ट्रीय सिकल सेल एनीमिया उन्मूलन मिशन" ने किस वर्ष तक सिकल सेल एनीमिया को भारत से समाप्त करने का लक्ष्य निर्धारित किया है?', '"[\"2032\",\"2037\",\"2042\",\"2047\"]"', '3.0', '✅ सही तर्क: भारत सरकार ने ''राष्ट्रीय सिकल सेल एनीमिया उन्मूलन मिशन'' के तहत वर्ष 2047 (जब भारत अपनी आजादी के 100 वर्ष मनाएगा) तक इस बीमारी को जड़ से खत्म करने का लक्ष्य रखा है।
💡 परीक्षा तथ्य: इस मिशन की शुरुआत प्रधानमंत्री ने जुलाई 2023 में मध्य प्रदेश के शहडोल जिले से की थी।
🧠 स्मृति टिप: आजादी का शताब्दी वर्ष (1947 + 100 = 2047) = सिकल सेल से आजादी।
🚫 स्कैम अलर्ट: टीबी (TB) उन्मूलन का लक्ष्य 2025 है और मलेरिया का 2030, बीमारियों के लक्ष्यों को आपस में न मिलाएँ।', 2, 0, 5, 'Health/Current Affairs', 'By which year has "National Sickle Cell Anaemia Elimination Mission" fixed the target to eliminate sickle cell anaemia from India?', '✅ Correct Logic: The National Sickle Cell Anaemia Elimination Mission aims to completely eradicate the genetic blood disorder from India by the year 2047.
💡 Exam Fact: The mission was officially launched by PM Modi in July 2023 from Shahdol, Madhya Pradesh, a heavily tribal-populated district.
🧠 Memory Tip: 100 years of Independence (2047) = Independence from Sickle Cell.
🚫 Scam Alert: Do not confuse this long-term genetic disease target with communicable disease targets like TB (2025) or Malaria (2030).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('OcKdA1BXUWKNRPeSFwIRJ', '2DXBWqHiYJFoR0eKfWzav', 'उचेहरा कांस्य शिल्प का बड़ा केन्द्र है। उचेहरा मध्यप्रदेश के किस जिले में स्थित है?', '"[\"बालाघाट (Balaghat)\",\"सतना (Satna)\",\"सिवनी (Seoni)\",\"खण्डवा (Khandwa)\"]"', '1.0', '✅ सही तर्क: उचेहरा (Uchehara), जो ठठेरा समुदाय द्वारा बनाए जाने वाले पारंपरिक कांस्य (कांसा/पीतल) शिल्प के लिए प्रसिद्ध है, सतना जिले में स्थित है।
💡 परीक्षा तथ्य: मध्य प्रदेश सरकार के ''एक जिला एक उत्पाद'' (ODOP) के तहत भी सतना का यह शिल्प बहुत महत्वपूर्ण है।
🧠 स्मृति टिप: उचेहरा = ''सतना'' का चमकता कांसा।
🚫 स्कैम अलर्ट: बालाघाट तांबे के लिए प्रसिद्ध है, लेकिन ''कांस्य शिल्प'' (हस्तशिल्प) का केंद्र सतना का उचेहरा है।', 2, 0, 6, 'MP Culture/Economy', 'Uchehara is a large centre of bronze craft. In which district of Madhya Pradesh is Uchehara located?', '✅ Correct Logic: Uchehara is a renowned hub for traditional bronze and brass metal craft (made by the Thathera community) and is located in the Satna district of MP.
💡 Exam Fact: This craft is heavily promoted by the state government under artisan welfare schemes and the ODOP initiative.
🧠 Memory Tip: Uchehara brings Bronze glory to Satna.
🚫 Scam Alert: Balaghat is the mining capital for copper ore, but the specific ''handicraft'' of bronze vessels is Satna''s specialty.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('k56W5eNuYDOeHeNpUf_g4', '2DXBWqHiYJFoR0eKfWzav', 'बाघ (जिला धार) की किस गुफा को ''रंग महल'' कहा जाता है?', '"[\"दूसरी (Second)\",\"तीसरी (Third)\",\"चौथी (Fourth)\",\"आठवीं (Eighth)\"]"', '2.0', '✅ सही तर्क: धार जिले की बाघ गुफाओं में ''गुफा नंबर 4'' को अपने अद्भुत और रंगीन भित्ति चित्रों (mural paintings) के कारण ''रंग महल'' (Rang Mahal) कहा जाता है।
💡 परीक्षा तथ्य: बाघ में कुल 9 गुफाएं थीं। गुफा नंबर 2 को ''पांडव गुफा'' और गुफा नंबर 3 को ''हाथी खाना'' कहा जाता है।
🧠 स्मृति टिप: 4 दिशाओं में ''रंग'' बिखरे हैं (चौथी गुफा)।
🚫 स्कैम अलर्ट: बाघ गुफाएं बौद्ध धर्म से संबंधित हैं; इन्हें अजंता की गुफाओं के समकालीन माना जाता है।', 2, 0, 7, 'MP Art & Culture', 'Which cave of Bagh (District Dhar) is called ''Rang Mahal''?', '✅ Correct Logic: Cave Number 4 of the Bagh Caves in Dhar district is famously known as the ''Rang Mahal'' (Palace of Colors) because of its exquisite and vibrant mural paintings.
💡 Exam Fact: The Bagh Caves originally had 9 rock-cut monuments. Cave 2 is known as ''Pandava Cave'' and Cave 3 as ''Hathikhana''.
🧠 Memory Tip: The 4 walls of Cave 4 are full of ''Rang'' (Colors).
🚫 Scam Alert: Do not mix the names up. Cave 2 = Pandava, Cave 3 = Elephant, Cave 4 = Color Palace.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('rR4MjCy8UuCOlNBufCFL4', '2DXBWqHiYJFoR0eKfWzav', 'इनमें से कौन-सी दो श्रेणियों के मध्य नीलगिरि पहाड़ियाँ स्थित हैं?', '"[\"हिमालय और अरावली (Himalayan and Aravalli)\",\"विन्ध्याचल और सतपुड़ा (Vindhyachal and Satpura)\",\"सहयाद्रि (पश्चिमी घाट) एवं पूर्वी घाट (Sahyadris (Western Ghats) and Eastern Ghats)\",\"सतपुड़ा और अरावली (Satpura and Aravalli)\"]"', '2.0', '✅ सही तर्क: नीलगिरि की पहाड़ियाँ दक्षिण भारत में वह भौगोलिक गांठ (Junction) हैं जहाँ सहयाद्रि (पश्चिमी घाट) और पूर्वी घाट आकर मिलते हैं।
💡 परीक्षा तथ्य: नीलगिरि की सबसे ऊँची चोटी ''डोडाबेट्टा'' (Doddabetta) है।
🧠 स्मृति टिप: नीलगिरि = पूरब और पश्चिम का ''मिलन स्थल''।
🚫 स्कैम अलर्ट: विन्ध्याचल और सतपुड़ा मध्य भारत में हैं, जबकि नीलगिरि पूरी तरह से सुदूर दक्षिण (तमिलनाडु/केरल) में है।', 2, 0, 8, 'Geography', 'The Nilgiri Hills are located between which of these two ranges?', '✅ Correct Logic: The Nilgiri Hills (Blue Mountains) form a geographical knot in southern India where the Sahyadris (Western Ghats) seamlessly merge with the Eastern Ghats.
💡 Exam Fact: The highest peak in the Nilgiri hills is Doddabetta (2,637 meters).
🧠 Memory Tip: Nilgiri is the ''Belt'' that ties the East and West coasts together.
🚫 Scam Alert: Vindhyachal and Satpura form the central dividing line of India, completely unrelated to the deep southern Nilgiri ranges.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('90hKfx4adbWzSELzwJJFT', '2DXBWqHiYJFoR0eKfWzav', 'छतरपुर के चरण पादुका गोली कांड में भीड़ पर गोली चलाने का आदेश किसने दिया?', '"[\"जी.टी. फिशर (G.T. Fisher)\",\"आसबर्न (Asburn)\",\"मेजर गाँसेन (Major Gausan)\",\"मेजर टिमनिस (Major Timnis)\"]"', '0.0', '✅ सही तर्क: 14 जनवरी 1931 (मकर संक्रांति) को छतरपुर के चरण पादुका में शांतिपूर्ण सभा कर रहे लोगों पर ब्रिटिश अधिकारी ''कर्नल फिशर'' (G.T. Fisher) ने अंधाधुंध गोलियां चलाने का आदेश दिया था।
💡 परीक्षा तथ्य: इस दर्दनाक घटना को ''मध्य प्रदेश का जलियांवाला बाग हत्याकांड'' कहा जाता है।
🧠 स्मृति टिप: जलियांवाला में ''डायर'' था, MP में ''फिशर'' था।
🚫 स्कैम अलर्ट: यह घटना उर्मिल नदी के तट पर हुई थी, इसे किसी अन्य रियासत के विद्रोह से न मिलाएं।', 2, 0, 9, 'MP History', 'In Chhatarpur''s Charan Paduka firing incident, who gave the order to open fire on the crowd?', '✅ Correct Logic: On Makar Sankranti (Jan 14, 1931), Political Agent G.T. Fisher ordered his forces to open unprovoked machine-gun fire on a peaceful gathering of freedom fighters at Charan Paduka in Chhatarpur.
💡 Exam Fact: Due to its sheer brutality, this massacre is widely recorded in history as the ''Jallianwala Bagh tragedy of Madhya Pradesh''.
🧠 Memory Tip: Fisher ''fished'' for innocent lives in MP''s Jallianwala.
🚫 Scam Alert: Do not confuse Fisher with General Dyer; Dyer is national, Fisher is specific to MP''s history.', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('_ueEyXizcdA0OqFXYxjmu', '2DXBWqHiYJFoR0eKfWzav', 'टूरिया जंगल सत्याग्रह का नेतृत्व किसने किया?', '"[\"ठाकुर मोहकम सिंह (Thakur Mohkam Singh)\",\"रामू गोंड (Ramu Gond)\",\"गंजन सिंह कोरकू (Ganjan Singh Korku)\",\"मूका लोहार (Mooka Lohar)\"]"', '3.0', '✅ सही तर्क: 1930 में सिवनी जिले के टूरिया में जंगल सत्याग्रह हुआ था, जिसका जमीनी नेतृत्व आदिवासी नेता ''मूका लोहार'' ने किया था, जहाँ पुलिस फायरिंग में कई आदिवासी शहीद हुए।
💡 परीक्षा तथ्य: इस सत्याग्रह की मूल शुरुआत कांग्रेस नेता ''दुर्गा शंकर मेहता'' ने की थी, लेकिन जन-नेतृत्व मूका लोहार का था। गंजन सिंह कोरकू ''घोड़ाडोंगरी'' (बैतूल) जंगल सत्याग्रह के नेता थे।
🧠 स्मृति टिप: टूरिया में ''लोहे'' (लोहार) जैसी हिम्मत दिखाई।
🚫 स्कैम अलर्ट: गंजन सिंह कोरकू को टूरिया से न जोड़ें, वे बैतूल के घोड़ाडोंगरी सत्याग्रह के नायक थे।', 2, 0, 10, 'MP History', 'Who led the Turiya Jungle Satyagraha?', '✅ Correct Logic: The Turiya Jungle Satyagraha took place in Seoni district in 1930. The grassroots tribal leadership during the protests and subsequent police firing was heavily driven by ''Mooka Lohar''.
💡 Exam Fact: While Durga Shankar Mehta initiated the political movement here, Mooka Lohar is remembered as the primary tribal hero of this specific incident. Ganjan Singh Korku is associated with the Ghoradongri satyagraha in Betul.
🧠 Memory Tip: Turiya required ''Iron'' (Lohar) will.
🚫 Scam Alert: Always separate the two famous 1930 jungle satyagrahas: Turiya (Seoni/Mooka Lohar) and Ghoradongri (Betul/Ganjan Singh Korku).', 60, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('_FcE_7EKZDQg1hpaVLi-V', 'tJwAn-g7aOPlKmJdxgPNG', '450 का 20% क्या होगा?', '"[{\"id\":\"1\",\"text\":\"90\",\"text_en\":\"90\"},{\"id\":\"2\",\"text\":\"80\",\"text_en\":\"80\"},{\"id\":\"3\",\"text\":\"100\",\"text_en\":\"100\"},{\"id\":\"4\",\"text\":\"110\",\"text_en\":\"110\"}]"', '1', 'प्रतिशत का मतलब होता है प्रति 100। 450 को 20/100 से गुणा करने पर 90 प्राप्त होता है।', 1, 0, 1, 'Quantitative Aptitude', 'What is 20% of 450?', 'Percent means out of 100. Multiplying 450 by 20/100 gives 90.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: हमें 450 का 20% निकालना है।","अब ध्यान से देखो, 20% को हम भिन्न में 20/100 लिख सकते हैं।","जिसे छोटा करने पर यह 1/5 बन जाता है।","अब 450 को 1/5 से गुणा कर दो: 450 × (1/5) = 90।"],"stepsEn":["Start by writing down the problem: we need 20% of 450.","Notice that 20% is exactly the same as the fraction 20/100.","Which simplifies neatly to 1/5.","Now just multiply 450 by 1/5. So, 450 × (1/5) = 90."],"shortcut":"किसी भी संख्या का 10% निकालने के लिए दाहिने से एक अंक के बाद दशमलव लगाओ (450 का 10% = 45)। 20% उसका दोगुना होगा (45 × 2 = 90)।","shortcutEn":"To find 10% of any number, move the decimal one place to the left (10% of 450 = 45). Double it for 20% (45 × 2 = 90).","trap":"जल्दबाजी में 450 को सीधा 20 से गुणा मत कर देना, यह प्रतिशत है, इसलिए 100 से भाग देना जरूरी है।","trapEn":"Don''t just multiply 450 by 20 and forget the percentage! You must divide by 100.","memoryTip":"बुनियादी भिन्न याद रखो: 20% = 1/5, 25% = 1/4, 50% = 1/2।","memoryTipEn":"Memorize common fractions: 20% = 1/5, 25% = 1/4, 50% = 1/2. It speeds up everything."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Z1da-8LF3-c0KWRX52_S8', 'tJwAn-g7aOPlKmJdxgPNG', 'एक वस्तु की कीमत 500 रुपये से बढ़कर 600 रुपये हो गई। कीमत में कितने प्रतिशत की वृद्धि हुई?', '"[{\"id\":\"1\",\"text\":\"10%\",\"text_en\":\"10%\"},{\"id\":\"2\",\"text\":\"20%\",\"text_en\":\"20%\"},{\"id\":\"3\",\"text\":\"25%\",\"text_en\":\"25%\"},{\"id\":\"4\",\"text\":\"15%\",\"text_en\":\"15%\"}]"', '2', '100 रुपये की वृद्धि 500 रुपये के आधार पर हुई है, इसलिए (100/500) × 100 = 20% की वृद्धि हुई।', 1, 0, 2, 'Quantitative Aptitude', 'The price of an article increased from Rs. 500 to Rs. 600. What is the percentage increase in the price?', 'An increase of Rs. 100 over the base of Rs. 500 means (100/500) × 100 = 20% increase.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: पुरानी कीमत = 500 रुपये, नई कीमत = 600 रुपये।","अब ध्यान से देखो, कीमत में वृद्धि कितनी हुई? 600 - 500 = 100 रुपये।","इसका मतलब हमें 100 रुपये की वृद्धि को प्रतिशत में बदलना है। प्रतिशत हमेशा पुरानी (मूल) कीमत पर निकलता है।","प्रतिशत वृद्धि = (वृद्धि / पुरानी कीमत) × 100","= (100 / 500) × 100 = (1 / 5) × 100 = 20%।"],"stepsEn":["Start by writing the given values: Old price = 500, New price = 600.","Find the actual increase: 600 - 500 = 100.","Remember, percentage changes are always calculated on the ORIGINAL price, not the new one.","Percentage Increase = (Increase / Old Price) × 100","= (100 / 500) × 100 = (1 / 5) × 100 = 20%."],"shortcut":"500 का 10% 50 होता है। 100 रुपये बढ़ने का मतलब है 50 का दोगुना, यानी 20% की वृद्धि।","shortcutEn":"10% of 500 is 50. An increase of 100 is double that, which means a 20% increase.","trap":"छात्र अक्सर 600 पर प्रतिशत निकाल देते हैं (100/600), जिससे गलत उत्तर 16.66% आ सकता है।","trapEn":"Students often calculate the percentage on the new price (100/600) getting a wrong answer of 16.66%.","memoryTip":"वृद्धि या कमी % = (अंतर / शुरुआती मान) × 100। शुरुआती मान हमेशा नीचे आता है।","memoryTipEn":"Change % = (Difference / Initial Value) × 100. The initial value is always the denominator."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4H5m0kuF1v6YXg7QyZCHc', 'tJwAn-g7aOPlKmJdxgPNG', 'एक टीवी की कीमत पहले 10% घटाई गई, फिर 20% घटाई गई। कुल कितने प्रतिशत की कमी हुई?', '"[{\"id\":\"1\",\"text\":\"30%\",\"text_en\":\"30%\"},{\"id\":\"2\",\"text\":\"28%\",\"text_en\":\"28%\"},{\"id\":\"3\",\"text\":\"32%\",\"text_en\":\"32%\"},{\"id\":\"4\",\"text\":\"25%\",\"text_en\":\"25%\"}]"', '2', 'क्रमिक छूट के लिए 100 से शुरुआत करें: पहले 10% की कमी (90), फिर 90 पर 20% की कमी (18 कम)। कुल 28% की कमी।', 1, 0, 3, 'Quantitative Aptitude', 'The price of a TV was decreased by 10% and then again by 20%. What is the total percentage decrease?', 'For successive discounts, start with 100: a 10% drop gives 90, then a 20% drop on 90 (18 less) gives 72. Total drop is 28%.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["मान लेते हैं कि टीवी की शुरुआती कीमत 100 रुपये थी।","पहले 10% की कमी हुई। 100 का 10% = 10 रुपये। तो नई कीमत हो गई 90 रुपये।","अब ध्यान से देखो, दूसरी कमी 20% की है, लेकिन ये 90 रुपये पर लगेगी, 100 पर नहीं।","90 का 20% = 18 रुपये।","अंतिम कीमत = 90 - 18 = 72 रुपये।","इसका मतलब 100 रुपये की चीज़ 72 की हो गई। कुल कमी = 100 - 72 = 28%।"],"stepsEn":["Let''s assume the initial price of the TV was Rs. 100.","First, there''s a 10% decrease. 10% of 100 is 10. The new price becomes 90.","Now look closely, the second 20% decrease applies to the NEW price (90), not the original 100.","20% of 90 is 18.","The final price = 90 - 18 = 72.","So, something worth 100 is now 72. Total decrease = 100 - 72 = 28%."],"shortcut":"सक्सेसिव फॉर्मूला (a + b + ab/100) का उपयोग करें: -10 - 20 + ((-10)(-20)/100) = -30 + 2 = -28% (यानी 28% कमी)।","shortcutEn":"Use the successive formula (a + b + ab/100): -10 - 20 + ((-10)(-20)/100) = -30 + 2 = -28% (meaning a 28% decrease).","trap":"सबसे बड़ी गलती: 10% + 20% को सीधा जोड़कर 30% उत्तर दे देना। प्रतिशत कभी सीधे नहीं जुड़ते।","trapEn":"The biggest trap: directly adding 10% + 20% to get 30%. Successive percentages never add up directly.","memoryTip":"लगातार बदलाव (Successive Change) दिखे तो 100 मानकर हल करना सबसे सुरक्षित तरीका है।","memoryTipEn":"Whenever you see ''successive changes'', assuming the base as 100 is the safest route."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7s2rLufxtjPstZtiNO3-1', 'tJwAn-g7aOPlKmJdxgPNG', 'एक चुनाव में दो उम्मीदवार थे। जीतने वाले को 60% वोट मिले और वह 400 वोटों से जीत गया। कुल कितने वोट पड़े?', '"[{\"id\":\"1\",\"text\":\"1000\",\"text_en\":\"1000\"},{\"id\":\"2\",\"text\":\"2000\",\"text_en\":\"2000\"},{\"id\":\"3\",\"text\":\"1500\",\"text_en\":\"1500\"},{\"id\":\"4\",\"text\":\"2500\",\"text_en\":\"2500\"}]"', '2', 'जीतने वाले को 60% मिले, तो हारने वाले को 40%। दोनों का अंतर 20% है, जो 400 वोटों के बराबर है। अतः 100% = 2000।', 1, 0, 4, 'Quantitative Aptitude', 'There were two candidates in an election. The winner got 60% of the votes and won by 400 votes. How many total votes were cast?', 'Winner gets 60%, loser gets 40%. The difference is 20%, which equals 400 votes. Thus, 100% = 2000.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: कुल वोट हमेशा 100% होते हैं।","जीतने वाले उम्मीदवार को मिले = 60% वोट।","इसका मतलब हारने वाले को कितने मिले होंगे? 100% - 60% = 40% वोट।","अब ध्यान से देखो, जीत का अंतर इन दोनों के वोटों का अंतर होता है। अंतर = 60% - 40% = 20%।","सवाल कहता है कि वह 400 वोटों से जीता। यानी यही 20% का अंतर 400 के बराबर है (20% = 400)।","अगर 20% = 400 है, तो 1% = 20। इसलिए कुल वोट (100%) = 20 × 100 = 2000।"],"stepsEn":["Start by writing: Total votes are always 100%.","The winning candidate received 60% of the votes.","So, what did the losing candidate get? 100% - 60% = 40% of the votes.","Look closely, the margin of victory is the difference between their votes. Difference = 60% - 40% = 20%.","The problem says he won by 400 votes. This means that 20% difference equals 400 votes (20% = 400).","If 20% = 400, then 1% = 20. Therefore, total votes (100%) = 20 × 100 = 2000."],"shortcut":"सीधे सोचें: 60% और 40% का अंतर 20% है। 20% मतलब 1/5 होता है। 1/5 = 400, तो कुल = 400 × 5 = 2000।","shortcutEn":"Think quickly: The gap between 60% and 40% is 20%. 20% is 1/5th. If 1/5th = 400, total = 400 × 5 = 2000.","trap":"कई बार छात्र 60% = 400 मान लेते हैं। लेकिन 400 कुल वोट नहीं हैं, वह ''जीत का अंतर'' है।","trapEn":"A common mistake is assuming 60% = 400. But 400 is the ''margin of victory'', not the winner''s total votes.","memoryTip":"चुनाव वाले सवालों में हमेशा ''जीत-हार का अंतर'' प्रतिशत के अंतर के बराबर रखो।","memoryTipEn":"In election problems, always equate the ''margin of votes'' to the difference in their vote percentages."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('aQfy6ErjdJt79mwyn0ivm', 'tJwAn-g7aOPlKmJdxgPNG', 'यदि A का वेतन B से 25% अधिक है, तो B का वेतन A से कितने प्रतिशत कम है?', '"[{\"id\":\"1\",\"text\":\"25%\",\"text_en\":\"25%\"},{\"id\":\"2\",\"text\":\"20%\",\"text_en\":\"20%\"},{\"id\":\"3\",\"text\":\"15%\",\"text_en\":\"15%\"},{\"id\":\"4\",\"text\":\"30%\",\"text_en\":\"30%\"}]"', '2', 'B को 100 मान लें, तो A 125 होगा। B, A से 25 कम है। यह कमी A (125) पर निकलेगी: (25/125)×100 = 20%।', 1, 0, 5, 'Quantitative Aptitude', 'If A''s salary is 25% more than B''s, then B''s salary is what percentage less than A''s?', 'Assume B is 100, so A is 125. B is 25 less than A. Calculated on A (125): (25/125)×100 = 20%.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: तुलना किससे हो रही है? शुरुआत में B से।","मान लेते हैं कि B का वेतन 100 रुपये है।","A का वेतन B से 25% अधिक है, तो A का वेतन हो गया 125 रुपये।","अब सवाल पूछ रहा है कि B, A से कितना कम है? अंतर 25 रुपये का ही है।","लेकिन अब ध्यान से देखो, तुलना ''A से'' हो रही है। इसलिए आधार (base) में A का वेतन आएगा।","प्रतिशत कमी = (25 / 125) × 100 = (1 / 5) × 100 = 20%।"],"stepsEn":["Start by identifying the base of comparison. Initially, it''s compared to B.","Let''s assume B''s salary is Rs. 100.","A''s salary is 25% more, making A''s salary Rs. 125.","Now, how much less is B than A? The difference is still Rs. 25.","But look closely: the comparison now is ''than A''. So A''s salary becomes the new base.","Percentage less = (25 / 125) × 100 = (1 / 5) × 100 = 20%."],"shortcut":"ऐसे सवालों के लिए फॉर्मूला: [R / (100 + R)] × 100. यहाँ R = 25 है। [25 / (100 + 25)] × 100 = (25 / 125) × 100 = 20%।","shortcutEn":"Use the formula: [R / (100 + R)] × 100. Here R = 25. [25 / (100 + 25)] × 100 = (25 / 125) × 100 = 20%.","trap":"सबसे आम गलती: अगर A 25% ज्यादा है, तो B 25% कम होगा। यह गलत है क्योंकि प्रतिशत हमेशा ''आधार'' (base) पर निर्भर करता है।","trapEn":"The most common error: assuming if A is 25% more, B must be 25% less. It''s false because the base value changes.","memoryTip":"तुलना करते समय जिसके साथ ''से'' (than) लगा हो, वो हमेशा बटे (denominator) में नीचे आता है।","memoryTipEn":"Whenever comparing, the value attached to the word ''than'' always goes in the denominator."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('IPikgZ3vXS_ycB3XtOuAX', 'tJwAn-g7aOPlKmJdxgPNG', 'एक छात्र को पास होने के लिए 40% अंक चाहिए। उसे 150 अंक मिले और वह 10 अंकों से फेल हो गया। अधिकतम अंक क्या हैं?', '"[{\"id\":\"1\",\"text\":\"400\",\"text_en\":\"400\"},{\"id\":\"2\",\"text\":\"500\",\"text_en\":\"500\"},{\"id\":\"3\",\"text\":\"300\",\"text_en\":\"300\"},{\"id\":\"4\",\"text\":\"450\",\"text_en\":\"450\"}]"', '1', 'पास होने के लिए 150 + 10 = 160 अंक चाहिए थे, जो 40% के बराबर हैं। यदि 40% = 160, तो 100% = 400 होगा।', 1, 0, 6, 'Quantitative Aptitude', 'A student needs 40% marks to pass. He gets 150 marks and fails by 10 marks. What are the maximum marks?', 'Passing marks are 150 + 10 = 160, which equals 40%. If 40% = 160, then 100% = 400.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: छात्र को 150 अंक मिले हैं।","वह 10 अंकों से फेल हो गया। इसका मतलब क्या है? अगर उसे 10 अंक और मिल जाते, तो वह पास हो जाता।","तो, पास होने के लिए जरूरी अंक = 150 + 10 = 160 अंक।","अब सवाल में दिया है कि पास होने के लिए 40% अंक चाहिए।","इसका सीधा सा मतलब है कि 40% अंक ही 160 अंकों के बराबर हैं (40% = 160)।","तो 1% = 160 / 40 = 4 अंक।","अधिकतम अंक हमेशा 100% होते हैं, इसलिए 100% = 4 × 100 = 400 अंक।"],"stepsEn":["Start by writing what you know: The student scored 150 marks.","He failed by 10 marks. What does that mean? If he had just 10 more marks, he would have passed.","So, the exact passing marks = 150 + 10 = 160 marks.","The problem also states that passing requires 40% of the total marks.","This means 40% is exactly equal to 160 marks (40% = 160).","If 40% = 160, then 1% = 160 / 40 = 4 marks.","Maximum marks are always 100%, so 100% = 4 × 100 = 400 marks."],"shortcut":"40% = 160. दोनों तरफ 4 से भाग दो: 10% = 40. फिर एक जीरो लगा दो: 100% = 400.","shortcutEn":"40% = 160. Divide both sides by 4 to get 10% = 40. Just add a zero to both sides: 100% = 400.","trap":"फेल होने वाले 10 अंकों को 150 में से घटा मत देना। पास होने के लिए अंक जोड़ने पड़ेंगे।","trapEn":"Don''t subtract the 10 failing marks from 150. You need to ADD them to reach the passing threshold.","memoryTip":"ऐसे सवालों में एक ही समीकरण बनाओ: प्राप्त अंक + फेल वाले अंक = पासिंग प्रतिशत।","memoryTipEn":"In such problems, form a simple equation: Marks obtained + Marks failed by = Passing Percentage."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('r9WhjlZ0FCTBK2gwhPnyf', 'tJwAn-g7aOPlKmJdxgPNG', 'चीनी की कीमत में 25% की वृद्धि हो जाने पर, एक परिवार को अपनी खपत कितने प्रतिशत कम करनी चाहिए ताकि खर्च न बढ़े?', '"[{\"id\":\"1\",\"text\":\"25%\",\"text_en\":\"25%\"},{\"id\":\"2\",\"text\":\"20%\",\"text_en\":\"20%\"},{\"id\":\"3\",\"text\":\"16.66%\",\"text_en\":\"16.66%\"},{\"id\":\"4\",\"text\":\"30%\",\"text_en\":\"30%\"}]"', '2', 'मान लें खर्च 100 था, अब 125 हो गया। खर्च वापस 100 करने के लिए 25 की कमी करनी होगी। (25/125)×100 = 20%।', 1, 0, 7, 'Quantitative Aptitude', 'If the price of sugar increases by 25%, by what percentage should a family reduce its consumption so that the expenditure does not increase?', 'Assume initial cost was 100, now 125. To go back to 100, reduce by 25 on a base of 125: (25/125)×100 = 20%.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले मान लो कि परिवार 100 रुपये की चीनी खाता था।","अब कीमत 25% बढ़ गई, तो वही चीनी अब 125 रुपये की मिलेगी।","लेकिन परिवार ने तय किया है कि खर्च सिर्फ 100 रुपये ही रखना है।","इसका मतलब उन्हें 125 रुपये से वापस 100 रुपये पर आना है, यानी 25 रुपये का सामान कम खरीदना होगा।","अब ध्यान से देखो, ये 25 रुपये की कमी ''नई कीमत'' यानी 125 पर होगी।","प्रतिशत कमी = (25 / 125) × 100 = (1 / 5) × 100 = 20%।"],"stepsEn":["Let''s assume the family used to spend Rs. 100 on sugar.","With a 25% price increase, the same amount of sugar now costs Rs. 125.","But the family wants to keep their spending strictly at Rs. 100.","This means they have to cut back from 125 down to 100—a reduction of 25 in value.","Look closely: this reduction must be calculated on the NEW price base of 125.","Percentage reduction = (25 / 125) × 100 = (1 / 5) × 100 = 20%."],"shortcut":"फॉर्मूला: [R / (100 + R)] × 100. यहाँ 25% वृद्धि है, तो [25 / 125] × 100 = 20% खपत कम करनी होगी।","shortcutEn":"Formula: [R / (100 + R)] × 100. Since price increased by 25%, it''s [25 / 125] × 100 = 20% reduction in consumption.","trap":"कीमत 25% बढ़ी है तो खपत 25% ही कम होगी, ऐसा सोचना बहुत बड़ी गलती है।","trapEn":"Thinking that a 25% price hike means a 25% consumption cut is a classic trap. The base shifts.","memoryTip":"अगर कोई चीज़ 1/4 (25%) से बढ़ती है, तो उसे बैलेंस करने के लिए 1/5 (20%) से घटाना पड़ता है।","memoryTipEn":"If something increases by a fraction of 1/4 (25%), balance it by decreasing it by 1/5 (20%)."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('gsarr0fxGlpB2y02Gt7Xz', 'tJwAn-g7aOPlKmJdxgPNG', 'एक गाँव की जनसंख्या 10,000 है। यदि यह 10% प्रति वर्ष की दर से बढ़ती है, तो 2 वर्ष बाद जनसंख्या क्या होगी?', '"[{\"id\":\"1\",\"text\":\"12000\",\"text_en\":\"12000\"},{\"id\":\"2\",\"text\":\"12100\",\"text_en\":\"12100\"},{\"id\":\"3\",\"text\":\"11000\",\"text_en\":\"11000\"},{\"id\":\"4\",\"text\":\"12500\",\"text_en\":\"12500\"}]"', '2', 'चक्रवृद्धि (compound) नियम से: 10,000 × (110/100) × (110/100) = 12,100।', 1, 0, 8, 'Quantitative Aptitude', 'The population of a village is 10,000. If it increases at the rate of 10% per annum, what will be the population after 2 years?', 'Using compound growth: 10,000 × (110/100) × (110/100) = 12,100.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: वर्तमान जनसंख्या = 10,000।","पहले साल 10% की वृद्धि होगी। 10,000 का 10% = 1,000।","तो 1 साल बाद जनसंख्या हो जाएगी: 10,000 + 1,000 = 11,000।","अब ध्यान से देखो, दूसरे साल की वृद्धि इस नई जनसंख्या (11,000) पर होगी।","दूसरे साल 11,000 का 10% = 1,100।","तो 2 साल बाद कुल जनसंख्या = 11,000 + 1,100 = 12,100।"],"stepsEn":["Start by noting the current population = 10,000.","In the first year, it grows by 10%. 10% of 10,000 = 1,000.","So after 1 year, the population becomes: 10,000 + 1,000 = 11,000.","Now look closely, the second year''s growth happens on this NEW population (11,000).","In the second year, 10% of 11,000 = 1,100.","Total population after 2 years = 11,000 + 1,100 = 12,100."],"shortcut":"सीधा गुणांक (Multiplier) लगाओ: 10% वृद्धि मतलब 1.1 गुना। 2 साल के लिए: 10000 × 1.1 × 1.1 = 12100।","shortcutEn":"Use a multiplier: 10% growth means multiplying by 1.1. For 2 years: 10000 × 1.1 × 1.1 = 12100.","trap":"सीधे 10% + 10% = 20% निकालकर 12,000 उत्तर मत देना, जनसंख्या वृद्धि चक्रवृद्धि (compound) होती है।","trapEn":"Don''t just add 10% + 10% = 20% to get 12,000. Population growth is always compounded.","memoryTip":"जनसंख्या वाले सवालों में हमेशा चक्रवृद्धि ब्याज (Compound Interest) का कॉन्सेप्ट काम करता है।","memoryTipEn":"Population growth problems always use the concept of Compound Interest."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('zAJDPGLB02o90tNVrSkz1', 'tJwAn-g7aOPlKmJdxgPNG', 'किसी संख्या का 15%, 45 है। वह संख्या क्या है?', '"[{\"id\":\"1\",\"text\":\"250\",\"text_en\":\"250\"},{\"id\":\"2\",\"text\":\"350\",\"text_en\":\"350\"},{\"id\":\"3\",\"text\":\"300\",\"text_en\":\"300\"},{\"id\":\"4\",\"text\":\"400\",\"text_en\":\"400\"}]"', '3', 'यदि 15% का मान 45 है, तो 1% का मान 3 होगा। इसलिए 100% (वह संख्या) 300 होगी।', 1, 0, 9, 'Quantitative Aptitude', '15% of a number is 45. What is the number?', 'If 15% equals 45, then 1% equals 3. Therefore, 100% (the whole number) is 300.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: मान लो वह अनजान संख्या x है।","सवाल कहता है कि x का 15% = 45 है।","इसे हम ऐसे लिख सकते हैं: x × (15 / 100) = 45।","अब ध्यान से देखो, हमें x निकालना है। 15 को उधर ले जाकर भाग कर दो।","x = 45 × (100 / 15)","15 से 45 तीन बार में कटेगा। तो x = 3 × 100 = 300।"],"stepsEn":["Start by writing an equation: Let the unknown number be x.","The problem says 15% of x = 45.","We can write this as: x × (15 / 100) = 45.","Now look closely, we need to isolate x. Move the fraction to the other side.","x = 45 × (100 / 15)","15 goes into 45 exactly three times. So, x = 3 × 100 = 300."],"shortcut":"ऐकिक नियम (Unitary method) का कमाल: 15 हिस्से = 45, तो 1 हिस्सा = 3। कुल 100 हिस्से = 300।","shortcutEn":"Unitary method magic: 15 parts = 45, so 1 part = 3. The whole 100 parts = 300.","trap":"गलती से 45 का 15% मत निकाल देना, सवाल में पूछा है कि 45 ''किसका'' 15% है।","trapEn":"Don''t accidentally calculate 15% of 45. The question asks ''of what number'' is 45 the 15%.","memoryTip":"जब भी ''संख्या क्या है'' पूछा जाए, तो समझो कि 100% का मान निकालना है।","memoryTipEn":"Whenever asked ''what is the number'', you are always solving for the 100% value."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7hTbShZcgepbhNaqGOm3l', 'tJwAn-g7aOPlKmJdxgPNG', '3/5 को प्रतिशत में कैसे लिखेंगे?', '"[{\"id\":\"1\",\"text\":\"40%\",\"text_en\":\"40%\"},{\"id\":\"2\",\"text\":\"60%\",\"text_en\":\"60%\"},{\"id\":\"3\",\"text\":\"50%\",\"text_en\":\"50%\"},{\"id\":\"4\",\"text\":\"75%\",\"text_en\":\"75%\"}]"', '2', 'किसी भी भिन्न को प्रतिशत में बदलने के लिए उसे 100 से गुणा किया जाता है। (3/5) × 100 = 60%।', 1, 0, 10, 'Quantitative Aptitude', 'How to write 3/5 as a percentage?', 'To convert any fraction into a percentage, multiply it by 100. (3/5) × 100 = 60%.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: दी गई भिन्न 3/5 है।","प्रतिशत का मतलब होता है ''100 में से कितना''।","अब ध्यान से देखो, भिन्न को प्रतिशत में बदलने का सीधा नियम है: 100 से गुणा कर दो।","तो, (3/5) × 100।","5 से 100 को काटोगे तो 20 आएगा।","फिर 3 को 20 से गुणा कर दो: 3 × 20 = 60%।"],"stepsEn":["Start by writing the fraction given: 3/5.","Percentage simply means ''how much out of 100''.","Notice the rule to convert a fraction to a percent: just multiply by 100.","So, (3/5) × 100.","Divide 100 by 5, which gives you 20.","Then multiply by the numerator 3: 3 × 20 = 60%."],"shortcut":"आधार याद रखो: 1/5 = 20%। तो 3/5 इसका तीन गुना होगा, यानी 20% × 3 = 60%।","shortcutEn":"Remember the base: 1/5 = 20%. So 3/5 is three times that, which is 20% × 3 = 60%.","trap":"कैलकुलेशन में 5 को 3 से भाग देकर 0.6 पर ही मत रुक जाना, प्रतिशत के लिए 100 से गुणा जरूरी है।","trapEn":"Don''t just divide 3 by 5 to get 0.6 and stop. You must multiply by 100 for the percentage.","memoryTip":"प्रतिशत हटाना हो तो 100 से भाग दो, प्रतिशत लगाना हो तो 100 से गुणा करो।","memoryTipEn":"To remove a percent sign, divide by 100. To attach a percent sign, multiply by 100."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('_6j-XGCjOUE_34vIvXY-K', 'tJwAn-g7aOPlKmJdxgPNG', 'दो संख्याएं एक तीसरी संख्या से क्रमशः 20% और 50% अधिक हैं। पहली संख्या दूसरी संख्या का कितने प्रतिशत है?', '"[{\"id\":\"1\",\"text\":\"80%\",\"text_en\":\"80%\"},{\"id\":\"2\",\"text\":\"75%\",\"text_en\":\"75%\"},{\"id\":\"3\",\"text\":\"85%\",\"text_en\":\"85%\"},{\"id\":\"4\",\"text\":\"70%\",\"text_en\":\"70%\"}]"', '1', 'तीसरी संख्या 100 मानें। पहली 120 होगी, दूसरी 150 होगी। पहली दूसरी का (120/150)×100 = 80% है।', 1, 0, 11, 'Quantitative Aptitude', 'Two numbers are respectively 20% and 50% more than a third number. What percentage is the first number of the second number?', 'Let 3rd number be 100. 1st is 120, 2nd is 150. The 1st as a % of 2nd is (120/150)×100 = 80%.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: तुलना ''तीसरी संख्या'' से हो रही है। तो सबसे आसान है कि तीसरी संख्या को 100 मान लें।","पहली संख्या 20% अधिक है, यानी 100 + 20 = 120।","दूसरी संख्या 50% अधिक है, यानी 100 + 50 = 150।","अब सवाल पूछ रहा है: पहली संख्या (120), दूसरी संख्या (150) का कितना प्रतिशत है?","अब ध्यान से देखो, तुलना दूसरी संख्या (150) से हो रही है, तो वह नीचे आएगी।","प्रतिशत = (120 / 150) × 100","इसे काटेंगे: 120/150 = 4/5। और (4/5) × 100 = 80%।"],"stepsEn":["Start by writing: Since everything is compared to a ''third number'', let''s assume it is 100.","The first number is 20% more, so it becomes 100 + 20 = 120.","The second number is 50% more, making it 100 + 50 = 150.","The question asks: What percentage is the first number (120) of the second (150)?","Notice that the base of comparison is the second number (150), so it goes in the denominator.","Percentage = (120 / 150) × 100.","Simplify it: 120/150 = 4/5. And (4/5) × 100 = 80%."],"shortcut":"सीधे अनुपात निकालें: 120 और 150 का अनुपात 4:5 है। 4, 5 का 80% होता है।","shortcutEn":"Quick ratio check: 120 and 150 have a ratio of 4:5. And 4 is exactly 80% of 5.","trap":"छात्र अक्सर 150 और 120 का अंतर (30) निकाल कर प्रतिशत निकाल देते हैं, लेकिन सवाल में ''कितना प्रतिशत अधिक/कम'' नहीं पूछा है।","trapEn":"Students often find the difference (30) and calculate percentage on that, but the question doesn''t ask ''how much more/less''.","memoryTip":"जिसके साथ ''का'' (of) लगा हो, वो हमेशा आधार (denominator) बनता है।","memoryTipEn":"In ''What % is A of B'', the word ''of'' points to the base. So B goes in the denominator."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ldsX5ABFcsOWdIZ5q6FbS', 'tJwAn-g7aOPlKmJdxgPNG', 'एक आयत की लंबाई 20% बढ़ाई जाती है और चौड़ाई 10% कम की जाती है। उसके क्षेत्रफल में क्या प्रभाव पड़ेगा?', '"[{\"id\":\"1\",\"text\":\"8% वृद्धि\",\"text_en\":\"8% Increase\"},{\"id\":\"2\",\"text\":\"8% कमी\",\"text_en\":\"8% Decrease\"},{\"id\":\"3\",\"text\":\"10% वृद्धि\",\"text_en\":\"10% Increase\"},{\"id\":\"4\",\"text\":\"10% कमी\",\"text_en\":\"10% Decrease\"}]"', '1', 'क्षेत्रफल = लंबाई × चौड़ाई। फॉर्मूला (a + b + ab/100) का उपयोग करें: 20 - 10 + (20 × -10)/100 = 10 - 2 = +8% (वृद्धि)।', 1, 0, 12, 'Quantitative Aptitude', 'The length of a rectangle is increased by 20% and its breadth is decreased by 10%. What will be the effect on its area?', 'Area = L × B. Use the successive formula (a + b + ab/100): 20 - 10 + (20 × -10)/100 = 10 - 2 = +8% (Increase).', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: मान लो आयत का शुरुआती क्षेत्रफल 100 था।","लंबाई 20% बढ़ी: तो प्रभाव 100 से बढ़कर 120 हो गया।","अब चौड़ाई 10% कम हुई। अब ध्यान से देखो, ये 10% की कमी 120 पर लगेगी।","120 का 10% = 12।","तो नया क्षेत्रफल = 120 - 12 = 108।","शुरुआत में क्षेत्रफल 100 था, अब 108 है। इसका मतलब 8% की वृद्धि हुई।"],"stepsEn":["Start by writing: Let''s assume the initial area of the rectangle was 100.","Length increased by 20%: So the effect pushes it from 100 to 120.","Now the breadth drops by 10%. Look closely, this 10% drop applies to the 120.","10% of 120 = 12.","So the new area = 120 - 12 = 108.","It started at 100 and is now 108. That''s a clear 8% increase."],"shortcut":"सक्सेसिव फॉर्मूला सबसे तेज़ है: x + y + (xy/100)। x = 20, y = -10। 20 - 10 - (200/100) = 8%।","shortcutEn":"The successive formula is fastest here: x + y + (xy/100). x = 20, y = -10. 20 - 10 - (200/100) = +8%.","trap":"लंबाई 20% बढ़ी और चौड़ाई 10% घटी, तो सीधा 20 - 10 = 10% वृद्धि मत मान लेना।","trapEn":"Don''t just subtract the percentages linearly (20 - 10 = 10%). 2D area changes are multiplicative.","memoryTip":"2D आकृतियों (आयत, वर्ग, वृत्त) में प्रतिशत बदलाव हमेशा सक्सेसिव (a+b+ab/100) होता है।","memoryTipEn":"Percentage changes in 2D figures (rectangles, squares, circles) are always successive."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('AwlCZzq4ePHGblONuIv9I', 'tJwAn-g7aOPlKmJdxgPNG', 'एक छात्र ने एक संख्या को 5/3 के बजाय 3/5 से गुणा कर दिया। उत्तर में कितने प्रतिशत की त्रुटि हुई?', '"[{\"id\":\"1\",\"text\":\"44%\",\"text_en\":\"44%\"},{\"id\":\"2\",\"text\":\"64%\",\"text_en\":\"64%\"},{\"id\":\"3\",\"text\":\"54%\",\"text_en\":\"54%\"},{\"id\":\"4\",\"text\":\"34%\",\"text_en\":\"34%\"}]"', '2', 'सही मान 5/3 था, गलत 3/5। त्रुटि = (5/3) - (3/5) = 16/15। प्रतिशत = (त्रुटि / सही मान) × 100 = 64%।', 1, 0, 13, 'Quantitative Aptitude', 'A student multiplied a number by 3/5 instead of 5/3. What is the percentage error in the calculation?', 'True value = 5/3, Wrong = 3/5. Error = (5/3) - (3/5) = 16/15. Error % = (Error / True Value) × 100 = 64%.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो, सवाल को आसान बनाने के लिए हम वो संख्या 15 मान लेते हैं (3 और 5 का LCM)।","सही गुणांक 5/3 था। तो सही उत्तर आना चाहिए था: 15 × (5/3) = 25।","पर गलती से 3/5 से गुणा कर दिया। तो गलत उत्तर आया: 15 × (3/5) = 9।","अब ध्यान से देखो, त्रुटि (गलती) कितनी हुई? 25 - 9 = 16 की गलती।","त्रुटि प्रतिशत हमेशा ''सही उत्तर'' पर निकाला जाता है।","त्रुटि % = (16 / 25) × 100 = 16 × 4 = 64%।"],"stepsEn":["Start by writing a smart assumption: Let the number be 15 (LCM of denominators 3 and 5) to avoid fractions.","True multiplier was 5/3. So correct answer should be: 15 × (5/3) = 25.","But it was multiplied by 3/5. So the wrong answer came out as: 15 × (3/5) = 9.","Look closely, what''s the magnitude of the error? 25 - 9 = 16.","Percentage error is always calculated on the ''True Value'' (which is 25).","Error % = (16 / 25) × 100 = 16 × 4 = 64%."],"shortcut":"भिन्न के क्रॉस-मल्टीप्लिकेशन से सोचें: (5×5) = 25 आना चाहिए था, पर (3×3) = 9 आया। 16 की कमी 25 पर = 64%।","shortcutEn":"Think via cross-multiplication: It should have been (5×5)=25, but became (3×3)=9. A gap of 16 over a base of 25 = 64%.","trap":"त्रुटि को गलत मान (9) से भाग मत देना, प्रतिशत हमेशा जो ''होना चाहिए था'' उस पर निकलता है।","trapEn":"Don''t divide the error by the wrong value (9). Percentage error is always based on what ''should have been''.","memoryTip":"ऐसे सवालों में हर (denominators) का LCM लेकर संख्या मान लेने से कैलकुलेशन बहुत तेज़ हो जाती है।","memoryTipEn":"Assuming a number that is the LCM of the denominators makes the calculation fraction-free and super fast."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('E0dj1QWBTwkPNqlu60dy3', 'tJwAn-g7aOPlKmJdxgPNG', 'राम अपनी आय का 20% भोजन पर खर्च करता है और शेष का 50% किराए पर। यदि उसके पास 4000 रुपये बचते हैं, तो उसकी कुल आय क्या है?', '"[{\"id\":\"1\",\"text\":\"10000\",\"text_en\":\"10000\"},{\"id\":\"2\",\"text\":\"8000\",\"text_en\":\"8000\"},{\"id\":\"3\",\"text\":\"12000\",\"text_en\":\"12000\"},{\"id\":\"4\",\"text\":\"15000\",\"text_en\":\"15000\"}]"', '1', 'आय 100 मानें। भोजन पर 20 गया, बचा 80। अब 80 का 50% किराए पर गया, यानी 40 बचा। 40% = 4000 तो 100% = 10000।', 1, 0, 14, 'Quantitative Aptitude', 'Ram spends 20% of his income on food and 50% of the remaining on rent. If he still has Rs. 4000 left, what is his total income?', 'Let income be 100. 20 spent on food, 80 left. 50% of 80 (which is 40) on rent. 40 left. 40% = 4000, so 100% = 10000.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: मान लेते हैं राम की कुल आय 100 रुपये है।","उसने 20% भोजन पर खर्च किया। तो 100 - 20 = 80 रुपये बच गए।","अब ध्यान से देखो, किराए पर खर्च कुल आय का नहीं, ''शेष'' (Remaining) का 50% है।","80 रुपये का 50% = 40 रुपये (किराए पर खर्च)।","तो अब उसके पास अंत में कितने बचे? 80 - 40 = 40 रुपये।","सवाल के अनुसार उसके पास 4000 रुपये बचते हैं। इसका मतलब हमारी 40 की वैल्यू 4000 के बराबर है (40 = 4000)।","अगर 40 = 4000 है, तो 1 = 100। कुल आय (100) = 100 × 100 = 10000।"],"stepsEn":["Start by writing: Let Ram''s total income be Rs. 100.","He spends 20% on food. So he is left with 100 - 20 = 80.","Now look closely, the rent is 50% of the ''REMAINING'' amount, not the total.","50% of 80 = 40 (spent on rent).","How much is he finally left with? 80 - 40 = 40.","The problem says he has 4000 left. This means our 40 units equal 4000 (40 = 4000).","If 40 = 4000, then 1 unit = 100. So, total income (100 units) = 100 × 100 = 10000."],"shortcut":"सीधा समीकरण (Successive deduction): आय × (80/100) × (50/100) = 4000। इसे हल करने पर आय 10000 आ जाएगी।","shortcutEn":"Straight successive deduction equation: Income × (80/100) × (50/100) = 4000. Solving this gives Income = 10000.","trap":"20% + 50% = 70% खर्च मानकर 30% = 4000 मत कर देना। ''शेष का'' (Of the remaining) शब्द बहुत अहम है।","trapEn":"Don''t just add 20% + 50% = 70% spent and equate 30% = 4000. The phrase ''of the remaining'' is crucial.","memoryTip":"जब भी ''शेष का'' (of remaining) लिखा हो, तो बचे हुए प्रतिशत का गुणा करते हुए आगे बढ़ें।","memoryTipEn":"Whenever you see ''of the remaining'', just keep multiplying by the unspent percentages sequentially."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('GoVUeTAmeDFPR2godDum8', 'tJwAn-g7aOPlKmJdxgPNG', '40 लीटर दूध और पानी के मिश्रण में 10% पानी है। इसमें कितना पानी और मिलाया जाए ताकि नए मिश्रण में 20% पानी हो जाए?', '"[{\"id\":\"1\",\"text\":\"4 लीटर\",\"text_en\":\"4 liters\"},{\"id\":\"2\",\"text\":\"5 लीटर\",\"text_en\":\"5 liters\"},{\"id\":\"3\",\"text\":\"6 लीटर\",\"text_en\":\"6 liters\"},{\"id\":\"4\",\"text\":\"8 लीटर\",\"text_en\":\"8 liters\"}]"', '2', 'दूध की मात्रा समान रहेगी। पहले दूध 36 ली (90%) था। नए मिश्रण में यह 80% होगा। 80% = 36 तो 100% = 45 ली। कुल 5 ली पानी मिला।', 1, 0, 15, 'Quantitative Aptitude', 'A 40-liter mixture of milk and water contains 10% water. How much more water must be added to make it 20% water in the new mixture?', 'Milk quantity remains constant. Initially milk is 36L (90%). In new mix, it''s 80%. If 80% = 36L, 100% = 45L. Added 5L water.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: शुरुआत में हमारे पास 40 लीटर मिश्रण है।","इसमें 10% पानी है, यानी 40 का 10% = 4 लीटर पानी है।","इसका मतलब दूध कितना है? 40 - 4 = 36 लीटर दूध।","अब ध्यान से देखो, हम सिर्फ पानी मिला रहे हैं। दूध की मात्रा (36 लीटर) बिल्कुल नहीं बदलेगी।","नए मिश्रण में हमें 20% पानी चाहिए, जिसका मतलब है कि बाकी 80% दूध होगा।","तो, नए मिश्रण का 80% = 36 लीटर।","इसलिए 100% (नया कुल मिश्रण) = (36 / 80) × 100 = 45 लीटर।","पहले मिश्रण 40 लीटर था, अब 45 लीटर है। यानी हमने 5 लीटर पानी मिलाया है।"],"stepsEn":["Start by writing: Initially, we have a 40-liter mixture.","It has 10% water, which means 10% of 40 = 4 liters of water.","This implies the rest is milk: 40 - 4 = 36 liters of milk.","Look closely, we are ONLY adding water. The quantity of milk (36 liters) stays exactly the same.","In the new mixture, we want 20% water, which means the remaining 80% must be milk.","So, 80% of the NEW mixture = 36 liters.","Therefore, 100% (the total new mixture) = (36 / 80) × 100 = 45 liters.","The mixture went from 40 liters to 45 liters. We added 5 liters of water."],"shortcut":"जो नहीं बदल रहा (दूध), उसे बराबर कर दो: 40 × 90% = NewMix × 80%। NewMix = 45 लीटर। 40 से 45 मतलब 5 लीटर मिलाया।","shortcutEn":"Equate what doesn''t change (milk): 40 × 90% = NewMix × 80%. NewMix = 45 liters. 40 to 45 means 5 liters added.","trap":"पानी को सीधे 10% से 20% करने के लिए 4 लीटर मत जोड़ देना, क्योंकि पानी मिलाने से कुल मिश्रण भी बढ़ जाता है।","trapEn":"Don''t just add 4 liters thinking it will double the water percentage. Adding water increases the total mixture volume too.","memoryTip":"मिश्रण के सवालों में हमेशा उस चीज़ पर फोकस करो जिसे ''नहीं'' मिलाया जा रहा है, उसकी मात्रा दोनों तरफ बराबर होती है।","memoryTipEn":"In mixture problems, always focus on the component that is NOT being added; its absolute quantity remains constant."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('CIYMzFV5lQnCqO7Sawio-', 'tJwAn-g7aOPlKmJdxgPNG', 'यदि P का 50% = Q का 25% है, तो P = Q का x% है। x का मान क्या है?', '"[{\"id\":\"1\",\"text\":\"50\",\"text_en\":\"50\"},{\"id\":\"2\",\"text\":\"100\",\"text_en\":\"100\"},{\"id\":\"3\",\"text\":\"25\",\"text_en\":\"25\"},{\"id\":\"4\",\"text\":\"200\",\"text_en\":\"200\"}]"', '1', 'P × 50 = Q × 25 => P = Q / 2। चूँकि 1/2 का मतलब 50% होता है, इसलिए P, Q का 50% है। x = 50।', 1, 0, 16, 'Quantitative Aptitude', 'If 50% of P = 25% of Q, then P = x% of Q. What is the value of x?', 'P × 50 = Q × 25 => P = Q / 2. Since 1/2 means 50%, P is 50% of Q. Therefore, x = 50.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: समीकरण दिया है, P का 50% = Q का 25%।","इसे गणित की भाषा में लिखें: P × (50 / 100) = Q × (25 / 100)।","अब ध्यान से देखो, दोनों तरफ 100 से 100 कट जाएगा। बचेगा: 50P = 25Q।","हमें P का मान Q के रूप में चाहिए, तो P को अकेला छोड़ें: P = (25 / 50) × Q।","यानी P = (1 / 2) × Q।","हम जानते हैं कि 1/2 को प्रतिशत में 50% कहते हैं। इसलिए P = Q का 50% है। x का मान 50 है।"],"stepsEn":["Start by writing the equation: 50% of P = 25% of Q.","Write it mathematically: P × (50 / 100) = Q × (25 / 100).","Notice that the 100 in the denominators cancel out on both sides. Leaving: 50P = 25Q.","We want P in terms of Q, so isolate P: P = (25 / 50) × Q.","Which simplifies to P = (1 / 2) × Q.","We know that 1/2 is exactly 50% as a percentage. So P is 50% of Q. x is 50."],"shortcut":"अनुपात निकालें: P/Q = 25/50 = 1/2। 1/2 का मतलब सीधा 50% होता है।","shortcutEn":"Find the ratio: P/Q = 25/50 = 1/2. 1/2 translates directly to 50%.","trap":"जल्दबाजी में P/Q = 50/25 मत कर देना। गुणांक दूसरी तरफ जाकर उल्टे हो जाते हैं।","trapEn":"Don''t hastily write P/Q = 50/25. The coefficients swap when creating the ratio.","memoryTip":"a% of A = b% of B वाले सवालों में, A और B का अनुपात b/a होता है (उल्टा)।","memoryTipEn":"In equations like a% of A = b% of B, the ratio A/B is always b/a (inversed)."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4xMPFFGCIT0aO0wOf4x20', 'tJwAn-g7aOPlKmJdxgPNG', 'सेब की कीमत में 20% की कमी होने पर एक व्यक्ति 240 रुपये में 2 किलो अधिक सेब खरीद सकता है। सेब की घटी हुई प्रति किलो कीमत क्या है?', '"[{\"id\":\"1\",\"text\":\"24 रुपये\",\"text_en\":\"Rs. 24\"},{\"id\":\"2\",\"text\":\"30 रुपये\",\"text_en\":\"Rs. 30\"},{\"id\":\"3\",\"text\":\"20 रुपये\",\"text_en\":\"Rs. 20\"},{\"id\":\"4\",\"text\":\"25 रुपये\",\"text_en\":\"Rs. 25\"}]"', '1', '240 रुपये का 20% = 48 रुपये। इस 48 रुपये की बचत से वह 2 किलो सेब खरीदता है। अतः नई (घटी हुई) कीमत = 48/2 = 24 रुपये/किलो।', 1, 0, 17, 'Quantitative Aptitude', 'Due to a 20% reduction in the price of apples, a person can buy 2 kg more for Rs. 240. What is the reduced price per kg of apples?', '20% of 240 is 48. With this Rs. 48 saved, he buys 2 kg apples. So, the new (reduced) price = 48/2 = Rs. 24/kg.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: व्यक्ति के पास कुल 240 रुपये हैं खर्च करने के लिए।","कीमत 20% कम हो गई। अगर वह उतनी ही सेब खरीदता जितनी पहले, तो उसके 240 रुपये का 20% बच जाता।","बचत = 240 का 20% = 48 रुपये।","अब ध्यान से देखो, उसने यह 48 रुपये घर ले जाने के बजाय इससे ''2 किलो अधिक'' सेब खरीद लिए।","इसका मतलब आज के समय में 2 किलो सेब की कीमत 48 रुपये है।","तो 1 किलो सेब की नई (घटी हुई) कीमत = 48 / 2 = 24 रुपये।"],"stepsEn":["Start by writing: The person has a fixed budget of Rs. 240.","The price drops by 20%. If he bought the usual amount, he would save 20% of his Rs. 240.","Savings = 20% of 240 = Rs. 48.","Look closely, instead of taking this Rs. 48 home, he used it to buy the ''2 kg extra'' apples.","This means at the CURRENT price, 2 kg of apples cost Rs. 48.","So, the new (reduced) price per kg = 48 / 2 = Rs. 24."],"shortcut":"घटी हुई कीमत का सीधा फॉर्मूला: (रुपये × प्रतिशत कमी) / (मात्रा × 100)। यानी (240 × 20) / (2 × 100) = 24 रुपये।","shortcutEn":"Direct formula for reduced price: (Amount × % Drop) / (Quantity × 100). So, (240 × 20) / (2 × 100) = 24.","trap":"सवाल में ''घटी हुई'' कीमत पूछी है या ''पुरानी'' कीमत, यह ध्यान से पढ़ना। पुरानी कीमत पूछी होती तो 30 रुपये उत्तर होता।","trapEn":"Always double-check if they asked for the ''reduced'' price or ''original'' price. If original, the answer would be 30.","memoryTip":"बचे हुए पैसे (Total × %) से ही अतिरिक्त मात्रा खरीदी जाती है। बस उसे अतिरिक्त मात्रा से भाग दे दो।","memoryTipEn":"The money ''saved'' (Total × %) is exactly what pays for the ''extra quantity''. Just divide them."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('hgcG-reB3ow-qX7maXo_t', 'tJwAn-g7aOPlKmJdxgPNG', 'एक परीक्षा में 60% छात्र गणित में और 70% अंग्रेजी में पास हुए, जबकि 20% दोनों में फेल हुए। दोनों विषयों में कितने प्रतिशत छात्र पास हुए?', '"[{\"id\":\"1\",\"text\":\"40%\",\"text_en\":\"40%\"},{\"id\":\"2\",\"text\":\"50%\",\"text_en\":\"50%\"},{\"id\":\"3\",\"text\":\"60%\",\"text_en\":\"60%\"},{\"id\":\"4\",\"text\":\"30%\",\"text_en\":\"30%\"}]"', '2', 'फेल छात्रों का सेट: गणित में 40% फेल, अंग्रेजी में 30% फेल। कम से कम एक में फेल = 40 + 30 - 20(दोनों में फेल) = 50%। अतः 100 - 50 = 50% दोनों में पास।', 1, 0, 18, 'Quantitative Aptitude', 'In an examination, 60% students passed in Math and 70% passed in English, while 20% failed in both. What percentage of students passed in both subjects?', 'Failures: Math 40%, Eng 30%. At least one fail = 40 + 30 - 20(both) = 50%. So, 100 - 50 = 50% passed both.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: वेन डायग्राम (Venn Diagram) से इसे आसान बनाते हैं। पहले सबको ''फेल'' में बदल लें।","गणित में 60% पास हुए, तो फेल कितने हुए? 100 - 60 = 40% फेल।","अंग्रेजी में 70% पास हुए, तो फेल कितने हुए? 100 - 70 = 30% फेल।","दोनों विषयों में फेल = 20% (ये पहले से दिया है)।","अब ध्यान से देखो, कुल फेल छात्रों का प्रतिशत = गणित में फेल + अंग्रेजी में फेल - दोनों में फेल।","कुल फेल = 40% + 30% - 20% = 50%।","अगर कक्षा में 50% किसी न किसी विषय में फेल हैं, तो बाकी पूरी तरह पास हैं। दोनों में पास = 100% - 50% = 50%।"],"stepsEn":["Start by writing: Let''s use a Venn Diagram logic. It''s easier if we convert everything to ''Fail'' first.","60% passed Math, which means 100 - 60 = 40% failed Math.","70% passed English, which means 100 - 70 = 30% failed English.","Failed in both = 20% (this is already given).","Look closely, Total Failed % = Failed Math + Failed English - Failed Both.","Total Failed = 40% + 30% - 20% = 50%.","If 50% failed in at least one subject, the rest passed entirely. Passed both = 100% - 50% = 50%."],"shortcut":"कुल पास + कुल पास + दोनों में फेल - 100 = दोनों में पास। 60 + 70 + 20 - 100 = 150 - 100 = 50%।","shortcutEn":"Quick formula: Pass 1 + Pass 2 + Fail Both - 100 = Pass Both. 60 + 70 + 20 - 100 = 150 - 100 = 50%.","trap":"पास और फेल के प्रतिशत को एक ही वेन डायग्राम में मिलाने की कोशिश मत करना, उलझ जाओगे। या तो सबको पास बनाओ या फेल।","trapEn":"Don''t mix Pass and Fail percentages in the same Venn calculation. Convert them all to either Pass or all to Fail first.","memoryTip":"वेन डायग्राम सेट थ्योरी: n(A U B) = n(A) + n(B) - n(A ∩ B)।","memoryTipEn":"Venn diagram set theory: n(A U B) = n(A) + n(B) - n(A ∩ B)."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('VQvpmC40HUxzYfFBN2X7N', 'tJwAn-g7aOPlKmJdxgPNG', '1 दिन का कितना प्रतिशत 3 घंटे होता है?', '"[{\"id\":\"1\",\"text\":\"12.5%\",\"text_en\":\"12.5%\"},{\"id\":\"2\",\"text\":\"15%\",\"text_en\":\"15%\"},{\"id\":\"3\",\"text\":\"10%\",\"text_en\":\"10%\"},{\"id\":\"4\",\"text\":\"20%\",\"text_en\":\"20%\"}]"', '1', 'इकाइयाँ समान करें। 1 दिन = 24 घंटे। प्रतिशत = (3 / 24) × 100 = 1/8 × 100 = 12.5%।', 1, 0, 19, 'Quantitative Aptitude', 'What percentage of 1 day is 3 hours?', 'Equate the units. 1 day = 24 hours. Percentage = (3 / 24) × 100 = 1/8 × 100 = 12.5%.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: हमें 3 घंटे और 1 दिन की तुलना करनी है।","गणित का नियम है कि तुलना हमेशा समान इकाई (units) में होती है।","हम जानते हैं कि 1 दिन में 24 घंटे होते हैं।","अब ध्यान से देखो, सवाल यह बन गया: 3 घंटे, 24 घंटे का कितना प्रतिशत है?","प्रतिशत = (3 / 24) × 100।","3/24 को छोटा करें तो 1/8 आता है। और (1/8) × 100 = 12.5%।"],"stepsEn":["Start by writing what we are comparing: 3 hours and 1 day.","Math rule: Comparisons must always be in the same units.","We know that 1 day is exactly 24 hours.","Notice how the question transforms: What percentage of 24 hours is 3 hours?","Percentage = (3 / 24) × 100.","3/24 simplifies to 1/8. And (1/8) × 100 = 12.5%."],"shortcut":"3 घंटे पूरे दिन (24 घंटे) का आठवाँ हिस्सा (1/8) है। 1/8 देखते ही 12.5% याद आना चाहिए।","shortcutEn":"3 hours is exactly one-eighth (1/8) of a 24-hour day. 1/8 should immediately remind you of 12.5%.","trap":"जल्दबाजी में 3/1 × 100 करके 300% मत निकाल देना। इकाइयाँ समान करना मत भूलना।","trapEn":"Don''t hastily do 3/1 × 100 and get 300%. You cannot forget to convert the units.","memoryTip":"प्रतिशत निकालते समय हमेशा ''छोटी इकाई'' (smaller unit) में बदलकर हल करना आसान होता है।","memoryTipEn":"When finding percentages, converting everything to the ''smaller unit'' always makes it easier."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('tci6ZI-ZuHrd6zPyOnQKI', 'tJwAn-g7aOPlKmJdxgPNG', 'एक कस्बे की जनसंख्या में पहले वर्ष 5% की वृद्धि हुई और दूसरे वर्ष 5% की कमी हुई। यदि वर्तमान जनसंख्या 9975 है, तो 2 वर्ष पहले जनसंख्या क्या थी?', '"[{\"id\":\"1\",\"text\":\"10000\",\"text_en\":\"10000\"},{\"id\":\"2\",\"text\":\"10500\",\"text_en\":\"10500\"},{\"id\":\"3\",\"text\":\"9500\",\"text_en\":\"9500\"},{\"id\":\"4\",\"text\":\"10250\",\"text_en\":\"10250\"}]"', '1', 'समान % वृद्धि और कमी पर हमेशा कमी होती है: (5²)/100 = 0.25% कमी। 99.75% = 9975, तो 100% = 10000।', 1, 0, 20, 'Quantitative Aptitude', 'The population of a town increased by 5% in the first year and decreased by 5% in the second year. If the present population is 9975, what was the population 2 years ago?', 'Same % up and down means a net drop: (5²)/100 = 0.25% drop. 99.75% = 9975, so 100% = 10000.', 60, 'standard', NULL, NULL, '{"explanation":{"stream":"math_quant","steps":["पहले लिख लो: मान लेते हैं 2 साल पहले जनसंख्या x थी।","पहले साल 5% बढ़ी, तो यह हो गई x × (105 / 100)।","दूसरे साल 5% घटी, तो यह हो गई x × (105 / 100) × (95 / 100)।","अब ध्यान से देखो, यही अंतिम जनसंख्या हमें 9975 दी गई है।","समीकरण: x × (1.05) × (0.95) = 9975","x × 0.9975 = 9975","तो x = 9975 / 0.9975 = 10000।"],"stepsEn":["Start by writing: Let the population 2 years ago be x.","First year it grew by 5%, making it x × (105 / 100).","Second year it dropped by 5%, making it x × (105 / 100) × (95 / 100).","Look closely, this final calculated population is given as 9975.","Equation: x × (1.05) × (0.95) = 9975","x × 0.9975 = 9975","So x = 9975 / 0.9975 = 10000."],"shortcut":"जब समान प्रतिशत से वृद्धि और कमी हो, तो नेट प्रभाव हमेशा (x² / 100)% की कमी होती है। 25/100 = 0.25% कमी। 100% - 0.25% = 99.75% = 9975, तो 100% = 10000।","shortcutEn":"When increased and decreased by same %, net effect is always a loss of (x² / 100)%. 25/100 = 0.25% loss. 100% - 0.25% = 99.75% = 9975. So 100% = 10000.","trap":"छात्र सोचते हैं +5% और -5% कटकर 0% हो जाएगा और जनसंख्या समान (9975) रहेगी। यह गलत है।","trapEn":"Students often think +5% and -5% cancel out to 0% change. This is mathematically incorrect for successive changes.","memoryTip":"बराबर लाभ और बराबर हानि (या वृद्धि-कमी) में अंततः हमेशा नुकसान होता है (x²/100 %)।","memoryTipEn":"An equal percentage increase followed by a decrease ALWAYS results in a net loss of (x²/100 %)."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5SYBVfGeFZXxzidMhnrRi', '3DqOcOP3gig2ULCKpZEdP', 'ब्राह्मणों की प्रकृति के संदर्भ में, नीचे दिए गए कथनों में से कौन सा सही है?', '"[{\"id\":\"A\",\"text\":\"वे यज्ञीय अनुष्ठानों के प्रतीकों और अर्थ की व्याख्या करते हैं।\",\"textEn\":\"They explain the symbols and meaning of the sacrificial rituals.\"},{\"id\":\"B\",\"text\":\"वे ब्रह्म की प्रकृति पर रहस्यमय और दार्शनिक सामग्री रखते हैं।\",\"textEn\":\"They contain mystical and philosophical material on the nature of Brahman.\"},{\"id\":\"C\",\"text\":\"वे यज्ञों के निष्पादन के लिए नियमों और विनियमों को निर्धारित करते हैं।\",\"textEn\":\"They lay down the rules and regulations for the performance of sacrifices.\"},{\"id\":\"D\",\"text\":\"उपर्युक्त सभी कथन सही हैं।\",\"textEn\":\"All of the statements given above are correct.\"}]"', 'A', '{"verdict": "**विकल्प A सही उत्तर है**।", "core_concept": "प्राचीन भारतीय साहित्य (वैदिक साहित्य): ब्राह्मण।", "elimination_wisdom": "ब्राह्मणों का मुख्य कार्य वेदों के यज्ञ सूत्रों की व्याख्या करना है। विकल्प B उपनिषदों का वर्णन करता है, ब्राह्मणों का नहीं। विकल्प C कल्पसूत्रों का वर्णन करता है। चूंकि केवल A सही है, इसलिए D स्वतः ही खारिज हो जाता है।", "trap_alerts": "वैदिक साहित्य के विभिन्न अंगों (वेद, ब्राह्मण, आरण्यक, उपनिषद) के बीच बारीक अंतर को समझें।"}', 2, 0, 1, 'History', 'With reference to the nature of Brahmanas, which of the statements given below is correct?', '{"verdict": "**Option A is the correct answer**.", "core_concept": "Ancient Indian Literature (Vedic Literature): Brahmanas.", "elimination_wisdom": "The main function of Brahmanas is to explain the sacrificial rituals of the Vedas. Option B describes the Upanishads, not the Brahmanas. Option C describes Kalpasutras. Since only A is correct, D is automatically incorrect.", "trap_alerts": "Understand the subtle differences between different parts of Vedic literature (Vedas, Brahmanas, Aranyakas, Upanishads)."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"With reference to the nature of Brahmanas, which of the statements given below is correct?","questionPromptEn":"With reference to the nature of Brahmanas, which of the statements given below is correct?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('kOJfvyWvn0BiBYAUN5FfM', '3DqOcOP3gig2ULCKpZEdP', 'प्राचीन भारत के इतिहास के संदर्भ में, भवभूति, हस्तिमल्ल और क्षेमेश्वर प्रसिद्ध थे:', '"[{\"id\":\"A\",\"text\":\"जैन साधु\",\"textEn\":\"Jain monks\"},{\"id\":\"B\",\"text\":\"नाटककार\",\"textEn\":\"playwrights\"},{\"id\":\"C\",\"text\":\"मंदिर वास्तुकार\",\"textEn\":\"temple architects\"},{\"id\":\"D\",\"text\":\"दार्शनिक\",\"textEn\":\"philosophers\"}]"', 'B', '{"verdict": "**विकल्प B सही उत्तर है**।", "core_concept": "प्राचीन भारत का साहित्य और कला: नाटककार।", "elimination_wisdom": "भवभूति (उत्तररामचरित), हस्तिमल्ल (विक्रांतकौरव), और क्षेमेश्वर प्रसिद्ध नाटककार थे। ये नाम दार्शनिकों या जैन साधुओं के रूप में प्रमुखता से नहीं जाने जाते हैं।", "trap_alerts": "UPSC अक्सर महत्वपूर्ण प्राचीन हस्तियों और उनके व्यवसायों से संबंधित तथ्यात्मक प्रश्न पूछता है।"}', 2, 0, 2, 'History', 'With reference to the history of ancient India, Bhavabhuti, Hastimalla and Kshemeshvara were famous', '{"verdict": "**Option B is the correct answer**.", "core_concept": "Literature and Art of Ancient India: Playwrights.", "elimination_wisdom": "Bhavabhuti (Uttararamacharita), Hastimalla (Vikrantakaurava), and Kshemeshvara were famous playwrights. These names are not prominently known as philosophers or Jain monks.", "trap_alerts": "UPSC often asks factual questions about important ancient figures and their professions."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"With reference to the history of ancient India, Bhavabhuti, Hastimalla and Kshemeshvara were famous","questionPromptEn":"With reference to the history of ancient India, Bhavabhuti, Hastimalla and Kshemeshvara were famous"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('m7aL7z67M7WImHgMMe05S', '3DqOcOP3gig2ULCKpZEdP', 'निम्नलिखित कथनों पर विचार कीजिए:', '"[{\"id\":\"A\",\"text\":\"केवल 1 और 2\",\"textEn\":\"1 and 2 only\"},{\"id\":\"B\",\"text\":\"केवल 2 और 3\",\"textEn\":\"2 and 3 only\"},{\"id\":\"C\",\"text\":\"केवल 1 और 3\",\"textEn\":\"1 and 3 only\"},{\"id\":\"D\",\"text\":\"1, 2 और 3\",\"textEn\":\"1, 2 and 3\"}]"', 'C', '{"verdict": "**विकल्प C सही उत्तर है**।", "core_concept": "RBI का संस्थागत ढांचा और बैंकिंग विनियम।", "elimination_wisdom": "कथन 1 सही है क्योंकि भारत सरकार आरबीआई गवर्नर नियुक्त करती है। कथन 3 सही है क्योंकि गवर्नर की शक्तियां आरबीआई अधिनियम, 1934 से आती हैं। कथन 2 गलत है क्योंकि सरकार को निर्देश देने की शक्ति संविधान में नहीं, बल्कि आरबीआई अधिनियम की धारा 7 में है। इसलिए, ''2'' वाले विकल्प (A, B, D) खारिज हो जाते हैं।", "trap_alerts": "संविधान में स्पष्ट उल्लेख बनाम वैधानिक कानूनों (Acts) के माध्यम से प्राप्त शक्तियों के बीच अंतर करें।"}', 2, 0, 3, 'Economy', 'Consider the following statements:', '{"verdict": "**Option C is the correct answer**.", "core_concept": "Institutional framework of RBI and banking regulations.", "elimination_wisdom": "Statement 1 is correct as the Government of India appoints the RBI Governor. Statement 3 is correct as the Governor''s powers derive from the RBI Act, 1934. Statement 2 is incorrect because the power to issue directions lies in Section 7 of the RBI Act, not in the Constitution. Therefore, options containing ''2'' (A, B, D) are eliminated.", "trap_alerts": "Distinguish between explicit mentions in the Constitution versus powers derived through statutory laws (Acts)."}', 60, 'standard', NULL, NULL, '{"layoutType":"statements","contextStr":"Consider the following statements:","contextStrEn":"Consider the following statements:","listItems":[{"id":"1","text":"The Governor of the Reserve Bank of India (RBI) is appointed by the Central Government.","textEn":"The Governor of the Reserve Bank of India (RBI) is appointed by the Central Government."},{"id":"2","text":"Certain provisions in the Constitution of India give the Central Government the right to issue directions to the RBI in public interest.","textEn":"Certain provisions in the Constitution of India give the Central Government the right to issue directions to the RBI in public interest."},{"id":"3","text":"The Governor of the RBI draws his power from the RBI Act.","textEn":"The Governor of the RBI draws his power from the RBI Act."}],"questionPrompt":"Which of the statements given above are correct?","questionPromptEn":"Which of the statements given above are correct?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('yqJ2YkjRoLUABGMNF0DEr', '3DqOcOP3gig2ULCKpZEdP', 'कारण संबंधों के संदर्भ में, दिए गए विवरण में निम्नलिखित में से किसका वर्णन किया गया है?
''उन्होंने तर्क दिया कि एक ही उद्देश्य के लिए कई कारणों का अस्तित्व अनावश्यक है; कि किसी प्रभाव को केवल एक मुख्य कारण से उत्पन्न माना जाना चाहिए।''', '"[{\"id\":\"A\",\"text\":\"प्रभाकर\",\"textEn\":\"Prabhakara\"},{\"id\":\"B\",\"text\":\"कुमारिल भट्ट\",\"textEn\":\"Kumarila Bhatta\"},{\"id\":\"C\",\"text\":\"शंकराचार्य\",\"textEn\":\"Shankaracharya\"},{\"id\":\"D\",\"text\":\"रामानुजाचार्य\",\"textEn\":\"Ramanujacharya\"}]"', 'A', '{"verdict": "**विकल्प A सही उत्तर है**।", "core_concept": "भारतीय दर्शन: कारण-कार्य संबंध।", "elimination_wisdom": "प्रभाकर मीमांसा स्कूल के एक दार्शनिक थे। उन्होंने तर्क दिया कि ''अपूर्व'' (अदृष्ट शक्ति) को ही मुख्य कारण माना जाना चाहिए, न कि कई अन्य सहायक कारणों को। कुमारिल भट्ट, शंकराचार्य और रामानुजाचार्य के दर्शन कारण-कार्य संबंध पर अलग विचार रखते हैं, जिसमें वे कई कारणों के सह-अस्तित्व को स्वीकार करते हैं।", "trap_alerts": "यह प्रश्न भारतीय दर्शन के सूक्ष्म और विशिष्ट दार्शनिक सिद्धांतों पर आधारित है, जो इसे कठिन बनाता है।"}', 2, 0, 4, 'History', 'With reference to causal relations, who among the following is described in the given description?
''He argued that existence of multiple causes for the same purpose is redundant; that an effect should be understood as produced from only one main cause.''', '{"verdict": "**Option A is the correct answer**.", "core_concept": "Indian Philosophy: Causal relations.", "elimination_wisdom": "Prabhakara was a philosopher of the Mimamsa school. He argued that ''Apurva'' (unseen potency) should be considered the main cause, rather than multiple ancillary causes. Kumarila Bhatta, Shankaracharya, and Ramanujacharya hold different views on causality, acknowledging the co-existence of multiple causes.", "trap_alerts": "This question is based on fine and specific philosophical tenets of Indian philosophy, making it difficult."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"With reference to causal relations, who among the following is described in the given description?","questionPromptEn":"With reference to causal relations, who among the following is described in the given description?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('N1Z08Rbp6GYyciG4L66CP', '3DqOcOP3gig2ULCKpZEdP', 'केंद्रीय सरकार के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', '"[{\"id\":\"A\",\"text\":\"केवल 1\",\"textEn\":\"1 only\"},{\"id\":\"B\",\"text\":\"केवल 2\",\"textEn\":\"2 only\"},{\"id\":\"C\",\"text\":\"1 और 2 दोनों\",\"textEn\":\"Both 1 and 2\"},{\"id\":\"D\",\"text\":\"न तो 1, न ही 2\",\"textEn\":\"Neither 1 nor 2\"}]"', 'B', '{"verdict": "**विकल्प B सही उत्तर है**।", "core_concept": "भारत सरकार (कार्य आवंटन) नियम, 1961।", "elimination_wisdom": "कथन 1 गलत है क्योंकि मंत्रालय/विभाग राष्ट्रपति द्वारा भारत सरकार (कार्य आवंटन) नियम, 1961 के तहत बनाए जाते हैं, न कि कैबिनेट सचिव की सलाह पर प्रधान मंत्री द्वारा। कथन 2 सही है क्योंकि राष्ट्रपति प्रधान मंत्री की सलाह पर मंत्रियों को विभाग आवंटित करते हैं।", "trap_alerts": "कैबिनेट सचिव की भूमिका सलाहकारी होती है, न कि कार्यकारी, विशेष रूप से मंत्रालयों के निर्माण में।"}', 2, 0, 5, 'Polity', 'With reference to the Union Government, consider the following statements:', '{"verdict": "**Option B is the correct answer**.", "core_concept": "Government of India (Allocation of Business) Rules, 1961.", "elimination_wisdom": "Statement 1 is incorrect because Ministries/Departments are created by the President under the Government of India (Allocation of Business) Rules, 1961, not by the Prime Minister on the advice of the Cabinet Secretary. Statement 2 is correct as the President allocates portfolios to Ministers on the advice of the Prime Minister.", "trap_alerts": "The Cabinet Secretary''s role is advisory, not executive, especially in the creation of ministries."}', 60, 'standard', NULL, NULL, '{"layoutType":"statements","contextStr":"With reference to the Union Government, consider the following statements:","contextStrEn":"With reference to the Union Government, consider the following statements:","listItems":[{"id":"1","text":"The Ministries/Departments of the Government of India are created by the Prime Minister on the advice of the Cabinet Secretary.","textEn":"The Ministries/Departments of the Government of India are created by the Prime Minister on the advice of the Cabinet Secretary."},{"id":"2","text":"Each Ministry is assigned to a Minister by the President of India on the advice of the Prime Minister.","textEn":"Each Ministry is assigned to a Minister by the President of India on the advice of the Prime Minister."}],"questionPrompt":"Which of the statements given above is/are correct?","questionPromptEn":"Which of the statements given above is/are correct?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('AXA7PG3KX-f0mWhuDymeF', '3DqOcOP3gig2ULCKpZEdP', 'निम्नलिखित में से कौन सी भारत सरकार अधिनियम, 1935 की विशेषता नहीं है?', '"[{\"id\":\"A\",\"text\":\"प्रांतीय स्वायत्तता\",\"textEn\":\"Provincial autonomy\"},{\"id\":\"B\",\"text\":\"अखिल भारतीय संघ\",\"textEn\":\"All-India Federation\"},{\"id\":\"C\",\"text\":\"केंद्र के साथ-साथ राज्यों में द्वैध शासन\",\"textEn\":\"Dyarchy at the Centre as well as in the provinces\"},{\"id\":\"D\",\"text\":\"विषयों का केंद्र और प्रांतों के बीच विभाजन\",\"textEn\":\"Division of subjects between the Centre and provinces\"}]"', 'C', '{"verdict": "**विकल्प C सही उत्तर है**।", "core_concept": "भारत सरकार अधिनियम, 1935: संवैधानिक विकास।", "elimination_wisdom": "1935 के अधिनियम ने प्रांतों में द्वैध शासन को समाप्त कर दिया और प्रांतीय स्वायत्तता की शुरुआत की। हालांकि, इसने केंद्र में द्वैध शासन का प्रस्ताव दिया (जो कभी लागू नहीं हुआ)। कथन C गलत है क्योंकि यह कहता है कि द्वैध शासन केंद्र *और* प्रांतों दोनों में था। अन्य विकल्प 1935 के अधिनियम की विशेषताएं हैं।", "trap_alerts": "1919 के अधिनियम (प्रांतों में द्वैध शासन) और 1935 के अधिनियम (केंद्र में द्वैध शासन, प्रांतों में स्वायत्तता) के बीच स्पष्ट अंतर रखें।"}', 2, 0, 6, 'Polity', 'Which one of the following is NOT a feature of the Government of India Act, 1935?', '{"verdict": "**Option C is the correct answer**.", "core_concept": "Government of India Act, 1935: Constitutional Development.", "elimination_wisdom": "The 1935 Act abolished dyarchy in the provinces and introduced provincial autonomy. However, it proposed dyarchy at the Centre (which was never implemented). Statement C is incorrect because it states that dyarchy was in both the Centre *and* the provinces. Other options are features of the 1935 Act.", "trap_alerts": "Clearly distinguish between the 1919 Act (dyarchy in provinces) and the 1935 Act (dyarchy at Centre, autonomy in provinces)."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"Which one of the following is NOT a feature of the Government of India Act, 1935?","questionPromptEn":"Which one of the following is NOT a feature of the Government of India Act, 1935?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('L5-zUGw9b-xJ-TR5F7Nw_', '3DqOcOP3gig2ULCKpZEdP', 'भारतीय अर्थव्यवस्था के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', '"[{\"id\":\"A\",\"text\":\"केवल 1\",\"textEn\":\"1 only\"},{\"id\":\"B\",\"text\":\"केवल 2\",\"textEn\":\"2 only\"},{\"id\":\"C\",\"text\":\"1 और 2 दोनों\",\"textEn\":\"Both 1 and 2\"},{\"id\":\"D\",\"text\":\"न तो 1, न ही 2\",\"textEn\":\"Neither 1 nor 2\"}]"', 'B', '{"verdict": "**विकल्प B सही उत्तर है**।", "core_concept": "पूंजी बाजार: सरकारी प्रतिभूतियां (G-Secs)।", "elimination_wisdom": "कथन 1 गलत है क्योंकि ''गिल्ट-एज्ड'' प्रतिभूतियां सरकार (केंद्र या राज्य) द्वारा जारी की जाती हैं, न कि निजी कंपनियों द्वारा। कथन 2 सही है क्योंकि सरकारी गारंटी के कारण इनमें डिफॉल्ट का जोखिम नगण्य होता है।", "trap_alerts": "''गिल्ट-एज्ड'' शब्द का अर्थ उत्कृष्ट गुणवत्ता है, लेकिन यह विशेष रूप से सरकारी प्रतिभूतियों के लिए उपयोग किया जाता है, न कि निजी ''ब्लू-चिप'' कंपनियों के लिए।"}', 2, 0, 7, 'Economy', 'With reference to the Indian economy, consider the following statements:', '{"verdict": "**Option B is the correct answer**.", "core_concept": "Capital Market: Government Securities (G-Secs).", "elimination_wisdom": "Statement 1 is incorrect because ''Gilt-edged'' securities are issued by the government (Central or State), not by private companies. Statement 2 is correct because they have negligible risk of default due to government guarantee.", "trap_alerts": "The term ''Gilt-edged'' means excellent quality, but it is specifically used for government securities, not private ''blue-chip'' companies."}', 60, 'standard', NULL, NULL, '{"layoutType":"statements","contextStr":"With reference to the Indian economy, consider the following statements:","contextStrEn":"With reference to the Indian economy, consider the following statements:","listItems":[{"id":"1","text":"''Gilt-edged'' securities are issued by blue-chip companies.","textEn":"''Gilt-edged'' securities are issued by blue-chip companies."},{"id":"2","text":"They are considered to be very safe as they have negligible risk of default.","textEn":"They are considered to be very safe as they have negligible risk of default."}],"questionPrompt":"Which of the statements given above is/are correct?","questionPromptEn":"Which of the statements given above is/are correct?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('7w3TeYmcpE-dNSPKYhoOG', '3DqOcOP3gig2ULCKpZEdP', 'निम्नलिखित का मिलान कीजिए:
जलप्रपात | क्षेत्र
1. बरकाना | पश्चिमी घाट
2. दूधसागर | पूर्वी घाट
3. जोग | पश्चिमी घाट
उपर्युक्त में से कितने युग्म सही सुमेलित हैं?', '"[{\"id\":\"A\",\"text\":\"केवल एक युग्म\",\"textEn\":\"Only one pair\"},{\"id\":\"B\",\"text\":\"केवल दो युग्म\",\"textEn\":\"Only two pairs\"},{\"id\":\"C\",\"text\":\"सभी तीन युग्म\",\"textEn\":\"All three pairs\"},{\"id\":\"D\",\"text\":\"कोई भी युग्म नहीं\",\"textEn\":\"None of the pairs\"}]"', 'B', '{"verdict": "**विकल्प B सही उत्तर है**।", "core_concept": "भारत का भौतिक भूगोल: जलप्रपात।", "elimination_wisdom": "बरकाना जलप्रपात (कर्नाटक) पश्चिमी घाट में स्थित है, इसलिए युग्म 1 सही है। दूधसागर जलप्रपात (गोवा/कर्नाटक सीमा) भी पश्चिमी घाट में स्थित है, पूर्वी घाट में नहीं, इसलिए युग्म 2 गलत है। जोग जलप्रपात (कर्नाटक) पश्चिमी घाट में स्थित है, इसलिए युग्म 3 सही है। दो युग्म सही सुमेलित हैं।", "trap_alerts": "UPSC अक्सर प्रमुख भौगोलिक विशेषताओं के सटीक स्थान और उनसे जुड़ी नदियों के बारे में पूछता है।"}', 2, 0, 8, 'Geography', 'Match the following:
Waterfall | Region
1. Barakana | Western Ghats
2. Dudhsagar | Eastern Ghats
3. Jog | Western Ghats
How many pairs given above are correctly matched?', '{"verdict": "**Option B is the correct answer**.", "core_concept": "Physical Geography of India: Waterfalls.", "elimination_wisdom": "Barkana Falls (Karnataka) is located in the Western Ghats, so pair 1 is correct. Dudhsagar Falls (Goa/Karnataka border) is also located in the Western Ghats, not the Eastern Ghats, so pair 2 is incorrect. Jog Falls (Karnataka) is located in the Western Ghats, so pair 3 is correct. Two pairs are correctly matched.", "trap_alerts": "UPSC often asks about the exact location of major geographical features and the rivers associated with them."}', 60, 'standard', NULL, NULL, '{"layoutType":"table","contextStr":"Match the following:","contextStrEn":"Match the following:","tableHeaders":["Waterfall","Region"],"tableHeadersEn":["Waterfall","Region"],"tableRows":[["1. Barakana","Western Ghats"],["2. Dudhsagar","Eastern Ghats"],["3. Jog","Western Ghats"]],"tableRowsEn":[["1. Barakana","Western Ghats"],["2. Dudhsagar","Eastern Ghats"],["3. Jog","Western Ghats"]],"questionPrompt":"How many pairs given above are correctly matched?","questionPromptEn":"How many pairs given above are correctly matched?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('JQzLXhPwfbaZ_jNmNr6ks', '3DqOcOP3gig2ULCKpZEdP', 'आर्द्रभूमियों और उनमें से बहने वाली नदियों के निम्नलिखित युग्मों पर विचार कीजिए:
आर्द्रभूमि | नदी
1. हरीके आर्द्रभूमि | ब्यास और सतलुज का संगम
2. केवलादेव घाना राष्ट्रीय उद्यान | बनास और चंबल का संगम
3. कोलेरू झील | मूसी और कृष्णा का संगम
उपर्युक्त में से कौन सा/से युग्म सही सुमेलित है/हैं?', '"[{\"id\":\"A\",\"text\":\"केवल 1\",\"textEn\":\"1 only\"},{\"id\":\"B\",\"text\":\"केवल 2\",\"textEn\":\"2 only\"},{\"id\":\"C\",\"text\":\"केवल 1 और 3\",\"textEn\":\"1 and 3 only\"},{\"id\":\"D\",\"text\":\"1, 2 और 3\",\"textEn\":\"1, 2 and 3\"}]"', 'A', '{"verdict": "**विकल्प A सही उत्तर है**।", "core_concept": "भारत की प्रमुख आर्द्रभूमियाँ और नदी प्रणाली।", "elimination_wisdom": "युग्म 1 सही है क्योंकि हरीके आर्द्रभूमि ब्यास और सतलुज के संगम पर है। युग्म 2 गलत है क्योंकि केवलादेव घाना राष्ट्रीय उद्यान गंभीर और बाणगंगा नदियों के संगम पर है, बनास और चंबल पर नहीं। युग्म 3 गलत है क्योंकि कोलेरू झील गोदावरी और कृष्णा डेल्टा के बीच स्थित है, लेकिन मूसी और कृष्णा के संगम पर नहीं। इसलिए, केवल 1 सही है।", "trap_alerts": "रामसर साइट्स और उनके भौगोलिक संदर्भ यूपीएससी के लिए अत्यधिक महत्वपूर्ण हैं।"}', 2, 0, 9, 'Geography', 'Consider the following pairs of Wetlands and Rivers flowing through them:
Wetland | River
1. Harike Wetlands | Confluence of Beas and Sutlej
2. Keoladeo Ghana National Park | Confluence of Banas and Chambal
3. Kolleru Lake | Confluence of Musi and Krishna
Which of the pairs given above is/are correctly matched?', '{"verdict": "**Option A is the correct answer**.", "core_concept": "Major Wetlands and River Systems of India.", "elimination_wisdom": "Pair 1 is correct as Harike Wetland is at the confluence of Beas and Sutlej. Pair 2 is incorrect because Keoladeo Ghana National Park is at the confluence of Gambhir and Banganga rivers, not Banas and Chambal. Pair 3 is incorrect because Kolleru Lake is situated between Godavari and Krishna deltas, but not at the confluence of Musi and Krishna. Therefore, only 1 is correct.", "trap_alerts": "Ramsar sites and their geographical contexts are highly important for UPSC."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"Consider the following pairs of Wetlands and Rivers flowing through them:","questionPromptEn":"Consider the following pairs of Wetlands and Rivers flowing through them:"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('38kCH35O3awR9N35pfj-g', '3DqOcOP3gig2ULCKpZEdP', 'आर्द्रभूमियों के संरक्षण के संदर्भ में, ''मोंट्रेक्स रिकॉर्ड'' के संबंध में निम्नलिखित कथनों पर विचार कीजिए:
1. यह रामसर कन्वेंशन के तहत अंतरराष्ट्रीय महत्व की आर्द्रभूमियों की सूची का एक हिस्सा है।
2. इस रिकॉर्ड में उन आर्द्रभूमियों को शामिल किया जाता है जहां तकनीकी विकास, प्रदूषण या अन्य मानवीय हस्तक्षेप के परिणामस्वरूप पारिस्थितिक चरित्र में परिवर्तन हुए हैं, हो रहे हैं या होने की संभावना है।
उपर्युक्त कथनों में से कौन सा/से सही है/हैं?', '"[{\"id\":\"A\",\"text\":\"केवल 1\",\"textEn\":\"1 only\"},{\"id\":\"B\",\"text\":\"केवल 2\",\"textEn\":\"2 only\"},{\"id\":\"C\",\"text\":\"1 और 2 दोनों\",\"textEn\":\"Both 1 and 2\"},{\"id\":\"D\",\"text\":\"न तो 1, न ही 2\",\"textEn\":\"Neither 1 nor 2\"}]"', 'C', '{"verdict": "**विकल्प B सही उत्तर है**।", "core_concept": "आर्द्रभूमि संरक्षण और रामसर कन्वेंशन।", "elimination_wisdom": "मोंट्रेक्स रिकॉर्ड रामसर कन्वेंशन के तहत एक रजिस्टर है जिसमें उन आर्द्रभूमि स्थलों को सूचीबद्ध किया जाता है जहां पारिस्थितिक चरित्र में परिवर्तन हुए हैं, हो रहे हैं या होने की संभावना है। अन्य विकल्प अन्य पर्यावरण सम्मेलनों से संबंधित हैं (जैसे जैव विविधता के लिए कार्टाजेना)।", "trap_alerts": "विभिन्न पर्यावरण सम्मेलनों और उनके विशिष्ट उपकरणों के बीच भ्रमित न हों।"}', 2, 0, 10, 'Environment', 'With reference to the conservation of wetlands, consider the following statements regarding ''Montreux Record'':
1. It is a part of the List of Wetlands of International Importance under the Ramsar Convention.
2. In this record, those wetlands are included where changes in ecological character have occurred, are occurring, or are likely to occur as a result of technological developments, pollution, or other human interference.
Which of the statements given above is/are correct?', '{"verdict": "**Option B is the correct answer**.", "core_concept": "Wetland Conservation and Ramsar Convention.", "elimination_wisdom": "The Montreux Record is a register under the Ramsar Convention that lists wetland sites where changes in ecological character have occurred, are occurring, or are likely to occur. Other options relate to other environmental conventions (e.g., Cartagena for biodiversity).", "trap_alerts": "Do not confuse between different environmental conventions and their specific instruments."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"With reference to the conservation of wetlands, consider the following statements regarding ''Montreux Record'':","questionPromptEn":"With reference to the conservation of wetlands, consider the following statements regarding ''Montreux Record'':"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('52mfo2UV3L_o9TMPpmBYw', '3DqOcOP3gig2ULCKpZEdP', 'यदि आप अपने बैंक के मांग जमा खाते से ₹1,00,000 नकद निकालते हैं, तो अर्थव्यवस्था में कुल मुद्रा आपूर्ति पर तत्काल प्रभाव पड़ेगा:', '"[{\"id\":\"A\",\"text\":\"₹1,00,000 की कमी\",\"textEn\":\"a reduction of ₹1,00,000\"},{\"id\":\"B\",\"text\":\"₹1,00,000 की वृद्धि\",\"textEn\":\"an increase of ₹1,00,000\"},{\"id\":\"C\",\"text\":\"₹1,00,000 से अधिक की वृद्धि\",\"textEn\":\"an increase of more than ₹1,00,000\"},{\"id\":\"D\",\"text\":\"अपरिवर्तित रहना\",\"textEn\":\"to leave it unchanged\"}]"', 'D', '{"verdict": "**विकल्प C सही उत्तर है**।", "core_concept": "मुद्रा आपूर्ति और बैंकिंग प्रणाली।", "elimination_wisdom": "जब आप बैंक से नकद निकालते हैं, तो मुद्रा जनता के पास चली जाती है, लेकिन बैंकों की मांग जमा कम हो जाती है। चूंकि M3 में संचलन में मुद्रा और मांग जमा दोनों शामिल हैं, इसलिए M3 में कोई तत्काल परिवर्तन नहीं होगा। नकद निकासी केवल M3 के घटकों को बदलती है।", "trap_alerts": "M1 (संकीर्ण मुद्रा) और M3 (व्यापक मुद्रा) की परिभाषाओं को याद रखें।"}', 2, 0, 11, 'Economy', 'If you withdraw ₹1,00,000 in cash from your Demand Deposit Account at your bank, the immediate effect on aggregate money supply in the economy will be', '{"verdict": "**Option C is the correct answer**.", "core_concept": "Money supply and banking system.", "elimination_wisdom": "When you withdraw cash from a bank, the currency moves to the public, but the demand deposits of banks decrease. Since M3 includes both currency in circulation and demand deposits, there will be no immediate change in M3. Cash withdrawal only changes the components of M3.", "trap_alerts": "Recall the definitions of M1 (Narrow Money) and M3 (Broad Money)."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"If you withdraw ₹1,00,000 in cash from your Demand Deposit Account at your bank, the immediate effect on aggregate money supply in the economy will be","questionPromptEn":"If you withdraw ₹1,00,000 in cash from your Demand Deposit Account at your bank, the immediate effect on aggregate money supply in the economy will be"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('EDrwEQXiEfRk3zg5ewyjQ', '3DqOcOP3gig2ULCKpZEdP', 'निम्नलिखित कथनों पर विचार कीजिए:', '"[{\"id\":\"A\",\"text\":\"केवल 1\",\"textEn\":\"1 only\"},{\"id\":\"B\",\"text\":\"केवल 2\",\"textEn\":\"2 only\"},{\"id\":\"C\",\"text\":\"1 और 2 दोनों\",\"textEn\":\"Both 1 and 2\"},{\"id\":\"D\",\"text\":\"न तो 1, न ही 2\",\"textEn\":\"Neither 1 nor 2\"}]"', 'D', '{"verdict": "**विकल्प D सही उत्तर है**।", "core_concept": "विश्व मानचित्र और अंतर्राष्ट्रीय संगठन।", "elimination_wisdom": "कथन 1 गलत है क्योंकि भूमध्य सागर सीमावर्ती कई देश (जैसे मिस्र, लीबिया, ट्यूनीशिया, अल्जीरिया, मोरक्को, सीरिया, लेबनान, इजरायल) यूरो क्षेत्र का हिस्सा नहीं हैं। कथन 2 गलत है क्योंकि उन्हीं देशों में से कई (जैसे उत्तरी अफ्रीका के देश, सीरिया, लेबनान, इजरायल) नाटो के सदस्य नहीं हैं। ''सभी'' जैसे चरम शब्द अक्सर गलत होते हैं।", "trap_alerts": "यूरो क्षेत्र और नाटो की सदस्यता के साथ भौगोलिक सीमाओं को न जोड़ें; वे राजनीतिक और आर्थिक संघ हैं।"}', 2, 0, 12, 'Geography', 'Consider the following statements:', '{"verdict": "**Option D is the correct answer**.", "core_concept": "World Map and International Organizations.", "elimination_wisdom": "Statement 1 is incorrect because many countries bordering the Mediterranean Sea (e.g., Egypt, Libya, Tunisia, Algeria, Morocco, Syria, Lebanon, Israel) are not part of the Eurozone. Statement 2 is incorrect because many of the same countries (e.g., North African countries, Syria, Lebanon, Israel) are not members of NATO. Extreme words like ''All'' are often incorrect.", "trap_alerts": "Do not conflate geographical borders with Eurozone and NATO membership; they are political and economic unions."}', 60, 'standard', NULL, NULL, '{"layoutType":"statements","contextStr":"Consider the following statements:","contextStrEn":"Consider the following statements:","listItems":[{"id":"1","text":"All the countries bordering the Mediterranean Sea are part of the Eurozone.","textEn":"All the countries bordering the Mediterranean Sea are part of the Eurozone."},{"id":"2","text":"All the countries bordering the Mediterranean Sea are part of the North Atlantic Treaty Organization (NATO).","textEn":"All the countries bordering the Mediterranean Sea are part of the North Atlantic Treaty Organization (NATO)."}],"questionPrompt":"Which of the statements given above is/are correct?","questionPromptEn":"Which of the statements given above is/are correct?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('a1kMECLs4jBr0VmL1SIBv', '3DqOcOP3gig2ULCKpZEdP', 'निम्नलिखित में से कौन सा देश भूमध्य सागर में नहीं खुलता है?', '"[{\"id\":\"A\",\"text\":\"सीरिया\",\"textEn\":\"Syria\"},{\"id\":\"B\",\"text\":\"जॉर्डन\",\"textEn\":\"Jordan\"},{\"id\":\"C\",\"text\":\"लेबनान\",\"textEn\":\"Lebanon\"},{\"id\":\"D\",\"text\":\"इजरायल\",\"textEn\":\"Israel\"}]"', 'B', '{"verdict": "**विकल्प B सही उत्तर है**।", "core_concept": "पश्चिम एशिया का मानचित्र।", "elimination_wisdom": "सीरिया, लेबनान और इजरायल सभी भूमध्य सागर के पूर्वी तट पर स्थित हैं। जॉर्डन एक स्थलबरुद्ध देश है (हालांकि अकाबा की खाड़ी के माध्यम से लाल सागर तक इसकी छोटी पहुंच है)।", "trap_alerts": "भूमध्य सागर, लाल सागर और उनके आसपास के देशों के मानचित्र का सावधानीपूर्वक अध्ययन करें, विशेष रूप से पश्चिम एशिया में।"}', 2, 0, 13, 'Geography', 'Which one of the following countries does not open out to the Mediterranean Sea?', '{"verdict": "**Option B is the correct answer**.", "core_concept": "Map of West Asia.", "elimination_wisdom": "Syria, Lebanon, and Israel are all situated on the eastern coast of the Mediterranean Sea. Jordan is a landlocked country (though it has a small outlet to the Red Sea via the Gulf of Aqaba).", "trap_alerts": "Carefully study the map of the Mediterranean Sea, Red Sea, and surrounding countries, especially in West Asia."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"Which one of the following countries does not open out to the Mediterranean Sea?","questionPromptEn":"Which one of the following countries does not open out to the Mediterranean Sea?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5bckZlu8L4J1c_ZtayN8Z', '3DqOcOP3gig2ULCKpZEdP', 'दक्षिण-पूर्व एशिया के निम्नलिखित शहरों का दक्षिण से उत्तर की ओर बढ़ने पर सही क्रम क्या है?
1. बैंकॉक
2. हनोई
3. जकार्ता
4. सिंगापुर
नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[{\"id\":\"A\",\"text\":\"3-4-1-2\",\"textEn\":\"3-4-1-2\"},{\"id\":\"B\",\"text\":\"3-4-2-1\",\"textEn\":\"3-4-2-1\"},{\"id\":\"C\",\"text\":\"4-3-1-2\",\"textEn\":\"4-3-1-2\"},{\"id\":\"D\",\"text\":\"4-3-2-1\",\"textEn\":\"4-3-2-1\"}]"', 'A', '{"verdict": "**विकल्प A सही उत्तर है**।", "core_concept": "दक्षिण-पूर्व एशिया का मानचित्र।", "elimination_wisdom": "जकार्ता (इंडोनेशिया) सबसे दक्षिण में है। उसके बाद सिंगापुर है। फिर बैंकॉक (थाईलैंड) और सबसे उत्तर में हनोई (वियतनाम) है। सही क्रम 3-4-1-2 है।", "trap_alerts": "प्रमुख शहरों और राजधानियों के अक्षांशीय स्थानों के बारे में मानचित्र-आधारित प्रश्न UPSC में आम हैं।"}', 2, 0, 14, 'Geography', 'What is the correct sequence of occurrence of the following cities in South-East Asia as one proceeds from South to North?
1. Bangkok
2. Hanoi
3. Jakarta
4. Singapore
Select the correct answer using the code given below:', '{"verdict": "**Option A is the correct answer**.", "core_concept": "Map of South-East Asia.", "elimination_wisdom": "Jakarta (Indonesia) is the southernmost. Then comes Singapore. Next is Bangkok (Thailand) and Hanoi (Vietnam) is the northernmost. The correct sequence is 3-4-1-2.", "trap_alerts": "Map-based questions about latitudinal locations of major cities and capitals are common in UPSC."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"What is the correct sequence of occurrence of the following cities in South-East Asia as one proceeds from South to North?","questionPromptEn":"What is the correct sequence of occurrence of the following cities in South-East Asia as one proceeds from South to North?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('NcfrQjO_bo__2VeL_i3fV', '3DqOcOP3gig2ULCKpZEdP', 'कथन I: भारतीय रिजर्व बैंक (RBI) संघ और राज्य सरकारों के सार्वजनिक ऋण का प्रबंधन करता है।
कथन II: RBI भारत में बैंकनोट जारी करने वाला एकमात्र प्राधिकरण है।
उपर्युक्त में से कौन सा/से कथन सही है/हैं?', '"[{\"id\":\"A\",\"text\":\"केवल I\",\"textEn\":\"I only\"},{\"id\":\"B\",\"text\":\"केवल II\",\"textEn\":\"II only\"},{\"id\":\"C\",\"text\":\"I और II दोनों\",\"textEn\":\"Both I and II\"},{\"id\":\"D\",\"text\":\"न तो I, न ही II\",\"textEn\":\"Neither I nor II\"}]"', 'C', '{"verdict": "**विकल्प C सही उत्तर है**।", "core_concept": "RBI के कार्य।", "elimination_wisdom": "कथन I सही है क्योंकि RBI अधिनियम की धारा 20 और 21A के तहत, RBI केंद्र और राज्य सरकारों के लिए ऋण प्रबंधक के रूप में कार्य करता है। कथन II सही है क्योंकि RBI अधिनियम की धारा 22 के तहत, RBI को भारत में बैंक नोट जारी करने का एकमात्र अधिकार है (सिवाय एक रुपये के नोट और सिक्कों के, जो वित्त मंत्रालय द्वारा जारी किए जाते हैं)।", "trap_alerts": "यद्यपि वित्त मंत्रालय सिक्के और एक रुपये का नोट जारी करता है, ''बैंक नोट'' जारी करने के लिए RBI एकमात्र प्राधिकरण है।"}', 2, 0, 15, 'Economy', 'Statement I: The Reserve Bank of India (RBI) manages the public debt of the Union and the State Governments.
Statement II: The RBI is the sole authority in India to issue banknotes.
Which of the statements given above is/are correct?', '{"verdict": "**Option C is the correct answer**.", "core_concept": "Functions of RBI.", "elimination_wisdom": "Statement I is correct because under sections 20 and 21A of the RBI Act, RBI acts as debt manager for the Central and State Governments. Statement II is correct because under Section 22 of the RBI Act, RBI has the sole right to issue bank notes in India (except for one-rupee notes and coins, which are issued by the Ministry of Finance).", "trap_alerts": "Although the Ministry of Finance issues coins and one-rupee notes, RBI is the sole authority for issuing ''bank notes''."}', 60, 'standard', NULL, NULL, '{"layoutType":"assertion_reason","statementI":"The Reserve Bank of India (RBI) manages the public debt of the Union and the State Governments.","statementIEn":"The Reserve Bank of India (RBI) manages the public debt of the Union and the State Governments.","statementII":"The RBI is the sole authority in India to issue banknotes.","statementIIEn":"The RBI is the sole authority in India to issue banknotes.","questionPrompt":"Which of the statements is/are correct?","questionPromptEn":"Which of the statements is/are correct?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('jOP0OvymwHV9_FON3SiE2', '3DqOcOP3gig2ULCKpZEdP', 'निम्नलिखित में से कौन सी उष्णकटिबंधीय सवाना क्षेत्र की विशिष्ट जलवायु है?', '"[{\"id\":\"A\",\"text\":\"वर्ष भर वर्षा\",\"textEn\":\"Rainfall throughout the year\"},{\"id\":\"B\",\"text\":\"केवल सर्दियों में वर्षा\",\"textEn\":\"Rainfall in winter only\"},{\"id\":\"C\",\"text\":\"एक अत्यंत छोटी शुष्क ऋतु\",\"textEn\":\"An extremely short dry season\"},{\"id\":\"D\",\"text\":\"एक निश्चित शुष्क और आर्द्र ऋतु\",\"textEn\":\"A definite dry and wet season\"}]"', 'D', '{"verdict": "**विकल्प D सही उत्तर है**।", "core_concept": "विश्व जलवायु क्षेत्र (कोपेन का वर्गीकरण): सवाना (Aw)।", "elimination_wisdom": "उष्णकटिबंधीय सवाना जलवायु (Aw) की विशेषता एक अलग शुष्क मौसम (सर्दियों में) और एक गीला मौसम (गर्मियों में) है। विकल्प A भूमध्यरेखीय जलवायु है। विकल्प B भूमध्यसागरीय जलवायु है। विकल्प C उष्णकटिबंधीय मानसून जलवायु (Am) के करीब है।", "trap_alerts": "विभिन्न जलवायु प्रकारों की मुख्य वर्षा और तापमान विशेषताओं को स्पष्ट रूप से समझें।"}', 2, 0, 16, 'Geography', 'Which one of the following is the characteristic climate of the Tropical Savannah Region?', '{"verdict": "**Option D is the correct answer**.", "core_concept": "World Climate Regions (Koppen''s classification): Savannah (Aw).", "elimination_wisdom": "The Tropical Savannah Climate (Aw) is characterized by a distinct dry season (in winter) and a wet season (in summer). Option A is Equatorial climate. Option B is Mediterranean climate. Option C is closer to Tropical Monsoon climate (Am).", "trap_alerts": "Clearly understand the key rainfall and temperature characteristics of different climate types."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"Which one of the following is the characteristic climate of the Tropical Savannah Region?","questionPromptEn":"Which one of the following is the characteristic climate of the Tropical Savannah Region?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('tCJh6_vdN2vJRrx7iZzJL', '3DqOcOP3gig2ULCKpZEdP', 'भारत में जल शासन के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', '"[{\"id\":\"A\",\"text\":\"केवल 1\",\"textEn\":\"1 only\"},{\"id\":\"B\",\"text\":\"केवल 2\",\"textEn\":\"2 only\"},{\"id\":\"C\",\"text\":\"1 और 2 दोनों\",\"textEn\":\"Both 1 and 2\"},{\"id\":\"D\",\"text\":\"न तो 1, न ही 2\",\"textEn\":\"Neither 1 nor 2\"}]"', 'A', '{"verdict": "**विकल्प A सही उत्तर है**।", "core_concept": "संविधान की सातवीं अनुसूची और विधायी शक्तियां।", "elimination_wisdom": "कथन 1 सही है क्योंकि ''जल'' राज्य सूची का विषय है (प्रविष्टि 17)। कथन 2 गलत है क्योंकि संघ सूची (प्रविष्टि 56) संसद को अंतर-राज्यीय नदियों के नियमन और विकास के लिए कानून बनाने की शक्ति देती है। इसलिए, केवल 1 सही है।", "trap_alerts": "राज्य सूची के विषयों और उन पर संघ की ओवरराइडिंग शक्तियों (जैसे अंतर-राज्यीय मुद्दे) के बीच संतुलन को समझें।"}', 2, 0, 17, 'Polity', 'With reference to water governance in India, consider the following statements:', '{"verdict": "**Option A is the correct answer**.", "core_concept": "Seventh Schedule of the Constitution and Legislative Powers.", "elimination_wisdom": "Statement 1 is correct as ''Water'' is a State subject (Entry 17). Statement 2 is incorrect because Union List (Entry 56) gives Parliament the power to legislate for the regulation and development of inter-State rivers. Therefore, only 1 is correct.", "trap_alerts": "Understand the balance between State list subjects and Union''s overriding powers over them (like inter-state issues)."}', 60, 'standard', NULL, NULL, '{"layoutType":"statements","contextStr":"With reference to water governance in India, consider the following statements:","contextStrEn":"With reference to water governance in India, consider the following statements:","listItems":[{"id":"1","text":"Water is a State Subject under the Seventh Schedule of the Constitution.","textEn":"Water is a State Subject under the Seventh Schedule of the Constitution."},{"id":"2","text":"The Central Government has no power to make laws on inter-State rivers.","textEn":"The Central Government has no power to make laws on inter-State rivers."}],"questionPrompt":"Which of the statements given above is/are correct?","questionPromptEn":"Which of the statements given above is/are correct?"}', 'upsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xwwrwq-L8n2zaMHvciO45', '3DqOcOP3gig2ULCKpZEdP', 'निम्नलिखित में से कौन सा यौगिक ''बायोएथेनॉल'' उत्पादन के लिए इनपुट सामग्री के रूप में उपयोग किया जाता है?', '"[{\"id\":\"A\",\"text\":\"सेलुलोज\",\"textEn\":\"Cellulose\"},{\"id\":\"B\",\"text\":\"चीनी\",\"textEn\":\"Sugar\"},{\"id\":\"C\",\"text\":\"स्टार्च\",\"textEn\":\"Starch\"},{\"id\":\"D\",\"text\":\"उपर्युक्त सभी\",\"textEn\":\"All of the above\"}]"', 'D', '{"verdict": "**विकल्प D सही उत्तर है**।", "core_concept": "जैव ईंधन: बायोएथेनॉल उत्पादन।", "elimination_wisdom": "बायोएथेनॉल चीनी (जैसे गन्ने का शीरा), स्टार्च (जैसे मक्का, कसावा), और सेलुलोज (कृषि अपशिष्ट) से उत्पादित किया जा सकता है। ये सभी बायोएथेनॉल के लिए फीडस्टॉक हैं, जो विभिन्न पीढ़ियों के जैव ईंधन का प्रतिनिधित्व करते हैं।", "trap_alerts": "बायोएथेनॉल के लिए केवल चीनी ही नहीं, बल्कि स्टार्च और सेलुलोज भी प्रमुख स्रोत हैं।"}', 2, 0, 18, 'Science', 'Which one of the following compounds is used as an input material for the ''bioethanol'' production?', '{"verdict": "**Option D is the correct answer**.", "core_concept": "Biofuels: Bioethanol production.", "elimination_wisdom": "Bioethanol can be produced from sugar (e.g., sugarcane molasses), starch (e.g., corn, cassava), and cellulose (agricultural waste). All of these are feedstocks for bioethanol, representing different generations of biofuels.", "trap_alerts": "Not just sugar, but starch and cellulose are also major sources for bioethanol."}', 60, 'standard', NULL, NULL, '{"layoutType":"standard","questionPrompt":"Which one of the following compounds is used as an input material for the ''bioethanol'' production?","questionPromptEn":"Which one of the following compounds is used as an input material for the ''bioethanol'' production?"}', 'upsc');
