There are _______ districts in Madhya Pradesh', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["वर्तमान में मध्य प्रदेश में कुल 55 ज़िले हैं।","2023 में तीन नए ज़िले बनाए गए थे: मऊगंज (Mauganj), पांढुर्णा (Pandhurna), और मैहर (Maihar)।","मऊगंज रीवा से, पांढुर्णा छिंदवाड़ा से और मैहर सतना से अलग होकर बने हैं।"],"factsEn":["Currently, there are 55 districts in Madhya Pradesh.","Three new districts were added in 2023: Mauganj, Pandhurna, and Maihar.","Mauganj was carved out of Rewa, Pandhurna from Chhindwara, and Maihar from Satna."],"mnemonics":["M-P has 5-5 districts! (Rhymes loosely to remember latest 55)"],"related":["Niwari was the 52nd district created in 2018."],"memoryTip":"एमपी पुलिस के एग्जाम में हमेशा लेटेस्ट ज़िलों का अपडेट (2023 के 3 नए ज़िले) पढ़कर जाना!"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9uAZnssyduXdEp7j4iTDV', '4dkhPsq6U4p7qF_tVJe1J', 'Q. 88)
