INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xEWRlZPBjsSP7c-OH6umZ', 'ic8HGDDApF4DYNBAn7DeE', 'पंडवानी गायन शैली की प्रसिद्ध कलाकार कौन हैं? / Who is the famous artist of Pandavani singing style?', '"[\"1) तीजन बाई / Teejan Bai\",\"2) गिरिजा देवी / Girija Devi\",\"3) शुभा मुद्गल / Shubha Mudgal\",\"4) अलका याज्ञनिक / Alka Yagnik\"]"', '1', NULL, 1, 0, 9, 'General', 'Who is the famous artist of Pandavani singing style?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["तीजन बाई पंडवानी लोकगायन की प्रसिद्ध कलाकार हैं।","वे छत्तीसगढ़ से संबंधित हैं।"],"factsEn":["Teejan Bai is famous for Pandavani folk singing.","She belongs to Chhattisgarh."],"mnemonics":["तीजन की तान = पंडवानी।"],"related":["लोककला","छत्तीसगढ़"],"memoryTip":"Pandavani सुनते ही Teejan Bai याद करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('IjRaOCEZlncXHguzOqEWF', 'ic8HGDDApF4DYNBAn7DeE', 'निम्न में से कौन संतूर वादक हैं? / Who among the following is a Santoor player?', '"[\"1) जाकिर हुसैन / Zakir Hussain\",\"2) शिवकुमार शर्मा / Shivkumar Sharma\",\"3) रवि शंकर / Ravi Shankar\",\"4) बिस्मिल्लाह खान / Bismillah Khan\"]"', '2', NULL, 1, 0, 10, 'General', 'Who among the following is a Santoor player?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पंडित शिवकुमार शर्मा संतूर वादन के लिए प्रसिद्ध थे।","उन्होंने संतूर को लोकप्रिय शास्त्रीय वाद्य बनाया।"],"factsEn":["Pandit Shivkumar Sharma was famous for Santoor.","He popularized Santoor as a classical instrument."],"mnemonics":["शिवकुमार शर्मा = संतूर शर्मा।"],"related":["वाद्य यंत्र","कश्मीर का संतूर"],"memoryTip":"Trap question: जाकिर = तबला, रवि = सितार, बिस्मिल्लाह = शहनाई।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Wc1FLnC4_B3OF4pnd-RM4', 'RDorT3G8BQOlU0nZMaQ9G', 'भरतनाट्यम किस राज्य का प्रसिद्ध शास्त्रीय नृत्य है?', '"[\"1) तमिलनाडु / Tamil Nadu\",\"2) केरल / Kerala\",\"3) कर्नाटक / Karnataka\",\"4) आंध्र प्रदेश / Andhra Pradesh\"]"', '1', NULL, 1, 0, 1, 'General', 'Bharatanatyam is the famous classical dance of which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भरतनाट्यम भारत का सबसे पुराना शास्त्रीय नृत्य है जो तमिलनाडु के हिंदू मंदिरों में उत्पन्न हुआ।","यह मुख्य रूप से दक्षिण भारतीय धार्मिक विषयों और शैव धर्म के आध्यात्मिक विचारों को व्यक्त करता है।"],"factsEn":["Bharatanatyam is the oldest classical dance of India that originated in the Hindu temples of Tamil Nadu.","It primarily expresses South Indian religious themes and spiritual ideas of Shaivism."],"mnemonics":["B-T-N: Bharatanatyam -> Tamil Nadu"],"related":["रुक्मिणी देवी अरुंडेल (प्रसिद्ध नर्तकी) / Rukmini Devi Arundale (Famous Dancer)"],"memoryTip":"भारत (भरत) का दक्षिण छोर तमिलनाडु है। (For more MP Police test series, visit mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('wb0JR4DYbN-O4I4nKfsJJ', 'RDorT3G8BQOlU0nZMaQ9G', 'कुचिपुड़ी किस भारतीय राज्य का शास्त्रीय नृत्य है?', '"[\"1) ओडिशा / Odisha\",\"2) आंध्र प्रदेश / Andhra Pradesh\",\"3) मणिपुर / Manipur\",\"4) तेलंगाना / Telangana\"]"', '2', NULL, 1, 0, 2, 'General', 'Kuchipudi is the classical dance of which Indian state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कुचिपुड़ी का नाम आंध्र प्रदेश के कृष्णा जिले के एक गांव कुचिपुड़ी के नाम पर रखा गया है।","यह नृत्य अपने तेज फुटवर्क और नाटकीय चरित्र चित्रण के लिए जाना जाता है।"],"factsEn":["Kuchipudi is named after a village in the Krishna district of Andhra Pradesh.","The dance is known for its fast footwork and dramatic characterization."],"mnemonics":["Kuchi-Andhra: कच्ची पूरी (कुचिपुड़ी) अंधा (आंध्र प्रदेश) आदमी खा गया।"],"related":["यामिनी कृष्णमूर्ति (प्रसिद्ध नर्तकी) / Yamini Krishnamurthy (Famous Dancer)"],"memoryTip":"कुचिपुड़ी और आंध्र प्रदेश हमेशा एक साथ आते हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('C5sn615Sg-Huh9cbjiZTD', 'RDorT3G8BQOlU0nZMaQ9G', 'प्रसिद्ध नृत्य रूप ''कथकली'' मुख्य रूप से किस राज्य से संबंधित है?', '"[\"1) केरल / Kerala\",\"2) असम / Assam\",\"3) तमिलनाडु / Tamil Nadu\",\"4) महाराष्ट्र / Maharashtra\"]"', '1', NULL, 1, 0, 3, 'General', 'The famous dance form ''Kathakali'' is primarily associated with which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कथकली केरल का एक शास्त्रीय नृत्य-नाटक है जो अपने विस्तृत मेकअप और वेशभूषा के लिए विश्व प्रसिद्ध है।","यह पारंपरिक रूप से पुरुष अभिनेताओं-नर्तकों द्वारा प्रदर्शित किया जाता है जो महाभारत और रामायण की कहानियों को दर्शाते हैं।"],"factsEn":["Kathakali is a classical dance-drama from Kerala, world-renowned for its elaborate makeup and costumes.","It is traditionally performed by male actor-dancers depicting stories from the Mahabharata and Ramayana."],"mnemonics":["K-K: Kathakali -> Kerala"],"related":["मोहिनीअट्टम (केरल का दूसरा शास्त्रीय नृत्य) / Mohiniyattam (Second classical dance of Kerala)"],"memoryTip":"''कली'' (कथकली) ''केरल'' के बागों में खिलती है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Ci_C_3cqxFKYLxFynAvJb', 'RDorT3G8BQOlU0nZMaQ9G', 'उत्तर भारत (विशेषकर उत्तर प्रदेश) का प्रमुख शास्त्रीय नृत्य कौन सा है?', '"[\"1) कथक / Kathak\",\"2) ओडिसी / Odissi\",\"3) सत्त्रिया / Sattriya\",\"4) मोहिनीअट्टम / Mohiniyattam\"]"', '1', NULL, 1, 0, 4, 'General', 'Which is the major classical dance of North India (especially Uttar Pradesh)?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कथक उत्तर भारत का शास्त्रीय नृत्य है। ''कथक'' शब्द ''कथा'' से लिया गया है जिसका अर्थ है कहानी।","यह नृत्य लखनऊ, जयपुर और बनारस घरानों (शैलियों) में विकसित हुआ है।"],"factsEn":["Kathak is the classical dance of North India. The word ''Kathak'' is derived from ''Katha'', meaning story.","This dance has evolved into Lucknow, Jaipur, and Benares gharanas (styles)."],"mnemonics":["UP ki Katha"],"related":["पंडित बिरजू महाराज (कथक के महान नर्तक) / Pandit Birju Maharaj (Great dancer of Kathak)"],"memoryTip":"''कथा'' सुनाने वाले ''उत्तर'' (North) की ओर मुंह करके बैठते हैं। (Practice more on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('TsNd5Kbj4i8j3ICgxsGVY', 'RDorT3G8BQOlU0nZMaQ9G', '''सत्त्रिया'' नृत्य किस राज्य का एक पारंपरिक हिंदू शास्त्रीय नृत्य है?', '"[\"1) पश्चिम बंगाल / West Bengal\",\"2) मिजोरम / Mizoram\",\"3) असम / Assam\",\"4) त्रिपुरा / Tripura\"]"', '3', NULL, 1, 0, 5, 'General', '''Sattriya'' dance is a traditional Hindu classical dance of which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["सत्त्रिया को 2000 में संगीत नाटक अकादमी द्वारा शास्त्रीय नृत्य का दर्जा दिया गया था।","इसकी उत्पत्ति 15वीं शताब्दी में असम के वैष्णव संत श्रीमंत शंकरदेव द्वारा की गई थी।"],"factsEn":["Sattriya was given the status of classical dance by the Sangeet Natak Akademi in 2000.","It was originated in the 15th century by Vaishnava saint Srimanta Sankardev in Assam."],"mnemonics":["S-A: Sattriya -> Assam"],"related":["बिहू (असम का लोक नृत्य) / Bihu (Folk dance of Assam)"],"memoryTip":"असम की चाय ''सत्य'' (सत्त्रिया) में बहुत अच्छी होती है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('-X-CshnnCeSjx_fqaIR34', 'RDorT3G8BQOlU0nZMaQ9G', 'मध्य प्रदेश का प्रसिद्ध लोक नृत्य ''राई'' मुख्य रूप से किस अंचल से संबंधित है?', '"[\"1) मालवा / Malwa\",\"2) बुंदेलखंड / Bundelkhand\",\"3) बघेलखंड / Baghelkhand\",\"4) निमाड़ / Nimar\"]"', '2', NULL, 1, 0, 6, 'General', 'The famous folk dance ''Rai'' of Madhya Pradesh is primarily associated with which region?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["''राई'' मध्य प्रदेश के बुंदेलखंड क्षेत्र का एक पारंपरिक लोक नृत्य है।","यह नृत्य बेड़िया जनजाति से जुड़ा है और अक्सर ढोलक और नगाड़े की धुन पर प्रदर्शित किया जाता है।"],"factsEn":["''Rai'' is a traditional folk dance of the Bundelkhand region of Madhya Pradesh.","This dance is associated with the Bedia tribe and is often performed to the beats of dholak and nagada."],"mnemonics":["Bundeli Rai"],"related":["बधाई नृत्य (बुंदेलखंड) / Badhai Dance (Bundelkhand)"],"memoryTip":"बुंदेलखंड के लोग राई (सरसों) की तरह चटकते हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('jXh9i1PW8DFlRVLFzLaRs', 'RDorT3G8BQOlU0nZMaQ9G', '''मटकी'' नृत्य मध्य प्रदेश के किस क्षेत्र का एक लोकप्रिय लोक नृत्य है?', '"[\"1) मालवा / Malwa\",\"2) महाकौशल / Mahakoshal\",\"3) निमाड़ / Nimar\",\"4) चंबल / Chambal\"]"', '1', NULL, 1, 0, 7, 'General', '''Matki'' dance is a popular folk dance of which region of Madhya Pradesh?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["मटकी मालवा क्षेत्र का एक सामुदायिक नृत्य है जो विशेषकर महिलाओं द्वारा विवाह और त्योहारों के अवसर पर किया जाता है।","नर्तकी अपने सिर पर एक मिट्टी का घड़ा (मटकी) संतुलित करती है।"],"factsEn":["Matki is a community dance of the Malwa region performed especially by women on the occasion of marriages and festivals.","The dancer balances an earthen pot (matki) on her head."],"mnemonics":["M-M: Matki -> Malwa"],"related":["आड़ा-खड़ा नृत्य (मालवा) / Aada-Khada Dance (Malwa)"],"memoryTip":"मालवा की महिलाएं ''मटकी'' में पानी भरती हैं। (Check mppsc.zenscroll.app for MP static GK)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('IwyYjj4nVBoGz0klt5OLX', 'RDorT3G8BQOlU0nZMaQ9G', '''मोहिनीअट्टम'' शास्त्रीय नृत्य किस राज्य से उत्पन्न हुआ है?', '"[\"1) केरल / Kerala\",\"2) कर्नाटक / Karnataka\",\"3) तमिलनाडु / Tamil Nadu\",\"4) ओडिशा / Odisha\"]"', '1', NULL, 1, 0, 8, 'General', '''Mohiniyattam'' classical dance originated from which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["मोहिनीअट्टम केरल का एक शास्त्रीय नृत्य है जो मुख्य रूप से महिलाओं द्वारा किया जाता है।","इसका नाम हिंदू देवता विष्णु के स्त्री रूप ''मोहिनी'' से लिया गया है।"],"factsEn":["Mohiniyattam is a classical dance from Kerala performed primarily by women.","Its name is derived from ''Mohini'', the female avatar of the Hindu god Vishnu."],"mnemonics":["Mohini-Kerala"],"related":["कथकली (केरल का अन्य शास्त्रीय नृत्य) / Kathakali (Other classical dance of Kerala)"],"memoryTip":"भगवान विष्णु मोहिनी का रूप धारण करके ''केरल'' गए।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('F_ZmlMYkab350bkTdBybm', 'RDorT3G8BQOlU0nZMaQ9G', '''गरबा'' किस राज्य का एक अत्यंत लोकप्रिय लोक नृत्य है?', '"[\"1) राजस्थान / Rajasthan\",\"2) गुजरात / Gujarat\",\"3) पंजाब / Punjab\",\"4) हरियाणा / Haryana\"]"', '2', NULL, 1, 0, 9, 'General', '''Garba'' is a very popular folk dance of which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["गरबा गुजरात का एक लोकप्रिय लोक नृत्य है जो मुख्य रूप से नवरात्रि के त्योहार के दौरान किया जाता है।","यह पारंपरिक रूप से ''गरबा दीप'' (दीपक) के चारों ओर गोलाकार रूप में किया जाता है।"],"factsEn":["Garba is a popular folk dance of Gujarat, performed primarily during the Navratri festival.","It is traditionally performed in a circle around the ''Garba Deep'' (lamp)."],"mnemonics":["G-G: Garba -> Gujarat"],"related":["डांडिया रास (गुजरात) / Dandiya Raas (Gujarat)","घूमर (राजस्थान) / Ghoomar (Rajasthan)"],"memoryTip":"गरबा और गुजरात दोनों ''ग'' से शुरू होते हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('iWUkhyjzD_CSuBK5U0TA7', 'RDorT3G8BQOlU0nZMaQ9G', '''बिहू'' नृत्य किस भारतीय राज्य का एक पारंपरिक लोक नृत्य है?', '"[\"1) असम / Assam\",\"2) सिक्किम / Sikkim\",\"3) मेघालय / Meghalaya\",\"4) नागालैंड / Nagaland\"]"', '1', NULL, 1, 0, 10, 'General', '''Bihu'' dance is a traditional folk dance of which Indian state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["बिहू असम का एक स्वदेशी लोक नृत्य है जो मुख्य रूप से बोहाग बिहू (असमिया नव वर्ष और वसंत उत्सव) के दौरान किया जाता है।","यह युवा पुरुषों और महिलाओं दोनों द्वारा किया जाने वाला एक ऊर्जावान नृत्य है।"],"factsEn":["Bihu is an indigenous folk dance of Assam, performed primarily during Bohag Bihu (Assamese New Year and spring festival).","It is an energetic dance performed by both young men and women."],"mnemonics":["A-B: Assam -> Bihu"],"related":["बागुरुम्बा (असम का बोडो लोक नृत्य) / Bagurumba (Bodo folk dance of Assam)"],"memoryTip":"असम की ''बहू'' (बिहू) बहुत अच्छा नृत्य करती है। (Track PYQs on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fS4o575KKhFbX10Ao_KfZ', 'Da3Htx-obYIs2OzpSrrHN', '‘स्टैच्यू ऑफ यूनिटी’ किस भारतीय नेता की प्रतिमा है? / ''Statue of Unity'' is the statue of which Indian leader?', '"[\"1) महात्मा गांधी / Mahatma Gandhi\",\"2) सरदार वल्लभभाई पटेल / Sardar Vallabhbhai Patel\",\"3) जवाहरलाल नेहरू / Jawaharlal Nehru\",\"4) सुभाष चंद्र बोस / Subhash Chandra Bose\"]"', '2', NULL, 1, 0, 1, 'General', '''Statue of Unity'' is the statue of which Indian leader?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["स्टैच्यू ऑफ यूनिटी गुजरात में स्थित है।","यह सरदार वल्लभभाई पटेल की प्रतिमा है।","यह विश्व की ऊंची प्रतिमाओं में से एक है।"],"factsEn":["Statue of Unity is located in Gujarat.","It is the statue of Sardar Vallabhbhai Patel.","It is among the tallest statues in the world."],"mnemonics":["Unity = Iron Man Patel = एकता।"],"related":["गुजरात","नर्मदा नदी"],"memoryTip":"Unity शब्द आते ही पटेल याद करें।"}}', 'mppolice');
