INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0id8GENSnAdbjt4n5B_ck', 'Da3Htx-obYIs2OzpSrrHN', '‘लायन कैपिटल ऑफ अशोक’ भारत का राष्ट्रीय प्रतीक कहाँ से लिया गया है? / The Lion Capital of Ashoka, India''s national emblem, is taken from where?', '"[\"1) सांची / Sanchi\",\"2) सारनाथ / Sarnath\",\"3) बोधगया / Bodh Gaya\",\"4) नालंदा / Nalanda\"]"', '2', NULL, 1, 0, 9, 'General', 'The Lion Capital of Ashoka, India''s national emblem, is taken from where?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भारत का राष्ट्रीय प्रतीक अशोक स्तंभ के सिंह शीर्ष से लिया गया है।","यह सारनाथ में मिला था।"],"factsEn":["India''s national emblem is adopted from the Lion Capital of Ashoka.","It was found at Sarnath."],"mnemonics":["सिंह शीर्ष = सारनाथ।"],"related":["अशोक","राष्ट्रीय प्रतीक"],"memoryTip":"National Emblem = Sarnath."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xwekjd1CBBh_zddVYE3lh', 'Da3Htx-obYIs2OzpSrrHN', 'एलिफेंटा गुफाओं में मुख्य रूप से किस देवता की मूर्तियां हैं? / Sculptures in Elephanta Caves mainly depict which deity?', '"[\"1) शिव / Shiva\",\"2) विष्णु / Vishnu\",\"3) राम / Rama\",\"4) बुद्ध / Buddha\"]"', '1', NULL, 1, 0, 10, 'General', 'Sculptures in Elephanta Caves mainly depict which deity?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["एलिफेंटा गुफाएं शिव मूर्तियों के लिए प्रसिद्ध हैं।","त्रिमूर्ति शिव वहां की प्रमुख प्रतिमा है।"],"factsEn":["Elephanta Caves are famous for Shiva sculptures.","Trimurti Shiva is the main sculpture there."],"mnemonics":["Elephanta में Elephant नहीं, शिव प्रसिद्ध।"],"related":["मुंबई","गुफा कला"],"memoryTip":"Elephanta = Shiva sculptures."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('SQy1LJq-kgc7_DR97spay', '7gsWBOpr68QYXtQI7Q2Sn', 'खजुराहो के प्रसिद्ध मंदिरों का निर्माण किस राजवंश के शासकों ने करवाया था?', '"[\"1) चंदेल / Chandela\",\"2) परमार / Parmara\",\"3) गुप्त / Gupta\",\"4) मौर्य / Maurya\"]"', '1', NULL, 1, 0, 1, 'General', 'The famous temples of Khajuraho were built by the rulers of which dynasty?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["खजुराहो के मंदिरों का निर्माण चंदेल राजवंश द्वारा 950 ईस्वी से 1050 ईस्वी के बीच किया गया था।","ये मंदिर अपनी नागर शैली की वास्तुकला और कामुक मूर्तियों के लिए यूनेस्को (UNESCO) विश्व धरोहर स्थल हैं।"],"factsEn":["The Khajuraho temples were built by the Chandela dynasty between 950 AD and 1050 AD.","These temples are a UNESCO World Heritage site for their Nagara-style architecture and erotic sculptures."],"mnemonics":["K-C: Khajuraho -> Chandela"],"related":["कंदरिया महादेव मंदिर (खजुराहो का सबसे बड़ा मंदिर) / Kandariya Mahadeva Temple (Largest in Khajuraho)"],"memoryTip":"चंदेलों ने खजुराहो में ''चांद'' (Chanda) जैसी चमक बिखेरी। (For more MP Tourism GK, visit mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('n1-LHG_1UeB4i2hH-1dT9', '7gsWBOpr68QYXtQI7Q2Sn', 'सांची का स्तूप, जो भारत के सबसे पुराने पत्थर के ढांचों में से एक है, का निर्माण किसने करवाया था?', '"[\"1) चंद्रगुप्त मौर्य / Chandragupta Maurya\",\"2) सम्राट अशोक / Emperor Ashoka\",\"3) कनिष्क / Kanishka\",\"4) पुष्यमित्र शुंग / Pushyamitra Shunga\"]"', '2', NULL, 1, 0, 2, 'General', 'Who built the Sanchi Stupa, which is one of the oldest stone structures in India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["सांची का महान स्तूप मूल रूप से तीसरी शताब्दी ईसा पूर्व में मौर्य सम्राट अशोक द्वारा बनवाया गया था।","यह मध्य प्रदेश के रायसेन जिले में स्थित है और बौद्ध धर्म का एक प्रमुख केंद्र है।"],"factsEn":["The Great Stupa at Sanchi was originally commissioned by the Mauryan emperor Ashoka in the 3rd century BCE.","It is located in the Raisen district of Madhya Pradesh and is a major center of Buddhism."],"mnemonics":["A-S: Ashoka -> Sanchi"],"related":["भरहुत स्तूप (सतना) / Bharhut Stupa (Satna)"],"memoryTip":"''अशोक'' ने शांति के लिए ''सांची'' का स्तूप बनवाया।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Q-NUkJPh9IRE67-QyiuwT', '7gsWBOpr68QYXtQI7Q2Sn', 'मध्य प्रदेश के किस पर्यटन स्थल को ''सिटी ऑफ जॉय'' (आनंद की नगरी) के नाम से जाना जाता है?', '"[\"1) पचमढ़ी / Pachmarhi\",\"2) मांडू / Mandu\",\"3) ओरछा / Orchha\",\"4) भेड़ाघाट / Bhedaghat\"]"', '2', NULL, 1, 0, 3, 'General', 'Which tourist destination of Madhya Pradesh is known as the ''City of Joy''?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["मांडू (मांडवगढ़) धार जिले में स्थित एक प्राचीन शहर है, जिसे ''सिटी ऑफ जॉय'' या ''शादियाबाद'' भी कहा जाता है।","यह रानी रूपमती और बाज बहादुर की प्रेम कहानी तथा जहाज महल के लिए प्रसिद्ध है।"],"factsEn":["Mandu (Mandavgarh) is an ancient city located in Dhar district, also known as the ''City of Joy'' or ''Shadiabad''.","It is famous for the love story of Rani Roopmati and Baz Bahadur, and the Jahaz Mahal."],"mnemonics":["Man-Joy (Mandu is Joy)"],"related":["जहाज महल (मांडू) / Jahaz Mahal (Mandu)","हिंडोला महल (मांडू) / Hindola Mahal (Mandu)"],"memoryTip":"''मांडू'' जाने से मन को ''आनंद'' (Joy) मिलता है। (Practice historical places on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ps-7t5Xhs6vRNFhOjqCiU', '7gsWBOpr68QYXtQI7Q2Sn', '''भारत के किलों का रत्न'' (जिब्राल्टर ऑफ इंडिया) किस ऐतिहासिक किले को कहा जाता है?', '"[\"1) लाल किला / Red Fort\",\"2) चित्तौड़गढ़ किला / Chittorgarh Fort\",\"3) ग्वालियर का किला / Gwalior Fort\",\"4) आगरा का किला / Agra Fort\"]"', '3', NULL, 1, 0, 4, 'General', 'Which historical fort is known as the ''Pearl of Indian Fortresses'' (Gibraltar of India)?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["ग्वालियर के किले को मुगल सम्राट बाबर द्वारा ''भारत के किलों के हार में मोती'' (जिब्राल्टर ऑफ इंडिया) कहा गया था।","इस किले का निर्माण मूल रूप से 8वीं शताब्दी में स्थानीय शासक सूरज सेन द्वारा किया गया था।"],"factsEn":["The Gwalior Fort was referred to as the ''pearl in the necklace of the forts of Hind'' (Gibraltar of India) by Mughal Emperor Babur.","The fort was originally built in the 8th century by a local ruler Suraj Sen."],"mnemonics":["Gwalior - Gibraltar"],"related":["मान सिंह महल (ग्वालियर किला) / Man Singh Palace (Gwalior Fort)","गुजरी महल (ग्वालियर) / Gujari Mahal (Gwalior)"],"memoryTip":"ग्वालियर (Gwalior) और जिब्राल्टर (Gibraltar) दोनों ''G'' से शुरू होते हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ppTjOFBU5tMQxqwn-oPo7', '7gsWBOpr68QYXtQI7Q2Sn', 'मध्य प्रदेश में स्थित भीमबेटका की गुफाएं किसके लिए प्रसिद्ध हैं?', '"[\"1) बौद्ध मूर्तियां / Buddhist statues\",\"2) रॉक शेल्टर और प्रागैतिहासिक चित्रकला / Rock shelters and prehistoric paintings\",\"3) शिव मंदिर / Shiva temples\",\"4) जैन वास्तुकला / Jain architecture\"]"', '2', NULL, 1, 0, 5, 'General', 'What are the Bhimbetka caves located in Madhya Pradesh famous for?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भीमबेटका (रायसेन जिले में) अपने प्रागैतिहासिक रॉक शेल्टर (पाषाण आश्रय) और गुफा चित्रों के लिए प्रसिद्ध है, जो पाषाण काल के हैं।","इसकी खोज 1957 में डॉ. वी.एस. वाकणकर ने की थी और यह यूनेस्को विश्व धरोहर स्थल है।"],"factsEn":["Bhimbetka (in Raisen district) is famous for its prehistoric rock shelters and cave paintings dating back to the Stone Age.","It was discovered by Dr. V.S. Wakankar in 1957 and is a UNESCO World Heritage site."],"mnemonics":["Bhim-Rock: भीम जैसी विशाल चट्टानों (Rock) पर चित्रकला।"],"related":["उदयगिरि की गुफाएं (विदिशा) / Udayagiri Caves (Vidisha)","बाघ की गुफाएं (धार) / Bagh Caves (Dhar)"],"memoryTip":"''भीम'' के समय से लोग इन चट्टानों (Rocks) पर चित्र बना रहे हैं। (Master art & culture on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Q2FUiR1L7cor9kZbcVHmw', '7gsWBOpr68QYXtQI7Q2Sn', 'प्रसिद्ध ऐतिहासिक स्मारक ''ताजमहल'' किस नदी के तट पर स्थित है?', '"[\"1) गंगा / Ganga\",\"2) यमुना / Yamuna\",\"3) गोमती / Gomti\",\"4) चंबल / Chambal\"]"', '2', NULL, 1, 0, 6, 'General', 'The famous historical monument ''Taj Mahal'' is situated on the banks of which river?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["ताजमहल उत्तर प्रदेश के आगरा शहर में यमुना नदी के दाहिने किनारे पर स्थित है।","इसे मुगल सम्राट शाहजहां ने अपनी पत्नी मुमताज महल की याद में 1632 में बनवाना शुरू किया था।"],"factsEn":["The Taj Mahal is located on the right bank of the Yamuna River in the city of Agra, Uttar Pradesh.","It was commissioned in 1632 by the Mughal emperor Shah Jahan to house the tomb of his wife, Mumtaz Mahal."],"mnemonics":["T-Y: Taj -> Yamuna"],"related":["आगरा का किला (यमुना नदी) / Agra Fort (Yamuna River)","फतेहपुर सीकरी (आगरा के पास) / Fatehpur Sikri (Near Agra)"],"memoryTip":"मुमताज की याद में ''ताज'' यमुना (Yamuna) के किनारे खड़ा है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('gT4VdALIBT9jBwLZFbYHz', '7gsWBOpr68QYXtQI7Q2Sn', 'बेतवा नदी के तट पर स्थित ''ओरछा'' की स्थापना किस राजवंश के शासकों ने की थी?', '"[\"1) बुंदेला / Bundela\",\"2) तोमर / Tomar\",\"3) सिंधिया / Scindia\",\"4) होल्कर / Holkar\"]"', '1', NULL, 1, 0, 7, 'General', 'Orchha, situated on the banks of the Betwa river, was established by the rulers of which dynasty?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["ओरछा की स्थापना 16वीं शताब्दी में बुंदेला राजपूत रुद्र प्रताप सिंह ने की थी।","यह शहर बेतवा नदी के किनारे स्थित है और अपने महलों, राम राजा मंदिर और छतरियों के लिए प्रसिद्ध है।"],"factsEn":["Orchha was established in the 16th century by the Bundela Rajput Rudra Pratap Singh.","The town is situated on the banks of the Betwa River and is famous for its palaces, Ram Raja Temple, and Chhatris."],"mnemonics":["O-B: Orchha -> Bundela"],"related":["जहांगीर महल (ओरछा) / Jahangir Mahal (Orchha)","चतुर्भुज मंदिर (ओरछा) / Chaturbhuj Temple (Orchha)"],"memoryTip":"ओरछा में बुंदेलों का राज चलता था। (Revise MP dynasties on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5b2cnZ9RbVKH5dIbS7HBz', '7gsWBOpr68QYXtQI7Q2Sn', 'महाराष्ट्र में स्थित यूनेस्को विश्व धरोहर ''अजंता की गुफाएं'' मुख्य रूप से किस धर्म से संबंधित हैं?', '"[\"1) हिंदू धर्म / Hinduism\",\"2) जैन धर्म / Jainism\",\"3) बौद्ध धर्म / Buddhism\",\"4) सिख धर्म / Sikhism\"]"', '3', NULL, 1, 0, 8, 'General', 'The UNESCO World Heritage ''Ajanta Caves'' located in Maharashtra are primarily associated with which religion?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["अजंता की गुफाएं लगभग 30 रॉक-कट बौद्ध गुफा स्मारक हैं जो महाराष्ट्र के औरंगाबाद (अब छत्रपति संभाजी नगर) जिले में स्थित हैं।","इन गुफाओं में भित्ति चित्र (Murals) और मूर्तियां हैं जो बौद्ध धार्मिक कला की उत्कृष्ट कृतियां हैं।"],"factsEn":["The Ajanta Caves are approximately 30 rock-cut Buddhist cave monuments located in the Aurangabad (now Chhatrapati Sambhajinagar) district of Maharashtra.","These caves feature murals and sculptures that are masterpieces of Buddhist religious art."],"mnemonics":["A-B: Ajanta -> Buddhism"],"related":["एलोरा की गुफाएं (हिंदू, बौद्ध, जैन) / Ellora Caves (Hindu, Buddhist, Jain)","एलीफेंटा की गुफाएं (मुख्य रूप से शिव) / Elephanta Caves (Primarily Shiva)"],"memoryTip":"''अजंता'' में भगवान ''बुद्ध'' (Buddhism) शांति से बैठे हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('8Xff_ZDLQ73F-WxJu7xJA', '7gsWBOpr68QYXtQI7Q2Sn', 'यूनेस्को विश्व धरोहर स्थल ''हम्पी'' किस प्राचीन साम्राज्य की राजधानी थी?', '"[\"1) चोल साम्राज्य / Chola Empire\",\"2) मराठा साम्राज्य / Maratha Empire\",\"3) विजयनगर साम्राज्य / Vijayanagara Empire\",\"4) मौर्य साम्राज्य / Maurya Empire\"]"', '3', NULL, 1, 0, 9, 'General', 'The UNESCO World Heritage Site ''Hampi'' was the capital of which ancient empire?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["हम्पी कर्नाटक में स्थित एक प्राचीन गाँव है जो 14वीं शताब्दी में विजयनगर साम्राज्य की राजधानी था।","यह तुंगभद्रा नदी के तट पर स्थित है और अपने शानदार मंदिरों (जैसे विरुपाक्ष मंदिर) और खंडहरों के लिए जाना जाता है।"],"factsEn":["Hampi is an ancient village in Karnataka that was the capital of the Vijayanagara Empire in the 14th century.","It is located on the banks of the Tungabhadra River and is known for its magnificent temples (like Virupaksha Temple) and ruins."],"mnemonics":["H-V: Hampi -> Vijayanagara"],"related":["विरुपाक्ष मंदिर (हम्पी) / Virupaksha Temple (Hampi)","विट्ठल मंदिर (हम्पी) / Vitthala Temple (Hampi)"],"memoryTip":"विजयनगर ने ''हम्पी'' में अपनी ''विजय'' का डंका बजाया।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5ilXEYGLnQgkMICGEyNqa', '7gsWBOpr68QYXtQI7Q2Sn', '''ब्लैक पैगोडा'' (Black Pagoda) के नाम से प्रसिद्ध सूर्य मंदिर कहाँ स्थित है?', '"[\"1) खजुराहो, मध्य प्रदेश / Khajuraho, Madhya Pradesh\",\"2) कोणार्क, ओडिशा / Konark, Odisha\",\"3) मदुरै, तमिलनाडु / Madurai, Tamil Nadu\",\"4) महाबलीपुरम, तमिलनाडु / Mahabalipuram, Tamil Nadu\"]"', '2', NULL, 1, 0, 10, 'General', 'Where is the Sun Temple, famously known as the ''Black Pagoda'', located?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कोणार्क सूर्य मंदिर ओडिशा के पुरी जिले में स्थित है। इसका निर्माण 13वीं शताब्दी में पूर्वी गंग वंश के राजा नरसिंहदेव प्रथम ने करवाया था।","इसके गहरे रंग के कारण यूरोपीय नाविकों द्वारा इसे ''ब्लैक पैगोडा'' कहा जाता था।"],"factsEn":["The Konark Sun Temple is located in the Puri district of Odisha. It was built in the 13th century by King Narasimhadeva I of the Eastern Ganga dynasty.","It was called the ''Black Pagoda'' by European sailors due to its dark color."],"mnemonics":["K-S-B: Konark Sun Black"],"related":["जगन्नाथ मंदिर (पुरी - व्हाइट पैगोडा) / Jagannath Temple (Puri - White Pagoda)"],"memoryTip":"सूर्य की तेज किरणों (Sun Temple) से ''कोण'' (Konark) ''ब्लैक'' हो गया। (Test your logic on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('L7D7ibf7AaBh9CdNoN6Lz', 'G5X9_U-QI-j3TyKTGw8rY', 'उस्ताद बिस्मिल्लाह खान किस वाद्य यंत्र के लिए प्रसिद्ध थे? / Ustad Bismillah Khan was famous for which musical instrument?', '"[\"1) सितार / Sitar\",\"2) शहनाई / Shehnai\",\"3) तबला / Tabla\",\"4) बांसुरी / Flute\"]"', '2', NULL, 1, 0, 1, 'General', 'Ustad Bismillah Khan was famous for which musical instrument?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["उस्ताद बिस्मिल्लाह खान शहनाई वादन के महान कलाकार थे।","उन्हें भारत रत्न से सम्मानित किया गया था।"],"factsEn":["Ustad Bismillah Khan was a great Shehnai maestro.","He was awarded Bharat Ratna."],"mnemonics":["बिस्मिल्लाह की शादी = शहनाई।"],"related":["भारत रत्न","शास्त्रीय संगीत"],"memoryTip":"बिस्मिल्लाह खान सुनते ही शहनाई याद करें।"}}', 'mppolice');
