INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('b0S5W9lNGX36E6JKY6Peb', 'G5X9_U-QI-j3TyKTGw8rY', 'वीणा किस प्रकार का वाद्य यंत्र है? / Veena belongs to which category of instrument?', '"[\"1) ताल वाद्य / Percussion\",\"2) तार वाद्य / String\",\"3) वायु वाद्य / Wind\",\"4) घर्षण वाद्य / Friction\"]"', '2', NULL, 1, 0, 7, 'General', 'Veena belongs to which category of instrument?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["वीणा भारतीय प्राचीन तार वाद्य यंत्र है।","इसे देवी सरस्वती से जोड़ा जाता है।"],"factsEn":["Veena is an ancient Indian string instrument.","It is associated with Goddess Saraswati."],"mnemonics":["वीणा के तार = तार वाद्य।"],"related":["सरस्वती","शास्त्रीय संगीत"],"memoryTip":"Veena = String instrument."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('RPLdd1TmimGa2icAHZYrH', 'G5X9_U-QI-j3TyKTGw8rY', 'शहनाई किस वर्ग का वाद्य यंत्र है? / Shehnai belongs to which class of instrument?', '"[\"1) वायु वाद्य / Wind\",\"2) तार वाद्य / String\",\"3) ताल वाद्य / Percussion\",\"4) इलेक्ट्रॉनिक / Electronic\"]"', '1', NULL, 1, 0, 8, 'General', 'Shehnai belongs to which class of instrument?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["शहनाई फूंक कर बजाई जाती है।","इसलिए यह वायु वाद्य है।"],"factsEn":["Shehnai is played by blowing air.","Hence it is a wind instrument."],"mnemonics":["शहनाई में सांस = वायु वाद्य।"],"related":["बिस्मिल्लाह खान","वायु वाद्य"],"memoryTip":"Blow instrument = Wind class."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Cm5E0CiMWYbxFbajNga10', 'G5X9_U-QI-j3TyKTGw8rY', 'निम्न में से कौन सा युग्म सही सुमेलित है? / Which of the following pair is correctly matched?', '"[\"1) जाकिर हुसैन - शहनाई / Zakir Hussain - Shehnai\",\"2) रवि शंकर - सितार / Ravi Shankar - Sitar\",\"3) बिस्मिल्लाह खान - तबला / Bismillah Khan - Tabla\",\"4) हरिप्रसाद चौरसिया - संतूर / Hariprasad Chaurasia - Santoor\"]"', '2', NULL, 1, 0, 9, 'General', 'Which of the following pair is correctly matched?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["रवि शंकर सितार वादक थे।","अन्य विकल्प जानबूझकर गलत जोड़े गए हैं।"],"factsEn":["Ravi Shankar was a sitar player.","Other options are intentionally mismatched."],"mnemonics":["रवि के तार = सितार सही जोड़ी।"],"related":["वाद्य कलाकार","Matching questions"],"memoryTip":"Trap questions में known pairs याद रखें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('KQdCLSEuABLqjUg2S0BvY', 'G5X9_U-QI-j3TyKTGw8rY', 'निम्न में से कौन सा ताल वाद्य यंत्र है? / Which of the following is a percussion instrument?', '"[\"1) तबला / Tabla\",\"2) सितार / Sitar\",\"3) बांसुरी / Flute\",\"4) शहनाई / Shehnai\"]"', '1', NULL, 1, 0, 10, 'General', 'Which of the following is a percussion instrument?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["तबला हाथों से बजाया जाने वाला ताल वाद्य है।","यह लय देने के लिए उपयोग होता है।"],"factsEn":["Tabla is a percussion instrument played with hands.","It is used for rhythm."],"mnemonics":["तबला = थपकी = ताल।"],"related":["ताल वाद्य","जाकिर हुसैन"],"memoryTip":"Hit instrument = Percussion."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('6VNpk7F3zfSnvn9zfEMKu', 'RB70XH6legjyFDNu7WEFc', 'भारत का सबसे दक्षिणी बिंदु कौन सा है?', '"[\"1) कन्याकुमारी / Kanyakumari\",\"2) इंदिरा पॉइंट / Indira Point\",\"3) इंदिरा कोल / Indira Col\",\"4) किबिथू / Kibithu\"]"', '2', NULL, 1, 0, 1, 'General', 'Which is the southernmost point of India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भारत का सबसे दक्षिणी बिंदु ''इंदिरा पॉइंट'' है, जो ग्रेट निकोबार द्वीप में स्थित है।","2004 की सूनामी के दौरान यह जलमग्न हो गया था, लेकिन यह अभी भी आधिकारिक दक्षिणी बिंदु है।"],"factsEn":["The southernmost point of India is ''Indira Point'', located in the Great Nicobar Island.","It was submerged during the 2004 tsunami, but it remains the official southernmost point."],"mnemonics":["Indira is at the Point (Bottom) and Col (Top)"],"related":["मुख्य भूमि का दक्षिणी बिंदु (कन्याकुमारी) / Southernmost point of mainland (Kanyakumari)","उत्तरी बिंदु (इंदिरा कोल) / Northernmost point (Indira Col)"],"memoryTip":"इंडिया के पैरों (दक्षिण) में ''पॉइंट'' (Indira Point) है और सिर (उत्तर) पर ''कोल'' (Indira Col)।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('B2S_oieYcRfO9wrRUFvjf', 'RB70XH6legjyFDNu7WEFc', 'भारत किस देश के साथ सबसे लंबी अंतरराष्ट्रीय सीमा साझा करता है?', '"[\"1) चीन / China\",\"2) पाकिस्तान / Pakistan\",\"3) नेपाल / Nepal\",\"4) बांग्लादेश / Bangladesh\"]"', '4', NULL, 1, 0, 2, 'General', 'India shares the longest international border with which country?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भारत बांग्लादेश के साथ सबसे लंबी अंतरराष्ट्रीय सीमा (4,096.7 किमी) साझा करता है।","यह सीमा पश्चिम बंगाल, असम, मेघालय, त्रिपुरा और मिजोरम राज्यों को छूती है।"],"factsEn":["India shares the longest international border (4,096.7 km) with Bangladesh.","This border touches the states of West Bengal, Assam, Meghalaya, Tripura, and Mizoram."],"mnemonics":["B-C-P-N-M-B-A (बचपन में बीए) - Bangladesh, China, Pakistan, Nepal, Myanmar, Bhutan, Afghanistan"],"related":["सबसे छोटी सीमा (अफगानिस्तान - 106 किमी) / Shortest border (Afghanistan - 106 km)"],"memoryTip":"''बचपन'' ट्रिक का ''ब'' सबसे पहले आता है, इसलिए बांग्लादेश (Bangladesh) की सीमा सबसे लंबी है। (Visit mppsc.zenscroll.app for more tricks)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('_jVdxk9x4pA6aETVoZypJ', 'RB70XH6legjyFDNu7WEFc', 'कर्क रेखा (Tropic of Cancer) भारत के कितने राज्यों से होकर गुजरती है?', '"[\"1) 6\",\"2) 7\",\"3) 8\",\"4) 9\"]"', '3', NULL, 1, 0, 3, 'General', 'The Tropic of Cancer passes through how many states in India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कर्क रेखा (23.5° उत्तरी अक्षांश) भारत के 8 राज्यों से होकर गुजरती है।","ये राज्य हैं: गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा और मिजोरम।"],"factsEn":["The Tropic of Cancer (23.5° N latitude) passes through 8 states in India.","These states are: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram."],"mnemonics":["मित्र पर गमछा झार (Mi-Mizoram, Tr-Tripura, P-Paschim Bengal, R-Rajasthan, G-Gujarat, M-MP, Chha-Chhattisgarh, Jhar-Jharkhand)"],"related":["मध्य प्रदेश में कर्क रेखा 14 जिलों से गुजरती है / Tropic of Cancer passes through 14 districts in MP"],"memoryTip":"कर्क रेखा भारत को ''8'' (Eight) राज्यों के माध्यम से दो बराबर भागों में काटती है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dOGWuITdq2rjCSO_HypHd', 'RB70XH6legjyFDNu7WEFc', 'भारत की सबसे पुरानी पर्वत श्रृंखला कौन सी है?', '"[\"1) हिमालय / Himalayas\",\"2) अरावली / Aravalli\",\"3) पश्चिमी घाट / Western Ghats\",\"4) विंध्य / Vindhya\"]"', '2', NULL, 1, 0, 4, 'General', 'Which is the oldest mountain range in India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["अरावली पर्वत श्रृंखला भारत की सबसे पुरानी मोड़दार (Folded) पर्वत श्रृंखला है।","यह मुख्य रूप से राजस्थान में फैली हुई है और इसकी सबसे ऊँची चोटी गुरु शिखर (माउंट आबू) है।"],"factsEn":["The Aravalli range is the oldest fold mountain system in India.","It is primarily spread across Rajasthan, and its highest peak is Guru Shikhar (Mount Abu)."],"mnemonics":["Oldest = Ara (A for Ancient)"],"related":["नवीनतम पर्वत (हिमालय) / Youngest mountain (Himalayas)"],"memoryTip":"भारत के भूगोल में ''अरावली'' उतनी ही पुरानी है जितना कि ''Ancient'' इतिहास। (Practice on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('wM8dMeSyd7Qhf0CDigy_T', 'RB70XH6legjyFDNu7WEFc', 'भारत की सबसे बड़ी खारे पानी की झील ''चिल्का झील'' किस राज्य में स्थित है?', '"[\"1) पश्चिम बंगाल / West Bengal\",\"2) आंध्र प्रदेश / Andhra Pradesh\",\"3) ओडिशा / Odisha\",\"4) तमिलनाडु / Tamil Nadu\"]"', '3', NULL, 1, 0, 5, 'General', 'India''s largest brackish water lake ''Chilika Lake'' is located in which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["चिल्का झील ओडिशा में स्थित है और यह भारत की सबसे बड़ी तटीय लैगून (Lagoon) झील है।","यह सर्दियों के दौरान प्रवासी पक्षियों के लिए एक प्रमुख शीतकालीन आश्रय स्थल है।"],"factsEn":["Chilika Lake is located in Odisha and is India''s largest coastal lagoon.","It is a major wintering ground for migratory birds during the winter season."],"mnemonics":["Chilika - Odisha (C-O)"],"related":["सबसे बड़ी मीठे पानी की झील (वुलर झील, जम्मू और कश्मीर) / Largest freshwater lake (Wular Lake, J&K)","पुलिकट झील (आंध्र प्रदेश और तमिलनाडु) / Pulicat Lake (Andhra Pradesh and Tamil Nadu)"],"memoryTip":"ओडिशा के तट पर एक ''चील'' (Chilika) उड़ रही है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sDzhDT8yK336h6WJx6ihe', 'RB70XH6legjyFDNu7WEFc', 'विश्व का सबसे बड़ा नदी द्वीप ''माजुली'' किस नदी पर स्थित है?', '"[\"1) गंगा / Ganga\",\"2) ब्रह्मपुत्र / Brahmaputra\",\"3) गोदावरी / Godavari\",\"4) सिंधु / Indus\"]"', '2', NULL, 1, 0, 6, 'General', 'On which river is ''Majuli'', the world''s largest river island, situated?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["माजुली द्वीप असम राज्य में ब्रह्मपुत्र नदी के मध्य में स्थित है।","2016 में, माजुली भारत का पहला ऐसा द्वीप बन गया जिसे एक जिले (District) का दर्जा दिया गया।"],"factsEn":["Majuli island is situated in the middle of the Brahmaputra River in the state of Assam.","In 2016, Majuli became the first island in India to be made a district."],"mnemonics":["M-B-A: Majuli -> Brahmaputra -> Assam"],"related":["उमानंद द्वीप (ब्रह्मपुत्र नदी पर सबसे छोटा बसा हुआ नदी द्वीप) / Umananda Island (Smallest inhabited river island on Brahmaputra)"],"memoryTip":"ब्रह्मा (Brahmaputra) जी ने एक बहुत बड़ी ''मंजिल'' (Majuli) बनाई।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9Gy_qvKwZsNsDHbzuULj5', 'RB70XH6legjyFDNu7WEFc', 'भारत का मानक समय (IST) किस देशांतर रेखा के आधार पर तय किया जाता है?', '"[\"1) 82.5° पूर्वी / 82.5° East\",\"2) 80.5° पूर्वी / 80.5° East\",\"3) 85.5° पूर्वी / 85.5° East\",\"4) 88.5° पूर्वी / 88.5° East\"]"', '1', NULL, 1, 0, 7, 'General', 'The Indian Standard Time (IST) is based on which longitude?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भारतीय मानक समय (IST) 82.5° पूर्वी देशांतर (Longitude) पर आधारित है।","यह रेखा उत्तर प्रदेश के मिर्जापुर (प्रयागराज के पास नैनी) से होकर गुजरती है और ग्रीनविच मीन टाइम (GMT) से 5 घंटे 30 मिनट आगे है।"],"factsEn":["Indian Standard Time (IST) is based on the 82.5° East longitude.","This line passes through Mirzapur (near Naini, Prayagraj) in Uttar Pradesh and is 5 hours 30 minutes ahead of Greenwich Mean Time (GMT)."],"mnemonics":["82.5 E = IST"],"related":["IST 5 राज्यों से गुजरती है: यूपी, एमपी, छत्तीसगढ़, ओडिशा, एपी / IST passes through 5 states: UP, MP, Chhattisgarh, Odisha, AP"],"memoryTip":"भारत का समय दुनिया से 5.5 घंटे आगे है, जो 82.5 डिग्री से मापा जाता है। (Check mock scores at mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('MDR7Fqw858n9ZhLQn_KJi', 'RB70XH6legjyFDNu7WEFc', 'भारत का एकमात्र सक्रिय ज्वालामुखी कहाँ स्थित है?', '"[\"1) लक्षद्वीप / Lakshadweep\",\"2) बैरन द्वीप (अंडमान) / Barren Island (Andaman)\",\"3) मिनिकॉय / Minicoy\",\"4) पंबन द्वीप / Pamban Island\"]"', '2', NULL, 1, 0, 8, 'General', 'Where is India''s only active volcano located?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भारत और दक्षिण एशिया का एकमात्र पुष्ट सक्रिय ज्वालामुखी बैरन द्वीप पर स्थित है।","यह अंडमान सागर में, पोर्ट ब्लेयर से लगभग 138 किमी उत्तर-पूर्व में स्थित है।"],"factsEn":["The only confirmed active volcano in India and South Asia is located on Barren Island.","It is situated in the Andaman Sea, about 138 km northeast of Port Blair."],"mnemonics":["Barren is Active"],"related":["नारकोंडम द्वीप (अंडमान में एक प्रसुप्त ज्वालामुखी) / Narcondam Island (A dormant volcano in Andaman)"],"memoryTip":"द्वीप भले ही ''बैरन'' (बंजर) हो, लेकिन ज्वालामुखी अभी भी ''एक्टिव'' है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3L1o3bmA78qlhHg8nr0rv', 'RB70XH6legjyFDNu7WEFc', 'प्रायद्वीपीय भारत (दक्षिण भारत) की सबसे लंबी नदी कौन सी है?', '"[\"1) कृष्णा / Krishna\",\"2) कावेरी / Cauvery\",\"3) गोदावरी / Godavari\",\"4) नर्मदा / Narmada\"]"', '3', NULL, 1, 0, 9, 'General', 'Which is the longest river of Peninsular India (South India)?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["गोदावरी प्रायद्वीपीय भारत की सबसे लंबी नदी (1,465 किमी) है।","इसकी लंबाई और विस्तार के कारण इसे ''दक्षिण गंगा'' या ''वृद्ध गंगा'' भी कहा जाता है। यह महाराष्ट्र के त्र्यंबकेश्वर से निकलती है।"],"factsEn":["Godavari is the longest river (1,465 km) of Peninsular India.","Due to its length and coverage area, it is also known as ''Dakshin Ganga'' or ''Vriddh Ganga''. It originates from Trimbakeshwar, Maharashtra."],"mnemonics":["God of South Rivers = Godavari"],"related":["कृष्णा नदी (दूसरी सबसे लंबी प्रायद्वीपीय नदी) / Krishna River (Second longest peninsular river)"],"memoryTip":"दक्षिण में सबसे लंबी नदी का नाम भगवान (God - Godavari) से शुरू होता है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('NDJ0w9PLZWPC5N9dpKmMZ', 'RB70XH6legjyFDNu7WEFc', 'मध्य प्रदेश में वर्तमान में कुल कितने रामसर स्थल (Ramsar Sites) हैं, जिनमें हाल ही में तवा जलाशय (Tawa Reservoir) को शामिल किया गया है?', '"[\"1) 3\",\"2) 4\",\"3) 5\",\"4) 6\"]"', '3', NULL, 1, 0, 10, 'General', 'How many Ramsar sites are currently there in Madhya Pradesh, including the recently added Tawa Reservoir?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["तवा जलाशय (नर्मदापुरम) को जोड़ने के साथ, मध्य प्रदेश में अब कुल 5 रामसर स्थल (Ramsar Sites) हो गए हैं।","अन्य चार हैं: भोज वेटलैंड (भोपाल), साख्य सागर (शिवपुरी), सिरपुर वेटलैंड और यशवंत सागर (दोनों इंदौर)।"],"factsEn":["With the addition of Tawa Reservoir (Narmadapuram), Madhya Pradesh now has a total of 5 Ramsar sites.","The other four are: Bhoj Wetland (Bhopal), Sakhya Sagar (Shivpuri), Sirpur Wetland, and Yashwant Sagar (both Indore)."],"mnemonics":["B-S-S-Y-T (Bhoj, Sakhya, Sirpur, Yashwant, Tawa) - 5 Sites"],"related":["भारत में सर्वाधिक रामसर स्थल तमिलनाडु में हैं / Maximum Ramsar sites in India are in Tamil Nadu"],"memoryTip":"तवा (Tawa) पर 5 रोटियां सेंकी। मध्य प्रदेश में अब 5 रामसर स्थल हैं। (Update your notes on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('EWjQQgnB4szD4Xn8JLOoB', 'xHIGYAK6Qw02dsmqnoIpd', 'भारत में ''योजना आयोग'' (Planning Commission) को प्रतिस्थापित कर किस नई संस्था का गठन किया गया है?', '"[\"1) नीति आयोग / NITI Aayog\",\"2) राष्ट्रीय विकास परिषद / NDC\",\"3) वित्त आयोग / Finance Commission\",\"4) चुनाव आयोग / Election Commission\"]"', '1', NULL, 1, 0, 1, 'General', 'Which new institution has been formed replacing the ''Planning Commission'' in India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["1 जनवरी 2015 को नीति आयोग (National Institution for Transforming India) की स्थापना की गई।","इसके अध्यक्ष पदेन रूप से भारत के प्रधानमंत्री होते हैं।"],"factsEn":["NITI Aayog (National Institution for Transforming India) was established on January 1, 2015.","The Prime Minister of India is its ex-officio chairman."],"mnemonics":["NITI = National Institution for Transforming India"],"related":["योजना आयोग की स्थापना (15 मार्च 1950) / Establishment of Planning Commission (15 March 1950)"],"memoryTip":"योजना पुरानी हुई, अब देश चलाने के लिए नई ''नीति'' (NITI) लानी है। (Check MP Police tests on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d0D_bBC6_oW2_l74cbuIx', 'xHIGYAK6Qw02dsmqnoIpd', 'भारत में वस्तु एवं सेवा कर (GST) किस तिथि को लागू किया गया था?', '"[\"1) 1 अप्रैल 2017 / 1 April 2017\",\"2) 1 जुलाई 2017 / 1 July 2017\",\"3) 8 नवंबर 2016 / 8 November 2016\",\"4) 1 जनवरी 2018 / 1 January 2018\"]"', '2', NULL, 1, 0, 2, 'General', 'On which date was the Goods and Services Tax (GST) implemented in India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["GST एक अप्रत्यक्ष कर (Indirect Tax) है जिसने भारत में कई अन्य अप्रत्यक्ष करों की जगह ली।","यह 101वें संविधान संशोधन अधिनियम द्वारा 1 जुलाई 2017 की मध्यरात्रि से लागू किया गया था।"],"factsEn":["GST is an Indirect Tax which replaced many other indirect taxes in India.","It was implemented from the midnight of 1 July 2017 by the 101st Constitutional Amendment Act."],"mnemonics":["July 1 - GST (One Nation, One Tax)"],"related":["GST परिषद के अध्यक्ष (केंद्रीय वित्त मंत्री) / Chairman of GST Council (Union Finance Minister)"],"memoryTip":"''जुलाई'' में ''जीएसटी'' लाई (1 July 2017)।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('-_sP69rEdf5AnxnE_x9ek', 'xHIGYAK6Qw02dsmqnoIpd', 'भारतीय कृषि क्षेत्र में मुख्य रूप से किस प्रकार की बेरोजगारी पाई जाती है?', '"[\"1) चक्रीय बेरोजगारी / Cyclical Unemployment\",\"2) घर्षण बेरोजगारी / Frictional Unemployment\",\"3) प्रच्छन्न (छिपी हुई) बेरोजगारी / Disguised Unemployment\",\"4) संरचनात्मक बेरोजगारी / Structural Unemployment\"]"', '3', NULL, 1, 0, 3, 'General', 'Which type of unemployment is primarily found in the Indian agriculture sector?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["प्रच्छन्न बेरोजगारी वह स्थिति है जहाँ आवश्यकता से अधिक लोग एक ही काम में लगे होते हैं।","कृषि क्षेत्र में यह एक आम आर्थिक समस्या है जहाँ पूरा परिवार खेत में काम करता है, भले ही उनके बिना भी उत्पादन उतना ही हो।"],"factsEn":["Disguised unemployment is a situation where more people are engaged in a job than required.","It is a common economic issue in the agricultural sector where the whole family works on the farm, even if production remains the same without them."],"mnemonics":["Agri-Disguise (छिपे हुए किसान)"],"related":["मौसमी बेरोजगारी (यह भी कृषि में आम है) / Seasonal Unemployment (Also common in agriculture)"],"memoryTip":"खेत में 2 का काम है, लेकिन 4 कर रहे हैं - यह ''छिपी हुई'' (Disguised) बेरोजगारी है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('e4UOxMzttu5vlqrnirQ_f', 'xHIGYAK6Qw02dsmqnoIpd', 'भारत में मौद्रिक नीति (Monetary Policy) किसके द्वारा तैयार और लागू की जाती है?', '"[\"1) वित्त मंत्रालय / Ministry of Finance\",\"2) भारतीय रिजर्व बैंक (RBI) / Reserve Bank of India\",\"3) नीति आयोग / NITI Aayog\",\"4) भारतीय प्रतिभूति और विनिमय बोर्ड (SEBI) / SEBI\"]"', '2', NULL, 1, 0, 4, 'General', 'By whom is the Monetary Policy formulated and implemented in India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["RBI भारत का केंद्रीय बैंक है जो मुद्रास्फीति को नियंत्रित करने और आर्थिक विकास को गति देने के लिए मौद्रिक नीति बनाता है।","इसमें रेपो रेट (Repo Rate), रिवर्स रेपो रेट और सीआरआर (CRR) जैसे महत्वपूर्ण उपकरण शामिल हैं।"],"factsEn":["RBI is India''s central bank that formulates monetary policy to control inflation and boost economic growth.","It includes important tools like Repo Rate, Reverse Repo Rate, and CRR."],"mnemonics":["M-P: Monetary = RBI, Fiscal = Finance Ministry"],"related":["राजकोषीय नीति (वित्त मंत्रालय द्वारा तैयार) / Fiscal Policy (Formulated by Ministry of Finance)"],"memoryTip":"''मुद्रा'' (Money) का रिज़र्व ''RBI'' के पास है, तो नीति भी वही बनाएगा। (Master economics on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('jFb6oAtpdCPWS0cMshqtZ', 'xHIGYAK6Qw02dsmqnoIpd', 'भारत की प्रथम पंचवर्षीय योजना (First Five Year Plan) का मुख्य फोकस किस क्षेत्र पर था?', '"[\"1) भारी उद्योग / Heavy Industries\",\"2) कृषि विकास / Agricultural Development\",\"3) सेवा क्षेत्र / Service Sector\",\"4) विदेशी व्यापार / Foreign Trade\"]"', '2', NULL, 1, 0, 5, 'General', 'What was the main focus of India''s First Five Year Plan?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पहली पंचवर्षीय योजना (1951-1956) हेरोड-डोमर (Harrod-Domar) मॉडल पर आधारित थी।","इसका प्राथमिक लक्ष्य भारत के कृषि क्षेत्र, सिंचाई और ऊर्जा परियोजनाओं का विकास करना था।"],"factsEn":["The First Five Year Plan (1951-1956) was based on the Harrod-Domar model.","Its primary goal was the development of India''s agricultural sector, irrigation, and power projects."],"mnemonics":["1-Agri, 2-Ind (पहली कृषि, दूसरी उद्योग)"],"related":["दूसरी पंचवर्षीय योजना का फोकस (भारी उद्योग - पीसी महालनोबिस मॉडल) / Focus of Second Five Year Plan (Heavy Industries - PC Mahalanobis Model)"],"memoryTip":"स्वतंत्रता के बाद सबसे पहले पेट भरने (कृषि) की व्यवस्था की गई।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('IHyYDgiorVRtG4-hABRLA', 'xHIGYAK6Qw02dsmqnoIpd', 'भारत में गरीबी रेखा (Poverty Line) के निर्धारण के लिए किस प्रसिद्ध समिति का गठन किया गया था?', '"[\"1) सुरेश तेंदुलकर समिति / Suresh Tendulkar Committee\",\"2) केलकर समिति / Kelkar Committee\",\"3) नरसिम्हम समिति / Narasimham Committee\",\"4) बलवंत राय मेहता समिति / Balwant Rai Mehta Committee\"]"', '1', NULL, 1, 0, 6, 'General', 'Which famous committee was formed to determine the poverty line in India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["सुरेश तेंदुलकर समिति (2009) ने भारत में गरीबी मापने की कार्यप्रणाली की समीक्षा की और खपत व्यय (consumption expenditure) पर आधारित एक नया तरीका सुझाया।","सी. रंगराजन समिति (2014) भी गरीबी रेखा के आकलन से जुड़ी एक अन्य महत्वपूर्ण समिति है।"],"factsEn":["The Suresh Tendulkar Committee (2009) reviewed the methodology for poverty estimation in India and suggested a new method based on consumption expenditure.","The C. Rangarajan Committee (2014) is another important committee related to poverty line estimation."],"mnemonics":["T-P: Tendulkar -> Poverty"],"related":["नरसिम्हम समिति (बैंकिंग सुधार) / Narasimham Committee (Banking Reforms)"],"memoryTip":"''तेंदुलकर'' ने गरीबी के आंकड़े (Poverty line) तय किए।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('VWnh8Yil6lbtftzPbwdTf', 'xHIGYAK6Qw02dsmqnoIpd', 'विनिर्माण क्षेत्र को बढ़ावा देने के लिए ''मेक इन इंडिया'' (Make in India) पहल किस वर्ष शुरू की गई थी?', '"[\"1) 2012\",\"2) 2014\",\"3) 2016\",\"4) 2018\"]"', '2', NULL, 1, 0, 7, 'General', 'In which year was the ''Make in India'' initiative launched to boost the manufacturing sector?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["मेक इन इंडिया कार्यक्रम 25 सितंबर 2014 को भारत सरकार द्वारा शुरू किया गया था।","इसका उद्देश्य भारत को एक वैश्विक डिजाइन और विनिर्माण केंद्र (Global Manufacturing Hub) बनाना और FDI को आकर्षित करना है।"],"factsEn":["The Make in India program was launched by the Government of India on September 25, 2014.","Its objective is to make India a global design and manufacturing hub and attract FDI."],"mnemonics":["MII-2014"],"related":["स्टार्टअप इंडिया (2016) / Startup India (2016)"],"memoryTip":"2014 में नई सरकार बनी और ''मेक इन इंडिया'' का नारा दिया। (Revise schemes on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sLWj6qbSOY74Fjuna0wz8', 'xHIGYAK6Qw02dsmqnoIpd', 'भारत में ''हरित क्रांति'' (Green Revolution) का जनक किसे माना जाता है?', '"[\"1) वर्गीज कुरियन / Verghese Kurien\",\"2) एम.एस. स्वामीनाथन / M.S. Swaminathan\",\"3) नॉर्मन बोरलॉग / Norman Borlaug\",\"4) सी. सुब्रमण्यम / C. Subramaniam\"]"', '2', NULL, 1, 0, 8, 'General', 'Who is considered the father of the Green Revolution in India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["डॉ. एम.एस. स्वामीनाथन ने 1960 के दशक में भारत में उच्च उपज वाले गेहूं और चावल के बीजों को पेश करने में महत्वपूर्ण भूमिका निभाई थी।","नॉर्मन बोरलॉग को विश्व स्तर पर हरित क्रांति का जनक माना जाता है।"],"factsEn":["Dr. M.S. Swaminathan played a key role in introducing high-yielding varieties of wheat and rice seeds in India in the 1960s.","Norman Borlaug is considered the father of the Green Revolution globally."],"mnemonics":["Green Swami"],"related":["वर्गीज कुरियन (भारत में श्वेत क्रांति/दुग्ध उत्पादन के जनक) / Verghese Kurien (Father of White Revolution/Milk production in India)"],"memoryTip":"''हरित'' (Green) खेतों का ''स्वामी'' - स्वामीनाथन।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ofhNWoS3F0hmKB9nTDBkX', 'xHIGYAK6Qw02dsmqnoIpd', 'आर्थिक शब्दावली में ''SEZ'' का पूर्ण रूप क्या है?', '"[\"1) स्पेशल इकोनॉमिक ज़ोन / Special Economic Zone\",\"2) स्टेट इकोनॉमिक ज़ोन / State Economic Zone\",\"3) सोशल एम्प्लॉयमेंट ज़ोन / Social Employment Zone\",\"4) सस्टेनेबल एनवायरनमेंट ज़ोन / Sustainable Environment Zone\"]"', '1', NULL, 1, 0, 9, 'General', 'What is the full form of ''SEZ'' in economic terminology?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["SEZ (विशेष आर्थिक क्षेत्र) एक ऐसा क्षेत्र है जहाँ व्यापार और वाणिज्यिक कानून देश के बाकी हिस्सों से अलग (अधिक उदार) होते हैं।","इसका मुख्य उद्देश्य विदेशी निवेश (FDI), निर्यात और रोजगार को बढ़ाना है। भारत में SEZ अधिनियम 2005 में पारित किया गया था।"],"factsEn":["SEZ (Special Economic Zone) is an area in which business and trade laws are different (more liberal) from the rest of the country.","Its main objective is to increase foreign investment (FDI), exports, and employment. The SEZ Act was passed in India in 2005."],"mnemonics":["SEZ = Special Zone for Economy"],"related":["EEZ (विशिष्ट आर्थिक क्षेत्र - समुद्री सीमा) / EEZ (Exclusive Economic Zone - Maritime boundary)"],"memoryTip":"व्यापार बढ़ाने के लिए कुछ इलाकों को ''Special'' दर्जा दिया जाता है (SEZ)।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('rDxCB8JRNJ4YVInPXHvSu', 'xHIGYAK6Qw02dsmqnoIpd', 'भारत सरकार का वित्तीय वर्ष (Financial Year) कब से कब तक होता है?', '"[\"1) 1 जनवरी से 31 दिसंबर / 1 January to 31 December\",\"2) 1 अप्रैल से 31 मार्च / 1 April to 31 March\",\"3) 1 जुलाई से 30 जून / 1 July to 30 June\",\"4) 1 अक्टूबर से 30 सितंबर / 1 October to 30 September\"]"', '2', NULL, 1, 0, 10, 'General', 'From when to when is the Financial Year of the Government of India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भारत में लेखांकन और बजट उद्देश्यों के लिए वित्तीय वर्ष 1 अप्रैल से शुरू होकर अगले वर्ष 31 मार्च तक चलता है।","हाल ही में, आरबीआई (RBI) का लेखा वर्ष (जो पहले जुलाई-जून था) भी अब सरकार के वित्तीय वर्ष (1 अप्रैल - 31 मार्च) के साथ संरेखित कर दिया गया है।"],"factsEn":["In India, the financial year for accounting and budget purposes runs from April 1 to March 31 of the following year.","Recently, the accounting year of RBI (which was earlier July-June) has also been aligned with the government''s financial year (April 1 - March 31)."],"mnemonics":["A to M (April to March)"],"related":["कृषि वर्ष (1 जुलाई से 30 जून) / Agricultural Year (1 July to 30 June)"],"memoryTip":"वित्तीय वर्ष की शुरुआत ''अप्रैल फूल'' (1 April) के दिन से होती है। (Track your progress at mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2DTUBf94JoeooJXU47Enk', 'Os3_RIp6jVzgPAlRzPhhg', 'भारत की सबसे बड़ी जनजाति कौन-सी मानी जाती है? / Which is considered the largest tribe of India?', '"[\"1) भील / Bhil\",\"2) गोंड / Gond\",\"3) संथाल / Santhal\",\"4) मुंडा / Munda\"]"', '1', NULL, 1, 0, 1, 'General', 'Which is considered the largest tribe of India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भील जनजाति भारत की सबसे बड़ी जनजातियों में मानी जाती है।","यह मुख्यतः मध्य प्रदेश, राजस्थान, गुजरात व महाराष्ट्र में पाई जाती है।"],"factsEn":["Bhil is considered the largest tribal community of India.","It is mainly found in Madhya Pradesh, Rajasthan, Gujarat and Maharashtra."],"mnemonics":["बड़ा भील = सबसे बड़ी जनजाति।"],"related":["मध्य प्रदेश","राजस्थान"],"memoryTip":"Largest tribe याद रखना हो तो Bhil चुनें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sfb585S2lLHvkHkOkoKQ7', 'Os3_RIp6jVzgPAlRzPhhg', 'गोंड जनजाति मुख्य रूप से किस क्षेत्र में निवास करती है? / Gond tribe mainly resides in which region?', '"[\"1) मध्य भारत / Central India\",\"2) उत्तर भारत / North India\",\"3) तटीय भारत / Coastal India\",\"4) द्वीपीय भारत / Island India\"]"', '1', NULL, 1, 0, 2, 'General', 'Gond tribe mainly resides in which region?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["गोंड जनजाति मध्य भारत की प्रमुख जनजाति है।","यह मध्य प्रदेश, छत्तीसगढ़, महाराष्ट्र आदि राज्यों में पाई जाती है।"],"factsEn":["Gond is a major tribe of Central India.","It is found in Madhya Pradesh, Chhattisgarh, Maharashtra etc."],"mnemonics":["गोंड = केंद्र = मध्य भारत।"],"related":["गोंडवाना क्षेत्र","मध्य प्रदेश"],"memoryTip":"Gond tribe आते ही Central India सोचें।"}}', 'mppolice');
