INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1InW1ngAbwD2yVd88PXAS', 'Os3_RIp6jVzgPAlRzPhhg', 'मध्य प्रदेश की प्रमुख जनजाति कौन-सी है? / Which is a major tribe of Madhya Pradesh?', '"[\"1) गोंड / Gond\",\"2) टोडा / Toda\",\"3) जारवा / Jarawa\",\"4) ओंगे / Onge\"]"', '1', NULL, 1, 0, 7, 'General', 'Which is a major tribe of Madhya Pradesh?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["मध्य प्रदेश में गोंड, भील, बैगा, कोरकू प्रमुख जनजातियाँ हैं।","गोंड जनजाति राज्य में अत्यंत महत्वपूर्ण है।"],"factsEn":["Gond, Bhil, Baiga and Korku are major tribes of Madhya Pradesh.","Gond is highly significant in the state."],"mnemonics":["MP = Major tribe Gond."],"related":["बैगा","कोरकू"],"memoryTip":"MP related tribe question में Gond याद रखें।"}}', 'mppolice');
