INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0DVj8t1SEXgJDg8mJBV8Y', 'Os3_RIp6jVzgPAlRzPhhg', 'बैगा जनजाति मुख्यतः किस राज्य में पाई जाती है? / Baiga tribe is mainly found in which state?', '"[\"1) मध्य प्रदेश / Madhya Pradesh\",\"2) केरल / Kerala\",\"3) पंजाब / Punjab\",\"4) गुजरात / Gujarat\"]"', '1', NULL, 1, 0, 9, 'General', 'Baiga tribe is mainly found in which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["बैगा जनजाति मध्य प्रदेश और छत्तीसगढ़ में पाई जाती है।","यह विशेष रूप से वन क्षेत्रों में निवास करती है।"],"factsEn":["Baiga tribe is found in Madhya Pradesh and Chhattisgarh.","It mainly lives in forest areas."],"mnemonics":["बैगा = बघेलखंड-वन = MP."],"related":["विशेष पिछड़ी जनजाति","वनवासी समुदाय"],"memoryTip":"Baiga = Madhya Pradesh."}}', 'mppolice');
