INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('vdD921qD-2DvxhqGDjg0-', '3HbTJ9bjzY6ghM9y259PB', 'कुंभ मेला भारत के कितने स्थानों पर आयोजित किया जाता है?', '"[\"1) दो / Two\",\"2) तीन / Three\",\"3) चार / Four\",\"4) पांच / Five\"]"', '3', NULL, 1, 0, 1, 'General', 'In how many places in India is the Kumbh Mela held?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कुंभ मेला हिंदू धर्म का एक प्रमुख तीर्थोत्सव है, जो भारत में 4 स्थानों पर आयोजित किया जाता है।","ये स्थान हैं: हरिद्वार (गंगा नदी), प्रयागराज (गंगा, यमुना और सरस्वती का संगम), नासिक (गोदावरी) और उज्जैन (क्षिप्रा)।"],"factsEn":["Kumbh Mela is a major pilgrimage festival in Hinduism, held at 4 locations in India.","These locations are: Haridwar (Ganges river), Prayagraj (confluence of Ganges, Yamuna, and Saraswati), Nashik (Godavari), and Ujjain (Kshipra)."],"mnemonics":["H-P-N-U (हरि प्रयाग में नहाकर उज्जैन गया)"],"related":["महाकुंभ (हर 12 वर्ष में प्रयागराज में आयोजित होता है) / Maha Kumbh (Held every 12 years in Prayagraj)"],"memoryTip":"भारत की 4 पवित्र नदियों के किनारे 4 कुंभ मेले लगते हैं। (Find more MP GK on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Zw6zowFjJL9n585A0gB1V', '3HbTJ9bjzY6ghM9y259PB', 'प्रसिद्ध लोक चित्रकला ''मधुबनी'' किस राज्य से संबंधित है?', '"[\"1) मध्य प्रदेश / Madhya Pradesh\",\"2) बिहार / Bihar\",\"3) राजस्थान / Rajasthan\",\"4) महाराष्ट्र / Maharashtra\"]"', '2', NULL, 1, 0, 2, 'General', 'The famous folk painting ''Madhubani'' is associated with which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["मधुबनी चित्रकला (जिसे मिथिला कला भी कहा जाता है) बिहार के मिथिला क्षेत्र की एक पारंपरिक कला है।","इसमें प्राकृतिक रंगों का उपयोग किया जाता है और यह कला मुख्य रूप से महिलाओं द्वारा दीवारों और आंगनों पर बनाई जाती है।"],"factsEn":["Madhubani painting (also known as Mithila art) is a traditional art form from the Mithila region of Bihar.","It uses natural colors and is primarily created by women on walls and courtyards."],"mnemonics":["M-B: Madhubani -> Bihar"],"related":["पट्टचित्र (ओडिशा) / Pattachitra (Odisha)","गोंड चित्रकला (मध्य प्रदेश) / Gond Painting (Madhya Pradesh)"],"memoryTip":"''मधु'' (शहद) की तरह मीठी कला ''बिहार'' से आती है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('vlLM0ltMVjsV4igSmicaK', '3HbTJ9bjzY6ghM9y259PB', 'भारत के किस उत्तर-पूर्वी राज्य में ''हॉर्नबिल महोत्सव'' मनाया जाता है?', '"[\"1) नागालैंड / Nagaland\",\"2) मणिपुर / Manipur\",\"3) असम / Assam\",\"4) मिजोरम / Mizoram\"]"', '1', NULL, 1, 0, 3, 'General', 'In which North-Eastern state of India is the ''Hornbill Festival'' celebrated?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["हॉर्नबिल महोत्सव नागालैंड का सबसे बड़ा सांस्कृतिक उत्सव है, जिसे ''त्योहारों का त्योहार'' (Festival of Festivals) भी कहा जाता है।","यह हर साल 1 से 10 दिसंबर तक नागा विरासत गांव ''किसामा'' में मनाया जाता है।"],"factsEn":["The Hornbill Festival is Nagaland''s largest cultural festival, also known as the ''Festival of Festivals''.","It is celebrated every year from December 1 to 10 at the Naga Heritage Village ''Kisama''."],"mnemonics":["Horn-Naga: नागा (सांप) को हॉर्न बजाकर भगाओ।"],"related":["चापचर कुट (मिजोरम) / Chapchar Kut (Mizoram)","वांगला महोत्सव (मेघालय) / Wangala Festival (Meghalaya)"],"memoryTip":"नागालैंड की जनजातियां हॉर्नबिल पक्षी का बहुत सम्मान करती हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('z9-4THCt7_Rj1Smf0kuMR', '3HbTJ9bjzY6ghM9y259PB', 'भारत सरकार द्वारा किस भाषा को पहली ''शास्त्रीय भाषा'' (Classical Language) का दर्जा दिया गया था?', '"[\"1) संस्कृत / Sanskrit\",\"2) तमिल / Tamil\",\"3) तेलुगु / Telugu\",\"4) कन्नड़ / Kannada\"]"', '2', NULL, 1, 0, 4, 'General', 'Which language was given the status of the first ''Classical Language'' by the Government of India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["तमिल को वर्ष 2004 में भारत की पहली शास्त्रीय भाषा घोषित किया गया था।","इसके बाद 2005 में संस्कृत को शास्त्रीय भाषा का दर्जा मिला। वर्तमान में 6 भाषाओं को यह दर्जा प्राप्त है।"],"factsEn":["Tamil was declared as the first classical language of India in the year 2004.","It was followed by Sanskrit in 2005. Currently, 6 languages hold this status."],"mnemonics":["T-S-T-K-M-O (Tamil, Sanskrit, Telugu, Kannada, Malayalam, Odia)"],"related":["सबसे नवीनतम शास्त्रीय भाषा (ओडिया - 2014) / Newest Classical Language (Odia - 2014)"],"memoryTip":"दक्षिण की ''तमिल'' ने सबसे पहले शास्त्रीय (Classical) होने का सम्मान पाया। (Practice detailed PYQs on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('BcIVIQeHRFl7kaoQpiuVC', '3HbTJ9bjzY6ghM9y259PB', '''कलारीपयट्टू'' (Kalaripayattu) किस भारतीय राज्य की एक प्रसिद्ध मार्शल आर्ट है?', '"[\"1) केरल / Kerala\",\"2) तमिलनाडु / Tamil Nadu\",\"3) पंजाब / Punjab\",\"4) मणिपुर / Manipur\"]"', '1', NULL, 1, 0, 5, 'General', '''Kalaripayattu'' is a famous martial art of which Indian state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कलारीपयट्टू भारत के केरल राज्य की एक प्राचीन मार्शल आर्ट है। इसे दुनिया के सबसे पुराने युद्ध कौशल में से एक माना जाता है।","''कलारी'' का अर्थ है युद्ध का मैदान और ''पयट्टू'' का अर्थ है अभ्यास।"],"factsEn":["Kalaripayattu is an ancient martial art from the Indian state of Kerala. It is considered one of the oldest fighting systems in the world.","''Kalari'' means battlefield and ''Payattu'' means practice."],"mnemonics":["Kalari-Kerala (K-K)"],"related":["थांग-ता (मणिपुर की मार्शल आर्ट) / Thang-Ta (Martial art of Manipur)","गतका (पंजाब की मार्शल आर्ट) / Gatka (Martial art of Punjab)"],"memoryTip":"केरल के लोग ''कलारी'' में अभ्यास करते हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9WbxLwPm7LRsbQTZY49Tc', '3HbTJ9bjzY6ghM9y259PB', 'पारंपरिक लोक रंगमंच ''यक्षगान'' (Yakshagana) मुख्य रूप से किस राज्य से जुड़ा है?', '"[\"1) कर्नाटक / Karnataka\",\"2) आंध्र प्रदेश / Andhra Pradesh\",\"3) महाराष्ट्र / Maharashtra\",\"4) ओडिशा / Odisha\"]"', '1', NULL, 1, 0, 6, 'General', 'The traditional folk theatre ''Yakshagana'' is primarily associated with which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["यक्षगान कर्नाटक का एक पारंपरिक रंगमंच है जो नृत्य, संगीत, संवाद और विस्तृत वेशभूषा का एक अनूठा मिश्रण है।","यह मुख्य रूप से रामायण, महाभारत और पुराणों की कहानियों पर आधारित होता है।"],"factsEn":["Yakshagana is a traditional theatre of Karnataka that is a unique blend of dance, music, dialogue, and elaborate costumes.","It is primarily based on stories from the Ramayana, Mahabharata, and Puranas."],"mnemonics":["Yaksha-Karna: यक्ष ने कर्ण (नाटक) किया।"],"related":["तमाशा (महाराष्ट्र का लोक रंगमंच) / Tamasha (Folk theatre of Maharashtra)","भवाई (गुजरात) / Bhavai (Gujarat)"],"memoryTip":"कर्नाटक में ''यक्ष'' (Yaksh) अपने ज्ञान (Gana) का नाटक करते हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('WVyZlOTVbwmrhXSh-AhTA', '3HbTJ9bjzY6ghM9y259PB', 'पारंपरिक कढ़ाई शैली ''फुलकारी'' मुख्य रूप से किस राज्य से संबंधित है?', '"[\"1) गुजरात / Gujarat\",\"2) पंजाब / Punjab\",\"3) राजस्थान / Rajasthan\",\"4) हरियाणा / Haryana\"]"', '2', NULL, 1, 0, 7, 'General', 'The traditional embroidery style ''Phulkari'' is mainly associated with which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["फुलकारी (जिसका शाब्दिक अर्थ ''फूलों का काम'' है) पंजाब क्षेत्र की एक पारंपरिक और रंगीन कढ़ाई तकनीक है।","इसे अक्सर महिलाओं द्वारा दुपट्टे या शॉल पर जटिल ज्यामितीय पैटर्न में रेशम के धागों से काढ़ा जाता है।"],"factsEn":["Phulkari (literally meaning ''flower work'') is a traditional and colorful embroidery technique from the Punjab region.","It is often embroidered by women on dupattas or shawls using silk threads in intricate geometric patterns."],"mnemonics":["Phul-Punjab (P-P)"],"related":["चिकनकारी (लखनऊ, उत्तर प्रदेश) / Chikankari (Lucknow, Uttar Pradesh)","कांथा कढ़ाई (पश्चिम बंगाल) / Kantha Embroidery (West Bengal)"],"memoryTip":"पंजाब के लहलहाते खेतों में ''फूल'' (Phul) खिलते हैं। (Learn more culture notes on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('rIroNBGkAbwmdB4yt2KcJ', '3HbTJ9bjzY6ghM9y259PB', '''वारली'' चित्रकला (Warli painting) की उत्पत्ति मुख्य रूप से किस राज्य की जनजातियों द्वारा की गई थी?', '"[\"1) महाराष्ट्र / Maharashtra\",\"2) मध्य प्रदेश / Madhya Pradesh\",\"3) ओडिशा / Odisha\",\"4) छत्तीसगढ़ / Chhattisgarh\"]"', '1', NULL, 1, 0, 8, 'General', 'Warli painting was primarily originated by the tribes of which state?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["वारली चित्रकला महाराष्ट्र की वारली जनजाति द्वारा बनाई जाने वाली एक आदिवासी कला है।","यह कला मुख्य रूप से सफेद रंग (चावल के पेस्ट) का उपयोग करके मिट्टी की लाल/भूरी दीवारों पर ज्यामितीय आकृतियों (वृत्त, त्रिकोण) में बनाई जाती है।"],"factsEn":["Warli painting is a tribal art created by the Warli tribe of Maharashtra.","This art is primarily created on mud walls in red/brown color using geometric shapes (circles, triangles) drawn with white color (rice paste)."],"mnemonics":["Warli-Maha: वारली जनजाति महाराष्ट्र की महान कला है।"],"related":["पिथौरा चित्रकला (गुजरात और मध्य प्रदेश) / Pithora Painting (Gujarat and Madhya Pradesh)"],"memoryTip":"मुंबई (महाराष्ट्र) के पास ''वर्ली'' (Worli/Warli) नाम की जगह भी है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bqDYWJvcHW93y8_Igbs8q', '3HbTJ9bjzY6ghM9y259PB', 'बौद्ध समुदाय द्वारा मनाया जाने वाला नव वर्ष का त्योहार ''लोसर'' (Losar) भारत के किस क्षेत्र में प्रमुखता से मनाया जाता है?', '"[\"1) कच्छ / Kutch\",\"2) बस्तर / Bastar\",\"3) लद्दाख / Ladakh\",\"4) मालवा / Malwa\"]"', '3', NULL, 1, 0, 9, 'General', 'The New Year festival ''Losar'' celebrated by the Buddhist community is prominently celebrated in which region of India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["लोसर तिब्बती बौद्ध धर्म में नए साल का त्योहार है, जो भारत में मुख्य रूप से लद्दाख, सिक्किम और अरुणाचल प्रदेश में मनाया जाता है।","यह त्योहार 15 दिनों तक चलता है और इसमें चाम नृत्य (Cham dance) जैसे पारंपरिक अनुष्ठान शामिल होते हैं।"],"factsEn":["Losar is the New Year festival in Tibetan Buddhism, celebrated primarily in Ladakh, Sikkim, and Arunachal Pradesh in India.","The festival lasts for 15 days and involves traditional rituals like Cham dance."],"mnemonics":["Losar-Ladakh (L-L)"],"related":["हेमिस महोत्सव (लद्दाख का एक अन्य प्रमुख बौद्ध त्योहार) / Hemis Festival (Another major Buddhist festival of Ladakh)"],"memoryTip":"लद्दाख की पहाड़ियों में ''लोसर'' (नए साल) का जश्न मनाया जाता है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('IVyF7MAPLxKzMtz1cazZy', '3HbTJ9bjzY6ghM9y259PB', 'उत्तर भारत के हिंदू मंदिरों की वास्तुकला की मुख्य शैली को क्या कहा जाता है?', '"[\"1) द्रविड़ शैली / Dravida Style\",\"2) नागर शैली / Nagara Style\",\"3) वेसर शैली / Vesara Style\",\"4) कलिंग शैली / Kalinga Style\"]"', '2', NULL, 1, 0, 10, 'General', 'What is the main style of architecture of Hindu temples in North India called?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["नागर शैली उत्तर भारत में मंदिर निर्माण की प्रमुख शैली है। खजुराहो के मंदिर नागर शैली का उत्कृष्ट उदाहरण हैं।","इस शैली की विशेषता ऊंचे शिखरों (टॉवर) और एक वर्गाकार गर्भगृह से होती है।"],"factsEn":["Nagara style is the major style of temple architecture in North India. The Khajuraho temples are excellent examples of the Nagara style.","This style is characterized by tall Shikharas (towers) and a square Garbhagriha (sanctum)."],"mnemonics":["N-N: North -> Nagara"],"related":["द्रविड़ शैली (दक्षिण भारत के मंदिर) / Dravida Style (Temples of South India)","वेसर शैली (नागर और द्रविड़ का मिश्रण) / Vesara Style (Mixture of Nagara and Dravida)"],"memoryTip":"उत्तर भारत के ''नगरों'' (Nagara) में ऊंचे शिखर वाले मंदिर होते हैं। (Test your logic on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('W9LvhG_VELo8Da_nfjafX', 'I--ZFJDWbkGEvUGlFvqk7', '2026 में स्ट्रेट ऑफ होर्मुज वैश्विक चर्चा में क्यों रहा? / Why was the Strait of Hormuz in global discussion in 2026?', '"[\"1) तेल आपूर्ति संकट / Oil supply crisis\",\"2) ओलंपिक आयोजन / Olympic hosting\",\"3) नई मुद्रा जारी / New currency launch\",\"4) अंतरिक्ष केंद्र निर्माण / Space center construction\"]"', '1', NULL, 1, 0, 1, 'General', 'Why was the Strait of Hormuz in global discussion in 2026?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["स्ट्रेट ऑफ होर्मुज विश्व के प्रमुख तेल मार्गों में से एक है।","2026 में पश्चिम एशिया तनाव के कारण यह चर्चा में रहा।"],"factsEn":["The Strait of Hormuz is one of the world''s major oil routes.","It remained in news in 2026 due to West Asia tensions."],"mnemonics":["Hormuz = Oil route."],"related":["ईरान","ऊर्जा सुरक्षा"],"memoryTip":"Hormuz दिखे तो तेल मार्ग याद करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Kg9ixcTavgmJTX4wnM7zV', 'I--ZFJDWbkGEvUGlFvqk7', '2026 में भारत ने ऊर्जा आपूर्ति सुरक्षा हेतु कौन-सा अभियान चलाया? / Which operation did India launch in 2026 for energy supply security?', '"[\"1) ऑपरेशन ऊर्जा सुरक्षा / Operation Urja Suraksha\",\"2) ऑपरेशन शक्ति / Operation Shakti\",\"3) ऑपरेशन समुद्र / Operation Samudra\",\"4) ऑपरेशन कवच / Operation Kavach\"]"', '1', NULL, 1, 0, 2, 'General', 'Which operation did India launch in 2026 for energy supply security?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भारत ने समुद्री मार्गों से ऊर्जा आपूर्ति सुरक्षित रखने हेतु ऑपरेशन ऊर्जा सुरक्षा चलाया।"],"factsEn":["India launched Operation Urja Suraksha to secure energy supply sea routes."],"mnemonics":["ऊर्जा सुरक्षा = Energy security mission."],"related":["भारतीय नौसेना","अरब सागर"],"memoryTip":"Energy issue + India = Urja Suraksha."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4zeKTWhs2eJNyT8x_pbnQ', 'I--ZFJDWbkGEvUGlFvqk7', 'IMF का पूरा नाम क्या है, जो 2026 में वैश्विक अर्थव्यवस्था पर चर्चा में था? / What is the full form of IMF, discussed in 2026 global economy news?', '"[\"1) International Monetary Fund\",\"2) Indian Monetary Forum\",\"3) International Market Force\",\"4) Internal Money Federation\"]"', '1', NULL, 1, 0, 3, 'General', 'What is the full form of IMF, discussed in 2026 global economy news?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["IMF वैश्विक वित्तीय संस्था है।","यह सदस्य देशों को आर्थिक सलाह और सहायता देती है।"],"factsEn":["IMF is a global financial institution.","It provides economic advice and support to member nations."],"mnemonics":["IMF = International Money Fund."],"related":["विश्व बैंक","अर्थव्यवस्था"],"memoryTip":"IMF = Monetary Fund याद रखें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('4TTImAFZj23OPkM1it9fo', 'I--ZFJDWbkGEvUGlFvqk7', '2026 में IMF ने भारत की GDP वृद्धि अनुमान लगभग कितना बताया? / In 2026, IMF projected India''s GDP growth at around what rate?', '"[\"1) 6.5%\",\"2) 2.5%\",\"3) 9.8%\",\"4) 1.2%\"]"', '1', NULL, 1, 0, 4, 'General', 'In 2026, IMF projected India''s GDP growth at around what rate?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["IMF ने 2026 में भारत की वृद्धि दर लगभग 6.5% बताई।","भारत प्रमुख तेज़ी से बढ़ती अर्थव्यवस्थाओं में शामिल रहा।"],"factsEn":["IMF estimated India''s growth around 6.5% in 2026.","India remained among fast-growing major economies."],"mnemonics":["India growth = 6.5 mix."],"related":["GDP","IMF outlook"],"memoryTip":"IMF + India = 6.5% याद रखें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('3BU7nzjNKk0vdA8nrkG3E', 'I--ZFJDWbkGEvUGlFvqk7', 'G20 की 2026 अध्यक्षता किस देश के पास थी? / Which country held the G20 presidency in 2026?', '"[\"1) संयुक्त राज्य अमेरिका / United States\",\"2) भारत / India\",\"3) ब्राज़ील / Brazil\",\"4) जापान / Japan\"]"', '1', NULL, 1, 0, 5, 'General', 'Which country held the G20 presidency in 2026?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["2026 में G20 की अध्यक्षता अमेरिका के पास थी।"],"factsEn":["The United States held the G20 presidency in 2026."],"mnemonics":["G20-26 = US mix."],"related":["G20","वैश्विक मंच"],"memoryTip":"2026 G20 = USA."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('T7_8TUnFpMwBRkzDn4nvm', 'I--ZFJDWbkGEvUGlFvqk7', '2026 में भारत-ROK रणनीतिक दृष्टि में ROK किस देश को दर्शाता है? / In 2026 India-ROK vision, ROK refers to which country?', '"[\"1) दक्षिण कोरिया / South Korea\",\"2) उत्तर कोरिया / North Korea\",\"3) रूस / Russia\",\"4) केन्या / Kenya\"]"', '1', NULL, 1, 0, 6, 'General', 'In 2026 India-ROK vision, ROK refers to which country?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["ROK का अर्थ Republic of Korea है।","यह दक्षिण कोरिया को दर्शाता है।"],"factsEn":["ROK stands for Republic of Korea.","It refers to South Korea."],"mnemonics":["ROK = Republic of Korea."],"related":["एशिया","भारत-दक्षिण कोरिया संबंध"],"memoryTip":"ROK = South Korea."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('GfRdhFYsiEHTbRP-OpLcF', 'I--ZFJDWbkGEvUGlFvqk7', 'विश्व बैंक (World Bank) का मुख्यालय कहाँ स्थित है? / Where is the headquarters of the World Bank located?', '"[\"1) वॉशिंगटन डी.सी. / Washington D.C.\",\"2) लंदन / London\",\"3) जेनेवा / Geneva\",\"4) पेरिस / Paris\"]"', '1', NULL, 1, 0, 7, 'General', 'Where is the headquarters of the World Bank located?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["विश्व बैंक का मुख्यालय अमेरिका की राजधानी वॉशिंगटन डी.सी. में है।"],"factsEn":["The World Bank headquarters is in Washington D.C., USA."],"mnemonics":["World Bank = Washington."],"related":["IMF","अंतरराष्ट्रीय संस्थाएँ"],"memoryTip":"WB HQ = Washington D.C."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ZIGEPBwQNHJWAO8_Qe6wC', 'I--ZFJDWbkGEvUGlFvqk7', 'NATO का मुख्य उद्देश्य क्या है? / What is the main objective of NATO?', '"[\"1) सामूहिक रक्षा / Collective defence\",\"2) व्यापार समझौता / Trade agreement\",\"3) शिक्षा सहयोग / Education cooperation\",\"4) कृषि विकास / Agricultural development\"]"', '1', NULL, 1, 0, 8, 'General', 'What is the main objective of NATO?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["NATO एक सैन्य गठबंधन है।","इसका प्रमुख उद्देश्य सदस्य देशों की सामूहिक रक्षा है।"],"factsEn":["NATO is a military alliance.","Its main objective is collective defence of members."],"mnemonics":["NATO = सुरक्षा गठबंधन।"],"related":["यूरोप","अमेरिका"],"memoryTip":"NATO = Defence alliance."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('nRIy59tikM6X25dcWh-57', 'I--ZFJDWbkGEvUGlFvqk7', 'UNO का मुख्यालय कहाँ है? / Where is the headquarters of the UNO?', '"[\"1) न्यूयॉर्क / New York\",\"2) रोम / Rome\",\"3) टोक्यो / Tokyo\",\"4) मॉस्को / Moscow\"]"', '1', NULL, 1, 0, 9, 'General', 'Where is the headquarters of the UNO?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["संयुक्त राष्ट्र संगठन का मुख्यालय न्यूयॉर्क में स्थित है।"],"factsEn":["The headquarters of the United Nations is in New York."],"mnemonics":["UNO = New York office."],"related":["UNSC","UNGA"],"memoryTip":"UNO HQ = New York."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('D5K2c3kXkv01ZF9XNtq35', 'I--ZFJDWbkGEvUGlFvqk7', 'निम्न में से कौन-सा युग्म सही सुमेलित है? / Which of the following pair is correctly matched?', '"[\"1) IMF - वॉशिंगटन डी.सी. / IMF - Washington D.C.\",\"2) UNO - पेरिस / UNO - Paris\",\"3) NATO - टोक्यो / NATO - Tokyo\",\"4) World Bank - जिनेवा / World Bank - Geneva\"]"', '1', NULL, 1, 0, 10, 'General', 'Which of the following pair is correctly matched?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["IMF का मुख्यालय वॉशिंगटन डी.सी. में है।","अन्य विकल्प गलत हैं।"],"factsEn":["IMF headquarters is in Washington D.C.","Other options are incorrect."],"mnemonics":["IMF + WB = Washington twins."],"related":["HQ based questions","Trap MCQs"],"memoryTip":"IMF/WB दोनों Washington D.C. में हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('nRtmgL3A6Bx3jwZ2m9A-1', 'oTPG8YtMT_Tpqe5JNRtWd', 'मध्य प्रदेश का कौन सा जिला अपनी विश्व प्रसिद्ध ''चंदेरी साड़ियों'' के लिए जाना जाता है?', '"[\"1) अशोकनगर / Ashoknagar\",\"2) धार / Dhar\",\"3) खरगोन / Khargone\",\"4) रीवा / Rewa\"]"', '1', NULL, 1, 0, 1, 'General', 'Which district of Madhya Pradesh is known for its world-famous ''Chanderi Sarees''?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["चंदेरी साड़ियाँ रेशम और सूती धागों के मिश्रण से बुनी जाती हैं और अपने हल्के वजन तथा पारदर्शी बनावट के लिए प्रसिद्ध हैं।","चंदेरी मध्य प्रदेश के अशोकनगर जिले का एक ऐतिहासिक शहर है।"],"factsEn":["Chanderi sarees are woven from a blend of silk and cotton threads and are famous for their lightweight and sheer texture.","Chanderi is a historical town in the Ashoknagar district of Madhya Pradesh."],"mnemonics":["Chanderi-Ashoka"],"related":["चंदेरी का किला (अशोकनगर) / Chanderi Fort (Ashoknagar)"],"memoryTip":"चंदेरी की साड़ी पहनकर ''अशोक'' नगर गया। (Visit mppsc.zenscroll.app for MP Police test series)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xhMc3aMZHh0v20CuOb0Lv', 'oTPG8YtMT_Tpqe5JNRtWd', 'प्राकृतिक रंगों का उपयोग करने वाला प्रसिद्ध ''बाघ प्रिंट'' (Bagh Print) हस्तशिल्प मध्य प्रदेश के किस जिले से संबंधित है?', '"[\"1) उज्जैन / Ujjain\",\"2) धार / Dhar\",\"3) भोपाल / Bhopal\",\"4) इंदौर / Indore\"]"', '2', NULL, 1, 0, 2, 'General', 'The famous ''Bagh Print'' handicraft, which uses natural colors, belongs to which district of Madhya Pradesh?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["बाघ प्रिंट मध्य प्रदेश के धार जिले के बाघ गांव की एक पारंपरिक ब्लॉक प्रिंटिंग तकनीक है।","इसमें कपड़े पर छपाई के लिए प्राकृतिक रंगों और लकड़ी के ब्लॉकों (wooden blocks) का उपयोग किया जाता है।"],"factsEn":["Bagh print is a traditional block printing technique from the Bagh village in the Dhar district of Madhya Pradesh.","It uses natural colors and wooden blocks for printing on fabric."],"mnemonics":["Bagh-Dhar"],"related":["बाघ की गुफाएं (धार) / Bagh Caves (Dhar)","भैरवगढ़ प्रिंट (उज्जैन) / Bhairavgarh Print (Ujjain)"],"memoryTip":"''बाघ'' (Bagh) के दांतों में बहुत ''धार'' (Dhar) होती है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0jA8l8CwRNpFjCXhZNG93', 'oTPG8YtMT_Tpqe5JNRtWd', 'मध्य प्रदेश का बैतूल जिला मुख्य रूप से किस पारंपरिक हस्तशिल्प के लिए प्रसिद्ध है?', '"[\"1) ढोकरा (बेल मेटल) शिल्प / Dhokra (Bell Metal) craft\",\"2) बांस शिल्प / Bamboo craft\",\"3) मिट्टी के बर्तन / Terracotta pottery\",\"4) पत्थर की नक्काशी / Stone carving\"]"', '1', NULL, 1, 0, 3, 'General', 'The Betul district of Madhya Pradesh is mainly famous for which traditional handicraft?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["ढोकरा या बेल मेटल शिल्प एक प्राचीन धातु कला है जो ''लॉस्ट वैक्स कास्टिंग'' (lost wax casting) तकनीक का उपयोग करती है।","मध्य प्रदेश में बैतूल का टिकारी गांव और टीकमगढ़ इस धातु कला के लिए विशेष रूप से प्रसिद्ध हैं।"],"factsEn":["Dhokra or Bell Metal craft is an ancient metal art that uses the ''lost wax casting'' technique.","In Madhya Pradesh, the Tikari village of Betul and Tikamgarh are particularly famous for this metal art."],"mnemonics":["Bell-Betul"],"related":["भरवे जनजाति (बैतूल की धातु शिल्पकार) / Bharwe tribe (Metal craftsmen of Betul)"],"memoryTip":"बिना ''तुल'' (Betul) के बेल (Bell Metal) नहीं बजती।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('p2DsRzeAuuzX2TDg3SD0u', 'oTPG8YtMT_Tpqe5JNRtWd', 'मध्य प्रदेश की प्रसिद्ध शिल्पकार ''बत्तो बाई'' किस हस्तशिल्प कला से जुड़ी हुई हैं?', '"[\"1) गुड़िया शिल्प / Doll craft\",\"2) छिपा शिल्प / Chhipa craft\",\"3) जरदोजी कला / Zardozi art\",\"4) पिथौरा चित्रकला / Pithora painting\"]"', '1', NULL, 1, 0, 4, 'General', 'The famous craftswoman of Madhya Pradesh, ''Batto Bai'', is associated with which handicraft art?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["बत्तो बाई मध्य प्रदेश के ग्वालियर शहर की एक प्रसिद्ध गुड़िया शिल्पकार (Doll maker) हैं।","ग्वालियर कपड़ों, लकड़ी और कागज की लुगदी से बनी अपनी पारंपरिक गुड़ियों के लिए जाना जाता है जो भारतीय संस्कृति को दर्शाती हैं।"],"factsEn":["Batto Bai is a famous doll maker from the Gwalior city of Madhya Pradesh.","Gwalior is known for its traditional dolls made of cloth, wood, and papier-mâché that depict Indian culture."],"mnemonics":["Batto-Doll"],"related":["झाबुआ गुड़िया (भील जनजाति की गुड़िया) / Jhabua Dolls (Dolls of Bhil tribe)"],"memoryTip":"ग्वालियर के किले में बत्तो बाई की ''गुड़िया'' (Dolls) हैं। (Explore more MP facts at upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('HNyPR2ghoOvVHaOI_ZUqH', 'oTPG8YtMT_Tpqe5JNRtWd', 'महारानी अहिल्याबाई होल्कर द्वारा किस प्रसिद्ध साड़ी की बुनाई का संरक्षण और विकास किया गया था?', '"[\"1) चंदेरी साड़ी / Chanderi Saree\",\"2) महेश्वरी साड़ी / Maheshwari Saree\",\"3) पैठणी साड़ी / Paithani Saree\",\"4) बनारसी साड़ी / Banarasi Saree\"]"', '2', NULL, 1, 0, 5, 'General', 'The weaving of which famous saree was patronized and developed by Queen Ahilyabai Holkar?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["महेश्वरी साड़ियों की उत्पत्ति मध्य प्रदेश के खरगोन जिले के ऐतिहासिक शहर महेश्वर में हुई थी।","इन्हें 18वीं शताब्दी में महारानी अहिल्याबाई होल्कर के संरक्षण में विकसित किया गया था।"],"factsEn":["Maheshwari sarees originated in the historical town of Maheshwar in the Khargone district of Madhya Pradesh.","They were developed under the patronage of Queen Ahilyabai Holkar in the 18th century."],"mnemonics":["Maheshwar-Holkar"],"related":["खरगोन जिला (महेश्वर स्थित है) / Khargone district (Maheshwar is located)"],"memoryTip":"महारानी अहिल्याबाई ने ''महेश्वर'' (Maheshwari) में अपनी राजधानी बनाई थी।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('RcBVLF47yDJeC3xogwzHq', 'oTPG8YtMT_Tpqe5JNRtWd', 'सुपारी (Betel nut) पर बारीक नक्काशी करके बनाए जाने वाले खिलौने और मूर्तियां मध्य प्रदेश के किस जिले की विशेषता हैं?', '"[\"1) पन्ना / Panna\",\"2) रीवा / Rewa\",\"3) दमोह / Damoh\",\"4) कटनी / Katni\"]"', '2', NULL, 1, 0, 6, 'General', 'Toys and idols made by intricate carving on Supari (Betel nut) are a specialty of which district of Madhya Pradesh?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["रीवा जिला सुपारी (Betel nut) हस्तशिल्प के लिए पूरे भारत में प्रसिद्ध है।","यहाँ के कारीगर सुपारी को तराश कर देवी-देवताओं की छोटी मूर्तियां और खिलौने बनाते हैं।"],"factsEn":["Rewa district is famous all over India for Supari (Betel nut) handicrafts.","Artisans here carve betel nuts to make small idols of deities and toys."],"mnemonics":["Rewa-Supari"],"related":["सफेद शेर (रीवा) / White Tiger (Rewa)"],"memoryTip":"सफेद शेर ''रीवा'' में ''सुपारी'' खाता है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('N5sHVzXTnzBc2H-QqVh1n', 'oTPG8YtMT_Tpqe5JNRtWd', 'मध्य प्रदेश का ''बुदनी'' (Budhni) शहर किस पारंपरिक हस्तशिल्प के लिए भौगोलिक संकेतक (GI) टैग की मांग के कारण चर्चा में रहा है?', '"[\"1) लकड़ी के खिलौने / Wooden Toys\",\"2) चमड़े के बैग / Leather Bags\",\"3) कांच की चूड़ियाँ / Glass Bangles\",\"4) जूट शिल्प / Jute Craft\"]"', '1', NULL, 1, 0, 7, 'General', 'The city of ''Budhni'' in Madhya Pradesh has been in news demanding a Geographical Indication (GI) tag for which traditional handicraft?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["सीहोर जिले का बुदनी क्षेत्र दूधी लकड़ी (Dudhi wood) से बने अपने पारंपरिक लकड़ी के खिलौनों के लिए प्रसिद्ध है।","इन खिलौनों को प्राकृतिक रंगों से रंगा जाता है और यह स्थानीय कारीगरों की आजीविका का मुख्य साधन है।"],"factsEn":["The Budhni region of Sehore district is famous for its traditional wooden toys made from Dudhi wood.","These toys are painted with natural colors and are the main source of livelihood for local artisans."],"mnemonics":["Budhni-Wood"],"related":["सीहोर जिला / Sehore district"],"memoryTip":"''बुद्ध'' (Budhni) को बचपन में ''लकड़ी के खिलौने'' (Wooden Toys) पसंद थे। (Keep revising on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('m5rOSYINQOxZZOtrIZDIJ', 'oTPG8YtMT_Tpqe5JNRtWd', 'सोने और चांदी के धागों से की जाने वाली ''ज़री-ज़रदोज़ी'' (Zari-Zardozi) कला मुख्य रूप से मध्य प्रदेश के किस शहर में की जाती है?', '"[\"1) इंदौर / Indore\",\"2) भोपाल / Bhopal\",\"3) जबलपुर / Jabalpur\",\"4) रतलाम / Ratlam\"]"', '2', NULL, 1, 0, 8, 'General', 'The ''Zari-Zardozi'' art, done with gold and silver threads, is mainly practiced in which city of Madhya Pradesh?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["ज़री-ज़रदोज़ी कपड़ों पर धातु के धागों (मूल रूप से सोने और चांदी) से की जाने वाली एक विस्तृत कढ़ाई है।","मध्य प्रदेश में, भोपाल इस शाही कढ़ाई कला का एक प्रमुख केंद्र है, जिसे नवाबों के समय से संरक्षण मिला हुआ है।"],"factsEn":["Zari-Zardozi is an elaborate embroidery done with metallic threads (originally gold and silver) on fabrics.","In Madhya Pradesh, Bhopal is a major center for this royal embroidery art, having received patronage since the time of the Nawabs."],"mnemonics":["Zari-Nawab-Bhopal"],"related":["बटुआ शिल्प (भोपाल) / Batua craft (Bhopal)"],"memoryTip":"भोपाल के नवाब ''ज़री'' (Zari) के शाही कपड़े पहनते थे।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('HyVCU-5z-3tE_h4tvobVf', 'oTPG8YtMT_Tpqe5JNRtWd', 'प्रसिद्ध ''चिकनकारी'' (Chikankari) कढ़ाई हस्तशिल्प भारत के किस शहर से संबंधित है?', '"[\"1) लखनऊ, उत्तर प्रदेश / Lucknow, Uttar Pradesh\",\"2) जयपुर, राजस्थान / Jaipur, Rajasthan\",\"3) सूरत, गुजरात / Surat, Gujarat\",\"4) अमृतसर, पंजाब / Amritsar, Punjab\"]"', '1', NULL, 1, 0, 9, 'General', 'The famous ''Chikankari'' embroidery handicraft belongs to which city of India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["चिकनकारी एक पारंपरिक और बारीक सफेद धागे की कढ़ाई है जो हल्के मलमल या सूती कपड़ों पर की जाती है।","यह उत्तर प्रदेश की राजधानी लखनऊ की सबसे प्रसिद्ध और पुरानी कलाओं में से एक है।"],"factsEn":["Chikankari is a traditional and delicate white thread embroidery done on light muslin or cotton fabrics.","It is one of the most famous and ancient arts of Lucknow, the capital of Uttar Pradesh."],"mnemonics":["Chikan-Nawab"],"related":["फुलकारी (पंजाब की कढ़ाई) / Phulkari (Embroidery of Punjab)"],"memoryTip":"नवाबों के शहर ''लखनऊ'' में लोग ''चिकनकारी'' वाले कुर्ते पहनते हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xrRgKJNxZT4wx2favm3wQ', 'oTPG8YtMT_Tpqe5JNRtWd', 'भील जनजाति द्वारा मुख्य रूप से उपयोग किया जाने वाला ''नंदना प्रिंट'' (Nandana Print) मध्य प्रदेश के किस जिले का प्रसिद्ध हस्तशिल्प है?', '"[\"1) नीमच / Neemuch\",\"2) झाबुआ / Jhabua\",\"3) अलीराजपुर / Alirajpur\",\"4) बड़वानी / Barwani\"]"', '1', NULL, 1, 0, 10, 'General', 'The ''Nandana Print'', primarily used by the Bhil tribe, is a famous handicraft of which district of Madhya Pradesh?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["नंदना प्रिंट नीमच जिले के तारापुर और उम्मेदपुरा गांवों की एक पारंपरिक ब्लॉक प्रिंटिंग कला है।","इस प्रिंट के कपड़े मुख्य रूप से भील जनजाति की महिलाओं द्वारा पहने जाते हैं और इसमें विशिष्ट प्रकृति-प्रेरित रूपांकन (motifs) होते हैं।"],"factsEn":["Nandana Print is a traditional block printing art of Tarapur and Ummedpura villages of Neemuch district.","Fabrics of this print are primarily worn by women of the Bhil tribe and feature distinctive nature-inspired motifs."],"mnemonics":["Nandana-Neemuch (N-N)"],"related":["तारापुर गांव (नीमच) / Tarapur village (Neemuch)"],"memoryTip":"''नंदना'' को ''नीम'' (Neemuch) का पेड़ पसंद है। (Mock tests available on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('op5JRvezXTbo0Ex7CjiGu', 'ojtefPsSxk3lsGBMtLuON', 'भारत की राजधानी क्या है? / What is the capital of India?', '"[\"1) नई दिल्ली / New Delhi\",\"2) मुंबई / Mumbai\",\"3) कोलकाता / Kolkata\",\"4) चेन्नई / Chennai\"]"', '1', NULL, 1, 0, 1, 'General', 'What is the capital of India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भारत की राजधानी नई दिल्ली है।","नई दिल्ली देश का प्रशासनिक केंद्र है।"],"factsEn":["New Delhi is the capital of India.","New Delhi is the administrative center of the country."],"mnemonics":["India = New Delhi fixed pair."],"related":["भारत","संसद भवन"],"memoryTip":"India पूछे तो New Delhi तुरंत याद करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0Sunc9INRDZ5I1kcHYG2l', 'ojtefPsSxk3lsGBMtLuON', 'जापान की राजधानी क्या है? / What is the capital of Japan?', '"[\"1) टोक्यो / Tokyo\",\"2) सियोल / Seoul\",\"3) बैंकॉक / Bangkok\",\"4) बीजिंग / Beijing\"]"', '1', NULL, 1, 0, 2, 'General', 'What is the capital of Japan?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["जापान की राजधानी टोक्यो है।","टोक्यो विश्व के प्रमुख महानगरों में से एक है।"],"factsEn":["Tokyo is the capital of Japan.","Tokyo is one of the major metropolitan cities of the world."],"mnemonics":["Japan jumps to Tokyo."],"related":["एशिया","जापान"],"memoryTip":"Japan = Tokyo."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Q-LmSRHmBvJYIbEX0Fxie', 'ojtefPsSxk3lsGBMtLuON', 'चीन की राजधानी क्या है? / What is the capital of China?', '"[\"1) बीजिंग / Beijing\",\"2) शंघाई / Shanghai\",\"3) हांगकांग / Hong Kong\",\"4) वुहान / Wuhan\"]"', '1', NULL, 1, 0, 3, 'General', 'What is the capital of China?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["चीन की राजधानी बीजिंग है।","बीजिंग चीन का राजनीतिक केंद्र है।"],"factsEn":["Beijing is the capital of China.","Beijing is the political center of China."],"mnemonics":["China chooses Beijing."],"related":["एशिया","चीन"],"memoryTip":"China = Beijing."}}', 'mppolice');
