INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9F8HIVvusTLGFzQm-oL_A', 'ojtefPsSxk3lsGBMtLuON', 'रूस की राजधानी क्या है? / What is the capital of Russia?', '"[\"1) मॉस्को / Moscow\",\"2) सेंट पीटर्सबर्ग / Saint Petersburg\",\"3) कज़ान / Kazan\",\"4) सोची / Sochi\"]"', '1', NULL, 1, 0, 5, 'General', 'What is the capital of Russia?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["रूस की राजधानी मॉस्को है।","मॉस्को यूरोप के बड़े शहरों में शामिल है।"],"factsEn":["Moscow is the capital of Russia.","Moscow is among the major cities of Europe."],"mnemonics":["Russia = Moscow must know."],"related":["रूस","यूरोप"],"memoryTip":"Russia = Moscow."}}', 'mppolice');
