INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('p0e6tDHM2iT1ZcXpLiDNc', 'ojtefPsSxk3lsGBMtLuON', 'ब्राज़ील की राजधानी क्या है? / What is the capital of Brazil?', '"[\"1) ब्रासीलिया / Brasilia\",\"2) रियो डी जेनेरो / Rio de Janeiro\",\"3) साओ पाउलो / Sao Paulo\",\"4) सल्वाडोर / Salvador\"]"', '1', NULL, 1, 0, 9, 'General', 'What is the capital of Brazil?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["ब्राज़ील की राजधानी ब्रासीलिया है।","रियो डी जेनेरो पूर्व राजधानी थी।"],"factsEn":["Brasilia is the capital of Brazil.","Rio de Janeiro was the former capital."],"mnemonics":["Brazil = Brasilia same sound."],"related":["दक्षिण अमेरिका","ब्राज़ील"],"memoryTip":"Brazil = Brasilia, not Rio."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('baYweQLKbrHoLfypUcvgN', 'ojtefPsSxk3lsGBMtLuON', 'निम्न में से कौन-सा युग्म सही सुमेलित है? / Which of the following pair is correctly matched?', '"[\"1) श्रीलंका - श्री जयवर्धनेपुरा कोट्टे / Sri Lanka - Sri Jayawardenepura Kotte\",\"2) पाकिस्तान - कराची / Pakistan - Karachi\",\"3) फ्रांस - मार्से / France - Marseille\",\"4) जर्मनी - म्यूनिख / Germany - Munich\"]"', '1', NULL, 1, 0, 10, 'General', 'Which of the following pair is correctly matched?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["श्रीलंका की आधिकारिक राजधानी श्री जयवर्धनेपुरा कोट्टे है।","पाकिस्तान की राजधानी इस्लामाबाद है।","फ्रांस की राजधानी पेरिस और जर्मनी की राजधानी बर्लिन है।"],"factsEn":["Sri Jayawardenepura Kotte is the official capital of Sri Lanka.","Islamabad is the capital of Pakistan.","Paris is the capital of France and Berlin of Germany."],"mnemonics":["Sri Lanka = Kotte tricky capital."],"related":["Trap capitals","पड़ोसी देश"],"memoryTip":"Unusual capitals अलग से revise करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('hfiVJyxQpmTbTmEmNlKG6', 'MMp8G22iL2O95zKvxI80k', 'आकाश नीला क्यों दिखाई देता है? / Why does the sky appear blue?', '"[\"1) प्रकाश का प्रकीर्णन / Scattering of light\",\"2) प्रकाश का परावर्तन / Reflection of light\",\"3) प्रकाश का अपवर्तन / Refraction of light\",\"4) प्रकाश का अवशोषण / Absorption of light\"]"', '1', NULL, 1, 0, 1, 'General', 'Why does the sky appear blue?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["आकाश नीला प्रकाश के प्रकीर्णन के कारण दिखाई देता है।","नीली तरंगदैर्घ्य का प्रकीर्णन अधिक होता है।"],"factsEn":["The sky appears blue due to scattering of light.","Blue wavelength scatters more in the atmosphere."],"mnemonics":["Blue = ज्यादा Scatter."],"related":["रेले प्रकीर्णन","वायुमंडल"],"memoryTip":"Sky blue = Scattering याद रखें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bXIiSIPxiXimQO2RiHTc9', 'MMp8G22iL2O95zKvxI80k', 'इंद्रधनुष बनने का मुख्य कारण क्या है? / What is the main reason for formation of a rainbow?', '"[\"1) अपवर्तन, परावर्तन व वर्ण विक्षेपण / Refraction, reflection and dispersion\",\"2) केवल परावर्तन / Only reflection\",\"3) केवल अवशोषण / Only absorption\",\"4) केवल चालकता / Only conductivity\"]"', '1', NULL, 1, 0, 2, 'General', 'What is the main reason for formation of a rainbow?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["इंद्रधनुष वर्षा की बूंदों में प्रकाश के अपवर्तन, आंतरिक परावर्तन और वर्ण विक्षेपण से बनता है।"],"factsEn":["Rainbow forms due to refraction, internal reflection and dispersion of light in raindrops."],"mnemonics":["Rainbow = RRD (Refraction Reflection Dispersion)."],"related":["सूर्य प्रकाश","जल बूंदें"],"memoryTip":"Rainbow में 3 process याद रखें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Nv9AH4RKCpygffX9mkzYn', 'MMp8G22iL2O95zKvxI80k', 'गर्मियों में पानी जल्दी क्यों सूखता है? / Why does water dry faster in summer?', '"[\"1) वाष्पीकरण तेज होने से / Due to faster evaporation\",\"2) संघनन बढ़ने से / Due to condensation\",\"3) जमने से / Due to freezing\",\"4) घुलनशीलता से / Due to solubility\"]"', '1', NULL, 1, 0, 3, 'General', 'Why does water dry faster in summer?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["उच्च तापमान पर वाष्पीकरण की दर बढ़ जाती है।","इसलिए गर्मियों में पानी जल्दी सूखता है।"],"factsEn":["Rate of evaporation increases at higher temperature.","Hence water dries faster in summer."],"mnemonics":["Heat = Fast Evaporation."],"related":["तापमान","जल चक्र"],"memoryTip":"Summer drying = Evaporation."}}', 'mppolice');
