INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('CcC0KhFlGSNCR-jcGsSOA', 'MMp8G22iL2O95zKvxI80k', 'मरुस्थल में दूर पानी जैसा दिखाई देना किसका उदाहरण है? / Seeing water at a distance in desert is an example of what?', '"[\"1) मृगतृष्णा / Mirage\",\"2) इंद्रधनुष / Rainbow\",\"3) ग्रहण / Eclipse\",\"4) धुंध / Fog\"]"', '1', NULL, 1, 0, 9, 'General', 'Seeing water at a distance in desert is an example of what?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["गरम हवा की परतों में प्रकाश के अपवर्तन से मृगतृष्णा बनती है।"],"factsEn":["Mirage is formed due to refraction of light in hot air layers."],"mnemonics":["Desert water = Mirage."],"related":["अपवर्तन","रेगिस्तान"],"memoryTip":"Desert illusion = Mirage."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ZvlLi1Dmqb02Bt9HCWMzT', 'MMp8G22iL2O95zKvxI80k', 'निम्न में से कौन-सा सही सुमेलित है? / Which of the following is correctly matched?', '"[\"1) दर्पण - परावर्तन / Mirror - Reflection\",\"2) इंद्रधनुष - चालकता / Rainbow - Conductivity\",\"3) पसीना - संघनन / Sweat - Condensation\",\"4) तारे टिमटिमाना - गुरुत्वाकर्षण / Twinkling stars - Gravitation\"]"', '1', NULL, 1, 0, 10, 'General', 'Which of the following is correctly matched?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["दर्पण में प्रतिबिंब परावर्तन से बनता है।","अन्य विकल्प गलत वैज्ञानिक कारण दर्शाते हैं।"],"factsEn":["Mirror image forms due to reflection.","Other options show incorrect scientific causes."],"mnemonics":["Mirror means Reflect."],"related":["Matching type","Optics"],"memoryTip":"Known phenomenon-cause pairs revise करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('_XVEXzi8JRya74CLAXEVv', 'k7Me5NZ5nQuJIttTuKhzg', 'भारतीय संविधान का कौन सा अनुच्छेद ''अस्पृश्यता के अंत'' (Abolition of Untouchability) से संबंधित है?', '"[\"1) अनुच्छेद 14 / Article 14\",\"2) अनुच्छेद 17 / Article 17\",\"3) अनुच्छेद 19 / Article 19\",\"4) अनुच्छेद 21 / Article 21\"]"', '2', NULL, 1, 0, 1, 'General', 'Which Article of the Indian Constitution deals with the ''Abolition of Untouchability''?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["अनुच्छेद 17 अस्पृश्यता (छुआछूत) को समाप्त करता है और किसी भी रूप में इसके अभ्यास को प्रतिबंधित करता है।","यह भारतीय संविधान के भाग III (मौलिक अधिकार) के अंतर्गत समानता के अधिकार का हिस्सा है।"],"factsEn":["Article 17 abolishes untouchability and forbids its practice in any form.","It is part of the Right to Equality under Part III (Fundamental Rights) of the Indian Constitution."],"mnemonics":["17 - खतरा (Khatra): छुआछूत समाज के लिए खतरा है।"],"related":["अनुच्छेद 14 (कानून के समक्ष समानता) / Article 14 (Equality before law)","अनुच्छेद 18 (उपाधियों का अंत) / Article 18 (Abolition of titles)"],"memoryTip":"17 में अस्पृश्यता को मिटा दिया गया। (Visit mppsc.zenscroll.app for MP Police test series)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sEguNWZmNV4nSrQmC4dw5', 'k7Me5NZ5nQuJIttTuKhzg', 'राज्य सभा के सदस्यों का कार्यकाल कितने वर्ष का होता है?', '"[\"1) 4 वर्ष / 4 Years\",\"2) 5 वर्ष / 5 Years\",\"3) 6 वर्ष / 6 Years\",\"4) 2 वर्ष / 2 Years\"]"', '3', NULL, 1, 0, 2, 'General', 'What is the tenure of the members of the Rajya Sabha?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["राज्य सभा (उच्च सदन) एक स्थायी निकाय है और इसे कभी भंग नहीं किया जा सकता।","हालाँकि, इसके प्रत्येक सदस्य को 6 वर्ष के कार्यकाल के लिए चुना जाता है, और एक तिहाई सदस्य हर दूसरे वर्ष सेवानिवृत्त होते हैं।"],"factsEn":["Rajya Sabha (Upper House) is a permanent body and is not subject to dissolution.","However, each member is elected for a term of 6 years, and one-third of the members retire every second year."],"mnemonics":["RS = 6 (Rajya Sabha members get 6 years)"],"related":["लोक सभा का कार्यकाल (5 वर्ष) / Lok Sabha tenure (5 Years)"],"memoryTip":"राज्य सभा स्थायी है, इसलिए इसके सदस्यों का कार्यकाल लोक सभा (5 वर्ष) से 1 वर्ष अधिक यानी 6 वर्ष है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9EmuDh2GMy7cOowDpKekn', 'k7Me5NZ5nQuJIttTuKhzg', 'भारत के राष्ट्रपति का चुनाव लड़ने के लिए न्यूनतम आयु सीमा क्या है?', '"[\"1) 25 वर्ष / 25 Years\",\"2) 30 वर्ष / 30 Years\",\"3) 35 वर्ष / 35 Years\",\"4) 40 वर्ष / 40 Years\"]"', '3', NULL, 1, 0, 3, 'General', 'What is the minimum age limit to contest the election for the President of India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["संविधान के अनुच्छेद 58 के अनुसार, राष्ट्रपति पद का उम्मीदवार भारत का नागरिक होना चाहिए और कम से कम 35 वर्ष की आयु पूरी कर चुका हो।","उसे लोक सभा का सदस्य चुने जाने के योग्य भी होना चाहिए।"],"factsEn":["According to Article 58, a candidate for the President''s post must be a citizen of India and have completed 35 years of age.","He/she must also be qualified for election as a member of the Lok Sabha."],"mnemonics":["PM-25, President-35"],"related":["प्रधानमंत्री के लिए न्यूनतम आयु (25 वर्ष यदि लोक सभा सदस्य है) / Minimum age for PM (25 years if Lok Sabha member)","राज्य सभा सदस्य के लिए न्यूनतम आयु (30 वर्ष) / Minimum age for Rajya Sabha member (30 years)"],"memoryTip":"देश का सबसे बड़ा पद संभालने के लिए कम से कम 35 साल का अनुभव (आयु) चाहिए।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Y0JmrRBcnauLrhYssytTY', 'k7Me5NZ5nQuJIttTuKhzg', 'भारतीय संविधान की ''प्रारूप समिति'' (Drafting Committee) के अध्यक्ष कौन थे?', '"[\"1) डॉ. राजेंद्र प्रसाद / Dr. Rajendra Prasad\",\"2) जवाहरलाल नेहरू / Jawaharlal Nehru\",\"3) बी. एन. राव / B. N. Rau\",\"4) डॉ. बी. आर. अंबेडकर / Dr. B. R. Ambedkar\"]"', '4', NULL, 1, 0, 4, 'General', 'Who was the Chairman of the ''Drafting Committee'' of the Indian Constitution?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["संविधान का मसौदा तैयार करने के लिए 29 अगस्त 1947 को डॉ. बी.आर. अंबेडकर की अध्यक्षता में प्रारूप समिति का गठन किया गया था।","इस समिति में कुल 7 सदस्य थे। डॉ. राजेंद्र प्रसाद संविधान सभा के स्थायी अध्यक्ष थे।"],"factsEn":["The Drafting Committee was set up on 29 August 1947 under the chairmanship of Dr. B.R. Ambedkar to prepare the draft of the Constitution.","This committee had 7 members. Dr. Rajendra Prasad was the permanent president of the Constituent Assembly."],"mnemonics":["Ambedkar - Architect (Drafting)"],"related":["संघ शक्ति समिति (जवाहरलाल नेहरू) / Union Powers Committee (Jawaharlal Nehru)"],"memoryTip":"संविधान का सबसे महत्वपूर्ण ''ड्राफ्ट'' अंबेडकर जी ने तैयार किया था। (Practice daily on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('xUF8-bOzmiWgJq-TND8IU', 'k7Me5NZ5nQuJIttTuKhzg', 'भारतीय संविधान के किस संशोधन द्वारा पंचायती राज व्यवस्था को संवैधानिक दर्जा दिया गया?', '"[\"1) 42वां संशोधन / 42nd Amendment\",\"2) 44वां संशोधन / 44th Amendment\",\"3) 73वां संशोधन / 73rd Amendment\",\"4) 74वां संशोधन / 74th Amendment\"]"', '3', NULL, 1, 0, 5, 'General', 'By which amendment of the Indian Constitution was constitutional status given to the Panchayati Raj system?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["73वें संविधान संशोधन अधिनियम (1992) द्वारा पंचायती राज संस्थाओं को संवैधानिक दर्जा प्रदान किया गया।","इस संशोधन ने संविधान में भाग IX और 11वीं अनुसूची जोड़ी, जिसमें पंचायतों के 29 विषय शामिल हैं।"],"factsEn":["The 73rd Constitutional Amendment Act (1992) granted constitutional status to Panchayati Raj institutions.","This amendment added Part IX and the 11th Schedule to the Constitution, containing 29 subjects of Panchayats."],"mnemonics":["73 = Village Panchayat, 74 = City Municipality"],"related":["74वां संशोधन (नगरपालिकाएं) / 74th Amendment (Municipalities)"],"memoryTip":"73वें साल में गांव (पंचायत) और 74वें में शहर (नगरपालिका) का विकास हुआ।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dDQ4W8AZ_gfNvoqa8U_dZ', 'k7Me5NZ5nQuJIttTuKhzg', 'भारतीय संविधान में ''मौलिक कर्तव्य'' (Fundamental Duties) किस देश के संविधान से लिए गए हैं?', '"[\"1) अमेरिका (USA) / USA\",\"2) रूस (USSR) / Russia (USSR)\",\"3) ब्रिटेन / Britain\",\"4) आयरलैंड / Ireland\"]"', '2', NULL, 1, 0, 6, 'General', '''Fundamental Duties'' in the Indian Constitution are borrowed from the constitution of which country?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["मौलिक कर्तव्यों को 42वें संविधान संशोधन (1976) द्वारा स्वर्ण सिंह समिति की सिफारिश पर तत्कालीन सोवियत संघ (USSR/रूस) से लिया गया था।","इन्हें संविधान के भाग IV-A के अनुच्छेद 51A में रखा गया है।"],"factsEn":["Fundamental Duties were added by the 42nd Amendment (1976) on the recommendation of the Swaran Singh Committee, borrowed from the then Soviet Union (USSR/Russia).","They are placed in Article 51A of Part IV-A of the Constitution."],"mnemonics":["USSR - U Should Serve Right (Duties)"],"related":["मौलिक अधिकार (अमेरिका से) / Fundamental Rights (from USA)","नीति निर्देशक तत्व (आयरलैंड से) / Directive Principles (from Ireland)"],"memoryTip":"हमारा पुराना मित्र रूस (USSR) हमें हमारे ''कर्तव्यों'' की याद दिलाता है। (Find polity notes on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('VBOOU54zOsEo8GmsLXkdI', 'k7Me5NZ5nQuJIttTuKhzg', 'किसी राज्य के राज्यपाल (Governor) की नियुक्ति किसके द्वारा की जाती है?', '"[\"1) मुख्यमंत्री / Chief Minister\",\"2) भारत के मुख्य न्यायाधीश / Chief Justice of India\",\"3) प्रधानमंत्री / Prime Minister\",\"4) राष्ट्रपति / President\"]"', '4', NULL, 1, 0, 7, 'General', 'The Governor of a state is appointed by whom?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["अनुच्छेद 155 के अनुसार, किसी राज्य के राज्यपाल की नियुक्ति भारत के राष्ट्रपति द्वारा अपने हस्ताक्षर और मुहर सहित अधिपत्र द्वारा की जाती है।","राज्यपाल राष्ट्रपति के प्रसादपर्यंत (during the pleasure of the President) पद धारण करता है।"],"factsEn":["According to Article 155, the Governor of a state is appointed by the President of India by warrant under his hand and seal.","The Governor holds office during the pleasure of the President."],"mnemonics":["P-G: President appoints Governor"],"related":["अनुच्छेद 153 (प्रत्येक राज्य के लिए एक राज्यपाल) / Article 153 (A Governor for each state)"],"memoryTip":"राज्य का मुखिया (राज्यपाल) देश के मुखिया (राष्ट्रपति) द्वारा चुना जाता है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('cvwyxeqtVAxLwVJz8WMAC', 'k7Me5NZ5nQuJIttTuKhzg', 'भारत के सर्वोच्च न्यायालय (Supreme Court) के मुख्य न्यायाधीश की सेवानिवृत्ति आयु क्या है?', '"[\"1) 60 वर्ष / 60 Years\",\"2) 62 वर्ष / 62 Years\",\"3) 65 वर्ष / 65 Years\",\"4) 70 वर्ष / 70 Years\"]"', '3', NULL, 1, 0, 8, 'General', 'What is the retirement age of the Chief Justice of the Supreme Court of India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भारत के सर्वोच्च न्यायालय (Supreme Court) के न्यायाधीश (मुख्य न्यायाधीश सहित) 65 वर्ष की आयु प्राप्त करने तक पद धारण करते हैं।","उच्च न्यायालय (High Court) के न्यायाधीशों की सेवानिवृत्ति आयु 62 वर्ष होती है।"],"factsEn":["Judges of the Supreme Court of India (including the Chief Justice) hold office until they attain the age of 65 years.","The retirement age for High Court judges is 62 years."],"mnemonics":["SC=65, HC=62"],"related":["नियंत्रक एवं महालेखा परीक्षक (CAG) - 65 वर्ष या 6 साल / CAG - 65 years or 6 years term"],"memoryTip":"सुप्रीम कोर्ट देश की सबसे बड़ी अदालत है, इसलिए उम्र सीमा भी हाई कोर्ट (62) से ज्यादा (65) है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('usdDS_RVV9ypXuzrLxnSu', 'k7Me5NZ5nQuJIttTuKhzg', 'भारत के संविधान का कौन सा अनुच्छेद ''राष्ट्रीय आपातकाल'' (National Emergency) से संबंधित है?', '"[\"1) अनुच्छेद 352 / Article 352\",\"2) अनुच्छेद 356 / Article 356\",\"3) अनुच्छेद 360 / Article 360\",\"4) अनुच्छेद 368 / Article 368\"]"', '1', NULL, 1, 0, 9, 'General', 'Which Article of the Constitution of India deals with ''National Emergency''?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["अनुच्छेद 352 युद्ध, बाहरी आक्रमण या सशस्त्र विद्रोह के आधार पर राष्ट्रीय आपातकाल की घोषणा से संबंधित है।","अनुच्छेद 356 राज्य आपातकाल (राष्ट्रपति शासन) और अनुच्छेद 360 वित्तीय आपातकाल से संबंधित है।"],"factsEn":["Article 352 deals with the proclamation of National Emergency on the grounds of war, external aggression, or armed rebellion.","Article 356 relates to State Emergency (President''s Rule) and Article 360 to Financial Emergency."],"mnemonics":["352 + 4 = 356 + 4 = 360 (National -> State -> Financial)"],"related":["अनुच्छेद 368 (संविधान संशोधन प्रक्रिया) / Article 368 (Amendment procedure of Constitution)"],"memoryTip":"आपातकाल की शुरुआत 352 से होती है, फिर हर 4 जोड़कर अगला आपातकाल आता है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('-ACtTBp49FMipXBjdafYG', 'k7Me5NZ5nQuJIttTuKhzg', 'मध्य प्रदेश उच्च न्यायालय (High Court) की मुख्य पीठ (Headquarters) कहाँ स्थित है?', '"[\"1) भोपाल / Bhopal\",\"2) इंदौर / Indore\",\"3) जबलपुर / Jabalpur\",\"4) ग्वालियर / Gwalior\"]"', '3', NULL, 1, 0, 10, 'General', 'Where is the principal seat (Headquarters) of the Madhya Pradesh High Court located?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["मध्य प्रदेश उच्च न्यायालय की मुख्य पीठ (Principal Seat) जबलपुर में स्थित है। इसकी स्थापना 1956 में हुई थी।","इसकी दो स्थायी खंडपीठ (Benches) ग्वालियर और इंदौर में स्थित हैं, जिनकी स्थापना 1968 में हुई थी।"],"factsEn":["The principal seat of the Madhya Pradesh High Court is located in Jabalpur. It was established in 1956.","It has two permanent benches located in Gwalior and Indore, established in 1968."],"mnemonics":["HC in JBP"],"related":["राजधानी भोपाल में कोई पीठ नहीं है / No bench in the capital Bhopal"],"memoryTip":"मध्य प्रदेश का ''न्याय'' (Court) राजधानी में नहीं, बल्कि ''जबलपुर'' में होता है। (Revise MP GK on mppsc.zenscroll.app)"}}', 'mppolice');
