INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Ym2kQR1IuV9fjW3CRmPuY', 'c3Gq134HNmx-iLu62-nff', 'कलम : लिखना :: चाकू : ? / Pen : Writing :: Knife : ?', '"[\"1) काटना / Cutting\",\"2) दौड़ना / Running\",\"3) पढ़ना / Reading\",\"4) बोलना / Speaking\"]"', '1', NULL, 1, 0, 1, 'General', 'Pen : Writing :: Knife : ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["यह सादृश्य (Analogy) का प्रश्न है।","कलम का कार्य लिखना है, उसी प्रकार चाकू का कार्य काटना है।"],"factsEn":["This is an Analogy question.","A pen is used for writing, similarly a knife is used for cutting."],"mnemonics":["वस्तु = उसका काम।"],"related":["Analogy","कार्य संबंध"],"memoryTip":"जोड़ी में वस्तु देखकर उसका मुख्य उपयोग सोचें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('yb3JPjUFkPOabkW4ZrD1f', 'c3Gq134HNmx-iLu62-nff', 'यदि CAT को DBU लिखा जाए, तो DOG को कैसे लिखा जाएगा? / If CAT is coded as DBU, then how will DOG be coded?', '"[\"1) EPH\",\"2) CNE\",\"3) FQI\",\"4) DPF\"]"', '1', NULL, 1, 0, 2, 'General', 'If CAT is coded as DBU, then how will DOG be coded?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["CAT → DBU में प्रत्येक अक्षर में +1 किया गया है।","D→E, O→P, G→H इसलिए DOG = EPH।"],"factsEn":["In CAT → DBU, each letter is shifted by +1.","D→E, O→P, G→H so DOG = EPH."],"mnemonics":["+1 coding rule."],"related":["Coding-Decoding","Alphabet shift"],"memoryTip":"अगर हर अक्षर अगला बन रहा हो तो +1 नियम देखें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ytDkPPvJDfWzGrfKYfFE5', 'c3Gq134HNmx-iLu62-nff', 'निम्न में से भिन्न शब्द चुनिए / Choose the odd one out', '"[\"1) आम / Mango\",\"2) केला / Banana\",\"3) सेब / Apple\",\"4) गाजर / Carrot\"]"', '4', NULL, 1, 0, 3, 'General', 'Choose the odd one out', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["आम, केला, सेब फल हैं।","गाजर सब्जी है, इसलिए भिन्न है।"],"factsEn":["Mango, Banana and Apple are fruits.","Carrot is a vegetable, so it is odd one out."],"mnemonics":["3 एक समूह, 1 अलग।"],"related":["Classification","Odd one out"],"memoryTip":"पहले common category पहचानें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('dPAuiaKYUweA4O3ea56Sj', 'c3Gq134HNmx-iLu62-nff', 'सभी बिल्ली जानवर हैं। कुछ जानवर काले हैं। निष्कर्ष: कुछ बिल्लियाँ काली हैं। / All cats are animals. Some animals are black. Conclusion: Some cats are black.', '"[\"1) निष्कर्ष अनुसरण नहीं करता / Does not follow\",\"2) निष्कर्ष अनुसरण करता है / Follows\",\"3) संभवतः सही / Possibly true\",\"4) दोनों / Both\"]"', '1', NULL, 1, 0, 4, 'General', 'All cats are animals. Some animals are black. Conclusion: Some cats are black.', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कुछ जानवर काले हैं, पर वे बिल्ली हों यह निश्चित नहीं।","अतः निष्कर्ष निश्चित रूप से अनुसरण नहीं करता।"],"factsEn":["Some animals are black, but they need not be cats.","Hence the conclusion does not definitely follow."],"mnemonics":["Some animal ≠ Some cat."],"related":["Syllogism","Conclusion logic"],"memoryTip":"कुछ से सीधे specific group conclude न करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('yK0JbfvmCIhyBh6i6rlr2', 'c3Gq134HNmx-iLu62-nff', 'राम मोहन से लंबा है। मोहन सोहन से लंबा है। सबसे छोटा कौन है? / Ram is taller than Mohan. Mohan is taller than Sohan. Who is shortest?', '"[\"1) सोहन / Sohan\",\"2) राम / Ram\",\"3) मोहन / Mohan\",\"4) तय नहीं / Cannot be determined\"]"', '1', NULL, 1, 0, 5, 'General', 'Ram is taller than Mohan. Mohan is taller than Sohan. Who is shortest?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["क्रम होगा: राम > मोहन > सोहन","अतः सबसे छोटा सोहन है।"],"factsEn":["Order is Ram > Mohan > Sohan.","Hence Sohan is the shortest."],"mnemonics":["बड़ा > मध्यम > छोटा।"],"related":["Ranking","Comparison"],"memoryTip":"Statements को क्रम में लिखें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9weMRxF-UkRtKLg5K2Fbt', 'c3Gq134HNmx-iLu62-nff', 'यदि SOUTH को HTUOS लिखा जाए, तो NORTH को कैसे लिखा जाएगा? / If SOUTH is written as HTUOS, then how will NORTH be written?', '"[\"1) HTRON\",\"2) NORHT\",\"3) TROHN\",\"4) HNORT\"]"', '1', NULL, 1, 0, 6, 'General', 'If SOUTH is written as HTUOS, then how will NORTH be written?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["SOUTH को उल्टा लिखकर HTUOS बना है।","इसी प्रकार NORTH उल्टा = HTRON।"],"factsEn":["SOUTH is reversed to form HTUOS.","Similarly NORTH reversed = HTRON."],"mnemonics":["Code = Reverse trick."],"related":["Coding-Decoding","Reverse pattern"],"memoryTip":"शब्द coding में reverse rule अक्सर आता है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Ri42eEngzhh_NkulsRVgO', 'c3Gq134HNmx-iLu62-nff', 'सुबह : नाश्ता :: रात : ? / Morning : Breakfast :: Night : ?', '"[\"1) रात्रिभोज / Dinner\",\"2) चाय / Tea\",\"3) खेल / Game\",\"4) स्कूल / School\"]"', '1', NULL, 1, 0, 7, 'General', 'Morning : Breakfast :: Night : ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["सुबह का भोजन नाश्ता है।","रात का भोजन रात्रिभोज (Dinner) है।"],"factsEn":["Breakfast is associated with morning.","Dinner is associated with night."],"mnemonics":["समय = भोजन।"],"related":["Analogy","Time relation"],"memoryTip":"दिन के समय से जुड़ी सामान्य गतिविधि सोचें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9LY2AfGL7oT1YrADv-eVl', 'c3Gq134HNmx-iLu62-nff', 'यदि किसी पंक्ति में रीना बाएँ से 12वीं और दाएँ से 9वीं है, तो कुल व्यक्ति कितने हैं? / If Reena is 12th from left and 9th from right in a row, total persons are?', '"[\"1) 20\",\"2) 21\",\"3) 19\",\"4) 18\"]"', '1', NULL, 1, 0, 8, 'General', 'If Reena is 12th from left and 9th from right in a row, total persons are?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कुल = बाएँ क्रम + दाएँ क्रम - 1","12 + 9 - 1 = 20"],"factsEn":["Total = Left rank + Right rank - 1","12 + 9 - 1 = 20"],"mnemonics":["L + R - 1"],"related":["Ranking","Row arrangement"],"memoryTip":"एक व्यक्ति दोनों तरफ गिना गया, इसलिए -1 करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Tkjlc0Zpdb1jg0kUaPKoV', 'c3Gq134HNmx-iLu62-nff', 'सभी फूल पौधे हैं। सभी पौधे जीवित हैं। निष्कर्ष: सभी फूल जीवित हैं। / All flowers are plants. All plants are living. Conclusion: All flowers are living.', '"[\"1) निष्कर्ष अनुसरण करता है / Follows\",\"2) अनुसरण नहीं करता / Does not follow\",\"3) संभवतः / Possibly\",\"4) कोई नहीं / None\"]"', '1', NULL, 1, 0, 9, 'General', 'All flowers are plants. All plants are living. Conclusion: All flowers are living.', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["Flowers ⊂ Plants और Plants ⊂ Living","अतः Flowers ⊂ Living"],"factsEn":["Flowers ⊂ Plants and Plants ⊂ Living.","Therefore Flowers ⊂ Living."],"mnemonics":["All-All = Chain true."],"related":["Syllogism","Set relation"],"memoryTip":"All A are B, All B are C ⇒ All A are C."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('bNoRVyoMPtnujuHzi-ruv', 'c3Gq134HNmx-iLu62-nff', 'पुस्तक : लेखक :: चित्र : ? / Book : Author :: Painting : ?', '"[\"1) चित्रकार / Painter\",\"2) पाठक / Reader\",\"3) व्यापारी / Trader\",\"4) शिक्षक / Teacher\"]"', '1', NULL, 1, 0, 10, 'General', 'Book : Author :: Painting : ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पुस्तक को लेखक बनाता है।","चित्र को चित्रकार बनाता है।"],"factsEn":["A book is created by an author.","A painting is created by a painter."],"mnemonics":["वस्तु = निर्माता।"],"related":["Analogy","Creator relation"],"memoryTip":"जो चीज बनाता है, वही उत्तर होगा।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Sp8HSMuBMEOeNoJFfLCKc', '_w_g1s1RjInkHs-tCW2WT', 'यदि CAT को DBU लिखा जाए, तो DOG को कैसे लिखा जाएगा? / If CAT is coded as DBU, then how will DOG be coded?', '"[\"1) EPH\",\"2) DNF\",\"3) FQI\",\"4) COG\"]"', '1', NULL, 1, 0, 1, 'General', 'If CAT is coded as DBU, then how will DOG be coded?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["CAT → DBU में प्रत्येक अक्षर एक स्थान आगे बढ़ाया गया है।","D→E, O→P, G→H इसलिए DOG = EPH।"],"factsEn":["In CAT → DBU, each letter is shifted by +1.","D→E, O→P, G→H therefore DOG = EPH."],"mnemonics":["+1 Alphabet Shift"],"related":["Letter coding","Alphabet series"],"memoryTip":"हर अक्षर अगला बन रहा हो तो +1 नियम लगाएं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('yCT_EiaZ7Pe88a5IhQNYW', '_w_g1s1RjInkHs-tCW2WT', 'यदि PEN को QFO लिखा जाए, तो BOOK को कैसे लिखा जाएगा? / If PEN is coded as QFO, then how will BOOK be coded?', '"[\"1) CPPL\",\"2) CQQM\",\"3) APPL\",\"4) DPPM\"]"', '1', NULL, 1, 0, 2, 'General', 'If PEN is coded as QFO, then how will BOOK be coded?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["P→Q, E→F, N→O यानी प्रत्येक अक्षर +1।","B→C, O→P, O→P, K→L इसलिए BOOK = CPPL।"],"factsEn":["P→Q, E→F, N→O means each letter +1.","B→C, O→P, O→P, K→L so BOOK = CPPL."],"mnemonics":["सबमें +1"],"related":["Basic coding","Letter shift"],"memoryTip":"पहले sample word में shift check करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('yWjg62Dc2YYkvfW4imBnZ', '_w_g1s1RjInkHs-tCW2WT', 'यदि SOUTH को HTUOS लिखा जाए, तो NORTH को कैसे लिखा जाएगा? / If SOUTH is written as HTUOS, then how will NORTH be written?', '"[\"1) HTRON\",\"2) TROHN\",\"3) NORHT\",\"4) HNORT\"]"', '1', NULL, 1, 0, 3, 'General', 'If SOUTH is written as HTUOS, then how will NORTH be written?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["SOUTH को उल्टा लिखकर HTUOS बना है।","NORTH उल्टा = HTRON।"],"factsEn":["SOUTH is reversed to HTUOS.","NORTH reversed = HTRON."],"mnemonics":["Reverse Code"],"related":["Reverse pattern","Word coding"],"memoryTip":"यदि अक्षर वही हों, क्रम उल्टा देखें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('UJCtYPaCVP6GqsqmHluPn', '_w_g1s1RjInkHs-tCW2WT', 'यदि 123 = ABC, तो 254 का कोड क्या होगा? / If 123 = ABC, then what is the code of 254?', '"[\"1) BED\",\"2) BCE\",\"3) BDE\",\"4) CED\"]"', '1', NULL, 1, 0, 4, 'General', 'If 123 = ABC, then what is the code of 254?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["1=A, 2=B, 3=C के अनुसार क्रम चलता है।","2=B, 5=E, 4=D इसलिए 254 = BED।"],"factsEn":["Following 1=A, 2=B, 3=C pattern.","2=B, 5=E, 4=D hence 254 = BED."],"mnemonics":["1=A rule"],"related":["Number coding","Alphabet position"],"memoryTip":"संख्या को alphabet position से जोड़ें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('WZADXTVDgvD1gBAyqKXod', '_w_g1s1RjInkHs-tCW2WT', 'यदि APPLE को BQQMF लिखा जाए, तो MANGO को कैसे लिखा जाएगा? / If APPLE is coded as BQQMF, then how will MANGO be coded?', '"[\"1) NBOHP\",\"2) MBNHP\",\"3) OCPIQ\",\"4) NCPGO\"]"', '1', NULL, 1, 0, 5, 'General', 'If APPLE is coded as BQQMF, then how will MANGO be coded?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["APPLE में हर अक्षर +1 होकर BQQMF बना है।","M→N, A→B, N→O, G→H, O→P इसलिए NBOHP।"],"factsEn":["APPLE becomes BQQMF by +1 each letter.","M→N, A→B, N→O, G→H, O→P hence NBOHP."],"mnemonics":["+1 each letter"],"related":["Letter shift","Word coding"],"memoryTip":"Repeated letters भी same rule follow करते हैं।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ytcO_bekYGyIBNp9aD7-R', '_w_g1s1RjInkHs-tCW2WT', 'यदि BAD को 214 लिखा जाए, तो CAB को कैसे लिखा जाएगा? / If BAD is coded as 214, then how will CAB be coded?', '"[\"1) 312\",\"2) 321\",\"3) 231\",\"4) 123\"]"', '1', NULL, 1, 0, 6, 'General', 'If BAD is coded as 214, then how will CAB be coded?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["B=2, A=1, D=4 इसलिए BAD = 214।","C=3, A=1, B=2 इसलिए CAB = 312।"],"factsEn":["B=2, A=1, D=4 so BAD = 214.","C=3, A=1, B=2 so CAB = 312."],"mnemonics":["Alphabet Number"],"related":["Direct coding","Positions"],"memoryTip":"A=1, B=2, C=3 याद रखें।"}}', 'mppolice');
