INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('78_CiLM3mwcyntXKwPyfJ', '_w_g1s1RjInkHs-tCW2WT', 'यदि TRAIN को WUDLQ लिखा जाए, तो यह किस नियम पर आधारित है? / If TRAIN is coded as WUDLQ, which rule is used?', '"[\"1) प्रत्येक अक्षर +3 / Each letter +3\",\"2) प्रत्येक अक्षर +1 / Each letter +1\",\"3) उल्टा क्रम / Reverse order\",\"4) प्रत्येक अक्षर -1 / Each letter -1\"]"', '1', NULL, 1, 0, 9, 'General', 'If TRAIN is coded as WUDLQ, which rule is used?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["T→W, R→U, A→D, I→L, N→Q","सभी अक्षरों में +3 shift है।"],"factsEn":["T→W, R→U, A→D, I→L, N→Q","All letters are shifted by +3."],"mnemonics":["+3 Jump"],"related":["Rule identification","Coding pattern"],"memoryTip":"पहले दो अक्षर देखकर shift पहचानें।"}}', 'mppolice');
