INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ccYcXv4VMbYdt-laAIafC', 'eaYibZV3grSslBxbhvxH1', 'भारत की राजधानी क्या है? / What is the capital of India?', '"[\"1) नई दिल्ली / New Delhi\",\"2) मुंबई / Mumbai\",\"3) कोलकाता / Kolkata\",\"4) चेन्नई / Chennai\"]"', '1', NULL, 1, 0, 1, 'General', 'What is the capital of India?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भारत की राजधानी नई दिल्ली है।","नई दिल्ली भारत का प्रशासनिक केंद्र है।"],"factsEn":["New Delhi is the capital of India.","New Delhi is the administrative center of India."],"mnemonics":["India = New Delhi."],"related":["भारत","संसद भवन"],"memoryTip":"India पूछे तो New Delhi याद करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('FinO868aVj8XV5J1Rg_aX', 'eaYibZV3grSslBxbhvxH1', 'जापान की राजधानी क्या है? / What is the capital of Japan?', '"[\"1) टोक्यो / Tokyo\",\"2) ओसाका / Osaka\",\"3) नागोया / Nagoya\",\"4) क्योटो / Kyoto\"]"', '1', NULL, 1, 0, 2, 'General', 'What is the capital of Japan?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["जापान की राजधानी टोक्यो है।","टोक्यो विश्व के प्रमुख महानगरों में गिना जाता है।"],"factsEn":["Tokyo is the capital of Japan.","Tokyo is one of the major metropolitan cities of the world."],"mnemonics":["Japan jumps to Tokyo."],"related":["एशिया","जापान"],"memoryTip":"Japan = Tokyo."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('uq-1VPD8UcuJaGFD18Wv_', 'eaYibZV3grSslBxbhvxH1', 'चीन की राजधानी क्या है? / What is the capital of China?', '"[\"1) बीजिंग / Beijing\",\"2) शंघाई / Shanghai\",\"3) वुहान / Wuhan\",\"4) ग्वांगझू / Guangzhou\"]"', '1', NULL, 1, 0, 3, 'General', 'What is the capital of China?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["चीन की राजधानी बीजिंग है।","बीजिंग चीन का राजनीतिक केंद्र है।"],"factsEn":["Beijing is the capital of China.","Beijing is the political center of China."],"mnemonics":["China chooses Beijing."],"related":["चीन","एशिया"],"memoryTip":"China = Beijing."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1wJgCao2DpbEfGs178Qmc', 'eaYibZV3grSslBxbhvxH1', 'संयुक्त राज्य अमेरिका (USA) की राजधानी क्या है? / What is the capital of USA?', '"[\"1) वॉशिंगटन डी.सी. / Washington D.C.\",\"2) न्यूयॉर्क / New York\",\"3) लॉस एंजेलिस / Los Angeles\",\"4) शिकागो / Chicago\"]"', '1', NULL, 1, 0, 4, 'General', 'What is the capital of USA?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["USA की राजधानी वॉशिंगटन डी.सी. है।","न्यूयॉर्क बड़ा शहर है, राजधानी नहीं।"],"factsEn":["Washington D.C. is the capital of USA.","New York is a major city, not the capital."],"mnemonics":["USA rules from Washington."],"related":["White House","अमेरिका"],"memoryTip":"Trap: USA = Washington D.C., not New York."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('BDsR5uOEZldOLcHaBIUjN', 'eaYibZV3grSslBxbhvxH1', 'ऑस्ट्रेलिया की राजधानी क्या है? / What is the capital of Australia?', '"[\"1) कैनबरा / Canberra\",\"2) सिडनी / Sydney\",\"3) मेलबर्न / Melbourne\",\"4) पर्थ / Perth\"]"', '1', NULL, 1, 0, 5, 'General', 'What is the capital of Australia?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["ऑस्ट्रेलिया की राजधानी कैनबरा है।","सिडनी सबसे प्रसिद्ध शहर है, राजधानी नहीं।"],"factsEn":["Canberra is the capital of Australia.","Sydney is a famous city, not the capital."],"mnemonics":["Australia = Canberra, not Sydney."],"related":["ओशिआनिया","ऑस्ट्रेलिया"],"memoryTip":"Australia पूछे तो Canberra याद रखें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('N20tznyWSTxMrWePyjLbz', 'eaYibZV3grSslBxbhvxH1', 'कनाडा की राजधानी क्या है? / What is the capital of Canada?', '"[\"1) ओटावा / Ottawa\",\"2) टोरंटो / Toronto\",\"3) वैंकूवर / Vancouver\",\"4) मॉन्ट्रियल / Montreal\"]"', '1', NULL, 1, 0, 6, 'General', 'What is the capital of Canada?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कनाडा की राजधानी ओटावा है।","टोरंटो सबसे बड़ा शहर है, राजधानी नहीं।"],"factsEn":["Ottawa is the capital of Canada.","Toronto is the largest city, not the capital."],"mnemonics":["Canada = Ottawa official."],"related":["उत्तरी अमेरिका","कनाडा"],"memoryTip":"Canada = Ottawa."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('oe8cmzTFzFmR8kNK7PK3j', 'eaYibZV3grSslBxbhvxH1', 'नेपाल की राजधानी क्या है? / What is the capital of Nepal?', '"[\"1) काठमांडू / Kathmandu\",\"2) पोखरा / Pokhara\",\"3) जनकपुर / Janakpur\",\"4) ललितपुर / Lalitpur\"]"', '1', NULL, 1, 0, 7, 'General', 'What is the capital of Nepal?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["नेपाल की राजधानी काठमांडू है।","यह भारत का पड़ोसी देश है।"],"factsEn":["Kathmandu is the capital of Nepal.","Nepal is a neighboring country of India."],"mnemonics":["Nepal climbs Kathmandu."],"related":["नेपाल","भारत के पड़ोसी"],"memoryTip":"Nepal = Kathmandu."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('f7QG_SOe-0Kv-4U3tMVAH', 'eaYibZV3grSslBxbhvxH1', 'पाकिस्तान की राजधानी क्या है? / What is the capital of Pakistan?', '"[\"1) इस्लामाबाद / Islamabad\",\"2) कराची / Karachi\",\"3) लाहौर / Lahore\",\"4) पेशावर / Peshawar\"]"', '1', NULL, 1, 0, 8, 'General', 'What is the capital of Pakistan?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पाकिस्तान की राजधानी इस्लामाबाद है।","कराची बड़ा शहर है, राजधानी नहीं।"],"factsEn":["Islamabad is the capital of Pakistan.","Karachi is a major city, not the capital."],"mnemonics":["Pakistan = Islamabad."],"related":["भारत का पड़ोसी","दक्षिण एशिया"],"memoryTip":"Trap: Karachi नहीं, Islamabad."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('oU7cloiuYm_Z1-v_WRxo3', 'eaYibZV3grSslBxbhvxH1', 'ब्राज़ील की राजधानी क्या है? / What is the capital of Brazil?', '"[\"1) ब्रासीलिया / Brasilia\",\"2) रियो डी जेनेरो / Rio de Janeiro\",\"3) साओ पाउलो / Sao Paulo\",\"4) साल्वाडोर / Salvador\"]"', '1', NULL, 1, 0, 9, 'General', 'What is the capital of Brazil?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["ब्राज़ील की राजधानी ब्रासीलिया है।","रियो डी जेनेरो पूर्व राजधानी थी।"],"factsEn":["Brasilia is the capital of Brazil.","Rio de Janeiro was the former capital."],"mnemonics":["Brazil = Brasilia same sound."],"related":["दक्षिण अमेरिका","ब्राज़ील"],"memoryTip":"Brazil = Brasilia, not Rio."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('IR1-AmLp8qudTOn6a_a31', 'eaYibZV3grSslBxbhvxH1', 'निम्न में से कौन-सा युग्म सही सुमेलित है? / Which of the following pair is correctly matched?', '"[\"1) श्रीलंका - श्री जयवर्धनेपुरा कोट्टे / Sri Lanka - Sri Jayawardenepura Kotte\",\"2) फ्रांस - मार्से / France - Marseille\",\"3) जर्मनी - म्यूनिख / Germany - Munich\",\"4) इटली - मिलान / Italy - Milan\"]"', '1', NULL, 1, 0, 10, 'General', 'Which of the following pair is correctly matched?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["श्रीलंका की आधिकारिक राजधानी श्री जयवर्धनेपुरा कोट्टे है।","फ्रांस की राजधानी पेरिस, जर्मनी की बर्लिन, इटली की रोम है।"],"factsEn":["Sri Jayawardenepura Kotte is the official capital of Sri Lanka.","Paris is the capital of France, Berlin of Germany, and Rome of Italy."],"mnemonics":["Sri Lanka = Kotte tricky capital."],"related":["Unusual capitals","Trap MCQ"],"memoryTip":"अलग capitals अलग से revise करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('YxFY0L3zOz28No_QvKd9Q', 'aCNjN9Fa18jdv7KfyN0YE', 'अभिकथन (A): नर्मदा नदी पूर्व से पश्चिम की ओर बहती है। कारण (R): यह एक भ्रंश घाटी (Rift Valley) में बहती है। दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[\"1) A और R दोनों सत्य हैं तथा R, A का सही स्पष्टीकरण है / Both A and R are true and R is the correct explanation of A\",\"2) A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है / Both A and R are true but R is NOT the correct explanation of A\",\"3) A सत्य है लेकिन R असत्य है / A is true but R is false\",\"4) A असत्य है लेकिन R सत्य है / A is false but R is true\"]"', '1', NULL, 1, 0, 1, 'General', 'Assertion (A): Narmada river flows from east to west. Reason (R): It flows in a rift valley. Choose the correct answer using the codes given:', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["नर्मदा और ताप्ती भारत की प्रमुख नदियां हैं जो पूर्व से पश्चिम की ओर बहती हैं।","इनके इस दिशा में बहने का मुख्य कारण विंध्य और सतपुड़ा पर्वतमाला के बीच एक भ्रंश घाटी (Rift Valley) का होना है।"],"factsEn":["Narmada and Tapti are the major rivers of India that flow from east to west.","The main reason for their flow in this direction is the presence of a rift valley between the Vindhya and Satpura ranges."],"mnemonics":["N-T-R: Narmada Tapti Rift-valley"],"related":["माही नदी भी पश्चिम की ओर बहती है / Mahi river also flows towards the west."],"memoryTip":"नर्मदा भ्रंश (Rift) में बहती है, इसलिए उलटी (पश्चिम) दिशा में जाती है। (Practice more A&R questions on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Jsu1Z9praNTCQYo1UYhOa', 'aCNjN9Fa18jdv7KfyN0YE', 'अभिकथन (A): मानव रक्त लाल रंग का होता है। कारण (R): रक्त में हीमोग्लोबिन नामक वर्णक (Pigment) होता है। दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[\"1) A और R दोनों सत्य हैं तथा R, A का सही स्पष्टीकरण है / Both A and R are true and R is the correct explanation of A\",\"2) A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है / Both A and R are true but R is NOT the correct explanation of A\",\"3) A सत्य है लेकिन R असत्य है / A is true but R is false\",\"4) A असत्य है लेकिन R सत्य है / A is false but R is true\"]"', '1', NULL, 1, 0, 2, 'General', 'Assertion (A): Human blood is red in colour. Reason (R): Blood contains a pigment called Haemoglobin. Choose the correct answer using the codes given:', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["लाल रक्त कोशिकाओं (RBCs) में हीमोग्लोबिन पाया जाता है जो लौह (Iron) युक्त प्रोटीन है।","हीमोग्लोबिन ऑक्सीजन के साथ जुड़कर ऑक्सीहीमोग्लोबिन बनाता है, जो रक्त को उसका विशिष्ट लाल रंग प्रदान करता है।"],"factsEn":["Red Blood Cells (RBCs) contain haemoglobin, which is an iron-containing protein.","Haemoglobin binds with oxygen to form oxyhaemoglobin, giving blood its characteristic red color."],"mnemonics":["Hemo-Glow-Red"],"related":["हीमोसाइनिन (नीला रक्त) कॉपर के कारण होता है / Haemocyanin (blue blood) is due to copper."],"memoryTip":"हीमोग्लोबिन का ''हीम'' (Heme) आयरन है, और लोहे पर जंग लाल होती है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('mSPXl1HzaRfhoAuW3UnN_', 'aCNjN9Fa18jdv7KfyN0YE', 'अभिकथन (A): सांची के महान स्तूप का निर्माण सम्राट अशोक ने करवाया था। कारण (R): सम्राट अशोक जैन धर्म के महान अनुयायी थे। दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[\"1) A और R दोनों सत्य हैं तथा R, A का सही स्पष्टीकरण है / Both A and R are true and R is the correct explanation of A\",\"2) A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है / Both A and R are true but R is NOT the correct explanation of A\",\"3) A सत्य है लेकिन R असत्य है / A is true but R is false\",\"4) A असत्य है लेकिन R सत्य है / A is false but R is true\"]"', '3', NULL, 1, 0, 3, 'General', 'Assertion (A): The Great Stupa at Sanchi was built by Emperor Ashoka. Reason (R): Emperor Ashoka was a great follower of Jainism. Choose the correct answer using the codes given:', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["सांची का स्तूप मध्य प्रदेश के रायसेन जिले में है और इसका निर्माण तीसरी शताब्दी ईसा पूर्व में मौर्य सम्राट अशोक ने करवाया था।","अशोक कलिंग युद्ध के बाद बौद्ध धर्म (Buddhism) के अनुयायी बन गए थे, न कि जैन धर्म के।"],"factsEn":["The Sanchi Stupa is in Raisen district of MP and was built by Mauryan Emperor Ashoka in the 3rd century BCE.","Ashoka became a follower of Buddhism after the Kalinga War, not Jainism."],"mnemonics":["Ashoka-Buddhism (A-B)"],"related":["चंद्रगुप्त मौर्य ने जीवन के अंत में जैन धर्म अपनाया था / Chandragupta Maurya adopted Jainism at the end of his life."],"memoryTip":"अशोक ने ''बौद्ध'' स्तूप बनवाए, इसलिए उनका धर्म ''बौद्ध'' था।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2sX4eaF7zqjbKyQSOfXsX', 'aCNjN9Fa18jdv7KfyN0YE', 'अभिकथन (A): हीरा सबसे कठोर प्राकृतिक पदार्थ है। कारण (R): हीरा कार्बन का एक अपरूप (Allotrope) है। दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[\"1) A और R दोनों सत्य हैं तथा R, A का सही स्पष्टीकरण है / Both A and R are true and R is the correct explanation of A\",\"2) A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है / Both A and R are true but R is NOT the correct explanation of A\",\"3) A सत्य है लेकिन R असत्य है / A is true but R is false\",\"4) A असत्य है लेकिन R सत्य है / A is false but R is true\"]"', '2', NULL, 1, 0, 4, 'General', 'Assertion (A): Diamond is the hardest natural substance. Reason (R): Diamond is an allotrope of carbon. Choose the correct answer using the codes given:', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["हीरा और ग्रेफाइट दोनों कार्बन के अपरूप हैं।","हीरा सबसे कठोर इसलिए है क्योंकि इसमें कार्बन परमाणु एक मजबूत 3D टेट्राहेड्रल संरचना (Tetrahedral structure) में मजबूती से बंधे होते हैं, केवल अपरूप होना इसकी कठोरता का कारण नहीं है।"],"factsEn":["Both diamond and graphite are allotropes of carbon.","Diamond is hardest because its carbon atoms are tightly bound in a strong 3D tetrahedral structure; merely being an allotrope is not the reason for its hardness."],"mnemonics":["Diamond 3D Hard"],"related":["ग्रेफाइट एक नरम अपरूप है / Graphite is a soft allotrope."],"memoryTip":"कथन और कारण दोनों सही हैं, लेकिन ''अपरूप'' होना कठोरता की व्याख्या नहीं करता (ग्रेफाइट भी अपरूप है पर नरम है)। (For deeper concepts, use upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('fSLghg28rCmrifBABRUV9', 'aCNjN9Fa18jdv7KfyN0YE', 'अभिकथन (A): कर्क रेखा (Tropic of Cancer) मध्य प्रदेश से होकर गुजरती है। कारण (R): कर्क रेखा भारत को लगभग दो बराबर हिस्सों में बांटती है। दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[\"1) A और R दोनों सत्य हैं तथा R, A का सही स्पष्टीकरण है / Both A and R are true and R is the correct explanation of A\",\"2) A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है / Both A and R are true but R is NOT the correct explanation of A\",\"3) A सत्य है लेकिन R असत्य है / A is true but R is false\",\"4) A असत्य है लेकिन R सत्य है / A is false but R is true\"]"', '2', NULL, 1, 0, 5, 'General', 'Assertion (A): The Tropic of Cancer passes through Madhya Pradesh. Reason (R): The Tropic of Cancer divides India into almost two equal halves. Choose the correct answer using the codes given:', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कर्क रेखा (23.5° N) भारत के 8 राज्यों से गुजरती है, जिसमें मध्य प्रदेश (14 जिलों से) शामिल है।","कर्क रेखा भारत को दो भागों में बांटती है, लेकिन यह इस बात का कारण नहीं है कि वह मध्य प्रदेश से क्यों गुजरती है; यह केवल भौगोलिक स्थिति है।"],"factsEn":["Tropic of Cancer (23.5° N) passes through 8 states in India, including MP (14 districts).","It divides India into two halves, but this is not the reason why it passes through MP; it''s just geographical location."],"mnemonics":["Both facts true, logic disconnected."],"related":["भूमध्य रेखा (Equator - 0°) / Equator (0°)"],"memoryTip":"दोनों बातें सच हैं, लेकिन भारत को दो भागों में बांटना, MP से गुजरने का ''कारण'' (Reason) नहीं है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('u9EU5HvYaNQiboveaKHNI', 'aCNjN9Fa18jdv7KfyN0YE', 'अभिकथन (A): किसी वस्तु का भार भूमध्य रेखा (Equator) की तुलना में ध्रुवों (Poles) पर अधिकतम होता है। कारण (R): गुरुत्वीय त्वरण (g) भूमध्य रेखा पर न्यूनतम और ध्रुवों पर अधिकतम होता है। दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[\"1) A और R दोनों सत्य हैं तथा R, A का सही स्पष्टीकरण है / Both A and R are true and R is the correct explanation of A\",\"2) A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है / Both A and R are true but R is NOT the correct explanation of A\",\"3) A सत्य है लेकिन R असत्य है / A is true but R is false\",\"4) A असत्य है लेकिन R सत्य है / A is false but R is true\"]"', '1', NULL, 1, 0, 6, 'General', 'Assertion (A): The weight of a body is maximum at the poles compared to the equator. Reason (R): Acceleration due to gravity (g) is minimum at the equator and maximum at the poles. Choose the correct answer using the codes given:', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["भार (W) = द्रव्यमान (m) × गुरुत्वीय त्वरण (g)। चूंकि द्रव्यमान स्थिर रहता है, भार ''g'' पर निर्भर करता है।","पृथ्वी के चपटे आकार के कारण, ध्रुवों पर पृथ्वी की त्रिज्या कम होती है, जिससे ध्रुवों पर ''g'' अधिकतम होता है।"],"factsEn":["Weight (W) = mass (m) × gravity (g). Since mass is constant, weight depends on ''g''.","Due to Earth''s oblate shape, the radius is smaller at the poles, making ''g'' maximum at the poles."],"mnemonics":["Pole = Pull (Maximum gravity)"],"related":["पृथ्वी के केंद्र में भार शून्य होता है / Weight at the center of the Earth is zero."],"memoryTip":"ध्रुवों (Poles) पर ''g'' ज्यादा है, इसलिए भार भी ज्यादा है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ZzHglnHGxFcCf9rhgGsWE', 'aCNjN9Fa18jdv7KfyN0YE', 'अभिकथन (A): पौधे हरे रंग के दिखाई देते हैं। कारण (R): पौधे प्रकाश संश्लेषण के दौरान हरे प्रकाश को पूरी तरह से अवशोषित (absorb) कर लेते हैं। दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[\"1) A और R दोनों सत्य हैं तथा R, A का सही स्पष्टीकरण है / Both A and R are true and R is the correct explanation of A\",\"2) A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है / Both A and R are true but R is NOT the correct explanation of A\",\"3) A सत्य है लेकिन R असत्य है / A is true but R is false\",\"4) A असत्य है लेकिन R सत्य है / A is false but R is true\"]"', '3', NULL, 1, 0, 7, 'General', 'Assertion (A): Plants appear green in colour. Reason (R): Plants completely absorb green light during photosynthesis. Choose the correct answer using the codes given:', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पौधों में क्लोरोफिल होता है, जिसके कारण वे हरे दिखते हैं।","कोई भी वस्तु उसी रंग की दिखती है जिस रंग के प्रकाश को वह परावर्तित (reflect) करती है। पौधे लाल और नीले प्रकाश को अवशोषित करते हैं और हरे प्रकाश को परावर्तित करते हैं, अवशोषित नहीं।"],"factsEn":["Plants contain chlorophyll, making them appear green.","An object appears the color of the light it reflects. Plants absorb red and blue light and reflect green light, not absorb it."],"mnemonics":["Reflect = Color you see"],"related":["सबसे अधिक प्रकाश संश्लेषण लाल प्रकाश में होता है / Maximum photosynthesis occurs in red light."],"memoryTip":"जो रंग अवशोषित (absorb) हो गया, वह दिखेगा नहीं। जो टकराकर वापस आया (reflect), वही दिखेगा। (Learn Science tricks at mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sKHs5jWhnSnrYLmJhuD_9', 'aCNjN9Fa18jdv7KfyN0YE', 'अभिकथन (A): पचमढ़ी को ''सतपुड़ा की रानी'' (Queen of Satpura) कहा जाता है। कारण (R): यह मध्य प्रदेश का एक सुंदर हिल स्टेशन है जो सतपुड़ा पर्वतमाला में सबसे ऊंचाई पर स्थित है। दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[\"1) A और R दोनों सत्य हैं तथा R, A का सही स्पष्टीकरण है / Both A and R are true and R is the correct explanation of A\",\"2) A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है / Both A and R are true but R is NOT the correct explanation of A\",\"3) A सत्य है लेकिन R असत्य है / A is true but R is false\",\"4) A असत्य है लेकिन R सत्य है / A is false but R is true\"]"', '1', NULL, 1, 0, 8, 'General', 'Assertion (A): Pachmarhi is known as the ''Queen of Satpura''. Reason (R): It is a beautiful hill station in Madhya Pradesh located at the highest point in the Satpura range. Choose the correct answer using the codes given:', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पचमढ़ी होशंगाबाद (नर्मदापुरम) जिले में है। इसे 1857 में कैप्टन जेम्स फोर्सिथ द्वारा खोजा गया था।","यह सतपुड़ा पर्वतमाला (महादेव पहाड़ियों) में 1,067 मीटर की ऊंचाई पर है, अपनी इसी सुंदरता और ऊंचाई के कारण इसे सतपुड़ा की रानी कहा जाता है।"],"factsEn":["Pachmarhi is in Hoshangabad (Narmadapuram) district. It was discovered by Captain James Forsyth in 1857.","It is at an altitude of 1,067 meters in the Satpura range (Mahadeo hills), and due to its beauty and height, it is called the Queen of Satpura."],"mnemonics":["Pachmarhi-Queen-Satpura"],"related":["धूपगढ़ (मध्य प्रदेश की सबसे ऊँची चोटी) पचमढ़ी में ही स्थित है / Dhoopgarh (highest peak of MP) is located in Pachmarhi."],"memoryTip":"ऊंचाई और सुंदरता ही किसी जगह को ''रानी'' का दर्जा दिलाती है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ZmkhRknfupNJBAa1ef0LR', 'aCNjN9Fa18jdv7KfyN0YE', 'अभिकथन (A): भारत का राष्ट्रपति राज्य का संवैधानिक प्रमुख होता है। कारण (R): प्रधानमंत्री और मंत्रिपरिषद कार्यपालिका के वास्तविक प्रमुख होते हैं। दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[\"1) A और R दोनों सत्य हैं तथा R, A का सही स्पष्टीकरण है / Both A and R are true and R is the correct explanation of A\",\"2) A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है / Both A and R are true but R is NOT the correct explanation of A\",\"3) A सत्य है लेकिन R असत्य है / A is true but R is false\",\"4) A असत्य है लेकिन R सत्य है / A is false but R is true\"]"', '2', NULL, 1, 0, 9, 'General', 'Assertion (A): The President of India is the constitutional head of the state. Reason (R): The Prime Minister and the Council of Ministers are the real head of the executive. Choose the correct answer using the codes given:', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["अनुच्छेद 53 के अनुसार, संघ की कार्यपालिका शक्ति राष्ट्रपति में निहित है (संवैधानिक प्रमुख)।","अनुच्छेद 74 के अनुसार, राष्ट्रपति को सहायता और सलाह देने के लिए प्रधानमंत्री की अध्यक्षता में एक मंत्रिपरिषद होगी (वास्तविक प्रमुख)। दोनों कथन स्वतंत्र रूप से सत्य हैं, लेकिन एक दूसरे का ''कारण'' नहीं हैं।"],"factsEn":["As per Article 53, the executive power of the Union is vested in the President (Constitutional Head).","As per Article 74, there is a Council of Ministers headed by PM to aid and advise the President (Real Head). Both statements are independently true but not a reason for one another."],"mnemonics":["President = Nominal, PM = Real"],"related":["संसदीय प्रणाली (ब्रिटेन से ली गई) / Parliamentary system (taken from Britain)"],"memoryTip":"राष्ट्रपति के संवैधानिक प्रमुख होने का कारण संविधान का अनुच्छेद है, न कि प्रधानमंत्री का वास्तविक प्रमुख होना। (Check detailed polity on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('CY0xXUkLgDFbL9ZMFMDbt', 'aCNjN9Fa18jdv7KfyN0YE', 'अभिकथन (A): खजुराहो के मंदिर अपनी द्रविड़ वास्तुकला शैली के लिए प्रसिद्ध हैं। कारण (R): इन मंदिरों का निर्माण चंदेल राजवंश द्वारा 950-1050 ईस्वी के बीच किया गया था। दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:', '"[\"1) A और R दोनों सत्य हैं तथा R, A का सही स्पष्टीकरण है / Both A and R are true and R is the correct explanation of A\",\"2) A और R दोनों सत्य हैं लेकिन R, A का सही स्पष्टीकरण नहीं है / Both A and R are true but R is NOT the correct explanation of A\",\"3) A सत्य है लेकिन R असत्य है / A is true but R is false\",\"4) A असत्य है लेकिन R सत्य है / A is false but R is true\"]"', '4', NULL, 1, 0, 10, 'General', 'Assertion (A): Khajuraho temples are famous for their Dravidian architecture style. Reason (R): These temples were built by the Chandela dynasty between 950-1050 AD. Choose the correct answer using the codes given:', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["खजुराहो के मंदिर ''नागर शैली'' (Nagara style) की वास्तुकला का एक उत्कृष्ट उदाहरण हैं, द्रविड़ शैली का नहीं। (द्रविड़ शैली दक्षिण भारत के मंदिरों में पाई जाती है)।","कारण (R) बिल्कुल सत्य है कि इन्हें चंदेल शासकों ने बनवाया था।"],"factsEn":["Khajuraho temples are an excellent example of ''Nagara style'' architecture, not Dravidian style. (Dravidian style is found in South Indian temples).","Reason (R) is completely true that they were built by Chandela rulers."],"mnemonics":["North-Nagara, South-Dravida"],"related":["कंदरिया महादेव मंदिर (खजुराहो का सबसे प्रसिद्ध मंदिर) / Kandariya Mahadeva Temple (most famous temple of Khajuraho)"],"memoryTip":"खजुराहो उत्तर/मध्य भारत में है, इसलिए यहाँ नागर (Nagara) शैली है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('U7cgcvQOdPeNAbZvjAnOD', 'GDjCxZCSv96Dc_-VwEs5W', 'एक किसान के पास कुछ मुर्गियां और कुछ भेड़ें हैं। यदि सिरों की कुल संख्या 40 है और पैरों की कुल संख्या 120 है, तो किसान के पास कितनी भेड़ें हैं?', '"[\"1) 10\",\"2) 20\",\"3) 25\",\"4) 30\"]"', '2', NULL, 1, 0, 1, 'General', 'A farmer has some hens and some sheep. If the total number of heads is 40 and the total number of legs is 120, how many sheep does the farmer have?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["मुर्गी के 2 पैर होते हैं और भेड़ के 4 पैर होते हैं। दोनों का 1-1 सिर होता है।","माना मुर्गियों की संख्या H और भेड़ों की संख्या S है। H + S = 40 (सिर)।","2H + 4S = 120 (पैर)। पहले समीकरण को 2 से गुणा करने पर 2H + 2S = 80। इसे दूसरे से घटाने पर 2S = 40, यानी S = 20।"],"factsEn":["A hen has 2 legs and a sheep has 4 legs. Both have 1 head each.","Let the number of hens be H and sheep be S. H + S = 40 (heads).","2H + 4S = 120 (legs). Multiplying the first equation by 2 gives 2H + 2S = 80. Subtracting this from the second gives 2S = 40, so S = 20."],"mnemonics":["Trick: (Total Legs / 2) - Total Heads = Number of 4-legged animals"],"related":["इसी तरह के प्रश्न गायों और बत्तखों पर भी पूछे जाते हैं। / Similar questions are asked on cows and ducks."],"memoryTip":"शॉर्टकट सूत्र: (120/2) - 40 = 60 - 40 = 20 (चार पैरों वाले जानवर)। (Visit mppsc.zenscroll.app for more VYAPAM tricks)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0LctjfcK4PhJVAFlfZwrx', 'GDjCxZCSv96Dc_-VwEs5W', 'यदि ''+'' का अर्थ ''भाग'' है, ''-'' का अर्थ ''गुणा'' है, ''×'' का अर्थ ''जोड़'' है, और ''÷'' का अर्थ ''घटाना'' है, तो 20 + 5 - 4 × 8 ÷ 2 का मान क्या होगा?', '"[\"1) 18\",\"2) 22\",\"3) 24\",\"4) 26\"]"', '2', NULL, 1, 0, 2, 'General', 'If ''+'' means ''divide'', ''-'' means ''multiply'', ''×'' means ''add'', and ''÷'' means ''subtract'', then what will be the value of 20 + 5 - 4 × 8 ÷ 2?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["चिह्नों को बदलने पर नया समीकरण होगा: 20 ÷ 5 × 4 + 8 - 2","BODMAS नियम के अनुसार, सबसे पहले भाग (Divide) करें: 20 ÷ 5 = 4। नया समीकरण: 4 × 4 + 8 - 2","फिर गुणा (Multiply) करें: 4 × 4 = 16। अब जोड़ें (Add): 16 + 8 = 24। अंत में घटाएं (Subtract): 24 - 2 = 22।"],"factsEn":["Changing the signs gives the new equation: 20 ÷ 5 × 4 + 8 - 2","According to the BODMAS rule, divide first: 20 ÷ 5 = 4. New equation: 4 × 4 + 8 - 2","Then multiply: 4 × 4 = 16. Now add: 16 + 8 = 24. Finally, subtract: 24 - 2 = 22."],"mnemonics":["BODMAS: Bracket, Order, Divide, Multiply, Add, Subtract"],"related":["चिह्न प्रतिस्थापन के प्रश्न पुलिस कांस्टेबल परीक्षा में बहुत आम हैं। / Sign substitution questions are very common in the Police Constable exam."],"memoryTip":"गणितीय संक्रियाओं (Mathematical operations) में हमेशा ''BODMAS'' का सख्ती से पालन करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('IR7ZlRVeh3qHiZDOv_YUw', 'GDjCxZCSv96Dc_-VwEs5W', 'एक पार्टी में 10 लोग मौजूद हैं। यदि हर व्यक्ति एक-दूसरे से ठीक एक बार हाथ मिलाता है, तो कुल कितनी बार हाथ मिलाए जाएंगे?', '"[\"1) 45\",\"2) 50\",\"3) 90\",\"4) 100\"]"', '1', NULL, 1, 0, 3, 'General', 'There are 10 people present in a party. If every person shakes hands with each other exactly once, what is the total number of handshakes?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["हाथ मिलाने (Handshakes) की कुल संख्या ज्ञात करने का सूत्र n(n - 1) / 2 है।","जहाँ n व्यक्तियों की कुल संख्या है। यहाँ n = 10 है।","इसलिए, कुल हाथ मिलाना = 10 × (10 - 1) / 2 = (10 × 9) / 2 = 90 / 2 = 45।"],"factsEn":["The formula to find the total number of handshakes is n(n - 1) / 2.","Where n is the total number of persons. Here n = 10.","Therefore, total handshakes = 10 × (10 - 1) / 2 = (10 × 9) / 2 = 90 / 2 = 45."],"mnemonics":["Handshake Formula: n(n-1)/2"],"related":["यदि लोग एक-दूसरे को उपहार (Gifts) देते हैं, तो सूत्र n(n - 1) होता है। / If people give gifts to each other, the formula is n(n - 1)."],"memoryTip":"हाथ मिलाने में 2 लोग शामिल होते हैं, इसलिए n(n-1) को 2 से भाग दिया जाता है। (Find complete math syllabus on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('NW2gZHwEfGKmRnr7ssmkv', 'GDjCxZCSv96Dc_-VwEs5W', 'एक बंदर 60 फीट ऊंचे खंभे पर चढ़ने का प्रयास करता है। वह एक मिनट में 3 फीट चढ़ता है और अगले मिनट में 2 फीट फिसल जाता है। उसे खंभे के शीर्ष पर पहुंचने में कितना समय (मिनटों में) लगेगा?', '"[\"1) 115\",\"2) 117\",\"3) 118\",\"4) 120\"]"', '1', NULL, 1, 0, 4, 'General', 'A monkey tries to climb a 60 feet high pole. He climbs 3 feet in one minute and slips down 2 feet in the next minute. How much time (in minutes) will he take to reach the top of the pole?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["बंदर 2 मिनट में 1 फीट (3 फीट चढ़ना - 2 फीट फिसलना) की शुद्ध ऊंचाई तय करता है।","बंदर को शीर्ष से ठीक पहले 57 फीट तक पहुंचने में 57 × 2 = 114 मिनट लगेंगे।","115वें मिनट में, वह 3 फीट छलांग लगाएगा और 60 फीट (शीर्ष) पर पहुंच जाएगा, और फिर नहीं फिसलेगा।"],"factsEn":["The monkey covers a net height of 1 foot (climbing 3 ft - slipping 2 ft) in 2 minutes.","The monkey will take 57 × 2 = 114 minutes to reach 57 feet just before the top.","In the 115th minute, he will jump 3 feet and reach 60 feet (the top), and will not slip again."],"mnemonics":["Last Jump Trick: Total - Climb = Base. Find time for base, then add 1."],"related":["ऐसे प्रश्न मेढक के कुएं से बाहर आने वाले पैटर्न पर भी पूछे जाते हैं। / Such questions are also asked on the frog coming out of the well pattern."],"memoryTip":"अंतिम छलांग को हमेशा अलग से गिनें क्योंकि शीर्ष पर पहुंचने के बाद फिसलने का सवाल ही नहीं उठता।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('KLMF-ESq14VbcrnHfQKlZ', 'GDjCxZCSv96Dc_-VwEs5W', 'एक पिता की आयु उसके पुत्र की आयु की तीन गुनी है। 10 वर्ष बाद, पिता की आयु पुत्र की आयु की दोगुनी हो जाएगी। पिता की वर्तमान आयु क्या है?', '"[\"1) 30 वर्ष / 30 years\",\"2) 40 वर्ष / 40 years\",\"3) 45 वर्ष / 45 years\",\"4) 50 वर्ष / 50 years\"]"', '1', NULL, 1, 0, 5, 'General', 'The age of a father is three times the age of his son. After 10 years, the father''s age will be twice the age of his son. What is the present age of the father?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["माना पुत्र की वर्तमान आयु x है। तो पिता की वर्तमान आयु 3x होगी।","10 वर्ष बाद, पुत्र की आयु = (x + 10) और पिता की आयु = (3x + 10)।","प्रश्नानुसार, 3x + 10 = 2(x + 10) ⇒ 3x + 10 = 2x + 20 ⇒ x = 10।","अतः, पिता की वर्तमान आयु = 3x = 3 × 10 = 30 वर्ष।"],"factsEn":["Let the present age of the son be x. Then the father''s present age will be 3x.","After 10 years, the son''s age = (x + 10) and the father''s age = (3x + 10).","According to the question, 3x + 10 = 2(x + 10) ⇒ 3x + 10 = 2x + 20 ⇒ x = 10.","Thus, the present age of the father = 3x = 3 × 10 = 30 years."],"mnemonics":["Age Equation: Past(-), Present(x), Future(+)"],"related":["उम्र पर आधारित प्रश्न अनुपात (Ratio) विधि से भी हल किए जा सकते हैं। / Age-based questions can also be solved by the Ratio method."],"memoryTip":"हमेशा छोटे व्यक्ति (पुत्र) की आयु को ''x'' मानें, इससे गुणा और भाग करने में आसानी होती है। (Solve more on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('-ajJ7F7VLvIN3Mh7zdS0t', 'GDjCxZCSv96Dc_-VwEs5W', 'एक कक्षा में, लड़कों की संख्या लड़कियों की संख्या से तिगुनी है। निम्नलिखित में से कौन सी संख्या कक्षा में बच्चों की कुल संख्या का प्रतिनिधित्व नहीं कर सकती है?', '"[\"1) 40\",\"2) 42\",\"3) 44\",\"4) 48\"]"', '2', NULL, 1, 0, 6, 'General', 'In a class, the number of boys is three times the number of girls. Which of the following numbers cannot represent the total number of children in the class?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["माना लड़कियों की संख्या G है। तो लड़कों की संख्या (B) = 3G होगी।","कक्षा में कुल बच्चे = B + G = 3G + G = 4G।","इसका मतलब है कि बच्चों की कुल संख्या 4 का गुणज (multiple) होनी चाहिए। विकल्पों में से केवल 42, 4 से विभाज्य नहीं है।"],"factsEn":["Let the number of girls be G. Then the number of boys (B) will be 3G.","Total children in the class = B + G = 3G + G = 4G.","This means the total number of children must be a multiple of 4. Among the options, only 42 is not divisible by 4."],"mnemonics":["Ratio Sum = Multiple factor"],"related":["अनुपात के योग (3+1=4) से कुल संख्या हमेशा पूरी तरह से विभाजित होनी चाहिए। / The total number must always be perfectly divisible by the sum of the ratio (3+1=4)."],"memoryTip":"चूंकि व्यक्ति (बच्चे) आंशिक (fractional) नहीं हो सकते, इसलिए कुल संख्या हमेशा अनुपात के योग का पूर्णांक गुणज होती है।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('igrS8_BeoeTGk48TTzZar', 'GDjCxZCSv96Dc_-VwEs5W', 'एक बस डिपो से हर 30 मिनट में एक बस दिल्ली के लिए निकलती है। एक पूछताछ क्लर्क ने एक यात्री को बताया कि बस 10 मिनट पहले ही निकल चुकी है और अगली बस सुबह 9:35 बजे निकलेगी। पूछताछ क्लर्क ने यह जानकारी यात्री को किस समय दी थी?', '"[\"1) 9:10 AM\",\"2) 9:15 AM\",\"3) 9:20 AM\",\"4) 9:25 AM\"]"', '2', NULL, 1, 0, 7, 'General', 'A bus leaves for Delhi every 30 minutes from a bus depot. An enquiry clerk told a passenger that the bus had already left 10 minutes ago and the next bus will leave at 9:35 AM. At what time did the enquiry clerk give this information to the passenger?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["अगली बस का समय = 9:35 AM।","चूंकि बसें हर 30 मिनट में निकलती हैं, इसलिए पिछली बस 9:35 AM से 30 मिनट पहले, यानी 9:05 AM पर निकली होगी।","क्लर्क के अनुसार, बस 10 मिनट पहले निकल चुकी है। इसलिए वर्तमान समय 9:05 AM + 10 मिनट = 9:15 AM है।"],"factsEn":["Time of the next bus = 9:35 AM.","Since buses leave every 30 minutes, the previous bus must have left 30 minutes before 9:35 AM, i.e., at 9:05 AM.","According to the clerk, the bus left 10 minutes ago. So the current time is 9:05 AM + 10 minutes = 9:15 AM."],"mnemonics":["Next Bus - Interval + Delay = Current Time"],"related":["इस प्रकार के प्रश्न तार्किक क्षमता (Logical Reasoning) और समय-आधारित गणना दोनों का परीक्षण करते हैं। / Such questions test both logical reasoning and time-based calculation."],"memoryTip":"हमेशा ''अगली बस'' के समय से ''पिछली बस'' का समय निकालें, फिर उसमें देरी (10 मिनट) जोड़ दें। (Practice more on upsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('9UXC4RAgVdtZ_i-1Ap8lD', 'GDjCxZCSv96Dc_-VwEs5W', 'दो संख्याओं का योग 25 है और उनका अंतर 13 है। दोनों संख्याओं का गुणनफल क्या होगा?', '"[\"1) 104\",\"2) 114\",\"3) 124\",\"4) 325\"]"', '2', NULL, 1, 0, 8, 'General', 'The sum of two numbers is 25 and their difference is 13. What will be the product of the two numbers?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["माना दो संख्याएँ x और y हैं।","प्रश्नानुसार: x + y = 25 और x - y = 13।","दोनों समीकरणों को जोड़ने पर: 2x = 38 ⇒ x = 19।","x का मान रखने पर: 19 + y = 25 ⇒ y = 6।","गुणनफल = x × y = 19 × 6 = 114।"],"factsEn":["Let the two numbers be x and y.","According to the question: x + y = 25 and x - y = 13.","Adding both equations: 2x = 38 ⇒ x = 19.","Putting the value of x: 19 + y = 25 ⇒ y = 6.","Product = x × y = 19 × 6 = 114."],"mnemonics":["Larger Number = (Sum + Difference)/2; Smaller Number = (Sum - Difference)/2"],"related":["(x+y)^2 - (x-y)^2 = 4xy सूत्र का उपयोग करके भी हल किया जा सकता है। / Can also be solved using the formula (x+y)^2 - (x-y)^2 = 4xy."],"memoryTip":"बड़ी संख्या = (25+13)/2 = 19। छोटी संख्या = (25-13)/2 = 6। गुणनफल = 114।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Lhx9GmuY2XbQS72FbbUCf', 'GDjCxZCSv96Dc_-VwEs5W', 'लड़कों की एक पंक्ति में, राहुल दोनों सिरों से 15वें स्थान पर है। पंक्ति में कुल कितने लड़के हैं?', '"[\"1) 29\",\"2) 30\",\"3) 31\",\"4) 28\"]"', '1', NULL, 1, 0, 9, 'General', 'In a row of boys, Rahul is 15th from both ends. How many boys are there in the row?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["जब किसी व्यक्ति का स्थान दोनों सिरों (दाएं और बाएं) से दिया गया हो, तो कुल संख्या = (बाएं से स्थान + दाएं से स्थान) - 1।","कुल लड़के = (15 + 15) - 1 = 30 - 1 = 29।"],"factsEn":["When a person''s position is given from both ends (left and right), Total number = (Position from left + Position from right) - 1.","Total boys = (15 + 15) - 1 = 30 - 1 = 29."],"mnemonics":["Total = Left + Right - 1"],"related":["रैंकिंग परीक्षण (Ranking Test) के प्रश्न MP Police परीक्षा का महत्वपूर्ण हिस्सा हैं। / Ranking test questions are an important part of the MP Police exam."],"memoryTip":"-1 इसलिए किया जाता है क्योंकि राहुल की गिनती दोनों तरफ से (दो बार) हो गई है। (Get ranking PDFs on mppsc.zenscroll.app)"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('ZQhCdm41-ZQkEfvyelhc3', 'GDjCxZCSv96Dc_-VwEs5W', 'एक 50 मीटर लंबे कपड़े के रोल से हर दिन 5 मीटर कपड़ा काटा जाता है। यदि कटाई पहले दिन शुरू होती है, तो पूरे रोल को काटने में कितने दिन लगेंगे?', '"[\"1) 10 दिन / 10 days\",\"2) 9 दिन / 9 days\",\"3) 8 दिन / 8 days\",\"4) 11 दिन / 11 days\"]"', '2', NULL, 1, 0, 10, 'General', '5 meters of cloth is cut every day from a 50-meter long roll of cloth. If cutting starts on the first day, how many days will it take to cut the entire roll?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["कपड़े की कुल लंबाई 50 मीटर है। हर दिन 5 मीटर काटा जाता है।","9वें दिन, जब 45 मीटर कपड़ा कट चुका होगा, तो शेष 5 मीटर का टुकड़ा अपने आप अलग हो जाएगा।","इसलिए, 10वें कट (day) की आवश्यकता नहीं होगी।"],"factsEn":["The total length of the cloth is 50 meters. 5 meters is cut every day.","On the 9th day, when 45 meters of cloth has been cut, the remaining 5 meters piece will be separated automatically.","Therefore, the 10th cut (day) will not be required."],"mnemonics":["Last cut separates two pieces."],"related":["यह लकड़ी काटने या रिबन काटने वाले तार्किक (Logical) प्रश्नों के समान है। / This is similar to logical questions about cutting wood or cutting ribbons."],"memoryTip":"अंतिम कट हमेशा दो टुकड़े बनाता है, इसलिए कुल कट्स (या दिन) = (कुल लंबाई / टुकड़े की लंबाई) - 1।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('5wn7EDTYyVxOqnePrqBSM', 'fpcjU-s-bejifhqHd79uh', 'BODMAS नियम के अनुसार 8 + 4 × 2 = ? / According to BODMAS, 8 + 4 × 2 = ?', '"[\"1) 16\",\"2) 24\",\"3) 20\",\"4) 12\"]"', '1', NULL, 1, 0, 1, 'General', 'According to BODMAS, 8 + 4 × 2 = ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पहले गुणा किया जाएगा: 4 × 2 = 8","फिर जोड़: 8 + 8 = 16"],"factsEn":["First multiplication: 4 × 2 = 8","Then addition: 8 + 8 = 16"],"mnemonics":["MDAS: Multiply before Add"],"related":["BODMAS","Simplification"],"memoryTip":"जहाँ × और + साथ हों, पहले × करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('XdUe_5J4R9Y2lgSq_xCVf', 'fpcjU-s-bejifhqHd79uh', '15 - 3 × 4 = ? / 15 - 3 × 4 = ?', '"[\"1) 3\",\"2) 48\",\"3) 12\",\"4) 60\"]"', '1', NULL, 1, 0, 2, 'General', '15 - 3 × 4 = ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पहले 3 × 4 = 12","फिर 15 - 12 = 3"],"factsEn":["First 3 × 4 = 12","Then 15 - 12 = 3"],"mnemonics":["Multiply first"],"related":["Arithmetic operations","BODMAS"],"memoryTip":"Minus से पहले multiply करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('R8qMOW1Yvx87hPmCjHO1m', 'fpcjU-s-bejifhqHd79uh', '(12 + 8) ÷ 4 = ? / (12 + 8) ÷ 4 = ?', '"[\"1) 5\",\"2) 4\",\"3) 20\",\"4) 8\"]"', '1', NULL, 1, 0, 3, 'General', '(12 + 8) ÷ 4 = ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पहले bracket: 12 + 8 = 20","फिर 20 ÷ 4 = 5"],"factsEn":["First bracket: 12 + 8 = 20","Then 20 ÷ 4 = 5"],"mnemonics":["B = Bracket first"],"related":["Division","BODMAS"],"memoryTip":"Bracket हमेशा पहले हल करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('1S2tDoQNYNT68vBnkTy_m', 'fpcjU-s-bejifhqHd79uh', '20 ÷ 5 + 6 = ? / 20 ÷ 5 + 6 = ?', '"[\"1) 10\",\"2) 2\",\"3) 24\",\"4) 11\"]"', '1', NULL, 1, 0, 4, 'General', '20 ÷ 5 + 6 = ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पहले 20 ÷ 5 = 4","फिर 4 + 6 = 10"],"factsEn":["First 20 ÷ 5 = 4","Then 4 + 6 = 10"],"mnemonics":["Division before Addition"],"related":["Basic math","Simplification"],"memoryTip":"÷ पहले, + बाद में।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('yzV-lG6y9SKaMv6PrIJVx', 'fpcjU-s-bejifhqHd79uh', '7 + 3 × (5 - 2) = ? / 7 + 3 × (5 - 2) = ?', '"[\"1) 16\",\"2) 30\",\"3) 10\",\"4) 13\"]"', '1', NULL, 1, 0, 5, 'General', '7 + 3 × (5 - 2) = ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पहले bracket: 5 - 2 = 3","फिर 3 × 3 = 9","फिर 7 + 9 = 16"],"factsEn":["First bracket: 5 - 2 = 3","Then 3 × 3 = 9","Then 7 + 9 = 16"],"mnemonics":["Bracket → Multiply → Add"],"related":["BODMAS","Mixed operations"],"memoryTip":"Bracket के बाद बाकी नियम लगाएँ।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('OCE3JTigDcZtIiFRNrEQF', 'fpcjU-s-bejifhqHd79uh', '18 - 6 ÷ 3 = ? / 18 - 6 ÷ 3 = ?', '"[\"1) 16\",\"2) 4\",\"3) 6\",\"4) 12\"]"', '1', NULL, 1, 0, 6, 'General', '18 - 6 ÷ 3 = ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पहले 6 ÷ 3 = 2","फिर 18 - 2 = 16"],"factsEn":["First 6 ÷ 3 = 2","Then 18 - 2 = 16"],"mnemonics":["Divide then Subtract"],"related":["Division","Subtraction"],"memoryTip":"÷ पहले हल करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('d1vCYkNp9zSQbdZmvcVAu', 'fpcjU-s-bejifhqHd79uh', '9 × 2 - 5 = ? / 9 × 2 - 5 = ?', '"[\"1) 13\",\"2) 18\",\"3) 8\",\"4) 23\"]"', '1', NULL, 1, 0, 7, 'General', '9 × 2 - 5 = ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पहले 9 × 2 = 18","फिर 18 - 5 = 13"],"factsEn":["First 9 × 2 = 18","Then 18 - 5 = 13"],"mnemonics":["× before -"],"related":["Multiplication","Subtraction"],"memoryTip":"Multiply first, then minus."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('0emyGstOchKy48teiE5G4', 'fpcjU-s-bejifhqHd79uh', '(16 ÷ 4) + (3 × 2) = ? / (16 ÷ 4) + (3 × 2) = ?', '"[\"1) 10\",\"2) 24\",\"3) 8\",\"4) 6\"]"', '1', NULL, 1, 0, 8, 'General', '(16 ÷ 4) + (3 × 2) = ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["16 ÷ 4 = 4","3 × 2 = 6","4 + 6 = 10"],"factsEn":["16 ÷ 4 = 4","3 × 2 = 6","4 + 6 = 10"],"mnemonics":["Separate brackets solve"],"related":["Brackets","Mixed operations"],"memoryTip":"हर bracket अलग हल करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('UjApixnDh5wLvqSBC4xxa', 'fpcjU-s-bejifhqHd79uh', '25 - (6 + 4) = ? / 25 - (6 + 4) = ?', '"[\"1) 15\",\"2) 35\",\"3) 23\",\"4) 19\"]"', '1', NULL, 1, 0, 9, 'General', '25 - (6 + 4) = ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["पहले bracket: 6 + 4 = 10","फिर 25 - 10 = 15"],"factsEn":["First bracket: 6 + 4 = 10","Then 25 - 10 = 15"],"mnemonics":["Bracket first always"],"related":["Subtraction","BODMAS"],"memoryTip":"Bracket solve करके बाहर की क्रिया करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('epwxRKhuG97GdC_TxAhD8', 'fpcjU-s-bejifhqHd79uh', '6 + 12 ÷ 3 × 2 = ? / 6 + 12 ÷ 3 × 2 = ?', '"[\"1) 14\",\"2) 18\",\"3) 10\",\"4) 24\"]"', '1', NULL, 1, 0, 10, 'General', '6 + 12 ÷ 3 × 2 = ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["÷ और × को बाएँ से दाएँ हल करें।","12 ÷ 3 = 4, फिर 4 × 2 = 8","फिर 6 + 8 = 14"],"factsEn":["Solve ÷ and × from left to right.","12 ÷ 3 = 4, then 4 × 2 = 8","Then 6 + 8 = 14"],"mnemonics":["DM left to right"],"related":["Order of operations","BODMAS"],"memoryTip":"÷ और × समान priority हैं, left to right करें।"}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('2i4msTeWaK5DG1f34oC4g', '3XarOrhKefRhBtTa-sEXN', 'A, C, E, G, ? / A, C, E, G, ?', '"[\"1) I\",\"2) H\",\"3) J\",\"4) K\"]"', '1', NULL, 1, 0, 1, 'General', 'A, C, E, G, ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["श्रृंखला में प्रत्येक बार 2 अक्षर छोड़कर अगला अक्षर लिया गया है।","A(+2)C(+2)E(+2)G(+2)I"],"factsEn":["Each term advances by skipping one letter (+2 positions).","A(+2)C(+2)E(+2)G(+2)I"],"mnemonics":["Odd letters pattern"],"related":["Alphabet series","Missing letter"],"memoryTip":"A=1 मानकर positions देखें: 1,3,5,7,9."}}', 'mppolice');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('I73vfBs3K8HUeJR69zic2', '3XarOrhKefRhBtTa-sEXN', '2, 4, 8, 16, ? / 2, 4, 8, 16, ?', '"[\"1) 32\",\"2) 24\",\"3) 18\",\"4) 30\"]"', '1', NULL, 1, 0, 2, 'General', '2, 4, 8, 16, ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["हर संख्या पिछली संख्या की दुगुनी है।","2×2=4, 4×2=8, 8×2=16, 16×2=32"],"factsEn":["Each number is double the previous one.","2×2=4, 4×2=8, 8×2=16, 16×2=32"],"mnemonics":["Double pattern"],"related":["Number series","Multiplication"],"memoryTip":"अगर numbers तेजी से बढ़ें तो ×2, ×3 जाँचें।"}}', 'mppolice');
