INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('YU0Um4wPZUlNmNH7by0mN', '3XarOrhKefRhBtTa-sEXN', 'B, E, H, K, ? / B, E, H, K, ?', '"[\"1) N\",\"2) M\",\"3) O\",\"4) P\"]"', '1', NULL, 1, 0, 5, 'General', 'B, E, H, K, ?', NULL, 60, 'standard', NULL, NULL, '{"explanation":{"stream":"gk_science","facts":["हर बार +3 positions बढ़ रही हैं।","B(2), E(5), H(8), K(11), N(14)"],"factsEn":["Each term increases by +3 positions.","B(2), E(5), H(8), K(11), N(14)"],"mnemonics":["+3 alphabet jump"],"related":["Alphabet positions","Pattern"],"memoryTip":"Letters को number positions में बदलें।"}}', 'mppolice');
