INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sxCqrA0zPyDgkKxSkS99h', '96_6JkQybSxCkaseu_zts', 'मध्य प्रदेश विधानसभा के सत्रों के विषय में निम्नलिखित में से कौन-सा कथन असत्य है?', '"[{\"id\":\"A\",\"text\":\"एक वर्ष में विधानसभा के न्यूनतम दो अधिवेशन होने चाहिए।\",\"text_en\":\"There should be a minimum of two sessions of the assembly in a year.\"},{\"id\":\"B\",\"text\":\"दो बैठकों के मध्य छः मास से अधिक का अन्तर नहीं होना चाहिए।\",\"text_en\":\"There should not be a gap of more than six months between two meetings.\"},{\"id\":\"C\",\"text\":\"राज्यपाल विधानसभा के अधिवेशन को बुलाते हैं।\",\"text_en\":\"The Governor summons the session of the legislative assembly.\"},{\"id\":\"D\",\"text\":\"विधानसभा अध्यक्ष विधानसभा के अधिवेशन को समाप्त करते हैं।\",\"text_en\":\"The Speaker of the assembly prorogues the session of the legislative assembly.\"}]"', '3.0', '[object Object]', 3, 1, 19, 'Polity', 'Which of the following statements regarding the sessions of the Madhya Pradesh Legislative Assembly is false?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
