INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('sin2mcIdXBpHgErOdKYwr', '96_6JkQybSxCkaseu_zts', 'जून 2025 में, ग्रुप कैप्टन शुभांशु शुक्ला ने भारत की अंतरिक्ष यात्रा में एक बड़ा मील का पत्थर हासिल करके इतिहास रच दिया। यह ऐतिहासिक उपलब्धि क्या थी?', '"[{\"id\":\"A\",\"text\":\"वह चन्द्रमा पर मानवयुक्त मिशन का नेतृत्व करने वाले पहले भारतीय बने।\",\"text_en\":\"He became the first Indian to lead a manned mission to the Moon.\"},{\"id\":\"B\",\"text\":\"उन्होंने खुले अंतरिक्ष में पहली भारतीय स्पेस वॉक सफलतापूर्वक पूरी की।\",\"text_en\":\"He successfully completed the first Indian spacewalk in open space.\"},{\"id\":\"C\",\"text\":\"वह अंतर्राष्ट्रीय अंतरिक्ष स्टेशन (ISS) पर कदम रखने वाले पहले भारतीय बने और मिशन पायलट के रूप में कार्य किया।\",\"text_en\":\"He became the first Indian to step on the International Space Station (ISS) and served as mission pilot.\"},{\"id\":\"D\",\"text\":\"वह मंगल ग्रह पर अंतरिक्ष यान ले जाने वाले पहले भारतीय बने।\",\"text_en\":\"He became the first Indian to take a spacecraft to Mars.\"}]"', '2.0', '[object Object]', 3, 1, 28, 'Current Affairs', 'In June 2025, Group Captain Shubhanshu Shukla created history by achieving a major milestone in India''s space journey. What was this historic achievement?', NULL, 45, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('asmOgxjqx61sdQefA1_5d', '96_6JkQybSxCkaseu_zts', 'चन्द्रयान-3 को कहाँ से प्रक्षेपित किया गया और इसके लैंडिंग स्थल की विशेषता क्या थी?', '"[{\"id\":\"A\",\"text\":\"सतीश धवन अंतरिक्ष केन्द्र (SHAR), श्रीहरिकोटा - चन्द्रमा के दक्षिण ध्रुवीय क्षेत्र के पास\",\"text_en\":\"Satish Dhawan Space Centre (SHAR), Sriharikota - Near the South Polar region of the Moon\"},{\"id\":\"B\",\"text\":\"विक्रम साराभाई अंतरिक्ष केन्द्र, तिरुवनंतपुरम - चन्द्रमा के विषुवतीय क्षेत्र में\",\"text_en\":\"Vikram Sarabhai Space Centre, Thiruvananthapuram - In the equatorial region of the Moon\"},{\"id\":\"C\",\"text\":\"श्रीहरिकोटा - चन्द्रमा के उत्तरी ध्रुव के पास\",\"text_en\":\"Sriharikota - Near the North Pole of the Moon\"},{\"id\":\"D\",\"text\":\"एसडीएससी, श्रीहरिकोटा - चन्द्रमा के दूरस्थ (far side) पर\",\"text_en\":\"SDSC, Sriharikota - On the far side of the Moon\"}]"', '0.0', '[object Object]', 3, 1, 29, 'Current Affairs', 'From where was Chandrayaan-3 launched and what was the characteristic of its landing site?', NULL, 30, 'standard', NULL, NULL, NULL, 'mppsc');
