INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('SqHt1oVTrOujI24OKNxd9', '96_6JkQybSxCkaseu_zts', 'खजुराहो स्थित ''जगदम्बी मंदिर'' की प्रमुख विशेषताओं में निम्नांकित में से कौन-सा तथ्य असत्य है?', '"[{\"id\":\"A\",\"text\":\"इस मंदिर में एक ही कक्ष में अर्द्ध-मण्डप और बरामदा दोनों व्यवस्थित हैं।\",\"text_en\":\"In this temple, both the ardha-mandapa and veranda are arranged in a single chamber.\"},{\"id\":\"B\",\"text\":\"इस मंदिर में प्रदक्षिणा पथ का अभाव है।\",\"text_en\":\"This temple lacks a circumambulatory path (pradakshina patha).\"},{\"id\":\"C\",\"text\":\"गर्भगृह में लक्ष्मी की एक विशालकाय मूर्ति है।\",\"text_en\":\"There is a giant idol of Lakshmi in the sanctum sanctorum (Garbhagriha).\"},{\"id\":\"D\",\"text\":\"गर्भगृह के मुख्य द्वार पर विष्णु की मूर्ति अधिष्ठित है।\",\"text_en\":\"An idol of Vishnu is enshrined at the main door of the sanctum sanctorum.\"}]"', '2.0', '[object Object]', 3, 1, 94, 'MP GK', 'Which of the following facts is false among the main features of the ''Jagadambi Temple'' located at Khajuraho?', NULL, 50, 'standard', NULL, NULL, NULL, 'mppsc');
INSERT INTO "questions" ("id", "test_id", "question_text", "options", "correct_answer", "explanation", "marks", "negative_marks", "order", "subject", "question_text_en", "explanation_en", "ideal_time", "type", "match_pairs", "deleted_at", "extended_data", "exam_type") VALUES ('Kg2JFHVmfn9hRBJishVmR', '96_6JkQybSxCkaseu_zts', 'मध्य प्रदेश की निम्नांकित जनजातियों को उनकी उप-जनजातियों से सुमेलित कीजिए :

