INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('XLOG56Q4P4DEbnnbHCPQW', 'twI93vCTNYcfRvqqDQDM5', 'मध्य प्रदेश के ''विश्व धरोहर स्थलों'' के संदर्भ में, निम्नलिखित में से कौन सा स्थल यूनेस्को की ''अस्थायी सूची'' (Tentative List) में शामिल है, लेकिन मुख्य सूची में नहीं? In the context of ''World Heritage Sites'' of Madhya Pradesh, which of the following sites is included in the UNESCO ''Tentative List'' but not in the main list?');
