INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('rjZwoS_9ZNqif9gg3yTux', 'FFPEWTMww259TMakCWyYF', 'यदि x + 1/x = 4 है, तो x² + 1/x² का मान क्या है? If x + 1/x = 4, then what is the value of x² + 1/x²?');
