INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('X_KOM9OlRU32x699_mnNI', 'FFPEWTMww259TMakCWyYF', 'एक पंक्ति में, रमन बाएं से 15वें और दायें से 10वें स्थान पर है। पंक्ति में कुल कितने लोग हैं? In a row, Raman is 15th from the left and 10th from the right. How many people are there in the row?');
