INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('IHXA1udZLmxzGZyWTWFZI', 'FFPEWTMww259TMakCWyYF', 'यदि ''P'', ''Q'' का भाई है; ''R'', ''Q'' की माँ है; ''S'', ''R'' का पिता है; तो ''P'' का ''S'' से क्या संबंध है? If ''P'' is the brother of ''Q''; ''R'' is the mother of ''Q''; ''S'' is the father of ''R''; then how is ''P'' related to ''S''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2qebIFesu4GiHFBqQJWE9', 'FFPEWTMww259TMakCWyYF', 'एक पासे की दो स्थितियाँ दी गई हैं। यदि ''5'' सबसे ऊपर है, तो सबसे नीचे कौन सी संख्या होगी? (स्थिति 1: 1,3,5; स्थिति 2: 1,2,4) Two positions of a dice are given. If ''5'' is at the top, which number will be at the bottom? (Pos 1: 1,3,5; Pos 2: 1,2,4)');
