INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('rz2Qi3wscYqouaSmh9cqC', 'FFPEWTMww259TMakCWyYF', 'कथन: क्या भारत में प्लास्टिक थैलियों पर पूर्ण प्रतिबंध होना चाहिए? तर्क 1: हाँ, ये पारिस्थितिकी तंत्र के लिए हानिकारक हैं। तर्क 2: नहीं, यह थैला निर्माण उद्योग को मार देगा। Statement: Should there be a complete ban on plastic bags in India? Arg 1: Yes, they are harmful to the ecosystem. Arg 2: No, it will kill the bag manufacturing industry.');
