INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('br-wch2v7u8wfwW0qMFrR', 'FFPEWTMww259TMakCWyYF', '**निर्देश: निम्नलिखित गद्यांश को पढ़ें:**
