INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('eahxxB6GflvC53GlV0489', 'drcNxyFKGMfTnD-GGZ89b', 'एक कूट भाषा में, ''TIGER'' को ''QDFHS'' लिखा जाता है। उसी कूट भाषा में ''FISH'' को कैसे लिखा जाएगा? In a code language, ''TIGER'' is written as ''QDFHS''. How will ''FISH'' be written?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('I3ZDYrm_rzqP5jBoeiOKe', 'drcNxyFKGMfTnD-GGZ89b', 'एक व्यक्ति उत्तर की ओर 10 किमी चलता है, फिर बाएं मुड़कर 5 किमी चलता है। वह फिर बाएं मुड़ता है और 10 किमी चलता है। वह प्रारंभिक बिंदु से कितनी दूर है? A person walks 10 km North, turns left and walks 5 km. He turns left again and walks 10 km. How far is he from the starting point?');
