INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('onKiADWH9dLBQ8DJHOp5G', 'drcNxyFKGMfTnD-GGZ89b', 'कथन: सभी कारें बसें हैं। कोई बस ट्रक नहीं है। निष्कर्ष: (I) कोई कार ट्रक नहीं है। (II) कुछ बसें कारें हैं। Statements: All cars are buses. No bus is a truck. Conclusions: (I) No car is a truck. (II) Some buses are cars.');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('k8la0hqCVRKYT6r3CnL3H', 'drcNxyFKGMfTnD-GGZ89b', 'एक परीक्षा में, उत्तीर्ण होने के लिए 40% अंकों की आवश्यकता है। एक छात्र को 178 अंक मिले और वह 22 अंकों से अनुत्तीर्ण हो गया। अधिकतम अंक क्या हैं? In an exam, 40% marks are required to pass. A student gets 178 marks and fails by 22 marks. What are the maximum marks?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('El264Jqm7hqsZM_LRhCxQ', 'drcNxyFKGMfTnD-GGZ89b', 'प्रथम 10 अभाज्य संख्याओं का योग क्या है? What is the sum of the first 10 prime numbers?');
