INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2rzjgJ23t0MI71exqW6qO', 'drcNxyFKGMfTnD-GGZ89b', 'रवि, सुरेश से 7 रैंक आगे है। 39 छात्रों की कक्षा में सुरेश का रैंक अंत से 17वां है। शुरुआत से रवि का रैंक क्या है? Ravi is 7 ranks ahead of Suresh. In a class of 39, Suresh is 17th from the end. What is Ravi''s rank from the start?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('-ayI4-sUt7ju6W6GJd_I_', 'drcNxyFKGMfTnD-GGZ89b', '2 बजे से 3 बजे के बीच, घड़ी की सुइयां किस समय एक-दूसरे के विपरीत (180°) होंगी? At what time between 2 and 3 o''clock will the hands of a clock be opposite (180°)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('Vi9LCL_YrAXoRvplAoRuU', 'drcNxyFKGMfTnD-GGZ89b', 'एक महिला की ओर इशारा करते हुए, नमन ने कहा, ''वह मेरी दादी के इकलौते बच्चे की बेटी है।'' महिला नमन से कैसे संबंधित है? Pointing to a woman, Naman said, ''She is the daughter of the only child of my grandmother.'' How is the woman related to Naman?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('-kiKd5FfA5yHdfWHJkl61', 'drcNxyFKGMfTnD-GGZ89b', 'एक पासे में, 3 के विपरीत कौन सी संख्या है, यदि स्थितियाँ हैं: (I) 2, 3, 6 (II) 6, 5, 2? In a dice, which number is opposite 3, if positions are: (I) 2, 3, 6 (II) 6, 5, 2?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('UoJecJGDd7IdgAJYi2PER', 'drcNxyFKGMfTnD-GGZ89b', 'वेन आरेख: ''यात्री, ट्रेन, बस'' के लिए सही संबंध क्या है? Venn Diagram: Correct relation for ''Traveler, Train, Bus''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2u7NTitvDa_ve2EYAy-qF', 'drcNxyFKGMfTnD-GGZ89b', 'कथन: क्या भारत में मतदान अनिवार्य होना चाहिए? तर्क 1: हाँ, यह लोकतंत्र को मजबूत करेगा। तर्क 2: नहीं, यह व्यक्तिगत स्वतंत्रता का उल्लंघन है। Statement: Should voting be made mandatory in India? Arg 1: Yes, it will strengthen democracy. Arg 2: No, it violates individual liberty.');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('Stdk-8u9Bu3D58Z-9P9cd', 'drcNxyFKGMfTnD-GGZ89b', '300 मीटर लंबी एक ट्रेन 54 किमी/घंटा की गति से एक प्लेटफॉर्म को 40 सेकंड में पार करती है। प्लेटफॉर्म की लंबाई क्या है? A 300m long train crosses a platform in 40 seconds at 54 km/hr. What is the length of the platform?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('WFz9tldBYvMVR5qjRmOl9', 'drcNxyFKGMfTnD-GGZ89b', 'एक नाव धारा के अनुकूल 15 किमी/घंटा और धारा के प्रतिकूल 9 किमी/घंटा की गति से चलती है। शांत जल में नाव की गति क्या है? A boat goes 15 km/hr downstream and 9 km/hr upstream. Speed of boat in still water?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ppgotxvDvzkrm0pnpLQ1n', 'drcNxyFKGMfTnD-GGZ89b', 'A, B से दोगुना अच्छा कामगार है और वे मिलकर एक काम 14 दिनों में करते हैं। A अकेले इसे कितने दिनों में करेगा? A is twice as good a workman as B and together they finish a work in 14 days. In how many days will A alone finish it?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3RKeGyuOH8w0t93sxWz1s', 'drcNxyFKGMfTnD-GGZ89b', 'एक बैग में ₹1, 50 पैसे और 25 पैसे के सिक्के 5:6:8 के अनुपात में हैं। यदि कुल राशि ₹240 है, तो 25 पैसे के सिक्कों की संख्या क्या है? A bag contains coins of ₹1, 50p, 25p in ratio 5:6:8. Total amount is ₹240. Number of 25p coins?');
