INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e_Z3QVaIqNE6pbg9_1jdD', 'drcNxyFKGMfTnD-GGZ89b', '**निर्देश: गद्यांश पढ़ें:**
