INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2c490f4d-d7ba-4f5c-adde-aab62c34fea2', '873f7e4d-586b-4656-8a5d-638565cd40a0', 'ऋग्वेद के किस मंडल को ''वंश मंडल'' (Family Books) कहा जाता है, जो सबसे प्राचीन माने जाते हैं? Which Mandalas of the Rigveda are called ''Vamsha Mandalas'' (Family Books) and are considered the oldest?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('158387d1-4146-45c7-b453-6e1e077431b9', '873f7e4d-586b-4656-8a5d-638565cd40a0', 'निम्नलिखित में से कौन सा वेद ''गद्य और पद्य'' (Prose and Verse) दोनों में लिखा गया है? Which of the following Vedas is written in both ''Prose and Verse''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d9124a73-f9de-4055-bad9-acb7825abddf', '873f7e4d-586b-4656-8a5d-638565cd40a0', 'किस वेद को ''ब्रह्मवेद'' (Brahmaveda) या ''श्रेष्ठ वेद'' भी कहा जाता है? Which Veda is also known as ''Brahmaveda'' or ''Best Veda''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5ac60313-ce9e-449a-bf2b-f09d174ca8e8', '873f7e4d-586b-4656-8a5d-638565cd40a0', 'ऋग्वेद के 7वें मंडल में वर्णित प्रसिद्ध ''दाशराज्ञ युद्ध'' (Battle of Ten Kings) किस नदी के तट पर लड़ा गया था? The famous ''Battle of Ten Kings'' (Dasharajna War) mentioned in the 7th Mandala of Rigveda was fought on the banks of which river?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('bb543c65-fae1-452e-a5e3-39d8ffbed767', '873f7e4d-586b-4656-8a5d-638565cd40a0', 'वेदों को उनके ''ऋत्विक'' (प्रधान पुरोहित) से सुमेलित करें (Match the Vedas with their ''Ritvik'' / Chief Priest): Match the Vedas with their ''Ritvik'' / Chief Priest:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f76d33e5-de1a-40f8-9142-f2b89a9a7290', '873f7e4d-586b-4656-8a5d-638565cd40a0', 'ऋग्वेद के 10वें मंडल के ''पुरुष सूक्त'' (Purusha Sukta) में पहली बार किसका उल्लेख मिलता है? What is mentioned for the first time in the ''Purusha Sukta'' of the 10th Mandala of Rigveda?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('64815a9a-6a12-4d9e-8472-bc1afcd320bf', '873f7e4d-586b-4656-8a5d-638565cd40a0', 'एशिया माइनर (तुर्की) के ''बोगज़-कोई'' (Boghaz-Koi) अभिलेख (1400 ई.पू.) में किन चार वैदिक देवताओं का उल्लेख मिलता है? Which four Vedic deities are mentioned in the ''Boghaz-Koi'' inscription (1400 BC) of Asia Minor (Turkey)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9bdedc06-0a91-4dfd-beeb-53222a138023', '873f7e4d-586b-4656-8a5d-638565cd40a0', 'कथन (A): ''वाजसनेयी संहिता'' (Vajasaneyi Samhita) केवल शुक्ल यजुर्वेद से संबंधित है।
कारण (R): याज्ञवल्क्य ने इसे सूर्य से प्राप्त किया था।
सही विकल्प चुनें: Assertion (A): ''Vajasaneyi Samhita'' is related only to Shukla Yajurveda.
Reason (R): Yajnavalkya received it from the Sun (Surya).
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e68be350-846c-41da-93ee-1c43ddd5b522', '873f7e4d-586b-4656-8a5d-638565cd40a0', '''त्रयी'' (Trayi) में अथर्ववेद को शामिल न करने का मुख्य कारण क्या था? What was the main reason for not including Atharvaveda in ''Trayi''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fc0f4750-5926-4461-a888-174f51e4e20f', '873f7e4d-586b-4656-8a5d-638565cd40a0', 'ऋग्वेद में ''अघन्या'' (Aghanya) शब्द का प्रयोग किसके लिए किया गया है? In Rigveda, the term ''Aghanya'' is used for:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6fb73f95-6a6e-428b-8e44-e8abe41dfe07', 'bd237dd0-b66d-482f-b8cf-cad3808532cb', 'प्राचीनतम और सर्वाधिक प्रामाणिक स्मृति कौन सी मानी जाती है? Which is considered the oldest and most authoritative Smriti?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('b4bc53d1-1856-41e4-877f-b13a832ab3f0', 'bd237dd0-b66d-482f-b8cf-cad3808532cb', '''मिताक्षरा'' (Mitakshara) टीका, जो हिंदू उत्तराधिकार कानून का आधार है, किस स्मृति पर लिखी गई है? The ''Mitakshara'' commentary, which is the basis of Hindu Succession Law, is written on which Smriti?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ef4fb416-d4ce-4ec0-bf52-f329acc6640b', 'bd237dd0-b66d-482f-b8cf-cad3808532cb', 'गुप्त काल में लिखी गई वह स्मृति कौन सी है जो दासों की मुक्ति (Emancipation of Slaves) के विस्तृत नियम बताती है? Which Smriti written in the Gupta period provides detailed rules for the ''Emancipation of Slaves''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ed3dde75-b256-4545-8fcd-99f94b0ed789', 'bd237dd0-b66d-482f-b8cf-cad3808532cb', 'कथन (A): स्मृतियों को ''धर्मशास्त्र'' भी कहा जाता है।
कारण (R): स्मृतियाँ वेदों (श्रुति) पर आधारित नहीं हैं, बल्कि स्वतंत्र ग्रंथ हैं।
सही विकल्प चुनें: Assertion (A): Smritis are also called ''Dharmashastra''.
Reason (R): Smritis are not based on Vedas (Shruti) but are independent texts.
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0a5cb6dd-25bc-4c71-b2b0-30f77fb17b5c', 'bd237dd0-b66d-482f-b8cf-cad3808532cb', 'प्रमुख स्मृतियों और उनके टीकाकारों (Commentators) को सुमेलित करें (Match the major Smritis with their Commentators): Match the major Smritis with their Commentators:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('06922e1d-d368-49b9-adf1-21e113e1e5b0', 'bd237dd0-b66d-482f-b8cf-cad3808532cb', 'पूर्व-मध्यकाल (Pre-Medieval) में विदेश यात्रा से लौटकर आए लोगों की ''शुद्धि'' के लिए किस स्मृति में विधान मिलते हैं? Which Smriti provides rules for the ''Shuddhi'' (Purification) of people returning from foreign travel in the Pre-Medieval period?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('da17065a-eb18-4f45-b789-3edef7bb6220', 'bd237dd0-b66d-482f-b8cf-cad3808532cb', 'किस स्मृति में ''कलिवर्ज्य'' (Kali-Varjya) का सिद्धांत मिलता है, जिसके तहत कलियुग में कुछ प्राचीन प्रथाओं (जैसे नियोग, गोमेध) को वर्जित किया गया? Which Smriti mentions the principle of ''Kali-Varjya'', under which certain ancient practices (like Niyoga, Gomedha) were forbidden in Kaliyuga?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e88e1c55-a7fe-4a48-ba9e-1b8edd0fbec9', 'bd237dd0-b66d-482f-b8cf-cad3808532cb', 'मनुस्मृति में विवाह के कितने प्रकारों (Forms of Marriage) का उल्लेख है? How many forms of Marriage are mentioned in Manusmriti?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('cbd8b8aa-2f12-4712-a951-02e125e7114b', 'bd237dd0-b66d-482f-b8cf-cad3808532cb', 'गद्य (Prose) में लिखी गई स्मृति कौन सी है? Which Smriti is written in Prose?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('929a0dfa-4920-43f5-9fdb-8b01c885d1fe', 'bd237dd0-b66d-482f-b8cf-cad3808532cb', '1882 में ''नारद स्मृति'' का अंग्रेजी अनुवाद किसने किया था? Who translated ''Narada Smriti'' into English in 1882?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('289e2345-e927-4ce4-be28-a715812d4903', '0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e', 'ऋग्वेद में ''ऋत'' (Ṛta) का मूल अर्थ क्या है? What is the basic meaning of ''Ṛta'' in Rigveda?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d383306c-5abe-4973-bdcd-0eb1250f73d2', '0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e', 'किस वैदिक देवता को ''ऋतस्य गोपा'' (Guardian of Ṛta) कहा जाता है? Which Vedic deity is called ''Ritasya Gopa'' (Guardian of Ṛta)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9a302adb-1427-46f5-aa5a-9c74ad96ed5b', '0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e', 'कथन (A): ''ऋत'' और ''सत्य'' एक ही सिक्के के दो पहलू माने जाते हैं।
कारण (R): ऋग्वेद के ''अघमर्षण सूक्त'' में कहा गया है कि तप से ऋत और सत्य दोनों की उत्पत्ति हुई।
सही विकल्प चुनें: Assertion (A): ''Ṛta'' and ''Satya'' are considered two sides of the same coin.
Reason (R): The ''Aghamarshana Sukta'' of Rigveda states that both Ṛta and Satya were born from Tapas (Heat/Austerity).
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5f11e1e7-dce0-44e7-9717-57e856b7576d', '0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e', '''ऋत'' के विभिन्न आयामों को सुमेलित करें (Match the different dimensions of ''Ṛta''): Match the different dimensions of ''Ṛta'':');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dd1eda90-b138-4279-99cf-4bf3126fbde1', '0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e', 'ऋत के पतन और ''धर्म'' (Dharma) के उदय का कारण क्या माना जाता है? What is considered the reason for the decline of Ṛta and the rise of ''Dharma''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('17abe141-c214-4bdf-95d4-72b062da98c9', '0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e', '''ऋत'' शब्द का विलोम (Antonym) ऋग्वेद में क्या प्रयोग हुआ है? What antonym for the word ''Ṛta'' is used in the Rigveda?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('98d946bd-d41b-4c91-9cd1-78c0cdc809f0', '0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e', 'किस विद्वान ने ऋत को ''Moral Order'' (नैतिक व्यवस्था) कहा है? Which scholar has termed Ṛta as ''Moral Order''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4c23980b-6b6e-4b3c-a7fb-f025b2903ef6', '0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e', 'ऋग्वेद में सूर्य को किसका ''चक्षु'' (Eye) माना गया है जो ऋत का निरीक्षण करता है? In Rigveda, the Sun is considered the ''Eye'' of whom, inspecting the Ṛta?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ab0e84f2-dbe9-4750-b505-85acff620906', '0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e', '''ऋत'' की अवधारणा आधुनिक विज्ञान के किस सिद्धांत के निकट प्रतीत होती है? The concept of ''Ṛta'' seems close to which principle of modern science?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f7982209-8d60-441c-a8bb-ccbef71a30d0', '0671d0bd-0c63-45c5-a83f-6d9cf4ed1e4e', 'ऋत के कितने स्तर (Levels) माने गए हैं? How many levels of Ṛta are considered?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f2ed3a8c-71ed-4069-b610-e69b58c50423', '86893312-7cbb-4e59-872a-ec210b0b282e', 'अथर्ववेद में ''सभा'' और ''समिति'' को किसकी दो ''पुत्रियाँ'' कहा गया है? In Atharvaveda, ''Sabha'' and ''Samiti'' are called the two ''daughters'' of whom?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8e5ac60c-b6f5-4cfc-bb85-314f786622f9', '86893312-7cbb-4e59-872a-ec210b0b282e', '''सभा'' (Sabha) मुख्य रूप से किस प्रकार के लोगों की संस्था थी? ''Sabha'' was primarily an assembly of what kind of people?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2880c579-ccfb-4a14-8044-e0a9698b72f4', '86893312-7cbb-4e59-872a-ec210b0b282e', 'ऋग्वैदिक काल में ''समिति'' (Samiti) का अध्यक्ष क्या कहलाता था? What was the President of the ''Samiti'' called in the Rigvedic period?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('bed276c5-5c53-4e83-900a-1fdeacf26c61', '86893312-7cbb-4e59-872a-ec210b0b282e', 'कथन (A): ऋग्वैदिक काल में महिलाएं ''सभा'' और ''विदय'' में भाग लेती थीं।
कारण (R): उत्तर वैदिक काल में महिलाओं का सभा में प्रवेश वर्जित हो गया।
सही विकल्प चुनें: Assertion (A): In Rigvedic period, women participated in ''Sabha'' and ''Vidatha''.
Reason (R): In Later Vedic period, entry of women in Sabha was prohibited.
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9693cbb3-0f83-4ef1-acb0-e657bbc124f6', '86893312-7cbb-4e59-872a-ec210b0b282e', 'वैदिक संस्थाओं और उनकी विशेषताओं को सुमेलित करें (Match the Vedic institutions with their features): Match the Vedic institutions with their features:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4560e5e3-be20-4925-b233-0a2e15ae25b4', '86893312-7cbb-4e59-872a-ec210b0b282e', 'अथर्ववेद में सभा के लिए ''नरिष्टा'' (Narishtha) शब्द का प्रयोग हुआ है। इसका अर्थ क्या है? The word ''Narishtha'' is used for Sabha in Atharvaveda. What does it mean?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('091c91ce-329c-49cf-9a7b-88855803fb3d', '86893312-7cbb-4e59-872a-ec210b0b282e', 'उत्तर वैदिक काल में सभा और समिति के महत्व में गिरावट का मुख्य कारण क्या था? What was the main reason for the decline in importance of Sabha and Samiti in the Later Vedic period?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8c5dae8c-2dbf-469f-b3bb-74a135001a02', '86893312-7cbb-4e59-872a-ec210b0b282e', '''रत्निन'' (Ratnin) कौन थे जो राजा के चुनाव या राज्याभिषेक में महत्वपूर्ण भूमिका निभाते थे? Who were the ''Ratnins'' who played an important role in the King''s election or coronation?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('7f8b91d5-a812-45d1-ad39-ccf3be6c3070', '86893312-7cbb-4e59-872a-ec210b0b282e', 'ऋग्वेद में ''विदथ'' (Vidatha) के बारे में कौन सा तथ्य सही है? Which fact is correct about ''Vidatha'' in Rigveda?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ef1513d2-eac6-4197-b7da-50a8a53f572a', '86893312-7cbb-4e59-872a-ec210b0b282e', 'निम्नलिखित में से कौन ''समिति'' के सत्रों में भाग ले सकता था? Who among the following could participate in the sessions of ''Samiti''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('49df1692-c938-4591-a99b-b7379b05b4b4', '15a46e2a-ac67-4384-b7e1-864f61398a70', 'बुद्ध काल में विश्व का सबसे बड़ा और शक्तिशाली ''गणतंत्र'' (Republic) कौन सा था? Which was the largest and most powerful ''Republic'' (Gantantra) in the world during the Buddha period?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('7f6053cf-2ea4-4577-bb2f-9b0dcb4eb831', '15a46e2a-ac67-4384-b7e1-864f61398a70', 'प्राचीन गणराज्यों में मतदान (Voting) के लिए किस शब्द का प्रयोग होता था? Which term was used for ''Voting'' in ancient Republics?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6a6ed58d-72ee-4bf3-b330-64f4df4a16fd', '15a46e2a-ac67-4384-b7e1-864f61398a70', 'गणराज्यों की केंद्रीय विधानसभा या बैठक स्थल को क्या कहा जाता था? What was the Central Assembly or Meeting place of the Republics called?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f5bb61e1-88cd-46ef-9efb-093e0d6e51f8', '15a46e2a-ac67-4384-b7e1-864f61398a70', 'प्रमुख गणराज्य और उनकी राजधानियों को सुमेलित करें (Match the major Republics with their Capitals): Match the major Republics with their Capitals:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('483b4e1a-d62c-4721-993c-1f57c387a2db', '15a46e2a-ac67-4384-b7e1-864f61398a70', 'कथन (A): प्राचीन गणराज्यों का पतन मगध साम्राज्य के उदय के साथ हुआ।
कारण (R): गणराज्यों में एकता का अभाव था और निर्णय लेने में देरी होती थी।
सही विकल्प चुनें: Assertion (A): Ancient Republics declined with the rise of Magadha Empire.
Reason (R): Republics lacked unity and there was delay in decision making.
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('543c81b2-1053-4d6b-af49-d02bfc040a2d', '15a46e2a-ac67-4384-b7e1-864f61398a70', 'पाणिनि ने ''अष्टाध्यायी'' में किन गणराज्यों को ''आयुधजीवी संघ'' (Ayudhajivi Sangha) कहा है? Which Republics did Panini call ''Ayudhajivi Sangha'' in ''Ashtadhyayi''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1e10c0c8-38ba-4d57-9cc4-228685acbf1f', '15a46e2a-ac67-4384-b7e1-864f61398a70', 'वैशाली के लिच्छवि गणराज्य में न्याय व्यवस्था (Judicial System) कितने चरणों (Stages) में थी? The Judicial System in the Lichchhavi Republic of Vaishali had how many Stages?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ac43854c-711a-4a37-a232-bbd400ff406c', '15a46e2a-ac67-4384-b7e1-864f61398a70', 'गणराज्यों में कार्यपालिका शक्ति (Executive Power) किसके हाथों में होती थी? In whose hands was the Executive Power in the Republics?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d2a03194-7ae7-4d5c-9172-9e42c2ce5f82', '15a46e2a-ac67-4384-b7e1-864f61398a70', '''अजातशत्रु और वज्जि संघ'' के बीच संघर्ष का वर्णन किस बौद्ध ग्रंथ में विस्तार से मिलता है? In which Buddhist text is the conflict between ''Ajatashatru and Vajji Sangha'' described in detail?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1231143b-f63a-4064-b118-3ef1dd01d454', '15a46e2a-ac67-4384-b7e1-864f61398a70', 'किस प्राचीन भारतीय गणराज्य ने सिकंदर (Alexander) के आक्रमण के समय अपनी स्त्रियों को भी युद्ध में उतारा था? Which ancient Indian Republic fielded even its women in war during Alexander''s invasion?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('22925218-fdba-41e6-b949-37ccedc37003', '98a7ad87-46ed-4f91-832b-c2038cdddbb0', 'प्राचीन काल के दौरान, राजा महिष्मत ने ''महिष्मती'' शहर की स्थापना की थी। वह किस वंश से संबंधित थे? During ancient times, King Mahishmat founded the city of ''Mahishmati''. To which dynasty did he belong?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('61a139a8-cb17-4be6-8992-69cc9870dbdc', '98a7ad87-46ed-4f91-832b-c2038cdddbb0', 'भोपाल रियासत के संबंध में निम्नलिखित कथनों पर विचार करें:
1. इसकी स्थापना दोस्त मोहम्मद खान ने 1723-24 में की थी।
2. इस्लाम नगर इसकी प्रारंभिक राजधानी थी।
3. दोस्त मोहम्मद खान ने अंतिम हिंदू शासिका रानी कमलापति की सहायता की थी।

सही कथन चुनें: Consider the following statements regarding Bhopal State:
1. It was founded by Dost Mohammad Khan in 1723-24.
2. Islam Nagar was its initial capital.
3. Dost Mohammad Khan helped the last Hindu ruler Rani Kamlapati.

Choose the correct statements:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dca655a8-2c27-486b-84db-225d702b766c', '98a7ad87-46ed-4f91-832b-c2038cdddbb0', 'कल्चुरी वंश की ''त्रिपुरी'' शाखा का वास्तविक संस्थापक किसे माना जाता है? Who is considered the real founder of the ''Tripuri'' branch of the Kalachuri dynasty?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('925e7efc-d25d-4b2b-8b84-c524560b061f', '98a7ad87-46ed-4f91-832b-c2038cdddbb0', 'भरहुत स्तूप (सतना) का निर्माण मौर्य काल में हुआ था, लेकिन इसकी वेष्टनी (Railing) का निर्माण किस वंश के दौरान कराया गया था? The Bharhut Stupa (Satna) was built during the Maurya period, but during which dynasty was its railing (Vedika) constructed?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9719d694-c7d9-46a5-ba3a-5d5286f2f04c', '98a7ad87-46ed-4f91-832b-c2038cdddbb0', 'निम्नलिखित मध्यकालीन शासकों और उनके क्षेत्रों को सुमेलित करें: Match the following medieval rulers and their regions:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('66af0344-0bc8-4d32-b842-20ace62140d0', '98a7ad87-46ed-4f91-832b-c2038cdddbb0', 'ओरछा के बुंदेला वंश के किस शासक ने जहांगीर के कहने पर अबुल फजल की हत्या की थी? Which ruler of the Bundela dynasty of Orchha murdered Abul Fazl at the behest of Jahangir?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8c975b98-d1dd-41aa-8d6e-9ee5d809e1a3', '98a7ad87-46ed-4f91-832b-c2038cdddbb0', '1857 के विद्रोह के दौरान ''गढ़ा मण्डला'' से विद्रोह का नेतृत्व किसने किया था? Who led the revolt from ''Garha Mandla'' during the 1857 uprising?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('abe0f051-ebef-4658-9c06-8ea02eb188d7', '98a7ad87-46ed-4f91-832b-c2038cdddbb0', 'परमार वंश के किस शासक ने धार में ''सरस्वती कंठाभरण'' नामक संस्कृत विद्यालय की स्थापना की थी? Which ruler of the Paramara dynasty established a Sanskrit school named ''Saraswati Kanthabharana'' in Dhar?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('057faa1e-6b48-46e2-ad89-580aef93709d', '98a7ad87-46ed-4f91-832b-c2038cdddbb0', 'चंदेल वंश के किस शासक ने महमूद गजनवी का सफलतापूर्वक प्रतिरोध किया था? Which ruler of the Chandela dynasty successfully resisted Mahmud Ghaznavi?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('09d0591a-9d09-45ee-9c08-d2c6a325798c', '98a7ad87-46ed-4f91-832b-c2038cdddbb0', 'ग्वालियर के सिंधिया वंश के संस्थापक कौन थे? Who was the founder of the Scindia dynasty of Gwalior?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6fcc23ee-9673-4257-9f74-c8d682ede480', 'ff20f456-3f09-4b99-948a-c8130f9616cf', 'प्राचीन जनपद ''वत्स'' की राजधानी क्या थी और इसका विस्तार वर्तमान मध्यप्रदेश के किस क्षेत्र में था? What was the capital of the ancient Janapada ''Vatsa'' and in which region of present-day MP was it extended?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('65cb6b13-67c7-4ad6-86ef-a84f93de9d41', 'ff20f456-3f09-4b99-948a-c8130f9616cf', 'राजा भोज के शासनकाल के दौरान परमारों की राजधानी ''धार'' स्थानांतरित होने से पहले क्या थी? What was the capital of the Paramaras before it was shifted to ''Dhar'' during Raja Bhoj''s reign?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3485796c-4c56-4c43-942b-0ae399529c2d', 'ff20f456-3f09-4b99-948a-c8130f9616cf', 'निम्नलिखित कथनों पर विचार करें:
1. ओलिवर वंश की राजधानी ''दशपुर'' (मंदसौर) थी।
2. राजा यशोधर्मन इस वंश के सबसे प्रतापी शासक थे।
3. उन्होंने हूण शासक मिहिरकुल को पराजित किया था।

सही कथन चुनें: Consider the following statements:
1. The capital of the Aulikara dynasty was ''Dashpur'' (Mandsaur).
2. King Yashodharman was the most illustrious ruler of this dynasty.
3. He defeated the Huna ruler Mihirakula.

Choose the correct statement:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5e1d6e55-9537-4a06-8608-848b9d8c84fa', 'ff20f456-3f09-4b99-948a-c8130f9616cf', 'बुंदेला राजाओं ने अपनी राजधानी ओरछा की स्थापना किस वर्ष की थी? In which year did the Bundela kings establish their capital, Orchha?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a8fc98a4-4777-48cf-afc1-8650230af436', 'ff20f456-3f09-4b99-948a-c8130f9616cf', 'राजवंश और उनकी राजधानियों को सुमेलित करें: Match the dynasties and their capitals:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8a50e721-8904-41c3-bc63-2ad30cd81459', 'ff20f456-3f09-4b99-948a-c8130f9616cf', 'गोंडवाना साम्राज्य के किस शासक ने अपनी राजधानी ''सिंगौरगढ़'' से ''चौरागढ़'' स्थानांतरित की थी? Which ruler of the Gondwana kingdom shifted the capital from ''Singaurgarh'' to ''Chauragarh''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('932a3d07-2679-4594-b33e-61efbd983d82', 'ff20f456-3f09-4b99-948a-c8130f9616cf', 'मालवा के खिलजी सुल्तान महमूद खिलजी ने ''मांडू'' का नाम बदलकर क्या रखा था? What did the Khilji Sultan of Malwa, Mahmud Khilji, rename ''Mandu''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c7411939-9369-491f-9f19-e7915be57ee0', 'ff20f456-3f09-4b99-948a-c8130f9616cf', 'अहिल्याबाई होलकर ने होलकर वंश की राजधानी इंदौर से कहाँ स्थानांतरित की थी? Where did Ahilyabai Holkar shift the capital of the Holkar dynasty from Indore?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('bf7d4fe7-59f8-4446-98d5-6b9fcc2d9493', 'ff20f456-3f09-4b99-948a-c8130f9616cf', 'जीवाजीराव सिंधिया के समय ग्वालियर रियासत की ''ग्रीष्मकालीन राजधानी'' क्या थी? What was the ''Summer Capital'' of the Gwalior State during the time of Jiwajirao Scindia?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4b257df7-20d9-4399-ad82-411aca714c63', 'ff20f456-3f09-4b99-948a-c8130f9616cf', 'मध्य भारत (1948-1956) की राजधानी के संबंध में कौन सा कथन गलत है? Which statement is incorrect regarding the capital of Madhya Bharat (1948-1956)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('AwclEcpImXMV-dnggur4e', '3bIu3iTfpozIvU5_YWpTk', 'पारस्परिक कौशल (Interpersonal Skills) में ''सहानुभूति'' (Empathy) का क्या अर्थ है? What is the meaning of ''Empathy'' in Interpersonal Skills?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('QtWjhYElb2hmWaFVQPVGG', '3bIu3iTfpozIvU5_YWpTk', 'संचार अवरोधों (Barriers) को उनके प्रकार से सुमेलित करें: Match Communication Barriers with their types:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('v5x6kyUnLZP-3T9Bi335P', '3bIu3iTfpozIvU5_YWpTk', 'संचार में ''फिल्टरिंग'' (Filtering) का क्या तात्पर्य है? What does ''Filtering'' imply in communication?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('Vv2M8l_1OgaaA8dxnGO3V', '3bIu3iTfpozIvU5_YWpTk', 'यदि ''ZEBRA'' को ''2652181'' लिखा जाता है, तो ''COBRA'' को कैसे लिखा जाएगा? If ''ZEBRA'' is written as ''2652181'', how will ''COBRA'' be written?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('84OthqeDhAn11GVxPzqHD', '3bIu3iTfpozIvU5_YWpTk', 'सुबह सूर्योदय के बाद, राम एक पोल की ओर मुंह करके खड़ा था। पोल की छाया उसके ठीक दाईं ओर गिर रही थी। राम किस दिशा की ओर मुंह करके खड़ा था? One morning after sunrise, Ram was facing a pole. The shadow of the pole fell exactly to his right. Which direction was Ram facing?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('zQkJKA6nnNZWJQWph_qQy', '3bIu3iTfpozIvU5_YWpTk', 'श्रृंखला पूरी करें: 4, 9, 25, 49, 121, ? Complete the series: 4, 9, 25, 49, 121, ?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dX0_heGeaT7EAWaifvxIe', '3bIu3iTfpozIvU5_YWpTk', 'कथन: कुछ फल आम हैं। कुछ आम लाल हैं। निष्कर्ष: (I) सभी फल लाल हैं। (II) कुछ लाल फल हैं। Statements: Some fruits are mangoes. Some mangoes are red. Conclusions: (I) All fruits are red. (II) Some red are fruits.');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('gVeOi02e0-zMA1qDPJZ76', '3bIu3iTfpozIvU5_YWpTk', 'एक क्रिकेट मैच में पहले 10 ओवर में रन रेट 3.2 था। शेष 40 ओवरों में 282 रन के लक्ष्य तक पहुंचने के लिए रन रेट क्या होना चाहिए? In the first 10 overs of a cricket game, the run rate was 3.2. What should be the run rate in the remaining 40 overs to reach the target of 282 runs?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('TLKGvyaKAu4qAsALB9UCz', '3bIu3iTfpozIvU5_YWpTk', 'दो संख्याओं का म.स. (HCF) 16 है और उनका गुणनफल 6400 है। उनका ल.स. (LCM) क्या है? HCF of two numbers is 16 and their product is 6400. What is their LCM?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1Ftz0n2imPURQ1PYDTWG0', '3bIu3iTfpozIvU5_YWpTk', 'असंगत ज्ञात करें: 125, 64, 216, 100 Find the odd one: 125, 64, 216, 100');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a7SYxw5quRbU9FzeN1-Pr', '3bIu3iTfpozIvU5_YWpTk', 'एक तस्वीर की ओर इशारा करते हुए, एक आदमी ने कहा, ''मेरा कोई भाई या बहन नहीं है, लेकिन उस आदमी का पिता मेरे पिता का बेटा है।'' तस्वीर किसकी है? Pointing to a photograph, a man said, ''I have no brother or sister, but that man''s father is my father''s son.'' Whose photograph is it?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fLWj9K-AQ3u8ZdBM2BxxP', '3bIu3iTfpozIvU5_YWpTk', 'यदि 5 जनवरी 2011 को गुरुवार था, तो 15 अगस्त 2011 को कौन सा दिन था? If 5th Jan 2011 was Thursday, what day was 15th Aug 2011?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('CbRnOWqnGsAjXINeDQfOp', '3bIu3iTfpozIvU5_YWpTk', 'यदि ''×'' का अर्थ ''-'', ''+'' का अर्थ ''÷'', ''-'' का अर्थ ''×'', और ''÷'' का अर्थ ''+'' है, तो: 15 - 2 ÷ 900 + 90 × 100 = ? If ''×'' means ''-'', ''+'' means ''÷'', ''-'' means ''×'', and ''÷'' means ''+'', then: 15 - 2 ÷ 900 + 90 × 100 = ?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('hdziKazqkh8x3VfkEwTvO', '3bIu3iTfpozIvU5_YWpTk', 'पासे की तीन स्थितियां दी गई हैं। ''1'' के विपरीत फलक पर कौन सी संख्या है? (I: 1,2,3; II: 1,3,5; III: 4,5,6) Three positions of dice given. Which number is opposite ''1''? (I: 1,2,3; II: 1,3,5; III: 4,5,6)');
