INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('yb-hV7VsjfY3n053401zb', '3bIu3iTfpozIvU5_YWpTk', 'निर्णय लेना: आप एक साक्षात्कार बोर्ड के सदस्य हैं। एक उम्मीदवार आपका करीबी रिश्तेदार है। आप क्या करेंगे? Decision Making: You are on an interview board. A candidate is your close relative. What will you do?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9zfPGjQDa3bqiLIEqD3-o', '3bIu3iTfpozIvU5_YWpTk', 'एक संख्या को जब 119 से विभाजित किया जाता है, तो शेषफल 19 बचता है। यदि उसी संख्या को 17 से विभाजित किया जाए, तो शेषफल क्या होगा? A number when divided by 119 leaves remainder 19. If divided by 17, remainder will be?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('vOktdXwW_rsIQOc6lEqt_', '3bIu3iTfpozIvU5_YWpTk', 'A और B की आयु का अनुपात 3:5 है। 10 वर्ष बाद, अनुपात 5:7 होगा। A की वर्तमान आयु क्या है? Ratio of ages of A and B is 3:5. After 10 years, ratio will be 5:7. What is A''s present age?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5jZCRnLy8cTLhuMrMZ-YO', '3bIu3iTfpozIvU5_YWpTk', 'एक फल विक्रेता के पास कुछ सेब थे। उसने 40% सेब बेचे और अभी भी उसके पास 420 सेब हैं। मूल रूप से उसके पास कितने सेब थे? A fruit seller had some apples. He sells 40% and still has 420 apples. Originally, he had?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3aDjmvRCe1EOvCGHhUXie', '3bIu3iTfpozIvU5_YWpTk', 'यदि P का 50% = Q का 25% है, तो P = Q का x% है। x का मान क्या है? If 50% of P = 25% of Q, then P = x% of Q. Find x.');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('tPJV6Je2TbD1NyVl1Glrv', '3bIu3iTfpozIvU5_YWpTk', '45 लीटर मिश्रण में दूध और पानी का अनुपात 4:1 है। इसमें कितना पानी और मिलाया जाए कि अनुपात 3:2 हो जाए? In 45L mixture, milk:water is 4:1. How much water to add to make ratio 3:2?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('cip7DzBsLuHQ3SGv_ACkP', '3bIu3iTfpozIvU5_YWpTk', 'एक त्रिभुज की भुजाएं 3 सेमी, 4 सेमी और 5 सेमी हैं। इसका क्षेत्रफल क्या है? Sides of a triangle are 3cm, 4cm, 5cm. Area is?');
