INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('53ec113f-d42e-4e95-a280-d3877a2c32ae', '491941d1-1508-44c2-9c41-bd862625df0e', 'ऋग्वेद के ''पुरुष सूक्त'' (Purusha Sukta) में चारों वर्णों की उत्पत्ति एक विराट पुरुष के विभिन्न अंगों से बताई गई है। इसमें ''क्षत्रिय'' (Kshatriya) की उत्पत्ति किस अंग से मानी गई है? In the ''Purusha Sukta'' of Rigveda, the origin of the four Varnas is described from different parts of a Cosmic Man. From which part is the ''Kshatriya'' said to have originated?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('da887242-b177-4a1f-ad96-1a6a60e88395', '491941d1-1508-44c2-9c41-bd862625df0e', 'भगवद्गीता में वर्ण व्यवस्था का आधार ''जन्म'' (Birth) न मानकर क्या माना गया है? In Bhagavad Gita, what is considered the basis of Varna system instead of ''Birth''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('b0ee9a48-6776-4942-99d4-7e0dc1f79c26', '491941d1-1508-44c2-9c41-bd862625df0e', 'निम्नलिखित में से कौन ''द्विज'' (Dwija) की श्रेणी में शामिल नहीं था? Who among the following was NOT included in the category of ''Dwija'' (Twice-born)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4d02d577-2c84-4126-825e-3ef865943d05', '491941d1-1508-44c2-9c41-bd862625df0e', '''आश्रम व्यवस्था'' (Ashrama System) का मुख्य उद्देश्य क्या था? What was the main objective of the ''Ashrama System''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ceea5367-fa4e-4d72-9576-c92f20489870', '491941d1-1508-44c2-9c41-bd862625df0e', 'आश्रमों को उनके मुख्य कर्तव्यों से सुमेलित करें (Match the Ashramas with their primary duties): Match the Ashramas with their primary duties:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2eff9b1a-8754-471f-9de7-381257f4fa4e', '491941d1-1508-44c2-9c41-bd862625df0e', 'किस आश्रम को ''सभी आश्रमों का आधार'' (Backbone of all Ashramas) कहा गया है? Which Ashrama is called the ''Backbone of all Ashramas''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('558b9ea0-b6da-45ce-9b78-06c840b6875c', '491941d1-1508-44c2-9c41-bd862625df0e', '''शूद्रों'' को किस रूप में सेवा करने का कर्तव्य सौंपा गया था? What duty was assigned to the ''Shudras''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('bd23e4b9-2f3a-48d5-98d7-41e35152115f', '491941d1-1508-44c2-9c41-bd862625df0e', 'कथन (A): वर्ण व्यवस्था शुरू में लचीली (Flexible) थी, लेकिन उत्तर वैदिक काल में यह कठोर (Rigid) हो गई।
कारण (R): उत्तर वैदिक काल में वर्ण का निर्धारण ''कर्म'' के बजाय ''जन्म'' से होने लगा।
सही विकल्प चुनें: Assertion (A): Varna system was initially flexible, but became rigid in Later Vedic period.
Reason (R): In Later Vedic period, Varna was determined by ''Birth'' instead of ''Karma''.
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d136e5de-4bf1-4bb4-86af-01fcf06926e3', '491941d1-1508-44c2-9c41-bd862625df0e', 'किस आश्रम में प्रवेश करने पर व्यक्ति ''परिव्राजक'' (Wanderer) कहलाता है? Entering which Ashrama does a person become a ''Parivrajaka'' (Wanderer)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('84d8d1ec-d7b3-41da-a868-e975720099d0', '491941d1-1508-44c2-9c41-bd862625df0e', 'वर्णसंकर (Varna-sankara) की स्थिति कब उत्पन्न होती है? When does the situation of ''Varna-sankara'' (Mixture of Varnas) arise?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('99a35d9b-365b-4fb8-a3f5-1cf1a6a5d832', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'भारतीय दर्शन में ''पुरुषार्थ'' (Purushartha) की कुल संख्या कितनी मानी गई है? What is the total number of ''Purusharthas'' in Indian philosophy?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6aa02067-6a6b-4d0f-ae7d-85a1799a86bb', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'पुरुषार्थों में किसे ''मूल'' (Root) या नियामक माना गया है जिसके बिना अन्य पुरुषार्थ अनियंत्रित हो सकते हैं? Which Purushartha is considered the ''Root'' or regulator without which other Purusharthas can become uncontrolled?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a86c3787-29b8-45d4-9789-e40560889886', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'निम्नलिखित में से कौन ''त्रिवर्ग'' (Trivarga) का हिस्सा नहीं है? Which of the following is NOT a part of ''Trivarga''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('04884379-9ef4-43ab-bb89-343ff7dd9d3c', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'पुरुषार्थों और उनके अर्थ/उद्देश्य को सुमेलित करें (Match the Purusharthas with their meaning/objective): Match the Purusharthas with their meaning/objective:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a694db06-fbcc-4f1f-b26c-8fc5fd0bfd1e', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'कौटिल्य ने अपने ''अर्थशास्त्र'' में किस पुरुषार्थ को सबसे प्रधान (Most Important) माना है? Which Purushartha did Kautilya consider the Most Important in his ''Arthashastra''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('99c08c62-9bfd-4bd5-bf14-8625cbae6f2a', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', '''परम पुरुषार्थ'' (Supreme Purushartha) किसे कहा जाता है? Which is called the ''Supreme Purushartha'' (Parama Purushartha)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c90a39cf-19ab-4814-a7ee-5d3befe9d6d5', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'किस पुरुषार्थ का संबंध मुख्य रूप से ''गृहस्थ आश्रम'' से है? Which Purushartha is mainly related to ''Grihastha Ashrama''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('b1e74ba0-d203-4c8f-8321-bf44d557acf9', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', 'कथन (A): पुरुषार्थ व्यवस्था भौतिकवाद और आध्यात्मिकता के बीच संतुलन बनाती है।
कारण (R): इसमें अर्थ और काम (भौतिक) को धर्म (नैतिक) और मोक्ष (आध्यात्मिक) के साथ रखा गया है।
सही विकल्प चुनें: Assertion (A): Purushartha system balances Materialism and Spirituality.
Reason (R): It places Artha and Kama (Material) along with Dharma (Moral) and Moksha (Spiritual).
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fe5b1bab-5f19-40fc-bcf1-ebbef6bddc8a', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', '''काम'' (Kama) का व्यापक अर्थ भारतीय संस्कृति में क्या है? What is the broader meaning of ''Kama'' in Indian culture?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e306927d-316a-4570-bcf3-61888316f132', 'b6ba1b57-dcd9-4149-9a87-49f34ccd0106', '''धर्म'' (Dharma) शब्द किस धातु से बना है और इसका अर्थ क्या है? The word ''Dharma'' is derived from which root and what does it mean?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('29cedaf2-4085-41e9-be42-1a38185c133d', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'प्राचीन भारतीय परंपरा में मनुष्य जन्म से ही कितने ''ऋण'' (Debts) लेकर पैदा होता है? According to ancient Indian tradition, a human is born with how many ''Rins'' (Debts)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4b0783e9-a351-498f-a9eb-56641d2a1d82', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', '''पितृ ऋण'' (Pitra Rin) से मुक्ति कैसे मिलती है? How does one get liberation from ''Pitra Rin'' (Debt to Ancestors)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a6b7faa3-0507-46b1-8f53-6da0e2bc3766', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', '''स्वाध्याय'' (Self-study of Vedas) किस ऋण से मुक्ति का साधन है? ''Swadhyaya'' (Self-study of Vedas) is the means to get liberated from which Debt?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('00741d71-b4b4-4b47-b585-0a27ba20ce27', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'ऋण और उसे चुकाने के माध्यम को सुमेलित करें (Match the Debt with the means to repay it): Match the Debt with the means to repay it:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1bc25b7e-53f8-4eea-9047-f3ab85165190', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'ऋण व्यवस्था का सामाजिक महत्व क्या था? What was the social significance of the Rin system?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('87b1bc7f-60e6-4ec2-9b90-86265bb0e9c1', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'तैत्तिरीय संहिता में कितने ऋणों का उल्लेख है? How many Rins are mentioned in Taittiriya Samhita?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dd866192-8750-4388-817c-a2f00242b246', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'किस आश्रम में रहकर ''तीनों ऋणों'' को चुकाना संभव है? In which Ashrama is it possible to repay ''All Three Debts''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dd6f0c05-d1c3-4801-bb63-8a49fb5c0099', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'कथन (A): ''अनृणी'' (ऋण मुक्त) होना भारतीय जीवन का लक्ष्य था।
कारण (R): ऋणों को चुकाए बिना मोक्ष की प्राप्ति संभव नहीं मानी जाती थी।
सही विकल्प चुनें: Assertion (A): Becoming ''Anrini'' (Debt-free) was a goal of Indian life.
Reason (R): Attainment of Moksha was not considered possible without repaying debts.
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3abd6a15-db2d-4b63-a8bc-3770ae8d8c89', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', '''देव ऋण'' चुकाने के लिए कौन सा कार्य आवश्यक है? Which action is necessary to repay ''Deva Rin''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a2705658-1865-465d-99d7-ca28067735b4', 'e8fe7b65-a1a2-4e8c-8978-f018659318b0', 'किस ग्रंथ में ''चौथा ऋण'' (मनुष्य ऋण) जोड़ा गया है? In which text is the ''Fourth Debt'' (Manushya Rin) added?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('81881e6c-26c8-4f0d-a035-bdd7f98ac674', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'गौतम धर्मसूत्र के अनुसार संस्कारों की कुल संख्या कितनी मानी गई है? According to Gautama Dharmasutra, what is the total number of Sanskaras?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d2147621-83bb-4d7e-8c4b-cf59341388dc', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'गर्भावस्था के दौरान बच्चे के मानसिक विकास और अमंगल से रक्षा के लिए कौन सा संस्कार किया जाता है? Which Sanskara is performed during pregnancy for the mental development of the child and protection from evil?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('20aa41a9-652f-4d27-bd02-02cb85bbe85a', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'किस संस्कार को ''द्विजत्व'' (Second Birth) का द्वार माना जाता है? Which Sanskara is considered the gateway to ''Dwijatva'' (Second Birth)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('236eb6f8-e969-41e2-b952-4cad0fefb526', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'संस्कारों और उनके सही क्रम/उद्देश्य को सुमेलित करें (Match the Sanskaras with their correct order/purpose): Match the Sanskaras with their correct order/purpose:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('43ae185a-4a7d-48b0-ae8f-b26b72d36d52', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'शिक्षा समाप्ति पर गुरु के घर से लौटते समय कौन सा संस्कार किया जाता था? Which Sanskara was performed while returning from Guru''s house after completion of education?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1d9be508-25d3-4a0d-8bbe-96cdab37ce17', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', '16 संस्कारों में ''प्रथम'' और ''अंतिम'' संस्कार कौन से हैं? Which are the ''First'' and ''Last'' Sanskaras among the 16 Sanskaras?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('eac93726-8780-4901-9d4f-a56bad5555ef', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', '''केशांत'' (Keshanta) संस्कार को और किस नाम से जाना जाता था, जिसमें पहली बार दाढ़ी-मूंछ मुंडवाई जाती थी? By what other name was ''Keshanta'' Sanskara known, in which the beard and moustache were shaved for the first time?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4c65314d-6d5b-45d1-a686-eebf1a9a3a0b', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'प्राचीन काल में ''कर्णवेध'' (Karnavedha) संस्कार का मुख्य उद्देश्य क्या था? What was the main purpose of ''Karnavedha'' (Ear piercing) Sanskara in ancient times?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f18de201-527d-4e23-917d-126486ce2602', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'विवाह संस्कार में ''पाणिग्रहण'' (Panigrahana) का क्या अर्थ है? What is the meaning of ''Panigrahana'' in Vivaha Sanskara?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2fdee784-d5ae-4c3d-8018-baecb8abe456', '6aadf0a3-04a1-4419-b904-1afbb967fe4e', 'संस्कारों का मुख्य मनोवैज्ञानिक उद्देश्य (Psychological Purpose) क्या था? What was the main Psychological Purpose of Sanskaras?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('66a78014-93e9-4d6f-b742-d647b60edde2', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'मध्य प्रदेश में ''घोड़ाडोंगरी'' (बैतूल) का जंगल सत्याग्रह किस वर्ष हुआ था और इसका नेतृत्व किसने किया था? In which year did the ''Ghoradongri'' (Betul) Forest Satyagraha take place in MP and who led it?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('479d5814-74f1-4db3-bcd5-dda67ea09df9', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'निम्नलिखित में से किसे ''मध्य प्रदेश का जलियांवाला बाग'' कहा जाता है? Which of the following is known as the ''Jallianwala Bagh of Madhya Pradesh''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4cd67890-2846-4a04-aa60-7bc466e9a401', 'deddbde4-947b-43c0-8598-79c1c09e73e8', '1923 के ''झंडा सत्याग्रह'' के संबंध में कौन सा कथन सही है?
1. इसकी शुरुआत जबलपुर से हुई थी।
2. सुंदरलाल जैन को इसमें कारावास की सजा हुई थी।
3. बाद में इसका नेतृत्व नागपुर में सरदार पटेल ने किया।

सही विकल्प चुनें: Which statement is correct regarding the ''Jhanda Satyagraha'' of 1923?
1. It started from Jabalpur.
2. Sundarlal Jain was sentenced to imprisonment.
3. Later, its leadership was taken over by Sardar Patel in Nagpur.

Choose the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('b58aebe0-6c26-40ba-9200-2f711b2a0115', 'deddbde4-947b-43c0-8598-79c1c09e73e8', '1939 में कांग्रेस का ऐतिहासिक ''त्रिपुरी अधिवेशन'' मध्य प्रदेश के किस शहर के पास आयोजित हुआ था? Near which city of MP was the historic ''Tripuri Session'' of Congress held in 1939?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('23cd2589-a5c5-496b-9fcd-f4a4adf44f0f', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'क्रांतिकारी घटनाओं और उनके स्थानों को सुमेलित करें: Match the revolutionary events and their locations:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('09f36360-8ce0-4091-a614-97f97c1a9bc9', 'deddbde4-947b-43c0-8598-79c1c09e73e8', '1857 के विद्रोह के दौरान ''नीमच'' से विद्रोह की शुरुआत किस तारीख को हुई थी? On which date did the revolt start from ''Neemuch'' during the 1857 uprising?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d54045a7-003a-4290-b2ec-bdcd14d3eb79', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'इंदौर के पास ''महू'' छावनी में 1857 के विद्रोह का नेतृत्व किसने किया था? Who led the 1857 revolt in the ''Mhow'' cantonment near Indore?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2a33f074-628f-4cd8-af5b-20ffb4b15c19', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'चंद्रशेखर आज़ाद का जन्म मध्य प्रदेश के किस जिले में हुआ था (वर्तमान स्थिति के अनुसार)? In which district of MP was Chandra Shekhar Azad born (as per current status)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('00d17bc0-448a-4442-9d38-2eeafaccf527', 'deddbde4-947b-43c0-8598-79c1c09e73e8', 'सीहोर के टाउन हॉल में अंग्रेजों के खिलाफ लड़ते हुए कौन शहीद हुआ था, जिन्हें ''मध्य प्रदेश का मंगल पांडे'' कहा जाता है? Who was martyred while fighting against the British at the Town Hall of Sehore and is called the ''Mangal Pandey of MP''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('cff7c856-d117-45b3-a56e-45cef170204c', 'deddbde4-947b-43c0-8598-79c1c09e73e8', '1942 के ''भारत छोड़ो आंदोलन'' की शुरुआत मध्य प्रदेश में कहाँ से हुई थी? From where did the ''Quit India Movement'' start in Madhya Pradesh in 1942?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2bdfebe7-5b1b-435f-8676-096e0d10a324', '84f43923-f20e-4508-a23f-c3c345cb5536', 'हिमालय के अनुदैर्ध्य विभाजन (Longitudinal divisions) के संदर्भ में, निम्नलिखित में से कौन सा युग्म ''कुमाऊँ हिमालय'' की सीमाओं को सही ढंग से दर्शाता है? With reference to the longitudinal divisions of the Himalayas, which of the following pairs correctly represents the boundaries of the ''Kumaon Himalayas''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('597cdbad-e24d-44bb-9839-ac43510df521', '84f43923-f20e-4508-a23f-c3c345cb5536', 'प्रायद्वीपीय भारत की निम्नलिखित पहाड़ियों को उत्तर से दक्षिण दिशा (North to South) में व्यवस्थित करें:
1. नल्लामाला पहाड़ियाँ (Nallamala Hills)
2. नीलगिरी पहाड़ियाँ (Nilgiri Hills)
3. जावदी पहाड़ियाँ (Javadi Hills)
4. पालकोंडा पहाड़ियाँ (Palkonda Hills) Arrange the following hills of Peninsular India in North to South direction:
1. Nallamala Hills
2. Nilgiri Hills
3. Javadi Hills
4. Palkonda Hills');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('967f36a4-366d-43b7-ac72-c6e60c61e8bc', '84f43923-f20e-4508-a23f-c3c345cb5536', 'ट्रांस-हिमालय (Trans-Himalayas) के संबंध में निम्नलिखित कथनों पर विचार करें:
1. इसका निर्माण हिमालय से पूर्व हुआ था।
2. लद्दाख श्रेणी और ज़स्कर श्रेणी इसी का हिस्सा हैं।
3. माउंट गॉडविन-ऑस्टिन (K2) वृहद हिमालय (Great Himalayas) में स्थित है।
सही कथन कौन से हैं? Consider the following statements regarding Trans-Himalayas:
1. It was formed before the Himalayas.
2. Ladakh Range and Zaskar Range are part of it.
3. Mount Godwin-Austen (K2) is located in the Great Himalayas.
Which statements are correct?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c9a8e68f-701d-4417-a010-fa58b396bc7b', '84f43923-f20e-4508-a23f-c3c345cb5536', 'पश्चिमी घाट (Western Ghats) को स्थानीय रूप से महाराष्ट्र और कर्नाटक में ''सह्याद्रि'' कहा जाता है। 16° उत्तरी अक्षांश (जो गोवा से गुजरती है) सह्याद्रि को किन दो भागों में विभाजित करती है? The Western Ghats are locally known as ''Sahyadri'' in Maharashtra and Karnataka. The 16° N latitude (passing through Goa) divides the Sahyadri into which two parts?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4f83134c-6508-49a4-b2a3-5569edb8833c', '84f43923-f20e-4508-a23f-c3c345cb5536', 'निम्नलिखित में से कौन सा ''असम हिमालय'' की सबसे ऊंची चोटी है? Which of the following is the highest peak of the ''Assam Himalayas''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('755a0409-3f89-4f4d-85a9-eaeba390ea7e', '84f43923-f20e-4508-a23f-c3c345cb5536', 'निम्नलिखित में से कौन सी पहाड़ी श्रृंखला ''ब्लॉक पर्वत'' (Block Mountain) का एक उदाहरण है जो नर्मदा और ताप्ती नदियों के बीच स्थित है? Which of the following mountain ranges is an example of a ''Block Mountain'' situated between the Narmada and Tapti rivers?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('087a181b-3237-4c77-a966-d04091bf1b9f', '84f43923-f20e-4508-a23f-c3c345cb5536', 'पूर्वोत्तर भारत की ''लुशाई पहाड़ियाँ'' (Lushai Hills) किस पर्वत श्रृंखला का हिस्सा हैं और वे किस राज्य में प्रमुखता से स्थित हैं? The ''Lushai Hills'' of North-East India are part of which mountain range and are predominantly located in which state?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6c233793-c87c-4a3d-a6e6-6bbefe350a89', '84f43923-f20e-4508-a23f-c3c345cb5536', '''सिंटैक्सियल बेंड'' (Syntaxial Bend) के संदर्भ में, हिमालय दक्षिण की ओर तीखा मोड़ लेता है। पश्चिमी छोर पर यह मोड़ किस पर्वत के पास स्थित है? With reference to the ''Syntaxial Bend'', the Himalayas take a sharp southward turn. Near which mountain is this bend located on the Western end?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ae75e381-5579-4848-a181-45c56c14d162', '84f43923-f20e-4508-a23f-c3c345cb5536', 'दक्षिण भारत की सबसे ऊंची चोटी ''अनामुडी'' (Anamudi) निम्नलिखित में से किस पहाड़ी का हिस्सा है? South India''s highest peak ''Anamudi'' is part of which of the following hills?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0bd09068-7968-4fa1-981c-4ecb7d8bc0bb', '84f43923-f20e-4508-a23f-c3c345cb5536', 'निम्नलिखित पर्वत श्रेणियों को उनकी सर्वोच्च चोटियों के साथ सुमेलित करें (Match the following mountain ranges with their highest peaks): Match the following mountain ranges with their highest peaks:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c9ea4a54-6333-45b3-990a-ef08e0a9c3aa', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'खजुराहो के मंदिरों के संबंध में निम्नलिखित कथनों पर विचार करें:
1. इनका निर्माण 950-1050 ईस्वी के बीच चंदेल शासकों द्वारा किया गया था।
2. यहाँ के मंदिर नागर शैली के उत्कृष्ट उदाहरण हैं।
3. लक्ष्मण मंदिर का निर्माण राजा धंग देव ने करवाया था।

सही कथन चुनें: Consider the following statements regarding Khajuraho temples:
1. They were built between 950-1050 AD by Chandela rulers.
2. The temples here are excellent examples of Nagara style.
3. The Lakshmana Temple was built by King Dhanga Deva.

Choose the correct statement:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('71a2c878-2d7f-4b2d-b970-3b6c0bf5f696', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'धार स्थित ''बाघ की गुफाओं'' की तुलना अक्सर अजंता की गुफाओं से की जाती है। इन गुफाओं का संबंध किस धर्म से है? The ''Bagh Caves'' in Dhar are often compared to the Ajanta Caves. Which religion are these caves associated with?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5ef5dc43-5e69-4b7c-96c7-6521bdf12b41', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'विदिशा में स्थित ''हेलियोडोरस स्तंभ'' किस धर्म की लोकप्रियता का प्राचीनतम साक्ष्य है? The ''Heliodorus Pillar'' in Vidisha is the oldest evidence of the popularity of which religion?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('795eed09-f6dd-4de5-803a-a7a14d70e1d2', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'ग्वालियर किले में स्थित ''तेली का मंदिर'' किस वास्तुकला शैली का मिश्रण है? The ''Teli ka Mandir'' in Gwalior Fort is a blend of which architectural styles?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('041be048-75da-4687-80b1-2656e0abff33', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'स्थापत्य कला और उनके संबंधित स्थान को सुमेलित करें: Match the architecture and their respective locations:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ce471158-8469-4e86-9d38-c3687b22dfec', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'पिथोरा भित्ति चित्र (Wall Paintings) किस जनजाति की प्रमुख कला है? Pithora wall painting is a major art form of which tribe?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d053331c-fc7e-4d6b-bd6a-091b5508df34', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'उदयगिरि की गुफा संख्या 5 में किस देवता की प्रसिद्ध ''वराह अवतार'' की विशाल प्रतिमा है? In cave number 5 of Udayagiri, there is a famous massive idol of which deity''s ''Varaha'' incarnation?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('87da4823-fd0c-4da5-b9f5-ad86c9132dd8', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'भीमबेटका की खोज किसने की थी और यहाँ किस प्रकार की कला पाई जाती है? Who discovered Bhimbetka and what type of art is found here?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('73cab7b9-e383-4e60-9c3a-8e8bc365026b', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'चंदेरी साड़ियों को किस वर्ष भारत का पहला भौगोलिक संकेत (GI Tag) प्राप्त हुआ था? In which year did Chanderi sarees receive India''s first Geographical Indication (GI Tag)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('63fe2e05-ec8f-4d52-ba7e-d9794d4f1d01', '6756a60b-58fc-41c1-a3ce-b9ddc909d1ea', 'भरहुत स्तूप की कलाकृतियां वर्तमान में किस संग्रहालय में मुख्य रूप से सुरक्षित हैं? In which museum are the artifacts of Bharhut Stupa primarily preserved currently?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('55062dd2-6935-4716-b703-da8b2b382f2c', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'मध्य प्रदेश की ''भारिया'' जनजाति के संदर्भ में ''पातालकोट'' क्षेत्र किस जिले में स्थित है? In which district is the ''Patalkot'' region located with respect to the ''Bharia'' tribe of Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6f933f9d-595a-48a8-9594-ce7c0d57f31d', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'निम्नलिखित में से कौन सी जनजाति ''दूध लौटावा'' विवाह प्रथा का पालन करती है? Which of the following tribes follows the ''Doodh Lautawa'' marriage custom?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4ad5da2a-9f61-4ce2-ab37-f6f6e5f30459', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'बैगा जनजाति के प्रमुख देवता कौन हैं जो ''साज'' के वृक्ष में निवास करते हैं? Who is the primary deity of the Baiga tribe believed to reside in the ''Saaj'' tree?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('baa5deaa-0b23-4c48-b73f-bac2d0cfdddc', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'मध्य प्रदेश की किस जनजाति को ''आदिम जनजाति समूह'' (PVTG) में शामिल नहीं किया गया है? Which tribe of MP is NOT included in the ''Particularly Vulnerable Tribal Groups'' (PVTG)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('96f12b7c-82a7-40be-8c31-4eaf3874da43', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'जनजाति और उनके प्रमुख नृत्य को सुमेलित करें: Match the tribe with their primary dance:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('97bc4195-be21-4af9-9651-4788ad2a0257', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'सहारिया जनजाति का निवास स्थान ''सहराना'' कहलाता है। यह जनजाति मुख्य रूप से किस क्षेत्र में पाई जाती है? The residence of the Sahariya tribe is called ''Saharana''. In which region is this tribe primarily found?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ad886951-499e-4938-abe3-5d52d55ae771', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'भील जनजाति में ''दापा'' प्रथा का क्या अर्थ है? What does the ''Dapa'' custom mean in the Bheel tribe?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6a1a9329-9499-4526-881c-b15ae05e5df7', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'गोंड जनजाति की कौन सी उप-जाति लोहे का काम करने वाली मानी जाती है? Which sub-caste of the Gond tribe is considered to be iron-smiths?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e82a4150-11b5-41b5-a336-cf87c43ea445', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'जनजातियों के संबंध में निम्नलिखित कथनों पर विचार करें:
1. कोल जनजाति मध्य प्रदेश की तीसरी सबसे बड़ी जनजाति है।
2. ''गो हिया'' कोल जनजाति की पंचायत को कहा जाता है।
3. कोल जनजाति मुख्य रूप से रीवा-सीधी क्षेत्र में पाई जाती है।

सही कथन चुनें: Consider the following statements regarding tribes:
1. Kol is the third largest tribe of MP.
2. ''Gohiya'' is the name of the Kol tribe''s panchayat.
3. Kol tribe is mainly found in the Rewa-Sidhi region.

Choose the correct statement:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('04c2068f-fb76-4953-96e4-156e9123d37f', '9a03dfb5-13f4-45c4-96e0-b432283f234c', 'मध्य प्रदेश के झाबुआ में आयोजित होने वाले ''भगोरिया हाट'' में कौन सा पक्ष विवाह का प्रस्ताव ''गुलाल'' लगाकर देता है? In the ''Bhagoria Haat'' held in Jhabua, which side proposes marriage by applying ''Gulal''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5054cc8a-3c81-427c-b955-6ced062ce7dc', '0f904fbf-45cc-4965-8ae3-107af61a3e39', '''कुरुक'' (Kurukh) बोली मध्य प्रदेश की किस जनजाति द्वारा मुख्य रूप से बोली जाती है? The ''Kurukh'' dialect is primarily spoken by which tribe of Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2df0a905-b95f-48ee-9821-df42c201e8c1', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'निम्नलिखित में से कौन सी बोली ''ऑस्ट्रो-एशियाटिक'' (मुंडा) भाषा परिवार के अंतर्गत आती है? Which of the following dialects falls under the ''Austro-Asiatic'' (Munda) language family?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ee028d3f-9831-4942-828f-5222f2503822', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'भीली बोली के संबंध में ''सर्वेक्षण'' करने वाले पहले भाषाविद् कौन थे, जिन्होंने इसे ''भीली'' नाम दिया? Who was the first linguist to ''survey'' the Bhili dialect and give it the name ''Bhili''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2fe3bc9c-256f-4f49-a1d4-728893ac8071', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'निम्नलिखित कथनों पर विचार करें:
1. गोंडी बोली द्रविड़ भाषा परिवार की एक सदस्य है।
2. ''परधान'' गोंडों की वह उपजाति है जो गोंडी भाषा में लोक गाथाएं गाती है।
3. गोंडी की अपनी लिपि है जिसे ''गुंजल गोंडी'' कहा जाता है।

सही कथन चुनें: Consider the following statements:
1. Gondi dialect is a member of the Dravidian language family.
2. ''Pradhan'' is the sub-tribe of Gonds that sings folk epics in Gondi.
3. Gondi has its own script called ''Gunjala Gondi''.

Choose the correct statement:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('830f2caf-568e-4f71-b857-2a53802141b3', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'जनजाति और उनकी विशिष्ट बोली/भाषा को सुमेलित करें: Match the tribe and their specific dialect/language:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('555df591-39b5-49a6-b813-52efc3e81828', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'पातालकोट के भारियाओं द्वारा बोली जाने वाली बोली को क्या कहा जाता है? What is the dialect spoken by the Bhariyas of Patalkot called?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('69210068-3936-4667-bd5e-c9e10ad9cffd', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'मध्य प्रदेश की ''कोल'' जनजाति की बोली मुख्य रूप से किस भाषा से प्रभावित है? The dialect of the ''Kol'' tribe of MP is primarily influenced by which language?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9137699f-70aa-4a15-8b41-cc7ee37a8dd2', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'सहारिया जनजाति की बोली पर किस पड़ोसी राज्य की भाषा का सर्वाधिक प्रभाव देखा जाता है? The dialect of the Sahariya tribe shows the maximum influence of which neighboring state''s language?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c884fab7-562b-4c37-a956-450debbdfc85', '0f904fbf-45cc-4965-8ae3-107af61a3e39', 'मध्य प्रदेश में बोली जाने वाली ''निमाड़ी'' बोली को ''दक्षिणी हिंदी'' किसने कहा था? Who called the ''Nimadi'' dialect, spoken in MP, as ''Southern Hindi''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4d8987fa-4f03-4c22-bcdf-a36de3e0598f', '0f904fbf-45cc-4965-8ae3-107af61a3e39', '''बैगाली'' बोली मुख्य रूप से मध्य प्रदेश के किन जिलों में बोली जाती है? The ''Baigali'' dialect is primarily spoken in which districts of MP?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a4f95629-6f69-40de-a168-8b9774c6b596', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'पूर्वी घाट (Eastern Ghats) की निम्नलिखित पहाड़ियों को उत्तर से दक्षिण (North to South) क्रम में व्यवस्थित करें:
1. शेवरॉय पहाड़ियाँ (Shevaroy Hills)
2. जावदी पहाड़ियाँ (Javadi Hills)
3. पालकोंडा पहाड़ियाँ (Palkonda Hills)
4. सिरुमलाई पहाड़ियाँ (Sirumalai Hills) Arrange the following hills of the Eastern Ghats in North to South order:
1. Shevaroy Hills
2. Javadi Hills
3. Palkonda Hills
4. Sirumalai Hills');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2bbc5900-c563-4464-9bf6-fcc607a808da', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'प्रायद्वीपीय भारत में ''बाबा बुदन गिरी'' (Baba Budan Giri) पहाड़ियाँ किस अयस्क और फसल के लिए प्रसिद्ध हैं? For which ore and crop are the ''Baba Budan Giri'' hills in Peninsular India famous?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c3b71820-8bc2-494b-9352-ecb6b97f96ce', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'गुजरात में स्थित ''मांडव पहाड़ियाँ'' (Mandav Hills) का संबंध किस पर्वतमाला से नहीं है, बल्कि यह एक स्वतंत्र उच्चभूमि है। यह मुख्य रूप से किस जिले में है? ''Mandav Hills'' located in Gujarat are not related to any major mountain range but are an independent highland. In which district are they mainly located?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0dcdc761-5982-4848-a40d-3d1d004729de', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', '''बरैल रेंज'' (Barail Range) पूर्वोत्तर भारत में एक महत्वपूर्ण विभाजक है। यह किन दो पहाड़ियों को अलग करती है? ''Barail Range'' is an important divider in Northeast India. It separates which two hills?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9de87fc1-0c22-42da-b7cf-dd866aa37667', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'महाराष्ट्र की निम्नलिखित पर्वत श्रेणियों को उत्तर से दक्षिण (North to South) क्रम में लगाइए:
1. अजंता श्रेणी (Ajanta Range)
2. हरिश्चंद्र श्रेणी (Harishchandra Range)
3. सातमाला श्रेणी (Satmala Range) Arrange the following mountain ranges of Maharashtra in North to South order:
1. Ajanta Range
2. Harishchandra Range
3. Satmala Range');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a008cdf2-22b1-4456-9556-a8a3708e2f16', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', '''शेषाचलम पहाड़ियाँ'' (Seshachalam Hills), जो भारत का पहला बायोस्फीयर रिजर्व भी घोषित किया गया था (दक्षिण भारत में), किस पर्वत श्रृंखला का हिस्सा हैं? ''Seshachalam Hills'', which was also declared a Biosphere Reserve (in South India), is part of which mountain range?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('b4902352-31ea-4b2a-afc1-df3706ca7f3f', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'निम्नलिखित में से कौन सी पहाड़ियाँ ''मेघालय पठार'' का हिस्सा **नहीं** हैं, बल्कि असम हिमालय का हिस्सा मानी जाती हैं? Which of the following hills are **NOT** part of the ''Meghalaya Plateau'' but are considered part of the Assam Himalayas/Purvanchal?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('09f7317d-3c50-4219-87bc-2a183ba81f88', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'झारखंड में स्थित ''पारसनाथ पहाड़ी'' (Parasnath Hill) किस पठार/पहाड़ी श्रृंखला का सर्वोच्च शिखर है? ''Parasnath Hill'' in Jharkhand is the highest peak of which plateau/hill range?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4057e251-52b7-4967-8e6b-3954ba813618', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', '''डालमा पहाड़ियाँ'' (Dalma Hills) मुख्य रूप से किस राज्य में स्थित हैं और अपनी किस विशेषता के लिए जानी जाती हैं? ''Dalma Hills'' are primarily located in which state and are known for which feature?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fb677b96-e418-49fe-952d-5d683b9e0fb1', 'b48c33bc-6dce-40f6-ab8a-1efa5e621e58', 'निम्नलिखित पहाड़ियों को संबंधित राज्यों से सुमेलित करें (Match the following hills with their respective states): Match the following hills with their respective states:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0289b6f5-e977-4c60-895b-6b419db3c87e', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'छोटा नागपुर पठार में ''पैट भूमि'' (Patlands) क्या है? What are ''Patlands'' in the Chota Nagpur Plateau?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c03990cf-eb60-4947-b08f-8dd525618717', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'निम्नलिखित कथनों पर विचार करें:
1. मालदा गैप (Malda Gap) मेघालय पठार को प्रायद्वीपीय भारत से अलग करता है।
2. मालदा गैप का निर्माण गंगा और ब्रह्मपुत्र नदियों के अवसादन (Sedimentation) से भर जाने वाले भ्रंश (Fault) के कारण हुआ है।
सही कथन चुनें: Consider the following statements:
1. Malda Gap separates the Meghalaya Plateau from Peninsular India.
2. Malda Gap was formed due to a fault that was filled by sedimentation from Ganga and Brahmaputra rivers.
Choose the correct statement:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e48bd7a1-0022-4b3d-a459-fa2e693ac1f9', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'बुंदेलखंड पठार (Bundelkhand Plateau) की भूगर्भीय संरचना मुख्य रूप से किस चट्टान से बनी है, जिसके कारण यहाँ जल धारण क्षमता कम है? The geological structure of Bundelkhand Plateau is mainly composed of which rock, leading to low water retention capacity?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0b824721-0360-4dc5-add4-14bb6ccda9f4', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'दंडकारण्य पठार (Dandakaranya Plateau) भारत के किस हिस्से में स्थित है और यह किस नदी का बेसिन है? Dandakaranya Plateau is located in which part of India and is the basin of which river?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0661f8fa-da3e-4fa9-abef-e50fc5b3039b', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'दक्कन ट्रैप (Deccan Trap) के निर्माण के संदर्भ में, यह घटना किस काल (Period) से संबंधित है? With reference to the formation of the Deccan Trap, to which period does this event belong?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('99ef7d5e-1760-464f-883e-168f63c93fdd', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'मेवाड़ पठार (Mewar Plateau) अरावली और मालवा पठार के बीच स्थित है। यह किस नदी अपवाह तंत्र (Drainage System) का हिस्सा है? Mewar Plateau lies between Aravali and Malwa Plateau. It is part of which river drainage system?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8990f60c-a79a-43fd-a317-e3cb57daf96b', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'छोटा नागपुर पठार में ''दामोदर भ्रंश'' (Damodar Trough) किन दो सूक्ष्म पठारों को अलग करता है? In the Chota Nagpur Plateau, the ''Damodar Trough'' separates which two micro-plateaus?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('16a8e97f-a4e8-4539-8aab-4c425ed69af9', '9b8fb8ae-157c-4003-b07c-4665830aca5e', '''शिलॉन्ग शिखर'' (Shillong Peak) के संबंध में सही तथ्य क्या है? What is the correct fact regarding ''Shillong Peak''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('37556ce8-58ba-4490-ae0a-66a275a5ea4d', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'रायलसीमा पठार (Rayalaseema Plateau) भौगोलिक रूप से किस कारण से ''वृष्टि छाया क्षेत्र'' (Rain Shadow Region) बना हुआ है? Geographically, why does the Rayalaseema Plateau remain a ''Rain Shadow Region''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f4a57a70-787a-420d-b83e-fd999da2329c', '9b8fb8ae-157c-4003-b07c-4665830aca5e', 'निम्नलिखित पठारों को उनकी प्रमुख नदी/विशेषता से सुमेलित करें (Match the following plateaus with their major river/feature): Match the following plateaus with their major river/feature:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6c4d4f7e-9397-41af-bcbb-308e792556e7', '689ff095-5286-4197-ad00-fbad55edea78', 'गृहस्थों के लिए प्रतिदिन किए जाने वाले ''पंचमहायज्ञों'' में से कौन सा यज्ञ ''चींटियों, पक्षियों और अन्य जीवों'' के लिए भोजन देने से संबंधित है? Which of the daily ''Pancha Mahayagyas'' for householders is related to offering food to ''ants, birds, and other creatures''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4bf3f645-ab26-4d72-b14b-f10d32ed4d14', '689ff095-5286-4197-ad00-fbad55edea78', '''ब्रह्म यज्ञ'' (Brahma Yajna) का संपादन मुख्य रूप से कैसे किया जाता है? How is ''Brahma Yajna'' primarily performed?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dc3d2f67-c000-46bb-92a5-bd7c78b02778', '689ff095-5286-4197-ad00-fbad55edea78', 'मनुस्मृति के अनुसार ''अतिथि देवो भव'' की भावना किस महायज्ञ का मूल आधार है? According to Manusmriti, the spirit of ''Atithi Devo Bhava'' is the basis of which Mahayagya?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('7063c4b7-930e-4547-be0c-8aeedddffacc', '689ff095-5286-4197-ad00-fbad55edea78', 'पंचमहायज्ञों को उनके लाभार्थियों (Beneficiaries) से सुमेलित करें (Match the Pancha Mahayagyas with their Beneficiaries): Match the Pancha Mahayagyas with their Beneficiaries:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('62199a09-a1c8-4451-a8e9-2ed64904cafc', '689ff095-5286-4197-ad00-fbad55edea78', '''अग्निहोत्र'' (Agnihotra) किस प्रकार का यज्ञ है? What type of Yajna is ''Agnihotra''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('44b78537-96ff-46f0-af29-293df87546d7', '689ff095-5286-4197-ad00-fbad55edea78', 'पंचमहायज्ञ की अवधारणा का मुख्य सामाजिक उद्देश्य क्या है? What is the main social objective of the concept of Pancha Mahayagya?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('afd4c983-4df6-4a6b-8a6e-adff8616c61d', '689ff095-5286-4197-ad00-fbad55edea78', 'वैदिक काल में ''वाजपेय यज्ञ'' (Vajapeya Yajna) का मुख्य आकर्षण क्या था? What was the main attraction of the ''Vajapeya Yajna'' in the Vedic period?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2fec048a-daa6-4a6c-b83d-bb31ba695033', '689ff095-5286-4197-ad00-fbad55edea78', '''अश्वमेध यज्ञ'' (Ashvamedha Yajna) का मुख्य उद्देश्य क्या था? What was the main objective of ''Ashvamedha Yajna''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('daacf468-ae87-450f-a13f-3a801c536d96', '689ff095-5286-4197-ad00-fbad55edea78', 'कथन (A): ''श्राद्ध'' (Shraddha) पितृ यज्ञ का ही एक रूप है।
कारण (R): श्राद्ध में ''पिंडदान'' (Offering of rice balls) के माध्यम से पितरों को तृप्त किया जाता है।
सही विकल्प चुनें: Assertion (A): ''Shraddha'' is a form of Pitra Yajna.
Reason (R): In Shraddha, ancestors are satisfied through ''Pindadana'' (Offering of rice balls).
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e2b605ae-39e4-47ac-98aa-bec8ac69f54b', '689ff095-5286-4197-ad00-fbad55edea78', 'निम्नलिखित में से कौन सा यज्ञ ''सोम यज्ञ'' (Soma Sacrifice) की श्रेणी में आता है? Which of the following falls under the category of ''Soma Sacrifice''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4492bb41-2e86-406f-9b7f-9fa4907c8335', '56d1fe30-34a0-410e-893b-5bc629864355', 'भारतीय दर्शन में ''कर्म'' (Karma) का मूल अर्थ क्या है? What is the basic meaning of ''Karma'' in Indian philosophy?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('982c2958-5b57-410a-95ff-fcf7b0a9d4a1', '56d1fe30-34a0-410e-893b-5bc629864355', 'भगवद्गीता में ''निष्काम कर्म'' (Nishkama Karma) का क्या अर्थ बताया गया है? What is the meaning of ''Nishkama Karma'' as described in Bhagavad Gita?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dd0ce6dc-b71c-40fc-9db3-a9340c53b864', '56d1fe30-34a0-410e-893b-5bc629864355', 'कर्म के तीन प्रकारों में से ''प्रारब्ध कर्म'' (Prarabdha Karma) किसे कहते हैं? Among the three types of Karma, what is ''Prarabdha Karma''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5ce56510-e1b5-4414-9baf-16bbe4156c14', '56d1fe30-34a0-410e-893b-5bc629864355', 'कर्म के प्रकारों को उनकी परिभाषा से सुमेलित करें (Match the types of Karma with their definition): Match the types of Karma with their definition:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ad08e27f-14bd-4e44-b947-f2dda5acd629', '56d1fe30-34a0-410e-893b-5bc629864355', 'कर्म के सिद्धांत और ''पुनर्जन्म'' (Rebirth) के बीच क्या संबंध है? What is the relationship between the Principle of Karma and ''Rebirth''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ced894f7-ab89-4229-92c0-f006b389f199', '56d1fe30-34a0-410e-893b-5bc629864355', 'जैन दर्शन में कर्म को किस रूप में देखा जाता है? How is Karma viewed in Jain philosophy?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('42d737a3-32f1-447f-bf25-d87807e1de35', '56d1fe30-34a0-410e-893b-5bc629864355', 'कथन (A): ज्ञान प्राप्त होने पर ''संचित कर्म'' नष्ट हो जाते हैं।
कारण (R): ज्ञान अग्नि के समान है जो कर्मों को जला देता है।
सही विकल्प चुनें: Assertion (A): ''Sanchita Karmas'' are destroyed upon attaining Knowledge.
Reason (R): Knowledge is like fire which burns the Karmas.
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fc12110b-259a-44ca-b2af-e87f420d8e24', '56d1fe30-34a0-410e-893b-5bc629864355', '''क्रिया-प्रतिक्रिया'' (Action-Reaction) का नियम कर्म सिद्धांत के किस पक्ष को दर्शाता है? The law of ''Action-Reaction'' represents which aspect of Karma theory?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f03c47ea-a3f2-4c8a-a490-cabf16cd2e5e', '56d1fe30-34a0-410e-893b-5bc629864355', 'महर्षि पतंजलि के अनुसार कर्म के फल (विपाक) कितने प्रकार के होते हैं? According to Maharishi Patanjali, Karma-phala (Vipaka) results in how many forms?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('84933a89-2d65-4e7a-9e57-f0420e033697', '56d1fe30-34a0-410e-893b-5bc629864355', '''सकाम कर्म'' (Sakama Karma) का परिणाम क्या होता है? What is the result of ''Sakama Karma'' (Action with desire)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('66bd390e-006a-473a-956a-df9183228922', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', '''बोधिसत्व'' (Bodhisattva) की अवधारणा बौद्ध धर्म की किस शाखा की मुख्य विशेषता है? The concept of ''Bodhisattva'' is the central feature of which branch of Buddhism?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('de919a8f-6294-49f8-839c-7ada6db65f9a', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'किस बोधिसत्व को ''पद्मपाणि'' (Padmapani) भी कहा जाता है, जो हाथ में कमल धारण करते हैं? Which Bodhisattva is also known as ''Padmapani'', holding a Lotus in hand?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('74c19e82-0766-4f81-9488-6413af2a35e1', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'भविष्य में अवतार लेने वाले बुद्ध (Future Buddha) के रूप में किस बोधिसत्व को जाना जाता है? Which Bodhisattva is known as the ''Future Buddha'' destined to incarnate?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('415c11be-9948-42de-9c80-163e5c868f7a', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'बोधिसत्वों को उनके प्रतीक/विशेषता से सुमेलित करें (Match the Bodhisattvas with their attributes/symbols): Match the Bodhisattvas with their attributes/symbols:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a9f78e6c-701f-47f0-b3dd-94b8c4d683ac', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'बोधिसत्व बनने के लिए किन गुणों का विकास करना आवश्यक है? Which virtues are essential to develop to become a Bodhisattva?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('190ccc3a-c82f-4fe3-bfbd-dd1003554b7a', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'कथन (A): बोधिसत्व अपनी मुक्ति (निर्वाण) को स्थगित कर देते हैं।
कारण (R): उनका उद्देश्य ''महाकरुणा'' से प्रेरित होकर समस्त प्राणियों को दुख से मुक्त करना है।
सही विकल्प चुनें: Assertion (A): Bodhisattvas postpone their own liberation (Nirvana).
Reason (R): Their aim is guided by ''Great Compassion'' to liberate all beings from suffering.
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ce53656a-882c-4a11-ad24-99a82534d88f', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', '''अमिताभ'' (Amitabha) कौन हैं? Who is ''Amitabha''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2f1aee7c-e6c3-4d9f-ab49-767c0629a206', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'किस बोधिसत्व को ''वज्र'' (Thunderbolt) धारण करने के कारण ग्रीक देवता ''हरक्यूलिस'' या ''ज्यूस'' के समान माना गया है? Which Bodhisattva is considered similar to Greek god ''Hercules'' or ''Zeus'' because of holding a ''Vajra'' (Thunderbolt)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fbc6b672-6ced-4bcb-9586-f8a9da9bb763', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'महायान बौद्ध धर्म में ''प्रज्ञापारमिता'' (Prajnaparamita) का मानवीकरण किस रूप में किया गया है? In Mahayana Buddhism, ''Prajnaparamita'' is personified as:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3f5ffc13-35a8-4348-8873-e130d5b67239', '03a39879-965d-48ec-ba2a-ddf2a6f54d97', 'किस बोधिसत्व का संबंध ''जापान'' में बच्चों और यात्रियों के संरक्षक (Jizo) के रूप में है? Which Bodhisattva is associated as the guardian of children and travelers (Jizo) in Japan?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9f5cd76e-1fd2-42cb-abf4-e10038cb69b1', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'जैन धर्म में ''तीर्थंकर'' का शाब्दिक अर्थ क्या है? What is the literal meaning of ''Tirthankara'' in Jainism?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('b02ebc8c-79c0-4dbe-860a-357eac50886a', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'प्रथम तीर्थंकर ऋषभदेव (आदिनाथ) का प्रतीक चिन्ह (Symbol) क्या है? What is the symbol of the first Tirthankara Rishabhdeva (Adinatha)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('66dfbfe2-ab39-4490-a205-d76af0987c05', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', '23वें तीर्थंकर पार्श्वनाथ ने ''चातुर्याम धर्म'' (Fourfold restraint) प्रतिपादित किया था। महावीर स्वामी ने उसमें पांचवां कौन सा व्रत जोड़ा? 23rd Tirthankara Parsvanath propounded ''Chaturyama Dharma''. Which fifth vow did Mahavira Swami add to it?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('231639af-1ea6-4b19-a328-1fa5875f4f3c', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'तीर्थंकरों को उनके प्रतीक चिन्ह से सुमेलित करें (Match the Tirthankaras with their Symbols): Match the Tirthankaras with their Symbols:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('60645def-0007-4886-b736-c1eeb48b75ba', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'किस तीर्थंकर को ऐतिहासिक रूप से प्रथम प्रमाणित (First Historically Verified) माना जाता है? Which Tirthankara is considered the ''First Historically Verified'' figure?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d02fabb7-197c-49cf-bc7e-399f6774b695', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'श्वेतांबर परंपरा के अनुसार, एकमात्र ''स्त्री'' तीर्थंकर कौन थीं? According to Shvetambara tradition, who was the only ''Female'' Tirthankara?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6a0b70ae-3c81-4a48-aea7-8da7abc63dbd', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'महावीर स्वामी को किस नदी के तट पर ''कैवल्य'' (पूर्ण ज्ञान) की प्राप्ति हुई थी? On the banks of which river did Mahavira Swami attain ''Kaivalya'' (Omniscience)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2920c4f4-cae3-4049-a343-0cc54560e4a2', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'किस तीर्थंकर का संबंध भगवान श्री कृष्ण का ''निकट संबंधी'' (Cousin) माना जाता है? Which Tirthankara is considered a ''Close Relative'' (Cousin) of Lord Krishna?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('aaafb41c-7c47-4073-8317-0025b53a94e4', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', 'जैन धर्म के ''त्रिरत्न'' (Three Jewels) में निम्नलिखित में से कौन शामिल नहीं है? Which of the following is NOT included in the ''Triratna'' (Three Jewels) of Jainism?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5930387d-f8ff-4608-8f64-ab00354d4018', 'e91e6175-e8ab-4b09-b4ef-7172ea9cb05d', '''स्याद्वाद'' (Syadvada) या ''सप्तभंगी नय'' किस धर्म का मौलिक दार्शनिक सिद्धांत है? ''Syadvada'' or ''Saptabhangi Naya'' is the fundamental philosophical doctrine of which religion?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dfbd976c-a51f-4334-8edc-dbf75fe8a05f', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', '''लोकरंग महोत्सव'' का आयोजन प्रतिवर्ष भोपाल में किस अवसर पर किया जाता है? On which occasion is the ''Lokrang Mahotsav'' organized annually in Bhopal?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9d4d1989-5ea5-4441-ba83-1f4ca672d804', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'बघेलखंड क्षेत्र में ''हरेली'' त्योहार के दौरान किस देवता की पूजा की जाती है, जो मुख्य रूप से किसानों का त्योहार है? Which deity is worshipped during the ''Hareli'' festival in the Baghelkhand region, primarily a farmers'' festival?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('080d6d77-4872-412c-9a8f-eb2dd2fdc2de', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'मालवा क्षेत्र में कुंवारी कन्याओं द्वारा मनाया जाने वाला ''संजा'' (Sanjha) उत्सव किस समय मनाया जाता है? At what time is the ''Sanjha'' festival celebrated by unmarried girls in the Malwa region?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('41f2d258-4565-4b8c-aadd-a35e8580a234', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'खजुराहो नृत्य समारोह की शुरुआत किस वर्ष हुई थी और यह किस माह में आयोजित किया जाता है? In which year did the Khajuraho Dance Festival start and in which month is it organized?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f9d167b5-fbc1-40d3-9be6-f379e152f008', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'महोत्सव और उनके आयोजन स्थल को सुमेलित करें: Match the festivals and their venues:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('34753b32-cb7a-47b8-9275-89c84d6fdc87', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'गोंड जनजाति द्वारा मनाया जाने वाला ''लारू काज'' (Laru Kaj) उत्सव किसके सम्मान में मनाया जाता है? In whose honor is the ''Laru Kaj'' festival, celebrated by the Gond tribe, held?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('aa0318e1-1b31-4b59-997d-6a30c4261f8e', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'बुंदेलखंड में प्रचलित ''नौरता'' (Navrata) त्योहार के बारे में क्या सही है? What is correct about the ''Navrata'' festival prevalent in Bundelkhand?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9f0e395c-d9e0-4dd7-8a34-79e03fe5036b', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'भील जनजाति का ''भगोरिया'' उत्सव होली के कितने दिन पहले शुरू होता है? How many days before Holi does the ''Bhagoria'' festival of the Bheel tribe begin?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('71446862-1332-46f0-9682-5ef15b3a2513', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'मध्य प्रदेश के किस जिले में ''आलमी तबलीगी इज्तिमा'' का आयोजन किया जाता है, जो दुनिया के सबसे बड़े मुस्लिम समागमों में से एक है? In which district of MP is the ''Alami Tablighi Ijtima'' organized, one of the world''s largest Muslim congregations?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('7b38b36e-4d65-4dfa-aecb-9871ae5c8471', 'e6066c62-ccd2-48e4-9e48-ef250d2caef1', 'मालवा का ''नोन-दौरा'' (Noh-Dora) पर्व किससे संबंधित है? The ''Noh-Dora'' festival of Malwa is related to which of the following?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8eKwhIJX_q-NawR6YNVkF', '-chUrwczP5DdYXa_jZP2M', 'संचार में ''पैराफ्रेजिंग'' (Paraphrasing) का क्या महत्व है? What is the importance of ''Paraphrasing'' in communication?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('GuBQuVxKv3FATtAJRcnDu', '-chUrwczP5DdYXa_jZP2M', 'संचार के अवरोधों (Barriers) को उनके उदाहरणों से सुमेलित करें: Match Communication Barriers with their examples:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2nnSaYF2OrbGdymI9_Dnn', '-chUrwczP5DdYXa_jZP2M', 'एक प्रभावी संचारक के लिए ''सहानुभूति'' (Empathy) और ''समानुभूति'' (Sympathy) में क्या अंतर है? What is the difference between ''Empathy'' and ''Sympathy'' for an effective communicator?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('Gq68deHLRC0l2wBLfJsBt', '-chUrwczP5DdYXa_jZP2M', 'यदि किसी कूट भाषा में ''DELHI'' को ''CCIDD'' लिखा जाता है, तो ''BOMBAY'' को क्या लिखा जाएगा? If ''DELHI'' is coded as ''CCIDD'', how is ''BOMBAY'' coded?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('wktbWzzJVE4dUqv4mZ2fl', '-chUrwczP5DdYXa_jZP2M', 'एक घड़ी में 4:30 बज रहे हैं। यदि मिनट की सुई पूर्व की ओर है, तो घंटे की सुई किस दिशा में होगी? It is 4:30 in a clock. If the minute hand points East, in which direction is the hour hand?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('-pulcMZGMJrNMiOTbxq1u', '-chUrwczP5DdYXa_jZP2M', 'अगला पद ज्ञात करें: 2, 10, 30, 68, ? Find the next term: 2, 10, 30, 68, ?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4eRIOrGgCCrgZPCIFmTuP', '-chUrwczP5DdYXa_jZP2M', 'कथन: कोई भी मोबाइल घड़ी नहीं है। सभी घड़ियां कैलकुलेटर हैं। निष्कर्ष: (I) कोई कैलकुलेटर मोबाइल नहीं है। (II) कुछ कैलकुलेटर घड़ियां हैं। Statements: No mobile is a watch. All watches are calculators. Conclusions: (I) No calculator is a mobile. (II) Some calculators are watches.');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('NJ14IN6GzcdZO9E1E8hE-', '-chUrwczP5DdYXa_jZP2M', 'यदि ''A'' की आय ''B'' से 25% अधिक है, तो ''B'' की आय ''A'' से कितने प्रतिशत कम है? If A''s income is 25% more than B, by what percent is B''s income less than A?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('Gg3s6mKSavROvE2FhiIFG', '-chUrwczP5DdYXa_jZP2M', 'एक नाव शांत जल में 10 किमी/घंटा की गति से चलती है। यदि धारा की गति 2 किमी/घंटा है, तो धारा के प्रतिकूल 24 किमी जाने में कितना समय लगेगा? Boat speed in still water is 10 km/hr. Stream speed is 2 km/hr. Time taken to go 24 km upstream?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('WLhfZGnfJJ10V05CjrqJ1', '-chUrwczP5DdYXa_jZP2M', 'शब्द ''EDUCATION'' के अक्षरों से कितने 4 अक्षरों वाले शब्द बनाए जा सकते हैं (बिना दोहराव के)? How many 4-letter words can be formed from ''EDUCATION'' (no repetition)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1FiXKaXANhEZE2erGX3an', '-chUrwczP5DdYXa_jZP2M', 'यदि ''15 अगस्त 2003'' को शुक्रवार था, तो ''15 अगस्त 2004'' को कौन सा दिन था? If 15 Aug 2003 was Friday, what day was 15 Aug 2004?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0hL6FZ29RcaVU2e_b_tgI', '-chUrwczP5DdYXa_jZP2M', 'A और B किसी काम को 15 दिनों में करते हैं। B और C उसी काम को 20 दिनों में, और C और A 30 दिनों में करते हैं। A अकेले उसे कितने दिनों में करेगा? A+B do work in 15 days, B+C in 20 days, C+A in 30 days. How many days for A alone?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('zw3gLTS7xGqXSVk07vfoI', '-chUrwczP5DdYXa_jZP2M', 'रीजनिंग: बेमेल चुनें (Odd One Out): Reasoning: Choose the Odd One Out:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('upXT1h3rL8V2BZMsHjdnh', '-chUrwczP5DdYXa_jZP2M', 'एक समचतुर्भुज (Rhombus) के विकर्ण 16 सेमी और 30 सेमी हैं। उसका परिमाप ज्ञात करें। Diagonals of a Rhombus are 16 cm and 30 cm. Find its perimeter.');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('uQ604byJKsL4VUuKjb6iv', '-chUrwczP5DdYXa_jZP2M', 'वेन आरेख: ''डॉक्टर, पुरुष, अभिनेता'' का सही प्रतिनिधित्व कौन करता है? Venn Diagram: Which represents ''Doctor, Male, Actor''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('x-rzVWhv-bNvrFqHErs1e', '-chUrwczP5DdYXa_jZP2M', 'नैतिक निर्णय: आपके कार्यालय में एक वरिष्ठ सहकर्मी महिला कर्मचारियों के प्रति अनुचित टिप्पणी करता है। कोई शिकायत नहीं करता क्योंकि वह प्रभावशाली है। आप क्या करेंगे? Ethical Decision: A senior colleague makes inappropriate comments to female staff. No one complains as he is influential. What will you do?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fS-a1PJvZReQZT0NTVYoW', '-chUrwczP5DdYXa_jZP2M', 'दो संख्याओं का अनुपात 3:4 है। यदि प्रत्येक में 6 जोड़ा जाए, तो अनुपात 4:5 हो जाता है। संख्याओं का अंतर क्या है? Two numbers are in ratio 3:4. If 6 is added to each, ratio becomes 4:5. Difference of numbers?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ycPw9W1qsUzVp6YzaSiqO', '-chUrwczP5DdYXa_jZP2M', 'एक दुकानदार 1 किलो चाय के साथ 50 ग्राम धूल मिलाता है। यदि वह मिश्रण को चाय के क्रय मूल्य पर बेचता है, तो उसका लाभ % क्या है? A shopkeeper mixes 50g dust with 1kg tea. Sells mixture at Cost Price of tea. Profit %?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('mUNyXV2ipTJ73ykljAY39', '-chUrwczP5DdYXa_jZP2M', '50 छात्रों की एक कक्षा का औसत वजन 45 किलो है। यदि शिक्षक का वजन शामिल किया जाए, तो औसत 500 ग्राम बढ़ जाता है। शिक्षक का वजन क्या है? Average weight of 50 students is 45kg. If teacher included, avg increases by 500g. Teacher''s weight?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('QbWvR1Vt1mPIg97mbXr0I', '-chUrwczP5DdYXa_jZP2M', 'यदि ''P'' का अर्थ ''÷'', ''Q'' का अर्थ ''×'', ''R'' का अर्थ ''+'', ''S'' का अर्थ ''-'' है, तो: 18 Q 12 P 4 R 5 S 6 = ? If P=÷, Q=×, R=+, S=-, then 18 Q 12 P 4 R 5 S 6 = ?');
