INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4430c6e5-143a-4130-83ba-78fd6dcfece2', '236e9574-e114-4b26-b1d1-63356903da51', 'अलाउद्दीन खिलजी की ''बाजार नियंत्रण नीति'' (Market Control Policy) का मुख्य उद्देश्य क्या था? What was the main objective of Alauddin Khilji''s ''Market Control Policy''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ec232263-080a-499a-a4a0-863a8511e0ef', '236e9574-e114-4b26-b1d1-63356903da51', 'शिवाजी के प्रशासन ''अष्टप्रधान'' (Ashtapradhan) में वित्त मंत्री को क्या कहा जाता था? What was the Finance Minister called in Shivaji''s ''Ashtapradhan'' administration?');
