INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('94237344-d84f-494b-ab29-8760045832ee', '236e9574-e114-4b26-b1d1-63356903da51', 'दिल्ली सल्तनत में ''दीवान-ए-आरिज'' (Diwan-i-Arz) किस विभाग से संबंधित था? In Delhi Sultanate, ''Diwan-i-Arz'' was related to which department?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0812e430-84cf-48db-a2d5-c8d602a917f4', '236e9574-e114-4b26-b1d1-63356903da51', 'मुगल काल में ''दहसाला'' (Dahsala) भू-राजस्व प्रणाली किसने तैयार की थी? Who devised the ''Dahsala'' land revenue system in Mughal period?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('814aed5c-f524-4a5f-8475-371d6320e22b', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'बुंदेलखंड की प्रसिद्ध ''सुरैती'' (Suraiti) लोक कला का संबंध किस अवसर से है? With which occasion is the famous ''Suraiti'' folk art of Bundelkhand associated?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('69338243-9faf-4d51-9c3a-7ab7307ef5c0', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'निमाड़ क्षेत्र में ''थापा'' (Thapa) लोक कला मुख्य रूप से किस अवसर पर बनाई जाती है? In which occasion is the ''Thapa'' folk art primarily made in the Nimar region?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('55c27ed2-f68f-40fa-a8cb-d48fb4ce913e', '3e0ca47f-d690-4c9f-9df3-317b8cc08864', 'बघेलखंड की ''कोहबर'' (Kohbar) चित्रकला के संबंध में कौन सा कथन सही है?
1. यह विवाह के अवसर पर बनाई जाती है।
2. इसमें वैवाहिक जोड़े के इष्टदेव का चित्रण होता है।
3. यह केवल पुरुष कलाकारों द्वारा बनाई जाती है।

