INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('7f9828de-a388-40ad-a6a6-cd2511b78947', 'bfac4716-0179-4db8-ba56-0572455da619', 'ओंकारेश्वर ज्योतिर्लिंग के संबंध में कौन सा कथन सत्य है?
