INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('266b7e77-1744-4c27-b556-55964769ba61', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'मध्य प्रदेश राज्य वन विकास निगम (MPSFDC) की स्थापना किस वर्ष की गई थी? In which year was the Madhya Pradesh State Forest Development Corporation (MPSFDC) established?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c448343c-3841-49bc-9517-75bc8f5b71ca', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'भारतीय वन स्थिति रिपोर्ट (ISFR) 2021 के अनुसार, मध्य प्रदेश के किस जिले में सर्वाधिक वन क्षेत्र (Area wise) पाया जाता है? According to the India State of Forest Report (ISFR) 2021, which district of MP has the maximum forest cover (Area wise)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('208b5407-8abd-4de4-a451-b625161d66dc', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'निम्नलिखित में से कौन सी वनोपज मध्य प्रदेश में ''हरा सोना'' (Green Gold) के नाम से जानी जाती है? Which of the following forest produce is known as ''Green Gold'' in Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('32c9f3a4-4d7f-4665-8f43-23b7bfe55145', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'प्रशासनिक आधार पर मध्य प्रदेश के वनों को तीन श्रेणियों में बाँटा गया है। इनमें से किसका प्रतिशत सर्वाधिक है? Based on administrative classification, forests of MP are divided into three categories. Which of these has the highest percentage?');
