INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('83124348-d1b3-420f-bb7b-12fc473e2123', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'मध्य प्रदेश की पहली ''वन नीति'' किस वर्ष घोषित की गई थी? In which year was the first ''Forest Policy'' of Madhya Pradesh announced?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8f52cdde-d7a1-4c69-a798-d9f671129843', '7f8fca5c-b82f-46ac-8275-0d539b3d6f51', 'उष्णकटिबंधीय पर्णपाती वनों (Tropical Deciduous Forests) के संबंध में निम्नलिखित कथनों पर विचार करें:
1. ये वन 75 से 100 सेमी वर्षा वाले क्षेत्रों में पाए जाते हैं।
2. सागौन इन वनों का मुख्य वृक्ष है।
3. ये वन ग्रीष्म ऋतु में अपनी पत्तियाँ गिरा देते हैं।

सही कथन चुनें: Consider the following statements regarding Tropical Deciduous Forests:
1. These forests are found in areas with 75-100 cm rainfall.
2. Teak is the main tree of these forests.
3. These forests shed their leaves in the summer season.

Choose the correct statement:');
