INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6727e58f-e7e3-4590-be71-a98edef81817', '22b17d52-e183-4bbe-bc36-1cef0f1ef5e4', 'मध्य प्रदेश की नदियों के संबंध में निम्नलिखित कथनों पर विचार करें:
1. वर्धा और वैनगंगा के संगम को ''प्राणहिता'' कहा जाता है।
2. वेनगंगा दक्षिण की ओर बहने वाली प्रमुख नदी है।
3. पेंच नदी वैनगंगा की सहायक है।

सही कथन चुनें: Consider the following statements regarding the rivers of MP:
1. The confluence of Wardha and Wainganga is called ''Pranhita''.
2. Wainganga is a major South-flowing river.
3. Pench river is a tributary of Wainganga.

Choose the correct statement:');
