INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('76064565-a8cc-43bf-9db2-88fa918ed80e', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'गुप्त कालीन मंदिर ''भीतरगाँव मंदिर'' (Bhitargaon Temple) की क्या विशेषता है? What is unique about the Gupta era ''Bhitargaon Temple''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9cc31127-d2b0-4cab-9dba-d585b284e3a0', 'd4fe15f9-faf0-42cb-a8d1-11831db84a5c', 'दार्शनिक आधार पर ''शिल्प शास्त्र'' (Shilpa Shastra) का मुख्य उद्देश्य क्या था? Philosophically, what was the primary objective of ''Shilpa Shastra''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dc85b375-c3e3-4f45-923c-1d9c501d0cf6', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मध्य प्रदेश के सर्वाधिक भू-भाग पर कौन सी मिट्टी पाई जाती है? Which soil is found over the maximum geographical area of Madhya Pradesh?');
