INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8b99ea32-8abc-4832-988f-7a981172755f', '321e54b4-0d2b-48d7-bfd1-325b8c91be1d', 'मिट्टी के संबंध में निम्नलिखित कथनों पर विचार करें:
