INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9c07bdb7-49b8-4038-8626-0eb07e7cef22', '33465b70-011e-45d7-92f3-5081351cc436', 'किस प्राचीन अभिलेख में पहली बार ''भारतवर्ष'' (Bharadhavasa) शब्द का स्पष्ट उल्लेख मिलता है? In which ancient inscription is the term ''Bharatvarsha'' (Bharadhavasa) clearly mentioned for the first time?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('930f5cf2-5f30-49f0-9658-041b78f3c325', '33465b70-011e-45d7-92f3-5081351cc436', 'प्राचीन भारतीय भूगोल में ''जम्बुद्वीप'' (Jambudvipa) के अंतर्गत भारत को किस नाम से जाना जाता था? In ancient Indian geography, by what name was India known within ''Jambudvipa''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0b04a512-ff8e-425a-8203-a15cb931b438', '33465b70-011e-45d7-92f3-5081351cc436', 'कथन (A): प्राचीन यूनानियों (Greeks) ने भारत के लिए ''इण्डिया'' (India) शब्द का प्रयोग किया।
कारण (R): वे सिन्धु नदी को ''इण्डोस'' (Indos) कहते थे।
