INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3f66d577-ee42-4a7e-a2d6-f61cf72a2fc0', '33465b70-011e-45d7-92f3-5081351cc436', 'मनुस्मृति में ''ब्रह्मावर्त'' (Brahmavarta) क्षेत्र किसे कहा गया है? Which region is called ''Brahmavarta'' in Manusmriti?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('115d2e19-2151-438f-bf41-adc7a00fc94a', '33465b70-011e-45d7-92f3-5081351cc436', 'पुराणों में वर्णित ''नवकौमार'' या ''नौ खंड'' (Nine Divisions) की संकल्पना भारतवर्ष के किस संदर्भ में है? The concept of ''Navakaumara'' or ''Nine Divisions'' mentioned in Puranas is in context of what for Bharatvarsha?');
