INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('08e8f4c0-95ba-41b3-a5a3-59a24b880005', '33465b70-011e-45d7-92f3-5081351cc436', 'बौद्ध ग्रन्थ ''दीघ निकाय'' में भारत की भौगोलिक आकृति को किस प्रकार वर्णित किया गया है? How is the geographical shape of India described in the Buddhist text ''Digha Nikaya''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ff18d4d4-4f4a-4a56-90a7-cc9bd73de80c', '33465b70-011e-45d7-92f3-5081351cc436', 'प्राचीन भारतीय ''आर्यावर्त'' (Aryavarta) की दक्षिणी सीमा किस पर्वत श्रृंखला को माना जाता था? Which mountain range was considered the southern boundary of ancient Indian ''Aryavarta''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1cb5b778-4729-4a38-8e5a-f6f698275cea', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'मध्य प्रदेश में सिंचाई का सबसे प्रमुख साधन कौन सा है? Which is the most prominent source of irrigation in Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3459cfb7-0723-43ca-a121-72f6f394cef9', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'मध्य प्रदेश की पहली ''जल विद्युत परियोजना'' (Hydro-electric Project) कौन सी है? Which is the first Hydro-electric Project of Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f70fec00-2cad-4e7c-82ce-a3cedda45f26', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', '''बाणसागर परियोजना'' किन तीन राज्यों की संयुक्त परियोजना है? ''Bansagar Project'' is a joint project of which three states?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('963f03b9-4611-41eb-9a19-dfd3f2a8694c', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'नर्मदा नदी पर निर्मित ''इंदिरा सागर बाँध'' की ऊँचाई कितनी है, जो भारत के सबसे ऊँचे बाँधों में से एक है? What is the height of ''Indira Sagar Dam'' built on the Narmada river?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6c86c56b-9442-46fc-9b16-0ddc9345bec7', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'परियोजनाओं और उनके उपनामों/संबंधित व्यक्तित्वों को सुमेलित करें: Match projects with their aliases/associated personalities:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3af01473-0c08-4add-a1b8-c6c783e66c41', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'मध्य प्रदेश के किस जिले में ''तालाबों'' द्वारा सर्वाधिक सिंचाई की जाती है? In which district of MP is maximum irrigation done through ''Tanks''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('46f4daca-9535-42bd-8204-a6009b58086b', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'नर्मदा बचाओ आंदोलन'' की शुरुआत किस वर्ष हुई थी और इसकी मुख्य नेता कौन हैं? In which year did the ''Narmada Bachao Andolan'' start and who is its primary leader?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('7ce62016-af1c-48a0-9b8a-8566669193da', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'मध्य प्रदेश की किस नदी को ''नदियों को जोड़ने'' (River Linking) की पहली परियोजना में शामिल किया गया था? Which river of MP was included in the first River Linking Project?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('717d82db-e622-4e9a-a470-729bea0f9638', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'बरगी बाँध (रानी अवंतीबाई सागर) किस नदी पर और किस जिले में स्थित है? Bargi Dam (Rani Avantibai Sagar) is located on which river and in which district?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f9df55a3-57c0-4fbc-a445-d6bd427b7f7e', '8f4e43eb-56c3-41f3-ad84-40060ddf0f36', 'मध्य प्रदेश के किस जिले को ''सिंचाई का द्वीप'' कहा जाता है क्योंकि वहाँ चारों ओर से सिंचाई परियोजनाओं का लाभ मिलता है? Which district is called the ''Island of Irrigation'' in MP?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8cbe36e1-2cad-427e-ac97-ab427863f015', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'हरित क्रांति शब्द (Term) का प्रयोग सबसे पहले किसके द्वारा किया गया था? Who coined the term ''Green Revolution'' for the first time?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5f85c785-5cfc-4704-a0ba-d95234eb3bc9', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'भारत में हरित क्रांति की शुरुआत किस पंचवर्षीय योजना (Five Year Plan) के दौरान मानी जाती है? The beginning of Green Revolution in India is considered during which Five Year Plan?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d45df4af-a078-46a2-af61-3023355a81c0', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'नॉर्मन बोरलॉग (Norman Borlaug) ने किस देश में उच्च उपज वाली गेहूं की किस्मों (HYV) को विकसित किया था? In which country did Norman Borlaug develop the High Yielding Varieties (HYV) of wheat?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('69be41b1-06e1-405a-91bf-ac4c8dcc3998', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'हरित क्रांति के नकारात्मक प्रभावों (Negative Impacts) में निम्नलिखित में से क्या शामिल नहीं है? Which of the following is NOT included in the negative impacts of the Green Revolution?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('798329bb-431f-4310-ab51-0909e387b5b4', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'हरित क्रांति के घटक (Components) क्या थे?
1. HYV बीज
2. रासायनिक उर्वरक
3. सिंचाई विस्तार
4. जैविक खेती What were the components of Green Revolution?
1. HYV Seeds
2. Chemical Fertilizers
3. Irrigation Expansion
4. Organic Farming');
