INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a19aff20-768e-45f3-a27b-fbddaf42e1be', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'निम्नलिखित में से किसने हरित क्रांति के आलोचक के रूप में ''वंदना शिवा'' (Vandana Shiva) की तरह तर्क दिया कि इसने ''हिंसा'' को जन्म दिया? Who among the following, like Vandana Shiva, argued as a critic of Green Revolution that it led to ''violence''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1a340540-4acd-47f3-bde3-52aea5bd017e', '5aedb15d-dfbf-4205-849d-31bedc1c8100', 'हरित क्रांति के दौरान, भारत सरकार ने किसानों को मूल्य सुरक्षा प्रदान करने के लिए कौन सी संस्था स्थापित की थी? During the Green Revolution, which institution was set up by Govt of India to provide price security to farmers?');
