INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('42b79dc8-67f8-4c56-a7e3-d391819f1094', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'यम और नचिकेता का प्रसिद्ध संवाद किस उपनिषद में वर्णित है? The famous dialogue between Yama and Nachiketa is described in which Upanishad?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e86c272d-7c0a-4daf-a65a-5fdfa3adcebb', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'पुनर्जन्म (Rebirth) के सिद्धांत का सर्वप्रथम स्पष्ट उल्लेख किस उपनिषद में मिलता है? Which Upanishad provides the first clear mention of the doctrine of Rebirth?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f110244d-ab69-45ac-b671-4a0653cfe4a1', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'कथन (A): उपनिषदों को ''वेदांत'' कहा जाता है।
कारण (R): ये वैदिक साहित्य के अंतिम भाग हैं और वेदों के दार्शनिक निष्कर्ष प्रस्तुत करते हैं।
सही विकल्प चुनें: Assertion (A): Upanishads are called ''Vedanta''.
Reason (R): They are the final parts of Vedic literature and present the philosophical conclusions of the Vedas.
Select the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('7f6c1af5-ec23-4951-95f8-bb8df3e39173', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'उपनिषदों के प्रसिद्ध उद्धरणों को उनके स्रोत से सुमेलित करें (Match the quotes with their Upanishads): Match the famous Upanishadic quotes with their sources:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('72038a38-264d-4ef8-9d10-57996c19191c', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'किस उपनिषद में ''यज्ञ'' की तुलना ''टूटी हुई नाव'' से की गई है? In which Upanishad is ''Sacrifice'' (Yajna) compared to a ''Broken Boat''?');
