INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('47a738f6-efdc-4255-a7f1-3bf44af18097', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'किस उपनिषद में भगवान श्रीकृष्ण का उल्लेख ''घोर आंगिरस के शिष्य'' के रूप में हुआ है? In which Upanishad is Lord Krishna mentioned as a disciple of ''Ghora Angirasa''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ddcdf62e-7b0e-41c4-a8ee-921f4ee0a2f1', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', '''अद्वैतवाद'' (Advaita) का दार्शनिक आधार मुख्य रूप से किन ग्रंथों को माना जाता है? Which texts are primarily considered the philosophical basis of ''Advaita''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6cedc090-0711-4855-8952-0b952333b59c', '0231a2c4-6cec-4081-b5a6-1c01357eefb9', 'विदेही राजा जनक की सभा में याज्ञवल्क्य और गार्गी का प्रसिद्ध संवाद किस उपनिषद में मिलता है? The famous debate between Yajnavalkya and Gargi in the court of King Janaka is found in which Upanishad?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1d713014-ec5b-49cb-a319-31efc324b36f', '65a17407-6a4a-41c3-a551-7ff11922b527', '2011 की जनगणना के अनुसार, मध्य प्रदेश की कुल जनसंख्या का कितना प्रतिशत शहरी (Urban) क्षेत्रों में निवास करता है? According to the 2011 Census, what percentage of the total population of MP resides in urban areas?');
