INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('19a59764-fe55-42fb-9295-730f08562f6f', '65a17407-6a4a-41c3-a551-7ff11922b527', 'नगरीकरण के प्रभाव के रूप में ''महानगरीय क्षेत्रों'' (Metropolitan areas) का विकास हो रहा है। मध्य प्रदेश में वर्तमान में कितने शहरों की जनसंख्या 10 लाख से अधिक (Million-plus) है? As an effect of urbanization, metropolitan areas are growing. How many cities in MP currently have a population of more than 10 lakhs (Million-plus)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('340ffba9-e48b-4455-8f5e-c7de31bd5bbc', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा के संबंध में निम्नलिखित में से कौन सा कथन ''गलत'' है? Which of the following statements regarding the Constituent Assembly is ''incorrect''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2e7a029c-00fa-4de4-ba3b-7a5cd4f6f8e3', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा में ''उद्देश्य प्रस्ताव'' (Objective Resolution) किसके द्वारा और कब प्रस्तुत किया गया था? By whom and when was the ''Objective Resolution'' presented in the Constituent Assembly?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('53258440-c4cf-45e7-a35c-f1643dca1b67', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा की ''प्रारूप समिति'' (Drafting Committee) में अध्यक्ष के अलावा कितने सदस्य थे? How many members were there in the ''Drafting Committee'' of the Constituent Assembly, excluding the Chairman?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d8e82424-97f2-411f-b0f0-81bc70017e30', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा के संबंध में निम्नलिखित कथनों पर विचार करें:
1. बी.एन. राव संविधान सभा के संवैधानिक सलाहकार थे।
2. डॉ. राजेंद्र प्रसाद को 11 दिसंबर 1946 को स्थायी अध्यक्ष चुना गया।
3. एच.सी. मुखर्जी संविधान सभा के उपाध्यक्ष थे।

सही कथन चुनें: Consider the following statements regarding the Constituent Assembly:
1. B.N. Rau was the Constitutional Advisor to the Assembly.
2. Dr. Rajendra Prasad was elected permanent President on Dec 11, 1946.
3. H.C. Mukherjee was the Vice-President of the Assembly.

Choose the correct statement:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('865b1a6f-11cf-4db7-af79-44bc8dc1e123', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा की समितियों और उनके अध्यक्षों को सुमेलित करें: Match the committees of the Constituent Assembly and their Chairmen:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5d510a6d-0621-4fef-a12d-4e922a02141b', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा द्वारा राष्ट्रीय ध्वज (National Flag) को कब अपनाया गया था? When was the National Flag adopted by the Constituent Assembly?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('05573328-3114-430f-a05e-d1f2d1614635', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा में रियासतों (Princely States) को कुल कितनी सीटें आवंटित की गई थीं? How many seats were total allocated to the Princely States in the Constituent Assembly?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d9613fcf-0b94-46b5-a56f-21e02e12f029', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'भारत के संविधान को संविधान सभा द्वारा किस तिथि को ''अंगीकृत, अधिनियमित और आत्मार्पित'' किया गया था? On which date was the Constitution of India ''adopted, enacted, and given to themselves'' by the Constituent Assembly?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('31b1fbbd-1b12-449c-a431-221d88abb383', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा की अंतिम बैठक कब आयोजित की गई थी? When was the final session of the Constituent Assembly held?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('aa8d9b5b-4fd2-43ce-8783-936476b58566', 'cbe4474d-b408-4cf2-b996-e2561cf3ad45', 'संविधान सभा में महिला सदस्यों की कुल संख्या कितनी थी? What was the total number of female members in the Constituent Assembly?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6675d752-806f-4f31-ac00-4671c2478f7c', '5a97965a-28b4-413a-a667-bd20d59440b6', 'भारतीय संविधान के किस अनुच्छेद के तहत राष्ट्रपति पर ''महाभियोग'' (Impeachment) चलाने की प्रक्रिया का वर्णन है? Under which Article of the Indian Constitution is the procedure for ''Impeachment'' of the President described?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('92b5f2f4-02a0-4e8f-bb78-0383c9d90095', '5a97965a-28b4-413a-a667-bd20d59440b6', 'संसद के ''संयुक्त अधिवेशन'' (Joint Sitting) की अध्यक्षता कौन करता है? Who presides over the ''Joint Sitting'' of the Parliament?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ce38054a-414c-4cb4-85c5-707853626b4e', '5a97965a-28b4-413a-a667-bd20d59440b6', 'निम्नलिखित कथनों पर विचार करें:
1. राज्यसभा एक स्थायी सदन है और इसे भंग नहीं किया जा सकता।
2. राज्यसभा के सदस्यों का कार्यकाल 5 वर्ष होता है।
3. प्रत्येक दो वर्ष बाद इसके एक-तिहाई सदस्य सेवानिवृत्त हो जाते हैं।

सही कथन चुनें: Consider the following statements:
1. Rajya Sabha is a permanent body and is not subject to dissolution.
2. The tenure of Rajya Sabha members is 5 years.
3. One-third of its members retire every second year.

Choose the correct statement:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('be7ec999-c341-40a7-ac75-3f6651d827b6', '5a97965a-28b4-413a-a667-bd20d59440b6', 'कोई विधेयक ''धन विधेयक'' (Money Bill) है या नहीं, इसका निर्णय कौन करता है? Who decides whether a Bill is a ''Money Bill'' or not?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('332ea459-c66a-459d-9871-00f9c2657f8d', '5a97965a-28b4-413a-a667-bd20d59440b6', 'संवैधानिक अनुच्छेदों और उनसे संबंधित प्रावधानों को सुमेलित करें: Match the Constitutional Articles and their respective provisions:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a28edf1e-b005-4c5e-8083-a96afebcb009', '5a97965a-28b4-413a-a667-bd20d59440b6', 'राष्ट्रपति द्वारा राज्यसभा में कितने सदस्यों को मनोनीत (Nominate) किया जाता है? How many members are nominated by the President to the Rajya Sabha?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('545e57da-f660-45c6-853e-ef27d18e9029', '5a97965a-28b4-413a-a667-bd20d59440b6', 'मंत्री सामूहिक रूप से किसके प्रति उत्तरदायी होते हैं? To whom are the Ministers collectively responsible?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fe445329-0fb4-4d36-9391-0680b71985fd', '5a97965a-28b4-413a-a667-bd20d59440b6', 'संसद के दो सत्रों के बीच अधिकतम कितना अंतराल (Interval) हो सकता है? What is the maximum interval allowed between two sessions of Parliament?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('43cb0baa-1634-4a9b-9897-9df0cc41140a', '5a97965a-28b4-413a-a667-bd20d59440b6', 'लोकसभा का सदस्य बनने के लिए न्यूनतम आयु क्या है? What is the minimum age to become a member of the Lok Sabha?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('05a20ac7-970a-4828-8e4d-e909f026c271', '5a97965a-28b4-413a-a667-bd20d59440b6', 'भारत का प्रधानमंत्री बनने के लिए न्यूनतम आयु क्या होगी यदि वह राज्यसभा का सदस्य है? What would be the minimum age to become the Prime Minister of India if he/she is a member of the Rajya Sabha?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d6ba08c4-9619-4b44-8b72-6a095333bc89', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'भारतीय संविधान के किस अनुच्छेद के तहत सर्वोच्च न्यायालय को ''अभिलेख न्यायालय'' (Court of Record) का दर्जा दिया गया है? Under which Article of the Indian Constitution is the Supreme Court given the status of a ''Court of Record''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('36880cfa-a143-4316-8b45-799168108c02', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'सर्वोच्च न्यायालय के न्यायाधीशों की सेवानिवृत्ति की आयु (Retirement Age) क्या है? What is the retirement age of the judges of the Supreme Court?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fdf520a4-419e-43d5-8edd-dc958c598b84', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'भारत के सर्वोच्च न्यायालय के पास ''परामर्शदात्री क्षेत्राधिकार'' (Advisory Jurisdiction) किस अनुच्छेद के अंतर्गत है? The Supreme Court of India has ''Advisory Jurisdiction'' under which Article?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('60f340f3-ee6d-4093-9dd2-30ae509edee0', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'सर्वोच्च न्यायालय के न्यायाधीश को पद से हटाने के लिए ''महाभियोग'' जैसा प्रस्ताव संसद के किस सदन में लाया जा सकता है? A motion to remove a Supreme Court judge can be initiated in which House of Parliament?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('aeff30d2-07a3-4a14-a027-ef4eb829c517', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'न्यायिक शब्दावली और संबंधित अनुच्छेदों को सुमेलित करें: Match the judicial terms and related Articles:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4d856740-6f63-4e5f-bc28-1df93bec009b', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'निम्नलिखित कथनों पर विचार करें:
1. भारत में एकीकृत (Integrated) न्यायपालिका की व्यवस्था है।
2. जनहित याचिका (PIL) की अवधारणा भारत में न्यायमूर्ति पी.एन. भगवती द्वारा शुरू की गई थी।
3. सर्वोच्च न्यायालय के न्यायाधीशों का वेतन भारत की संचित निधि (Consolidated Fund) पर भारित होता है।

सही कथन चुनें: Consider the following statements:
1. India has an Integrated Judicial System.
2. The concept of PIL was introduced in India by Justice P.N. Bhagwati.
3. The salaries of Supreme Court judges are charged to the Consolidated Fund of India.

Choose the correct statement:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e46c445a-12a7-46fb-b5a7-694fc95430bd', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'सर्वोच्च न्यायालय का न्यायाधीश बनने के लिए ''उच्च न्यायालय'' में कम से कम कितने वर्षों का वकालत (Advocate) का अनुभव अनिवार्य है? How many years of practice as an Advocate in a High Court is mandatory to become a Supreme Court judge?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('793326ac-d39b-4ebe-8bfb-9700f4ed4d0c', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'भारत में ''न्यायिक सक्रियता'' (Judicial Activism) का मुख्य अर्थ क्या है? What is the primary meaning of ''Judicial Activism'' in India?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fd2255d8-f080-41ba-8ab7-9cb0d4c43da8', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'संविधान का ''अंतिम व्याख्याकार'' (Final Interpreter) किसे माना जाता है? Who is considered the ''Final Interpreter'' of the Constitution?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('640a98d0-3f41-4687-b80e-8ac0c833c667', 'a859175c-0c2e-4773-af73-1ff5e073bbc6', 'वर्तमान में भारत के सर्वोच्च न्यायालय में न्यायाधीशों की कुल स्वीकृत संख्या (अध्यक्ष सहित) कितनी है? What is the current sanctioned strength of judges in the Supreme Court (including the CJI)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4614c6e3-0d4a-4eec-888c-c288bbab558d', '6abaf652-ef39-468b-a88a-be12bdb55484', 'भारतीय संविधान के किस अनुच्छेद और भाग में संशोधन की प्रक्रिया का उल्लेख है? In which Article and Part of the Indian Constitution is the amendment procedure mentioned?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3edd94ec-946b-4ae7-899e-7048ac9d505d', '6abaf652-ef39-468b-a88a-be12bdb55484', 'किस संविधान संशोधन को ''लघु संविधान'' (Mini Constitution) कहा जाता है? Which Constitutional Amendment is known as the ''Mini Constitution''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fcc11db2-a339-46c3-9217-66ac051db0fc', '6abaf652-ef39-468b-a88a-be12bdb55484', '91वें संविधान संशोधन अधिनियम (2003) के अनुसार, मंत्रिपरिषद का आकार लोकसभा की कुल सदस्य संख्या के कितने प्रतिशत से अधिक नहीं हो सकता? According to the 91st Amendment Act (2003), the size of the Council of Ministers cannot exceed what percentage of the total strength of the Lok Sabha?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ff301ce0-b5d2-4b63-859d-a0ab877d7f38', '6abaf652-ef39-468b-a88a-be12bdb55484', 'जीएसटी (GST) को किस संविधान संशोधन अधिनियम के माध्यम से लागू किया गया था? Through which Constitutional Amendment Act was GST implemented?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('118e9db9-6138-45e8-b176-ca9efde0ce48', '6abaf652-ef39-468b-a88a-be12bdb55484', 'संशोधन और उनके प्रमुख विषयों को सुमेलित करें: Match the amendments and their primary subjects:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a9a9b19b-7c69-4408-8456-1697fbe50c26', '6abaf652-ef39-468b-a88a-be12bdb55484', 'किस संशोधन द्वारा सिंधी भाषा को 8वीं अनुसूची में 15वीं भाषा के रूप में जोड़ा गया था? By which amendment was the Sindhi language added to the 8th Schedule as the 15th language?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('35374d00-9e7d-4dcf-a609-8e2fb3c8bc92', '6abaf652-ef39-468b-a88a-be12bdb55484', 'संवैधानिक संशोधनों के संबंध में कौन सा कथन सही है?
1. संशोधन विधेयक किसी भी सदन में पेश किया जा सकता है।
2. राष्ट्रपति संशोधन विधेयक पर अपनी सहमति देने के लिए बाध्य है।
3. संशोधन के लिए संयुक्त बैठक (Joint Sitting) का प्रावधान नहीं है।

सही विकल्प चुनें: Which statement is correct regarding Constitutional Amendments?
1. An amendment bill can be introduced in either House.
2. The President is bound to give assent to an amendment bill.
3. There is no provision for a Joint Sitting for an amendment bill.

Choose the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('562e6544-326f-46e5-bc1c-fb3642ab661d', '6abaf652-ef39-468b-a88a-be12bdb55484', 'आर्थिक रूप से पिछड़े वर्गों (EWS) को 10% आरक्षण किस संशोधन अधिनियम द्वारा दिया गया? 10% reservation for Economically Weaker Sections (EWS) was given by which Amendment Act?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('38dfd456-8270-410a-880e-6d3046874b9d', '6abaf652-ef39-468b-a88a-be12bdb55484', 'पंचायती राज संस्थाओं को संवैधानिक दर्जा किस संशोधन द्वारा प्रदान किया गया था? By which amendment was constitutional status granted to Panchayati Raj Institutions?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d23cb0d7-c6ff-4f70-9c08-cfd716175b03', '6abaf652-ef39-468b-a88a-be12bdb55484', 'किस संशोधन ने ''संपत्ति के अधिकार'' को मौलिक अधिकारों की सूची से हटा दिया? Which amendment removed the ''Right to Property'' from the list of Fundamental Rights?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6a4f22b9-4946-4338-aa29-806f2064274c', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'दक्षिणी दोलन सूचकांक (SOI) की गणना किन दो स्थानों के बीच वायुमंडलीय दबाव के अंतर के आधार पर की जाती है? The Southern Oscillation Index (SOI) is calculated based on the difference in atmospheric pressure between which two places?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c72b18a2-8c1f-4cd3-82be-efc514968cb5', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'सर गिल्बर्ट वॉकर (Gilbert Walker) ने 1920 के दशक में ''दक्षिणी दोलन'' की खोज की थी। उस समय वे किस पद पर थे? Sir Gilbert Walker discovered ''Southern Oscillation'' in the 1920s. What position did he hold at that time?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('7de14d45-6b92-4ee9-b2c9-8005c7090870', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'जब दक्षिणी दोलन सूचकांक (SOI) ''नकारात्मक'' (Negative) होता है, तो इसका क्या अर्थ है? When the Southern Oscillation Index (SOI) is ''Negative'', what does it imply?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1efd6912-6ec8-4dc1-b44d-58d31d4f8001', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'दक्षिणी दोलन (Southern Oscillation) और अल-नीनो (El Nino) के संयुक्त प्रभाव को क्या कहा जाता है? What is the combined effect of Southern Oscillation and El Nino called?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('530fe8ca-a51c-4284-8a8c-5d05000b9196', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'दक्षिणी दोलन का संबंध मुख्य रूप से किस महासागर बेसिन में वायुदाब परिवर्तन से है? Southern Oscillation is primarily related to pressure changes in which ocean basin?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5aca195d-b327-4fcf-8bf3-c81fc5ea5991', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'ENSO तटस्थ (Neutral) स्थिति के दौरान, पश्चिमी प्रशांत (इंडोनेशिया/ऑस्ट्रेलिया) में दबाव कैसा होता है? During ENSO Neutral conditions, how is the pressure in the Western Pacific (Indonesia/Australia)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5f7e8795-716d-4972-9a10-fde71dd82ab1', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'मैडेन-जूलियन ऑसिलेशन (MJO) और दक्षिणी दोलन (SO) में मुख्य अंतर क्या है? What is the main difference between Madden-Julian Oscillation (MJO) and Southern Oscillation (SO)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('483957f1-1267-42cc-8f08-e37721c61f71', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'दक्षिणी दोलन के संदर्भ में ''टेलीकनेक्शन'' (Teleconnection) का क्या अर्थ है? What does ''Teleconnection'' mean in the context of Southern Oscillation?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5f07a4b8-4868-42fa-84c6-13c021e91d41', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'दक्षिणी दोलन का भारतीय कृषि पर क्या प्रभाव पड़ सकता है? What can be the impact of Southern Oscillation on Indian Agriculture?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3e91f1ab-5b1e-4bc8-bffb-2846665db184', '9b7d1f15-4ed4-42b9-8d41-89ae10353707', 'निम्नलिखित वायुमंडलीय स्थितियों को उनके दबाव पैटर्न से सुमेलित करें (Match the atmospheric conditions with their pressure pattern): Match the atmospheric conditions with their pressure pattern:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d9be11a1-8f0f-48a3-9e1b-37c0f778d90c', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'IPCC की छठी आकलन रिपोर्ट (AR6) के अनुसार, यदि तापमान 1.5°C से अधिक बढ़ता है, तो हिमालय के ग्लेशियरों पर क्या प्रभाव पड़ेगा? According to IPCC AR6, what will be the impact on Himalayan glaciers if temperature rises above 1.5°C?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('39c7b819-34b9-4b85-b151-a7cc0f3567c4', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'समुद्र स्तर में वृद्धि (Sea Level Rise) का भारत के किस तटीय राज्य पर सबसे विनाशकारी प्रभाव पड़ने की आशंका है? Which coastal state of India is feared to face the most devastating impact of Sea Level Rise?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('304c071a-d1b0-41a9-ab96-787ecf859df6', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'जलवायु परिवर्तन के कारण ''कोरल ब्लीचिंग'' (Coral Bleaching) की घटनाएँ बढ़ रही हैं। इसका मुख्य कारण क्या है? Coral Bleaching events are increasing due to climate change. What is the main cause?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6788d5a9-35ec-4762-b4a5-5b7710962dbc', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', '''शहरी हीट आइलैंड'' (Urban Heat Island) प्रभाव, जो जलवायु परिवर्तन से और खराब हो रहा है, का क्या अर्थ है? What does ''Urban Heat Island'' effect, worsened by climate change, mean?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('44c115dd-306f-467d-9f7c-7ea1f96ab8ca', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'जलवायु परिवर्तन का भारतीय कृषि पर क्या प्रभाव पड़ने की संभावना है? What is the likely impact of Climate Change on Indian Agriculture?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f65dda80-7bda-44f3-b629-bbf0a441cd79', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'भारत ने COP26 (ग्लासगो) में 2070 तक किस लक्ष्य को प्राप्त करने की घोषणा की है? What target has India announced to achieve by 2070 at COP26 (Glasgow)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dd9b48f7-0af0-4e0d-8144-50218426740e', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'जलवायु परिवर्तन के कारण ''वेक्टर जनित रोगों'' (Vector-borne diseases) पर क्या प्रभाव पड़ेगा? What will be the impact on ''Vector-borne diseases'' due to Climate Change?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6bedbe86-7890-47af-a5a9-0da70a8ee606', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', '''क्लाइमेट टिपिंग पॉइंट्स'' (Climate Tipping Points) का क्या अर्थ है? What does ''Climate Tipping Points'' mean?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d9446dc9-b70d-4026-a2bc-d9b6b23cfad5', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'कार्बन सीक्वेस्ट्रेशन (Carbon Sequestration) जलवायु परिवर्तन को कम करने में कैसे मदद करता है? How does Carbon Sequestration help in mitigating climate change?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1a002b24-9756-4f9b-bd93-c997f82be524', 'e167874b-4a98-4779-bd7c-e3f1d90c5e11', 'निम्नलिखित पर्यावरणीय समझौतों को उनके उद्देश्य से सुमेलित करें (Match the environmental agreements with their objective): Match the environmental agreements with their objective:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('02923b05-3d40-4cdd-9285-3c7a798de934', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'भारतीय संविधान के किस अनुच्छेद को डॉ. बी.आर. अंबेडकर ने ''संविधान का हृदय और आत्मा'' कहा था? Which Article of the Indian Constitution was called the ''Heart and Soul of the Constitution'' by Dr. B.R. Ambedkar?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5fa6e895-9ec2-4df7-bc7a-8ec428c9810f', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'मौलिक कर्तव्यों (Fundamental Duties) को किस समिति की सिफारिश पर संविधान में जोड़ा गया था? On the recommendation of which committee were the Fundamental Duties added to the Constitution?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('235d3a52-8c80-47a8-930c-805ed3afdb03', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'निम्नलिखित में से कौन सा अधिकार केवल भारतीय नागरिकों को प्राप्त है, विदेशियों को नहीं? Which of the following rights is available only to Indian citizens and not to foreigners?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('306923ba-65f5-4e5e-b095-9d97a3c573ef', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'निवारक निरोध (Preventive Detention) के तहत किसी व्यक्ति को बिना मुकदमे के अधिकतम कितने समय तक हिरासत में रखा जा सकता है? What is the maximum period a person can be detained without trial under Preventive Detention?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('231702db-4372-4282-b724-2e45fc50c24b', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'मौलिक अधिकारों और उनसे संबंधित अनुच्छेदों को सुमेलित करें: Match the Fundamental Rights with their respective Articles:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('b9af31ba-8b4a-4782-b008-a9ca2f4dc4ff', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'किस मौलिक अधिकार को आपातकाल (अनुच्छेद 352) के दौरान भी निलंबित नहीं किया जा सकता? Which Fundamental Rights cannot be suspended even during an Emergency (Article 352)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3c779625-3f6f-43db-a0f2-ae67c910768a', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', '''शिक्षा का अधिकार'' (RTE) संविधान के किस अनुच्छेद के तहत एक मौलिक अधिकार है? Under which Article is the ''Right to Education'' (RTE) a Fundamental Right?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('064e48ba-4041-4585-b138-750a3ddb2712', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'वर्तमान में संविधान के भाग IV-A में कुल कितने मौलिक कर्तव्य वर्णित हैं? How many Fundamental Duties are currently described in Part IV-A of the Constitution?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('65440afb-c5d1-4248-89e0-cbee3d9830c6', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'सर्वोच्च न्यायालय द्वारा किस रिट (Writ) को ''व्यक्तिगत स्वतंत्रता का रक्षक'' (Bulwark of Personal Liberty) कहा जाता है? Which Writ is called the ''Bulwark of Personal Liberty'' by the Supreme Court?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('556719a5-3f88-45a3-ad24-50ff1380bd26', '6e2bbbae-828e-4ffe-b029-abe88597d8d6', 'संविधान के अनुच्छेद 19 के तहत वर्तमान में कुल कितनी ''स्वतंत्रताएं'' प्रदान की गई हैं? How many ''Freedoms'' are currently provided under Article 19 of the Constitution?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3d93d049-5e1a-42c1-8339-fde9d084100a', 'a10ad250-9d27-4869-87ed-5629145fdfa5', '''आरण्यक'' ग्रंथों का मुख्य विषय-वस्तु (Subject Matter) क्या है? What is the primary subject matter of the ''Aranyaka'' texts?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('95fcfb19-fb3f-4294-8c41-db5b05df624a', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'निम्नलिखित में से किस वेद का कोई ''आरण्यक'' (Aranyaka) उपलब्ध नहीं है? Which of the following Vedas has NO available ''Aranyaka''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d8b7400e-2f10-4cac-9e3e-f5d62956defe', 'a10ad250-9d27-4869-87ed-5629145fdfa5', '''ऐतरेय आरण्यक'' किस वेद से संबंधित है? To which Veda does the ''Aitareya Aranyaka'' belong?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3fdadb62-9c63-49b1-a57d-d03ecc25c664', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'आरण्यक ग्रंथों को वैदिक साहित्य के किस कालक्रम में रखा जाता है? In which chronological order of Vedic literature are Aranyakas placed?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a2d76676-12ec-4ee4-8079-69f20824f147', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'वेदों को उनके प्रमुख आरण्यकों से सुमेलित करें (Match the Vedas with their major Aranyakas): Match the Vedas with their major Aranyakas:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('eef478c9-a275-47ae-bebb-72024a563fe6', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'आरण्यकों का नामकरण किस आधार पर हुआ है? On what basis were the Aranyakas named?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('b8116e10-e40f-43bb-b87b-afead1c02da6', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'वानप्रस्थ आश्रम (Vanaprastha) के दौरान मुख्य रूप से किन ग्रंथों का अध्ययन किया जाता था? Which texts were primarily studied during the Vanaprastha stage of life?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d610f766-da41-4e25-8126-e712f6132295', 'a10ad250-9d27-4869-87ed-5629145fdfa5', '''प्राण'' की महत्ता और उसकी दार्शनिक व्याख्या किस आरण्यक की मुख्य विशेषता है? The importance of ''Prana'' (life force) and its philosophical explanation is a key feature of which Aranyaka?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e6ec4d94-57ba-43da-8e87-6ba2a739536c', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'आरण्यकों में किस पर सर्वाधिक बल दिया गया है? What is most emphasized in the Aranyakas?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('56c4a75d-18d0-4191-a3ed-bb3f4809ec0b', 'a10ad250-9d27-4869-87ed-5629145fdfa5', 'कथन 1: आरण्यक ग्रंथ ''संन्यासियों'' के लिए लिखे गए थे।
कथन 2: इनमें कर्मकांडों की आलोचना की गई है।
सही विकल्प चुनें: Statement 1: Aranyakas were written for ''Sannyasis''.
Statement 2: They contain criticism of rituals.
Choose the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ecb08ddc-4b4f-4e95-99f3-ce0fd16acdf6', '4bb204de-8033-489a-a151-f019409fb593', 'ब्राह्मण ग्रंथों का मुख्य कार्य क्या है? What is the primary function of the Brahmana texts?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0b82da44-aa44-43d1-8aa6-dd0228dc5c2d', '4bb204de-8033-489a-a151-f019409fb593', 'सर्वाधिक विशाल और महत्वपूर्ण ब्राह्मण ग्रंथ कौन सा है? Which is the largest and most important Brahmana text?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('7cde3cc0-d956-435d-81d8-664a783f42d9', '4bb204de-8033-489a-a151-f019409fb593', '''विदेह माधव'' की कथा, जो आर्यों के पूर्व दिशा में प्रसार का वर्णन करती है, किस ब्राह्मण में है? The story of ''Videha Madhava'', which describes the eastward expansion of Aryans, is found in which Brahmana?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c71a3736-90f4-4e1f-bc42-d6dbeb82e18c', '4bb204de-8033-489a-a151-f019409fb593', 'किस ब्राह्मण ग्रंथ को ''पंचविश'' (Panchavisha) के नाम से भी जाना जाता है? Which Brahmana text is also known as ''Panchavisha''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e29481f1-773c-401e-b2a2-606bf5c83cb2', '4bb204de-8033-489a-a151-f019409fb593', 'वेदों को उनके एकमात्र/प्रमुख ब्राह्मण ग्रंथों से सुमेलित करें (Match the Vedas with their Brahmanas): Match the Vedas with their Brahmanas:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8fea0da6-6f38-4426-8ec9-1b3038779740', '4bb204de-8033-489a-a151-f019409fb593', 'राजा के ''राज्याभिषेक'' (Coronation) और राजत्व की उत्पत्ति का विवरण किस ब्राह्मण में मिलता है? Details of the King''s Coronation and the origin of kingship are found in which Brahmana?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('be414779-a796-46d1-820b-f33c00873b03', '4bb204de-8033-489a-a151-f019409fb593', 'किस ब्राह्मण ग्रंथ में स्त्रियों को ''सुरा और पासे'' (Wine & Dice) के समान बुराई बताया गया है? In which Brahmana/Vedic text are women listed as an evil alongside ''Wine and Dice''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('cf43cef3-b063-4dc3-82c5-209d4a8d216b', '4bb204de-8033-489a-a151-f019409fb593', 'अथर्ववेद का एकमात्र ब्राह्मण ग्रंथ ''गोपथ'' किसने लिखा था? Who is the traditionally attributed author of the Gopatha Brahmana, the only Brahmana of Atharvaveda?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d45edcd6-0bd3-4df4-b3d5-444f8a57c667', '4bb204de-8033-489a-a151-f019409fb593', 'ब्राह्मण ग्रंथों की शैली कैसी है? What is the literary style of the Brahmana texts?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3d5698d9-2b2a-44ca-bc9f-cd902ec049c5', '4bb204de-8033-489a-a151-f019409fb593', 'कथन 1: शतपथ ब्राह्मण के अनुसार ''रेवा'' (नर्मदा) नदी का उल्लेख मिलता है।
कथन 2: ब्राह्मण ग्रंथों में राजा को ईश्वर का अंश माना गया है।
सही विकल्प चुनें: Statement 1: The Satapatha Brahmana mentions the ''Reva'' (Narmada) river.
Statement 2: Brahmanas consider the King to be a part of God.
Choose the correct option:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9f359a8a-cda5-4d6e-a98b-217f06d1a978', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'भारतीय संविधान में ''राज्य के नीति-निदेशक सिद्धांत'' (DPSP) किस देश के संविधान से प्रेरित हैं? The ''Directive Principles of State Policy'' (DPSP) in the Indian Constitution are inspired by which country''s constitution?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('792d55d7-c756-49ee-a951-8403d95dd7e9', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'निम्नलिखित में से कौन सा अनुच्छेद ''ग्राम पंचायतों के संगठन'' (Organization of Village Panchayats) से संबंधित है? Which of the following Articles relates to the ''Organization of Village Panchayats''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1775f989-1e7e-4e21-83b2-abf840b2874b', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', '''समान नागरिक संहिता'' (Uniform Civil Code) का उल्लेख संविधान के किस अनुच्छेद में किया गया है? In which Article of the Constitution is the ''Uniform Civil Code'' mentioned?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6f5ae605-bb2d-4962-8e9e-ce9e6db43d23', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'किस संशोधन द्वारा नीति-निदेशक तत्वों में अनुच्छेद 39A (समान न्याय और मुफ्त कानूनी सहायता) जोड़ा गया था? By which amendment was Article 39A (Equal Justice and Free Legal Aid) added to the DPSP?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a40f16d4-c67c-4d71-81a7-3e31c5fc4f51', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'अनुच्छेदों और उनके विषयों को सुमेलित करें: Match the Articles and their subjects:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1e1cecd7-6ea8-4d07-9bf8-86b9017656fa', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'निम्नलिखित में से कौन सा एक ''नीति-निदेशक तत्व'' नहीं है? Which of the following is NOT a ''Directive Principle''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('17861295-9470-4ed1-aa1f-126e56fdc2e0', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'डॉ. बी.आर. अंबेडकर ने नीति-निदेशक तत्वों को क्या कहकर संबोधित किया था? How did Dr. B.R. Ambedkar describe the Directive Principles of State Policy?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('b722ee3c-a111-4b36-b112-f549708feaa5', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'नीति-निदेशक तत्वों की प्रकृति (Nature) कैसी है? What is the ''Nature'' of the Directive Principles of State Policy?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6fba34fe-d917-4be7-9291-80bbd1ca8d54', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', '97वें संविधान संशोधन (2011) द्वारा कौन सा नया नीति-निदेशक तत्व जोड़ा गया था? Which new Directive Principle was added by the 97th Amendment (2011)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0e079f34-da07-4046-9965-aca6ef697dcd', '9ea88978-b802-4b5f-8c45-71bb1f6cf177', 'किस मामले में सर्वोच्च न्यायालय ने यह व्यवस्था दी कि ''मौलिक अधिकार और नीति-निदेशक तत्वों के बीच संतुलन'' संविधान के मूल ढांचे का हिस्सा है? In which case did the Supreme Court rule that the ''balance between Fundamental Rights and DPSP'' is part of the basic structure?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('b37236a7-2a3d-4932-9a88-0e7bcf2e907d', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'भारत के निर्वाचन आयोग (ECI) के संबंध में कौन सा अनुच्छेद ''निर्वाचन नामावली'' तैयार करने और चुनाव के ''अधीक्षण, निर्देशन और नियंत्रण'' की शक्ति प्रदान करता है? Which Article regarding the Election Commission of India (ECI) grants power for the ''superintendence, direction, and control'' of elections?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4b5593e0-3269-4abb-905e-5783bdbfe926', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'संघ लोक सेवा आयोग (UPSC) के अध्यक्ष और सदस्यों की नियुक्ति किसके द्वारा की जाती है और उनका कार्यकाल क्या होता है? By whom are the Chairman and members of UPSC appointed and what is their tenure?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e279d6e0-cfe3-4a72-b9cb-92a456d977d2', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'भारत के नियंत्रक एवं महालेखा परीक्षक (CAG) के वेतन और सेवा शर्तें किसके द्वारा निर्धारित की जाती हैं? Who determines the salary and service conditions of the Comptroller and Auditor General (CAG) of India?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('70cd0ac2-91e0-40b0-b93f-6e6fc90ea06b', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'नीति आयोग (NITI Aayog) के वर्तमान संरचना में ''पदेन सदस्य'' (Ex-officio members) की अधिकतम संख्या कितनी हो सकती है? What is the maximum number of ''Ex-officio members'' in the current structure of NITI Aayog?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ed77e471-42e5-485e-8360-4d27ee921698', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'आयोग और उनके स्थापना वर्षों को सुमेलित करें: Match the Commissions with their years of establishment:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0083c10e-59e0-44fd-867b-1163bce6ea7a', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'राष्ट्रीय अनुसूचित जनजाति आयोग (NCST) को किस संविधान संशोधन द्वारा पृथक आयोग बनाया गया था? By which Constitutional Amendment was the National Commission for Scheduled Tribes (NCST) made a separate commission?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2437a627-69a9-49c5-9f7c-162764848533', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'केंद्रीय सतर्कता आयोग (CVC) की स्थापना किस समिति की सिफारिश पर की गई थी? On the recommendation of which committee was the Central Vigilance Commission (CVC) established?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4e2931b5-4af5-498e-971f-c1e937c30c0f', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'राष्ट्रीय मानवाधिकार आयोग (NHRC) के अध्यक्ष के रूप में किसे नियुक्त किया जा सकता है? Who can be appointed as the Chairman of the National Human Rights Commission (NHRC)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('83d1eebc-8c5e-414d-bc01-661926b30dda', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'मध्य प्रदेश राज्य निर्वाचन आयोग (SEC) का गठन कब किया गया था? When was the Madhya Pradesh State Election Commission (SEC) constituted?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ce4bc620-d598-4dd3-b2f0-6b4e9b147d07', 'acc88b22-23f2-4cfe-9032-f590c8ea5fb2', 'राष्ट्रीय बाल अधिकार संरक्षण आयोग (NCPCR) में अध्यक्ष के अलावा कितने सदस्य होते हैं और उनमें कितनी महिलाओं का होना अनिवार्य है? Excluding the Chairman, how many members are there in NCPCR and how many must be women?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3dddfe22-9032-48a2-8892-6656190abb8e', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश के प्रथम राज्यपाल कौन थे? Who was the first Governor of Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('571079c3-f622-4c58-8272-f7cea9ce5fa6', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश विधानसभा भवन का नाम क्या है और इसके वास्तुकार कौन थे? What is the name of the MP Legislative Assembly building and who was its architect?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('362462e5-d3cb-4007-9c54-6332d32f30b3', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश में अब तक कितनी बार ''राष्ट्रपति शासन'' (President''s Rule) लगाया गया है? How many times has ''President''s Rule'' been imposed in Madhya Pradesh so far?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ae282f3d-9f28-4fa6-9c37-89ea7295b580', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश विधानसभा में कुल कितनी सीटें हैं और उनमें से कितनी SC और ST के लिए आरक्षित हैं? What is the total number of seats in the MP Legislative Assembly and how many are reserved for SC and ST?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('7a80a8f2-3749-40d0-a879-74b464e96ccc', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'प्रथम व्यक्तित्व और उनके संबंधित पदों को सुमेलित करें: Match the first personalities and their respective positions:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('56714d16-d24b-4d1c-83d2-9bb3215ad97c', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश विधानसभा के ''नेता प्रतिपक्ष'' (Leader of Opposition) बनने वाले पहले व्यक्ति कौन थे? Who was the first person to become the ''Leader of Opposition'' in the MP Legislative Assembly?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1175b924-e894-41a0-9238-8a0d9eeca50d', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश उच्च न्यायालय की ''खंडपीठ'' (Bench) कहाँ-कहाँ स्थित हैं? Where are the ''Benches'' of the Madhya Pradesh High Court located?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('337a1e71-b64a-451c-9e47-cfbe377ab7fb', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश की पहली महिला मुख्यमंत्री कौन थी? Who was the first female Chief Minister of Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0725a6c4-3933-4e69-a563-2691e1c92ff7', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'मध्य प्रदेश के किस मुख्यमंत्री का कार्यकाल सबसे कम (मात्र 1 दिन) रहा? Which CM of Madhya Pradesh had the shortest tenure (only 1 day)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4734f213-3622-4462-bc35-74e9e0ea8a72', '2714d50b-4b7e-428b-bf4f-e70614f683cc', 'राज्यपाल द्वारा राज्य विधानसभा में 1 ''एंग्लो-इंडियन'' सदस्य को मनोनीत करने की शक्ति किस अनुच्छेद में थी, जिसे अब समाप्त कर दिया गया है? Under which Article did the Governor have the power to nominate 1 Anglo-Indian member, which is now abolished?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('c92c77ec-e667-4a86-8960-e84404e2a00e', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'मध्य प्रदेश पंचायती राज अधिनियम, 1993 के तहत ''ग्राम सभा'' का गठन किस अनुच्छेद/धारा के प्रावधानों के अनुरूप किया गया है? Under which Article/Section provisions was the ''Gram Sabha'' constituted under the MP Panchayati Raj Act, 1993?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('54f5616b-c214-43a0-8c58-c5634d7a60a4', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'मध्य प्रदेश में पंचायती राज व्यवस्था में महिलाओं के लिए कितने प्रतिशत आरक्षण का प्रावधान है? What is the percentage of reservation for women in the Panchayati Raj system in Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('bdf44056-af0c-4d26-b586-241671d3b3f6', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'जनपद पंचायत'' के मुख्य कार्यपालन अधिकारी (CEO) की नियुक्ति किसके द्वारा की जाती है? Who appoints the Chief Executive Officer (CEO) of a Janpad Panchayat?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('72412006-9978-4dfe-a6c3-31d9eb53406f', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'मध्य प्रदेश में पंचायत चुनाव कराने का दायित्व किसका है? Who is responsible for conducting Panchayat elections in Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6880ed76-0e93-4e08-9a6c-60a5ac3c7e6c', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'पंचायती राज के स्तर और उनकी न्यूनतम जनसंख्या सीमा (MP संदर्भ) को सुमेलित करें: Match the tiers of Panchayati Raj and their minimum population limits (MP context):');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('63492522-6d23-4100-aa4d-c24552148a8b', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'मध्य प्रदेश में ''पंचायती राज दिवस'' किस तिथि को मनाया जाता है? On which date is ''Panchayati Raj Day'' celebrated in Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('55d7dac1-d9fc-4cb2-bc18-ef366f338ccf', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'पंचायतों की वित्तीय स्थिति की समीक्षा के लिए ''राज्य वित्त आयोग'' का गठन किस अनुच्छेद के तहत किया जाता है? Under which Article is the ''State Finance Commission'' constituted to review the financial position of Panchayats?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('08392ed8-51da-4b46-a9f5-8e23c9190853', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'मध्य प्रदेश में ग्राम स्वराज की नई व्यवस्था कब लागू की गई थी? When was the new system of ''Gram Swaraj'' implemented in Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1aa3f93f-1a5b-4d1d-ac6c-8fb688b180c5', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', '73वें संविधान संशोधन अधिनियम को लागू करने वाला देश का पहला राज्य कौन सा है? Which is the first state in India to implement the 73rd Constitutional Amendment Act?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8769ec3b-8a4e-42fc-b529-f40893ade109', '18f3d1ed-33dc-4b48-86d2-0822ecee0137', 'जिला पंचायत के अध्यक्ष का चुनाव किस प्रकार होता है? How is the President of the Zila Panchayat elected?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('03d417a5-ede3-4a4b-9c55-73352fedb232', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'मध्य प्रदेश की पहली ''नगर पालिका'' (Municipality) कहाँ और कब स्थापित की गई थी? Where and when was the first ''Municipality'' of Madhya Pradesh established?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5612b2b5-c4e3-40d6-aed1-4f34651312ad', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', '74वें संविधान संशोधन के तहत नगर निगम (Municipal Corporation) के लिए न्यूनतम जनसंख्या कितनी निर्धारित की गई है? What is the minimum population prescribed for a Municipal Corporation under the 74th Amendment?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('198651be-47d9-4f53-8c3a-9b9c561b31a9', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'नगर निगम का प्रशासनिक प्रमुख (Administrative Head) कौन होता है? Who is the Administrative Head of a Municipal Corporation?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('14ef6c30-ff03-49ad-9633-9bf49af524ac', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', '74वें संविधान संशोधन अधिनियम द्वारा संविधान में कौन सी अनुसूची जोड़ी गई थी? Which Schedule was added to the Constitution by the 74th Amendment Act?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('31579371-2f65-467e-a3fc-30f6e10bd558', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'नगरीय निकायों और उनकी जनसंख्या सीमा (मध्य प्रदेश संदर्भ) को सुमेलित करें: Match the urban bodies and their population limits (MP context):');
