INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9fe731a4-df80-4663-9517-7a13cf42e6c2', '78018eef-ac36-4dc9-ad54-b8c6735abe7e', 'मध्य प्रदेश में नगर निगमों की वार्ड समितियों (Ward Committees) का गठन कितनी जनसंख्या वाले शहरों में अनिवार्य है? In which cities of MP is the formation of Ward Committees mandatory based on population?');
