INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a1d34867-3456-429c-ac73-b16c86b5deac', '3f2cf06d-2cdc-48e8-af39-5e9cfe97335b', 'मध्य प्रदेश में ''ई-डिस्ट्रिक्ट'' (e-District) परियोजना का मुख्य उद्देश्य क्या है? What is the primary objective of the ''e-District'' project in Madhya Pradesh?');
