INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4dff154f-9e6e-4208-b4a9-445cb3e9fe7b', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'सांख्य दर्शन के अनुसार, सृष्टि की उत्पत्ति किन दो मूल तत्वों के संयोग से होती है? According to Sankhya philosophy, the creation of the universe results from the union of which two fundamental elements?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6f39fd54-38b6-4153-b3c9-80fb48d2358a', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'न्याय दर्शन का मुख्य प्रतिपाद्य विषय क्या है? What is the primary subject matter of the Nyaya philosophy?');
