INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('a042d841-9026-4111-90d2-3be6826af44f', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'शंकराचार्य का ''अद्वैत'' दर्शन किस षड्दर्शन का अंग है? Shankaracharya''s ''Advaita'' philosophy is a branch of which Shaddarshan?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e091b2ef-d567-4310-a14e-dda0d7ee7497', '7e0f0608-37d8-4b62-9f32-be594f782ccd', 'सांख्य दर्शन के अनुसार ''त्रिविध दुख'' में कौन सा शामिल नहीं है? According to Sankhya philosophy, which of the following is NOT included in the ''three-fold suffering''?');
