INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('cb3ce2d8-6afd-4338-8f70-f4b303cc45b6', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'प्राचीनतम और सर्वाधिक प्रामाणिक स्मृति कौन सी मानी जाती है? Which Smriti is considered the oldest and most authoritative?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('425121c1-6dfa-4151-ac4f-c195c615c921', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'प्रसिद्ध ''मिताक्षरा'' (Mitakshara) टीका किस स्मृति पर लिखी गई है? The famous ''Mitakshara'' commentary is written on which Smriti?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('d0505421-fde9-4997-8f1b-29fca2183228', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'किस स्मृति में गुप्त काल के दौरान दासों की मुक्ति (Emancipation of Slaves) के नियम विस्तार से दिए गए हैं? Which Smriti provides detailed rules for the emancipation of slaves during the Gupta period?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('83c8e6b9-4af3-4881-b89e-f290fbaa2d1f', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'कथन (A): स्मृतियों को ''धर्मशास्त्र'' (Dharmashastra) भी कहा जाता है।
कारण (R): ये समाज के नैतिक, सामाजिक और कानूनी आचरण को संहिताबद्ध करती हैं।
सही विकल्प चुनें: Assertion (A): Smritis are also called ''Dharmashastra''.
Reason (R): They codify the moral, social, and legal conduct of society.
