INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('28fd757b-c6d9-40c6-979f-3d846b7824b8', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'प्रमुख स्मृतियों और उनके टीकाकारों (Commentators) को सुमेलित करें (Match the major Smritis with their commentators): Match the major Smritis with their commentators:');
