INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3d208f91-3453-4325-a96e-f27184095254', '673e46ac-9acd-4a7d-8cae-bcae2ba70d7d', 'किस स्मृति में सर्वप्रथम ''कायस्थों'' (Kayasthas) का उल्लेख एक ''जाति'' के रूप में मिलता है? In which Smriti do we find the first mention of Kayasthas as a specific caste?');
