INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5S_Tc00VRH0-4Pub8qQ_K', 'D0gf6bklgl3RT-sTnue2n', '6 अप्रैल, 1930 की तिथि भारत के इतिहास में अच्छी तरह जानी जाती है क्योंकि यह तिथि संबंधित है: The date 6th April, 1930 is well known in the history of India because this date is associated with:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('IU0QwMRGVxAHKmp6H6hmb', 'D0gf6bklgl3RT-sTnue2n', 'भारत में किसी राज्य को विशेष दर्जा देने के लिए निम्नलिखित में से कौन-सा पैरामीटर सामान्यतः स्वीकार नहीं किया जाता है? Which of the following is not a generally accepted parameter for granting special status to a state in India?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4tEqgLbW8Jfxm14hxa_tI', 'D0gf6bklgl3RT-sTnue2n', '18वीं लोकसभा के स्पीकर द्वारा वर्ष 2024-25 के लिए गठित संसदीय समितियों के अध्यक्षों की नियुक्ति के संबंध में कौन-सा युग्म गलत है? Which pair is incorrect regarding the appointment of Chairpersons of Parliamentary Committees constituted by the Speaker of the 18th Lok Sabha for the year 2024-25?');
