INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('biX6h62CUh-iAUQxN-9MJ', 'D0gf6bklgl3RT-sTnue2n', 'निम्नलिखित में से कौन-सा देश और भारत के साथ संयुक्त सैन्य अभ्यास का युग्म गलत है? Which of the following pairs of country and joint military exercise conducted with India is incorrect?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('vX0-ytZCE77hWqA47o7L6', 'D0gf6bklgl3RT-sTnue2n', 'डेटा सुरक्षा प्रबंधन का सिद्धांत, जो ग्राहकों और संगठन के डेटा को अवैध पहुँच (illicit access) या प्रयोग से सुरक्षित रखने के लिए उपयोग की जाने वाली प्रक्रियाओं, नीतियों और नियंत्रणों को शामिल करता है, उसे कहा जाता है: The principle of data security management, which covers the procedures, policies and controls utilized to secure the data of customers and the organization against illicit access or use, is known as:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('TBnITEwju6UJO2tDGYWxb', 'D0gf6bklgl3RT-sTnue2n', 'भारत वन स्थिति रिपोर्ट (ISFR) 2021 के अनुसार, मध्यप्रदेश के इनमें से कौन-से जिले में वन आवरण 10 प्रतिशत से कम है? According to India State of Forest Report (ISFR) 2021, which of these districts of Madhya Pradesh has forest cover less than 10 percent?');
