INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('M7djolJSyhmf_4Lh3UHP0', 'D0gf6bklgl3RT-sTnue2n', '"मुख्यमंत्री लाडली बहना योजना" जो पूरे मध्यप्रदेश में क्रियान्वित की गई है, का उद्देश्य आर्थिक स्वावलंबन के अतिरिक्त निम्न भी है: The objective of "Mukhyamantri Ladli Behna Yojana" implemented in entire Madhya Pradesh, in addition to economic self-reliance is:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('50MYgGrobgMZJxbVEfOH9', 'D0gf6bklgl3RT-sTnue2n', '30.04.1977 से 23.06.1977 के दौरान, जब मध्यप्रदेश में राष्ट्रपति शासन लागू किया गया, तब मध्यप्रदेश के राज्यपाल थे: Who was the Governor of Madhya Pradesh when President''s rule was imposed in Madhya Pradesh between 30.04.1977 to 23.06.1977?');
