INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('e_B20swCyt-zv9LCJyNzl', 'D0gf6bklgl3RT-sTnue2n', 'निम्नलिखित में से कौन-सा गैर-लाभकारी संगठन भारत में रोबोटिक्स और ऑटोमेशन में मानक स्थापित करने के लिए शीर्ष निकाय है? Which one of the following not-for-profit organization is the apex body for setting up standards in Robotics and Automation in India?');
