INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('zckDEpzzQ8lRyWYY52KXZ', 'D0gf6bklgl3RT-sTnue2n', 'मध्यप्रदेश में मैंगनीज के संबंध में निम्नलिखित कथनों को पढ़िए और सही उत्तर चुनिए:
1. 2020-21 में, म.प्र. मैंगनीज निक्षेप (Reserves) में देश में द्वितीय था।
2. 2020-21 में, म.प्र. मैंगनीज उत्पादन (Production) में देश में प्रथम था।
3. छिंदवाड़ा की गोदावरी-वर्धा घाटियों में निक्षेप हैं।
4. झाबुआ की थांदला तहसील में निक्षेप हैं। Read statements regarding manganese in MP:
1. In 2020-21, MP ranked 2nd in reserves.
