INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('681a5c6a-4535-4207-b90f-1528160a2caa', '6da26a45-96cc-45dd-90e4-8651185ed2ab', 'मध्य प्रदेश में ''आत्मनिर्भर म.प्र.'' रोडमैप के तहत किस वर्ष तक राज्य की अर्थव्यवस्था को $550 बिलियन करने का लक्ष्य रखा गया है? Under ''Atmanirbhar MP'' roadmap, by which year the target is set to make the state economy $550 Billion?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('f316160a-2724-404d-bc99-45853f989394', '6da26a45-96cc-45dd-90e4-8651185ed2ab', 'कथन (Statement) आधारित प्रश्न: 
