INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('WhfYzsjiLpX9BPz1cdmE9', 'ON4tI03fHnGbNOd93yEL4', 'निम्नलिखित में से कौन सा रिट (Writ) किसी अवैध रूप से हिरासत में लिए गए व्यक्ति की रिहाई के लिए जारी किया जाता है? Which of the following Writs is issued for the release of a person who has been detained unlawfully?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('BShqhPBMYY_PxU85jlNSl', 'ON4tI03fHnGbNOd93yEL4', '''प्रेस की स्वतंत्रता'' (Freedom of Press) भारतीय संविधान के किस अनुच्छेद में अंतर्निहित (Implicit) है? ''Freedom of Press'' is implicit in which Article of the Indian Constitution?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('zqKMFvpellxG-ABBcbodS', 'GNNi7IhV5GR3SsIyAn4zM', 'भारतीय संविधान के अनुच्छेद 12 के तहत ''राज्य'' (State) की परिभाषा में निम्नलिखित में से कौन शामिल नहीं है? Which of the following is NOT included in the definition of ''State'' under Article 12 of the Indian Constitution?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('N9kBHEC8hg3SGfk2dR2pt', 'GNNi7IhV5GR3SsIyAn4zM', 'संविधान का कौन सा अनुच्छेद सर्वोच्च न्यायालय और उच्च न्यायालयों को ''न्यायिक समीक्षा'' (Judicial Review) की शक्ति प्रदान करता है, जिससे वे मौलिक अधिकारों का उल्लंघन करने वाले कानूनों को शून्य घोषित कर सकते हैं? Which Article of the Constitution confers the power of ''Judicial Review'' on the Supreme Court and High Courts, allowing them to declare laws violating Fundamental Rights as void?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('YZCf0QHG7uryCabnjrGd7', 'GNNi7IhV5GR3SsIyAn4zM', 'किसी भी व्यक्ति को एक ही अपराध के लिए एक से अधिक बार दंडित नहीं किया जाएगा। ''दोहरे दंड से संरक्षण'' (Protection against Double Jeopardy) किस अनुच्छेद में दिया गया है? No person shall be prosecuted and punished for the same offense more than once. The ''Protection against Double Jeopardy'' is provided in which Article?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('aRKddTfIGRx5dnXQuQc43', 'GNNi7IhV5GR3SsIyAn4zM', 'सूची-I को सूची-II से सुमेलित कीजिए:

सूची-I (रिट - Writ)
A. बंदी प्रत्यक्षीकरण (Habeas Corpus)
B. परमादेश (Mandamus)
C. उत्प्रेषण (Certiorari)
D. अधिकार पृच्छा (Quo-Warranto)

सूची-II (शाब्दिक अर्थ)
1. प्रमाणित होना (To be certified)
2. किस अधिकार से (By what authority)
3. शरीर प्रस्तुत करना (To have the body of)
4. हम आदेश देते हैं (We command)

नीचे दिए गए कूट का उपयोग करके सही उत्तर चुनिए: Match List-I with List-II:

List-I (Writ)
A. Habeas Corpus
B. Mandamus
C. Certiorari
D. Quo-Warranto

List-II (Literal Meaning)
1. To be certified
2. By what authority
3. To have the body of
4. We command

Select the correct answer using the code given below:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('Dc1R3bqEG0AmlnNMh8Qo7', 'GNNi7IhV5GR3SsIyAn4zM', '''बेगार'' (Begar) और मानव के दुर्व्यापार (Human Trafficking) पर रोक संविधान के किस अनुच्छेद के तहत एक मौलिक अधिकार है? Prohibition of ''Begar'' (forced labor) and Human Trafficking is a Fundamental Right under which Article of the Constitution?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('4gabDKIofAqPAQLk8uHPP', 'GNNi7IhV5GR3SsIyAn4zM', 'धार्मिक मामलों के प्रबंधन की स्वतंत्रता (Freedom to manage religious affairs) भारतीय संविधान के किस अनुच्छेद के तहत प्रदान की गई है? The ''Freedom to manage religious affairs'' is granted under which Article of the Indian Constitution?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('5QtHpSFMjJ0AvwjtV7JYQ', 'GNNi7IhV5GR3SsIyAn4zM', 'अल्पसंख्यकों (Minorities) को अपनी पसंद के ''शैक्षणिक संस्थान स्थापित करने और उनका प्रशासन करने'' का अधिकार किस अनुच्छेद में निहित है? The right of minorities to ''establish and administer educational institutions'' of their choice is enshrined in which Article?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('-tjfNF61Y3mCW1ya3U1Ad', 'GNNi7IhV5GR3SsIyAn4zM', 'सशस्त्र बलों (Armed Forces), खुफिया एजेंसियों और पुलिस बलों के सदस्यों के मौलिक अधिकारों को प्रतिबंधित या निरस्त करने की शक्ति किसके पास है? Who has the power to restrict or abrogate the Fundamental Rights of the members of the Armed Forces, intelligence agencies, and police forces?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('rFULi9O29nyRWYT_KofwL', 'GNNi7IhV5GR3SsIyAn4zM', 'भारतीय संविधान के अनुच्छेद 18 के तहत ''उपाधियों के अंत'' (Abolition of Titles) में किन क्षेत्रों की उपाधियों को अपवाद (Exception) माना गया है? Under the ''Abolition of Titles'' in Article 18 of the Indian Constitution, which fields of titles are considered exceptions?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('xi1bBzJObIVLr8zt78o-W', 'GNNi7IhV5GR3SsIyAn4zM', 'सर्वोच्च न्यायालय के ऐतिहासिक ''पुट्टास्वामी फैसले'' (Puttaswamy judgment) 2017 के अनुसार, ''निजता का अधिकार'' (Right to Privacy) किस अनुच्छेद के तहत एक मौलिक अधिकार है? According to the historic ''Puttaswamy judgment'' (2017) of the Supreme Court, the ''Right to Privacy'' is a Fundamental Right under which Article?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('chmXlPebq0W940uBfmHZx', '_C5jUKhFJ0byCmtI2Us7r', 'निम्नलिखित में से कौन सी जलसंधि भूमध्य सागर को अटलांटिक महासागर से जोड़ती है? Which of the following straits connects the Mediterranean Sea to the Atlantic Ocean?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('qTqKUWFbnxYx3YH7py_H7', '_C5jUKhFJ0byCmtI2Us7r', 'मलक्का जलसंधि (Strait of Malacca) किन दो भू-भागों को अलग करती है? The Strait of Malacca separates which two landmasses?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('KTsSSt-SYcX_31zWwdt_j', '_C5jUKhFJ0byCmtI2Us7r', 'बेरिंग जलसंधि (Bering Strait) किन दो महाद्वीपों को अलग करती है? The Bering Strait separates which two continents?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1oCqWQQKhkmz9KqYDt0UY', '_C5jUKhFJ0byCmtI2Us7r', 'सूची-I को सूची-II से सुमेलित कीजिए:

सूची-I (जलसंधि)
A. हर्मुज जलसंधि
B. बाब-अल-मंडेब
C. पाक जलसंधि
D. फ्लोरिडा जलसंधि

सूची-II (जोड़ती है/स्थान)
1. लाल सागर और अदन की खाड़ी
2. फारस की खाड़ी और ओमान की खाड़ी
3. भारत और श्रीलंका
4. मैक्सिको की खाड़ी और अटलांटिक महासागर

नीचे दिए गए कूट का उपयोग करके सही उत्तर चुनिए: Match List-I with List-II:

List-I (Strait)
A. Strait of Hormuz
B. Bab-el-Mandeb
C. Palk Strait
D. Strait of Florida

List-II (Connects/Location)
1. Red Sea & Gulf of Aden
2. Persian Gulf & Gulf of Oman
3. India & Sri Lanka
4. Gulf of Mexico & Atlantic Ocean

Select the correct answer using the code given below:');
