INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('Bkf_MFCPjulhe7pQ_68qQ', 'Gxafr3tH9_drYZGafDynl', 'सूची-I को सूची-II से सुमेलित कीजिए:

