INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('YymKtUW-UGtt40el8hhxo', 'Gxafr3tH9_drYZGafDynl', '1960 की सिंधु जल संधि (Indus Water Treaty) के अनुसार, भारत को किन तीन ''पूर्वी नदियों'' (Eastern Rivers) के पानी के उपयोग पर पूर्ण अधिकार मिला है? According to the Indus Water Treaty of 1960, India got full rights over the water usage of which three ''Eastern Rivers''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('CIEHXhubQe7j13PNkfwkh', 'Gxafr3tH9_drYZGafDynl', 'हिमालय से निकलने वाली गंगा नदी मैदानी भाग (Plains) में किस स्थान से प्रवेश करती है? From which place does the Ganga river, originating from the Himalayas, enter the plains?');
