INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('oUDhFNaSDf3-yPOg1iIAg', 'Gxafr3tH9_drYZGafDynl', 'सिंधु नदी (Indus River) भारत के किस एकमात्र केंद्र शासित प्रदेश (UT) या राज्य से होकर बहती है? The Indus River flows through which ONLY Union Territory (UT) or State of India?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('UkOrfH_U26-6rjXcNIFyB', 'Gxafr3tH9_drYZGafDynl', 'पश्चिम बंगाल में गंगा नदी मुख्य रूप से दो शाखाओं में विभाजित हो जाती है। बांग्लादेश जाने वाली मुख्य शाखा को क्या कहा जाता है? In West Bengal, the Ganga river bifurcates into two main branches. What is the main branch heading to Bangladesh called?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('lP1PgZEExYk5LmjFgaFRV', 'Gxafr3tH9_drYZGafDynl', '''शोक की नदी'' (River of Sorrow) के नाम से प्रसिद्ध ''दामोदर नदी'' (Damodar River) किस पठार से निकलती है? The ''Damodar River'', famous as the ''River of Sorrow'', originates from which plateau?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('eXElaQoHmYV_kZH2yI7co', 'nDSP0MEmi_Zz2DjGtnyJc', 'भारतीय राष्ट्रीय कांग्रेस के किस अधिवेशन में पहली बार ''पूर्ण स्वराज'' (Complete Independence) का प्रस्ताव पारित किया गया था? In which session of the Indian National Congress was the resolution for ''Purna Swaraj'' (Complete Independence) passed for the first time?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('vqT8LDYxmLi7lxxKV-lQT', 'nDSP0MEmi_Zz2DjGtnyJc', 'महात्मा गांधी के राजनीतिक गुरु (Political Guru) कौन थे? Who was the political guru of Mahatma Gandhi?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('hZuNgoCr7RKKO0XwNEU3t', 'nDSP0MEmi_Zz2DjGtnyJc', '1905 में बंगाल विभाजन (Partition of Bengal) के समय भारत का वायसराय कौन था? Who was the Viceroy of India during the Partition of Bengal in 1905?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('r5ANhjx42AOHW8eEsgdvM', 'nDSP0MEmi_Zz2DjGtnyJc', 'भारतीय राष्ट्रीय कांग्रेस की प्रथम भारतीय महिला अध्यक्ष (First Indian Woman President) कौन थीं? Who was the first Indian Woman President of the Indian National Congress?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('azPJPPT9PmS29hCn_-i38', 'nDSP0MEmi_Zz2DjGtnyJc', 'सुभाष चंद्र बोस ने 1939 में कांग्रेस के अध्यक्ष पद से इस्तीफा देने के बाद किस संगठन की स्थापना की थी? Which organization was founded by Subhas Chandra Bose in 1939 after resigning from the presidency of the Congress?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('B_0rag5nrJ3VjdCWT_l5i', 'nDSP0MEmi_Zz2DjGtnyJc', 'जलियांवाला बाग हत्याकांड (13 अप्रैल 1919) किस काले कानून के विरोध में हो रही शांतिपूर्ण सभा पर गोलियां चलाने का परिणाम था? The Jallianwala Bagh Massacre (13 April 1919) was the result of firing on a peaceful gathering protesting against which draconian law?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('Es8FBMDuNtTlsVdwwM4TO', 'nDSP0MEmi_Zz2DjGtnyJc', 'किस ऐतिहासिक आंदोलन के दौरान गांधीजी ने साबरमती आश्रम से दांडी तक अपनी प्रसिद्ध ''नमक यात्रा'' (Salt March) शुरू की थी? During which historic movement did Gandhiji start his famous ''Salt March'' from Sabarmati Ashram to Dandi?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('l1OyyLUCEw6z9linByim3', 'nDSP0MEmi_Zz2DjGtnyJc', 'भारत के ''वयोवृद्ध पुरुष'' (Grand Old Man of India) के रूप में किसे जाना जाता है? Who is known as the ''Grand Old Man of India''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1aErOIjQPy1Eb9x495FaJ', 'nDSP0MEmi_Zz2DjGtnyJc', 'गांधीजी ने लंदन में आयोजित किस गोलमेज सम्मेलन (Round Table Conference) में भाग लिया था? Which Round Table Conference held in London was attended by Gandhiji?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('zngzy-3JsJAvaLj52aR4l', 'nDSP0MEmi_Zz2DjGtnyJc', 'निम्नलिखित में से किसे ''भारतीय अशांति का जनक'' (Father of Indian Unrest) कहा गया था? Who among the following was called the ''Father of Indian Unrest''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('TMbdWxErjSx_DCLgGJiwj', '61nhqDjHyPAvHeuMxb2ri', 'स्वतंत्रता के बाद ''ऑपरेशन पोलो'' (Operation Polo) का संबंध किस रियासत के भारत में विलय से है? After independence, ''Operation Polo'' is associated with the integration of which princely state into India?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('L6wOPVoatckrpTvBioXCV', '61nhqDjHyPAvHeuMxb2ri', 'भाषा के आधार पर (On linguistic basis) गठित होने वाला भारत का पहला राज्य कौन सा था? Which was the first state in India to be formed on a linguistic basis?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('dMyGovtvJXtUKfFkxQybw', '61nhqDjHyPAvHeuMxb2ri', 'जूनागढ़ रियासत (Junagadh Princely State) का भारत संघ में विलय किस प्रक्रिया द्वारा संपन्न हुआ था? By which process was the integration of the Junagadh Princely State into the Indian Union completed?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fKMmkCnDrQkUy6g7s6jhw', '61nhqDjHyPAvHeuMxb2ri', 'सूची-I को सूची-II से सुमेलित कीजिए:

सूची-I (आयोग/समिति)
A. एस.के. धर आयोग (S.K. Dhar Commission)
B. जेवीपी समिति (JVP Committee)
C. फज़ल अली आयोग (Fazl Ali Commission)
D. शाह आयोग (Shah Commission)

सूची-II (सिफारिश/घटना)
1. भाषा के आधार पर राज्यों के पुनर्गठन को औपचारिक स्वीकृति (1953)
2. पंजाब और हरियाणा का विभाजन (1966)
3. राज्यों के पुनर्गठन के लिए भाषा के बजाय ''प्रशासनिक सुविधा'' की सिफारिश (1948)
4. कांग्रेस की समिति जिसने भाषाई आधार को खारिज किया (1948)

नीचे दिए गए कूट का उपयोग करके सही उत्तर चुनिए: Match List-I with List-II:

List-I (Commission/Committee)
A. S.K. Dhar Commission
B. JVP Committee
C. Fazl Ali Commission
D. Shah Commission

List-II (Recommendation/Event)
1. Formally accepted language as the basis of reorganization (1953)
2. Bifurcation of Punjab and Haryana (1966)
3. Recommended ''administrative convenience'' rather than language (1948)
4. Congress committee that formally rejected linguistic basis (1948)

Select the correct answer using the code given below:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('pidj0iTEWcmKqKac8qMOT', '61nhqDjHyPAvHeuMxb2ri', 'सरदार वल्लभभाई पटेल के साथ रियासतों के एकीकरण में महत्वपूर्ण भूमिका निभाने वाले ''रियासती मंत्रालय'' (Ministry of States) के सचिव (Secretary) कौन थे? Who was the Secretary of the ''Ministry of States'' who played a crucial role alongside Sardar Vallabhbhai Patel in the integration of princely states?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('gf6A86EtH9wJk_kWjIMgj', '61nhqDjHyPAvHeuMxb2ri', 'राज्य पुनर्गठन अधिनियम 1956 (States Reorganisation Act, 1956) के तहत भारत में कितने राज्यों और केंद्र शासित प्रदेशों का गठन किया गया था? Under the States Reorganisation Act, 1956, how many States and Union Territories were created in India?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('AHc4pEQmTW8UedDdE6z-A', '61nhqDjHyPAvHeuMxb2ri', 'निम्नलिखित में से कौन राज्य पुनर्गठन आयोग (Fazl Ali Commission) का सदस्य नहीं था? Who among the following was NOT a member of the States Reorganisation Commission (Fazl Ali Commission)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ax2tjZ5zdPkTUBjnwKgGM', '61nhqDjHyPAvHeuMxb2ri', '1961 में भारत सरकार ने किस सैन्य अभियान के माध्यम से गोवा, दमन और दीव को पुर्तगाली शासन से मुक्त कराया था? Through which military operation did the Government of India liberate Goa, Daman, and Diu from Portuguese rule in 1961?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('71gX6oJ6D60eoRPMrhhlP', '61nhqDjHyPAvHeuMxb2ri', 'सिक्किम को किस संविधान संशोधन के माध्यम से भारत का ''पूर्ण राज्य'' (Full-fledged state) बनाया गया था? Through which Constitutional Amendment was Sikkim made a ''Full-fledged state'' of India?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('YY8sjRNgfP88ydbpuV79g', '61nhqDjHyPAvHeuMxb2ri', 'जेवीपी समिति (JVP Committee) 1948 का गठन राज्यों के पुनर्गठन के मुद्दे पर विचार करने के लिए किया गया था। J, V, और P का पूर्ण रूप क्या है? The JVP Committee (1948) was formed to consider the issue of reorganization of states. What does J, V, and P stand for?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('GEXR7gmSu2MYJv60-IHUq', 'VOyU0Flerk2uiVqQo6FCw', 'रॉकेट का अंतरिक्ष में प्रक्षेपण मुख्य रूप से भौतिकी के किस सिद्धांत पर आधारित है? The launch of a rocket into space is primarily based on which principle of physics?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('8JIkjSkptFI0uaBNv3Yxb', 'VOyU0Flerk2uiVqQo6FCw', 'DTH (Direct-To-Home) टीवी प्रसारण और निर्बाध संचार के लिए उपग्रहों को आमतौर पर किस कक्षा में स्थापित किया जाता है? For DTH (Direct-To-Home) TV broadcasting and seamless communication, satellites are generally placed in which orbit?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('1hlGE4b5PgihNky7QeOL6', 'VOyU0Flerk2uiVqQo6FCw', 'GPS (Global Positioning System) रिसीवर को अक्षांश, देशांतर और ऊंचाई (3D Location) की सटीक गणना करने के लिए कम से कम कितने उपग्रहों के सिग्नल की आवश्यकता होती है? To accurately calculate latitude, longitude, and altitude (3D Location), a GPS receiver requires signals from a minimum of how many satellites?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3tDFSDUx6B1kGud3ptdpp', 'VOyU0Flerk2uiVqQo6FCw', 'सूची-I को सूची-II से सुमेलित कीजिए:

सूची-I (नेविगेशन प्रणाली)
