INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('MxK8NH21ZHbrEeSruacCw', '9egUY4tEq7qsshk3TigSZ', 'मानव शरीर की अधिकांश प्रतिवर्ती क्रियाएं (Reflex Actions) मुख्य रूप से किसके द्वारा नियंत्रित होती हैं? Most of the Reflex Actions in the human body are primarily controlled by which of the following?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('s4Gs05aUAYgtVpR7e-Mxg', '9egUY4tEq7qsshk3TigSZ', 'वजन (Weight) के आधार पर मानव शरीर की सबसे मजबूत मांसपेशी कौन सी है? Which is the strongest muscle in the human body based on its weight?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('pPJLxZsRra9aVGlIX04Ju', '9egUY4tEq7qsshk3TigSZ', 'अक्षीय कंकाल (Axial Skeleton) में कुल कितनी हड्डियां होती हैं? How many bones are there in total in the Axial Skeleton?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('pIMcIHz6mQQ2QnpqKFzxb', '9egUY4tEq7qsshk3TigSZ', 'पाचन तंत्र का वह कौन सा भाग है जहाँ भोजन का सबसे अधिक पाचन और पोषक तत्वों का अवशोषण होता है? Which part of the digestive system is responsible for the maximum digestion of food and absorption of nutrients?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('sdgHawX8somW2X0W3F6XW', '9egUY4tEq7qsshk3TigSZ', 'मानव शरीर में कपाल तंत्रिकाओं (Cranial Nerves) के कितने जोड़े होते हैं? How many pairs of Cranial Nerves are there in the human body?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('0ABkEOTokN1bl0PyZ4URN', '9egUY4tEq7qsshk3TigSZ', 'श्वसन तंत्र में गैसों का वास्तविक विनिमय (O2 और CO2 का आदान-प्रदान) कहाँ होता है? Where does the actual exchange of gases (O2 and CO2) take place in the respiratory system?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('SRu58Xn2pBjqwsB3GWBJq', 'BZNDQooJmHPj2AphRRsAP', 'विटामिन सी (Vitamin C) की कमी से निम्नलिखित में से कौन सा रोग होता है? Which of the following diseases is caused by the deficiency of Vitamin C?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('jjZNq9VK89ze2cvpwQ3b1', 'BZNDQooJmHPj2AphRRsAP', 'निम्नलिखित में से कौन सा एक ''मैक्रोन्यूट्रिएंट'' (Macronutrient / वृहत् पोषक तत्व) नहीं है? Which of the following is NOT a ''Macronutrient''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('ToBb_BGBj7QlDZj60fZcT', 'BZNDQooJmHPj2AphRRsAP', 'किस विटामिन में ''कोबाल्ट'' (Cobalt) पाया जाता है, जिसकी कमी से पर्निशियस एनीमिया (Pernicious Anemia) होता है? Which vitamin contains ''Cobalt'', the deficiency of which causes Pernicious Anemia?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('DcD-2DtX9gVClDcP7ZL1E', 'BZNDQooJmHPj2AphRRsAP', 'सूची-I को सूची-II से सुमेलित कीजिए:

