INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('BcnvY_nj3YtC1h0rrC2uS', 'BZNDQooJmHPj2AphRRsAP', 'बच्चों में प्रोटीन की गंभीर कमी के कारण कौन सा रोग होता है, जिसमें मुख्य रूप से पेट फूल जाता है (pot-belly) और तरल पदार्थ जमा (Edema) हो जाता है? Which disease is caused by severe protein deficiency in children, characterized mainly by a swollen pot-belly and fluid retention (Edema)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('Ic3cC11HT4f_G9QeJgxy7', 'BZNDQooJmHPj2AphRRsAP', 'निम्नलिखित में से कौन सा विटामिन ''जल में घुलनशील'' (Water-soluble) है और शरीर में जमा नहीं होता है? Which of the following vitamins is ''Water-soluble'' and is not stored in the body?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('MGzhkE8BAbswDuQTmTIgy', 'BZNDQooJmHPj2AphRRsAP', 'रक्त में ''हीमोग्लोबिन'' (Hemoglobin) के निर्माण के लिए कौन सा खनिज (Mineral) अत्यंत आवश्यक है? Which mineral is extremely essential for the formation of ''Hemoglobin'' in the blood?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('hKEz_YgdCmA__H5jsG_iA', 'BZNDQooJmHPj2AphRRsAP', 'कौन सा विटामिन हमारे शरीर में सूर्य के प्रकाश (UV rays) की उपस्थिति में त्वचा द्वारा संश्लेषित (synthesized) किया जाता है? Which vitamin is synthesized by the skin in our body in the presence of sunlight (UV rays)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('IoU1HDsnhuLieL7nYdQtM', 'BZNDQooJmHPj2AphRRsAP', '''पेलाग्रा'' (Pellagra) रोग, जो 3 D''s (Dermatitis, Diarrhea, Dementia) की विशेषता है, किस विटामिन की कमी से होता है? ''Pellagra'' disease, characterized by the 3 D''s (Dermatitis, Diarrhea, Dementia), is caused by the deficiency of which vitamin?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fvf_1l_W3qajX7g0t71Xd', 'BZNDQooJmHPj2AphRRsAP', 'थायरॉयड ग्रंथि (Thyroid gland) के सामान्य कामकाज और गले में सूजन वाले ''घेंघा'' (Goiter) रोग से बचाव के लिए कौन सा पोषक तत्व आवश्यक है? Which nutrient is essential for the normal functioning of the thyroid gland and prevention of the neck-swelling ''Goiter'' disease?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('yQ2X1trQd0avQRhIrG4MR', 'Hl-IOch4U2b4t43Ukf92z', 'सिकल सेल एनीमिया में, हीमोग्लोबिन की बीटा-ग्लोबिन श्रृंखला में छठा अमीनो एसिड ''ग्लूटामिक एसिड'' (Glutamic acid) किस अमीनो एसिड से बदल जाता है? In Sickle Cell Anemia, the sixth amino acid ''Glutamic acid'' in the beta-globin chain of hemoglobin is replaced by which amino acid?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('qsFMhzHgUIpORVMP5ZvB_', 'Hl-IOch4U2b4t43Ukf92z', 'सिकल सेल एनीमिया किस प्रकार का आनुवंशिक विकार (Genetic Disorder) है? What type of genetic disorder is Sickle Cell Anemia?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('2glUbaLBrznr0YFoIpEzk', 'Hl-IOch4U2b4t43Ukf92z', 'सिकल सेल ''ट्रेट'' (कैरियर) वाले व्यक्तियों को प्राकृतिक रूप से किस बीमारी के प्रति प्रतिरोधक क्षमता (Resistance) प्राप्त होती है? Individuals with the Sickle Cell ''Trait'' (carriers) naturally acquire resistance against which disease?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('-wViwN2mk_M93RcRz3ZL8', 'Hl-IOch4U2b4t43Ukf92z', 'थैलेसीमिया (Thalassemia) और सिकल सेल एनीमिया (SCA) दोनों रक्त विकार हैं, लेकिन उनके बीच मुख्य जैविक अंतर क्या है? Thalassemia and Sickle Cell Anemia (SCA) are both blood disorders, but what is the main biological difference between them?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('x89OMzjfjZRg8KnzcrcQO', 'Hl-IOch4U2b4t43Ukf92z', 'सूची-I को सूची-II से सुमेलित कीजिए:

सूची-I (आनुवंशिक रक्त विकार)
A. सिकल सेल एनीमिया
B. थैलेसीमिया
C. हीमोफीलिया
D. ल्यूकेमिया

सूची-II (मुख्य विशेषता/प्रभाव)
1. रक्त का थक्का न जमना (कोगुलेशन दोष)
2. RBC का हंसिया (Sickle) आकार
3. WBC का कैंसर (अत्यधिक उत्पादन)
4. हीमोग्लोबिन श्रृंखलाओं का कम उत्पादन

नीचे दिए गए कूट का उपयोग करके सही उत्तर चुनिए: Match List-I with List-II:

List-I (Genetic/Blood Disorder)
A. Sickle Cell Anemia
B. Thalassemia
C. Hemophilia
D. Leukemia

List-II (Main Feature/Effect)
1. Failure of blood clotting (Coagulation defect)
2. Sickle shape of RBCs
3. Cancer of WBCs (Overproduction)
4. Underproduction of hemoglobin chains

Select the correct answer using the code given below:');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('s3XO31cMWyNWUQ6yZODh5', 'Hl-IOch4U2b4t43Ukf92z', 'सिकल सेल एनीमिया में आमतौर पर किस दवा (Drug) का उपयोग किया जाता है जो ''भ्रूण हीमोग्लोबिन'' (Fetal Hemoglobin - HbF) के स्तर को बढ़ाती है और दर्द के दौरों को कम करती है? Which drug is commonly used in Sickle Cell Anemia that increases the level of ''Fetal Hemoglobin'' (HbF) and reduces pain crises?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('DN_JNqX2oMvA1Pgj6gk_T', 'Hl-IOch4U2b4t43Ukf92z', 'सिकल सेल एनीमिया में उस अत्यधिक दर्दनाक स्थिति को क्या कहा जाता है जब विकृत लाल रक्त कोशिकाएं (RBCs) छोटी रक्त वाहिकाओं (Capillaries) को अवरुद्ध कर देती हैं? What is the extremely painful condition in Sickle Cell Anemia called when deformed RBCs block small blood vessels (capillaries)?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('za0fg0Yegl7aeK50XnSW4', 'Hl-IOch4U2b4t43Ukf92z', 'वर्तमान चिकित्सा विज्ञान में, सिकल सेल एनीमिया के लिए एकमात्र संभावित ''स्थायी इलाज'' (Permanent Cure) क्या माना जाता है? In current medical science, what is considered the only potential ''Permanent Cure'' for Sickle Cell Anemia?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('fK4dod-nky7r3CzYL-lQ6', 'Hl-IOch4U2b4t43Ukf92z', 'आनुवंशिक रक्त विकार ''हीमोफीलिया ए'' (Hemophilia A) मुख्य रूप से रक्त के थक्के जमने वाले किस कारक (Clotting Factor) की कमी के कारण होता है? The inherited blood disorder ''Hemophilia A'' is primarily caused by the deficiency of which blood clotting factor?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('cc7z07flNNvM-qrkeK_PA', 'Hl-IOch4U2b4t43Ukf92z', 'सिकल सेल रोग के बारे में जागरूकता बढ़ाने के लिए संयुक्त राष्ट्र द्वारा ''विश्व सिकल सेल जागरूकता दिवस'' (World Sickle Cell Awareness Day) प्रतिवर्ष कब मनाया जाता है? When is ''World Sickle Cell Awareness Day'' observed globally every year by the United Nations to raise awareness about the disease?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('XkwN4y6eg8pDI3tM6uW7b', '71oWfwvxa9OfQ5gQ8l1az', 'दुनिया की सबसे बड़ी पूर्णतः सरकारी वित्त-पोषित स्वास्थ्य बीमा योजना ''आयुष्मान भारत प्रधानमंत्री जन आरोग्य योजना'' (PM-JAY) के तहत प्रति परिवार प्रति वर्ष कितना स्वास्थ्य कवर प्रदान किया जाता है? Under the world''s largest fully government-financed health insurance scheme ''Ayushman Bharat Pradhan Mantri Jan Arogya Yojana'' (PM-JAY), how much health cover is provided per family per year?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('wlFUYiSYdeTS-40dflSHX', '71oWfwvxa9OfQ5gQ8l1az', 'भारत सरकार द्वारा 2014 में शुरू किए गए ''मिशन इंद्रधनुष'' (Mission Indradhanush) का मुख्य उद्देश्य क्या है? What is the main objective of ''Mission Indradhanush'' launched by the Government of India in 2014?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('JPELOLWMr8l8Kh8bDxd_a', '71oWfwvxa9OfQ5gQ8l1az', 'मध्य प्रदेश सरकार की ''सरदार वल्लभ भाई पटेल निःशुल्क औषधि वितरण योजना'' (Sardar Vallabhbhai Patel Free Drug Distribution Scheme) किस वर्ष शुरू की गई थी? In which year was the ''Sardar Vallabhbhai Patel Free Drug Distribution Scheme'' launched by the Madhya Pradesh Government?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('FH36LAXZxybSuKVemdpqd', '71oWfwvxa9OfQ5gQ8l1az', 'भारत सरकार ने देश से ''टीबी'' (Tuberculosis) को पूरी तरह से समाप्त (Eradicate) करने का लक्ष्य किस वर्ष तक रखा है? By which year has the Government of India set the target to completely eradicate ''TB'' (Tuberculosis) from the country?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('IcDvI8niH2Skb5qijeqHP', '71oWfwvxa9OfQ5gQ8l1az', 'मध्य प्रदेश सरकार के ''दस्तक अभियान'' (Dastak Abhiyan) का मुख्य उद्देश्य क्या है? What is the main objective of the Madhya Pradesh Government''s ''Dastak Abhiyan''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('QDnUU3kFt3uqtrtmmqgkS', '71oWfwvxa9OfQ5gQ8l1az', '''प्रधानमंत्री भारतीय जन औषधि परियोजना'' (PMBJP) का मुख्य उद्देश्य आम लोगों को क्या उपलब्ध कराना है? What is the primary objective of the ''Pradhan Mantri Bhartiya Janaushadhi Pariyojana'' (PMBJP) for the common people?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('A8HGzA23_fQQFD7SQ6oPw', '71oWfwvxa9OfQ5gQ8l1az', 'मध्य प्रदेश में बच्चों, किशोरियों और महिलाओं को ''एनीमिया'' (Anemia) से मुक्त करने के लिए कौन सा विशेष अभियान चलाया जा रहा है? Which special campaign is being run in Madhya Pradesh to make children, adolescent girls, and women free from ''Anemia''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('lTRQD9BWp_UCNCG6dOGpX', '71oWfwvxa9OfQ5gQ8l1az', 'राष्ट्रीय स्वास्थ्य मिशन (NHM) के तहत एक सुरक्षित मातृत्व हस्तक्षेप ''जननी सुरक्षा योजना'' (JSY) मुख्य रूप से किस बात पर जोर देती है? The ''Janani Suraksha Yojana'' (JSY), a safe motherhood intervention under the National Health Mission (NHM), primarily emphasizes what?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('VTjQD42fsgFunMiuq44ax', '71oWfwvxa9OfQ5gQ8l1az', 'मध्य प्रदेश सरकार की ''चिरायु योजना'' (Chirayu Yojana) का संबंध किस आयु वर्ग के बच्चों में 4D (जन्मजात दोष, बीमारियों, कमियों और विकास में देरी) की जांच और मुफ्त उपचार से है? The Madhya Pradesh Government''s ''Chirayu Yojana'' is related to the screening and free treatment of 4Ds (Defects at birth, Diseases, Deficiencies, and Developmental delays) in children of which age group?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('3vbwd9IJe702QPAWyQQ0R', '71oWfwvxa9OfQ5gQ8l1az', 'केंद्र सरकार की ''निक्षय पोषण योजना'' (Nikshay Poshan Yojana) के तहत किस बीमारी के मरीजों को पोषण संबंधी सहायता के लिए प्रति माह 500 रुपये की वित्तीय सहायता (DBT) प्रदान की जाती है? Under the Central Government''s ''Nikshay Poshan Yojana'', financial assistance (DBT) of Rs 500 per month for nutritional support is provided to patients suffering from which disease?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('Q05K9U6ZrKN0rFfGZVN_D', 'M1XPa_DxEQGDVbKzK6u89', 'उज्जैन में स्थित ''महाकालेश्वर ज्योतिर्लिंग'' की सबसे अनूठी विशेषता क्या है जो इसे अन्य सभी ज्योतिर्लिंगों से अलग बनाती है? What is the most unique feature of the ''Mahakaleshwar Jyotirlinga'' located in Ujjain that sets it apart from all other Jyotirlingas?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('OrzWveMFgv-LWabe0o-Sd', 'M1XPa_DxEQGDVbKzK6u89', 'विदिशा स्थित ''उदयगिरि की गुफाओं'' (Udayagiri Caves) में से किस गुफा में भगवान विष्णु के ''वराह अवतार'' (Varaha Avatar) की प्रसिद्ध और विशाल प्रतिमा स्थित है? In which of the ''Udayagiri Caves'' located in Vidisha is the famous and colossal statue of Lord Vishnu''s ''Varaha Avatar'' situated?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('cZ-DvikuzLNBNVorn7SL1', 'M1XPa_DxEQGDVbKzK6u89', '''आनंद की नगरी'' (City of Joy) मांडू में स्थित प्रसिद्ध ''जहाज महल'' (Jahaz Mahal) का निर्माण किस शासक ने करवाया था? Which ruler built the famous ''Jahaz Mahal'' located in Mandu, the ''City of Joy''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('26CMVrjjGR9j-8SU-rquy', 'M1XPa_DxEQGDVbKzK6u89', 'सूची-I को सूची-II से सुमेलित कीजिए:

