INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('TpjJed76gnfLn5fE2DM48', 'M1XPa_DxEQGDVbKzK6u89', 'मध्य प्रदेश में स्थित ''भीमबेटका'' (Bhimbetka) की गुफाएं विश्व स्तर पर मुख्य रूप से किस लिए प्रसिद्ध हैं? The caves of ''Bhimbetka'' located in Madhya Pradesh are globally famous primarily for what?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('nFUxiFiEUkaHPllbL5SZ2', 'M1XPa_DxEQGDVbKzK6u89', 'ओंकारेश्वर (Omkareshwar) ज्योतिर्लिंग मध्य प्रदेश के किस जिले में नर्मदा नदी के ''मांधाता द्वीप'' (Mandhata Island) पर स्थित है? Omkareshwar Jyotirlinga is located on the ''Mandhata Island'' of the Narmada river in which district of Madhya Pradesh?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('sK13yrEC1hBNIUCAeoea0', 'M1XPa_DxEQGDVbKzK6u89', 'सांची का महान स्तूप (Great Stupa of Sanchi), जो भारत की सबसे पुरानी पत्थर की संरचनाओं में से एक है, मूल रूप से किसके द्वारा बनवाया गया था? The Great Stupa of Sanchi, one of the oldest stone structures in India, was originally commissioned by whom?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('NSU0RndPnoT5h9LIUv97s', 'M1XPa_DxEQGDVbKzK6u89', 'निम्नलिखित में से कौन सा प्रसिद्ध ऐतिहासिक स्मारक ''मांडू'' (Mandu) में स्थित नहीं है? Which of the following famous historical monuments is NOT located in ''Mandu''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('9WZl6jCGZSt-qw1CTLbQM', 'M1XPa_DxEQGDVbKzK6u89', 'यूनेस्को विश्व धरोहर स्थल ''खजुराहो'' (Khajuraho) के विश्व प्रसिद्ध मंदिरों का निर्माण किस राजवंश के शासकों द्वारा करवाया गया था? The world-famous temples of the UNESCO World Heritage site ''Khajuraho'' were built by the rulers of which dynasty?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('zW3hiHPSipsIy15WZEjD6', 'M1XPa_DxEQGDVbKzK6u89', '1957 में भीमबेटका (Bhimbetka) रॉक शेल्टर की खोज किस प्रसिद्ध भारतीय पुरातत्वविद् (Archaeologist) ने की थी? Which famous Indian archaeologist discovered the Bhimbetka rock shelters in 1957?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('FElZYecOYJfrm0-tGiXaT', '1MQQRJR5gGLzTBUt6MThg', 'निम्नलिखित में से कौन सी रचना महाकवि कालिदास का ''खंडकाव्य'' (Khandakavya) या गीतिकाव्य है? Which of the following works is a ''Khandakavya'' (lyric poetry) by the great poet Kalidasa?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('yRb1r6ZVx8VmJk2AlRxEF', '1MQQRJR5gGLzTBUt6MThg', 'माखनलाल चतुर्वेदी को उनकी किस काव्य रचना के लिए वर्ष 1955 में हिंदी का ''प्रथम साहित्य अकादमी पुरस्कार'' प्रदान किया गया था? For which of his poetic works was Makhanlal Chaturvedi awarded the ''First Sahitya Akademi Award'' for Hindi in 1955?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('WXfiwNMB1j0AjtvUSC52B', '1MQQRJR5gGLzTBUt6MThg', 'प्रसिद्ध कवयित्री ''सुभद्रा कुमारी चौहान'' (Subhadra Kumari Chauhan) के संबंध में कौन सा/से कथन सत्य है/हैं?
1. उनका जन्म जबलपुर में हुआ था।
2. वह मध्य प्रदेश विधानसभा की सदस्य (MLA) चुनी गई थीं। Which statement(s) is/are true regarding the famous poetess ''Subhadra Kumari Chauhan''?
1. She was born in Jabalpur.
2. She was elected as a member of the Madhya Pradesh Legislative Assembly (MLA).');
