INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('mNuxxloCWo9oBMJ5vABla', '1MQQRJR5gGLzTBUt6MThg', 'संस्कृत के महान नाटककार ''भवभूति'' (Bhavabhuti) की रचनाओं का मुख्य ''रस'' (Rasa/Emotion) क्या माना जाता है, जिसे उन्होंने अपनी रचना ''उत्तररामचरित'' में "एको रसः करुण एव" कहा है? What is considered the main ''Rasa'' (Emotion) of the works of the great Sanskrit dramatist ''Bhavabhuti'', which he proclaimed as "Eko Rasah Karuna Eva" in his work ''Uttararamacarita''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('DZan17kHvYtDgJJahDgNF', '1MQQRJR5gGLzTBUt6MThg', 'मध्य प्रदेश के प्रसिद्ध व्यंग्यकार (Satirist) शरद जोशी (Sharad Joshi) का जन्म राज्य के किस शहर में हुआ था? The famous satirist of Madhya Pradesh, Sharad Joshi, was born in which city of the state?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('6u_Zjz1rRD42g9gxeuBm3', '1MQQRJR5gGLzTBUt6MThg', 'प्रसिद्ध प्रयोगवादी कवि ''गजानन माधव मुक्तिबोध'' (Gajanan Madhav Muktibodh) ने मध्य प्रदेश से प्रकाशित होने वाली किस प्रसिद्ध पत्रिका का संपादन किया था? Which famous magazine published from Madhya Pradesh was edited by the renowned experimentalist poet ''Gajanan Madhav Muktibodh''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('aLXbW9adTYoaXSaIxPcQw', '1MQQRJR5gGLzTBUt6MThg', '"जिस तरह हम बोलते हैं, उस तरह तू लिख, और इसके बाद भी हमसे बड़ा तू दिख।" यह प्रसिद्ध पंक्तियां मध्य प्रदेश के किस कवि की हैं, जिन्हें ''कविता का गांधी'' (Gandhi of Poetry) भी कहा जाता है? "Write the way we speak, and even after that, appear greater than us." These famous lines belong to which poet from MP, who is also called the ''Gandhi of Poetry''?');
INSERT INTO "questions_fts" ("id", "testId", "questionText") VALUES ('l1FvJa6HnHYHgWlY88nOV', '1MQQRJR5gGLzTBUt6MThg', 'मध्य प्रदेश के स्वतंत्रता सेनानी और कवि ''बालकृष्ण शर्मा नवीन'' (Balkrishna Sharma ''Navin'') द्वारा रचित महाकाव्य ''उर्मिला'' (Urmila) किस महाकाव्य की एक उपेक्षित पात्रा के जीवन पर आधारित है? The epic ''Urmila'' composed by MP''s freedom fighter and poet Balkrishna Sharma ''Navin'' is based on the life of a neglected character from which epic?');
