INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('21bb3b57-6573-4070-a0fa-dd270ed19c1b', 'unit_1', 'प्राचीन भारतीय ज्ञान परंपरा', 'Ancient Indian Knowledge Tradition', '{"back":"यह हमारे पूर्वजों की सोचने की शक्ति और विज्ञान है, जहाँ शिक्षा सिर्फ किताबी नहीं बल्कि जीवन जीने का तरीका थी।","details":"वेद, उपनिषद और वेदांग इस परंपरा के आधार स्तंभ हैं।","impact_emoji":"🕉️","important_facts":["शिक्षा को ''विद्या'' कहा जाता था जिसका अर्थ है जानना।","गुरु-शिष्य परंपरा इस प्रणाली की मुख्य विशेषता थी।","तक्षशिला और नालंदा प्राचीन ज्ञान के वैश्विक केंद्र थे।","शिक्षा का उद्देश्य केवल आजीविका नहीं बल्कि आत्म-साक्षात्कार था।"],"image_url":"https://images.unsplash.com/photo-1544924222-cd53eb09995d?q=80&w=800&auto=format&fit=crop"}', '{"back":"The foundational wisdom of our ancestors where science, logic, and spirituality were taught as a unified way of life.","impact_emoji":"🕉️"}', 1, 1, 'https://images.unsplash.com/photo-1544924222-cd53eb09995d?q=80&w=800&auto=format&fit=crop', 1769948924, '{"front":"प्राचीन भारतीय ज्ञान परंपरा","points":["श्रुति एवं स्मृति: ज्ञान हस्तांतरण की मौखिक (श्रुति) एवं लिखित (स्मृति) परंपरा।","गुरुकुल प्रणाली: शिक्षा, संस्कार और सर्वांगीण विकास का केंद्र।","14 विद्या एवं 64 कलाएं: प्राचीन पाठ्यक्रम के मुख्य अंग।"],"pyq":[{"year":2021,"question":"प्राचीन भारत में ज्ञान प्राप्ति का सर्वोच्च लक्ष्य क्या था?","strategy":"मोक्ष/आत्म-साक्षात्कार पर ध्यान दें।"}],"mnemonic":"SSG (श्रुति-स्मृति-गुरुकुल)","impact_emoji":"📜"}', '{"front":"Ancient Indian Knowledge Tradition","points":["Shruti & Smriti: Oral (Shruti) vs Written (Smriti) modes of knowledge transfer.","Gurukul System: Residential schooling focusing on holistic development.","14 Vidyas & 64 Kalas: Core components of the ancient curriculum."],"pyq":[{"year":2021,"question":"What was considered the ultimate goal of knowledge in Ancient India?","strategy":"Focus on Moksha/Self-realization."}],"mnemonic":"SSG (Shruti-Smriti-Gurukul)","impact_emoji":"📜"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('1cd12ca0-1077-4962-be19-e4b146e46309', 'unit_1', 'भारतवर्ष', 'Bharatvarsha', '{"back":"सिर्फ एक ज़मीन का टुकड़ा नहीं, बल्कि हिमालय से समुद्र तक फैली हमारी सांस्कृतिक और भौगोलिक पहचान।","mnemonic":"याद रखें: उत्तर में हिमालय, दक्षिण में समुद्र (Him-Sam)","impact_emoji":"🗺️","important_facts":["विष्णु पुराण में कहा गया है: ''उत्तरं यत्समुद्रस्य हिमाद्रेश्चैव दक्षिणम्। तद्वर्षं भारतं नाम भारती यत्र सन्ततिः।''","भारतवर्ष भरत कबीले/राजा के नाम पर आधारित है।","प्राचीन काल में इसे जंबूद्वीप का हिस्सा माना जाता था।","यह एक सांस्कृतिक इकाई है जहाँ विविध भाषाएँ और परंपराएँ जुड़ी हैं।"],"image_url":"https://images.unsplash.com/photo-1532375811409-ca664b4c1737?q=80&w=800&auto=format&fit=crop"}', '{"back":"Beyond a map, it is the cultural identity of the land stretching from the Himalayas to the oceans.","impact_emoji":"🗺️"}', 2, 1, 'https://images.unsplash.com/photo-1532375811409-ca664b4c1737?q=80&w=800&auto=format&fit=crop', 1769948924, '{"front":"भारतवर्ष","points":["नामकरण: राजा दुष्यंत के पुत्र ''भरत'' या ऋषभदेव के पुत्र ''भरत'' के नाम पर।","विष्णु पुराण: ''उत्तरं यत्समुद्रस्य...'' श्लोक में भौगोलिक सीमाओं का वर्णन।","जम्बूद्वीप: प्राचीन ब्रह्मांड विज्ञान में भारत जम्बूद्वीप का दक्षिणी भाग था।"],"pyq":[{"year":2022,"question":"विष्णु पुराण के अनुसार समुद्र के उत्तर और हिमालय के दक्षिण में स्थित देश का नाम क्या है?","strategy":"पुराणों के भौगोलिक संदर्भ याद रखें।"}],"mnemonic":"VJ-Bharat (विष्णुपुराण-जम्बूद्वीप-भरत)","impact_emoji":"🗺️"}', '{"front":"Bharatvarsha","points":["Nomenclature: Named after King Bharata (son of Dushyant) or Bharata (son of Rishabhdev).","Vishnu Purana: Defines boundaries (''Uttaram Yat Samudrasya...'').","Jambudvipa: India was described as the southern part of Jambudvipa in ancient cosmology."],"pyq":[{"year":2022,"question":"According to Vishnu Purana, what is the country north of the ocean and south of the Himalayas?","strategy":"Recall Puranic geography."}],"mnemonic":"VJ-Bharat (Vishnu-Jambudvipa-Bharat)","impact_emoji":"🗺️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('5fe401b3-feb0-4050-af5d-682a48a969c3', 'unit_1', 'वेद', 'Vedas', '{"back":"दुनिया का सबसे पुराना ज्ञान का भंडार (ऋग्वेद, सामवेद, यजुर्वेद, अथर्ववेद) जिसमें ब्रह्मांड के रहस्य छुपे हैं।","mnemonic":"Trick: R-S-Y-A (Rishabh Sings Yearly Always)","impact_emoji":"📜","important_facts":["ऋग्वेद: सबसे प्राचीन, देवताओं की स्तुति में मंत्र।","यजुर्वेद: यज्ञों और अनुष्ठानों की विधियाँ।","सामवेद: संगीत और गायन का आधार।","अथर्ववेद: चिकित्सा, जादू और दैनिक जीवन के नियम।"],"image_url":"https://images.unsplash.com/photo-1620311124458-96264024b335?q=80&w=800&auto=format&fit=crop"}', '{"back":"The world''s oldest ''knowledge library'' (Rigveda, Samaveda, Yajurveda, Atharvaveda) containing the secrets of the universe.","mnemonic":"Trick: R-S-Y-A","impact_emoji":"📜"}', 3, 0, 'https://images.unsplash.com/photo-1620311124458-96264024b335?q=80&w=800&auto=format&fit=crop', 1769948924, '{"front":"वेद","points":["अपौरुषेय: वेदों को ईश्वरीय ज्ञान माना जाता है, किसी पुरुष द्वारा रचित नहीं।","चार वेद: ऋग्वेद (सबसे प्राचीन, 1028 सूक्त), यजुर्वेद (कर्मकांड), सामवेद (संगीत), अथर्ववेद (जादू/चिकित्सा)।","त्रयी: ऋग्वेद, यजुर्वेद और सामवेद को संयुक्त रूप से ''वेदत्रयी'' कहा जाता है।"],"pyq":[{"year":2020,"question":"किस वेद में ''गायत्री मंत्र'' का उल्लेख है?","strategy":"ऋग्वेद के मंडल याद करें (तीसरा)।"}],"mnemonic":"RYSA (ऋग-यजु-साम-अथर्व)","impact_emoji":"🕉️"}', '{"front":"Vedas","points":["Apaurusheya: Considered divine knowledge, not authored by humans.","Four Vedas: Rig (Oldest, 1028 Hymns), Yajur (Rituals), Sama (Music), Atharva (Charms/Medicine).","Trayi: The first three Vedas (Rig, Yajur, Sama) are collectively called ''Vedatrayi''."],"pyq":[{"year":2020,"question":"In which Veda is the ''Gayatri Mantra'' mentioned?","strategy":"Recall Rigveda Mandalas (3rd)."}],"mnemonic":"RYSA (Rig-Yaju-Sama-Atharva)","impact_emoji":"🕉️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('aa169a2c-19d7-4b17-b7fe-ffc9a4c8f244', 'unit_1', 'उपनिषद', 'Upanishad', '{"back":"गुरु के समीप बैठकर सीखा गया वो दार्शनिक ज्ञान जो आत्मा और परमात्मा की गहराई समझाता है।","impact_emoji":"🧘‍♂️"}', '{"back":"Philosophical teachings learned ''sitting near the Guru'' that explore deep questions like ''Who am I?''","impact_emoji":"🧘‍♂️"}', 4, 0, NULL, 1769948924, '{"front":"उपनिषद","points":["वेदांत: वेदों के अंतिम भाग, दर्शन और ज्ञान मार्ग पर केंद्रित।","अर्थ: ''उप'' (समीप) + ''नि'' (निष्ठापूर्वक) + ''षद्'' (बैठना) - गुरु के समीप बैठकर ज्ञान लेना।","सत्यमेव जयते: यह आदर्श वाक्य ''मुंडकोपनिषद'' से लिया गया है।"],"pyq":[{"year":2023,"question":"''नचिकेता और यम'' का संवाद किस उपनिषद में है?","strategy":"कठोपनिषद (Key Dialogues)।"}],"mnemonic":"Mundaka-Satya (मुंडक से सत्य)","impact_emoji":"🧘"}', '{"front":"Upanishad","points":["Vedanta: The concluding part of Vedas, focusing on philosophy and Jnana (knowledge).","Meaning: ''Upa'' (Near) + ''Ni'' (Devotedly) + ''Shad'' (Sit) - Sitting near the Guru.","Satyameva Jayate: National motto taken from ''Mundaka Upanishad''."],"pyq":[{"year":2023,"question":"The dialogue between ''Nachiketa and Yama'' is in which Upanishad?","strategy":"Katha Upanishad (Key Dialogues)."}],"mnemonic":"Mundaka-Satya (Truth from Mundaka)","impact_emoji":"🧘"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('632829db-84bf-4818-818a-b22866467dbd', 'unit_1', 'आरण्यक', 'Aranyaka', '{"back":"वो ग्रंथ जो जंगलों (अरण्य) के एकांत में ऋषियों द्वारा लिखे गए, जिनमें ध्यान और दर्शन की बातें हैं।","impact_emoji":"🌲"}', '{"back":"The ''Forest Books'' written by sages in solitude, focusing on meditation and the symbolism of rituals.","impact_emoji":"🌲"}', 5, 0, NULL, 1769948924, '{"front":"आरण्यक","points":["वन ग्रंथ: वानप्रस्थ आश्रम में वनों में पठनीय, रहस्यवाद और दर्शन पर जोर।","सेतु: कर्मकांड (ब्राह्मण ग्रंथ) और ज्ञानकांड (उपनिषद) के बीच की कड़ी।","विषय: यज्ञों की दार्शनिक और प्रतीकात्मक व्याख्या।"],"pyq":[{"year":2019,"question":"ब्राह्मण ग्रंथों के अंतिम भाग को क्या कहा जाता है?","strategy":"साहित्यिक क्रम याद रखें।"}],"mnemonic":"Forest Bridge (कर्म से ज्ञान का पुल)","impact_emoji":"🌳"}', '{"front":"Aranyaka","points":["Forest Texts: Meant to be studied in forests (Vanaprastha); focus on mysticism.","Bridge: Connects Karma Kanda (Brahmanas) with Jnana Kanda (Upanishads).","Content: Symbolic and philosophical interpretation of rituals."],"pyq":[{"year":2019,"question":"What constitutes the concluding portion of the Brahmanas?","strategy":"Recall literary chronology."}],"mnemonic":"Forest Bridge (Bridge to Knowledge)","impact_emoji":"🌳"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('bcf35c14-4533-4e48-81b4-63aa60bebfba', 'unit_1', 'ब्राह्मण ग्रंथ', 'Brahman Granth', '{"back":"वेदों के कठिन मंत्रों को सरल भाषा में समझाने और यज्ञों की विधि बताने वाले ग्रंथ।","impact_emoji":"📖"}', '{"back":"Texts that simplify the complex Vedic hymns and explain the procedures and meanings of various rituals.","impact_emoji":"📖"}', 6, 1, NULL, 1769948924, '{"front":"ब्राह्मण ग्रंथ","points":["उद्देश्य: वेदों के मंत्रों की गद्य में व्याख्या और यज्ञीय विधि-विधान।","शतपथ ब्राह्मण: यजुर्वेद से संबंधित, सबसे प्राचीन और विशाल (कृषि विधियों का उल्लेख)।","ऐतरेय ब्राह्मण: ऋग्वेद से संबंधित, राज्याभिषेक के नियम।"],"pyq":[{"year":2021,"question":"शतपथ ब्राह्मण किस वेद से संबंधित है?","strategy":"वेद-ब्राह्मण मिलान (Yajurveda)।"}],"mnemonic":"Ritual Manuals (कर्मकांड नियम)","impact_emoji":"🔥"}', '{"front":"Brahman Granth","points":["Purpose: Prose commentaries on Vedas explaining sacrificial rituals.","Shatapatha Brahmana: Related to Yajurveda; oldest/largest (mentions agriculture).","Aitareya Brahmana: Related to Rigveda; rules of coronation."],"pyq":[{"year":2021,"question":"Shatapatha Brahmana is related to which Veda?","strategy":"Match Veda-Brahmana (Yajurveda)."}],"mnemonic":"Ritual Manuals","impact_emoji":"🔥"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('3d822263-8b12-455a-83fa-bd6a63a550fd', 'unit_1', 'षड्दर्शन', 'Shaddarshan', '{"back":"भारतीय दर्शन के 6 स्कूल (सांख्य, योग, न्याय, वैशेषिक, मीमांसा, वेदांत) जो सत्य को खोजने के अलग रास्ते बताते हैं।","mnemonic":"Trick: न्या-वै, सां-यो, मी-वे","impact_emoji":"🧠"}', '{"back":"The 6 schools of Indian Philosophy (Sankhya, Yoga, Nyaya, Vaisheshika, Mimamsa, Vedanta) offering different paths to Truth.","impact_emoji":"🧠"}', 7, 0, NULL, 1769948925, '{"front":"षड्दर्शन","points":["सांख्य (कपिल): सबसे प्राचीन, प्रकृति-पुरुष द्वैतवाद।","योग (पतंजलि): अष्टांग योग; न्याय (गौतम): तर्कशास्त्र।","वैशेषिक (कणाद): परमाणुवाद; मीमांसा (जैमिनी); वेदांत (बादरायण)।"],"pyq":[{"year":2022,"question":"न्याय दर्शन के प्रवर्तक कौन थे?","strategy":"संस्थापक रट लें (Gautama)।"}],"mnemonic":"SKY-NV-MV (सांख्य-कपिल, योग-पतंजलि...)","impact_emoji":"🤔"}', '{"front":"Shaddarshan","points":["Sankhya (Kapila): Oldest, Prakriti-Purusha dualism.","Yoga (Patanjali): Ashtanga Yoga; Nyaya (Gautama): Logic.","Vaisheshika (Kanada): Atomism; Mimamsa (Jaimini); Vedanta (Badarayana)."],"pyq":[{"year":2022,"question":"Who was the founder of Nyaya philosophy?","strategy":"Memorize Founders (Gautama)."}],"mnemonic":"SKY-NV-MV (Sankhya-Kapila, Yoga-Patanjali...)","impact_emoji":"🤔"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('902fd2a3-bc3c-4a23-b66e-dd8bca8353e4', 'unit_1', 'स्मृतियाँ', 'Smritiyan', '{"back":"प्राचीन समाज के नियम और कानून की पुस्तकें, जैसे मनुस्मृति और याज्ञवल्क्य स्मृति।","impact_emoji":"⚖️"}', '{"back":"The ancient legal and social codes that defined the rules of conduct for society (e.g., Manusmriti).","impact_emoji":"⚖️"}', 8, 0, NULL, 1769948925, '{"front":"स्मृतियाँ","points":["परिभाषा: ''जो याद रखा गया'', हिंदू धर्मशास्त्र और कानूनी ग्रंथ।","मनुस्मृति: सबसे प्राचीन (शुंग काल), सामाजिक नियमों का संग्रह।","याज्ञवल्क्य स्मृति: व्यवहार और न्याय पर केंद्रित।"],"pyq":[{"year":2020,"question":"सबसे प्राचीन स्मृति ग्रंथ कौन सा है?","strategy":"कालक्रम याद रखें (Manusmriti)।"}],"mnemonic":"Hindu Law Books","impact_emoji":"⚖️"}', '{"front":"Smritiyan","points":["Definition: ''That which is remembered''; Hindu codes of law/Dharmashastras.","Manusmriti: Oldest (Sunga Period); codifies social laws.","Yajnavalkya Smriti: Focuses on conduct and justice."],"pyq":[{"year":2020,"question":"Which is the oldest Smriti text?","strategy":"Recall Chronology (Manusmriti)."}],"mnemonic":"Hindu Law Books","impact_emoji":"⚖️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('a1cf23ba-c59e-4a07-bb74-f49479f98cdf', 'unit_1', 'ऋत', 'Rit (Ṛta)', '{"back":"ब्रह्मांड का वो अटूट प्राकृतिक नियम जिससे पूरी सृष्टि (सूरज, चाँद, मौसम) अनुशासन में चलती है।","impact_emoji":"🌌"}', '{"back":"The eternal cosmic order that keeps the universe, nature, and human life in perfect harmony.","impact_emoji":"🌌"}', 9, 0, NULL, 1769948925, '{"front":"ऋत (Ṛta)","points":["अर्थ: प्राकृतिक और नैतिक ब्रह्मांडीय व्यवस्था (Cosmic Order)।","संरक्षक: वरुण देवता को ''ऋतस्य गोपा'' कहा गया है।","महत्व: यह ''धर्म'' और ''कर्म'' की अवधारणा का पूर्वगामी है।"],"pyq":[{"year":2021,"question":"ऋग्वेद में किस देवता को नैतिक व्यवस्था का संरक्षक माना गया है?","strategy":"देवता-उपाधि (Varuna)।"}],"mnemonic":"Right Order (R-ita)","impact_emoji":"🌌"}', '{"front":"Rit (Ṛta)","points":["Meaning: Natural and Moral Cosmic Order.","Guardian: God Varuna is called ''Ritasya Gopa'' (Guardian of Rita).","Significance: Precursor to the concepts of Dharma and Karma."],"pyq":[{"year":2021,"question":"Which Vedic deity is the guardian of the moral order (Rita)?","strategy":"Deity-Title match (Varuna)."}],"mnemonic":"Right Order (R-ita)","impact_emoji":"🌌"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('c291adab-cc58-4eed-8065-2b733235b493', 'unit_1', 'सभा एवं समिति', 'Sabha and Samiti', '{"back":"वैदिक काल की लोकतांत्रिक संस्थाएं; सभा में अनुभवी लोग और समिति में आम जनता शामिल होती थी।","impact_emoji":"🏛️"}', '{"back":"Ancient democratic assemblies; Sabha was the council of elders, and Samiti was the general house of the people.","impact_emoji":"🏛️"}', 10, 0, NULL, 1769948925, '{"front":"सभा एवं समिति","points":["परिचय: वैदिक कालीन राजनीतिक संस्थाएं, राजा पर नियंत्रण रखती थीं।","अथर्ववेद: इन्हें प्रजापति की ''दो पुत्रियां'' कहा गया है।","अंतर: सभा (कुलीन/वृद्ध लोगों की संस्था), समिति (आम जनमानस की संस्था)।"],"pyq":[{"year":2023,"question":"किस वेद में सभा और समिति को प्रजापति की पुत्रियां कहा गया है?","strategy":"अथर्ववेद तथ्य।"}],"mnemonic":"Sabha-Senior, Samiti-Samanya","impact_emoji":"👥"}', '{"front":"Sabha and Samiti","points":["Intro: Vedic political assemblies that checked the King''s power.","Atharvaveda: Called the ''Twin Daughters of Prajapati''.","Difference: Sabha (Elite/Elders), Samiti (General Assembly/Commoners)."],"pyq":[{"year":2023,"question":"In which Veda are Sabha and Samiti called daughters of Prajapati?","strategy":"Atharvaveda Fact."}],"mnemonic":"Sabha-Senior, Samiti-Samanya (Common)","impact_emoji":"👥"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('f2b430fc-a4c1-43a5-bb27-c5cb43b32472', 'unit_1', 'गणतंत्र', 'Gantantra (Republic)', '{"back":"भारत की वो पुरानी व्यवस्था जहाँ शासन किसी राजा के वंश से नहीं बल्कि लोगों या संघ द्वारा चुना जाता था।","impact_emoji":"🤝"}', '{"back":"An ancient system where power was held by the people or a group of representatives, rather than a single hereditary king.","impact_emoji":"🤝"}', 11, 0, NULL, 1769948925, '{"front":"गणतंत्र (Republic)","points":["महाजनपद काल: वज्जि (लिच्छवि) और मल्ल प्रमुख गणतंत्र थे।","प्रणाली: राजा का चुनाव ''शलाका'' (वोटिंग स्टिक) द्वारा होता था।","वैशाली: विश्व का प्रथम गणतंत्र माना जाता है।"],"pyq":[{"year":2020,"question":"विश्व का प्राचीनतम गणतंत्र किसे माना जाता है?","strategy":"स्थान विशेष (Vaishali)।"}],"mnemonic":"Vajji-Vote-Vaishali","impact_emoji":"🗳️"}', '{"front":"Gantantra (Republic)","points":["Mahajanapada Era: Vajji (Lichchhavi) and Malla were key republics.","System: King elected using ''Salaka'' (voting sticks).","Vaishali: Considered the world''s first republic."],"pyq":[{"year":2020,"question":"Which is considered the world''s oldest republic?","strategy":"Location specific (Vaishali)."}],"mnemonic":"Vajji-Vote-Vaishali","impact_emoji":"🗳️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('9992cfa1-10fe-4327-b506-7ec9d379cdc8', 'unit_1', 'वर्णाश्रम', 'Varnashrama', '{"back":"समाज और जीवन को व्यवस्थित करने का तरीका (ब्राह्मण, क्षत्रिय, वैश्य, शूद्र) और जीवन के 4 चरण।","impact_emoji":"🏘️"}', '{"back":"A framework to organize society (Varna) and a person’s life stages (Ashrama: Student, Householder, Forest-dweller, Ascetic).","impact_emoji":"🏘️"}', 12, 0, NULL, 1769948925, '{"front":"वर्णाश्रम","points":["वर्ण: ब्राह्मण, क्षत्रिय, वैश्य, शूद्र। (उल्लेख: ऋग्वेद, 10वां मंडल, पुरुष सूक्त)।","आश्रम: ब्रह्मचर्य, गृहस्थ, वानप्रस्थ, संन्यास। (उल्लेख: जाबालोपनिषद)।","उद्देश्य: समाज (वर्ण) और व्यक्ति (आश्रम) के जीवन का व्यवस्थित संचालन।"],"pyq":[{"year":2019,"question":"चारों आश्रमों का सर्वप्रथम उल्लेख किस उपनिषद में मिलता है?","strategy":"स्रोत ग्रंथ (Jabala Upanishad)।"}],"mnemonic":"4V-10M (4 वर्ण - 10वां मंडल)","impact_emoji":"🏗️"}', '{"front":"Varnashrama","points":["Varna: Brahmin, Kshatriya, Vaishya, Shudra. (Source: Rigveda, 10th Mandala, Purusha Sukta).","Ashrama: Brahmacharya, Grihastha, Vanaprastha, Sanyasa. (Source: Jabala Upanishad).","Purpose: Organized structure for Society (Varna) and Individual (Ashrama)."],"pyq":[{"year":2019,"question":"Which Upanishad first mentions all four Ashramas?","strategy":"Source Text (Jabala Upanishad)."}],"mnemonic":"4V-10M (4 Varnas - 10th Mandala)","impact_emoji":"🏗️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('a5be7614-b2c3-47d6-a1a4-614bf1379fac', 'unit_1', 'पुरुषार्थ', 'Purushartha', '{"back":"जीवन के चार बड़े उद्देश्य: धर्म (कर्तव्य), अर्थ (धन), काम (इच्छा), और मोक्ष (मुक्ति)।","mnemonic":"Trick: D-A-K-M","impact_emoji":"🎯"}', '{"back":"The four great goals of human life: Dharma (Duty), Artha (Wealth), Kama (Desires), and Moksha (Liberation).","impact_emoji":"🎯"}', 13, 0, NULL, 1769948925, '{"front":"पुरुषार्थ","points":["चतुष्टय: धर्म (नैतिक कर्तव्य), अर्थ (भौतिक संसाधन), काम (इच्छाएं), मोक्ष (मुक्ति)।","त्रिवर्ग: धर्म, अर्थ और काम को ''त्रिवर्ग'' कहा जाता है (गृहस्थ तक सीमित)।","सर्वोच्च लक्ष्य: मोक्ष (जीवन-मरण के चक्र से मुक्ति)।"],"pyq":[{"year":2022,"question":"निम्न में से कौन ''त्रिवर्ग'' का हिस्सा नहीं है?","strategy":"बहिष्करण विधि (Moksha)।"}],"mnemonic":"DAK-M (धर्म-अर्थ-काम -> मोक्ष)","impact_emoji":"🎯"}', '{"front":"Purushartha","points":["Four Goals: Dharma (Duty), Artha (Wealth), Kama (Desire), Moksha (Salvation).","Trivarga: Dharma, Artha, and Kama are collectively called ''Trivarga''.","Ultimate Goal: Moksha (Liberation from the cycle of rebirth)."],"pyq":[{"year":2022,"question":"Which of the following is not part of ''Trivarga''?","strategy":"Exclusion method (Moksha)."}],"mnemonic":"DAK-M (Dharma-Artha-Kama -> Moksha)","impact_emoji":"🎯"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('66cab6fb-abb7-4433-bf9c-7f32fb72e11c', 'unit_1', 'ऋण', 'Rin (Debt) & Sanskara', '{"back":"इंसान पर तीन मुख्य कर्ज: देव ऋण, ऋषि ऋण, और पितृ ऋण, जिन्हें चुकाना पुण्य माना जाता है।","impact_emoji":"💳"}', '{"back":"The three moral debts we owe to gods, sages, and ancestors, and the 16 life-defining rituals from birth to death.","impact_emoji":"💳"}', 14, 0, NULL, 1769948925, '{"front":"ऋण (Rin)","points":["तीन ऋण: देव ऋण (यज्ञ से मुक्ति), ऋषि ऋण (स्वाध्याय/शिक्षण से मुक्ति), पितृ ऋण (संतान उत्पत्ति से मुक्ति)।","तैत्तिरीय संहिता: ऋणों की अवधारणा का मूल उल्लेख।","अनिवार्यता: गृहस्थ के लिए इन ऋणों को चुकाना अनिवार्य है।"],"pyq":[{"year":2021,"question":"प्राचीन भारत में मनुष्य कितने प्रकार के ऋणों से बंधा माना जाता था?","strategy":"संख्या याद रखें (3)।"}],"mnemonic":"P-R-D (पितृ-ऋषि-देव)","impact_emoji":"💳"}', '{"front":"Rin (Debt)","points":["Three Debts: Deva Rin (via Yajna), Rishi Rin (via Study/Teaching), Pitri Rin (via Progeny).","Taittiriya Samhita: Source of the concept.","Obligation: Mandatory for a Grihastha (householder) to repay these."],"pyq":[{"year":2021,"question":"How many types of debts (Rin) was a man supposed to repay in Ancient India?","strategy":"Remember Number (3)."}],"mnemonic":"P-R-D (Pitri-Rishi-Deva)","impact_emoji":"💳"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('733e6666-3668-4bfd-b617-811b23bbb8ce', 'unit_1', 'संस्कार', 'Panch Mahayagya', '{"back":"इंसान को बेहतर बनाने की प्रक्रिया, जिसमें जन्म से मृत्यु तक 16 मुख्य रीति-रिवाजों का पालन होता है।","mnemonic":"Trick: 16 Steps of Life","impact_emoji":"🔥"}', '{"back":"Five daily duties/sacrifices performed to express gratitude to gods, sages, ancestors, humans, and nature.","impact_emoji":"🙏"}', 15, 0, NULL, 1769948925, '{"front":"संस्कार","points":["संख्या: प्रमुख 16 संस्कार (षोडश संस्कार)।","क्रम: गर्भाधान (प्रथम) से अंत्येष्टि (अंतिम) तक।","उपनयन: शिक्षा का प्रारंभ, ''द्विज'' (दुबारा जन्म) का दर्जा।"],"pyq":[{"year":2023,"question":"उपनयन संस्कार का शाब्दिक अर्थ क्या है?","strategy":"अर्थ समझें (समीप ले जाना)।"}],"mnemonic":"Sweet 16 Samskaras","impact_emoji":"✨"}', '{"front":"Samskara","points":["Number: 16 Major Samskaras (Shodasha).","Sequence: From Garbhadhana (Conception) to Antyeshti (Funeral).","Upanayana: Initiation of education; confers ''Dvija'' (twice-born) status."],"pyq":[{"year":2023,"question":"What is the literal meaning of Upanayana Samskara?","strategy":"Understand Meaning (Taking near)."}],"mnemonic":"Sweet 16 Samskaras","impact_emoji":"✨"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('1581de26-11dd-4146-b6ea-0e5c4661e035', 'unit_1', 'पंचमहायज्ञ / यज्ञ', 'Principle of Karma', '{"back":"प्रकृति और ईश्वर के प्रति कृतज्ञता जताने के लिए किए जाने वाले 5 मुख्य दैनिक कर्तव्य।","impact_emoji":"🙏"}', '{"back":"The law of cause and effect: ''As you sow, so shall you reap.'' Our actions determine our destiny.","impact_emoji":"🎡"}', 16, 0, NULL, 1769948925, '{"front":"पंचमहायज्ञ","points":["ब्रह्म/ऋषि यज्ञ: वेदों का अध्ययन/अध्यापन।","देव यज्ञ: देवताओं के लिए हवन; पितृ यज्ञ: पूर्वजों का तर्पण।","नृ/मनुष्य यज्ञ: अतिथि सेवा; भूत यज्ञ: पशु-पक्षियों को भोजन।"],"pyq":[{"year":2020,"question":"अतिथि सत्कार किस महायज्ञ के अंतर्गत आता है?","strategy":"वर्गीकरण (नृ यज्ञ)।"}],"mnemonic":"B-D-P-N-B (ब्रह्म-देव-पितृ-नृ-भूत)","impact_emoji":"🤚"}', '{"front":"Panch Mahayagya","points":["Brahma/Rishi Yajna: Study/Teaching of Vedas.","Deva Yajna: Offerings to Gods; Pitri Yajna: Offering to ancestors.","Nri Yajna: Serving guests; Bhuta Yajna: Feeding animals/spirits."],"pyq":[{"year":2020,"question":"Hospitality to guests falls under which Mahayagya?","strategy":"Classification (Nri Yajna)."}],"mnemonic":"B-D-P-N-B (Brahma-Deva-Pitri-Nri-Bhuta)","impact_emoji":"🤚"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('07a2ee54-8031-4411-8775-6d460baa7f07', 'unit_1', 'कर्म का सिद्धांत', 'Bodhisattva', '{"back":"जैसा बीज बोओगे वैसी फसल काटोगे; हमारे अच्छे या बुरे काम ही हमारा भविष्य तय करते हैं।","impact_emoji":"🎡"}', '{"back":"In Buddhism, a great soul who attains enlightenment but stays back to help others achieve liberation from suffering.","impact_emoji":"🏵️"}', 17, 0, NULL, 1769948925, '{"front":"कर्म का सिद्धांत","points":["मूल विचार: ''जैसा बोओगे, वैसा काटोगे'' - कार्य-कारण संबंध।","प्रकार: संचित (पुराने), प्रारब्ध (वर्तमान जीवन का आधार), क्रियमाण (वर्तमान कर्म)।","स्रोत: बृहदारण्यक उपनिषद में याज्ञवल्क्य द्वारा स्पष्ट विवेचना।"],"pyq":[{"year":2022,"question":"पुनर्जन्म का सिद्धांत किस अवधारणा पर आधारित है?","strategy":"मूल अवधारणा (कर्म फल)।"}],"mnemonic":"Boomerang Effect","impact_emoji":"🔄"}', '{"front":"Doctrine of Karma","points":["Core Idea: Cause and Effect - actions determine future existence.","Types: Sanchita (Accumulated), Prarabdha (Fructifying), Kriyamana (Current).","Source: Clearly discussed by Yajnavalkya in Brihadaranyaka Upanishad."],"pyq":[{"year":2022,"question":"The theory of Rebirth is primarily based on which concept?","strategy":"Core Concept (Karma Phala)."}],"mnemonic":"Boomerang Effect","impact_emoji":"🔄"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('b5d8ea6d-d322-4ecc-836a-ef9df25716bf', 'unit_1', 'बोधिसत्व', 'Tirthankar', '{"back":"बौद्ध धर्म की वो महान आत्मा जो खुद निर्वाण पा सकती है पर दूसरों के दुःख दूर करने के लिए रुक जाती है।","impact_emoji":"🏵️"}', '{"back":"The 24 spiritual masters of Jainism who ''built the ford'' to cross the ocean of birth and death.","impact_emoji":"🚶‍♂️"}', 18, 0, NULL, 1769948925, '{"front":"बोधिसत्व","points":["महायान बौद्ध धर्म: वह व्यक्ति जो निर्वाण में देरी करता है ताकि दूसरों की मदद कर सके।","प्रमुख बोधिसत्व: अवलोकितेश्वर (पद्मपाणि - दया), वज्रपाणि (शक्ति), मैत्रेय (भावी बुद्ध)।","षड्पारमिता: बोधिसत्व द्वारा पालन किए जाने वाले 6 आदर्श गुण।"],"pyq":[{"year":2021,"question":"भविष्य के बुद्ध के रूप में किसे जाना जाता है?","strategy":"विशिष्ट नाम (Maitreya)।"}],"mnemonic":"Compassionate Delay (दूसरों के लिए रुकना)","impact_emoji":"🪷"}', '{"front":"Bodhisattva","points":["Mahayana Buddhism: One who delays Nirvana to assist all sentient beings.","Key Figures: Avalokiteshvara (Padmapani-Compassion), Vajrapani (Power), Maitreya (Future Buddha).","Paramitas: The 6 perfections cultivated by a Bodhisattva."],"pyq":[{"year":2021,"question":"Who is known as the Future Buddha?","strategy":"Specific Name (Maitreya)."}],"mnemonic":"Compassionate Delay","impact_emoji":"🪷"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('5ee603f6-c98e-42a8-9921-dae4954bec93', 'unit_1', 'तीर्थंकर', 'Administrative, Social, and Economic Systems of Ancient/Medieval India', '{"back":"जैन धर्म के वो 24 महापुरुष जिन्होंने संसार रूपी सागर को पार करने का रास्ता दिखाया।","impact_emoji":"🚶‍♂️"}', '{"back":"The study of how taxes were collected, how people lived together, and how kings governed in the past.","impact_emoji":"👑"}', 19, 0, NULL, 1769948925, '{"front":"तीर्थंकर","points":["जैन धर्म: 24 तीर्थंकर (''तीर्थ'' या घाट बनाने वाले)।","प्रमुख: ऋषभदेव (1ले - प्रतीक: सांड), पार्श्वनाथ (23वें - प्रतीक: सर्प), महावीर (24वें - प्रतीक: सिंह)।","कैवल्य: सर्वोच्च ज्ञान प्राप्त व्यक्ति ''जिन'' (विजेता) कहलाता है।"],"pyq":[{"year":2020,"question":"23वें तीर्थंकर पार्श्वनाथ का प्रतीक चिन्ह क्या है?","strategy":"चिन्ह मिलान (सर्प)।"}],"mnemonic":"R-P-M (1-23-24 Bull-Snake-Lion)","impact_emoji":"🦁"}', '{"front":"Tirthankar","points":["Jainism: 24 Tirthankaras (''Ford-makers'' across the river of misery).","Key Figures: Rishabhdev (1st-Bull), Parshvanath (23rd-Snake), Mahavira (24th-Lion).","Kaivalya: One who attains supreme knowledge is called ''Jina'' (Conqueror)."],"pyq":[{"year":2020,"question":"What is the symbol of the 23rd Tirthankara Parshvanath?","strategy":"Match Symbol (Snake)."}],"mnemonic":"R-P-M (1-23-24 Bull-Snake-Lion)","impact_emoji":"🦁"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('1f48ee3d-a8af-4f62-8b11-d19472efc8b4', 'unit_1', 'प्राचीन एवं मध्यकालीन भारत की विशेषताएं', 'India''s Cultural Heritage', '{"back":"भारत की वो खूबियाँ जिन्होंने हमें ''सोने की चिड़िया'' बनाया, जैसे हमारी वास्तुकला और व्यापार।","impact_emoji":"🏰"}', '{"back":"Our magnificent art forms, literature, and festivals that represent the soul and diversity of the country.","impact_emoji":"🎨"}', 20, 0, NULL, 1769948926, '{"front":"प्राचीन एवं मध्यकालीन भारत की विशेषताएं","points":["राजनीति: राजतंत्रात्मक, सप्तांग सिद्धांत (कौटिल्य), सामंतवाद का उदय (गुप्तोत्तर काल)।","समाज: संयुक्त परिवार, जाति व्यवस्था की कठोरता, श्रेणी (Guilds) व्यवस्था।","अर्थव्यवस्था: कृषि प्रधान, वस्तु विनिमय और मौद्रिक प्रणाली का मिश्रण।"],"pyq":[{"year":2019,"question":"प्राचीन भारत में व्यापारियों के संगठन को क्या कहा जाता था?","strategy":"शब्दावली (श्रेणी)।"}],"mnemonic":"King-Caste-Guilds","impact_emoji":"🏰"}', '{"front":"Features of Ancient/Medieval India","points":["Polity: Monarchy, Saptanga Theory (Kautilya), Rise of Feudalism (Post-Gupta).","Society: Joint Family, rigid Caste System, Shreni (Guild) system.","Economy: Agrarian base, mixed barter and monetary systems."],"pyq":[{"year":2019,"question":"What was the organization of merchants called in Ancient India?","strategy":"Terminology (Shreni)."}],"mnemonic":"King-Caste-Guilds","impact_emoji":"🏰"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('a0120f98-8817-4877-b54b-f62694180151', 'unit_1', 'प्रशासनिक, सामाजिक तथा आर्थिक व्यवस्थाएं', 'Social and Religious Reform Movements (19th & 20th Century)', '{"back":"पुराने समय में टैक्स कैसे वसूला जाता था, समाज कैसा था और राजा कैसे राज करते थे।","impact_emoji":"👑"}', '{"back":"The fight against social evils like Sati and untouchability led by heroes like Raja Rammohan Roy and Vivekananda.","impact_emoji":"🕯️"}', 21, 0, NULL, 1769948926, '{"front":"प्रशासनिक, सामाजिक तथा आर्थिक व्यवस्थाएं","points":["मौर्य: केंद्रीकृत प्रशासन, तीर्थ और अध्यक्ष (27 अध्यक्ष)।","चोल: स्थानीय स्वशासन (उर और सभा), नटराज कांस्य कला।","मुगल: मनसबदारी प्रथा (अकबर), ज़ब्ती प्रणाली (टोडरमल)।"],"pyq":[{"year":2022,"question":"अष्टप्रधान किस शासक की मंत्रिपरिषद थी?","strategy":"मराठा प्रशासन (शिवाजी)।"}],"mnemonic":"Local Chola, Central Maurya, Mansab Mughal","impact_emoji":"⚖️"}', '{"front":"Admin, Social & Economic Systems","points":["Maurya: Centralized administration, Tirthas and Adhyakshas.","Chola: Local Self-Government (Ur and Sabha), Nataraja bronze art.","Mughal: Mansabdari System (Akbar), Zabti System (Todarmal)."],"pyq":[{"year":2022,"question":"Ashtapradhan was the council of ministers of which ruler?","strategy":"Maratha Admin (Shivaji)."}],"mnemonic":"Local Chola, Central Maurya, Mansab Mughal","impact_emoji":"⚖️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('ad897db4-976d-422b-b4b6-fba5e19c4c00', 'unit_1', 'सांस्कृतिक विरासत: कला प्रारूप, साहित्य, पर्व एवं उत्सव', 'Independence Struggle & National Movement', '{"back":"हमारी मूर्तियाँ, चित्रकारी, महान लेखकों की किताबें और वो त्यौहार जो आज भी हमें जोड़कर रखते हैं।","impact_emoji":"🎨"}', '{"back":"The epic story of sacrifice and courage, from the 1857 revolt to the final victory in 1947.","impact_emoji":"🇮🇳"}', 22, 0, NULL, 1769948926, '{"front":"सांस्कृतिक विरासत: कला, साहित्य, पर्व","points":["मंदिर शैली: नागर (उत्तर - खजुराहो), द्रविड़ (दक्षिण - तंजौर), बेसर (मिश्रित - होयसल)।","शास्त्रीय नृत्य: 8 प्रमुख (भरतनाट्यम-TN, कथक-UP, कथकली-Kerala आदि)।","साहित्य: कालिदास (शकुंतलम), संगम साहित्य (तमिल), महाभारत (वेद व्यास)।"],"pyq":[{"year":2023,"question":"सत्रिया नृत्य भारत के किस राज्य से संबंधित है?","strategy":"नृत्य-राज्य (असम)।"}],"mnemonic":"N-D-V Styles (Nagara-Dravida-Vesara)","impact_emoji":"🎭"}', '{"front":"Cultural Heritage: Art, Literature, Festivals","points":["Temple Styles: Nagara (North), Dravida (South), Vesara (Mixed).","Classical Dances: 8 Major (Bharatanatyam-TN, Kathak-UP, Sattriya-Assam, etc.).","Literature: Kalidasa (Shakuntalam), Sangam Literature (Tamil), Mahabharata."],"pyq":[{"year":2023,"question":"Sattriya dance is related to which Indian state?","strategy":"Dance-State (Assam)."}],"mnemonic":"N-D-V Styles (Nagara-Dravida-Vesara)","impact_emoji":"🎭"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('4afbc85f-7378-4dbe-81af-bc33bb20a733', 'unit_1', '19वीं एवं 20वीं शताब्दी के सामाजिक-धार्मिक सुधार', 'Integration and Reorganization of India after Independence', '{"back":"सती प्रथा और छुआछूत जैसी बुराइयों को खत्म करने के लिए राजा राममोहन राय और विवेकानंद जैसे महापुरुषों की जंग।","impact_emoji":"🕯️"}', '{"back":"The masterstroke of Sardar Patel in uniting fragmented princely states into one strong nation.","impact_emoji":"🔗"}', 23, 0, NULL, 1769948926, '{"front":"19वीं-20वीं सदी: सामाजिक-धार्मिक सुधार","points":["राजा राम मोहन राय: ब्रह्म समाज (1828), सती प्रथा का अंत (1829)।","दयानंद सरस्वती: आर्य समाज (1875), ''वेदों की ओर लौटो'', शुद्धि आंदोलन।","विवेकानंद: रामकृष्ण मिशन (1897), नव-हिंदूवाद।"],"pyq":[{"year":2021,"question":"''सत्यार्थ प्रकाश'' के लेखक कौन थे?","strategy":"पुस्तक-लेखक (दयानंद सरस्वती)।"}],"mnemonic":"BRA (Brahmo-Roy-1828), ADS (Arya-Dayanand-Satyarth)","impact_emoji":"🕯️"}', '{"front":"19th-20th Century: Socio-Religious Reforms","points":["Raja Ram Mohan Roy: Brahmo Samaj (1828), Abolition of Sati (1829).","Dayanand Saraswati: Arya Samaj (1875), ''Go back to Vedas'', Shuddhi Movement.","Vivekananda: Ramakrishna Mission (1897), Neo-Hinduism."],"pyq":[{"year":2021,"question":"Who was the author of ''Satyarth Prakash''?","strategy":"Book-Author (Dayanand Saraswati)."}],"mnemonic":"BRA (Brahmo-Roy-1828), ADS (Arya-Dayanand-Satyarth)","impact_emoji":"🕯️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('be426066-2577-45ea-ac69-3bda332c4538', 'unit_1', 'स्वतंत्रता संघर्ष एवं भारतीय राष्ट्रीय आंदोलन', NULL, '{"back":"1857 की क्रांति से लेकर 1947 तक आज़ादी के दीवानों के बलिदान और संघर्ष की पूरी कहानी।","impact_emoji":"🇮🇳"}', NULL, 24, 0, NULL, 1769948926, '{"front":"स्वतंत्रता संघर्ष एवं राष्ट्रीय आंदोलन","points":["1857: प्रथम स्वतंत्रता संग्राम (मंगल पांडे, झाँसी की रानी)।","गांधी युग: चंपारण (1917), असहयोग (1920), सविनय अवज्ञा (1930), भारत छोड़ो (1942)।","क्रांतिकारी: भगत सिंह (HRA/HSRA), सुभाष चंद्र बोस (आजाद हिंद फौज)।"],"pyq":[{"year":2022,"question":"कांग्रेस के किस अधिवेशन में ''पूर्ण स्वराज'' का प्रस्ताव पारित हुआ?","strategy":"अधिवेशन-वर्ष (लाहौर 1929)।"}],"mnemonic":"CAQ (Champaran-Asahyog-Quit India)","impact_emoji":"🇮🇳"}', '{"front":"Independence Struggle & National Movement","points":["1857: First War of Independence (Mangal Pandey, Rani of Jhansi).","Gandhian Era: Champaran (1917), Non-Cooperation (1920), Civil Disobedience (1930), Quit India (1942).","Revolutionaries: Bhagat Singh (HSRA), Subhash Chandra Bose (INA)."],"pyq":[{"year":2022,"question":"In which Congress session was the ''Purna Swaraj'' resolution passed?","strategy":"Session-Year (Lahore 1929)."}],"mnemonic":"CAQ (Champaran-NonCoop-Quit)","impact_emoji":"🇮🇳"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('93d7a6b0-082b-4ef2-acc5-fe06ca24e767', 'unit_1', 'स्वतंत्रता के पश्चात् भारत का एकीकरण एवं पुनर्गठन', NULL, '{"back":"आज़ादी के बाद टुकड़ों में बँटी रियासतों को जोड़कर एक मज़बूत भारत बनाने का सरदार पटेल का करिश्मा।","impact_emoji":"🔗"}', NULL, 25, 0, NULL, 1769948926, '{"front":"स्वतंत्रता पश्चात: एकीकरण एवं पुनर्गठन","points":["सरदार पटेल: रियासती मंत्रालय, ''लौह पुरुष'', जूनागढ़-हैदराबाद-कश्मीर का विलय।","ऑपरेशन पोलो (1948): हैदराबाद का पुलिस कार्यवाही द्वारा विलय।","राज्य पुनर्गठन आयोग (1953): अध्यक्ष फजल अली, आधार - भाषा।"],"pyq":[{"year":2020,"question":"स्वतंत्र भारत के प्रथम ''रियासती विभाग'' के सचिव कौन थे?","strategy":"प्रमुख व्यक्तित्व (वी.पी. मेनन)।"}],"mnemonic":"Patel-Polo-Police (हैदराबाद)","impact_emoji":"🤝"}', '{"front":"Post-Independence: Integration & Reorganization","points":["Sardar Patel: Ministry of States, ''Iron Man'', Integration of Junagadh-Hyderabad-Kashmir.","Operation Polo (1948): Police action to integrate Hyderabad.","States Reorganization Commission (1953): Chair Fazl Ali, Basis - Language."],"pyq":[{"year":2020,"question":"Who was the secretary of the ''States Department'' in independent India?","strategy":"Key Personality (V.P. Menon)."}],"mnemonic":"Patel-Polo-Police (Hyderabad)","impact_emoji":"🤝"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('0b1ccb3a-5922-4063-9b2d-77a7d915d606', 'unit_2', 'मध्यप्रदेश के इतिहास की महत्वपूर्ण घटनाएँ', 'Major Events and Dynasties of MP', '{"back":"प्राचीन काल से लेकर आधुनिक काल तक की वो घटनाएं जिन्होंने राज्य की दिशा तय की।"}', '{"back":"Key historical turning points and the rule of families like the Holkars, Scindias, Chandelas, and Parmars."}', 1, 0, NULL, 1769948926, '{"front":"मध्यप्रदेश के इतिहास की महत्वपूर्ण घटनाएँ","content":"प्रागैतिहासिक काल से आधुनिक काल तक के प्रमुख पड़ाव।","points":["भीमबेटका: विष्णु वाकणकर द्वारा खोज (1957), पुरापाषाण कालीन स्थल।","एरण अभिलेख (सागर): 510 ई. (भानुगुप्त), सती प्रथा का प्रथम लिखित साक्ष्य।","त्रिपुरी अधिवेशन (1939): जबलपुर, सुभाष चंद्र बोस अध्यक्ष चुने गए।"],"pyq":[{"year":2021,"question":"सती प्रथा का प्रथम अभिलेखीय साक्ष्य कहाँ मिला?","strategy":"एरण (सागर) - 510 ई. याद रखें।"}],"mnemonic":"Bhim (Oldest) - Eran (Sati) - Tripuri (Bose)","impact_emoji":"📜"}', '{"front":"Major Events of MP History","content":"Key milestones from Prehistoric to Modern times.","points":["Bhimbetka: Discovered by Vishnu Wakankar (1957), Paleolithic site.","Eran Inscription (Sagar): 510 AD (Bhanugupta), First written evidence of Sati.","Tripuri Session (1939): Jabalpur, Subhash Chandra Bose elected President."],"pyq":[{"year":2021,"question":"Where was the first epigraphic evidence of Sati found?","strategy":"Remember Eran (Sagar) - 510 AD."}],"mnemonic":"Bhim (Oldest) - Eran (Sati) - Tripuri (Bose)","impact_emoji":"📜"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('e23453c7-114c-4edd-b282-74e90c671670', 'unit_2', 'प्रमुख राजवंश और उनकी राजधानियाँ', 'Dynasties & Capitals', '{"back":"मध्य भारत की प्रमुख सत्तारूढ़ शक्तियाँ और उनकी सरकार के मुख्य केंद्र।","mnemonic":"होलकर इन डोर्स (इंदौर - Indore)","impact_emoji":"🏰","important_facts":["होलकर: इंदौर (मालवा)","सिंधिया: ग्वालियर","बुंदेला: ओरछा"]}', '{"back":"The major ruling powers of Central India and their primary seats of government.","mnemonic":"Holkar In Doors (Indore)","impact_emoji":"🏰","important_facts":["Holkar: Indore (Malwa)","Scindia: Gwalior","Bundela: Orchha"]}', 2, 0, NULL, 1769948926, '{"front":"प्रमुख राजवंश और उनकी राजधानियाँ","content":"क्षेत्रीय राजवंशों का उदय और प्रशासन।","points":["परमार वंश: राजा भोज (धार), सरस्वती कंठाभरण की रचना।","चंदेल वंश: नन्नुक द्वारा स्थापित, राजधानी- खजुराहो (जेजाकभुक्ति)।","कलचुरी वंश: कोक्कल प्रथम (त्रिपुरी/जबलपुर), ''हिन्द का नेपोलियन'' (कर्णदेव)।"],"pyq":[{"year":2022,"question":"राजा भोज किस राजवंश से संबंधित थे?","strategy":"धार नगरी = परमार वंश।"}],"mnemonic":"P-Dhar (Parmar) | C-Khajuraho (Chandela) | K-Tripuri (Kalchuri)","impact_emoji":"👑"}', '{"front":"Dynasties & Capitals","content":"Rise of regional dynasties and administration.","points":["Parmar Dynasty: Raja Bhoj (Dhar), Author of Saraswati Kanthabharana.","Chandela Dynasty: Founded by Nannuk, Capital- Khajuraho (Jejakbhukti).","Kalchuri Dynasty: Kokkal I (Tripuri/Jabalpur), ''Napoleon of Hind'' (Karndev)."],"pyq":[{"year":2022,"question":"Raja Bhoj belonged to which dynasty?","strategy":"City of Dhar = Parmar Dynasty."}],"mnemonic":"P-Dhar (Parmar) | C-Khajuraho (Chandela) | K-Tripuri (Kalchuri)","impact_emoji":"👑"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('438351cd-72a8-40fd-bff5-59ec421493c7', 'unit_2', 'स्वतंत्रता आंदोलन में मध्यप्रदेश का योगदान', 'Contribution of MP in Freedom Movement', '{"back":"1857 की क्रांति और जंगल सत्याग्रह जैसे आंदोलनों में MP के वीरों की भूमिका।"}', '{"back":"The sparks of resistance in MP, including the Forest Satyagraha and the bravery of local revolutionaries."}', 3, 0, NULL, 1769948926, '{"front":"स्वतंत्रता आंदोलन में मध्यप्रदेश का योगदान","content":"1857 की क्रांति और गांधीवादी आंदोलन।","points":["झंडा सत्याग्रह (1923): जबलपुर से प्रारंभ (प्रेमचंद, सुंदरलाल)।","चरण पादुका नरसंहार (1931): छतरपुर (उर्मिल नदी तट), ''म.प्र. का जलियाँवाला'' ।","जंगल सत्याग्रह (1930): घोड़ाडोंगरी (बैतूल - गंजन सिंह कोरकू)।"],"pyq":[{"year":2020,"question":"चरण पादुका नरसंहार किस जिले में हुआ था?","strategy":"C-C (Charan - Chhatarpur)।"}],"mnemonic":"Flag (Jabalpur) | Jungle (Betul) | Rice (Rewa)","impact_emoji":"🇮🇳"}', '{"front":"Contribution of MP in Freedom Movement","content":"1857 Revolt and Gandhian Movements.","points":["Flag Satyagraha (1923): Started from Jabalpur (Premchand, Sundarlal).","Charan Paduka Massacre (1931): Chhatarpur (Urmil River), ''Jallianwala of MP''.","Jungle Satyagraha (1930): Ghoradongri (Betul - Ganjan Singh Korku)."],"pyq":[{"year":2020,"question":"In which district did Charan Paduka massacre take place?","strategy":"C-C (Charan - Chhatarpur)."}],"mnemonic":"Flag (Jabalpur) | Jungle (Betul) | Rice (Rewa)","impact_emoji":"🇮🇳"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('e5003134-3e0d-4be8-aaf5-b0745a6d6040', 'unit_2', 'मध्यप्रदेश की प्रमुख कला एवं स्थापत्य कला', 'Major Arts and Sculpture of MP', '{"back":"खजुराहो के मंदिर, किलों की नक्काशी और प्राचीन गुफाओं की बेजोड़ बनावट।"}', '{"back":"Stone poetry! The intricate temples of Khajuraho and the ancient caves that showcase our artistic peak."}', 4, 0, NULL, 1769948926, '{"front":"मध्यप्रदेश की प्रमुख कला एवं स्थापत्य कला","content":"मंदिर, स्तूप और गुफा वास्तुकला।","points":["खजुराहो मंदिर: नागर शैली, चंदेल शासक (950-1050 ई.), कंदरिया महादेव प्रमुख।","सांची स्तूप: मौर्यकालीन (अशोक), तोरण द्वार (शुंग काल)।","बाघ की गुफाएं: धार (गुप्ताकालीन चित्रकला), बौद्ध धर्म से संबंधित।"],"pyq":[{"year":2023,"question":"कंदरिया महादेव मंदिर का निर्माण किसने करवाया?","strategy":"शक्तिशाली चंदेल राजा = विद्याधर।"}],"mnemonic":"K-Nagara (Style) | S-Buddhist (Theme) | B-Gupta (Period)","impact_emoji":"🛕"}', '{"front":"Major Arts and Sculpture of MP","content":"Temples, Stupas and Cave Architecture.","points":["Khajuraho Temples: Nagara Style, Chandela Rulers (950-1050 AD), Kandariya Mahadev.","Sanchi Stupa: Mauryan Era (Ashoka), Toran Gateways (Shunga Period).","Bagh Caves: Dhar (Gupta Era Paintings), Related to Buddhism."],"pyq":[{"year":2023,"question":"Who built the Kandariya Mahadev Temple?","strategy":"Powerful Chandela King = Vidyadhar."}],"mnemonic":"K-Nagara (Style) | S-Buddhist (Theme) | B-Gupta (Period)","impact_emoji":"🛕"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('d0aa63b0-7c54-4f9d-bac6-1767d1aa5859', 'unit_2', 'मध्यप्रदेश की प्रमुख जनजातियाँ', 'Major Tribes of MP', '{"back":"भील, गोंड, बैगा, सहरिया—जो MP की असली सांस्कृतिक विरासत के संरक्षक हैं।"}', '{"back":"The soul of the state—communities like Bhil, Gond, and Baiga who preserve the indigenous heritage."}', 5, 0, NULL, 1769948926, '{"front":"मध्यप्रदेश की प्रमुख जनजातियाँ","content":"जनजातीय जनसांख्यिकी और वर्गीकरण।","points":["भील: ''धनुष'' शब्द से उत्पत्ति, भगोरिया हाट (झाबुआ/अलीराजपुर)।","गोंड: भारत का सबसे बड़ा समूह (म.प्र. में दूसरा), प्रमुख देवता (बड़ादेव)।","बैगा: ''प्रकृति पुत्र'', दुनिया की सबसे प्राचीन जनजातियों में से एक।"],"pyq":[{"year":2021,"question":"दूध लौटावा प्रथा किस जनजाति में प्रचलित है?","strategy":"गोंड (ममेरे-फुफेरे भाई-बहन विवाह)।"}],"mnemonic":"Bhil (West) | Gond (Center/East) | Baiga (South-East)","impact_emoji":"🏹"}', '{"front":"Major Tribes of MP","content":"Tribal Demography and Classification.","points":["Bhil: Origin from ''Dhanush'' (Bow), Bhagoriya Haat (Jhabua/Alirajpur).","Gond: Largest group in India (2nd in MP), Main Deity (Badadev).","Baiga: ''Children of Nature'', One of the most primitive tribes."],"pyq":[{"year":2021,"question":"Doodh Lautawa custom is practiced in which tribe?","strategy":"Gond (Cousin Marriage)."}],"mnemonic":"Bhil (West) | Gond (Center/East) | Baiga (South-East)","impact_emoji":"🏹"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('aa73b0c2-9db0-44a1-9d2f-b4bd04728012', 'unit_2', 'जनजातियों की बोलियाँ', 'Dialects of Tribes', '{"back":"बघेली, निमाड़ी, मालवी और जनजातीय भाषाएं जो हमारी मिट्टी की खुशबू हैं।"}', '{"back":"The rich linguistic tapestry of MP including Bagheli, Nimadi, Malvi and various tribal dialects."}', 6, 0, NULL, 1769948926, '{"front":"जनजातियों की बोलियाँ","content":"क्षेत्रीय बोलियाँ और भाषाई परिवार।","points":["भीली: इंडो-आर्यन परिवार, गुजराती और राजस्थानी का प्रभाव।","गोंडी: द्रविड़ियन परिवार, तेलुगु और कन्नड़ से समानता।","कोरकू: ऑस्ट्रो-एशियाटिक परिवार (मुंडा शाखा)।"],"pyq":[{"year":2022,"question":"कोरकू जनजाति किस भाषाई परिवार से संबंधित है?","strategy":"Unique in MP = ऑस्ट्रो-एशियाटिक (मुंडा)।"}],"mnemonic":"Bhil (Aryan) | Gond (Dravidian) | Korku (Munda)","impact_emoji":"🗣️"}', '{"front":"Dialects of Tribes","content":"Regional dialects and Linguistic families.","points":["Bhili: Indo-Aryan family, Influence of Gujarati & Rajasthani.","Gondi: Dravidian family, Similarity with Telugu & Kannada.","Korku: Austro-Asiatic family (Munda branch)."],"pyq":[{"year":2022,"question":"Korku tribe belongs to which linguistic family?","strategy":"Unique in MP = Austro-Asiatic (Munda)."}],"mnemonic":"Bhil (Aryan) | Gond (Dravidian) | Korku (Munda)","impact_emoji":"🗣️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('0c84569b-a245-4ef2-bab6-43bdd137a217', 'unit_2', 'मध्यप्रदेश के प्रमुख त्योहार', 'Major Festivals of MP', '{"back":"लोकरंजन, भगोरिया और खजुराहो उत्सव जैसे सांस्कृतिक मिलन के अवसर।"}', '{"back":"Cultural celebrations like Lokranjan, Bhagoria, and the Khajuraho Dance Festival."}', 7, 0, NULL, 1769948926, '{"front":"मध्यप्रदेश के प्रमुख त्योहार","content":"सांस्कृतिक समारोह और उत्सव।","points":["तानसेन समारोह: ग्वालियर (दिसंबर), शास्त्रीय संगीत।","खजुराहो नृत्य महोत्सव: 1976 से प्रारंभ, शास्त्रीय नृत्य (फरवरी)।","लोकरंग: भोपाल (26 जनवरी), लोक कलाओं का प्रदर्शन।"],"pyq":[{"year":2023,"question":"खजुराहो नृत्य महोत्सव कब शुरू हुआ?","strategy":"Year = 1976 (Important Date)।"}],"mnemonic":"Tansen (Gwalior) | Kalidas (Ujjain) | Lokrang (Bhopal)","impact_emoji":"🎉"}', '{"front":"Major Festivals of MP","content":"Cultural Events and Celebrations.","points":["Tansen Samaroh: Gwalior (December), Classical Music.","Khajuraho Dance Festival: Started 1976, Classical Dance (February).","Lokrang: Bhopal (26 Jan), Display of Folk Arts."],"pyq":[{"year":2023,"question":"When did Khajuraho Dance Festival start?","strategy":"Year = 1976 (Important Date)."}],"mnemonic":"Tansen (Gwalior) | Kalidas (Ujjain) | Lokrang (Bhopal)","impact_emoji":"🎉"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('c8edb8b9-701c-4526-9d9e-239b48812382', 'unit_2', 'लोक संगीत', 'Folk Music', '{"back":"गाँव-गाँव में गूँजने वाले आल्हा, फाग और पंडवानी जैसे मधुर संगीत।"}', '{"back":"Traditional melodies echoing in villages, like Alha, Phag, and Pandvani."}', 8, 0, NULL, 1769948926, '{"front":"लोक संगीत (Folk Music)","content":"आंचलिक गायन शैलियाँ।","points":["आल्हा गायन (बुंदेलखंड): वीर रस, वर्षा ऋतु (आल्हा-ऊदल की गाथा)।","कलगी-तुर्रा (निमाड़): प्रतिस्पर्धात्मक गायन (शिव-शक्ति)।","भरथरी (मालवा): राजा भरथरी की कथा, नाथ संप्रदाय (चिंकारा वाद्य)।"],"pyq":[{"year":2021,"question":"आल्हा गायन किस ऋतु में गाया जाता है?","strategy":"Monsoon = वर्षा ऋतु।"}],"mnemonic":"Alha (Rain/War) | Bharthari (Morning/Malwa)","impact_emoji":"🎵"}', '{"front":"Folk Music","content":"Regional Singing Styles.","points":["Alha Singing (Bundelkhand): Heroic sentiment, Monsoon (Tales of Alha-Udal).","Kalgi-Turra (Nimar): Competitive singing (Shiva-Shakti).","Bharthari (Malwa): Tales of King Bharthari, Nath Sect (Chinkara instrument)."],"pyq":[{"year":2021,"question":"Alha singing is performed in which season?","strategy":"Monsoon = Rainy Season."}],"mnemonic":"Alha (Rain/War) | Bharthari (Morning/Malwa)","impact_emoji":"🎵"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('750c0124-994d-4a42-936c-5b71322bdbf5', 'unit_2', 'लोक कलाएँ', 'Folk Arts', '{"back":"मिट्टी के काम (Clay art), चित्रकारी और हस्तशिल्प जो MP को खास बनाते हैं।"}', '{"back":"Masterpieces of clay art, painting, and handicrafts that define MP''s artistic identity."}', 9, 0, NULL, 1769948926, '{"front":"लोक कलाएँ (Folk Arts)","content":"चित्रकला और हस्तशिल्प।","points":["पिथौरा (भील): घोड़ों का चित्रांकन, घर की दीवारों पर।","सांझा (मालवा): कुंवारी लड़कियों द्वारा, गोबर-फूल से (पितृपक्ष में)।","बाघ प्रिंट (धार): इस्माइल सुलेमानजी (GI टैग प्राप्त)।"],"pyq":[{"year":2020,"question":"सांझा किस क्षेत्र की लोककला है?","strategy":"M-M (Malwa - Maidens)।"}],"mnemonic":"Pithora-Horse | Sanjha-Wall | Bagh-Print","impact_emoji":"🖌️"}', '{"front":"Folk Arts","content":"Paintings and Handicrafts.","points":["Pithora (Bhil): Depiction of horses, on house walls.","Sanjha (Malwa): By unmarried girls, Cowdung-Flowers (Pitrapaksha).","Bagh Print (Dhar): Ismail Sulemanji (GI Tagged)."],"pyq":[{"year":2020,"question":"Sanjha is the folk art of which region?","strategy":"M-M (Malwa - Maidens)."}],"mnemonic":"Pithora-Horse | Sanjha-Wall | Bagh-Print","impact_emoji":"🖌️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('e9a35685-b7a4-4611-8de6-2608346743b5', 'unit_2', 'लोक-साहित्य', 'Folk Literature', '{"back":"क्षेत्रीय भाषाओं में रची गई वो कहानियाँ और कविताएँ जो पीढ़ियों से सुनी जा रही हैं।"}', '{"back":"Stories and poems composed in regional languages, passed down through oral traditions."}', 10, 0, NULL, 1769948926, '{"front":"लोक-साहित्य (Folk Literature)","content":"क्षेत्रीय कवि और उनकी रचनाएँ।","points":["संत सिंगाजी (निमाड़): कबीर के समकालीन, निर्गुण धारा।","ईसुरी (बुंदेलखंड): ''फाग के सम्राट'', रचना: ईसुरी की फाग।","घाघ (कृषि पंडित): कृषि संबंधी कहावतें।"],"pyq":[{"year":2022,"question":"ईसुरी का संबंध किस क्षेत्र से है?","strategy":"फाग = बुंदेलखंड।"}],"mnemonic":"Singaji (Nimar) | Isuri (Bundel) | Ghagh (Agri)","impact_emoji":"📖"}', '{"front":"Folk Literature","content":"Regional Poets and their works.","points":["Sant Singaji (Nimar): Contemporary of Kabir, Nirgun stream.","Isuri (Bundelkhand): ''Emperor of Phag'', Work: Isuri ki Phag.","Ghagh (Agri-Scholar): Agriculture proverbs."],"pyq":[{"year":2022,"question":"Isuri belongs to which region?","strategy":"Phag = Bundelkhand."}],"mnemonic":"Singaji (Nimar) | Isuri (Bundel) | Ghagh (Agri)","impact_emoji":"📖"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('d40d88ec-ef52-4366-9881-ae1be9d7300b', 'unit_2', 'मध्यप्रदेश के प्रमुख साहित्यकार एवं उनकी कृतियाँ', 'Important Literary Creators and their Creations', '{"back":"कालिदास, माखनलाल चतुर्वेदी और गजानन माधव मुक्तिबोध की अमर रचनाएँ।"}', '{"back":"The legends of the pen—from Kalidasa''s Sanskrit epics to the modern poetry of Makhanlal Chaturvedi."}', 11, 0, NULL, 1769948926, '{"front":"मध्यप्रदेश के प्रमुख साहित्यकार एवं कृतियाँ","content":"प्राचीन और आधुनिक साहित्यकार।","points":["कालिदास (उज्जैन): भारत का शेक्सपियर (मेघदूत, अभिज्ञान शाकुंतलम)।","माखनलाल चतुर्वेदी: ''एक भारतीय आत्मा'', रचना: हिमतरंगिनी (प्रथम साहित्य अकादमी)।","हरिशंकर परसाई: व्यंग्यकार (होशंगाबाद), रचना: ''विकलांग श्रद्धा का दौर''।"],"pyq":[{"year":2021,"question":"''पुष्प की अभिलाषा'' कविता किसने लिखी?","strategy":"माखनलाल चतुर्वेदी (बिलासपुर जेल में)।"}],"mnemonic":"Kalidas (Drama) | Makhan (Soul) | Parsai (Satire)","impact_emoji":"✍️"}', '{"front":"Important Literary Creators & Creations","content":"Ancient and Modern Writers.","points":["Kalidas (Ujjain): Shakespeare of India (Meghdoot, Abhigyan Shakuntalam).","Makhanlal Chaturvedi: ''An Indian Soul'', Work: Himtarangini (1st Sahitya Akademi).","Harishankar Parsai: Satirist (Hoshangabad), Work: ''Viklang Shraddha Ka Daur''."],"pyq":[{"year":2021,"question":"Who wrote the poem ''Pushp Ki Abhilasha''?","strategy":"Makhanlal Chaturvedi (In Bilaspur Jail)."}],"mnemonic":"Kalidas (Drama) | Makhan (Soul) | Parsai (Satire)","impact_emoji":"✍️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('a36e67c3-b307-4933-9b07-c414d03e7958', 'unit_2', 'धार्मिक, सांस्कृतिक एवं पुरातात्विक पर्यटन स्थल', 'Religious, Cultural, and Archaeological Tourism', '{"back":"उज्जैन के महाकाल, सांची के स्तूप और भीमबेटका की ऐतिहासिक गुफाएं।"}', '{"back":"Holy sites like Ujjain Mahakal, Sanchi Stupa, and Bhimbetka—where history meets spirituality."}', 12, 0, NULL, 1769948926, '{"front":"धार्मिक, सांस्कृतिक एवं पुरातात्विक पर्यटन","content":"तीर्थ स्थल और ऐतिहासिक स्मारक।","points":["ज्योतिर्लिंग: महाकालेश्वर (उज्जैन - दक्षिणमुखी) और ओंकारेश्वर (खंडवा)।","उदयगिरि की गुफाएं: विदिशा (वराह अवतार प्रतिमा - गुफा नं 5)।","जहाज महल: मांडू (सिटी ऑफ जॉय), गयासुद्दीन खिलजी द्वारा निर्मित।"],"pyq":[{"year":2020,"question":"वराह अवतार की विशाल प्रतिमा कहाँ स्थित है?","strategy":"उदयगिरि गुफा (विदिशा)।"}],"mnemonic":"Mandu (Joy) | Ujjain (Mahakal) | Vidisha (Caves)","impact_emoji":"🚩"}', '{"front":"Religious, Cultural & Archaeological Tourism","content":"Pilgrimage sites and Historical monuments.","points":["Jyotirlingas: Mahakaleshwar (Ujjain - South facing) & Omkareshwar (Khandwa).","Udayagiri Caves: Vidisha (Varaha Avatar Statue - Cave No 5).","Jahaz Mahal: Mandu (City of Joy), Built by Ghiyas-ud-din Khilji."],"pyq":[{"year":2020,"question":"Where is the colossal statue of Varaha Avatar located?","strategy":"Udayagiri Caves (Vidisha)."}],"mnemonic":"Mandu (Joy) | Ujjain (Mahakal) | Vidisha (Caves)","impact_emoji":"🚩"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('3f7fb8d6-f8cb-479d-b43f-c7353d6fc811', 'unit_2', 'मध्यप्रदेश में विश्व धरोहर स्थल', 'World Heritage Sites in MP', '{"back":"UNESCO द्वारा मान्यता प्राप्त अनमोल जगहें—खजुराहो, सांची और भीमबेटका।"}', '{"back":"The three jewels recognized by UNESCO: Khajuraho, Sanchi Stupa, and Bhimbetka Caves."}', 13, 0, NULL, 1769948926, '{"front":"मध्यप्रदेश में विश्व धरोहर स्थल (UNESCO)","content":"यूनेस्को द्वारा घोषित 3 प्रमुख स्थल।","points":["खजुराहो: 1986 (छतरपुर)।","सांची: 1989 (रायसेन)।","भीमबेटका: 2003 (रायसेन)।"],"pyq":[{"year":2023,"question":"भीमबेटका को विश्व धरोहर सूची में कब शामिल किया गया?","strategy":"K-S-B (86-89-03)।"}],"mnemonic":"19-86-89-03 (K-S-B)","impact_emoji":"🌍"}', '{"front":"World Heritage Sites in MP","content":"3 Major sites declared by UNESCO.","points":["Khajuraho: 1986 (Chhatarpur).","Sanchi: 1989 (Raisen).","Bhimbetka: 2003 (Raisen)."],"pyq":[{"year":2023,"question":"When was Bhimbetka included in World Heritage List?","strategy":"K-S-B (86-89-03)."}],"mnemonic":"19-86-89-03 (K-S-B)","impact_emoji":"🌍"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('82634033-dbe8-4088-9d2c-08826c163be5', 'unit_2', 'मध्यप्रदेश के प्रमुख जनजातीय व्यक्तित्व', 'Important Tribal Personalities of MP', '{"back":"टंट्या भील और रानी दुर्गावती जैसे महानायक जिन्होंने स्वाभिमान की रक्षा की।"}', '{"back":"Icons of pride like Tantya Bhil and Rani Durgavati who sacrificed everything for their land and dignity."}', 14, 0, NULL, 1769948926, '{"front":"मध्यप्रदेश के प्रमुख जनजातीय व्यक्तित्व","content":"स्वतंत्रता संग्राम सेनानी।","points":["रानी दुर्गावती: गोंडवाना, आसफ खान के विरुद्ध युद्ध (1564)।","शंकर शाह - रघुनाथ शाह: 1857 क्रांति (जबलपुर), तोप से उड़ाया गया।","भीमा नायक: ''निमाड़ का रॉबिनहुड'', अंबापानी का युद्ध।"],"pyq":[{"year":2022,"question":"रानी दुर्गावती ने किसके विरुद्ध युद्ध किया?","strategy":"अकबर का सेनापति = आसफ खान।"}],"mnemonic":"Durgavati (Akbar) | Shankar (Canon) | Bhima (Robinhood)","impact_emoji":"⚔️"}', '{"front":"Important Tribal Personalities of MP","content":"Freedom Fighters.","points":["Rani Durgavati: Gondwana, Fought against Asaf Khan (1564).","Shankar Shah - Raghunath Shah: 1857 Revolt (Jabalpur), Blown by cannon.","Bhima Nayak: ''Robinhood of Nimar'', Battle of Ambapani."],"pyq":[{"year":2022,"question":"Against whom did Rani Durgavati fight?","strategy":"Akbar''s General = Asaf Khan."}],"mnemonic":"Durgavati (Akbar) | Shankar (Canon) | Bhima (Robinhood)","impact_emoji":"⚔️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('7e09693c-78cc-4f17-b9ef-832665381a48', 'unit_3', 'पर्वत', 'Mountains', '{"back":"हिमालय से लेकर अरावली तक, भारत की वो ऊँचाइयाँ जो मानसून और सीमाओं की रक्षा करती हैं।"}', '{"back":"From the mighty Himalayas in the North to the ancient Aravallis, these peaks protect our borders and influence India''s monsoon."}', 1, 1, NULL, 1769948927, '{"front":"पर्वत","points":["हिमालय: वलित पर्वत, 4 श्रेणियाँ (ट्रांस, वृहद, लघु, शिवालिक)।","अरावली: विश्व की प्राचीनतम वलित पर्वतमाला, सर्वोच्च शिखर ''गुरु शिखर'' (1722 मी)।","K2 (गाडविन ऑस्टिन): भारत की सबसे ऊँची चोटी (8611 मी), काराकोरम श्रेणी में।"],"pyq":[{"year":2022,"question":"नंदा देवी चोटी हिमालय के किस भाग में स्थित है?","strategy":"प्रादेशिक विभाजन (कुमाऊँ हिमालय)।"}],"mnemonic":"KLZP (काराकोरम-लद्दाख-जास्कर-पीरपंजाल - उत्तर से दक्षिण)","impact_emoji":"🏔️"}', '{"front":"Mountains","points":["Himalayas: Fold mountains, 4 ranges (Trans, Greater, Lesser, Shiwalik).","Aravali: Oldest fold mountain in the world, Highest peak ''Guru Shikhar'' (1722m).","K2 (Godwin-Austen): Highest peak of India (8611m), in Karakoram range."],"pyq":[{"year":2022,"question":"Nanda Devi peak is located in which part of the Himalayas?","strategy":"Regional Division (Kumaon Himalaya)."}],"mnemonic":"KLZP (Karakoram-Ladakh-Zaskar-Pirpanjal - N to S)","impact_emoji":"🏔️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('d1ba8928-11aa-4635-8beb-a6b41870a72b', 'unit_3', 'पहाड़ियाँ', 'Hills', '{"back":"नीलगिरी और विंध्याचल जैसी छोटी पर्वत श्रृंखलाएँ जो जैव-विविधता का घर हैं।"}', '{"back":"Smaller mountain ranges like the Nilgiris and Western Ghats that are hotspots for biodiversity and heavy rainfall."}', 2, 0, NULL, 1769948927, '{"front":"पहाड़ियाँ","points":["नीलगिरि: पश्चिमी और पूर्वी घाट का मिलन बिंदु, सर्वोच्च चोटी ''डोडाबेटा'' (2637 मी)।","अन्नामलाई: दक्षिण भारत की सबसे ऊँची चोटी ''अनाईमुडी'' (2695 मी) यहीं है।","गारो-खासी-जयंतिया: मेघालय में कीपनुमा पहाड़ियाँ, सर्वाधिक वर्षा (मासिनराम)।"],"pyq":[{"year":2020,"question":"कार्डमम पहाड़ियाँ (इलायची पहाड़ियाँ) किन राज्यों की सीमा पर स्थित हैं?","strategy":"मानचित्र अध्ययन (केरल-तमिलनाडु)।"}],"mnemonic":"N-A-C (North to South: Nilgiri-Annamalai-Cardamom)","impact_emoji":"⛰️"}', '{"front":"Hills","points":["Nilgiri: Meeting point of Western & Eastern Ghats, Highest peak ''Doda Betta'' (2637m).","Annamalai: Home to South India''s highest peak ''Anaimudi'' (2695m).","Garo-Khasi-Jaintia: Funnel-shaped hills in Meghalaya, Highest rainfall (Mawsynram)."],"pyq":[{"year":2020,"question":"Cardamom Hills are located on the border of which states?","strategy":"Map Study (Kerala-Tamil Nadu)."}],"mnemonic":"N-A-C (North to South: Nilgiri-Annamalai-Cardamom)","impact_emoji":"⛰️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('fd2793b6-1226-4c44-b43d-9c7997990081', 'unit_3', 'पठार', 'Plateaus', '{"back":"दक्कन और छोटा नागपुर का पठार जहाँ भारत का सबसे ज़्यादा खनिज पाया जाता है।"}', '{"back":"The Deccan and Chota Nagpur plateaus—the ''mineral heart'' of India where most of our natural resources are found."}', 3, 0, NULL, 1769948927, '{"front":"पठार","points":["दक्कन का पठार: विशालतम, त्रिभुजाकार, बेसाल्ट चट्टानों (काली मिट्टी) से निर्मित।","छोटा नागपुर: ''भारत का रूर'' (खनिज संपदा), सर्वोच्च चोटी ''पारसनाथ''।","मालवा का पठार: चंबल और बेतवा नदियाँ, ''रोटी की डलिया''।"],"pyq":[{"year":2021,"question":"मेघालय का पठार किसका विस्तार है?","strategy":"भूगर्भिक संरचना (प्रायद्वीपीय पठार)।"}],"mnemonic":"Mineral Heart (Chota Nagpur)","impact_emoji":"🌋"}', '{"front":"Plateaus","points":["Deccan Plateau: Largest, Triangular, made of Basalt rocks (Black Soil).","Chota Nagpur: ''Ruhr of India'' (Mineral rich), Highest peak ''Parasnath''.","Malwa Plateau: Drained by Chambal & Betwa, ''Wheat Basket''."],"pyq":[{"year":2021,"question":"The Meghalaya Plateau is an extension of which structure?","strategy":"Geological Structure (Peninsular Plateau)."}],"mnemonic":"Mineral Heart (Chota Nagpur)","impact_emoji":"🌋"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('a8c8bfd2-1d7e-46c4-be94-d13f596be982', 'unit_3', 'नदियाँ', 'Rivers', '{"back":"गंगा, नर्मदा और कावेरी—भारत की जीवन रेखाएं जो प्यास भी बुझाती हैं और संस्कृति भी पालती हैं।"}', '{"back":"Life-lines of India like the Ganga, Narmada, and Kaveri that provide water for agriculture and sacred cultural roots."}', 4, 0, NULL, 1769948927, '{"front":"नदियाँ","points":["गंगा: भारत की सबसे लंबी नदी (2525 किमी), पंच प्रयाग (देवप्रयाग: भागीरथी+अलकनंदा)।","गोदावरी: ''दक्षिण गंगा'' या ''बूढ़ी गंगा'', प्रायद्वीपीय भारत की सबसे लंबी नदी (1465 किमी)।","भ्रंश घाटी नदियाँ: नर्मदा और ताप्ती (पश्चिम की ओर बहने वाली)।"],"pyq":[{"year":2023,"question":"सिंधु नदी जल समझौता (1960) किन दो देशों के बीच हुआ?","strategy":"संधि/वर्ष (भारत-पाकिस्तान)।"}],"mnemonic":"B-A-G (Bhagirathi + Alaknanda = Ganga)","impact_emoji":"🌊"}', '{"front":"Rivers","points":["Ganga: Longest river in India (2525 km), Panch Prayag (Devprayag: Bhagirathi+Alaknanda).","Godavari: ''Dakshin Ganga'' or ''Old Ganga'', Longest peninsular river (1465 km).","Rift Valley Rivers: Narmada and Tapti (West flowing)."],"pyq":[{"year":2023,"question":"Indus Water Treaty (1960) was signed between which two countries?","strategy":"Treaty/Year (India-Pakistan)."}],"mnemonic":"B-A-G (Bhagirathi + Alaknanda = Ganga)","impact_emoji":"🌊"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('69ddbd9a-1d3a-46b4-9d81-613da3524294', 'unit_3', 'झीलें', 'Lakes', '{"back":"चिल्का से लेकर वुलर तक, भारत के वो प्राकृतिक जल निकाय जो इकोसिस्टम का हिस्सा हैं।"}', '{"back":"Natural water bodies like Chilika and Wular that support local ecosystems and migratory birds."}', 5, 0, NULL, 1769948927, '{"front":"झीलें","points":["चिल्का (ओडिशा): भारत की सबसे बड़ी खारे पानी की लैगून झील।","वुलर (J&K): भारत की सबसे बड़ी मीठे पानी की झील (झेलम नदी)।","लोकटक (मणिपुर): ''केइबुल लामजाओ'' (तैरता हुआ राष्ट्रीय उद्यान)।"],"pyq":[{"year":2019,"question":"श्रीहरिकोटा द्वीप किस झील को बंगाल की खाड़ी से अलग करता है?","strategy":"अवस्थिति (पुलिकट झील)।"}],"mnemonic":"Loktak-Floating (मणिपुर में तैरता)","impact_emoji":"🚣"}', '{"front":"Lakes","points":["Chilika (Odisha): Largest brackish water lagoon in India.","Wular (J&K): Largest fresh water lake in India (fed by Jhelum).","Loktak (Manipur): ''Keibul Lamjao'' (Only floating National Park)."],"pyq":[{"year":2019,"question":"Sriharikota Island separates which lake from the Bay of Bengal?","strategy":"Location (Pulicat Lake)."}],"mnemonic":"Loktak-Floating","impact_emoji":"🚣"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('feae7943-40c2-4f50-a0c9-5988731e7575', 'unit_3', 'जलवायु घटनाएँ—अल-नीनो, ला-नीना', 'Climate Phenomena: El Nino & La Nina', '{"back":"प्रशांत महासागर की वो हलचल जो भारत की बारिश और सूखे को तय करती है।"}', '{"back":"Major Pacific Ocean events that can cause either drought or heavy monsoon rains in India."}', 6, 0, NULL, 1769948927, '{"front":"जलवायु घटनाएँ—अल-नीनो, ला-नीना","points":["अल-नीनो: प्रशांत महासागर का गर्म होना, भारतीय मानसून को कमजोर करता है (सूखा)।","ला-नीना: प्रशांत महासागर का ठंडा होना, भारतीय मानसून को मजबूत करता है (वर्षा)।","आवृति: ये घटनाएं हर 2-7 साल में अनियमित रूप से होती हैं।"],"pyq":[{"year":2022,"question":"अल-नीनो का शाब्दिक अर्थ क्या है?","strategy":"स्पेनिश शब्द (छोटा बच्चा/Christ Child)।"}],"mnemonic":"El Nino = Enemy (सूखा), La Nina = Love (बारिश)","impact_emoji":"🌧️"}', '{"front":"Climate Phenomena: El Nino & La Nina","points":["El Nino: Warming of Pacific, Weakens Indian Monsoon (Droughts).","La Nina: Cooling of Pacific, Strengthens Indian Monsoon (Heavy Rains).","Frequency: Occurs irregularly every 2-7 years."],"pyq":[{"year":2022,"question":"What is the literal meaning of El Nino?","strategy":"Spanish Term (Little Boy/Christ Child)."}],"mnemonic":"El Nino = Enemy (Dry), La Nina = Love (Rain)","impact_emoji":"🌧️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('864f7665-1925-4189-b5a7-3591c77cdf5b', 'unit_3', 'दक्षिणी दोलन', 'Southern Oscillation', '{"back":"हवा के दबाव में होने वाला बदलाव जो मानसून की ताकत को प्रभावित करता है।"}', '{"back":"Periodic changes in air pressure over the ocean that directly impact the strength of our rainy season."}', 7, 0, NULL, 1769948927, '{"front":"दक्षिणी दोलन (Southern Oscillation)","points":["परिभाषा: उष्णकटिबंधीय प्रशांत महासागर में वायुमंडलीय दबाव का उतार-चढ़ाव।","संबंध: अल-नीनो के साथ मिलकर ENSO (El Nino Southern Oscillation) बनाता है।","मापन: ताहिती (फ्रेंच पोलिनेशिया) और डार्विन (ऑस्ट्रेलिया) के दबाव अंतर से।"],"pyq":[{"year":2021,"question":"दक्षिणी दोलन का संबंध किस महासागर से है?","strategy":"महासागर (प्रशांत/Pacific)।"}],"mnemonic":"See-Saw of Pressure (दबाव का झूला)","impact_emoji":"🌬️"}', '{"front":"Southern Oscillation","points":["Definition: Fluctuation in atmospheric pressure over the tropical Pacific Ocean.","Relation: Combined with El Nino, it forms ENSO (El Nino Southern Oscillation).","Measurement: Pressure difference between Tahiti and Darwin."],"pyq":[{"year":2021,"question":"Southern Oscillation is related to which ocean?","strategy":"Ocean (Pacific)."}],"mnemonic":"See-Saw of Pressure","impact_emoji":"🌬️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('c74d09d0-2af7-4650-beb5-fd4710f49853', 'unit_3', 'पश्चिमी विक्षोभ (Western Disturbances)', 'Western Disturbance', '{"back":"सर्दियों में उत्तर भारत में होने वाली वो बारिश जो रबी की फसल के लिए सोना है।"}', '{"back":"Winter storms from the Mediterranean that bring much-needed rain to North India for the Rabi crops."}', 8, 0, NULL, 1769948927, '{"front":"पश्चिमी विक्षोभ (Western Disturbance)","points":["उत्पत्ति: भूमध्य सागर (Mediterranean Sea) से उठने वाले चक्रवात।","शीतकालीन वर्षा: उत्तर-पश्चिम भारत (पंजाब, हरियाणा) में रबी फसलों (गेहूँ) के लिए लाभदायक।","जेट स्ट्रीम: पछुवा जेट स्ट्रीम इसे भारत की ओर लाती है।"],"pyq":[{"year":2020,"question":"भारत में शीतकालीन वर्षा का मुख्य कारण क्या है?","strategy":"कारण (पश्चिमी विक्षोभ)।"}],"mnemonic":"Medi-Rain (भूमध्य सागर से वर्षा)","impact_emoji":"🌾"}', '{"front":"Western Disturbance","points":["Origin: Cyclonic storms originating from the Mediterranean Sea.","Winter Rain: Beneficial for Rabi crops (Wheat) in NW India (Punjab, Haryana).","Jet Stream: Westerly Jet Stream brings it to India."],"pyq":[{"year":2020,"question":"What is the main cause of winter rainfall in NW India?","strategy":"Cause (Western Disturbance)."}],"mnemonic":"Medi-Rain (Rain from Mediterranean)","impact_emoji":"🌾"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('49332f93-bdac-4451-9b46-13b551a2170f', 'unit_3', 'जलवायु परिवर्तन के परिणाम', 'Consequences of Climate Change', '{"back":"बढ़ता तापमान और पिघलते ग्लेशियर—आने वाले समय की सबसे बड़ी चुनौती।"}', '{"back":"Glacier melting, rising sea levels, and unpredictable weather—the biggest challenge for India''s future."}', 9, 0, NULL, 1769948927, '{"front":"जलवायु परिवर्तन के परिणाम","points":["ग्लेशियर पिघलना: हिमालयी नदियाँ प्रभावित, समुद्र स्तर में वृद्धि (सुंदरबन को खतरा)।","कृषि: मानसून की अनियमितता से फसल चक्र प्रभावित।","चरम घटनाएँ: लू (Heatwaves), चक्रवात और बादलों का फटना (Cloudbursts) की वृद्धि।"],"pyq":[{"year":2023,"question":"भारत का कौन सा क्षेत्र समुद्र जल स्तर बढ़ने से सर्वाधिक खतरे में है?","strategy":"तटीय क्षेत्र (सुंदरबन/लक्षद्वीप)।"}],"mnemonic":"HOT (Heat-Ocean rise-Time unpredictable)","impact_emoji":"🌡️"}', '{"front":"Consequences of Climate Change","points":["Glacier Melt: Affects Himalayan rivers, Sea level rise (Threat to Sundarbans).","Agriculture: Erratic monsoon affects crop cycles.","Extreme Events: Increase in Heatwaves, Cyclones, and Cloudbursts."],"pyq":[{"year":2023,"question":"Which Indian region is most threatened by rising sea levels?","strategy":"Coastal Region (Sundarbans/Lakshadweep)."}],"mnemonic":"HOT (Heat-Ocean rise-Time unpredictable)","impact_emoji":"🌡️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('880cb60d-e159-4ef1-b0ad-c5ef328a691c', 'unit_3', 'प्राकृतिक संसाधन—वन', 'Natural Resources: Forests', '{"back":"भारत के फेफड़े—सदाबहार से लेकर कटीले वनों तक की हरियाली।"}', '{"back":"India''s green cover—from tropical evergreens to dry deciduous forests that act as the country''s lungs."}', 10, 0, NULL, 1769948927, '{"front":"प्राकृतिक संसाधन—वन","points":["ISFR 2021: म.प्र. में सर्वाधिक वन क्षेत्र (Area), मिजोरम में सर्वाधिक प्रतिशत।","वर्गीकरण: उष्णकटिबंधीय पर्णपाती वन (भारत में सर्वाधिक विस्तार)।","नीति: राष्ट्रीय वन नीति 1988 (लक्ष्य: 33% भू-भाग पर वन)।"],"pyq":[{"year":2022,"question":"भारतीय वन सर्वेक्षण (FSI) का मुख्यालय कहाँ है?","strategy":"संस्थान (देहरादून)।"}],"mnemonic":"MP-Area, Miz-Percent (MAP)","impact_emoji":"🌲"}', '{"front":"Natural Resources: Forests","points":["ISFR 2021: MP has largest Area, Mizoram has highest Percentage.","Classification: Tropical Deciduous Forests (Most widespread in India).","Policy: National Forest Policy 1988 (Target: 33% land cover)."],"pyq":[{"year":2022,"question":"Where is the headquarters of Forest Survey of India (FSI)?","strategy":"Institution (Dehradun)."}],"mnemonic":"MP-Area, Miz-Percent (MAP)","impact_emoji":"🌲"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('50350549-83a0-46a7-ad63-44c96299c94d', 'unit_3', 'प्राकृतिक संसाधन—खनिज', 'Natural Resources: Minerals', '{"back":"ज़मीन के नीचे छुपा लोहा, कोयला और सोना जो देश की इकॉनमी चलाता है।"}', '{"back":"The hidden wealth of iron, coal, and gold under our soil that drives the nation''s industrial economy."}', 11, 0, NULL, 1769948927, '{"front":"प्राकृतिक संसाधन—खनिज","points":["लौह अयस्क: हेमेटाइट (ओडिशा प्रमुख उत्पादक), मैग्नेटाइट (कर्नाटक - कुद्रेमुख)।","कोयला: गोंडवाना क्रम की चट्टानें (98%), झारखंड (झरिया), ओडिशा (तालचेर)।","तांबा: बालाघाट (म.प्र.) की मलाजखंड खदान ''तांबा नगरी'' कहलाती है।"],"pyq":[{"year":2020,"question":"बैलाडीला (छत्तीसगढ़) किस खनिज के लिए प्रसिद्ध है?","strategy":"खदान-खनिज (लौह अयस्क)।"}],"mnemonic":"Iron-Odisha, Copper-MP, Gold-Karnataka","impact_emoji":"⛏️"}', '{"front":"Natural Resources: Minerals","points":["Iron Ore: Hematite (Odisha top producer), Magnetite (Karnataka - Kudremukh).","Coal: Gondwana rocks (98%), Jharkhand (Jharia), Odisha (Talcher).","Copper: Malanjkhand mine in Balaghat (MP) is ''Copper City''."],"pyq":[{"year":2020,"question":"Bailadila (Chhattisgarh) is famous for which mineral?","strategy":"Mine-Mineral (Iron Ore)."}],"mnemonic":"Iron-Odisha, Copper-MP, Gold-Karnataka","impact_emoji":"⛏️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('070a0a88-2e2d-4166-8f37-c990c8e1ff33', 'unit_3', 'प्राकृतिक संसाधन—जल संसाधन', 'Natural Resources: Water Resources', '{"back":"नहरों, बांधों और बारिश के पानी का सही प्रबंधन जो खेती का आधार है।"}', '{"back":"The management of rivers, dams, and rainfall to ensure water for every citizen and farm."}', 12, 0, NULL, 1769948927, '{"front":"प्राकृतिक संसाधन—जल संसाधन","points":["उपलब्धता: भारत में विश्व के जल संसाधनों का केवल 4% है (जनसंख्या 18%)।","सिंचाई: नलकूप (Tubewells) सिंचाई का मुख्य स्रोत हैं (लगभग 46%)।","नमामि गंगे: गंगा संरक्षण मिशन (शुरुआत: 2014)।"],"pyq":[{"year":2021,"question":"भारत में सिंचाई का सबसे प्रमुख साधन कौन सा है?","strategy":"आंकड़े (नलकूप/कुएं)।"}],"mnemonic":"Tube-Canal-Tank (क्रम: नलकूप-नहर-तालाब)","impact_emoji":"💧"}', '{"front":"Natural Resources: Water Resources","points":["Availability: India has only 4% of world''s water resources (Population 18%).","Irrigation: Tubewells are the main source of irrigation (~46%).","Namami Gange: Ganga conservation mission (Launched: 2014)."],"pyq":[{"year":2021,"question":"Which is the main source of irrigation in India?","strategy":"Data (Tubewells/Wells)."}],"mnemonic":"Tube-Canal-Tank (Order)","impact_emoji":"💧"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('2a6dfb13-b90d-4fc4-a03e-0abfd75cd5a9', 'unit_3', 'प्रमुख फसलें', 'Major Crops', '{"back":"गेहूँ, चावल और मसालों की खेती जो पूरी दुनिया का पेट भरती है।"}', '{"back":"The staple foods like Rice and Wheat, and cash crops like Sugarcane that feed over a billion people."}', 13, 0, NULL, 1769948927, '{"front":"प्रमुख फसलें","points":["रबी: शीतकालीन (गेहूँ, चना, सरसों), बुवाई: अक्टू-नवं।","खरीफ: वर्षाकालीन (चावल, सोयाबीन, कपास), बुवाई: जून-जुलाई।","नगदी फसलें: गन्ना, कपास, जूट, तंबाकू।"],"pyq":[{"year":2022,"question":"सोयाबीन उत्पादन में कौन सा राज्य शीर्ष पर है (2022-23)?","strategy":"आर्थिक सर्वेक्षण (महाराष्ट्र/म.प्र.)।"}],"mnemonic":"Rabi-Wheat (RW), Kharif-Rice (KR)","impact_emoji":"🌽"}', '{"front":"Major Crops","points":["Rabi: Winter crops (Wheat, Gram, Mustard), Sown: Oct-Nov.","Kharif: Monsoon crops (Rice, Soybean, Cotton), Sown: June-July.","Cash Crops: Sugarcane, Cotton, Jute, Tobacco."],"pyq":[{"year":2022,"question":"Which state tops in Soybean production (2022-23)?","strategy":"Eco Survey (Maharashtra/MP)."}],"mnemonic":"Rabi-Wheat (RW), Kharif-Rice (KR)","impact_emoji":"🌽"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('3d1a6aa7-d9e2-4d27-8ec5-bf03c25dc417', 'unit_3', 'खाद्य सुरक्षा', 'Food Security', '{"back":"हर नागरिक तक अनाज पहुँचाने की सरकारी और सामाजिक ज़िम्मेदारी।"}', '{"back":"The national mission to ensure no citizen goes hungry by managing grain stocks and distribution."}', 14, 0, NULL, 1769948928, '{"front":"खाद्य सुरक्षा","points":["NFSA 2013: 75% ग्रामीण और 50% शहरी आबादी को कवर करता है।","अधिकार: 5 किलो खाद्यान्न प्रति व्यक्ति/माह (चावल ₹3, गेहूं ₹2, मोटा अनाज ₹1)।","बफर स्टॉक: FCI (Food Corporation of India) द्वारा अनाज का भंडारण।"],"pyq":[{"year":2020,"question":"राष्ट्रीय खाद्य सुरक्षा अधिनियम किस वर्ष पारित किया गया?","strategy":"वर्ष (2013)।"}],"mnemonic":"3-2-1 Rates (Rice-Wheat-Coarse)","impact_emoji":"🍚"}', '{"front":"Food Security","points":["NFSA 2013: Covers 75% rural and 50% urban population.","Entitlement: 5kg grains per person/month (Rice ₹3, Wheat ₹2, Coarse ₹1).","Buffer Stock: Maintained by FCI (Food Corporation of India)."],"pyq":[{"year":2020,"question":"In which year was the National Food Security Act passed?","strategy":"Year (2013)."}],"mnemonic":"3-2-1 Rates (Rice-Wheat-Coarse)","impact_emoji":"🍚"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('b94cba9e-cfea-4a7b-9fc9-339f79834306', 'unit_3', 'हरित क्रांति', 'Green Revolution', '{"back":"60 के दशक का वो चमत्कार जिसने भारत को अनाज के लिए आत्मनिर्भर बनाया।"}', '{"back":"The 1960s transformation that used technology and seeds to make India self-sufficient in food grains."}', 15, 0, NULL, 1769948928, '{"front":"हरित क्रांति","points":["जनक: नॉर्मन बोरलॉग (विश्व), एम.एस. स्वामीनाथन (भारत)।","शुरुआत: 1966-67, उच्च उपज वाले बीज (HYV) का प्रयोग।","प्रभाव: गेहूँ (सर्वाधिक लाभ) और चावल के उत्पादन में वृद्धि, पंजाब-हरियाणा प्रमुख केंद्र।"],"pyq":[{"year":2019,"question":"हरित क्रांति का सर्वाधिक प्रभाव किस फसल पर पड़ा?","strategy":"फसल (गेहूँ)।"}],"mnemonic":"HYV Seeds + Water = Green Rev","impact_emoji":"🚜"}', '{"front":"Green Revolution","points":["Father: Norman Borlaug (World), M.S. Swaminathan (India).","Start: 1966-67, Use of High Yielding Variety (HYV) seeds.","Impact: Boom in Wheat (Max benefit) & Rice, Punjab-Haryana key centers."],"pyq":[{"year":2019,"question":"Which crop was most benefited by the Green Revolution?","strategy":"Crop (Wheat)."}],"mnemonic":"HYV Seeds + Water = Green Rev","impact_emoji":"🚜"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('686a532e-b7b0-47c1-bf67-903786ca06ae', 'unit_3', 'दूसरी हरित क्रांति की रणनीतियाँ', 'Strategies for Second Green Revolution', '{"back":"आधुनिक तकनीक और सस्टेनेबल खेती के साथ उत्पादन बढ़ाने का नया प्लान।"}', '{"back":"Focusing on sustainable farming, technology, and high-yield seeds to feed the future population."}', 16, 0, NULL, 1769948928, '{"front":"दूसरी हरित क्रांति की रणनीतियाँ","points":["लक्ष्य: सतत कृषि, पूर्वी भारत (Eastern India) पर फोकस, दलहन-तिलहन का समावेश।","इंद्रधनुषी क्रांति: कृषि के सभी क्षेत्रों (फसल, बागवानी, मछली) का समग्र विकास।","मृदा स्वास्थ्य कार्ड: 2015 में लॉन्च, मिट्टी की गुणवत्ता सुधारना।"],"pyq":[{"year":2023,"question":"सदाबहार क्रांति (Evergreen Revolution) का आह्वान किसने किया था?","strategy":"व्यक्ति (एम.एस. स्वामीनाथन)।"}],"mnemonic":"Sustainable & East (सतत और पूर्वी भारत)","impact_emoji":"🌱"}', '{"front":"Strategies for 2nd Green Revolution","points":["Goal: Sustainable agriculture, Focus on Eastern India, Inclusion of Pulses/Oilseeds.","Rainbow Revolution: Holistic development of all agri-sectors.","Soil Health Card: Launched 2015, to improve soil quality."],"pyq":[{"year":2023,"question":"Who gave the call for ''Evergreen Revolution''?","strategy":"Person (M.S. Swaminathan)."}],"mnemonic":"Sustainable & East","impact_emoji":"🌱"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('93f9b95e-932a-45b0-8409-7631c4bf39ff', 'unit_3', 'ऊर्जा के पारंपरिक स्रोत', 'Conventional Sources of Energy', '{"back":"कोयला और पेट्रोलियम—जो सालों से हमारी बिजली और गाड़ियों की ज़रूरत पूरी कर रहे हैं।"}', '{"back":"Traditional power sources like Coal and Petroleum that have powered our vehicles and homes for decades."}', 17, 0, NULL, 1769948928, '{"front":"ऊर्जा के पारंपरिक स्रोत","points":["कोयला: भारत में ऊर्जा का प्राथमिक स्रोत (~55% बिजली उत्पादन)।","पेट्रोलियम: बॉम्बे हाई (सबसे बड़ा अपतटीय क्षेत्र), डिगबोई (असम - सबसे पुराना)।","प्राकृतिक गैस: कृष्णा-गोदावरी बेसिन (K-G Basin) प्रमुख क्षेत्र।"],"pyq":[{"year":2021,"question":"भारत में सबसे पुराना तेल क्षेत्र कौन सा है?","strategy":"स्थान (डिगबोई)।"}],"mnemonic":"Coal is King (Energy Mix)","impact_emoji":"🏭"}', '{"front":"Conventional Sources of Energy","points":["Coal: Primary source of energy in India (~55% electricity generation).","Petroleum: Bombay High (Largest offshore), Digboi (Assam - Oldest).","Natural Gas: Krishna-Godavari Basin (K-G Basin) is a key region."],"pyq":[{"year":2021,"question":"Which is the oldest oil field in India?","strategy":"Location (Digboi)."}],"mnemonic":"Coal is King","impact_emoji":"🏭"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('1095df19-7851-4ef7-828d-29d8dfa7d78f', 'unit_3', 'ऊर्जा के गैर-पारंपरिक स्रोत', 'Non-Conventional Sources of Energy', '{"back":"सौर ऊर्जा और पवन ऊर्जा—भविष्य की साफ और कभी न खत्म होने वाली बिजली।"}', '{"back":"Future energy like Solar and Wind—clean, green, and never-ending power."}', 18, 0, NULL, 1769948928, '{"front":"ऊर्जा के गैर-पारंपरिक स्रोत","points":["सौर ऊर्जा: भारत ISA (अंतर्राष्ट्रीय सौर गठबंधन) का संस्थापक, रीवा (MP) में सोलर प्लांट।","पवन ऊर्जा: तमिलनाडु और गुजरात अग्रणी राज्य।","परमाणु ऊर्जा: तारापुर (पहला संयंत्र), कुडनकुलम (रूस की सहायता से)।"],"pyq":[{"year":2022,"question":"अंतर्राष्ट्रीय सौर गठबंधन (ISA) का मुख्यालय कहाँ है?","strategy":"स्थान (गुरुग्राम)।"}],"mnemonic":"Sun-Wind-Atom (Future Energy)","impact_emoji":"☀️"}', '{"front":"Non-Conventional Sources of Energy","points":["Solar: India founder of ISA, Rewa (MP) Ultra Mega Solar Plant.","Wind: Tamil Nadu and Gujarat are leading states.","Nuclear: Tarapur (First plant), Kudankulam (Russian aid)."],"pyq":[{"year":2022,"question":"Where is the HQ of International Solar Alliance (ISA)?","strategy":"Location (Gurugram)."}],"mnemonic":"Sun-Wind-Atom","impact_emoji":"☀️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('5779401b-973a-4aa0-983f-1be0a3a4eab8', 'unit_3', 'भारत में प्राकृतिक खतरे और आपदाएँ', 'Natural Hazards and Disasters in India', '{"back":"बाढ़, भूकंप और सूखा—प्रकृति की वो चुनौतियां जिनसे हमें निपटना सीखना है।"}', '{"back":"Challenges like floods, earthquakes, and landslides that require smart planning and quick response."}', 19, 0, NULL, 1769948928, '{"front":"भारत में प्राकृतिक खतरे और आपदाएँ","points":["भूकंप: हिमालय क्षेत्र जोन V (सर्वाधिक जोखिम), भुज भूकंप (2001)।","बाढ़: गंगा-ब्रह्मपुत्र बेसिन सर्वाधिक प्रभावित, असम और बिहार।","NDMA: राष्ट्रीय आपदा प्रबंधन प्राधिकरण, अध्यक्ष - प्रधानमंत्री।"],"pyq":[{"year":2020,"question":"आपदा प्रबंधन अधिनियम किस वर्ष लागू हुआ?","strategy":"वर्ष (2005)।"}],"mnemonic":"PM leads NDMA (PM अध्यक्ष)","impact_emoji":"🚨"}', '{"front":"Natural Hazards & Disasters","points":["Earthquake: Himalayan region Zone V (High Risk), Bhuj Earthquake (2001).","Floods: Ganga-Brahmaputra basin most affected (Assam, Bihar).","NDMA: National Disaster Management Authority, Headed by Prime Minister."],"pyq":[{"year":2020,"question":"In which year was the Disaster Management Act enacted?","strategy":"Year (2005)."}],"mnemonic":"PM leads NDMA","impact_emoji":"🚨"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('b5bc6857-bff7-4579-b1ac-ad5d2df06550', 'unit_3', 'भारत में प्रमुख चक्रवात', 'Major Cyclones in India', '{"back":"समुद्र से आने वाले वो तूफान जो तटीय इलाकों में तबाही और बारिश लाते हैं।"}', '{"back":"Powerful sea storms that hit our coastal areas, bringing heavy wind and rainfall."}', 20, 0, NULL, 1769948928, '{"front":"भारत में प्रमुख चक्रवात","points":["ओडिशा: 1999 का सुपर साइक्लोन, ''फानी'' (2019)।","अरब सागर: हाल ही में आवृत्ति बढ़ी (जैसे ''बिपरजॉय'', ''तौकते'')।","नामाकरण: हिंद महासागर के 13 देश बारी-बारी से नाम देते हैं।"],"pyq":[{"year":2021,"question":"चक्रवात ''तौकते'' (Tauktae) का नामकरण किस देश ने किया था?","strategy":"देश-नाम (म्यांमार - अर्थ: छिपकली)।"}],"mnemonic":"Bay > Arab (बंगाल की खाड़ी में ज्यादा)","impact_emoji":"🌀"}', '{"front":"Major Cyclones in India","points":["Odisha: 1999 Super Cyclone, ''Fani'' (2019).","Arabian Sea: Recent increase in frequency (e.g., ''Biparjoy'', ''Tauktae'').","Naming: 13 countries of Indian Ocean region name them rotationally."],"pyq":[{"year":2021,"question":"Which country named the cyclone ''Tauktae''?","strategy":"Country-Name (Myanmar - Meaning: Gecko)."}],"mnemonic":"Bay > Arab (More in Bay of Bengal)","impact_emoji":"🌀"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('fbe47df3-d7b2-4e6e-9a6c-02b05d2b8161', 'unit_3', 'जनसंख्या वृद्धि, वितरण एवं घनत्व', 'Population Growth, Distribution and Density', '{"back":"भारत के लोग कहाँ और कितने बसे हैं, और हमारी आबादी कैसे बढ़ रही है।"}', '{"back":"The study of where Indians live and how fast our population is growing across different states."}', 21, 0, NULL, 1769948928, '{"front":"जनसंख्या वृद्धि, वितरण एवं घनत्व","points":["जनगणना 2011: जनसंख्या 121 करोड़, दशकीय वृद्धि 17.7%।","घनत्व: बिहार (1106) सर्वाधिक, अरुणाचल (17) न्यूनतम, भारत का औसत 382।","महान विभाजक वर्ष: 1921 (जनसंख्या में कमी आई थी)।"],"pyq":[{"year":2022,"question":"2011 की जनगणना के अनुसार भारत का जनसंख्या घनत्व कितना है?","strategy":"आंकड़े (382 व्यक्ति/वर्ग किमी)।"}],"mnemonic":"BAD (Bihar-Arunachal-Density)","impact_emoji":"👨‍👩‍👧‍👦"}', '{"front":"Population Growth, Dist. & Density","points":["Census 2011: Pop 121 Cr, Decadal Growth 17.7%.","Density: Bihar (1106) Highest, Arunachal (17) Lowest, India Avg 382.","Great Divide Year: 1921 (Population decreased)."],"pyq":[{"year":2022,"question":"What is the population density of India as per 2011 Census?","strategy":"Data (382 persons/sq km)."}],"mnemonic":"BAD (Bihar-Arunachal-Density)","impact_emoji":"👨‍👩‍👧‍👦"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('ed585bd9-393b-4f40-891e-2e9d2780477d', 'unit_3', 'ग्रामीण-नगरीय प्रवास (Migration)', 'Rural-Urban Migration', '{"back":"गाँव से शहर की ओर पलायन और उससे जुड़े सामाजिक-आर्थिक बदलाव।"}', '{"back":"The movement of people from villages to cities in search of better jobs and lifestyle."}', 22, 0, NULL, 1769948928, '{"front":"ग्रामीण-नगरीय प्रवास (Migration)","points":["मुख्य कारण: रोजगार (पुरुषों के लिए), विवाह (महिलाओं के लिए)।","रुझान: ग्रामीण से नगरीय (Rural to Urban) प्रवास बढ़ रहा है।","परिणाम: शहरों में स्लम बस्तियां, ''पुश'' (धकेलने वाले) और ''पुल'' (खींचने वाले) कारक।"],"pyq":[{"year":2019,"question":"भारत में महिलाओं के प्रवास का मुख्य कारण क्या है?","strategy":"सामाजिक कारण (विवाह/Marriage)।"}],"mnemonic":"Job-Men, Marriage-Women","impact_emoji":"🏙️"}', '{"front":"Rural-Urban Migration","points":["Main Cause: Employment (For Men), Marriage (For Women).","Trend: Increasing Rural to Urban migration.","Consequence: Urban slums, Push factors (Distress) vs Pull factors (Opportunity)."],"pyq":[{"year":2019,"question":"What is the main reason for migration of women in India?","strategy":"Social Reason (Marriage)."}],"mnemonic":"Job-Men, Marriage-Women","impact_emoji":"🏙️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('99e699b2-b3bf-4232-b06d-ce116f9cc61c', 'unit_4', 'वन एवं वनोपज', 'Forest and Forest Produce', '{"back":"MP के घने जंगल और उनसे मिलने वाली बेशकीमती चीज़ें जैसे महुआ, सागौन और तेंदूपत्ता।"}', '{"back":"MP is the ''Forest State''—home to dense woods providing teak, tendu leaves, and medicinal herbs."}', 1, 0, NULL, 1769948928, '{"front":"वन एवं वनोपज","points":["वन स्थिति रिपोर्ट 2021: म.प्र. में देश का सर्वाधिक वन क्षेत्र (77,493 वर्ग किमी)।","सागौन (Teak): म.प्र. के वनों में सर्वाधिक पाया जाने वाला वृक्ष (लगभग 19%)।","वनोपज: तेंदूपत्ता उत्पादन में म.प्र. देश में प्रथम (बीड़ी उद्योग)।"],"pyq":[{"year":2020,"question":"मध्यप्रदेश के किस जिले में सर्वाधिक वन आवरण है?","strategy":"तथ्य (बालाघाट)।"}],"mnemonic":"BT (Balaghat-Teak)","impact_emoji":"🌳"}', '{"front":"Forest and Forest Produce","points":["ISFR 2021: MP has the largest forest cover in India (77,493 sq km).","Teak (Sagoun): Most abundant tree species in MP forests (~19%).","Produce: MP ranks 1st in Tendu Patta production (Beedi Industry)."],"pyq":[{"year":2020,"question":"Which district of MP has the maximum forest cover?","strategy":"Fact (Balaghat)."}],"mnemonic":"BT (Balaghat-Teak)","impact_emoji":"🌳"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('03594540-744e-42ff-b13d-1c1364c18ac9', 'unit_4', 'नदियाँ', 'Rivers of MP', '{"back":"नर्मदा, चंबल और सोन जैसी नदियाँ जो मध्यप्रदेश की प्यास बुझाती हैं।"}', '{"back":"The ''Narmada'' (lifeline of MP) and rivers like Chambal and Betwa that define our landscape."}', 2, 0, NULL, 1769948928, '{"front":"मध्यप्रदेश की नदियाँ","points":["नर्मदा: ''म.प्र. की जीवन रेखा'', अनूपपुर (अमरकंटक) से उद्गम, 1312 किमी कुल लंबाई।","चंबल: बीहड़ (Ravines) निर्माण के लिए प्रसिद्ध, जानापाव (महू) से उद्गम।","बेतवा: प्रदूषण के कारण ''म.प्र. की गंगा'', रायसेन (कुम्भराज) से उद्गम।"],"pyq":[{"year":2021,"question":"चंबल नदी का उद्गम स्थल किस पहाड़ी से है?","strategy":"स्थान (जानापाव पहाड़ी)।"}],"mnemonic":"Narmada-Amar, Chambal-Janapav","impact_emoji":"🌊"}', '{"front":"Rivers of MP","points":["Narmada: ''Lifeline of MP'', Originates from Anuppur (Amarkantak), Total length 1312 km.","Chambal: Famous for Ravines formation, Originates from Janapav (Mhow).","Betwa: ''Ganga of MP'' due to pollution, Originates from Raisen (Kumhra Gaon)."],"pyq":[{"year":2021,"question":"What is the origin place of Chambal river?","strategy":"Location (Janapav Hill)."}],"mnemonic":"Narmada-Amar, Chambal-Janapav","impact_emoji":"🌊"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('62bf67e9-3f41-4d64-aa71-ed3cd028db3a', 'unit_4', 'पहाड़ियाँ और पठार', 'Hills and Plateaus of MP', '{"back":"सतपुड़ा और विंध्याचल की ऊँचाइयाँ और मालवा का उपजाऊ पठार।"}', '{"back":"From the Satpura and Vindhyachal ranges to the fertile Malwa plateau."}', 3, 0, NULL, 1769948928, '{"front":"पहाड़ियाँ और पठार","points":["मालवा का पठार: म.प्र. का सबसे बड़ा प्राकृतिक विभाग (28%), काली मिट्टी की अधिकता।","सतपुड़ा श्रेणी: धूपगढ़ (1350 मी) म.प्र. की सबसे ऊँची चोटी (पचमढ़ी)।","विंध्याचल श्रेणी: उत्तर और दक्षिण भारत का विभाजक, सद्भावना शिखर (Goodwill Peak)।"],"pyq":[{"year":2019,"question":"मध्यप्रदेश की सर्वोच्च चोटी धूपगढ़ किस श्रेणी में स्थित है?","strategy":"पर्वत श्रेणी (सतपुड़ा/महादेव)।"}],"mnemonic":"Malwa-Largest, Dhupgarh-Highest","impact_emoji":"⛰️"}', '{"front":"Hills and Plateaus of MP","points":["Malwa Plateau: Largest physical division of MP (28%), Abundance of Black Soil.","Satpura Range: Dhupgarh (1350m) is the highest peak of MP (Pachmarhi).","Vindhyachal Range: Divider of North and South India, Sadbhavana Shikhar."],"pyq":[{"year":2019,"question":"The highest peak Dhupgarh is located in which range?","strategy":"Mountain Range (Satpura/Mahadeo)."}],"mnemonic":"Malwa-Largest, Dhupgarh-Highest","impact_emoji":"⛰️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('8321d02d-74ef-4663-a92d-ecf5652cbe04', 'unit_4', 'जलवायु: ऋतुएँ, तापमान, वर्षा', 'Climate: Seasons, Temperature, Rainfall', '{"back":"MP में गर्मी, सर्दी और बारिश का चक्र और यहाँ के मौसम की खास बातें।"}', '{"back":"The weather cycle in MP—hot summers, cool winters, and the life-giving monsoon."}', 4, 0, NULL, 1769948928, '{"front":"जलवायु: ऋतुएँ, तापमान, वर्षा","points":["जलवायु प्रकार: उष्णकटिबंधीय मानसूनी जलवायु (Tropical Monsoon)।","स्थानीय नाम: ग्रीष्म (यूनाला), वर्षा (चौमासा), शीत (सियाला)।","तापमान: गंजबासौदा (विदिशा) ऐतिहासिक रूप से सबसे गर्म स्थान रहा है।"],"pyq":[{"year":2022,"question":"मध्यप्रदेश की जलवायु कैसी है?","strategy":"प्रकार (मानसूनी)।"}],"mnemonic":"Unala-Hot, Siyala-Cold","impact_emoji":"🌦️"}', '{"front":"Climate: Seasons, Temp, Rainfall","points":["Climate Type: Tropical Monsoon Climate.","Local Names: Summer (Unala), Rainy (Chaumasa), Winter (Siyala).","Temperature: Ganjbasoda (Vidisha) has historically been the hottest place."],"pyq":[{"year":2022,"question":"What is the type of climate in Madhya Pradesh?","strategy":"Type (Monsoon)."}],"mnemonic":"Unala-Hot, Siyala-Cold","impact_emoji":"🌦️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('f4e5383d-5abe-4a6d-8a3a-f58286718e56', 'unit_4', 'प्राकृतिक संसाधन—मिट्टियाँ', 'Soils of Madhya Pradesh', '{"back":"काली मिट्टी से लेकर लाल-पीली मिट्टी तक, जो यहाँ की फसलों की जान है।"}', '{"back":"The diverse earth of MP, including rich black soil for cotton and red-yellow soil for rice."}', 5, 0, NULL, 1769948928, '{"front":"प्राकृतिक संसाधन—मिट्टियाँ","points":["काली मिट्टी: सर्वाधिक क्षेत्र (47%), मालवा पठार, कपास और सोयाबीन के लिए उपयुक्त।","जलोढ़ मिट्टी: चंबल क्षेत्र (भिंड, मुरैना), सर्वाधिक उपजाऊ, मृदा अपरदन की समस्या।","लाल-पीली मिट्टी: बघेलखंड क्षेत्र (पूर्वी म.प्र.), चावल (धान) के लिए उपयुक्त।"],"pyq":[{"year":2020,"question":"मालवा के पठार में कौन सी मिट्टी पाई जाती है?","strategy":"क्षेत्र-मिट्टी (काली मिट्टी)।"}],"mnemonic":"Black-Malwa, Alluvial-Chambal","impact_emoji":"🌱"}', '{"front":"Soils of Madhya Pradesh","points":["Black Soil: Largest area (47%), Malwa Plateau, Best for Cotton & Soybean.","Alluvial Soil: Chambal region (Bhind, Morena), Most fertile, Soil erosion issue.","Red-Yellow Soil: Baghelkhand region (Eastern MP), Suitable for Rice (Paddy)."],"pyq":[{"year":2020,"question":"Which soil is found in the Malwa Plateau?","strategy":"Region-Soil (Black Soil)."}],"mnemonic":"Black-Malwa, Alluvial-Chambal","impact_emoji":"🌱"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('00bd272f-3e49-4b92-a9fe-a53bed7041ac', 'unit_4', 'प्रमुख खनिज संसाधन', 'Major Mineral Resources', '{"back":"MP की ज़मीन में छुपा हीरा, तांबा और कोयला जो राज्य को अमीर बनाता है।"}', '{"back":"The state''s wealth of Diamond (Panna), Copper, and Manganese."}', 6, 0, NULL, 1769948928, '{"front":"प्रमुख खनिज संसाधन","points":["हीरा: म.प्र. एकमात्र उत्पादक राज्य, पन्ना (मझगवां खान)।","तांबा: बालाघाट (मलाजखंड - ''तांबा नगरी'')।","मैंगनीज: बालाघाट (भरवेली - एशिया की सबसे बड़ी खुले मुँह की खदान)।"],"pyq":[{"year":2021,"question":"मलाजखंड किस खनिज के लिए प्रसिद्ध है?","strategy":"स्थान-खनिज (तांबा)।"}],"mnemonic":"Diamond-Panna, Copper-Balaghat","impact_emoji":"💎"}', '{"front":"Major Mineral Resources","points":["Diamond: MP is the only producing state, Panna (Majhgawan mine).","Copper: Balaghat (Malanjkhand - ''Copper City'').","Manganese: Balaghat (Bharveli - Asia''s largest open cast mine)."],"pyq":[{"year":2021,"question":"Malanjkhand is famous for which mineral?","strategy":"Location-Mineral (Copper)."}],"mnemonic":"Diamond-Panna, Copper-Balaghat","impact_emoji":"💎"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('dd564a78-d0bc-4130-86f5-3e4e7c086cb3', 'unit_4', 'प्रमुख फसलें', 'Major Crops', '{"back":"सोयाबीन, गेहूँ और चना—जिनकी पैदावार में MP देश में नाम कमाता है।"}', '{"back":"MP is the ''Soyabean State'' and also a leading producer of Wheat and Gram."}', 7, 0, NULL, 1769948928, '{"front":"प्रमुख फसलें","points":["सोयाबीन: म.प्र. ''सोया स्टेट'' (उज्जैन/धार प्रमुख उत्पादक)।","गेहूँ: सर्वाधिक सिंचित फसल, सीहोर का ''शरबती गेहूँ'' प्रसिद्ध (GI टैग प्रयास)।","अफीम: मंदसौर और नीमच जिले प्रमुख उत्पादक।"],"pyq":[{"year":2019,"question":"मध्यप्रदेश का कौन सा जिला अफीम उत्पादन के लिए जाना जाता है?","strategy":"जिला (मंदसौर)।"}],"mnemonic":"Soya-Ujjain, Opium-Mandsaur","impact_emoji":"🌽"}', '{"front":"Major Crops","points":["Soybean: MP is ''Soya State'' (Ujjain/Dhar major producers).","Wheat: Most irrigated crop, Sehore''s ''Sharbati Wheat'' is famous.","Opium: Mandsaur and Neemuch are major producing districts."],"pyq":[{"year":2019,"question":"Which district of MP is known for Opium production?","strategy":"District (Mandsaur)."}],"mnemonic":"Soya-Ujjain, Opium-Mandsaur","impact_emoji":"🌽"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('fe22ccc1-e34d-440c-be28-7fe042a88801', 'unit_4', 'जल संसाधन, सिंचाई और परियोजनाएं', 'Irrigation and Irrigation Projects', '{"back":"नहरों का जाल और बड़े बांध जो खेतों तक पानी पहुँचाते हैं।"}', '{"back":"Dams and canals that turn our dry lands into productive farms."}', 8, 0, NULL, 1769948928, '{"front":"जल संसाधन, सिंचाई और परियोजनाएं","points":["इंदिरा सागर: खंडवा (पुनासा), नर्मदा नदी पर, सर्वाधिक जल भराव क्षमता।","गांधी सागर: मंदसौर, चंबल नदी पर (म.प्र. की पहली जलविद्युत परियोजना)।","बाणसागर: शहडोल (देवलोद), सोन नदी पर (म.प्र., यू.पी., बिहार की संयुक्त)।"],"pyq":[{"year":2022,"question":"बाणसागर परियोजना किस नदी पर स्थित है?","strategy":"परियोजना-नदी (सोन)।"}],"mnemonic":"Indira-Narmada, Gandhi-Chambal","impact_emoji":"💧"}', '{"front":"Irrigation and Projects","points":["Indira Sagar: Khandwa (Punasa), on Narmada, Highest water storage capacity.","Gandhi Sagar: Mandsaur, on Chambal (First Hydel project of MP).","Bansagar: Shahdol (Deolond), on Son river (Joint venture of MP, UP, Bihar)."],"pyq":[{"year":2022,"question":"Bansagar project is located on which river?","strategy":"Project-River (Son)."}],"mnemonic":"Indira-Narmada, Gandhi-Chambal","impact_emoji":"💧"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('e65d79dd-fe6a-4376-b688-2f2f64eb72e1', 'unit_4', 'ऊर्जा के पारंपरिक और गैर-पारंपरिक स्रोत', 'Conventional and Non-Conventional Sources of Energy', '{"back":"कोयले से बनने वाली बिजली और अब बढ़ता हुआ सोलर प्लांट का नेटवर्क।"}', '{"back":"Thermal power plants and MP''s massive shift towards giant Solar Parks like Rewa."}', 9, 0, NULL, 1769948928, '{"front":"ऊर्जा के पारंपरिक और गैर-पारंपरिक स्रोत","points":["थर्मल पावर: विंध्याचल (सिंगरौली) - सबसे बड़ा ताप विद्युत गृह।","सौर ऊर्जा: रीवा अल्ट्रा मेगा सोलर प्लांट (750 मेगावाट)।","फ्लोटिंग सोलर: ओंकारेश्वर (खंडवा) में प्रस्तावित (600 मेगावाट)।"],"pyq":[{"year":2021,"question":"रीवा सोलर प्लांट की क्षमता कितनी है?","strategy":"तथ्य (750 MW)।"}],"mnemonic":"Singrauli-Energy Capital","impact_emoji":"⚡"}', '{"front":"Conv. & Non-Conv. Energy Sources","points":["Thermal Power: Vindhyachal (Singrauli) - Largest Thermal Power Station.","Solar Energy: Rewa Ultra Mega Solar Plant (750 MW).","Floating Solar: Proposed at Omkareshwar (Khandwa) (600 MW)."],"pyq":[{"year":2021,"question":"What is the capacity of Rewa Solar Plant?","strategy":"Fact (750 MW)."}],"mnemonic":"Singrauli-Energy Capital","impact_emoji":"⚡"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('540ed4f2-8bc2-43cd-8600-b6f9317e372d', 'unit_4', 'मध्यप्रदेश के प्रमुख उद्योग', 'Major Industries of MP', '{"back":"कपड़ा, लोहा और सीमेंट जैसे कारखाने जो राज्य की इकॉनमी की रीढ़ हैं।"}', '{"back":"From textiles and cement to modern industrial hubs like Pithampur and Mandideep."}', 10, 0, NULL, 1769948928, '{"front":"मध्यप्रदेश के प्रमुख उद्योग","points":["भेल (BHEL): भोपाल (1964), ब्रिटेन के सहयोग से स्थापित, भारी विद्युत उपकरण।","नेपानगर: बुरहानपुर, अखबारी कागज का कारखाना।","पीथमपुर (धार): ''भारत का डेट्रायट'' (ऑटोमोबाइल उद्योग केंद्र)।"],"pyq":[{"year":2020,"question":"मध्यप्रदेश में ''करेंसी प्रिंटिंग प्रेस'' कहाँ स्थित है?","strategy":"स्थान (देवास)।"}],"mnemonic":"BHEL-Bhopal, Nepa-News","impact_emoji":"🏭"}', '{"front":"Major Industries of MP","points":["BHEL: Bhopal (1964), est. with British aid, Heavy electrical equipment.","Nepanagar: Burhanpur, Newsprint paper mill.","Pithampur (Dhar): ''Detroit of India'' (Automobile Hub)."],"pyq":[{"year":2020,"question":"Where is the ''Currency Printing Press'' located in MP?","strategy":"Location (Dewas)."}],"mnemonic":"BHEL-Bhopal, Nepa-News","impact_emoji":"🏭"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('422161b2-1ac8-4932-ae9d-e6ebc6fc2481', 'unit_4', 'जनसंख्या वृद्धि, वितरण एवं घनत्व', 'Population Growth, Distribution and Density', '{"back":"MP के लोग कहाँ ज़्यादा बसे हैं और आबादी कैसे बढ़ रही है।"}', '{"back":"A look at the demographic spread across MP''s 50+ districts."}', 11, 0, NULL, 1769948928, '{"front":"जनसंख्या वृद्धि, वितरण एवं घनत्व","points":["जनगणना 2011: कुल जनसंख्या 7.26 करोड़, दशकीय वृद्धि 20.35%।","लिंगानुपात: 931 (बालाघाट सर्वाधिक - 1021)।","जनघनत्व: 236 व्यक्ति/वर्ग किमी (भोपाल सर्वाधिक - 855)।"],"pyq":[{"year":2022,"question":"2011 की जनगणना के अनुसार म.प्र. का जनसंख्या घनत्व कितना है?","strategy":"आंकड़े (236)।"}],"mnemonic":"20-30 Growth (20.35%)","impact_emoji":"👥"}', '{"front":"Population Growth, Dist. & Density","points":["Census 2011: Total Pop 7.26 Cr, Decadal Growth 20.35%.","Sex Ratio: 931 (Balaghat highest - 1021).","Density: 236 persons/sq km (Bhopal highest - 855)."],"pyq":[{"year":2022,"question":"What is the population density of MP as per 2011 Census?","strategy":"Data (236)."}],"mnemonic":"20-30 Growth (20.35%)","impact_emoji":"👥"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('29422c95-58a6-454c-a9cf-de9972b148fc', 'unit_4', 'नगरीकरण (Urbanization)', 'Urbanisation in MP', '{"back":"तेज़ी से बढ़ते शहर और गाँवों का शहरों में तब्दील होना।"}', '{"back":"The growth of smart cities like Indore, Bhopal, and Gwalior."}', 12, 0, NULL, 1769948929, '{"front":"नगरीकरण (Urbanization)","points":["प्रतिशत: 27.6% जनसंख्या शहरी है (इंदौर संभाग सर्वाधिक नगरीकृत)।","सर्वाधिक नगरीकृत जिला: भोपाल (80.9%)।","न्यूनतम नगरीकृत जिला: डिंडोरी (4.6%)।"],"pyq":[{"year":2021,"question":"मध्यप्रदेश का सर्वाधिक नगरीकृत जिला कौन सा है?","strategy":"जिला (भोपाल)।"}],"mnemonic":"Bhopal-City, Dindori-Village","impact_emoji":"🏙️"}', '{"front":"Urbanisation in MP","points":["Percentage: 27.6% population is urban (Indore division most urbanized).","Most Urbanized District: Bhopal (80.9%).","Least Urbanized District: Dindori (4.6%)."],"pyq":[{"year":2021,"question":"Which is the most urbanized district of MP?","strategy":"District (Bhopal)."}],"mnemonic":"Bhopal-City, Dindori-Village","impact_emoji":"🏙️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('23082d7d-5174-41f2-913f-e44d235d48a8', 'unit_5', 'संविधान सभा', 'Constituent Assembly', '{"back":"वो महान सभा जिसने आज़ाद भारत के लिए दुनिया का सबसे बड़ा लिखित संविधान बनाया।"}', '{"back":"The assembly of great minds that debated and drafted the world''s longest written constitution."}', 1, 0, NULL, 1769948929, '{"front":"संविधान सभा","points":["गठन: कैबिनेट मिशन योजना (1946) के तहत।","बैठकें: 9 दिसंबर (अस्थायी अध्यक्ष: सच्चिदानंद सिन्हा), 11 दिसंबर (स्थायी: राजेंद्र प्रसाद), 13 दिसंबर (उद्देश्य प्रस्ताव: नेहरू)।","प्रारूप समिति: अध्यक्ष बी.आर. अंबेडकर, गठन 29 अगस्त 1947 (कुल 7 सदस्य)।"],"pyq":[{"year":2020,"question":"संविधान सभा की ''संचालन समिति'' के अध्यक्ष कौन थे?","strategy":"व्यक्ति (डॉ. राजेंद्र प्रसाद)।"}],"mnemonic":"9-11-13 (दिसंबर 1946 की प्रमुख तिथियाँ)","impact_emoji":"📜"}', '{"front":"Constituent Assembly","points":["Formation: Under Cabinet Mission Plan (1946).","Meetings: Dec 9 (Temp Prez: Sachchidanand Sinha), Dec 11 (Perm Prez: Rajendra Prasad), Dec 13 (Objective Resolution: Nehru).","Drafting Committee: Chairman B.R. Ambedkar, Formed 29 Aug 1947 (7 Members)."],"pyq":[{"year":2020,"question":"Who was the chairman of the ''Steering Committee'' of the Constituent Assembly?","strategy":"Person (Dr. Rajendra Prasad)."}],"mnemonic":"9-11-13 (Key dates of Dec 1946)","impact_emoji":"📜"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('dd623a8f-1b8c-4edd-b23d-75343b447848', 'unit_5', 'संघीय कार्यपालिका, राष्ट्रपति एवं संसद', 'Federal Executive, President and Parliament', '{"back":"देश कैसे चलता है—राष्ट्रपति की शक्ति और संसद में कानून बनने की प्रक्रिया।"}', '{"back":"How India is governed—the powers of the President and how laws are made in the Lok Sabha & Rajya Sabha."}', 2, 0, NULL, 1769948929, '{"front":"संघीय कार्यपालिका, राष्ट्रपति एवं संसद","points":["राष्ट्रपति: अनुच्छेद 52 (पद), अनुच्छेद 61 (महाभियोग), अनुच्छेद 123 (अध्यादेश)।","संसद (Art 79): राष्ट्रपति + राज्यसभा (Art 80) + लोकसभा (Art 81)।","संयुक्त अधिवेशन (Art 108): राष्ट्रपति बुलाता है, लोकसभा अध्यक्ष अध्यक्षता करता है।"],"pyq":[{"year":2021,"question":"संसद के दोनों सदनों की संयुक्त बैठक कौन आहूत करता है?","strategy":"प्राधिकारी (राष्ट्रपति)।"}],"mnemonic":"SARLA (Sansad-79, Rajya-80, Lok-81)","impact_emoji":"🏛️"}', '{"front":"Federal Executive, President & Parliament","points":["President: Art 52 (Post), Art 61 (Impeachment), Art 123 (Ordinance).","Parliament (Art 79): President + Rajya Sabha (Art 80) + Lok Sabha (Art 81).","Joint Sitting (Art 108): Called by President, Presided by LS Speaker."],"pyq":[{"year":2021,"question":"Who summons the joint sitting of both houses of Parliament?","strategy":"Authority (President)."}],"mnemonic":"SARLA (Sansad-79, Rajya-80, Lok-81)","impact_emoji":"🏛️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('93dac088-5f12-4237-9e51-03a61a14d785', 'unit_5', 'सर्वोच्च न्यायालय एवं न्यायिक व्यवस्था', 'Supreme Court and Judicial System', '{"back":"इंसाफ का सबसे बड़ा मंदिर और कानून की रक्षा करने वाला सिस्टम।"}', '{"back":"The guardian of the Constitution and the ultimate temple of justice for every citizen."}', 3, 0, NULL, 1769948929, '{"front":"सर्वोच्च न्यायालय एवं न्यायिक व्यवस्था","points":["सर्वोच्च न्यायालय: भाग V, अनुच्छेद 124 से 147।","नियुक्ति: कॉलेजियम प्रणाली (NJAC 99वें संशोधन द्वारा रद्द)।","जनहित याचिका (PIL): जनक पी.एन. भगवती, अवधारणा अमेरिका से ली गई।"],"pyq":[{"year":2019,"question":"सर्वोच्च न्यायालय के न्यायाधीशों की सेवानिवृत्ति आयु क्या है?","strategy":"आयु (65 वर्ष)।"}],"mnemonic":"1-2-4 (Article 124 for SC)","impact_emoji":"⚖️"}', '{"front":"Supreme Court & Judicial System","points":["Supreme Court: Part V, Articles 124 to 147.","Appointment: Collegium System (NJAC struck down by 99th Amd).","PIL: Father P.N. Bhagwati, Concept borrowed from USA."],"pyq":[{"year":2019,"question":"What is the retirement age of Supreme Court judges?","strategy":"Age (65 Years)."}],"mnemonic":"1-2-4 (Article 124 for SC)","impact_emoji":"⚖️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('ceee1217-b6da-4f7c-933e-fd1e01d6eab2', 'unit_5', 'संवैधानिक संशोधन', 'Constitutional Amendments', '{"back":"समय के साथ संविधान को बेहतर बनाने के लिए किए गए बदलाव।"}', '{"back":"The process of updating the Constitution to keep it relevant for modern times."}', 4, 0, NULL, 1769948929, '{"front":"संवैधानिक संशोधन","points":["प्रक्रिया: अनुच्छेद 368 (भाग XX), दक्षिण अफ्रीका से लिया गया।","42वां संशोधन (1976): ''लघु संविधान'', प्रस्तावना में 3 शब्द जोड़े गए।","101वां संशोधन: GST (माल एवं सेवा कर)।"],"pyq":[{"year":2022,"question":"किस संविधान संशोधन द्वारा मतदान की आयु 21 से घटाकर 18 वर्ष की गई?","strategy":"संशोधन (61वां, 1989)।"}],"mnemonic":"4+2=6 (1976 - Mini Const), 4+4=8 (1978 - Property removed)","impact_emoji":"🖊️"}', '{"front":"Constitutional Amendments","points":["Process: Article 368 (Part XX), Borrowed from South Africa.","42nd Amd (1976): ''Mini Constitution'', Added 3 words to Preamble.","101st Amd: GST (Goods and Services Tax)."],"pyq":[{"year":2022,"question":"Which amendment reduced voting age from 21 to 18 years?","strategy":"Amendment (61st, 1989)."}],"mnemonic":"4+2=6 (1976), 4+4=8 (1978)","impact_emoji":"🖊️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('f57ec0c2-6938-4c2f-96ef-1e1445cd8091', 'unit_5', 'नागरिकों के मौलिक अधिकार एवं कर्तव्य', 'Fundamental Rights and Duties', '{"back":"संविधान से मिले हमारे हक़ और देश के प्रति हमारी ज़िम्मेदारियाँ।"}', '{"back":"The basic freedoms every Indian enjoys and the responsibilities we owe to the nation."}', 5, 0, NULL, 1769948929, '{"front":"मौलिक अधिकार एवं कर्तव्य","points":["मौलिक अधिकार: भाग III (अनुच्छेद 12-35), ''मैग्ना कार्टा'', अमेरिका से प्रेरित।","मौलिक कर्तव्य: भाग IV-A (अनुच्छेद 51A), स्वर्ण सिंह समिति, रूस (USSR) से प्रेरित।","हटाया गया अधिकार: संपत्ति का अधिकार (44वें संशोधन द्वारा 300A में विधिक अधिकार बना)।"],"pyq":[{"year":2020,"question":"अस्पृश्यता का अंत किस अनुच्छेद में वर्णित है?","strategy":"अनुच्छेद (Art 17)।"}],"mnemonic":"Rights-USA, Duties-Russia","impact_emoji":"✊"}', '{"front":"Fundamental Rights and Duties","points":["Fundamental Rights: Part III (Art 12-35), ''Magna Carta'', from USA.","Fundamental Duties: Part IV-A (Art 51A), Swaran Singh Comm, from Russia (USSR).","Removed Right: Right to Property (Made legal right in 300A by 44th Amd)."],"pyq":[{"year":2020,"question":"Abolition of Untouchability is mentioned in which Article?","strategy":"Article (Art 17)."}],"mnemonic":"Rights-USA, Duties-Russia","impact_emoji":"✊"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('ef4a4910-7b2a-48d0-9d81-205f5ed0dd12', 'unit_5', 'राज्य के नीति-निदेशक सिद्धांत', 'Directive Principles of State Policy', '{"back":"सरकार के लिए वो दिशा-निर्देश जो एक अच्छे समाज को बनाने में मदद करते हैं।"}', '{"back":"Guidelines for the government to create a fair, equal, and welfare-oriented society."}', 6, 0, NULL, 1769948929, '{"front":"राज्य के नीति-निदेशक सिद्धांत (DPSP)","points":["स्रोत: भाग IV (अनुच्छेद 36-51), आयरलैंड के संविधान से।","उद्देश्य: कल्याणकारी राज्य (Welfare State) की स्थापना।","अनुच्छेद 44: समान नागरिक संहिता (UCC)।"],"pyq":[{"year":2021,"question":"नीति निर्देशक तत्वों में ''ग्राम पंचायतों का गठन'' किस अनुच्छेद में है?","strategy":"अनुच्छेद (Art 40)।"}],"mnemonic":"Ireland > Welfare State","impact_emoji":"🧭"}', '{"front":"Directive Principles of State Policy","points":["Source: Part IV (Art 36-51), from Irish Constitution.","Aim: Establishment of a Welfare State.","Article 44: Uniform Civil Code (UCC)."],"pyq":[{"year":2021,"question":"Organization of Village Panchayats is in which Article of DPSP?","strategy":"Article (Art 40)."}],"mnemonic":"Ireland > Welfare State","impact_emoji":"🧭"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('752d2705-1a32-404f-ba23-81b4f247d070', 'unit_5', 'राष्ट्रीय एवं प्रादेशिक संवैधानिक/सांविधिक आयोग', 'National and Regional Constitutional/Statutory Commissions', '{"back":"चुनाव आयोग और UPSC जैसी संस्थाएं जो देश के लोकतंत्र को मज़बूत रखती हैं।"}', '{"back":"Powerful bodies like the Election Commission and UPSC that protect our democracy."}', 7, 0, NULL, 1769948929, '{"front":"संवैधानिक/सांविधिक आयोग","points":["निर्वाचन आयोग (ECI): अनुच्छेद 324, 3 सदस्यीय निकाय।","CAG (कैग): अनुच्छेद 148, ''सार्वजनिक धन का प्रहरी''।","नीति आयोग: 1 जनवरी 2015, गैर-संवैधानिक (कार्यकारी निकाय), अध्यक्ष - PM।"],"pyq":[{"year":2022,"question":"भारत के नियंत्रक एवं महालेखा परीक्षक (CAG) का कार्यकाल कितना होता है?","strategy":"तथ्य (6 वर्ष या 65 वर्ष आयु)।"}],"mnemonic":"CAG-148, UPSC-315, ECI-324","impact_emoji":"🏢"}', '{"front":"Const./Statutory Commissions","points":["Election Commission (ECI): Art 324, 3-member body.","CAG: Art 148, ''Guardian of Public Purse''.","NITI Aayog: 1 Jan 2015, Non-Constitutional (Executive body), Chair - PM."],"pyq":[{"year":2022,"question":"What is the tenure of the Comptroller and Auditor General (CAG)?","strategy":"Fact (6 years or 65 age)."}],"mnemonic":"CAG-148, UPSC-315, ECI-324","impact_emoji":"🏢"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('06f9545b-bd59-42ed-9559-62ba247ecd7e', 'unit_5', 'मध्यप्रदेश की संवैधानिक व्यवस्था', 'Constitutional System of Madhya Pradesh', '{"back":"राज्यपाल, मुख्यमंत्री और विधानसभा—राज्य सरकार के कामकाज का तरीका।"}', '{"back":"State governance—the role of the Governor, Chief Minister, and the State Legislature."}', 8, 0, NULL, 1769948929, '{"front":"मध्यप्रदेश की संवैधानिक व्यवस्था","points":["राज्यपाल: अनुच्छेद 153, म.प्र. के प्रथम - पट्टाभि सीतारमैया।","विधानसभा: इंदिरा गांधी विधान भवन (1996), वास्तुकार - चार्ल्स कोरिया।","उच्च न्यायालय: जबलपुर (खंडपीठ: इंदौर और ग्वालियर), अनुच्छेद 214।"],"pyq":[{"year":2019,"question":"मध्यप्रदेश के प्रथम मुख्यमंत्री कौन थे?","strategy":"व्यक्ति (पं. रविशंकर शुक्ल)।"}],"mnemonic":"Gov-Sitaramayya, CM-Shukla","impact_emoji":"🏫"}', '{"front":"Const. System of Madhya Pradesh","points":["Governor: Art 153, First of MP - Pattabhi Sitaramayya.","Legislative Assembly: Indira Gandhi Vidhan Bhavan (1996), Arch - Charles Correa.","High Court: Jabalpur (Benches: Indore & Gwalior), Article 214."],"pyq":[{"year":2019,"question":"Who was the first Chief Minister of Madhya Pradesh?","strategy":"Person (Pt. Ravishankar Shukla)."}],"mnemonic":"Gov-Sitaramayya, CM-Shukla","impact_emoji":"🏫"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('cd3863c3-ff5c-464e-88a4-6c17ac84d1ea', 'unit_5', 'मध्यप्रदेश में त्रिस्तरीय पंचायतीराज', 'Three-Tier Panchayati Raj', '{"back":"गाँव की सरकार—सरपंच और पंचायत की ताकत और उनकी भूमिका।"}', '{"back":"Grassroots democracy—village, block, and district levels giving power to the people."}', 9, 0, NULL, 1769948929, '{"front":"मध्यप्रदेश में त्रिस्तरीय पंचायतीराज","points":["73वां संशोधन (1992): लागू करने वाला म.प्र. देश का पहला राज्य (25 जनवरी 1994)।","संरचना: ग्राम पंचायत, जनपद पंचायत (ब्लॉक), जिला पंचायत।","आरक्षण: महिलाओं के लिए 50% आरक्षण (अनुच्छेद 243D)।"],"pyq":[{"year":2020,"question":"बलवंत राय मेहता समिति का संबंध किससे है?","strategy":"विषय (पंचायती राज - त्रिस्तरीय)।"}],"mnemonic":"73-Village-29 Subjects","impact_emoji":"🗳️"}', '{"front":"Three-Tier Panchayati Raj in MP","points":["73rd Amd (1992): MP was the first state to implement it (25 Jan 1994).","Structure: Gram Panchayat, Janpad Panchayat (Block), Zila Panchayat.","Reservation: 50% reservation for women (Article 243D)."],"pyq":[{"year":2020,"question":"Balwant Rai Mehta committee is related to?","strategy":"Subject (Panchayati Raj - 3 Tier)."}],"mnemonic":"73-Village-29 Subjects","impact_emoji":"🗳️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('11295c4f-7cec-49af-805b-30169636f5b2', 'unit_5', 'नगरीय प्रशासन व्यवस्था', 'Civil Administration System in MP', '{"back":"नगर निगम और नगर पालिकाओं का ढांचा जो शहरों का विकास देखते हैं।"}', '{"back":"The machinery of Municipalities and local bodies that run our towns and cities."}', 10, 0, NULL, 1769948929, '{"front":"नगरीय प्रशासन व्यवस्था","points":["74वां संशोधन (1992): भाग IX-A, 12वीं अनुसूची (18 विषय)।","महापौर (Mayor): म.प्र. में जनता द्वारा प्रत्यक्ष निर्वाचन प्रणाली।","निकाय: नगर निगम, नगर पालिका, नगर परिषद।"],"pyq":[{"year":2021,"question":"संविधान की 12वीं अनुसूची में कितने विषय हैं?","strategy":"संख्या (18)।"}],"mnemonic":"74-City-18 Subjects","impact_emoji":"🏙️"}', '{"front":"Civil Administration System in MP","points":["74th Amd (1992): Part IX-A, 12th Schedule (18 Subjects).","Mayor: Direct election system by public in MP.","Bodies: Municipal Corporation, Municipality, Nagar Parishad."],"pyq":[{"year":2021,"question":"How many subjects are there in the 12th Schedule of the Constitution?","strategy":"Number (18)."}],"mnemonic":"74-City-18 Subjects","impact_emoji":"🏙️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('ba5967ee-80ea-4a9f-b5b4-40b572b0811f', 'unit_5', 'मध्यप्रदेश में सुशासन (Good Governance)', 'Good Governance in Madhya Pradesh', '{"back":"ईमानदार और तेज़ प्रशासन की वो व्यवस्था जिससे जनता को फायदा मिले।"}', '{"back":"The vision of transparent, fast, and digital administration to serve every citizen efficiently."}', 11, 0, NULL, 1769948929, '{"front":"मध्यप्रदेश में सुशासन (Good Governance)","points":["लोक सेवा गारंटी अधिनियम 2010: ऐसा कानून बनाने वाला म.प्र. देश का पहला राज्य।","CM हेल्पलाइन: नंबर ''181'', शिकायतों के निवारण हेतु।","समाधान ऑनलाइन: मुख्यमंत्री द्वारा सीधे अधिकारियों से संवाद।"],"pyq":[{"year":2019,"question":"म.प्र. लोक सेवा गारंटी अधिनियम किस वर्ष पारित हुआ?","strategy":"वर्ष (2010)।"}],"mnemonic":"Guaranteed Service @ 2010","impact_emoji":"🤝"}', '{"front":"Good Governance in MP","points":["Public Service Guarantee Act 2010: MP was 1st state to enact this.","CM Helpline: Number ''181'' for grievance redressal.","Samadhan Online: Direct interaction of CM with officials."],"pyq":[{"year":2019,"question":"In which year was MP Public Service Guarantee Act passed?","strategy":"Year (2010)."}],"mnemonic":"Guaranteed Service @ 2010","impact_emoji":"🤝"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('84e29a99-24a4-4aa7-8f94-5b11a8d2b543', 'unit_6', 'भारतीय अर्थव्यवस्था में मध्यप्रदेश की वर्तमान स्थिति', 'Current Position of MP in Indian Economy', '{"back":"देश की जीडीपी (GDP) और विकास में हमारा MP कहाँ खड़ा है और कितना योगदान दे रहा है।"}', '{"back":"The state''s share in national GDP and its contribution to India''s overall growth story."}', 1, 0, NULL, 1769948929, '{"front":"भारतीय अर्थव्यवस्था में म.प्र. की वर्तमान स्थिति","points":["GSDP योगदान: भारत की जीडीपी में म.प्र. का योगदान लगभग 4.8% (बढ़ता हुआ)।","विकास दर: म.प्र. देश के सबसे तेज बढ़ने वाले राज्यों में से एक (Double Digit Growth)।","अर्थव्यवस्था का स्वरूप: कृषि प्रधान (प्राथमिक क्षेत्र का प्रमुख योगदान)।"],"pyq":[{"year":2022,"question":"म.प्र. की अर्थव्यवस्था कैसी है?","strategy":"प्रकृति (कृषि प्रधान)।"}],"mnemonic":"Agri-Powerhouse (कृषि शक्ति)","impact_emoji":"📈"}', '{"front":"Current Position of MP in Indian Economy","points":["GSDP Contribution: MP contributes approx 4.8% to India''s GDP (Rising trend).","Growth Rate: MP is one of the fastest growing states (Double Digit Growth).","Nature: Agrarian Economy (Dominance of Primary Sector)."],"pyq":[{"year":2022,"question":"What is the nature of MP''s economy?","strategy":"Nature (Agrarian)."}],"mnemonic":"Agri-Powerhouse","impact_emoji":"📈"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('4c123004-abb5-47ee-9245-9e3f18149d3b', 'unit_6', 'मध्यप्रदेश की जनसंख्या व मानवीय संसाधनों का विकास', 'Development of Human Resources in MP', '{"back":"MP के लोगों की ताकत—कैसे शिक्षा, स्वास्थ्य और स्किल (कौशल) से हम राज्य को आगे बढ़ा सकते हैं।"}', '{"back":"Focus on education, health, and skill development to turn MP''s population into a productive workforce."}', 2, 0, NULL, 1769948929, '{"front":"म.प्र. की जनसंख्या व मानवीय संसाधनों का विकास","points":["साक्षरता (2011): 69.3% (पुरुष: 78.7%, महिला: 59.2%)।","कौशल विकास: ''मुख्यमंत्री सीखो कमाओ योजना'' (युवाओं के प्रशिक्षण हेतु)।","HDI: मानव विकास सूचकांक में म.प्र. का स्थान राष्ट्रीय औसत से नीचे रहता है।"],"pyq":[{"year":2020,"question":"2011 की जनगणना के अनुसार म.प्र. की साक्षरता दर कितनी है?","strategy":"आंकड़े (69.3%)।"}],"mnemonic":"Learn & Earn (सीखो-कमाओ)","impact_emoji":"🧑‍🎓"}', '{"front":"Human Resources Development in MP","points":["Literacy (2011): 69.3% (Male: 78.7%, Female: 59.2%).","Skill Dev: ''Mukhyamantri Seekho Kamao Yojana'' (For youth training).","HDI: MP usually ranks below national average in Human Development Index."],"pyq":[{"year":2020,"question":"What is the literacy rate of MP as per 2011 Census?","strategy":"Data (69.3%)."}],"mnemonic":"Learn & Earn","impact_emoji":"🧑‍🎓"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('62e7ff44-627e-4808-8f85-dab28d820246', 'unit_6', 'सतत् विकास लक्ष्यों (SDG) में मध्यप्रदेश की प्रगति', 'Progress of MP in Sustainable Development Goals (SDG)', '{"back":"गरीबी मिटाने और पर्यावरण बचाने जैसे ग्लोबल लक्ष्यों को हासिल करने में MP की प्रोग्रेस।"}', '{"back":"The state''s roadmap and achievements in meeting global targets like ending poverty and protecting the planet."}', 3, 0, NULL, 1769948930, '{"front":"सतत् विकास लक्ष्यों (SDG) में म.प्र. की प्रगति","points":["नीति आयोग इंडेक्स: म.प्र. ''परफॉर्मर'' (Performer) श्रेणी में आता है।","अच्छा प्रदर्शन: ''स्वच्छ जल और स्वच्छता'' (Goal 6) और ''किफायती ऊर्जा'' (Goal 7)।","सुधार की आवश्यकता: ''गरीबी उन्मूलन'' (Goal 1) और ''लैंगिक समानता'' (Goal 5)।"],"pyq":[{"year":2023,"question":"SDG इंडिया इंडेक्स कौन जारी करता है?","strategy":"संस्था (नीति आयोग)।"}],"mnemonic":"Clean Water, Good Energy","impact_emoji":"♻️"}', '{"front":"Progress of MP in SDGs","points":["NITI Aayog Index: MP falls in the ''Performer'' category.","Good Performance: ''Clean Water & Sanitation'' (Goal 6) & ''Affordable Energy'' (Goal 7).","Needs Improvement: ''No Poverty'' (Goal 1) & ''Gender Equality'' (Goal 5)."],"pyq":[{"year":2023,"question":"Who releases the SDG India Index?","strategy":"Body (NITI Aayog)."}],"mnemonic":"Clean Water, Good Energy","impact_emoji":"♻️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('95e06119-236e-4730-bc21-d17c29717109', 'unit_6', 'मध्यप्रदेश में कृषि, उद्योग, एम.एस.एम.ई. एवं अधोसंरचना का विकास', 'Development of Agriculture, Industry, MSME & Infrastructure', '{"back":"खेती, छोटे-बड़े कारखाने और सड़कों-पुलों का जाल, जो राज्य की तरक्की का आधार हैं।"}', '{"back":"The backbone of MP—how farms, small businesses, and roads/power are driving state wealth."}', 4, 0, NULL, 1769948930, '{"front":"कृषि, उद्योग, MSME एवं अधोसंरचना","points":["कृषि: म.प्र. को लगातार 7 बार ''कृषि कर्मण पुरस्कार'' मिला है।","औद्योगिक कॉरिडोर: भोपाल-इंदौर और जबलपुर-सिंगरौली।","MSME: म.प्र. MSME विकास नीति 2021 लागू।"],"pyq":[{"year":2019,"question":"मध्यप्रदेश में ऑप्टिकल फाइबर कारखाना कहाँ स्थित है?","strategy":"उद्योग-स्थान (मंडीदीप)।"}],"mnemonic":"Krishi Karman x 7","impact_emoji":"🏭"}', '{"front":"Agri, Industry, MSME & Infrastructure","points":["Agriculture: MP received ''Krishi Karman Award'' 7 consecutive times.","Industrial Corridor: Bhopal-Indore & Jabalpur-Singrauli.","MSME: MP MSME Development Policy 2021 is in force."],"pyq":[{"year":2019,"question":"Where is the Optical Fiber factory located in MP?","strategy":"Industry-Loc (Mandideep)."}],"mnemonic":"Krishi Karman x 7","impact_emoji":"🏭"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('fb2c3e82-3913-4906-b4cf-0714be18de68', 'unit_6', 'आत्मनिर्भर मध्यप्रदेश', 'Self-Reliant Madhya Pradesh (Atmanirbhar MP)', '{"back":"MP को अपने पैरों पर खड़ा करने का विजन, ताकि हमें बाहर से मदद की ज़रूरत न पड़े।"}', '{"back":"The vision to make the state self-sufficient and a leader in local manufacturing and services."}', 5, 0, NULL, 1769948930, '{"front":"आत्मनिर्भर मध्यप्रदेश","points":["रोडमैप 2023: 4 प्रमुख स्तंभों पर आधारित।","4 स्तंभ: 1. भौतिक अधोसंरचना, 2. सुशासन, 3. स्वास्थ्य एवं शिक्षा, 4. अर्थव्यवस्था एवं रोजगार।","लक्ष्य: स्थानीय उत्पादों को बढ़ावा (''वोकल फॉर लोकल'')।"],"pyq":[{"year":2021,"question":"आत्मनिर्भर मध्यप्रदेश रोडमैप कब जारी किया गया?","strategy":"वर्ष (2020)।"}],"mnemonic":"Infra-Gov-Health-Eco (IGHE)","impact_emoji":"🇮🇳"}', '{"front":"Atmanirbhar Madhya Pradesh","points":["Roadmap 2023: Based on 4 Main Pillars.","4 Pillars: 1. Physical Infra, 2. Good Governance, 3. Health & Edu, 4. Economy & Employment.","Goal: Promoting local products (''Vocal for Local'')."],"pyq":[{"year":2021,"question":"When was Atmanirbhar MP Roadmap released?","strategy":"Year (2020)."}],"mnemonic":"Infra-Gov-Health-Eco (IGHE)","impact_emoji":"🇮🇳"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('0976aeb2-c9fe-4bab-9f24-3eebe640ef1c', 'unit_6', 'एक जिला एक उत्पाद (ODOP)', 'One District One Product (ODOP)', '{"back":"हर जिले की एक खास पहचान (जैसे रतलाम के सेव या चंदेरी की साड़ी) को ग्लोबल ब्रांड बनाना।"}', '{"back":"A strategy to promote a unique local product from each district (like Ratlami Sev) as a global brand."}', 6, 0, NULL, 1769948930, '{"front":"एक जिला एक उत्पाद (ODOP)","points":["बुरहानपुर: केला (Banana)।","इंदौर: आलू (Potato) / शुगर फ्री आलू।","सीहोर: लकड़ी के खिलौने (Wooden Toys)।","मुरैना/भिंड: सरसों (Mustard)।"],"pyq":[{"year":2022,"question":"नूरजहां आम की प्रजाति म.प्र. के किस जिले में पाई जाती है?","strategy":"ODOP/विशेषता (अलीराजपुर)।"}],"mnemonic":"Banana-Burhanpur, Toys-Sehore","impact_emoji":"🍌"}', '{"front":"One District One Product (ODOP)","points":["Burhanpur: Banana.","Indore: Potato / Sugar-free Potato.","Sehore: Wooden Toys.","Morena/Bhind: Mustard."],"pyq":[{"year":2022,"question":"Noorjahan mango variety is found in which district of MP?","strategy":"ODOP/Specialty (Alirajpur)."}],"mnemonic":"Banana-Burhanpur, Toys-Sehore","impact_emoji":"🍌"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('8b0b1163-038d-4506-9423-cc4cba2a4654', 'unit_6', 'मध्यप्रदेश में बौद्धिक संपदा अधिकारों (IPR) की प्रगति', 'Intellectual Property Rights (IPR) in MP', '{"back":"MP के नए अविष्कारों और लोकल प्रोडक्ट्स (GI Tag) के कानूनी हक़ की सुरक्षा।"}', '{"back":"Protecting legal rights for local innovations and traditional products (like GI Tags)."}', 7, 0, NULL, 1769948930, '{"front":"बौद्धिक संपदा अधिकार (IPR) - GI टैग","points":["चंदेरी साड़ी: म.प्र. का पहला GI टैग प्राप्त उत्पाद।","कड़कनाथ मुर्गा: झाबुआ (काले मांस वाला)।","सुंदरजा आम: रीवा (हाल ही में मिला)।","अन्य: रतलामी सेव, बासमती चावल (विवादित/चर्चा में)।"],"pyq":[{"year":2019,"question":"कड़कनाथ मुर्गा किस जिले से संबंधित है?","strategy":"स्थान (झाबुआ)।"}],"mnemonic":"Black Chicken - Jhabua","impact_emoji":"🐓"}', '{"front":"IPR in MP (GI Tags)","points":["Chanderi Saree: First GI Tagged product of MP.","Kadaknath Chicken: Jhabua (Black meat).","Sundaraja Mango: Rewa (Recently awarded).","Others: Ratlami Sev, Basmati Rice (In talks)."],"pyq":[{"year":2019,"question":"Kadaknath chicken belongs to which district?","strategy":"Location (Jhabua)."}],"mnemonic":"Black Chicken - Jhabua","impact_emoji":"🐓"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('dcb3a40b-8ce3-4523-b95b-de25e3ff0b6b', 'unit_6', 'भारतीय अर्थव्यवस्था की नवीन प्रवृत्तियाँ', 'New Trends in Indian Economy', '{"back":"खेती, फैक्ट्रियों और सर्विस सेक्टर (IT, बैंकिंग) में आ रहे नए बदलाव और ट्रेंड्स।"}', '{"back":"Modern shifts in agriculture, manufacturing, and the fast-growing service sector (IT, Finance)."}', 8, 0, NULL, 1769948930, '{"front":"भारतीय अर्थव्यवस्था की नवीन प्रवृत्तियाँ","points":["लक्ष्य: 2025 तक 5 ट्रिलियन डॉलर की अर्थव्यवस्था।","डिजिटल इकोनॉमी: UPI भुगतान में भारत विश्व में अग्रणी।","स्टार्टअप: भारत दुनिया का तीसरा सबसे बड़ा स्टार्टअप इकोसिस्टम।"],"pyq":[{"year":2021,"question":"मेक इन इंडिया कार्यक्रम कब शुरू किया गया?","strategy":"वर्ष (सितंबर 2014)।"}],"mnemonic":"Digital-Startups-5Trillion","impact_emoji":"📱"}', '{"front":"New Trends in Indian Economy","points":["Goal: $5 Trillion Economy by 2025.","Digital Economy: India leads globally in UPI payments.","Startups: India is the 3rd largest startup ecosystem in the world."],"pyq":[{"year":2021,"question":"When was ''Make in India'' program launched?","strategy":"Year (Sept 2014)."}],"mnemonic":"Digital-Startups-5Trillion","impact_emoji":"📱"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('439f2234-4ede-4f56-aed3-36f0a4d3442e', 'unit_6', 'वित्तीय संस्थाएँ: रिजर्व बैंक, वाणिज्यिक बैंक', 'Financial Institutions: RBI & Commercial Banks', '{"back":"बैंकों का सिस्टम—पैसों का लेन-देन संभालने वाले छोटे बैंक और सबका बॉस RBI।"}', '{"back":"The banking ecosystem—how money flows, and the role of RBI as the ''Banker to the Banks''."}', 9, 0, NULL, 1769948930, '{"front":"वित्तीय संस्थाएँ: RBI, बैंक","points":["RBI: स्थापना 1 अप्रैल 1935 (हिल्टन यंग आयोग), राष्ट्रीयकरण 1949।","मौद्रिक नीति: RBI द्वारा साख नियंत्रण (Repo Rate, CRR, SLR)।","SBI: 1955 में गोरेवाला समिति की सिफारिश पर गठन।"],"pyq":[{"year":2020,"question":"भारतीय रिजर्व बैंक का राष्ट्रीयकरण किस वर्ष हुआ?","strategy":"वर्ष (1949)।"}],"mnemonic":"RBI-1935, SBI-1955","impact_emoji":"🏦"}', '{"front":"Financial Institutions: RBI & Banks","points":["RBI: Est. 1 April 1935 (Hilton Young Comm), Nationalized 1949.","Monetary Policy: Credit control by RBI (Repo, CRR, SLR).","SBI: Formed in 1955 on Gorewala Committee recommendation."],"pyq":[{"year":2020,"question":"In which year was RBI nationalized?","strategy":"Year (1949)."}],"mnemonic":"RBI-1935, SBI-1955","impact_emoji":"🏦"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('fdd31789-9daf-410d-911f-1337fc57d718', 'unit_6', 'सेबी (SEBI), गैर बैंकिंग वित्तीय संस्थाएँ', 'SEBI and Non-Banking Financial Companies (NBFC)', '{"back":"शेयर बाज़ार की रखवाली करने वाली संस्था और वो कंपनियाँ जो बैंक नहीं हैं पर लोन देती हैं।"}', '{"back":"The watchdogs of the stock market and companies that provide loans without being traditional banks."}', 10, 0, NULL, 1769948930, '{"front":"SEBI और NBFC","points":["SEBI: स्थापना 1988, वैधानिक दर्जा 1992 (सेबी एक्ट), मुख्यालय: मुंबई।","कार्य: शेयर बाजार (Capital Market) का विनियमन, निवेशकों की सुरक्षा।","NBFC: बैंकिंग लाइसेंस के बिना वित्तीय सेवाएँ (जैसे मुथूट फाइनेंस, बजाज फिनसर्व)।"],"pyq":[{"year":2019,"question":"SEBI को वैधानिक दर्जा कब प्राप्त हुआ?","strategy":"वर्ष (1992)।"}],"mnemonic":"SEBI-92 (Statutory)","impact_emoji":"📊"}', '{"front":"SEBI and NBFC","points":["SEBI: Est. 1988, Statutory status 1992 (SEBI Act), HQ: Mumbai.","Function: Regulation of Capital Market, Investor protection.","NBFC: Financial services without banking license (e.g. Muthoot, Bajaj)."],"pyq":[{"year":2019,"question":"When did SEBI get statutory status?","strategy":"Year (1992)."}],"mnemonic":"SEBI-92 (Statutory)","impact_emoji":"📊"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('1f949707-2ff8-4a52-a323-5b25498172b2', 'unit_6', 'भारत की विदेशी व्यापार की नीतियाँ', 'India''s Foreign Trade Policy', '{"back":"दुनिया के दूसरे देशों के साथ सामान बेचने (Export) और खरीदने (Import) के सरकारी नियम।"}', '{"back":"The rules and strategies for buying (Import) and selling (Export) goods with other countries."}', 11, 0, NULL, 1769948930, '{"front":"भारत की विदेशी व्यापार नीतियाँ","points":["FTP 2023: 2030 तक 2 ट्रिलियन डॉलर के निर्यात का लक्ष्य।","EXIM बैंक: निर्यात-आयात बैंक, स्थापना 1982।","प्रमुख निर्यात: पेट्रोलियम उत्पाद, रत्न एवं आभूषण, दवाइयाँ।"],"pyq":[{"year":2022,"question":"एग्जिम बैंक (EXIM Bank) की स्थापना किस वर्ष हुई?","strategy":"वर्ष (1982)।"}],"mnemonic":"Target 2030 (2 Trillion)","impact_emoji":"🚢"}', '{"front":"India''s Foreign Trade Policy","points":["FTP 2023: Target of $2 Trillion exports by 2030.","EXIM Bank: Export-Import Bank, Est. 1982.","Major Exports: Petroleum products, Gems & Jewelry, Pharmaceuticals."],"pyq":[{"year":2022,"question":"In which year was EXIM Bank established?","strategy":"Year (1982)."}],"mnemonic":"Target 2030 (2 Trillion)","impact_emoji":"🚢"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('4e58494c-7cda-4ed2-a0b5-3aa0bff8d2b5', 'unit_6', 'जी-20 (G-20), सार्क (SAARC) तथा एशियन (ASEAN)', 'International Groups: G-20, SAARC, ASEAN', '{"back":"दुनिया के बड़े देशों के वो ग्रुप्स जहाँ भारत व्यापार और शांति की चर्चा करता है।"}', '{"back":"Global platforms where India collaborates for better trade, security, and economic ties."}', 12, 0, NULL, 1769948930, '{"front":"G-20, SAARC और ASEAN","points":["G-20: 2023 शिखर सम्मेलन भारत में (थीम: वसुधैव कुटुम्बकम)।","SAARC: मुख्यालय काठमांडू, 8 सदस्य (Trick: MBBS PAIN), भारत सबसे बड़ा सदस्य।","ASEAN: मुख्यालय जकार्ता, 10 सदस्य, भारत सदस्य नहीं है।"],"pyq":[{"year":2020,"question":"सार्क (SAARC) का मुख्यालय कहाँ स्थित है?","strategy":"स्थान (काठमांडू)।"}],"mnemonic":"MBBS PAIN (SAARC)","impact_emoji":"🌍"}', '{"front":"G-20, SAARC and ASEAN","points":["G-20: 2023 Summit in India (Theme: Vasudhaiva Kutumbakam).","SAARC: HQ Kathmandu, 8 Members (Trick: MBBS PAIN), India is largest.","ASEAN: HQ Jakarta, 10 Members, India is NOT a member."],"pyq":[{"year":2020,"question":"Where is the HQ of SAARC located?","strategy":"Location (Kathmandu)."}],"mnemonic":"MBBS PAIN (SAARC)","impact_emoji":"🌍"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('79d735e3-0cdd-4930-9664-faa923b446e9', 'unit_7', 'विज्ञान की प्रमुख शाखाओं का प्रारंभिक ज्ञान', 'Basic Knowledge of Science Branches', '{"back":"Physics, Chemistry और Biology के वो बेसिक नियम जो हमारे रोज़ाना के जीवन में काम आते हैं।"}', '{"back":"The fundamental principles of Physics, Chemistry, and Biology that we see in everyday life."}', 1, 0, NULL, 1769948930, '{"front":"विज्ञान की प्रमुख शाखाओं का प्रारंभिक ज्ञान","content":"अध्ययन के विशिष्ट क्षेत्र और उनके जनक।","points":["विटिकल्चर: अंगूर की खेती (Viti = Vine)।","सेरीकल्चर: रेशम कीट पालन (शहतूत के पत्ते)।","एंटोमोलोजी (Entomology): कीटों का अध्ययन (Insects)।"],"pyq":[{"year":2021,"question":"ओस्टियोलॉजी (Osteology) किसका अध्ययन है?","strategy":"Osteo = हड्डी (Bone)।"}],"mnemonic":"Entomo (Ant/कीटी) - Viti (Vine/अंगूर)","impact_emoji":"🔬"}', '{"front":"Basic Knowledge of Science Branches","content":"Specific fields of study and their terminology.","points":["Viticulture: Cultivation of Grapes.","Sericulture: Rearing of Silkworms (Mulberry leaves).","Entomology: Study of Insects."],"pyq":[{"year":2021,"question":"Osteology is the study of?","strategy":"Osteo = Bone."}],"mnemonic":"Entomo (Ant) - Viti (Vine)","impact_emoji":"🔬"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('1ec74f32-e421-4bfe-8f4f-3eff4f8ee8ea', 'unit_7', 'भारत के प्रमुख वैज्ञानिक संस्थान एवं उनकी उपलब्धियाँ', 'Major Scientific Institutions of India', '{"back":"ISRO, DRDO और CSIR जैसे संस्थान जिन्होंने भारत को विज्ञान की दुनिया में सरताज बनाया।"}', '{"back":"Pride of India—institutions like ISRO, DRDO, and BARC and their world-class achievements."}', 2, 0, NULL, 1769948930, '{"front":"भारत के प्रमुख वैज्ञानिक संस्थान","content":"मुख्यालय, स्थापना वर्ष और प्रमुख उपलब्धियाँ।","points":["ISRO: 15 अगस्त 1969, मुख्यालय: बेंगलुरु (प्रथम अध्यक्ष: विक्रम साराभाई)।","DRDO: 1958, मुख्यालय: नई दिल्ली (समीकरण: Defense + Tech)।","RRCAT: राजा रमन्ना प्रगत प्रौद्योगिकी केंद्र, इंदौर (1984 - लेजर अनुसंधान)।"],"pyq":[{"year":2022,"question":"राष्ट्रीय सुदूर संवेदन केंद्र (NRSC) कहाँ स्थित है?","strategy":"डाटा केंद्र = हैदराबाद (Cyber City)।"}],"mnemonic":"ISRO-69 (Space) | DRDO-58 (Defense) | RRCAT (Indore)","impact_emoji":"🚀"}', '{"front":"Major Scientific Institutions of India","content":"HQ, Founding Years and Achievements.","points":["ISRO: 15 Aug 1969, HQ: Bengaluru (1st Chief: Vikram Sarabhai).","DRDO: 1958, HQ: New Delhi.","RRCAT: Raja Ramanna Centre for Advanced Technology, Indore (1984 - Laser)."],"pyq":[{"year":2022,"question":"Where is the National Remote Sensing Centre (NRSC) located?","strategy":"Data Hub = Hyderabad."}],"mnemonic":"ISRO-69 (Space) | DRDO-58 (Defense) | RRCAT (Indore)","impact_emoji":"🚀"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('4c5e8113-5ca4-4a2d-a496-811f1c92b8e8', 'unit_7', 'उपग्रह एवं अंतरिक्ष प्रौद्योगिकी', 'Satellite and Space Technology', '{"back":"आसमान में तैरते हमारे सैटेलाइट्स और वो रॉकेट जो हमें तारों तक ले जाते हैं।"}', '{"back":"How rockets work and how satellites in space provide us with GPS, TV, and weather data."}', 3, 0, NULL, 1769948930, '{"front":"उपग्रह एवं अंतरिक्ष प्रौद्योगिकी","content":"भारतीय मिशन और प्रक्षेपण यान (PSLV/GSLV)।","points":["चंद्रयान-3: लॉन्च 14 जुलाई 2023, लैंडिंग 23 अगस्त (राष्ट्रीय अंतरिक्ष दिवस)।","लैंडिंग पॉइंट: ''शिव शक्ति'' (दक्षिणी ध्रुव)।","आदित्य L1: सूर्य मिशन, लैग्रेंज पॉइंट-1 (L1) पर स्थापित।"],"pyq":[{"year":2023,"question":"चंद्रयान-3 को किस रॉकेट से लॉन्च किया गया?","strategy":"बाहुबली रॉकेट = LVM3-M4."}],"mnemonic":"C3 = Shiv Shakti | C2 = Tiranga","impact_emoji":"🛰️"}', '{"front":"Satellite and Space Technology","content":"Indian Missions and Launch Vehicles.","points":["Chandrayaan-3: Launch 14 July 2023, Landed 23 Aug (National Space Day).","Landing Point: ''Shiv Shakti'' (South Pole).","Aditya L1: Solar Mission, placed at Lagrange Point-1."],"pyq":[{"year":2023,"question":"Which rocket launched Chandrayaan-3?","strategy":"Bahubali Rocket = LVM3-M4."}],"mnemonic":"C3 = Shiv Shakti | C2 = Tiranga","impact_emoji":"🛰️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('0f06453a-730b-444f-8008-29baf79cc196', 'unit_7', 'मानव शरीर संरचना', 'Human Body Structure', '{"back":"हड्डियों से लेकर दिल की धड़कन तक—इंसानी शरीर की अद्भुत मशीन कैसे काम करती है।"}', '{"back":"The incredible machinery of the human body—from the skeleton to the nervous system."}', 4, 0, NULL, 1769948930, '{"front":"मानव शरीर संरचना","content":"अंग तंत्र, कंकाल और महत्वपूर्ण ग्रंथियाँ।","points":["अस्थियाँ: कुल 206 (वयस्क)। सबसे छोटी: स्टेप्स (कान), सबसे बड़ी: फीमर (जांघ)।","यकृत (Liver): मानव शरीर की सबसे बड़ी ग्रंथि (1.5 kg)।","पिट्यूटरी ग्रंथि: ''मास्टर ग्रंथि'' (मस्तिष्क में स्थित)।"],"pyq":[{"year":2020,"question":"मानव शरीर में सबसे लंबी कोशिका कौन सी है?","strategy":"संदेश वाहक = तंत्रिका कोशिका (Neuron)।"}],"mnemonic":"Step on Ear (Stapes) | Femur on Thigh","impact_emoji":"🦴"}', '{"front":"Human Body Structure","content":"Organ systems, Skeleton, and Glands.","points":["Bones: Total 206. Smallest: Stapes (Ear), Largest: Femur (Thigh).","Liver: Largest Gland in human body (Chemical Lab).","Pituitary Gland: ''Master Gland'' (Located in Brain)."],"pyq":[{"year":2020,"question":"Which is the longest cell in the human body?","strategy":"Messenger = Neuron (Nerve Cell)."}],"mnemonic":"Step on Ear (Stapes) | Femur on Thigh","impact_emoji":"🦴"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('dbdcc173-4354-4d76-8ab3-a817dce79bcc', 'unit_7', 'पोषण, आहार, पोषक तत्व एवं कुपोषण', 'Nutrition, Diet and Nutrients', '{"back":"क्या खाने से शरीर बनता है और खाने की कमी से होने वाली बीमारियाँ।"}', '{"back":"The fuel for our body—understanding vitamins, minerals, and the impact of malnutrition."}', 5, 0, NULL, 1769948930, '{"front":"पोषण, आहार, पोषक तत्व एवं कुपोषण","content":"विटामिन, खनिज और उनकी कमी से होने वाले रोग।","points":["विटामिन C: एस्कॉर्बिक एसिड (कमी: स्कर्वी - मसूड़ों से खून)।","विटामिन D: कैल्सिफेरॉल (कमी: रिकेट्स/ऑस्टियोमलेशिया)।","प्रोटीन की कमी: क्वाशिओरकोर (सूजा हुआ पेट) और मरास्मस (सूखा)।"],"pyq":[{"year":2022,"question":"विटामिन ''A'' का रासायनिक नाम क्या है?","strategy":"आंख (Retina) = रेटिनॉल।"}],"mnemonic":"रथ एक टॉफी (A-Retinol, B-Thiamine, C-Ascorbic, D-Calciferol, E-Tocopherol)","impact_emoji":"🍎"}', '{"front":"Nutrition, Diet and Nutrients","content":"Vitamins, Minerals and Deficiency Diseases.","points":["Vitamin C: Ascorbic Acid (Deficiency: Scurvy).","Vitamin D: Calciferol (Deficiency: Rickets/Osteomalacia).","Protein Deficiency: Kwashiorkor (Pot belly) & Marasmus (Wasting)."],"pyq":[{"year":2022,"question":"What is the chemical name of Vitamin A?","strategy":"Eye (Retina) = Retinol."}],"mnemonic":"A-Retinol | C-Ascorbic | D-Calciferol (Calcium)","impact_emoji":"🍎"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('4293729d-7766-42f7-a915-923f0245b0ee', 'unit_7', 'अनुवांशिक रोग: सिकल सेल एनीमिया', 'Genetic Diseases: Sickle Cell Anemia', '{"back":"वो बीमारियाँ जो खून के जरिए पीढ़ियों तक पहुँचती हैं और उनका इलाज।"}', '{"back":"Inherited blood disorders, their biological causes, and how they are managed/prevented."}', 6, 0, NULL, 1769948930, '{"front":"अनुवांशिक रोग: सिकल सेल एनीमिया","content":"RBC का हंसियाकर (Sickle) होना। म.प्र. विशेष फोकस।","points":["कारण: गुणसूत्र 11 पर हीमोग्लोबिन जीन में उत्परिवर्तन (Glutamic Acid -> Valine)।","विश्व सिकल सेल दिवस: 19 जून।","मिशन: राष्ट्रीय सिकल सेल उन्मूलन मिशन (शहडोल से लॉन्च, लक्ष्य 2047)।"],"pyq":[{"year":2024,"question":"सिकल सेल एनीमिया में RBC का आकार कैसा हो जाता है?","strategy":"Sickle = हंसिया (Crescent Moon)।"}],"mnemonic":"Sickle-19 (June) | Shahdol-2047 (Target)","impact_emoji":"🩸"}', '{"front":"Genetic Diseases: Sickle Cell Anemia","content":"RBCs turn sickle-shaped. MP Special Focus.","points":["Cause: Mutation on Chromosome 11 (Glutamic Acid -> Valine).","World Sickle Cell Day: 19th June.","Mission: Launched from Shahdol (MP), Elimination Target: 2047."],"pyq":[{"year":2024,"question":"What happens to RBC shape in Sickle Cell Anemia?","strategy":"Sickle = Crescent/Farm Tool."}],"mnemonic":"Sickle-19 (June) | Shahdol-2047 (Target)","impact_emoji":"🩸"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('6f5a16b3-f792-48e4-bf33-5daae147e6b8', 'unit_7', 'स्वास्थ्य नीति एवं कार्यक्रम', 'Health Policy and Programs', '{"back":"सरकार की वो योजनाएं जो देश के हर नागरिक को सस्ता और अच्छा इलाज देने के लिए बनी हैं।"}', '{"back":"Government initiatives to provide affordable healthcare and eradicate diseases across India."}', 7, 0, NULL, 1769948930, '{"front":"स्वास्थ्य नीति एवं कार्यक्रम","content":"राष्ट्रीय और राज्य स्तरीय प्रमुख स्वास्थ्य योजनाएं।","points":["आयुष्मान भारत (PM-JAY): 2018 (रांची), ₹5 लाख तक का बीमा।","राष्ट्रीय ग्रामीण स्वास्थ्य मिशन (NRHM): 12 अप्रैल 2005।","मिशन इंद्रधनुष: 2014 (टीकाकरण/Vaccination से संबंधित)।"],"pyq":[{"year":2021,"question":"जननी सुरक्षा योजना कब शुरू हुई?","strategy":"NRHM के साथ (2005)।"}],"mnemonic":"NRHM (2005) -> Ayushman (2018)","impact_emoji":"🏥"}', '{"front":"Health Policy and Programs","content":"Flagship National and State Health Schemes.","points":["Ayushman Bharat: 2018 (Ranchi), Cover up to ₹5 Lakh.","National Rural Health Mission (NRHM): 12 April 2005.","Mission Indradhanush: 2014 (Related to Vaccination)."],"pyq":[{"year":2021,"question":"When was Janani Suraksha Yojana launched?","strategy":"With NRHM (2005)."}],"mnemonic":"NRHM (2005) -> Ayushman (2018)","impact_emoji":"🏥"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('1ed6c789-8cfd-4950-937f-c076e161b11c', 'unit_7', 'संक्रामक रोग, उनकी रोकथाम एवं स्वास्थ्य सूचक', 'Infectious Diseases and Prevention', '{"back":"फैलने वाली बीमारियाँ, उनसे बचने के तरीके और ये जाँचना कि देश कितना स्वस्थ है।"}', '{"back":"How germs spread, how to stop them, and the indicators that measure a nation''s health."}', 8, 0, NULL, 1769948930, '{"front":"संक्रामक रोग, रोकथाम एवं स्वास्थ्य सूचक","content":"जीवाणु, विषाणु और प्रोटोजोआ जनित रोग।","points":["जीवाणु (Bacteria): टी.बी. (मायकोबैक्टीरियम), टायफाइड (साल्मोनेला)।","विषाणु (Virus): डेंगू (एडीज मच्छर), रेबीज (हाइड्रोफोबिया)।","प्रोटोजोआ (Protozoa): मलेरिया (मादा एनाफिलीज)।"],"pyq":[{"year":2023,"question":"विडल टेस्ट (Widal Test) किस रोग के लिए किया जाता है?","strategy":"Common Fever = टायफाइड।"}],"mnemonic":"MP (Malaria-Protozoa) | TB (Bacteria) | DV (Dengue-Virus)","impact_emoji":"🦠"}', '{"front":"Infectious Diseases & Indicators","content":"Bacterial, Viral and Protozoan diseases.","points":["Bacteria: TB (Mycobacterium), Typhoid (Salmonella).","Virus: Dengue (Aedes Mosquito), Rabies (Hydrophobia).","Protozoa: Malaria (Female Anopheles), Kala-azar."],"pyq":[{"year":2023,"question":"Widal Test is used for which disease?","strategy":"Common Fever = Typhoid."}],"mnemonic":"MP (Malaria-Protozoa) | TB (Bacteria) | DV (Dengue-Virus)","impact_emoji":"🦠"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('e9c76679-fae2-4b68-99d4-b5d69285cb14', 'unit_7', 'सतत् विकास की अवधारणा एवं एस.डी.जी. (SDG)', 'Concept of Sustainable Development and SDGs', '{"back":"ऐसा विकास जो आज की ज़रूरतें पूरी करे और भविष्य की पीढ़ी के लिए भी संसाधन बचाए।"}', '{"back":"Meeting the needs of the present without compromising the ability of future generations to meet theirs."}', 9, 0, NULL, 1769948930, '{"front":"सतत् विकास की अवधारणा एवं SDG","content":"भविष्य की पीढ़ियों के लिए संसाधनों का संरक्षण।","points":["ब्रंटलैंड रिपोर्ट (1987): ''Our Common Future'' (परिभाषा दी)।","SDG लक्ष्य: कुल 17 लक्ष्य, 169 उप-लक्ष्य (2015-2030)।","लक्ष्य 1: शून्य गरीबी, लक्ष्य 2: शून्य भुखमरी।"],"pyq":[{"year":2022,"question":"एस.डी.जी. (SDG) 2030 में कितने लक्ष्य निर्धारित हैं?","strategy":"Number = 17 Goals।"}],"mnemonic":"1-Poor, 2-Hungry, 3-Healthy, 4-Educated","impact_emoji":"♻️"}', '{"front":"Sustainable Development & SDGs","content":"Preserving resources for future generations.","points":["Brundtland Report (1987): ''Our Common Future'' (Defined SD).","SDG Goals: 17 Goals, 169 Targets (Period 2015-2030).","Goal 1: No Poverty, Goal 2: Zero Hunger."],"pyq":[{"year":2022,"question":"How many goals are there in SDG 2030?","strategy":"Number = 17 Goals."}],"mnemonic":"1-Poor, 2-Hungry, 3-Healthy, 4-Educated","impact_emoji":"♻️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('6f11164b-289d-4158-b898-9b8f1daf0f8d', 'unit_7', 'पर्यावरणीय कारक, पारिस्थितिकीय तंत्र एवं जैव-विविधता', 'Environment, Ecosystem and Biodiversity', '{"back":"प्रकृति का वो जाल जहाँ जीव-जंतु और इंसान एक-दूसरे पर निर्भर रहते हैं।"}', '{"back":"The complex web of life where plants, animals, and humans depend on each other for survival."}', 10, 0, NULL, 1769948931, '{"front":"पर्यावरणीय कारक, पारिस्थितिकी एवं जैव-विविधता","content":"पारिस्थितिकी तंत्र के घटक और संरक्षण अधिनियम।","points":["शब्द प्रयोग: ''इकोलॉजी'' (अर्न्स्ट हैकल), ''इकोसिस्टम'' (ए.जी. टांसले)।","10% का नियम: लिंडमैन (ऊर्जा प्रवाह)।","जैव विविधता हॉटस्पॉट: भारत में 4 (पश्चिमी घाट, हिमालय, इंडो-बर्मा, सुंडालैंड)।"],"pyq":[{"year":2020,"question":"खाद्य श्रृंखला में ऊर्जा का प्रवाह कैसा होता है?","strategy":"हमेशा एकदिशीय (Unidirectional)।"}],"mnemonic":"Tansley (System) | Haeckel (Logy) | 10% (Lindeman)","impact_emoji":"🌿"}', '{"front":"Environment, Ecosystem & Biodiversity","content":"Ecosystem components and Conservation Acts.","points":["Terms: ''Ecology'' (Ernst Haeckel), ''Ecosystem'' (A.G. Tansley).","10% Law: Lindeman (Energy flow decreases by 90%).","Biodiversity Hotspots: 4 in India (Western Ghats, Himalayas, etc)."],"pyq":[{"year":2020,"question":"Energy flow in an ecosystem is?","strategy":"Always Unidirectional."}],"mnemonic":"Tansley (System) | Haeckel (Logy) | 10% (Lindeman)","impact_emoji":"🌿"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('52aaaaac-4c2a-4678-b41c-157f2cc26769', 'unit_7', 'प्रदूषण, प्राकृतिक आपदाएँ एवं प्रबंधन', 'Pollution and Natural Disaster Management', '{"back":"गंदी हवा-पानी की समस्या और बाढ़-भूकंप जैसे खतरों से बचने का तरीका।"}', '{"back":"The threat of environmental damage and strategies to handle floods, earthquakes, and cyclones."}', 11, 0, NULL, 1769948931, '{"front":"प्रदूषण, प्राकृतिक आपदाएँ एवं प्रबंधन","content":"प्रमुख त्रासदियाँ और आपदा प्रबंधन अधिनियम।","points":["भोपाल गैस त्रासदी: 2-3 दिसंबर 1984 (मिथाइल आइसोसायनेट - MIC)।","मिनीमाता रोग: पारा (Mercury) प्रदूषण। इटाई-इटाई: कैडमियम (Cadmium)।","आपदा प्रबंधन अधिनियम: 2005 (NDMA के अध्यक्ष: प्रधानमंत्री)।"],"pyq":[{"year":2021,"question":"ब्लू बेबी सिंड्रोम (Blue Baby Syndrome) किस कारण होता है?","strategy":"पानी में नाइट्रेट (Nitrate)।"}],"mnemonic":"Mini-Mercury | Itai-Cadmium | Blue-Nitrate","impact_emoji":"⚠️"}', '{"front":"Pollution & Disaster Management","content":"Major Tragedies and Management Acts.","points":["Bhopal Gas Tragedy: 2-3 Dec 1984 (Methyl Isocyanate - MIC).","Minamata Disease: Mercury. Itai-Itai: Cadmium.","Disaster Management Act: 2005 (NDMA Head: PM)."],"pyq":[{"year":2021,"question":"Blue Baby Syndrome is caused by?","strategy":"Nitrate in water."}],"mnemonic":"Mini-Mercury | Itai-Cadmium | Blue-Nitrate","impact_emoji":"⚠️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('626bac0d-f23f-40ac-b491-ede55d40d1e9', 'unit_8', 'अंतर्राष्ट्रीय समसामयिक घटनाएँ', 'International Current Events', '{"back":"पूरी दुनिया में होने वाली बड़ी हलचलें, समझौते और वर्ल्ड लीडर्स के बीच की चर्चाएं।"}', '{"back":"Major global happenings, international summits, and shifting diplomatic relations between world powers."}', 1, 0, NULL, 1769948931, '{"front":"अंतर्राष्ट्रीय समसामयिक घटनाएँ","points":["प्रमुख नियुक्तियाँ: संयुक्त राष्ट्र (UN) के महासचिव, विभिन्न देशों के भारतीय मूल के राष्ट्राध्यक्ष।","अंतर्राष्ट्रीय पुरस्कार: नोबेल पुरस्कार (विजेता व क्षेत्र), ऑस्कर, और बुकर प्राइज।","वैश्विक सूचकांक: प्रेस स्वतंत्रता, प्रसन्नता सूचकांक और मानव विकास सूचकांक (HDI) में भारत का स्थान।"],"pyq":[{"year":2021,"question":"वर्ष 2021 के ''नोबेल शांति पुरस्कार'' से किसे सम्मानित किया गया?","strategy":"पुरस्कार (मारिया रसा और दमित्री मुरातोव)।"}],"mnemonic":"Index-Award-Appoint (IAA)","impact_emoji":"🌍"}', '{"front":"International Current Events","points":["Major Appointments: UN Secretary-General, Indian-origin Heads of States.","Global Awards: Nobel Prize (Winners & Fields), Oscars, and Booker Prize.","Global Indices: India''s rank in Press Freedom, Happiness Index, and HDI."],"pyq":[{"year":2021,"question":"Who was awarded the Nobel Peace Prize 2021?","strategy":"Award (Maria Ressa & Dmitry Muratov)."}],"mnemonic":"Index-Award-Appoint (IAA)","impact_emoji":"🌍"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('644dc59b-e91e-496e-a6d4-2778dc51d688', 'unit_8', 'राष्ट्रीय समसामयिक घटनाएँ', 'National Current Events', '{"back":"हमारे देश में आज क्या नया हो रहा है—नई योजनाएं, कानून और बड़ी खबरें।"}', '{"back":"Key developments across India, including new government schemes, legal landmark decisions, and national achievements."}', 2, 0, NULL, 1769948931, '{"front":"राष्ट्रीय समसामयिक घटनाएँ","points":["योजनाएं: आयुष्मान भारत, पीएम-किसान, और जल जीवन मिशन जैसी प्रमुख केंद्र सरकार की योजनाएं।","खेल: ओलंपिक, एशियाई खेल, और राष्ट्रीय खेल (विजेता और आयोजन स्थल)।","रक्षा: प्रमुख सैन्य अभ्यास (जैसे ''सूर्य किरण'', ''गरुड़'') और रक्षा सौदे।"],"pyq":[{"year":2022,"question":"नीति आयोग के वर्तमान उपाध्यक्ष कौन हैं?","strategy":"नियुक्ति (सुमन बेरी)।"}],"mnemonic":"Scheme-Sports-Defense (SSD)","impact_emoji":"🇮🇳"}', '{"front":"National Current Events","points":["Schemes: Ayushman Bharat, PM-Kisan, and Jal Jeevan Mission.","Sports: Olympics, Asian Games, and National Games (Winners & Venues).","Defense: Major Military Exercises (e.g., ''Surya Kiran'') and Defense Deals."],"pyq":[{"year":2022,"question":"Who is the current Vice-Chairman of NITI Aayog?","strategy":"Appointment (Suman Bery)."}],"mnemonic":"Scheme-Sports-Defense (SSD)","impact_emoji":"🇮🇳"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('a63ed3b7-1a2a-419c-ac06-c0af79958f80', 'unit_8', 'मध्यप्रदेश की समसामयिक घटनाएँ', 'Current Events of Madhya Pradesh', '{"back":"हमारे अपने राज्य की ताज़ा खबरें, सरकारी फैसले और MP का गौरव बढ़ाने वाली बातें।"}', '{"back":"Latest news and policy decisions from our own state, highlighting MP''s growth and local milestones."}', 3, 0, NULL, 1769948931, '{"front":"मध्यप्रदेश की समसामयिक घटनाएँ","points":["पुरस्कार: कालिदास सम्मान, तानसेन सम्मान और पद्म पुरस्कार (म.प्र. के प्राप्तकर्ता)।","योजनाएं: लाड़ली बहना योजना, लाड़ली लक्ष्मी 2.0, और संबल योजना।","प्रमुख स्थल: कूनो नेशनल पार्क (चीता पुनरुद्धार), सांची (भारत की पहली सोलर सिटी)।"],"pyq":[{"year":2023,"question":"खेलो इंडिया यूथ गेम्स का 5वाँ संस्करण म.प्र. के कितने शहरों में आयोजित हुआ?","strategy":"खेल आयोजन (8 शहर)।"}],"mnemonic":"Honor-Scheme-Venue (HSV)","impact_emoji":"🏹"}', '{"front":"Current Events of Madhya Pradesh","points":["Honors: Kalidas Samman, Tansen Samman, and Padma Awards (MP recipients).","Schemes: Ladli Behna Yojana, Ladli Laxmi 2.0, and Sambal Yojana.","Key Locations: Kuno National Park (Cheetah Project), Sanchi (India''s first Solar City)."],"pyq":[{"year":2023,"question":"In how many cities of MP was the 5th edition of Khelo India Youth Games held?","strategy":"Sports Event (8 Cities)."}],"mnemonic":"Honor-Scheme-Venue (HSV)","impact_emoji":"🏹"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('e6792a2d-f287-425c-93dd-39e2cebc4170', 'unit_9', 'कंप्यूटर का आधारभूत ज्ञान', 'Basic Knowledge of Computer', '{"back":"कंप्यूटर कैसे काम करता है—हार्डवेयर, सॉफ्टवेयर और ऑपरेटिंग सिस्टम की बेसिक जानकारी।"}', '{"back":"Understanding how computers work—including hardware, software systems, and basic operating principles."}', 1, 0, NULL, 1769948931, '{"front":"कंप्यूटर का आधारभूत ज्ञान","points":["पीढ़ियाँ: पहली (Vaccum Tubes), दूसरी (Transistors), तीसरी (IC Chips), चौथी (Microprocessors)।","मेमोरी: RAM (Volatile), ROM (Non-volatile), Cache (सबसे तेज)।","सॉफ्टवेयर: ऑपरेटिंग सिस्टम (OS), कंपाइलर, इंटरप्रेटर।"],"pyq":[{"year":2021,"question":"कंप्यूटर की किस पीढ़ी में माइक्रोप्रोसेसर का उपयोग किया गया था?","strategy":"तथ्य (चौथी पीढ़ी)।"}],"mnemonic":"V-T-I-M (Vacuum, Transistor, IC, Micro)","impact_emoji":"💻"}', '{"front":"Basic Knowledge of Computer","points":["Generations: 1st (Vacuum Tubes), 2nd (Transistors), 3rd (IC Chips), 4th (Microprocessors).","Memory: RAM (Volatile), ROM (Non-volatile), Cache (Fastest).","Software: OS (Operating System), Compiler, Interpreter."],"pyq":[{"year":2021,"question":"In which generation of computers was the microprocessor used?","strategy":"Fact (4th Generation)."}],"mnemonic":"V-T-I-M (Vacuum, Transistor, IC, Micro)","impact_emoji":"💻"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('64ce3f11-7f58-4584-ac5d-ae4faa14e424', 'unit_9', 'इलेक्ट्रॉनिकी (Electronics)', 'Electronics, Information and Communication Technology', '{"back":"सेमीकंडक्टर, चिप्स और वो तकनीक जिससे हमारे मोबाइल और गैजेट्स चलते हैं।"}', '{"back":"The science of circuits, semiconductors, and the tech behind modern digital communication."}', 2, 0, NULL, 1769948931, '{"front":"इलेक्ट्रॉनिकी (Electronics)","points":["सेमीकंडक्टर: सिलिकॉन और जर्मेनियम प्रमुख उदाहरण।","उपकरण: डायोड (धारा एक दिशा में), ट्रांजिस्टर (सिग्नल एम्प्लीफिकेशन)।","भारत में: इलेक्ट्रॉनिक्स विभाग की स्थापना 1970 में।"],"pyq":[{"year":2020,"question":"एक अर्धचालक (Semiconductor) में अशुद्धियाँ मिलाने की प्रक्रिया को क्या कहते हैं?","strategy":"पारिभाषिक शब्दावली (डोपिंग)।"}],"mnemonic":"Si-Ge (Silicon-Germanium)","impact_emoji":"🔌"}', '{"front":"Electronics & ICT","points":["Semiconductors: Silicon and Germanium are primary examples.","Components: Diode (One-way current), Transistor (Amplification).","India: Dept. of Electronics established in 1970."],"pyq":[{"year":2020,"question":"What is the process of adding impurities to a semiconductor called?","strategy":"Terminology (Doping)."}],"mnemonic":"Si-Ge (Silicon-Germanium)","impact_emoji":"🔌"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('38220050-4c5b-4a14-b91a-075b3d6b6f67', 'unit_9', 'सूचना एवं संचार प्रौद्योगिकी', 'Robotics', '{"back":"डाटा भेजने और बातचीत करने के आधुनिक तरीके, जैसे टेलीकॉम और नेटवर्क।"}', '{"back":"The design and use of automated machines programmed to perform tasks traditionally done by humans."}', 3, 0, NULL, 1769948931, NULL, NULL, 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('58c89fbc-a011-42d3-8945-5650da94e4cc', 'unit_9', 'रोबोटिक्स (Robotics)', 'Artificial Intelligence (AI)', '{"back":"इंसानों की तरह काम करने वाली मशीनें और उनकी बनावट व उपयोग।"}', '{"back":"Smart machines that can learn, reason, and solve problems like a human brain—shaping the future of tech."}', 4, 0, NULL, 1769948931, '{"front":"रोबोटिक्स (Robotics)","points":["नियम: ''आइजैक असिमोव'' ने रोबोटिक्स के तीन नियम दिए।","घटक: सेंसर, एक्चुएटर, कंट्रोलर।","भारतीय रोबोट: व्योममित्र (ISRO द्वारा निर्मित महिला रोबोट), चतुर।"],"pyq":[{"year":2022,"question":"इसरो द्वारा विकसित ''व्योममित्र'' क्या है?","strategy":"तथ्य (ह्यूमनॉइड रोबोट)।"}],"mnemonic":"Asimov''s Law, Vyommitra","impact_emoji":"🤖"}', '{"front":"Robotics","points":["Laws: Isaac Asimov gave the ''Three Laws of Robotics''.","Components: Sensors, Actuators, Controllers.","Indian Robots: Vyommitra (ISRO''s female humanoid), Chatur."],"pyq":[{"year":2022,"question":"What is ''Vyommitra'' developed by ISRO?","strategy":"Fact (Humanoid Robot)."}],"mnemonic":"Asimov''s Law, Vyommitra","impact_emoji":"🤖"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('12bf145d-5b27-49d4-8360-b007aa9e5b88', 'unit_9', 'आर्टिफिशियल इंटेलिजेंस (AI)', 'Cyber Security', '{"back":"मशीनों का इंसानी दिमाग की तरह सोचना और फैसले लेना, जैसे चैटबॉट्स और ऑटोमेशन।"}', '{"back":"Strategies and tools used to protect digital data from hackers and online threats."}', 5, 0, NULL, 1769948931, '{"front":"आर्टिफिशियल इंटेलिजेंस (AI)","points":["जनक: जॉन मैकार्थी (1956 डार्टमाउथ सम्मेलन)।","प्रकार: मशीन लर्निंग, डीप लर्निंग, NLP (Natural Language Processing)।","उदाहरण: ChatGPT (OpenAI), बार्ड/जेमिनी (Google), एलेक्सा।"],"pyq":[{"year":2021,"question":"आर्टिफिशियल इंटेलिजेंस का जनक किसे माना जाता है?","strategy":"व्यक्तित्व (जॉन मैकार्थी)।"}],"mnemonic":"McCarthy-1956","impact_emoji":"🧠"}', '{"front":"Artificial Intelligence (AI)","points":["Father: John McCarthy (1956 Dartmouth Conference).","Types: Machine Learning, Deep Learning, NLP.","Examples: ChatGPT (OpenAI), Bard/Gemini (Google), Alexa."],"pyq":[{"year":2021,"question":"Who is considered the father of Artificial Intelligence?","strategy":"Personality (John McCarthy)."}],"mnemonic":"McCarthy-1956","impact_emoji":"🧠"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('b9bb9b0f-54f1-4070-8b89-2a17c3f144c5', 'unit_9', 'साइबर सिक्योरिटी', 'E-Governance', '{"back":"इंटरनेट की दुनिया में हैकर्स से बचने और अपने डाटा को सुरक्षित रखने के तरीके।"}', '{"back":"The use of digital platforms by the government to provide fast and transparent services to citizens."}', 6, 0, NULL, 1769948931, '{"front":"साइबर सिक्योरिटी","points":["खतरे: मालवेयर (वायरस, वर्म, ट्रोजन), फिशिंग, रैनसमवेयर।","सुरक्षा: फायरवॉल (Firewall), एन्क्रिप्शन, टू-फैक्टर ऑथेंटिकेशन।","CERT-In: भारत की नेशनल नोडल एजेंसी (2004)।"],"pyq":[{"year":2020,"question":"इनमें से कौन सा एक साइबर हमला नहीं है?","strategy":"पहचान (विकल्प आधारित)।"}],"mnemonic":"Malware-Phish-Ransom","impact_emoji":"🛡️"}', '{"front":"Cyber Security","points":["Threats: Malware (Virus, Worm, Trojan), Phishing, Ransomware.","Protection: Firewall, Encryption, 2FA (Two-factor Auth).","CERT-In: National nodal agency for cyber incidents (2004)."],"pyq":[{"year":2020,"question":"Which of the following is not a cyber attack?","strategy":"Identification (Option based)."}],"mnemonic":"Malware-Phish-Ransom","impact_emoji":"🛡️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('00587594-26da-4a48-8425-1d23cd57dc6a', 'unit_9', 'ई-गवर्नेंस', 'Internet and Social Networking Platforms', '{"back":"सरकारी सुविधाओं का डिजिटल होना, ताकि जनता को घर बैठे सरकारी सेवाएँ मिल सकें।"}', '{"back":"The global web of connectivity and platforms like X, LinkedIn, and Facebook that redefine communication."}', 7, 0, NULL, 1769948931, '{"front":"ई-गवर्नेंस","points":["मॉडल: G2G (Gov to Gov), G2C (Gov to Citizen), G2B (Gov to Business)।","प्रमुख पहल: डिजिटल इंडिया (2015), डिजिलॉकर, उमंग (UMANG) ऐप।","म.प्र.: ''स्वान'' (SWAN) नेटवर्क, एमपी ऑनलाइन।"],"pyq":[{"year":2019,"question":"डिजिटल इंडिया कार्यक्रम की शुरुआत कब हुई थी?","strategy":"वर्ष (1 जुलाई 2015)।"}],"mnemonic":"G2C (Common Citizen)","impact_emoji":"🏛️"}', '{"front":"E-Governance","points":["Models: G2G, G2C, G2B, G2E.","Initiatives: Digital India (2015), DigiLocker, UMANG App.","MP Context: SWAN (State Wide Area Network), MP Online."],"pyq":[{"year":2019,"question":"When was the Digital India program launched?","strategy":"Year (1 July 2015)."}],"mnemonic":"G2C (Common Citizen)","impact_emoji":"🏛️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('38e6d5ae-a398-45e4-a298-8f660fff0b20', 'unit_9', 'इंटरनेट तथा सोशल नेटवर्किंग प्लेटफॉर्म्स', NULL, '{"back":"फेसबुक, एक्स (Twitter) और इंस्टाग्राम जैसे प्लेटफॉर्म्स और इंटरनेट का जाल।"}', NULL, 8, 0, NULL, 1769948931, '{"front":"इंटरनेट तथा सोशल नेटवर्किंग","points":["प्रोटोकॉल: HTTP, TCP/IP, FTP, SMTP (ईमेल हेतु)।","सोशल मीडिया: फेसबुक (2004), ट्विटर/X (2006), इंस्टाग्राम (2010)।","सर्च इंजन: गूगल, बिंग, बतख (DuckDuckGo)।"],"pyq":[{"year":2021,"question":"ईमेल के जनक किसे माना जाता है?","strategy":"व्यक्तित्व (रे टॉमलिंसन)।"}],"mnemonic":"SMTP (Simple Mail To Person)","impact_emoji":"🌐"}', '{"front":"Internet & Social Networking","points":["Protocols: HTTP, TCP/IP, FTP, SMTP (for Emails).","Social Media: Facebook (2004), Twitter/X (2006), Instagram (2010).","Search Engines: Google, Bing, DuckDuckGo."],"pyq":[{"year":2021,"question":"Who is considered the father of Email?","strategy":"Personality (Ray Tomlinson)."}],"mnemonic":"SMTP (Simple Mail To Person)","impact_emoji":"🌐"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('36a2abc5-f758-43e7-8296-b60e0589363b', 'unit_10', 'मध्यप्रदेश में जनजातियों का भौगोलिक विस्तार', 'Geographical Distribution and Constitutional Provisions', '{"back":"MP के नक्शे पर कौन सी जनजाति (भील, गोंड, कोरकू आदि) कहाँ बसी है।"}', '{"back":"Where different tribes live across MP and the legal laws in the Constitution that protect their rights."}', 1, 0, NULL, 1769948931, '{"front":"मध्यप्रदेश में जनजातियों का भौगोलिक विस्तार","content":"MP में देश की सर्वाधिक जनजातीय जनसंख्या (1.53 करोड़) निवास करती है।","points":["जनसंख्या: 21.1% (2011 जनगणना अनुसार)।","सर्वाधिक विस्तार: पश्चिमी म.प्र. (भील) एवं पूर्वी म.प्र. (गोंड)।","जिला: सर्वाधिक संख्या (धार), सर्वाधिक प्रतिशत (अलीराजपुर - 89%)।"],"pyq":[{"year":2022,"question":"मध्यप्रदेश के किस जिले में जनजातीय जनसंख्या का प्रतिशत सर्वाधिक है?","strategy":"प्रतिशत में ''अलीराजपुर'', संख्या में ''धार''।"}],"mnemonic":"ZONE: West(Bhil) - East(Gond) - South(Bharia)","impact_emoji":"🗺️"}', '{"front":"Geographical Distribution of Tribes in MP","content":"MP hosts the largest tribal population in India (1.53 Crore).","points":["Population: 21.1% (As per Census 2011).","Distribution: Western MP (Bhil) & Eastern MP (Gond).","District: Max Population (Dhar), Max Percentage (Alirajpur - 89%)."],"pyq":[{"year":2022,"question":"Which district has the highest percentage of tribal population?","strategy":"Percentage = Alirajpur, Absolute = Dhar."}],"mnemonic":"ZONE: West(Bhil) - East(Gond) - South(Bharia)","impact_emoji":"🗺️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('e279f5a6-fe0d-4e4e-9637-6ab00e70867f', 'unit_10', 'जनजातियों से संबंधित संवैधानिक प्रावधान', 'Particularly Vulnerable Tribal Groups (PVTG)', '{"back":"संविधान के वो कानून और आर्टिकल्स जो आदिवासियों के अधिकारों की रक्षा करते हैं।"}', '{"back":"Special focus on the Baiga, Bharia, and Sahariya tribes who need extra protection and care."}', 2, 0, NULL, 1769948931, '{"front":"जनजातियों से संबंधित संवैधानिक प्रावधान","content":"भारतीय संविधान के भाग 10 और 5वीं/6ठी अनुसूची में विशेष प्रावधान।","points":["अनुच्छेद 342: राष्ट्रपति द्वारा जनजातियों की घोषणा।","अनुच्छेद 338A: राष्ट्रीय अनुसूचित जनजाति आयोग (NCST)।","अनुच्छेद 244(1): अनुसूचित क्षेत्रों का प्रशासन।"],"pyq":[{"year":2023,"question":"राष्ट्रीय अनुसूचित जनजाति आयोग का वर्णन किस अनुच्छेद में है?","strategy":"338(SC) -> 338A(ST) -> 338B(OBC)."}],"mnemonic":"342 (Who) -> 338A (Commission) -> 244 (Area)","impact_emoji":"⚖️"}', '{"front":"Constitutional Provisions for Tribes","content":"Special provisions in Part 10 and 5th/6th Schedule of Constitution.","points":["Article 342: Notification of Tribes by President.","Article 338A: National Commission for ST (NCST).","Article 244(1): Administration of Scheduled Areas."],"pyq":[{"year":2023,"question":"Which article deals with the National Commission for ST?","strategy":"338(SC) -> 338A(ST) -> 338B(OBC)."}],"mnemonic":"342 (Who) -> 338A (Commission) -> 244 (Area)","impact_emoji":"⚖️"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('e4935aec-0d01-4920-96d4-861df04410d1', 'unit_10', 'मध्यप्रदेश की प्रमुख जनजातियाँ', 'Tribal Welfare Programs', '{"back":"राज्य की सबसे बड़ी और प्रभावशाली जनजातियों का विस्तृत परिचय।"}', '{"back":"Government initiatives and schemes specifically designed to improve the lives and livelihood of tribal communities."}', 3, 0, NULL, 1769948931, '{"front":"मध्यप्रदेश की प्रमुख जनजातियाँ","content":"गोंड, भील, कोल, कोरकू और बैगा प्रमुख समूह हैं।","points":["भील: म.प्र. की सबसे बड़ी जनजाति (पश्चिमी म.प्र.)।","गोंड: सबसे बड़ा समूह, उपजातियां (अगरिया, ओझा, प्रधान)।","कोरकू: सतपुड़ा क्षेत्र, उपजातियां (रोमा, बवारी, बोबई)।"],"pyq":[{"year":2021,"question":"भगोरिया हाट किस जनजाति से संबंधित है?","strategy":"होली + झाबुआ + भील।"}],"mnemonic":"Bhil (Big-West) | Gond (Group-East) | Korku (Satpura)","impact_emoji":"🏹"}', '{"front":"Major Tribes of Madhya Pradesh","content":"Gond, Bhil, Kol, Korku and Baiga are major groups.","points":["Bhil: Largest tribe of MP (Western MP).","Gond: Largest group, Subcastes (Agariya, Ojha, Pradhan).","Korku: Satpura region, Subcastes (Roma, Bawari, Bobai)."],"pyq":[{"year":2021,"question":"Bhagoriya Haat is related to which tribe?","strategy":"Holi + Jhabua + Bhil."}],"mnemonic":"Bhil (Big-West) | Gond (Group-East) | Korku (Satpura)","impact_emoji":"🏹"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('361d6510-d4b7-42fb-b2ed-712e437d1d72', 'unit_10', 'विशेष पिछड़ी जनजातियाँ (PVTG)', 'Tribal Culture: Customs, Traditions, and Special Arts', '{"back":"बैगा, भारिया और सहरिया जैसी वो जनजातियाँ जिन्हें विशेष मदद और सुरक्षा की ज़रूरत है।"}', '{"back":"The rich lifestyle of tribes, including their unique marriage rituals, tattoos (Godna), and handcrafted arts."}', 4, 0, NULL, 1769948931, '{"front":"विशेष पिछड़ी जनजातियाँ (PVTG)","content":"म.प्र. में 3 जनजातियों को PVTG का दर्जा प्राप्त है।","points":["बैगा: मंडला, बालाघाट (चक, बैगाचक)।","भारिया: पातालकोट (छिंदवाड़ा), ''जंगलियों के भी जंगली'' (1981 जनगणना)।","सहरिया: उत्तरी म.प्र. (श्योपुर, ग्वालियर), कुपोषण से ग्रस्त।"],"pyq":[{"year":2020,"question":"पातालकोट किस जनजाति का निवास स्थान है?","strategy":"गहराई (पाताल) = भारिया।"}],"mnemonic":"B-B-S (बैगा - भारिया - सहरिया)","impact_emoji":"🔥"}', '{"front":"Particularly Vulnerable Tribal Groups (PVTG)","content":"3 Tribes in MP have PVTG status.","points":["Baiga: Mandla, Balaghat (Chak, Baigachak).","Bharia: Patalkot (Chhindwara), ''Savages of Savages'' (1981 Census).","Sahariya: Northern MP (Sheopur), High malnutrition."],"pyq":[{"year":2020,"question":"Patalkot is the habitat of which tribe?","strategy":"Deep (Patal) = Bharia."}],"mnemonic":"B-B-S (Baiga - Bharia - Sahariya)","impact_emoji":"🔥"}', 1, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('27af7483-7ef3-42c6-ad37-bf8d1d55d435', 'unit_10', 'घुमन्तू जातियाँ', 'Festivals, Dialects, and Literature', '{"back":"वो समाज जो एक जगह टिकने के बजाय अपनी संस्कृति के साथ एक जगह से दूसरी जगह प्रवास करते हैं।"}', '{"back":"Vibrant celebrations like Bhagoria, their native tongues, and stories passed down through generations."}', 5, 0, NULL, 1769948931, '{"front":"घुमन्तू जातियाँ (Nomadic Tribes)","content":"वे जातियाँ जो निरंतर भ्रमणशील रहती हैं (जैसे बंजारा)।","points":["बंजारा: कंघी के आविष्कारक, प्रमुख नृत्य (तलवार, डांडा)।","विमुक्त जाति दिवस: 31 अगस्त (म.प्र. में)।","योजना: मुख्यमंत्री विमुक्त, घुमक्कड़ एवं अर्द्ध-घुमक्कड़ बस्ती विकास योजना (2013)।"],"pyq":[{"year":2024,"question":"कंघी कला का श्रेय किस जनजाति को जाता है?","strategy":"श्रृंगार प्रेमी = बंजारा।"}],"mnemonic":"Comb (Kanghi) = Banjara","impact_emoji":"🎪"}', '{"front":"Nomadic Tribes (Ghumantu)","content":"Tribes that are constantly moving (e.g., Banjara).","points":["Banjara: Inventors of the Comb, Dance (Talwar, Danda).","Vimukt Jati Day: 31st August (In MP).","Scheme: MM Vimukt, Ghumakkad Basti Vikas Yojana (2013)."],"pyq":[{"year":2024,"question":"Which tribe is credited with the invention of the comb?","strategy":"Fashion Lovers = Banjara."}],"mnemonic":"Comb (Kanghi) = Banjara","impact_emoji":"🎪"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('30a4384e-440d-46c7-9b3f-2dee7e46015e', 'unit_10', 'जनजातियों के कल्याण के लिए योजनाएँ', 'Contribution to the Freedom Movement', '{"back":"सरकार द्वारा चलाई जा रही वो स्कीम्स जो आदिवासियों के जीवन को बेहतर बना रही हैं।"}', '{"back":"The heroic struggle of tribal warriors who fought bravely against British rule for their land and pride."}', 6, 0, NULL, 1769948932, '{"front":"जनजातियों के कल्याण के लिए योजनाएँ","content":"आर्थिक और सामाजिक उत्थान हेतु प्रमुख शासकीय पहल।","points":["आहार अनुदान योजना: बैगा, भारिया, सहरिया महिलाओं को ₹1500/माह (2017)।","सिकल सेल उन्मूलन मिशन: 2047 तक उन्मूलन का लक्ष्य (शहडोल से लॉन्च)।","टंट्या मामा आर्थिक कल्याण योजना: युवाओं को ऋण सहायता।"],"pyq":[{"year":2023,"question":"आहार अनुदान योजना में कितनी राशि दी जाती है?","strategy":"अब ₹1500 (पहले ₹1000 थी)।"}],"mnemonic":"Food (Aahar-PVTG) | Health (Sickle-2047) | Money (Tantiya)","impact_emoji":"🤝"}', '{"front":"Tribal Welfare Schemes","content":"Govt initiatives for economic and social upliftment.","points":["Aahar Anudan Yojana: ₹1500/month to Baiga, Bharia, Sahariya women (2017).","Sickle Cell Mission: Target elimination by 2047 (Launched from Shahdol).","Tantiya Mama Economic Welfare Scheme: Loan support for youth."],"pyq":[{"year":2023,"question":"What is the amount provided under Aahar Anudan Yojana?","strategy":"Now ₹1500 (Previously ₹1000)."}],"mnemonic":"Food (Aahar-PVTG) | Health (Sickle-2047) | Money (Tantiya)","impact_emoji":"🤝"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('0fd3c592-d13e-4a87-a700-0aa9c9647230', 'unit_10', 'जनजातीय संस्कृति: परम्पराएँ, विशिष्ट कलाएँ', 'Tribal Personalities of Madhya Pradesh', '{"back":"उनके अनोखे रीति-रिवाज, टैटू (गूदना) और हाथों से बनी कलाकृतियाँ।"}', '{"back":"Icons like Tantya Bhil and Rani Durgavati who represent the courage and heritage of our state."}', 7, 0, NULL, 1769948932, '{"front":"जनजातीय संस्कृति: परम्पराएँ, विशिष्ट कलाएँ","content":"चित्रकला और शिल्पकला की समृद्ध विरासत।","points":["पिथौरा चित्रकला: भील जनजाति (पेमा फाल्या, भूरी बाई)।","गोंड चित्रकला: बिंदु और रेखा प्रधान (जनगढ़ सिंह श्याम)।","धातु शिल्प: ढोकरा कला (बैतूल - भरेवा समुदाय)।"],"pyq":[{"year":2021,"question":"पेमा फाल्या का संबंध किस चित्रकला से है?","strategy":"भील = पिथौरा (घोड़े का चित्रांकन)।"}],"mnemonic":"Pithora (Bhil) - Dhokra (Betul) - Nandna (Print)","impact_emoji":"🎨"}', '{"front":"Tribal Culture: Customs & Special Arts","content":"Rich heritage of paintings and craftsmanship.","points":["Pithora Painting: Bhil Tribe (Pema Fatya, Bhuri Bai).","Gond Painting: Dots & Lines dominant (Jangarh Singh Shyam).","Metal Craft: Dhokra Art (Betul - Bharewa community)."],"pyq":[{"year":2021,"question":"Pema Fatya is associated with which painting style?","strategy":"Bhil = Pithora (Depiction of Horses)."}],"mnemonic":"Pithora (Bhil) - Dhokra (Betul) - Nandna (Print)","impact_emoji":"🎨"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('ae9d26f0-f140-42c3-8abe-f55e6fc8c9ed', 'unit_10', 'जनजातीय त्योहार, उत्सव, भाषा और बोली', 'Tribal Institutes, Museums and Publications', '{"back":"भगोरिया जैसे मेले और उनकी अपनी मीठी बोलियाँ जो हमारी संस्कृति की जड़ें हैं।"}', '{"back":"Centers that preserve tribal history and the books that document their ancient wisdom."}', 8, 0, NULL, 1769948932, '{"front":"जनजातीय त्योहार, उत्सव, भाषा और बोली","content":"सांस्कृतिक उत्सव और भाषाई विविधता।","points":["भगोरिया (भील): होली के समय, 3 चरण (गुलालिया, गोल-गधेड़ो, उजाड़िया)।","मड़ई (गोंड): नारायणपुर (बस्तर) और मंडला में प्रसिद्ध।","मेघनाद पर्व: गोंड जनजाति (होली के बाद)।"],"pyq":[{"year":2020,"question":"गोल-गधेड़ो उत्सव किस जनजाति से संबंधित है?","strategy":"भगोरिया का हिस्सा = भील।"}],"mnemonic":"Bha-Go-Me (भगोरिया - गोलगधेड़ो - मेघनाद)","impact_emoji":"🥁"}', '{"front":"Tribal Festivals, Dialects & Language","content":"Cultural festivals and linguistic diversity.","points":["Bhagoriya (Bhil): During Holi, 3 stages (Gulalia, Gol-Gadhedo, Ujadia).","Madai (Gond): Famous in Narayanpur (Bastar) & Mandla.","Meghnath Festival: Gond Tribe (After Holi)."],"pyq":[{"year":2020,"question":"Gol-Gadhedo festival is related to which tribe?","strategy":"Part of Bhagoriya = Bhil."}],"mnemonic":"Bha-Go-Me (Bhagoriya - Golgadhedo - Meghnath)","impact_emoji":"🥁"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('9b091f41-128c-49ed-8ede-a0b096156f2c', 'unit_10', 'जनजातीय साहित्य', 'Folk Culture and Literature of Madhya Pradesh', '{"back":"आदिवासी समाज की वो लोककथाएं और गीत जो मौखिक रूप से पीढ़ियों से चले आ रहे हैं।"}', '{"back":"The overall shared folk traditions, songs, and stories that bind the people of MP together."}', 9, 0, NULL, 1769948932, '{"front":"जनजातीय साहित्य","content":"जनजातियों पर लिखित प्रमुख पुस्तकें एवं मौखिक साहित्य।","points":["द बैगा (The Baiga): वेरियर एल्विन (1939)।","द भील्स: टी.वी. नायक।","जगनीक: परमाल रासो (आल्हा-ऊदल की गाथा)।"],"pyq":[{"year":2022,"question":"''द बैगा'' पुस्तक के लेखक कौन हैं?","strategy":"विदेशी मानवशास्त्री = वेरियर एल्विन।"}],"mnemonic":"Baiga by Elwin | Bhils by Naik","impact_emoji":"📚"}', '{"front":"Tribal Literature","content":"Key books written on tribes and oral traditions.","points":["The Baiga: Verrier Elwin (1939).","The Bhils: T.V. Naik.","Jagnik: Parmal Raso (Tales of Alha-Udal)."],"pyq":[{"year":2022,"question":"Who is the author of the book ''The Baiga''?","strategy":"Foreign Anthropologist = Verrier Elwin."}],"mnemonic":"Baiga by Elwin | Bhils by Naik","impact_emoji":"📚"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('2d2b8df3-cb40-477d-a357-f7396aed4855', 'unit_10', 'भारत के स्वतंत्रता आंदोलन में जनजातियों का योगदान', NULL, '{"back":"अंग्रेजों के खिलाफ लड़ाई में आदिवासी क्रांतिकारियों के बलिदान की दास्तान।"}', NULL, 10, 0, NULL, 1769948932, '{"front":"स्वतंत्रता आंदोलन में जनजातियों का योगदान","content":"1857 की क्रांति और जंगल सत्याग्रह में भूमिका।","points":["शंकर शाह - रघुनाथ शाह (गोंड): जबलपुर (गढ़ा मंडला), तोप से उड़ाया गया (1858)।","खाज्या नायक - भीमा नायक (भील): बड़वानी/निमाड़ क्षेत्र (1857)।","जंगल सत्याग्रह (1930): गंजन सिंह कोरकू (घोड़ाडोंगरी - बैतूल)।"],"pyq":[{"year":2023,"question":"भीमा नायक का कार्यक्षेत्र क्या था?","strategy":"निमाड़ का रॉबिनहुड = बड़वानी।"}],"mnemonic":"Shah (Jabalpur) | Nayak (Nimar) | Ganjan (Betul)","impact_emoji":"🇮🇳"}', '{"front":"Contribution to Freedom Movement","content":"Role in 1857 Revolt and Jungle Satyagraha.","points":["Shankar Shah - Raghunath Shah (Gond): Jabalpur, Blown by cannon (1858).","Khajya Nayak - Bhima Nayak (Bhil): Barwani/Nimar region (1857).","Jungle Satyagraha (1930): Ganjan Singh Korku (Ghoradongri - Betul)."],"pyq":[{"year":2023,"question":"What was the area of operation of Bhima Nayak?","strategy":"Robinhood of Nimar = Barwani."}],"mnemonic":"Shah (Jabalpur) | Nayak (Nimar) | Ganjan (Betul)","impact_emoji":"🇮🇳"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('f6efcced-7256-48fa-837d-7aa30e383bb6', 'unit_10', 'मध्यप्रदेश के प्रमुख जनजातीय व्यक्तित्व', NULL, '{"back":"टंट्या मामा, भीमा नायक और गुंडाधुर जैसे नायक जिन्होंने झुकना नहीं सीखा।"}', NULL, 11, 0, NULL, 1769948932, '{"front":"मध्यप्रदेश के प्रमुख जनजातीय व्यक्तित्व","content":"इतिहास निर्माता और पद्म पुरस्कार विजेता।","points":["टंट्या भील: ''इंडियन रॉबिनहुड'', समाधि पातालपानी (महू)।","भूरी बाई: पिथौरा चित्रकार, पद्मश्री (2021)।","रानी दुर्गावती: गोंडवाना की शासिका, अकबर से युद्ध (नरई नाला)।"],"pyq":[{"year":2022,"question":"भूरी बाई किस जिले से संबंधित हैं?","strategy":"झाबुआ (कला केंद्र)।"}],"mnemonic":"Tantiya (Mhow) | Bhuri (Jhabua) | Durgavati (Jabalpur)","impact_emoji":"🌟"}', '{"front":"Tribal Personalities of MP","content":"History makers and Padma awardees.","points":["Tantiya Bhil: ''Indian Robinhood'', Memorial at Patalpani (Mhow).","Bhuri Bai: Pithora Artist, Padma Shri (2021).","Rani Durgavati: Ruler of Gondwana, Fought Akbar (Narai Nala)."],"pyq":[{"year":2022,"question":"Bhuri Bai belongs to which district?","strategy":"Jhabua (Art Hub)."}],"mnemonic":"Tantiya (Mhow) | Bhuri (Jhabua) | Durgavati (Jabalpur)","impact_emoji":"🌟"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('103b88ea-9bc7-429e-9da1-bd46104da436', 'unit_10', 'जनजातियों से संबंधित प्रमुख संस्थान, संग्रहालय, प्रकाशन', NULL, '{"back":"आदिवासी संस्कृति को सहेजने वाले म्यूजियम और उनसे जुड़ी किताबें।"}', NULL, 12, 0, NULL, 1769948932, '{"front":"संस्थान, संग्रहालय और प्रकाशन","content":"जनजातीय शोध और संरक्षण केंद्र।","points":["बादल भोई राज्य आदिवासी संग्रहालय: छिंदवाड़ा (1954, सबसे पुराना)।","म.प्र. जनजातीय संग्रहालय: भोपाल (2013)।","आदिवर्त संग्रहालय: खजुराहो (जनजातीय एवं लोक कला)।"],"pyq":[{"year":2023,"question":"बादल भोई आदिवासी संग्रहालय कहाँ स्थित है?","strategy":"नाम याद रखें: बादल - छिंदवाड़ा।"}],"mnemonic":"Badal (Chhindwara) - State (Bhopal) - Aadivart (Khajuraho)","impact_emoji":"🏛️"}', '{"front":"Tribal Institutes, Museums & Publications","content":"Centers for tribal research and preservation.","points":["Badal Bhoi State Tribal Museum: Chhindwara (1954, Oldest).","MP Tribal Museum: Bhopal (2013).","Aadivart Museum: Khajuraho (Tribal & Folk Art)."],"pyq":[{"year":2023,"question":"Where is Badal Bhoi Tribal Museum located?","strategy":"Remember Name: Badal - Chhindwara."}],"mnemonic":"Badal (Chhindwara) - State (Bhopal) - Aadivart (Khajuraho)","impact_emoji":"🏛️"}', 0, 1, 'mppsc');
INSERT INTO "syllabus_topics" ("id", "unit_id", "title", "title_en", "content", "content_en", "order", "is_free", "img_url", "created_at", "ai_content", "ai_content_en", "is_lite_access", "is_pro_access", "exam_type") VALUES ('30f659e3-dd2e-486b-9374-53f5b8bfc6ac', 'unit_10', 'मध्यप्रदेश की लोक संस्कृति एवं लोक साहित्य', NULL, '{"back":"पूरे राज्य की साझा संस्कृति, लोकगीत और वो कहानियाँ जो हमें एक सूत्र में पिरोती हैं।"}', NULL, 13, 0, NULL, 1769948932, '{"front":"मध्यप्रदेश की लोक संस्कृति एवं लोक साहित्य","content":"क्षेत्रीय गायन, नृत्य और नाट्य।","points":["निमाड़: कलगी-तुर्रा (गायन), गणगौर (नृत्य), संत सिंगाजी।","बुंदेलखंड: राई (राजकीय नृत्य), आल्हा गायन (वर्षा ऋतु)।","मालवा: माच (राजकीय नाट्य), भरथरी गायन।"],"pyq":[{"year":2021,"question":"कलगी-तुर्रा किस अंचल का लोकगायन है?","strategy":"प्रतिस्पर्धात्मक गायन = निमाड़।"}],"mnemonic":"Rai (Bundel) - Macha (Malwa) - Kalgi (Nimar)","impact_emoji":"🎭"}', '{"front":"Folk Culture & Literature of MP","content":"Regional Singing, Dance, and Drama.","points":["Nimar: Kalgi-Turra (Singing), Gangaur (Dance), Sant Singaji.","Bundelkhand: Rai (State Dance), Alha Singing (Monsoon).","Malwa: Macha (State Drama), Bharthari Singing."],"pyq":[{"year":2021,"question":"Kalgi-Turra belongs to which folk region?","strategy":"Competitive Singing = Nimar."}],"mnemonic":"Rai (Bundel) - Macha (Malwa) - Kalgi (Nimar)","impact_emoji":"🎭"}', 0, 1, 'mppsc');
